INSERT INTO heb_vpl VALUES ("GN43_12","002_43_12","GEN","43","12","12","וכסף משנה קחו בידכם ואת הכסף המושב בפי אמתחתיכם תשיבו בידכם אולי משגה הוא׃ ");
