INSERT INTO heb_vpl VALUES ("EX32_2","003_32_2","EXO","32","2","2","ויאמר אלהם אהרן פרקו נזמי הזהב אשר באזני נשיכם בניכם ובנתיכם והביאו אלי׃ ");
