INSERT INTO heb_vpl VALUES ("LV19_20","004_19_20","LEV","19","20","20","ואיש כי ישכב את אשה שכבת זרע והוא שפחה נחרפת לאיש והפדה לא נפדתה או חפשה לא נתן לה בקרת תהיה לא יומתו כי לא חפשה׃ ");
