INSERT INTO heb_vpl VALUES ("NU6_25","005_6_25","NUM","6","25","25","יאר יהוה פניו אליך ויחנך׃ ");
INSERT INTO heb_vpl VALUES ("NU6_26","005_6_26","NUM","6","26","26","ישא יהוה פניו אליך וישם לך שלום׃ ");
