INSERT INTO heb_vpl VALUES ("NU9_3","005_9_3","NUM","9","3","3","בארבעה עשר יום בחדש הזה בין הערבים תעשו אתו במועדו ככל חקתיו וככל משפטיו תעשו אתו׃ ");
