INSERT INTO heb_vpl VALUES ("NU20_6","005_20_6","NUM","20","6","6","ויבא משה ואהרן מפני הקהל אל פתח אהל מועד ויפלו על פניהם וירא כבוד יהוה אליהם׃ ");
