INSERT INTO heb_vpl VALUES ("DT1_4","006_1_4","DEU","1","4","4","אחרי הכתו את סיחן מלך האמרי אשר יושב בחשבון ואת עוג מלך הבשן אשר יושב בעשתרת באדרעי׃ ");
