INSERT INTO heb_vpl VALUES ("JS10_33","007_10_33","JOS","10","33","33","אז עלה הרם מלך גזר לעזר את לכיש ויכהו יהושע ואת עמו עד בלתי השאיר לו שריד׃ ");
