INSERT INTO heb_vpl VALUES ("JS13_3","007_13_3","JOS","13","3","3","מן השיחור אשר על פני מצרים ועד גבול עקרון צפונה לכנעני תחשב חמשת סרני פלשתים העזתי והאשדודי האשקלוני הגתי והעקרוני והעוים׃ ");
