INSERT INTO heb_vpl VALUES ("JS13_6","007_13_6","JOS","13","6","6","כל ישבי ההר מן הלבנון עד משרפת מים כל צידנים אנכי אורישם מפני בני ישראל רק הפלה לישראל בנחלה כאשר צויתיך׃ ");
