INSERT INTO heb_vpl VALUES ("JS21_27","007_21_27","JOS","21","27","27","ולבני גרשון ממשפחת הלוים מחצי מטה מנשה את עיר מקלט הרצח את גלון בבשן ואת מגרשה ואת בעשתרה ואת מגרשה ערים שתים׃ ");
INSERT INTO heb_vpl VALUES ("JS21_28","007_21_28","JOS","21","28","28","וממטה יששכר את קשיון ואת מגרשה את דברת ואת מגרשה׃ ");
INSERT INTO heb_vpl VALUES ("JS21_29","007_21_29","JOS","21","29","29","את ירמות ואת מגרשה את עין גנים ואת מגרשה ערים ארבע׃ ");
INSERT INTO heb_vpl VALUES ("JS21_30","007_21_30","JOS","21","30","30","וממטה אשר את משאל ואת מגרשה את עבדון ואת מגרשה׃ ");
INSERT INTO heb_vpl VALUES ("JS21_31","007_21_31","JOS","21","31","31","את חלקת ואת מגרשה ואת רחב ואת מגרשה ערים ארבע׃ ");
INSERT INTO heb_vpl VALUES ("JS21_32","007_21_32","JOS","21","32","32","וממטה נפתלי את עיר מקלט הרצח את קדש בגליל ואת מגרשה ואת חמת דאר ואת מגרשה ואת קרתן ואת מגרשה ערים שלש׃ ");
INSERT INTO heb_vpl VALUES ("JS21_33","007_21_33","JOS","21","33","33","כל ערי הגרשני למשפחתם שלש עשרה עיר ומגרשיהן׃ ");
INSERT INTO heb_vpl VALUES ("JS21_34","007_21_34","JOS","21","34","34","ולמשפחות בני מררי הלוים הנותרים מאת מטה זבולן את יקנעם ואת מגרשה את קרתה ואת מגרשה׃ ");
INSERT INTO heb_vpl VALUES ("JS21_35","007_21_35","JOS","21","35","35","את דמנה ואת מגרשה את נהלל ואת מגרשה ערים ארבע׃ ");
INSERT INTO heb_vpl VALUES ("JS21_36","007_21_36","JOS","21","36","36","וממטה ראובן את בצר ואת מגרשה ואת יהצה ואת מגרשה׃ ");
INSERT INTO heb_vpl VALUES ("JS21_37","007_21_37","JOS","21","37","37","את קדמות ואת מגרשה ואת מיפעת ואת מגרשה ערים ארבע׃ ");
INSERT INTO heb_vpl VALUES ("JS21_38","007_21_38","JOS","21","38","38","וממטה גד את עיר מקלט הרצח את רמת בגלעד ואת מגרשה ואת מחנים ואת מגרשה׃ ");
INSERT INTO heb_vpl VALUES ("JS21_39","007_21_39","JOS","21","39","39","את חשבון ואת מגרשה את יעזר ואת מגרשה כל ערים ארבע׃ ");
INSERT INTO heb_vpl VALUES ("JS21_40","007_21_40","JOS","21","40","40","כל הערים לבני מררי למשפחתם הנותרים ממשפחות הלוים ויהי גורלם ערים שתים עשרה׃ ");
INSERT INTO heb_vpl VALUES ("JS21_41","007_21_41","JOS","21","41","41","כל ערי הלוים בתוך אחזת בני ישראל ערים ארבעים ושמנה ומגרשיהן׃ ");
INSERT INTO heb_vpl VALUES ("JS21_42","007_21_42","JOS","21","42","42","תהיינה הערים האלה עיר עיר ומגרשיה סביבתיה כן לכל הערים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JS21_43","007_21_43","JOS","21","43","43","ויתן יהוה לישראל את כל הארץ אשר נשבע לתת לאבותם וירשוה וישבו בה׃ ");
INSERT INTO heb_vpl VALUES ("JS21_44","007_21_44","JOS","21","44","44","וינח יהוה להם מסביב ככל אשר נשבע לאבותם ולא עמד איש בפניהם מכל איביהם את כל איביהם נתן יהוה בידם׃ ");
INSERT INTO heb_vpl VALUES ("JS21_45","007_21_45","JOS","21","45","45","לא נפל דבר מכל הדבר הטוב אשר דבר יהוה אל בית ישראל הכל בא׃ ");
INSERT INTO heb_vpl VALUES ("JS22_1","007_22_1","JOS","22","1","1","אז יקרא יהושע לראובני ולגדי ולחצי מטה מנשה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_2","007_22_2","JOS","22","2","2","ויאמר אליהם אתם שמרתם את כל אשר צוה אתכם משה עבד יהוה ותשמעו בקולי לכל אשר צויתי אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JS22_3","007_22_3","JOS","22","3","3","לא עזבתם את אחיכם זה ימים רבים עד היום הזה ושמרתם את משמרת מצות יהוה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("JS22_4","007_22_4","JOS","22","4","4","ועתה הניח יהוה אלהיכם לאחיכם כאשר דבר להם ועתה פנו ולכו לכם לאהליכם אל ארץ אחזתכם אשר נתן לכם משה עבד יהוה בעבר הירדן׃ ");
INSERT INTO heb_vpl VALUES ("JS22_5","007_22_5","JOS","22","5","5","רק שמרו מאד לעשות את המצוה ואת התורה אשר צוה אתכם משה עבד יהוה לאהבה את יהוה אלהיכם וללכת בכל דרכיו ולשמר מצותיו ולדבקה בו ולעבדו בכל לבבכם ובכל נפשכם׃ ");
INSERT INTO heb_vpl VALUES ("JS22_6","007_22_6","JOS","22","6","6","ויברכם יהושע וישלחם וילכו אל אהליהם׃ ");
INSERT INTO heb_vpl VALUES ("JS22_7","007_22_7","JOS","22","7","7","ולחצי שבט המנשה נתן משה בבשן ולחציו נתן יהושע עם אחיהם מעבר הירדן ימה וגם כי שלחם יהושע אל אהליהם ויברכם׃ ");
INSERT INTO heb_vpl VALUES ("JS22_8","007_22_8","JOS","22","8","8","ויאמר אליהם לאמר בנכסים רבים שובו אל אהליכם ובמקנה רב מאד בכסף ובזהב ובנחשת ובברזל ובשלמות הרבה מאד חלקו שלל איביכם עם אחיכם׃ ");
INSERT INTO heb_vpl VALUES ("JS22_9","007_22_9","JOS","22","9","9","וישבו וילכו בני ראובן ובני גד וחצי שבט המנשה מאת בני ישראל משלה אשר בארץ כנען ללכת אל ארץ הגלעד אל ארץ אחזתם אשר נאחזו בה על פי יהוה ביד משה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_10","007_22_10","JOS","22","10","10","ויבאו אל גלילות הירדן אשר בארץ כנען ויבנו בני ראובן ובני גד וחצי שבט המנשה שם מזבח על הירדן מזבח גדול למראה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_11","007_22_11","JOS","22","11","11","וישמעו בני ישראל לאמר הנה בנו בני ראובן ובני גד וחצי שבט המנשה את המזבח אל מול ארץ כנען אל גלילות הירדן אל עבר בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JS22_12","007_22_12","JOS","22","12","12","וישמעו בני ישראל ויקהלו כל עדת בני ישראל שלה לעלות עליהם לצבא׃ ");
INSERT INTO heb_vpl VALUES ("JS22_13","007_22_13","JOS","22","13","13","וישלחו בני ישראל אל בני ראובן ואל בני גד ואל חצי שבט מנשה אל ארץ הגלעד את פינחס בן אלעזר הכהן׃ ");
INSERT INTO heb_vpl VALUES ("JS22_14","007_22_14","JOS","22","14","14","ועשרה נשאים עמו נשיא אחד נשיא אחד לבית אב לכל מטות ישראל ואיש ראש בית אבותם המה לאלפי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JS22_15","007_22_15","JOS","22","15","15","ויבאו אל בני ראובן ואל בני גד ואל חצי שבט מנשה אל ארץ הגלעד וידברו אתם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JS22_16","007_22_16","JOS","22","16","16","כה אמרו כל עדת יהוה מה המעל הזה אשר מעלתם באלהי ישראל לשוב היום מאחרי יהוה בבנותכם לכם מזבח למרדכם היום ביהוה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_17","007_22_17","JOS","22","17","17","המעט לנו את עון פעור אשר לא הטהרנו ממנו עד היום הזה ויהי הנגף בעדת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_18","007_22_18","JOS","22","18","18","ואתם תשבו היום מאחרי יהוה והיה אתם תמרדו היום ביהוה ומחר אל כל עדת ישראל יקצף׃ ");
INSERT INTO heb_vpl VALUES ("JS22_19","007_22_19","JOS","22","19","19","ואך אם טמאה ארץ אחזתכם עברו לכם אל ארץ אחזת יהוה אשר שכן שם משכן יהוה והאחזו בתוכנו וביהוה אל תמרדו ואתנו אל תמרדו בבנתכם לכם מזבח מבלעדי מזבח יהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JS22_20","007_22_20","JOS","22","20","20","הלוא עכן בן זרח מעל מעל בחרם ועל כל עדת ישראל היה קצף והוא איש אחד לא גוע בעונו׃ ");
INSERT INTO heb_vpl VALUES ("JS22_21","007_22_21","JOS","22","21","21","ויענו בני ראובן ובני גד וחצי שבט המנשה וידברו את ראשי אלפי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JS22_22","007_22_22","JOS","22","22","22","אל אלהים יהוה אל אלהים יהוה הוא ידע וישראל הוא ידע אם במרד ואם במעל ביהוה אל תושיענו היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_23","007_22_23","JOS","22","23","23","לבנות לנו מזבח לשוב מאחרי יהוה ואם להעלות עליו עולה ומנחה ואם לעשות עליו זבחי שלמים יהוה הוא יבקש׃ ");
INSERT INTO heb_vpl VALUES ("JS22_24","007_22_24","JOS","22","24","24","ואם לא מדאגה מדבר עשינו את זאת לאמר מחר יאמרו בניכם לבנינו לאמר מה לכם וליהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JS22_25","007_22_25","JOS","22","25","25","וגבול נתן יהוה ביננו וביניכם בני ראובן ובני גד את הירדן אין לכם חלק ביהוה והשביתו בניכם את בנינו לבלתי ירא את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_26","007_22_26","JOS","22","26","26","ונאמר נעשה נא לנו לבנות את המזבח לא לעולה ולא לזבח׃ ");
INSERT INTO heb_vpl VALUES ("JS22_27","007_22_27","JOS","22","27","27","כי עד הוא בינינו וביניכם ובין דרותינו אחרינו לעבד את עבדת יהוה לפניו בעלותינו ובזבחינו ובשלמינו ולא יאמרו בניכם מחר לבנינו אין לכם חלק ביהוה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_28","007_22_28","JOS","22","28","28","ונאמר והיה כי יאמרו אלינו ואל דרתינו מחר ואמרנו ראו את תבנית מזבח יהוה אשר עשו אבותינו לא לעולה ולא לזבח כי עד הוא בינינו וביניכם׃ ");
INSERT INTO heb_vpl VALUES ("JS22_29","007_22_29","JOS","22","29","29","חלילה לנו ממנו למרד ביהוה ולשוב היום מאחרי יהוה לבנות מזבח לעלה למנחה ולזבח מלבד מזבח יהוה אלהינו אשר לפני משכנו׃ ");
INSERT INTO heb_vpl VALUES ("JS22_30","007_22_30","JOS","22","30","30","וישמע פינחס הכהן ונשיאי העדה וראשי אלפי ישראל אשר אתו את הדברים אשר דברו בני ראובן ובני גד ובני מנשה וייטב בעיניהם׃ ");
INSERT INTO heb_vpl VALUES ("JS22_31","007_22_31","JOS","22","31","31","ויאמר פינחס בן אלעזר הכהן אל בני ראובן ואל בני גד ואל בני מנשה היום ידענו כי בתוכנו יהוה אשר לא מעלתם ביהוה המעל הזה אז הצלתם את בני ישראל מיד יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_32","007_22_32","JOS","22","32","32","וישב פינחס בן אלעזר הכהן והנשיאים מאת בני ראובן ומאת בני גד מארץ הגלעד אל ארץ כנען אל בני ישראל וישבו אותם דבר׃ ");
INSERT INTO heb_vpl VALUES ("JS22_33","007_22_33","JOS","22","33","33","וייטב הדבר בעיני בני ישראל ויברכו אלהים בני ישראל ולא אמרו לעלות עליהם לצבא לשחת את הארץ אשר בני ראובן ובני גד ישבים בה׃ ");
INSERT INTO heb_vpl VALUES ("JS22_34","007_22_34","JOS","22","34","34","ויקראו בני ראובן ובני גד למזבח כי עד הוא בינתינו כי יהוה האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JS23_1","007_23_1","JOS","23","1","1","ויהי מימים רבים אחרי אשר הניח יהוה לישראל מכל איביהם מסביב ויהושע זקן בא בימים׃ ");
INSERT INTO heb_vpl VALUES ("JS23_2","007_23_2","JOS","23","2","2","ויקרא יהושע לכל ישראל לזקניו ולראשיו ולשפטיו ולשטריו ויאמר אלהם אני זקנתי באתי בימים׃ ");
INSERT INTO heb_vpl VALUES ("JS23_3","007_23_3","JOS","23","3","3","ואתם ראיתם את כל אשר עשה יהוה אלהיכם לכל הגוים האלה מפניכם כי יהוה אלהיכם הוא הנלחם לכם׃ ");
INSERT INTO heb_vpl VALUES ("JS23_4","007_23_4","JOS","23","4","4","ראו הפלתי לכם את הגוים הנשארים האלה בנחלה לשבטיכם מן הירדן וכל הגוים אשר הכרתי והים הגדול מבוא השמש׃ ");
INSERT INTO heb_vpl VALUES ("JS23_5","007_23_5","JOS","23","5","5","ויהוה אלהיכם הוא יהדפם מפניכם והוריש אתם מלפניכם וירשתם את ארצם כאשר דבר יהוה אלהיכם לכם׃ ");
INSERT INTO heb_vpl VALUES ("JS23_6","007_23_6","JOS","23","6","6","וחזקתם מאד לשמר ולעשות את כל הכתוב בספר תורת משה לבלתי סור ממנו ימין ושמאול׃ ");
INSERT INTO heb_vpl VALUES ("JS23_7","007_23_7","JOS","23","7","7","לבלתי בוא בגוים האלה הנשארים האלה אתכם ובשם אלהיהם לא תזכירו ולא תשביעו ולא תעבדום ולא תשתחוו להם׃ ");
INSERT INTO heb_vpl VALUES ("JS23_8","007_23_8","JOS","23","8","8","כי אם ביהוה אלהיכם תדבקו כאשר עשיתם עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JS23_9","007_23_9","JOS","23","9","9","ויורש יהוה מפניכם גוים גדלים ועצומים ואתם לא עמד איש בפניכם עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JS23_10","007_23_10","JOS","23","10","10","איש אחד מכם ירדף אלף כי יהוה אלהיכם הוא הנלחם לכם כאשר דבר לכם׃ ");
INSERT INTO heb_vpl VALUES ("JS23_11","007_23_11","JOS","23","11","11","ונשמרתם מאד לנפשתיכם לאהבה את יהוה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("JS23_12","007_23_12","JOS","23","12","12","כי אם שוב תשובו ודבקתם ביתר הגוים האלה הנשארים האלה אתכם והתחתנתם בהם ובאתם בהם והם בכם׃ ");
INSERT INTO heb_vpl VALUES ("JS23_13","007_23_13","JOS","23","13","13","ידוע תדעו כי לא יוסיף יהוה אלהיכם להוריש את הגוים האלה מלפניכם והיו לכם לפח ולמוקש ולשטט בצדיכם ולצננים בעיניכם עד אבדכם מעל האדמה הטובה הזאת אשר נתן לכם יהוה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("JS23_14","007_23_14","JOS","23","14","14","והנה אנכי הולך היום בדרך כל הארץ וידעתם בכל לבבכם ובכל נפשכם כי לא נפל דבר אחד מכל הדברים הטובים אשר דבר יהוה אלהיכם עליכם הכל באו לכם לא נפל ממנו דבר אחד׃ ");
INSERT INTO heb_vpl VALUES ("JS23_15","007_23_15","JOS","23","15","15","והיה כאשר בא עליכם כל הדבר הטוב אשר דבר יהוה אלהיכם אליכם כן יביא יהוה עליכם את כל הדבר הרע עד השמידו אותכם מעל האדמה הטובה הזאת אשר נתן לכם יהוה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("JS23_16","007_23_16","JOS","23","16","16","בעברכם את ברית יהוה אלהיכם אשר צוה אתכם והלכתם ועבדתם אלהים אחרים והשתחויתם להם וחרה אף יהוה בכם ואבדתם מהרה מעל הארץ הטובה אשר נתן לכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_1","007_24_1","JOS","24","1","1","ויאסף יהושע את כל שבטי ישראל שכמה ויקרא לזקני ישראל ולראשיו ולשפטיו ולשטריו ויתיצבו לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JS24_2","007_24_2","JOS","24","2","2","ויאמר יהושע אל כל העם כה אמר יהוה אלהי ישראל בעבר הנהר ישבו אבותיכם מעולם תרח אבי אברהם ואבי נחור ויעבדו אלהים אחרים׃ ");
INSERT INTO heb_vpl VALUES ("JS24_3","007_24_3","JOS","24","3","3","ואקח את אביכם את אברהם מעבר הנהר ואולך אותו בכל ארץ כנען וארב את זרעו ואתן לו את יצחק׃ ");
INSERT INTO heb_vpl VALUES ("JS24_4","007_24_4","JOS","24","4","4","ואתן ליצחק את יעקב ואת עשו ואתן לעשו את הר שעיר לרשת אותו ויעקב ובניו ירדו מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JS24_5","007_24_5","JOS","24","5","5","ואשלח את משה ואת אהרן ואגף את מצרים כאשר עשיתי בקרבו ואחר הוצאתי אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_6","007_24_6","JOS","24","6","6","ואוציא את אבותיכם ממצרים ותבאו הימה וירדפו מצרים אחרי אבותיכם ברכב ובפרשים ים סוף׃ ");
INSERT INTO heb_vpl VALUES ("JS24_7","007_24_7","JOS","24","7","7","ויצעקו אל יהוה וישם מאפל ביניכם ובין המצרים ויבא עליו את הים ויכסהו ותראינה עיניכם את אשר עשיתי במצרים ותשבו במדבר ימים רבים׃ ");
INSERT INTO heb_vpl VALUES ("JS24_8","007_24_8","JOS","24","8","8","ואביאה אתכם אל ארץ האמרי היושב בעבר הירדן וילחמו אתכם ואתן אותם בידכם ותירשו את ארצם ואשמידם מפניכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_9","007_24_9","JOS","24","9","9","ויקם בלק בן צפור מלך מואב וילחם בישראל וישלח ויקרא לבלעם בן בעור לקלל אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_10","007_24_10","JOS","24","10","10","ולא אביתי לשמע לבלעם ויברך ברוך אתכם ואצל אתכם מידו׃ ");
INSERT INTO heb_vpl VALUES ("JS24_11","007_24_11","JOS","24","11","11","ותעברו את הירדן ותבאו אל יריחו וילחמו בכם בעלי יריחו האמרי והפרזי והכנעני והחתי והגרגשי החוי והיבוסי ואתן אותם בידכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_12","007_24_12","JOS","24","12","12","ואשלח לפניכם את הצרעה ותגרש אותם מפניכם שני מלכי האמרי לא בחרבך ולא בקשתך׃ ");
INSERT INTO heb_vpl VALUES ("JS24_13","007_24_13","JOS","24","13","13","ואתן לכם ארץ אשר לא יגעת בה וערים אשר לא בניתם ותשבו בהם כרמים וזיתים אשר לא נטעתם אתם אכלים׃ ");
INSERT INTO heb_vpl VALUES ("JS24_14","007_24_14","JOS","24","14","14","ועתה יראו את יהוה ועבדו אתו בתמים ובאמת והסירו את אלהים אשר עבדו אבותיכם בעבר הנהר ובמצרים ועבדו את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JS24_15","007_24_15","JOS","24","15","15","ואם רע בעיניכם לעבד את יהוה בחרו לכם היום את מי תעבדון אם את אלהים אשר עבדו אבותיכם אשר בעבר הנהר ואם את אלהי האמרי אשר אתם ישבים בארצם ואנכי וביתי נעבד את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JS24_16","007_24_16","JOS","24","16","16","ויען העם ויאמר חלילה לנו מעזב את יהוה לעבד אלהים אחרים׃ ");
INSERT INTO heb_vpl VALUES ("JS24_17","007_24_17","JOS","24","17","17","כי יהוה אלהינו הוא המעלה אתנו ואת אבותינו מארץ מצרים מבית עבדים ואשר עשה לעינינו את האתות הגדלות האלה וישמרנו בכל הדרך אשר הלכנו בה ובכל העמים אשר עברנו בקרבם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_18","007_24_18","JOS","24","18","18","ויגרש יהוה את כל העמים ואת האמרי ישב הארץ מפנינו גם אנחנו נעבד את יהוה כי הוא אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JS24_19","007_24_19","JOS","24","19","19","ויאמר יהושע אל העם לא תוכלו לעבד את יהוה כי אלהים קדשים הוא אל קנוא הוא לא ישא לפשעכם ולחטאותיכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_20","007_24_20","JOS","24","20","20","כי תעזבו את יהוה ועבדתם אלהי נכר ושב והרע לכם וכלה אתכם אחרי אשר היטיב לכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_21","007_24_21","JOS","24","21","21","ויאמר העם אל יהושע לא כי את יהוה נעבד׃ ");
INSERT INTO heb_vpl VALUES ("JS24_22","007_24_22","JOS","24","22","22","ויאמר יהושע אל העם עדים אתם בכם כי אתם בחרתם לכם את יהוה לעבד אותו ויאמרו עדים׃ ");
INSERT INTO heb_vpl VALUES ("JS24_23","007_24_23","JOS","24","23","23","ועתה הסירו את אלהי הנכר אשר בקרבכם והטו את לבבכם אל יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JS24_24","007_24_24","JOS","24","24","24","ויאמרו העם אל יהושע את יהוה אלהינו נעבד ובקולו נשמע׃ ");
INSERT INTO heb_vpl VALUES ("JS24_25","007_24_25","JOS","24","25","25","ויכרת יהושע ברית לעם ביום ההוא וישם לו חק ומשפט בשכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_26","007_24_26","JOS","24","26","26","ויכתב יהושע את הדברים האלה בספר תורת אלהים ויקח אבן גדולה ויקימה שם תחת האלה אשר במקדש יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JS24_27","007_24_27","JOS","24","27","27","ויאמר יהושע אל כל העם הנה האבן הזאת תהיה בנו לעדה כי היא שמעה את כל אמרי יהוה אשר דבר עמנו והיתה בכם לעדה פן תכחשון באלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("JS24_28","007_24_28","JOS","24","28","28","וישלח יהושע את העם איש לנחלתו׃ ");
INSERT INTO heb_vpl VALUES ("JS24_29","007_24_29","JOS","24","29","29","ויהי אחרי הדברים האלה וימת יהושע בן נון עבד יהוה בן מאה ועשר שנים׃ ");
INSERT INTO heb_vpl VALUES ("JS24_30","007_24_30","JOS","24","30","30","ויקברו אתו בגבול נחלתו בתמנת סרח אשר בהר אפרים מצפון להר געש׃ ");
INSERT INTO heb_vpl VALUES ("JS24_31","007_24_31","JOS","24","31","31","ויעבד ישראל את יהוה כל ימי יהושע וכל ימי הזקנים אשר האריכו ימים אחרי יהושע ואשר ידעו את כל מעשה יהוה אשר עשה לישראל׃ ");
INSERT INTO heb_vpl VALUES ("JS24_32","007_24_32","JOS","24","32","32","ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם בחלקת השדה אשר קנה יעקב מאת בני חמור אבי שכם במאה קשיטה ויהיו לבני יוסף לנחלה׃ ");
INSERT INTO heb_vpl VALUES ("JS24_33","007_24_33","JOS","24","33","33","ואלעזר בן אהרן מת ויקברו אתו בגבעת פינחס בנו אשר נתן לו בהר אפרים׃ ");
INSERT INTO heb_vpl VALUES ("JG1_1","008_1_1","JDG","1","1","1","ויהי אחרי מות יהושע וישאלו בני ישראל ביהוה לאמר מי יעלה לנו אל הכנעני בתחלה להלחם בו׃ ");
INSERT INTO heb_vpl VALUES ("JG1_2","008_1_2","JDG","1","2","2","ויאמר יהוה יהודה יעלה הנה נתתי את הארץ בידו׃ ");
INSERT INTO heb_vpl VALUES ("JG1_3","008_1_3","JDG","1","3","3","ויאמר יהודה לשמעון אחיו עלה אתי בגורלי ונלחמה בכנעני והלכתי גם אני אתך בגורלך וילך אתו שמעון׃ ");
INSERT INTO heb_vpl VALUES ("JG1_4","008_1_4","JDG","1","4","4","ויעל יהודה ויתן יהוה את הכנעני והפרזי בידם ויכום בבזק עשרת אלפים איש׃ ");
INSERT INTO heb_vpl VALUES ("JG1_5","008_1_5","JDG","1","5","5","וימצאו את אדני בזק בבזק וילחמו בו ויכו את הכנעני ואת הפרזי׃ ");
INSERT INTO heb_vpl VALUES ("JG1_6","008_1_6","JDG","1","6","6","וינס אדני בזק וירדפו אחריו ויאחזו אתו ויקצצו את בהנות ידיו ורגליו׃ ");
INSERT INTO heb_vpl VALUES ("JG1_7","008_1_7","JDG","1","7","7","ויאמר אדני בזק שבעים מלכים בהנות ידיהם ורגליהם מקצצים היו מלקטים תחת שלחני כאשר עשיתי כן שלם לי אלהים ויביאהו ירושלם וימת שם׃ ");
INSERT INTO heb_vpl VALUES ("JG1_8","008_1_8","JDG","1","8","8","וילחמו בני יהודה בירושלם וילכדו אותה ויכוה לפי חרב ואת העיר שלחו באש׃ ");
INSERT INTO heb_vpl VALUES ("JG1_9","008_1_9","JDG","1","9","9","ואחר ירדו בני יהודה להלחם בכנעני יושב ההר והנגב והשפלה׃ ");
INSERT INTO heb_vpl VALUES ("JG1_10","008_1_10","JDG","1","10","10","וילך יהודה אל הכנעני היושב בחברון ושם חברון לפנים קרית ארבע ויכו את ששי ואת אחימן ואת תלמי׃ ");
INSERT INTO heb_vpl VALUES ("JG1_11","008_1_11","JDG","1","11","11","וילך משם אל יושבי דביר ושם דביר לפנים קרית ספר׃ ");
INSERT INTO heb_vpl VALUES ("JG1_12","008_1_12","JDG","1","12","12","ויאמר כלב אשר יכה את קרית ספר ולכדה ונתתי לו את עכסה בתי לאשה׃ ");
INSERT INTO heb_vpl VALUES ("JG1_13","008_1_13","JDG","1","13","13","וילכדה עתניאל בן קנז אחי כלב הקטן ממנו ויתן לו את עכסה בתו לאשה׃ ");
INSERT INTO heb_vpl VALUES ("JG1_14","008_1_14","JDG","1","14","14","ויהי בבואה ותסיתהו לשאול מאת אביה השדה ותצנח מעל החמור ויאמר לה כלב מה לך׃ ");
INSERT INTO heb_vpl VALUES ("JG1_15","008_1_15","JDG","1","15","15","ותאמר לו הבה לי ברכה כי ארץ הנגב נתתני ונתתה לי גלת מים ויתן לה כלב את גלת עלית ואת גלת תחתית׃ ");
INSERT INTO heb_vpl VALUES ("JG1_16","008_1_16","JDG","1","16","16","ובני קיני חתן משה עלו מעיר התמרים את בני יהודה מדבר יהודה אשר בנגב ערד וילך וישב את העם׃ ");
INSERT INTO heb_vpl VALUES ("JG1_17","008_1_17","JDG","1","17","17","וילך יהודה את שמעון אחיו ויכו את הכנעני יושב צפת ויחרימו אותה ויקרא את שם העיר חרמה׃ ");
INSERT INTO heb_vpl VALUES ("JG1_18","008_1_18","JDG","1","18","18","וילכד יהודה את עזה ואת גבולה ואת אשקלון ואת גבולה ואת עקרון ואת גבולה׃ ");
INSERT INTO heb_vpl VALUES ("JG1_19","008_1_19","JDG","1","19","19","ויהי יהוה את יהודה וירש את ההר כי לא להוריש את ישבי העמק כי רכב ברזל להם׃ ");
INSERT INTO heb_vpl VALUES ("JG1_20","008_1_20","JDG","1","20","20","ויתנו לכלב את חברון כאשר דבר משה ויורש משם את שלשה בני הענק׃ ");
INSERT INTO heb_vpl VALUES ("JG1_21","008_1_21","JDG","1","21","21","ואת היבוסי ישב ירושלם לא הורישו בני בנימן וישב היבוסי את בני בנימן בירושלם עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JG1_22","008_1_22","JDG","1","22","22","ויעלו בית יוסף גם הם בית אל ויהוה עמם׃ ");
INSERT INTO heb_vpl VALUES ("JG1_23","008_1_23","JDG","1","23","23","ויתירו בית יוסף בבית אל ושם העיר לפנים לוז׃ ");
INSERT INTO heb_vpl VALUES ("JG1_24","008_1_24","JDG","1","24","24","ויראו השמרים איש יוצא מן העיר ויאמרו לו הראנו נא את מבוא העיר ועשינו עמך חסד׃ ");
INSERT INTO heb_vpl VALUES ("JG1_25","008_1_25","JDG","1","25","25","ויראם את מבוא העיר ויכו את העיר לפי חרב ואת האיש ואת כל משפחתו שלחו׃ ");
INSERT INTO heb_vpl VALUES ("JG1_26","008_1_26","JDG","1","26","26","וילך האיש ארץ החתים ויבן עיר ויקרא שמה לוז הוא שמה עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JG1_27","008_1_27","JDG","1","27","27","ולא הוריש מנשה את בית שאן ואת בנותיה ואת תענך ואת בנתיה ואת ישב דור ואת בנותיה ואת יושבי יבלעם ואת בנתיה ואת יושבי מגדו ואת בנותיה ויואל הכנעני לשבת בארץ הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JG1_28","008_1_28","JDG","1","28","28","ויהי כי חזק ישראל וישם את הכנעני למס והוריש לא הורישו׃ ");
INSERT INTO heb_vpl VALUES ("JG1_29","008_1_29","JDG","1","29","29","ואפרים לא הוריש את הכנעני היושב בגזר וישב הכנעני בקרבו בגזר׃ ");
INSERT INTO heb_vpl VALUES ("JG1_30","008_1_30","JDG","1","30","30","זבולן לא הוריש את יושבי קטרון ואת יושבי נהלל וישב הכנעני בקרבו ויהיו למס׃ ");
INSERT INTO heb_vpl VALUES ("JG1_31","008_1_31","JDG","1","31","31","אשר לא הוריש את ישבי עכו ואת יושבי צידון ואת אחלב ואת אכזיב ואת חלבה ואת אפיק ואת רחב׃ ");
INSERT INTO heb_vpl VALUES ("JG1_32","008_1_32","JDG","1","32","32","וישב האשרי בקרב הכנעני ישבי הארץ כי לא הורישו׃ ");
INSERT INTO heb_vpl VALUES ("JG1_33","008_1_33","JDG","1","33","33","נפתלי לא הוריש את ישבי בית שמש ואת ישבי בית ענת וישב בקרב הכנעני ישבי הארץ וישבי בית שמש ובית ענת היו להם למס׃ ");
INSERT INTO heb_vpl VALUES ("JG1_34","008_1_34","JDG","1","34","34","וילחצו האמרי את בני דן ההרה כי לא נתנו לרדת לעמק׃ ");
INSERT INTO heb_vpl VALUES ("JG1_35","008_1_35","JDG","1","35","35","ויואל האמרי לשבת בהר חרס באילון ובשעלבים ותכבד יד בית יוסף ויהיו למס׃ ");
INSERT INTO heb_vpl VALUES ("JG1_36","008_1_36","JDG","1","36","36","וגבול האמרי ממעלה עקרבים מהסלע ומעלה׃ ");
INSERT INTO heb_vpl VALUES ("JG2_1","008_2_1","JDG","2","1","1","ויעל מלאך יהוה מן הגלגל אל הבכים ויאמר אעלה אתכם ממצרים ואביא אתכם אל הארץ אשר נשבעתי לאבתיכם ואמר לא אפר בריתי אתכם לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JG2_2","008_2_2","JDG","2","2","2","ואתם לא תכרתו ברית ליושבי הארץ הזאת מזבחותיהם תתצון ולא שמעתם בקלי מה זאת עשיתם׃ ");
INSERT INTO heb_vpl VALUES ("JG2_3","008_2_3","JDG","2","3","3","וגם אמרתי לא אגרש אותם מפניכם והיו לכם לצדים ואלהיהם יהיו לכם למוקש׃ ");
INSERT INTO heb_vpl VALUES ("JG2_4","008_2_4","JDG","2","4","4","ויהי כדבר מלאך יהוה את הדברים האלה אל כל בני ישראל וישאו העם את קולם ויבכו׃ ");
INSERT INTO heb_vpl VALUES ("JG2_5","008_2_5","JDG","2","5","5","ויקראו שם המקום ההוא בכים ויזבחו שם ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG2_6","008_2_6","JDG","2","6","6","וישלח יהושע את העם וילכו בני ישראל איש לנחלתו לרשת את הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JG2_7","008_2_7","JDG","2","7","7","ויעבדו העם את יהוה כל ימי יהושע וכל ימי הזקנים אשר האריכו ימים אחרי יהושוע אשר ראו את כל מעשה יהוה הגדול אשר עשה לישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG2_8","008_2_8","JDG","2","8","8","וימת יהושע בן נון עבד יהוה בן מאה ועשר שנים׃ ");
INSERT INTO heb_vpl VALUES ("JG2_9","008_2_9","JDG","2","9","9","ויקברו אותו בגבול נחלתו בתמנת חרס בהר אפרים מצפון להר געש׃ ");
INSERT INTO heb_vpl VALUES ("JG2_10","008_2_10","JDG","2","10","10","וגם כל הדור ההוא נאספו אל אבותיו ויקם דור אחר אחריהם אשר לא ידעו את יהוה וגם את המעשה אשר עשה לישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG2_11","008_2_11","JDG","2","11","11","ויעשו בני ישראל את הרע בעיני יהוה ויעבדו את הבעלים׃ ");
INSERT INTO heb_vpl VALUES ("JG2_12","008_2_12","JDG","2","12","12","ויעזבו את יהוה אלהי אבותם המוציא אותם מארץ מצרים וילכו אחרי אלהים אחרים מאלהי העמים אשר סביבותיהם וישתחוו להם ויכעסו את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG2_13","008_2_13","JDG","2","13","13","ויעזבו את יהוה ויעבדו לבעל ולעשתרות׃ ");
INSERT INTO heb_vpl VALUES ("JG2_14","008_2_14","JDG","2","14","14","ויחר אף יהוה בישראל ויתנם ביד שסים וישסו אותם וימכרם ביד אויביהם מסביב ולא יכלו עוד לעמד לפני אויביהם׃ ");
INSERT INTO heb_vpl VALUES ("JG2_15","008_2_15","JDG","2","15","15","בכל אשר יצאו יד יהוה היתה בם לרעה כאשר דבר יהוה וכאשר נשבע יהוה להם ויצר להם מאד׃ ");
INSERT INTO heb_vpl VALUES ("JG2_16","008_2_16","JDG","2","16","16","ויקם יהוה שפטים ויושיעום מיד שסיהם׃ ");
INSERT INTO heb_vpl VALUES ("JG2_17","008_2_17","JDG","2","17","17","וגם אל שפטיהם לא שמעו כי זנו אחרי אלהים אחרים וישתחוו להם סרו מהר מן הדרך אשר הלכו אבותם לשמע מצות יהוה לא עשו כן׃ ");
INSERT INTO heb_vpl VALUES ("JG2_18","008_2_18","JDG","2","18","18","וכי הקים יהוה להם שפטים והיה יהוה עם השפט והושיעם מיד איביהם כל ימי השופט כי ינחם יהוה מנאקתם מפני לחציהם ודחקיהם׃ ");
INSERT INTO heb_vpl VALUES ("JG2_19","008_2_19","JDG","2","19","19","והיה במות השופט ישבו והשחיתו מאבותם ללכת אחרי אלהים אחרים לעבדם ולהשתחות להם לא הפילו ממעלליהם ומדרכם הקשה׃ ");
INSERT INTO heb_vpl VALUES ("JG2_20","008_2_20","JDG","2","20","20","ויחר אף יהוה בישראל ויאמר יען אשר עברו הגוי הזה את בריתי אשר צויתי את אבותם ולא שמעו לקולי׃ ");
INSERT INTO heb_vpl VALUES ("JG2_21","008_2_21","JDG","2","21","21","גם אני לא אוסיף להוריש איש מפניהם מן הגוים אשר עזב יהושע וימת׃ ");
INSERT INTO heb_vpl VALUES ("JG2_22","008_2_22","JDG","2","22","22","למען נסות בם את ישראל השמרים הם את דרך יהוה ללכת בם כאשר שמרו אבותם אם לא׃ ");
INSERT INTO heb_vpl VALUES ("JG2_23","008_2_23","JDG","2","23","23","וינח יהוה את הגוים האלה לבלתי הורישם מהר ולא נתנם ביד יהושע׃ ");
INSERT INTO heb_vpl VALUES ("JG3_1","008_3_1","JDG","3","1","1","ואלה הגוים אשר הניח יהוה לנסות בם את ישראל את כל אשר לא ידעו את כל מלחמות כנען׃ ");
INSERT INTO heb_vpl VALUES ("JG3_2","008_3_2","JDG","3","2","2","רק למען דעת דרות בני ישראל ללמדם מלחמה רק אשר לפנים לא ידעום׃ ");
INSERT INTO heb_vpl VALUES ("JG3_3","008_3_3","JDG","3","3","3","חמשת סרני פלשתים וכל הכנעני והצידני והחוי ישב הר הלבנון מהר בעל חרמון עד לבוא חמת׃ ");
INSERT INTO heb_vpl VALUES ("JG3_4","008_3_4","JDG","3","4","4","ויהיו לנסות בם את ישראל לדעת הישמעו את מצות יהוה אשר צוה את אבותם ביד משה׃ ");
INSERT INTO heb_vpl VALUES ("JG3_5","008_3_5","JDG","3","5","5","ובני ישראל ישבו בקרב הכנעני החתי והאמרי והפרזי והחוי והיבוסי׃ ");
INSERT INTO heb_vpl VALUES ("JG3_6","008_3_6","JDG","3","6","6","ויקחו את בנותיהם להם לנשים ואת בנותיהם נתנו לבניהם ויעבדו את אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("JG3_7","008_3_7","JDG","3","7","7","ויעשו בני ישראל את הרע בעיני יהוה וישכחו את יהוה אלהיהם ויעבדו את הבעלים ואת האשרות׃ ");
INSERT INTO heb_vpl VALUES ("JG3_8","008_3_8","JDG","3","8","8","ויחר אף יהוה בישראל וימכרם ביד כושן רשעתים מלך ארם נהרים ויעבדו בני ישראל את כושן רשעתים שמנה שנים׃ ");
INSERT INTO heb_vpl VALUES ("JG3_9","008_3_9","JDG","3","9","9","ויזעקו בני ישראל אל יהוה ויקם יהוה מושיע לבני ישראל ויושיעם את עתניאל בן קנז אחי כלב הקטן ממנו׃ ");
INSERT INTO heb_vpl VALUES ("JG3_10","008_3_10","JDG","3","10","10","ותהי עליו רוח יהוה וישפט את ישראל ויצא למלחמה ויתן יהוה בידו את כושן רשעתים מלך ארם ותעז ידו על כושן רשעתים׃ ");
INSERT INTO heb_vpl VALUES ("JG3_11","008_3_11","JDG","3","11","11","ותשקט הארץ ארבעים שנה וימת עתניאל בן קנז׃ ");
INSERT INTO heb_vpl VALUES ("JG3_12","008_3_12","JDG","3","12","12","ויספו בני ישראל לעשות הרע בעיני יהוה ויחזק יהוה את עגלון מלך מואב על ישראל על כי עשו את הרע בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG3_13","008_3_13","JDG","3","13","13","ויאסף אליו את בני עמון ועמלק וילך ויך את ישראל ויירשו את עיר התמרים׃ ");
INSERT INTO heb_vpl VALUES ("JG3_14","008_3_14","JDG","3","14","14","ויעבדו בני ישראל את עגלון מלך מואב שמונה עשרה שנה׃ ");
INSERT INTO heb_vpl VALUES ("JG3_15","008_3_15","JDG","3","15","15","ויזעקו בני ישראל אל יהוה ויקם יהוה להם מושיע את אהוד בן גרא בן הימיני איש אטר יד ימינו וישלחו בני ישראל בידו מנחה לעגלון מלך מואב׃ ");
INSERT INTO heb_vpl VALUES ("JG3_16","008_3_16","JDG","3","16","16","ויעש לו אהוד חרב ולה שני פיות גמד ארכה ויחגר אותה מתחת למדיו על ירך ימינו׃ ");
INSERT INTO heb_vpl VALUES ("JG3_17","008_3_17","JDG","3","17","17","ויקרב את המנחה לעגלון מלך מואב ועגלון איש בריא מאד׃ ");
INSERT INTO heb_vpl VALUES ("JG3_18","008_3_18","JDG","3","18","18","ויהי כאשר כלה להקריב את המנחה וישלח את העם נשאי המנחה׃ ");
INSERT INTO heb_vpl VALUES ("JG3_19","008_3_19","JDG","3","19","19","והוא שב מן הפסילים אשר את הגלגל ויאמר דבר סתר לי אליך המלך ויאמר הס ויצאו מעליו כל העמדים עליו׃ ");
INSERT INTO heb_vpl VALUES ("JG3_20","008_3_20","JDG","3","20","20","ואהוד בא אליו והוא ישב בעלית המקרה אשר לו לבדו ויאמר אהוד דבר אלהים לי אליך ויקם מעל הכסא׃ ");
INSERT INTO heb_vpl VALUES ("JG3_21","008_3_21","JDG","3","21","21","וישלח אהוד את יד שמאלו ויקח את החרב מעל ירך ימינו ויתקעה בבטנו׃ ");
INSERT INTO heb_vpl VALUES ("JG3_22","008_3_22","JDG","3","22","22","ויבא גם הנצב אחר הלהב ויסגר החלב בעד הלהב כי לא שלף החרב מבטנו ויצא הפרשדנה׃ ");
INSERT INTO heb_vpl VALUES ("JG3_23","008_3_23","JDG","3","23","23","ויצא אהוד המסדרונה ויסגר דלתות העליה בעדו ונעל׃ ");
INSERT INTO heb_vpl VALUES ("JG3_24","008_3_24","JDG","3","24","24","והוא יצא ועבדיו באו ויראו והנה דלתות העליה נעלות ויאמרו אך מסיך הוא את רגליו בחדר המקרה׃ ");
INSERT INTO heb_vpl VALUES ("JG3_25","008_3_25","JDG","3","25","25","ויחילו עד בוש והנה איננו פתח דלתות העליה ויקחו את המפתח ויפתחו והנה אדניהם נפל ארצה מת׃ ");
INSERT INTO heb_vpl VALUES ("JG3_26","008_3_26","JDG","3","26","26","ואהוד נמלט עד התמהמהם והוא עבר את הפסילים וימלט השעירתה׃ ");
INSERT INTO heb_vpl VALUES ("JG3_27","008_3_27","JDG","3","27","27","ויהי בבואו ויתקע בשופר בהר אפרים וירדו עמו בני ישראל מן ההר והוא לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("JG3_28","008_3_28","JDG","3","28","28","ויאמר אלהם רדפו אחרי כי נתן יהוה את איביכם את מואב בידכם וירדו אחריו וילכדו את מעברות הירדן למואב ולא נתנו איש לעבר׃ ");
INSERT INTO heb_vpl VALUES ("JG3_29","008_3_29","JDG","3","29","29","ויכו את מואב בעת ההיא כעשרת אלפים איש כל שמן וכל איש חיל ולא נמלט איש׃ ");
INSERT INTO heb_vpl VALUES ("JG3_30","008_3_30","JDG","3","30","30","ותכנע מואב ביום ההוא תחת יד ישראל ותשקט הארץ שמונים שנה׃ ");
INSERT INTO heb_vpl VALUES ("JG3_31","008_3_31","JDG","3","31","31","ואחריו היה שמגר בן ענת ויך את פלשתים שש מאות איש במלמד הבקר וישע גם הוא את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG4_1","008_4_1","JDG","4","1","1","ויספו בני ישראל לעשות הרע בעיני יהוה ואהוד מת׃ ");
INSERT INTO heb_vpl VALUES ("JG4_2","008_4_2","JDG","4","2","2","וימכרם יהוה ביד יבין מלך כנען אשר מלך בחצור ושר צבאו סיסרא והוא יושב בחרשת הגוים׃ ");
INSERT INTO heb_vpl VALUES ("JG4_3","008_4_3","JDG","4","3","3","ויצעקו בני ישראל אל יהוה כי תשע מאות רכב ברזל לו והוא לחץ את בני ישראל בחזקה עשרים שנה׃ ");
INSERT INTO heb_vpl VALUES ("JG4_4","008_4_4","JDG","4","4","4","ודבורה אשה נביאה אשת לפידות היא שפטה את ישראל בעת ההיא׃ ");
INSERT INTO heb_vpl VALUES ("JG4_5","008_4_5","JDG","4","5","5","והיא יושבת תחת תמר דבורה בין הרמה ובין בית אל בהר אפרים ויעלו אליה בני ישראל למשפט׃ ");
INSERT INTO heb_vpl VALUES ("JG4_6","008_4_6","JDG","4","6","6","ותשלח ותקרא לברק בן אבינעם מקדש נפתלי ותאמר אליו הלא צוה יהוה אלהי ישראל לך ומשכת בהר תבור ולקחת עמך עשרת אלפים איש מבני נפתלי ומבני זבלון׃ ");
INSERT INTO heb_vpl VALUES ("JG4_7","008_4_7","JDG","4","7","7","ומשכתי אליך אל נחל קישון את סיסרא שר צבא יבין ואת רכבו ואת המונו ונתתיהו בידך׃ ");
INSERT INTO heb_vpl VALUES ("JG4_8","008_4_8","JDG","4","8","8","ויאמר אליה ברק אם תלכי עמי והלכתי ואם לא תלכי עמי לא אלך׃ ");
INSERT INTO heb_vpl VALUES ("JG4_9","008_4_9","JDG","4","9","9","ותאמר הלך אלך עמך אפס כי לא תהיה תפארתך על הדרך אשר אתה הולך כי ביד אשה ימכר יהוה את סיסרא ותקם דבורה ותלך עם ברק קדשה׃ ");
INSERT INTO heb_vpl VALUES ("JG4_10","008_4_10","JDG","4","10","10","ויזעק ברק את זבולן ואת נפתלי קדשה ויעל ברגליו עשרת אלפי איש ותעל עמו דבורה׃ ");
INSERT INTO heb_vpl VALUES ("JG4_11","008_4_11","JDG","4","11","11","וחבר הקיני נפרד מקין מבני חבב חתן משה ויט אהלו עד אלון בצענים אשר את קדש׃ ");
INSERT INTO heb_vpl VALUES ("JG4_12","008_4_12","JDG","4","12","12","ויגדו לסיסרא כי עלה ברק בן אבינעם הר תבור׃ ");
INSERT INTO heb_vpl VALUES ("JG4_13","008_4_13","JDG","4","13","13","ויזעק סיסרא את כל רכבו תשע מאות רכב ברזל ואת כל העם אשר אתו מחרשת הגוים אל נחל קישון׃ ");
INSERT INTO heb_vpl VALUES ("JG4_14","008_4_14","JDG","4","14","14","ותאמר דברה אל ברק קום כי זה היום אשר נתן יהוה את סיסרא בידך הלא יהוה יצא לפניך וירד ברק מהר תבור ועשרת אלפים איש אחריו׃ ");
INSERT INTO heb_vpl VALUES ("JG4_15","008_4_15","JDG","4","15","15","ויהם יהוה את סיסרא ואת כל הרכב ואת כל המחנה לפי חרב לפני ברק וירד סיסרא מעל המרכבה וינס ברגליו׃ ");
INSERT INTO heb_vpl VALUES ("JG4_16","008_4_16","JDG","4","16","16","וברק רדף אחרי הרכב ואחרי המחנה עד חרשת הגוים ויפל כל מחנה סיסרא לפי חרב לא נשאר עד אחד׃ ");
INSERT INTO heb_vpl VALUES ("JG4_17","008_4_17","JDG","4","17","17","וסיסרא נס ברגליו אל אהל יעל אשת חבר הקיני כי שלום בין יבין מלך חצור ובין בית חבר הקיני׃ ");
INSERT INTO heb_vpl VALUES ("JG4_18","008_4_18","JDG","4","18","18","ותצא יעל לקראת סיסרא ותאמר אליו סורה אדני סורה אלי אל תירא ויסר אליה האהלה ותכסהו בשמיכה׃ ");
INSERT INTO heb_vpl VALUES ("JG4_19","008_4_19","JDG","4","19","19","ויאמר אליה השקיני נא מעט מים כי צמאתי ותפתח את נאוד החלב ותשקהו ותכסהו׃ ");
INSERT INTO heb_vpl VALUES ("JG4_20","008_4_20","JDG","4","20","20","ויאמר אליה עמד פתח האהל והיה אם איש יבוא ושאלך ואמר היש פה איש ואמרת אין׃ ");
INSERT INTO heb_vpl VALUES ("JG4_21","008_4_21","JDG","4","21","21","ותקח יעל אשת חבר את יתד האהל ותשם את המקבת בידה ותבוא אליו בלאט ותתקע את היתד ברקתו ותצנח בארץ והוא נרדם ויעף וימת׃ ");
INSERT INTO heb_vpl VALUES ("JG4_22","008_4_22","JDG","4","22","22","והנה ברק רדף את סיסרא ותצא יעל לקראתו ותאמר לו לך ואראך את האיש אשר אתה מבקש ויבא אליה והנה סיסרא נפל מת והיתד ברקתו׃ ");
INSERT INTO heb_vpl VALUES ("JG4_23","008_4_23","JDG","4","23","23","ויכנע אלהים ביום ההוא את יבין מלך כנען לפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG4_24","008_4_24","JDG","4","24","24","ותלך יד בני ישראל הלוך וקשה על יבין מלך כנען עד אשר הכריתו את יבין מלך כנען׃ ");
INSERT INTO heb_vpl VALUES ("JG5_1","008_5_1","JDG","5","1","1","ותשר דבורה וברק בן אבינעם ביום ההוא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JG5_2","008_5_2","JDG","5","2","2","בפרע פרעות בישראל בהתנדב עם ברכו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG5_3","008_5_3","JDG","5","3","3","שמעו מלכים האזינו רזנים אנכי ליהוה אנכי אשירה אזמר ליהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG5_4","008_5_4","JDG","5","4","4","יהוה בצאתך משעיר בצעדך משדה אדום ארץ רעשה גם שמים נטפו גם עבים נטפו מים׃ ");
INSERT INTO heb_vpl VALUES ("JG5_5","008_5_5","JDG","5","5","5","הרים נזלו מפני יהוה זה סיני מפני יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG5_6","008_5_6","JDG","5","6","6","בימי שמגר בן ענת בימי יעל חדלו ארחות והלכי נתיבות ילכו ארחות עקלקלות׃ ");
INSERT INTO heb_vpl VALUES ("JG5_7","008_5_7","JDG","5","7","7","חדלו פרזון בישראל חדלו עד שקמתי דבורה שקמתי אם בישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG5_8","008_5_8","JDG","5","8","8","יבחר אלהים חדשים אז לחם שערים מגן אם יראה ורמח בארבעים אלף בישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG5_9","008_5_9","JDG","5","9","9","לבי לחוקקי ישראל המתנדבים בעם ברכו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG5_10","008_5_10","JDG","5","10","10","רכבי אתנות צחרות ישבי על מדין והלכי על דרך שיחו׃ ");
INSERT INTO heb_vpl VALUES ("JG5_11","008_5_11","JDG","5","11","11","מקול מחצצים בין משאבים שם יתנו צדקות יהוה צדקת פרזנו בישראל אז ירדו לשערים עם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG5_12","008_5_12","JDG","5","12","12","עורי עורי דבורה עורי עורי דברי שיר קום ברק ושבה שביך בן אבינעם׃ ");
INSERT INTO heb_vpl VALUES ("JG5_13","008_5_13","JDG","5","13","13","אז ירד שריד לאדירים עם יהוה ירד לי בגבורים׃ ");
INSERT INTO heb_vpl VALUES ("JG5_14","008_5_14","JDG","5","14","14","מני אפרים שרשם בעמלק אחריך בנימין בעממיך מני מכיר ירדו מחקקים ומזבולן משכים בשבט ספר׃ ");
INSERT INTO heb_vpl VALUES ("JG5_15","008_5_15","JDG","5","15","15","ושרי ביששכר עם דברה ויששכר כן ברק בעמק שלח ברגליו בפלגות ראובן גדלים חקקי לב׃ ");
INSERT INTO heb_vpl VALUES ("JG5_16","008_5_16","JDG","5","16","16","למה ישבת בין המשפתים לשמע שרקות עדרים לפלגות ראובן גדולים חקרי לב׃ ");
INSERT INTO heb_vpl VALUES ("JG5_17","008_5_17","JDG","5","17","17","גלעד בעבר הירדן שכן ודן למה יגור אניות אשר ישב לחוף ימים ועל מפרציו ישכון׃ ");
INSERT INTO heb_vpl VALUES ("JG5_18","008_5_18","JDG","5","18","18","זבלון עם חרף נפשו למות ונפתלי על מרומי שדה׃ ");
INSERT INTO heb_vpl VALUES ("JG5_19","008_5_19","JDG","5","19","19","באו מלכים נלחמו אז נלחמו מלכי כנען בתענך על מי מגדו בצע כסף לא לקחו׃ ");
INSERT INTO heb_vpl VALUES ("JG5_20","008_5_20","JDG","5","20","20","מן שמים נלחמו הכוכבים ממסלותם נלחמו עם סיסרא׃ ");
INSERT INTO heb_vpl VALUES ("JG5_21","008_5_21","JDG","5","21","21","נחל קישון גרפם נחל קדומים נחל קישון תדרכי נפשי עז׃ ");
INSERT INTO heb_vpl VALUES ("JG5_22","008_5_22","JDG","5","22","22","אז הלמו עקבי סוס מדהרות דהרות אביריו׃ ");
INSERT INTO heb_vpl VALUES ("JG5_23","008_5_23","JDG","5","23","23","אורו מרוז אמר מלאך יהוה ארו ארור ישביה כי לא באו לעזרת יהוה לעזרת יהוה בגבורים׃ ");
INSERT INTO heb_vpl VALUES ("JG5_24","008_5_24","JDG","5","24","24","תברך מנשים יעל אשת חבר הקיני מנשים באהל תברך׃ ");
INSERT INTO heb_vpl VALUES ("JG5_25","008_5_25","JDG","5","25","25","מים שאל חלב נתנה בספל אדירים הקריבה חמאה׃ ");
INSERT INTO heb_vpl VALUES ("JG5_26","008_5_26","JDG","5","26","26","ידה ליתד תשלחנה וימינה להלמות עמלים והלמה סיסרא מחקה ראשו ומחצה וחלפה רקתו׃ ");
INSERT INTO heb_vpl VALUES ("JG5_27","008_5_27","JDG","5","27","27","בין רגליה כרע נפל שכב בין רגליה כרע נפל באשר כרע שם נפל שדוד׃ ");
INSERT INTO heb_vpl VALUES ("JG5_28","008_5_28","JDG","5","28","28","בעד החלון נשקפה ותיבב אם סיסרא בעד האשנב מדוע בשש רכבו לבוא מדוע אחרו פעמי מרכבותיו׃ ");
INSERT INTO heb_vpl VALUES ("JG5_29","008_5_29","JDG","5","29","29","חכמות שרותיה תענינה אף היא תשיב אמריה לה׃ ");
INSERT INTO heb_vpl VALUES ("JG5_30","008_5_30","JDG","5","30","30","הלא ימצאו יחלקו שלל רחם רחמתים לראש גבר שלל צבעים לסיסרא שלל צבעים רקמה צבע רקמתים לצוארי שלל׃ ");
INSERT INTO heb_vpl VALUES ("JG5_31","008_5_31","JDG","5","31","31","כן יאבדו כל אויביך יהוה ואהביו כצאת השמש בגברתו ותשקט הארץ ארבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("JG6_1","008_6_1","JDG","6","1","1","ויעשו בני ישראל הרע בעיני יהוה ויתנם יהוה ביד מדין שבע שנים׃ ");
INSERT INTO heb_vpl VALUES ("JG6_2","008_6_2","JDG","6","2","2","ותעז יד מדין על ישראל מפני מדין עשו להם בני ישראל את המנהרות אשר בהרים ואת המערות ואת המצדות׃ ");
INSERT INTO heb_vpl VALUES ("JG6_3","008_6_3","JDG","6","3","3","והיה אם זרע ישראל ועלה מדין ועמלק ובני קדם ועלו עליו׃ ");
INSERT INTO heb_vpl VALUES ("JG6_4","008_6_4","JDG","6","4","4","ויחנו עליהם וישחיתו את יבול הארץ עד בואך עזה ולא ישאירו מחיה בישראל ושה ושור וחמור׃ ");
INSERT INTO heb_vpl VALUES ("JG6_5","008_6_5","JDG","6","5","5","כי הם ומקניהם יעלו ואהליהם יבאו כדי ארבה לרב ולהם ולגמליהם אין מספר ויבאו בארץ לשחתה׃ ");
INSERT INTO heb_vpl VALUES ("JG6_6","008_6_6","JDG","6","6","6","וידל ישראל מאד מפני מדין ויזעקו בני ישראל אל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG6_7","008_6_7","JDG","6","7","7","ויהי כי זעקו בני ישראל אל יהוה על אדות מדין׃ ");
INSERT INTO heb_vpl VALUES ("JG6_8","008_6_8","JDG","6","8","8","וישלח יהוה איש נביא אל בני ישראל ויאמר להם כה אמר יהוה אלהי ישראל אנכי העליתי אתכם ממצרים ואציא אתכם מבית עבדים׃ ");
INSERT INTO heb_vpl VALUES ("JG6_9","008_6_9","JDG","6","9","9","ואצל אתכם מיד מצרים ומיד כל לחציכם ואגרש אותם מפניכם ואתנה לכם את ארצם׃ ");
INSERT INTO heb_vpl VALUES ("JG6_10","008_6_10","JDG","6","10","10","ואמרה לכם אני יהוה אלהיכם לא תיראו את אלהי האמרי אשר אתם יושבים בארצם ולא שמעתם בקולי׃ ");
INSERT INTO heb_vpl VALUES ("JG6_11","008_6_11","JDG","6","11","11","ויבא מלאך יהוה וישב תחת האלה אשר בעפרה אשר ליואש אבי העזרי וגדעון בנו חבט חטים בגת להניס מפני מדין׃ ");
INSERT INTO heb_vpl VALUES ("JG6_12","008_6_12","JDG","6","12","12","וירא אליו מלאך יהוה ויאמר אליו יהוה עמך גבור החיל׃ ");
INSERT INTO heb_vpl VALUES ("JG6_13","008_6_13","JDG","6","13","13","ויאמר אליו גדעון בי אדני ויש יהוה עמנו ולמה מצאתנו כל זאת ואיה כל נפלאתיו אשר ספרו לנו אבותינו לאמר הלא ממצרים העלנו יהוה ועתה נטשנו יהוה ויתננו בכף מדין׃ ");
INSERT INTO heb_vpl VALUES ("JG6_14","008_6_14","JDG","6","14","14","ויפן אליו יהוה ויאמר לך בכחך זה והושעת את ישראל מכף מדין הלא שלחתיך׃ ");
INSERT INTO heb_vpl VALUES ("JG6_15","008_6_15","JDG","6","15","15","ויאמר אליו בי אדני במה אושיע את ישראל הנה אלפי הדל במנשה ואנכי הצעיר בבית אבי׃ ");
INSERT INTO heb_vpl VALUES ("JG6_16","008_6_16","JDG","6","16","16","ויאמר אליו יהוה כי אהיה עמך והכית את מדין כאיש אחד׃ ");
INSERT INTO heb_vpl VALUES ("JG6_17","008_6_17","JDG","6","17","17","ויאמר אליו אם נא מצאתי חן בעיניך ועשית לי אות שאתה מדבר עמי׃ ");
INSERT INTO heb_vpl VALUES ("JG6_18","008_6_18","JDG","6","18","18","אל נא תמש מזה עד באי אליך והצאתי את מנחתי והנחתי לפניך ויאמר אנכי אשב עד שובך׃ ");
INSERT INTO heb_vpl VALUES ("JG6_19","008_6_19","JDG","6","19","19","וגדעון בא ויעש גדי עזים ואיפת קמח מצות הבשר שם בסל והמרק שם בפרור ויוצא אליו אל תחת האלה ויגש׃ ");
INSERT INTO heb_vpl VALUES ("JG6_20","008_6_20","JDG","6","20","20","ויאמר אליו מלאך האלהים קח את הבשר ואת המצות והנח אל הסלע הלז ואת המרק שפוך ויעש כן׃ ");
INSERT INTO heb_vpl VALUES ("JG6_21","008_6_21","JDG","6","21","21","וישלח מלאך יהוה את קצה המשענת אשר בידו ויגע בבשר ובמצות ותעל האש מן הצור ותאכל את הבשר ואת המצות ומלאך יהוה הלך מעיניו׃ ");
INSERT INTO heb_vpl VALUES ("JG6_22","008_6_22","JDG","6","22","22","וירא גדעון כי מלאך יהוה הוא ויאמר גדעון אהה אדני יהוה כי על כן ראיתי מלאך יהוה פנים אל פנים׃ ");
INSERT INTO heb_vpl VALUES ("JG6_23","008_6_23","JDG","6","23","23","ויאמר לו יהוה שלום לך אל תירא לא תמות׃ ");
INSERT INTO heb_vpl VALUES ("JG6_24","008_6_24","JDG","6","24","24","ויבן שם גדעון מזבח ליהוה ויקרא לו יהוה שלום עד היום הזה עודנו בעפרת אבי העזרי׃ ");
INSERT INTO heb_vpl VALUES ("JG6_25","008_6_25","JDG","6","25","25","ויהי בלילה ההוא ויאמר לו יהוה קח את פר השור אשר לאביך ופר השני שבע שנים והרסת את מזבח הבעל אשר לאביך ואת האשרה אשר עליו תכרת׃ ");
INSERT INTO heb_vpl VALUES ("JG6_26","008_6_26","JDG","6","26","26","ובנית מזבח ליהוה אלהיך על ראש המעוז הזה במערכה ולקחת את הפר השני והעלית עולה בעצי האשרה אשר תכרת׃ ");
INSERT INTO heb_vpl VALUES ("JG6_27","008_6_27","JDG","6","27","27","ויקח גדעון עשרה אנשים מעבדיו ויעש כאשר דבר אליו יהוה ויהי כאשר ירא את בית אביו ואת אנשי העיר מעשות יומם ויעש לילה׃ ");
INSERT INTO heb_vpl VALUES ("JG6_28","008_6_28","JDG","6","28","28","וישכימו אנשי העיר בבקר והנה נתץ מזבח הבעל והאשרה אשר עליו כרתה ואת הפר השני העלה על המזבח הבנוי׃ ");
INSERT INTO heb_vpl VALUES ("JG6_29","008_6_29","JDG","6","29","29","ויאמרו איש אל רעהו מי עשה הדבר הזה וידרשו ויבקשו ויאמרו גדעון בן יואש עשה הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("JG6_30","008_6_30","JDG","6","30","30","ויאמרו אנשי העיר אל יואש הוצא את בנך וימת כי נתץ את מזבח הבעל וכי כרת האשרה אשר עליו׃ ");
INSERT INTO heb_vpl VALUES ("JG6_31","008_6_31","JDG","6","31","31","ויאמר יואש לכל אשר עמדו עליו האתם תריבון לבעל אם אתם תושיעון אותו אשר יריב לו יומת עד הבקר אם אלהים הוא ירב לו כי נתץ את מזבחו׃ ");
INSERT INTO heb_vpl VALUES ("JG6_32","008_6_32","JDG","6","32","32","ויקרא לו ביום ההוא ירבעל לאמר ירב בו הבעל כי נתץ את מזבחו׃ ");
INSERT INTO heb_vpl VALUES ("JG6_33","008_6_33","JDG","6","33","33","וכל מדין ועמלק ובני קדם נאספו יחדו ויעברו ויחנו בעמק יזרעאל׃ ");
INSERT INTO heb_vpl VALUES ("JG6_34","008_6_34","JDG","6","34","34","ורוח יהוה לבשה את גדעון ויתקע בשופר ויזעק אביעזר אחריו׃ ");
INSERT INTO heb_vpl VALUES ("JG6_35","008_6_35","JDG","6","35","35","ומלאכים שלח בכל מנשה ויזעק גם הוא אחריו ומלאכים שלח באשר ובזבלון ובנפתלי ויעלו לקראתם׃ ");
INSERT INTO heb_vpl VALUES ("JG6_36","008_6_36","JDG","6","36","36","ויאמר גדעון אל האלהים אם ישך מושיע בידי את ישראל כאשר דברת׃ ");
INSERT INTO heb_vpl VALUES ("JG6_37","008_6_37","JDG","6","37","37","הנה אנכי מציג את גזת הצמר בגרן אם טל יהיה על הגזה לבדה ועל כל הארץ חרב וידעתי כי תושיע בידי את ישראל כאשר דברת׃ ");
INSERT INTO heb_vpl VALUES ("JG6_38","008_6_38","JDG","6","38","38","ויהי כן וישכם ממחרת ויזר את הגזה וימץ טל מן הגזה מלוא הספל מים׃ ");
INSERT INTO heb_vpl VALUES ("JG6_39","008_6_39","JDG","6","39","39","ויאמר גדעון אל האלהים אל יחר אפך בי ואדברה אך הפעם אנסה נא רק הפעם בגזה יהי נא חרב אל הגזה לבדה ועל כל הארץ יהיה טל׃ ");
INSERT INTO heb_vpl VALUES ("JG6_40","008_6_40","JDG","6","40","40","ויעש אלהים כן בלילה ההוא ויהי חרב אל הגזה לבדה ועל כל הארץ היה טל׃ ");
INSERT INTO heb_vpl VALUES ("JG7_1","008_7_1","JDG","7","1","1","וישכם ירבעל הוא גדעון וכל העם אשר אתו ויחנו על עין חרד ומחנה מדין היה לו מצפון מגבעת המורה בעמק׃ ");
INSERT INTO heb_vpl VALUES ("JG7_2","008_7_2","JDG","7","2","2","ויאמר יהוה אל גדעון רב העם אשר אתך מתתי את מדין בידם פן יתפאר עלי ישראל לאמר ידי הושיעה לי׃ ");
INSERT INTO heb_vpl VALUES ("JG7_3","008_7_3","JDG","7","3","3","ועתה קרא נא באזני העם לאמר מי ירא וחרד ישב ויצפר מהר הגלעד וישב מן העם עשרים ושנים אלף ועשרת אלפים נשארו׃ ");
INSERT INTO heb_vpl VALUES ("JG7_4","008_7_4","JDG","7","4","4","ויאמר יהוה אל גדעון עוד העם רב הורד אותם אל המים ואצרפנו לך שם והיה אשר אמר אליך זה ילך אתך הוא ילך אתך וכל אשר אמר אליך זה לא ילך עמך הוא לא ילך׃ ");
INSERT INTO heb_vpl VALUES ("JG7_5","008_7_5","JDG","7","5","5","ויורד את העם אל המים ויאמר יהוה אל גדעון כל אשר ילק בלשונו מן המים כאשר ילק הכלב תציג אותו לבד וכל אשר יכרע על ברכיו לשתות׃ ");
INSERT INTO heb_vpl VALUES ("JG7_6","008_7_6","JDG","7","6","6","ויהי מספר המלקקים בידם אל פיהם שלש מאות איש וכל יתר העם כרעו על ברכיהם לשתות מים׃ ");
INSERT INTO heb_vpl VALUES ("JG7_7","008_7_7","JDG","7","7","7","ויאמר יהוה אל גדעון בשלש מאות האיש המלקקים אושיע אתכם ונתתי את מדין בידך וכל העם ילכו איש למקמו׃ ");
INSERT INTO heb_vpl VALUES ("JG7_8","008_7_8","JDG","7","8","8","ויקחו את צדה העם בידם ואת שופרתיהם ואת כל איש ישראל שלח איש לאהליו ובשלש מאות האיש החזיק ומחנה מדין היה לו מתחת בעמק׃ ");
INSERT INTO heb_vpl VALUES ("JG7_9","008_7_9","JDG","7","9","9","ויהי בלילה ההוא ויאמר אליו יהוה קום רד במחנה כי נתתיו בידך׃ ");
INSERT INTO heb_vpl VALUES ("JG7_10","008_7_10","JDG","7","10","10","ואם ירא אתה לרדת רד אתה ופרה נערך אל המחנה׃ ");
INSERT INTO heb_vpl VALUES ("JG7_11","008_7_11","JDG","7","11","11","ושמעת מה ידברו ואחר תחזקנה ידיך וירדת במחנה וירד הוא ופרה נערו אל קצה החמשים אשר במחנה׃ ");
INSERT INTO heb_vpl VALUES ("JG7_12","008_7_12","JDG","7","12","12","ומדין ועמלק וכל בני קדם נפלים בעמק כארבה לרב ולגמליהם אין מספר כחול שעל שפת הים לרב׃ ");
INSERT INTO heb_vpl VALUES ("JG7_13","008_7_13","JDG","7","13","13","ויבא גדעון והנה איש מספר לרעהו חלום ויאמר הנה חלום חלמתי והנה צלול לחם שערים מתהפך במחנה מדין ויבא עד האהל ויכהו ויפל ויהפכהו למעלה ונפל האהל׃ ");
INSERT INTO heb_vpl VALUES ("JG7_14","008_7_14","JDG","7","14","14","ויען רעהו ויאמר אין זאת בלתי אם חרב גדעון בן יואש איש ישראל נתן האלהים בידו את מדין ואת כל המחנה׃ ");
INSERT INTO heb_vpl VALUES ("JG7_15","008_7_15","JDG","7","15","15","ויהי כשמע גדעון את מספר החלום ואת שברו וישתחו וישב אל מחנה ישראל ויאמר קומו כי נתן יהוה בידכם את מחנה מדין׃ ");
INSERT INTO heb_vpl VALUES ("JG7_16","008_7_16","JDG","7","16","16","ויחץ את שלש מאות האיש שלשה ראשים ויתן שופרות ביד כלם וכדים רקים ולפדים בתוך הכדים׃ ");
INSERT INTO heb_vpl VALUES ("JG7_17","008_7_17","JDG","7","17","17","ויאמר אליהם ממני תראו וכן תעשו והנה אנכי בא בקצה המחנה והיה כאשר אעשה כן תעשון׃ ");
INSERT INTO heb_vpl VALUES ("JG7_18","008_7_18","JDG","7","18","18","ותקעתי בשופר אנכי וכל אשר אתי ותקעתם בשופרות גם אתם סביבות כל המחנה ואמרתם ליהוה ולגדעון׃ ");
INSERT INTO heb_vpl VALUES ("JG7_19","008_7_19","JDG","7","19","19","ויבא גדעון ומאה איש אשר אתו בקצה המחנה ראש האשמרת התיכונה אך הקם הקימו את השמרים ויתקעו בשופרות ונפוץ הכדים אשר בידם׃ ");
INSERT INTO heb_vpl VALUES ("JG7_20","008_7_20","JDG","7","20","20","ויתקעו שלשת הראשים בשופרות וישברו הכדים ויחזיקו ביד שמאולם בלפדים וביד ימינם השופרות לתקוע ויקראו חרב ליהוה ולגדעון׃ ");
INSERT INTO heb_vpl VALUES ("JG7_21","008_7_21","JDG","7","21","21","ויעמדו איש תחתיו סביב למחנה וירץ כל המחנה ויריעו ויניסו׃ ");
INSERT INTO heb_vpl VALUES ("JG7_22","008_7_22","JDG","7","22","22","ויתקעו שלש מאות השופרות וישם יהוה את חרב איש ברעהו ובכל המחנה וינס המחנה עד בית השטה צררתה עד שפת אבל מחולה על טבת׃ ");
INSERT INTO heb_vpl VALUES ("JG7_23","008_7_23","JDG","7","23","23","ויצעק איש ישראל מנפתלי ומן אשר ומן כל מנשה וירדפו אחרי מדין׃ ");
INSERT INTO heb_vpl VALUES ("JG7_24","008_7_24","JDG","7","24","24","ומלאכים שלח גדעון בכל הר אפרים לאמר רדו לקראת מדין ולכדו להם את המים עד בית ברה ואת הירדן ויצעק כל איש אפרים וילכדו את המים עד בית ברה ואת הירדן׃ ");
INSERT INTO heb_vpl VALUES ("JG7_25","008_7_25","JDG","7","25","25","וילכדו שני שרי מדין את ערב ואת זאב ויהרגו את עורב בצור עורב ואת זאב הרגו ביקב זאב וירדפו אל מדין וראש ערב וזאב הביאו אל גדעון מעבר לירדן׃ ");
INSERT INTO heb_vpl VALUES ("JG8_1","008_8_1","JDG","8","1","1","ויאמרו אליו איש אפרים מה הדבר הזה עשית לנו לבלתי קראות לנו כי הלכת להלחם במדין ויריבון אתו בחזקה׃ ");
INSERT INTO heb_vpl VALUES ("JG8_2","008_8_2","JDG","8","2","2","ויאמר אליהם מה עשיתי עתה ככם הלוא טוב עללות אפרים מבציר אביעזר׃ ");
INSERT INTO heb_vpl VALUES ("JG8_3","008_8_3","JDG","8","3","3","בידכם נתן אלהים את שרי מדין את ערב ואת זאב ומה יכלתי עשות ככם אז רפתה רוחם מעליו בדברו הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("JG8_4","008_8_4","JDG","8","4","4","ויבא גדעון הירדנה עבר הוא ושלש מאות האיש אשר אתו עיפים ורדפים׃ ");
INSERT INTO heb_vpl VALUES ("JG8_5","008_8_5","JDG","8","5","5","ויאמר לאנשי סכות תנו נא ככרות לחם לעם אשר ברגלי כי עיפים הם ואנכי רדף אחרי זבח וצלמנע מלכי מדין׃ ");
INSERT INTO heb_vpl VALUES ("JG8_6","008_8_6","JDG","8","6","6","ויאמר שרי סכות הכף זבח וצלמנע עתה בידך כי נתן לצבאך לחם׃ ");
INSERT INTO heb_vpl VALUES ("JG8_7","008_8_7","JDG","8","7","7","ויאמר גדעון לכן בתת יהוה את זבח ואת צלמנע בידי ודשתי את בשרכם את קוצי המדבר ואת הברקנים׃ ");
INSERT INTO heb_vpl VALUES ("JG8_8","008_8_8","JDG","8","8","8","ויעל משם פנואל וידבר אליהם כזאת ויענו אותו אנשי פנואל כאשר ענו אנשי סכות׃ ");
INSERT INTO heb_vpl VALUES ("JG8_9","008_8_9","JDG","8","9","9","ויאמר גם לאנשי פנואל לאמר בשובי בשלום אתץ את המגדל הזה׃ ");
INSERT INTO heb_vpl VALUES ("JG8_10","008_8_10","JDG","8","10","10","וזבח וצלמנע בקרקר ומחניהם עמם כחמשת עשר אלף כל הנותרים מכל מחנה בני קדם והנפלים מאה ועשרים אלף איש שלף חרב׃ ");
INSERT INTO heb_vpl VALUES ("JG8_11","008_8_11","JDG","8","11","11","ויעל גדעון דרך השכוני באהלים מקדם לנבח ויגבהה ויך את המחנה והמחנה היה בטח׃ ");
INSERT INTO heb_vpl VALUES ("JG8_12","008_8_12","JDG","8","12","12","וינוסו זבח וצלמנע וירדף אחריהם וילכד את שני מלכי מדין את זבח ואת צלמנע וכל המחנה החריד׃ ");
INSERT INTO heb_vpl VALUES ("JG8_13","008_8_13","JDG","8","13","13","וישב גדעון בן יואש מן המלחמה מלמעלה החרס׃ ");
INSERT INTO heb_vpl VALUES ("JG8_14","008_8_14","JDG","8","14","14","וילכד נער מאנשי סכות וישאלהו ויכתב אליו את שרי סכות ואת זקניה שבעים ושבעה איש׃ ");
INSERT INTO heb_vpl VALUES ("JG8_15","008_8_15","JDG","8","15","15","ויבא אל אנשי סכות ויאמר הנה זבח וצלמנע אשר חרפתם אותי לאמר הכף זבח וצלמנע עתה בידך כי נתן לאנשיך היעפים לחם׃ ");
INSERT INTO heb_vpl VALUES ("JG8_16","008_8_16","JDG","8","16","16","ויקח את זקני העיר ואת קוצי המדבר ואת הברקנים וידע בהם את אנשי סכות׃ ");
INSERT INTO heb_vpl VALUES ("JG8_17","008_8_17","JDG","8","17","17","ואת מגדל פנואל נתץ ויהרג את אנשי העיר׃ ");
INSERT INTO heb_vpl VALUES ("JG8_18","008_8_18","JDG","8","18","18","ויאמר אל זבח ואל צלמנע איפה האנשים אשר הרגתם בתבור ויאמרו כמוך כמוהם אחד כתאר בני המלך׃ ");
INSERT INTO heb_vpl VALUES ("JG8_19","008_8_19","JDG","8","19","19","ויאמר אחי בני אמי הם חי יהוה לו החיתם אותם לא הרגתי אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JG8_20","008_8_20","JDG","8","20","20","ויאמר ליתר בכורו קום הרג אותם ולא שלף הנער חרבו כי ירא כי עודנו נער׃ ");
INSERT INTO heb_vpl VALUES ("JG8_21","008_8_21","JDG","8","21","21","ויאמר זבח וצלמנע קום אתה ופגע בנו כי כאיש גבורתו ויקם גדעון ויהרג את זבח ואת צלמנע ויקח את השהרנים אשר בצוארי גמליהם׃ ");
INSERT INTO heb_vpl VALUES ("JG8_22","008_8_22","JDG","8","22","22","ויאמרו איש ישראל אל גדעון משל בנו גם אתה גם בנך גם בן בנך כי הושעתנו מיד מדין׃ ");
INSERT INTO heb_vpl VALUES ("JG8_23","008_8_23","JDG","8","23","23","ויאמר אלהם גדעון לא אמשל אני בכם ולא ימשל בני בכם יהוה ימשל בכם׃ ");
INSERT INTO heb_vpl VALUES ("JG8_24","008_8_24","JDG","8","24","24","ויאמר אלהם גדעון אשאלה מכם שאלה ותנו לי איש נזם שללו כי נזמי זהב להם כי ישמעאלים הם׃ ");
INSERT INTO heb_vpl VALUES ("JG8_25","008_8_25","JDG","8","25","25","ויאמרו נתון נתן ויפרשו את השמלה וישליכו שמה איש נזם שללו׃ ");
INSERT INTO heb_vpl VALUES ("JG8_26","008_8_26","JDG","8","26","26","ויהי משקל נזמי הזהב אשר שאל אלף ושבע מאות זהב לבד מן השהרנים והנטפות ובגדי הארגמן שעל מלכי מדין ולבד מן הענקות אשר בצוארי גמליהם׃ ");
INSERT INTO heb_vpl VALUES ("JG8_27","008_8_27","JDG","8","27","27","ויעש אותו גדעון לאפוד ויצג אותו בעירו בעפרה ויזנו כל ישראל אחריו שם ויהי לגדעון ולביתו למוקש׃ ");
INSERT INTO heb_vpl VALUES ("JG8_28","008_8_28","JDG","8","28","28","ויכנע מדין לפני בני ישראל ולא יספו לשאת ראשם ותשקט הארץ ארבעים שנה בימי גדעון׃ ");
INSERT INTO heb_vpl VALUES ("JG8_29","008_8_29","JDG","8","29","29","וילך ירבעל בן יואש וישב בביתו׃ ");
INSERT INTO heb_vpl VALUES ("JG8_30","008_8_30","JDG","8","30","30","ולגדעון היו שבעים בנים יצאי ירכו כי נשים רבות היו לו׃ ");
INSERT INTO heb_vpl VALUES ("JG8_31","008_8_31","JDG","8","31","31","ופילגשו אשר בשכם ילדה לו גם היא בן וישם את שמו אבימלך׃ ");
INSERT INTO heb_vpl VALUES ("JG8_32","008_8_32","JDG","8","32","32","וימת גדעון בן יואש בשיבה טובה ויקבר בקבר יואש אביו בעפרה אבי העזרי׃ ");
INSERT INTO heb_vpl VALUES ("JG8_33","008_8_33","JDG","8","33","33","ויהי כאשר מת גדעון וישובו בני ישראל ויזנו אחרי הבעלים וישימו להם בעל ברית לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JG8_34","008_8_34","JDG","8","34","34","ולא זכרו בני ישראל את יהוה אלהיהם המציל אותם מיד כל איביהם מסביב׃ ");
INSERT INTO heb_vpl VALUES ("JG8_35","008_8_35","JDG","8","35","35","ולא עשו חסד עם בית ירבעל גדעון ככל הטובה אשר עשה עם ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG9_1","008_9_1","JDG","9","1","1","וילך אבימלך בן ירבעל שכמה אל אחי אמו וידבר אליהם ואל כל משפחת בית אבי אמו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JG9_2","008_9_2","JDG","9","2","2","דברו נא באזני כל בעלי שכם מה טוב לכם המשל בכם שבעים איש כל בני ירבעל אם משל בכם איש אחד וזכרתם כי עצמכם ובשרכם אני׃ ");
INSERT INTO heb_vpl VALUES ("JG9_3","008_9_3","JDG","9","3","3","וידברו אחי אמו עליו באזני כל בעלי שכם את כל הדברים האלה ויט לבם אחרי אבימלך כי אמרו אחינו הוא׃ ");
INSERT INTO heb_vpl VALUES ("JG9_4","008_9_4","JDG","9","4","4","ויתנו לו שבעים כסף מבית בעל ברית וישכר בהם אבימלך אנשים ריקים ופחזים וילכו אחריו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_5","008_9_5","JDG","9","5","5","ויבא בית אביו עפרתה ויהרג את אחיו בני ירבעל שבעים איש על אבן אחת ויותר יותם בן ירבעל הקטן כי נחבא׃ ");
INSERT INTO heb_vpl VALUES ("JG9_6","008_9_6","JDG","9","6","6","ויאספו כל בעלי שכם וכל בית מלוא וילכו וימליכו את אבימלך למלך עם אלון מצב אשר בשכם׃ ");
INSERT INTO heb_vpl VALUES ("JG9_7","008_9_7","JDG","9","7","7","ויגדו ליותם וילך ויעמד בראש הר גרזים וישא קולו ויקרא ויאמר להם שמעו אלי בעלי שכם וישמע אליכם אלהים׃ ");
INSERT INTO heb_vpl VALUES ("JG9_8","008_9_8","JDG","9","8","8","הלוך הלכו העצים למשח עליהם מלך ויאמרו לזית מלוכה עלינו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_9","008_9_9","JDG","9","9","9","ויאמר להם הזית החדלתי את דשני אשר בי יכבדו אלהים ואנשים והלכתי לנוע על העצים׃ ");
INSERT INTO heb_vpl VALUES ("JG9_10","008_9_10","JDG","9","10","10","ויאמרו העצים לתאנה לכי את מלכי עלינו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_11","008_9_11","JDG","9","11","11","ותאמר להם התאנה החדלתי את מתקי ואת תנובתי הטובה והלכתי לנוע על העצים׃ ");
INSERT INTO heb_vpl VALUES ("JG9_12","008_9_12","JDG","9","12","12","ויאמרו העצים לגפן לכי את מלוכי עלינו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_13","008_9_13","JDG","9","13","13","ותאמר להם הגפן החדלתי את תירושי המשמח אלהים ואנשים והלכתי לנוע על העצים׃ ");
INSERT INTO heb_vpl VALUES ("JG9_14","008_9_14","JDG","9","14","14","ויאמרו כל העצים אל האטד לך אתה מלך עלינו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_15","008_9_15","JDG","9","15","15","ויאמר האטד אל העצים אם באמת אתם משחים אתי למלך עליכם באו חסו בצלי ואם אין תצא אש מן האטד ותאכל את ארזי הלבנון׃ ");
INSERT INTO heb_vpl VALUES ("JG9_16","008_9_16","JDG","9","16","16","ועתה אם באמת ובתמים עשיתם ותמליכו את אבימלך ואם טובה עשיתם עם ירבעל ועם ביתו ואם כגמול ידיו עשיתם לו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_17","008_9_17","JDG","9","17","17","אשר נלחם אבי עליכם וישלך את נפשו מנגד ויצל אתכם מיד מדין׃ ");
INSERT INTO heb_vpl VALUES ("JG9_18","008_9_18","JDG","9","18","18","ואתם קמתם על בית אבי היום ותהרגו את בניו שבעים איש על אבן אחת ותמליכו את אבימלך בן אמתו על בעלי שכם כי אחיכם הוא׃ ");
INSERT INTO heb_vpl VALUES ("JG9_19","008_9_19","JDG","9","19","19","ואם באמת ובתמים עשיתם עם ירבעל ועם ביתו היום הזה שמחו באבימלך וישמח גם הוא בכם׃ ");
INSERT INTO heb_vpl VALUES ("JG9_20","008_9_20","JDG","9","20","20","ואם אין תצא אש מאבימלך ותאכל את בעלי שכם ואת בית מלוא ותצא אש מבעלי שכם ומבית מלוא ותאכל את אבימלך׃ ");
INSERT INTO heb_vpl VALUES ("JG9_21","008_9_21","JDG","9","21","21","וינס יותם ויברח וילך בארה וישב שם מפני אבימלך אחיו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_22","008_9_22","JDG","9","22","22","וישר אבימלך על ישראל שלש שנים׃ ");
INSERT INTO heb_vpl VALUES ("JG9_23","008_9_23","JDG","9","23","23","וישלח אלהים רוח רעה בין אבימלך ובין בעלי שכם ויבגדו בעלי שכם באבימלך׃ ");
INSERT INTO heb_vpl VALUES ("JG9_24","008_9_24","JDG","9","24","24","לבוא חמס שבעים בני ירבעל ודמם לשום על אבימלך אחיהם אשר הרג אותם ועל בעלי שכם אשר חזקו את ידיו להרג את אחיו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_25","008_9_25","JDG","9","25","25","וישימו לו בעלי שכם מארבים על ראשי ההרים ויגזלו את כל אשר יעבר עליהם בדרך ויגד לאבימלך׃ ");
INSERT INTO heb_vpl VALUES ("JG9_26","008_9_26","JDG","9","26","26","ויבא געל בן עבד ואחיו ויעברו בשכם ויבטחו בו בעלי שכם׃ ");
INSERT INTO heb_vpl VALUES ("JG9_27","008_9_27","JDG","9","27","27","ויצאו השדה ויבצרו את כרמיהם וידרכו ויעשו הלולים ויבאו בית אלהיהם ויאכלו וישתו ויקללו את אבימלך׃ ");
INSERT INTO heb_vpl VALUES ("JG9_28","008_9_28","JDG","9","28","28","ויאמר געל בן עבד מי אבימלך ומי שכם כי נעבדנו הלא בן ירבעל וזבל פקידו עבדו את אנשי חמור אבי שכם ומדוע נעבדנו אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_29","008_9_29","JDG","9","29","29","ומי יתן את העם הזה בידי ואסירה את אבימלך ויאמר לאבימלך רבה צבאך וצאה׃ ");
INSERT INTO heb_vpl VALUES ("JG9_30","008_9_30","JDG","9","30","30","וישמע זבל שר העיר את דברי געל בן עבד ויחר אפו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_31","008_9_31","JDG","9","31","31","וישלח מלאכים אל אבימלך בתרמה לאמר הנה געל בן עבד ואחיו באים שכמה והנם צרים את העיר עליך׃ ");
INSERT INTO heb_vpl VALUES ("JG9_32","008_9_32","JDG","9","32","32","ועתה קום לילה אתה והעם אשר אתך וארב בשדה׃ ");
INSERT INTO heb_vpl VALUES ("JG9_33","008_9_33","JDG","9","33","33","והיה בבקר כזרח השמש תשכים ופשטת על העיר והנה הוא והעם אשר אתו יצאים אליך ועשית לו כאשר תמצא ידך׃ ");
INSERT INTO heb_vpl VALUES ("JG9_34","008_9_34","JDG","9","34","34","ויקם אבימלך וכל העם אשר עמו לילה ויארבו על שכם ארבעה ראשים׃ ");
INSERT INTO heb_vpl VALUES ("JG9_35","008_9_35","JDG","9","35","35","ויצא געל בן עבד ויעמד פתח שער העיר ויקם אבימלך והעם אשר אתו מן המארב׃ ");
INSERT INTO heb_vpl VALUES ("JG9_36","008_9_36","JDG","9","36","36","וירא געל את העם ויאמר אל זבל הנה עם יורד מראשי ההרים ויאמר אליו זבל את צל ההרים אתה ראה כאנשים׃ ");
INSERT INTO heb_vpl VALUES ("JG9_37","008_9_37","JDG","9","37","37","ויסף עוד געל לדבר ויאמר הנה עם יורדים מעם טבור הארץ וראש אחד בא מדרך אלון מעוננים׃ ");
INSERT INTO heb_vpl VALUES ("JG9_38","008_9_38","JDG","9","38","38","ויאמר אליו זבל איה אפוא פיך אשר תאמר מי אבימלך כי נעבדנו הלא זה העם אשר מאסתה בו צא נא עתה והלחם בו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_39","008_9_39","JDG","9","39","39","ויצא געל לפני בעלי שכם וילחם באבימלך׃ ");
INSERT INTO heb_vpl VALUES ("JG9_40","008_9_40","JDG","9","40","40","וירדפהו אבימלך וינס מפניו ויפלו חללים רבים עד פתח השער׃ ");
INSERT INTO heb_vpl VALUES ("JG9_41","008_9_41","JDG","9","41","41","וישב אבימלך בארומה ויגרש זבל את געל ואת אחיו משבת בשכם׃ ");
INSERT INTO heb_vpl VALUES ("JG9_42","008_9_42","JDG","9","42","42","ויהי ממחרת ויצא העם השדה ויגדו לאבימלך׃ ");
INSERT INTO heb_vpl VALUES ("JG9_43","008_9_43","JDG","9","43","43","ויקח את העם ויחצם לשלשה ראשים ויארב בשדה וירא והנה העם יצא מן העיר ויקם עליהם ויכם׃ ");
INSERT INTO heb_vpl VALUES ("JG9_44","008_9_44","JDG","9","44","44","ואבימלך והראשים אשר עמו פשטו ויעמדו פתח שער העיר ושני הראשים פשטו על כל אשר בשדה ויכום׃ ");
INSERT INTO heb_vpl VALUES ("JG9_45","008_9_45","JDG","9","45","45","ואבימלך נלחם בעיר כל היום ההוא וילכד את העיר ואת העם אשר בה הרג ויתץ את העיר ויזרעה מלח׃ ");
INSERT INTO heb_vpl VALUES ("JG9_46","008_9_46","JDG","9","46","46","וישמעו כל בעלי מגדל שכם ויבאו אל צריח בית אל ברית׃ ");
INSERT INTO heb_vpl VALUES ("JG9_47","008_9_47","JDG","9","47","47","ויגד לאבימלך כי התקבצו כל בעלי מגדל שכם׃ ");
INSERT INTO heb_vpl VALUES ("JG9_48","008_9_48","JDG","9","48","48","ויעל אבימלך הר צלמון הוא וכל העם אשר אתו ויקח אבימלך את הקרדמות בידו ויכרת שוכת עצים וישאה וישם על שכמו ויאמר אל העם אשר עמו מה ראיתם עשיתי מהרו עשו כמוני׃ ");
INSERT INTO heb_vpl VALUES ("JG9_49","008_9_49","JDG","9","49","49","ויכרתו גם כל העם איש שוכה וילכו אחרי אבימלך וישימו על הצריח ויציתו עליהם את הצריח באש וימתו גם כל אנשי מגדל שכם כאלף איש ואשה׃ ");
INSERT INTO heb_vpl VALUES ("JG9_50","008_9_50","JDG","9","50","50","וילך אבימלך אל תבץ ויחן בתבץ וילכדה׃ ");
INSERT INTO heb_vpl VALUES ("JG9_51","008_9_51","JDG","9","51","51","ומגדל עז היה בתוך העיר וינסו שמה כל האנשים והנשים וכל בעלי העיר ויסגרו בעדם ויעלו על גג המגדל׃ ");
INSERT INTO heb_vpl VALUES ("JG9_52","008_9_52","JDG","9","52","52","ויבא אבימלך עד המגדל וילחם בו ויגש עד פתח המגדל לשרפו באש׃ ");
INSERT INTO heb_vpl VALUES ("JG9_53","008_9_53","JDG","9","53","53","ותשלך אשה אחת פלח רכב על ראש אבימלך ותרץ את גלגלתו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_54","008_9_54","JDG","9","54","54","ויקרא מהרה אל הנער נשא כליו ויאמר לו שלף חרבך ומותתני פן יאמרו לי אשה הרגתהו וידקרהו נערו וימת׃ ");
INSERT INTO heb_vpl VALUES ("JG9_55","008_9_55","JDG","9","55","55","ויראו איש ישראל כי מת אבימלך וילכו איש למקמו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_56","008_9_56","JDG","9","56","56","וישב אלהים את רעת אבימלך אשר עשה לאביו להרג את שבעים אחיו׃ ");
INSERT INTO heb_vpl VALUES ("JG9_57","008_9_57","JDG","9","57","57","ואת כל רעת אנשי שכם השיב אלהים בראשם ותבא אליהם קללת יותם בן ירבעל׃ ");
INSERT INTO heb_vpl VALUES ("JG10_1","008_10_1","JDG","10","1","1","ויקם אחרי אבימלך להושיע את ישראל תולע בן פואה בן דודו איש יששכר והוא ישב בשמיר בהר אפרים׃ ");
INSERT INTO heb_vpl VALUES ("JG10_2","008_10_2","JDG","10","2","2","וישפט את ישראל עשרים ושלש שנה וימת ויקבר בשמיר׃ ");
INSERT INTO heb_vpl VALUES ("JG10_3","008_10_3","JDG","10","3","3","ויקם אחריו יאיר הגלעדי וישפט את ישראל עשרים ושתים שנה׃ ");
INSERT INTO heb_vpl VALUES ("JG10_4","008_10_4","JDG","10","4","4","ויהי לו שלשים בנים רכבים על שלשים עירים ושלשים עירים להם להם יקראו חות יאיר עד היום הזה אשר בארץ הגלעד׃ ");
INSERT INTO heb_vpl VALUES ("JG10_5","008_10_5","JDG","10","5","5","וימת יאיר ויקבר בקמון׃ ");
INSERT INTO heb_vpl VALUES ("JG10_6","008_10_6","JDG","10","6","6","ויספו בני ישראל לעשות הרע בעיני יהוה ויעבדו את הבעלים ואת העשתרות ואת אלהי ארם ואת אלהי צידון ואת אלהי מואב ואת אלהי בני עמון ואת אלהי פלשתים ויעזבו את יהוה ולא עבדוהו׃ ");
INSERT INTO heb_vpl VALUES ("JG10_7","008_10_7","JDG","10","7","7","ויחר אף יהוה בישראל וימכרם ביד פלשתים וביד בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JG10_8","008_10_8","JDG","10","8","8","וירעצו וירצצו את בני ישראל בשנה ההיא שמנה עשרה שנה את כל בני ישראל אשר בעבר הירדן בארץ האמרי אשר בגלעד׃ ");
INSERT INTO heb_vpl VALUES ("JG10_9","008_10_9","JDG","10","9","9","ויעברו בני עמון את הירדן להלחם גם ביהודה ובבנימין ובבית אפרים ותצר לישראל מאד׃ ");
INSERT INTO heb_vpl VALUES ("JG10_10","008_10_10","JDG","10","10","10","ויזעקו בני ישראל אל יהוה לאמר חטאנו לך וכי עזבנו את אלהינו ונעבד את הבעלים׃ ");
INSERT INTO heb_vpl VALUES ("JG10_11","008_10_11","JDG","10","11","11","ויאמר יהוה אל בני ישראל הלא ממצרים ומן האמרי ומן בני עמון ומן פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("JG10_12","008_10_12","JDG","10","12","12","וצידונים ועמלק ומעון לחצו אתכם ותצעקו אלי ואושיעה אתכם מידם׃ ");
INSERT INTO heb_vpl VALUES ("JG10_13","008_10_13","JDG","10","13","13","ואתם עזבתם אותי ותעבדו אלהים אחרים לכן לא אוסיף להושיע אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JG10_14","008_10_14","JDG","10","14","14","לכו וזעקו אל האלהים אשר בחרתם בם המה יושיעו לכם בעת צרתכם׃ ");
INSERT INTO heb_vpl VALUES ("JG10_15","008_10_15","JDG","10","15","15","ויאמרו בני ישראל אל יהוה חטאנו עשה אתה לנו ככל הטוב בעיניך אך הצילנו נא היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JG10_16","008_10_16","JDG","10","16","16","ויסירו את אלהי הנכר מקרבם ויעבדו את יהוה ותקצר נפשו בעמל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG10_17","008_10_17","JDG","10","17","17","ויצעקו בני עמון ויחנו בגלעד ויאספו בני ישראל ויחנו במצפה׃ ");
INSERT INTO heb_vpl VALUES ("JG10_18","008_10_18","JDG","10","18","18","ויאמרו העם שרי גלעד איש אל רעהו מי האיש אשר יחל להלחם בבני עמון יהיה לראש לכל ישבי גלעד׃ ");
INSERT INTO heb_vpl VALUES ("JG11_1","008_11_1","JDG","11","1","1","ויפתח הגלעדי היה גבור חיל והוא בן אשה זונה ויולד גלעד את יפתח׃ ");
INSERT INTO heb_vpl VALUES ("JG11_2","008_11_2","JDG","11","2","2","ותלד אשת גלעד לו בנים ויגדלו בני האשה ויגרשו את יפתח ויאמרו לו לא תנחל בבית אבינו כי בן אשה אחרת אתה׃ ");
INSERT INTO heb_vpl VALUES ("JG11_3","008_11_3","JDG","11","3","3","ויברח יפתח מפני אחיו וישב בארץ טוב ויתלקטו אל יפתח אנשים ריקים ויצאו עמו׃ ");
INSERT INTO heb_vpl VALUES ("JG11_4","008_11_4","JDG","11","4","4","ויהי מימים וילחמו בני עמון עם ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG11_5","008_11_5","JDG","11","5","5","ויהי כאשר נלחמו בני עמון עם ישראל וילכו זקני גלעד לקחת את יפתח מארץ טוב׃ ");
INSERT INTO heb_vpl VALUES ("JG11_6","008_11_6","JDG","11","6","6","ויאמרו ליפתח לכה והייתה לנו לקצין ונלחמה בבני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JG11_7","008_11_7","JDG","11","7","7","ויאמר יפתח לזקני גלעד הלא אתם שנאתם אותי ותגרשוני מבית אבי ומדוע באתם אלי עתה כאשר צר לכם׃ ");
INSERT INTO heb_vpl VALUES ("JG11_8","008_11_8","JDG","11","8","8","ויאמרו זקני גלעד אל יפתח לכן עתה שבנו אליך והלכת עמנו ונלחמת בבני עמון והיית לנו לראש לכל ישבי גלעד׃ ");
INSERT INTO heb_vpl VALUES ("JG11_9","008_11_9","JDG","11","9","9","ויאמר יפתח אל זקני גלעד אם משיבים אתם אותי להלחם בבני עמון ונתן יהוה אותם לפני אנכי אהיה לכם לראש׃ ");
INSERT INTO heb_vpl VALUES ("JG11_10","008_11_10","JDG","11","10","10","ויאמרו זקני גלעד אל יפתח יהוה יהיה שמע בינותינו אם לא כדברך כן נעשה׃ ");
INSERT INTO heb_vpl VALUES ("JG11_11","008_11_11","JDG","11","11","11","וילך יפתח עם זקני גלעד וישימו העם אותו עליהם לראש ולקצין וידבר יפתח את כל דבריו לפני יהוה במצפה׃ ");
INSERT INTO heb_vpl VALUES ("JG11_12","008_11_12","JDG","11","12","12","וישלח יפתח מלאכים אל מלך בני עמון לאמר מה לי ולך כי באת אלי להלחם בארצי׃ ");
INSERT INTO heb_vpl VALUES ("JG11_13","008_11_13","JDG","11","13","13","ויאמר מלך בני עמון אל מלאכי יפתח כי לקח ישראל את ארצי בעלותו ממצרים מארנון ועד היבק ועד הירדן ועתה השיבה אתהן בשלום׃ ");
INSERT INTO heb_vpl VALUES ("JG11_14","008_11_14","JDG","11","14","14","ויוסף עוד יפתח וישלח מלאכים אל מלך בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JG11_15","008_11_15","JDG","11","15","15","ויאמר לו כה אמר יפתח לא לקח ישראל את ארץ מואב ואת ארץ בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JG11_16","008_11_16","JDG","11","16","16","כי בעלותם ממצרים וילך ישראל במדבר עד ים סוף ויבא קדשה׃ ");
INSERT INTO heb_vpl VALUES ("JG11_17","008_11_17","JDG","11","17","17","וישלח ישראל מלאכים אל מלך אדום לאמר אעברה נא בארצך ולא שמע מלך אדום וגם אל מלך מואב שלח ולא אבה וישב ישראל בקדש׃ ");
INSERT INTO heb_vpl VALUES ("JG11_18","008_11_18","JDG","11","18","18","וילך במדבר ויסב את ארץ אדום ואת ארץ מואב ויבא ממזרח שמש לארץ מואב ויחנון בעבר ארנון ולא באו בגבול מואב כי ארנון גבול מואב׃ ");
INSERT INTO heb_vpl VALUES ("JG11_19","008_11_19","JDG","11","19","19","וישלח ישראל מלאכים אל סיחון מלך האמרי מלך חשבון ויאמר לו ישראל נעברה נא בארצך עד מקומי׃ ");
INSERT INTO heb_vpl VALUES ("JG11_20","008_11_20","JDG","11","20","20","ולא האמין סיחון את ישראל עבר בגבלו ויאסף סיחון את כל עמו ויחנו ביהצה וילחם עם ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG11_21","008_11_21","JDG","11","21","21","ויתן יהוה אלהי ישראל את סיחון ואת כל עמו ביד ישראל ויכום ויירש ישראל את כל ארץ האמרי יושב הארץ ההיא׃ ");
INSERT INTO heb_vpl VALUES ("JG11_22","008_11_22","JDG","11","22","22","ויירשו את כל גבול האמרי מארנון ועד היבק ומן המדבר ועד הירדן׃ ");
INSERT INTO heb_vpl VALUES ("JG11_23","008_11_23","JDG","11","23","23","ועתה יהוה אלהי ישראל הוריש את האמרי מפני עמו ישראל ואתה תירשנו׃ ");
INSERT INTO heb_vpl VALUES ("JG11_24","008_11_24","JDG","11","24","24","הלא את אשר יורישך כמוש אלהיך אותו תירש ואת כל אשר הוריש יהוה אלהינו מפנינו אותו נירש׃ ");
INSERT INTO heb_vpl VALUES ("JG11_25","008_11_25","JDG","11","25","25","ועתה הטוב טוב אתה מבלק בן צפור מלך מואב הרוב רב עם ישראל אם נלחם נלחם בם׃ ");
INSERT INTO heb_vpl VALUES ("JG11_26","008_11_26","JDG","11","26","26","בשבת ישראל בחשבון ובבנותיה ובערעור ובבנותיה ובכל הערים אשר על ידי ארנון שלש מאות שנה ומדוע לא הצלתם בעת ההיא׃ ");
INSERT INTO heb_vpl VALUES ("JG11_27","008_11_27","JDG","11","27","27","ואנכי לא חטאתי לך ואתה עשה אתי רעה להלחם בי ישפט יהוה השפט היום בין בני ישראל ובין בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JG11_28","008_11_28","JDG","11","28","28","ולא שמע מלך בני עמון אל דברי יפתח אשר שלח אליו׃ ");
INSERT INTO heb_vpl VALUES ("JG11_29","008_11_29","JDG","11","29","29","ותהי על יפתח רוח יהוה ויעבר את הגלעד ואת מנשה ויעבר את מצפה גלעד וממצפה גלעד עבר בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JG11_30","008_11_30","JDG","11","30","30","וידר יפתח נדר ליהוה ויאמר אם נתון תתן את בני עמון בידי׃ ");
INSERT INTO heb_vpl VALUES ("JG11_31","008_11_31","JDG","11","31","31","והיה היוצא אשר יצא מדלתי ביתי לקראתי בשובי בשלום מבני עמון והיה ליהוה והעליתהו עולה׃ ");
INSERT INTO heb_vpl VALUES ("JG11_32","008_11_32","JDG","11","32","32","ויעבר יפתח אל בני עמון להלחם בם ויתנם יהוה בידו׃ ");
INSERT INTO heb_vpl VALUES ("JG11_33","008_11_33","JDG","11","33","33","ויכם מערוער ועד בואך מנית עשרים עיר ועד אבל כרמים מכה גדולה מאד ויכנעו בני עמון מפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG11_34","008_11_34","JDG","11","34","34","ויבא יפתח המצפה אל ביתו והנה בתו יצאת לקראתו בתפים ובמחלות ורק היא יחידה אין לו ממנו בן או בת׃ ");
INSERT INTO heb_vpl VALUES ("JG11_35","008_11_35","JDG","11","35","35","ויהי כראותו אותה ויקרע את בגדיו ויאמר אהה בתי הכרע הכרעתני ואת היית בעכרי ואנכי פציתי פי אל יהוה ולא אוכל לשוב׃ ");
INSERT INTO heb_vpl VALUES ("JG11_36","008_11_36","JDG","11","36","36","ותאמר אליו אבי פציתה את פיך אל יהוה עשה לי כאשר יצא מפיך אחרי אשר עשה לך יהוה נקמות מאיביך מבני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JG11_37","008_11_37","JDG","11","37","37","ותאמר אל אביה יעשה לי הדבר הזה הרפה ממני שנים חדשים ואלכה וירדתי על ההרים ואבכה על בתולי אנכי ורעיתי׃ ");
INSERT INTO heb_vpl VALUES ("JG11_38","008_11_38","JDG","11","38","38","ויאמר לכי וישלח אותה שני חדשים ותלך היא ורעותיה ותבך על בתוליה על ההרים׃ ");
INSERT INTO heb_vpl VALUES ("JG11_39","008_11_39","JDG","11","39","39","ויהי מקץ שנים חדשים ותשב אל אביה ויעש לה את נדרו אשר נדר והיא לא ידעה איש ותהי חק בישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG11_40","008_11_40","JDG","11","40","40","מימים ימימה תלכנה בנות ישראל לתנות לבת יפתח הגלעדי ארבעת ימים בשנה׃ ");
INSERT INTO heb_vpl VALUES ("JG12_1","008_12_1","JDG","12","1","1","ויצעק איש אפרים ויעבר צפונה ויאמרו ליפתח מדוע עברת להלחם בבני עמון ולנו לא קראת ללכת עמך ביתך נשרף עליך באש׃ ");
INSERT INTO heb_vpl VALUES ("JG12_2","008_12_2","JDG","12","2","2","ויאמר יפתח אליהם איש ריב הייתי אני ועמי ובני עמון מאד ואזעק אתכם ולא הושעתם אותי מידם׃ ");
INSERT INTO heb_vpl VALUES ("JG12_3","008_12_3","JDG","12","3","3","ואראה כי אינך מושיע ואשימה נפשי בכפי ואעברה אל בני עמון ויתנם יהוה בידי ולמה עליתם אלי היום הזה להלחם בי׃ ");
INSERT INTO heb_vpl VALUES ("JG12_4","008_12_4","JDG","12","4","4","ויקבץ יפתח את כל אנשי גלעד וילחם את אפרים ויכו אנשי גלעד את אפרים כי אמרו פליטי אפרים אתם גלעד בתוך אפרים בתוך מנשה׃ ");
INSERT INTO heb_vpl VALUES ("JG12_5","008_12_5","JDG","12","5","5","וילכד גלעד את מעברות הירדן לאפרים והיה כי יאמרו פליטי אפרים אעברה ויאמרו לו אנשי גלעד האפרתי אתה ויאמר לא׃ ");
INSERT INTO heb_vpl VALUES ("JG12_6","008_12_6","JDG","12","6","6","ויאמרו לו אמר נא שבלת ויאמר סבלת ולא יכין לדבר כן ויאחזו אותו וישחטוהו אל מעברות הירדן ויפל בעת ההיא מאפרים ארבעים ושנים אלף׃ ");
INSERT INTO heb_vpl VALUES ("JG12_7","008_12_7","JDG","12","7","7","וישפט יפתח את ישראל שש שנים וימת יפתח הגלעדי ויקבר בערי גלעד׃ ");
INSERT INTO heb_vpl VALUES ("JG12_8","008_12_8","JDG","12","8","8","וישפט אחריו את ישראל אבצן מבית לחם׃ ");
INSERT INTO heb_vpl VALUES ("JG12_9","008_12_9","JDG","12","9","9","ויהי לו שלשים בנים ושלשים בנות שלח החוצה ושלשים בנות הביא לבניו מן החוץ וישפט את ישראל שבע שנים׃ ");
INSERT INTO heb_vpl VALUES ("JG12_10","008_12_10","JDG","12","10","10","וימת אבצן ויקבר בבית לחם׃ ");
INSERT INTO heb_vpl VALUES ("JG12_11","008_12_11","JDG","12","11","11","וישפט אחריו את ישראל אילון הזבולני וישפט את ישראל עשר שנים׃ ");
INSERT INTO heb_vpl VALUES ("JG12_12","008_12_12","JDG","12","12","12","וימת אילון הזבולני ויקבר באילון בארץ זבולן׃ ");
INSERT INTO heb_vpl VALUES ("JG12_13","008_12_13","JDG","12","13","13","וישפט אחריו את ישראל עבדון בן הלל הפרעתוני׃ ");
INSERT INTO heb_vpl VALUES ("JG12_14","008_12_14","JDG","12","14","14","ויהי לו ארבעים בנים ושלשים בני בנים רכבים על שבעים עירם וישפט את ישראל שמנה שנים׃ ");
INSERT INTO heb_vpl VALUES ("JG12_15","008_12_15","JDG","12","15","15","וימת עבדון בן הלל הפרעתוני ויקבר בפרעתון בארץ אפרים בהר העמלקי׃ ");
INSERT INTO heb_vpl VALUES ("JG13_1","008_13_1","JDG","13","1","1","ויספו בני ישראל לעשות הרע בעיני יהוה ויתנם יהוה ביד פלשתים ארבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("JG13_2","008_13_2","JDG","13","2","2","ויהי איש אחד מצרעה ממשפחת הדני ושמו מנוח ואשתו עקרה ולא ילדה׃ ");
INSERT INTO heb_vpl VALUES ("JG13_3","008_13_3","JDG","13","3","3","וירא מלאך יהוה אל האשה ויאמר אליה הנה נא את עקרה ולא ילדת והרית וילדת בן׃ ");
INSERT INTO heb_vpl VALUES ("JG13_4","008_13_4","JDG","13","4","4","ועתה השמרי נא ואל תשתי יין ושכר ואל תאכלי כל טמא׃ ");
INSERT INTO heb_vpl VALUES ("JG13_5","008_13_5","JDG","13","5","5","כי הנך הרה וילדת בן ומורה לא יעלה על ראשו כי נזיר אלהים יהיה הנער מן הבטן והוא יחל להושיע את ישראל מיד פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("JG13_6","008_13_6","JDG","13","6","6","ותבא האשה ותאמר לאישה לאמר איש האלהים בא אלי ומראהו כמראה מלאך האלהים נורא מאד ולא שאלתיהו אי מזה הוא ואת שמו לא הגיד לי׃ ");
INSERT INTO heb_vpl VALUES ("JG13_7","008_13_7","JDG","13","7","7","ויאמר לי הנך הרה וילדת בן ועתה אל תשתי יין ושכר ואל תאכלי כל טמאה כי נזיר אלהים יהיה הנער מן הבטן עד יום מותו׃ ");
INSERT INTO heb_vpl VALUES ("JG13_8","008_13_8","JDG","13","8","8","ויעתר מנוח אל יהוה ויאמר בי אדוני איש האלהים אשר שלחת יבוא נא עוד אלינו ויורנו מה נעשה לנער היולד׃ ");
INSERT INTO heb_vpl VALUES ("JG13_9","008_13_9","JDG","13","9","9","וישמע האלהים בקול מנוח ויבא מלאך האלהים עוד אל האשה והיא יושבת בשדה ומנוח אישה אין עמה׃ ");
INSERT INTO heb_vpl VALUES ("JG13_10","008_13_10","JDG","13","10","10","ותמהר האשה ותרץ ותגד לאישה ותאמר אליו הנה נראה אלי האיש אשר בא ביום אלי׃ ");
INSERT INTO heb_vpl VALUES ("JG13_11","008_13_11","JDG","13","11","11","ויקם וילך מנוח אחרי אשתו ויבא אל האיש ויאמר לו האתה האיש אשר דברת אל האשה ויאמר אני׃ ");
INSERT INTO heb_vpl VALUES ("JG13_12","008_13_12","JDG","13","12","12","ויאמר מנוח עתה יבא דבריך מה יהיה משפט הנער ומעשהו׃ ");
INSERT INTO heb_vpl VALUES ("JG13_13","008_13_13","JDG","13","13","13","ויאמר מלאך יהוה אל מנוח מכל אשר אמרתי אל האשה תשמר׃ ");
INSERT INTO heb_vpl VALUES ("JG13_14","008_13_14","JDG","13","14","14","מכל אשר יצא מגפן היין לא תאכל ויין ושכר אל תשת וכל טמאה אל תאכל כל אשר צויתיה תשמר׃ ");
INSERT INTO heb_vpl VALUES ("JG13_15","008_13_15","JDG","13","15","15","ויאמר מנוח אל מלאך יהוה נעצרה נא אותך ונעשה לפניך גדי עזים׃ ");
INSERT INTO heb_vpl VALUES ("JG13_16","008_13_16","JDG","13","16","16","ויאמר מלאך יהוה אל מנוח אם תעצרני לא אכל בלחמך ואם תעשה עלה ליהוה תעלנה כי לא ידע מנוח כי מלאך יהוה הוא׃ ");
INSERT INTO heb_vpl VALUES ("JG13_17","008_13_17","JDG","13","17","17","ויאמר מנוח אל מלאך יהוה מי שמך כי יבא דבריך וכבדנוך׃ ");
INSERT INTO heb_vpl VALUES ("JG13_18","008_13_18","JDG","13","18","18","ויאמר לו מלאך יהוה למה זה תשאל לשמי והוא פלאי׃ ");
INSERT INTO heb_vpl VALUES ("JG13_19","008_13_19","JDG","13","19","19","ויקח מנוח את גדי העזים ואת המנחה ויעל על הצור ליהוה ומפלא לעשות ומנוח ואשתו ראים׃ ");
INSERT INTO heb_vpl VALUES ("JG13_20","008_13_20","JDG","13","20","20","ויהי בעלות הלהב מעל המזבח השמימה ויעל מלאך יהוה בלהב המזבח ומנוח ואשתו ראים ויפלו על פניהם ארצה׃ ");
INSERT INTO heb_vpl VALUES ("JG13_21","008_13_21","JDG","13","21","21","ולא יסף עוד מלאך יהוה להראה אל מנוח ואל אשתו אז ידע מנוח כי מלאך יהוה הוא׃ ");
INSERT INTO heb_vpl VALUES ("JG13_22","008_13_22","JDG","13","22","22","ויאמר מנוח אל אשתו מות נמות כי אלהים ראינו׃ ");
INSERT INTO heb_vpl VALUES ("JG13_23","008_13_23","JDG","13","23","23","ותאמר לו אשתו לו חפץ יהוה להמיתנו לא לקח מידנו עלה ומנחה ולא הראנו את כל אלה וכעת לא השמיענו כזאת׃ ");
INSERT INTO heb_vpl VALUES ("JG13_24","008_13_24","JDG","13","24","24","ותלד האשה בן ותקרא את שמו שמשון ויגדל הנער ויברכהו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG13_25","008_13_25","JDG","13","25","25","ותחל רוח יהוה לפעמו במחנה דן בין צרעה ובין אשתאל׃ ");
INSERT INTO heb_vpl VALUES ("JG14_1","008_14_1","JDG","14","1","1","וירד שמשון תמנתה וירא אשה בתמנתה מבנות פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("JG14_2","008_14_2","JDG","14","2","2","ויעל ויגד לאביו ולאמו ויאמר אשה ראיתי בתמנתה מבנות פלשתים ועתה קחו אותה לי לאשה׃ ");
INSERT INTO heb_vpl VALUES ("JG14_3","008_14_3","JDG","14","3","3","ויאמר לו אביו ואמו האין בבנות אחיך ובכל עמי אשה כי אתה הולך לקחת אשה מפלשתים הערלים ויאמר שמשון אל אביו אותה קח לי כי היא ישרה בעיני׃ ");
INSERT INTO heb_vpl VALUES ("JG14_4","008_14_4","JDG","14","4","4","ואביו ואמו לא ידעו כי מיהוה היא כי תאנה הוא מבקש מפלשתים ובעת ההיא פלשתים משלים בישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG14_5","008_14_5","JDG","14","5","5","וירד שמשון ואביו ואמו תמנתה ויבאו עד כרמי תמנתה והנה כפיר אריות שאג לקראתו׃ ");
INSERT INTO heb_vpl VALUES ("JG14_6","008_14_6","JDG","14","6","6","ותצלח עליו רוח יהוה וישסעהו כשסע הגדי ומאומה אין בידו ולא הגיד לאביו ולאמו את אשר עשה׃ ");
INSERT INTO heb_vpl VALUES ("JG14_7","008_14_7","JDG","14","7","7","וירד וידבר לאשה ותישר בעיני שמשון׃ ");
INSERT INTO heb_vpl VALUES ("JG14_8","008_14_8","JDG","14","8","8","וישב מימים לקחתה ויסר לראות את מפלת האריה והנה עדת דבורים בגוית האריה ודבש׃ ");
INSERT INTO heb_vpl VALUES ("JG14_9","008_14_9","JDG","14","9","9","וירדהו אל כפיו וילך הלוך ואכל וילך אל אביו ואל אמו ויתן להם ויאכלו ולא הגיד להם כי מגוית האריה רדה הדבש׃ ");
INSERT INTO heb_vpl VALUES ("JG14_10","008_14_10","JDG","14","10","10","וירד אביהו אל האשה ויעש שם שמשון משתה כי כן יעשו הבחורים׃ ");
INSERT INTO heb_vpl VALUES ("JG14_11","008_14_11","JDG","14","11","11","ויהי כראותם אותו ויקחו שלשים מרעים ויהיו אתו׃ ");
INSERT INTO heb_vpl VALUES ("JG14_12","008_14_12","JDG","14","12","12","ויאמר להם שמשון אחודה נא לכם חידה אם הגד תגידו אותה לי שבעת ימי המשתה ומצאתם ונתתי לכם שלשים סדינים ושלשים חלפת בגדים׃ ");
INSERT INTO heb_vpl VALUES ("JG14_13","008_14_13","JDG","14","13","13","ואם לא תוכלו להגיד לי ונתתם אתם לי שלשים סדינים ושלשים חליפות בגדים ויאמרו לו חודה חידתך ונשמענה׃ ");
INSERT INTO heb_vpl VALUES ("JG14_14","008_14_14","JDG","14","14","14","ויאמר להם מהאכל יצא מאכל ומעז יצא מתוק ולא יכלו להגיד החידה שלשת ימים׃ ");
INSERT INTO heb_vpl VALUES ("JG14_15","008_14_15","JDG","14","15","15","ויהי ביום השביעי ויאמרו לאשת שמשון פתי את אישך ויגד לנו את החידה פן נשרף אותך ואת בית אביך באש הלירשנו קראתם לנו הלא׃ ");
INSERT INTO heb_vpl VALUES ("JG14_16","008_14_16","JDG","14","16","16","ותבך אשת שמשון עליו ותאמר רק שנאתני ולא אהבתני החידה חדת לבני עמי ולי לא הגדתה ויאמר לה הנה לאבי ולאמי לא הגדתי ולך אגיד׃ ");
INSERT INTO heb_vpl VALUES ("JG14_17","008_14_17","JDG","14","17","17","ותבך עליו שבעת הימים אשר היה להם המשתה ויהי ביום השביעי ויגד לה כי הציקתהו ותגד החידה לבני עמה׃ ");
INSERT INTO heb_vpl VALUES ("JG14_18","008_14_18","JDG","14","18","18","ויאמרו לו אנשי העיר ביום השביעי בטרם יבא החרסה מה מתוק מדבש ומה עז מארי ויאמר להם לולא חרשתם בעגלתי לא מצאתם חידתי׃ ");
INSERT INTO heb_vpl VALUES ("JG14_19","008_14_19","JDG","14","19","19","ותצלח עליו רוח יהוה וירד אשקלון ויך מהם שלשים איש ויקח את חליצותם ויתן החליפות למגידי החידה ויחר אפו ויעל בית אביהו׃ ");
INSERT INTO heb_vpl VALUES ("JG14_20","008_14_20","JDG","14","20","20","ותהי אשת שמשון למרעהו אשר רעה לו׃ ");
INSERT INTO heb_vpl VALUES ("JG15_1","008_15_1","JDG","15","1","1","ויהי מימים בימי קציר חטים ויפקד שמשון את אשתו בגדי עזים ויאמר אבאה אל אשתי החדרה ולא נתנו אביה לבוא׃ ");
INSERT INTO heb_vpl VALUES ("JG15_2","008_15_2","JDG","15","2","2","ויאמר אביה אמר אמרתי כי שנא שנאתה ואתננה למרעך הלא אחתה הקטנה טובה ממנה תהי נא לך תחתיה׃ ");
INSERT INTO heb_vpl VALUES ("JG15_3","008_15_3","JDG","15","3","3","ויאמר להם שמשון נקיתי הפעם מפלשתים כי עשה אני עמם רעה׃ ");
INSERT INTO heb_vpl VALUES ("JG15_4","008_15_4","JDG","15","4","4","וילך שמשון וילכד שלש מאות שועלים ויקח לפדים ויפן זנב אל זנב וישם לפיד אחד בין שני הזנבות בתוך׃ ");
INSERT INTO heb_vpl VALUES ("JG15_5","008_15_5","JDG","15","5","5","ויבער אש בלפידים וישלח בקמות פלשתים ויבער מגדיש ועד קמה ועד כרם זית׃ ");
INSERT INTO heb_vpl VALUES ("JG15_6","008_15_6","JDG","15","6","6","ויאמרו פלשתים מי עשה זאת ויאמרו שמשון חתן התמני כי לקח את אשתו ויתנה למרעהו ויעלו פלשתים וישרפו אותה ואת אביה באש׃ ");
INSERT INTO heb_vpl VALUES ("JG15_7","008_15_7","JDG","15","7","7","ויאמר להם שמשון אם תעשון כזאת כי אם נקמתי בכם ואחר אחדל׃ ");
INSERT INTO heb_vpl VALUES ("JG15_8","008_15_8","JDG","15","8","8","ויך אותם שוק על ירך מכה גדולה וירד וישב בסעיף סלע עיטם׃ ");
INSERT INTO heb_vpl VALUES ("JG15_9","008_15_9","JDG","15","9","9","ויעלו פלשתים ויחנו ביהודה וינטשו בלחי׃ ");
INSERT INTO heb_vpl VALUES ("JG15_10","008_15_10","JDG","15","10","10","ויאמרו איש יהודה למה עליתם עלינו ויאמרו לאסור את שמשון עלינו לעשות לו כאשר עשה לנו׃ ");
INSERT INTO heb_vpl VALUES ("JG15_11","008_15_11","JDG","15","11","11","וירדו שלשת אלפים איש מיהודה אל סעיף סלע עיטם ויאמרו לשמשון הלא ידעת כי משלים בנו פלשתים ומה זאת עשית לנו ויאמר להם כאשר עשו לי כן עשיתי להם׃ ");
INSERT INTO heb_vpl VALUES ("JG15_12","008_15_12","JDG","15","12","12","ויאמרו לו לאסרך ירדנו לתתך ביד פלשתים ויאמר להם שמשון השבעו לי פן תפגעון בי אתם׃ ");
INSERT INTO heb_vpl VALUES ("JG15_13","008_15_13","JDG","15","13","13","ויאמרו לו לאמר לא כי אסר נאסרך ונתנוך בידם והמת לא נמיתך ויאסרהו בשנים עבתים חדשים ויעלוהו מן הסלע׃ ");
INSERT INTO heb_vpl VALUES ("JG15_14","008_15_14","JDG","15","14","14","הוא בא עד לחי ופלשתים הריעו לקראתו ותצלח עליו רוח יהוה ותהיינה העבתים אשר על זרועותיו כפשתים אשר בערו באש וימסו אסוריו מעל ידיו׃ ");
INSERT INTO heb_vpl VALUES ("JG15_15","008_15_15","JDG","15","15","15","וימצא לחי חמור טריה וישלח ידו ויקחה ויך בה אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("JG15_16","008_15_16","JDG","15","16","16","ויאמר שמשון בלחי החמור חמור חמרתים בלחי החמור הכיתי אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("JG15_17","008_15_17","JDG","15","17","17","ויהי ככלתו לדבר וישלך הלחי מידו ויקרא למקום ההוא רמת לחי׃ ");
INSERT INTO heb_vpl VALUES ("JG15_18","008_15_18","JDG","15","18","18","ויצמא מאד ויקרא אל יהוה ויאמר אתה נתת ביד עבדך את התשועה הגדלה הזאת ועתה אמות בצמא ונפלתי ביד הערלים׃ ");
INSERT INTO heb_vpl VALUES ("JG15_19","008_15_19","JDG","15","19","19","ויבקע אלהים את המכתש אשר בלחי ויצאו ממנו מים וישת ותשב רוחו ויחי על כן קרא שמה עין הקורא אשר בלחי עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JG15_20","008_15_20","JDG","15","20","20","וישפט את ישראל בימי פלשתים עשרים שנה׃ ");
INSERT INTO heb_vpl VALUES ("JG16_1","008_16_1","JDG","16","1","1","וילך שמשון עזתה וירא שם אשה זונה ויבא אליה׃ ");
INSERT INTO heb_vpl VALUES ("JG16_2","008_16_2","JDG","16","2","2","לעזתים לאמר בא שמשון הנה ויסבו ויארבו לו כל הלילה בשער העיר ויתחרשו כל הלילה לאמר עד אור הבקר והרגנהו׃ ");
INSERT INTO heb_vpl VALUES ("JG16_3","008_16_3","JDG","16","3","3","וישכב שמשון עד חצי הלילה ויקם בחצי הלילה ויאחז בדלתות שער העיר ובשתי המזוזות ויסעם עם הבריח וישם על כתפיו ויעלם אל ראש ההר אשר על פני חברון׃ ");
INSERT INTO heb_vpl VALUES ("JG16_4","008_16_4","JDG","16","4","4","ויהי אחרי כן ויאהב אשה בנחל שרק ושמה דלילה׃ ");
INSERT INTO heb_vpl VALUES ("JG16_5","008_16_5","JDG","16","5","5","ויעלו אליה סרני פלשתים ויאמרו לה פתי אותו וראי במה כחו גדול ובמה נוכל לו ואסרנהו לענתו ואנחנו נתן לך איש אלף ומאה כסף׃ ");
INSERT INTO heb_vpl VALUES ("JG16_6","008_16_6","JDG","16","6","6","ותאמר דלילה אל שמשון הגידה נא לי במה כחך גדול ובמה תאסר לענותך׃ ");
INSERT INTO heb_vpl VALUES ("JG16_7","008_16_7","JDG","16","7","7","ויאמר אליה שמשון אם יאסרני בשבעה יתרים לחים אשר לא חרבו וחליתי והייתי כאחד האדם׃ ");
INSERT INTO heb_vpl VALUES ("JG16_8","008_16_8","JDG","16","8","8","ויעלו לה סרני פלשתים שבעה יתרים לחים אשר לא חרבו ותאסרהו בהם׃ ");
INSERT INTO heb_vpl VALUES ("JG16_9","008_16_9","JDG","16","9","9","והארב ישב לה בחדר ותאמר אליו פלשתים עליך שמשון וינתק את היתרים כאשר ינתק פתיל הנערת בהריחו אש ולא נודע כחו׃ ");
INSERT INTO heb_vpl VALUES ("JG16_10","008_16_10","JDG","16","10","10","ותאמר דלילה אל שמשון הנה התלת בי ותדבר אלי כזבים עתה הגידה נא לי במה תאסר׃ ");
INSERT INTO heb_vpl VALUES ("JG16_11","008_16_11","JDG","16","11","11","ויאמר אליה אם אסור יאסרוני בעבתים חדשים אשר לא נעשה בהם מלאכה וחליתי והייתי כאחד האדם׃ ");
INSERT INTO heb_vpl VALUES ("JG16_12","008_16_12","JDG","16","12","12","ותקח דלילה עבתים חדשים ותאסרהו בהם ותאמר אליו פלשתים עליך שמשון והארב ישב בחדר וינתקם מעל זרעתיו כחוט׃ ");
INSERT INTO heb_vpl VALUES ("JG16_13","008_16_13","JDG","16","13","13","ותאמר דלילה אל שמשון עד הנה התלת בי ותדבר אלי כזבים הגידה לי במה תאסר ויאמר אליה אם תארגי את שבע מחלפות ראשי עם המסכת׃ ");
INSERT INTO heb_vpl VALUES ("JG16_14","008_16_14","JDG","16","14","14","ותתקע ביתד ותאמר אליו פלשתים עליך שמשון וייקץ משנתו ויסע את היתד הארג ואת המסכת׃ ");
INSERT INTO heb_vpl VALUES ("JG16_15","008_16_15","JDG","16","15","15","ותאמר אליו איך תאמר אהבתיך ולבך אין אתי זה שלש פעמים התלת בי ולא הגדת לי במה כחך גדול׃ ");
INSERT INTO heb_vpl VALUES ("JG16_16","008_16_16","JDG","16","16","16","ויהי כי הציקה לו בדבריה כל הימים ותאלצהו ותקצר נפשו למות׃ ");
INSERT INTO heb_vpl VALUES ("JG16_17","008_16_17","JDG","16","17","17","ויגד לה את כל לבו ויאמר לה מורה לא עלה על ראשי כי נזיר אלהים אני מבטן אמי אם גלחתי וסר ממני כחי וחליתי והייתי ככל האדם׃ ");
INSERT INTO heb_vpl VALUES ("JG16_18","008_16_18","JDG","16","18","18","ותרא דלילה כי הגיד לה את כל לבו ותשלח ותקרא לסרני פלשתים לאמר עלו הפעם כי הגיד לה את כל לבו ועלו אליה סרני פלשתים ויעלו הכסף בידם׃ ");
INSERT INTO heb_vpl VALUES ("JG16_19","008_16_19","JDG","16","19","19","ותישנהו על ברכיה ותקרא לאיש ותגלח את שבע מחלפות ראשו ותחל לענותו ויסר כחו מעליו׃ ");
INSERT INTO heb_vpl VALUES ("JG16_20","008_16_20","JDG","16","20","20","ותאמר פלשתים עליך שמשון ויקץ משנתו ויאמר אצא כפעם בפעם ואנער והוא לא ידע כי יהוה סר מעליו׃ ");
INSERT INTO heb_vpl VALUES ("JG16_21","008_16_21","JDG","16","21","21","ויאחזוהו פלשתים וינקרו את עיניו ויורידו אותו עזתה ויאסרוהו בנחשתים ויהי טוחן בבית האסירים׃ ");
INSERT INTO heb_vpl VALUES ("JG16_22","008_16_22","JDG","16","22","22","ויחל שער ראשו לצמח כאשר גלח׃ ");
INSERT INTO heb_vpl VALUES ("JG16_23","008_16_23","JDG","16","23","23","וסרני פלשתים נאספו לזבח זבח גדול לדגון אלהיהם ולשמחה ויאמרו נתן אלהינו בידנו את שמשון אויבינו׃ ");
INSERT INTO heb_vpl VALUES ("JG16_24","008_16_24","JDG","16","24","24","ויראו אתו העם ויהללו את אלהיהם כי אמרו נתן אלהינו בידנו את אויבנו ואת מחריב ארצנו ואשר הרבה את חללינו׃ ");
INSERT INTO heb_vpl VALUES ("JG16_25","008_16_25","JDG","16","25","25","ויהי כי טוב לבם ויאמרו קראו לשמשון וישחק לנו ויקראו לשמשון מבית האסירים ויצחק לפניהם ויעמידו אותו בין העמודים׃ ");
INSERT INTO heb_vpl VALUES ("JG16_26","008_16_26","JDG","16","26","26","ויאמר שמשון אל הנער המחזיק בידו הניחה אותי והימשני את העמדים אשר הבית נכון עליהם ואשען עליהם׃ ");
INSERT INTO heb_vpl VALUES ("JG16_27","008_16_27","JDG","16","27","27","והבית מלא האנשים והנשים ושמה כל סרני פלשתים ועל הגג כשלשת אלפים איש ואשה הראים בשחוק שמשון׃ ");
INSERT INTO heb_vpl VALUES ("JG16_28","008_16_28","JDG","16","28","28","ויקרא שמשון אל יהוה ויאמר אדני יהוה זכרני נא וחזקני נא אך הפעם הזה האלהים ואנקמה נקם אחת משתי עיני מפלשתים׃ ");
INSERT INTO heb_vpl VALUES ("JG16_29","008_16_29","JDG","16","29","29","וילפת שמשון את שני עמודי התוך אשר הבית נכון עליהם ויסמך עליהם אחד בימינו ואחד בשמאלו׃ ");
INSERT INTO heb_vpl VALUES ("JG16_30","008_16_30","JDG","16","30","30","ויאמר שמשון תמות נפשי עם פלשתים ויט בכח ויפל הבית על הסרנים ועל כל העם אשר בו ויהיו המתים אשר המית במותו רבים מאשר המית בחייו׃ ");
INSERT INTO heb_vpl VALUES ("JG16_31","008_16_31","JDG","16","31","31","וירדו אחיו וכל בית אביהו וישאו אתו ויעלו ויקברו אותו בין צרעה ובין אשתאל בקבר מנוח אביו והוא שפט את ישראל עשרים שנה׃ ");
INSERT INTO heb_vpl VALUES ("JG17_1","008_17_1","JDG","17","1","1","ויהי איש מהר אפרים ושמו מיכיהו׃ ");
INSERT INTO heb_vpl VALUES ("JG17_2","008_17_2","JDG","17","2","2","ויאמר לאמו אלף ומאה הכסף אשר לקח לך ואתי אלית וגם אמרת באזני הנה הכסף אתי אני לקחתיו ותאמר אמו ברוך בני ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG17_3","008_17_3","JDG","17","3","3","וישב את אלף ומאה הכסף לאמו ותאמר אמו הקדש הקדשתי את הכסף ליהוה מידי לבני לעשות פסל ומסכה ועתה אשיבנו לך׃ ");
INSERT INTO heb_vpl VALUES ("JG17_4","008_17_4","JDG","17","4","4","וישב את הכסף לאמו ותקח אמו מאתים כסף ותתנהו לצורף ויעשהו פסל ומסכה ויהי בבית מיכיהו׃ ");
INSERT INTO heb_vpl VALUES ("JG17_5","008_17_5","JDG","17","5","5","והאיש מיכה לו בית אלהים ויעש אפוד ותרפים וימלא את יד אחד מבניו ויהי לו לכהן׃ ");
INSERT INTO heb_vpl VALUES ("JG17_6","008_17_6","JDG","17","6","6","בימים ההם אין מלך בישראל איש הישר בעיניו יעשה׃ ");
INSERT INTO heb_vpl VALUES ("JG17_7","008_17_7","JDG","17","7","7","ויהי נער מבית לחם יהודה ממשפחת יהודה והוא לוי והוא גר שם׃ ");
INSERT INTO heb_vpl VALUES ("JG17_8","008_17_8","JDG","17","8","8","וילך האיש מהעיר מבית לחם יהודה לגור באשר ימצא ויבא הר אפרים עד בית מיכה לעשות דרכו׃ ");
INSERT INTO heb_vpl VALUES ("JG17_9","008_17_9","JDG","17","9","9","ויאמר לו מיכה מאין תבוא ויאמר אליו לוי אנכי מבית לחם יהודה ואנכי הלך לגור באשר אמצא׃ ");
INSERT INTO heb_vpl VALUES ("JG17_10","008_17_10","JDG","17","10","10","ויאמר לו מיכה שבה עמדי והיה לי לאב ולכהן ואנכי אתן לך עשרת כסף לימים וערך בגדים ומחיתך וילך הלוי׃ ");
INSERT INTO heb_vpl VALUES ("JG17_11","008_17_11","JDG","17","11","11","ויואל הלוי לשבת את האיש ויהי הנער לו כאחד מבניו׃ ");
INSERT INTO heb_vpl VALUES ("JG17_12","008_17_12","JDG","17","12","12","וימלא מיכה את יד הלוי ויהי לו הנער לכהן ויהי בבית מיכה׃ ");
INSERT INTO heb_vpl VALUES ("JG17_13","008_17_13","JDG","17","13","13","ויאמר מיכה עתה ידעתי כי ייטיב יהוה לי כי היה לי הלוי לכהן׃ ");
INSERT INTO heb_vpl VALUES ("JG18_1","008_18_1","JDG","18","1","1","בימים ההם אין מלך בישראל ובימים ההם שבט הדני מבקש לו נחלה לשבת כי לא נפלה לו עד היום ההוא בתוך שבטי ישראל בנחלה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_2","008_18_2","JDG","18","2","2","וישלחו בני דן ממשפחתם חמשה אנשים מקצותם אנשים בני חיל מצרעה ומאשתאל לרגל את הארץ ולחקרה ויאמרו אלהם לכו חקרו את הארץ ויבאו הר אפרים עד בית מיכה וילינו שם׃ ");
INSERT INTO heb_vpl VALUES ("JG18_3","008_18_3","JDG","18","3","3","המה עם בית מיכה והמה הכירו את קול הנער הלוי ויסורו שם ויאמרו לו מי הביאך הלם ומה אתה עשה בזה ומה לך פה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_4","008_18_4","JDG","18","4","4","ויאמר אלהם כזה וכזה עשה לי מיכה וישכרני ואהי לו לכהן׃ ");
INSERT INTO heb_vpl VALUES ("JG18_5","008_18_5","JDG","18","5","5","ויאמרו לו שאל נא באלהים ונדעה התצליח דרכנו אשר אנחנו הלכים עליה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_6","008_18_6","JDG","18","6","6","ויאמר להם הכהן לכו לשלום נכח יהוה דרככם אשר תלכו בה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_7","008_18_7","JDG","18","7","7","וילכו חמשת האנשים ויבאו לישה ויראו את העם אשר בקרבה יושבת לבטח כמשפט צדנים שקט ובטח ואין מכלים דבר בארץ יורש עצר ורחקים המה מצדנים ודבר אין להם עם אדם׃ ");
INSERT INTO heb_vpl VALUES ("JG18_8","008_18_8","JDG","18","8","8","ויבאו אל אחיהם צרעה ואשתאל ויאמרו להם אחיהם מה אתם׃ ");
INSERT INTO heb_vpl VALUES ("JG18_9","008_18_9","JDG","18","9","9","ויאמרו קומה ונעלה עליהם כי ראינו את הארץ והנה טובה מאד ואתם מחשים אל תעצלו ללכת לבא לרשת את הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JG18_10","008_18_10","JDG","18","10","10","כבאכם תבאו אל עם בטח והארץ רחבת ידים כי נתנה אלהים בידכם מקום אשר אין שם מחסור כל דבר אשר בארץ׃ ");
INSERT INTO heb_vpl VALUES ("JG18_11","008_18_11","JDG","18","11","11","ויסעו משם ממשפחת הדני מצרעה ומאשתאל שש מאות איש חגור כלי מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_12","008_18_12","JDG","18","12","12","ויעלו ויחנו בקרית יערים ביהודה על כן קראו למקום ההוא מחנה דן עד היום הזה הנה אחרי קרית יערים׃ ");
INSERT INTO heb_vpl VALUES ("JG18_13","008_18_13","JDG","18","13","13","ויעברו משם הר אפרים ויבאו עד בית מיכה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_14","008_18_14","JDG","18","14","14","ויענו חמשת האנשים ההלכים לרגל את הארץ ליש ויאמרו אל אחיהם הידעתם כי יש בבתים האלה אפוד ותרפים ופסל ומסכה ועתה דעו מה תעשו׃ ");
INSERT INTO heb_vpl VALUES ("JG18_15","008_18_15","JDG","18","15","15","ויסורו שמה ויבאו אל בית הנער הלוי בית מיכה וישאלו לו לשלום׃ ");
INSERT INTO heb_vpl VALUES ("JG18_16","008_18_16","JDG","18","16","16","ושש מאות איש חגורים כלי מלחמתם נצבים פתח השער אשר מבני דן׃ ");
INSERT INTO heb_vpl VALUES ("JG18_17","008_18_17","JDG","18","17","17","ויעלו חמשת האנשים ההלכים לרגל את הארץ באו שמה לקחו את הפסל ואת האפוד ואת התרפים ואת המסכה והכהן נצב פתח השער ושש מאות האיש החגור כלי המלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_18","008_18_18","JDG","18","18","18","ואלה באו בית מיכה ויקחו את פסל האפוד ואת התרפים ואת המסכה ויאמר אליהם הכהן מה אתם עשים׃ ");
INSERT INTO heb_vpl VALUES ("JG18_19","008_18_19","JDG","18","19","19","ויאמרו לו החרש שים ידך על פיך ולך עמנו והיה לנו לאב ולכהן הטוב היותך כהן לבית איש אחד או היותך כהן לשבט ולמשפחה בישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG18_20","008_18_20","JDG","18","20","20","וייטב לב הכהן ויקח את האפוד ואת התרפים ואת הפסל ויבא בקרב העם׃ ");
INSERT INTO heb_vpl VALUES ("JG18_21","008_18_21","JDG","18","21","21","ויפנו וילכו וישימו את הטף ואת המקנה ואת הכבודה לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("JG18_22","008_18_22","JDG","18","22","22","המה הרחיקו מבית מיכה והאנשים אשר בבתים אשר עם בית מיכה נזעקו וידביקו את בני דן׃ ");
INSERT INTO heb_vpl VALUES ("JG18_23","008_18_23","JDG","18","23","23","ויקראו אל בני דן ויסבו פניהם ויאמרו למיכה מה לך כי נזעקת׃ ");
INSERT INTO heb_vpl VALUES ("JG18_24","008_18_24","JDG","18","24","24","ויאמר את אלהי אשר עשיתי לקחתם ואת הכהן ותלכו ומה לי עוד ומה זה תאמרו אלי מה לך׃ ");
INSERT INTO heb_vpl VALUES ("JG18_25","008_18_25","JDG","18","25","25","ויאמרו אליו בני דן אל תשמע קולך עמנו פן יפגעו בכם אנשים מרי נפש ואספתה נפשך ונפש ביתך׃ ");
INSERT INTO heb_vpl VALUES ("JG18_26","008_18_26","JDG","18","26","26","וילכו בני דן לדרכם וירא מיכה כי חזקים המה ממנו ויפן וישב אל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("JG18_27","008_18_27","JDG","18","27","27","והמה לקחו את אשר עשה מיכה ואת הכהן אשר היה לו ויבאו על ליש על עם שקט ובטח ויכו אותם לפי חרב ואת העיר שרפו באש׃ ");
INSERT INTO heb_vpl VALUES ("JG18_28","008_18_28","JDG","18","28","28","ואין מציל כי רחוקה היא מצידון ודבר אין להם עם אדם והיא בעמק אשר לבית רחוב ויבנו את העיר וישבו בה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_29","008_18_29","JDG","18","29","29","ויקראו שם העיר דן בשם דן אביהם אשר יולד לישראל ואולם ליש שם העיר לראשנה׃ ");
INSERT INTO heb_vpl VALUES ("JG18_30","008_18_30","JDG","18","30","30","ויקימו להם בני דן את הפסל ויהונתן בן גרשם בן מנשה הוא ובניו היו כהנים לשבט הדני עד יום גלות הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JG18_31","008_18_31","JDG","18","31","31","וישימו להם את פסל מיכה אשר עשה כל ימי היות בית האלהים בשלה׃ ");
INSERT INTO heb_vpl VALUES ("JG19_1","008_19_1","JDG","19","1","1","ויהי בימים ההם ומלך אין בישראל ויהי איש לוי גר בירכתי הר אפרים ויקח לו אשה פילגש מבית לחם יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JG19_2","008_19_2","JDG","19","2","2","ותזנה עליו פילגשו ותלך מאתו אל בית אביה אל בית לחם יהודה ותהי שם ימים ארבעה חדשים׃ ");
INSERT INTO heb_vpl VALUES ("JG19_3","008_19_3","JDG","19","3","3","ויקם אישה וילך אחריה לדבר על לבה להשיבו ונערו עמו וצמד חמרים ותביאהו בית אביה ויראהו אבי הנערה וישמח לקראתו׃ ");
INSERT INTO heb_vpl VALUES ("JG19_4","008_19_4","JDG","19","4","4","ויחזק בו חתנו אבי הנערה וישב אתו שלשת ימים ויאכלו וישתו וילינו שם׃ ");
INSERT INTO heb_vpl VALUES ("JG19_5","008_19_5","JDG","19","5","5","ויהי ביום הרביעי וישכימו בבקר ויקם ללכת ויאמר אבי הנערה אל חתנו סעד לבך פת לחם ואחר תלכו׃ ");
INSERT INTO heb_vpl VALUES ("JG19_6","008_19_6","JDG","19","6","6","וישבו ויאכלו שניהם יחדו וישתו ויאמר אבי הנערה אל האיש הואל נא ולין ויטב לבך׃ ");
INSERT INTO heb_vpl VALUES ("JG19_7","008_19_7","JDG","19","7","7","ויקם האיש ללכת ויפצר בו חתנו וישב וילן שם׃ ");
INSERT INTO heb_vpl VALUES ("JG19_8","008_19_8","JDG","19","8","8","וישכם בבקר ביום החמישי ללכת ויאמר אבי הנערה סעד נא לבבך והתמהמהו עד נטות היום ויאכלו שניהם׃ ");
INSERT INTO heb_vpl VALUES ("JG19_9","008_19_9","JDG","19","9","9","ויקם האיש ללכת הוא ופילגשו ונערו ויאמר לו חתנו אבי הנערה הנה נא רפה היום לערב לינו נא הנה חנות היום לין פה וייטב לבבך והשכמתם מחר לדרככם והלכת לאהלך׃ ");
INSERT INTO heb_vpl VALUES ("JG19_10","008_19_10","JDG","19","10","10","ולא אבה האיש ללון ויקם וילך ויבא עד נכח יבוס היא ירושלם ועמו צמד חמורים חבושים ופילגשו עמו׃ ");
INSERT INTO heb_vpl VALUES ("JG19_11","008_19_11","JDG","19","11","11","הם עם יבוס והיום רד מאד ויאמר הנער אל אדניו לכה נא ונסורה אל עיר היבוסי הזאת ונלין בה׃ ");
INSERT INTO heb_vpl VALUES ("JG19_12","008_19_12","JDG","19","12","12","ויאמר אליו אדניו לא נסור אל עיר נכרי אשר לא מבני ישראל הנה ועברנו עד גבעה׃ ");
INSERT INTO heb_vpl VALUES ("JG19_13","008_19_13","JDG","19","13","13","ויאמר לנערו לך ונקרבה באחד המקמות ולנו בגבעה או ברמה׃ ");
INSERT INTO heb_vpl VALUES ("JG19_14","008_19_14","JDG","19","14","14","ויעברו וילכו ותבא להם השמש אצל הגבעה אשר לבנימן׃ ");
INSERT INTO heb_vpl VALUES ("JG19_15","008_19_15","JDG","19","15","15","ויסרו שם לבוא ללון בגבעה ויבא וישב ברחוב העיר ואין איש מאסף אותם הביתה ללון׃ ");
INSERT INTO heb_vpl VALUES ("JG19_16","008_19_16","JDG","19","16","16","והנה איש זקן בא מן מעשהו מן השדה בערב והאיש מהר אפרים והוא גר בגבעה ואנשי המקום בני ימיני׃ ");
INSERT INTO heb_vpl VALUES ("JG19_17","008_19_17","JDG","19","17","17","וישא עיניו וירא את האיש הארח ברחב העיר ויאמר האיש הזקן אנה תלך ומאין תבוא׃ ");
INSERT INTO heb_vpl VALUES ("JG19_18","008_19_18","JDG","19","18","18","ויאמר אליו עברים אנחנו מבית לחם יהודה עד ירכתי הר אפרים משם אנכי ואלך עד בית לחם יהודה ואת בית יהוה אני הלך ואין איש מאסף אותי הביתה׃ ");
INSERT INTO heb_vpl VALUES ("JG19_19","008_19_19","JDG","19","19","19","וגם תבן גם מספוא יש לחמורינו וגם לחם ויין יש לי ולאמתך ולנער עם עבדיך אין מחסור כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("JG19_20","008_19_20","JDG","19","20","20","ויאמר האיש הזקן שלום לך רק כל מחסורך עלי רק ברחוב אל תלן׃ ");
INSERT INTO heb_vpl VALUES ("JG19_21","008_19_21","JDG","19","21","21","ויביאהו לביתו ויבול לחמורים וירחצו רגליהם ויאכלו וישתו׃ ");
INSERT INTO heb_vpl VALUES ("JG19_22","008_19_22","JDG","19","22","22","המה מיטיבים את לבם והנה אנשי העיר אנשי בני בליעל נסבו את הבית מתדפקים על הדלת ויאמרו אל האיש בעל הבית הזקן לאמר הוצא את האיש אשר בא אל ביתך ונדענו׃ ");
INSERT INTO heb_vpl VALUES ("JG19_23","008_19_23","JDG","19","23","23","ויצא אליהם האיש בעל הבית ויאמר אלהם אל אחי אל תרעו נא אחרי אשר בא האיש הזה אל ביתי אל תעשו את הנבלה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JG19_24","008_19_24","JDG","19","24","24","הנה בתי הבתולה ופילגשהו אוציאה נא אותם וענו אותם ועשו להם הטוב בעיניכם ולאיש הזה לא תעשו דבר הנבלה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JG19_25","008_19_25","JDG","19","25","25","ולא אבו האנשים לשמע לו ויחזק האיש בפילגשו ויצא אליהם החוץ וידעו אותה ויתעללו בה כל הלילה עד הבקר וישלחוה בעלות השחר׃ ");
INSERT INTO heb_vpl VALUES ("JG19_26","008_19_26","JDG","19","26","26","ותבא האשה לפנות הבקר ותפל פתח בית האיש אשר אדוניה שם עד האור׃ ");
INSERT INTO heb_vpl VALUES ("JG19_27","008_19_27","JDG","19","27","27","ויקם אדניה בבקר ויפתח דלתות הבית ויצא ללכת לדרכו והנה האשה פילגשו נפלת פתח הבית וידיה על הסף׃ ");
INSERT INTO heb_vpl VALUES ("JG19_28","008_19_28","JDG","19","28","28","ויאמר אליה קומי ונלכה ואין ענה ויקחה על החמור ויקם האיש וילך למקמו׃ ");
INSERT INTO heb_vpl VALUES ("JG19_29","008_19_29","JDG","19","29","29","ויבא אל ביתו ויקח את המאכלת ויחזק בפילגשו וינתחה לעצמיה לשנים עשר נתחים וישלחה בכל גבול ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG19_30","008_19_30","JDG","19","30","30","והיה כל הראה ואמר לא נהיתה ולא נראתה כזאת למיום עלות בני ישראל מארץ מצרים עד היום הזה שימו לכם עליה עצו ודברו׃ ");
INSERT INTO heb_vpl VALUES ("JG20_1","008_20_1","JDG","20","1","1","ויצאו כל בני ישראל ותקהל העדה כאיש אחד למדן ועד באר שבע וארץ הגלעד אל יהוה המצפה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_2","008_20_2","JDG","20","2","2","ויתיצבו פנות כל העם כל שבטי ישראל בקהל עם האלהים ארבע מאות אלף איש רגלי שלף חרב׃ ");
INSERT INTO heb_vpl VALUES ("JG20_3","008_20_3","JDG","20","3","3","וישמעו בני בנימן כי עלו בני ישראל המצפה ויאמרו בני ישראל דברו איכה נהיתה הרעה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JG20_4","008_20_4","JDG","20","4","4","ויען האיש הלוי איש האשה הנרצחה ויאמר הגבעתה אשר לבנימן באתי אני ופילגשי ללון׃ ");
INSERT INTO heb_vpl VALUES ("JG20_5","008_20_5","JDG","20","5","5","ויקמו עלי בעלי הגבעה ויסבו עלי את הבית לילה אותי דמו להרג ואת פילגשי ענו ותמת׃ ");
INSERT INTO heb_vpl VALUES ("JG20_6","008_20_6","JDG","20","6","6","ואחז בפילגשי ואנתחה ואשלחה בכל שדה נחלת ישראל כי עשו זמה ונבלה בישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG20_7","008_20_7","JDG","20","7","7","הנה כלכם בני ישראל הבו לכם דבר ועצה הלם׃ ");
INSERT INTO heb_vpl VALUES ("JG20_8","008_20_8","JDG","20","8","8","ויקם כל העם כאיש אחד לאמר לא נלך איש לאהלו ולא נסור איש לביתו׃ ");
INSERT INTO heb_vpl VALUES ("JG20_9","008_20_9","JDG","20","9","9","ועתה זה הדבר אשר נעשה לגבעה עליה בגורל׃ ");
INSERT INTO heb_vpl VALUES ("JG20_10","008_20_10","JDG","20","10","10","ולקחנו עשרה אנשים למאה לכל שבטי ישראל ומאה לאלף ואלף לרבבה לקחת צדה לעם לעשות לבואם לגבע בנימן ככל הנבלה אשר עשה בישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG20_11","008_20_11","JDG","20","11","11","ויאסף כל איש ישראל אל העיר כאיש אחד חברים׃ ");
INSERT INTO heb_vpl VALUES ("JG20_12","008_20_12","JDG","20","12","12","וישלחו שבטי ישראל אנשים בכל שבטי בנימן לאמר מה הרעה הזאת אשר נהיתה בכם׃ ");
INSERT INTO heb_vpl VALUES ("JG20_13","008_20_13","JDG","20","13","13","ועתה תנו את האנשים בני בליעל אשר בגבעה ונמיתם ונבערה רעה מישראל ולא אבו בנימן לשמע בקול אחיהם בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG20_14","008_20_14","JDG","20","14","14","ויאספו בני בנימן מן הערים הגבעתה לצאת למלחמה עם בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG20_15","008_20_15","JDG","20","15","15","ויתפקדו בני בנימן ביום ההוא מהערים עשרים וששה אלף איש שלף חרב לבד מישבי הגבעה התפקדו שבע מאות איש בחור׃ ");
INSERT INTO heb_vpl VALUES ("JG20_16","008_20_16","JDG","20","16","16","מכל העם הזה שבע מאות איש בחור אטר יד ימינו כל זה קלע באבן אל השערה ולא יחטא׃ ");
INSERT INTO heb_vpl VALUES ("JG20_17","008_20_17","JDG","20","17","17","ואיש ישראל התפקדו לבד מבנימן ארבע מאות אלף איש שלף חרב כל זה איש מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_18","008_20_18","JDG","20","18","18","ויקמו ויעלו בית אל וישאלו באלהים ויאמרו בני ישראל מי יעלה לנו בתחלה למלחמה עם בני בנימן ויאמר יהוה יהודה בתחלה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_19","008_20_19","JDG","20","19","19","ויקומו בני ישראל בבקר ויחנו על הגבעה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_20","008_20_20","JDG","20","20","20","ויצא איש ישראל למלחמה עם בנימן ויערכו אתם איש ישראל מלחמה אל הגבעה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_21","008_20_21","JDG","20","21","21","ויצאו בני בנימן מן הגבעה וישחיתו בישראל ביום ההוא שנים ועשרים אלף איש ארצה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_22","008_20_22","JDG","20","22","22","ויתחזק העם איש ישראל ויספו לערך מלחמה במקום אשר ערכו שם ביום הראשון׃ ");
INSERT INTO heb_vpl VALUES ("JG20_23","008_20_23","JDG","20","23","23","ויעלו בני ישראל ויבכו לפני יהוה עד הערב וישאלו ביהוה לאמר האוסיף לגשת למלחמה עם בני בנימן אחי ויאמר יהוה עלו אליו׃ ");
INSERT INTO heb_vpl VALUES ("JG20_24","008_20_24","JDG","20","24","24","ויקרבו בני ישראל אל בני בנימן ביום השני׃ ");
INSERT INTO heb_vpl VALUES ("JG20_25","008_20_25","JDG","20","25","25","ויצא בנימן לקראתם מן הגבעה ביום השני וישחיתו בבני ישראל עוד שמנת עשר אלף איש ארצה כל אלה שלפי חרב׃ ");
INSERT INTO heb_vpl VALUES ("JG20_26","008_20_26","JDG","20","26","26","ויעלו כל בני ישראל וכל העם ויבאו בית אל ויבכו וישבו שם לפני יהוה ויצומו ביום ההוא עד הערב ויעלו עלות ושלמים לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_27","008_20_27","JDG","20","27","27","וישאלו בני ישראל ביהוה ושם ארון ברית האלהים בימים ההם׃ ");
INSERT INTO heb_vpl VALUES ("JG20_28","008_20_28","JDG","20","28","28","ופינחס בן אלעזר בן אהרן עמד לפניו בימים ההם לאמר האוסף עוד לצאת למלחמה עם בני בנימן אחי אם אחדל ויאמר יהוה עלו כי מחר אתננו בידך׃ ");
INSERT INTO heb_vpl VALUES ("JG20_29","008_20_29","JDG","20","29","29","וישם ישראל ארבים אל הגבעה סביב׃ ");
INSERT INTO heb_vpl VALUES ("JG20_30","008_20_30","JDG","20","30","30","ויעלו בני ישראל אל בני בנימן ביום השלישי ויערכו אל הגבעה כפעם בפעם׃ ");
INSERT INTO heb_vpl VALUES ("JG20_31","008_20_31","JDG","20","31","31","ויצאו בני בנימן לקראת העם הנתקו מן העיר ויחלו להכות מהעם חללים כפעם בפעם במסלות אשר אחת עלה בית אל ואחת גבעתה בשדה כשלשים איש בישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG20_32","008_20_32","JDG","20","32","32","ויאמרו בני בנימן נגפים הם לפנינו כבראשנה ובני ישראל אמרו ננוסה ונתקנהו מן העיר אל המסלות׃ ");
INSERT INTO heb_vpl VALUES ("JG20_33","008_20_33","JDG","20","33","33","וכל איש ישראל קמו ממקומו ויערכו בבעל תמר וארב ישראל מגיח ממקמו ממערה גבע׃ ");
INSERT INTO heb_vpl VALUES ("JG20_34","008_20_34","JDG","20","34","34","ויבאו מנגד לגבעה עשרת אלפים איש בחור מכל ישראל והמלחמה כבדה והם לא ידעו כי נגעת עליהם הרעה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_35","008_20_35","JDG","20","35","35","ויגף יהוה את בנימן לפני ישראל וישחיתו בני ישראל בבנימן ביום ההוא עשרים וחמשה אלף ומאה איש כל אלה שלף חרב׃ ");
INSERT INTO heb_vpl VALUES ("JG20_36","008_20_36","JDG","20","36","36","ויראו בני בנימן כי נגפו ויתנו איש ישראל מקום לבנימן כי בטחו אל הארב אשר שמו אל הגבעה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_37","008_20_37","JDG","20","37","37","והארב החישו ויפשטו אל הגבעה וימשך הארב ויך את כל העיר לפי חרב׃ ");
INSERT INTO heb_vpl VALUES ("JG20_38","008_20_38","JDG","20","38","38","והמועד היה לאיש ישראל עם הארב הרב להעלותם משאת העשן מן העיר׃ ");
INSERT INTO heb_vpl VALUES ("JG20_39","008_20_39","JDG","20","39","39","ויהפך איש ישראל במלחמה ובנימן החל להכות חללים באיש ישראל כשלשים איש כי אמרו אך נגוף נגף הוא לפנינו כמלחמה הראשנה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_40","008_20_40","JDG","20","40","40","והמשאת החלה לעלות מן העיר עמוד עשן ויפן בנימן אחריו והנה עלה כליל העיר השמימה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_41","008_20_41","JDG","20","41","41","ואיש ישראל הפך ויבהל איש בנימן כי ראה כי נגעה עליו הרעה׃ ");
INSERT INTO heb_vpl VALUES ("JG20_42","008_20_42","JDG","20","42","42","ויפנו לפני איש ישראל אל דרך המדבר והמלחמה הדביקתהו ואשר מהערים משחיתים אותו בתוכו׃ ");
INSERT INTO heb_vpl VALUES ("JG20_43","008_20_43","JDG","20","43","43","כתרו את בנימן הרדיפהו מנוחה הדריכהו עד נכח הגבעה ממזרח שמש׃ ");
INSERT INTO heb_vpl VALUES ("JG20_44","008_20_44","JDG","20","44","44","ויפלו מבנימן שמנה עשר אלף איש את כל אלה אנשי חיל׃ ");
INSERT INTO heb_vpl VALUES ("JG20_45","008_20_45","JDG","20","45","45","ויפנו וינסו המדברה אל סלע הרמון ויעללהו במסלות חמשת אלפים איש וידביקו אחריו עד גדעם ויכו ממנו אלפים איש׃ ");
INSERT INTO heb_vpl VALUES ("JG20_46","008_20_46","JDG","20","46","46","ויהי כל הנפלים מבנימן עשרים וחמשה אלף איש שלף חרב ביום ההוא את כל אלה אנשי חיל׃ ");
INSERT INTO heb_vpl VALUES ("JG20_47","008_20_47","JDG","20","47","47","ויפנו וינסו המדברה אל סלע הרמון שש מאות איש וישבו בסלע רמון ארבעה חדשים׃ ");
INSERT INTO heb_vpl VALUES ("JG20_48","008_20_48","JDG","20","48","48","ואיש ישראל שבו אל בני בנימן ויכום לפי חרב מעיר מתם עד בהמה עד כל הנמצא גם כל הערים הנמצאות שלחו באש׃ ");
INSERT INTO heb_vpl VALUES ("JG21_1","008_21_1","JDG","21","1","1","ואיש ישראל נשבע במצפה לאמר איש ממנו לא יתן בתו לבנימן לאשה׃ ");
INSERT INTO heb_vpl VALUES ("JG21_2","008_21_2","JDG","21","2","2","ויבא העם בית אל וישבו שם עד הערב לפני האלהים וישאו קולם ויבכו בכי גדול׃ ");
INSERT INTO heb_vpl VALUES ("JG21_3","008_21_3","JDG","21","3","3","ויאמרו למה יהוה אלהי ישראל היתה זאת בישראל להפקד היום מישראל שבט אחד׃ ");
INSERT INTO heb_vpl VALUES ("JG21_4","008_21_4","JDG","21","4","4","ויהי ממחרת וישכימו העם ויבנו שם מזבח ויעלו עלות ושלמים׃ ");
INSERT INTO heb_vpl VALUES ("JG21_5","008_21_5","JDG","21","5","5","ויאמרו בני ישראל מי אשר לא עלה בקהל מכל שבטי ישראל אל יהוה כי השבועה הגדולה היתה לאשר לא עלה אל יהוה המצפה לאמר מות יומת׃ ");
INSERT INTO heb_vpl VALUES ("JG21_6","008_21_6","JDG","21","6","6","וינחמו בני ישראל אל בנימן אחיו ויאמרו נגדע היום שבט אחד מישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG21_7","008_21_7","JDG","21","7","7","מה נעשה להם לנותרים לנשים ואנחנו נשבענו ביהוה לבלתי תת להם מבנותינו לנשים׃ ");
INSERT INTO heb_vpl VALUES ("JG21_8","008_21_8","JDG","21","8","8","ויאמרו מי אחד משבטי ישראל אשר לא עלה אל יהוה המצפה והנה לא בא איש אל המחנה מיביש גלעד אל הקהל׃ ");
INSERT INTO heb_vpl VALUES ("JG21_9","008_21_9","JDG","21","9","9","ויתפקד העם והנה אין שם איש מיושבי יבש גלעד׃ ");
INSERT INTO heb_vpl VALUES ("JG21_10","008_21_10","JDG","21","10","10","וישלחו שם העדה שנים עשר אלף איש מבני החיל ויצוו אותם לאמר לכו והכיתם את יושבי יבש גלעד לפי חרב והנשים והטף׃ ");
INSERT INTO heb_vpl VALUES ("JG21_11","008_21_11","JDG","21","11","11","וזה הדבר אשר תעשו כל זכר וכל אשה ידעת משכב זכר תחרימו׃ ");
INSERT INTO heb_vpl VALUES ("JG21_12","008_21_12","JDG","21","12","12","וימצאו מיושבי יביש גלעד ארבע מאות נערה בתולה אשר לא ידעה איש למשכב זכר ויביאו אותם אל המחנה שלה אשר בארץ כנען׃ ");
INSERT INTO heb_vpl VALUES ("JG21_13","008_21_13","JDG","21","13","13","וישלחו כל העדה וידברו אל בני בנימן אשר בסלע רמון ויקראו להם שלום׃ ");
INSERT INTO heb_vpl VALUES ("JG21_14","008_21_14","JDG","21","14","14","וישב בנימן בעת ההיא ויתנו להם הנשים אשר חיו מנשי יבש גלעד ולא מצאו להם כן׃ ");
INSERT INTO heb_vpl VALUES ("JG21_15","008_21_15","JDG","21","15","15","והעם נחם לבנימן כי עשה יהוה פרץ בשבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG21_16","008_21_16","JDG","21","16","16","ויאמרו זקני העדה מה נעשה לנותרים לנשים כי נשמדה מבנימן אשה׃ ");
INSERT INTO heb_vpl VALUES ("JG21_17","008_21_17","JDG","21","17","17","ויאמרו ירשת פליטה לבנימן ולא ימחה שבט מישראל׃ ");
INSERT INTO heb_vpl VALUES ("JG21_18","008_21_18","JDG","21","18","18","ואנחנו לא נוכל לתת להם נשים מבנותינו כי נשבעו בני ישראל לאמר ארור נתן אשה לבנימן׃ ");
INSERT INTO heb_vpl VALUES ("JG21_19","008_21_19","JDG","21","19","19","ויאמרו הנה חג יהוה בשלו מימים ימימה אשר מצפונה לבית אל מזרחה השמש למסלה העלה מבית אל שכמה ומנגב ללבונה׃ ");
INSERT INTO heb_vpl VALUES ("JG21_20","008_21_20","JDG","21","20","20","ויצו את בני בנימן לאמר לכו וארבתם בכרמים׃ ");
INSERT INTO heb_vpl VALUES ("JG21_21","008_21_21","JDG","21","21","21","וראיתם והנה אם יצאו בנות שילו לחול במחלות ויצאתם מן הכרמים וחטפתם לכם איש אשתו מבנות שילו והלכתם ארץ בנימן׃ ");
INSERT INTO heb_vpl VALUES ("JG21_22","008_21_22","JDG","21","22","22","והיה כי יבאו אבותם או אחיהם לרוב אלינו ואמרנו אליהם חנונו אותם כי לא לקחנו איש אשתו במלחמה כי לא אתם נתתם להם כעת תאשמו׃ ");
INSERT INTO heb_vpl VALUES ("JG21_23","008_21_23","JDG","21","23","23","ויעשו כן בני בנימן וישאו נשים למספרם מן המחללות אשר גזלו וילכו וישובו אל נחלתם ויבנו את הערים וישבו בהם׃ ");
INSERT INTO heb_vpl VALUES ("JG21_24","008_21_24","JDG","21","24","24","ויתהלכו משם בני ישראל בעת ההיא איש לשבטו ולמשפחתו ויצאו משם איש לנחלתו׃ ");
INSERT INTO heb_vpl VALUES ("JG21_25","008_21_25","JDG","21","25","25","בימים ההם אין מלך בישראל איש הישר בעיניו יעשה׃ ");
INSERT INTO heb_vpl VALUES ("RT1_1","009_1_1","RUT","1","1","1","ויהי בימי שפט השפטים ויהי רעב בארץ וילך איש מבית לחם יהודה לגור בשדי מואב הוא ואשתו ושני בניו׃ ");
INSERT INTO heb_vpl VALUES ("RT1_2","009_1_2","RUT","1","2","2","ושם האיש אלימלך ושם אשתו נעמי ושם שני בניו מחלון וכליון אפרתים מבית לחם יהודה ויבאו שדי מואב ויהיו שם׃ ");
INSERT INTO heb_vpl VALUES ("RT1_3","009_1_3","RUT","1","3","3","וימת אלימלך איש נעמי ותשאר היא ושני בניה׃ ");
INSERT INTO heb_vpl VALUES ("RT1_4","009_1_4","RUT","1","4","4","וישאו להם נשים מאביות שם האחת ערפה ושם השנית רות וישבו שם כעשר שנים׃ ");
INSERT INTO heb_vpl VALUES ("RT1_5","009_1_5","RUT","1","5","5","וימותו גם שניהם מחלון וכליון ותשאר האשה משני ילדיה ומאישה׃ ");
INSERT INTO heb_vpl VALUES ("RT1_6","009_1_6","RUT","1","6","6","ותקם היא וכלתיה ותשב משדי מואב כי שמעה בשדה מואב כי פקד יהוה את עמו לתת להם לחם׃ ");
INSERT INTO heb_vpl VALUES ("RT1_7","009_1_7","RUT","1","7","7","ותצא מן המקום אשר היתה שמה ושתי כלתיה עמה ותלכנה בדרך לשוב אל ארץ יהודה׃ ");
INSERT INTO heb_vpl VALUES ("RT1_8","009_1_8","RUT","1","8","8","ותאמר נעמי לשתי כלתיה לכנה שבנה אשה לבית אמה יעשה יהוה עמכם חסד כאשר עשיתם עם המתים ועמדי׃ ");
INSERT INTO heb_vpl VALUES ("RT1_9","009_1_9","RUT","1","9","9","יתן יהוה לכם ומצאן מנוחה אשה בית אישה ותשק להן ותשאנה קולן ותבכינה׃ ");
INSERT INTO heb_vpl VALUES ("RT1_10","009_1_10","RUT","1","10","10","ותאמרנה לה כי אתך נשוב לעמך׃ ");
INSERT INTO heb_vpl VALUES ("RT1_11","009_1_11","RUT","1","11","11","ותאמר נעמי שבנה בנתי למה תלכנה עמי העוד לי בנים במעי והיו לכם לאנשים׃ ");
INSERT INTO heb_vpl VALUES ("RT1_12","009_1_12","RUT","1","12","12","שבנה בנתי לכן כי זקנתי מהיות לאיש כי אמרתי יש לי תקוה גם הייתי הלילה לאיש וגם ילדתי בנים׃ ");
INSERT INTO heb_vpl VALUES ("RT1_13","009_1_13","RUT","1","13","13","הלהן תשברנה עד אשר יגדלו הלהן תעגנה לבלתי היות לאיש אל בנתי כי מר לי מאד מכם כי יצאה בי יד יהוה׃ ");
INSERT INTO heb_vpl VALUES ("RT1_14","009_1_14","RUT","1","14","14","ותשנה קולן ותבכינה עוד ותשק ערפה לחמותה ורות דבקה בה׃ ");
INSERT INTO heb_vpl VALUES ("RT1_15","009_1_15","RUT","1","15","15","ותאמר הנה שבה יבמתך אל עמה ואל אלהיה שובי אחרי יבמתך׃ ");
INSERT INTO heb_vpl VALUES ("RT1_16","009_1_16","RUT","1","16","16","ותאמר רות אל תפגעי בי לעזבך לשוב מאחריך כי אל אשר תלכי אלך ובאשר תליני אלין עמך עמי ואלהיך אלהי׃ ");
INSERT INTO heb_vpl VALUES ("RT1_17","009_1_17","RUT","1","17","17","באשר תמותי אמות ושם אקבר כה יעשה יהוה לי וכה יסיף כי המות יפריד ביני ובינך׃ ");
INSERT INTO heb_vpl VALUES ("RT1_18","009_1_18","RUT","1","18","18","ותרא כי מתאמצת היא ללכת אתה ותחדל לדבר אליה׃ ");
INSERT INTO heb_vpl VALUES ("RT1_19","009_1_19","RUT","1","19","19","ותלכנה שתיהם עד באנה בית לחם ויהי כבאנה בית לחם ותהם כל העיר עליהן ותאמרנה הזאת נעמי׃ ");
INSERT INTO heb_vpl VALUES ("RT1_20","009_1_20","RUT","1","20","20","ותאמר אליהן אל תקראנה לי נעמי קראן לי מרא כי המר שדי לי מאד׃ ");
INSERT INTO heb_vpl VALUES ("RT1_21","009_1_21","RUT","1","21","21","אני מלאה הלכתי וריקם השיבני יהוה למה תקראנה לי נעמי ויהוה ענה בי ושדי הרע לי׃ ");
INSERT INTO heb_vpl VALUES ("RT1_22","009_1_22","RUT","1","22","22","ותשב נעמי ורות המואביה כלתה עמה השבה משדי מואב והמה באו בית לחם בתחלת קציר שערים׃ ");
INSERT INTO heb_vpl VALUES ("RT2_1","009_2_1","RUT","2","1","1","ולנעמי מידע לאישה איש גבור חיל ממשפחת אלימלך ושמו בעז׃ ");
INSERT INTO heb_vpl VALUES ("RT2_2","009_2_2","RUT","2","2","2","ותאמר רות המואביה אל נעמי אלכה נא השדה ואלקטה בשבלים אחר אשר אמצא חן בעיניו ותאמר לה לכי בתי׃ ");
INSERT INTO heb_vpl VALUES ("RT2_3","009_2_3","RUT","2","3","3","ותלך ותבוא ותלקט בשדה אחרי הקצרים ויקר מקרה חלקת השדה לבעז אשר ממשפחת אלימלך׃ ");
INSERT INTO heb_vpl VALUES ("RT2_4","009_2_4","RUT","2","4","4","והנה בעז בא מבית לחם ויאמר לקוצרים יהוה עמכם ויאמרו לו יברכך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("RT2_5","009_2_5","RUT","2","5","5","ויאמר בעז לנערו הנצב על הקוצרים למי הנערה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("RT2_6","009_2_6","RUT","2","6","6","ויען הנער הנצב על הקוצרים ויאמר נערה מואביה היא השבה עם נעמי משדה מואב׃ ");
INSERT INTO heb_vpl VALUES ("RT2_7","009_2_7","RUT","2","7","7","ותאמר אלקטה נא ואספתי בעמרים אחרי הקוצרים ותבוא ותעמוד מאז הבקר ועד עתה זה שבתה הבית מעט׃ ");
INSERT INTO heb_vpl VALUES ("RT2_8","009_2_8","RUT","2","8","8","ויאמר בעז אל רות הלוא שמעת בתי אל תלכי ללקט בשדה אחר וגם לא תעבורי מזה וכה תדבקין עם נערתי׃ ");
INSERT INTO heb_vpl VALUES ("RT2_9","009_2_9","RUT","2","9","9","עיניך בשדה אשר יקצרון והלכת אחריהן הלוא צויתי את הנערים לבלתי נגעך וצמת והלכת אל הכלים ושתית מאשר ישאבון הנערים׃ ");
INSERT INTO heb_vpl VALUES ("RT2_10","009_2_10","RUT","2","10","10","ותפל על פניה ותשתחו ארצה ותאמר אליו מדוע מצאתי חן בעיניך להכירני ואנכי נכריה׃ ");
INSERT INTO heb_vpl VALUES ("RT2_11","009_2_11","RUT","2","11","11","ויען בעז ויאמר לה הגד הגד לי כל אשר עשית את חמותך אחרי מות אישך ותעזבי אביך ואמך וארץ מולדתך ותלכי אל עם אשר לא ידעת תמול שלשום׃ ");
INSERT INTO heb_vpl VALUES ("RT2_12","009_2_12","RUT","2","12","12","ישלם יהוה פעלך ותהי משכרתך שלמה מעם יהוה אלהי ישראל אשר באת לחסות תחת כנפיו׃ ");
INSERT INTO heb_vpl VALUES ("RT2_13","009_2_13","RUT","2","13","13","ותאמר אמצא חן בעיניך אדני כי נחמתני וכי דברת על לב שפחתך ואנכי לא אהיה כאחת שפחתיך׃ ");
INSERT INTO heb_vpl VALUES ("RT2_14","009_2_14","RUT","2","14","14","ויאמר לה בעז לעת האכל גשי הלם ואכלת מן הלחם וטבלת פתך בחמץ ותשב מצד הקוצרים ויצבט לה קלי ותאכל ותשבע ותתר׃ ");
INSERT INTO heb_vpl VALUES ("RT2_15","009_2_15","RUT","2","15","15","ותקם ללקט ויצו בעז את נעריו לאמר גם בין העמרים תלקט ולא תכלימוה׃ ");
INSERT INTO heb_vpl VALUES ("RT2_16","009_2_16","RUT","2","16","16","וגם של תשלו לה מן הצבתים ועזבתם ולקטה ולא תגערו בה׃ ");
INSERT INTO heb_vpl VALUES ("RT2_17","009_2_17","RUT","2","17","17","ותלקט בשדה עד הערב ותחבט את אשר לקטה ויהי כאיפה שערים׃ ");
INSERT INTO heb_vpl VALUES ("RT2_18","009_2_18","RUT","2","18","18","ותשא ותבוא העיר ותרא חמותה את אשר לקטה ותוצא ותתן לה את אשר הותרה משבעה׃ ");
INSERT INTO heb_vpl VALUES ("RT2_19","009_2_19","RUT","2","19","19","ותאמר לה חמותה איפה לקטת היום ואנה עשית יהי מכירך ברוך ותגד לחמותה את אשר עשתה עמו ותאמר שם האיש אשר עשיתי עמו היום בעז׃ ");
INSERT INTO heb_vpl VALUES ("RT2_20","009_2_20","RUT","2","20","20","ותאמר נעמי לכלתה ברוך הוא ליהוה אשר לא עזב חסדו את החיים ואת המתים ותאמר לה נעמי קרוב לנו האיש מגאלנו הוא׃ ");
INSERT INTO heb_vpl VALUES ("RT2_21","009_2_21","RUT","2","21","21","ותאמר רות המואביה גם כי אמר אלי עם הנערים אשר לי תדבקין עד אם כלו את כל הקציר אשר לי׃ ");
INSERT INTO heb_vpl VALUES ("RT2_22","009_2_22","RUT","2","22","22","ותאמר נעמי אל רות כלתה טוב בתי כי תצאי עם נערותיו ולא יפגעו בך בשדה אחר׃ ");
INSERT INTO heb_vpl VALUES ("RT2_23","009_2_23","RUT","2","23","23","ותדבק בנערות בעז ללקט עד כלות קציר השערים וקציר החטים ותשב את חמותה׃ ");
INSERT INTO heb_vpl VALUES ("RT3_1","009_3_1","RUT","3","1","1","ותאמר לה נעמי חמותה בתי הלא אבקש לך מנוח אשר ייטב לך׃ ");
INSERT INTO heb_vpl VALUES ("RT3_2","009_3_2","RUT","3","2","2","ועתה הלא בעז מדעתנו אשר היית את נערותיו הנה הוא זרה את גרן השערים הלילה׃ ");
INSERT INTO heb_vpl VALUES ("RT3_3","009_3_3","RUT","3","3","3","ורחצת וסכת ושמת שמלתך עליך וירדתי הגרן אל תודעי לאיש עד כלתו לאכל ולשתות׃ ");
INSERT INTO heb_vpl VALUES ("RT3_4","009_3_4","RUT","3","4","4","ויהי בשכבו וידעת את המקום אשר ישכב שם ובאת וגלית מרגלתיו ושכבתי והוא יגיד לך את אשר תעשין׃ ");
INSERT INTO heb_vpl VALUES ("RT3_5","009_3_5","RUT","3","5","5","ותאמר אליה כל אשר תאמרי אעשה׃ ");
INSERT INTO heb_vpl VALUES ("RT3_6","009_3_6","RUT","3","6","6","ותרד הגרן ותעש ככל אשר צותה חמותה׃ ");
INSERT INTO heb_vpl VALUES ("RT3_7","009_3_7","RUT","3","7","7","ויאכל בעז וישת וייטב לבו ויבא לשכב בקצה הערמה ותבא בלט ותגל מרגלתיו ותשכב׃ ");
INSERT INTO heb_vpl VALUES ("RT3_8","009_3_8","RUT","3","8","8","ויהי בחצי הלילה ויחרד האיש וילפת והנה אשה שכבת מרגלתיו׃ ");
INSERT INTO heb_vpl VALUES ("RT3_9","009_3_9","RUT","3","9","9","ויאמר מי את ותאמר אנכי רות אמתך ופרשת כנפך על אמתך כי גאל אתה׃ ");
INSERT INTO heb_vpl VALUES ("RT3_10","009_3_10","RUT","3","10","10","ויאמר ברוכה את ליהוה בתי היטבת חסדך האחרון מן הראשון לבלתי לכת אחרי הבחורים אם דל ואם עשיר׃ ");
INSERT INTO heb_vpl VALUES ("RT3_11","009_3_11","RUT","3","11","11","ועתה בתי אל תיראי כל אשר תאמרי אעשה לך כי יודע כל שער עמי כי אשת חיל את׃ ");
INSERT INTO heb_vpl VALUES ("RT3_12","009_3_12","RUT","3","12","12","ועתה כי אמנם כי אם גאל אנכי וגם יש גאל קרוב ממני׃ ");
INSERT INTO heb_vpl VALUES ("RT3_13","009_3_13","RUT","3","13","13","ליני הלילה והיה בבקר אם יגאלך טוב יגאל ואם לא יחפץ לגאלך וגאלתיך אנכי חי יהוה שכבי עד הבקר׃ ");
INSERT INTO heb_vpl VALUES ("RT3_14","009_3_14","RUT","3","14","14","ותשכב מרגלתו עד הבקר ותקם בטרום יכיר איש את רעהו ויאמר אל יודע כי באה האשה הגרן׃ ");
INSERT INTO heb_vpl VALUES ("RT3_15","009_3_15","RUT","3","15","15","ויאמר הבי המטפחת אשר עליך ואחזי בה ותאחז בה וימד שש שערים וישת עליה ויבא העיר׃ ");
INSERT INTO heb_vpl VALUES ("RT3_16","009_3_16","RUT","3","16","16","ותבוא אל חמותה ותאמר מי את בתי ותגד לה את כל אשר עשה לה האיש׃ ");
INSERT INTO heb_vpl VALUES ("RT3_17","009_3_17","RUT","3","17","17","ותאמר שש השערים האלה נתן לי כי אמר אל תבואי ריקם אל חמותך׃ ");
INSERT INTO heb_vpl VALUES ("RT3_18","009_3_18","RUT","3","18","18","ותאמר שבי בתי עד אשר תדעין איך יפל דבר כי לא ישקט האיש כי אם כלה הדבר היום׃ ");
INSERT INTO heb_vpl VALUES ("RT4_1","009_4_1","RUT","4","1","1","ובעז עלה השער וישב שם והנה הגאל עבר אשר דבר בעז ויאמר סורה שבה פה פלני אלמני ויסר וישב׃ ");
INSERT INTO heb_vpl VALUES ("RT4_2","009_4_2","RUT","4","2","2","ויקח עשרה אנשים מזקני העיר ויאמר שבו פה וישבו׃ ");
INSERT INTO heb_vpl VALUES ("RT4_3","009_4_3","RUT","4","3","3","ויאמר לגאל חלקת השדה אשר לאחינו לאלימלך מכרה נעמי השבה משדה מואב׃ ");
INSERT INTO heb_vpl VALUES ("RT4_4","009_4_4","RUT","4","4","4","ואני אמרתי אגלה אזנך לאמר קנה נגד הישבים ונגד זקני עמי אם תגאל גאל ואם לא יגאל הגידה לי ואדע כי אין זולתך לגאול ואנכי אחריך ויאמר אנכי אגאל׃ ");
INSERT INTO heb_vpl VALUES ("RT4_5","009_4_5","RUT","4","5","5","ויאמר בעז ביום קנותך השדה מיד נעמי ומאת רות המואביה אשת המת קניתי להקים שם המת על נחלתו׃ ");
INSERT INTO heb_vpl VALUES ("RT4_6","009_4_6","RUT","4","6","6","ויאמר הגאל לא אוכל לגאול לי פן אשחית את נחלתי גאל לך אתה את גאלתי כי לא אוכל לגאל׃ ");
INSERT INTO heb_vpl VALUES ("RT4_7","009_4_7","RUT","4","7","7","וזאת לפנים בישראל על הגאולה ועל התמורה לקים כל דבר שלף איש נעלו ונתן לרעהו וזאת התעודה בישראל׃ ");
INSERT INTO heb_vpl VALUES ("RT4_8","009_4_8","RUT","4","8","8","ויאמר הגאל לבעז קנה לך וישלף נעלו׃ ");
INSERT INTO heb_vpl VALUES ("RT4_9","009_4_9","RUT","4","9","9","ויאמר בעז לזקנים וכל העם עדים אתם היום כי קניתי את כל אשר לאלימלך ואת כל אשר לכליון ומחלון מיד נעמי׃ ");
INSERT INTO heb_vpl VALUES ("RT4_10","009_4_10","RUT","4","10","10","וגם את רות המאביה אשת מחלון קניתי לי לאשה להקים שם המת על נחלתו ולא יכרת שם המת מעם אחיו ומשער מקומו עדים אתם היום׃ ");
INSERT INTO heb_vpl VALUES ("RT4_11","009_4_11","RUT","4","11","11","ויאמרו כל העם אשר בשער והזקנים עדים יתן יהוה את האשה הבאה אל ביתך כרחל וכלאה אשר בנו שתיהם את בית ישראל ועשה חיל באפרתה וקרא שם בבית לחם׃ ");
INSERT INTO heb_vpl VALUES ("RT4_12","009_4_12","RUT","4","12","12","ויהי ביתך כבית פרץ אשר ילדה תמר ליהודה מן הזרע אשר יתן יהוה לך מן הנערה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("RT4_13","009_4_13","RUT","4","13","13","ויקח בעז את רות ותהי לו לאשה ויבא אליה ויתן יהוה לה הריון ותלד בן׃ ");
INSERT INTO heb_vpl VALUES ("RT4_14","009_4_14","RUT","4","14","14","ותאמרנה הנשים אל נעמי ברוך יהוה אשר לא השבית לך גאל היום ויקרא שמו בישראל׃ ");
INSERT INTO heb_vpl VALUES ("RT4_15","009_4_15","RUT","4","15","15","והיה לך למשיב נפש ולכלכל את שיבתך כי כלתך אשר אהבתך ילדתו אשר היא טובה לך משבעה בנים׃ ");
INSERT INTO heb_vpl VALUES ("RT4_16","009_4_16","RUT","4","16","16","ותקח נעמי את הילד ותשתהו בחיקה ותהי לו לאמנת׃ ");
INSERT INTO heb_vpl VALUES ("RT4_17","009_4_17","RUT","4","17","17","ותקראנה לו השכנות שם לאמר ילד בן לנעמי ותקראנה שמו עובד הוא אבי ישי אבי דוד׃ ");
INSERT INTO heb_vpl VALUES ("RT4_18","009_4_18","RUT","4","18","18","ואלה תולדות פרץ פרץ הוליד את חצרון׃ ");
INSERT INTO heb_vpl VALUES ("RT4_19","009_4_19","RUT","4","19","19","וחצרון הוליד את רם ורם הוליד את עמינדב׃ ");
INSERT INTO heb_vpl VALUES ("RT4_20","009_4_20","RUT","4","20","20","ועמינדב הוליד את נחשון ונחשון הוליד את שלמה׃ ");
INSERT INTO heb_vpl VALUES ("RT4_21","009_4_21","RUT","4","21","21","ושלמון הוליד את בעז ובעז הוליד את עובד׃ ");
INSERT INTO heb_vpl VALUES ("RT4_22","009_4_22","RUT","4","22","22","ועבד הוליד את ישי וישי הוליד את דוד׃ ");
INSERT INTO heb_vpl VALUES ("S11_1","010_1_1","1SA","1","1","1","ויהי איש אחד מן הרמתים צופים מהר אפרים ושמו אלקנה בן ירחם בן אליהוא בן תחו בן צוף אפרתי׃ ");
INSERT INTO heb_vpl VALUES ("S11_2","010_1_2","1SA","1","2","2","ולו שתי נשים שם אחת חנה ושם השנית פננה ויהי לפננה ילדים ולחנה אין ילדים׃ ");
INSERT INTO heb_vpl VALUES ("S11_3","010_1_3","1SA","1","3","3","ועלה האיש ההוא מעירו מימים ימימה להשתחות ולזבח ליהוה צבאות בשלה ושם שני בני עלי חפני ופנחס כהנים ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S11_4","010_1_4","1SA","1","4","4","ויהי היום ויזבח אלקנה ונתן לפננה אשתו ולכל בניה ובנותיה מנות׃ ");
INSERT INTO heb_vpl VALUES ("S11_5","010_1_5","1SA","1","5","5","ולחנה יתן מנה אחת אפים כי את חנה אהב ויהוה סגר רחמה׃ ");
INSERT INTO heb_vpl VALUES ("S11_6","010_1_6","1SA","1","6","6","וכעסתה צרתה גם כעס בעבור הרעמה כי סגר יהוה בעד רחמה׃ ");
INSERT INTO heb_vpl VALUES ("S11_7","010_1_7","1SA","1","7","7","וכן יעשה שנה בשנה מדי עלתה בבית יהוה כן תכעסנה ותבכה ולא תאכל׃ ");
INSERT INTO heb_vpl VALUES ("S11_8","010_1_8","1SA","1","8","8","ויאמר לה אלקנה אישה חנה למה תבכי ולמה לא תאכלי ולמה ירע לבבך הלוא אנכי טוב לך מעשרה בנים׃ ");
INSERT INTO heb_vpl VALUES ("S11_9","010_1_9","1SA","1","9","9","ותקם חנה אחרי אכלה בשלה ואחרי שתה ועלי הכהן ישב על הכסא על מזוזת היכל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S11_10","010_1_10","1SA","1","10","10","והיא מרת נפש ותתפלל על יהוה ובכה תבכה׃ ");
INSERT INTO heb_vpl VALUES ("S11_11","010_1_11","1SA","1","11","11","ותדר נדר ותאמר יהוה צבאות אם ראה תראה בעני אמתך וזכרתני ולא תשכח את אמתך ונתתה לאמתך זרע אנשים ונתתיו ליהוה כל ימי חייו ומורה לא יעלה על ראשו׃ ");
INSERT INTO heb_vpl VALUES ("S11_12","010_1_12","1SA","1","12","12","והיה כי הרבתה להתפלל לפני יהוה ועלי שמר את פיה׃ ");
INSERT INTO heb_vpl VALUES ("S11_13","010_1_13","1SA","1","13","13","וחנה היא מדברת על לבה רק שפתיה נעות וקולה לא ישמע ויחשבה עלי לשכרה׃ ");
INSERT INTO heb_vpl VALUES ("S11_14","010_1_14","1SA","1","14","14","ויאמר אליה עלי עד מתי תשתכרין הסירי את יינך מעליך׃ ");
INSERT INTO heb_vpl VALUES ("S11_15","010_1_15","1SA","1","15","15","ותען חנה ותאמר לא אדני אשה קשת רוח אנכי ויין ושכר לא שתיתי ואשפך את נפשי לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S11_16","010_1_16","1SA","1","16","16","אל תתן את אמתך לפני בת בליעל כי מרב שיחי וכעסי דברתי עד הנה׃ ");
INSERT INTO heb_vpl VALUES ("S11_17","010_1_17","1SA","1","17","17","ויען עלי ויאמר לכי לשלום ואלהי ישראל יתן את שלתך אשר שאלת מעמו׃ ");
INSERT INTO heb_vpl VALUES ("S11_18","010_1_18","1SA","1","18","18","ותאמר תמצא שפחתך חן בעיניך ותלך האשה לדרכה ותאכל ופניה לא היו לה עוד׃ ");
INSERT INTO heb_vpl VALUES ("S11_19","010_1_19","1SA","1","19","19","וישכמו בבקר וישתחוו לפני יהוה וישבו ויבאו אל ביתם הרמתה וידע אלקנה את חנה אשתו ויזכרה יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S11_20","010_1_20","1SA","1","20","20","ויהי לתקפות הימים ותהר חנה ותלד בן ותקרא את שמו שמואל כי מיהוה שאלתיו׃ ");
INSERT INTO heb_vpl VALUES ("S11_21","010_1_21","1SA","1","21","21","ויעל האיש אלקנה וכל ביתו לזבח ליהוה את זבח הימים ואת נדרו׃ ");
INSERT INTO heb_vpl VALUES ("S11_22","010_1_22","1SA","1","22","22","וחנה לא עלתה כי אמרה לאישה עד יגמל הנער והבאתיו ונראה את פני יהוה וישב שם עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("S11_23","010_1_23","1SA","1","23","23","ויאמר לה אלקנה אישה עשי הטוב בעיניך שבי עד גמלך אתו אך יקם יהוה את דברו ותשב האשה ותינק את בנה עד גמלה אתו׃ ");
INSERT INTO heb_vpl VALUES ("S11_24","010_1_24","1SA","1","24","24","ותעלהו עמה כאשר גמלתו בפרים שלשה ואיפה אחת קמח ונבל יין ותבאהו בית יהוה שלו והנער נער׃ ");
INSERT INTO heb_vpl VALUES ("S11_25","010_1_25","1SA","1","25","25","וישחטו את הפר ויביאו את הנער אל עלי׃ ");
INSERT INTO heb_vpl VALUES ("S11_26","010_1_26","1SA","1","26","26","ותאמר בי אדני חי נפשך אדני אני האשה הנצבת עמכה בזה להתפלל אל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S11_27","010_1_27","1SA","1","27","27","אל הנער הזה התפללתי ויתן יהוה לי את שאלתי אשר שאלתי מעמו׃ ");
INSERT INTO heb_vpl VALUES ("S11_28","010_1_28","1SA","1","28","28","וגם אנכי השאלתהו ליהוה כל הימים אשר היה הוא שאול ליהוה וישתחו שם ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S12_1","010_2_1","1SA","2","1","1","ותתפלל חנה ותאמר עלץ לבי ביהוה רמה קרני ביהוה רחב פי על אויבי כי שמחתי בישועתך׃ ");
INSERT INTO heb_vpl VALUES ("S12_2","010_2_2","1SA","2","2","2","אין קדוש כיהוה כי אין בלתך ואין צור כאלהינו׃ ");
INSERT INTO heb_vpl VALUES ("S12_3","010_2_3","1SA","2","3","3","אל תרבו תדברו גבהה גבהה יצא עתק מפיכם כי אל דעות יהוה ולא נתכנו עללות׃ ");
INSERT INTO heb_vpl VALUES ("S12_4","010_2_4","1SA","2","4","4","קשת גברים חתים ונכשלים אזרו חיל׃ ");
INSERT INTO heb_vpl VALUES ("S12_5","010_2_5","1SA","2","5","5","שבעים בלחם נשכרו ורעבים חדלו עד עקרה ילדה שבעה ורבת בנים אמללה׃ ");
INSERT INTO heb_vpl VALUES ("S12_6","010_2_6","1SA","2","6","6","יהוה ממית ומחיה מוריד שאול ויעל׃ ");
INSERT INTO heb_vpl VALUES ("S12_7","010_2_7","1SA","2","7","7","יהוה מוריש ומעשיר משפיל אף מרומם׃ ");
INSERT INTO heb_vpl VALUES ("S12_8","010_2_8","1SA","2","8","8","מקים מעפר דל מאשפת ירים אביון להושיב עם נדיבים וכסא כבוד ינחלם כי ליהוה מצקי ארץ וישת עליהם תבל׃ ");
INSERT INTO heb_vpl VALUES ("S12_9","010_2_9","1SA","2","9","9","רגלי חסידו ישמר ורשעים בחשך ידמו כי לא בכח יגבר איש׃ ");
INSERT INTO heb_vpl VALUES ("S12_10","010_2_10","1SA","2","10","10","יהוה יחתו מריבו עלו בשמים ירעם יהוה ידין אפסי ארץ ויתן עז למלכו וירם קרן משיחו׃ ");
INSERT INTO heb_vpl VALUES ("S12_11","010_2_11","1SA","2","11","11","וילך אלקנה הרמתה על ביתו והנער היה משרת את יהוה את פני עלי הכהן׃ ");
INSERT INTO heb_vpl VALUES ("S12_12","010_2_12","1SA","2","12","12","ובני עלי בני בליעל לא ידעו את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S12_13","010_2_13","1SA","2","13","13","ומשפט הכהנים את העם כל איש זבח זבח ובא נער הכהן כבשל הבשר והמזלג שלש השנים בידו׃ ");
INSERT INTO heb_vpl VALUES ("S12_14","010_2_14","1SA","2","14","14","והכה בכיור או בדוד או בקלחת או בפרור כל אשר יעלה המזלג יקח הכהן בו ככה יעשו לכל ישראל הבאים שם בשלה׃ ");
INSERT INTO heb_vpl VALUES ("S12_15","010_2_15","1SA","2","15","15","גם בטרם יקטרון את החלב ובא נער הכהן ואמר לאיש הזבח תנה בשר לצלות לכהן ולא יקח ממך בשר מבשל כי אם חי׃ ");
INSERT INTO heb_vpl VALUES ("S12_16","010_2_16","1SA","2","16","16","ויאמר אליו האיש קטר יקטירון כיום החלב וקח לך כאשר תאוה נפשך ואמר לו כי עתה תתן ואם לא לקחתי בחזקה׃ ");
INSERT INTO heb_vpl VALUES ("S12_17","010_2_17","1SA","2","17","17","ותהי חטאת הנערים גדולה מאד את פני יהוה כי נאצו האנשים את מנחת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S12_18","010_2_18","1SA","2","18","18","ושמואל משרת את פני יהוה נער חגור אפוד בד׃ ");
INSERT INTO heb_vpl VALUES ("S12_19","010_2_19","1SA","2","19","19","ומעיל קטן תעשה לו אמו והעלתה לו מימים ימימה בעלותה את אישה לזבח את זבח הימים׃ ");
INSERT INTO heb_vpl VALUES ("S12_20","010_2_20","1SA","2","20","20","וברך עלי את אלקנה ואת אשתו ואמר ישם יהוה לך זרע מן האשה הזאת תחת השאלה אשר שאל ליהוה והלכו למקמו׃ ");
INSERT INTO heb_vpl VALUES ("S12_21","010_2_21","1SA","2","21","21","כי פקד יהוה את חנה ותהר ותלד שלשה בנים ושתי בנות ויגדל הנער שמואל עם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S12_22","010_2_22","1SA","2","22","22","ועלי זקן מאד ושמע את כל אשר יעשון בניו לכל ישראל ואת אשר ישכבון את הנשים הצבאות פתח אהל מועד׃ ");
INSERT INTO heb_vpl VALUES ("S12_23","010_2_23","1SA","2","23","23","ויאמר להם למה תעשון כדברים האלה אשר אנכי שמע את דבריכם רעים מאת כל העם אלה׃ ");
INSERT INTO heb_vpl VALUES ("S12_24","010_2_24","1SA","2","24","24","אל בני כי לוא טובה השמעה אשר אנכי שמע מעברים עם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S12_25","010_2_25","1SA","2","25","25","אם יחטא איש לאיש ופללו אלהים ואם ליהוה יחטא איש מי יתפלל לו ולא ישמעו לקול אביהם כי חפץ יהוה להמיתם׃ ");
INSERT INTO heb_vpl VALUES ("S12_26","010_2_26","1SA","2","26","26","והנער שמואל הלך וגדל וטוב גם עם יהוה וגם עם אנשים׃ ");
INSERT INTO heb_vpl VALUES ("S12_27","010_2_27","1SA","2","27","27","ויבא איש אלהים אל עלי ויאמר אליו כה אמר יהוה הנגלה נגליתי אל בית אביך בהיותם במצרים לבית פרעה׃ ");
INSERT INTO heb_vpl VALUES ("S12_28","010_2_28","1SA","2","28","28","ובחר אתו מכל שבטי ישראל לי לכהן לעלות על מזבחי להקטיר קטרת לשאת אפוד לפני ואתנה לבית אביך את כל אשי בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S12_29","010_2_29","1SA","2","29","29","למה תבעטו בזבחי ובמנחתי אשר צויתי מעון ותכבד את בניך ממני להבריאכם מראשית כל מנחת ישראל לעמי׃ ");
INSERT INTO heb_vpl VALUES ("S12_30","010_2_30","1SA","2","30","30","לכן נאם יהוה אלהי ישראל אמור אמרתי ביתך ובית אביך יתהלכו לפני עד עולם ועתה נאם יהוה חלילה לי כי מכבדי אכבד ובזי יקלו׃ ");
INSERT INTO heb_vpl VALUES ("S12_31","010_2_31","1SA","2","31","31","הנה ימים באים וגדעתי את זרעך ואת זרע בית אביך מהיות זקן בביתך׃ ");
INSERT INTO heb_vpl VALUES ("S12_32","010_2_32","1SA","2","32","32","והבטת צר מעון בכל אשר ייטיב את ישראל ולא יהיה זקן בביתך כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("S12_33","010_2_33","1SA","2","33","33","ואיש לא אכרית לך מעם מזבחי לכלות את עיניך ולאדיב את נפשך וכל מרבית ביתך ימותו אנשים׃ ");
INSERT INTO heb_vpl VALUES ("S12_34","010_2_34","1SA","2","34","34","וזה לך האות אשר יבא אל שני בניך אל חפני ופינחס ביום אחד ימותו שניהם׃ ");
INSERT INTO heb_vpl VALUES ("S12_35","010_2_35","1SA","2","35","35","והקימתי לי כהן נאמן כאשר בלבבי ובנפשי יעשה ובניתי לו בית נאמן והתהלך לפני משיחי כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("S12_36","010_2_36","1SA","2","36","36","והיה כל הנותר בביתך יבוא להשתחות לו לאגורת כסף וככר לחם ואמר ספחני נא אל אחת הכהנות לאכל פת לחם׃ ");
INSERT INTO heb_vpl VALUES ("S13_1","010_3_1","1SA","3","1","1","והנער שמואל משרת את יהוה לפני עלי ודבר יהוה היה יקר בימים ההם אין חזון נפרץ׃ ");
INSERT INTO heb_vpl VALUES ("S13_2","010_3_2","1SA","3","2","2","ויהי ביום ההוא ועלי שכב במקמו ועינו החלו כהות לא יוכל לראות׃ ");
INSERT INTO heb_vpl VALUES ("S13_3","010_3_3","1SA","3","3","3","ונר אלהים טרם יכבה ושמואל שכב בהיכל יהוה אשר שם ארון אלהים׃ ");
INSERT INTO heb_vpl VALUES ("S13_4","010_3_4","1SA","3","4","4","ויקרא יהוה אל שמואל ויאמר הנני׃ ");
INSERT INTO heb_vpl VALUES ("S13_5","010_3_5","1SA","3","5","5","וירץ אל עלי ויאמר הנני כי קראת לי ויאמר לא קראתי שוב שכב וילך וישכב׃ ");
INSERT INTO heb_vpl VALUES ("S13_6","010_3_6","1SA","3","6","6","ויסף יהוה קרא עוד שמואל ויקם שמואל וילך אל עלי ויאמר הנני כי קראת לי ויאמר לא קראתי בני שוב שכב׃ ");
INSERT INTO heb_vpl VALUES ("S13_7","010_3_7","1SA","3","7","7","ושמואל טרם ידע את יהוה וטרם יגלה אליו דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S13_8","010_3_8","1SA","3","8","8","ויסף יהוה קרא שמואל בשלשית ויקם וילך אל עלי ויאמר הנני כי קראת לי ויבן עלי כי יהוה קרא לנער׃ ");
INSERT INTO heb_vpl VALUES ("S13_9","010_3_9","1SA","3","9","9","ויאמר עלי לשמואל לך שכב והיה אם יקרא אליך ואמרת דבר יהוה כי שמע עבדך וילך שמואל וישכב במקומו׃ ");
INSERT INTO heb_vpl VALUES ("S13_10","010_3_10","1SA","3","10","10","ויבא יהוה ויתיצב ויקרא כפעם בפעם שמואל שמואל ויאמר שמואל דבר כי שמע עבדך׃ ");
INSERT INTO heb_vpl VALUES ("S13_11","010_3_11","1SA","3","11","11","ויאמר יהוה אל שמואל הנה אנכי עשה דבר בישראל אשר כל שמעו תצלינה שתי אזניו׃ ");
INSERT INTO heb_vpl VALUES ("S13_12","010_3_12","1SA","3","12","12","ביום ההוא אקים אל עלי את כל אשר דברתי אל ביתו החל וכלה׃ ");
INSERT INTO heb_vpl VALUES ("S13_13","010_3_13","1SA","3","13","13","והגדתי לו כי שפט אני את ביתו עד עולם בעון אשר ידע כי מקללים להם בניו ולא כהה בם׃ ");
INSERT INTO heb_vpl VALUES ("S13_14","010_3_14","1SA","3","14","14","ולכן נשבעתי לבית עלי אם יתכפר עון בית עלי בזבח ובמנחה עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("S13_15","010_3_15","1SA","3","15","15","וישכב שמואל עד הבקר ויפתח את דלתות בית יהוה ושמואל ירא מהגיד את המראה אל עלי׃ ");
INSERT INTO heb_vpl VALUES ("S13_16","010_3_16","1SA","3","16","16","ויקרא עלי את שמואל ויאמר שמואל בני ויאמר הנני׃ ");
INSERT INTO heb_vpl VALUES ("S13_17","010_3_17","1SA","3","17","17","ויאמר מה הדבר אשר דבר אליך אל נא תכחד ממני כה יעשה לך אלהים וכה יוסיף אם תכחד ממני דבר מכל הדבר אשר דבר אליך׃ ");
INSERT INTO heb_vpl VALUES ("S13_18","010_3_18","1SA","3","18","18","ויגד לו שמואל את כל הדברים ולא כחד ממנו ויאמר יהוה הוא הטוב בעינו יעשה׃ ");
INSERT INTO heb_vpl VALUES ("S13_19","010_3_19","1SA","3","19","19","ויגדל שמואל ויהוה היה עמו ולא הפיל מכל דבריו ארצה׃ ");
INSERT INTO heb_vpl VALUES ("S13_20","010_3_20","1SA","3","20","20","וידע כל ישראל מדן ועד באר שבע כי נאמן שמואל לנביא ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S13_21","010_3_21","1SA","3","21","21","ויסף יהוה להראה בשלה כי נגלה יהוה אל שמואל בשלו בדבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S14_1","010_4_1","1SA","4","1","1","ויהי דבר שמואל לכל ישראל ויצא ישראל לקראת פלשתים למלחמה ויחנו על האבן העזר ופלשתים חנו באפק׃ ");
INSERT INTO heb_vpl VALUES ("S14_2","010_4_2","1SA","4","2","2","ויערכו פלשתים לקראת ישראל ותטש המלחמה וינגף ישראל לפני פלשתים ויכו במערכה בשדה כארבעת אלפים איש׃ ");
INSERT INTO heb_vpl VALUES ("S14_3","010_4_3","1SA","4","3","3","ויבא העם אל המחנה ויאמרו זקני ישראל למה נגפנו יהוה היום לפני פלשתים נקחה אלינו משלה את ארון ברית יהוה ויבא בקרבנו וישענו מכף איבינו׃ ");
INSERT INTO heb_vpl VALUES ("S14_4","010_4_4","1SA","4","4","4","וישלח העם שלה וישאו משם את ארון ברית יהוה צבאות ישב הכרבים ושם שני בני עלי עם ארון ברית האלהים חפני ופינחס׃ ");
INSERT INTO heb_vpl VALUES ("S14_5","010_4_5","1SA","4","5","5","ויהי כבוא ארון ברית יהוה אל המחנה וירעו כל ישראל תרועה גדולה ותהם הארץ׃ ");
INSERT INTO heb_vpl VALUES ("S14_6","010_4_6","1SA","4","6","6","וישמעו פלשתים את קול התרועה ויאמרו מה קול התרועה הגדולה הזאת במחנה העברים וידעו כי ארון יהוה בא אל המחנה׃ ");
INSERT INTO heb_vpl VALUES ("S14_7","010_4_7","1SA","4","7","7","ויראו הפלשתים כי אמרו בא אלהים אל המחנה ויאמרו אוי לנו כי לא היתה כזאת אתמול שלשם׃ ");
INSERT INTO heb_vpl VALUES ("S14_8","010_4_8","1SA","4","8","8","אוי לנו מי יצילנו מיד האלהים האדירים האלה אלה הם האלהים המכים את מצרים בכל מכה במדבר׃ ");
INSERT INTO heb_vpl VALUES ("S14_9","010_4_9","1SA","4","9","9","התחזקו והיו לאנשים פלשתים פן תעבדו לעברים כאשר עבדו לכם והייתם לאנשים ונלחמתם׃ ");
INSERT INTO heb_vpl VALUES ("S14_10","010_4_10","1SA","4","10","10","וילחמו פלשתים וינגף ישראל וינסו איש לאהליו ותהי המכה גדולה מאד ויפל מישראל שלשים אלף רגלי׃ ");
INSERT INTO heb_vpl VALUES ("S14_11","010_4_11","1SA","4","11","11","וארון אלהים נלקח ושני בני עלי מתו חפני ופינחס׃ ");
INSERT INTO heb_vpl VALUES ("S14_12","010_4_12","1SA","4","12","12","וירץ איש בנימן מהמערכה ויבא שלה ביום ההוא ומדיו קרעים ואדמה על ראשו׃ ");
INSERT INTO heb_vpl VALUES ("S14_13","010_4_13","1SA","4","13","13","ויבוא והנה עלי ישב על הכסא יך דרך מצפה כי היה לבו חרד על ארון האלהים והאיש בא להגיד בעיר ותזעק כל העיר׃ ");
INSERT INTO heb_vpl VALUES ("S14_14","010_4_14","1SA","4","14","14","וישמע עלי את קול הצעקה ויאמר מה קול ההמון הזה והאיש מהר ויבא ויגד לעלי׃ ");
INSERT INTO heb_vpl VALUES ("S14_15","010_4_15","1SA","4","15","15","ועלי בן תשעים ושמנה שנה ועיניו קמה ולא יכול לראות׃ ");
INSERT INTO heb_vpl VALUES ("S14_16","010_4_16","1SA","4","16","16","ויאמר האיש אל עלי אנכי הבא מן המערכה ואני מן המערכה נסתי היום ויאמר מה היה הדבר בני׃ ");
INSERT INTO heb_vpl VALUES ("S14_17","010_4_17","1SA","4","17","17","ויען המבשר ויאמר נס ישראל לפני פלשתים וגם מגפה גדולה היתה בעם וגם שני בניך מתו חפני ופינחס וארון האלהים נלקחה׃ ");
INSERT INTO heb_vpl VALUES ("S14_18","010_4_18","1SA","4","18","18","ויהי כהזכירו את ארון האלהים ויפל מעל הכסא אחרנית בעד יד השער ותשבר מפרקתו וימת כי זקן האיש וכבד והוא שפט את ישראל ארבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("S14_19","010_4_19","1SA","4","19","19","וכלתו אשת פינחס הרה ללת ותשמע את השמעה אל הלקח ארון האלהים ומת חמיה ואישה ותכרע ותלד כי נהפכו עליה צריה׃ ");
INSERT INTO heb_vpl VALUES ("S14_20","010_4_20","1SA","4","20","20","וכעת מותה ותדברנה הנצבות עליה אל תיראי כי בן ילדת ולא ענתה ולא שתה לבה׃ ");
INSERT INTO heb_vpl VALUES ("S14_21","010_4_21","1SA","4","21","21","ותקרא לנער אי כבוד לאמר גלה כבוד מישראל אל הלקח ארון האלהים ואל חמיה ואישה׃ ");
INSERT INTO heb_vpl VALUES ("S14_22","010_4_22","1SA","4","22","22","ותאמר גלה כבוד מישראל כי נלקח ארון האלהים׃ ");
INSERT INTO heb_vpl VALUES ("S15_1","010_5_1","1SA","5","1","1","ופלשתים לקחו את ארון האלהים ויבאהו מאבן העזר אשדודה׃ ");
INSERT INTO heb_vpl VALUES ("S15_2","010_5_2","1SA","5","2","2","ויקחו פלשתים את ארון האלהים ויביאו אתו בית דגון ויציגו אתו אצל דגון׃ ");
INSERT INTO heb_vpl VALUES ("S15_3","010_5_3","1SA","5","3","3","וישכמו אשדודים ממחרת והנה דגון נפל לפניו ארצה לפני ארון יהוה ויקחו את דגון וישבו אתו למקומו׃ ");
INSERT INTO heb_vpl VALUES ("S15_4","010_5_4","1SA","5","4","4","וישכמו בבקר ממחרת והנה דגון נפל לפניו ארצה לפני ארון יהוה וראש דגון ושתי כפות ידיו כרתות אל המפתן רק דגון נשאר עליו׃ ");
INSERT INTO heb_vpl VALUES ("S15_5","010_5_5","1SA","5","5","5","על כן לא ידרכו כהני דגון וכל הבאים בית דגון על מפתן דגון באשדוד עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S15_6","010_5_6","1SA","5","6","6","ותכבד יד יהוה אל האשדודים וישמם ויך אתם בעפלים את אשדוד ואת גבוליה׃ ");
INSERT INTO heb_vpl VALUES ("S15_7","010_5_7","1SA","5","7","7","ויראו אנשי אשדוד כי כן ואמרו לא ישב ארון אלהי ישראל עמנו כי קשתה ידו עלינו ועל דגון אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("S15_8","010_5_8","1SA","5","8","8","וישלחו ויאספו את כל סרני פלשתים אליהם ויאמרו מה נעשה לארון אלהי ישראל ויאמרו גת יסב ארון אלהי ישראל ויסבו את ארון אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S15_9","010_5_9","1SA","5","9","9","ויהי אחרי הסבו אתו ותהי יד יהוה בעיר מהומה גדולה מאד ויך את אנשי העיר מקטן ועד גדול וישתרו להם עפלים׃ ");
INSERT INTO heb_vpl VALUES ("S15_10","010_5_10","1SA","5","10","10","וישלחו את ארון האלהים עקרון ויהי כבוא ארון האלהים עקרון ויזעקו העקרנים לאמר הסבו אלי את ארון אלהי ישראל להמיתני ואת עמי׃ ");
INSERT INTO heb_vpl VALUES ("S15_11","010_5_11","1SA","5","11","11","וישלחו ויאספו את כל סרני פלשתים ויאמרו שלחו את ארון אלהי ישראל וישב למקמו ולא ימית אתי ואת עמי כי היתה מהומת מות בכל העיר כבדה מאד יד האלהים שם׃ ");
INSERT INTO heb_vpl VALUES ("S15_12","010_5_12","1SA","5","12","12","והאנשים אשר לא מתו הכו בעפלים ותעל שועת העיר השמים׃ ");
INSERT INTO heb_vpl VALUES ("S16_1","010_6_1","1SA","6","1","1","ויהי ארון יהוה בשדה פלשתים שבעה חדשים׃ ");
INSERT INTO heb_vpl VALUES ("S16_2","010_6_2","1SA","6","2","2","ויקראו פלשתים לכהנים ולקסמים לאמר מה נעשה לארון יהוה הודענו במה נשלחנו למקומו׃ ");
INSERT INTO heb_vpl VALUES ("S16_3","010_6_3","1SA","6","3","3","ויאמרו אם משלחים את ארון אלהי ישראל אל תשלחו אתו ריקם כי השב תשיבו לו אשם אז תרפאו ונודע לכם למה לא תסור ידו מכם׃ ");
INSERT INTO heb_vpl VALUES ("S16_4","010_6_4","1SA","6","4","4","ויאמרו מה האשם אשר נשיב לו ויאמרו מספר סרני פלשתים חמשה עפלי זהב וחמשה עכברי זהב כי מגפה אחת לכלם ולסרניכם׃ ");
INSERT INTO heb_vpl VALUES ("S16_5","010_6_5","1SA","6","5","5","ועשיתם צלמי עפליכם וצלמי עכבריכם המשחיתם את הארץ ונתתם לאלהי ישראל כבוד אולי יקל את ידו מעליכם ומעל אלהיכם ומעל ארצכם׃ ");
INSERT INTO heb_vpl VALUES ("S16_6","010_6_6","1SA","6","6","6","ולמה תכבדו את לבבכם כאשר כבדו מצרים ופרעה את לבם הלוא כאשר התעלל בהם וישלחום וילכו׃ ");
INSERT INTO heb_vpl VALUES ("S16_7","010_6_7","1SA","6","7","7","ועתה קחו ועשו עגלה חדשה אחת ושתי פרות עלות אשר לא עלה עליהם על ואסרתם את הפרות בעגלה והשיבתם בניהם מאחריהם הביתה׃ ");
INSERT INTO heb_vpl VALUES ("S16_8","010_6_8","1SA","6","8","8","ולקחתם את ארון יהוה ונתתם אתו אל העגלה ואת כלי הזהב אשר השבתם לו אשם תשימו בארגז מצדו ושלחתם אתו והלך׃ ");
INSERT INTO heb_vpl VALUES ("S16_9","010_6_9","1SA","6","9","9","וראיתם אם דרך גבולו יעלה בית שמש הוא עשה לנו את הרעה הגדולה הזאת ואם לא וידענו כי לא ידו נגעה בנו מקרה הוא היה לנו׃ ");
INSERT INTO heb_vpl VALUES ("S16_10","010_6_10","1SA","6","10","10","ויעשו האנשים כן ויקחו שתי פרות עלות ויאסרום בעגלה ואת בניהם כלו בבית׃ ");
INSERT INTO heb_vpl VALUES ("S16_11","010_6_11","1SA","6","11","11","וישמו את ארון יהוה אל העגלה ואת הארגז ואת עכברי הזהב ואת צלמי טחריהם׃ ");
INSERT INTO heb_vpl VALUES ("S16_12","010_6_12","1SA","6","12","12","וישרנה הפרות בדרך על דרך בית שמש במסלה אחת הלכו הלך וגעו ולא סרו ימין ושמאול וסרני פלשתים הלכים אחריהם עד גבול בית שמש׃ ");
INSERT INTO heb_vpl VALUES ("S16_13","010_6_13","1SA","6","13","13","ובית שמש קצרים קציר חטים בעמק וישאו את עיניהם ויראו את הארון וישמחו לראות׃ ");
INSERT INTO heb_vpl VALUES ("S16_14","010_6_14","1SA","6","14","14","והעגלה באה אל שדה יהושע בית השמשי ותעמד שם ושם אבן גדולה ויבקעו את עצי העגלה ואת הפרות העלו עלה ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S16_15","010_6_15","1SA","6","15","15","והלוים הורידו את ארון יהוה ואת הארגז אשר אתו אשר בו כלי זהב וישמו אל האבן הגדולה ואנשי בית שמש העלו עלות ויזבחו זבחים ביום ההוא ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S16_16","010_6_16","1SA","6","16","16","וחמשה סרני פלשתים ראו וישבו עקרון ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("S16_17","010_6_17","1SA","6","17","17","ואלה טחרי הזהב אשר השיבו פלשתים אשם ליהוה לאשדוד אחד לעזה אחד לאשקלון אחד לגת אחד לעקרון אחד׃ ");
INSERT INTO heb_vpl VALUES ("S16_18","010_6_18","1SA","6","18","18","ועכברי הזהב מספר כל ערי פלשתים לחמשת הסרנים מעיר מבצר ועד כפר הפרזי ועד אבל הגדולה אשר הניחו עליה את ארון יהוה עד היום הזה בשדה יהושע בית השמשי׃ ");
INSERT INTO heb_vpl VALUES ("S16_19","010_6_19","1SA","6","19","19","ויך באנשי בית שמש כי ראו בארון יהוה ויך בעם שבעים איש חמשים אלף איש ויתאבלו העם כי הכה יהוה בעם מכה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("S16_20","010_6_20","1SA","6","20","20","ויאמרו אנשי בית שמש מי יוכל לעמד לפני יהוה האלהים הקדוש הזה ואל מי יעלה מעלינו׃ ");
INSERT INTO heb_vpl VALUES ("S16_21","010_6_21","1SA","6","21","21","וישלחו מלאכים אל יושבי קרית יערים לאמר השבו פלשתים את ארון יהוה רדו העלו אתו אליכם׃ ");
INSERT INTO heb_vpl VALUES ("S17_1","010_7_1","1SA","7","1","1","ויבאו אנשי קרית יערים ויעלו את ארון יהוה ויבאו אתו אל בית אבינדב בגבעה ואת אלעזר בנו קדשו לשמר את ארון יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S17_2","010_7_2","1SA","7","2","2","ויהי מיום שבת הארון בקרית יערים וירבו הימים ויהיו עשרים שנה וינהו כל בית ישראל אחרי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S17_3","010_7_3","1SA","7","3","3","ויאמר שמואל אל כל בית ישראל לאמר אם בכל לבבכם אתם שבים אל יהוה הסירו את אלהי הנכר מתוככם והעשתרות והכינו לבבכם אל יהוה ועבדהו לבדו ויצל אתכם מיד פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S17_4","010_7_4","1SA","7","4","4","ויסירו בני ישראל את הבעלים ואת העשתרת ויעבדו את יהוה לבדו׃ ");
INSERT INTO heb_vpl VALUES ("S17_5","010_7_5","1SA","7","5","5","ויאמר שמואל קבצו את כל ישראל המצפתה ואתפלל בעדכם אל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S17_6","010_7_6","1SA","7","6","6","ויקבצו המצפתה וישאבו מים וישפכו לפני יהוה ויצומו ביום ההוא ויאמרו שם חטאנו ליהוה וישפט שמואל את בני ישראל במצפה׃ ");
INSERT INTO heb_vpl VALUES ("S17_7","010_7_7","1SA","7","7","7","וישמעו פלשתים כי התקבצו בני ישראל המצפתה ויעלו סרני פלשתים אל ישראל וישמעו בני ישראל ויראו מפני פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S17_8","010_7_8","1SA","7","8","8","ויאמרו בני ישראל אל שמואל אל תחרש ממנו מזעק אל יהוה אלהינו וישענו מיד פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S17_9","010_7_9","1SA","7","9","9","ויקח שמואל טלה חלב אחד ויעלה עולה כליל ליהוה ויזעק שמואל אל יהוה בעד ישראל ויענהו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S17_10","010_7_10","1SA","7","10","10","ויהי שמואל מעלה העולה ופלשתים נגשו למלחמה בישראל וירעם יהוה בקול גדול ביום ההוא על פלשתים ויהמם וינגפו לפני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S17_11","010_7_11","1SA","7","11","11","ויצאו אנשי ישראל מן המצפה וירדפו את פלשתים ויכום עד מתחת לבית כר׃ ");
INSERT INTO heb_vpl VALUES ("S17_12","010_7_12","1SA","7","12","12","ויקח שמואל אבן אחת וישם בין המצפה ובין השן ויקרא את שמה אבן העזר ויאמר עד הנה עזרנו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S17_13","010_7_13","1SA","7","13","13","ויכנעו הפלשתים ולא יספו עוד לבוא בגבול ישראל ותהי יד יהוה בפלשתים כל ימי שמואל׃ ");
INSERT INTO heb_vpl VALUES ("S17_14","010_7_14","1SA","7","14","14","ותשבנה הערים אשר לקחו פלשתים מאת ישראל לישראל מעקרון ועד גת ואת גבולן הציל ישראל מיד פלשתים ויהי שלום בין ישראל ובין האמרי׃ ");
INSERT INTO heb_vpl VALUES ("S17_15","010_7_15","1SA","7","15","15","וישפט שמואל את ישראל כל ימי חייו׃ ");
INSERT INTO heb_vpl VALUES ("S17_16","010_7_16","1SA","7","16","16","והלך מדי שנה בשנה וסבב בית אל והגלגל והמצפה ושפט את ישראל את כל המקומות האלה׃ ");
INSERT INTO heb_vpl VALUES ("S17_17","010_7_17","1SA","7","17","17","ותשבתו הרמתה כי שם ביתו ושם שפט את ישראל ויבן שם מזבח ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S18_1","010_8_1","1SA","8","1","1","ויהי כאשר זקן שמואל וישם את בניו שפטים לישראל׃ ");
INSERT INTO heb_vpl VALUES ("S18_2","010_8_2","1SA","8","2","2","ויהי שם בנו הבכור יואל ושם משנהו אביה שפטים בבאר שבע׃ ");
INSERT INTO heb_vpl VALUES ("S18_3","010_8_3","1SA","8","3","3","ולא הלכו בניו בדרכו ויטו אחרי הבצע ויקחו שחד ויטו משפט׃ ");
INSERT INTO heb_vpl VALUES ("S18_4","010_8_4","1SA","8","4","4","ויתקבצו כל זקני ישראל ויבאו אל שמואל הרמתה׃ ");
INSERT INTO heb_vpl VALUES ("S18_5","010_8_5","1SA","8","5","5","ויאמרו אליו הנה אתה זקנת ובניך לא הלכו בדרכיך עתה שימה לנו מלך לשפטנו ככל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("S18_6","010_8_6","1SA","8","6","6","וירע הדבר בעיני שמואל כאשר אמרו תנה לנו מלך לשפטנו ויתפלל שמואל אל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S18_7","010_8_7","1SA","8","7","7","ויאמר יהוה אל שמואל שמע בקול העם לכל אשר יאמרו אליך כי לא אתך מאסו כי אתי מאסו ממלך עליהם׃ ");
INSERT INTO heb_vpl VALUES ("S18_8","010_8_8","1SA","8","8","8","ככל המעשים אשר עשו מיום העלתי אתם ממצרים ועד היום הזה ויעזבני ויעבדו אלהים אחרים כן המה עשים גם לך׃ ");
INSERT INTO heb_vpl VALUES ("S18_9","010_8_9","1SA","8","9","9","ועתה שמע בקולם אך כי העד תעיד בהם והגדת להם משפט המלך אשר ימלך עליהם׃ ");
INSERT INTO heb_vpl VALUES ("S18_10","010_8_10","1SA","8","10","10","ויאמר שמואל את כל דברי יהוה אל העם השאלים מאתו מלך׃ ");
INSERT INTO heb_vpl VALUES ("S18_11","010_8_11","1SA","8","11","11","ויאמר זה יהיה משפט המלך אשר ימלך עליכם את בניכם יקח ושם לו במרכבתו ובפרשיו ורצו לפני מרכבתו׃ ");
INSERT INTO heb_vpl VALUES ("S18_12","010_8_12","1SA","8","12","12","ולשום לו שרי אלפים ושרי חמשים ולחרש חרישו ולקצר קצירו ולעשות כלי מלחמתו וכלי רכבו׃ ");
INSERT INTO heb_vpl VALUES ("S18_13","010_8_13","1SA","8","13","13","ואת בנותיכם יקח לרקחות ולטבחות ולאפות׃ ");
INSERT INTO heb_vpl VALUES ("S18_14","010_8_14","1SA","8","14","14","ואת שדותיכם ואת כרמיכם וזיתיכם הטובים יקח ונתן לעבדיו׃ ");
INSERT INTO heb_vpl VALUES ("S18_15","010_8_15","1SA","8","15","15","וזרעיכם וכרמיכם יעשר ונתן לסריסיו ולעבדיו׃ ");
INSERT INTO heb_vpl VALUES ("S18_16","010_8_16","1SA","8","16","16","ואת עבדיכם ואת שפחותיכם ואת בחוריכם הטובים ואת חמוריכם יקח ועשה למלאכתו׃ ");
INSERT INTO heb_vpl VALUES ("S18_17","010_8_17","1SA","8","17","17","צאנכם יעשר ואתם תהיו לו לעבדים׃ ");
INSERT INTO heb_vpl VALUES ("S18_18","010_8_18","1SA","8","18","18","וזעקתם ביום ההוא מלפני מלככם אשר בחרתם לכם ולא יענה יהוה אתכם ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("S18_19","010_8_19","1SA","8","19","19","וימאנו העם לשמע בקול שמואל ויאמרו לא כי אם מלך יהיה עלינו׃ ");
INSERT INTO heb_vpl VALUES ("S18_20","010_8_20","1SA","8","20","20","והיינו גם אנחנו ככל הגוים ושפטנו מלכנו ויצא לפנינו ונלחם את מלחמתנו׃ ");
INSERT INTO heb_vpl VALUES ("S18_21","010_8_21","1SA","8","21","21","וישמע שמואל את כל דברי העם וידברם באזני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S18_22","010_8_22","1SA","8","22","22","ויאמר יהוה אל שמואל שמע בקולם והמלכת להם מלך ויאמר שמואל אל אנשי ישראל לכו איש לעירו׃ ");
INSERT INTO heb_vpl VALUES ("S19_1","010_9_1","1SA","9","1","1","ויהי איש מבן ימין ושמו קיש בן אביאל בן צרור בן בכורת בן אפיח בן איש ימיני גבור חיל׃ ");
INSERT INTO heb_vpl VALUES ("S19_2","010_9_2","1SA","9","2","2","ולו היה בן ושמו שאול בחור וטוב ואין איש מבני ישראל טוב ממנו משכמו ומעלה גבה מכל העם׃ ");
INSERT INTO heb_vpl VALUES ("S19_3","010_9_3","1SA","9","3","3","ותאבדנה האתנות לקיש אבי שאול ויאמר קיש אל שאול בנו קח נא אתך את אחד מהנערים וקום לך בקש את האתנת׃ ");
INSERT INTO heb_vpl VALUES ("S19_4","010_9_4","1SA","9","4","4","ויעבר בהר אפרים ויעבר בארץ שלשה ולא מצאו ויעברו בארץ שעלים ואין ויעבר בארץ ימיני ולא מצאו׃ ");
INSERT INTO heb_vpl VALUES ("S19_5","010_9_5","1SA","9","5","5","המה באו בארץ צוף ושאול אמר לנערו אשר עמו לכה ונשובה פן יחדל אבי מן האתנות ודאג לנו׃ ");
INSERT INTO heb_vpl VALUES ("S19_6","010_9_6","1SA","9","6","6","ויאמר לו הנה נא איש אלהים בעיר הזאת והאיש נכבד כל אשר ידבר בוא יבוא עתה נלכה שם אולי יגיד לנו את דרכנו אשר הלכנו עליה׃ ");
INSERT INTO heb_vpl VALUES ("S19_7","010_9_7","1SA","9","7","7","ויאמר שאול לנערו והנה נלך ומה נביא לאיש כי הלחם אזל מכלינו ותשורה אין להביא לאיש האלהים מה אתנו׃ ");
INSERT INTO heb_vpl VALUES ("S19_8","010_9_8","1SA","9","8","8","ויסף הנער לענות את שאול ויאמר הנה נמצא בידי רבע שקל כסף ונתתי לאיש האלהים והגיד לנו את דרכנו׃ ");
INSERT INTO heb_vpl VALUES ("S19_9","010_9_9","1SA","9","9","9","לפנים בישראל כה אמר האיש בלכתו לדרוש אלהים לכו ונלכה עד הראה כי לנביא היום יקרא לפנים הראה׃ ");
INSERT INTO heb_vpl VALUES ("S19_10","010_9_10","1SA","9","10","10","ויאמר שאול לנערו טוב דברך לכה נלכה וילכו אל העיר אשר שם איש האלהים׃ ");
INSERT INTO heb_vpl VALUES ("S19_11","010_9_11","1SA","9","11","11","המה עלים במעלה העיר והמה מצאו נערות יצאות לשאב מים ויאמרו להן היש בזה הראה׃ ");
INSERT INTO heb_vpl VALUES ("S19_12","010_9_12","1SA","9","12","12","ותענינה אותם ותאמרנה יש הנה לפניך מהר עתה כי היום בא לעיר כי זבח היום לעם בבמה׃ ");
INSERT INTO heb_vpl VALUES ("S19_13","010_9_13","1SA","9","13","13","כבאכם העיר כן תמצאון אתו בטרם יעלה הבמתה לאכל כי לא יאכל העם עד באו כי הוא יברך הזבח אחרי כן יאכלו הקראים ועתה עלו כי אתו כהיום תמצאון אתו׃ ");
INSERT INTO heb_vpl VALUES ("S19_14","010_9_14","1SA","9","14","14","ויעלו העיר המה באים בתוך העיר והנה שמואל יצא לקראתם לעלות הבמה׃ ");
INSERT INTO heb_vpl VALUES ("S19_15","010_9_15","1SA","9","15","15","ויהוה גלה את אזן שמואל יום אחד לפני בוא שאול לאמר׃ ");
INSERT INTO heb_vpl VALUES ("S19_16","010_9_16","1SA","9","16","16","כעת מחר אשלח אליך איש מארץ בנימן ומשחתו לנגיד על עמי ישראל והושיע את עמי מיד פלשתים כי ראיתי את עמי כי באה צעקתו אלי׃ ");
INSERT INTO heb_vpl VALUES ("S19_17","010_9_17","1SA","9","17","17","ושמואל ראה את שאול ויהוה ענהו הנה האיש אשר אמרתי אליך זה יעצר בעמי׃ ");
INSERT INTO heb_vpl VALUES ("S19_18","010_9_18","1SA","9","18","18","ויגש שאול את שמואל בתוך השער ויאמר הגידה נא לי אי זה בית הראה׃ ");
INSERT INTO heb_vpl VALUES ("S19_19","010_9_19","1SA","9","19","19","ויען שמואל את שאול ויאמר אנכי הראה עלה לפני הבמה ואכלתם עמי היום ושלחתיך בבקר וכל אשר בלבבך אגיד לך׃ ");
INSERT INTO heb_vpl VALUES ("S19_20","010_9_20","1SA","9","20","20","ולאתנות האבדות לך היום שלשת הימים אל תשם את לבך להם כי נמצאו ולמי כל חמדת ישראל הלוא לך ולכל בית אביך׃ ");
INSERT INTO heb_vpl VALUES ("S19_21","010_9_21","1SA","9","21","21","ויען שאול ויאמר הלוא בן ימיני אנכי מקטני שבטי ישראל ומשפחתי הצערה מכל משפחות שבטי בנימן ולמה דברת אלי כדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("S19_22","010_9_22","1SA","9","22","22","ויקח שמואל את שאול ואת נערו ויביאם לשכתה ויתן להם מקום בראש הקרואים והמה כשלשים איש׃ ");
INSERT INTO heb_vpl VALUES ("S19_23","010_9_23","1SA","9","23","23","ויאמר שמואל לטבח תנה את המנה אשר נתתי לך אשר אמרתי אליך שים אתה עמך׃ ");
INSERT INTO heb_vpl VALUES ("S19_24","010_9_24","1SA","9","24","24","וירם הטבח את השוק והעליה וישם לפני שאול ויאמר הנה הנשאר שים לפניך אכל כי למועד שמור לך לאמר העם קראתי ויאכל שאול עם שמואל ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("S19_25","010_9_25","1SA","9","25","25","וירדו מהבמה העיר וידבר עם שאול על הגג׃ ");
INSERT INTO heb_vpl VALUES ("S19_26","010_9_26","1SA","9","26","26","וישכמו ויהי כעלות השחר ויקרא שמואל אל שאול הגג לאמר קומה ואשלחך ויקם שאול ויצאו שניהם הוא ושמואל החוצה׃ ");
INSERT INTO heb_vpl VALUES ("S19_27","010_9_27","1SA","9","27","27","המה יורדים בקצה העיר ושמואל אמר אל שאול אמר לנער ויעבר לפנינו ויעבר ואתה עמד כיום ואשמיעך את דבר אלהים׃ ");
INSERT INTO heb_vpl VALUES ("S110_1","010_10_1","1SA","10","1","1","ויקח שמואל את פך השמן ויצק על ראשו וישקהו ויאמר הלוא כי משחך יהוה על נחלתו לנגיד׃ ");
INSERT INTO heb_vpl VALUES ("S110_2","010_10_2","1SA","10","2","2","בלכתך היום מעמדי ומצאת שני אנשים עם קברת רחל בגבול בנימן בצלצח ואמרו אליך נמצאו האתנות אשר הלכת לבקש והנה נטש אביך את דברי האתנות ודאג לכם לאמר מה אעשה לבני׃ ");
INSERT INTO heb_vpl VALUES ("S110_3","010_10_3","1SA","10","3","3","וחלפת משם והלאה ובאת עד אלון תבור ומצאוך שם שלשה אנשים עלים אל האלהים בית אל אחד נשא שלשה גדיים ואחד נשא שלשת ככרות לחם ואחד נשא נבל יין׃ ");
INSERT INTO heb_vpl VALUES ("S110_4","010_10_4","1SA","10","4","4","ושאלו לך לשלום ונתנו לך שתי לחם ולקחת מידם׃ ");
INSERT INTO heb_vpl VALUES ("S110_5","010_10_5","1SA","10","5","5","אחר כן תבוא גבעת האלהים אשר שם נצבי פלשתים ויהי כבאך שם העיר ופגעת חבל נביאים ירדים מהבמה ולפניהם נבל ותף וחליל וכנור והמה מתנבאים׃ ");
INSERT INTO heb_vpl VALUES ("S110_6","010_10_6","1SA","10","6","6","וצלחה עליך רוח יהוה והתנבית עמם ונהפכת לאיש אחר׃ ");
INSERT INTO heb_vpl VALUES ("S110_7","010_10_7","1SA","10","7","7","והיה כי תבאינה האתות האלה לך עשה לך אשר תמצא ידך כי האלהים עמך׃ ");
INSERT INTO heb_vpl VALUES ("S110_8","010_10_8","1SA","10","8","8","וירדת לפני הגלגל והנה אנכי ירד אליך להעלות עלות לזבח זבחי שלמים שבעת ימים תוחל עד בואי אליך והודעתי לך את אשר תעשה׃ ");
INSERT INTO heb_vpl VALUES ("S110_9","010_10_9","1SA","10","9","9","והיה כהפנתו שכמו ללכת מעם שמואל ויהפך לו אלהים לב אחר ויבאו כל האתות האלה ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("S110_10","010_10_10","1SA","10","10","10","ויבאו שם הגבעתה והנה חבל נבאים לקראתו ותצלח עליו רוח אלהים ויתנבא בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("S110_11","010_10_11","1SA","10","11","11","ויהי כל יודעו מאתמול שלשום ויראו והנה עם נבאים נבא ויאמר העם איש אל רעהו מה זה היה לבן קיש הגם שאול בנביאים׃ ");
INSERT INTO heb_vpl VALUES ("S110_12","010_10_12","1SA","10","12","12","ויען איש משם ויאמר ומי אביהם על כן היתה למשל הגם שאול בנבאים׃ ");
INSERT INTO heb_vpl VALUES ("S110_13","010_10_13","1SA","10","13","13","ויכל מהתנבות ויבא הבמה׃ ");
INSERT INTO heb_vpl VALUES ("S110_14","010_10_14","1SA","10","14","14","ויאמר דוד שאול אליו ואל נערו אן הלכתם ויאמר לבקש את האתנות ונראה כי אין ונבוא אל שמואל׃ ");
INSERT INTO heb_vpl VALUES ("S110_15","010_10_15","1SA","10","15","15","ויאמר דוד שאול הגידה נא לי מה אמר לכם שמואל׃ ");
INSERT INTO heb_vpl VALUES ("S110_16","010_10_16","1SA","10","16","16","ויאמר שאול אל דודו הגד הגיד לנו כי נמצאו האתנות ואת דבר המלוכה לא הגיד לו אשר אמר שמואל׃ ");
INSERT INTO heb_vpl VALUES ("S110_17","010_10_17","1SA","10","17","17","ויצעק שמואל את העם אל יהוה המצפה׃ ");
INSERT INTO heb_vpl VALUES ("S110_18","010_10_18","1SA","10","18","18","ויאמר אל בני ישראל כה אמר יהוה אלהי ישראל אנכי העליתי את ישראל ממצרים ואציל אתכם מיד מצרים ומיד כל הממלכות הלחצים אתכם׃ ");
INSERT INTO heb_vpl VALUES ("S110_19","010_10_19","1SA","10","19","19","ואתם היום מאסתם את אלהיכם אשר הוא מושיע לכם מכל רעותיכם וצרתיכם ותאמרו לו כי מלך תשים עלינו ועתה התיצבו לפני יהוה לשבטיכם ולאלפיכם׃ ");
INSERT INTO heb_vpl VALUES ("S110_20","010_10_20","1SA","10","20","20","ויקרב שמואל את כל שבטי ישראל וילכד שבט בנימן׃ ");
INSERT INTO heb_vpl VALUES ("S110_21","010_10_21","1SA","10","21","21","ויקרב את שבט בנימן למשפחתו ותלכד משפחת המטרי וילכד שאול בן קיש ויבקשהו ולא נמצא׃ ");
INSERT INTO heb_vpl VALUES ("S110_22","010_10_22","1SA","10","22","22","וישאלו עוד ביהוה הבא עוד הלם איש ויאמר יהוה הנה הוא נחבא אל הכלים׃ ");
INSERT INTO heb_vpl VALUES ("S110_23","010_10_23","1SA","10","23","23","וירצו ויקחהו משם ויתיצב בתוך העם ויגבה מכל העם משכמו ומעלה׃ ");
INSERT INTO heb_vpl VALUES ("S110_24","010_10_24","1SA","10","24","24","ויאמר שמואל אל כל העם הראיתם אשר בחר בו יהוה כי אין כמהו בכל העם וירעו כל העם ויאמרו יחי המלך׃ ");
INSERT INTO heb_vpl VALUES ("S110_25","010_10_25","1SA","10","25","25","וידבר שמואל אל העם את משפט המלכה ויכתב בספר וינח לפני יהוה וישלח שמואל את כל העם איש לביתו׃ ");
INSERT INTO heb_vpl VALUES ("S110_26","010_10_26","1SA","10","26","26","וגם שאול הלך לביתו גבעתה וילכו עמו החיל אשר נגע אלהים בלבם׃ ");
INSERT INTO heb_vpl VALUES ("S110_27","010_10_27","1SA","10","27","27","ובני בליעל אמרו מה ישענו זה ויבזהו ולא הביאו לו מנחה ויהי כמחריש׃ ");
INSERT INTO heb_vpl VALUES ("S111_1","010_11_1","1SA","11","1","1","ויעל נחש העמוני ויחן על יבש גלעד ויאמרו כל אנשי יביש אל נחש כרת לנו ברית ונעבדך׃ ");
INSERT INTO heb_vpl VALUES ("S111_2","010_11_2","1SA","11","2","2","ויאמר אליהם נחש העמוני בזאת אכרת לכם בנקור לכם כל עין ימין ושמתיה חרפה על כל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S111_3","010_11_3","1SA","11","3","3","ויאמרו אליו זקני יביש הרף לנו שבעת ימים ונשלחה מלאכים בכל גבול ישראל ואם אין מושיע אתנו ויצאנו אליך׃ ");
INSERT INTO heb_vpl VALUES ("S111_4","010_11_4","1SA","11","4","4","ויבאו המלאכים גבעת שאול וידברו הדברים באזני העם וישאו כל העם את קולם ויבכו׃ ");
INSERT INTO heb_vpl VALUES ("S111_5","010_11_5","1SA","11","5","5","והנה שאול בא אחרי הבקר מן השדה ויאמר שאול מה לעם כי יבכו ויספרו לו את דברי אנשי יביש׃ ");
INSERT INTO heb_vpl VALUES ("S111_6","010_11_6","1SA","11","6","6","ותצלח רוח אלהים על שאול בשמעו את הדברים האלה ויחר אפו מאד׃ ");
INSERT INTO heb_vpl VALUES ("S111_7","010_11_7","1SA","11","7","7","ויקח צמד בקר וינתחהו וישלח בכל גבול ישראל ביד המלאכים לאמר אשר איננו יצא אחרי שאול ואחר שמואל כה יעשה לבקרו ויפל פחד יהוה על העם ויצאו כאיש אחד׃ ");
INSERT INTO heb_vpl VALUES ("S111_8","010_11_8","1SA","11","8","8","ויפקדם בבזק ויהיו בני ישראל שלש מאות אלף ואיש יהודה שלשים אלף׃ ");
INSERT INTO heb_vpl VALUES ("S111_9","010_11_9","1SA","11","9","9","ויאמרו למלאכים הבאים כה תאמרון לאיש יביש גלעד מחר תהיה לכם תשועה בחם השמש ויבאו המלאכים ויגידו לאנשי יביש וישמחו׃ ");
INSERT INTO heb_vpl VALUES ("S111_10","010_11_10","1SA","11","10","10","ויאמרו אנשי יביש מחר נצא אליכם ועשיתם לנו ככל הטוב בעיניכם׃ ");
INSERT INTO heb_vpl VALUES ("S111_11","010_11_11","1SA","11","11","11","ויהי ממחרת וישם שאול את העם שלשה ראשים ויבאו בתוך המחנה באשמרת הבקר ויכו את עמון עד חם היום ויהי הנשארים ויפצו ולא נשארו בם שנים יחד׃ ");
INSERT INTO heb_vpl VALUES ("S111_12","010_11_12","1SA","11","12","12","ויאמר העם אל שמואל מי האמר שאול ימלך עלינו תנו האנשים ונמיתם׃ ");
INSERT INTO heb_vpl VALUES ("S111_13","010_11_13","1SA","11","13","13","ויאמר שאול לא יומת איש ביום הזה כי היום עשה יהוה תשועה בישראל׃ ");
INSERT INTO heb_vpl VALUES ("S111_14","010_11_14","1SA","11","14","14","ויאמר שמואל אל העם לכו ונלכה הגלגל ונחדש שם המלוכה׃ ");
INSERT INTO heb_vpl VALUES ("S111_15","010_11_15","1SA","11","15","15","וילכו כל העם הגלגל וימלכו שם את שאול לפני יהוה בגלגל ויזבחו שם זבחים שלמים לפני יהוה וישמח שם שאול וכל אנשי ישראל עד מאד׃ ");
INSERT INTO heb_vpl VALUES ("S112_1","010_12_1","1SA","12","1","1","ויאמר שמואל אל כל ישראל הנה שמעתי בקלכם לכל אשר אמרתם לי ואמליך עליכם מלך׃ ");
INSERT INTO heb_vpl VALUES ("S112_2","010_12_2","1SA","12","2","2","ועתה הנה המלך מתהלך לפניכם ואני זקנתי ושבתי ובני הנם אתכם ואני התהלכתי לפניכם מנערי עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S112_3","010_12_3","1SA","12","3","3","הנני ענו בי נגד יהוה ונגד משיחו את שור מי לקחתי וחמור מי לקחתי ואת מי עשקתי את מי רצותי ומיד מי לקחתי כפר ואעלים עיני בו ואשיב לכם׃ ");
INSERT INTO heb_vpl VALUES ("S112_4","010_12_4","1SA","12","4","4","ויאמרו לא עשקתנו ולא רצותנו ולא לקחת מיד איש מאומה׃ ");
INSERT INTO heb_vpl VALUES ("S112_5","010_12_5","1SA","12","5","5","ויאמר אליהם עד יהוה בכם ועד משיחו היום הזה כי לא מצאתם בידי מאומה ויאמר עד׃ ");
INSERT INTO heb_vpl VALUES ("S112_6","010_12_6","1SA","12","6","6","ויאמר שמואל אל העם יהוה אשר עשה את משה ואת אהרן ואשר העלה את אבתיכם מארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("S112_7","010_12_7","1SA","12","7","7","ועתה התיצבו ואשפטה אתכם לפני יהוה את כל צדקות יהוה אשר עשה אתכם ואת אבותיכם׃ ");
INSERT INTO heb_vpl VALUES ("S112_8","010_12_8","1SA","12","8","8","כאשר בא יעקב מצרים ויזעקו אבותיכם אל יהוה וישלח יהוה את משה ואת אהרן ויוציאו את אבתיכם ממצרים וישבום במקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S112_9","010_12_9","1SA","12","9","9","וישכחו את יהוה אלהיהם וימכר אתם ביד סיסרא שר צבא חצור וביד פלשתים וביד מלך מואב וילחמו בם׃ ");
INSERT INTO heb_vpl VALUES ("S112_10","010_12_10","1SA","12","10","10","ויזעקו אל יהוה ויאמר חטאנו כי עזבנו את יהוה ונעבד את הבעלים ואת העשתרות ועתה הצילנו מיד איבינו ונעבדך׃ ");
INSERT INTO heb_vpl VALUES ("S112_11","010_12_11","1SA","12","11","11","וישלח יהוה את ירבעל ואת בדן ואת יפתח ואת שמואל ויצל אתכם מיד איביכם מסביב ותשבו בטח׃ ");
INSERT INTO heb_vpl VALUES ("S112_12","010_12_12","1SA","12","12","12","ותראו כי נחש מלך בני עמון בא עליכם ותאמרו לי לא כי מלך ימלך עלינו ויהוה אלהיכם מלככם׃ ");
INSERT INTO heb_vpl VALUES ("S112_13","010_12_13","1SA","12","13","13","ועתה הנה המלך אשר בחרתם אשר שאלתם והנה נתן יהוה עליכם מלך׃ ");
INSERT INTO heb_vpl VALUES ("S112_14","010_12_14","1SA","12","14","14","אם תיראו את יהוה ועבדתם אתו ושמעתם בקלו ולא תמרו את פי יהוה והיתם גם אתם וגם המלך אשר מלך עליכם אחר יהוה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("S112_15","010_12_15","1SA","12","15","15","ואם לא תשמעו בקול יהוה ומריתם את פי יהוה והיתה יד יהוה בכם ובאבתיכם׃ ");
INSERT INTO heb_vpl VALUES ("S112_16","010_12_16","1SA","12","16","16","גם עתה התיצבו וראו את הדבר הגדול הזה אשר יהוה עשה לעיניכם׃ ");
INSERT INTO heb_vpl VALUES ("S112_17","010_12_17","1SA","12","17","17","הלוא קציר חטים היום אקרא אל יהוה ויתן קלות ומטר ודעו וראו כי רעתכם רבה אשר עשיתם בעיני יהוה לשאול לכם מלך׃ ");
INSERT INTO heb_vpl VALUES ("S112_18","010_12_18","1SA","12","18","18","ויקרא שמואל אל יהוה ויתן יהוה קלת ומטר ביום ההוא ויירא כל העם מאד את יהוה ואת שמואל׃ ");
INSERT INTO heb_vpl VALUES ("S112_19","010_12_19","1SA","12","19","19","ויאמרו כל העם אל שמואל התפלל בעד עבדיך אל יהוה אלהיך ואל נמות כי יספנו על כל חטאתינו רעה לשאל לנו מלך׃ ");
INSERT INTO heb_vpl VALUES ("S112_20","010_12_20","1SA","12","20","20","ויאמר שמואל אל העם אל תיראו אתם עשיתם את כל הרעה הזאת אך אל תסורו מאחרי יהוה ועבדתם את יהוה בכל לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("S112_21","010_12_21","1SA","12","21","21","ולא תסורו כי אחרי התהו אשר לא יועילו ולא יצילו כי תהו המה׃ ");
INSERT INTO heb_vpl VALUES ("S112_22","010_12_22","1SA","12","22","22","כי לא יטש יהוה את עמו בעבור שמו הגדול כי הואיל יהוה לעשות אתכם לו לעם׃ ");
INSERT INTO heb_vpl VALUES ("S112_23","010_12_23","1SA","12","23","23","גם אנכי חלילה לי מחטא ליהוה מחדל להתפלל בעדכם והוריתי אתכם בדרך הטובה והישרה׃ ");
INSERT INTO heb_vpl VALUES ("S112_24","010_12_24","1SA","12","24","24","אך יראו את יהוה ועבדתם אתו באמת בכל לבבכם כי ראו את אשר הגדל עמכם׃ ");
INSERT INTO heb_vpl VALUES ("S112_25","010_12_25","1SA","12","25","25","ואם הרע תרעו גם אתם גם מלככם תספו׃ ");
INSERT INTO heb_vpl VALUES ("S113_1","010_13_1","1SA","13","1","1","בן שנה שאול במלכו ושתי שנים מלך על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S113_2","010_13_2","1SA","13","2","2","ויבחר לו שאול שלשת אלפים מישראל ויהיו עם שאול אלפים במכמש ובהר בית אל ואלף היו עם יונתן בגבעת בנימין ויתר העם שלח איש לאהליו׃ ");
INSERT INTO heb_vpl VALUES ("S113_3","010_13_3","1SA","13","3","3","ויך יונתן את נציב פלשתים אשר בגבע וישמעו פלשתים ושאול תקע בשופר בכל הארץ לאמר ישמעו העברים׃ ");
INSERT INTO heb_vpl VALUES ("S113_4","010_13_4","1SA","13","4","4","וכל ישראל שמעו לאמר הכה שאול את נציב פלשתים וגם נבאש ישראל בפלשתים ויצעקו העם אחרי שאול הגלגל׃ ");
INSERT INTO heb_vpl VALUES ("S113_5","010_13_5","1SA","13","5","5","ופלשתים נאספו להלחם עם ישראל שלשים אלף רכב וששת אלפים פרשים ועם כחול אשר על שפת הים לרב ויעלו ויחנו במכמש קדמת בית און׃ ");
INSERT INTO heb_vpl VALUES ("S113_6","010_13_6","1SA","13","6","6","ואיש ישראל ראו כי צר לו כי נגש העם ויתחבאו העם במערות ובחוחים ובסלעים ובצרחים ובברות׃ ");
INSERT INTO heb_vpl VALUES ("S113_7","010_13_7","1SA","13","7","7","ועברים עברו את הירדן ארץ גד וגלעד ושאול עודנו בגלגל וכל העם חרדו אחריו׃ ");
INSERT INTO heb_vpl VALUES ("S113_8","010_13_8","1SA","13","8","8","וייחל שבעת ימים למועד אשר שמואל ולא בא שמואל הגלגל ויפץ העם מעליו׃ ");
INSERT INTO heb_vpl VALUES ("S113_9","010_13_9","1SA","13","9","9","ויאמר שאול הגשו אלי העלה והשלמים ויעל העלה׃ ");
INSERT INTO heb_vpl VALUES ("S113_10","010_13_10","1SA","13","10","10","ויהי ככלתו להעלות העלה והנה שמואל בא ויצא שאול לקראתו לברכו׃ ");
INSERT INTO heb_vpl VALUES ("S113_11","010_13_11","1SA","13","11","11","ויאמר שמואל מה עשית ויאמר שאול כי ראיתי כי נפץ העם מעלי ואתה לא באת למועד הימים ופלשתים נאספים מכמש׃ ");
INSERT INTO heb_vpl VALUES ("S113_12","010_13_12","1SA","13","12","12","ואמר עתה ירדו פלשתים אלי הגלגל ופני יהוה לא חליתי ואתאפק ואעלה העלה׃ ");
INSERT INTO heb_vpl VALUES ("S113_13","010_13_13","1SA","13","13","13","ויאמר שמואל אל שאול נסכלת לא שמרת את מצות יהוה אלהיך אשר צוך כי עתה הכין יהוה את ממלכתך אל ישראל עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("S113_14","010_13_14","1SA","13","14","14","ועתה ממלכתך לא תקום בקש יהוה לו איש כלבבו ויצוהו יהוה לנגיד על עמו כי לא שמרת את אשר צוך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S113_15","010_13_15","1SA","13","15","15","ויקם שמואל ויעל מן הגלגל גבעת בנימן ויפקד שאול את העם הנמצאים עמו כשש מאות איש׃ ");
INSERT INTO heb_vpl VALUES ("S113_16","010_13_16","1SA","13","16","16","ושאול ויונתן בנו והעם הנמצא עמם ישבים בגבע בנימן ופלשתים חנו במכמש׃ ");
INSERT INTO heb_vpl VALUES ("S113_17","010_13_17","1SA","13","17","17","ויצא המשחית ממחנה פלשתים שלשה ראשים הראש אחד יפנה אל דרך עפרה אל ארץ שועל׃ ");
INSERT INTO heb_vpl VALUES ("S113_18","010_13_18","1SA","13","18","18","והראש אחד יפנה דרך בית חרון והראש אחד יפנה דרך הגבול הנשקף על גי הצבעים המדברה׃ ");
INSERT INTO heb_vpl VALUES ("S113_19","010_13_19","1SA","13","19","19","וחרש לא ימצא בכל ארץ ישראל כי אמר פלשתים פן יעשו העברים חרב או חנית׃ ");
INSERT INTO heb_vpl VALUES ("S113_20","010_13_20","1SA","13","20","20","וירדו כל ישראל הפלשתים ללטוש איש את מחרשתו ואת אתו ואת קרדמו ואת מחרשתו׃ ");
INSERT INTO heb_vpl VALUES ("S113_21","010_13_21","1SA","13","21","21","והיתה הפצירה פים למחרשת ולאתים ולשלש קלשון ולהקרדמים ולהציב הדרבן׃ ");
INSERT INTO heb_vpl VALUES ("S113_22","010_13_22","1SA","13","22","22","והיה ביום מלחמת ולא נמצא חרב וחנית ביד כל העם אשר את שאול ואת יונתן ותמצא לשאול וליונתן בנו׃ ");
INSERT INTO heb_vpl VALUES ("S113_23","010_13_23","1SA","13","23","23","ויצא מצב פלשתים אל מעבר מכמש׃ ");
INSERT INTO heb_vpl VALUES ("S114_1","010_14_1","1SA","14","1","1","ויהי היום ויאמר יונתן בן שאול אל הנער נשא כליו לכה ונעברה אל מצב פלשתים אשר מעבר הלז ולאביו לא הגיד׃ ");
INSERT INTO heb_vpl VALUES ("S114_2","010_14_2","1SA","14","2","2","ושאול יושב בקצה הגבעה תחת הרמון אשר במגרון והעם אשר עמו כשש מאות איש׃ ");
INSERT INTO heb_vpl VALUES ("S114_3","010_14_3","1SA","14","3","3","ואחיה בן אחטוב אחי איכבוד בן פינחס בן עלי כהן יהוה בשלו נשא אפוד והעם לא ידע כי הלך יונתן׃ ");
INSERT INTO heb_vpl VALUES ("S114_4","010_14_4","1SA","14","4","4","ובין המעברות אשר בקש יונתן לעבר על מצב פלשתים שן הסלע מהעבר מזה ושן הסלע מהעבר מזה ושם האחד בוצץ ושם האחד סנה׃ ");
INSERT INTO heb_vpl VALUES ("S114_5","010_14_5","1SA","14","5","5","השן האחד מצוק מצפון מול מכמש והאחד מנגב מול גבע׃ ");
INSERT INTO heb_vpl VALUES ("S114_6","010_14_6","1SA","14","6","6","ויאמר יהונתן אל הנער נשא כליו לכה ונעברה אל מצב הערלים האלה אולי יעשה יהוה לנו כי אין ליהוה מעצור להושיע ברב או במעט׃ ");
INSERT INTO heb_vpl VALUES ("S114_7","010_14_7","1SA","14","7","7","ויאמר לו נשא כליו עשה כל אשר בלבבך נטה לך הנני עמך כלבבך׃ ");
INSERT INTO heb_vpl VALUES ("S114_8","010_14_8","1SA","14","8","8","ויאמר יהונתן הנה אנחנו עברים אל האנשים ונגלינו אליהם׃ ");
INSERT INTO heb_vpl VALUES ("S114_9","010_14_9","1SA","14","9","9","אם כה יאמרו אלינו דמו עד הגיענו אליכם ועמדנו תחתינו ולא נעלה אליהם׃ ");
INSERT INTO heb_vpl VALUES ("S114_10","010_14_10","1SA","14","10","10","ואם כה יאמרו עלו עלינו ועלינו כי נתנם יהוה בידנו וזה לנו האות׃ ");
INSERT INTO heb_vpl VALUES ("S114_11","010_14_11","1SA","14","11","11","ויגלו שניהם אל מצב פלשתים ויאמרו פלשתים הנה עברים יצאים מן החרים אשר התחבאו שם׃ ");
INSERT INTO heb_vpl VALUES ("S114_12","010_14_12","1SA","14","12","12","ויענו אנשי המצבה את יונתן ואת נשא כליו ויאמרו עלו אלינו ונודיעה אתכם דבר ויאמר יונתן אל נשא כליו עלה אחרי כי נתנם יהוה ביד ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S114_13","010_14_13","1SA","14","13","13","ויעל יונתן על ידיו ועל רגליו ונשא כליו אחריו ויפלו לפני יונתן ונשא כליו ממותת אחריו׃ ");
INSERT INTO heb_vpl VALUES ("S114_14","010_14_14","1SA","14","14","14","ותהי המכה הראשנה אשר הכה יונתן ונשא כליו כעשרים איש כבחצי מענה צמד שדה׃ ");
INSERT INTO heb_vpl VALUES ("S114_15","010_14_15","1SA","14","15","15","ותהי חרדה במחנה בשדה ובכל העם המצב והמשחית חרדו גם המה ותרגז הארץ ותהי לחרדת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("S114_16","010_14_16","1SA","14","16","16","ויראו הצפים לשאול בגבעת בנימן והנה ההמון נמוג וילך והלם׃ ");
INSERT INTO heb_vpl VALUES ("S114_17","010_14_17","1SA","14","17","17","ויאמר שאול לעם אשר אתו פקדו נא וראו מי הלך מעמנו ויפקדו והנה אין יונתן ונשא כליו׃ ");
INSERT INTO heb_vpl VALUES ("S114_18","010_14_18","1SA","14","18","18","ויאמר שאול לאחיה הגישה ארון האלהים כי היה ארון האלהים ביום ההוא ובני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S114_19","010_14_19","1SA","14","19","19","ויהי עד דבר שאול אל הכהן וההמון אשר במחנה פלשתים וילך הלוך ורב ויאמר שאול אל הכהן אסף ידך׃ ");
INSERT INTO heb_vpl VALUES ("S114_20","010_14_20","1SA","14","20","20","ויזעק שאול וכל העם אשר אתו ויבאו עד המלחמה והנה היתה חרב איש ברעהו מהומה גדולה מאד׃ ");
INSERT INTO heb_vpl VALUES ("S114_21","010_14_21","1SA","14","21","21","והעברים היו לפלשתים כאתמול שלשום אשר עלו עמם במחנה סביב וגם המה להיות עם ישראל אשר עם שאול ויונתן׃ ");
INSERT INTO heb_vpl VALUES ("S114_22","010_14_22","1SA","14","22","22","וכל איש ישראל המתחבאים בהר אפרים שמעו כי נסו פלשתים וידבקו גם המה אחריהם במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("S114_23","010_14_23","1SA","14","23","23","ויושע יהוה ביום ההוא את ישראל והמלחמה עברה את בית און׃ ");
INSERT INTO heb_vpl VALUES ("S114_24","010_14_24","1SA","14","24","24","ואיש ישראל נגש ביום ההוא ויאל שאול את העם לאמר ארור האיש אשר יאכל לחם עד הערב ונקמתי מאיבי ולא טעם כל העם לחם׃ ");
INSERT INTO heb_vpl VALUES ("S114_25","010_14_25","1SA","14","25","25","וכל הארץ באו ביער ויהי דבש על פני השדה׃ ");
INSERT INTO heb_vpl VALUES ("S114_26","010_14_26","1SA","14","26","26","ויבא העם אל היער והנה הלך דבש ואין משיג ידו אל פיו כי ירא העם את השבעה׃ ");
INSERT INTO heb_vpl VALUES ("S114_27","010_14_27","1SA","14","27","27","ויונתן לא שמע בהשביע אביו את העם וישלח את קצה המטה אשר בידו ויטבל אותה ביערת הדבש וישב ידו אל פיו ותראנה עיניו׃ ");
INSERT INTO heb_vpl VALUES ("S114_28","010_14_28","1SA","14","28","28","ויען איש מהעם ויאמר השבע השביע אביך את העם לאמר ארור האיש אשר יאכל לחם היום ויעף העם׃ ");
INSERT INTO heb_vpl VALUES ("S114_29","010_14_29","1SA","14","29","29","ויאמר יונתן עכר אבי את הארץ ראו נא כי ארו עיני כי טעמתי מעט דבש הזה׃ ");
INSERT INTO heb_vpl VALUES ("S114_30","010_14_30","1SA","14","30","30","אף כי לוא אכל אכל היום העם משלל איביו אשר מצא כי עתה לא רבתה מכה בפלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S114_31","010_14_31","1SA","14","31","31","ויכו ביום ההוא בפלשתים ממכמש אילנה ויעף העם מאד׃ ");
INSERT INTO heb_vpl VALUES ("S114_32","010_14_32","1SA","14","32","32","ויעש העם אל שלל ויקחו צאן ובקר ובני בקר וישחטו ארצה ויאכל העם על הדם׃ ");
INSERT INTO heb_vpl VALUES ("S114_33","010_14_33","1SA","14","33","33","ויגידו לשאול לאמר הנה העם חטאים ליהוה לאכל על הדם ויאמר בגדתם גלו אלי היום אבן גדולה׃ ");
INSERT INTO heb_vpl VALUES ("S114_34","010_14_34","1SA","14","34","34","ויאמר שאול פצו בעם ואמרתם להם הגישו אלי איש שורו ואיש שיהו ושחטתם בזה ואכלתם ולא תחטאו ליהוה לאכל אל הדם ויגשו כל העם איש שורו בידו הלילה וישחטו שם׃ ");
INSERT INTO heb_vpl VALUES ("S114_35","010_14_35","1SA","14","35","35","ויבן שאול מזבח ליהוה אתו החל לבנות מזבח ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S114_36","010_14_36","1SA","14","36","36","ויאמר שאול נרדה אחרי פלשתים לילה ונבזה בהם עד אור הבקר ולא נשאר בהם איש ויאמרו כל הטוב בעיניך עשה ויאמר הכהן נקרבה הלם אל האלהים׃ ");
INSERT INTO heb_vpl VALUES ("S114_37","010_14_37","1SA","14","37","37","וישאל שאול באלהים הארד אחרי פלשתים התתנם ביד ישראל ולא ענהו ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("S114_38","010_14_38","1SA","14","38","38","ויאמר שאול גשו הלם כל פנות העם ודעו וראו במה היתה החטאת הזאת היום׃ ");
INSERT INTO heb_vpl VALUES ("S114_39","010_14_39","1SA","14","39","39","כי חי יהוה המושיע את ישראל כי אם ישנו ביונתן בני כי מות ימות ואין ענהו מכל העם׃ ");
INSERT INTO heb_vpl VALUES ("S114_40","010_14_40","1SA","14","40","40","ויאמר אל כל ישראל אתם תהיו לעבר אחד ואני ויונתן בני נהיה לעבר אחד ויאמרו העם אל שאול הטוב בעיניך עשה׃ ");
INSERT INTO heb_vpl VALUES ("S114_41","010_14_41","1SA","14","41","41","ויאמר שאול אל יהוה אלהי ישראל הבה תמים וילכד יונתן ושאול והעם יצאו׃ ");
INSERT INTO heb_vpl VALUES ("S114_42","010_14_42","1SA","14","42","42","ויאמר שאול הפילו ביני ובין יונתן בני וילכד יונתן׃ ");
INSERT INTO heb_vpl VALUES ("S114_43","010_14_43","1SA","14","43","43","ויאמר שאול אל יונתן הגידה לי מה עשיתה ויגד לו יונתן ויאמר טעם טעמתי בקצה המטה אשר בידי מעט דבש הנני אמות׃ ");
INSERT INTO heb_vpl VALUES ("S114_44","010_14_44","1SA","14","44","44","ויאמר שאול כה יעשה אלהים וכה יוסף כי מות תמות יונתן׃ ");
INSERT INTO heb_vpl VALUES ("S114_45","010_14_45","1SA","14","45","45","ויאמר העם אל שאול היונתן ימות אשר עשה הישועה הגדולה הזאת בישראל חלילה חי יהוה אם יפל משערת ראשו ארצה כי עם אלהים עשה היום הזה ויפדו העם את יונתן ולא מת׃ ");
INSERT INTO heb_vpl VALUES ("S114_46","010_14_46","1SA","14","46","46","ויעל שאול מאחרי פלשתים ופלשתים הלכו למקומם׃ ");
INSERT INTO heb_vpl VALUES ("S114_47","010_14_47","1SA","14","47","47","ושאול לכד המלוכה על ישראל וילחם סביב בכל איביו במואב ובבני עמון ובאדום ובמלכי צובה ובפלשתים ובכל אשר יפנה ירשיע׃ ");
INSERT INTO heb_vpl VALUES ("S114_48","010_14_48","1SA","14","48","48","ויעש חיל ויך את עמלק ויצל את ישראל מיד שסהו׃ ");
INSERT INTO heb_vpl VALUES ("S114_49","010_14_49","1SA","14","49","49","ויהיו בני שאול יונתן וישוי ומלכי שוע ושם שתי בנתיו שם הבכירה מרב ושם הקטנה מיכל׃ ");
INSERT INTO heb_vpl VALUES ("S114_50","010_14_50","1SA","14","50","50","ושם אשת שאול אחינעם בת אחימעץ ושם שר צבאו אבינר בן נר דוד שאול׃ ");
INSERT INTO heb_vpl VALUES ("S114_51","010_14_51","1SA","14","51","51","וקיש אבי שאול ונר אבי אבנר בן אביאל׃ ");
INSERT INTO heb_vpl VALUES ("S114_52","010_14_52","1SA","14","52","52","ותהי המלחמה חזקה על פלשתים כל ימי שאול וראה שאול כל איש גבור וכל בן חיל ויאספהו אליו׃ ");
INSERT INTO heb_vpl VALUES ("S115_1","010_15_1","1SA","15","1","1","ויאמר שמואל אל שאול אתי שלח יהוה למשחך למלך על עמו על ישראל ועתה שמע לקול דברי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S115_2","010_15_2","1SA","15","2","2","כה אמר יהוה צבאות פקדתי את אשר עשה עמלק לישראל אשר שם לו בדרך בעלתו ממצרים׃ ");
INSERT INTO heb_vpl VALUES ("S115_3","010_15_3","1SA","15","3","3","עתה לך והכיתה את עמלק והחרמתם את כל אשר לו ולא תחמל עליו והמתה מאיש עד אשה מעלל ועד יונק משור ועד שה מגמל ועד חמור׃ ");
INSERT INTO heb_vpl VALUES ("S115_4","010_15_4","1SA","15","4","4","וישמע שאול את העם ויפקדם בטלאים מאתים אלף רגלי ועשרת אלפים את איש יהודה׃ ");
INSERT INTO heb_vpl VALUES ("S115_5","010_15_5","1SA","15","5","5","ויבא שאול עד עיר עמלק וירב בנחל׃ ");
INSERT INTO heb_vpl VALUES ("S115_6","010_15_6","1SA","15","6","6","ויאמר שאול אל הקיני לכו סרו רדו מתוך עמלקי פן אספך עמו ואתה עשיתה חסד עם כל בני ישראל בעלותם ממצרים ויסר קיני מתוך עמלק׃ ");
INSERT INTO heb_vpl VALUES ("S115_7","010_15_7","1SA","15","7","7","ויך שאול את עמלק מחוילה בואך שור אשר על פני מצרים׃ ");
INSERT INTO heb_vpl VALUES ("S115_8","010_15_8","1SA","15","8","8","ויתפש את אגג מלך עמלק חי ואת כל העם החרים לפי חרב׃ ");
INSERT INTO heb_vpl VALUES ("S115_9","010_15_9","1SA","15","9","9","ויחמל שאול והעם על אגג ועל מיטב הצאן והבקר והמשנים ועל הכרים ועל כל הטוב ולא אבו החרימם וכל המלאכה נמבזה ונמס אתה החרימו׃ ");
INSERT INTO heb_vpl VALUES ("S115_10","010_15_10","1SA","15","10","10","ויהי דבר יהוה אל שמואל לאמר׃ ");
INSERT INTO heb_vpl VALUES ("S115_11","010_15_11","1SA","15","11","11","נחמתי כי המלכתי את שאול למלך כי שב מאחרי ואת דברי לא הקים ויחר לשמואל ויזעק אל יהוה כל הלילה׃ ");
INSERT INTO heb_vpl VALUES ("S115_12","010_15_12","1SA","15","12","12","וישכם שמואל לקראת שאול בבקר ויגד לשמואל לאמר בא שאול הכרמלה והנה מציב לו יד ויסב ויעבר וירד הגלגל׃ ");
INSERT INTO heb_vpl VALUES ("S115_13","010_15_13","1SA","15","13","13","ויבא שמואל אל שאול ויאמר לו שאול ברוך אתה ליהוה הקימתי את דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S115_14","010_15_14","1SA","15","14","14","ויאמר שמואל ומה קול הצאן הזה באזני וקול הבקר אשר אנכי שמע׃ ");
INSERT INTO heb_vpl VALUES ("S115_15","010_15_15","1SA","15","15","15","ויאמר שאול מעמלקי הביאום אשר חמל העם על מיטב הצאן והבקר למען זבח ליהוה אלהיך ואת היותר החרמנו׃ ");
INSERT INTO heb_vpl VALUES ("S115_16","010_15_16","1SA","15","16","16","ויאמר שמואל אל שאול הרף ואגידה לך את אשר דבר יהוה אלי הלילה ויאמרו לו דבר׃ ");
INSERT INTO heb_vpl VALUES ("S115_17","010_15_17","1SA","15","17","17","ויאמר שמואל הלוא אם קטן אתה בעיניך ראש שבטי ישראל אתה וימשחך יהוה למלך על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S115_18","010_15_18","1SA","15","18","18","וישלחך יהוה בדרך ויאמר לך והחרמתה את החטאים את עמלק ונלחמת בו עד כלותם אתם׃ ");
INSERT INTO heb_vpl VALUES ("S115_19","010_15_19","1SA","15","19","19","ולמה לא שמעת בקול יהוה ותעט אל השלל ותעש הרע בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S115_20","010_15_20","1SA","15","20","20","ויאמר שאול אל שמואל אשר שמעתי בקול יהוה ואלך בדרך אשר שלחני יהוה ואביא את אגג מלך עמלק ואת עמלק החרמתי׃ ");
INSERT INTO heb_vpl VALUES ("S115_21","010_15_21","1SA","15","21","21","ויקח העם מהשלל צאן ובקר ראשית החרם לזבח ליהוה אלהיך בגלגל׃ ");
INSERT INTO heb_vpl VALUES ("S115_22","010_15_22","1SA","15","22","22","ויאמר שמואל החפץ ליהוה בעלות וזבחים כשמע בקול יהוה הנה שמע מזבח טוב להקשיב מחלב אילים׃ ");
INSERT INTO heb_vpl VALUES ("S115_23","010_15_23","1SA","15","23","23","כי חטאת קסם מרי ואון ותרפים הפצר יען מאסת את דבר יהוה וימאסך ממלך׃ ");
INSERT INTO heb_vpl VALUES ("S115_24","010_15_24","1SA","15","24","24","ויאמר שאול אל שמואל חטאתי כי עברתי את פי יהוה ואת דבריך כי יראתי את העם ואשמע בקולם׃ ");
INSERT INTO heb_vpl VALUES ("S115_25","010_15_25","1SA","15","25","25","ועתה שא נא את חטאתי ושוב עמי ואשתחוה ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S115_26","010_15_26","1SA","15","26","26","ויאמר שמואל אל שאול לא אשוב עמך כי מאסתה את דבר יהוה וימאסך יהוה מהיות מלך על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S115_27","010_15_27","1SA","15","27","27","ויסב שמואל ללכת ויחזק בכנף מעילו ויקרע׃ ");
INSERT INTO heb_vpl VALUES ("S115_28","010_15_28","1SA","15","28","28","ויאמר אליו שמואל קרע יהוה את ממלכות ישראל מעליך היום ונתנה לרעך הטוב ממך׃ ");
INSERT INTO heb_vpl VALUES ("S115_29","010_15_29","1SA","15","29","29","וגם נצח ישראל לא ישקר ולא ינחם כי לא אדם הוא להנחם׃ ");
INSERT INTO heb_vpl VALUES ("S115_30","010_15_30","1SA","15","30","30","ויאמר חטאתי עתה כבדני נא נגד זקני עמי ונגד ישראל ושוב עמי והשתחויתי ליהוה אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("S115_31","010_15_31","1SA","15","31","31","וישב שמואל אחרי שאול וישתחו שאול ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S115_32","010_15_32","1SA","15","32","32","ויאמר שמואל הגישו אלי את אגג מלך עמלק וילך אליו אגג מעדנת ויאמר אגג אכן סר מר המות׃ ");
INSERT INTO heb_vpl VALUES ("S115_33","010_15_33","1SA","15","33","33","ויאמר שמואל כאשר שכלה נשים חרבך כן תשכל מנשים אמך וישסף שמואל את אגג לפני יהוה בגלגל׃ ");
INSERT INTO heb_vpl VALUES ("S115_34","010_15_34","1SA","15","34","34","וילך שמואל הרמתה ושאול עלה אל ביתו גבעת שאול׃ ");
INSERT INTO heb_vpl VALUES ("S115_35","010_15_35","1SA","15","35","35","ולא יסף שמואל לראות את שאול עד יום מותו כי התאבל שמואל אל שאול ויהוה נחם כי המליך את שאול על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S116_1","010_16_1","1SA","16","1","1","ויאמר יהוה אל שמואל עד מתי אתה מתאבל אל שאול ואני מאסתיו ממלך על ישראל מלא קרנך שמן ולך אשלחך אל ישי בית הלחמי כי ראיתי בבניו לי מלך׃ ");
INSERT INTO heb_vpl VALUES ("S116_2","010_16_2","1SA","16","2","2","ויאמר שמואל איך אלך ושמע שאול והרגני ויאמר יהוה עגלת בקר תקח בידך ואמרת לזבח ליהוה באתי׃ ");
INSERT INTO heb_vpl VALUES ("S116_3","010_16_3","1SA","16","3","3","וקראת לישי בזבח ואנכי אודיעך את אשר תעשה ומשחת לי את אשר אמר אליך׃ ");
INSERT INTO heb_vpl VALUES ("S116_4","010_16_4","1SA","16","4","4","ויעש שמואל את אשר דבר יהוה ויבא בית לחם ויחרדו זקני העיר לקראתו ויאמר שלם בואך׃ ");
INSERT INTO heb_vpl VALUES ("S116_5","010_16_5","1SA","16","5","5","ויאמר שלום לזבח ליהוה באתי התקדשו ובאתם אתי בזבח ויקדש את ישי ואת בניו ויקרא להם לזבח׃ ");
INSERT INTO heb_vpl VALUES ("S116_6","010_16_6","1SA","16","6","6","ויהי בבואם וירא את אליאב ויאמר אך נגד יהוה משיחו׃ ");
INSERT INTO heb_vpl VALUES ("S116_7","010_16_7","1SA","16","7","7","ויאמר יהוה אל שמואל אל תבט אל מראהו ואל גבה קומתו כי מאסתיהו כי לא אשר יראה האדם כי האדם יראה לעינים ויהוה יראה ללבב׃ ");
INSERT INTO heb_vpl VALUES ("S116_8","010_16_8","1SA","16","8","8","ויקרא ישי אל אבינדב ויעברהו לפני שמואל ויאמר גם בזה לא בחר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S116_9","010_16_9","1SA","16","9","9","ויעבר ישי שמה ויאמר גם בזה לא בחר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S116_10","010_16_10","1SA","16","10","10","ויעבר ישי שבעת בניו לפני שמואל ויאמר שמואל אל ישי לא בחר יהוה באלה׃ ");
INSERT INTO heb_vpl VALUES ("S116_11","010_16_11","1SA","16","11","11","ויאמר שמואל אל ישי התמו הנערים ויאמר עוד שאר הקטן והנה רעה בצאן ויאמר שמואל אל ישי שלחה וקחנו כי לא נסב עד באו פה׃ ");
INSERT INTO heb_vpl VALUES ("S116_12","010_16_12","1SA","16","12","12","וישלח ויביאהו והוא אדמוני עם יפה עינים וטוב ראי ויאמר יהוה קום משחהו כי זה הוא׃ ");
INSERT INTO heb_vpl VALUES ("S116_13","010_16_13","1SA","16","13","13","ויקח שמואל את קרן השמן וימשח אתו בקרב אחיו ותצלח רוח יהוה אל דוד מהיום ההוא ומעלה ויקם שמואל וילך הרמתה׃ ");
INSERT INTO heb_vpl VALUES ("S116_14","010_16_14","1SA","16","14","14","ורוח יהוה סרה מעם שאול ובעתתו רוח רעה מאת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S116_15","010_16_15","1SA","16","15","15","ויאמרו עבדי שאול אליו הנה נא רוח אלהים רעה מבעתך׃ ");
INSERT INTO heb_vpl VALUES ("S116_16","010_16_16","1SA","16","16","16","יאמר נא אדננו עבדיך לפניך יבקשו איש ידע מנגן בכנור והיה בהיות עליך רוח אלהים רעה ונגן בידו וטוב לך׃ ");
INSERT INTO heb_vpl VALUES ("S116_17","010_16_17","1SA","16","17","17","ויאמר שאול אל עבדיו ראו נא לי איש מיטיב לנגן והביאותם אלי׃ ");
INSERT INTO heb_vpl VALUES ("S116_18","010_16_18","1SA","16","18","18","ויען אחד מהנערים ויאמר הנה ראיתי בן לישי בית הלחמי ידע נגן וגבור חיל ואיש מלחמה ונבון דבר ואיש תאר ויהוה עמו׃ ");
INSERT INTO heb_vpl VALUES ("S116_19","010_16_19","1SA","16","19","19","וישלח שאול מלאכים אל ישי ויאמר שלחה אלי את דוד בנך אשר בצאן׃ ");
INSERT INTO heb_vpl VALUES ("S116_20","010_16_20","1SA","16","20","20","ויקח ישי חמור לחם ונאד יין וגדי עזים אחד וישלח ביד דוד בנו אל שאול׃ ");
INSERT INTO heb_vpl VALUES ("S116_21","010_16_21","1SA","16","21","21","ויבא דוד אל שאול ויעמד לפניו ויאהבהו מאד ויהי לו נשא כלים׃ ");
INSERT INTO heb_vpl VALUES ("S116_22","010_16_22","1SA","16","22","22","וישלח שאול אל ישי לאמר יעמד נא דוד לפני כי מצא חן בעיני׃ ");
INSERT INTO heb_vpl VALUES ("S116_23","010_16_23","1SA","16","23","23","והיה בהיות רוח אלהים אל שאול ולקח דוד את הכנור ונגן בידו ורוח לשאול וטוב לו וסרה מעליו רוח הרעה׃ ");
INSERT INTO heb_vpl VALUES ("S117_1","010_17_1","1SA","17","1","1","ויאספו פלשתים את מחניהם למלחמה ויאספו שכה אשר ליהודה ויחנו בין שוכה ובין עזקה באפס דמים׃ ");
INSERT INTO heb_vpl VALUES ("S117_2","010_17_2","1SA","17","2","2","ושאול ואיש ישראל נאספו ויחנו בעמק האלה ויערכו מלחמה לקראת פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S117_3","010_17_3","1SA","17","3","3","ופלשתים עמדים אל ההר מזה וישראל עמדים אל ההר מזה והגיא ביניהם׃ ");
INSERT INTO heb_vpl VALUES ("S117_4","010_17_4","1SA","17","4","4","ויצא איש הבנים ממחנות פלשתים גלית שמו מגת גבהו שש אמות וזרת׃ ");
INSERT INTO heb_vpl VALUES ("S117_5","010_17_5","1SA","17","5","5","וכובע נחשת על ראשו ושריון קשקשים הוא לבוש ומשקל השריון חמשת אלפים שקלים נחשת׃ ");
INSERT INTO heb_vpl VALUES ("S117_6","010_17_6","1SA","17","6","6","ומצחת נחשת על רגליו וכידון נחשת בין כתפיו׃ ");
INSERT INTO heb_vpl VALUES ("S117_7","010_17_7","1SA","17","7","7","וחץ חניתו כמנור ארגים ולהבת חניתו שש מאות שקלים ברזל ונשא הצנה הלך לפניו׃ ");
INSERT INTO heb_vpl VALUES ("S117_8","010_17_8","1SA","17","8","8","ויעמד ויקרא אל מערכת ישראל ויאמר להם למה תצאו לערך מלחמה הלוא אנכי הפלשתי ואתם עבדים לשאול ברו לכם איש וירד אלי׃ ");
INSERT INTO heb_vpl VALUES ("S117_9","010_17_9","1SA","17","9","9","אם יוכל להלחם אתי והכני והיינו לכם לעבדים ואם אני אוכל לו והכיתיו והייתם לנו לעבדים ועבדתם אתנו׃ ");
INSERT INTO heb_vpl VALUES ("S117_10","010_17_10","1SA","17","10","10","ויאמר הפלשתי אני חרפתי את מערכות ישראל היום הזה תנו לי איש ונלחמה יחד׃ ");
INSERT INTO heb_vpl VALUES ("S117_11","010_17_11","1SA","17","11","11","וישמע שאול וכל ישראל את דברי הפלשתי האלה ויחתו ויראו מאד׃ ");
INSERT INTO heb_vpl VALUES ("S117_12","010_17_12","1SA","17","12","12","ודוד בן איש אפרתי הזה מבית לחם יהודה ושמו ישי ולו שמנה בנים והאיש בימי שאול זקן בא באנשים׃ ");
INSERT INTO heb_vpl VALUES ("S117_13","010_17_13","1SA","17","13","13","וילכו שלשת בני ישי הגדלים הלכו אחרי שאול למלחמה ושם שלשת בניו אשר הלכו במלחמה אליאב הבכור ומשנהו אבינדב והשלשי שמה׃ ");
INSERT INTO heb_vpl VALUES ("S117_14","010_17_14","1SA","17","14","14","ודוד הוא הקטן ושלשה הגדלים הלכו אחרי שאול׃ ");
INSERT INTO heb_vpl VALUES ("S117_15","010_17_15","1SA","17","15","15","ודוד הלך ושב מעל שאול לרעות את צאן אביו בית לחם׃ ");
INSERT INTO heb_vpl VALUES ("S117_16","010_17_16","1SA","17","16","16","ויגש הפלשתי השכם והערב ויתיצב ארבעים יום׃ ");
INSERT INTO heb_vpl VALUES ("S117_17","010_17_17","1SA","17","17","17","ויאמר ישי לדוד בנו קח נא לאחיך איפת הקליא הזה ועשרה לחם הזה והרץ המחנה לאחיך׃ ");
INSERT INTO heb_vpl VALUES ("S117_18","010_17_18","1SA","17","18","18","ואת עשרת חרצי החלב האלה תביא לשר האלף ואת אחיך תפקד לשלום ואת ערבתם תקח׃ ");
INSERT INTO heb_vpl VALUES ("S117_19","010_17_19","1SA","17","19","19","ושאול והמה וכל איש ישראל בעמק האלה נלחמים עם פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S117_20","010_17_20","1SA","17","20","20","וישכם דוד בבקר ויטש את הצאן על שמר וישא וילך כאשר צוהו ישי ויבא המעגלה והחיל היצא אל המערכה והרעו במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("S117_21","010_17_21","1SA","17","21","21","ותערך ישראל ופלשתים מערכה לקראת מערכה׃ ");
INSERT INTO heb_vpl VALUES ("S117_22","010_17_22","1SA","17","22","22","ויטש דוד את הכלים מעליו על יד שומר הכלים וירץ המערכה ויבא וישאל לאחיו לשלום׃ ");
INSERT INTO heb_vpl VALUES ("S117_23","010_17_23","1SA","17","23","23","והוא מדבר עמם והנה איש הבנים עולה גלית הפלשתי שמו מגת ממערות פלשתים וידבר כדברים האלה וישמע דוד׃ ");
INSERT INTO heb_vpl VALUES ("S117_24","010_17_24","1SA","17","24","24","וכל איש ישראל בראותם את האיש וינסו מפניו וייראו מאד׃ ");
INSERT INTO heb_vpl VALUES ("S117_25","010_17_25","1SA","17","25","25","ויאמר איש ישראל הראיתם האיש העלה הזה כי לחרף את ישראל עלה והיה האיש אשר יכנו יעשרנו המלך עשר גדול ואת בתו יתן לו ואת בית אביו יעשה חפשי בישראל׃ ");
INSERT INTO heb_vpl VALUES ("S117_26","010_17_26","1SA","17","26","26","ויאמר דוד אל האנשים העמדים עמו לאמר מה יעשה לאיש אשר יכה את הפלשתי הלז והסיר חרפה מעל ישראל כי מי הפלשתי הערל הזה כי חרף מערכות אלהים חיים׃ ");
INSERT INTO heb_vpl VALUES ("S117_27","010_17_27","1SA","17","27","27","ויאמר לו העם כדבר הזה לאמר כה יעשה לאיש אשר יכנו׃ ");
INSERT INTO heb_vpl VALUES ("S117_28","010_17_28","1SA","17","28","28","וישמע אליאב אחיו הגדול בדברו אל האנשים ויחר אף אליאב בדוד ויאמר למה זה ירדת ועל מי נטשת מעט הצאן ההנה במדבר אני ידעתי את זדנך ואת רע לבבך כי למען ראות המלחמה ירדת׃ ");
INSERT INTO heb_vpl VALUES ("S117_29","010_17_29","1SA","17","29","29","ויאמר דוד מה עשיתי עתה הלוא דבר הוא׃ ");
INSERT INTO heb_vpl VALUES ("S117_30","010_17_30","1SA","17","30","30","ויסב מאצלו אל מול אחר ויאמר כדבר הזה וישבהו העם דבר כדבר הראשון׃ ");
INSERT INTO heb_vpl VALUES ("S117_31","010_17_31","1SA","17","31","31","וישמעו הדברים אשר דבר דוד ויגדו לפני שאול ויקחהו׃ ");
INSERT INTO heb_vpl VALUES ("S117_32","010_17_32","1SA","17","32","32","ויאמר דוד אל שאול אל יפל לב אדם עליו עבדך ילך ונלחם עם הפלשתי הזה׃ ");
INSERT INTO heb_vpl VALUES ("S117_33","010_17_33","1SA","17","33","33","ויאמר שאול אל דוד לא תוכל ללכת אל הפלשתי הזה להלחם עמו כי נער אתה והוא איש מלחמה מנעריו׃ ");
INSERT INTO heb_vpl VALUES ("S117_34","010_17_34","1SA","17","34","34","ויאמר דוד אל שאול רעה היה עבדך לאביו בצאן ובא הארי ואת הדוב ונשא שה מהעדר׃ ");
INSERT INTO heb_vpl VALUES ("S117_35","010_17_35","1SA","17","35","35","ויצאתי אחריו והכתיו והצלתי מפיו ויקם עלי והחזקתי בזקנו והכתיו והמיתיו׃ ");
INSERT INTO heb_vpl VALUES ("S117_36","010_17_36","1SA","17","36","36","גם את הארי גם הדוב הכה עבדך והיה הפלשתי הערל הזה כאחד מהם כי חרף מערכת אלהים חיים׃ ");
INSERT INTO heb_vpl VALUES ("S117_37","010_17_37","1SA","17","37","37","ויאמר דוד יהוה אשר הצלני מיד הארי ומיד הדב הוא יצילני מיד הפלשתי הזה ויאמר שאול אל דוד לך ויהוה יהיה עמך׃ ");
INSERT INTO heb_vpl VALUES ("S117_38","010_17_38","1SA","17","38","38","וילבש שאול את דוד מדיו ונתן קובע נחשת על ראשו וילבש אתו שריון׃ ");
INSERT INTO heb_vpl VALUES ("S117_39","010_17_39","1SA","17","39","39","ויחגר דוד את חרבו מעל למדיו ויאל ללכת כי לא נסה ויאמר דוד אל שאול לא אוכל ללכת באלה כי לא נסיתי ויסרם דוד מעליו׃ ");
INSERT INTO heb_vpl VALUES ("S117_40","010_17_40","1SA","17","40","40","ויקח מקלו בידו ויבחר לו חמשה חלקי אבנים מן הנחל וישם אתם בכלי הרעים אשר לו ובילקוט וקלעו בידו ויגש אל הפלשתי׃ ");
INSERT INTO heb_vpl VALUES ("S117_41","010_17_41","1SA","17","41","41","וילך הפלשתי הלך וקרב אל דוד והאיש נשא הצנה לפניו׃ ");
INSERT INTO heb_vpl VALUES ("S117_42","010_17_42","1SA","17","42","42","ויבט הפלשתי ויראה את דוד ויבזהו כי היה נער ואדמני עם יפה מראה׃ ");
INSERT INTO heb_vpl VALUES ("S117_43","010_17_43","1SA","17","43","43","ויאמר הפלשתי אל דוד הכלב אנכי כי אתה בא אלי במקלות ויקלל הפלשתי את דוד באלהיו׃ ");
INSERT INTO heb_vpl VALUES ("S117_44","010_17_44","1SA","17","44","44","ויאמר הפלשתי אל דוד לכה אלי ואתנה את בשרך לעוף השמים ולבהמת השדה׃ ");
INSERT INTO heb_vpl VALUES ("S117_45","010_17_45","1SA","17","45","45","ויאמר דוד אל הפלשתי אתה בא אלי בחרב ובחנית ובכידון ואנכי בא אליך בשם יהוה צבאות אלהי מערכות ישראל אשר חרפת׃ ");
INSERT INTO heb_vpl VALUES ("S117_46","010_17_46","1SA","17","46","46","היום הזה יסגרך יהוה בידי והכיתך והסרתי את ראשך מעליך ונתתי פגר מחנה פלשתים היום הזה לעוף השמים ולחית הארץ וידעו כל הארץ כי יש אלהים לישראל׃ ");
INSERT INTO heb_vpl VALUES ("S117_47","010_17_47","1SA","17","47","47","וידעו כל הקהל הזה כי לא בחרב ובחנית יהושיע יהוה כי ליהוה המלחמה ונתן אתכם בידנו׃ ");
INSERT INTO heb_vpl VALUES ("S117_48","010_17_48","1SA","17","48","48","והיה כי קם הפלשתי וילך ויקרב לקראת דוד וימהר דוד וירץ המערכה לקראת הפלשתי׃ ");
INSERT INTO heb_vpl VALUES ("S117_49","010_17_49","1SA","17","49","49","וישלח דוד את ידו אל הכלי ויקח משם אבן ויקלע ויך את הפלשתי אל מצחו ותטבע האבן במצחו ויפל על פניו ארצה׃ ");
INSERT INTO heb_vpl VALUES ("S117_50","010_17_50","1SA","17","50","50","ויחזק דוד מן הפלשתי בקלע ובאבן ויך את הפלשתי וימיתהו וחרב אין ביד דוד׃ ");
INSERT INTO heb_vpl VALUES ("S117_51","010_17_51","1SA","17","51","51","וירץ דוד ויעמד אל הפלשתי ויקח את חרבו וישלפה מתערה וימתתהו ויכרת בה את ראשו ויראו הפלשתים כי מת גבורם וינסו׃ ");
INSERT INTO heb_vpl VALUES ("S117_52","010_17_52","1SA","17","52","52","ויקמו אנשי ישראל ויהודה וירעו וירדפו את הפלשתים עד בואך גיא ועד שערי עקרון ויפלו חללי פלשתים בדרך שערים ועד גת ועד עקרון׃ ");
INSERT INTO heb_vpl VALUES ("S117_53","010_17_53","1SA","17","53","53","וישבו בני ישראל מדלק אחרי פלשתים וישסו את מחניהם׃ ");
INSERT INTO heb_vpl VALUES ("S117_54","010_17_54","1SA","17","54","54","ויקח דוד את ראש הפלשתי ויבאהו ירושלם ואת כליו שם באהלו׃ ");
INSERT INTO heb_vpl VALUES ("S117_55","010_17_55","1SA","17","55","55","וכראות שאול את דוד יצא לקראת הפלשתי אמר אל אבנר שר הצבא בן מי זה הנער אבנר ויאמר אבנר חי נפשך המלך אם ידעתי׃ ");
INSERT INTO heb_vpl VALUES ("S117_56","010_17_56","1SA","17","56","56","ויאמר המלך שאל אתה בן מי זה העלם׃ ");
INSERT INTO heb_vpl VALUES ("S117_57","010_17_57","1SA","17","57","57","וכשוב דוד מהכות את הפלשתי ויקח אתו אבנר ויבאהו לפני שאול וראש הפלשתי בידו׃ ");
INSERT INTO heb_vpl VALUES ("S117_58","010_17_58","1SA","17","58","58","ויאמר אליו שאול בן מי אתה הנער ויאמר דוד בן עבדך ישי בית הלחמי׃ ");
INSERT INTO heb_vpl VALUES ("S118_1","010_18_1","1SA","18","1","1","ויהי ככלתו לדבר אל שאול ונפש יהונתן נקשרה בנפש דוד ויאהבו יהונתן כנפשו׃ ");
INSERT INTO heb_vpl VALUES ("S118_2","010_18_2","1SA","18","2","2","ויקחהו שאול ביום ההוא ולא נתנו לשוב בית אביו׃ ");
INSERT INTO heb_vpl VALUES ("S118_3","010_18_3","1SA","18","3","3","ויכרת יהונתן ודוד ברית באהבתו אתו כנפשו׃ ");
INSERT INTO heb_vpl VALUES ("S118_4","010_18_4","1SA","18","4","4","ויתפשט יהונתן את המעיל אשר עליו ויתנהו לדוד ומדיו ועד חרבו ועד קשתו ועד חגרו׃ ");
INSERT INTO heb_vpl VALUES ("S118_5","010_18_5","1SA","18","5","5","ויצא דוד בכל אשר ישלחנו שאול ישכיל וישמהו שאול על אנשי המלחמה וייטב בעיני כל העם וגם בעיני עבדי שאול׃ ");
INSERT INTO heb_vpl VALUES ("S118_6","010_18_6","1SA","18","6","6","ויהי בבואם בשוב דוד מהכות את הפלשתי ותצאנה הנשים מכל ערי ישראל לשור והמחלות לקראת שאול המלך בתפים בשמחה ובשלשים׃ ");
INSERT INTO heb_vpl VALUES ("S118_7","010_18_7","1SA","18","7","7","ותענינה הנשים המשחקות ותאמרן הכה שאול באלפו ודוד ברבבתיו׃ ");
INSERT INTO heb_vpl VALUES ("S118_8","010_18_8","1SA","18","8","8","ויחר לשאול מאד וירע בעיניו הדבר הזה ויאמר נתנו לדוד רבבות ולי נתנו האלפים ועוד לו אך המלוכה׃ ");
INSERT INTO heb_vpl VALUES ("S118_9","010_18_9","1SA","18","9","9","ויהי שאול עון את דוד מהיום ההוא והלאה׃ ");
INSERT INTO heb_vpl VALUES ("S118_10","010_18_10","1SA","18","10","10","ויהי ממחרת ותצלח רוח אלהים רעה אל שאול ויתנבא בתוך הבית ודוד מנגן בידו כיום ביום והחנית ביד שאול׃ ");
INSERT INTO heb_vpl VALUES ("S118_11","010_18_11","1SA","18","11","11","ויטל שאול את החנית ויאמר אכה בדוד ובקיר ויסב דוד מפניו פעמים׃ ");
INSERT INTO heb_vpl VALUES ("S118_12","010_18_12","1SA","18","12","12","וירא שאול מלפני דוד כי היה יהוה עמו ומעם שאול סר׃ ");
INSERT INTO heb_vpl VALUES ("S118_13","010_18_13","1SA","18","13","13","ויסרהו שאול מעמו וישמהו לו שר אלף ויצא ויבא לפני העם׃ ");
INSERT INTO heb_vpl VALUES ("S118_14","010_18_14","1SA","18","14","14","ויהי דוד לכל דרכו משכיל ויהוה עמו׃ ");
INSERT INTO heb_vpl VALUES ("S118_15","010_18_15","1SA","18","15","15","וירא שאול אשר הוא משכיל מאד ויגר מפניו׃ ");
INSERT INTO heb_vpl VALUES ("S118_16","010_18_16","1SA","18","16","16","וכל ישראל ויהודה אהב את דוד כי הוא יוצא ובא לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("S118_17","010_18_17","1SA","18","17","17","ויאמר שאול אל דוד הנה בתי הגדולה מרב אתה אתן לך לאשה אך היה לי לבן חיל והלחם מלחמות יהוה ושאול אמר אל תהי ידי בו ותהי בו יד פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S118_18","010_18_18","1SA","18","18","18","ויאמר דוד אל שאול מי אנכי ומי חיי משפחת אבי בישראל כי אהיה חתן למלך׃ ");
INSERT INTO heb_vpl VALUES ("S118_19","010_18_19","1SA","18","19","19","ויהי בעת תת את מרב בת שאול לדוד והיא נתנה לעדריאל המחלתי לאשה׃ ");
INSERT INTO heb_vpl VALUES ("S118_20","010_18_20","1SA","18","20","20","ותאהב מיכל בת שאול את דוד ויגדו לשאול וישר הדבר בעיניו׃ ");
INSERT INTO heb_vpl VALUES ("S118_21","010_18_21","1SA","18","21","21","ויאמר שאול אתננה לו ותהי לו למוקש ותהי בו יד פלשתים ויאמר שאול אל דוד בשתים תתחתן בי היום׃ ");
INSERT INTO heb_vpl VALUES ("S118_22","010_18_22","1SA","18","22","22","ויצו שאול את עבדו דברו אל דוד בלט לאמר הנה חפץ בך המלך וכל עבדיו אהבוך ועתה התחתן במלך׃ ");
INSERT INTO heb_vpl VALUES ("S118_23","010_18_23","1SA","18","23","23","וידברו עבדי שאול באזני דוד את הדברים האלה ויאמר דוד הנקלה בעיניכם התחתן במלך ואנכי איש רש ונקלה׃ ");
INSERT INTO heb_vpl VALUES ("S118_24","010_18_24","1SA","18","24","24","ויגדו עבדי שאול לו לאמר כדברים האלה דבר דוד׃ ");
INSERT INTO heb_vpl VALUES ("S118_25","010_18_25","1SA","18","25","25","ויאמר שאול כה תאמרו לדוד אין חפץ למלך במהר כי במאה ערלות פלשתים להנקם באיבי המלך ושאול חשב להפיל את דוד ביד פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S118_26","010_18_26","1SA","18","26","26","ויגדו עבדיו לדוד את הדברים האלה וישר הדבר בעיני דוד להתחתן במלך ולא מלאו הימים׃ ");
INSERT INTO heb_vpl VALUES ("S118_27","010_18_27","1SA","18","27","27","ויקם דוד וילך הוא ואנשיו ויך בפלשתים מאתים איש ויבא דוד את ערלתיהם וימלאום למלך להתחתן במלך ויתן לו שאול את מיכל בתו לאשה׃ ");
INSERT INTO heb_vpl VALUES ("S118_28","010_18_28","1SA","18","28","28","וירא שאול וידע כי יהוה עם דוד ומיכל בת שאול אהבתהו׃ ");
INSERT INTO heb_vpl VALUES ("S118_29","010_18_29","1SA","18","29","29","ויאסף שאול לרא מפני דוד עוד ויהי שאול איב את דוד כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("S118_30","010_18_30","1SA","18","30","30","ויצאו שרי פלשתים ויהי מדי צאתם שכל דוד מכל עבדי שאול וייקר שמו מאד׃ ");
INSERT INTO heb_vpl VALUES ("S119_1","010_19_1","1SA","19","1","1","וידבר שאול אל יונתן בנו ואל כל עבדיו להמית את דוד ויהונתן בן שאול חפץ בדוד מאד׃ ");
INSERT INTO heb_vpl VALUES ("S119_2","010_19_2","1SA","19","2","2","ויגד יהונתן לדוד לאמר מבקש שאול אבי להמיתך ועתה השמר נא בבקר וישבת בסתר ונחבאת׃ ");
INSERT INTO heb_vpl VALUES ("S119_3","010_19_3","1SA","19","3","3","ואני אצא ועמדתי ליד אבי בשדה אשר אתה שם ואני אדבר בך אל אבי וראיתי מה והגדתי לך׃ ");
INSERT INTO heb_vpl VALUES ("S119_4","010_19_4","1SA","19","4","4","וידבר יהונתן בדוד טוב אל שאול אביו ויאמר אליו אל יחטא המלך בעבדו בדוד כי לוא חטא לך וכי מעשיו טוב לך מאד׃ ");
INSERT INTO heb_vpl VALUES ("S119_5","010_19_5","1SA","19","5","5","וישם את נפשו בכפו ויך את הפלשתי ויעש יהוה תשועה גדולה לכל ישראל ראית ותשמח ולמה תחטא בדם נקי להמית את דוד חנם׃ ");
INSERT INTO heb_vpl VALUES ("S119_6","010_19_6","1SA","19","6","6","וישמע שאול בקול יהונתן וישבע שאול חי יהוה אם יומת׃ ");
INSERT INTO heb_vpl VALUES ("S119_7","010_19_7","1SA","19","7","7","ויקרא יהונתן לדוד ויגד לו יהונתן את כל הדברים האלה ויבא יהונתן את דוד אל שאול ויהי לפניו כאתמול שלשום׃ ");
INSERT INTO heb_vpl VALUES ("S119_8","010_19_8","1SA","19","8","8","ותוסף המלחמה להיות ויצא דוד וילחם בפלשתים ויך בהם מכה גדולה וינסו מפניו׃ ");
INSERT INTO heb_vpl VALUES ("S119_9","010_19_9","1SA","19","9","9","ותהי רוח יהוה רעה אל שאול והוא בביתו יושב וחניתו בידו ודוד מנגן ביד׃ ");
INSERT INTO heb_vpl VALUES ("S119_10","010_19_10","1SA","19","10","10","ויבקש שאול להכות בחנית בדוד ובקיר ויפטר מפני שאול ויך את החנית בקיר ודוד נס וימלט בלילה הוא׃ ");
INSERT INTO heb_vpl VALUES ("S119_11","010_19_11","1SA","19","11","11","וישלח שאול מלאכים אל בית דוד לשמרו ולהמיתו בבקר ותגד לדוד מיכל אשתו לאמר אם אינך ממלט את נפשך הלילה מחר אתה מומת׃ ");
INSERT INTO heb_vpl VALUES ("S119_12","010_19_12","1SA","19","12","12","ותרד מיכל את דוד בעד החלון וילך ויברח וימלט׃ ");
INSERT INTO heb_vpl VALUES ("S119_13","010_19_13","1SA","19","13","13","ותקח מיכל את התרפים ותשם אל המטה ואת כביר העזים שמה מראשתיו ותכס בבגד׃ ");
INSERT INTO heb_vpl VALUES ("S119_14","010_19_14","1SA","19","14","14","וישלח שאול מלאכים לקחת את דוד ותאמר חלה הוא׃ ");
INSERT INTO heb_vpl VALUES ("S119_15","010_19_15","1SA","19","15","15","וישלח שאול את המלאכים לראות את דוד לאמר העלו אתו במטה אלי להמתו׃ ");
INSERT INTO heb_vpl VALUES ("S119_16","010_19_16","1SA","19","16","16","ויבאו המלאכים והנה התרפים אל המטה וכביר העזים מראשתיו׃ ");
INSERT INTO heb_vpl VALUES ("S119_17","010_19_17","1SA","19","17","17","ויאמר שאול אל מיכל למה ככה רמיתני ותשלחי את איבי וימלט ותאמר מיכל אל שאול הוא אמר אלי שלחני למה אמיתך׃ ");
INSERT INTO heb_vpl VALUES ("S119_18","010_19_18","1SA","19","18","18","ודוד ברח וימלט ויבא אל שמואל הרמתה ויגד לו את כל אשר עשה לו שאול וילך הוא ושמואל וישבו בנוית׃ ");
INSERT INTO heb_vpl VALUES ("S119_19","010_19_19","1SA","19","19","19","ויגד לשאול לאמר הנה דוד בנוית ברמה׃ ");
INSERT INTO heb_vpl VALUES ("S119_20","010_19_20","1SA","19","20","20","וישלח שאול מלאכים לקחת את דוד וירא את להקת הנביאים נבאים ושמואל עמד נצב עליהם ותהי על מלאכי שאול רוח אלהים ויתנבאו גם המה׃ ");
INSERT INTO heb_vpl VALUES ("S119_21","010_19_21","1SA","19","21","21","ויגדו לשאול וישלח מלאכים אחרים ויתנבאו גם המה ויסף שאול וישלח מלאכים שלשים ויתנבאו גם המה׃ ");
INSERT INTO heb_vpl VALUES ("S119_22","010_19_22","1SA","19","22","22","וילך גם הוא הרמתה ויבא עד בור הגדול אשר בשכו וישאל ויאמר איפה שמואל ודוד ויאמר הנה בנוית ברמה׃ ");
INSERT INTO heb_vpl VALUES ("S119_23","010_19_23","1SA","19","23","23","וילך שם אל נוית ברמה ותהי עליו גם הוא רוח אלהים וילך הלוך ויתנבא עד באו בנוית ברמה׃ ");
INSERT INTO heb_vpl VALUES ("S119_24","010_19_24","1SA","19","24","24","ויפשט גם הוא בגדיו ויתנבא גם הוא לפני שמואל ויפל ערם כל היום ההוא וכל הלילה על כן יאמרו הגם שאול בנביאם׃ ");
INSERT INTO heb_vpl VALUES ("S120_1","010_20_1","1SA","20","1","1","ויברח דוד מנוית ברמה ויבא ויאמר לפני יהונתן מה עשיתי מה עוני ומה חטאתי לפני אביך כי מבקש את נפשי׃ ");
INSERT INTO heb_vpl VALUES ("S120_2","010_20_2","1SA","20","2","2","ויאמר לו חלילה לא תמות הנה לו עשה אבי דבר גדול או דבר קטן ולא יגלה את אזני ומדוע יסתיר אבי ממני את הדבר הזה אין זאת׃ ");
INSERT INTO heb_vpl VALUES ("S120_3","010_20_3","1SA","20","3","3","וישבע עוד דוד ויאמר ידע ידע אביך כי מצאתי חן בעיניך ויאמר אל ידע זאת יהונתן פן יעצב ואולם חי יהוה וחי נפשך כי כפשע ביני ובין המות׃ ");
INSERT INTO heb_vpl VALUES ("S120_4","010_20_4","1SA","20","4","4","ויאמר יהונתן אל דוד מה תאמר נפשך ואעשה לך׃ ");
INSERT INTO heb_vpl VALUES ("S120_5","010_20_5","1SA","20","5","5","ויאמר דוד אל יהונתן הנה חדש מחר ואנכי ישב אשב עם המלך לאכול ושלחתני ונסתרתי בשדה עד הערב השלשית׃ ");
INSERT INTO heb_vpl VALUES ("S120_6","010_20_6","1SA","20","6","6","אם פקד יפקדני אביך ואמרת נשאל נשאל ממני דוד לרוץ בית לחם עירו כי זבח הימים שם לכל המשפחה׃ ");
INSERT INTO heb_vpl VALUES ("S120_7","010_20_7","1SA","20","7","7","אם כה יאמר טוב שלום לעבדך ואם חרה יחרה לו דע כי כלתה הרעה מעמו׃ ");
INSERT INTO heb_vpl VALUES ("S120_8","010_20_8","1SA","20","8","8","ועשית חסד על עבדך כי בברית יהוה הבאת את עבדך עמך ואם יש בי עון המיתני אתה ועד אביך למה זה תביאני׃ ");
INSERT INTO heb_vpl VALUES ("S120_9","010_20_9","1SA","20","9","9","ויאמר יהונתן חלילה לך כי אם ידע אדע כי כלתה הרעה מעם אבי לבוא עליך ולא אתה אגיד לך׃ ");
INSERT INTO heb_vpl VALUES ("S120_10","010_20_10","1SA","20","10","10","ויאמר דוד אל יהונתן מי יגיד לי או מה יענך אביך קשה׃ ");
INSERT INTO heb_vpl VALUES ("S120_11","010_20_11","1SA","20","11","11","ויאמר יהונתן אל דוד לכה ונצא השדה ויצאו שניהם השדה׃ ");
INSERT INTO heb_vpl VALUES ("S120_12","010_20_12","1SA","20","12","12","ויאמר יהונתן אל דוד יהוה אלהי ישראל כי אחקר את אבי כעת מחר השלשית והנה טוב אל דוד ולא אז אשלח אליך וגליתי את אזנך׃ ");
INSERT INTO heb_vpl VALUES ("S120_13","010_20_13","1SA","20","13","13","כה יעשה יהוה ליהונתן וכה יסיף כי ייטב אל אבי את הרעה עליך וגליתי את אזנך ושלחתיך והלכת לשלום ויהי יהוה עמך כאשר היה עם אבי׃ ");
INSERT INTO heb_vpl VALUES ("S120_14","010_20_14","1SA","20","14","14","ולא אם עודני חי ולא תעשה עמדי חסד יהוה ולא אמות׃ ");
INSERT INTO heb_vpl VALUES ("S120_15","010_20_15","1SA","20","15","15","ולא תכרת את חסדך מעם ביתי עד עולם ולא בהכרת יהוה את איבי דוד איש מעל פני האדמה׃ ");
INSERT INTO heb_vpl VALUES ("S120_16","010_20_16","1SA","20","16","16","ויכרת יהונתן עם בית דוד ובקש יהוה מיד איבי דוד׃ ");
INSERT INTO heb_vpl VALUES ("S120_17","010_20_17","1SA","20","17","17","ויוסף יהונתן להשביע את דוד באהבתו אתו כי אהבת נפשו אהבו׃ ");
INSERT INTO heb_vpl VALUES ("S120_18","010_20_18","1SA","20","18","18","ויאמר לו יהונתן מחר חדש ונפקדת כי יפקד מושבך׃ ");
INSERT INTO heb_vpl VALUES ("S120_19","010_20_19","1SA","20","19","19","ושלשת תרד מאד ובאת אל המקום אשר נסתרת שם ביום המעשה וישבת אצל האבן האזל׃ ");
INSERT INTO heb_vpl VALUES ("S120_20","010_20_20","1SA","20","20","20","ואני שלשת החצים צדה אורה לשלח לי למטרה׃ ");
INSERT INTO heb_vpl VALUES ("S120_21","010_20_21","1SA","20","21","21","והנה אשלח את הנער לך מצא את החצים אם אמר אמר לנער הנה החצים ממך והנה קחנו ובאה כי שלום לך ואין דבר חי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S120_22","010_20_22","1SA","20","22","22","ואם כה אמר לעלם הנה החצים ממך והלאה לך כי שלחך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S120_23","010_20_23","1SA","20","23","23","והדבר אשר דברנו אני ואתה הנה יהוה ביני ובינך עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("S120_24","010_20_24","1SA","20","24","24","ויסתר דוד בשדה ויהי החדש וישב המלך על הלחם לאכול׃ ");
INSERT INTO heb_vpl VALUES ("S120_25","010_20_25","1SA","20","25","25","וישב המלך על מושבו כפעם בפעם אל מושב הקיר ויקם יהונתן וישב אבנר מצד שאול ויפקד מקום דוד׃ ");
INSERT INTO heb_vpl VALUES ("S120_26","010_20_26","1SA","20","26","26","ולא דבר שאול מאומה ביום ההוא כי אמר מקרה הוא בלתי טהור הוא כי לא טהור׃ ");
INSERT INTO heb_vpl VALUES ("S120_27","010_20_27","1SA","20","27","27","ויהי ממחרת החדש השני ויפקד מקום דוד ויאמר שאול אל יהונתן בנו מדוע לא בא בן ישי גם תמול גם היום אל הלחם׃ ");
INSERT INTO heb_vpl VALUES ("S120_28","010_20_28","1SA","20","28","28","ויען יהונתן את שאול נשאל נשאל דוד מעמדי עד בית לחם׃ ");
INSERT INTO heb_vpl VALUES ("S120_29","010_20_29","1SA","20","29","29","ויאמר שלחני נא כי זבח משפחה לנו בעיר והוא צוה לי אחי ועתה אם מצאתי חן בעיניך אמלטה נא ואראה את אחי על כן לא בא אל שלחן המלך׃ ");
INSERT INTO heb_vpl VALUES ("S120_30","010_20_30","1SA","20","30","30","ויחר אף שאול ביהונתן ויאמר לו בן נעות המרדות הלוא ידעתי כי בחר אתה לבן ישי לבשתך ולבשת ערות אמך׃ ");
INSERT INTO heb_vpl VALUES ("S120_31","010_20_31","1SA","20","31","31","כי כל הימים אשר בן ישי חי על האדמה לא תכון אתה ומלכותך ועתה שלח וקח אתו אלי כי בן מות הוא׃ ");
INSERT INTO heb_vpl VALUES ("S120_32","010_20_32","1SA","20","32","32","ויען יהונתן את שאול אביו ויאמר אליו למה יומת מה עשה׃ ");
INSERT INTO heb_vpl VALUES ("S120_33","010_20_33","1SA","20","33","33","ויטל שאול את החנית עליו להכתו וידע יהונתן כי כלה היא מעם אביו להמית את דוד׃ ");
INSERT INTO heb_vpl VALUES ("S120_34","010_20_34","1SA","20","34","34","ויקם יהונתן מעם השלחן בחרי אף ולא אכל ביום החדש השני לחם כי נעצב אל דוד כי הכלמו אביו׃ ");
INSERT INTO heb_vpl VALUES ("S120_35","010_20_35","1SA","20","35","35","ויהי בבקר ויצא יהונתן השדה למועד דוד ונער קטן עמו׃ ");
INSERT INTO heb_vpl VALUES ("S120_36","010_20_36","1SA","20","36","36","ויאמר לנערו רץ מצא נא את החצים אשר אנכי מורה הנער רץ והוא ירה החצי להעברו׃ ");
INSERT INTO heb_vpl VALUES ("S120_37","010_20_37","1SA","20","37","37","ויבא הנער עד מקום החצי אשר ירה יהונתן ויקרא יהונתן אחרי הנער ויאמר הלוא החצי ממך והלאה׃ ");
INSERT INTO heb_vpl VALUES ("S120_38","010_20_38","1SA","20","38","38","ויקרא יהונתן אחרי הנער מהרה חושה אל תעמד וילקט נער יהונתן את החצי ויבא אל אדניו׃ ");
INSERT INTO heb_vpl VALUES ("S120_39","010_20_39","1SA","20","39","39","והנער לא ידע מאומה אך יהונתן ודוד ידעו את הדבר׃ ");
INSERT INTO heb_vpl VALUES ("S120_40","010_20_40","1SA","20","40","40","ויתן יהונתן את כליו אל הנער אשר לו ויאמר לו לך הביא העיר׃ ");
INSERT INTO heb_vpl VALUES ("S120_41","010_20_41","1SA","20","41","41","הנער בא ודוד קם מאצל הנגב ויפל לאפיו ארצה וישתחו שלש פעמים וישקו איש את רעהו ויבכו איש את רעהו עד דוד הגדיל׃ ");
INSERT INTO heb_vpl VALUES ("S120_42","010_20_42","1SA","20","42","42","ויאמר יהונתן לדוד לך לשלום אשר נשבענו שנינו אנחנו בשם יהוה לאמר יהוה יהיה ביני ובינך ובין זרעי ובין זרעך עד עולם ויקם וילך ויהונתן בא העיר׃ ");
INSERT INTO heb_vpl VALUES ("S121_1","010_21_1","1SA","21","1","1","ויבא דוד נבה אל אחימלך הכהן ויחרד אחימלך לקראת דוד ויאמר לו מדוע אתה לבדך ואיש אין אתך׃ ");
INSERT INTO heb_vpl VALUES ("S121_2","010_21_2","1SA","21","2","2","ויאמר דוד לאחימלך הכהן המלך צוני דבר ויאמר אלי איש אל ידע מאומה את הדבר אשר אנכי שלחך ואשר צויתך ואת הנערים יודעתי אל מקום פלני אלמוני׃ ");
INSERT INTO heb_vpl VALUES ("S121_3","010_21_3","1SA","21","3","3","ועתה מה יש תחת ידך חמשה לחם תנה בידי או הנמצא׃ ");
INSERT INTO heb_vpl VALUES ("S121_4","010_21_4","1SA","21","4","4","ויען הכהן את דוד ויאמר אין לחם חל אל תחת ידי כי אם לחם קדש יש אם נשמרו הנערים אך מאשה׃ ");
INSERT INTO heb_vpl VALUES ("S121_5","010_21_5","1SA","21","5","5","ויען דוד את הכהן ויאמר לו כי אם אשה עצרה לנו כתמול שלשם בצאתי ויהיו כלי הנערים קדש והוא דרך חל ואף כי היום יקדש בכלי׃ ");
INSERT INTO heb_vpl VALUES ("S121_6","010_21_6","1SA","21","6","6","ויתן לו הכהן קדש כי לא היה שם לחם כי אם לחם הפנים המוסרים מלפני יהוה לשום לחם חם ביום הלקחו׃ ");
INSERT INTO heb_vpl VALUES ("S121_7","010_21_7","1SA","21","7","7","ושם איש מעבדי שאול ביום ההוא נעצר לפני יהוה ושמו דאג האדמי אביר הרעים אשר לשאול׃ ");
INSERT INTO heb_vpl VALUES ("S121_8","010_21_8","1SA","21","8","8","ויאמר דוד לאחימלך ואין יש פה תחת ידך חנית או חרב כי גם חרבי וגם כלי לא לקחתי בידי כי היה דבר המלך נחוץ׃ ");
INSERT INTO heb_vpl VALUES ("S121_9","010_21_9","1SA","21","9","9","ויאמר הכהן חרב גלית הפלשתי אשר הכית בעמק האלה הנה היא לוטה בשמלה אחרי האפוד אם אתה תקח לך קח כי אין אחרת זולתה בזה ויאמר דוד אין כמוה תננה לי׃ ");
INSERT INTO heb_vpl VALUES ("S121_10","010_21_10","1SA","21","10","10","ויקם דוד ויברח ביום ההוא מפני שאול ויבא אל אכיש מלך גת׃ ");
INSERT INTO heb_vpl VALUES ("S121_11","010_21_11","1SA","21","11","11","ויאמרו עבדי אכיש אליו הלוא זה דוד מלך הארץ הלוא לזה יענו במחלות לאמר הכה שאול באלפו ודוד ברבבתו׃ ");
INSERT INTO heb_vpl VALUES ("S121_12","010_21_12","1SA","21","12","12","וישם דוד את הדברים האלה בלבבו וירא מאד מפני אכיש מלך גת׃ ");
INSERT INTO heb_vpl VALUES ("S121_13","010_21_13","1SA","21","13","13","וישנו את טעמו בעיניהם ויתהלל בידם ויתו על דלתות השער ויורד רירו אל זקנו׃ ");
INSERT INTO heb_vpl VALUES ("S121_14","010_21_14","1SA","21","14","14","ויאמר אכיש אל עבדיו הנה תראו איש משתגע למה תביאו אתו אלי׃ ");
INSERT INTO heb_vpl VALUES ("S121_15","010_21_15","1SA","21","15","15","חסר משגעים אני כי הבאתם את זה להשתגע עלי הזה יבוא אל ביתי׃ ");
INSERT INTO heb_vpl VALUES ("S122_1","010_22_1","1SA","22","1","1","וילך דוד משם וימלט אל מערת עדלם וישמעו אחיו וכל בית אביו וירדו אליו שמה׃ ");
INSERT INTO heb_vpl VALUES ("S122_2","010_22_2","1SA","22","2","2","ויתקבצו אליו כל איש מצוק וכל איש אשר לו נשא וכל איש מר נפש ויהי עליהם לשר ויהיו עמו כארבע מאות איש׃ ");
INSERT INTO heb_vpl VALUES ("S122_3","010_22_3","1SA","22","3","3","וילך דוד משם מצפה מואב ויאמר אל מלך מואב יצא נא אבי ואמי אתכם עד אשר אדע מה יעשה לי אלהים׃ ");
INSERT INTO heb_vpl VALUES ("S122_4","010_22_4","1SA","22","4","4","וינחם את פני מלך מואב וישבו עמו כל ימי היות דוד במצודה׃ ");
INSERT INTO heb_vpl VALUES ("S122_5","010_22_5","1SA","22","5","5","ויאמר גד הנביא אל דוד לא תשב במצודה לך ובאת לך ארץ יהודה וילך דוד ויבא יער חרת׃ ");
INSERT INTO heb_vpl VALUES ("S122_6","010_22_6","1SA","22","6","6","וישמע שאול כי נודע דוד ואנשים אשר אתו ושאול יושב בגבעה תחת האשל ברמה וחניתו בידו וכל עבדיו נצבים עליו׃ ");
INSERT INTO heb_vpl VALUES ("S122_7","010_22_7","1SA","22","7","7","ויאמר שאול לעבדיו הנצבים עליו שמעו נא בני ימיני גם לכלכם יתן בן ישי שדות וכרמים לכלכם ישים שרי אלפים ושרי מאות׃ ");
INSERT INTO heb_vpl VALUES ("S122_8","010_22_8","1SA","22","8","8","כי קשרתם כלכם עלי ואין גלה את אזני בכרת בני עם בן ישי ואין חלה מכם עלי וגלה את אזני כי הקים בני את עבדי עלי לארב כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S122_9","010_22_9","1SA","22","9","9","ויען דאג האדמי והוא נצב על עבדי שאול ויאמר ראיתי את בן ישי בא נבה אל אחימלך בן אחטוב׃ ");
INSERT INTO heb_vpl VALUES ("S122_10","010_22_10","1SA","22","10","10","וישאל לו ביהוה וצידה נתן לו ואת חרב גלית הפלשתי נתן לו׃ ");
INSERT INTO heb_vpl VALUES ("S122_11","010_22_11","1SA","22","11","11","וישלח המלך לקרא את אחימלך בן אחיטוב הכהן ואת כל בית אביו הכהנים אשר בנב ויבאו כלם אל המלך׃ ");
INSERT INTO heb_vpl VALUES ("S122_12","010_22_12","1SA","22","12","12","ויאמר שאול שמע נא בן אחיטוב ויאמר הנני אדני׃ ");
INSERT INTO heb_vpl VALUES ("S122_13","010_22_13","1SA","22","13","13","ויאמר אלו שאול למה קשרתם עלי אתה ובן ישי בתתך לו לחם וחרב ושאול לו באלהים לקום אלי לארב כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S122_14","010_22_14","1SA","22","14","14","ויען אחימלך את המלך ויאמר ומי בכל עבדיך כדוד נאמן וחתן המלך וסר אל משמעתך ונכבד בביתך׃ ");
INSERT INTO heb_vpl VALUES ("S122_15","010_22_15","1SA","22","15","15","היום החלתי לשאול לו באלהים חלילה לי אל ישם המלך בעבדו דבר בכל בית אבי כי לא ידע עבדך בכל זאת דבר קטן או גדול׃ ");
INSERT INTO heb_vpl VALUES ("S122_16","010_22_16","1SA","22","16","16","ויאמר המלך מות תמות אחימלך אתה וכל בית אביך׃ ");
INSERT INTO heb_vpl VALUES ("S122_17","010_22_17","1SA","22","17","17","ויאמר המלך לרצים הנצבים עליו סבו והמיתו כהני יהוה כי גם ידם עם דוד וכי ידעו כי ברח הוא ולא גלו את אזנו ולא אבו עבדי המלך לשלח את ידם לפגע בכהני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S122_18","010_22_18","1SA","22","18","18","ויאמר המלך לדויג סב אתה ופגע בכהנים ויסב דויג האדמי ויפגע הוא בכהנים וימת ביום ההוא שמנים וחמשה איש נשא אפוד בד׃ ");
INSERT INTO heb_vpl VALUES ("S122_19","010_22_19","1SA","22","19","19","ואת נב עיר הכהנים הכה לפי חרב מאיש ועד אשה מעולל ועד יונק ושור וחמור ושה לפי חרב׃ ");
INSERT INTO heb_vpl VALUES ("S122_20","010_22_20","1SA","22","20","20","וימלט בן אחד לאחימלך בן אחטוב ושמו אביתר ויברח אחרי דוד׃ ");
INSERT INTO heb_vpl VALUES ("S122_21","010_22_21","1SA","22","21","21","ויגד אביתר לדוד כי הרג שאול את כהני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S122_22","010_22_22","1SA","22","22","22","ויאמר דוד לאביתר ידעתי ביום ההוא כי שם דויג האדמי כי הגד יגיד לשאול אנכי סבתי בכל נפש בית אביך׃ ");
INSERT INTO heb_vpl VALUES ("S122_23","010_22_23","1SA","22","23","23","שבה אתי אל תירא כי אשר יבקש את נפשי יבקש את נפשך כי משמרת אתה עמדי׃ ");
INSERT INTO heb_vpl VALUES ("S123_1","010_23_1","1SA","23","1","1","ויגדו לדוד לאמר הנה פלשתים נלחמים בקעילה והמה שסים את הגרנות׃ ");
INSERT INTO heb_vpl VALUES ("S123_2","010_23_2","1SA","23","2","2","וישאל דוד ביהוה לאמר האלך והכיתי בפלשתים האלה ויאמר יהוה אל דוד לך והכית בפלשתים והושעת את קעילה׃ ");
INSERT INTO heb_vpl VALUES ("S123_3","010_23_3","1SA","23","3","3","ויאמרו אנשי דוד אליו הנה אנחנו פה ביהודה יראים ואף כי נלך קעלה אל מערכות פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S123_4","010_23_4","1SA","23","4","4","ויוסף עוד דוד לשאל ביהוה ויענהו יהוה ויאמר קום רד קעילה כי אני נתן את פלשתים בידך׃ ");
INSERT INTO heb_vpl VALUES ("S123_5","010_23_5","1SA","23","5","5","וילך דוד ואנשו קעילה וילחם בפלשתים וינהג את מקניהם ויך בהם מכה גדולה וישע דוד את ישבי קעילה׃ ");
INSERT INTO heb_vpl VALUES ("S123_6","010_23_6","1SA","23","6","6","ויהי בברח אביתר בן אחימלך אל דוד קעילה אפוד ירד בידו׃ ");
INSERT INTO heb_vpl VALUES ("S123_7","010_23_7","1SA","23","7","7","ויגד לשאול כי בא דוד קעילה ויאמר שאול נכר אתו אלהים בידי כי נסגר לבוא בעיר דלתים ובריח׃ ");
INSERT INTO heb_vpl VALUES ("S123_8","010_23_8","1SA","23","8","8","וישמע שאול את כל העם למלחמה לרדת קעילה לצור אל דוד ואל אנשיו׃ ");
INSERT INTO heb_vpl VALUES ("S123_9","010_23_9","1SA","23","9","9","וידע דוד כי עליו שאול מחריש הרעה ויאמר אל אביתר הכהן הגישה האפוד׃ ");
INSERT INTO heb_vpl VALUES ("S123_10","010_23_10","1SA","23","10","10","ויאמר דוד יהוה אלהי ישראל שמע שמע עבדך כי מבקש שאול לבוא אל קעילה לשחת לעיר בעבורי׃ ");
INSERT INTO heb_vpl VALUES ("S123_11","010_23_11","1SA","23","11","11","היסגרני בעלי קעילה בידו הירד שאול כאשר שמע עבדך יהוה אלהי ישראל הגד נא לעבדך ויאמר יהוה ירד׃ ");
INSERT INTO heb_vpl VALUES ("S123_12","010_23_12","1SA","23","12","12","ויאמר דוד היסגרו בעלי קעילה אתי ואת אנשי ביד שאול ויאמר יהוה יסגירו׃ ");
INSERT INTO heb_vpl VALUES ("S123_13","010_23_13","1SA","23","13","13","ויקם דוד ואנשיו כשש מאות איש ויצאו מקעלה ויתהלכו באשר יתהלכו ולשאול הגד כי נמלט דוד מקעילה ויחדל לצאת׃ ");
INSERT INTO heb_vpl VALUES ("S123_14","010_23_14","1SA","23","14","14","וישב דוד במדבר במצדות וישב בהר במדבר זיף ויבקשהו שאול כל הימים ולא נתנו אלהים בידו׃ ");
INSERT INTO heb_vpl VALUES ("S123_15","010_23_15","1SA","23","15","15","וירא דוד כי יצא שאול לבקש את נפשו ודוד במדבר זיף בחרשה׃ ");
INSERT INTO heb_vpl VALUES ("S123_16","010_23_16","1SA","23","16","16","ויקם יהונתן בן שאול וילך אל דוד חרשה ויחזק את ידו באלהים׃ ");
INSERT INTO heb_vpl VALUES ("S123_17","010_23_17","1SA","23","17","17","ויאמר אליו אל תירא כי לא תמצאך יד שאול אבי ואתה תמלך על ישראל ואנכי אהיה לך למשנה וגם שאול אבי ידע כן׃ ");
INSERT INTO heb_vpl VALUES ("S123_18","010_23_18","1SA","23","18","18","ויכרתו שניהם ברית לפני יהוה וישב דוד בחרשה ויהונתן הלך לביתו׃ ");
INSERT INTO heb_vpl VALUES ("S123_19","010_23_19","1SA","23","19","19","ויעלו זפים אל שאול הגבעתה לאמר הלוא דוד מסתתר עמנו במצדות בחרשה בגבעת החכילה אשר מימין הישימון׃ ");
INSERT INTO heb_vpl VALUES ("S123_20","010_23_20","1SA","23","20","20","ועתה לכל אות נפשך המלך לרדת רד ולנו הסגירו ביד המלך׃ ");
INSERT INTO heb_vpl VALUES ("S123_21","010_23_21","1SA","23","21","21","ויאמר שאול ברוכים אתם ליהוה כי חמלתם עלי׃ ");
INSERT INTO heb_vpl VALUES ("S123_22","010_23_22","1SA","23","22","22","לכו נא הכינו עוד ודעו וראו את מקומו אשר תהיה רגלו מי ראהו שם כי אמר אלי ערום יערם הוא׃ ");
INSERT INTO heb_vpl VALUES ("S123_23","010_23_23","1SA","23","23","23","וראו ודעו מכל המחבאים אשר יתחבא שם ושבתם אלי אל נכון והלכתי אתכם והיה אם ישנו בארץ וחפשתי אתו בכל אלפי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("S123_24","010_23_24","1SA","23","24","24","ויקומו וילכו זיפה לפני שאול ודוד ואנשיו במדבר מעון בערבה אל ימין הישימון׃ ");
INSERT INTO heb_vpl VALUES ("S123_25","010_23_25","1SA","23","25","25","וילך שאול ואנשיו לבקש ויגדו לדוד וירד הסלע וישב במדבר מעון וישמע שאול וירדף אחרי דוד מדבר מעון׃ ");
INSERT INTO heb_vpl VALUES ("S123_26","010_23_26","1SA","23","26","26","וילך שאול מצד ההר מזה ודוד ואנשיו מצד ההר מזה ויהי דוד נחפז ללכת מפני שאול ושאול ואנשיו עטרים אל דוד ואל אנשיו לתפשם׃ ");
INSERT INTO heb_vpl VALUES ("S123_27","010_23_27","1SA","23","27","27","ומלאך בא אל שאול לאמר מהרה ולכה כי פשטו פלשתים על הארץ׃ ");
INSERT INTO heb_vpl VALUES ("S123_28","010_23_28","1SA","23","28","28","וישב שאול מרדף אחרי דוד וילך לקראת פלשתים על כן קראו למקום ההוא סלע המחלקות׃ ");
INSERT INTO heb_vpl VALUES ("S123_29","010_23_29","1SA","23","29","29","ויעל דוד משם וישב במצדות עין גדי׃ ");
INSERT INTO heb_vpl VALUES ("S124_1","010_24_1","1SA","24","1","1","ויהי כאשר שב שאול מאחרי פלשתים ויגדו לו לאמר הנה דוד במדבר עין גדי׃ ");
INSERT INTO heb_vpl VALUES ("S124_2","010_24_2","1SA","24","2","2","ויקח שאול שלשת אלפים איש בחור מכל ישראל וילך לבקש את דוד ואנשיו על פני צורי היעלים׃ ");
INSERT INTO heb_vpl VALUES ("S124_3","010_24_3","1SA","24","3","3","ויבא אל גדרות הצאן על הדרך ושם מערה ויבא שאול להסך את רגליו ודוד ואנשיו בירכתי המערה ישבים׃ ");
INSERT INTO heb_vpl VALUES ("S124_4","010_24_4","1SA","24","4","4","ויאמרו אנשי דוד אליו הנה היום אשר אמר יהוה אליך הנה אנכי נתן את איביך בידך ועשית לו כאשר יטב בעיניך ויקם דוד ויכרת את כנף המעיל אשר לשאול בלט׃ ");
INSERT INTO heb_vpl VALUES ("S124_5","010_24_5","1SA","24","5","5","ויהי אחרי כן ויך לב דוד אתו על אשר כרת את כנף אשר לשאול׃ ");
INSERT INTO heb_vpl VALUES ("S124_6","010_24_6","1SA","24","6","6","ויאמר לאנשיו חלילה לי מיהוה אם אעשה את הדבר הזה לאדני למשיח יהוה לשלח ידי בו כי משיח יהוה הוא׃ ");
INSERT INTO heb_vpl VALUES ("S124_7","010_24_7","1SA","24","7","7","וישסע דוד את אנשיו בדברים ולא נתנם לקום אל שאול ושאול קם מהמערה וילך בדרך׃ ");
INSERT INTO heb_vpl VALUES ("S124_8","010_24_8","1SA","24","8","8","ויקם דוד אחרי כן ויצא מן המערה ויקרא אחרי שאול לאמר אדני המלך ויבט שאול אחריו ויקד דוד אפים ארצה וישתחו׃ ");
INSERT INTO heb_vpl VALUES ("S124_9","010_24_9","1SA","24","9","9","ויאמר דוד לשאול למה תשמע את דברי אדם לאמר הנה דוד מבקש רעתך׃ ");
INSERT INTO heb_vpl VALUES ("S124_10","010_24_10","1SA","24","10","10","הנה היום הזה ראו עיניך את אשר נתנך יהוה היום בידי במערה ואמר להרגך ותחס עליך ואמר לא אשלח ידי באדני כי משיח יהוה הוא׃ ");
INSERT INTO heb_vpl VALUES ("S124_11","010_24_11","1SA","24","11","11","ואבי ראה גם ראה את כנף מעילך בידי כי בכרתי את כנף מעילך ולא הרגתיך דע וראה כי אין בידי רעה ופשע ולא חטאתי לך ואתה צדה את נפשי לקחתה׃ ");
INSERT INTO heb_vpl VALUES ("S124_12","010_24_12","1SA","24","12","12","ישפט יהוה ביני ובינך ונקמני יהוה ממך וידי לא תהיה בך׃ ");
INSERT INTO heb_vpl VALUES ("S124_13","010_24_13","1SA","24","13","13","כאשר יאמר משל הקדמני מרשעים יצא רשע וידי לא תהיה בך׃ ");
INSERT INTO heb_vpl VALUES ("S124_14","010_24_14","1SA","24","14","14","אחרי מי יצא מלך ישראל אחרי מי אתה רדף אחרי כלב מת אחרי פרעש אחד׃ ");
INSERT INTO heb_vpl VALUES ("S124_15","010_24_15","1SA","24","15","15","והיה יהוה לדין ושפט ביני ובינך וירא וירב את ריבי וישפטני מידך׃ ");
INSERT INTO heb_vpl VALUES ("S124_16","010_24_16","1SA","24","16","16","ויהי ככלות דוד לדבר את הדברים האלה אל שאול ויאמר שאול הקלך זה בני דוד וישא שאול קלו ויבך׃ ");
INSERT INTO heb_vpl VALUES ("S124_17","010_24_17","1SA","24","17","17","ויאמר אל דוד צדיק אתה ממני כי אתה גמלתני הטובה ואני גמלתיך הרעה׃ ");
INSERT INTO heb_vpl VALUES ("S124_18","010_24_18","1SA","24","18","18","ואת הגדת היום את אשר עשיתה אתי טובה את אשר סגרני יהוה בידך ולא הרגתני׃ ");
INSERT INTO heb_vpl VALUES ("S124_19","010_24_19","1SA","24","19","19","וכי ימצא איש את איבו ושלחו בדרך טובה ויהוה ישלמך טובה תחת היום הזה אשר עשיתה לי׃ ");
INSERT INTO heb_vpl VALUES ("S124_20","010_24_20","1SA","24","20","20","ועתה הנה ידעתי כי מלך תמלוך וקמה בידך ממלכת ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S124_21","010_24_21","1SA","24","21","21","ועתה השבעה לי ביהוה אם תכרית את זרעי אחרי ואם תשמיד את שמי מבית אבי׃ ");
INSERT INTO heb_vpl VALUES ("S124_22","010_24_22","1SA","24","22","22","וישבע דוד לשאול וילך שאול אל ביתו ודוד ואנשיו עלו על המצודה׃ ");
INSERT INTO heb_vpl VALUES ("S125_1","010_25_1","1SA","25","1","1","וימת שמואל ויקבצו כל ישראל ויספדו לו ויקברהו בביתו ברמה ויקם דוד וירד אל מדבר פארן׃ ");
INSERT INTO heb_vpl VALUES ("S125_2","010_25_2","1SA","25","2","2","ואיש במעון ומעשהו בכרמל והאיש גדול מאד ולו צאן שלשת אלפים ואלף עזים ויהי בגזז את צאנו בכרמל׃ ");
INSERT INTO heb_vpl VALUES ("S125_3","010_25_3","1SA","25","3","3","ושם האיש נבל ושם אשתו אבגיל והאשה טובת שכל ויפת תאר והאיש קשה ורע מעללים והוא כלבו׃ ");
INSERT INTO heb_vpl VALUES ("S125_4","010_25_4","1SA","25","4","4","וישמע דוד במדבר כי גזז נבל את צאנו׃ ");
INSERT INTO heb_vpl VALUES ("S125_5","010_25_5","1SA","25","5","5","וישלח דוד עשרה נערים ויאמר דוד לנערים עלו כרמלה ובאתם אל נבל ושאלתם לו בשמי לשלום׃ ");
INSERT INTO heb_vpl VALUES ("S125_6","010_25_6","1SA","25","6","6","ואמרתם כה לחי ואתה שלום וביתך שלום וכל אשר לך שלום׃ ");
INSERT INTO heb_vpl VALUES ("S125_7","010_25_7","1SA","25","7","7","ועתה שמעתי כי גזזים לך עתה הרעים אשר לך היו עמנו לא הכלמנום ולא נפקד להם מאומה כל ימי היותם בכרמל׃ ");
INSERT INTO heb_vpl VALUES ("S125_8","010_25_8","1SA","25","8","8","שאל את נעריך ויגידו לך וימצאו הנערים חן בעיניך כי על יום טוב בנו תנה נא את אשר תמצא ידך לעבדיך ולבנך לדוד׃ ");
INSERT INTO heb_vpl VALUES ("S125_9","010_25_9","1SA","25","9","9","ויבאו נערי דוד וידברו אל נבל ככל הדברים האלה בשם דוד וינוחו׃ ");
INSERT INTO heb_vpl VALUES ("S125_10","010_25_10","1SA","25","10","10","ויען נבל את עבדי דוד ויאמר מי דוד ומי בן ישי היום רבו עבדים המתפרצים איש מפני אדניו׃ ");
INSERT INTO heb_vpl VALUES ("S125_11","010_25_11","1SA","25","11","11","ולקחתי את לחמי ואת מימי ואת טבחתי אשר טבחתי לגזזי ונתתי לאנשים אשר לא ידעתי אי מזה המה׃ ");
INSERT INTO heb_vpl VALUES ("S125_12","010_25_12","1SA","25","12","12","ויהפכו נערי דוד לדרכם וישבו ויבאו ויגדו לו ככל הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("S125_13","010_25_13","1SA","25","13","13","ויאמר דוד לאנשיו חגרו איש את חרבו ויחגרו איש את חרבו ויחגר גם דוד את חרבו ויעלו אחרי דוד כארבע מאות איש ומאתים ישבו על הכלים׃ ");
INSERT INTO heb_vpl VALUES ("S125_14","010_25_14","1SA","25","14","14","ולאביגיל אשת נבל הגיד נער אחד מהנערים לאמר הנה שלח דוד מלאכים מהמדבר לברך את אדנינו ויעט בהם׃ ");
INSERT INTO heb_vpl VALUES ("S125_15","010_25_15","1SA","25","15","15","והאנשים טבים לנו מאד ולא הכלמנו ולא פקדנו מאומה כל ימי התהלכנו אתם בהיותנו בשדה׃ ");
INSERT INTO heb_vpl VALUES ("S125_16","010_25_16","1SA","25","16","16","חומה היו עלינו גם לילה גם יומם כל ימי היותנו עמם רעים הצאן׃ ");
INSERT INTO heb_vpl VALUES ("S125_17","010_25_17","1SA","25","17","17","ועתה דעי וראי מה תעשי כי כלתה הרעה אל אדנינו ועל כל ביתו והוא בן בליעל מדבר אליו׃ ");
INSERT INTO heb_vpl VALUES ("S125_18","010_25_18","1SA","25","18","18","ותמהר אבוגיל ותקח מאתים לחם ושנים נבלי יין וחמש צאן עשוות וחמש סאים קלי ומאה צמקים ומאתים דבלים ותשם על החמרים׃ ");
INSERT INTO heb_vpl VALUES ("S125_19","010_25_19","1SA","25","19","19","ותאמר לנעריה עברו לפני הנני אחריכם באה ולאישה נבל לא הגידה׃ ");
INSERT INTO heb_vpl VALUES ("S125_20","010_25_20","1SA","25","20","20","והיה היא רכבת על החמור וירדת בסתר ההר והנה דוד ואנשיו ירדים לקראתה ותפגש אתם׃ ");
INSERT INTO heb_vpl VALUES ("S125_21","010_25_21","1SA","25","21","21","ודוד אמר אך לשקר שמרתי את כל אשר לזה במדבר ולא נפקד מכל אשר לו מאומה וישב לי רעה תחת טובה׃ ");
INSERT INTO heb_vpl VALUES ("S125_22","010_25_22","1SA","25","22","22","כה יעשה אלהים לאיבי דוד וכה יסיף אם אשאיר מכל אשר לו עד הבקר משתין בקיר׃ ");
INSERT INTO heb_vpl VALUES ("S125_23","010_25_23","1SA","25","23","23","ותרא אביגיל את דוד ותמהר ותרד מעל החמור ותפל לאפי דוד על פניה ותשתחו ארץ׃ ");
INSERT INTO heb_vpl VALUES ("S125_24","010_25_24","1SA","25","24","24","ותפל על רגליו ותאמר בי אני אדני העון ותדבר נא אמתך באזניך ושמע את דברי אמתך׃ ");
INSERT INTO heb_vpl VALUES ("S125_25","010_25_25","1SA","25","25","25","אל נא ישים אדני את לבו אל איש הבליעל הזה על נבל כי כשמו כן הוא נבל שמו ונבלה עמו ואני אמתך לא ראיתי את נערי אדני אשר שלחת׃ ");
INSERT INTO heb_vpl VALUES ("S125_26","010_25_26","1SA","25","26","26","ועתה אדני חי יהוה וחי נפשך אשר מנעך יהוה מבוא בדמים והושע ידך לך ועתה יהיו כנבל איביך והמבקשים אל אדני רעה׃ ");
INSERT INTO heb_vpl VALUES ("S125_27","010_25_27","1SA","25","27","27","ועתה הברכה הזאת אשר הביא שפחתך לאדני ונתנה לנערים המתהלכים ברגלי אדני׃ ");
INSERT INTO heb_vpl VALUES ("S125_28","010_25_28","1SA","25","28","28","שא נא לפשע אמתך כי עשה יעשה יהוה לאדני בית נאמן כי מלחמות יהוה אדני נלחם ורעה לא תמצא בך מימיך׃ ");
INSERT INTO heb_vpl VALUES ("S125_29","010_25_29","1SA","25","29","29","ויקם אדם לרדפך ולבקש את נפשך והיתה נפש אדני צרורה בצרור החיים את יהוה אלהיך ואת נפש איביך יקלענה בתוך כף הקלע׃ ");
INSERT INTO heb_vpl VALUES ("S125_30","010_25_30","1SA","25","30","30","והיה כי יעשה יהוה לאדני ככל אשר דבר את הטובה עליך וצוך לנגיד על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S125_31","010_25_31","1SA","25","31","31","ולא תהיה זאת לך לפוקה ולמכשול לב לאדני ולשפך דם חנם ולהושיע אדני לו והיטב יהוה לאדני וזכרת את אמתך׃ ");
INSERT INTO heb_vpl VALUES ("S125_32","010_25_32","1SA","25","32","32","ויאמר דוד לאביגל ברוך יהוה אלהי ישראל אשר שלחך היום הזה לקראתי׃ ");
INSERT INTO heb_vpl VALUES ("S125_33","010_25_33","1SA","25","33","33","וברוך טעמך וברוכה את אשר כלתני היום הזה מבוא בדמים והשע ידי לי׃ ");
INSERT INTO heb_vpl VALUES ("S125_34","010_25_34","1SA","25","34","34","ואולם חי יהוה אלהי ישראל אשר מנעני מהרע אתך כי לולי מהרת ותבאתי לקראתי כי אם נותר לנבל עד אור הבקר משתין בקיר׃ ");
INSERT INTO heb_vpl VALUES ("S125_35","010_25_35","1SA","25","35","35","ויקח דוד מידה את אשר הביאה לו ולה אמר עלי לשלום לביתך ראי שמעתי בקולך ואשא פניך׃ ");
INSERT INTO heb_vpl VALUES ("S125_36","010_25_36","1SA","25","36","36","ותבא אביגיל אל נבל והנה לו משתה בביתו כמשתה המלך ולב נבל טוב עליו והוא שכר עד מאד ולא הגידה לו דבר קטן וגדול עד אור הבקר׃ ");
INSERT INTO heb_vpl VALUES ("S125_37","010_25_37","1SA","25","37","37","ויהי בבקר בצאת היין מנבל ותגד לו אשתו את הדברים האלה וימת לבו בקרבו והוא היה לאבן׃ ");
INSERT INTO heb_vpl VALUES ("S125_38","010_25_38","1SA","25","38","38","ויהי כעשרת הימים ויגף יהוה את נבל וימת׃ ");
INSERT INTO heb_vpl VALUES ("S125_39","010_25_39","1SA","25","39","39","וישמע דוד כי מת נבל ויאמר ברוך יהוה אשר רב את ריב חרפתי מיד נבל ואת עבדו חשך מרעה ואת רעת נבל השיב יהוה בראשו וישלח דוד וידבר באביגיל לקחתה לו לאשה׃ ");
INSERT INTO heb_vpl VALUES ("S125_40","010_25_40","1SA","25","40","40","ויבאו עבדי דוד אל אביגיל הכרמלה וידברו אליה לאמר דוד שלחנו אליך לקחתך לו לאשה׃ ");
INSERT INTO heb_vpl VALUES ("S125_41","010_25_41","1SA","25","41","41","ותקם ותשתחו אפים ארצה ותאמר הנה אמתך לשפחה לרחץ רגלי עבדי אדני׃ ");
INSERT INTO heb_vpl VALUES ("S125_42","010_25_42","1SA","25","42","42","ותמהר ותקם אביגיל ותרכב על החמור וחמש נערתיה ההלכות לרגלה ותלך אחרי מלאכי דוד ותהי לו לאשה׃ ");
INSERT INTO heb_vpl VALUES ("S125_43","010_25_43","1SA","25","43","43","ואת אחינעם לקח דוד מיזרעאל ותהיין גם שתיהן לו לנשים׃ ");
INSERT INTO heb_vpl VALUES ("S125_44","010_25_44","1SA","25","44","44","ושאול נתן את מיכל בתו אשת דוד לפלטי בן ליש אשר מגלים׃ ");
INSERT INTO heb_vpl VALUES ("S126_1","010_26_1","1SA","26","1","1","ויבאו הזפים אל שאול הגבעתה לאמר הלוא דוד מסתתר בגבעת החכילה על פני הישימן׃ ");
INSERT INTO heb_vpl VALUES ("S126_2","010_26_2","1SA","26","2","2","ויקם שאול וירד אל מדבר זיף ואתו שלשת אלפים איש בחורי ישראל לבקש את דוד במדבר זיף׃ ");
INSERT INTO heb_vpl VALUES ("S126_3","010_26_3","1SA","26","3","3","ויחן שאול בגבעת החכילה אשר על פני הישימן על הדרך ודוד ישב במדבר וירא כי בא שאול אחריו המדברה׃ ");
INSERT INTO heb_vpl VALUES ("S126_4","010_26_4","1SA","26","4","4","וישלח דוד מרגלים וידע כי בא שאול אל נכון׃ ");
INSERT INTO heb_vpl VALUES ("S126_5","010_26_5","1SA","26","5","5","ויקם דוד ויבא אל המקום אשר חנה שם שאול וירא דוד את המקום אשר שכב שם שאול ואבנר בן נר שר צבאו ושאול שכב במעגל והעם חנים סביבתו׃ ");
INSERT INTO heb_vpl VALUES ("S126_6","010_26_6","1SA","26","6","6","ויען דוד ויאמר אל אחימלך החתי ואל אבישי בן צרויה אחי יואב לאמר מי ירד אתי אל שאול אל המחנה ויאמר אבישי אני ארד עמך׃ ");
INSERT INTO heb_vpl VALUES ("S126_7","010_26_7","1SA","26","7","7","ויבא דוד ואבישי אל העם לילה והנה שאול שכב ישן במעגל וחניתו מעוכה בארץ מראשתו ואבנר והעם שכבים סביבתו׃ ");
INSERT INTO heb_vpl VALUES ("S126_8","010_26_8","1SA","26","8","8","ויאמר אבישי אל דוד סגר אלהים היום את אויבך בידך ועתה אכנו נא בחנית ובארץ פעם אחת ולא אשנה לו׃ ");
INSERT INTO heb_vpl VALUES ("S126_9","010_26_9","1SA","26","9","9","ויאמר דוד אל אבישי אל תשחיתהו כי מי שלח ידו במשיח יהוה ונקה׃ ");
INSERT INTO heb_vpl VALUES ("S126_10","010_26_10","1SA","26","10","10","ויאמר דוד חי יהוה כי אם יהוה יגפנו או יומו יבוא ומת או במלחמה ירד ונספה׃ ");
INSERT INTO heb_vpl VALUES ("S126_11","010_26_11","1SA","26","11","11","חלילה לי מיהוה משלח ידי במשיח יהוה ועתה קח נא את החנית אשר מראשתו ואת צפחת המים ונלכה לנו׃ ");
INSERT INTO heb_vpl VALUES ("S126_12","010_26_12","1SA","26","12","12","ויקח דוד את החנית ואת צפחת המים מראשתי שאול וילכו להם ואין ראה ואין יודע ואין מקיץ כי כלם ישנים כי תרדמת יהוה נפלה עליהם׃ ");
INSERT INTO heb_vpl VALUES ("S126_13","010_26_13","1SA","26","13","13","ויעבר דוד העבר ויעמד על ראש ההר מרחק רב המקום ביניהם׃ ");
INSERT INTO heb_vpl VALUES ("S126_14","010_26_14","1SA","26","14","14","ויקרא דוד אל העם ואל אבנר בן נר לאמר הלוא תענה אבנר ויען אבנר ויאמר מי אתה קראת אל המלך׃ ");
INSERT INTO heb_vpl VALUES ("S126_15","010_26_15","1SA","26","15","15","ויאמר דוד אל אבנר הלוא איש אתה ומי כמוך בישראל ולמה לא שמרת אל אדניך המלך כי בא אחד העם להשחית את המלך אדניך׃ ");
INSERT INTO heb_vpl VALUES ("S126_16","010_26_16","1SA","26","16","16","לא טוב הדבר הזה אשר עשית חי יהוה כי בני מות אתם אשר לא שמרתם על אדניכם על משיח יהוה ועתה ראה אי חנית המלך ואת צפחת המים אשר מראשתו׃ ");
INSERT INTO heb_vpl VALUES ("S126_17","010_26_17","1SA","26","17","17","ויכר שאול את קול דוד ויאמר הקולך זה בני דוד ויאמר דוד קולי אדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S126_18","010_26_18","1SA","26","18","18","ויאמר למה זה אדני רדף אחרי עבדו כי מה עשיתי ומה בידי רעה׃ ");
INSERT INTO heb_vpl VALUES ("S126_19","010_26_19","1SA","26","19","19","ועתה ישמע נא אדני המלך את דברי עבדו אם יהוה הסיתך בי ירח מנחה ואם בני האדם ארורים הם לפני יהוה כי גרשוני היום מהסתפח בנחלת יהוה לאמר לך עבד אלהים אחרים׃ ");
INSERT INTO heb_vpl VALUES ("S126_20","010_26_20","1SA","26","20","20","ועתה אל יפל דמי ארצה מנגד פני יהוה כי יצא מלך ישראל לבקש את פרעש אחד כאשר ירדף הקרא בהרים׃ ");
INSERT INTO heb_vpl VALUES ("S126_21","010_26_21","1SA","26","21","21","ויאמר שאול חטאתי שוב בני דוד כי לא ארע לך עוד תחת אשר יקרה נפשי בעיניך היום הזה הנה הסכלתי ואשגה הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("S126_22","010_26_22","1SA","26","22","22","ויען דוד ויאמר הנה החנית המלך ויעבר אחד מהנערים ויקחה׃ ");
INSERT INTO heb_vpl VALUES ("S126_23","010_26_23","1SA","26","23","23","ויהוה ישיב לאיש את צדקתו ואת אמנתו אשר נתנך יהוה היום ביד ולא אביתי לשלח ידי במשיח יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S126_24","010_26_24","1SA","26","24","24","והנה כאשר גדלה נפשך היום הזה בעיני כן תגדל נפשי בעיני יהוה ויצלני מכל צרה׃ ");
INSERT INTO heb_vpl VALUES ("S126_25","010_26_25","1SA","26","25","25","ויאמר שאול אל דוד ברוך אתה בני דוד גם עשה תעשה וגם יכל תוכל וילך דוד לדרכו ושאול שב למקומו׃ ");
INSERT INTO heb_vpl VALUES ("S127_1","010_27_1","1SA","27","1","1","ויאמר דוד אל לבו עתה אספה יום אחד ביד שאול אין לי טוב כי המלט אמלט אל ארץ פלשתים ונואש ממני שאול לבקשני עוד בכל גבול ישראל ונמלטתי מידו׃ ");
INSERT INTO heb_vpl VALUES ("S127_2","010_27_2","1SA","27","2","2","ויקם דוד ויעבר הוא ושש מאות איש אשר עמו אל אכיש בן מעוך מלך גת׃ ");
INSERT INTO heb_vpl VALUES ("S127_3","010_27_3","1SA","27","3","3","וישב דוד עם אכיש בגת הוא ואנשיו איש וביתו דוד ושתי נשיו אחינעם היזרעאלית ואביגיל אשת נבל הכרמלית׃ ");
INSERT INTO heb_vpl VALUES ("S127_4","010_27_4","1SA","27","4","4","ויגד לשאול כי ברח דוד גת ולא יוסף עוד לבקשו׃ ");
INSERT INTO heb_vpl VALUES ("S127_5","010_27_5","1SA","27","5","5","ויאמר דוד אל אכיש אם נא מצאתי חן בעיניך יתנו לי מקום באחת ערי השדה ואשבה שם ולמה ישב עבדך בעיר הממלכה עמך׃ ");
INSERT INTO heb_vpl VALUES ("S127_6","010_27_6","1SA","27","6","6","ויתן לו אכיש ביום ההוא את צקלג לכן היתה צקלג למלכי יהודה עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S127_7","010_27_7","1SA","27","7","7","ויהי מספר הימים אשר ישב דוד בשדה פלשתים ימים וארבעה חדשים׃ ");
INSERT INTO heb_vpl VALUES ("S127_8","010_27_8","1SA","27","8","8","ויעל דוד ואנשיו ויפשטו אל הגשורי והגרזי והעמלקי כי הנה ישבות הארץ אשר מעולם בואך שורה ועד ארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("S127_9","010_27_9","1SA","27","9","9","והכה דוד את הארץ ולא יחיה איש ואשה ולקח צאן ובקר וחמרים וגמלים ובגדים וישב ויבא אל אכיש׃ ");
INSERT INTO heb_vpl VALUES ("S127_10","010_27_10","1SA","27","10","10","ויאמר אכיש אל פשטתם היום ויאמר דוד על נגב יהודה ועל נגב הירחמאלי ואל נגב הקיני׃ ");
INSERT INTO heb_vpl VALUES ("S127_11","010_27_11","1SA","27","11","11","ואיש ואשה לא יחיה דוד להביא גת לאמר פן יגדו עלינו לאמר כה עשה דוד וכה משפטו כל הימים אשר ישב בשדה פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S127_12","010_27_12","1SA","27","12","12","ויאמן אכיש בדוד לאמר הבאש הבאיש בעמו בישראל והיה לי לעבד עולם׃ ");
INSERT INTO heb_vpl VALUES ("S128_1","010_28_1","1SA","28","1","1","ויהי בימים ההם ויקבצו פלשתים את מחניהם לצבא להלחם בישראל ויאמר אכיש אל דוד ידע תדע כי אתי תצא במחנה אתה ואנשיך׃ ");
INSERT INTO heb_vpl VALUES ("S128_2","010_28_2","1SA","28","2","2","ויאמר דוד אל אכיש לכן אתה תדע את אשר יעשה עבדך ויאמר אכיש אל דוד לכן שמר לראשי אשימך כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("S128_3","010_28_3","1SA","28","3","3","ושמואל מת ויספדו לו כל ישראל ויקברהו ברמה ובעירו ושאול הסיר האבות ואת הידענים מהארץ׃ ");
INSERT INTO heb_vpl VALUES ("S128_4","010_28_4","1SA","28","4","4","ויקבצו פלשתים ויבאו ויחנו בשונם ויקבץ שאול את כל ישראל ויחנו בגלבע׃ ");
INSERT INTO heb_vpl VALUES ("S128_5","010_28_5","1SA","28","5","5","וירא שאול את מחנה פלשתים וירא ויחרד לבו מאד׃ ");
INSERT INTO heb_vpl VALUES ("S128_6","010_28_6","1SA","28","6","6","וישאל שאול ביהוה ולא ענהו יהוה גם בחלמות גם באורים גם בנביאם׃ ");
INSERT INTO heb_vpl VALUES ("S128_7","010_28_7","1SA","28","7","7","ויאמר שאול לעבדיו בקשו לי אשת בעלת אוב ואלכה אליה ואדרשה בה ויאמרו עבדיו אליו הנה אשת בעלת אוב בעין דור׃ ");
INSERT INTO heb_vpl VALUES ("S128_8","010_28_8","1SA","28","8","8","ויתחפש שאול וילבש בגדים אחרים וילך הוא ושני אנשים עמו ויבאו אל האשה לילה ויאמר קסומי נא לי באוב והעלי לי את אשר אמר אליך׃ ");
INSERT INTO heb_vpl VALUES ("S128_9","010_28_9","1SA","28","9","9","ותאמר האשה אליו הנה אתה ידעת את אשר עשה שאול אשר הכרית את האבות ואת הידעני מן הארץ ולמה אתה מתנקש בנפשי להמיתני׃ ");
INSERT INTO heb_vpl VALUES ("S128_10","010_28_10","1SA","28","10","10","וישבע לה שאול ביהוה לאמר חי יהוה אם יקרך עון בדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("S128_11","010_28_11","1SA","28","11","11","ותאמר האשה את מי אעלה לך ויאמר את שמואל העלי לי׃ ");
INSERT INTO heb_vpl VALUES ("S128_12","010_28_12","1SA","28","12","12","ותרא האשה את שמואל ותזעק בקול גדול ותאמר האשה אל שאול לאמר למה רמיתני ואתה שאול׃ ");
INSERT INTO heb_vpl VALUES ("S128_13","010_28_13","1SA","28","13","13","ויאמר לה המלך אל תיראי כי מה ראית ותאמר האשה אל שאול אלהים ראיתי עלים מן הארץ׃ ");
INSERT INTO heb_vpl VALUES ("S128_14","010_28_14","1SA","28","14","14","ויאמר לה מה תארו ותאמר איש זקן עלה והוא עטה מעיל וידע שאול כי שמואל הוא ויקד אפים ארצה וישתחו׃ ");
INSERT INTO heb_vpl VALUES ("S128_15","010_28_15","1SA","28","15","15","ויאמר שמואל אל שאול למה הרגזתני להעלות אתי ויאמר שאול צר לי מאד ופלשתים נלחמים בי ואלהים סר מעלי ולא ענני עוד גם ביד הנביאם גם בחלמות ואקראה לך להודיעני מה אעשה׃ ");
INSERT INTO heb_vpl VALUES ("S128_16","010_28_16","1SA","28","16","16","ויאמר שמואל ולמה תשאלני ויהוה סר מעליך ויהי ערך׃ ");
INSERT INTO heb_vpl VALUES ("S128_17","010_28_17","1SA","28","17","17","ויעש יהוה לו כאשר דבר בידי ויקרע יהוה את הממלכה מידך ויתנה לרעך לדוד׃ ");
INSERT INTO heb_vpl VALUES ("S128_18","010_28_18","1SA","28","18","18","כאשר לא שמעת בקול יהוה ולא עשית חרון אפו בעמלק על כן הדבר הזה עשה לך יהוה היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S128_19","010_28_19","1SA","28","19","19","ויתן יהוה גם את ישראל עמך ביד פלשתים ומחר אתה ובניך עמי גם את מחנה ישראל יתן יהוה ביד פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S128_20","010_28_20","1SA","28","20","20","וימהר שאול ויפל מלא קומתו ארצה וירא מאד מדברי שמואל גם כח לא היה בו כי לא אכל לחם כל היום וכל הלילה׃ ");
INSERT INTO heb_vpl VALUES ("S128_21","010_28_21","1SA","28","21","21","ותבוא האשה אל שאול ותרא כי נבהל מאד ותאמר אליו הנה שמעה שפחתך בקולך ואשים נפשי בכפי ואשמע את דבריך אשר דברת אלי׃ ");
INSERT INTO heb_vpl VALUES ("S128_22","010_28_22","1SA","28","22","22","ועתה שמע נא גם אתה בקול שפחתך ואשמה לפניך פת לחם ואכול ויהי בך כח כי תלך בדרך׃ ");
INSERT INTO heb_vpl VALUES ("S128_23","010_28_23","1SA","28","23","23","וימאן ויאמר לא אכל ויפרצו בו עבדיו וגם האשה וישמע לקלם ויקם מהארץ וישב אל המטה׃ ");
INSERT INTO heb_vpl VALUES ("S128_24","010_28_24","1SA","28","24","24","ולאשה עגל מרבק בבית ותמהר ותזבחהו ותקח קמח ותלש ותפהו מצות׃ ");
INSERT INTO heb_vpl VALUES ("S128_25","010_28_25","1SA","28","25","25","ותגש לפני שאול ולפני עבדיו ויאכלו ויקמו וילכו בלילה ההוא׃ ");
INSERT INTO heb_vpl VALUES ("S129_1","010_29_1","1SA","29","1","1","ויקבצו פלשתים את כל מחניהם אפקה וישראל חנים בעין אשר ביזרעאל׃ ");
INSERT INTO heb_vpl VALUES ("S129_2","010_29_2","1SA","29","2","2","וסרני פלשתים עברים למאות ולאלפים ודוד ואנשיו עברים באחרנה עם אכיש׃ ");
INSERT INTO heb_vpl VALUES ("S129_3","010_29_3","1SA","29","3","3","ויאמרו שרי פלשתים מה העברים האלה ויאמר אכיש אל שרי פלשתים הלוא זה דוד עבד שאול מלך ישראל אשר היה אתי זה ימים או זה שנים ולא מצאתי בו מאומה מיום נפלו עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S129_4","010_29_4","1SA","29","4","4","ויקצפו עליו שרי פלשתים ויאמרו לו שרי פלשתים השב את האיש וישב אל מקומו אשר הפקדתו שם ולא ירד עמנו במלחמה ולא יהיה לנו לשטן במלחמה ובמה יתרצה זה אל אדניו הלוא בראשי האנשים ההם׃ ");
INSERT INTO heb_vpl VALUES ("S129_5","010_29_5","1SA","29","5","5","הלוא זה דוד אשר יענו לו במחלות לאמר הכה שאול באלפו ודוד ברבבתו׃ ");
INSERT INTO heb_vpl VALUES ("S129_6","010_29_6","1SA","29","6","6","ויקרא אכיש אל דוד ויאמר אליו חי יהוה כי ישר אתה וטוב בעיני צאתך ובאך אתי במחנה כי לא מצאתי בך רעה מיום באך אלי עד היום הזה ובעיני הסרנים לא טוב אתה׃ ");
INSERT INTO heb_vpl VALUES ("S129_7","010_29_7","1SA","29","7","7","ועתה שוב ולך בשלום ולא תעשה רע בעיני סרני פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S129_8","010_29_8","1SA","29","8","8","ויאמר דוד אל אכיש כי מה עשיתי ומה מצאת בעבדך מיום אשר הייתי לפניך עד היום הזה כי לא אבוא ונלחמתי באיבי אדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S129_9","010_29_9","1SA","29","9","9","ויען אכיש ויאמר אל דוד ידעתי כי טוב אתה בעיני כמלאך אלהים אך שרי פלשתים אמרו לא יעלה עמנו במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("S129_10","010_29_10","1SA","29","10","10","ועתה השכם בבקר ועבדי אדניך אשר באו אתך והשכמתם בבקר ואור לכם ולכו׃ ");
INSERT INTO heb_vpl VALUES ("S129_11","010_29_11","1SA","29","11","11","וישכם דוד הוא ואנשיו ללכת בבקר לשוב אל ארץ פלשתים ופלשתים עלו יזרעאל׃ ");
INSERT INTO heb_vpl VALUES ("S130_1","010_30_1","1SA","30","1","1","ויהי בבא דוד ואנשיו צקלג ביום השלישי ועמלקי פשטו אל נגב ואל צקלג ויכו את צקלג וישרפו אתה באש׃ ");
INSERT INTO heb_vpl VALUES ("S130_2","010_30_2","1SA","30","2","2","וישבו את הנשים אשר בה מקטן ועד גדול לא המיתו איש וינהגו וילכו לדרכם׃ ");
INSERT INTO heb_vpl VALUES ("S130_3","010_30_3","1SA","30","3","3","ויבא דוד ואנשיו אל העיר והנה שרופה באש ונשיהם ובניהם ובנתיהם נשבו׃ ");
INSERT INTO heb_vpl VALUES ("S130_4","010_30_4","1SA","30","4","4","וישא דוד והעם אשר אתו את קולם ויבכו עד אשר אין בהם כח לבכות׃ ");
INSERT INTO heb_vpl VALUES ("S130_5","010_30_5","1SA","30","5","5","ושתי נשי דוד נשבו אחינעם היזרעלית ואביגיל אשת נבל הכרמלי׃ ");
INSERT INTO heb_vpl VALUES ("S130_6","010_30_6","1SA","30","6","6","ותצר לדוד מאד כי אמרו העם לסקלו כי מרה נפש כל העם איש על בנו ועל בנתיו ויתחזק דוד ביהוה אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("S130_7","010_30_7","1SA","30","7","7","ויאמר דוד אל אביתר הכהן בן אחימלך הגישה נא לי האפד ויגש אביתר את האפד אל דוד׃ ");
INSERT INTO heb_vpl VALUES ("S130_8","010_30_8","1SA","30","8","8","וישאל דוד ביהוה לאמר ארדף אחרי הגדוד הזה האשגנו ויאמר לו רדף כי השג תשיג והצל תציל׃ ");
INSERT INTO heb_vpl VALUES ("S130_9","010_30_9","1SA","30","9","9","וילך דוד הוא ושש מאות איש אשר אתו ויבאו עד נחל הבשור והנותרים עמדו׃ ");
INSERT INTO heb_vpl VALUES ("S130_10","010_30_10","1SA","30","10","10","וירדף דוד הוא וארבע מאות איש ויעמדו מאתים איש אשר פגרו מעבר את נחל הבשור׃ ");
INSERT INTO heb_vpl VALUES ("S130_11","010_30_11","1SA","30","11","11","וימצאו איש מצרי בשדה ויקחו אתו אל דוד ויתנו לו לחם ויאכל וישקהו מים׃ ");
INSERT INTO heb_vpl VALUES ("S130_12","010_30_12","1SA","30","12","12","ויתנו לו פלח דבלה ושני צמקים ויאכל ותשב רוחו אליו כי לא אכל לחם ולא שתה מים שלשה ימים ושלשה לילות׃ ");
INSERT INTO heb_vpl VALUES ("S130_13","010_30_13","1SA","30","13","13","ויאמר לו דוד למי אתה ואי מזה אתה ויאמר נער מצרי אנכי עבד לאיש עמלקי ויעזבני אדני כי חליתי היום שלשה׃ ");
INSERT INTO heb_vpl VALUES ("S130_14","010_30_14","1SA","30","14","14","אנחנו פשטנו נגב הכרתי ועל אשר ליהודה ועל נגב כלב ואת צקלג שרפנו באש׃ ");
INSERT INTO heb_vpl VALUES ("S130_15","010_30_15","1SA","30","15","15","ויאמר אליו דוד התורדני אל הגדוד הזה ויאמר השבעה לי באלהים אם תמיתני ואם תסגרני ביד אדני ואורדך אל הגדוד הזה׃ ");
INSERT INTO heb_vpl VALUES ("S130_16","010_30_16","1SA","30","16","16","וירדהו והנה נטשים על פני כל הארץ אכלים ושתים וחגגים בכל השלל הגדול אשר לקחו מארץ פלשתים ומארץ יהודה׃ ");
INSERT INTO heb_vpl VALUES ("S130_17","010_30_17","1SA","30","17","17","ויכם דוד מהנשף ועד הערב למחרתם ולא נמלט מהם איש כי אם ארבע מאות איש נער אשר רכבו על הגמלים וינסו׃ ");
INSERT INTO heb_vpl VALUES ("S130_18","010_30_18","1SA","30","18","18","ויצל דוד את כל אשר לקחו עמלק ואת שתי נשיו הציל דוד׃ ");
INSERT INTO heb_vpl VALUES ("S130_19","010_30_19","1SA","30","19","19","ולא נעדר להם מן הקטן ועד הגדול ועד בנים ובנות ומשלל ועד כל אשר לקחו להם הכל השיב דוד׃ ");
INSERT INTO heb_vpl VALUES ("S130_20","010_30_20","1SA","30","20","20","ויקח דוד את כל הצאן והבקר נהגו לפני המקנה ההוא ויאמרו זה שלל דוד׃ ");
INSERT INTO heb_vpl VALUES ("S130_21","010_30_21","1SA","30","21","21","ויבא דוד אל מאתים האנשים אשר פגרו מלכת אחרי דוד וישיבם בנחל הבשור ויצאו לקראת דוד ולקראת העם אשר אתו ויגש דוד את העם וישאל להם לשלום׃ ");
INSERT INTO heb_vpl VALUES ("S130_22","010_30_22","1SA","30","22","22","ויען כל איש רע ובליעל מהאנשים אשר הלכו עם דוד ויאמרו יען אשר לא הלכו עמי לא נתן להם מהשלל אשר הצלנו כי אם איש את אשתו ואת בניו וינהגו וילכו׃ ");
INSERT INTO heb_vpl VALUES ("S130_23","010_30_23","1SA","30","23","23","ויאמר דוד לא תעשו כן אחי את אשר נתן יהוה לנו וישמר אתנו ויתן את הגדוד הבא עלינו בידנו׃ ");
INSERT INTO heb_vpl VALUES ("S130_24","010_30_24","1SA","30","24","24","ומי ישמע לכם לדבר הזה כי כחלק הירד במלחמה וכחלק הישב על הכלים יחדו יחלקו׃ ");
INSERT INTO heb_vpl VALUES ("S130_25","010_30_25","1SA","30","25","25","ויהי מהיום ההוא ומעלה וישמה לחק ולמשפט לישראל עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S130_26","010_30_26","1SA","30","26","26","ויבא דוד אל צקלג וישלח מהשלל לזקני יהודה לרעהו לאמר הנה לכם ברכה משלל איבי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S130_27","010_30_27","1SA","30","27","27","לאשר בבית אל ולאשר ברמות נגב ולאשר ביתר׃ ");
INSERT INTO heb_vpl VALUES ("S130_28","010_30_28","1SA","30","28","28","ולאשר בערער ולאשר בשפמות ולאשר באשתמע׃ ");
INSERT INTO heb_vpl VALUES ("S130_29","010_30_29","1SA","30","29","29","ולאשר ברכל ולאשר בערי הירחמאלי ולאשר בערי הקיני׃ ");
INSERT INTO heb_vpl VALUES ("S130_30","010_30_30","1SA","30","30","30","ולאשר בחרמה ולאשר בבור עשן ולאשר בעתך׃ ");
INSERT INTO heb_vpl VALUES ("S130_31","010_30_31","1SA","30","31","31","ולאשר בחברון ולכל המקמות אשר התהלך שם דוד הוא ואנשיו׃ ");
INSERT INTO heb_vpl VALUES ("S131_1","010_31_1","1SA","31","1","1","ופלשתים נלחמים בישראל וינסו אנשי ישראל מפני פלשתים ויפלו חללים בהר הגלבע׃ ");
INSERT INTO heb_vpl VALUES ("S131_2","010_31_2","1SA","31","2","2","וידבקו פלשתים את שאול ואת בניו ויכו פלשתים את יהונתן ואת אבינדב ואת מלכי שוע בני שאול׃ ");
INSERT INTO heb_vpl VALUES ("S131_3","010_31_3","1SA","31","3","3","ותכבד המלחמה אל שאול וימצאהו המורים אנשים בקשת ויחל מאד מהמורים׃ ");
INSERT INTO heb_vpl VALUES ("S131_4","010_31_4","1SA","31","4","4","ויאמר שאול לנשא כליו שלף חרבך ודקרני בה פן יבואו הערלים האלה ודקרני והתעללו בי ולא אבה נשא כליו כי ירא מאד ויקח שאול את החרב ויפל עליה׃ ");
INSERT INTO heb_vpl VALUES ("S131_5","010_31_5","1SA","31","5","5","וירא נשא כליו כי מת שאול ויפל גם הוא על חרבו וימת עמו׃ ");
INSERT INTO heb_vpl VALUES ("S131_6","010_31_6","1SA","31","6","6","וימת שאול ושלשת בניו ונשא כליו גם כל אנשיו ביום ההוא יחדו׃ ");
INSERT INTO heb_vpl VALUES ("S131_7","010_31_7","1SA","31","7","7","ויראו אנשי ישראל אשר בעבר העמק ואשר בעבר הירדן כי נסו אנשי ישראל וכי מתו שאול ובניו ויעזבו את הערים וינסו ויבאו פלשתים וישבו בהן׃ ");
INSERT INTO heb_vpl VALUES ("S131_8","010_31_8","1SA","31","8","8","ויהי ממחרת ויבאו פלשתים לפשט את החללים וימצאו את שאול ואת שלשת בניו נפלים בהר הגלבע׃ ");
INSERT INTO heb_vpl VALUES ("S131_9","010_31_9","1SA","31","9","9","ויכרתו את ראשו ויפשיטו את כליו וישלחו בארץ פלשתים סביב לבשר בית עצביהם ואת העם׃ ");
INSERT INTO heb_vpl VALUES ("S131_10","010_31_10","1SA","31","10","10","וישמו את כליו בית עשתרות ואת גויתו תקעו בחומת בית שן׃ ");
INSERT INTO heb_vpl VALUES ("S131_11","010_31_11","1SA","31","11","11","וישמעו אליו ישבי יביש גלעד את אשר עשו פלשתים לשאול׃ ");
INSERT INTO heb_vpl VALUES ("S131_12","010_31_12","1SA","31","12","12","ויקומו כל איש חיל וילכו כל הלילה ויקחו את גוית שאול ואת גוית בניו מחומת בית שן ויבאו יבשה וישרפו אתם שם׃ ");
INSERT INTO heb_vpl VALUES ("S131_13","010_31_13","1SA","31","13","13","ויקחו את עצמתיהם ויקברו תחת האשל ביבשה ויצמו שבעת ימים׃ ");
INSERT INTO heb_vpl VALUES ("S21_1","011_1_1","2SA","1","1","1","ויהי אחרי מות שאול ודוד שב מהכות את העמלק וישב דוד בצקלג ימים שנים׃ ");
INSERT INTO heb_vpl VALUES ("S21_2","011_1_2","2SA","1","2","2","ויהי ביום השלישי והנה איש בא מן המחנה מעם שאול ובגדיו קרעים ואדמה על ראשו ויהי בבאו אל דוד ויפל ארצה וישתחו׃ ");
INSERT INTO heb_vpl VALUES ("S21_3","011_1_3","2SA","1","3","3","ויאמר לו דוד אי מזה תבוא ויאמר אליו ממחנה ישראל נמלטתי׃ ");
INSERT INTO heb_vpl VALUES ("S21_4","011_1_4","2SA","1","4","4","ויאמר אליו דוד מה היה הדבר הגד נא לי ויאמר אשר נס העם מן המלחמה וגם הרבה נפל מן העם וימתו וגם שאול ויהונתן בנו מתו׃ ");
INSERT INTO heb_vpl VALUES ("S21_5","011_1_5","2SA","1","5","5","ויאמר דוד אל הנער המגיד לו איך ידעת כי מת שאול ויהונתן בנו׃ ");
INSERT INTO heb_vpl VALUES ("S21_6","011_1_6","2SA","1","6","6","ויאמר הנער המגיד לו נקרא נקריתי בהר הגלבע והנה שאול נשען על חניתו והנה הרכב ובעלי הפרשים הדבקהו׃ ");
INSERT INTO heb_vpl VALUES ("S21_7","011_1_7","2SA","1","7","7","ויפן אחריו ויראני ויקרא אלי ואמר הנני׃ ");
INSERT INTO heb_vpl VALUES ("S21_8","011_1_8","2SA","1","8","8","ויאמר לי מי אתה ויאמר אליו עמלקי אנכי׃ ");
INSERT INTO heb_vpl VALUES ("S21_9","011_1_9","2SA","1","9","9","ויאמר אלי עמד נא עלי ומתתני כי אחזני השבץ כי כל עוד נפשי בי׃ ");
INSERT INTO heb_vpl VALUES ("S21_10","011_1_10","2SA","1","10","10","ואעמד עליו ואמתתהו כי ידעתי כי לא יחיה אחרי נפלו ואקח הנזר אשר על ראשו ואצעדה אשר על זרעו ואביאם אל אדני הנה׃ ");
INSERT INTO heb_vpl VALUES ("S21_11","011_1_11","2SA","1","11","11","ויחזק דוד בבגדו ויקרעם וגם כל האנשים אשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("S21_12","011_1_12","2SA","1","12","12","ויספדו ויבכו ויצמו עד הערב על שאול ועל יהונתן בנו ועל עם יהוה ועל בית ישראל כי נפלו בחרב׃ ");
INSERT INTO heb_vpl VALUES ("S21_13","011_1_13","2SA","1","13","13","ויאמר דוד אל הנער המגיד לו אי מזה אתה ויאמר בן איש גר עמלקי אנכי׃ ");
INSERT INTO heb_vpl VALUES ("S21_14","011_1_14","2SA","1","14","14","ויאמר אליו דוד איך לא יראת לשלח ידך לשחת את משיח יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S21_15","011_1_15","2SA","1","15","15","ויקרא דוד לאחד מהנערים ויאמר גש פגע בו ויכהו וימת׃ ");
INSERT INTO heb_vpl VALUES ("S21_16","011_1_16","2SA","1","16","16","ויאמר אליו דוד דמיך על ראשך כי פיך ענה בך לאמר אנכי מתתי את משיח יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S21_17","011_1_17","2SA","1","17","17","ויקנן דוד את הקינה הזאת על שאול ועל יהונתן בנו׃ ");
INSERT INTO heb_vpl VALUES ("S21_18","011_1_18","2SA","1","18","18","ויאמר ללמד בני יהודה קשת הנה כתובה על ספר הישר׃ ");
INSERT INTO heb_vpl VALUES ("S21_19","011_1_19","2SA","1","19","19","הצבי ישראל על במותיך חלל איך נפלו גבורים׃ ");
INSERT INTO heb_vpl VALUES ("S21_20","011_1_20","2SA","1","20","20","אל תגידו בגת אל תבשרו בחוצת אשקלון פן תשמחנה בנות פלשתים פן תעלזנה בנות הערלים׃ ");
INSERT INTO heb_vpl VALUES ("S21_21","011_1_21","2SA","1","21","21","הרי בגלבע אל טל ואל מטר עליכם ושדי תרומת כי שם נגעל מגן גבורים מגן שאול בלי משיח בשמן׃ ");
INSERT INTO heb_vpl VALUES ("S21_22","011_1_22","2SA","1","22","22","מדם חללים מחלב גבורים קשת יהונתן לא נשוג אחור וחרב שאול לא תשוב ריקם׃ ");
INSERT INTO heb_vpl VALUES ("S21_23","011_1_23","2SA","1","23","23","שאול ויהונתן הנאהבים והנעימם בחייהם ובמותם לא נפרדו מנשרים קלו מאריות גברו׃ ");
INSERT INTO heb_vpl VALUES ("S21_24","011_1_24","2SA","1","24","24","בנות ישראל אל שאול בכינה המלבשכם שני עם עדנים המעלה עדי זהב על לבושכן׃ ");
INSERT INTO heb_vpl VALUES ("S21_25","011_1_25","2SA","1","25","25","איך נפלו גברים בתוך המלחמה יהונתן על במותיך חלל׃ ");
INSERT INTO heb_vpl VALUES ("S21_26","011_1_26","2SA","1","26","26","צר לי עליך אחי יהונתן נעמת לי מאד נפלאתה אהבתך לי מאהבת נשים׃ ");
INSERT INTO heb_vpl VALUES ("S21_27","011_1_27","2SA","1","27","27","איך נפלו גבורים ויאבדו כלי מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("S22_1","011_2_1","2SA","2","1","1","ויהי אחרי כן וישאל דוד ביהוה לאמר האעלה באחת ערי יהודה ויאמר יהוה אליו עלה ויאמר דוד אנה אעלה ויאמר חברנה׃ ");
INSERT INTO heb_vpl VALUES ("S22_2","011_2_2","2SA","2","2","2","ויעל שם דוד וגם שתי נשיו אחינעם היזרעלית ואביגיל אשת נבל הכרמלי׃ ");
INSERT INTO heb_vpl VALUES ("S22_3","011_2_3","2SA","2","3","3","ואנשיו אשר עמו העלה דוד איש וביתו וישבו בערי חברון׃ ");
INSERT INTO heb_vpl VALUES ("S22_4","011_2_4","2SA","2","4","4","ויבאו אנשי יהודה וימשחו שם את דוד למלך על בית יהודה ויגדו לדוד לאמר אנשי יביש גלעד אשר קברו את שאול׃ ");
INSERT INTO heb_vpl VALUES ("S22_5","011_2_5","2SA","2","5","5","וישלח דוד מלאכים אל אנשי יביש גלעד ויאמר אליהם ברכים אתם ליהוה אשר עשיתם החסד הזה עם אדניכם עם שאול ותקברו אתו׃ ");
INSERT INTO heb_vpl VALUES ("S22_6","011_2_6","2SA","2","6","6","ועתה יעש יהוה עמכם חסד ואמת וגם אנכי אעשה אתכם הטובה הזאת אשר עשיתם הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("S22_7","011_2_7","2SA","2","7","7","ועתה תחזקנה ידיכם והיו לבני חיל כי מת אדניכם שאול וגם אתי משחו בית יהודה למלך עליהם׃ ");
INSERT INTO heb_vpl VALUES ("S22_8","011_2_8","2SA","2","8","8","ואבנר בן נר שר צבא אשר לשאול לקח את איש בשת בן שאול ויעברהו מחנים׃ ");
INSERT INTO heb_vpl VALUES ("S22_9","011_2_9","2SA","2","9","9","וימלכהו אל הגלעד ואל האשורי ואל יזרעאל ועל אפרים ועל בנימן ועל ישראל כלה׃ ");
INSERT INTO heb_vpl VALUES ("S22_10","011_2_10","2SA","2","10","10","בן ארבעים שנה איש בשת בן שאול במלכו על ישראל ושתים שנים מלך אך בית יהודה היו אחרי דוד׃ ");
INSERT INTO heb_vpl VALUES ("S22_11","011_2_11","2SA","2","11","11","ויהי מספר הימים אשר היה דוד מלך בחברון על בית יהודה שבע שנים וששה חדשים׃ ");
INSERT INTO heb_vpl VALUES ("S22_12","011_2_12","2SA","2","12","12","ויצא אבנר בן נר ועבדי איש בשת בן שאול ממחנים גבעונה׃ ");
INSERT INTO heb_vpl VALUES ("S22_13","011_2_13","2SA","2","13","13","ויואב בן צרויה ועבדי דוד יצאו ויפגשום על ברכת גבעון יחדו וישבו אלה על הברכה מזה ואלה על הברכה מזה׃ ");
INSERT INTO heb_vpl VALUES ("S22_14","011_2_14","2SA","2","14","14","ויאמר אבנר אל יואב יקומו נא הנערים וישחקו לפנינו ויאמר יואב יקמו׃ ");
INSERT INTO heb_vpl VALUES ("S22_15","011_2_15","2SA","2","15","15","ויקמו ויעברו במספר שנים עשר לבנימן ולאיש בשת בן שאול ושנים עשר מעבדי דוד׃ ");
INSERT INTO heb_vpl VALUES ("S22_16","011_2_16","2SA","2","16","16","ויחזקו איש בראש רעהו וחרבו בצד רעהו ויפלו יחדו ויקרא למקום ההוא חלקת הצרים אשר בגבעון׃ ");
INSERT INTO heb_vpl VALUES ("S22_17","011_2_17","2SA","2","17","17","ותהי המלחמה קשה עד מאד ביום ההוא וינגף אבנר ואנשי ישראל לפני עבדי דוד׃ ");
INSERT INTO heb_vpl VALUES ("S22_18","011_2_18","2SA","2","18","18","ויהיו שם שלשה בני צרויה יואב ואבישי ועשהאל ועשהאל קל ברגליו כאחד הצבים אשר בשדה׃ ");
INSERT INTO heb_vpl VALUES ("S22_19","011_2_19","2SA","2","19","19","וירדף עשהאל אחרי אבנר ולא נטה ללכת על הימין ועל השמאול מאחרי אבנר׃ ");
INSERT INTO heb_vpl VALUES ("S22_20","011_2_20","2SA","2","20","20","ויפן אבנר אחריו ויאמר האתה זה עשהאל ויאמר אנכי׃ ");
INSERT INTO heb_vpl VALUES ("S22_21","011_2_21","2SA","2","21","21","ויאמר לו אבנר נטה לך על ימינך או על שמאלך ואחז לך אחד מהנערים וקח לך את חלצתו ולא אבה עשהאל לסור מאחריו׃ ");
INSERT INTO heb_vpl VALUES ("S22_22","011_2_22","2SA","2","22","22","ויסף עוד אבנר לאמר אל עשהאל סור לך מאחרי למה אככה ארצה ואיך אשא פני אל יואב אחיך׃ ");
INSERT INTO heb_vpl VALUES ("S22_23","011_2_23","2SA","2","23","23","וימאן לסור ויכהו אבנר באחרי החנית אל החמש ותצא החנית מאחריו ויפל שם וימת תחתו ויהי כל הבא אל המקום אשר נפל שם עשהאל וימת ויעמדו׃ ");
INSERT INTO heb_vpl VALUES ("S22_24","011_2_24","2SA","2","24","24","וירדפו יואב ואבישי אחרי אבנר והשמש באה והמה באו עד גבעת אמה אשר על פני גיח דרך מדבר גבעון׃ ");
INSERT INTO heb_vpl VALUES ("S22_25","011_2_25","2SA","2","25","25","ויתקבצו בני בנימן אחרי אבנר ויהיו לאגדה אחת ויעמדו על ראש גבעה אחת׃ ");
INSERT INTO heb_vpl VALUES ("S22_26","011_2_26","2SA","2","26","26","ויקרא אבנר אל יואב ויאמר הלנצח תאכל חרב הלוא ידעתה כי מרה תהיה באחרונה ועד מתי לא תאמר לעם לשוב מאחרי אחיהם׃ ");
INSERT INTO heb_vpl VALUES ("S22_27","011_2_27","2SA","2","27","27","ויאמר יואב חי האלהים כי לולא דברת כי אז מהבקר נעלה העם איש מאחרי אחיו׃ ");
INSERT INTO heb_vpl VALUES ("S22_28","011_2_28","2SA","2","28","28","ויתקע יואב בשופר ויעמדו כל העם ולא ירדפו עוד אחרי ישראל ולא יספו עוד להלחם׃ ");
INSERT INTO heb_vpl VALUES ("S22_29","011_2_29","2SA","2","29","29","ואבנר ואנשיו הלכו בערבה כל הלילה ההוא ויעברו את הירדן וילכו כל הבתרון ויבאו מחנים׃ ");
INSERT INTO heb_vpl VALUES ("S22_30","011_2_30","2SA","2","30","30","ויואב שב מאחרי אבנר ויקבץ את כל העם ויפקדו מעבדי דוד תשעה עשר איש ועשהאל׃ ");
INSERT INTO heb_vpl VALUES ("S22_31","011_2_31","2SA","2","31","31","ועבדי דוד הכו מבנימן ובאנשי אבנר שלש מאות וששים איש מתו׃ ");
INSERT INTO heb_vpl VALUES ("S22_32","011_2_32","2SA","2","32","32","וישאו את עשהאל ויקברהו בקבר אביו אשר בית לחם וילכו כל הלילה יואב ואנשיו ויאר להם בחברון׃ ");
INSERT INTO heb_vpl VALUES ("S23_1","011_3_1","2SA","3","1","1","ותהי המלחמה ארכה בין בית שאול ובין בית דוד ודוד הלך וחזק ובית שאול הלכים ודלים׃ ");
INSERT INTO heb_vpl VALUES ("S23_2","011_3_2","2SA","3","2","2","וילדו לדוד בנים בחברון ויהי בכורו אמנון לאחינעם היזרעאלת׃ ");
INSERT INTO heb_vpl VALUES ("S23_3","011_3_3","2SA","3","3","3","ומשנהו כלאב לאביגל אשת נבל הכרמלי והשלשי אבשלום בן מעכה בת תלמי מלך גשור׃ ");
INSERT INTO heb_vpl VALUES ("S23_4","011_3_4","2SA","3","4","4","והרביעי אדניה בן חגית והחמישי שפטיה בן אביטל׃ ");
INSERT INTO heb_vpl VALUES ("S23_5","011_3_5","2SA","3","5","5","והששי יתרעם לעגלה אשת דוד אלה ילדו לדוד בחברון׃ ");
INSERT INTO heb_vpl VALUES ("S23_6","011_3_6","2SA","3","6","6","ויהי בהיות המלחמה בין בית שאול ובין בית דוד ואבנר היה מתחזק בבית שאול׃ ");
INSERT INTO heb_vpl VALUES ("S23_7","011_3_7","2SA","3","7","7","ולשאול פלגש ושמה רצפה בת איה ויאמר אל אבנר מדוע באתה אל פילגש אבי׃ ");
INSERT INTO heb_vpl VALUES ("S23_8","011_3_8","2SA","3","8","8","ויחר לאבנר מאד על דברי איש בשת ויאמר הראש כלב אנכי אשר ליהודה היום אעשה חסד עם בית שאול אביך אל אחיו ואל מרעהו ולא המציתך ביד דוד ותפקד עלי עון האשה היום׃ ");
INSERT INTO heb_vpl VALUES ("S23_9","011_3_9","2SA","3","9","9","כה יעשה אלהים לאבנר וכה יסיף לו כי כאשר נשבע יהוה לדוד כי כן אעשה לו׃ ");
INSERT INTO heb_vpl VALUES ("S23_10","011_3_10","2SA","3","10","10","להעביר הממלכה מבית שאול ולהקים את כסא דוד על ישראל ועל יהודה מדן ועד באר שבע׃ ");
INSERT INTO heb_vpl VALUES ("S23_11","011_3_11","2SA","3","11","11","ולא יכל עוד להשיב את אבנר דבר מיראתו אתו׃ ");
INSERT INTO heb_vpl VALUES ("S23_12","011_3_12","2SA","3","12","12","וישלח אבנר מלאכים אל דוד תחתו לאמר למי ארץ לאמר כרתה בריתך אתי והנה ידי עמך להסב אליך את כל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S23_13","011_3_13","2SA","3","13","13","ויאמר טוב אני אכרת אתך ברית אך דבר אחד אנכי שאל מאתך לאמר לא תראה את פני כי אם לפני הביאך את מיכל בת שאול בבאך לראות את פני׃ ");
INSERT INTO heb_vpl VALUES ("S23_14","011_3_14","2SA","3","14","14","וישלח דוד מלאכים אל איש בשת בן שאול לאמר תנה את אשתי את מיכל אשר ארשתי לי במאה ערלות פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S23_15","011_3_15","2SA","3","15","15","וישלח איש בשת ויקחה מעם איש מעם פלטיאל בן לוש׃ ");
INSERT INTO heb_vpl VALUES ("S23_16","011_3_16","2SA","3","16","16","וילך אתה אישה הלוך ובכה אחריה עד בחרים ויאמר אליו אבנר לך שוב וישב׃ ");
INSERT INTO heb_vpl VALUES ("S23_17","011_3_17","2SA","3","17","17","ודבר אבנר היה עם זקני ישראל לאמר גם תמול גם שלשם הייתם מבקשים את דוד למלך עליכם׃ ");
INSERT INTO heb_vpl VALUES ("S23_18","011_3_18","2SA","3","18","18","ועתה עשו כי יהוה אמר אל דוד לאמר ביד דוד עבדי הושיע את עמי ישראל מיד פלשתים ומיד כל איביהם׃ ");
INSERT INTO heb_vpl VALUES ("S23_19","011_3_19","2SA","3","19","19","וידבר גם אבנר באזני בנימין וילך גם אבנר לדבר באזני דוד בחברון את כל אשר טוב בעיני ישראל ובעיני כל בית בנימן׃ ");
INSERT INTO heb_vpl VALUES ("S23_20","011_3_20","2SA","3","20","20","ויבא אבנר אל דוד חברון ואתו עשרים אנשים ויעש דוד לאבנר ולאנשים אשר אתו משתה׃ ");
INSERT INTO heb_vpl VALUES ("S23_21","011_3_21","2SA","3","21","21","ויאמר אבנר אל דוד אקומה ואלכה ואקבצה אל אדני המלך את כל ישראל ויכרתו אתך ברית ומלכת בכל אשר תאוה נפשך וישלח דוד את אבנר וילך בשלום׃ ");
INSERT INTO heb_vpl VALUES ("S23_22","011_3_22","2SA","3","22","22","והנה עבדי דוד ויואב בא מהגדוד ושלל רב עמם הביאו ואבנר איננו עם דוד בחברון כי שלחו וילך בשלום׃ ");
INSERT INTO heb_vpl VALUES ("S23_23","011_3_23","2SA","3","23","23","ויואב וכל הצבא אשר אתו באו ויגדו ליואב לאמר בא אבנר בן נר אל המלך וישלחהו וילך בשלום׃ ");
INSERT INTO heb_vpl VALUES ("S23_24","011_3_24","2SA","3","24","24","ויבא יואב אל המלך ויאמר מה עשיתה הנה בא אבנר אליך למה זה שלחתו וילך הלוך׃ ");
INSERT INTO heb_vpl VALUES ("S23_25","011_3_25","2SA","3","25","25","ידעת את אבנר בן נר כי לפתתך בא ולדעת את מוצאך ואת מבואך ולדעת את כל אשר אתה עשה׃ ");
INSERT INTO heb_vpl VALUES ("S23_26","011_3_26","2SA","3","26","26","ויצא יואב מעם דוד וישלח מלאכים אחרי אבנר וישבו אתו מבור הסרה ודוד לא ידע׃ ");
INSERT INTO heb_vpl VALUES ("S23_27","011_3_27","2SA","3","27","27","וישב אבנר חברון ויטהו יואב אל תוך השער לדבר אתו בשלי ויכהו שם החמש וימת בדם עשה אל אחיו׃ ");
INSERT INTO heb_vpl VALUES ("S23_28","011_3_28","2SA","3","28","28","וישמע דוד מאחרי כן ויאמר נקי אנכי וממלכתי מעם יהוה עד עולם מדמי אבנר בן נר׃ ");
INSERT INTO heb_vpl VALUES ("S23_29","011_3_29","2SA","3","29","29","יחלו על ראש יואב ואל כל בית אביו ואל יכרת מבית יואב זב ומצרע ומחזיק בפלך ונפל בחרב וחסר לחם׃ ");
INSERT INTO heb_vpl VALUES ("S23_30","011_3_30","2SA","3","30","30","ויואב ואבישי אחיו הרגו לאבנר על אשר המית את עשהאל אחיהם בגבעון במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("S23_31","011_3_31","2SA","3","31","31","ויאמר דוד אל יואב ואל כל העם אשר אתו קרעו בגדיכם וחגרו שקים וספדו לפני אבנר והמלך דוד הלך אחרי המטה׃ ");
INSERT INTO heb_vpl VALUES ("S23_32","011_3_32","2SA","3","32","32","ויקברו את אבנר בחברון וישא המלך את קולו ויבך אל קבר אבנר ויבכו כל העם׃ ");
INSERT INTO heb_vpl VALUES ("S23_33","011_3_33","2SA","3","33","33","ויקנן המלך אל אבנר ויאמר הכמות נבל ימות אבנר׃ ");
INSERT INTO heb_vpl VALUES ("S23_34","011_3_34","2SA","3","34","34","ידך לא אסרות ורגליך לא לנחשתים הגשו כנפול לפני בני עולה נפלת ויספו כל העם לבכות עליו׃ ");
INSERT INTO heb_vpl VALUES ("S23_35","011_3_35","2SA","3","35","35","ויבא כל העם להברות את דוד לחם בעוד היום וישבע דוד לאמר כה יעשה לי אלהים וכה יסיף כי אם לפני בוא השמש אטעם לחם או כל מאומה׃ ");
INSERT INTO heb_vpl VALUES ("S23_36","011_3_36","2SA","3","36","36","וכל העם הכירו וייטב בעיניהם ככל אשר עשה המלך בעיני כל העם טוב׃ ");
INSERT INTO heb_vpl VALUES ("S23_37","011_3_37","2SA","3","37","37","וידעו כל העם וכל ישראל ביום ההוא כי לא היתה מהמלך להמית את אבנר בן נר׃ ");
INSERT INTO heb_vpl VALUES ("S23_38","011_3_38","2SA","3","38","38","ויאמר המלך אל עבדיו הלוא תדעו כי שר וגדול נפל היום הזה בישראל׃ ");
INSERT INTO heb_vpl VALUES ("S23_39","011_3_39","2SA","3","39","39","ואנכי היום רך ומשוח מלך והאנשים האלה בני צרויה קשים ממני ישלם יהוה לעשה הרעה כרעתו׃ ");
INSERT INTO heb_vpl VALUES ("S24_1","011_4_1","2SA","4","1","1","וישמע בן שאול כי מת אבנר בחברון וירפו ידיו וכל ישראל נבהלו׃ ");
INSERT INTO heb_vpl VALUES ("S24_2","011_4_2","2SA","4","2","2","ושני אנשים שרי גדודים היו בן שאול שם האחד בענה ושם השני רכב בני רמון הבארתי מבני בנימן כי גם בארות תחשב על בנימן׃ ");
INSERT INTO heb_vpl VALUES ("S24_3","011_4_3","2SA","4","3","3","ויברחו הבארתים גתימה ויהיו שם גרים עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S24_4","011_4_4","2SA","4","4","4","וליהונתן בן שאול בן נכה רגלים בן חמש שנים היה בבא שמעת שאול ויהונתן מיזרעאל ותשאהו אמנתו ותנס ויהי בחפזה לנוס ויפל ויפסח ושמו מפיבשת׃ ");
INSERT INTO heb_vpl VALUES ("S24_5","011_4_5","2SA","4","5","5","וילכו בני רמון הבארתי רכב ובענה ויבאו כחם היום אל בית איש בשת והוא שכב את משכב הצהרים׃ ");
INSERT INTO heb_vpl VALUES ("S24_6","011_4_6","2SA","4","6","6","והנה באו עד תוך הבית לקחי חטים ויכהו אל החמש ורכב ובענה אחיו נמלטו׃ ");
INSERT INTO heb_vpl VALUES ("S24_7","011_4_7","2SA","4","7","7","ויבאו הבית והוא שכב על מטתו בחדר משכבו ויכהו וימתהו ויסירו את ראשו ויקחו את ראשו וילכו דרך הערבה כל הלילה׃ ");
INSERT INTO heb_vpl VALUES ("S24_8","011_4_8","2SA","4","8","8","ויבאו את ראש איש בשת אל דוד חברון ויאמרו אל המלך הנה ראש איש בשת בן שאול איבך אשר בקש את נפשך ויתן יהוה לאדני המלך נקמות היום הזה משאול ומזרעו׃ ");
INSERT INTO heb_vpl VALUES ("S24_9","011_4_9","2SA","4","9","9","ויען דוד את רכב ואת בענה אחיו בני רמון הבארתי ויאמר להם חי יהוה אשר פדה את נפשי מכל צרה׃ ");
INSERT INTO heb_vpl VALUES ("S24_10","011_4_10","2SA","4","10","10","כי המגיד לי לאמר הנה מת שאול והוא היה כמבשר בעיניו ואחזה בו ואהרגהו בצקלג אשר לתתי לו בשרה׃ ");
INSERT INTO heb_vpl VALUES ("S24_11","011_4_11","2SA","4","11","11","אף כי אנשים רשעים הרגו את איש צדיק בביתו על משכבו ועתה הלוא אבקש את דמו מידכם ובערתי אתכם מן הארץ׃ ");
INSERT INTO heb_vpl VALUES ("S24_12","011_4_12","2SA","4","12","12","ויצו דוד את הנערים ויהרגום ויקצצו את ידיהם ואת רגליהם ויתלו על הברכה בחברון ואת ראש איש בשת לקחו ויקברו בקבר אבנר בחברון׃ ");
INSERT INTO heb_vpl VALUES ("S25_1","011_5_1","2SA","5","1","1","ויבאו כל שבטי ישראל אל דוד חברונה ויאמרו לאמר הננו עצמך ובשרך אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("S25_2","011_5_2","2SA","5","2","2","גם אתמול גם שלשום בהיות שאול מלך עלינו אתה הייתה מוציא והמבי את ישראל ויאמר יהוה לך אתה תרעה את עמי את ישראל ואתה תהיה לנגיד על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S25_3","011_5_3","2SA","5","3","3","ויבאו כל זקני ישראל אל המלך חברונה ויכרת להם המלך דוד ברית בחברון לפני יהוה וימשחו את דוד למלך על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S25_4","011_5_4","2SA","5","4","4","בן שלשים שנה דוד במלכו ארבעים שנה מלך׃ ");
INSERT INTO heb_vpl VALUES ("S25_5","011_5_5","2SA","5","5","5","בחברון מלך על יהודה שבע שנים וששה חדשים ובירושלם מלך שלשים ושלש שנה על כל ישראל ויהודה׃ ");
INSERT INTO heb_vpl VALUES ("S25_6","011_5_6","2SA","5","6","6","וילך המלך ואנשיו ירושלם אל היבסי יושב הארץ ויאמר לדוד לאמר לא תבוא הנה כי אם הסירך העורים והפסחים לאמר לא יבוא דוד הנה׃ ");
INSERT INTO heb_vpl VALUES ("S25_7","011_5_7","2SA","5","7","7","וילכד דוד את מצדת ציון היא עיר דוד׃ ");
INSERT INTO heb_vpl VALUES ("S25_8","011_5_8","2SA","5","8","8","ויאמר דוד ביום ההוא כל מכה יבסי ויגע בצנור ואת הפסחים ואת העורים שנאו נפש דוד על כן יאמרו עור ופסח לא יבוא אל הבית׃ ");
INSERT INTO heb_vpl VALUES ("S25_9","011_5_9","2SA","5","9","9","וישב דוד במצדה ויקרא לה עיר דוד ויבן דוד סביב מן המלוא וביתה׃ ");
INSERT INTO heb_vpl VALUES ("S25_10","011_5_10","2SA","5","10","10","וילך דוד הלוך וגדול ויהוה אלהי צבאות עמו׃ ");
INSERT INTO heb_vpl VALUES ("S25_11","011_5_11","2SA","5","11","11","וישלח חירם מלך צר מלאכים אל דוד ועצי ארזים וחרשי עץ וחרשי אבן קיר ויבנו בית לדוד׃ ");
INSERT INTO heb_vpl VALUES ("S25_12","011_5_12","2SA","5","12","12","וידע דוד כי הכינו יהוה למלך על ישראל וכי נשא ממלכתו בעבור עמו ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S25_13","011_5_13","2SA","5","13","13","ויקח דוד עוד פלגשים ונשים מירושלם אחרי באו מחברון ויולדו עוד לדוד בנים ובנות׃ ");
INSERT INTO heb_vpl VALUES ("S25_14","011_5_14","2SA","5","14","14","ואלה שמות הילדים לו בירושלם שמוע ושובב ונתן ושלמה׃ ");
INSERT INTO heb_vpl VALUES ("S25_15","011_5_15","2SA","5","15","15","ויבחר ואלישוע ונפג ויפיע׃ ");
INSERT INTO heb_vpl VALUES ("S25_16","011_5_16","2SA","5","16","16","ואלישמע ואלידע ואליפלט׃ ");
INSERT INTO heb_vpl VALUES ("S25_17","011_5_17","2SA","5","17","17","וישמעו פלשתים כי משחו את דוד למלך על ישראל ויעלו כל פלשתים לבקש את דוד וישמע דוד וירד אל המצודה׃ ");
INSERT INTO heb_vpl VALUES ("S25_18","011_5_18","2SA","5","18","18","ופלשתים באו וינטשו בעמק רפאים׃ ");
INSERT INTO heb_vpl VALUES ("S25_19","011_5_19","2SA","5","19","19","וישאל דוד ביהוה לאמר האעלה אל פלשתים התתנם בידי ויאמר יהוה אל דוד עלה כי נתן אתן את הפלשתים בידך׃ ");
INSERT INTO heb_vpl VALUES ("S25_20","011_5_20","2SA","5","20","20","ויבא דוד בבעל פרצים ויכם שם דוד ויאמר פרץ יהוה את איבי לפני כפרץ מים על כן קרא שם המקום ההוא בעל פרצים׃ ");
INSERT INTO heb_vpl VALUES ("S25_21","011_5_21","2SA","5","21","21","ויעזבו שם את עצביהם וישאם דוד ואנשיו׃ ");
INSERT INTO heb_vpl VALUES ("S25_22","011_5_22","2SA","5","22","22","ויספו עוד פלשתים לעלות וינטשו בעמק רפאים׃ ");
INSERT INTO heb_vpl VALUES ("S25_23","011_5_23","2SA","5","23","23","וישאל דוד ביהוה ויאמר לא תעלה הסב אל אחריהם ובאת להם ממול בכאים׃ ");
INSERT INTO heb_vpl VALUES ("S25_24","011_5_24","2SA","5","24","24","ויהי בשמעך את קול צעדה בראשי הבכאים אז תחרץ כי אז יצא יהוה לפניך להכות במחנה פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S25_25","011_5_25","2SA","5","25","25","ויעש דוד כן כאשר צוהו יהוה ויך את פלשתים מגבע עד באך גזר׃ ");
INSERT INTO heb_vpl VALUES ("S26_1","011_6_1","2SA","6","1","1","ויסף עוד דוד את כל בחור בישראל שלשים אלף׃ ");
INSERT INTO heb_vpl VALUES ("S26_2","011_6_2","2SA","6","2","2","ויקם וילך דוד וכל העם אשר אתו מבעלי יהודה להעלות משם את ארון האלהים אשר נקרא שם שם יהוה צבאות ישב הכרבים עליו׃ ");
INSERT INTO heb_vpl VALUES ("S26_3","011_6_3","2SA","6","3","3","וירכבו את ארון האלהים אל עגלה חדשה וישאהו מבית אבינדב אשר בגבעה ועזא ואחיו בני אבינדב נהגים את העגלה חדשה׃ ");
INSERT INTO heb_vpl VALUES ("S26_4","011_6_4","2SA","6","4","4","וישאהו מבית אבינדב אשר בגבעה עם ארון האלהים ואחיו הלך לפני הארון׃ ");
INSERT INTO heb_vpl VALUES ("S26_5","011_6_5","2SA","6","5","5","ודוד וכל בית ישראל משחקים לפני יהוה בכל עצי ברושים ובכנרות ובנבלים ובתפים ובמנענעים ובצלצלים׃ ");
INSERT INTO heb_vpl VALUES ("S26_6","011_6_6","2SA","6","6","6","ויבאו עד גרן נכון וישלח עזא אל ארון האלהים ויאחז בו כי שמטו הבקר׃ ");
INSERT INTO heb_vpl VALUES ("S26_7","011_6_7","2SA","6","7","7","ויחר אף יהוה בעזה ויכהו שם האלהים על השל וימת שם עם ארון האלהים׃ ");
INSERT INTO heb_vpl VALUES ("S26_8","011_6_8","2SA","6","8","8","ויחר לדוד על אשר פרץ יהוה פרץ בעזה ויקרא למקום ההוא פרץ עזה עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S26_9","011_6_9","2SA","6","9","9","וירא דוד את יהוה ביום ההוא ויאמר איך יבוא אלי ארון יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S26_10","011_6_10","2SA","6","10","10","ולא אבה דוד להסיר אליו את ארון יהוה על עיר דוד ויטהו דוד בית עבד אדום הגתי׃ ");
INSERT INTO heb_vpl VALUES ("S26_11","011_6_11","2SA","6","11","11","וישב ארון יהוה בית עבד אדם הגתי שלשה חדשים ויברך יהוה את עבד אדם ואת כל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("S26_12","011_6_12","2SA","6","12","12","ויגד למלך דוד לאמר ברך יהוה את בית עבד אדם ואת כל אשר לו בעבור ארון האלהים וילך דוד ויעל את ארון האלהים מבית עבד אדם עיר דוד בשמחה׃ ");
INSERT INTO heb_vpl VALUES ("S26_13","011_6_13","2SA","6","13","13","ויהי כי צעדו נשאי ארון יהוה ששה צעדים ויזבח שור ומריא׃ ");
INSERT INTO heb_vpl VALUES ("S26_14","011_6_14","2SA","6","14","14","ודוד מכרכר בכל עז לפני יהוה ודוד חגור אפוד בד׃ ");
INSERT INTO heb_vpl VALUES ("S26_15","011_6_15","2SA","6","15","15","ודוד וכל בית ישראל מעלים את ארון יהוה בתרועה ובקול שופר׃ ");
INSERT INTO heb_vpl VALUES ("S26_16","011_6_16","2SA","6","16","16","והיה ארון יהוה בא עיר דוד ומיכל בת שאול נשקפה בעד החלון ותרא את המלך דוד מפזז ומכרכר לפני יהוה ותבז לו בלבה׃ ");
INSERT INTO heb_vpl VALUES ("S26_17","011_6_17","2SA","6","17","17","ויבאו את ארון יהוה ויצגו אתו במקומו בתוך האהל אשר נטה לו דוד ויעל דוד עלות לפני יהוה ושלמים׃ ");
INSERT INTO heb_vpl VALUES ("S26_18","011_6_18","2SA","6","18","18","ויכל דוד מהעלות העולה והשלמים ויברך את העם בשם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("S26_19","011_6_19","2SA","6","19","19","ויחלק לכל העם לכל המון ישראל למאיש ועד אשה לאיש חלת לחם אחת ואשפר אחד ואשישה אחת וילך כל העם איש לביתו׃ ");
INSERT INTO heb_vpl VALUES ("S26_20","011_6_20","2SA","6","20","20","וישב דוד לברך את ביתו ותצא מיכל בת שאול לקראת דוד ותאמר מה נכבד היום מלך ישראל אשר נגלה היום לעיני אמהות עבדיו כהגלות נגלות אחד הרקים׃ ");
INSERT INTO heb_vpl VALUES ("S26_21","011_6_21","2SA","6","21","21","ויאמר דוד אל מיכל לפני יהוה אשר בחר בי מאביך ומכל ביתו לצות אתי נגיד על עם יהוה על ישראל ושחקתי לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S26_22","011_6_22","2SA","6","22","22","ונקלתי עוד מזאת והייתי שפל בעיני ועם האמהות אשר אמרת עמם אכבדה׃ ");
INSERT INTO heb_vpl VALUES ("S26_23","011_6_23","2SA","6","23","23","ולמיכל בת שאול לא היה לה ילד עד יום מותה׃ ");
INSERT INTO heb_vpl VALUES ("S27_1","011_7_1","2SA","7","1","1","ויהי כי ישב המלך בביתו ויהוה הניח לו מסביב מכל איביו׃ ");
INSERT INTO heb_vpl VALUES ("S27_2","011_7_2","2SA","7","2","2","ויאמר המלך אל נתן הנביא ראה נא אנכי יושב בבית ארזים וארון האלהים ישב בתוך היריעה׃ ");
INSERT INTO heb_vpl VALUES ("S27_3","011_7_3","2SA","7","3","3","ויאמר נתן אל המלך כל אשר בלבבך לך עשה כי יהוה עמך׃ ");
INSERT INTO heb_vpl VALUES ("S27_4","011_7_4","2SA","7","4","4","ויהי בלילה ההוא ויהי דבר יהוה אל נתן לאמר׃ ");
INSERT INTO heb_vpl VALUES ("S27_5","011_7_5","2SA","7","5","5","לך ואמרת אל עבדי אל דוד כה אמר יהוה האתה תבנה לי בית לשבתי׃ ");
INSERT INTO heb_vpl VALUES ("S27_6","011_7_6","2SA","7","6","6","כי לא ישבתי בבית למיום העלתי את בני ישראל ממצרים ועד היום הזה ואהיה מתהלך באהל ובמשכן׃ ");
INSERT INTO heb_vpl VALUES ("S27_7","011_7_7","2SA","7","7","7","בכל אשר התהלכתי בכל בני ישראל הדבר דברתי את אחד שבטי ישראל אשר צויתי לרעות את עמי את ישראל לאמר למה לא בניתם לי בית ארזים׃ ");
INSERT INTO heb_vpl VALUES ("S27_8","011_7_8","2SA","7","8","8","ועתה כה תאמר לעבדי לדוד כה אמר יהוה צבאות אני לקחתיך מן הנוה מאחר הצאן להיות נגיד על עמי על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S27_9","011_7_9","2SA","7","9","9","ואהיה עמך בכל אשר הלכת ואכרתה את כל איביך מפניך ועשתי לך שם גדול כשם הגדלים אשר בארץ׃ ");
INSERT INTO heb_vpl VALUES ("S27_10","011_7_10","2SA","7","10","10","ושמתי מקום לעמי לישראל ונטעתיו ושכן תחתיו ולא ירגז עוד ולא יסיפו בני עולה לענותו כאשר בראשונה׃ ");
INSERT INTO heb_vpl VALUES ("S27_11","011_7_11","2SA","7","11","11","ולמן היום אשר צויתי שפטים על עמי ישראל והניחתי לך מכל איביך והגיד לך יהוה כי בית יעשה לך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S27_12","011_7_12","2SA","7","12","12","כי ימלאו ימיך ושכבת את אבתיך והקימתי את זרעך אחריך אשר יצא ממעיך והכינתי את ממלכתו׃ ");
INSERT INTO heb_vpl VALUES ("S27_13","011_7_13","2SA","7","13","13","הוא יבנה בית לשמי וכננתי את כסא ממלכתו עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("S27_14","011_7_14","2SA","7","14","14","אני אהיה לו לאב והוא יהיה לי לבן אשר בהעותו והכחתיו בשבט אנשים ובנגעי בני אדם׃ ");
INSERT INTO heb_vpl VALUES ("S27_15","011_7_15","2SA","7","15","15","וחסדי לא יסור ממנו כאשר הסרתי מעם שאול אשר הסרתי מלפניך׃ ");
INSERT INTO heb_vpl VALUES ("S27_16","011_7_16","2SA","7","16","16","ונאמן ביתך וממלכתך עד עולם לפניך כסאך יהיה נכון עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("S27_17","011_7_17","2SA","7","17","17","ככל הדברים האלה וככל החזיון הזה כן דבר נתן אל דוד׃ ");
INSERT INTO heb_vpl VALUES ("S27_18","011_7_18","2SA","7","18","18","ויבא המלך דוד וישב לפני יהוה ויאמר מי אנכי אדני יהוה ומי ביתי כי הביאתני עד הלם׃ ");
INSERT INTO heb_vpl VALUES ("S27_19","011_7_19","2SA","7","19","19","ותקטן עוד זאת בעיניך אדני יהוה ותדבר גם אל בית עבדך למרחוק וזאת תורת האדם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S27_20","011_7_20","2SA","7","20","20","ומה יוסיף דוד עוד לדבר אליך ואתה ידעת את עבדך אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S27_21","011_7_21","2SA","7","21","21","בעבור דברך וכלבך עשית את כל הגדולה הזאת להודיע את עבדך׃ ");
INSERT INTO heb_vpl VALUES ("S27_22","011_7_22","2SA","7","22","22","על כן גדלת אדני יהוה כי אין כמוך ואין אלהים זולתך בכל אשר שמענו באזנינו׃ ");
INSERT INTO heb_vpl VALUES ("S27_23","011_7_23","2SA","7","23","23","ומי כעמך כישראל גוי אחד בארץ אשר הלכו אלהים לפדות לו לעם ולשום לו שם ולעשות לכם הגדולה ונראות לארצך מפני עמך אשר פדית לך ממצרים גוים ואלהיו׃ ");
INSERT INTO heb_vpl VALUES ("S27_24","011_7_24","2SA","7","24","24","ותכונן לך את עמך ישראל לך לעם עד עולם ואתה יהוה היית להם לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("S27_25","011_7_25","2SA","7","25","25","ועתה יהוה אלהים הדבר אשר דברת על עבדך ועל ביתו הקם עד עולם ועשה כאשר דברת׃ ");
INSERT INTO heb_vpl VALUES ("S27_26","011_7_26","2SA","7","26","26","ויגדל שמך עד עולם לאמר יהוה צבאות אלהים על ישראל ובית עבדך דוד יהיה נכון לפניך׃ ");
INSERT INTO heb_vpl VALUES ("S27_27","011_7_27","2SA","7","27","27","כי אתה יהוה צבאות אלהי ישראל גליתה את אזן עבדך לאמר בית אבנה לך על כן מצא עבדך את לבו להתפלל אליך את התפלה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("S27_28","011_7_28","2SA","7","28","28","ועתה אדני יהוה אתה הוא האלהים ודבריך יהיו אמת ותדבר אל עבדך את הטובה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("S27_29","011_7_29","2SA","7","29","29","ועתה הואל וברך את בית עבדך להיות לעולם לפניך כי אתה אדני יהוה דברת ומברכתך יברך בית עבדך לעולם׃ ");
INSERT INTO heb_vpl VALUES ("S28_1","011_8_1","2SA","8","1","1","ויהי אחרי כן ויך דוד את פלשתים ויכניעם ויקח דוד את מתג האמה מיד פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S28_2","011_8_2","2SA","8","2","2","ויך את מואב וימדדם בחבל השכב אותם ארצה וימדד שני חבלים להמית ומלא החבל להחיות ותהי מואב לדוד לעבדים נשאי מנחה׃ ");
INSERT INTO heb_vpl VALUES ("S28_3","011_8_3","2SA","8","3","3","ויך דוד את הדדעזר בן רחב מלך צובה בלכתו להשיב ידו בנהר׃ ");
INSERT INTO heb_vpl VALUES ("S28_4","011_8_4","2SA","8","4","4","וילכד דוד ממנו אלף ושבע מאות פרשים ועשרים אלף איש רגלי ויעקר דוד את כל הרכב ויותר ממנו מאה רכב׃ ");
INSERT INTO heb_vpl VALUES ("S28_5","011_8_5","2SA","8","5","5","ותבא ארם דמשק לעזר להדדעזר מלך צובה ויך דוד בארם עשרים ושנים אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("S28_6","011_8_6","2SA","8","6","6","וישם דוד נצבים בארם דמשק ותהי ארם לדוד לעבדים נושאי מנחה וישע יהוה את דוד בכל אשר הלך׃ ");
INSERT INTO heb_vpl VALUES ("S28_7","011_8_7","2SA","8","7","7","ויקח דוד את שלטי הזהב אשר היו אל עבדי הדדעזר ויביאם ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S28_8","011_8_8","2SA","8","8","8","ומבטח ומברתי ערי הדדעזר לקח המלך דוד נחשת הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("S28_9","011_8_9","2SA","8","9","9","וישמע תעי מלך חמת כי הכה דוד את כל חיל הדדעזר׃ ");
INSERT INTO heb_vpl VALUES ("S28_10","011_8_10","2SA","8","10","10","וישלח תעי את יורם בנו אל המלך דוד לשאל לו לשלום ולברכו על אשר נלחם בהדדעזר ויכהו כי איש מלחמות תעי היה הדדעזר ובידו היו כלי כסף וכלי זהב וכלי נחשת׃ ");
INSERT INTO heb_vpl VALUES ("S28_11","011_8_11","2SA","8","11","11","גם אתם הקדיש המלך דוד ליהוה עם הכסף והזהב אשר הקדיש מכל הגוים אשר כבש׃ ");
INSERT INTO heb_vpl VALUES ("S28_12","011_8_12","2SA","8","12","12","מארם וממואב ומבני עמון ומפלשתים ומעמלק ומשלל הדדעזר בן רחב מלך צובה׃ ");
INSERT INTO heb_vpl VALUES ("S28_13","011_8_13","2SA","8","13","13","ויעש דוד שם בשבו מהכותו את ארם בגיא מלח שמונה עשר אלף׃ ");
INSERT INTO heb_vpl VALUES ("S28_14","011_8_14","2SA","8","14","14","וישם באדום נצבים בכל אדום שם נצבים ויהי כל אדום עבדים לדוד ויושע יהוה את דוד בכל אשר הלך׃ ");
INSERT INTO heb_vpl VALUES ("S28_15","011_8_15","2SA","8","15","15","וימלך דוד על כל ישראל ויהי דוד עשה משפט וצדקה לכל עמו׃ ");
INSERT INTO heb_vpl VALUES ("S28_16","011_8_16","2SA","8","16","16","ויואב בן צרויה על הצבא ויהושפט בן אחילוד מזכיר׃ ");
INSERT INTO heb_vpl VALUES ("S28_17","011_8_17","2SA","8","17","17","וצדוק בן אחיטוב ואחימלך בן אביתר כהנים ושריה סופר׃ ");
INSERT INTO heb_vpl VALUES ("S28_18","011_8_18","2SA","8","18","18","ובניהו בן יהוידע והכרתי והפלתי ובני דוד כהנים היו׃ ");
INSERT INTO heb_vpl VALUES ("S29_1","011_9_1","2SA","9","1","1","ויאמר דוד הכי יש עוד אשר נותר לבית שאול ואעשה עמו חסד בעבור יהונתן׃ ");
INSERT INTO heb_vpl VALUES ("S29_2","011_9_2","2SA","9","2","2","ולבית שאול עבד ושמו ציבא ויקראו לו אל דוד ויאמר המלך אליו האתה ציבא ויאמר עבדך׃ ");
INSERT INTO heb_vpl VALUES ("S29_3","011_9_3","2SA","9","3","3","ויאמר המלך האפס עוד איש לבית שאול ואעשה עמו חסד אלהים ויאמר ציבא אל המלך עוד בן ליהונתן נכה רגלים׃ ");
INSERT INTO heb_vpl VALUES ("S29_4","011_9_4","2SA","9","4","4","ויאמר לו המלך איפה הוא ויאמר ציבא אל המלך הנה הוא בית מכיר בן עמיאל בלו דבר׃ ");
INSERT INTO heb_vpl VALUES ("S29_5","011_9_5","2SA","9","5","5","וישלח המלך דוד ויקחהו מבית מכיר בן עמיאל מלו דבר׃ ");
INSERT INTO heb_vpl VALUES ("S29_6","011_9_6","2SA","9","6","6","ויבא מפיבשת בן יהונתן בן שאול אל דוד ויפל על פניו וישתחו ויאמר דוד מפיבשת ויאמר הנה עבדך׃ ");
INSERT INTO heb_vpl VALUES ("S29_7","011_9_7","2SA","9","7","7","ויאמר לו דוד אל תירא כי עשה אעשה עמך חסד בעבור יהונתן אביך והשבתי לך את כל שדה שאול אביך ואתה תאכל לחם על שלחני תמיד׃ ");
INSERT INTO heb_vpl VALUES ("S29_8","011_9_8","2SA","9","8","8","וישתחו ויאמר מה עבדך כי פנית אל הכלב המת אשר כמוני׃ ");
INSERT INTO heb_vpl VALUES ("S29_9","011_9_9","2SA","9","9","9","ויקרא המלך אל ציבא נער שאול ויאמר אליו כל אשר היה לשאול ולכל ביתו נתתי לבן אדניך׃ ");
INSERT INTO heb_vpl VALUES ("S29_10","011_9_10","2SA","9","10","10","ועבדת לו את האדמה אתה ובניך ועבדיך והבאת והיה לבן אדניך לחם ואכלו ומפיבשת בן אדניך יאכל תמיד לחם על שלחני ולציבא חמשה עשר בנים ועשרים עבדים׃ ");
INSERT INTO heb_vpl VALUES ("S29_11","011_9_11","2SA","9","11","11","ויאמר ציבא אל המלך ככל אשר יצוה אדני המלך את עבדו כן יעשה עבדך ומפיבשת אכל על שלחני כאחד מבני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S29_12","011_9_12","2SA","9","12","12","ולמפיבשת בן קטן ושמו מיכא וכל מושב בית ציבא עבדים למפיבשת׃ ");
INSERT INTO heb_vpl VALUES ("S29_13","011_9_13","2SA","9","13","13","ומפיבשת ישב בירושלם כי על שלחן המלך תמיד הוא אכל והוא פסח שתי רגליו׃ ");
INSERT INTO heb_vpl VALUES ("S210_1","011_10_1","2SA","10","1","1","ויהי אחרי כן וימת מלך בני עמון וימלך חנון בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("S210_2","011_10_2","2SA","10","2","2","ויאמר דוד אעשה חסד עם חנון בן נחש כאשר עשה אביו עמדי חסד וישלח דוד לנחמו ביד עבדיו אל אביו ויבאו עבדי דוד ארץ בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("S210_3","011_10_3","2SA","10","3","3","ויאמרו שרי בני עמון אל חנון אדניהם המכבד דוד את אביך בעיניך כי שלח לך מנחמים הלוא בעבור חקור את העיר ולרגלה ולהפכה שלח דוד את עבדיו אליך׃ ");
INSERT INTO heb_vpl VALUES ("S210_4","011_10_4","2SA","10","4","4","ויקח חנון את עבדי דוד ויגלח את חצי זקנם ויכרת את מדויהם בחצי עד שתותיהם וישלחם׃ ");
INSERT INTO heb_vpl VALUES ("S210_5","011_10_5","2SA","10","5","5","ויגדו לדוד וישלח לקראתם כי היו האנשים נכלמים מאד ויאמר המלך שבו בירחו עד יצמח זקנכם ושבתם׃ ");
INSERT INTO heb_vpl VALUES ("S210_6","011_10_6","2SA","10","6","6","ויראו בני עמון כי נבאשו בדוד וישלחו בני עמון וישכרו את ארם בית רחוב ואת ארם צובא עשרים אלף רגלי ואת מלך מעכה אלף איש ואיש טוב שנים עשר אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("S210_7","011_10_7","2SA","10","7","7","וישמע דוד וישלח את יואב ואת כל הצבא הגברים׃ ");
INSERT INTO heb_vpl VALUES ("S210_8","011_10_8","2SA","10","8","8","ויצאו בני עמון ויערכו מלחמה פתח השער וארם צובא ורחוב ואיש טוב ומעכה לבדם בשדה׃ ");
INSERT INTO heb_vpl VALUES ("S210_9","011_10_9","2SA","10","9","9","וירא יואב כי היתה אליו פני המלחמה מפנים ומאחור ויבחר מכל בחורי בישראל ויערך לקראת ארם׃ ");
INSERT INTO heb_vpl VALUES ("S210_10","011_10_10","2SA","10","10","10","ואת יתר העם נתן ביד אבשי אחיו ויערך לקראת בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("S210_11","011_10_11","2SA","10","11","11","ויאמר אם תחזק ארם ממני והיתה לי לישועה ואם בני עמון יחזקו ממך והלכתי להושיע לך׃ ");
INSERT INTO heb_vpl VALUES ("S210_12","011_10_12","2SA","10","12","12","חזק ונתחזק בעד עמנו ובעד ערי אלהינו ויהוה יעשה הטוב בעיניו׃ ");
INSERT INTO heb_vpl VALUES ("S210_13","011_10_13","2SA","10","13","13","ויגש יואב והעם אשר עמו למלחמה בארם וינסו מפניו׃ ");
INSERT INTO heb_vpl VALUES ("S210_14","011_10_14","2SA","10","14","14","ובני עמון ראו כי נס ארם וינסו מפני אבישי ויבאו העיר וישב יואב מעל בני עמון ויבא ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S210_15","011_10_15","2SA","10","15","15","וירא ארם כי נגף לפני ישראל ויאספו יחד׃ ");
INSERT INTO heb_vpl VALUES ("S210_16","011_10_16","2SA","10","16","16","וישלח הדדעזר ויצא את ארם אשר מעבר הנהר ויבאו חילם ושובך שר צבא הדדעזר לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("S210_17","011_10_17","2SA","10","17","17","ויגד לדוד ויאסף את כל ישראל ויעבר את הירדן ויבא חלאמה ויערכו ארם לקראת דוד וילחמו עמו׃ ");
INSERT INTO heb_vpl VALUES ("S210_18","011_10_18","2SA","10","18","18","וינס ארם מפני ישראל ויהרג דוד מארם שבע מאות רכב וארבעים אלף פרשים ואת שובך שר צבאו הכה וימת שם׃ ");
INSERT INTO heb_vpl VALUES ("S210_19","011_10_19","2SA","10","19","19","ויראו כל המלכים עבדי הדדעזר כי נגפו לפני ישראל וישלמו את ישראל ויעבדום ויראו ארם להושיע עוד את בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("S211_1","011_11_1","2SA","11","1","1","ויהי לתשובת השנה לעת צאת המלאכים וישלח דוד את יואב ואת עבדיו עמו ואת כל ישראל וישחתו את בני עמון ויצרו על רבה ודוד יושב בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S211_2","011_11_2","2SA","11","2","2","ויהי לעת הערב ויקם דוד מעל משכבו ויתהלך על גג בית המלך וירא אשה רחצת מעל הגג והאשה טובת מראה מאד׃ ");
INSERT INTO heb_vpl VALUES ("S211_3","011_11_3","2SA","11","3","3","וישלח דוד וידרש לאשה ויאמר הלוא זאת בת שבע בת אליעם אשת אוריה החתי׃ ");
INSERT INTO heb_vpl VALUES ("S211_4","011_11_4","2SA","11","4","4","וישלח דוד מלאכים ויקחה ותבוא אליו וישכב עמה והיא מתקדשת מטמאתה ותשב אל ביתה׃ ");
INSERT INTO heb_vpl VALUES ("S211_5","011_11_5","2SA","11","5","5","ותהר האשה ותשלח ותגד לדוד ותאמר הרה אנכי׃ ");
INSERT INTO heb_vpl VALUES ("S211_6","011_11_6","2SA","11","6","6","וישלח דוד אל יואב שלח אלי את אוריה החתי וישלח יואב את אוריה אל דוד׃ ");
INSERT INTO heb_vpl VALUES ("S211_7","011_11_7","2SA","11","7","7","ויבא אוריה אליו וישאל דוד לשלום יואב ולשלום העם ולשלום המלחמה׃ ");
INSERT INTO heb_vpl VALUES ("S211_8","011_11_8","2SA","11","8","8","ויאמר דוד לאוריה רד לביתך ורחץ רגליך ויצא אוריה מבית המלך ותצא אחריו משאת המלך׃ ");
INSERT INTO heb_vpl VALUES ("S211_9","011_11_9","2SA","11","9","9","וישכב אוריה פתח בית המלך את כל עבדי אדניו ולא ירד אל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("S211_10","011_11_10","2SA","11","10","10","ויגדו לדוד לאמר לא ירד אוריה אל ביתו ויאמר דוד אל אוריה הלוא מדרך אתה בא מדוע לא ירדת אל ביתך׃ ");
INSERT INTO heb_vpl VALUES ("S211_11","011_11_11","2SA","11","11","11","ויאמר אוריה אל דוד הארון וישראל ויהודה ישבים בסכות ואדני יואב ועבדי אדני על פני השדה חנים ואני אבוא אל ביתי לאכל ולשתות ולשכב עם אשתי חיך וחי נפשך אם אעשה את הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("S211_12","011_11_12","2SA","11","12","12","ויאמר דוד אל אוריה שב בזה גם היום ומחר אשלחך וישב אוריה בירושלם ביום ההוא וממחרת׃ ");
INSERT INTO heb_vpl VALUES ("S211_13","011_11_13","2SA","11","13","13","ויקרא לו דוד ויאכל לפניו וישת וישכרהו ויצא בערב לשכב במשכבו עם עבדי אדניו ואל ביתו לא ירד׃ ");
INSERT INTO heb_vpl VALUES ("S211_14","011_11_14","2SA","11","14","14","ויהי בבקר ויכתב דוד ספר אל יואב וישלח ביד אוריה׃ ");
INSERT INTO heb_vpl VALUES ("S211_15","011_11_15","2SA","11","15","15","ויכתב בספר לאמר הבו את אוריה אל מול פני המלחמה החזקה ושבתם מאחריו ונכה ומת׃ ");
INSERT INTO heb_vpl VALUES ("S211_16","011_11_16","2SA","11","16","16","ויהי בשמור יואב אל העיר ויתן את אוריה אל המקום אשר ידע כי אנשי חיל שם׃ ");
INSERT INTO heb_vpl VALUES ("S211_17","011_11_17","2SA","11","17","17","ויצאו אנשי העיר וילחמו את יואב ויפל מן העם מעבדי דוד וימת גם אוריה החתי׃ ");
INSERT INTO heb_vpl VALUES ("S211_18","011_11_18","2SA","11","18","18","וישלח יואב ויגד לדוד את כל דברי המלחמה׃ ");
INSERT INTO heb_vpl VALUES ("S211_19","011_11_19","2SA","11","19","19","ויצו את המלאך לאמר ככלותך את כל דברי המלחמה לדבר אל המלך׃ ");
INSERT INTO heb_vpl VALUES ("S211_20","011_11_20","2SA","11","20","20","והיה אם תעלה חמת המלך ואמר לך מדוע נגשתם אל העיר להלחם הלוא ידעתם את אשר ירו מעל החומה׃ ");
INSERT INTO heb_vpl VALUES ("S211_21","011_11_21","2SA","11","21","21","מי הכה את אבימלך בן ירבשת הלוא אשה השליכה עליו פלח רכב מעל החומה וימת בתבץ למה נגשתם אל החומה ואמרת גם עבדך אוריה החתי מת׃ ");
INSERT INTO heb_vpl VALUES ("S211_22","011_11_22","2SA","11","22","22","וילך המלאך ויבא ויגד לדוד את כל אשר שלחו יואב׃ ");
INSERT INTO heb_vpl VALUES ("S211_23","011_11_23","2SA","11","23","23","ויאמר המלאך אל דוד כי גברו עלינו האנשים ויצאו אלינו השדה ונהיה עליהם עד פתח השער׃ ");
INSERT INTO heb_vpl VALUES ("S211_24","011_11_24","2SA","11","24","24","ויראו המוראים אל עבדך מעל החומה וימותו מעבדי המלך וגם עבדך אוריה החתי מת׃ ");
INSERT INTO heb_vpl VALUES ("S211_25","011_11_25","2SA","11","25","25","ויאמר דוד אל המלאך כה תאמר אל יואב אל ירע בעיניך את הדבר הזה כי כזה וכזה תאכל החרב החזק מלחמתך אל העיר והרסה וחזקהו׃ ");
INSERT INTO heb_vpl VALUES ("S211_26","011_11_26","2SA","11","26","26","ותשמע אשת אוריה כי מת אוריה אישה ותספד על בעלה׃ ");
INSERT INTO heb_vpl VALUES ("S211_27","011_11_27","2SA","11","27","27","ויעבר האבל וישלח דוד ויאספה אל ביתו ותהי לו לאשה ותלד לו בן וירע הדבר אשר עשה דוד בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S212_1","011_12_1","2SA","12","1","1","וישלח יהוה את נתן אל דוד ויבא אליו ויאמר לו שני אנשים היו בעיר אחת אחד עשיר ואחד ראש׃ ");
INSERT INTO heb_vpl VALUES ("S212_2","011_12_2","2SA","12","2","2","לעשיר היה צאן ובקר הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("S212_3","011_12_3","2SA","12","3","3","ולרש אין כל כי אם כבשה אחת קטנה אשר קנה ויחיה ותגדל עמו ועם בניו יחדו מפתו תאכל ומכסו תשתה ובחיקו תשכב ותהי לו כבת׃ ");
INSERT INTO heb_vpl VALUES ("S212_4","011_12_4","2SA","12","4","4","ויבא הלך לאיש העשיר ויחמל לקחת מצאנו ומבקרו לעשות לארח הבא לו ויקח את כבשת האיש הראש ויעשה לאיש הבא אליו׃ ");
INSERT INTO heb_vpl VALUES ("S212_5","011_12_5","2SA","12","5","5","ויחר אף דוד באיש מאד ויאמר אל נתן חי יהוה כי בן מות האיש העשה זאת׃ ");
INSERT INTO heb_vpl VALUES ("S212_6","011_12_6","2SA","12","6","6","ואת הכבשה ישלם ארבעתים עקב אשר עשה את הדבר הזה ועל אשר לא חמל׃ ");
INSERT INTO heb_vpl VALUES ("S212_7","011_12_7","2SA","12","7","7","ויאמר נתן אל דוד אתה האיש כה אמר יהוה אלהי ישראל אנכי משחתיך למלך על ישראל ואנכי הצלתיך מיד שאול׃ ");
INSERT INTO heb_vpl VALUES ("S212_8","011_12_8","2SA","12","8","8","ואתנה לך את בית אדניך ואת נשי אדניך בחיקך ואתנה לך את בית ישראל ויהודה ואם מעט ואספה לך כהנה וכהנה׃ ");
INSERT INTO heb_vpl VALUES ("S212_9","011_12_9","2SA","12","9","9","מדוע בזית את דבר יהוה לעשות הרע בעינו את אוריה החתי הכית בחרב ואת אשתו לקחת לך לאשה ואתו הרגת בחרב בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("S212_10","011_12_10","2SA","12","10","10","ועתה לא תסור חרב מביתך עד עולם עקב כי בזתני ותקח את אשת אוריה החתי להיות לך לאשה׃ ");
INSERT INTO heb_vpl VALUES ("S212_11","011_12_11","2SA","12","11","11","כה אמר יהוה הנני מקים עליך רעה מביתך ולקחתי את נשיך לעיניך ונתתי לרעיך ושכב עם נשיך לעיני השמש הזאת׃ ");
INSERT INTO heb_vpl VALUES ("S212_12","011_12_12","2SA","12","12","12","כי אתה עשית בסתר ואני אעשה את הדבר הזה נגד כל ישראל ונגד השמש׃ ");
INSERT INTO heb_vpl VALUES ("S212_13","011_12_13","2SA","12","13","13","ויאמר דוד אל נתן חטאתי ליהוה ויאמר נתן אל דוד גם יהוה העביר חטאתך לא תמות׃ ");
INSERT INTO heb_vpl VALUES ("S212_14","011_12_14","2SA","12","14","14","אפס כי נאץ נאצת את איבי יהוה בדבר הזה גם הבן הילוד לך מות ימות׃ ");
INSERT INTO heb_vpl VALUES ("S212_15","011_12_15","2SA","12","15","15","וילך נתן אל ביתו ויגף יהוה את הילד אשר ילדה אשת אוריה לדוד ויאנש׃ ");
INSERT INTO heb_vpl VALUES ("S212_16","011_12_16","2SA","12","16","16","ויבקש דוד את האלהים בעד הנער ויצם דוד צום ובא ולן ושכב ארצה׃ ");
INSERT INTO heb_vpl VALUES ("S212_17","011_12_17","2SA","12","17","17","ויקמו זקני ביתו עליו להקימו מן הארץ ולא אבה ולא ברא אתם לחם׃ ");
INSERT INTO heb_vpl VALUES ("S212_18","011_12_18","2SA","12","18","18","ויהי ביום השביעי וימת הילד ויראו עבדי דוד להגיד לו כי מת הילד כי אמרו הנה בהיות הילד חי דברנו אליו ולא שמע בקולנו ואיך נאמר אליו מת הילד ועשה רעה׃ ");
INSERT INTO heb_vpl VALUES ("S212_19","011_12_19","2SA","12","19","19","וירא דוד כי עבדיו מתלחשים ויבן דוד כי מת הילד ויאמר דוד אל עבדיו המת הילד ויאמרו מת׃ ");
INSERT INTO heb_vpl VALUES ("S212_20","011_12_20","2SA","12","20","20","ויקם דוד מהארץ וירחץ ויסך ויחלף שמלתו ויבא בית יהוה וישתחו ויבא אל ביתו וישאל וישימו לו לחם ויאכל׃ ");
INSERT INTO heb_vpl VALUES ("S212_21","011_12_21","2SA","12","21","21","ויאמרו עבדיו אליו מה הדבר הזה אשר עשיתה בעבור הילד חי צמת ותבך וכאשר מת הילד קמת ותאכל לחם׃ ");
INSERT INTO heb_vpl VALUES ("S212_22","011_12_22","2SA","12","22","22","ויאמר בעוד הילד חי צמתי ואבכה כי אמרתי מי יודע יחנני יהוה וחי הילד׃ ");
INSERT INTO heb_vpl VALUES ("S212_23","011_12_23","2SA","12","23","23","ועתה מת למה זה אני צם האוכל להשיבו עוד אני הלך אליו והוא לא ישוב אלי׃ ");
INSERT INTO heb_vpl VALUES ("S212_24","011_12_24","2SA","12","24","24","וינחם דוד את בת שבע אשתו ויבא אליה וישכב עמה ותלד בן ויקרא את שמו שלמה ויהוה אהבו׃ ");
INSERT INTO heb_vpl VALUES ("S212_25","011_12_25","2SA","12","25","25","וישלח ביד נתן הנביא ויקרא את שמו ידידיה בעבור יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S212_26","011_12_26","2SA","12","26","26","וילחם יואב ברבת בני עמון וילכד את עיר המלוכה׃ ");
INSERT INTO heb_vpl VALUES ("S212_27","011_12_27","2SA","12","27","27","וישלח יואב מלאכים אל דוד ויאמר נלחמתי ברבה גם לכדתי את עיר המים׃ ");
INSERT INTO heb_vpl VALUES ("S212_28","011_12_28","2SA","12","28","28","ועתה אסף את יתר העם וחנה על העיר ולכדה פן אלכד אני את העיר ונקרא שמי עליה׃ ");
INSERT INTO heb_vpl VALUES ("S212_29","011_12_29","2SA","12","29","29","ויאסף דוד את כל העם וילך רבתה וילחם בה וילכדה׃ ");
INSERT INTO heb_vpl VALUES ("S212_30","011_12_30","2SA","12","30","30","ויקח את עטרת מלכם מעל ראשו ומשקלה ככר זהב ואבן יקרה ותהי על ראש דוד ושלל העיר הוציא הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("S212_31","011_12_31","2SA","12","31","31","ואת העם אשר בה הוציא וישם במגרה ובחרצי הברזל ובמגזרת הברזל והעביר אותם במלכן וכן יעשה לכל ערי בני עמון וישב דוד וכל העם ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S213_1","011_13_1","2SA","13","1","1","ויהי אחרי כן ולאבשלום בן דוד אחות יפה ושמה תמר ויאהבה אמנון בן דוד׃ ");
INSERT INTO heb_vpl VALUES ("S213_2","011_13_2","2SA","13","2","2","ויצר לאמנון להתחלות בעבור תמר אחתו כי בתולה היא ויפלא בעיני אמנון לעשות לה מאומה׃ ");
INSERT INTO heb_vpl VALUES ("S213_3","011_13_3","2SA","13","3","3","ולאמנון רע ושמו יונדב בן שמעה אחי דוד ויונדב איש חכם מאד׃ ");
INSERT INTO heb_vpl VALUES ("S213_4","011_13_4","2SA","13","4","4","ויאמר לו מדוע אתה ככה דל בן המלך בבקר בבקר הלוא תגיד לי ויאמר לו אמנון את תמר אחות אבשלם אחי אני אהב׃ ");
INSERT INTO heb_vpl VALUES ("S213_5","011_13_5","2SA","13","5","5","ויאמר לו יהונדב שכב על משכבך והתחל ובא אביך לראותך ואמרת אליו תבא נא תמר אחותי ותברני לחם ועשתה לעיני את הבריה למען אשר אראה ואכלתי מידה׃ ");
INSERT INTO heb_vpl VALUES ("S213_6","011_13_6","2SA","13","6","6","וישכב אמנון ויתחל ויבא המלך לראתו ויאמר אמנון אל המלך תבוא נא תמר אחתי ותלבב לעיני שתי לבבות ואברה מידה׃ ");
INSERT INTO heb_vpl VALUES ("S213_7","011_13_7","2SA","13","7","7","וישלח דוד אל תמר הביתה לאמר לכי נא בית אמנון אחיך ועשי לו הבריה׃ ");
INSERT INTO heb_vpl VALUES ("S213_8","011_13_8","2SA","13","8","8","ותלך תמר בית אמנון אחיה והוא שכב ותקח את הבצק ותלוש ותלבב לעיניו ותבשל את הלבבות׃ ");
INSERT INTO heb_vpl VALUES ("S213_9","011_13_9","2SA","13","9","9","ותקח את המשרת ותצק לפניו וימאן לאכול ויאמר אמנון הוציאו כל איש מעלי ויצאו כל איש מעליו׃ ");
INSERT INTO heb_vpl VALUES ("S213_10","011_13_10","2SA","13","10","10","ויאמר אמנון אל תמר הביאי הבריה החדר ואברה מידך ותקח תמר את הלבבות אשר עשתה ותבא לאמנון אחיה החדרה׃ ");
INSERT INTO heb_vpl VALUES ("S213_11","011_13_11","2SA","13","11","11","ותגש אליו לאכל ויחזק בה ויאמר לה בואי שכבי עמי אחותי׃ ");
INSERT INTO heb_vpl VALUES ("S213_12","011_13_12","2SA","13","12","12","ותאמר לו אל אחי אל תענני כי לא יעשה כן בישראל אל תעשה את הנבלה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("S213_13","011_13_13","2SA","13","13","13","ואני אנה אוליך את חרפתי ואתה תהיה כאחד הנבלים בישראל ועתה דבר נא אל המלך כי לא ימנעני ממך׃ ");
INSERT INTO heb_vpl VALUES ("S213_14","011_13_14","2SA","13","14","14","ולא אבה לשמע בקולה ויחזק ממנה ויענה וישכב אתה׃ ");
INSERT INTO heb_vpl VALUES ("S213_15","011_13_15","2SA","13","15","15","וישנאה אמנון שנאה גדולה מאד כי גדולה השנאה אשר שנאה מאהבה אשר אהבה ויאמר לה אמנון קומי לכי׃ ");
INSERT INTO heb_vpl VALUES ("S213_16","011_13_16","2SA","13","16","16","ותאמר לו אל אודת הרעה הגדולה הזאת מאחרת אשר עשית עמי לשלחני ולא אבה לשמע לה׃ ");
INSERT INTO heb_vpl VALUES ("S213_17","011_13_17","2SA","13","17","17","ויקרא את נערו משרתו ויאמר שלחו נא את זאת מעלי החוצה ונעל הדלת אחריה׃ ");
INSERT INTO heb_vpl VALUES ("S213_18","011_13_18","2SA","13","18","18","ועליה כתנת פסים כי כן תלבשן בנות המלך הבתולת מעילים ויצא אותה משרתו החוץ ונעל הדלת אחריה׃ ");
INSERT INTO heb_vpl VALUES ("S213_19","011_13_19","2SA","13","19","19","ותקח תמר אפר על ראשה וכתנת הפסים אשר עליה קרעה ותשם ידה על ראשה ותלך הלוך וזעקה׃ ");
INSERT INTO heb_vpl VALUES ("S213_20","011_13_20","2SA","13","20","20","ויאמר אליה אבשלום אחיה האמינון אחיך היה עמך ועתה אחותי החרישי אחיך הוא אל תשיתי את לבך לדבר הזה ותשב תמר ושממה בית אבשלום אחיה׃ ");
INSERT INTO heb_vpl VALUES ("S213_21","011_13_21","2SA","13","21","21","והמלך דוד שמע את כל הדברים האלה ויחר לו מאד׃ ");
INSERT INTO heb_vpl VALUES ("S213_22","011_13_22","2SA","13","22","22","ולא דבר אבשלום עם אמנון למרע ועד טוב כי שנא אבשלום את אמנון על דבר אשר ענה את תמר אחתו׃ ");
INSERT INTO heb_vpl VALUES ("S213_23","011_13_23","2SA","13","23","23","ויהי לשנתים ימים ויהיו גזזים לאבשלום בבעל חצור אשר עם אפרים ויקרא אבשלום לכל בני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S213_24","011_13_24","2SA","13","24","24","ויבא אבשלום אל המלך ויאמר הנה נא גזזים לעבדך ילך נא המלך ועבדיו עם עבדך׃ ");
INSERT INTO heb_vpl VALUES ("S213_25","011_13_25","2SA","13","25","25","ויאמר המלך אל אבשלום אל בני אל נא נלך כלנו ולא נכבד עליך ויפרץ בו ולא אבה ללכת ויברכהו׃ ");
INSERT INTO heb_vpl VALUES ("S213_26","011_13_26","2SA","13","26","26","ויאמר אבשלום ולא ילך נא אתנו אמנון אחי ויאמר לו המלך למה ילך עמך׃ ");
INSERT INTO heb_vpl VALUES ("S213_27","011_13_27","2SA","13","27","27","ויפרץ בו אבשלום וישלח אתו את אמנון ואת כל בני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S213_28","011_13_28","2SA","13","28","28","ויצו אבשלום את נעריו לאמר ראו נא כטוב לב אמנון ביין ואמרתי אליכם הכו את אמנון והמתם אתו אל תיראו הלוא כי אנכי צויתי אתכם חזקו והיו לבני חיל׃ ");
INSERT INTO heb_vpl VALUES ("S213_29","011_13_29","2SA","13","29","29","ויעשו נערי אבשלום לאמנון כאשר צוה אבשלום ויקמו כל בני המלך וירכבו איש על פרדו וינסו׃ ");
INSERT INTO heb_vpl VALUES ("S213_30","011_13_30","2SA","13","30","30","ויהי המה בדרך והשמעה באה אל דוד לאמר הכה אבשלום את כל בני המלך ולא נותר מהם אחד׃ ");
INSERT INTO heb_vpl VALUES ("S213_31","011_13_31","2SA","13","31","31","ויקם המלך ויקרע את בגדיו וישכב ארצה וכל עבדיו נצבים קרעי בגדים׃ ");
INSERT INTO heb_vpl VALUES ("S213_32","011_13_32","2SA","13","32","32","ויען יונדב בן שמעה אחי דוד ויאמר אל יאמר אדני את כל הנערים בני המלך המיתו כי אמנון לבדו מת כי על פי אבשלום היתה שימה מיום ענתו את תמר אחתו׃ ");
INSERT INTO heb_vpl VALUES ("S213_33","011_13_33","2SA","13","33","33","ועתה אל ישם אדני המלך אל לבו דבר לאמר כל בני המלך מתו כי אם אמנון לבדו מת׃ ");
INSERT INTO heb_vpl VALUES ("S213_34","011_13_34","2SA","13","34","34","ויברח אבשלום וישא הנער הצפה את עינו וירא והנה עם רב הלכים מדרך אחריו מצד ההר׃ ");
INSERT INTO heb_vpl VALUES ("S213_35","011_13_35","2SA","13","35","35","ויאמר יונדב אל המלך הנה בני המלך באו כדבר עבדך כן היה׃ ");
INSERT INTO heb_vpl VALUES ("S213_36","011_13_36","2SA","13","36","36","ויהי ככלתו לדבר והנה בני המלך באו וישאו קולם ויבכו וגם המלך וכל עבדיו בכו בכי גדול מאד׃ ");
INSERT INTO heb_vpl VALUES ("S213_37","011_13_37","2SA","13","37","37","ואבשלום ברח וילך אל תלמי בן עמיחור מלך גשור ויתאבל על בנו כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("S213_38","011_13_38","2SA","13","38","38","ואבשלום ברח וילך גשור ויהי שם שלש שנים׃ ");
INSERT INTO heb_vpl VALUES ("S213_39","011_13_39","2SA","13","39","39","ותכל דוד המלך לצאת אל אבשלום כי נחם על אמנון כי מת׃ ");
INSERT INTO heb_vpl VALUES ("S214_1","011_14_1","2SA","14","1","1","וידע יואב בן צריה כי לב המלך על אבשלום׃ ");
INSERT INTO heb_vpl VALUES ("S214_2","011_14_2","2SA","14","2","2","וישלח יואב תקועה ויקח משם אשה חכמה ויאמר אליה התאבלי נא ולבשי נא בגדי אבל ואל תסוכי שמן והיית כאשה זה ימים רבים מתאבלת על מת׃ ");
INSERT INTO heb_vpl VALUES ("S214_3","011_14_3","2SA","14","3","3","ובאת אל המלך ודברת אליו כדבר הזה וישם יואב את הדברים בפיה׃ ");
INSERT INTO heb_vpl VALUES ("S214_4","011_14_4","2SA","14","4","4","ותאמר האשה התקעית אל המלך ותפל על אפיה ארצה ותשתחו ותאמר הושעה המלך׃ ");
INSERT INTO heb_vpl VALUES ("S214_5","011_14_5","2SA","14","5","5","ויאמר לה המלך מה לך ותאמר אבל אשה אלמנה אני וימת אישי׃ ");
INSERT INTO heb_vpl VALUES ("S214_6","011_14_6","2SA","14","6","6","ולשפחתך שני בנים וינצו שניהם בשדה ואין מציל ביניהם ויכו האחד את האחד וימת אתו׃ ");
INSERT INTO heb_vpl VALUES ("S214_7","011_14_7","2SA","14","7","7","והנה קמה כל המשפחה על שפחתך ויאמרו תני את מכה אחיו ונמתהו בנפש אחיו אשר הרג ונשמידה גם את היורש וכבו את גחלתי אשר נשארה לבלתי שום לאישי שם ושארית על פני האדמה׃ ");
INSERT INTO heb_vpl VALUES ("S214_8","011_14_8","2SA","14","8","8","ויאמר המלך אל האשה לכי לביתך ואני אצוה עליך׃ ");
INSERT INTO heb_vpl VALUES ("S214_9","011_14_9","2SA","14","9","9","ותאמר האשה התקועית אל המלך עלי אדני המלך העון ועל בית אבי והמלך וכסאו נקי׃ ");
INSERT INTO heb_vpl VALUES ("S214_10","011_14_10","2SA","14","10","10","ויאמר המלך המדבר אליך והבאתו אלי ולא יסיף עוד לגעת בך׃ ");
INSERT INTO heb_vpl VALUES ("S214_11","011_14_11","2SA","14","11","11","ותאמר יזכר נא המלך את יהוה אלהיך מהרבית גאל הדם לשחת ולא ישמידו את בני ויאמר חי יהוה אם יפל משערת בנך ארצה׃ ");
INSERT INTO heb_vpl VALUES ("S214_12","011_14_12","2SA","14","12","12","ותאמר האשה תדבר נא שפחתך אל אדני המלך דבר ויאמר דברי׃ ");
INSERT INTO heb_vpl VALUES ("S214_13","011_14_13","2SA","14","13","13","ותאמר האשה ולמה חשבתה כזאת על עם אלהים ומדבר המלך הדבר הזה כאשם לבלתי השיב המלך את נדחו׃ ");
INSERT INTO heb_vpl VALUES ("S214_14","011_14_14","2SA","14","14","14","כי מות נמות וכמים הנגרים ארצה אשר לא יאספו ולא ישא אלהים נפש וחשב מחשבות לבלתי ידח ממנו נדח׃ ");
INSERT INTO heb_vpl VALUES ("S214_15","011_14_15","2SA","14","15","15","ועתה אשר באתי לדבר אל המלך אדני את הדבר הזה כי יראני העם ותאמר שפחתך אדברה נא אל המלך אולי יעשה המלך את דבר אמתו׃ ");
INSERT INTO heb_vpl VALUES ("S214_16","011_14_16","2SA","14","16","16","כי ישמע המלך להציל את אמתו מכף האיש להשמיד אתי ואת בני יחד מנחלת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("S214_17","011_14_17","2SA","14","17","17","ותאמר שפחתך יהיה נא דבר אדני המלך למנוחה כי כמלאך האלהים כן אדני המלך לשמע הטוב והרע ויהוה אלהיך יהי עמך׃ ");
INSERT INTO heb_vpl VALUES ("S214_18","011_14_18","2SA","14","18","18","ויען המלך ויאמר אל האשה אל נא תכחדי ממני דבר אשר אנכי שאל אתך ותאמר האשה ידבר נא אדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S214_19","011_14_19","2SA","14","19","19","ויאמר המלך היד יואב אתך בכל זאת ותען האשה ותאמר חי נפשך אדני המלך אם אש להמין ולהשמיל מכל אשר דבר אדני המלך כי עבדך יואב הוא צוני והוא שם בפי שפחתך את כל הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("S214_20","011_14_20","2SA","14","20","20","לבעבור סבב את פני הדבר עשה עבדך יואב את הדבר הזה ואדני חכם כחכמת מלאך האלהים לדעת את כל אשר בארץ׃ ");
INSERT INTO heb_vpl VALUES ("S214_21","011_14_21","2SA","14","21","21","ויאמר המלך אל יואב הנה נא עשיתי את הדבר הזה ולך השב את הנער את אבשלום׃ ");
INSERT INTO heb_vpl VALUES ("S214_22","011_14_22","2SA","14","22","22","ויפל יואב אל פניו ארצה וישתחו ויברך את המלך ויאמר יואב היום ידע עבדך כי מצאתי חן בעיניך אדני המלך אשר עשה המלך את דבר עבדו׃ ");
INSERT INTO heb_vpl VALUES ("S214_23","011_14_23","2SA","14","23","23","ויקם יואב וילך גשורה ויבא את אבשלום ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S214_24","011_14_24","2SA","14","24","24","ויאמר המלך יסב אל ביתו ופני לא יראה ויסב אבשלום אל ביתו ופני המלך לא ראה׃ ");
INSERT INTO heb_vpl VALUES ("S214_25","011_14_25","2SA","14","25","25","וכאבשלום לא היה איש יפה בכל ישראל להלל מאד מכף רגלו ועד קדקדו לא היה בו מום׃ ");
INSERT INTO heb_vpl VALUES ("S214_26","011_14_26","2SA","14","26","26","ובגלחו את ראשו והיה מקץ ימים לימים אשר יגלח כי כבד עליו וגלחו ושקל את שער ראשו מאתים שקלים באבן המלך׃ ");
INSERT INTO heb_vpl VALUES ("S214_27","011_14_27","2SA","14","27","27","ויולדו לאבשלום שלושה בנים ובת אחת ושמה תמר היא היתה אשה יפת מראה׃ ");
INSERT INTO heb_vpl VALUES ("S214_28","011_14_28","2SA","14","28","28","וישב אבשלום בירושלם שנתים ימים ופני המלך לא ראה׃ ");
INSERT INTO heb_vpl VALUES ("S214_29","011_14_29","2SA","14","29","29","וישלח אבשלום אל יואב לשלח אתו אל המלך ולא אבה לבוא אליו וישלח עוד שנית ולא אבה לבוא׃ ");
INSERT INTO heb_vpl VALUES ("S214_30","011_14_30","2SA","14","30","30","ויאמר אל עבדיו ראו חלקת יואב אל ידי ולו שם שערים לכו והוצתיה באש ויצתו עבדי אבשלום את החלקה באש׃ ");
INSERT INTO heb_vpl VALUES ("S214_31","011_14_31","2SA","14","31","31","ויקם יואב ויבא אל אבשלום הביתה ויאמר אליו למה הציתו עבדך את החלקה אשר לי באש׃ ");
INSERT INTO heb_vpl VALUES ("S214_32","011_14_32","2SA","14","32","32","ויאמר אבשלום אל יואב הנה שלחתי אליך לאמר בא הנה ואשלחה אתך אל המלך לאמר למה באתי מגשור טוב לי עד אני שם ועתה אראה פני המלך ואם יש בי עון והמתני׃ ");
INSERT INTO heb_vpl VALUES ("S214_33","011_14_33","2SA","14","33","33","ויבא יואב אל המלך ויגד לו ויקרא אל אבשלום ויבא אל המלך וישתחו לו על אפיו ארצה לפני המלך וישק המלך לאבשלום׃ ");
INSERT INTO heb_vpl VALUES ("S215_1","011_15_1","2SA","15","1","1","ויהי מאחרי כן ויעש לו אבשלום מרכבה וססים וחמשים איש רצים לפניו׃ ");
INSERT INTO heb_vpl VALUES ("S215_2","011_15_2","2SA","15","2","2","והשכים אבשלום ועמד על יד דרך השער ויהי כל האיש אשר יהיה לו ריב לבוא אל המלך למשפט ויקרא אבשלום אליו ויאמר אי מזה עיר אתה ויאמר מאחד שבטי ישראל עבדך׃ ");
INSERT INTO heb_vpl VALUES ("S215_3","011_15_3","2SA","15","3","3","ויאמר אליו אבשלום ראה דברך טובים ונכחים ושמע אין לך מאת המלך׃ ");
INSERT INTO heb_vpl VALUES ("S215_4","011_15_4","2SA","15","4","4","ויאמר אבשלום מי ישמני שפט בארץ ועלי יבוא כל איש אשר יהיה לו ריב ומשפט והצדקתיו׃ ");
INSERT INTO heb_vpl VALUES ("S215_5","011_15_5","2SA","15","5","5","והיה בקרב איש להשתחות לו ושלח את ידו והחזיק לו ונשק לו׃ ");
INSERT INTO heb_vpl VALUES ("S215_6","011_15_6","2SA","15","6","6","ויעש אבשלום כדבר הזה לכל ישראל אשר יבאו למשפט אל המלך ויגנב אבשלום את לב אנשי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S215_7","011_15_7","2SA","15","7","7","ויהי מקץ ארבעים שנה ויאמר אבשלום אל המלך אלכה נא ואשלם את נדרי אשר נדרתי ליהוה בחברון׃ ");
INSERT INTO heb_vpl VALUES ("S215_8","011_15_8","2SA","15","8","8","כי נדר נדר עבדך בשבתי בגשור בארם לאמר אם ישיב ישיבני יהוה ירושלם ועבדתי את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S215_9","011_15_9","2SA","15","9","9","ויאמר לו המלך לך בשלום ויקם וילך חברונה׃ ");
INSERT INTO heb_vpl VALUES ("S215_10","011_15_10","2SA","15","10","10","וישלח אבשלום מרגלים בכל שבטי ישראל לאמר כשמעכם את קול השפר ואמרתם מלך אבשלום בחברון׃ ");
INSERT INTO heb_vpl VALUES ("S215_11","011_15_11","2SA","15","11","11","ואת אבשלום הלכו מאתים איש מירושלם קראים והלכים לתמם ולא ידעו כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("S215_12","011_15_12","2SA","15","12","12","וישלח אבשלום את אחיתפל הגילני יועץ דוד מעירו מגלה בזבחו את הזבחים ויהי הקשר אמץ והעם הולך ורב את אבשלום׃ ");
INSERT INTO heb_vpl VALUES ("S215_13","011_15_13","2SA","15","13","13","ויבא המגיד אל דוד לאמר היה לב איש ישראל אחרי אבשלום׃ ");
INSERT INTO heb_vpl VALUES ("S215_14","011_15_14","2SA","15","14","14","ויאמר דוד לכל עבדיו אשר אתו בירושלם קומו ונברחה כי לא תהיה לנו פליטה מפני אבשלום מהרו ללכת פן ימהר והשגנו והדיח עלינו את הרעה והכה העיר לפי חרב׃ ");
INSERT INTO heb_vpl VALUES ("S215_15","011_15_15","2SA","15","15","15","ויאמרו עבדי המלך אל המלך ככל אשר יבחר אדני המלך הנה עבדיך׃ ");
INSERT INTO heb_vpl VALUES ("S215_16","011_15_16","2SA","15","16","16","ויצא המלך וכל ביתו ברגליו ויעזב המלך את עשר נשים פלגשים לשמר הבית׃ ");
INSERT INTO heb_vpl VALUES ("S215_17","011_15_17","2SA","15","17","17","ויצא המלך וכל העם ברגליו ויעמדו בית המרחק׃ ");
INSERT INTO heb_vpl VALUES ("S215_18","011_15_18","2SA","15","18","18","וכל עבדיו עברים על ידו וכל הכרתי וכל הפלתי וכל הגתים שש מאות איש אשר באו ברגלו מגת עברים על פני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S215_19","011_15_19","2SA","15","19","19","ויאמר המלך אל אתי הגתי למה תלך גם אתה אתנו שוב ושב עם המלך כי נכרי אתה וגם גלה אתה למקומך׃ ");
INSERT INTO heb_vpl VALUES ("S215_20","011_15_20","2SA","15","20","20","תמול בואך והיום אנועך עמנו ללכת ואני הולך על אשר אני הולך שוב והשב את אחיך עמך חסד ואמת׃ ");
INSERT INTO heb_vpl VALUES ("S215_21","011_15_21","2SA","15","21","21","ויען אתי את המלך ויאמר חי יהוה וחי אדני המלך כי אם במקום אשר יהיה שם אדני המלך אם למות אם לחיים כי שם יהיה עבדך׃ ");
INSERT INTO heb_vpl VALUES ("S215_22","011_15_22","2SA","15","22","22","ויאמר דוד אל אתי לך ועבר ויעבר אתי הגתי וכל אנשיו וכל הטף אשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("S215_23","011_15_23","2SA","15","23","23","וכל הארץ בוכים קול גדול וכל העם עברים והמלך עבר בנחל קדרון וכל העם עברים על פני דרך את המדבר׃ ");
INSERT INTO heb_vpl VALUES ("S215_24","011_15_24","2SA","15","24","24","והנה גם צדוק וכל הלוים אתו נשאים את ארון ברית האלהים ויצקו את ארון האלהים ויעל אביתר עד תם כל העם לעבור מן העיר׃ ");
INSERT INTO heb_vpl VALUES ("S215_25","011_15_25","2SA","15","25","25","ויאמר המלך לצדוק השב את ארון האלהים העיר אם אמצא חן בעיני יהוה והשבני והראני אתו ואת נוהו׃ ");
INSERT INTO heb_vpl VALUES ("S215_26","011_15_26","2SA","15","26","26","ואם כה יאמר לא חפצתי בך הנני יעשה לי כאשר טוב בעיניו׃ ");
INSERT INTO heb_vpl VALUES ("S215_27","011_15_27","2SA","15","27","27","ויאמר המלך אל צדוק הכהן הרואה אתה שבה העיר בשלום ואחימעץ בנך ויהונתן בן אביתר שני בניכם אתכם׃ ");
INSERT INTO heb_vpl VALUES ("S215_28","011_15_28","2SA","15","28","28","ראו אנכי מתמהמה בעברות המדבר עד בוא דבר מעמכם להגיד לי׃ ");
INSERT INTO heb_vpl VALUES ("S215_29","011_15_29","2SA","15","29","29","וישב צדוק ואביתר את ארון האלהים ירושלם וישבו שם׃ ");
INSERT INTO heb_vpl VALUES ("S215_30","011_15_30","2SA","15","30","30","ודוד עלה במעלה הזיתים עלה ובוכה וראש לו חפוי והוא הלך יחף וכל העם אשר אתו חפו איש ראשו ועלו עלה ובכה׃ ");
INSERT INTO heb_vpl VALUES ("S215_31","011_15_31","2SA","15","31","31","ודוד הגיד לאמר אחיתפל בקשרים עם אבשלום ויאמר דוד סכל נא את עצת אחיתפל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S215_32","011_15_32","2SA","15","32","32","ויהי דוד בא עד הראש אשר ישתחוה שם לאלהים והנה לקראתו חושי הארכי קרוע כתנתו ואדמה על ראשו׃ ");
INSERT INTO heb_vpl VALUES ("S215_33","011_15_33","2SA","15","33","33","ויאמר לו דוד אם עברת אתי והית עלי למשא׃ ");
INSERT INTO heb_vpl VALUES ("S215_34","011_15_34","2SA","15","34","34","ואם העיר תשוב ואמרת לאבשלום עבדך אני המלך אהיה עבד אביך ואני מאז ועתה ואני עבדך והפרתה לי את עצת אחיתפל׃ ");
INSERT INTO heb_vpl VALUES ("S215_35","011_15_35","2SA","15","35","35","והלוא עמך שם צדוק ואביתר הכהנים והיה כל הדבר אשר תשמע מבית המלך תגיד לצדוק ולאביתר הכהנים׃ ");
INSERT INTO heb_vpl VALUES ("S215_36","011_15_36","2SA","15","36","36","הנה שם עמם שני בניהם אחימעץ לצדוק ויהונתן לאביתר ושלחתם בידם אלי כל דבר אשר תשמעו׃ ");
INSERT INTO heb_vpl VALUES ("S215_37","011_15_37","2SA","15","37","37","ויבא חושי רעה דוד העיר ואבשלם יבא ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S216_1","011_16_1","2SA","16","1","1","ודוד עבר מעט מהראש והנה ציבא נער מפי בשת לקראתו וצמד חמרים חבשים ועליהם מאתים לחם ומאה צמוקים ומאה קיץ ונבל יין׃ ");
INSERT INTO heb_vpl VALUES ("S216_2","011_16_2","2SA","16","2","2","ויאמר המלך אל ציבא מה אלה לך ויאמר ציבא החמורים לבית המלך לרכב ולהלחם והקיץ לאכול הנערים והיין לשתות היעף במדבר׃ ");
INSERT INTO heb_vpl VALUES ("S216_3","011_16_3","2SA","16","3","3","ויאמר המלך ואיה בן אדניך ויאמר ציבא אל המלך הנה יושב בירושלם כי אמר היום ישיבו לי בית ישראל את ממלכות אבי׃ ");
INSERT INTO heb_vpl VALUES ("S216_4","011_16_4","2SA","16","4","4","ויאמר המלך לצבא הנה לך כל אשר למפי בשת ויאמר ציבא השתחויתי אמצא חן בעיניך אדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S216_5","011_16_5","2SA","16","5","5","ובא המלך דוד עד בחורים והנה משם איש יוצא ממשפחת בית שאול ושמו שמעי בן גרא יצא יצוא ומקלל׃ ");
INSERT INTO heb_vpl VALUES ("S216_6","011_16_6","2SA","16","6","6","ויסקל באבנים את דוד ואת כל עבדי המלך דוד וכל העם וכל הגברים מימינו ומשמאלו׃ ");
INSERT INTO heb_vpl VALUES ("S216_7","011_16_7","2SA","16","7","7","וכה אמר שמעי בקללו צא צא איש הדמים ואיש הבליעל׃ ");
INSERT INTO heb_vpl VALUES ("S216_8","011_16_8","2SA","16","8","8","השיב עליך יהוה כל דמי בית שאול אשר מלכת תחתו ויתן יהוה את המלוכה ביד אבשלום בנך והנך ברעתך כי איש דמים אתה׃ ");
INSERT INTO heb_vpl VALUES ("S216_9","011_16_9","2SA","16","9","9","ויאמר אבישי בן צרויה אל המלך למה יקלל הכלב המת הזה את אדני המלך אעברה נא ואסירה את ראשו׃ ");
INSERT INTO heb_vpl VALUES ("S216_10","011_16_10","2SA","16","10","10","ויאמר המלך מה לי ולכם בני צריה כי יקלל וכי יהוה אמר לו קלל את דוד ומי יאמר מדוע עשיתה כן׃ ");
INSERT INTO heb_vpl VALUES ("S216_11","011_16_11","2SA","16","11","11","ויאמר דוד אל אבישי ואל כל עבדיו הנה בני אשר יצא ממעי מבקש את נפשי ואף כי עתה בן הימיני הנחו לו ויקלל כי אמר לו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S216_12","011_16_12","2SA","16","12","12","אולי יראה יהוה בעוני והשיב יהוה לי טובה תחת קללתו היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S216_13","011_16_13","2SA","16","13","13","וילך דוד ואנשיו בדרך ושמעי הלך בצלע ההר לעמתו הלוך ויקלל ויסקל באבנים לעמתו ועפר בעפר׃ ");
INSERT INTO heb_vpl VALUES ("S216_14","011_16_14","2SA","16","14","14","ויבא המלך וכל העם אשר אתו עיפים וינפש שם׃ ");
INSERT INTO heb_vpl VALUES ("S216_15","011_16_15","2SA","16","15","15","ואבשלום וכל העם איש ישראל באו ירושלם ואחיתפל אתו׃ ");
INSERT INTO heb_vpl VALUES ("S216_16","011_16_16","2SA","16","16","16","ויהי כאשר בא חושי הארכי רעה דוד אל אבשלום ויאמר חושי אל אבשלם יחי המלך יחי המלך׃ ");
INSERT INTO heb_vpl VALUES ("S216_17","011_16_17","2SA","16","17","17","ויאמר אבשלום אל חושי זה חסדך את רעך למה לא הלכת את רעך׃ ");
INSERT INTO heb_vpl VALUES ("S216_18","011_16_18","2SA","16","18","18","ויאמר חושי אל אבשלם לא כי אשר בחר יהוה והעם הזה וכל איש ישראל לא אהיה ואתו אשב׃ ");
INSERT INTO heb_vpl VALUES ("S216_19","011_16_19","2SA","16","19","19","והשנית למי אני אעבד הלוא לפני בנו כאשר עבדתי לפני אביך כן אהיה לפניך׃ ");
INSERT INTO heb_vpl VALUES ("S216_20","011_16_20","2SA","16","20","20","ויאמר אבשלום אל אחיתפל הבו לכם עצה מה נעשה׃ ");
INSERT INTO heb_vpl VALUES ("S216_21","011_16_21","2SA","16","21","21","ויאמר אחיתפל אל אבשלם בוא אל פלגשי אביך אשר הניח לשמור הבית ושמע כל ישראל כי נבאשת את אביך וחזקו ידי כל אשר אתך׃ ");
INSERT INTO heb_vpl VALUES ("S216_22","011_16_22","2SA","16","22","22","ויטו לאבשלום האהל על הגג ויבא אבשלום אל פלגשי אביו לעיני כל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S216_23","011_16_23","2SA","16","23","23","ועצת אחיתפל אשר יעץ בימים ההם כאשר ישאל בדבר האלהים כן כל עצת אחיתפל גם לדוד גם לאבשלם׃ ");
INSERT INTO heb_vpl VALUES ("S217_1","011_17_1","2SA","17","1","1","ויאמר אחיתפל אל אבשלם אבחרה נא שנים עשר אלף איש ואקומה וארדפה אחרי דוד הלילה׃ ");
INSERT INTO heb_vpl VALUES ("S217_2","011_17_2","2SA","17","2","2","ואבוא עליו והוא יגע ורפה ידים והחרדתי אתו ונס כל העם אשר אתו והכיתי את המלך לבדו׃ ");
INSERT INTO heb_vpl VALUES ("S217_3","011_17_3","2SA","17","3","3","ואשיבה כל העם אליך כשוב הכל האיש אשר אתה מבקש כל העם יהיה שלום׃ ");
INSERT INTO heb_vpl VALUES ("S217_4","011_17_4","2SA","17","4","4","ויישר הדבר בעיני אבשלם ובעיני כל זקני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S217_5","011_17_5","2SA","17","5","5","ויאמר אבשלום קרא נא גם לחושי הארכי ונשמעה מה בפיו גם הוא׃ ");
INSERT INTO heb_vpl VALUES ("S217_6","011_17_6","2SA","17","6","6","ויבא חושי אל אבשלום ויאמר אבשלום אליו לאמר כדבר הזה דבר אחיתפל הנעשה את דברו אם אין אתה דבר׃ ");
INSERT INTO heb_vpl VALUES ("S217_7","011_17_7","2SA","17","7","7","ויאמר חושי אל אבשלום לא טובה העצה אשר יעץ אחיתפל בפעם הזאת׃ ");
INSERT INTO heb_vpl VALUES ("S217_8","011_17_8","2SA","17","8","8","ויאמר חושי אתה ידעת את אביך ואת אנשיו כי גברים המה ומרי נפש המה כדב שכול בשדה ואביך איש מלחמה ולא ילין את העם׃ ");
INSERT INTO heb_vpl VALUES ("S217_9","011_17_9","2SA","17","9","9","הנה עתה הוא נחבא באחת הפחתים או באחד המקומת והיה כנפל בהם בתחלה ושמע השמע ואמר היתה מגפה בעם אשר אחרי אבשלם׃ ");
INSERT INTO heb_vpl VALUES ("S217_10","011_17_10","2SA","17","10","10","והוא גם בן חיל אשר לבו כלב האריה המס ימס כי ידע כל ישראל כי גבור אביך ובני חיל אשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("S217_11","011_17_11","2SA","17","11","11","כי יעצתי האסף יאסף עליך כל ישראל מדן ועד באר שבע כחול אשר על הים לרב ופניך הלכים בקרב׃ ");
INSERT INTO heb_vpl VALUES ("S217_12","011_17_12","2SA","17","12","12","ובאנו אליו באחת המקומת אשר נמצא שם ונחנו עליו כאשר יפל הטל על האדמה ולא נותר בו ובכל האנשים אשר אתו גם אחד׃ ");
INSERT INTO heb_vpl VALUES ("S217_13","011_17_13","2SA","17","13","13","ואם אל עיר יאסף והשיאו כל ישראל אל העיר ההיא חבלים וסחבנו אתו עד הנחל עד אשר לא נמצא שם גם צרור׃ ");
INSERT INTO heb_vpl VALUES ("S217_14","011_17_14","2SA","17","14","14","ויאמר אבשלום וכל איש ישראל טובה עצת חושי הארכי מעצת אחיתפל ויהוה צוה להפר את עצת אחיתפל הטובה לבעבור הביא יהוה אל אבשלום את הרעה׃ ");
INSERT INTO heb_vpl VALUES ("S217_15","011_17_15","2SA","17","15","15","ויאמר חושי אל צדוק ואל אביתר הכהנים כזאת וכזאת יעץ אחיתפל את אבשלם ואת זקני ישראל וכזאת וכזאת יעצתי אני׃ ");
INSERT INTO heb_vpl VALUES ("S217_16","011_17_16","2SA","17","16","16","ועתה שלחו מהרה והגידו לדוד לאמר אל תלן הלילה בערבות המדבר וגם עבור תעבור פן יבלע למלך ולכל העם אשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("S217_17","011_17_17","2SA","17","17","17","ויהונתן ואחימעץ עמדים בעין רגל והלכה השפחה והגידה להם והם ילכו והגידו למלך דוד כי לא יוכלו להראות לבוא העירה׃ ");
INSERT INTO heb_vpl VALUES ("S217_18","011_17_18","2SA","17","18","18","וירא אתם נער ויגד לאבשלם וילכו שניהם מהרה ויבאו אל בית איש בבחורים ולו באר בחצרו וירדו שם׃ ");
INSERT INTO heb_vpl VALUES ("S217_19","011_17_19","2SA","17","19","19","ותקח האשה ותפרש את המסך על פני הבאר ותשטח עליו הרפות ולא נודע דבר׃ ");
INSERT INTO heb_vpl VALUES ("S217_20","011_17_20","2SA","17","20","20","ויבאו עבדי אבשלום אל האשה הביתה ויאמרו איה אחימעץ ויהונתן ותאמר להם האשה עברו מיכל המים ויבקשו ולא מצאו וישבו ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S217_21","011_17_21","2SA","17","21","21","ויהי אחרי לכתם ויעלו מהבאר וילכו ויגדו למלך דוד ויאמרו אל דוד קומו ועברו מהרה את המים כי ככה יעץ עליכם אחיתפל׃ ");
INSERT INTO heb_vpl VALUES ("S217_22","011_17_22","2SA","17","22","22","ויקם דוד וכל העם אשר אתו ויעברו את הירדן עד אור הבקר עד אחד לא נעדר אשר לא עבר את הירדן׃ ");
INSERT INTO heb_vpl VALUES ("S217_23","011_17_23","2SA","17","23","23","ואחיתפל ראה כי לא נעשתה עצתו ויחבש את החמור ויקם וילך אל ביתו אל עירו ויצו אל ביתו ויחנק וימת ויקבר בקבר אביו׃ ");
INSERT INTO heb_vpl VALUES ("S217_24","011_17_24","2SA","17","24","24","ודוד בא מחנימה ואבשלם עבר את הירדן הוא וכל איש ישראל עמו׃ ");
INSERT INTO heb_vpl VALUES ("S217_25","011_17_25","2SA","17","25","25","ואת עמשא שם אבשלם תחת יואב על הצבא ועמשא בן איש ושמו יתרא הישראלי אשר בא אל אביגל בת נחש אחות צרויה אם יואב׃ ");
INSERT INTO heb_vpl VALUES ("S217_26","011_17_26","2SA","17","26","26","ויחן ישראל ואבשלם ארץ הגלעד׃ ");
INSERT INTO heb_vpl VALUES ("S217_27","011_17_27","2SA","17","27","27","ויהי כבוא דוד מחנימה ושבי בן נחש מרבת בני עמון ומכיר בן עמיאל מלא דבר וברזלי הגלעדי מרגלים׃ ");
INSERT INTO heb_vpl VALUES ("S217_28","011_17_28","2SA","17","28","28","משכב וספות וכלי יוצר וחטים ושערים וקמח וקלי ופול ועדשים וקלי׃ ");
INSERT INTO heb_vpl VALUES ("S217_29","011_17_29","2SA","17","29","29","ודבש וחמאה וצאן ושפות בקר הגישו לדוד ולעם אשר אתו לאכול כי אמרו העם רעב ועיף וצמא במדבר׃ ");
INSERT INTO heb_vpl VALUES ("S218_1","011_18_1","2SA","18","1","1","ויפקד דוד את העם אשר אתו וישם עליהם שרי אלפים ושרי מאות׃ ");
INSERT INTO heb_vpl VALUES ("S218_2","011_18_2","2SA","18","2","2","וישלח דוד את העם השלשית ביד יואב והשלשית ביד אבישי בן צרויה אחי יואב והשלשת ביד אתי הגתי ויאמר המלך אל העם יצא אצא גם אני עמכם׃ ");
INSERT INTO heb_vpl VALUES ("S218_3","011_18_3","2SA","18","3","3","ויאמר העם לא תצא כי אם נס ננוס לא ישימו אלינו לב ואם ימתו חצינו לא ישימו אלינו לב כי עתה כמנו עשרה אלפים ועתה טוב כי תהיה לנו מעיר לעזיר׃ ");
INSERT INTO heb_vpl VALUES ("S218_4","011_18_4","2SA","18","4","4","ויאמר אליהם המלך אשר ייטב בעיניכם אעשה ויעמד המלך אל יד השער וכל העם יצאו למאות ולאלפים׃ ");
INSERT INTO heb_vpl VALUES ("S218_5","011_18_5","2SA","18","5","5","ויצו המלך את יואב ואת אבישי ואת אתי לאמר לאט לי לנער לאבשלום וכל העם שמעו בצות המלך את כל השרים על דבר אבשלום׃ ");
INSERT INTO heb_vpl VALUES ("S218_6","011_18_6","2SA","18","6","6","ויצא העם השדה לקראת ישראל ותהי המלחמה ביער אפרים׃ ");
INSERT INTO heb_vpl VALUES ("S218_7","011_18_7","2SA","18","7","7","וינגפו שם עם ישראל לפני עבדי דוד ותהי שם המגפה גדולה ביום ההוא עשרים אלף׃ ");
INSERT INTO heb_vpl VALUES ("S218_8","011_18_8","2SA","18","8","8","ותהי שם המלחמה נפצות על פני כל הארץ וירב היער לאכל בעם מאשר אכלה החרב ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("S218_9","011_18_9","2SA","18","9","9","ויקרא אבשלום לפני עבדי דוד ואבשלום רכב על הפרד ויבא הפרד תחת שובך האלה הגדולה ויחזק ראשו באלה ויתן בין השמים ובין הארץ והפרד אשר תחתיו עבר׃ ");
INSERT INTO heb_vpl VALUES ("S218_10","011_18_10","2SA","18","10","10","וירא איש אחד ויגד ליואב ויאמר הנה ראיתי את אבשלם תלוי באלה׃ ");
INSERT INTO heb_vpl VALUES ("S218_11","011_18_11","2SA","18","11","11","ויאמר יואב לאיש המגיד לו והנה ראית ומדוע לא הכיתו שם ארצה ועלי לתת לך עשרה כסף וחגרה אחת׃ ");
INSERT INTO heb_vpl VALUES ("S218_12","011_18_12","2SA","18","12","12","ויאמר האיש אל יואב ולא אנכי שקל על כפי אלף כסף לא אשלח ידי אל בן המלך כי באזנינו צוה המלך אתך ואת אבישי ואת אתי לאמר שמרו מי בנער באבשלום׃ ");
INSERT INTO heb_vpl VALUES ("S218_13","011_18_13","2SA","18","13","13","או עשיתי בנפשו שקר וכל דבר לא יכחד מן המלך ואתה תתיצב מנגד׃ ");
INSERT INTO heb_vpl VALUES ("S218_14","011_18_14","2SA","18","14","14","ויאמר יואב לא כן אחילה לפניך ויקח שלשה שבטים בכפו ויתקעם בלב אבשלום עודנו חי בלב האלה׃ ");
INSERT INTO heb_vpl VALUES ("S218_15","011_18_15","2SA","18","15","15","ויסבו עשרה נערים נשאי כלי יואב ויכו את אבשלום וימיתהו׃ ");
INSERT INTO heb_vpl VALUES ("S218_16","011_18_16","2SA","18","16","16","ויתקע יואב בשפר וישב העם מרדף אחרי ישראל כי חשך יואב את העם׃ ");
INSERT INTO heb_vpl VALUES ("S218_17","011_18_17","2SA","18","17","17","ויקחו את אבשלום וישליכו אתו ביער אל הפחת הגדול ויצבו עליו גל אבנים גדול מאד וכל ישראל נסו איש לאהלו׃ ");
INSERT INTO heb_vpl VALUES ("S218_18","011_18_18","2SA","18","18","18","ואבשלם לקח ויצב לו בחיו את מצבת אשר בעמק המלך כי אמר אין לי בן בעבור הזכיר שמי ויקרא למצבת על שמו ויקרא לה יד אבשלם עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("S218_19","011_18_19","2SA","18","19","19","ואחימעץ בן צדוק אמר ארוצה נא ואבשרה את המלך כי שפטו יהוה מיד איביו׃ ");
INSERT INTO heb_vpl VALUES ("S218_20","011_18_20","2SA","18","20","20","ויאמר לו יואב לא איש בשרה אתה היום הזה ובשרת ביום אחר והיום הזה לא תבשר כי על בן המלך מת׃ ");
INSERT INTO heb_vpl VALUES ("S218_21","011_18_21","2SA","18","21","21","ויאמר יואב לכושי לך הגד למלך אשר ראיתה וישתחו כושי ליואב וירץ׃ ");
INSERT INTO heb_vpl VALUES ("S218_22","011_18_22","2SA","18","22","22","ויסף עוד אחימעץ בן צדוק ויאמר אל יואב ויהי מה ארצה נא גם אני אחרי הכושי ויאמר יואב למה זה אתה רץ בני ולכה אין בשורה מצאת׃ ");
INSERT INTO heb_vpl VALUES ("S218_23","011_18_23","2SA","18","23","23","ויהי מה ארוץ ויאמר לו רוץ וירץ אחימעץ דרך הככר ויעבר את הכושי׃ ");
INSERT INTO heb_vpl VALUES ("S218_24","011_18_24","2SA","18","24","24","ודוד יושב בין שני השערים וילך הצפה אל גג השער אל החומה וישא את עיניו וירא והנה איש רץ לבדו׃ ");
INSERT INTO heb_vpl VALUES ("S218_25","011_18_25","2SA","18","25","25","ויקרא הצפה ויגד למלך ויאמר המלך אם לבדו בשורה בפיו וילך הלוך וקרב׃ ");
INSERT INTO heb_vpl VALUES ("S218_26","011_18_26","2SA","18","26","26","וירא הצפה איש אחר רץ ויקרא הצפה אל השער ויאמר הנה איש רץ לבדו ויאמר המלך גם זה מבשר׃ ");
INSERT INTO heb_vpl VALUES ("S218_27","011_18_27","2SA","18","27","27","ויאמר הצפה אני ראה את מרוצת הראשון כמרצת אחימעץ בן צדוק ויאמר המלך איש טוב זה ואל בשורה טובה יבוא׃ ");
INSERT INTO heb_vpl VALUES ("S218_28","011_18_28","2SA","18","28","28","ויקרא אחימעץ ויאמר אל המלך שלום וישתחו למלך לאפיו ארצה ויאמר ברוך יהוה אלהיך אשר סגר את האנשים אשר נשאו את ידם באדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S218_29","011_18_29","2SA","18","29","29","ויאמר המלך שלום לנער לאבשלום ויאמר אחימעץ ראיתי ההמון הגדול לשלח את עבד המלך יואב ואת עבדך ולא ידעתי מה׃ ");
INSERT INTO heb_vpl VALUES ("S218_30","011_18_30","2SA","18","30","30","ויאמר המלך סב התיצב כה ויסב ויעמד׃ ");
INSERT INTO heb_vpl VALUES ("S218_31","011_18_31","2SA","18","31","31","והנה הכושי בא ויאמר הכושי יתבשר אדני המלך כי שפטך יהוה היום מיד כל הקמים עליך׃ ");
INSERT INTO heb_vpl VALUES ("S218_32","011_18_32","2SA","18","32","32","ויאמר המלך אל הכושי השלום לנער לאבשלום ויאמר הכושי יהיו כנער איבי אדני המלך וכל אשר קמו עליך לרעה׃ ");
INSERT INTO heb_vpl VALUES ("S218_33","011_18_33","2SA","18","33","33","וירגז המלך ויעל על עלית השער ויבך וכה אמר בלכתו בני אבשלום בני בני אבשלום מי יתן מותי אני תחתיך אבשלום בני בני׃ ");
INSERT INTO heb_vpl VALUES ("S219_1","011_19_1","2SA","19","1","1","ויגד ליואב הנה המלך בכה ויתאבל על אבשלם׃ ");
INSERT INTO heb_vpl VALUES ("S219_2","011_19_2","2SA","19","2","2","ותהי התשעה ביום ההוא לאבל לכל העם כי שמע העם ביום ההוא לאמר נעצב המלך על בנו׃ ");
INSERT INTO heb_vpl VALUES ("S219_3","011_19_3","2SA","19","3","3","ויתגנב העם ביום ההוא לבוא העיר כאשר יתגנב העם הנכלמים בנוסם במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("S219_4","011_19_4","2SA","19","4","4","והמלך לאט את פניו ויזעק המלך קול גדול בני אבשלום אבשלום בני בני׃ ");
INSERT INTO heb_vpl VALUES ("S219_5","011_19_5","2SA","19","5","5","ויבא יואב אל המלך הבית ויאמר הבשת היום את פני כל עבדיך הממלטים את נפשך היום ואת נפש בניך ובנתיך ונפש נשיך ונפש פלגשיך׃ ");
INSERT INTO heb_vpl VALUES ("S219_6","011_19_6","2SA","19","6","6","לאהבה את שנאיך ולשנא את אהביך כי הגדת היום כי אין לך שרים ועבדים כי ידעתי היום כי לא אבשלום חי וכלנו היום מתים כי אז ישר בעיניך׃ ");
INSERT INTO heb_vpl VALUES ("S219_7","011_19_7","2SA","19","7","7","ועתה קום צא ודבר על לב עבדיך כי ביהוה נשבעתי כי אינך יוצא אם ילין איש אתך הלילה ורעה לך זאת מכל הרעה אשר באה עליך מנעריך עד עתה׃ ");
INSERT INTO heb_vpl VALUES ("S219_8","011_19_8","2SA","19","8","8","ויקם המלך וישב בשער ולכל העם הגידו לאמר הנה המלך יושב בשער ויבא כל העם לפני המלך וישראל נס איש לאהליו׃ ");
INSERT INTO heb_vpl VALUES ("S219_9","011_19_9","2SA","19","9","9","ויהי כל העם נדון בכל שבטי ישראל לאמר המלך הצילנו מכף איבינו והוא מלטנו מכף פלשתים ועתה ברח מן הארץ מעל אבשלום׃ ");
INSERT INTO heb_vpl VALUES ("S219_10","011_19_10","2SA","19","10","10","ואבשלום אשר משחנו עלינו מת במלחמה ועתה למה אתם מחרשים להשיב את המלך׃ ");
INSERT INTO heb_vpl VALUES ("S219_11","011_19_11","2SA","19","11","11","והמלך דוד שלח אל צדוק ואל אביתר הכהנים לאמר דברו אל זקני יהודה לאמר למה תהיו אחרנים להשיב את המלך אל ביתו ודבר כל ישראל בא אל המלך אל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("S219_12","011_19_12","2SA","19","12","12","אחי אתם עצמי ובשרי אתם ולמה תהיו אחרנים להשיב את המלך׃ ");
INSERT INTO heb_vpl VALUES ("S219_13","011_19_13","2SA","19","13","13","ולעמשא תמרו הלוא עצמי ובשרי אתה כה יעשה לי אלהים וכה יוסיף אם לא שר צבא תהיה לפני כל הימים תחת יואב׃ ");
INSERT INTO heb_vpl VALUES ("S219_14","011_19_14","2SA","19","14","14","ויט את לבב כל איש יהודה כאיש אחד וישלחו אל המלך שוב אתה וכל עבדיך׃ ");
INSERT INTO heb_vpl VALUES ("S219_15","011_19_15","2SA","19","15","15","וישב המלך ויבא עד הירדן ויהודה בא הגלגלה ללכת לקראת המלך להעביר את המלך את הירדן׃ ");
INSERT INTO heb_vpl VALUES ("S219_16","011_19_16","2SA","19","16","16","וימהר שמעי בן גרא בן הימיני אשר מבחורים וירד עם איש יהודה לקראת המלך דוד׃ ");
INSERT INTO heb_vpl VALUES ("S219_17","011_19_17","2SA","19","17","17","ואלף איש עמו מבנימן וציבא נער בית שאול וחמשת עשר בניו ועשרים עבדיו אתו וצלחו הירדן לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S219_18","011_19_18","2SA","19","18","18","ועברה העברה לעביר את בית המלך ולעשות הטוב בעינו ושמעי בן גרא נפל לפני המלך בעברו בירדן׃ ");
INSERT INTO heb_vpl VALUES ("S219_19","011_19_19","2SA","19","19","19","ויאמר אל המלך אל יחשב לי אדני עון ואל תזכר את אשר העוה עבדך ביום אשר יצא אדני המלך מירושלם לשום המלך אל לבו׃ ");
INSERT INTO heb_vpl VALUES ("S219_20","011_19_20","2SA","19","20","20","כי ידע עבדך כי אני חטאתי והנה באתי היום ראשון לכל בית יוסף לרדת לקראת אדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S219_21","011_19_21","2SA","19","21","21","ויען אבישי בן צרויה ויאמר התחת זאת לא יומת שמעי כי קלל את משיח יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S219_22","011_19_22","2SA","19","22","22","ויאמר דוד מה לי ולכם בני צרויה כי תהיו לי היום לשטן היום יומת איש בישראל כי הלוא ידעתי כי היום אני מלך על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S219_23","011_19_23","2SA","19","23","23","ויאמר המלך אל שמעי לא תמות וישבע לו המלך׃ ");
INSERT INTO heb_vpl VALUES ("S219_24","011_19_24","2SA","19","24","24","ומפבשת בן שאול ירד לקראת המלך ולא עשה רגליו ולא עשה שפמו ואת בגדיו לא כבס למן היום לכת המלך עד היום אשר בא בשלום׃ ");
INSERT INTO heb_vpl VALUES ("S219_25","011_19_25","2SA","19","25","25","ויהי כי בא ירושלם לקראת המלך ויאמר לו המלך למה לא הלכת עמי מפיבשת׃ ");
INSERT INTO heb_vpl VALUES ("S219_26","011_19_26","2SA","19","26","26","ויאמר אדני המלך עבדי רמני כי אמר עבדך אחבשה לי החמור וארכב עליה ואלך את המלך כי פסח עבדך׃ ");
INSERT INTO heb_vpl VALUES ("S219_27","011_19_27","2SA","19","27","27","וירגל בעבדך אל אדני המלך ואדני המלך כמלאך האלהים ועשה הטוב בעיניך׃ ");
INSERT INTO heb_vpl VALUES ("S219_28","011_19_28","2SA","19","28","28","כי לא היה כל בית אבי כי אם אנשי מות לאדני המלך ותשת את עבדך באכלי שלחנך ומה יש לי עוד צדקה ולזעק עוד אל המלך׃ ");
INSERT INTO heb_vpl VALUES ("S219_29","011_19_29","2SA","19","29","29","ויאמר לו המלך למה תדבר עוד דבריך אמרתי אתה וציבא תחלקו את השדה׃ ");
INSERT INTO heb_vpl VALUES ("S219_30","011_19_30","2SA","19","30","30","ויאמר מפיבשת אל המלך גם את הכל יקח אחרי אשר בא אדני המלך בשלום אל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("S219_31","011_19_31","2SA","19","31","31","וברזלי הגלעדי ירד מרגלים ויעבר את המלך הירדן לשלחו את בירדן׃ ");
INSERT INTO heb_vpl VALUES ("S219_32","011_19_32","2SA","19","32","32","וברזלי זקן מאד בן שמנים שנה והוא כלכל את המלך בשיבתו במחנים כי איש גדול הוא מאד׃ ");
INSERT INTO heb_vpl VALUES ("S219_33","011_19_33","2SA","19","33","33","ויאמר המלך אל ברזלי אתה עבר אתי וכלכלתי אתך עמדי בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S219_34","011_19_34","2SA","19","34","34","ויאמר ברזלי אל המלך כמה ימי שני חיי כי אעלה את המלך ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S219_35","011_19_35","2SA","19","35","35","בן שמנים שנה אנכי היום האדע בין טוב לרע אם יטעם עבדך את אשר אכל ואת אשר אשתה אם אשמע עוד בקול שרים ושרות ולמה יהיה עבדך עוד למשא אל אדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("S219_36","011_19_36","2SA","19","36","36","כמעט יעבר עבדך את הירדן את המלך ולמה יגמלני המלך הגמולה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("S219_37","011_19_37","2SA","19","37","37","ישב נא עבדך ואמת בעירי עם קבר אבי ואמי והנה עבדך כמהם יעבר עם אדני המלך ועשה לו את אשר טוב בעיניך׃ ");
INSERT INTO heb_vpl VALUES ("S219_38","011_19_38","2SA","19","38","38","ויאמר המלך אתי יעבר כמהם ואני אעשה לו את הטוב בעיניך וכל אשר תבחר עלי אעשה לך׃ ");
INSERT INTO heb_vpl VALUES ("S219_39","011_19_39","2SA","19","39","39","ויעבר כל העם את הירדן והמלך עבר וישק המלך לברזלי ויברכהו וישב למקמו׃ ");
INSERT INTO heb_vpl VALUES ("S219_40","011_19_40","2SA","19","40","40","ויעבר המלך הגלגלה וכמהן עבר עמו וכל עם יהודה ויעבירו את המלך וגם חצי עם ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S219_41","011_19_41","2SA","19","41","41","והנה כל איש ישראל באים אל המלך ויאמרו אל המלך מדוע גנבוך אחינו איש יהודה ויעברו את המלך ואת ביתו את הירדן וכל אנשי דוד עמו׃ ");
INSERT INTO heb_vpl VALUES ("S219_42","011_19_42","2SA","19","42","42","ויען כל איש יהודה על איש ישראל כי קרוב המלך אלי ולמה זה חרה לך על הדבר הזה האכול אכלנו מן המלך אם נשאת נשא לנו׃ ");
INSERT INTO heb_vpl VALUES ("S219_43","011_19_43","2SA","19","43","43","ויען איש ישראל את איש יהודה ויאמר עשר ידות לי במלך וגם בדוד אני ממך ומדוע הקלתני ולא היה דברי ראשון לי להשיב את מלכי ויקש דבר איש יהודה מדבר איש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S220_1","011_20_1","2SA","20","1","1","ושם נקרא איש בליעל ושמו שבע בן בכרי איש ימיני ויתקע בשפר ויאמר אין לנו חלק בדוד ולא נחלה לנו בבן ישי איש לאהליו ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S220_2","011_20_2","2SA","20","2","2","ויעל כל איש ישראל מאחרי דוד אחרי שבע בן בכרי ואיש יהודה דבקו במלכם מן הירדן ועד ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S220_3","011_20_3","2SA","20","3","3","ויבא דוד אל ביתו ירושלם ויקח המלך את עשר נשים פלגשים אשר הניח לשמר הבית ויתנם בית משמרת ויכלכלם ואליהם לא בא ותהיינה צררות עד יום מתן אלמנות חיות׃ ");
INSERT INTO heb_vpl VALUES ("S220_4","011_20_4","2SA","20","4","4","ויאמר המלך אל עמשא הזעק לי את איש יהודה שלשת ימים ואתה פה עמד׃ ");
INSERT INTO heb_vpl VALUES ("S220_5","011_20_5","2SA","20","5","5","וילך עמשא להזעיק את יהודה וייחר מן המועד אשר יעדו׃ ");
INSERT INTO heb_vpl VALUES ("S220_6","011_20_6","2SA","20","6","6","ויאמר דוד אל אבישי עתה ירע לנו שבע בן בכרי מן אבשלום אתה קח את עבדי אדניך ורדף אחריו פן מצא לו ערים בצרות והציל עיננו׃ ");
INSERT INTO heb_vpl VALUES ("S220_7","011_20_7","2SA","20","7","7","ויצאו אחריו אנשי יואב והכרתי והפלתי וכל הגברים ויצאו מירושלם לרדף אחרי שבע בן בכרי׃ ");
INSERT INTO heb_vpl VALUES ("S220_8","011_20_8","2SA","20","8","8","הם עם האבן הגדולה אשר בגבעון ועמשא בא לפניהם ויואב חגור מדו לבשו ועלו חגור חרב מצמדת על מתניו בתערה והוא יצא ותפל׃ ");
INSERT INTO heb_vpl VALUES ("S220_9","011_20_9","2SA","20","9","9","ויאמר יואב לעמשא השלום אתה אחי ותחז יד ימין יואב בזקן עמשא לנשק לו׃ ");
INSERT INTO heb_vpl VALUES ("S220_10","011_20_10","2SA","20","10","10","ועמשא לא נשמר בחרב אשר ביד יואב ויכהו בה אל החמש וישפך מעיו ארצה ולא שנה לו וימת ויואב ואבישי אחיו רדף אחרי שבע בן בכרי׃ ");
INSERT INTO heb_vpl VALUES ("S220_11","011_20_11","2SA","20","11","11","ואיש עמד עליו מנערי יואב ויאמר מי אשר חפץ ביואב ומי אשר לדוד אחרי יואב׃ ");
INSERT INTO heb_vpl VALUES ("S220_12","011_20_12","2SA","20","12","12","ועמשא מתגלל בדם בתוך המסלה וירא האיש כי עמד כל העם ויסב את עמשא מן המסלה השדה וישלך עליו בגד כאשר ראה כל הבא עליו ועמד׃ ");
INSERT INTO heb_vpl VALUES ("S220_13","011_20_13","2SA","20","13","13","כאשר הגה מן המסלה עבר כל איש אחרי יואב לרדף אחרי שבע בן בכרי׃ ");
INSERT INTO heb_vpl VALUES ("S220_14","011_20_14","2SA","20","14","14","ויעבר בכל שבטי ישראל אבלה ובית מעכה וכל הברים ויקלהו ויבאו אף אחריו׃ ");
INSERT INTO heb_vpl VALUES ("S220_15","011_20_15","2SA","20","15","15","ויבאו ויצרו עליו באבלה בית המעכה וישפכו סללה אל העיר ותעמד בחל וכל העם אשר את יואב משחיתם להפיל החומה׃ ");
INSERT INTO heb_vpl VALUES ("S220_16","011_20_16","2SA","20","16","16","ותקרא אשה חכמה מן העיר שמעו שמעו אמרו נא אל יואב קרב עד הנה ואדברה אליך׃ ");
INSERT INTO heb_vpl VALUES ("S220_17","011_20_17","2SA","20","17","17","ויקרב אליה ותאמר האשה האתה יואב ויאמר אני ותאמר לו שמע דברי אמתך ויאמר שמע אנכי׃ ");
INSERT INTO heb_vpl VALUES ("S220_18","011_20_18","2SA","20","18","18","ותאמר לאמר דבר ידברו בראשנה לאמר שאל ישאלו באבל וכן התמו׃ ");
INSERT INTO heb_vpl VALUES ("S220_19","011_20_19","2SA","20","19","19","אנכי שלמי אמוני ישראל אתה מבקש להמית עיר ואם בישראל למה תבלע נחלת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S220_20","011_20_20","2SA","20","20","20","ויען יואב ויאמר חלילה חלילה לי אם אבלע ואם אשחית׃ ");
INSERT INTO heb_vpl VALUES ("S220_21","011_20_21","2SA","20","21","21","לא כן הדבר כי איש מהר אפרים שבע בן בכרי שמו נשא ידו במלך בדוד תנו אתו לבדו ואלכה מעל העיר ותאמר האשה אל יואב הנה ראשו משלך אליך בעד החומה׃ ");
INSERT INTO heb_vpl VALUES ("S220_22","011_20_22","2SA","20","22","22","ותבוא האשה אל כל העם בחכמתה ויכרתו את ראש שבע בן בכרי וישלכו אל יואב ויתקע בשופר ויפצו מעל העיר איש לאהליו ויואב שב ירושלם אל המלך׃ ");
INSERT INTO heb_vpl VALUES ("S220_23","011_20_23","2SA","20","23","23","ויואב אל כל הצבא ישראל ובניה בן יהוידע על הכרי ועל הפלתי׃ ");
INSERT INTO heb_vpl VALUES ("S220_24","011_20_24","2SA","20","24","24","ואדרם על המס ויהושפט בן אחילוד המזכיר׃ ");
INSERT INTO heb_vpl VALUES ("S220_25","011_20_25","2SA","20","25","25","ושיא ספר וצדוק ואביתר כהנים׃ ");
INSERT INTO heb_vpl VALUES ("S220_26","011_20_26","2SA","20","26","26","וגם עירא היארי היה כהן לדוד׃ ");
INSERT INTO heb_vpl VALUES ("S221_1","011_21_1","2SA","21","1","1","ויהי רעב בימי דוד שלש שנים שנה אחרי שנה ויבקש דוד את פני יהוה ויאמר יהוה אל שאול ואל בית הדמים על אשר המית את הגבענים׃ ");
INSERT INTO heb_vpl VALUES ("S221_2","011_21_2","2SA","21","2","2","ויקרא המלך לגבענים ויאמר אליהם והגבענים לא מבני ישראל המה כי אם מיתר האמרי ובני ישראל נשבעו להם ויבקש שאול להכתם בקנאתו לבני ישראל ויהודה׃ ");
INSERT INTO heb_vpl VALUES ("S221_3","011_21_3","2SA","21","3","3","ויאמר דוד אל הגבענים מה אעשה לכם ובמה אכפר וברכו את נחלת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S221_4","011_21_4","2SA","21","4","4","ויאמרו לו הגבענים אין לי כסף וזהב עם שאול ועם ביתו ואין לנו איש להמית בישראל ויאמר מה אתם אמרים אעשה לכם׃ ");
INSERT INTO heb_vpl VALUES ("S221_5","011_21_5","2SA","21","5","5","ויאמרו אל המלך האיש אשר כלנו ואשר דמה לנו נשמדנו מהתיצב בכל גבל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S221_6","011_21_6","2SA","21","6","6","ינתן לנו שבעה אנשים מבניו והוקענום ליהוה בגבעת שאול בחיר יהוה ויאמר המלך אני אתן׃ ");
INSERT INTO heb_vpl VALUES ("S221_7","011_21_7","2SA","21","7","7","ויחמל המלך על מפיבשת בן יהונתן בן שאול על שבעת יהוה אשר בינתם בין דוד ובין יהונתן בן שאול׃ ");
INSERT INTO heb_vpl VALUES ("S221_8","011_21_8","2SA","21","8","8","ויקח המלך את שני בני רצפה בת איה אשר ילדה לשאול את ארמני ואת מפבשת ואת חמשת בני מיכל בת שאול אשר ילדה לעדריאל בן ברזלי המחלתי׃ ");
INSERT INTO heb_vpl VALUES ("S221_9","011_21_9","2SA","21","9","9","ויתנם ביד הגבענים ויקיעם בהר לפני יהוה ויפלו שבעתים יחד והם המתו בימי קציר בראשנים תחלת קציר שערים׃ ");
INSERT INTO heb_vpl VALUES ("S221_10","011_21_10","2SA","21","10","10","ותקח רצפה בת איה את השק ותטהו לה אל הצור מתחלת קציר עד נתך מים עליהם מן השמים ולא נתנה עוף השמים לנוח עליהם יומם ואת חית השדה לילה׃ ");
INSERT INTO heb_vpl VALUES ("S221_11","011_21_11","2SA","21","11","11","ויגד לדוד את אשר עשתה רצפה בת איה פלגש שאול׃ ");
INSERT INTO heb_vpl VALUES ("S221_12","011_21_12","2SA","21","12","12","וילך דוד ויקח את עצמות שאול ואת עצמות יהונתן בנו מאת בעלי יביש גלעד אשר גנבו אתם מרחב בית שן אשר תלום שם הפלשתים ביום הכות פלשתים את שאול בגלבע׃ ");
INSERT INTO heb_vpl VALUES ("S221_13","011_21_13","2SA","21","13","13","ויעל משם את עצמות שאול ואת עצמות יהונתן בנו ויאספו את עצמות המוקעים׃ ");
INSERT INTO heb_vpl VALUES ("S221_14","011_21_14","2SA","21","14","14","ויקברו את עצמות שאול ויהונתן בנו בארץ בנימן בצלע בקבר קיש אביו ויעשו כל אשר צוה המלך ויעתר אלהים לארץ אחרי כן׃ ");
INSERT INTO heb_vpl VALUES ("S221_15","011_21_15","2SA","21","15","15","ותהי עוד מלחמה לפלשתים את ישראל וירד דוד ועבדיו עמו וילחמו את פלשתים ויעף דוד׃ ");
INSERT INTO heb_vpl VALUES ("S221_16","011_21_16","2SA","21","16","16","וישבו בנב אשר בילידי הרפה ומשקל קינו שלש מאות משקל נחשת והוא חגור חדשה ויאמר להכות את דוד׃ ");
INSERT INTO heb_vpl VALUES ("S221_17","011_21_17","2SA","21","17","17","ויעזר לו אבישי בן צרויה ויך את הפלשתי וימיתהו אז נשבעו אנשי דוד לו לאמר לא תצא עוד אתנו למלחמה ולא תכבה את נר ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S221_18","011_21_18","2SA","21","18","18","ויהי אחרי כן ותהי עוד המלחמה בגוב עם פלשתים אז הכה סבכי החשתי את סף אשר בילדי הרפה׃ ");
INSERT INTO heb_vpl VALUES ("S221_19","011_21_19","2SA","21","19","19","ותהי עוד המלחמה בגוב עם פלשתים ויך אלחנן בן יערי ארגים בית הלחמי את גלית הגתי ועץ חניתו כמנור ארגים׃ ");
INSERT INTO heb_vpl VALUES ("S221_20","011_21_20","2SA","21","20","20","ותהי עוד מלחמה בגת ויהי איש מדין ואצבעת ידיו ואצבעות רגליו שש ושש עשרים וארבע מספר וגם הוא ילד להרפה׃ ");
INSERT INTO heb_vpl VALUES ("S221_21","011_21_21","2SA","21","21","21","ויחרף את ישראל ויכהו יהונתן בן שמעי אחי דוד׃ ");
INSERT INTO heb_vpl VALUES ("S221_22","011_21_22","2SA","21","22","22","את ארבעת אלה ילדו להרפה בגת ויפלו ביד דוד וביד עבדיו׃ ");
INSERT INTO heb_vpl VALUES ("S222_1","011_22_1","2SA","22","1","1","וידבר דוד ליהוה את דברי השירה הזאת ביום הציל יהוה אתו מכף כל איביו ומכף שאול׃ ");
INSERT INTO heb_vpl VALUES ("S222_2","011_22_2","2SA","22","2","2","ויאמר יהוה סלעי ומצדתי ומפלטי לי׃ ");
INSERT INTO heb_vpl VALUES ("S222_3","011_22_3","2SA","22","3","3","אלהי צורי אחסה בו מגני וקרן ישעי משגבי ומנוסי משעי מחמס תשעני׃ ");
INSERT INTO heb_vpl VALUES ("S222_4","011_22_4","2SA","22","4","4","מהלל אקרא יהוה ומאיבי אושע׃ ");
INSERT INTO heb_vpl VALUES ("S222_5","011_22_5","2SA","22","5","5","כי אפפני משברי מות נחלי בליעל יבעתני׃ ");
INSERT INTO heb_vpl VALUES ("S222_6","011_22_6","2SA","22","6","6","חבלי שאול סבני קדמני מקשי מות׃ ");
INSERT INTO heb_vpl VALUES ("S222_7","011_22_7","2SA","22","7","7","בצר לי אקרא יהוה ואל אלהי אקרא וישמע מהיכלו קולי ושועתי באזניו׃ ");
INSERT INTO heb_vpl VALUES ("S222_8","011_22_8","2SA","22","8","8","ותגעש ותרעש הארץ מוסדות השמים ירגזו ויתגעשו כי חרה לו׃ ");
INSERT INTO heb_vpl VALUES ("S222_9","011_22_9","2SA","22","9","9","עלה עשן באפו ואש מפיו תאכל גחלים בערו ממנו׃ ");
INSERT INTO heb_vpl VALUES ("S222_10","011_22_10","2SA","22","10","10","ויט שמים וירד וערפל תחת רגליו׃ ");
INSERT INTO heb_vpl VALUES ("S222_11","011_22_11","2SA","22","11","11","וירכב על כרוב ויעף וירא על כנפי רוח׃ ");
INSERT INTO heb_vpl VALUES ("S222_12","011_22_12","2SA","22","12","12","וישת חשך סביבתיו סכות חשרת מים עבי שחקים׃ ");
INSERT INTO heb_vpl VALUES ("S222_13","011_22_13","2SA","22","13","13","מנגה נגדו בערו גחלי אש׃ ");
INSERT INTO heb_vpl VALUES ("S222_14","011_22_14","2SA","22","14","14","ירעם מן שמים יהוה ועליון יתן קולו׃ ");
INSERT INTO heb_vpl VALUES ("S222_15","011_22_15","2SA","22","15","15","וישלח חצים ויפיצם ברק ויהמם׃ ");
INSERT INTO heb_vpl VALUES ("S222_16","011_22_16","2SA","22","16","16","ויראו אפקי ים יגלו מסדות תבל בגערת יהוה מנשמת רוח אפו׃ ");
INSERT INTO heb_vpl VALUES ("S222_17","011_22_17","2SA","22","17","17","ישלח ממרום יקחני ימשני ממים רבים׃ ");
INSERT INTO heb_vpl VALUES ("S222_18","011_22_18","2SA","22","18","18","יצילני מאיבי עז משנאי כי אמצו ממני׃ ");
INSERT INTO heb_vpl VALUES ("S222_19","011_22_19","2SA","22","19","19","יקדמני ביום אידי ויהי יהוה משען לי׃ ");
INSERT INTO heb_vpl VALUES ("S222_20","011_22_20","2SA","22","20","20","ויצא למרחב אתי יחלצני כי חפץ בי׃ ");
INSERT INTO heb_vpl VALUES ("S222_21","011_22_21","2SA","22","21","21","יגמלני יהוה כצדקתי כבר ידי ישיב לי׃ ");
INSERT INTO heb_vpl VALUES ("S222_22","011_22_22","2SA","22","22","22","כי שמרתי דרכי יהוה ולא רשעתי מאלהי׃ ");
INSERT INTO heb_vpl VALUES ("S222_23","011_22_23","2SA","22","23","23","כי כל משפטו לנגדי וחקתיו לא אסור ממנה׃ ");
INSERT INTO heb_vpl VALUES ("S222_24","011_22_24","2SA","22","24","24","ואהיה תמים לו ואשתמרה מעוני׃ ");
INSERT INTO heb_vpl VALUES ("S222_25","011_22_25","2SA","22","25","25","וישב יהוה לי כצדקתי כברי לנגד עיניו׃ ");
INSERT INTO heb_vpl VALUES ("S222_26","011_22_26","2SA","22","26","26","עם חסיד תתחסד עם גבור תמים תתמם׃ ");
INSERT INTO heb_vpl VALUES ("S222_27","011_22_27","2SA","22","27","27","עם נבר תתבר ועם עקש תתפל׃ ");
INSERT INTO heb_vpl VALUES ("S222_28","011_22_28","2SA","22","28","28","ואת עם עני תושיע ועיניך על רמים תשפיל׃ ");
INSERT INTO heb_vpl VALUES ("S222_29","011_22_29","2SA","22","29","29","כי אתה נירי יהוה ויהוה יגיה חשכי׃ ");
INSERT INTO heb_vpl VALUES ("S222_30","011_22_30","2SA","22","30","30","כי בכה ארוץ גדוד באלהי אדלג שור׃ ");
INSERT INTO heb_vpl VALUES ("S222_31","011_22_31","2SA","22","31","31","האל תמים דרכו אמרת יהוה צרופה מגן הוא לכל החסים בו׃ ");
INSERT INTO heb_vpl VALUES ("S222_32","011_22_32","2SA","22","32","32","כי מי אל מבלעדי יהוה ומי צור מבלעדי אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("S222_33","011_22_33","2SA","22","33","33","האל מעוזי חיל ויתר תמים דרכו׃ ");
INSERT INTO heb_vpl VALUES ("S222_34","011_22_34","2SA","22","34","34","משוה רגליו כאילות ועל במותי יעמדני׃ ");
INSERT INTO heb_vpl VALUES ("S222_35","011_22_35","2SA","22","35","35","מלמד ידי למלחמה ונחת קשת נחושה זרעתי׃ ");
INSERT INTO heb_vpl VALUES ("S222_36","011_22_36","2SA","22","36","36","ותתן לי מגן ישעך וענתך תרבני׃ ");
INSERT INTO heb_vpl VALUES ("S222_37","011_22_37","2SA","22","37","37","תרחיב צעדי תחתני ולא מעדו קרסלי׃ ");
INSERT INTO heb_vpl VALUES ("S222_38","011_22_38","2SA","22","38","38","ארדפה איבי ואשמידם ולא אשוב עד כלותם׃ ");
INSERT INTO heb_vpl VALUES ("S222_39","011_22_39","2SA","22","39","39","ואכלם ואמחצם ולא יקומון ויפלו תחת רגלי׃ ");
INSERT INTO heb_vpl VALUES ("S222_40","011_22_40","2SA","22","40","40","ותזרני חיל למלחמה תכריע קמי תחתני׃ ");
INSERT INTO heb_vpl VALUES ("S222_41","011_22_41","2SA","22","41","41","ואיבי תתה לי ערף משנאי ואצמיתם׃ ");
INSERT INTO heb_vpl VALUES ("S222_42","011_22_42","2SA","22","42","42","ישעו ואין משיע אל יהוה ולא ענם׃ ");
INSERT INTO heb_vpl VALUES ("S222_43","011_22_43","2SA","22","43","43","ואשחקם כעפר ארץ כטיט חוצות אדקם ארקעם׃ ");
INSERT INTO heb_vpl VALUES ("S222_44","011_22_44","2SA","22","44","44","ותפלטני מריבי עמי תשמרני לראש גוים עם לא ידעתי יעבדני׃ ");
INSERT INTO heb_vpl VALUES ("S222_45","011_22_45","2SA","22","45","45","בני נכר יתכחשו לי לשמוע אזן ישמעו לי׃ ");
INSERT INTO heb_vpl VALUES ("S222_46","011_22_46","2SA","22","46","46","בני נכר יבלו ויחגרו ממסגרותם׃ ");
INSERT INTO heb_vpl VALUES ("S222_47","011_22_47","2SA","22","47","47","חי יהוה וברוך צורי וירם אלהי צור ישעי׃ ");
INSERT INTO heb_vpl VALUES ("S222_48","011_22_48","2SA","22","48","48","האל הנתן נקמת לי ומוריד עמים תחתני׃ ");
INSERT INTO heb_vpl VALUES ("S222_49","011_22_49","2SA","22","49","49","ומוציאי מאיבי ומקמי תרוממני מאיש חמסים תצילני׃ ");
INSERT INTO heb_vpl VALUES ("S222_50","011_22_50","2SA","22","50","50","על כן אודך יהוה בגוים ולשמך אזמר׃ ");
INSERT INTO heb_vpl VALUES ("S222_51","011_22_51","2SA","22","51","51","מגדיל ישועות מלכו ועשה חסד למשיחו לדוד ולזרעו עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("S223_1","011_23_1","2SA","23","1","1","ואלה דברי דוד האחרנים נאם דוד בן ישי ונאם הגבר הקם על משיח אלהי יעקב ונעים זמרות ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S223_2","011_23_2","2SA","23","2","2","רוח יהוה דבר בי ומלתו על לשוני׃ ");
INSERT INTO heb_vpl VALUES ("S223_3","011_23_3","2SA","23","3","3","אמר אלהי ישראל לי דבר צור ישראל מושל באדם צדיק מושל יראת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("S223_4","011_23_4","2SA","23","4","4","וכאור בקר יזרח שמש בקר לא עבות מנגה ממטר דשא מארץ׃ ");
INSERT INTO heb_vpl VALUES ("S223_5","011_23_5","2SA","23","5","5","כי לא כן ביתי עם אל כי ברית עולם שם לי ערוכה בכל ושמרה כי כל ישעי וכל חפץ כי לא יצמיח׃ ");
INSERT INTO heb_vpl VALUES ("S223_6","011_23_6","2SA","23","6","6","ובליעל כקוץ מנד כלהם כי לא ביד יקחו׃ ");
INSERT INTO heb_vpl VALUES ("S223_7","011_23_7","2SA","23","7","7","ואיש יגע בהם ימלא ברזל ועץ חנית ובאש שרוף ישרפו בשבת׃ ");
INSERT INTO heb_vpl VALUES ("S223_8","011_23_8","2SA","23","8","8","אלה שמות הגברים אשר לדוד ישב בשבת תחכמני ראש השלשי הוא עדינו העצנו על שמנה מאות חלל בפעם אחד׃ ");
INSERT INTO heb_vpl VALUES ("S223_9","011_23_9","2SA","23","9","9","ואחרו אלעזר בן דדי בן אחחי בשלשה גברים עם דוד בחרפם בפלשתים נאספו שם למלחמה ויעלו איש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S223_10","011_23_10","2SA","23","10","10","הוא קם ויך בפלשתים עד כי יגעה ידו ותדבק ידו אל החרב ויעש יהוה תשועה גדולה ביום ההוא והעם ישבו אחריו אך לפשט׃ ");
INSERT INTO heb_vpl VALUES ("S223_11","011_23_11","2SA","23","11","11","ואחריו שמא בן אגא הררי ויאספו פלשתים לחיה ותהי שם חלקת השדה מלאה עדשים והעם נס מפני פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("S223_12","011_23_12","2SA","23","12","12","ויתיצב בתוך החלקה ויצילה ויך את פלשתים ויעש יהוה תשועה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("S223_13","011_23_13","2SA","23","13","13","וירדו שלשים מהשלשים ראש ויבאו אל קציר אל דוד אל מערת עדלם וחית פלשתים חנה בעמק רפאים׃ ");
INSERT INTO heb_vpl VALUES ("S223_14","011_23_14","2SA","23","14","14","ודוד אז במצודה ומצב פלשתים אז בית לחם׃ ");
INSERT INTO heb_vpl VALUES ("S223_15","011_23_15","2SA","23","15","15","ויתאוה דוד ויאמר מי ישקני מים מבאר בית לחם אשר בשער׃ ");
INSERT INTO heb_vpl VALUES ("S223_16","011_23_16","2SA","23","16","16","ויבקעו שלשת הגברים במחנה פלשתים וישאבו מים מבאר בית לחם אשר בשער וישאו ויבאו אל דוד ולא אבה לשתותם ויסך אתם ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("S223_17","011_23_17","2SA","23","17","17","ויאמר חלילה לי יהוה מעשתי זאת הדם האנשים ההלכים בנפשותם ולא אבה לשתותם אלה עשו שלשת הגברים׃ ");
INSERT INTO heb_vpl VALUES ("S223_18","011_23_18","2SA","23","18","18","ואבישי אחי יואב בן צרויה הוא ראש השלשי והוא עורר את חניתו על שלש מאות חלל ולו שם בשלשה׃ ");
INSERT INTO heb_vpl VALUES ("S223_19","011_23_19","2SA","23","19","19","מן השלשה הכי נכבד ויהי להם לשר ועד השלשה לא בא׃ ");
INSERT INTO heb_vpl VALUES ("S223_20","011_23_20","2SA","23","20","20","ובניהו בן יהוידע בן איש חי רב פעלים מקבצאל הוא הכה את שני אראל מואב והוא ירד והכה את האריה בתוך הבאר ביום השלג׃ ");
INSERT INTO heb_vpl VALUES ("S223_21","011_23_21","2SA","23","21","21","והוא הכה את איש מצרי אשר מראה וביד המצרי חנית וירד אליו בשבט ויגזל את החנית מיד המצרי ויהרגהו בחניתו׃ ");
INSERT INTO heb_vpl VALUES ("S223_22","011_23_22","2SA","23","22","22","אלה עשה בניהו בן יהוידע ולו שם בשלשה הגברים׃ ");
INSERT INTO heb_vpl VALUES ("S223_23","011_23_23","2SA","23","23","23","מן השלשים נכבד ואל השלשה לא בא וישמהו דוד אל משמעתו׃ ");
INSERT INTO heb_vpl VALUES ("S223_24","011_23_24","2SA","23","24","24","עשה אל אחי יואב בשלשים אלחנן בן דדו בית לחם׃ ");
INSERT INTO heb_vpl VALUES ("S223_25","011_23_25","2SA","23","25","25","שמה החרדי אליקא החרדי׃ ");
INSERT INTO heb_vpl VALUES ("S223_26","011_23_26","2SA","23","26","26","חלץ הפלטי עירא בן עקש התקועי׃ ");
INSERT INTO heb_vpl VALUES ("S223_27","011_23_27","2SA","23","27","27","אביעזר הענתתי מבני החשתי׃ ");
INSERT INTO heb_vpl VALUES ("S223_28","011_23_28","2SA","23","28","28","צלמון האחחי מהרי הנטפתי׃ ");
INSERT INTO heb_vpl VALUES ("S223_29","011_23_29","2SA","23","29","29","חלב בן בענה הנטפתי אתי בן ריבי מגבעת בני בנימן׃ ");
INSERT INTO heb_vpl VALUES ("S223_30","011_23_30","2SA","23","30","30","בניהו פרעתני הדי מנחלי געש׃ ");
INSERT INTO heb_vpl VALUES ("S223_31","011_23_31","2SA","23","31","31","אבי עלבון הערבתי עזמות הברחמי׃ ");
INSERT INTO heb_vpl VALUES ("S223_32","011_23_32","2SA","23","32","32","אליחבא השעלבני בני ישן יהונתן׃ ");
INSERT INTO heb_vpl VALUES ("S223_33","011_23_33","2SA","23","33","33","שמה ההררי אחיאם בן שרר האררי׃ ");
INSERT INTO heb_vpl VALUES ("S223_34","011_23_34","2SA","23","34","34","אליפלט בן אחסבי בן המעכתי אליעם בן אחיתפל הגלני׃ ");
INSERT INTO heb_vpl VALUES ("S223_35","011_23_35","2SA","23","35","35","חצרו הכרמלי פערי הארבי׃ ");
INSERT INTO heb_vpl VALUES ("S223_36","011_23_36","2SA","23","36","36","יגאל בן נתן מצבה בני הגדי׃ ");
INSERT INTO heb_vpl VALUES ("S223_37","011_23_37","2SA","23","37","37","צלק העמני נחרי הבארתי נשאי כלי יואב בן צריה׃ ");
INSERT INTO heb_vpl VALUES ("S223_38","011_23_38","2SA","23","38","38","עירא היתרי גרב היתרי׃ ");
INSERT INTO heb_vpl VALUES ("S223_39","011_23_39","2SA","23","39","39","אוריה החתי כל שלשים ושבעה׃ ");
INSERT INTO heb_vpl VALUES ("S224_1","011_24_1","2SA","24","1","1","ויסף אף יהוה לחרות בישראל ויסת את דוד בהם לאמר לך מנה את ישראל ואת יהודה׃ ");
INSERT INTO heb_vpl VALUES ("S224_2","011_24_2","2SA","24","2","2","ויאמר המלך אל יואב שר החיל אשר אתו שוט נא בכל שבטי ישראל מדן ועד באר שבע ופקדו את העם וידעתי את מספר העם׃ ");
INSERT INTO heb_vpl VALUES ("S224_3","011_24_3","2SA","24","3","3","ויאמר יואב אל המלך ויוסף יהוה אלהיך אל העם כהם וכהם מאה פעמים ועיני אדני המלך ראות ואדני המלך למה חפץ בדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("S224_4","011_24_4","2SA","24","4","4","ויחזק דבר המלך אל יואב ועל שרי החיל ויצא יואב ושרי החיל לפני המלך לפקד את העם את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("S224_5","011_24_5","2SA","24","5","5","ויעברו את הירדן ויחנו בערוער ימין העיר אשר בתוך הנחל הגד ואל יעזר׃ ");
INSERT INTO heb_vpl VALUES ("S224_6","011_24_6","2SA","24","6","6","ויבאו הגלעדה ואל ארץ תחתים חדשי ויבאו דנה יען וסביב אל צידון׃ ");
INSERT INTO heb_vpl VALUES ("S224_7","011_24_7","2SA","24","7","7","ויבאו מבצר צר וכל ערי החוי והכנעני ויצאו אל נגב יהודה באר שבע׃ ");
INSERT INTO heb_vpl VALUES ("S224_8","011_24_8","2SA","24","8","8","וישטו בכל הארץ ויבאו מקצה תשעה חדשים ועשרים יום ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("S224_9","011_24_9","2SA","24","9","9","ויתן יואב את מספר מפקד העם אל המלך ותהי ישראל שמנה מאות אלף איש חיל שלף חרב ואיש יהודה חמש מאות אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("S224_10","011_24_10","2SA","24","10","10","ויך לב דוד אתו אחרי כן ספר את העם ויאמר דוד אל יהוה חטאתי מאד אשר עשיתי ועתה יהוה העבר נא את עון עבדך כי נסכלתי מאד׃ ");
INSERT INTO heb_vpl VALUES ("S224_11","011_24_11","2SA","24","11","11","ויקם דוד בבקר ודבר יהוה היה אל גד הנביא חזה דוד לאמר׃ ");
INSERT INTO heb_vpl VALUES ("S224_12","011_24_12","2SA","24","12","12","הלוך ודברת אל דוד כה אמר יהוה שלש אנכי נוטל עליך בחר לך אחת מהם ואעשה לך׃ ");
INSERT INTO heb_vpl VALUES ("S224_13","011_24_13","2SA","24","13","13","ויבא גד אל דוד ויגד לו ויאמר לו התבוא לך שבע שנים רעב בארצך אם שלשה חדשים נסך לפני צריך והוא רדפך ואם היות שלשת ימים דבר בארצך עתה דע וראה מה אשיב שלחי דבר׃ ");
INSERT INTO heb_vpl VALUES ("S224_14","011_24_14","2SA","24","14","14","ויאמר דוד אל גד צר לי מאד נפלה נא ביד יהוה כי רבים רחמו וביד אדם אל אפלה׃ ");
INSERT INTO heb_vpl VALUES ("S224_15","011_24_15","2SA","24","15","15","ויתן יהוה דבר בישראל מהבקר ועד עת מועד וימת מן העם מדן ועד באר שבע שבעים אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("S224_16","011_24_16","2SA","24","16","16","וישלח ידו המלאך ירושלם לשחתה וינחם יהוה אל הרעה ויאמר למלאך המשחית בעם רב עתה הרף ידך ומלאך יהוה היה עם גרן האורנה היבסי׃ ");
INSERT INTO heb_vpl VALUES ("S224_17","011_24_17","2SA","24","17","17","ויאמר דוד אל יהוה בראתו את המלאך המכה בעם ויאמר הנה אנכי חטאתי ואנכי העויתי ואלה הצאן מה עשו תהי נא ידך בי ובבית אבי׃ ");
INSERT INTO heb_vpl VALUES ("S224_18","011_24_18","2SA","24","18","18","ויבא גד אל דוד ביום ההוא ויאמר לו עלה הקם ליהוה מזבח בגרן ארניה היבסי׃ ");
INSERT INTO heb_vpl VALUES ("S224_19","011_24_19","2SA","24","19","19","ויעל דוד כדבר גד כאשר צוה יהוה׃ ");
INSERT INTO heb_vpl VALUES ("S224_20","011_24_20","2SA","24","20","20","וישקף ארונה וירא את המלך ואת עבדיו עברים עליו ויצא ארונה וישתחו למלך אפיו ארצה׃ ");
INSERT INTO heb_vpl VALUES ("S224_21","011_24_21","2SA","24","21","21","ויאמר ארונה מדוע בא אדני המלך אל עבדו ויאמר דוד לקנות מעמך את הגרן לבנות מזבח ליהוה ותעצר המגפה מעל העם׃ ");
INSERT INTO heb_vpl VALUES ("S224_22","011_24_22","2SA","24","22","22","ויאמר ארונה אל דוד יקח ויעל אדני המלך הטוב בעינו ראה הבקר לעלה והמרגים וכלי הבקר לעצים׃ ");
INSERT INTO heb_vpl VALUES ("S224_23","011_24_23","2SA","24","23","23","הכל נתן ארונה המלך למלך ויאמר ארונה אל המלך יהוה אלהיך ירצך׃ ");
INSERT INTO heb_vpl VALUES ("S224_24","011_24_24","2SA","24","24","24","ויאמר המלך אל ארונה לא כי קנו אקנה מאותך במחיר ולא אעלה ליהוה אלהי עלות חנם ויקן דוד את הגרן ואת הבקר בכסף שקלים חמשים׃ ");
INSERT INTO heb_vpl VALUES ("S224_25","011_24_25","2SA","24","25","25","ויבן שם דוד מזבח ליהוה ויעל עלות ושלמים ויעתר יהוה לארץ ותעצר המגפה מעל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K11_1","012_1_1","1KI","1","1","1","והמלך דוד זקן בא בימים ויכסהו בבגדים ולא יחם לו׃ ");
INSERT INTO heb_vpl VALUES ("K11_2","012_1_2","1KI","1","2","2","ויאמרו לו עבדיו יבקשו לאדני המלך נערה בתולה ועמדה לפני המלך ותהי לו סכנת ושכבה בחיקך וחם לאדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("K11_3","012_1_3","1KI","1","3","3","ויבקשו נערה יפה בכל גבול ישראל וימצאו את אבישג השונמית ויבאו אתה למלך׃ ");
INSERT INTO heb_vpl VALUES ("K11_4","012_1_4","1KI","1","4","4","והנערה יפה עד מאד ותהי למלך סכנת ותשרתהו והמלך לא ידעה׃ ");
INSERT INTO heb_vpl VALUES ("K11_5","012_1_5","1KI","1","5","5","ואדניה בן חגית מתנשא לאמר אני אמלך ויעש לו רכב ופרשים וחמשים איש רצים לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K11_6","012_1_6","1KI","1","6","6","ולא עצבו אביו מימיו לאמר מדוע ככה עשית וגם הוא טוב תאר מאד ואתו ילדה אחרי אבשלום׃ ");
INSERT INTO heb_vpl VALUES ("K11_7","012_1_7","1KI","1","7","7","ויהיו דבריו עם יואב בן צרויה ועם אביתר הכהן ויעזרו אחרי אדניה׃ ");
INSERT INTO heb_vpl VALUES ("K11_8","012_1_8","1KI","1","8","8","וצדוק הכהן ובניהו בן יהוידע ונתן הנביא ושמעי ורעי והגבורים אשר לדוד לא היו עם אדניהו׃ ");
INSERT INTO heb_vpl VALUES ("K11_9","012_1_9","1KI","1","9","9","ויזבח אדניהו צאן ובקר ומריא עם אבן הזחלת אשר אצל עין רגל ויקרא את כל אחיו בני המלך ולכל אנשי יהודה עבדי המלך׃ ");
INSERT INTO heb_vpl VALUES ("K11_10","012_1_10","1KI","1","10","10","ואת נתן הנביא ובניהו ואת הגבורים ואת שלמה אחיו לא קרא׃ ");
INSERT INTO heb_vpl VALUES ("K11_11","012_1_11","1KI","1","11","11","ויאמר נתן אל בת שבע אם שלמה לאמר הלוא שמעת כי מלך אדניהו בן חגית ואדנינו דוד לא ידע׃ ");
INSERT INTO heb_vpl VALUES ("K11_12","012_1_12","1KI","1","12","12","ועתה לכי איעצך נא עצה ומלטי את נפשך ואת נפש בנך שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K11_13","012_1_13","1KI","1","13","13","לכי ובאי אל המלך דוד ואמרת אליו הלא אתה אדני המלך נשבעת לאמתך לאמר כי שלמה בנך ימלך אחרי והוא ישב על כסאי ומדוע מלך אדניהו׃ ");
INSERT INTO heb_vpl VALUES ("K11_14","012_1_14","1KI","1","14","14","הנה עודך מדברת שם עם המלך ואני אבוא אחריך ומלאתי את דבריך׃ ");
INSERT INTO heb_vpl VALUES ("K11_15","012_1_15","1KI","1","15","15","ותבא בת שבע אל המלך החדרה והמלך זקן מאד ואבישג השונמית משרת את המלך׃ ");
INSERT INTO heb_vpl VALUES ("K11_16","012_1_16","1KI","1","16","16","ותקד בת שבע ותשתחו למלך ויאמר המלך מה לך׃ ");
INSERT INTO heb_vpl VALUES ("K11_17","012_1_17","1KI","1","17","17","ותאמר לו אדני אתה נשבעת ביהוה אלהיך לאמתך כי שלמה בנך ימלך אחרי והוא ישב על כסאי׃ ");
INSERT INTO heb_vpl VALUES ("K11_18","012_1_18","1KI","1","18","18","ועתה הנה אדניה מלך ועתה אדני המלך לא ידעת׃ ");
INSERT INTO heb_vpl VALUES ("K11_19","012_1_19","1KI","1","19","19","ויזבח שור ומריא וצאן לרב ויקרא לכל בני המלך ולאביתר הכהן וליאב שר הצבא ולשלמה עבדך לא קרא׃ ");
INSERT INTO heb_vpl VALUES ("K11_20","012_1_20","1KI","1","20","20","ואתה אדני המלך עיני כל ישראל עליך להגיד להם מי ישב על כסא אדני המלך אחריו׃ ");
INSERT INTO heb_vpl VALUES ("K11_21","012_1_21","1KI","1","21","21","והיה כשכב אדני המלך עם אבתיו והייתי אני ובני שלמה חטאים׃ ");
INSERT INTO heb_vpl VALUES ("K11_22","012_1_22","1KI","1","22","22","והנה עודנה מדברת עם המלך ונתן הנביא בא׃ ");
INSERT INTO heb_vpl VALUES ("K11_23","012_1_23","1KI","1","23","23","ויגידו למלך לאמר הנה נתן הנביא ויבא לפני המלך וישתחו למלך על אפיו ארצה׃ ");
INSERT INTO heb_vpl VALUES ("K11_24","012_1_24","1KI","1","24","24","ויאמר נתן אדני המלך אתה אמרת אדניהו ימלך אחרי והוא ישב על כסאי׃ ");
INSERT INTO heb_vpl VALUES ("K11_25","012_1_25","1KI","1","25","25","כי ירד היום ויזבח שור ומריא וצאן לרב ויקרא לכל בני המלך ולשרי הצבא ולאביתר הכהן והנם אכלים ושתים לפניו ויאמרו יחי המלך אדניהו׃ ");
INSERT INTO heb_vpl VALUES ("K11_26","012_1_26","1KI","1","26","26","ולי אני עבדך ולצדק הכהן ולבניהו בן יהוידע ולשלמה עבדך לא קרא׃ ");
INSERT INTO heb_vpl VALUES ("K11_27","012_1_27","1KI","1","27","27","אם מאת אדני המלך נהיה הדבר הזה ולא הודעת את עבדיך מי ישב על כסא אדני המלך אחריו׃ ");
INSERT INTO heb_vpl VALUES ("K11_28","012_1_28","1KI","1","28","28","ויען המלך דוד ויאמר קראו לי לבת שבע ותבא לפני המלך ותעמד לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("K11_29","012_1_29","1KI","1","29","29","וישבע המלך ויאמר חי יהוה אשר פדה את נפשי מכל צרה׃ ");
INSERT INTO heb_vpl VALUES ("K11_30","012_1_30","1KI","1","30","30","כי כאשר נשבעתי לך ביהוה אלהי ישראל לאמר כי שלמה בנך ימלך אחרי והוא ישב על כסאי תחתי כי כן אעשה היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K11_31","012_1_31","1KI","1","31","31","ותקד בת שבע אפים ארץ ותשתחו למלך ותאמר יחי אדני המלך דוד לעלם׃ ");
INSERT INTO heb_vpl VALUES ("K11_32","012_1_32","1KI","1","32","32","ויאמר המלך דוד קראו לי לצדוק הכהן ולנתן הנביא ולבניהו בן יהוידע ויבאו לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("K11_33","012_1_33","1KI","1","33","33","ויאמר המלך להם קחו עמכם את עבדי אדניכם והרכבתם את שלמה בני על הפרדה אשר לי והורדתם אתו אל גחון׃ ");
INSERT INTO heb_vpl VALUES ("K11_34","012_1_34","1KI","1","34","34","ומשח אתו שם צדוק הכהן ונתן הנביא למלך על ישראל ותקעתם בשופר ואמרתם יחי המלך שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K11_35","012_1_35","1KI","1","35","35","ועליתם אחריו ובא וישב על כסאי והוא ימלך תחתי ואתו צויתי להיות נגיד על ישראל ועל יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K11_36","012_1_36","1KI","1","36","36","ויען בניהו בן יהוידע את המלך ויאמר אמן כן יאמר יהוה אלהי אדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("K11_37","012_1_37","1KI","1","37","37","כאשר היה יהוה עם אדני המלך כן יהי עם שלמה ויגדל את כסאו מכסא אדני המלך דוד׃ ");
INSERT INTO heb_vpl VALUES ("K11_38","012_1_38","1KI","1","38","38","וירד צדוק הכהן ונתן הנביא ובניהו בן יהוידע והכרתי והפלתי וירכבו את שלמה על פרדת המלך דוד וילכו אתו על גחון׃ ");
INSERT INTO heb_vpl VALUES ("K11_39","012_1_39","1KI","1","39","39","ויקח צדוק הכהן את קרן השמן מן האהל וימשח את שלמה ויתקעו בשופר ויאמרו כל העם יחי המלך שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K11_40","012_1_40","1KI","1","40","40","ויעלו כל העם אחריו והעם מחללים בחללים ושמחים שמחה גדולה ותבקע הארץ בקולם׃ ");
INSERT INTO heb_vpl VALUES ("K11_41","012_1_41","1KI","1","41","41","וישמע אדניהו וכל הקראים אשר אתו והם כלו לאכל וישמע יואב את קול השופר ויאמר מדוע קול הקריה הומה׃ ");
INSERT INTO heb_vpl VALUES ("K11_42","012_1_42","1KI","1","42","42","עודנו מדבר והנה יונתן בן אביתר הכהן בא ויאמר אדניהו בא כי איש חיל אתה וטוב תבשר׃ ");
INSERT INTO heb_vpl VALUES ("K11_43","012_1_43","1KI","1","43","43","ויען יונתן ויאמר לאדניהו אבל אדנינו המלך דוד המליך את שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K11_44","012_1_44","1KI","1","44","44","וישלח אתו המלך את צדוק הכהן ואת נתן הנביא ובניהו בן יהוידע והכרתי והפלתי וירכבו אתו על פרדת המלך׃ ");
INSERT INTO heb_vpl VALUES ("K11_45","012_1_45","1KI","1","45","45","וימשחו אתו צדוק הכהן ונתן הנביא למלך בגחון ויעלו משם שמחים ותהם הקריה הוא הקול אשר שמעתם׃ ");
INSERT INTO heb_vpl VALUES ("K11_46","012_1_46","1KI","1","46","46","וגם ישב שלמה על כסא המלוכה׃ ");
INSERT INTO heb_vpl VALUES ("K11_47","012_1_47","1KI","1","47","47","וגם באו עבדי המלך לברך את אדנינו המלך דוד לאמר ייטב אלהיך את שם שלמה משמך ויגדל את כסאו מכסאך וישתחו המלך על המשכב׃ ");
INSERT INTO heb_vpl VALUES ("K11_48","012_1_48","1KI","1","48","48","וגם ככה אמר המלך ברוך יהוה אלהי ישראל אשר נתן היום ישב על כסאי ועיני ראות׃ ");
INSERT INTO heb_vpl VALUES ("K11_49","012_1_49","1KI","1","49","49","ויחרדו ויקמו כל הקראים אשר לאדניהו וילכו איש לדרכו׃ ");
INSERT INTO heb_vpl VALUES ("K11_50","012_1_50","1KI","1","50","50","ואדניהו ירא מפני שלמה ויקם וילך ויחזק בקרנות המזבח׃ ");
INSERT INTO heb_vpl VALUES ("K11_51","012_1_51","1KI","1","51","51","ויגד לשלמה לאמר הנה אדניהו ירא את המלך שלמה והנה אחז בקרנות המזבח לאמר ישבע לי כיום המלך שלמה אם ימית את עבדו בחרב׃ ");
INSERT INTO heb_vpl VALUES ("K11_52","012_1_52","1KI","1","52","52","ויאמר שלמה אם יהיה לבן חיל לא יפל משערתו ארצה ואם רעה תמצא בו ומת׃ ");
INSERT INTO heb_vpl VALUES ("K11_53","012_1_53","1KI","1","53","53","וישלח המלך שלמה וירדהו מעל המזבח ויבא וישתחו למלך שלמה ויאמר לו שלמה לך לביתך׃ ");
INSERT INTO heb_vpl VALUES ("K12_1","012_2_1","1KI","2","1","1","ויקרבו ימי דוד למות ויצו את שלמה בנו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K12_2","012_2_2","1KI","2","2","2","אנכי הלך בדרך כל הארץ וחזקת והיית לאיש׃ ");
INSERT INTO heb_vpl VALUES ("K12_3","012_2_3","1KI","2","3","3","ושמרת את משמרת יהוה אלהיך ללכת בדרכיו לשמר חקתיו מצותיו ומשפטיו ועדותיו ככתוב בתורת משה למען תשכיל את כל אשר תעשה ואת כל אשר תפנה שם׃ ");
INSERT INTO heb_vpl VALUES ("K12_4","012_2_4","1KI","2","4","4","למען יקים יהוה את דברו אשר דבר עלי לאמר אם ישמרו בניך את דרכם ללכת לפני באמת בכל לבבם ובכל נפשם לאמר לא יכרת לך איש מעל כסא ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K12_5","012_2_5","1KI","2","5","5","וגם אתה ידעת את אשר עשה לי יואב בן צרויה אשר עשה לשני שרי צבאות ישראל לאבנר בן נר ולעמשא בן יתר ויהרגם וישם דמי מלחמה בשלם ויתן דמי מלחמה בחגרתו אשר במתניו ובנעלו אשר ברגליו׃ ");
INSERT INTO heb_vpl VALUES ("K12_6","012_2_6","1KI","2","6","6","ועשית כחכמתך ולא תורד שיבתו בשלם שאל׃ ");
INSERT INTO heb_vpl VALUES ("K12_7","012_2_7","1KI","2","7","7","ולבני ברזלי הגלעדי תעשה חסד והיו באכלי שלחנך כי כן קרבו אלי בברחי מפני אבשלום אחיך׃ ");
INSERT INTO heb_vpl VALUES ("K12_8","012_2_8","1KI","2","8","8","והנה עמך שמעי בן גרא בן הימיני מבחרים והוא קללני קללה נמרצת ביום לכתי מחנים והוא ירד לקראתי הירדן ואשבע לו ביהוה לאמר אם אמיתך בחרב׃ ");
INSERT INTO heb_vpl VALUES ("K12_9","012_2_9","1KI","2","9","9","ועתה אל תנקהו כי איש חכם אתה וידעת את אשר תעשה לו והורדת את שיבתו בדם שאול׃ ");
INSERT INTO heb_vpl VALUES ("K12_10","012_2_10","1KI","2","10","10","וישכב דוד עם אבתיו ויקבר בעיר דוד׃ ");
INSERT INTO heb_vpl VALUES ("K12_11","012_2_11","1KI","2","11","11","והימים אשר מלך דוד על ישראל ארבעים שנה בחברון מלך שבע שנים ובירושלם מלך שלשים ושלש שנים׃ ");
INSERT INTO heb_vpl VALUES ("K12_12","012_2_12","1KI","2","12","12","ושלמה ישב על כסא דוד אביו ותכן מלכתו מאד׃ ");
INSERT INTO heb_vpl VALUES ("K12_13","012_2_13","1KI","2","13","13","ויבא אדניהו בן חגית אל בת שבע אם שלמה ותאמר השלום באך ויאמר שלום׃ ");
INSERT INTO heb_vpl VALUES ("K12_14","012_2_14","1KI","2","14","14","ויאמר דבר לי אליך ותאמר דבר׃ ");
INSERT INTO heb_vpl VALUES ("K12_15","012_2_15","1KI","2","15","15","ויאמר את ידעת כי לי היתה המלוכה ועלי שמו כל ישראל פניהם למלך ותסב המלוכה ותהי לאחי כי מיהוה היתה לו׃ ");
INSERT INTO heb_vpl VALUES ("K12_16","012_2_16","1KI","2","16","16","ועתה שאלה אחת אנכי שאל מאתך אל תשבי את פני ותאמר אליו דבר׃ ");
INSERT INTO heb_vpl VALUES ("K12_17","012_2_17","1KI","2","17","17","ויאמר אמרי נא לשלמה המלך כי לא ישיב את פניך ויתן לי את אבישג השונמית לאשה׃ ");
INSERT INTO heb_vpl VALUES ("K12_18","012_2_18","1KI","2","18","18","ותאמר בת שבע טוב אנכי אדבר עליך אל המלך׃ ");
INSERT INTO heb_vpl VALUES ("K12_19","012_2_19","1KI","2","19","19","ותבא בת שבע אל המלך שלמה לדבר לו על אדניהו ויקם המלך לקראתה וישתחו לה וישב על כסאו וישם כסא לאם המלך ותשב לימינו׃ ");
INSERT INTO heb_vpl VALUES ("K12_20","012_2_20","1KI","2","20","20","ותאמר שאלה אחת קטנה אנכי שאלת מאתך אל תשב את פני ויאמר לה המלך שאלי אמי כי לא אשיב את פניך׃ ");
INSERT INTO heb_vpl VALUES ("K12_21","012_2_21","1KI","2","21","21","ותאמר יתן את אבישג השנמית לאדניהו אחיך לאשה׃ ");
INSERT INTO heb_vpl VALUES ("K12_22","012_2_22","1KI","2","22","22","ויען המלך שלמה ויאמר לאמו ולמה את שאלת את אבישג השנמית לאדניהו ושאלי לו את המלוכה כי הוא אחי הגדול ממני ולו ולאביתר הכהן וליואב בן צרויה׃ ");
INSERT INTO heb_vpl VALUES ("K12_23","012_2_23","1KI","2","23","23","וישבע המלך שלמה ביהוה לאמר כה יעשה לי אלהים וכה יוסיף כי בנפשו דבר אדניהו את הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("K12_24","012_2_24","1KI","2","24","24","ועתה חי יהוה אשר הכינני ויושיביני על כסא דוד אבי ואשר עשה לי בית כאשר דבר כי היום יומת אדניהו׃ ");
INSERT INTO heb_vpl VALUES ("K12_25","012_2_25","1KI","2","25","25","וישלח המלך שלמה ביד בניהו בן יהוידע ויפגע בו וימת׃ ");
INSERT INTO heb_vpl VALUES ("K12_26","012_2_26","1KI","2","26","26","ולאביתר הכהן אמר המלך ענתת לך על שדיך כי איש מות אתה וביום הזה לא אמיתך כי נשאת את ארון אדני יהוה לפני דוד אבי וכי התענית בכל אשר התענה אבי׃ ");
INSERT INTO heb_vpl VALUES ("K12_27","012_2_27","1KI","2","27","27","ויגרש שלמה את אביתר מהיות כהן ליהוה למלא את דבר יהוה אשר דבר על בית עלי בשלה׃ ");
INSERT INTO heb_vpl VALUES ("K12_28","012_2_28","1KI","2","28","28","והשמעה באה עד יואב כי יואב נטה אחרי אדניה ואחרי אבשלום לא נטה וינס יואב אל אהל יהוה ויחזק בקרנות המזבח׃ ");
INSERT INTO heb_vpl VALUES ("K12_29","012_2_29","1KI","2","29","29","ויגד למלך שלמה כי נס יואב אל אהל יהוה והנה אצל המזבח וישלח שלמה את בניהו בן יהוידע לאמר לך פגע בו׃ ");
INSERT INTO heb_vpl VALUES ("K12_30","012_2_30","1KI","2","30","30","ויבא בניהו אל אהל יהוה ויאמר אליו כה אמר המלך צא ויאמר לא כי פה אמות וישב בניהו את המלך דבר לאמר כה דבר יואב וכה ענני׃ ");
INSERT INTO heb_vpl VALUES ("K12_31","012_2_31","1KI","2","31","31","ויאמר לו המלך עשה כאשר דבר ופגע בו וקברתו והסירת דמי חנם אשר שפך יואב מעלי ומעל בית אבי׃ ");
INSERT INTO heb_vpl VALUES ("K12_32","012_2_32","1KI","2","32","32","והשיב יהוה את דמו על ראשו אשר פגע בשני אנשים צדקים וטבים ממנו ויהרגם בחרב ואבי דוד לא ידע את אבנר בן נר שר צבא ישראל ואת עמשא בן יתר שר צבא יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K12_33","012_2_33","1KI","2","33","33","ושבו דמיהם בראש יואב ובראש זרעו לעלם ולדוד ולזרעו ולביתו ולכסאו יהיה שלום עד עולם מעם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K12_34","012_2_34","1KI","2","34","34","ויעל בניהו בן יהוידע ויפגע בו וימתהו ויקבר בביתו במדבר׃ ");
INSERT INTO heb_vpl VALUES ("K12_35","012_2_35","1KI","2","35","35","ויתן המלך את בניהו בן יהוידע תחתיו על הצבא ואת צדוק הכהן נתן המלך תחת אביתר׃ ");
INSERT INTO heb_vpl VALUES ("K12_36","012_2_36","1KI","2","36","36","וישלח המלך ויקרא לשמעי ויאמר לו בנה לך בית בירושלם וישבת שם ולא תצא משם אנה ואנה׃ ");
INSERT INTO heb_vpl VALUES ("K12_37","012_2_37","1KI","2","37","37","והיה ביום צאתך ועברת את נחל קדרון ידע תדע כי מות תמות דמך יהיה בראשך׃ ");
INSERT INTO heb_vpl VALUES ("K12_38","012_2_38","1KI","2","38","38","ויאמר שמעי למלך טוב הדבר כאשר דבר אדני המלך כן יעשה עבדך וישב שמעי בירושלם ימים רבים׃ ");
INSERT INTO heb_vpl VALUES ("K12_39","012_2_39","1KI","2","39","39","ויהי מקץ שלש שנים ויברחו שני עבדים לשמעי אל אכיש בן מעכה מלך גת ויגידו לשמעי לאמר הנה עבדיך בגת׃ ");
INSERT INTO heb_vpl VALUES ("K12_40","012_2_40","1KI","2","40","40","ויקם שמעי ויחבש את חמרו וילך גתה אל אכיש לבקש את עבדיו וילך שמעי ויבא את עבדיו מגת׃ ");
INSERT INTO heb_vpl VALUES ("K12_41","012_2_41","1KI","2","41","41","ויגד לשלמה כי הלך שמעי מירושלם גת וישב׃ ");
INSERT INTO heb_vpl VALUES ("K12_42","012_2_42","1KI","2","42","42","וישלח המלך ויקרא לשמעי ויאמר אליו הלוא השבעתיך ביהוה ואעד בך לאמר ביום צאתך והלכת אנה ואנה ידע תדע כי מות תמות ותאמר אלי טוב הדבר שמעתי׃ ");
INSERT INTO heb_vpl VALUES ("K12_43","012_2_43","1KI","2","43","43","ומדוע לא שמרת את שבעת יהוה ואת המצוה אשר צויתי עליך׃ ");
INSERT INTO heb_vpl VALUES ("K12_44","012_2_44","1KI","2","44","44","ויאמר המלך אל שמעי אתה ידעת את כל הרעה אשר ידע לבבך אשר עשית לדוד אבי והשיב יהוה את רעתך בראשך׃ ");
INSERT INTO heb_vpl VALUES ("K12_45","012_2_45","1KI","2","45","45","והמלך שלמה ברוך וכסא דוד יהיה נכון לפני יהוה עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("K12_46","012_2_46","1KI","2","46","46","ויצו המלך את בניהו בן יהוידע ויצא ויפגע בו וימת והממלכה נכונה ביד שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K13_1","012_3_1","1KI","3","1","1","ויתחתן שלמה את פרעה מלך מצרים ויקח את בת פרעה ויביאה אל עיר דוד עד כלתו לבנות את ביתו ואת בית יהוה ואת חומת ירושלם סביב׃ ");
INSERT INTO heb_vpl VALUES ("K13_2","012_3_2","1KI","3","2","2","רק העם מזבחים בבמות כי לא נבנה בית לשם יהוה עד הימים ההם׃ ");
INSERT INTO heb_vpl VALUES ("K13_3","012_3_3","1KI","3","3","3","ויאהב שלמה את יהוה ללכת בחקות דוד אביו רק בבמות הוא מזבח ומקטיר׃ ");
INSERT INTO heb_vpl VALUES ("K13_4","012_3_4","1KI","3","4","4","וילך המלך גבענה לזבח שם כי היא הבמה הגדולה אלף עלות יעלה שלמה על המזבח ההוא׃ ");
INSERT INTO heb_vpl VALUES ("K13_5","012_3_5","1KI","3","5","5","בגבעון נראה יהוה אל שלמה בחלום הלילה ויאמר אלהים שאל מה אתן לך׃ ");
INSERT INTO heb_vpl VALUES ("K13_6","012_3_6","1KI","3","6","6","ויאמר שלמה אתה עשית עם עבדך דוד אבי חסד גדול כאשר הלך לפניך באמת ובצדקה ובישרת לבב עמך ותשמר לו את החסד הגדול הזה ותתן לו בן ישב על כסאו כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K13_7","012_3_7","1KI","3","7","7","ועתה יהוה אלהי אתה המלכת את עבדך תחת דוד אבי ואנכי נער קטן לא אדע צאת ובא׃ ");
INSERT INTO heb_vpl VALUES ("K13_8","012_3_8","1KI","3","8","8","ועבדך בתוך עמך אשר בחרת עם רב אשר לא ימנה ולא יספר מרב׃ ");
INSERT INTO heb_vpl VALUES ("K13_9","012_3_9","1KI","3","9","9","ונתת לעבדך לב שמע לשפט את עמך להבין בין טוב לרע כי מי יוכל לשפט את עמך הכבד הזה׃ ");
INSERT INTO heb_vpl VALUES ("K13_10","012_3_10","1KI","3","10","10","וייטב הדבר בעיני אדני כי שאל שלמה את הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("K13_11","012_3_11","1KI","3","11","11","ויאמר אלהים אליו יען אשר שאלת את הדבר הזה ולא שאלת לך ימים רבים ולא שאלת לך עשר ולא שאלת נפש איביך ושאלת לך הבין לשמע משפט׃ ");
INSERT INTO heb_vpl VALUES ("K13_12","012_3_12","1KI","3","12","12","הנה עשיתי כדבריך הנה נתתי לך לב חכם ונבון אשר כמוך לא היה לפניך ואחריך לא יקום כמוך׃ ");
INSERT INTO heb_vpl VALUES ("K13_13","012_3_13","1KI","3","13","13","וגם אשר לא שאלת נתתי לך גם עשר גם כבוד אשר לא היה כמוך איש במלכים כל ימיך׃ ");
INSERT INTO heb_vpl VALUES ("K13_14","012_3_14","1KI","3","14","14","ואם תלך בדרכי לשמר חקי ומצותי כאשר הלך דויד אביך והארכתי את ימיך׃ ");
INSERT INTO heb_vpl VALUES ("K13_15","012_3_15","1KI","3","15","15","ויקץ שלמה והנה חלום ויבוא ירושלם ויעמד לפני ארון ברית אדני ויעל עלות ויעש שלמים ויעש משתה לכל עבדיו׃ ");
INSERT INTO heb_vpl VALUES ("K13_16","012_3_16","1KI","3","16","16","אז תבאנה שתים נשים זנות אל המלך ותעמדנה לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K13_17","012_3_17","1KI","3","17","17","ותאמר האשה האחת בי אדני אני והאשה הזאת ישבת בבית אחד ואלד עמה בבית׃ ");
INSERT INTO heb_vpl VALUES ("K13_18","012_3_18","1KI","3","18","18","ויהי ביום השלישי ללדתי ותלד גם האשה הזאת ואנחנו יחדו אין זר אתנו בבית זולתי שתים אנחנו בבית׃ ");
INSERT INTO heb_vpl VALUES ("K13_19","012_3_19","1KI","3","19","19","וימת בן האשה הזאת לילה אשר שכבה עליו׃ ");
INSERT INTO heb_vpl VALUES ("K13_20","012_3_20","1KI","3","20","20","ותקם בתוך הלילה ותקח את בני מאצלי ואמתך ישנה ותשכיבהו בחיקה ואת בנה המת השכיבה בחיקי׃ ");
INSERT INTO heb_vpl VALUES ("K13_21","012_3_21","1KI","3","21","21","ואקם בבקר להיניק את בני והנה מת ואתבונן אליו בבקר והנה לא היה בני אשר ילדתי׃ ");
INSERT INTO heb_vpl VALUES ("K13_22","012_3_22","1KI","3","22","22","ותאמר האשה האחרת לא כי בני החי ובנך המת וזאת אמרת לא כי בנך המת ובני החי ותדברנה לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("K13_23","012_3_23","1KI","3","23","23","ויאמר המלך זאת אמרת זה בני החי ובנך המת וזאת אמרת לא כי בנך המת ובני החי׃ ");
INSERT INTO heb_vpl VALUES ("K13_24","012_3_24","1KI","3","24","24","ויאמר המלך קחו לי חרב ויבאו החרב לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("K13_25","012_3_25","1KI","3","25","25","ויאמר המלך גזרו את הילד החי לשנים ותנו את החצי לאחת ואת החצי לאחת׃ ");
INSERT INTO heb_vpl VALUES ("K13_26","012_3_26","1KI","3","26","26","ותאמר האשה אשר בנה החי אל המלך כי נכמרו רחמיה על בנה ותאמר בי אדני תנו לה את הילוד החי והמת אל תמיתהו וזאת אמרת גם לי גם לך לא יהיה גזרו׃ ");
INSERT INTO heb_vpl VALUES ("K13_27","012_3_27","1KI","3","27","27","ויען המלך ויאמר תנו לה את הילוד החי והמת לא תמיתהו היא אמו׃ ");
INSERT INTO heb_vpl VALUES ("K13_28","012_3_28","1KI","3","28","28","וישמעו כל ישראל את המשפט אשר שפט המלך ויראו מפני המלך כי ראו כי חכמת אלהים בקרבו לעשות משפט׃ ");
INSERT INTO heb_vpl VALUES ("K14_1","012_4_1","1KI","4","1","1","ויהי המלך שלמה מלך על כל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K14_2","012_4_2","1KI","4","2","2","ואלה השרים אשר לו עזריהו בן צדוק הכהן׃ ");
INSERT INTO heb_vpl VALUES ("K14_3","012_4_3","1KI","4","3","3","אליחרף ואחיה בני שישא ספרים יהושפט בן אחילוד המזכיר׃ ");
INSERT INTO heb_vpl VALUES ("K14_4","012_4_4","1KI","4","4","4","ובניהו בן יהוידע על הצבא וצדוק ואביתר כהנים׃ ");
INSERT INTO heb_vpl VALUES ("K14_5","012_4_5","1KI","4","5","5","ועזריהו בן נתן על הנצבים וזבוד בן נתן כהן רעה המלך׃ ");
INSERT INTO heb_vpl VALUES ("K14_6","012_4_6","1KI","4","6","6","ואחישר על הבית ואדנירם בן עבדא על המס׃ ");
INSERT INTO heb_vpl VALUES ("K14_7","012_4_7","1KI","4","7","7","ולשלמה שנים עשר נצבים על כל ישראל וכלכלו את המלך ואת ביתו חדש בשנה יהיה על אחד לכלכל׃ ");
INSERT INTO heb_vpl VALUES ("K14_8","012_4_8","1KI","4","8","8","ואלה שמותם בן חור בהר אפרים׃ ");
INSERT INTO heb_vpl VALUES ("K14_9","012_4_9","1KI","4","9","9","בן דקר במקץ ובשעלבים ובית שמש ואילון בית חנן׃ ");
INSERT INTO heb_vpl VALUES ("K14_10","012_4_10","1KI","4","10","10","בן חסד בארבות לו שכה וכל ארץ חפר׃ ");
INSERT INTO heb_vpl VALUES ("K14_11","012_4_11","1KI","4","11","11","בן אבינדב כל נפת דאר טפת בת שלמה היתה לו לאשה׃ ");
INSERT INTO heb_vpl VALUES ("K14_12","012_4_12","1KI","4","12","12","בענא בן אחילוד תענך ומגדו וכל בית שאן אשר אצל צרתנה מתחת ליזרעאל מבית שאן עד אבל מחולה עד מעבר ליקמעם׃ ");
INSERT INTO heb_vpl VALUES ("K14_13","012_4_13","1KI","4","13","13","בן גבר ברמת גלעד לו חות יאיר בן מנשה אשר בגלעד לו חבל ארגב אשר בבשן ששים ערים גדלות חומה ובריח נחשת׃ ");
INSERT INTO heb_vpl VALUES ("K14_14","012_4_14","1KI","4","14","14","אחינדב בן עדא מחנימה׃ ");
INSERT INTO heb_vpl VALUES ("K14_15","012_4_15","1KI","4","15","15","אחימעץ בנפתלי גם הוא לקח את בשמת בת שלמה לאשה׃ ");
INSERT INTO heb_vpl VALUES ("K14_16","012_4_16","1KI","4","16","16","בענא בן חושי באשר ובעלות׃ ");
INSERT INTO heb_vpl VALUES ("K14_17","012_4_17","1KI","4","17","17","יהושפט בן פרוח ביששכר׃ ");
INSERT INTO heb_vpl VALUES ("K14_18","012_4_18","1KI","4","18","18","שמעי בן אלא בבנימן׃ ");
INSERT INTO heb_vpl VALUES ("K14_19","012_4_19","1KI","4","19","19","גבר בן ארי בארץ גלעד ארץ סיחון מלך האמרי ועג מלך הבשן ונציב אחד אשר בארץ׃ ");
INSERT INTO heb_vpl VALUES ("K14_20","012_4_20","1KI","4","20","20","יהודה וישראל רבים כחול אשר על הים לרב אכלים ושתים ושמחים׃ ");
INSERT INTO heb_vpl VALUES ("K14_21","012_4_21","1KI","4","21","21","ושלמה היה מושל בכל הממלכות מן הנהר ארץ פלשתים ועד גבול מצרים מגשים מנחה ועבדים את שלמה כל ימי חייו׃ ");
INSERT INTO heb_vpl VALUES ("K14_22","012_4_22","1KI","4","22","22","ויהי לחם שלמה ליום אחד שלשים כר סלת וששים כר קמח׃ ");
INSERT INTO heb_vpl VALUES ("K14_23","012_4_23","1KI","4","23","23","עשרה בקר בראים ועשרים בקר רעי ומאה צאן לבד מאיל וצבי ויחמור וברברים אבוסים׃ ");
INSERT INTO heb_vpl VALUES ("K14_24","012_4_24","1KI","4","24","24","כי הוא רדה בכל עבר הנהר מתפסח ועד עזה בכל מלכי עבר הנהר ושלום היה לו מכל עבריו מסביב׃ ");
INSERT INTO heb_vpl VALUES ("K14_25","012_4_25","1KI","4","25","25","וישב יהודה וישראל לבטח איש תחת גפנו ותחת תאנתו מדן ועד באר שבע כל ימי שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K14_26","012_4_26","1KI","4","26","26","ויהי לשלמה ארבעים אלף ארות סוסים למרכבו ושנים עשר אלף פרשים׃ ");
INSERT INTO heb_vpl VALUES ("K14_27","012_4_27","1KI","4","27","27","וכלכלו הנצבים האלה את המלך שלמה ואת כל הקרב אל שלחן המלך שלמה איש חדשו לא יעדרו דבר׃ ");
INSERT INTO heb_vpl VALUES ("K14_28","012_4_28","1KI","4","28","28","והשערים והתבן לסוסים ולרכש יבאו אל המקום אשר יהיה שם איש כמשפטו׃ ");
INSERT INTO heb_vpl VALUES ("K14_29","012_4_29","1KI","4","29","29","ויתן אלהים חכמה לשלמה ותבונה הרבה מאד ורחב לב כחול אשר על שפת הים׃ ");
INSERT INTO heb_vpl VALUES ("K14_30","012_4_30","1KI","4","30","30","ותרב חכמת שלמה מחכמת כל בני קדם ומכל חכמת מצרים׃ ");
INSERT INTO heb_vpl VALUES ("K14_31","012_4_31","1KI","4","31","31","ויחכם מכל האדם מאיתן האזרחי והימן וכלכל ודרדע בני מחול ויהי שמו בכל הגוים סביב׃ ");
INSERT INTO heb_vpl VALUES ("K14_32","012_4_32","1KI","4","32","32","וידבר שלשת אלפים משל ויהי שירו חמשה ואלף׃ ");
INSERT INTO heb_vpl VALUES ("K14_33","012_4_33","1KI","4","33","33","וידבר על העצים מן הארז אשר בלבנון ועד האזוב אשר יצא בקיר וידבר על הבהמה ועל העוף ועל הרמש ועל הדגים׃ ");
INSERT INTO heb_vpl VALUES ("K14_34","012_4_34","1KI","4","34","34","ויבאו מכל העמים לשמע את חכמת שלמה מאת כל מלכי הארץ אשר שמעו את חכמתו׃ ");
INSERT INTO heb_vpl VALUES ("K15_1","012_5_1","1KI","5","1","1","וישלח חירם מלך צור את עבדיו אל שלמה כי שמע כי אתו משחו למלך תחת אביהו כי אהב היה חירם לדוד כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("K15_2","012_5_2","1KI","5","2","2","וישלח שלמה אל חירם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K15_3","012_5_3","1KI","5","3","3","אתה ידעת את דוד אבי כי לא יכל לבנות בית לשם יהוה אלהיו מפני המלחמה אשר סבבהו עד תת יהוה אתם תחת כפות רגלו׃ ");
INSERT INTO heb_vpl VALUES ("K15_4","012_5_4","1KI","5","4","4","ועתה הניח יהוה אלהי לי מסביב אין שטן ואין פגע רע׃ ");
INSERT INTO heb_vpl VALUES ("K15_5","012_5_5","1KI","5","5","5","והנני אמר לבנות בית לשם יהוה אלהי כאשר דבר יהוה אל דוד אבי לאמר בנך אשר אתן תחתיך על כסאך הוא יבנה הבית לשמי׃ ");
INSERT INTO heb_vpl VALUES ("K15_6","012_5_6","1KI","5","6","6","ועתה צוה ויכרתו לי ארזים מן הלבנון ועבדי יהיו עם עבדיך ושכר עבדיך אתן לך ככל אשר תאמר כי אתה ידעת כי אין בנו איש ידע לכרת עצים כצדנים׃ ");
INSERT INTO heb_vpl VALUES ("K15_7","012_5_7","1KI","5","7","7","ויהי כשמע חירם את דברי שלמה וישמח מאד ויאמר ברוך יהוה היום אשר נתן לדוד בן חכם על העם הרב הזה׃ ");
INSERT INTO heb_vpl VALUES ("K15_8","012_5_8","1KI","5","8","8","וישלח חירם אל שלמה לאמר שמעתי את אשר שלחת אלי אני אעשה את כל חפצך בעצי ארזים ובעצי ברושים׃ ");
INSERT INTO heb_vpl VALUES ("K15_9","012_5_9","1KI","5","9","9","עבדי ירדו מן הלבנון ימה ואני אשימם דברות בים עד המקום אשר תשלח אלי ונפצתים שם ואתה תשא ואתה תעשה את חפצי לתת לחם ביתי׃ ");
INSERT INTO heb_vpl VALUES ("K15_10","012_5_10","1KI","5","10","10","ויהי חירום נתן לשלמה עצי ארזים ועצי ברושים כל חפצו׃ ");
INSERT INTO heb_vpl VALUES ("K15_11","012_5_11","1KI","5","11","11","ושלמה נתן לחירם עשרים אלף כר חטים מכלת לביתו ועשרים כר שמן כתית כה יתן שלמה לחירם שנה בשנה׃ ");
INSERT INTO heb_vpl VALUES ("K15_12","012_5_12","1KI","5","12","12","ויהוה נתן חכמה לשלמה כאשר דבר לו ויהי שלם בין חירם ובין שלמה ויכרתו ברית שניהם׃ ");
INSERT INTO heb_vpl VALUES ("K15_13","012_5_13","1KI","5","13","13","ויעל המלך שלמה מס מכל ישראל ויהי המס שלשים אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("K15_14","012_5_14","1KI","5","14","14","וישלחם לבנונה עשרת אלפים בחדש חליפות חדש יהיו בלבנון שנים חדשים בביתו ואדנירם על המס׃ ");
INSERT INTO heb_vpl VALUES ("K15_15","012_5_15","1KI","5","15","15","ויהי לשלמה שבעים אלף נשא סבל ושמנים אלף חצב בהר׃ ");
INSERT INTO heb_vpl VALUES ("K15_16","012_5_16","1KI","5","16","16","לבד משרי הנצבים לשלמה אשר על המלאכה שלשת אלפים ושלש מאות הרדים בעם העשים במלאכה׃ ");
INSERT INTO heb_vpl VALUES ("K15_17","012_5_17","1KI","5","17","17","ויצו המלך ויסעו אבנים גדלות אבנים יקרות ליסד הבית אבני גזית׃ ");
INSERT INTO heb_vpl VALUES ("K15_18","012_5_18","1KI","5","18","18","ויפסלו בני שלמה ובני חירום והגבלים ויכינו העצים והאבנים לבנות הבית׃ ");
INSERT INTO heb_vpl VALUES ("K16_1","012_6_1","1KI","6","1","1","ויהי בשמונים שנה וארבע מאות שנה לצאת בני ישראל מארץ מצרים בשנה הרביעית בחדש זו הוא החדש השני למלך שלמה על ישראל ויבן הבית ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("K16_2","012_6_2","1KI","6","2","2","והבית אשר בנה המלך שלמה ליהוה ששים אמה ארכו ועשרים רחבו ושלשים אמה קומתו׃ ");
INSERT INTO heb_vpl VALUES ("K16_3","012_6_3","1KI","6","3","3","והאולם על פני היכל הבית עשרים אמה ארכו על פני רחב הבית עשר באמה רחבו על פני הבית׃ ");
INSERT INTO heb_vpl VALUES ("K16_4","012_6_4","1KI","6","4","4","ויעש לבית חלוני שקפים אטמים׃ ");
INSERT INTO heb_vpl VALUES ("K16_5","012_6_5","1KI","6","5","5","ויבן על קיר הבית יצוע סביב את קירות הבית סביב להיכל ולדביר ויעש צלעות סביב׃ ");
INSERT INTO heb_vpl VALUES ("K16_6","012_6_6","1KI","6","6","6","היצוע התחתנה חמש באמה רחבה והתיכנה שש באמה רחבה והשלישית שבע באמה רחבה כי מגרעות נתן לבית סביב חוצה לבלתי אחז בקירות הבית׃ ");
INSERT INTO heb_vpl VALUES ("K16_7","012_6_7","1KI","6","7","7","והבית בהבנתו אבן שלמה מסע נבנה ומקבות והגרזן כל כלי ברזל לא נשמע בבית בהבנתו׃ ");
INSERT INTO heb_vpl VALUES ("K16_8","012_6_8","1KI","6","8","8","פתח הצלע התיכנה אל כתף הבית הימנית ובלולים יעלו על התיכנה ומן התיכנה אל השלשים׃ ");
INSERT INTO heb_vpl VALUES ("K16_9","012_6_9","1KI","6","9","9","ויבן את הבית ויכלהו ויספן את הבית גבים ושדרת בארזים׃ ");
INSERT INTO heb_vpl VALUES ("K16_10","012_6_10","1KI","6","10","10","ויבן את היצוע על כל הבית חמש אמות קומתו ויאחז את הבית בעצי ארזים׃ ");
INSERT INTO heb_vpl VALUES ("K16_11","012_6_11","1KI","6","11","11","ויהי דבר יהוה אל שלמה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K16_12","012_6_12","1KI","6","12","12","הבית הזה אשר אתה בנה אם תלך בחקתי ואת משפטי תעשה ושמרת את כל מצותי ללכת בהם והקמתי את דברי אתך אשר דברתי אל דוד אביך׃ ");
INSERT INTO heb_vpl VALUES ("K16_13","012_6_13","1KI","6","13","13","ושכנתי בתוך בני ישראל ולא אעזב את עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K16_14","012_6_14","1KI","6","14","14","ויבן שלמה את הבית ויכלהו׃ ");
INSERT INTO heb_vpl VALUES ("K16_15","012_6_15","1KI","6","15","15","ויבן את קירות הבית מביתה בצלעות ארזים מקרקע הבית עד קירות הספן צפה עץ מבית ויצף את קרקע הבית בצלעות ברושים׃ ");
INSERT INTO heb_vpl VALUES ("K16_16","012_6_16","1KI","6","16","16","ויבן את עשרים אמה מירכותי הבית בצלעות ארזים מן הקרקע עד הקירות ויבן לו מבית לדביר לקדש הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("K16_17","012_6_17","1KI","6","17","17","וארבעים באמה היה הבית הוא ההיכל לפני׃ ");
INSERT INTO heb_vpl VALUES ("K16_18","012_6_18","1KI","6","18","18","וארז אל הבית פנימה מקלעת פקעים ופטורי צצים הכל ארז אין אבן נראה׃ ");
INSERT INTO heb_vpl VALUES ("K16_19","012_6_19","1KI","6","19","19","ודביר בתוך הבית מפנימה הכין לתתן שם את ארון ברית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K16_20","012_6_20","1KI","6","20","20","ולפני הדביר עשרים אמה ארך ועשרים אמה רחב ועשרים אמה קומתו ויצפהו זהב סגור ויצף מזבח ארז׃ ");
INSERT INTO heb_vpl VALUES ("K16_21","012_6_21","1KI","6","21","21","ויצף שלמה את הבית מפנימה זהב סגור ויעבר ברתיקות זהב לפני הדביר ויצפהו זהב׃ ");
INSERT INTO heb_vpl VALUES ("K16_22","012_6_22","1KI","6","22","22","ואת כל הבית צפה זהב עד תם כל הבית וכל המזבח אשר לדביר צפה זהב׃ ");
INSERT INTO heb_vpl VALUES ("K16_23","012_6_23","1KI","6","23","23","ויעש בדביר שני כרובים עצי שמן עשר אמות קומתו׃ ");
INSERT INTO heb_vpl VALUES ("K16_24","012_6_24","1KI","6","24","24","וחמש אמות כנף הכרוב האחת וחמש אמות כנף הכרוב השנית עשר אמות מקצות כנפיו ועד קצות כנפיו׃ ");
INSERT INTO heb_vpl VALUES ("K16_25","012_6_25","1KI","6","25","25","ועשר באמה הכרוב השני מדה אחת וקצב אחד לשני הכרבים׃ ");
INSERT INTO heb_vpl VALUES ("K16_26","012_6_26","1KI","6","26","26","קומת הכרוב האחד עשר באמה וכן הכרוב השני׃ ");
INSERT INTO heb_vpl VALUES ("K16_27","012_6_27","1KI","6","27","27","ויתן את הכרובים בתוך הבית הפנימי ויפרשו את כנפי הכרבים ותגע כנף האחד בקיר וכנף הכרוב השני נגעת בקיר השני וכנפיהם אל תוך הבית נגעת כנף אל כנף׃ ");
INSERT INTO heb_vpl VALUES ("K16_28","012_6_28","1KI","6","28","28","ויצף את הכרובים זהב׃ ");
INSERT INTO heb_vpl VALUES ("K16_29","012_6_29","1KI","6","29","29","ואת כל קירות הבית מסב קלע פתוחי מקלעות כרובים ותמרת ופטורי צצים מלפנים ולחיצון׃ ");
INSERT INTO heb_vpl VALUES ("K16_30","012_6_30","1KI","6","30","30","ואת קרקע הבית צפה זהב לפנימה ולחיצון׃ ");
INSERT INTO heb_vpl VALUES ("K16_31","012_6_31","1KI","6","31","31","ואת פתח הדביר עשה דלתות עצי שמן האיל מזוזות חמשית׃ ");
INSERT INTO heb_vpl VALUES ("K16_32","012_6_32","1KI","6","32","32","ושתי דלתות עצי שמן וקלע עליהם מקלעות כרובים ותמרות ופטורי צצים וצפה זהב וירד על הכרובים ועל התמרות את הזהב׃ ");
INSERT INTO heb_vpl VALUES ("K16_33","012_6_33","1KI","6","33","33","וכן עשה לפתח ההיכל מזוזות עצי שמן מאת רבעית׃ ");
INSERT INTO heb_vpl VALUES ("K16_34","012_6_34","1KI","6","34","34","ושתי דלתות עצי ברושים שני צלעים הדלת האחת גלילים ושני קלעים הדלת השנית גלילים׃ ");
INSERT INTO heb_vpl VALUES ("K16_35","012_6_35","1KI","6","35","35","וקלע כרובים ותמרות ופטרי צצים וצפה זהב מישר על המחקה׃ ");
INSERT INTO heb_vpl VALUES ("K16_36","012_6_36","1KI","6","36","36","ויבן את החצר הפנימית שלשה טורי גזית וטור כרתת ארזים׃ ");
INSERT INTO heb_vpl VALUES ("K16_37","012_6_37","1KI","6","37","37","בשנה הרביעית יסד בית יהוה בירח זו׃ ");
INSERT INTO heb_vpl VALUES ("K16_38","012_6_38","1KI","6","38","38","ובשנה האחת עשרה בירח בול הוא החדש השמיני כלה הבית לכל דבריו ולכל משפטו ויבנהו שבע שנים׃ ");
INSERT INTO heb_vpl VALUES ("K17_1","012_7_1","1KI","7","1","1","ואת ביתו בנה שלמה שלש עשרה שנה ויכל את כל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("K17_2","012_7_2","1KI","7","2","2","ויבן את בית יער הלבנון מאה אמה ארכו וחמשים אמה רחבו ושלשים אמה קומתו על ארבעה טורי עמודי ארזים וכרתות ארזים על העמודים׃ ");
INSERT INTO heb_vpl VALUES ("K17_3","012_7_3","1KI","7","3","3","וספן בארז ממעל על הצלעת אשר על העמודים ארבעים וחמשה חמשה עשר הטור׃ ");
INSERT INTO heb_vpl VALUES ("K17_4","012_7_4","1KI","7","4","4","ושקפים שלשה טורים ומחזה אל מחזה שלש פעמים׃ ");
INSERT INTO heb_vpl VALUES ("K17_5","012_7_5","1KI","7","5","5","וכל הפתחים והמזוזות רבעים שקף ומול מחזה אל מחזה שלש פעמים׃ ");
INSERT INTO heb_vpl VALUES ("K17_6","012_7_6","1KI","7","6","6","ואת אולם העמודים עשה חמשים אמה ארכו ושלשים אמה רחבו ואולם על פניהם ועמדים ועב על פניהם׃ ");
INSERT INTO heb_vpl VALUES ("K17_7","012_7_7","1KI","7","7","7","ואולם הכסא אשר ישפט שם אלם המשפט עשה וספון בארז מהקרקע עד הקרקע׃ ");
INSERT INTO heb_vpl VALUES ("K17_8","012_7_8","1KI","7","8","8","וביתו אשר ישב שם חצר האחרת מבית לאולם כמעשה הזה היה ובית יעשה לבת פרעה אשר לקח שלמה כאולם הזה׃ ");
INSERT INTO heb_vpl VALUES ("K17_9","012_7_9","1KI","7","9","9","כל אלה אבנים יקרת כמדת גזית מגררות במגרה מבית ומחוץ וממסד עד הטפחות ומחוץ עד החצר הגדולה׃ ");
INSERT INTO heb_vpl VALUES ("K17_10","012_7_10","1KI","7","10","10","ומיסד אבנים יקרות אבנים גדלות אבני עשר אמות ואבני שמנה אמות׃ ");
INSERT INTO heb_vpl VALUES ("K17_11","012_7_11","1KI","7","11","11","ומלמעלה אבנים יקרות כמדות גזית וארז׃ ");
INSERT INTO heb_vpl VALUES ("K17_12","012_7_12","1KI","7","12","12","וחצר הגדולה סביב שלשה טורים גזית וטור כרתת ארזים ולחצר בית יהוה הפנימית ולאלם הבית׃ ");
INSERT INTO heb_vpl VALUES ("K17_13","012_7_13","1KI","7","13","13","וישלח המלך שלמה ויקח את חירם מצר׃ ");
INSERT INTO heb_vpl VALUES ("K17_14","012_7_14","1KI","7","14","14","בן אשה אלמנה הוא ממטה נפתלי ואביו איש צרי חרש נחשת וימלא את החכמה ואת התבונה ואת הדעת לעשות כל מלאכה בנחשת ויבוא אל המלך שלמה ויעש את כל מלאכתו׃ ");
INSERT INTO heb_vpl VALUES ("K17_15","012_7_15","1KI","7","15","15","ויצר את שני העמודים נחשת שמנה עשרה אמה קומת העמוד האחד וחוט שתים עשרה אמה יסב את העמוד השני׃ ");
INSERT INTO heb_vpl VALUES ("K17_16","012_7_16","1KI","7","16","16","ושתי כתרת עשה לתת על ראשי העמודים מצק נחשת חמש אמות קומת הכתרת האחת וחמש אמות קומת הכתרת השנית׃ ");
INSERT INTO heb_vpl VALUES ("K17_17","012_7_17","1KI","7","17","17","שבכים מעשה שבכה גדלים מעשה שרשרות לכתרת אשר על ראש העמודים שבעה לכתרת האחת ושבעה לכתרת השנית׃ ");
INSERT INTO heb_vpl VALUES ("K17_18","012_7_18","1KI","7","18","18","ויעש את העמודים ושני טורים סביב על השבכה האחת לכסות את הכתרת אשר על ראש הרמנים וכן עשה לכתרת השנית׃ ");
INSERT INTO heb_vpl VALUES ("K17_19","012_7_19","1KI","7","19","19","וכתרת אשר על ראש העמודים מעשה שושן באולם ארבע אמות׃ ");
INSERT INTO heb_vpl VALUES ("K17_20","012_7_20","1KI","7","20","20","וכתרת על שני העמודים גם ממעל מלעמת הבטן אשר לעבר שבכה והרמונים מאתים טרים סביב על הכתרת השנית׃ ");
INSERT INTO heb_vpl VALUES ("K17_21","012_7_21","1KI","7","21","21","ויקם את העמדים לאלם ההיכל ויקם את העמוד הימני ויקרא את שמו יכין ויקם את העמוד השמאלי ויקרא את שמו בעז׃ ");
INSERT INTO heb_vpl VALUES ("K17_22","012_7_22","1KI","7","22","22","ועל ראש העמודים מעשה שושן ותתם מלאכת העמודים׃ ");
INSERT INTO heb_vpl VALUES ("K17_23","012_7_23","1KI","7","23","23","ויעש את הים מוצק עשר באמה משפתו עד שפתו עגל סביב וחמש באמה קומתו וקוה שלשים באמה יסב אתו סביב׃ ");
INSERT INTO heb_vpl VALUES ("K17_24","012_7_24","1KI","7","24","24","ופקעים מתחת לשפתו סביב סבבים אתו עשר באמה מקפים את הים סביב שני טורים הפקעים יצקים ביצקתו׃ ");
INSERT INTO heb_vpl VALUES ("K17_25","012_7_25","1KI","7","25","25","עמד על שני עשר בקר שלשה פנים צפונה ושלשה פנים ימה ושלשה פנים נגבה ושלשה פנים מזרחה והים עליהם מלמעלה וכל אחריהם ביתה׃ ");
INSERT INTO heb_vpl VALUES ("K17_26","012_7_26","1KI","7","26","26","ועביו טפח ושפתו כמעשה שפת כוס פרח שושן אלפים בת יכיל׃ ");
INSERT INTO heb_vpl VALUES ("K17_27","012_7_27","1KI","7","27","27","ויעש את המכנות עשר נחשת ארבע באמה ארך המכונה האחת וארבע באמה רחבה ושלש באמה קומתה׃ ");
INSERT INTO heb_vpl VALUES ("K17_28","012_7_28","1KI","7","28","28","וזה מעשה המכונה מסגרת להם ומסגרת בין השלבים׃ ");
INSERT INTO heb_vpl VALUES ("K17_29","012_7_29","1KI","7","29","29","ועל המסגרות אשר בין השלבים אריות בקר וכרובים ועל השלבים כן ממעל ומתחת לאריות ולבקר ליות מעשה מורד׃ ");
INSERT INTO heb_vpl VALUES ("K17_30","012_7_30","1KI","7","30","30","וארבעה אופני נחשת למכונה האחת וסרני נחשת וארבעה פעמתיו כתפת להם מתחת לכיר הכתפת יצקות מעבר איש ליות׃ ");
INSERT INTO heb_vpl VALUES ("K17_31","012_7_31","1KI","7","31","31","ופיהו מבית לכתרת ומעלה באמה ופיה עגל מעשה כן אמה וחצי האמה וגם על פיה מקלעות ומסגרתיהם מרבעות לא עגלות׃ ");
INSERT INTO heb_vpl VALUES ("K17_32","012_7_32","1KI","7","32","32","וארבעת האופנים למתחת למסגרות וידות האופנים במכונה וקומת האופן האחד אמה וחצי האמה׃ ");
INSERT INTO heb_vpl VALUES ("K17_33","012_7_33","1KI","7","33","33","ומעשה האופנים כמעשה אופן המרכבה ידותם וגביהם וחשקיהם וחשריהם הכל מוצק׃ ");
INSERT INTO heb_vpl VALUES ("K17_34","012_7_34","1KI","7","34","34","וארבע כתפות אל ארבע פנות המכנה האחת מן המכנה כתפיה׃ ");
INSERT INTO heb_vpl VALUES ("K17_35","012_7_35","1KI","7","35","35","ובראש המכונה חצי האמה קומה עגל סביב ועל ראש המכנה ידתיה ומסגרתיה ממנה׃ ");
INSERT INTO heb_vpl VALUES ("K17_36","012_7_36","1KI","7","36","36","ויפתח על הלחת ידתיה ועל ומסגרתיה כרובים אריות ותמרת כמער איש וליות סביב׃ ");
INSERT INTO heb_vpl VALUES ("K17_37","012_7_37","1KI","7","37","37","כזאת עשה את עשר המכנות מוצק אחד מדה אחת קצב אחד לכלהנה׃ ");
INSERT INTO heb_vpl VALUES ("K17_38","012_7_38","1KI","7","38","38","ויעש עשרה כירות נחשת ארבעים בת יכיל הכיור האחד ארבע באמה הכיור האחד כיור אחד על המכנה האחת לעשר המכונות׃ ");
INSERT INTO heb_vpl VALUES ("K17_39","012_7_39","1KI","7","39","39","ויתן את המכנות חמש על כתף הבית מימין וחמש על כתף הבית משמאלו ואת הים נתן מכתף הבית הימנית קדמה ממול נגב׃ ");
INSERT INTO heb_vpl VALUES ("K17_40","012_7_40","1KI","7","40","40","ויעש חירום את הכירות ואת היעים ואת המזרקות ויכל חירם לעשות את כל המלאכה אשר עשה למלך שלמה בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K17_41","012_7_41","1KI","7","41","41","עמדים שנים וגלת הכתרת אשר על ראש העמדים שתים והשבכות שתים לכסות את שתי גלת הכתרת אשר על ראש העמודים׃ ");
INSERT INTO heb_vpl VALUES ("K17_42","012_7_42","1KI","7","42","42","ואת הרמנים ארבע מאות לשתי השבכות שני טורים רמנים לשבכה האחת לכסות את שתי גלת הכתרת אשר על פני העמודים׃ ");
INSERT INTO heb_vpl VALUES ("K17_43","012_7_43","1KI","7","43","43","ואת המכנות עשר ואת הכירת עשרה על המכנות׃ ");
INSERT INTO heb_vpl VALUES ("K17_44","012_7_44","1KI","7","44","44","ואת הים האחד ואת הבקר שנים עשר תחת הים׃ ");
INSERT INTO heb_vpl VALUES ("K17_45","012_7_45","1KI","7","45","45","ואת הסירות ואת היעים ואת המזרקות ואת כל הכלים האהל אשר עשה חירם למלך שלמה בית יהוה נחשת ממרט׃ ");
INSERT INTO heb_vpl VALUES ("K17_46","012_7_46","1KI","7","46","46","בככר הירדן יצקם המלך במעבה האדמה בין סכות ובין צרתן׃ ");
INSERT INTO heb_vpl VALUES ("K17_47","012_7_47","1KI","7","47","47","וינח שלמה את כל הכלים מרב מאד מאד לא נחקר משקל הנחשת׃ ");
INSERT INTO heb_vpl VALUES ("K17_48","012_7_48","1KI","7","48","48","ויעש שלמה את כל הכלים אשר בית יהוה את מזבח הזהב ואת השלחן אשר עליו לחם הפנים זהב׃ ");
INSERT INTO heb_vpl VALUES ("K17_49","012_7_49","1KI","7","49","49","ואת המנרות חמש מימין וחמש משמאול לפני הדביר זהב סגור והפרח והנרת והמלקחים זהב׃ ");
INSERT INTO heb_vpl VALUES ("K17_50","012_7_50","1KI","7","50","50","והספות והמזמרות והמזרקות והכפות והמחתות זהב סגור והפתות לדלתות הבית הפנימי לקדש הקדשים לדלתי הבית להיכל זהב׃ ");
INSERT INTO heb_vpl VALUES ("K17_51","012_7_51","1KI","7","51","51","ותשלם כל המלאכה אשר עשה המלך שלמה בית יהוה ויבא שלמה את קדשי דוד אביו את הכסף ואת הזהב ואת הכלים נתן באצרות בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K18_1","012_8_1","1KI","8","1","1","אז יקהל שלמה את זקני ישראל את כל ראשי המטות נשיאי האבות לבני ישראל אל המלך שלמה ירושלם להעלות את ארון ברית יהוה מעיר דוד היא ציון׃ ");
INSERT INTO heb_vpl VALUES ("K18_2","012_8_2","1KI","8","2","2","ויקהלו אל המלך שלמה כל איש ישראל בירח האתנים בחג הוא החדש השביעי׃ ");
INSERT INTO heb_vpl VALUES ("K18_3","012_8_3","1KI","8","3","3","ויבאו כל זקני ישראל וישאו הכהנים את הארון׃ ");
INSERT INTO heb_vpl VALUES ("K18_4","012_8_4","1KI","8","4","4","ויעלו את ארון יהוה ואת אהל מועד ואת כל כלי הקדש אשר באהל ויעלו אתם הכהנים והלוים׃ ");
INSERT INTO heb_vpl VALUES ("K18_5","012_8_5","1KI","8","5","5","והמלך שלמה וכל עדת ישראל הנועדים עליו אתו לפני הארון מזבחים צאן ובקר אשר לא יספרו ולא ימנו מרב׃ ");
INSERT INTO heb_vpl VALUES ("K18_6","012_8_6","1KI","8","6","6","ויבאו הכהנים את ארון ברית יהוה אל מקומו אל דביר הבית אל קדש הקדשים אל תחת כנפי הכרובים׃ ");
INSERT INTO heb_vpl VALUES ("K18_7","012_8_7","1KI","8","7","7","כי הכרובים פרשים כנפים אל מקום הארון ויסכו הכרבים על הארון ועל בדיו מלמעלה׃ ");
INSERT INTO heb_vpl VALUES ("K18_8","012_8_8","1KI","8","8","8","ויארכו הבדים ויראו ראשי הבדים מן הקדש על פני הדביר ולא יראו החוצה ויהיו שם עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K18_9","012_8_9","1KI","8","9","9","אין בארון רק שני לחות האבנים אשר הנח שם משה בחרב אשר כרת יהוה עם בני ישראל בצאתם מארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("K18_10","012_8_10","1KI","8","10","10","ויהי בצאת הכהנים מן הקדש והענן מלא את בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K18_11","012_8_11","1KI","8","11","11","ולא יכלו הכהנים לעמד לשרת מפני הענן כי מלא כבוד יהוה את בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K18_12","012_8_12","1KI","8","12","12","אז אמר שלמה יהוה אמר לשכן בערפל׃ ");
INSERT INTO heb_vpl VALUES ("K18_13","012_8_13","1KI","8","13","13","בנה בניתי בית זבל לך מכון לשבתך עולמים׃ ");
INSERT INTO heb_vpl VALUES ("K18_14","012_8_14","1KI","8","14","14","ויסב המלך את פניו ויברך את כל קהל ישראל וכל קהל ישראל עמד׃ ");
INSERT INTO heb_vpl VALUES ("K18_15","012_8_15","1KI","8","15","15","ויאמר ברוך יהוה אלהי ישראל אשר דבר בפיו את דוד אבי ובידו מלא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K18_16","012_8_16","1KI","8","16","16","מן היום אשר הוצאתי את עמי את ישראל ממצרים לא בחרתי בעיר מכל שבטי ישראל לבנות בית להיות שמי שם ואבחר בדוד להיות על עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K18_17","012_8_17","1KI","8","17","17","ויהי עם לבב דוד אבי לבנות בית לשם יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K18_18","012_8_18","1KI","8","18","18","ויאמר יהוה אל דוד אבי יען אשר היה עם לבבך לבנות בית לשמי הטיבת כי היה עם לבבך׃ ");
INSERT INTO heb_vpl VALUES ("K18_19","012_8_19","1KI","8","19","19","רק אתה לא תבנה הבית כי אם בנך היצא מחלציך הוא יבנה הבית לשמי׃ ");
INSERT INTO heb_vpl VALUES ("K18_20","012_8_20","1KI","8","20","20","ויקם יהוה את דברו אשר דבר ואקם תחת דוד אבי ואשב על כסא ישראל כאשר דבר יהוה ואבנה הבית לשם יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K18_21","012_8_21","1KI","8","21","21","ואשם שם מקום לארון אשר שם ברית יהוה אשר כרת עם אבתינו בהוציאו אתם מארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("K18_22","012_8_22","1KI","8","22","22","ויעמד שלמה לפני מזבח יהוה נגד כל קהל ישראל ויפרש כפיו השמים׃ ");
INSERT INTO heb_vpl VALUES ("K18_23","012_8_23","1KI","8","23","23","ויאמר יהוה אלהי ישראל אין כמוך אלהים בשמים ממעל ועל הארץ מתחת שמר הברית והחסד לעבדיך ההלכים לפניך בכל לבם׃ ");
INSERT INTO heb_vpl VALUES ("K18_24","012_8_24","1KI","8","24","24","אשר שמרת לעבדך דוד אבי את אשר דברת לו ותדבר בפיך ובידך מלאת כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K18_25","012_8_25","1KI","8","25","25","ועתה יהוה אלהי ישראל שמר לעבדך דוד אבי את אשר דברת לו לאמר לא יכרת לך איש מלפני ישב על כסא ישראל רק אם ישמרו בניך את דרכם ללכת לפני כאשר הלכת לפני׃ ");
INSERT INTO heb_vpl VALUES ("K18_26","012_8_26","1KI","8","26","26","ועתה אלהי ישראל יאמן נא דבריך אשר דברת לעבדך דוד אבי׃ ");
INSERT INTO heb_vpl VALUES ("K18_27","012_8_27","1KI","8","27","27","כי האמנם ישב אלהים על הארץ הנה השמים ושמי השמים לא יכלכלוך אף כי הבית הזה אשר בניתי׃ ");
INSERT INTO heb_vpl VALUES ("K18_28","012_8_28","1KI","8","28","28","ופנית אל תפלת עבדך ואל תחנתו יהוה אלהי לשמע אל הרנה ואל התפלה אשר עבדך מתפלל לפניך היום׃ ");
INSERT INTO heb_vpl VALUES ("K18_29","012_8_29","1KI","8","29","29","להיות עינך פתחות אל הבית הזה לילה ויום אל המקום אשר אמרת יהיה שמי שם לשמע אל התפלה אשר יתפלל עבדך אל המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K18_30","012_8_30","1KI","8","30","30","ושמעת אל תחנת עבדך ועמך ישראל אשר יתפללו אל המקום הזה ואתה תשמע אל מקום שבתך אל השמים ושמעת וסלחת׃ ");
INSERT INTO heb_vpl VALUES ("K18_31","012_8_31","1KI","8","31","31","את אשר יחטא איש לרעהו ונשא בו אלה להאלתו ובא אלה לפני מזבחך בבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("K18_32","012_8_32","1KI","8","32","32","ואתה תשמע השמים ועשית ושפטת את עבדיך להרשיע רשע לתת דרכו בראשו ולהצדיק צדיק לתת לו כצדקתו׃ ");
INSERT INTO heb_vpl VALUES ("K18_33","012_8_33","1KI","8","33","33","בהנגף עמך ישראל לפני אויב אשר יחטאו לך ושבו אליך והודו את שמך והתפללו והתחננו אליך בבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("K18_34","012_8_34","1KI","8","34","34","ואתה תשמע השמים וסלחת לחטאת עמך ישראל והשבתם אל האדמה אשר נתת לאבותם׃ ");
INSERT INTO heb_vpl VALUES ("K18_35","012_8_35","1KI","8","35","35","בהעצר שמים ולא יהיה מטר כי יחטאו לך והתפללו אל המקום הזה והודו את שמך ומחטאתם ישובון כי תענם׃ ");
INSERT INTO heb_vpl VALUES ("K18_36","012_8_36","1KI","8","36","36","ואתה תשמע השמים וסלחת לחטאת עבדיך ועמך ישראל כי תורם את הדרך הטובה אשר ילכו בה ונתתה מטר על ארצך אשר נתתה לעמך לנחלה׃ ");
INSERT INTO heb_vpl VALUES ("K18_37","012_8_37","1KI","8","37","37","רעב כי יהיה בארץ דבר כי יהיה שדפון ירקון ארבה חסיל כי יהיה כי יצר לו איבו בארץ שעריו כל נגע כל מחלה׃ ");
INSERT INTO heb_vpl VALUES ("K18_38","012_8_38","1KI","8","38","38","כל תפלה כל תחנה אשר תהיה לכל האדם לכל עמך ישראל אשר ידעון איש נגע לבבו ופרש כפיו אל הבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("K18_39","012_8_39","1KI","8","39","39","ואתה תשמע השמים מכון שבתך וסלחת ועשית ונתת לאיש ככל דרכיו אשר תדע את לבבו כי אתה ידעת לבדך את לבב כל בני האדם׃ ");
INSERT INTO heb_vpl VALUES ("K18_40","012_8_40","1KI","8","40","40","למען יראוך כל הימים אשר הם חיים על פני האדמה אשר נתתה לאבתינו׃ ");
INSERT INTO heb_vpl VALUES ("K18_41","012_8_41","1KI","8","41","41","וגם אל הנכרי אשר לא מעמך ישראל הוא ובא מארץ רחוקה למען שמך׃ ");
INSERT INTO heb_vpl VALUES ("K18_42","012_8_42","1KI","8","42","42","כי ישמעון את שמך הגדול ואת ידך החזקה וזרעך הנטויה ובא והתפלל אל הבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("K18_43","012_8_43","1KI","8","43","43","אתה תשמע השמים מכון שבתך ועשית ככל אשר יקרא אליך הנכרי למען ידעון כל עמי הארץ את שמך ליראה אתך כעמך ישראל ולדעת כי שמך נקרא על הבית הזה אשר בניתי׃ ");
INSERT INTO heb_vpl VALUES ("K18_44","012_8_44","1KI","8","44","44","כי יצא עמך למלחמה על איבו בדרך אשר תשלחם והתפללו אל יהוה דרך העיר אשר בחרת בה והבית אשר בנתי לשמך׃ ");
INSERT INTO heb_vpl VALUES ("K18_45","012_8_45","1KI","8","45","45","ושמעת השמים את תפלתם ואת תחנתם ועשית משפטם׃ ");
INSERT INTO heb_vpl VALUES ("K18_46","012_8_46","1KI","8","46","46","כי יחטאו לך כי אין אדם אשר לא יחטא ואנפת בם ונתתם לפני אויב ושבום שביהם אל ארץ האויב רחוקה או קרובה׃ ");
INSERT INTO heb_vpl VALUES ("K18_47","012_8_47","1KI","8","47","47","והשיבו אל לבם בארץ אשר נשבו שם ושבו והתחננו אליך בארץ שביהם לאמר חטאנו והעוינו רשענו׃ ");
INSERT INTO heb_vpl VALUES ("K18_48","012_8_48","1KI","8","48","48","ושבו אליך בכל לבבם ובכל נפשם בארץ איביהם אשר שבו אתם והתפללו אליך דרך ארצם אשר נתתה לאבותם העיר אשר בחרת והבית אשר בנית לשמך׃ ");
INSERT INTO heb_vpl VALUES ("K18_49","012_8_49","1KI","8","49","49","ושמעת השמים מכון שבתך את תפלתם ואת תחנתם ועשית משפטם׃ ");
INSERT INTO heb_vpl VALUES ("K18_50","012_8_50","1KI","8","50","50","וסלחת לעמך אשר חטאו לך ולכל פשעיהם אשר פשעו בך ונתתם לרחמים לפני שביהם ורחמום׃ ");
INSERT INTO heb_vpl VALUES ("K18_51","012_8_51","1KI","8","51","51","כי עמך ונחלתך הם אשר הוצאת ממצרים מתוך כור הברזל׃ ");
INSERT INTO heb_vpl VALUES ("K18_52","012_8_52","1KI","8","52","52","להיות עיניך פתחות אל תחנת עבדך ואל תחנת עמך ישראל לשמע אליהם בכל קראם אליך׃ ");
INSERT INTO heb_vpl VALUES ("K18_53","012_8_53","1KI","8","53","53","כי אתה הבדלתם לך לנחלה מכל עמי הארץ כאשר דברת ביד משה עבדך בהוציאך את אבתינו ממצרים אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K18_54","012_8_54","1KI","8","54","54","ויהי ככלות שלמה להתפלל אל יהוה את כל התפלה והתחנה הזאת קם מלפני מזבח יהוה מכרע על ברכיו וכפיו פרשות השמים׃ ");
INSERT INTO heb_vpl VALUES ("K18_55","012_8_55","1KI","8","55","55","ויעמד ויברך את כל קהל ישראל קול גדול לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K18_56","012_8_56","1KI","8","56","56","ברוך יהוה אשר נתן מנוחה לעמו ישראל ככל אשר דבר לא נפל דבר אחד מכל דברו הטוב אשר דבר ביד משה עבדו׃ ");
INSERT INTO heb_vpl VALUES ("K18_57","012_8_57","1KI","8","57","57","יהי יהוה אלהינו עמנו כאשר היה עם אבתינו אל יעזבנו ואל יטשנו׃ ");
INSERT INTO heb_vpl VALUES ("K18_58","012_8_58","1KI","8","58","58","להטות לבבנו אליו ללכת בכל דרכיו ולשמר מצותיו וחקיו ומשפטיו אשר צוה את אבתינו׃ ");
INSERT INTO heb_vpl VALUES ("K18_59","012_8_59","1KI","8","59","59","ויהיו דברי אלה אשר התחננתי לפני יהוה קרבים אל יהוה אלהינו יומם ולילה לעשות משפט עבדו ומשפט עמו ישראל דבר יום ביומו׃ ");
INSERT INTO heb_vpl VALUES ("K18_60","012_8_60","1KI","8","60","60","למען דעת כל עמי הארץ כי יהוה הוא האלהים אין עוד׃ ");
INSERT INTO heb_vpl VALUES ("K18_61","012_8_61","1KI","8","61","61","והיה לבבכם שלם עם יהוה אלהינו ללכת בחקיו ולשמר מצותיו כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K18_62","012_8_62","1KI","8","62","62","והמלך וכל ישראל עמו זבחים זבח לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K18_63","012_8_63","1KI","8","63","63","ויזבח שלמה את זבח השלמים אשר זבח ליהוה בקר עשרים ושנים אלף וצאן מאה ועשרים אלף ויחנכו את בית יהוה המלך וכל בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K18_64","012_8_64","1KI","8","64","64","ביום ההוא קדש המלך את תוך החצר אשר לפני בית יהוה כי עשה שם את העלה ואת המנחה ואת חלבי השלמים כי מזבח הנחשת אשר לפני יהוה קטן מהכיל את העלה ואת המנחה ואת חלבי השלמים׃ ");
INSERT INTO heb_vpl VALUES ("K18_65","012_8_65","1KI","8","65","65","ויעש שלמה בעת ההיא את החג וכל ישראל עמו קהל גדול מלבוא חמת עד נחל מצרים לפני יהוה אלהינו שבעת ימים ושבעת ימים ארבעה עשר יום׃ ");
INSERT INTO heb_vpl VALUES ("K18_66","012_8_66","1KI","8","66","66","ביום השמיני שלח את העם ויברכו את המלך וילכו לאהליהם שמחים וטובי לב על כל הטובה אשר עשה יהוה לדוד עבדו ולישראל עמו׃ ");
INSERT INTO heb_vpl VALUES ("K19_1","012_9_1","1KI","9","1","1","ויהי ככלות שלמה לבנות את בית יהוה ואת בית המלך ואת כל חשק שלמה אשר חפץ לעשות׃ ");
INSERT INTO heb_vpl VALUES ("K19_2","012_9_2","1KI","9","2","2","וירא יהוה אל שלמה שנית כאשר נראה אליו בגבעון׃ ");
INSERT INTO heb_vpl VALUES ("K19_3","012_9_3","1KI","9","3","3","ויאמר יהוה אליו שמעתי את תפלתך ואת תחנתך אשר התחננתה לפני הקדשתי את הבית הזה אשר בנתה לשום שמי שם עד עולם והיו עיני ולבי שם כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("K19_4","012_9_4","1KI","9","4","4","ואתה אם תלך לפני כאשר הלך דוד אביך בתם לבב ובישר לעשות ככל אשר צויתיך חקי ומשפטי תשמר׃ ");
INSERT INTO heb_vpl VALUES ("K19_5","012_9_5","1KI","9","5","5","והקמתי את כסא ממלכתך על ישראל לעלם כאשר דברתי על דוד אביך לאמר לא יכרת לך איש מעל כסא ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K19_6","012_9_6","1KI","9","6","6","אם שוב תשבון אתם ובניכם מאחרי ולא תשמרו מצותי חקתי אשר נתתי לפניכם והלכתם ועבדתם אלהים אחרים והשתחויתם להם׃ ");
INSERT INTO heb_vpl VALUES ("K19_7","012_9_7","1KI","9","7","7","והכרתי את ישראל מעל פני האדמה אשר נתתי להם ואת הבית אשר הקדשתי לשמי אשלח מעל פני והיה ישראל למשל ולשנינה בכל העמים׃ ");
INSERT INTO heb_vpl VALUES ("K19_8","012_9_8","1KI","9","8","8","והבית הזה יהיה עליון כל עבר עליו ישם ושרק ואמרו על מה עשה יהוה ככה לארץ הזאת ולבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("K19_9","012_9_9","1KI","9","9","9","ואמרו על אשר עזבו את יהוה אלהיהם אשר הוציא את אבתם מארץ מצרים ויחזקו באלהים אחרים וישתחו להם ויעבדם על כן הביא יהוה עליהם את כל הרעה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("K19_10","012_9_10","1KI","9","10","10","ויהי מקצה עשרים שנה אשר בנה שלמה את שני הבתים את בית יהוה ואת בית המלך׃ ");
INSERT INTO heb_vpl VALUES ("K19_11","012_9_11","1KI","9","11","11","חירם מלך צר נשא את שלמה בעצי ארזים ובעצי ברושים ובזהב לכל חפצו אז יתן המלך שלמה לחירם עשרים עיר בארץ הגליל׃ ");
INSERT INTO heb_vpl VALUES ("K19_12","012_9_12","1KI","9","12","12","ויצא חירם מצר לראות את הערים אשר נתן לו שלמה ולא ישרו בעיניו׃ ");
INSERT INTO heb_vpl VALUES ("K19_13","012_9_13","1KI","9","13","13","ויאמר מה הערים האלה אשר נתתה לי אחי ויקרא להם ארץ כבול עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K19_14","012_9_14","1KI","9","14","14","וישלח חירם למלך מאה ועשרים ככר זהב׃ ");
INSERT INTO heb_vpl VALUES ("K19_15","012_9_15","1KI","9","15","15","וזה דבר המס אשר העלה המלך שלמה לבנות את בית יהוה ואת ביתו ואת המלוא ואת חומת ירושלם ואת חצר ואת מגדו ואת גזר׃ ");
INSERT INTO heb_vpl VALUES ("K19_16","012_9_16","1KI","9","16","16","פרעה מלך מצרים עלה וילכד את גזר וישרפה באש ואת הכנעני הישב בעיר הרג ויתנה שלחים לבתו אשת שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K19_17","012_9_17","1KI","9","17","17","ויבן שלמה את גזר ואת בית חרן תחתון׃ ");
INSERT INTO heb_vpl VALUES ("K19_18","012_9_18","1KI","9","18","18","ואת בעלת ואת תמר במדבר בארץ׃ ");
INSERT INTO heb_vpl VALUES ("K19_19","012_9_19","1KI","9","19","19","ואת כל ערי המסכנות אשר היו לשלמה ואת ערי הרכב ואת ערי הפרשים ואת חשק שלמה אשר חשק לבנות בירושלם ובלבנון ובכל ארץ ממשלתו׃ ");
INSERT INTO heb_vpl VALUES ("K19_20","012_9_20","1KI","9","20","20","כל העם הנותר מן האמרי החתי הפרזי החוי והיבוסי אשר לא מבני ישראל המה׃ ");
INSERT INTO heb_vpl VALUES ("K19_21","012_9_21","1KI","9","21","21","בניהם אשר נתרו אחריהם בארץ אשר לא יכלו בני ישראל להחרימם ויעלם שלמה למס עבד עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K19_22","012_9_22","1KI","9","22","22","ומבני ישראל לא נתן שלמה עבד כי הם אנשי המלחמה ועבדיו ושריו ושלשיו ושרי רכבו ופרשיו׃ ");
INSERT INTO heb_vpl VALUES ("K19_23","012_9_23","1KI","9","23","23","אלה שרי הנצבים אשר על המלאכה לשלמה חמשים וחמש מאות הרדים בעם העשים במלאכה׃ ");
INSERT INTO heb_vpl VALUES ("K19_24","012_9_24","1KI","9","24","24","אך בת פרעה עלתה מעיר דוד אל ביתה אשר בנה לה אז בנה את המלוא׃ ");
INSERT INTO heb_vpl VALUES ("K19_25","012_9_25","1KI","9","25","25","והעלה שלמה שלש פעמים בשנה עלות ושלמים על המזבח אשר בנה ליהוה והקטיר אתו אשר לפני יהוה ושלם את הבית׃ ");
INSERT INTO heb_vpl VALUES ("K19_26","012_9_26","1KI","9","26","26","ואני עשה המלך שלמה בעציון גבר אשר את אלות על שפת ים סוף בארץ אדום׃ ");
INSERT INTO heb_vpl VALUES ("K19_27","012_9_27","1KI","9","27","27","וישלח חירם באני את עבדיו אנשי אניות ידעי הים עם עבדי שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K19_28","012_9_28","1KI","9","28","28","ויבאו אופירה ויקחו משם זהב ארבע מאות ועשרים ככר ויבאו אל המלך שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K110_1","012_10_1","1KI","10","1","1","ומלכת שבא שמעת את שמע שלמה לשם יהוה ותבא לנסתו בחידות׃ ");
INSERT INTO heb_vpl VALUES ("K110_2","012_10_2","1KI","10","2","2","ותבא ירושלמה בחיל כבד מאד גמלים נשאים בשמים וזהב רב מאד ואבן יקרה ותבא אל שלמה ותדבר אליו את כל אשר היה עם לבבה׃ ");
INSERT INTO heb_vpl VALUES ("K110_3","012_10_3","1KI","10","3","3","ויגד לה שלמה את כל דבריה לא היה דבר נעלם מן המלך אשר לא הגיד לה׃ ");
INSERT INTO heb_vpl VALUES ("K110_4","012_10_4","1KI","10","4","4","ותרא מלכת שבא את כל חכמת שלמה והבית אשר בנה׃ ");
INSERT INTO heb_vpl VALUES ("K110_5","012_10_5","1KI","10","5","5","ומאכל שלחנו ומושב עבדיו ומעמד משרתו ומלבשיהם ומשקיו ועלתו אשר יעלה בית יהוה ולא היה בה עוד רוח׃ ");
INSERT INTO heb_vpl VALUES ("K110_6","012_10_6","1KI","10","6","6","ותאמר אל המלך אמת היה הדבר אשר שמעתי בארצי על דבריך ועל חכמתך׃ ");
INSERT INTO heb_vpl VALUES ("K110_7","012_10_7","1KI","10","7","7","ולא האמנתי לדברים עד אשר באתי ותראינה עיני והנה לא הגד לי החצי הוספת חכמה וטוב אל השמועה אשר שמעתי׃ ");
INSERT INTO heb_vpl VALUES ("K110_8","012_10_8","1KI","10","8","8","אשרי אנשיך אשרי עבדיך אלה העמדים לפניך תמיד השמעים את חכמתך׃ ");
INSERT INTO heb_vpl VALUES ("K110_9","012_10_9","1KI","10","9","9","יהי יהוה אלהיך ברוך אשר חפץ בך לתתך על כסא ישראל באהבת יהוה את ישראל לעלם וישימך למלך לעשות משפט וצדקה׃ ");
INSERT INTO heb_vpl VALUES ("K110_10","012_10_10","1KI","10","10","10","ותתן למלך מאה ועשרים ככר זהב ובשמים הרבה מאד ואבן יקרה לא בא כבשם ההוא עוד לרב אשר נתנה מלכת שבא למלך שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K110_11","012_10_11","1KI","10","11","11","וגם אני חירם אשר נשא זהב מאופיר הביא מאפיר עצי אלמגים הרבה מאד ואבן יקרה׃ ");
INSERT INTO heb_vpl VALUES ("K110_12","012_10_12","1KI","10","12","12","ויעש המלך את עצי האלמגים מסעד לבית יהוה ולבית המלך וכנרות ונבלים לשרים לא בא כן עצי אלמגים ולא נראה עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K110_13","012_10_13","1KI","10","13","13","והמלך שלמה נתן למלכת שבא את כל חפצה אשר שאלה מלבד אשר נתן לה כיד המלך שלמה ותפן ותלך לארצה היא ועבדיה׃ ");
INSERT INTO heb_vpl VALUES ("K110_14","012_10_14","1KI","10","14","14","ויהי משקל הזהב אשר בא לשלמה בשנה אחת שש מאות ששים ושש ככר זהב׃ ");
INSERT INTO heb_vpl VALUES ("K110_15","012_10_15","1KI","10","15","15","לבד מאנשי התרים ומסחר הרכלים וכל מלכי הערב ופחות הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K110_16","012_10_16","1KI","10","16","16","ויעש המלך שלמה מאתים צנה זהב שחוט שש מאות זהב יעלה על הצנה האחת׃ ");
INSERT INTO heb_vpl VALUES ("K110_17","012_10_17","1KI","10","17","17","ושלש מאות מגנים זהב שחוט שלשת מנים זהב יעלה על המגן האחת ויתנם המלך בית יער הלבנון׃ ");
INSERT INTO heb_vpl VALUES ("K110_18","012_10_18","1KI","10","18","18","ויעש המלך כסא שן גדול ויצפהו זהב מופז׃ ");
INSERT INTO heb_vpl VALUES ("K110_19","012_10_19","1KI","10","19","19","שש מעלות לכסה וראש עגל לכסה מאחריו וידת מזה ומזה אל מקום השבת ושנים אריות עמדים אצל הידות׃ ");
INSERT INTO heb_vpl VALUES ("K110_20","012_10_20","1KI","10","20","20","ושנים עשר אריים עמדים שם על שש המעלות מזה ומזה לא נעשה כן לכל ממלכות׃ ");
INSERT INTO heb_vpl VALUES ("K110_21","012_10_21","1KI","10","21","21","וכל כלי משקה המלך שלמה זהב וכל כלי בית יער הלבנון זהב סגור אין כסף לא נחשב בימי שלמה למאומה׃ ");
INSERT INTO heb_vpl VALUES ("K110_22","012_10_22","1KI","10","22","22","כי אני תרשיש למלך בים עם אני חירם אחת לשלש שנים תבוא אני תרשיש נשאת זהב וכסף שנהבים וקפים ותכיים׃ ");
INSERT INTO heb_vpl VALUES ("K110_23","012_10_23","1KI","10","23","23","ויגדל המלך שלמה מכל מלכי הארץ לעשר ולחכמה׃ ");
INSERT INTO heb_vpl VALUES ("K110_24","012_10_24","1KI","10","24","24","וכל הארץ מבקשים את פני שלמה לשמע את חכמתו אשר נתן אלהים בלבו׃ ");
INSERT INTO heb_vpl VALUES ("K110_25","012_10_25","1KI","10","25","25","והמה מבאים איש מנחתו כלי כסף וכלי זהב ושלמות ונשק ובשמים סוסים ופרדים דבר שנה בשנה׃ ");
INSERT INTO heb_vpl VALUES ("K110_26","012_10_26","1KI","10","26","26","ויאסף שלמה רכב ופרשים ויהי לו אלף וארבע מאות רכב ושנים עשר אלף פרשים וינחם בערי הרכב ועם המלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K110_27","012_10_27","1KI","10","27","27","ויתן המלך את הכסף בירושלם כאבנים ואת הארזים נתן כשקמים אשר בשפלה לרב׃ ");
INSERT INTO heb_vpl VALUES ("K110_28","012_10_28","1KI","10","28","28","ומוצא הסוסים אשר לשלמה ממצרים ומקוה סחרי המלך יקחו מקוה במחיר׃ ");
INSERT INTO heb_vpl VALUES ("K110_29","012_10_29","1KI","10","29","29","ותעלה ותצא מרכבה ממצרים בשש מאות כסף וסוס בחמשים ומאה וכן לכל מלכי החתים ולמלכי ארם בידם יצאו׃ ");
INSERT INTO heb_vpl VALUES ("K111_1","012_11_1","1KI","11","1","1","והמלך שלמה אהב נשים נכריות רבות ואת בת פרעה מואביות עמניות אדמית צדנית חתית׃ ");
INSERT INTO heb_vpl VALUES ("K111_2","012_11_2","1KI","11","2","2","מן הגוים אשר אמר יהוה אל בני ישראל לא תבאו בהם והם לא יבאו בכם אכן יטו את לבבכם אחרי אלהיהם בהם דבק שלמה לאהבה׃ ");
INSERT INTO heb_vpl VALUES ("K111_3","012_11_3","1KI","11","3","3","ויהי לו נשים שרות שבע מאות ופלגשים שלש מאות ויטו נשיו את לבו׃ ");
INSERT INTO heb_vpl VALUES ("K111_4","012_11_4","1KI","11","4","4","ויהי לעת זקנת שלמה נשיו הטו את לבבו אחרי אלהים אחרים ולא היה לבבו שלם עם יהוה אלהיו כלבב דויד אביו׃ ");
INSERT INTO heb_vpl VALUES ("K111_5","012_11_5","1KI","11","5","5","וילך שלמה אחרי עשתרת אלהי צדנים ואחרי מלכם שקץ עמנים׃ ");
INSERT INTO heb_vpl VALUES ("K111_6","012_11_6","1KI","11","6","6","ויעש שלמה הרע בעיני יהוה ולא מלא אחרי יהוה כדוד אביו׃ ");
INSERT INTO heb_vpl VALUES ("K111_7","012_11_7","1KI","11","7","7","אז יבנה שלמה במה לכמוש שקץ מואב בהר אשר על פני ירושלם ולמלך שקץ בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("K111_8","012_11_8","1KI","11","8","8","וכן עשה לכל נשיו הנכריות מקטירות ומזבחות לאלהיהן׃ ");
INSERT INTO heb_vpl VALUES ("K111_9","012_11_9","1KI","11","9","9","ויתאנף יהוה בשלמה כי נטה לבבו מעם יהוה אלהי ישראל הנראה אליו פעמים׃ ");
INSERT INTO heb_vpl VALUES ("K111_10","012_11_10","1KI","11","10","10","וצוה אליו על הדבר הזה לבלתי לכת אחרי אלהים אחרים ולא שמר את אשר צוה יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K111_11","012_11_11","1KI","11","11","11","ויאמר יהוה לשלמה יען אשר היתה זאת עמך ולא שמרת בריתי וחקתי אשר צויתי עליך קרע אקרע את הממלכה מעליך ונתתיה לעבדך׃ ");
INSERT INTO heb_vpl VALUES ("K111_12","012_11_12","1KI","11","12","12","אך בימיך לא אעשנה למען דוד אביך מיד בנך אקרענה׃ ");
INSERT INTO heb_vpl VALUES ("K111_13","012_11_13","1KI","11","13","13","רק את כל הממלכה לא אקרע שבט אחד אתן לבנך למען דוד עבדי ולמען ירושלם אשר בחרתי׃ ");
INSERT INTO heb_vpl VALUES ("K111_14","012_11_14","1KI","11","14","14","ויקם יהוה שטן לשלמה את הדד האדמי מזרע המלך הוא באדום׃ ");
INSERT INTO heb_vpl VALUES ("K111_15","012_11_15","1KI","11","15","15","ויהי בהיות דוד את אדום בעלות יואב שר הצבא לקבר את החללים ויך כל זכר באדום׃ ");
INSERT INTO heb_vpl VALUES ("K111_16","012_11_16","1KI","11","16","16","כי ששת חדשים ישב שם יואב וכל ישראל עד הכרית כל זכר באדום׃ ");
INSERT INTO heb_vpl VALUES ("K111_17","012_11_17","1KI","11","17","17","ויברח אדד הוא ואנשים אדמיים מעבדי אביו אתו לבוא מצרים והדד נער קטן׃ ");
INSERT INTO heb_vpl VALUES ("K111_18","012_11_18","1KI","11","18","18","ויקמו ממדין ויבאו פארן ויקחו אנשים עמם מפארן ויבאו מצרים אל פרעה מלך מצרים ויתן לו בית ולחם אמר לו וארץ נתן לו׃ ");
INSERT INTO heb_vpl VALUES ("K111_19","012_11_19","1KI","11","19","19","וימצא הדד חן בעיני פרעה מאד ויתן לו אשה את אחות אשתו אחות תחפניס הגבירה׃ ");
INSERT INTO heb_vpl VALUES ("K111_20","012_11_20","1KI","11","20","20","ותלד לו אחות תחפניס את גנבת בנו ותגמלהו תחפנס בתוך בית פרעה ויהי גנבת בית פרעה בתוך בני פרעה׃ ");
INSERT INTO heb_vpl VALUES ("K111_21","012_11_21","1KI","11","21","21","והדד שמע במצרים כי שכב דוד עם אבתיו וכי מת יואב שר הצבא ויאמר הדד אל פרעה שלחני ואלך אל ארצי׃ ");
INSERT INTO heb_vpl VALUES ("K111_22","012_11_22","1KI","11","22","22","ויאמר לו פרעה כי מה אתה חסר עמי והנך מבקש ללכת אל ארצך ויאמר לא כי שלח תשלחני׃ ");
INSERT INTO heb_vpl VALUES ("K111_23","012_11_23","1KI","11","23","23","ויקם אלהים לו שטן את רזון בן אלידע אשר ברח מאת הדדעזר מלך צובה אדניו׃ ");
INSERT INTO heb_vpl VALUES ("K111_24","012_11_24","1KI","11","24","24","ויקבץ עליו אנשים ויהי שר גדוד בהרג דוד אתם וילכו דמשק וישבו בה וימלכו בדמשק׃ ");
INSERT INTO heb_vpl VALUES ("K111_25","012_11_25","1KI","11","25","25","ויהי שטן לישראל כל ימי שלמה ואת הרעה אשר הדד ויקץ בישראל וימלך על ארם׃ ");
INSERT INTO heb_vpl VALUES ("K111_26","012_11_26","1KI","11","26","26","וירבעם בן נבט אפרתי מן הצרדה ושם אמו צרועה אשה אלמנה עבד לשלמה וירם יד במלך׃ ");
INSERT INTO heb_vpl VALUES ("K111_27","012_11_27","1KI","11","27","27","וזה הדבר אשר הרים יד במלך שלמה בנה את המלוא סגר את פרץ עיר דוד אביו׃ ");
INSERT INTO heb_vpl VALUES ("K111_28","012_11_28","1KI","11","28","28","והאיש ירבעם גבור חיל וירא שלמה את הנער כי עשה מלאכה הוא ויפקד אתו לכל סבל בית יוסף׃ ");
INSERT INTO heb_vpl VALUES ("K111_29","012_11_29","1KI","11","29","29","ויהי בעת ההיא וירבעם יצא מירושלם וימצא אתו אחיה השילני הנביא בדרך והוא מתכסה בשלמה חדשה ושניהם לבדם בשדה׃ ");
INSERT INTO heb_vpl VALUES ("K111_30","012_11_30","1KI","11","30","30","ויתפש אחיה בשלמה החדשה אשר עליו ויקרעה שנים עשר קרעים׃ ");
INSERT INTO heb_vpl VALUES ("K111_31","012_11_31","1KI","11","31","31","ויאמר לירבעם קח לך עשרה קרעים כי כה אמר יהוה אלהי ישראל הנני קרע את הממלכה מיד שלמה ונתתי לך את עשרה השבטים׃ ");
INSERT INTO heb_vpl VALUES ("K111_32","012_11_32","1KI","11","32","32","והשבט האחד יהיה לו למען עבדי דוד ולמען ירושלם העיר אשר בחרתי בה מכל שבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K111_33","012_11_33","1KI","11","33","33","יען אשר עזבוני וישתחוו לעשתרת אלהי צדנין לכמוש אלהי מואב ולמלכם אלהי בני עמון ולא הלכו בדרכי לעשות הישר בעיני וחקתי ומשפטי כדוד אביו׃ ");
INSERT INTO heb_vpl VALUES ("K111_34","012_11_34","1KI","11","34","34","ולא אקח את כל הממלכה מידו כי נשיא אשתנו כל ימי חייו למען דוד עבדי אשר בחרתי אתו אשר שמר מצותי וחקתי׃ ");
INSERT INTO heb_vpl VALUES ("K111_35","012_11_35","1KI","11","35","35","ולקחתי המלוכה מיד בנו ונתתיה לך את עשרת השבטים׃ ");
INSERT INTO heb_vpl VALUES ("K111_36","012_11_36","1KI","11","36","36","ולבנו אתן שבט אחד למען היות ניר לדויד עבדי כל הימים לפני בירושלם העיר אשר בחרתי לי לשום שמי שם׃ ");
INSERT INTO heb_vpl VALUES ("K111_37","012_11_37","1KI","11","37","37","ואתך אקח ומלכת בכל אשר תאוה נפשך והיית מלך על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K111_38","012_11_38","1KI","11","38","38","והיה אם תשמע את כל אשר אצוך והלכת בדרכי ועשית הישר בעיני לשמור חקותי ומצותי כאשר עשה דוד עבדי והייתי עמך ובניתי לך בית נאמן כאשר בניתי לדוד ונתתי לך את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K111_39","012_11_39","1KI","11","39","39","ואענה את זרע דוד למען זאת אך לא כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("K111_40","012_11_40","1KI","11","40","40","ויבקש שלמה להמית את ירבעם ויקם ירבעם ויברח מצרים אל שישק מלך מצרים ויהי במצרים עד מות שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K111_41","012_11_41","1KI","11","41","41","ויתר דברי שלמה וכל אשר עשה וחכמתו הלוא הם כתבים על ספר דברי שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K111_42","012_11_42","1KI","11","42","42","והימים אשר מלך שלמה בירושלם על כל ישראל ארבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("K111_43","012_11_43","1KI","11","43","43","וישכב שלמה עם אבתיו ויקבר בעיר דוד אביו וימלך רחבעם בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K112_1","012_12_1","1KI","12","1","1","וילך רחבעם שכם כי שכם בא כל ישראל להמליך אתו׃ ");
INSERT INTO heb_vpl VALUES ("K112_2","012_12_2","1KI","12","2","2","ויהי כשמע ירבעם בן נבט והוא עודנו במצרים אשר ברח מפני המלך שלמה וישב ירבעם במצרים׃ ");
INSERT INTO heb_vpl VALUES ("K112_3","012_12_3","1KI","12","3","3","וישלחו ויקראו לו ויבאו ירבעם וכל קהל ישראל וידברו אל רחבעם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K112_4","012_12_4","1KI","12","4","4","אביך הקשה את עלנו ואתה עתה הקל מעבדת אביך הקשה ומעלו הכבד אשר נתן עלינו ונעבדך׃ ");
INSERT INTO heb_vpl VALUES ("K112_5","012_12_5","1KI","12","5","5","ויאמר אליהם לכו עד שלשה ימים ושובו אלי וילכו העם׃ ");
INSERT INTO heb_vpl VALUES ("K112_6","012_12_6","1KI","12","6","6","ויועץ המלך רחבעם את הזקנים אשר היו עמדים את פני שלמה אביו בהיתו חי לאמר איך אתם נועצים להשיב את העם הזה דבר׃ ");
INSERT INTO heb_vpl VALUES ("K112_7","012_12_7","1KI","12","7","7","וידבר אליו לאמר אם היום תהיה עבד לעם הזה ועבדתם ועניתם ודברת אליהם דברים טובים והיו לך עבדים כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("K112_8","012_12_8","1KI","12","8","8","ויעזב את עצת הזקנים אשר יעצהו ויועץ את הילדים אשר גדלו אתו אשר העמדים לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K112_9","012_12_9","1KI","12","9","9","ויאמר אליהם מה אתם נועצים ונשיב דבר את העם הזה אשר דברו אלי לאמר הקל מן העל אשר נתן אביך עלינו׃ ");
INSERT INTO heb_vpl VALUES ("K112_10","012_12_10","1KI","12","10","10","וידברו אליו הילדים אשר גדלו אתו לאמר כה תאמר לעם הזה אשר דברו אליך לאמר אביך הכביד את עלנו ואתה הקל מעלינו כה תדבר אליהם קטני עבה ממתני אבי׃ ");
INSERT INTO heb_vpl VALUES ("K112_11","012_12_11","1KI","12","11","11","ועתה אבי העמיס עליכם על כבד ואני אוסיף על עלכם אבי יסר אתכם בשוטים ואני איסר אתכם בעקרבים׃ ");
INSERT INTO heb_vpl VALUES ("K112_12","012_12_12","1KI","12","12","12","ויבו ירבעם וכל העם אל רחבעם ביום השלישי כאשר דבר המלך לאמר שובו אלי ביום השלישי׃ ");
INSERT INTO heb_vpl VALUES ("K112_13","012_12_13","1KI","12","13","13","ויען המלך את העם קשה ויעזב את עצת הזקנים אשר יעצהו׃ ");
INSERT INTO heb_vpl VALUES ("K112_14","012_12_14","1KI","12","14","14","וידבר אליהם כעצת הילדים לאמר אבי הכביד את עלכם ואני אסיף על עלכם אבי יסר אתכם בשוטים ואני איסר אתכם בעקרבים׃ ");
INSERT INTO heb_vpl VALUES ("K112_15","012_12_15","1KI","12","15","15","ולא שמע המלך אל העם כי היתה סבה מעם יהוה למען הקים את דברו אשר דבר יהוה ביד אחיה השילני אל ירבעם בן נבט׃ ");
INSERT INTO heb_vpl VALUES ("K112_16","012_12_16","1KI","12","16","16","וירא כל ישראל כי לא שמע המלך אליהם וישבו העם את המלך דבר לאמר מה לנו חלק בדוד ולא נחלה בבן ישי לאהליך ישראל עתה ראה ביתך דוד וילך ישראל לאהליו׃ ");
INSERT INTO heb_vpl VALUES ("K112_17","012_12_17","1KI","12","17","17","ובני ישראל הישבים בערי יהודה וימלך עליהם רחבעם׃ ");
INSERT INTO heb_vpl VALUES ("K112_18","012_12_18","1KI","12","18","18","וישלח המלך רחבעם את אדרם אשר על המס וירגמו כל ישראל בו אבן וימת והמלך רחבעם התאמץ לעלות במרכבה לנוס ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K112_19","012_12_19","1KI","12","19","19","ויפשעו ישראל בבית דוד עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K112_20","012_12_20","1KI","12","20","20","ויהי כשמע כל ישראל כי שב ירבעם וישלחו ויקראו אתו אל העדה וימליכו אתו על כל ישראל לא היה אחרי בית דוד זולתי שבט יהודה לבדו׃ ");
INSERT INTO heb_vpl VALUES ("K112_21","012_12_21","1KI","12","21","21","ויבאו רחבעם ירושלם ויקהל את כל בית יהודה ואת שבט בנימן מאה ושמנים אלף בחור עשה מלחמה להלחם עם בית ישראל להשיב את המלוכה לרחבעם בן שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K112_22","012_12_22","1KI","12","22","22","ויהי דבר האלהים אל שמעיה איש האלהים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K112_23","012_12_23","1KI","12","23","23","אמר אל רחבעם בן שלמה מלך יהודה ואל כל בית יהודה ובנימין ויתר העם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K112_24","012_12_24","1KI","12","24","24","כה אמר יהוה לא תעלו ולא תלחמון עם אחיכם בני ישראל שובו איש לביתו כי מאתי נהיה הדבר הזה וישמעו את דבר יהוה וישבו ללכת כדבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K112_25","012_12_25","1KI","12","25","25","ויבן ירבעם את שכם בהר אפרים וישב בה ויצא משם ויבן את פנואל׃ ");
INSERT INTO heb_vpl VALUES ("K112_26","012_12_26","1KI","12","26","26","ויאמר ירבעם בלבו עתה תשוב הממלכה לבית דוד׃ ");
INSERT INTO heb_vpl VALUES ("K112_27","012_12_27","1KI","12","27","27","אם יעלה העם הזה לעשות זבחים בבית יהוה בירושלם ושב לב העם הזה אל אדניהם אל רחבעם מלך יהודה והרגני ושבו אל רחבעם מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K112_28","012_12_28","1KI","12","28","28","ויועץ המלך ויעש שני עגלי זהב ויאמר אלהם רב לכם מעלות ירושלם הנה אלהיך ישראל אשר העלוך מארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("K112_29","012_12_29","1KI","12","29","29","וישם את האחד בבית אל ואת האחד נתן בדן׃ ");
INSERT INTO heb_vpl VALUES ("K112_30","012_12_30","1KI","12","30","30","ויהי הדבר הזה לחטאת וילכו העם לפני האחד עד דן׃ ");
INSERT INTO heb_vpl VALUES ("K112_31","012_12_31","1KI","12","31","31","ויעש את בית במות ויעש כהנים מקצות העם אשר לא היו מבני לוי׃ ");
INSERT INTO heb_vpl VALUES ("K112_32","012_12_32","1KI","12","32","32","ויעש ירבעם חג בחדש השמיני בחמשה עשר יום לחדש כחג אשר ביהודה ויעל על המזבח כן עשה בבית אל לזבח לעגלים אשר עשה והעמיד בבית אל את כהני הבמות אשר עשה׃ ");
INSERT INTO heb_vpl VALUES ("K112_33","012_12_33","1KI","12","33","33","ויעל על המזבח אשר עשה בבית אל בחמשה עשר יום בחדש השמיני בחדש אשר בדא מלבד ויעש חג לבני ישראל ויעל על המזבח להקטיר׃ ");
INSERT INTO heb_vpl VALUES ("K113_1","012_13_1","1KI","13","1","1","והנה איש אלהים בא מיהודה בדבר יהוה אל בית אל וירבעם עמד על המזבח להקטיר׃ ");
INSERT INTO heb_vpl VALUES ("K113_2","012_13_2","1KI","13","2","2","ויקרא על המזבח בדבר יהוה ויאמר מזבח מזבח כה אמר יהוה הנה בן נולד לבית דוד יאשיהו שמו וזבח עליך את כהני הבמות המקטרים עליך ועצמות אדם ישרפו עליך׃ ");
INSERT INTO heb_vpl VALUES ("K113_3","012_13_3","1KI","13","3","3","ונתן ביום ההוא מופת לאמר זה המופת אשר דבר יהוה הנה המזבח נקרע ונשפך הדשן אשר עליו׃ ");
INSERT INTO heb_vpl VALUES ("K113_4","012_13_4","1KI","13","4","4","ויהי כשמע המלך את דבר איש האלהים אשר קרא על המזבח בבית אל וישלח ירבעם את ידו מעל המזבח לאמר תפשהו ותיבש ידו אשר שלח עליו ולא יכל להשיבה אליו׃ ");
INSERT INTO heb_vpl VALUES ("K113_5","012_13_5","1KI","13","5","5","והמזבח נקרע וישפך הדשן מן המזבח כמופת אשר נתן איש האלהים בדבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K113_6","012_13_6","1KI","13","6","6","ויען המלך ויאמר אל איש האלהים חל נא את פני יהוה אלהיך והתפלל בעדי ותשב ידי אלי ויחל איש האלהים את פני יהוה ותשב יד המלך אליו ותהי כבראשנה׃ ");
INSERT INTO heb_vpl VALUES ("K113_7","012_13_7","1KI","13","7","7","וידבר המלך אל איש האלהים באה אתי הביתה וסעדה ואתנה לך מתת׃ ");
INSERT INTO heb_vpl VALUES ("K113_8","012_13_8","1KI","13","8","8","ויאמר איש האלהים אל המלך אם תתן לי את חצי ביתך לא אבא עמך ולא אכל לחם ולא אשתה מים במקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K113_9","012_13_9","1KI","13","9","9","כי כן צוה אתי בדבר יהוה לאמר לא תאכל לחם ולא תשתה מים ולא תשוב בדרך אשר הלכת׃ ");
INSERT INTO heb_vpl VALUES ("K113_10","012_13_10","1KI","13","10","10","וילך בדרך אחר ולא שב בדרך אשר בא בה אל בית אל׃ ");
INSERT INTO heb_vpl VALUES ("K113_11","012_13_11","1KI","13","11","11","ונביא אחד זקן ישב בבית אל ויבוא בנו ויספר לו את כל המעשה אשר עשה איש האלהים היום בבית אל את הדברים אשר דבר אל המלך ויספרום לאביהם׃ ");
INSERT INTO heb_vpl VALUES ("K113_12","012_13_12","1KI","13","12","12","וידבר אלהם אביהם אי זה הדרך הלך ויראו בניו את הדרך אשר הלך איש האלהים אשר בא מיהודה׃ ");
INSERT INTO heb_vpl VALUES ("K113_13","012_13_13","1KI","13","13","13","ויאמר אל בניו חבשו לי החמור ויחבשו לו החמור וירכב עליו׃ ");
INSERT INTO heb_vpl VALUES ("K113_14","012_13_14","1KI","13","14","14","וילך אחרי איש האלהים וימצאהו ישב תחת האלה ויאמר אליו האתה איש האלהים אשר באת מיהודה ויאמר אני׃ ");
INSERT INTO heb_vpl VALUES ("K113_15","012_13_15","1KI","13","15","15","ויאמר אליו לך אתי הביתה ואכל לחם׃ ");
INSERT INTO heb_vpl VALUES ("K113_16","012_13_16","1KI","13","16","16","ויאמר לא אוכל לשוב אתך ולבוא אתך ולא אכל לחם ולא אשתה אתך מים במקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K113_17","012_13_17","1KI","13","17","17","כי דבר אלי בדבר יהוה לא תאכל לחם ולא תשתה שם מים לא תשוב ללכת בדרך אשר הלכת בה׃ ");
INSERT INTO heb_vpl VALUES ("K113_18","012_13_18","1KI","13","18","18","ויאמר לו גם אני נביא כמוך ומלאך דבר אלי בדבר יהוה לאמר השבהו אתך אל ביתך ויאכל לחם וישת מים כחש לו׃ ");
INSERT INTO heb_vpl VALUES ("K113_19","012_13_19","1KI","13","19","19","וישב אתו ויאכל לחם בביתו וישת מים׃ ");
INSERT INTO heb_vpl VALUES ("K113_20","012_13_20","1KI","13","20","20","ויהי הם ישבים אל השלחן ויהי דבר יהוה אל הנביא אשר השיבו׃ ");
INSERT INTO heb_vpl VALUES ("K113_21","012_13_21","1KI","13","21","21","ויקרא אל איש האלהים אשר בא מיהודה לאמר כה אמר יהוה יען כי מרית פי יהוה ולא שמרת את המצוה אשר צוך יהוה אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("K113_22","012_13_22","1KI","13","22","22","ותשב ותאכל לחם ותשת מים במקום אשר דבר אליך אל תאכל לחם ואל תשת מים לא תבוא נבלתך אל קבר אבתיך׃ ");
INSERT INTO heb_vpl VALUES ("K113_23","012_13_23","1KI","13","23","23","ויהי אחרי אכלו לחם ואחרי שתותו ויחבש לו החמור לנביא אשר השיבו׃ ");
INSERT INTO heb_vpl VALUES ("K113_24","012_13_24","1KI","13","24","24","וילך וימצאהו אריה בדרך וימיתהו ותהי נבלתו משלכת בדרך והחמור עמד אצלה והאריה עמד אצל הנבלה׃ ");
INSERT INTO heb_vpl VALUES ("K113_25","012_13_25","1KI","13","25","25","והנה אנשים עברים ויראו את הנבלה משלכת בדרך ואת האריה עמד אצל הנבלה ויבאו וידברו בעיר אשר הנביא הזקן ישב בה׃ ");
INSERT INTO heb_vpl VALUES ("K113_26","012_13_26","1KI","13","26","26","וישמע הנביא אשר השיבו מן הדרך ויאמר איש האלהים הוא אשר מרה את פי יהוה ויתנהו יהוה לאריה וישברהו וימתהו כדבר יהוה אשר דבר לו׃ ");
INSERT INTO heb_vpl VALUES ("K113_27","012_13_27","1KI","13","27","27","וידבר אל בניו לאמר חבשו לי את החמור ויחבשו׃ ");
INSERT INTO heb_vpl VALUES ("K113_28","012_13_28","1KI","13","28","28","וילך וימצא את נבלתו משלכת בדרך וחמור והאריה עמדים אצל הנבלה לא אכל האריה את הנבלה ולא שבר את החמור׃ ");
INSERT INTO heb_vpl VALUES ("K113_29","012_13_29","1KI","13","29","29","וישא הנביא את נבלת איש האלהים וינחהו אל החמור וישיבהו ויבא אל עיר הנביא הזקן לספד ולקברו׃ ");
INSERT INTO heb_vpl VALUES ("K113_30","012_13_30","1KI","13","30","30","וינח את נבלתו בקברו ויספדו עליו הוי אחי׃ ");
INSERT INTO heb_vpl VALUES ("K113_31","012_13_31","1KI","13","31","31","ויהי אחרי קברו אתו ויאמר אל בניו לאמר במותי וקברתם אתי בקבר אשר איש האלהים קבור בו אצל עצמתיו הניחו את עצמתי׃ ");
INSERT INTO heb_vpl VALUES ("K113_32","012_13_32","1KI","13","32","32","כי היה יהיה הדבר אשר קרא בדבר יהוה על המזבח אשר בבית אל ועל כל בתי הבמות אשר בערי שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K113_33","012_13_33","1KI","13","33","33","אחר הדבר הזה לא שב ירבעם מדרכו הרעה וישב ויעש מקצות העם כהני במות החפץ ימלא את ידו ויהי כהני במות׃ ");
INSERT INTO heb_vpl VALUES ("K113_34","012_13_34","1KI","13","34","34","ויהי בדבר הזה לחטאת בית ירבעם ולהכחיד ולהשמיד מעל פני האדמה׃ ");
INSERT INTO heb_vpl VALUES ("K114_1","012_14_1","1KI","14","1","1","בעת ההיא חלה אביה בן ירבעם׃ ");
INSERT INTO heb_vpl VALUES ("K114_2","012_14_2","1KI","14","2","2","ויאמר ירבעם לאשתו קומי נא והשתנית ולא ידעו כי אתי אשת ירבעם והלכת שלה הנה שם אחיה הנביא הוא דבר עלי למלך על העם הזה׃ ");
INSERT INTO heb_vpl VALUES ("K114_3","012_14_3","1KI","14","3","3","ולקחת בידך עשרה לחם ונקדים ובקבק דבש ובאת אליו הוא יגיד לך מה יהיה לנער׃ ");
INSERT INTO heb_vpl VALUES ("K114_4","012_14_4","1KI","14","4","4","ותעש כן אשת ירבעם ותקם ותלך שלה ותבא בית אחיה ואחיהו לא יכל לראות כי קמו עיניו משיבו׃ ");
INSERT INTO heb_vpl VALUES ("K114_5","012_14_5","1KI","14","5","5","ויהוה אמר אל אחיהו הנה אשת ירבעם באה לדרש דבר מעמך אל בנה כי חלה הוא כזה וכזה תדבר אליה ויהי כבאה והיא מתנכרה׃ ");
INSERT INTO heb_vpl VALUES ("K114_6","012_14_6","1KI","14","6","6","ויהי כשמע אחיהו את קול רגליה באה בפתח ויאמר באי אשת ירבעם למה זה את מתנכרה ואנכי שלוח אליך קשה׃ ");
INSERT INTO heb_vpl VALUES ("K114_7","012_14_7","1KI","14","7","7","לכי אמרי לירבעם כה אמר יהוה אלהי ישראל יען אשר הרימתיך מתוך העם ואתנך נגיד על עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K114_8","012_14_8","1KI","14","8","8","ואקרע את הממלכה מבית דוד ואתנה לך ולא היית כעבדי דוד אשר שמר מצותי ואשר הלך אחרי בכל לבבו לעשות רק הישר בעיני׃ ");
INSERT INTO heb_vpl VALUES ("K114_9","012_14_9","1KI","14","9","9","ותרע לעשות מכל אשר היו לפניך ותלך ותעשה לך אלהים אחרים ומסכות להכעיסני ואתי השלכת אחרי גוך׃ ");
INSERT INTO heb_vpl VALUES ("K114_10","012_14_10","1KI","14","10","10","לכן הנני מביא רעה אל בית ירבעם והכרתי לירבעם משתין בקיר עצור ועזוב בישראל ובערתי אחרי בית ירבעם כאשר יבער הגלל עד תמו׃ ");
INSERT INTO heb_vpl VALUES ("K114_11","012_14_11","1KI","14","11","11","המת לירבעם בעיר יאכלו הכלבים והמת בשדה יאכלו עוף השמים כי יהוה דבר׃ ");
INSERT INTO heb_vpl VALUES ("K114_12","012_14_12","1KI","14","12","12","ואת קומי לכי לביתך בבאה רגליך העירה ומת הילד׃ ");
INSERT INTO heb_vpl VALUES ("K114_13","012_14_13","1KI","14","13","13","וספדו לו כל ישראל וקברו אתו כי זה לבדו יבא לירבעם אל קבר יען נמצא בו דבר טוב אל יהוה אלהי ישראל בבית ירבעם׃ ");
INSERT INTO heb_vpl VALUES ("K114_14","012_14_14","1KI","14","14","14","והקים יהוה לו מלך על ישראל אשר יכרית את בית ירבעם זה היום ומה גם עתה׃ ");
INSERT INTO heb_vpl VALUES ("K114_15","012_14_15","1KI","14","15","15","והכה יהוה את ישראל כאשר ינוד הקנה במים ונתש את ישראל מעל האדמה הטובה הזאת אשר נתן לאבותיהם וזרם מעבר לנהר יען אשר עשו את אשריהם מכעיסים את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K114_16","012_14_16","1KI","14","16","16","ויתן את ישראל בגלל חטאות ירבעם אשר חטא ואשר החטיא את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K114_17","012_14_17","1KI","14","17","17","ותקם אשת ירבעם ותלך ותבא תרצתה היא באה בסף הבית והנער מת׃ ");
INSERT INTO heb_vpl VALUES ("K114_18","012_14_18","1KI","14","18","18","ויקברו אתו ויספדו לו כל ישראל כדבר יהוה אשר דבר ביד עבדו אחיהו הנביא׃ ");
INSERT INTO heb_vpl VALUES ("K114_19","012_14_19","1KI","14","19","19","ויתר דברי ירבעם אשר נלחם ואשר מלך הנם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K114_20","012_14_20","1KI","14","20","20","והימים אשר מלך ירבעם עשרים ושתים שנה וישכב עם אבתיו וימלך נדב בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K114_21","012_14_21","1KI","14","21","21","ורחבעם בן שלמה מלך ביהודה בן ארבעים ואחת שנה רחבעם במלכו ושבע עשרה שנה מלך בירושלם העיר אשר בחר יהוה לשום את שמו שם מכל שבטי ישראל ושם אמו נעמה העמנית׃ ");
INSERT INTO heb_vpl VALUES ("K114_22","012_14_22","1KI","14","22","22","ויעש יהודה הרע בעיני יהוה ויקנאו אתו מכל אשר עשו אבתם בחטאתם אשר חטאו׃ ");
INSERT INTO heb_vpl VALUES ("K114_23","012_14_23","1KI","14","23","23","ויבנו גם המה להם במות ומצבות ואשרים על כל גבעה גבהה ותחת כל עץ רענן׃ ");
INSERT INTO heb_vpl VALUES ("K114_24","012_14_24","1KI","14","24","24","וגם קדש היה בארץ עשו ככל התועבת הגוים אשר הוריש יהוה מפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K114_25","012_14_25","1KI","14","25","25","ויהי בשנה החמישית למלך רחבעם עלה שושק מלך מצרים על ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K114_26","012_14_26","1KI","14","26","26","ויקח את אצרות בית יהוה ואת אוצרות בית המלך ואת הכל לקח ויקח את כל מגני הזהב אשר עשה שלמה׃ ");
INSERT INTO heb_vpl VALUES ("K114_27","012_14_27","1KI","14","27","27","ויעש המלך רחבעם תחתם מגני נחשת והפקיד על יד שרי הרצים השמרים פתח בית המלך׃ ");
INSERT INTO heb_vpl VALUES ("K114_28","012_14_28","1KI","14","28","28","ויהי מדי בא המלך בית יהוה ישאום הרצים והשיבום אל תא הרצים׃ ");
INSERT INTO heb_vpl VALUES ("K114_29","012_14_29","1KI","14","29","29","ויתר דברי רחבעם וכל אשר עשה הלא המה כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K114_30","012_14_30","1KI","14","30","30","ומלחמה היתה בין רחבעם ובין ירבעם כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("K114_31","012_14_31","1KI","14","31","31","וישכב רחבעם עם אבתיו ויקבר עם אבתיו בעיר דוד ושם אמו נעמה העמנית וימלך אבים בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K115_1","012_15_1","1KI","15","1","1","ובשנת שמנה עשרה למלך ירבעם בן נבט מלך אבים על יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K115_2","012_15_2","1KI","15","2","2","שלש שנים מלך בירושלם ושם אמו מעכה בת אבישלום׃ ");
INSERT INTO heb_vpl VALUES ("K115_3","012_15_3","1KI","15","3","3","וילך בכל חטאות אביו אשר עשה לפניו ולא היה לבבו שלם עם יהוה אלהיו כלבב דוד אביו׃ ");
INSERT INTO heb_vpl VALUES ("K115_4","012_15_4","1KI","15","4","4","כי למען דוד נתן יהוה אלהיו לו ניר בירושלם להקים את בנו אחריו ולהעמיד את ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K115_5","012_15_5","1KI","15","5","5","אשר עשה דוד את הישר בעיני יהוה ולא סר מכל אשר צוהו כל ימי חייו רק בדבר אוריה החתי׃ ");
INSERT INTO heb_vpl VALUES ("K115_6","012_15_6","1KI","15","6","6","ומלחמה היתה בין רחבעם ובין ירבעם כל ימי חייו׃ ");
INSERT INTO heb_vpl VALUES ("K115_7","012_15_7","1KI","15","7","7","ויתר דברי אבים וכל אשר עשה הלוא הם כתובים על ספר דברי הימים למלכי יהודה ומלחמה היתה בין אבים ובין ירבעם׃ ");
INSERT INTO heb_vpl VALUES ("K115_8","012_15_8","1KI","15","8","8","וישכב אבים עם אבתיו ויקברו אתו בעיר דוד וימלך אסא בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K115_9","012_15_9","1KI","15","9","9","ובשנת עשרים לירבעם מלך ישראל מלך אסא מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K115_10","012_15_10","1KI","15","10","10","וארבעים ואחת שנה מלך בירושלם ושם אמו מעכה בת אבישלום׃ ");
INSERT INTO heb_vpl VALUES ("K115_11","012_15_11","1KI","15","11","11","ויעש אסא הישר בעיני יהוה כדוד אביו׃ ");
INSERT INTO heb_vpl VALUES ("K115_12","012_15_12","1KI","15","12","12","ויעבר הקדשים מן הארץ ויסר את כל הגללים אשר עשו אבתיו׃ ");
INSERT INTO heb_vpl VALUES ("K115_13","012_15_13","1KI","15","13","13","וגם את מעכה אמו ויסרה מגבירה אשר עשתה מפלצת לאשרה ויכרת אסא את מפלצתה וישרף בנחל קדרון׃ ");
INSERT INTO heb_vpl VALUES ("K115_14","012_15_14","1KI","15","14","14","והבמות לא סרו רק לבב אסא היה שלם עם יהוה כל ימיו׃ ");
INSERT INTO heb_vpl VALUES ("K115_15","012_15_15","1KI","15","15","15","ויבא את קדשי אביו וקדשו בית יהוה כסף וזהב וכלים׃ ");
INSERT INTO heb_vpl VALUES ("K115_16","012_15_16","1KI","15","16","16","ומלחמה היתה בין אסא ובין בעשא מלך ישראל כל ימיהם׃ ");
INSERT INTO heb_vpl VALUES ("K115_17","012_15_17","1KI","15","17","17","ויעל בעשא מלך ישראל על יהודה ויבן את הרמה לבלתי תת יצא ובא לאסא מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K115_18","012_15_18","1KI","15","18","18","ויקח אסא את כל הכסף והזהב הנותרים באוצרות בית יהוה ואת אוצרות בית מלך ויתנם ביד עבדיו וישלחם המלך אסא אל בן הדד בן טברמן בן חזיון מלך ארם הישב בדמשק לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K115_19","012_15_19","1KI","15","19","19","ברית ביני ובינך בין אבי ובין אביך הנה שלחתי לך שחד כסף וזהב לך הפרה את בריתך את בעשא מלך ישראל ויעלה מעלי׃ ");
INSERT INTO heb_vpl VALUES ("K115_20","012_15_20","1KI","15","20","20","וישמע בן הדד אל המלך אסא וישלח את שרי החילים אשר לו על ערי ישראל ויך את עיון ואת דן ואת אבל בית מעכה ואת כל כנרות על כל ארץ נפתלי׃ ");
INSERT INTO heb_vpl VALUES ("K115_21","012_15_21","1KI","15","21","21","ויהי כשמע בעשא ויחדל מבנות את הרמה וישב בתרצה׃ ");
INSERT INTO heb_vpl VALUES ("K115_22","012_15_22","1KI","15","22","22","והמלך אסא השמיע את כל יהודה אין נקי וישאו את אבני הרמה ואת עציה אשר בנה בעשא ויבן בם המלך אסא את גבע בנימן ואת המצפה׃ ");
INSERT INTO heb_vpl VALUES ("K115_23","012_15_23","1KI","15","23","23","ויתר כל דברי אסא וכל גבורתו וכל אשר עשה והערים אשר בנה הלא המה כתובים על ספר דברי הימים למלכי יהודה רק לעת זקנתו חלה את רגליו׃ ");
INSERT INTO heb_vpl VALUES ("K115_24","012_15_24","1KI","15","24","24","וישכב אסא עם אבתיו ויקבר עם אבתיו בעיר דוד אביו וימלך יהושפט בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K115_25","012_15_25","1KI","15","25","25","ונדב בן ירבעם מלך על ישראל בשנת שתים לאסא מלך יהודה וימלך על ישראל שנתים׃ ");
INSERT INTO heb_vpl VALUES ("K115_26","012_15_26","1KI","15","26","26","ויעש הרע בעיני יהוה וילך בדרך אביו ובחטאתו אשר החטיא את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K115_27","012_15_27","1KI","15","27","27","ויקשר עליו בעשא בן אחיה לבית יששכר ויכהו בעשא בגבתון אשר לפלשתים ונדב וכל ישראל צרים על גבתון׃ ");
INSERT INTO heb_vpl VALUES ("K115_28","012_15_28","1KI","15","28","28","וימתהו בעשא בשנת שלש לאסא מלך יהודה וימלך תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K115_29","012_15_29","1KI","15","29","29","ויהי כמלכו הכה את כל בית ירבעם לא השאיר כל נשמה לירבעם עד השמדו כדבר יהוה אשר דבר ביד עבדו אחיה השילני׃ ");
INSERT INTO heb_vpl VALUES ("K115_30","012_15_30","1KI","15","30","30","על חטאות ירבעם אשר חטא ואשר החטיא את ישראל בכעסו אשר הכעיס את יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K115_31","012_15_31","1KI","15","31","31","ויתר דברי נדב וכל אשר עשה הלא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K115_32","012_15_32","1KI","15","32","32","ומלחמה היתה בין אסא ובין בעשא מלך ישראל כל ימיהם׃ ");
INSERT INTO heb_vpl VALUES ("K115_33","012_15_33","1KI","15","33","33","בשנת שלש לאסא מלך יהודה מלך בעשא בן אחיה על כל ישראל בתרצה עשרים וארבע שנה׃ ");
INSERT INTO heb_vpl VALUES ("K115_34","012_15_34","1KI","15","34","34","ויעש הרע בעיני יהוה וילך בדרך ירבעם ובחטאתו אשר החטיא את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K116_1","012_16_1","1KI","16","1","1","ויהי דבר יהוה אל יהוא בן חנני על בעשא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K116_2","012_16_2","1KI","16","2","2","יען אשר הרימתיך מן העפר ואתנך נגיד על עמי ישראל ותלך בדרך ירבעם ותחטא את עמי ישראל להכעיסני בחטאתם׃ ");
INSERT INTO heb_vpl VALUES ("K116_3","012_16_3","1KI","16","3","3","הנני מבעיר אחרי בעשא ואחרי ביתו ונתתי את ביתך כבית ירבעם בן נבט׃ ");
INSERT INTO heb_vpl VALUES ("K116_4","012_16_4","1KI","16","4","4","המת לבעשא בעיר יאכלו הכלבים והמת לו בשדה יאכלו עוף השמים׃ ");
INSERT INTO heb_vpl VALUES ("K116_5","012_16_5","1KI","16","5","5","ויתר דברי בעשא ואשר עשה וגבורתו הלא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K116_6","012_16_6","1KI","16","6","6","וישכב בעשא עם אבתיו ויקבר בתרצה וימלך אלה בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K116_7","012_16_7","1KI","16","7","7","וגם ביד יהוא בן חנני הנביא דבר יהוה היה אל בעשא ואל ביתו ועל כל הרעה אשר עשה בעיני יהוה להכעיסו במעשה ידיו להיות כבית ירבעם ועל אשר הכה אתו׃ ");
INSERT INTO heb_vpl VALUES ("K116_8","012_16_8","1KI","16","8","8","בשנת עשרים ושש שנה לאסא מלך יהודה מלך אלה בן בעשא על ישראל בתרצה שנתים׃ ");
INSERT INTO heb_vpl VALUES ("K116_9","012_16_9","1KI","16","9","9","ויקשר עליו עבדו זמרי שר מחצית הרכב והוא בתרצה שתה שכור בית ארצא אשר על הבית בתרצה׃ ");
INSERT INTO heb_vpl VALUES ("K116_10","012_16_10","1KI","16","10","10","ויבא זמרי ויכהו וימיתהו בשנת עשרים ושבע לאסא מלך יהודה וימלך תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K116_11","012_16_11","1KI","16","11","11","ויהי במלכו כשבתו על כסאו הכה את כל בית בעשא לא השאיר לו משתין בקיר וגאליו ורעהו׃ ");
INSERT INTO heb_vpl VALUES ("K116_12","012_16_12","1KI","16","12","12","וישמד זמרי את כל בית בעשא כדבר יהוה אשר דבר אל בעשא ביד יהוא הנביא׃ ");
INSERT INTO heb_vpl VALUES ("K116_13","012_16_13","1KI","16","13","13","אל כל חטאות בעשא וחטאות אלה בנו אשר חטאו ואשר החטיאו את ישראל להכעיס את יהוה אלהי ישראל בהבליהם׃ ");
INSERT INTO heb_vpl VALUES ("K116_14","012_16_14","1KI","16","14","14","ויתר דברי אלה וכל אשר עשה הלוא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K116_15","012_16_15","1KI","16","15","15","בשנת עשרים ושבע שנה לאסא מלך יהודה מלך זמרי שבעת ימים בתרצה והעם חנים על גבתון אשר לפלשתים׃ ");
INSERT INTO heb_vpl VALUES ("K116_16","012_16_16","1KI","16","16","16","וישמע העם החנים לאמר קשר זמרי וגם הכה את המלך וימלכו כל ישראל את עמרי שר צבא על ישראל ביום ההוא במחנה׃ ");
INSERT INTO heb_vpl VALUES ("K116_17","012_16_17","1KI","16","17","17","ויעלה עמרי וכל ישראל עמו מגבתון ויצרו על תרצה׃ ");
INSERT INTO heb_vpl VALUES ("K116_18","012_16_18","1KI","16","18","18","ויהי כראות זמרי כי נלכדה העיר ויבא אל ארמון בית המלך וישרף עליו את בית מלך באש וימת׃ ");
INSERT INTO heb_vpl VALUES ("K116_19","012_16_19","1KI","16","19","19","על חטאתיו אשר חטא לעשות הרע בעיני יהוה ללכת בדרך ירבעם ובחטאתו אשר עשה להחטיא את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K116_20","012_16_20","1KI","16","20","20","ויתר דברי זמרי וקשרו אשר קשר הלא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K116_21","012_16_21","1KI","16","21","21","אז יחלק העם ישראל לחצי חצי העם היה אחרי תבני בן גינת להמליכו והחצי אחרי עמרי׃ ");
INSERT INTO heb_vpl VALUES ("K116_22","012_16_22","1KI","16","22","22","ויחזק העם אשר אחרי עמרי את העם אשר אחרי תבני בן גינת וימת תבני וימלך עמרי׃ ");
INSERT INTO heb_vpl VALUES ("K116_23","012_16_23","1KI","16","23","23","בשנת שלשים ואחת שנה לאסא מלך יהודה מלך עמרי על ישראל שתים עשרה שנה בתרצה מלך שש שנים׃ ");
INSERT INTO heb_vpl VALUES ("K116_24","012_16_24","1KI","16","24","24","ויקן את ההר שמרון מאת שמר בככרים כסף ויבן את ההר ויקרא את שם העיר אשר בנה על שם שמר אדני ההר שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K116_25","012_16_25","1KI","16","25","25","ויעשה עמרי הרע בעיני יהוה וירע מכל אשר לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K116_26","012_16_26","1KI","16","26","26","וילך בכל דרך ירבעם בן נבט ובחטאתיו אשר החטיא את ישראל להכעיס את יהוה אלהי ישראל בהבליהם׃ ");
INSERT INTO heb_vpl VALUES ("K116_27","012_16_27","1KI","16","27","27","ויתר דברי עמרי אשר עשה וגבורתו אשר עשה הלא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K116_28","012_16_28","1KI","16","28","28","וישכב עמרי עם אבתיו ויקבר בשמרון וימלך אחאב בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K116_29","012_16_29","1KI","16","29","29","ואחאב בן עמרי מלך על ישראל בשנת שלשים ושמנה שנה לאסא מלך יהודה וימלך אחאב בן עמרי על ישראל בשמרון עשרים ושתים שנה׃ ");
INSERT INTO heb_vpl VALUES ("K116_30","012_16_30","1KI","16","30","30","ויעש אחאב בן עמרי הרע בעיני יהוה מכל אשר לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K116_31","012_16_31","1KI","16","31","31","ויהי הנקל לכתו בחטאות ירבעם בן נבט ויקח אשה את איזבל בת אתבעל מלך צידנים וילך ויעבד את הבעל וישתחו לו׃ ");
INSERT INTO heb_vpl VALUES ("K116_32","012_16_32","1KI","16","32","32","ויקם מזבח לבעל בית הבעל אשר בנה בשמרון׃ ");
INSERT INTO heb_vpl VALUES ("K116_33","012_16_33","1KI","16","33","33","ויעש אחאב את האשרה ויוסף אחאב לעשות להכעיס את יהוה אלהי ישראל מכל מלכי ישראל אשר היו לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K116_34","012_16_34","1KI","16","34","34","בימיו בנה חיאל בית האלי את יריחה באבירם בכרו יסדה ובשגיב צעירו הציב דלתיה כדבר יהוה אשר דבר ביד יהושע בן נון׃ ");
INSERT INTO heb_vpl VALUES ("K117_1","012_17_1","1KI","17","1","1","ויאמר אליהו התשבי מתשבי גלעד אל אחאב חי יהוה אלהי ישראל אשר עמדתי לפניו אם יהיה השנים האלה טל ומטר כי אם לפי דברי׃ ");
INSERT INTO heb_vpl VALUES ("K117_2","012_17_2","1KI","17","2","2","ויהי דבר יהוה אליו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K117_3","012_17_3","1KI","17","3","3","לך מזה ופנית לך קדמה ונסתרת בנחל כרית אשר על פני הירדן׃ ");
INSERT INTO heb_vpl VALUES ("K117_4","012_17_4","1KI","17","4","4","והיה מהנחל תשתה ואת הערבים צויתי לכלכלך שם׃ ");
INSERT INTO heb_vpl VALUES ("K117_5","012_17_5","1KI","17","5","5","וילך ויעש כדבר יהוה וילך וישב בנחל כרית אשר על פני הירדן׃ ");
INSERT INTO heb_vpl VALUES ("K117_6","012_17_6","1KI","17","6","6","והערבים מביאים לו לחם ובשר בבקר ולחם ובשר בערב ומן הנחל ישתה׃ ");
INSERT INTO heb_vpl VALUES ("K117_7","012_17_7","1KI","17","7","7","ויהי מקץ ימים וייבש הנחל כי לא היה גשם בארץ׃ ");
INSERT INTO heb_vpl VALUES ("K117_8","012_17_8","1KI","17","8","8","ויהי דבר יהוה אליו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K117_9","012_17_9","1KI","17","9","9","קום לך צרפתה אשר לצידון וישבת שם הנה צויתי שם אשה אלמנה לכלכלך׃ ");
INSERT INTO heb_vpl VALUES ("K117_10","012_17_10","1KI","17","10","10","ויקם וילך צרפתה ויבא אל פתח העיר והנה שם אשה אלמנה מקששת עצים ויקרא אליה ויאמר קחי נא לי מעט מים בכלי ואשתה׃ ");
INSERT INTO heb_vpl VALUES ("K117_11","012_17_11","1KI","17","11","11","ותלך לקחת ויקרא אליה ויאמר לקחי נא לי פת לחם בידך׃ ");
INSERT INTO heb_vpl VALUES ("K117_12","012_17_12","1KI","17","12","12","ותאמר חי יהוה אלהיך אם יש לי מעוג כי אם מלא כף קמח בכד ומעט שמן בצפחת והנני מקששת שנים עצים ובאתי ועשיתיהו לי ולבני ואכלנהו ומתנו׃ ");
INSERT INTO heb_vpl VALUES ("K117_13","012_17_13","1KI","17","13","13","ויאמר אליה אליהו אל תיראי באי עשי כדברך אך עשי לי משם עגה קטנה בראשנה והוצאת לי ולך ולבנך תעשי באחרנה׃ ");
INSERT INTO heb_vpl VALUES ("K117_14","012_17_14","1KI","17","14","14","כי כה אמר יהוה אלהי ישראל כד הקמח לא תכלה וצפחת השמן לא תחסר עד יום תתן יהוה גשם על פני האדמה׃ ");
INSERT INTO heb_vpl VALUES ("K117_15","012_17_15","1KI","17","15","15","ותלך ותעשה כדבר אליהו ותאכל הוא והיא וביתה ימים׃ ");
INSERT INTO heb_vpl VALUES ("K117_16","012_17_16","1KI","17","16","16","כד הקמח לא כלתה וצפחת השמן לא חסר כדבר יהוה אשר דבר ביד אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K117_17","012_17_17","1KI","17","17","17","ויהי אחר הדברים האלה חלה בן האשה בעלת הבית ויהי חליו חזק מאד עד אשר לא נותרה בו נשמה׃ ");
INSERT INTO heb_vpl VALUES ("K117_18","012_17_18","1KI","17","18","18","ותאמר אל אליהו מה לי ולך איש האלהים באת אלי להזכיר את עוני ולהמית את בני׃ ");
INSERT INTO heb_vpl VALUES ("K117_19","012_17_19","1KI","17","19","19","ויאמר אליה תני לי את בנך ויקחהו מחיקה ויעלהו אל העליה אשר הוא ישב שם וישכבהו על מטתו׃ ");
INSERT INTO heb_vpl VALUES ("K117_20","012_17_20","1KI","17","20","20","ויקרא אל יהוה ויאמר יהוה אלהי הגם על האלמנה אשר אני מתגורר עמה הרעות להמית את בנה׃ ");
INSERT INTO heb_vpl VALUES ("K117_21","012_17_21","1KI","17","21","21","ויתמדד על הילד שלש פעמים ויקרא אל יהוה ויאמר יהוה אלהי תשב נא נפש הילד הזה על קרבו׃ ");
INSERT INTO heb_vpl VALUES ("K117_22","012_17_22","1KI","17","22","22","וישמע יהוה בקול אליהו ותשב נפש הילד על קרבו ויחי׃ ");
INSERT INTO heb_vpl VALUES ("K117_23","012_17_23","1KI","17","23","23","ויקח אליהו את הילד וירדהו מן העליה הביתה ויתנהו לאמו ויאמר אליהו ראי חי בנך׃ ");
INSERT INTO heb_vpl VALUES ("K117_24","012_17_24","1KI","17","24","24","ותאמר האשה אל אליהו עתה זה ידעתי כי איש אלהים אתה ודבר יהוה בפיך אמת׃ ");
INSERT INTO heb_vpl VALUES ("K118_1","012_18_1","1KI","18","1","1","ויהי ימים רבים ודבר יהוה היה אל אליהו בשנה השלישית לאמר לך הראה אל אחאב ואתנה מטר על פני האדמה׃ ");
INSERT INTO heb_vpl VALUES ("K118_2","012_18_2","1KI","18","2","2","וילך אליהו להראות אל אחאב והרעב חזק בשמרון׃ ");
INSERT INTO heb_vpl VALUES ("K118_3","012_18_3","1KI","18","3","3","ויקרא אחאב אל עבדיהו אשר על הבית ועבדיהו היה ירא את יהוה מאד׃ ");
INSERT INTO heb_vpl VALUES ("K118_4","012_18_4","1KI","18","4","4","ויהי בהכרית איזבל את נביאי יהוה ויקח עבדיהו מאה נבאים ויחביאם חמשים איש במערה וכלכלם לחם ומים׃ ");
INSERT INTO heb_vpl VALUES ("K118_5","012_18_5","1KI","18","5","5","ויאמר אחאב אל עבדיהו לך בארץ אל כל מעיני המים ואל כל הנחלים אולי נמצא חציר ונחיה סוס ופרד ולוא נכרית מהבהמה׃ ");
INSERT INTO heb_vpl VALUES ("K118_6","012_18_6","1KI","18","6","6","ויחלקו להם את הארץ לעבר בה אחאב הלך בדרך אחד לבדו ועבדיהו הלך בדרך אחד לבדו׃ ");
INSERT INTO heb_vpl VALUES ("K118_7","012_18_7","1KI","18","7","7","ויהי עבדיהו בדרך והנה אליהו לקראתו ויכרהו ויפל על פניו ויאמר האתה זה אדני אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K118_8","012_18_8","1KI","18","8","8","ויאמר לו אני לך אמר לאדניך הנה אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K118_9","012_18_9","1KI","18","9","9","ויאמר מה חטאתי כי אתה נתן את עבדך ביד אחאב להמיתני׃ ");
INSERT INTO heb_vpl VALUES ("K118_10","012_18_10","1KI","18","10","10","חי יהוה אלהיך אם יש גוי וממלכה אשר לא שלח אדני שם לבקשך ואמרו אין והשביע את הממלכה ואת הגוי כי לא ימצאכה׃ ");
INSERT INTO heb_vpl VALUES ("K118_11","012_18_11","1KI","18","11","11","ועתה אתה אמר לך אמר לאדניך הנה אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K118_12","012_18_12","1KI","18","12","12","והיה אני אלך מאתך ורוח יהוה ישאך על אשר לא אדע ובאתי להגיד לאחאב ולא ימצאך והרגני ועבדך ירא את יהוה מנערי׃ ");
INSERT INTO heb_vpl VALUES ("K118_13","012_18_13","1KI","18","13","13","הלא הגד לאדני את אשר עשיתי בהרג איזבל את נביאי יהוה ואחבא מנביאי יהוה מאה איש חמשים חמשים איש במערה ואכלכלם לחם ומים׃ ");
INSERT INTO heb_vpl VALUES ("K118_14","012_18_14","1KI","18","14","14","ועתה אתה אמר לך אמר לאדניך הנה אליהו והרגני׃ ");
INSERT INTO heb_vpl VALUES ("K118_15","012_18_15","1KI","18","15","15","ויאמר אליהו חי יהוה צבאות אשר עמדתי לפניו כי היום אראה אליו׃ ");
INSERT INTO heb_vpl VALUES ("K118_16","012_18_16","1KI","18","16","16","וילך עבדיהו לקראת אחאב ויגד לו וילך אחאב לקראת אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K118_17","012_18_17","1KI","18","17","17","ויהי כראות אחאב את אליהו ויאמר אחאב אליו האתה זה עכר ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K118_18","012_18_18","1KI","18","18","18","ויאמר לא עכרתי את ישראל כי אם אתה ובית אביך בעזבכם את מצות יהוה ותלך אחרי הבעלים׃ ");
INSERT INTO heb_vpl VALUES ("K118_19","012_18_19","1KI","18","19","19","ועתה שלח קבץ אלי את כל ישראל אל הר הכרמל ואת נביאי הבעל ארבע מאות וחמשים ונביאי האשרה ארבע מאות אכלי שלחן איזבל׃ ");
INSERT INTO heb_vpl VALUES ("K118_20","012_18_20","1KI","18","20","20","וישלח אחאב בכל בני ישראל ויקבץ את הנביאים אל הר הכרמל׃ ");
INSERT INTO heb_vpl VALUES ("K118_21","012_18_21","1KI","18","21","21","ויגש אליהו אל כל העם ויאמר עד מתי אתם פסחים על שתי הסעפים אם יהוה האלהים לכו אחריו ואם הבעל לכו אחריו ולא ענו העם אתו דבר׃ ");
INSERT INTO heb_vpl VALUES ("K118_22","012_18_22","1KI","18","22","22","ויאמר אליהו אל העם אני נותרתי נביא ליהוה לבדי ונביאי הבעל ארבע מאות וחמשים איש׃ ");
INSERT INTO heb_vpl VALUES ("K118_23","012_18_23","1KI","18","23","23","ויתנו לנו שנים פרים ויבחרו להם הפר האחד וינתחהו וישימו על העצים ואש לא ישימו ואני אעשה את הפר האחד ונתתי על העצים ואש לא אשים׃ ");
INSERT INTO heb_vpl VALUES ("K118_24","012_18_24","1KI","18","24","24","וקראתם בשם אלהיכם ואני אקרא בשם יהוה והיה האלהים אשר יענה באש הוא האלהים ויען כל העם ויאמרו טוב הדבר׃ ");
INSERT INTO heb_vpl VALUES ("K118_25","012_18_25","1KI","18","25","25","ויאמר אליהו לנביאי הבעל בחרו לכם הפר האחד ועשו ראשנה כי אתם הרבים וקראו בשם אלהיכם ואש לא תשימו׃ ");
INSERT INTO heb_vpl VALUES ("K118_26","012_18_26","1KI","18","26","26","ויקחו את הפר אשר נתן להם ויעשו ויקראו בשם הבעל מהבקר ועד הצהרים לאמר הבעל עננו ואין קול ואין ענה ויפסחו על המזבח אשר עשה׃ ");
INSERT INTO heb_vpl VALUES ("K118_27","012_18_27","1KI","18","27","27","ויהי בצהרים ויהתל בהם אליהו ויאמר קראו בקול גדול כי אלהים הוא כי שיח וכי שיג לו וכי דרך לו אולי ישן הוא ויקץ׃ ");
INSERT INTO heb_vpl VALUES ("K118_28","012_18_28","1KI","18","28","28","ויקראו בקול גדול ויתגדדו כמשפטם בחרבות וברמחים עד שפך דם עליהם׃ ");
INSERT INTO heb_vpl VALUES ("K118_29","012_18_29","1KI","18","29","29","ויהי כעבר הצהרים ויתנבאו עד לעלות המנחה ואין קול ואין ענה ואין קשב׃ ");
INSERT INTO heb_vpl VALUES ("K118_30","012_18_30","1KI","18","30","30","ויאמר אליהו לכל העם גשו אלי ויגשו כל העם אליו וירפא את מזבח יהוה ההרוס׃ ");
INSERT INTO heb_vpl VALUES ("K118_31","012_18_31","1KI","18","31","31","ויקח אליהו שתים עשרה אבנים כמספר שבטי בני יעקב אשר היה דבר יהוה אליו לאמר ישראל יהיה שמך׃ ");
INSERT INTO heb_vpl VALUES ("K118_32","012_18_32","1KI","18","32","32","ויבנה את האבנים מזבח בשם יהוה ויעש תעלה כבית סאתים זרע סביב למזבח׃ ");
INSERT INTO heb_vpl VALUES ("K118_33","012_18_33","1KI","18","33","33","ויערך את העצים וינתח את הפר וישם על העצים׃ ");
INSERT INTO heb_vpl VALUES ("K118_34","012_18_34","1KI","18","34","34","ויאמר מלאו ארבעה כדים מים ויצקו על העלה ועל העצים ויאמר שנו וישנו ויאמר שלשו וישלשו׃ ");
INSERT INTO heb_vpl VALUES ("K118_35","012_18_35","1KI","18","35","35","וילכו המים סביב למזבח וגם את התעלה מלא מים׃ ");
INSERT INTO heb_vpl VALUES ("K118_36","012_18_36","1KI","18","36","36","ויהי בעלות המנחה ויגש אליהו הנביא ויאמר יהוה אלהי אברהם יצחק וישראל היום יודע כי אתה אלהים בישראל ואני עבדך ובדבריך עשיתי את כל הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("K118_37","012_18_37","1KI","18","37","37","ענני יהוה ענני וידעו העם הזה כי אתה יהוה האלהים ואתה הסבת את לבם אחרנית׃ ");
INSERT INTO heb_vpl VALUES ("K118_38","012_18_38","1KI","18","38","38","ותפל אש יהוה ותאכל את העלה ואת העצים ואת האבנים ואת העפר ואת המים אשר בתעלה לחכה׃ ");
INSERT INTO heb_vpl VALUES ("K118_39","012_18_39","1KI","18","39","39","וירא כל העם ויפלו על פניהם ויאמרו יהוה הוא האלהים יהוה הוא האלהים׃ ");
INSERT INTO heb_vpl VALUES ("K118_40","012_18_40","1KI","18","40","40","ויאמר אליהו להם תפשו את נביאי הבעל איש אל ימלט מהם ויתפשום ויורדם אליהו אל נחל קישון וישחטם שם׃ ");
INSERT INTO heb_vpl VALUES ("K118_41","012_18_41","1KI","18","41","41","ויאמר אליהו לאחאב עלה אכל ושתה כי קול המון הגשם׃ ");
INSERT INTO heb_vpl VALUES ("K118_42","012_18_42","1KI","18","42","42","ויעלה אחאב לאכל ולשתות ואליהו עלה אל ראש הכרמל ויגהר ארצה וישם פניו בין ברכו׃ ");
INSERT INTO heb_vpl VALUES ("K118_43","012_18_43","1KI","18","43","43","ויאמר אל נערו עלה נא הבט דרך ים ויעל ויבט ויאמר אין מאומה ויאמר שב שבע פעמים׃ ");
INSERT INTO heb_vpl VALUES ("K118_44","012_18_44","1KI","18","44","44","ויהי בשבעית ויאמר הנה עב קטנה ככף איש עלה מים ויאמר עלה אמר אל אחאב אסר ורד ולא יעצרכה הגשם׃ ");
INSERT INTO heb_vpl VALUES ("K118_45","012_18_45","1KI","18","45","45","ויהי עד כה ועד כה והשמים התקדרו עבים ורוח ויהי גשם גדול וירכב אחאב וילך יזרעאלה׃ ");
INSERT INTO heb_vpl VALUES ("K118_46","012_18_46","1KI","18","46","46","ויד יהוה היתה אל אליהו וישנס מתניו וירץ לפני אחאב עד באכה יזרעאלה׃ ");
INSERT INTO heb_vpl VALUES ("K119_1","012_19_1","1KI","19","1","1","ויגד אחאב לאיזבל את כל אשר עשה אליהו ואת כל אשר הרג את כל הנביאים בחרב׃ ");
INSERT INTO heb_vpl VALUES ("K119_2","012_19_2","1KI","19","2","2","ותשלח איזבל מלאך אל אליהו לאמר כה יעשון אלהים וכה יוספון כי כעת מחר אשים את נפשך כנפש אחד מהם׃ ");
INSERT INTO heb_vpl VALUES ("K119_3","012_19_3","1KI","19","3","3","וירא ויקם וילך אל נפשו ויבא באר שבע אשר ליהודה וינח את נערו שם׃ ");
INSERT INTO heb_vpl VALUES ("K119_4","012_19_4","1KI","19","4","4","והוא הלך במדבר דרך יום ויבא וישב תחת רתם אחת וישאל את נפשו למות ויאמר רב עתה יהוה קח נפשי כי לא טוב אנכי מאבתי׃ ");
INSERT INTO heb_vpl VALUES ("K119_5","012_19_5","1KI","19","5","5","וישכב ויישן תחת רתם אחד והנה זה מלאך נגע בו ויאמר לו קום אכול׃ ");
INSERT INTO heb_vpl VALUES ("K119_6","012_19_6","1KI","19","6","6","ויבט והנה מראשתיו עגת רצפים וצפחת מים ויאכל וישת וישב וישכב׃ ");
INSERT INTO heb_vpl VALUES ("K119_7","012_19_7","1KI","19","7","7","וישב מלאך יהוה שנית ויגע בו ויאמר קום אכל כי רב ממך הדרך׃ ");
INSERT INTO heb_vpl VALUES ("K119_8","012_19_8","1KI","19","8","8","ויקם ויאכל וישתה וילך בכח האכילה ההיא ארבעים יום וארבעים לילה עד הר האלהים חרב׃ ");
INSERT INTO heb_vpl VALUES ("K119_9","012_19_9","1KI","19","9","9","ויבא שם אל המערה וילן שם והנה דבר יהוה אליו ויאמר לו מה לך פה אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K119_10","012_19_10","1KI","19","10","10","ויאמר קנא קנאתי ליהוה אלהי צבאות כי עזבו בריתך בני ישראל את מזבחתיך הרסו ואת נביאיך הרגו בחרב ואותר אני לבדי ויבקשו את נפשי לקחתה׃ ");
INSERT INTO heb_vpl VALUES ("K119_11","012_19_11","1KI","19","11","11","ויאמר צא ועמדת בהר לפני יהוה והנה יהוה עבר ורוח גדולה וחזק מפרק הרים ומשבר סלעים לפני יהוה לא ברוח יהוה ואחר הרוח רעש לא ברעש יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K119_12","012_19_12","1KI","19","12","12","ואחר הרעש אש לא באש יהוה ואחר האש קול דממה דקה׃ ");
INSERT INTO heb_vpl VALUES ("K119_13","012_19_13","1KI","19","13","13","ויהי כשמע אליהו וילט פניו באדרתו ויצא ויעמד פתח המערה והנה אליו קול ויאמר מה לך פה אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K119_14","012_19_14","1KI","19","14","14","ויאמר קנא קנאתי ליהוה אלהי צבאות כי עזבו בריתך בני ישראל את מזבחתיך הרסו ואת נביאיך הרגו בחרב ואותר אני לבדי ויבקשו את נפשי לקחתה׃ ");
INSERT INTO heb_vpl VALUES ("K119_15","012_19_15","1KI","19","15","15","ויאמר יהוה אליו לך שוב לדרכך מדברה דמשק ובאת ומשחת את חזאל למלך על ארם׃ ");
INSERT INTO heb_vpl VALUES ("K119_16","012_19_16","1KI","19","16","16","ואת יהוא בן נמשי תמשח למלך על ישראל ואת אלישע בן שפט מאבל מחולה תמשח לנביא תחתיך׃ ");
INSERT INTO heb_vpl VALUES ("K119_17","012_19_17","1KI","19","17","17","והיה הנמלט מחרב חזאל ימית יהוא והנמלט מחרב יהוא ימית אלישע׃ ");
INSERT INTO heb_vpl VALUES ("K119_18","012_19_18","1KI","19","18","18","והשארתי בישראל שבעת אלפים כל הברכים אשר לא כרעו לבעל וכל הפה אשר לא נשק לו׃ ");
INSERT INTO heb_vpl VALUES ("K119_19","012_19_19","1KI","19","19","19","וילך משם וימצא את אלישע בן שפט והוא חרש שנים עשר צמדים לפניו והוא בשנים העשר ויעבר אליהו אליו וישלך אדרתו אליו׃ ");
INSERT INTO heb_vpl VALUES ("K119_20","012_19_20","1KI","19","20","20","ויעזב את הבקר וירץ אחרי אליהו ויאמר אשקה נא לאבי ולאמי ואלכה אחריך ויאמר לו לך שוב כי מה עשיתי לך׃ ");
INSERT INTO heb_vpl VALUES ("K119_21","012_19_21","1KI","19","21","21","וישב מאחריו ויקח את צמד הבקר ויזבחהו ובכלי הבקר בשלם הבשר ויתן לעם ויאכלו ויקם וילך אחרי אליהו וישרתהו׃ ");
INSERT INTO heb_vpl VALUES ("K120_1","012_20_1","1KI","20","1","1","ובן הדד מלך ארם קבץ את כל חילו ושלשים ושנים מלך אתו וסוס ורכב ויעל ויצר על שמרון וילחם בה׃ ");
INSERT INTO heb_vpl VALUES ("K120_2","012_20_2","1KI","20","2","2","וישלח מלאכים אל אחאב מלך ישראל העירה׃ ");
INSERT INTO heb_vpl VALUES ("K120_3","012_20_3","1KI","20","3","3","ויאמר לו כה אמר בן הדד כספך וזהבך לי הוא ונשיך ובניך הטובים לי הם׃ ");
INSERT INTO heb_vpl VALUES ("K120_4","012_20_4","1KI","20","4","4","ויען מלך ישראל ויאמר כדברך אדני המלך לך אני וכל אשר לי׃ ");
INSERT INTO heb_vpl VALUES ("K120_5","012_20_5","1KI","20","5","5","וישבו המלאכים ויאמרו כה אמר בן הדד לאמר כי שלחתי אליך לאמר כספך וזהבך ונשיך ובניך לי תתן׃ ");
INSERT INTO heb_vpl VALUES ("K120_6","012_20_6","1KI","20","6","6","כי אם כעת מחר אשלח את עבדי אליך וחפשו את ביתך ואת בתי עבדיך והיה כל מחמד עיניך ישימו בידם ולקחו׃ ");
INSERT INTO heb_vpl VALUES ("K120_7","012_20_7","1KI","20","7","7","ויקרא מלך ישראל לכל זקני הארץ ויאמר דעו נא וראו כי רעה זה מבקש כי שלח אלי לנשי ולבני ולכספי ולזהבי ולא מנעתי ממנו׃ ");
INSERT INTO heb_vpl VALUES ("K120_8","012_20_8","1KI","20","8","8","ויאמרו אליו כל הזקנים וכל העם אל תשמע ולוא תאבה׃ ");
INSERT INTO heb_vpl VALUES ("K120_9","012_20_9","1KI","20","9","9","ויאמר למלאכי בן הדד אמרו לאדני המלך כל אשר שלחת אל עבדך בראשנה אעשה והדבר הזה לא אוכל לעשות וילכו המלאכים וישבהו דבר׃ ");
INSERT INTO heb_vpl VALUES ("K120_10","012_20_10","1KI","20","10","10","וישלח אליו בן הדד ויאמר כה יעשון לי אלהים וכה יוספו אם ישפק עפר שמרון לשעלים לכל העם אשר ברגלי׃ ");
INSERT INTO heb_vpl VALUES ("K120_11","012_20_11","1KI","20","11","11","ויען מלך ישראל ויאמר דברו אל יתהלל חגר כמפתח׃ ");
INSERT INTO heb_vpl VALUES ("K120_12","012_20_12","1KI","20","12","12","ויהי כשמע את הדבר הזה והוא שתה הוא והמלכים בסכות ויאמר אל עבדיו שימו וישימו על העיר׃ ");
INSERT INTO heb_vpl VALUES ("K120_13","012_20_13","1KI","20","13","13","והנה נביא אחד נגש אל אחאב מלך ישראל ויאמר כה אמר יהוה הראית את כל ההמון הגדול הזה הנני נתנו בידך היום וידעת כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K120_14","012_20_14","1KI","20","14","14","ויאמר אחאב במי ויאמר כה אמר יהוה בנערי שרי המדינות ויאמר מי יאסר המלחמה ויאמר אתה׃ ");
INSERT INTO heb_vpl VALUES ("K120_15","012_20_15","1KI","20","15","15","ויפקד את נערי שרי המדינות ויהיו מאתים שנים ושלשים ואחריהם פקד את כל העם כל בני ישראל שבעת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("K120_16","012_20_16","1KI","20","16","16","ויצאו בצהרים ובן הדד שתה שכור בסכות הוא והמלכים שלשים ושנים מלך עזר אתו׃ ");
INSERT INTO heb_vpl VALUES ("K120_17","012_20_17","1KI","20","17","17","ויצאו נערי שרי המדינות בראשנה וישלח בן הדד ויגידו לו לאמר אנשים יצאו משמרון׃ ");
INSERT INTO heb_vpl VALUES ("K120_18","012_20_18","1KI","20","18","18","ויאמר אם לשלום יצאו תפשום חיים ואם למלחמה יצאו חיים תפשום׃ ");
INSERT INTO heb_vpl VALUES ("K120_19","012_20_19","1KI","20","19","19","ואלה יצאו מן העיר נערי שרי המדינות והחיל אשר אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("K120_20","012_20_20","1KI","20","20","20","ויכו איש אישו וינסו ארם וירדפם ישראל וימלט בן הדד מלך ארם על סוס ופרשים׃ ");
INSERT INTO heb_vpl VALUES ("K120_21","012_20_21","1KI","20","21","21","ויצא מלך ישראל ויך את הסוס ואת הרכב והכה בארם מכה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("K120_22","012_20_22","1KI","20","22","22","ויגש הנביא אל מלך ישראל ויאמר לו לך התחזק ודע וראה את אשר תעשה כי לתשובת השנה מלך ארם עלה עליך׃ ");
INSERT INTO heb_vpl VALUES ("K120_23","012_20_23","1KI","20","23","23","ועבדי מלך ארם אמרו אליו אלהי הרים אלהיהם על כן חזקו ממנו ואולם נלחם אתם במישור אם לא נחזק מהם׃ ");
INSERT INTO heb_vpl VALUES ("K120_24","012_20_24","1KI","20","24","24","ואת הדבר הזה עשה הסר המלכים איש ממקמו ושים פחות תחתיהם׃ ");
INSERT INTO heb_vpl VALUES ("K120_25","012_20_25","1KI","20","25","25","ואתה תמנה לך חיל כחיל הנפל מאותך וסוס כסוס ורכב כרכב ונלחמה אותם במישור אם לא נחזק מהם וישמע לקלם ויעש כן׃ ");
INSERT INTO heb_vpl VALUES ("K120_26","012_20_26","1KI","20","26","26","ויהי לתשובת השנה ויפקד בן הדד את ארם ויעל אפקה למלחמה עם ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K120_27","012_20_27","1KI","20","27","27","ובני ישראל התפקדו וכלכלו וילכו לקראתם ויחנו בני ישראל נגדם כשני חשפי עזים וארם מלאו את הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K120_28","012_20_28","1KI","20","28","28","ויגש איש האלהים ויאמר אל מלך ישראל ויאמר כה אמר יהוה יען אשר אמרו ארם אלהי הרים יהוה ולא אלהי עמקים הוא ונתתי את כל ההמון הגדול הזה בידך וידעתם כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K120_29","012_20_29","1KI","20","29","29","ויחנו אלה נכח אלה שבעת ימים ויהי ביום השביעי ותקרב המלחמה ויכו בני ישראל את ארם מאה אלף רגלי ביום אחד׃ ");
INSERT INTO heb_vpl VALUES ("K120_30","012_20_30","1KI","20","30","30","וינסו הנותרים אפקה אל העיר ותפל החומה על עשרים ושבעה אלף איש הנותרים ובן הדד נס ויבא אל העיר חדר בחדר׃ ");
INSERT INTO heb_vpl VALUES ("K120_31","012_20_31","1KI","20","31","31","ויאמרו אליו עבדיו הנה נא שמענו כי מלכי בית ישראל כי מלכי חסד הם נשימה נא שקים במתנינו וחבלים בראשנו ונצא אל מלך ישראל אולי יחיה את נפשך׃ ");
INSERT INTO heb_vpl VALUES ("K120_32","012_20_32","1KI","20","32","32","ויחגרו שקים במתניהם וחבלים בראשיהם ויבאו אל מלך ישראל ויאמרו עבדך בן הדד אמר תחי נא נפשי ויאמר העודנו חי אחי הוא׃ ");
INSERT INTO heb_vpl VALUES ("K120_33","012_20_33","1KI","20","33","33","והאנשים ינחשו וימהרו ויחלטו הממנו ויאמרו אחיך בן הדד ויאמר באו קחהו ויצא אליו בן הדד ויעלהו על המרכבה׃ ");
INSERT INTO heb_vpl VALUES ("K120_34","012_20_34","1KI","20","34","34","ויאמר אליו הערים אשר לקח אבי מאת אביך אשיב וחוצות תשים לך בדמשק כאשר שם אבי בשמרון ואני בברית אשלחך ויכרת לו ברית וישלחהו׃ ");
INSERT INTO heb_vpl VALUES ("K120_35","012_20_35","1KI","20","35","35","ואיש אחד מבני הנביאים אמר אל רעהו בדבר יהוה הכיני נא וימאן האיש להכתו׃ ");
INSERT INTO heb_vpl VALUES ("K120_36","012_20_36","1KI","20","36","36","ויאמר לו יען אשר לא שמעת בקול יהוה הנך הולך מאתי והכך האריה וילך מאצלו וימצאהו האריה ויכהו׃ ");
INSERT INTO heb_vpl VALUES ("K120_37","012_20_37","1KI","20","37","37","וימצא איש אחר ויאמר הכיני נא ויכהו האיש הכה ופצע׃ ");
INSERT INTO heb_vpl VALUES ("K120_38","012_20_38","1KI","20","38","38","וילך הנביא ויעמד למלך על הדרך ויתחפש באפר על עיניו׃ ");
INSERT INTO heb_vpl VALUES ("K120_39","012_20_39","1KI","20","39","39","ויהי המלך עבר והוא צעק אל המלך ויאמר עבדך יצא בקרב המלחמה והנה איש סר ויבא אלי איש ויאמר שמר את האיש הזה אם הפקד יפקד והיתה נפשך תחת נפשו או ככר כסף תשקול׃ ");
INSERT INTO heb_vpl VALUES ("K120_40","012_20_40","1KI","20","40","40","ויהי עבדך עשה הנה והנה והוא איננו ויאמר אליו מלך ישראל כן משפטך אתה חרצת׃ ");
INSERT INTO heb_vpl VALUES ("K120_41","012_20_41","1KI","20","41","41","וימהר ויסר את האפר מעל עיניו ויכר אתו מלך ישראל כי מהנבאים הוא׃ ");
INSERT INTO heb_vpl VALUES ("K120_42","012_20_42","1KI","20","42","42","ויאמר אליו כה אמר יהוה יען שלחת את איש חרמי מיד והיתה נפשך תחת נפשו ועמך תחת עמו׃ ");
INSERT INTO heb_vpl VALUES ("K120_43","012_20_43","1KI","20","43","43","וילך מלך ישראל על ביתו סר וזעף ויבא שמרונה׃ ");
INSERT INTO heb_vpl VALUES ("K121_1","012_21_1","1KI","21","1","1","ויהי אחר הדברים האלה כרם היה לנבות היזרעאלי אשר ביזרעאל אצל היכל אחאב מלך שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K121_2","012_21_2","1KI","21","2","2","וידבר אחאב אל נבות לאמר תנה לי את כרמך ויהי לי לגן ירק כי הוא קרוב אצל ביתי ואתנה לך תחתיו כרם טוב ממנו אם טוב בעיניך אתנה לך כסף מחיר זה׃ ");
INSERT INTO heb_vpl VALUES ("K121_3","012_21_3","1KI","21","3","3","ויאמר נבות אל אחאב חלילה לי מיהוה מתתי את נחלת אבתי לך׃ ");
INSERT INTO heb_vpl VALUES ("K121_4","012_21_4","1KI","21","4","4","ויבא אחאב אל ביתו סר וזעף על הדבר אשר דבר אליו נבות היזרעאלי ויאמר לא אתן לך את נחלת אבותי וישכב על מטתו ויסב את פניו ולא אכל לחם׃ ");
INSERT INTO heb_vpl VALUES ("K121_5","012_21_5","1KI","21","5","5","ותבא אליו איזבל אשתו ותדבר אליו מה זה רוחך סרה ואינך אכל לחם׃ ");
INSERT INTO heb_vpl VALUES ("K121_6","012_21_6","1KI","21","6","6","וידבר אליה כי אדבר אל נבות היזרעאלי ואמר לו תנה לי את כרמך בכסף או אם חפץ אתה אתנה לך כרם תחתיו ויאמר לא אתן לך את כרמי׃ ");
INSERT INTO heb_vpl VALUES ("K121_7","012_21_7","1KI","21","7","7","ותאמר אליו איזבל אשתו אתה עתה תעשה מלוכה על ישראל קום אכל לחם ויטב לבך אני אתן לך את כרם נבות היזרעאלי׃ ");
INSERT INTO heb_vpl VALUES ("K121_8","012_21_8","1KI","21","8","8","ותכתב ספרים בשם אחאב ותחתם בחתמו ותשלח הספרים אל הזקנים ואל החרים אשר בעירו הישבים את נבות׃ ");
INSERT INTO heb_vpl VALUES ("K121_9","012_21_9","1KI","21","9","9","ותכתב בספרים לאמר קראו צום והושיבו את נבות בראש העם׃ ");
INSERT INTO heb_vpl VALUES ("K121_10","012_21_10","1KI","21","10","10","והושיבו שנים אנשים בני בליעל נגדו ויעדהו לאמר ברכת אלהים ומלך והוציאהו וסקלהו וימת׃ ");
INSERT INTO heb_vpl VALUES ("K121_11","012_21_11","1KI","21","11","11","ויעשו אנשי עירו הזקנים והחרים אשר הישבים בעירו כאשר שלחה אליהם איזבל כאשר כתוב בספרים אשר שלחה אליהם׃ ");
INSERT INTO heb_vpl VALUES ("K121_12","012_21_12","1KI","21","12","12","קראו צום והשיבו את נבות בראש העם׃ ");
INSERT INTO heb_vpl VALUES ("K121_13","012_21_13","1KI","21","13","13","ויבאו שני האנשים בני בליעל וישבו נגדו ויעדהו אנשי הבליעל את נבות נגד העם לאמר ברך נבות אלהים ומלך ויצאהו מחוץ לעיר ויסקלהו באבנים וימת׃ ");
INSERT INTO heb_vpl VALUES ("K121_14","012_21_14","1KI","21","14","14","וישלחו אל איזבל לאמר סקל נבות וימת׃ ");
INSERT INTO heb_vpl VALUES ("K121_15","012_21_15","1KI","21","15","15","ויהי כשמע איזבל כי סקל נבות וימת ותאמר איזבל אל אחאב קום רש את כרם נבות היזרעאלי אשר מאן לתת לך בכסף כי אין נבות חי כי מת׃ ");
INSERT INTO heb_vpl VALUES ("K121_16","012_21_16","1KI","21","16","16","ויהי כשמע אחאב כי מת נבות ויקם אחאב לרדת אל כרם נבות היזרעאלי לרשתו׃ ");
INSERT INTO heb_vpl VALUES ("K121_17","012_21_17","1KI","21","17","17","ויהי דבר יהוה אל אליהו התשבי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K121_18","012_21_18","1KI","21","18","18","קום רד לקראת אחאב מלך ישראל אשר בשמרון הנה בכרם נבות אשר ירד שם לרשתו׃ ");
INSERT INTO heb_vpl VALUES ("K121_19","012_21_19","1KI","21","19","19","ודברת אליו לאמר כה אמר יהוה הרצחת וגם ירשת ודברת אליו לאמר כה אמר יהוה במקום אשר לקקו הכלבים את דם נבות ילקו הכלבים את דמך גם אתה׃ ");
INSERT INTO heb_vpl VALUES ("K121_20","012_21_20","1KI","21","20","20","ויאמר אחאב אל אליהו המצאתני איבי ויאמר מצאתי יען התמכרך לעשות הרע בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K121_21","012_21_21","1KI","21","21","21","הנני מבי אליך רעה ובערתי אחריך והכרתי לאחאב משתין בקיר ועצור ועזוב בישראל׃ ");
INSERT INTO heb_vpl VALUES ("K121_22","012_21_22","1KI","21","22","22","ונתתי את ביתך כבית ירבעם בן נבט וכבית בעשא בן אחיה אל הכעס אשר הכעסת ותחטא את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K121_23","012_21_23","1KI","21","23","23","וגם לאיזבל דבר יהוה לאמר הכלבים יאכלו את איזבל בחל יזרעאל׃ ");
INSERT INTO heb_vpl VALUES ("K121_24","012_21_24","1KI","21","24","24","המת לאחאב בעיר יאכלו הכלבים והמת בשדה יאכלו עוף השמים׃ ");
INSERT INTO heb_vpl VALUES ("K121_25","012_21_25","1KI","21","25","25","רק לא היה כאחאב אשר התמכר לעשות הרע בעיני יהוה אשר הסתה אתו איזבל אשתו׃ ");
INSERT INTO heb_vpl VALUES ("K121_26","012_21_26","1KI","21","26","26","ויתעב מאד ללכת אחרי הגללים ככל אשר עשו האמרי אשר הוריש יהוה מפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K121_27","012_21_27","1KI","21","27","27","ויהי כשמע אחאב את הדברים האלה ויקרע בגדיו וישם שק על בשרו ויצום וישכב בשק ויהלך אט׃ ");
INSERT INTO heb_vpl VALUES ("K121_28","012_21_28","1KI","21","28","28","ויהי דבר יהוה אל אליהו התשבי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K121_29","012_21_29","1KI","21","29","29","הראית כי נכנע אחאב מלפני יען כי נכנע מפני לא אבי הרעה בימיו בימי בנו אביא הרעה על ביתו׃ ");
INSERT INTO heb_vpl VALUES ("K122_1","012_22_1","1KI","22","1","1","וישבו שלש שנים אין מלחמה בין ארם ובין ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K122_2","012_22_2","1KI","22","2","2","ויהי בשנה השלישית וירד יהושפט מלך יהודה אל מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K122_3","012_22_3","1KI","22","3","3","ויאמר מלך ישראל אל עבדיו הידעתם כי לנו רמת גלעד ואנחנו מחשים מקחת אתה מיד מלך ארם׃ ");
INSERT INTO heb_vpl VALUES ("K122_4","012_22_4","1KI","22","4","4","ויאמר אל יהושפט התלך אתי למלחמה רמת גלעד ויאמר יהושפט אל מלך ישראל כמוני כמוך כעמי כעמך כסוסי כסוסיך׃ ");
INSERT INTO heb_vpl VALUES ("K122_5","012_22_5","1KI","22","5","5","ויאמר יהושפט אל מלך ישראל דרש נא כיום את דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K122_6","012_22_6","1KI","22","6","6","ויקבץ מלך ישראל את הנביאים כארבע מאות איש ויאמר אלהם האלך על רמת גלעד למלחמה אם אחדל ויאמרו עלה ויתן אדני ביד המלך׃ ");
INSERT INTO heb_vpl VALUES ("K122_7","012_22_7","1KI","22","7","7","ויאמר יהושפט האין פה נביא ליהוה עוד ונדרשה מאותו׃ ");
INSERT INTO heb_vpl VALUES ("K122_8","012_22_8","1KI","22","8","8","ויאמר מלך ישראל אל יהושפט עוד איש אחד לדרש את יהוה מאתו ואני שנאתיו כי לא יתנבא עלי טוב כי אם רע מיכיהו בן ימלה ויאמר יהושפט אל יאמר המלך כן׃ ");
INSERT INTO heb_vpl VALUES ("K122_9","012_22_9","1KI","22","9","9","ויקרא מלך ישראל אל סריס אחד ויאמר מהרה מיכיהו בן ימלה׃ ");
INSERT INTO heb_vpl VALUES ("K122_10","012_22_10","1KI","22","10","10","ומלך ישראל ויהושפט מלך יהודה ישבים איש על כסאו מלבשים בגדים בגרן פתח שער שמרון וכל הנביאים מתנבאים לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("K122_11","012_22_11","1KI","22","11","11","ויעש לו צדקיה בן כנענה קרני ברזל ויאמר כה אמר יהוה באלה תנגח את ארם עד כלתם׃ ");
INSERT INTO heb_vpl VALUES ("K122_12","012_22_12","1KI","22","12","12","וכל הנבאים נבאים כן לאמר עלה רמת גלעד והצלח ונתן יהוה ביד המלך׃ ");
INSERT INTO heb_vpl VALUES ("K122_13","012_22_13","1KI","22","13","13","והמלאך אשר הלך לקרא מיכיהו דבר אליו לאמר הנה נא דברי הנביאים פה אחד טוב אל המלך יהי נא דבריך כדבר אחד מהם ודברת טוב׃ ");
INSERT INTO heb_vpl VALUES ("K122_14","012_22_14","1KI","22","14","14","ויאמר מיכיהו חי יהוה כי את אשר יאמר יהוה אלי אתו אדבר׃ ");
INSERT INTO heb_vpl VALUES ("K122_15","012_22_15","1KI","22","15","15","ויבוא אל המלך ויאמר המלך אליו מיכיהו הנלך אל רמת גלעד למלחמה אם נחדל ויאמר אליו עלה והצלח ונתן יהוה ביד המלך׃ ");
INSERT INTO heb_vpl VALUES ("K122_16","012_22_16","1KI","22","16","16","ויאמר אליו המלך עד כמה פעמים אני משבעך אשר לא תדבר אלי רק אמת בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K122_17","012_22_17","1KI","22","17","17","ויאמר ראיתי את כל ישראל נפצים אל ההרים כצאן אשר אין להם רעה ויאמר יהוה לא אדנים לאלה ישובו איש לביתו בשלום׃ ");
INSERT INTO heb_vpl VALUES ("K122_18","012_22_18","1KI","22","18","18","ויאמר מלך ישראל אל יהושפט הלוא אמרתי אליך לוא יתנבא עלי טוב כי אם רע׃ ");
INSERT INTO heb_vpl VALUES ("K122_19","012_22_19","1KI","22","19","19","ויאמר לכן שמע דבר יהוה ראיתי את יהוה ישב על כסאו וכל צבא השמים עמד עליו מימינו ומשמאלו׃ ");
INSERT INTO heb_vpl VALUES ("K122_20","012_22_20","1KI","22","20","20","ויאמר יהוה מי יפתה את אחאב ויעל ויפל ברמת גלעד ויאמר זה בכה וזה אמר בכה׃ ");
INSERT INTO heb_vpl VALUES ("K122_21","012_22_21","1KI","22","21","21","ויצא הרוח ויעמד לפני יהוה ויאמר אני אפתנו ויאמר יהוה אליו במה׃ ");
INSERT INTO heb_vpl VALUES ("K122_22","012_22_22","1KI","22","22","22","ויאמר אצא והייתי רוח שקר בפי כל נביאיו ויאמר תפתה וגם תוכל צא ועשה כן׃ ");
INSERT INTO heb_vpl VALUES ("K122_23","012_22_23","1KI","22","23","23","ועתה הנה נתן יהוה רוח שקר בפי כל נביאיך אלה ויהוה דבר עליך רעה׃ ");
INSERT INTO heb_vpl VALUES ("K122_24","012_22_24","1KI","22","24","24","ויגש צדקיהו בן כנענה ויכה את מיכיהו על הלחי ויאמר אי זה עבר רוח יהוה מאתי לדבר אותך׃ ");
INSERT INTO heb_vpl VALUES ("K122_25","012_22_25","1KI","22","25","25","ויאמר מיכיהו הנך ראה ביום ההוא אשר תבא חדר בחדר להחבה׃ ");
INSERT INTO heb_vpl VALUES ("K122_26","012_22_26","1KI","22","26","26","ויאמר מלך ישראל קח את מיכיהו והשיבהו אל אמן שר העיר ואל יואש בן המלך׃ ");
INSERT INTO heb_vpl VALUES ("K122_27","012_22_27","1KI","22","27","27","ואמרת כה אמר המלך שימו את זה בית הכלא והאכילהו לחם לחץ ומים לחץ עד באי בשלום׃ ");
INSERT INTO heb_vpl VALUES ("K122_28","012_22_28","1KI","22","28","28","ויאמר מיכיהו אם שוב תשוב בשלום לא דבר יהוה בי ויאמר שמעו עמים כלם׃ ");
INSERT INTO heb_vpl VALUES ("K122_29","012_22_29","1KI","22","29","29","ויעל מלך ישראל ויהושפט מלך יהודה רמת גלעד׃ ");
INSERT INTO heb_vpl VALUES ("K122_30","012_22_30","1KI","22","30","30","ויאמר מלך ישראל אל יהושפט התחפש ובא במלחמה ואתה לבש בגדיך ויתחפש מלך ישראל ויבוא במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("K122_31","012_22_31","1KI","22","31","31","ומלך ארם צוה את שרי הרכב אשר לו שלשים ושנים לאמר לא תלחמו את קטן ואת גדול כי אם את מלך ישראל לבדו׃ ");
INSERT INTO heb_vpl VALUES ("K122_32","012_22_32","1KI","22","32","32","ויהי כראות שרי הרכב את יהושפט והמה אמרו אך מלך ישראל הוא ויסרו עליו להלחם ויזעק יהושפט׃ ");
INSERT INTO heb_vpl VALUES ("K122_33","012_22_33","1KI","22","33","33","ויהי כראות שרי הרכב כי לא מלך ישראל הוא וישובו מאחריו׃ ");
INSERT INTO heb_vpl VALUES ("K122_34","012_22_34","1KI","22","34","34","ואיש משך בקשת לתמו ויכה את מלך ישראל בין הדבקים ובין השרין ויאמר לרכבו הפך ידך והוציאני מן המחנה כי החליתי׃ ");
INSERT INTO heb_vpl VALUES ("K122_35","012_22_35","1KI","22","35","35","ותעלה המלחמה ביום ההוא והמלך היה מעמד במרכבה נכח ארם וימת בערב ויצק דם המכה אל חיק הרכב׃ ");
INSERT INTO heb_vpl VALUES ("K122_36","012_22_36","1KI","22","36","36","ויעבר הרנה במחנה כבא השמש לאמר איש אל עירו ואיש אל ארצו׃ ");
INSERT INTO heb_vpl VALUES ("K122_37","012_22_37","1KI","22","37","37","וימת המלך ויבוא שמרון ויקברו את המלך בשמרון׃ ");
INSERT INTO heb_vpl VALUES ("K122_38","012_22_38","1KI","22","38","38","וישטף את הרכב על ברכת שמרון וילקו הכלבים את דמו והזנות רחצו כדבר יהוה אשר דבר׃ ");
INSERT INTO heb_vpl VALUES ("K122_39","012_22_39","1KI","22","39","39","ויתר דברי אחאב וכל אשר עשה ובית השן אשר בנה וכל הערים אשר בנה הלוא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K122_40","012_22_40","1KI","22","40","40","וישכב אחאב עם אבתיו וימלך אחזיהו בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K122_41","012_22_41","1KI","22","41","41","ויהושפט בן אסא מלך על יהודה בשנת ארבע לאחאב מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K122_42","012_22_42","1KI","22","42","42","יהושפט בן שלשים וחמש שנה במלכו ועשרים וחמש שנה מלך בירושלם ושם אמו עזובה בת שלחי׃ ");
INSERT INTO heb_vpl VALUES ("K122_43","012_22_43","1KI","22","43","43","וילך בכל דרך אסא אביו לא סר ממנו לעשות הישר בעיני יהוה אך הבמות לא סרו עוד העם מזבחים ומקטרים בבמות׃ ");
INSERT INTO heb_vpl VALUES ("K122_44","012_22_44","1KI","22","44","44","וישלם יהושפט עם מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K122_45","012_22_45","1KI","22","45","45","ויתר דברי יהושפט וגבורתו אשר עשה ואשר נלחם הלא הם כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K122_46","012_22_46","1KI","22","46","46","ויתר הקדש אשר נשאר בימי אסא אביו בער מן הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K122_47","012_22_47","1KI","22","47","47","ומלך אין באדום נצב מלך׃ ");
INSERT INTO heb_vpl VALUES ("K122_48","012_22_48","1KI","22","48","48","יהושפט עשר אניות תרשיש ללכת אופירה לזהב ולא הלך כי נשברה אניות בעציון גבר׃ ");
INSERT INTO heb_vpl VALUES ("K122_49","012_22_49","1KI","22","49","49","אז אמר אחזיהו בן אחאב אל יהושפט ילכו עבדי עם עבדיך באניות ולא אבה יהושפט׃ ");
INSERT INTO heb_vpl VALUES ("K122_50","012_22_50","1KI","22","50","50","וישכב יהושפט עם אבתיו ויקבר עם אבתיו בעיר דוד אביו וימלך יהורם בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K122_51","012_22_51","1KI","22","51","51","אחזיהו בן אחאב מלך על ישראל בשמרון בשנת שבע עשרה ליהושפט מלך יהודה וימלך על ישראל שנתים׃ ");
INSERT INTO heb_vpl VALUES ("K122_52","012_22_52","1KI","22","52","52","ויעש הרע בעיני יהוה וילך בדרך אביו ובדרך אמו ובדרך ירבעם בן נבט אשר החטיא את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K122_53","012_22_53","1KI","22","53","53","ויעבד את הבעל וישתחוה לו ויכעס את יהוה אלהי ישראל ככל אשר עשה אביו׃ ");
INSERT INTO heb_vpl VALUES ("K21_1","013_1_1","2KI","1","1","1","ויפשע מואב בישראל אחרי מות אחאב׃ ");
INSERT INTO heb_vpl VALUES ("K21_2","013_1_2","2KI","1","2","2","ויפל אחזיה בעד השבכה בעליתו אשר בשמרון ויחל וישלח מלאכים ויאמר אלהם לכו דרשו בבעל זבוב אלהי עקרון אם אחיה מחלי זה׃ ");
INSERT INTO heb_vpl VALUES ("K21_3","013_1_3","2KI","1","3","3","ומלאך יהוה דבר אל אליה התשבי קום עלה לקראת מלאכי מלך שמרון ודבר אלהם המבלי אין אלהים בישראל אתם הלכים לדרש בבעל זבוב אלהי עקרון׃ ");
INSERT INTO heb_vpl VALUES ("K21_4","013_1_4","2KI","1","4","4","ולכן כה אמר יהוה המטה אשר עלית שם לא תרד ממנה כי מות תמות וילך אליה׃ ");
INSERT INTO heb_vpl VALUES ("K21_5","013_1_5","2KI","1","5","5","וישובו המלאכים אליו ויאמר אליהם מה זה שבתם׃ ");
INSERT INTO heb_vpl VALUES ("K21_6","013_1_6","2KI","1","6","6","ויאמרו אליו איש עלה לקראתנו ויאמר אלינו לכו שובו אל המלך אשר שלח אתכם ודברתם אליו כה אמר יהוה המבלי אין אלהים בישראל אתה שלח לדרש בבעל זבוב אלהי עקרון לכן המטה אשר עלית שם לא תרד ממנה כי מות תמות׃ ");
INSERT INTO heb_vpl VALUES ("K21_7","013_1_7","2KI","1","7","7","וידבר אלהם מה משפט האיש אשר עלה לקראתכם וידבר אליכם את הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("K21_8","013_1_8","2KI","1","8","8","ויאמרו אליו איש בעל שער ואזור עור אזור במתניו ויאמר אליה התשבי הוא׃ ");
INSERT INTO heb_vpl VALUES ("K21_9","013_1_9","2KI","1","9","9","וישלח אליו שר חמשים וחמשיו ויעל אליו והנה ישב על ראש ההר וידבר אליו איש האלהים המלך דבר רדה׃ ");
INSERT INTO heb_vpl VALUES ("K21_10","013_1_10","2KI","1","10","10","ויענה אליהו וידבר אל שר החמשים ואם איש אלהים אני תרד אש מן השמים ותאכל אתך ואת חמשיך ותרד אש מן השמים ותאכל אתו ואת חמשיו׃ ");
INSERT INTO heb_vpl VALUES ("K21_11","013_1_11","2KI","1","11","11","וישב וישלח אליו שר חמשים אחר וחמשיו ויען וידבר אליו איש האלהים כה אמר המלך מהרה רדה׃ ");
INSERT INTO heb_vpl VALUES ("K21_12","013_1_12","2KI","1","12","12","ויען אליה וידבר אליהם אם איש האלהים אני תרד אש מן השמים ותאכל אתך ואת חמשיך ותרד אש אלהים מן השמים ותאכל אתו ואת חמשיו׃ ");
INSERT INTO heb_vpl VALUES ("K21_13","013_1_13","2KI","1","13","13","וישב וישלח שר חמשים שלשים וחמשיו ויעל ויבא שר החמשים השלישי ויכרע על ברכיו לנגד אליהו ויתחנן אליו וידבר אליו איש האלהים תיקר נא נפשי ונפש עבדיך אלה חמשים בעיניך׃ ");
INSERT INTO heb_vpl VALUES ("K21_14","013_1_14","2KI","1","14","14","הנה ירדה אש מן השמים ותאכל את שני שרי החמשים הראשנים ואת חמשיהם ועתה תיקר נפשי בעיניך׃ ");
INSERT INTO heb_vpl VALUES ("K21_15","013_1_15","2KI","1","15","15","וידבר מלאך יהוה אל אליהו רד אותו אל תירא מפניו ויקם וירד אותו אל המלך׃ ");
INSERT INTO heb_vpl VALUES ("K21_16","013_1_16","2KI","1","16","16","וידבר אליו כה אמר יהוה יען אשר שלחת מלאכים לדרש בבעל זבוב אלהי עקרון המבלי אין אלהים בישראל לדרש בדברו לכן המטה אשר עלית שם לא תרד ממנה כי מות תמות׃ ");
INSERT INTO heb_vpl VALUES ("K21_17","013_1_17","2KI","1","17","17","וימת כדבר יהוה אשר דבר אליהו וימלך יהורם תחתיו בשנת שתים ליהורם בן יהושפט מלך יהודה כי לא היה לו בן׃ ");
INSERT INTO heb_vpl VALUES ("K21_18","013_1_18","2KI","1","18","18","ויתר דברי אחזיהו אשר עשה הלוא המה כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K22_1","013_2_1","2KI","2","1","1","ויהי בהעלות יהוה את אליהו בסערה השמים וילך אליהו ואלישע מן הגלגל׃ ");
INSERT INTO heb_vpl VALUES ("K22_2","013_2_2","2KI","2","2","2","ויאמר אליהו אל אלישע שב נא פה כי יהוה שלחני עד בית אל ויאמר אלישע חי יהוה וחי נפשך אם אעזבך וירדו בית אל׃ ");
INSERT INTO heb_vpl VALUES ("K22_3","013_2_3","2KI","2","3","3","ויצאו בני הנביאים אשר בית אל אל אלישע ויאמרו אליו הידעת כי היום יהוה לקח את אדניך מעל ראשך ויאמר גם אני ידעתי החשו׃ ");
INSERT INTO heb_vpl VALUES ("K22_4","013_2_4","2KI","2","4","4","ויאמר לו אליהו אלישע שב נא פה כי יהוה שלחני יריחו ויאמר חי יהוה וחי נפשך אם אעזבך ויבאו יריחו׃ ");
INSERT INTO heb_vpl VALUES ("K22_5","013_2_5","2KI","2","5","5","ויגשו בני הנביאים אשר ביריחו אל אלישע ויאמרו אליו הידעת כי היום יהוה לקח את אדניך מעל ראשך ויאמר גם אני ידעתי החשו׃ ");
INSERT INTO heb_vpl VALUES ("K22_6","013_2_6","2KI","2","6","6","ויאמר לו אליהו שב נא פה כי יהוה שלחני הירדנה ויאמר חי יהוה וחי נפשך אם אעזבך וילכו שניהם׃ ");
INSERT INTO heb_vpl VALUES ("K22_7","013_2_7","2KI","2","7","7","וחמשים איש מבני הנביאים הלכו ויעמדו מנגד מרחוק ושניהם עמדו על הירדן׃ ");
INSERT INTO heb_vpl VALUES ("K22_8","013_2_8","2KI","2","8","8","ויקח אליהו את אדרתו ויגלם ויכה את המים ויחצו הנה והנה ויעברו שניהם בחרבה׃ ");
INSERT INTO heb_vpl VALUES ("K22_9","013_2_9","2KI","2","9","9","ויהי כעברם ואליהו אמר אל אלישע שאל מה אעשה לך בטרם אלקח מעמך ויאמר אלישע ויהי נא פי שנים ברוחך אלי׃ ");
INSERT INTO heb_vpl VALUES ("K22_10","013_2_10","2KI","2","10","10","ויאמר הקשית לשאול אם תראה אתי לקח מאתך יהי לך כן ואם אין לא יהיה׃ ");
INSERT INTO heb_vpl VALUES ("K22_11","013_2_11","2KI","2","11","11","ויהי המה הלכים הלוך ודבר והנה רכב אש וסוסי אש ויפרדו בין שניהם ויעל אליהו בסערה השמים׃ ");
INSERT INTO heb_vpl VALUES ("K22_12","013_2_12","2KI","2","12","12","ואלישע ראה והוא מצעק אבי אבי רכב ישראל ופרשיו ולא ראהו עוד ויחזק בבגדיו ויקרעם לשנים קרעים׃ ");
INSERT INTO heb_vpl VALUES ("K22_13","013_2_13","2KI","2","13","13","וירם את אדרת אליהו אשר נפלה מעליו וישב ויעמד על שפת הירדן׃ ");
INSERT INTO heb_vpl VALUES ("K22_14","013_2_14","2KI","2","14","14","ויקח את אדרת אליהו אשר נפלה מעליו ויכה את המים ויאמר איה יהוה אלהי אליהו אף הוא ויכה את המים ויחצו הנה והנה ויעבר אלישע׃ ");
INSERT INTO heb_vpl VALUES ("K22_15","013_2_15","2KI","2","15","15","ויראהו בני הנביאים אשר ביריחו מנגד ויאמרו נחה רוח אליהו על אלישע ויבאו לקראתו וישתחוו לו ארצה׃ ");
INSERT INTO heb_vpl VALUES ("K22_16","013_2_16","2KI","2","16","16","ויאמרו אליו הנה נא יש את עבדיך חמשים אנשים בני חיל ילכו נא ויבקשו את אדניך פן נשאו רוח יהוה וישלכהו באחד ההרים או באחת הגיאות ויאמר לא תשלחו׃ ");
INSERT INTO heb_vpl VALUES ("K22_17","013_2_17","2KI","2","17","17","ויפצרו בו עד בש ויאמר שלחו וישלחו חמשים איש ויבקשו שלשה ימים ולא מצאהו׃ ");
INSERT INTO heb_vpl VALUES ("K22_18","013_2_18","2KI","2","18","18","וישבו אליו והוא ישב ביריחו ויאמר אלהם הלוא אמרתי אליכם אל תלכו׃ ");
INSERT INTO heb_vpl VALUES ("K22_19","013_2_19","2KI","2","19","19","ויאמרו אנשי העיר אל אלישע הנה נא מושב העיר טוב כאשר אדני ראה והמים רעים והארץ משכלת׃ ");
INSERT INTO heb_vpl VALUES ("K22_20","013_2_20","2KI","2","20","20","ויאמר קחו לי צלחית חדשה ושימו שם מלח ויקחו אליו׃ ");
INSERT INTO heb_vpl VALUES ("K22_21","013_2_21","2KI","2","21","21","ויצא אל מוצא המים וישלך שם מלח ויאמר כה אמר יהוה רפאתי למים האלה לא יהיה משם עוד מות ומשכלת׃ ");
INSERT INTO heb_vpl VALUES ("K22_22","013_2_22","2KI","2","22","22","וירפו המים עד היום הזה כדבר אלישע אשר דבר׃ ");
INSERT INTO heb_vpl VALUES ("K22_23","013_2_23","2KI","2","23","23","ויעל משם בית אל והוא עלה בדרך ונערים קטנים יצאו מן העיר ויתקלסו בו ויאמרו לו עלה קרח עלה קרח׃ ");
INSERT INTO heb_vpl VALUES ("K22_24","013_2_24","2KI","2","24","24","ויפן אחריו ויראם ויקללם בשם יהוה ותצאנה שתים דבים מן היער ותבקענה מהם ארבעים ושני ילדים׃ ");
INSERT INTO heb_vpl VALUES ("K22_25","013_2_25","2KI","2","25","25","וילך משם אל הר הכרמל ומשם שב שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K23_1","013_3_1","2KI","3","1","1","ויהורם בן אחאב מלך על ישראל בשמרון בשנת שמנה עשרה ליהושפט מלך יהודה וימלך שתים עשרה שנה׃ ");
INSERT INTO heb_vpl VALUES ("K23_2","013_3_2","2KI","3","2","2","ויעשה הרע בעיני יהוה רק לא כאביו וכאמו ויסר את מצבת הבעל אשר עשה אביו׃ ");
INSERT INTO heb_vpl VALUES ("K23_3","013_3_3","2KI","3","3","3","רק בחטאות ירבעם בן נבט אשר החטיא את ישראל דבק לא סר ממנה׃ ");
INSERT INTO heb_vpl VALUES ("K23_4","013_3_4","2KI","3","4","4","ומישע מלך מואב היה נקד והשיב למלך ישראל מאה אלף כרים ומאה אלף אילים צמר׃ ");
INSERT INTO heb_vpl VALUES ("K23_5","013_3_5","2KI","3","5","5","ויהי כמות אחאב ויפשע מלך מואב במלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K23_6","013_3_6","2KI","3","6","6","ויצא המלך יהורם ביום ההוא משמרון ויפקד את כל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K23_7","013_3_7","2KI","3","7","7","וילך וישלח אל יהושפט מלך יהודה לאמר מלך מואב פשע בי התלך אתי אל מואב למלחמה ויאמר אעלה כמוני כמוך כעמי כעמך כסוסי כסוסיך׃ ");
INSERT INTO heb_vpl VALUES ("K23_8","013_3_8","2KI","3","8","8","ויאמר אי זה הדרך נעלה ויאמר דרך מדבר אדום׃ ");
INSERT INTO heb_vpl VALUES ("K23_9","013_3_9","2KI","3","9","9","וילך מלך ישראל ומלך יהודה ומלך אדום ויסבו דרך שבעת ימים ולא היה מים למחנה ולבהמה אשר ברגליהם׃ ");
INSERT INTO heb_vpl VALUES ("K23_10","013_3_10","2KI","3","10","10","ויאמר מלך ישראל אהה כי קרא יהוה לשלשת המלכים האלה לתת אותם ביד מואב׃ ");
INSERT INTO heb_vpl VALUES ("K23_11","013_3_11","2KI","3","11","11","ויאמר יהושפט האין פה נביא ליהוה ונדרשה את יהוה מאותו ויען אחד מעבדי מלך ישראל ויאמר פה אלישע בן שפט אשר יצק מים על ידי אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K23_12","013_3_12","2KI","3","12","12","ויאמר יהושפט יש אותו דבר יהוה וירדו אליו מלך ישראל ויהושפט ומלך אדום׃ ");
INSERT INTO heb_vpl VALUES ("K23_13","013_3_13","2KI","3","13","13","ויאמר אלישע אל מלך ישראל מה לי ולך לך אל נביאי אביך ואל נביאי אמך ויאמר לו מלך ישראל אל כי קרא יהוה לשלשת המלכים האלה לתת אותם ביד מואב׃ ");
INSERT INTO heb_vpl VALUES ("K23_14","013_3_14","2KI","3","14","14","ויאמר אלישע חי יהוה צבאות אשר עמדתי לפניו כי לולי פני יהושפט מלך יהודה אני נשא אם אביט אליך ואם אראך׃ ");
INSERT INTO heb_vpl VALUES ("K23_15","013_3_15","2KI","3","15","15","ועתה קחו לי מנגן והיה כנגן המנגן ותהי עליו יד יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K23_16","013_3_16","2KI","3","16","16","ויאמר כה אמר יהוה עשה הנחל הזה גבים גבים׃ ");
INSERT INTO heb_vpl VALUES ("K23_17","013_3_17","2KI","3","17","17","כי כה אמר יהוה לא תראו רוח ולא תראו גשם והנחל ההוא ימלא מים ושתיתם אתם ומקניכם ובהמתכם׃ ");
INSERT INTO heb_vpl VALUES ("K23_18","013_3_18","2KI","3","18","18","ונקל זאת בעיני יהוה ונתן את מואב בידכם׃ ");
INSERT INTO heb_vpl VALUES ("K23_19","013_3_19","2KI","3","19","19","והכיתם כל עיר מבצר וכל עיר מבחור וכל עץ טוב תפילו וכל מעיני מים תסתמו וכל החלקה הטובה תכאבו באבנים׃ ");
INSERT INTO heb_vpl VALUES ("K23_20","013_3_20","2KI","3","20","20","ויהי בבקר כעלות המנחה והנה מים באים מדרך אדום ותמלא הארץ את המים׃ ");
INSERT INTO heb_vpl VALUES ("K23_21","013_3_21","2KI","3","21","21","וכל מואב שמעו כי עלו המלכים להלחם בם ויצעקו מכל חגר חגרה ומעלה ויעמדו על הגבול׃ ");
INSERT INTO heb_vpl VALUES ("K23_22","013_3_22","2KI","3","22","22","וישכימו בבקר והשמש זרחה על המים ויראו מואב מנגד את המים אדמים כדם׃ ");
INSERT INTO heb_vpl VALUES ("K23_23","013_3_23","2KI","3","23","23","ויאמרו דם זה החרב נחרבו המלכים ויכו איש את רעהו ועתה לשלל מואב׃ ");
INSERT INTO heb_vpl VALUES ("K23_24","013_3_24","2KI","3","24","24","ויבאו אל מחנה ישראל ויקמו ישראל ויכו את מואב וינסו מפניהם ויבו בה והכות את מואב׃ ");
INSERT INTO heb_vpl VALUES ("K23_25","013_3_25","2KI","3","25","25","והערים יהרסו וכל חלקה טובה ישליכו איש אבנו ומלאוה וכל מעין מים יסתמו וכל עץ טוב יפילו עד השאיר אבניה בקיר חרשת ויסבו הקלעים ויכוה׃ ");
INSERT INTO heb_vpl VALUES ("K23_26","013_3_26","2KI","3","26","26","וירא מלך מואב כי חזק ממנו המלחמה ויקח אותו שבע מאות איש שלף חרב להבקיע אל מלך אדום ולא יכלו׃ ");
INSERT INTO heb_vpl VALUES ("K23_27","013_3_27","2KI","3","27","27","ויקח את בנו הבכור אשר ימלך תחתיו ויעלהו עלה על החמה ויהי קצף גדול על ישראל ויסעו מעליו וישבו לארץ׃ ");
INSERT INTO heb_vpl VALUES ("K24_1","013_4_1","2KI","4","1","1","ואשה אחת מנשי בני הנביאים צעקה אל אלישע לאמר עבדך אישי מת ואתה ידעת כי עבדך היה ירא את יהוה והנשה בא לקחת את שני ילדי לו לעבדים׃ ");
INSERT INTO heb_vpl VALUES ("K24_2","013_4_2","2KI","4","2","2","ויאמר אליה אלישע מה אעשה לך הגידי לי מה יש לכי בבית ותאמר אין לשפחתך כל בבית כי אם אסוך שמן׃ ");
INSERT INTO heb_vpl VALUES ("K24_3","013_4_3","2KI","4","3","3","ויאמר לכי שאלי לך כלים מן החוץ מאת כל שכנכי כלים רקים אל תמעיטי׃ ");
INSERT INTO heb_vpl VALUES ("K24_4","013_4_4","2KI","4","4","4","ובאת וסגרת הדלת בעדך ובעד בניך ויצקת על כל הכלים האלה והמלא תסיעי׃ ");
INSERT INTO heb_vpl VALUES ("K24_5","013_4_5","2KI","4","5","5","ותלך מאתו ותסגר הדלת בעדה ובעד בניה הם מגשים אליה והיא מיצקת׃ ");
INSERT INTO heb_vpl VALUES ("K24_6","013_4_6","2KI","4","6","6","ויהי כמלאת הכלים ותאמר אל בנה הגישה אלי עוד כלי ויאמר אליה אין עוד כלי ויעמד השמן׃ ");
INSERT INTO heb_vpl VALUES ("K24_7","013_4_7","2KI","4","7","7","ותבא ותגד לאיש האלהים ויאמר לכי מכרי את השמן ושלמי את נשיכי ואת בניכי תחיי בנותר׃ ");
INSERT INTO heb_vpl VALUES ("K24_8","013_4_8","2KI","4","8","8","ויהי היום ויעבר אלישע אל שונם ושם אשה גדולה ותחזק בו לאכל לחם ויהי מדי עברו יסר שמה לאכל לחם׃ ");
INSERT INTO heb_vpl VALUES ("K24_9","013_4_9","2KI","4","9","9","ותאמר אל אישה הנה נא ידעתי כי איש אלהים קדוש הוא עבר עלינו תמיד׃ ");
INSERT INTO heb_vpl VALUES ("K24_10","013_4_10","2KI","4","10","10","נעשה נא עלית קיר קטנה ונשים לו שם מטה ושלחן וכסא ומנורה והיה בבאו אלינו יסור שמה׃ ");
INSERT INTO heb_vpl VALUES ("K24_11","013_4_11","2KI","4","11","11","ויהי היום ויבא שמה ויסר אל העליה וישכב שמה׃ ");
INSERT INTO heb_vpl VALUES ("K24_12","013_4_12","2KI","4","12","12","ויאמר אל גחזי נערו קרא לשונמית הזאת ויקרא לה ותעמד לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K24_13","013_4_13","2KI","4","13","13","ויאמר לו אמר נא אליה הנה חרדת אלינו את כל החרדה הזאת מה לעשות לך היש לדבר לך אל המלך או אל שר הצבא ותאמר בתוך עמי אנכי ישבת׃ ");
INSERT INTO heb_vpl VALUES ("K24_14","013_4_14","2KI","4","14","14","ויאמר ומה לעשות לה ויאמר גיחזי אבל בן אין לה ואישה זקן׃ ");
INSERT INTO heb_vpl VALUES ("K24_15","013_4_15","2KI","4","15","15","ויאמר קרא לה ויקרא לה ותעמד בפתח׃ ");
INSERT INTO heb_vpl VALUES ("K24_16","013_4_16","2KI","4","16","16","ויאמר למועד הזה כעת חיה אתי חבקת בן ותאמר אל אדני איש האלהים אל תכזב בשפחתך׃ ");
INSERT INTO heb_vpl VALUES ("K24_17","013_4_17","2KI","4","17","17","ותהר האשה ותלד בן למועד הזה כעת חיה אשר דבר אליה אלישע׃ ");
INSERT INTO heb_vpl VALUES ("K24_18","013_4_18","2KI","4","18","18","ויגדל הילד ויהי היום ויצא אל אביו אל הקצרים׃ ");
INSERT INTO heb_vpl VALUES ("K24_19","013_4_19","2KI","4","19","19","ויאמר אל אביו ראשי ראשי ויאמר אל הנער שאהו אל אמו׃ ");
INSERT INTO heb_vpl VALUES ("K24_20","013_4_20","2KI","4","20","20","וישאהו ויביאהו אל אמו וישב על ברכיה עד הצהרים וימת׃ ");
INSERT INTO heb_vpl VALUES ("K24_21","013_4_21","2KI","4","21","21","ותעל ותשכבהו על מטת איש האלהים ותסגר בעדו ותצא׃ ");
INSERT INTO heb_vpl VALUES ("K24_22","013_4_22","2KI","4","22","22","ותקרא אל אישה ותאמר שלחה נא לי אחד מן הנערים ואחת האתנות וארוצה עד איש האלהים ואשובה׃ ");
INSERT INTO heb_vpl VALUES ("K24_23","013_4_23","2KI","4","23","23","ויאמר מדוע אתי הלכתי אליו היום לא חדש ולא שבת ותאמר שלום׃ ");
INSERT INTO heb_vpl VALUES ("K24_24","013_4_24","2KI","4","24","24","ותחבש האתון ותאמר אל נערה נהג ולך אל תעצר לי לרכב כי אם אמרתי לך׃ ");
INSERT INTO heb_vpl VALUES ("K24_25","013_4_25","2KI","4","25","25","ותלך ותבוא אל איש האלהים אל הר הכרמל ויהי כראות איש האלהים אתה מנגד ויאמר אל גיחזי נערו הנה השונמית הלז׃ ");
INSERT INTO heb_vpl VALUES ("K24_26","013_4_26","2KI","4","26","26","עתה רוץ נא לקראתה ואמר לה השלום לך השלום לאישך השלום לילד ותאמר שלום׃ ");
INSERT INTO heb_vpl VALUES ("K24_27","013_4_27","2KI","4","27","27","ותבא אל איש האלהים אל ההר ותחזק ברגליו ויגש גיחזי להדפה ויאמר איש האלהים הרפה לה כי נפשה מרה לה ויהוה העלים ממני ולא הגיד לי׃ ");
INSERT INTO heb_vpl VALUES ("K24_28","013_4_28","2KI","4","28","28","ותאמר השאלתי בן מאת אדני הלא אמרתי לא תשלה אתי׃ ");
INSERT INTO heb_vpl VALUES ("K24_29","013_4_29","2KI","4","29","29","ויאמר לגיחזי חגר מתניך וקח משענתי בידך ולך כי תמצא איש לא תברכנו וכי יברכך איש לא תעננו ושמת משענתי על פני הנער׃ ");
INSERT INTO heb_vpl VALUES ("K24_30","013_4_30","2KI","4","30","30","ותאמר אם הנער חי יהוה וחי נפשך אם אעזבך ויקם וילך אחריה׃ ");
INSERT INTO heb_vpl VALUES ("K24_31","013_4_31","2KI","4","31","31","וגחזי עבר לפניהם וישם את המשענת על פני הנער ואין קול ואין קשב וישב לקראתו ויגד לו לאמר לא הקיץ הנער׃ ");
INSERT INTO heb_vpl VALUES ("K24_32","013_4_32","2KI","4","32","32","ויבא אלישע הביתה והנה הנער מת משכב על מטתו׃ ");
INSERT INTO heb_vpl VALUES ("K24_33","013_4_33","2KI","4","33","33","ויבא ויסגר הדלת בעד שניהם ויתפלל אל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K24_34","013_4_34","2KI","4","34","34","ויעל וישכב על הילד וישם פיו על פיו ועיניו על עיניו וכפיו על כפו ויגהר עליו ויחם בשר הילד׃ ");
INSERT INTO heb_vpl VALUES ("K24_35","013_4_35","2KI","4","35","35","וישב וילך בבית אחת הנה ואחת הנה ויעל ויגהר עליו ויזורר הנער עד שבע פעמים ויפקח הנער את עיניו׃ ");
INSERT INTO heb_vpl VALUES ("K24_36","013_4_36","2KI","4","36","36","ויקרא אל גיחזי ויאמר קרא אל השנמית הזאת ויקראה ותבוא אליו ויאמר שאי בנך׃ ");
INSERT INTO heb_vpl VALUES ("K24_37","013_4_37","2KI","4","37","37","ותבא ותפל על רגליו ותשתחו ארצה ותשא את בנה ותצא׃ ");
INSERT INTO heb_vpl VALUES ("K24_38","013_4_38","2KI","4","38","38","ואלישע שב הגלגלה והרעב בארץ ובני הנביאים ישבים לפניו ויאמר לנערו שפת הסיר הגדולה ובשל נזיד לבני הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("K24_39","013_4_39","2KI","4","39","39","ויצא אחד אל השדה ללקט ארת וימצא גפן שדה וילקט ממנו פקעת שדה מלא בגדו ויבא ויפלח אל סיר הנזיד כי לא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("K24_40","013_4_40","2KI","4","40","40","ויצקו לאנשים לאכול ויהי כאכלם מהנזיד והמה צעקו ויאמרו מות בסיר איש האלהים ולא יכלו לאכל׃ ");
INSERT INTO heb_vpl VALUES ("K24_41","013_4_41","2KI","4","41","41","ויאמר וקחו קמח וישלך אל הסיר ויאמר צק לעם ויאכלו ולא היה דבר רע בסיר׃ ");
INSERT INTO heb_vpl VALUES ("K24_42","013_4_42","2KI","4","42","42","ואיש בא מבעל שלשה ויבא לאיש האלהים לחם בכורים עשרים לחם שערים וכרמל בצקלנו ויאמר תן לעם ויאכלו׃ ");
INSERT INTO heb_vpl VALUES ("K24_43","013_4_43","2KI","4","43","43","ויאמר משרתו מה אתן זה לפני מאה איש ויאמר תן לעם ויאכלו כי כה אמר יהוה אכל והותר׃ ");
INSERT INTO heb_vpl VALUES ("K24_44","013_4_44","2KI","4","44","44","ויתן לפניהם ויאכלו ויותרו כדבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K25_1","013_5_1","2KI","5","1","1","ונעמן שר צבא מלך ארם היה איש גדול לפני אדניו ונשא פנים כי בו נתן יהוה תשועה לארם והאיש היה גבור חיל מצרע׃ ");
INSERT INTO heb_vpl VALUES ("K25_2","013_5_2","2KI","5","2","2","וארם יצאו גדודים וישבו מארץ ישראל נערה קטנה ותהי לפני אשת נעמן׃ ");
INSERT INTO heb_vpl VALUES ("K25_3","013_5_3","2KI","5","3","3","ותאמר אל גברתה אחלי אדני לפני הנביא אשר בשמרון אז יאסף אתו מצרעתו׃ ");
INSERT INTO heb_vpl VALUES ("K25_4","013_5_4","2KI","5","4","4","ויבא ויגד לאדניו לאמר כזאת וכזאת דברה הנערה אשר מארץ ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K25_5","013_5_5","2KI","5","5","5","ויאמר מלך ארם לך בא ואשלחה ספר אל מלך ישראל וילך ויקח בידו עשר ככרי כסף וששת אלפים זהב ועשר חליפות בגדים׃ ");
INSERT INTO heb_vpl VALUES ("K25_6","013_5_6","2KI","5","6","6","ויבא הספר אל מלך ישראל לאמר ועתה כבוא הספר הזה אליך הנה שלחתי אליך את נעמן עבדי ואספתו מצרעתו׃ ");
INSERT INTO heb_vpl VALUES ("K25_7","013_5_7","2KI","5","7","7","ויהי כקרא מלך ישראל את הספר ויקרע בגדיו ויאמר האלהים אני להמית ולהחיות כי זה שלח אלי לאסף איש מצרעתו כי אך דעו נא וראו כי מתאנה הוא לי׃ ");
INSERT INTO heb_vpl VALUES ("K25_8","013_5_8","2KI","5","8","8","ויהי כשמע אלישע איש האלהים כי קרע מלך ישראל את בגדיו וישלח אל המלך לאמר למה קרעת בגדיך יבא נא אלי וידע כי יש נביא בישראל׃ ");
INSERT INTO heb_vpl VALUES ("K25_9","013_5_9","2KI","5","9","9","ויבא נעמן בסוסו וברכבו ויעמד פתח הבית לאלישע׃ ");
INSERT INTO heb_vpl VALUES ("K25_10","013_5_10","2KI","5","10","10","וישלח אליו אלישע מלאך לאמר הלוך ורחצת שבע פעמים בירדן וישב בשרך לך וטהר׃ ");
INSERT INTO heb_vpl VALUES ("K25_11","013_5_11","2KI","5","11","11","ויקצף נעמן וילך ויאמר הנה אמרתי אלי יצא יצוא ועמד וקרא בשם יהוה אלהיו והניף ידו אל המקום ואסף המצרע׃ ");
INSERT INTO heb_vpl VALUES ("K25_12","013_5_12","2KI","5","12","12","הלא טוב אבנה ופרפר נהרות דמשק מכל מימי ישראל הלא ארחץ בהם וטהרתי ויפן וילך בחמה׃ ");
INSERT INTO heb_vpl VALUES ("K25_13","013_5_13","2KI","5","13","13","ויגשו עבדיו וידברו אליו ויאמרו אבי דבר גדול הנביא דבר אליך הלוא תעשה ואף כי אמר אליך רחץ וטהר׃ ");
INSERT INTO heb_vpl VALUES ("K25_14","013_5_14","2KI","5","14","14","וירד ויטבל בירדן שבע פעמים כדבר איש האלהים וישב בשרו כבשר נער קטן ויטהר׃ ");
INSERT INTO heb_vpl VALUES ("K25_15","013_5_15","2KI","5","15","15","וישב אל איש האלהים הוא וכל מחנהו ויבא ויעמד לפניו ויאמר הנה נא ידעתי כי אין אלהים בכל הארץ כי אם בישראל ועתה קח נא ברכה מאת עבדך׃ ");
INSERT INTO heb_vpl VALUES ("K25_16","013_5_16","2KI","5","16","16","ויאמר חי יהוה אשר עמדתי לפניו אם אקח ויפצר בו לקחת וימאן׃ ");
INSERT INTO heb_vpl VALUES ("K25_17","013_5_17","2KI","5","17","17","ויאמר נעמן ולא יתן נא לעבדך משא צמד פרדים אדמה כי לוא יעשה עוד עבדך עלה וזבח לאלהים אחרים כי אם ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("K25_18","013_5_18","2KI","5","18","18","לדבר הזה יסלח יהוה לעבדך בבוא אדני בית רמון להשתחות שמה והוא נשען על ידי והשתחויתי בית רמן בהשתחויתי בית רמן יסלח נא יהוה לעבדך בדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("K25_19","013_5_19","2KI","5","19","19","ויאמר לו לך לשלום וילך מאתו כברת ארץ׃ ");
INSERT INTO heb_vpl VALUES ("K25_20","013_5_20","2KI","5","20","20","ויאמר גיחזי נער אלישע איש האלהים הנה חשך אדני את נעמן הארמי הזה מקחת מידו את אשר הביא חי יהוה כי אם רצתי אחריו ולקחתי מאתו מאומה׃ ");
INSERT INTO heb_vpl VALUES ("K25_21","013_5_21","2KI","5","21","21","וירדף גיחזי אחרי נעמן ויראה נעמן רץ אחריו ויפל מעל המרכבה לקראתו ויאמר השלום׃ ");
INSERT INTO heb_vpl VALUES ("K25_22","013_5_22","2KI","5","22","22","ויאמר שלום אדני שלחני לאמר הנה עתה זה באו אלי שני נערים מהר אפרים מבני הנביאים תנה נא להם ככר כסף ושתי חלפות בגדים׃ ");
INSERT INTO heb_vpl VALUES ("K25_23","013_5_23","2KI","5","23","23","ויאמר נעמן הואל קח ככרים ויפרץ בו ויצר ככרים כסף בשני חרטים ושתי חלפות בגדים ויתן אל שני נעריו וישאו לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K25_24","013_5_24","2KI","5","24","24","ויבא אל העפל ויקח מידם ויפקד בבית וישלח את האנשים וילכו׃ ");
INSERT INTO heb_vpl VALUES ("K25_25","013_5_25","2KI","5","25","25","והוא בא ויעמד אל אדניו ויאמר אליו אלישע מאן גחזי ויאמר לא הלך עבדך אנה ואנה׃ ");
INSERT INTO heb_vpl VALUES ("K25_26","013_5_26","2KI","5","26","26","ויאמר אליו לא לבי הלך כאשר הפך איש מעל מרכבתו לקראתך העת לקחת את הכסף ולקחת בגדים וזיתים וכרמים וצאן ובקר ועבדים ושפחות׃ ");
INSERT INTO heb_vpl VALUES ("K25_27","013_5_27","2KI","5","27","27","וצרעת נעמן תדבק בך ובזרעך לעולם ויצא מלפניו מצרע כשלג׃ ");
INSERT INTO heb_vpl VALUES ("K26_1","013_6_1","2KI","6","1","1","ויאמרו בני הנביאים אל אלישע הנה נא המקום אשר אנחנו ישבים שם לפניך צר ממנו׃ ");
INSERT INTO heb_vpl VALUES ("K26_2","013_6_2","2KI","6","2","2","נלכה נא עד הירדן ונקחה משם איש קורה אחת ונעשה לנו שם מקום לשבת שם ויאמר לכו׃ ");
INSERT INTO heb_vpl VALUES ("K26_3","013_6_3","2KI","6","3","3","ויאמר האחד הואל נא ולך את עבדיך ויאמר אני אלך׃ ");
INSERT INTO heb_vpl VALUES ("K26_4","013_6_4","2KI","6","4","4","וילך אתם ויבאו הירדנה ויגזרו העצים׃ ");
INSERT INTO heb_vpl VALUES ("K26_5","013_6_5","2KI","6","5","5","ויהי האחד מפיל הקורה ואת הברזל נפל אל המים ויצעק ויאמר אהה אדני והוא שאול׃ ");
INSERT INTO heb_vpl VALUES ("K26_6","013_6_6","2KI","6","6","6","ויאמר איש האלהים אנה נפל ויראהו את המקום ויקצב עץ וישלך שמה ויצף הברזל׃ ");
INSERT INTO heb_vpl VALUES ("K26_7","013_6_7","2KI","6","7","7","ויאמר הרם לך וישלח ידו ויקחהו׃ ");
INSERT INTO heb_vpl VALUES ("K26_8","013_6_8","2KI","6","8","8","ומלך ארם היה נלחם בישראל ויועץ אל עבדיו לאמר אל מקום פלני אלמני תחנתי׃ ");
INSERT INTO heb_vpl VALUES ("K26_9","013_6_9","2KI","6","9","9","וישלח איש האלהים אל מלך ישראל לאמר השמר מעבר המקום הזה כי שם ארם נחתים׃ ");
INSERT INTO heb_vpl VALUES ("K26_10","013_6_10","2KI","6","10","10","וישלח מלך ישראל אל המקום אשר אמר לו איש האלהים והזהירה ונשמר שם לא אחת ולא שתים׃ ");
INSERT INTO heb_vpl VALUES ("K26_11","013_6_11","2KI","6","11","11","ויסער לב מלך ארם על הדבר הזה ויקרא אל עבדיו ויאמר אליהם הלוא תגידו לי מי משלנו אל מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K26_12","013_6_12","2KI","6","12","12","ויאמר אחד מעבדיו לוא אדני המלך כי אלישע הנביא אשר בישראל יגיד למלך ישראל את הדברים אשר תדבר בחדר משכבך׃ ");
INSERT INTO heb_vpl VALUES ("K26_13","013_6_13","2KI","6","13","13","ויאמר לכו וראו איכה הוא ואשלח ואקחהו ויגד לו לאמר הנה בדתן׃ ");
INSERT INTO heb_vpl VALUES ("K26_14","013_6_14","2KI","6","14","14","וישלח שמה סוסים ורכב וחיל כבד ויבאו לילה ויקפו על העיר׃ ");
INSERT INTO heb_vpl VALUES ("K26_15","013_6_15","2KI","6","15","15","וישכם משרת איש האלהים לקום ויצא והנה חיל סובב את העיר וסוס ורכב ויאמר נערו אליו אהה אדני איכה נעשה׃ ");
INSERT INTO heb_vpl VALUES ("K26_16","013_6_16","2KI","6","16","16","ויאמר אל תירא כי רבים אשר אתנו מאשר אותם׃ ");
INSERT INTO heb_vpl VALUES ("K26_17","013_6_17","2KI","6","17","17","ויתפלל אלישע ויאמר יהוה פקח נא את עיניו ויראה ויפקח יהוה את עיני הנער וירא והנה ההר מלא סוסים ורכב אש סביבת אלישע׃ ");
INSERT INTO heb_vpl VALUES ("K26_18","013_6_18","2KI","6","18","18","וירדו אליו ויתפלל אלישע אל יהוה ויאמר הך נא את הגוי הזה בסנורים ויכם בסנורים כדבר אלישע׃ ");
INSERT INTO heb_vpl VALUES ("K26_19","013_6_19","2KI","6","19","19","ויאמר אלהם אלישע לא זה הדרך ולא זה העיר לכו אחרי ואוליכה אתכם אל האיש אשר תבקשון וילך אותם שמרונה׃ ");
INSERT INTO heb_vpl VALUES ("K26_20","013_6_20","2KI","6","20","20","ויהי כבאם שמרון ויאמר אלישע יהוה פקח את עיני אלה ויראו ויפקח יהוה את עיניהם ויראו והנה בתוך שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K26_21","013_6_21","2KI","6","21","21","ויאמר מלך ישראל אל אלישע כראתו אותם האכה אכה אבי׃ ");
INSERT INTO heb_vpl VALUES ("K26_22","013_6_22","2KI","6","22","22","ויאמר לא תכה האשר שבית בחרבך ובקשתך אתה מכה שים לחם ומים לפניהם ויאכלו וישתו וילכו אל אדניהם׃ ");
INSERT INTO heb_vpl VALUES ("K26_23","013_6_23","2KI","6","23","23","ויכרה להם כרה גדולה ויאכלו וישתו וישלחם וילכו אל אדניהם ולא יספו עוד גדודי ארם לבוא בארץ ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K26_24","013_6_24","2KI","6","24","24","ויהי אחרי כן ויקבץ בן הדד מלך ארם את כל מחנהו ויעל ויצר על שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K26_25","013_6_25","2KI","6","25","25","ויהי רעב גדול בשמרון והנה צרים עליה עד היות ראש חמור בשמנים כסף ורבע הקב חרייונים בחמשה כסף׃ ");
INSERT INTO heb_vpl VALUES ("K26_26","013_6_26","2KI","6","26","26","ויהי מלך ישראל עבר על החמה ואשה צעקה אליו לאמר הושיעה אדני המלך׃ ");
INSERT INTO heb_vpl VALUES ("K26_27","013_6_27","2KI","6","27","27","ויאמר אל יושעך יהוה מאין אושיעך המן הגרן או מן היקב׃ ");
INSERT INTO heb_vpl VALUES ("K26_28","013_6_28","2KI","6","28","28","ויאמר לה המלך מה לך ותאמר האשה הזאת אמרה אלי תני את בנך ונאכלנו היום ואת בני נאכל מחר׃ ");
INSERT INTO heb_vpl VALUES ("K26_29","013_6_29","2KI","6","29","29","ונבשל את בני ונאכלהו ואמר אליה ביום האחר תני את בנך ונאכלנו ותחבא את בנה׃ ");
INSERT INTO heb_vpl VALUES ("K26_30","013_6_30","2KI","6","30","30","ויהי כשמע המלך את דברי האשה ויקרע את בגדיו והוא עבר על החמה וירא העם והנה השק על בשרו מבית׃ ");
INSERT INTO heb_vpl VALUES ("K26_31","013_6_31","2KI","6","31","31","ויאמר כה יעשה לי אלהים וכה יוסף אם יעמד ראש אלישע בן שפט עליו היום׃ ");
INSERT INTO heb_vpl VALUES ("K26_32","013_6_32","2KI","6","32","32","ואלישע ישב בביתו והזקנים ישבים אתו וישלח איש מלפניו בטרם יבא המלאך אליו והוא אמר אל הזקנים הראיתם כי שלח בן המרצח הזה להסיר את ראשי ראו כבא המלאך סגרו הדלת ולחצתם אתו בדלת הלוא קול רגלי אדניו אחריו׃ ");
INSERT INTO heb_vpl VALUES ("K26_33","013_6_33","2KI","6","33","33","עודנו מדבר עמם והנה המלאך ירד אליו ויאמר הנה זאת הרעה מאת יהוה מה אוחיל ליהוה עוד׃ ");
INSERT INTO heb_vpl VALUES ("K27_1","013_7_1","2KI","7","1","1","ויאמר אלישע שמעו דבר יהוה כה אמר יהוה כעת מחר סאה סלת בשקל וסאתים שערים בשקל בשער שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K27_2","013_7_2","2KI","7","2","2","ויען השליש אשר למלך נשען על ידו את איש האלהים ויאמר הנה יהוה עשה ארבות בשמים היהיה הדבר הזה ויאמר הנכה ראה בעיניך ומשם לא תאכל׃ ");
INSERT INTO heb_vpl VALUES ("K27_3","013_7_3","2KI","7","3","3","וארבעה אנשים היו מצרעים פתח השער ויאמרו איש אל רעהו מה אנחנו ישבים פה עד מתנו׃ ");
INSERT INTO heb_vpl VALUES ("K27_4","013_7_4","2KI","7","4","4","אם אמרנו נבוא העיר והרעב בעיר ומתנו שם ואם ישבנו פה ומתנו ועתה לכו ונפלה אל מחנה ארם אם יחינו נחיה ואם ימיתנו ומתנו׃ ");
INSERT INTO heb_vpl VALUES ("K27_5","013_7_5","2KI","7","5","5","ויקומו בנשף לבוא אל מחנה ארם ויבאו עד קצה מחנה ארם והנה אין שם איש׃ ");
INSERT INTO heb_vpl VALUES ("K27_6","013_7_6","2KI","7","6","6","ואדני השמיע את מחנה ארם קול רכב קול סוס קול חיל גדול ויאמרו איש אל אחיו הנה שכר עלינו מלך ישראל את מלכי החתים ואת מלכי מצרים לבוא עלינו׃ ");
INSERT INTO heb_vpl VALUES ("K27_7","013_7_7","2KI","7","7","7","ויקומו וינוסו בנשף ויעזבו את אהליהם ואת סוסיהם ואת חמריהם המחנה כאשר היא וינסו אל נפשם׃ ");
INSERT INTO heb_vpl VALUES ("K27_8","013_7_8","2KI","7","8","8","ויבאו המצרעים האלה עד קצה המחנה ויבאו אל אהל אחד ויאכלו וישתו וישאו משם כסף וזהב ובגדים וילכו ויטמנו וישבו ויבאו אל אהל אחר וישאו משם וילכו ויטמנו׃ ");
INSERT INTO heb_vpl VALUES ("K27_9","013_7_9","2KI","7","9","9","ויאמרו איש אל רעהו לא כן אנחנו עשים היום הזה יום בשרה הוא ואנחנו מחשים וחכינו עד אור הבקר ומצאנו עוון ועתה לכו ונבאה ונגידה בית המלך׃ ");
INSERT INTO heb_vpl VALUES ("K27_10","013_7_10","2KI","7","10","10","ויבאו ויקראו אל שער העיר ויגידו להם לאמר באנו אל מחנה ארם והנה אין שם איש וקול אדם כי אם הסוס אסור והחמור אסור ואהלים כאשר המה׃ ");
INSERT INTO heb_vpl VALUES ("K27_11","013_7_11","2KI","7","11","11","ויקרא השערים ויגידו בית המלך פנימה׃ ");
INSERT INTO heb_vpl VALUES ("K27_12","013_7_12","2KI","7","12","12","ויקם המלך לילה ויאמר אל עבדיו אגידה נא לכם את אשר עשו לנו ארם ידעו כי רעבים אנחנו ויצאו מן המחנה להחבה בהשדה לאמר כי יצאו מן העיר ונתפשם חיים ואל העיר נבא׃ ");
INSERT INTO heb_vpl VALUES ("K27_13","013_7_13","2KI","7","13","13","ויען אחד מעבדיו ויאמר ויקחו נא חמשה מן הסוסים הנשארים אשר נשארו בה הנם ככל ההמון ישראל אשר נשארו בה הנם ככל המון ישראל אשר תמו ונשלחה ונראה׃ ");
INSERT INTO heb_vpl VALUES ("K27_14","013_7_14","2KI","7","14","14","ויקחו שני רכב סוסים וישלח המלך אחרי מחנה ארם לאמר לכו וראו׃ ");
INSERT INTO heb_vpl VALUES ("K27_15","013_7_15","2KI","7","15","15","וילכו אחריהם עד הירדן והנה כל הדרך מלאה בגדים וכלים אשר השליכו ארם בהחפזם וישבו המלאכים ויגדו למלך׃ ");
INSERT INTO heb_vpl VALUES ("K27_16","013_7_16","2KI","7","16","16","ויצא העם ויבזו את מחנה ארם ויהי סאה סלת בשקל וסאתים שערים בשקל כדבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K27_17","013_7_17","2KI","7","17","17","והמלך הפקיד את השליש אשר נשען על ידו על השער וירמסהו העם בשער וימת כאשר דבר איש האלהים אשר דבר ברדת המלך אליו׃ ");
INSERT INTO heb_vpl VALUES ("K27_18","013_7_18","2KI","7","18","18","ויהי כדבר איש האלהים אל המלך לאמר סאתים שערים בשקל וסאה סלת בשקל יהיה כעת מחר בשער שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K27_19","013_7_19","2KI","7","19","19","ויען השליש את איש האלהים ויאמר והנה יהוה עשה ארבות בשמים היהיה כדבר הזה ויאמר הנך ראה בעיניך ומשם לא תאכל׃ ");
INSERT INTO heb_vpl VALUES ("K27_20","013_7_20","2KI","7","20","20","ויהי לו כן וירמסו אתו העם בשער וימת׃ ");
INSERT INTO heb_vpl VALUES ("K28_1","013_8_1","2KI","8","1","1","ואלישע דבר אל האשה אשר החיה את בנה לאמר קומי ולכי אתי וביתך וגורי באשר תגורי כי קרא יהוה לרעב וגם בא אל הארץ שבע שנים׃ ");
INSERT INTO heb_vpl VALUES ("K28_2","013_8_2","2KI","8","2","2","ותקם האשה ותעש כדבר איש האלהים ותלך היא וביתה ותגר בארץ פלשתים שבע שנים׃ ");
INSERT INTO heb_vpl VALUES ("K28_3","013_8_3","2KI","8","3","3","ויהי מקצה שבע שנים ותשב האשה מארץ פלשתים ותצא לצעק אל המלך אל ביתה ואל שדה׃ ");
INSERT INTO heb_vpl VALUES ("K28_4","013_8_4","2KI","8","4","4","והמלך מדבר אל גחזי נער איש האלהים לאמר ספרה נא לי את כל הגדלות אשר עשה אלישע׃ ");
INSERT INTO heb_vpl VALUES ("K28_5","013_8_5","2KI","8","5","5","ויהי הוא מספר למלך את אשר החיה את המת והנה האשה אשר החיה את בנה צעקת אל המלך על ביתה ועל שדה ויאמר גחזי אדני המלך זאת האשה וזה בנה אשר החיה אלישע׃ ");
INSERT INTO heb_vpl VALUES ("K28_6","013_8_6","2KI","8","6","6","וישאל המלך לאשה ותספר לו ויתן לה המלך סריס אחד לאמר השיב את כל אשר לה ואת כל תבואת השדה מיום עזבה את הארץ ועד עתה׃ ");
INSERT INTO heb_vpl VALUES ("K28_7","013_8_7","2KI","8","7","7","ויבא אלישע דמשק ובן הדד מלך ארם חלה ויגד לו לאמר בא איש האלהים עד הנה׃ ");
INSERT INTO heb_vpl VALUES ("K28_8","013_8_8","2KI","8","8","8","ויאמר המלך אל חזהאל קח בידך מנחה ולך לקראת איש האלהים ודרשת את יהוה מאותו לאמר האחיה מחלי זה׃ ");
INSERT INTO heb_vpl VALUES ("K28_9","013_8_9","2KI","8","9","9","וילך חזאל לקראתו ויקח מנחה בידו וכל טוב דמשק משא ארבעים גמל ויבא ויעמד לפניו ויאמר בנך בן הדד מלך ארם שלחני אליך לאמר האחיה מחלי זה׃ ");
INSERT INTO heb_vpl VALUES ("K28_10","013_8_10","2KI","8","10","10","ויאמר אליו אלישע לך אמר לא חיה תחיה והראני יהוה כי מות ימות׃ ");
INSERT INTO heb_vpl VALUES ("K28_11","013_8_11","2KI","8","11","11","ויעמד את פניו וישם עד בש ויבך איש האלהים׃ ");
INSERT INTO heb_vpl VALUES ("K28_12","013_8_12","2KI","8","12","12","ויאמר חזאל מדוע אדני בכה ויאמר כי ידעתי את אשר תעשה לבני ישראל רעה מבצריהם תשלח באש ובחריהם בחרב תהרג ועלליהם תרטש והרתיהם תבקע׃ ");
INSERT INTO heb_vpl VALUES ("K28_13","013_8_13","2KI","8","13","13","ויאמר חזהאל כי מה עבדך הכלב כי יעשה הדבר הגדול הזה ויאמר אלישע הראני יהוה אתך מלך על ארם׃ ");
INSERT INTO heb_vpl VALUES ("K28_14","013_8_14","2KI","8","14","14","וילך מאת אלישע ויבא אל אדניו ויאמר לו מה אמר לך אלישע ויאמר אמר לי חיה תחיה׃ ");
INSERT INTO heb_vpl VALUES ("K28_15","013_8_15","2KI","8","15","15","ויהי ממחרת ויקח המכבר ויטבל במים ויפרש על פניו וימת וימלך חזהאל תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K28_16","013_8_16","2KI","8","16","16","ובשנת חמש ליורם בן אחאב מלך ישראל ויהושפט מלך יהודה מלך יהורם בן יהושפט מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K28_17","013_8_17","2KI","8","17","17","בן שלשים ושתים שנה היה במלכו ושמנה שנה מלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K28_18","013_8_18","2KI","8","18","18","וילך בדרך מלכי ישראל כאשר עשו בית אחאב כי בת אחאב היתה לו לאשה ויעש הרע בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K28_19","013_8_19","2KI","8","19","19","ולא אבה יהוה להשחית את יהודה למען דוד עבדו כאשר אמר לו לתת לו ניר לבניו כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("K28_20","013_8_20","2KI","8","20","20","בימיו פשע אדום מתחת יד יהודה וימלכו עליהם מלך׃ ");
INSERT INTO heb_vpl VALUES ("K28_21","013_8_21","2KI","8","21","21","ויעבר יורם צעירה וכל הרכב עמו ויהי הוא קם לילה ויכה את אדום הסביב אליו ואת שרי הרכב וינס העם לאהליו׃ ");
INSERT INTO heb_vpl VALUES ("K28_22","013_8_22","2KI","8","22","22","ויפשע אדום מתחת יד יהודה עד היום הזה אז תפשע לבנה בעת ההיא׃ ");
INSERT INTO heb_vpl VALUES ("K28_23","013_8_23","2KI","8","23","23","ויתר דברי יורם וכל אשר עשה הלוא הם כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K28_24","013_8_24","2KI","8","24","24","וישכב יורם עם אבתיו ויקבר עם אבתיו בעיר דוד וימלך אחזיהו בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K28_25","013_8_25","2KI","8","25","25","בשנת שתים עשרה שנה ליורם בן אחאב מלך ישראל מלך אחזיהו בן יהורם מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K28_26","013_8_26","2KI","8","26","26","בן עשרים ושתים שנה אחזיהו במלכו ושנה אחת מלך בירושלם ושם אמו עתליהו בת עמרי מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K28_27","013_8_27","2KI","8","27","27","וילך בדרך בית אחאב ויעש הרע בעיני יהוה כבית אחאב כי חתן בית אחאב הוא׃ ");
INSERT INTO heb_vpl VALUES ("K28_28","013_8_28","2KI","8","28","28","וילך את יורם בן אחאב למלחמה עם חזהאל מלך ארם ברמת גלעד ויכו ארמים את יורם׃ ");
INSERT INTO heb_vpl VALUES ("K28_29","013_8_29","2KI","8","29","29","וישב יורם המלך להתרפא ביזרעאל מן המכים אשר יכהו ארמים ברמה בהלחמו את חזהאל מלך ארם ואחזיהו בן יהורם מלך יהודה ירד לראות את יורם בן אחאב ביזרעאל כי חלה הוא׃ ");
INSERT INTO heb_vpl VALUES ("K29_1","013_9_1","2KI","9","1","1","ואלישע הנביא קרא לאחד מבני הנביאים ויאמר לו חגר מתניך וקח פך השמן הזה בידך ולך רמת גלעד׃ ");
INSERT INTO heb_vpl VALUES ("K29_2","013_9_2","2KI","9","2","2","ובאת שמה וראה שם יהוא בן יהושפט בן נמשי ובאת והקמתו מתוך אחיו והביאת אתו חדר בחדר׃ ");
INSERT INTO heb_vpl VALUES ("K29_3","013_9_3","2KI","9","3","3","ולקחת פך השמן ויצקת על ראשו ואמרת כה אמר יהוה משחתיך למלך אל ישראל ופתחת הדלת ונסתה ולא תחכה׃ ");
INSERT INTO heb_vpl VALUES ("K29_4","013_9_4","2KI","9","4","4","וילך הנער הנער הנביא רמת גלעד׃ ");
INSERT INTO heb_vpl VALUES ("K29_5","013_9_5","2KI","9","5","5","ויבא והנה שרי החיל ישבים ויאמר דבר לי אליך השר ויאמר יהוא אל מי מכלנו ויאמר אליך השר׃ ");
INSERT INTO heb_vpl VALUES ("K29_6","013_9_6","2KI","9","6","6","ויקם ויבא הביתה ויצק השמן אל ראשו ויאמר לו כה אמר יהוה אלהי ישראל משחתיך למלך אל עם יהוה אל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K29_7","013_9_7","2KI","9","7","7","והכיתה את בית אחאב אדניך ונקמתי דמי עבדי הנביאים ודמי כל עבדי יהוה מיד איזבל׃ ");
INSERT INTO heb_vpl VALUES ("K29_8","013_9_8","2KI","9","8","8","ואבד כל בית אחאב והכרתי לאחאב משתין בקיר ועצור ועזוב בישראל׃ ");
INSERT INTO heb_vpl VALUES ("K29_9","013_9_9","2KI","9","9","9","ונתתי את בית אחאב כבית ירבעם בן נבט וכבית בעשא בן אחיה׃ ");
INSERT INTO heb_vpl VALUES ("K29_10","013_9_10","2KI","9","10","10","ואת איזבל יאכלו הכלבים בחלק יזרעאל ואין קבר ויפתח הדלת וינס׃ ");
INSERT INTO heb_vpl VALUES ("K29_11","013_9_11","2KI","9","11","11","ויהוא יצא אל עבדי אדניו ויאמר לו השלום מדוע בא המשגע הזה אליך ויאמר אליהם אתם ידעתם את האיש ואת שיחו׃ ");
INSERT INTO heb_vpl VALUES ("K29_12","013_9_12","2KI","9","12","12","ויאמרו שקר הגד נא לנו ויאמר כזאת וכזאת אמר אלי לאמר כה אמר יהוה משחתיך למלך אל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K29_13","013_9_13","2KI","9","13","13","וימהרו ויקחו איש בגדו וישימו תחתיו אל גרם המעלות ויתקעו בשופר ויאמרו מלך יהוא׃ ");
INSERT INTO heb_vpl VALUES ("K29_14","013_9_14","2KI","9","14","14","ויתקשר יהוא בן יהושפט בן נמשי אל יורם ויורם היה שמר ברמת גלעד הוא וכל ישראל מפני חזאל מלך ארם׃ ");
INSERT INTO heb_vpl VALUES ("K29_15","013_9_15","2KI","9","15","15","וישב יהורם המלך להתרפא ביזרעאל מן המכים אשר יכהו ארמים בהלחמו את חזאל מלך ארם ויאמר יהוא אם יש נפשכם אל יצא פליט מן העיר ללכת לגיד ביזרעאל׃ ");
INSERT INTO heb_vpl VALUES ("K29_16","013_9_16","2KI","9","16","16","וירכב יהוא וילך יזרעאלה כי יורם שכב שמה ואחזיה מלך יהודה ירד לראות את יורם׃ ");
INSERT INTO heb_vpl VALUES ("K29_17","013_9_17","2KI","9","17","17","והצפה עמד על המגדל ביזרעאל וירא את שפעת יהוא בבאו ויאמר שפעת אני ראה ויאמר יהורם קח רכב ושלח לקראתם ויאמר השלום׃ ");
INSERT INTO heb_vpl VALUES ("K29_18","013_9_18","2KI","9","18","18","וילך רכב הסוס לקראתו ויאמר כה אמר המלך השלום ויאמר יהוא מה לך ולשלום סב אל אחרי ויגד הצפה לאמר בא המלאך עד הם ולא שב׃ ");
INSERT INTO heb_vpl VALUES ("K29_19","013_9_19","2KI","9","19","19","וישלח רכב סוס שני ויבא אלהם ויאמר כה אמר המלך שלום ויאמר יהוא מה לך ולשלום סב אל אחרי׃ ");
INSERT INTO heb_vpl VALUES ("K29_20","013_9_20","2KI","9","20","20","ויגד הצפה לאמר בא עד אליהם ולא שב והמנהג כמנהג יהוא בן נמשי כי בשגעון ינהג׃ ");
INSERT INTO heb_vpl VALUES ("K29_21","013_9_21","2KI","9","21","21","ויאמר יהורם אסר ויאסר רכבו ויצא יהורם מלך ישראל ואחזיהו מלך יהודה איש ברכבו ויצאו לקראת יהוא וימצאהו בחלקת נבות היזרעאלי׃ ");
INSERT INTO heb_vpl VALUES ("K29_22","013_9_22","2KI","9","22","22","ויהי כראות יהורם את יהוא ויאמר השלום יהוא ויאמר מה השלום עד זנוני איזבל אמך וכשפיה הרבים׃ ");
INSERT INTO heb_vpl VALUES ("K29_23","013_9_23","2KI","9","23","23","ויהפך יהורם ידיו וינס ויאמר אל אחזיהו מרמה אחזיה׃ ");
INSERT INTO heb_vpl VALUES ("K29_24","013_9_24","2KI","9","24","24","ויהוא מלא ידו בקשת ויך את יהורם בין זרעיו ויצא החצי מלבו ויכרע ברכבו׃ ");
INSERT INTO heb_vpl VALUES ("K29_25","013_9_25","2KI","9","25","25","ויאמר אל בדקר שלשה שא השלכהו בחלקת שדה נבות היזרעאלי כי זכר אני ואתה את רכבים צמדים אחרי אחאב אביו ויהוה נשא עליו את המשא הזה׃ ");
INSERT INTO heb_vpl VALUES ("K29_26","013_9_26","2KI","9","26","26","אם לא את דמי נבות ואת דמי בניו ראיתי אמש נאם יהוה ושלמתי לך בחלקה הזאת נאם יהוה ועתה שא השלכהו בחלקה כדבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K29_27","013_9_27","2KI","9","27","27","ואחזיה מלך יהודה ראה וינס דרך בית הגן וירדף אחריו יהוא ויאמר גם אתו הכהו אל המרכבה במעלה גור אשר את יבלעם וינס מגדו וימת שם׃ ");
INSERT INTO heb_vpl VALUES ("K29_28","013_9_28","2KI","9","28","28","וירכבו אתו עבדיו ירושלמה ויקברו אתו בקברתו עם אבתיו בעיר דוד׃ ");
INSERT INTO heb_vpl VALUES ("K29_29","013_9_29","2KI","9","29","29","ובשנת אחת עשרה שנה ליורם בן אחאב מלך אחזיה על יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K29_30","013_9_30","2KI","9","30","30","ויבוא יהוא יזרעאלה ואיזבל שמעה ותשם בפוך עיניה ותיטב את ראשה ותשקף בעד החלון׃ ");
INSERT INTO heb_vpl VALUES ("K29_31","013_9_31","2KI","9","31","31","ויהוא בא בשער ותאמר השלום זמרי הרג אדניו׃ ");
INSERT INTO heb_vpl VALUES ("K29_32","013_9_32","2KI","9","32","32","וישא פניו אל החלון ויאמר מי אתי מי וישקיפו אליו שנים שלשה סריסים׃ ");
INSERT INTO heb_vpl VALUES ("K29_33","013_9_33","2KI","9","33","33","ויאמר שמטהו וישמטוה ויז מדמה אל הקיר ואל הסוסים וירמסנה׃ ");
INSERT INTO heb_vpl VALUES ("K29_34","013_9_34","2KI","9","34","34","ויבא ויאכל וישת ויאמר פקדו נא את הארורה הזאת וקברוה כי בת מלך היא׃ ");
INSERT INTO heb_vpl VALUES ("K29_35","013_9_35","2KI","9","35","35","וילכו לקברה ולא מצאו בה כי אם הגלגלת והרגלים וכפות הידים׃ ");
INSERT INTO heb_vpl VALUES ("K29_36","013_9_36","2KI","9","36","36","וישבו ויגידו לו ויאמר דבר יהוה הוא אשר דבר ביד עבדו אליהו התשבי לאמר בחלק יזרעאל יאכלו הכלבים את בשר איזבל׃ ");
INSERT INTO heb_vpl VALUES ("K29_37","013_9_37","2KI","9","37","37","והית נבלת איזבל כדמן על פני השדה בחלק יזרעאל אשר לא יאמרו זאת איזבל׃ ");
INSERT INTO heb_vpl VALUES ("K210_1","013_10_1","2KI","10","1","1","ולאחאב שבעים בנים בשמרון ויכתב יהוא ספרים וישלח שמרון אל שרי יזרעאל הזקנים ואל האמנים אחאב לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K210_2","013_10_2","2KI","10","2","2","ועתה כבא הספר הזה אליכם ואתכם בני אדניכם ואתכם הרכב והסוסים ועיר מבצר והנשק׃ ");
INSERT INTO heb_vpl VALUES ("K210_3","013_10_3","2KI","10","3","3","וראיתם הטוב והישר מבני אדניכם ושמתם על כסא אביו והלחמו על בית אדניכם׃ ");
INSERT INTO heb_vpl VALUES ("K210_4","013_10_4","2KI","10","4","4","ויראו מאד מאד ויאמרו הנה שני המלכים לא עמדו לפניו ואיך נעמד אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("K210_5","013_10_5","2KI","10","5","5","וישלח אשר על הבית ואשר על העיר והזקנים והאמנים אל יהוא לאמר עבדיך אנחנו וכל אשר תאמר אלינו נעשה לא נמליך איש הטוב בעיניך עשה׃ ");
INSERT INTO heb_vpl VALUES ("K210_6","013_10_6","2KI","10","6","6","ויכתב אליהם ספר שנית לאמר אם לי אתם ולקלי אתם שמעים קחו את ראשי אנשי בני אדניכם ובאו אלי כעת מחר יזרעאלה ובני המלך שבעים איש את גדלי העיר מגדלים אותם׃ ");
INSERT INTO heb_vpl VALUES ("K210_7","013_10_7","2KI","10","7","7","ויהי כבא הספר אליהם ויקחו את בני המלך וישחטו שבעים איש וישימו את ראשיהם בדודים וישלחו אליו יזרעאלה׃ ");
INSERT INTO heb_vpl VALUES ("K210_8","013_10_8","2KI","10","8","8","ויבא המלאך ויגד לו לאמר הביאו ראשי בני המלך ויאמר שימו אתם שני צברים פתח השער עד הבקר׃ ");
INSERT INTO heb_vpl VALUES ("K210_9","013_10_9","2KI","10","9","9","ויהי בבקר ויצא ויעמד ויאמר אל כל העם צדקים אתם הנה אני קשרתי על אדני ואהרגהו ומי הכה את כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("K210_10","013_10_10","2KI","10","10","10","דעו אפוא כי לא יפל מדבר יהוה ארצה אשר דבר יהוה על בית אחאב ויהוה עשה את אשר דבר ביד עבדו אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K210_11","013_10_11","2KI","10","11","11","ויך יהוא את כל הנשארים לבית אחאב ביזרעאל וכל גדליו ומידעיו וכהניו עד בלתי השאיר לו שריד׃ ");
INSERT INTO heb_vpl VALUES ("K210_12","013_10_12","2KI","10","12","12","ויקם ויבא וילך שמרון הוא בית עקד הרעים בדרך׃ ");
INSERT INTO heb_vpl VALUES ("K210_13","013_10_13","2KI","10","13","13","ויהוא מצא את אחי אחזיהו מלך יהודה ויאמר מי אתם ויאמרו אחי אחזיהו אנחנו ונרד לשלום בני המלך ובני הגבירה׃ ");
INSERT INTO heb_vpl VALUES ("K210_14","013_10_14","2KI","10","14","14","ויאמר תפשום חיים ויתפשום חיים וישחטום אל בור בית עקד ארבעים ושנים איש ולא השאיר איש מהם׃ ");
INSERT INTO heb_vpl VALUES ("K210_15","013_10_15","2KI","10","15","15","וילך משם וימצא את יהונדב בן רכב לקראתו ויברכהו ויאמר אליו היש את לבבך ישר כאשר לבבי עם לבבך ויאמר יהונדב יש ויש תנה את ידך ויתן ידו ויעלהו אליו אל המרכבה׃ ");
INSERT INTO heb_vpl VALUES ("K210_16","013_10_16","2KI","10","16","16","ויאמר לכה אתי וראה בקנאתי ליהוה וירכבו אתו ברכבו׃ ");
INSERT INTO heb_vpl VALUES ("K210_17","013_10_17","2KI","10","17","17","ויבא שמרון ויך את כל הנשארים לאחאב בשמרון עד השמידו כדבר יהוה אשר דבר אל אליהו׃ ");
INSERT INTO heb_vpl VALUES ("K210_18","013_10_18","2KI","10","18","18","ויקבץ יהוא את כל העם ויאמר אלהם אחאב עבד את הבעל מעט יהוא יעבדנו הרבה׃ ");
INSERT INTO heb_vpl VALUES ("K210_19","013_10_19","2KI","10","19","19","ועתה כל נביאי הבעל כל עבדיו וכל כהניו קראו אלי איש אל יפקד כי זבח גדול לי לבעל כל אשר יפקד לא יחיה ויהוא עשה בעקבה למען האביד את עבדי הבעל׃ ");
INSERT INTO heb_vpl VALUES ("K210_20","013_10_20","2KI","10","20","20","ויאמר יהוא קדשו עצרה לבעל ויקראו׃ ");
INSERT INTO heb_vpl VALUES ("K210_21","013_10_21","2KI","10","21","21","וישלח יהוא בכל ישראל ויבאו כל עבדי הבעל ולא נשאר איש אשר לא בא ויבאו בית הבעל וימלא בית הבעל פה לפה׃ ");
INSERT INTO heb_vpl VALUES ("K210_22","013_10_22","2KI","10","22","22","ויאמר לאשר על המלתחה הוצא לבוש לכל עבדי הבעל ויצא להם המלבוש׃ ");
INSERT INTO heb_vpl VALUES ("K210_23","013_10_23","2KI","10","23","23","ויבא יהוא ויהונדב בן רכב בית הבעל ויאמר לעבדי הבעל חפשו וראו פן יש פה עמכם מעבדי יהוה כי אם עבדי הבעל לבדם׃ ");
INSERT INTO heb_vpl VALUES ("K210_24","013_10_24","2KI","10","24","24","ויבאו לעשות זבחים ועלות ויהוא שם לו בחוץ שמנים איש ויאמר האיש אשר ימלט מן האנשים אשר אני מביא על ידיכם נפשו תחת נפשו׃ ");
INSERT INTO heb_vpl VALUES ("K210_25","013_10_25","2KI","10","25","25","ויהי ככלתו לעשות העלה ויאמר יהוא לרצים ולשלשים באו הכום איש אל יצא ויכום לפי חרב וישלכו הרצים והשלשים וילכו עד עיר בית הבעל׃ ");
INSERT INTO heb_vpl VALUES ("K210_26","013_10_26","2KI","10","26","26","ויצאו את מצבות בית הבעל וישרפוה׃ ");
INSERT INTO heb_vpl VALUES ("K210_27","013_10_27","2KI","10","27","27","ויתצו את מצבת הבעל ויתצו את בית הבעל וישמהו למחראות עד היום׃ ");
INSERT INTO heb_vpl VALUES ("K210_28","013_10_28","2KI","10","28","28","וישמד יהוא את הבעל מישראל׃ ");
INSERT INTO heb_vpl VALUES ("K210_29","013_10_29","2KI","10","29","29","רק חטאי ירבעם בן נבט אשר החטיא את ישראל לא סר יהוא מאחריהם עגלי הזהב אשר בית אל ואשר בדן׃ ");
INSERT INTO heb_vpl VALUES ("K210_30","013_10_30","2KI","10","30","30","ויאמר יהוה אל יהוא יען אשר הטיבת לעשות הישר בעיני ככל אשר בלבבי עשית לבית אחאב בני רבעים ישבו לך על כסא ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K210_31","013_10_31","2KI","10","31","31","ויהוא לא שמר ללכת בתורת יהוה אלהי ישראל בכל לבבו לא סר מעל חטאות ירבעם אשר החטיא את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K210_32","013_10_32","2KI","10","32","32","בימים ההם החל יהוה לקצות בישראל ויכם חזאל בכל גבול ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K210_33","013_10_33","2KI","10","33","33","מן הירדן מזרח השמש את כל ארץ הגלעד הגדי והראובני והמנשי מערער אשר על נחל ארנן והגלעד והבשן׃ ");
INSERT INTO heb_vpl VALUES ("K210_34","013_10_34","2KI","10","34","34","ויתר דברי יהוא וכל אשר עשה וכל גבורתו הלוא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K210_35","013_10_35","2KI","10","35","35","וישכב יהוא עם אבתיו ויקברו אתו בשמרון וימלך יהואחז בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K210_36","013_10_36","2KI","10","36","36","והימים אשר מלך יהוא על ישראל עשרים ושמנה שנה בשמרון׃ ");
INSERT INTO heb_vpl VALUES ("K211_1","013_11_1","2KI","11","1","1","ועתליה אם אחזיהו וראתה כי מת בנה ותקם ותאבד את כל זרע הממלכה׃ ");
INSERT INTO heb_vpl VALUES ("K211_2","013_11_2","2KI","11","2","2","ותקח יהושבע בת המלך יורם אחות אחזיהו את יואש בן אחזיה ותגנב אתו מתוך בני המלך הממותתים אתו ואת מינקתו בחדר המטות ויסתרו אתו מפני עתליהו ולא הומת׃ ");
INSERT INTO heb_vpl VALUES ("K211_3","013_11_3","2KI","11","3","3","ויהי אתה בית יהוה מתחבא שש שנים ועתליה מלכת על הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K211_4","013_11_4","2KI","11","4","4","ובשנה השביעית שלח יהוידע ויקח את שרי המאיות לכרי ולרצים ויבא אתם אליו בית יהוה ויכרת להם ברית וישבע אתם בבית יהוה וירא אתם את בן המלך׃ ");
INSERT INTO heb_vpl VALUES ("K211_5","013_11_5","2KI","11","5","5","ויצום לאמר זה הדבר אשר תעשון השלשית מכם באי השבת ושמרי משמרת בית המלך׃ ");
INSERT INTO heb_vpl VALUES ("K211_6","013_11_6","2KI","11","6","6","והשלשית בשער סור והשלשית בשער אחר הרצים ושמרתם את משמרת הבית מסח׃ ");
INSERT INTO heb_vpl VALUES ("K211_7","013_11_7","2KI","11","7","7","ושתי הידות בכם כל יצאי השבת ושמרו את משמרת בית יהוה אל המלך׃ ");
INSERT INTO heb_vpl VALUES ("K211_8","013_11_8","2KI","11","8","8","והקפתם על המלך סביב איש וכליו בידו והבא אל השדרות יומת והיו את המלך בצאתו ובבאו׃ ");
INSERT INTO heb_vpl VALUES ("K211_9","013_11_9","2KI","11","9","9","ויעשו שרי המאיות ככל אשר צוה יהוידע הכהן ויקחו איש את אנשיו באי השבת עם יצאי השבת ויבאו אל יהוידע הכהן׃ ");
INSERT INTO heb_vpl VALUES ("K211_10","013_11_10","2KI","11","10","10","ויתן הכהן לשרי המאיות את החנית ואת השלטים אשר למלך דוד אשר בבית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K211_11","013_11_11","2KI","11","11","11","ויעמדו הרצים איש וכליו בידו מכתף הבית הימנית עד כתף הבית השמאלית למזבח ולבית על המלך סביב׃ ");
INSERT INTO heb_vpl VALUES ("K211_12","013_11_12","2KI","11","12","12","ויוצא את בן המלך ויתן עליו את הנזר ואת העדות וימלכו אתו וימשחהו ויכו כף ויאמרו יחי המלך׃ ");
INSERT INTO heb_vpl VALUES ("K211_13","013_11_13","2KI","11","13","13","ותשמע עתליה את קול הרצין העם ותבא אל העם בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K211_14","013_11_14","2KI","11","14","14","ותרא והנה המלך עמד על העמוד כמשפט והשרים והחצצרות אל המלך וכל עם הארץ שמח ותקע בחצצרות ותקרע עתליה את בגדיה ותקרא קשר קשר׃ ");
INSERT INTO heb_vpl VALUES ("K211_15","013_11_15","2KI","11","15","15","ויצו יהוידע הכהן את שרי המאיות פקדי החיל ויאמר אליהם הוציאו אתה אל מבית לשדרת והבא אחריה המת בחרב כי אמר הכהן אל תומת בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K211_16","013_11_16","2KI","11","16","16","וישמו לה ידים ותבוא דרך מבוא הסוסים בית המלך ותומת שם׃ ");
INSERT INTO heb_vpl VALUES ("K211_17","013_11_17","2KI","11","17","17","ויכרת יהוידע את הברית בין יהוה ובין המלך ובין העם להיות לעם ליהוה ובין המלך ובין העם׃ ");
INSERT INTO heb_vpl VALUES ("K211_18","013_11_18","2KI","11","18","18","ויבאו כל עם הארץ בית הבעל ויתצהו את מזבחתו ואת צלמיו שברו היטב ואת מתן כהן הבעל הרגו לפני המזבחות וישם הכהן פקדות על בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K211_19","013_11_19","2KI","11","19","19","ויקח את שרי המאות ואת הכרי ואת הרצים ואת כל עם הארץ וירידו את המלך מבית יהוה ויבואו דרך שער הרצים בית המלך וישב על כסא המלכים׃ ");
INSERT INTO heb_vpl VALUES ("K211_20","013_11_20","2KI","11","20","20","וישמח כל עם הארץ והעיר שקטה ואת עתליהו המיתו בחרב בית מלך׃ ");
INSERT INTO heb_vpl VALUES ("K211_21","013_11_21","2KI","11","21","21","בן שבע שנים יהואש במלכו׃ ");
INSERT INTO heb_vpl VALUES ("K212_1","013_12_1","2KI","12","1","1","בשנת שבע ליהוא מלך יהואש וארבעים שנה מלך בירושלם ושם אמו צביה מבאר שבע׃ ");
INSERT INTO heb_vpl VALUES ("K212_2","013_12_2","2KI","12","2","2","ויעש יהואש הישר בעיני יהוה כל ימיו אשר הורהו יהוידע הכהן׃ ");
INSERT INTO heb_vpl VALUES ("K212_3","013_12_3","2KI","12","3","3","רק הבמות לא סרו עוד העם מזבחים ומקטרים בבמות׃ ");
INSERT INTO heb_vpl VALUES ("K212_4","013_12_4","2KI","12","4","4","ויאמר יהואש אל הכהנים כל כסף הקדשים אשר יובא בית יהוה כסף עובר איש כסף נפשות ערכו כל כסף אשר יעלה על לב איש להביא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K212_5","013_12_5","2KI","12","5","5","יקחו להם הכהנים איש מאת מכרו והם יחזקו את בדק הבית לכל אשר ימצא שם בדק׃ ");
INSERT INTO heb_vpl VALUES ("K212_6","013_12_6","2KI","12","6","6","ויהי בשנת עשרים ושלש שנה למלך יהואש לא חזקו הכהנים את בדק הבית׃ ");
INSERT INTO heb_vpl VALUES ("K212_7","013_12_7","2KI","12","7","7","ויקרא המלך יהואש ליהוידע הכהן ולכהנים ויאמר אלהם מדוע אינכם מחזקים את בדק הבית ועתה אל תקחו כסף מאת מכריכם כי לבדק הבית תתנהו׃ ");
INSERT INTO heb_vpl VALUES ("K212_8","013_12_8","2KI","12","8","8","ויאתו הכהנים לבלתי קחת כסף מאת העם ולבלתי חזק את בדק הבית׃ ");
INSERT INTO heb_vpl VALUES ("K212_9","013_12_9","2KI","12","9","9","ויקח יהוידע הכהן ארון אחד ויקב חר בדלתו ויתן אתו אצל המזבח בימין בבוא איש בית יהוה ונתנו שמה הכהנים שמרי הסף את כל הכסף המובא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K212_10","013_12_10","2KI","12","10","10","ויהי כראותם כי רב הכסף בארון ויעל ספר המלך והכהן הגדול ויצרו וימנו את הכסף הנמצא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K212_11","013_12_11","2KI","12","11","11","ונתנו את הכסף המתכן על יד עשי המלאכה הפקדים בית יהוה ויוציאהו לחרשי העץ ולבנים העשים בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K212_12","013_12_12","2KI","12","12","12","ולגדרים ולחצבי האבן ולקנות עצים ואבני מחצב לחזק את בדק בית יהוה ולכל אשר יצא על הבית לחזקה׃ ");
INSERT INTO heb_vpl VALUES ("K212_13","013_12_13","2KI","12","13","13","אך לא יעשה בית יהוה ספות כסף מזמרות מזרקות חצצרות כל כלי זהב וכלי כסף מן הכסף המובא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K212_14","013_12_14","2KI","12","14","14","כי לעשי המלאכה יתנהו וחזקו בו את בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K212_15","013_12_15","2KI","12","15","15","ולא יחשבו את האנשים אשר יתנו את הכסף על ידם לתת לעשי המלאכה כי באמנה הם עשים׃ ");
INSERT INTO heb_vpl VALUES ("K212_16","013_12_16","2KI","12","16","16","כסף אשם וכסף חטאות לא יובא בית יהוה לכהנים יהיו׃ ");
INSERT INTO heb_vpl VALUES ("K212_17","013_12_17","2KI","12","17","17","אז יעלה חזאל מלך ארם וילחם על גת וילכדה וישם חזאל פניו לעלות על ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K212_18","013_12_18","2KI","12","18","18","ויקח יהואש מלך יהודה את כל הקדשים אשר הקדישו יהושפט ויהורם ואחזיהו אבתיו מלכי יהודה ואת קדשיו ואת כל הזהב הנמצא באצרות בית יהוה ובית המלך וישלח לחזאל מלך ארם ויעל מעל ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K212_19","013_12_19","2KI","12","19","19","ויתר דברי יואש וכל אשר עשה הלוא הם כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K212_20","013_12_20","2KI","12","20","20","ויקמו עבדיו ויקשרו קשר ויכו את יואש בית מלא היורד סלא׃ ");
INSERT INTO heb_vpl VALUES ("K212_21","013_12_21","2KI","12","21","21","ויוזבד בן שמעת ויהוזבד בן שמר עבדיו הכהו וימת ויקברו אתו עם אבתיו בעיר דוד וימלך אמציה בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K213_1","013_13_1","2KI","13","1","1","בשנת עשרים ושלש שנה ליואש בן אחזיהו מלך יהודה מלך יהואחז בן יהוא על ישראל בשמרון שבע עשרה שנה׃ ");
INSERT INTO heb_vpl VALUES ("K213_2","013_13_2","2KI","13","2","2","ויעש הרע בעיני יהוה וילך אחר חטאת ירבעם בן נבט אשר החטיא את ישראל לא סר ממנה׃ ");
INSERT INTO heb_vpl VALUES ("K213_3","013_13_3","2KI","13","3","3","ויחר אף יהוה בישראל ויתנם ביד חזאל מלך ארם וביד בן הדד בן חזאל כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("K213_4","013_13_4","2KI","13","4","4","ויחל יהואחז את פני יהוה וישמע אליו יהוה כי ראה את לחץ ישראל כי לחץ אתם מלך ארם׃ ");
INSERT INTO heb_vpl VALUES ("K213_5","013_13_5","2KI","13","5","5","ויתן יהוה לישראל מושיע ויצאו מתחת יד ארם וישבו בני ישראל באהליהם כתמול שלשום׃ ");
INSERT INTO heb_vpl VALUES ("K213_6","013_13_6","2KI","13","6","6","אך לא סרו מחטאות בית ירבעם אשר החטי את ישראל בה הלך וגם האשרה עמדה בשמרון׃ ");
INSERT INTO heb_vpl VALUES ("K213_7","013_13_7","2KI","13","7","7","כי לא השאיר ליהואחז עם כי אם חמשים פרשים ועשרה רכב ועשרת אלפים רגלי כי אבדם מלך ארם וישמם כעפר לדש׃ ");
INSERT INTO heb_vpl VALUES ("K213_8","013_13_8","2KI","13","8","8","ויתר דברי יהואחז וכל אשר עשה וגבורתו הלוא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K213_9","013_13_9","2KI","13","9","9","וישכב יהואחז עם אבתיו ויקברהו בשמרון וימלך יואש בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K213_10","013_13_10","2KI","13","10","10","בשנת שלשים ושבע שנה ליואש מלך יהודה מלך יהואש בן יהואחז על ישראל בשמרון שש עשרה שנה׃ ");
INSERT INTO heb_vpl VALUES ("K213_11","013_13_11","2KI","13","11","11","ויעשה הרע בעיני יהוה לא סר מכל חטאות ירבעם בן נבט אשר החטיא את ישראל בה הלך׃ ");
INSERT INTO heb_vpl VALUES ("K213_12","013_13_12","2KI","13","12","12","ויתר דברי יואש וכל אשר עשה וגבורתו אשר נלחם עם אמציה מלך יהודה הלוא הם כתובים על ספר דברי הימים למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K213_13","013_13_13","2KI","13","13","13","וישכב יואש עם אבתיו וירבעם ישב על כסאו ויקבר יואש בשמרון עם מלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K213_14","013_13_14","2KI","13","14","14","ואלישע חלה את חליו אשר ימות בו וירד אליו יואש מלך ישראל ויבך על פניו ויאמר אבי אבי רכב ישראל ופרשיו׃ ");
INSERT INTO heb_vpl VALUES ("K213_15","013_13_15","2KI","13","15","15","ויאמר לו אלישע קח קשת וחצים ויקח אליו קשת וחצים׃ ");
INSERT INTO heb_vpl VALUES ("K213_16","013_13_16","2KI","13","16","16","ויאמר למלך ישראל הרכב ידך על הקשת וירכב ידו וישם אלישע ידיו על ידי המלך׃ ");
INSERT INTO heb_vpl VALUES ("K213_17","013_13_17","2KI","13","17","17","ויאמר פתח החלון קדמה ויפתח ויאמר אלישע ירה ויור ויאמר חץ תשועה ליהוה וחץ תשועה בארם והכית את ארם באפק עד כלה׃ ");
INSERT INTO heb_vpl VALUES ("K213_18","013_13_18","2KI","13","18","18","ויאמר קח החצים ויקח ויאמר למלך ישראל הך ארצה ויך שלש פעמים ויעמד׃ ");
INSERT INTO heb_vpl VALUES ("K213_19","013_13_19","2KI","13","19","19","ויקצף עליו איש האלהים ויאמר להכות חמש או שש פעמים אז הכית את ארם עד כלה ועתה שלש פעמים תכה את ארם׃ ");
INSERT INTO heb_vpl VALUES ("K213_20","013_13_20","2KI","13","20","20","וימת אלישע ויקברהו וגדודי מואב יבאו בארץ בא שנה׃ ");
INSERT INTO heb_vpl VALUES ("K213_21","013_13_21","2KI","13","21","21","ויהי הם קברים איש והנה ראו את הגדוד וישליכו את האיש בקבר אלישע וילך ויגע האיש בעצמות אלישע ויחי ויקם על רגליו׃ ");
INSERT INTO heb_vpl VALUES ("K213_22","013_13_22","2KI","13","22","22","וחזאל מלך ארם לחץ את ישראל כל ימי יהואחז׃ ");
INSERT INTO heb_vpl VALUES ("K213_23","013_13_23","2KI","13","23","23","ויחן יהוה אתם וירחמם ויפן אליהם למען בריתו את אברהם יצחק ויעקב ולא אבה השחיתם ולא השליכם מעל פניו עד עתה׃ ");
INSERT INTO heb_vpl VALUES ("K213_24","013_13_24","2KI","13","24","24","וימת חזאל מלך ארם וימלך בן הדד בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K213_25","013_13_25","2KI","13","25","25","וישב יהואש בן יהואחז ויקח את הערים מיד בן הדד בן חזאל אשר לקח מיד יהואחז אביו במלחמה שלש פעמים הכהו יואש וישב את ערי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K214_1","013_14_1","2KI","14","1","1","בשנת שתים ליואש בן יואחז מלך ישראל מלך אמציהו בן יואש מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K214_2","013_14_2","2KI","14","2","2","בן עשרים וחמש שנה היה במלכו ועשרים ותשע שנה מלך בירושלם ושם אמו יהועדין מן ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K214_3","013_14_3","2KI","14","3","3","ויעש הישר בעיני יהוה רק לא כדוד אביו ככל אשר עשה יואש אביו עשה׃ ");
INSERT INTO heb_vpl VALUES ("K214_4","013_14_4","2KI","14","4","4","רק הבמות לא סרו עוד העם מזבחים ומקטרים בבמות׃ ");
INSERT INTO heb_vpl VALUES ("K214_5","013_14_5","2KI","14","5","5","ויהי כאשר חזקה הממלכה בידו ויך את עבדיו המכים את המלך אביו׃ ");
INSERT INTO heb_vpl VALUES ("K214_6","013_14_6","2KI","14","6","6","ואת בני המכים לא המית ככתוב בספר תורת משה אשר צוה יהוה לאמר לא יומתו אבות על בנים ובנים לא יומתו על אבות כי אם איש בחטאו ימות׃ ");
INSERT INTO heb_vpl VALUES ("K214_7","013_14_7","2KI","14","7","7","הוא הכה את אדום בגיא המלח עשרת אלפים ותפש את הסלע במלחמה ויקרא את שמה יקתאל עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K214_8","013_14_8","2KI","14","8","8","אז שלח אמציה מלאכים אל יהואש בן יהואחז בן יהוא מלך ישראל לאמר לכה נתראה פנים׃ ");
INSERT INTO heb_vpl VALUES ("K214_9","013_14_9","2KI","14","9","9","וישלח יהואש מלך ישראל אל אמציהו מלך יהודה לאמר החוח אשר בלבנון שלח אל הארז אשר בלבנון לאמר תנה את בתך לבני לאשה ותעבר חית השדה אשר בלבנון ותרמס את החוח׃ ");
INSERT INTO heb_vpl VALUES ("K214_10","013_14_10","2KI","14","10","10","הכה הכית את אדום ונשאך לבך הכבד ושב בביתך ולמה תתגרה ברעה ונפלתה אתה ויהודה עמך׃ ");
INSERT INTO heb_vpl VALUES ("K214_11","013_14_11","2KI","14","11","11","ולא שמע אמציהו ויעל יהואש מלך ישראל ויתראו פנים הוא ואמציהו מלך יהודה בבית שמש אשר ליהודה׃ ");
INSERT INTO heb_vpl VALUES ("K214_12","013_14_12","2KI","14","12","12","וינגף יהודה לפני ישראל וינסו איש לאהלו׃ ");
INSERT INTO heb_vpl VALUES ("K214_13","013_14_13","2KI","14","13","13","ואת אמציהו מלך יהודה בן יהואש בן אחזיהו תפש יהואש מלך ישראל בבית שמש ויבאו ירושלם ויפרץ בחומת ירושלם בשער אפרים עד שער הפנה ארבע מאות אמה׃ ");
INSERT INTO heb_vpl VALUES ("K214_14","013_14_14","2KI","14","14","14","ולקח את כל הזהב והכסף ואת כל הכלים הנמצאים בית יהוה ובאצרות בית המלך ואת בני התערבות וישב שמרונה׃ ");
