INSERT INTO heb_vpl VALUES ("K217_2","013_17_2","2KI","17","2","2","ויעש הרע בעיני יהוה רק לא כמלכי ישראל אשר היו לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K217_3","013_17_3","2KI","17","3","3","עליו עלה שלמנאסר מלך אשור ויהי לו הושע עבד וישב לו מנחה׃ ");
INSERT INTO heb_vpl VALUES ("K217_4","013_17_4","2KI","17","4","4","וימצא מלך אשור בהושע קשר אשר שלח מלאכים אל סוא מלך מצרים ולא העלה מנחה למלך אשור כשנה בשנה ויעצרהו מלך אשור ויאסרהו בית כלא׃ ");
INSERT INTO heb_vpl VALUES ("K217_5","013_17_5","2KI","17","5","5","ויעל מלך אשור בכל הארץ ויעל שמרון ויצר עליה שלש שנים׃ ");
INSERT INTO heb_vpl VALUES ("K217_6","013_17_6","2KI","17","6","6","בשנת התשיעית להושע לכד מלך אשור את שמרון ויגל את ישראל אשורה וישב אתם בחלח ובחבור נהר גוזן וערי מדי׃ ");
INSERT INTO heb_vpl VALUES ("K217_7","013_17_7","2KI","17","7","7","ויהי כי חטאו בני ישראל ליהוה אלהיהם המעלה אתם מארץ מצרים מתחת יד פרעה מלך מצרים וייראו אלהים אחרים׃ ");
INSERT INTO heb_vpl VALUES ("K217_8","013_17_8","2KI","17","8","8","וילכו בחקות הגוים אשר הוריש יהוה מפני בני ישראל ומלכי ישראל אשר עשו׃ ");
INSERT INTO heb_vpl VALUES ("K217_9","013_17_9","2KI","17","9","9","ויחפאו בני ישראל דברים אשר לא כן על יהוה אלהיהם ויבנו להם במות בכל עריהם ממגדל נוצרים עד עיר מבצר׃ ");
INSERT INTO heb_vpl VALUES ("K217_10","013_17_10","2KI","17","10","10","ויצבו להם מצבות ואשרים על כל גבעה גבהה ותחת כל עץ רענן׃ ");
INSERT INTO heb_vpl VALUES ("K217_11","013_17_11","2KI","17","11","11","ויקטרו שם בכל במות כגוים אשר הגלה יהוה מפניהם ויעשו דברים רעים להכעיס את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K217_12","013_17_12","2KI","17","12","12","ויעבדו הגללים אשר אמר יהוה להם לא תעשו את הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("K217_13","013_17_13","2KI","17","13","13","ויעד יהוה בישראל וביהודה ביד כל נביאו כל חזה לאמר שבו מדרכיכם הרעים ושמרו מצותי חקותי ככל התורה אשר צויתי את אבתיכם ואשר שלחתי אליכם ביד עבדי הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("K217_14","013_17_14","2KI","17","14","14","ולא שמעו ויקשו את ערפם כערף אבותם אשר לא האמינו ביהוה אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("K217_15","013_17_15","2KI","17","15","15","וימאסו את חקיו ואת בריתו אשר כרת את אבותם ואת עדותיו אשר העיד בם וילכו אחרי ההבל ויהבלו ואחרי הגוים אשר סביבתם אשר צוה יהוה אתם לבלתי עשות כהם׃ ");
INSERT INTO heb_vpl VALUES ("K217_16","013_17_16","2KI","17","16","16","ויעזבו את כל מצות יהוה אלהיהם ויעשו להם מסכה שנים עגלים ויעשו אשירה וישתחוו לכל צבא השמים ויעבדו את הבעל׃ ");
INSERT INTO heb_vpl VALUES ("K217_17","013_17_17","2KI","17","17","17","ויעבירו את בניהם ואת בנותיהם באש ויקסמו קסמים וינחשו ויתמכרו לעשות הרע בעיני יהוה להכעיסו׃ ");
INSERT INTO heb_vpl VALUES ("K217_18","013_17_18","2KI","17","18","18","ויתאנף יהוה מאד בישראל ויסרם מעל פניו לא נשאר רק שבט יהודה לבדו׃ ");
INSERT INTO heb_vpl VALUES ("K217_19","013_17_19","2KI","17","19","19","גם יהודה לא שמר את מצות יהוה אלהיהם וילכו בחקות ישראל אשר עשו׃ ");
INSERT INTO heb_vpl VALUES ("K217_20","013_17_20","2KI","17","20","20","וימאס יהוה בכל זרע ישראל ויענם ויתנם ביד שסים עד אשר השליכם מפניו׃ ");
INSERT INTO heb_vpl VALUES ("K217_21","013_17_21","2KI","17","21","21","כי קרע ישראל מעל בית דוד וימליכו את ירבעם בן נבט וידא ירבעם את ישראל מאחרי יהוה והחטיאם חטאה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("K217_22","013_17_22","2KI","17","22","22","וילכו בני ישראל בכל חטאות ירבעם אשר עשה לא סרו ממנה׃ ");
INSERT INTO heb_vpl VALUES ("K217_23","013_17_23","2KI","17","23","23","עד אשר הסיר יהוה את ישראל מעל פניו כאשר דבר ביד כל עבדיו הנביאים ויגל ישראל מעל אדמתו אשורה עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K217_24","013_17_24","2KI","17","24","24","ויבא מלך אשור מבבל ומכותה ומעוא ומחמת וספרוים וישב בערי שמרון תחת בני ישראל וירשו את שמרון וישבו בעריה׃ ");
INSERT INTO heb_vpl VALUES ("K217_25","013_17_25","2KI","17","25","25","ויהי בתחלת שבתם שם לא יראו את יהוה וישלח יהוה בהם את האריות ויהיו הרגים בהם׃ ");
INSERT INTO heb_vpl VALUES ("K217_26","013_17_26","2KI","17","26","26","ויאמרו למלך אשור לאמר הגוים אשר הגלית ותושב בערי שמרון לא ידעו את משפט אלהי הארץ וישלח בם את האריות והנם ממיתים אותם כאשר אינם ידעים את משפט אלהי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K217_27","013_17_27","2KI","17","27","27","ויצו מלך אשור לאמר הליכו שמה אחד מהכהנים אשר הגליתם משם וילכו וישבו שם וירם את משפט אלהי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K217_28","013_17_28","2KI","17","28","28","ויבא אחד מהכהנים אשר הגלו משמרון וישב בבית אל ויהי מורה אתם איך ייראו את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K217_29","013_17_29","2KI","17","29","29","ויהיו עשים גוי גוי אלהיו ויניחו בבית הבמות אשר עשו השמרנים גוי גוי בעריהם אשר הם ישבים שם׃ ");
INSERT INTO heb_vpl VALUES ("K217_30","013_17_30","2KI","17","30","30","ואנשי בבל עשו את סכות בנות ואנשי כות עשו את נרגל ואנשי חמת עשו את אשימא׃ ");
INSERT INTO heb_vpl VALUES ("K217_31","013_17_31","2KI","17","31","31","והעוים עשו נבחז ואת תרתק והספרוים שרפים את בניהם באש לאדרמלך וענמלך אלה ספרים׃ ");
INSERT INTO heb_vpl VALUES ("K217_32","013_17_32","2KI","17","32","32","ויהיו יראים את יהוה ויעשו להם מקצותם כהני במות ויהיו עשים להם בבית הבמות׃ ");
INSERT INTO heb_vpl VALUES ("K217_33","013_17_33","2KI","17","33","33","את יהוה היו יראים ואת אלהיהם היו עבדים כמשפט הגוים אשר הגלו אתם משם׃ ");
INSERT INTO heb_vpl VALUES ("K217_34","013_17_34","2KI","17","34","34","עד היום הזה הם עשים כמשפטים הראשנים אינם יראים את יהוה ואינם עשים כחקתם וכמשפטם וכתורה וכמצוה אשר צוה יהוה את בני יעקב אשר שם שמו ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K217_35","013_17_35","2KI","17","35","35","ויכרת יהוה אתם ברית ויצום לאמר לא תיראו אלהים אחרים ולא תשתחוו להם ולא תעבדום ולא תזבחו להם׃ ");
INSERT INTO heb_vpl VALUES ("K217_36","013_17_36","2KI","17","36","36","כי אם את יהוה אשר העלה אתכם מארץ מצרים בכח גדול ובזרוע נטויה אתו תיראו ולו תשתחוו ולו תזבחו׃ ");
INSERT INTO heb_vpl VALUES ("K217_37","013_17_37","2KI","17","37","37","ואת החקים ואת המשפטים והתורה והמצוה אשר כתב לכם תשמרון לעשות כל הימים ולא תיראו אלהים אחרים׃ ");
INSERT INTO heb_vpl VALUES ("K217_38","013_17_38","2KI","17","38","38","והברית אשר כרתי אתכם לא תשכחו ולא תיראו אלהים אחרים׃ ");
INSERT INTO heb_vpl VALUES ("K217_39","013_17_39","2KI","17","39","39","כי אם את יהוה אלהיכם תיראו והוא יציל אתכם מיד כל איביכם׃ ");
INSERT INTO heb_vpl VALUES ("K217_40","013_17_40","2KI","17","40","40","ולא שמעו כי אם כמשפטם הראשון הם עשים׃ ");
INSERT INTO heb_vpl VALUES ("K217_41","013_17_41","2KI","17","41","41","ויהיו הגוים האלה יראים את יהוה ואת פסיליהם היו עבדים גם בניהם ובני בניהם כאשר עשו אבתם הם עשים עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K218_1","013_18_1","2KI","18","1","1","ויהי בשנת שלש להושע בן אלה מלך ישראל מלך חזקיה בן אחז מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K218_2","013_18_2","2KI","18","2","2","בן עשרים וחמש שנה היה במלכו ועשרים ותשע שנה מלך בירושלם ושם אמו אבי בת זכריה׃ ");
INSERT INTO heb_vpl VALUES ("K218_3","013_18_3","2KI","18","3","3","ויעש הישר בעיני יהוה ככל אשר עשה דוד אביו׃ ");
INSERT INTO heb_vpl VALUES ("K218_4","013_18_4","2KI","18","4","4","הוא הסיר את הבמות ושבר את המצבת וכרת את האשרה וכתת נחש הנחשת אשר עשה משה כי עד הימים ההמה היו בני ישראל מקטרים לו ויקרא לו נחשתן׃ ");
INSERT INTO heb_vpl VALUES ("K218_5","013_18_5","2KI","18","5","5","ביהוה אלהי ישראל בטח ואחריו לא היה כמהו בכל מלכי יהודה ואשר היו לפניו׃ ");
INSERT INTO heb_vpl VALUES ("K218_6","013_18_6","2KI","18","6","6","וידבק ביהוה לא סר מאחריו וישמר מצותיו אשר צוה יהוה את משה׃ ");
INSERT INTO heb_vpl VALUES ("K218_7","013_18_7","2KI","18","7","7","והיה יהוה עמו בכל אשר יצא ישכיל וימרד במלך אשור ולא עבדו׃ ");
INSERT INTO heb_vpl VALUES ("K218_8","013_18_8","2KI","18","8","8","הוא הכה את פלשתים עד עזה ואת גבוליה ממגדל נוצרים עד עיר מבצר׃ ");
INSERT INTO heb_vpl VALUES ("K218_9","013_18_9","2KI","18","9","9","ויהי בשנה הרביעית למלך חזקיהו היא השנה השביעית להושע בן אלה מלך ישראל עלה שלמנאסר מלך אשור על שמרון ויצר עליה׃ ");
INSERT INTO heb_vpl VALUES ("K218_10","013_18_10","2KI","18","10","10","וילכדה מקצה שלש שנים בשנת שש לחזקיה היא שנת תשע להושע מלך ישראל נלכדה שמרון׃ ");
INSERT INTO heb_vpl VALUES ("K218_11","013_18_11","2KI","18","11","11","ויגל מלך אשור את ישראל אשורה וינחם בחלח ובחבור נהר גוזן וערי מדי׃ ");
INSERT INTO heb_vpl VALUES ("K218_12","013_18_12","2KI","18","12","12","על אשר לא שמעו בקול יהוה אלהיהם ויעברו את בריתו את כל אשר צוה משה עבד יהוה ולא שמעו ולא עשו׃ ");
INSERT INTO heb_vpl VALUES ("K218_13","013_18_13","2KI","18","13","13","ובארבע עשרה שנה למלך חזקיה עלה סנחריב מלך אשור על כל ערי יהודה הבצרות ויתפשם׃ ");
INSERT INTO heb_vpl VALUES ("K218_14","013_18_14","2KI","18","14","14","וישלח חזקיה מלך יהודה אל מלך אשור לכישה לאמר חטאתי שוב מעלי את אשר תתן עלי אשא וישם מלך אשור על חזקיה מלך יהודה שלש מאות ככר כסף ושלשים ככר זהב׃ ");
INSERT INTO heb_vpl VALUES ("K218_15","013_18_15","2KI","18","15","15","ויתן חזקיה את כל הכסף הנמצא בית יהוה ובאצרות בית המלך׃ ");
INSERT INTO heb_vpl VALUES ("K218_16","013_18_16","2KI","18","16","16","בעת ההיא קצץ חזקיה את דלתות היכל יהוה ואת האמנות אשר צפה חזקיה מלך יהודה ויתנם למלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("K218_17","013_18_17","2KI","18","17","17","וישלח מלך אשור את תרתן ואת רב סריס ואת רב שקה מן לכיש אל המלך חזקיהו בחיל כבד ירושלם ויעלו ויבאו ירושלם ויעלו ויבאו ויעמדו בתעלת הברכה העליונה אשר במסלת שדה כובס׃ ");
INSERT INTO heb_vpl VALUES ("K218_18","013_18_18","2KI","18","18","18","ויקראו אל המלך ויצא אלהם אליקים בן חלקיהו אשר על הבית ושבנה הספר ויואח בן אסף המזכיר׃ ");
INSERT INTO heb_vpl VALUES ("K218_19","013_18_19","2KI","18","19","19","ויאמר אלהם רב שקה אמרו נא אל חזקיהו כה אמר המלך הגדול מלך אשור מה הבטחון הזה אשר בטחת׃ ");
INSERT INTO heb_vpl VALUES ("K218_20","013_18_20","2KI","18","20","20","אמרת אך דבר שפתים עצה וגבורה למלחמה עתה על מי בטחת כי מרדת בי׃ ");
INSERT INTO heb_vpl VALUES ("K218_21","013_18_21","2KI","18","21","21","עתה הנה בטחת לך על משענת הקנה הרצוץ הזה על מצרים אשר יסמך איש עליו ובא בכפו ונקבה כן פרעה מלך מצרים לכל הבטחים עליו׃ ");
INSERT INTO heb_vpl VALUES ("K218_22","013_18_22","2KI","18","22","22","וכי תאמרון אלי אל יהוה אלהינו בטחנו הלוא הוא אשר הסיר חזקיהו את במתיו ואת מזבחתיו ויאמר ליהודה ולירושלם לפני המזבח הזה תשתחוו בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K218_23","013_18_23","2KI","18","23","23","ועתה התערב נא את אדני את מלך אשור ואתנה לך אלפים סוסים אם תוכל לתת לך רכבים עליהם׃ ");
INSERT INTO heb_vpl VALUES ("K218_24","013_18_24","2KI","18","24","24","ואיך תשיב את פני פחת אחד עבדי אדני הקטנים ותבטח לך על מצרים לרכב ולפרשים׃ ");
INSERT INTO heb_vpl VALUES ("K218_25","013_18_25","2KI","18","25","25","עתה המבלעדי יהוה עליתי על המקום הזה להשחתו יהוה אמר אלי עלה על הארץ הזאת והשחיתה׃ ");
INSERT INTO heb_vpl VALUES ("K218_26","013_18_26","2KI","18","26","26","ויאמר אליקים בן חלקיהו ושבנה ויואח אל רב שקה דבר נא אל עבדיך ארמית כי שמעים אנחנו ואל תדבר עמנו יהודית באזני העם אשר על החמה׃ ");
INSERT INTO heb_vpl VALUES ("K218_27","013_18_27","2KI","18","27","27","ויאמר אליהם רב שקה העל אדניך ואליך שלחני אדני לדבר את הדברים האלה הלא על האנשים הישבים על החמה לאכל את חריהם ולשתות את שיניהם עמכם׃ ");
INSERT INTO heb_vpl VALUES ("K218_28","013_18_28","2KI","18","28","28","ויעמד רב שקה ויקרא בקול גדול יהודית וידבר ויאמר שמעו דבר המלך הגדול מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("K218_29","013_18_29","2KI","18","29","29","כה אמר המלך אל ישיא לכם חזקיהו כי לא יוכל להציל אתכם מידו׃ ");
INSERT INTO heb_vpl VALUES ("K218_30","013_18_30","2KI","18","30","30","ואל יבטח אתכם חזקיהו אל יהוה לאמר הצל יצילנו יהוה ולא תנתן את העיר הזאת ביד מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("K218_31","013_18_31","2KI","18","31","31","אל תשמעו אל חזקיהו כי כה אמר מלך אשור עשו אתי ברכה וצאו אלי ואכלו איש גפנו ואיש תאנתו ושתו איש מי בורו׃ ");
INSERT INTO heb_vpl VALUES ("K218_32","013_18_32","2KI","18","32","32","עד באי ולקחתי אתכם אל ארץ כארצכם ארץ דגן ותירוש ארץ לחם וכרמים ארץ זית יצהר ודבש וחיו ולא תמתו ואל תשמעו אל חזקיהו כי יסית אתכם לאמר יהוה יצילנו׃ ");
INSERT INTO heb_vpl VALUES ("K218_33","013_18_33","2KI","18","33","33","ההצל הצילו אלהי הגוים איש את ארצו מיד מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("K218_34","013_18_34","2KI","18","34","34","איה אלהי חמת וארפד איה אלהי ספרוים הנע ועוה כי הצילו את שמרון מידי׃ ");
INSERT INTO heb_vpl VALUES ("K218_35","013_18_35","2KI","18","35","35","מי בכל אלהי הארצות אשר הצילו את ארצם מידי כי יציל יהוה את ירושלם מידי׃ ");
INSERT INTO heb_vpl VALUES ("K218_36","013_18_36","2KI","18","36","36","והחרישו העם ולא ענו אתו דבר כי מצות המלך היא לאמר לא תענהו׃ ");
INSERT INTO heb_vpl VALUES ("K218_37","013_18_37","2KI","18","37","37","ויבא אליקים בן חלקיה אשר על הבית ושבנא הספר ויואח בן אסף המזכיר אל חזקיהו קרועי בגדים ויגדו לו דברי רב שקה׃ ");
INSERT INTO heb_vpl VALUES ("K219_1","013_19_1","2KI","19","1","1","ויהי כשמע המלך חזקיהו ויקרע את בגדיו ויתכס בשק ויבא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K219_2","013_19_2","2KI","19","2","2","וישלח את אליקים אשר על הבית ושבנא הספר ואת זקני הכהנים מתכסים בשקים אל ישעיהו הנביא בן אמוץ׃ ");
INSERT INTO heb_vpl VALUES ("K219_3","013_19_3","2KI","19","3","3","ויאמרו אליו כה אמר חזקיהו יום צרה ותוכחה ונאצה היום הזה כי באו בנים עד משבר וכח אין ללדה׃ ");
INSERT INTO heb_vpl VALUES ("K219_4","013_19_4","2KI","19","4","4","אולי ישמע יהוה אלהיך את כל דברי רב שקה אשר שלחו מלך אשור אדניו לחרף אלהים חי והוכיח בדברים אשר שמע יהוה אלהיך ונשאת תפלה בעד השארית הנמצאה׃ ");
INSERT INTO heb_vpl VALUES ("K219_5","013_19_5","2KI","19","5","5","ויבאו עבדי המלך חזקיהו אל ישעיהו׃ ");
INSERT INTO heb_vpl VALUES ("K219_6","013_19_6","2KI","19","6","6","ויאמר להם ישעיהו כה תאמרון אל אדניכם כה אמר יהוה אל תירא מפני הדברים אשר שמעת אשר גדפו נערי מלך אשור אתי׃ ");
INSERT INTO heb_vpl VALUES ("K219_7","013_19_7","2KI","19","7","7","הנני נתן בו רוח ושמע שמועה ושב לארצו והפלתיו בחרב בארצו׃ ");
INSERT INTO heb_vpl VALUES ("K219_8","013_19_8","2KI","19","8","8","וישב רב שקה וימצא את מלך אשור נלחם על לבנה כי שמע כי נסע מלכיש׃ ");
INSERT INTO heb_vpl VALUES ("K219_9","013_19_9","2KI","19","9","9","וישמע אל תרהקה מלך כוש לאמר הנה יצא להלחם אתך וישב וישלח מלאכים אל חזקיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K219_10","013_19_10","2KI","19","10","10","כה תאמרון אל חזקיהו מלך יהודה לאמר אל ישאך אלהיך אשר אתה בטח בו לאמר לא תנתן ירושלם ביד מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("K219_11","013_19_11","2KI","19","11","11","הנה אתה שמעת את אשר עשו מלכי אשור לכל הארצות להחרימם ואתה תנצל׃ ");
INSERT INTO heb_vpl VALUES ("K219_12","013_19_12","2KI","19","12","12","ההצילו אתם אלהי הגוים אשר שחתו אבותי את גוזן ואת חרן ורצף ובני עדן אשר בתלאשר׃ ");
INSERT INTO heb_vpl VALUES ("K219_13","013_19_13","2KI","19","13","13","איו מלך חמת ומלך ארפד ומלך לעיר ספרוים הנע ועוה׃ ");
INSERT INTO heb_vpl VALUES ("K219_14","013_19_14","2KI","19","14","14","ויקח חזקיהו את הספרים מיד המלאכים ויקראם ויעל בית יהוה ויפרשהו חזקיהו לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K219_15","013_19_15","2KI","19","15","15","ויתפלל חזקיהו לפני יהוה ויאמר יהוה אלהי ישראל ישב הכרבים אתה הוא האלהים לבדך לכל ממלכות הארץ אתה עשית את השמים ואת הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K219_16","013_19_16","2KI","19","16","16","הטה יהוה אזנך ושמע פקח יהוה עיניך וראה ושמע את דברי סנחריב אשר שלחו לחרף אלהים חי׃ ");
INSERT INTO heb_vpl VALUES ("K219_17","013_19_17","2KI","19","17","17","אמנם יהוה החריבו מלכי אשור את הגוים ואת ארצם׃ ");
INSERT INTO heb_vpl VALUES ("K219_18","013_19_18","2KI","19","18","18","ונתנו את אלהיהם באש כי לא אלהים המה כי אם מעשה ידי אדם עץ ואבן ויאבדום׃ ");
INSERT INTO heb_vpl VALUES ("K219_19","013_19_19","2KI","19","19","19","ועתה יהוה אלהינו הושיענו נא מידו וידעו כל ממלכות הארץ כי אתה יהוה אלהים לבדך׃ ");
INSERT INTO heb_vpl VALUES ("K219_20","013_19_20","2KI","19","20","20","וישלח ישעיהו בן אמוץ אל חזקיהו לאמר כה אמר יהוה אלהי ישראל אשר התפללת אלי אל סנחרב מלך אשור שמעתי׃ ");
INSERT INTO heb_vpl VALUES ("K219_21","013_19_21","2KI","19","21","21","זה הדבר אשר דבר יהוה עליו בזה לך לעגה לך בתולת בת ציון אחריך ראש הניעה בת ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K219_22","013_19_22","2KI","19","22","22","את מי חרפת וגדפת ועל מי הרימות קול ותשא מרום עיניך על קדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K219_23","013_19_23","2KI","19","23","23","ביד מלאכיך חרפת אדני ותאמר ברכב רכבי אני עליתי מרום הרים ירכתי לבנון ואכרת קומת ארזיו מבחור ברשיו ואבואה מלון קצה יער כרמלו׃ ");
INSERT INTO heb_vpl VALUES ("K219_24","013_19_24","2KI","19","24","24","אני קרתי ושתיתי מים זרים ואחרב בכף פעמי כל יארי מצור׃ ");
INSERT INTO heb_vpl VALUES ("K219_25","013_19_25","2KI","19","25","25","הלא שמעת למרחוק אתה עשיתי למימי קדם ויצרתיה עתה הביאתיה ותהי להשות גלים נצים ערים בצרות׃ ");
INSERT INTO heb_vpl VALUES ("K219_26","013_19_26","2KI","19","26","26","וישביהן קצרי יד חתו ויבשו היו עשב שדה וירק דשא חציר גגות ושדפה לפני קמה׃ ");
INSERT INTO heb_vpl VALUES ("K219_27","013_19_27","2KI","19","27","27","ושבתך וצאתך ובאך ידעתי ואת התרגזך אלי׃ ");
INSERT INTO heb_vpl VALUES ("K219_28","013_19_28","2KI","19","28","28","יען התרגזך אלי ושאננך עלה באזני ושמתי חחי באפך ומתגי בשפתיך והשבתיך בדרך אשר באת בה׃ ");
INSERT INTO heb_vpl VALUES ("K219_29","013_19_29","2KI","19","29","29","וזה לך האות אכול השנה ספיח ובשנה השנית סחיש ובשנה השלישית זרעו וקצרו ונטעו כרמים ואכלו פרים׃ ");
INSERT INTO heb_vpl VALUES ("K219_30","013_19_30","2KI","19","30","30","ויספה פליטת בית יהודה הנשארה שרש למטה ועשה פרי למעלה׃ ");
INSERT INTO heb_vpl VALUES ("K219_31","013_19_31","2KI","19","31","31","כי מירושלם תצא שארית ופליטה מהר ציון קנאת יהוה תעשה זאת׃ ");
INSERT INTO heb_vpl VALUES ("K219_32","013_19_32","2KI","19","32","32","לכן כה אמר יהוה אל מלך אשור לא יבא אל העיר הזאת ולא יורה שם חץ ולא יקדמנה מגן ולא ישפך עליה סללה׃ ");
INSERT INTO heb_vpl VALUES ("K219_33","013_19_33","2KI","19","33","33","בדרך אשר יבא בה ישוב ואל העיר הזאת לא יבא נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K219_34","013_19_34","2KI","19","34","34","וגנותי אל העיר הזאת להושיעה למעני ולמען דוד עבדי׃ ");
INSERT INTO heb_vpl VALUES ("K219_35","013_19_35","2KI","19","35","35","ויהי בלילה ההוא ויצא מלאך יהוה ויך במחנה אשור מאה שמונים וחמשה אלף וישכימו בבקר והנה כלם פגרים מתים׃ ");
INSERT INTO heb_vpl VALUES ("K219_36","013_19_36","2KI","19","36","36","ויסע וילך וישב סנחריב מלך אשור וישב בנינוה׃ ");
INSERT INTO heb_vpl VALUES ("K219_37","013_19_37","2KI","19","37","37","ויהי הוא משתחוה בית נסרך אלהיו ואדרמלך ושראצר הכהו בחרב והמה נמלטו ארץ אררט וימלך אסר חדן בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K220_1","013_20_1","2KI","20","1","1","בימים ההם חלה חזקיהו למות ויבא אליו ישעיהו בן אמוץ הנביא ויאמר אליו כה אמר יהוה צו לביתך כי מת אתה ולא תחיה׃ ");
INSERT INTO heb_vpl VALUES ("K220_2","013_20_2","2KI","20","2","2","ויסב את פניו אל הקיר ויתפלל אל יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K220_3","013_20_3","2KI","20","3","3","אנה יהוה זכר נא את אשר התהלכתי לפניך באמת ובלבב שלם והטוב בעיניך עשיתי ויבך חזקיהו בכי גדול׃ ");
INSERT INTO heb_vpl VALUES ("K220_4","013_20_4","2KI","20","4","4","ויהי ישעיהו לא יצא העיר התיכנה ודבר יהוה היה אליו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K220_5","013_20_5","2KI","20","5","5","שוב ואמרת אל חזקיהו נגיד עמי כה אמר יהוה אלהי דוד אביך שמעתי את תפלתך ראיתי את דמעתך הנני רפא לך ביום השלישי תעלה בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K220_6","013_20_6","2KI","20","6","6","והספתי על ימיך חמש עשרה שנה ומכף מלך אשור אצילך ואת העיר הזאת וגנותי על העיר הזאת למעני ולמען דוד עבדי׃ ");
INSERT INTO heb_vpl VALUES ("K220_7","013_20_7","2KI","20","7","7","ויאמר ישעיהו קחו דבלת תאנים ויקחו וישימו על השחין ויחי׃ ");
INSERT INTO heb_vpl VALUES ("K220_8","013_20_8","2KI","20","8","8","ויאמר חזקיהו אל ישעיהו מה אות כי ירפא יהוה לי ועליתי ביום השלישי בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K220_9","013_20_9","2KI","20","9","9","ויאמר ישעיהו זה לך האות מאת יהוה כי יעשה יהוה את הדבר אשר דבר הלך הצל עשר מעלות אם ישוב עשר מעלות׃ ");
INSERT INTO heb_vpl VALUES ("K220_10","013_20_10","2KI","20","10","10","ויאמר יחזקיהו נקל לצל לנטות עשר מעלות לא כי ישוב הצל אחרנית עשר מעלות׃ ");
INSERT INTO heb_vpl VALUES ("K220_11","013_20_11","2KI","20","11","11","ויקרא ישעיהו הנביא אל יהוה וישב את הצל במעלות אשר ירדה במעלות אחז אחרנית עשר מעלות׃ ");
INSERT INTO heb_vpl VALUES ("K220_12","013_20_12","2KI","20","12","12","בעת ההיא שלח בראדך בלאדן בן בלאדן מלך בבל ספרים ומנחה אל חזקיהו כי שמע כי חלה חזקיהו׃ ");
INSERT INTO heb_vpl VALUES ("K220_13","013_20_13","2KI","20","13","13","וישמע עליהם חזקיהו ויראם את כל בית נכתה את הכסף ואת הזהב ואת הבשמים ואת שמן הטוב ואת בית כליו ואת כל אשר נמצא באוצרתיו לא היה דבר אשר לא הראם חזקיהו בביתו ובכל ממשלתו׃ ");
INSERT INTO heb_vpl VALUES ("K220_14","013_20_14","2KI","20","14","14","ויבא ישעיהו הנביא אל המלך חזקיהו ויאמר אליו מה אמרו האנשים האלה ומאין יבאו אליך ויאמר חזקיהו מארץ רחוקה באו מבבל׃ ");
INSERT INTO heb_vpl VALUES ("K220_15","013_20_15","2KI","20","15","15","ויאמר מה ראו בביתך ויאמר חזקיהו את כל אשר בביתי ראו לא היה דבר אשר לא הראיתם באצרתי׃ ");
INSERT INTO heb_vpl VALUES ("K220_16","013_20_16","2KI","20","16","16","ויאמר ישעיהו אל חזקיהו שמע דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K220_17","013_20_17","2KI","20","17","17","הנה ימים באים ונשא כל אשר בביתך ואשר אצרו אבתיך עד היום הזה בבלה לא יותר דבר אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K220_18","013_20_18","2KI","20","18","18","ומבניך אשר יצאו ממך אשר תוליד יקח והיו סריסים בהיכל מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("K220_19","013_20_19","2KI","20","19","19","ויאמר חזקיהו אל ישעיהו טוב דבר יהוה אשר דברת ויאמר הלוא אם שלום ואמת יהיה בימי׃ ");
INSERT INTO heb_vpl VALUES ("K220_20","013_20_20","2KI","20","20","20","ויתר דברי חזקיהו וכל גבורתו ואשר עשה את הברכה ואת התעלה ויבא את המים העירה הלא הם כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K220_21","013_20_21","2KI","20","21","21","וישכב חזקיהו עם אבתיו וימלך מנשה בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K221_1","013_21_1","2KI","21","1","1","בן שתים עשרה שנה מנשה במלכו וחמשים וחמש שנה מלך בירושלם ושם אמו חפצי בה׃ ");
INSERT INTO heb_vpl VALUES ("K221_2","013_21_2","2KI","21","2","2","ויעש הרע בעיני יהוה כתועבת הגוים אשר הוריש יהוה מפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K221_3","013_21_3","2KI","21","3","3","וישב ויבן את הבמות אשר אבד חזקיהו אביו ויקם מזבחת לבעל ויעש אשרה כאשר עשה אחאב מלך ישראל וישתחו לכל צבא השמים ויעבד אתם׃ ");
INSERT INTO heb_vpl VALUES ("K221_4","013_21_4","2KI","21","4","4","ובנה מזבחת בבית יהוה אשר אמר יהוה בירושלם אשים את שמי׃ ");
INSERT INTO heb_vpl VALUES ("K221_5","013_21_5","2KI","21","5","5","ויבן מזבחות לכל צבא השמים בשתי חצרות בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K221_6","013_21_6","2KI","21","6","6","והעביר את בנו באש ועונן ונחש ועשה אוב וידענים הרבה לעשות הרע בעיני יהוה להכעיס׃ ");
INSERT INTO heb_vpl VALUES ("K221_7","013_21_7","2KI","21","7","7","וישם את פסל האשרה אשר עשה בבית אשר אמר יהוה אל דוד ואל שלמה בנו בבית הזה ובירושלם אשר בחרתי מכל שבטי ישראל אשים את שמי לעולם׃ ");
INSERT INTO heb_vpl VALUES ("K221_8","013_21_8","2KI","21","8","8","ולא אסיף להניד רגל ישראל מן האדמה אשר נתתי לאבותם רק אם ישמרו לעשות ככל אשר צויתים ולכל התורה אשר צוה אתם עבדי משה׃ ");
INSERT INTO heb_vpl VALUES ("K221_9","013_21_9","2KI","21","9","9","ולא שמעו ויתעם מנשה לעשות את הרע מן הגוים אשר השמיד יהוה מפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("K221_10","013_21_10","2KI","21","10","10","וידבר יהוה ביד עבדיו הנביאים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K221_11","013_21_11","2KI","21","11","11","יען אשר עשה מנשה מלך יהודה התעבות האלה הרע מכל אשר עשו האמרי אשר לפניו ויחטא גם את יהודה בגלוליו׃ ");
INSERT INTO heb_vpl VALUES ("K221_12","013_21_12","2KI","21","12","12","לכן כה אמר יהוה אלהי ישראל הנני מביא רעה על ירושלם ויהודה אשר כל שמעיו תצלנה שתי אזניו׃ ");
INSERT INTO heb_vpl VALUES ("K221_13","013_21_13","2KI","21","13","13","ונטיתי על ירושלם את קו שמרון ואת משקלת בית אחאב ומחיתי את ירושלם כאשר ימחה את הצלחת מחה והפך על פניה׃ ");
INSERT INTO heb_vpl VALUES ("K221_14","013_21_14","2KI","21","14","14","ונטשתי את שארית נחלתי ונתתים ביד איביהם והיו לבז ולמשסה לכל איביהם׃ ");
INSERT INTO heb_vpl VALUES ("K221_15","013_21_15","2KI","21","15","15","יען אשר עשו את הרע בעיני ויהיו מכעסים אתי מן היום אשר יצאו אבותם ממצרים ועד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("K221_16","013_21_16","2KI","21","16","16","וגם דם נקי שפך מנשה הרבה מאד עד אשר מלא את ירושלם פה לפה לבד מחטאתו אשר החטיא את יהודה לעשות הרע בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K221_17","013_21_17","2KI","21","17","17","ויתר דברי מנשה וכל אשר עשה וחטאתו אשר חטא הלא הם כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K221_18","013_21_18","2KI","21","18","18","וישכב מנשה עם אבתיו ויקבר בגן ביתו בגן עזא וימלך אמון בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K221_19","013_21_19","2KI","21","19","19","בן עשרים ושתים שנה אמון במלכו ושתים שנים מלך בירושלם ושם אמו משלמת בת חרוץ מן יטבה׃ ");
INSERT INTO heb_vpl VALUES ("K221_20","013_21_20","2KI","21","20","20","ויעש הרע בעיני יהוה כאשר עשה מנשה אביו׃ ");
INSERT INTO heb_vpl VALUES ("K221_21","013_21_21","2KI","21","21","21","וילך בכל הדרך אשר הלך אביו ויעבד את הגללים אשר עבד אביו וישתחו להם׃ ");
INSERT INTO heb_vpl VALUES ("K221_22","013_21_22","2KI","21","22","22","ויעזב את יהוה אלהי אבתיו ולא הלך בדרך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K221_23","013_21_23","2KI","21","23","23","ויקשרו עבדי אמון עליו וימיתו את המלך בביתו׃ ");
INSERT INTO heb_vpl VALUES ("K221_24","013_21_24","2KI","21","24","24","ויך עם הארץ את כל הקשרים על המלך אמון וימליכו עם הארץ את יאשיהו בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K221_25","013_21_25","2KI","21","25","25","ויתר דברי אמון אשר עשה הלא הם כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K221_26","013_21_26","2KI","21","26","26","ויקבר אתו בקברתו בגן עזא וימלך יאשיהו בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K222_1","013_22_1","2KI","22","1","1","בן שמנה שנה יאשיהו במלכו ושלשים ואחת שנה מלך בירושלם ושם אמו ידידה בת עדיה מבצקת׃ ");
INSERT INTO heb_vpl VALUES ("K222_2","013_22_2","2KI","22","2","2","ויעש הישר בעיני יהוה וילך בכל דרך דוד אביו ולא סר ימין ושמאול׃ ");
INSERT INTO heb_vpl VALUES ("K222_3","013_22_3","2KI","22","3","3","ויהי בשמנה עשרה שנה למלך יאשיהו שלח המלך את שפן בן אצליהו בן משלם הספר בית יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K222_4","013_22_4","2KI","22","4","4","עלה אל חלקיהו הכהן הגדול ויתם את הכסף המובא בית יהוה אשר אספו שמרי הסף מאת העם׃ ");
INSERT INTO heb_vpl VALUES ("K222_5","013_22_5","2KI","22","5","5","ויתנה על יד עשי המלאכה המפקדים בבית יהוה ויתנו אתו לעשי המלאכה אשר בבית יהוה לחזק בדק הבית׃ ");
INSERT INTO heb_vpl VALUES ("K222_6","013_22_6","2KI","22","6","6","לחרשים ולבנים ולגדרים ולקנות עצים ואבני מחצב לחזק את הבית׃ ");
INSERT INTO heb_vpl VALUES ("K222_7","013_22_7","2KI","22","7","7","אך לא יחשב אתם הכסף הנתן על ידם כי באמונה הם עשים׃ ");
INSERT INTO heb_vpl VALUES ("K222_8","013_22_8","2KI","22","8","8","ויאמר חלקיהו הכהן הגדול על שפן הספר ספר התורה מצאתי בבית יהוה ויתן חלקיה את הספר אל שפן ויקראהו׃ ");
INSERT INTO heb_vpl VALUES ("K222_9","013_22_9","2KI","22","9","9","ויבא שפן הספר אל המלך וישב את המלך דבר ויאמר התיכו עבדיך את הכסף הנמצא בבית ויתנהו על יד עשי המלאכה המפקדים בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K222_10","013_22_10","2KI","22","10","10","ויגד שפן הספר למלך לאמר ספר נתן לי חלקיה הכהן ויקראהו שפן לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("K222_11","013_22_11","2KI","22","11","11","ויהי כשמע המלך את דברי ספר התורה ויקרע את בגדיו׃ ");
INSERT INTO heb_vpl VALUES ("K222_12","013_22_12","2KI","22","12","12","ויצו המלך את חלקיה הכהן ואת אחיקם בן שפן ואת עכבור בן מיכיה ואת שפן הספר ואת עשיה עבד המלך לאמר׃ ");
INSERT INTO heb_vpl VALUES ("K222_13","013_22_13","2KI","22","13","13","לכו דרשו את יהוה בעדי ובעד העם ובעד כל יהודה על דברי הספר הנמצא הזה כי גדולה חמת יהוה אשר היא נצתה בנו על אשר לא שמעו אבתינו על דברי הספר הזה לעשות ככל הכתוב עלינו׃ ");
INSERT INTO heb_vpl VALUES ("K222_14","013_22_14","2KI","22","14","14","וילך חלקיהו הכהן ואחיקם ועכבור ושפן ועשיה אל חלדה הנביאה אשת שלם בן תקוה בן חרחס שמר הבגדים והיא ישבת בירושלם במשנה וידברו אליה׃ ");
INSERT INTO heb_vpl VALUES ("K222_15","013_22_15","2KI","22","15","15","ותאמר אליהם כה אמר יהוה אלהי ישראל אמרו לאיש אשר שלח אתכם אלי׃ ");
INSERT INTO heb_vpl VALUES ("K222_16","013_22_16","2KI","22","16","16","כה אמר יהוה הנני מביא רעה אל המקום הזה ועל ישביו את כל דברי הספר אשר קרא מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K222_17","013_22_17","2KI","22","17","17","תחת אשר עזבוני ויקטרו לאלהים אחרים למען הכעיסני בכל מעשה ידיהם ונצתה חמתי במקום הזה ולא תכבה׃ ");
INSERT INTO heb_vpl VALUES ("K222_18","013_22_18","2KI","22","18","18","ואל מלך יהודה השלח אתכם לדרש את יהוה כה תאמרו אליו כה אמר יהוה אלהי ישראל הדברים אשר שמעת׃ ");
INSERT INTO heb_vpl VALUES ("K222_19","013_22_19","2KI","22","19","19","יען רך לבבך ותכנע מפני יהוה בשמעך אשר דברתי על המקום הזה ועל ישביו להיות לשמה ולקללה ותקרע את בגדיך ותבכה לפני וגם אנכי שמעתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K222_20","013_22_20","2KI","22","20","20","לכן הנני אספך על אבתיך ונאספת אל קברתיך בשלום ולא תראינה עיניך בכל הרעה אשר אני מביא על המקום הזה וישיבו את המלך דבר׃ ");
INSERT INTO heb_vpl VALUES ("K223_1","013_23_1","2KI","23","1","1","וישלח המלך ויאספו אליו כל זקני יהודה וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K223_2","013_23_2","2KI","23","2","2","ויעל המלך בית יהוה וכל איש יהודה וכל ישבי ירושלם אתו והכהנים והנביאים וכל העם למקטן ועד גדול ויקרא באזניהם את כל דברי ספר הברית הנמצא בבית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K223_3","013_23_3","2KI","23","3","3","ויעמד המלך על העמוד ויכרת את הברית לפני יהוה ללכת אחר יהוה ולשמר מצותיו ואת עדותיו ואת חקתיו בכל לב ובכל נפש להקים את דברי הברית הזאת הכתבים על הספר הזה ויעמד כל העם בברית׃ ");
INSERT INTO heb_vpl VALUES ("K223_4","013_23_4","2KI","23","4","4","ויצו המלך את חלקיהו הכהן הגדול ואת כהני המשנה ואת שמרי הסף להוציא מהיכל יהוה את כל הכלים העשוים לבעל ולאשרה ולכל צבא השמים וישרפם מחוץ לירושלם בשדמות קדרון ונשא את עפרם בית אל׃ ");
INSERT INTO heb_vpl VALUES ("K223_5","013_23_5","2KI","23","5","5","והשבית את הכמרים אשר נתנו מלכי יהודה ויקטר בבמות בערי יהודה ומסבי ירושלם ואת המקטרים לבעל לשמש ולירח ולמזלות ולכל צבא השמים׃ ");
INSERT INTO heb_vpl VALUES ("K223_6","013_23_6","2KI","23","6","6","ויצא את האשרה מבית יהוה מחוץ לירושלם אל נחל קדרון וישרף אתה בנחל קדרון וידק לעפר וישלך את עפרה על קבר בני העם׃ ");
INSERT INTO heb_vpl VALUES ("K223_7","013_23_7","2KI","23","7","7","ויתץ את בתי הקדשים אשר בבית יהוה אשר הנשים ארגות שם בתים לאשרה׃ ");
INSERT INTO heb_vpl VALUES ("K223_8","013_23_8","2KI","23","8","8","ויבא את כל הכהנים מערי יהודה ויטמא את הבמות אשר קטרו שמה הכהנים מגבע עד באר שבע ונתץ את במות השערים אשר פתח שער יהושע שר העיר אשר על שמאול איש בשער העיר׃ ");
INSERT INTO heb_vpl VALUES ("K223_9","013_23_9","2KI","23","9","9","אך לא יעלו כהני הבמות אל מזבח יהוה בירושלם כי אם אכלו מצות בתוך אחיהם׃ ");
INSERT INTO heb_vpl VALUES ("K223_10","013_23_10","2KI","23","10","10","וטמא את התפת אשר בגי בני הנם לבלתי להעביר איש את בנו ואת בתו באש למלך׃ ");
INSERT INTO heb_vpl VALUES ("K223_11","013_23_11","2KI","23","11","11","וישבת את הסוסים אשר נתנו מלכי יהודה לשמש מבא בית יהוה אל לשכת נתן מלך הסריס אשר בפרורים ואת מרכבות השמש שרף באש׃ ");
INSERT INTO heb_vpl VALUES ("K223_12","013_23_12","2KI","23","12","12","ואת המזבחות אשר על הגג עלית אחז אשר עשו מלכי יהודה ואת המזבחות אשר עשה מנשה בשתי חצרות בית יהוה נתץ המלך וירץ משם והשליך את עפרם אל נחל קדרון׃ ");
INSERT INTO heb_vpl VALUES ("K223_13","013_23_13","2KI","23","13","13","ואת הבמות אשר על פני ירושלם אשר מימין להר המשחית אשר בנה שלמה מלך ישראל לעשתרת שקץ צידנים ולכמוש שקץ מואב ולמלכם תועבת בני עמון טמא המלך׃ ");
INSERT INTO heb_vpl VALUES ("K223_14","013_23_14","2KI","23","14","14","ושבר את המצבות ויכרת את האשרים וימלא את מקומם עצמות אדם׃ ");
INSERT INTO heb_vpl VALUES ("K223_15","013_23_15","2KI","23","15","15","וגם את המזבח אשר בבית אל הבמה אשר עשה ירבעם בן נבט אשר החטיא את ישראל גם את המזבח ההוא ואת הבמה נתץ וישרף את הבמה הדק לעפר ושרף אשרה׃ ");
INSERT INTO heb_vpl VALUES ("K223_16","013_23_16","2KI","23","16","16","ויפן יאשיהו וירא את הקברים אשר שם בהר וישלח ויקח את העצמות מן הקברים וישרף על המזבח ויטמאהו כדבר יהוה אשר קרא איש האלהים אשר קרא את הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("K223_17","013_23_17","2KI","23","17","17","ויאמר מה הציון הלז אשר אני ראה ויאמרו אליו אנשי העיר הקבר איש האלהים אשר בא מיהודה ויקרא את הדברים האלה אשר עשית על המזבח בית אל׃ ");
INSERT INTO heb_vpl VALUES ("K223_18","013_23_18","2KI","23","18","18","ויאמר הניחו לו איש אל ינע עצמתיו וימלטו עצמתיו את עצמות הנביא אשר בא משמרון׃ ");
INSERT INTO heb_vpl VALUES ("K223_19","013_23_19","2KI","23","19","19","וגם את כל בתי הבמות אשר בערי שמרון אשר עשו מלכי ישראל להכעיס הסיר יאשיהו ויעש להם ככל המעשים אשר עשה בבית אל׃ ");
INSERT INTO heb_vpl VALUES ("K223_20","013_23_20","2KI","23","20","20","ויזבח את כל כהני הבמות אשר שם על המזבחות וישרף את עצמות אדם עליהם וישב ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K223_21","013_23_21","2KI","23","21","21","ויצו המלך את כל העם לאמר עשו פסח ליהוה אלהיכם ככתוב על ספר הברית הזה׃ ");
INSERT INTO heb_vpl VALUES ("K223_22","013_23_22","2KI","23","22","22","כי לא נעשה כפסח הזה מימי השפטים אשר שפטו את ישראל וכל ימי מלכי ישראל ומלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K223_23","013_23_23","2KI","23","23","23","כי אם בשמנה עשרה שנה למלך יאשיהו נעשה הפסח הזה ליהוה בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K223_24","013_23_24","2KI","23","24","24","וגם את האבות ואת הידענים ואת התרפים ואת הגללים ואת כל השקצים אשר נראו בארץ יהודה ובירושלם בער יאשיהו למען הקים את דברי התורה הכתבים על הספר אשר מצא חלקיהו הכהן בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K223_25","013_23_25","2KI","23","25","25","וכמהו לא היה לפניו מלך אשר שב אל יהוה בכל לבבו ובכל נפשו ובכל מאדו ככל תורת משה ואחריו לא קם כמהו׃ ");
INSERT INTO heb_vpl VALUES ("K223_26","013_23_26","2KI","23","26","26","אך לא שב יהוה מחרון אפו הגדול אשר חרה אפו ביהודה על כל הכעסים אשר הכעיסו מנשה׃ ");
INSERT INTO heb_vpl VALUES ("K223_27","013_23_27","2KI","23","27","27","ויאמר יהוה גם את יהודה אסיר מעל פני כאשר הסרתי את ישראל ומאסתי את העיר הזאת אשר בחרתי את ירושלם ואת הבית אשר אמרתי יהיה שמי שם׃ ");
INSERT INTO heb_vpl VALUES ("K223_28","013_23_28","2KI","23","28","28","ויתר דברי יאשיהו וכל אשר עשה הלא הם כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K223_29","013_23_29","2KI","23","29","29","בימיו עלה פרעה נכה מלך מצרים על מלך אשור על נהר פרת וילך המלך יאשיהו לקראתו וימיתהו במגדו כראתו אתו׃ ");
INSERT INTO heb_vpl VALUES ("K223_30","013_23_30","2KI","23","30","30","וירכבהו עבדיו מת ממגדו ויבאהו ירושלם ויקברהו בקברתו ויקח עם הארץ את יהואחז בן יאשיהו וימשחו אתו וימליכו אתו תחת אביו׃ ");
INSERT INTO heb_vpl VALUES ("K223_31","013_23_31","2KI","23","31","31","בן עשרים ושלש שנה יהואחז במלכו ושלשה חדשים מלך בירושלם ושם אמו חמוטל בת ירמיהו מלבנה׃ ");
INSERT INTO heb_vpl VALUES ("K223_32","013_23_32","2KI","23","32","32","ויעש הרע בעיני יהוה ככל אשר עשו אבתיו׃ ");
INSERT INTO heb_vpl VALUES ("K223_33","013_23_33","2KI","23","33","33","ויאסרהו פרעה נכה ברבלה בארץ חמת במלך בירושלם ויתן ענש על הארץ מאה ככר כסף וככר זהב׃ ");
INSERT INTO heb_vpl VALUES ("K223_34","013_23_34","2KI","23","34","34","וימלך פרעה נכה את אליקים בן יאשיהו תחת יאשיהו אביו ויסב את שמו יהויקים ואת יהואחז לקח ויבא מצרים וימת שם׃ ");
INSERT INTO heb_vpl VALUES ("K223_35","013_23_35","2KI","23","35","35","והכסף והזהב נתן יהויקים לפרעה אך העריך את הארץ לתת את הכסף על פי פרעה איש כערכו נגש את הכסף ואת הזהב את עם הארץ לתת לפרעה נכה׃ ");
INSERT INTO heb_vpl VALUES ("K223_36","013_23_36","2KI","23","36","36","בן עשרים וחמש שנה יהויקים במלכו ואחת עשרה שנה מלך בירושלם ושם אמו זבידה בת פדיה מן רומה׃ ");
INSERT INTO heb_vpl VALUES ("K223_37","013_23_37","2KI","23","37","37","ויעש הרע בעיני יהוה ככל אשר עשו אבתיו׃ ");
INSERT INTO heb_vpl VALUES ("K224_1","013_24_1","2KI","24","1","1","בימיו עלה נבכדנאצר מלך בבל ויהי לו יהויקים עבד שלש שנים וישב וימרד בו׃ ");
INSERT INTO heb_vpl VALUES ("K224_2","013_24_2","2KI","24","2","2","וישלח יהוה בו את גדודי כשדים ואת גדודי ארם ואת גדודי מואב ואת גדודי בני עמון וישלחם ביהודה להאבידו כדבר יהוה אשר דבר ביד עבדיו הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("K224_3","013_24_3","2KI","24","3","3","אך על פי יהוה היתה ביהודה להסיר מעל פניו בחטאת מנשה ככל אשר עשה׃ ");
INSERT INTO heb_vpl VALUES ("K224_4","013_24_4","2KI","24","4","4","וגם דם הנקי אשר שפך וימלא את ירושלם דם נקי ולא אבה יהוה לסלח׃ ");
INSERT INTO heb_vpl VALUES ("K224_5","013_24_5","2KI","24","5","5","ויתר דברי יהויקים וכל אשר עשה הלא הם כתובים על ספר דברי הימים למלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("K224_6","013_24_6","2KI","24","6","6","וישכב יהויקים עם אבתיו וימלך יהויכין בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("K224_7","013_24_7","2KI","24","7","7","ולא הסיף עוד מלך מצרים לצאת מארצו כי לקח מלך בבל מנחל מצרים עד נהר פרת כל אשר היתה למלך מצרים׃ ");
INSERT INTO heb_vpl VALUES ("K224_8","013_24_8","2KI","24","8","8","בן שמנה עשרה שנה יהויכין במלכו ושלשה חדשים מלך בירושלם ושם אמו נחשתא בת אלנתן מירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K224_9","013_24_9","2KI","24","9","9","ויעש הרע בעיני יהוה ככל אשר עשה אביו׃ ");
INSERT INTO heb_vpl VALUES ("K224_10","013_24_10","2KI","24","10","10","בעת ההיא עלה עבדי נבכדנאצר מלך בבל ירושלם ותבא העיר במצור׃ ");
INSERT INTO heb_vpl VALUES ("K224_11","013_24_11","2KI","24","11","11","ויבא נבוכדנאצר מלך בבל על העיר ועבדיו צרים עליה׃ ");
INSERT INTO heb_vpl VALUES ("K224_12","013_24_12","2KI","24","12","12","ויצא יהויכין מלך יהודה על מלך בבל הוא ואמו ועבדיו ושריו וסריסיו ויקח אתו מלך בבל בשנת שמנה למלכו׃ ");
INSERT INTO heb_vpl VALUES ("K224_13","013_24_13","2KI","24","13","13","ויוצא משם את כל אוצרות בית יהוה ואוצרות בית המלך ויקצץ את כל כלי הזהב אשר עשה שלמה מלך ישראל בהיכל יהוה כאשר דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("K224_14","013_24_14","2KI","24","14","14","והגלה את כל ירושלם ואת כל השרים ואת כל גבורי החיל עשרה אלפים גולה וכל החרש והמסגר לא נשאר זולת דלת עם הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K224_15","013_24_15","2KI","24","15","15","ויגל את יהויכין בבלה ואת אם המלך ואת נשי המלך ואת סריסיו ואת אולי הארץ הוליך גולה מירושלם בבלה׃ ");
INSERT INTO heb_vpl VALUES ("K224_16","013_24_16","2KI","24","16","16","ואת כל אנשי החיל שבעת אלפים והחרש והמסגר אלף הכל גבורים עשי מלחמה ויביאם מלך בבל גולה בבלה׃ ");
INSERT INTO heb_vpl VALUES ("K224_17","013_24_17","2KI","24","17","17","וימלך מלך בבל את מתניה דדו תחתיו ויסב את שמו צדקיהו׃ ");
INSERT INTO heb_vpl VALUES ("K224_18","013_24_18","2KI","24","18","18","בן עשרים ואחת שנה צדקיהו במלכו ואחת עשרה שנה מלך בירושלם ושם אמו חמיטל בת ירמיהו מלבנה׃ ");
INSERT INTO heb_vpl VALUES ("K224_19","013_24_19","2KI","24","19","19","ויעש הרע בעיני יהוה ככל אשר עשה יהויקים׃ ");
INSERT INTO heb_vpl VALUES ("K224_20","013_24_20","2KI","24","20","20","כי על אף יהוה היתה בירושלם וביהודה עד השלכו אתם מעל פניו וימרד צדקיהו במלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("K225_1","013_25_1","2KI","25","1","1","ויהי בשנת התשיעית למלכו בחדש העשירי בעשור לחדש בא נבכדנאצר מלך בבל הוא וכל חילו על ירושלם ויחן עליה ויבנו עליה דיק סביב׃ ");
INSERT INTO heb_vpl VALUES ("K225_2","013_25_2","2KI","25","2","2","ותבא העיר במצור עד עשתי עשרה שנה למלך צדקיהו׃ ");
INSERT INTO heb_vpl VALUES ("K225_3","013_25_3","2KI","25","3","3","בתשעה לחדש ויחזק הרעב בעיר ולא היה לחם לעם הארץ׃ ");
INSERT INTO heb_vpl VALUES ("K225_4","013_25_4","2KI","25","4","4","ותבקע העיר וכל אנשי המלחמה הלילה דרך שער בין החמתים אשר על גן המלך וכשדים על העיר סביב וילך דרך הערבה׃ ");
INSERT INTO heb_vpl VALUES ("K225_5","013_25_5","2KI","25","5","5","וירדפו חיל כשדים אחר המלך וישגו אתו בערבות ירחו וכל חילו נפצו מעליו׃ ");
INSERT INTO heb_vpl VALUES ("K225_6","013_25_6","2KI","25","6","6","ויתפשו את המלך ויעלו אתו אל מלך בבל רבלתה וידברו אתו משפט׃ ");
INSERT INTO heb_vpl VALUES ("K225_7","013_25_7","2KI","25","7","7","ואת בני צדקיהו שחטו לעיניו ואת עיני צדקיהו עור ויאסרהו בנחשתים ויבאהו בבל׃ ");
INSERT INTO heb_vpl VALUES ("K225_8","013_25_8","2KI","25","8","8","ובחדש החמישי בשבעה לחדש היא שנת תשע עשרה שנה למלך נבכדנאצר מלך בבל בא נבוזראדן רב טבחים עבד מלך בבל ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("K225_9","013_25_9","2KI","25","9","9","וישרף את בית יהוה ואת בית המלך ואת כל בתי ירושלם ואת כל בית גדול שרף באש׃ ");
INSERT INTO heb_vpl VALUES ("K225_10","013_25_10","2KI","25","10","10","ואת חומת ירושלם סביב נתצו כל חיל כשדים אשר רב טבחים׃ ");
INSERT INTO heb_vpl VALUES ("K225_11","013_25_11","2KI","25","11","11","ואת יתר העם הנשארים בעיר ואת הנפלים אשר נפלו על המלך בבל ואת יתר ההמון הגלה נבוזראדן רב טבחים׃ ");
INSERT INTO heb_vpl VALUES ("K225_12","013_25_12","2KI","25","12","12","ומדלת הארץ השאיר רב טבחים לכרמים וליגבים׃ ");
INSERT INTO heb_vpl VALUES ("K225_13","013_25_13","2KI","25","13","13","ואת עמודי הנחשת אשר בית יהוה ואת המכנות ואת ים הנחשת אשר בבית יהוה שברו כשדים וישאו את נחשתם בבלה׃ ");
INSERT INTO heb_vpl VALUES ("K225_14","013_25_14","2KI","25","14","14","ואת הסירת ואת היעים ואת המזמרות ואת הכפות ואת כל כלי הנחשת אשר ישרתו בם לקחו׃ ");
INSERT INTO heb_vpl VALUES ("K225_15","013_25_15","2KI","25","15","15","ואת המחתות ואת המזרקות אשר זהב זהב ואשר כסף כסף לקח רב טבחים׃ ");
INSERT INTO heb_vpl VALUES ("K225_16","013_25_16","2KI","25","16","16","העמודים שנים הים האחד והמכנות אשר עשה שלמה לבית יהוה לא היה משקל לנחשת כל הכלים האלה׃ ");
INSERT INTO heb_vpl VALUES ("K225_17","013_25_17","2KI","25","17","17","שמנה עשרה אמה קומת העמוד האחד וכתרת עליו נחשת וקומת הכתרת שלש אמה ושבכה ורמנים על הכתרת סביב הכל נחשת וכאלה לעמוד השני על השבכה׃ ");
INSERT INTO heb_vpl VALUES ("K225_18","013_25_18","2KI","25","18","18","ויקח רב טבחים את שריה כהן הראש ואת צפניהו כהן משנה ואת שלשת שמרי הסף׃ ");
INSERT INTO heb_vpl VALUES ("K225_19","013_25_19","2KI","25","19","19","ומן העיר לקח סריס אחד אשר הוא פקיד על אנשי המלחמה וחמשה אנשים מראי פני המלך אשר נמצאו בעיר ואת הספר שר הצבא המצבא את עם הארץ וששים איש מעם הארץ הנמצאים בעיר׃ ");
INSERT INTO heb_vpl VALUES ("K225_20","013_25_20","2KI","25","20","20","ויקח אתם נבוזראדן רב טבחים וילך אתם על מלך בבל רבלתה׃ ");
INSERT INTO heb_vpl VALUES ("K225_21","013_25_21","2KI","25","21","21","ויך אתם מלך בבל וימיתם ברבלה בארץ חמת ויגל יהודה מעל אדמתו׃ ");
INSERT INTO heb_vpl VALUES ("K225_22","013_25_22","2KI","25","22","22","והעם הנשאר בארץ יהודה אשר השאיר נבוכדנאצר מלך בבל ויפקד עליהם את גדליהו בן אחיקם בן שפן׃ ");
INSERT INTO heb_vpl VALUES ("K225_23","013_25_23","2KI","25","23","23","וישמעו כל שרי החילים המה והאנשים כי הפקיד מלך בבל את גדליהו ויבאו אל גדליהו המצפה וישמעאל בן נתניה ויוחנן בן קרח ושריה בן תנחמת הנטפתי ויאזניהו בן המעכתי המה ואנשיהם׃ ");
INSERT INTO heb_vpl VALUES ("K225_24","013_25_24","2KI","25","24","24","וישבע להם גדליהו ולאנשיהם ויאמר להם אל תיראו מעבדי הכשדים שבו בארץ ועבדו את מלך בבל ויטב לכם׃ ");
INSERT INTO heb_vpl VALUES ("K225_25","013_25_25","2KI","25","25","25","ויהי בחדש השביעי בא ישמעאל בן נתניה בן אלישמע מזרע המלוכה ועשרה אנשים אתו ויכו את גדליהו וימת ואת היהודים ואת הכשדים אשר היו אתו במצפה׃ ");
INSERT INTO heb_vpl VALUES ("K225_26","013_25_26","2KI","25","26","26","ויקמו כל העם מקטן ועד גדול ושרי החילים ויבאו מצרים כי יראו מפני כשדים׃ ");
INSERT INTO heb_vpl VALUES ("K225_27","013_25_27","2KI","25","27","27","ויהי בשלשים ושבע שנה לגלות יהויכין מלך יהודה בשנים עשר חדש בעשרים ושבעה לחדש נשא אויל מרדך מלך בבל בשנת מלכו את ראש יהויכין מלך יהודה מבית כלא׃ ");
INSERT INTO heb_vpl VALUES ("K225_28","013_25_28","2KI","25","28","28","וידבר אתו טבות ויתן את כסאו מעל כסא המלכים אשר אתו בבבל׃ ");
INSERT INTO heb_vpl VALUES ("K225_29","013_25_29","2KI","25","29","29","ושנא את בגדי כלאו ואכל לחם תמיד לפניו כל ימי חייו׃ ");
INSERT INTO heb_vpl VALUES ("K225_30","013_25_30","2KI","25","30","30","וארחתו ארחת תמיד נתנה לו מאת המלך דבר יום ביומו כל ימי חיו׃ ");
INSERT INTO heb_vpl VALUES ("R11_1","014_1_1","1CH","1","1","1","אדם שת אנוש׃ ");
INSERT INTO heb_vpl VALUES ("R11_2","014_1_2","1CH","1","2","2","קינן מהללאל ירד׃ ");
INSERT INTO heb_vpl VALUES ("R11_3","014_1_3","1CH","1","3","3","חנוך מתושלח למך׃ ");
INSERT INTO heb_vpl VALUES ("R11_4","014_1_4","1CH","1","4","4","נח שם חם ויפת׃ ");
INSERT INTO heb_vpl VALUES ("R11_5","014_1_5","1CH","1","5","5","בני יפת גמר ומגוג ומדי ויון ותבל ומשך ותירס׃ ");
INSERT INTO heb_vpl VALUES ("R11_6","014_1_6","1CH","1","6","6","ובני גמר אשכנז ודיפת ותוגרמה׃ ");
INSERT INTO heb_vpl VALUES ("R11_7","014_1_7","1CH","1","7","7","ובני יון אלישה ותרשישה כתים ורודנים׃ ");
INSERT INTO heb_vpl VALUES ("R11_8","014_1_8","1CH","1","8","8","בני חם כוש ומצרים פוט וכנען׃ ");
INSERT INTO heb_vpl VALUES ("R11_9","014_1_9","1CH","1","9","9","ובני כוש סבא וחוילה וסבתא ורעמא וסבתכא ובני רעמא שבא ודדן׃ ");
INSERT INTO heb_vpl VALUES ("R11_10","014_1_10","1CH","1","10","10","וכוש ילד את נמרוד הוא החל להיות גבור בארץ׃ ");
INSERT INTO heb_vpl VALUES ("R11_11","014_1_11","1CH","1","11","11","ומצרים ילד את לודיים ואת ענמים ואת להבים ואת נפתחים׃ ");
INSERT INTO heb_vpl VALUES ("R11_12","014_1_12","1CH","1","12","12","ואת פתרסים ואת כסלחים אשר יצאו משם פלשתים ואת כפתרים׃ ");
INSERT INTO heb_vpl VALUES ("R11_13","014_1_13","1CH","1","13","13","וכנען ילד את צידון בכרו ואת חת׃ ");
INSERT INTO heb_vpl VALUES ("R11_14","014_1_14","1CH","1","14","14","ואת היבוסי ואת האמרי ואת הגרגשי׃ ");
INSERT INTO heb_vpl VALUES ("R11_15","014_1_15","1CH","1","15","15","ואת החוי ואת הערקי ואת הסיני׃ ");
INSERT INTO heb_vpl VALUES ("R11_16","014_1_16","1CH","1","16","16","ואת הארודי ואת הצמרי ואת החמתי׃ ");
INSERT INTO heb_vpl VALUES ("R11_17","014_1_17","1CH","1","17","17","בני שם עילם ואשור וארפכשד ולוד וארם ועוץ וחול וגתר ומשך׃ ");
INSERT INTO heb_vpl VALUES ("R11_18","014_1_18","1CH","1","18","18","וארפכשד ילד את שלח ושלח ילד את עבר׃ ");
INSERT INTO heb_vpl VALUES ("R11_19","014_1_19","1CH","1","19","19","ולעבר ילד שני בנים שם האחד פלג כי בימיו נפלגה הארץ ושם אחיו יקטן׃ ");
INSERT INTO heb_vpl VALUES ("R11_20","014_1_20","1CH","1","20","20","ויקטן ילד את אלמודד ואת שלף ואת חצרמות ואת ירח׃ ");
INSERT INTO heb_vpl VALUES ("R11_21","014_1_21","1CH","1","21","21","ואת הדורם ואת אוזל ואת דקלה׃ ");
INSERT INTO heb_vpl VALUES ("R11_22","014_1_22","1CH","1","22","22","ואת עיבל ואת אבימאל ואת שבא׃ ");
INSERT INTO heb_vpl VALUES ("R11_23","014_1_23","1CH","1","23","23","ואת אופיר ואת חוילה ואת יובב כל אלה בני יקטן׃ ");
INSERT INTO heb_vpl VALUES ("R11_24","014_1_24","1CH","1","24","24","שם ארפכשד שלח׃ ");
INSERT INTO heb_vpl VALUES ("R11_25","014_1_25","1CH","1","25","25","עבר פלג רעו׃ ");
INSERT INTO heb_vpl VALUES ("R11_26","014_1_26","1CH","1","26","26","שרוג נחור תרח׃ ");
INSERT INTO heb_vpl VALUES ("R11_27","014_1_27","1CH","1","27","27","אברם הוא אברהם׃ ");
INSERT INTO heb_vpl VALUES ("R11_28","014_1_28","1CH","1","28","28","בני אברהם יצחק וישמעאל׃ ");
INSERT INTO heb_vpl VALUES ("R11_29","014_1_29","1CH","1","29","29","אלה תלדותם בכור ישמעאל נביות וקדר ואדבאל ומבשם׃ ");
INSERT INTO heb_vpl VALUES ("R11_30","014_1_30","1CH","1","30","30","משמע ודומה משא חדד ותימא׃ ");
INSERT INTO heb_vpl VALUES ("R11_31","014_1_31","1CH","1","31","31","יטור נפיש וקדמה אלה הם בני ישמעאל׃ ");
INSERT INTO heb_vpl VALUES ("R11_32","014_1_32","1CH","1","32","32","ובני קטורה פילגש אברהם ילדה את זמרן ויקשן ומדן ומדין וישבק ושוח ובני יקשן שבא ודדן׃ ");
INSERT INTO heb_vpl VALUES ("R11_33","014_1_33","1CH","1","33","33","ובני מדין עיפה ועפר וחנוך ואבידע ואלדעה כל אלה בני קטורה׃ ");
INSERT INTO heb_vpl VALUES ("R11_34","014_1_34","1CH","1","34","34","ויולד אברהם את יצחק בני יצחק עשו וישראל׃ ");
INSERT INTO heb_vpl VALUES ("R11_35","014_1_35","1CH","1","35","35","בני עשו אליפז רעואל ויעוש ויעלם וקרח׃ ");
INSERT INTO heb_vpl VALUES ("R11_36","014_1_36","1CH","1","36","36","בני אליפז תימן ואומר צפי וגעתם קנז ותמנע ועמלק׃ ");
INSERT INTO heb_vpl VALUES ("R11_37","014_1_37","1CH","1","37","37","בני רעואל נחת זרח שמה ומזה׃ ");
INSERT INTO heb_vpl VALUES ("R11_38","014_1_38","1CH","1","38","38","ובני שעיר לוטן ושובל וצבעון וענה ודישן ואצר ודישן׃ ");
INSERT INTO heb_vpl VALUES ("R11_39","014_1_39","1CH","1","39","39","ובני לוטן חרי והומם ואחות לוטן תמנע׃ ");
INSERT INTO heb_vpl VALUES ("R11_40","014_1_40","1CH","1","40","40","בני שובל עלין ומנחת ועיבל שפי ואונם ובני צבעון איה וענה׃ ");
INSERT INTO heb_vpl VALUES ("R11_41","014_1_41","1CH","1","41","41","בני ענה דישון ובני דישון חמרן ואשבן ויתרן וכרן׃ ");
