INSERT INTO heb_vpl VALUES ("R18_32","014_8_32","1CH","8","32","32","ומקלות הוליד את שמאה ואף המה נגד אחיהם ישבו בירושלם עם אחיהם׃ ");
INSERT INTO heb_vpl VALUES ("R18_33","014_8_33","1CH","8","33","33","ונר הוליד את קיש וקיש הוליד את שאול ושאול הוליד את יהונתן ואת מלכי שוע ואת אבינדב ואת אשבעל׃ ");
INSERT INTO heb_vpl VALUES ("R18_34","014_8_34","1CH","8","34","34","ובן יהונתן מריב בעל ומריב בעל הוליד את מיכה׃ ");
INSERT INTO heb_vpl VALUES ("R18_35","014_8_35","1CH","8","35","35","ובני מיכה פיתון ומלך ותארע ואחז׃ ");
INSERT INTO heb_vpl VALUES ("R18_36","014_8_36","1CH","8","36","36","ואחז הוליד את יהועדה ויהועדה הוליד את עלמת ואת עזמות ואת זמרי וזמרי הוליד את מוצא׃ ");
INSERT INTO heb_vpl VALUES ("R18_37","014_8_37","1CH","8","37","37","ומוצא הוליד את בנעא רפה בנו אלעשה בנו אצל בנו׃ ");
INSERT INTO heb_vpl VALUES ("R18_38","014_8_38","1CH","8","38","38","ולאצל ששה בנים ואלה שמותם עזריקם בכרו וישמעאל ושעריה ועבדיה וחנן כל אלה בני אצל׃ ");
INSERT INTO heb_vpl VALUES ("R18_39","014_8_39","1CH","8","39","39","ובני עשק אחיו אולם בכרו יעוש השני ואליפלט השלשי׃ ");
INSERT INTO heb_vpl VALUES ("R18_40","014_8_40","1CH","8","40","40","ויהיו בני אולם אנשים גברי חיל דרכי קשת ומרבים בנים ובני בנים מאה וחמשים כל אלה מבני בנימן׃ ");
INSERT INTO heb_vpl VALUES ("R19_1","014_9_1","1CH","9","1","1","וכל ישראל התיחשו והנם כתובים על ספר מלכי ישראל ויהודה הגלו לבבל במעלם׃ ");
INSERT INTO heb_vpl VALUES ("R19_2","014_9_2","1CH","9","2","2","והיושבים הראשנים אשר באחזתם בעריהם ישראל הכהנים הלוים והנתינים׃ ");
INSERT INTO heb_vpl VALUES ("R19_3","014_9_3","1CH","9","3","3","ובירושלם ישבו מן בני יהודה ומן בני בנימן ומן בני אפרים ומנשה׃ ");
INSERT INTO heb_vpl VALUES ("R19_4","014_9_4","1CH","9","4","4","עותי בן עמיהוד בן עמרי בן אמרי בן בנימן בני פרץ בן יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R19_5","014_9_5","1CH","9","5","5","ומן השילוני עשיה הבכור ובניו׃ ");
INSERT INTO heb_vpl VALUES ("R19_6","014_9_6","1CH","9","6","6","ומן בני זרח יעואל ואחיהם שש מאות ותשעים׃ ");
INSERT INTO heb_vpl VALUES ("R19_7","014_9_7","1CH","9","7","7","ומן בני בנימן סלוא בן משלם בן הודויה בן הסנאה׃ ");
INSERT INTO heb_vpl VALUES ("R19_8","014_9_8","1CH","9","8","8","ויבניה בן ירחם ואלה בן עזי בן מכרי ומשלם בן שפטיה בן רעואל בן יבניה׃ ");
INSERT INTO heb_vpl VALUES ("R19_9","014_9_9","1CH","9","9","9","ואחיהם לתלדותם תשע מאות וחמשים וששה כל אלה אנשים ראשי אבות לבית אבתיהם׃ ");
INSERT INTO heb_vpl VALUES ("R19_10","014_9_10","1CH","9","10","10","ומן הכהנים ידעיה ויהויריב ויכין׃ ");
INSERT INTO heb_vpl VALUES ("R19_11","014_9_11","1CH","9","11","11","ועזריה בן חלקיה בן משלם בן צדוק בן מריות בן אחיטוב נגיד בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R19_12","014_9_12","1CH","9","12","12","ועדיה בן ירחם בן פשחור בן מלכיה ומעשי בן עדיאל בן יחזרה בן משלם בן משלמית בן אמר׃ ");
INSERT INTO heb_vpl VALUES ("R19_13","014_9_13","1CH","9","13","13","ואחיהם ראשים לבית אבותם אלף ושבע מאות וששים גבורי חיל מלאכת עבודת בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R19_14","014_9_14","1CH","9","14","14","ומן הלוים שמעיה בן חשוב בן עזריקם בן חשביה מן בני מררי׃ ");
INSERT INTO heb_vpl VALUES ("R19_15","014_9_15","1CH","9","15","15","ובקבקר חרש וגלל ומתניה בן מיכא בן זכרי בן אסף׃ ");
INSERT INTO heb_vpl VALUES ("R19_16","014_9_16","1CH","9","16","16","ועבדיה בן שמעיה בן גלל בן ידותון וברכיה בן אסא בן אלקנה היושב בחצרי נטופתי׃ ");
INSERT INTO heb_vpl VALUES ("R19_17","014_9_17","1CH","9","17","17","והשערים שלום ועקוב וטלמן ואחימן ואחיהם שלום הראש׃ ");
INSERT INTO heb_vpl VALUES ("R19_18","014_9_18","1CH","9","18","18","ועד הנה בשער המלך מזרחה המה השערים למחנות בני לוי׃ ");
INSERT INTO heb_vpl VALUES ("R19_19","014_9_19","1CH","9","19","19","ושלום בן קורא בן אביסף בן קרח ואחיו לבית אביו הקרחים על מלאכת העבודה שמרי הספים לאהל ואבתיהם על מחנה יהוה שמרי המבוא׃ ");
INSERT INTO heb_vpl VALUES ("R19_20","014_9_20","1CH","9","20","20","ופינחס בן אלעזר נגיד היה עליהם לפנים יהוה עמו׃ ");
INSERT INTO heb_vpl VALUES ("R19_21","014_9_21","1CH","9","21","21","זכריה בן משלמיה שער פתח לאהל מועד׃ ");
INSERT INTO heb_vpl VALUES ("R19_22","014_9_22","1CH","9","22","22","כלם הברורים לשערים בספים מאתים ושנים עשר המה בחצריהם התיחשם המה יסד דויד ושמואל הראה באמונתם׃ ");
INSERT INTO heb_vpl VALUES ("R19_23","014_9_23","1CH","9","23","23","והם ובניהם על השערים לבית יהוה לבית האהל למשמרות׃ ");
INSERT INTO heb_vpl VALUES ("R19_24","014_9_24","1CH","9","24","24","לארבע רוחות יהיו השערים מזרח ימה צפונה ונגבה׃ ");
INSERT INTO heb_vpl VALUES ("R19_25","014_9_25","1CH","9","25","25","ואחיהם בחצריהם לבוא לשבעת הימים מעת אל עת עם אלה׃ ");
INSERT INTO heb_vpl VALUES ("R19_26","014_9_26","1CH","9","26","26","כי באמונה המה ארבעת גברי השערים הם הלוים והיו על הלשכות ועל האצרות בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R19_27","014_9_27","1CH","9","27","27","וסביבות בית האלהים ילינו כי עליהם משמרת והם על המפתח ולבקר לבקר׃ ");
INSERT INTO heb_vpl VALUES ("R19_28","014_9_28","1CH","9","28","28","ומהם על כלי העבודה כי במספר יביאום ובמספר יוציאום׃ ");
INSERT INTO heb_vpl VALUES ("R19_29","014_9_29","1CH","9","29","29","ומהם ממנים על הכלים ועל כל כלי הקדש ועל הסלת והיין והשמן והלבונה והבשמים׃ ");
INSERT INTO heb_vpl VALUES ("R19_30","014_9_30","1CH","9","30","30","ומן בני הכהנים רקחי המרקחת לבשמים׃ ");
INSERT INTO heb_vpl VALUES ("R19_31","014_9_31","1CH","9","31","31","ומתתיה מן הלוים הוא הבכור לשלם הקרחי באמונה על מעשה החבתים׃ ");
INSERT INTO heb_vpl VALUES ("R19_32","014_9_32","1CH","9","32","32","ומן בני הקהתי מן אחיהם על לחם המערכת להכין שבת שבת׃ ");
INSERT INTO heb_vpl VALUES ("R19_33","014_9_33","1CH","9","33","33","ואלה המשררים ראשי אבות ללוים בלשכת פטירים כי יומם ולילה עליהם במלאכה׃ ");
INSERT INTO heb_vpl VALUES ("R19_34","014_9_34","1CH","9","34","34","אלה ראשי האבות ללוים לתלדותם ראשים אלה ישבו בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R19_35","014_9_35","1CH","9","35","35","ובגבעון ישבו אבי גבעון יעואל ושם אשתו מעכה׃ ");
INSERT INTO heb_vpl VALUES ("R19_36","014_9_36","1CH","9","36","36","ובנו הבכור עבדון וצור וקיש ובעל ונר ונדב׃ ");
INSERT INTO heb_vpl VALUES ("R19_37","014_9_37","1CH","9","37","37","וגדור ואחיו וזכריה ומקלות׃ ");
INSERT INTO heb_vpl VALUES ("R19_38","014_9_38","1CH","9","38","38","ומקלות הוליד את שמאם ואף הם נגד אחיהם ישבו בירושלם עם אחיהם׃ ");
INSERT INTO heb_vpl VALUES ("R19_39","014_9_39","1CH","9","39","39","ונר הוליד את קיש וקיש הוליד את שאול ושאול הוליד את יהונתן ואת מלכי שוע ואת אבינדב ואת אשבעל׃ ");
INSERT INTO heb_vpl VALUES ("R19_40","014_9_40","1CH","9","40","40","ובן יהונתן מריב בעל ומרי בעל הוליד את מיכה׃ ");
INSERT INTO heb_vpl VALUES ("R19_41","014_9_41","1CH","9","41","41","ובני מיכה פיתון ומלך ותחרע׃ ");
INSERT INTO heb_vpl VALUES ("R19_42","014_9_42","1CH","9","42","42","ואחז הוליד את יערה ויערה הוליד את עלמת ואת עזמות ואת זמרי וזמרי הוליד את מוצא׃ ");
INSERT INTO heb_vpl VALUES ("R19_43","014_9_43","1CH","9","43","43","ומוצא הוליד את בנעא ורפיה בנו אלעשה בנו אצל בנו׃ ");
INSERT INTO heb_vpl VALUES ("R19_44","014_9_44","1CH","9","44","44","ולאצל ששה בנים ואלה שמותם עזריקם בכרו וישמעאל ושעריה ועבדיה וחנן אלה בני אצל׃ ");
INSERT INTO heb_vpl VALUES ("R110_1","014_10_1","1CH","10","1","1","ופלשתים נלחמו בישראל וינס איש ישראל מפני פלשתים ויפלו חללים בהר גלבע׃ ");
INSERT INTO heb_vpl VALUES ("R110_2","014_10_2","1CH","10","2","2","וידבקו פלשתים אחרי שאול ואחרי בניו ויכו פלשתים את יונתן ואת אבינדב ואת מלכי שוע בני שאול׃ ");
INSERT INTO heb_vpl VALUES ("R110_3","014_10_3","1CH","10","3","3","ותכבד המלחמה על שאול וימצאהו המורים בקשת ויחל מן היורים׃ ");
INSERT INTO heb_vpl VALUES ("R110_4","014_10_4","1CH","10","4","4","ויאמר שאול אל נשא כליו שלף חרבך ודקרני בה פן יבאו הערלים האלה והתעללו בי ולא אבה נשא כליו כי ירא מאד ויקח שאול את החרב ויפל עליה׃ ");
INSERT INTO heb_vpl VALUES ("R110_5","014_10_5","1CH","10","5","5","וירא נשא כליו כי מת שאול ויפל גם הוא על החרב וימת׃ ");
INSERT INTO heb_vpl VALUES ("R110_6","014_10_6","1CH","10","6","6","וימת שאול ושלשת בניו וכל ביתו יחדו מתו׃ ");
INSERT INTO heb_vpl VALUES ("R110_7","014_10_7","1CH","10","7","7","ויראו כל איש ישראל אשר בעמק כי נסו וכי מתו שאול ובניו ויעזבו עריהם וינסו ויבאו פלשתים וישבו בהם׃ ");
INSERT INTO heb_vpl VALUES ("R110_8","014_10_8","1CH","10","8","8","ויהי ממחרת ויבאו פלשתים לפשט את החללים וימצאו את שאול ואת בניו נפלים בהר גלבע׃ ");
INSERT INTO heb_vpl VALUES ("R110_9","014_10_9","1CH","10","9","9","ויפשיטהו וישאו את ראשו ואת כליו וישלחו בארץ פלשתים סביב לבשר את עצביהם ואת העם׃ ");
INSERT INTO heb_vpl VALUES ("R110_10","014_10_10","1CH","10","10","10","וישימו את כליו בית אלהיהם ואת גלגלתו תקעו בית דגון׃ ");
INSERT INTO heb_vpl VALUES ("R110_11","014_10_11","1CH","10","11","11","וישמעו כל יביש גלעד את כל אשר עשו פלשתים לשאול׃ ");
INSERT INTO heb_vpl VALUES ("R110_12","014_10_12","1CH","10","12","12","ויקומו כל איש חיל וישאו את גופת שאול ואת גופת בניו ויביאום יבישה ויקברו את עצמותיהם תחת האלה ביבש ויצומו שבעת ימים׃ ");
INSERT INTO heb_vpl VALUES ("R110_13","014_10_13","1CH","10","13","13","וימת שאול במעלו אשר מעל ביהוה על דבר יהוה אשר לא שמר וגם לשאול באוב לדרוש׃ ");
INSERT INTO heb_vpl VALUES ("R110_14","014_10_14","1CH","10","14","14","ולא דרש ביהוה וימיתהו ויסב את המלוכה לדויד בן ישי׃ ");
INSERT INTO heb_vpl VALUES ("R111_1","014_11_1","1CH","11","1","1","ויקבצו כל ישראל אל דויד חברונה לאמר הנה עצמך ובשרך אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("R111_2","014_11_2","1CH","11","2","2","גם תמול גם שלשום גם בהיות שאול מלך אתה המוציא והמביא את ישראל ויאמר יהוה אלהיך לך אתה תרעה את עמי את ישראל ואתה תהיה נגיד על עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R111_3","014_11_3","1CH","11","3","3","ויבאו כל זקני ישראל אל המלך חברונה ויכרת להם דויד ברית בחברון לפני יהוה וימשחו את דויד למלך על ישראל כדבר יהוה ביד שמואל׃ ");
INSERT INTO heb_vpl VALUES ("R111_4","014_11_4","1CH","11","4","4","וילך דויד וכל ישראל ירושלם היא יבוס ושם היבוסי ישבי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("R111_5","014_11_5","1CH","11","5","5","ויאמרו ישבי יבוס לדויד לא תבוא הנה וילכד דויד את מצדת ציון היא עיר דויד׃ ");
INSERT INTO heb_vpl VALUES ("R111_6","014_11_6","1CH","11","6","6","ויאמר דויד כל מכה יבוסי בראשונה יהיה לראש ולשר ויעל בראשונה יואב בן צרויה ויהי לראש׃ ");
INSERT INTO heb_vpl VALUES ("R111_7","014_11_7","1CH","11","7","7","וישב דויד במצד על כן קראו לו עיר דויד׃ ");
INSERT INTO heb_vpl VALUES ("R111_8","014_11_8","1CH","11","8","8","ויבן העיר מסביב מן המלוא ועד הסביב ויואב יחיה את שאר העיר׃ ");
INSERT INTO heb_vpl VALUES ("R111_9","014_11_9","1CH","11","9","9","וילך דויד הלוך וגדול ויהוה צבאות עמו׃ ");
INSERT INTO heb_vpl VALUES ("R111_10","014_11_10","1CH","11","10","10","ואלה ראשי הגבורים אשר לדויד המתחזקים עמו במלכותו עם כל ישראל להמליכו כדבר יהוה על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R111_11","014_11_11","1CH","11","11","11","ואלה מספר הגברים אשר לדויד ישבעם בן חכמוני ראש השלושים הוא עורר את חניתו על שלש מאות חלל בפעם אחת׃ ");
INSERT INTO heb_vpl VALUES ("R111_12","014_11_12","1CH","11","12","12","ואחריו אלעזר בן דודו האחוחי הוא בשלושה הגברים׃ ");
INSERT INTO heb_vpl VALUES ("R111_13","014_11_13","1CH","11","13","13","הוא היה עם דויד בפס דמים והפלשתים נאספו שם למלחמה ותהי חלקת השדה מלאה שעורים והעם נסו מפני פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("R111_14","014_11_14","1CH","11","14","14","ויתיצבו בתוך החלקה ויצילוה ויכו את פלשתים ויושע יהוה תשועה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("R111_15","014_11_15","1CH","11","15","15","וירדו שלושה מן השלושים ראש על הצר אל דויד אל מערת עדלם ומחנה פלשתים חנה בעמק רפאים׃ ");
INSERT INTO heb_vpl VALUES ("R111_16","014_11_16","1CH","11","16","16","ודויד אז במצודה ונציב פלשתים אז בבית לחם׃ ");
INSERT INTO heb_vpl VALUES ("R111_17","014_11_17","1CH","11","17","17","ויתאו דויד ויאמר מי ישקני מים מבור בית לחם אשר בשער׃ ");
INSERT INTO heb_vpl VALUES ("R111_18","014_11_18","1CH","11","18","18","ויבקעו השלשה במחנה פלשתים וישאבו מים מבור בית לחם אשר בשער וישאו ויבאו אל דויד ולא אבה דויד לשתותם וינסך אתם ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("R111_19","014_11_19","1CH","11","19","19","ויאמר חלילה לי מאלהי מעשות זאת הדם האנשים האלה אשתה בנפשותם כי בנפשותם הביאום ולא אבה לשתותם אלה עשו שלשת הגבורים׃ ");
INSERT INTO heb_vpl VALUES ("R111_20","014_11_20","1CH","11","20","20","ואבשי אחי יואב הוא היה ראש השלושה והוא עורר את חניתו על שלש מאות חלל ולא שם בשלושה׃ ");
INSERT INTO heb_vpl VALUES ("R111_21","014_11_21","1CH","11","21","21","מן השלושה בשנים נכבד ויהי להם לשר ועד השלושה לא בא׃ ");
INSERT INTO heb_vpl VALUES ("R111_22","014_11_22","1CH","11","22","22","בניה בן יהוידע בן איש חיל רב פעלים מן קבצאל הוא הכה את שני אריאל מואב והוא ירד והכה את הארי בתוך הבור ביום השלג׃ ");
INSERT INTO heb_vpl VALUES ("R111_23","014_11_23","1CH","11","23","23","והוא הכה את האיש המצרי איש מדה חמש באמה וביד המצרי חנית כמנור ארגים וירד אליו בשבט ויגזל את החנית מיד המצרי ויהרגהו בחניתו׃ ");
INSERT INTO heb_vpl VALUES ("R111_24","014_11_24","1CH","11","24","24","אלה עשה בניהו בן יהוידע ולו שם בשלושה הגברים׃ ");
INSERT INTO heb_vpl VALUES ("R111_25","014_11_25","1CH","11","25","25","מן השלושים הנו נכבד הוא ואל השלושה לא בא וישימהו דויד על משמעתו׃ ");
INSERT INTO heb_vpl VALUES ("R111_26","014_11_26","1CH","11","26","26","וגבורי החילים עשה אל אחי יואב אלחנן בן דודו מבית לחם׃ ");
INSERT INTO heb_vpl VALUES ("R111_27","014_11_27","1CH","11","27","27","שמות ההרורי חלץ הפלוני׃ ");
INSERT INTO heb_vpl VALUES ("R111_28","014_11_28","1CH","11","28","28","עירא בן עקש התקועי אביעזר הענתותי׃ ");
INSERT INTO heb_vpl VALUES ("R111_29","014_11_29","1CH","11","29","29","סבכי החשתי עילי האחוחי׃ ");
INSERT INTO heb_vpl VALUES ("R111_30","014_11_30","1CH","11","30","30","מהרי הנטפתי חלד בן בענה הנטופתי׃ ");
INSERT INTO heb_vpl VALUES ("R111_31","014_11_31","1CH","11","31","31","איתי בן ריבי מגבעת בני בנימן בניה הפרעתני׃ ");
INSERT INTO heb_vpl VALUES ("R111_32","014_11_32","1CH","11","32","32","חורי מנחלי געש אביאל הערבתי׃ ");
INSERT INTO heb_vpl VALUES ("R111_33","014_11_33","1CH","11","33","33","עזמות הבחרומי אליחבא השעלבני׃ ");
INSERT INTO heb_vpl VALUES ("R111_34","014_11_34","1CH","11","34","34","בני השם הגזוני יונתן בן שגה ההררי׃ ");
INSERT INTO heb_vpl VALUES ("R111_35","014_11_35","1CH","11","35","35","אחיאם בן שכר ההררי אליפל בן אור׃ ");
INSERT INTO heb_vpl VALUES ("R111_36","014_11_36","1CH","11","36","36","חפר המכרתי אחיה הפלני׃ ");
INSERT INTO heb_vpl VALUES ("R111_37","014_11_37","1CH","11","37","37","חצרו הכרמלי נערי בן אזבי׃ ");
INSERT INTO heb_vpl VALUES ("R111_38","014_11_38","1CH","11","38","38","יואל אחי נתן מבחר בן הגרי׃ ");
INSERT INTO heb_vpl VALUES ("R111_39","014_11_39","1CH","11","39","39","צלק העמוני נחרי הברתי נשא כלי יואב בן צרויה׃ ");
INSERT INTO heb_vpl VALUES ("R111_40","014_11_40","1CH","11","40","40","עירא היתרי גרב היתרי׃ ");
INSERT INTO heb_vpl VALUES ("R111_41","014_11_41","1CH","11","41","41","אוריה החתי זבד בן אחלי׃ ");
INSERT INTO heb_vpl VALUES ("R111_42","014_11_42","1CH","11","42","42","עדינא בן שיזא הראובני ראש לראובני ועליו שלושים׃ ");
INSERT INTO heb_vpl VALUES ("R111_43","014_11_43","1CH","11","43","43","חנן בן מעכה ויושפט המתני׃ ");
INSERT INTO heb_vpl VALUES ("R111_44","014_11_44","1CH","11","44","44","עזיא העשתרתי שמע ויעואל בני חותם הערערי׃ ");
INSERT INTO heb_vpl VALUES ("R111_45","014_11_45","1CH","11","45","45","ידיעאל בן שמרי ויחא אחיו התיצי׃ ");
INSERT INTO heb_vpl VALUES ("R111_46","014_11_46","1CH","11","46","46","אליאל המחוים ויריבי ויושויה בני אלנעם ויתמה המואבי׃ ");
INSERT INTO heb_vpl VALUES ("R111_47","014_11_47","1CH","11","47","47","אליאל ועובד ויעשיאל המצביה׃ ");
INSERT INTO heb_vpl VALUES ("R112_1","014_12_1","1CH","12","1","1","ואלה הבאים אל דויד לציקלג עוד עצור מפני שאול בן קיש והמה בגבורים עזרי המלחמה׃ ");
INSERT INTO heb_vpl VALUES ("R112_2","014_12_2","1CH","12","2","2","נשקי קשת מימינים ומשמאלים באבנים ובחצים בקשת מאחי שאול מבנימן׃ ");
INSERT INTO heb_vpl VALUES ("R112_3","014_12_3","1CH","12","3","3","הראש אחיעזר ויואש בני השמעה הגבעתי ויזואל ופלט בני עזמות וברכה ויהוא הענתתי׃ ");
INSERT INTO heb_vpl VALUES ("R112_4","014_12_4","1CH","12","4","4","וישמעיה הגבעוני גבור בשלשים ועל השלשים וירמיה ויחזיאל ויוחנן ויוזבד הגדרתי׃ ");
INSERT INTO heb_vpl VALUES ("R112_5","014_12_5","1CH","12","5","5","אלעוזי וירימות ובעליה ושמריהו ושפטיהו החריפי׃ ");
INSERT INTO heb_vpl VALUES ("R112_6","014_12_6","1CH","12","6","6","אלקנה וישיהו ועזראל ויועזר וישבעם הקרחים׃ ");
INSERT INTO heb_vpl VALUES ("R112_7","014_12_7","1CH","12","7","7","ויועאלה וזבדיה בני ירחם מן הגדור׃ ");
INSERT INTO heb_vpl VALUES ("R112_8","014_12_8","1CH","12","8","8","ומן הגדי נבדלו אל דויד למצד מדברה גברי החיל אנשי צבא למלחמה ערכי צנה ורמח ופני אריה פניהם וכצבאים על ההרים למהר׃ ");
INSERT INTO heb_vpl VALUES ("R112_9","014_12_9","1CH","12","9","9","עזר הראש עבדיה השני אליאב השלשי׃ ");
INSERT INTO heb_vpl VALUES ("R112_10","014_12_10","1CH","12","10","10","משמנה הרביעי ירמיה החמשי׃ ");
INSERT INTO heb_vpl VALUES ("R112_11","014_12_11","1CH","12","11","11","עתי הששי אליאל השבעי׃ ");
INSERT INTO heb_vpl VALUES ("R112_12","014_12_12","1CH","12","12","12","יוחנן השמיני אלזבד התשיעי׃ ");
INSERT INTO heb_vpl VALUES ("R112_13","014_12_13","1CH","12","13","13","ירמיהו העשירי מכבני עשתי עשר׃ ");
INSERT INTO heb_vpl VALUES ("R112_14","014_12_14","1CH","12","14","14","אלה מבני גד ראשי הצבא אחד למאה הקטן והגדול לאלף׃ ");
INSERT INTO heb_vpl VALUES ("R112_15","014_12_15","1CH","12","15","15","אלה הם אשר עברו את הירדן בחדש הראשון והוא ממלא על כל גדיתיו ויבריחו את כל העמקים למזרח ולמערב׃ ");
INSERT INTO heb_vpl VALUES ("R112_16","014_12_16","1CH","12","16","16","ויבאו מן בני בנימן ויהודה עד למצד לדויד׃ ");
INSERT INTO heb_vpl VALUES ("R112_17","014_12_17","1CH","12","17","17","ויצא דויד לפניהם ויען ויאמר להם אם לשלום באתם אלי לעזרני יהיה לי עליכם לבב ליחד ואם לרמותני לצרי בלא חמס בכפי ירא אלהי אבותינו ויוכח׃ ");
INSERT INTO heb_vpl VALUES ("R112_18","014_12_18","1CH","12","18","18","ורוח לבשה את עמשי ראש השלושים לך דויד ועמך בן ישי שלום שלום לך ושלום לעזרך כי עזרך אלהיך ויקבלם דויד ויתנם בראשי הגדוד׃ ");
INSERT INTO heb_vpl VALUES ("R112_19","014_12_19","1CH","12","19","19","וממנשה נפלו על דויד בבאו עם פלשתים על שאול למלחמה ולא עזרם כי בעצה שלחהו סרני פלשתים לאמר בראשינו יפול אל אדניו שאול׃ ");
INSERT INTO heb_vpl VALUES ("R112_20","014_12_20","1CH","12","20","20","בלכתו אל ציקלג נפלו עליו ממנשה עדנח ויוזבד וידיעאל ומיכאל ויוזבד ואליהוא וצלתי ראשי האלפים אשר למנשה׃ ");
INSERT INTO heb_vpl VALUES ("R112_21","014_12_21","1CH","12","21","21","והמה עזרו עם דויד על הגדוד כי גבורי חיל כלם ויהיו שרים בצבא׃ ");
INSERT INTO heb_vpl VALUES ("R112_22","014_12_22","1CH","12","22","22","כי לעת יום ביום יבאו על דויד לעזרו עד למחנה גדול כמחנה אלהים׃ ");
INSERT INTO heb_vpl VALUES ("R112_23","014_12_23","1CH","12","23","23","ואלה מספרי ראשי החלוץ לצבא באו על דויד חברונה להסב מלכות שאול אליו כפי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R112_24","014_12_24","1CH","12","24","24","בני יהודה נשאי צנה ורמח ששת אלפים ושמונה מאות חלוצי צבא׃ ");
INSERT INTO heb_vpl VALUES ("R112_25","014_12_25","1CH","12","25","25","מן בני שמעון גבורי חיל לצבא שבעת אלפים ומאה׃ ");
INSERT INTO heb_vpl VALUES ("R112_26","014_12_26","1CH","12","26","26","מן בני הלוי ארבעת אלפים ושש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R112_27","014_12_27","1CH","12","27","27","ויהוידע הנגיד לאהרן ועמו שלשת אלפים ושבע מאות׃ ");
INSERT INTO heb_vpl VALUES ("R112_28","014_12_28","1CH","12","28","28","וצדוק נער גבור חיל ובית אביו שרים עשרים ושנים׃ ");
INSERT INTO heb_vpl VALUES ("R112_29","014_12_29","1CH","12","29","29","ומן בני בנימן אחי שאול שלשת אלפים ועד הנה מרביתם שמרים משמרת בית שאול׃ ");
INSERT INTO heb_vpl VALUES ("R112_30","014_12_30","1CH","12","30","30","ומן בני אפרים עשרים אלף ושמונה מאות גבורי חיל אנשי שמות לבית אבותם׃ ");
INSERT INTO heb_vpl VALUES ("R112_31","014_12_31","1CH","12","31","31","ומחצי מטה מנשה שמונה עשר אלף אשר נקבו בשמות לבוא להמליך את דויד׃ ");
INSERT INTO heb_vpl VALUES ("R112_32","014_12_32","1CH","12","32","32","ומבני יששכר יודעי בינה לעתים לדעת מה יעשה ישראל ראשיהם מאתים וכל אחיהם על פיהם׃ ");
INSERT INTO heb_vpl VALUES ("R112_33","014_12_33","1CH","12","33","33","מזבלון יוצאי צבא ערכי מלחמה בכל כלי מלחמה חמשים אלף ולעדר בלא לב ולב׃ ");
INSERT INTO heb_vpl VALUES ("R112_34","014_12_34","1CH","12","34","34","ומנפתלי שרים אלף ועמהם בצנה וחנית שלשים ושבעה אלף׃ ");
INSERT INTO heb_vpl VALUES ("R112_35","014_12_35","1CH","12","35","35","ומן הדני ערכי מלחמה עשרים ושמונה אלף ושש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R112_36","014_12_36","1CH","12","36","36","ומאשר יוצאי צבא לערך מלחמה ארבעים אלף׃ ");
INSERT INTO heb_vpl VALUES ("R112_37","014_12_37","1CH","12","37","37","ומעבר לירדן מן הראובני והגדי וחצי שבט מנשה בכל כלי צבא מלחמה מאה ועשרים אלף׃ ");
INSERT INTO heb_vpl VALUES ("R112_38","014_12_38","1CH","12","38","38","כל אלה אנשי מלחמה עדרי מערכה בלבב שלם באו חברונה להמליך את דויד על כל ישראל וגם כל שרית ישראל לב אחד להמליך את דויד׃ ");
INSERT INTO heb_vpl VALUES ("R112_39","014_12_39","1CH","12","39","39","ויהיו שם עם דויד ימים שלושה אכלים ושותים כי הכינו להם אחיהם׃ ");
INSERT INTO heb_vpl VALUES ("R112_40","014_12_40","1CH","12","40","40","וגם הקרובים אליהם עד יששכר וזבלון ונפתלי מביאים לחם בחמורים ובגמלים ובפרדים ובבקר מאכל קמח דבלים וצמוקים ויין ושמן ובקר וצאן לרב כי שמחה בישראל׃ ");
INSERT INTO heb_vpl VALUES ("R113_1","014_13_1","1CH","13","1","1","ויועץ דויד עם שרי האלפים והמאות לכל נגיד׃ ");
INSERT INTO heb_vpl VALUES ("R113_2","014_13_2","1CH","13","2","2","ויאמר דויד לכל קהל ישראל אם עליכם טוב ומן יהוה אלהינו נפרצה נשלחה על אחינו הנשארים בכל ארצות ישראל ועמהם הכהנים והלוים בערי מגרשיהם ויקבצו אלינו׃ ");
INSERT INTO heb_vpl VALUES ("R113_3","014_13_3","1CH","13","3","3","ונסבה את ארון אלהינו אלינו כי לא דרשנהו בימי שאול׃ ");
INSERT INTO heb_vpl VALUES ("R113_4","014_13_4","1CH","13","4","4","ויאמרו כל הקהל לעשות כן כי ישר הדבר בעיני כל העם׃ ");
INSERT INTO heb_vpl VALUES ("R113_5","014_13_5","1CH","13","5","5","ויקהל דויד את כל ישראל מן שיחור מצרים ועד לבוא חמת להביא את ארון האלהים מקרית יערים׃ ");
INSERT INTO heb_vpl VALUES ("R113_6","014_13_6","1CH","13","6","6","ויעל דויד וכל ישראל בעלתה אל קרית יערים אשר ליהודה להעלות משם את ארון האלהים יהוה יושב הכרובים אשר נקרא שם׃ ");
INSERT INTO heb_vpl VALUES ("R113_7","014_13_7","1CH","13","7","7","וירכיבו את ארון האלהים על עגלה חדשה מבית אבינדב ועזא ואחיו נהגים בעגלה׃ ");
INSERT INTO heb_vpl VALUES ("R113_8","014_13_8","1CH","13","8","8","ודויד וכל ישראל משחקים לפני האלהים בכל עז ובשירים ובכנרות ובנבלים ובתפים ובמצלתים ובחצצרות׃ ");
INSERT INTO heb_vpl VALUES ("R113_9","014_13_9","1CH","13","9","9","ויבאו עד גרן כידן וישלח עזא את ידו לאחז את הארון כי שמטו הבקר׃ ");
INSERT INTO heb_vpl VALUES ("R113_10","014_13_10","1CH","13","10","10","ויחר אף יהוה בעזא ויכהו על אשר שלח ידו על הארון וימת שם לפני אלהים׃ ");
INSERT INTO heb_vpl VALUES ("R113_11","014_13_11","1CH","13","11","11","ויחר לדויד כי פרץ יהוה פרץ בעזא ויקרא למקום ההוא פרץ עזא עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R113_12","014_13_12","1CH","13","12","12","ויירא דויד את האלהים ביום ההוא לאמר היך אביא אלי את ארון האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R113_13","014_13_13","1CH","13","13","13","ולא הסיר דויד את הארון אליו אל עיר דויד ויטהו אל בית עבד אדם הגתי׃ ");
INSERT INTO heb_vpl VALUES ("R113_14","014_13_14","1CH","13","14","14","וישב ארון האלהים עם בית עבד אדם בביתו שלשה חדשים ויברך יהוה את בית עבד אדם ואת כל אשר לו׃ ");
INSERT INTO heb_vpl VALUES ("R114_1","014_14_1","1CH","14","1","1","וישלח חירם מלך צר מלאכים אל דויד ועצי ארזים וחרשי קיר וחרשי עצים לבנות לו בית׃ ");
INSERT INTO heb_vpl VALUES ("R114_2","014_14_2","1CH","14","2","2","וידע דויד כי הכינו יהוה למלך על ישראל כי נשאת למעלה מלכותו בעבור עמו ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R114_3","014_14_3","1CH","14","3","3","ויקח דויד עוד נשים בירושלם ויולד דויד עוד בנים ובנות׃ ");
INSERT INTO heb_vpl VALUES ("R114_4","014_14_4","1CH","14","4","4","ואלה שמות הילודים אשר היו לו בירושלם שמוע ושובב נתן ושלמה׃ ");
INSERT INTO heb_vpl VALUES ("R114_5","014_14_5","1CH","14","5","5","ויבחר ואלישוע ואלפלט׃ ");
INSERT INTO heb_vpl VALUES ("R114_6","014_14_6","1CH","14","6","6","ונגה ונפג ויפיע׃ ");
INSERT INTO heb_vpl VALUES ("R114_7","014_14_7","1CH","14","7","7","ואלישמע ובעלידע ואליפלט׃ ");
INSERT INTO heb_vpl VALUES ("R114_8","014_14_8","1CH","14","8","8","וישמעו פלשתים כי נמשח דויד למלך על כל ישראל ויעלו כל פלשתים לבקש את דויד וישמע דויד ויצא לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("R114_9","014_14_9","1CH","14","9","9","ופלשתים באו ויפשטו בעמק רפאים׃ ");
INSERT INTO heb_vpl VALUES ("R114_10","014_14_10","1CH","14","10","10","וישאל דויד באלהים לאמר האעלה על פלשתיים ונתתם בידי ויאמר לו יהוה עלה ונתתים בידך׃ ");
INSERT INTO heb_vpl VALUES ("R114_11","014_14_11","1CH","14","11","11","ויעלו בבעל פרצים ויכם שם דויד ויאמר דויד פרץ האלהים את אויבי בידי כפרץ מים על כן קראו שם המקום ההוא בעל פרצים׃ ");
INSERT INTO heb_vpl VALUES ("R114_12","014_14_12","1CH","14","12","12","ויעזבו שם את אלהיהם ויאמר דויד וישרפו באש׃ ");
INSERT INTO heb_vpl VALUES ("R114_13","014_14_13","1CH","14","13","13","ויסיפו עוד פלשתים ויפשטו בעמק׃ ");
INSERT INTO heb_vpl VALUES ("R114_14","014_14_14","1CH","14","14","14","וישאל עוד דויד באלהים ויאמר לו האלהים לא תעלה אחריהם הסב מעליהם ובאת להם ממול הבכאים׃ ");
INSERT INTO heb_vpl VALUES ("R114_15","014_14_15","1CH","14","15","15","ויהי כשמעך את קול הצעדה בראשי הבכאים אז תצא במלחמה כי יצא האלהים לפניך להכות את מחנה פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("R114_16","014_14_16","1CH","14","16","16","ויעש דויד כאשר צוהו האלהים ויכו את מחנה פלשתים מגבעון ועד גזרה׃ ");
INSERT INTO heb_vpl VALUES ("R114_17","014_14_17","1CH","14","17","17","ויצא שם דויד בכל הארצות ויהוה נתן את פחדו על כל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("R115_1","014_15_1","1CH","15","1","1","ויעש לו בתים בעיר דויד ויכן מקום לארון האלהים ויט לו אהל׃ ");
INSERT INTO heb_vpl VALUES ("R115_2","014_15_2","1CH","15","2","2","אז אמר דויד לא לשאת את ארון האלהים כי אם הלוים כי בם בחר יהוה לשאת את ארון יהוה ולשרתו עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("R115_3","014_15_3","1CH","15","3","3","ויקהל דויד את כל ישראל אל ירושלם להעלות את ארון יהוה אל מקומו אשר הכין לו׃ ");
INSERT INTO heb_vpl VALUES ("R115_4","014_15_4","1CH","15","4","4","ויאסף דויד את בני אהרן ואת הלוים׃ ");
INSERT INTO heb_vpl VALUES ("R115_5","014_15_5","1CH","15","5","5","לבני קהת אוריאל השר ואחיו מאה ועשרים׃ ");
INSERT INTO heb_vpl VALUES ("R115_6","014_15_6","1CH","15","6","6","לבני מררי עשיה השר ואחיו מאתים ועשרים׃ ");
INSERT INTO heb_vpl VALUES ("R115_7","014_15_7","1CH","15","7","7","לבני גרשום יואל השר ואחיו מאה ושלשים׃ ");
INSERT INTO heb_vpl VALUES ("R115_8","014_15_8","1CH","15","8","8","לבני אליצפן שמעיה השר ואחיו מאתים׃ ");
INSERT INTO heb_vpl VALUES ("R115_9","014_15_9","1CH","15","9","9","לבני חברון אליאל השר ואחיו שמונים׃ ");
INSERT INTO heb_vpl VALUES ("R115_10","014_15_10","1CH","15","10","10","לבני עזיאל עמינדב השר ואחיו מאה ושנים עשר׃ ");
INSERT INTO heb_vpl VALUES ("R115_11","014_15_11","1CH","15","11","11","ויקרא דויד לצדוק ולאביתר הכהנים וללוים לאוריאל עשיה ויואל שמעיה ואליאל ועמינדב׃ ");
INSERT INTO heb_vpl VALUES ("R115_12","014_15_12","1CH","15","12","12","ויאמר להם אתם ראשי האבות ללוים התקדשו אתם ואחיכם והעליתם את ארון יהוה אלהי ישראל אל הכינותי לו׃ ");
INSERT INTO heb_vpl VALUES ("R115_13","014_15_13","1CH","15","13","13","כי למבראשונה לא אתם פרץ יהוה אלהינו בנו כי לא דרשנהו כמשפט׃ ");
INSERT INTO heb_vpl VALUES ("R115_14","014_15_14","1CH","15","14","14","ויתקדשו הכהנים והלוים להעלות את ארון יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R115_15","014_15_15","1CH","15","15","15","וישאו בני הלוים את ארון האלהים כאשר צוה משה כדבר יהוה בכתפם במטות עליהם׃ ");
INSERT INTO heb_vpl VALUES ("R115_16","014_15_16","1CH","15","16","16","ויאמר דויד לשרי הלוים להעמיד את אחיהם המשררים בכלי שיר נבלים וכנרות ומצלתים משמיעים להרים בקול לשמחה׃ ");
INSERT INTO heb_vpl VALUES ("R115_17","014_15_17","1CH","15","17","17","ויעמידו הלוים את הימן בן יואל ומן אחיו אסף בן ברכיהו ומן בני מררי אחיהם איתן בן קושיהו׃ ");
INSERT INTO heb_vpl VALUES ("R115_18","014_15_18","1CH","15","18","18","ועמהם אחיהם המשנים זכריהו בן ויעזיאל ושמירמות ויחיאל ועני אליאב ובניהו ומעשיהו ומתתיהו ואליפלהו ומקניהו ועבד אדם ויעיאל השערים׃ ");
INSERT INTO heb_vpl VALUES ("R115_19","014_15_19","1CH","15","19","19","והמשררים הימן אסף ואיתן במצלתים נחשת להשמיע׃ ");
INSERT INTO heb_vpl VALUES ("R115_20","014_15_20","1CH","15","20","20","וזכריה ועזיאל ושמירמות ויחיאל ועני ואליאב ומעשיהו ובניהו בנבלים על עלמות׃ ");
INSERT INTO heb_vpl VALUES ("R115_21","014_15_21","1CH","15","21","21","ומתתיהו ואליפלהו ומקניהו ועבד אדם ויעיאל ועזזיהו בכנרות על השמינית לנצח׃ ");
INSERT INTO heb_vpl VALUES ("R115_22","014_15_22","1CH","15","22","22","וכנניהו שר הלוים במשא יסר במשא כי מבין הוא׃ ");
INSERT INTO heb_vpl VALUES ("R115_23","014_15_23","1CH","15","23","23","וברכיה ואלקנה שערים לארון׃ ");
INSERT INTO heb_vpl VALUES ("R115_24","014_15_24","1CH","15","24","24","ושבניהו ויושפט ונתנאל ועמשי וזכריהו ובניהו ואליעזר הכהנים מחצצרים בחצצרות לפני ארון האלהים ועבד אדם ויחיה שערים לארון׃ ");
INSERT INTO heb_vpl VALUES ("R115_25","014_15_25","1CH","15","25","25","ויהי דויד וזקני ישראל ושרי האלפים ההלכים להעלות את ארון ברית יהוה מן בית עבד אדם בשמחה׃ ");
INSERT INTO heb_vpl VALUES ("R115_26","014_15_26","1CH","15","26","26","ויהי בעזר האלהים את הלוים נשאי ארון ברית יהוה ויזבחו שבעה פרים ושבעה אילים׃ ");
INSERT INTO heb_vpl VALUES ("R115_27","014_15_27","1CH","15","27","27","ודויד מכרבל במעיל בוץ וכל הלוים הנשאים את הארון והמשררים וכנניה השר המשא המשררים ועל דויד אפוד בד׃ ");
INSERT INTO heb_vpl VALUES ("R115_28","014_15_28","1CH","15","28","28","וכל ישראל מעלים את ארון ברית יהוה בתרועה ובקול שופר ובחצצרות ובמצלתים משמעים בנבלים וכנרות׃ ");
INSERT INTO heb_vpl VALUES ("R115_29","014_15_29","1CH","15","29","29","ויהי ארון ברית יהוה בא עד עיר דויד ומיכל בת שאול נשקפה בעד החלון ותרא את המלך דויד מרקד ומשחק ותבז לו בלבה׃ ");
INSERT INTO heb_vpl VALUES ("R116_1","014_16_1","1CH","16","1","1","ויביאו את ארון האלהים ויציגו אתו בתוך האהל אשר נטה לו דויד ויקריבו עלות ושלמים לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R116_2","014_16_2","1CH","16","2","2","ויכל דויד מהעלות העלה והשלמים ויברך את העם בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R116_3","014_16_3","1CH","16","3","3","ויחלק לכל איש ישראל מאיש ועד אשה לאיש ככר לחם ואשפר ואשישה׃ ");
INSERT INTO heb_vpl VALUES ("R116_4","014_16_4","1CH","16","4","4","ויתן לפני ארון יהוה מן הלוים משרתים ולהזכיר ולהודות ולהלל ליהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R116_5","014_16_5","1CH","16","5","5","אסף הראש ומשנהו זכריה יעיאל ושמירמות ויחיאל ומתתיה ואליאב ובניהו ועבד אדם ויעיאל בכלי נבלים ובכנרות ואסף במצלתים משמיע׃ ");
INSERT INTO heb_vpl VALUES ("R116_6","014_16_6","1CH","16","6","6","ובניהו ויחזיאל הכהנים בחצצרות תמיד לפני ארון ברית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R116_7","014_16_7","1CH","16","7","7","ביום ההוא אז נתן דויד בראש להדות ליהוה ביד אסף ואחיו׃ ");
INSERT INTO heb_vpl VALUES ("R116_8","014_16_8","1CH","16","8","8","הודו ליהוה קראו בשמו הודיעו בעמים עלילתיו׃ ");
INSERT INTO heb_vpl VALUES ("R116_9","014_16_9","1CH","16","9","9","שירו לו זמרו לו שיחו בכל נפלאתיו׃ ");
INSERT INTO heb_vpl VALUES ("R116_10","014_16_10","1CH","16","10","10","התהללו בשם קדשו ישמח לב מבקשי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R116_11","014_16_11","1CH","16","11","11","דרשו יהוה ועזו בקשו פניו תמיד׃ ");
INSERT INTO heb_vpl VALUES ("R116_12","014_16_12","1CH","16","12","12","זכרו נפלאתיו אשר עשה מפתיו ומשפטי פיהו׃ ");
INSERT INTO heb_vpl VALUES ("R116_13","014_16_13","1CH","16","13","13","זרע ישראל עבדו בני יעקב בחיריו׃ ");
INSERT INTO heb_vpl VALUES ("R116_14","014_16_14","1CH","16","14","14","הוא יהוה אלהינו בכל הארץ משפטיו׃ ");
INSERT INTO heb_vpl VALUES ("R116_15","014_16_15","1CH","16","15","15","זכרו לעולם בריתו דבר צוה לאלף דור׃ ");
INSERT INTO heb_vpl VALUES ("R116_16","014_16_16","1CH","16","16","16","אשר כרת את אברהם ושבועתו ליצחק׃ ");
INSERT INTO heb_vpl VALUES ("R116_17","014_16_17","1CH","16","17","17","ויעמידה ליעקב לחק לישראל ברית עולם׃ ");
INSERT INTO heb_vpl VALUES ("R116_18","014_16_18","1CH","16","18","18","לאמר לך אתן ארץ כנען חבל נחלתכם׃ ");
INSERT INTO heb_vpl VALUES ("R116_19","014_16_19","1CH","16","19","19","בהיותכם מתי מספר כמעט וגרים בה׃ ");
INSERT INTO heb_vpl VALUES ("R116_20","014_16_20","1CH","16","20","20","ויתהלכו מגוי אל גוי ומממלכה אל עם אחר׃ ");
INSERT INTO heb_vpl VALUES ("R116_21","014_16_21","1CH","16","21","21","לא הניח לאיש לעשקם ויוכח עליהם מלכים׃ ");
INSERT INTO heb_vpl VALUES ("R116_22","014_16_22","1CH","16","22","22","אל תגעו במשיחי ובנביאי אל תרעו׃ ");
INSERT INTO heb_vpl VALUES ("R116_23","014_16_23","1CH","16","23","23","שירו ליהוה כל הארץ בשרו מיום אל יום ישועתו׃ ");
INSERT INTO heb_vpl VALUES ("R116_24","014_16_24","1CH","16","24","24","ספרו בגוים את כבודו בכל העמים נפלאתיו׃ ");
INSERT INTO heb_vpl VALUES ("R116_25","014_16_25","1CH","16","25","25","כי גדול יהוה ומהלל מאד ונורא הוא על כל אלהים׃ ");
INSERT INTO heb_vpl VALUES ("R116_26","014_16_26","1CH","16","26","26","כי כל אלהי העמים אלילים ויהוה שמים עשה׃ ");
INSERT INTO heb_vpl VALUES ("R116_27","014_16_27","1CH","16","27","27","הוד והדר לפניו עז וחדוה במקמו׃ ");
INSERT INTO heb_vpl VALUES ("R116_28","014_16_28","1CH","16","28","28","הבו ליהוה משפחות עמים הבו ליהוה כבוד ועז׃ ");
INSERT INTO heb_vpl VALUES ("R116_29","014_16_29","1CH","16","29","29","הבו ליהוה כבוד שמו שאו מנחה ובאו לפניו השתחוו ליהוה בהדרת קדש׃ ");
INSERT INTO heb_vpl VALUES ("R116_30","014_16_30","1CH","16","30","30","חילו מלפניו כל הארץ אף תכון תבל בל תמוט׃ ");
INSERT INTO heb_vpl VALUES ("R116_31","014_16_31","1CH","16","31","31","ישמחו השמים ותגל הארץ ויאמרו בגוים יהוה מלך׃ ");
INSERT INTO heb_vpl VALUES ("R116_32","014_16_32","1CH","16","32","32","ירעם הים ומלואו יעלץ השדה וכל אשר בו׃ ");
INSERT INTO heb_vpl VALUES ("R116_33","014_16_33","1CH","16","33","33","אז ירננו עצי היער מלפני יהוה כי בא לשפוט את הארץ׃ ");
INSERT INTO heb_vpl VALUES ("R116_34","014_16_34","1CH","16","34","34","הודו ליהוה כי טוב כי לעולם חסדו׃ ");
INSERT INTO heb_vpl VALUES ("R116_35","014_16_35","1CH","16","35","35","ואמרו הושיענו אלהי ישענו וקבצנו והצילנו מן הגוים להדות לשם קדשך להשתבח בתהלתך׃ ");
INSERT INTO heb_vpl VALUES ("R116_36","014_16_36","1CH","16","36","36","ברוך יהוה אלהי ישראל מן העולם ועד העלם ויאמרו כל העם אמן והלל ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("R116_37","014_16_37","1CH","16","37","37","ויעזב שם לפני ארון ברית יהוה לאסף ולאחיו לשרת לפני הארון תמיד לדבר יום ביומו׃ ");
INSERT INTO heb_vpl VALUES ("R116_38","014_16_38","1CH","16","38","38","ועבד אדם ואחיהם ששים ושמונה ועבד אדם בן ידיתון וחסה לשערים׃ ");
INSERT INTO heb_vpl VALUES ("R116_39","014_16_39","1CH","16","39","39","ואת צדוק הכהן ואחיו הכהנים לפני משכן יהוה בבמה אשר בגבעון׃ ");
INSERT INTO heb_vpl VALUES ("R116_40","014_16_40","1CH","16","40","40","להעלות עלות ליהוה על מזבח העלה תמיד לבקר ולערב ולכל הכתוב בתורת יהוה אשר צוה על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R116_41","014_16_41","1CH","16","41","41","ועמהם הימן וידותון ושאר הברורים אשר נקבו בשמות להדות ליהוה כי לעולם חסדו׃ ");
INSERT INTO heb_vpl VALUES ("R116_42","014_16_42","1CH","16","42","42","ועמהם הימן וידותון חצצרות ומצלתים למשמיעים וכלי שיר האלהים ובני ידותון לשער׃ ");
INSERT INTO heb_vpl VALUES ("R116_43","014_16_43","1CH","16","43","43","וילכו כל העם איש לביתו ויסב דויד לברך את ביתו׃ ");
INSERT INTO heb_vpl VALUES ("R117_1","014_17_1","1CH","17","1","1","ויהי כאשר ישב דויד בביתו ויאמר דויד אל נתן הנביא הנה אנכי יושב בבית הארזים וארון ברית יהוה תחת יריעות׃ ");
INSERT INTO heb_vpl VALUES ("R117_2","014_17_2","1CH","17","2","2","ויאמר נתן אל דויד כל אשר בלבבך עשה כי האלהים עמך׃ ");
INSERT INTO heb_vpl VALUES ("R117_3","014_17_3","1CH","17","3","3","ויהי בלילה ההוא ויהי דבר אלהים אל נתן לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R117_4","014_17_4","1CH","17","4","4","לך ואמרת אל דויד עבדי כה אמר יהוה לא אתה תבנה לי הבית לשבת׃ ");
INSERT INTO heb_vpl VALUES ("R117_5","014_17_5","1CH","17","5","5","כי לא ישבתי בבית מן היום אשר העליתי את ישראל עד היום הזה ואהיה מאהל אל אהל וממשכן׃ ");
INSERT INTO heb_vpl VALUES ("R117_6","014_17_6","1CH","17","6","6","בכל אשר התהלכתי בכל ישראל הדבר דברתי את אחד שפטי ישראל אשר צויתי לרעות את עמי לאמר למה לא בניתם לי בית ארזים׃ ");
INSERT INTO heb_vpl VALUES ("R117_7","014_17_7","1CH","17","7","7","ועתה כה תאמר לעבדי לדויד כה אמר יהוה צבאות אני לקחתיך מן הנוה מן אחרי הצאן להיות נגיד על עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R117_8","014_17_8","1CH","17","8","8","ואהיה עמך בכל אשר הלכת ואכרית את כל אויביך מפניך ועשיתי לך שם כשם הגדולים אשר בארץ׃ ");
INSERT INTO heb_vpl VALUES ("R117_9","014_17_9","1CH","17","9","9","ושמתי מקום לעמי ישראל ונטעתיהו ושכן תחתיו ולא ירגז עוד ולא יוסיפו בני עולה לבלתו כאשר בראשונה׃ ");
INSERT INTO heb_vpl VALUES ("R117_10","014_17_10","1CH","17","10","10","ולמימים אשר צויתי שפטים על עמי ישראל והכנעתי את כל אויביך ואגד לך ובית יבנה לך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R117_11","014_17_11","1CH","17","11","11","והיה כי מלאו ימיך ללכת עם אבתיך והקימותי את זרעך אחריך אשר יהיה מבניך והכינותי את מלכותו׃ ");
INSERT INTO heb_vpl VALUES ("R117_12","014_17_12","1CH","17","12","12","הוא יבנה לי בית וכננתי את כסאו עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("R117_13","014_17_13","1CH","17","13","13","אני אהיה לו לאב והוא יהיה לי לבן וחסדי לא אסיר מעמו כאשר הסירותי מאשר היה לפניך׃ ");
INSERT INTO heb_vpl VALUES ("R117_14","014_17_14","1CH","17","14","14","והעמדתיהו בביתי ובמלכותי עד העולם וכסאו יהיה נכון עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("R117_15","014_17_15","1CH","17","15","15","ככל הדברים האלה וככל החזון הזה כן דבר נתן אל דויד׃ ");
INSERT INTO heb_vpl VALUES ("R117_16","014_17_16","1CH","17","16","16","ויבא המלך דויד וישב לפני יהוה ויאמר מי אני יהוה אלהים ומי ביתי כי הביאתני עד הלם׃ ");
INSERT INTO heb_vpl VALUES ("R117_17","014_17_17","1CH","17","17","17","ותקטן זאת בעיניך אלהים ותדבר על בית עבדך למרחוק וראיתני כתור האדם המעלה יהוה אלהים׃ ");
INSERT INTO heb_vpl VALUES ("R117_18","014_17_18","1CH","17","18","18","מה יוסיף עוד דויד אליך לכבוד את עבדך ואתה את עבדך ידעת׃ ");
INSERT INTO heb_vpl VALUES ("R117_19","014_17_19","1CH","17","19","19","יהוה בעבור עבדך וכלבך עשית את כל הגדולה הזאת להדיע את כל הגדלות׃ ");
INSERT INTO heb_vpl VALUES ("R117_20","014_17_20","1CH","17","20","20","יהוה אין כמוך ואין אלהים זולתך בכל אשר שמענו באזנינו׃ ");
INSERT INTO heb_vpl VALUES ("R117_21","014_17_21","1CH","17","21","21","ומי כעמך ישראל גוי אחד בארץ אשר הלך האלהים לפדות לו עם לשום לך שם גדלות ונראות לגרש מפני עמך אשר פדית ממצרים גוים׃ ");
INSERT INTO heb_vpl VALUES ("R117_22","014_17_22","1CH","17","22","22","ותתן את עמך ישראל לך לעם עד עולם ואתה יהוה היית להם לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("R117_23","014_17_23","1CH","17","23","23","ועתה יהוה הדבר אשר דברת על עבדך ועל ביתו יאמן עד עולם ועשה כאשר דברת׃ ");
INSERT INTO heb_vpl VALUES ("R117_24","014_17_24","1CH","17","24","24","ויאמן ויגדל שמך עד עולם לאמר יהוה צבאות אלהי ישראל אלהים לישראל ובית דויד עבדך נכון לפניך׃ ");
INSERT INTO heb_vpl VALUES ("R117_25","014_17_25","1CH","17","25","25","כי אתה אלהי גלית את אזן עבדך לבנות לו בית על כן מצא עבדך להתפלל לפניך׃ ");
INSERT INTO heb_vpl VALUES ("R117_26","014_17_26","1CH","17","26","26","ועתה יהוה אתה הוא האלהים ותדבר על עבדך הטובה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("R117_27","014_17_27","1CH","17","27","27","ועתה הואלת לברך את בית עבדך להיות לעולם לפניך כי אתה יהוה ברכת ומברך לעולם׃ ");
INSERT INTO heb_vpl VALUES ("R118_1","014_18_1","1CH","18","1","1","ויהי אחרי כן ויך דויד את פלשתים ויכניעם ויקח את גת ובנתיה מיד פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("R118_2","014_18_2","1CH","18","2","2","ויך את מואב ויהיו מואב עבדים לדויד נשאי מנחה׃ ");
INSERT INTO heb_vpl VALUES ("R118_3","014_18_3","1CH","18","3","3","ויך דויד את הדדעזר מלך צובה חמתה בלכתו להציב ידו בנהר פרת׃ ");
INSERT INTO heb_vpl VALUES ("R118_4","014_18_4","1CH","18","4","4","וילכד דויד ממנו אלף רכב ושבעת אלפים פרשים ועשרים אלף איש רגלי ויעקר דויד את כל הרכב ויותר ממנו מאה רכב׃ ");
INSERT INTO heb_vpl VALUES ("R118_5","014_18_5","1CH","18","5","5","ויבא ארם דרמשק לעזור להדדעזר מלך צובה ויך דויד בארם עשרים ושנים אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("R118_6","014_18_6","1CH","18","6","6","וישם דויד בארם דרמשק ויהי ארם לדויד עבדים נשאי מנחה ויושע יהוה לדויד בכל אשר הלך׃ ");
INSERT INTO heb_vpl VALUES ("R118_7","014_18_7","1CH","18","7","7","ויקח דויד את שלטי הזהב אשר היו על עבדי הדדעזר ויביאם ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R118_8","014_18_8","1CH","18","8","8","ומטבחת ומכון ערי הדדעזר לקח דויד נחשת רבה מאד בה עשה שלמה את ים הנחשת ואת העמודים ואת כלי הנחשת׃ ");
INSERT INTO heb_vpl VALUES ("R118_9","014_18_9","1CH","18","9","9","וישמע תעו מלך חמת כי הכה דויד את כל חיל הדדעזר מלך צובה׃ ");
INSERT INTO heb_vpl VALUES ("R118_10","014_18_10","1CH","18","10","10","וישלח את הדורם בנו אל המלך דויד לשאול לו לשלום ולברכו על אשר נלחם בהדדעזר ויכהו כי איש מלחמות תעו היה הדדעזר וכל כלי זהב וכסף ונחשת׃ ");
INSERT INTO heb_vpl VALUES ("R118_11","014_18_11","1CH","18","11","11","גם אתם הקדיש המלך דויד ליהוה עם הכסף והזהב אשר נשא מכל הגוים מאדום וממואב ומבני עמון ומפלשתים ומעמלק׃ ");
INSERT INTO heb_vpl VALUES ("R118_12","014_18_12","1CH","18","12","12","ואבשי בן צרויה הכה את אדום בגיא המלח שמונה עשר אלף׃ ");
INSERT INTO heb_vpl VALUES ("R118_13","014_18_13","1CH","18","13","13","וישם באדום נציבים ויהיו כל אדום עבדים לדויד ויושע יהוה את דויד בכל אשר הלך׃ ");
INSERT INTO heb_vpl VALUES ("R118_14","014_18_14","1CH","18","14","14","וימלך דויד על כל ישראל ויהי עשה משפט וצדקה לכל עמו׃ ");
INSERT INTO heb_vpl VALUES ("R118_15","014_18_15","1CH","18","15","15","ויואב בן צרויה על הצבא ויהושפט בן אחילוד מזכיר׃ ");
INSERT INTO heb_vpl VALUES ("R118_16","014_18_16","1CH","18","16","16","וצדוק בן אחיטוב ואבימלך בן אביתר כהנים ושושא סופר׃ ");
INSERT INTO heb_vpl VALUES ("R118_17","014_18_17","1CH","18","17","17","ובניהו בן יהוידע על הכרתי והפלתי ובני דויד הראשנים ליד המלך׃ ");
INSERT INTO heb_vpl VALUES ("R119_1","014_19_1","1CH","19","1","1","ויהי אחרי כן וימת נחש מלך בני עמון וימלך בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R119_2","014_19_2","1CH","19","2","2","ויאמר דויד אעשה חסד עם חנון בן נחש כי עשה אביו עמי חסד וישלח דויד מלאכים לנחמו על אביו ויבאו עבדי דויד אל ארץ בני עמון אל חנון לנחמו׃ ");
INSERT INTO heb_vpl VALUES ("R119_3","014_19_3","1CH","19","3","3","ויאמרו שרי בני עמון לחנון המכבד דויד את אביך בעיניך כי שלח לך מנחמים הלא בעבור לחקר ולהפך ולרגל הארץ באו עבדיו אליך׃ ");
INSERT INTO heb_vpl VALUES ("R119_4","014_19_4","1CH","19","4","4","ויקח חנון את עבדי דויד ויגלחם ויכרת את מדויהם בחצי עד המפשעה וישלחם׃ ");
INSERT INTO heb_vpl VALUES ("R119_5","014_19_5","1CH","19","5","5","וילכו ויגידו לדויד על האנשים וישלח לקראתם כי היו האנשים נכלמים מאד ויאמר המלך שבו בירחו עד אשר יצמח זקנכם ושבתם׃ ");
INSERT INTO heb_vpl VALUES ("R119_6","014_19_6","1CH","19","6","6","ויראו בני עמון כי התבאשו עם דויד וישלח חנון ובני עמון אלף ככר כסף לשכר להם מן ארם נהרים ומן ארם מעכה ומצובה רכב ופרשים׃ ");
INSERT INTO heb_vpl VALUES ("R119_7","014_19_7","1CH","19","7","7","וישכרו להם שנים ושלשים אלף רכב ואת מלך מעכה ואת עמו ויבאו ויחנו לפני מידבא ובני עמון נאספו מעריהם ויבאו למלחמה׃ ");
INSERT INTO heb_vpl VALUES ("R119_8","014_19_8","1CH","19","8","8","וישמע דויד וישלח את יואב ואת כל צבא הגבורים׃ ");
INSERT INTO heb_vpl VALUES ("R119_9","014_19_9","1CH","19","9","9","ויצאו בני עמון ויערכו מלחמה פתח העיר והמלכים אשר באו לבדם בשדה׃ ");
INSERT INTO heb_vpl VALUES ("R119_10","014_19_10","1CH","19","10","10","וירא יואב כי היתה פני המלחמה אליו פנים ואחור ויבחר מכל בחור בישראל ויערך לקראת ארם׃ ");
INSERT INTO heb_vpl VALUES ("R119_11","014_19_11","1CH","19","11","11","ואת יתר העם נתן ביד אבשי אחיו ויערכו לקראת בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("R119_12","014_19_12","1CH","19","12","12","ויאמר אם תחזק ממני ארם והיית לי לתשועה ואם בני עמון יחזקו ממך והושעתיך׃ ");
INSERT INTO heb_vpl VALUES ("R119_13","014_19_13","1CH","19","13","13","חזק ונתחזקה בעד עמנו ובעד ערי אלהינו ויהוה הטוב בעיניו יעשה׃ ");
INSERT INTO heb_vpl VALUES ("R119_14","014_19_14","1CH","19","14","14","ויגש יואב והעם אשר עמו לפני ארם למלחמה וינוסו מפניו׃ ");
INSERT INTO heb_vpl VALUES ("R119_15","014_19_15","1CH","19","15","15","ובני עמון ראו כי נס ארם וינוסו גם הם מפני אבשי אחיו ויבאו העירה ויבא יואב ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R119_16","014_19_16","1CH","19","16","16","וירא ארם כי נגפו לפני ישראל וישלחו מלאכים ויוציאו את ארם אשר מעבר הנהר ושופך שר צבא הדדעזר לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("R119_17","014_19_17","1CH","19","17","17","ויגד לדויד ויאסף את כל ישראל ויעבר הירדן ויבא אלהם ויערך אלהם ויערך דויד לקראת ארם מלחמה וילחמו עמו׃ ");
INSERT INTO heb_vpl VALUES ("R119_18","014_19_18","1CH","19","18","18","וינס ארם מלפני ישראל ויהרג דויד מארם שבעת אלפים רכב וארבעים אלף איש רגלי ואת שופך שר הצבא המית׃ ");
INSERT INTO heb_vpl VALUES ("R119_19","014_19_19","1CH","19","19","19","ויראו עבדי הדדעזר כי נגפו לפני ישראל וישלימו עם דויד ויעבדהו ולא אבה ארם להושיע את בני עמון עוד׃ ");
INSERT INTO heb_vpl VALUES ("R120_1","014_20_1","1CH","20","1","1","ויהי לעת תשובת השנה לעת צאת המלכים וינהג יואב את חיל הצבא וישחת את ארץ בני עמון ויבא ויצר את רבה ודויד ישב בירושלם ויך יואב את רבה ויהרסה׃ ");
INSERT INTO heb_vpl VALUES ("R120_2","014_20_2","1CH","20","2","2","ויקח דויד את עטרת מלכם מעל ראשו וימצאה משקל ככר זהב ובה אבן יקרה ותהי על ראש דויד ושלל העיר הוציא הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("R120_3","014_20_3","1CH","20","3","3","ואת העם אשר בה הוציא וישר במגרה ובחריצי הברזל ובמגרות וכן יעשה דויד לכל ערי בני עמון וישב דויד וכל העם ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R120_4","014_20_4","1CH","20","4","4","ויהי אחריכן ותעמד מלחמה בגזר עם פלשתים אז הכה סבכי החשתי את ספי מילדי הרפאים ויכנעו׃ ");
INSERT INTO heb_vpl VALUES ("R120_5","014_20_5","1CH","20","5","5","ותהי עוד מלחמה את פלשתים ויך אלחנן בן יעור את לחמי אחי גלית הגתי ועץ חניתו כמנור ארגים׃ ");
INSERT INTO heb_vpl VALUES ("R120_6","014_20_6","1CH","20","6","6","ותהי עוד מלחמה בגת ויהי איש מדה ואצבעתיו שש ושש עשרים וארבע וגם הוא נולד להרפא׃ ");
INSERT INTO heb_vpl VALUES ("R120_7","014_20_7","1CH","20","7","7","ויחרף את ישראל ויכהו יהונתן בן שמעא אחי דויד׃ ");
INSERT INTO heb_vpl VALUES ("R120_8","014_20_8","1CH","20","8","8","אל נולדו להרפא בגת ויפלו ביד דויד וביד עבדיו׃ ");
INSERT INTO heb_vpl VALUES ("R121_1","014_21_1","1CH","21","1","1","ויעמד שטן על ישראל ויסת את דויד למנות את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R121_2","014_21_2","1CH","21","2","2","ויאמר דויד אל יואב ואל שרי העם לכו ספרו את ישראל מבאר שבע ועד דן והביאו אלי ואדעה את מספרם׃ ");
INSERT INTO heb_vpl VALUES ("R121_3","014_21_3","1CH","21","3","3","ויאמר יואב יוסף יהוה על עמו כהם מאה פעמים הלא אדני המלך כלם לאדני לעבדים למה יבקש זאת אדני למה יהיה לאשמה לישראל׃ ");
INSERT INTO heb_vpl VALUES ("R121_4","014_21_4","1CH","21","4","4","ודבר המלך חזק על יואב ויצא יואב ויתהלך בכל ישראל ויבא ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R121_5","014_21_5","1CH","21","5","5","ויתן יואב את מספר מפקד העם אל דויד ויהי כל ישראל אלף אלפים ומאה אלף איש שלף חרב ויהודה ארבע מאות ושבעים אלף איש שלף חרב׃ ");
INSERT INTO heb_vpl VALUES ("R121_6","014_21_6","1CH","21","6","6","ולוי ובנימן לא פקד בתוכם כי נתעב דבר המלך את יואב׃ ");
INSERT INTO heb_vpl VALUES ("R121_7","014_21_7","1CH","21","7","7","וירע בעיני האלהים על הדבר הזה ויך את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R121_8","014_21_8","1CH","21","8","8","ויאמר דויד אל האלהים חטאתי מאד אשר עשיתי את הדבר הזה ועתה העבר נא את עוון עבדך כי נסכלתי מאד׃ ");
INSERT INTO heb_vpl VALUES ("R121_9","014_21_9","1CH","21","9","9","וידבר יהוה אל גד חזה דויד לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R121_10","014_21_10","1CH","21","10","10","לך ודברת אל דויד לאמר כה אמר יהוה שלוש אני נטה עליך בחר לך אחת מהנה ואעשה לך׃ ");
INSERT INTO heb_vpl VALUES ("R121_11","014_21_11","1CH","21","11","11","ויבא גד אל דויד ויאמר לו כה אמר יהוה קבל לך׃ ");
INSERT INTO heb_vpl VALUES ("R121_12","014_21_12","1CH","21","12","12","אם שלוש שנים רעב ואם שלשה חדשים נספה מפני צריך וחרב אויבך למשגת ואם שלשת ימים חרב יהוה ודבר בארץ ומלאך יהוה משחית בכל גבול ישראל ועתה ראה מה אשיב את שלחי דבר׃ ");
INSERT INTO heb_vpl VALUES ("R121_13","014_21_13","1CH","21","13","13","ויאמר דויד אל גד צר לי מאד אפלה נא ביד יהוה כי רבים רחמיו מאד וביד אדם אל אפל׃ ");
INSERT INTO heb_vpl VALUES ("R121_14","014_21_14","1CH","21","14","14","ויתן יהוה דבר בישראל ויפל מישראל שבעים אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("R121_15","014_21_15","1CH","21","15","15","וישלח האלהים מלאך לירושלם להשחיתה וכהשחית ראה יהוה וינחם על הרעה ויאמר למלאך המשחית רב עתה הרף ידך ומלאך יהוה עמד עם גרן ארנן היבוסי׃ ");
INSERT INTO heb_vpl VALUES ("R121_16","014_21_16","1CH","21","16","16","וישא דויד את עיניו וירא את מלאך יהוה עמד בין הארץ ובין השמים וחרבו שלופה בידו נטויה על ירושלם ויפל דויד והזקנים מכסים בשקים על פניהם׃ ");
INSERT INTO heb_vpl VALUES ("R121_17","014_21_17","1CH","21","17","17","ויאמר דויד אל האלהים הלא אני אמרתי למנות בעם ואני הוא אשר חטאתי והרע הרעותי ואלה הצאן מה עשו יהוה אלהי תהי נא ידך בי ובבית אבי ובעמך לא למגפה׃ ");
INSERT INTO heb_vpl VALUES ("R121_18","014_21_18","1CH","21","18","18","ומלאך יהוה אמר אל גד לאמר לדויד כי יעלה דויד להקים מזבח ליהוה בגרן ארנן היבסי׃ ");
INSERT INTO heb_vpl VALUES ("R121_19","014_21_19","1CH","21","19","19","ויעל דויד בדבר גד אשר דבר בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R121_20","014_21_20","1CH","21","20","20","וישב ארנן וירא את המלאך וארבעת בניו עמו מתחבאים וארנן דש חטים׃ ");
INSERT INTO heb_vpl VALUES ("R121_21","014_21_21","1CH","21","21","21","ויבא דויד עד ארנן ויבט ארנן וירא את דויד ויצא מן הגרן וישתחו לדויד אפים ארצה׃ ");
INSERT INTO heb_vpl VALUES ("R121_22","014_21_22","1CH","21","22","22","ויאמר דויד אל ארנן תנה לי מקום הגרן ואבנה בו מזבח ליהוה בכסף מלא תנהו לי ותעצר המגפה מעל העם׃ ");
INSERT INTO heb_vpl VALUES ("R121_23","014_21_23","1CH","21","23","23","ויאמר ארנן אל דויד קח לך ויעש אדני המלך הטוב בעיניו ראה נתתי הבקר לעלות והמורגים לעצים והחטים למנחה הכל נתתי׃ ");
INSERT INTO heb_vpl VALUES ("R121_24","014_21_24","1CH","21","24","24","ויאמר המלך דויד לארנן לא כי קנה אקנה בכסף מלא כי לא אשא אשר לך ליהוה והעלות עולה חנם׃ ");
INSERT INTO heb_vpl VALUES ("R121_25","014_21_25","1CH","21","25","25","ויתן דויד לארנן במקום שקלי זהב משקל שש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R121_26","014_21_26","1CH","21","26","26","ויבן שם דויד מזבח ליהוה ויעל עלות ושלמים ויקרא אל יהוה ויענהו באש מן השמים על מזבח העלה׃ ");
INSERT INTO heb_vpl VALUES ("R121_27","014_21_27","1CH","21","27","27","ויאמר יהוה למלאך וישב חרבו אל נדנה׃ ");
INSERT INTO heb_vpl VALUES ("R121_28","014_21_28","1CH","21","28","28","בעת ההיא בראות דויד כי ענהו יהוה בגרן ארנן היבוסי ויזבח שם׃ ");
INSERT INTO heb_vpl VALUES ("R121_29","014_21_29","1CH","21","29","29","ומשכן יהוה אשר עשה משה במדבר ומזבח העולה בעת ההיא בבמה בגבעון׃ ");
INSERT INTO heb_vpl VALUES ("R121_30","014_21_30","1CH","21","30","30","ולא יכל דויד ללכת לפניו לדרש אלהים כי נבעת מפני חרב מלאך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R122_1","014_22_1","1CH","22","1","1","ויאמר דויד זה הוא בית יהוה האלהים וזה מזבח לעלה לישראל׃ ");
INSERT INTO heb_vpl VALUES ("R122_2","014_22_2","1CH","22","2","2","ויאמר דויד לכנוס את הגרים אשר בארץ ישראל ויעמד חצבים לחצוב אבני גזית לבנות בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R122_3","014_22_3","1CH","22","3","3","וברזל לרב למסמרים לדלתות השערים ולמחברות הכין דויד ונחשת לרב אין משקל׃ ");
INSERT INTO heb_vpl VALUES ("R122_4","014_22_4","1CH","22","4","4","ועצי ארזים לאין מספר כי הביאו הצידנים והצרים עצי ארזים לרב לדויד׃ ");
INSERT INTO heb_vpl VALUES ("R122_5","014_22_5","1CH","22","5","5","ויאמר דויד שלמה בני נער ורך והבית לבנות ליהוה להגדיל למעלה לשם ולתפארת לכל הארצות אכינה נא לו ויכן דויד לרב לפני מותו׃ ");
INSERT INTO heb_vpl VALUES ("R122_6","014_22_6","1CH","22","6","6","ויקרא לשלמה בנו ויצוהו לבנות בית ליהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R122_7","014_22_7","1CH","22","7","7","ויאמר דויד לשלמה בנו אני היה עם לבבי לבנות בית לשם יהוה אלהי׃ ");
INSERT INTO heb_vpl VALUES ("R122_8","014_22_8","1CH","22","8","8","ויהי עלי דבר יהוה לאמר דם לרב שפכת ומלחמות גדלות עשית לא תבנה בית לשמי כי דמים רבים שפכת ארצה לפני׃ ");
INSERT INTO heb_vpl VALUES ("R122_9","014_22_9","1CH","22","9","9","הנה בן נולד לך הוא יהיה איש מנוחה והנחותי לו מכל אויביו מסביב כי שלמה יהיה שמו ושלום ושקט אתן על ישראל בימיו׃ ");
INSERT INTO heb_vpl VALUES ("R122_10","014_22_10","1CH","22","10","10","הוא יבנה בית לשמי והוא יהיה לי לבן ואני לו לאב והכינותי כסא מלכותו על ישראל עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("R122_11","014_22_11","1CH","22","11","11","עתה בני יהי יהוה עמך והצלחת ובנית בית יהוה אלהיך כאשר דבר עליך׃ ");
INSERT INTO heb_vpl VALUES ("R122_12","014_22_12","1CH","22","12","12","אך יתן לך יהוה שכל ובינה ויצוך על ישראל ולשמור את תורת יהוה אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("R122_13","014_22_13","1CH","22","13","13","אז תצליח אם תשמור לעשות את החקים ואת המשפטים אשר צוה יהוה את משה על ישראל חזק ואמץ אל תירא ואל תחת׃ ");
INSERT INTO heb_vpl VALUES ("R122_14","014_22_14","1CH","22","14","14","והנה בעניי הכינותי לבית יהוה זהב ככרים מאה אלף וכסף אלף אלפים ככרים ולנחשת ולברזל אין משקל כי לרב היה ועצים ואבנים הכינותי ועליהם תוסיף׃ ");
INSERT INTO heb_vpl VALUES ("R122_15","014_22_15","1CH","22","15","15","ועמך לרב עשי מלאכה חצבים וחרשי אבן ועץ וכל חכם בכל מלאכה׃ ");
INSERT INTO heb_vpl VALUES ("R122_16","014_22_16","1CH","22","16","16","לזהב לכסף ולנחשת ולברזל אין מספר קום ועשה ויהי יהוה עמך׃ ");
INSERT INTO heb_vpl VALUES ("R122_17","014_22_17","1CH","22","17","17","ויצו דויד לכל שרי ישראל לעזר לשלמה בנו׃ ");
INSERT INTO heb_vpl VALUES ("R122_18","014_22_18","1CH","22","18","18","הלא יהוה אלהיכם עמכם והניח לכם מסביב כי נתן בידי את ישבי הארץ ונכבשה הארץ לפני יהוה ולפני עמו׃ ");
INSERT INTO heb_vpl VALUES ("R122_19","014_22_19","1CH","22","19","19","עתה תנו לבבכם ונפשכם לדרוש ליהוה אלהיכם וקומו ובנו את מקדש יהוה האלהים להביא את ארון ברית יהוה וכלי קדש האלהים לבית הנבנה לשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R123_1","014_23_1","1CH","23","1","1","ודויד זקן ושבע ימים וימלך את שלמה בנו על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R123_2","014_23_2","1CH","23","2","2","ויאסף את כל שרי ישראל והכהנים והלוים׃ ");
INSERT INTO heb_vpl VALUES ("R123_3","014_23_3","1CH","23","3","3","ויספרו הלוים מבן שלשים שנה ומעלה ויהי מספרם לגלגלתם לגברים שלשים ושמונה אלף׃ ");
INSERT INTO heb_vpl VALUES ("R123_4","014_23_4","1CH","23","4","4","מאלה לנצח על מלאכת בית יהוה עשרים וארבעה אלף ושטרים ושפטים ששת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("R123_5","014_23_5","1CH","23","5","5","וארבעת אלפים שערים וארבעת אלפים מהללים ליהוה בכלים אשר עשיתי להלל׃ ");
INSERT INTO heb_vpl VALUES ("R123_6","014_23_6","1CH","23","6","6","ויחלקם דויד מחלקות לבני לוי לגרשון קהת ומררי׃ ");
INSERT INTO heb_vpl VALUES ("R123_7","014_23_7","1CH","23","7","7","לגרשני לעדן ושמעי׃ ");
INSERT INTO heb_vpl VALUES ("R123_8","014_23_8","1CH","23","8","8","בני לעדן הראש יחיאל וזתם ויואל שלשה׃ ");
INSERT INTO heb_vpl VALUES ("R123_9","014_23_9","1CH","23","9","9","בני שמעי שלמות וחזיאל והרן שלשה אלה ראשי האבות ללעדן׃ ");
INSERT INTO heb_vpl VALUES ("R123_10","014_23_10","1CH","23","10","10","ובני שמעי יחת זינא ויעוש ובריעה אלה בני שמעי ארבעה׃ ");
INSERT INTO heb_vpl VALUES ("R123_11","014_23_11","1CH","23","11","11","ויהי יחת הראש וזיזה השני ויעוש ובריעה לא הרבו בנים ויהיו לבית אב לפקדה אחת׃ ");
INSERT INTO heb_vpl VALUES ("R123_12","014_23_12","1CH","23","12","12","בני קהת עמרם יצהר חברון ועזיאל ארבעה׃ ");
INSERT INTO heb_vpl VALUES ("R123_13","014_23_13","1CH","23","13","13","בני עמרם אהרן ומשה ויבדל אהרן להקדישו קדש קדשים הוא ובניו עד עולם להקטיר לפני יהוה לשרתו ולברך בשמו עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("R123_14","014_23_14","1CH","23","14","14","ומשה איש האלהים בניו יקראו על שבט הלוי׃ ");
INSERT INTO heb_vpl VALUES ("R123_15","014_23_15","1CH","23","15","15","בני משה גרשם ואליעזר׃ ");
INSERT INTO heb_vpl VALUES ("R123_16","014_23_16","1CH","23","16","16","בני גרשום שבואל הראש׃ ");
INSERT INTO heb_vpl VALUES ("R123_17","014_23_17","1CH","23","17","17","ויהיו בני אליעזר רחביה הראש ולא היה לאליעזר בנים אחרים ובני רחביה רבו למעלה׃ ");
INSERT INTO heb_vpl VALUES ("R123_18","014_23_18","1CH","23","18","18","בני יצהר שלמית הראש׃ ");
INSERT INTO heb_vpl VALUES ("R123_19","014_23_19","1CH","23","19","19","בני חברון יריהו הראש אמריה השני יחזיאל השלישי ויקמעם הרביעי׃ ");
INSERT INTO heb_vpl VALUES ("R123_20","014_23_20","1CH","23","20","20","בני עזיאל מיכה הראש וישיה השני׃ ");
INSERT INTO heb_vpl VALUES ("R123_21","014_23_21","1CH","23","21","21","בני מררי מחלי ומושי בני מחלי אלעזר וקיש׃ ");
INSERT INTO heb_vpl VALUES ("R123_22","014_23_22","1CH","23","22","22","וימת אלעזר ולא היו לו בנים כי אם בנות וישאום בני קיש אחיהם׃ ");
INSERT INTO heb_vpl VALUES ("R123_23","014_23_23","1CH","23","23","23","בני מושי מחלי ועדר וירמות שלשה׃ ");
INSERT INTO heb_vpl VALUES ("R123_24","014_23_24","1CH","23","24","24","אלה בני לוי לבית אבתיהם ראשי האבות לפקודיהם במספר שמות לגלגלתם עשה המלאכה לעבדת בית יהוה מבן עשרים שנה ומעלה׃ ");
INSERT INTO heb_vpl VALUES ("R123_25","014_23_25","1CH","23","25","25","כי אמר דויד הניח יהוה אלהי ישראל לעמו וישכן בירושלם עד לעולם׃ ");
INSERT INTO heb_vpl VALUES ("R123_26","014_23_26","1CH","23","26","26","וגם ללוים אין לשאת את המשכן ואת כל כליו לעבדתו׃ ");
INSERT INTO heb_vpl VALUES ("R123_27","014_23_27","1CH","23","27","27","כי בדברי דויד האחרנים המה מספר בני לוי מבן עשרים שנה ולמעלה׃ ");
INSERT INTO heb_vpl VALUES ("R123_28","014_23_28","1CH","23","28","28","כי מעמדם ליד בני אהרן לעבדת בית יהוה על החצרות ועל הלשכות ועל טהרת לכל קדש ומעשה עבדת בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R123_29","014_23_29","1CH","23","29","29","וללחם המערכת ולסלת למנחה ולרקיקי המצות ולמחבת ולמרבכת ולכל משורה ומדה׃ ");
INSERT INTO heb_vpl VALUES ("R123_30","014_23_30","1CH","23","30","30","ולעמד בבקר בבקר להדות ולהלל ליהוה וכן לערב׃ ");
INSERT INTO heb_vpl VALUES ("R123_31","014_23_31","1CH","23","31","31","ולכל העלות עלות ליהוה לשבתות לחדשים ולמעדים במספר כמשפט עליהם תמיד לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R123_32","014_23_32","1CH","23","32","32","ושמרו את משמרת אהל מועד ואת משמרת הקדש ומשמרת בני אהרן אחיהם לעבדת בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R124_1","014_24_1","1CH","24","1","1","ולבני אהרן מחלקותם בני אהרן נדב ואביהוא אלעזר ואיתמר׃ ");
INSERT INTO heb_vpl VALUES ("R124_2","014_24_2","1CH","24","2","2","וימת נדב ואביהוא לפני אביהם ובנים לא היו להם ויכהנו אלעזר ואיתמר׃ ");
INSERT INTO heb_vpl VALUES ("R124_3","014_24_3","1CH","24","3","3","ויחלקם דויד וצדוק מן בני אלעזר ואחימלך מן בני איתמר לפקדתם בעבדתם׃ ");
INSERT INTO heb_vpl VALUES ("R124_4","014_24_4","1CH","24","4","4","וימצאו בני אלעזר רבים לראשי הגברים מן בני איתמר ויחלקום לבני אלעזר ראשים לבית אבות ששה עשר ולבני איתמר לבית אבותם שמונה׃ ");
INSERT INTO heb_vpl VALUES ("R124_5","014_24_5","1CH","24","5","5","ויחלקום בגורלות אלה עם אלה כי היו שרי קדש ושרי האלהים מבני אלעזר ובבני איתמר׃ ");
INSERT INTO heb_vpl VALUES ("R124_6","014_24_6","1CH","24","6","6","ויכתבם שמעיה בן נתנאל הסופר מן הלוי לפני המלך והשרים וצדוק הכהן ואחימלך בן אביתר וראשי האבות לכהנים וללוים בית אב אחד אחז לאלעזר ואחז אחז לאיתמר׃ ");
INSERT INTO heb_vpl VALUES ("R124_7","014_24_7","1CH","24","7","7","ויצא הגורל הראשון ליהויריב לידעיה השני׃ ");
INSERT INTO heb_vpl VALUES ("R124_8","014_24_8","1CH","24","8","8","לחרם השלישי לשערים הרבעי׃ ");
INSERT INTO heb_vpl VALUES ("R124_9","014_24_9","1CH","24","9","9","למלכיה החמישי למימן הששי׃ ");
INSERT INTO heb_vpl VALUES ("R124_10","014_24_10","1CH","24","10","10","להקוץ השבעי לאביה השמיני׃ ");
INSERT INTO heb_vpl VALUES ("R124_11","014_24_11","1CH","24","11","11","לישוע התשעי לשכניהו העשרי׃ ");
INSERT INTO heb_vpl VALUES ("R124_12","014_24_12","1CH","24","12","12","לאלישיב עשתי עשר ליקים שנים עשר׃ ");
INSERT INTO heb_vpl VALUES ("R124_13","014_24_13","1CH","24","13","13","לחפה שלשה עשר לישבאב ארבעה עשר׃ ");
INSERT INTO heb_vpl VALUES ("R124_14","014_24_14","1CH","24","14","14","לבלגה חמשה עשר לאמר ששה עשר׃ ");
INSERT INTO heb_vpl VALUES ("R124_15","014_24_15","1CH","24","15","15","לחזיר שבעה עשר להפצץ שמונה עשר׃ ");
INSERT INTO heb_vpl VALUES ("R124_16","014_24_16","1CH","24","16","16","לפתחיה תשעה עשר ליחזקאל העשרים׃ ");
INSERT INTO heb_vpl VALUES ("R124_17","014_24_17","1CH","24","17","17","ליכין אחד ועשרים לגמול שנים ועשרים׃ ");
INSERT INTO heb_vpl VALUES ("R124_18","014_24_18","1CH","24","18","18","לדליהו שלשה ועשרים למעזיהו ארבעה ועשרים׃ ");
INSERT INTO heb_vpl VALUES ("R124_19","014_24_19","1CH","24","19","19","אלה פקדתם לעבדתם לבוא לבית יהוה כמשפטם ביד אהרן אביהם כאשר צוהו יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R124_20","014_24_20","1CH","24","20","20","ולבני לוי הנותרים לבני עמרם שובאל לבני שובאל יחדיהו׃ ");
INSERT INTO heb_vpl VALUES ("R124_21","014_24_21","1CH","24","21","21","לרחביהו לבני רחביהו הראש ישיה׃ ");
INSERT INTO heb_vpl VALUES ("R124_22","014_24_22","1CH","24","22","22","ליצהרי שלמות לבני שלמות יחת׃ ");
INSERT INTO heb_vpl VALUES ("R124_23","014_24_23","1CH","24","23","23","ובני יריהו אמריהו השני יחזיאל השלישי יקמעם הרביעי׃ ");
INSERT INTO heb_vpl VALUES ("R124_24","014_24_24","1CH","24","24","24","בני עזיאל מיכה לבני מיכה שמור׃ ");
INSERT INTO heb_vpl VALUES ("R124_25","014_24_25","1CH","24","25","25","אחי מיכה ישיה לבני ישיה זכריהו׃ ");
INSERT INTO heb_vpl VALUES ("R124_26","014_24_26","1CH","24","26","26","בני מררי מחלי ומושי בני יעזיהו בנו׃ ");
INSERT INTO heb_vpl VALUES ("R124_27","014_24_27","1CH","24","27","27","בני מררי ליעזיהו בנו ושהם וזכור ועברי׃ ");
INSERT INTO heb_vpl VALUES ("R124_28","014_24_28","1CH","24","28","28","למחלי אלעזר ולא היה לו בנים׃ ");
INSERT INTO heb_vpl VALUES ("R124_29","014_24_29","1CH","24","29","29","לקיש בני קיש ירחמאל׃ ");
INSERT INTO heb_vpl VALUES ("R124_30","014_24_30","1CH","24","30","30","ובני מושי מחלי ועדר וירימות אלה בני הלוים לבית אבתיהם׃ ");
INSERT INTO heb_vpl VALUES ("R124_31","014_24_31","1CH","24","31","31","ויפילו גם הם גורלות לעמת אחיהם בני אהרן לפני דויד המלך וצדוק ואחימלך וראשי האבות לכהנים וללוים אבות הראש לעמת אחיו הקטן׃ ");
INSERT INTO heb_vpl VALUES ("R125_1","014_25_1","1CH","25","1","1","ויבדל דויד ושרי הצבא לעבדה לבני אסף והימן וידותון הנביאים בכנרות בנבלים ובמצלתים ויהי מספרם אנשי מלאכה לעבדתם׃ ");
INSERT INTO heb_vpl VALUES ("R125_2","014_25_2","1CH","25","2","2","לבני אסף זכור ויוסף ונתניה ואשראלה בני אסף על יד אסף הנבא על ידי המלך׃ ");
