INSERT INTO heb_vpl VALUES ("R125_4","014_25_4","1CH","25","4","4","להימן בני הימן בקיהו מתניהו עזיאל שבואל וירימות חנניה חנני אליאתה גדלתי ורממתי עזר ישבקשה מלותי הותיר מחזיאות׃ ");
INSERT INTO heb_vpl VALUES ("R125_5","014_25_5","1CH","25","5","5","כל אלה בנים להימן חזה המלך בדברי האלהים להרים קרן ויתן האלהים להימן בנים ארבעה עשר ובנות שלוש׃ ");
