INSERT INTO heb_vpl VALUES ("R125_7","014_25_7","1CH","25","7","7","ויהי מספרם עם אחיהם מלמדי שיר ליהוה כל המבין מאתים שמונים ושמונה׃ ");
INSERT INTO heb_vpl VALUES ("R125_8","014_25_8","1CH","25","8","8","ויפילו גורלות משמרת לעמת כקטן כגדול מבין עם תלמיד׃ ");
