INSERT INTO heb_vpl VALUES ("R127_24","014_27_24","1CH","27","24","24","יואב בן צרויה החל למנות ולא כלה ויהי בזאת קצף על ישראל ולא עלה המספר במספר דברי הימים למלך דויד׃ ");
