INSERT INTO heb_vpl VALUES ("R127_32","014_27_32","1CH","27","32","32","ויהונתן דוד דויד יועץ איש מבין וסופר הוא ויחיאל בן חכמוני עם בני המלך׃ ");
INSERT INTO heb_vpl VALUES ("R127_33","014_27_33","1CH","27","33","33","ואחיתפל יועץ למלך וחושי הארכי רע המלך׃ ");
INSERT INTO heb_vpl VALUES ("R127_34","014_27_34","1CH","27","34","34","ואחרי אחיתפל יהוידע בן בניהו ואביתר ושר צבא למלך יואב׃ ");
INSERT INTO heb_vpl VALUES ("R128_1","014_28_1","1CH","28","1","1","ויקהל דויד את כל שרי ישראל שרי השבטים ושרי המחלקות המשרתים את המלך ושרי האלפים ושרי המאות ושרי כל רכוש ומקנה למלך ולבניו עם הסריסים והגבורים ולכל גבור חיל אל ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R128_2","014_28_2","1CH","28","2","2","ויקם דויד המלך על רגליו ויאמר שמעוני אחי ועמי אני עם לבבי לבנות בית מנוחה לארון ברית יהוה ולהדם רגלי אלהינו והכינותי לבנות׃ ");
INSERT INTO heb_vpl VALUES ("R128_3","014_28_3","1CH","28","3","3","והאלהים אמר לי לא תבנה בית לשמי כי איש מלחמות אתה ודמים שפכת׃ ");
INSERT INTO heb_vpl VALUES ("R128_4","014_28_4","1CH","28","4","4","ויבחר יהוה אלהי ישראל בי מכל בית אבי להיות למלך על ישראל לעולם כי ביהודה בחר לנגיד ובבית יהודה בית אבי ובבני אבי בי רצה להמליך על כל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R128_5","014_28_5","1CH","28","5","5","ומכל בני כי רבים בנים נתן לי יהוה ויבחר בשלמה בני לשבת על כסא מלכות יהוה על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R128_6","014_28_6","1CH","28","6","6","ויאמר לי שלמה בנך הוא יבנה ביתי וחצרותי כי בחרתי בו לי לבן ואני אהיה לו לאב׃ ");
INSERT INTO heb_vpl VALUES ("R128_7","014_28_7","1CH","28","7","7","והכינותי את מלכותו עד לעולם אם יחזק לעשות מצותי ומשפטי כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R128_8","014_28_8","1CH","28","8","8","ועתה לעיני כל ישראל קהל יהוה ובאזני אלהינו שמרו ודרשו כל מצות יהוה אלהיכם למען תירשו את הארץ הטובה והנחלתם לבניכם אחריכם עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("R128_9","014_28_9","1CH","28","9","9","ואתה שלמה בני דע את אלהי אביך ועבדהו בלב שלם ובנפש חפצה כי כל לבבות דורש יהוה וכל יצר מחשבות מבין אם תדרשנו ימצא לך ואם תעזבנו יזניחך לעד׃ ");
INSERT INTO heb_vpl VALUES ("R128_10","014_28_10","1CH","28","10","10","ראה עתה כי יהוה בחר בך לבנות בית למקדש חזק ועשה׃ ");
INSERT INTO heb_vpl VALUES ("R128_11","014_28_11","1CH","28","11","11","ויתן דויד לשלמה בנו את תבנית האולם ואת בתיו וגנזכיו ועליתיו וחדריו הפנימים ובית הכפרת׃ ");
INSERT INTO heb_vpl VALUES ("R128_12","014_28_12","1CH","28","12","12","ותבנית כל אשר היה ברוח עמו לחצרות בית יהוה ולכל הלשכות סביב לאצרות בית האלהים ולאצרות הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("R128_13","014_28_13","1CH","28","13","13","ולמחלקות הכהנים והלוים ולכל מלאכת עבודת בית יהוה ולכל כלי עבודת בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R128_14","014_28_14","1CH","28","14","14","לזהב במשקל לזהב לכל כלי עבודה ועבודה לכל כלי הכסף במשקל לכל כלי עבודה ועבודה׃ ");
INSERT INTO heb_vpl VALUES ("R128_15","014_28_15","1CH","28","15","15","ומשקל למנרות הזהב ונרתיהם זהב במשקל מנורה ומנורה ונרתיה ולמנרות הכסף במשקל למנורה ונרתיה כעבודת מנורה ומנורה׃ ");
INSERT INTO heb_vpl VALUES ("R128_16","014_28_16","1CH","28","16","16","ואת הזהב משקל לשלחנות המערכת לשלחן ושלחן וכסף לשלחנות הכסף׃ ");
INSERT INTO heb_vpl VALUES ("R128_17","014_28_17","1CH","28","17","17","והמזלגות והמזרקות והקשות זהב טהור ולכפורי הזהב במשקל לכפור וכפור ולכפורי הכסף במשקל לכפור וכפור׃ ");
INSERT INTO heb_vpl VALUES ("R128_18","014_28_18","1CH","28","18","18","ולמזבח הקטרת זהב מזקק במשקל ולתבנית המרכבה הכרבים זהב לפרשים וסככים על ארון ברית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R128_19","014_28_19","1CH","28","19","19","הכל בכתב מיד יהוה עלי השכיל כל מלאכות התבנית׃ ");
INSERT INTO heb_vpl VALUES ("R128_20","014_28_20","1CH","28","20","20","ויאמר דויד לשלמה בנו חזק ואמץ ועשה אל תירא ואל תחת כי יהוה אלהים אלהי עמך לא ירפך ולא יעזבך עד לכלות כל מלאכת עבודת בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R128_21","014_28_21","1CH","28","21","21","והנה מחלקות הכהנים והלוים לכל עבודת בית האלהים ועמך בכל מלאכה לכל נדיב בחכמה לכל עבודה והשרים וכל העם לכל דבריך׃ ");
INSERT INTO heb_vpl VALUES ("R129_1","014_29_1","1CH","29","1","1","ויאמר דויד המלך לכל הקהל שלמה בני אחד בחר בו אלהים נער ורך והמלאכה גדולה כי לא לאדם הבירה כי ליהוה אלהים׃ ");
INSERT INTO heb_vpl VALUES ("R129_2","014_29_2","1CH","29","2","2","וככל כחי הכינותי לבית אלהי הזהב לזהב והכסף לכסף והנחשת לנחשת הברזל לברזל והעצים לעצים אבני שהם ומלואים אבני פוך ורקמה וכל אבן יקרה ואבני שיש לרב׃ ");
INSERT INTO heb_vpl VALUES ("R129_3","014_29_3","1CH","29","3","3","ועוד ברצותי בבית אלהי יש לי סגלה זהב וכסף נתתי לבית אלהי למעלה מכל הכינותי לבית הקדש׃ ");
INSERT INTO heb_vpl VALUES ("R129_4","014_29_4","1CH","29","4","4","שלשת אלפים ככרי זהב מזהב אופיר ושבעת אלפים ככר כסף מזקק לטוח קירות הבתים׃ ");
INSERT INTO heb_vpl VALUES ("R129_5","014_29_5","1CH","29","5","5","לזהב לזהב ולכסף לכסף ולכל מלאכה ביד חרשים ומי מתנדב למלאות ידו היום ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("R129_6","014_29_6","1CH","29","6","6","ויתנדבו שרי האבות ושרי שבטי ישראל ושרי האלפים והמאות ולשרי מלאכת המלך׃ ");
INSERT INTO heb_vpl VALUES ("R129_7","014_29_7","1CH","29","7","7","ויתנו לעבודת בית האלהים זהב ככרים חמשת אלפים ואדרכנים רבו וכסף ככרים עשרת אלפים ונחשת רבו ושמונת אלפים ככרים וברזל מאה אלף ככרים׃ ");
INSERT INTO heb_vpl VALUES ("R129_8","014_29_8","1CH","29","8","8","והנמצא אתו אבנים נתנו לאוצר בית יהוה על יד יחיאל הגרשני׃ ");
INSERT INTO heb_vpl VALUES ("R129_9","014_29_9","1CH","29","9","9","וישמחו העם על התנדבם כי בלב שלם התנדבו ליהוה וגם דויד המלך שמח שמחה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("R129_10","014_29_10","1CH","29","10","10","ויברך דויד את יהוה לעיני כל הקהל ויאמר דויד ברוך אתה יהוה אלהי ישראל אבינו מעולם ועד עולם׃ ");
INSERT INTO heb_vpl VALUES ("R129_11","014_29_11","1CH","29","11","11","לך יהוה הגדלה והגבורה והתפארת והנצח וההוד כי כל בשמים ובארץ לך יהוה הממלכה והמתנשא לכל לראש׃ ");
INSERT INTO heb_vpl VALUES ("R129_12","014_29_12","1CH","29","12","12","והעשר והכבוד מלפניך ואתה מושל בכל ובידך כח וגבורה ובידך לגדל ולחזק לכל׃ ");
INSERT INTO heb_vpl VALUES ("R129_13","014_29_13","1CH","29","13","13","ועתה אלהינו מודים אנחנו לך ומהללים לשם תפארתך׃ ");
INSERT INTO heb_vpl VALUES ("R129_14","014_29_14","1CH","29","14","14","וכי מי אני ומי עמי כי נעצר כח להתנדב כזאת כי ממך הכל ומידך נתנו לך׃ ");
INSERT INTO heb_vpl VALUES ("R129_15","014_29_15","1CH","29","15","15","כי גרים אנחנו לפניך ותושבים ככל אבתינו כצל ימינו על הארץ ואין מקוה׃ ");
INSERT INTO heb_vpl VALUES ("R129_16","014_29_16","1CH","29","16","16","יהוה אלהינו כל ההמון הזה אשר הכיננו לבנות לך בית לשם קדשך מידך היא ולך הכל׃ ");
INSERT INTO heb_vpl VALUES ("R129_17","014_29_17","1CH","29","17","17","וידעתי אלהי כי אתה בחן לבב ומישרים תרצה אני בישר לבבי התנדבתי כל אלה ועתה עמך הנמצאו פה ראיתי בשמחה להתנדב לך׃ ");
INSERT INTO heb_vpl VALUES ("R129_18","014_29_18","1CH","29","18","18","יהוה אלהי אברהם יצחק וישראל אבתינו שמרה זאת לעולם ליצר מחשבות לבב עמך והכן לבבם אליך׃ ");
INSERT INTO heb_vpl VALUES ("R129_19","014_29_19","1CH","29","19","19","ולשלמה בני תן לבב שלם לשמור מצותיך עדותיך וחקיך ולעשות הכל ולבנות הבירה אשר הכינותי׃ ");
INSERT INTO heb_vpl VALUES ("R129_20","014_29_20","1CH","29","20","20","ויאמר דויד לכל הקהל ברכו נא את יהוה אלהיכם ויברכו כל הקהל ליהוה אלהי אבתיהם ויקדו וישתחוו ליהוה ולמלך׃ ");
INSERT INTO heb_vpl VALUES ("R129_21","014_29_21","1CH","29","21","21","ויזבחו ליהוה זבחים ויעלו עלות ליהוה למחרת היום ההוא פרים אלף אילים אלף כבשים אלף ונסכיהם וזבחים לרב לכל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R129_22","014_29_22","1CH","29","22","22","ויאכלו וישתו לפני יהוה ביום ההוא בשמחה גדולה וימליכו שנית לשלמה בן דויד וימשחו ליהוה לנגיד ולצדוק לכהן׃ ");
INSERT INTO heb_vpl VALUES ("R129_23","014_29_23","1CH","29","23","23","וישב שלמה על כסא יהוה למלך תחת דויד אביו ויצלח וישמעו אליו כל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R129_24","014_29_24","1CH","29","24","24","וכל השרים והגברים וגם כל בני המלך דויד נתנו יד תחת שלמה המלך׃ ");
INSERT INTO heb_vpl VALUES ("R129_25","014_29_25","1CH","29","25","25","ויגדל יהוה את שלמה למעלה לעיני כל ישראל ויתן עליו הוד מלכות אשר לא היה על כל מלך לפניו על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R129_26","014_29_26","1CH","29","26","26","ודויד בן ישי מלך על כל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R129_27","014_29_27","1CH","29","27","27","והימים אשר מלך על ישראל ארבעים שנה בחברון מלך שבע שנים ובירושלם מלך שלשים ושלוש׃ ");
INSERT INTO heb_vpl VALUES ("R129_28","014_29_28","1CH","29","28","28","וימת בשיבה טובה שבע ימים עשר וכבוד וימלך שלמה בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R129_29","014_29_29","1CH","29","29","29","ודברי דויד המלך הראשנים והאחרנים הנם כתובים על דברי שמואל הראה ועל דברי נתן הנביא ועל דברי גד החזה׃ ");
INSERT INTO heb_vpl VALUES ("R129_30","014_29_30","1CH","29","30","30","עם כל מלכותו וגבורתו והעתים אשר עברו עליו ועל ישראל ועל כל ממלכות הארצות׃ ");
INSERT INTO heb_vpl VALUES ("R21_1","015_1_1","2CH","1","1","1","ויתחזק שלמה בן דויד על מלכותו ויהוה אלהיו עמו ויגדלהו למעלה׃ ");
INSERT INTO heb_vpl VALUES ("R21_2","015_1_2","2CH","1","2","2","ויאמר שלמה לכל ישראל לשרי האלפים והמאות ולשפטים ולכל נשיא לכל ישראל ראשי האבות׃ ");
INSERT INTO heb_vpl VALUES ("R21_3","015_1_3","2CH","1","3","3","וילכו שלמה וכל הקהל עמו לבמה אשר בגבעון כי שם היה אהל מועד האלהים אשר עשה משה עבד יהוה במדבר׃ ");
INSERT INTO heb_vpl VALUES ("R21_4","015_1_4","2CH","1","4","4","אבל ארון האלהים העלה דויד מקרית יערים בהכין לו דויד כי נטה לו אהל בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R21_5","015_1_5","2CH","1","5","5","ומזבח הנחשת אשר עשה בצלאל בן אורי בן חור שם לפני משכן יהוה וידרשהו שלמה והקהל׃ ");
INSERT INTO heb_vpl VALUES ("R21_6","015_1_6","2CH","1","6","6","ויעל שלמה שם על מזבח הנחשת לפני יהוה אשר לאהל מועד ויעל עליו עלות אלף׃ ");
INSERT INTO heb_vpl VALUES ("R21_7","015_1_7","2CH","1","7","7","בלילה ההוא נראה אלהים לשלמה ויאמר לו שאל מה אתן לך׃ ");
INSERT INTO heb_vpl VALUES ("R21_8","015_1_8","2CH","1","8","8","ויאמר שלמה לאלהים אתה עשית עם דויד אבי חסד גדול והמלכתני תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R21_9","015_1_9","2CH","1","9","9","עתה יהוה אלהים יאמן דברך עם דויד אבי כי אתה המלכתני על עם רב כעפר הארץ׃ ");
INSERT INTO heb_vpl VALUES ("R21_10","015_1_10","2CH","1","10","10","עתה חכמה ומדע תן לי ואצאה לפני העם הזה ואבואה כי מי ישפט את עמך הזה הגדול׃ ");
INSERT INTO heb_vpl VALUES ("R21_11","015_1_11","2CH","1","11","11","ויאמר אלהים לשלמה יען אשר היתה זאת עם לבבך ולא שאלת עשר נכסים וכבוד ואת נפש שנאיך וגם ימים רבים לא שאלת ותשאל לך חכמה ומדע אשר תשפוט את עמי אשר המלכתיך עליו׃ ");
INSERT INTO heb_vpl VALUES ("R21_12","015_1_12","2CH","1","12","12","החכמה והמדע נתון לך ועשר ונכסים וכבוד אתן לך אשר לא היה כן למלכים אשר לפניך ואחריך לא יהיה כן׃ ");
INSERT INTO heb_vpl VALUES ("R21_13","015_1_13","2CH","1","13","13","ויבא שלמה לבמה אשר בגבעון ירושלם מלפני אהל מועד וימלך על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R21_14","015_1_14","2CH","1","14","14","ויאסף שלמה רכב ופרשים ויהי לו אלף וארבע מאות רכב ושנים עשר אלף פרשים ויניחם בערי הרכב ועם המלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R21_15","015_1_15","2CH","1","15","15","ויתן המלך את הכסף ואת הזהב בירושלם כאבנים ואת הארזים נתן כשקמים אשר בשפלה לרב׃ ");
INSERT INTO heb_vpl VALUES ("R21_16","015_1_16","2CH","1","16","16","ומוצא הסוסים אשר לשלמה ממצרים ומקוא סחרי המלך מקוא יקחו במחיר׃ ");
INSERT INTO heb_vpl VALUES ("R21_17","015_1_17","2CH","1","17","17","ויעלו ויוציאו ממצרים מרכבה בשש מאות כסף וסוס בחמשים ומאה וכן לכל מלכי החתים ומלכי ארם בידם יוציאו׃ ");
INSERT INTO heb_vpl VALUES ("R22_1","015_2_1","2CH","2","1","1","ויאמר שלמה לבנות בית לשם יהוה ובית למלכותו׃ ");
INSERT INTO heb_vpl VALUES ("R22_2","015_2_2","2CH","2","2","2","ויספר שלמה שבעים אלף איש סבל ושמונים אלף איש חצב בהר ומנצחים עליהם שלשת אלפים ושש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R22_3","015_2_3","2CH","2","3","3","וישלח שלמה אל חורם מלך צר לאמר כאשר עשית עם דויד אבי ותשלח לו ארזים לבנות לו בית לשבת בו׃ ");
INSERT INTO heb_vpl VALUES ("R22_4","015_2_4","2CH","2","4","4","הנה אני בונה בית לשם יהוה אלהי להקדיש לו להקטיר לפניו קטרת סמים ומערכת תמיד ועלות לבקר ולערב לשבתות ולחדשים ולמועדי יהוה אלהינו לעולם זאת על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R22_5","015_2_5","2CH","2","5","5","והבית אשר אני בונה גדול כי גדול אלהינו מכל האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R22_6","015_2_6","2CH","2","6","6","ומי יעצר כח לבנות לו בית כי השמים ושמי השמים לא יכלכלהו ומי אני אשר אבנה לו בית כי אם להקטיר לפניו׃ ");
INSERT INTO heb_vpl VALUES ("R22_7","015_2_7","2CH","2","7","7","ועתה שלח לי איש חכם לעשות בזהב ובכסף ובנחשת ובברזל ובארגון וכרמיל ותכלת וידע לפתח פתוחים עם החכמים אשר עמי ביהודה ובירושלם אשר הכין דויד אבי׃ ");
INSERT INTO heb_vpl VALUES ("R22_8","015_2_8","2CH","2","8","8","ושלח לי עצי ארזים ברושים ואלגומים מהלבנון כי אני ידעתי אשר עבדיך יודעים לכרות עצי לבנון והנה עבדי עם עבדיך׃ ");
INSERT INTO heb_vpl VALUES ("R22_9","015_2_9","2CH","2","9","9","ולהכין לי עצים לרב כי הבית אשר אני בונה גדול והפלא׃ ");
INSERT INTO heb_vpl VALUES ("R22_10","015_2_10","2CH","2","10","10","והנה לחטבים לכרתי העצים נתתי חטים מכות לעבדיך כרים עשרים אלף ושערים כרים עשרים אלף ויין בתים עשרים אלף ושמן בתים עשרים אלף׃ ");
INSERT INTO heb_vpl VALUES ("R22_11","015_2_11","2CH","2","11","11","ויאמר חורם מלך צר בכתב וישלח אל שלמה באהבת יהוה את עמו נתנך עליהם מלך׃ ");
INSERT INTO heb_vpl VALUES ("R22_12","015_2_12","2CH","2","12","12","ויאמר חורם ברוך יהוה אלהי ישראל אשר עשה את השמים ואת הארץ אשר נתן לדויד המלך בן חכם יודע שכל ובינה אשר יבנה בית ליהוה ובית למלכותו׃ ");
INSERT INTO heb_vpl VALUES ("R22_13","015_2_13","2CH","2","13","13","ועתה שלחתי איש חכם יודע בינה לחורם אבי׃ ");
INSERT INTO heb_vpl VALUES ("R22_14","015_2_14","2CH","2","14","14","בן אשה מן בנות דן ואביו איש צרי יודע לעשות בזהב ובכסף בנחשת בברזל באבנים ובעצים בארגמן בתכלת ובבוץ ובכרמיל ולפתח כל פתוח ולחשב כל מחשבת אשר ינתן לו עם חכמיך וחכמי אדני דויד אביך׃ ");
INSERT INTO heb_vpl VALUES ("R22_15","015_2_15","2CH","2","15","15","ועתה החטים והשערים השמן והיין אשר אמר אדני ישלח לעבדיו׃ ");
INSERT INTO heb_vpl VALUES ("R22_16","015_2_16","2CH","2","16","16","ואנחנו נכרת עצים מן הלבנון ככל צרכך ונביאם לך רפסדות על ים יפו ואתה תעלה אתם ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R22_17","015_2_17","2CH","2","17","17","ויספר שלמה כל האנשים הגירים אשר בארץ ישראל אחרי הספר אשר ספרם דויד אביו וימצאו מאה וחמשים אלף ושלשת אלפים ושש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R22_18","015_2_18","2CH","2","18","18","ויעש מהם שבעים אלף סבל ושמנים אלף חצב בהר ושלשת אלפים ושש מאות מנצחים להעביד את העם׃ ");
INSERT INTO heb_vpl VALUES ("R23_1","015_3_1","2CH","3","1","1","ויחל שלמה לבנות את בית יהוה בירושלם בהר המוריה אשר נראה לדויד אביהו אשר הכין במקום דויד בגרן ארנן היבוסי׃ ");
INSERT INTO heb_vpl VALUES ("R23_2","015_3_2","2CH","3","2","2","ויחל לבנות בחדש השני בשני בשנת ארבע למלכותו׃ ");
INSERT INTO heb_vpl VALUES ("R23_3","015_3_3","2CH","3","3","3","ואלה הוסד שלמה לבנות את בית האלהים הארך אמות במדה הראשונה אמות ששים ורחב אמות עשרים׃ ");
INSERT INTO heb_vpl VALUES ("R23_4","015_3_4","2CH","3","4","4","והאולם אשר על פני הארך על פני רחב הבית אמות עשרים והגבה מאה ועשרים ויצפהו מפנימה זהב טהור׃ ");
INSERT INTO heb_vpl VALUES ("R23_5","015_3_5","2CH","3","5","5","ואת הבית הגדול חפה עץ ברושים ויחפהו זהב טוב ויעל עליו תמרים ושרשרות׃ ");
INSERT INTO heb_vpl VALUES ("R23_6","015_3_6","2CH","3","6","6","ויצף את הבית אבן יקרה לתפארת והזהב זהב פרוים׃ ");
INSERT INTO heb_vpl VALUES ("R23_7","015_3_7","2CH","3","7","7","ויחף את הבית הקרות הספים וקירותיו ודלתותיו זהב ופתח כרובים על הקירות׃ ");
INSERT INTO heb_vpl VALUES ("R23_8","015_3_8","2CH","3","8","8","ויעש את בית קדש הקדשים ארכו על פני רחב הבית אמות עשרים ורחבו אמות עשרים ויחפהו זהב טוב לככרים שש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R23_9","015_3_9","2CH","3","9","9","ומשקל למסמרות לשקלים חמשים זהב והעליות חפה זהב׃ ");
INSERT INTO heb_vpl VALUES ("R23_10","015_3_10","2CH","3","10","10","ויעש בבית קדש הקדשים כרובים שנים מעשה צעצעים ויצפו אתם זהב׃ ");
INSERT INTO heb_vpl VALUES ("R23_11","015_3_11","2CH","3","11","11","וכנפי הכרובים ארכם אמות עשרים כנף האחד לאמות חמש מגעת לקיר הבית והכנף האחרת אמות חמש מגיע לכנף הכרוב האחר׃ ");
INSERT INTO heb_vpl VALUES ("R23_12","015_3_12","2CH","3","12","12","וכנף הכרוב האחד אמות חמש מגיע לקיר הבית והכנף האחרת אמות חמש דבקה לכנף הכרוב האחר׃ ");
INSERT INTO heb_vpl VALUES ("R23_13","015_3_13","2CH","3","13","13","כנפי הכרובים האלה פרשים אמות עשרים והם עמדים על רגליהם ופניהם לבית׃ ");
INSERT INTO heb_vpl VALUES ("R23_14","015_3_14","2CH","3","14","14","ויעש את הפרכת תכלת וארגמן וכרמיל ובוץ ויעל עליו כרובים׃ ");
INSERT INTO heb_vpl VALUES ("R23_15","015_3_15","2CH","3","15","15","ויעש לפני הבית עמודים שנים אמות שלשים וחמש ארך והצפת אשר על ראשו אמות חמש׃ ");
INSERT INTO heb_vpl VALUES ("R23_16","015_3_16","2CH","3","16","16","ויעש שרשרות בדביר ויתן על ראש העמדים ויעש רמונים מאה ויתן בשרשרות׃ ");
INSERT INTO heb_vpl VALUES ("R23_17","015_3_17","2CH","3","17","17","ויקם את העמודים על פני ההיכל אחד מימין ואחד מהשמאול ויקרא שם הימיני יכין ושם השמאלי בעז׃ ");
INSERT INTO heb_vpl VALUES ("R24_1","015_4_1","2CH","4","1","1","ויעש מזבח נחשת עשרים אמה ארכו ועשרים אמה רחבו ועשר אמות קומתו׃ ");
INSERT INTO heb_vpl VALUES ("R24_2","015_4_2","2CH","4","2","2","ויעש את הים מוצק עשר באמה משפתו אל שפתו עגול סביב וחמש באמה קומתו וקו שלשים באמה יסב אתו סביב׃ ");
INSERT INTO heb_vpl VALUES ("R24_3","015_4_3","2CH","4","3","3","ודמות בקרים תחת לו סביב סביב סובבים אתו עשר באמה מקיפים את הים סביב שנים טורים הבקר יצוקים במצקתו׃ ");
INSERT INTO heb_vpl VALUES ("R24_4","015_4_4","2CH","4","4","4","עומד על שנים עשר בקר שלשה פנים צפונה ושלושה פנים ימה ושלשה פנים נגבה ושלשה פנים מזרחה והים עליהם מלמעלה וכל אחריהם ביתה׃ ");
INSERT INTO heb_vpl VALUES ("R24_5","015_4_5","2CH","4","5","5","ועביו טפח ושפתו כמעשה שפת כוס פרח שושנה מחזיק בתים שלשת אלפים יכיל׃ ");
INSERT INTO heb_vpl VALUES ("R24_6","015_4_6","2CH","4","6","6","ויעש כיורים עשרה ויתן חמשה מימין וחמשה משמאול לרחצה בהם את מעשה העולה ידיחו בם והים לרחצה לכהנים בו׃ ");
INSERT INTO heb_vpl VALUES ("R24_7","015_4_7","2CH","4","7","7","ויעש את מנרות הזהב עשר כמשפטם ויתן בהיכל חמש מימין וחמש משמאול׃ ");
INSERT INTO heb_vpl VALUES ("R24_8","015_4_8","2CH","4","8","8","ויעש שלחנות עשרה וינח בהיכל חמשה מימין וחמשה משמאול ויעש מזרקי זהב מאה׃ ");
INSERT INTO heb_vpl VALUES ("R24_9","015_4_9","2CH","4","9","9","ויעש חצר הכהנים והעזרה הגדולה ודלתות לעזרה ודלתותיהם צפה נחשת׃ ");
INSERT INTO heb_vpl VALUES ("R24_10","015_4_10","2CH","4","10","10","ואת הים נתן מכתף הימנית קדמה ממול נגבה׃ ");
INSERT INTO heb_vpl VALUES ("R24_11","015_4_11","2CH","4","11","11","ויעש חורם את הסירות ואת היעים ואת המזרקות ויכל חירם לעשות את המלאכה אשר עשה למלך שלמה בבית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R24_12","015_4_12","2CH","4","12","12","עמודים שנים והגלות והכתרות על ראש העמודים שתים והשבכות שתים לכסות את שתי גלות הכתרות אשר על ראש העמודים׃ ");
INSERT INTO heb_vpl VALUES ("R24_13","015_4_13","2CH","4","13","13","ואת הרמונים ארבע מאות לשתי השבכות שנים טורים רמונים לשבכה האחת לכסות את שתי גלות הכתרות אשר על פני העמודים׃ ");
INSERT INTO heb_vpl VALUES ("R24_14","015_4_14","2CH","4","14","14","ואת המכנות עשה ואת הכירות עשה על המכנות׃ ");
INSERT INTO heb_vpl VALUES ("R24_15","015_4_15","2CH","4","15","15","את הים אחד ואת הבקר שנים עשר תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R24_16","015_4_16","2CH","4","16","16","ואת הסירות ואת היעים ואת המזלגות ואת כל כליהם עשה חורם אביו למלך שלמה לבית יהוה נחשת מרוק׃ ");
INSERT INTO heb_vpl VALUES ("R24_17","015_4_17","2CH","4","17","17","בככר הירדן יצקם המלך בעבי האדמה בין סכות ובין צרדתה׃ ");
INSERT INTO heb_vpl VALUES ("R24_18","015_4_18","2CH","4","18","18","ויעש שלמה כל הכלים האלה לרב מאד כי לא נחקר משקל הנחשת׃ ");
INSERT INTO heb_vpl VALUES ("R24_19","015_4_19","2CH","4","19","19","ויעש שלמה את כל הכלים אשר בית האלהים ואת מזבח הזהב ואת השלחנות ועליהם לחם הפנים׃ ");
INSERT INTO heb_vpl VALUES ("R24_20","015_4_20","2CH","4","20","20","ואת המנרות ונרתיהם לבערם כמשפט לפני הדביר זהב סגור׃ ");
INSERT INTO heb_vpl VALUES ("R24_21","015_4_21","2CH","4","21","21","והפרח והנרות והמלקחים זהב הוא מכלות זהב׃ ");
INSERT INTO heb_vpl VALUES ("R24_22","015_4_22","2CH","4","22","22","והמזמרות והמזרקות והכפות והמחתות זהב סגור ופתח הבית דלתותיו הפנימיות לקדש הקדשים ודלתי הבית להיכל זהב׃ ");
INSERT INTO heb_vpl VALUES ("R25_1","015_5_1","2CH","5","1","1","ותשלם כל המלאכה אשר עשה שלמה לבית יהוה ויבא שלמה את קדשי דויד אביו ואת הכסף ואת הזהב ואת כל הכלים נתן באצרות בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R25_2","015_5_2","2CH","5","2","2","אז יקהיל שלמה את זקני ישראל ואת כל ראשי המטות נשיאי האבות לבני ישראל אל ירושלם להעלות את ארון ברית יהוה מעיר דויד היא ציון׃ ");
INSERT INTO heb_vpl VALUES ("R25_3","015_5_3","2CH","5","3","3","ויקהלו אל המלך כל איש ישראל בחג הוא החדש השבעי׃ ");
INSERT INTO heb_vpl VALUES ("R25_4","015_5_4","2CH","5","4","4","ויבאו כל זקני ישראל וישאו הלוים את הארון׃ ");
INSERT INTO heb_vpl VALUES ("R25_5","015_5_5","2CH","5","5","5","ויעלו את הארון ואת אהל מועד ואת כל כלי הקדש אשר באהל העלו אתם הכהנים הלוים׃ ");
INSERT INTO heb_vpl VALUES ("R25_6","015_5_6","2CH","5","6","6","והמלך שלמה וכל עדת ישראל הנועדים עליו לפני הארון מזבחים צאן ובקר אשר לא יספרו ולא ימנו מרב׃ ");
INSERT INTO heb_vpl VALUES ("R25_7","015_5_7","2CH","5","7","7","ויביאו הכהנים את ארון ברית יהוה אל מקומו אל דביר הבית אל קדש הקדשים אל תחת כנפי הכרובים׃ ");
INSERT INTO heb_vpl VALUES ("R25_8","015_5_8","2CH","5","8","8","ויהיו הכרובים פרשים כנפים על מקום הארון ויכסו הכרובים על הארון ועל בדיו מלמעלה׃ ");
INSERT INTO heb_vpl VALUES ("R25_9","015_5_9","2CH","5","9","9","ויאריכו הבדים ויראו ראשי הבדים מן הארון על פני הדביר ולא יראו החוצה ויהי שם עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R25_10","015_5_10","2CH","5","10","10","אין בארון רק שני הלחות אשר נתן משה בחרב אשר כרת יהוה עם בני ישראל בצאתם ממצרים׃ ");
INSERT INTO heb_vpl VALUES ("R25_11","015_5_11","2CH","5","11","11","ויהי בצאת הכהנים מן הקדש כי כל הכהנים הנמצאים התקדשו אין לשמור למחלקות׃ ");
INSERT INTO heb_vpl VALUES ("R25_12","015_5_12","2CH","5","12","12","והלוים המשררים לכלם לאסף להימן לידתון ולבניהם ולאחיהם מלבשים בוץ במצלתים ובנבלים וכנרות עמדים מזרח למזבח ועמהם כהנים למאה ועשרים מחצררים בחצצרות׃ ");
INSERT INTO heb_vpl VALUES ("R25_13","015_5_13","2CH","5","13","13","ויהי כאחד למחצצרים ולמשררים להשמיע קול אחד להלל ולהדות ליהוה וכהרים קול בחצצרות ובמצלתים ובכלי השיר ובהלל ליהוה כי טוב כי לעולם חסדו והבית מלא ענן בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R25_14","015_5_14","2CH","5","14","14","ולא יכלו הכהנים לעמוד לשרת מפני הענן כי מלא כבוד יהוה את בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R26_1","015_6_1","2CH","6","1","1","אז אמר שלמה יהוה אמר לשכון בערפל׃ ");
INSERT INTO heb_vpl VALUES ("R26_2","015_6_2","2CH","6","2","2","ואני בניתי בית זבל לך ומכון לשבתך עולמים׃ ");
INSERT INTO heb_vpl VALUES ("R26_3","015_6_3","2CH","6","3","3","ויסב המלך את פניו ויברך את כל קהל ישראל וכל קהל ישראל עומד׃ ");
INSERT INTO heb_vpl VALUES ("R26_4","015_6_4","2CH","6","4","4","ויאמר ברוך יהוה אלהי ישראל אשר דבר בפיו את דויד אבי ובידיו מלא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R26_5","015_6_5","2CH","6","5","5","מן היום אשר הוצאתי את עמי מארץ מצרים לא בחרתי בעיר מכל שבטי ישראל לבנות בית להיות שמי שם ולא בחרתי באיש להיות נגיד על עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R26_6","015_6_6","2CH","6","6","6","ואבחר בירושלם להיות שמי שם ואבחר בדויד להיות על עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R26_7","015_6_7","2CH","6","7","7","ויהי עם לבב דויד אבי לבנות בית לשם יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R26_8","015_6_8","2CH","6","8","8","ויאמר יהוה אל דויד אבי יען אשר היה עם לבבך לבנות בית לשמי הטיבות כי היה עם לבבך׃ ");
INSERT INTO heb_vpl VALUES ("R26_9","015_6_9","2CH","6","9","9","רק אתה לא תבנה הבית כי בנך היוצא מחלציך הוא יבנה הבית לשמי׃ ");
INSERT INTO heb_vpl VALUES ("R26_10","015_6_10","2CH","6","10","10","ויקם יהוה את דברו אשר דבר ואקום תחת דויד אבי ואשב על כסא ישראל כאשר דבר יהוה ואבנה הבית לשם יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R26_11","015_6_11","2CH","6","11","11","ואשים שם את הארון אשר שם ברית יהוה אשר כרת עם בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R26_12","015_6_12","2CH","6","12","12","ויעמד לפני מזבח יהוה נגד כל קהל ישראל ויפרש כפיו׃ ");
INSERT INTO heb_vpl VALUES ("R26_13","015_6_13","2CH","6","13","13","כי עשה שלמה כיור נחשת ויתנהו בתוך העזרה חמש אמות ארכו וחמש אמות רחבו ואמות שלוש קומתו ויעמד עליו ויברך על ברכיו נגד כל קהל ישראל ויפרש כפיו השמימה׃ ");
INSERT INTO heb_vpl VALUES ("R26_14","015_6_14","2CH","6","14","14","ויאמר יהוה אלהי ישראל אין כמוך אלהים בשמים ובארץ שמר הברית והחסד לעבדיך ההלכים לפניך בכל לבם׃ ");
INSERT INTO heb_vpl VALUES ("R26_15","015_6_15","2CH","6","15","15","אשר שמרת לעבדך דויד אבי את אשר דברת לו ותדבר בפיך ובידך מלאת כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R26_16","015_6_16","2CH","6","16","16","ועתה יהוה אלהי ישראל שמר לעבדך דויד אבי את אשר דברת לו לאמר לא יכרת לך איש מלפני יושב על כסא ישראל רק אם ישמרו בניך את דרכם ללכת בתורתי כאשר הלכת לפני׃ ");
INSERT INTO heb_vpl VALUES ("R26_17","015_6_17","2CH","6","17","17","ועתה יהוה אלהי ישראל יאמן דברך אשר דברת לעבדך לדויד׃ ");
INSERT INTO heb_vpl VALUES ("R26_18","015_6_18","2CH","6","18","18","כי האמנם ישב אלהים את האדם על הארץ הנה שמים ושמי השמים לא יכלכלוך אף כי הבית הזה אשר בניתי׃ ");
INSERT INTO heb_vpl VALUES ("R26_19","015_6_19","2CH","6","19","19","ופנית אל תפלת עבדך ואל תחנתו יהוה אלהי לשמע אל הרנה ואל התפלה אשר עבדך מתפלל לפניך׃ ");
INSERT INTO heb_vpl VALUES ("R26_20","015_6_20","2CH","6","20","20","להיות עיניך פתחות אל הבית הזה יומם ולילה אל המקום אשר אמרת לשום שמך שם לשמוע אל התפלה אשר יתפלל עבדך אל המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R26_21","015_6_21","2CH","6","21","21","ושמעת אל תחנוני עבדך ועמך ישראל אשר יתפללו אל המקום הזה ואתה תשמע ממקום שבתך מן השמים ושמעת וסלחת׃ ");
INSERT INTO heb_vpl VALUES ("R26_22","015_6_22","2CH","6","22","22","אם יחטא איש לרעהו ונשא בו אלה להאלתו ובא אלה לפני מזבחך בבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("R26_23","015_6_23","2CH","6","23","23","ואתה תשמע מן השמים ועשית ושפטת את עבדיך להשיב לרשע לתת דרכו בראשו ולהצדיק צדיק לתת לו כצדקתו׃ ");
INSERT INTO heb_vpl VALUES ("R26_24","015_6_24","2CH","6","24","24","ואם ינגף עמך ישראל לפני אויב כי יחטאו לך ושבו והודו את שמך והתפללו והתחננו לפניך בבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("R26_25","015_6_25","2CH","6","25","25","ואתה תשמע מן השמים וסלחת לחטאת עמך ישראל והשיבותם אל האדמה אשר נתתה להם ולאבתיהם׃ ");
INSERT INTO heb_vpl VALUES ("R26_26","015_6_26","2CH","6","26","26","בהעצר השמים ולא יהיה מטר כי יחטאו לך והתפללו אל המקום הזה והודו את שמך מחטאתם ישובון כי תענם׃ ");
INSERT INTO heb_vpl VALUES ("R26_27","015_6_27","2CH","6","27","27","ואתה תשמע השמים וסלחת לחטאת עבדיך ועמך ישראל כי תורם אל הדרך הטובה אשר ילכו בה ונתתה מטר על ארצך אשר נתתה לעמך לנחלה׃ ");
INSERT INTO heb_vpl VALUES ("R26_28","015_6_28","2CH","6","28","28","רעב כי יהיה בארץ דבר כי יהיה שדפון וירקון ארבה וחסיל כי יהיה כי יצר לו אויביו בארץ שעריו כל נגע וכל מחלה׃ ");
INSERT INTO heb_vpl VALUES ("R26_29","015_6_29","2CH","6","29","29","כל תפלה כל תחנה אשר יהיה לכל האדם ולכל עמך ישראל אשר ידעו איש נגעו ומכאבו ופרש כפיו אל הבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("R26_30","015_6_30","2CH","6","30","30","ואתה תשמע מן השמים מכון שבתך וסלחת ונתתה לאיש ככל דרכיו אשר תדע את לבבו כי אתה לבדך ידעת את לבב בני האדם׃ ");
INSERT INTO heb_vpl VALUES ("R26_31","015_6_31","2CH","6","31","31","למען ייראוך ללכת בדרכיך כל הימים אשר הם חיים על פני האדמה אשר נתתה לאבתינו׃ ");
INSERT INTO heb_vpl VALUES ("R26_32","015_6_32","2CH","6","32","32","וגם אל הנכרי אשר לא מעמך ישראל הוא ובא מארץ רחוקה למען שמך הגדול וידך החזקה וזרועך הנטויה ובאו והתפללו אל הבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("R26_33","015_6_33","2CH","6","33","33","ואתה תשמע מן השמים ממכון שבתך ועשית ככל אשר יקרא אליך הנכרי למען ידעו כל עמי הארץ את שמך וליראה אתך כעמך ישראל ולדעת כי שמך נקרא על הבית הזה אשר בניתי׃ ");
INSERT INTO heb_vpl VALUES ("R26_34","015_6_34","2CH","6","34","34","כי יצא עמך למלחמה על אויביו בדרך אשר תשלחם והתפללו אליך דרך העיר הזאת אשר בחרת בה והבית אשר בניתי לשמך׃ ");
INSERT INTO heb_vpl VALUES ("R26_35","015_6_35","2CH","6","35","35","ושמעת מן השמים את תפלתם ואת תחנתם ועשית משפטם׃ ");
INSERT INTO heb_vpl VALUES ("R26_36","015_6_36","2CH","6","36","36","כי יחטאו לך כי אין אדם אשר לא יחטא ואנפת בם ונתתם לפני אויב ושבום שוביהם אל ארץ רחוקה או קרובה׃ ");
INSERT INTO heb_vpl VALUES ("R26_37","015_6_37","2CH","6","37","37","והשיבו אל לבבם בארץ אשר נשבו שם ושבו והתחננו אליך בארץ שבים לאמר חטאנו העוינו ורשענו׃ ");
INSERT INTO heb_vpl VALUES ("R26_38","015_6_38","2CH","6","38","38","ושבו אליך בכל לבם ובכל נפשם בארץ שבים אשר שבו אתם והתפללו דרך ארצם אשר נתתה לאבותם והעיר אשר בחרת ולבית אשר בניתי לשמך׃ ");
INSERT INTO heb_vpl VALUES ("R26_39","015_6_39","2CH","6","39","39","ושמעת מן השמים ממכון שבתך את תפלתם ואת תחנתיהם ועשית משפטם וסלחת לעמך אשר חטאו לך׃ ");
INSERT INTO heb_vpl VALUES ("R26_40","015_6_40","2CH","6","40","40","עתה אלהי יהיו נא עיניך פתחות ואזניך קשבות לתפלת המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R26_41","015_6_41","2CH","6","41","41","ועתה קומה יהוה אלהים לנוחך אתה וארון עזך כהניך יהוה אלהים ילבשו תשועה וחסידיך ישמחו בטוב׃ ");
INSERT INTO heb_vpl VALUES ("R26_42","015_6_42","2CH","6","42","42","יהוה אלהים אל תשב פני משיחיך זכרה לחסדי דויד עבדך׃ ");
INSERT INTO heb_vpl VALUES ("R27_1","015_7_1","2CH","7","1","1","וככלות שלמה להתפלל והאש ירדה מהשמים ותאכל העלה והזבחים וכבוד יהוה מלא את הבית׃ ");
INSERT INTO heb_vpl VALUES ("R27_2","015_7_2","2CH","7","2","2","ולא יכלו הכהנים לבוא אל בית יהוה כי מלא כבוד יהוה את בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R27_3","015_7_3","2CH","7","3","3","וכל בני ישראל ראים ברדת האש וכבוד יהוה על הבית ויכרעו אפים ארצה על הרצפה וישתחוו והודות ליהוה כי טוב כי לעולם חסדו׃ ");
INSERT INTO heb_vpl VALUES ("R27_4","015_7_4","2CH","7","4","4","והמלך וכל העם זבחים זבח לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R27_5","015_7_5","2CH","7","5","5","ויזבח המלך שלמה את זבח הבקר עשרים ושנים אלף וצאן מאה ועשרים אלף ויחנכו את בית האלהים המלך וכל העם׃ ");
INSERT INTO heb_vpl VALUES ("R27_6","015_7_6","2CH","7","6","6","והכהנים על משמרותם עמדים והלוים בכלי שיר יהוה אשר עשה דויד המלך להדות ליהוה כי לעולם חסדו בהלל דויד בידם והכהנים מחצצרים נגדם וכל ישראל עמדים׃ ");
INSERT INTO heb_vpl VALUES ("R27_7","015_7_7","2CH","7","7","7","ויקדש שלמה את תוך החצר אשר לפני בית יהוה כי עשה שם העלות ואת חלבי השלמים כי מזבח הנחשת אשר עשה שלמה לא יכול להכיל את העלה ואת המנחה ואת החלבים׃ ");
INSERT INTO heb_vpl VALUES ("R27_8","015_7_8","2CH","7","8","8","ויעש שלמה את החג בעת ההיא שבעת ימים וכל ישראל עמו קהל גדול מאד מלבוא חמת עד נחל מצרים׃ ");
INSERT INTO heb_vpl VALUES ("R27_9","015_7_9","2CH","7","9","9","ויעשו ביום השמיני עצרת כי חנכת המזבח עשו שבעת ימים והחג שבעת ימים׃ ");
INSERT INTO heb_vpl VALUES ("R27_10","015_7_10","2CH","7","10","10","וביום עשרים ושלשה לחדש השביעי שלח את העם לאהליהם שמחים וטובי לב על הטובה אשר עשה יהוה לדויד ולשלמה ולישראל עמו׃ ");
INSERT INTO heb_vpl VALUES ("R27_11","015_7_11","2CH","7","11","11","ויכל שלמה את בית יהוה ואת בית המלך ואת כל הבא על לב שלמה לעשות בבית יהוה ובביתו הצליח׃ ");
INSERT INTO heb_vpl VALUES ("R27_12","015_7_12","2CH","7","12","12","וירא יהוה אל שלמה בלילה ויאמר לו שמעתי את תפלתך ובחרתי במקום הזה לי לבית זבח׃ ");
INSERT INTO heb_vpl VALUES ("R27_13","015_7_13","2CH","7","13","13","הן אעצר השמים ולא יהיה מטר והן אצוה על חגב לאכול הארץ ואם אשלח דבר בעמי׃ ");
INSERT INTO heb_vpl VALUES ("R27_14","015_7_14","2CH","7","14","14","ויכנעו עמי אשר נקרא שמי עליהם ויתפללו ויבקשו פני וישבו מדרכיהם הרעים ואני אשמע מן השמים ואסלח לחטאתם וארפא את ארצם׃ ");
INSERT INTO heb_vpl VALUES ("R27_15","015_7_15","2CH","7","15","15","עתה עיני יהיו פתחות ואזני קשבות לתפלת המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R27_16","015_7_16","2CH","7","16","16","ועתה בחרתי והקדשתי את הבית הזה להיות שמי שם עד עולם והיו עיני ולבי שם כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("R27_17","015_7_17","2CH","7","17","17","ואתה אם תלך לפני כאשר הלך דויד אביך ולעשות ככל אשר צויתיך וחקי ומשפטי תשמור׃ ");
INSERT INTO heb_vpl VALUES ("R27_18","015_7_18","2CH","7","18","18","והקימותי את כסא מלכותך כאשר כרתי לדויד אביך לאמר לא יכרת לך איש מושל בישראל׃ ");
INSERT INTO heb_vpl VALUES ("R27_19","015_7_19","2CH","7","19","19","ואם תשובון אתם ועזבתם חקותי ומצותי אשר נתתי לפניכם והלכתם ועבדתם אלהים אחרים והשתחויתם להם׃ ");
INSERT INTO heb_vpl VALUES ("R27_20","015_7_20","2CH","7","20","20","ונתשתים מעל אדמתי אשר נתתי להם ואת הבית הזה אשר הקדשתי לשמי אשליך מעל פני ואתננו למשל ולשנינה בכל העמים׃ ");
INSERT INTO heb_vpl VALUES ("R27_21","015_7_21","2CH","7","21","21","והבית הזה אשר היה עליון לכל עבר עליו ישם ואמר במה עשה יהוה ככה לארץ הזאת ולבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("R27_22","015_7_22","2CH","7","22","22","ואמרו על אשר עזבו את יהוה אלהי אבתיהם אשר הוציאם מארץ מצרים ויחזיקו באלהים אחרים וישתחוו להם ויעבדום על כן הביא עליהם את כל הרעה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("R28_1","015_8_1","2CH","8","1","1","ויהי מקץ עשרים שנה אשר בנה שלמה את בית יהוה ואת ביתו׃ ");
INSERT INTO heb_vpl VALUES ("R28_2","015_8_2","2CH","8","2","2","והערים אשר נתן חורם לשלמה בנה שלמה אתם ויושב שם את בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R28_3","015_8_3","2CH","8","3","3","וילך שלמה חמת צובה ויחזק עליה׃ ");
INSERT INTO heb_vpl VALUES ("R28_4","015_8_4","2CH","8","4","4","ויבן את תדמר במדבר ואת כל ערי המסכנות אשר בנה בחמת׃ ");
INSERT INTO heb_vpl VALUES ("R28_5","015_8_5","2CH","8","5","5","ויבן את בית חורון העליון ואת בית חורון התחתון ערי מצור חומות דלתים ובריח׃ ");
INSERT INTO heb_vpl VALUES ("R28_6","015_8_6","2CH","8","6","6","ואת בעלת ואת כל ערי המסכנות אשר היו לשלמה ואת כל ערי הרכב ואת ערי הפרשים ואת כל חשק שלמה אשר חשק לבנות בירושלם ובלבנון ובכל ארץ ממשלתו׃ ");
INSERT INTO heb_vpl VALUES ("R28_7","015_8_7","2CH","8","7","7","כל העם הנותר מן החתי והאמרי והפרזי והחוי והיבוסי אשר לא מישראל המה׃ ");
INSERT INTO heb_vpl VALUES ("R28_8","015_8_8","2CH","8","8","8","מן בניהם אשר נותרו אחריהם בארץ אשר לא כלום בני ישראל ויעלם שלמה למס עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R28_9","015_8_9","2CH","8","9","9","ומן בני ישראל אשר לא נתן שלמה לעבדים למלאכתו כי המה אנשי מלחמה ושרי שלישיו ושרי רכבו ופרשיו׃ ");
INSERT INTO heb_vpl VALUES ("R28_10","015_8_10","2CH","8","10","10","ואלה שרי הנציבים אשר למלך שלמה חמשים ומאתים הרדים בעם׃ ");
INSERT INTO heb_vpl VALUES ("R28_11","015_8_11","2CH","8","11","11","ואת בת פרעה העלה שלמה מעיר דויד לבית אשר בנה לה כי אמר לא תשב אשה לי בבית דויד מלך ישראל כי קדש המה אשר באה אליהם ארון יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R28_12","015_8_12","2CH","8","12","12","אז העלה שלמה עלות ליהוה על מזבח יהוה אשר בנה לפני האולם׃ ");
INSERT INTO heb_vpl VALUES ("R28_13","015_8_13","2CH","8","13","13","ובדבר יום ביום להעלות כמצות משה לשבתות ולחדשים ולמועדות שלוש פעמים בשנה בחג המצות ובחג השבעות ובחג הסכות׃ ");
INSERT INTO heb_vpl VALUES ("R28_14","015_8_14","2CH","8","14","14","ויעמד כמשפט דויד אביו את מחלקות הכהנים על עבדתם והלוים על משמרותם להלל ולשרת נגד הכהנים לדבר יום ביומו והשוערים במחלקותם לשער ושער כי כן מצות דויד איש האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R28_15","015_8_15","2CH","8","15","15","ולא סרו מצות המלך על הכהנים והלוים לכל דבר ולאצרות׃ ");
INSERT INTO heb_vpl VALUES ("R28_16","015_8_16","2CH","8","16","16","ותכן כל מלאכת שלמה עד היום מוסד בית יהוה ועד כלתו שלם בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R28_17","015_8_17","2CH","8","17","17","אז הלך שלמה לעציון גבר ואל אילות על שפת הים בארץ אדום׃ ");
INSERT INTO heb_vpl VALUES ("R28_18","015_8_18","2CH","8","18","18","וישלח לו חורם ביד עבדיו אוניות ועבדים יודעי ים ויבאו עם עבדי שלמה אופירה ויקחו משם ארבע מאות וחמשים ככר זהב ויביאו אל המלך שלמה׃ ");
INSERT INTO heb_vpl VALUES ("R29_1","015_9_1","2CH","9","1","1","ומלכת שבא שמעה את שמע שלמה ותבוא לנסות את שלמה בחידות בירושלם בחיל כבד מאד וגמלים נשאים בשמים וזהב לרב ואבן יקרה ותבוא אל שלמה ותדבר עמו את כל אשר היה עם לבבה׃ ");
INSERT INTO heb_vpl VALUES ("R29_2","015_9_2","2CH","9","2","2","ויגד לה שלמה את כל דבריה ולא נעלם דבר משלמה אשר לא הגיד לה׃ ");
INSERT INTO heb_vpl VALUES ("R29_3","015_9_3","2CH","9","3","3","ותרא מלכת שבא את חכמת שלמה והבית אשר בנה׃ ");
INSERT INTO heb_vpl VALUES ("R29_4","015_9_4","2CH","9","4","4","ומאכל שלחנו ומושב עבדיו ומעמד משרתיו ומלבושיהם ומשקיו ומלבושיהם ועליתו אשר יעלה בית יהוה ולא היה עוד בה רוח׃ ");
INSERT INTO heb_vpl VALUES ("R29_5","015_9_5","2CH","9","5","5","ותאמר אל המלך אמת הדבר אשר שמעתי בארצי על דבריך ועל חכמתך׃ ");
INSERT INTO heb_vpl VALUES ("R29_6","015_9_6","2CH","9","6","6","ולא האמנתי לדבריהם עד אשר באתי ותראינה עיני והנה לא הגד לי חצי מרבית חכמתך יספת על השמועה אשר שמעתי׃ ");
INSERT INTO heb_vpl VALUES ("R29_7","015_9_7","2CH","9","7","7","אשרי אנשיך ואשרי עבדיך אלה העמדים לפניך תמיד ושמעים את חכמתך׃ ");
INSERT INTO heb_vpl VALUES ("R29_8","015_9_8","2CH","9","8","8","יהי יהוה אלהיך ברוך אשר חפץ בך לתתך על כסאו למלך ליהוה אלהיך באהבת אלהיך את ישראל להעמידו לעולם ויתנך עליהם למלך לעשות משפט וצדקה׃ ");
INSERT INTO heb_vpl VALUES ("R29_9","015_9_9","2CH","9","9","9","ותתן למלך מאה ועשרים ככר זהב ובשמים לרב מאד ואבן יקרה ולא היה כבשם ההוא אשר נתנה מלכת שבא למלך שלמה׃ ");
INSERT INTO heb_vpl VALUES ("R29_10","015_9_10","2CH","9","10","10","וגם עבדי חירם ועבדי שלמה אשר הביאו זהב מאופיר הביאו עצי אלגומים ואבן יקרה׃ ");
INSERT INTO heb_vpl VALUES ("R29_11","015_9_11","2CH","9","11","11","ויעש המלך את עצי האלגומים מסלות לבית יהוה ולבית המלך וכנרות ונבלים לשרים ולא נראו כהם לפנים בארץ יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R29_12","015_9_12","2CH","9","12","12","והמלך שלמה נתן למלכת שבא את כל חפצה אשר שאלה מלבד אשר הביאה אל המלך ותהפך ותלך לארצה היא ועבדיה׃ ");
INSERT INTO heb_vpl VALUES ("R29_13","015_9_13","2CH","9","13","13","ויהי משקל הזהב אשר בא לשלמה בשנה אחת שש מאות וששים ושש ככרי זהב׃ ");
INSERT INTO heb_vpl VALUES ("R29_14","015_9_14","2CH","9","14","14","לבד מאנשי התרים והסחרים מביאים וכל מלכי ערב ופחות הארץ מביאים זהב וכסף לשלמה׃ ");
INSERT INTO heb_vpl VALUES ("R29_15","015_9_15","2CH","9","15","15","ויעש המלך שלמה מאתים צנה זהב שחוט שש מאות זהב שחוט יעלה על הצנה האחת׃ ");
INSERT INTO heb_vpl VALUES ("R29_16","015_9_16","2CH","9","16","16","ושלש מאות מגנים זהב שחוט שלש מאות זהב יעלה על המגן האחת ויתנם המלך בבית יער הלבנון׃ ");
INSERT INTO heb_vpl VALUES ("R29_17","015_9_17","2CH","9","17","17","ויעש המלך כסא שן גדול ויצפהו זהב טהור׃ ");
INSERT INTO heb_vpl VALUES ("R29_18","015_9_18","2CH","9","18","18","ושש מעלות לכסא וכבש בזהב לכסא מאחזים וידות מזה ומזה על מקום השבת ושנים אריות עמדים אצל הידות׃ ");
INSERT INTO heb_vpl VALUES ("R29_19","015_9_19","2CH","9","19","19","ושנים עשר אריות עמדים שם על שש המעלות מזה ומזה לא נעשה כן לכל ממלכה׃ ");
INSERT INTO heb_vpl VALUES ("R29_20","015_9_20","2CH","9","20","20","וכל כלי משקה המלך שלמה זהב וכל כלי בית יער הלבנון זהב סגור אין כסף נחשב בימי שלמה למאומה׃ ");
INSERT INTO heb_vpl VALUES ("R29_21","015_9_21","2CH","9","21","21","כי אניות למלך הלכות תרשיש עם עבדי חורם אחת לשלוש שנים תבואנה אניות תרשיש נשאות זהב וכסף שנהבים וקופים ותוכיים׃ ");
INSERT INTO heb_vpl VALUES ("R29_22","015_9_22","2CH","9","22","22","ויגדל המלך שלמה מכל מלכי הארץ לעשר וחכמה׃ ");
INSERT INTO heb_vpl VALUES ("R29_23","015_9_23","2CH","9","23","23","וכל מלכי הארץ מבקשים את פני שלמה לשמע את חכמתו אשר נתן האלהים בלבו׃ ");
INSERT INTO heb_vpl VALUES ("R29_24","015_9_24","2CH","9","24","24","והם מביאים איש מנחתו כלי כסף וכלי זהב ושלמות נשק ובשמים סוסים ופרדים דבר שנה בשנה׃ ");
INSERT INTO heb_vpl VALUES ("R29_25","015_9_25","2CH","9","25","25","ויהי לשלמה ארבעת אלפים אריות סוסים ומרכבות ושנים עשר אלף פרשים ויניחם בערי הרכב ועם המלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R29_26","015_9_26","2CH","9","26","26","ויהי מושל בכל המלכים מן הנהר ועד ארץ פלשתים ועד גבול מצרים׃ ");
INSERT INTO heb_vpl VALUES ("R29_27","015_9_27","2CH","9","27","27","ויתן המלך את הכסף בירושלם כאבנים ואת הארזים נתן כשקמים אשר בשפלה לרב׃ ");
INSERT INTO heb_vpl VALUES ("R29_28","015_9_28","2CH","9","28","28","ומוציאים סוסים ממצרים לשלמה ומכל הארצות׃ ");
INSERT INTO heb_vpl VALUES ("R29_29","015_9_29","2CH","9","29","29","ושאר דברי שלמה הראשנים והאחרונים הלא הם כתובים על דברי נתן הנביא ועל נבואת אחיה השילוני ובחזות יעדי החזה על ירבעם בן נבט׃ ");
INSERT INTO heb_vpl VALUES ("R29_30","015_9_30","2CH","9","30","30","וימלך שלמה בירושלם על כל ישראל ארבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("R29_31","015_9_31","2CH","9","31","31","וישכב שלמה עם אבתיו ויקברהו בעיר דויד אביו וימלך רחבעם בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R210_1","015_10_1","2CH","10","1","1","וילך רחבעם שכמה כי שכם באו כל ישראל להמליך אתו׃ ");
INSERT INTO heb_vpl VALUES ("R210_2","015_10_2","2CH","10","2","2","ויהי כשמע ירבעם בן נבט והוא במצרים אשר ברח מפני שלמה המלך וישב ירבעם ממצרים׃ ");
INSERT INTO heb_vpl VALUES ("R210_3","015_10_3","2CH","10","3","3","וישלחו ויקראו לו ויבא ירבעם וכל ישראל וידברו אל רחבעם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R210_4","015_10_4","2CH","10","4","4","אביך הקשה את עלנו ועתה הקל מעבדת אביך הקשה ומעלו הכבד אשר נתן עלינו ונעבדך׃ ");
INSERT INTO heb_vpl VALUES ("R210_5","015_10_5","2CH","10","5","5","ויאמר אלהם עוד שלשת ימים ושובו אלי וילך העם׃ ");
INSERT INTO heb_vpl VALUES ("R210_6","015_10_6","2CH","10","6","6","ויועץ המלך רחבעם את הזקנים אשר היו עמדים לפני שלמה אביו בהיתו חי לאמר איך אתם נועצים להשיב לעם הזה דבר׃ ");
INSERT INTO heb_vpl VALUES ("R210_7","015_10_7","2CH","10","7","7","וידברו אליו לאמר אם תהיה לטוב להעם הזה ורציתם ודברת אלהם דברים טובים והיו לך עבדים כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("R210_8","015_10_8","2CH","10","8","8","ויעזב את עצת הזקנים אשר יעצהו ויועץ את הילדים אשר גדלו אתו העמדים לפניו׃ ");
INSERT INTO heb_vpl VALUES ("R210_9","015_10_9","2CH","10","9","9","ויאמר אלהם מה אתם נועצים ונשיב דבר את העם הזה אשר דברו אלי לאמר הקל מן העל אשר נתן אביך עלינו׃ ");
INSERT INTO heb_vpl VALUES ("R210_10","015_10_10","2CH","10","10","10","וידברו אתו הילדים אשר גדלו אתו לאמר כה תאמר לעם אשר דברו אליך לאמר אביך הכביד את עלנו ואתה הקל מעלינו כה תאמר אלהם קטני עבה ממתני אבי׃ ");
INSERT INTO heb_vpl VALUES ("R210_11","015_10_11","2CH","10","11","11","ועתה אבי העמיס עליכם על כבד ואני אסיף על עלכם אבי יסר אתכם בשוטים ואני בעקרבים׃ ");
INSERT INTO heb_vpl VALUES ("R210_12","015_10_12","2CH","10","12","12","ויבא ירבעם וכל העם אל רחבעם ביום השלשי כאשר דבר המלך לאמר שובו אלי ביום השלשי׃ ");
INSERT INTO heb_vpl VALUES ("R210_13","015_10_13","2CH","10","13","13","ויענם המלך קשה ויעזב המלך רחבעם את עצת הזקנים׃ ");
INSERT INTO heb_vpl VALUES ("R210_14","015_10_14","2CH","10","14","14","וידבר אלהם כעצת הילדים לאמר אכביד את עלכם ואני אסיף עליו אבי יסר אתכם בשוטים ואני בעקרבים׃ ");
INSERT INTO heb_vpl VALUES ("R210_15","015_10_15","2CH","10","15","15","ולא שמע המלך אל העם כי היתה נסבה מעם האלהים למען הקים יהוה את דברו אשר דבר ביד אחיהו השלוני אל ירבעם בן נבט׃ ");
INSERT INTO heb_vpl VALUES ("R210_16","015_10_16","2CH","10","16","16","וכל ישראל כי לא שמע המלך להם וישיבו העם את המלך לאמר מה לנו חלק בדויד ולא נחלה בבן ישי איש לאהליך ישראל עתה ראה ביתך דויד וילך כל ישראל לאהליו׃ ");
INSERT INTO heb_vpl VALUES ("R210_17","015_10_17","2CH","10","17","17","ובני ישראל הישבים בערי יהודה וימלך עליהם רחבעם׃ ");
INSERT INTO heb_vpl VALUES ("R210_18","015_10_18","2CH","10","18","18","וישלח המלך רחבעם את הדרם אשר על המס וירגמו בו בני ישראל אבן וימת והמלך רחבעם התאמץ לעלות במרכבה לנוס ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R210_19","015_10_19","2CH","10","19","19","ויפשעו ישראל בבית דויד עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("R211_1","015_11_1","2CH","11","1","1","ויבא רחבעם ירושלם ויקהל את בית יהודה ובנימן מאה ושמונים אלף בחור עשה מלחמה להלחם עם ישראל להשיב את הממלכה לרחבעם׃ ");
INSERT INTO heb_vpl VALUES ("R211_2","015_11_2","2CH","11","2","2","ויהי דבר יהוה אל שמעיהו איש האלהים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R211_3","015_11_3","2CH","11","3","3","אמר אל רחבעם בן שלמה מלך יהודה ואל כל ישראל ביהודה ובנימן לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R211_4","015_11_4","2CH","11","4","4","כה אמר יהוה לא תעלו ולא תלחמו עם אחיכם שובו איש לביתו כי מאתי נהיה הדבר הזה וישמעו את דברי יהוה וישבו מלכת אל ירבעם׃ ");
INSERT INTO heb_vpl VALUES ("R211_5","015_11_5","2CH","11","5","5","וישב רחבעם בירושלם ויבן ערים למצור ביהודה׃ ");
INSERT INTO heb_vpl VALUES ("R211_6","015_11_6","2CH","11","6","6","ויבן את בית לחם ואת עיטם ואת תקוע׃ ");
INSERT INTO heb_vpl VALUES ("R211_7","015_11_7","2CH","11","7","7","ואת בית צור ואת שוכו ואת עדלם׃ ");
INSERT INTO heb_vpl VALUES ("R211_8","015_11_8","2CH","11","8","8","ואת גת ואת מרשה ואת זיף׃ ");
INSERT INTO heb_vpl VALUES ("R211_9","015_11_9","2CH","11","9","9","ואת אדורים ואת לכיש ואת עזקה׃ ");
INSERT INTO heb_vpl VALUES ("R211_10","015_11_10","2CH","11","10","10","ואת צרעה ואת אילון ואת חברון אשר ביהודה ובבנימן ערי מצרות׃ ");
INSERT INTO heb_vpl VALUES ("R211_11","015_11_11","2CH","11","11","11","ויחזק את המצרות ויתן בהם נגידים ואצרות מאכל ושמן ויין׃ ");
INSERT INTO heb_vpl VALUES ("R211_12","015_11_12","2CH","11","12","12","ובכל עיר ועיר צנות ורמחים ויחזקם להרבה מאד ויהי לו יהודה ובנימן׃ ");
INSERT INTO heb_vpl VALUES ("R211_13","015_11_13","2CH","11","13","13","והכהנים והלוים אשר בכל ישראל התיצבו עליו מכל גבולם׃ ");
INSERT INTO heb_vpl VALUES ("R211_14","015_11_14","2CH","11","14","14","כי עזבו הלוים את מגרשיהם ואחזתם וילכו ליהודה ולירושלם כי הזניחם ירבעם ובניו מכהן ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("R211_15","015_11_15","2CH","11","15","15","ויעמד לו כהנים לבמות ולשעירים ולעגלים אשר עשה׃ ");
INSERT INTO heb_vpl VALUES ("R211_16","015_11_16","2CH","11","16","16","ואחריהם מכל שבטי ישראל הנתנים את לבבם לבקש את יהוה אלהי ישראל באו ירושלם לזבוח ליהוה אלהי אבותיהם׃ ");
INSERT INTO heb_vpl VALUES ("R211_17","015_11_17","2CH","11","17","17","ויחזקו את מלכות יהודה ויאמצו את רחבעם בן שלמה לשנים שלוש כי הלכו בדרך דויד ושלמה לשנים שלוש׃ ");
INSERT INTO heb_vpl VALUES ("R211_18","015_11_18","2CH","11","18","18","ויקח לו רחבעם אשה את מחלת בן ירימות בן דויד אביהיל בת אליאב בן ישי׃ ");
INSERT INTO heb_vpl VALUES ("R211_19","015_11_19","2CH","11","19","19","ותלד לו בנים את יעוש ואת שמריה ואת זהם׃ ");
INSERT INTO heb_vpl VALUES ("R211_20","015_11_20","2CH","11","20","20","ואחריה לקח את מעכה בת אבשלום ותלד לו את אביה ואת עתי ואת זיזא ואת שלמית׃ ");
INSERT INTO heb_vpl VALUES ("R211_21","015_11_21","2CH","11","21","21","ויאהב רחבעם את מעכה בת אבשלום מכל נשיו ופילגשיו כי נשים שמונה עשרה נשא ופילגשים ששים ויולד עשרים ושמונה בנים וששים בנות׃ ");
INSERT INTO heb_vpl VALUES ("R211_22","015_11_22","2CH","11","22","22","ויעמד לראש רחבעם את אביה בן מעכה לנגיד באחיו כי להמליכו׃ ");
INSERT INTO heb_vpl VALUES ("R211_23","015_11_23","2CH","11","23","23","ויבן ויפרץ מכל בניו לכל ארצות יהודה ובנימן לכל ערי המצרות ויתן להם המזון לרב וישאל המון נשים׃ ");
INSERT INTO heb_vpl VALUES ("R212_1","015_12_1","2CH","12","1","1","ויהי כהכין מלכות רחבעם וכחזקתו עזב את תורת יהוה וכל ישראל עמו׃ ");
INSERT INTO heb_vpl VALUES ("R212_2","015_12_2","2CH","12","2","2","ויהי בשנה החמישית למלך רחבעם עלה שישק מלך מצרים על ירושלם כי מעלו ביהוה׃ ");
INSERT INTO heb_vpl VALUES ("R212_3","015_12_3","2CH","12","3","3","באלף ומאתים רכב ובששים אלף פרשים ואין מספר לעם אשר באו עמו ממצרים לובים סכיים וכושים׃ ");
INSERT INTO heb_vpl VALUES ("R212_4","015_12_4","2CH","12","4","4","וילכד את ערי המצרות אשר ליהודה ויבא עד ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R212_5","015_12_5","2CH","12","5","5","ושמעיה הנביא בא אל רחבעם ושרי יהודה אשר נאספו אל ירושלם מפני שישק ויאמר להם כה אמר יהוה אתם עזבתם אתי ואף אני עזבתי אתכם ביד שישק׃ ");
INSERT INTO heb_vpl VALUES ("R212_6","015_12_6","2CH","12","6","6","ויכנעו שרי ישראל והמלך ויאמרו צדיק יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R212_7","015_12_7","2CH","12","7","7","ובראות יהוה כי נכנעו היה דבר יהוה אל שמעיה לאמר נכנעו לא אשחיתם ונתתי להם כמעט לפליטה ולא תתך חמתי בירושלם ביד שישק׃ ");
INSERT INTO heb_vpl VALUES ("R212_8","015_12_8","2CH","12","8","8","כי יהיו לו לעבדים וידעו עבודתי ועבודת ממלכות הארצות׃ ");
INSERT INTO heb_vpl VALUES ("R212_9","015_12_9","2CH","12","9","9","ויעל שישק מלך מצרים על ירושלם ויקח את אצרות בית יהוה ואת אצרות בית המלך את הכל לקח ויקח את מגני הזהב אשר עשה שלמה׃ ");
INSERT INTO heb_vpl VALUES ("R212_10","015_12_10","2CH","12","10","10","ויעש המלך רחבעם תחתיהם מגני נחשת והפקיד על יד שרי הרצים השמרים פתח בית המלך׃ ");
INSERT INTO heb_vpl VALUES ("R212_11","015_12_11","2CH","12","11","11","ויהי מדי בוא המלך בית יהוה באו הרצים ונשאום והשבום אל תא הרצים׃ ");
INSERT INTO heb_vpl VALUES ("R212_12","015_12_12","2CH","12","12","12","ובהכנעו שב ממנו אף יהוה ולא להשחית לכלה וגם ביהודה היה דברים טובים׃ ");
INSERT INTO heb_vpl VALUES ("R212_13","015_12_13","2CH","12","13","13","ויתחזק המלך רחבעם בירושלם וימלך כי בן ארבעים ואחת שנה רחבעם במלכו ושבע עשרה שנה מלך בירושלם העיר אשר בחר יהוה לשום את שמו שם מכל שבטי ישראל ושם אמו נעמה העמנית׃ ");
INSERT INTO heb_vpl VALUES ("R212_14","015_12_14","2CH","12","14","14","ויעש הרע כי לא הכין לבו לדרוש את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R212_15","015_12_15","2CH","12","15","15","ודברי רחבעם הראשנים והאחרונים הלא הם כתובים בדברי שמעיה הנביא ועדו החזה להתיחש ומלחמות רחבעם וירבעם כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("R212_16","015_12_16","2CH","12","16","16","וישכב רחבעם עם אבתיו ויקבר בעיר דויד וימלך אביה בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R213_1","015_13_1","2CH","13","1","1","בשנת שמונה עשרה למלך ירבעם וימלך אביה על יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R213_2","015_13_2","2CH","13","2","2","שלוש שנים מלך בירושלם ושם אמו מיכיהו בת אוריאל מן גבעה ומלחמה היתה בין אביה ובין ירבעם׃ ");
INSERT INTO heb_vpl VALUES ("R213_3","015_13_3","2CH","13","3","3","ויאסר אביה את המלחמה בחיל גבורי מלחמה ארבע מאות אלף איש בחור וירבעם ערך עמו מלחמה בשמונה מאות אלף איש בחור גבור חיל׃ ");
INSERT INTO heb_vpl VALUES ("R213_4","015_13_4","2CH","13","4","4","ויקם אביה מעל להר צמרים אשר בהר אפרים ויאמר שמעוני ירבעם וכל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R213_5","015_13_5","2CH","13","5","5","הלא לכם לדעת כי יהוה אלהי ישראל נתן ממלכה לדויד על ישראל לעולם לו ולבניו ברית מלח׃ ");
INSERT INTO heb_vpl VALUES ("R213_6","015_13_6","2CH","13","6","6","ויקם ירבעם בן נבט עבד שלמה בן דויד וימרד על אדניו׃ ");
INSERT INTO heb_vpl VALUES ("R213_7","015_13_7","2CH","13","7","7","ויקבצו עליו אנשים רקים בני בליעל ויתאמצו על רחבעם בן שלמה ורחבעם היה נער ורך לבב ולא התחזק לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("R213_8","015_13_8","2CH","13","8","8","ועתה אתם אמרים להתחזק לפני ממלכת יהוה ביד בני דויד ואתם המון רב ועמכם עגלי זהב אשר עשה לכם ירבעם לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("R213_9","015_13_9","2CH","13","9","9","הלא הדחתם את כהני יהוה את בני אהרן והלוים ותעשו לכם כהנים כעמי הארצות כל הבא למלא ידו בפר בן בקר ואילם שבעה והיה כהן ללא אלהים׃ ");
INSERT INTO heb_vpl VALUES ("R213_10","015_13_10","2CH","13","10","10","ואנחנו יהוה אלהינו ולא עזבנהו וכהנים משרתים ליהוה בני אהרן והלוים במלאכת׃ ");
INSERT INTO heb_vpl VALUES ("R213_11","015_13_11","2CH","13","11","11","ומקטרים ליהוה עלות בבקר בבקר ובערב בערב וקטרת סמים ומערכת לחם על השלחן הטהור ומנורת הזהב ונרתיה לבער בערב בערב כי שמרים אנחנו את משמרת יהוה אלהינו ואתם עזבתם אתו׃ ");
INSERT INTO heb_vpl VALUES ("R213_12","015_13_12","2CH","13","12","12","והנה עמנו בראש האלהים וכהניו וחצצרות התרועה להריע עליכם בני ישראל אל תלחמו עם יהוה אלהי אבתיכם כי לא תצליחו׃ ");
INSERT INTO heb_vpl VALUES ("R213_13","015_13_13","2CH","13","13","13","וירבעם הסב את המארב לבוא מאחריהם ויהיו לפני יהודה והמארב מאחריהם׃ ");
INSERT INTO heb_vpl VALUES ("R213_14","015_13_14","2CH","13","14","14","ויפנו יהודה והנה להם המלחמה פנים ואחור ויצעקו ליהוה והכהנים מחצצרים בחצצרות׃ ");
INSERT INTO heb_vpl VALUES ("R213_15","015_13_15","2CH","13","15","15","ויריעו איש יהודה ויהי בהריע איש יהודה והאלהים נגף את ירבעם וכל ישראל לפני אביה ויהודה׃ ");
INSERT INTO heb_vpl VALUES ("R213_16","015_13_16","2CH","13","16","16","וינוסו בני ישראל מפני יהודה ויתנם אלהים בידם׃ ");
INSERT INTO heb_vpl VALUES ("R213_17","015_13_17","2CH","13","17","17","ויכו בהם אביה ועמו מכה רבה ויפלו חללים מישראל חמש מאות אלף איש בחור׃ ");
INSERT INTO heb_vpl VALUES ("R213_18","015_13_18","2CH","13","18","18","ויכנעו בני ישראל בעת ההיא ויאמצו בני יהודה כי נשענו על יהוה אלהי אבותיהם׃ ");
INSERT INTO heb_vpl VALUES ("R213_19","015_13_19","2CH","13","19","19","וירדף אביה אחרי ירבעם וילכד ממנו ערים את בית אל ואת בנותיה ואת ישנה ואת בנותיה ואת עפרון ובנתיה׃ ");
INSERT INTO heb_vpl VALUES ("R213_20","015_13_20","2CH","13","20","20","ולא עצר כח ירבעם עוד בימי אביהו ויגפהו יהוה וימת׃ ");
INSERT INTO heb_vpl VALUES ("R213_21","015_13_21","2CH","13","21","21","ויתחזק אביהו וישא לו נשים ארבע עשרה ויולד עשרים ושנים בנים ושש עשרה בנות׃ ");
INSERT INTO heb_vpl VALUES ("R213_22","015_13_22","2CH","13","22","22","ויתר דברי אביה ודרכיו ודבריו כתובים במדרש הנביא עדו׃ ");
INSERT INTO heb_vpl VALUES ("R214_1","015_14_1","2CH","14","1","1","וישכב אביה עם אבתיו ויקברו אתו בעיר דויד וימלך אסא בנו תחתיו בימיו שקטה הארץ עשר שנים׃ ");
INSERT INTO heb_vpl VALUES ("R214_2","015_14_2","2CH","14","2","2","ויעש אסא הטוב והישר בעיני יהוה אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("R214_3","015_14_3","2CH","14","3","3","ויסר את מזבחות הנכר והבמות וישבר את המצבות ויגדע את האשרים׃ ");
INSERT INTO heb_vpl VALUES ("R214_4","015_14_4","2CH","14","4","4","ויאמר ליהודה לדרוש את יהוה אלהי אבותיהם ולעשות התורה והמצוה׃ ");
INSERT INTO heb_vpl VALUES ("R214_5","015_14_5","2CH","14","5","5","ויסר מכל ערי יהודה את הבמות ואת החמנים ותשקט הממלכה לפניו׃ ");
INSERT INTO heb_vpl VALUES ("R214_6","015_14_6","2CH","14","6","6","ויבן ערי מצורה ביהודה כי שקטה הארץ ואין עמו מלחמה בשנים האלה כי הניח יהוה לו׃ ");
INSERT INTO heb_vpl VALUES ("R214_7","015_14_7","2CH","14","7","7","ויאמר ליהודה נבנה את הערים האלה ונסב חומה ומגדלים דלתים ובריחים עודנו הארץ לפנינו כי דרשנו את יהוה אלהינו דרשנו וינח לנו מסביב ויבנו ויצליחו׃ ");
INSERT INTO heb_vpl VALUES ("R214_8","015_14_8","2CH","14","8","8","ויהי לאסא חיל נשא צנה ורמח מיהודה שלש מאות אלף ומבנימן נשאי מגן ודרכי קשת מאתים ושמונים אלף כל אלה גבורי חיל׃ ");
INSERT INTO heb_vpl VALUES ("R214_9","015_14_9","2CH","14","9","9","ויצא אליהם זרח הכושי בחיל אלף אלפים ומרכבות שלש מאות ויבא עד מרשה׃ ");
INSERT INTO heb_vpl VALUES ("R214_10","015_14_10","2CH","14","10","10","ויצא אסא לפניו ויערכו מלחמה בגיא צפתה למרשה׃ ");
INSERT INTO heb_vpl VALUES ("R214_11","015_14_11","2CH","14","11","11","ויקרא אסא אל יהוה אלהיו ויאמר יהוה אין עמך לעזור בין רב לאין כח עזרנו יהוה אלהינו כי עליך נשענו ובשמך באנו על ההמון הזה יהוה אלהינו אתה אל יעצר עמך אנוש׃ ");
INSERT INTO heb_vpl VALUES ("R214_12","015_14_12","2CH","14","12","12","ויגף יהוה את הכושים לפני אסא ולפני יהודה וינסו הכושים׃ ");
INSERT INTO heb_vpl VALUES ("R214_13","015_14_13","2CH","14","13","13","וירדפם אסא והעם אשר עמו עד לגרר ויפל מכושים לאין להם מחיה כי נשברו לפני יהוה ולפני מחנהו וישאו שלל הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("R214_14","015_14_14","2CH","14","14","14","ויכו את כל הערים סביבות גרר כי היה פחד יהוה עליהם ויבזו את כל הערים כי בזה רבה היתה בהם׃ ");
INSERT INTO heb_vpl VALUES ("R214_15","015_14_15","2CH","14","15","15","וגם אהלי מקנה הכו וישבו צאן לרב וגמלים וישבו ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R215_1","015_15_1","2CH","15","1","1","ועזריהו בן עודד היתה עליו רוח אלהים׃ ");
INSERT INTO heb_vpl VALUES ("R215_2","015_15_2","2CH","15","2","2","ויצא לפני אסא ויאמר לו שמעוני אסא וכל יהודה ובנימן יהוה עמכם בהיותכם עמו ואם תדרשהו ימצא לכם ואם תעזבהו יעזב אתכם׃ ");
INSERT INTO heb_vpl VALUES ("R215_3","015_15_3","2CH","15","3","3","וימים רבים לישראל ללא אלהי אמת וללא כהן מורה וללא תורה׃ ");
INSERT INTO heb_vpl VALUES ("R215_4","015_15_4","2CH","15","4","4","וישב בצר לו על יהוה אלהי ישראל ויבקשהו וימצא להם׃ ");
INSERT INTO heb_vpl VALUES ("R215_5","015_15_5","2CH","15","5","5","ובעתים ההם אין שלום ליוצא ולבא כי מהומת רבות על כל יושבי הארצות׃ ");
INSERT INTO heb_vpl VALUES ("R215_6","015_15_6","2CH","15","6","6","וכתתו גוי בגוי ועיר בעיר כי אלהים הממם בכל צרה׃ ");
INSERT INTO heb_vpl VALUES ("R215_7","015_15_7","2CH","15","7","7","ואתם חזקו ואל ירפו ידיכם כי יש שכר לפעלתכם׃ ");
INSERT INTO heb_vpl VALUES ("R215_8","015_15_8","2CH","15","8","8","וכשמע אסא הדברים האלה והנבואה עדד הנביא התחזק ויעבר השקוצים מכל ארץ יהודה ובנימן ומן הערים אשר לכד מהר אפרים ויחדש את מזבח יהוה אשר לפני אולם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R215_9","015_15_9","2CH","15","9","9","ויקבץ את כל יהודה ובנימן והגרים עמהם מאפרים ומנשה ומשמעון כי נפלו עליו מישראל לרב בראתם כי יהוה אלהיו עמו׃ ");
INSERT INTO heb_vpl VALUES ("R215_10","015_15_10","2CH","15","10","10","ויקבצו ירושלם בחדש השלישי לשנת חמש עשרה למלכות אסא׃ ");
INSERT INTO heb_vpl VALUES ("R215_11","015_15_11","2CH","15","11","11","ויזבחו ליהוה ביום ההוא מן השלל הביאו בקר שבע מאות וצאן שבעת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("R215_12","015_15_12","2CH","15","12","12","ויבאו בברית לדרוש את יהוה אלהי אבותיהם בכל לבבם ובכל נפשם׃ ");
INSERT INTO heb_vpl VALUES ("R215_13","015_15_13","2CH","15","13","13","וכל אשר לא ידרש ליהוה אלהי ישראל יומת למן קטן ועד גדול למאיש ועד אשה׃ ");
INSERT INTO heb_vpl VALUES ("R215_14","015_15_14","2CH","15","14","14","וישבעו ליהוה בקול גדול ובתרועה ובחצצרות ובשופרות׃ ");
INSERT INTO heb_vpl VALUES ("R215_15","015_15_15","2CH","15","15","15","וישמחו כל יהודה על השבועה כי בכל לבבם נשבעו ובכל רצונם בקשהו וימצא להם וינח יהוה להם מסביב׃ ");
INSERT INTO heb_vpl VALUES ("R215_16","015_15_16","2CH","15","16","16","וגם מעכה אם אסא המלך הסירה מגבירה אשר עשתה לאשרה מפלצת ויכרת אסא את מפלצתה וידק וישרף בנחל קדרון׃ ");
INSERT INTO heb_vpl VALUES ("R215_17","015_15_17","2CH","15","17","17","והבמות לא סרו מישראל רק לבב אסא היה שלם כל ימיו׃ ");
INSERT INTO heb_vpl VALUES ("R215_18","015_15_18","2CH","15","18","18","ויבא את קדשי אביו וקדשיו בית האלהים כסף וזהב וכלים׃ ");
INSERT INTO heb_vpl VALUES ("R215_19","015_15_19","2CH","15","19","19","ומלחמה לא היתה עד שנת שלשים וחמש למלכות אסא׃ ");
INSERT INTO heb_vpl VALUES ("R216_1","015_16_1","2CH","16","1","1","בשנת שלשים ושש למלכות אסא עלה בעשא מלך ישראל על יהודה ויבן את הרמה לבלתי תת יוצא ובא לאסא מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R216_2","015_16_2","2CH","16","2","2","ויצא אסא כסף וזהב מאצרות בית יהוה ובית המלך וישלח אל בן הדד מלך ארם היושב בדרמשק לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R216_3","015_16_3","2CH","16","3","3","ברית ביני ובינך ובין אבי ובין אביך הנה שלחתי לך כסף וזהב לך הפר בריתך את בעשא מלך ישראל ויעלה מעלי׃ ");
INSERT INTO heb_vpl VALUES ("R216_4","015_16_4","2CH","16","4","4","וישמע בן הדד אל המלך אסא וישלח את שרי החילים אשר לו אל ערי ישראל ויכו את עיון ואת דן ואת אבל מים ואת כל מסכנות ערי נפתלי׃ ");
INSERT INTO heb_vpl VALUES ("R216_5","015_16_5","2CH","16","5","5","ויהי כשמע בעשא ויחדל מבנות את הרמה וישבת את מלאכתו׃ ");
INSERT INTO heb_vpl VALUES ("R216_6","015_16_6","2CH","16","6","6","ואסא המלך לקח את כל יהודה וישאו את אבני הרמה ואת עציה אשר בנה בעשא ויבן בהם את גבע ואת המצפה׃ ");
INSERT INTO heb_vpl VALUES ("R216_7","015_16_7","2CH","16","7","7","ובעת ההיא בא חנני הראה אל אסא מלך יהודה ויאמר אליו בהשענך על מלך ארם ולא נשענת על יהוה אלהיך על כן נמלט חיל מלך ארם מידך׃ ");
INSERT INTO heb_vpl VALUES ("R216_8","015_16_8","2CH","16","8","8","הלא הכושים והלובים היו לחיל לרב לרכב ולפרשים להרבה מאד ובהשענך על יהוה נתנם בידך׃ ");
INSERT INTO heb_vpl VALUES ("R216_9","015_16_9","2CH","16","9","9","כי יהוה עיניו משטטות בכל הארץ להתחזק עם לבבם שלם אליו נסכלת על זאת כי מעתה יש עמך מלחמות׃ ");
INSERT INTO heb_vpl VALUES ("R216_10","015_16_10","2CH","16","10","10","ויכעס אסא אל הראה ויתנהו בית המהפכת כי בזעף עמו על זאת וירצץ אסא מן העם בעת ההיא׃ ");
INSERT INTO heb_vpl VALUES ("R216_11","015_16_11","2CH","16","11","11","והנה דברי אסא הראשונים והאחרונים הנם כתובים על ספר המלכים ליהודה וישראל׃ ");
INSERT INTO heb_vpl VALUES ("R216_12","015_16_12","2CH","16","12","12","ויחלא אסא בשנת שלושים ותשע למלכותו ברגליו עד למעלה חליו וגם בחליו לא דרש את יהוה כי ברפאים׃ ");
INSERT INTO heb_vpl VALUES ("R216_13","015_16_13","2CH","16","13","13","וישכב אסא עם אבתיו וימת בשנת ארבעים ואחת למלכו׃ ");
INSERT INTO heb_vpl VALUES ("R216_14","015_16_14","2CH","16","14","14","ויקברהו בקברתיו אשר כרה לו בעיר דויד וישכיבהו במשכב אשר מלא בשמים וזנים מרקחים במרקחת מעשה וישרפו לו שרפה גדולה עד למאד׃ ");
INSERT INTO heb_vpl VALUES ("R217_1","015_17_1","2CH","17","1","1","וימלך יהושפט בנו תחתיו ויתחזק על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R217_2","015_17_2","2CH","17","2","2","ויתן חיל בכל ערי יהודה הבצרות ויתן נציבים בארץ יהודה ובערי אפרים אשר לכד אסא אביו׃ ");
INSERT INTO heb_vpl VALUES ("R217_3","015_17_3","2CH","17","3","3","ויהי יהוה עם יהושפט כי הלך בדרכי דויד אביו הראשנים ולא דרש לבעלים׃ ");
INSERT INTO heb_vpl VALUES ("R217_4","015_17_4","2CH","17","4","4","כי לאלהי אביו דרש ובמצותיו הלך ולא כמעשה ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R217_5","015_17_5","2CH","17","5","5","ויכן יהוה את הממלכה בידו ויתנו כל יהודה מנחה ליהושפט ויהי לו עשר וכבוד לרב׃ ");
INSERT INTO heb_vpl VALUES ("R217_6","015_17_6","2CH","17","6","6","ויגבה לבו בדרכי יהוה ועוד הסיר את הבמות ואת האשרים מיהודה׃ ");
INSERT INTO heb_vpl VALUES ("R217_7","015_17_7","2CH","17","7","7","ובשנת שלוש למלכו שלח לשריו לבן חיל ולעבדיה ולזכריה ולנתנאל ולמיכיהו ללמד בערי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R217_8","015_17_8","2CH","17","8","8","ועמהם הלוים שמעיהו ונתניהו וזבדיהו ועשהאל ושמרימות ויהונתן ואדניהו וטוביהו וטוב אדוניה הלוים ועמהם אלישמע ויהורם הכהנים׃ ");
INSERT INTO heb_vpl VALUES ("R217_9","015_17_9","2CH","17","9","9","וילמדו ביהודה ועמהם ספר תורת יהוה ויסבו בכל ערי יהודה וילמדו בעם׃ ");
INSERT INTO heb_vpl VALUES ("R217_10","015_17_10","2CH","17","10","10","ויהי פחד יהוה על כל ממלכות הארצות אשר סביבות יהודה ולא נלחמו עם יהושפט׃ ");
INSERT INTO heb_vpl VALUES ("R217_11","015_17_11","2CH","17","11","11","ומן פלשתים מביאים ליהושפט מנחה וכסף משא גם הערביאים מביאים לו צאן אילים שבעת אלפים ושבע מאות ותישים שבעת אלפים ושבע מאות׃ ");
INSERT INTO heb_vpl VALUES ("R217_12","015_17_12","2CH","17","12","12","ויהי יהושפט הלך וגדל עד למעלה ויבן ביהודה בירניות וערי מסכנות׃ ");
INSERT INTO heb_vpl VALUES ("R217_13","015_17_13","2CH","17","13","13","ומלאכה רבה היה לו בערי יהודה ואנשי מלחמה גבורי חיל בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R217_14","015_17_14","2CH","17","14","14","ואלה פקדתם לבית אבותיהם ליהודה שרי אלפים עדנה השר ועמו גבורי חיל שלש מאות אלף׃ ");
INSERT INTO heb_vpl VALUES ("R217_15","015_17_15","2CH","17","15","15","ועל ידו יהוחנן השר ועמו מאתים ושמונים אלף׃ ");
INSERT INTO heb_vpl VALUES ("R217_16","015_17_16","2CH","17","16","16","ועל ידו עמסיה בן זכרי המתנדב ליהוה ועמו מאתים אלף גבור חיל׃ ");
INSERT INTO heb_vpl VALUES ("R217_17","015_17_17","2CH","17","17","17","ומן בנימן גבור חיל אלידע ועמו נשקי קשת ומגן מאתים אלף׃ ");
INSERT INTO heb_vpl VALUES ("R217_18","015_17_18","2CH","17","18","18","ועל ידו יהוזבד ועמו מאה ושמונים אלף חלוצי צבא׃ ");
INSERT INTO heb_vpl VALUES ("R217_19","015_17_19","2CH","17","19","19","אלה המשרתים את המלך מלבד אשר נתן המלך בערי המבצר בכל יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R218_1","015_18_1","2CH","18","1","1","ויהי ליהושפט עשר וכבוד לרב ויתחתן לאחאב׃ ");
INSERT INTO heb_vpl VALUES ("R218_2","015_18_2","2CH","18","2","2","וירד לקץ שנים אל אחאב לשמרון ויזבח לו אחאב צאן ובקר לרב ולעם אשר עמו ויסיתהו לעלות אל רמות גלעד׃ ");
INSERT INTO heb_vpl VALUES ("R218_3","015_18_3","2CH","18","3","3","ויאמר אחאב מלך ישראל אל יהושפט מלך יהודה התלך עמי רמת גלעד ויאמר לו כמוני כמוך וכעמך עמי ועמך במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("R218_4","015_18_4","2CH","18","4","4","ויאמר יהושפט אל מלך ישראל דרש נא כיום את דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R218_5","015_18_5","2CH","18","5","5","ויקבץ מלך ישראל את הנבאים ארבע מאות איש ויאמר אלהם הנלך אל רמת גלעד למלחמה אם אחדל ויאמרו עלה ויתן האלהים ביד המלך׃ ");
INSERT INTO heb_vpl VALUES ("R218_6","015_18_6","2CH","18","6","6","ויאמר יהושפט האין פה נביא ליהוה עוד ונדרשה מאתו׃ ");
INSERT INTO heb_vpl VALUES ("R218_7","015_18_7","2CH","18","7","7","ויאמר מלך ישראל אל יהושפט עוד איש אחד לדרוש את יהוה מאתו ואני שנאתיהו כי איננו מתנבא עלי לטובה כי כל ימיו לרעה הוא מיכיהו בן ימלא ויאמר יהושפט אל יאמר המלך כן׃ ");
INSERT INTO heb_vpl VALUES ("R218_8","015_18_8","2CH","18","8","8","ויקרא מלך ישראל אל סריס אחד ויאמר מהר מיכהו בן ימלא׃ ");
INSERT INTO heb_vpl VALUES ("R218_9","015_18_9","2CH","18","9","9","ומלך ישראל ויהושפט מלך יהודה יושבים איש על כסאו מלבשים בגדים וישבים בגרן פתח שער שמרון וכל הנביאים מתנבאים לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("R218_10","015_18_10","2CH","18","10","10","ויעש לו צדקיהו בן כנענה קרני ברזל ויאמר כה אמר יהוה באלה תנגח את ארם עד כלותם׃ ");
INSERT INTO heb_vpl VALUES ("R218_11","015_18_11","2CH","18","11","11","וכל הנבאים נבאים כן לאמר עלה רמת גלעד והצלח ונתן יהוה ביד המלך׃ ");
INSERT INTO heb_vpl VALUES ("R218_12","015_18_12","2CH","18","12","12","והמלאך אשר הלך לקרא למיכיהו דבר אליו לאמר הנה דברי הנבאים פה אחד טוב אל המלך ויהי נא דברך כאחד מהם ודברת טוב׃ ");
INSERT INTO heb_vpl VALUES ("R218_13","015_18_13","2CH","18","13","13","ויאמר מיכיהו חי יהוה כי את אשר יאמר אלהי אתו אדבר׃ ");
INSERT INTO heb_vpl VALUES ("R218_14","015_18_14","2CH","18","14","14","ויבא אל המלך ויאמר המלך אליו מיכה הנלך אל רמת גלעד למלחמה אם אחדל ויאמר עלו והצליחו וינתנו בידכם׃ ");
INSERT INTO heb_vpl VALUES ("R218_15","015_18_15","2CH","18","15","15","ויאמר אליו המלך עד כמה פעמים אני משביעך אשר לא תדבר אלי רק אמת בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R218_16","015_18_16","2CH","18","16","16","ויאמר ראיתי את כל ישראל נפוצים על ההרים כצאן אשר אין להן רעה ויאמר יהוה לא אדנים לאלה ישובו איש לביתו בשלום׃ ");
INSERT INTO heb_vpl VALUES ("R218_17","015_18_17","2CH","18","17","17","ויאמר מלך ישראל אל יהושפט הלא אמרתי אליך לא יתנבא עלי טוב כי אם לרע׃ ");
INSERT INTO heb_vpl VALUES ("R218_18","015_18_18","2CH","18","18","18","ויאמר לכן שמעו דבר יהוה ראיתי את יהוה יושב על כסאו וכל צבא השמים עמדים על ימינו ושמאלו׃ ");
INSERT INTO heb_vpl VALUES ("R218_19","015_18_19","2CH","18","19","19","ויאמר יהוה מי יפתה את אחאב מלך ישראל ויעל ויפל ברמות גלעד ויאמר זה אמר ככה וזה אמר ככה׃ ");
INSERT INTO heb_vpl VALUES ("R218_20","015_18_20","2CH","18","20","20","ויצא הרוח ויעמד לפני יהוה ויאמר אני אפתנו ויאמר יהוה אליו במה׃ ");
INSERT INTO heb_vpl VALUES ("R218_21","015_18_21","2CH","18","21","21","ויאמר אצא והייתי לרוח שקר בפי כל נביאיו ויאמר תפתה וגם תוכל צא ועשה כן׃ ");
INSERT INTO heb_vpl VALUES ("R218_22","015_18_22","2CH","18","22","22","ועתה הנה נתן יהוה רוח שקר בפי נביאיך אלה ויהוה דבר עליך רעה׃ ");
INSERT INTO heb_vpl VALUES ("R218_23","015_18_23","2CH","18","23","23","ויגש צדקיהו בן כנענה ויך את מיכיהו על הלחי ויאמר אי זה הדרך עבר רוח יהוה מאתי לדבר אתך׃ ");
INSERT INTO heb_vpl VALUES ("R218_24","015_18_24","2CH","18","24","24","ויאמר מיכיהו הנך ראה ביום ההוא אשר תבוא חדר בחדר להחבא׃ ");
INSERT INTO heb_vpl VALUES ("R218_25","015_18_25","2CH","18","25","25","ויאמר מלך ישראל קחו את מיכיהו והשיבהו אל אמון שר העיר ואל יואש בן המלך׃ ");
INSERT INTO heb_vpl VALUES ("R218_26","015_18_26","2CH","18","26","26","ואמרתם כה אמר המלך שימו זה בית הכלא והאכלהו לחם לחץ ומים לחץ עד שובי בשלום׃ ");
INSERT INTO heb_vpl VALUES ("R218_27","015_18_27","2CH","18","27","27","ויאמר מיכיהו אם שוב תשוב בשלום לא דבר יהוה בי ויאמר שמעו עמים כלם׃ ");
INSERT INTO heb_vpl VALUES ("R218_28","015_18_28","2CH","18","28","28","ויעל מלך ישראל ויהושפט מלך יהודה אל רמת גלעד׃ ");
INSERT INTO heb_vpl VALUES ("R218_29","015_18_29","2CH","18","29","29","ויאמר מלך ישראל אל יהושפט התחפש ובוא במלחמה ואתה לבש בגדיך ויתחפש מלך ישראל ויבאו במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("R218_30","015_18_30","2CH","18","30","30","ומלך ארם צוה את שרי הרכב אשר לו לאמר לא תלחמו את הקטן את הגדול כי אם את מלך ישראל לבדו׃ ");
INSERT INTO heb_vpl VALUES ("R218_31","015_18_31","2CH","18","31","31","ויהי כראות שרי הרכב את יהושפט והמה אמרו מלך ישראל הוא ויסבו עליו להלחם ויזעק יהושפט ויהוה עזרו ויסיתם אלהים ממנו׃ ");
INSERT INTO heb_vpl VALUES ("R218_32","015_18_32","2CH","18","32","32","ויהי כראות שרי הרכב כי לא היה מלך ישראל וישבו מאחריו׃ ");
INSERT INTO heb_vpl VALUES ("R218_33","015_18_33","2CH","18","33","33","ואיש משך בקשת לתמו ויך את מלך ישראל בין הדבקים ובין השרין ויאמר לרכב הפך ידיך והוצאתני מן המחנה כי החליתי׃ ");
INSERT INTO heb_vpl VALUES ("R218_34","015_18_34","2CH","18","34","34","ותעל המלחמה ביום ההוא ומלך ישראל היה מעמיד במרכבה נכח ארם עד הערב וימת לעת בוא השמש׃ ");
INSERT INTO heb_vpl VALUES ("R219_1","015_19_1","2CH","19","1","1","וישב יהושפט מלך יהודה אל ביתו בשלום לירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R219_2","015_19_2","2CH","19","2","2","ויצא אל פניו יהוא בן חנני החזה ויאמר אל המלך יהושפט הלרשע לעזר ולשנאי יהוה תאהב ובזאת עליך קצף מלפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R219_3","015_19_3","2CH","19","3","3","אבל דברים טובים נמצאו עמך כי בערת האשרות מן הארץ והכינות לבבך לדרש האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R219_4","015_19_4","2CH","19","4","4","וישב יהושפט בירושלם וישב ויצא בעם מבאר שבע עד הר אפרים וישיבם אל יהוה אלהי אבותיהם׃ ");
INSERT INTO heb_vpl VALUES ("R219_5","015_19_5","2CH","19","5","5","ויעמד שפטים בארץ בכל ערי יהודה הבצרות לעיר ועיר׃ ");
INSERT INTO heb_vpl VALUES ("R219_6","015_19_6","2CH","19","6","6","ויאמר אל השפטים ראו מה אתם עשים כי לא לאדם תשפטו כי ליהוה ועמכם בדבר משפט׃ ");
INSERT INTO heb_vpl VALUES ("R219_7","015_19_7","2CH","19","7","7","ועתה יהי פחד יהוה עליכם שמרו ועשו כי אין עם יהוה אלהינו עולה ומשא פנים ומקח שחד׃ ");
INSERT INTO heb_vpl VALUES ("R219_8","015_19_8","2CH","19","8","8","וגם בירושלם העמיד יהושפט מן הלוים והכהנים ומראשי האבות לישראל למשפט יהוה ולריב וישבו ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R219_9","015_19_9","2CH","19","9","9","ויצו עליהם לאמר כה תעשון ביראת יהוה באמונה ובלבב שלם׃ ");
INSERT INTO heb_vpl VALUES ("R219_10","015_19_10","2CH","19","10","10","וכל ריב אשר יבוא עליכם מאחיכם הישבים בעריהם בין דם לדם בין תורה למצוה לחקים ולמשפטים והזהרתם אתם ולא יאשמו ליהוה והיה קצף עליכם ועל אחיכם כה תעשון ולא תאשמו׃ ");
INSERT INTO heb_vpl VALUES ("R219_11","015_19_11","2CH","19","11","11","והנה אמריהו כהן הראש עליכם לכל דבר יהוה וזבדיהו בן ישמעאל הנגיד לבית יהודה לכל דבר המלך ושטרים הלוים לפניכם חזקו ועשו ויהי יהוה עם הטוב׃ ");
INSERT INTO heb_vpl VALUES ("R220_1","015_20_1","2CH","20","1","1","ויהי אחריכן באו בני מואב ובני עמון ועמהם מהעמונים על יהושפט למלחמה׃ ");
INSERT INTO heb_vpl VALUES ("R220_2","015_20_2","2CH","20","2","2","ויבאו ויגידו ליהושפט לאמר בא עליך המון רב מעבר לים מארם והנם בחצצון תמר היא עין גדי׃ ");
INSERT INTO heb_vpl VALUES ("R220_3","015_20_3","2CH","20","3","3","וירא ויתן יהושפט את פניו לדרוש ליהוה ויקרא צום על כל יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R220_4","015_20_4","2CH","20","4","4","ויקבצו יהודה לבקש מיהוה גם מכל ערי יהודה באו לבקש את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R220_5","015_20_5","2CH","20","5","5","ויעמד יהושפט בקהל יהודה וירושלם בבית יהוה לפני החצר החדשה׃ ");
INSERT INTO heb_vpl VALUES ("R220_6","015_20_6","2CH","20","6","6","ויאמר יהוה אלהי אבתינו הלא אתה הוא אלהים בשמים ואתה מושל בכל ממלכות הגוים ובידך כח וגבורה ואין עמך להתיצב׃ ");
INSERT INTO heb_vpl VALUES ("R220_7","015_20_7","2CH","20","7","7","הלא אתה אלהינו הורשת את ישבי הארץ הזאת מלפני עמך ישראל ותתנה לזרע אברהם אהבך לעולם׃ ");
INSERT INTO heb_vpl VALUES ("R220_8","015_20_8","2CH","20","8","8","וישבו בה ויבנו לך בה מקדש לשמך לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R220_9","015_20_9","2CH","20","9","9","אם תבוא עלינו רעה חרב שפוט ודבר ורעב נעמדה לפני הבית הזה ולפניך כי שמך בבית הזה ונזעק אליך מצרתנו ותשמע ותושיע׃ ");
INSERT INTO heb_vpl VALUES ("R220_10","015_20_10","2CH","20","10","10","ועתה הנה בני עמון ומואב והר שעיר אשר לא נתתה לישראל לבוא בהם בבאם מארץ מצרים כי סרו מעליהם ולא השמידום׃ ");
INSERT INTO heb_vpl VALUES ("R220_11","015_20_11","2CH","20","11","11","והנה הם גמלים עלינו לבוא לגרשנו מירשתך אשר הורשתנו׃ ");
INSERT INTO heb_vpl VALUES ("R220_12","015_20_12","2CH","20","12","12","אלהינו הלא תשפט בם כי אין בנו כח לפני ההמון הרב הזה הבא עלינו ואנחנו לא נדע מה נעשה כי עליך עינינו׃ ");
INSERT INTO heb_vpl VALUES ("R220_13","015_20_13","2CH","20","13","13","וכל יהודה עמדים לפני יהוה גם טפם נשיהם ובניהם׃ ");
INSERT INTO heb_vpl VALUES ("R220_14","015_20_14","2CH","20","14","14","ויחזיאל בן זכריהו בן בניה בן יעיאל בן מתניה הלוי מן בני אסף היתה עליו רוח יהוה בתוך הקהל׃ ");
INSERT INTO heb_vpl VALUES ("R220_15","015_20_15","2CH","20","15","15","ויאמר הקשיבו כל יהודה וישבי ירושלם והמלך יהושפט כה אמר יהוה לכם אתם אל תיראו ואל תחתו מפני ההמון הרב הזה כי לא לכם המלחמה כי לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("R220_16","015_20_16","2CH","20","16","16","מחר רדו עליהם הנם עלים במעלה הציץ ומצאתם אתם בסוף הנחל פני מדבר ירואל׃ ");
INSERT INTO heb_vpl VALUES ("R220_17","015_20_17","2CH","20","17","17","לא לכם להלחם בזאת התיצבו עמדו וראו את ישועת יהוה עמכם יהודה וירושלם אל תיראו ואל תחתו מחר צאו לפניהם ויהוה עמכם׃ ");
INSERT INTO heb_vpl VALUES ("R220_18","015_20_18","2CH","20","18","18","ויקד יהושפט אפים ארצה וכל יהודה וישבי ירושלם נפלו לפני יהוה להשתחות ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("R220_19","015_20_19","2CH","20","19","19","ויקמו הלוים מן בני הקהתים ומן בני הקרחים להלל ליהוה אלהי ישראל בקול גדול למעלה׃ ");
INSERT INTO heb_vpl VALUES ("R220_20","015_20_20","2CH","20","20","20","וישכימו בבקר ויצאו למדבר תקוע ובצאתם עמד יהושפט ויאמר שמעוני יהודה וישבי ירושלם האמינו ביהוה אלהיכם ותאמנו האמינו בנביאיו והצליחו׃ ");
INSERT INTO heb_vpl VALUES ("R220_21","015_20_21","2CH","20","21","21","ויועץ אל העם ויעמד משררים ליהוה ומהללים להדרת קדש בצאת לפני החלוץ ואמרים הודו ליהוה כי לעולם חסדו׃ ");
INSERT INTO heb_vpl VALUES ("R220_22","015_20_22","2CH","20","22","22","ובעת החלו ברנה ותהלה נתן יהוה מארבים על בני עמון מואב והר שעיר הבאים ליהודה וינגפו׃ ");
INSERT INTO heb_vpl VALUES ("R220_23","015_20_23","2CH","20","23","23","ויעמדו בני עמון ומואב על ישבי הר שעיר להחרים ולהשמיד וככלותם ביושבי שעיר עזרו איש ברעהו למשחית׃ ");
INSERT INTO heb_vpl VALUES ("R220_24","015_20_24","2CH","20","24","24","ויהודה בא על המצפה למדבר ויפנו אל ההמון והנם פגרים נפלים ארצה ואין פליטה׃ ");
INSERT INTO heb_vpl VALUES ("R220_25","015_20_25","2CH","20","25","25","ויבא יהושפט ועמו לבז את שללם וימצאו בהם לרב ורכוש ופגרים וכלי חמדות וינצלו להם לאין משא ויהיו ימים שלושה בזזים את השלל כי רב הוא׃ ");
INSERT INTO heb_vpl VALUES ("R220_26","015_20_26","2CH","20","26","26","וביום הרבעי נקהלו לעמק ברכה כי שם ברכו את יהוה על כן קראו את שם המקום ההוא עמק ברכה עד היום׃ ");
INSERT INTO heb_vpl VALUES ("R220_27","015_20_27","2CH","20","27","27","וישבו כל איש יהודה וירושלם ויהושפט בראשם לשוב אל ירושלם בשמחה כי שמחם יהוה מאויביהם׃ ");
INSERT INTO heb_vpl VALUES ("R220_28","015_20_28","2CH","20","28","28","ויבאו ירושלם בנבלים ובכנרות ובחצצרות אל בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R220_29","015_20_29","2CH","20","29","29","ויהי פחד אלהים על כל ממלכות הארצות בשמעם כי נלחם יהוה עם אויבי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R220_30","015_20_30","2CH","20","30","30","ותשקט מלכות יהושפט וינח לו אלהיו מסביב׃ ");
INSERT INTO heb_vpl VALUES ("R220_31","015_20_31","2CH","20","31","31","וימלך יהושפט על יהודה בן שלשים וחמש שנה במלכו ועשרים וחמש שנה מלך בירושלם ושם אמו עזובה בת שלחי׃ ");
INSERT INTO heb_vpl VALUES ("R220_32","015_20_32","2CH","20","32","32","וילך בדרך אביו אסא ולא סר ממנה לעשות הישר בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R220_33","015_20_33","2CH","20","33","33","אך הבמות לא סרו ועוד העם לא הכינו לבבם לאלהי אבתיהם׃ ");
INSERT INTO heb_vpl VALUES ("R220_34","015_20_34","2CH","20","34","34","ויתר דברי יהושפט הראשנים והאחרנים הנם כתובים בדברי יהוא בן חנני אשר העלה על ספר מלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R220_35","015_20_35","2CH","20","35","35","ואחריכן אתחבר יהושפט מלך יהודה עם אחזיה מלך ישראל הוא הרשיע לעשות׃ ");
INSERT INTO heb_vpl VALUES ("R220_36","015_20_36","2CH","20","36","36","ויחברהו עמו לעשות אניות ללכת תרשיש ויעשו אניות בעציון גבר׃ ");
INSERT INTO heb_vpl VALUES ("R220_37","015_20_37","2CH","20","37","37","ויתנבא אליעזר בן דדוהו ממרשה על יהושפט לאמר כהתחברך עם אחזיהו פרץ יהוה את מעשיך וישברו אניות ולא עצרו ללכת אל תרשיש׃ ");
INSERT INTO heb_vpl VALUES ("R221_1","015_21_1","2CH","21","1","1","וישכב יהושפט עם אבתיו ויקבר עם אבתיו בעיר דויד וימלך יהורם בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R221_2","015_21_2","2CH","21","2","2","ולו אחים בני יהושפט עזריה ויחיאל וזכריהו ועזריהו ומיכאל ושפטיהו כל אלה בני יהושפט מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R221_3","015_21_3","2CH","21","3","3","ויתן להם אביהם מתנות רבות לכסף ולזהב ולמגדנות עם ערי מצרות ביהודה ואת הממלכה נתן ליהורם כי הוא הבכור׃ ");
INSERT INTO heb_vpl VALUES ("R221_4","015_21_4","2CH","21","4","4","ויקם יהורם על ממלכת אביו ויתחזק ויהרג את כל אחיו בחרב וגם משרי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R221_5","015_21_5","2CH","21","5","5","בן שלשים ושתים שנה יהורם במלכו ושמונה שנים מלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R221_6","015_21_6","2CH","21","6","6","וילך בדרך מלכי ישראל כאשר עשו בית אחאב כי בת אחאב היתה לו אשה ויעש הרע בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R221_7","015_21_7","2CH","21","7","7","ולא אבה יהוה להשחית את בית דויד למען הברית אשר כרת לדויד וכאשר אמר לתת לו ניר ולבניו כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("R221_8","015_21_8","2CH","21","8","8","בימיו פשע אדום מתחת יד יהודה וימליכו עליהם מלך׃ ");
INSERT INTO heb_vpl VALUES ("R221_9","015_21_9","2CH","21","9","9","ויעבר יהורם עם שריו וכל הרכב עמו ויהי קם לילה ויך את אדום הסובב אליו ואת שרי הרכב׃ ");
INSERT INTO heb_vpl VALUES ("R221_10","015_21_10","2CH","21","10","10","ויפשע אדום מתחת יד יהודה עד היום הזה אז תפשע לבנה בעת ההיא מתחת ידו כי עזב את יהוה אלהי אבתיו׃ ");
INSERT INTO heb_vpl VALUES ("R221_11","015_21_11","2CH","21","11","11","גם הוא עשה במות בהרי יהודה ויזן את ישבי ירושלם וידח את יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R221_12","015_21_12","2CH","21","12","12","ויבא אליו מכתב מאליהו הנביא לאמר כה אמר יהוה אלהי דויד אביך תחת אשר לא הלכת בדרכי יהושפט אביך ובדרכי אסא מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R221_13","015_21_13","2CH","21","13","13","ותלך בדרך מלכי ישראל ותזנה את יהודה ואת ישבי ירושלם כהזנות בית אחאב וגם את אחיך בית אביך הטובים ממך הרגת׃ ");
INSERT INTO heb_vpl VALUES ("R221_14","015_21_14","2CH","21","14","14","הנה יהוה נגף מגפה גדולה בעמך ובבניך ובנשיך ובכל רכושך׃ ");
INSERT INTO heb_vpl VALUES ("R221_15","015_21_15","2CH","21","15","15","ואתה בחליים רבים במחלה מעיך עד יצאו מעיך מן החלי ימים על ימים׃ ");
INSERT INTO heb_vpl VALUES ("R221_16","015_21_16","2CH","21","16","16","ויער יהוה על יהורם את רוח הפלשתים והערבים אשר על יד כושים׃ ");
INSERT INTO heb_vpl VALUES ("R221_17","015_21_17","2CH","21","17","17","ויעלו ביהודה ויבקעוה וישבו את כל הרכוש הנמצא לבית המלך וגם בניו ונשיו ולא נשאר לו בן כי אם יהואחז קטן בניו׃ ");
INSERT INTO heb_vpl VALUES ("R221_18","015_21_18","2CH","21","18","18","ואחרי כל זאת נגפו יהוה במעיו לחלי לאין מרפא׃ ");
INSERT INTO heb_vpl VALUES ("R221_19","015_21_19","2CH","21","19","19","ויהי לימים מימים וכעת צאת הקץ לימים שנים יצאו מעיו עם חליו וימת בתחלאים רעים ולא עשו לו עמו שרפה כשרפת אבתיו׃ ");
INSERT INTO heb_vpl VALUES ("R221_20","015_21_20","2CH","21","20","20","בן שלשים ושתים היה במלכו ושמונה שנים מלך בירושלם וילך בלא חמדה ויקברהו בעיר דויד ולא בקברות המלכים׃ ");
INSERT INTO heb_vpl VALUES ("R222_1","015_22_1","2CH","22","1","1","וימליכו יושבי ירושלם את אחזיהו בנו הקטן תחתיו כי כל הראשנים הרג הגדוד הבא בערבים למחנה וימלך אחזיהו בן יהורם מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R222_2","015_22_2","2CH","22","2","2","בן ארבעים ושתים שנה אחזיהו במלכו ושנה אחת מלך בירושלם ושם אמו עתליהו בת עמרי׃ ");
INSERT INTO heb_vpl VALUES ("R222_3","015_22_3","2CH","22","3","3","גם הוא הלך בדרכי בית אחאב כי אמו היתה יועצתו להרשיע׃ ");
INSERT INTO heb_vpl VALUES ("R222_4","015_22_4","2CH","22","4","4","ויעש הרע בעיני יהוה כבית אחאב כי המה היו לו יועצים אחרי מות אביו למשחית לו׃ ");
INSERT INTO heb_vpl VALUES ("R222_5","015_22_5","2CH","22","5","5","גם בעצתם הלך וילך את יהורם בן אחאב מלך ישראל למלחמה על חזאל מלך ארם ברמות גלעד ויכו הרמים את יורם׃ ");
INSERT INTO heb_vpl VALUES ("R222_6","015_22_6","2CH","22","6","6","וישב להתרפא ביזרעאל כי המכים אשר הכהו ברמה בהלחמו את חזהאל מלך ארם ועזריהו בן יהורם מלך יהודה ירד לראות את יהורם בן אחאב ביזרעאל כי חלה הוא׃ ");
INSERT INTO heb_vpl VALUES ("R222_7","015_22_7","2CH","22","7","7","ומאלהים היתה תבוסת אחזיהו לבוא אל יורם ובבאו יצא עם יהורם אל יהוא בן נמשי אשר משחו יהוה להכרית את בית אחאב׃ ");
INSERT INTO heb_vpl VALUES ("R222_8","015_22_8","2CH","22","8","8","ויהי כהשפט יהוא עם בית אחאב וימצא את שרי יהודה ובני אחי אחזיהו משרתים לאחזיהו ויהרגם׃ ");
INSERT INTO heb_vpl VALUES ("R222_9","015_22_9","2CH","22","9","9","ויבקש את אחזיהו וילכדהו והוא מתחבא בשמרון ויבאהו אל יהוא וימתהו ויקברהו כי אמרו בן יהושפט הוא אשר דרש את יהוה בכל לבבו ואין לבית אחזיהו לעצר כח לממלכה׃ ");
INSERT INTO heb_vpl VALUES ("R222_10","015_22_10","2CH","22","10","10","ועתליהו אם אחזיהו ראתה כי מת בנה ותקם ותדבר את כל זרע הממלכה לבית יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R222_11","015_22_11","2CH","22","11","11","ותקח יהושבעת בת המלך את יואש בן אחזיהו ותגנב אתו מתוך בני המלך המומתים ותתן אתו ואת מינקתו בחדר המטות ותסתירהו יהושבעת בת המלך יהורם אשת יהוידע הכהן כי היא היתה אחות אחזיהו מפני עתליהו ולא המיתתהו׃ ");
INSERT INTO heb_vpl VALUES ("R222_12","015_22_12","2CH","22","12","12","ויהי אתם בבית האלהים מתחבא שש שנים ועתליה מלכת על הארץ׃ ");
INSERT INTO heb_vpl VALUES ("R223_1","015_23_1","2CH","23","1","1","ובשנה השבעית התחזק יהוידע ויקח את שרי המאות לעזריהו בן ירחם ולישמעאל בן יהוחנן ולעזריהו בן עובד ואת מעשיהו בן עדיהו ואת אלישפט בן זכרי עמו בברית׃ ");
INSERT INTO heb_vpl VALUES ("R223_2","015_23_2","2CH","23","2","2","ויסבו ביהודה ויקבצו את הלוים מכל ערי יהודה וראשי האבות לישראל ויבאו אל ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R223_3","015_23_3","2CH","23","3","3","ויכרת כל הקהל ברית בבית האלהים עם המלך ויאמר להם הנה בן המלך ימלך כאשר דבר יהוה על בני דויד׃ ");
INSERT INTO heb_vpl VALUES ("R223_4","015_23_4","2CH","23","4","4","זה הדבר אשר תעשו השלשית מכם באי השבת לכהנים וללוים לשערי הספים׃ ");
INSERT INTO heb_vpl VALUES ("R223_5","015_23_5","2CH","23","5","5","והשלשית בבית המלך והשלשית בשער היסוד וכל העם בחצרות בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R223_6","015_23_6","2CH","23","6","6","ואל יבוא בית יהוה כי אם הכהנים והמשרתים ללוים המה יבאו כי קדש המה וכל העם ישמרו משמרת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R223_7","015_23_7","2CH","23","7","7","והקיפו הלוים את המלך סביב איש וכליו בידו והבא אל הבית יומת והיו את המלך בבאו ובצאתו׃ ");
INSERT INTO heb_vpl VALUES ("R223_8","015_23_8","2CH","23","8","8","ויעשו הלוים וכל יהודה ככל אשר צוה יהוידע הכהן ויקחו איש את אנשיו באי השבת עם יוצאי השבת כי לא פטר יהוידע הכהן את המחלקות׃ ");
INSERT INTO heb_vpl VALUES ("R223_9","015_23_9","2CH","23","9","9","ויתן יהוידע הכהן לשרי המאות את החניתים ואת המגנות ואת השלטים אשר למלך דויד אשר בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R223_10","015_23_10","2CH","23","10","10","ויעמד את כל העם ואיש שלחו בידו מכתף הבית הימנית עד כתף הבית השמאלית למזבח ולבית על המלך סביב׃ ");
INSERT INTO heb_vpl VALUES ("R223_11","015_23_11","2CH","23","11","11","ויוציאו את בן המלך ויתנו עליו את הנזר ואת העדות וימליכו אתו וימשחהו יהוידע ובניו ויאמרו יחי המלך׃ ");
INSERT INTO heb_vpl VALUES ("R223_12","015_23_12","2CH","23","12","12","ותשמע עתליהו את קול העם הרצים והמהללים את המלך ותבוא אל העם בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R223_13","015_23_13","2CH","23","13","13","ותרא והנה המלך עומד על עמודו במבוא והשרים והחצצרות על המלך וכל עם הארץ שמח ותוקע בחצצרות והמשוררים בכלי השיר ומודיעים להלל ותקרע עתליהו את בגדיה ותאמר קשר קשר׃ ");
INSERT INTO heb_vpl VALUES ("R223_14","015_23_14","2CH","23","14","14","ויוצא יהוידע הכהן את שרי המאות פקודי החיל ויאמר אלהם הוציאוה אל מבית השדרות והבא אחריה יומת בחרב כי אמר הכהן לא תמיתוה בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R223_15","015_23_15","2CH","23","15","15","וישימו לה ידים ותבוא אל מבוא שער הסוסים בית המלך וימיתוה שם׃ ");
INSERT INTO heb_vpl VALUES ("R223_16","015_23_16","2CH","23","16","16","ויכרת יהוידע ברית בינו ובין כל העם ובין המלך להיות לעם ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("R223_17","015_23_17","2CH","23","17","17","ויבאו כל העם בית הבעל ויתצהו ואת מזבחתיו ואת צלמיו שברו ואת מתן כהן הבעל הרגו לפני המזבחות׃ ");
INSERT INTO heb_vpl VALUES ("R223_18","015_23_18","2CH","23","18","18","וישם יהוידע פקדת בית יהוה ביד הכהנים הלוים אשר חלק דויד על בית יהוה להעלות עלות יהוה ככתוב בתורת משה בשמחה ובשיר על ידי דויד׃ ");
INSERT INTO heb_vpl VALUES ("R223_19","015_23_19","2CH","23","19","19","ויעמד השוערים על שערי בית יהוה ולא יבא טמא לכל דבר׃ ");
INSERT INTO heb_vpl VALUES ("R223_20","015_23_20","2CH","23","20","20","ויקח את שרי המאות ואת האדירים ואת המושלים בעם ואת כל עם הארץ ויורד את המלך מבית יהוה ויבאו בתוך שער העליון בית המלך ויושיבו את המלך על כסא הממלכה׃ ");
INSERT INTO heb_vpl VALUES ("R223_21","015_23_21","2CH","23","21","21","וישמחו כל עם הארץ והעיר שקטה ואת עתליהו המיתו בחרב׃ ");
INSERT INTO heb_vpl VALUES ("R224_1","015_24_1","2CH","24","1","1","בן שבע שנים יאש במלכו וארבעים שנה מלך בירושלם ושם אמו צביה מבאר שבע׃ ");
INSERT INTO heb_vpl VALUES ("R224_2","015_24_2","2CH","24","2","2","ויעש יואש הישר בעיני יהוה כל ימי יהוידע הכהן׃ ");
INSERT INTO heb_vpl VALUES ("R224_3","015_24_3","2CH","24","3","3","וישא לו יהוידע נשים שתים ויולד בנים ובנות׃ ");
INSERT INTO heb_vpl VALUES ("R224_4","015_24_4","2CH","24","4","4","ויהי אחריכן היה עם לב יואש לחדש את בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R224_5","015_24_5","2CH","24","5","5","ויקבץ את הכהנים והלוים ויאמר להם צאו לערי יהודה וקבצו מכל ישראל כסף לחזק את בית אלהיכם מדי שנה בשנה ואתם תמהרו לדבר ולא מהרו הלוים׃ ");
INSERT INTO heb_vpl VALUES ("R224_6","015_24_6","2CH","24","6","6","ויקרא המלך ליהוידע הראש ויאמר לו מדוע לא דרשת על הלוים להביא מיהודה ומירושלם את משאת משה עבד יהוה והקהל לישראל לאהל העדות׃ ");
INSERT INTO heb_vpl VALUES ("R224_7","015_24_7","2CH","24","7","7","כי עתליהו המרשעת בניה פרצו את בית האלהים וגם כל קדשי בית יהוה עשו לבעלים׃ ");
INSERT INTO heb_vpl VALUES ("R224_8","015_24_8","2CH","24","8","8","ויאמר המלך ויעשו ארון אחד ויתנהו בשער בית יהוה חוצה׃ ");
INSERT INTO heb_vpl VALUES ("R224_9","015_24_9","2CH","24","9","9","ויתנו קול ביהודה ובירושלם להביא ליהוה משאת משה עבד האלהים על ישראל במדבר׃ ");
INSERT INTO heb_vpl VALUES ("R224_10","015_24_10","2CH","24","10","10","וישמחו כל השרים וכל העם ויביאו וישליכו לארון עד לכלה׃ ");
INSERT INTO heb_vpl VALUES ("R224_11","015_24_11","2CH","24","11","11","ויהי בעת יביא את הארון אל פקדת המלך ביד הלוים וכראותם כי רב הכסף ובא סופר המלך ופקיד כהן הראש ויערו את הארון וישאהו וישיבהו אל מקמו כה עשו ליום ביום ויאספו כסף לרב׃ ");
INSERT INTO heb_vpl VALUES ("R224_12","015_24_12","2CH","24","12","12","ויתנהו המלך ויהוידע אל עושה מלאכת עבודת בית יהוה ויהיו שכרים חצבים וחרשים לחדש בית יהוה וגם לחרשי ברזל ונחשת לחזק את בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R224_13","015_24_13","2CH","24","13","13","ויעשו עשי המלאכה ותעל ארוכה למלאכה בידם ויעמידו את בית האלהים על מתכנתו ויאמצהו׃ ");
INSERT INTO heb_vpl VALUES ("R224_14","015_24_14","2CH","24","14","14","וככלותם הביאו לפני המלך ויהוידע את שאר הכסף ויעשהו כלים לבית יהוה כלי שרת והעלות וכפות וכלי זהב וכסף ויהיו מעלים עלות בבית יהוה תמיד כל ימי יהוידע׃ ");
INSERT INTO heb_vpl VALUES ("R224_15","015_24_15","2CH","24","15","15","ויזקן יהוידע וישבע ימים וימת בן מאה ושלשים שנה במותו׃ ");
INSERT INTO heb_vpl VALUES ("R224_16","015_24_16","2CH","24","16","16","ויקברהו בעיר דויד עם המלכים כי עשה טובה בישראל ועם האלהים וביתו׃ ");
INSERT INTO heb_vpl VALUES ("R224_17","015_24_17","2CH","24","17","17","ואחרי מות יהוידע באו שרי יהודה וישתחוו למלך אז שמע המלך אליהם׃ ");
INSERT INTO heb_vpl VALUES ("R224_18","015_24_18","2CH","24","18","18","ויעזבו את בית יהוה אלהי אבותיהם ויעבדו את האשרים ואת העצבים ויהי קצף על יהודה וירושלם באשמתם זאת׃ ");
INSERT INTO heb_vpl VALUES ("R224_19","015_24_19","2CH","24","19","19","וישלח בהם נבאים להשיבם אל יהוה ויעידו בם ולא האזינו׃ ");
INSERT INTO heb_vpl VALUES ("R224_20","015_24_20","2CH","24","20","20","ורוח אלהים לבשה את זכריה בן יהוידע הכהן ויעמד מעל לעם ויאמר להם כה אמר האלהים למה אתם עברים את מצות יהוה ולא תצליחו כי עזבתם את יהוה ויעזב אתכם׃ ");
INSERT INTO heb_vpl VALUES ("R224_21","015_24_21","2CH","24","21","21","ויקשרו עליו וירגמהו אבן במצות המלך בחצר בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R224_22","015_24_22","2CH","24","22","22","ולא זכר יואש המלך החסד אשר עשה יהוידע אביו עמו ויהרג את בנו וכמותו אמר ירא יהוה וידרש׃ ");
INSERT INTO heb_vpl VALUES ("R224_23","015_24_23","2CH","24","23","23","ויהי לתקופת השנה עלה עליו חיל ארם ויבאו אל יהודה וירושלם וישחיתו את כל שרי העם מעם וכל שללם שלחו למלך דרמשק׃ ");
INSERT INTO heb_vpl VALUES ("R224_24","015_24_24","2CH","24","24","24","כי במצער אנשים באו חיל ארם ויהוה נתן בידם חיל לרב מאד כי עזבו את יהוה אלהי אבותיהם ואת יואש עשו שפטים׃ ");
INSERT INTO heb_vpl VALUES ("R224_25","015_24_25","2CH","24","25","25","ובלכתם ממנו כי עזבו אתו במחליים רבים התקשרו עליו עבדיו בדמי בני יהוידע הכהן ויהרגהו על מטתו וימת ויקברהו בעיר דויד ולא קברהו בקברות המלכים׃ ");
INSERT INTO heb_vpl VALUES ("R224_26","015_24_26","2CH","24","26","26","ואלה המתקשרים עליו זבד בן שמעת העמונית ויהוזבד בן שמרית המואבית׃ ");
INSERT INTO heb_vpl VALUES ("R224_27","015_24_27","2CH","24","27","27","ובניו ורב המשא עליו ויסוד בית האלהים הנם כתובים על מדרש ספר המלכים וימלך אמציהו בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R225_1","015_25_1","2CH","25","1","1","בן עשרים וחמש שנה מלך אמציהו ועשרים ותשע שנה מלך בירושלם ושם אמו יהועדן מירושלים׃ ");
INSERT INTO heb_vpl VALUES ("R225_2","015_25_2","2CH","25","2","2","ויעש הישר בעיני יהוה רק לא בלבב שלם׃ ");
INSERT INTO heb_vpl VALUES ("R225_3","015_25_3","2CH","25","3","3","ויהי כאשר חזקה הממלכה עליו ויהרג את עבדיו המכים את המלך אביו׃ ");
INSERT INTO heb_vpl VALUES ("R225_4","015_25_4","2CH","25","4","4","ואת בניהם לא המית כי ככתוב בתורה בספר משה אשר צוה יהוה לאמר לא ימותו אבות על בנים ובנים לא ימותו על אבות כי איש בחטאו ימותו׃ ");
INSERT INTO heb_vpl VALUES ("R225_5","015_25_5","2CH","25","5","5","ויקבץ אמציהו את יהודה ויעמידם לבית אבות לשרי האלפים ולשרי המאות לכל יהודה ובנימן ויפקדם למבן עשרים שנה ומעלה וימצאם שלש מאות אלף בחור יוצא צבא אחז רמח וצנה׃ ");
INSERT INTO heb_vpl VALUES ("R225_6","015_25_6","2CH","25","6","6","וישכר מישראל מאה אלף גבור חיל במאה ככר כסף׃ ");
INSERT INTO heb_vpl VALUES ("R225_7","015_25_7","2CH","25","7","7","ואיש האלהים בא אליו לאמר המלך אל יבא עמך צבא ישראל כי אין יהוה עם ישראל כל בני אפרים׃ ");
INSERT INTO heb_vpl VALUES ("R225_8","015_25_8","2CH","25","8","8","כי אם בא אתה עשה חזק למלחמה יכשילך האלהים לפני אויב כי יש כח באלהים לעזור ולהכשיל׃ ");
INSERT INTO heb_vpl VALUES ("R225_9","015_25_9","2CH","25","9","9","ויאמר אמציהו לאיש האלהים ומה לעשות למאת הככר אשר נתתי לגדוד ישראל ויאמר איש האלהים יש ליהוה לתת לך הרבה מזה׃ ");
INSERT INTO heb_vpl VALUES ("R225_10","015_25_10","2CH","25","10","10","ויבדילם אמציהו להגדוד אשר בא אליו מאפרים ללכת למקומם ויחר אפם מאד ביהודה וישובו למקומם בחרי אף׃ ");
INSERT INTO heb_vpl VALUES ("R225_11","015_25_11","2CH","25","11","11","ואמציהו התחזק וינהג את עמו וילך גיא המלח ויך את בני שעיר עשרת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("R225_12","015_25_12","2CH","25","12","12","ועשרת אלפים חיים שבו בני יהודה ויביאום לראש הסלע וישליכום מראש הסלע וכלם נבקעו׃ ");
INSERT INTO heb_vpl VALUES ("R225_13","015_25_13","2CH","25","13","13","ובני הגדוד אשר השיב אמציהו מלכת עמו למלחמה ויפשטו בערי יהודה משמרון ועד בית חורון ויכו מהם שלשת אלפים ויבזו בזה רבה׃ ");
INSERT INTO heb_vpl VALUES ("R225_14","015_25_14","2CH","25","14","14","ויהי אחרי בוא אמציהו מהכות את אדומים ויבא את אלהי בני שעיר ויעמידם לו לאלהים ולפניהם ישתחוה ולהם יקטר׃ ");
INSERT INTO heb_vpl VALUES ("R225_15","015_25_15","2CH","25","15","15","ויחר אף יהוה באמציהו וישלח אליו נביא ויאמר לו למה דרשת את אלהי העם אשר לא הצילו את עמם מידך׃ ");
INSERT INTO heb_vpl VALUES ("R225_16","015_25_16","2CH","25","16","16","ויהי בדברו אליו ויאמר לו הליועץ למלך נתנוך חדל לך למה יכוך ויחדל הנביא ויאמר ידעתי כי יעץ אלהים להשחיתך כי עשית זאת ולא שמעת לעצתי׃ ");
INSERT INTO heb_vpl VALUES ("R225_17","015_25_17","2CH","25","17","17","ויועץ אמציהו מלך יהודה וישלח אל יואש בן יהואחז בן יהוא מלך ישראל לאמר לך נתראה פנים׃ ");
INSERT INTO heb_vpl VALUES ("R225_18","015_25_18","2CH","25","18","18","וישלח יואש מלך ישראל אל אמציהו מלך יהודה לאמר החוח אשר בלבנון שלח אל הארז אשר בלבנון לאמר תנה את בתך לבני לאשה ותעבר חית השדה אשר בלבנון ותרמס את החוח׃ ");
INSERT INTO heb_vpl VALUES ("R225_19","015_25_19","2CH","25","19","19","אמרת הנה הכית את אדום ונשאך לבך להכביד עתה שבה בביתך למה תתגרה ברעה ונפלת אתה ויהודה עמך׃ ");
INSERT INTO heb_vpl VALUES ("R225_20","015_25_20","2CH","25","20","20","ולא שמע אמציהו כי מהאלהים היא למען תתם ביד כי דרשו את אלהי אדום׃ ");
INSERT INTO heb_vpl VALUES ("R225_21","015_25_21","2CH","25","21","21","ויעל יואש מלך ישראל ויתראו פנים הוא ואמציהו מלך יהודה בבית שמש אשר ליהודה׃ ");
INSERT INTO heb_vpl VALUES ("R225_22","015_25_22","2CH","25","22","22","וינגף יהודה לפני ישראל וינסו איש לאהליו׃ ");
INSERT INTO heb_vpl VALUES ("R225_23","015_25_23","2CH","25","23","23","ואת אמציהו מלך יהודה בן יואש בן יהואחז תפש יואש מלך ישראל בבית שמש ויביאהו ירושלם ויפרץ בחומת ירושלם משער אפרים עד שער הפונה ארבע מאות אמה׃ ");
INSERT INTO heb_vpl VALUES ("R225_24","015_25_24","2CH","25","24","24","וכל הזהב והכסף ואת כל הכלים הנמצאים בבית האלהים עם עבד אדום ואת אצרות בית המלך ואת בני התערבות וישב שמרון׃ ");
INSERT INTO heb_vpl VALUES ("R225_25","015_25_25","2CH","25","25","25","ויחי אמציהו בן יואש מלך יהודה אחרי מות יואש בן יהואחז מלך ישראל חמש עשרה שנה׃ ");
INSERT INTO heb_vpl VALUES ("R225_26","015_25_26","2CH","25","26","26","ויתר דברי אמציהו הראשנים והאחרונים הלא הנם כתובים על ספר מלכי יהודה וישראל׃ ");
INSERT INTO heb_vpl VALUES ("R225_27","015_25_27","2CH","25","27","27","ומעת אשר סר אמציהו מאחרי יהוה ויקשרו עליו קשר בירושלם וינס לכישה וישלחו אחריו לכישה וימיתהו שם׃ ");
INSERT INTO heb_vpl VALUES ("R225_28","015_25_28","2CH","25","28","28","וישאהו על הסוסים ויקברו אתו עם אבתיו בעיר יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R226_1","015_26_1","2CH","26","1","1","ויקחו כל עם יהודה את עזיהו והוא בן שש עשרה שנה וימליכו אתו תחת אביו אמציהו׃ ");
INSERT INTO heb_vpl VALUES ("R226_2","015_26_2","2CH","26","2","2","הוא בנה את אילות וישיבה ליהודה אחרי שכב המלך עם אבתיו׃ ");
INSERT INTO heb_vpl VALUES ("R226_3","015_26_3","2CH","26","3","3","בן שש עשרה שנה עזיהו במלכו וחמשים ושתים שנה מלך בירושלם ושם אמו יכיליה מן ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R226_4","015_26_4","2CH","26","4","4","ויעש הישר בעיני יהוה ככל אשר עשה אמציהו אביו׃ ");
INSERT INTO heb_vpl VALUES ("R226_5","015_26_5","2CH","26","5","5","ויהי לדרש אלהים בימי זכריהו המבין בראת האלהים ובימי דרשו את יהוה הצליחו האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R226_6","015_26_6","2CH","26","6","6","ויצא וילחם בפלשתים ויפרץ את חומת גת ואת חומת יבנה ואת חומת אשדוד ויבנה ערים באשדוד ובפלשתים׃ ");
INSERT INTO heb_vpl VALUES ("R226_7","015_26_7","2CH","26","7","7","ויעזרהו האלהים על פלשתים ועל הערביים הישבים בגור בעל והמעונים׃ ");
INSERT INTO heb_vpl VALUES ("R226_8","015_26_8","2CH","26","8","8","ויתנו העמונים מנחה לעזיהו וילך שמו עד לבוא מצרים כי החזיק עד למעלה׃ ");
INSERT INTO heb_vpl VALUES ("R226_9","015_26_9","2CH","26","9","9","ויבן עזיהו מגדלים בירושלם על שער הפנה ועל שער הגיא ועל המקצוע ויחזקם׃ ");
INSERT INTO heb_vpl VALUES ("R226_10","015_26_10","2CH","26","10","10","ויבן מגדלים במדבר ויחצב ברות רבים כי מקנה רב היה לו ובשפלה ובמישור אכרים וכרמים בהרים ובכרמל כי אהב אדמה היה׃ ");
INSERT INTO heb_vpl VALUES ("R226_11","015_26_11","2CH","26","11","11","ויהי לעזיהו חיל עשה מלחמה יוצאי צבא לגדוד במספר פקדתם ביד יעואל הסופר ומעשיהו השוטר על יד חנניהו משרי המלך׃ ");
INSERT INTO heb_vpl VALUES ("R226_12","015_26_12","2CH","26","12","12","כל מספר ראשי האבות לגבורי חיל אלפים ושש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R226_13","015_26_13","2CH","26","13","13","ועל ידם חיל צבא שלש מאות אלף ושבעת אלפים וחמש מאות עושי מלחמה בכח חיל לעזר למלך על האויב׃ ");
INSERT INTO heb_vpl VALUES ("R226_14","015_26_14","2CH","26","14","14","ויכן להם עזיהו לכל הצבא מגנים ורמחים וכובעים ושרינות וקשתות ולאבני קלעים׃ ");
INSERT INTO heb_vpl VALUES ("R226_15","015_26_15","2CH","26","15","15","ויעש בירושלם חשבנות מחשבת חושב להיות על המגדלים ועל הפנות לירוא בחצים ובאבנים גדלות ויצא שמו עד למרחוק כי הפליא להעזר עד כי חזק׃ ");
INSERT INTO heb_vpl VALUES ("R226_16","015_26_16","2CH","26","16","16","וכחזקתו גבה לבו עד להשחית וימעל ביהוה אלהיו ויבא אל היכל יהוה להקטיר על מזבח הקטרת׃ ");
INSERT INTO heb_vpl VALUES ("R226_17","015_26_17","2CH","26","17","17","ויבא אחריו עזריהו הכהן ועמו כהנים ליהוה שמונים בני חיל׃ ");
INSERT INTO heb_vpl VALUES ("R226_18","015_26_18","2CH","26","18","18","ויעמדו על עזיהו המלך ויאמרו לו לא לך עזיהו להקטיר ליהוה כי לכהנים בני אהרן המקדשים להקטיר צא מן המקדש כי מעלת ולא לך לכבוד מיהוה אלהים׃ ");
INSERT INTO heb_vpl VALUES ("R226_19","015_26_19","2CH","26","19","19","ויזעף עזיהו ובידו מקטרת להקטיר ובזעפו עם הכהנים והצרעת זרחה במצחו לפני הכהנים בבית יהוה מעל למזבח הקטרת׃ ");
INSERT INTO heb_vpl VALUES ("R226_20","015_26_20","2CH","26","20","20","ויפן אליו עזריהו כהן הראש וכל הכהנים והנה הוא מצרע במצחו ויבהלוהו משם וגם הוא נדחף לצאת כי נגעו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R226_21","015_26_21","2CH","26","21","21","ויהי עזיהו המלך מצרע עד יום מותו וישב בית החפשות מצרע כי נגזר מבית יהוה ויותם בנו על בית המלך שופט את עם הארץ׃ ");
INSERT INTO heb_vpl VALUES ("R226_22","015_26_22","2CH","26","22","22","ויתר דברי עזיהו הראשנים והאחרנים כתב ישעיהו בן אמוץ הנביא׃ ");
INSERT INTO heb_vpl VALUES ("R226_23","015_26_23","2CH","26","23","23","וישכב עזיהו עם אבתיו ויקברו אתו עם אבתיו בשדה הקבורה אשר למלכים כי אמרו מצורע הוא וימלך יותם בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R227_1","015_27_1","2CH","27","1","1","בן עשרים וחמש שנה יותם במלכו ושש עשרה שנה מלך בירושלם ושם אמו ירושה בת צדוק׃ ");
INSERT INTO heb_vpl VALUES ("R227_2","015_27_2","2CH","27","2","2","ויעש הישר בעיני יהוה ככל אשר עשה עזיהו אביו רק לא בא אל היכל יהוה ועוד העם משחיתים׃ ");
INSERT INTO heb_vpl VALUES ("R227_3","015_27_3","2CH","27","3","3","הוא בנה את שער בית יהוה העליון ובחומת העפל בנה לרב׃ ");
INSERT INTO heb_vpl VALUES ("R227_4","015_27_4","2CH","27","4","4","וערים בנה בהר יהודה ובחרשים בנה בירניות ומגדלים׃ ");
INSERT INTO heb_vpl VALUES ("R227_5","015_27_5","2CH","27","5","5","והוא נלחם עם מלך בני עמון ויחזק עליהם ויתנו לו בני עמון בשנה ההיא מאה ככר כסף ועשרת אלפים כרים חטים ושעורים עשרת אלפים זאת השיבו לו בני עמון ובשנה השנית והשלשית׃ ");
INSERT INTO heb_vpl VALUES ("R227_6","015_27_6","2CH","27","6","6","ויתחזק יותם כי הכין דרכיו לפני יהוה אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("R227_7","015_27_7","2CH","27","7","7","ויתר דברי יותם וכל מלחמתיו ודרכיו הנם כתובים על ספר מלכי ישראל ויהודה׃ ");
INSERT INTO heb_vpl VALUES ("R227_8","015_27_8","2CH","27","8","8","בן עשרים וחמש שנה היה במלכו ושש עשרה שנה מלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R227_9","015_27_9","2CH","27","9","9","וישכב יותם עם אבתיו ויקברו אתו בעיר דויד וימלך אחז בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R228_1","015_28_1","2CH","28","1","1","בן עשרים שנה אחז במלכו ושש עשרה שנה מלך בירושלם ולא עשה הישר בעיני יהוה כדויד אביו׃ ");
INSERT INTO heb_vpl VALUES ("R228_2","015_28_2","2CH","28","2","2","וילך בדרכי מלכי ישראל וגם מסכות עשה לבעלים׃ ");
INSERT INTO heb_vpl VALUES ("R228_3","015_28_3","2CH","28","3","3","והוא הקטיר בגיא בן הנם ויבער את בניו באש כתעבות הגוים אשר הריש יהוה מפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R228_4","015_28_4","2CH","28","4","4","ויזבח ויקטר בבמות ועל הגבעות ותחת כל עץ רענן׃ ");
INSERT INTO heb_vpl VALUES ("R228_5","015_28_5","2CH","28","5","5","ויתנהו יהוה אלהיו ביד מלך ארם ויכו בו וישבו ממנו שביה גדולה ויביאו דרמשק וגם ביד מלך ישראל נתן ויך בו מכה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("R228_6","015_28_6","2CH","28","6","6","ויהרג פקח בן רמליהו ביהודה מאה ועשרים אלף ביום אחד הכל בני חיל בעזבם את יהוה אלהי אבותם׃ ");
INSERT INTO heb_vpl VALUES ("R228_7","015_28_7","2CH","28","7","7","ויהרג זכרי גבור אפרים את מעשיהו בן המלך ואת עזריקם נגיד הבית ואת אלקנה משנה המלך׃ ");
INSERT INTO heb_vpl VALUES ("R228_8","015_28_8","2CH","28","8","8","וישבו בני ישראל מאחיהם מאתים אלף נשים בנים ובנות וגם שלל רב בזזו מהם ויביאו את השלל לשמרון׃ ");
INSERT INTO heb_vpl VALUES ("R228_9","015_28_9","2CH","28","9","9","ושם היה נביא ליהוה עדד שמו ויצא לפני הצבא הבא לשמרון ויאמר להם הנה בחמת יהוה אלהי אבותיכם על יהודה נתנם בידכם ותהרגו בם בזעף עד לשמים הגיע׃ ");
INSERT INTO heb_vpl VALUES ("R228_10","015_28_10","2CH","28","10","10","ועתה בני יהודה וירושלם אתם אמרים לכבש לעבדים ולשפחות לכם הלא רק אתם עמכם אשמות ליהוה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("R228_11","015_28_11","2CH","28","11","11","ועתה שמעוני והשיבו השביה אשר שביתם מאחיכם כי חרון אף יהוה עליכם׃ ");
INSERT INTO heb_vpl VALUES ("R228_12","015_28_12","2CH","28","12","12","ויקמו אנשים מראשי בני אפרים עזריהו בן יהוחנן ברכיהו בן משלמות ויחזקיהו בן שלם ועמשא בן חדלי על הבאים מן הצבא׃ ");
INSERT INTO heb_vpl VALUES ("R228_13","015_28_13","2CH","28","13","13","ויאמרו להם לא תביאו את השביה הנה כי לאשמת יהוה עלינו אתם אמרים להסיף על חטאתינו ועל אשמתינו כי רבה אשמה לנו וחרון אף על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R228_14","015_28_14","2CH","28","14","14","ויעזב החלוץ את השביה ואת הבזה לפני השרים וכל הקהל׃ ");
INSERT INTO heb_vpl VALUES ("R228_15","015_28_15","2CH","28","15","15","ויקמו האנשים אשר נקבו בשמות ויחזיקו בשביה וכל מערמיהם הלבישו מן השלל וילבשום וינעלום ויאכלום וישקום ויסכום וינהלום בחמרים לכל כושל ויביאום ירחו עיר התמרים אצל אחיהם וישובו שמרון׃ ");
INSERT INTO heb_vpl VALUES ("R228_16","015_28_16","2CH","28","16","16","בעת ההיא שלח המלך אחז על מלכי אשור לעזר לו׃ ");
INSERT INTO heb_vpl VALUES ("R228_17","015_28_17","2CH","28","17","17","ועוד אדומים באו ויכו ביהודה וישבו שבי׃ ");
INSERT INTO heb_vpl VALUES ("R228_18","015_28_18","2CH","28","18","18","ופלשתים פשטו בערי השפלה והנגב ליהודה וילכדו את בית שמש ואת אילון ואת הגדרות ואת שוכו ובנותיה ואת תמנה ובנותיה ואת גמזו ואת בנתיה וישבו שם׃ ");
INSERT INTO heb_vpl VALUES ("R228_19","015_28_19","2CH","28","19","19","כי הכניע יהוה את יהודה בעבור אחז מלך ישראל כי הפריע ביהודה ומעול מעל ביהוה׃ ");
INSERT INTO heb_vpl VALUES ("R228_20","015_28_20","2CH","28","20","20","ויבא עליו תלגת פלנאסר מלך אשור ויצר לו ולא חזקו׃ ");
INSERT INTO heb_vpl VALUES ("R228_21","015_28_21","2CH","28","21","21","כי חלק אחז את בית יהוה ואת בית המלך והשרים ויתן למלך אשור ולא לעזרה לו׃ ");
INSERT INTO heb_vpl VALUES ("R228_22","015_28_22","2CH","28","22","22","ובעת הצר לו ויוסף למעול ביהוה הוא המלך אחז׃ ");
INSERT INTO heb_vpl VALUES ("R228_23","015_28_23","2CH","28","23","23","ויזבח לאלהי דרמשק המכים בו ויאמר כי אלהי מלכי ארם הם מעזרים אותם להם אזבח ויעזרוני והם היו לו להכשילו ולכל ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R228_24","015_28_24","2CH","28","24","24","ויאסף אחז את כלי בית האלהים ויקצץ את כלי בית האלהים ויסגר את דלתות בית יהוה ויעש לו מזבחות בכל פנה בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R228_25","015_28_25","2CH","28","25","25","ובכל עיר ועיר ליהודה עשה במות לקטר לאלהים אחרים ויכעס את יהוה אלהי אבתיו׃ ");
INSERT INTO heb_vpl VALUES ("R228_26","015_28_26","2CH","28","26","26","ויתר דבריו וכל דרכיו הראשנים והאחרונים הנם כתובים על ספר מלכי יהודה וישראל׃ ");
INSERT INTO heb_vpl VALUES ("R228_27","015_28_27","2CH","28","27","27","וישכב אחז עם אבתיו ויקברהו בעיר בירושלם כי לא הביאהו לקברי מלכי ישראל וימלך יחזקיהו בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R229_1","015_29_1","2CH","29","1","1","יחזקיהו מלך בן עשרים וחמש שנה ועשרים ותשע שנה מלך בירושלם ושם אמו אביה בת זכריהו׃ ");
INSERT INTO heb_vpl VALUES ("R229_2","015_29_2","2CH","29","2","2","ויעש הישר בעיני יהוה ככל אשר עשה דויד אביו׃ ");
INSERT INTO heb_vpl VALUES ("R229_3","015_29_3","2CH","29","3","3","הוא בשנה הראשונה למלכו בחדש הראשון פתח את דלתות בית יהוה ויחזקם׃ ");
INSERT INTO heb_vpl VALUES ("R229_4","015_29_4","2CH","29","4","4","ויבא את הכהנים ואת הלוים ויאספם לרחוב המזרח׃ ");
INSERT INTO heb_vpl VALUES ("R229_5","015_29_5","2CH","29","5","5","ויאמר להם שמעוני הלוים עתה התקדשו וקדשו את בית יהוה אלהי אבתיכם והוציאו את הנדה מן הקדש׃ ");
INSERT INTO heb_vpl VALUES ("R229_6","015_29_6","2CH","29","6","6","כי מעלו אבתינו ועשו הרע בעיני יהוה אלהינו ויעזבהו ויסבו פניהם ממשכן יהוה ויתנו ערף׃ ");
INSERT INTO heb_vpl VALUES ("R229_7","015_29_7","2CH","29","7","7","גם סגרו דלתות האולם ויכבו את הנרות וקטרת לא הקטירו ועלה לא העלו בקדש לאלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R229_8","015_29_8","2CH","29","8","8","ויהי קצף יהוה על יהודה וירושלם ויתנם לזועה לשמה ולשרקה כאשר אתם ראים בעיניכם׃ ");
INSERT INTO heb_vpl VALUES ("R229_9","015_29_9","2CH","29","9","9","והנה נפלו אבותינו בחרב ובנינו ובנותינו ונשינו בשבי על זאת׃ ");
INSERT INTO heb_vpl VALUES ("R229_10","015_29_10","2CH","29","10","10","עתה עם לבבי לכרות ברית ליהוה אלהי ישראל וישב ממנו חרון אפו׃ ");
INSERT INTO heb_vpl VALUES ("R229_11","015_29_11","2CH","29","11","11","בני עתה אל תשלו כי בכם בחר יהוה לעמד לפניו לשרתו ולהיות לו משרתים ומקטרים׃ ");
INSERT INTO heb_vpl VALUES ("R229_12","015_29_12","2CH","29","12","12","ויקמו הלוים מחת בן עמשי ויואל בן עזריהו מן בני הקהתי ומן בני מררי קיש בן עבדי ועזריהו בן יהללאל ומן הגרשני יואח בן זמה ועדן בן יואח׃ ");
INSERT INTO heb_vpl VALUES ("R229_13","015_29_13","2CH","29","13","13","ומן בני אליצפן שמרי ויעואל ומן בני אסף זכריהו ומתניהו׃ ");
INSERT INTO heb_vpl VALUES ("R229_14","015_29_14","2CH","29","14","14","ומן בני הימן יחואל ושמעי ומן בני ידותון שמעיה ועזיאל׃ ");
INSERT INTO heb_vpl VALUES ("R229_15","015_29_15","2CH","29","15","15","ויאספו את אחיהם ויתקדשו ויבאו כמצות המלך בדברי יהוה לטהר בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R229_16","015_29_16","2CH","29","16","16","ויבאו הכהנים לפנימה בית יהוה לטהר ויוציאו את כל הטמאה אשר מצאו בהיכל יהוה לחצר בית יהוה ויקבלו הלוים להוציא לנחל קדרון חוצה׃ ");
INSERT INTO heb_vpl VALUES ("R229_17","015_29_17","2CH","29","17","17","ויחלו באחד לחדש הראשון לקדש וביום שמונה לחדש באו לאולם יהוה ויקדשו את בית יהוה לימים שמונה וביום ששה עשר לחדש הראשון כלו׃ ");
INSERT INTO heb_vpl VALUES ("R229_18","015_29_18","2CH","29","18","18","ויבואו פנימה אל חזקיהו המלך ויאמרו טהרנו את כל בית יהוה את מזבח העולה ואת כל כליו ואת שלחן המערכת ואת כל כליו׃ ");
INSERT INTO heb_vpl VALUES ("R229_19","015_29_19","2CH","29","19","19","ואת כל הכלים אשר הזניח המלך אחז במלכותו במעלו הכנו והקדשנו והנם לפני מזבח יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R229_20","015_29_20","2CH","29","20","20","וישכם יחזקיהו המלך ויאסף את שרי העיר ויעל בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R229_21","015_29_21","2CH","29","21","21","ויביאו פרים שבעה ואילים שבעה וכבשים שבעה וצפירי עזים שבעה לחטאת על הממלכה ועל המקדש ועל יהודה ויאמר לבני אהרן הכהנים להעלות על מזבח יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R229_22","015_29_22","2CH","29","22","22","וישחטו הבקר ויקבלו הכהנים את הדם ויזרקו המזבחה וישחטו האלים ויזרקו הדם המזבחה וישחטו הכבשים ויזרקו הדם המזבחה׃ ");
INSERT INTO heb_vpl VALUES ("R229_23","015_29_23","2CH","29","23","23","ויגישו את שעירי החטאת לפני המלך והקהל ויסמכו ידיהם עליהם׃ ");
INSERT INTO heb_vpl VALUES ("R229_24","015_29_24","2CH","29","24","24","וישחטום הכהנים ויחטאו את דמם המזבחה לכפר על כל ישראל כי לכל ישראל אמר המלך העולה והחטאת׃ ");
INSERT INTO heb_vpl VALUES ("R229_25","015_29_25","2CH","29","25","25","ויעמד את הלוים בית יהוה במצלתים בנבלים ובכנרות במצות דויד וגד חזה המלך ונתן הנביא כי ביד יהוה המצוה ביד נביאיו׃ ");
INSERT INTO heb_vpl VALUES ("R229_26","015_29_26","2CH","29","26","26","ויעמדו הלוים בכלי דויד והכהנים בחצצרות׃ ");
INSERT INTO heb_vpl VALUES ("R229_27","015_29_27","2CH","29","27","27","ויאמר חזקיהו להעלות העלה להמזבח ובעת החל העולה החל שיר יהוה והחצצרות ועל ידי כלי דויד מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R229_28","015_29_28","2CH","29","28","28","וכל הקהל משתחוים והשיר משורר והחצצרות מחצצרים הכל עד לכלות העלה׃ ");
INSERT INTO heb_vpl VALUES ("R229_29","015_29_29","2CH","29","29","29","וככלות להעלות כרעו המלך וכל הנמצאים אתו וישתחוו׃ ");
INSERT INTO heb_vpl VALUES ("R229_30","015_29_30","2CH","29","30","30","ויאמר יחזקיהו המלך והשרים ללוים להלל ליהוה בדברי דויד ואסף החזה ויהללו עד לשמחה ויקדו וישתחוו׃ ");
INSERT INTO heb_vpl VALUES ("R229_31","015_29_31","2CH","29","31","31","ויען יחזקיהו ויאמר עתה מלאתם ידכם ליהוה גשו והביאו זבחים ותודות לבית יהוה ויביאו הקהל זבחים ותודות וכל נדיב לב עלות׃ ");
INSERT INTO heb_vpl VALUES ("R229_32","015_29_32","2CH","29","32","32","ויהי מספר העלה אשר הביאו הקהל בקר שבעים אילים מאה כבשים מאתים לעלה ליהוה כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("R229_33","015_29_33","2CH","29","33","33","והקדשים בקר שש מאות וצאן שלשת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("R229_34","015_29_34","2CH","29","34","34","רק הכהנים היו למעט ולא יכלו להפשיט את כל העלות ויחזקום אחיהם הלוים עד כלות המלאכה ועד יתקדשו הכהנים כי הלוים ישרי לבב להתקדש מהכהנים׃ ");
INSERT INTO heb_vpl VALUES ("R229_35","015_29_35","2CH","29","35","35","וגם עלה לרב בחלבי השלמים ובנסכים לעלה ותכון עבודת בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R229_36","015_29_36","2CH","29","36","36","וישמח יחזקיהו וכל העם על ההכין האלהים לעם כי בפתאם היה הדבר׃ ");
INSERT INTO heb_vpl VALUES ("R230_1","015_30_1","2CH","30","1","1","וישלח יחזקיהו על כל ישראל ויהודה וגם אגרות כתב על אפרים ומנשה לבוא לבית יהוה בירושלם לעשות פסח ליהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R230_2","015_30_2","2CH","30","2","2","ויועץ המלך ושריו וכל הקהל בירושלם לעשות הפסח בחדש השני׃ ");
INSERT INTO heb_vpl VALUES ("R230_3","015_30_3","2CH","30","3","3","כי לא יכלו לעשתו בעת ההיא כי הכהנים לא התקדשו למדי והעם לא נאספו לירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R230_4","015_30_4","2CH","30","4","4","ויישר הדבר בעיני המלך ובעיני כל הקהל׃ ");
INSERT INTO heb_vpl VALUES ("R230_5","015_30_5","2CH","30","5","5","ויעמידו דבר להעביר קול בכל ישראל מבאר שבע ועד דן לבוא לעשות פסח ליהוה אלהי ישראל בירושלם כי לא לרב עשו ככתוב׃ ");
INSERT INTO heb_vpl VALUES ("R230_6","015_30_6","2CH","30","6","6","וילכו הרצים באגרות מיד המלך ושריו בכל ישראל ויהודה וכמצות המלך לאמר בני ישראל שובו אל יהוה אלהי אברהם יצחק וישראל וישב אל הפליטה הנשארת לכם מכף מלכי אשור׃ ");
INSERT INTO heb_vpl VALUES ("R230_7","015_30_7","2CH","30","7","7","ואל תהיו כאבותיכם וכאחיכם אשר מעלו ביהוה אלהי אבותיהם ויתנם לשמה כאשר אתם ראים׃ ");
INSERT INTO heb_vpl VALUES ("R230_8","015_30_8","2CH","30","8","8","עתה אל תקשו ערפכם כאבותיכם תנו יד ליהוה ובאו למקדשו אשר הקדיש לעולם ועבדו את יהוה אלהיכם וישב מכם חרון אפו׃ ");
INSERT INTO heb_vpl VALUES ("R230_9","015_30_9","2CH","30","9","9","כי בשובכם על יהוה אחיכם ובניכם לרחמים לפני שוביהם ולשוב לארץ הזאת כי חנון ורחום יהוה אלהיכם ולא יסיר פנים מכם אם תשובו אליו׃ ");
INSERT INTO heb_vpl VALUES ("R230_10","015_30_10","2CH","30","10","10","ויהיו הרצים עברים מעיר לעיר בארץ אפרים ומנשה ועד זבלון ויהיו משחיקים עליהם ומלעגים בם׃ ");
INSERT INTO heb_vpl VALUES ("R230_11","015_30_11","2CH","30","11","11","אך אנשים מאשר ומנשה ומזבלון נכנעו ויבאו לירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R230_12","015_30_12","2CH","30","12","12","גם ביהודה היתה יד האלהים לתת להם לב אחד לעשות מצות המלך והשרים בדבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R230_13","015_30_13","2CH","30","13","13","ויאספו ירושלם עם רב לעשות את חג המצות בחדש השני קהל לרב מאד׃ ");
INSERT INTO heb_vpl VALUES ("R230_14","015_30_14","2CH","30","14","14","ויקמו ויסירו את המזבחות אשר בירושלם ואת כל המקטרות הסירו וישליכו לנחל קדרון׃ ");
INSERT INTO heb_vpl VALUES ("R230_15","015_30_15","2CH","30","15","15","וישחטו הפסח בארבעה עשר לחדש השני והכהנים והלוים נכלמו ויתקדשו ויביאו עלות בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R230_16","015_30_16","2CH","30","16","16","ויעמדו על עמדם כמשפטם כתורת משה איש האלהים הכהנים זרקים את הדם מיד הלוים׃ ");
INSERT INTO heb_vpl VALUES ("R230_17","015_30_17","2CH","30","17","17","כי רבת בקהל אשר לא התקדשו והלוים על שחיטת הפסחים לכל לא טהור להקדיש ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("R230_18","015_30_18","2CH","30","18","18","כי מרבית העם רבת מאפרים ומנשה יששכר וזבלון לא הטהרו כי אכלו את הפסח בלא ככתוב כי התפלל יחזקיהו עליהם לאמר יהוה הטוב יכפר בעד׃ ");
INSERT INTO heb_vpl VALUES ("R230_19","015_30_19","2CH","30","19","19","כל לבבו הכין לדרוש האלהים יהוה אלהי אבותיו ולא כטהרת הקדש׃ ");
INSERT INTO heb_vpl VALUES ("R230_20","015_30_20","2CH","30","20","20","וישמע יהוה אל יחזקיהו וירפא את העם׃ ");
INSERT INTO heb_vpl VALUES ("R230_21","015_30_21","2CH","30","21","21","ויעשו בני ישראל הנמצאים בירושלם את חג המצות שבעת ימים בשמחה גדולה ומהללים ליהוה יום ביום הלוים והכהנים בכלי עז ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("R230_22","015_30_22","2CH","30","22","22","וידבר יחזקיהו על לב כל הלוים המשכילים שכל טוב ליהוה ויאכלו את המועד שבעת הימים מזבחים זבחי שלמים ומתודים ליהוה אלהי אבותיהם׃ ");
INSERT INTO heb_vpl VALUES ("R230_23","015_30_23","2CH","30","23","23","ויועצו כל הקהל לעשות שבעת ימים אחרים ויעשו שבעת ימים שמחה׃ ");
INSERT INTO heb_vpl VALUES ("R230_24","015_30_24","2CH","30","24","24","כי חזקיהו מלך יהודה הרים לקהל אלף פרים ושבעת אלפים צאן והשרים הרימו לקהל פרים אלף וצאן עשרת אלפים ויתקדשו כהנים לרב׃ ");
INSERT INTO heb_vpl VALUES ("R230_25","015_30_25","2CH","30","25","25","וישמחו כל קהל יהודה והכהנים והלוים וכל הקהל הבאים מישראל והגרים הבאים מארץ ישראל והיושבים ביהודה׃ ");
INSERT INTO heb_vpl VALUES ("R230_26","015_30_26","2CH","30","26","26","ותהי שמחה גדולה בירושלם כי מימי שלמה בן דויד מלך ישראל לא כזאת בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R230_27","015_30_27","2CH","30","27","27","ויקמו הכהנים הלוים ויברכו את העם וישמע בקולם ותבוא תפלתם למעון קדשו לשמים׃ ");
INSERT INTO heb_vpl VALUES ("R231_1","015_31_1","2CH","31","1","1","וככלות כל זאת יצאו כל ישראל הנמצאים לערי יהודה וישברו המצבות ויגדעו האשרים וינתצו את הבמות ואת המזבחת מכל יהודה ובנימן ובאפרים ומנשה עד לכלה וישובו כל בני ישראל איש לאחזתו לעריהם׃ ");
INSERT INTO heb_vpl VALUES ("R231_2","015_31_2","2CH","31","2","2","ויעמד יחזקיהו את מחלקות הכהנים והלוים על מחלקותם איש כפי עבדתו לכהנים וללוים לעלה ולשלמים לשרת ולהדות ולהלל בשערי מחנות יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R231_3","015_31_3","2CH","31","3","3","ומנת המלך מן רכושו לעלות לעלות הבקר והערב והעלות לשבתות ולחדשים ולמעדים ככתוב בתורת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R231_4","015_31_4","2CH","31","4","4","ויאמר לעם ליושבי ירושלם לתת מנת הכהנים והלוים למען יחזקו בתורת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R231_5","015_31_5","2CH","31","5","5","וכפרץ הדבר הרבו בני ישראל ראשית דגן תירוש ויצהר ודבש וכל תבואת שדה ומעשר הכל לרב הביאו׃ ");
INSERT INTO heb_vpl VALUES ("R231_6","015_31_6","2CH","31","6","6","ובני ישראל ויהודה היושבים בערי יהודה גם הם מעשר בקר וצאן ומעשר קדשים המקדשים ליהוה אלהיהם הביאו ויתנו ערמות ערמות׃ ");
INSERT INTO heb_vpl VALUES ("R231_7","015_31_7","2CH","31","7","7","בחדש השלשי החלו הערמות ליסוד ובחדש השביעי כלו׃ ");
INSERT INTO heb_vpl VALUES ("R231_8","015_31_8","2CH","31","8","8","ויבאו יחזקיהו והשרים ויראו את הערמות ויברכו את יהוה ואת עמו ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R231_9","015_31_9","2CH","31","9","9","וידרש יחזקיהו על הכהנים והלוים על הערמות׃ ");
INSERT INTO heb_vpl VALUES ("R231_10","015_31_10","2CH","31","10","10","ויאמר אליו עזריהו הכהן הראש לבית צדוק ויאמר מהחל התרומה לביא בית יהוה אכול ושבוע והותר עד לרוב כי יהוה ברך את עמו והנותר את ההמון הזה׃ ");
INSERT INTO heb_vpl VALUES ("R231_11","015_31_11","2CH","31","11","11","ויאמר יחזקיהו להכין לשכות בבית יהוה ויכינו׃ ");
INSERT INTO heb_vpl VALUES ("R231_12","015_31_12","2CH","31","12","12","ויביאו את התרומה והמעשר והקדשים באמונה ועליהם נגיד כונניהו הלוי ושמעי אחיהו משנה׃ ");
INSERT INTO heb_vpl VALUES ("R231_13","015_31_13","2CH","31","13","13","ויחיאל ועזזיהו ונחת ועשהאל וירימות ויוזבד ואליאל ויסמכיהו ומחת ובניהו פקידים מיד כונניהו ושמעי אחיו במפקד יחזקיהו המלך ועזריהו נגיד בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R231_14","015_31_14","2CH","31","14","14","וקורא בן ימנה הלוי השוער למזרחה על נדבות האלהים לתת תרומת יהוה וקדשי הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("R231_15","015_31_15","2CH","31","15","15","ועל ידו עדן ומנימן וישוע ושמעיהו אמריהו ושכניהו בערי הכהנים באמונה לתת לאחיהם במחלקות כגדול כקטן׃ ");
INSERT INTO heb_vpl VALUES ("R231_16","015_31_16","2CH","31","16","16","מלבד התיחשם לזכרים מבן שלוש שנים ולמעלה לכל הבא לבית יהוה לדבר יום ביומו לעבודתם במשמרותם כמחלקותיהם׃ ");
INSERT INTO heb_vpl VALUES ("R231_17","015_31_17","2CH","31","17","17","ואת התיחש הכהנים לבית אבותיהם והלוים מבן עשרים שנה ולמעלה במשמרותיהם במחלקותיהם׃ ");
INSERT INTO heb_vpl VALUES ("R231_18","015_31_18","2CH","31","18","18","ולהתיחש בכל טפם נשיהם ובניהם ובנותיהם לכל קהל כי באמונתם יתקדשו קדש׃ ");
INSERT INTO heb_vpl VALUES ("R231_19","015_31_19","2CH","31","19","19","ולבני אהרן הכהנים בשדי מגרש עריהם בכל עיר ועיר אנשים אשר נקבו בשמות לתת מנות לכל זכר בכהנים ולכל התיחש בלוים׃ ");
INSERT INTO heb_vpl VALUES ("R231_20","015_31_20","2CH","31","20","20","ויעש כזאת יחזקיהו בכל יהודה ויעש הטוב והישר והאמת לפני יהוה אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("R231_21","015_31_21","2CH","31","21","21","ובכל מעשה אשר החל בעבודת בית האלהים ובתורה ובמצוה לדרש לאלהיו בכל לבבו עשה והצליח׃ ");
INSERT INTO heb_vpl VALUES ("R232_1","015_32_1","2CH","32","1","1","אחרי הדברים והאמת האלה בא סנחריב מלך אשור ויבא ביהודה ויחן על הערים הבצרות ויאמר לבקעם אליו׃ ");
INSERT INTO heb_vpl VALUES ("R232_2","015_32_2","2CH","32","2","2","וירא יחזקיהו כי בא סנחריב ופניו למלחמה על ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R232_3","015_32_3","2CH","32","3","3","ויועץ עם שריו וגבריו לסתום את מימי העינות אשר מחוץ לעיר ויעזרוהו׃ ");
INSERT INTO heb_vpl VALUES ("R232_4","015_32_4","2CH","32","4","4","ויקבצו עם רב ויסתמו את כל המעינות ואת הנחל השוטף בתוך הארץ לאמר למה יבואו מלכי אשור ומצאו מים רבים׃ ");
INSERT INTO heb_vpl VALUES ("R232_5","015_32_5","2CH","32","5","5","ויתחזק ויבן את כל החומה הפרוצה ויעל על המגדלות ולחוצה החומה אחרת ויחזק את המלוא עיר דויד ויעש שלח לרב ומגנים׃ ");
INSERT INTO heb_vpl VALUES ("R232_6","015_32_6","2CH","32","6","6","ויתן שרי מלחמות על העם ויקבצם אליו אל רחוב שער העיר וידבר על לבבם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R232_7","015_32_7","2CH","32","7","7","חזקו ואמצו אל תיראו ואל תחתו מפני מלך אשור ומלפני כל ההמון אשר עמו כי עמנו רב מעמו׃ ");
INSERT INTO heb_vpl VALUES ("R232_8","015_32_8","2CH","32","8","8","עמו זרוע בשר ועמנו יהוה אלהינו לעזרנו ולהלחם מלחמתנו ויסמכו העם על דברי יחזקיהו מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R232_9","015_32_9","2CH","32","9","9","אחר זה שלח סנחריב מלך אשור עבדיו ירושלימה והוא על לכיש וכל ממשלתו עמו על יחזקיהו מלך יהודה ועל כל יהודה אשר בירושלם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R232_10","015_32_10","2CH","32","10","10","כה אמר סנחריב מלך אשור על מה אתם בטחים וישבים במצור בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R232_11","015_32_11","2CH","32","11","11","הלא יחזקיהו מסית אתכם לתת אתכם למות ברעב ובצמא לאמר יהוה אלהינו יצילנו מכף מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("R232_12","015_32_12","2CH","32","12","12","הלא הוא יחזקיהו הסיר את במתיו ואת מזבחתיו ויאמר ליהודה ולירושלם לאמר לפני מזבח אחד תשתחוו ועליו תקטירו׃ ");
INSERT INTO heb_vpl VALUES ("R232_13","015_32_13","2CH","32","13","13","הלא תדעו מה עשיתי אני ואבותי לכל עמי הארצות היכול יכלו אלהי גוי הארצות להציל את ארצם מידי׃ ");
INSERT INTO heb_vpl VALUES ("R232_14","015_32_14","2CH","32","14","14","מי בכל אלהי הגוים האלה אשר החרימו אבותי אשר יכול להציל את עמו מידי כי יוכל אלהיכם להציל אתכם מידי׃ ");
INSERT INTO heb_vpl VALUES ("R232_15","015_32_15","2CH","32","15","15","ועתה אל ישיא אתכם חזקיהו ואל יסית אתכם כזאת ואל תאמינו לו כי לא יוכל כל אלוה כל גוי וממלכה להציל עמו מידי ומיד אבותי אף כי אלהיכם לא יצילו אתכם מידי׃ ");
INSERT INTO heb_vpl VALUES ("R232_16","015_32_16","2CH","32","16","16","ועוד דברו עבדיו על יהוה האלהים ועל יחזקיהו עבדו׃ ");
INSERT INTO heb_vpl VALUES ("R232_17","015_32_17","2CH","32","17","17","וספרים כתב לחרף ליהוה אלהי ישראל ולאמר עליו לאמר כאלהי גוי הארצות אשר לא הצילו עמם מידי כן לא יציל אלהי יחזקיהו עמו מידי׃ ");
INSERT INTO heb_vpl VALUES ("R232_18","015_32_18","2CH","32","18","18","ויקראו בקול גדול יהודית על עם ירושלם אשר על החומה ליראם ולבהלם למען ילכדו את העיר׃ ");
INSERT INTO heb_vpl VALUES ("R232_19","015_32_19","2CH","32","19","19","וידברו אל אלהי ירושלם כעל אלהי עמי הארץ מעשה ידי האדם׃ ");
INSERT INTO heb_vpl VALUES ("R232_20","015_32_20","2CH","32","20","20","ויתפלל יחזקיהו המלך וישעיהו בן אמוץ הנביא על זאת ויזעקו השמים׃ ");
INSERT INTO heb_vpl VALUES ("R232_21","015_32_21","2CH","32","21","21","וישלח יהוה מלאך ויכחד כל גבור חיל ונגיד ושר במחנה מלך אשור וישב בבשת פנים לארצו ויבא בית אלהיו ומיציאו מעיו שם הפילהו בחרב׃ ");
INSERT INTO heb_vpl VALUES ("R232_22","015_32_22","2CH","32","22","22","ויושע יהוה את יחזקיהו ואת ישבי ירושלם מיד סנחריב מלך אשור ומיד כל וינהלם מסביב׃ ");
INSERT INTO heb_vpl VALUES ("R232_23","015_32_23","2CH","32","23","23","ורבים מביאים מנחה ליהוה לירושלם ומגדנות ליחזקיהו מלך יהודה וינשא לעיני כל הגוים מאחרי כן׃ ");
INSERT INTO heb_vpl VALUES ("R232_24","015_32_24","2CH","32","24","24","בימים ההם חלה יחזקיהו עד למות ויתפלל אל יהוה ויאמר לו ומופת נתן לו׃ ");
INSERT INTO heb_vpl VALUES ("R232_25","015_32_25","2CH","32","25","25","ולא כגמל עליו השיב יחזקיהו כי גבה לבו ויהי עליו קצף ועל יהודה וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R232_26","015_32_26","2CH","32","26","26","ויכנע יחזקיהו בגבה לבו הוא וישבי ירושלם ולא בא עליהם קצף יהוה בימי יחזקיהו׃ ");
INSERT INTO heb_vpl VALUES ("R232_27","015_32_27","2CH","32","27","27","ויהי ליחזקיהו עשר וכבוד הרבה מאד ואצרות עשה לו לכסף ולזהב ולאבן יקרה ולבשמים ולמגנים ולכל כלי חמדה׃ ");
INSERT INTO heb_vpl VALUES ("R232_28","015_32_28","2CH","32","28","28","ומסכנות לתבואת דגן ותירוש ויצהר וארות לכל בהמה ובהמה ועדרים לאורות׃ ");
INSERT INTO heb_vpl VALUES ("R232_29","015_32_29","2CH","32","29","29","וערים עשה לו ומקנה צאן ובקר לרב כי נתן לו אלהים רכוש רב מאד׃ ");
INSERT INTO heb_vpl VALUES ("R232_30","015_32_30","2CH","32","30","30","והוא יחזקיהו סתם את מוצא מימי גיחון העליון ויישרם למטה מערבה לעיר דויד ויצלח יחזקיהו בכל מעשהו׃ ");
INSERT INTO heb_vpl VALUES ("R232_31","015_32_31","2CH","32","31","31","וכן במליצי שרי בבל המשלחים עליו לדרש המופת אשר היה בארץ עזבו האלהים לנסותו לדעת כל בלבבו׃ ");
INSERT INTO heb_vpl VALUES ("R232_32","015_32_32","2CH","32","32","32","ויתר דברי יחזקיהו וחסדיו הנם כתובים בחזון ישעיהו בן אמוץ הנביא על ספר מלכי יהודה וישראל׃ ");
INSERT INTO heb_vpl VALUES ("R232_33","015_32_33","2CH","32","33","33","וישכב יחזקיהו עם אבתיו ויקברהו במעלה קברי בני דויד וכבוד עשו לו במותו כל יהודה וישבי ירושלם וימלך מנשה בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R233_1","015_33_1","2CH","33","1","1","בן שתים עשרה שנה מנשה במלכו וחמשים וחמש שנה מלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R233_2","015_33_2","2CH","33","2","2","ויעש הרע בעיני יהוה כתועבות הגוים אשר הוריש יהוה מפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R233_3","015_33_3","2CH","33","3","3","וישב ויבן את הבמות אשר נתץ יחזקיהו אביו ויקם מזבחות לבעלים ויעש אשרות וישתחו לכל צבא השמים ויעבד אתם׃ ");
INSERT INTO heb_vpl VALUES ("R233_4","015_33_4","2CH","33","4","4","ובנה מזבחות בבית יהוה אשר אמר יהוה בירושלם יהיה שמי לעולם׃ ");
INSERT INTO heb_vpl VALUES ("R233_5","015_33_5","2CH","33","5","5","ויבן מזבחות לכל צבא השמים בשתי חצרות בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R233_6","015_33_6","2CH","33","6","6","והוא העביר את בניו באש בגי בן הנם ועונן ונחש וכשף ועשה אוב וידעוני הרבה לעשות הרע בעיני יהוה להכעיסו׃ ");
INSERT INTO heb_vpl VALUES ("R233_7","015_33_7","2CH","33","7","7","וישם את פסל הסמל אשר עשה בבית האלהים אשר אמר אלהים אל דויד ואל שלמה בנו בבית הזה ובירושלם אשר בחרתי מכל שבטי ישראל אשים את שמי לעילום׃ ");
INSERT INTO heb_vpl VALUES ("R233_8","015_33_8","2CH","33","8","8","ולא אוסיף להסיר את רגל ישראל מעל האדמה אשר העמדתי לאבתיכם רק אם ישמרו לעשות את כל אשר צויתים לכל התורה והחקים והמשפטים ביד משה׃ ");
INSERT INTO heb_vpl VALUES ("R233_9","015_33_9","2CH","33","9","9","ויתע מנשה את יהודה וישבי ירושלם לעשות רע מן הגוים אשר השמיד יהוה מפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R233_10","015_33_10","2CH","33","10","10","וידבר יהוה אל מנשה ואל עמו ולא הקשיבו׃ ");
INSERT INTO heb_vpl VALUES ("R233_11","015_33_11","2CH","33","11","11","ויבא יהוה עליהם את שרי הצבא אשר למלך אשור וילכדו את מנשה בחחים ויאסרהו בנחשתים ויוליכהו בבלה׃ ");
INSERT INTO heb_vpl VALUES ("R233_12","015_33_12","2CH","33","12","12","וכהצר לו חלה את פני יהוה אלהיו ויכנע מאד מלפני אלהי אבתיו׃ ");
INSERT INTO heb_vpl VALUES ("R233_13","015_33_13","2CH","33","13","13","ויתפלל אליו ויעתר לו וישמע תחנתו וישיבהו ירושלם למלכותו וידע מנשה כי יהוה הוא האלהים׃ ");
INSERT INTO heb_vpl VALUES ("R233_14","015_33_14","2CH","33","14","14","ואחרי כן בנה חומה חיצונה לעיר דויד מערבה לגיחון בנחל ולבוא בשער הדגים וסבב לעפל ויגביהה מאד וישם שרי חיל בכל הערים הבצרות ביהודה׃ ");
INSERT INTO heb_vpl VALUES ("R233_15","015_33_15","2CH","33","15","15","ויסר את אלהי הנכר ואת הסמל מבית יהוה וכל המזבחות אשר בנה בהר בית יהוה ובירושלם וישלך חוצה לעיר׃ ");
INSERT INTO heb_vpl VALUES ("R233_16","015_33_16","2CH","33","16","16","ויכן את מזבח יהוה ויזבח עליו זבחי שלמים ותודה ויאמר ליהודה לעבוד את יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R233_17","015_33_17","2CH","33","17","17","אבל עוד העם זבחים בבמות רק ליהוה אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("R233_18","015_33_18","2CH","33","18","18","ויתר דברי מנשה ותפלתו אל אלהיו ודברי החזים המדברים אליו בשם יהוה אלהי ישראל הנם על דברי מלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R233_19","015_33_19","2CH","33","19","19","ותפלתו והעתר לו וכל חטאתו ומעלו והמקמות אשר בנה בהם במות והעמיד האשרים והפסלים לפני הכנעו הנם כתובים על דברי חוזי׃ ");
INSERT INTO heb_vpl VALUES ("R233_20","015_33_20","2CH","33","20","20","וישכב מנשה עם אבתיו ויקברהו ביתו וימלך אמון בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R233_21","015_33_21","2CH","33","21","21","בן עשרים ושתים שנה אמון במלכו ושתים שנים מלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R233_22","015_33_22","2CH","33","22","22","ויעש הרע בעיני יהוה כאשר עשה מנשה אביו ולכל הפסילים אשר עשה מנשה אביו זבח אמון ויעבדם׃ ");
INSERT INTO heb_vpl VALUES ("R233_23","015_33_23","2CH","33","23","23","ולא נכנע מלפני יהוה כהכנע מנשה אביו כי הוא אמון הרבה אשמה׃ ");
INSERT INTO heb_vpl VALUES ("R233_24","015_33_24","2CH","33","24","24","ויקשרו עליו עבדיו וימיתהו בביתו׃ ");
INSERT INTO heb_vpl VALUES ("R233_25","015_33_25","2CH","33","25","25","ויכו עם הארץ את כל הקשרים על המלך אמון וימליכו עם הארץ את יאשיהו בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R234_1","015_34_1","2CH","34","1","1","בן שמונה שנים יאשיהו במלכו ושלשים ואחת שנה מלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R234_2","015_34_2","2CH","34","2","2","ויעש הישר בעיני יהוה וילך בדרכי דויד אביו ולא סר ימין ושמאול׃ ");
INSERT INTO heb_vpl VALUES ("R234_3","015_34_3","2CH","34","3","3","ובשמונה שנים למלכו והוא עודנו נער החל לדרוש לאלהי דויד אביו ובשתים עשרה שנה החל לטהר את יהודה וירושלם מן הבמות והאשרים והפסלים והמסכות׃ ");
INSERT INTO heb_vpl VALUES ("R234_4","015_34_4","2CH","34","4","4","וינתצו לפניו את מזבחות הבעלים והחמנים אשר למעלה מעליהם גדע והאשרים והפסלים והמסכות שבר והדק ויזרק על פני הקברים הזבחים להם׃ ");
INSERT INTO heb_vpl VALUES ("R234_5","015_34_5","2CH","34","5","5","ועצמות כהנים שרף על מזבחותים ויטהר את יהודה ואת ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R234_6","015_34_6","2CH","34","6","6","ובערי מנשה ואפרים ושמעון ועד נפתלי בהר בתיהם סביב׃ ");
INSERT INTO heb_vpl VALUES ("R234_7","015_34_7","2CH","34","7","7","וינתץ את המזבחות ואת האשרים והפסלים כתת להדק וכל החמנים גדע בכל ארץ ישראל וישב לירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R234_8","015_34_8","2CH","34","8","8","ובשנת שמונה עשרה למלכו לטהר הארץ והבית שלח את שפן בן אצליהו ואת מעשיהו שר העיר ואת יואח בן יואחז המזכיר לחזק את בית יהוה אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("R234_9","015_34_9","2CH","34","9","9","ויבאו אל חלקיהו הכהן הגדול ויתנו את הכסף המובא בית אלהים אשר אספו הלוים שמרי הסף מיד מנשה ואפרים ומכל שארית ישראל ומכל יהודה ובנימן וישבי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R234_10","015_34_10","2CH","34","10","10","ויתנו על יד עשה המלאכה המפקדים בבית יהוה ויתנו אתו עושי המלאכה אשר עשים בבית יהוה לבדוק ולחזק הבית׃ ");
INSERT INTO heb_vpl VALUES ("R234_11","015_34_11","2CH","34","11","11","ויתנו לחרשים ולבנים לקנות אבני מחצב ועצים למחברות ולקרות את הבתים אשר השחיתו מלכי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R234_12","015_34_12","2CH","34","12","12","והאנשים עשים באמונה במלאכה ועליהם מפקדים יחת ועבדיהו הלוים מן בני מררי וזכריה ומשלם מן בני הקהתים לנצח והלוים כל מבין בכלי שיר׃ ");
INSERT INTO heb_vpl VALUES ("R234_13","015_34_13","2CH","34","13","13","ועל הסבלים ומנצחים לכל עשה מלאכה לעבודה ועבודה ומהלוים סופרים ושטרים ושוערים׃ ");
INSERT INTO heb_vpl VALUES ("R234_14","015_34_14","2CH","34","14","14","ובהוציאם את הכסף המובא בית יהוה מצא חלקיהו הכהן את ספר תורת יהוה ביד משה׃ ");
INSERT INTO heb_vpl VALUES ("R234_15","015_34_15","2CH","34","15","15","ויען חלקיהו ויאמר אל שפן הסופר ספר התורה מצאתי בבית יהוה ויתן חלקיהו את הספר אל שפן׃ ");
INSERT INTO heb_vpl VALUES ("R234_16","015_34_16","2CH","34","16","16","ויבא שפן את הספר אל המלך וישב עוד את המלך דבר לאמר כל אשר נתן ביד עבדיך הם עשים׃ ");
INSERT INTO heb_vpl VALUES ("R234_17","015_34_17","2CH","34","17","17","ויתיכו את הכסף הנמצא בבית יהוה ויתנוהו על יד המפקדים ועל יד עושי המלאכה׃ ");
INSERT INTO heb_vpl VALUES ("R234_18","015_34_18","2CH","34","18","18","ויגד שפן הסופר למלך לאמר ספר נתן לי חלקיהו הכהן ויקרא בו שפן לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("R234_19","015_34_19","2CH","34","19","19","ויהי כשמע המלך את דברי התורה ויקרע את בגדיו׃ ");
INSERT INTO heb_vpl VALUES ("R234_20","015_34_20","2CH","34","20","20","ויצו המלך את חלקיהו ואת אחיקם בן שפן ואת עבדון בן מיכה ואת שפן הסופר ואת עשיה עבד המלך לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R234_21","015_34_21","2CH","34","21","21","לכו דרשו את יהוה בעדי ובעד הנשאר בישראל וביהודה על דברי הספר אשר נמצא כי גדולה חמת יהוה אשר נתכה בנו על אשר לא שמרו אבותינו את דבר יהוה לעשות ככל הכתוב על הספר הזה׃ ");
INSERT INTO heb_vpl VALUES ("R234_22","015_34_22","2CH","34","22","22","וילך חלקיהו ואשר המלך אל חלדה הנביאה אשת שלם בן תוקהת בן חסרה שומר הבגדים והיא יושבת בירושלם במשנה וידברו אליה כזאת׃ ");
INSERT INTO heb_vpl VALUES ("R234_23","015_34_23","2CH","34","23","23","ותאמר להם כה אמר יהוה אלהי ישראל אמרו לאיש אשר שלח אתכם אלי׃ ");
INSERT INTO heb_vpl VALUES ("R234_24","015_34_24","2CH","34","24","24","כה אמר יהוה הנני מביא רעה על המקום הזה ועל יושביו את כל האלות הכתובות על הספר אשר קראו לפני מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("R234_25","015_34_25","2CH","34","25","25","תחת אשר עזבוני ויקטירו לאלהים אחרים למען הכעיסני בכל מעשי ידיהם ותתך חמתי במקום הזה ולא תכבה׃ ");
INSERT INTO heb_vpl VALUES ("R234_26","015_34_26","2CH","34","26","26","ואל מלך יהודה השלח אתכם לדרוש ביהוה כה תאמרו אליו כה אמר יהוה אלהי ישראל הדברים אשר שמעת׃ ");
INSERT INTO heb_vpl VALUES ("R234_27","015_34_27","2CH","34","27","27","יען רך לבבך ותכנע מלפני אלהים בשמעך את דבריו על המקום הזה ועל ישביו ותכנע לפני ותקרע את בגדיך ותבך לפני וגם אני שמעתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R234_28","015_34_28","2CH","34","28","28","הנני אספך אל אבתיך ונאספת אל קברתיך בשלום ולא תראינה עיניך בכל הרעה אשר אני מביא על המקום הזה ועל ישביו וישיבו את המלך דבר׃ ");
INSERT INTO heb_vpl VALUES ("R234_29","015_34_29","2CH","34","29","29","וישלח המלך ויאסף את כל זקני יהודה וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R234_30","015_34_30","2CH","34","30","30","ויעל המלך בית יהוה וכל איש יהודה וישבי ירושלם והכהנים והלוים וכל העם מגדול ועד קטן ויקרא באזניהם את כל דברי ספר הברית הנמצא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R234_31","015_34_31","2CH","34","31","31","ויעמד המלך על עמדו ויכרת את הברית לפני יהוה ללכת אחרי יהוה ולשמור את מצותיו ועדותיו וחקיו בכל לבבו ובכל נפשו לעשות את דברי הברית הכתובים על הספר הזה׃ ");
INSERT INTO heb_vpl VALUES ("R234_32","015_34_32","2CH","34","32","32","ויעמד את כל הנמצא בירושלם ובנימן ויעשו ישבי ירושלם כברית אלהים אלהי אבותיהם׃ ");
INSERT INTO heb_vpl VALUES ("R234_33","015_34_33","2CH","34","33","33","ויסר יאשיהו את כל התועבות מכל הארצות אשר לבני ישראל ויעבד את כל הנמצא בישראל לעבוד את יהוה אלהיהם כל ימיו לא סרו מאחרי יהוה אלהי אבותיהם׃ ");
INSERT INTO heb_vpl VALUES ("R235_1","015_35_1","2CH","35","1","1","ויעש יאשיהו בירושלם פסח ליהוה וישחטו הפסח בארבעה עשר לחדש הראשון׃ ");
INSERT INTO heb_vpl VALUES ("R235_2","015_35_2","2CH","35","2","2","ויעמד הכהנים על משמרותם ויחזקם לעבודת בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R235_3","015_35_3","2CH","35","3","3","ויאמר ללוים המבונים לכל ישראל הקדושים ליהוה תנו את ארון הקדש בבית אשר בנה שלמה בן דויד מלך ישראל אין לכם משא בכתף עתה עבדו את יהוה אלהיכם ואת עמו ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R235_4","015_35_4","2CH","35","4","4","והכונו לבית אבותיכם כמחלקותיכם בכתב דויד מלך ישראל ובמכתב שלמה בנו׃ ");
INSERT INTO heb_vpl VALUES ("R235_5","015_35_5","2CH","35","5","5","ועמדו בקדש לפלגות בית האבות לאחיכם בני העם וחלקת בית אב ללוים׃ ");
INSERT INTO heb_vpl VALUES ("R235_6","015_35_6","2CH","35","6","6","ושחטו הפסח והתקדשו והכינו לאחיכם לעשות כדבר יהוה ביד משה׃ ");
INSERT INTO heb_vpl VALUES ("R235_7","015_35_7","2CH","35","7","7","וירם יאשיהו לבני העם צאן כבשים ובני עזים הכל לפסחים לכל הנמצא למספר שלשים אלף ובקר שלשת אלפים אלה מרכוש המלך׃ ");
INSERT INTO heb_vpl VALUES ("R235_8","015_35_8","2CH","35","8","8","ושריו לנדבה לעם לכהנים וללוים הרימו חלקיה וזכריהו ויחיאל נגידי בית האלהים לכהנים נתנו לפסחים אלפים ושש מאות ובקר שלש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R235_9","015_35_9","2CH","35","9","9","וכונניהו ושמעיהו ונתנאל אחיו וחשביהו ויעיאל ויוזבד שרי הלוים הרימו ללוים לפסחים חמשת אלפים ובקר חמש מאות׃ ");
INSERT INTO heb_vpl VALUES ("R235_10","015_35_10","2CH","35","10","10","ותכון העבודה ויעמדו הכהנים על עמדם והלוים על מחלקותם כמצות המלך׃ ");
INSERT INTO heb_vpl VALUES ("R235_11","015_35_11","2CH","35","11","11","וישחטו הפסח ויזרקו הכהנים מידם והלוים מפשיטים׃ ");
INSERT INTO heb_vpl VALUES ("R235_12","015_35_12","2CH","35","12","12","ויסירו העלה לתתם למפלגות לבית אבות לבני העם להקריב ליהוה ככתוב בספר משה וכן לבקר׃ ");
INSERT INTO heb_vpl VALUES ("R235_13","015_35_13","2CH","35","13","13","ויבשלו הפסח באש כמשפט והקדשים בשלו בסירות ובדודים ובצלחות ויריצו לכל בני העם׃ ");
INSERT INTO heb_vpl VALUES ("R235_14","015_35_14","2CH","35","14","14","ואחר הכינו להם ולכהנים כי הכהנים בני אהרן בהעלות העולה והחלבים עד לילה והלוים הכינו להם ולכהנים בני אהרן׃ ");
INSERT INTO heb_vpl VALUES ("R235_15","015_35_15","2CH","35","15","15","והמשררים בני אסף על מעמדם כמצות דויד ואסף והימן וידתון חוזה המלך והשערים לשער ושער אין להם לסור מעל עבדתם כי אחיהם הלוים הכינו להם׃ ");
INSERT INTO heb_vpl VALUES ("R235_16","015_35_16","2CH","35","16","16","ותכון כל עבודת יהוה ביום ההוא לעשות הפסח והעלות עלות על מזבח יהוה כמצות המלך יאשיהו׃ ");
INSERT INTO heb_vpl VALUES ("R235_17","015_35_17","2CH","35","17","17","ויעשו בני ישראל הנמצאים את הפסח בעת ההיא ואת חג המצות שבעת ימים׃ ");
INSERT INTO heb_vpl VALUES ("R235_18","015_35_18","2CH","35","18","18","ולא נעשה פסח כמהו בישראל מימי שמואל הנביא וכל מלכי ישראל לא עשו כפסח אשר עשה יאשיהו והכהנים והלוים וכל יהודה וישראל הנמצא ויושבי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R235_19","015_35_19","2CH","35","19","19","בשמונה עשרה שנה למלכות יאשיהו נעשה הפסח הזה׃ ");
INSERT INTO heb_vpl VALUES ("R235_20","015_35_20","2CH","35","20","20","אחרי כל זאת אשר הכין יאשיהו את הבית עלה נכו מלך מצרים להלחם בכרכמיש על פרת ויצא לקראתו יאשיהו׃ ");
INSERT INTO heb_vpl VALUES ("R235_21","015_35_21","2CH","35","21","21","וישלח אליו מלאכים לאמר מה לי ולך מלך יהודה לא עליך אתה היום כי אל בית מלחמתי ואלהים אמר לבהלני חדל לך מאלהים אשר עמי ואל ישחיתך׃ ");
INSERT INTO heb_vpl VALUES ("R235_22","015_35_22","2CH","35","22","22","ולא הסב יאשיהו פניו ממנו כי להלחם בו התחפש ולא שמע אל דברי נכו מפי אלהים ויבא להלחם בבקעת מגדו׃ ");
INSERT INTO heb_vpl VALUES ("R235_23","015_35_23","2CH","35","23","23","וירו הירים למלך יאשיהו ויאמר המלך לעבדיו העבירוני כי החליתי מאד׃ ");
INSERT INTO heb_vpl VALUES ("R235_24","015_35_24","2CH","35","24","24","ויעבירהו עבדיו מן המרכבה וירכיבהו על רכב המשנה אשר לו ויוליכהו ירושלם וימת ויקבר בקברות אבתיו וכל יהודה וירושלם מתאבלים על יאשיהו׃ ");
INSERT INTO heb_vpl VALUES ("R235_25","015_35_25","2CH","35","25","25","ויקונן ירמיהו על יאשיהו ויאמרו כל השרים והשרות בקינותיהם על יאשיהו עד היום ויתנום לחק על ישראל והנם כתובים על הקינות׃ ");
INSERT INTO heb_vpl VALUES ("R235_26","015_35_26","2CH","35","26","26","ויתר דברי יאשיהו וחסדיו ככתוב בתורת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R235_27","015_35_27","2CH","35","27","27","ודבריו הראשנים והאחרנים הנם כתובים על ספר מלכי ישראל ויהודה׃ ");
INSERT INTO heb_vpl VALUES ("R236_1","015_36_1","2CH","36","1","1","ויקחו עם הארץ את יהואחז בן יאשיהו וימליכהו תחת אביו בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R236_2","015_36_2","2CH","36","2","2","בן שלוש ועשרים שנה יואחז במלכו ושלשה חדשים מלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R236_3","015_36_3","2CH","36","3","3","ויסירהו מלך מצרים בירושלם ויענש את הארץ מאה ככר כסף וככר זהב׃ ");
INSERT INTO heb_vpl VALUES ("R236_4","015_36_4","2CH","36","4","4","וימלך מלך מצרים את אליקים אחיו על יהודה וירושלם ויסב את שמו יהויקים ואת יואחז אחיו לקח נכו ויביאהו מצרימה׃ ");
INSERT INTO heb_vpl VALUES ("R236_5","015_36_5","2CH","36","5","5","בן עשרים וחמש שנה יהויקים במלכו ואחת עשרה שנה מלך בירושלם ויעש הרע בעיני יהוה אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("R236_6","015_36_6","2CH","36","6","6","עליו עלה נבוכדנאצר מלך בבל ויאסרהו בנחשתים להליכו בבלה׃ ");
INSERT INTO heb_vpl VALUES ("R236_7","015_36_7","2CH","36","7","7","ומכלי בית יהוה הביא נבוכדנאצר לבבל ויתנם בהיכלו בבבל׃ ");
INSERT INTO heb_vpl VALUES ("R236_8","015_36_8","2CH","36","8","8","ויתר דברי יהויקים ותעבתיו אשר עשה והנמצא עליו הנם כתובים על ספר מלכי ישראל ויהודה וימלך יהויכין בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("R236_9","015_36_9","2CH","36","9","9","בן שמונה שנים יהויכין במלכו ושלשה חדשים ועשרת ימים מלך בירושלם ויעש הרע בעיני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R236_10","015_36_10","2CH","36","10","10","ולתשובת השנה שלח המלך נבוכדנאצר ויבאהו בבלה עם כלי חמדת בית יהוה וימלך את צדקיהו אחיו על יהודה וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R236_11","015_36_11","2CH","36","11","11","בן עשרים ואחת שנה צדקיהו במלכו ואחת עשרה שנה מלך בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R236_12","015_36_12","2CH","36","12","12","ויעש הרע בעיני יהוה אלהיו לא נכנע מלפני ירמיהו הנביא מפי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("R236_13","015_36_13","2CH","36","13","13","וגם במלך נבוכדנאצר מרד אשר השביעו באלהים ויקש את ערפו ויאמץ את לבבו משוב אל יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("R236_14","015_36_14","2CH","36","14","14","גם כל שרי הכהנים והעם הרבו למעול מעל ככל תעבות הגוים ויטמאו את בית יהוה אשר הקדיש בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("R236_15","015_36_15","2CH","36","15","15","וישלח יהוה אלהי אבותיהם עליהם ביד מלאכיו השכם ושלוח כי חמל על עמו ועל מעונו׃ ");
INSERT INTO heb_vpl VALUES ("R236_16","015_36_16","2CH","36","16","16","ויהיו מלעבים במלאכי האלהים ובוזים דבריו ומתעתעים בנבאיו עד עלות חמת יהוה בעמו עד לאין מרפא׃ ");
INSERT INTO heb_vpl VALUES ("R236_17","015_36_17","2CH","36","17","17","ויעל עליהם את מלך כשדיים ויהרג בחוריהם בחרב בבית מקדשם ולא חמל על בחור ובתולה זקן וישש הכל נתן בידו׃ ");
INSERT INTO heb_vpl VALUES ("R236_18","015_36_18","2CH","36","18","18","וכל כלי בית האלהים הגדלים והקטנים ואצרות בית יהוה ואצרות המלך ושריו הכל הביא בבל׃ ");
INSERT INTO heb_vpl VALUES ("R236_19","015_36_19","2CH","36","19","19","וישרפו את בית האלהים וינתצו את חומת ירושלם וכל ארמנותיה שרפו באש וכל כלי מחמדיה להשחית׃ ");
INSERT INTO heb_vpl VALUES ("R236_20","015_36_20","2CH","36","20","20","ויגל השארית מן החרב אל בבל ויהיו לו ולבניו לעבדים עד מלך מלכות פרס׃ ");
INSERT INTO heb_vpl VALUES ("R236_21","015_36_21","2CH","36","21","21","למלאות דבר יהוה בפי ירמיהו עד רצתה הארץ את שבתותיה כל ימי השמה שבתה למלאות שבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("R236_22","015_36_22","2CH","36","22","22","ובשנת אחת לכורש מלך פרס לכלות דבר יהוה בפי ירמיהו העיר יהוה את רוח כורש מלך פרס ויעבר קול בכל מלכותו וגם במכתב לאמר׃ ");
INSERT INTO heb_vpl VALUES ("R236_23","015_36_23","2CH","36","23","23","כה אמר כורש מלך פרס כל ממלכות הארץ נתן לי יהוה אלהי השמים והוא פקד עלי לבנות לו בית בירושלם אשר ביהודה מי בכם מכל עמו יהוה אלהיו עמו ויעל׃ ");
INSERT INTO heb_vpl VALUES ("ER1_1","016_1_1","EZR","1","1","1","ובשנת אחת לכורש מלך פרס לכלות דבר יהוה מפי ירמיה העיר יהוה את רוח כרש מלך פרס ויעבר קול בכל מלכותו וגם במכתב לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ER1_2","016_1_2","EZR","1","2","2","כה אמר כרש מלך פרס כל ממלכות הארץ נתן לי יהוה אלהי השמים והוא פקד עלי לבנות לו בית בירושלם אשר ביהודה׃ ");
INSERT INTO heb_vpl VALUES ("ER1_3","016_1_3","EZR","1","3","3","מי בכם מכל עמו יהי אלהיו עמו ויעל לירושלם אשר ביהודה ויבן את בית יהוה אלהי ישראל הוא האלהים אשר בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER1_4","016_1_4","EZR","1","4","4","וכל הנשאר מכל המקמות אשר הוא גר שם ינשאוהו אנשי מקמו בכסף ובזהב וברכוש ובבהמה עם הנדבה לבית האלהים אשר בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER1_5","016_1_5","EZR","1","5","5","ויקומו ראשי האבות ליהודה ובנימן והכהנים והלוים לכל העיר האלהים את רוחו לעלות לבנות את בית יהוה אשר בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER1_6","016_1_6","EZR","1","6","6","וכל סביבתיהם חזקו בידיהם בכלי כסף בזהב ברכוש ובבהמה ובמגדנות לבד על כל התנדב׃ ");
INSERT INTO heb_vpl VALUES ("ER1_7","016_1_7","EZR","1","7","7","והמלך כורש הוציא את כלי בית יהוה אשר הוציא נבוכדנצר מירושלם ויתנם בבית אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("ER1_8","016_1_8","EZR","1","8","8","ויוציאם כורש מלך פרס על יד מתרדת הגזבר ויספרם לששבצר הנשיא ליהודה׃ ");
INSERT INTO heb_vpl VALUES ("ER1_9","016_1_9","EZR","1","9","9","ואלה מספרם אגרטלי זהב שלשים אגרטלי כסף אלף מחלפים תשעה ועשרים׃ ");
INSERT INTO heb_vpl VALUES ("ER1_10","016_1_10","EZR","1","10","10","כפורי זהב שלשים כפורי כסף משנים ארבע מאות ועשרה כלים אחרים אלף׃ ");
INSERT INTO heb_vpl VALUES ("ER1_11","016_1_11","EZR","1","11","11","כל כלים לזהב ולכסף חמשת אלפים וארבע מאות הכל העלה ששבצר עם העלות הגולה מבבל לירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER2_1","016_2_1","EZR","2","1","1","ואלה בני המדינה העלים משבי הגולה אשר הגלה נבוכדנצור מלך בבל לבבל וישובו לירושלם ויהודה איש לעירו׃ ");
INSERT INTO heb_vpl VALUES ("ER2_2","016_2_2","EZR","2","2","2","אשר באו עם זרבבל ישוע נחמיה שריה רעליה מרדכי בלשן מספר בגוי רחום בענה מספר אנשי עם ישראל׃ ");
