INSERT INTO heb_vpl VALUES ("ER2_68","016_2_68","EZR","2","68","68","ומראשי האבות בבואם לבית יהוה אשר בירושלם התנדבו לבית האלהים להעמידו על מכונו׃ ");
INSERT INTO heb_vpl VALUES ("ER2_69","016_2_69","EZR","2","69","69","ככחם נתנו לאוצר המלאכה זהב דרכמונים שש רבאות ואלף וכסף מנים חמשת אלפים וכתנת כהנים מאה׃ ");
INSERT INTO heb_vpl VALUES ("ER2_70","016_2_70","EZR","2","70","70","וישבו הכהנים והלוים ומן העם והמשררים והשוערים והנתינים בעריהם וכל ישראל בעריהם׃ ");
INSERT INTO heb_vpl VALUES ("ER3_1","016_3_1","EZR","3","1","1","ויגע החדש השביעי ובני ישראל בערים ויאספו העם כאיש אחד אל ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER3_2","016_3_2","EZR","3","2","2","ויקם ישוע בן יוצדק ואחיו הכהנים וזרבבל בן שאלתיאל ואחיו ויבנו את מזבח אלהי ישראל להעלות עליו עלות ככתוב בתורת משה איש האלהים׃ ");
INSERT INTO heb_vpl VALUES ("ER3_3","016_3_3","EZR","3","3","3","ויכינו המזבח על מכונתיו כי באימה עליהם מעמי הארצות ויעל עליו עלות ליהוה עלות לבקר ולערב׃ ");
INSERT INTO heb_vpl VALUES ("ER3_4","016_3_4","EZR","3","4","4","ויעשו את חג הסכות ככתוב ועלת יום ביום במספר כמשפט דבר יום ביומו׃ ");
INSERT INTO heb_vpl VALUES ("ER3_5","016_3_5","EZR","3","5","5","ואחריכן עלת תמיד ולחדשים ולכל מועדי יהוה המקדשים ולכל מתנדב נדבה ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("ER3_6","016_3_6","EZR","3","6","6","מיום אחד לחדש השביעי החלו להעלות עלות ליהוה והיכל יהוה לא יסד׃ ");
INSERT INTO heb_vpl VALUES ("ER3_7","016_3_7","EZR","3","7","7","ויתנו כסף לחצבים ולחרשים ומאכל ומשתה ושמן לצדנים ולצרים להביא עצי ארזים מן הלבנון אל ים יפוא כרשיון כורש מלך פרס עליהם׃ ");
INSERT INTO heb_vpl VALUES ("ER3_8","016_3_8","EZR","3","8","8","ובשנה השנית לבואם אל בית האלהים לירושלם בחדש השני החלו זרבבל בן שאלתיאל וישוע בן יוצדק ושאר אחיהם הכהנים והלוים וכל הבאים מהשבי ירושלם ויעמידו את הלוים מבן עשרים שנה ומעלה לנצח על מלאכת בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ER3_9","016_3_9","EZR","3","9","9","ויעמד ישוע בניו ואחיו קדמיאל ובניו בני יהודה כאחד לנצח על עשה המלאכה בבית האלהים בני חנדד בניהם ואחיהם הלוים׃ ");
INSERT INTO heb_vpl VALUES ("ER3_10","016_3_10","EZR","3","10","10","ויסדו הבנים את היכל יהוה ויעמידו הכהנים מלבשים בחצצרות והלוים בני אסף במצלתים להלל את יהוה על ידי דויד מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ER3_11","016_3_11","EZR","3","11","11","ויענו בהלל ובהודת ליהוה כי טוב כי לעולם חסדו על ישראל וכל העם הריעו תרועה גדולה בהלל ליהוה על הוסד בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ER3_12","016_3_12","EZR","3","12","12","ורבים מהכהנים והלוים וראשי האבות הזקנים אשר ראו את הבית הראשון ביסדו זה הבית בעיניהם בכים בקול גדול ורבים בתרועה בשמחה להרים קול׃ ");
INSERT INTO heb_vpl VALUES ("ER3_13","016_3_13","EZR","3","13","13","ואין העם מכירים קול תרועת השמחה לקול בכי העם כי העם מריעים תרועה גדולה והקול נשמע עד למרחוק׃ ");
INSERT INTO heb_vpl VALUES ("ER4_1","016_4_1","EZR","4","1","1","וישמעו צרי יהודה ובנימן כי בני הגולה בונים היכל ליהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ER4_2","016_4_2","EZR","4","2","2","ויגשו אל זרבבל ואל ראשי האבות ויאמרו להם נבנה עמכם כי ככם נדרוש לאלהיכם ולא אנחנו זבחים מימי אסר חדן מלך אשור המעלה אתנו פה׃ ");
INSERT INTO heb_vpl VALUES ("ER4_3","016_4_3","EZR","4","3","3","ויאמר להם זרבבל וישוע ושאר ראשי האבות לישראל לא לכם ולנו לבנות בית לאלהינו כי אנחנו יחד נבנה ליהוה אלהי ישראל כאשר צונו המלך כורש מלך פרס׃ ");
INSERT INTO heb_vpl VALUES ("ER4_4","016_4_4","EZR","4","4","4","ויהי עם הארץ מרפים ידי עם יהודה ומבלהים אותם לבנות׃ ");
INSERT INTO heb_vpl VALUES ("ER4_5","016_4_5","EZR","4","5","5","וסכרים עליהם יועצים להפר עצתם כל ימי כורש מלך פרס ועד מלכות דריוש מלך פרס׃ ");
INSERT INTO heb_vpl VALUES ("ER4_6","016_4_6","EZR","4","6","6","ובמלכות אחשורוש בתחלת מלכותו כתבו שטנה על ישבי יהודה וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER4_7","016_4_7","EZR","4","7","7","ובימי ארתחששתא כתב בשלם מתרדת טבאל ושאר כנותו על ארתחששתא מלך פרס וכתב הנשתון כתוב ארמית ומתרגם ארמית׃ ");
INSERT INTO heb_vpl VALUES ("ER4_8","016_4_8","EZR","4","8","8","רחום בעל טעם ושמשי ספרא כתבו אגרה חדה על ירושלם לארתחששתא מלכא כנמא׃ ");
INSERT INTO heb_vpl VALUES ("ER4_9","016_4_9","EZR","4","9","9","אדין רחום בעל טעם ושמשי ספרא ושאר כנותהון דיניא ואפרסתכיא טרפליא אפרסיא ארכוי בבליא שושנכיא דהוא עלמיא׃ ");
INSERT INTO heb_vpl VALUES ("ER4_10","016_4_10","EZR","4","10","10","ושאר אמיא די הגלי אסנפר רבא ויקירא והותב המו בקריה די שמרין ושאר עבר נהרה וכענת׃ ");
INSERT INTO heb_vpl VALUES ("ER4_11","016_4_11","EZR","4","11","11","דנה פרשגן אגרתא די שלחו עלוהי על ארתחששתא מלכא עבדיך אנש עבר נהרה וכענת׃ ");
INSERT INTO heb_vpl VALUES ("ER4_12","016_4_12","EZR","4","12","12","ידיע להוא למלכא די יהודיא די סלקו מן לותך עלינא אתו לירושלם קריתא מרדתא ובאישתא בנין ושורי אשכללו ואשיא יחיטו׃ ");
INSERT INTO heb_vpl VALUES ("ER4_13","016_4_13","EZR","4","13","13","כען ידיע להוא למלכא די הן קריתא דך תתבנא ושוריה ישתכללון מנדה בלו והלך לא ינתנון ואפתם מלכים תהנזק׃ ");
INSERT INTO heb_vpl VALUES ("ER4_14","016_4_14","EZR","4","14","14","כען כל קבל די מלח היכלא מלחנא וערות מלכא לא אריך לנא למחזא על דנה שלחנא והודענא למלכא׃ ");
INSERT INTO heb_vpl VALUES ("ER4_15","016_4_15","EZR","4","15","15","די יבקר בספר דכרניא די אבהתך ותהשכח בספר דכרניא ותנדע די קריתא דך קריא מרדא ומהנזקת מלכין ומדנן ואשתדור עבדין בגוה מן יומת עלמא על דנה קריתא דך החרבת׃ ");
INSERT INTO heb_vpl VALUES ("ER4_16","016_4_16","EZR","4","16","16","מהודעין אנחנה למלכא די הן קריתא דך תתבנא ושוריה ישתכללון לקבל דנה חלק בעבר נהרא לא איתי לך׃ ");
INSERT INTO heb_vpl VALUES ("ER4_17","016_4_17","EZR","4","17","17","פתגמא שלח מלכא על רחום בעל טעם ושמשי ספרא ושאר כנותהון די יתבין בשמרין ושאר עבר נהרה שלם וכעת׃ ");
INSERT INTO heb_vpl VALUES ("ER4_18","016_4_18","EZR","4","18","18","נשתונא די שלחתון עלינא מפרש קרי קדמי׃ ");
INSERT INTO heb_vpl VALUES ("ER4_19","016_4_19","EZR","4","19","19","ומני שים טעם ובקרו והשכחו די קריתא דך מן יומת עלמא על מלכין מתנשאה ומרד ואשתדור מתעבד בה׃ ");
INSERT INTO heb_vpl VALUES ("ER4_20","016_4_20","EZR","4","20","20","ומלכין תקיפין הוו על ירושלם ושליטין בכל עבר נהרה ומדה בלו והלך מתיהב להון׃ ");
INSERT INTO heb_vpl VALUES ("ER4_21","016_4_21","EZR","4","21","21","כען שימו טעם לבטלא גבריא אלך וקריתא דך לא תתבנא עד מני טעמא יתשם׃ ");
INSERT INTO heb_vpl VALUES ("ER4_22","016_4_22","EZR","4","22","22","וזהירין הוו שלו למעבד על דנה למה ישגא חבלא להנזקת מלכין׃ ");
INSERT INTO heb_vpl VALUES ("ER4_23","016_4_23","EZR","4","23","23","אדין מן די פרשגן נשתונא די ארתחששתא מלכא קרי קדם רחום ושמשי ספרא וכנותהון אזלו בבהילו לירושלם על יהודיא ובטלו המו באדרע וחיל׃ ");
INSERT INTO heb_vpl VALUES ("ER4_24","016_4_24","EZR","4","24","24","באדין בטלת עבידת בית אלהא די בירושלם והות בטלא עד שנת תרתין למלכות דריוש מלך פרס׃ ");
INSERT INTO heb_vpl VALUES ("ER5_1","016_5_1","EZR","5","1","1","והתנבי חגי נביאה וזכריה בר עדוא נביאיא על יהודיא די ביהוד ובירושלם בשם אלה ישראל עליהון׃ ");
INSERT INTO heb_vpl VALUES ("ER5_2","016_5_2","EZR","5","2","2","באדין קמו זרבבל בר שאלתיאל וישוע בר יוצדק ושריו למבנא בית אלהא די בירושלם ועמהון נביאיא די אלהא מסעדין להון׃ ");
INSERT INTO heb_vpl VALUES ("ER5_3","016_5_3","EZR","5","3","3","בה זמנא אתא עליהון תתני פחת עבר נהרה ושתר בוזני וכנותהון וכן אמרין להם מן שם לכם טעם ביתא דנה לבנא ואשרנא דנה לשכללה׃ ");
INSERT INTO heb_vpl VALUES ("ER5_4","016_5_4","EZR","5","4","4","אדין כנמא אמרנא להם מן אנון שמהת גבריא די דנה בנינא בנין׃ ");
INSERT INTO heb_vpl VALUES ("ER5_5","016_5_5","EZR","5","5","5","ועין אלההם הות על שבי יהודיא ולא בטלו המו עד טעמא לדריוש יהך ואדין יתיבון נשתונא על דנה׃ ");
INSERT INTO heb_vpl VALUES ("ER5_6","016_5_6","EZR","5","6","6","פרשגן אגרתא די שלח תתני פחת עבר נהרה ושתר בוזני וכנותה אפרסכיא די בעבר נהרה על דריוש מלכא׃ ");
INSERT INTO heb_vpl VALUES ("ER5_7","016_5_7","EZR","5","7","7","פתגמא שלחו עלוהי וכדנה כתיב בגוה לדריוש מלכא שלמא כלא׃ ");
INSERT INTO heb_vpl VALUES ("ER5_8","016_5_8","EZR","5","8","8","ידיע להוא למלכא די אזלנא ליהוד מדינתא לבית אלהא רבא והוא מתבנא אבן גלל ואע מתשם בכתליא ועבידתא דך אספרנא מתעבדא ומצלח בידהם׃ ");
INSERT INTO heb_vpl VALUES ("ER5_9","016_5_9","EZR","5","9","9","אדין שאלנא לשביא אלך כנמא אמרנא להם מן שם לכם טעם ביתא דנה למבניה ואשרנא דנה לשכללה׃ ");
INSERT INTO heb_vpl VALUES ("ER5_10","016_5_10","EZR","5","10","10","ואף שמהתהם שאלנא להם להודעותך די נכתב שם גבריא די בראשיהם׃ ");
INSERT INTO heb_vpl VALUES ("ER5_11","016_5_11","EZR","5","11","11","וכנמא פתגמא התיבונא לממר אנחנא המו עבדוהי די אלה שמיא וארעא ובנין ביתא די הוא בנה מקדמת דנה שנין שגיאן ומלך לישראל רב בנהי ושכללה׃ ");
INSERT INTO heb_vpl VALUES ("ER5_12","016_5_12","EZR","5","12","12","להן מן די הרגזו אבהתנא לאלה שמיא יהב המו ביד נבוכדנצר מלך בבל כסדיא וביתה דנה סתרה ועמה הגלי לבבל׃ ");
INSERT INTO heb_vpl VALUES ("ER5_13","016_5_13","EZR","5","13","13","ברם בשנת חדה לכורש מלכא די בבל כורש מלכא שם טעם בית אלהא דנה לבנא׃ ");
INSERT INTO heb_vpl VALUES ("ER5_14","016_5_14","EZR","5","14","14","ואף מאניא די בית אלהא די דהבה וכספא די נבוכדנצר הנפק מן היכלא די בירושלם והיבל המו להיכלא די בבל הנפק המו כורש מלכא מן היכלא די בבל ויהיבו לששבצר שמה די פחה שמה׃ ");
INSERT INTO heb_vpl VALUES ("ER5_15","016_5_15","EZR","5","15","15","ואמר לה אלה מאניא שא אזל אחת המו בהיכלא די בירושלם ובית אלהא יתבנא על אתרה׃ ");
INSERT INTO heb_vpl VALUES ("ER5_16","016_5_16","EZR","5","16","16","אדין ששבצר דך אתא יהב אשיא די בית אלהא די בירושלם ומן אדין ועד כען מתבנא ולא שלם׃ ");
INSERT INTO heb_vpl VALUES ("ER5_17","016_5_17","EZR","5","17","17","וכען הן על מלכא טב יתבקר בבית גנזיא די מלכא תמה די בבבל הן איתי די מן כורש מלכא שים טעם למבנא בית אלהא דך בירושלם ורעות מלכא על דנה ישלח עלינא׃ ");
INSERT INTO heb_vpl VALUES ("ER6_1","016_6_1","EZR","6","1","1","באדין דריוש מלכא שם טעם ובקרו בבית ספריא די גנזיא מהחתין תמה בבבל׃ ");
INSERT INTO heb_vpl VALUES ("ER6_2","016_6_2","EZR","6","2","2","והשתכח באחמתא בבירתא די במדי מדינתה מגלה חדה וכן כתיב בגוה דכרונה׃ ");
INSERT INTO heb_vpl VALUES ("ER6_3","016_6_3","EZR","6","3","3","בשנת חדה לכורש מלכא כורש מלכא שם טעם בית אלהא בירושלם ביתא יתבנא אתר די דבחין דבחין ואשוהי מסובלין רומה אמין שתין פתיה אמין שתין׃ ");
INSERT INTO heb_vpl VALUES ("ER6_4","016_6_4","EZR","6","4","4","נדבכין די אבן גלל תלתא ונדבך די אע חדת ונפקתא מן בית מלכא תתיהב׃ ");
INSERT INTO heb_vpl VALUES ("ER6_5","016_6_5","EZR","6","5","5","ואף מאני בית אלהא די דהבה וכספא די נבוכדנצר הנפק מן היכלא די בירושלם והיבל לבבל יהתיבון ויהך להיכלא די בירושלם לאתרה ותחת בבית אלהא׃ ");
INSERT INTO heb_vpl VALUES ("ER6_6","016_6_6","EZR","6","6","6","כען תתני פחת עבר נהרה שתר בוזני וכנותהון אפרסכיא די בעבר נהרה רחיקין הוו מן תמה׃ ");
INSERT INTO heb_vpl VALUES ("ER6_7","016_6_7","EZR","6","7","7","שבקו לעבידת בית אלהא דך פחת יהודיא ולשבי יהודיא בית אלהא דך יבנון על אתרה׃ ");
INSERT INTO heb_vpl VALUES ("ER6_8","016_6_8","EZR","6","8","8","ומני שים טעם למא די תעבדון עם שבי יהודיא אלך למבנא בית אלהא דך ומנכסי מלכא די מדת עבר נהרה אספרנא נפקתא תהוא מתיהבא לגבריא אלך די לא לבטלא׃ ");
INSERT INTO heb_vpl VALUES ("ER6_9","016_6_9","EZR","6","9","9","ומה חשחן ובני תורין ודכרין ואמרין לעלון לאלה שמיא חנטין מלח חמר ומשח כמאמר כהניא די בירושלם להוא מתיהב להם יום ביום די לא שלו׃ ");
INSERT INTO heb_vpl VALUES ("ER6_10","016_6_10","EZR","6","10","10","די להון מהקרבין ניחוחין לאלה שמיא ומצלין לחיי מלכא ובנוהי׃ ");
INSERT INTO heb_vpl VALUES ("ER6_11","016_6_11","EZR","6","11","11","ומני שים טעם די כל אנש די יהשנא פתגמא דנה יתנסח אע מן ביתה וזקיף יתמחא עלהי וביתה נולו יתעבד על דנה׃ ");
INSERT INTO heb_vpl VALUES ("ER6_12","016_6_12","EZR","6","12","12","ואלהא די שכן שמה תמה ימגר כל מלך ועם די ישלח ידה להשניה לחבלה בית אלהא דך די בירושלם אנה דריוש שמת טעם אספרנא יתעבד׃ ");
INSERT INTO heb_vpl VALUES ("ER6_13","016_6_13","EZR","6","13","13","אדין תתני פחת עבר נהרה שתר בוזני וכנותהון לקבל די שלח דריוש מלכא כנמא אספרנא עבדו׃ ");
INSERT INTO heb_vpl VALUES ("ER6_14","016_6_14","EZR","6","14","14","ושבי יהודיא בנין ומצלחין בנבואת חגי נביאה וזכריה בר עדוא ובנו ושכללו מן טעם אלה ישראל ומטעם כורש ודריוש וארתחששתא מלך פרס׃ ");
INSERT INTO heb_vpl VALUES ("ER6_15","016_6_15","EZR","6","15","15","ושיציא ביתה דנה עד יום תלתה לירח אדר די היא שנת שת למלכות דריוש מלכא׃ ");
INSERT INTO heb_vpl VALUES ("ER6_16","016_6_16","EZR","6","16","16","ועבדו בני ישראל כהניא ולויא ושאר בני גלותא חנכת בית אלהא דנה בחדוה׃ ");
INSERT INTO heb_vpl VALUES ("ER6_17","016_6_17","EZR","6","17","17","והקרבו לחנכת בית אלהא דנה תורין מאה דכרין מאתין אמרין ארבע מאה וצפירי עזין לחטיא על כל ישראל תרי עשר למנין שבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ER6_18","016_6_18","EZR","6","18","18","והקימו כהניא בפלגתהון ולויא במחלקתהון על עבידת אלהא די בירושלם ככתב ספר משה׃ ");
INSERT INTO heb_vpl VALUES ("ER6_19","016_6_19","EZR","6","19","19","ויעשו בני הגולה את הפסח בארבעה עשר לחדש הראשון׃ ");
INSERT INTO heb_vpl VALUES ("ER6_20","016_6_20","EZR","6","20","20","כי הטהרו הכהנים והלוים כאחד כלם טהורים וישחטו הפסח לכל בני הגולה ולאחיהם הכהנים ולהם׃ ");
INSERT INTO heb_vpl VALUES ("ER6_21","016_6_21","EZR","6","21","21","ויאכלו בני ישראל השבים מהגולה וכל הנבדל מטמאת גוי הארץ אלהם לדרש ליהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ER6_22","016_6_22","EZR","6","22","22","ויעשו חג מצות שבעת ימים בשמחה כי שמחם יהוה והסב לב מלך אשור עליהם לחזק ידיהם במלאכת בית האלהים אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ER7_1","016_7_1","EZR","7","1","1","ואחר הדברים האלה במלכות ארתחשסתא מלך פרס עזרא בן שריה בן עזריה בן חלקיה׃ ");
INSERT INTO heb_vpl VALUES ("ER7_2","016_7_2","EZR","7","2","2","בן שלום בן צדוק בן אחיטוב׃ ");
INSERT INTO heb_vpl VALUES ("ER7_3","016_7_3","EZR","7","3","3","בן אמריה בן עזריה בן מריות׃ ");
INSERT INTO heb_vpl VALUES ("ER7_4","016_7_4","EZR","7","4","4","בן זרחיה בן עזי בן בקי׃ ");
INSERT INTO heb_vpl VALUES ("ER7_5","016_7_5","EZR","7","5","5","בן אבישוע בן פינחס בן אלעזר בן אהרן הכהן הראש׃ ");
INSERT INTO heb_vpl VALUES ("ER7_6","016_7_6","EZR","7","6","6","הוא עזרא עלה מבבל והוא ספר מהיר בתורת משה אשר נתן יהוה אלהי ישראל ויתן לו המלך כיד יהוה אלהיו עליו כל בקשתו׃ ");
INSERT INTO heb_vpl VALUES ("ER7_7","016_7_7","EZR","7","7","7","ויעלו מבני ישראל ומן הכהנים והלוים והמשררים והשערים והנתינים אל ירושלם בשנת שבע לארתחשסתא המלך׃ ");
INSERT INTO heb_vpl VALUES ("ER7_8","016_7_8","EZR","7","8","8","ויבא ירושלם בחדש החמישי היא שנת השביעית למלך׃ ");
INSERT INTO heb_vpl VALUES ("ER7_9","016_7_9","EZR","7","9","9","כי באחד לחדש הראשון הוא יסד המעלה מבבל ובאחד לחדש החמישי בא אל ירושלם כיד אלהיו הטובה עליו׃ ");
INSERT INTO heb_vpl VALUES ("ER7_10","016_7_10","EZR","7","10","10","כי עזרא הכין לבבו לדרוש את תורת יהוה ולעשת וללמד בישראל חק ומשפט׃ ");
INSERT INTO heb_vpl VALUES ("ER7_11","016_7_11","EZR","7","11","11","וזה פרשגן הנשתון אשר נתן המלך ארתחשסתא לעזרא הכהן הספר ספר דברי מצות יהוה וחקיו על ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ER7_12","016_7_12","EZR","7","12","12","ארתחשסתא מלך מלכיא לעזרא כהנא ספר דתא די אלה שמיא גמיר וכענת׃ ");
INSERT INTO heb_vpl VALUES ("ER7_13","016_7_13","EZR","7","13","13","מני שים טעם די כל מתנדב במלכותי מן עמה ישראל וכהנוהי ולויא למהך לירושלם עמך יהך׃ ");
INSERT INTO heb_vpl VALUES ("ER7_14","016_7_14","EZR","7","14","14","כל קבל די מן קדם מלכא ושבעת יעטהי שליח לבקרא על יהוד ולירושלם בדת אלהך די בידך׃ ");
INSERT INTO heb_vpl VALUES ("ER7_15","016_7_15","EZR","7","15","15","ולהיבלה כסף ודהב די מלכא ויעטוהי התנדבו לאלה ישראל די בירושלם משכנה׃ ");
INSERT INTO heb_vpl VALUES ("ER7_16","016_7_16","EZR","7","16","16","וכל כסף ודהב די תהשכח בכל מדינת בבל עם התנדבות עמא וכהניא מתנדבין לבית אלההם די בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER7_17","016_7_17","EZR","7","17","17","כל קבל דנה אספרנא תקנא בכספא דנה תורין דכרין אמרין ומנחתהון ונסכיהון ותקרב המו על מדבחה די בית אלהכם די בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER7_18","016_7_18","EZR","7","18","18","ומה די עליך ועל אחיך ייטב בשאר כספא ודהבה למעבד כרעות אלהכם תעבדון׃ ");
INSERT INTO heb_vpl VALUES ("ER7_19","016_7_19","EZR","7","19","19","ומאניא די מתיהבין לך לפלחן בית אלהך השלם קדם אלה ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER7_20","016_7_20","EZR","7","20","20","ושאר חשחות בית אלהך די יפל לך למנתן תנתן מן בית גנזי מלכא׃ ");
INSERT INTO heb_vpl VALUES ("ER7_21","016_7_21","EZR","7","21","21","ומני אנה ארתחשסתא מלכא שים טעם לכל גזבריא די בעבר נהרה די כל די ישאלנכון עזרא כהנה ספר דתא די אלה שמיא אספרנא יתעבד׃ ");
INSERT INTO heb_vpl VALUES ("ER7_22","016_7_22","EZR","7","22","22","עד כסף ככרין מאה ועד חנטין כרין מאה ועד חמר בתין מאה ועד בתין משח מאה ומלח די לא כתב׃ ");
INSERT INTO heb_vpl VALUES ("ER7_23","016_7_23","EZR","7","23","23","כל די מן טעם אלה שמיא יתעבד אדרזדא לבית אלה שמיא די למה להוא קצף על מלכות מלכא ובנוהי׃ ");
INSERT INTO heb_vpl VALUES ("ER7_24","016_7_24","EZR","7","24","24","ולכם מהודעין די כל כהניא ולויא זמריא תרעיא נתיניא ופלחי בית אלהא דנה מנדה בלו והלך לא שליט למרמא עליהם׃ ");
INSERT INTO heb_vpl VALUES ("ER7_25","016_7_25","EZR","7","25","25","ואנת עזרא כחכמת אלהך די בידך מני שפטין ודינין די להון דאנין לכל עמה די בעבר נהרה לכל ידעי דתי אלהך ודי לא ידע תהודעון׃ ");
INSERT INTO heb_vpl VALUES ("ER7_26","016_7_26","EZR","7","26","26","וכל די לא להוא עבד דתא די אלהך ודתא די מלכא אספרנא דינה להוא מתעבד מנה הן למות הן לשרשו הן לענש נכסין ולאסורין׃ ");
INSERT INTO heb_vpl VALUES ("ER7_27","016_7_27","EZR","7","27","27","ברוך יהוה אלהי אבותינו אשר נתן כזאת בלב המלך לפאר את בית יהוה אשר בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER7_28","016_7_28","EZR","7","28","28","ועלי הטה חסד לפני המלך ויועציו ולכל שרי המלך הגברים ואני התחזקתי כיד יהוה אלהי עלי ואקבצה מישראל ראשים לעלות עמי׃ ");
INSERT INTO heb_vpl VALUES ("ER8_1","016_8_1","EZR","8","1","1","ואלה ראשי אבתיהם והתיחשם העלים עמי במלכות ארתחשסתא המלך מבבל׃ ");
INSERT INTO heb_vpl VALUES ("ER8_2","016_8_2","EZR","8","2","2","מבני פינחס גרשם מבני איתמר דניאל מבני דויד חטוש׃ ");
INSERT INTO heb_vpl VALUES ("ER8_3","016_8_3","EZR","8","3","3","מבני שכניה מבני פרעש זכריה ועמו התיחש לזכרים מאה וחמשים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_4","016_8_4","EZR","8","4","4","מבני פחת מואב אליהועיני בן זרחיה ועמו מאתים הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_5","016_8_5","EZR","8","5","5","מבני שכניה בן יחזיאל ועמו שלש מאות הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_6","016_8_6","EZR","8","6","6","ומבני עדין עבד בן יונתן ועמו חמשים הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_7","016_8_7","EZR","8","7","7","ומבני עילם ישעיה בן עתליה ועמו שבעים הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_8","016_8_8","EZR","8","8","8","ומבני שפטיה זבדיה בן מיכאל ועמו שמנים הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_9","016_8_9","EZR","8","9","9","מבני יואב עבדיה בן יחיאל ועמו מאתים ושמנה עשר הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_10","016_8_10","EZR","8","10","10","ומבני שלומית בן יוספיה ועמו מאה וששים הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_11","016_8_11","EZR","8","11","11","ומבני בבי זכריה בן בבי ועמו עשרים ושמנה הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_12","016_8_12","EZR","8","12","12","ומבני עזגד יוחנן בן הקטן ועמו מאה ועשרה הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_13","016_8_13","EZR","8","13","13","ומבני אדניקם אחרנים ואלה שמותם אליפלט יעיאל ושמעיה ועמהם ששים הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_14","016_8_14","EZR","8","14","14","ומבני בגוי עותי וזבוד ועמו שבעים הזכרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_15","016_8_15","EZR","8","15","15","ואקבצם אל הנהר הבא אל אהוא ונחנה שם ימים שלשה ואבינה בעם ובכהנים ומבני לוי לא מצאתי שם׃ ");
INSERT INTO heb_vpl VALUES ("ER8_16","016_8_16","EZR","8","16","16","ואשלחה לאליעזר לאריאל לשמעיה ולאלנתן וליריב ולאלנתן ולנתן ולזכריה ולמשלם ראשים וליויריב ולאלנתן מבינים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_17","016_8_17","EZR","8","17","17","ואוצאה אותם על אדו הראש בכספיא המקום ואשימה בפיהם דברים לדבר אל אדו אחיו הנתונים בכספיא המקום להביא לנו משרתים לבית אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("ER8_18","016_8_18","EZR","8","18","18","ויביאו לנו כיד אלהינו הטובה עלינו איש שכל מבני מחלי בן לוי בן ישראל ושרביה ובניו ואחיו שמנה עשר׃ ");
INSERT INTO heb_vpl VALUES ("ER8_19","016_8_19","EZR","8","19","19","ואת חשביה ואתו ישעיה מבני מררי אחיו ובניהם עשרים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_20","016_8_20","EZR","8","20","20","ומן הנתינים שנתן דויד והשרים לעבדת הלוים נתינים מאתים ועשרים כלם נקבו בשמות׃ ");
INSERT INTO heb_vpl VALUES ("ER8_21","016_8_21","EZR","8","21","21","ואקרא שם צום על הנהר אהוא להתענות לפני אלהינו לבקש ממנו דרך ישרה לנו ולטפנו ולכל רכושנו׃ ");
INSERT INTO heb_vpl VALUES ("ER8_22","016_8_22","EZR","8","22","22","כי בשתי לשאול מן המלך חיל ופרשים לעזרנו מאויב בדרך כי אמרנו למלך לאמר יד אלהינו על כל מבקשיו לטובה ועזו ואפו על כל עזביו׃ ");
INSERT INTO heb_vpl VALUES ("ER8_23","016_8_23","EZR","8","23","23","ונצומה ונבקשה מאלהינו על זאת ויעתר לנו׃ ");
INSERT INTO heb_vpl VALUES ("ER8_24","016_8_24","EZR","8","24","24","ואבדילה משרי הכהנים שנים עשר לשרביה חשביה ועמהם מאחיהם עשרה׃ ");
INSERT INTO heb_vpl VALUES ("ER8_25","016_8_25","EZR","8","25","25","ואשקולה להם את הכסף ואת הזהב ואת הכלים תרומת בית אלהינו ההרימו המלך ויעציו ושריו וכל ישראל הנמצאים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_26","016_8_26","EZR","8","26","26","ואשקלה על ידם כסף ככרים שש מאות וחמשים וכלי כסף מאה לככרים זהב מאה ככר׃ ");
INSERT INTO heb_vpl VALUES ("ER8_27","016_8_27","EZR","8","27","27","וכפרי זהב עשרים לאדרכנים אלף וכלי נחשת מצהב טובה שנים חמודת כזהב׃ ");
INSERT INTO heb_vpl VALUES ("ER8_28","016_8_28","EZR","8","28","28","ואמרה אלהם אתם קדש ליהוה והכלים קדש והכסף והזהב נדבה ליהוה אלהי אבתיכם׃ ");
INSERT INTO heb_vpl VALUES ("ER8_29","016_8_29","EZR","8","29","29","שקדו ושמרו עד תשקלו לפני שרי הכהנים והלוים ושרי האבות לישראל בירושלם הלשכות בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ER8_30","016_8_30","EZR","8","30","30","וקבלו הכהנים והלוים משקל הכסף והזהב והכלים להביא לירושלם לבית אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("ER8_31","016_8_31","EZR","8","31","31","ונסעה מנהר אהוא בשנים עשר לחדש הראשון ללכת ירושלם ויד אלהינו היתה עלינו ויצילנו מכף אויב ואורב על הדרך׃ ");
INSERT INTO heb_vpl VALUES ("ER8_32","016_8_32","EZR","8","32","32","ונבוא ירושלם ונשב שם ימים שלשה׃ ");
INSERT INTO heb_vpl VALUES ("ER8_33","016_8_33","EZR","8","33","33","וביום הרביעי נשקל הכסף והזהב והכלים בבית אלהינו על יד מרמות בן אוריה הכהן ועמו אלעזר בן פינחס ועמהם יוזבד בן ישוע ונועדיה בן בנוי הלוים׃ ");
INSERT INTO heb_vpl VALUES ("ER8_34","016_8_34","EZR","8","34","34","במספר במשקל לכל ויכתב כל המשקל בעת ההיא׃ ");
INSERT INTO heb_vpl VALUES ("ER8_35","016_8_35","EZR","8","35","35","הבאים מהשבי בני הגולה הקריבו עלות לאלהי ישראל פרים שנים עשר על כל ישראל אילים תשעים וששה כבשים שבעים ושבעה צפירי חטאת שנים עשר הכל עולה ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("ER8_36","016_8_36","EZR","8","36","36","ויתנו את דתי המלך לאחשדרפני המלך ופחוות עבר הנהר ונשאו את העם ואת בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("ER9_1","016_9_1","EZR","9","1","1","וככלות אלה נגשו אלי השרים לאמר לא נבדלו העם ישראל והכהנים והלוים מעמי הארצות כתועבתיהם לכנעני החתי הפרזי היבוסי העמני המאבי המצרי והאמרי׃ ");
INSERT INTO heb_vpl VALUES ("ER9_2","016_9_2","EZR","9","2","2","כי נשאו מבנתיהם להם ולבניהם והתערבו זרע הקדש בעמי הארצות ויד השרים והסגנים היתה במעל הזה ראשונה׃ ");
INSERT INTO heb_vpl VALUES ("ER9_3","016_9_3","EZR","9","3","3","וכשמעי את הדבר הזה קרעתי את בגדי ומעילי ואמרטה משער ראשי וזקני ואשבה משומם׃ ");
INSERT INTO heb_vpl VALUES ("ER9_4","016_9_4","EZR","9","4","4","ואלי יאספו כל חרד בדברי אלהי ישראל על מעל הגולה ואני ישב משומם עד למנחת הערב׃ ");
INSERT INTO heb_vpl VALUES ("ER9_5","016_9_5","EZR","9","5","5","ובמנחת הערב קמתי מתעניתי ובקרעי בגדי ומעילי ואכרעה על ברכי ואפרשה כפי אל יהוה אלהי׃ ");
INSERT INTO heb_vpl VALUES ("ER9_6","016_9_6","EZR","9","6","6","ואמרה אלהי בשתי ונכלמתי להרים אלהי פני אליך כי עונתינו רבו למעלה ראש ואשמתנו גדלה עד לשמים׃ ");
INSERT INTO heb_vpl VALUES ("ER9_7","016_9_7","EZR","9","7","7","מימי אבתינו אנחנו באשמה גדלה עד היום הזה ובעונתינו נתנו אנחנו מלכינו כהנינו ביד מלכי הארצות בחרב בשבי ובבזה ובבשת פנים כהיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("ER9_8","016_9_8","EZR","9","8","8","ועתה כמעט רגע היתה תחנה מאת יהוה אלהינו להשאיר לנו פליטה ולתת לנו יתד במקום קדשו להאיר עינינו אלהינו ולתתנו מחיה מעט בעבדתנו׃ ");
INSERT INTO heb_vpl VALUES ("ER9_9","016_9_9","EZR","9","9","9","כי עבדים אנחנו ובעבדתנו לא עזבנו אלהינו ויט עלינו חסד לפני מלכי פרס לתת לנו מחיה לרומם את בית אלהינו ולהעמיד את חרבתיו ולתת לנו גדר ביהודה ובירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER9_10","016_9_10","EZR","9","10","10","ועתה מה נאמר אלהינו אחרי זאת כי עזבנו מצותיך׃ ");
INSERT INTO heb_vpl VALUES ("ER9_11","016_9_11","EZR","9","11","11","אשר צוית ביד עבדיך הנביאים לאמר הארץ אשר אתם באים לרשתה ארץ נדה היא בנדת עמי הארצות בתועבתיהם אשר מלאוה מפה אל פה בטמאתם׃ ");
INSERT INTO heb_vpl VALUES ("ER9_12","016_9_12","EZR","9","12","12","ועתה בנותיכם אל תתנו לבניהם ובנתיהם אל תשאו לבניכם ולא תדרשו שלמם וטובתם עד עולם למען תחזקו ואכלתם את טוב הארץ והורשתם לבניכם עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("ER9_13","016_9_13","EZR","9","13","13","ואחרי כל הבא עלינו במעשינו הרעים ובאשמתנו הגדלה כי אתה אלהינו חשכת למטה מעוננו ונתתה לנו פליטה כזאת׃ ");
INSERT INTO heb_vpl VALUES ("ER9_14","016_9_14","EZR","9","14","14","הנשוב להפר מצותיך ולהתחתן בעמי התעבות האלה הלוא תאנף בנו עד כלה לאין שארית ופליטה׃ ");
INSERT INTO heb_vpl VALUES ("ER9_15","016_9_15","EZR","9","15","15","יהוה אלהי ישראל צדיק אתה כי נשארנו פליטה כהיום הזה הננו לפניך באשמתינו כי אין לעמוד לפניך על זאת׃ ");
INSERT INTO heb_vpl VALUES ("ER10_1","016_10_1","EZR","10","1","1","וכהתפלל עזרא וכהתודתו בכה ומתנפל לפני בית האלהים נקבצו אליו מישראל קהל רב מאד אנשים ונשים וילדים כי בכו העם הרבה בכה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_2","016_10_2","EZR","10","2","2","ויען שכניה בן יחיאל מבני עולם ויאמר לעזרא אנחנו מעלנו באלהינו ונשב נשים נכריות מעמי הארץ ועתה יש מקוה לישראל על זאת׃ ");
INSERT INTO heb_vpl VALUES ("ER10_3","016_10_3","EZR","10","3","3","ועתה נכרת ברית לאלהינו להוציא כל נשים והנולד מהם בעצת אדני והחרדים במצות אלהינו וכתורה יעשה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_4","016_10_4","EZR","10","4","4","קום כי עליך הדבר ואנחנו עמך חזק ועשה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_5","016_10_5","EZR","10","5","5","ויקם עזרא וישבע את שרי הכהנים הלוים וכל ישראל לעשות כדבר הזה וישבעו׃ ");
INSERT INTO heb_vpl VALUES ("ER10_6","016_10_6","EZR","10","6","6","ויקם עזרא מלפני בית האלהים וילך אל לשכת יהוחנן בן אלישיב וילך שם לחם לא אכל ומים לא שתה כי מתאבל על מעל הגולה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_7","016_10_7","EZR","10","7","7","ויעבירו קול ביהודה וירושלם לכל בני הגולה להקבץ ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ER10_8","016_10_8","EZR","10","8","8","וכל אשר לא יבוא לשלשת הימים כעצת השרים והזקנים יחרם כל רכושו והוא יבדל מקהל הגולה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_9","016_10_9","EZR","10","9","9","ויקבצו כל אנשי יהודה ובנימן ירושלם לשלשת הימים הוא חדש התשיעי בעשרים בחדש וישבו כל העם ברחוב בית האלהים מרעידים על הדבר ומהגשמים׃ ");
INSERT INTO heb_vpl VALUES ("ER10_10","016_10_10","EZR","10","10","10","ויקם עזרא הכהן ויאמר אלהם אתם מעלתם ותשיבו נשים נכריות להוסיף על אשמת ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ER10_11","016_10_11","EZR","10","11","11","ועתה תנו תודה ליהוה אלהי אבתיכם ועשו רצונו והבדלו מעמי הארץ ומן הנשים הנכריות׃ ");
INSERT INTO heb_vpl VALUES ("ER10_12","016_10_12","EZR","10","12","12","ויענו כל הקהל ויאמרו קול גדול כן כדבריך עלינו לעשות׃ ");
INSERT INTO heb_vpl VALUES ("ER10_13","016_10_13","EZR","10","13","13","אבל העם רב והעת גשמים ואין כח לעמוד בחוץ והמלאכה לא ליום אחד ולא לשנים כי הרבינו לפשע בדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_14","016_10_14","EZR","10","14","14","יעמדו נא שרינו לכל הקהל וכל אשר בערינו ההשיב נשים נכריות יבא לעתים מזמנים ועמהם זקני עיר ועיר ושפטיה עד להשיב חרון אף אלהינו ממנו עד לדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_15","016_10_15","EZR","10","15","15","אך יונתן בן עשהאל ויחזיה בן תקוה עמדו על זאת ומשלם ושבתי הלוי עזרם׃ ");
INSERT INTO heb_vpl VALUES ("ER10_16","016_10_16","EZR","10","16","16","ויעשו כן בני הגולה ויבדלו עזרא הכהן אנשים ראשי האבות לבית אבתם וכלם בשמות וישבו ביום אחד לחדש העשירי לדריוש הדבר׃ ");
INSERT INTO heb_vpl VALUES ("ER10_17","016_10_17","EZR","10","17","17","ויכלו בכל אנשים ההשיבו נשים נכריות עד יום אחד לחדש הראשון׃ ");
INSERT INTO heb_vpl VALUES ("ER10_18","016_10_18","EZR","10","18","18","וימצא מבני הכהנים אשר השיבו נשים נכריות מבני ישוע בן יוצדק ואחיו מעשיה ואליעזר ויריב וגדליה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_19","016_10_19","EZR","10","19","19","ויתנו ידם להוציא נשיהם ואשמים איל צאן על אשמתם׃ ");
INSERT INTO heb_vpl VALUES ("ER10_20","016_10_20","EZR","10","20","20","ומבני אמר חנני וזבדיה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_21","016_10_21","EZR","10","21","21","ומבני חרם מעשיה ואליה ושמעיה ויחיאל ועזיה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_22","016_10_22","EZR","10","22","22","ומבני פשחור אליועיני מעשיה ישמעאל נתנאל יוזבד ואלעשה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_23","016_10_23","EZR","10","23","23","ומן הלוים יוזבד ושמעי וקליה הוא קליטא פתחיה יהודה ואליעזר׃ ");
INSERT INTO heb_vpl VALUES ("ER10_24","016_10_24","EZR","10","24","24","ומן המשררים אלישיב ומן השערים שלם וטלם ואורי׃ ");
INSERT INTO heb_vpl VALUES ("ER10_25","016_10_25","EZR","10","25","25","ומישראל מבני פרעש רמיה ויזיה ומלכיה ומימן ואלעזר ומלכיה ובניה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_26","016_10_26","EZR","10","26","26","ומבני עילם מתניה זכריה ויחיאל ועבדי וירמות ואליה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_27","016_10_27","EZR","10","27","27","ומבני זתוא אליועני אלישיב מתניה וירמות וזבד ועזיזא׃ ");
INSERT INTO heb_vpl VALUES ("ER10_28","016_10_28","EZR","10","28","28","ומבני בבי יהוחנן חנניה זבי עתלי׃ ");
INSERT INTO heb_vpl VALUES ("ER10_29","016_10_29","EZR","10","29","29","ומבני בני משלם מלוך ועדיה ישוב ושאל ירמות׃ ");
INSERT INTO heb_vpl VALUES ("ER10_30","016_10_30","EZR","10","30","30","ומבני פחת מואב עדנא וכלל בניה מעשיה מתניה בצלאל ובנוי ומנשה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_31","016_10_31","EZR","10","31","31","ובני חרם אליעזר ישיה מלכיה שמעיה שמעון׃ ");
INSERT INTO heb_vpl VALUES ("ER10_32","016_10_32","EZR","10","32","32","בנימן מלוך שמריה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_33","016_10_33","EZR","10","33","33","מבני חשם מתני מתתה זבד אליפלט ירמי מנשה שמעי׃ ");
INSERT INTO heb_vpl VALUES ("ER10_34","016_10_34","EZR","10","34","34","מבני בני מעדי עמרם ואואל׃ ");
