INSERT INTO heb_vpl VALUES ("ER10_36","016_10_36","EZR","10","36","36","וניה מרמות אלישיב׃ ");
INSERT INTO heb_vpl VALUES ("ER10_37","016_10_37","EZR","10","37","37","מתניה מתני ויעשו׃ ");
INSERT INTO heb_vpl VALUES ("ER10_38","016_10_38","EZR","10","38","38","ובני ובנוי שמעי׃ ");
INSERT INTO heb_vpl VALUES ("ER10_39","016_10_39","EZR","10","39","39","ושלמיה ונתן ועדיה׃ ");
