INSERT INTO heb_vpl VALUES ("ER10_43","016_10_43","EZR","10","43","43","מבני נבו יעיאל מתתיה זבד זבינא ידו ויואל בניה׃ ");
INSERT INTO heb_vpl VALUES ("ER10_44","016_10_44","EZR","10","44","44","כל אלה נשאי נשים נכריות ויש מהם נשים וישימו בנים׃ ");
INSERT INTO heb_vpl VALUES ("NH1_1","017_1_1","NEH","1","1","1","דברי נחמיה בן חכליה ויהי בחדש כסלו שנת עשרים ואני הייתי בשושן הבירה׃ ");
INSERT INTO heb_vpl VALUES ("NH1_2","017_1_2","NEH","1","2","2","ויבא חנני אחד מאחי הוא ואנשים מיהודה ואשאלם על היהודים הפליטה אשר נשארו מן השבי ועל ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("NH1_3","017_1_3","NEH","1","3","3","ויאמרו לי הנשארים אשר נשארו מן השבי שם במדינה ברעה גדלה ובחרפה וחומת ירושלם מפרצת ושעריה נצתו באש׃ ");
INSERT INTO heb_vpl VALUES ("NH1_4","017_1_4","NEH","1","4","4","ויהי כשמעי את הדברים האלה ישבתי ואבכה ואתאבלה ימים ואהי צם ומתפלל לפני אלהי השמים׃ ");
INSERT INTO heb_vpl VALUES ("NH1_5","017_1_5","NEH","1","5","5","ואמר אנא יהוה אלהי השמים האל הגדול והנורא שמר הברית וחסד לאהביו ולשמרי מצותיו׃ ");
INSERT INTO heb_vpl VALUES ("NH1_6","017_1_6","NEH","1","6","6","תהי נא אזנך קשבת ועיניך פתוחות לשמע אל תפלת עבדך אשר אנכי מתפלל לפניך היום יומם ולילה על בני ישראל עבדיך ומתודה על חטאות בני ישראל אשר חטאנו לך ואני ובית אבי חטאנו׃ ");
INSERT INTO heb_vpl VALUES ("NH1_7","017_1_7","NEH","1","7","7","חבל חבלנו לך ולא שמרנו את המצות ואת החקים ואת המשפטים אשר צוית את משה עבדך׃ ");
INSERT INTO heb_vpl VALUES ("NH1_8","017_1_8","NEH","1","8","8","זכר נא את הדבר אשר צוית את משה עבדך לאמר אתם תמעלו אני אפיץ אתכם בעמים׃ ");
INSERT INTO heb_vpl VALUES ("NH1_9","017_1_9","NEH","1","9","9","ושבתם אלי ושמרתם מצותי ועשיתם אתם אם יהיה נדחכם בקצה השמים משם אקבצם והבואתים אל המקום אשר בחרתי לשכן את שמי שם׃ ");
INSERT INTO heb_vpl VALUES ("NH1_10","017_1_10","NEH","1","10","10","והם עבדיך ועמך אשר פדית בכחך הגדול ובידך החזקה׃ ");
INSERT INTO heb_vpl VALUES ("NH1_11","017_1_11","NEH","1","11","11","אנא אדני תהי נא אזנך קשבת אל תפלת עבדך ואל תפלת עבדיך החפצים ליראה את שמך והצליחה נא לעבדך היום ותנהו לרחמים לפני האיש הזה ואני הייתי משקה למלך׃ ");
INSERT INTO heb_vpl VALUES ("NH2_1","017_2_1","NEH","2","1","1","ויהי בחדש ניסן שנת עשרים לארתחשסתא המלך יין לפניו ואשא את היין ואתנה למלך ולא הייתי רע לפניו׃ ");
INSERT INTO heb_vpl VALUES ("NH2_2","017_2_2","NEH","2","2","2","ויאמר לי המלך מדוע פניך רעים ואתה אינך חולה אין זה כי אם רע לב ואירא הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("NH2_3","017_2_3","NEH","2","3","3","ואמר למלך המלך לעולם יחיה מדוע לא ירעו פני אשר העיר בית קברות אבתי חרבה ושעריה אכלו באש׃ ");
INSERT INTO heb_vpl VALUES ("NH2_4","017_2_4","NEH","2","4","4","ויאמר לי המלך על מה זה אתה מבקש ואתפלל אל אלהי השמים׃ ");
INSERT INTO heb_vpl VALUES ("NH2_5","017_2_5","NEH","2","5","5","ואמר למלך אם על המלך טוב ואם ייטב עבדך לפניך אשר תשלחני אל יהודה אל עיר קברות אבתי ואבננה׃ ");
INSERT INTO heb_vpl VALUES ("NH2_6","017_2_6","NEH","2","6","6","ויאמר לי המלך והשגל יושבת אצלו עד מתי יהיה מהלכך ומתי תשוב וייטב לפני המלך וישלחני ואתנה לו זמן׃ ");
INSERT INTO heb_vpl VALUES ("NH2_7","017_2_7","NEH","2","7","7","ואומר למלך אם על המלך טוב אגרות יתנו לי על פחוות עבר הנהר אשר יעבירוני עד אשר אבוא אל יהודה׃ ");
INSERT INTO heb_vpl VALUES ("NH2_8","017_2_8","NEH","2","8","8","ואגרת אל אסף שמר הפרדס אשר למלך אשר יתן לי עצים לקרות את שערי הבירה אשר לבית ולחומת העיר ולבית אשר אבוא אליו ויתן לי המלך כיד אלהי הטובה עלי׃ ");
INSERT INTO heb_vpl VALUES ("NH2_9","017_2_9","NEH","2","9","9","ואבוא אל פחוות עבר הנהר ואתנה להם את אגרות המלך וישלח עמי המלך שרי חיל ופרשים׃ ");
INSERT INTO heb_vpl VALUES ("NH2_10","017_2_10","NEH","2","10","10","וישמע סנבלט החרני וטוביה העבד העמני וירע להם רעה גדלה אשר בא אדם לבקש טובה לבני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("NH2_11","017_2_11","NEH","2","11","11","ואבוא אל ירושלם ואהי שם ימים שלשה׃ ");
INSERT INTO heb_vpl VALUES ("NH2_12","017_2_12","NEH","2","12","12","ואקום לילה אני ואנשים מעט עמי ולא הגדתי לאדם מה אלהי נתן אל לבי לעשות לירושלם ובהמה אין עמי כי אם הבהמה אשר אני רכב בה׃ ");
INSERT INTO heb_vpl VALUES ("NH2_13","017_2_13","NEH","2","13","13","ואצאה בשער הגיא לילה ואל פני עין התנין ואל שער האשפת ואהי שבר בחומת ירושלם אשר הם פרוצים ושעריה אכלו באש׃ ");
INSERT INTO heb_vpl VALUES ("NH2_14","017_2_14","NEH","2","14","14","ואעבר אל שער העין ואל ברכת המלך ואין מקום לבהמה לעבר תחתי׃ ");
INSERT INTO heb_vpl VALUES ("NH2_15","017_2_15","NEH","2","15","15","ואהי עלה בנחל לילה ואהי שבר בחומה ואשוב ואבוא בשער הגיא ואשוב׃ ");
INSERT INTO heb_vpl VALUES ("NH2_16","017_2_16","NEH","2","16","16","והסגנים לא ידעו אנה הלכתי ומה אני עשה וליהודים ולכהנים ולחרים ולסגנים וליתר עשה המלאכה עד כן לא הגדתי׃ ");
INSERT INTO heb_vpl VALUES ("NH2_17","017_2_17","NEH","2","17","17","ואומר אלהם אתם ראים הרעה אשר אנחנו בה אשר ירושלם חרבה ושעריה נצתו באש לכו ונבנה את חומת ירושלם ולא נהיה עוד חרפה׃ ");
INSERT INTO heb_vpl VALUES ("NH2_18","017_2_18","NEH","2","18","18","ואגיד להם את יד אלהי אשר היא טובה עלי ואף דברי המלך אשר אמר לי ויאמרו נקום ובנינו ויחזקו ידיהם לטובה׃ ");
INSERT INTO heb_vpl VALUES ("NH2_19","017_2_19","NEH","2","19","19","וישמע סנבלט החרני וטביה העבד העמוני וגשם הערבי וילעגו לנו ויבזו עלינו ויאמרו מה הדבר הזה אשר אתם עשים העל המלך אתם מרדים׃ ");
INSERT INTO heb_vpl VALUES ("NH2_20","017_2_20","NEH","2","20","20","ואשיב אותם דבר ואומר להם אלהי השמים הוא יצליח לנו ואנחנו עבדיו נקום ובנינו ולכם אין חלק וצדקה וזכרון בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("NH3_1","017_3_1","NEH","3","1","1","ויקם אלישיב הכהן הגדול ואחיו הכהנים ויבנו את שער הצאן המה קדשוהו ויעמידו דלתתיו ועד מגדל המאה קדשוהו עד מגדל חננאל׃ ");
INSERT INTO heb_vpl VALUES ("NH3_2","017_3_2","NEH","3","2","2","ועל ידו בנו אנשי ירחו ועל ידו בנה זכור בן אמרי׃ ");
INSERT INTO heb_vpl VALUES ("NH3_3","017_3_3","NEH","3","3","3","ואת שער הדגים בנו בני הסנאה המה קרוהו ויעמידו דלתתיו מנעוליו ובריחיו׃ ");
INSERT INTO heb_vpl VALUES ("NH3_4","017_3_4","NEH","3","4","4","ועל ידם החזיק מרמות בן אוריה בן הקוץ ועל ידם החזיק משלם בן ברכיה בן משיזבאל ועל ידם החזיק צדוק בן בענא׃ ");
INSERT INTO heb_vpl VALUES ("NH3_5","017_3_5","NEH","3","5","5","ועל ידם החזיקו התקועים ואדיריהם לא הביאו צורם בעבדת אדניהם׃ ");
INSERT INTO heb_vpl VALUES ("NH3_6","017_3_6","NEH","3","6","6","ואת שער הישנה החזיקו יוידע בן פסח ומשלם בן בסודיה המה קרוהו ויעמידו דלתתיו ומנעליו ובריחיו׃ ");
INSERT INTO heb_vpl VALUES ("NH3_7","017_3_7","NEH","3","7","7","ועל ידם החזיק מלטיה הגבעני וידון המרנתי אנשי גבעון והמצפה לכסא פחת עבר הנהר׃ ");
INSERT INTO heb_vpl VALUES ("NH3_8","017_3_8","NEH","3","8","8","על ידו החזיק עזיאל בן חרהיה צורפים ועל ידו החזיק חנניה בן הרקחים ויעזבו ירושלם עד החומה הרחבה׃ ");
INSERT INTO heb_vpl VALUES ("NH3_9","017_3_9","NEH","3","9","9","ועל ידם החזיק רפיה בן חור שר חצי פלך ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("NH3_10","017_3_10","NEH","3","10","10","ועל ידם החזיק ידיה בן חרומף ונגד ביתו ועל ידו החזיק חטוש בן חשבניה׃ ");
INSERT INTO heb_vpl VALUES ("NH3_11","017_3_11","NEH","3","11","11","מדה שנית החזיק מלכיה בן חרם וחשוב בן פחת מואב ואת מגדל התנורים׃ ");
INSERT INTO heb_vpl VALUES ("NH3_12","017_3_12","NEH","3","12","12","ועל ידו החזיק שלום בן הלוחש שר חצי פלך ירושלם הוא ובנותיו׃ ");
INSERT INTO heb_vpl VALUES ("NH3_13","017_3_13","NEH","3","13","13","את שער הגיא החזיק חנון וישבי זנוח המה בנוהו ויעמידו דלתתיו מנעליו ובריחיו ואלף אמה בחומה עד שער השפות׃ ");
INSERT INTO heb_vpl VALUES ("NH3_14","017_3_14","NEH","3","14","14","ואת שער האשפות החזיק מלכיה בן רכב שר פלך בית הכרם הוא יבננו ויעמיד דלתתיו מנעליו ובריחיו׃ ");
INSERT INTO heb_vpl VALUES ("NH3_15","017_3_15","NEH","3","15","15","ואת שער העין החזיק שלון בן כל חזה שר פלך המצפה הוא יבננו ויטללנו ויעמידו דלתתיו מנעליו ובריחיו ואת חומת ברכת השלח לגן המלך ועד המעלות היורדות מעיר דויד׃ ");
INSERT INTO heb_vpl VALUES ("NH3_16","017_3_16","NEH","3","16","16","אחריו החזיק נחמיה בן עזבוק שר חצי פלך בית צור עד נגד קברי דויד ועד הברכה העשויה ועד בית הגברים׃ ");
INSERT INTO heb_vpl VALUES ("NH3_17","017_3_17","NEH","3","17","17","אחריו החזיקו הלוים רחום בן בני על ידו החזיק חשביה שר חצי פלך קעילה לפלכו׃ ");
INSERT INTO heb_vpl VALUES ("NH3_18","017_3_18","NEH","3","18","18","אחריו החזיקו אחיהם בוי בן חנדד שר חצי פלך קעילה׃ ");
INSERT INTO heb_vpl VALUES ("NH3_19","017_3_19","NEH","3","19","19","ויחזק על ידו עזר בן ישוע שר המצפה מדה שנית מנגד עלת הנשק המקצע׃ ");
INSERT INTO heb_vpl VALUES ("NH3_20","017_3_20","NEH","3","20","20","אחריו החרה החזיק ברוך בן זבי מדה שנית מן המקצוע עד פתח בית אלישיב הכהן הגדול׃ ");
INSERT INTO heb_vpl VALUES ("NH3_21","017_3_21","NEH","3","21","21","אחריו החזיק מרמות בן אוריה בן הקוץ מדה שנית מפתח בית אלישיב ועד תכלית בית אלישיב׃ ");
INSERT INTO heb_vpl VALUES ("NH3_22","017_3_22","NEH","3","22","22","ואחריו החזיקו הכהנים אנשי הככר׃ ");
INSERT INTO heb_vpl VALUES ("NH3_23","017_3_23","NEH","3","23","23","אחריו החזיק בנימן וחשוב נגד ביתם אחריו החזיק עזריה בן מעשיה בן ענניה אצל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("NH3_24","017_3_24","NEH","3","24","24","אחריו החזיק בנוי בן חנדד מדה שנית מבית עזריה עד המקצוע ועד הפנה׃ ");
INSERT INTO heb_vpl VALUES ("NH3_25","017_3_25","NEH","3","25","25","פלל בן אוזי מנגד המקצוע והמגדל היוצא מבית המלך העליון אשר לחצר המטרה אחריו פדיה בן פרעש׃ ");
INSERT INTO heb_vpl VALUES ("NH3_26","017_3_26","NEH","3","26","26","והנתינים היו ישבים בעפל עד נגד שער המים למזרח והמגדל היוצא׃ ");
INSERT INTO heb_vpl VALUES ("NH3_27","017_3_27","NEH","3","27","27","אחריו החזיקו התקעים מדה שנית מנגד המגדל הגדול היוצא ועד חומת העפל׃ ");
INSERT INTO heb_vpl VALUES ("NH3_28","017_3_28","NEH","3","28","28","מעל שער הסוסים החזיקו הכהנים איש לנגד ביתו׃ ");
INSERT INTO heb_vpl VALUES ("NH3_29","017_3_29","NEH","3","29","29","אחריו החזיק צדוק בן אמר נגד ביתו ואחריו החזיק שמעיה בן שכניה שמר שער המזרח׃ ");
INSERT INTO heb_vpl VALUES ("NH3_30","017_3_30","NEH","3","30","30","אחרי החזיק חנניה בן שלמיה וחנון בן צלף הששי מדה שני אחריו החזיק משלם בן ברכיה נגד נשכתו׃ ");
INSERT INTO heb_vpl VALUES ("NH3_31","017_3_31","NEH","3","31","31","אחרי החזיק מלכיה בן הצרפי עד בית הנתינים והרכלים נגד שער המפקד ועד עלית הפנה׃ ");
INSERT INTO heb_vpl VALUES ("NH3_32","017_3_32","NEH","3","32","32","ובין עלית הפנה לשער הצאן החזיקו הצרפים והרכלים׃ ");
INSERT INTO heb_vpl VALUES ("NH4_1","017_4_1","NEH","4","1","1","ויהי כאשר שמע סנבלט כי אנחנו בונים את החומה ויחר לו ויכעס הרבה וילעג על היהודים׃ ");
INSERT INTO heb_vpl VALUES ("NH4_2","017_4_2","NEH","4","2","2","ויאמר לפני אחיו וחיל שמרון ויאמר מה היהודים האמללים עשים היעזבו להם היזבחו היכלו ביום היחיו את האבנים מערמות העפר והמה שרופות׃ ");
INSERT INTO heb_vpl VALUES ("NH4_3","017_4_3","NEH","4","3","3","וטוביה העמני אצלו ויאמר גם אשר הם בונים אם יעלה שועל ופרץ חומת אבניהם׃ ");
INSERT INTO heb_vpl VALUES ("NH4_4","017_4_4","NEH","4","4","4","שמע אלהינו כי היינו בוזה והשב חרפתם אל ראשם ותנם לבזה בארץ שביה׃ ");
INSERT INTO heb_vpl VALUES ("NH4_5","017_4_5","NEH","4","5","5","ואל תכס על עונם וחטאתם מלפניך אל תמחה כי הכעיסו לנגד הבונים׃ ");
INSERT INTO heb_vpl VALUES ("NH4_6","017_4_6","NEH","4","6","6","ונבנה את החומה ותקשר כל החומה עד חציה ויהי לב לעם לעשות׃ ");
INSERT INTO heb_vpl VALUES ("NH4_7","017_4_7","NEH","4","7","7","ויהי כאשר שמע סנבלט וטוביה והערבים והעמנים והאשדודים כי עלתה ארוכה לחמות ירושלם כי החלו הפרצים להסתם ויחר להם מאד׃ ");
INSERT INTO heb_vpl VALUES ("NH4_8","017_4_8","NEH","4","8","8","ויקשרו כלם יחדו לבוא להלחם בירושלם ולעשות לו תועה׃ ");
INSERT INTO heb_vpl VALUES ("NH4_9","017_4_9","NEH","4","9","9","ונתפלל אל אלהינו ונעמיד משמר עליהם יומם ולילה מפניהם׃ ");
INSERT INTO heb_vpl VALUES ("NH4_10","017_4_10","NEH","4","10","10","ויאמר יהודה כשל כח הסבל והעפר הרבה ואנחנו לא נוכל לבנות בחומה׃ ");
INSERT INTO heb_vpl VALUES ("NH4_11","017_4_11","NEH","4","11","11","ויאמרו צרינו לא ידעו ולא יראו עד אשר נבוא אל תוכם והרגנום והשבתנו את המלאכה׃ ");
INSERT INTO heb_vpl VALUES ("NH4_12","017_4_12","NEH","4","12","12","ויהי כאשר באו היהודים הישבים אצלם ויאמרו לנו עשר פעמים מכל המקמות אשר תשובו עלינו׃ ");
INSERT INTO heb_vpl VALUES ("NH4_13","017_4_13","NEH","4","13","13","ואעמיד מתחתיות למקום מאחרי לחומה בצחחיים ואעמיד את העם למשפחות עם חרבתיהם רמחיהם וקשתתיהם׃ ");
INSERT INTO heb_vpl VALUES ("NH4_14","017_4_14","NEH","4","14","14","וארא ואקום ואמר אל החרים ואל הסגנים ואל יתר העם אל תיראו מפניהם את אדני הגדול והנורא זכרו והלחמו על אחיכם בניכם ובנתיכם נשיכם ובתיכם׃ ");
INSERT INTO heb_vpl VALUES ("NH4_15","017_4_15","NEH","4","15","15","ויהי כאשר שמעו אויבינו כי נודע לנו ויפר האלהים את עצתם ונשוב כלנו אל החומה איש אל מלאכתו׃ ");
INSERT INTO heb_vpl VALUES ("NH4_16","017_4_16","NEH","4","16","16","ויהי מן היום ההוא חצי נערי עשים במלאכה וחצים מחזיקים והרמחים המגנים והקשתות והשרינים והשרים אחרי כל בית יהודה׃ ");
INSERT INTO heb_vpl VALUES ("NH4_17","017_4_17","NEH","4","17","17","הבונים בחומה והנשאים בסבל עמשים באחת ידו עשה במלאכה ואחת מחזקת השלח׃ ");
INSERT INTO heb_vpl VALUES ("NH4_18","017_4_18","NEH","4","18","18","והבונים איש חרבו אסורים על מתניו ובונים והתוקע בשופר אצלי׃ ");
INSERT INTO heb_vpl VALUES ("NH4_19","017_4_19","NEH","4","19","19","ואמר אל החרים ואל הסגנים ואל יתר העם המלאכה הרבה ורחבה ואנחנו נפרדים על החומה רחוקים איש מאחיו׃ ");
INSERT INTO heb_vpl VALUES ("NH4_20","017_4_20","NEH","4","20","20","במקום אשר תשמעו את קול השופר שמה תקבצו אלינו אלהינו ילחם לנו׃ ");
INSERT INTO heb_vpl VALUES ("NH4_21","017_4_21","NEH","4","21","21","ואנחנו עשים במלאכה וחצים מחזיקים ברמחים מעלות השחר עד צאת הכוכבים׃ ");
INSERT INTO heb_vpl VALUES ("NH4_22","017_4_22","NEH","4","22","22","גם בעת ההיא אמרתי לעם איש ונערו ילינו בתוך ירושלם והיו לנו הלילה משמר והיום מלאכה׃ ");
INSERT INTO heb_vpl VALUES ("NH4_23","017_4_23","NEH","4","23","23","ואין אני ואחי ונערי ואנשי המשמר אשר אחרי אין אנחנו פשטים בגדינו איש שלחו המים׃ ");
INSERT INTO heb_vpl VALUES ("NH5_1","017_5_1","NEH","5","1","1","ותהי צעקת העם ונשיהם גדולה אל אחיהם היהודים׃ ");
INSERT INTO heb_vpl VALUES ("NH5_2","017_5_2","NEH","5","2","2","ויש אשר אמרים בנינו ובנתינו אנחנו רבים ונקחה דגן ונאכלה ונחיה׃ ");
INSERT INTO heb_vpl VALUES ("NH5_3","017_5_3","NEH","5","3","3","ויש אשר אמרים שדתינו וכרמינו ובתינו אנחנו ערבים ונקחה דגן ברעב׃ ");
INSERT INTO heb_vpl VALUES ("NH5_4","017_5_4","NEH","5","4","4","ויש אשר אמרים לוינו כסף למדת המלך שדתינו וכרמינו׃ ");
INSERT INTO heb_vpl VALUES ("NH5_5","017_5_5","NEH","5","5","5","ועתה כבשר אחינו בשרנו כבניהם בנינו והנה אנחנו כבשים את בנינו ואת בנתינו לעבדים ויש מבנתינו נכבשות ואין לאל ידנו ושדתינו וכרמינו לאחרים׃ ");
INSERT INTO heb_vpl VALUES ("NH5_6","017_5_6","NEH","5","6","6","ויחר לי מאד כאשר שמעתי את זעקתם ואת הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("NH5_7","017_5_7","NEH","5","7","7","וימלך לבי עלי ואריבה את החרים ואת הסגנים ואמרה להם משא איש באחיו אתם נשאים ואתן עליהם קהלה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("NH5_8","017_5_8","NEH","5","8","8","ואמרה להם אנחנו קנינו את אחינו היהודים הנמכרים לגוים כדי בנו וגם אתם תמכרו את אחיכם ונמכרו לנו ויחרישו ולא מצאו דבר׃ ");
INSERT INTO heb_vpl VALUES ("NH5_9","017_5_9","NEH","5","9","9","ויאמר לא טוב הדבר אשר אתם עשים הלוא ביראת אלהינו תלכו מחרפת הגוים אויבינו׃ ");
INSERT INTO heb_vpl VALUES ("NH5_10","017_5_10","NEH","5","10","10","וגם אני אחי ונערי נשים בהם כסף ודגן נעזבה נא את המשא הזה׃ ");
INSERT INTO heb_vpl VALUES ("NH5_11","017_5_11","NEH","5","11","11","השיבו נא להם כהיום שדתיהם כרמיהם זיתיהם ובתיהם ומאת הכסף והדגן התירוש והיצהר אשר אתם נשים בהם׃ ");
INSERT INTO heb_vpl VALUES ("NH5_12","017_5_12","NEH","5","12","12","ויאמרו נשיב ומהם לא נבקש כן נעשה כאשר אתה אומר ואקרא את הכהנים ואשביעם לעשות כדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("NH5_13","017_5_13","NEH","5","13","13","גם חצני נערתי ואמרה ככה ינער האלהים את כל האיש אשר לא יקים את הדבר הזה מביתו ומיגיעו וככה יהיה נעור ורק ויאמרו כל הקהל אמן ויהללו את יהוה ויעש העם כדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("NH5_14","017_5_14","NEH","5","14","14","גם מיום אשר צוה אתי להיות פחם בארץ יהודה משנת עשרים ועד שנת שלשים ושתים לארתחשסתא המלך שנים שתים עשרה אני ואחי לחם הפחה לא אכלתי׃ ");
INSERT INTO heb_vpl VALUES ("NH5_15","017_5_15","NEH","5","15","15","והפחות הראשנים אשר לפני הכבידו על העם ויקחו מהם בלחם ויין אחר כסף שקלים ארבעים גם נעריהם שלטו על העם ואני לא עשיתי כן מפני יראת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("NH5_16","017_5_16","NEH","5","16","16","וגם במלאכת החומה הזאת החזקתי ושדה לא קנינו וכל נערי קבוצים שם על המלאכה׃ ");
INSERT INTO heb_vpl VALUES ("NH5_17","017_5_17","NEH","5","17","17","והיהודים והסגנים מאה וחמשים איש והבאים אלינו מן הגוים אשר סביבתינו על שלחני׃ ");
INSERT INTO heb_vpl VALUES ("NH5_18","017_5_18","NEH","5","18","18","ואשר היה נעשה ליום אחד שור אחד צאן שש בררות וצפרים נעשו לי ובין עשרת ימים בכל יין להרבה ועם זה לחם הפחה לא בקשתי כי כבדה העבדה על העם הזה׃ ");
INSERT INTO heb_vpl VALUES ("NH5_19","017_5_19","NEH","5","19","19","זכרה לי אלהי לטובה כל אשר עשיתי על העם הזה׃ ");
INSERT INTO heb_vpl VALUES ("NH6_1","017_6_1","NEH","6","1","1","ויהי כאשר נשמע לסנבלט וטוביה ולגשם הערבי וליתר איבינו כי בניתי את החומה ולא נותר בה פרץ גם עד העת ההיא דלתות לא העמדתי בשערים׃ ");
INSERT INTO heb_vpl VALUES ("NH6_2","017_6_2","NEH","6","2","2","וישלח סנבלט וגשם אלי לאמר לכה ונועדה יחדו בכפירים בבקעת אונו והמה חשבים לעשות לי רעה׃ ");
INSERT INTO heb_vpl VALUES ("NH6_3","017_6_3","NEH","6","3","3","ואשלחה עליהם מלאכים לאמר מלאכה גדולה אני עשה ולא אוכל לרדת למה תשבת המלאכה כאשר ארפה וירדתי אליכם׃ ");
INSERT INTO heb_vpl VALUES ("NH6_4","017_6_4","NEH","6","4","4","וישלחו אלי כדבר הזה ארבע פעמים ואשיב אותם כדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("NH6_5","017_6_5","NEH","6","5","5","וישלח אלי סנבלט כדבר הזה פעם חמישית את נערו ואגרת פתוחה בידו׃ ");
INSERT INTO heb_vpl VALUES ("NH6_6","017_6_6","NEH","6","6","6","כתוב בה בגוים נשמע וגשמו אמר אתה והיהודים חשבים למרוד על כן אתה בונה החומה ואתה הוה להם למלך כדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("NH6_7","017_6_7","NEH","6","7","7","וגם נביאים העמדת לקרא עליך בירושלם לאמר מלך ביהודה ועתה ישמע למלך כדברים האלה ועתה לכה ונועצה יחדו׃ ");
INSERT INTO heb_vpl VALUES ("NH6_8","017_6_8","NEH","6","8","8","ואשלחה אליו לאמר לא נהיה כדברים האלה אשר אתה אומר כי מלבך אתה בודאם׃ ");
INSERT INTO heb_vpl VALUES ("NH6_9","017_6_9","NEH","6","9","9","כי כלם מיראים אותנו לאמר ירפו ידיהם מן המלאכה ולא תעשה ועתה חזק את ידי׃ ");
INSERT INTO heb_vpl VALUES ("NH6_10","017_6_10","NEH","6","10","10","ואני באתי בית שמעיה בן דליה בן מהיטבאל והוא עצור ויאמר נועד אל בית האלהים אל תוך ההיכל ונסגרה דלתות ההיכל כי באים להרגך ולילה באים להרגך׃ ");
INSERT INTO heb_vpl VALUES ("NH6_11","017_6_11","NEH","6","11","11","ואמרה האיש כמוני יברח ומי כמוני אשר יבוא אל ההיכל וחי לא אבוא׃ ");
INSERT INTO heb_vpl VALUES ("NH6_12","017_6_12","NEH","6","12","12","ואכירה והנה לא אלהים שלחו כי הנבואה דבר עלי וטוביה וסנבלט שכרו׃ ");
INSERT INTO heb_vpl VALUES ("NH6_13","017_6_13","NEH","6","13","13","למען שכור הוא למען אירא ואעשה כן וחטאתי והיה להם לשם רע למען יחרפוני׃ ");
INSERT INTO heb_vpl VALUES ("NH6_14","017_6_14","NEH","6","14","14","זכרה אלהי לטוביה ולסנבלט כמעשיו אלה וגם לנועדיה הנביאה וליתר הנביאים אשר היו מיראים אותי׃ ");
INSERT INTO heb_vpl VALUES ("NH6_15","017_6_15","NEH","6","15","15","ותשלם החומה בעשרים וחמשה לאלול לחמשים ושנים יום׃ ");
INSERT INTO heb_vpl VALUES ("NH6_16","017_6_16","NEH","6","16","16","ויהי כאשר שמעו כל אויבינו ויראו כל הגוים אשר סביבתינו ויפלו מאד בעיניהם וידעו כי מאת אלהינו נעשתה המלאכה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("NH6_17","017_6_17","NEH","6","17","17","גם בימים ההם מרבים חרי יהודה אגרתיהם הולכות על טוביה ואשר לטוביה באות אליהם׃ ");
INSERT INTO heb_vpl VALUES ("NH6_18","017_6_18","NEH","6","18","18","כי רבים ביהודה בעלי שבועה לו כי חתן הוא לשכניה בן ארח ויהוחנן בנו לקח את בת משלם בן ברכיה׃ ");
INSERT INTO heb_vpl VALUES ("NH6_19","017_6_19","NEH","6","19","19","גם טובתיו היו אמרים לפני ודברי היו מוציאים לו אגרות שלח טוביה ליראני׃ ");
INSERT INTO heb_vpl VALUES ("NH7_1","017_7_1","NEH","7","1","1","ויהי כאשר נבנתה החומה ואעמיד הדלתות ויפקדו השוערים והמשררים והלוים׃ ");
INSERT INTO heb_vpl VALUES ("NH7_2","017_7_2","NEH","7","2","2","ואצוה את חנני אחי ואת חנניה שר הבירה על ירושלם כי הוא כאיש אמת וירא את האלהים מרבים׃ ");
INSERT INTO heb_vpl VALUES ("NH7_3","017_7_3","NEH","7","3","3","ויאמר להם לא יפתחו שערי ירושלם עד חם השמש ועד הם עמדים יגיפו הדלתות ואחזו והעמיד משמרות ישבי ירושלם איש במשמרו ואיש נגד ביתו׃ ");
INSERT INTO heb_vpl VALUES ("NH7_4","017_7_4","NEH","7","4","4","והעיר רחבת ידים וגדולה והעם מעט בתוכה ואין בתים בנוים׃ ");
INSERT INTO heb_vpl VALUES ("NH7_5","017_7_5","NEH","7","5","5","ויתן אלהי אל לבי ואקבצה את החרים ואת הסגנים ואת העם להתיחש ואמצא ספר היחש העולים בראשונה ואמצא כתוב בו׃ ");
INSERT INTO heb_vpl VALUES ("NH7_6","017_7_6","NEH","7","6","6","אלה בני המדינה העלים משבי הגולה אשר הגלה נבוכדנצר מלך בבל וישובו לירושלם וליהודה איש לעירו׃ ");
INSERT INTO heb_vpl VALUES ("NH7_7","017_7_7","NEH","7","7","7","הבאים עם זרבבל ישוע נחמיה עזריה רעמיה נחמני מרדכי בלשן מספרת בגוי נחום בענה מספר אנשי עם ישראל׃ ");
