INSERT INTO heb_vpl VALUES ("NH7_61","017_7_61","NEH","7","61","61","ואלה העולים מתל מלח תל חרשא כרוב אדון ואמר ולא יכלו להגיד בית אבותם וזרעם אם מישראל הם׃ ");
