INSERT INTO heb_vpl VALUES ("NH7_63","017_7_63","NEH","7","63","63","ומן הכהנים בני חביה בני הקוץ בני ברזלי אשר לקח מבנות ברזלי הגלעדי אשה ויקרא על שמם׃ ");
INSERT INTO heb_vpl VALUES ("NH7_64","017_7_64","NEH","7","64","64","אלה בקשו כתבם המתיחשים ולא נמצא ויגאלו מן הכהנה׃ ");
INSERT INTO heb_vpl VALUES ("NH7_65","017_7_65","NEH","7","65","65","ויאמר התרשתא להם אשר לא יאכלו מקדש הקדשים עד עמד הכהן לאורים ותומים׃ ");
INSERT INTO heb_vpl VALUES ("NH7_66","017_7_66","NEH","7","66","66","כל הקהל כאחד ארבע רבוא אלפים שלש מאות וששים׃ ");
INSERT INTO heb_vpl VALUES ("NH7_67","017_7_67","NEH","7","67","67","מלבד עבדיהם ואמהתיהם אלה שבעת אלפים שלש מאות שלשים ושבעה ולהם משררים ומשררות מאתים וארבעים וחמשה׃ ");
INSERT INTO heb_vpl VALUES ("NH7_68","017_7_68","NEH","7","68","68","סוסיהם שבע מאות שלשים וששה פרדיהם מאתים ארבעים וחמשה׃ ");
INSERT INTO heb_vpl VALUES ("NH7_69","017_7_69","NEH","7","69","69","גמלים ארבע מאות שלשים וחמשה חמרים ששת אלפים שבע מאות ועשרים׃ ");
INSERT INTO heb_vpl VALUES ("NH7_70","017_7_70","NEH","7","70","70","ומקצת ראשי האבות נתנו למלאכה התרשתא נתן לאוצר זהב דרכמנים אלף מזרקות חמשים כתנות כהנים שלשים וחמש מאות׃ ");
INSERT INTO heb_vpl VALUES ("NH7_71","017_7_71","NEH","7","71","71","ומראשי האבות נתנו לאוצר המלאכה זהב דרכמונים שתי רבות וכסף מנים אלפים ומאתים׃ ");
INSERT INTO heb_vpl VALUES ("NH7_72","017_7_72","NEH","7","72","72","ואשר נתנו שארית העם זהב דרכמונים שתי רבוא וכסף מנים אלפים וכתנת כהנים ששים ושבעה׃ ");
INSERT INTO heb_vpl VALUES ("NH7_73","017_7_73","NEH","7","73","73","וישבו הכהנים והלוים והשוערים והמשררים ומן העם והנתינים וכל ישראל בעריהם ויגע החדש השביעי ובני ישראל בעריהם׃ ");
INSERT INTO heb_vpl VALUES ("NH8_1","017_8_1","NEH","8","1","1","ויאספו כל העם כאיש אחד אל הרחוב אשר לפני שער המים ויאמרו לעזרא הספר להביא את ספר תורת משה אשר צוה יהוה את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("NH8_2","017_8_2","NEH","8","2","2","ויביא עזרא הכהן את התורה לפני הקהל מאיש ועד אשה וכל מבין לשמע ביום אחד לחדש השביעי׃ ");
INSERT INTO heb_vpl VALUES ("NH8_3","017_8_3","NEH","8","3","3","ויקרא בו לפני הרחוב אשר לפני שער המים מן האור עד מחצית היום נגד האנשים והנשים והמבינים ואזני כל העם אל ספר התורה׃ ");
INSERT INTO heb_vpl VALUES ("NH8_4","017_8_4","NEH","8","4","4","ויעמד עזרא הספר על מגדל עץ אשר עשו לדבר ויעמד אצלו מתתיה ושמע ועניה ואוריה וחלקיה ומעשיה על ימינו ומשמאלו פדיה ומישאל ומלכיה וחשם וחשבדנה זכריה משלם׃ ");
INSERT INTO heb_vpl VALUES ("NH8_5","017_8_5","NEH","8","5","5","ויפתח עזרא הספר לעיני כל העם כי מעל כל העם היה וכפתחו עמדו כל העם׃ ");
INSERT INTO heb_vpl VALUES ("NH8_6","017_8_6","NEH","8","6","6","ויברך עזרא את יהוה האלהים הגדול ויענו כל העם אמן אמן במעל ידיהם ויקדו וישתחו ליהוה אפים ארצה׃ ");
INSERT INTO heb_vpl VALUES ("NH8_7","017_8_7","NEH","8","7","7","וישוע ובני ושרביה ימין עקוב שבתי הודיה מעשיה קליטא עזריה יוזבד חנן פלאיה והלוים מבינים את העם לתורה והעם על עמדם׃ ");
INSERT INTO heb_vpl VALUES ("NH8_8","017_8_8","NEH","8","8","8","ויקראו בספר בתורת האלהים מפרש ושום שכל ויבינו במקרא׃ ");
INSERT INTO heb_vpl VALUES ("NH8_9","017_8_9","NEH","8","9","9","ויאמר נחמיה הוא התרשתא ועזרא הכהן הספר והלוים המבינים את העם לכל העם היום קדש הוא ליהוה אלהיכם אל תתאבלו ואל תבכו כי בוכים כל העם כשמעם את דברי התורה׃ ");
INSERT INTO heb_vpl VALUES ("NH8_10","017_8_10","NEH","8","10","10","ויאמר להם לכו אכלו משמנים ושתו ממתקים ושלחו מנות לאין נכון לו כי קדוש היום לאדנינו ואל תעצבו כי חדות יהוה היא מעזכם׃ ");
INSERT INTO heb_vpl VALUES ("NH8_11","017_8_11","NEH","8","11","11","והלוים מחשים לכל העם לאמר הסו כי היום קדש ואל תעצבו׃ ");
INSERT INTO heb_vpl VALUES ("NH8_12","017_8_12","NEH","8","12","12","וילכו כל העם לאכל ולשתות ולשלח מנות ולעשות שמחה גדולה כי הבינו בדברים אשר הודיעו להם׃ ");
INSERT INTO heb_vpl VALUES ("NH8_13","017_8_13","NEH","8","13","13","וביום השני נאספו ראשי האבות לכל העם הכהנים והלוים אל עזרא הספר ולהשכיל אל דברי התורה׃ ");
INSERT INTO heb_vpl VALUES ("NH8_14","017_8_14","NEH","8","14","14","וימצאו כתוב בתורה אשר צוה יהוה ביד משה אשר ישבו בני ישראל בסכות בחג בחדש השביעי׃ ");
INSERT INTO heb_vpl VALUES ("NH8_15","017_8_15","NEH","8","15","15","ואשר ישמיעו ויעבירו קול בכל עריהם ובירושלם לאמר צאו ההר והביאו עלי זית ועלי עץ שמן ועלי הדס ועלי תמרים ועלי עץ עבת לעשת סכת ככתוב׃ ");
INSERT INTO heb_vpl VALUES ("NH8_16","017_8_16","NEH","8","16","16","ויצאו העם ויביאו ויעשו להם סכות איש על גגו ובחצרתיהם ובחצרות בית האלהים וברחוב שער המים וברחוב שער אפרים׃ ");
INSERT INTO heb_vpl VALUES ("NH8_17","017_8_17","NEH","8","17","17","ויעשו כל הקהל השבים מן השבי סכות וישבו בסכות כי לא עשו מימי ישוע בן נון כן בני ישראל עד היום ההוא ותהי שמחה גדולה מאד׃ ");
INSERT INTO heb_vpl VALUES ("NH8_18","017_8_18","NEH","8","18","18","ויקרא בספר תורת האלהים יום ביום מן היום הראשון עד היום האחרון ויעשו חג שבעת ימים וביום השמיני עצרת כמשפט׃ ");
INSERT INTO heb_vpl VALUES ("NH9_1","017_9_1","NEH","9","1","1","וביום עשרים וארבעה לחדש הזה נאספו בני ישראל בצום ובשקים ואדמה עליהם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_2","017_9_2","NEH","9","2","2","ויבדלו זרע ישראל מכל בני נכר ויעמדו ויתודו על חטאתיהם ועונות אבתיהם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_3","017_9_3","NEH","9","3","3","ויקומו על עמדם ויקראו בספר תורת יהוה אלהיהם רבעית היום ורבעית מתודים ומשתחוים ליהוה אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_4","017_9_4","NEH","9","4","4","ויקם על מעלה הלוים ישוע ובני קדמיאל שבניה בני שרביה בני כנני ויזעקו בקול גדול אל יהוה אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_5","017_9_5","NEH","9","5","5","ויאמרו הלוים ישוע וקדמיאל בני חשבניה שרביה הודיה שבניה פתחיה קומו ברכו את יהוה אלהיכם מן העולם עד העולם ויברכו שם כבודך ומרומם על כל ברכה ותהלה׃ ");
INSERT INTO heb_vpl VALUES ("NH9_6","017_9_6","NEH","9","6","6","אתה הוא יהוה לבדך את עשית את השמים שמי השמים וכל צבאם הארץ וכל אשר עליה הימים וכל אשר בהם ואתה מחיה את כלם וצבא השמים לך משתחוים׃ ");
INSERT INTO heb_vpl VALUES ("NH9_7","017_9_7","NEH","9","7","7","אתה הוא יהוה האלהים אשר בחרת באברם והוצאתו מאור כשדים ושמת שמו אברהם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_8","017_9_8","NEH","9","8","8","ומצאת את לבבו נאמן לפניך וכרות עמו הברית לתת את ארץ הכנעני החתי האמרי והפרזי והיבוסי והגרגשי לתת לזרעו ותקם את דבריך כי צדיק אתה׃ ");
INSERT INTO heb_vpl VALUES ("NH9_9","017_9_9","NEH","9","9","9","ותרא את עני אבתינו במצרים ואת זעקתם שמעת על ים סוף׃ ");
INSERT INTO heb_vpl VALUES ("NH9_10","017_9_10","NEH","9","10","10","ותתן אתת ומפתים בפרעה ובכל עבדיו ובכל עם ארצו כי ידעת כי הזידו עליהם ותעש לך שם כהיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("NH9_11","017_9_11","NEH","9","11","11","והים בקעת לפניהם ויעברו בתוך הים ביבשה ואת רדפיהם השלכת במצולת כמו אבן במים עזים׃ ");
INSERT INTO heb_vpl VALUES ("NH9_12","017_9_12","NEH","9","12","12","ובעמוד ענן הנחיתם יומם ובעמוד אש לילה להאיר להם את הדרך אשר ילכו בה׃ ");
INSERT INTO heb_vpl VALUES ("NH9_13","017_9_13","NEH","9","13","13","ועל הר סיני ירדת ודבר עמהם משמים ותתן להם משפטים ישרים ותורות אמת חקים ומצות טובים׃ ");
INSERT INTO heb_vpl VALUES ("NH9_14","017_9_14","NEH","9","14","14","ואת שבת קדשך הודעת להם ומצוות וחקים ותורה צוית להם ביד משה עבדך׃ ");
INSERT INTO heb_vpl VALUES ("NH9_15","017_9_15","NEH","9","15","15","ולחם משמים נתתה להם לרעבם ומים מסלע הוצאת להם לצמאם ותאמר להם לבוא לרשת את הארץ אשר נשאת את ידך לתת להם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_16","017_9_16","NEH","9","16","16","והם ואבתינו הזידו ויקשו את ערפם ולא שמעו אל מצותיך׃ ");
INSERT INTO heb_vpl VALUES ("NH9_17","017_9_17","NEH","9","17","17","וימאנו לשמע ולא זכרו נפלאתיך אשר עשית עמהם ויקשו את ערפם ויתנו ראש לשוב לעבדתם במרים ואתה אלוה סליחות חנון ורחום ארך אפים ורב וחסד ולא עזבתם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_18","017_9_18","NEH","9","18","18","אף כי עשו להם עגל מסכה ויאמרו זה אלהיך אשר העלך ממצרים ויעשו נאצות גדלות׃ ");
INSERT INTO heb_vpl VALUES ("NH9_19","017_9_19","NEH","9","19","19","ואתה ברחמיך הרבים לא עזבתם במדבר את עמוד הענן לא סר מעליהם ביומם להנחתם בהדרך ואת עמוד האש בלילה להאיר להם ואת הדרך אשר ילכו בה׃ ");
INSERT INTO heb_vpl VALUES ("NH9_20","017_9_20","NEH","9","20","20","ורוחך הטובה נתת להשכילם ומנך לא מנעת מפיהם ומים נתתה להם לצמאם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_21","017_9_21","NEH","9","21","21","וארבעים שנה כלכלתם במדבר לא חסרו שלמתיהם לא בלו ורגליהם לא בצקו׃ ");
INSERT INTO heb_vpl VALUES ("NH9_22","017_9_22","NEH","9","22","22","ותתן להם ממלכות ועממים ותחלקם לפאה ויירשו את ארץ סיחון ואת ארץ מלך חשבון ואת ארץ עוג מלך הבשן׃ ");
INSERT INTO heb_vpl VALUES ("NH9_23","017_9_23","NEH","9","23","23","ובניהם הרבית כככבי השמים ותביאם אל הארץ אשר אמרת לאבתיהם לבוא לרשת׃ ");
INSERT INTO heb_vpl VALUES ("NH9_24","017_9_24","NEH","9","24","24","ויבאו הבנים ויירשו את הארץ ותכנע לפניהם את ישבי הארץ הכנענים ותתנם בידם ואת מלכיהם ואת עממי הארץ לעשות בהם כרצונם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_25","017_9_25","NEH","9","25","25","וילכדו ערים בצרות ואדמה שמנה ויירשו בתים מלאים כל טוב ברות חצובים כרמים וזיתים ועץ מאכל לרב ויאכלו וישבעו וישמינו ויתעדנו בטובך הגדול׃ ");
INSERT INTO heb_vpl VALUES ("NH9_26","017_9_26","NEH","9","26","26","וימרו וימרדו בך וישלכו את תורתך אחרי גום ואת נביאיך הרגו אשר העידו בם להשיבם אליך ויעשו נאצות גדולת׃ ");
INSERT INTO heb_vpl VALUES ("NH9_27","017_9_27","NEH","9","27","27","ותתנם ביד צריהם ויצרו להם ובעת צרתם יצעקו אליך ואתה משמים תשמע וכרחמיך הרבים תתן להם מושיעים ויושיעום מיד צריהם׃ ");
INSERT INTO heb_vpl VALUES ("NH9_28","017_9_28","NEH","9","28","28","וכנוח להם ישובו לעשות רע לפניך ותעזבם ביד איביהם וירדו בהם וישובו ויזעקוך ואתה משמים תשמע ותצילם כרחמיך רבות עתים׃ ");
INSERT INTO heb_vpl VALUES ("NH9_29","017_9_29","NEH","9","29","29","ותעד בהם להשיבם אל תורתך והמה הזידו ולא שמעו למצותיך ובמשפטיך חטאו בם אשר יעשה אדם וחיה בהם ויתנו כתף סוררת וערפם הקשו ולא שמעו׃ ");
INSERT INTO heb_vpl VALUES ("NH9_30","017_9_30","NEH","9","30","30","ותמשך עליהם שנים רבות ותעד בם ברוחך ביד נביאיך ולא האזינו ותתנם ביד עמי הארצת׃ ");
