INSERT INTO heb_vpl VALUES ("NH12_14","017_12_14","NEH","12","14","14","למלוכי יונתן לשבניה יוסף׃ ");
INSERT INTO heb_vpl VALUES ("NH12_15","017_12_15","NEH","12","15","15","לחרם עדנא למריות חלקי׃ ");
INSERT INTO heb_vpl VALUES ("NH12_16","017_12_16","NEH","12","16","16","לעדיא זכריה לגנתון משלם׃ ");
INSERT INTO heb_vpl VALUES ("NH12_17","017_12_17","NEH","12","17","17","לאביה זכרי למנימין למועדיה פלטי׃ ");
INSERT INTO heb_vpl VALUES ("NH12_18","017_12_18","NEH","12","18","18","לבלגה שמוע לשמעיה יהונתן׃ ");
INSERT INTO heb_vpl VALUES ("NH12_19","017_12_19","NEH","12","19","19","וליויריב מתני לידעיה עזי׃ ");
INSERT INTO heb_vpl VALUES ("NH12_20","017_12_20","NEH","12","20","20","לסלי קלי לעמוק עבר׃ ");
INSERT INTO heb_vpl VALUES ("NH12_21","017_12_21","NEH","12","21","21","לחלקיה חשביה לידעיה נתנאל׃ ");
INSERT INTO heb_vpl VALUES ("NH12_22","017_12_22","NEH","12","22","22","הלוים בימי אלישיב יוידע ויוחנן וידוע כתובים ראשי אבות והכהנים על מלכות דריוש הפרסי׃ ");
INSERT INTO heb_vpl VALUES ("NH12_23","017_12_23","NEH","12","23","23","בני לוי ראשי האבות כתובים על ספר דברי הימים ועד ימי יוחנן בן אלישיב׃ ");
INSERT INTO heb_vpl VALUES ("NH12_24","017_12_24","NEH","12","24","24","וראשי הלוים חשביה שרביה וישוע בן קדמיאל ואחיהם לנגדם להלל להודות במצות דויד איש האלהים משמר לעמת משמר׃ ");
INSERT INTO heb_vpl VALUES ("NH12_25","017_12_25","NEH","12","25","25","מתניה ובקבקיה עבדיה משלם טלמון עקוב שמרים שוערים משמר באספי השערים׃ ");
INSERT INTO heb_vpl VALUES ("NH12_26","017_12_26","NEH","12","26","26","אלה בימי יויקים בן ישוע בן יוצדק ובימי נחמיה הפחה ועזרא הכהן הסופר׃ ");
INSERT INTO heb_vpl VALUES ("NH12_27","017_12_27","NEH","12","27","27","ובחנכת חומת ירושלם בקשו את הלוים מכל מקומתם להביאם לירושלם לעשת חנכה ושמחה ובתודות ובשיר מצלתים נבלים ובכנרות׃ ");
INSERT INTO heb_vpl VALUES ("NH12_28","017_12_28","NEH","12","28","28","ויאספו בני המשררים ומן הככר סביבות ירושלם ומן חצרי נטפתי׃ ");
INSERT INTO heb_vpl VALUES ("NH12_29","017_12_29","NEH","12","29","29","ומבית הגלגל ומשדות גבע ועזמות כי חצרים בנו להם המשררים סביבות ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("NH12_30","017_12_30","NEH","12","30","30","ויטהרו הכהנים והלוים ויטהרו את העם ואת השערים ואת החומה׃ ");
INSERT INTO heb_vpl VALUES ("NH12_31","017_12_31","NEH","12","31","31","ואעלה את שרי יהודה מעל לחומה ואעמידה שתי תודת גדולת ותהלכת לימין מעל לחומה לשער האשפת׃ ");
INSERT INTO heb_vpl VALUES ("NH12_32","017_12_32","NEH","12","32","32","וילך אחריהם הושעיה וחצי שרי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("NH12_33","017_12_33","NEH","12","33","33","ועזריה עזרא ומשלם׃ ");
INSERT INTO heb_vpl VALUES ("NH12_34","017_12_34","NEH","12","34","34","יהודה ובנימן ושמעיה וירמיה׃ ");
INSERT INTO heb_vpl VALUES ("NH12_35","017_12_35","NEH","12","35","35","ומבני הכהנים בחצצרות זכריה בן יונתן בן שמעיה בן מתניה בן מיכיה בן זכור בן אסף׃ ");
INSERT INTO heb_vpl VALUES ("NH12_36","017_12_36","NEH","12","36","36","ואחיו שמעיה ועזראל מללי גללי מעי נתנאל ויהודה חנני בכלי שיר דויד איש האלהים ועזרא הסופר לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("NH12_37","017_12_37","NEH","12","37","37","ועל שער העין ונגדם עלו על מעלות עיר דויד במעלה לחומה מעל לבית דויד ועד שער המים מזרח׃ ");
INSERT INTO heb_vpl VALUES ("NH12_38","017_12_38","NEH","12","38","38","והתודה השנית ההולכת למואל ואני אחריה וחצי העם מעל להחומה מעל למגדל התנורים ועד החומה הרחבה׃ ");
INSERT INTO heb_vpl VALUES ("NH12_39","017_12_39","NEH","12","39","39","ומעל לשער אפרים ועל שער הישנה ועל שער הדגים ומגדל חננאל ומגדל המאה ועד שער הצאן ועמדו בשער המטרה׃ ");
INSERT INTO heb_vpl VALUES ("NH12_40","017_12_40","NEH","12","40","40","ותעמדנה שתי התודת בבית האלהים ואני וחצי הסגנים עמי׃ ");
