INSERT INTO heb_vpl VALUES ("NH12_42","017_12_42","NEH","12","42","42","ומעשיה ושמעיה ואלעזר ועזי ויהוחנן ומלכיה ועילם ועזר וישמיעו המשררים ויזרחיה הפקיד׃ ");
INSERT INTO heb_vpl VALUES ("NH12_43","017_12_43","NEH","12","43","43","ויזבחו ביום ההוא זבחים גדולים וישמחו כי האלהים שמחם שמחה גדולה וגם הנשים והילדים שמחו ותשמע שמחת ירושלם מרחוק׃ ");
INSERT INTO heb_vpl VALUES ("NH12_44","017_12_44","NEH","12","44","44","ויפקדו ביום ההוא אנשים על הנשכות לאוצרות לתרומות לראשית ולמעשרות לכנוס בהם לשדי הערים מנאות התורה לכהנים וללוים כי שמחת יהודה על הכהנים ועל הלוים העמדים׃ ");
INSERT INTO heb_vpl VALUES ("NH12_45","017_12_45","NEH","12","45","45","וישמרו משמרת אלהיהם ומשמרת הטהרה והמשררים והשערים כמצות דויד שלמה בנו׃ ");
INSERT INTO heb_vpl VALUES ("NH12_46","017_12_46","NEH","12","46","46","כי בימי דויד ואסף מקדם ראש המשררים ושיר תהלה והדות לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("NH12_47","017_12_47","NEH","12","47","47","וכל ישראל בימי זרבבל ובימי נחמיה נתנים מניות המשררים והשערים דבר יום ביומו ומקדשים ללוים והלוים מקדשים לבני אהרן׃ ");
INSERT INTO heb_vpl VALUES ("NH13_1","017_13_1","NEH","13","1","1","ביום ההוא נקרא בספר משה באזני העם ונמצא כתוב בו אשר לא יבוא עמני ומאבי בקהל האלהים עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("NH13_2","017_13_2","NEH","13","2","2","כי לא קדמו את בני ישראל בלחם ובמים וישכר עליו את בלעם לקללו ויהפך אלהינו הקללה לברכה׃ ");
INSERT INTO heb_vpl VALUES ("NH13_3","017_13_3","NEH","13","3","3","ויהי כשמעם את התורה ויבדילו כל ערב מישראל׃ ");
INSERT INTO heb_vpl VALUES ("NH13_4","017_13_4","NEH","13","4","4","ולפני מזה אלישיב הכהן נתון בלשכת בית אלהינו קרוב לטוביה׃ ");
INSERT INTO heb_vpl VALUES ("NH13_5","017_13_5","NEH","13","5","5","ויעש לו לשכה גדולה ושם היו לפנים נתנים את המנחה הלבונה והכלים ומעשר הדגן התירוש והיצהר מצות הלוים והמשררים והשערים ותרומת הכהנים׃ ");
INSERT INTO heb_vpl VALUES ("NH13_6","017_13_6","NEH","13","6","6","ובכל זה לא הייתי בירושלם כי בשנת שלשים ושתים לארתחשסתא מלך בבל באתי אל המלך ולקץ ימים נשאלתי מן המלך׃ ");
INSERT INTO heb_vpl VALUES ("NH13_7","017_13_7","NEH","13","7","7","ואבוא לירושלם ואבינה ברעה אשר עשה אלישיב לטוביה לעשות לו נשכה בחצרי בית האלהים׃ ");
INSERT INTO heb_vpl VALUES ("NH13_8","017_13_8","NEH","13","8","8","וירע לי מאד ואשליכה את כל כלי בית טוביה החוץ מן הלשכה׃ ");
INSERT INTO heb_vpl VALUES ("NH13_9","017_13_9","NEH","13","9","9","ואמרה ויטהרו הלשכות ואשיבה שם כלי בית האלהים את המנחה והלבונה׃ ");
INSERT INTO heb_vpl VALUES ("NH13_10","017_13_10","NEH","13","10","10","ואדעה כי מניות הלוים לא נתנה ויברחו איש לשדהו הלוים והמשררים עשי המלאכה׃ ");
INSERT INTO heb_vpl VALUES ("NH13_11","017_13_11","NEH","13","11","11","ואריבה את הסגנים ואמרה מדוע נעזב בית האלהים ואקבצם ואעמדם על עמדם׃ ");
INSERT INTO heb_vpl VALUES ("NH13_12","017_13_12","NEH","13","12","12","וכל יהודה הביאו מעשר הדגן והתירוש והיצהר לאוצרות׃ ");
INSERT INTO heb_vpl VALUES ("NH13_13","017_13_13","NEH","13","13","13","ואוצרה על אוצרות שלמיה הכהן וצדוק הסופר ופדיה מן הלוים ועל ידם חנן בן זכור בן מתניה כי נאמנים נחשבו ועליהם לחלק לאחיהם׃ ");
INSERT INTO heb_vpl VALUES ("NH13_14","017_13_14","NEH","13","14","14","זכרה לי אלהי על זאת ואל תמח חסדי אשר עשיתי בבית אלהי ובמשמריו׃ ");
INSERT INTO heb_vpl VALUES ("NH13_15","017_13_15","NEH","13","15","15","בימים ההמה ראיתי ביהודה דרכים גתות בשבת ומביאים הערמות ועמסים על החמרים ואף יין ענבים ותאנים וכל משא ומביאים ירושלם ביום השבת ואעיד ביום מכרם ציד׃ ");
INSERT INTO heb_vpl VALUES ("NH13_16","017_13_16","NEH","13","16","16","והצרים ישבו בה מביאים דאג וכל מכר ומכרים בשבת לבני יהודה ובירושלם׃ ");
INSERT INTO heb_vpl VALUES ("NH13_17","017_13_17","NEH","13","17","17","ואריבה את חרי יהודה ואמרה להם מה הדבר הרע הזה אשר אתם עשים ומחללים את יום השבת׃ ");
INSERT INTO heb_vpl VALUES ("NH13_18","017_13_18","NEH","13","18","18","הלוא כה עשו אבתיכם ויבא אלהינו עלינו את כל הרעה הזאת ועל העיר הזאת ואתם מוסיפים חרון על ישראל לחלל את השבת׃ ");
INSERT INTO heb_vpl VALUES ("NH13_19","017_13_19","NEH","13","19","19","ויהי כאשר צללו שערי ירושלם לפני השבת ואמרה ויסגרו הדלתות ואמרה אשר לא יפתחום עד אחר השבת ומנערי העמדתי על השערים לא יבוא משא ביום השבת׃ ");
INSERT INTO heb_vpl VALUES ("NH13_20","017_13_20","NEH","13","20","20","וילינו הרכלים ומכרי כל ממכר מחוץ לירושלם פעם ושתים׃ ");
INSERT INTO heb_vpl VALUES ("NH13_21","017_13_21","NEH","13","21","21","ואעידה בהם ואמרה אליהם מדוע אתם לנים נגד החומה אם תשנו יד אשלח בכם מן העת ההיא לא באו בשבת׃ ");
INSERT INTO heb_vpl VALUES ("NH13_22","017_13_22","NEH","13","22","22","ואמרה ללוים אשר יהיו מטהרים ובאים שמרים השערים לקדש את יום השבת גם זאת זכרה לי אלהי וחוסה עלי כרב חסדך׃ ");
INSERT INTO heb_vpl VALUES ("NH13_23","017_13_23","NEH","13","23","23","גם בימים ההם ראיתי את היהודים השיבו נשים אשדודיות עמוניות מואביות׃ ");
INSERT INTO heb_vpl VALUES ("NH13_24","017_13_24","NEH","13","24","24","ובניהם חצי מדבר אשדודית ואינם מכירים לדבר יהודית וכלשון עם ועם׃ ");
INSERT INTO heb_vpl VALUES ("NH13_25","017_13_25","NEH","13","25","25","ואריב עמם ואקללם ואכה מהם אנשים ואמרטם ואשביעם באלהים אם תתנו בנתיכם לבניהם ואם תשאו מבנתיהם לבניכם ולכם׃ ");
INSERT INTO heb_vpl VALUES ("NH13_26","017_13_26","NEH","13","26","26","הלוא על אלה חטא שלמה מלך ישראל ובגוים הרבים לא היה מלך כמהו ואהוב לאלהיו היה ויתנהו אלהים מלך על כל ישראל גם אותו החטיאו הנשים הנכריות׃ ");
INSERT INTO heb_vpl VALUES ("NH13_27","017_13_27","NEH","13","27","27","ולכם הנשמע לעשת את כל הרעה הגדולה הזאת למעל באלהינו להשיב נשים נכריות׃ ");
INSERT INTO heb_vpl VALUES ("NH13_28","017_13_28","NEH","13","28","28","ומבני יוידע בן אלישיב הכהן הגדול חתן לסנבלט החרני ואבריחהו מעלי׃ ");
INSERT INTO heb_vpl VALUES ("NH13_29","017_13_29","NEH","13","29","29","זכרה להם אלהי על גאלי הכהנה וברית הכהנה והלוים׃ ");
INSERT INTO heb_vpl VALUES ("NH13_30","017_13_30","NEH","13","30","30","וטהרתים מכל נכר ואעמידה משמרות לכהנים וללוים איש במלאכתו׃ ");
INSERT INTO heb_vpl VALUES ("NH13_31","017_13_31","NEH","13","31","31","ולקרבן העצים בעתים מזמנות ולבכורים זכרה לי אלהי לטובה׃ ");
INSERT INTO heb_vpl VALUES ("ET1_1","018_1_1","EST","1","1","1","ויהי בימי אחשורוש הוא אחשורוש המלך מהדו ועד כוש שבע ועשרים ומאה מדינה׃ ");
INSERT INTO heb_vpl VALUES ("ET1_2","018_1_2","EST","1","2","2","בימים ההם כשבת המלך אחשורוש על כסא מלכותו אשר בשושן הבירה׃ ");
INSERT INTO heb_vpl VALUES ("ET1_3","018_1_3","EST","1","3","3","בשנת שלוש למלכו עשה משתה לכל שריו ועבדיו חיל פרס ומדי הפרתמים ושרי המדינות לפניו׃ ");
INSERT INTO heb_vpl VALUES ("ET1_4","018_1_4","EST","1","4","4","בהראתו את עשר כבוד מלכותו ואת יקר תפארת גדולתו ימים רבים שמונים ומאת יום׃ ");
INSERT INTO heb_vpl VALUES ("ET1_5","018_1_5","EST","1","5","5","ובמלואת הימים האלה עשה המלך לכל העם הנמצאים בשושן הבירה למגדול ועד קטן משתה שבעת ימים בחצר גנת ביתן המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET1_6","018_1_6","EST","1","6","6","חור כרפס ותכלת אחוז בחבלי בוץ וארגמן על גלילי כסף ועמודי שש מטות זהב וכסף על רצפת בהט ושש ודר וסחרת׃ ");
INSERT INTO heb_vpl VALUES ("ET1_7","018_1_7","EST","1","7","7","והשקות בכלי זהב וכלים מכלים שונים ויין מלכות רב כיד המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET1_8","018_1_8","EST","1","8","8","והשתיה כדת אין אנס כי כן יסד המלך על כל רב ביתו לעשות כרצון איש ואיש׃ ");
INSERT INTO heb_vpl VALUES ("ET1_9","018_1_9","EST","1","9","9","גם ושתי המלכה עשתה משתה נשים בית המלכות אשר למלך אחשורוש׃ ");
INSERT INTO heb_vpl VALUES ("ET1_10","018_1_10","EST","1","10","10","ביום השביעי כטוב לב המלך ביין אמר למהומן בזתא חרבונא בגתא ואבגתא זתר וכרכס שבעת הסריסים המשרתים את פני המלך אחשורוש׃ ");
INSERT INTO heb_vpl VALUES ("ET1_11","018_1_11","EST","1","11","11","להביא את ושתי המלכה לפני המלך בכתר מלכות להראות העמים והשרים את יפיה כי טובת מראה היא׃ ");
INSERT INTO heb_vpl VALUES ("ET1_12","018_1_12","EST","1","12","12","ותמאן המלכה ושתי לבוא בדבר המלך אשר ביד הסריסים ויקצף המלך מאד וחמתו בערה בו׃ ");
INSERT INTO heb_vpl VALUES ("ET1_13","018_1_13","EST","1","13","13","ויאמר המלך לחכמים ידעי העתים כי כן דבר המלך לפני כל ידעי דת ודין׃ ");
INSERT INTO heb_vpl VALUES ("ET1_14","018_1_14","EST","1","14","14","והקרב אליו כרשנא שתר אדמתא תרשיש מרס מרסנא ממוכן שבעת שרי פרס ומדי ראי פני המלך הישבים ראשנה במלכות׃ ");
INSERT INTO heb_vpl VALUES ("ET1_15","018_1_15","EST","1","15","15","כדת מה לעשות במלכה ושתי על אשר לא עשתה את מאמר המלך אחשורוש ביד הסריסים׃ ");
INSERT INTO heb_vpl VALUES ("ET1_16","018_1_16","EST","1","16","16","ויאמר מומכן לפני המלך והשרים לא על המלך לבדו עותה ושתי המלכה כי על כל השרים ועל כל העמים אשר בכל מדינות המלך אחשורוש׃ ");
INSERT INTO heb_vpl VALUES ("ET1_17","018_1_17","EST","1","17","17","כי יצא דבר המלכה על כל הנשים להבזות בעליהן בעיניהן באמרם המלך אחשורוש אמר להביא את ושתי המלכה לפניו ולא באה׃ ");
INSERT INTO heb_vpl VALUES ("ET1_18","018_1_18","EST","1","18","18","והיום הזה תאמרנה שרות פרס ומדי אשר שמעו את דבר המלכה לכל שרי המלך וכדי בזיון וקצף׃ ");
INSERT INTO heb_vpl VALUES ("ET1_19","018_1_19","EST","1","19","19","אם על המלך טוב יצא דבר מלכות מלפניו ויכתב בדתי פרס ומדי ולא יעבור אשר לא תבוא ושתי לפני המלך אחשורוש ומלכותה יתן המלך לרעותה הטובה ממנה׃ ");
INSERT INTO heb_vpl VALUES ("ET1_20","018_1_20","EST","1","20","20","ונשמע פתגם המלך אשר יעשה בכל מלכותו כי רבה היא וכל הנשים יתנו יקר לבעליהן למגדול ועד קטן׃ ");
INSERT INTO heb_vpl VALUES ("ET1_21","018_1_21","EST","1","21","21","וייטב הדבר בעיני המלך והשרים ויעש המלך כדבר ממוכן׃ ");
INSERT INTO heb_vpl VALUES ("ET1_22","018_1_22","EST","1","22","22","וישלח ספרים אל כל מדינות המלך אל מדינה ומדינה ככתבה ואל עם ועם כלשונו להיות כל איש שרר בביתו ומדבר כלשון עמו׃ ");
INSERT INTO heb_vpl VALUES ("ET2_1","018_2_1","EST","2","1","1","אחר הדברים האלה כשך חמת המלך אחשורוש זכר את ושתי ואת אשר עשתה ואת אשר נגזר עליה׃ ");
INSERT INTO heb_vpl VALUES ("ET2_2","018_2_2","EST","2","2","2","ויאמרו נערי המלך משרתיו יבקשו למלך נערות בתולות טובות מראה׃ ");
INSERT INTO heb_vpl VALUES ("ET2_3","018_2_3","EST","2","3","3","ויפקד המלך פקידים בכל מדינות מלכותו ויקבצו את כל נערה בתולה טובת מראה אל שושן הבירה אל בית הנשים אל יד הגא סריס המלך שמר הנשים ונתון תמרוקיהן׃ ");
INSERT INTO heb_vpl VALUES ("ET2_4","018_2_4","EST","2","4","4","והנערה אשר תיטב בעיני המלך תמלך תחת ושתי וייטב הדבר בעיני המלך ויעש כן׃ ");
INSERT INTO heb_vpl VALUES ("ET2_5","018_2_5","EST","2","5","5","איש יהודי היה בשושן הבירה ושמו מרדכי בן יאיר בן שמעי בן קיש איש ימיני׃ ");
INSERT INTO heb_vpl VALUES ("ET2_6","018_2_6","EST","2","6","6","אשר הגלה מירושלים עם הגלה אשר הגלתה עם יכניה מלך יהודה אשר הגלה נבוכדנאצר מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("ET2_7","018_2_7","EST","2","7","7","ויהי אמן את הדסה היא אסתר בת דדו כי אין לה אב ואם והנערה יפת תאר וטובת מראה ובמות אביה ואמה לקחה מרדכי לו לבת׃ ");
INSERT INTO heb_vpl VALUES ("ET2_8","018_2_8","EST","2","8","8","ויהי בהשמע דבר המלך ודתו ובהקבץ נערות רבות אל שושן הבירה אל יד הגי ותלקח אסתר אל בית המלך אל יד הגי שמר הנשים׃ ");
INSERT INTO heb_vpl VALUES ("ET2_9","018_2_9","EST","2","9","9","ותיטב הנערה בעיניו ותשא חסד לפניו ויבהל את תמרוקיה ואת מנותה לתת לה ואת שבע הנערות הראיות לתת לה מבית המלך וישנה ואת נערותיה לטוב בית הנשים׃ ");
INSERT INTO heb_vpl VALUES ("ET2_10","018_2_10","EST","2","10","10","לא הגידה אסתר את עמה ואת מולדתה כי מרדכי צוה עליה אשר לא תגיד׃ ");
INSERT INTO heb_vpl VALUES ("ET2_11","018_2_11","EST","2","11","11","ובכל יום ויום מרדכי מתהלך לפני חצר בית הנשים לדעת את שלום אסתר ומה יעשה בה׃ ");
INSERT INTO heb_vpl VALUES ("ET2_12","018_2_12","EST","2","12","12","ובהגיע תר נערה ונערה לבוא אל המלך אחשורוש מקץ היות לה כדת הנשים שנים עשר חדש כי כן ימלאו ימי מרוקיהן ששה חדשים בשמן המר וששה חדשים בבשמים ובתמרוקי הנשים׃ ");
INSERT INTO heb_vpl VALUES ("ET2_13","018_2_13","EST","2","13","13","ובזה הנערה באה אל המלך את כל אשר תאמר ינתן לה לבוא עמה מבית הנשים עד בית המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET2_14","018_2_14","EST","2","14","14","בערב היא באה ובבקר היא שבה אל בית הנשים שני אל יד שעשגז סריס המלך שמר הפילגשים לא תבוא עוד אל המלך כי אם חפץ בה המלך ונקראה בשם׃ ");
INSERT INTO heb_vpl VALUES ("ET2_15","018_2_15","EST","2","15","15","ובהגיע תר אסתר בת אביחיל דד מרדכי אשר לקח לו לבת לבוא אל המלך לא בקשה דבר כי אם את אשר יאמר הגי סריס המלך שמר הנשים ותהי אסתר נשאת חן בעיני כל ראיה׃ ");
INSERT INTO heb_vpl VALUES ("ET2_16","018_2_16","EST","2","16","16","ותלקח אסתר אל המלך אחשורוש אל בית מלכותו בחדש העשירי הוא חדש טבת בשנת שבע למלכותו׃ ");
INSERT INTO heb_vpl VALUES ("ET2_17","018_2_17","EST","2","17","17","ויאהב המלך את אסתר מכל הנשים ותשא חן וחסד לפניו מכל הבתולת וישם כתר מלכות בראשה וימליכה תחת ושתי׃ ");
INSERT INTO heb_vpl VALUES ("ET2_18","018_2_18","EST","2","18","18","ויעש המלך משתה גדול לכל שריו ועבדיו את משתה אסתר והנחה למדינות עשה ויתן משאת כיד המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET2_19","018_2_19","EST","2","19","19","ובהקבץ בתולות שנית ומרדכי ישב בשער המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET2_20","018_2_20","EST","2","20","20","אין אסתר מגדת מולדתה ואת עמה כאשר צוה עליה מרדכי ואת מאמר מרדכי אסתר עשה כאשר היתה באמנה אתו׃ ");
INSERT INTO heb_vpl VALUES ("ET2_21","018_2_21","EST","2","21","21","בימים ההם ומרדכי ישב בשער המלך קצף בגתן ותרש שני סריסי המלך משמרי הסף ויבקשו לשלח יד במלך אחשורש׃ ");
INSERT INTO heb_vpl VALUES ("ET2_22","018_2_22","EST","2","22","22","ויודע הדבר למרדכי ויגד לאסתר המלכה ותאמר אסתר למלך בשם מרדכי׃ ");
INSERT INTO heb_vpl VALUES ("ET2_23","018_2_23","EST","2","23","23","ויבקש הדבר וימצא ויתלו שניהם על עץ ויכתב בספר דברי הימים לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET3_1","018_3_1","EST","3","1","1","אחר הדברים האלה גדל המלך אחשורוש את המן בן המדתא האגגי וינשאהו וישם את כסאו מעל כל השרים אשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("ET3_2","018_3_2","EST","3","2","2","וכל עבדי המלך אשר בשער המלך כרעים ומשתחוים להמן כי כן צוה לו המלך ומרדכי לא יכרע ולא ישתחוה׃ ");
INSERT INTO heb_vpl VALUES ("ET3_3","018_3_3","EST","3","3","3","ויאמרו עבדי המלך אשר בשער המלך למרדכי מדוע אתה עובר את מצות המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET3_4","018_3_4","EST","3","4","4","ויהי באמרם אליו יום ויום ולא שמע אליהם ויגידו להמן לראות היעמדו דברי מרדכי כי הגיד להם אשר הוא יהודי׃ ");
INSERT INTO heb_vpl VALUES ("ET3_5","018_3_5","EST","3","5","5","וירא המן כי אין מרדכי כרע ומשתחוה לו וימלא המן חמה׃ ");
INSERT INTO heb_vpl VALUES ("ET3_6","018_3_6","EST","3","6","6","ויבז בעיניו לשלח יד במרדכי לבדו כי הגידו לו את עם מרדכי ויבקש המן להשמיד את כל היהודים אשר בכל מלכות אחשורוש עם מרדכי׃ ");
INSERT INTO heb_vpl VALUES ("ET3_7","018_3_7","EST","3","7","7","בחדש הראשון הוא חדש ניסן בשנת שתים עשרה למלך אחשורוש הפיל פור הוא הגורל לפני המן מיום ליום ומחדש לחדש שנים עשר הוא חדש אדר׃ ");
INSERT INTO heb_vpl VALUES ("ET3_8","018_3_8","EST","3","8","8","ויאמר המן למלך אחשורוש ישנו עם אחד מפזר ומפרד בין העמים בכל מדינות מלכותך ודתיהם שנות מכל עם ואת דתי המלך אינם עשים ולמלך אין שוה להניחם׃ ");
INSERT INTO heb_vpl VALUES ("ET3_9","018_3_9","EST","3","9","9","אם על המלך טוב יכתב לאבדם ועשרת אלפים ככר כסף אשקול על ידי עשי המלאכה להביא אל גנזי המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET3_10","018_3_10","EST","3","10","10","ויסר המלך את טבעתו מעל ידו ויתנה להמן בן המדתא האגגי צרר היהודים׃ ");
INSERT INTO heb_vpl VALUES ("ET3_11","018_3_11","EST","3","11","11","ויאמר המלך להמן הכסף נתון לך והעם לעשות בו כטוב בעיניך׃ ");
INSERT INTO heb_vpl VALUES ("ET3_12","018_3_12","EST","3","12","12","ויקראו ספרי המלך בחדש הראשון בשלושה עשר יום בו ויכתב ככל אשר צוה המן אל אחשדרפני המלך ואל הפחות אשר על מדינה ומדינה ואל שרי עם ועם מדינה ומדינה ככתבה ועם ועם כלשונו בשם המלך אחשורש נכתב ונחתם בטבעת המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET3_13","018_3_13","EST","3","13","13","ונשלוח ספרים ביד הרצים אל כל מדינות המלך להשמיד להרג ולאבד את כל היהודים מנער ועד זקן טף ונשים ביום אחד בשלושה עשר לחדש שנים עשר הוא חדש אדר ושללם לבוז׃ ");
INSERT INTO heb_vpl VALUES ("ET3_14","018_3_14","EST","3","14","14","פתשגן הכתב להנתן דת בכל מדינה ומדינה גלוי לכל העמים להיות עתדים ליום הזה׃ ");
INSERT INTO heb_vpl VALUES ("ET3_15","018_3_15","EST","3","15","15","הרצים יצאו דחופים בדבר המלך והדת נתנה בשושן הבירה והמלך והמן ישבו לשתות והעיר שושן נבוכה׃ ");
INSERT INTO heb_vpl VALUES ("ET4_1","018_4_1","EST","4","1","1","ומרדכי ידע את כל אשר נעשה ויקרע מרדכי את בגדיו וילבש שק ואפר ויצא בתוך העיר ויזעק זעקה גדלה ומרה׃ ");
INSERT INTO heb_vpl VALUES ("ET4_2","018_4_2","EST","4","2","2","ויבוא עד לפני שער המלך כי אין לבוא אל שער המלך בלבוש שק׃ ");
INSERT INTO heb_vpl VALUES ("ET4_3","018_4_3","EST","4","3","3","ובכל מדינה ומדינה מקום אשר דבר המלך ודתו מגיע אבל גדול ליהודים וצום ובכי ומספד שק ואפר יצע לרבים׃ ");
INSERT INTO heb_vpl VALUES ("ET4_4","018_4_4","EST","4","4","4","ותבואינה נערות אסתר וסריסיה ויגידו לה ותתחלחל המלכה מאד ותשלח בגדים להלביש את מרדכי ולהסיר שקו מעליו ולא קבל׃ ");
INSERT INTO heb_vpl VALUES ("ET4_5","018_4_5","EST","4","5","5","ותקרא אסתר להתך מסריסי המלך אשר העמיד לפניה ותצוהו על מרדכי לדעת מה זה ועל מה זה׃ ");
INSERT INTO heb_vpl VALUES ("ET4_6","018_4_6","EST","4","6","6","ויצא התך אל מרדכי אל רחוב העיר אשר לפני שער המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET4_7","018_4_7","EST","4","7","7","ויגד לו מרדכי את כל אשר קרהו ואת פרשת הכסף אשר אמר המן לשקול על גנזי המלך ביהודיים לאבדם׃ ");
INSERT INTO heb_vpl VALUES ("ET4_8","018_4_8","EST","4","8","8","ואת פתשגן כתב הדת אשר נתן בשושן להשמידם נתן לו להראות את אסתר ולהגיד לה ולצוות עליה לבוא אל המלך להתחנן לו ולבקש מלפניו על עמה׃ ");
INSERT INTO heb_vpl VALUES ("ET4_9","018_4_9","EST","4","9","9","ויבוא התך ויגד לאסתר את דברי מרדכי׃ ");
INSERT INTO heb_vpl VALUES ("ET4_10","018_4_10","EST","4","10","10","ותאמר אסתר להתך ותצוהו אל מרדכי׃ ");
INSERT INTO heb_vpl VALUES ("ET4_11","018_4_11","EST","4","11","11","כל עבדי המלך ועם מדינות המלך יודעים אשר כל איש ואשה אשר יבוא אל המלך אל החצר הפנימית אשר לא יקרא אחת דתו להמית לבד מאשר יושיט לו המלך את שרביט הזהב וחיה ואני לא נקראתי לבוא אל המלך זה שלושים יום׃ ");
INSERT INTO heb_vpl VALUES ("ET4_12","018_4_12","EST","4","12","12","ויגידו למרדכי את דברי אסתר׃ ");
INSERT INTO heb_vpl VALUES ("ET4_13","018_4_13","EST","4","13","13","ויאמר מרדכי להשיב אל אסתר אל תדמי בנפשך להמלט בית המלך מכל היהודים׃ ");
INSERT INTO heb_vpl VALUES ("ET4_14","018_4_14","EST","4","14","14","כי אם החרש תחרישי בעת הזאת רוח והצלה יעמוד ליהודים ממקום אחר ואת ובית אביך תאבדו ומי יודע אם לעת כזאת הגעת למלכות׃ ");
INSERT INTO heb_vpl VALUES ("ET4_15","018_4_15","EST","4","15","15","ותאמר אסתר להשיב אל מרדכי׃ ");
INSERT INTO heb_vpl VALUES ("ET4_16","018_4_16","EST","4","16","16","לך כנוס את כל היהודים הנמצאים בשושן וצומו עלי ואל תאכלו ואל תשתו שלשת ימים לילה ויום גם אני ונערתי אצום כן ובכן אבוא אל המלך אשר לא כדת וכאשר אבדתי אבדתי׃ ");
INSERT INTO heb_vpl VALUES ("ET4_17","018_4_17","EST","4","17","17","ויעבר מרדכי ויעש ככל אשר צותה עליו אסתר׃ ");
INSERT INTO heb_vpl VALUES ("ET5_1","018_5_1","EST","5","1","1","ויהי ביום השלישי ותלבש אסתר מלכות ותעמד בחצר בית המלך הפנימית נכח בית המלך והמלך יושב על כסא מלכותו בבית המלכות נכח פתח הבית׃ ");
INSERT INTO heb_vpl VALUES ("ET5_2","018_5_2","EST","5","2","2","ויהי כראות המלך את אסתר המלכה עמדת בחצר נשאה חן בעיניו ויושט המלך לאסתר את שרביט הזהב אשר בידו ותקרב אסתר ותגע בראש השרביט׃ ");
INSERT INTO heb_vpl VALUES ("ET5_3","018_5_3","EST","5","3","3","ויאמר לה המלך מה לך אסתר המלכה ומה בקשתך עד חצי המלכות וינתן לך׃ ");
INSERT INTO heb_vpl VALUES ("ET5_4","018_5_4","EST","5","4","4","ותאמר אסתר אם על המלך טוב יבוא המלך והמן היום אל המשתה אשר עשיתי לו׃ ");
INSERT INTO heb_vpl VALUES ("ET5_5","018_5_5","EST","5","5","5","ויאמר המלך מהרו את המן לעשות את דבר אסתר ויבא המלך והמן אל המשתה אשר עשתה אסתר׃ ");
INSERT INTO heb_vpl VALUES ("ET5_6","018_5_6","EST","5","6","6","ויאמר המלך לאסתר במשתה היין מה שאלתך וינתן לך ומה בקשתך עד חצי המלכות ותעש׃ ");
INSERT INTO heb_vpl VALUES ("ET5_7","018_5_7","EST","5","7","7","ותען אסתר ותאמר שאלתי ובקשתי׃ ");
INSERT INTO heb_vpl VALUES ("ET5_8","018_5_8","EST","5","8","8","אם מצאתי חן בעיני המלך ואם על המלך טוב לתת את שאלתי ולעשות את בקשתי יבוא המלך והמן אל המשתה אשר אעשה להם ומחר אעשה כדבר המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET5_9","018_5_9","EST","5","9","9","ויצא המן ביום ההוא שמח וטוב לב וכראות המן את מרדכי בשער המלך ולא קם ולא זע ממנו וימלא המן על מרדכי חמה׃ ");
INSERT INTO heb_vpl VALUES ("ET5_10","018_5_10","EST","5","10","10","ויתאפק המן ויבוא אל ביתו וישלח ויבא את אהביו ואת זרש אשתו׃ ");
INSERT INTO heb_vpl VALUES ("ET5_11","018_5_11","EST","5","11","11","ויספר להם המן את כבוד עשרו ורב בניו ואת כל אשר גדלו המלך ואת אשר נשאו על השרים ועבדי המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET5_12","018_5_12","EST","5","12","12","ויאמר המן אף לא הביאה אסתר המלכה עם המלך אל המשתה אשר עשתה כי אם אותי וגם למחר אני קרוא לה עם המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET5_13","018_5_13","EST","5","13","13","וכל זה איננו שוה לי בכל עת אשר אני ראה את מרדכי היהודי יושב בשער המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET5_14","018_5_14","EST","5","14","14","ותאמר לו זרש אשתו וכל אהביו יעשו עץ גבה חמשים אמה ובבקר אמר למלך ויתלו את מרדכי עליו ובא עם המלך אל המשתה שמח וייטב הדבר לפני המן ויעש העץ׃ ");
INSERT INTO heb_vpl VALUES ("ET6_1","018_6_1","EST","6","1","1","בלילה ההוא נדדה שנת המלך ויאמר להביא את ספר הזכרנות דברי הימים ויהיו נקראים לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET6_2","018_6_2","EST","6","2","2","וימצא כתוב אשר הגיד מרדכי על בגתנא ותרש שני סריסי המלך משמרי הסף אשר בקשו לשלח יד במלך אחשורוש׃ ");
INSERT INTO heb_vpl VALUES ("ET6_3","018_6_3","EST","6","3","3","ויאמר המלך מה נעשה יקר וגדולה למרדכי על זה ויאמרו נערי המלך משרתיו לא נעשה עמו דבר׃ ");
INSERT INTO heb_vpl VALUES ("ET6_4","018_6_4","EST","6","4","4","ויאמר המלך מי בחצר והמן בא לחצר בית המלך החיצונה לאמר למלך לתלות את מרדכי על העץ אשר הכין לו׃ ");
INSERT INTO heb_vpl VALUES ("ET6_5","018_6_5","EST","6","5","5","ויאמרו נערי המלך אליו הנה המן עמד בחצר ויאמר המלך יבוא׃ ");
INSERT INTO heb_vpl VALUES ("ET6_6","018_6_6","EST","6","6","6","ויבוא המן ויאמר לו המלך מה לעשות באיש אשר המלך חפץ ביקרו ויאמר המן בלבו למי יחפץ המלך לעשות יקר יותר ממני׃ ");
INSERT INTO heb_vpl VALUES ("ET6_7","018_6_7","EST","6","7","7","ויאמר המן אל המלך איש אשר המלך חפץ ביקרו׃ ");
INSERT INTO heb_vpl VALUES ("ET6_8","018_6_8","EST","6","8","8","יביאו לבוש מלכות אשר לבש בו המלך וסוס אשר רכב עליו המלך ואשר נתן כתר מלכות בראשו׃ ");
INSERT INTO heb_vpl VALUES ("ET6_9","018_6_9","EST","6","9","9","ונתון הלבוש והסוס על יד איש משרי המלך הפרתמים והלבישו את האיש אשר המלך חפץ ביקרו והרכיבהו על הסוס ברחוב העיר וקראו לפניו ככה יעשה לאיש אשר המלך חפץ ביקרו׃ ");
INSERT INTO heb_vpl VALUES ("ET6_10","018_6_10","EST","6","10","10","ויאמר המלך להמן מהר קח את הלבוש ואת הסוס כאשר דברת ועשה כן למרדכי היהודי היושב בשער המלך אל תפל דבר מכל אשר דברת׃ ");
INSERT INTO heb_vpl VALUES ("ET6_11","018_6_11","EST","6","11","11","ויקח המן את הלבוש ואת הסוס וילבש את מרדכי וירכיבהו ברחוב העיר ויקרא לפניו ככה יעשה לאיש אשר המלך חפץ ביקרו׃ ");
INSERT INTO heb_vpl VALUES ("ET6_12","018_6_12","EST","6","12","12","וישב מרדכי אל שער המלך והמן נדחף אל ביתו אבל וחפוי ראש׃ ");
INSERT INTO heb_vpl VALUES ("ET6_13","018_6_13","EST","6","13","13","ויספר המן לזרש אשתו ולכל אהביו את כל אשר קרהו ויאמרו לו חכמיו וזרש אשתו אם מזרע היהודים מרדכי אשר החלות לנפל לפניו לא תוכל לו כי נפול תפול לפניו׃ ");
INSERT INTO heb_vpl VALUES ("ET6_14","018_6_14","EST","6","14","14","עודם מדברים עמו וסריסי המלך הגיעו ויבהלו להביא את המן אל המשתה אשר עשתה אסתר׃ ");
INSERT INTO heb_vpl VALUES ("ET7_1","018_7_1","EST","7","1","1","ויבא המלך והמן לשתות עם אסתר המלכה׃ ");
INSERT INTO heb_vpl VALUES ("ET7_2","018_7_2","EST","7","2","2","ויאמר המלך לאסתר גם ביום השני במשתה היין מה שאלתך אסתר המלכה ותנתן לך ומה בקשתך עד חצי המלכות ותעש׃ ");
INSERT INTO heb_vpl VALUES ("ET7_3","018_7_3","EST","7","3","3","ותען אסתר המלכה ותאמר אם מצאתי חן בעיניך המלך ואם על המלך טוב תנתן לי נפשי בשאלתי ועמי בבקשתי׃ ");
INSERT INTO heb_vpl VALUES ("ET7_4","018_7_4","EST","7","4","4","כי נמכרנו אני ועמי להשמיד להרוג ולאבד ואלו לעבדים ולשפחות נמכרנו החרשתי כי אין הצר שוה בנזק המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET7_5","018_7_5","EST","7","5","5","ויאמר המלך אחשורוש ויאמר לאסתר המלכה מי הוא זה ואי זה הוא אשר מלאו לבו לעשות כן׃ ");
INSERT INTO heb_vpl VALUES ("ET7_6","018_7_6","EST","7","6","6","ותאמר אסתר איש צר ואויב המן הרע הזה והמן נבעת מלפני המלך והמלכה׃ ");
INSERT INTO heb_vpl VALUES ("ET7_7","018_7_7","EST","7","7","7","והמלך קם בחמתו ממשתה היין אל גנת הביתן והמן עמד לבקש על נפשו מאסתר המלכה כי ראה כי כלתה אליו הרעה מאת המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET7_8","018_7_8","EST","7","8","8","והמלך שב מגנת הביתן אל בית משתה היין והמן נפל על המטה אשר אסתר עליה ויאמר המלך הגם לכבוש את המלכה עמי בבית הדבר יצא מפי המלך ופני המן חפו׃ ");
INSERT INTO heb_vpl VALUES ("ET7_9","018_7_9","EST","7","9","9","ויאמר חרבונה אחד מן הסריסים לפני המלך גם הנה העץ אשר עשה המן למרדכי אשר דבר טוב על המלך עמד בבית המן גבה חמשים אמה ויאמר המלך תלהו עליו׃ ");
INSERT INTO heb_vpl VALUES ("ET7_10","018_7_10","EST","7","10","10","ויתלו את המן על העץ אשר הכין למרדכי וחמת המלך שככה׃ ");
INSERT INTO heb_vpl VALUES ("ET8_1","018_8_1","EST","8","1","1","ביום ההוא נתן המלך אחשורוש לאסתר המלכה את בית המן צרר היהודיים ומרדכי בא לפני המלך כי הגידה אסתר מה הוא לה׃ ");
INSERT INTO heb_vpl VALUES ("ET8_2","018_8_2","EST","8","2","2","ויסר המלך את טבעתו אשר העביר מהמן ויתנה למרדכי ותשם אסתר את מרדכי על בית המן׃ ");
INSERT INTO heb_vpl VALUES ("ET8_3","018_8_3","EST","8","3","3","ותוסף אסתר ותדבר לפני המלך ותפל לפני רגליו ותבך ותתחנן לו להעביר את רעת המן האגגי ואת מחשבתו אשר חשב על היהודים׃ ");
INSERT INTO heb_vpl VALUES ("ET8_4","018_8_4","EST","8","4","4","ויושט המלך לאסתר את שרבט הזהב ותקם אסתר ותעמד לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET8_5","018_8_5","EST","8","5","5","ותאמר אם על המלך טוב ואם מצאתי חן לפניו וכשר הדבר לפני המלך וטובה אני בעיניו יכתב להשיב את הספרים מחשבת המן בן המדתא האגגי אשר כתב לאבד את היהודים אשר בכל מדינות המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET8_6","018_8_6","EST","8","6","6","כי איככה אוכל וראיתי ברעה אשר ימצא את עמי ואיככה אוכל וראיתי באבדן מולדתי׃ ");
INSERT INTO heb_vpl VALUES ("ET8_7","018_8_7","EST","8","7","7","ויאמר המלך אחשורש לאסתר המלכה ולמרדכי היהודי הנה בית המן נתתי לאסתר ואתו תלו על העץ על אשר שלח ידו ביהודיים׃ ");
INSERT INTO heb_vpl VALUES ("ET8_8","018_8_8","EST","8","8","8","ואתם כתבו על היהודים כטוב בעיניכם בשם המלך וחתמו בטבעת המלך כי כתב אשר נכתב בשם המלך ונחתום בטבעת המלך אין להשיב׃ ");
INSERT INTO heb_vpl VALUES ("ET8_9","018_8_9","EST","8","9","9","ויקראו ספרי המלך בעת ההיא בחדש השלישי הוא חדש סיון בשלושה ועשרים בו ויכתב ככל אשר צוה מרדכי אל היהודים ואל האחשדרפנים והפחות ושרי המדינות אשר מהדו ועד כוש שבע ועשרים ומאה מדינה מדינה ומדינה ככתבה ועם ועם כלשנו ואל היהודים ככתבם וכלשונם׃ ");
INSERT INTO heb_vpl VALUES ("ET8_10","018_8_10","EST","8","10","10","ויכתב בשם המלך אחשורש ויחתם בטבעת המלך וישלח ספרים ביד הרצים בסוסים רכבי הרכש האחשתרנים בני הרמכים׃ ");
INSERT INTO heb_vpl VALUES ("ET8_11","018_8_11","EST","8","11","11","אשר נתן המלך ליהודים אשר בכל עיר ועיר להקהל ולעמד על נפשם להשמיד ולהרג ולאבד את כל חיל עם ומדינה הצרים אתם טף ונשים ושללם לבוז׃ ");
INSERT INTO heb_vpl VALUES ("ET8_12","018_8_12","EST","8","12","12","ביום אחד בכל מדינות המלך אחשורוש בשלושה עשר לחדש שנים עשר הוא חדש אדר׃ ");
INSERT INTO heb_vpl VALUES ("ET8_13","018_8_13","EST","8","13","13","פתשגן הכתב להנתן דת בכל מדינה ומדינה גלוי לכל העמים ולהיות היהודיים עתודים ליום הזה להנקם מאיביהם׃ ");
INSERT INTO heb_vpl VALUES ("ET8_14","018_8_14","EST","8","14","14","הרצים רכבי הרכש האחשתרנים יצאו מבהלים ודחופים בדבר המלך והדת נתנה בשושן הבירה׃ ");
INSERT INTO heb_vpl VALUES ("ET8_15","018_8_15","EST","8","15","15","ומרדכי יצא מלפני המלך בלבוש מלכות תכלת וחור ועטרת זהב גדולה ותכריך בוץ וארגמן והעיר שושן צהלה ושמחה׃ ");
INSERT INTO heb_vpl VALUES ("ET8_16","018_8_16","EST","8","16","16","ליהודים היתה אורה ושמחה וששן ויקר׃ ");
INSERT INTO heb_vpl VALUES ("ET8_17","018_8_17","EST","8","17","17","ובכל מדינה ומדינה ובכל עיר ועיר מקום אשר דבר המלך ודתו מגיע שמחה וששון ליהודים משתה ויום טוב ורבים מעמי הארץ מתיהדים כי נפל פחד היהודים עליהם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_1","018_9_1","EST","9","1","1","ובשנים עשר חדש הוא חדש אדר בשלושה עשר יום בו אשר הגיע דבר המלך ודתו להעשות ביום אשר שברו איבי היהודים לשלוט בהם ונהפוך הוא אשר ישלטו היהודים המה בשנאיהם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_2","018_9_2","EST","9","2","2","נקהלו היהודים בעריהם בכל מדינות המלך אחשורוש לשלח יד במבקשי רעתם ואיש לא עמד לפניהם כי נפל פחדם על כל העמים׃ ");
INSERT INTO heb_vpl VALUES ("ET9_3","018_9_3","EST","9","3","3","וכל שרי המדינות והאחשדרפנים והפחות ועשי המלאכה אשר למלך מנשאים את היהודים כי נפל פחד מרדכי עליהם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_4","018_9_4","EST","9","4","4","כי גדול מרדכי בבית המלך ושמעו הולך בכל המדינות כי האיש מרדכי הולך וגדול׃ ");
INSERT INTO heb_vpl VALUES ("ET9_5","018_9_5","EST","9","5","5","ויכו היהודים בכל איביהם מכת חרב והרג ואבדן ויעשו בשנאיהם כרצונם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_6","018_9_6","EST","9","6","6","ובשושן הבירה הרגו היהודים ואבד חמש מאות איש׃ ");
INSERT INTO heb_vpl VALUES ("ET9_7","018_9_7","EST","9","7","7","ואת פרשנדתא ואת דלפון ואת אספתא׃ ");
INSERT INTO heb_vpl VALUES ("ET9_8","018_9_8","EST","9","8","8","ואת פורתא ואת אדליא ואת ארידתא׃ ");
INSERT INTO heb_vpl VALUES ("ET9_9","018_9_9","EST","9","9","9","ואת פרמשתא ואת אריסי ואת ארדי ואת ויזתא׃ ");
INSERT INTO heb_vpl VALUES ("ET9_10","018_9_10","EST","9","10","10","עשרת בני המן בן המדתא צרר היהודים הרגו ובבזה לא שלחו את ידם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_11","018_9_11","EST","9","11","11","ביום ההוא בא מספר ההרוגים בשושן הבירה לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("ET9_12","018_9_12","EST","9","12","12","ויאמר המלך לאסתר המלכה בשושן הבירה הרגו היהודים ואבד חמש מאות איש ואת עשרת בני המן בשאר מדינות המלך מה עשו ומה שאלתך וינתן לך ומה בקשתך עוד ותעש׃ ");
INSERT INTO heb_vpl VALUES ("ET9_13","018_9_13","EST","9","13","13","ותאמר אסתר אם על המלך טוב ינתן גם מחר ליהודים אשר בשושן לעשות כדת היום ואת עשרת בני המן יתלו על העץ׃ ");
INSERT INTO heb_vpl VALUES ("ET9_14","018_9_14","EST","9","14","14","ויאמר המלך להעשות כן ותנתן דת בשושן ואת עשרת בני המן תלו׃ ");
INSERT INTO heb_vpl VALUES ("ET9_15","018_9_15","EST","9","15","15","ויקהלו היהודיים אשר בשושן גם ביום ארבעה עשר לחדש אדר ויהרגו בשושן שלש מאות איש ובבזה לא שלחו את ידם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_16","018_9_16","EST","9","16","16","ושאר היהודים אשר במדינות המלך נקהלו ועמד על נפשם ונוח מאיביהם והרג בשנאיהם חמשה ושבעים אלף ובבזה לא שלחו את ידם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_17","018_9_17","EST","9","17","17","ביום שלשה עשר לחדש אדר ונוח בארבעה עשר בו ועשה אתו יום משתה ושמחה׃ ");
INSERT INTO heb_vpl VALUES ("ET9_18","018_9_18","EST","9","18","18","והיהודיים אשר בשושן נקהלו בשלשה עשר בו ובארבעה עשר בו ונוח בחמשה עשר בו ועשה אתו יום משתה ושמחה׃ ");
INSERT INTO heb_vpl VALUES ("ET9_19","018_9_19","EST","9","19","19","על כן היהודים הפרוזים הישבים בערי הפרזות עשים את יום ארבעה עשר לחדש אדר שמחה ומשתה ויום טוב ומשלוח מנות איש לרעהו׃ ");
INSERT INTO heb_vpl VALUES ("ET9_20","018_9_20","EST","9","20","20","ויכתב מרדכי את הדברים האלה וישלח ספרים אל כל היהודים אשר בכל מדינות המלך אחשורוש הקרובים והרחוקים׃ ");
INSERT INTO heb_vpl VALUES ("ET9_21","018_9_21","EST","9","21","21","לקים עליהם להיות עשים את יום ארבעה עשר לחדש אדר ואת יום חמשה עשר בו בכל שנה ושנה׃ ");
INSERT INTO heb_vpl VALUES ("ET9_22","018_9_22","EST","9","22","22","כימים אשר נחו בהם היהודים מאויביהם והחדש אשר נהפך להם מיגון לשמחה ומאבל ליום טוב לעשות אותם ימי משתה ושמחה ומשלוח מנות איש לרעהו ומתנות לאביונים׃ ");
INSERT INTO heb_vpl VALUES ("ET9_23","018_9_23","EST","9","23","23","וקבל היהודים את אשר החלו לעשות ואת אשר כתב מרדכי אליהם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_24","018_9_24","EST","9","24","24","כי המן בן המדתא האגגי צרר כל היהודים חשב על היהודים לאבדם והפיל פור הוא הגורל להמם ולאבדם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_25","018_9_25","EST","9","25","25","ובבאה לפני המלך אמר עם הספר ישוב מחשבתו הרעה אשר חשב על היהודים על ראשו ותלו אתו ואת בניו על העץ׃ ");
INSERT INTO heb_vpl VALUES ("ET9_26","018_9_26","EST","9","26","26","על כן קראו לימים האלה פורים על שם הפור על כן על כל דברי האגרת הזאת ומה ראו על ככה ומה הגיע אליהם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_27","018_9_27","EST","9","27","27","קימו וקבל היהודים עליהם ועל זרעם ועל כל הנלוים עליהם ולא יעבור להיות עשים את שני הימים האלה ככתבם וכזמנם בכל שנה ושנה׃ ");
INSERT INTO heb_vpl VALUES ("ET9_28","018_9_28","EST","9","28","28","והימים האלה נזכרים ונעשים בכל דור ודור משפחה ומשפחה מדינה ומדינה ועיר ועיר וימי הפורים האלה לא יעברו מתוך היהודים וזכרם לא יסוף מזרעם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_29","018_9_29","EST","9","29","29","ותכתב אסתר המלכה בת אביחיל ומרדכי היהודי את כל תקף לקים את אגרת הפורים הזאת השנית׃ ");
INSERT INTO heb_vpl VALUES ("ET9_30","018_9_30","EST","9","30","30","וישלח ספרים אל כל היהודים אל שבע ועשרים ומאה מדינה מלכות אחשורוש דברי שלום ואמת׃ ");
INSERT INTO heb_vpl VALUES ("ET9_31","018_9_31","EST","9","31","31","לקים את ימי הפרים האלה בזמניהם כאשר קים עליהם מרדכי היהודי ואסתר המלכה וכאשר קימו על נפשם ועל זרעם דברי הצמות וזעקתם׃ ");
INSERT INTO heb_vpl VALUES ("ET9_32","018_9_32","EST","9","32","32","ומאמר אסתר קים דברי הפרים האלה ונכתב בספר׃ ");
INSERT INTO heb_vpl VALUES ("ET10_1","018_10_1","EST","10","1","1","וישם המלך אחשרש מס על הארץ ואיי הים׃ ");
INSERT INTO heb_vpl VALUES ("ET10_2","018_10_2","EST","10","2","2","וכל מעשה תקפו וגבורתו ופרשת גדלת מרדכי אשר גדלו המלך הלוא הם כתובים על ספר דברי הימים למלכי מדי ופרס׃ ");
INSERT INTO heb_vpl VALUES ("ET10_3","018_10_3","EST","10","3","3","כי מרדכי היהודי משנה למלך אחשורוש וגדול ליהודים ורצוי לרב אחיו דרש טוב לעמו ודבר שלום לכל זרעו׃ ");
INSERT INTO heb_vpl VALUES ("JB1_1","019_1_1","JOB","1","1","1","איש היה בארץ עוץ איוב שמו והיה האיש ההוא תם וישר וירא אלהים וסר מרע׃ ");
INSERT INTO heb_vpl VALUES ("JB1_2","019_1_2","JOB","1","2","2","ויולדו לו שבעה בנים ושלוש בנות׃ ");
INSERT INTO heb_vpl VALUES ("JB1_3","019_1_3","JOB","1","3","3","ויהי מקנהו שבעת אלפי צאן ושלשת אלפי גמלים וחמש מאות צמד בקר וחמש מאות אתונות ועבדה רבה מאד ויהי האיש ההוא גדול מכל בני קדם׃ ");
INSERT INTO heb_vpl VALUES ("JB1_4","019_1_4","JOB","1","4","4","והלכו בניו ועשו משתה בית איש יומו ושלחו וקראו לשלשת אחיתיהם לאכל ולשתות עמהם׃ ");
INSERT INTO heb_vpl VALUES ("JB1_5","019_1_5","JOB","1","5","5","ויהי כי הקיפו ימי המשתה וישלח איוב ויקדשם והשכים בבקר והעלה עלות מספר כלם כי אמר איוב אולי חטאו בני וברכו אלהים בלבבם ככה יעשה איוב כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("JB1_6","019_1_6","JOB","1","6","6","ויהי היום ויבאו בני האלהים להתיצב על יהוה ויבוא גם השטן בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("JB1_7","019_1_7","JOB","1","7","7","ויאמר יהוה אל השטן מאין תבא ויען השטן את יהוה ויאמר משוט בארץ ומהתהלך בה׃ ");
INSERT INTO heb_vpl VALUES ("JB1_8","019_1_8","JOB","1","8","8","ויאמר יהוה אל השטן השמת לבך על עבדי איוב כי אין כמהו בארץ איש תם וישר ירא אלהים וסר מרע׃ ");
INSERT INTO heb_vpl VALUES ("JB1_9","019_1_9","JOB","1","9","9","ויען השטן את יהוה ויאמר החנם ירא איוב אלהים׃ ");
INSERT INTO heb_vpl VALUES ("JB1_10","019_1_10","JOB","1","10","10","הלא את שכת בעדו ובעד ביתו ובעד כל אשר לו מסביב מעשה ידיו ברכת ומקנהו פרץ בארץ׃ ");
INSERT INTO heb_vpl VALUES ("JB1_11","019_1_11","JOB","1","11","11","ואולם שלח נא ידך וגע בכל אשר לו אם לא על פניך יברכך׃ ");
INSERT INTO heb_vpl VALUES ("JB1_12","019_1_12","JOB","1","12","12","ויאמר יהוה אל השטן הנה כל אשר לו בידך רק אליו אל תשלח ידך ויצא השטן מעם פני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JB1_13","019_1_13","JOB","1","13","13","ויהי היום ובניו ובנתיו אכלים ושתים יין בבית אחיהם הבכור׃ ");
INSERT INTO heb_vpl VALUES ("JB1_14","019_1_14","JOB","1","14","14","ומלאך בא אל איוב ויאמר הבקר היו חרשות והאתנות רעות על ידיהם׃ ");
INSERT INTO heb_vpl VALUES ("JB1_15","019_1_15","JOB","1","15","15","ותפל שבא ותקחם ואת הנערים הכו לפי חרב ואמלטה רק אני לבדי להגיד לך׃ ");
INSERT INTO heb_vpl VALUES ("JB1_16","019_1_16","JOB","1","16","16","עוד זה מדבר וזה בא ויאמר אש אלהים נפלה מן השמים ותבער בצאן ובנערים ותאכלם ואמלטה רק אני לבדי להגיד לך׃ ");
INSERT INTO heb_vpl VALUES ("JB1_17","019_1_17","JOB","1","17","17","עוד זה מדבר וזה בא ויאמר כשדים שמו שלשה ראשים ויפשטו על הגמלים ויקחום ואת הנערים הכו לפי חרב ואמלטה רק אני לבדי להגיד לך׃ ");
INSERT INTO heb_vpl VALUES ("JB1_18","019_1_18","JOB","1","18","18","עד זה מדבר וזה בא ויאמר בניך ובנותיך אכלים ושתים יין בבית אחיהם הבכור׃ ");
INSERT INTO heb_vpl VALUES ("JB1_19","019_1_19","JOB","1","19","19","והנה רוח גדולה באה מעבר המדבר ויגע בארבע פנות הבית ויפל על הנערים וימותו ואמלטה רק אני לבדי להגיד לך׃ ");
INSERT INTO heb_vpl VALUES ("JB1_20","019_1_20","JOB","1","20","20","ויקם איוב ויקרע את מעלו ויגז את ראשו ויפל ארצה וישתחו׃ ");
INSERT INTO heb_vpl VALUES ("JB1_21","019_1_21","JOB","1","21","21","ויאמר ערם יצתי מבטן אמי וערם אשוב שמה יהוה נתן ויהוה לקח יהי שם יהוה מברך׃ ");
INSERT INTO heb_vpl VALUES ("JB1_22","019_1_22","JOB","1","22","22","בכל זאת לא חטא איוב ולא נתן תפלה לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JB2_1","019_2_1","JOB","2","1","1","ויהי היום ויבאו בני האלהים להתיצב על יהוה ויבוא גם השטן בתכם להתיצב על יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JB2_2","019_2_2","JOB","2","2","2","ויאמר יהוה אל השטן אי מזה תבא ויען השטן את יהוה ויאמר משט בארץ ומהתהלך בה׃ ");
INSERT INTO heb_vpl VALUES ("JB2_3","019_2_3","JOB","2","3","3","ויאמר יהוה אל השטן השמת לבך אל עבדי איוב כי אין כמהו בארץ איש תם וישר ירא אלהים וסר מרע ועדנו מחזיק בתמתו ותסיתני בו לבלעו חנם׃ ");
INSERT INTO heb_vpl VALUES ("JB2_4","019_2_4","JOB","2","4","4","ויען השטן את יהוה ויאמר עור בעד עור וכל אשר לאיש יתן בעד נפשו׃ ");
INSERT INTO heb_vpl VALUES ("JB2_5","019_2_5","JOB","2","5","5","אולם שלח נא ידך וגע אל עצמו ואל בשרו אם לא אל פניך יברכך׃ ");
INSERT INTO heb_vpl VALUES ("JB2_6","019_2_6","JOB","2","6","6","ויאמר יהוה אל השטן הנו בידך אך את נפשו שמר׃ ");
INSERT INTO heb_vpl VALUES ("JB2_7","019_2_7","JOB","2","7","7","ויצא השטן מאת פני יהוה ויך את איוב בשחין רע מכף רגלו עד קדקדו׃ ");
INSERT INTO heb_vpl VALUES ("JB2_8","019_2_8","JOB","2","8","8","ויקח לו חרש להתגרד בו והוא ישב בתוך האפר׃ ");
INSERT INTO heb_vpl VALUES ("JB2_9","019_2_9","JOB","2","9","9","ותאמר לו אשתו עדך מחזיק בתמתך ברך אלהים ומת׃ ");
INSERT INTO heb_vpl VALUES ("JB2_10","019_2_10","JOB","2","10","10","ויאמר אליה כדבר אחת הנבלות תדברי גם את הטוב נקבל מאת האלהים ואת הרע לא נקבל בכל זאת לא חטא איוב בשפתיו׃ ");
INSERT INTO heb_vpl VALUES ("JB2_11","019_2_11","JOB","2","11","11","וישמעו שלשת רעי איוב את כל הרעה הזאת הבאה עליו ויבאו איש ממקמו אליפז התימני ובלדד השוחי וצופר הנעמתי ויועדו יחדו לבוא לנוד לו ולנחמו׃ ");
INSERT INTO heb_vpl VALUES ("JB2_12","019_2_12","JOB","2","12","12","וישאו את עיניהם מרחוק ולא הכירהו וישאו קולם ויבכו ויקרעו איש מעלו ויזרקו עפר על ראשיהם השמימה׃ ");
INSERT INTO heb_vpl VALUES ("JB2_13","019_2_13","JOB","2","13","13","וישבו אתו לארץ שבעת ימים ושבעת לילות ואין דבר אליו דבר כי ראו כי גדל הכאב מאד׃ ");
INSERT INTO heb_vpl VALUES ("JB3_1","019_3_1","JOB","3","1","1","אחרי כן פתח איוב את פיהו ויקלל את יומו׃ ");
INSERT INTO heb_vpl VALUES ("JB3_2","019_3_2","JOB","3","2","2","ויען איוב ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("JB3_3","019_3_3","JOB","3","3","3","יאבד יום אולד בו והלילה אמר הרה גבר׃ ");
INSERT INTO heb_vpl VALUES ("JB3_4","019_3_4","JOB","3","4","4","היום ההוא יהי חשך אל ידרשהו אלוה ממעל ואל תופע עליו נהרה׃ ");
INSERT INTO heb_vpl VALUES ("JB3_5","019_3_5","JOB","3","5","5","יגאלהו חשך וצלמות תשכן עליו עננה יבעתהו כמרירי יום׃ ");
INSERT INTO heb_vpl VALUES ("JB3_6","019_3_6","JOB","3","6","6","הלילה ההוא יקחהו אפל אל יחד בימי שנה במספר ירחים אל יבא׃ ");
INSERT INTO heb_vpl VALUES ("JB3_7","019_3_7","JOB","3","7","7","הנה הלילה ההוא יהי גלמוד אל תבא רננה בו׃ ");
INSERT INTO heb_vpl VALUES ("JB3_8","019_3_8","JOB","3","8","8","יקבהו אררי יום העתידים ערר לויתן׃ ");
INSERT INTO heb_vpl VALUES ("JB3_9","019_3_9","JOB","3","9","9","יחשכו כוכבי נשפו יקו לאור ואין ואל יראה בעפעפי שחר׃ ");
INSERT INTO heb_vpl VALUES ("JB3_10","019_3_10","JOB","3","10","10","כי לא סגר דלתי בטני ויסתר עמל מעיני׃ ");
INSERT INTO heb_vpl VALUES ("JB3_11","019_3_11","JOB","3","11","11","למה לא מרחם אמות מבטן יצאתי ואגוע׃ ");
INSERT INTO heb_vpl VALUES ("JB3_12","019_3_12","JOB","3","12","12","מדוע קדמוני ברכים ומה שדים כי אינק׃ ");
INSERT INTO heb_vpl VALUES ("JB3_13","019_3_13","JOB","3","13","13","כי עתה שכבתי ואשקוט ישנתי אז ינוח לי׃ ");
INSERT INTO heb_vpl VALUES ("JB3_14","019_3_14","JOB","3","14","14","עם מלכים ויעצי ארץ הבנים חרבות למו׃ ");
INSERT INTO heb_vpl VALUES ("JB3_15","019_3_15","JOB","3","15","15","או עם שרים זהב להם הממלאים בתיהם כסף׃ ");
INSERT INTO heb_vpl VALUES ("JB3_16","019_3_16","JOB","3","16","16","או כנפל טמון לא אהיה כעללים לא ראו אור׃ ");
INSERT INTO heb_vpl VALUES ("JB3_17","019_3_17","JOB","3","17","17","שם רשעים חדלו רגז ושם ינוחו יגיעי כח׃ ");
INSERT INTO heb_vpl VALUES ("JB3_18","019_3_18","JOB","3","18","18","יחד אסירים שאננו לא שמעו קול נגש׃ ");
INSERT INTO heb_vpl VALUES ("JB3_19","019_3_19","JOB","3","19","19","קטן וגדול שם הוא ועבד חפשי מאדניו׃ ");
INSERT INTO heb_vpl VALUES ("JB3_20","019_3_20","JOB","3","20","20","למה יתן לעמל אור וחיים למרי נפש׃ ");
INSERT INTO heb_vpl VALUES ("JB3_21","019_3_21","JOB","3","21","21","המחכים למות ואיננו ויחפרהו ממטמונים׃ ");
INSERT INTO heb_vpl VALUES ("JB3_22","019_3_22","JOB","3","22","22","השמחים אלי גיל ישישו כי ימצאו קבר׃ ");
INSERT INTO heb_vpl VALUES ("JB3_23","019_3_23","JOB","3","23","23","לגבר אשר דרכו נסתרה ויסך אלוה בעדו׃ ");
INSERT INTO heb_vpl VALUES ("JB3_24","019_3_24","JOB","3","24","24","כי לפני לחמי אנחתי תבא ויתכו כמים שאגתי׃ ");
INSERT INTO heb_vpl VALUES ("JB3_25","019_3_25","JOB","3","25","25","כי פחד פחדתי ויאתיני ואשר יגרתי יבא לי׃ ");
INSERT INTO heb_vpl VALUES ("JB3_26","019_3_26","JOB","3","26","26","לא שלותי ולא שקטתי ולא נחתי ויבא רגז׃ ");
INSERT INTO heb_vpl VALUES ("JB4_1","019_4_1","JOB","4","1","1","ויען אליפז התימני ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("JB4_2","019_4_2","JOB","4","2","2","הנסה דבר אליך תלאה ועצר במלין מי יוכל׃ ");
INSERT INTO heb_vpl VALUES ("JB4_3","019_4_3","JOB","4","3","3","הנה יסרת רבים וידים רפות תחזק׃ ");
INSERT INTO heb_vpl VALUES ("JB4_4","019_4_4","JOB","4","4","4","כושל יקימון מליך וברכים כרעות תאמץ׃ ");
INSERT INTO heb_vpl VALUES ("JB4_5","019_4_5","JOB","4","5","5","כי עתה תבוא אליך ותלא תגע עדיך ותבהל׃ ");
INSERT INTO heb_vpl VALUES ("JB4_6","019_4_6","JOB","4","6","6","הלא יראתך כסלתך תקותך ותם דרכיך׃ ");
INSERT INTO heb_vpl VALUES ("JB4_7","019_4_7","JOB","4","7","7","זכר נא מי הוא נקי אבד ואיפה ישרים נכחדו׃ ");
INSERT INTO heb_vpl VALUES ("JB4_8","019_4_8","JOB","4","8","8","כאשר ראיתי חרשי און וזרעי עמל יקצרהו׃ ");
INSERT INTO heb_vpl VALUES ("JB4_9","019_4_9","JOB","4","9","9","מנשמת אלוה יאבדו ומרוח אפו יכלו׃ ");
INSERT INTO heb_vpl VALUES ("JB4_10","019_4_10","JOB","4","10","10","שאגת אריה וקול שחל ושני כפירים נתעו׃ ");
