INSERT INTO heb_vpl VALUES ("JB4_12","019_4_12","JOB","4","12","12","ואלי דבר יגנב ותקח אזני שמץ מנהו׃ ");
INSERT INTO heb_vpl VALUES ("JB4_13","019_4_13","JOB","4","13","13","בשעפים מחזינות לילה בנפל תרדמה על אנשים׃ ");
INSERT INTO heb_vpl VALUES ("JB4_14","019_4_14","JOB","4","14","14","פחד קראני ורעדה ורב עצמותי הפחיד׃ ");
INSERT INTO heb_vpl VALUES ("JB4_15","019_4_15","JOB","4","15","15","ורוח על פני יחלף תסמר שערת בשרי׃ ");
INSERT INTO heb_vpl VALUES ("JB4_16","019_4_16","JOB","4","16","16","יעמד ולא אכיר מראהו תמונה לנגד עיני דממה וקול אשמע׃ ");
INSERT INTO heb_vpl VALUES ("JB4_17","019_4_17","JOB","4","17","17","האנוש מאלוה יצדק אם מעשהו יטהר גבר׃ ");
INSERT INTO heb_vpl VALUES ("JB4_18","019_4_18","JOB","4","18","18","הן בעבדיו לא יאמין ובמלאכיו ישים תהלה׃ ");
