INSERT INTO heb_vpl VALUES ("JB42_2","019_42_2","JOB","42","2","2","ידעת כי כל תוכל ולא יבצר ממך מזמה׃ ");
INSERT INTO heb_vpl VALUES ("JB42_3","019_42_3","JOB","42","3","3","מי זה מעלים עצה בלי דעת לכן הגדתי ולא אבין נפלאות ממני ולא אדע׃ ");
INSERT INTO heb_vpl VALUES ("JB42_4","019_42_4","JOB","42","4","4","שמע נא ואנכי אדבר אשאלך והודיעני׃ ");
INSERT INTO heb_vpl VALUES ("JB42_5","019_42_5","JOB","42","5","5","לשמע אזן שמעתיך ועתה עיני ראתך׃ ");
INSERT INTO heb_vpl VALUES ("JB42_6","019_42_6","JOB","42","6","6","על כן אמאס ונחמתי על עפר ואפר׃ ");
INSERT INTO heb_vpl VALUES ("JB42_7","019_42_7","JOB","42","7","7","ויהי אחר דבר יהוה את הדברים האלה אל איוב ויאמר יהוה אל אליפז התימני חרה אפי בך ובשני רעיך כי לא דברתם אלי נכונה כעבדי איוב׃ ");
INSERT INTO heb_vpl VALUES ("JB42_8","019_42_8","JOB","42","8","8","ועתה קחו לכם שבעה פרים ושבעה אילים ולכו אל עבדי איוב והעליתם עולה בעדכם ואיוב עבדי יתפלל עליכם כי אם פניו אשא לבלתי עשות עמכם נבלה כי לא דברתם אלי נכונה כעבדי איוב׃ ");
INSERT INTO heb_vpl VALUES ("JB42_9","019_42_9","JOB","42","9","9","וילכו אליפז התימני ובלדד השוחי צפר הנעמתי ויעשו כאשר דבר אליהם יהוה וישא יהוה את פני איוב׃ ");
INSERT INTO heb_vpl VALUES ("JB42_10","019_42_10","JOB","42","10","10","ויהוה שב את שבית איוב בהתפללו בעד רעהו ויסף יהוה את כל אשר לאיוב למשנה׃ ");
INSERT INTO heb_vpl VALUES ("JB42_11","019_42_11","JOB","42","11","11","ויבאו אליו כל אחיו וכל אחיתיו וכל ידעיו לפנים ויאכלו עמו לחם בביתו וינדו לו וינחמו אתו על כל הרעה אשר הביא יהוה עליו ויתנו לו איש קשיטה אחת ואיש נזם זהב אחד׃ ");
INSERT INTO heb_vpl VALUES ("JB42_12","019_42_12","JOB","42","12","12","ויהוה ברך את אחרית איוב מראשתו ויהי לו ארבעה עשר אלף צאן וששת אלפים גמלים ואלף צמד בקר ואלף אתונות׃ ");
INSERT INTO heb_vpl VALUES ("JB42_13","019_42_13","JOB","42","13","13","ויהי לו שבענה בנים ושלוש בנות׃ ");
INSERT INTO heb_vpl VALUES ("JB42_14","019_42_14","JOB","42","14","14","ויקרא שם האחת ימימה ושם השנית קציעה ושם השלישית קרן הפוך׃ ");
INSERT INTO heb_vpl VALUES ("JB42_15","019_42_15","JOB","42","15","15","ולא נמצא נשים יפות כבנות איוב בכל הארץ ויתן להם אביהם נחלה בתוך אחיהם׃ ");
INSERT INTO heb_vpl VALUES ("JB42_16","019_42_16","JOB","42","16","16","ויחי איוב אחרי זאת מאה וארבעים שנה וירא את בניו ואת בני בניו ארבעה דרות׃ ");
INSERT INTO heb_vpl VALUES ("JB42_17","019_42_17","JOB","42","17","17","וימת איוב זקן ושבע ימים׃ ");
INSERT INTO heb_vpl VALUES ("PS1_1","020_1_1","PSA","1","1","1","אשרי האיש אשר לא הלך בעצת רשעים ובדרך חטאים לא עמד ובמושב לצים לא ישב׃ ");
INSERT INTO heb_vpl VALUES ("PS1_2","020_1_2","PSA","1","2","2","כי אם בתורת יהוה חפצו ובתורתו יהגה יומם ולילה׃ ");
