INSERT INTO heb_vpl VALUES ("PS18_19","020_18_19","PSA","18","19","19","ויוציאני למרחב יחלצני כי חפץ בי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_20","020_18_20","PSA","18","20","20","יגמלני יהוה כצדקי כבר ידי ישיב לי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_21","020_18_21","PSA","18","21","21","כי שמרתי דרכי יהוה ולא רשעתי מאלהי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_22","020_18_22","PSA","18","22","22","כי כל משפטיו לנגדי וחקתיו לא אסיר מני׃ ");
INSERT INTO heb_vpl VALUES ("PS18_23","020_18_23","PSA","18","23","23","ואהי תמים עמו ואשתמר מעוני׃ ");
INSERT INTO heb_vpl VALUES ("PS18_24","020_18_24","PSA","18","24","24","וישב יהוה לי כצדקי כבר ידי לנגד עיניו׃ ");
INSERT INTO heb_vpl VALUES ("PS18_25","020_18_25","PSA","18","25","25","עם חסיד תתחסד עם גבר תמים תתמם׃ ");
INSERT INTO heb_vpl VALUES ("PS18_26","020_18_26","PSA","18","26","26","עם נבר תתברר ועם עקש תתפתל׃ ");
INSERT INTO heb_vpl VALUES ("PS18_27","020_18_27","PSA","18","27","27","כי אתה עם עני תושיע ועינים רמות תשפיל׃ ");
INSERT INTO heb_vpl VALUES ("PS18_28","020_18_28","PSA","18","28","28","כי אתה תאיר נרי יהוה אלהי יגיה חשכי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_29","020_18_29","PSA","18","29","29","כי בך ארץ גדוד ובאלהי אדלג שור׃ ");
INSERT INTO heb_vpl VALUES ("PS18_30","020_18_30","PSA","18","30","30","האל תמים דרכו אמרת יהוה צרופה מגן הוא לכל החסים בו׃ ");
INSERT INTO heb_vpl VALUES ("PS18_31","020_18_31","PSA","18","31","31","כי מי אלוה מבלעדי יהוה ומי צור זולתי אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("PS18_32","020_18_32","PSA","18","32","32","האל המאזרני חיל ויתן תמים דרכי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_33","020_18_33","PSA","18","33","33","משוה רגלי כאילות ועל במתי יעמידני׃ ");
INSERT INTO heb_vpl VALUES ("PS18_34","020_18_34","PSA","18","34","34","מלמד ידי למלחמה ונחתה קשת נחושה זרועתי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_35","020_18_35","PSA","18","35","35","ותתן לי מגן ישעך וימינך תסעדני וענותך תרבני׃ ");
INSERT INTO heb_vpl VALUES ("PS18_36","020_18_36","PSA","18","36","36","תרחיב צעדי תחתי ולא מעדו קרסלי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_37","020_18_37","PSA","18","37","37","ארדוף אויבי ואשיגם ולא אשוב עד כלותם׃ ");
INSERT INTO heb_vpl VALUES ("PS18_38","020_18_38","PSA","18","38","38","אמחצם ולא יכלו קום יפלו תחת רגלי׃ ");
