INSERT INTO heb_vpl VALUES ("PS18_41","020_18_41","PSA","18","41","41","ישועו ואין מושיע על יהוה ולא ענם׃ ");
INSERT INTO heb_vpl VALUES ("PS18_42","020_18_42","PSA","18","42","42","ואשחקם כעפר על פני רוח כטיט חוצות אריקם׃ ");
INSERT INTO heb_vpl VALUES ("PS18_43","020_18_43","PSA","18","43","43","תפלטני מריבי עם תשימני לראש גוים עם לא ידעתי יעבדוני׃ ");
INSERT INTO heb_vpl VALUES ("PS18_44","020_18_44","PSA","18","44","44","לשמע אזן ישמעו לי בני נכר יכחשו לי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_45","020_18_45","PSA","18","45","45","בני נכר יבלו ויחרגו ממסגרותיהם׃ ");
INSERT INTO heb_vpl VALUES ("PS18_46","020_18_46","PSA","18","46","46","חי יהוה וברוך צורי וירום אלוהי ישעי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_47","020_18_47","PSA","18","47","47","האל הנותן נקמות לי וידבר עמים תחתי׃ ");
INSERT INTO heb_vpl VALUES ("PS18_48","020_18_48","PSA","18","48","48","מפלטי מאיבי אף מן קמי תרוממני מאיש חמס תצילני׃ ");
INSERT INTO heb_vpl VALUES ("PS18_49","020_18_49","PSA","18","49","49","על כן אודך בגוים יהוה ולשמך אזמרה׃ ");
INSERT INTO heb_vpl VALUES ("PS18_50","020_18_50","PSA","18","50","50","מגדל ישועות מלכו ועשה חסד למשיחו לדוד ולזרעו עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("PS19_1","020_19_1","PSA","19","1","1","למנצח מזמור לדוד השמים מספרים כבוד אל ומעשה ידיו מגיד הרקיע׃ ");
INSERT INTO heb_vpl VALUES ("PS19_2","020_19_2","PSA","19","2","2","יום ליום יביע אמר ולילה ללילה יחוה דעת׃ ");
INSERT INTO heb_vpl VALUES ("PS19_3","020_19_3","PSA","19","3","3","אין אמר ואין דברים בלי נשמע קולם׃ ");
INSERT INTO heb_vpl VALUES ("PS19_4","020_19_4","PSA","19","4","4","בכל הארץ יצא קום ובקצה תבל מליהם לשמש שם אהל בהם׃ ");
INSERT INTO heb_vpl VALUES ("PS19_5","020_19_5","PSA","19","5","5","והוא כחתן יצא מחפתו ישיש כגבור לרוץ ארח׃ ");
INSERT INTO heb_vpl VALUES ("PS19_6","020_19_6","PSA","19","6","6","מקצה השמים מוצאו ותקופתו על קצותם ואין נסתר מחמתו׃ ");
INSERT INTO heb_vpl VALUES ("PS19_7","020_19_7","PSA","19","7","7","תורת יהוה תמימה משיבת נפש עדות יהוה נאמנה מחכימת פתי׃ ");
INSERT INTO heb_vpl VALUES ("PS19_8","020_19_8","PSA","19","8","8","פקודי יהוה ישרים משמחי לב מצות יהוה ברה מאירת עינים׃ ");
INSERT INTO heb_vpl VALUES ("PS19_9","020_19_9","PSA","19","9","9","יראת יהוה טהורה עומדת לעד משפטי יהוה אמת צדקו יחדו׃ ");
INSERT INTO heb_vpl VALUES ("PS19_10","020_19_10","PSA","19","10","10","הנחמדים מזהב ומפז רב ומתוקים מדבש ונפת צופים׃ ");
INSERT INTO heb_vpl VALUES ("PS19_11","020_19_11","PSA","19","11","11","גם עבדך נזהר בהם בשמרם עקב רב׃ ");
INSERT INTO heb_vpl VALUES ("PS19_12","020_19_12","PSA","19","12","12","שגיאות מי יבין מנסתרות נקני׃ ");
INSERT INTO heb_vpl VALUES ("PS19_13","020_19_13","PSA","19","13","13","גם מזדים חשך עבדך אל ימשלו בי אז איתם ונקיתי מפשע רב׃ ");
INSERT INTO heb_vpl VALUES ("PS19_14","020_19_14","PSA","19","14","14","יהיו לרצון אמרי פי והגיון לבי לפניך יהוה צורי וגאלי׃ ");
INSERT INTO heb_vpl VALUES ("PS20_1","020_20_1","PSA","20","1","1","למנצח מזמור לדוד יענך יהוה ביום צרה ישגבך שם אלהי יעקב׃ ");
INSERT INTO heb_vpl VALUES ("PS20_2","020_20_2","PSA","20","2","2","ישלח עזרך מקדש ומציון יסעדך׃ ");
INSERT INTO heb_vpl VALUES ("PS20_3","020_20_3","PSA","20","3","3","יזכר כל מנחתך ועולתך ידשנה סלה׃ ");
INSERT INTO heb_vpl VALUES ("PS20_4","020_20_4","PSA","20","4","4","יתן לך כלבבך וכל עצתך ימלא׃ ");
INSERT INTO heb_vpl VALUES ("PS20_5","020_20_5","PSA","20","5","5","נרננה בישועתך ובשם אלהינו נדגל ימלא יהוה כל משאלותיך׃ ");
INSERT INTO heb_vpl VALUES ("PS20_6","020_20_6","PSA","20","6","6","עתה ידעתי כי הושיע יהוה משיחו יענהו משמי קדשו בגברות ישע ימינו׃ ");
INSERT INTO heb_vpl VALUES ("PS20_7","020_20_7","PSA","20","7","7","אלה ברכב ואלה בסוסים ואנחנו בשם יהוה אלהינו נזכיר׃ ");
INSERT INTO heb_vpl VALUES ("PS20_8","020_20_8","PSA","20","8","8","המה כרעו ונפלו ואנחנו קמנו ונתעודד׃ ");
INSERT INTO heb_vpl VALUES ("PS20_9","020_20_9","PSA","20","9","9","יהוה הושיעה המלך יעננו ביום קראנו׃ ");
INSERT INTO heb_vpl VALUES ("PS21_1","020_21_1","PSA","21","1","1","למנצח מזמור לדוד יהוה בעזך ישמח מלך ובישועתך מה יגיל מאד׃ ");
INSERT INTO heb_vpl VALUES ("PS21_2","020_21_2","PSA","21","2","2","תאות לבו נתתה לו וארשת שפתיו בל מנעת סלה׃ ");
INSERT INTO heb_vpl VALUES ("PS21_3","020_21_3","PSA","21","3","3","כי תקדמנו ברכות טוב תשית לראשו עטרת פז׃ ");
INSERT INTO heb_vpl VALUES ("PS21_4","020_21_4","PSA","21","4","4","חיים שאל ממך נתתה לו ארך ימים עולם ועד׃ ");
INSERT INTO heb_vpl VALUES ("PS21_5","020_21_5","PSA","21","5","5","גדול כבודו בישועתך הוד והדר תשוה עליו׃ ");
INSERT INTO heb_vpl VALUES ("PS21_6","020_21_6","PSA","21","6","6","כי תשיתהו ברכות לעד תחדהו בשמחה את פניך׃ ");
INSERT INTO heb_vpl VALUES ("PS21_7","020_21_7","PSA","21","7","7","כי המלך בטח ביהוה ובחסד עליון בל ימוט׃ ");
INSERT INTO heb_vpl VALUES ("PS21_8","020_21_8","PSA","21","8","8","תמצא ידך לכל איביך ימינך תמצא שנאיך׃ ");
INSERT INTO heb_vpl VALUES ("PS21_9","020_21_9","PSA","21","9","9","תשיתמו כתנור אש לעת פניך יהוה באפו יבלעם ותאכלם אש׃ ");
INSERT INTO heb_vpl VALUES ("PS21_10","020_21_10","PSA","21","10","10","פרימו מארץ תאבד וזרעם מבני אדם׃ ");
INSERT INTO heb_vpl VALUES ("PS21_11","020_21_11","PSA","21","11","11","כי נטו עליך רעה חשבו מזמה בל יוכלו׃ ");
INSERT INTO heb_vpl VALUES ("PS21_12","020_21_12","PSA","21","12","12","כי תשיתמו שכם במיתריך תכונן על פניהם׃ ");
INSERT INTO heb_vpl VALUES ("PS21_13","020_21_13","PSA","21","13","13","רומה יהוה בעזך נשירה ונזמרה גבורתך׃ ");
INSERT INTO heb_vpl VALUES ("PS22_1","020_22_1","PSA","22","1","1","למנצח על אילת השחר מזמור לדוד אלי אלי למה עזבתני רחוק מישועתי דברי שאגתי׃ ");
INSERT INTO heb_vpl VALUES ("PS22_2","020_22_2","PSA","22","2","2","אלהי אקרא יומם ולא תענה ולילה ולא דומיה לי׃ ");
INSERT INTO heb_vpl VALUES ("PS22_3","020_22_3","PSA","22","3","3","ואתה קדוש יושב תהלות ישראל׃ ");
INSERT INTO heb_vpl VALUES ("PS22_4","020_22_4","PSA","22","4","4","בך בטחו אבתינו בטחו ותפלטמו׃ ");
INSERT INTO heb_vpl VALUES ("PS22_5","020_22_5","PSA","22","5","5","אליך זעקו ונמלטו בך בטחו ולא בושו׃ ");
INSERT INTO heb_vpl VALUES ("PS22_6","020_22_6","PSA","22","6","6","ואנכי תולעת ולא איש חרפת אדם ובזוי עם׃ ");
INSERT INTO heb_vpl VALUES ("PS22_7","020_22_7","PSA","22","7","7","כל ראי ילעגו לי יפטירו בשפה יניעו ראש׃ ");
INSERT INTO heb_vpl VALUES ("PS22_8","020_22_8","PSA","22","8","8","גל אל יהוה יפלטהו יצילהו כי חפץ בו׃ ");
INSERT INTO heb_vpl VALUES ("PS22_9","020_22_9","PSA","22","9","9","כי אתה גחי מבטן מבטיחי על שדי אמי׃ ");
INSERT INTO heb_vpl VALUES ("PS22_10","020_22_10","PSA","22","10","10","עליך השלכתי מרחם מבטן אמי אלי אתה׃ ");
INSERT INTO heb_vpl VALUES ("PS22_11","020_22_11","PSA","22","11","11","אל תרחק ממני כי צרה קרובה כי אין עוזר׃ ");
INSERT INTO heb_vpl VALUES ("PS22_12","020_22_12","PSA","22","12","12","סבבוני פרים רבים אבירי בשן כתרוני׃ ");
INSERT INTO heb_vpl VALUES ("PS22_13","020_22_13","PSA","22","13","13","פצו עלי פיהם אריה טרף ושאג׃ ");
INSERT INTO heb_vpl VALUES ("PS22_14","020_22_14","PSA","22","14","14","כמים נשפכתי והתפרדו כל עצמותי היה לבי כדונג נמס בתוך מעי׃ ");
INSERT INTO heb_vpl VALUES ("PS22_15","020_22_15","PSA","22","15","15","יבש כחרש כחי ולשוני מדבק מלקוחי ולעפר מות תשפתני׃ ");
INSERT INTO heb_vpl VALUES ("PS22_16","020_22_16","PSA","22","16","16","כי סבבוני כלבים עדת מרעים הקיפוני כארי ידי ורגלי׃ ");
INSERT INTO heb_vpl VALUES ("PS22_17","020_22_17","PSA","22","17","17","אספר כל עצמותי המה יביטו יראו בי׃ ");
INSERT INTO heb_vpl VALUES ("PS22_18","020_22_18","PSA","22","18","18","יחלקו בגדי להם ועל לבושי יפילו גורל׃ ");
INSERT INTO heb_vpl VALUES ("PS22_19","020_22_19","PSA","22","19","19","ואתה יהוה אל תרחק אילותי לעזרתי חושה׃ ");
INSERT INTO heb_vpl VALUES ("PS22_20","020_22_20","PSA","22","20","20","הצילה מחרב נפשי מיד כלב יחידתי׃ ");
INSERT INTO heb_vpl VALUES ("PS22_21","020_22_21","PSA","22","21","21","הושיעני מפי אריה ומקרני רמים עניתני׃ ");
INSERT INTO heb_vpl VALUES ("PS22_22","020_22_22","PSA","22","22","22","אספרה שמך לאחי בתוך קהל אהללך׃ ");
INSERT INTO heb_vpl VALUES ("PS22_23","020_22_23","PSA","22","23","23","יראי יהוה הללוהו כל זרע יעקב כבדוהו וגורו ממנו כל זרע ישראל׃ ");
INSERT INTO heb_vpl VALUES ("PS22_24","020_22_24","PSA","22","24","24","כי לא בזה ולא שקץ ענות עני ולא הסתיר פניו ממנו ובשועו אליו שמע׃ ");
INSERT INTO heb_vpl VALUES ("PS22_25","020_22_25","PSA","22","25","25","מאתך תהלתי בקהל רב נדרי אשלם נגד יראיו׃ ");
INSERT INTO heb_vpl VALUES ("PS22_26","020_22_26","PSA","22","26","26","יאכלו ענוים וישבעו יהללו יהוה דרשיו יחי לבבכם לעד׃ ");
INSERT INTO heb_vpl VALUES ("PS22_27","020_22_27","PSA","22","27","27","יזכרו וישבו אל יהוה כל אפסי ארץ וישתחוו לפניך כל משפחות גוים׃ ");
INSERT INTO heb_vpl VALUES ("PS22_28","020_22_28","PSA","22","28","28","כי ליהוה המלוכה ומשל בגוים׃ ");
INSERT INTO heb_vpl VALUES ("PS22_29","020_22_29","PSA","22","29","29","אכלו וישתחוו כל דשני ארץ לפניו יכרעו כל יורדי עפר ונפשו לא חיה׃ ");
INSERT INTO heb_vpl VALUES ("PS22_30","020_22_30","PSA","22","30","30","זרע יעבדנו יספר לאדני לדור׃ ");
INSERT INTO heb_vpl VALUES ("PS22_31","020_22_31","PSA","22","31","31","יבאו ויגידו צדקתו לעם נולד כי עשה׃ ");
INSERT INTO heb_vpl VALUES ("PS23_1","020_23_1","PSA","23","1","1","מזמור לדוד יהוה רעי לא אחסר׃ ");
INSERT INTO heb_vpl VALUES ("PS23_2","020_23_2","PSA","23","2","2","בנאות דשא ירביצני על מי מנחות ינהלני׃ ");
INSERT INTO heb_vpl VALUES ("PS23_3","020_23_3","PSA","23","3","3","נפשי ישובב ינחני במעגלי צדק למען שמו׃ ");
INSERT INTO heb_vpl VALUES ("PS23_4","020_23_4","PSA","23","4","4","גם כי אלך בגיא צלמות לא אירא רע כי אתה עמדי שבטך ומשענתך המה ינחמני׃ ");
INSERT INTO heb_vpl VALUES ("PS23_5","020_23_5","PSA","23","5","5","תערך לפני שלחן נגד צררי דשנת בשמן ראשי כוסי רויה׃ ");
INSERT INTO heb_vpl VALUES ("PS23_6","020_23_6","PSA","23","6","6","אך טוב וחסד ירדפוני כל ימי חיי ושבתי בבית יהוה לארך ימים׃ ");
INSERT INTO heb_vpl VALUES ("PS24_1","020_24_1","PSA","24","1","1","לדוד מזמור ליהוה הארץ ומלואה תבל וישבי בה׃ ");
INSERT INTO heb_vpl VALUES ("PS24_2","020_24_2","PSA","24","2","2","כי הוא על ימים יסדה ועל נהרות יכוננה׃ ");
INSERT INTO heb_vpl VALUES ("PS24_3","020_24_3","PSA","24","3","3","מי יעלה בהר יהוה ומי יקום במקום קדשו׃ ");
INSERT INTO heb_vpl VALUES ("PS24_4","020_24_4","PSA","24","4","4","נקי כפים ובר לבב אשר לא נשא לשוא נפשי ולא נשבע למרמה׃ ");
INSERT INTO heb_vpl VALUES ("PS24_5","020_24_5","PSA","24","5","5","ישא ברכה מאת יהוה וצדקה מאלהי ישעו׃ ");
INSERT INTO heb_vpl VALUES ("PS24_6","020_24_6","PSA","24","6","6","זה דור דרשו מבקשי פניך יעקב סלה׃ ");
