INSERT INTO heb_vpl VALUES ("PS32_5","020_32_5","PSA","32","5","5","חטאתי אודיעך ועוני לא כסיתי אמרתי אודה עלי פשעי ליהוה ואתה נשאת עון חטאתי סלה׃ ");
INSERT INTO heb_vpl VALUES ("PS32_6","020_32_6","PSA","32","6","6","על זאת יתפלל כל חסיד אליך לעת מצא רק לשטף מים רבים אליו לא יגיעו׃ ");
INSERT INTO heb_vpl VALUES ("PS32_7","020_32_7","PSA","32","7","7","אתה סתר לי מצר תצרני רני פלט תסובבני סלה׃ ");
INSERT INTO heb_vpl VALUES ("PS32_8","020_32_8","PSA","32","8","8","אשכילך ואורך בדרך זו תלך איעצה עליך עיני׃ ");
INSERT INTO heb_vpl VALUES ("PS32_9","020_32_9","PSA","32","9","9","אל תהיו כסוס כפרד אין הבין במתג ורסן עדיו לבלום בל קרב אליך׃ ");
INSERT INTO heb_vpl VALUES ("PS32_10","020_32_10","PSA","32","10","10","רבים מכאובים לרשע והבוטח ביהוה חסד יסובבנו׃ ");
INSERT INTO heb_vpl VALUES ("PS32_11","020_32_11","PSA","32","11","11","שמחו ביהוה וגילו צדיקים והרנינו כל ישרי לב׃ ");
INSERT INTO heb_vpl VALUES ("PS33_1","020_33_1","PSA","33","1","1","רננו צדיקים ביהוה לישרים נאוה תהלה׃ ");
INSERT INTO heb_vpl VALUES ("PS33_2","020_33_2","PSA","33","2","2","הודו ליהוה בכנור בנבל עשור זמרו לו׃ ");
INSERT INTO heb_vpl VALUES ("PS33_3","020_33_3","PSA","33","3","3","שירו לו שיר חדש היטיבו נגן בתרועה׃ ");
INSERT INTO heb_vpl VALUES ("PS33_4","020_33_4","PSA","33","4","4","כי ישר דבר יהוה וכל מעשהו באמונה׃ ");
INSERT INTO heb_vpl VALUES ("PS33_5","020_33_5","PSA","33","5","5","אהב צדקה ומשפט חסד יהוה מלאה הארץ׃ ");
INSERT INTO heb_vpl VALUES ("PS33_6","020_33_6","PSA","33","6","6","בדבר יהוה שמים נעשו וברוח פיו כל צבאם׃ ");
INSERT INTO heb_vpl VALUES ("PS33_7","020_33_7","PSA","33","7","7","כנס כנד מי הים נתן באצרות תהומות׃ ");
INSERT INTO heb_vpl VALUES ("PS33_8","020_33_8","PSA","33","8","8","ייראו מיהוה כל הארץ ממנו יגורו כל ישבי תבל׃ ");
INSERT INTO heb_vpl VALUES ("PS33_9","020_33_9","PSA","33","9","9","כי הוא אמר ויהי הוא צוה ויעמד׃ ");
INSERT INTO heb_vpl VALUES ("PS33_10","020_33_10","PSA","33","10","10","יהוה הפיר עצת גוים הניא מחשבות עמים׃ ");
INSERT INTO heb_vpl VALUES ("PS33_11","020_33_11","PSA","33","11","11","עצת יהוה לעולם תעמד מחשבות לבו לדר ודר׃ ");
INSERT INTO heb_vpl VALUES ("PS33_12","020_33_12","PSA","33","12","12","אשרי הגוי אשר יהוה אלהיו העם בחר לנחלה לו׃ ");
INSERT INTO heb_vpl VALUES ("PS33_13","020_33_13","PSA","33","13","13","משמים הביט יהוה ראה את כל בני האדם׃ ");
INSERT INTO heb_vpl VALUES ("PS33_14","020_33_14","PSA","33","14","14","ממכון שבתו השגיח אל כל ישבי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("PS33_15","020_33_15","PSA","33","15","15","היצר יחד לבם המבין אל כל מעשיהם׃ ");
INSERT INTO heb_vpl VALUES ("PS33_16","020_33_16","PSA","33","16","16","אין המלך נושע ברב חיל גבור לא ינצל ברב כח׃ ");
INSERT INTO heb_vpl VALUES ("PS33_17","020_33_17","PSA","33","17","17","שקר הסוס לתשועה וברב חילו לא ימלט׃ ");
INSERT INTO heb_vpl VALUES ("PS33_18","020_33_18","PSA","33","18","18","הנה עין יהוה אל יראיו למיחלים לחסדו׃ ");
INSERT INTO heb_vpl VALUES ("PS33_19","020_33_19","PSA","33","19","19","להציל ממות נפשם ולחיותם ברעב׃ ");
INSERT INTO heb_vpl VALUES ("PS33_20","020_33_20","PSA","33","20","20","נפשנו חכתה ליהוה עזרנו ומגננו הוא׃ ");
INSERT INTO heb_vpl VALUES ("PS33_21","020_33_21","PSA","33","21","21","כי בו ישמח לבנו כי בשם קדשו בטחנו׃ ");
INSERT INTO heb_vpl VALUES ("PS33_22","020_33_22","PSA","33","22","22","יהי חסדך יהוה עלינו כאשר יחלנו לך׃ ");
INSERT INTO heb_vpl VALUES ("PS34_1","020_34_1","PSA","34","1","1","לדוד בשנותו את טעמו לפני אבימלך ויגרשהו וילך אברכה את יהוה בכל עת תמיד תהלתו בפי׃ ");
INSERT INTO heb_vpl VALUES ("PS34_2","020_34_2","PSA","34","2","2","ביהוה תתהלל נפשי ישמעו ענוים וישמחו׃ ");
INSERT INTO heb_vpl VALUES ("PS34_3","020_34_3","PSA","34","3","3","גדלו ליהוה אתי ונרוממה שמו יחדו׃ ");
INSERT INTO heb_vpl VALUES ("PS34_4","020_34_4","PSA","34","4","4","דרשתי את יהוה וענני ומכל מגורותי הצילני׃ ");
INSERT INTO heb_vpl VALUES ("PS34_5","020_34_5","PSA","34","5","5","הביטו אליו ונהרו ופניהם אל יחפרו׃ ");
INSERT INTO heb_vpl VALUES ("PS34_6","020_34_6","PSA","34","6","6","זה עני קרא ויהוה שמע ומכל צרותיו הושיעו׃ ");
INSERT INTO heb_vpl VALUES ("PS34_7","020_34_7","PSA","34","7","7","חנה מלאך יהוה סביב ליראיו ויחלצם׃ ");
INSERT INTO heb_vpl VALUES ("PS34_8","020_34_8","PSA","34","8","8","טעמו וראו כי טוב יהוה אשרי הגבר יחסה בו׃ ");
INSERT INTO heb_vpl VALUES ("PS34_9","020_34_9","PSA","34","9","9","יראו את יהוה קדשיו כי אין מחסור ליראיו׃ ");
INSERT INTO heb_vpl VALUES ("PS34_10","020_34_10","PSA","34","10","10","כפירים רשו ורעבו ודרשי יהוה לא יחסרו כל טוב׃ ");
INSERT INTO heb_vpl VALUES ("PS34_11","020_34_11","PSA","34","11","11","לכו בנים שמעו לי יראת יהוה אלמדכם׃ ");
INSERT INTO heb_vpl VALUES ("PS34_12","020_34_12","PSA","34","12","12","מי האיש החפץ חיים אהב ימים לראות טוב׃ ");
INSERT INTO heb_vpl VALUES ("PS34_13","020_34_13","PSA","34","13","13","נצר לשונך מרע ושפתיך מדבר מרמה׃ ");
INSERT INTO heb_vpl VALUES ("PS34_14","020_34_14","PSA","34","14","14","סור מרע ועשה טוב בקש שלום ורדפהו׃ ");
INSERT INTO heb_vpl VALUES ("PS34_15","020_34_15","PSA","34","15","15","עיני יהוה אל צדיקים ואזניו אל שועתם׃ ");
INSERT INTO heb_vpl VALUES ("PS34_16","020_34_16","PSA","34","16","16","פני יהוה בעשי רע להכרית מארץ זכרם׃ ");
INSERT INTO heb_vpl VALUES ("PS34_17","020_34_17","PSA","34","17","17","צעקו ויהוה שמע ומכל צרותם הצילם׃ ");
INSERT INTO heb_vpl VALUES ("PS34_18","020_34_18","PSA","34","18","18","קרוב יהוה לנשברי לב ואת דכאי רוח יושיע׃ ");
INSERT INTO heb_vpl VALUES ("PS34_19","020_34_19","PSA","34","19","19","רבות רעות צדיק ומכלם יצילנו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("PS34_20","020_34_20","PSA","34","20","20","שמר כל עצמותיו אחת מהנה לא נשברה׃ ");
INSERT INTO heb_vpl VALUES ("PS34_21","020_34_21","PSA","34","21","21","תמותת רשע רעה ושנאי צדיק יאשמו׃ ");
INSERT INTO heb_vpl VALUES ("PS34_22","020_34_22","PSA","34","22","22","פודה יהוה נפש עבדיו ולא יאשמו כל החסים בו׃ ");
INSERT INTO heb_vpl VALUES ("PS35_1","020_35_1","PSA","35","1","1","לדוד ריבה יהוה את יריבי לחם את לחמי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_2","020_35_2","PSA","35","2","2","החזק מגן וצנה וקומה בעזרתי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_3","020_35_3","PSA","35","3","3","והרק חנית וסגר לקראת רדפי אמר לנפשי ישעתך אני׃ ");
INSERT INTO heb_vpl VALUES ("PS35_4","020_35_4","PSA","35","4","4","יבשו ויכלמו מבקשי נפשי יסגו אחור ויחפרו חשבי רעתי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_5","020_35_5","PSA","35","5","5","יהיו כמץ לפני רוח ומלאך יהוה דוחה׃ ");
INSERT INTO heb_vpl VALUES ("PS35_6","020_35_6","PSA","35","6","6","יהי דרכם חשך וחלקלקות ומלאך יהוה רדפם׃ ");
INSERT INTO heb_vpl VALUES ("PS35_7","020_35_7","PSA","35","7","7","כי חנם טמנו לי שחת רשתם חנם חפרו לנפשי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_8","020_35_8","PSA","35","8","8","תבואהו שואה לא ידע ורשתו אשר טמן תלכדו בשואה יפל בה׃ ");
INSERT INTO heb_vpl VALUES ("PS35_9","020_35_9","PSA","35","9","9","ונפשי תגיל ביהוה תשיש בישועתו׃ ");
INSERT INTO heb_vpl VALUES ("PS35_10","020_35_10","PSA","35","10","10","כל עצמותי תאמרנה יהוה מי כמוך מציל עני מחזק ממנו ועני ואביון מגזלו׃ ");
INSERT INTO heb_vpl VALUES ("PS35_11","020_35_11","PSA","35","11","11","יקומון עדי חמס אשר לא ידעתי ישאלוני׃ ");
INSERT INTO heb_vpl VALUES ("PS35_12","020_35_12","PSA","35","12","12","ישלמוני רעה תחת טובה שכול לנפשי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_13","020_35_13","PSA","35","13","13","ואני בחלותם לבושי שק עניתי בצום נפשי ותפלתי על חיקי תשוב׃ ");
INSERT INTO heb_vpl VALUES ("PS35_14","020_35_14","PSA","35","14","14","כרע כאח לי התהלכתי כאבל אם קדר שחותי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_15","020_35_15","PSA","35","15","15","ובצלעי שמחו ונאספו נאספו עלי נכים ולא ידעתי קרעו ולא דמו׃ ");
INSERT INTO heb_vpl VALUES ("PS35_16","020_35_16","PSA","35","16","16","בחנפי לעגי מעוג חרק עלי שנימו׃ ");
