INSERT INTO heb_vpl VALUES ("PS35_19","020_35_19","PSA","35","19","19","אל ישמחו לי איבי שקר שנאי חנם יקרצו עין׃ ");
INSERT INTO heb_vpl VALUES ("PS35_20","020_35_20","PSA","35","20","20","כי לא שלום ידברו ועל רגעי ארץ דברי מרמות יחשבון׃ ");
INSERT INTO heb_vpl VALUES ("PS35_21","020_35_21","PSA","35","21","21","וירחיבו עלי פיהם אמרו האח האח ראתה עינינו׃ ");
INSERT INTO heb_vpl VALUES ("PS35_22","020_35_22","PSA","35","22","22","ראיתה יהוה אל תחרש אדני אל תרחק ממני׃ ");
INSERT INTO heb_vpl VALUES ("PS35_23","020_35_23","PSA","35","23","23","העירה והקיצה למשפטי אלהי ואדני לריבי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_24","020_35_24","PSA","35","24","24","שפטני כצדקך יהוה אלהי ואל ישמחו לי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_25","020_35_25","PSA","35","25","25","אל יאמרו בלבם האח נפשנו אל יאמרו בלענוהו׃ ");
INSERT INTO heb_vpl VALUES ("PS35_26","020_35_26","PSA","35","26","26","יבשו ויחפרו יחדו שמחי רעתי ילבשו בשת וכלמה המגדילים עלי׃ ");
INSERT INTO heb_vpl VALUES ("PS35_27","020_35_27","PSA","35","27","27","ירנו וישמחו חפצי צדקי ויאמרו תמיד יגדל יהוה החפץ שלום עבדו׃ ");
INSERT INTO heb_vpl VALUES ("PS35_28","020_35_28","PSA","35","28","28","ולשוני תהגה צדקך כל היום תהלתך׃ ");
INSERT INTO heb_vpl VALUES ("PS36_1","020_36_1","PSA","36","1","1","למנצח לעבד יהוה לדוד נאם פשע לרשע בקרב לבי אין פחד אלהים לנגד עיניו׃ ");
INSERT INTO heb_vpl VALUES ("PS36_2","020_36_2","PSA","36","2","2","כי החליק אליו בעיניו למצא עונו לשנא׃ ");
INSERT INTO heb_vpl VALUES ("PS36_3","020_36_3","PSA","36","3","3","דברי פיו און ומרמה חדל להשכיל להיטיב׃ ");
INSERT INTO heb_vpl VALUES ("PS36_4","020_36_4","PSA","36","4","4","און יחשב על משכבו יתיצב על דרך לא טוב רע לא ימאס׃ ");
INSERT INTO heb_vpl VALUES ("PS36_5","020_36_5","PSA","36","5","5","יהוה בהשמים חסדך אמונתך עד שחקים׃ ");
INSERT INTO heb_vpl VALUES ("PS36_6","020_36_6","PSA","36","6","6","צדקתך כהררי אל משפטך תהום רבה אדם ובהמה תושיע יהוה׃ ");
INSERT INTO heb_vpl VALUES ("PS36_7","020_36_7","PSA","36","7","7","מה יקר חסדך אלהים ובני אדם בצל כנפיך יחסיון׃ ");
INSERT INTO heb_vpl VALUES ("PS36_8","020_36_8","PSA","36","8","8","ירוין מדשן ביתך ונחל עדניך תשקם׃ ");
INSERT INTO heb_vpl VALUES ("PS36_9","020_36_9","PSA","36","9","9","כי עמך מקור חיים באורך נראה אור׃ ");
INSERT INTO heb_vpl VALUES ("PS36_10","020_36_10","PSA","36","10","10","משך חסדך לידעיך וצדקתך לישרי לב׃ ");
INSERT INTO heb_vpl VALUES ("PS36_11","020_36_11","PSA","36","11","11","אל תבואני רגל גאוה ויד רשעים אל תנדני׃ ");
INSERT INTO heb_vpl VALUES ("PS36_12","020_36_12","PSA","36","12","12","שם נפלו פעלי און דחו ולא יכלו קום׃ ");
INSERT INTO heb_vpl VALUES ("PS37_1","020_37_1","PSA","37","1","1","לדוד אל תתחר במרעים אל תקנא בעשי עולה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_2","020_37_2","PSA","37","2","2","כי כחציר מהרה ימלו וכירק דשא יבולון׃ ");
INSERT INTO heb_vpl VALUES ("PS37_3","020_37_3","PSA","37","3","3","בטח ביהוה ועשה טוב שכן ארץ ורעה אמונה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_4","020_37_4","PSA","37","4","4","והתענג על יהוה ויתן לך משאלת לבך׃ ");
INSERT INTO heb_vpl VALUES ("PS37_5","020_37_5","PSA","37","5","5","גול על יהוה דרכך ובטח עליו והוא יעשה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_6","020_37_6","PSA","37","6","6","והוציא כאור צדקך ומשפטך כצהרים׃ ");
INSERT INTO heb_vpl VALUES ("PS37_7","020_37_7","PSA","37","7","7","דום ליהוה והתחולל לו אל תתחר במצליח דרכו באיש עשה מזמות׃ ");
INSERT INTO heb_vpl VALUES ("PS37_8","020_37_8","PSA","37","8","8","הרף מאף ועזב חמה אל תתחר אך להרע׃ ");
INSERT INTO heb_vpl VALUES ("PS37_9","020_37_9","PSA","37","9","9","כי מרעים יכרתון וקוי יהוה המה יירשו ארץ׃ ");
INSERT INTO heb_vpl VALUES ("PS37_10","020_37_10","PSA","37","10","10","ועוד מעט ואין רשע והתבוננת על מקומו ואיננו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_11","020_37_11","PSA","37","11","11","וענוים יירשו ארץ והתענגו על רב שלום׃ ");
INSERT INTO heb_vpl VALUES ("PS37_12","020_37_12","PSA","37","12","12","זמם רשע לצדיק וחרק עליו שניו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_13","020_37_13","PSA","37","13","13","אדני ישחק לו כי ראה כי יבא יומו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_14","020_37_14","PSA","37","14","14","חרב פתחו רשעים ודרכו קשתם להפיל עני ואביון לטבוח ישרי דרך׃ ");
INSERT INTO heb_vpl VALUES ("PS37_15","020_37_15","PSA","37","15","15","חרבם תבוא בלבם וקשתותם תשברנה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_16","020_37_16","PSA","37","16","16","טוב מעט לצדיק מהמון רשעים רבים׃ ");
INSERT INTO heb_vpl VALUES ("PS37_17","020_37_17","PSA","37","17","17","כי זרועות רשעים תשברנה וסומך צדיקים יהוה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_18","020_37_18","PSA","37","18","18","יודע יהוה ימי תמימם ונחלתם לעולם תהיה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_19","020_37_19","PSA","37","19","19","לא יבשו בעת רעה ובימי רעבון ישבעו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_20","020_37_20","PSA","37","20","20","כי רשעים יאבדו ואיבי יהוה כיקר כרים כלו בעשן כלו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_21","020_37_21","PSA","37","21","21","לוה רשע ולא ישלם וצדיק חונן ונותן׃ ");
INSERT INTO heb_vpl VALUES ("PS37_22","020_37_22","PSA","37","22","22","כי מברכיו יירשו ארץ ומקלליו יכרתו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_23","020_37_23","PSA","37","23","23","מיהוה מצעדי גבר כוננו ודרכו יחפץ׃ ");
INSERT INTO heb_vpl VALUES ("PS37_24","020_37_24","PSA","37","24","24","כי יפל לא יוטל כי יהוה סומך ידו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_25","020_37_25","PSA","37","25","25","נער הייתי גם זקנתי ולא ראיתי צדיק נעזב וזרעו מבקש לחם׃ ");
INSERT INTO heb_vpl VALUES ("PS37_26","020_37_26","PSA","37","26","26","כל היום חונן ומלוה וזרעו לברכה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_27","020_37_27","PSA","37","27","27","סור מרע ועשה טוב ושכן לעולם׃ ");
INSERT INTO heb_vpl VALUES ("PS37_28","020_37_28","PSA","37","28","28","כי יהוה אהב משפט ולא יעזב את חסידיו לעולם נשמרו וזרע רשעים נכרת׃ ");
INSERT INTO heb_vpl VALUES ("PS37_29","020_37_29","PSA","37","29","29","צדיקים יירשו ארץ וישכנו לעד עליה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_30","020_37_30","PSA","37","30","30","פי צדיק יהגה חכמה ולשונו תדבר משפט׃ ");
INSERT INTO heb_vpl VALUES ("PS37_31","020_37_31","PSA","37","31","31","תורת אלהיו בלבו לא תמעד אשריו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_32","020_37_32","PSA","37","32","32","צופה רשע לצדיק ומבקש להמיתו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_33","020_37_33","PSA","37","33","33","יהוה לא יעזבנו בידו ולא ירשיענו בהשפטו׃ ");
INSERT INTO heb_vpl VALUES ("PS37_34","020_37_34","PSA","37","34","34","קוה אל יהוה ושמר דרכו וירוממך לרשת ארץ בהכרת רשעים תראה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_35","020_37_35","PSA","37","35","35","ראיתי רשע עריץ ומתערה כאזרח רענן׃ ");
INSERT INTO heb_vpl VALUES ("PS37_36","020_37_36","PSA","37","36","36","ויעבר והנה איננו ואבקשהו ולא נמצא׃ ");
INSERT INTO heb_vpl VALUES ("PS37_37","020_37_37","PSA","37","37","37","שמר תם וראה ישר כי אחרית לאיש שלום׃ ");
INSERT INTO heb_vpl VALUES ("PS37_38","020_37_38","PSA","37","38","38","ופשעים נשמדו יחדו אחרית רשעים נכרתה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_39","020_37_39","PSA","37","39","39","ותשועת צדיקים מיהוה מעוזם בעת צרה׃ ");
INSERT INTO heb_vpl VALUES ("PS37_40","020_37_40","PSA","37","40","40","ויעזרם יהוה ויפלטם יפלטם מרשעים ויושיעם כי חסו בו׃ ");
INSERT INTO heb_vpl VALUES ("PS38_1","020_38_1","PSA","38","1","1","מזמור לדוד להזכיר יהוה אל בקצפך תוכיחני ובחמתך תיסרני׃ ");
INSERT INTO heb_vpl VALUES ("PS38_2","020_38_2","PSA","38","2","2","כי חציך נחתו בי ותנחת עלי ידך׃ ");
INSERT INTO heb_vpl VALUES ("PS38_3","020_38_3","PSA","38","3","3","אין מתם בבשרי מפני זעמך אין שלום בעצמי מפני חטאתי׃ ");
INSERT INTO heb_vpl VALUES ("PS38_4","020_38_4","PSA","38","4","4","כי עונתי עברו ראשי כמשא כבד יכבדו ממני׃ ");
INSERT INTO heb_vpl VALUES ("PS38_5","020_38_5","PSA","38","5","5","הבאישו נמקו חבורתי מפני אולתי׃ ");
INSERT INTO heb_vpl VALUES ("PS38_6","020_38_6","PSA","38","6","6","נעויתי שחתי עד מאד כל היום קדר הלכתי׃ ");
INSERT INTO heb_vpl VALUES ("PS38_7","020_38_7","PSA","38","7","7","כי כסלי מלאו נקלה ואין מתם בבשרי׃ ");
INSERT INTO heb_vpl VALUES ("PS38_8","020_38_8","PSA","38","8","8","נפוגותי ונדכיתי עד מאד שאגתי מנהמת לבי׃ ");
INSERT INTO heb_vpl VALUES ("PS38_9","020_38_9","PSA","38","9","9","אדני נגדך כל תאותי ואנחתי ממך לא נסתרה׃ ");
INSERT INTO heb_vpl VALUES ("PS38_10","020_38_10","PSA","38","10","10","לבי סחרחר עזבני כחי ואור עיני גם הם אין אתי׃ ");
INSERT INTO heb_vpl VALUES ("PS38_11","020_38_11","PSA","38","11","11","אהבי ורעי מנגד נגעי יעמדו וקרובי מרחק עמדו׃ ");
INSERT INTO heb_vpl VALUES ("PS38_12","020_38_12","PSA","38","12","12","וינקשו מבקשי נפשי ודרשי רעתי דברו הוות ומרמות כל היום יהגו׃ ");
INSERT INTO heb_vpl VALUES ("PS38_13","020_38_13","PSA","38","13","13","ואני כחרש לא אשמע וכאלם לא יפתח פיו׃ ");
INSERT INTO heb_vpl VALUES ("PS38_14","020_38_14","PSA","38","14","14","ואהי כאיש אשר לא שמע ואין בפיו תוכחות׃ ");
INSERT INTO heb_vpl VALUES ("PS38_15","020_38_15","PSA","38","15","15","כי לך יהוה הוחלתי אתה תענה אדני אלהי׃ ");
INSERT INTO heb_vpl VALUES ("PS38_16","020_38_16","PSA","38","16","16","כי אמרתי פן ישמחו לי במוט רגלי עלי הגדילו׃ ");
INSERT INTO heb_vpl VALUES ("PS38_17","020_38_17","PSA","38","17","17","כי אני לצלע נכון ומכאובי נגדי תמיד׃ ");
INSERT INTO heb_vpl VALUES ("PS38_18","020_38_18","PSA","38","18","18","כי עוני אגיד אדאג מחטאתי׃ ");
INSERT INTO heb_vpl VALUES ("PS38_19","020_38_19","PSA","38","19","19","ואיבי חיים עצמו ורבו שנאי שקר׃ ");
INSERT INTO heb_vpl VALUES ("PS38_20","020_38_20","PSA","38","20","20","ומשלמי רעה תחת טובה ישטנוני תחת רדופי טוב׃ ");
INSERT INTO heb_vpl VALUES ("PS38_21","020_38_21","PSA","38","21","21","אל תעזבני יהוה אלהי אל תרחק ממני׃ ");
INSERT INTO heb_vpl VALUES ("PS38_22","020_38_22","PSA","38","22","22","חושה לעזרתי אדני תשועתי׃ ");
INSERT INTO heb_vpl VALUES ("PS39_1","020_39_1","PSA","39","1","1","למנצח לידיתון מזמור לדוד אמרתי אשמרה דרכי מחטוא בלשוני אשמרה לפי מחסום בעד רשע לנגדי׃ ");
INSERT INTO heb_vpl VALUES ("PS39_2","020_39_2","PSA","39","2","2","נאלמתי דומיה החשיתי מטוב וכאבי נעכר׃ ");
INSERT INTO heb_vpl VALUES ("PS39_3","020_39_3","PSA","39","3","3","חם לבי בקרבי בהגיגי תבער אש דברתי בלשוני׃ ");
INSERT INTO heb_vpl VALUES ("PS39_4","020_39_4","PSA","39","4","4","הודיעני יהוה קצי ומדת ימי מה היא אדעה מה חדל אני׃ ");
INSERT INTO heb_vpl VALUES ("PS39_5","020_39_5","PSA","39","5","5","הנה טפחות נתתה ימי וחלדי כאין נגדך אך כל הבל כל אדם נצב סלה׃ ");
INSERT INTO heb_vpl VALUES ("PS39_6","020_39_6","PSA","39","6","6","אך בצלם יתהלך איש אך הבל יהמיון יצבר ולא ידע מי אספם׃ ");
INSERT INTO heb_vpl VALUES ("PS39_7","020_39_7","PSA","39","7","7","ועתה מה קויתי אדני תוחלתי לך היא׃ ");
INSERT INTO heb_vpl VALUES ("PS39_8","020_39_8","PSA","39","8","8","מכל פשעי הצילני חרפת נבל אל תשימני׃ ");
INSERT INTO heb_vpl VALUES ("PS39_9","020_39_9","PSA","39","9","9","נאלמתי לא אפתח פי כי אתה עשית׃ ");
INSERT INTO heb_vpl VALUES ("PS39_10","020_39_10","PSA","39","10","10","הסר מעלי נגעך מתגרת ידך אני כליתי׃ ");
INSERT INTO heb_vpl VALUES ("PS39_11","020_39_11","PSA","39","11","11","בתוכחות על עון יסרת איש ותמס כעש חמודו אך הבל כל אדם סלה׃ ");
INSERT INTO heb_vpl VALUES ("PS39_12","020_39_12","PSA","39","12","12","שמעה תפלתי יהוה ושועתי האזינה אל דמעתי אל תחרש כי גר אנכי עמך תושב ככל אבותי׃ ");
INSERT INTO heb_vpl VALUES ("PS39_13","020_39_13","PSA","39","13","13","השע ממני ואבליגה בטרם אלך ואינני׃ ");
INSERT INTO heb_vpl VALUES ("PS40_1","020_40_1","PSA","40","1","1","למנצח לדוד מזמור קוה קויתי יהוה ויט אלי וישמע שועתי׃ ");
INSERT INTO heb_vpl VALUES ("PS40_2","020_40_2","PSA","40","2","2","ויעלני מבור שאון מטיט היון ויקם על סלע רגלי כונן אשרי׃ ");
INSERT INTO heb_vpl VALUES ("PS40_3","020_40_3","PSA","40","3","3","ויתן בפי שיר חדש תהלה לאלהינו יראו רבים וייראו ויבטחו ביהוה׃ ");
INSERT INTO heb_vpl VALUES ("PS40_4","020_40_4","PSA","40","4","4","אשרי הגבר אשר שם יהוה מבטחו ולא פנה אל רהבים ושטי כזב׃ ");
INSERT INTO heb_vpl VALUES ("PS40_5","020_40_5","PSA","40","5","5","רבות עשית אתה יהוה אלהי נפלאתיך ומחשבתיך אלינו אין ערך אליך אגידה ואדברה עצמו מספר׃ ");
INSERT INTO heb_vpl VALUES ("PS40_6","020_40_6","PSA","40","6","6","זבח ומנחה לא חפצת אזנים כרית לי עולה וחטאה לא שאלת׃ ");
INSERT INTO heb_vpl VALUES ("PS40_7","020_40_7","PSA","40","7","7","אז אמרתי הנה באתי במגלת ספר כתוב עלי׃ ");
INSERT INTO heb_vpl VALUES ("PS40_8","020_40_8","PSA","40","8","8","לעשות רצונך אלהי חפצתי ותורתך בתוך מעי׃ ");
INSERT INTO heb_vpl VALUES ("PS40_9","020_40_9","PSA","40","9","9","בשרתי צדק בקהל רב הנה שפתי לא אכלא יהוה אתה ידעת׃ ");
INSERT INTO heb_vpl VALUES ("PS40_10","020_40_10","PSA","40","10","10","צדקתך לא כסיתי בתוך לבי אמונתך ותשועתך אמרתי לא כחדתי חסדך ואמתך לקהל רב׃ ");
INSERT INTO heb_vpl VALUES ("PS40_11","020_40_11","PSA","40","11","11","אתה יהוה לא תכלא רחמיך ממני חסדך ואמתך תמיד יצרוני׃ ");
INSERT INTO heb_vpl VALUES ("PS40_12","020_40_12","PSA","40","12","12","כי אפפו עלי רעות עד אין מספר השיגוני עונתי ולא יכלתי לראות עצמו משערות ראשי ולבי עזבני׃ ");
INSERT INTO heb_vpl VALUES ("PS40_13","020_40_13","PSA","40","13","13","רצה יהוה להצילני יהוה לעזרתי חושה׃ ");
INSERT INTO heb_vpl VALUES ("PS40_14","020_40_14","PSA","40","14","14","יבשו ויחפרו יחד מבקשי נפשי לספותה יסגו אחור ויכלמו חפצי רעתי׃ ");
INSERT INTO heb_vpl VALUES ("PS40_15","020_40_15","PSA","40","15","15","ישמו על עקב בשתם האמרים לי האח האח׃ ");
INSERT INTO heb_vpl VALUES ("PS40_16","020_40_16","PSA","40","16","16","ישישו וישמחו בך כל מבקשיך יאמרו תמיד יגדל יהוה אהבי תשועתך׃ ");
INSERT INTO heb_vpl VALUES ("PS40_17","020_40_17","PSA","40","17","17","ואני עני ואביון אדני יחשב לי עזרתי ומפלטי אתה אלהי אל תאחר׃ ");
INSERT INTO heb_vpl VALUES ("PS41_1","020_41_1","PSA","41","1","1","למנצח מזמור לדוד אשרי משכיל אל דל ביום רעה ימלטהו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("PS41_2","020_41_2","PSA","41","2","2","יהוה ישמרהו ויחיהו יאשר בארץ ואל תתנהו בנפש איביו׃ ");
INSERT INTO heb_vpl VALUES ("PS41_3","020_41_3","PSA","41","3","3","יהוה יסעדנו על ערש דוי כל משכבו הפכת בחליו׃ ");
INSERT INTO heb_vpl VALUES ("PS41_4","020_41_4","PSA","41","4","4","אני אמרתי יהוה חנני רפאה נפשי כי חטאתי לך׃ ");
INSERT INTO heb_vpl VALUES ("PS41_5","020_41_5","PSA","41","5","5","אויבי יאמרו רע לי מתי ימות ואבד שמו׃ ");
INSERT INTO heb_vpl VALUES ("PS41_6","020_41_6","PSA","41","6","6","ואם בא לראות שוא ידבר לבו יקבץ און לו יצא לחוץ ידבר׃ ");
INSERT INTO heb_vpl VALUES ("PS41_7","020_41_7","PSA","41","7","7","יחד עלי יתלחשו כל שנאי עלי יחשבו רעה לי׃ ");
INSERT INTO heb_vpl VALUES ("PS41_8","020_41_8","PSA","41","8","8","דבר בליעל יצוק בו ואשר שכב לא יוסיף לקום׃ ");
INSERT INTO heb_vpl VALUES ("PS41_9","020_41_9","PSA","41","9","9","גם איש שלומי אשר בטחתי בו אוכל לחמי הגדיל עלי עקב׃ ");
INSERT INTO heb_vpl VALUES ("PS41_10","020_41_10","PSA","41","10","10","ואתה יהוה חנני והקימני ואשלמה להם׃ ");
INSERT INTO heb_vpl VALUES ("PS41_11","020_41_11","PSA","41","11","11","בזאת ידעתי כי חפצת בי כי לא יריע איבי עלי׃ ");
INSERT INTO heb_vpl VALUES ("PS41_12","020_41_12","PSA","41","12","12","ואני בתמי תמכת בי ותציבני לפניך לעולם׃ ");
INSERT INTO heb_vpl VALUES ("PS41_13","020_41_13","PSA","41","13","13","ברוך יהוה אלהי ישראל מהעולם ועד העולם אמן ואמן׃ ");
INSERT INTO heb_vpl VALUES ("PS42_1","020_42_1","PSA","42","1","1","למנצח משכיל לבני קרח כאיל תערג על אפיקי מים כן נפשי תערג אליך אלהים׃ ");
INSERT INTO heb_vpl VALUES ("PS42_2","020_42_2","PSA","42","2","2","צמאה נפשי לאלהים לאל חי מתי אבוא ואראה פני אלהים׃ ");
INSERT INTO heb_vpl VALUES ("PS42_3","020_42_3","PSA","42","3","3","היתה לי דמעתי לחם יומם ולילה באמר אלי כל היום איה אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("PS42_4","020_42_4","PSA","42","4","4","אלה אזכרה ואשפכה עלי נפשי כי אעבר בסך אדדם עד בית אלהים בקול רנה ותודה המון חוגג׃ ");
INSERT INTO heb_vpl VALUES ("PS42_5","020_42_5","PSA","42","5","5","מה תשתוחחי נפשי ותהמי עלי הוחילי לאלהים כי עוד אודנו ישועות פניו׃ ");
INSERT INTO heb_vpl VALUES ("PS42_6","020_42_6","PSA","42","6","6","אלהי עלי נפשי תשתוחח על כן אזכרך מארץ ירדן וחרמונים מהר מצער׃ ");
INSERT INTO heb_vpl VALUES ("PS42_7","020_42_7","PSA","42","7","7","תהום אל תהום קורא לקול צנוריך כל משבריך וגליך עלי עברו׃ ");
INSERT INTO heb_vpl VALUES ("PS42_8","020_42_8","PSA","42","8","8","יומם יצוה יהוה חסדו ובלילה שירה עמי תפלה לאל חיי׃ ");
INSERT INTO heb_vpl VALUES ("PS42_9","020_42_9","PSA","42","9","9","אומרה לאל סלעי למה שכחתני למה קדר אלך בלחץ אויב׃ ");
INSERT INTO heb_vpl VALUES ("PS42_10","020_42_10","PSA","42","10","10","ברצח בעצמותי חרפוני צוררי באמרם אלי כל היום איה אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("PS42_11","020_42_11","PSA","42","11","11","מה תשתוחחי נפשי ומה תהמי עלי הוחילי לאלהים כי עוד אודנו ישועת פני ואלהי׃ ");
INSERT INTO heb_vpl VALUES ("PS43_1","020_43_1","PSA","43","1","1","שפטני אלהים וריבה ריבי מגוי לא חסיד מאיש מרמה ועולה תפלטני׃ ");
INSERT INTO heb_vpl VALUES ("PS43_2","020_43_2","PSA","43","2","2","כי אתה אלהי מעוזי למה זנחתני למה קדר אתהלך בלחץ אויב׃ ");
INSERT INTO heb_vpl VALUES ("PS43_3","020_43_3","PSA","43","3","3","שלח אורך ואמתך המה ינחוני יביאוני אל הר קדשך ואל משכנותיך׃ ");
INSERT INTO heb_vpl VALUES ("PS43_4","020_43_4","PSA","43","4","4","ואבואה אל מזבח אלהים אל אל שמחת גילי ואודך בכנור אלהים אלהי׃ ");
INSERT INTO heb_vpl VALUES ("PS43_5","020_43_5","PSA","43","5","5","מה תשתוחחי נפשי ומה תהמי עלי הוחילי לאלהים כי עוד אודנו ישועת פני ואלהי׃ ");
INSERT INTO heb_vpl VALUES ("PS44_1","020_44_1","PSA","44","1","1","למנצח לבני קרח משכיל אלהים באזנינו שמענו אבותינו ספרו לנו פעל פעלת בימיהם בימי קדם׃ ");
INSERT INTO heb_vpl VALUES ("PS44_2","020_44_2","PSA","44","2","2","אתה ידך גוים הורשת ותטעם תרע לאמים ותשלחם׃ ");
INSERT INTO heb_vpl VALUES ("PS44_3","020_44_3","PSA","44","3","3","כי לא בחרבם ירשו ארץ וזרועם לא הושיעה למו כי ימינך וזרועך ואור פניך כי רציתם׃ ");
INSERT INTO heb_vpl VALUES ("PS44_4","020_44_4","PSA","44","4","4","אתה הוא מלכי אלהים צוה ישועות יעקב׃ ");
INSERT INTO heb_vpl VALUES ("PS44_5","020_44_5","PSA","44","5","5","בך צרינו ננגח בשמך נבוס קמינו׃ ");
INSERT INTO heb_vpl VALUES ("PS44_6","020_44_6","PSA","44","6","6","כי לא בקשתי אבטח וחרבי לא תושיעני׃ ");
INSERT INTO heb_vpl VALUES ("PS44_7","020_44_7","PSA","44","7","7","כי הושעתנו מצרינו ומשנאינו הבישות׃ ");
INSERT INTO heb_vpl VALUES ("PS44_8","020_44_8","PSA","44","8","8","באלהים הללנו כל היום ושמך לעולם נודה סלה׃ ");
