INSERT INTO heb_vpl VALUES ("PS52_1","020_52_1","PSA","52","1","1","למנצח משכיל לדוד בבוא דואג האדמי ויגד לשאול ויאמר לו בא דוד אל בית אחימלך מה תתהלל ברעה הגבור חסד אל כל היום׃ ");
