INSERT INTO heb_vpl VALUES ("EC3_19","022_3_19","ECC","3","19","19","כי מקרה בני האדם ומקרה הבהמה ומקרה אחד להם כמות זה כן מות זה ורוח אחד לכל ומותר האדם מן הבהמה אין כי הכל הבל׃ ");
INSERT INTO heb_vpl VALUES ("EC3_20","022_3_20","ECC","3","20","20","הכל הולך אל מקום אחד הכל היה מן העפר והכל שב אל העפר׃ ");
