INSERT INTO heb_vpl VALUES ("EC4_1","022_4_1","ECC","4","1","1","ושבתי אני ואראה את כל העשקים אשר נעשים תחת השמש והנה דמעת העשקים ואין להם מנחם ומיד עשקיהם כח ואין להם מנחם׃ ");
INSERT INTO heb_vpl VALUES ("EC4_2","022_4_2","ECC","4","2","2","ושבח אני את המתים שכבר מתו מן החיים אשר המה חיים עדנה׃ ");
