INSERT INTO heb_vpl VALUES ("EC4_4","022_4_4","ECC","4","4","4","וראיתי אני את כל עמל ואת כל כשרון המעשה כי היא קנאת איש מרעהו גם זה הבל ורעות רוח׃ ");
INSERT INTO heb_vpl VALUES ("EC4_5","022_4_5","ECC","4","5","5","הכסיל חבק את ידיו ואכל את בשרו׃ ");
INSERT INTO heb_vpl VALUES ("EC4_6","022_4_6","ECC","4","6","6","טוב מלא כף נחת ממלא חפנים עמל ורעות רוח׃ ");
INSERT INTO heb_vpl VALUES ("EC4_7","022_4_7","ECC","4","7","7","ושבתי אני ואראה הבל תחת השמש׃ ");
INSERT INTO heb_vpl VALUES ("EC4_8","022_4_8","ECC","4","8","8","יש אחד ואין שני גם בן ואח אין לו ואין קץ לכל עמלו גם עיניו לא תשבע עשר ולמי אני עמל ומחסר את נפשי מטובה גם זה הבל וענין רע הוא׃ ");
INSERT INTO heb_vpl VALUES ("EC4_9","022_4_9","ECC","4","9","9","טובים השנים מן האחד אשר יש להם שכר טוב בעמלם׃ ");
INSERT INTO heb_vpl VALUES ("EC4_10","022_4_10","ECC","4","10","10","כי אם יפלו האחד יקים את חברו ואילו האחד שיפול ואין שני להקימו׃ ");
INSERT INTO heb_vpl VALUES ("EC4_11","022_4_11","ECC","4","11","11","גם אם ישכבו שנים וחם להם ולאחד איך יחם׃ ");
INSERT INTO heb_vpl VALUES ("EC4_12","022_4_12","ECC","4","12","12","ואם יתקפו האחד השנים יעמדו נגדו והחוט המשלש לא במהרה ינתק׃ ");
INSERT INTO heb_vpl VALUES ("EC4_13","022_4_13","ECC","4","13","13","טוב ילד מסכן וחכם ממלך זקן וכסיל אשר לא ידע להזהר עוד׃ ");
INSERT INTO heb_vpl VALUES ("EC4_14","022_4_14","ECC","4","14","14","כי מבית הסורים יצא למלך כי גם במלכותו נולד רש׃ ");
INSERT INTO heb_vpl VALUES ("EC4_15","022_4_15","ECC","4","15","15","ראיתי את כל החיים המהלכים תחת השמש עם הילד השני אשר יעמד תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("EC4_16","022_4_16","ECC","4","16","16","אין קץ לכל העם לכל אשר היה לפניהם גם האחרונים לא ישמחו בו כי גם זה הבל ורעיון רוח׃ ");
INSERT INTO heb_vpl VALUES ("EC5_1","022_5_1","ECC","5","1","1","שמר רגליך כאשר תלך אל בית האלהים וקרוב לשמע מתת הכסילים זבח כי אינם יודעים לעשות רע׃ ");
INSERT INTO heb_vpl VALUES ("EC5_2","022_5_2","ECC","5","2","2","אל תבהל על פיך ולבך אל ימהר להוציא דבר לפני האלהים כי האלהים בשמים ואתה על הארץ על כן יהיו דבריך מעטים׃ ");
INSERT INTO heb_vpl VALUES ("EC5_3","022_5_3","ECC","5","3","3","כי בא החלום ברב ענין וקול כסיל ברב דברים׃ ");
INSERT INTO heb_vpl VALUES ("EC5_4","022_5_4","ECC","5","4","4","כאשר תדר נדר לאלהים אל תאחר לשלמו כי אין חפץ בכסילים את אשר תדר שלם׃ ");
INSERT INTO heb_vpl VALUES ("EC5_5","022_5_5","ECC","5","5","5","טוב אשר לא תדר משתדור ולא תשלם׃ ");
INSERT INTO heb_vpl VALUES ("EC5_6","022_5_6","ECC","5","6","6","אל תתן את פיך לחטיא את בשרך ואל תאמר לפני המלאך כי שגגה היא למה יקצף האלהים על קולך וחבל את מעשה ידיך׃ ");
INSERT INTO heb_vpl VALUES ("EC5_7","022_5_7","ECC","5","7","7","כי ברב חלמות והבלים ודברים הרבה כי את האלהים ירא׃ ");
INSERT INTO heb_vpl VALUES ("EC5_8","022_5_8","ECC","5","8","8","אם עשק רש וגזל משפט וצדק תראה במדינה אל תתמה על החפץ כי גבה מעל גבה שמר וגבהים עליהם׃ ");
INSERT INTO heb_vpl VALUES ("EC5_9","022_5_9","ECC","5","9","9","ויתרון ארץ בכל היא מלך לשדה נעבד׃ ");
INSERT INTO heb_vpl VALUES ("EC5_10","022_5_10","ECC","5","10","10","אהב כסף לא ישבע כסף ומי אהב בהמון לא תבואה גם זה הבל׃ ");
INSERT INTO heb_vpl VALUES ("EC5_11","022_5_11","ECC","5","11","11","ברבות הטובה רבו אוכליה ומה כשרון לבעליה כי אם ראית עיניו׃ ");
INSERT INTO heb_vpl VALUES ("EC5_12","022_5_12","ECC","5","12","12","מתוקה שנת העבד אם מעט ואם הרבה יאכל והשבע לעשיר איננו מניח לו לישון׃ ");
INSERT INTO heb_vpl VALUES ("EC5_13","022_5_13","ECC","5","13","13","יש רעה חולה ראיתי תחת השמש עשר שמור לבעליו לרעתו׃ ");
INSERT INTO heb_vpl VALUES ("EC5_14","022_5_14","ECC","5","14","14","ואבד העשר ההוא בענין רע והוליד בן ואין בידו מאומה׃ ");
INSERT INTO heb_vpl VALUES ("EC5_15","022_5_15","ECC","5","15","15","כאשר יצא מבטן אמו ערום ישוב ללכת כשבא ומאומה לא ישא בעמלו שילך בידו׃ ");
INSERT INTO heb_vpl VALUES ("EC5_16","022_5_16","ECC","5","16","16","וגם זה רעה חולה כל עמת שבא כן ילך ומה יתרון לו שיעמל לרוח׃ ");
INSERT INTO heb_vpl VALUES ("EC5_17","022_5_17","ECC","5","17","17","גם כל ימיו בחשך יאכל וכעס הרבה וחליו וקצף׃ ");
INSERT INTO heb_vpl VALUES ("EC5_18","022_5_18","ECC","5","18","18","הנה אשר ראיתי אני טוב אשר יפה לאכול ולשתות ולראות טובה בכל עמלו שיעמל תחת השמש מספר ימי חיו אשר נתן לו האלהים כי הוא חלקו׃ ");
INSERT INTO heb_vpl VALUES ("EC5_19","022_5_19","ECC","5","19","19","גם כל האדם אשר נתן לו האלהים עשר ונכסים והשליטו לאכל ממנו ולשאת את חלקו ולשמח בעמלו זה מתת אלהים היא׃ ");
INSERT INTO heb_vpl VALUES ("EC5_20","022_5_20","ECC","5","20","20","כי לא הרבה יזכר את ימי חייו כי האלהים מענה בשמחת לבו׃ ");
INSERT INTO heb_vpl VALUES ("EC6_1","022_6_1","ECC","6","1","1","יש רעה אשר ראיתי תחת השמש ורבה היא על האדם׃ ");
INSERT INTO heb_vpl VALUES ("EC6_2","022_6_2","ECC","6","2","2","איש אשר יתן לו האלהים עשר ונכסים וכבוד ואיננו חסר לנפשו מכל אשר יתאוה ולא ישליטנו האלהים לאכל ממנו כי איש נכרי יאכלנו זה הבל וחלי רע הוא׃ ");
INSERT INTO heb_vpl VALUES ("EC6_3","022_6_3","ECC","6","3","3","אם יוליד איש מאה ושנים רבות יחיה ורב שיהיו ימי שניו ונפשו לא תשבע מן הטובה וגם קבורה לא היתה לו אמרתי טוב ממנו הנפל׃ ");
INSERT INTO heb_vpl VALUES ("EC6_4","022_6_4","ECC","6","4","4","כי בהבל בא ובחשך ילך ובחשך שמו יכסה׃ ");
INSERT INTO heb_vpl VALUES ("EC6_5","022_6_5","ECC","6","5","5","גם שמש לא ראה ולא ידע נחת לזה מזה׃ ");
INSERT INTO heb_vpl VALUES ("EC6_6","022_6_6","ECC","6","6","6","ואלו חיה אלף שנים פעמים וטובה לא ראה הלא אל מקום אחד הכל הולך׃ ");
INSERT INTO heb_vpl VALUES ("EC6_7","022_6_7","ECC","6","7","7","כל עמל האדם לפיהו וגם הנפש לא תמלא׃ ");
INSERT INTO heb_vpl VALUES ("EC6_8","022_6_8","ECC","6","8","8","כי מה יותר לחכם מן הכסיל מה לעני יודע להלך נגד החיים׃ ");
INSERT INTO heb_vpl VALUES ("EC6_9","022_6_9","ECC","6","9","9","טוב מראה עינים מהלך נפש גם זה הבל ורעות רוח׃ ");
INSERT INTO heb_vpl VALUES ("EC6_10","022_6_10","ECC","6","10","10","מה שהיה כבר נקרא שמו ונודע אשר הוא אדם ולא יוכל לדין עם שהתקיף ממנו׃ ");
INSERT INTO heb_vpl VALUES ("EC6_11","022_6_11","ECC","6","11","11","כי יש דברים הרבה מרבים הבל מה יתר לאדם׃ ");
INSERT INTO heb_vpl VALUES ("EC6_12","022_6_12","ECC","6","12","12","כי מי יודע מה טוב לאדם בחיים מספר ימי חיי הבלו ויעשם כצל אשר מי יגיד לאדם מה יהיה אחריו תחת השמש׃ ");
INSERT INTO heb_vpl VALUES ("EC7_1","022_7_1","ECC","7","1","1","טוב שם משמן טוב ויום המות מיום הולדו׃ ");
INSERT INTO heb_vpl VALUES ("EC7_2","022_7_2","ECC","7","2","2","טוב ללכת אל בית אבל מלכת אל בית משתה באשר הוא סוף כל האדם והחי יתן אל לבו׃ ");
INSERT INTO heb_vpl VALUES ("EC7_3","022_7_3","ECC","7","3","3","טוב כעס משחק כי ברע פנים ייטב לב׃ ");
INSERT INTO heb_vpl VALUES ("EC7_4","022_7_4","ECC","7","4","4","לב חכמים בבית אבל ולב כסילים בבית שמחה׃ ");
INSERT INTO heb_vpl VALUES ("EC7_5","022_7_5","ECC","7","5","5","טוב לשמע גערת חכם מאיש שמע שיר כסילים׃ ");
INSERT INTO heb_vpl VALUES ("EC7_6","022_7_6","ECC","7","6","6","כי כקול הסירים תחת הסיר כן שחק הכסיל וגם זה הבל׃ ");
INSERT INTO heb_vpl VALUES ("EC7_7","022_7_7","ECC","7","7","7","כי העשק יהולל חכם ויאבד את לב מתנה׃ ");
INSERT INTO heb_vpl VALUES ("EC7_8","022_7_8","ECC","7","8","8","טוב אחרית דבר מראשיתו טוב ארך רוח מגבה רוח׃ ");
INSERT INTO heb_vpl VALUES ("EC7_9","022_7_9","ECC","7","9","9","אל תבהל ברוחך לכעוס כי כעס בחיק כסילים ינוח׃ ");
INSERT INTO heb_vpl VALUES ("EC7_10","022_7_10","ECC","7","10","10","אל תאמר מה היה שהימים הראשנים היו טובים מאלה כי לא מחכמה שאלת על זה׃ ");
INSERT INTO heb_vpl VALUES ("EC7_11","022_7_11","ECC","7","11","11","טובה חכמה עם נחלה ויתר לראי השמש׃ ");
INSERT INTO heb_vpl VALUES ("EC7_12","022_7_12","ECC","7","12","12","כי בצל החכמה בצל הכסף ויתרון דעת החכמה תחיה בעליה׃ ");
INSERT INTO heb_vpl VALUES ("EC7_13","022_7_13","ECC","7","13","13","ראה את מעשה האלהים כי מי יוכל לתקן את אשר עותו׃ ");
INSERT INTO heb_vpl VALUES ("EC7_14","022_7_14","ECC","7","14","14","ביום טובה היה בטוב וביום רעה ראה גם את זה לעמת זה עשה האלהים על דברת שלא ימצא האדם אחריו מאומה׃ ");
INSERT INTO heb_vpl VALUES ("EC7_15","022_7_15","ECC","7","15","15","את הכל ראיתי בימי הבלי יש צדיק אבד בצדקו ויש רשע מאריך ברעתו׃ ");
INSERT INTO heb_vpl VALUES ("EC7_16","022_7_16","ECC","7","16","16","אל תהי צדיק הרבה ואל תתחכם יותר למה תשומם׃ ");
INSERT INTO heb_vpl VALUES ("EC7_17","022_7_17","ECC","7","17","17","אל תרשע הרבה ואל תהי סכל למה תמות בלא עתך׃ ");
INSERT INTO heb_vpl VALUES ("EC7_18","022_7_18","ECC","7","18","18","טוב אשר תאחז בזה וגם מזה אל תנח את ידך כי ירא אלהים יצא את כלם׃ ");
INSERT INTO heb_vpl VALUES ("EC7_19","022_7_19","ECC","7","19","19","החכמה תעז לחכם מעשרה שליטים אשר היו בעיר׃ ");
INSERT INTO heb_vpl VALUES ("EC7_20","022_7_20","ECC","7","20","20","כי אדם אין צדיק בארץ אשר יעשה טוב ולא יחטא׃ ");
INSERT INTO heb_vpl VALUES ("EC7_21","022_7_21","ECC","7","21","21","גם לכל הדברים אשר ידברו אל תתן לבך אשר לא תשמע את עבדך מקללך׃ ");
INSERT INTO heb_vpl VALUES ("EC7_22","022_7_22","ECC","7","22","22","כי גם פעמים רבות ידע לבך אשר גם את קללת אחרים׃ ");
INSERT INTO heb_vpl VALUES ("EC7_23","022_7_23","ECC","7","23","23","כל זה נסיתי בחכמה אמרתי אחכמה והיא רחוקה ממני׃ ");
INSERT INTO heb_vpl VALUES ("EC7_24","022_7_24","ECC","7","24","24","רחוק מה שהיה ועמק עמק מי ימצאנו׃ ");
INSERT INTO heb_vpl VALUES ("EC7_25","022_7_25","ECC","7","25","25","סבותי אני ולבי לדעת ולתור ובקש חכמה וחשבון ולדעת רשע כסל והסכלות הוללות׃ ");
INSERT INTO heb_vpl VALUES ("EC7_26","022_7_26","ECC","7","26","26","ומוצא אני מר ממות את האשה אשר היא מצודים וחרמים לבה אסורים ידיה טוב לפני האלהים ימלט ממנה וחוטא ילכד בה׃ ");
INSERT INTO heb_vpl VALUES ("EC7_27","022_7_27","ECC","7","27","27","ראה זה מצאתי אמרה קהלת אחת לאחת למצא חשבון׃ ");
INSERT INTO heb_vpl VALUES ("EC7_28","022_7_28","ECC","7","28","28","אשר עוד בקשה נפשי ולא מצאתי אדם אחד מאלף מצאתי ואשה בכל אלה לא מצאתי׃ ");
INSERT INTO heb_vpl VALUES ("EC7_29","022_7_29","ECC","7","29","29","לבד ראה זה מצאתי אשר עשה האלהים את האדם ישר והמה בקשו חשבנות רבים׃ ");
INSERT INTO heb_vpl VALUES ("EC8_1","022_8_1","ECC","8","1","1","מי כהחכם ומי יודע פשר דבר חכמת אדם תאיר פניו ועז פניו ישנא׃ ");
INSERT INTO heb_vpl VALUES ("EC8_2","022_8_2","ECC","8","2","2","אני פי מלך שמור ועל דברת שבועת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("EC8_3","022_8_3","ECC","8","3","3","אל תבהל מפניו תלך אל תעמד בדבר רע כי כל אשר יחפץ יעשה׃ ");
INSERT INTO heb_vpl VALUES ("EC8_4","022_8_4","ECC","8","4","4","באשר דבר מלך שלטון ומי יאמר לו מה תעשה׃ ");
INSERT INTO heb_vpl VALUES ("EC8_5","022_8_5","ECC","8","5","5","שומר מצוה לא ידע דבר רע ועת ומשפט ידע לב חכם׃ ");
INSERT INTO heb_vpl VALUES ("EC8_6","022_8_6","ECC","8","6","6","כי לכל חפץ יש עת ומשפט כי רעת האדם רבה עליו׃ ");
INSERT INTO heb_vpl VALUES ("EC8_7","022_8_7","ECC","8","7","7","כי איננו ידע מה שיהיה כי כאשר יהיה מי יגיד לו׃ ");
INSERT INTO heb_vpl VALUES ("EC8_8","022_8_8","ECC","8","8","8","אין אדם שליט ברוח לכלוא את הרוח ואין שלטון ביום המות ואין משלחת במלחמה ולא ימלט רשע את בעליו׃ ");
INSERT INTO heb_vpl VALUES ("EC8_9","022_8_9","ECC","8","9","9","את כל זה ראיתי ונתון את לבי לכל מעשה אשר נעשה תחת השמש עת אשר שלט האדם באדם לרע לו׃ ");
INSERT INTO heb_vpl VALUES ("EC8_10","022_8_10","ECC","8","10","10","ובכן ראיתי רשעים קברים ובאו וממקום קדוש יהלכו וישתכחו בעיר אשר כן עשו גם זה הבל׃ ");
INSERT INTO heb_vpl VALUES ("EC8_11","022_8_11","ECC","8","11","11","אשר אין נעשה פתגם מעשה הרעה מהרה על כן מלא לב בני האדם בהם לעשות רע׃ ");
INSERT INTO heb_vpl VALUES ("EC8_12","022_8_12","ECC","8","12","12","אשר חטא עשה רע מאת ומאריך לו כי גם יודע אני אשר יהיה טוב ליראי האלהים אשר ייראו מלפניו׃ ");
INSERT INTO heb_vpl VALUES ("EC8_13","022_8_13","ECC","8","13","13","וטוב לא יהיה לרשע ולא יאריך ימים כצל אשר איננו ירא מלפני אלהים׃ ");
INSERT INTO heb_vpl VALUES ("EC8_14","022_8_14","ECC","8","14","14","יש הבל אשר נעשה על הארץ אשר יש צדיקים אשר מגיע אלהם כמעשה הרשעים ויש רשעים שמגיע אלהם כמעשה הצדיקים אמרתי שגם זה הבל׃ ");
INSERT INTO heb_vpl VALUES ("EC8_15","022_8_15","ECC","8","15","15","ושבחתי אני את השמחה אשר אין טוב לאדם תחת השמש כי אם לאכול ולשתות ולשמוח והוא ילונו בעמלו ימי חייו אשר נתן לו האלהים תחת השמש׃ ");
INSERT INTO heb_vpl VALUES ("EC8_16","022_8_16","ECC","8","16","16","כאשר נתתי את לבי לדעת חכמה ולראות את הענין אשר נעשה על הארץ כי גם ביום ובלילה שנה בעיניו איננו ראה׃ ");
INSERT INTO heb_vpl VALUES ("EC8_17","022_8_17","ECC","8","17","17","וראיתי את כל מעשה האלהים כי לא יוכל האדם למצוא את המעשה אשר נעשה תחת השמש בשל אשר יעמל האדם לבקש ולא ימצא וגם אם יאמר החכם לדעת לא יוכל למצא׃ ");
INSERT INTO heb_vpl VALUES ("EC9_1","022_9_1","ECC","9","1","1","כי את כל זה נתתי אל לבי ולבור את כל זה אשר הצדיקים והחכמים ועבדיהם ביד האלהים גם אהבה גם שנאה אין יודע האדם הכל לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("EC9_2","022_9_2","ECC","9","2","2","הכל כאשר לכל מקרה אחד לצדיק ולרשע לטוב ולטהור ולטמא ולזבח ולאשר איננו זבח כטוב כחטא הנשבע כאשר שבועה ירא׃ ");
INSERT INTO heb_vpl VALUES ("EC9_3","022_9_3","ECC","9","3","3","זה רע בכל אשר נעשה תחת השמש כי מקרה אחד לכל וגם לב בני האדם מלא רע והוללות בלבבם בחייהם ואחריו אל המתים׃ ");
INSERT INTO heb_vpl VALUES ("EC9_4","022_9_4","ECC","9","4","4","כי מי אשר יבחר אל כל החיים יש בטחון כי לכלב חי הוא טוב מן האריה המת׃ ");
INSERT INTO heb_vpl VALUES ("EC9_5","022_9_5","ECC","9","5","5","כי החיים יודעים שימתו והמתים אינם יודעים מאומה ואין עוד להם שכר כי נשכח זכרם׃ ");
INSERT INTO heb_vpl VALUES ("EC9_6","022_9_6","ECC","9","6","6","גם אהבתם גם שנאתם גם קנאתם כבר אבדה וחלק אין להם עוד לעולם בכל אשר נעשה תחת השמש׃ ");
INSERT INTO heb_vpl VALUES ("EC9_7","022_9_7","ECC","9","7","7","לך אכל בשמחה לחמך ושתה בלב טוב יינך כי כבר רצה האלהים את מעשיך׃ ");
INSERT INTO heb_vpl VALUES ("EC9_8","022_9_8","ECC","9","8","8","בכל עת יהיו בגדיך לבנים ושמן על ראשך אל יחסר׃ ");
INSERT INTO heb_vpl VALUES ("EC9_9","022_9_9","ECC","9","9","9","ראה חיים עם אשה אשר אהבת כל ימי חיי הבלך אשר נתן לך תחת השמש כל ימי הבלך כי הוא חלקך בחיים ובעמלך אשר אתה עמל תחת השמש׃ ");
INSERT INTO heb_vpl VALUES ("EC9_10","022_9_10","ECC","9","10","10","כל אשר תמצא ידך לעשות בכחך עשה כי אין מעשה וחשבון ודעת וחכמה בשאול אשר אתה הלך שמה׃ ");
INSERT INTO heb_vpl VALUES ("EC9_11","022_9_11","ECC","9","11","11","שבתי וראה תחת השמש כי לא לקלים המרוץ ולא לגבורים המלחמה וגם לא לחכמים לחם וגם לא לנבנים עשר וגם לא לידעים חן כי עת ופגע יקרה את כלם׃ ");
INSERT INTO heb_vpl VALUES ("EC9_12","022_9_12","ECC","9","12","12","כי גם לא ידע האדם את עתו כדגים שנאחזים במצודה רעה וכצפרים האחזות בפח כהם יוקשים בני האדם לעת רעה כשתפול עליהם פתאם׃ ");
INSERT INTO heb_vpl VALUES ("EC9_13","022_9_13","ECC","9","13","13","גם זה ראיתי חכמה תחת השמש וגדולה היא אלי׃ ");
INSERT INTO heb_vpl VALUES ("EC9_14","022_9_14","ECC","9","14","14","עיר קטנה ואנשים בה מעט ובא אליה מלך גדול וסבב אתה ובנה עליה מצודים גדלים׃ ");
INSERT INTO heb_vpl VALUES ("EC9_15","022_9_15","ECC","9","15","15","ומצא בה איש מסכן חכם ומלט הוא את העיר בחכמתו ואדם לא זכר את האיש המסכן ההוא׃ ");
INSERT INTO heb_vpl VALUES ("EC9_16","022_9_16","ECC","9","16","16","ואמרתי אני טובה חכמה מגבורה וחכמת המסכן בזויה ודבריו אינם נשמעים׃ ");
INSERT INTO heb_vpl VALUES ("EC9_17","022_9_17","ECC","9","17","17","דברי חכמים בנחת נשמעים מזעקת מושל בכסילים׃ ");
INSERT INTO heb_vpl VALUES ("EC9_18","022_9_18","ECC","9","18","18","טובה חכמה מכלי קרב וחוטא אחד יאבד טובה הרבה׃ ");
INSERT INTO heb_vpl VALUES ("EC10_1","022_10_1","ECC","10","1","1","זבובי מות יבאיש יביע שמן רוקח יקר מחכמה מכבוד סכלות מעט׃ ");
INSERT INTO heb_vpl VALUES ("EC10_2","022_10_2","ECC","10","2","2","לב חכם לימינו ולב כסיל לשמאלו׃ ");
INSERT INTO heb_vpl VALUES ("EC10_3","022_10_3","ECC","10","3","3","וגם בדרך כשהסכל הלך לבו חסר ואמר לכל סכל הוא׃ ");
INSERT INTO heb_vpl VALUES ("EC10_4","022_10_4","ECC","10","4","4","אם רוח המושל תעלה עליך מקומך אל תנח כי מרפא יניח חטאים גדולים׃ ");
INSERT INTO heb_vpl VALUES ("EC10_5","022_10_5","ECC","10","5","5","יש רעה ראיתי תחת השמש כשגגה שיצא מלפני השליט׃ ");
INSERT INTO heb_vpl VALUES ("EC10_6","022_10_6","ECC","10","6","6","נתן הסכל במרומים רבים ועשירים בשפל ישבו׃ ");
INSERT INTO heb_vpl VALUES ("EC10_7","022_10_7","ECC","10","7","7","ראיתי עבדים על סוסים ושרים הלכים כעבדים על הארץ׃ ");
INSERT INTO heb_vpl VALUES ("EC10_8","022_10_8","ECC","10","8","8","חפר גומץ בו יפול ופרץ גדר ישכנו נחש׃ ");
INSERT INTO heb_vpl VALUES ("EC10_9","022_10_9","ECC","10","9","9","מסיע אבנים יעצב בהם בוקע עצים יסכן בם׃ ");
INSERT INTO heb_vpl VALUES ("EC10_10","022_10_10","ECC","10","10","10","אם קהה הברזל והוא לא פנים קלקל וחילים יגבר ויתרון הכשיר חכמה׃ ");
INSERT INTO heb_vpl VALUES ("EC10_11","022_10_11","ECC","10","11","11","אם ישך הנחש בלוא לחש ואין יתרון לבעל הלשון׃ ");
INSERT INTO heb_vpl VALUES ("EC10_12","022_10_12","ECC","10","12","12","דברי פי חכם חן ושפתות כסיל תבלענו׃ ");
INSERT INTO heb_vpl VALUES ("EC10_13","022_10_13","ECC","10","13","13","תחלת דברי פיהו סכלות ואחרית פיהו הוללות רעה׃ ");
INSERT INTO heb_vpl VALUES ("EC10_14","022_10_14","ECC","10","14","14","והסכל ירבה דברים לא ידע האדם מה שיהיה ואשר יהיה מאחריו מי יגיד לו׃ ");
INSERT INTO heb_vpl VALUES ("EC10_15","022_10_15","ECC","10","15","15","עמל הכסילים תיגענו אשר לא ידע ללכת אל עיר׃ ");
INSERT INTO heb_vpl VALUES ("EC10_16","022_10_16","ECC","10","16","16","אי לך ארץ שמלכך נער ושריך בבקר יאכלו׃ ");
INSERT INTO heb_vpl VALUES ("EC10_17","022_10_17","ECC","10","17","17","אשריך ארץ שמלכך בן חורים ושריך בעת יאכלו בגבורה ולא בשתי׃ ");
INSERT INTO heb_vpl VALUES ("EC10_18","022_10_18","ECC","10","18","18","בעצלתים ימך המקרה ובשפלות ידים ידלף הבית׃ ");
INSERT INTO heb_vpl VALUES ("EC10_19","022_10_19","ECC","10","19","19","לשחוק עשים לחם ויין ישמח חיים והכסף יענה את הכל׃ ");
INSERT INTO heb_vpl VALUES ("EC10_20","022_10_20","ECC","10","20","20","גם במדעך מלך אל תקלל ובחדרי משכבך אל תקלל עשיר כי עוף השמים יוליך את הקול ובעל הכנפים יגיד דבר׃ ");
INSERT INTO heb_vpl VALUES ("EC11_1","022_11_1","ECC","11","1","1","שלח לחמך על פני המים כי ברב הימים תמצאנו׃ ");
INSERT INTO heb_vpl VALUES ("EC11_2","022_11_2","ECC","11","2","2","תן חלק לשבעה וגם לשמונה כי לא תדע מה יהיה רעה על הארץ׃ ");
INSERT INTO heb_vpl VALUES ("EC11_3","022_11_3","ECC","11","3","3","אם ימלאו העבים גשם על הארץ יריקו ואם יפול עץ בדרום ואם בצפון מקום שיפול העץ שם יהוא׃ ");
INSERT INTO heb_vpl VALUES ("EC11_4","022_11_4","ECC","11","4","4","שמר רוח לא יזרע וראה בעבים לא יקצור׃ ");
INSERT INTO heb_vpl VALUES ("EC11_5","022_11_5","ECC","11","5","5","כאשר אינך יודע מה דרך הרוח כעצמים בבטן המלאה ככה לא תדע את מעשה האלהים אשר יעשה את הכל׃ ");
INSERT INTO heb_vpl VALUES ("EC11_6","022_11_6","ECC","11","6","6","בבקר זרע את זרעך ולערב אל תנח ידך כי אינך יודע אי זה יכשר הזה או זה ואם שניהם כאחד טובים׃ ");
INSERT INTO heb_vpl VALUES ("EC11_7","022_11_7","ECC","11","7","7","ומתוק האור וטוב לעינים לראות את השמש׃ ");
INSERT INTO heb_vpl VALUES ("EC11_8","022_11_8","ECC","11","8","8","כי אם שנים הרבה יחיה האדם בכלם ישמח ויזכר את ימי החשך כי הרבה יהיו כל שבא הבל׃ ");
INSERT INTO heb_vpl VALUES ("EC11_9","022_11_9","ECC","11","9","9","שמח בחור בילדותיך ויטיבך לבך בימי בחורותך והלך בדרכי לבך ובמראי עיניך ודע כי על כל אלה יביאך האלהים במשפט׃ ");
INSERT INTO heb_vpl VALUES ("EC11_10","022_11_10","ECC","11","10","10","והסר כעס מלבך והעבר רעה מבשרך כי הילדות והשחרות הבל׃ ");
INSERT INTO heb_vpl VALUES ("EC12_1","022_12_1","ECC","12","1","1","וזכר את בוראיך בימי בחורתיך עד אשר לא יבאו ימי הרעה והגיעו שנים אשר תאמר אין לי בהם חפץ׃ ");
INSERT INTO heb_vpl VALUES ("EC12_2","022_12_2","ECC","12","2","2","עד אשר לא תחשך השמש והאור והירח והכוכבים ושבו העבים אחר הגשם׃ ");
INSERT INTO heb_vpl VALUES ("EC12_3","022_12_3","ECC","12","3","3","ביום שיזעו שמרי הבית והתעותו אנשי החיל ובטלו הטחנות כי מעטו וחשכו הראות בארבות׃ ");
INSERT INTO heb_vpl VALUES ("EC12_4","022_12_4","ECC","12","4","4","וסגרו דלתים בשוק בשפל קול הטחנה ויקום לקול הצפור וישחו כל בנות השיר׃ ");
INSERT INTO heb_vpl VALUES ("EC12_5","022_12_5","ECC","12","5","5","גם מגבה יראו וחתחתים בדרך וינאץ השקד ויסתבל החגב ותפר האביונה כי הלך האדם אל בית עולמו וסבבו בשוק הספדים׃ ");
INSERT INTO heb_vpl VALUES ("EC12_6","022_12_6","ECC","12","6","6","עד אשר לא ירחק חבל הכסף ותרץ גלת הזהב ותשבר כד על המבוע ונרץ הגלגל אל הבור׃ ");
INSERT INTO heb_vpl VALUES ("EC12_7","022_12_7","ECC","12","7","7","וישב העפר על הארץ כשהיה והרוח תשוב אל האלהים אשר נתנה׃ ");
INSERT INTO heb_vpl VALUES ("EC12_8","022_12_8","ECC","12","8","8","הבל הבלים אמר הקוהלת הכל הבל׃ ");
INSERT INTO heb_vpl VALUES ("EC12_9","022_12_9","ECC","12","9","9","ויתר שהיה קהלת חכם עוד למד דעת את העם ואזן וחקר תקן משלים הרבה׃ ");
INSERT INTO heb_vpl VALUES ("EC12_10","022_12_10","ECC","12","10","10","בקש קהלת למצא דברי חפץ וכתוב ישר דברי אמת׃ ");
INSERT INTO heb_vpl VALUES ("EC12_11","022_12_11","ECC","12","11","11","דברי חכמים כדרבנות וכמשמרות נטועים בעלי אספות נתנו מרעה אחד׃ ");
INSERT INTO heb_vpl VALUES ("EC12_12","022_12_12","ECC","12","12","12","ויתר מהמה בני הזהר עשות ספרים הרבה אין קץ ולהג הרבה יגעת בשר׃ ");
INSERT INTO heb_vpl VALUES ("EC12_13","022_12_13","ECC","12","13","13","סוף דבר הכל נשמע את האלהים ירא ואת מצותיו שמור כי זה כל האדם׃ ");
INSERT INTO heb_vpl VALUES ("EC12_14","022_12_14","ECC","12","14","14","כי את כל מעשה האלהים יבא במשפט על כל נעלם אם טוב ואם רע׃ ");
INSERT INTO heb_vpl VALUES ("SS1_1","023_1_1","SNG","1","1","1","שיר השירים אשר לשלמה׃ ");
INSERT INTO heb_vpl VALUES ("SS1_2","023_1_2","SNG","1","2","2","ישקני מנשיקות פיהו כי טובים דדיך מיין׃ ");
INSERT INTO heb_vpl VALUES ("SS1_3","023_1_3","SNG","1","3","3","לריח שמניך טובים שמן תורק שמך על כן עלמות אהבוך׃ ");
INSERT INTO heb_vpl VALUES ("SS1_4","023_1_4","SNG","1","4","4","משכני אחריך נרוצה הביאני המלך חדריו נגילה ונשמחה בך נזכירה דדיך מיין מישרים אהבוך׃ ");
INSERT INTO heb_vpl VALUES ("SS1_5","023_1_5","SNG","1","5","5","שחורה אני ונאוה בנות ירושלם כאהלי קדר כיריעות שלמה׃ ");
