INSERT INTO heb_vpl VALUES ("SS1_7","023_1_7","SNG","1","7","7","הגידה לי שאהבה נפשי איכה תרעה איכה תרביץ בצהרים שלמה אהיה כעטיה על עדרי חבריך׃ ");
INSERT INTO heb_vpl VALUES ("SS1_8","023_1_8","SNG","1","8","8","אם לא תדעי לך היפה בנשים צאי לך בעקבי הצאן ורעי את גדיתיך על משכנות הרעים׃ ");
INSERT INTO heb_vpl VALUES ("SS1_9","023_1_9","SNG","1","9","9","לססתי ברכבי פרעה דמיתיך רעיתי׃ ");
INSERT INTO heb_vpl VALUES ("SS1_10","023_1_10","SNG","1","10","10","נאוו לחייך בתרים צוארך בחרוזים׃ ");
INSERT INTO heb_vpl VALUES ("SS1_11","023_1_11","SNG","1","11","11","תורי זהב נעשה לך עם נקדות הכסף׃ ");
INSERT INTO heb_vpl VALUES ("SS1_12","023_1_12","SNG","1","12","12","עד שהמלך במסבו נרדי נתן ריחו׃ ");
INSERT INTO heb_vpl VALUES ("SS1_13","023_1_13","SNG","1","13","13","צרור המר דודי לי בין שדי ילין׃ ");
INSERT INTO heb_vpl VALUES ("SS1_14","023_1_14","SNG","1","14","14","אשכל הכפר דודי לי בכרמי עין גדי׃ ");
INSERT INTO heb_vpl VALUES ("SS1_15","023_1_15","SNG","1","15","15","הנך יפה רעיתי הנך יפה עיניך יונים׃ ");
INSERT INTO heb_vpl VALUES ("SS1_16","023_1_16","SNG","1","16","16","הנך יפה דודי אף נעים אף ערשנו רעננה׃ ");
INSERT INTO heb_vpl VALUES ("SS1_17","023_1_17","SNG","1","17","17","קרות בתינו ארזים רחיטנו ברותים׃ ");
INSERT INTO heb_vpl VALUES ("SS2_1","023_2_1","SNG","2","1","1","אני חבצלת השרון שושנת העמקים׃ ");
INSERT INTO heb_vpl VALUES ("SS2_2","023_2_2","SNG","2","2","2","כשושנה בין החוחים כן רעיתי בין הבנות׃ ");
INSERT INTO heb_vpl VALUES ("SS2_3","023_2_3","SNG","2","3","3","כתפוח בעצי היער כן דודי בין הבנים בצלו חמדתי וישבתי ופריו מתוק לחכי׃ ");
INSERT INTO heb_vpl VALUES ("SS2_4","023_2_4","SNG","2","4","4","הביאני אל בית היין ודגלו עלי אהבה׃ ");
INSERT INTO heb_vpl VALUES ("SS2_5","023_2_5","SNG","2","5","5","סמכוני באשישות רפדוני בתפוחים כי חולת אהבה אני׃ ");
INSERT INTO heb_vpl VALUES ("SS2_6","023_2_6","SNG","2","6","6","שמאלו תחת לראשי וימינו תחבקני׃ ");
INSERT INTO heb_vpl VALUES ("SS2_7","023_2_7","SNG","2","7","7","השבעתי אתכם בנות ירושלם בצבאות או באילות השדה אם תעירו ואם תעוררו את האהבה עד שתחפץ׃ ");
INSERT INTO heb_vpl VALUES ("SS2_8","023_2_8","SNG","2","8","8","קול דודי הנה זה בא מדלג על ההרים מקפץ על הגבעות׃ ");
INSERT INTO heb_vpl VALUES ("SS2_9","023_2_9","SNG","2","9","9","דומה דודי לצבי או לעפר האילים הנה זה עומד אחר כתלנו משגיח מן החלנות מציץ מן החרכים׃ ");
INSERT INTO heb_vpl VALUES ("SS2_10","023_2_10","SNG","2","10","10","ענה דודי ואמר לי קומי לך רעיתי יפתי ולכי לך׃ ");
INSERT INTO heb_vpl VALUES ("SS2_11","023_2_11","SNG","2","11","11","כי הנה הסתו עבר הגשם חלף הלך לו׃ ");
INSERT INTO heb_vpl VALUES ("SS2_12","023_2_12","SNG","2","12","12","הנצנים נראו בארץ עת הזמיר הגיע וקול התור נשמע בארצנו׃ ");
INSERT INTO heb_vpl VALUES ("SS2_13","023_2_13","SNG","2","13","13","התאנה חנטה פגיה והגפנים סמדר נתנו ריח קומי לכי רעיתי יפתי ולכי לך׃ ");
INSERT INTO heb_vpl VALUES ("SS2_14","023_2_14","SNG","2","14","14","יונתי בחגוי הסלע בסתר המדרגה הראיני את מראיך השמיעיני את קולך כי קולך ערב ומראיך נאוה׃ ");
INSERT INTO heb_vpl VALUES ("SS2_15","023_2_15","SNG","2","15","15","אחזו לנו שועלים שועלים קטנים מחבלים כרמים וכרמינו סמדר׃ ");
INSERT INTO heb_vpl VALUES ("SS2_16","023_2_16","SNG","2","16","16","דודי לי ואני לו הרעה בשושנים׃ ");
INSERT INTO heb_vpl VALUES ("SS2_17","023_2_17","SNG","2","17","17","עד שיפוח היום ונסו הצללים סב דמה לך דודי לצבי או לעפר האילים על הרי בתר׃ ");
INSERT INTO heb_vpl VALUES ("SS3_1","023_3_1","SNG","3","1","1","על משכבי בלילות בקשתי את שאהבה נפשי בקשתיו ולא מצאתיו׃ ");
INSERT INTO heb_vpl VALUES ("SS3_2","023_3_2","SNG","3","2","2","אקומה נא ואסובבה בעיר בשוקים וברחבות אבקשה את שאהבה נפשי בקשתיו ולא מצאתיו׃ ");
INSERT INTO heb_vpl VALUES ("SS3_3","023_3_3","SNG","3","3","3","מצאוני השמרים הסבבים בעיר את שאהבה נפשי ראיתם׃ ");
INSERT INTO heb_vpl VALUES ("SS3_4","023_3_4","SNG","3","4","4","כמעט שעברתי מהם עד שמצאתי את שאהבה נפשי אחזתיו ולא ארפנו עד שהביאתיו אל בית אמי ואל חדר הורתי׃ ");
INSERT INTO heb_vpl VALUES ("SS3_5","023_3_5","SNG","3","5","5","השבעתי אתכם בנות ירושלם בצבאות או באילות השדה אם תעירו ואם תעוררו את האהבה עד שתחפץ׃ ");
INSERT INTO heb_vpl VALUES ("SS3_6","023_3_6","SNG","3","6","6","מי זאת עלה מן המדבר כתימרות עשן מקטרת מור ולבונה מכל אבקת רוכל׃ ");
INSERT INTO heb_vpl VALUES ("SS3_7","023_3_7","SNG","3","7","7","הנה מטתו שלשלמה ששים גברים סביב לה מגברי ישראל׃ ");
