INSERT INTO heb_vpl VALUES ("IS1_19","024_1_19","ISA","1","19","19","אם תאבו ושמעתם טוב הארץ תאכלו׃ ");
INSERT INTO heb_vpl VALUES ("IS1_20","024_1_20","ISA","1","20","20","ואם תמאנו ומריתם חרב תאכלו כי פי יהוה דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS1_21","024_1_21","ISA","1","21","21","איכה היתה לזונה קריה נאמנה מלאתי משפט צדק ילין בה ועתה מרצחים׃ ");
INSERT INTO heb_vpl VALUES ("IS1_22","024_1_22","ISA","1","22","22","כספך היה לסיגים סבאך מהול במים׃ ");
INSERT INTO heb_vpl VALUES ("IS1_23","024_1_23","ISA","1","23","23","שריך סוררים וחברי גנבים כלו אהב שחד ורדף שלמנים יתום לא ישפטו וריב אלמנה לא יבוא אליהם׃ ");
INSERT INTO heb_vpl VALUES ("IS1_24","024_1_24","ISA","1","24","24","לכן נאם האדון יהוה צבאות אביר ישראל הוי אנחם מצרי ואנקמה מאויבי׃ ");
INSERT INTO heb_vpl VALUES ("IS1_25","024_1_25","ISA","1","25","25","ואשיבה ידי עליך ואצרף כבר סיגיך ואסירה כל בדיליך׃ ");
INSERT INTO heb_vpl VALUES ("IS1_26","024_1_26","ISA","1","26","26","ואשיבה שפטיך כבראשנה ויעציך כבתחלה אחרי כן יקרא לך עיר הצדק קריה נאמנה׃ ");
INSERT INTO heb_vpl VALUES ("IS1_27","024_1_27","ISA","1","27","27","ציון במשפט תפדה ושביה בצדקה׃ ");
INSERT INTO heb_vpl VALUES ("IS1_28","024_1_28","ISA","1","28","28","ושבר פשעים וחטאים יחדו ועזבי יהוה יכלו׃ ");
INSERT INTO heb_vpl VALUES ("IS1_29","024_1_29","ISA","1","29","29","כי יבשו מאילים אשר חמדתם ותחפרו מהגנות אשר בחרתם׃ ");
INSERT INTO heb_vpl VALUES ("IS1_30","024_1_30","ISA","1","30","30","כי תהיו כאלה נבלת עלה וכגנה אשר מים אין לה׃ ");
INSERT INTO heb_vpl VALUES ("IS1_31","024_1_31","ISA","1","31","31","והיה החסן לנערת ופעלו לניצוץ ובערו שניהם יחדו ואין מכבה׃ ");
INSERT INTO heb_vpl VALUES ("IS2_1","024_2_1","ISA","2","1","1","הדבר אשר חזה ישעיהו בן אמוץ על יהודה וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS2_2","024_2_2","ISA","2","2","2","והיה באחרית הימים נכון יהיה הר בית יהוה בראש ההרים ונשא מגבעות ונהרו אליו כל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("IS2_3","024_2_3","ISA","2","3","3","והלכו עמים רבים ואמרו לכו ונעלה אל הר יהוה אל בית אלהי יעקב וירנו מדרכיו ונלכה בארחתיו כי מציון תצא תורה ודבר יהוה מירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS2_4","024_2_4","ISA","2","4","4","ושפט בין הגוים והוכיח לעמים רבים וכתתו חרבותם לאתים וחניתותיהם למזמרות לא ישא גוי אל גוי חרב ולא ילמדו עוד מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("IS2_5","024_2_5","ISA","2","5","5","בית יעקב לכו ונלכה באור יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS2_6","024_2_6","ISA","2","6","6","כי נטשתה עמך בית יעקב כי מלאו מקדם ועננים כפלשתים ובילדי נכרים ישפיקו׃ ");
INSERT INTO heb_vpl VALUES ("IS2_7","024_2_7","ISA","2","7","7","ותמלא ארצו כסף וזהב ואין קצה לאצרתיו ותמלא ארצו סוסים ואין קצה למרכבתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS2_8","024_2_8","ISA","2","8","8","ותמלא ארצו אלילים למעשה ידיו ישתחוו לאשר עשו אצבעתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS2_9","024_2_9","ISA","2","9","9","וישח אדם וישפל איש ואל תשא להם׃ ");
INSERT INTO heb_vpl VALUES ("IS2_10","024_2_10","ISA","2","10","10","בוא בצור והטמן בעפר מפני פחד יהוה ומהדר גאנו׃ ");
INSERT INTO heb_vpl VALUES ("IS2_11","024_2_11","ISA","2","11","11","עיני גבהות אדם שפל ושח רום אנשים ונשגב יהוה לבדו ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("IS2_12","024_2_12","ISA","2","12","12","כי יום ליהוה צבאות על כל גאה ורם ועל כל נשא ושפל׃ ");
INSERT INTO heb_vpl VALUES ("IS2_13","024_2_13","ISA","2","13","13","ועל כל ארזי הלבנון הרמים והנשאים ועל כל אלוני הבשן׃ ");
INSERT INTO heb_vpl VALUES ("IS2_14","024_2_14","ISA","2","14","14","ועל כל ההרים הרמים ועל כל הגבעות הנשאות׃ ");
INSERT INTO heb_vpl VALUES ("IS2_15","024_2_15","ISA","2","15","15","ועל כל מגדל גבה ועל כל חומה בצורה׃ ");
INSERT INTO heb_vpl VALUES ("IS2_16","024_2_16","ISA","2","16","16","ועל כל אניות תרשיש ועל כל שכיות החמדה׃ ");
INSERT INTO heb_vpl VALUES ("IS2_17","024_2_17","ISA","2","17","17","ושח גבהות האדם ושפל רום אנשים ונשגב יהוה לבדו ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("IS2_18","024_2_18","ISA","2","18","18","והאלילים כליל יחלף׃ ");
INSERT INTO heb_vpl VALUES ("IS2_19","024_2_19","ISA","2","19","19","ובאו במערות צרים ובמחלות עפר מפני פחד יהוה ומהדר גאונו בקומו לערץ הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS2_20","024_2_20","ISA","2","20","20","ביום ההוא ישליך האדם את אלילי כספו ואת אלילי זהבו אשר עשו לו להשתחות לחפר פרות ולעטלפים׃ ");
INSERT INTO heb_vpl VALUES ("IS2_21","024_2_21","ISA","2","21","21","לבוא בנקרות הצרים ובסעפי הסלעים מפני פחד יהוה ומהדר גאונו בקומו לערץ הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS2_22","024_2_22","ISA","2","22","22","חדלו לכם מן האדם אשר נשמה באפו כי במה נחשב הוא׃ ");
INSERT INTO heb_vpl VALUES ("IS3_1","024_3_1","ISA","3","1","1","כי הנה האדון יהוה צבאות מסיר מירושלם ומיהודה משען ומשענה כל משען לחם וכל משען מים׃ ");
INSERT INTO heb_vpl VALUES ("IS3_2","024_3_2","ISA","3","2","2","גבור ואיש מלחמה שופט ונביא וקסם וזקן׃ ");
INSERT INTO heb_vpl VALUES ("IS3_3","024_3_3","ISA","3","3","3","שר חמשים ונשוא פנים ויועץ וחכם חרשים ונבון לחש׃ ");
INSERT INTO heb_vpl VALUES ("IS3_4","024_3_4","ISA","3","4","4","ונתתי נערים שריהם ותעלולים ימשלו בם׃ ");
INSERT INTO heb_vpl VALUES ("IS3_5","024_3_5","ISA","3","5","5","ונגש העם איש באיש ואיש ברעהו ירהבו הנער בזקן והנקלה בנכבד׃ ");
INSERT INTO heb_vpl VALUES ("IS3_6","024_3_6","ISA","3","6","6","כי יתפש איש באחיו בית אביו שמלה לכה קצין תהיה לנו והמכשלה הזאת תחת ידך׃ ");
INSERT INTO heb_vpl VALUES ("IS3_7","024_3_7","ISA","3","7","7","ישא ביום ההוא לאמר לא אהיה חבש ובביתי אין לחם ואין שמלה לא תשימני קצין עם׃ ");
INSERT INTO heb_vpl VALUES ("IS3_8","024_3_8","ISA","3","8","8","כי כשלה ירושלם ויהודה נפל כי לשונם ומעלליהם אל יהוה למרות עני כבודו׃ ");
INSERT INTO heb_vpl VALUES ("IS3_9","024_3_9","ISA","3","9","9","הכרת פניהם ענתה בם וחטאתם כסדם הגידו לא כחדו אוי לנפשם כי גמלו להם רעה׃ ");
INSERT INTO heb_vpl VALUES ("IS3_10","024_3_10","ISA","3","10","10","אמרו צדיק כי טוב כי פרי מעלליהם יאכלו׃ ");
INSERT INTO heb_vpl VALUES ("IS3_11","024_3_11","ISA","3","11","11","אוי לרשע רע כי גמול ידיו יעשה לו׃ ");
INSERT INTO heb_vpl VALUES ("IS3_12","024_3_12","ISA","3","12","12","עמי נגשיו מעולל ונשים משלו בו עמי מאשריך מתעים ודרך ארחתיך בלעו׃ ");
INSERT INTO heb_vpl VALUES ("IS3_13","024_3_13","ISA","3","13","13","נצב לריב יהוה ועמד לדין עמים׃ ");
INSERT INTO heb_vpl VALUES ("IS3_14","024_3_14","ISA","3","14","14","יהוה במשפט יבוא עם זקני עמו ושריו ואתם בערתם הכרם גזלת העני בבתיכם׃ ");
INSERT INTO heb_vpl VALUES ("IS3_15","024_3_15","ISA","3","15","15","מלכם תדכאו עמי ופני עניים תטחנו נאם אדני יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("IS3_16","024_3_16","ISA","3","16","16","ויאמר יהוה יען כי גבהו בנות ציון ותלכנה נטוות גרון ומשקרות עינים הלוך וטפוף תלכנה וברגליהם תעכסנה׃ ");
INSERT INTO heb_vpl VALUES ("IS3_17","024_3_17","ISA","3","17","17","ושפח אדני קדקד בנות ציון ויהוה פתהן יערה׃ ");
INSERT INTO heb_vpl VALUES ("IS3_18","024_3_18","ISA","3","18","18","ביום ההוא יסיר אדני את תפארת העכסים והשביסים והשהרנים׃ ");
INSERT INTO heb_vpl VALUES ("IS3_19","024_3_19","ISA","3","19","19","הנטפות והשרות והרעלות׃ ");
INSERT INTO heb_vpl VALUES ("IS3_20","024_3_20","ISA","3","20","20","הפארים והצעדות והקשרים ובתי הנפש והלחשים׃ ");
INSERT INTO heb_vpl VALUES ("IS3_21","024_3_21","ISA","3","21","21","הטבעות ונזמי האף׃ ");
INSERT INTO heb_vpl VALUES ("IS3_22","024_3_22","ISA","3","22","22","המחלצות והמעטפות והמטפחות והחריטים׃ ");
INSERT INTO heb_vpl VALUES ("IS3_23","024_3_23","ISA","3","23","23","הגלינים והסדינים והצניפות והרדידים׃ ");
INSERT INTO heb_vpl VALUES ("IS3_24","024_3_24","ISA","3","24","24","והיה תחת בשם מק יהיה ותחת חגורה נקפה ותחת מעשה מקשה קרחה ותחת פתיגיל מחגרת שק כי תחת יפי׃ ");
INSERT INTO heb_vpl VALUES ("IS3_25","024_3_25","ISA","3","25","25","מתיך בחרב יפלו וגבורתך במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("IS3_26","024_3_26","ISA","3","26","26","ואנו ואבלו פתחיה ונקתה לארץ תשב׃ ");
INSERT INTO heb_vpl VALUES ("IS4_1","024_4_1","ISA","4","1","1","והחזיקו שבע נשים באיש אחד ביום ההוא לאמר לחמנו נאכל ושמלתנו נלבש רק יקרא שמך עלינו אסף חרפתנו׃ ");
INSERT INTO heb_vpl VALUES ("IS4_2","024_4_2","ISA","4","2","2","ביום ההוא יהיה צמח יהוה לצבי ולכבוד ופרי הארץ לגאון ולתפארת לפליטת ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS4_3","024_4_3","ISA","4","3","3","והיה הנשאר בציון והנותר בירושלם קדוש יאמר לו כל הכתוב לחיים בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS4_4","024_4_4","ISA","4","4","4","אם רחץ אדני את צאת בנות ציון ואת דמי ירושלם ידיח מקרבה ברוח משפט וברוח בער׃ ");
INSERT INTO heb_vpl VALUES ("IS4_5","024_4_5","ISA","4","5","5","וברא יהוה על כל מכון הר ציון ועל מקראה ענן יומם ועשן ונגה אש להבה לילה כי על כל כבוד חפה׃ ");
INSERT INTO heb_vpl VALUES ("IS4_6","024_4_6","ISA","4","6","6","וסכה תהיה לצל יומם מחרב ולמחסה ולמסתור מזרם וממטר׃ ");
INSERT INTO heb_vpl VALUES ("IS5_1","024_5_1","ISA","5","1","1","אשירה נא לידידי שירת דודי לכרמו כרם היה לידידי בקרן בן שמן׃ ");
INSERT INTO heb_vpl VALUES ("IS5_2","024_5_2","ISA","5","2","2","ויעזקהו ויסקלהו ויטעהו שרק ויבן מגדל בתוכו וגם יקב חצב בו ויקו לעשות ענבים ויעש באשים׃ ");
INSERT INTO heb_vpl VALUES ("IS5_3","024_5_3","ISA","5","3","3","ועתה יושב ירושלם ואיש יהודה שפטו נא ביני ובין כרמי׃ ");
INSERT INTO heb_vpl VALUES ("IS5_4","024_5_4","ISA","5","4","4","מה לעשות עוד לכרמי ולא עשיתי בו מדוע קויתי לעשות ענבים ויעש באשים׃ ");
INSERT INTO heb_vpl VALUES ("IS5_5","024_5_5","ISA","5","5","5","ועתה אודיעה נא אתכם את אשר אני עשה לכרמי הסר משוכתו והיה לבער פרץ גדרו והיה למרמס׃ ");
INSERT INTO heb_vpl VALUES ("IS5_6","024_5_6","ISA","5","6","6","ואשיתהו בתה לא יזמר ולא יעדר ועלה שמיר ושית ועל העבים אצוה מהמטיר עליו מטר׃ ");
INSERT INTO heb_vpl VALUES ("IS5_7","024_5_7","ISA","5","7","7","כי כרם יהוה צבאות בית ישראל ואיש יהודה נטע שעשועיו ויקו למשפט והנה משפח לצדקה והנה צעקה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_8","024_5_8","ISA","5","8","8","הוי מגיעי בית בבית שדה בשדה יקריבו עד אפס מקום והושבתם לבדכם בקרב הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS5_9","024_5_9","ISA","5","9","9","באזני יהוה צבאות אם לא בתים רבים לשמה יהיו גדלים וטובים מאין יושב׃ ");
INSERT INTO heb_vpl VALUES ("IS5_10","024_5_10","ISA","5","10","10","כי עשרת צמדי כרם יעשו בת אחת וזרע חמר יעשה איפה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_11","024_5_11","ISA","5","11","11","הוי משכימי בבקר שכר ירדפו מאחרי בנשף יין ידליקם׃ ");
INSERT INTO heb_vpl VALUES ("IS5_12","024_5_12","ISA","5","12","12","והיה כנור ונבל תף וחליל ויין משתיהם ואת פעל יהוה לא יביטו ומעשה ידיו לא ראו׃ ");
INSERT INTO heb_vpl VALUES ("IS5_13","024_5_13","ISA","5","13","13","לכן גלה עמי מבלי דעת וכבודו מתי רעב והמונו צחה צמא׃ ");
INSERT INTO heb_vpl VALUES ("IS5_14","024_5_14","ISA","5","14","14","לכן הרחיבה שאול נפשה ופערה פיה לבלי חק וירד הדרה והמונה ושאונה ועלז בה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_15","024_5_15","ISA","5","15","15","וישח אדם וישפל איש ועיני גבהים תשפלנה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_16","024_5_16","ISA","5","16","16","ויגבה יהוה צבאות במשפט והאל הקדוש נקדש בצדקה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_17","024_5_17","ISA","5","17","17","ורעו כבשים כדברם וחרבות מחים גרים יאכלו׃ ");
INSERT INTO heb_vpl VALUES ("IS5_18","024_5_18","ISA","5","18","18","הוי משכי העון בחבלי השוא וכעבות העגלה חטאה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_19","024_5_19","ISA","5","19","19","האמרים ימהר יחישה מעשהו למען נראה ותקרב ותבואה עצת קדוש ישראל ונדעה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_20","024_5_20","ISA","5","20","20","הוי האמרים לרע טוב ולטוב רע שמים חשך לאור ואור לחשך שמים מר למתוק ומתוק למר׃ ");
INSERT INTO heb_vpl VALUES ("IS5_21","024_5_21","ISA","5","21","21","הוי חכמים בעיניהם ונגד פניהם נבנים׃ ");
INSERT INTO heb_vpl VALUES ("IS5_22","024_5_22","ISA","5","22","22","הוי גבורים לשתות יין ואנשי חיל למסך שכר׃ ");
INSERT INTO heb_vpl VALUES ("IS5_23","024_5_23","ISA","5","23","23","מצדיקי רשע עקב שחד וצדקת צדיקים יסירו ממנו׃ ");
INSERT INTO heb_vpl VALUES ("IS5_24","024_5_24","ISA","5","24","24","לכן כאכל קש לשון אש וחשש להבה ירפה שרשם כמק יהיה ופרחם כאבק יעלה כי מאסו את תורת יהוה צבאות ואת אמרת קדוש ישראל נאצו׃ ");
INSERT INTO heb_vpl VALUES ("IS5_25","024_5_25","ISA","5","25","25","על כן חרה אף יהוה בעמו ויט ידו עליו ויכהו וירגזו ההרים ותהי נבלתם כסוחה בקרב חוצות בכל זאת לא שב אפו ועוד ידו נטויה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_26","024_5_26","ISA","5","26","26","ונשא נס לגוים מרחוק ושרק לו מקצה הארץ והנה מהרה קל יבוא׃ ");
INSERT INTO heb_vpl VALUES ("IS5_27","024_5_27","ISA","5","27","27","אין עיף ואין כושל בו לא ינום ולא יישן ולא נפתח אזור חלציו ולא נתק שרוך נעליו׃ ");
INSERT INTO heb_vpl VALUES ("IS5_28","024_5_28","ISA","5","28","28","אשר חציו שנונים וכל קשתתיו דרכות פרסות סוסיו כצר נחשבו וגלגליו כסופה׃ ");
INSERT INTO heb_vpl VALUES ("IS5_29","024_5_29","ISA","5","29","29","שאגה לו כלביא ושאג ככפירים וינהם ויאחז טרף ויפליט ואין מציל׃ ");
INSERT INTO heb_vpl VALUES ("IS5_30","024_5_30","ISA","5","30","30","וינהם עליו ביום ההוא כנהמת ים ונבט לארץ והנה חשך צר ואור חשך בעריפיה׃ ");
INSERT INTO heb_vpl VALUES ("IS6_1","024_6_1","ISA","6","1","1","בשנת מות המלך עזיהו ואראה את אדני ישב על כסא רם ונשא ושוליו מלאים את ההיכל׃ ");
INSERT INTO heb_vpl VALUES ("IS6_2","024_6_2","ISA","6","2","2","שרפים עמדים ממעל לו שש כנפים שש כנפים לאחד בשתים יכסה פניו ובשתים יכסה רגליו ובשתים יעופף׃ ");
INSERT INTO heb_vpl VALUES ("IS6_3","024_6_3","ISA","6","3","3","וקרא זה אל זה ואמר קדוש קדוש קדוש יהוה צבאות מלא כל הארץ כבודו׃ ");
INSERT INTO heb_vpl VALUES ("IS6_4","024_6_4","ISA","6","4","4","וינעו אמות הספים מקול הקורא והבית ימלא עשן׃ ");
INSERT INTO heb_vpl VALUES ("IS6_5","024_6_5","ISA","6","5","5","ואמר אוי לי כי נדמיתי כי איש טמא שפתים אנכי ובתוך עם טמא שפתים אנכי יושב כי את המלך יהוה צבאות ראו עיני׃ ");
INSERT INTO heb_vpl VALUES ("IS6_6","024_6_6","ISA","6","6","6","ויעף אלי אחד מן השרפים ובידו רצפה במלקחים לקח מעל המזבח׃ ");
INSERT INTO heb_vpl VALUES ("IS6_7","024_6_7","ISA","6","7","7","ויגע על פי ויאמר הנה נגע זה על שפתיך וסר עונך וחטאתך תכפר׃ ");
INSERT INTO heb_vpl VALUES ("IS6_8","024_6_8","ISA","6","8","8","ואשמע את קול אדני אמר את מי אשלח ומי ילך לנו ואמר הנני שלחני׃ ");
INSERT INTO heb_vpl VALUES ("IS6_9","024_6_9","ISA","6","9","9","ויאמר לך ואמרת לעם הזה שמעו שמוע ואל תבינו וראו ראו ואל תדעו׃ ");
INSERT INTO heb_vpl VALUES ("IS6_10","024_6_10","ISA","6","10","10","השמן לב העם הזה ואזניו הכבד ועיניו השע פן יראה בעיניו ובאזניו ישמע ולבבו יבין ושב ורפא לו׃ ");
INSERT INTO heb_vpl VALUES ("IS6_11","024_6_11","ISA","6","11","11","ואמר עד מתי אדני ויאמר עד אשר אם שאו ערים מאין יושב ובתים מאין אדם והאדמה תשאה שממה׃ ");
INSERT INTO heb_vpl VALUES ("IS6_12","024_6_12","ISA","6","12","12","ורחק יהוה את האדם ורבה העזובה בקרב הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS6_13","024_6_13","ISA","6","13","13","ועוד בה עשריה ושבה והיתה לבער כאלה וכאלון אשר בשלכת מצבת בם זרע קדש מצבתה׃ ");
INSERT INTO heb_vpl VALUES ("IS7_1","024_7_1","ISA","7","1","1","ויהי בימי אחז בן יותם בן עזיהו מלך יהודה עלה רצין מלך ארם ופקח בן רמליהו מלך ישראל ירושלם למלחמה עליה ולא יכל להלחם עליה׃ ");
INSERT INTO heb_vpl VALUES ("IS7_2","024_7_2","ISA","7","2","2","ויגד לבית דוד לאמר נחה ארם על אפרים וינע לבבו ולבב עמו כנוע עצי יער מפני רוח׃ ");
INSERT INTO heb_vpl VALUES ("IS7_3","024_7_3","ISA","7","3","3","ויאמר יהוה אל ישעיהו צא נא לקראת אחז אתה ושאר ישוב בנך אל קצה תעלת הברכה העליונה אל מסלת שדה כובס׃ ");
INSERT INTO heb_vpl VALUES ("IS7_4","024_7_4","ISA","7","4","4","ואמרת אליו השמר והשקט אל תירא ולבבך אל ירך משני זנבות האודים העשנים האלה בחרי אף רצין וארם ובן רמליהו׃ ");
INSERT INTO heb_vpl VALUES ("IS7_5","024_7_5","ISA","7","5","5","יען כי יעץ עליך ארם רעה אפרים ובן רמליהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("IS7_6","024_7_6","ISA","7","6","6","נעלה ביהודה ונקיצנה ונבקענה אלינו ונמליך מלך בתוכה את בן טבאל׃ ");
INSERT INTO heb_vpl VALUES ("IS7_7","024_7_7","ISA","7","7","7","כה אמר אדני יהוה לא תקום ולא תהיה׃ ");
INSERT INTO heb_vpl VALUES ("IS7_8","024_7_8","ISA","7","8","8","כי ראש ארם דמשק וראש דמשק רצין ובעוד ששים וחמש שנה יחת אפרים מעם׃ ");
INSERT INTO heb_vpl VALUES ("IS7_9","024_7_9","ISA","7","9","9","וראש אפרים שמרון וראש שמרון בן רמליהו אם לא תאמינו כי לא תאמנו׃ ");
INSERT INTO heb_vpl VALUES ("IS7_10","024_7_10","ISA","7","10","10","ויוסף יהוה דבר אל אחז לאמר׃ ");
INSERT INTO heb_vpl VALUES ("IS7_11","024_7_11","ISA","7","11","11","שאל לך אות מעם יהוה אלהיך העמק שאלה או הגבה למעלה׃ ");
INSERT INTO heb_vpl VALUES ("IS7_12","024_7_12","ISA","7","12","12","ויאמר אחז לא אשאל ולא אנסה את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS7_13","024_7_13","ISA","7","13","13","ויאמר שמעו נא בית דוד המעט מכם הלאות אנשים כי תלאו גם את אלהי׃ ");
INSERT INTO heb_vpl VALUES ("IS7_14","024_7_14","ISA","7","14","14","לכן יתן אדני הוא לכם אות הנה העלמה הרה וילדת בן וקראת שמו עמנו אל׃ ");
INSERT INTO heb_vpl VALUES ("IS7_15","024_7_15","ISA","7","15","15","חמאה ודבש יאכל לדעתו מאוס ברע ובחור בטוב׃ ");
INSERT INTO heb_vpl VALUES ("IS7_16","024_7_16","ISA","7","16","16","כי בטרם ידע הנער מאס ברע ובחר בטוב תעזב האדמה אשר אתה קץ מפני שני מלכיה׃ ");
INSERT INTO heb_vpl VALUES ("IS7_17","024_7_17","ISA","7","17","17","יביא יהוה עליך ועל עמך ועל בית אביך ימים אשר לא באו למיום סור אפרים מעל יהודה את מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS7_18","024_7_18","ISA","7","18","18","והיה ביום ההוא ישרק יהוה לזבוב אשר בקצה יארי מצרים ולדבורה אשר בארץ אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS7_19","024_7_19","ISA","7","19","19","ובאו ונחו כלם בנחלי הבתות ובנקיקי הסלעים ובכל הנעצוצים ובכל הנהללים׃ ");
INSERT INTO heb_vpl VALUES ("IS7_20","024_7_20","ISA","7","20","20","ביום ההוא יגלח אדני בתער השכירה בעברי נהר במלך אשור את הראש ושער הרגלים וגם את הזקן תספה׃ ");
INSERT INTO heb_vpl VALUES ("IS7_21","024_7_21","ISA","7","21","21","והיה ביום ההוא יחיה איש עגלת בקר ושתי צאן׃ ");
INSERT INTO heb_vpl VALUES ("IS7_22","024_7_22","ISA","7","22","22","והיה מרב עשות חלב יאכל חמאה כי חמאה ודבש יאכל כל הנותר בקרב הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS7_23","024_7_23","ISA","7","23","23","והיה ביום ההוא יהיה כל מקום אשר יהיה שם אלף גפן באלף כסף לשמיר ולשית יהיה׃ ");
INSERT INTO heb_vpl VALUES ("IS7_24","024_7_24","ISA","7","24","24","בחצים ובקשת יבוא שמה כי שמיר ושית תהיה כל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS7_25","024_7_25","ISA","7","25","25","וכל ההרים אשר במעדר יעדרון לא תבוא שמה יראת שמיר ושית והיה למשלח שור ולמרמס שה׃ ");
INSERT INTO heb_vpl VALUES ("IS8_1","024_8_1","ISA","8","1","1","ויאמר יהוה אלי קח לך גליון גדול וכתב עליו בחרט אנוש למהר שלל חש בז׃ ");
INSERT INTO heb_vpl VALUES ("IS8_2","024_8_2","ISA","8","2","2","ואעידה לי עדים נאמנים את אוריה הכהן ואת זכריהו בן יברכיהו׃ ");
INSERT INTO heb_vpl VALUES ("IS8_3","024_8_3","ISA","8","3","3","ואקרב אל הנביאה ותהר ותלד בן ויאמר יהוה אלי קרא שמו מהר שלל חש בז׃ ");
INSERT INTO heb_vpl VALUES ("IS8_4","024_8_4","ISA","8","4","4","כי בטרם ידע הנער קרא אבי ואמי ישא את חיל דמשק ואת שלל שמרון לפני מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS8_5","024_8_5","ISA","8","5","5","ויסף יהוה דבר אלי עוד לאמר׃ ");
INSERT INTO heb_vpl VALUES ("IS8_6","024_8_6","ISA","8","6","6","יען כי מאס העם הזה את מי השלח ההלכים לאט ומשוש את רצין ובן רמליהו׃ ");
INSERT INTO heb_vpl VALUES ("IS8_7","024_8_7","ISA","8","7","7","ולכן הנה אדני מעלה עליהם את מי הנהר העצומים והרבים את מלך אשור ואת כל כבודו ועלה על כל אפיקיו והלך על כל גדותיו׃ ");
INSERT INTO heb_vpl VALUES ("IS8_8","024_8_8","ISA","8","8","8","וחלף ביהודה שטף ועבר עד צואר יגיע והיה מטות כנפיו מלא רחב ארצך עמנו אל׃ ");
INSERT INTO heb_vpl VALUES ("IS8_9","024_8_9","ISA","8","9","9","רעו עמים וחתו והאזינו כל מרחקי ארץ התאזרו וחתו התאזרו וחתו׃ ");
INSERT INTO heb_vpl VALUES ("IS8_10","024_8_10","ISA","8","10","10","עצו עצה ותפר דברו דבר ולא יקום כי עמנו אל׃ ");
INSERT INTO heb_vpl VALUES ("IS8_11","024_8_11","ISA","8","11","11","כי כה אמר יהוה אלי בחזקת היד ויסרני מלכת בדרך העם הזה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("IS8_12","024_8_12","ISA","8","12","12","לא תאמרון קשר לכל אשר יאמר העם הזה קשר ואת מוראו לא תיראו ולא תעריצו׃ ");
INSERT INTO heb_vpl VALUES ("IS8_13","024_8_13","ISA","8","13","13","את יהוה צבאות אתו תקדישו והוא מוראכם והוא מערצכם׃ ");
INSERT INTO heb_vpl VALUES ("IS8_14","024_8_14","ISA","8","14","14","והיה למקדש ולאבן נגף ולצור מכשול לשני בתי ישראל לפח ולמוקש ליושב ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS8_15","024_8_15","ISA","8","15","15","וכשלו בם רבים ונפלו ונשברו ונוקשו ונלכדו׃ ");
INSERT INTO heb_vpl VALUES ("IS8_16","024_8_16","ISA","8","16","16","צור תעודה חתום תורה בלמדי׃ ");
INSERT INTO heb_vpl VALUES ("IS8_17","024_8_17","ISA","8","17","17","וחכיתי ליהוה המסתיר פניו מבית יעקב וקויתי לו׃ ");
INSERT INTO heb_vpl VALUES ("IS8_18","024_8_18","ISA","8","18","18","הנה אנכי והילדים אשר נתן לי יהוה לאתות ולמופתים בישראל מעם יהוה צבאות השכן בהר ציון׃ ");
INSERT INTO heb_vpl VALUES ("IS8_19","024_8_19","ISA","8","19","19","וכי יאמרו אליכם דרשו אל האבות ואל הידענים המצפצפים והמהגים הלוא עם אל אלהיו ידרש בעד החיים אל המתים׃ ");
INSERT INTO heb_vpl VALUES ("IS8_20","024_8_20","ISA","8","20","20","לתורה ולתעודה אם לא יאמרו כדבר הזה אשר אין לו שחר׃ ");
INSERT INTO heb_vpl VALUES ("IS8_21","024_8_21","ISA","8","21","21","ועבר בה נקשה ורעב והיה כי ירעב והתקצף וקלל במלכו ובאלהיו ופנה למעלה׃ ");
INSERT INTO heb_vpl VALUES ("IS8_22","024_8_22","ISA","8","22","22","ואל ארץ יביט והנה צרה וחשכה מעוף צוקה ואפלה מנדח׃ ");
INSERT INTO heb_vpl VALUES ("IS9_1","024_9_1","ISA","9","1","1","כי לא מועף לאשר מוצק לה כעת הראשון הקל ארצה זבלון וארצה נפתלי והאחרון הכביד דרך הים עבר הירדן גליל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("IS9_2","024_9_2","ISA","9","2","2","העם ההלכים בחשך ראו אור גדול ישבי בארץ צלמות אור נגה עליהם׃ ");
INSERT INTO heb_vpl VALUES ("IS9_3","024_9_3","ISA","9","3","3","הרבית הגוי לא הגדלת השמחה שמחו לפניך כשמחת בקציר כאשר יגילו בחלקם שלל׃ ");
INSERT INTO heb_vpl VALUES ("IS9_4","024_9_4","ISA","9","4","4","כי את על סבלו ואת מטה שכמו שבט הנגש בו החתת כיום מדין׃ ");
INSERT INTO heb_vpl VALUES ("IS9_5","024_9_5","ISA","9","5","5","כי כל סאון סאן ברעש ושמלה מגוללה בדמים והיתה לשרפה מאכלת אש׃ ");
INSERT INTO heb_vpl VALUES ("IS9_6","024_9_6","ISA","9","6","6","כי ילד ילד לנו בן נתן לנו ותהי המשרה על שכמו ויקרא שמו פלא יועץ אל גבור אביעד שר שלום׃ ");
INSERT INTO heb_vpl VALUES ("IS9_7","024_9_7","ISA","9","7","7","למרבה המשרה ולשלום אין קץ על כסא דוד ועל ממלכתו להכין אתה ולסעדה במשפט ובצדקה מעתה ועד עולם קנאת יהוה צבאות תעשה זאת׃ ");
INSERT INTO heb_vpl VALUES ("IS9_8","024_9_8","ISA","9","8","8","דבר שלח אדני ביעקב ונפל בישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS9_9","024_9_9","ISA","9","9","9","וידעו העם כלו אפרים ויושב שמרון בגאוה ובגדל לבב לאמר׃ ");
INSERT INTO heb_vpl VALUES ("IS9_10","024_9_10","ISA","9","10","10","לבנים נפלו וגזית נבנה שקמים גדעו וארזים נחליף׃ ");
INSERT INTO heb_vpl VALUES ("IS9_11","024_9_11","ISA","9","11","11","וישגב יהוה את צרי רצין עליו ואת איביו יסכסך׃ ");
INSERT INTO heb_vpl VALUES ("IS9_12","024_9_12","ISA","9","12","12","ארם מקדם ופלשתים מאחור ויאכלו את ישראל בכל פה בכל זאת לא שב אפו ועוד ידו נטויה׃ ");
INSERT INTO heb_vpl VALUES ("IS9_13","024_9_13","ISA","9","13","13","והעם לא שב עד המכהו ואת יהוה צבאות לא דרשו׃ ");
INSERT INTO heb_vpl VALUES ("IS9_14","024_9_14","ISA","9","14","14","ויכרת יהוה מישראל ראש וזנב כפה ואגמון יום אחד׃ ");
INSERT INTO heb_vpl VALUES ("IS9_15","024_9_15","ISA","9","15","15","זקן ונשוא פנים הוא הראש ונביא מורה שקר הוא הזנב׃ ");
INSERT INTO heb_vpl VALUES ("IS9_16","024_9_16","ISA","9","16","16","ויהיו מאשרי העם הזה מתעים ומאשריו מבלעים׃ ");
INSERT INTO heb_vpl VALUES ("IS9_17","024_9_17","ISA","9","17","17","על כן על בחוריו לא ישמח אדני ואת יתמיו ואת אלמנתיו לא ירחם כי כלו חנף ומרע וכל פה דבר נבלה בכל זאת לא שב אפו ועוד ידו נטויה׃ ");
INSERT INTO heb_vpl VALUES ("IS9_18","024_9_18","ISA","9","18","18","כי בערה כאש רשעה שמיר ושית תאכל ותצת בסבכי היער ויתאבכו גאות עשן׃ ");
INSERT INTO heb_vpl VALUES ("IS9_19","024_9_19","ISA","9","19","19","בעברת יהוה צבאות נעתם ארץ ויהי העם כמאכלת אש איש אל אחיו לא יחמלו׃ ");
INSERT INTO heb_vpl VALUES ("IS9_20","024_9_20","ISA","9","20","20","ויגזר על ימין ורעב ויאכל על שמאול ולא שבעו איש בשר זרעו יאכלו׃ ");
INSERT INTO heb_vpl VALUES ("IS9_21","024_9_21","ISA","9","21","21","מנשה את אפרים ואפרים את מנשה יחדו המה על יהודה בכל זאת לא שב אפו ועוד ידו נטויה׃ ");
INSERT INTO heb_vpl VALUES ("IS10_1","024_10_1","ISA","10","1","1","הוי החקקים חקקי און ומכתבים עמל כתבו׃ ");
INSERT INTO heb_vpl VALUES ("IS10_2","024_10_2","ISA","10","2","2","להטות מדין דלים ולגזל משפט עניי עמי להיות אלמנות שללם ואת יתומים יבזו׃ ");
INSERT INTO heb_vpl VALUES ("IS10_3","024_10_3","ISA","10","3","3","ומה תעשו ליום פקדה ולשואה ממרחק תבוא על מי תנוסו לעזרה ואנה תעזבו כבודכם׃ ");
INSERT INTO heb_vpl VALUES ("IS10_4","024_10_4","ISA","10","4","4","בלתי כרע תחת אסיר ותחת הרוגים יפלו בכל זאת לא שב אפו ועוד ידו נטויה׃ ");
INSERT INTO heb_vpl VALUES ("IS10_5","024_10_5","ISA","10","5","5","הוי אשור שבט אפי ומטה הוא בידם זעמי׃ ");
INSERT INTO heb_vpl VALUES ("IS10_6","024_10_6","ISA","10","6","6","בגוי חנף אשלחנו ועל עם עברתי אצונו לשלל שלל ולבז בז ולשימו מרמס כחמר חוצות׃ ");
INSERT INTO heb_vpl VALUES ("IS10_7","024_10_7","ISA","10","7","7","והוא לא כן ידמה ולבבו לא כן יחשב כי להשמיד בלבבו ולהכרית גוים לא מעט׃ ");
INSERT INTO heb_vpl VALUES ("IS10_8","024_10_8","ISA","10","8","8","כי יאמר הלא שרי יחדו מלכים׃ ");
INSERT INTO heb_vpl VALUES ("IS10_9","024_10_9","ISA","10","9","9","הלא ככרכמיש כלנו אם לא כארפד חמת אם לא כדמשק שמרון׃ ");
INSERT INTO heb_vpl VALUES ("IS10_10","024_10_10","ISA","10","10","10","כאשר מצאה ידי לממלכת האליל ופסיליהם מירושלם ומשמרון׃ ");
INSERT INTO heb_vpl VALUES ("IS10_11","024_10_11","ISA","10","11","11","הלא כאשר עשיתי לשמרון ולאליליה כן אעשה לירושלם ולעצביה׃ ");
INSERT INTO heb_vpl VALUES ("IS10_12","024_10_12","ISA","10","12","12","והיה כי יבצע אדני את כל מעשהו בהר ציון ובירושלם אפקד על פרי גדל לבב מלך אשור ועל תפארת רום עיניו׃ ");
INSERT INTO heb_vpl VALUES ("IS10_13","024_10_13","ISA","10","13","13","כי אמר בכח ידי עשיתי ובחכמתי כי נבנותי ואסיר גבולת עמים ועתידתיהם שושתי ואוריד כאביר יושבים׃ ");
INSERT INTO heb_vpl VALUES ("IS10_14","024_10_14","ISA","10","14","14","ותמצא כקן ידי לחיל העמים וכאסף ביצים עזבות כל הארץ אני אספתי ולא היה נדד כנף ופצה פה ומצפצף׃ ");
INSERT INTO heb_vpl VALUES ("IS10_15","024_10_15","ISA","10","15","15","היתפאר הגרזן על החצב בו אם יתגדל המשור על מניפו כהניף שבט את מרימיו כהרים מטה לא עץ׃ ");
INSERT INTO heb_vpl VALUES ("IS10_16","024_10_16","ISA","10","16","16","לכן ישלח האדון יהוה צבאות במשמניו רזון ותחת כבדו יקד יקד כיקוד אש׃ ");
INSERT INTO heb_vpl VALUES ("IS10_17","024_10_17","ISA","10","17","17","והיה אור ישראל לאש וקדושו ללהבה ובערה ואכלה שיתו ושמירו ביום אחד׃ ");
INSERT INTO heb_vpl VALUES ("IS10_18","024_10_18","ISA","10","18","18","וכבוד יערו וכרמלו מנפש ועד בשר יכלה והיה כמסס נסס׃ ");
INSERT INTO heb_vpl VALUES ("IS10_19","024_10_19","ISA","10","19","19","ושאר עץ יערו מספר יהיו ונער יכתבם׃ ");
INSERT INTO heb_vpl VALUES ("IS10_20","024_10_20","ISA","10","20","20","והיה ביום ההוא לא יוסיף עוד שאר ישראל ופליטת בית יעקב להשען על מכהו ונשען על יהוה קדוש ישראל באמת׃ ");
INSERT INTO heb_vpl VALUES ("IS10_21","024_10_21","ISA","10","21","21","שאר ישוב שאר יעקב אל אל גבור׃ ");
INSERT INTO heb_vpl VALUES ("IS10_22","024_10_22","ISA","10","22","22","כי אם יהיה עמך ישראל כחול הים שאר ישוב בו כליון חרוץ שוטף צדקה׃ ");
INSERT INTO heb_vpl VALUES ("IS10_23","024_10_23","ISA","10","23","23","כי כלה ונחרצה אדני יהוה צבאות עשה בקרב כל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS10_24","024_10_24","ISA","10","24","24","לכן כה אמר אדני יהוה צבאות אל תירא עמי ישב ציון מאשור בשבט יככה ומטהו ישא עליך בדרך מצרים׃ ");
INSERT INTO heb_vpl VALUES ("IS10_25","024_10_25","ISA","10","25","25","כי עוד מעט מזער וכלה זעם ואפי על תבליתם׃ ");
INSERT INTO heb_vpl VALUES ("IS10_26","024_10_26","ISA","10","26","26","ועורר עליו יהוה צבאות שוט כמכת מדין בצור עורב ומטהו על הים ונשאו בדרך מצרים׃ ");
INSERT INTO heb_vpl VALUES ("IS10_27","024_10_27","ISA","10","27","27","והיה ביום ההוא יסור סבלו מעל שכמך ועלו מעל צוארך וחבל על מפני שמן׃ ");
INSERT INTO heb_vpl VALUES ("IS10_28","024_10_28","ISA","10","28","28","בא על עית עבר במגרון למכמש יפקיד כליו׃ ");
INSERT INTO heb_vpl VALUES ("IS10_29","024_10_29","ISA","10","29","29","עברו מעברה גבע מלון לנו חרדה הרמה גבעת שאול נסה׃ ");
INSERT INTO heb_vpl VALUES ("IS10_30","024_10_30","ISA","10","30","30","צהלי קולך בת גלים הקשיבי לישה עניה ענתות׃ ");
INSERT INTO heb_vpl VALUES ("IS10_31","024_10_31","ISA","10","31","31","נדדה מדמנה ישבי הגבים העיזו׃ ");
INSERT INTO heb_vpl VALUES ("IS10_32","024_10_32","ISA","10","32","32","עוד היום בנב לעמד ינפף ידו הר בית ציון גבעת ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS10_33","024_10_33","ISA","10","33","33","הנה האדון יהוה צבאות מסעף פארה במערצה ורמי הקומה גדועים והגבהים ישפלו׃ ");
INSERT INTO heb_vpl VALUES ("IS10_34","024_10_34","ISA","10","34","34","ונקף סבכי היער בברזל והלבנון באדיר יפול׃ ");
INSERT INTO heb_vpl VALUES ("IS11_1","024_11_1","ISA","11","1","1","ויצא חטר מגזע ישי ונצר משרשיו יפרה׃ ");
INSERT INTO heb_vpl VALUES ("IS11_2","024_11_2","ISA","11","2","2","ונחה עליו רוח יהוה רוח חכמה ובינה רוח עצה וגבורה רוח דעת ויראת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS11_3","024_11_3","ISA","11","3","3","והריחו ביראת יהוה ולא למראה עיניו ישפוט ולא למשמע אזניו יוכיח׃ ");
INSERT INTO heb_vpl VALUES ("IS11_4","024_11_4","ISA","11","4","4","ושפט בצדק דלים והוכיח במישור לענוי ארץ והכה ארץ בשבט פיו וברוח שפתיו ימית רשע׃ ");
INSERT INTO heb_vpl VALUES ("IS11_5","024_11_5","ISA","11","5","5","והיה צדק אזור מתניו והאמונה אזור חלציו׃ ");
INSERT INTO heb_vpl VALUES ("IS11_6","024_11_6","ISA","11","6","6","וגר זאב עם כבש ונמר עם גדי ירבץ ועגל וכפיר ומריא יחדו ונער קטן נהג בם׃ ");
INSERT INTO heb_vpl VALUES ("IS11_7","024_11_7","ISA","11","7","7","ופרה ודב תרעינה יחדו ירבצו ילדיהן ואריה כבקר יאכל תבן׃ ");
INSERT INTO heb_vpl VALUES ("IS11_8","024_11_8","ISA","11","8","8","ושעשע יונק על חר פתן ועל מאורת צפעוני גמול ידו הדה׃ ");
INSERT INTO heb_vpl VALUES ("IS11_9","024_11_9","ISA","11","9","9","לא ירעו ולא ישחיתו בכל הר קדשי כי מלאה הארץ דעה את יהוה כמים לים מכסים׃ ");
INSERT INTO heb_vpl VALUES ("IS11_10","024_11_10","ISA","11","10","10","והיה ביום ההוא שרש ישי אשר עמד לנס עמים אליו גוים ידרשו והיתה מנחתו כבוד׃ ");
INSERT INTO heb_vpl VALUES ("IS11_11","024_11_11","ISA","11","11","11","והיה ביום ההוא יוסיף אדני שנית ידו לקנות את שאר עמו אשר ישאר מאשור וממצרים ומפתרוס ומכוש ומעילם ומשנער ומחמת ומאיי הים׃ ");
INSERT INTO heb_vpl VALUES ("IS11_12","024_11_12","ISA","11","12","12","ונשא נס לגוים ואסף נדחי ישראל ונפצות יהודה יקבץ מארבע כנפות הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS11_13","024_11_13","ISA","11","13","13","וסרה קנאת אפרים וצררי יהודה יכרתו אפרים לא יקנא את יהודה ויהודה לא יצר את אפרים׃ ");
INSERT INTO heb_vpl VALUES ("IS11_14","024_11_14","ISA","11","14","14","ועפו בכתף פלשתים ימה יחדו יבזו את בני קדם אדום ומואב משלוח ידם ובני עמון משמעתם׃ ");
INSERT INTO heb_vpl VALUES ("IS11_15","024_11_15","ISA","11","15","15","והחרים יהוה את לשון ים מצרים והניף ידו על הנהר בעים רוחו והכהו לשבעה נחלים והדריך בנעלים׃ ");
INSERT INTO heb_vpl VALUES ("IS11_16","024_11_16","ISA","11","16","16","והיתה מסלה לשאר עמו אשר ישאר מאשור כאשר היתה לישראל ביום עלתו מארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("IS12_1","024_12_1","ISA","12","1","1","ואמרת ביום ההוא אודך יהוה כי אנפת בי ישב אפך ותנחמני׃ ");
INSERT INTO heb_vpl VALUES ("IS12_2","024_12_2","ISA","12","2","2","הנה אל ישועתי אבטח ולא אפחד כי עזי וזמרת יה יהוה ויהי לי לישועה׃ ");
INSERT INTO heb_vpl VALUES ("IS12_3","024_12_3","ISA","12","3","3","ושאבתם מים בששון ממעיני הישועה׃ ");
INSERT INTO heb_vpl VALUES ("IS12_4","024_12_4","ISA","12","4","4","ואמרתם ביום ההוא הודו ליהוה קראו בשמו הודיעו בעמים עלילתיו הזכירו כי נשגב שמו׃ ");
INSERT INTO heb_vpl VALUES ("IS12_5","024_12_5","ISA","12","5","5","זמרו יהוה כי גאות עשה מידעת זאת בכל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS12_6","024_12_6","ISA","12","6","6","צהלי ורני יושבת ציון כי גדול בקרבך קדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS13_1","024_13_1","ISA","13","1","1","משא בבל אשר חזה ישעיהו בן אמוץ׃ ");
INSERT INTO heb_vpl VALUES ("IS13_2","024_13_2","ISA","13","2","2","על הר נשפה שאו נס הרימו קול להם הניפו יד ויבאו פתחי נדיבים׃ ");
INSERT INTO heb_vpl VALUES ("IS13_3","024_13_3","ISA","13","3","3","אני צויתי למקדשי גם קראתי גבורי לאפי עליזי גאותי׃ ");
INSERT INTO heb_vpl VALUES ("IS13_4","024_13_4","ISA","13","4","4","קול המון בהרים דמות עם רב קול שאון ממלכות גוים נאספים יהוה צבאות מפקד צבא מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("IS13_5","024_13_5","ISA","13","5","5","באים מארץ מרחק מקצה השמים יהוה וכלי זעמו לחבל כל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS13_6","024_13_6","ISA","13","6","6","הילילו כי קרוב יום יהוה כשד משדי יבוא׃ ");
INSERT INTO heb_vpl VALUES ("IS13_7","024_13_7","ISA","13","7","7","על כן כל ידים תרפינה וכל לבב אנוש ימס׃ ");
INSERT INTO heb_vpl VALUES ("IS13_8","024_13_8","ISA","13","8","8","ונבהלו צירים וחבלים יאחזון כיולדה יחילון איש אל רעהו יתמהו פני להבים פניהם׃ ");
INSERT INTO heb_vpl VALUES ("IS13_9","024_13_9","ISA","13","9","9","הנה יום יהוה בא אכזרי ועברה וחרון אף לשום הארץ לשמה וחטאיה ישמיד ממנה׃ ");
INSERT INTO heb_vpl VALUES ("IS13_10","024_13_10","ISA","13","10","10","כי כוכבי השמים וכסיליהם לא יהלו אורם חשך השמש בצאתו וירח לא יגיה אורו׃ ");
INSERT INTO heb_vpl VALUES ("IS13_11","024_13_11","ISA","13","11","11","ופקדתי על תבל רעה ועל רשעים עונם והשבתי גאון זדים וגאות עריצים אשפיל׃ ");
INSERT INTO heb_vpl VALUES ("IS13_12","024_13_12","ISA","13","12","12","אוקיר אנוש מפז ואדם מכתם אופיר׃ ");
INSERT INTO heb_vpl VALUES ("IS13_13","024_13_13","ISA","13","13","13","על כן שמים ארגיז ותרעש הארץ ממקומה בעברת יהוה צבאות וביום חרון אפו׃ ");
INSERT INTO heb_vpl VALUES ("IS13_14","024_13_14","ISA","13","14","14","והיה כצבי מדח וכצאן ואין מקבץ איש אל עמו יפנו ואיש אל ארצו ינוסו׃ ");
INSERT INTO heb_vpl VALUES ("IS13_15","024_13_15","ISA","13","15","15","כל הנמצא ידקר וכל הנספה יפול בחרב׃ ");
INSERT INTO heb_vpl VALUES ("IS13_16","024_13_16","ISA","13","16","16","ועלליהם ירטשו לעיניהם ישסו בתיהם ונשיהם תשגלנה׃ ");
INSERT INTO heb_vpl VALUES ("IS13_17","024_13_17","ISA","13","17","17","הנני מעיר עליהם את מדי אשר כסף לא יחשבו וזהב לא יחפצו בו׃ ");
INSERT INTO heb_vpl VALUES ("IS13_18","024_13_18","ISA","13","18","18","וקשתות נערים תרטשנה ופרי בטן לא ירחמו על בנים לא תחוס עינם׃ ");
INSERT INTO heb_vpl VALUES ("IS13_19","024_13_19","ISA","13","19","19","והיתה בבל צבי ממלכות תפארת גאון כשדים כמהפכת אלהים את סדם ואת עמרה׃ ");
INSERT INTO heb_vpl VALUES ("IS13_20","024_13_20","ISA","13","20","20","לא תשב לנצח ולא תשכן עד דור ודור ולא יהל שם ערבי ורעים לא ירבצו שם׃ ");
INSERT INTO heb_vpl VALUES ("IS13_21","024_13_21","ISA","13","21","21","ורבצו שם ציים ומלאו בתיהם אחים ושכנו שם בנות יענה ושעירים ירקדו שם׃ ");
INSERT INTO heb_vpl VALUES ("IS13_22","024_13_22","ISA","13","22","22","וענה איים באלמנותיו ותנים בהיכלי ענג וקרוב לבוא עתה וימיה לא ימשכו׃ ");
INSERT INTO heb_vpl VALUES ("IS14_1","024_14_1","ISA","14","1","1","כי ירחם יהוה את יעקב ובחר עוד בישראל והניחם על אדמתם ונלוה הגר עליהם ונספחו על בית יעקב׃ ");
INSERT INTO heb_vpl VALUES ("IS14_2","024_14_2","ISA","14","2","2","ולקחום עמים והביאום אל מקומם והתנחלום בית ישראל על אדמת יהוה לעבדים ולשפחות והיו שבים לשביהם ורדו בנגשיהם׃ ");
INSERT INTO heb_vpl VALUES ("IS14_3","024_14_3","ISA","14","3","3","והיה ביום הניח יהוה לך מעצבך ומרגזך ומן העבדה הקשה אשר עבד בך׃ ");
INSERT INTO heb_vpl VALUES ("IS14_4","024_14_4","ISA","14","4","4","ונשאת המשל הזה על מלך בבל ואמרת איך שבת נגש שבתה מדהבה׃ ");
INSERT INTO heb_vpl VALUES ("IS14_5","024_14_5","ISA","14","5","5","שבר יהוה מטה רשעים שבט משלים׃ ");
INSERT INTO heb_vpl VALUES ("IS14_6","024_14_6","ISA","14","6","6","מכה עמים בעברה מכת בלתי סרה רדה באף גוים מרדף בלי חשך׃ ");
INSERT INTO heb_vpl VALUES ("IS14_7","024_14_7","ISA","14","7","7","נחה שקטה כל הארץ פצחו רנה׃ ");
INSERT INTO heb_vpl VALUES ("IS14_8","024_14_8","ISA","14","8","8","גם ברושים שמחו לך ארזי לבנון מאז שכבת לא יעלה הכרת עלינו׃ ");
INSERT INTO heb_vpl VALUES ("IS14_9","024_14_9","ISA","14","9","9","שאול מתחת רגזה לך לקראת בואך עורר לך רפאים כל עתודי ארץ הקים מכסאותם כל מלכי גוים׃ ");
INSERT INTO heb_vpl VALUES ("IS14_10","024_14_10","ISA","14","10","10","כלם יענו ויאמרו אליך גם אתה חלית כמונו אלינו נמשלת׃ ");
INSERT INTO heb_vpl VALUES ("IS14_11","024_14_11","ISA","14","11","11","הורד שאול גאונך המית נבליך תחתיך יצע רמה ומכסיך תולעה׃ ");
INSERT INTO heb_vpl VALUES ("IS14_12","024_14_12","ISA","14","12","12","איך נפלת משמים הילל בן שחר נגדעת לארץ חולש על גוים׃ ");
INSERT INTO heb_vpl VALUES ("IS14_13","024_14_13","ISA","14","13","13","ואתה אמרת בלבבך השמים אעלה ממעל לכוכבי אל ארים כסאי ואשב בהר מועד בירכתי צפון׃ ");
INSERT INTO heb_vpl VALUES ("IS14_14","024_14_14","ISA","14","14","14","אעלה על במתי עב אדמה לעליון׃ ");
INSERT INTO heb_vpl VALUES ("IS14_15","024_14_15","ISA","14","15","15","אך אל שאול תורד אל ירכתי בור׃ ");
INSERT INTO heb_vpl VALUES ("IS14_16","024_14_16","ISA","14","16","16","ראיך אליך ישגיחו אליך יתבוננו הזה האיש מרגיז הארץ מרעיש ממלכות׃ ");
INSERT INTO heb_vpl VALUES ("IS14_17","024_14_17","ISA","14","17","17","שם תבל כמדבר ועריו הרס אסיריו לא פתח ביתה׃ ");
INSERT INTO heb_vpl VALUES ("IS14_18","024_14_18","ISA","14","18","18","כל מלכי גוים כלם שכבו בכבוד איש בביתו׃ ");
INSERT INTO heb_vpl VALUES ("IS14_19","024_14_19","ISA","14","19","19","ואתה השלכת מקברך כנצר נתעב לבוש הרגים מטעני חרב יורדי אל אבני בור כפגר מובס׃ ");
INSERT INTO heb_vpl VALUES ("IS14_20","024_14_20","ISA","14","20","20","לא תחד אתם בקבורה כי ארצך שחת עמך הרגת לא יקרא לעולם זרע מרעים׃ ");
INSERT INTO heb_vpl VALUES ("IS14_21","024_14_21","ISA","14","21","21","הכינו לבניו מטבח בעון אבותם בל יקמו וירשו ארץ ומלאו פני תבל ערים׃ ");
INSERT INTO heb_vpl VALUES ("IS14_22","024_14_22","ISA","14","22","22","וקמתי עליהם נאם יהוה צבאות והכרתי לבבל שם ושאר ונין ונכד נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS14_23","024_14_23","ISA","14","23","23","ושמתיה למורש קפד ואגמי מים וטאטאתיה במטאטא השמד נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("IS14_24","024_14_24","ISA","14","24","24","נשבע יהוה צבאות לאמר אם לא כאשר דמיתי כן היתה וכאשר יעצתי היא תקום׃ ");
INSERT INTO heb_vpl VALUES ("IS14_25","024_14_25","ISA","14","25","25","לשבר אשור בארצי ועל הרי אבוסנו וסר מעליהם עלו וסבלו מעל שכמו יסור׃ ");
INSERT INTO heb_vpl VALUES ("IS14_26","024_14_26","ISA","14","26","26","זאת העצה היעוצה על כל הארץ וזאת היד הנטויה על כל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("IS14_27","024_14_27","ISA","14","27","27","כי יהוה צבאות יעץ ומי יפר וידו הנטויה ומי ישיבנה׃ ");
INSERT INTO heb_vpl VALUES ("IS14_28","024_14_28","ISA","14","28","28","בשנת מות המלך אחז היה המשא הזה׃ ");
INSERT INTO heb_vpl VALUES ("IS14_29","024_14_29","ISA","14","29","29","אל תשמחי פלשת כלך כי נשבר שבט מכך כי משרש נחש יצא צפע ופריו שרף מעופף׃ ");
INSERT INTO heb_vpl VALUES ("IS14_30","024_14_30","ISA","14","30","30","ורעו בכורי דלים ואביונים לבטח ירבצו והמתי ברעב שרשך ושאריתך יהרג׃ ");
INSERT INTO heb_vpl VALUES ("IS14_31","024_14_31","ISA","14","31","31","הילילי שער זעקי עיר נמוג פלשת כלך כי מצפון עשן בא ואין בודד במועדיו׃ ");
INSERT INTO heb_vpl VALUES ("IS14_32","024_14_32","ISA","14","32","32","ומה יענה מלאכי גוי כי יהוה יסד ציון ובה יחסו עניי עמו׃ ");
INSERT INTO heb_vpl VALUES ("IS15_1","024_15_1","ISA","15","1","1","משא מואב כי בליל שדד ער מואב נדמה כי בליל שדד קיר מואב נדמה׃ ");
INSERT INTO heb_vpl VALUES ("IS15_2","024_15_2","ISA","15","2","2","עלה הבית ודיבן הבמות לבכי על נבו ועל מידבא מואב ייליל בכל ראשיו קרחה כל זקן גרועה׃ ");
INSERT INTO heb_vpl VALUES ("IS15_3","024_15_3","ISA","15","3","3","בחוצתיו חגרו שק על גגותיה וברחבתיה כלה ייליל ירד בבכי׃ ");
INSERT INTO heb_vpl VALUES ("IS15_4","024_15_4","ISA","15","4","4","ותזעק חשבון ואלעלה עד יהץ נשמע קולם על כן חלצי מואב יריעו נפשו ירעה לו׃ ");
INSERT INTO heb_vpl VALUES ("IS15_5","024_15_5","ISA","15","5","5","לבי למואב יזעק בריחה עד צער עגלת שלשיה כי מעלה הלוחית בבכי יעלה בו כי דרך חורנים זעקת שבר יעערו׃ ");
INSERT INTO heb_vpl VALUES ("IS15_6","024_15_6","ISA","15","6","6","כי מי נמרים משמות יהיו כי יבש חציר כלה דשא ירק לא היה׃ ");
INSERT INTO heb_vpl VALUES ("IS15_7","024_15_7","ISA","15","7","7","על כן יתרה עשה ופקדתם על נחל הערבים ישאום׃ ");
INSERT INTO heb_vpl VALUES ("IS15_8","024_15_8","ISA","15","8","8","כי הקיפה הזעקה את גבול מואב עד אגלים יללתה ובאר אילים יללתה׃ ");
INSERT INTO heb_vpl VALUES ("IS15_9","024_15_9","ISA","15","9","9","כי מי דימון מלאו דם כי אשית על דימון נוספות לפליטת מואב אריה ולשארית אדמה׃ ");
INSERT INTO heb_vpl VALUES ("IS16_1","024_16_1","ISA","16","1","1","שלחו כר משל ארץ מסלע מדברה אל הר בת ציון׃ ");
INSERT INTO heb_vpl VALUES ("IS16_2","024_16_2","ISA","16","2","2","והיה כעוף נודד קן משלח תהיינה בנות מואב מעברת לארנון׃ ");
INSERT INTO heb_vpl VALUES ("IS16_3","024_16_3","ISA","16","3","3","הביאו עצה עשו פלילה שיתי כליל צלך בתוך צהרים סתרי נדחים נדד אל תגלי׃ ");
INSERT INTO heb_vpl VALUES ("IS16_4","024_16_4","ISA","16","4","4","יגורו בך נדחי מואב הוי סתר למו מפני שודד כי אפס המץ כלה שד תמו רמס מן הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS16_5","024_16_5","ISA","16","5","5","והוכן בחסד כסא וישב עליו באמת באהל דוד שפט ודרש משפט ומהר צדק׃ ");
INSERT INTO heb_vpl VALUES ("IS16_6","024_16_6","ISA","16","6","6","שמענו גאון מואב גא מאד גאותו וגאונו ועברתו לא כן בדיו׃ ");
INSERT INTO heb_vpl VALUES ("IS16_7","024_16_7","ISA","16","7","7","לכן ייליל מואב למואב כלה ייליל לאשישי קיר חרשת תהגו אך נכאים׃ ");
INSERT INTO heb_vpl VALUES ("IS16_8","024_16_8","ISA","16","8","8","כי שדמות חשבון אמלל גפן שבמה בעלי גוים הלמו שרוקיה עד יעזר נגעו תעו מדבר שלחותיה נטשו עברו ים׃ ");
INSERT INTO heb_vpl VALUES ("IS16_9","024_16_9","ISA","16","9","9","על כן אבכה בבכי יעזר גפן שבמה אריוך דמעתי חשבון ואלעלה כי על קיצך ועל קצירך הידד נפל׃ ");
INSERT INTO heb_vpl VALUES ("IS16_10","024_16_10","ISA","16","10","10","ונאסף שמחה וגיל מן הכרמל ובכרמים לא ירנן לא ירעע יין ביקבים לא ידרך הדרך הידד השבתי׃ ");
INSERT INTO heb_vpl VALUES ("IS16_11","024_16_11","ISA","16","11","11","על כן מעי למואב ככנור יהמו וקרבי לקיר חרש׃ ");
INSERT INTO heb_vpl VALUES ("IS16_12","024_16_12","ISA","16","12","12","והיה כי נראה כי נלאה מואב על הבמה ובא אל מקדשו להתפלל ולא יוכל׃ ");
INSERT INTO heb_vpl VALUES ("IS16_13","024_16_13","ISA","16","13","13","זה הדבר אשר דבר יהוה אל מואב מאז׃ ");
INSERT INTO heb_vpl VALUES ("IS16_14","024_16_14","ISA","16","14","14","ועתה דבר יהוה לאמר בשלש שנים כשני שכיר ונקלה כבוד מואב בכל ההמון הרב ושאר מעט מזער לוא כביר׃ ");
INSERT INTO heb_vpl VALUES ("IS17_1","024_17_1","ISA","17","1","1","משא דמשק הנה דמשק מוסר מעיר והיתה מעי מפלה׃ ");
INSERT INTO heb_vpl VALUES ("IS17_2","024_17_2","ISA","17","2","2","עזבות ערי ערער לעדרים תהיינה ורבצו ואין מחריד׃ ");
INSERT INTO heb_vpl VALUES ("IS17_3","024_17_3","ISA","17","3","3","ונשבת מבצר מאפרים וממלכה מדמשק ושאר ארם ככבוד בני ישראל יהיו נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("IS17_4","024_17_4","ISA","17","4","4","והיה ביום ההוא ידל כבוד יעקב ומשמן בשרו ירזה׃ ");
INSERT INTO heb_vpl VALUES ("IS17_5","024_17_5","ISA","17","5","5","והיה כאסף קציר קמה וזרעו שבלים יקצור והיה כמלקט שבלים בעמק רפאים׃ ");
INSERT INTO heb_vpl VALUES ("IS17_6","024_17_6","ISA","17","6","6","ונשאר בו עוללת כנקף זית שנים שלשה גרגרים בראש אמיר ארבעה חמשה בסעפיה פריה נאם יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS17_7","024_17_7","ISA","17","7","7","ביום ההוא ישעה האדם על עשהו ועיניו אל קדוש ישראל תראינה׃ ");
INSERT INTO heb_vpl VALUES ("IS17_8","024_17_8","ISA","17","8","8","ולא ישעה אל המזבחות מעשה ידיו ואשר עשו אצבעתיו לא יראה והאשרים והחמנים׃ ");
INSERT INTO heb_vpl VALUES ("IS17_9","024_17_9","ISA","17","9","9","ביום ההוא יהיו ערי מעזו כעזובת החרש והאמיר אשר עזבו מפני בני ישראל והיתה שממה׃ ");
INSERT INTO heb_vpl VALUES ("IS17_10","024_17_10","ISA","17","10","10","כי שכחת אלהי ישעך וצור מעזך לא זכרת על כן תטעי נטעי נעמנים וזמרת זר תזרענו׃ ");
INSERT INTO heb_vpl VALUES ("IS17_11","024_17_11","ISA","17","11","11","ביום נטעך תשגשגי ובבקר זרעך תפריחי נד קציר ביום נחלה וכאב אנוש׃ ");
INSERT INTO heb_vpl VALUES ("IS17_12","024_17_12","ISA","17","12","12","הוי המון עמים רבים כהמות ימים יהמיון ושאון לאמים כשאון מים כבירים ישאון׃ ");
INSERT INTO heb_vpl VALUES ("IS17_13","024_17_13","ISA","17","13","13","לאמים כשאון מים רבים ישאון וגער בו ונס ממרחק ורדף כמץ הרים לפני רוח וכגלגל לפני סופה׃ ");
INSERT INTO heb_vpl VALUES ("IS17_14","024_17_14","ISA","17","14","14","לעת ערב והנה בלהה בטרם בקר איננו זה חלק שוסינו וגורל לבזזינו׃ ");
INSERT INTO heb_vpl VALUES ("IS18_1","024_18_1","ISA","18","1","1","הוי ארץ צלצל כנפים אשר מעבר לנהרי כוש׃ ");
INSERT INTO heb_vpl VALUES ("IS18_2","024_18_2","ISA","18","2","2","השלח בים צירים ובכלי גמא על פני מים לכו מלאכים קלים אל גוי ממשך ומורט אל עם נורא מן הוא והלאה גוי קו קו ומבוסה אשר בזאו נהרים ארצו׃ ");
INSERT INTO heb_vpl VALUES ("IS18_3","024_18_3","ISA","18","3","3","כל ישבי תבל ושכני ארץ כנשא נס הרים תראו וכתקע שופר תשמעו׃ ");
INSERT INTO heb_vpl VALUES ("IS18_4","024_18_4","ISA","18","4","4","כי כה אמר יהוה אלי אשקוטה ואביטה במכוני כחם צח עלי אור כעב טל בחם קציר׃ ");
INSERT INTO heb_vpl VALUES ("IS18_5","024_18_5","ISA","18","5","5","כי לפני קציר כתם פרח ובסר גמל יהיה נצה וכרת הזלזלים במזמרות ואת הנטישות הסיר התז׃ ");
INSERT INTO heb_vpl VALUES ("IS18_6","024_18_6","ISA","18","6","6","יעזבו יחדו לעיט הרים ולבהמת הארץ וקץ עליו העיט וכל בהמת הארץ עליו תחרף׃ ");
INSERT INTO heb_vpl VALUES ("IS18_7","024_18_7","ISA","18","7","7","בעת ההיא יובל שי ליהוה צבאות עם ממשך ומורט ומעם נורא מן הוא והלאה גוי קו קו ומבוסה אשר בזאו נהרים ארצו אל מקום שם יהוה צבאות הר ציון׃ ");
INSERT INTO heb_vpl VALUES ("IS19_1","024_19_1","ISA","19","1","1","משא מצרים הנה יהוה רכב על עב קל ובא מצרים ונעו אלילי מצרים מפניו ולבב מצרים ימס בקרבו׃ ");
INSERT INTO heb_vpl VALUES ("IS19_2","024_19_2","ISA","19","2","2","וסכסכתי מצרים במצרים ונלחמו איש באחיו ואיש ברעהו עיר בעיר ממלכה בממלכה׃ ");
INSERT INTO heb_vpl VALUES ("IS19_3","024_19_3","ISA","19","3","3","ונבקה רוח מצרים בקרבו ועצתו אבלע ודרשו אל האלילים ואל האטים ואל האבות ואל הידענים׃ ");
INSERT INTO heb_vpl VALUES ("IS19_4","024_19_4","ISA","19","4","4","וסכרתי את מצרים ביד אדנים קשה ומלך עז ימשל בם נאם האדון יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("IS19_5","024_19_5","ISA","19","5","5","ונשתו מים מהים ונהר יחרב ויבש׃ ");
INSERT INTO heb_vpl VALUES ("IS19_6","024_19_6","ISA","19","6","6","והאזניחו נהרות דללו וחרבו יארי מצור קנה וסוף קמלו׃ ");
INSERT INTO heb_vpl VALUES ("IS19_7","024_19_7","ISA","19","7","7","ערות על יאור על פי יאור וכל מזרע יאור ייבש נדף ואיננו׃ ");
INSERT INTO heb_vpl VALUES ("IS19_8","024_19_8","ISA","19","8","8","ואנו הדיגים ואבלו כל משליכי ביאור חכה ופרשי מכמרת על פני מים אמללו׃ ");
INSERT INTO heb_vpl VALUES ("IS19_9","024_19_9","ISA","19","9","9","ובשו עבדי פשתים שריקות וארגים חורי׃ ");
INSERT INTO heb_vpl VALUES ("IS19_10","024_19_10","ISA","19","10","10","והיו שתתיה מדכאים כל עשי שכר אגמי נפש׃ ");
INSERT INTO heb_vpl VALUES ("IS19_11","024_19_11","ISA","19","11","11","אך אולים שרי צען חכמי יעצי פרעה עצה נבערה איך תאמרו אל פרעה בן חכמים אני בן מלכי קדם׃ ");
INSERT INTO heb_vpl VALUES ("IS19_12","024_19_12","ISA","19","12","12","אים אפוא חכמיך ויגידו נא לך וידעו מה יעץ יהוה צבאות על מצרים׃ ");
INSERT INTO heb_vpl VALUES ("IS19_13","024_19_13","ISA","19","13","13","נואלו שרי צען נשאו שרי נף התעו את מצרים פנת שבטיה׃ ");
INSERT INTO heb_vpl VALUES ("IS19_14","024_19_14","ISA","19","14","14","יהוה מסך בקרבה רוח עועים והתעו את מצרים בכל מעשהו כהתעות שכור בקיאו׃ ");
INSERT INTO heb_vpl VALUES ("IS19_15","024_19_15","ISA","19","15","15","ולא יהיה למצרים מעשה אשר יעשה ראש וזנב כפה ואגמון׃ ");
INSERT INTO heb_vpl VALUES ("IS19_16","024_19_16","ISA","19","16","16","ביום ההוא יהיה מצרים כנשים וחרד ופחד מפני תנופת יד יהוה צבאות אשר הוא מניף עליו׃ ");
INSERT INTO heb_vpl VALUES ("IS19_17","024_19_17","ISA","19","17","17","והיתה אדמת יהודה למצרים לחגא כל אשר יזכיר אתה אליו יפחד מפני עצת יהוה צבאות אשר הוא יועץ עליו׃ ");
INSERT INTO heb_vpl VALUES ("IS19_18","024_19_18","ISA","19","18","18","ביום ההוא יהיו חמש ערים בארץ מצרים מדברות שפת כנען ונשבעות ליהוה צבאות עיר ההרס יאמר לאחת׃ ");
INSERT INTO heb_vpl VALUES ("IS19_19","024_19_19","ISA","19","19","19","ביום ההוא יהיה מזבח ליהוה בתוך ארץ מצרים ומצבה אצל גבולה ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS19_20","024_19_20","ISA","19","20","20","והיה לאות ולעד ליהוה צבאות בארץ מצרים כי יצעקו אל יהוה מפני לחצים וישלח להם מושיע ורב והצילם׃ ");
INSERT INTO heb_vpl VALUES ("IS19_21","024_19_21","ISA","19","21","21","ונודע יהוה למצרים וידעו מצרים את יהוה ביום ההוא ועבדו זבח ומנחה ונדרו נדר ליהוה ושלמו׃ ");
INSERT INTO heb_vpl VALUES ("IS19_22","024_19_22","ISA","19","22","22","ונגף יהוה את מצרים נגף ורפוא ושבו עד יהוה ונעתר להם ורפאם׃ ");
INSERT INTO heb_vpl VALUES ("IS19_23","024_19_23","ISA","19","23","23","ביום ההוא תהיה מסלה ממצרים אשורה ובא אשור במצרים ומצרים באשור ועבדו מצרים את אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS19_24","024_19_24","ISA","19","24","24","ביום ההוא יהיה ישראל שלישיה למצרים ולאשור ברכה בקרב הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS19_25","024_19_25","ISA","19","25","25","אשר ברכו יהוה צבאות לאמר ברוך עמי מצרים ומעשה ידי אשור ונחלתי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS20_1","024_20_1","ISA","20","1","1","בשנת בא תרתן אשדודה בשלח אתו סרגון מלך אשור וילחם באשדוד וילכדה׃ ");
INSERT INTO heb_vpl VALUES ("IS20_2","024_20_2","ISA","20","2","2","בעת ההיא דבר יהוה ביד ישעיהו בן אמוץ לאמר לך ופתחת השק מעל מתניך ונעלך תחלץ מעל רגליך ויעש כן הלך ערום ויחף׃ ");
INSERT INTO heb_vpl VALUES ("IS20_3","024_20_3","ISA","20","3","3","ויאמר יהוה כאשר הלך עבדי ישעיהו ערום ויחף שלש שנים אות ומופת על מצרים ועל כוש׃ ");
INSERT INTO heb_vpl VALUES ("IS20_4","024_20_4","ISA","20","4","4","כן ינהג מלך אשור את שבי מצרים ואת גלות כוש נערים וזקנים ערום ויחף וחשופי שת ערות מצרים׃ ");
INSERT INTO heb_vpl VALUES ("IS20_5","024_20_5","ISA","20","5","5","וחתו ובשו מכוש מבטם ומן מצרים תפארתם׃ ");
INSERT INTO heb_vpl VALUES ("IS20_6","024_20_6","ISA","20","6","6","ואמר ישב האי הזה ביום ההוא הנה כה מבטנו אשר נסנו שם לעזרה להנצל מפני מלך אשור ואיך נמלט אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("IS21_1","024_21_1","ISA","21","1","1","משא מדבר ים כסופות בנגב לחלף ממדבר בא מארץ נוראה׃ ");
INSERT INTO heb_vpl VALUES ("IS21_2","024_21_2","ISA","21","2","2","חזות קשה הגד לי הבוגד בוגד והשודד שודד עלי עילם צורי מדי כל אנחתה השבתי׃ ");
INSERT INTO heb_vpl VALUES ("IS21_3","024_21_3","ISA","21","3","3","על כן מלאו מתני חלחלה צירים אחזוני כצירי יולדה נעויתי משמע נבהלתי מראות׃ ");
INSERT INTO heb_vpl VALUES ("IS21_4","024_21_4","ISA","21","4","4","תעה לבבי פלצות בעתתני את נשף חשקי שם לי לחרדה׃ ");
INSERT INTO heb_vpl VALUES ("IS21_5","024_21_5","ISA","21","5","5","ערך השלחן צפה הצפית אכול שתה קומו השרים משחו מגן׃ ");
INSERT INTO heb_vpl VALUES ("IS21_6","024_21_6","ISA","21","6","6","כי כה אמר אלי אדני לך העמד המצפה אשר יראה יגיד׃ ");
INSERT INTO heb_vpl VALUES ("IS21_7","024_21_7","ISA","21","7","7","וראה רכב צמד פרשים רכב חמור רכב גמל והקשיב קשב רב קשב׃ ");
INSERT INTO heb_vpl VALUES ("IS21_8","024_21_8","ISA","21","8","8","ויקרא אריה על מצפה אדני אנכי עמד תמיד יומם ועל משמרתי אנכי נצב כל הלילות׃ ");
INSERT INTO heb_vpl VALUES ("IS21_9","024_21_9","ISA","21","9","9","והנה זה בא רכב איש צמד פרשים ויען ויאמר נפלה נפלה בבל וכל פסילי אלהיה שבר לארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS21_10","024_21_10","ISA","21","10","10","מדשתי ובן גרני אשר שמעתי מאת יהוה צבאות אלהי ישראל הגדתי לכם׃ ");
INSERT INTO heb_vpl VALUES ("IS21_11","024_21_11","ISA","21","11","11","משא דומה אלי קרא משעיר שמר מה מלילה שמר מה מליל׃ ");
INSERT INTO heb_vpl VALUES ("IS21_12","024_21_12","ISA","21","12","12","אמר שמר אתה בקר וגם לילה אם תבעיון בעיו שבו אתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS21_13","024_21_13","ISA","21","13","13","משא בערב ביער בערב תלינו ארחות דדנים׃ ");
INSERT INTO heb_vpl VALUES ("IS21_14","024_21_14","ISA","21","14","14","לקראת צמא התיו מים ישבי ארץ תימא בלחמו קדמו נדד׃ ");
INSERT INTO heb_vpl VALUES ("IS21_15","024_21_15","ISA","21","15","15","כי מפני חרבות נדדו מפני חרב נטושה ומפני קשת דרוכה ומפני כבד מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("IS21_16","024_21_16","ISA","21","16","16","כי כה אמר אדני אלי בעוד שנה כשני שכיר וכלה כל כבוד קדר׃ ");
INSERT INTO heb_vpl VALUES ("IS21_17","024_21_17","ISA","21","17","17","ושאר מספר קשת גבורי בני קדר ימעטו כי יהוה אלהי ישראל דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS22_1","024_22_1","ISA","22","1","1","משא גיא חזיון מה לך אפוא כי עלית כלך לגגות׃ ");
INSERT INTO heb_vpl VALUES ("IS22_2","024_22_2","ISA","22","2","2","תשאות מלאה עיר הומיה קריה עליזה חלליך לא חללי חרב ולא מתי מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("IS22_3","024_22_3","ISA","22","3","3","כל קציניך נדדו יחד מקשת אסרו כל נמצאיך אסרו יחדו מרחוק ברחו׃ ");
INSERT INTO heb_vpl VALUES ("IS22_4","024_22_4","ISA","22","4","4","על כן אמרתי שעו מני אמרר בבכי אל תאיצו לנחמני על שד בת עמי׃ ");
INSERT INTO heb_vpl VALUES ("IS22_5","024_22_5","ISA","22","5","5","כי יום מהומה ומבוסה ומבוכה לאדני יהוה צבאות בגיא חזיון מקרקר קר ושוע אל ההר׃ ");
INSERT INTO heb_vpl VALUES ("IS22_6","024_22_6","ISA","22","6","6","ועילם נשא אשפה ברכב אדם פרשים וקיר ערה מגן׃ ");
INSERT INTO heb_vpl VALUES ("IS22_7","024_22_7","ISA","22","7","7","ויהי מבחר עמקיך מלאו רכב והפרשים שת שתו השערה׃ ");
INSERT INTO heb_vpl VALUES ("IS22_8","024_22_8","ISA","22","8","8","ויגל את מסך יהודה ותבט ביום ההוא אל נשק בית היער׃ ");
INSERT INTO heb_vpl VALUES ("IS22_9","024_22_9","ISA","22","9","9","ואת בקיעי עיר דוד ראיתם כי רבו ותקבצו את מי הברכה התחתונה׃ ");
INSERT INTO heb_vpl VALUES ("IS22_10","024_22_10","ISA","22","10","10","ואת בתי ירושלם ספרתם ותתצו הבתים לבצר החומה׃ ");
INSERT INTO heb_vpl VALUES ("IS22_11","024_22_11","ISA","22","11","11","ומקוה עשיתם בין החמתים למי הברכה הישנה ולא הבטתם אל עשיה ויצרה מרחוק לא ראיתם׃ ");
INSERT INTO heb_vpl VALUES ("IS22_12","024_22_12","ISA","22","12","12","ויקרא אדני יהוה צבאות ביום ההוא לבכי ולמספד ולקרחה ולחגר שק׃ ");
INSERT INTO heb_vpl VALUES ("IS22_13","024_22_13","ISA","22","13","13","והנה ששון ושמחה הרג בקר ושחט צאן אכל בשר ושתות יין אכול ושתו כי מחר נמות׃ ");
INSERT INTO heb_vpl VALUES ("IS22_14","024_22_14","ISA","22","14","14","ונגלה באזני יהוה צבאות אם יכפר העון הזה לכם עד תמתון אמר אדני יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("IS22_15","024_22_15","ISA","22","15","15","כה אמר אדני יהוה צבאות לך בא אל הסכן הזה על שבנא אשר על הבית׃ ");
INSERT INTO heb_vpl VALUES ("IS22_16","024_22_16","ISA","22","16","16","מה לך פה ומי לך פה כי חצבת לך פה קבר חצבי מרום קברו חקקי בסלע משכן לו׃ ");
INSERT INTO heb_vpl VALUES ("IS22_17","024_22_17","ISA","22","17","17","הנה יהוה מטלטלך טלטלה גבר ועטך עטה׃ ");
INSERT INTO heb_vpl VALUES ("IS22_18","024_22_18","ISA","22","18","18","צנוף יצנפך צנפה כדור אל ארץ רחבת ידים שמה תמות ושמה מרכבות כבודך קלון בית אדניך׃ ");
INSERT INTO heb_vpl VALUES ("IS22_19","024_22_19","ISA","22","19","19","והדפתיך ממצבך וממעמדך יהרסך׃ ");
INSERT INTO heb_vpl VALUES ("IS22_20","024_22_20","ISA","22","20","20","והיה ביום ההוא וקראתי לעבדי לאליקים בן חלקיהו׃ ");
INSERT INTO heb_vpl VALUES ("IS22_21","024_22_21","ISA","22","21","21","והלבשתיו כתנתך ואבנטך אחזקנו וממשלתך אתן בידו והיה לאב ליושב ירושלם ולבית יהודה׃ ");
INSERT INTO heb_vpl VALUES ("IS22_22","024_22_22","ISA","22","22","22","ונתתי מפתח בית דוד על שכמו ופתח ואין סגר וסגר ואין פתח׃ ");
INSERT INTO heb_vpl VALUES ("IS22_23","024_22_23","ISA","22","23","23","ותקעתיו יתד במקום נאמן והיה לכסא כבוד לבית אביו׃ ");
INSERT INTO heb_vpl VALUES ("IS22_24","024_22_24","ISA","22","24","24","ותלו עליו כל כבוד בית אביו הצאצאים והצפעות כל כלי הקטן מכלי האגנות ועד כל כלי הנבלים׃ ");
INSERT INTO heb_vpl VALUES ("IS22_25","024_22_25","ISA","22","25","25","ביום ההוא נאם יהוה צבאות תמוש היתד התקועה במקום נאמן ונגדעה ונפלה ונכרת המשא אשר עליה כי יהוה דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS23_1","024_23_1","ISA","23","1","1","משא צר הילילו אניות תרשיש כי שדד מבית מבוא מארץ כתים נגלה למו׃ ");
INSERT INTO heb_vpl VALUES ("IS23_2","024_23_2","ISA","23","2","2","דמו ישבי אי סחר צידון עבר ים מלאוך׃ ");
INSERT INTO heb_vpl VALUES ("IS23_3","024_23_3","ISA","23","3","3","ובמים רבים זרע שחר קציר יאור תבואתה ותהי סחר גוים׃ ");
INSERT INTO heb_vpl VALUES ("IS23_4","024_23_4","ISA","23","4","4","בושי צידון כי אמר ים מעוז הים לאמר לא חלתי ולא ילדתי ולא גדלתי בחורים רוממתי בתולות׃ ");
INSERT INTO heb_vpl VALUES ("IS23_5","024_23_5","ISA","23","5","5","כאשר שמע למצרים יחילו כשמע צר׃ ");
INSERT INTO heb_vpl VALUES ("IS23_6","024_23_6","ISA","23","6","6","עברו תרשישה הילילו ישבי אי׃ ");
INSERT INTO heb_vpl VALUES ("IS23_7","024_23_7","ISA","23","7","7","הזאת לכם עליזה מימי קדם קדמתה יבלוה רגליה מרחוק לגור׃ ");
INSERT INTO heb_vpl VALUES ("IS23_8","024_23_8","ISA","23","8","8","מי יעץ זאת על צר המעטירה אשר סחריה שרים כנעניה נכבדי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS23_9","024_23_9","ISA","23","9","9","יהוה צבאות יעצה לחלל גאון כל צבי להקל כל נכבדי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS23_10","024_23_10","ISA","23","10","10","עברי ארצך כיאר בת תרשיש אין מזח עוד׃ ");
INSERT INTO heb_vpl VALUES ("IS23_11","024_23_11","ISA","23","11","11","ידו נטה על הים הרגיז ממלכות יהוה צוה אל כנען לשמד מעזניה׃ ");
INSERT INTO heb_vpl VALUES ("IS23_12","024_23_12","ISA","23","12","12","ויאמר לא תוסיפי עוד לעלוז המעשקה בתולת בת צידון כתיים קומי עברי גם שם לא ינוח לך׃ ");
INSERT INTO heb_vpl VALUES ("IS23_13","024_23_13","ISA","23","13","13","הן ארץ כשדים זה העם לא היה אשור יסדה לציים הקימו בחיניו עררו ארמנותיה שמה למפלה׃ ");
INSERT INTO heb_vpl VALUES ("IS23_14","024_23_14","ISA","23","14","14","הילילו אניות תרשיש כי שדד מעזכן׃ ");
INSERT INTO heb_vpl VALUES ("IS23_15","024_23_15","ISA","23","15","15","והיה ביום ההוא ונשכחת צר שבעים שנה כימי מלך אחד מקץ שבעים שנה יהיה לצר כשירת הזונה׃ ");
INSERT INTO heb_vpl VALUES ("IS23_16","024_23_16","ISA","23","16","16","קחי כנור סבי עיר זונה נשכחה היטיבי נגן הרבי שיר למען תזכרי׃ ");
INSERT INTO heb_vpl VALUES ("IS23_17","024_23_17","ISA","23","17","17","והיה מקץ שבעים שנה יפקד יהוה את צר ושבה לאתננה וזנתה את כל ממלכות הארץ על פני האדמה׃ ");
INSERT INTO heb_vpl VALUES ("IS23_18","024_23_18","ISA","23","18","18","והיה סחרה ואתננה קדש ליהוה לא יאצר ולא יחסן כי לישבים לפני יהוה יהיה סחרה לאכל לשבעה ולמכסה עתיק׃ ");
INSERT INTO heb_vpl VALUES ("IS24_1","024_24_1","ISA","24","1","1","הנה יהוה בוקק הארץ ובולקה ועוה פניה והפיץ ישביה׃ ");
INSERT INTO heb_vpl VALUES ("IS24_2","024_24_2","ISA","24","2","2","והיה כעם ככהן כעבד כאדניו כשפחה כגברתה כקונה כמוכר כמלוה כלוה כנשה כאשר נשא בו׃ ");
INSERT INTO heb_vpl VALUES ("IS24_3","024_24_3","ISA","24","3","3","הבוק תבוק הארץ והבוז תבוז כי יהוה דבר את הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("IS24_4","024_24_4","ISA","24","4","4","אבלה נבלה הארץ אמללה נבלה תבל אמללו מרום עם הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS24_5","024_24_5","ISA","24","5","5","והארץ חנפה תחת ישביה כי עברו תורת חלפו חק הפרו ברית עולם׃ ");
INSERT INTO heb_vpl VALUES ("IS24_6","024_24_6","ISA","24","6","6","על כן אלה אכלה ארץ ויאשמו ישבי בה על כן חרו ישבי ארץ ונשאר אנוש מזער׃ ");
INSERT INTO heb_vpl VALUES ("IS24_7","024_24_7","ISA","24","7","7","אבל תירוש אמללה גפן נאנחו כל שמחי לב׃ ");
INSERT INTO heb_vpl VALUES ("IS24_8","024_24_8","ISA","24","8","8","שבת משוש תפים חדל שאון עליזים שבת משוש כנור׃ ");
INSERT INTO heb_vpl VALUES ("IS24_9","024_24_9","ISA","24","9","9","בשיר לא ישתו יין ימר שכר לשתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS24_10","024_24_10","ISA","24","10","10","נשברה קרית תהו סגר כל בית מבוא׃ ");
INSERT INTO heb_vpl VALUES ("IS24_11","024_24_11","ISA","24","11","11","צוחה על היין בחוצות ערבה כל שמחה גלה משוש הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS24_12","024_24_12","ISA","24","12","12","נשאר בעיר שמה ושאיה יכת שער׃ ");
INSERT INTO heb_vpl VALUES ("IS24_13","024_24_13","ISA","24","13","13","כי כה יהיה בקרב הארץ בתוך העמים כנקף זית כעוללת אם כלה בציר׃ ");
INSERT INTO heb_vpl VALUES ("IS24_14","024_24_14","ISA","24","14","14","המה ישאו קולם ירנו בגאון יהוה צהלו מים׃ ");
INSERT INTO heb_vpl VALUES ("IS24_15","024_24_15","ISA","24","15","15","על כן בארים כבדו יהוה באיי הים שם יהוה אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS24_16","024_24_16","ISA","24","16","16","מכנף הארץ זמרת שמענו צבי לצדיק ואמר רזי לי רזי לי אוי לי בגדים בגדו ובגד בוגדים בגדו׃ ");
INSERT INTO heb_vpl VALUES ("IS24_17","024_24_17","ISA","24","17","17","פחד ופחת ופח עליך יושב הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS24_18","024_24_18","ISA","24","18","18","והיה הנס מקול הפחד יפל אל הפחת והעולה מתוך הפחת ילכד בפח כי ארבות ממרום נפתחו וירעשו מוסדי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS24_19","024_24_19","ISA","24","19","19","רעה התרעעה הארץ פור התפוררה ארץ מוט התמוטטה ארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS24_20","024_24_20","ISA","24","20","20","נוע תנוע ארץ כשכור והתנודדה כמלונה וכבד עליה פשעה ונפלה ולא תסיף קום׃ ");
INSERT INTO heb_vpl VALUES ("IS24_21","024_24_21","ISA","24","21","21","והיה ביום ההוא יפקד יהוה על צבא המרום במרום ועל מלכי האדמה על האדמה׃ ");
INSERT INTO heb_vpl VALUES ("IS24_22","024_24_22","ISA","24","22","22","ואספו אספה אסיר על בור וסגרו על מסגר ומרב ימים יפקדו׃ ");
INSERT INTO heb_vpl VALUES ("IS24_23","024_24_23","ISA","24","23","23","וחפרה הלבנה ובושה החמה כי מלך יהוה צבאות בהר ציון ובירושלם ונגד זקניו כבוד׃ ");
INSERT INTO heb_vpl VALUES ("IS25_1","024_25_1","ISA","25","1","1","יהוה אלהי אתה ארוממך אודה שמך כי עשית פלא עצות מרחוק אמונה אמן׃ ");
INSERT INTO heb_vpl VALUES ("IS25_2","024_25_2","ISA","25","2","2","כי שמת מעיר לגל קריה בצורה למפלה ארמון זרים מעיר לעולם לא יבנה׃ ");
INSERT INTO heb_vpl VALUES ("IS25_3","024_25_3","ISA","25","3","3","על כן יכבדוך עם עז קרית גוים עריצים ייראוך׃ ");
INSERT INTO heb_vpl VALUES ("IS25_4","024_25_4","ISA","25","4","4","כי היית מעוז לדל מעוז לאביון בצר לו מחסה מזרם צל מחרב כי רוח עריצים כזרם קיר׃ ");
INSERT INTO heb_vpl VALUES ("IS25_5","024_25_5","ISA","25","5","5","כחרב בציון שאון זרים תכניע חרב בצל עב זמיר עריצים יענה׃ ");
INSERT INTO heb_vpl VALUES ("IS25_6","024_25_6","ISA","25","6","6","ועשה יהוה צבאות לכל העמים בהר הזה משתה שמנים משתה שמרים שמנים ממחים שמרים מזקקים׃ ");
INSERT INTO heb_vpl VALUES ("IS25_7","024_25_7","ISA","25","7","7","ובלע בהר הזה פני הלוט הלוט על כל העמים והמסכה הנסוכה על כל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("IS25_8","024_25_8","ISA","25","8","8","בלע המות לנצח ומחה אדני יהוה דמעה מעל כל פנים וחרפת עמו יסיר מעל כל הארץ כי יהוה דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS25_9","024_25_9","ISA","25","9","9","ואמר ביום ההוא הנה אלהינו זה קוינו לו ויושיענו זה יהוה קוינו לו נגילה ונשמחה בישועתו׃ ");
INSERT INTO heb_vpl VALUES ("IS25_10","024_25_10","ISA","25","10","10","כי תנוח יד יהוה בהר הזה ונדוש מואב תחתיו כהדוש מתבן במי מדמנה׃ ");
INSERT INTO heb_vpl VALUES ("IS25_11","024_25_11","ISA","25","11","11","ופרש ידיו בקרבו כאשר יפרש השחה לשחות והשפיל גאותו עם ארבות ידיו׃ ");
INSERT INTO heb_vpl VALUES ("IS25_12","024_25_12","ISA","25","12","12","ומבצר משגב חומתיך השח השפיל הגיע לארץ עד עפר׃ ");
INSERT INTO heb_vpl VALUES ("IS26_1","024_26_1","ISA","26","1","1","ביום ההוא יושר השיר הזה בארץ יהודה עיר עז לנו ישועה ישית חומות וחל׃ ");
INSERT INTO heb_vpl VALUES ("IS26_2","024_26_2","ISA","26","2","2","פתחו שערים ויבא גוי צדיק שמר אמנים׃ ");
INSERT INTO heb_vpl VALUES ("IS26_3","024_26_3","ISA","26","3","3","יצר סמוך תצר שלום שלום כי בך בטוח׃ ");
INSERT INTO heb_vpl VALUES ("IS26_4","024_26_4","ISA","26","4","4","בטחו ביהוה עדי עד כי ביה יהוה צור עולמים׃ ");
INSERT INTO heb_vpl VALUES ("IS26_5","024_26_5","ISA","26","5","5","כי השח ישבי מרום קריה נשגבה ישפילנה ישפילה עד ארץ יגיענה עד עפר׃ ");
INSERT INTO heb_vpl VALUES ("IS26_6","024_26_6","ISA","26","6","6","תרמסנה רגל רגלי עני פעמי דלים׃ ");
INSERT INTO heb_vpl VALUES ("IS26_7","024_26_7","ISA","26","7","7","ארח לצדיק מישרים ישר מעגל צדיק תפלס׃ ");
INSERT INTO heb_vpl VALUES ("IS26_8","024_26_8","ISA","26","8","8","אף ארח משפטיך יהוה קוינוך לשמך ולזכרך תאות נפש׃ ");
INSERT INTO heb_vpl VALUES ("IS26_9","024_26_9","ISA","26","9","9","נפשי אויתיך בלילה אף רוחי בקרבי אשחרך כי כאשר משפטיך לארץ צדק למדו ישבי תבל׃ ");
INSERT INTO heb_vpl VALUES ("IS26_10","024_26_10","ISA","26","10","10","יחן רשע בל למד צדק בארץ נכחות יעול ובל יראה גאות יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS26_11","024_26_11","ISA","26","11","11","יהוה רמה ידך בל יחזיון יחזו ויבשו קנאת עם אף אש צריך תאכלם׃ ");
INSERT INTO heb_vpl VALUES ("IS26_12","024_26_12","ISA","26","12","12","יהוה תשפת שלום לנו כי גם כל מעשינו פעלת לנו׃ ");
INSERT INTO heb_vpl VALUES ("IS26_13","024_26_13","ISA","26","13","13","יהוה אלהינו בעלונו אדנים זולתך לבד בך נזכיר שמך׃ ");
INSERT INTO heb_vpl VALUES ("IS26_14","024_26_14","ISA","26","14","14","מתים בל יחיו רפאים בל יקמו לכן פקדת ותשמידם ותאבד כל זכר למו׃ ");
INSERT INTO heb_vpl VALUES ("IS26_15","024_26_15","ISA","26","15","15","יספת לגוי יהוה יספת לגוי נכבדת רחקת כל קצוי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS26_16","024_26_16","ISA","26","16","16","יהוה בצר פקדוך צקון לחש מוסרך למו׃ ");
INSERT INTO heb_vpl VALUES ("IS26_17","024_26_17","ISA","26","17","17","כמו הרה תקריב ללדת תחיל תזעק בחבליה כן היינו מפניך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS26_18","024_26_18","ISA","26","18","18","הרינו חלנו כמו ילדנו רוח ישועת בל נעשה ארץ ובל יפלו ישבי תבל׃ ");
INSERT INTO heb_vpl VALUES ("IS26_19","024_26_19","ISA","26","19","19","יחיו מתיך נבלתי יקומון הקיצו ורננו שכני עפר כי טל אורת טלך וארץ רפאים תפיל׃ ");
INSERT INTO heb_vpl VALUES ("IS26_20","024_26_20","ISA","26","20","20","לך עמי בא בחדריך וסגר דלתיך בעדך חבי כמעט רגע עד יעבור זעם׃ ");
INSERT INTO heb_vpl VALUES ("IS26_21","024_26_21","ISA","26","21","21","כי הנה יהוה יצא ממקומו לפקד עון ישב הארץ עליו וגלתה הארץ את דמיה ולא תכסה עוד על הרוגיה׃ ");
INSERT INTO heb_vpl VALUES ("IS27_1","024_27_1","ISA","27","1","1","ביום ההוא יפקד יהוה בחרבו הקשה והגדולה והחזקה על לויתן נחש ברח ועל לויתן נחש עקלתון והרג את התנין אשר בים׃ ");
INSERT INTO heb_vpl VALUES ("IS27_2","024_27_2","ISA","27","2","2","ביום ההוא כרם חמד ענו לה׃ ");
INSERT INTO heb_vpl VALUES ("IS27_3","024_27_3","ISA","27","3","3","אני יהוה נצרה לרגעים אשקנה פן יפקד עליה לילה ויום אצרנה׃ ");
INSERT INTO heb_vpl VALUES ("IS27_4","024_27_4","ISA","27","4","4","חמה אין לי מי יתנני שמיר שית במלחמה אפשעה בה אציתנה יחד׃ ");
INSERT INTO heb_vpl VALUES ("IS27_5","024_27_5","ISA","27","5","5","או יחזק במעוזי יעשה שלום לי שלום יעשה לי׃ ");
INSERT INTO heb_vpl VALUES ("IS27_6","024_27_6","ISA","27","6","6","הבאים ישרש יעקב יציץ ופרח ישראל ומלאו פני תבל תנובה׃ ");
INSERT INTO heb_vpl VALUES ("IS27_7","024_27_7","ISA","27","7","7","הכמכת מכהו הכהו אם כהרג הרגיו הרג׃ ");
INSERT INTO heb_vpl VALUES ("IS27_8","024_27_8","ISA","27","8","8","בסאסאה בשלחה תריבנה הגה ברוחו הקשה ביום קדים׃ ");
INSERT INTO heb_vpl VALUES ("IS27_9","024_27_9","ISA","27","9","9","לכן בזאת יכפר עון יעקב וזה כל פרי הסר חטאתו בשומו כל אבני מזבח כאבני גר מנפצות לא יקמו אשרים וחמנים׃ ");
INSERT INTO heb_vpl VALUES ("IS27_10","024_27_10","ISA","27","10","10","כי עיר בצורה בדד נוה משלח ונעזב כמדבר שם ירעה עגל ושם ירבץ וכלה סעפיה׃ ");
INSERT INTO heb_vpl VALUES ("IS27_11","024_27_11","ISA","27","11","11","ביבש קצירה תשברנה נשים באות מאירות אותה כי לא עם בינות הוא על כן לא ירחמנו עשהו ויצרו לא יחננו׃ ");
INSERT INTO heb_vpl VALUES ("IS27_12","024_27_12","ISA","27","12","12","והיה ביום ההוא יחבט יהוה משבלת הנהר עד נחל מצרים ואתם תלקטו לאחד אחד בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS27_13","024_27_13","ISA","27","13","13","והיה ביום ההוא יתקע בשופר גדול ובאו האבדים בארץ אשור והנדחים בארץ מצרים והשתחוו ליהוה בהר הקדש בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS28_1","024_28_1","ISA","28","1","1","הוי עטרת גאות שכרי אפרים וציץ נבל צבי תפארתו אשר על ראש גיא שמנים הלומי יין׃ ");
INSERT INTO heb_vpl VALUES ("IS28_2","024_28_2","ISA","28","2","2","הנה חזק ואמץ לאדני כזרם ברד שער קטב כזרם מים כבירים שטפים הניח לארץ ביד׃ ");
INSERT INTO heb_vpl VALUES ("IS28_3","024_28_3","ISA","28","3","3","ברגלים תרמסנה עטרת גאות שכורי אפרים׃ ");
INSERT INTO heb_vpl VALUES ("IS28_4","024_28_4","ISA","28","4","4","והיתה ציצת נבל צבי תפארתו אשר על ראש גיא שמנים כבכורה בטרם קיץ אשר יראה הראה אותה בעודה בכפו יבלענה׃ ");
INSERT INTO heb_vpl VALUES ("IS28_5","024_28_5","ISA","28","5","5","ביום ההוא יהיה יהוה צבאות לעטרת צבי ולצפירת תפארה לשאר עמו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_6","024_28_6","ISA","28","6","6","ולרוח משפט ליושב על המשפט ולגבורה משיבי מלחמה שערה׃ ");
INSERT INTO heb_vpl VALUES ("IS28_7","024_28_7","ISA","28","7","7","וגם אלה ביין שגו ובשכר תעו כהן ונביא שגו בשכר נבלעו מן היין תעו מן השכר שגו בראה פקו פליליה׃ ");
INSERT INTO heb_vpl VALUES ("IS28_8","024_28_8","ISA","28","8","8","כי כל שלחנות מלאו קיא צאה בלי מקום׃ ");
INSERT INTO heb_vpl VALUES ("IS28_9","024_28_9","ISA","28","9","9","את מי יורה דעה ואת מי יבין שמועה גמולי מחלב עתיקי משדים׃ ");
INSERT INTO heb_vpl VALUES ("IS28_10","024_28_10","ISA","28","10","10","כי צו לצו צו לצו קו לקו קו לקו זעיר שם זעיר שם׃ ");
INSERT INTO heb_vpl VALUES ("IS28_11","024_28_11","ISA","28","11","11","כי בלעגי שפה ובלשון אחרת ידבר אל העם הזה׃ ");
INSERT INTO heb_vpl VALUES ("IS28_12","024_28_12","ISA","28","12","12","אשר אמר אליהם זאת המנוחה הניחו לעיף וזאת המרגעה ולא אבוא שמוע׃ ");
INSERT INTO heb_vpl VALUES ("IS28_13","024_28_13","ISA","28","13","13","והיה להם דבר יהוה צו לצו צו לצו קו לקו קו לקו זעיר שם זעיר שם למען ילכו וכשלו אחור ונשברו ונוקשו ונלכדו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_14","024_28_14","ISA","28","14","14","לכן שמעו דבר יהוה אנשי לצון משלי העם הזה אשר בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS28_15","024_28_15","ISA","28","15","15","כי אמרתם כרתנו ברית את מות ועם שאול עשינו חזה שיט שוטף כי עבר לא יבואנו כי שמנו כזב מחסנו ובשקר נסתרנו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_16","024_28_16","ISA","28","16","16","לכן כה אמר אדני יהוה הנני יסד בציון אבן אבן בחן פנת יקרת מוסד מוסד המאמין לא יחיש׃ ");
INSERT INTO heb_vpl VALUES ("IS28_17","024_28_17","ISA","28","17","17","ושמתי משפט לקו וצדקה למשקלת ויעה ברד מחסה כזב וסתר מים ישטפו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_18","024_28_18","ISA","28","18","18","וכפר בריתכם את מות וחזותכם את שאול לא תקום שוט שוטף כי יעבר והייתם לו למרמס׃ ");
INSERT INTO heb_vpl VALUES ("IS28_19","024_28_19","ISA","28","19","19","מדי עברו יקח אתכם כי בבקר בבקר יעבר ביום ובלילה והיה רק זועה הבין שמועה׃ ");
INSERT INTO heb_vpl VALUES ("IS28_20","024_28_20","ISA","28","20","20","כי קצר המצע מהשתרע והמסכה צרה כהתכנס׃ ");
INSERT INTO heb_vpl VALUES ("IS28_21","024_28_21","ISA","28","21","21","כי כהר פרצים יקום יהוה כעמק בגבעון ירגז לעשות מעשהו זר מעשהו ולעבד עבדתו נכריה עבדתו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_22","024_28_22","ISA","28","22","22","ועתה אל תתלוצצו פן יחזקו מוסריכם כי כלה ונחרצה שמעתי מאת אדני יהוה צבאות על כל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS28_23","024_28_23","ISA","28","23","23","האזינו ושמעו קולי הקשיבו ושמעו אמרתי׃ ");
INSERT INTO heb_vpl VALUES ("IS28_24","024_28_24","ISA","28","24","24","הכל היום יחרש החרש לזרע יפתח וישדד אדמתו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_25","024_28_25","ISA","28","25","25","הלוא אם שוה פניה והפיץ קצח וכמן יזרק ושם חטה שורה ושערה נסמן וכסמת גבלתו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_26","024_28_26","ISA","28","26","26","ויסרו למשפט אלהיו יורנו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_27","024_28_27","ISA","28","27","27","כי לא בחרוץ יודש קצח ואופן עגלה על כמן יוסב כי במטה יחבט קצח וכמן בשבט׃ ");
INSERT INTO heb_vpl VALUES ("IS28_28","024_28_28","ISA","28","28","28","לחם יודק כי לא לנצח אדוש ידושנו והמם גלגל עגלתו ופרשיו לא ידקנו׃ ");
INSERT INTO heb_vpl VALUES ("IS28_29","024_28_29","ISA","28","29","29","גם זאת מעם יהוה צבאות יצאה הפליא עצה הגדיל תושיה׃ ");
INSERT INTO heb_vpl VALUES ("IS29_1","024_29_1","ISA","29","1","1","הוי אריאל אריאל קרית חנה דוד ספו שנה על שנה חגים ינקפו׃ ");
INSERT INTO heb_vpl VALUES ("IS29_2","024_29_2","ISA","29","2","2","והציקותי לאריאל והיתה תאניה ואניה והיתה לי כאריאל׃ ");
INSERT INTO heb_vpl VALUES ("IS29_3","024_29_3","ISA","29","3","3","וחניתי כדור עליך וצרתי עליך מצב והקימתי עליך מצרת׃ ");
INSERT INTO heb_vpl VALUES ("IS29_4","024_29_4","ISA","29","4","4","ושפלת מארץ תדברי ומעפר תשח אמרתך והיה כאוב מארץ קולך ומעפר אמרתך תצפצף׃ ");
INSERT INTO heb_vpl VALUES ("IS29_5","024_29_5","ISA","29","5","5","והיה כאבק דק המון זריך וכמץ עבר המון עריצים והיה לפתע פתאם׃ ");
INSERT INTO heb_vpl VALUES ("IS29_6","024_29_6","ISA","29","6","6","מעם יהוה צבאות תפקד ברעם וברעש וקול גדול סופה וסערה ולהב אש אוכלה׃ ");
INSERT INTO heb_vpl VALUES ("IS29_7","024_29_7","ISA","29","7","7","והיה כחלום חזון לילה המון כל הגוים הצבאים על אריאל וכל צביה ומצדתה והמציקים לה׃ ");
INSERT INTO heb_vpl VALUES ("IS29_8","024_29_8","ISA","29","8","8","והיה כאשר יחלם הרעב והנה אוכל והקיץ וריקה נפשו וכאשר יחלם הצמא והנה שתה והקיץ והנה עיף ונפשו שוקקה כן יהיה המון כל הגוים הצבאים על הר ציון׃ ");
INSERT INTO heb_vpl VALUES ("IS29_9","024_29_9","ISA","29","9","9","התמהמהו ותמהו השתעשעו ושעו שכרו ולא יין נעו ולא שכר׃ ");
INSERT INTO heb_vpl VALUES ("IS29_10","024_29_10","ISA","29","10","10","כי נסך עליכם יהוה רוח תרדמה ויעצם את עיניכם את הנביאים ואת ראשיכם החזים כסה׃ ");
INSERT INTO heb_vpl VALUES ("IS29_11","024_29_11","ISA","29","11","11","ותהי לכם חזות הכל כדברי הספר החתום אשר יתנו אתו אל יודע הספר לאמר קרא נא זה ואמר לא אוכל כי חתום הוא׃ ");
INSERT INTO heb_vpl VALUES ("IS29_12","024_29_12","ISA","29","12","12","ונתן הספר על אשר לא ידע ספר לאמר קרא נא זה ואמר לא ידעתי ספר׃ ");
INSERT INTO heb_vpl VALUES ("IS29_13","024_29_13","ISA","29","13","13","ויאמר אדני יען כי נגש העם הזה בפיו ובשפתיו כבדוני ולבו רחק ממני ותהי יראתם אתי מצות אנשים מלמדה׃ ");
INSERT INTO heb_vpl VALUES ("IS29_14","024_29_14","ISA","29","14","14","לכן הנני יוסף להפליא את העם הזה הפלא ופלא ואבדה חכמת חכמיו ובינת נבניו תסתתר׃ ");
INSERT INTO heb_vpl VALUES ("IS29_15","024_29_15","ISA","29","15","15","הוי המעמיקים מיהוה לסתר עצה והיה במחשך מעשיהם ויאמרו מי ראנו ומי יודענו׃ ");
INSERT INTO heb_vpl VALUES ("IS29_16","024_29_16","ISA","29","16","16","הפככם אם כחמר היצר יחשב כי יאמר מעשה לעשהו לא עשני ויצר אמר ליוצרו לא הבין׃ ");
INSERT INTO heb_vpl VALUES ("IS29_17","024_29_17","ISA","29","17","17","הלוא עוד מעט מזער ושב לבנון לכרמל והכרמל ליער יחשב׃ ");
INSERT INTO heb_vpl VALUES ("IS29_18","024_29_18","ISA","29","18","18","ושמעו ביום ההוא החרשים דברי ספר ומאפל ומחשך עיני עורים תראינה׃ ");
INSERT INTO heb_vpl VALUES ("IS29_19","024_29_19","ISA","29","19","19","ויספו ענוים ביהוה שמחה ואביוני אדם בקדוש ישראל יגילו׃ ");
INSERT INTO heb_vpl VALUES ("IS29_20","024_29_20","ISA","29","20","20","כי אפס עריץ וכלה לץ ונכרתו כל שקדי און׃ ");
INSERT INTO heb_vpl VALUES ("IS29_21","024_29_21","ISA","29","21","21","מחטיאי אדם בדבר ולמוכיח בשער יקשון ויטו בתהו צדיק׃ ");
INSERT INTO heb_vpl VALUES ("IS29_22","024_29_22","ISA","29","22","22","לכן כה אמר יהוה אל בית יעקב אשר פדה את אברהם לא עתה יבוש יעקב ולא עתה פניו יחורו׃ ");
INSERT INTO heb_vpl VALUES ("IS29_23","024_29_23","ISA","29","23","23","כי בראתו ילדיו מעשה ידי בקרבו יקדישו שמי והקדישו את קדוש יעקב ואת אלהי ישראל יעריצו׃ ");
INSERT INTO heb_vpl VALUES ("IS29_24","024_29_24","ISA","29","24","24","וידעו תעי רוח בינה ורוגנים ילמדו לקח׃ ");
INSERT INTO heb_vpl VALUES ("IS30_1","024_30_1","ISA","30","1","1","הוי בנים סוררים נאם יהוה לעשות עצה ולא מני ולנסך מסכה ולא רוחי למען ספות חטאת על חטאת׃ ");
INSERT INTO heb_vpl VALUES ("IS30_2","024_30_2","ISA","30","2","2","ההלכים לרדת מצרים ופי לא שאלו לעוז במעוז פרעה ולחסות בצל מצרים׃ ");
INSERT INTO heb_vpl VALUES ("IS30_3","024_30_3","ISA","30","3","3","והיה לכם מעוז פרעה לבשת והחסות בצל מצרים לכלמה׃ ");
INSERT INTO heb_vpl VALUES ("IS30_4","024_30_4","ISA","30","4","4","כי היו בצען שריו ומלאכיו חנס יגיעו׃ ");
INSERT INTO heb_vpl VALUES ("IS30_5","024_30_5","ISA","30","5","5","כל הבאיש על עם לא יועילו למו לא לעזר ולא להועיל כי לבשת וגם לחרפה׃ ");
INSERT INTO heb_vpl VALUES ("IS30_6","024_30_6","ISA","30","6","6","משא בהמות נגב בארץ צרה וצוקה לביא וליש מהם אפעה ושרף מעופף ישאו על כתף עירים חילהם ועל דבשת גמלים אוצרתם על עם לא יועילו׃ ");
INSERT INTO heb_vpl VALUES ("IS30_7","024_30_7","ISA","30","7","7","ומצרים הבל וריק יעזרו לכן קראתי לזאת רהב הם שבת׃ ");
INSERT INTO heb_vpl VALUES ("IS30_8","024_30_8","ISA","30","8","8","עתה בוא כתבה על לוח אתם ועל ספר חקה ותהי ליום אחרון לעד עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("IS30_9","024_30_9","ISA","30","9","9","כי עם מרי הוא בנים כחשים בנים לא אבו שמוע תורת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS30_10","024_30_10","ISA","30","10","10","אשר אמרו לראים לא תראו ולחזים לא תחזו לנו נכחות דברו לנו חלקות חזו מהתלות׃ ");
INSERT INTO heb_vpl VALUES ("IS30_11","024_30_11","ISA","30","11","11","סורו מני דרך הטו מני ארח השביתו מפנינו את קדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS30_12","024_30_12","ISA","30","12","12","לכן כה אמר קדוש ישראל יען מאסכם בדבר הזה ותבטחו בעשק ונלוז ותשענו עליו׃ ");
INSERT INTO heb_vpl VALUES ("IS30_13","024_30_13","ISA","30","13","13","לכן יהיה לכם העון הזה כפרץ נפל נבעה בחומה נשגבה אשר פתאם לפתע יבוא שברה׃ ");
INSERT INTO heb_vpl VALUES ("IS30_14","024_30_14","ISA","30","14","14","ושברה כשבר נבל יוצרים כתות לא יחמל ולא ימצא במכתתו חרש לחתות אש מיקוד ולחשף מים מגבא׃ ");
INSERT INTO heb_vpl VALUES ("IS30_15","024_30_15","ISA","30","15","15","כי כה אמר אדני יהוה קדוש ישראל בשובה ונחת תושעון בהשקט ובבטחה תהיה גבורתכם ולא אביתם׃ ");
INSERT INTO heb_vpl VALUES ("IS30_16","024_30_16","ISA","30","16","16","ותאמרו לא כי על סוס ננוס על כן תנוסון ועל קל נרכב על כן יקלו רדפיכם׃ ");
INSERT INTO heb_vpl VALUES ("IS30_17","024_30_17","ISA","30","17","17","אלף אחד מפני גערת אחד מפני גערת חמשה תנסו עד אם נותרתם כתרן על ראש ההר וכנס על הגבעה׃ ");
INSERT INTO heb_vpl VALUES ("IS30_18","024_30_18","ISA","30","18","18","ולכן יחכה יהוה לחננכם ולכן ירום לרחמכם כי אלהי משפט יהוה אשרי כל חוכי לו׃ ");
INSERT INTO heb_vpl VALUES ("IS30_19","024_30_19","ISA","30","19","19","כי עם בציון ישב בירושלם בכו לא תבכה חנון יחנך לקול זעקך כשמעתו ענך׃ ");
INSERT INTO heb_vpl VALUES ("IS30_20","024_30_20","ISA","30","20","20","ונתן לכם אדני לחם צר ומים לחץ ולא יכנף עוד מוריך והיו עיניך ראות את מוריך׃ ");
INSERT INTO heb_vpl VALUES ("IS30_21","024_30_21","ISA","30","21","21","ואזניך תשמענה דבר מאחריך לאמר זה הדרך לכו בו כי תאמינו וכי תשמאילו׃ ");
INSERT INTO heb_vpl VALUES ("IS30_22","024_30_22","ISA","30","22","22","וטמאתם את צפוי פסילי כספך ואת אפדת מסכת זהבך תזרם כמו דוה צא תאמר לו׃ ");
INSERT INTO heb_vpl VALUES ("IS30_23","024_30_23","ISA","30","23","23","ונתן מטר זרעך אשר תזרע את האדמה ולחם תבואת האדמה והיה דשן ושמן ירעה מקניך ביום ההוא כר נרחב׃ ");
INSERT INTO heb_vpl VALUES ("IS30_24","024_30_24","ISA","30","24","24","והאלפים והעירים עבדי האדמה בליל חמיץ יאכלו אשר זרה ברחת ובמזרה׃ ");
INSERT INTO heb_vpl VALUES ("IS30_25","024_30_25","ISA","30","25","25","והיה על כל הר גבה ועל כל גבעה נשאה פלגים יבלי מים ביום הרג רב בנפל מגדלים׃ ");
INSERT INTO heb_vpl VALUES ("IS30_26","024_30_26","ISA","30","26","26","והיה אור הלבנה כאור החמה ואור החמה יהיה שבעתים כאור שבעת הימים ביום חבש יהוה את שבר עמו ומחץ מכתו ירפא׃ ");
INSERT INTO heb_vpl VALUES ("IS30_27","024_30_27","ISA","30","27","27","הנה שם יהוה בא ממרחק בער אפו וכבד משאה שפתיו מלאו זעם ולשונו כאש אכלת׃ ");
INSERT INTO heb_vpl VALUES ("IS30_28","024_30_28","ISA","30","28","28","ורוחו כנחל שוטף עד צואר יחצה להנפה גוים בנפת שוא ורסן מתעה על לחיי עמים׃ ");
INSERT INTO heb_vpl VALUES ("IS30_29","024_30_29","ISA","30","29","29","השיר יהיה לכם כליל התקדש חג ושמחת לבב כהולך בחליל לבוא בהר יהוה אל צור ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS30_30","024_30_30","ISA","30","30","30","והשמיע יהוה את הוד קולו ונחת זרועו יראה בזעף אף ולהב אש אוכלה נפץ וזרם ואבן ברד׃ ");
INSERT INTO heb_vpl VALUES ("IS30_31","024_30_31","ISA","30","31","31","כי מקול יהוה יחת אשור בשבט יכה׃ ");
INSERT INTO heb_vpl VALUES ("IS30_32","024_30_32","ISA","30","32","32","והיה כל מעבר מטה מוסדה אשר יניח יהוה עליו בתפים ובכנרות ובמלחמות תנופה נלחם בה׃ ");
INSERT INTO heb_vpl VALUES ("IS30_33","024_30_33","ISA","30","33","33","כי ערוך מאתמול תפתה גם הוא למלך הוכן העמיק הרחב מדרתה אש ועצים הרבה נשמת יהוה כנחל גפרית בערה בה׃ ");
INSERT INTO heb_vpl VALUES ("IS31_1","024_31_1","ISA","31","1","1","הוי הירדים מצרים לעזרה על סוסים ישענו ויבטחו על רכב כי רב ועל פרשים כי עצמו מאד ולא שעו על קדוש ישראל ואת יהוה לא דרשו׃ ");
INSERT INTO heb_vpl VALUES ("IS31_2","024_31_2","ISA","31","2","2","וגם הוא חכם ויבא רע ואת דבריו לא הסיר וקם על בית מרעים ועל עזרת פעלי און׃ ");
INSERT INTO heb_vpl VALUES ("IS31_3","024_31_3","ISA","31","3","3","ומצרים אדם ולא אל וסוסיהם בשר ולא רוח ויהוה יטה ידו וכשל עוזר ונפל עזר ויחדו כלם יכליון׃ ");
INSERT INTO heb_vpl VALUES ("IS31_4","024_31_4","ISA","31","4","4","כי כה אמר יהוה אלי כאשר יהגה האריה והכפיר על טרפו אשר יקרא עליו מלא רעים מקולם לא יחת ומהמונם לא יענה כן ירד יהוה צבאות לצבא על הר ציון ועל גבעתה׃ ");
INSERT INTO heb_vpl VALUES ("IS31_5","024_31_5","ISA","31","5","5","כצפרים עפות כן יגן יהוה צבאות על ירושלם גנון והציל פסח והמליט׃ ");
INSERT INTO heb_vpl VALUES ("IS31_6","024_31_6","ISA","31","6","6","שובו לאשר העמיקו סרה בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS31_7","024_31_7","ISA","31","7","7","כי ביום ההוא ימאסון איש אלילי כספו ואלילי זהבו אשר עשו לכם ידיכם חטא׃ ");
INSERT INTO heb_vpl VALUES ("IS31_8","024_31_8","ISA","31","8","8","ונפל אשור בחרב לא איש וחרב לא אדם תאכלנו ונס לו מפני חרב ובחוריו למס יהיו׃ ");
INSERT INTO heb_vpl VALUES ("IS31_9","024_31_9","ISA","31","9","9","וסלעו ממגור יעבור וחתו מנס שריו נאם יהוה אשר אור לו בציון ותנור לו בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS32_1","024_32_1","ISA","32","1","1","הן לצדק ימלך מלך ולשרים למשפט ישרו׃ ");
INSERT INTO heb_vpl VALUES ("IS32_2","024_32_2","ISA","32","2","2","והיה איש כמחבא רוח וסתר זרם כפלגי מים בציון כצל סלע כבד בארץ עיפה׃ ");
INSERT INTO heb_vpl VALUES ("IS32_3","024_32_3","ISA","32","3","3","ולא תשעינה עיני ראים ואזני שמעים תקשבנה׃ ");
INSERT INTO heb_vpl VALUES ("IS32_4","024_32_4","ISA","32","4","4","ולבב נמהרים יבין לדעת ולשון עלגים תמהר לדבר צחות׃ ");
INSERT INTO heb_vpl VALUES ("IS32_5","024_32_5","ISA","32","5","5","לא יקרא עוד לנבל נדיב ולכילי לא יאמר שוע׃ ");
INSERT INTO heb_vpl VALUES ("IS32_6","024_32_6","ISA","32","6","6","כי נבל נבלה ידבר ולבו יעשה און לעשות חנף ולדבר אל יהוה תועה להריק נפש רעב ומשקה צמא יחסיר׃ ");
INSERT INTO heb_vpl VALUES ("IS32_7","024_32_7","ISA","32","7","7","וכלי כליו רעים הוא זמות יעץ לחבל ענוים באמרי שקר ובדבר אביון משפט׃ ");
INSERT INTO heb_vpl VALUES ("IS32_8","024_32_8","ISA","32","8","8","ונדיב נדיבות יעץ והוא על נדיבות יקום׃ ");
INSERT INTO heb_vpl VALUES ("IS32_9","024_32_9","ISA","32","9","9","נשים שאננות קמנה שמענה קולי בנות בטחות האזנה אמרתי׃ ");
INSERT INTO heb_vpl VALUES ("IS32_10","024_32_10","ISA","32","10","10","ימים על שנה תרגזנה בטחות כי כלה בציר אסף בלי יבוא׃ ");
INSERT INTO heb_vpl VALUES ("IS32_11","024_32_11","ISA","32","11","11","חרדו שאננות רגזה בטחות פשטה וערה וחגורה על חלצים׃ ");
INSERT INTO heb_vpl VALUES ("IS32_12","024_32_12","ISA","32","12","12","על שדים ספדים על שדי חמד על גפן פריה׃ ");
INSERT INTO heb_vpl VALUES ("IS32_13","024_32_13","ISA","32","13","13","על אדמת עמי קוץ שמיר תעלה כי על כל בתי משוש קריה עליזה׃ ");
INSERT INTO heb_vpl VALUES ("IS32_14","024_32_14","ISA","32","14","14","כי ארמון נטש המון עיר עזב עפל ובחן היה בעד מערות עד עולם משוש פראים מרעה עדרים׃ ");
INSERT INTO heb_vpl VALUES ("IS32_15","024_32_15","ISA","32","15","15","עד יערה עלינו רוח ממרום והיה מדבר לכרמל וכרמל ליער יחשב׃ ");
INSERT INTO heb_vpl VALUES ("IS32_16","024_32_16","ISA","32","16","16","ושכן במדבר משפט וצדקה בכרמל תשב׃ ");
INSERT INTO heb_vpl VALUES ("IS32_17","024_32_17","ISA","32","17","17","והיה מעשה הצדקה שלום ועבדת הצדקה השקט ובטח עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("IS32_18","024_32_18","ISA","32","18","18","וישב עמי בנוה שלום ובמשכנות מבטחים ובמנוחת שאננות׃ ");
INSERT INTO heb_vpl VALUES ("IS32_19","024_32_19","ISA","32","19","19","וברד ברדת היער ובשפלה תשפל העיר׃ ");
INSERT INTO heb_vpl VALUES ("IS32_20","024_32_20","ISA","32","20","20","אשריכם זרעי על כל מים משלחי רגל השור והחמור׃ ");
INSERT INTO heb_vpl VALUES ("IS33_1","024_33_1","ISA","33","1","1","הוי שודד ואתה לא שדוד ובוגד ולא בגדו בו כהתמך שודד תושד כנלתך לבגד יבגדו בך׃ ");
INSERT INTO heb_vpl VALUES ("IS33_2","024_33_2","ISA","33","2","2","יהוה חננו לך קוינו היה זרעם לבקרים אף ישועתנו בעת צרה׃ ");
INSERT INTO heb_vpl VALUES ("IS33_3","024_33_3","ISA","33","3","3","מקול המון נדדו עמים מרוממתך נפצו גוים׃ ");
INSERT INTO heb_vpl VALUES ("IS33_4","024_33_4","ISA","33","4","4","ואסף שללכם אסף החסיל כמשק גבים שוקק בו׃ ");
INSERT INTO heb_vpl VALUES ("IS33_5","024_33_5","ISA","33","5","5","נשגב יהוה כי שכן מרום מלא ציון משפט וצדקה׃ ");
INSERT INTO heb_vpl VALUES ("IS33_6","024_33_6","ISA","33","6","6","והיה אמונת עתיך חסן ישועת חכמת ודעת יראת יהוה היא אוצרו׃ ");
INSERT INTO heb_vpl VALUES ("IS33_7","024_33_7","ISA","33","7","7","הן אראלם צעקו חצה מלאכי שלום מר יבכיון׃ ");
INSERT INTO heb_vpl VALUES ("IS33_8","024_33_8","ISA","33","8","8","נשמו מסלות שבת עבר ארח הפר ברית מאס ערים לא חשב אנוש׃ ");
INSERT INTO heb_vpl VALUES ("IS33_9","024_33_9","ISA","33","9","9","אבל אמללה ארץ החפיר לבנון קמל היה השרון כערבה ונער בשן וכרמל׃ ");
INSERT INTO heb_vpl VALUES ("IS33_10","024_33_10","ISA","33","10","10","עתה אקום יאמר יהוה עתה ארומם עתה אנשא׃ ");
INSERT INTO heb_vpl VALUES ("IS33_11","024_33_11","ISA","33","11","11","תהרו חשש תלדו קש רוחכם אש תאכלכם׃ ");
INSERT INTO heb_vpl VALUES ("IS33_12","024_33_12","ISA","33","12","12","והיו עמים משרפות שיד קוצים כסוחים באש יצתו׃ ");
INSERT INTO heb_vpl VALUES ("IS33_13","024_33_13","ISA","33","13","13","שמעו רחוקים אשר עשיתי ודעו קרובים גברתי׃ ");
INSERT INTO heb_vpl VALUES ("IS33_14","024_33_14","ISA","33","14","14","פחדו בציון חטאים אחזה רעדה חנפים מי יגור לנו אש אוכלה מי יגור לנו מוקדי עולם׃ ");
INSERT INTO heb_vpl VALUES ("IS33_15","024_33_15","ISA","33","15","15","הלך צדקות ודבר מישרים מאס בבצע מעשקות נער כפיו מתמך בשחד אטם אזנו משמע דמים ועצם עיניו מראות ברע׃ ");
INSERT INTO heb_vpl VALUES ("IS33_16","024_33_16","ISA","33","16","16","הוא מרומים ישכן מצדות סלעים משגבו לחמו נתן מימיו נאמנים׃ ");
INSERT INTO heb_vpl VALUES ("IS33_17","024_33_17","ISA","33","17","17","מלך ביפיו תחזינה עיניך תראינה ארץ מרחקים׃ ");
INSERT INTO heb_vpl VALUES ("IS33_18","024_33_18","ISA","33","18","18","לבך יהגה אימה איה ספר איה שקל איה ספר את המגדלים׃ ");
INSERT INTO heb_vpl VALUES ("IS33_19","024_33_19","ISA","33","19","19","את עם נועז לא תראה עם עמקי שפה משמוע נלעג לשון אין בינה׃ ");
INSERT INTO heb_vpl VALUES ("IS33_20","024_33_20","ISA","33","20","20","חזה ציון קרית מועדנו עיניך תראינה ירושלם נוה שאנן אהל בל יצען בל יסע יתדתיו לנצח וכל חבליו בל ינתקו׃ ");
INSERT INTO heb_vpl VALUES ("IS33_21","024_33_21","ISA","33","21","21","כי אם שם אדיר יהוה לנו מקום נהרים יארים רחבי ידים בל תלך בו אני שיט וצי אדיר לא יעברנו׃ ");
INSERT INTO heb_vpl VALUES ("IS33_22","024_33_22","ISA","33","22","22","כי יהוה שפטנו יהוה מחקקנו יהוה מלכנו הוא יושיענו׃ ");
INSERT INTO heb_vpl VALUES ("IS33_23","024_33_23","ISA","33","23","23","נטשו חבליך בל יחזקו כן תרנם בל פרשו נס אז חלק עד שלל מרבה פסחים בזזו בז׃ ");
INSERT INTO heb_vpl VALUES ("IS33_24","024_33_24","ISA","33","24","24","ובל יאמר שכן חליתי העם הישב בה נשא עון׃ ");
INSERT INTO heb_vpl VALUES ("IS34_1","024_34_1","ISA","34","1","1","קרבו גוים לשמע ולאמים הקשיבו תשמע הארץ ומלאה תבל וכל צאצאיה׃ ");
INSERT INTO heb_vpl VALUES ("IS34_2","024_34_2","ISA","34","2","2","כי קצף ליהוה על כל הגוים וחמה על כל צבאם החרימם נתנם לטבח׃ ");
INSERT INTO heb_vpl VALUES ("IS34_3","024_34_3","ISA","34","3","3","וחלליהם ישלכו ופגריהם יעלה באשם ונמסו הרים מדמם׃ ");
INSERT INTO heb_vpl VALUES ("IS34_4","024_34_4","ISA","34","4","4","ונמקו כל צבא השמים ונגלו כספר השמים וכל צבאם יבול כנבל עלה מגפן וכנבלת מתאנה׃ ");
INSERT INTO heb_vpl VALUES ("IS34_5","024_34_5","ISA","34","5","5","כי רותה בשמים חרבי הנה על אדום תרד ועל עם חרמי למשפט׃ ");
INSERT INTO heb_vpl VALUES ("IS34_6","024_34_6","ISA","34","6","6","חרב ליהוה מלאה דם הדשנה מחלב מדם כרים ועתודים מחלב כליות אילים כי זבח ליהוה בבצרה וטבח גדול בארץ אדום׃ ");
INSERT INTO heb_vpl VALUES ("IS34_7","024_34_7","ISA","34","7","7","וירדו ראמים עמם ופרים עם אבירים ורותה ארצם מדם ועפרם מחלב ידשן׃ ");
INSERT INTO heb_vpl VALUES ("IS34_8","024_34_8","ISA","34","8","8","כי יום נקם ליהוה שנת שלומים לריב ציון׃ ");
INSERT INTO heb_vpl VALUES ("IS34_9","024_34_9","ISA","34","9","9","ונהפכו נחליה לזפת ועפרה לגפרית והיתה ארצה לזפת בערה׃ ");
INSERT INTO heb_vpl VALUES ("IS34_10","024_34_10","ISA","34","10","10","לילה ויומם לא תכבה לעולם יעלה עשנה מדור לדור תחרב לנצח נצחים אין עבר בה׃ ");
INSERT INTO heb_vpl VALUES ("IS34_11","024_34_11","ISA","34","11","11","וירשוה קאת וקפוד וינשוף וערב ישכנו בה ונטה עליה קו תהו ואבני בהו׃ ");
INSERT INTO heb_vpl VALUES ("IS34_12","024_34_12","ISA","34","12","12","חריה ואין שם מלוכה יקראו וכל שריה יהיו אפס׃ ");
INSERT INTO heb_vpl VALUES ("IS34_13","024_34_13","ISA","34","13","13","ועלתה ארמנתיה סירים קמוש וחוח במבצריה והיתה נוה תנים חציר לבנות יענה׃ ");
INSERT INTO heb_vpl VALUES ("IS34_14","024_34_14","ISA","34","14","14","ופגשו ציים את איים ושעיר על רעהו יקרא אך שם הרגיעה לילית ומצאה לה מנוח׃ ");
INSERT INTO heb_vpl VALUES ("IS34_15","024_34_15","ISA","34","15","15","שמה קננה קפוז ותמלט ובקעה ודגרה בצלה אך שם נקבצו דיות אשה רעותה׃ ");
INSERT INTO heb_vpl VALUES ("IS34_16","024_34_16","ISA","34","16","16","דרשו מעל ספר יהוה וקראו אחת מהנה לא נעדרה אשה רעותה לא פקדו כי פי הוא צוה ורוחו הוא קבצן׃ ");
INSERT INTO heb_vpl VALUES ("IS34_17","024_34_17","ISA","34","17","17","והוא הפיל להן גורל וידו חלקתה להם בקו עד עולם יירשוה לדור ודור ישכנו בה׃ ");
INSERT INTO heb_vpl VALUES ("IS35_1","024_35_1","ISA","35","1","1","יששום מדבר וציה ותגל ערבה ותפרח כחבצלת׃ ");
INSERT INTO heb_vpl VALUES ("IS35_2","024_35_2","ISA","35","2","2","פרח תפרח ותגל אף גילת ורנן כבוד הלבנון נתן לה הדר הכרמל והשרון המה יראו כבוד יהוה הדר אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("IS35_3","024_35_3","ISA","35","3","3","חזקו ידים רפות וברכים כשלות אמצו׃ ");
INSERT INTO heb_vpl VALUES ("IS35_4","024_35_4","ISA","35","4","4","אמרו לנמהרי לב חזקו אל תיראו הנה אלהיכם נקם יבוא גמול אלהים הוא יבוא וישעכם׃ ");
INSERT INTO heb_vpl VALUES ("IS35_5","024_35_5","ISA","35","5","5","אז תפקחנה עיני עורים ואזני חרשים תפתחנה׃ ");
INSERT INTO heb_vpl VALUES ("IS35_6","024_35_6","ISA","35","6","6","אז ידלג כאיל פסח ותרן לשון אלם כי נבקעו במדבר מים ונחלים בערבה׃ ");
INSERT INTO heb_vpl VALUES ("IS35_7","024_35_7","ISA","35","7","7","והיה השרב לאגם וצמאון למבועי מים בנוה תנים רבצה חציר לקנה וגמא׃ ");
INSERT INTO heb_vpl VALUES ("IS35_8","024_35_8","ISA","35","8","8","והיה שם מסלול ודרך ודרך הקדש יקרא לה לא יעברנו טמא והוא למו הלך דרך ואוילים לא יתעו׃ ");
INSERT INTO heb_vpl VALUES ("IS35_9","024_35_9","ISA","35","9","9","לא יהיה שם אריה ופריץ חיות בל יעלנה לא תמצא שם והלכו גאולים׃ ");
INSERT INTO heb_vpl VALUES ("IS35_10","024_35_10","ISA","35","10","10","ופדויי יהוה ישבון ובאו ציון ברנה ושמחת עולם על ראשם ששון ושמחה ישיגו ונסו יגון ואנחה׃ ");
INSERT INTO heb_vpl VALUES ("IS36_1","024_36_1","ISA","36","1","1","ויהי בארבע עשרה שנה למלך חזקיהו עלה סנחריב מלך אשור על כל ערי יהודה הבצרות ויתפשם׃ ");
INSERT INTO heb_vpl VALUES ("IS36_2","024_36_2","ISA","36","2","2","וישלח מלך אשור את רב שקה מלכיש ירושלמה אל המלך חזקיהו בחיל כבד ויעמד בתעלת הברכה העליונה במסלת שדה כובס׃ ");
INSERT INTO heb_vpl VALUES ("IS36_3","024_36_3","ISA","36","3","3","ויצא אליו אליקים בן חלקיהו אשר על הבית ושבנא הספר ויואח בן אסף המזכיר׃ ");
INSERT INTO heb_vpl VALUES ("IS36_4","024_36_4","ISA","36","4","4","ויאמר אליהם רב שקה אמרו נא אל חזקיהו כה אמר המלך הגדול מלך אשור מה הבטחון הזה אשר בטחת׃ ");
INSERT INTO heb_vpl VALUES ("IS36_5","024_36_5","ISA","36","5","5","אמרתי אך דבר שפתים עצה וגבורה למלחמה עתה על מי בטחת כי מרדת בי׃ ");
INSERT INTO heb_vpl VALUES ("IS36_6","024_36_6","ISA","36","6","6","הנה בטחת על משענת הקנה הרצוץ הזה על מצרים אשר יסמך איש עליו ובא בכפו ונקבה כן פרעה מלך מצרים לכל הבטחים עליו׃ ");
INSERT INTO heb_vpl VALUES ("IS36_7","024_36_7","ISA","36","7","7","וכי תאמר אלי אל יהוה אלהינו בטחנו הלוא הוא אשר הסיר חזקיהו את במתיו ואת מזבחתיו ויאמר ליהודה ולירושלם לפני המזבח הזה תשתחוו׃ ");
INSERT INTO heb_vpl VALUES ("IS36_8","024_36_8","ISA","36","8","8","ועתה התערב נא את אדני המלך אשור ואתנה לך אלפים סוסים אם תוכל לתת לך רכבים עליהם׃ ");
INSERT INTO heb_vpl VALUES ("IS36_9","024_36_9","ISA","36","9","9","ואיך תשיב את פני פחת אחד עבדי אדני הקטנים ותבטח לך על מצרים לרכב ולפרשים׃ ");
INSERT INTO heb_vpl VALUES ("IS36_10","024_36_10","ISA","36","10","10","ועתה המבלעדי יהוה עליתי על הארץ הזאת להשחיתה יהוה אמר אלי עלה אל הארץ הזאת והשחיתה׃ ");
INSERT INTO heb_vpl VALUES ("IS36_11","024_36_11","ISA","36","11","11","ויאמר אליקים ושבנא ויואח אל רב שקה דבר נא אל עבדיך ארמית כי שמעים אנחנו ואל תדבר אלינו יהודית באזני העם אשר על החומה׃ ");
INSERT INTO heb_vpl VALUES ("IS36_12","024_36_12","ISA","36","12","12","ויאמר רב שקה האל אדניך ואליך שלחני אדני לדבר את הדברים האלה הלא על האנשים הישבים על החומה לאכל את חראיהם ולשתות את שיניהם עמכם׃ ");
INSERT INTO heb_vpl VALUES ("IS36_13","024_36_13","ISA","36","13","13","ויעמד רב שקה ויקרא בקול גדול יהודית ויאמר שמעו את דברי המלך הגדול מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS36_14","024_36_14","ISA","36","14","14","כה אמר המלך אל ישא לכם חזקיהו כי לא יוכל להציל אתכם׃ ");
INSERT INTO heb_vpl VALUES ("IS36_15","024_36_15","ISA","36","15","15","ואל יבטח אתכם חזקיהו אל יהוה לאמר הצל יצילנו יהוה לא תנתן העיר הזאת ביד מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS36_16","024_36_16","ISA","36","16","16","אל תשמעו אל חזקיהו כי כה אמר המלך אשור עשו אתי ברכה וצאו אלי ואכלו איש גפנו ואיש תאנתו ושתו איש מי בורו׃ ");
INSERT INTO heb_vpl VALUES ("IS36_17","024_36_17","ISA","36","17","17","עד באי ולקחתי אתכם אל ארץ כארצכם ארץ דגן ותירוש ארץ לחם וכרמים׃ ");
INSERT INTO heb_vpl VALUES ("IS36_18","024_36_18","ISA","36","18","18","פן יסית אתכם חזקיהו לאמר יהוה יצילנו ההצילו אלהי הגוים איש את ארצו מיד מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS36_19","024_36_19","ISA","36","19","19","איה אלהי חמת וארפד איה אלהי ספרוים וכי הצילו את שמרון מידי׃ ");
INSERT INTO heb_vpl VALUES ("IS36_20","024_36_20","ISA","36","20","20","מי בכל אלהי הארצות האלה אשר הצילו את ארצם מידי כי יציל יהוה את ירושלם מידי׃ ");
INSERT INTO heb_vpl VALUES ("IS36_21","024_36_21","ISA","36","21","21","ויחרישו ולא ענו אתו דבר כי מצות המלך היא לאמר לא תענהו׃ ");
INSERT INTO heb_vpl VALUES ("IS36_22","024_36_22","ISA","36","22","22","ויבא אליקים בן חלקיהו אשר על הבית ושבנא הסופר ויואח בן אסף המזכיר אל חזקיהו קרועי בגדים ויגידו לו את דברי רב שקה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_1","024_37_1","ISA","37","1","1","ויהי כשמע המלך חזקיהו ויקרע את בגדיו ויתכס בשק ויבא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_2","024_37_2","ISA","37","2","2","וישלח את אליקים אשר על הבית ואת שבנא הסופר ואת זקני הכהנים מתכסים בשקים אל ישעיהו בן אמוץ הנביא׃ ");
INSERT INTO heb_vpl VALUES ("IS37_3","024_37_3","ISA","37","3","3","ויאמרו אליו כה אמר חזקיהו יום צרה ותוכחה ונאצה היום הזה כי באו בנים עד משבר וכח אין ללדה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_4","024_37_4","ISA","37","4","4","אולי ישמע יהוה אלהיך את דברי רב שקה אשר שלחו מלך אשור אדניו לחרף אלהים חי והוכיח בדברים אשר שמע יהוה אלהיך ונשאת תפלה בעד השארית הנמצאה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_5","024_37_5","ISA","37","5","5","ויבאו עבדי המלך חזקיהו אל ישעיהו׃ ");
INSERT INTO heb_vpl VALUES ("IS37_6","024_37_6","ISA","37","6","6","ויאמר אליהם ישעיהו כה תאמרון אל אדניכם כה אמר יהוה אל תירא מפני הדברים אשר שמעת אשר גדפו נערי מלך אשור אותי׃ ");
INSERT INTO heb_vpl VALUES ("IS37_7","024_37_7","ISA","37","7","7","הנני נותן בו רוח ושמע שמועה ושב אל ארצו והפלתיו בחרב בארצו׃ ");
INSERT INTO heb_vpl VALUES ("IS37_8","024_37_8","ISA","37","8","8","וישב רב שקה וימצא את מלך אשור נלחם על לבנה כי שמע כי נסע מלכיש׃ ");
INSERT INTO heb_vpl VALUES ("IS37_9","024_37_9","ISA","37","9","9","וישמע על תרהקה מלך כוש לאמר יצא להלחם אתך וישמע וישלח מלאכים אל חזקיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("IS37_10","024_37_10","ISA","37","10","10","כה תאמרון אל חזקיהו מלך יהודה לאמר אל ישאך אלהיך אשר אתה בוטח בו לאמר לא תנתן ירושלם ביד מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS37_11","024_37_11","ISA","37","11","11","הנה אתה שמעת אשר עשו מלכי אשור לכל הארצות להחרימם ואתה תנצל׃ ");
INSERT INTO heb_vpl VALUES ("IS37_12","024_37_12","ISA","37","12","12","ההצילו אותם אלהי הגוים אשר השחיתו אבותי את גוזן ואת חרן ורצף ובני עדן אשר בתלשר׃ ");
INSERT INTO heb_vpl VALUES ("IS37_13","024_37_13","ISA","37","13","13","איה מלך חמת ומלך ארפד ומלך לעיר ספרוים הנע ועוה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_14","024_37_14","ISA","37","14","14","ויקח חזקיהו את הספרים מיד המלאכים ויקראהו ויעל בית יהוה ויפרשהו חזקיהו לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_15","024_37_15","ISA","37","15","15","ויתפלל חזקיהו אל יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("IS37_16","024_37_16","ISA","37","16","16","יהוה צבאות אלהי ישראל ישב הכרבים אתה הוא האלהים לבדך לכל ממלכות הארץ אתה עשית את השמים ואת הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS37_17","024_37_17","ISA","37","17","17","הטה יהוה אזנך ושמע פקח יהוה עינך וראה ושמע את כל דברי סנחריב אשר שלח לחרף אלהים חי׃ ");
INSERT INTO heb_vpl VALUES ("IS37_18","024_37_18","ISA","37","18","18","אמנם יהוה החריבו מלכי אשור את כל הארצות ואת ארצם׃ ");
INSERT INTO heb_vpl VALUES ("IS37_19","024_37_19","ISA","37","19","19","ונתן את אלהיהם באש כי לא אלהים המה כי אם מעשה ידי אדם עץ ואבן ויאבדום׃ ");
INSERT INTO heb_vpl VALUES ("IS37_20","024_37_20","ISA","37","20","20","ועתה יהוה אלהינו הושיענו מידו וידעו כל ממלכות הארץ כי אתה יהוה לבדך׃ ");
INSERT INTO heb_vpl VALUES ("IS37_21","024_37_21","ISA","37","21","21","וישלח ישעיהו בן אמוץ אל חזקיהו לאמר כה אמר יהוה אלהי ישראל אשר התפללת אלי אל סנחריב מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("IS37_22","024_37_22","ISA","37","22","22","זה הדבר אשר דבר יהוה עליו בזה לך לעגה לך בתולת בת ציון אחריך ראש הניעה בת ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS37_23","024_37_23","ISA","37","23","23","את מי חרפת וגדפת ועל מי הרימותה קול ותשא מרום עיניך אל קדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS37_24","024_37_24","ISA","37","24","24","ביד עבדיך חרפת אדני ותאמר ברב רכבי אני עליתי מרום הרים ירכתי לבנון ואכרת קומת ארזיו מבחר ברשיו ואבוא מרום קצו יער כרמלו׃ ");
INSERT INTO heb_vpl VALUES ("IS37_25","024_37_25","ISA","37","25","25","אני קרתי ושתיתי מים ואחרב בכף פעמי כל יארי מצור׃ ");
INSERT INTO heb_vpl VALUES ("IS37_26","024_37_26","ISA","37","26","26","הלוא שמעת למרחוק אותה עשיתי מימי קדם ויצרתיה עתה הבאתיה ותהי להשאות גלים נצים ערים בצרות׃ ");
INSERT INTO heb_vpl VALUES ("IS37_27","024_37_27","ISA","37","27","27","וישביהן קצרי יד חתו ובשו היו עשב שדה וירק דשא חציר גגות ושדמה לפני קמה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_28","024_37_28","ISA","37","28","28","ושבתך וצאתך ובואך ידעתי ואת התרגזך אלי׃ ");
INSERT INTO heb_vpl VALUES ("IS37_29","024_37_29","ISA","37","29","29","יען התרגזך אלי ושאננך עלה באזני ושמתי חחי באפך ומתגי בשפתיך והשיבתיך בדרך אשר באת בה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_30","024_37_30","ISA","37","30","30","וזה לך האות אכול השנה ספיח ובשנה השנית שחיס ובשנה השלישית זרעו וקצרו ונטעו כרמים ואכול פרים׃ ");
INSERT INTO heb_vpl VALUES ("IS37_31","024_37_31","ISA","37","31","31","ויספה פליטת בית יהודה הנשארה שרש למטה ועשה פרי למעלה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_32","024_37_32","ISA","37","32","32","כי מירושלם תצא שארית ופליטה מהר ציון קנאת יהוה צבאות תעשה זאת׃ ");
INSERT INTO heb_vpl VALUES ("IS37_33","024_37_33","ISA","37","33","33","לכן כה אמר יהוה אל מלך אשור לא יבוא אל העיר הזאת ולא יורה שם חץ ולא יקדמנה מגן ולא ישפך עליה סללה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_34","024_37_34","ISA","37","34","34","בדרך אשר בא בה ישוב ואל העיר הזאת לא יבוא נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_35","024_37_35","ISA","37","35","35","וגנותי על העיר הזאת להושיעה למעני ולמען דוד עבדי׃ ");
INSERT INTO heb_vpl VALUES ("IS37_36","024_37_36","ISA","37","36","36","ויצא מלאך יהוה ויכה במחנה אשור מאה ושמנים וחמשה אלף וישכימו בבקר והנה כלם פגרים מתים׃ ");
INSERT INTO heb_vpl VALUES ("IS37_37","024_37_37","ISA","37","37","37","ויסע וילך וישב סנחריב מלך אשור וישב בנינוה׃ ");
INSERT INTO heb_vpl VALUES ("IS37_38","024_37_38","ISA","37","38","38","ויהי הוא משתחוה בית נסרך אלהיו ואדרמלך ושראצר בניו הכהו בחרב והמה נמלטו ארץ אררט וימלך אסר חדן בנו תחתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS38_1","024_38_1","ISA","38","1","1","בימים ההם חלה חזקיהו למות ויבוא אליו ישעיהו בן אמוץ הנביא ויאמר אליו כה אמר יהוה צו לביתך כי מת אתה ולא תחיה׃ ");
INSERT INTO heb_vpl VALUES ("IS38_2","024_38_2","ISA","38","2","2","ויסב חזקיהו פניו אל הקיר ויתפלל אל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS38_3","024_38_3","ISA","38","3","3","ויאמר אנה יהוה זכר נא את אשר התהלכתי לפניך באמת ובלב שלם והטוב בעיניך עשיתי ויבך חזקיהו בכי גדול׃ ");
INSERT INTO heb_vpl VALUES ("IS38_4","024_38_4","ISA","38","4","4","ויהי דבר יהוה אל ישעיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("IS38_5","024_38_5","ISA","38","5","5","הלוך ואמרת אל חזקיהו כה אמר יהוה אלהי דוד אביך שמעתי את תפלתך ראיתי את דמעתך הנני יוסף על ימיך חמש עשרה שנה׃ ");
INSERT INTO heb_vpl VALUES ("IS38_6","024_38_6","ISA","38","6","6","ומכף מלך אשור אצילך ואת העיר הזאת וגנותי על העיר הזאת׃ ");
INSERT INTO heb_vpl VALUES ("IS38_7","024_38_7","ISA","38","7","7","וזה לך האות מאת יהוה אשר יעשה יהוה את הדבר הזה אשר דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS38_8","024_38_8","ISA","38","8","8","הנני משיב את צל המעלות אשר ירדה במעלות אחז בשמש אחרנית עשר מעלות ותשב השמש עשר מעלות במעלות אשר ירדה׃ ");
INSERT INTO heb_vpl VALUES ("IS38_9","024_38_9","ISA","38","9","9","מכתב לחזקיהו מלך יהודה בחלתו ויחי מחליו׃ ");
INSERT INTO heb_vpl VALUES ("IS38_10","024_38_10","ISA","38","10","10","אני אמרתי בדמי ימי אלכה בשערי שאול פקדתי יתר שנותי׃ ");
INSERT INTO heb_vpl VALUES ("IS38_11","024_38_11","ISA","38","11","11","אמרתי לא אראה יה יה בארץ החיים לא אביט אדם עוד עם יושבי חדל׃ ");
INSERT INTO heb_vpl VALUES ("IS38_12","024_38_12","ISA","38","12","12","דורי נסע ונגלה מני כאהל רעי קפדתי כארג חיי מדלה יבצעני מיום עד לילה תשלימני׃ ");
INSERT INTO heb_vpl VALUES ("IS38_13","024_38_13","ISA","38","13","13","שויתי עד בקר כארי כן ישבר כל עצמותי מיום עד לילה תשלימני׃ ");
INSERT INTO heb_vpl VALUES ("IS38_14","024_38_14","ISA","38","14","14","כסוס עגור כן אצפצף אהגה כיונה דלו עיני למרום אדני עשקה לי ערבני׃ ");
INSERT INTO heb_vpl VALUES ("IS38_15","024_38_15","ISA","38","15","15","מה אדבר ואמר לי והוא עשה אדדה כל שנותי על מר נפשי׃ ");
INSERT INTO heb_vpl VALUES ("IS38_16","024_38_16","ISA","38","16","16","אדני עליהם יחיו ולכל בהן חיי רוחי ותחלימני והחיני׃ ");
INSERT INTO heb_vpl VALUES ("IS38_17","024_38_17","ISA","38","17","17","הנה לשלום מר לי מר ואתה חשקת נפשי משחת בלי כי השלכת אחרי גוך כל חטאי׃ ");
INSERT INTO heb_vpl VALUES ("IS38_18","024_38_18","ISA","38","18","18","כי לא שאול תודך מות יהללך לא ישברו יורדי בור אל אמתך׃ ");
INSERT INTO heb_vpl VALUES ("IS38_19","024_38_19","ISA","38","19","19","חי חי הוא יודך כמוני היום אב לבנים יודיע אל אמתך׃ ");
INSERT INTO heb_vpl VALUES ("IS38_20","024_38_20","ISA","38","20","20","יהוה להושיעני ונגנותי ננגן כל ימי חיינו על בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS38_21","024_38_21","ISA","38","21","21","ויאמר ישעיהו ישאו דבלת תאנים וימרחו על השחין ויחי׃ ");
INSERT INTO heb_vpl VALUES ("IS38_22","024_38_22","ISA","38","22","22","ויאמר חזקיהו מה אות כי אעלה בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS39_1","024_39_1","ISA","39","1","1","בעת ההיא שלח מרדך בלאדן בן בלאדן מלך בבל ספרים ומנחה אל חזקיהו וישמע כי חלה ויחזק׃ ");
INSERT INTO heb_vpl VALUES ("IS39_2","024_39_2","ISA","39","2","2","וישמח עליהם חזקיהו ויראם את בית נכתה את הכסף ואת הזהב ואת הבשמים ואת השמן הטוב ואת כל בית כליו ואת כל אשר נמצא באצרתיו לא היה דבר אשר לא הראם חזקיהו בביתו ובכל ממשלתו׃ ");
INSERT INTO heb_vpl VALUES ("IS39_3","024_39_3","ISA","39","3","3","ויבא ישעיהו הנביא אל המלך חזקיהו ויאמר אליו מה אמרו האנשים האלה ומאין יבאו אליך ויאמר חזקיהו מארץ רחוקה באו אלי מבבל׃ ");
INSERT INTO heb_vpl VALUES ("IS39_4","024_39_4","ISA","39","4","4","ויאמר מה ראו בביתך ויאמר חזקיהו את כל אשר בביתי ראו לא היה דבר אשר לא הראיתים באוצרתי׃ ");
INSERT INTO heb_vpl VALUES ("IS39_5","024_39_5","ISA","39","5","5","ויאמר ישעיהו אל חזקיהו שמע דבר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("IS39_6","024_39_6","ISA","39","6","6","הנה ימים באים ונשא כל אשר בביתך ואשר אצרו אבתיך עד היום הזה בבל לא יותר דבר אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS39_7","024_39_7","ISA","39","7","7","ומבניך אשר יצאו ממך אשר תוליד יקחו והיו סריסים בהיכל מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("IS39_8","024_39_8","ISA","39","8","8","ויאמר חזקיהו אל ישעיהו טוב דבר יהוה אשר דברת ויאמר כי יהיה שלום ואמת בימי׃ ");
INSERT INTO heb_vpl VALUES ("IS40_1","024_40_1","ISA","40","1","1","נחמו נחמו עמי יאמר אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("IS40_2","024_40_2","ISA","40","2","2","דברו על לב ירושלם וקראו אליה כי מלאה צבאה כי נרצה עונה כי לקחה מיד יהוה כפלים בכל חטאתיה׃ ");
INSERT INTO heb_vpl VALUES ("IS40_3","024_40_3","ISA","40","3","3","קול קורא במדבר פנו דרך יהוה ישרו בערבה מסלה לאלהינו׃ ");
INSERT INTO heb_vpl VALUES ("IS40_4","024_40_4","ISA","40","4","4","כל גיא ינשא וכל הר וגבעה ישפלו והיה העקב למישור והרכסים לבקעה׃ ");
INSERT INTO heb_vpl VALUES ("IS40_5","024_40_5","ISA","40","5","5","ונגלה כבוד יהוה וראו כל בשר יחדו כי פי יהוה דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS40_6","024_40_6","ISA","40","6","6","קול אמר קרא ואמר מה אקרא כל הבשר חציר וכל חסדו כציץ השדה׃ ");
INSERT INTO heb_vpl VALUES ("IS40_7","024_40_7","ISA","40","7","7","יבש חציר נבל ציץ כי רוח יהוה נשבה בו אכן חציר העם׃ ");
INSERT INTO heb_vpl VALUES ("IS40_8","024_40_8","ISA","40","8","8","יבש חציר נבל ציץ ודבר אלהינו יקום לעולם׃ ");
INSERT INTO heb_vpl VALUES ("IS40_9","024_40_9","ISA","40","9","9","על הר גבה עלי לך מבשרת ציון הרימי בכח קולך מבשרת ירושלם הרימי אל תיראי אמרי לערי יהודה הנה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("IS40_10","024_40_10","ISA","40","10","10","הנה אדני יהוה בחזק יבוא וזרעו משלה לו הנה שכרו אתו ופעלתו לפניו׃ ");
INSERT INTO heb_vpl VALUES ("IS40_11","024_40_11","ISA","40","11","11","כרעה עדרו ירעה בזרעו יקבץ טלאים ובחיקו ישא עלות ינהל׃ ");
INSERT INTO heb_vpl VALUES ("IS40_12","024_40_12","ISA","40","12","12","מי מדד בשעלו מים ושמים בזרת תכן וכל בשלש עפר הארץ ושקל בפלס הרים וגבעות במאזנים׃ ");
INSERT INTO heb_vpl VALUES ("IS40_13","024_40_13","ISA","40","13","13","מי תכן את רוח יהוה ואיש עצתו יודיענו׃ ");
INSERT INTO heb_vpl VALUES ("IS40_14","024_40_14","ISA","40","14","14","את מי נועץ ויבינהו וילמדהו בארח משפט וילמדהו דעת ודרך תבונות יודיענו׃ ");
INSERT INTO heb_vpl VALUES ("IS40_15","024_40_15","ISA","40","15","15","הן גוים כמר מדלי וכשחק מאזנים נחשבו הן איים כדק יטול׃ ");
INSERT INTO heb_vpl VALUES ("IS40_16","024_40_16","ISA","40","16","16","ולבנון אין די בער וחיתו אין די עולה׃ ");
INSERT INTO heb_vpl VALUES ("IS40_17","024_40_17","ISA","40","17","17","כל הגוים כאין נגדו מאפס ותהו נחשבו לו׃ ");
INSERT INTO heb_vpl VALUES ("IS40_18","024_40_18","ISA","40","18","18","ואל מי תדמיון אל ומה דמות תערכו לו׃ ");
INSERT INTO heb_vpl VALUES ("IS40_19","024_40_19","ISA","40","19","19","הפסל נסך חרש וצרף בזהב ירקענו ורתקות כסף צורף׃ ");
INSERT INTO heb_vpl VALUES ("IS40_20","024_40_20","ISA","40","20","20","המסכן תרומה עץ לא ירקב יבחר חרש חכם יבקש לו להכין פסל לא ימוט׃ ");
INSERT INTO heb_vpl VALUES ("IS40_21","024_40_21","ISA","40","21","21","הלוא תדעו הלוא תשמעו הלוא הגד מראש לכם הלוא הבינתם מוסדות הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS40_22","024_40_22","ISA","40","22","22","הישב על חוג הארץ וישביה כחגבים הנוטה כדק שמים וימתחם כאהל לשבת׃ ");
INSERT INTO heb_vpl VALUES ("IS40_23","024_40_23","ISA","40","23","23","הנותן רוזנים לאין שפטי ארץ כתהו עשה׃ ");
INSERT INTO heb_vpl VALUES ("IS40_24","024_40_24","ISA","40","24","24","אף בל נטעו אף בל זרעו אף בל שרש בארץ גזעם וגם נשף בהם ויבשו וסערה כקש תשאם׃ ");
INSERT INTO heb_vpl VALUES ("IS40_25","024_40_25","ISA","40","25","25","ואל מי תדמיוני ואשוה יאמר קדוש׃ ");
INSERT INTO heb_vpl VALUES ("IS40_26","024_40_26","ISA","40","26","26","שאו מרום עיניכם וראו מי ברא אלה המוציא במספר צבאם לכלם בשם יקרא מרב אונים ואמיץ כח איש לא נעדר׃ ");
INSERT INTO heb_vpl VALUES ("IS40_27","024_40_27","ISA","40","27","27","למה תאמר יעקב ותדבר ישראל נסתרה דרכי מיהוה ומאלהי משפטי יעבור׃ ");
INSERT INTO heb_vpl VALUES ("IS40_28","024_40_28","ISA","40","28","28","הלוא ידעת אם לא שמעת אלהי עולם יהוה בורא קצות הארץ לא ייעף ולא ייגע אין חקר לתבונתו׃ ");
INSERT INTO heb_vpl VALUES ("IS40_29","024_40_29","ISA","40","29","29","נתן ליעף כח ולאין אונים עצמה ירבה׃ ");
INSERT INTO heb_vpl VALUES ("IS40_30","024_40_30","ISA","40","30","30","ויעפו נערים ויגעו ובחורים כשול יכשלו׃ ");
INSERT INTO heb_vpl VALUES ("IS40_31","024_40_31","ISA","40","31","31","וקוי יהוה יחליפו כח יעלו אבר כנשרים ירוצו ולא ייגעו ילכו ולא ייעפו׃ ");
INSERT INTO heb_vpl VALUES ("IS41_1","024_41_1","ISA","41","1","1","החרישו אלי איים ולאמים יחליפו כח יגשו אז ידברו יחדו למשפט נקרבה׃ ");
INSERT INTO heb_vpl VALUES ("IS41_2","024_41_2","ISA","41","2","2","מי העיר ממזרח צדק יקראהו לרגלו יתן לפניו גוים ומלכים ירד יתן כעפר חרבו כקש נדף קשתו׃ ");
INSERT INTO heb_vpl VALUES ("IS41_3","024_41_3","ISA","41","3","3","ירדפם יעבור שלום ארח ברגליו לא יבוא׃ ");
INSERT INTO heb_vpl VALUES ("IS41_4","024_41_4","ISA","41","4","4","מי פעל ועשה קרא הדרות מראש אני יהוה ראשון ואת אחרנים אני הוא׃ ");
INSERT INTO heb_vpl VALUES ("IS41_5","024_41_5","ISA","41","5","5","ראו איים וייראו קצות הארץ יחרדו קרבו ויאתיון׃ ");
INSERT INTO heb_vpl VALUES ("IS41_6","024_41_6","ISA","41","6","6","איש את רעהו יעזרו ולאחיו יאמר חזק׃ ");
INSERT INTO heb_vpl VALUES ("IS41_7","024_41_7","ISA","41","7","7","ויחזק חרש את צרף מחליק פטיש את הולם פעם אמר לדבק טוב הוא ויחזקהו במסמרים לא ימוט׃ ");
INSERT INTO heb_vpl VALUES ("IS41_8","024_41_8","ISA","41","8","8","ואתה ישראל עבדי יעקב אשר בחרתיך זרע אברהם אהבי׃ ");
INSERT INTO heb_vpl VALUES ("IS41_9","024_41_9","ISA","41","9","9","אשר החזקתיך מקצות הארץ ומאציליה קראתיך ואמר לך עבדי אתה בחרתיך ולא מאסתיך׃ ");
INSERT INTO heb_vpl VALUES ("IS41_10","024_41_10","ISA","41","10","10","אל תירא כי עמך אני אל תשתע כי אני אלהיך אמצתיך אף עזרתיך אף תמכתיך בימין צדקי׃ ");
INSERT INTO heb_vpl VALUES ("IS41_11","024_41_11","ISA","41","11","11","הן יבשו ויכלמו כל הנחרים בך יהיו כאין ויאבדו אנשי ריבך׃ ");
INSERT INTO heb_vpl VALUES ("IS41_12","024_41_12","ISA","41","12","12","תבקשם ולא תמצאם אנשי מצתך יהיו כאין וכאפס אנשי מלחמתך׃ ");
INSERT INTO heb_vpl VALUES ("IS41_13","024_41_13","ISA","41","13","13","כי אני יהוה אלהיך מחזיק ימינך האמר לך אל תירא אני עזרתיך׃ ");
INSERT INTO heb_vpl VALUES ("IS41_14","024_41_14","ISA","41","14","14","אל תיראי תולעת יעקב מתי ישראל אני עזרתיך נאם יהוה וגאלך קדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS41_15","024_41_15","ISA","41","15","15","הנה שמתיך למורג חרוץ חדש בעל פיפיות תדוש הרים ותדק וגבעות כמץ תשים׃ ");
INSERT INTO heb_vpl VALUES ("IS41_16","024_41_16","ISA","41","16","16","תזרם ורוח תשאם וסערה תפיץ אותם ואתה תגיל ביהוה בקדוש ישראל תתהלל׃ ");
INSERT INTO heb_vpl VALUES ("IS41_17","024_41_17","ISA","41","17","17","העניים והאביונים מבקשים מים ואין לשונם בצמא נשתה אני יהוה אענם אלהי ישראל לא אעזבם׃ ");
INSERT INTO heb_vpl VALUES ("IS41_18","024_41_18","ISA","41","18","18","אפתח על שפיים נהרות ובתוך בקעות מעינות אשים מדבר לאגם מים וארץ ציה למוצאי מים׃ ");
INSERT INTO heb_vpl VALUES ("IS41_19","024_41_19","ISA","41","19","19","אתן במדבר ארז שטה והדס ועץ שמן אשים בערבה ברוש תדהר ותאשור יחדו׃ ");
INSERT INTO heb_vpl VALUES ("IS41_20","024_41_20","ISA","41","20","20","למען יראו וידעו וישימו וישכילו יחדו כי יד יהוה עשתה זאת וקדוש ישראל בראה׃ ");
INSERT INTO heb_vpl VALUES ("IS41_21","024_41_21","ISA","41","21","21","קרבו ריבכם יאמר יהוה הגישו עצמותיכם יאמר מלך יעקב׃ ");
INSERT INTO heb_vpl VALUES ("IS41_22","024_41_22","ISA","41","22","22","יגישו ויגידו לנו את אשר תקרינה הראשנות מה הנה הגידו ונשימה לבנו ונדעה אחריתן או הבאות השמיענו׃ ");
INSERT INTO heb_vpl VALUES ("IS41_23","024_41_23","ISA","41","23","23","הגידו האתיות לאחור ונדעה כי אלהים אתם אף תיטיבו ותרעו ונשתעה ונרא יחדו׃ ");
INSERT INTO heb_vpl VALUES ("IS41_24","024_41_24","ISA","41","24","24","הן אתם מאין ופעלכם מאפע תועבה יבחר בכם׃ ");
INSERT INTO heb_vpl VALUES ("IS41_25","024_41_25","ISA","41","25","25","העירותי מצפון ויאת ממזרח שמש יקרא בשמי ויבא סגנים כמו חמר וכמו יוצר ירמס טיט׃ ");
INSERT INTO heb_vpl VALUES ("IS41_26","024_41_26","ISA","41","26","26","מי הגיד מראש ונדעה ומלפנים ונאמר צדיק אף אין מגיד אף אין משמיע אף אין שמע אמריכם׃ ");
INSERT INTO heb_vpl VALUES ("IS41_27","024_41_27","ISA","41","27","27","ראשון לציון הנה הנם ולירושלם מבשר אתן׃ ");
INSERT INTO heb_vpl VALUES ("IS41_28","024_41_28","ISA","41","28","28","וארא ואין איש ומאלה ואין יועץ ואשאלם וישיבו דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS41_29","024_41_29","ISA","41","29","29","הן כלם און אפס מעשיהם רוח ותהו נסכיהם׃ ");
INSERT INTO heb_vpl VALUES ("IS42_1","024_42_1","ISA","42","1","1","הן עבדי אתמך בו בחירי רצתה נפשי נתתי רוחי עליו משפט לגוים יוציא׃ ");
INSERT INTO heb_vpl VALUES ("IS42_2","024_42_2","ISA","42","2","2","לא יצעק ולא ישא ולא ישמיע בחוץ קולו׃ ");
INSERT INTO heb_vpl VALUES ("IS42_3","024_42_3","ISA","42","3","3","קנה רצוץ לא ישבור ופשתה כהה לא יכבנה לאמת יוציא משפט׃ ");
INSERT INTO heb_vpl VALUES ("IS42_4","024_42_4","ISA","42","4","4","לא יכהה ולא ירוץ עד ישים בארץ משפט ולתורתו איים ייחילו׃ ");
INSERT INTO heb_vpl VALUES ("IS42_5","024_42_5","ISA","42","5","5","כה אמר האל יהוה בורא השמים ונוטיהם רקע הארץ וצאצאיה נתן נשמה לעם עליה ורוח להלכים בה׃ ");
INSERT INTO heb_vpl VALUES ("IS42_6","024_42_6","ISA","42","6","6","אני יהוה קראתיך בצדק ואחזק בידך ואצרך ואתנך לברית עם לאור גוים׃ ");
INSERT INTO heb_vpl VALUES ("IS42_7","024_42_7","ISA","42","7","7","לפקח עינים עורות להוציא ממסגר אסיר מבית כלא ישבי חשך׃ ");
INSERT INTO heb_vpl VALUES ("IS42_8","024_42_8","ISA","42","8","8","אני יהוה הוא שמי וכבודי לאחר לא אתן ותהלתי לפסילים׃ ");
INSERT INTO heb_vpl VALUES ("IS42_9","024_42_9","ISA","42","9","9","הראשנות הנה באו וחדשות אני מגיד בטרם תצמחנה אשמיע אתכם׃ ");
INSERT INTO heb_vpl VALUES ("IS42_10","024_42_10","ISA","42","10","10","שירו ליהוה שיר חדש תהלתו מקצה הארץ יורדי הים ומלאו איים וישביהם׃ ");
INSERT INTO heb_vpl VALUES ("IS42_11","024_42_11","ISA","42","11","11","ישאו מדבר ועריו חצרים תשב קדר ירנו ישבי סלע מראש הרים יצוחו׃ ");
INSERT INTO heb_vpl VALUES ("IS42_12","024_42_12","ISA","42","12","12","ישימו ליהוה כבוד ותהלתו באיים יגידו׃ ");
INSERT INTO heb_vpl VALUES ("IS42_13","024_42_13","ISA","42","13","13","יהוה כגבור יצא כאיש מלחמות יעיר קנאה יריע אף יצריח על איביו יתגבר׃ ");
INSERT INTO heb_vpl VALUES ("IS42_14","024_42_14","ISA","42","14","14","החשיתי מעולם אחריש אתאפק כיולדה אפעה אשם ואשאף יחד׃ ");
INSERT INTO heb_vpl VALUES ("IS42_15","024_42_15","ISA","42","15","15","אחריב הרים וגבעות וכל עשבם אוביש ושמתי נהרות לאיים ואגמים אוביש׃ ");
INSERT INTO heb_vpl VALUES ("IS42_16","024_42_16","ISA","42","16","16","והולכתי עורים בדרך לא ידעו בנתיבות לא ידעו אדריכם אשים מחשך לפניהם לאור ומעקשים למישור אלה הדברים עשיתם ולא עזבתים׃ ");
INSERT INTO heb_vpl VALUES ("IS42_17","024_42_17","ISA","42","17","17","נסגו אחור יבשו בשת הבטחים בפסל האמרים למסכה אתם אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("IS42_18","024_42_18","ISA","42","18","18","החרשים שמעו והעורים הביטו לראות׃ ");
INSERT INTO heb_vpl VALUES ("IS42_19","024_42_19","ISA","42","19","19","מי עור כי אם עבדי וחרש כמלאכי אשלח מי עור כמשלם ועור כעבד יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS42_20","024_42_20","ISA","42","20","20","ראית רבות ולא תשמר פקוח אזנים ולא ישמע׃ ");
INSERT INTO heb_vpl VALUES ("IS42_21","024_42_21","ISA","42","21","21","יהוה חפץ למען צדקו יגדיל תורה ויאדיר׃ ");
INSERT INTO heb_vpl VALUES ("IS42_22","024_42_22","ISA","42","22","22","והוא עם בזוז ושסוי הפח בחורים כלם ובבתי כלאים החבאו היו לבז ואין מציל משסה ואין אמר השב׃ ");
INSERT INTO heb_vpl VALUES ("IS42_23","024_42_23","ISA","42","23","23","מי בכם יאזין זאת יקשב וישמע לאחור׃ ");
INSERT INTO heb_vpl VALUES ("IS42_24","024_42_24","ISA","42","24","24","מי נתן למשוסה יעקב וישראל לבזזים הלוא יהוה זו חטאנו לו ולא אבו בדרכיו הלוך ולא שמעו בתורתו׃ ");
INSERT INTO heb_vpl VALUES ("IS42_25","024_42_25","ISA","42","25","25","וישפך עליו חמה אפו ועזוז מלחמה ותלהטהו מסביב ולא ידע ותבער בו ולא ישים על לב׃ ");
INSERT INTO heb_vpl VALUES ("IS43_1","024_43_1","ISA","43","1","1","ועתה כה אמר יהוה בראך יעקב ויצרך ישראל אל תירא כי גאלתיך קראתי בשמך לי אתה׃ ");
INSERT INTO heb_vpl VALUES ("IS43_2","024_43_2","ISA","43","2","2","כי תעבר במים אתך אני ובנהרות לא ישטפוך כי תלך במו אש לא תכוה ולהבה לא תבער בך׃ ");
INSERT INTO heb_vpl VALUES ("IS43_3","024_43_3","ISA","43","3","3","כי אני יהוה אלהיך קדוש ישראל מושיעך נתתי כפרך מצרים כוש וסבא תחתיך׃ ");
INSERT INTO heb_vpl VALUES ("IS43_4","024_43_4","ISA","43","4","4","מאשר יקרת בעיני נכבדת ואני אהבתיך ואתן אדם תחתיך ולאמים תחת נפשך׃ ");
INSERT INTO heb_vpl VALUES ("IS43_5","024_43_5","ISA","43","5","5","אל תירא כי אתך אני ממזרח אביא זרעך וממערב אקבצך׃ ");
INSERT INTO heb_vpl VALUES ("IS43_6","024_43_6","ISA","43","6","6","אמר לצפון תני ולתימן אל תכלאי הביאי בני מרחוק ובנותי מקצה הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS43_7","024_43_7","ISA","43","7","7","כל הנקרא בשמי ולכבודי בראתיו יצרתיו אף עשיתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS43_8","024_43_8","ISA","43","8","8","הוציא עם עור ועינים יש וחרשים ואזנים למו׃ ");
INSERT INTO heb_vpl VALUES ("IS43_9","024_43_9","ISA","43","9","9","כל הגוים נקבצו יחדו ויאספו לאמים מי בהם יגיד זאת וראשנות ישמיענו יתנו עדיהם ויצדקו וישמעו ויאמרו אמת׃ ");
INSERT INTO heb_vpl VALUES ("IS43_10","024_43_10","ISA","43","10","10","אתם עדי נאם יהוה ועבדי אשר בחרתי למען תדעו ותאמינו לי ותבינו כי אני הוא לפני לא נוצר אל ואחרי לא יהיה׃ ");
INSERT INTO heb_vpl VALUES ("IS43_11","024_43_11","ISA","43","11","11","אנכי אנכי יהוה ואין מבלעדי מושיע׃ ");
INSERT INTO heb_vpl VALUES ("IS43_12","024_43_12","ISA","43","12","12","אנכי הגדתי והושעתי והשמעתי ואין בכם זר ואתם עדי נאם יהוה ואני אל׃ ");
INSERT INTO heb_vpl VALUES ("IS43_13","024_43_13","ISA","43","13","13","גם מיום אני הוא ואין מידי מציל אפעל ומי ישיבנה׃ ");
INSERT INTO heb_vpl VALUES ("IS43_14","024_43_14","ISA","43","14","14","כה אמר יהוה גאלכם קדוש ישראל למענכם שלחתי בבלה והורדתי בריחים כלם וכשדים באניות רנתם׃ ");
INSERT INTO heb_vpl VALUES ("IS43_15","024_43_15","ISA","43","15","15","אני יהוה קדושכם בורא ישראל מלככם׃ ");
INSERT INTO heb_vpl VALUES ("IS43_16","024_43_16","ISA","43","16","16","כה אמר יהוה הנותן בים דרך ובמים עזים נתיבה׃ ");
INSERT INTO heb_vpl VALUES ("IS43_17","024_43_17","ISA","43","17","17","המוציא רכב וסוס חיל ועזוז יחדו ישכבו בל יקומו דעכו כפשתה כבו׃ ");
INSERT INTO heb_vpl VALUES ("IS43_18","024_43_18","ISA","43","18","18","אל תזכרו ראשנות וקדמניות אל תתבננו׃ ");
INSERT INTO heb_vpl VALUES ("IS43_19","024_43_19","ISA","43","19","19","הנני עשה חדשה עתה תצמח הלוא תדעוה אף אשים במדבר דרך בישמון נהרות׃ ");
INSERT INTO heb_vpl VALUES ("IS43_20","024_43_20","ISA","43","20","20","תכבדני חית השדה תנים ובנות יענה כי נתתי במדבר מים נהרות בישימן להשקות עמי בחירי׃ ");
INSERT INTO heb_vpl VALUES ("IS43_21","024_43_21","ISA","43","21","21","עם זו יצרתי לי תהלתי יספרו׃ ");
INSERT INTO heb_vpl VALUES ("IS43_22","024_43_22","ISA","43","22","22","ולא אתי קראת יעקב כי יגעת בי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS43_23","024_43_23","ISA","43","23","23","לא הביאת לי שה עלתיך וזבחיך לא כבדתני לא העבדתיך במנחה ולא הוגעתיך בלבונה׃ ");
INSERT INTO heb_vpl VALUES ("IS43_24","024_43_24","ISA","43","24","24","לא קנית לי בכסף קנה וחלב זבחיך לא הרויתני אך העבדתני בחטאותיך הוגעתני בעונתיך׃ ");
INSERT INTO heb_vpl VALUES ("IS43_25","024_43_25","ISA","43","25","25","אנכי אנכי הוא מחה פשעיך למעני וחטאתיך לא אזכר׃ ");
INSERT INTO heb_vpl VALUES ("IS43_26","024_43_26","ISA","43","26","26","הזכירני נשפטה יחד ספר אתה למען תצדק׃ ");
INSERT INTO heb_vpl VALUES ("IS43_27","024_43_27","ISA","43","27","27","אביך הראשון חטא ומליציך פשעו בי׃ ");
INSERT INTO heb_vpl VALUES ("IS43_28","024_43_28","ISA","43","28","28","ואחלל שרי קדש ואתנה לחרם יעקב וישראל לגדופים׃ ");
INSERT INTO heb_vpl VALUES ("IS44_1","024_44_1","ISA","44","1","1","ועתה שמע יעקב עבדי וישראל בחרתי בו׃ ");
INSERT INTO heb_vpl VALUES ("IS44_2","024_44_2","ISA","44","2","2","כה אמר יהוה עשך ויצרך מבטן יעזרך אל תירא עבדי יעקב וישרון בחרתי בו׃ ");
INSERT INTO heb_vpl VALUES ("IS44_3","024_44_3","ISA","44","3","3","כי אצק מים על צמא ונזלים על יבשה אצק רוחי על זרעך וברכתי על צאצאיך׃ ");
INSERT INTO heb_vpl VALUES ("IS44_4","024_44_4","ISA","44","4","4","וצמחו בבין חציר כערבים על יבלי מים׃ ");
INSERT INTO heb_vpl VALUES ("IS44_5","024_44_5","ISA","44","5","5","זה יאמר ליהוה אני וזה יקרא בשם יעקב וזה יכתב ידו ליהוה ובשם ישראל יכנה׃ ");
INSERT INTO heb_vpl VALUES ("IS44_6","024_44_6","ISA","44","6","6","כה אמר יהוה מלך ישראל וגאלו יהוה צבאות אני ראשון ואני אחרון ומבלעדי אין אלהים׃ ");
INSERT INTO heb_vpl VALUES ("IS44_7","024_44_7","ISA","44","7","7","ומי כמוני יקרא ויגידה ויערכה לי משומי עם עולם ואתיות ואשר תבאנה יגידו למו׃ ");
INSERT INTO heb_vpl VALUES ("IS44_8","024_44_8","ISA","44","8","8","אל תפחדו ואל תרהו הלא מאז השמעתיך והגדתי ואתם עדי היש אלוה מבלעדי ואין צור בל ידעתי׃ ");
INSERT INTO heb_vpl VALUES ("IS44_9","024_44_9","ISA","44","9","9","יצרי פסל כלם תהו וחמודיהם בל יועילו ועדיהם המה בל יראו ובל ידעו למען יבשו׃ ");
INSERT INTO heb_vpl VALUES ("IS44_10","024_44_10","ISA","44","10","10","מי יצר אל ופסל נסך לבלתי הועיל׃ ");
INSERT INTO heb_vpl VALUES ("IS44_11","024_44_11","ISA","44","11","11","הן כל חבריו יבשו וחרשים המה מאדם יתקבצו כלם יעמדו יפחדו יבשו יחד׃ ");
INSERT INTO heb_vpl VALUES ("IS44_12","024_44_12","ISA","44","12","12","חרש ברזל מעצד ופעל בפחם ובמקבות יצרהו ויפעלהו בזרוע כחו גם רעב ואין כח לא שתה מים וייעף׃ ");
INSERT INTO heb_vpl VALUES ("IS44_13","024_44_13","ISA","44","13","13","חרש עצים נטה קו יתארהו בשרד יעשהו במקצעות ובמחוגה יתארהו ויעשהו כתבנית איש כתפארת אדם לשבת בית׃ ");
INSERT INTO heb_vpl VALUES ("IS44_14","024_44_14","ISA","44","14","14","לכרת לו ארזים ויקח תרזה ואלון ויאמץ לו בעצי יער נטע ארן וגשם יגדל׃ ");
INSERT INTO heb_vpl VALUES ("IS44_15","024_44_15","ISA","44","15","15","והיה לאדם לבער ויקח מהם ויחם אף ישיק ואפה לחם אף יפעל אל וישתחו עשהו פסל ויסגד למו׃ ");
INSERT INTO heb_vpl VALUES ("IS44_16","024_44_16","ISA","44","16","16","חציו שרף במו אש על חציו בשר יאכל יצלה צלי וישבע אף יחם ויאמר האח חמותי ראיתי אור׃ ");
INSERT INTO heb_vpl VALUES ("IS44_17","024_44_17","ISA","44","17","17","ושאריתו לאל עשה לפסלו יסגוד לו וישתחו ויתפלל אליו ויאמר הצילני כי אלי אתה׃ ");
INSERT INTO heb_vpl VALUES ("IS44_18","024_44_18","ISA","44","18","18","לא ידעו ולא יבינו כי טח מראות עיניהם מהשכיל לבתם׃ ");
INSERT INTO heb_vpl VALUES ("IS44_19","024_44_19","ISA","44","19","19","ולא ישיב אל לבו ולא דעת ולא תבונה לאמר חציו שרפתי במו אש ואף אפיתי על גחליו לחם אצלה בשר ואכל ויתרו לתועבה אעשה לבול עץ אסגוד׃ ");
INSERT INTO heb_vpl VALUES ("IS44_20","024_44_20","ISA","44","20","20","רעה אפר לב הותל הטהו ולא יציל את נפשו ולא יאמר הלוא שקר בימיני׃ ");
INSERT INTO heb_vpl VALUES ("IS44_21","024_44_21","ISA","44","21","21","זכר אלה יעקב וישראל כי עבדי אתה יצרתיך עבד לי אתה ישראל לא תנשני׃ ");
INSERT INTO heb_vpl VALUES ("IS44_22","024_44_22","ISA","44","22","22","מחיתי כעב פשעיך וכענן חטאותיך שובה אלי כי גאלתיך׃ ");
INSERT INTO heb_vpl VALUES ("IS44_23","024_44_23","ISA","44","23","23","רנו שמים כי עשה יהוה הריעו תחתיות ארץ פצחו הרים רנה יער וכל עץ בו כי גאל יהוה יעקב ובישראל יתפאר׃ ");
INSERT INTO heb_vpl VALUES ("IS44_24","024_44_24","ISA","44","24","24","כה אמר יהוה גאלך ויצרך מבטן אנכי יהוה עשה כל נטה שמים לבדי רקע הארץ מי אתי׃ ");
INSERT INTO heb_vpl VALUES ("IS44_25","024_44_25","ISA","44","25","25","מפר אתות בדים וקסמים יהולל משיב חכמים אחור ודעתם ישכל׃ ");
INSERT INTO heb_vpl VALUES ("IS44_26","024_44_26","ISA","44","26","26","מקים דבר עבדו ועצת מלאכיו ישלים האמר לירושלם תושב ולערי יהודה תבנינה וחרבותיה אקומם׃ ");
INSERT INTO heb_vpl VALUES ("IS44_27","024_44_27","ISA","44","27","27","האמר לצולה חרבי ונהרתיך אוביש׃ ");
INSERT INTO heb_vpl VALUES ("IS44_28","024_44_28","ISA","44","28","28","האמר לכורש רעי וכל חפצי ישלם ולאמר לירושלם תבנה והיכל תוסד׃ ");
INSERT INTO heb_vpl VALUES ("IS45_1","024_45_1","ISA","45","1","1","כה אמר יהוה למשיחו לכורש אשר החזקתי בימינו לרד לפניו גוים ומתני מלכים אפתח לפתח לפניו דלתים ושערים לא יסגרו׃ ");
INSERT INTO heb_vpl VALUES ("IS45_2","024_45_2","ISA","45","2","2","אני לפניך אלך והדורים אושר דלתות נחושה אשבר ובריחי ברזל אגדע׃ ");
INSERT INTO heb_vpl VALUES ("IS45_3","024_45_3","ISA","45","3","3","ונתתי לך אוצרות חשך ומטמני מסתרים למען תדע כי אני יהוה הקורא בשמך אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS45_4","024_45_4","ISA","45","4","4","למען עבדי יעקב וישראל בחירי ואקרא לך בשמך אכנך ולא ידעתני׃ ");
INSERT INTO heb_vpl VALUES ("IS45_5","024_45_5","ISA","45","5","5","אני יהוה ואין עוד זולתי אין אלהים אאזרך ולא ידעתני׃ ");
INSERT INTO heb_vpl VALUES ("IS45_6","024_45_6","ISA","45","6","6","למען ידעו ממזרח שמש וממערבה כי אפס בלעדי אני יהוה ואין עוד׃ ");
INSERT INTO heb_vpl VALUES ("IS45_7","024_45_7","ISA","45","7","7","יוצר אור ובורא חשך עשה שלום ובורא רע אני יהוה עשה כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("IS45_8","024_45_8","ISA","45","8","8","הרעיפו שמים ממעל ושחקים יזלו צדק תפתח ארץ ויפרו ישע וצדקה תצמיח יחד אני יהוה בראתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS45_9","024_45_9","ISA","45","9","9","הוי רב את יצרו חרש את חרשי אדמה היאמר חמר ליצרו מה תעשה ופעלך אין ידים לו׃ ");
INSERT INTO heb_vpl VALUES ("IS45_10","024_45_10","ISA","45","10","10","הוי אמר לאב מה תוליד ולאשה מה תחילין׃ ");
INSERT INTO heb_vpl VALUES ("IS45_11","024_45_11","ISA","45","11","11","כה אמר יהוה קדוש ישראל ויצרו האתיות שאלוני על בני ועל פעל ידי תצוני׃ ");
INSERT INTO heb_vpl VALUES ("IS45_12","024_45_12","ISA","45","12","12","אנכי עשיתי ארץ ואדם עליה בראתי אני ידי נטו שמים וכל צבאם צויתי׃ ");
INSERT INTO heb_vpl VALUES ("IS45_13","024_45_13","ISA","45","13","13","אנכי העירתהו בצדק וכל דרכיו אישר הוא יבנה עירי וגלותי ישלח לא במחיר ולא בשחד אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("IS45_14","024_45_14","ISA","45","14","14","כה אמר יהוה יגיע מצרים וסחר כוש וסבאים אנשי מדה עליך יעברו ולך יהיו אחריך ילכו בזקים יעברו ואליך ישתחוו אליך יתפללו אך בך אל ואין עוד אפס אלהים׃ ");
INSERT INTO heb_vpl VALUES ("IS45_15","024_45_15","ISA","45","15","15","אכן אתה אל מסתתר אלהי ישראל מושיע׃ ");
INSERT INTO heb_vpl VALUES ("IS45_16","024_45_16","ISA","45","16","16","בושו וגם נכלמו כלם יחדו הלכו בכלמה חרשי צירים׃ ");
INSERT INTO heb_vpl VALUES ("IS45_17","024_45_17","ISA","45","17","17","ישראל נושע ביהוה תשועת עולמים לא תבשו ולא תכלמו עד עולמי עד׃ ");
INSERT INTO heb_vpl VALUES ("IS45_18","024_45_18","ISA","45","18","18","כי כה אמר יהוה בורא השמים הוא האלהים יצר הארץ ועשה הוא כוננה לא תהו בראה לשבת יצרה אני יהוה ואין עוד׃ ");
INSERT INTO heb_vpl VALUES ("IS45_19","024_45_19","ISA","45","19","19","לא בסתר דברתי במקום ארץ חשך לא אמרתי לזרע יעקב תהו בקשוני אני יהוה דבר צדק מגיד מישרים׃ ");
INSERT INTO heb_vpl VALUES ("IS45_20","024_45_20","ISA","45","20","20","הקבצו ובאו התנגשו יחדו פליטי הגוים לא ידעו הנשאים את עץ פסלם ומתפללים אל אל לא יושיע׃ ");
INSERT INTO heb_vpl VALUES ("IS45_21","024_45_21","ISA","45","21","21","הגידו והגישו אף יועצו יחדו מי השמיע זאת מקדם מאז הגידה הלוא אני יהוה ואין עוד אלהים מבלעדי אל צדיק ומושיע אין זולתי׃ ");
INSERT INTO heb_vpl VALUES ("IS45_22","024_45_22","ISA","45","22","22","פנו אלי והושעו כל אפסי ארץ כי אני אל ואין עוד׃ ");
INSERT INTO heb_vpl VALUES ("IS45_23","024_45_23","ISA","45","23","23","בי נשבעתי יצא מפי צדקה דבר ולא ישוב כי לי תכרע כל ברך תשבע כל לשון׃ ");
INSERT INTO heb_vpl VALUES ("IS45_24","024_45_24","ISA","45","24","24","אך ביהוה לי אמר צדקות ועז עדיו יבוא ויבשו כל הנחרים בו׃ ");
INSERT INTO heb_vpl VALUES ("IS45_25","024_45_25","ISA","45","25","25","ביהוה יצדקו ויתהללו כל זרע ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS46_1","024_46_1","ISA","46","1","1","כרע בל קרס נבו היו עצביהם לחיה ולבהמה נשאתיכם עמוסות משא לעיפה׃ ");
INSERT INTO heb_vpl VALUES ("IS46_2","024_46_2","ISA","46","2","2","קרסו כרעו יחדו לא יכלו מלט משא ונפשם בשבי הלכה׃ ");
INSERT INTO heb_vpl VALUES ("IS46_3","024_46_3","ISA","46","3","3","שמעו אלי בית יעקב וכל שארית בית ישראל העמסים מני בטן הנשאים מני רחם׃ ");
INSERT INTO heb_vpl VALUES ("IS46_4","024_46_4","ISA","46","4","4","ועד זקנה אני הוא ועד שיבה אני אסבל אני עשיתי ואני אשא ואני אסבל ואמלט׃ ");
INSERT INTO heb_vpl VALUES ("IS46_5","024_46_5","ISA","46","5","5","למי תדמיוני ותשוו ותמשלוני ונדמה׃ ");
INSERT INTO heb_vpl VALUES ("IS46_6","024_46_6","ISA","46","6","6","הזלים זהב מכיס וכסף בקנה ישקלו ישכרו צורף ויעשהו אל יסגדו אף ישתחוו׃ ");
INSERT INTO heb_vpl VALUES ("IS46_7","024_46_7","ISA","46","7","7","ישאהו על כתף יסבלהו ויניחהו תחתיו ויעמד ממקומו לא ימיש אף יצעק אליו ולא יענה מצרתו לא יושיענו׃ ");
INSERT INTO heb_vpl VALUES ("IS46_8","024_46_8","ISA","46","8","8","זכרו זאת והתאששו השיבו פושעים על לב׃ ");
INSERT INTO heb_vpl VALUES ("IS46_9","024_46_9","ISA","46","9","9","זכרו ראשנות מעולם כי אנכי אל ואין עוד אלהים ואפס כמוני׃ ");
INSERT INTO heb_vpl VALUES ("IS46_10","024_46_10","ISA","46","10","10","מגיד מראשית אחרית ומקדם אשר לא נעשו אמר עצתי תקום וכל חפצי אעשה׃ ");
INSERT INTO heb_vpl VALUES ("IS46_11","024_46_11","ISA","46","11","11","קרא ממזרח עיט מארץ מרחק איש עצתו אף דברתי אף אביאנה יצרתי אף אעשנה׃ ");
INSERT INTO heb_vpl VALUES ("IS46_12","024_46_12","ISA","46","12","12","שמעו אלי אבירי לב הרחוקים מצדקה׃ ");
INSERT INTO heb_vpl VALUES ("IS46_13","024_46_13","ISA","46","13","13","קרבתי צדקתי לא תרחק ותשועתי לא תאחר ונתתי בציון תשועה לישראל תפארתי׃ ");
INSERT INTO heb_vpl VALUES ("IS47_1","024_47_1","ISA","47","1","1","רדי ושבי על עפר בתולת בת בבל שבי לארץ אין כסא בת כשדים כי לא תוסיפי יקראו לך רכה וענגה׃ ");
INSERT INTO heb_vpl VALUES ("IS47_2","024_47_2","ISA","47","2","2","קחי רחים וטחני קמח גלי צמתך חשפי שבל גלי שוק עברי נהרות׃ ");
INSERT INTO heb_vpl VALUES ("IS47_3","024_47_3","ISA","47","3","3","תגל ערותך גם תראה חרפתך נקם אקח ולא אפגע אדם׃ ");
INSERT INTO heb_vpl VALUES ("IS47_4","024_47_4","ISA","47","4","4","גאלנו יהוה צבאות שמו קדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS47_5","024_47_5","ISA","47","5","5","שבי דומם ובאי בחשך בת כשדים כי לא תוסיפי יקראו לך גברת ממלכות׃ ");
INSERT INTO heb_vpl VALUES ("IS47_6","024_47_6","ISA","47","6","6","קצפתי על עמי חללתי נחלתי ואתנם בידך לא שמת להם רחמים על זקן הכבדת עלך מאד׃ ");
INSERT INTO heb_vpl VALUES ("IS47_7","024_47_7","ISA","47","7","7","ותאמרי לעולם אהיה גברת עד לא שמת אלה על לבך לא זכרת אחריתה׃ ");
INSERT INTO heb_vpl VALUES ("IS47_8","024_47_8","ISA","47","8","8","ועתה שמעי זאת עדינה היושבת לבטח האמרה בלבבה אני ואפסי עוד לא אשב אלמנה ולא אדע שכול׃ ");
INSERT INTO heb_vpl VALUES ("IS47_9","024_47_9","ISA","47","9","9","ותבאנה לך שתי אלה רגע ביום אחד שכול ואלמן כתמם באו עליך ברב כשפיך בעצמת חבריך מאד׃ ");
INSERT INTO heb_vpl VALUES ("IS47_10","024_47_10","ISA","47","10","10","ותבטחי ברעתך אמרת אין ראני חכמתך ודעתך היא שובבתך ותאמרי בלבך אני ואפסי עוד׃ ");
INSERT INTO heb_vpl VALUES ("IS47_11","024_47_11","ISA","47","11","11","ובא עליך רעה לא תדעי שחרה ותפל עליך הוה לא תוכלי כפרה ותבא עליך פתאם שואה לא תדעי׃ ");
INSERT INTO heb_vpl VALUES ("IS47_12","024_47_12","ISA","47","12","12","עמדי נא בחבריך וברב כשפיך באשר יגעת מנעוריך אולי תוכלי הועיל אולי תערוצי׃ ");
INSERT INTO heb_vpl VALUES ("IS47_13","024_47_13","ISA","47","13","13","נלאית ברב עצתיך יעמדו נא ויושיעך הברו שמים החזים בכוכבים מודיעם לחדשים מאשר יבאו עליך׃ ");
INSERT INTO heb_vpl VALUES ("IS47_14","024_47_14","ISA","47","14","14","הנה היו כקש אש שרפתם לא יצילו את נפשם מיד להבה אין גחלת לחמם אור לשבת נגדו׃ ");
INSERT INTO heb_vpl VALUES ("IS47_15","024_47_15","ISA","47","15","15","כן היו לך אשר יגעת סחריך מנעוריך איש לעברו תעו אין מושיעך׃ ");
INSERT INTO heb_vpl VALUES ("IS48_1","024_48_1","ISA","48","1","1","שמעו זאת בית יעקב הנקראים בשם ישראל וממי יהודה יצאו הנשבעים בשם יהוה ובאלהי ישראל יזכירו לא באמת ולא בצדקה׃ ");
INSERT INTO heb_vpl VALUES ("IS48_2","024_48_2","ISA","48","2","2","כי מעיר הקדש נקראו ועל אלהי ישראל נסמכו יהוה צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("IS48_3","024_48_3","ISA","48","3","3","הראשנות מאז הגדתי ומפי יצאו ואשמיעם פתאם עשיתי ותבאנה׃ ");
INSERT INTO heb_vpl VALUES ("IS48_4","024_48_4","ISA","48","4","4","מדעתי כי קשה אתה וגיד ברזל ערפך ומצחך נחושה׃ ");
INSERT INTO heb_vpl VALUES ("IS48_5","024_48_5","ISA","48","5","5","ואגיד לך מאז בטרם תבוא השמעתיך פן תאמר עצבי עשם ופסלי ונסכי צום׃ ");
INSERT INTO heb_vpl VALUES ("IS48_6","024_48_6","ISA","48","6","6","שמעת חזה כלה ואתם הלוא תגידו השמעתיך חדשות מעתה ונצרות ולא ידעתם׃ ");
INSERT INTO heb_vpl VALUES ("IS48_7","024_48_7","ISA","48","7","7","עתה נבראו ולא מאז ולפני יום ולא שמעתם פן תאמר הנה ידעתין׃ ");
INSERT INTO heb_vpl VALUES ("IS48_8","024_48_8","ISA","48","8","8","גם לא שמעת גם לא ידעת גם מאז לא פתחה אזנך כי ידעתי בגוד תבגוד ופשע מבטן קרא לך׃ ");
INSERT INTO heb_vpl VALUES ("IS48_9","024_48_9","ISA","48","9","9","למען שמי אאריך אפי ותהלתי אחטם לך לבלתי הכריתך׃ ");
INSERT INTO heb_vpl VALUES ("IS48_10","024_48_10","ISA","48","10","10","הנה צרפתיך ולא בכסף בחרתיך בכור עני׃ ");
INSERT INTO heb_vpl VALUES ("IS48_11","024_48_11","ISA","48","11","11","למעני למעני אעשה כי איך יחל וכבודי לאחר לא אתן׃ ");
INSERT INTO heb_vpl VALUES ("IS48_12","024_48_12","ISA","48","12","12","שמע אלי יעקב וישראל מקראי אני הוא אני ראשון אף אני אחרון׃ ");
INSERT INTO heb_vpl VALUES ("IS48_13","024_48_13","ISA","48","13","13","אף ידי יסדה ארץ וימיני טפחה שמים קרא אני אליהם יעמדו יחדו׃ ");
INSERT INTO heb_vpl VALUES ("IS48_14","024_48_14","ISA","48","14","14","הקבצו כלכם ושמעו מי בהם הגיד את אלה יהוה אהבו יעשה חפצו בבבל וזרעו כשדים׃ ");
INSERT INTO heb_vpl VALUES ("IS48_15","024_48_15","ISA","48","15","15","אני אני דברתי אף קראתיו הביאתיו והצליח דרכו׃ ");
INSERT INTO heb_vpl VALUES ("IS48_16","024_48_16","ISA","48","16","16","קרבו אלי שמעו זאת לא מראש בסתר דברתי מעת היותה שם אני ועתה אדני יהוה שלחני ורוחו׃ ");
INSERT INTO heb_vpl VALUES ("IS48_17","024_48_17","ISA","48","17","17","כה אמר יהוה גאלך קדוש ישראל אני יהוה אלהיך מלמדך להועיל מדריכך בדרך תלך׃ ");
INSERT INTO heb_vpl VALUES ("IS48_18","024_48_18","ISA","48","18","18","לוא הקשבת למצותי ויהי כנהר שלומך וצדקתך כגלי הים׃ ");
INSERT INTO heb_vpl VALUES ("IS48_19","024_48_19","ISA","48","19","19","ויהי כחול זרעך וצאצאי מעיך כמעתיו לא יכרת ולא ישמד שמו מלפני׃ ");
INSERT INTO heb_vpl VALUES ("IS48_20","024_48_20","ISA","48","20","20","צאו מבבל ברחו מכשדים בקול רנה הגידו השמיעו זאת הוציאוה עד קצה הארץ אמרו גאל יהוה עבדו יעקב׃ ");
INSERT INTO heb_vpl VALUES ("IS48_21","024_48_21","ISA","48","21","21","ולא צמאו בחרבות הוליכם מים מצור הזיל למו ויבקע צור ויזבו מים׃ ");
INSERT INTO heb_vpl VALUES ("IS48_22","024_48_22","ISA","48","22","22","אין שלום אמר יהוה לרשעים׃ ");
INSERT INTO heb_vpl VALUES ("IS49_1","024_49_1","ISA","49","1","1","שמעו איים אלי והקשיבו לאמים מרחוק יהוה מבטן קראני ממעי אמי הזכיר שמי׃ ");
INSERT INTO heb_vpl VALUES ("IS49_2","024_49_2","ISA","49","2","2","וישם פי כחרב חדה בצל ידו החביאני וישימני לחץ ברור באשפתו הסתירני׃ ");
INSERT INTO heb_vpl VALUES ("IS49_3","024_49_3","ISA","49","3","3","ויאמר לי עבדי אתה ישראל אשר בך אתפאר׃ ");
INSERT INTO heb_vpl VALUES ("IS49_4","024_49_4","ISA","49","4","4","ואני אמרתי לריק יגעתי לתהו והבל כחי כליתי אכן משפטי את יהוה ופעלתי את אלהי׃ ");
INSERT INTO heb_vpl VALUES ("IS49_5","024_49_5","ISA","49","5","5","ועתה אמר יהוה יצרי מבטן לעבד לו לשובב יעקב אליו וישראל לא יאסף ואכבד בעיני יהוה ואלהי היה עזי׃ ");
INSERT INTO heb_vpl VALUES ("IS49_6","024_49_6","ISA","49","6","6","ויאמר נקל מהיותך לי עבד להקים את שבטי יעקב ונצירי ישראל להשיב ונתתיך לאור גוים להיות ישועתי עד קצה הארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS49_7","024_49_7","ISA","49","7","7","כה אמר יהוה גאל ישראל קדושו לבזה נפש למתעב גוי לעבד משלים מלכים יראו וקמו שרים וישתחוו למען יהוה אשר נאמן קדש ישראל ויבחרך׃ ");
INSERT INTO heb_vpl VALUES ("IS49_8","024_49_8","ISA","49","8","8","כה אמר יהוה בעת רצון עניתיך וביום ישועה עזרתיך ואצרך ואתנך לברית עם להקים ארץ להנחיל נחלות שממות׃ ");
INSERT INTO heb_vpl VALUES ("IS49_9","024_49_9","ISA","49","9","9","לאמר לאסורים צאו לאשר בחשך הגלו על דרכים ירעו ובכל שפיים מרעיתם׃ ");
INSERT INTO heb_vpl VALUES ("IS49_10","024_49_10","ISA","49","10","10","לא ירעבו ולא יצמאו ולא יכם שרב ושמש כי מרחמם ינהגם ועל מבועי מים ינהלם׃ ");
INSERT INTO heb_vpl VALUES ("IS49_11","024_49_11","ISA","49","11","11","ושמתי כל הרי לדרך ומסלתי ירמון׃ ");
INSERT INTO heb_vpl VALUES ("IS49_12","024_49_12","ISA","49","12","12","הנה אלה מרחוק יבאו והנה אלה מצפון ומים ואלה מארץ סינים׃ ");
INSERT INTO heb_vpl VALUES ("IS49_13","024_49_13","ISA","49","13","13","רנו שמים וגילי ארץ יפצחו הרים רנה כי נחם יהוה עמו ועניו ירחם׃ ");
INSERT INTO heb_vpl VALUES ("IS49_14","024_49_14","ISA","49","14","14","ותאמר ציון עזבני יהוה ואדני שכחני׃ ");
INSERT INTO heb_vpl VALUES ("IS49_15","024_49_15","ISA","49","15","15","התשכח אשה עולה מרחם בן בטנה גם אלה תשכחנה ואנכי לא אשכחך׃ ");
INSERT INTO heb_vpl VALUES ("IS49_16","024_49_16","ISA","49","16","16","הן על כפים חקתיך חומתיך נגדי תמיד׃ ");
INSERT INTO heb_vpl VALUES ("IS49_17","024_49_17","ISA","49","17","17","מהרו בניך מהרסיך ומחרביך ממך יצאו׃ ");
INSERT INTO heb_vpl VALUES ("IS49_18","024_49_18","ISA","49","18","18","שאי סביב עיניך וראי כלם נקבצו באו לך חי אני נאם יהוה כי כלם כעדי תלבשי ותקשרים ככלה׃ ");
INSERT INTO heb_vpl VALUES ("IS49_19","024_49_19","ISA","49","19","19","כי חרבתיך ושממתיך וארץ הרסתיך כי עתה תצרי מיושב ורחקו מבלעיך׃ ");
INSERT INTO heb_vpl VALUES ("IS49_20","024_49_20","ISA","49","20","20","עוד יאמרו באזניך בני שכליך צר לי המקום גשה לי ואשבה׃ ");
INSERT INTO heb_vpl VALUES ("IS49_21","024_49_21","ISA","49","21","21","ואמרת בלבבך מי ילד לי את אלה ואני שכולה וגלמודה גלה וסורה ואלה מי גדל הן אני נשארתי לבדי אלה איפה הם׃ ");
INSERT INTO heb_vpl VALUES ("IS49_22","024_49_22","ISA","49","22","22","כה אמר אדני יהוה הנה אשא אל גוים ידי ואל עמים ארים נסי והביאו בניך בחצן ובנתיך על כתף תנשאנה׃ ");
INSERT INTO heb_vpl VALUES ("IS49_23","024_49_23","ISA","49","23","23","והיו מלכים אמניך ושרותיהם מיניקתיך אפים ארץ ישתחוו לך ועפר רגליך ילחכו וידעת כי אני יהוה אשר לא יבשו קוי׃ ");
INSERT INTO heb_vpl VALUES ("IS49_24","024_49_24","ISA","49","24","24","היקח מגבור מלקוח ואם שבי צדיק ימלט׃ ");
INSERT INTO heb_vpl VALUES ("IS49_25","024_49_25","ISA","49","25","25","כי כה אמר יהוה גם שבי גבור יקח ומלקוח עריץ ימלט ואת יריבך אנכי אריב ואת בניך אנכי אושיע׃ ");
INSERT INTO heb_vpl VALUES ("IS49_26","024_49_26","ISA","49","26","26","והאכלתי את מוניך את בשרם וכעסיס דמם ישכרון וידעו כל בשר כי אני יהוה מושיעך וגאלך אביר יעקב׃ ");
INSERT INTO heb_vpl VALUES ("IS50_1","024_50_1","ISA","50","1","1","כה אמר יהוה אי זה ספר כריתות אמכם אשר שלחתיה או מי מנושי אשר מכרתי אתכם לו הן בעונתיכם נמכרתם ובפשעיכם שלחה אמכם׃ ");
INSERT INTO heb_vpl VALUES ("IS50_2","024_50_2","ISA","50","2","2","מדוע באתי ואין איש קראתי ואין עונה הקצור קצרה ידי מפדות ואם אין בי כח להציל הן בגערתי אחריב ים אשים נהרות מדבר תבאש דגתם מאין מים ותמת בצמא׃ ");
INSERT INTO heb_vpl VALUES ("IS50_3","024_50_3","ISA","50","3","3","אלביש שמים קדרות ושק אשים כסותם׃ ");
INSERT INTO heb_vpl VALUES ("IS50_4","024_50_4","ISA","50","4","4","אדני יהוה נתן לי לשון למודים לדעת לעות את יעף דבר יעיר בבקר בבקר יעיר לי אזן לשמע כלמודים׃ ");
INSERT INTO heb_vpl VALUES ("IS50_5","024_50_5","ISA","50","5","5","אדני יהוה פתח לי אזן ואנכי לא מריתי אחור לא נסוגתי׃ ");
INSERT INTO heb_vpl VALUES ("IS50_6","024_50_6","ISA","50","6","6","גוי נתתי למכים ולחיי למרטים פני לא הסתרתי מכלמות ורק׃ ");
INSERT INTO heb_vpl VALUES ("IS50_7","024_50_7","ISA","50","7","7","ואדני יהוה יעזר לי על כן לא נכלמתי על כן שמתי פני כחלמיש ואדע כי לא אבוש׃ ");
INSERT INTO heb_vpl VALUES ("IS50_8","024_50_8","ISA","50","8","8","קרוב מצדיקי מי יריב אתי נעמדה יחד מי בעל משפטי יגש אלי׃ ");
INSERT INTO heb_vpl VALUES ("IS50_9","024_50_9","ISA","50","9","9","הן אדני יהוה יעזר לי מי הוא ירשיעני הן כלם כבגד יבלו עש יאכלם׃ ");
INSERT INTO heb_vpl VALUES ("IS50_10","024_50_10","ISA","50","10","10","מי בכם ירא יהוה שמע בקול עבדו אשר הלך חשכים ואין נגה לו יבטח בשם יהוה וישען באלהיו׃ ");
INSERT INTO heb_vpl VALUES ("IS50_11","024_50_11","ISA","50","11","11","הן כלכם קדחי אש מאזרי זיקות לכו באור אשכם ובזיקות בערתם מידי היתה זאת לכם למעצבה תשכבון׃ ");
INSERT INTO heb_vpl VALUES ("IS51_1","024_51_1","ISA","51","1","1","שמעו אלי רדפי צדק מבקשי יהוה הביטו אל צור חצבתם ואל מקבת בור נקרתם׃ ");
INSERT INTO heb_vpl VALUES ("IS51_2","024_51_2","ISA","51","2","2","הביטו אל אברהם אביכם ואל שרה תחוללכם כי אחד קראתיו ואברכהו וארבהו׃ ");
INSERT INTO heb_vpl VALUES ("IS51_3","024_51_3","ISA","51","3","3","כי נחם יהוה ציון נחם כל חרבתיה וישם מדברה כעדן וערבתה כגן יהוה ששון ושמחה ימצא בה תודה וקול זמרה׃ ");
INSERT INTO heb_vpl VALUES ("IS51_4","024_51_4","ISA","51","4","4","הקשיבו אלי עמי ולאומי אלי האזינו כי תורה מאתי תצא ומשפטי לאור עמים ארגיע׃ ");
INSERT INTO heb_vpl VALUES ("IS51_5","024_51_5","ISA","51","5","5","קרוב צדקי יצא ישעי וזרעי עמים ישפטו אלי איים יקוו ואל זרעי ייחלון׃ ");
INSERT INTO heb_vpl VALUES ("IS51_6","024_51_6","ISA","51","6","6","שאו לשמים עיניכם והביטו אל הארץ מתחת כי שמים כעשן נמלחו והארץ כבגד תבלה וישביה כמו כן ימותון וישועתי לעולם תהיה וצדקתי לא תחת׃ ");
INSERT INTO heb_vpl VALUES ("IS51_7","024_51_7","ISA","51","7","7","שמעו אלי ידעי צדק עם תורתי בלבם אל תיראו חרפת אנוש ומגדפתם אל תחתו׃ ");
INSERT INTO heb_vpl VALUES ("IS51_8","024_51_8","ISA","51","8","8","כי כבגד יאכלם עש וכצמר יאכלם סס וצדקתי לעולם תהיה וישועתי לדור דורים׃ ");
INSERT INTO heb_vpl VALUES ("IS51_9","024_51_9","ISA","51","9","9","עורי עורי לבשי עז זרוע יהוה עורי כימי קדם דרות עולמים הלוא את היא המחצבת רהב מחוללת תנין׃ ");
INSERT INTO heb_vpl VALUES ("IS51_10","024_51_10","ISA","51","10","10","הלוא את היא המחרבת ים מי תהום רבה השמה מעמקי ים דרך לעבר גאולים׃ ");
INSERT INTO heb_vpl VALUES ("IS51_11","024_51_11","ISA","51","11","11","ופדויי יהוה ישובון ובאו ציון ברנה ושמחת עולם על ראשם ששון ושמחה ישיגון נסו יגון ואנחה׃ ");
INSERT INTO heb_vpl VALUES ("IS51_12","024_51_12","ISA","51","12","12","אנכי אנכי הוא מנחמכם מי את ותיראי מאנוש ימות ומבן אדם חציר ינתן׃ ");
INSERT INTO heb_vpl VALUES ("IS51_13","024_51_13","ISA","51","13","13","ותשכח יהוה עשך נוטה שמים ויסד ארץ ותפחד תמיד כל היום מפני חמת המציק כאשר כונן להשחית ואיה חמת המציק׃ ");
INSERT INTO heb_vpl VALUES ("IS51_14","024_51_14","ISA","51","14","14","מהר צעה להפתח ולא ימות לשחת ולא יחסר לחמו׃ ");
INSERT INTO heb_vpl VALUES ("IS51_15","024_51_15","ISA","51","15","15","ואנכי יהוה אלהיך רגע הים ויהמו גליו יהוה צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("IS51_16","024_51_16","ISA","51","16","16","ואשים דברי בפיך ובצל ידי כסיתיך לנטע שמים וליסד ארץ ולאמר לציון עמי אתה׃ ");
INSERT INTO heb_vpl VALUES ("IS51_17","024_51_17","ISA","51","17","17","התעוררי התעוררי קומי ירושלם אשר שתית מיד יהוה את כוס חמתו את קבעת כוס התרעלה שתית מצית׃ ");
INSERT INTO heb_vpl VALUES ("IS51_18","024_51_18","ISA","51","18","18","אין מנהל לה מכל בנים ילדה ואין מחזיק בידה מכל בנים גדלה׃ ");
INSERT INTO heb_vpl VALUES ("IS51_19","024_51_19","ISA","51","19","19","שתים הנה קראתיך מי ינוד לך השד והשבר והרעב והחרב מי אנחמך׃ ");
INSERT INTO heb_vpl VALUES ("IS51_20","024_51_20","ISA","51","20","20","בניך עלפו שכבו בראש כל חוצות כתוא מכמר המלאים חמת יהוה גערת אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("IS51_21","024_51_21","ISA","51","21","21","לכן שמעי נא זאת עניה ושכרת ולא מיין׃ ");
INSERT INTO heb_vpl VALUES ("IS51_22","024_51_22","ISA","51","22","22","כה אמר אדניך יהוה ואלהיך יריב עמו הנה לקחתי מידך את כוס התרעלה את קבעת כוס חמתי לא תוסיפי לשתותה עוד׃ ");
INSERT INTO heb_vpl VALUES ("IS51_23","024_51_23","ISA","51","23","23","ושמתיה ביד מוגיך אשר אמרו לנפשך שחי ונעברה ותשימי כארץ גוך וכחוץ לעברים׃ ");
INSERT INTO heb_vpl VALUES ("IS52_1","024_52_1","ISA","52","1","1","עורי עורי לבשי עזך ציון לבשי בגדי תפארתך ירושלם עיר הקדש כי לא יוסיף יבא בך עוד ערל וטמא׃ ");
INSERT INTO heb_vpl VALUES ("IS52_2","024_52_2","ISA","52","2","2","התנערי מעפר קומי שבי ירושלם התפתחו מוסרי צוארך שביה בת ציון׃ ");
INSERT INTO heb_vpl VALUES ("IS52_3","024_52_3","ISA","52","3","3","כי כה אמר יהוה חנם נמכרתם ולא בכסף תגאלו׃ ");
INSERT INTO heb_vpl VALUES ("IS52_4","024_52_4","ISA","52","4","4","כי כה אמר אדני יהוה מצרים ירד עמי בראשנה לגור שם ואשור באפס עשקו׃ ");
INSERT INTO heb_vpl VALUES ("IS52_5","024_52_5","ISA","52","5","5","ועתה מה לי פה נאם יהוה כי לקח עמי חנם משלו יהילילו נאם יהוה ותמיד כל היום שמי מנאץ׃ ");
INSERT INTO heb_vpl VALUES ("IS52_6","024_52_6","ISA","52","6","6","לכן ידע עמי שמי לכן ביום ההוא כי אני הוא המדבר הנני׃ ");
INSERT INTO heb_vpl VALUES ("IS52_7","024_52_7","ISA","52","7","7","מה נאוו על ההרים רגלי מבשר משמיע שלום מבשר טוב משמיע ישועה אמר לציון מלך אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("IS52_8","024_52_8","ISA","52","8","8","קול צפיך נשאו קול יחדו ירננו כי עין בעין יראו בשוב יהוה ציון׃ ");
INSERT INTO heb_vpl VALUES ("IS52_9","024_52_9","ISA","52","9","9","פצחו רננו יחדו חרבות ירושלם כי נחם יהוה עמו גאל ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("IS52_10","024_52_10","ISA","52","10","10","חשף יהוה את זרוע קדשו לעיני כל הגוים וראו כל אפסי ארץ את ישועת אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("IS52_11","024_52_11","ISA","52","11","11","סורו סורו צאו משם טמא אל תגעו צאו מתוכה הברו נשאי כלי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS52_12","024_52_12","ISA","52","12","12","כי לא בחפזון תצאו ובמנוסה לא תלכון כי הלך לפניכם יהוה ומאספכם אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS52_13","024_52_13","ISA","52","13","13","הנה ישכיל עבדי ירום ונשא וגבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("IS52_14","024_52_14","ISA","52","14","14","כאשר שממו עליך רבים כן משחת מאיש מראהו ותארו מבני אדם׃ ");
INSERT INTO heb_vpl VALUES ("IS52_15","024_52_15","ISA","52","15","15","כן יזה גוים רבים עליו יקפצו מלכים פיהם כי אשר לא ספר להם ראו ואשר לא שמעו התבוננו׃ ");
INSERT INTO heb_vpl VALUES ("IS53_1","024_53_1","ISA","53","1","1","מי האמין לשמעתנו וזרוע יהוה על מי נגלתה׃ ");
INSERT INTO heb_vpl VALUES ("IS53_2","024_53_2","ISA","53","2","2","ויעל כיונק לפניו וכשרש מארץ ציה לא תאר לו ולא הדר ונראהו ולא מראה ונחמדהו׃ ");
INSERT INTO heb_vpl VALUES ("IS53_3","024_53_3","ISA","53","3","3","נבזה וחדל אישים איש מכאבות וידוע חלי וכמסתר פנים ממנו נבזה ולא חשבנהו׃ ");
INSERT INTO heb_vpl VALUES ("IS53_4","024_53_4","ISA","53","4","4","אכן חלינו הוא נשא ומכאבינו סבלם ואנחנו חשבנהו נגוע מכה אלהים ומענה׃ ");
INSERT INTO heb_vpl VALUES ("IS53_5","024_53_5","ISA","53","5","5","והוא מחלל מפשענו מדכא מעונתינו מוסר שלומנו עליו ובחברתו נרפא לנו׃ ");
INSERT INTO heb_vpl VALUES ("IS53_6","024_53_6","ISA","53","6","6","כלנו כצאן תעינו איש לדרכו פנינו ויהוה הפגיע בו את עון כלנו׃ ");
INSERT INTO heb_vpl VALUES ("IS53_7","024_53_7","ISA","53","7","7","נגש והוא נענה ולא יפתח פיו כשה לטבח יובל וכרחל לפני גזזיה נאלמה ולא יפתח פיו׃ ");
INSERT INTO heb_vpl VALUES ("IS53_8","024_53_8","ISA","53","8","8","מעצר וממשפט לקח ואת דורו מי ישוחח כי נגזר מארץ חיים מפשע עמי נגע למו׃ ");
INSERT INTO heb_vpl VALUES ("IS53_9","024_53_9","ISA","53","9","9","ויתן את רשעים קברו ואת עשיר במתיו על לא חמס עשה ולא מרמה בפיו׃ ");
INSERT INTO heb_vpl VALUES ("IS53_10","024_53_10","ISA","53","10","10","ויהוה חפץ דכאו החלי אם תשים אשם נפשו יראה זרע יאריך ימים וחפץ יהוה בידו יצלח׃ ");
INSERT INTO heb_vpl VALUES ("IS53_11","024_53_11","ISA","53","11","11","מעמל נפשו יראה ישבע בדעתו יצדיק צדיק עבדי לרבים ועונתם הוא יסבל׃ ");
INSERT INTO heb_vpl VALUES ("IS53_12","024_53_12","ISA","53","12","12","לכן אחלק לו ברבים ואת עצומים יחלק שלל תחת אשר הערה למות נפשו ואת פשעים נמנה והוא חטא רבים נשא ולפשעים יפגיע׃ ");
INSERT INTO heb_vpl VALUES ("IS54_1","024_54_1","ISA","54","1","1","רני עקרה לא ילדה פצחי רנה וצהלי לא חלה כי רבים בני שוממה מבני בעולה אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS54_2","024_54_2","ISA","54","2","2","הרחיבי מקום אהלך ויריעות משכנותיך יטו אל תחשכי האריכי מיתריך ויתדתיך חזקי׃ ");
INSERT INTO heb_vpl VALUES ("IS54_3","024_54_3","ISA","54","3","3","כי ימין ושמאול תפרצי וזרעך גוים יירש וערים נשמות יושיבו׃ ");
INSERT INTO heb_vpl VALUES ("IS54_4","024_54_4","ISA","54","4","4","אל תיראי כי לא תבושי ואל תכלמי כי לא תחפירי כי בשת עלומיך תשכחי וחרפת אלמנותיך לא תזכרי עוד׃ ");
INSERT INTO heb_vpl VALUES ("IS54_5","024_54_5","ISA","54","5","5","כי בעליך עשיך יהוה צבאות שמו וגאלך קדוש ישראל אלהי כל הארץ יקרא׃ ");
INSERT INTO heb_vpl VALUES ("IS54_6","024_54_6","ISA","54","6","6","כי כאשה עזובה ועצובת רוח קראך יהוה ואשת נעורים כי תמאס אמר אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("IS54_7","024_54_7","ISA","54","7","7","ברגע קטן עזבתיך וברחמים גדלים אקבצך׃ ");
INSERT INTO heb_vpl VALUES ("IS54_8","024_54_8","ISA","54","8","8","בשצף קצף הסתרתי פני רגע ממך ובחסד עולם רחמתיך אמר גאלך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS54_9","024_54_9","ISA","54","9","9","כי מי נח זאת לי אשר נשבעתי מעבר מי נח עוד על הארץ כן נשבעתי מקצף עליך ומגער בך׃ ");
INSERT INTO heb_vpl VALUES ("IS54_10","024_54_10","ISA","54","10","10","כי ההרים ימושו והגבעות תמוטנה וחסדי מאתך לא ימוש וברית שלומי לא תמוט אמר מרחמך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS54_11","024_54_11","ISA","54","11","11","עניה סערה לא נחמה הנה אנכי מרביץ בפוך אבניך ויסדתיך בספירים׃ ");
INSERT INTO heb_vpl VALUES ("IS54_12","024_54_12","ISA","54","12","12","ושמתי כדכד שמשתיך ושעריך לאבני אקדח וכל גבולך לאבני חפץ׃ ");
INSERT INTO heb_vpl VALUES ("IS54_13","024_54_13","ISA","54","13","13","וכל בניך למודי יהוה ורב שלום בניך׃ ");
INSERT INTO heb_vpl VALUES ("IS54_14","024_54_14","ISA","54","14","14","בצדקה תכונני רחקי מעשק כי לא תיראי וממחתה כי לא תקרב אליך׃ ");
INSERT INTO heb_vpl VALUES ("IS54_15","024_54_15","ISA","54","15","15","הן גור יגור אפס מאותי מי גר אתך עליך יפול׃ ");
INSERT INTO heb_vpl VALUES ("IS54_16","024_54_16","ISA","54","16","16","הן אנכי בראתי חרש נפח באש פחם ומוציא כלי למעשהו ואנכי בראתי משחית לחבל׃ ");
INSERT INTO heb_vpl VALUES ("IS54_17","024_54_17","ISA","54","17","17","כל כלי יוצר עליך לא יצלח וכל לשון תקום אתך למשפט תרשיעי זאת נחלת עבדי יהוה וצדקתם מאתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS55_1","024_55_1","ISA","55","1","1","הוי כל צמא לכו למים ואשר אין לו כסף לכו שברו ואכלו ולכו שברו בלוא כסף ובלוא מחיר יין וחלב׃ ");
INSERT INTO heb_vpl VALUES ("IS55_2","024_55_2","ISA","55","2","2","למה תשקלו כסף בלוא לחם ויגיעכם בלוא לשבעה שמעו שמוע אלי ואכלו טוב ותתענג בדשן נפשכם׃ ");
INSERT INTO heb_vpl VALUES ("IS55_3","024_55_3","ISA","55","3","3","הטו אזנכם ולכו אלי שמעו ותחי נפשכם ואכרתה לכם ברית עולם חסדי דוד הנאמנים׃ ");
INSERT INTO heb_vpl VALUES ("IS55_4","024_55_4","ISA","55","4","4","הן עד לאומים נתתיו נגיד ומצוה לאמים׃ ");
INSERT INTO heb_vpl VALUES ("IS55_5","024_55_5","ISA","55","5","5","הן גוי לא תדע תקרא וגוי לא ידעוך אליך ירוצו למען יהוה אלהיך ולקדוש ישראל כי פארך׃ ");
INSERT INTO heb_vpl VALUES ("IS55_6","024_55_6","ISA","55","6","6","דרשו יהוה בהמצאו קראהו בהיותו קרוב׃ ");
INSERT INTO heb_vpl VALUES ("IS55_7","024_55_7","ISA","55","7","7","יעזב רשע דרכו ואיש און מחשבתיו וישב אל יהוה וירחמהו ואל אלהינו כי ירבה לסלוח׃ ");
INSERT INTO heb_vpl VALUES ("IS55_8","024_55_8","ISA","55","8","8","כי לא מחשבותי מחשבותיכם ולא דרכיכם דרכי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS55_9","024_55_9","ISA","55","9","9","כי גבהו שמים מארץ כן גבהו דרכי מדרכיכם ומחשבתי ממחשבתיכם׃ ");
INSERT INTO heb_vpl VALUES ("IS55_10","024_55_10","ISA","55","10","10","כי כאשר ירד הגשם והשלג מן השמים ושמה לא ישוב כי אם הרוה את הארץ והולידה והצמיחה ונתן זרע לזרע ולחם לאכל׃ ");
INSERT INTO heb_vpl VALUES ("IS55_11","024_55_11","ISA","55","11","11","כן יהיה דברי אשר יצא מפי לא ישוב אלי ריקם כי אם עשה את אשר חפצתי והצליח אשר שלחתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS55_12","024_55_12","ISA","55","12","12","כי בשמחה תצאו ובשלום תובלון ההרים והגבעות יפצחו לפניכם רנה וכל עצי השדה ימחאו כף׃ ");
INSERT INTO heb_vpl VALUES ("IS55_13","024_55_13","ISA","55","13","13","תחת הנעצוץ יעלה ברוש תחת הסרפד יעלה הדס והיה ליהוה לשם לאות עולם לא יכרת׃ ");
INSERT INTO heb_vpl VALUES ("IS56_1","024_56_1","ISA","56","1","1","כה אמר יהוה שמרו משפט ועשו צדקה כי קרובה ישועתי לבוא וצדקתי להגלות׃ ");
INSERT INTO heb_vpl VALUES ("IS56_2","024_56_2","ISA","56","2","2","אשרי אנוש יעשה זאת ובן אדם יחזיק בה שמר שבת מחללו ושמר ידו מעשות כל רע׃ ");
INSERT INTO heb_vpl VALUES ("IS56_3","024_56_3","ISA","56","3","3","ואל יאמר בן הנכר הנלוה אל יהוה לאמר הבדל יבדילני יהוה מעל עמו ואל יאמר הסריס הן אני עץ יבש׃ ");
INSERT INTO heb_vpl VALUES ("IS56_4","024_56_4","ISA","56","4","4","כי כה אמר יהוה לסריסים אשר ישמרו את שבתותי ובחרו באשר חפצתי ומחזיקים בבריתי׃ ");
INSERT INTO heb_vpl VALUES ("IS56_5","024_56_5","ISA","56","5","5","ונתתי להם בביתי ובחומתי יד ושם טוב מבנים ומבנות שם עולם אתן לו אשר לא יכרת׃ ");
INSERT INTO heb_vpl VALUES ("IS56_6","024_56_6","ISA","56","6","6","ובני הנכר הנלוים על יהוה לשרתו ולאהבה את שם יהוה להיות לו לעבדים כל שמר שבת מחללו ומחזיקים בבריתי׃ ");
INSERT INTO heb_vpl VALUES ("IS56_7","024_56_7","ISA","56","7","7","והביאותים אל הר קדשי ושמחתים בבית תפלתי עולתיהם וזבחיהם לרצון על מזבחי כי ביתי בית תפלה יקרא לכל העמים׃ ");
INSERT INTO heb_vpl VALUES ("IS56_8","024_56_8","ISA","56","8","8","נאם אדני יהוה מקבץ נדחי ישראל עוד אקבץ עליו לנקבציו׃ ");
INSERT INTO heb_vpl VALUES ("IS56_9","024_56_9","ISA","56","9","9","כל חיתו שדי אתיו לאכל כל חיתו ביער׃ ");
INSERT INTO heb_vpl VALUES ("IS56_10","024_56_10","ISA","56","10","10","צפו עורים כלם לא ידעו כלם כלבים אלמים לא יוכלו לנבח הזים שכבים אהבי לנום׃ ");
INSERT INTO heb_vpl VALUES ("IS56_11","024_56_11","ISA","56","11","11","והכלבים עזי נפש לא ידעו שבעה והמה רעים לא ידעו הבין כלם לדרכם פנו איש לבצעו מקצהו׃ ");
INSERT INTO heb_vpl VALUES ("IS56_12","024_56_12","ISA","56","12","12","אתיו אקחה יין ונסבאה שכר והיה כזה יום מחר גדול יתר מאד׃ ");
INSERT INTO heb_vpl VALUES ("IS57_1","024_57_1","ISA","57","1","1","הצדיק אבד ואין איש שם על לב ואנשי חסד נאספים באין מבין כי מפני הרעה נאסף הצדיק׃ ");
INSERT INTO heb_vpl VALUES ("IS57_2","024_57_2","ISA","57","2","2","יבוא שלום ינוחו על משכבותם הלך נכחו׃ ");
INSERT INTO heb_vpl VALUES ("IS57_3","024_57_3","ISA","57","3","3","ואתם קרבו הנה בני עננה זרע מנאף ותזנה׃ ");
INSERT INTO heb_vpl VALUES ("IS57_4","024_57_4","ISA","57","4","4","על מי תתענגו על מי תרחיבו פה תאריכו לשון הלוא אתם ילדי פשע זרע שקר׃ ");
INSERT INTO heb_vpl VALUES ("IS57_5","024_57_5","ISA","57","5","5","הנחמים באלים תחת כל עץ רענן שחטי הילדים בנחלים תחת סעפי הסלעים׃ ");
INSERT INTO heb_vpl VALUES ("IS57_6","024_57_6","ISA","57","6","6","בחלקי נחל חלקך הם הם גורלך גם להם שפכת נסך העלית מנחה העל אלה אנחם׃ ");
INSERT INTO heb_vpl VALUES ("IS57_7","024_57_7","ISA","57","7","7","על הר גבה ונשא שמת משכבך גם שם עלית לזבח זבח׃ ");
INSERT INTO heb_vpl VALUES ("IS57_8","024_57_8","ISA","57","8","8","ואחר הדלת והמזוזה שמת זכרונך כי מאתי גלית ותעלי הרחבת משכבך ותכרת לך מהם אהבת משכבם יד חזית׃ ");
INSERT INTO heb_vpl VALUES ("IS57_9","024_57_9","ISA","57","9","9","ותשרי למלך בשמן ותרבי רקחיך ותשלחי צריך עד מרחק ותשפילי עד שאול׃ ");
INSERT INTO heb_vpl VALUES ("IS57_10","024_57_10","ISA","57","10","10","ברב דרכך יגעת לא אמרת נואש חית ידך מצאת על כן לא חלית׃ ");
INSERT INTO heb_vpl VALUES ("IS57_11","024_57_11","ISA","57","11","11","ואת מי דאגת ותיראי כי תכזבי ואותי לא זכרת לא שמת על לבך הלא אני מחשה ומעלם ואותי לא תיראי׃ ");
INSERT INTO heb_vpl VALUES ("IS57_12","024_57_12","ISA","57","12","12","אני אגיד צדקתך ואת מעשיך ולא יועילוך׃ ");
INSERT INTO heb_vpl VALUES ("IS57_13","024_57_13","ISA","57","13","13","בזעקך יצילך קבוציך ואת כלם ישא רוח יקח הבל והחוסה בי ינחל ארץ ויירש הר קדשי׃ ");
INSERT INTO heb_vpl VALUES ("IS57_14","024_57_14","ISA","57","14","14","ואמר סלו סלו פנו דרך הרימו מכשול מדרך עמי׃ ");
INSERT INTO heb_vpl VALUES ("IS57_15","024_57_15","ISA","57","15","15","כי כה אמר רם ונשא שכן עד וקדוש שמו מרום וקדוש אשכון ואת דכא ושפל רוח להחיות רוח שפלים ולהחיות לב נדכאים׃ ");
INSERT INTO heb_vpl VALUES ("IS57_16","024_57_16","ISA","57","16","16","כי לא לעולם אריב ולא לנצח אקצוף כי רוח מלפני יעטוף ונשמות אני עשיתי׃ ");
INSERT INTO heb_vpl VALUES ("IS57_17","024_57_17","ISA","57","17","17","בעון בצעו קצפתי ואכהו הסתר ואקצף וילך שובב בדרך לבו׃ ");
INSERT INTO heb_vpl VALUES ("IS57_18","024_57_18","ISA","57","18","18","דרכיו ראיתי וארפאהו ואנחהו ואשלם נחמים לו ולאבליו׃ ");
INSERT INTO heb_vpl VALUES ("IS57_19","024_57_19","ISA","57","19","19","בורא נוב שפתים שלום שלום לרחוק ולקרוב אמר יהוה ורפאתיו׃ ");
INSERT INTO heb_vpl VALUES ("IS57_20","024_57_20","ISA","57","20","20","והרשעים כים נגרש כי השקט לא יוכל ויגרשו מימיו רפש וטיט׃ ");
INSERT INTO heb_vpl VALUES ("IS57_21","024_57_21","ISA","57","21","21","אין שלום אמר אלהי לרשעים׃ ");
INSERT INTO heb_vpl VALUES ("IS58_1","024_58_1","ISA","58","1","1","קרא בגרון אל תחשך כשופר הרם קולך והגד לעמי פשעם ולבית יעקב חטאתם׃ ");
INSERT INTO heb_vpl VALUES ("IS58_2","024_58_2","ISA","58","2","2","ואותי יום יום ידרשון ודעת דרכי יחפצון כגוי אשר צדקה עשה ומשפט אלהיו לא עזב ישאלוני משפטי צדק קרבת אלהים יחפצון׃ ");
INSERT INTO heb_vpl VALUES ("IS58_3","024_58_3","ISA","58","3","3","למה צמנו ולא ראית ענינו נפשנו ולא תדע הן ביום צמכם תמצאו חפץ וכל עצביכם תנגשו׃ ");
INSERT INTO heb_vpl VALUES ("IS58_4","024_58_4","ISA","58","4","4","הן לריב ומצה תצומו ולהכות באגרף רשע לא תצומו כיום להשמיע במרום קולכם׃ ");
INSERT INTO heb_vpl VALUES ("IS58_5","024_58_5","ISA","58","5","5","הכזה יהיה צום אבחרהו יום ענות אדם נפשו הלכף כאגמן ראשו ושק ואפר יציע הלזה תקרא צום ויום רצון ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS58_6","024_58_6","ISA","58","6","6","הלוא זה צום אבחרהו פתח חרצבות רשע התר אגדות מוטה ושלח רצוצים חפשים וכל מוטה תנתקו׃ ");
INSERT INTO heb_vpl VALUES ("IS58_7","024_58_7","ISA","58","7","7","הלוא פרס לרעב לחמך ועניים מרודים תביא בית כי תראה ערם וכסיתו ומבשרך לא תתעלם׃ ");
INSERT INTO heb_vpl VALUES ("IS58_8","024_58_8","ISA","58","8","8","אז יבקע כשחר אורך וארכתך מהרה תצמח והלך לפניך צדקך כבוד יהוה יאספך׃ ");
INSERT INTO heb_vpl VALUES ("IS58_9","024_58_9","ISA","58","9","9","אז תקרא ויהוה יענה תשוע ויאמר הנני אם תסיר מתוכך מוטה שלח אצבע ודבר און׃ ");
INSERT INTO heb_vpl VALUES ("IS58_10","024_58_10","ISA","58","10","10","ותפק לרעב נפשך ונפש נענה תשביע וזרח בחשך אורך ואפלתך כצהרים׃ ");
INSERT INTO heb_vpl VALUES ("IS58_11","024_58_11","ISA","58","11","11","ונחך יהוה תמיד והשביע בצחצחות נפשך ועצמתיך יחליץ והיית כגן רוה וכמוצא מים אשר לא יכזבו מימיו׃ ");
INSERT INTO heb_vpl VALUES ("IS58_12","024_58_12","ISA","58","12","12","ובנו ממך חרבות עולם מוסדי דור ודור תקומם וקרא לך גדר פרץ משבב נתיבות לשבת׃ ");
INSERT INTO heb_vpl VALUES ("IS58_13","024_58_13","ISA","58","13","13","אם תשיב משבת רגלך עשות חפציך ביום קדשי וקראת לשבת ענג לקדוש יהוה מכבד וכבדתו מעשות דרכיך ממצוא חפצך ודבר דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS58_14","024_58_14","ISA","58","14","14","אז תתענג על יהוה והרכבתיך על במותי ארץ והאכלתיך נחלת יעקב אביך כי פי יהוה דבר׃ ");
INSERT INTO heb_vpl VALUES ("IS59_1","024_59_1","ISA","59","1","1","הן לא קצרה יד יהוה מהושיע ולא כבדה אזנו משמוע׃ ");
INSERT INTO heb_vpl VALUES ("IS59_2","024_59_2","ISA","59","2","2","כי אם עונתיכם היו מבדלים בינכם לבין אלהיכם וחטאותיכם הסתירו פנים מכם משמוע׃ ");
INSERT INTO heb_vpl VALUES ("IS59_3","024_59_3","ISA","59","3","3","כי כפיכם נגאלו בדם ואצבעותיכם בעון שפתותיכם דברו שקר לשונכם עולה תהגה׃ ");
INSERT INTO heb_vpl VALUES ("IS59_4","024_59_4","ISA","59","4","4","אין קרא בצדק ואין נשפט באמונה בטוח על תהו ודבר שוא הרו עמל והוליד און׃ ");
INSERT INTO heb_vpl VALUES ("IS59_5","024_59_5","ISA","59","5","5","ביצי צפעוני בקעו וקורי עכביש יארגו האכל מביציהם ימות והזורה תבקע אפעה׃ ");
INSERT INTO heb_vpl VALUES ("IS59_6","024_59_6","ISA","59","6","6","קוריהם לא יהיו לבגד ולא יתכסו במעשיהם מעשיהם מעשי און ופעל חמס בכפיהם׃ ");
INSERT INTO heb_vpl VALUES ("IS59_7","024_59_7","ISA","59","7","7","רגליהם לרע ירצו וימהרו לשפך דם נקי מחשבותיהם מחשבות און שד ושבר במסלותם׃ ");
INSERT INTO heb_vpl VALUES ("IS59_8","024_59_8","ISA","59","8","8","דרך שלום לא ידעו ואין משפט במעגלותם נתיבותיהם עקשו להם כל דרך בה לא ידע שלום׃ ");
INSERT INTO heb_vpl VALUES ("IS59_9","024_59_9","ISA","59","9","9","על כן רחק משפט ממנו ולא תשיגנו צדקה נקוה לאור והנה חשך לנגהות באפלות נהלך׃ ");
INSERT INTO heb_vpl VALUES ("IS59_10","024_59_10","ISA","59","10","10","נגששה כעורים קיר וכאין עינים נגששה כשלנו בצהרים כנשף באשמנים כמתים׃ ");
INSERT INTO heb_vpl VALUES ("IS59_11","024_59_11","ISA","59","11","11","נהמה כדבים כלנו וכיונים הגה נהגה נקוה למשפט ואין לישועה רחקה ממנו׃ ");
INSERT INTO heb_vpl VALUES ("IS59_12","024_59_12","ISA","59","12","12","כי רבו פשעינו נגדך וחטאותינו ענתה בנו כי פשעינו אתנו ועונתינו ידענום׃ ");
INSERT INTO heb_vpl VALUES ("IS59_13","024_59_13","ISA","59","13","13","פשע וכחש ביהוה ונסוג מאחר אלהינו דבר עשק וסרה הרו והגו מלב דברי שקר׃ ");
INSERT INTO heb_vpl VALUES ("IS59_14","024_59_14","ISA","59","14","14","והסג אחור משפט וצדקה מרחוק תעמד כי כשלה ברחוב אמת ונכחה לא תוכל לבוא׃ ");
INSERT INTO heb_vpl VALUES ("IS59_15","024_59_15","ISA","59","15","15","ותהי האמת נעדרת וסר מרע משתולל וירא יהוה וירע בעיניו כי אין משפט׃ ");
INSERT INTO heb_vpl VALUES ("IS59_16","024_59_16","ISA","59","16","16","וירא כי אין איש וישתומם כי אין מפגיע ותושע לו זרעו וצדקתו היא סמכתהו׃ ");
INSERT INTO heb_vpl VALUES ("IS59_17","024_59_17","ISA","59","17","17","וילבש צדקה כשרין וכובע ישועה בראשו וילבש בגדי נקם תלבשת ויעט כמעיל קנאה׃ ");
INSERT INTO heb_vpl VALUES ("IS59_18","024_59_18","ISA","59","18","18","כעל גמלות כעל ישלם חמה לצריו גמול לאיביו לאיים גמול ישלם׃ ");
INSERT INTO heb_vpl VALUES ("IS59_19","024_59_19","ISA","59","19","19","וייראו ממערב את שם יהוה וממזרח שמש את כבודו כי יבוא כנהר צר רוח יהוה נססה בו׃ ");
INSERT INTO heb_vpl VALUES ("IS59_20","024_59_20","ISA","59","20","20","ובא לציון גואל ולשבי פשע ביעקב נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS59_21","024_59_21","ISA","59","21","21","ואני זאת בריתי אותם אמר יהוה רוחי אשר עליך ודברי אשר שמתי בפיך לא ימושו מפיך ומפי זרעך ומפי זרע זרעך אמר יהוה מעתה ועד עולם׃ ");
INSERT INTO heb_vpl VALUES ("IS60_1","024_60_1","ISA","60","1","1","קומי אורי כי בא אורך וכבוד יהוה עליך זרח׃ ");
INSERT INTO heb_vpl VALUES ("IS60_2","024_60_2","ISA","60","2","2","כי הנה החשך יכסה ארץ וערפל לאמים ועליך יזרח יהוה וכבודו עליך יראה׃ ");
INSERT INTO heb_vpl VALUES ("IS60_3","024_60_3","ISA","60","3","3","והלכו גוים לאורך ומלכים לנגה זרחך׃ ");
INSERT INTO heb_vpl VALUES ("IS60_4","024_60_4","ISA","60","4","4","שאי סביב עיניך וראי כלם נקבצו באו לך בניך מרחוק יבאו ובנתיך על צד תאמנה׃ ");
INSERT INTO heb_vpl VALUES ("IS60_5","024_60_5","ISA","60","5","5","אז תראי ונהרת ופחד ורחב לבבך כי יהפך עליך המון ים חיל גוים יבאו לך׃ ");
INSERT INTO heb_vpl VALUES ("IS60_6","024_60_6","ISA","60","6","6","שפעת גמלים תכסך בכרי מדין ועיפה כלם משבא יבאו זהב ולבונה ישאו ותהלת יהוה יבשרו׃ ");
INSERT INTO heb_vpl VALUES ("IS60_7","024_60_7","ISA","60","7","7","כל צאן קדר יקבצו לך אילי נביות ישרתונך יעלו על רצון מזבחי ובית תפארתי אפאר׃ ");
INSERT INTO heb_vpl VALUES ("IS60_8","024_60_8","ISA","60","8","8","מי אלה כעב תעופינה וכיונים אל ארבתיהם׃ ");
INSERT INTO heb_vpl VALUES ("IS60_9","024_60_9","ISA","60","9","9","כי לי איים יקוו ואניות תרשיש בראשנה להביא בניך מרחוק כספם וזהבם אתם לשם יהוה אלהיך ולקדוש ישראל כי פארך׃ ");
INSERT INTO heb_vpl VALUES ("IS60_10","024_60_10","ISA","60","10","10","ובנו בני נכר חמתיך ומלכיהם ישרתונך כי בקצפי הכיתיך וברצוני רחמתיך׃ ");
INSERT INTO heb_vpl VALUES ("IS60_11","024_60_11","ISA","60","11","11","ופתחו שעריך תמיד יומם ולילה לא יסגרו להביא אליך חיל גוים ומלכיהם נהוגים׃ ");
INSERT INTO heb_vpl VALUES ("IS60_12","024_60_12","ISA","60","12","12","כי הגוי והממלכה אשר לא יעבדוך יאבדו והגוים חרב יחרבו׃ ");
INSERT INTO heb_vpl VALUES ("IS60_13","024_60_13","ISA","60","13","13","כבוד הלבנון אליך יבוא ברוש תדהר ותאשור יחדו לפאר מקום מקדשי ומקום רגלי אכבד׃ ");
INSERT INTO heb_vpl VALUES ("IS60_14","024_60_14","ISA","60","14","14","והלכו אליך שחוח בני מעניך והשתחוו על כפות רגליך כל מנאציך וקראו לך עיר יהוה ציון קדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("IS60_15","024_60_15","ISA","60","15","15","תחת היותך עזובה ושנואה ואין עובר ושמתיך לגאון עולם משוש דור ודור׃ ");
INSERT INTO heb_vpl VALUES ("IS60_16","024_60_16","ISA","60","16","16","וינקת חלב גוים ושד מלכים תינקי וידעת כי אני יהוה מושיעך וגאלך אביר יעקב׃ ");
INSERT INTO heb_vpl VALUES ("IS60_17","024_60_17","ISA","60","17","17","תחת הנחשת אביא זהב ותחת הברזל אביא כסף ותחת העצים נחשת ותחת האבנים ברזל ושמתי פקדתך שלום ונגשיך צדקה׃ ");
INSERT INTO heb_vpl VALUES ("IS60_18","024_60_18","ISA","60","18","18","לא ישמע עוד חמס בארצך שד ושבר בגבוליך וקראת ישועה חומתיך ושעריך תהלה׃ ");
INSERT INTO heb_vpl VALUES ("IS60_19","024_60_19","ISA","60","19","19","לא יהיה לך עוד השמש לאור יומם ולנגה הירח לא יאיר לך והיה לך יהוה לאור עולם ואלהיך לתפארתך׃ ");
INSERT INTO heb_vpl VALUES ("IS60_20","024_60_20","ISA","60","20","20","לא יבוא עוד שמשך וירחך לא יאסף כי יהוה יהיה לך לאור עולם ושלמו ימי אבלך׃ ");
INSERT INTO heb_vpl VALUES ("IS60_21","024_60_21","ISA","60","21","21","ועמך כלם צדיקים לעולם יירשו ארץ נצר מטעו מעשה ידי להתפאר׃ ");
INSERT INTO heb_vpl VALUES ("IS60_22","024_60_22","ISA","60","22","22","הקטן יהיה לאלף והצעיר לגוי עצום אני יהוה בעתה אחישנה׃ ");
INSERT INTO heb_vpl VALUES ("IS61_1","024_61_1","ISA","61","1","1","רוח אדני יהוה עלי יען משח יהוה אתי לבשר ענוים שלחני לחבש לנשברי לב לקרא לשבוים דרור ולאסורים פקח קוח׃ ");
INSERT INTO heb_vpl VALUES ("IS61_2","024_61_2","ISA","61","2","2","לקרא שנת רצון ליהוה ויום נקם לאלהינו לנחם כל אבלים׃ ");
INSERT INTO heb_vpl VALUES ("IS61_3","024_61_3","ISA","61","3","3","לשום לאבלי ציון לתת להם פאר תחת אפר שמן ששון תחת אבל מעטה תהלה תחת רוח כהה וקרא להם אילי הצדק מטע יהוה להתפאר׃ ");
INSERT INTO heb_vpl VALUES ("IS61_4","024_61_4","ISA","61","4","4","ובנו חרבות עולם שממות ראשנים יקוממו וחדשו ערי חרב שממות דור ודור׃ ");
INSERT INTO heb_vpl VALUES ("IS61_5","024_61_5","ISA","61","5","5","ועמדו זרים ורעו צאנכם ובני נכר אכריכם וכרמיכם׃ ");
INSERT INTO heb_vpl VALUES ("IS61_6","024_61_6","ISA","61","6","6","ואתם כהני יהוה תקראו משרתי אלהינו יאמר לכם חיל גוים תאכלו ובכבודם תתימרו׃ ");
INSERT INTO heb_vpl VALUES ("IS61_7","024_61_7","ISA","61","7","7","תחת בשתכם משנה וכלמה ירנו חלקם לכן בארצם משנה יירשו שמחת עולם תהיה להם׃ ");
INSERT INTO heb_vpl VALUES ("IS61_8","024_61_8","ISA","61","8","8","כי אני יהוה אהב משפט שנא גזל בעולה ונתתי פעלתם באמת וברית עולם אכרות להם׃ ");
INSERT INTO heb_vpl VALUES ("IS61_9","024_61_9","ISA","61","9","9","ונודע בגוים זרעם וצאצאיהם בתוך העמים כל ראיהם יכירום כי הם זרע ברך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS61_10","024_61_10","ISA","61","10","10","שוש אשיש ביהוה תגל נפשי באלהי כי הלבישני בגדי ישע מעיל צדקה יעטני כחתן יכהן פאר וככלה תעדה כליה׃ ");
INSERT INTO heb_vpl VALUES ("IS61_11","024_61_11","ISA","61","11","11","כי כארץ תוציא צמחה וכגנה זרועיה תצמיח כן אדני יהוה יצמיח צדקה ותהלה נגד כל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("IS62_1","024_62_1","ISA","62","1","1","למען ציון לא אחשה ולמען ירושלם לא אשקוט עד יצא כנגה צדקה וישועתה כלפיד יבער׃ ");
INSERT INTO heb_vpl VALUES ("IS62_2","024_62_2","ISA","62","2","2","וראו גוים צדקך וכל מלכים כבודך וקרא לך שם חדש אשר פי יהוה יקבנו׃ ");
INSERT INTO heb_vpl VALUES ("IS62_3","024_62_3","ISA","62","3","3","והיית עטרת תפארת ביד יהוה וצנוף מלוכה בכף אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("IS62_4","024_62_4","ISA","62","4","4","לא יאמר לך עוד עזובה ולארצך לא יאמר עוד שממה כי לך יקרא חפצי בה ולארצך בעולה כי חפץ יהוה בך וארצך תבעל׃ ");
INSERT INTO heb_vpl VALUES ("IS62_5","024_62_5","ISA","62","5","5","כי יבעל בחור בתולה יבעלוך בניך ומשוש חתן על כלה ישיש עליך אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("IS62_6","024_62_6","ISA","62","6","6","על חומתיך ירושלם הפקדתי שמרים כל היום וכל הלילה תמיד לא יחשו המזכרים את יהוה אל דמי לכם׃ ");
INSERT INTO heb_vpl VALUES ("IS62_7","024_62_7","ISA","62","7","7","ואל תתנו דמי לו עד יכונן ועד ישים את ירושלם תהלה בארץ׃ ");
INSERT INTO heb_vpl VALUES ("IS62_8","024_62_8","ISA","62","8","8","נשבע יהוה בימינו ובזרוע עזו אם אתן את דגנך עוד מאכל לאיביך ואם ישתו בני נכר תירושך אשר יגעת בו׃ ");
INSERT INTO heb_vpl VALUES ("IS62_9","024_62_9","ISA","62","9","9","כי מאספיו יאכלהו והללו את יהוה ומקבציו ישתהו בחצרות קדשי׃ ");
INSERT INTO heb_vpl VALUES ("IS62_10","024_62_10","ISA","62","10","10","עברו עברו בשערים פנו דרך העם סלו סלו המסלה סקלו מאבן הרימו נס על העמים׃ ");
INSERT INTO heb_vpl VALUES ("IS62_11","024_62_11","ISA","62","11","11","הנה יהוה השמיע אל קצה הארץ אמרו לבת ציון הנה ישעך בא הנה שכרו אתו ופעלתו לפניו׃ ");
INSERT INTO heb_vpl VALUES ("IS62_12","024_62_12","ISA","62","12","12","וקראו להם עם הקדש גאולי יהוה ולך יקרא דרושה עיר לא נעזבה׃ ");
INSERT INTO heb_vpl VALUES ("IS63_1","024_63_1","ISA","63","1","1","מי זה בא מאדום חמוץ בגדים מבצרה זה הדור בלבושו צעה ברב כחו אני מדבר בצדקה רב להושיע׃ ");
INSERT INTO heb_vpl VALUES ("IS63_2","024_63_2","ISA","63","2","2","מדוע אדם ללבושך ובגדיך כדרך בגת׃ ");
INSERT INTO heb_vpl VALUES ("IS63_3","024_63_3","ISA","63","3","3","פורה דרכתי לבדי ומעמים אין איש אתי ואדרכם באפי וארמסם בחמתי ויז נצחם על בגדי וכל מלבושי אגאלתי׃ ");
INSERT INTO heb_vpl VALUES ("IS63_4","024_63_4","ISA","63","4","4","כי יום נקם בלבי ושנת גאולי באה׃ ");
INSERT INTO heb_vpl VALUES ("IS63_5","024_63_5","ISA","63","5","5","ואביט ואין עזר ואשתומם ואין סומך ותושע לי זרעי וחמתי היא סמכתני׃ ");
INSERT INTO heb_vpl VALUES ("IS63_6","024_63_6","ISA","63","6","6","ואבוס עמים באפי ואשכרם בחמתי ואוריד לארץ נצחם׃ ");
INSERT INTO heb_vpl VALUES ("IS63_7","024_63_7","ISA","63","7","7","חסדי יהוה אזכיר תהלת יהוה כעל כל אשר גמלנו יהוה ורב טוב לבית ישראל אשר גמלם כרחמיו וכרב חסדיו׃ ");
INSERT INTO heb_vpl VALUES ("IS63_8","024_63_8","ISA","63","8","8","ויאמר אך עמי המה בנים לא ישקרו ויהי להם למושיע׃ ");
INSERT INTO heb_vpl VALUES ("IS63_9","024_63_9","ISA","63","9","9","בכל צרתם לא צר ומלאך פניו הושיעם באהבתו ובחמלתו הוא גאלם וינטלם וינשאם כל ימי עולם׃ ");
INSERT INTO heb_vpl VALUES ("IS63_10","024_63_10","ISA","63","10","10","והמה מרו ועצבו את רוח קדשו ויהפך להם לאויב הוא נלחם בם׃ ");
INSERT INTO heb_vpl VALUES ("IS63_11","024_63_11","ISA","63","11","11","ויזכר ימי עולם משה עמו איה המעלם מים את רעי צאנו איה השם בקרבו את רוח קדשו׃ ");
INSERT INTO heb_vpl VALUES ("IS63_12","024_63_12","ISA","63","12","12","מוליך לימין משה זרוע תפארתו בוקע מים מפניהם לעשות לו שם עולם׃ ");
INSERT INTO heb_vpl VALUES ("IS63_13","024_63_13","ISA","63","13","13","מוליכם בתהמות כסוס במדבר לא יכשלו׃ ");
INSERT INTO heb_vpl VALUES ("IS63_14","024_63_14","ISA","63","14","14","כבהמה בבקעה תרד רוח יהוה תניחנו כן נהגת עמך לעשות לך שם תפארת׃ ");
INSERT INTO heb_vpl VALUES ("IS63_15","024_63_15","ISA","63","15","15","הבט משמים וראה מזבל קדשך ותפארתך איה קנאתך וגבורתך המון מעיך ורחמיך אלי התאפקו׃ ");
INSERT INTO heb_vpl VALUES ("IS63_16","024_63_16","ISA","63","16","16","כי אתה אבינו כי אברהם לא ידענו וישראל לא יכירנו אתה יהוה אבינו גאלנו מעולם שמך׃ ");
INSERT INTO heb_vpl VALUES ("IS63_17","024_63_17","ISA","63","17","17","למה תתענו יהוה מדרכיך תקשיח לבנו מיראתך שוב למען עבדיך שבטי נחלתך׃ ");
INSERT INTO heb_vpl VALUES ("IS63_18","024_63_18","ISA","63","18","18","למצער ירשו עם קדשך צרינו בוססו מקדשך׃ ");
INSERT INTO heb_vpl VALUES ("IS63_19","024_63_19","ISA","63","19","19","היינו מעולם לא משלת בם לא נקרא שמך עליהם׃ ");
INSERT INTO heb_vpl VALUES ("IS64_1","024_64_1","ISA","64","1","1","לוא קרעת שמים ירדת מפניך הרים נזלו׃ ");
INSERT INTO heb_vpl VALUES ("IS64_2","024_64_2","ISA","64","2","2","כקדח אש המסים מים תבעה אש להודיע שמך לצריך מפניך גוים ירגזו׃ ");
INSERT INTO heb_vpl VALUES ("IS64_3","024_64_3","ISA","64","3","3","בעשותך נוראות לא נקוה ירדת מפניך הרים נזלו׃ ");
INSERT INTO heb_vpl VALUES ("IS64_4","024_64_4","ISA","64","4","4","ומעולם לא שמעו לא האזינו עין לא ראתה אלהים זולתך יעשה למחכה לו׃ ");
INSERT INTO heb_vpl VALUES ("IS64_5","024_64_5","ISA","64","5","5","פגעת את שש ועשה צדק בדרכיך יזכרוך הן אתה קצפת ונחטא בהם עולם ונושע׃ ");
INSERT INTO heb_vpl VALUES ("IS64_6","024_64_6","ISA","64","6","6","ונהי כטמא כלנו וכבגד עדים כל צדקתינו ונבל כעלה כלנו ועוננו כרוח ישאנו׃ ");
INSERT INTO heb_vpl VALUES ("IS64_7","024_64_7","ISA","64","7","7","ואין קורא בשמך מתעורר להחזיק בך כי הסתרת פניך ממנו ותמוגנו ביד עוננו׃ ");
INSERT INTO heb_vpl VALUES ("IS64_8","024_64_8","ISA","64","8","8","ועתה יהוה אבינו אתה אנחנו החמר ואתה יצרנו ומעשה ידך כלנו׃ ");
INSERT INTO heb_vpl VALUES ("IS64_9","024_64_9","ISA","64","9","9","אל תקצף יהוה עד מאד ואל לעד תזכר עון הן הבט נא עמך כלנו׃ ");
INSERT INTO heb_vpl VALUES ("IS64_10","024_64_10","ISA","64","10","10","ערי קדשך היו מדבר ציון מדבר היתה ירושלם שממה׃ ");
INSERT INTO heb_vpl VALUES ("IS64_11","024_64_11","ISA","64","11","11","בית קדשנו ותפארתנו אשר הללוך אבתינו היה לשרפת אש וכל מחמדינו היה לחרבה׃ ");
INSERT INTO heb_vpl VALUES ("IS64_12","024_64_12","ISA","64","12","12","העל אלה תתאפק יהוה תחשה ותעננו עד מאד׃ ");
INSERT INTO heb_vpl VALUES ("IS65_1","024_65_1","ISA","65","1","1","נדרשתי ללוא שאלו נמצאתי ללא בקשני אמרתי הנני הנני אל גוי לא קרא בשמי׃ ");
INSERT INTO heb_vpl VALUES ("IS65_2","024_65_2","ISA","65","2","2","פרשתי ידי כל היום אל עם סורר ההלכים הדרך לא טוב אחר מחשבתיהם׃ ");
INSERT INTO heb_vpl VALUES ("IS65_3","024_65_3","ISA","65","3","3","העם המכעיסים אותי על פני תמיד זבחים בגנות ומקטרים על הלבנים׃ ");
INSERT INTO heb_vpl VALUES ("IS65_4","024_65_4","ISA","65","4","4","הישבים בקברים ובנצורים ילינו האכלים בשר החזיר ופרק פגלים כליהם׃ ");
INSERT INTO heb_vpl VALUES ("IS65_5","024_65_5","ISA","65","5","5","האמרים קרב אליך אל תגש בי כי קדשתיך אלה עשן באפי אש יקדת כל היום׃ ");
INSERT INTO heb_vpl VALUES ("IS65_6","024_65_6","ISA","65","6","6","הנה כתובה לפני לא אחשה כי אם שלמתי ושלמתי על חיקם׃ ");
INSERT INTO heb_vpl VALUES ("IS65_7","024_65_7","ISA","65","7","7","עונתיכם ועונת אבותיכם יחדו אמר יהוה אשר קטרו על ההרים ועל הגבעות חרפוני ומדתי פעלתם ראשנה על חיקם׃ ");
INSERT INTO heb_vpl VALUES ("IS65_8","024_65_8","ISA","65","8","8","כה אמר יהוה כאשר ימצא התירוש באשכול ואמר אל תשחיתהו כי ברכה בו כן אעשה למען עבדי לבלתי השחית הכל׃ ");
INSERT INTO heb_vpl VALUES ("IS65_9","024_65_9","ISA","65","9","9","והוצאתי מיעקב זרע ומיהודה יורש הרי וירשוה בחירי ועבדי ישכנו שמה׃ ");
INSERT INTO heb_vpl VALUES ("IS65_10","024_65_10","ISA","65","10","10","והיה השרון לנוה צאן ועמק עכור לרבץ בקר לעמי אשר דרשוני׃ ");
INSERT INTO heb_vpl VALUES ("IS65_11","024_65_11","ISA","65","11","11","ואתם עזבי יהוה השכחים את הר קדשי הערכים לגד שלחן והממלאים למני ממסך׃ ");
INSERT INTO heb_vpl VALUES ("IS65_12","024_65_12","ISA","65","12","12","ומניתי אתכם לחרב וכלכם לטבח תכרעו יען קראתי ולא עניתם דברתי ולא שמעתם ותעשו הרע בעיני ובאשר לא חפצתי בחרתם׃ ");
INSERT INTO heb_vpl VALUES ("IS65_13","024_65_13","ISA","65","13","13","לכן כה אמר אדני יהוה הנה עבדי יאכלו ואתם תרעבו הנה עבדי ישתו ואתם תצמאו הנה עבדי ישמחו ואתם תבשו׃ ");
INSERT INTO heb_vpl VALUES ("IS65_14","024_65_14","ISA","65","14","14","הנה עבדי ירנו מטוב לב ואתם תצעקו מכאב לב ומשבר רוח תילילו׃ ");
INSERT INTO heb_vpl VALUES ("IS65_15","024_65_15","ISA","65","15","15","והנחתם שמכם לשבועה לבחירי והמיתך אדני יהוה ולעבדיו יקרא שם אחר׃ ");
INSERT INTO heb_vpl VALUES ("IS65_16","024_65_16","ISA","65","16","16","אשר המתברך בארץ יתברך באלהי אמן והנשבע בארץ ישבע באלהי אמן כי נשכחו הצרות הראשנות וכי נסתרו מעיני׃ ");
INSERT INTO heb_vpl VALUES ("IS65_17","024_65_17","ISA","65","17","17","כי הנני בורא שמים חדשים וארץ חדשה ולא תזכרנה הראשנות ולא תעלינה על לב׃ ");
INSERT INTO heb_vpl VALUES ("IS65_18","024_65_18","ISA","65","18","18","כי אם שישו וגילו עדי עד אשר אני בורא כי הנני בורא את ירושלם גילה ועמה משוש׃ ");
INSERT INTO heb_vpl VALUES ("IS65_19","024_65_19","ISA","65","19","19","וגלתי בירושלם וששתי בעמי ולא ישמע בה עוד קול בכי וקול זעקה׃ ");
INSERT INTO heb_vpl VALUES ("IS65_20","024_65_20","ISA","65","20","20","לא יהיה משם עוד עול ימים וזקן אשר לא ימלא את ימיו כי הנער בן מאה שנה ימות והחוטא בן מאה שנה יקלל׃ ");
INSERT INTO heb_vpl VALUES ("IS65_21","024_65_21","ISA","65","21","21","ובנו בתים וישבו ונטעו כרמים ואכלו פרים׃ ");
INSERT INTO heb_vpl VALUES ("IS65_22","024_65_22","ISA","65","22","22","לא יבנו ואחר ישב לא יטעו ואחר יאכל כי כימי העץ ימי עמי ומעשה ידיהם יבלו בחירי׃ ");
INSERT INTO heb_vpl VALUES ("IS65_23","024_65_23","ISA","65","23","23","לא ייגעו לריק ולא ילדו לבהלה כי זרע ברוכי יהוה המה וצאצאיהם אתם׃ ");
INSERT INTO heb_vpl VALUES ("IS65_24","024_65_24","ISA","65","24","24","והיה טרם יקראו ואני אענה עוד הם מדברים ואני אשמע׃ ");
INSERT INTO heb_vpl VALUES ("IS65_25","024_65_25","ISA","65","25","25","זאב וטלה ירעו כאחד ואריה כבקר יאכל תבן ונחש עפר לחמו לא ירעו ולא ישחיתו בכל הר קדשי אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_1","024_66_1","ISA","66","1","1","כה אמר יהוה השמים כסאי והארץ הדם רגלי אי זה בית אשר תבנו לי ואי זה מקום מנוחתי׃ ");
INSERT INTO heb_vpl VALUES ("IS66_2","024_66_2","ISA","66","2","2","ואת כל אלה ידי עשתה ויהיו כל אלה נאם יהוה ואל זה אביט אל עני ונכה רוח וחרד על דברי׃ ");
INSERT INTO heb_vpl VALUES ("IS66_3","024_66_3","ISA","66","3","3","שוחט השור מכה איש זובח השה ערף כלב מעלה מנחה דם חזיר מזכיר לבנה מברך און גם המה בחרו בדרכיהם ובשקוציהם נפשם חפצה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_4","024_66_4","ISA","66","4","4","גם אני אבחר בתעלליהם ומגורתם אביא להם יען קראתי ואין עונה דברתי ולא שמעו ויעשו הרע בעיני ובאשר לא חפצתי בחרו׃ ");
INSERT INTO heb_vpl VALUES ("IS66_5","024_66_5","ISA","66","5","5","שמעו דבר יהוה החרדים אל דברו אמרו אחיכם שנאיכם מנדיכם למען שמי יכבד יהוה ונראה בשמחתכם והם יבשו׃ ");
INSERT INTO heb_vpl VALUES ("IS66_6","024_66_6","ISA","66","6","6","קול שאון מעיר קול מהיכל קול יהוה משלם גמול לאיביו׃ ");
INSERT INTO heb_vpl VALUES ("IS66_7","024_66_7","ISA","66","7","7","בטרם תחיל ילדה בטרם יבוא חבל לה והמליטה זכר׃ ");
INSERT INTO heb_vpl VALUES ("IS66_8","024_66_8","ISA","66","8","8","מי שמע כזאת מי ראה כאלה היוחל ארץ ביום אחד אם יולד גוי פעם אחת כי חלה גם ילדה ציון את בניה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_9","024_66_9","ISA","66","9","9","האני אשביר ולא אוליד יאמר יהוה אם אני המוליד ועצרתי אמר אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("IS66_10","024_66_10","ISA","66","10","10","שמחו את ירושלם וגילו בה כל אהביה שישו אתה משוש כל המתאבלים עליה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_11","024_66_11","ISA","66","11","11","למען תינקו ושבעתם משד תנחמיה למען תמצו והתענגתם מזיז כבודה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_12","024_66_12","ISA","66","12","12","כי כה אמר יהוה הנני נטה אליה כנהר שלום וכנחל שוטף כבוד גוים וינקתם על צד תנשאו ועל ברכים תשעשעו׃ ");
INSERT INTO heb_vpl VALUES ("IS66_13","024_66_13","ISA","66","13","13","כאיש אשר אמו תנחמנו כן אנכי אנחמכם ובירושלם תנחמו׃ ");
INSERT INTO heb_vpl VALUES ("IS66_14","024_66_14","ISA","66","14","14","וראיתם ושש לבכם ועצמותיכם כדשא תפרחנה ונודעה יד יהוה את עבדיו וזעם את איביו׃ ");
INSERT INTO heb_vpl VALUES ("IS66_15","024_66_15","ISA","66","15","15","כי הנה יהוה באש יבוא וכסופה מרכבתיו להשיב בחמה אפו וגערתו בלהבי אש׃ ");
INSERT INTO heb_vpl VALUES ("IS66_16","024_66_16","ISA","66","16","16","כי באש יהוה נשפט ובחרבו את כל בשר ורבו חללי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_17","024_66_17","ISA","66","17","17","המתקדשים והמטהרים אל הגנות אחר אחד בתוך אכלי בשר החזיר והשקץ והעכבר יחדו יספו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_18","024_66_18","ISA","66","18","18","ואנכי מעשיהם ומחשבתיהם באה לקבץ את כל הגוים והלשנות ובאו וראו את כבודי׃ ");
INSERT INTO heb_vpl VALUES ("IS66_19","024_66_19","ISA","66","19","19","ושמתי בהם אות ושלחתי מהם פליטים אל הגוים תרשיש פול ולוד משכי קשת תבל ויון האיים הרחקים אשר לא שמעו את שמעי ולא ראו את כבודי והגידו את כבודי בגוים׃ ");
INSERT INTO heb_vpl VALUES ("IS66_20","024_66_20","ISA","66","20","20","והביאו את כל אחיכם מכל הגוים מנחה ליהוה בסוסים וברכב ובצבים ובפרדים ובכרכרות על הר קדשי ירושלם אמר יהוה כאשר יביאו בני ישראל את המנחה בכלי טהור בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_21","024_66_21","ISA","66","21","21","וגם מהם אקח לכהנים ללוים אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_22","024_66_22","ISA","66","22","22","כי כאשר השמים החדשים והארץ החדשה אשר אני עשה עמדים לפני נאם יהוה כן יעמד זרעכם ושמכם׃ ");
INSERT INTO heb_vpl VALUES ("IS66_23","024_66_23","ISA","66","23","23","והיה מדי חדש בחדשו ומדי שבת בשבתו יבוא כל בשר להשתחות לפני אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("IS66_24","024_66_24","ISA","66","24","24","ויצאו וראו בפגרי האנשים הפשעים בי כי תולעתם לא תמות ואשם לא תכבה והיו דראון לכל בשר׃ ");
INSERT INTO heb_vpl VALUES ("JR1_1","025_1_1","JER","1","1","1","דברי ירמיהו בן חלקיהו מן הכהנים אשר בענתות בארץ בנימן׃ ");
INSERT INTO heb_vpl VALUES ("JR1_2","025_1_2","JER","1","2","2","אשר היה דבר יהוה אליו בימי יאשיהו בן אמון מלך יהודה בשלש עשרה שנה למלכו׃ ");
INSERT INTO heb_vpl VALUES ("JR1_3","025_1_3","JER","1","3","3","ויהי בימי יהויקים בן יאשיהו מלך יהודה עד תם עשתי עשרה שנה לצדקיהו בן יאשיהו מלך יהודה עד גלות ירושלם בחדש החמישי׃ ");
INSERT INTO heb_vpl VALUES ("JR1_4","025_1_4","JER","1","4","4","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR1_5","025_1_5","JER","1","5","5","בטרם אצורך בבטן ידעתיך ובטרם תצא מרחם הקדשתיך נביא לגוים נתתיך׃ ");
INSERT INTO heb_vpl VALUES ("JR1_6","025_1_6","JER","1","6","6","ואמר אהה אדני יהוה הנה לא ידעתי דבר כי נער אנכי׃ ");
INSERT INTO heb_vpl VALUES ("JR1_7","025_1_7","JER","1","7","7","ויאמר יהוה אלי אל תאמר נער אנכי כי על כל אשר אשלחך תלך ואת כל אשר אצוך תדבר׃ ");
INSERT INTO heb_vpl VALUES ("JR1_8","025_1_8","JER","1","8","8","אל תירא מפניהם כי אתך אני להצלך נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR1_9","025_1_9","JER","1","9","9","וישלח יהוה את ידו ויגע על פי ויאמר יהוה אלי הנה נתתי דברי בפיך׃ ");
INSERT INTO heb_vpl VALUES ("JR1_10","025_1_10","JER","1","10","10","ראה הפקדתיך היום הזה על הגוים ועל הממלכות לנתוש ולנתוץ ולהאביד ולהרוס לבנות ולנטוע׃ ");
INSERT INTO heb_vpl VALUES ("JR1_11","025_1_11","JER","1","11","11","ויהי דבר יהוה אלי לאמר מה אתה ראה ירמיהו ואמר מקל שקד אני ראה׃ ");
INSERT INTO heb_vpl VALUES ("JR1_12","025_1_12","JER","1","12","12","ויאמר יהוה אלי היטבת לראות כי שקד אני על דברי לעשתו׃ ");
INSERT INTO heb_vpl VALUES ("JR1_13","025_1_13","JER","1","13","13","ויהי דבר יהוה אלי שנית לאמר מה אתה ראה ואמר סיר נפוח אני ראה ופניו מפני צפונה׃ ");
INSERT INTO heb_vpl VALUES ("JR1_14","025_1_14","JER","1","14","14","ויאמר יהוה אלי מצפון תפתח הרעה על כל ישבי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR1_15","025_1_15","JER","1","15","15","כי הנני קרא לכל משפחות ממלכות צפונה נאם יהוה ובאו ונתנו איש כסאו פתח שערי ירושלם ועל כל חומתיה סביב ועל כל ערי יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR1_16","025_1_16","JER","1","16","16","ודברתי משפטי אותם על כל רעתם אשר עזבוני ויקטרו לאלהים אחרים וישתחוו למעשי ידיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR1_17","025_1_17","JER","1","17","17","ואתה תאזר מתניך וקמת ודברת אליהם את כל אשר אנכי אצוך אל תחת מפניהם פן אחתך לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("JR1_18","025_1_18","JER","1","18","18","ואני הנה נתתיך היום לעיר מבצר ולעמוד ברזל ולחמות נחשת על כל הארץ למלכי יהודה לשריה לכהניה ולעם הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR1_19","025_1_19","JER","1","19","19","ונלחמו אליך ולא יוכלו לך כי אתך אני נאם יהוה להצילך׃ ");
INSERT INTO heb_vpl VALUES ("JR2_1","025_2_1","JER","2","1","1","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR2_2","025_2_2","JER","2","2","2","הלך וקראת באזני ירושלם לאמר כה אמר יהוה זכרתי לך חסד נעוריך אהבת כלולתיך לכתך אחרי במדבר בארץ לא זרועה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_3","025_2_3","JER","2","3","3","קדש ישראל ליהוה ראשית תבואתה כל אכליו יאשמו רעה תבא אליהם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_4","025_2_4","JER","2","4","4","שמעו דבר יהוה בית יעקב וכל משפחות בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR2_5","025_2_5","JER","2","5","5","כה אמר יהוה מה מצאו אבותיכם בי עול כי רחקו מעלי וילכו אחרי ההבל ויהבלו׃ ");
INSERT INTO heb_vpl VALUES ("JR2_6","025_2_6","JER","2","6","6","ולא אמרו איה יהוה המעלה אתנו מארץ מצרים המוליך אתנו במדבר בארץ ערבה ושוחה בארץ ציה וצלמות בארץ לא עבר בה איש ולא ישב אדם שם׃ ");
INSERT INTO heb_vpl VALUES ("JR2_7","025_2_7","JER","2","7","7","ואביא אתכם אל ארץ הכרמל לאכל פריה וטובה ותבאו ותטמאו את ארצי ונחלתי שמתם לתועבה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_8","025_2_8","JER","2","8","8","הכהנים לא אמרו איה יהוה ותפשי התורה לא ידעוני והרעים פשעו בי והנביאים נבאו בבעל ואחרי לא יועלו הלכו׃ ");
INSERT INTO heb_vpl VALUES ("JR2_9","025_2_9","JER","2","9","9","לכן עד אריב אתכם נאם יהוה ואת בני בניכם אריב׃ ");
INSERT INTO heb_vpl VALUES ("JR2_10","025_2_10","JER","2","10","10","כי עברו איי כתיים וראו וקדר שלחו והתבוננו מאד וראו הן היתה כזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR2_11","025_2_11","JER","2","11","11","ההימיר גוי אלהים והמה לא אלהים ועמי המיר כבודו בלוא יועיל׃ ");
INSERT INTO heb_vpl VALUES ("JR2_12","025_2_12","JER","2","12","12","שמו שמים על זאת ושערו חרבו מאד נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_13","025_2_13","JER","2","13","13","כי שתים רעות עשה עמי אתי עזבו מקור מים חיים לחצב להם בארות בארת נשברים אשר לא יכלו המים׃ ");
INSERT INTO heb_vpl VALUES ("JR2_14","025_2_14","JER","2","14","14","העבד ישראל אם יליד בית הוא מדוע היה לבז׃ ");
INSERT INTO heb_vpl VALUES ("JR2_15","025_2_15","JER","2","15","15","עליו ישאגו כפרים נתנו קולם וישיתו ארצו לשמה עריו נצתה מבלי ישב׃ ");
INSERT INTO heb_vpl VALUES ("JR2_16","025_2_16","JER","2","16","16","גם בני נף ותחפנס ירעוך קדקד׃ ");
INSERT INTO heb_vpl VALUES ("JR2_17","025_2_17","JER","2","17","17","הלוא זאת תעשה לך עזבך את יהוה אלהיך בעת מוליכך בדרך׃ ");
INSERT INTO heb_vpl VALUES ("JR2_18","025_2_18","JER","2","18","18","ועתה מה לך לדרך מצרים לשתות מי שחור ומה לך לדרך אשור לשתות מי נהר׃ ");
INSERT INTO heb_vpl VALUES ("JR2_19","025_2_19","JER","2","19","19","תיסרך רעתך ומשבותיך תוכחך ודעי וראי כי רע ומר עזבך את יהוה אלהיך ולא פחדתי אליך נאם אדני יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("JR2_20","025_2_20","JER","2","20","20","כי מעולם שברתי עלך נתקתי מוסרתיך ותאמרי לא אעבד כי על כל גבעה גבהה ותחת כל עץ רענן את צעה זנה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_21","025_2_21","JER","2","21","21","ואנכי נטעתיך שרק כלה זרע אמת ואיך נהפכת לי סורי הגפן נכריה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_22","025_2_22","JER","2","22","22","כי אם תכבסי בנתר ותרבי לך ברית נכתם עונך לפני נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_23","025_2_23","JER","2","23","23","איך תאמרי לא נטמאתי אחרי הבעלים לא הלכתי ראי דרכך בגיא דעי מה עשית בכרה קלה משרכת דרכיה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_24","025_2_24","JER","2","24","24","פרה למד מדבר באות נפשו שאפה רוח תאנתה מי ישיבנה כל מבקשיה לא ייעפו בחדשה ימצאונה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_25","025_2_25","JER","2","25","25","מנעי רגלך מיחף וגורנך מצמאה ותאמרי נואש לוא כי אהבתי זרים ואחריהם אלך׃ ");
INSERT INTO heb_vpl VALUES ("JR2_26","025_2_26","JER","2","26","26","כבשת גנב כי ימצא כן הבישו בית ישראל המה מלכיהם שריהם וכהניהם ונביאיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR2_27","025_2_27","JER","2","27","27","אמרים לעץ אבי אתה ולאבן את ילדתני כי פנו אלי ערף ולא פנים ובעת רעתם יאמרו קומה והושיענו׃ ");
INSERT INTO heb_vpl VALUES ("JR2_28","025_2_28","JER","2","28","28","ואיה אלהיך אשר עשית לך יקומו אם יושיעוך בעת רעתך כי מספר עריך היו אלהיך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_29","025_2_29","JER","2","29","29","למה תריבו אלי כלכם פשעתם בי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_30","025_2_30","JER","2","30","30","לשוא הכיתי את בניכם מוסר לא לקחו אכלה חרבכם נביאיכם כאריה משחית׃ ");
INSERT INTO heb_vpl VALUES ("JR2_31","025_2_31","JER","2","31","31","הדור אתם ראו דבר יהוה המדבר הייתי לישראל אם ארץ מאפליה מדוע אמרו עמי רדנו לוא נבוא עוד אליך׃ ");
INSERT INTO heb_vpl VALUES ("JR2_32","025_2_32","JER","2","32","32","התשכח בתולה עדיה כלה קשריה ועמי שכחוני ימים אין מספר׃ ");
INSERT INTO heb_vpl VALUES ("JR2_33","025_2_33","JER","2","33","33","מה תיטבי דרכך לבקש אהבה לכן גם את הרעות למדתי את דרכיך׃ ");
INSERT INTO heb_vpl VALUES ("JR2_34","025_2_34","JER","2","34","34","גם בכנפיך נמצאו דם נפשות אביונים נקיים לא במחתרת מצאתים כי על כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("JR2_35","025_2_35","JER","2","35","35","ותאמרי כי נקיתי אך שב אפו ממני הנני נשפט אותך על אמרך לא חטאתי׃ ");
INSERT INTO heb_vpl VALUES ("JR2_36","025_2_36","JER","2","36","36","מה תזלי מאד לשנות את דרכך גם ממצרים תבושי כאשר בשת מאשור׃ ");
INSERT INTO heb_vpl VALUES ("JR2_37","025_2_37","JER","2","37","37","גם מאת זה תצאי וידיך על ראשך כי מאס יהוה במבטחיך ולא תצליחי להם׃ ");
INSERT INTO heb_vpl VALUES ("JR3_1","025_3_1","JER","3","1","1","לאמר הן ישלח איש את אשתו והלכה מאתו והיתה לאיש אחר הישוב אליה עוד הלוא חנוף תחנף הארץ ההיא ואת זנית רעים רבים ושוב אלי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR3_2","025_3_2","JER","3","2","2","שאי עיניך על שפים וראי איפה לא שגלת על דרכים ישבת להם כערבי במדבר ותחניפי ארץ בזנותיך וברעתך׃ ");
INSERT INTO heb_vpl VALUES ("JR3_3","025_3_3","JER","3","3","3","וימנעו רבבים ומלקוש לוא היה ומצח אשה זונה היה לך מאנת הכלם׃ ");
INSERT INTO heb_vpl VALUES ("JR3_4","025_3_4","JER","3","4","4","הלוא מעתה קראתי לי אבי אלוף נערי אתה׃ ");
INSERT INTO heb_vpl VALUES ("JR3_5","025_3_5","JER","3","5","5","הינטר לעולם אם ישמר לנצח הנה דברתי ותעשי הרעות ותוכל׃ ");
INSERT INTO heb_vpl VALUES ("JR3_6","025_3_6","JER","3","6","6","ויאמר יהוה אלי בימי יאשיהו המלך הראית אשר עשתה משבה ישראל הלכה היא על כל הר גבה ואל תחת כל עץ רענן ותזני שם׃ ");
INSERT INTO heb_vpl VALUES ("JR3_7","025_3_7","JER","3","7","7","ואמר אחרי עשותה את כל אלה אלי תשוב ולא שבה ותראה בגודה אחותה יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR3_8","025_3_8","JER","3","8","8","וארא כי על כל אדות אשר נאפה משבה ישראל שלחתיה ואתן את ספר כריתתיה אליה ולא יראה בגדה יהודה אחותה ותלך ותזן גם היא׃ ");
INSERT INTO heb_vpl VALUES ("JR3_9","025_3_9","JER","3","9","9","והיה מקל זנותה ותחנף את הארץ ותנאף את האבן ואת העץ׃ ");
INSERT INTO heb_vpl VALUES ("JR3_10","025_3_10","JER","3","10","10","וגם בכל זאת לא שבה אלי בגודה אחותה יהודה בכל לבה כי אם בשקר נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR3_11","025_3_11","JER","3","11","11","ויאמר יהוה אלי צדקה נפשה משבה ישראל מבגדה יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR3_12","025_3_12","JER","3","12","12","הלך וקראת את הדברים האלה צפונה ואמרת שובה משבה ישראל נאם יהוה לוא אפיל פני בכם כי חסיד אני נאם יהוה לא אטור לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JR3_13","025_3_13","JER","3","13","13","אך דעי עונך כי ביהוה אלהיך פשעת ותפזרי את דרכיך לזרים תחת כל עץ רענן ובקולי לא שמעתם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR3_14","025_3_14","JER","3","14","14","שובו בנים שובבים נאם יהוה כי אנכי בעלתי בכם ולקחתי אתכם אחד מעיר ושנים ממשפחה והבאתי אתכם ציון׃ ");
INSERT INTO heb_vpl VALUES ("JR3_15","025_3_15","JER","3","15","15","ונתתי לכם רעים כלבי ורעו אתכם דעה והשכיל׃ ");
INSERT INTO heb_vpl VALUES ("JR3_16","025_3_16","JER","3","16","16","והיה כי תרבו ופריתם בארץ בימים ההמה נאם יהוה לא יאמרו עוד ארון ברית יהוה ולא יעלה על לב ולא יזכרו בו ולא יפקדו ולא יעשה עוד׃ ");
INSERT INTO heb_vpl VALUES ("JR3_17","025_3_17","JER","3","17","17","בעת ההיא יקראו לירושלם כסא יהוה ונקוו אליה כל הגוים לשם יהוה לירושלם ולא ילכו עוד אחרי שררות לבם הרע׃ ");
INSERT INTO heb_vpl VALUES ("JR3_18","025_3_18","JER","3","18","18","בימים ההמה ילכו בית יהודה על בית ישראל ויבאו יחדו מארץ צפון על הארץ אשר הנחלתי את אבותיכם׃ ");
INSERT INTO heb_vpl VALUES ("JR3_19","025_3_19","JER","3","19","19","ואנכי אמרתי איך אשיתך בבנים ואתן לך ארץ חמדה נחלת צבי צבאות גוים ואמר אבי תקראו לי ומאחרי לא תשובו׃ ");
INSERT INTO heb_vpl VALUES ("JR3_20","025_3_20","JER","3","20","20","אכן בגדה אשה מרעה כן בגדתם בי בית ישראל נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR3_21","025_3_21","JER","3","21","21","קול על שפיים נשמע בכי תחנוני בני ישראל כי העוו את דרכם שכחו את יהוה אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR3_22","025_3_22","JER","3","22","22","שובו בנים שובבים ארפה משובתיכם הננו אתנו לך כי אתה יהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JR3_23","025_3_23","JER","3","23","23","אכן לשקר מגבעות המון הרים אכן ביהוה אלהינו תשועת ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR3_24","025_3_24","JER","3","24","24","והבשת אכלה את יגיע אבותינו מנעורינו את צאנם ואת בקרם את בניהם ואת בנותיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR3_25","025_3_25","JER","3","25","25","נשכבה בבשתנו ותכסנו כלמתנו כי ליהוה אלהינו חטאנו אנחנו ואבותינו מנעורינו ועד היום הזה ולא שמענו בקול יהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_1","025_4_1","JER","4","1","1","אם תשוב ישראל נאם יהוה אלי תשוב ואם תסיר שקוציך מפני ולא תנוד׃ ");
INSERT INTO heb_vpl VALUES ("JR4_2","025_4_2","JER","4","2","2","ונשבעת חי יהוה באמת במשפט ובצדקה והתברכו בו גוים ובו יתהללו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_3","025_4_3","JER","4","3","3","כי כה אמר יהוה לאיש יהודה ולירושלם נירו לכם ניר ואל תזרעו אל קוצים׃ ");
INSERT INTO heb_vpl VALUES ("JR4_4","025_4_4","JER","4","4","4","המלו ליהוה והסרו ערלות לבבכם איש יהודה וישבי ירושלם פן תצא כאש חמתי ובערה ואין מכבה מפני רע מעלליכם׃ ");
INSERT INTO heb_vpl VALUES ("JR4_5","025_4_5","JER","4","5","5","הגידו ביהודה ובירושלם השמיעו ואמרו ותקעו שופר בארץ קראו מלאו ואמרו האספו ונבואה אל ערי המבצר׃ ");
INSERT INTO heb_vpl VALUES ("JR4_6","025_4_6","JER","4","6","6","שאו נס ציונה העיזו אל תעמדו כי רעה אנכי מביא מצפון ושבר גדול׃ ");
INSERT INTO heb_vpl VALUES ("JR4_7","025_4_7","JER","4","7","7","עלה אריה מסבכו ומשחית גוים נסע יצא ממקמו לשום ארצך לשמה עריך תצינה מאין יושב׃ ");
INSERT INTO heb_vpl VALUES ("JR4_8","025_4_8","JER","4","8","8","על זאת חגרו שקים ספדו והילילו כי לא שב חרון אף יהוה ממנו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_9","025_4_9","JER","4","9","9","והיה ביום ההוא נאם יהוה יאבד לב המלך ולב השרים ונשמו הכהנים והנביאים יתמהו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_10","025_4_10","JER","4","10","10","ואמר אהה אדני יהוה אכן השא השאת לעם הזה ולירושלם לאמר שלום יהיה לכם ונגעה חרב עד הנפש׃ ");
INSERT INTO heb_vpl VALUES ("JR4_11","025_4_11","JER","4","11","11","בעת ההיא יאמר לעם הזה ולירושלם רוח צח שפיים במדבר דרך בת עמי לוא לזרות ולוא להבר׃ ");
INSERT INTO heb_vpl VALUES ("JR4_12","025_4_12","JER","4","12","12","רוח מלא מאלה יבוא לי עתה גם אני אדבר משפטים אותם׃ ");
INSERT INTO heb_vpl VALUES ("JR4_13","025_4_13","JER","4","13","13","הנה כעננים יעלה וכסופה מרכבותיו קלו מנשרים סוסיו אוי לנו כי שדדנו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_14","025_4_14","JER","4","14","14","כבסי מרעה לבך ירושלם למען תושעי עד מתי תלין בקרבך מחשבות אונך׃ ");
INSERT INTO heb_vpl VALUES ("JR4_15","025_4_15","JER","4","15","15","כי קול מגיד מדן ומשמיע און מהר אפרים׃ ");
INSERT INTO heb_vpl VALUES ("JR4_16","025_4_16","JER","4","16","16","הזכירו לגוים הנה השמיעו על ירושלם נצרים באים מארץ המרחק ויתנו על ערי יהודה קולם׃ ");
INSERT INTO heb_vpl VALUES ("JR4_17","025_4_17","JER","4","17","17","כשמרי שדי היו עליה מסביב כי אתי מרתה נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR4_18","025_4_18","JER","4","18","18","דרכך ומעלליך עשו אלה לך זאת רעתך כי מר כי נגע עד לבך׃ ");
INSERT INTO heb_vpl VALUES ("JR4_19","025_4_19","JER","4","19","19","מעי מעי אחולה קירות לבי המה לי לבי לא אחריש כי קול שופר שמעתי נפשי תרועת מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JR4_20","025_4_20","JER","4","20","20","שבר על שבר נקרא כי שדדה כל הארץ פתאם שדדו אהלי רגע יריעתי׃ ");
INSERT INTO heb_vpl VALUES ("JR4_21","025_4_21","JER","4","21","21","עד מתי אראה נס אשמעה קול שופר׃ ");
INSERT INTO heb_vpl VALUES ("JR4_22","025_4_22","JER","4","22","22","כי אויל עמי אותי לא ידעו בנים סכלים המה ולא נבונים המה חכמים המה להרע ולהיטיב לא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_23","025_4_23","JER","4","23","23","ראיתי את הארץ והנה תהו ובהו ואל השמים ואין אורם׃ ");
INSERT INTO heb_vpl VALUES ("JR4_24","025_4_24","JER","4","24","24","ראיתי ההרים והנה רעשים וכל הגבעות התקלקלו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_25","025_4_25","JER","4","25","25","ראיתי והנה אין האדם וכל עוף השמים נדדו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_26","025_4_26","JER","4","26","26","ראיתי והנה הכרמל המדבר וכל עריו נתצו מפני יהוה מפני חרון אפו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_27","025_4_27","JER","4","27","27","כי כה אמר יהוה שממה תהיה כל הארץ וכלה לא אעשה׃ ");
INSERT INTO heb_vpl VALUES ("JR4_28","025_4_28","JER","4","28","28","על זאת תאבל הארץ וקדרו השמים ממעל על כי דברתי זמתי ולא נחמתי ולא אשוב ממנה׃ ");
INSERT INTO heb_vpl VALUES ("JR4_29","025_4_29","JER","4","29","29","מקול פרש ורמה קשת ברחת כל העיר באו בעבים ובכפים עלו כל העיר עזובה ואין יושב בהן איש׃ ");
INSERT INTO heb_vpl VALUES ("JR4_30","025_4_30","JER","4","30","30","ואתי שדוד מה תעשי כי תלבשי שני כי תעדי עדי זהב כי תקרעי בפוך עיניך לשוא תתיפי מאסו בך עגבים נפשך יבקשו׃ ");
INSERT INTO heb_vpl VALUES ("JR4_31","025_4_31","JER","4","31","31","כי קול כחולה שמעתי צרה כמבכירה קול בת ציון תתיפח תפרש כפיה אוי נא לי כי עיפה נפשי להרגים׃ ");
INSERT INTO heb_vpl VALUES ("JR5_1","025_5_1","JER","5","1","1","שוטטו בחוצות ירושלם וראו נא ודעו ובקשו ברחובותיה אם תמצאו איש אם יש עשה משפט מבקש אמונה ואסלח לה׃ ");
INSERT INTO heb_vpl VALUES ("JR5_2","025_5_2","JER","5","2","2","ואם חי יהוה יאמרו לכן לשקר ישבעו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_3","025_5_3","JER","5","3","3","יהוה עיניך הלוא לאמונה הכיתה אתם ולא חלו כליתם מאנו קחת מוסר חזקו פניהם מסלע מאנו לשוב׃ ");
INSERT INTO heb_vpl VALUES ("JR5_4","025_5_4","JER","5","4","4","ואני אמרתי אך דלים הם נואלו כי לא ידעו דרך יהוה משפט אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR5_5","025_5_5","JER","5","5","5","אלכה לי אל הגדלים ואדברה אותם כי המה ידעו דרך יהוה משפט אלהיהם אך המה יחדו שברו על נתקו מוסרות׃ ");
INSERT INTO heb_vpl VALUES ("JR5_6","025_5_6","JER","5","6","6","על כן הכם אריה מיער זאב ערבות ישדדם נמר שקד על עריהם כל היוצא מהנה יטרף כי רבו פשעיהם עצמו משבותיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR5_7","025_5_7","JER","5","7","7","אי לזאת אסלוח לך בניך עזבוני וישבעו בלא אלהים ואשבע אותם וינאפו ובית זונה יתגדדו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_8","025_5_8","JER","5","8","8","סוסים מיזנים משכים היו איש אל אשת רעהו יצהלו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_9","025_5_9","JER","5","9","9","העל אלה לוא אפקד נאם יהוה ואם בגוי אשר כזה לא תתנקם נפשי׃ ");
INSERT INTO heb_vpl VALUES ("JR5_10","025_5_10","JER","5","10","10","עלו בשרותיה ושחתו וכלה אל תעשו הסירו נטישותיה כי לוא ליהוה המה׃ ");
INSERT INTO heb_vpl VALUES ("JR5_11","025_5_11","JER","5","11","11","כי בגוד בגדו בי בית ישראל ובית יהודה נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR5_12","025_5_12","JER","5","12","12","כחשו ביהוה ויאמרו לא הוא ולא תבוא עלינו רעה וחרב ורעב לוא נראה׃ ");
INSERT INTO heb_vpl VALUES ("JR5_13","025_5_13","JER","5","13","13","והנביאים יהיו לרוח והדבר אין בהם כה יעשה להם׃ ");
INSERT INTO heb_vpl VALUES ("JR5_14","025_5_14","JER","5","14","14","לכן כה אמר יהוה אלהי צבאות יען דברכם את הדבר הזה הנני נתן דברי בפיך לאש והעם הזה עצים ואכלתם׃ ");
INSERT INTO heb_vpl VALUES ("JR5_15","025_5_15","JER","5","15","15","הנני מביא עליכם גוי ממרחק בית ישראל נאם יהוה גוי איתן הוא גוי מעולם הוא גוי לא תדע לשנו ולא תשמע מה ידבר׃ ");
INSERT INTO heb_vpl VALUES ("JR5_16","025_5_16","JER","5","16","16","אשפתו כקבר פתוח כלם גבורים׃ ");
INSERT INTO heb_vpl VALUES ("JR5_17","025_5_17","JER","5","17","17","ואכל קצירך ולחמך יאכלו בניך ובנותיך יאכל צאנך ובקרך יאכל גפנך ותאנתך ירשש ערי מבצריך אשר אתה בוטח בהנה בחרב׃ ");
INSERT INTO heb_vpl VALUES ("JR5_18","025_5_18","JER","5","18","18","וגם בימים ההמה נאם יהוה לא אעשה אתכם כלה׃ ");
INSERT INTO heb_vpl VALUES ("JR5_19","025_5_19","JER","5","19","19","והיה כי תאמרו תחת מה עשה יהוה אלהינו לנו את כל אלה ואמרת אליהם כאשר עזבתם אותי ותעבדו אלהי נכר בארצכם כן תעבדו זרים בארץ לא לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR5_20","025_5_20","JER","5","20","20","הגידו זאת בבית יעקב והשמיעוה ביהודה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR5_21","025_5_21","JER","5","21","21","שמעו נא זאת עם סכל ואין לב עינים להם ולא יראו אזנים להם ולא ישמעו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_22","025_5_22","JER","5","22","22","האותי לא תיראו נאם יהוה אם מפני לא תחילו אשר שמתי חול גבול לים חק עולם ולא יעברנהו ויתגעשו ולא יוכלו והמו גליו ולא יעברנהו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_23","025_5_23","JER","5","23","23","ולעם הזה היה לב סורר ומורה סרו וילכו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_24","025_5_24","JER","5","24","24","ולא אמרו בלבבם נירא נא את יהוה אלהינו הנתן גשם וירה ומלקוש בעתו שבעות חקות קציר ישמר לנו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_25","025_5_25","JER","5","25","25","עונותיכם הטו אלה וחטאותיכם מנעו הטוב מכם׃ ");
INSERT INTO heb_vpl VALUES ("JR5_26","025_5_26","JER","5","26","26","כי נמצאו בעמי רשעים ישור כשך יקושים הציבו משחית אנשים ילכדו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_27","025_5_27","JER","5","27","27","ככלוב מלא עוף כן בתיהם מלאים מרמה על כן גדלו ויעשירו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_28","025_5_28","JER","5","28","28","שמנו עשתו גם עברו דברי רע דין לא דנו דין יתום ויצליחו ומשפט אביונים לא שפטו׃ ");
INSERT INTO heb_vpl VALUES ("JR5_29","025_5_29","JER","5","29","29","העל אלה לא אפקד נאם יהוה אם בגוי אשר כזה לא תתנקם נפשי׃ ");
INSERT INTO heb_vpl VALUES ("JR5_30","025_5_30","JER","5","30","30","שמה ושערורה נהיתה בארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR5_31","025_5_31","JER","5","31","31","הנביאים נבאו בשקר והכהנים ירדו על ידיהם ועמי אהבו כן ומה תעשו לאחריתה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_1","025_6_1","JER","6","1","1","העזו בני בנימן מקרב ירושלם ובתקוע תקעו שופר ועל בית הכרם שאו משאת כי רעה נשקפה מצפון ושבר גדול׃ ");
INSERT INTO heb_vpl VALUES ("JR6_2","025_6_2","JER","6","2","2","הנוה והמענגה דמיתי בת ציון׃ ");
INSERT INTO heb_vpl VALUES ("JR6_3","025_6_3","JER","6","3","3","אליה יבאו רעים ועדריהם תקעו עליה אהלים סביב רעו איש את ידו׃ ");
INSERT INTO heb_vpl VALUES ("JR6_4","025_6_4","JER","6","4","4","קדשו עליה מלחמה קומו ונעלה בצהרים אוי לנו כי פנה היום כי ינטו צללי ערב׃ ");
INSERT INTO heb_vpl VALUES ("JR6_5","025_6_5","JER","6","5","5","קומו ונעלה בלילה ונשחיתה ארמנותיה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_6","025_6_6","JER","6","6","6","כי כה אמר יהוה צבאות כרתו עצה ושפכו על ירושלם סללה היא העיר הפקד כלה עשק בקרבה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_7","025_6_7","JER","6","7","7","כהקיר בור מימיה כן הקרה רעתה חמס ושד ישמע בה על פני תמיד חלי ומכה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_8","025_6_8","JER","6","8","8","הוסרי ירושלם פן תקע נפשי ממך פן אשימך שממה ארץ לוא נושבה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_9","025_6_9","JER","6","9","9","כה אמר יהוה צבאות עולל יעוללו כגפן שארית ישראל השב ידך כבוצר על סלסלות׃ ");
INSERT INTO heb_vpl VALUES ("JR6_10","025_6_10","JER","6","10","10","על מי אדברה ואעידה וישמעו הנה ערלה אזנם ולא יוכלו להקשיב הנה דבר יהוה היה להם לחרפה לא יחפצו בו׃ ");
INSERT INTO heb_vpl VALUES ("JR6_11","025_6_11","JER","6","11","11","ואת חמת יהוה מלאתי נלאיתי הכיל שפך על עולל בחוץ ועל סוד בחורים יחדו כי גם איש עם אשה ילכדו זקן עם מלא ימים׃ ");
INSERT INTO heb_vpl VALUES ("JR6_12","025_6_12","JER","6","12","12","ונסבו בתיהם לאחרים שדות ונשים יחדו כי אטה את ידי על ישבי הארץ נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_13","025_6_13","JER","6","13","13","כי מקטנם ועד גדולם כלו בוצע בצע ומנביא ועד כהן כלו עשה שקר׃ ");
INSERT INTO heb_vpl VALUES ("JR6_14","025_6_14","JER","6","14","14","וירפאו את שבר עמי על נקלה לאמר שלום שלום ואין שלום׃ ");
INSERT INTO heb_vpl VALUES ("JR6_15","025_6_15","JER","6","15","15","הבישו כי תועבה עשו גם בוש לא יבושו גם הכלים לא ידעו לכן יפלו בנפלים בעת פקדתים יכשלו אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_16","025_6_16","JER","6","16","16","כה אמר יהוה עמדו על דרכים וראו ושאלו לנתבות עולם אי זה דרך הטוב ולכו בה ומצאו מרגוע לנפשכם ויאמרו לא נלך׃ ");
INSERT INTO heb_vpl VALUES ("JR6_17","025_6_17","JER","6","17","17","והקמתי עליכם צפים הקשיבו לקול שופר ויאמרו לא נקשיב׃ ");
INSERT INTO heb_vpl VALUES ("JR6_18","025_6_18","JER","6","18","18","לכן שמעו הגוים ודעי עדה את אשר בם׃ ");
INSERT INTO heb_vpl VALUES ("JR6_19","025_6_19","JER","6","19","19","שמעי הארץ הנה אנכי מביא רעה אל העם הזה פרי מחשבותם כי על דברי לא הקשיבו ותורתי וימאסו בה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_20","025_6_20","JER","6","20","20","למה זה לי לבונה משבא תבוא וקנה הטוב מארץ מרחק עלותיכם לא לרצון וזבחיכם לא ערבו לי׃ ");
INSERT INTO heb_vpl VALUES ("JR6_21","025_6_21","JER","6","21","21","לכן כה אמר יהוה הנני נתן אל העם הזה מכשלים וכשלו בם אבות ובנים יחדו שכן ורעו יאבדו׃ ");
INSERT INTO heb_vpl VALUES ("JR6_22","025_6_22","JER","6","22","22","כה אמר יהוה הנה עם בא מארץ צפון וגוי גדול יעור מירכתי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR6_23","025_6_23","JER","6","23","23","קשת וכידון יחזיקו אכזרי הוא ולא ירחמו קולם כים יהמה ועל סוסים ירכבו ערוך כאיש למלחמה עליך בת ציון׃ ");
INSERT INTO heb_vpl VALUES ("JR6_24","025_6_24","JER","6","24","24","שמענו את שמעו רפו ידינו צרה החזיקתנו חיל כיולדה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_25","025_6_25","JER","6","25","25","אל תצאי השדה ובדרך אל תלכי כי חרב לאיב מגור מסביב׃ ");
INSERT INTO heb_vpl VALUES ("JR6_26","025_6_26","JER","6","26","26","בת עמי חגרי שק והתפלשי באפר אבל יחיד עשי לך מספד תמרורים כי פתאם יבא השדד עלינו׃ ");
INSERT INTO heb_vpl VALUES ("JR6_27","025_6_27","JER","6","27","27","בחון נתתיך בעמי מבצר ותדע ובחנת את דרכם׃ ");
INSERT INTO heb_vpl VALUES ("JR6_28","025_6_28","JER","6","28","28","כלם סרי סוררים הלכי רכיל נחשת וברזל כלם משחיתים המה׃ ");
INSERT INTO heb_vpl VALUES ("JR6_29","025_6_29","JER","6","29","29","נחר מפח מאשתם עפרת לשוא צרף צרוף ורעים לא נתקו׃ ");
INSERT INTO heb_vpl VALUES ("JR6_30","025_6_30","JER","6","30","30","כסף נמאס קראו להם כי מאס יהוה בהם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_1","025_7_1","JER","7","1","1","הדבר אשר היה אל ירמיהו מאת יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR7_2","025_7_2","JER","7","2","2","עמד בשער בית יהוה וקראת שם את הדבר הזה ואמרת שמעו דבר יהוה כל יהודה הבאים בשערים האלה להשתחות ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR7_3","025_7_3","JER","7","3","3","כה אמר יהוה צבאות אלהי ישראל היטיבו דרכיכם ומעלליכם ואשכנה אתכם במקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR7_4","025_7_4","JER","7","4","4","אל תבטחו לכם אל דברי השקר לאמר היכל יהוה היכל יהוה היכל יהוה המה׃ ");
INSERT INTO heb_vpl VALUES ("JR7_5","025_7_5","JER","7","5","5","כי אם היטיב תיטיבו את דרכיכם ואת מעלליכם אם עשו תעשו משפט בין איש ובין רעהו׃ ");
INSERT INTO heb_vpl VALUES ("JR7_6","025_7_6","JER","7","6","6","גר יתום ואלמנה לא תעשקו ודם נקי אל תשפכו במקום הזה ואחרי אלהים אחרים לא תלכו לרע לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_7","025_7_7","JER","7","7","7","ושכנתי אתכם במקום הזה בארץ אשר נתתי לאבותיכם למן עולם ועד עולם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_8","025_7_8","JER","7","8","8","הנה אתם בטחים לכם על דברי השקר לבלתי הועיל׃ ");
INSERT INTO heb_vpl VALUES ("JR7_9","025_7_9","JER","7","9","9","הגנב רצח ונאף והשבע לשקר וקטר לבעל והלך אחרי אלהים אחרים אשר לא ידעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_10","025_7_10","JER","7","10","10","ובאתם ועמדתם לפני בבית הזה אשר נקרא שמי עליו ואמרתם נצלנו למען עשות את כל התועבות האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR7_11","025_7_11","JER","7","11","11","המערת פרצים היה הבית הזה אשר נקרא שמי עליו בעיניכם גם אנכי הנה ראיתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR7_12","025_7_12","JER","7","12","12","כי לכו נא אל מקומי אשר בשילו אשר שכנתי שמי שם בראשונה וראו את אשר עשיתי לו מפני רעת עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR7_13","025_7_13","JER","7","13","13","ועתה יען עשותכם את כל המעשים האלה נאם יהוה ואדבר אליכם השכם ודבר ולא שמעתם ואקרא אתכם ולא עניתם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_14","025_7_14","JER","7","14","14","ועשיתי לבית אשר נקרא שמי עליו אשר אתם בטחים בו ולמקום אשר נתתי לכם ולאבותיכם כאשר עשיתי לשלו׃ ");
INSERT INTO heb_vpl VALUES ("JR7_15","025_7_15","JER","7","15","15","והשלכתי אתכם מעל פני כאשר השלכתי את כל אחיכם את כל זרע אפרים׃ ");
INSERT INTO heb_vpl VALUES ("JR7_16","025_7_16","JER","7","16","16","ואתה אל תתפלל בעד העם הזה ואל תשא בעדם רנה ותפלה ואל תפגע בי כי אינני שמע אתך׃ ");
INSERT INTO heb_vpl VALUES ("JR7_17","025_7_17","JER","7","17","17","האינך ראה מה המה עשים בערי יהודה ובחצות ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_18","025_7_18","JER","7","18","18","הבנים מלקטים עצים והאבות מבערים את האש והנשים לשות בצק לעשות כונים למלכת השמים והסך נסכים לאלהים אחרים למען הכעסני׃ ");
INSERT INTO heb_vpl VALUES ("JR7_19","025_7_19","JER","7","19","19","האתי הם מכעסים נאם יהוה הלוא אתם למען בשת פניהם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_20","025_7_20","JER","7","20","20","לכן כה אמר אדני יהוה הנה אפי וחמתי נתכת אל המקום הזה על האדם ועל הבהמה ועל עץ השדה ועל פרי האדמה ובערה ולא תכבה׃ ");
INSERT INTO heb_vpl VALUES ("JR7_21","025_7_21","JER","7","21","21","כה אמר יהוה צבאות אלהי ישראל עלותיכם ספו על זבחיכם ואכלו בשר׃ ");
INSERT INTO heb_vpl VALUES ("JR7_22","025_7_22","JER","7","22","22","כי לא דברתי את אבותיכם ולא צויתים ביום הוציא אותם מארץ מצרים על דברי עולה וזבח׃ ");
INSERT INTO heb_vpl VALUES ("JR7_23","025_7_23","JER","7","23","23","כי אם את הדבר הזה צויתי אותם לאמר שמעו בקולי והייתי לכם לאלהים ואתם תהיו לי לעם והלכתם בכל הדרך אשר אצוה אתכם למען ייטב לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_24","025_7_24","JER","7","24","24","ולא שמעו ולא הטו את אזנם וילכו במעצות בשררות לבם הרע ויהיו לאחור ולא לפנים׃ ");
INSERT INTO heb_vpl VALUES ("JR7_25","025_7_25","JER","7","25","25","למן היום אשר יצאו אבותיכם מארץ מצרים עד היום הזה ואשלח אליכם את כל עבדי הנביאים יום השכם ושלח׃ ");
INSERT INTO heb_vpl VALUES ("JR7_26","025_7_26","JER","7","26","26","ולוא שמעו אלי ולא הטו את אזנם ויקשו את ערפם הרעו מאבותם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_27","025_7_27","JER","7","27","27","ודברת אליהם את כל הדברים האלה ולא ישמעו אליך וקראת אליהם ולא יענוכה׃ ");
INSERT INTO heb_vpl VALUES ("JR7_28","025_7_28","JER","7","28","28","ואמרת אליהם זה הגוי אשר לוא שמעו בקול יהוה אלהיו ולא לקחו מוסר אבדה האמונה ונכרתה מפיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR7_29","025_7_29","JER","7","29","29","גזי נזרך והשליכי ושאי על שפים קינה כי מאס יהוה ויטש את דור עברתו׃ ");
INSERT INTO heb_vpl VALUES ("JR7_30","025_7_30","JER","7","30","30","כי עשו בני יהודה הרע בעיני נאום יהוה שמו שקוציהם בבית אשר נקרא שמי עליו לטמאו׃ ");
INSERT INTO heb_vpl VALUES ("JR7_31","025_7_31","JER","7","31","31","ובנו במות התפת אשר בגיא בן הנם לשרף את בניהם ואת בנתיהם באש אשר לא צויתי ולא עלתה על לבי׃ ");
INSERT INTO heb_vpl VALUES ("JR7_32","025_7_32","JER","7","32","32","לכן הנה ימים באים נאם יהוה ולא יאמר עוד התפת וגיא בן הנם כי אם גיא ההרגה וקברו בתפת מאין מקום׃ ");
INSERT INTO heb_vpl VALUES ("JR7_33","025_7_33","JER","7","33","33","והיתה נבלת העם הזה למאכל לעוף השמים ולבהמת הארץ ואין מחריד׃ ");
INSERT INTO heb_vpl VALUES ("JR7_34","025_7_34","JER","7","34","34","והשבתי מערי יהודה ומחצות ירושלם קול ששון וקול שמחה קול חתן וקול כלה כי לחרבה תהיה הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR8_1","025_8_1","JER","8","1","1","בעת ההיא נאם יהוה ויציאו את עצמות מלכי יהודה ואת עצמות שריו ואת עצמות הכהנים ואת עצמות הנביאים ואת עצמות יושבי ירושלם מקבריהם׃ ");
INSERT INTO heb_vpl VALUES ("JR8_2","025_8_2","JER","8","2","2","ושטחום לשמש ולירח ולכל צבא השמים אשר אהבום ואשר עבדום ואשר הלכו אחריהם ואשר דרשום ואשר השתחוו להם לא יאספו ולא יקברו לדמן על פני האדמה יהיו׃ ");
INSERT INTO heb_vpl VALUES ("JR8_3","025_8_3","JER","8","3","3","ונבחר מות מחיים לכל השארית הנשארים מן המשפחה הרעה הזאת בכל המקמות הנשארים אשר הדחתים שם נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("JR8_4","025_8_4","JER","8","4","4","ואמרת אליהם כה אמר יהוה היפלו ולא יקומו אם ישוב ולא ישוב׃ ");
INSERT INTO heb_vpl VALUES ("JR8_5","025_8_5","JER","8","5","5","מדוע שובבה העם הזה ירושלם משבה נצחת החזיקו בתרמית מאנו לשוב׃ ");
INSERT INTO heb_vpl VALUES ("JR8_6","025_8_6","JER","8","6","6","הקשבתי ואשמע לוא כן ידברו אין איש נחם על רעתו לאמר מה עשיתי כלה שב במרצותם כסוס שוטף במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JR8_7","025_8_7","JER","8","7","7","גם חסידה בשמים ידעה מועדיה ותר וסוס ועגור שמרו את עת באנה ועמי לא ידעו את משפט יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR8_8","025_8_8","JER","8","8","8","איכה תאמרו חכמים אנחנו ותורת יהוה אתנו אכן הנה לשקר עשה עט שקר ספרים׃ ");
INSERT INTO heb_vpl VALUES ("JR8_9","025_8_9","JER","8","9","9","הבישו חכמים חתו וילכדו הנה בדבר יהוה מאסו וחכמת מה להם׃ ");
INSERT INTO heb_vpl VALUES ("JR8_10","025_8_10","JER","8","10","10","לכן אתן את נשיהם לאחרים שדותיהם ליורשים כי מקטן ועד גדול כלה בצע בצע מנביא ועד כהן כלה עשה שקר׃ ");
INSERT INTO heb_vpl VALUES ("JR8_11","025_8_11","JER","8","11","11","וירפו את שבר בת עמי על נקלה לאמר שלום שלום ואין שלום׃ ");
INSERT INTO heb_vpl VALUES ("JR8_12","025_8_12","JER","8","12","12","הבשו כי תועבה עשו גם בוש לא יבשו והכלם לא ידעו לכן יפלו בנפלים בעת פקדתם יכשלו אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR8_13","025_8_13","JER","8","13","13","אסף אסיפם נאם יהוה אין ענבים בגפן ואין תאנים בתאנה והעלה נבל ואתן להם יעברום׃ ");
INSERT INTO heb_vpl VALUES ("JR8_14","025_8_14","JER","8","14","14","על מה אנחנו ישבים האספו ונבוא אל ערי המבצר ונדמה שם כי יהוה אלהינו הדמנו וישקנו מי ראש כי חטאנו ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR8_15","025_8_15","JER","8","15","15","קוה לשלום ואין טוב לעת מרפה והנה בעתה׃ ");
INSERT INTO heb_vpl VALUES ("JR8_16","025_8_16","JER","8","16","16","מדן נשמע נחרת סוסיו מקול מצהלות אביריו רעשה כל הארץ ויבואו ויאכלו ארץ ומלואה עיר וישבי בה׃ ");
INSERT INTO heb_vpl VALUES ("JR8_17","025_8_17","JER","8","17","17","כי הנני משלח בכם נחשים צפענים אשר אין להם לחש ונשכו אתכם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR8_18","025_8_18","JER","8","18","18","מבליגיתי עלי יגון עלי לבי דוי׃ ");
INSERT INTO heb_vpl VALUES ("JR8_19","025_8_19","JER","8","19","19","הנה קול שועת בת עמי מארץ מרחקים היהוה אין בציון אם מלכה אין בה מדוע הכעסוני בפסליהם בהבלי נכר׃ ");
INSERT INTO heb_vpl VALUES ("JR8_20","025_8_20","JER","8","20","20","עבר קציר כלה קיץ ואנחנו לוא נושענו׃ ");
INSERT INTO heb_vpl VALUES ("JR8_21","025_8_21","JER","8","21","21","על שבר בת עמי השברתי קדרתי שמה החזקתני׃ ");
INSERT INTO heb_vpl VALUES ("JR8_22","025_8_22","JER","8","22","22","הצרי אין בגלעד אם רפא אין שם כי מדוע לא עלתה ארכת בת עמי׃ ");
INSERT INTO heb_vpl VALUES ("JR9_1","025_9_1","JER","9","1","1","מי יתן ראשי מים ועיני מקור דמעה ואבכה יומם ולילה את חללי בת עמי׃ ");
INSERT INTO heb_vpl VALUES ("JR9_2","025_9_2","JER","9","2","2","מי יתנני במדבר מלון ארחים ואעזבה את עמי ואלכה מאתם כי כלם מנאפים עצרת בגדים׃ ");
INSERT INTO heb_vpl VALUES ("JR9_3","025_9_3","JER","9","3","3","וידרכו את לשונם קשתם שקר ולא לאמונה גברו בארץ כי מרעה אל רעה יצאו ואתי לא ידעו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR9_4","025_9_4","JER","9","4","4","איש מרעהו השמרו ועל כל אח אל תבטחו כי כל אח עקוב יעקב וכל רע רכיל יהלך׃ ");
INSERT INTO heb_vpl VALUES ("JR9_5","025_9_5","JER","9","5","5","ואיש ברעהו יהתלו ואמת לא ידברו למדו לשונם דבר שקר העוה נלאו׃ ");
INSERT INTO heb_vpl VALUES ("JR9_6","025_9_6","JER","9","6","6","שבתך בתוך מרמה במרמה מאנו דעת אותי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR9_7","025_9_7","JER","9","7","7","לכן כה אמר יהוה צבאות הנני צורפם ובחנתים כי איך אעשה מפני בת עמי׃ ");
INSERT INTO heb_vpl VALUES ("JR9_8","025_9_8","JER","9","8","8","חץ שוחט לשונם מרמה דבר בפיו שלום את רעהו ידבר ובקרבו ישים ארבו׃ ");
INSERT INTO heb_vpl VALUES ("JR9_9","025_9_9","JER","9","9","9","העל אלה לא אפקד בם נאם יהוה אם בגוי אשר כזה לא תתנקם נפשי׃ ");
INSERT INTO heb_vpl VALUES ("JR9_10","025_9_10","JER","9","10","10","על ההרים אשא בכי ונהי ועל נאות מדבר קינה כי נצתו מבלי איש עבר ולא שמעו קול מקנה מעוף השמים ועד בהמה נדדו הלכו׃ ");
INSERT INTO heb_vpl VALUES ("JR9_11","025_9_11","JER","9","11","11","ונתתי את ירושלם לגלים מעון תנים ואת ערי יהודה אתן שממה מבלי יושב׃ ");
INSERT INTO heb_vpl VALUES ("JR9_12","025_9_12","JER","9","12","12","מי האיש החכם ויבן את זאת ואשר דבר פי יהוה אליו ויגדה על מה אבדה הארץ נצתה כמדבר מבלי עבר׃ ");
INSERT INTO heb_vpl VALUES ("JR9_13","025_9_13","JER","9","13","13","ויאמר יהוה על עזבם את תורתי אשר נתתי לפניהם ולא שמעו בקולי ולא הלכו בה׃ ");
INSERT INTO heb_vpl VALUES ("JR9_14","025_9_14","JER","9","14","14","וילכו אחרי שררות לבם ואחרי הבעלים אשר למדום אבותם׃ ");
INSERT INTO heb_vpl VALUES ("JR9_15","025_9_15","JER","9","15","15","לכן כה אמר יהוה צבאות אלהי ישראל הנני מאכילם את העם הזה לענה והשקיתים מי ראש׃ ");
INSERT INTO heb_vpl VALUES ("JR9_16","025_9_16","JER","9","16","16","והפצותים בגוים אשר לא ידעו המה ואבותם ושלחתי אחריהם את החרב עד כלותי אותם׃ ");
INSERT INTO heb_vpl VALUES ("JR9_17","025_9_17","JER","9","17","17","כה אמר יהוה צבאות התבוננו וקראו למקוננות ותבואינה ואל החכמות שלחו ותבואנה׃ ");
INSERT INTO heb_vpl VALUES ("JR9_18","025_9_18","JER","9","18","18","ותמהרנה ותשנה עלינו נהי ותרדנה עינינו דמעה ועפעפינו יזלו מים׃ ");
INSERT INTO heb_vpl VALUES ("JR9_19","025_9_19","JER","9","19","19","כי קול נהי נשמע מציון איך שדדנו בשנו מאד כי עזבנו ארץ כי השליכו משכנותינו׃ ");
INSERT INTO heb_vpl VALUES ("JR9_20","025_9_20","JER","9","20","20","כי שמענה נשים דבר יהוה ותקח אזנכם דבר פיו ולמדנה בנותיכם נהי ואשה רעותה קינה׃ ");
INSERT INTO heb_vpl VALUES ("JR9_21","025_9_21","JER","9","21","21","כי עלה מות בחלונינו בא בארמנותינו להכרית עולל מחוץ בחורים מרחבות׃ ");
INSERT INTO heb_vpl VALUES ("JR9_22","025_9_22","JER","9","22","22","דבר כה נאם יהוה ונפלה נבלת האדם כדמן על פני השדה וכעמיר מאחרי הקצר ואין מאסף׃ ");
INSERT INTO heb_vpl VALUES ("JR9_23","025_9_23","JER","9","23","23","כה אמר יהוה אל יתהלל חכם בחכמתו ואל יתהלל הגבור בגבורתו אל יתהלל עשיר בעשרו׃ ");
INSERT INTO heb_vpl VALUES ("JR9_24","025_9_24","JER","9","24","24","כי אם בזאת יתהלל המתהלל השכל וידע אותי כי אני יהוה עשה חסד משפט וצדקה בארץ כי באלה חפצתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR9_25","025_9_25","JER","9","25","25","הנה ימים באים נאם יהוה ופקדתי על כל מול בערלה׃ ");
INSERT INTO heb_vpl VALUES ("JR9_26","025_9_26","JER","9","26","26","על מצרים ועל יהודה ועל אדום ועל בני עמון ועל מואב ועל כל קצוצי פאה הישבים במדבר כי כל הגוים ערלים וכל בית ישראל ערלי לב׃ ");
INSERT INTO heb_vpl VALUES ("JR10_1","025_10_1","JER","10","1","1","שמעו את הדבר אשר דבר יהוה עליכם בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR10_2","025_10_2","JER","10","2","2","כה אמר יהוה אל דרך הגוים אל תלמדו ומאתות השמים אל תחתו כי יחתו הגוים מהמה׃ ");
INSERT INTO heb_vpl VALUES ("JR10_3","025_10_3","JER","10","3","3","כי חקות העמים הבל הוא כי עץ מיער כרתו מעשה ידי חרש במעצד׃ ");
INSERT INTO heb_vpl VALUES ("JR10_4","025_10_4","JER","10","4","4","בכסף ובזהב ייפהו במסמרות ובמקבות יחזקום ולוא יפיק׃ ");
INSERT INTO heb_vpl VALUES ("JR10_5","025_10_5","JER","10","5","5","כתמר מקשה המה ולא ידברו נשוא ינשוא כי לא יצעדו אל תיראו מהם כי לא ירעו וגם היטיב אין אותם׃ ");
INSERT INTO heb_vpl VALUES ("JR10_6","025_10_6","JER","10","6","6","מאין כמוך יהוה גדול אתה וגדול שמך בגבורה׃ ");
INSERT INTO heb_vpl VALUES ("JR10_7","025_10_7","JER","10","7","7","מי לא יראך מלך הגוים כי לך יאתה כי בכל חכמי הגוים ובכל מלכותם מאין כמוך׃ ");
INSERT INTO heb_vpl VALUES ("JR10_8","025_10_8","JER","10","8","8","ובאחת יבערו ויכסלו מוסר הבלים עץ הוא׃ ");
INSERT INTO heb_vpl VALUES ("JR10_9","025_10_9","JER","10","9","9","כסף מרקע מתרשיש יובא וזהב מאופז מעשה חרש וידי צורף תכלת וארגמן לבושם מעשה חכמים כלם׃ ");
INSERT INTO heb_vpl VALUES ("JR10_10","025_10_10","JER","10","10","10","ויהוה אלהים אמת הוא אלהים חיים ומלך עולם מקצפו תרעש הארץ ולא יכלו גוים זעמו׃ ");
INSERT INTO heb_vpl VALUES ("JR10_11","025_10_11","JER","10","11","11","כדנה תאמרון להום אלהיא די שמיא וארקא לא עבדו יאבדו מארעא ומן תחות שמיא אלה׃ ");
INSERT INTO heb_vpl VALUES ("JR10_12","025_10_12","JER","10","12","12","עשה ארץ בכחו מכין תבל בחכמתו ובתבונתו נטה שמים׃ ");
INSERT INTO heb_vpl VALUES ("JR10_13","025_10_13","JER","10","13","13","לקול תתו המון מים בשמים ויעלה נשאים מקצה ארץ ברקים למטר עשה ויוצא רוח מאצרתיו׃ ");
INSERT INTO heb_vpl VALUES ("JR10_14","025_10_14","JER","10","14","14","נבער כל אדם מדעת הביש כל צורף מפסל כי שקר נסכו ולא רוח בם׃ ");
INSERT INTO heb_vpl VALUES ("JR10_15","025_10_15","JER","10","15","15","הבל המה מעשה תעתעים בעת פקדתם יאבדו׃ ");
INSERT INTO heb_vpl VALUES ("JR10_16","025_10_16","JER","10","16","16","לא כאלה חלק יעקב כי יוצר הכל הוא וישראל שבט נחלתו יהוה צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("JR10_17","025_10_17","JER","10","17","17","אספי מארץ כנעתך ישבתי במצור׃ ");
INSERT INTO heb_vpl VALUES ("JR10_18","025_10_18","JER","10","18","18","כי כה אמר יהוה הנני קולע את יושבי הארץ בפעם הזאת והצרותי להם למען ימצאו׃ ");
INSERT INTO heb_vpl VALUES ("JR10_19","025_10_19","JER","10","19","19","אוי לי על שברי נחלה מכתי ואני אמרתי אך זה חלי ואשאנו׃ ");
INSERT INTO heb_vpl VALUES ("JR10_20","025_10_20","JER","10","20","20","אהלי שדד וכל מיתרי נתקו בני יצאני ואינם אין נטה עוד אהלי ומקים יריעותי׃ ");
INSERT INTO heb_vpl VALUES ("JR10_21","025_10_21","JER","10","21","21","כי נבערו הרעים ואת יהוה לא דרשו על כן לא השכילו וכל מרעיתם נפוצה׃ ");
INSERT INTO heb_vpl VALUES ("JR10_22","025_10_22","JER","10","22","22","קול שמועה הנה באה ורעש גדול מארץ צפון לשום את ערי יהודה שממה מעון תנים׃ ");
INSERT INTO heb_vpl VALUES ("JR10_23","025_10_23","JER","10","23","23","ידעתי יהוה כי לא לאדם דרכו לא לאיש הלך והכין את צעדו׃ ");
INSERT INTO heb_vpl VALUES ("JR10_24","025_10_24","JER","10","24","24","יסרני יהוה אך במשפט אל באפך פן תמעטני׃ ");
INSERT INTO heb_vpl VALUES ("JR10_25","025_10_25","JER","10","25","25","שפך חמתך על הגוים אשר לא ידעוך ועל משפחות אשר בשמך לא קראו כי אכלו את יעקב ואכלהו ויכלהו ואת נוהו השמו׃ ");
INSERT INTO heb_vpl VALUES ("JR11_1","025_11_1","JER","11","1","1","הדבר אשר היה אל ירמיהו מאת יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR11_2","025_11_2","JER","11","2","2","שמעו את דברי הברית הזאת ודברתם אל איש יהודה ועל ישבי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR11_3","025_11_3","JER","11","3","3","ואמרת אליהם כה אמר יהוה אלהי ישראל ארור האיש אשר לא ישמע את דברי הברית הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR11_4","025_11_4","JER","11","4","4","אשר צויתי את אבותיכם ביום הוציאי אותם מארץ מצרים מכור הברזל לאמר שמעו בקולי ועשיתם אותם ככל אשר אצוה אתכם והייתם לי לעם ואנכי אהיה לכם לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JR11_5","025_11_5","JER","11","5","5","למען הקים את השבועה אשר נשבעתי לאבותיכם לתת להם ארץ זבת חלב ודבש כיום הזה ואען ואמר אמן יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR11_6","025_11_6","JER","11","6","6","ויאמר יהוה אלי קרא את כל הדברים האלה בערי יהודה ובחצות ירושלם לאמר שמעו את דברי הברית הזאת ועשיתם אותם׃ ");
INSERT INTO heb_vpl VALUES ("JR11_7","025_11_7","JER","11","7","7","כי העד העדתי באבותיכם ביום העלותי אותם מארץ מצרים ועד היום הזה השכם והעד לאמר שמעו בקולי׃ ");
INSERT INTO heb_vpl VALUES ("JR11_8","025_11_8","JER","11","8","8","ולא שמעו ולא הטו את אזנם וילכו איש בשרירות לבם הרע ואביא עליהם את כל דברי הברית הזאת אשר צויתי לעשות ולא עשו׃ ");
INSERT INTO heb_vpl VALUES ("JR11_9","025_11_9","JER","11","9","9","ויאמר יהוה אלי נמצא קשר באיש יהודה ובישבי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR11_10","025_11_10","JER","11","10","10","שבו על עונת אבותם הראשנים אשר מאנו לשמוע את דברי והמה הלכו אחרי אלהים אחרים לעבדם הפרו בית ישראל ובית יהודה את בריתי אשר כרתי את אבותם׃ ");
INSERT INTO heb_vpl VALUES ("JR11_11","025_11_11","JER","11","11","11","לכן כה אמר יהוה הנני מביא אליהם רעה אשר לא יוכלו לצאת ממנה וזעקו אלי ולא אשמע אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR11_12","025_11_12","JER","11","12","12","והלכו ערי יהודה וישבי ירושלם וזעקו אל האלהים אשר הם מקטרים להם והושע לא יושיעו להם בעת רעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR11_13","025_11_13","JER","11","13","13","כי מספר עריך היו אלהיך יהודה ומספר חצות ירושלם שמתם מזבחות לבשת מזבחות לקטר לבעל׃ ");
INSERT INTO heb_vpl VALUES ("JR11_14","025_11_14","JER","11","14","14","ואתה אל תתפלל בעד העם הזה ואל תשא בעדם רנה ותפלה כי אינני שמע בעת קראם אלי בעד רעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR11_15","025_11_15","JER","11","15","15","מה לידידי בביתי עשותה המזמתה הרבים ובשר קדש יעברו מעליך כי רעתכי אז תעלזי׃ ");
INSERT INTO heb_vpl VALUES ("JR11_16","025_11_16","JER","11","16","16","זית רענן יפה פרי תאר קרא יהוה שמך לקול המולה גדלה הצית אש עליה ורעו דליותיו׃ ");
INSERT INTO heb_vpl VALUES ("JR11_17","025_11_17","JER","11","17","17","ויהוה צבאות הנוטע אותך דבר עליך רעה בגלל רעת בית ישראל ובית יהודה אשר עשו להם להכעסני לקטר לבעל׃ ");
INSERT INTO heb_vpl VALUES ("JR11_18","025_11_18","JER","11","18","18","ויהוה הודיעני ואדעה אז הראיתני מעלליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR11_19","025_11_19","JER","11","19","19","ואני ככבש אלוף יובל לטבוח ולא ידעתי כי עלי חשבו מחשבות נשחיתה עץ בלחמו ונכרתנו מארץ חיים ושמו לא יזכר עוד׃ ");
INSERT INTO heb_vpl VALUES ("JR11_20","025_11_20","JER","11","20","20","ויהוה צבאות שפט צדק בחן כליות ולב אראה נקמתך מהם כי אליך גליתי את ריבי׃ ");
INSERT INTO heb_vpl VALUES ("JR11_21","025_11_21","JER","11","21","21","לכן כה אמר יהוה על אנשי ענתות המבקשים את נפשך לאמר לא תנבא בשם יהוה ולא תמות בידנו׃ ");
INSERT INTO heb_vpl VALUES ("JR11_22","025_11_22","JER","11","22","22","לכן כה אמר יהוה צבאות הנני פקד עליהם הבחורים ימתו בחרב בניהם ובנותיהם ימתו ברעב׃ ");
INSERT INTO heb_vpl VALUES ("JR11_23","025_11_23","JER","11","23","23","ושארית לא תהיה להם כי אביא רעה אל אנשי ענתות שנת פקדתם׃ ");
INSERT INTO heb_vpl VALUES ("JR12_1","025_12_1","JER","12","1","1","צדיק אתה יהוה כי אריב אליך אך משפטים אדבר אותך מדוע דרך רשעים צלחה שלו כל בגדי בגד׃ ");
INSERT INTO heb_vpl VALUES ("JR12_2","025_12_2","JER","12","2","2","נטעתם גם שרשו ילכו גם עשו פרי קרוב אתה בפיהם ורחוק מכליותיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR12_3","025_12_3","JER","12","3","3","ואתה יהוה ידעתני תראני ובחנת לבי אתך התקם כצאן לטבחה והקדשם ליום הרגה׃ ");
INSERT INTO heb_vpl VALUES ("JR12_4","025_12_4","JER","12","4","4","עד מתי תאבל הארץ ועשב כל השדה ייבש מרעת ישבי בה ספתה בהמות ועוף כי אמרו לא יראה את אחריתנו׃ ");
INSERT INTO heb_vpl VALUES ("JR12_5","025_12_5","JER","12","5","5","כי את רגלים רצתה וילאוך ואיך תתחרה את הסוסים ובארץ שלום אתה בוטח ואיך תעשה בגאון הירדן׃ ");
INSERT INTO heb_vpl VALUES ("JR12_6","025_12_6","JER","12","6","6","כי גם אחיך ובית אביך גם המה בגדו בך גם המה קראו אחריך מלא אל תאמן בם כי ידברו אליך טובות׃ ");
INSERT INTO heb_vpl VALUES ("JR12_7","025_12_7","JER","12","7","7","עזבתי את ביתי נטשתי את נחלתי נתתי את ידדות נפשי בכף איביה׃ ");
INSERT INTO heb_vpl VALUES ("JR12_8","025_12_8","JER","12","8","8","היתה לי נחלתי כאריה ביער נתנה עלי בקולה על כן שנאתיה׃ ");
INSERT INTO heb_vpl VALUES ("JR12_9","025_12_9","JER","12","9","9","העיט צבוע נחלתי לי העיט סביב עליה לכו אספו כל חית השדה התיו לאכלה׃ ");
INSERT INTO heb_vpl VALUES ("JR12_10","025_12_10","JER","12","10","10","רעים רבים שחתו כרמי בססו את חלקתי נתנו את חלקת חמדתי למדבר שממה׃ ");
INSERT INTO heb_vpl VALUES ("JR12_11","025_12_11","JER","12","11","11","שמה לשממה אבלה עלי שממה נשמה כל הארץ כי אין איש שם על לב׃ ");
INSERT INTO heb_vpl VALUES ("JR12_12","025_12_12","JER","12","12","12","על כל שפים במדבר באו שדדים כי חרב ליהוה אכלה מקצה ארץ ועד קצה הארץ אין שלום לכל בשר׃ ");
INSERT INTO heb_vpl VALUES ("JR12_13","025_12_13","JER","12","13","13","זרעו חטים וקצים קצרו נחלו לא יועלו ובשו מתבואתיכם מחרון אף יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR12_14","025_12_14","JER","12","14","14","כה אמר יהוה על כל שכני הרעים הנגעים בנחלה אשר הנחלתי את עמי את ישראל הנני נתשם מעל אדמתם ואת בית יהודה אתוש מתוכם׃ ");
INSERT INTO heb_vpl VALUES ("JR12_15","025_12_15","JER","12","15","15","והיה אחרי נתשי אותם אשוב ורחמתים והשבתים איש לנחלתו ואיש לארצו׃ ");
INSERT INTO heb_vpl VALUES ("JR12_16","025_12_16","JER","12","16","16","והיה אם למד ילמדו את דרכי עמי להשבע בשמי חי יהוה כאשר למדו את עמי להשבע בבעל ונבנו בתוך עמי׃ ");
INSERT INTO heb_vpl VALUES ("JR12_17","025_12_17","JER","12","17","17","ואם לא ישמעו ונתשתי את הגוי ההוא נתוש ואבד נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR13_1","025_13_1","JER","13","1","1","כה אמר יהוה אלי הלוך וקנית לך אזור פשתים ושמתו על מתניך ובמים לא תבאהו׃ ");
INSERT INTO heb_vpl VALUES ("JR13_2","025_13_2","JER","13","2","2","ואקנה את האזור כדבר יהוה ואשם על מתני׃ ");
INSERT INTO heb_vpl VALUES ("JR13_3","025_13_3","JER","13","3","3","ויהי דבר יהוה אלי שנית לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR13_4","025_13_4","JER","13","4","4","קח את האזור אשר קנית אשר על מתניך וקום לך פרתה וטמנהו שם בנקיק הסלע׃ ");
INSERT INTO heb_vpl VALUES ("JR13_5","025_13_5","JER","13","5","5","ואלך ואטמנהו בפרת כאשר צוה יהוה אותי׃ ");
INSERT INTO heb_vpl VALUES ("JR13_6","025_13_6","JER","13","6","6","ויהי מקץ ימים רבים ויאמר יהוה אלי קום לך פרתה וקח משם את האזור אשר צויתיך לטמנו שם׃ ");
INSERT INTO heb_vpl VALUES ("JR13_7","025_13_7","JER","13","7","7","ואלך פרתה ואחפר ואקח את האזור מן המקום אשר טמנתיו שמה והנה נשחת האזור לא יצלח לכל׃ ");
INSERT INTO heb_vpl VALUES ("JR13_8","025_13_8","JER","13","8","8","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR13_9","025_13_9","JER","13","9","9","כה אמר יהוה ככה אשחית את גאון יהודה ואת גאון ירושלם הרב׃ ");
INSERT INTO heb_vpl VALUES ("JR13_10","025_13_10","JER","13","10","10","העם הזה הרע המאנים לשמוע את דברי ההלכים בשררות לבם וילכו אחרי אלהים אחרים לעבדם ולהשתחות להם ויהי כאזור הזה אשר לא יצלח לכל׃ ");
INSERT INTO heb_vpl VALUES ("JR13_11","025_13_11","JER","13","11","11","כי כאשר ידבק האזור אל מתני איש כן הדבקתי אלי את כל בית ישראל ואת כל בית יהודה נאם יהוה להיות לי לעם ולשם ולתהלה ולתפארת ולא שמעו׃ ");
INSERT INTO heb_vpl VALUES ("JR13_12","025_13_12","JER","13","12","12","ואמרת אליהם את הדבר הזה כה אמר יהוה אלהי ישראל כל נבל ימלא יין ואמרו אליך הידע לא נדע כי כל נבל ימלא יין׃ ");
INSERT INTO heb_vpl VALUES ("JR13_13","025_13_13","JER","13","13","13","ואמרת אליהם כה אמר יהוה הנני ממלא את כל ישבי הארץ הזאת ואת המלכים הישבים לדוד על כסאו ואת הכהנים ואת הנביאים ואת כל ישבי ירושלם שכרון׃ ");
INSERT INTO heb_vpl VALUES ("JR13_14","025_13_14","JER","13","14","14","ונפצתים איש אל אחיו והאבות והבנים יחדו נאם יהוה לא אחמול ולא אחוס ולא ארחם מהשחיתם׃ ");
INSERT INTO heb_vpl VALUES ("JR13_15","025_13_15","JER","13","15","15","שמעו והאזינו אל תגבהו כי יהוה דבר׃ ");
INSERT INTO heb_vpl VALUES ("JR13_16","025_13_16","JER","13","16","16","תנו ליהוה אלהיכם כבוד בטרם יחשך ובטרם יתנגפו רגליכם על הרי נשף וקויתם לאור ושמה לצלמות ישית לערפל׃ ");
INSERT INTO heb_vpl VALUES ("JR13_17","025_13_17","JER","13","17","17","ואם לא תשמעוה במסתרים תבכה נפשי מפני גוה ודמע תדמע ותרד עיני דמעה כי נשבה עדר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR13_18","025_13_18","JER","13","18","18","אמר למלך ולגבירה השפילו שבו כי ירד מראשותיכם עטרת תפארתכם׃ ");
INSERT INTO heb_vpl VALUES ("JR13_19","025_13_19","JER","13","19","19","ערי הנגב סגרו ואין פתח הגלת יהודה כלה הגלת שלומים׃ ");
INSERT INTO heb_vpl VALUES ("JR13_20","025_13_20","JER","13","20","20","שאי עיניכם וראי הבאים מצפון איה העדר נתן לך צאן תפארתך׃ ");
INSERT INTO heb_vpl VALUES ("JR13_21","025_13_21","JER","13","21","21","מה תאמרי כי יפקד עליך ואת למדת אתם עליך אלפים לראש הלוא חבלים יאחזוך כמו אשת לדה׃ ");
INSERT INTO heb_vpl VALUES ("JR13_22","025_13_22","JER","13","22","22","וכי תאמרי בלבבך מדוע קראני אלה ברב עונך נגלו שוליך נחמסו עקביך׃ ");
INSERT INTO heb_vpl VALUES ("JR13_23","025_13_23","JER","13","23","23","היהפך כושי עורו ונמר חברברתיו גם אתם תוכלו להיטיב למדי הרע׃ ");
INSERT INTO heb_vpl VALUES ("JR13_24","025_13_24","JER","13","24","24","ואפיצם כקש עובר לרוח מדבר׃ ");
INSERT INTO heb_vpl VALUES ("JR13_25","025_13_25","JER","13","25","25","זה גורלך מנת מדיך מאתי נאם יהוה אשר שכחת אותי ותבטחי בשקר׃ ");
INSERT INTO heb_vpl VALUES ("JR13_26","025_13_26","JER","13","26","26","וגם אני חשפתי שוליך על פניך ונראה קלונך׃ ");
INSERT INTO heb_vpl VALUES ("JR13_27","025_13_27","JER","13","27","27","נאפיך ומצהלותיך זמת זנותך על גבעות בשדה ראיתי שקוציך אוי לך ירושלם לא תטהרי אחרי מתי עד׃ ");
INSERT INTO heb_vpl VALUES ("JR14_1","025_14_1","JER","14","1","1","אשר היה דבר יהוה אל ירמיהו על דברי הבצרות׃ ");
INSERT INTO heb_vpl VALUES ("JR14_2","025_14_2","JER","14","2","2","אבלה יהודה ושעריה אמללו קדרו לארץ וצוחת ירושלם עלתה׃ ");
INSERT INTO heb_vpl VALUES ("JR14_3","025_14_3","JER","14","3","3","ואדריהם שלחו צעוריהם למים באו על גבים לא מצאו מים שבו כליהם ריקם בשו והכלמו וחפו ראשם׃ ");
INSERT INTO heb_vpl VALUES ("JR14_4","025_14_4","JER","14","4","4","בעבור האדמה חתה כי לא היה גשם בארץ בשו אכרים חפו ראשם׃ ");
INSERT INTO heb_vpl VALUES ("JR14_5","025_14_5","JER","14","5","5","כי גם אילת בשדה ילדה ועזוב כי לא היה דשא׃ ");
INSERT INTO heb_vpl VALUES ("JR14_6","025_14_6","JER","14","6","6","ופראים עמדו על שפים שאפו רוח כתנים כלו עיניהם כי אין עשב׃ ");
INSERT INTO heb_vpl VALUES ("JR14_7","025_14_7","JER","14","7","7","אם עונינו ענו בנו יהוה עשה למען שמך כי רבו משובתינו לך חטאנו׃ ");
INSERT INTO heb_vpl VALUES ("JR14_8","025_14_8","JER","14","8","8","מקוה ישראל מושיעו בעת צרה למה תהיה כגר בארץ וכארח נטה ללון׃ ");
INSERT INTO heb_vpl VALUES ("JR14_9","025_14_9","JER","14","9","9","למה תהיה כאיש נדהם כגבור לא יוכל להושיע ואתה בקרבנו יהוה ושמך עלינו נקרא אל תנחנו׃ ");
INSERT INTO heb_vpl VALUES ("JR14_10","025_14_10","JER","14","10","10","כה אמר יהוה לעם הזה כן אהבו לנוע רגליהם לא חשכו ויהוה לא רצם עתה יזכר עונם ויפקד חטאתם׃ ");
INSERT INTO heb_vpl VALUES ("JR14_11","025_14_11","JER","14","11","11","ויאמר יהוה אלי אל תתפלל בעד העם הזה לטובה׃ ");
INSERT INTO heb_vpl VALUES ("JR14_12","025_14_12","JER","14","12","12","כי יצמו אינני שמע אל רנתם וכי יעלו עלה ומנחה אינני רצם כי בחרב וברעב ובדבר אנכי מכלה אותם׃ ");
INSERT INTO heb_vpl VALUES ("JR14_13","025_14_13","JER","14","13","13","ואמר אהה אדני יהוה הנה הנבאים אמרים להם לא תראו חרב ורעב לא יהיה לכם כי שלום אמת אתן לכם במקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR14_14","025_14_14","JER","14","14","14","ויאמר יהוה אלי שקר הנבאים נבאים בשמי לא שלחתים ולא צויתים ולא דברתי אליהם חזון שקר וקסם ואלול ותרמות לבם המה מתנבאים לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR14_15","025_14_15","JER","14","15","15","לכן כה אמר יהוה על הנבאים הנבאים בשמי ואני לא שלחתים והמה אמרים חרב ורעב לא יהיה בארץ הזאת בחרב וברעב יתמו הנבאים ההמה׃ ");
INSERT INTO heb_vpl VALUES ("JR14_16","025_14_16","JER","14","16","16","והעם אשר המה נבאים להם יהיו משלכים בחצות ירושלם מפני הרעב והחרב ואין מקבר להמה המה נשיהם ובניהם ובנתיהם ושפכתי עליהם את רעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR14_17","025_14_17","JER","14","17","17","ואמרת אליהם את הדבר הזה תרדנה עיני דמעה לילה ויומם ואל תדמינה כי שבר גדול נשברה בתולת בת עמי מכה נחלה מאד׃ ");
INSERT INTO heb_vpl VALUES ("JR14_18","025_14_18","JER","14","18","18","אם יצאתי השדה והנה חללי חרב ואם באתי העיר והנה תחלואי רעב כי גם נביא גם כהן סחרו אל ארץ ולא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("JR14_19","025_14_19","JER","14","19","19","המאס מאסת את יהודה אם בציון געלה נפשך מדוע הכיתנו ואין לנו מרפא קוה לשלום ואין טוב ולעת מרפא והנה בעתה׃ ");
INSERT INTO heb_vpl VALUES ("JR14_20","025_14_20","JER","14","20","20","ידענו יהוה רשענו עון אבותינו כי חטאנו לך׃ ");
INSERT INTO heb_vpl VALUES ("JR14_21","025_14_21","JER","14","21","21","אל תנאץ למען שמך אל תנבל כסא כבודך זכר אל תפר בריתך אתנו׃ ");
INSERT INTO heb_vpl VALUES ("JR14_22","025_14_22","JER","14","22","22","היש בהבלי הגוים מגשמים ואם השמים יתנו רבבים הלא אתה הוא יהוה אלהינו ונקוה לך כי אתה עשית את כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("JR15_1","025_15_1","JER","15","1","1","ויאמר יהוה אלי אם יעמד משה ושמואל לפני אין נפשי אל העם הזה שלח מעל פני ויצאו׃ ");
INSERT INTO heb_vpl VALUES ("JR15_2","025_15_2","JER","15","2","2","והיה כי יאמרו אליך אנה נצא ואמרת אליהם כה אמר יהוה אשר למות למות ואשר לחרב לחרב ואשר לרעב לרעב ואשר לשבי לשבי׃ ");
INSERT INTO heb_vpl VALUES ("JR15_3","025_15_3","JER","15","3","3","ופקדתי עליהם ארבע משפחות נאם יהוה את החרב להרג ואת הכלבים לסחב ואת עוף השמים ואת בהמת הארץ לאכל ולהשחית׃ ");
INSERT INTO heb_vpl VALUES ("JR15_4","025_15_4","JER","15","4","4","ונתתים לזועה לכל ממלכות הארץ בגלל מנשה בן יחזקיהו מלך יהודה על אשר עשה בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR15_5","025_15_5","JER","15","5","5","כי מי יחמל עליך ירושלם ומי ינוד לך ומי יסור לשאל לשלם לך׃ ");
INSERT INTO heb_vpl VALUES ("JR15_6","025_15_6","JER","15","6","6","את נטשת אתי נאם יהוה אחור תלכי ואט את ידי עליך ואשחיתך נלאיתי הנחם׃ ");
INSERT INTO heb_vpl VALUES ("JR15_7","025_15_7","JER","15","7","7","ואזרם במזרה בשערי הארץ שכלתי אבדתי את עמי מדרכיהם לוא שבו׃ ");
INSERT INTO heb_vpl VALUES ("JR15_8","025_15_8","JER","15","8","8","עצמו לי אלמנתו מחול ימים הבאתי להם על אם בחור שדד בצהרים הפלתי עליה פתאם עיר ובהלות׃ ");
INSERT INTO heb_vpl VALUES ("JR15_9","025_15_9","JER","15","9","9","אמללה ילדת השבעה נפחה נפשה באה שמשה בעד יומם בושה וחפרה ושאריתם לחרב אתן לפני איביהם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR15_10","025_15_10","JER","15","10","10","אוי לי אמי כי ילדתני איש ריב ואיש מדון לכל הארץ לא נשיתי ולא נשו בי כלה מקללוני׃ ");
INSERT INTO heb_vpl VALUES ("JR15_11","025_15_11","JER","15","11","11","אמר יהוה אם לא שרותך לטוב אם לוא הפגעתי בך בעת רעה ובעת צרה את האיב׃ ");
INSERT INTO heb_vpl VALUES ("JR15_12","025_15_12","JER","15","12","12","הירע ברזל ברזל מצפון ונחשת׃ ");
INSERT INTO heb_vpl VALUES ("JR15_13","025_15_13","JER","15","13","13","חילך ואוצרותיך לבז אתן לא במחיר ובכל חטאותיך ובכל גבוליך׃ ");
INSERT INTO heb_vpl VALUES ("JR15_14","025_15_14","JER","15","14","14","והעברתי את איביך בארץ לא ידעת כי אש קדחה באפי עליכם תוקד׃ ");
INSERT INTO heb_vpl VALUES ("JR15_15","025_15_15","JER","15","15","15","אתה ידעת יהוה זכרני ופקדני והנקם לי מרדפי אל לארך אפך תקחני דע שאתי עליך חרפה׃ ");
INSERT INTO heb_vpl VALUES ("JR15_16","025_15_16","JER","15","16","16","נמצאו דבריך ואכלם ויהי דבריך לי לששון ולשמחת לבבי כי נקרא שמך עלי יהוה אלהי צבאות׃ ");
INSERT INTO heb_vpl VALUES ("JR15_17","025_15_17","JER","15","17","17","לא ישבתי בסוד משחקים ואעלז מפני ידך בדד ישבתי כי זעם מלאתני׃ ");
INSERT INTO heb_vpl VALUES ("JR15_18","025_15_18","JER","15","18","18","למה היה כאבי נצח ומכתי אנושה מאנה הרפא היו תהיה לי כמו אכזב מים לא נאמנו׃ ");
INSERT INTO heb_vpl VALUES ("JR15_19","025_15_19","JER","15","19","19","לכן כה אמר יהוה אם תשוב ואשיבך לפני תעמד ואם תוציא יקר מזולל כפי תהיה ישבו המה אליך ואתה לא תשוב אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR15_20","025_15_20","JER","15","20","20","ונתתיך לעם הזה לחומת נחשת בצורה ונלחמו אליך ולא יוכלו לך כי אתך אני להושיעך ולהצילך נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR15_21","025_15_21","JER","15","21","21","והצלתיך מיד רעים ופדתיך מכף ערצים׃ ");
INSERT INTO heb_vpl VALUES ("JR16_1","025_16_1","JER","16","1","1","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR16_2","025_16_2","JER","16","2","2","לא תקח לך אשה ולא יהיו לך בנים ובנות במקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR16_3","025_16_3","JER","16","3","3","כי כה אמר יהוה על הבנים ועל הבנות הילודים במקום הזה ועל אמתם הילדות אותם ועל אבותם המולדים אותם בארץ הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR16_4","025_16_4","JER","16","4","4","ממותי תחלאים ימתו לא יספדו ולא יקברו לדמן על פני האדמה יהיו ובחרב וברעב יכלו והיתה נבלתם למאכל לעוף השמים ולבהמת הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR16_5","025_16_5","JER","16","5","5","כי כה אמר יהוה אל תבוא בית מרזח ואל תלך לספוד ואל תנד להם כי אספתי את שלומי מאת העם הזה נאם יהוה את החסד ואת הרחמים׃ ");
INSERT INTO heb_vpl VALUES ("JR16_6","025_16_6","JER","16","6","6","ומתו גדלים וקטנים בארץ הזאת לא יקברו ולא יספדו להם ולא יתגדד ולא יקרח להם׃ ");
INSERT INTO heb_vpl VALUES ("JR16_7","025_16_7","JER","16","7","7","ולא יפרסו להם על אבל לנחמו על מת ולא ישקו אותם כוס תנחומים על אביו ועל אמו׃ ");
INSERT INTO heb_vpl VALUES ("JR16_8","025_16_8","JER","16","8","8","ובית משתה לא תבוא לשבת אותם לאכל ולשתות׃ ");
INSERT INTO heb_vpl VALUES ("JR16_9","025_16_9","JER","16","9","9","כי כה אמר יהוה צבאות אלהי ישראל הנני משבית מן המקום הזה לעיניכם ובימיכם קול ששון וקול שמחה קול חתן וקול כלה׃ ");
INSERT INTO heb_vpl VALUES ("JR16_10","025_16_10","JER","16","10","10","והיה כי תגיד לעם הזה את כל הדברים האלה ואמרו אליך על מה דבר יהוה עלינו את כל הרעה הגדולה הזאת ומה עוננו ומה חטאתנו אשר חטאנו ליהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JR16_11","025_16_11","JER","16","11","11","ואמרת אליהם על אשר עזבו אבותיכם אותי נאם יהוה וילכו אחרי אלהים אחרים ויעבדום וישתחוו להם ואתי עזבו ואת תורתי לא שמרו׃ ");
INSERT INTO heb_vpl VALUES ("JR16_12","025_16_12","JER","16","12","12","ואתם הרעתם לעשות מאבותיכם והנכם הלכים איש אחרי שררות לבו הרע לבלתי שמע אלי׃ ");
INSERT INTO heb_vpl VALUES ("JR16_13","025_16_13","JER","16","13","13","והטלתי אתכם מעל הארץ הזאת על הארץ אשר לא ידעתם אתם ואבותיכם ועבדתם שם את אלהים אחרים יומם ולילה אשר לא אתן לכם חנינה׃ ");
INSERT INTO heb_vpl VALUES ("JR16_14","025_16_14","JER","16","14","14","לכן הנה ימים באים נאם יהוה ולא יאמר עוד חי יהוה אשר העלה את בני ישראל מארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR16_15","025_16_15","JER","16","15","15","כי אם חי יהוה אשר העלה את בני ישראל מארץ צפון ומכל הארצות אשר הדיחם שמה והשבתים על אדמתם אשר נתתי לאבותם׃ ");
INSERT INTO heb_vpl VALUES ("JR16_16","025_16_16","JER","16","16","16","הנני שלח לדוגים רבים נאם יהוה ודיגום ואחרי כן אשלח לרבים צידים וצדום מעל כל הר ומעל כל גבעה ומנקיקי הסלעים׃ ");
INSERT INTO heb_vpl VALUES ("JR16_17","025_16_17","JER","16","17","17","כי עיני על כל דרכיהם לא נסתרו מלפני ולא נצפן עונם מנגד עיני׃ ");
INSERT INTO heb_vpl VALUES ("JR16_18","025_16_18","JER","16","18","18","ושלמתי ראשונה משנה עונם וחטאתם על חללם את ארצי בנבלת שקוציהם ותועבותיהם מלאו את נחלתי׃ ");
INSERT INTO heb_vpl VALUES ("JR16_19","025_16_19","JER","16","19","19","יהוה עזי ומעזי ומנוסי ביום צרה אליך גוים יבאו מאפסי ארץ ויאמרו אך שקר נחלו אבותינו הבל ואין בם מועיל׃ ");
INSERT INTO heb_vpl VALUES ("JR16_20","025_16_20","JER","16","20","20","היעשה לו אדם אלהים והמה לא אלהים׃ ");
INSERT INTO heb_vpl VALUES ("JR16_21","025_16_21","JER","16","21","21","לכן הנני מודיעם בפעם הזאת אודיעם את ידי ואת גבורתי וידעו כי שמי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR17_1","025_17_1","JER","17","1","1","חטאת יהודה כתובה בעט ברזל בצפרן שמיר חרושה על לוח לבם ולקרנות מזבחותיכם׃ ");
INSERT INTO heb_vpl VALUES ("JR17_2","025_17_2","JER","17","2","2","כזכר בניהם מזבחותם ואשריהם על עץ רענן על גבעות הגבהות׃ ");
INSERT INTO heb_vpl VALUES ("JR17_3","025_17_3","JER","17","3","3","הררי בשדה חילך כל אוצרותיך לבז אתן במתיך בחטאת בכל גבוליך׃ ");
INSERT INTO heb_vpl VALUES ("JR17_4","025_17_4","JER","17","4","4","ושמטתה ובך מנחלתך אשר נתתי לך והעבדתיך את איביך בארץ אשר לא ידעת כי אש קדחתם באפי עד עולם תוקד׃ ");
INSERT INTO heb_vpl VALUES ("JR17_5","025_17_5","JER","17","5","5","כה אמר יהוה ארור הגבר אשר יבטח באדם ושם בשר זרעו ומן יהוה יסור לבו׃ ");
INSERT INTO heb_vpl VALUES ("JR17_6","025_17_6","JER","17","6","6","והיה כערער בערבה ולא יראה כי יבוא טוב ושכן חררים במדבר ארץ מלחה ולא תשב׃ ");
INSERT INTO heb_vpl VALUES ("JR17_7","025_17_7","JER","17","7","7","ברוך הגבר אשר יבטח ביהוה והיה יהוה מבטחו׃ ");
INSERT INTO heb_vpl VALUES ("JR17_8","025_17_8","JER","17","8","8","והיה כעץ שתול על מים ועל יובל ישלח שרשיו ולא ירא כי יבא חם והיה עלהו רענן ובשנת בצרת לא ידאג ולא ימיש מעשות פרי׃ ");
INSERT INTO heb_vpl VALUES ("JR17_9","025_17_9","JER","17","9","9","עקב הלב מכל ואנש הוא מי ידענו׃ ");
INSERT INTO heb_vpl VALUES ("JR17_10","025_17_10","JER","17","10","10","אני יהוה חקר לב בחן כליות ולתת לאיש כדרכו כפרי מעלליו׃ ");
INSERT INTO heb_vpl VALUES ("JR17_11","025_17_11","JER","17","11","11","קרא דגר ולא ילד עשה עשר ולא במשפט בחצי ימו יעזבנו ובאחריתו יהיה נבל׃ ");
INSERT INTO heb_vpl VALUES ("JR17_12","025_17_12","JER","17","12","12","כסא כבוד מרום מראשון מקום מקדשנו׃ ");
INSERT INTO heb_vpl VALUES ("JR17_13","025_17_13","JER","17","13","13","מקוה ישראל יהוה כל עזביך יבשו יסורי בארץ יכתבו כי עזבו מקור מים חיים את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR17_14","025_17_14","JER","17","14","14","רפאני יהוה וארפא הושיעני ואושעה כי תהלתי אתה׃ ");
INSERT INTO heb_vpl VALUES ("JR17_15","025_17_15","JER","17","15","15","הנה המה אמרים אלי איה דבר יהוה יבוא נא׃ ");
INSERT INTO heb_vpl VALUES ("JR17_16","025_17_16","JER","17","16","16","ואני לא אצתי מרעה אחריך ויום אנוש לא התאויתי אתה ידעת מוצא שפתי נכח פניך היה׃ ");
INSERT INTO heb_vpl VALUES ("JR17_17","025_17_17","JER","17","17","17","אל תהיה לי למחתה מחסי אתה ביום רעה׃ ");
INSERT INTO heb_vpl VALUES ("JR17_18","025_17_18","JER","17","18","18","יבשו רדפי ואל אבשה אני יחתו המה ואל אחתה אני הביא עליהם יום רעה ומשנה שברון שברם׃ ");
INSERT INTO heb_vpl VALUES ("JR17_19","025_17_19","JER","17","19","19","כה אמר יהוה אלי הלך ועמדת בשער בני עם אשר יבאו בו מלכי יהודה ואשר יצאו בו ובכל שערי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR17_20","025_17_20","JER","17","20","20","ואמרת אליהם שמעו דבר יהוה מלכי יהודה וכל יהודה וכל ישבי ירושלם הבאים בשערים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR17_21","025_17_21","JER","17","21","21","כה אמר יהוה השמרו בנפשותיכם ואל תשאו משא ביום השבת והבאתם בשערי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR17_22","025_17_22","JER","17","22","22","ולא תוציאו משא מבתיכם ביום השבת וכל מלאכה לא תעשו וקדשתם את יום השבת כאשר צויתי את אבותיכם׃ ");
INSERT INTO heb_vpl VALUES ("JR17_23","025_17_23","JER","17","23","23","ולא שמעו ולא הטו את אזנם ויקשו את ערפם לבלתי שומע ולבלתי קחת מוסר׃ ");
INSERT INTO heb_vpl VALUES ("JR17_24","025_17_24","JER","17","24","24","והיה אם שמע תשמעון אלי נאם יהוה לבלתי הביא משא בשערי העיר הזאת ביום השבת ולקדש את יום השבת לבלתי עשות בה כל מלאכה׃ ");
INSERT INTO heb_vpl VALUES ("JR17_25","025_17_25","JER","17","25","25","ובאו בשערי העיר הזאת מלכים ושרים ישבים על כסא דוד רכבים ברכב ובסוסים המה ושריהם איש יהודה וישבי ירושלם וישבה העיר הזאת לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JR17_26","025_17_26","JER","17","26","26","ובאו מערי יהודה ומסביבות ירושלם ומארץ בנימן ומן השפלה ומן ההר ומן הנגב מבאים עולה וזבח ומנחה ולבונה ומבאי תודה בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR17_27","025_17_27","JER","17","27","27","ואם לא תשמעו אלי לקדש את יום השבת ולבלתי שאת משא ובא בשערי ירושלם ביום השבת והצתי אש בשעריה ואכלה ארמנות ירושלם ולא תכבה׃ ");
INSERT INTO heb_vpl VALUES ("JR18_1","025_18_1","JER","18","1","1","הדבר אשר היה אל ירמיהו מאת יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR18_2","025_18_2","JER","18","2","2","קום וירדת בית היוצר ושמה אשמיעך את דברי׃ ");
INSERT INTO heb_vpl VALUES ("JR18_3","025_18_3","JER","18","3","3","וארד בית היוצר והנהו עשה מלאכה על האבנים׃ ");
INSERT INTO heb_vpl VALUES ("JR18_4","025_18_4","JER","18","4","4","ונשחת הכלי אשר הוא עשה בחמר ביד היוצר ושב ויעשהו כלי אחר כאשר ישר בעיני היוצר לעשות׃ ");
INSERT INTO heb_vpl VALUES ("JR18_5","025_18_5","JER","18","5","5","ויהי דבר יהוה אלי לאמור׃ ");
INSERT INTO heb_vpl VALUES ("JR18_6","025_18_6","JER","18","6","6","הכיוצר הזה לא אוכל לעשות לכם בית ישראל נאם יהוה הנה כחמר ביד היוצר כן אתם בידי בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR18_7","025_18_7","JER","18","7","7","רגע אדבר על גוי ועל ממלכה לנתוש ולנתוץ ולהאביד׃ ");
INSERT INTO heb_vpl VALUES ("JR18_8","025_18_8","JER","18","8","8","ושב הגוי ההוא מרעתו אשר דברתי עליו ונחמתי על הרעה אשר חשבתי לעשות לו׃ ");
INSERT INTO heb_vpl VALUES ("JR18_9","025_18_9","JER","18","9","9","ורגע אדבר על גוי ועל ממלכה לבנת ולנטע׃ ");
INSERT INTO heb_vpl VALUES ("JR18_10","025_18_10","JER","18","10","10","ועשה הרעה בעיני לבלתי שמע בקולי ונחמתי על הטובה אשר אמרתי להיטיב אותו׃ ");
INSERT INTO heb_vpl VALUES ("JR18_11","025_18_11","JER","18","11","11","ועתה אמר נא אל איש יהודה ועל יושבי ירושלם לאמר כה אמר יהוה הנה אנכי יוצר עליכם רעה וחשב עליכם מחשבה שובו נא איש מדרכו הרעה והיטיבו דרכיכם ומעלליכם׃ ");
INSERT INTO heb_vpl VALUES ("JR18_12","025_18_12","JER","18","12","12","ואמרו נואש כי אחרי מחשבותינו נלך ואיש שררות לבו הרע נעשה׃ ");
INSERT INTO heb_vpl VALUES ("JR18_13","025_18_13","JER","18","13","13","לכן כה אמר יהוה שאלו נא בגוים מי שמע כאלה שעררת עשתה מאד בתולת ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR18_14","025_18_14","JER","18","14","14","היעזב מצור שדי שלג לבנון אם ינתשו מים זרים קרים נוזלים׃ ");
INSERT INTO heb_vpl VALUES ("JR18_15","025_18_15","JER","18","15","15","כי שכחני עמי לשוא יקטרו ויכשלום בדרכיהם שבילי עולם ללכת נתיבות דרך לא סלולה׃ ");
INSERT INTO heb_vpl VALUES ("JR18_16","025_18_16","JER","18","16","16","לשום ארצם לשמה שרוקת עולם כל עובר עליה ישם ויניד בראשו׃ ");
INSERT INTO heb_vpl VALUES ("JR18_17","025_18_17","JER","18","17","17","כרוח קדים אפיצם לפני אויב ערף ולא פנים אראם ביום אידם׃ ");
INSERT INTO heb_vpl VALUES ("JR18_18","025_18_18","JER","18","18","18","ויאמרו לכו ונחשבה על ירמיהו מחשבות כי לא תאבד תורה מכהן ועצה מחכם ודבר מנביא לכו ונכהו בלשון ואל נקשיבה אל כל דבריו׃ ");
INSERT INTO heb_vpl VALUES ("JR18_19","025_18_19","JER","18","19","19","הקשיבה יהוה אלי ושמע לקול יריבי׃ ");
INSERT INTO heb_vpl VALUES ("JR18_20","025_18_20","JER","18","20","20","הישלם תחת טובה רעה כי כרו שוחה לנפשי זכר עמדי לפניך לדבר עליהם טובה להשיב את חמתך מהם׃ ");
INSERT INTO heb_vpl VALUES ("JR18_21","025_18_21","JER","18","21","21","לכן תן את בניהם לרעב והגרם על ידי חרב ותהינה נשיהם שכלות ואלמנות ואנשיהם יהיו הרגי מות בחוריהם מכי חרב במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JR18_22","025_18_22","JER","18","22","22","תשמע זעקה מבתיהם כי תביא עליהם גדוד פתאם כי כרו שיחה ללכדני ופחים טמנו לרגלי׃ ");
INSERT INTO heb_vpl VALUES ("JR18_23","025_18_23","JER","18","23","23","ואתה יהוה ידעת את כל עצתם עלי למות אל תכפר על עונם וחטאתם מלפניך אל תמחי והיו מכשלים לפניך בעת אפך עשה בהם׃ ");
INSERT INTO heb_vpl VALUES ("JR19_1","025_19_1","JER","19","1","1","כה אמר יהוה הלוך וקנית בקבק יוצר חרש ומזקני העם ומזקני הכהנים׃ ");
INSERT INTO heb_vpl VALUES ("JR19_2","025_19_2","JER","19","2","2","ויצאת אל גיא בן הנם אשר פתח שער החרסות וקראת שם את הדברים אשר אדבר אליך׃ ");
INSERT INTO heb_vpl VALUES ("JR19_3","025_19_3","JER","19","3","3","ואמרת שמעו דבר יהוה מלכי יהודה וישבי ירושלם כה אמר יהוה צבאות אלהי ישראל הנני מביא רעה על המקום הזה אשר כל שמעה תצלנה אזניו׃ ");
INSERT INTO heb_vpl VALUES ("JR19_4","025_19_4","JER","19","4","4","יען אשר עזבני וינכרו את המקום הזה ויקטרו בו לאלהים אחרים אשר לא ידעום המה ואבותיהם ומלכי יהודה ומלאו את המקום הזה דם נקים׃ ");
INSERT INTO heb_vpl VALUES ("JR19_5","025_19_5","JER","19","5","5","ובנו את במות הבעל לשרף את בניהם באש עלות לבעל אשר לא צויתי ולא דברתי ולא עלתה על לבי׃ ");
INSERT INTO heb_vpl VALUES ("JR19_6","025_19_6","JER","19","6","6","לכן הנה ימים באים נאם יהוה ולא יקרא למקום הזה עוד התפת וגיא בן הנם כי אם גיא ההרגה׃ ");
INSERT INTO heb_vpl VALUES ("JR19_7","025_19_7","JER","19","7","7","ובקתי את עצת יהודה וירושלם במקום הזה והפלתים בחרב לפני איביהם וביד מבקשי נפשם ונתתי את נבלתם למאכל לעוף השמים ולבהמת הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR19_8","025_19_8","JER","19","8","8","ושמתי את העיר הזאת לשמה ולשרקה כל עבר עליה ישם וישרק על כל מכתה׃ ");
INSERT INTO heb_vpl VALUES ("JR19_9","025_19_9","JER","19","9","9","והאכלתים את בשר בניהם ואת בשר בנתיהם ואיש בשר רעהו יאכלו במצור ובמצוק אשר יציקו להם איביהם ומבקשי נפשם׃ ");
INSERT INTO heb_vpl VALUES ("JR19_10","025_19_10","JER","19","10","10","ושברת הבקבק לעיני האנשים ההלכים אותך׃ ");
INSERT INTO heb_vpl VALUES ("JR19_11","025_19_11","JER","19","11","11","ואמרת אליהם כה אמר יהוה צבאות ככה אשבר את העם הזה ואת העיר הזאת כאשר ישבר את כלי היוצר אשר לא יוכל להרפה עוד ובתפת יקברו מאין מקום לקבור׃ ");
INSERT INTO heb_vpl VALUES ("JR19_12","025_19_12","JER","19","12","12","כן אעשה למקום הזה נאם יהוה וליושביו ולתת את העיר הזאת כתפת׃ ");
INSERT INTO heb_vpl VALUES ("JR19_13","025_19_13","JER","19","13","13","והיו בתי ירושלם ובתי מלכי יהודה כמקום התפת הטמאים לכל הבתים אשר קטרו על גגתיהם לכל צבא השמים והסך נסכים לאלהים אחרים׃ ");
INSERT INTO heb_vpl VALUES ("JR19_14","025_19_14","JER","19","14","14","ויבא ירמיהו מהתפת אשר שלחו יהוה שם להנבא ויעמד בחצר בית יהוה ויאמר אל כל העם׃ ");
INSERT INTO heb_vpl VALUES ("JR19_15","025_19_15","JER","19","15","15","כה אמר יהוה צבאות אלהי ישראל הנני מבי אל העיר הזאת ועל כל עריה את כל הרעה אשר דברתי עליה כי הקשו את ערפם לבלתי שמוע את דברי׃ ");
INSERT INTO heb_vpl VALUES ("JR20_1","025_20_1","JER","20","1","1","וישמע פשחור בן אמר הכהן והוא פקיד נגיד בבית יהוה את ירמיהו נבא את הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR20_2","025_20_2","JER","20","2","2","ויכה פשחור את ירמיהו הנביא ויתן אתו על המהפכת אשר בשער בנימן העליון אשר בבית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR20_3","025_20_3","JER","20","3","3","ויהי ממחרת ויצא פשחור את ירמיהו מן המהפכת ויאמר אליו ירמיהו לא פשחור קרא יהוה שמך כי אם מגור מסביב׃ ");
INSERT INTO heb_vpl VALUES ("JR20_4","025_20_4","JER","20","4","4","כי כה אמר יהוה הנני נתנך למגור לך ולכל אהביך ונפלו בחרב איביהם ועיניך ראות ואת כל יהודה אתן ביד מלך בבל והגלם בבלה והכם בחרב׃ ");
INSERT INTO heb_vpl VALUES ("JR20_5","025_20_5","JER","20","5","5","ונתתי את כל חסן העיר הזאת ואת כל יגיעה ואת כל יקרה ואת כל אוצרות מלכי יהודה אתן ביד איביהם ובזזום ולקחום והביאום בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR20_6","025_20_6","JER","20","6","6","ואתה פשחור וכל ישבי ביתך תלכו בשבי ובבל תבוא ושם תמות ושם תקבר אתה וכל אהביך אשר נבאת להם בשקר׃ ");
INSERT INTO heb_vpl VALUES ("JR20_7","025_20_7","JER","20","7","7","פתיתני יהוה ואפת חזקתני ותוכל הייתי לשחוק כל היום כלה לעג לי׃ ");
INSERT INTO heb_vpl VALUES ("JR20_8","025_20_8","JER","20","8","8","כי מדי אדבר אזעק חמס ושד אקרא כי היה דבר יהוה לי לחרפה ולקלס כל היום׃ ");
INSERT INTO heb_vpl VALUES ("JR20_9","025_20_9","JER","20","9","9","ואמרתי לא אזכרנו ולא אדבר עוד בשמו והיה בלבי כאש בערת עצר בעצמתי ונלאיתי כלכל ולא אוכל׃ ");
INSERT INTO heb_vpl VALUES ("JR20_10","025_20_10","JER","20","10","10","כי שמעתי דבת רבים מגור מסביב הגידו ונגידנו כל אנוש שלומי שמרי צלעי אולי יפתה ונוכלה לו ונקחה נקמתנו ממנו׃ ");
INSERT INTO heb_vpl VALUES ("JR20_11","025_20_11","JER","20","11","11","ויהוה אותי כגבור עריץ על כן רדפי יכשלו ולא יכלו בשו מאד כי לא השכילו כלמת עולם לא תשכח׃ ");
INSERT INTO heb_vpl VALUES ("JR20_12","025_20_12","JER","20","12","12","ויהוה צבאות בחן צדיק ראה כליות ולב אראה נקמתך מהם כי אליך גליתי את ריבי׃ ");
INSERT INTO heb_vpl VALUES ("JR20_13","025_20_13","JER","20","13","13","שירו ליהוה הללו את יהוה כי הציל את נפש אביון מיד מרעים׃ ");
INSERT INTO heb_vpl VALUES ("JR20_14","025_20_14","JER","20","14","14","ארור היום אשר ילדתי בו יום אשר ילדתני אמי אל יהי ברוך׃ ");
INSERT INTO heb_vpl VALUES ("JR20_15","025_20_15","JER","20","15","15","ארור האיש אשר בשר את אבי לאמר ילד לך בן זכר שמח שמחהו׃ ");
INSERT INTO heb_vpl VALUES ("JR20_16","025_20_16","JER","20","16","16","והיה האיש ההוא כערים אשר הפך יהוה ולא נחם ושמע זעקה בבקר ותרועה בעת צהרים׃ ");
INSERT INTO heb_vpl VALUES ("JR20_17","025_20_17","JER","20","17","17","אשר לא מותתני מרחם ותהי לי אמי קברי ורחמה הרת עולם׃ ");
INSERT INTO heb_vpl VALUES ("JR20_18","025_20_18","JER","20","18","18","למה זה מרחם יצאתי לראות עמל ויגון ויכלו בבשת ימי׃ ");
INSERT INTO heb_vpl VALUES ("JR21_1","025_21_1","JER","21","1","1","הדבר אשר היה אל ירמיהו מאת יהוה בשלח אליו המלך צדקיהו את פשחור בן מלכיה ואת צפניה בן מעשיה הכהן לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR21_2","025_21_2","JER","21","2","2","דרש נא בעדנו את יהוה כי נבוכדראצר מלך בבל נלחם עלינו אולי יעשה יהוה אותנו ככל נפלאתיו ויעלה מעלינו׃ ");
INSERT INTO heb_vpl VALUES ("JR21_3","025_21_3","JER","21","3","3","ויאמר ירמיהו אליהם כה תאמרן אל צדקיהו׃ ");
INSERT INTO heb_vpl VALUES ("JR21_4","025_21_4","JER","21","4","4","כה אמר יהוה אלהי ישראל הנני מסב את כלי המלחמה אשר בידכם אשר אתם נלחמים בם את מלך בבל ואת הכשדים הצרים עליכם מחוץ לחומה ואספתי אותם אל תוך העיר הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR21_5","025_21_5","JER","21","5","5","ונלחמתי אני אתכם ביד נטויה ובזרוע חזקה ובאף ובחמה ובקצף גדול׃ ");
INSERT INTO heb_vpl VALUES ("JR21_6","025_21_6","JER","21","6","6","והכיתי את יושבי העיר הזאת ואת האדם ואת הבהמה בדבר גדול ימתו׃ ");
INSERT INTO heb_vpl VALUES ("JR21_7","025_21_7","JER","21","7","7","ואחרי כן נאם יהוה אתן את צדקיהו מלך יהודה ואת עבדיו ואת העם ואת הנשארים בעיר הזאת מן הדבר מן החרב ומן הרעב ביד נבוכדראצר מלך בבל וביד איביהם וביד מבקשי נפשם והכם לפי חרב לא יחוס עליהם ולא יחמל ולא ירחם׃ ");
INSERT INTO heb_vpl VALUES ("JR21_8","025_21_8","JER","21","8","8","ואל העם הזה תאמר כה אמר יהוה הנני נתן לפניכם את דרך החיים ואת דרך המות׃ ");
INSERT INTO heb_vpl VALUES ("JR21_9","025_21_9","JER","21","9","9","הישב בעיר הזאת ימות בחרב וברעב ובדבר והיוצא ונפל על הכשדים הצרים עליכם יחיה והיתה לו נפשו לשלל׃ ");
INSERT INTO heb_vpl VALUES ("JR21_10","025_21_10","JER","21","10","10","כי שמתי פני בעיר הזאת לרעה ולא לטובה נאם יהוה ביד מלך בבל תנתן ושרפה באש׃ ");
INSERT INTO heb_vpl VALUES ("JR21_11","025_21_11","JER","21","11","11","ולבית מלך יהודה שמעו דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR21_12","025_21_12","JER","21","12","12","בית דוד כה אמר יהוה דינו לבקר משפט והצילו גזול מיד עושק פן תצא כאש חמתי ובערה ואין מכבה מפני רע מעלליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR21_13","025_21_13","JER","21","13","13","הנני אליך ישבת העמק צור המישר נאם יהוה האמרים מי יחת עלינו ומי יבוא במעונותינו׃ ");
INSERT INTO heb_vpl VALUES ("JR21_14","025_21_14","JER","21","14","14","ופקדתי עליכם כפרי מעלליכם נאם יהוה והצתי אש ביערה ואכלה כל סביביה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_1","025_22_1","JER","22","1","1","כה אמר יהוה רד בית מלך יהודה ודברת שם את הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_2","025_22_2","JER","22","2","2","ואמרת שמע דבר יהוה מלך יהודה הישב על כסא דוד אתה ועבדיך ועמך הבאים בשערים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_3","025_22_3","JER","22","3","3","כה אמר יהוה עשו משפט וצדקה והצילו גזול מיד עשוק וגר יתום ואלמנה אל תנו אל תחמסו ודם נקי אל תשפכו במקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_4","025_22_4","JER","22","4","4","כי אם עשו תעשו את הדבר הזה ובאו בשערי הבית הזה מלכים ישבים לדוד על כסאו רכבים ברכב ובסוסים הוא ועבדו ועמו׃ ");
INSERT INTO heb_vpl VALUES ("JR22_5","025_22_5","JER","22","5","5","ואם לא תשמעו את הדברים האלה בי נשבעתי נאם יהוה כי לחרבה יהיה הבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_6","025_22_6","JER","22","6","6","כי כה אמר יהוה על בית מלך יהודה גלעד אתה לי ראש הלבנון אם לא אשיתך מדבר ערים לא נושבה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_7","025_22_7","JER","22","7","7","וקדשתי עליך משחתים איש וכליו וכרתו מבחר ארזיך והפילו על האש׃ ");
INSERT INTO heb_vpl VALUES ("JR22_8","025_22_8","JER","22","8","8","ועברו גוים רבים על העיר הזאת ואמרו איש אל רעהו על מה עשה יהוה ככה לעיר הגדולה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR22_9","025_22_9","JER","22","9","9","ואמרו על אשר עזבו את ברית יהוה אלהיהם וישתחוו לאלהים אחרים ויעבדום׃ ");
INSERT INTO heb_vpl VALUES ("JR22_10","025_22_10","JER","22","10","10","אל תבכו למת ואל תנדו לו בכו בכו להלך כי לא ישוב עוד וראה את ארץ מולדתו׃ ");
INSERT INTO heb_vpl VALUES ("JR22_11","025_22_11","JER","22","11","11","כי כה אמר יהוה אל שלם בן יאשיהו מלך יהודה המלך תחת יאשיהו אביו אשר יצא מן המקום הזה לא ישוב שם עוד׃ ");
INSERT INTO heb_vpl VALUES ("JR22_12","025_22_12","JER","22","12","12","כי במקום אשר הגלו אתו שם ימות ואת הארץ הזאת לא יראה עוד׃ ");
INSERT INTO heb_vpl VALUES ("JR22_13","025_22_13","JER","22","13","13","הוי בנה ביתו בלא צדק ועליותיו בלא משפט ברעהו יעבד חנם ופעלו לא יתן לו׃ ");
INSERT INTO heb_vpl VALUES ("JR22_14","025_22_14","JER","22","14","14","האמר אבנה לי בית מדות ועליות מרוחים וקרע לו חלוני וספון בארז ומשוח בששר׃ ");
INSERT INTO heb_vpl VALUES ("JR22_15","025_22_15","JER","22","15","15","התמלך כי אתה מתחרה בארז אביך הלוא אכל ושתה ועשה משפט וצדקה אז טוב לו׃ ");
INSERT INTO heb_vpl VALUES ("JR22_16","025_22_16","JER","22","16","16","דן דין עני ואביון אז טוב הלוא היא הדעת אתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_17","025_22_17","JER","22","17","17","כי אין עיניך ולבך כי אם על בצעך ועל דם הנקי לשפוך ועל העשק ועל המרוצה לעשות׃ ");
INSERT INTO heb_vpl VALUES ("JR22_18","025_22_18","JER","22","18","18","לכן כה אמר יהוה אל יהויקים בן יאשיהו מלך יהודה לא יספדו לו הוי אחי והוי אחות לא יספדו לו הוי אדון והוי הדה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_19","025_22_19","JER","22","19","19","קבורת חמור יקבר סחוב והשלך מהלאה לשערי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR22_20","025_22_20","JER","22","20","20","עלי הלבנון וצעקי ובבשן תני קולך וצעקי מעברים כי נשברו כל מאהביך׃ ");
INSERT INTO heb_vpl VALUES ("JR22_21","025_22_21","JER","22","21","21","דברתי אליך בשלותיך אמרת לא אשמע זה דרכך מנעוריך כי לא שמעת בקולי׃ ");
INSERT INTO heb_vpl VALUES ("JR22_22","025_22_22","JER","22","22","22","כל רעיך תרעה רוח ומאהביך בשבי ילכו כי אז תבשי ונכלמת מכל רעתך׃ ");
INSERT INTO heb_vpl VALUES ("JR22_23","025_22_23","JER","22","23","23","ישבתי בלבנון מקננתי בארזים מה נחנת בבא לך חבלים חיל כילדה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_24","025_22_24","JER","22","24","24","חי אני נאם יהוה כי אם יהיה כניהו בן יהויקים מלך יהודה חותם על יד ימיני כי משם אתקנך׃ ");
INSERT INTO heb_vpl VALUES ("JR22_25","025_22_25","JER","22","25","25","ונתתיך ביד מבקשי נפשך וביד אשר אתה יגור מפניהם וביד נבוכדראצר מלך בבל וביד הכשדים׃ ");
INSERT INTO heb_vpl VALUES ("JR22_26","025_22_26","JER","22","26","26","והטלתי אתך ואת אמך אשר ילדתך על הארץ אחרת אשר לא ילדתם שם ושם תמותו׃ ");
INSERT INTO heb_vpl VALUES ("JR22_27","025_22_27","JER","22","27","27","ועל הארץ אשר הם מנשאים את נפשם לשוב שם שמה לא ישובו׃ ");
INSERT INTO heb_vpl VALUES ("JR22_28","025_22_28","JER","22","28","28","העצב נבזה נפוץ האיש הזה כניהו אם כלי אין חפץ בו מדוע הוטלו הוא וזרעו והשלכו על הארץ אשר לא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("JR22_29","025_22_29","JER","22","29","29","ארץ ארץ ארץ שמעי דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR22_30","025_22_30","JER","22","30","30","כה אמר יהוה כתבו את האיש הזה ערירי גבר לא יצלח בימיו כי לא יצלח מזרעו איש ישב על כסא דוד ומשל עוד ביהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_1","025_23_1","JER","23","1","1","הוי רעים מאבדים ומפצים את צאן מרעיתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_2","025_23_2","JER","23","2","2","לכן כה אמר יהוה אלהי ישראל על הרעים הרעים את עמי אתם הפצתם את צאני ותדחום ולא פקדתם אתם הנני פקד עליכם את רע מעלליכם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_3","025_23_3","JER","23","3","3","ואני אקבץ את שארית צאני מכל הארצות אשר הדחתי אתם שם והשבתי אתהן על נוהן ופרו ורבו׃ ");
INSERT INTO heb_vpl VALUES ("JR23_4","025_23_4","JER","23","4","4","והקמתי עליהם רעים ורעום ולא ייראו עוד ולא יחתו ולא יפקדו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_5","025_23_5","JER","23","5","5","הנה ימים באים נאם יהוה והקמתי לדוד צמח צדיק ומלך מלך והשכיל ועשה משפט וצדקה בארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR23_6","025_23_6","JER","23","6","6","בימיו תושע יהודה וישראל ישכן לבטח וזה שמו אשר יקראו יהוה צדקנו׃ ");
INSERT INTO heb_vpl VALUES ("JR23_7","025_23_7","JER","23","7","7","לכן הנה ימים באים נאם יהוה ולא יאמרו עוד חי יהוה אשר העלה את בני ישראל מארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR23_8","025_23_8","JER","23","8","8","כי אם חי יהוה אשר העלה ואשר הביא את זרע בית ישראל מארץ צפונה ומכל הארצות אשר הדחתים שם וישבו על אדמתם׃ ");
INSERT INTO heb_vpl VALUES ("JR23_9","025_23_9","JER","23","9","9","לנבאים נשבר לבי בקרבי רחפו כל עצמותי הייתי כאיש שכור וכגבר עברו יין מפני יהוה ומפני דברי קדשו׃ ");
INSERT INTO heb_vpl VALUES ("JR23_10","025_23_10","JER","23","10","10","כי מנאפים מלאה הארץ כי מפני אלה אבלה הארץ יבשו נאות מדבר ותהי מרוצתם רעה וגבורתם לא כן׃ ");
INSERT INTO heb_vpl VALUES ("JR23_11","025_23_11","JER","23","11","11","כי גם נביא גם כהן חנפו גם בביתי מצאתי רעתם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_12","025_23_12","JER","23","12","12","לכן יהיה דרכם להם כחלקלקות באפלה ידחו ונפלו בה כי אביא עליהם רעה שנת פקדתם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_13","025_23_13","JER","23","13","13","ובנביאי שמרון ראיתי תפלה הנבאו בבעל ויתעו את עמי את ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR23_14","025_23_14","JER","23","14","14","ובנבאי ירושלם ראיתי שערורה נאוף והלך בשקר וחזקו ידי מרעים לבלתי שבו איש מרעתו היו לי כלם כסדם וישביה כעמרה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_15","025_23_15","JER","23","15","15","לכן כה אמר יהוה צבאות על הנבאים הנני מאכיל אותם לענה והשקתים מי ראש כי מאת נביאי ירושלם יצאה חנפה לכל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR23_16","025_23_16","JER","23","16","16","כה אמר יהוה צבאות אל תשמעו על דברי הנבאים הנבאים לכם מהבלים המה אתכם חזון לבם ידברו לא מפי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_17","025_23_17","JER","23","17","17","אמרים אמור למנאצי דבר יהוה שלום יהיה לכם וכל הלך בשררות לבו אמרו לא תבוא עליכם רעה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_18","025_23_18","JER","23","18","18","כי מי עמד בסוד יהוה וירא וישמע את דברו מי הקשיב דברי וישמע׃ ");
INSERT INTO heb_vpl VALUES ("JR23_19","025_23_19","JER","23","19","19","הנה סערת יהוה חמה יצאה וסער מתחולל על ראש רשעים יחול׃ ");
INSERT INTO heb_vpl VALUES ("JR23_20","025_23_20","JER","23","20","20","לא ישוב אף יהוה עד עשתו ועד הקימו מזמות לבו באחרית הימים תתבוננו בה בינה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_21","025_23_21","JER","23","21","21","לא שלחתי את הנבאים והם רצו לא דברתי אליהם והם נבאו׃ ");
INSERT INTO heb_vpl VALUES ("JR23_22","025_23_22","JER","23","22","22","ואם עמדו בסודי וישמעו דברי את עמי וישבום מדרכם הרע ומרע מעלליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR23_23","025_23_23","JER","23","23","23","האלהי מקרב אני נאם יהוה ולא אלהי מרחק׃ ");
INSERT INTO heb_vpl VALUES ("JR23_24","025_23_24","JER","23","24","24","אם יסתר איש במסתרים ואני לא אראנו נאם יהוה הלוא את השמים ואת הארץ אני מלא נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_25","025_23_25","JER","23","25","25","שמעתי את אשר אמרו הנבאים הנבאים בשמי שקר לאמר חלמתי חלמתי׃ ");
INSERT INTO heb_vpl VALUES ("JR23_26","025_23_26","JER","23","26","26","עד מתי היש בלב הנבאים נבאי השקר ונביאי תרמת לבם׃ ");
INSERT INTO heb_vpl VALUES ("JR23_27","025_23_27","JER","23","27","27","החשבים להשכיח את עמי שמי בחלומתם אשר יספרו איש לרעהו כאשר שכחו אבותם את שמי בבעל׃ ");
INSERT INTO heb_vpl VALUES ("JR23_28","025_23_28","JER","23","28","28","הנביא אשר אתו חלום יספר חלום ואשר דברי אתו ידבר דברי אמת מה לתבן את הבר נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_29","025_23_29","JER","23","29","29","הלוא כה דברי כאש נאם יהוה וכפטיש יפצץ סלע׃ ");
INSERT INTO heb_vpl VALUES ("JR23_30","025_23_30","JER","23","30","30","לכן הנני על הנבאים נאם יהוה מגנבי דברי איש מאת רעהו׃ ");
INSERT INTO heb_vpl VALUES ("JR23_31","025_23_31","JER","23","31","31","הנני על הנביאם נאם יהוה הלקחים לשונם וינאמו נאם׃ ");
INSERT INTO heb_vpl VALUES ("JR23_32","025_23_32","JER","23","32","32","הנני על נבאי חלמות שקר נאם יהוה ויספרום ויתעו את עמי בשקריהם ובפחזותם ואנכי לא שלחתים ולא צויתים והועיל לא יועילו לעם הזה נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_33","025_23_33","JER","23","33","33","וכי ישאלך העם הזה או הנביא או כהן לאמר מה משא יהוה ואמרת אליהם את מה משא ונטשתי אתכם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_34","025_23_34","JER","23","34","34","והנביא והכהן והעם אשר יאמר משא יהוה ופקדתי על האיש ההוא ועל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("JR23_35","025_23_35","JER","23","35","35","כה תאמרו איש על רעהו ואיש אל אחיו מה ענה יהוה ומה דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_36","025_23_36","JER","23","36","36","ומשא יהוה לא תזכרו עוד כי המשא יהיה לאיש דברו והפכתם את דברי אלהים חיים יהוה צבאות אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JR23_37","025_23_37","JER","23","37","37","כה תאמר אל הנביא מה ענך יהוה ומה דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_38","025_23_38","JER","23","38","38","ואם משא יהוה תאמרו לכן כה אמר יהוה יען אמרכם את הדבר הזה משא יהוה ואשלח אליכם לאמר לא תאמרו משא יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR23_39","025_23_39","JER","23","39","39","לכן הנני ונשיתי אתכם נשא ונטשתי אתכם ואת העיר אשר נתתי לכם ולאבותיכם מעל פני׃ ");
INSERT INTO heb_vpl VALUES ("JR23_40","025_23_40","JER","23","40","40","ונתתי עליכם חרפת עולם וכלמות עולם אשר לא תשכח׃ ");
INSERT INTO heb_vpl VALUES ("JR24_1","025_24_1","JER","24","1","1","הראני יהוה והנה שני דודאי תאנים מועדים לפני היכל יהוה אחרי הגלות נבוכדראצר מלך בבל את יכניהו בן יהויקים מלך יהודה ואת שרי יהודה ואת החרש ואת המסגר מירושלם ויבאם בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR24_2","025_24_2","JER","24","2","2","הדוד אחד תאנים טבות מאד כתאני הבכרות והדוד אחד תאנים רעות מאד אשר לא תאכלנה מרע׃ ");
INSERT INTO heb_vpl VALUES ("JR24_3","025_24_3","JER","24","3","3","ויאמר יהוה אלי מה אתה ראה ירמיהו ואמר תאנים התאנים הטבות טבות מאד והרעות רעות מאד אשר לא תאכלנה מרע׃ ");
INSERT INTO heb_vpl VALUES ("JR24_4","025_24_4","JER","24","4","4","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR24_5","025_24_5","JER","24","5","5","כה אמר יהוה אלהי ישראל כתאנים הטבות האלה כן אכיר את גלות יהודה אשר שלחתי מן המקום הזה ארץ כשדים לטובה׃ ");
INSERT INTO heb_vpl VALUES ("JR24_6","025_24_6","JER","24","6","6","ושמתי עיני עליהם לטובה והשבתים על הארץ הזאת ובניתים ולא אהרס ונטעתים ולא אתוש׃ ");
INSERT INTO heb_vpl VALUES ("JR24_7","025_24_7","JER","24","7","7","ונתתי להם לב לדעת אתי כי אני יהוה והיו לי לעם ואנכי אהיה להם לאלהים כי ישבו אלי בכל לבם׃ ");
INSERT INTO heb_vpl VALUES ("JR24_8","025_24_8","JER","24","8","8","וכתאנים הרעות אשר לא תאכלנה מרע כי כה אמר יהוה כן אתן את צדקיהו מלך יהודה ואת שריו ואת שארית ירושלם הנשארים בארץ הזאת והישבים בארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR24_9","025_24_9","JER","24","9","9","ונתתים לזועה לרעה לכל ממלכות הארץ לחרפה ולמשל לשנינה ולקללה בכל המקמות אשר אדיחם שם׃ ");
INSERT INTO heb_vpl VALUES ("JR24_10","025_24_10","JER","24","10","10","ושלחתי בם את החרב את הרעב ואת הדבר עד תמם מעל האדמה אשר נתתי להם ולאבותיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_1","025_25_1","JER","25","1","1","הדבר אשר היה על ירמיהו על כל עם יהודה בשנה הרבעית ליהויקים בן יאשיהו מלך יהודה היא השנה הראשנית לנבוכדראצר מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR25_2","025_25_2","JER","25","2","2","אשר דבר ירמיהו הנביא על כל עם יהודה ואל כל ישבי ירושלם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR25_3","025_25_3","JER","25","3","3","מן שלש עשרה שנה ליאשיהו בן אמון מלך יהודה ועד היום הזה זה שלש ועשרים שנה היה דבר יהוה אלי ואדבר אליכם אשכים ודבר ולא שמעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_4","025_25_4","JER","25","4","4","ושלח יהוה אליכם את כל עבדיו הנבאים השכם ושלח ולא שמעתם ולא הטיתם את אזנכם לשמע׃ ");
INSERT INTO heb_vpl VALUES ("JR25_5","025_25_5","JER","25","5","5","לאמר שובו נא איש מדרכו הרעה ומרע מעלליכם ושבו על האדמה אשר נתן יהוה לכם ולאבותיכם למן עולם ועד עולם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_6","025_25_6","JER","25","6","6","ואל תלכו אחרי אלהים אחרים לעבדם ולהשתחות להם ולא תכעיסו אותי במעשה ידיכם ולא ארע לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_7","025_25_7","JER","25","7","7","ולא שמעתם אלי נאם יהוה למען הכעסוני במעשה ידיכם לרע לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_8","025_25_8","JER","25","8","8","לכן כה אמר יהוה צבאות יען אשר לא שמעתם את דברי׃ ");
INSERT INTO heb_vpl VALUES ("JR25_9","025_25_9","JER","25","9","9","הנני שלח ולקחתי את כל משפחות צפון נאם יהוה ואל נבוכדראצר מלך בבל עבדי והבאתים על הארץ הזאת ועל ישביה ועל כל הגוים האלה סביב והחרמתים ושמתים לשמה ולשרקה ולחרבות עולם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_10","025_25_10","JER","25","10","10","והאבדתי מהם קול ששון וקול שמחה קול חתן וקול כלה קול רחים ואור נר׃ ");
INSERT INTO heb_vpl VALUES ("JR25_11","025_25_11","JER","25","11","11","והיתה כל הארץ הזאת לחרבה לשמה ועבדו הגוים האלה את מלך בבל שבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("JR25_12","025_25_12","JER","25","12","12","והיה כמלאות שבעים שנה אפקד על מלך בבל ועל הגוי ההוא נאם יהוה את עונם ועל ארץ כשדים ושמתי אתו לשממות עולם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_13","025_25_13","JER","25","13","13","והבאיתי על הארץ ההיא את כל דברי אשר דברתי עליה את כל הכתוב בספר הזה אשר נבא ירמיהו על כל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("JR25_14","025_25_14","JER","25","14","14","כי עבדו בם גם המה גוים רבים ומלכים גדולים ושלמתי להם כפעלם וכמעשה ידיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_15","025_25_15","JER","25","15","15","כי כה אמר יהוה אלהי ישראל אלי קח את כוס היין החמה הזאת מידי והשקיתה אתו את כל הגוים אשר אנכי שלח אותך אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_16","025_25_16","JER","25","16","16","ושתו והתגעשו והתהללו מפני החרב אשר אנכי שלח בינתם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_17","025_25_17","JER","25","17","17","ואקח את הכוס מיד יהוה ואשקה את כל הגוים אשר שלחני יהוה אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_18","025_25_18","JER","25","18","18","את ירושלם ואת ערי יהודה ואת מלכיה את שריה לתת אתם לחרבה לשמה לשרקה ולקללה כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR25_19","025_25_19","JER","25","19","19","את פרעה מלך מצרים ואת עבדיו ואת שריו ואת כל עמו׃ ");
INSERT INTO heb_vpl VALUES ("JR25_20","025_25_20","JER","25","20","20","ואת כל הערב ואת כל מלכי ארץ העוץ ואת כל מלכי ארץ פלשתים ואת אשקלון ואת עזה ואת עקרון ואת שארית אשדוד׃ ");
INSERT INTO heb_vpl VALUES ("JR25_21","025_25_21","JER","25","21","21","את אדום ואת מואב ואת בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JR25_22","025_25_22","JER","25","22","22","ואת כל מלכי צר ואת כל מלכי צידון ואת מלכי האי אשר בעבר הים׃ ");
INSERT INTO heb_vpl VALUES ("JR25_23","025_25_23","JER","25","23","23","ואת דדן ואת תימא ואת בוז ואת כל קצוצי פאה׃ ");
INSERT INTO heb_vpl VALUES ("JR25_24","025_25_24","JER","25","24","24","ואת כל מלכי ערב ואת כל מלכי הערב השכנים במדבר׃ ");
INSERT INTO heb_vpl VALUES ("JR25_25","025_25_25","JER","25","25","25","ואת כל מלכי זמרי ואת כל מלכי עילם ואת כל מלכי מדי׃ ");
INSERT INTO heb_vpl VALUES ("JR25_26","025_25_26","JER","25","26","26","ואת כל מלכי הצפון הקרבים והרחקים איש אל אחיו ואת כל הממלכות הארץ אשר על פני האדמה ומלך ששך ישתה אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_27","025_25_27","JER","25","27","27","ואמרת אליהם כה אמר יהוה צבאות אלהי ישראל שתו ושכרו וקיו ונפלו ולא תקומו מפני החרב אשר אנכי שלח ביניכם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_28","025_25_28","JER","25","28","28","והיה כי ימאנו לקחת הכוס מידך לשתות ואמרת אליהם כה אמר יהוה צבאות שתו תשתו׃ ");
INSERT INTO heb_vpl VALUES ("JR25_29","025_25_29","JER","25","29","29","כי הנה בעיר אשר נקרא שמי עליה אנכי מחל להרע ואתם הנקה תנקו לא תנקו כי חרב אני קרא על כל ישבי הארץ נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("JR25_30","025_25_30","JER","25","30","30","ואתה תנבא אליהם את כל הדברים האלה ואמרת אליהם יהוה ממרום ישאג וממעון קדשו יתן קולו שאג ישאג על נוהו הידד כדרכים יענה אל כל ישבי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR25_31","025_25_31","JER","25","31","31","בא שאון עד קצה הארץ כי ריב ליהוה בגוים נשפט הוא לכל בשר הרשעים נתנם לחרב נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR25_32","025_25_32","JER","25","32","32","כה אמר יהוה צבאות הנה רעה יצאת מגוי אל גוי וסער גדול יעור מירכתי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR25_33","025_25_33","JER","25","33","33","והיו חללי יהוה ביום ההוא מקצה הארץ ועד קצה הארץ לא יספדו ולא יאספו ולא יקברו לדמן על פני האדמה יהיו׃ ");
INSERT INTO heb_vpl VALUES ("JR25_34","025_25_34","JER","25","34","34","הילילו הרעים וזעקו והתפלשו אדירי הצאן כי מלאו ימיכם לטבוח ותפוצותיכם ונפלתם ככלי חמדה׃ ");
INSERT INTO heb_vpl VALUES ("JR25_35","025_25_35","JER","25","35","35","ואבד מנוס מן הרעים ופליטה מאדירי הצאן׃ ");
INSERT INTO heb_vpl VALUES ("JR25_36","025_25_36","JER","25","36","36","קול צעקת הרעים ויללת אדירי הצאן כי שדד יהוה את מרעיתם׃ ");
INSERT INTO heb_vpl VALUES ("JR25_37","025_25_37","JER","25","37","37","ונדמו נאות השלום מפני חרון אף יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR25_38","025_25_38","JER","25","38","38","עזב ככפיר סכו כי היתה ארצם לשמה מפני חרון היונה ומפני חרון אפו׃ ");
INSERT INTO heb_vpl VALUES ("JR26_1","025_26_1","JER","26","1","1","בראשית ממלכות יהויקים בן יאשיהו מלך יהודה היה הדבר הזה מאת יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR26_2","025_26_2","JER","26","2","2","כה אמר יהוה עמד בחצר בית יהוה ודברת על כל ערי יהודה הבאים להשתחות בית יהוה את כל הדברים אשר צויתיך לדבר אליהם אל תגרע דבר׃ ");
INSERT INTO heb_vpl VALUES ("JR26_3","025_26_3","JER","26","3","3","אולי ישמעו וישבו איש מדרכו הרעה ונחמתי אל הרעה אשר אנכי חשב לעשות להם מפני רע מעלליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR26_4","025_26_4","JER","26","4","4","ואמרת אליהם כה אמר יהוה אם לא תשמעו אלי ללכת בתורתי אשר נתתי לפניכם׃ ");
INSERT INTO heb_vpl VALUES ("JR26_5","025_26_5","JER","26","5","5","לשמע על דברי עבדי הנבאים אשר אנכי שלח אליכם והשכם ושלח ולא שמעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR26_6","025_26_6","JER","26","6","6","ונתתי את הבית הזה כשלה ואת העיר הזאתה אתן לקללה לכל גויי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR26_7","025_26_7","JER","26","7","7","וישמעו הכהנים והנבאים וכל העם את ירמיהו מדבר את הדברים האלה בבית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR26_8","025_26_8","JER","26","8","8","ויהי ככלות ירמיהו לדבר את כל אשר צוה יהוה לדבר אל כל העם ויתפשו אתו הכהנים והנבאים וכל העם לאמר מות תמות׃ ");
INSERT INTO heb_vpl VALUES ("JR26_9","025_26_9","JER","26","9","9","מדוע נבית בשם יהוה לאמר כשלו יהיה הבית הזה והעיר הזאת תחרב מאין יושב ויקהל כל העם אל ירמיהו בבית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR26_10","025_26_10","JER","26","10","10","וישמעו שרי יהודה את הדברים האלה ויעלו מבית המלך בית יהוה וישבו בפתח שער יהוה החדש׃ ");
INSERT INTO heb_vpl VALUES ("JR26_11","025_26_11","JER","26","11","11","ויאמרו הכהנים והנבאים אל השרים ואל כל העם לאמר משפט מות לאיש הזה כי נבא אל העיר הזאת כאשר שמעתם באזניכם׃ ");
INSERT INTO heb_vpl VALUES ("JR26_12","025_26_12","JER","26","12","12","ויאמר ירמיהו אל כל השרים ואל כל העם לאמר יהוה שלחני להנבא אל הבית הזה ואל העיר הזאת את כל הדברים אשר שמעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR26_13","025_26_13","JER","26","13","13","ועתה היטיבו דרכיכם ומעלליכם ושמעו בקול יהוה אלהיכם וינחם יהוה אל הרעה אשר דבר עליכם׃ ");
INSERT INTO heb_vpl VALUES ("JR26_14","025_26_14","JER","26","14","14","ואני הנני בידכם עשו לי כטוב וכישר בעיניכם׃ ");
INSERT INTO heb_vpl VALUES ("JR26_15","025_26_15","JER","26","15","15","אך ידע תדעו כי אם ממתים אתם אתי כי דם נקי אתם נתנים עליכם ואל העיר הזאת ואל ישביה כי באמת שלחני יהוה עליכם לדבר באזניכם את כל הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR26_16","025_26_16","JER","26","16","16","ויאמרו השרים וכל העם אל הכהנים ואל הנביאים אין לאיש הזה משפט מות כי בשם יהוה אלהינו דבר אלינו׃ ");
INSERT INTO heb_vpl VALUES ("JR26_17","025_26_17","JER","26","17","17","ויקמו אנשים מזקני הארץ ויאמרו אל כל קהל העם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR26_18","025_26_18","JER","26","18","18","מיכיה המורשתי היה נבא בימי חזקיהו מלך יהודה ויאמר אל כל עם יהודה לאמר כה אמר יהוה צבאות ציון שדה תחרש וירושלים עיים תהיה והר הבית לבמות יער׃ ");
INSERT INTO heb_vpl VALUES ("JR26_19","025_26_19","JER","26","19","19","ההמת המתהו חזקיהו מלך יהודה וכל יהודה הלא ירא את יהוה ויחל את פני יהוה וינחם יהוה אל הרעה אשר דבר עליהם ואנחנו עשים רעה גדולה על נפשותינו׃ ");
INSERT INTO heb_vpl VALUES ("JR26_20","025_26_20","JER","26","20","20","וגם איש היה מתנבא בשם יהוה אוריהו בן שמעיהו מקרית היערים וינבא על העיר הזאת ועל הארץ הזאת ככל דברי ירמיהו׃ ");
INSERT INTO heb_vpl VALUES ("JR26_21","025_26_21","JER","26","21","21","וישמע המלך יהויקים וכל גבוריו וכל השרים את דבריו ויבקש המלך המיתו וישמע אוריהו וירא ויברח ויבא מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR26_22","025_26_22","JER","26","22","22","וישלח המלך יהויקים אנשים מצרים את אלנתן בן עכבור ואנשים אתו אל מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR26_23","025_26_23","JER","26","23","23","ויוציאו את אוריהו ממצרים ויבאהו אל המלך יהויקים ויכהו בחרב וישלך את נבלתו אל קברי בני העם׃ ");
INSERT INTO heb_vpl VALUES ("JR26_24","025_26_24","JER","26","24","24","אך יד אחיקם בן שפן היתה את ירמיהו לבלתי תת אתו ביד העם להמיתו׃ ");
INSERT INTO heb_vpl VALUES ("JR27_1","025_27_1","JER","27","1","1","בראשית ממלכת יהויקם בן יאושיהו מלך יהודה היה הדבר הזה אל ירמיה מאת יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR27_2","025_27_2","JER","27","2","2","כה אמר יהוה אלי עשה לך מוסרות ומטות ונתתם על צוארך׃ ");
INSERT INTO heb_vpl VALUES ("JR27_3","025_27_3","JER","27","3","3","ושלחתם אל מלך אדום ואל מלך מואב ואל מלך בני עמון ואל מלך צר ואל מלך צידון ביד מלאכים הבאים ירושלם אל צדקיהו מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR27_4","025_27_4","JER","27","4","4","וצוית אתם אל אדניהם לאמר כה אמר יהוה צבאות אלהי ישראל כה תאמרו אל אדניכם׃ ");
INSERT INTO heb_vpl VALUES ("JR27_5","025_27_5","JER","27","5","5","אנכי עשיתי את הארץ את האדם ואת הבהמה אשר על פני הארץ בכחי הגדול ובזרועי הנטויה ונתתיה לאשר ישר בעיני׃ ");
INSERT INTO heb_vpl VALUES ("JR27_6","025_27_6","JER","27","6","6","ועתה אנכי נתתי את כל הארצות האלה ביד נבוכדנאצר מלך בבל עבדי וגם את חית השדה נתתי לו לעבדו׃ ");
INSERT INTO heb_vpl VALUES ("JR27_7","025_27_7","JER","27","7","7","ועבדו אתו כל הגוים ואת בנו ואת בן בנו עד בא עת ארצו גם הוא ועבדו בו גוים רבים ומלכים גדלים׃ ");
INSERT INTO heb_vpl VALUES ("JR27_8","025_27_8","JER","27","8","8","והיה הגוי והממלכה אשר לא יעבדו אתו את נבוכדנאצר מלך בבל ואת אשר לא יתן את צוארו בעל מלך בבל בחרב וברעב ובדבר אפקד על הגוי ההוא נאם יהוה עד תמי אתם בידו׃ ");
INSERT INTO heb_vpl VALUES ("JR27_9","025_27_9","JER","27","9","9","ואתם אל תשמעו אל נביאיכם ואל קסמיכם ואל חלמתיכם ואל ענניכם ואל כשפיכם אשר הם אמרים אליכם לאמר לא תעבדו את מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR27_10","025_27_10","JER","27","10","10","כי שקר הם נבאים לכם למען הרחיק אתכם מעל אדמתכם והדחתי אתכם ואבדתם׃ ");
INSERT INTO heb_vpl VALUES ("JR27_11","025_27_11","JER","27","11","11","והגוי אשר יביא את צוארו בעל מלך בבל ועבדו והנחתיו על אדמתו נאם יהוה ועבדה וישב בה׃ ");
INSERT INTO heb_vpl VALUES ("JR27_12","025_27_12","JER","27","12","12","ואל צדקיה מלך יהודה דברתי ככל הדברים האלה לאמר הביאו את צואריכם בעל מלך בבל ועבדו אתו ועמו וחיו׃ ");
INSERT INTO heb_vpl VALUES ("JR27_13","025_27_13","JER","27","13","13","למה תמותו אתה ועמך בחרב ברעב ובדבר כאשר דבר יהוה אל הגוי אשר לא יעבד את מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR27_14","025_27_14","JER","27","14","14","ואל תשמעו אל דברי הנבאים האמרים אליכם לאמר לא תעבדו את מלך בבל כי שקר הם נבאים לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR27_15","025_27_15","JER","27","15","15","כי לא שלחתים נאם יהוה והם נבאים בשמי לשקר למען הדיחי אתכם ואבדתם אתם והנבאים הנבאים לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR27_16","025_27_16","JER","27","16","16","ואל הכהנים ואל כל העם הזה דברתי לאמר כה אמר יהוה אל תשמעו אל דברי נביאיכם הנבאים לכם לאמר הנה כלי בית יהוה מושבים מבבלה עתה מהרה כי שקר המה נבאים לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR27_17","025_27_17","JER","27","17","17","אל תשמעו אליהם עבדו את מלך בבל וחיו למה תהיה העיר הזאת חרבה׃ ");
INSERT INTO heb_vpl VALUES ("JR27_18","025_27_18","JER","27","18","18","ואם נבאים הם ואם יש דבר יהוה אתם יפגעו נא ביהוה צבאות לבלתי באו הכלים הנותרים בבית יהוה ובית מלך יהודה ובירושלם בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR27_19","025_27_19","JER","27","19","19","כי כה אמר יהוה צבאות אל העמדים ועל הים ועל המכנות ועל יתר הכלים הנותרים בעיר הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR27_20","025_27_20","JER","27","20","20","אשר לא לקחם נבוכדנאצר מלך בבל בגלותו את יכוניה בן יהויקים מלך יהודה מירושלם בבלה ואת כל חרי יהודה וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR27_21","025_27_21","JER","27","21","21","כי כה אמר יהוה צבאות אלהי ישראל על הכלים הנותרים בית יהוה ובית מלך יהודה וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR27_22","025_27_22","JER","27","22","22","בבלה יובאו ושמה יהיו עד יום פקדי אתם נאם יהוה והעליתים והשיבתים אל המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR28_1","025_28_1","JER","28","1","1","ויהי בשנה ההיא בראשית ממלכת צדקיה מלך יהודה בשנת הרבעית בחדש החמישי אמר אלי חנניה בן עזור הנביא אשר מגבעון בבית יהוה לעיני הכהנים וכל העם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR28_2","025_28_2","JER","28","2","2","כה אמר יהוה צבאות אלהי ישראל לאמר שברתי את על מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR28_3","025_28_3","JER","28","3","3","בעוד שנתים ימים אני משיב אל המקום הזה את כל כלי בית יהוה אשר לקח נבוכדנאצר מלך בבל מן המקום הזה ויביאם בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR28_4","025_28_4","JER","28","4","4","ואת יכניה בן יהויקים מלך יהודה ואת כל גלות יהודה הבאים בבלה אני משיב אל המקום הזה נאם יהוה כי אשבר את על מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR28_5","025_28_5","JER","28","5","5","ויאמר ירמיה הנביא אל חנניה הנביא לעיני הכהנים ולעיני כל העם העמדים בבית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR28_6","025_28_6","JER","28","6","6","ויאמר ירמיה הנביא אמן כן יעשה יהוה יקם יהוה את דבריך אשר נבאת להשיב כלי בית יהוה וכל הגולה מבבל אל המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR28_7","025_28_7","JER","28","7","7","אך שמע נא הדבר הזה אשר אנכי דבר באזניך ובאזני כל העם׃ ");
INSERT INTO heb_vpl VALUES ("JR28_8","025_28_8","JER","28","8","8","הנביאים אשר היו לפני ולפניך מן העולם וינבאו אל ארצות רבות ועל ממלכות גדלות למלחמה ולרעה ולדבר׃ ");
INSERT INTO heb_vpl VALUES ("JR28_9","025_28_9","JER","28","9","9","הנביא אשר ינבא לשלום בבא דבר הנביא יודע הנביא אשר שלחו יהוה באמת׃ ");
INSERT INTO heb_vpl VALUES ("JR28_10","025_28_10","JER","28","10","10","ויקח חנניה הנביא את המוטה מעל צואר ירמיה הנביא וישברהו׃ ");
INSERT INTO heb_vpl VALUES ("JR28_11","025_28_11","JER","28","11","11","ויאמר חנניה לעיני כל העם לאמר כה אמר יהוה ככה אשבר את על נבכדנאצר מלך בבל בעוד שנתים ימים מעל צואר כל הגוים וילך ירמיה הנביא לדרכו׃ ");
INSERT INTO heb_vpl VALUES ("JR28_12","025_28_12","JER","28","12","12","ויהי דבר יהוה אל ירמיה אחרי שבור חנניה הנביא את המוטה מעל צואר ירמיה הנביא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR28_13","025_28_13","JER","28","13","13","הלוך ואמרת אל חנניה לאמר כה אמר יהוה מוטת עץ שברת ועשית תחתיהן מטות ברזל׃ ");
INSERT INTO heb_vpl VALUES ("JR28_14","025_28_14","JER","28","14","14","כי כה אמר יהוה צבאות אלהי ישראל על ברזל נתתי על צואר כל הגוים האלה לעבד את נבכדנאצר מלך בבל ועבדהו וגם את חית השדה נתתי לו׃ ");
INSERT INTO heb_vpl VALUES ("JR28_15","025_28_15","JER","28","15","15","ויאמר ירמיה הנביא אל חנניה הנביא שמע נא חנניה לא שלחך יהוה ואתה הבטחת את העם הזה על שקר׃ ");
INSERT INTO heb_vpl VALUES ("JR28_16","025_28_16","JER","28","16","16","לכן כה אמר יהוה הנני משלחך מעל פני האדמה השנה אתה מת כי סרה דברת אל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR28_17","025_28_17","JER","28","17","17","וימת חנניה הנביא בשנה ההיא בחדש השביעי׃ ");
INSERT INTO heb_vpl VALUES ("JR29_1","025_29_1","JER","29","1","1","ואלה דברי הספר אשר שלח ירמיה הנביא מירושלם אל יתר זקני הגולה ואל הכהנים ואל הנביאים ואל כל העם אשר הגלה נבוכדנאצר מירושלם בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_2","025_29_2","JER","29","2","2","אחרי צאת יכניה המלך והגבירה והסריסים שרי יהודה וירושלם והחרש והמסגר מירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR29_3","025_29_3","JER","29","3","3","ביד אלעשה בן שפן וגמריה בן חלקיה אשר שלח צדקיה מלך יהודה אל נבוכדנאצר מלך בבל בבלה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR29_4","025_29_4","JER","29","4","4","כה אמר יהוה צבאות אלהי ישראל לכל הגולה אשר הגליתי מירושלם בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_5","025_29_5","JER","29","5","5","בנו בתים ושבו ונטעו גנות ואכלו את פרין׃ ");
INSERT INTO heb_vpl VALUES ("JR29_6","025_29_6","JER","29","6","6","קחו נשים והולידו בנים ובנות וקחו לבניכם נשים ואת בנותיכם תנו לאנשים ותלדנה בנים ובנות ורבו שם ואל תמעטו׃ ");
INSERT INTO heb_vpl VALUES ("JR29_7","025_29_7","JER","29","7","7","ודרשו את שלום העיר אשר הגליתי אתכם שמה והתפללו בעדה אל יהוה כי בשלומה יהיה לכם שלום׃ ");
INSERT INTO heb_vpl VALUES ("JR29_8","025_29_8","JER","29","8","8","כי כה אמר יהוה צבאות אלהי ישראל אל ישיאו לכם נביאיכם אשר בקרבכם וקסמיכם ואל תשמעו אל חלמתיכם אשר אתם מחלמים׃ ");
INSERT INTO heb_vpl VALUES ("JR29_9","025_29_9","JER","29","9","9","כי בשקר הם נבאים לכם בשמי לא שלחתים נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_10","025_29_10","JER","29","10","10","כי כה אמר יהוה כי לפי מלאת לבבל שבעים שנה אפקד אתכם והקמתי עליכם את דברי הטוב להשיב אתכם אל המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_11","025_29_11","JER","29","11","11","כי אנכי ידעתי את המחשבת אשר אנכי חשב עליכם נאם יהוה מחשבות שלום ולא לרעה לתת לכם אחרית ותקוה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_12","025_29_12","JER","29","12","12","וקראתם אתי והלכתם והתפללתם אלי ושמעתי אליכם׃ ");
INSERT INTO heb_vpl VALUES ("JR29_13","025_29_13","JER","29","13","13","ובקשתם אתי ומצאתם כי תדרשני בכל לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("JR29_14","025_29_14","JER","29","14","14","ונמצאתי לכם נאם יהוה ושבתי את שביתכם וקבצתי אתכם מכל הגוים ומכל המקומות אשר הדחתי אתכם שם נאם יהוה והשבתי אתכם אל המקום אשר הגליתי אתכם משם׃ ");
INSERT INTO heb_vpl VALUES ("JR29_15","025_29_15","JER","29","15","15","כי אמרתם הקים לנו יהוה נבאים בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_16","025_29_16","JER","29","16","16","כי כה אמר יהוה אל המלך היושב אל כסא דוד ואל כל העם היושב בעיר הזאת אחיכם אשר לא יצאו אתכם בגולה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_17","025_29_17","JER","29","17","17","כה אמר יהוה צבאות הנני משלח בם את החרב את הרעב ואת הדבר ונתתי אותם כתאנים השערים אשר לא תאכלנה מרע׃ ");
INSERT INTO heb_vpl VALUES ("JR29_18","025_29_18","JER","29","18","18","ורדפתי אחריהם בחרב ברעב ובדבר ונתתים לזועה לכל ממלכות הארץ לאלה ולשמה ולשרקה ולחרפה בכל הגוים אשר הדחתים שם׃ ");
INSERT INTO heb_vpl VALUES ("JR29_19","025_29_19","JER","29","19","19","תחת אשר לא שמעו אל דברי נאם יהוה אשר שלחתי אליהם את עבדי הנבאים השכם ושלח ולא שמעתם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_20","025_29_20","JER","29","20","20","ואתם שמעו דבר יהוה כל הגולה אשר שלחתי מירושלם בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_21","025_29_21","JER","29","21","21","כה אמר יהוה צבאות אלהי ישראל אל אחאב בן קוליה ואל צדקיהו בן מעשיה הנבאים לכם בשמי שקר הנני נתן אתם ביד נבוכדראצר מלך בבל והכם לעיניכם׃ ");
INSERT INTO heb_vpl VALUES ("JR29_22","025_29_22","JER","29","22","22","ולקח מהם קללה לכל גלות יהודה אשר בבבל לאמר ישמך יהוה כצדקיהו וכאחב אשר קלם מלך בבל באש׃ ");
INSERT INTO heb_vpl VALUES ("JR29_23","025_29_23","JER","29","23","23","יען אשר עשו נבלה בישראל וינאפו את נשי רעיהם וידברו דבר בשמי שקר אשר לוא צויתם ואנכי הוידע ועד נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR29_24","025_29_24","JER","29","24","24","ואל שמעיהו הנחלמי תאמר לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR29_25","025_29_25","JER","29","25","25","כה אמר יהוה צבאות אלהי ישראל לאמר יען אשר אתה שלחת בשמכה ספרים אל כל העם אשר בירושלם ואל צפניה בן מעשיה הכהן ואל כל הכהנים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR29_26","025_29_26","JER","29","26","26","יהוה נתנך כהן תחת יהוידע הכהן להיות פקדים בית יהוה לכל איש משגע ומתנבא ונתתה אתו אל המהפכת ואל הצינק׃ ");
INSERT INTO heb_vpl VALUES ("JR29_27","025_29_27","JER","29","27","27","ועתה למה לא גערת בירמיהו הענתתי המתנבא לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR29_28","025_29_28","JER","29","28","28","כי על כן שלח אלינו בבל לאמר ארכה היא בנו בתים ושבו ונטעו גנות ואכלו את פריהן׃ ");
INSERT INTO heb_vpl VALUES ("JR29_29","025_29_29","JER","29","29","29","ויקרא צפניה הכהן את הספר הזה באזני ירמיהו הנביא׃ ");
INSERT INTO heb_vpl VALUES ("JR29_30","025_29_30","JER","29","30","30","ויהי דבר יהוה אל ירמיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR29_31","025_29_31","JER","29","31","31","שלח על כל הגולה לאמר כה אמר יהוה אל שמעיה הנחלמי יען אשר נבא לכם שמעיה ואני לא שלחתיו ויבטח אתכם על שקר׃ ");
INSERT INTO heb_vpl VALUES ("JR29_32","025_29_32","JER","29","32","32","לכן כה אמר יהוה הנני פקד על שמעיה הנחלמי ועל זרעו לא יהיה לו איש יושב בתוך העם הזה ולא יראה בטוב אשר אני עשה לעמי נאם יהוה כי סרה דבר על יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR30_1","025_30_1","JER","30","1","1","הדבר אשר היה אל ירמיהו מאת יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR30_2","025_30_2","JER","30","2","2","כה אמר יהוה אלהי ישראל לאמר כתב לך את כל הדברים אשר דברתי אליך אל ספר׃ ");
INSERT INTO heb_vpl VALUES ("JR30_3","025_30_3","JER","30","3","3","כי הנה ימים באים נאם יהוה ושבתי את שבות עמי ישראל ויהודה אמר יהוה והשבתים אל הארץ אשר נתתי לאבותם וירשוה׃ ");
INSERT INTO heb_vpl VALUES ("JR30_4","025_30_4","JER","30","4","4","ואלה הדברים אשר דבר יהוה אל ישראל ואל יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR30_5","025_30_5","JER","30","5","5","כי כה אמר יהוה קול חרדה שמענו פחד ואין שלום׃ ");
INSERT INTO heb_vpl VALUES ("JR30_6","025_30_6","JER","30","6","6","שאלו נא וראו אם ילד זכר מדוע ראיתי כל גבר ידיו על חלציו כיולדה ונהפכו כל פנים לירקון׃ ");
INSERT INTO heb_vpl VALUES ("JR30_7","025_30_7","JER","30","7","7","הוי כי גדול היום ההוא מאין כמהו ועת צרה היא ליעקב וממנה יושע׃ ");
INSERT INTO heb_vpl VALUES ("JR30_8","025_30_8","JER","30","8","8","והיה ביום ההוא נאם יהוה צבאות אשבר עלו מעל צוארך ומוסרותיך אנתק ולא יעבדו בו עוד זרים׃ ");
INSERT INTO heb_vpl VALUES ("JR30_9","025_30_9","JER","30","9","9","ועבדו את יהוה אלהיהם ואת דוד מלכם אשר אקים להם׃ ");
INSERT INTO heb_vpl VALUES ("JR30_10","025_30_10","JER","30","10","10","ואתה אל תירא עבדי יעקב נאם יהוה ואל תחת ישראל כי הנני מושיעך מרחוק ואת זרעך מארץ שבים ושב יעקב ושקט ושאנן ואין מחריד׃ ");
INSERT INTO heb_vpl VALUES ("JR30_11","025_30_11","JER","30","11","11","כי אתך אני נאם יהוה להושיעך כי אעשה כלה בכל הגוים אשר הפצותיך שם אך אתך לא אעשה כלה ויסרתיך למשפט ונקה לא אנקך׃ ");
INSERT INTO heb_vpl VALUES ("JR30_12","025_30_12","JER","30","12","12","כי כה אמר יהוה אנוש לשברך נחלה מכתך׃ ");
INSERT INTO heb_vpl VALUES ("JR30_13","025_30_13","JER","30","13","13","אין דן דינך למזור רפאות תעלה אין לך׃ ");
INSERT INTO heb_vpl VALUES ("JR30_14","025_30_14","JER","30","14","14","כל מאהביך שכחוך אותך לא ידרשו כי מכת אויב הכיתיך מוסר אכזרי על רב עונך עצמו חטאתיך׃ ");
INSERT INTO heb_vpl VALUES ("JR30_15","025_30_15","JER","30","15","15","מה תזעק על שברך אנוש מכאבך על רב עונך עצמו חטאתיך עשיתי אלה לך׃ ");
INSERT INTO heb_vpl VALUES ("JR30_16","025_30_16","JER","30","16","16","לכן כל אכליך יאכלו וכל צריך כלם בשבי ילכו והיו שאסיך למשסה וכל בזזיך אתן לבז׃ ");
INSERT INTO heb_vpl VALUES ("JR30_17","025_30_17","JER","30","17","17","כי אעלה ארכה לך וממכותיך ארפאך נאם יהוה כי נדחה קראו לך ציון היא דרש אין לה׃ ");
INSERT INTO heb_vpl VALUES ("JR30_18","025_30_18","JER","30","18","18","כה אמר יהוה הנני שב שבות אהלי יעקוב ומשכנתיו ארחם ונבנתה עיר על תלה וארמון על משפטו ישב׃ ");
INSERT INTO heb_vpl VALUES ("JR30_19","025_30_19","JER","30","19","19","ויצא מהם תודה וקול משחקים והרבתים ולא ימעטו והכבדתים ולא יצערו׃ ");
INSERT INTO heb_vpl VALUES ("JR30_20","025_30_20","JER","30","20","20","והיו בניו כקדם ועדתו לפני תכון ופקדתי על כל לחציו׃ ");
INSERT INTO heb_vpl VALUES ("JR30_21","025_30_21","JER","30","21","21","והיה אדירו ממנו ומשלו מקרבו יצא והקרבתיו ונגש אלי כי מי הוא זה ערב את לבו לגשת אלי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR30_22","025_30_22","JER","30","22","22","והייתם לי לעם ואנכי אהיה לכם לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JR30_23","025_30_23","JER","30","23","23","הנה סערת יהוה חמה יצאה סער מתגורר על ראש רשעים יחול׃ ");
INSERT INTO heb_vpl VALUES ("JR30_24","025_30_24","JER","30","24","24","לא ישוב חרון אף יהוה עד עשתו ועד הקימו מזמות לבו באחרית הימים תתבוננו בה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_1","025_31_1","JER","31","1","1","בעת ההיא נאם יהוה אהיה לאלהים לכל משפחות ישראל והמה יהיו לי לעם׃ ");
INSERT INTO heb_vpl VALUES ("JR31_2","025_31_2","JER","31","2","2","כה אמר יהוה מצא חן במדבר עם שרידי חרב הלוך להרגיעו ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR31_3","025_31_3","JER","31","3","3","מרחוק יהוה נראה לי ואהבת עולם אהבתיך על כן משכתיך חסד׃ ");
INSERT INTO heb_vpl VALUES ("JR31_4","025_31_4","JER","31","4","4","עוד אבנך ונבנית בתולת ישראל עוד תעדי תפיך ויצאת במחול משחקים׃ ");
INSERT INTO heb_vpl VALUES ("JR31_5","025_31_5","JER","31","5","5","עוד תטעי כרמים בהרי שמרון נטעו נטעים וחללו׃ ");
INSERT INTO heb_vpl VALUES ("JR31_6","025_31_6","JER","31","6","6","כי יש יום קראו נצרים בהר אפרים קומו ונעלה ציון אל יהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JR31_7","025_31_7","JER","31","7","7","כי כה אמר יהוה רנו ליעקב שמחה וצהלו בראש הגוים השמיעו הללו ואמרו הושע יהוה את עמך את שארית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR31_8","025_31_8","JER","31","8","8","הנני מביא אותם מארץ צפון וקבצתים מירכתי ארץ בם עור ופסח הרה וילדת יחדו קהל גדול ישובו הנה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_9","025_31_9","JER","31","9","9","בבכי יבאו ובתחנונים אובילם אוליכם אל נחלי מים בדרך ישר לא יכשלו בה כי הייתי לישראל לאב ואפרים בכרי הוא׃ ");
INSERT INTO heb_vpl VALUES ("JR31_10","025_31_10","JER","31","10","10","שמעו דבר יהוה גוים והגידו באיים ממרחק ואמרו מזרה ישראל יקבצנו ושמרו כרעה עדרו׃ ");
INSERT INTO heb_vpl VALUES ("JR31_11","025_31_11","JER","31","11","11","כי פדה יהוה את יעקב וגאלו מיד חזק ממנו׃ ");
INSERT INTO heb_vpl VALUES ("JR31_12","025_31_12","JER","31","12","12","ובאו ורננו במרום ציון ונהרו אל טוב יהוה על דגן ועל תירש ועל יצהר ועל בני צאן ובקר והיתה נפשם כגן רוה ולא יוסיפו לדאבה עוד׃ ");
INSERT INTO heb_vpl VALUES ("JR31_13","025_31_13","JER","31","13","13","אז תשמח בתולה במחול ובחרים וזקנים יחדו והפכתי אבלם לששון ונחמתים ושמחתים מיגונם׃ ");
INSERT INTO heb_vpl VALUES ("JR31_14","025_31_14","JER","31","14","14","ורויתי נפש הכהנים דשן ועמי את טובי ישבעו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_15","025_31_15","JER","31","15","15","כה אמר יהוה קול ברמה נשמע נהי בכי תמרורים רחל מבכה על בניה מאנה להנחם על בניה כי איננו׃ ");
INSERT INTO heb_vpl VALUES ("JR31_16","025_31_16","JER","31","16","16","כה אמר יהוה מנעי קולך מבכי ועיניך מדמעה כי יש שכר לפעלתך נאם יהוה ושבו מארץ אויב׃ ");
INSERT INTO heb_vpl VALUES ("JR31_17","025_31_17","JER","31","17","17","ויש תקוה לאחריתך נאם יהוה ושבו בנים לגבולם׃ ");
INSERT INTO heb_vpl VALUES ("JR31_18","025_31_18","JER","31","18","18","שמוע שמעתי אפרים מתנודד יסרתני ואוסר כעגל לא למד השבני ואשובה כי אתה יהוה אלהי׃ ");
INSERT INTO heb_vpl VALUES ("JR31_19","025_31_19","JER","31","19","19","כי אחרי שובי נחמתי ואחרי הודעי ספקתי על ירך בשתי וגם נכלמתי כי נשאתי חרפת נעורי׃ ");
INSERT INTO heb_vpl VALUES ("JR31_20","025_31_20","JER","31","20","20","הבן יקיר לי אפרים אם ילד שעשועים כי מדי דברי בו זכר אזכרנו עוד על כן המו מעי לו רחם ארחמנו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_21","025_31_21","JER","31","21","21","הציבי לך צינים שמי לך תמרורים שתי לבך למסלה דרך הלכתי שובי בתולת ישראל שבי אל עריך אלה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_22","025_31_22","JER","31","22","22","עד מתי תתחמקין הבת השובבה כי ברא יהוה חדשה בארץ נקבה תסובב גבר׃ ");
INSERT INTO heb_vpl VALUES ("JR31_23","025_31_23","JER","31","23","23","כה אמר יהוה צבאות אלהי ישראל עוד יאמרו את הדבר הזה בארץ יהודה ובעריו בשובי את שבותם יברכך יהוה נוה צדק הר הקדש׃ ");
INSERT INTO heb_vpl VALUES ("JR31_24","025_31_24","JER","31","24","24","וישבו בה יהודה וכל עריו יחדו אכרים ונסעו בעדר׃ ");
INSERT INTO heb_vpl VALUES ("JR31_25","025_31_25","JER","31","25","25","כי הרויתי נפש עיפה וכל נפש דאבה מלאתי׃ ");
INSERT INTO heb_vpl VALUES ("JR31_26","025_31_26","JER","31","26","26","על זאת הקיצתי ואראה ושנתי ערבה לי׃ ");
INSERT INTO heb_vpl VALUES ("JR31_27","025_31_27","JER","31","27","27","הנה ימים באים נאם יהוה וזרעתי את בית ישראל ואת בית יהודה זרע אדם וזרע בהמה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_28","025_31_28","JER","31","28","28","והיה כאשר שקדתי עליהם לנתוש ולנתוץ ולהרס ולהאביד ולהרע כן אשקד עליהם לבנות ולנטוע נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_29","025_31_29","JER","31","29","29","בימים ההם לא יאמרו עוד אבות אכלו בסר ושני בנים תקהינה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_30","025_31_30","JER","31","30","30","כי אם איש בעונו ימות כל האדם האכל הבסר תקהינה שניו׃ ");
INSERT INTO heb_vpl VALUES ("JR31_31","025_31_31","JER","31","31","31","הנה ימים באים נאם יהוה וכרתי את בית ישראל ואת בית יהודה ברית חדשה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_32","025_31_32","JER","31","32","32","לא כברית אשר כרתי את אבותם ביום החזיקי בידם להוציאם מארץ מצרים אשר המה הפרו את בריתי ואנכי בעלתי בם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_33","025_31_33","JER","31","33","33","כי זאת הברית אשר אכרת את בית ישראל אחרי הימים ההם נאם יהוה נתתי את תורתי בקרבם ועל לבם אכתבנה והייתי להם לאלהים והמה יהיו לי לעם׃ ");
INSERT INTO heb_vpl VALUES ("JR31_34","025_31_34","JER","31","34","34","ולא ילמדו עוד איש את רעהו ואיש את אחיו לאמר דעו את יהוה כי כולם ידעו אותי למקטנם ועד גדולם נאם יהוה כי אסלח לעונם ולחטאתם לא אזכר עוד׃ ");
INSERT INTO heb_vpl VALUES ("JR31_35","025_31_35","JER","31","35","35","כה אמר יהוה נתן שמש לאור יומם חקת ירח וכוכבים לאור לילה רגע הים ויהמו גליו יהוה צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("JR31_36","025_31_36","JER","31","36","36","אם ימשו החקים האלה מלפני נאם יהוה גם זרע ישראל ישבתו מהיות גוי לפני כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("JR31_37","025_31_37","JER","31","37","37","כה אמר יהוה אם ימדו שמים מלמעלה ויחקרו מוסדי ארץ למטה גם אני אמאס בכל זרע ישראל על כל אשר עשו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_38","025_31_38","JER","31","38","38","הנה ימים נאם יהוה ונבנתה העיר ליהוה ממגדל חננאל שער הפנה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_39","025_31_39","JER","31","39","39","ויצא עוד קוה המדה נגדו על גבעת גרב ונסב געתה׃ ");
INSERT INTO heb_vpl VALUES ("JR31_40","025_31_40","JER","31","40","40","וכל העמק הפגרים והדשן וכל השרמות עד נחל קדרון עד פנת שער הסוסים מזרחה קדש ליהוה לא ינתש ולא יהרס עוד לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JR32_1","025_32_1","JER","32","1","1","הדבר אשר היה אל ירמיהו מאת יהוה בשנת העשרית לצדקיהו מלך יהודה היא השנה שמנה עשרה שנה לנבוכדראצר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_2","025_32_2","JER","32","2","2","ואז חיל מלך בבל צרים על ירושלם וירמיהו הנביא היה כלוא בחצר המטרה אשר בית מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_3","025_32_3","JER","32","3","3","אשר כלאו צדקיהו מלך יהודה לאמר מדוע אתה נבא לאמר כה אמר יהוה הנני נתן את העיר הזאת ביד מלך בבל ולכדה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_4","025_32_4","JER","32","4","4","וצדקיהו מלך יהודה לא ימלט מיד הכשדים כי הנתן ינתן ביד מלך בבל ודבר פיו עם פיו ועיניו את עינו תראינה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_5","025_32_5","JER","32","5","5","ובבל יולך את צדקיהו ושם יהיה עד פקדי אתו נאם יהוה כי תלחמו את הכשדים לא תצליחו׃ ");
INSERT INTO heb_vpl VALUES ("JR32_6","025_32_6","JER","32","6","6","ויאמר ירמיהו היה דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_7","025_32_7","JER","32","7","7","הנה חנמאל בן שלם דדך בא אליך לאמר קנה לך את שדי אשר בענתות כי לך משפט הגאלה לקנות׃ ");
INSERT INTO heb_vpl VALUES ("JR32_8","025_32_8","JER","32","8","8","ויבא אלי חנמאל בן דדי כדבר יהוה אל חצר המטרה ויאמר אלי קנה נא את שדי אשר בענתות אשר בארץ בנימין כי לך משפט הירשה ולך הגאלה קנה לך ואדע כי דבר יהוה הוא׃ ");
INSERT INTO heb_vpl VALUES ("JR32_9","025_32_9","JER","32","9","9","ואקנה את השדה מאת חנמאל בן דדי אשר בענתות ואשקלה לו את הכסף שבעה שקלים ועשרה הכסף׃ ");
INSERT INTO heb_vpl VALUES ("JR32_10","025_32_10","JER","32","10","10","ואכתב בספר ואחתם ואעד עדים ואשקל הכסף במאזנים׃ ");
INSERT INTO heb_vpl VALUES ("JR32_11","025_32_11","JER","32","11","11","ואקח את ספר המקנה את החתום המצוה והחקים ואת הגלוי׃ ");
INSERT INTO heb_vpl VALUES ("JR32_12","025_32_12","JER","32","12","12","ואתן את הספר המקנה אל ברוך בן נריה בן מחסיה לעיני חנמאל דדי ולעיני העדים הכתבים בספר המקנה לעיני כל היהודים הישבים בחצר המטרה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_13","025_32_13","JER","32","13","13","ואצוה את ברוך לעיניהם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_14","025_32_14","JER","32","14","14","כה אמר יהוה צבאות אלהי ישראל לקוח את הספרים האלה את ספר המקנה הזה ואת החתום ואת ספר הגלוי הזה ונתתם בכלי חרש למען יעמדו ימים רבים׃ ");
INSERT INTO heb_vpl VALUES ("JR32_15","025_32_15","JER","32","15","15","כי כה אמר יהוה צבאות אלהי ישראל עוד יקנו בתים ושדות וכרמים בארץ הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR32_16","025_32_16","JER","32","16","16","ואתפלל אל יהוה אחרי תתי את ספר המקנה אל ברוך בן נריה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_17","025_32_17","JER","32","17","17","אהה אדני יהוה הנה אתה עשית את השמים ואת הארץ בכחך הגדול ובזרעך הנטויה לא יפלא ממך כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_18","025_32_18","JER","32","18","18","עשה חסד לאלפים ומשלם עון אבות אל חיק בניהם אחריהם האל הגדול הגבור יהוה צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("JR32_19","025_32_19","JER","32","19","19","גדל העצה ורב העליליה אשר עיניך פקחות על כל דרכי בני אדם לתת לאיש כדרכיו וכפרי מעלליו׃ ");
INSERT INTO heb_vpl VALUES ("JR32_20","025_32_20","JER","32","20","20","אשר שמת אתות ומפתים בארץ מצרים עד היום הזה ובישראל ובאדם ותעשה לך שם כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_21","025_32_21","JER","32","21","21","ותצא את עמך את ישראל מארץ מצרים באתות ובמופתים וביד חזקה ובאזרוע נטויה ובמורא גדול׃ ");
INSERT INTO heb_vpl VALUES ("JR32_22","025_32_22","JER","32","22","22","ותתן להם את הארץ הזאת אשר נשבעת לאבותם לתת להם ארץ זבת חלב ודבש׃ ");
INSERT INTO heb_vpl VALUES ("JR32_23","025_32_23","JER","32","23","23","ויבאו וירשו אתה ולא שמעו בקולך ובתרותך לא הלכו את כל אשר צויתה להם לעשות לא עשו ותקרא אתם את כל הרעה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR32_24","025_32_24","JER","32","24","24","הנה הסללות באו העיר ללכדה והעיר נתנה ביד הכשדים הנלחמים עליה מפני החרב והרעב והדבר ואשר דברת היה והנך ראה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_25","025_32_25","JER","32","25","25","ואתה אמרת אלי אדני יהוה קנה לך השדה בכסף והעד עדים והעיר נתנה ביד הכשדים׃ ");
INSERT INTO heb_vpl VALUES ("JR32_26","025_32_26","JER","32","26","26","ויהי דבר יהוה אל ירמיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_27","025_32_27","JER","32","27","27","הנה אני יהוה אלהי כל בשר הממני יפלא כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_28","025_32_28","JER","32","28","28","לכן כה אמר יהוה הנני נתן את העיר הזאת ביד הכשדים וביד נבוכדראצר מלך בבל ולכדה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_29","025_32_29","JER","32","29","29","ובאו הכשדים הנלחמים על העיר הזאת והציתו את העיר הזאת באש ושרפוה ואת הבתים אשר קטרו על גגותיהם לבעל והסכו נסכים לאלהים אחרים למען הכעסני׃ ");
INSERT INTO heb_vpl VALUES ("JR32_30","025_32_30","JER","32","30","30","כי היו בני ישראל ובני יהודה אך עשים הרע בעיני מנערתיהם כי בני ישראל אך מכעסים אתי במעשה ידיהם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_31","025_32_31","JER","32","31","31","כי על אפי ועל חמתי היתה לי העיר הזאת למן היום אשר בנו אותה ועד היום הזה להסירה מעל פני׃ ");
INSERT INTO heb_vpl VALUES ("JR32_32","025_32_32","JER","32","32","32","על כל רעת בני ישראל ובני יהודה אשר עשו להכעסני המה מלכיהם שריהם כהניהם ונביאיהם ואיש יהודה וישבי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR32_33","025_32_33","JER","32","33","33","ויפנו אלי ערף ולא פנים ולמד אתם השכם ולמד ואינם שמעים לקחת מוסר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_34","025_32_34","JER","32","34","34","וישימו שקוציהם בבית אשר נקרא שמי עליו לטמאו׃ ");
INSERT INTO heb_vpl VALUES ("JR32_35","025_32_35","JER","32","35","35","ויבנו את במות הבעל אשר בגיא בן הנם להעביר את בניהם ואת בנותיהם למלך אשר לא צויתים ולא עלתה על לבי לעשות התועבה הזאת למען החטי את יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR32_36","025_32_36","JER","32","36","36","ועתה לכן כה אמר יהוה אלהי ישראל אל העיר הזאת אשר אתם אמרים נתנה ביד מלך בבל בחרב וברעב ובדבר׃ ");
INSERT INTO heb_vpl VALUES ("JR32_37","025_32_37","JER","32","37","37","הנני מקבצם מכל הארצות אשר הדחתים שם באפי ובחמתי ובקצף גדול והשבתים אל המקום הזה והשבתים לבטח׃ ");
INSERT INTO heb_vpl VALUES ("JR32_38","025_32_38","JER","32","38","38","והיו לי לעם ואני אהיה להם לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JR32_39","025_32_39","JER","32","39","39","ונתתי להם לב אחד ודרך אחד ליראה אותי כל הימים לטוב להם ולבניהם אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("JR32_40","025_32_40","JER","32","40","40","וכרתי להם ברית עולם אשר לא אשוב מאחריהם להיטיבי אותם ואת יראתי אתן בלבבם לבלתי סור מעלי׃ ");
INSERT INTO heb_vpl VALUES ("JR32_41","025_32_41","JER","32","41","41","וששתי עליהם להטיב אותם ונטעתים בארץ הזאת באמת בכל לבי ובכל נפשי׃ ");
INSERT INTO heb_vpl VALUES ("JR32_42","025_32_42","JER","32","42","42","כי כה אמר יהוה כאשר הבאתי אל העם הזה את כל הרעה הגדולה הזאת כן אנכי מביא עליהם את כל הטובה אשר אנכי דבר עליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR32_43","025_32_43","JER","32","43","43","ונקנה השדה בארץ הזאת אשר אתם אמרים שממה היא מאין אדם ובהמה נתנה ביד הכשדים׃ ");
INSERT INTO heb_vpl VALUES ("JR32_44","025_32_44","JER","32","44","44","שדות בכסף יקנו וכתוב בספר וחתום והעד עדים בארץ בנימן ובסביבי ירושלם ובערי יהודה ובערי ההר ובערי השפלה ובערי הנגב כי אשיב את שבותם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR33_1","025_33_1","JER","33","1","1","ויהי דבר יהוה אל ירמיהו שנית והוא עודנו עצור בחצר המטרה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR33_2","025_33_2","JER","33","2","2","כה אמר יהוה עשה יהוה יוצר אותה להכינה יהוה שמו׃ ");
INSERT INTO heb_vpl VALUES ("JR33_3","025_33_3","JER","33","3","3","קרא אלי ואענך ואגידה לך גדלות ובצרות לא ידעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR33_4","025_33_4","JER","33","4","4","כי כה אמר יהוה אלהי ישראל על בתי העיר הזאת ועל בתי מלכי יהודה הנתצים אל הסללות ואל החרב׃ ");
INSERT INTO heb_vpl VALUES ("JR33_5","025_33_5","JER","33","5","5","באים להלחם את הכשדים ולמלאם את פגרי האדם אשר הכיתי באפי ובחמתי ואשר הסתרתי פני מהעיר הזאת על כל רעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR33_6","025_33_6","JER","33","6","6","הנני מעלה לה ארכה ומרפא ורפאתים וגליתי להם עתרת שלום ואמת׃ ");
INSERT INTO heb_vpl VALUES ("JR33_7","025_33_7","JER","33","7","7","והשבתי את שבות יהודה ואת שבות ישראל ובנתים כבראשנה׃ ");
INSERT INTO heb_vpl VALUES ("JR33_8","025_33_8","JER","33","8","8","וטהרתים מכל עונם אשר חטאו לי וסלחתי לכול עונותיהם אשר חטאו לי ואשר פשעו בי׃ ");
INSERT INTO heb_vpl VALUES ("JR33_9","025_33_9","JER","33","9","9","והיתה לי לשם ששון לתהלה ולתפארת לכל גויי הארץ אשר ישמעו את כל הטובה אשר אנכי עשה אתם ופחדו ורגזו על כל הטובה ועל כל השלום אשר אנכי עשה לה׃ ");
INSERT INTO heb_vpl VALUES ("JR33_10","025_33_10","JER","33","10","10","כה אמר יהוה עוד ישמע במקום הזה אשר אתם אמרים חרב הוא מאין אדם ומאין בהמה בערי יהודה ובחצות ירושלם הנשמות מאין אדם ומאין יושב ומאין בהמה׃ ");
INSERT INTO heb_vpl VALUES ("JR33_11","025_33_11","JER","33","11","11","קול ששון וקול שמחה קול חתן וקול כלה קול אמרים הודו את יהוה צבאות כי טוב יהוה כי לעולם חסדו מבאים תודה בית יהוה כי אשיב את שבות הארץ כבראשנה אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR33_12","025_33_12","JER","33","12","12","כה אמר יהוה צבאות עוד יהיה במקום הזה החרב מאין אדם ועד בהמה ובכל עריו נוה רעים מרבצים צאן׃ ");
INSERT INTO heb_vpl VALUES ("JR33_13","025_33_13","JER","33","13","13","בערי ההר בערי השפלה ובערי הנגב ובארץ בנימן ובסביבי ירושלם ובערי יהודה עד תעברנה הצאן על ידי מונה אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR33_14","025_33_14","JER","33","14","14","הנה ימים באים נאם יהוה והקמתי את הדבר הטוב אשר דברתי אל בית ישראל ועל בית יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR33_15","025_33_15","JER","33","15","15","בימים ההם ובעת ההיא אצמיח לדוד צמח צדקה ועשה משפט וצדקה בארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR33_16","025_33_16","JER","33","16","16","בימים ההם תושע יהודה וירושלם תשכון לבטח וזה אשר יקרא לה יהוה צדקנו׃ ");
INSERT INTO heb_vpl VALUES ("JR33_17","025_33_17","JER","33","17","17","כי כה אמר יהוה לא יכרת לדוד איש ישב על כסא בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR33_18","025_33_18","JER","33","18","18","ולכהנים הלוים לא יכרת איש מלפני מעלה עולה ומקטיר מנחה ועשה זבח כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("JR33_19","025_33_19","JER","33","19","19","ויהי דבר יהוה אל ירמיהו לאמור׃ ");
INSERT INTO heb_vpl VALUES ("JR33_20","025_33_20","JER","33","20","20","כה אמר יהוה אם תפרו את בריתי היום ואת בריתי הלילה ולבלתי היות יומם ולילה בעתם׃ ");
INSERT INTO heb_vpl VALUES ("JR33_21","025_33_21","JER","33","21","21","גם בריתי תפר את דוד עבדי מהיות לו בן מלך על כסאו ואת הלוים הכהנים משרתי׃ ");
INSERT INTO heb_vpl VALUES ("JR33_22","025_33_22","JER","33","22","22","אשר לא יספר צבא השמים ולא ימד חול הים כן ארבה את זרע דוד עבדי ואת הלוים משרתי אתי׃ ");
INSERT INTO heb_vpl VALUES ("JR33_23","025_33_23","JER","33","23","23","ויהי דבר יהוה אל ירמיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR33_24","025_33_24","JER","33","24","24","הלוא ראית מה העם הזה דברו לאמר שתי המשפחות אשר בחר יהוה בהם וימאסם ואת עמי ינאצון מהיות עוד גוי לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("JR33_25","025_33_25","JER","33","25","25","כה אמר יהוה אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי׃ ");
INSERT INTO heb_vpl VALUES ("JR33_26","025_33_26","JER","33","26","26","גם זרע יעקוב ודוד עבדי אמאס מקחת מזרעו משלים אל זרע אברהם ישחק ויעקב כי אשוב את שבותם ורחמתים׃ ");
INSERT INTO heb_vpl VALUES ("JR34_1","025_34_1","JER","34","1","1","הדבר אשר היה אל ירמיהו מאת יהוה ונבוכדראצר מלך בבל וכל חילו וכל ממלכות ארץ ממשלת ידו וכל העמים נלחמים על ירושלם ועל כל עריה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR34_2","025_34_2","JER","34","2","2","כה אמר יהוה אלהי ישראל הלך ואמרת אל צדקיהו מלך יהודה ואמרת אליו כה אמר יהוה הנני נתן את העיר הזאת ביד מלך בבל ושרפה באש׃ ");
INSERT INTO heb_vpl VALUES ("JR34_3","025_34_3","JER","34","3","3","ואתה לא תמלט מידו כי תפש תתפש ובידו תנתן ועיניך את עיני מלך בבל תראינה ופיהו את פיך ידבר ובבל תבוא׃ ");
INSERT INTO heb_vpl VALUES ("JR34_4","025_34_4","JER","34","4","4","אך שמע דבר יהוה צדקיהו מלך יהודה כה אמר יהוה עליך לא תמות בחרב׃ ");
INSERT INTO heb_vpl VALUES ("JR34_5","025_34_5","JER","34","5","5","בשלום תמות וכמשרפות אבותיך המלכים הראשנים אשר היו לפניך כן ישרפו לך והוי אדון יספדו לך כי דבר אני דברתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR34_6","025_34_6","JER","34","6","6","וידבר ירמיהו הנביא אל צדקיהו מלך יהודה את כל הדברים האלה בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR34_7","025_34_7","JER","34","7","7","וחיל מלך בבל נלחמים על ירושלם ועל כל ערי יהודה הנותרות אל לכיש ואל עזקה כי הנה נשארו בערי יהודה ערי מבצר׃ ");
INSERT INTO heb_vpl VALUES ("JR34_8","025_34_8","JER","34","8","8","הדבר אשר היה אל ירמיהו מאת יהוה אחרי כרת המלך צדקיהו ברית את כל העם אשר בירושלם לקרא להם דרור׃ ");
INSERT INTO heb_vpl VALUES ("JR34_9","025_34_9","JER","34","9","9","לשלח איש את עבדו ואיש את שפחתו העברי והעבריה חפשים לבלתי עבד בם ביהודי אחיהו איש׃ ");
INSERT INTO heb_vpl VALUES ("JR34_10","025_34_10","JER","34","10","10","וישמעו כל השרים וכל העם אשר באו בברית לשלח איש את עבדו ואיש את שפחתו חפשים לבלתי עבד בם עוד וישמעו וישלחו׃ ");
INSERT INTO heb_vpl VALUES ("JR34_11","025_34_11","JER","34","11","11","וישובו אחרי כן וישבו את העבדים ואת השפחות אשר שלחו חפשים ויכבישום לעבדים ולשפחות׃ ");
INSERT INTO heb_vpl VALUES ("JR34_12","025_34_12","JER","34","12","12","ויהי דבר יהוה אל ירמיהו מאת יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR34_13","025_34_13","JER","34","13","13","כה אמר יהוה אלהי ישראל אנכי כרתי ברית את אבותיכם ביום הוצאי אותם מארץ מצרים מבית עבדים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR34_14","025_34_14","JER","34","14","14","מקץ שבע שנים תשלחו איש את אחיו העברי אשר ימכר לך ועבדך שש שנים ושלחתו חפשי מעמך ולא שמעו אבותיכם אלי ולא הטו את אזנם׃ ");
INSERT INTO heb_vpl VALUES ("JR34_15","025_34_15","JER","34","15","15","ותשבו אתם היום ותעשו את הישר בעיני לקרא דרור איש לרעהו ותכרתו ברית לפני בבית אשר נקרא שמי עליו׃ ");
INSERT INTO heb_vpl VALUES ("JR34_16","025_34_16","JER","34","16","16","ותשבו ותחללו את שמי ותשבו איש את עבדו ואיש את שפחתו אשר שלחתם חפשים לנפשם ותכבשו אתם להיות לכם לעבדים ולשפחות׃ ");
INSERT INTO heb_vpl VALUES ("JR34_17","025_34_17","JER","34","17","17","לכן כה אמר יהוה אתם לא שמעתם אלי לקרא דרור איש לאחיו ואיש לרעהו הנני קרא לכם דרור נאם יהוה אל החרב אל הדבר ואל הרעב ונתתי אתכם לזועה לכל ממלכות הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR34_18","025_34_18","JER","34","18","18","ונתתי את האנשים העברים את ברתי אשר לא הקימו את דברי הברית אשר כרתו לפני העגל אשר כרתו לשנים ויעברו בין בתריו׃ ");
INSERT INTO heb_vpl VALUES ("JR34_19","025_34_19","JER","34","19","19","שרי יהודה ושרי ירושלם הסרסים והכהנים וכל עם הארץ העברים בין בתרי העגל׃ ");
INSERT INTO heb_vpl VALUES ("JR34_20","025_34_20","JER","34","20","20","ונתתי אותם ביד איביהם וביד מבקשי נפשם והיתה נבלתם למאכל לעוף השמים ולבהמת הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR34_21","025_34_21","JER","34","21","21","ואת צדקיהו מלך יהודה ואת שריו אתן ביד איביהם וביד מבקשי נפשם וביד חיל מלך בבל העלים מעליכם׃ ");
INSERT INTO heb_vpl VALUES ("JR34_22","025_34_22","JER","34","22","22","הנני מצוה נאם יהוה והשבתים אל העיר הזאת ונלחמו עליה ולכדוה ושרפה באש ואת ערי יהודה אתן שממה מאין ישב׃ ");
INSERT INTO heb_vpl VALUES ("JR35_1","025_35_1","JER","35","1","1","הדבר אשר היה אל ירמיהו מאת יהוה בימי יהויקים בן יאשיהו מלך יהודה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR35_2","025_35_2","JER","35","2","2","הלוך אל בית הרכבים ודברת אותם והבאותם בית יהוה אל אחת הלשכות והשקית אותם יין׃ ");
INSERT INTO heb_vpl VALUES ("JR35_3","025_35_3","JER","35","3","3","ואקח את יאזניה בן ירמיהו בן חבצניה ואת אחיו ואת כל בניו ואת כל בית הרכבים׃ ");
INSERT INTO heb_vpl VALUES ("JR35_4","025_35_4","JER","35","4","4","ואבא אתם בית יהוה אל לשכת בני חנן בן יגדליהו איש האלהים אשר אצל לשכת השרים אשר ממעל ללשכת מעשיהו בן שלם שמר הסף׃ ");
INSERT INTO heb_vpl VALUES ("JR35_5","025_35_5","JER","35","5","5","ואתן לפני בני בית הרכבים גבעים מלאים יין וכסות ואמר אליהם שתו יין׃ ");
INSERT INTO heb_vpl VALUES ("JR35_6","025_35_6","JER","35","6","6","ויאמרו לא נשתה יין כי יונדב בן רכב אבינו צוה עלינו לאמר לא תשתו יין אתם ובניכם עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("JR35_7","025_35_7","JER","35","7","7","ובית לא תבנו וזרע לא תזרעו וכרם לא תטעו ולא יהיה לכם כי באהלים תשבו כל ימיכם למען תחיו ימים רבים על פני האדמה אשר אתם גרים שם׃ ");
INSERT INTO heb_vpl VALUES ("JR35_8","025_35_8","JER","35","8","8","ונשמע בקול יהונדב בן רכב אבינו לכל אשר צונו לבלתי שתות יין כל ימינו אנחנו נשינו בנינו ובנתינו׃ ");
INSERT INTO heb_vpl VALUES ("JR35_9","025_35_9","JER","35","9","9","ולבלתי בנות בתים לשבתנו וכרם ושדה וזרע לא יהיה לנו׃ ");
INSERT INTO heb_vpl VALUES ("JR35_10","025_35_10","JER","35","10","10","ונשב באהלים ונשמע ונעש ככל אשר צונו יונדב אבינו׃ ");
INSERT INTO heb_vpl VALUES ("JR35_11","025_35_11","JER","35","11","11","ויהי בעלות נבוכדראצר מלך בבל אל הארץ ונאמר באו ונבוא ירושלם מפני חיל הכשדים ומפני חיל ארם ונשב בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR35_12","025_35_12","JER","35","12","12","ויהי דבר יהוה אל ירמיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR35_13","025_35_13","JER","35","13","13","כה אמר יהוה צבאות אלהי ישראל הלך ואמרת לאיש יהודה וליושבי ירושלם הלוא תקחו מוסר לשמע אל דברי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR35_14","025_35_14","JER","35","14","14","הוקם את דברי יהונדב בן רכב אשר צוה את בניו לבלתי שתות יין ולא שתו עד היום הזה כי שמעו את מצות אביהם ואנכי דברתי אליכם השכם ודבר ולא שמעתם אלי׃ ");
INSERT INTO heb_vpl VALUES ("JR35_15","025_35_15","JER","35","15","15","ואשלח אליכם את כל עבדי הנבאים השכים ושלח לאמר שבו נא איש מדרכו הרעה והיטיבו מעלליכם ואל תלכו אחרי אלהים אחרים לעבדם ושבו אל האדמה אשר נתתי לכם ולאבתיכם ולא הטיתם את אזנכם ולא שמעתם אלי׃ ");
INSERT INTO heb_vpl VALUES ("JR35_16","025_35_16","JER","35","16","16","כי הקימו בני יהונדב בן רכב את מצות אביהם אשר צום והעם הזה לא שמעו אלי׃ ");
INSERT INTO heb_vpl VALUES ("JR35_17","025_35_17","JER","35","17","17","לכן כה אמר יהוה אלהי צבאות אלהי ישראל הנני מביא אל יהודה ואל כל יושבי ירושלם את כל הרעה אשר דברתי עליהם יען דברתי אליהם ולא שמעו ואקרא להם ולא ענו׃ ");
INSERT INTO heb_vpl VALUES ("JR35_18","025_35_18","JER","35","18","18","ולבית הרכבים אמר ירמיהו כה אמר יהוה צבאות אלהי ישראל יען אשר שמעתם על מצות יהונדב אביכם ותשמרו את כל מצותיו ותעשו ככל אשר צוה אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JR35_19","025_35_19","JER","35","19","19","לכן כה אמר יהוה צבאות אלהי ישראל לא יכרת איש ליונדב בן רכב עמד לפני כל הימים׃ ");
INSERT INTO heb_vpl VALUES ("JR36_1","025_36_1","JER","36","1","1","ויהי בשנה הרביעת ליהויקים בן יאשיהו מלך יהודה היה הדבר הזה אל ירמיהו מאת יהוה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR36_2","025_36_2","JER","36","2","2","קח לך מגלת ספר וכתבת אליה את כל הדברים אשר דברתי אליך על ישראל ועל יהודה ועל כל הגוים מיום דברתי אליך מימי יאשיהו ועד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_3","025_36_3","JER","36","3","3","אולי ישמעו בית יהודה את כל הרעה אשר אנכי חשב לעשות להם למען ישובו איש מדרכו הרעה וסלחתי לעונם ולחטאתם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_4","025_36_4","JER","36","4","4","ויקרא ירמיהו את ברוך בן נריה ויכתב ברוך מפי ירמיהו את כל דברי יהוה אשר דבר אליו על מגלת ספר׃ ");
INSERT INTO heb_vpl VALUES ("JR36_5","025_36_5","JER","36","5","5","ויצוה ירמיהו את ברוך לאמר אני עצור לא אוכל לבוא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_6","025_36_6","JER","36","6","6","ובאת אתה וקראת במגלה אשר כתבת מפי את דברי יהוה באזני העם בית יהוה ביום צום וגם באזני כל יהודה הבאים מעריהם תקראם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_7","025_36_7","JER","36","7","7","אולי תפל תחנתם לפני יהוה וישבו איש מדרכו הרעה כי גדול האף והחמה אשר דבר יהוה אל העם הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_8","025_36_8","JER","36","8","8","ויעש ברוך בן נריה ככל אשר צוהו ירמיהו הנביא לקרא בספר דברי יהוה בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_9","025_36_9","JER","36","9","9","ויהי בשנה החמשית ליהויקים בן יאשיהו מלך יהודה בחדש התשעי קראו צום לפני יהוה כל העם בירושלם וכל העם הבאים מערי יהודה בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_10","025_36_10","JER","36","10","10","ויקרא ברוך בספר את דברי ירמיהו בית יהוה בלשכת גמריהו בן שפן הספר בחצר העליון פתח שער בית יהוה החדש באזני כל העם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_11","025_36_11","JER","36","11","11","וישמע מכיהו בן גמריהו בן שפן את כל דברי יהוה מעל הספר׃ ");
INSERT INTO heb_vpl VALUES ("JR36_12","025_36_12","JER","36","12","12","וירד בית המלך על לשכת הספר והנה שם כל השרים יושבים אלישמע הספר ודליהו בן שמעיהו ואלנתן בן עכבור וגמריהו בן שפן וצדקיהו בן חנניהו וכל השרים׃ ");
INSERT INTO heb_vpl VALUES ("JR36_13","025_36_13","JER","36","13","13","ויגד להם מכיהו את כל הדברים אשר שמע בקרא ברוך בספר באזני העם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_14","025_36_14","JER","36","14","14","וישלחו כל השרים אל ברוך את יהודי בן נתניהו בן שלמיהו בן כושי לאמר המגלה אשר קראת בה באזני העם קחנה בידך ולך ויקח ברוך בן נריהו את המגלה בידו ויבא אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_15","025_36_15","JER","36","15","15","ויאמרו אליו שב נא וקראנה באזנינו ויקרא ברוך באזניהם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_16","025_36_16","JER","36","16","16","ויהי כשמעם את כל הדברים פחדו איש אל רעהו ויאמרו אל ברוך הגיד נגיד למלך את כל הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_17","025_36_17","JER","36","17","17","ואת ברוך שאלו לאמר הגד נא לנו איך כתבת את כל הדברים האלה מפיו׃ ");
INSERT INTO heb_vpl VALUES ("JR36_18","025_36_18","JER","36","18","18","ויאמר להם ברוך מפיו יקרא אלי את כל הדברים האלה ואני כתב על הספר בדיו׃ ");
INSERT INTO heb_vpl VALUES ("JR36_19","025_36_19","JER","36","19","19","ויאמרו השרים אל ברוך לך הסתר אתה וירמיהו ואיש אל ידע איפה אתם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_20","025_36_20","JER","36","20","20","ויבאו אל המלך חצרה ואת המגלה הפקדו בלשכת אלישמע הספר ויגידו באזני המלך את כל הדברים׃ ");
INSERT INTO heb_vpl VALUES ("JR36_21","025_36_21","JER","36","21","21","וישלח המלך את יהודי לקחת את המגלה ויקחה מלשכת אלישמע הספר ויקראה יהודי באזני המלך ובאזני כל השרים העמדים מעל המלך׃ ");
INSERT INTO heb_vpl VALUES ("JR36_22","025_36_22","JER","36","22","22","והמלך יושב בית החרף בחדש התשיעי ואת האח לפניו מבערת׃ ");
INSERT INTO heb_vpl VALUES ("JR36_23","025_36_23","JER","36","23","23","ויהי כקרוא יהודי שלש דלתות וארבעה יקרעה בתער הספר והשלך אל האש אשר אל האח עד תם כל המגלה על האש אשר על האח׃ ");
INSERT INTO heb_vpl VALUES ("JR36_24","025_36_24","JER","36","24","24","ולא פחדו ולא קרעו את בגדיהם המלך וכל עבדיו השמעים את כל הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_25","025_36_25","JER","36","25","25","וגם אלנתן ודליהו וגמריהו הפגעו במלך לבלתי שרף את המגלה ולא שמע אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR36_26","025_36_26","JER","36","26","26","ויצוה המלך את ירחמאל בן המלך ואת שריהו בן עזריאל ואת שלמיהו בן עבדאל לקחת את ברוך הספר ואת ירמיהו הנביא ויסתרם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_27","025_36_27","JER","36","27","27","ויהי דבר יהוה אל ירמיהו אחרי שרף המלך את המגלה ואת הדברים אשר כתב ברוך מפי ירמיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR36_28","025_36_28","JER","36","28","28","שוב קח לך מגלה אחרת וכתב עליה את כל הדברים הראשנים אשר היו על המגלה הראשנה אשר שרף יהויקים מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_29","025_36_29","JER","36","29","29","ועל יהויקים מלך יהודה תאמר כה אמר יהוה אתה שרפת את המגלה הזאת לאמר מדוע כתבת עליה לאמר בא יבוא מלך בבל והשחית את הארץ הזאת והשבית ממנה אדם ובהמה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_30","025_36_30","JER","36","30","30","לכן כה אמר יהוה על יהויקים מלך יהודה לא יהיה לו יושב על כסא דוד ונבלתו תהיה משלכת לחרב ביום ולקרח בלילה׃ ");
INSERT INTO heb_vpl VALUES ("JR36_31","025_36_31","JER","36","31","31","ופקדתי עליו ועל זרעו ועל עבדיו את עונם והבאתי עליהם ועל ישבי ירושלם ואל איש יהודה את כל הרעה אשר דברתי אליהם ולא שמעו׃ ");
INSERT INTO heb_vpl VALUES ("JR36_32","025_36_32","JER","36","32","32","וירמיהו לקח מגלה אחרת ויתנה אל ברוך בן נריהו הספר ויכתב עליה מפי ירמיהו את כל דברי הספר אשר שרף יהויקים מלך יהודה באש ועוד נוסף עליהם דברים רבים כהמה׃ ");
INSERT INTO heb_vpl VALUES ("JR37_1","025_37_1","JER","37","1","1","וימלך מלך צדקיהו בן יאשיהו תחת כניהו בן יהויקים אשר המליך נבוכדראצר מלך בבל בארץ יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR37_2","025_37_2","JER","37","2","2","ולא שמע הוא ועבדיו ועם הארץ אל דברי יהוה אשר דבר ביד ירמיהו הנביא׃ ");
INSERT INTO heb_vpl VALUES ("JR37_3","025_37_3","JER","37","3","3","וישלח המלך צדקיהו את יהוכל בן שלמיה ואת צפניהו בן מעשיה הכהן אל ירמיהו הנביא לאמר התפלל נא בעדנו אל יהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JR37_4","025_37_4","JER","37","4","4","וירמיהו בא ויצא בתוך העם ולא נתנו אתו בית הכליא׃ ");
INSERT INTO heb_vpl VALUES ("JR37_5","025_37_5","JER","37","5","5","וחיל פרעה יצא ממצרים וישמעו הכשדים הצרים על ירושלם את שמעם ויעלו מעל ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR37_6","025_37_6","JER","37","6","6","ויהי דבר יהוה אל ירמיהו הנביא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR37_7","025_37_7","JER","37","7","7","כה אמר יהוה אלהי ישראל כה תאמרו אל מלך יהודה השלח אתכם אלי לדרשני הנה חיל פרעה היצא לכם לעזרה שב לארצו מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR37_8","025_37_8","JER","37","8","8","ושבו הכשדים ונלחמו על העיר הזאת ולכדה ושרפה באש׃ ");
INSERT INTO heb_vpl VALUES ("JR37_9","025_37_9","JER","37","9","9","כה אמר יהוה אל תשאו נפשתיכם לאמר הלך ילכו מעלינו הכשדים כי לא ילכו׃ ");
INSERT INTO heb_vpl VALUES ("JR37_10","025_37_10","JER","37","10","10","כי אם הכיתם כל חיל כשדים הנלחמים אתכם ונשארו בם אנשים מדקרים איש באהלו יקומו ושרפו את העיר הזאת באש׃ ");
INSERT INTO heb_vpl VALUES ("JR37_11","025_37_11","JER","37","11","11","והיה בהעלות חיל הכשדים מעל ירושלם מפני חיל פרעה׃ ");
INSERT INTO heb_vpl VALUES ("JR37_12","025_37_12","JER","37","12","12","ויצא ירמיהו מירושלם ללכת ארץ בנימן לחלק משם בתוך העם׃ ");
INSERT INTO heb_vpl VALUES ("JR37_13","025_37_13","JER","37","13","13","ויהי הוא בשער בנימן ושם בעל פקדת ושמו יראייה בן שלמיה בן חנניה ויתפש את ירמיהו הנביא לאמר אל הכשדים אתה נפל׃ ");
INSERT INTO heb_vpl VALUES ("JR37_14","025_37_14","JER","37","14","14","ויאמר ירמיהו שקר אינני נפל על הכשדים ולא שמע אליו ויתפש יראייה בירמיהו ויבאהו אל השרים׃ ");
INSERT INTO heb_vpl VALUES ("JR37_15","025_37_15","JER","37","15","15","ויקצפו השרים על ירמיהו והכו אתו ונתנו אותו בית האסור בית יהונתן הספר כי אתו עשו לבית הכלא׃ ");
INSERT INTO heb_vpl VALUES ("JR37_16","025_37_16","JER","37","16","16","כי בא ירמיהו אל בית הבור ואל החניות וישב שם ירמיהו ימים רבים׃ ");
INSERT INTO heb_vpl VALUES ("JR37_17","025_37_17","JER","37","17","17","וישלח המלך צדקיהו ויקחהו וישאלהו המלך בביתו בסתר ויאמר היש דבר מאת יהוה ויאמר ירמיהו יש ויאמר ביד מלך בבל תנתן׃ ");
INSERT INTO heb_vpl VALUES ("JR37_18","025_37_18","JER","37","18","18","ויאמר ירמיהו אל המלך צדקיהו מה חטאתי לך ולעבדיך ולעם הזה כי נתתם אותי אל בית הכלא׃ ");
INSERT INTO heb_vpl VALUES ("JR37_19","025_37_19","JER","37","19","19","ואיו נביאיכם אשר נבאו לכם לאמר לא יבא מלך בבל עליכם ועל הארץ הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JR37_20","025_37_20","JER","37","20","20","ועתה שמע נא אדני המלך תפל נא תחנתי לפניך ואל תשבני בית יהונתן הספר ולא אמות שם׃ ");
INSERT INTO heb_vpl VALUES ("JR37_21","025_37_21","JER","37","21","21","ויצוה המלך צדקיהו ויפקדו את ירמיהו בחצר המטרה ונתן לו ככר לחם ליום מחוץ האפים עד תם כל הלחם מן העיר וישב ירמיהו בחצר המטרה׃ ");
INSERT INTO heb_vpl VALUES ("JR38_1","025_38_1","JER","38","1","1","וישמע שפטיה בן מתן וגדליהו בן פשחור ויוכל בן שלמיהו ופשחור בן מלכיה את הדברים אשר ירמיהו מדבר אל כל העם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR38_2","025_38_2","JER","38","2","2","כה אמר יהוה הישב בעיר הזאת ימות בחרב ברעב ובדבר והיצא אל הכשדים יחיה והיתה לו נפשו לשלל וחי׃ ");
INSERT INTO heb_vpl VALUES ("JR38_3","025_38_3","JER","38","3","3","כה אמר יהוה הנתן תנתן העיר הזאת ביד חיל מלך בבל ולכדה׃ ");
INSERT INTO heb_vpl VALUES ("JR38_4","025_38_4","JER","38","4","4","ויאמרו השרים אל המלך יומת נא את האיש הזה כי על כן הוא מרפא את ידי אנשי המלחמה הנשארים בעיר הזאת ואת ידי כל העם לדבר אליהם כדברים האלה כי האיש הזה איננו דרש לשלום לעם הזה כי אם לרעה׃ ");
INSERT INTO heb_vpl VALUES ("JR38_5","025_38_5","JER","38","5","5","ויאמר המלך צדקיהו הנה הוא בידכם כי אין המלך יוכל אתכם דבר׃ ");
INSERT INTO heb_vpl VALUES ("JR38_6","025_38_6","JER","38","6","6","ויקחו את ירמיהו וישלכו אתו אל הבור מלכיהו בן המלך אשר בחצר המטרה וישלחו את ירמיהו בחבלים ובבור אין מים כי אם טיט ויטבע ירמיהו בטיט׃ ");
INSERT INTO heb_vpl VALUES ("JR38_7","025_38_7","JER","38","7","7","וישמע עבד מלך הכושי איש סריס והוא בבית המלך כי נתנו את ירמיהו אל הבור והמלך יושב בשער בנימן׃ ");
INSERT INTO heb_vpl VALUES ("JR38_8","025_38_8","JER","38","8","8","ויצא עבד מלך מבית המלך וידבר אל המלך לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR38_9","025_38_9","JER","38","9","9","אדני המלך הרעו האנשים האלה את כל אשר עשו לירמיהו הנביא את אשר השליכו אל הבור וימת תחתיו מפני הרעב כי אין הלחם עוד בעיר׃ ");
INSERT INTO heb_vpl VALUES ("JR38_10","025_38_10","JER","38","10","10","ויצוה המלך את עבד מלך הכושי לאמר קח בידך מזה שלשים אנשים והעלית את ירמיהו הנביא מן הבור בטרם ימות׃ ");
INSERT INTO heb_vpl VALUES ("JR38_11","025_38_11","JER","38","11","11","ויקח עבד מלך את האנשים בידו ויבא בית המלך אל תחת האוצר ויקח משם בלוי הסחבות ובלוי מלחים וישלחם אל ירמיהו אל הבור בחבלים׃ ");
INSERT INTO heb_vpl VALUES ("JR38_12","025_38_12","JER","38","12","12","ויאמר עבד מלך הכושי אל ירמיהו שים נא בלואי הסחבות והמלחים תחת אצלות ידיך מתחת לחבלים ויעש ירמיהו כן׃ ");
INSERT INTO heb_vpl VALUES ("JR38_13","025_38_13","JER","38","13","13","וימשכו את ירמיהו בחבלים ויעלו אתו מן הבור וישב ירמיהו בחצר המטרה׃ ");
INSERT INTO heb_vpl VALUES ("JR38_14","025_38_14","JER","38","14","14","וישלח המלך צדקיהו ויקח את ירמיהו הנביא אליו אל מבוא השלישי אשר בבית יהוה ויאמר המלך אל ירמיהו שאל אני אתך דבר אל תכחד ממני דבר׃ ");
INSERT INTO heb_vpl VALUES ("JR38_15","025_38_15","JER","38","15","15","ויאמר ירמיהו אל צדקיהו כי אגיד לך הלוא המת תמיתני וכי איעצך לא תשמע אלי׃ ");
INSERT INTO heb_vpl VALUES ("JR38_16","025_38_16","JER","38","16","16","וישבע המלך צדקיהו אל ירמיהו בסתר לאמר חי יהוה את אשר עשה לנו את הנפש הזאת אם אמיתך ואם אתנך ביד האנשים האלה אשר מבקשים את נפשך׃ ");
INSERT INTO heb_vpl VALUES ("JR38_17","025_38_17","JER","38","17","17","ויאמר ירמיהו אל צדקיהו כה אמר יהוה אלהי צבאות אלהי ישראל אם יצא תצא אל שרי מלך בבל וחיתה נפשך והעיר הזאת לא תשרף באש וחיתה אתה וביתך׃ ");
INSERT INTO heb_vpl VALUES ("JR38_18","025_38_18","JER","38","18","18","ואם לא תצא אל שרי מלך בבל ונתנה העיר הזאת ביד הכשדים ושרפוה באש ואתה לא תמלט מידם׃ ");
INSERT INTO heb_vpl VALUES ("JR38_19","025_38_19","JER","38","19","19","ויאמר המלך צדקיהו אל ירמיהו אני דאג את היהודים אשר נפלו אל הכשדים פן יתנו אתי בידם והתעללו בי׃ ");
INSERT INTO heb_vpl VALUES ("JR38_20","025_38_20","JER","38","20","20","ויאמר ירמיהו לא יתנו שמע נא בקול יהוה לאשר אני דבר אליך וייטב לך ותחי נפשך׃ ");
INSERT INTO heb_vpl VALUES ("JR38_21","025_38_21","JER","38","21","21","ואם מאן אתה לצאת זה הדבר אשר הראני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR38_22","025_38_22","JER","38","22","22","והנה כל הנשים אשר נשארו בבית מלך יהודה מוצאות אל שרי מלך בבל והנה אמרות הסיתוך ויכלו לך אנשי שלמך הטבעו בבץ רגלך נסגו אחור׃ ");
INSERT INTO heb_vpl VALUES ("JR38_23","025_38_23","JER","38","23","23","ואת כל נשיך ואת בניך מוצאים אל הכשדים ואתה לא תמלט מידם כי ביד מלך בבל תתפש ואת העיר הזאת תשרף באש׃ ");
INSERT INTO heb_vpl VALUES ("JR38_24","025_38_24","JER","38","24","24","ויאמר צדקיהו אל ירמיהו איש אל ידע בדברים האלה ולא תמות׃ ");
INSERT INTO heb_vpl VALUES ("JR38_25","025_38_25","JER","38","25","25","וכי ישמעו השרים כי דברתי אתך ובאו אליך ואמרו אליך הגידה נא לנו מה דברת אל המלך אל תכחד ממנו ולא נמיתך ומה דבר אליך המלך׃ ");
INSERT INTO heb_vpl VALUES ("JR38_26","025_38_26","JER","38","26","26","ואמרת אליהם מפיל אני תחנתי לפני המלך לבלתי השיבני בית יהונתן למות שם׃ ");
INSERT INTO heb_vpl VALUES ("JR38_27","025_38_27","JER","38","27","27","ויבאו כל השרים אל ירמיהו וישאלו אתו ויגד להם ככל הדברים האלה אשר צוה המלך ויחרשו ממנו כי לא נשמע הדבר׃ ");
INSERT INTO heb_vpl VALUES ("JR38_28","025_38_28","JER","38","28","28","וישב ירמיהו בחצר המטרה עד יום אשר נלכדה ירושלם והיה כאשר נלכדה ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR39_1","025_39_1","JER","39","1","1","בשנה התשעית לצדקיהו מלך יהודה בחדש העשרי בא נבוכדראצר מלך בבל וכל חילו אל ירושלם ויצרו עליה׃ ");
INSERT INTO heb_vpl VALUES ("JR39_2","025_39_2","JER","39","2","2","בעשתי עשרה שנה לצדקיהו בחדש הרביעי בתשעה לחדש הבקעה העיר׃ ");
INSERT INTO heb_vpl VALUES ("JR39_3","025_39_3","JER","39","3","3","ויבאו כל שרי מלך בבל וישבו בשער התוך נרגל שר אצר סמגר נבו שר סכים רב סריס נרגל שר אצר רב מג וכל שארית שרי מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR39_4","025_39_4","JER","39","4","4","ויהי כאשר ראם צדקיהו מלך יהודה וכל אנשי המלחמה ויברחו ויצאו לילה מן העיר דרך גן המלך בשער בין החמתים ויצא דרך הערבה׃ ");
INSERT INTO heb_vpl VALUES ("JR39_5","025_39_5","JER","39","5","5","וירדפו חיל כשדים אחריהם וישגו את צדקיהו בערבות ירחו ויקחו אתו ויעלהו אל נבוכדראצר מלך בבל רבלתה בארץ חמת וידבר אתו משפטים׃ ");
INSERT INTO heb_vpl VALUES ("JR39_6","025_39_6","JER","39","6","6","וישחט מלך בבל את בני צדקיהו ברבלה לעיניו ואת כל חרי יהודה שחט מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR39_7","025_39_7","JER","39","7","7","ואת עיני צדקיהו עור ויאסרהו בנחשתים לביא אתו בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR39_8","025_39_8","JER","39","8","8","ואת בית המלך ואת בית העם שרפו הכשדים באש ואת חמות ירושלם נתצו׃ ");
INSERT INTO heb_vpl VALUES ("JR39_9","025_39_9","JER","39","9","9","ואת יתר העם הנשארים בעיר ואת הנפלים אשר נפלו עליו ואת יתר העם הנשארים הגלה נבוזר אדן רב טבחים בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR39_10","025_39_10","JER","39","10","10","ומן העם הדלים אשר אין להם מאומה השאיר נבוזראדן רב טבחים בארץ יהודה ויתן להם כרמים ויגבים ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("JR39_11","025_39_11","JER","39","11","11","ויצו נבוכדראצר מלך בבל על ירמיהו ביד נבוזראדן רב טבחים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR39_12","025_39_12","JER","39","12","12","קחנו ועיניך שים עליו ואל תעש לו מאומה רע כי אם כאשר ידבר אליך כן עשה עמו׃ ");
INSERT INTO heb_vpl VALUES ("JR39_13","025_39_13","JER","39","13","13","וישלח נבוזראדן רב טבחים ונבושזבן רב סריס ונרגל שר אצר רב מג וכל רבי מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR39_14","025_39_14","JER","39","14","14","וישלחו ויקחו את ירמיהו מחצר המטרה ויתנו אתו אל גדליהו בן אחיקם בן שפן להוצאהו אל הבית וישב בתוך העם׃ ");
INSERT INTO heb_vpl VALUES ("JR39_15","025_39_15","JER","39","15","15","ואל ירמיהו היה דבר יהוה בהיתו עצור בחצר המטרה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR39_16","025_39_16","JER","39","16","16","הלוך ואמרת לעבד מלך הכושי לאמר כה אמר יהוה צבאות אלהי ישראל הנני מבי את דברי אל העיר הזאת לרעה ולא לטובה והיו לפניך ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("JR39_17","025_39_17","JER","39","17","17","והצלתיך ביום ההוא נאם יהוה ולא תנתן ביד האנשים אשר אתה יגור מפניהם׃ ");
INSERT INTO heb_vpl VALUES ("JR39_18","025_39_18","JER","39","18","18","כי מלט אמלטך ובחרב לא תפל והיתה לך נפשך לשלל כי בטחת בי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR40_1","025_40_1","JER","40","1","1","הדבר אשר היה אל ירמיהו מאת יהוה אחר שלח אתו נבוזראדן רב טבחים מן הרמה בקחתו אתו והוא אסור באזקים בתוך כל גלות ירושלם ויהודה המגלים בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR40_2","025_40_2","JER","40","2","2","ויקח רב טבחים לירמיהו ויאמר אליו יהוה אלהיך דבר את הרעה הזאת אל המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR40_3","025_40_3","JER","40","3","3","ויבא ויעש יהוה כאשר דבר כי חטאתם ליהוה ולא שמעתם בקולו והיה לכם דבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR40_4","025_40_4","JER","40","4","4","ועתה הנה פתחתיך היום מן האזקים אשר על ידך אם טוב בעיניך לבוא אתי בבל בא ואשים את עיני עליך ואם רע בעיניך לבוא אתי בבל חדל ראה כל הארץ לפניך אל טוב ואל הישר בעיניך ללכת שמה לך׃ ");
INSERT INTO heb_vpl VALUES ("JR40_5","025_40_5","JER","40","5","5","ועודנו לא ישוב ושבה אל גדליה בן אחיקם בן שפן אשר הפקיד מלך בבל בערי יהודה ושב אתו בתוך העם או אל כל הישר בעיניך ללכת לך ויתן לו רב טבחים ארחה ומשאת וישלחהו׃ ");
INSERT INTO heb_vpl VALUES ("JR40_6","025_40_6","JER","40","6","6","ויבא ירמיהו אל גדליה בן אחיקם המצפתה וישב אתו בתוך העם הנשארים בארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR40_7","025_40_7","JER","40","7","7","וישמעו כל שרי החילים אשר בשדה המה ואנשיהם כי הפקיד מלך בבל את גדליהו בן אחיקם בארץ וכי הפקיד אתו אנשים ונשים וטף ומדלת הארץ מאשר לא הגלו בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR40_8","025_40_8","JER","40","8","8","ויבאו אל גדליה המצפתה וישמעאל בן נתניהו ויוחנן ויונתן בני קרח ושריה בן תנחמת ובני עופי הנטפתי ויזניהו בן המעכתי המה ואנשיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR40_9","025_40_9","JER","40","9","9","וישבע להם גדליהו בן אחיקם בן שפן ולאנשיהם לאמר אל תיראו מעבוד הכשדים שבו בארץ ועבדו את מלך בבל וייטב לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR40_10","025_40_10","JER","40","10","10","ואני הנני ישב במצפה לעמד לפני הכשדים אשר יבאו אלינו ואתם אספו יין וקיץ ושמן ושמו בכליכם ושבו בעריכם אשר תפשתם׃ ");
INSERT INTO heb_vpl VALUES ("JR40_11","025_40_11","JER","40","11","11","וגם כל היהודים אשר במואב ובבני עמון ובאדום ואשר בכל הארצות שמעו כי נתן מלך בבל שארית ליהודה וכי הפקיד עליהם את גדליהו בן אחיקם בן שפן׃ ");
INSERT INTO heb_vpl VALUES ("JR40_12","025_40_12","JER","40","12","12","וישבו כל היהודים מכל המקמות אשר נדחו שם ויבאו ארץ יהודה אל גדליהו המצפתה ויאספו יין וקיץ הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("JR40_13","025_40_13","JER","40","13","13","ויוחנן בן קרח וכל שרי החילים אשר בשדה באו אל גדליהו המצפתה׃ ");
INSERT INTO heb_vpl VALUES ("JR40_14","025_40_14","JER","40","14","14","ויאמרו אליו הידע תדע כי בעליס מלך בני עמון שלח את ישמעאל בן נתניה להכתך נפש ולא האמין להם גדליהו בן אחיקם׃ ");
INSERT INTO heb_vpl VALUES ("JR40_15","025_40_15","JER","40","15","15","ויוחנן בן קרח אמר אל גדליהו בסתר במצפה לאמר אלכה נא ואכה את ישמעאל בן נתניה ואיש לא ידע למה יככה נפש ונפצו כל יהודה הנקבצים אליך ואבדה שארית יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR40_16","025_40_16","JER","40","16","16","ויאמר גדליהו בן אחיקם אל יוחנן בן קרח אל תעש את הדבר הזה כי שקר אתה דבר אל ישמעאל׃ ");
INSERT INTO heb_vpl VALUES ("JR41_1","025_41_1","JER","41","1","1","ויהי בחדש השביעי בא ישמעאל בן נתניה בן אלישמע מזרע המלוכה ורבי המלך ועשרה אנשים אתו אל גדליהו בן אחיקם המצפתה ויאכלו שם לחם יחדו במצפה׃ ");
INSERT INTO heb_vpl VALUES ("JR41_2","025_41_2","JER","41","2","2","ויקם ישמעאל בן נתניה ועשרת האנשים אשר היו אתו ויכו את גדליהו בן אחיקם בן שפן בחרב וימת אתו אשר הפקיד מלך בבל בארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR41_3","025_41_3","JER","41","3","3","ואת כל היהודים אשר היו אתו את גדליהו במצפה ואת הכשדים אשר נמצאו שם את אנשי המלחמה הכה ישמעאל׃ ");
INSERT INTO heb_vpl VALUES ("JR41_4","025_41_4","JER","41","4","4","ויהי ביום השני להמית את גדליהו ואיש לא ידע׃ ");
INSERT INTO heb_vpl VALUES ("JR41_5","025_41_5","JER","41","5","5","ויבאו אנשים משכם משלו ומשמרון שמנים איש מגלחי זקן וקרעי בגדים ומתגדדים ומנחה ולבונה בידם להביא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR41_6","025_41_6","JER","41","6","6","ויצא ישמעאל בן נתניה לקראתם מן המצפה הלך הלך ובכה ויהי כפגש אתם ויאמר אליהם באו אל גדליהו בן אחיקם׃ ");
INSERT INTO heb_vpl VALUES ("JR41_7","025_41_7","JER","41","7","7","ויהי כבואם אל תוך העיר וישחטם ישמעאל בן נתניה אל תוך הבור הוא והאנשים אשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("JR41_8","025_41_8","JER","41","8","8","ועשרה אנשים נמצאו בם ויאמרו אל ישמעאל אל תמתנו כי יש לנו מטמנים בשדה חטים ושערים ושמן ודבש ויחדל ולא המיתם בתוך אחיהם׃ ");
INSERT INTO heb_vpl VALUES ("JR41_9","025_41_9","JER","41","9","9","והבור אשר השליך שם ישמעאל את כל פגרי האנשים אשר הכה ביד גדליהו הוא אשר עשה המלך אסא מפני בעשא מלך ישראל אתו מלא ישמעאל בן נתניהו חללים׃ ");
INSERT INTO heb_vpl VALUES ("JR41_10","025_41_10","JER","41","10","10","וישב ישמעאל את כל שארית העם אשר במצפה את בנות המלך ואת כל העם הנשארים במצפה אשר הפקיד נבוזראדן רב טבחים את גדליהו בן אחיקם וישבם ישמעאל בן נתניה וילך לעבר אל בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JR41_11","025_41_11","JER","41","11","11","וישמע יוחנן בן קרח וכל שרי החילים אשר אתו את כל הרעה אשר עשה ישמעאל בן נתניה׃ ");
INSERT INTO heb_vpl VALUES ("JR41_12","025_41_12","JER","41","12","12","ויקחו את כל האנשים וילכו להלחם עם ישמעאל בן נתניה וימצאו אתו אל מים רבים אשר בגבעון׃ ");
INSERT INTO heb_vpl VALUES ("JR41_13","025_41_13","JER","41","13","13","ויהי כראות כל העם אשר את ישמעאל את יוחנן בן קרח ואת כל שרי החילים אשר אתו וישמחו׃ ");
INSERT INTO heb_vpl VALUES ("JR41_14","025_41_14","JER","41","14","14","ויסבו כל העם אשר שבה ישמעאל מן המצפה וישבו וילכו אל יוחנן בן קרח׃ ");
INSERT INTO heb_vpl VALUES ("JR41_15","025_41_15","JER","41","15","15","וישמעאל בן נתניה נמלט בשמנה אנשים מפני יוחנן וילך אל בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("JR41_16","025_41_16","JER","41","16","16","ויקח יוחנן בן קרח וכל שרי החילים אשר אתו את כל שארית העם אשר השיב מאת ישמעאל בן נתניה מן המצפה אחר הכה את גדליה בן אחיקם גברים אנשי המלחמה ונשים וטף וסרסים אשר השיב מגבעון׃ ");
INSERT INTO heb_vpl VALUES ("JR41_17","025_41_17","JER","41","17","17","וילכו וישבו בגרות כמוהם אשר אצל בית לחם ללכת לבוא מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR41_18","025_41_18","JER","41","18","18","מפני הכשדים כי יראו מפניהם כי הכה ישמעאל בן נתניה את גדליהו בן אחיקם אשר הפקיד מלך בבל בארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR42_1","025_42_1","JER","42","1","1","ויגשו כל שרי החילים ויוחנן בן קרח ויזניה בן הושעיה וכל העם מקטן ועד גדול׃ ");
INSERT INTO heb_vpl VALUES ("JR42_2","025_42_2","JER","42","2","2","ויאמרו אל ירמיהו הנביא תפל נא תחנתנו לפניך והתפלל בעדנו אל יהוה אלהיך בעד כל השארית הזאת כי נשארנו מעט מהרבה כאשר עיניך ראות אתנו׃ ");
INSERT INTO heb_vpl VALUES ("JR42_3","025_42_3","JER","42","3","3","ויגד לנו יהוה אלהיך את הדרך אשר נלך בה ואת הדבר אשר נעשה׃ ");
INSERT INTO heb_vpl VALUES ("JR42_4","025_42_4","JER","42","4","4","ויאמר אליהם ירמיהו הנביא שמעתי הנני מתפלל אל יהוה אלהיכם כדבריכם והיה כל הדבר אשר יענה יהוה אתכם אגיד לכם לא אמנע מכם דבר׃ ");
INSERT INTO heb_vpl VALUES ("JR42_5","025_42_5","JER","42","5","5","והמה אמרו אל ירמיהו יהי יהוה בנו לעד אמת ונאמן אם לא ככל הדבר אשר ישלחך יהוה אלהיך אלינו כן נעשה׃ ");
INSERT INTO heb_vpl VALUES ("JR42_6","025_42_6","JER","42","6","6","אם טוב ואם רע בקול יהוה אלהינו אשר אנו שלחים אתך אליו נשמע למען אשר ייטב לנו כי נשמע בקול יהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JR42_7","025_42_7","JER","42","7","7","ויהי מקץ עשרת ימים ויהי דבר יהוה אל ירמיהו׃ ");
INSERT INTO heb_vpl VALUES ("JR42_8","025_42_8","JER","42","8","8","ויקרא אל יוחנן בן קרח ואל כל שרי החילים אשר אתו ולכל העם למקטן ועד גדול׃ ");
INSERT INTO heb_vpl VALUES ("JR42_9","025_42_9","JER","42","9","9","ויאמר אליהם כה אמר יהוה אלהי ישראל אשר שלחתם אתי אליו להפיל תחנתכם לפניו׃ ");
INSERT INTO heb_vpl VALUES ("JR42_10","025_42_10","JER","42","10","10","אם שוב תשבו בארץ הזאת ובניתי אתכם ולא אהרס ונטעתי אתכם ולא אתוש כי נחמתי אל הרעה אשר עשיתי לכם׃ ");
INSERT INTO heb_vpl VALUES ("JR42_11","025_42_11","JER","42","11","11","אל תיראו מפני מלך בבל אשר אתם יראים מפניו אל תיראו ממנו נאם יהוה כי אתכם אני להושיע אתכם ולהציל אתכם מידו׃ ");
INSERT INTO heb_vpl VALUES ("JR42_12","025_42_12","JER","42","12","12","ואתן לכם רחמים ורחם אתכם והשיב אתכם אל אדמתכם׃ ");
INSERT INTO heb_vpl VALUES ("JR42_13","025_42_13","JER","42","13","13","ואם אמרים אתם לא נשב בארץ הזאת לבלתי שמע בקול יהוה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("JR42_14","025_42_14","JER","42","14","14","לאמר לא כי ארץ מצרים נבוא אשר לא נראה מלחמה וקול שופר לא נשמע וללחם לא נרעב ושם נשב׃ ");
INSERT INTO heb_vpl VALUES ("JR42_15","025_42_15","JER","42","15","15","ועתה לכן שמעו דבר יהוה שארית יהודה כה אמר יהוה צבאות אלהי ישראל אם אתם שום תשמון פניכם לבא מצרים ובאתם לגור שם׃ ");
INSERT INTO heb_vpl VALUES ("JR42_16","025_42_16","JER","42","16","16","והיתה החרב אשר אתם יראים ממנה שם תשיג אתכם בארץ מצרים והרעב אשר אתם דאגים ממנו שם ידבק אחריכם מצרים ושם תמתו׃ ");
INSERT INTO heb_vpl VALUES ("JR42_17","025_42_17","JER","42","17","17","ויהיו כל האנשים אשר שמו את פניהם לבוא מצרים לגור שם ימותו בחרב ברעב ובדבר ולא יהיה להם שריד ופליט מפני הרעה אשר אני מביא עליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR42_18","025_42_18","JER","42","18","18","כי כה אמר יהוה צבאות אלהי ישראל כאשר נתך אפי וחמתי על ישבי ירושלם כן תתך חמתי עליכם בבאכם מצרים והייתם לאלה ולשמה ולקללה ולחרפה ולא תראו עוד את המקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR42_19","025_42_19","JER","42","19","19","דבר יהוה עליכם שארית יהודה אל תבאו מצרים ידע תדעו כי העידתי בכם היום׃ ");
INSERT INTO heb_vpl VALUES ("JR42_20","025_42_20","JER","42","20","20","כי התעתים בנפשותיכם כי אתם שלחתם אתי אל יהוה אלהיכם לאמר התפלל בעדנו אל יהוה אלהינו וככל אשר יאמר יהוה אלהינו כן הגד לנו ועשינו׃ ");
INSERT INTO heb_vpl VALUES ("JR42_21","025_42_21","JER","42","21","21","ואגד לכם היום ולא שמעתם בקול יהוה אלהיכם ולכל אשר שלחני אליכם׃ ");
INSERT INTO heb_vpl VALUES ("JR42_22","025_42_22","JER","42","22","22","ועתה ידע תדעו כי בחרב ברעב ובדבר תמותו במקום אשר חפצתם לבוא לגור שם׃ ");
INSERT INTO heb_vpl VALUES ("JR43_1","025_43_1","JER","43","1","1","ויהי ככלות ירמיהו לדבר אל כל העם את כל דברי יהוה אלהיהם אשר שלחו יהוה אלהיהם אליהם את כל הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR43_2","025_43_2","JER","43","2","2","ויאמר עזריה בן הושעיה ויוחנן בן קרח וכל האנשים הזדים אמרים אל ירמיהו שקר אתה מדבר לא שלחך יהוה אלהינו לאמר לא תבאו מצרים לגור שם׃ ");
INSERT INTO heb_vpl VALUES ("JR43_3","025_43_3","JER","43","3","3","כי ברוך בן נריה מסית אתך בנו למען תת אתנו ביד הכשדים להמית אתנו ולהגלות אתנו בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR43_4","025_43_4","JER","43","4","4","ולא שמע יוחנן בן קרח וכל שרי החילים וכל העם בקול יהוה לשבת בארץ יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR43_5","025_43_5","JER","43","5","5","ויקח יוחנן בן קרח וכל שרי החילים את כל שארית יהודה אשר שבו מכל הגוים אשר נדחו שם לגור בארץ יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR43_6","025_43_6","JER","43","6","6","את הגברים ואת הנשים ואת הטף ואת בנות המלך ואת כל הנפש אשר הניח נבוזראדן רב טבחים את גדליהו בן אחיקם בן שפן ואת ירמיהו הנביא ואת ברוך בן נריהו׃ ");
INSERT INTO heb_vpl VALUES ("JR43_7","025_43_7","JER","43","7","7","ויבאו ארץ מצרים כי לא שמעו בקול יהוה ויבאו עד תחפנחס׃ ");
INSERT INTO heb_vpl VALUES ("JR43_8","025_43_8","JER","43","8","8","ויהי דבר יהוה אל ירמיהו בתחפנחס לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR43_9","025_43_9","JER","43","9","9","קח בידך אבנים גדלות וטמנתם במלט במלבן אשר בפתח בית פרעה בתחפנחס לעיני אנשים יהודים׃ ");
INSERT INTO heb_vpl VALUES ("JR43_10","025_43_10","JER","43","10","10","ואמרת אליהם כה אמר יהוה צבאות אלהי ישראל הנני שלח ולקחתי את נבוכדראצר מלך בבל עבדי ושמתי כסאו ממעל לאבנים האלה אשר טמנתי ונטה את שפרורו עליהם׃ ");
INSERT INTO heb_vpl VALUES ("JR43_11","025_43_11","JER","43","11","11","ובאה והכה את ארץ מצרים אשר למות למות ואשר לשבי לשבי ואשר לחרב לחרב׃ ");
INSERT INTO heb_vpl VALUES ("JR43_12","025_43_12","JER","43","12","12","והצתי אש בבתי אלהי מצרים ושרפם ושבם ועטה את ארץ מצרים כאשר יעטה הרעה את בגדו ויצא משם בשלום׃ ");
INSERT INTO heb_vpl VALUES ("JR43_13","025_43_13","JER","43","13","13","ושבר את מצבות בית שמש אשר בארץ מצרים ואת בתי אלהי מצרים ישרף באש׃ ");
INSERT INTO heb_vpl VALUES ("JR44_1","025_44_1","JER","44","1","1","הדבר אשר היה אל ירמיהו אל כל היהודים הישבים בארץ מצרים הישבים במגדל ובתחפנחס ובנף ובארץ פתרוס לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR44_2","025_44_2","JER","44","2","2","כה אמר יהוה צבאות אלהי ישראל אתם ראיתם את כל הרעה אשר הבאתי על ירושלם ועל כל ערי יהודה והנם חרבה היום הזה ואין בהם יושב׃ ");
INSERT INTO heb_vpl VALUES ("JR44_3","025_44_3","JER","44","3","3","מפני רעתם אשר עשו להכעסני ללכת לקטר לעבד לאלהים אחרים אשר לא ידעום המה אתם ואבתיכם׃ ");
INSERT INTO heb_vpl VALUES ("JR44_4","025_44_4","JER","44","4","4","ואשלח אליכם את כל עבדי הנביאים השכים ושלח לאמר אל נא תעשו את דבר התעבה הזאת אשר שנאתי׃ ");
INSERT INTO heb_vpl VALUES ("JR44_5","025_44_5","JER","44","5","5","ולא שמעו ולא הטו את אזנם לשוב מרעתם לבלתי קטר לאלהים אחרים׃ ");
INSERT INTO heb_vpl VALUES ("JR44_6","025_44_6","JER","44","6","6","ותתך חמתי ואפי ותבער בערי יהודה ובחצות ירושלם ותהיינה לחרבה לשממה כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR44_7","025_44_7","JER","44","7","7","ועתה כה אמר יהוה אלהי צבאות אלהי ישראל למה אתם עשים רעה גדולה אל נפשתכם להכרית לכם איש ואשה עולל ויונק מתוך יהודה לבלתי הותיר לכם שארית׃ ");
INSERT INTO heb_vpl VALUES ("JR44_8","025_44_8","JER","44","8","8","להכעסני במעשי ידיכם לקטר לאלהים אחרים בארץ מצרים אשר אתם באים לגור שם למען הכרית לכם ולמען היותכם לקללה ולחרפה בכל גויי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR44_9","025_44_9","JER","44","9","9","השכחתם את רעות אבותיכם ואת רעות מלכי יהודה ואת רעות נשיו ואת רעתכם ואת רעת נשיכם אשר עשו בארץ יהודה ובחצות ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR44_10","025_44_10","JER","44","10","10","לא דכאו עד היום הזה ולא יראו ולא הלכו בתורתי ובחקתי אשר נתתי לפניכם ולפני אבותיכם׃ ");
INSERT INTO heb_vpl VALUES ("JR44_11","025_44_11","JER","44","11","11","לכן כה אמר יהוה צבאות אלהי ישראל הנני שם פני בכם לרעה ולהכרית את כל יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR44_12","025_44_12","JER","44","12","12","ולקחתי את שארית יהודה אשר שמו פניהם לבוא ארץ מצרים לגור שם ותמו כל בארץ מצרים יפלו בחרב ברעב יתמו מקטן ועד גדול בחרב וברעב ימתו והיו לאלה לשמה ולקללה ולחרפה׃ ");
INSERT INTO heb_vpl VALUES ("JR44_13","025_44_13","JER","44","13","13","ופקדתי על היושבים בארץ מצרים כאשר פקדתי על ירושלם בחרב ברעב ובדבר׃ ");
INSERT INTO heb_vpl VALUES ("JR44_14","025_44_14","JER","44","14","14","ולא יהיה פליט ושריד לשארית יהודה הבאים לגור שם בארץ מצרים ולשוב ארץ יהודה אשר המה מנשאים את נפשם לשוב לשבת שם כי לא ישובו כי אם פלטים׃ ");
INSERT INTO heb_vpl VALUES ("JR44_15","025_44_15","JER","44","15","15","ויענו את ירמיהו כל האנשים הידעים כי מקטרות נשיהם לאלהים אחרים וכל הנשים העמדות קהל גדול וכל העם הישבים בארץ מצרים בפתרוס לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR44_16","025_44_16","JER","44","16","16","הדבר אשר דברת אלינו בשם יהוה איננו שמעים אליך׃ ");
INSERT INTO heb_vpl VALUES ("JR44_17","025_44_17","JER","44","17","17","כי עשה נעשה את כל הדבר אשר יצא מפינו לקטר למלכת השמים והסיך לה נסכים כאשר עשינו אנחנו ואבתינו מלכינו ושרינו בערי יהודה ובחצות ירושלם ונשבע לחם ונהיה טובים ורעה לא ראינו׃ ");
INSERT INTO heb_vpl VALUES ("JR44_18","025_44_18","JER","44","18","18","ומן אז חדלנו לקטר למלכת השמים והסך לה נסכים חסרנו כל ובחרב וברעב תמנו׃ ");
INSERT INTO heb_vpl VALUES ("JR44_19","025_44_19","JER","44","19","19","וכי אנחנו מקטרים למלכת השמים ולהסך לה נסכים המבלעדי אנשינו עשינו לה כונים להעצבה והסך לה נסכים׃ ");
INSERT INTO heb_vpl VALUES ("JR44_20","025_44_20","JER","44","20","20","ויאמר ירמיהו אל כל העם על הגברים ועל הנשים ועל כל העם הענים אתו דבר לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR44_21","025_44_21","JER","44","21","21","הלוא את הקטר אשר קטרתם בערי יהודה ובחצות ירושלם אתם ואבותיכם מלכיכם ושריכם ועם הארץ אתם זכר יהוה ותעלה על לבו׃ ");
INSERT INTO heb_vpl VALUES ("JR44_22","025_44_22","JER","44","22","22","ולא יוכל יהוה עוד לשאת מפני רע מעלליכם מפני התועבת אשר עשיתם ותהי ארצכם לחרבה ולשמה ולקללה מאין יושב כהיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR44_23","025_44_23","JER","44","23","23","מפני אשר קטרתם ואשר חטאתם ליהוה ולא שמעתם בקול יהוה ובתרתו ובחקתיו ובעדותיו לא הלכתם על כן קראת אתכם הרעה הזאת כיום הזה׃ ");
INSERT INTO heb_vpl VALUES ("JR44_24","025_44_24","JER","44","24","24","ויאמר ירמיהו אל כל העם ואל כל הנשים שמעו דבר יהוה כל יהודה אשר בארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR44_25","025_44_25","JER","44","25","25","כה אמר יהוה צבאות אלהי ישראל לאמר אתם ונשיכם ותדברנה בפיכם ובידיכם מלאתם לאמר עשה נעשה את נדרינו אשר נדרנו לקטר למלכת השמים ולהסך לה נסכים הקים תקימנה את נדריכם ועשה תעשינה את נדריכם׃ ");
INSERT INTO heb_vpl VALUES ("JR44_26","025_44_26","JER","44","26","26","לכן שמעו דבר יהוה כל יהודה הישבים בארץ מצרים הנני נשבעתי בשמי הגדול אמר יהוה אם יהיה עוד שמי נקרא בפי כל איש יהודה אמר חי אדני יהוה בכל ארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR44_27","025_44_27","JER","44","27","27","הנני שקד עליהם לרעה ולא לטובה ותמו כל איש יהודה אשר בארץ מצרים בחרב וברעב עד כלותם׃ ");
INSERT INTO heb_vpl VALUES ("JR44_28","025_44_28","JER","44","28","28","ופליטי חרב ישבון מן ארץ מצרים ארץ יהודה מתי מספר וידעו כל שארית יהודה הבאים לארץ מצרים לגור שם דבר מי יקום ממני ומהם׃ ");
INSERT INTO heb_vpl VALUES ("JR44_29","025_44_29","JER","44","29","29","וזאת לכם האות נאם יהוה כי פקד אני עליכם במקום הזה למען תדעו כי קום יקומו דברי עליכם לרעה׃ ");
INSERT INTO heb_vpl VALUES ("JR44_30","025_44_30","JER","44","30","30","כה אמר יהוה הנני נתן את פרעה חפרע מלך מצרים ביד איביו וביד מבקשי נפשו כאשר נתתי את צדקיהו מלך יהודה ביד נבוכדראצר מלך בבל איבו ומבקש נפשו׃ ");
INSERT INTO heb_vpl VALUES ("JR45_1","025_45_1","JER","45","1","1","הדבר אשר דבר ירמיהו הנביא אל ברוך בן נריה בכתבו את הדברים האלה על ספר מפי ירמיהו בשנה הרבעית ליהויקים בן יאשיהו מלך יהודה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR45_2","025_45_2","JER","45","2","2","כה אמר יהוה אלהי ישראל עליך ברוך׃ ");
INSERT INTO heb_vpl VALUES ("JR45_3","025_45_3","JER","45","3","3","אמרת אוי נא לי כי יסף יהוה יגון על מכאבי יגעתי באנחתי ומנוחה לא מצאתי׃ ");
INSERT INTO heb_vpl VALUES ("JR45_4","025_45_4","JER","45","4","4","כה תאמר אליו כה אמר יהוה הנה אשר בניתי אני הרס ואת אשר נטעתי אני נתש ואת כל הארץ היא׃ ");
INSERT INTO heb_vpl VALUES ("JR45_5","025_45_5","JER","45","5","5","ואתה תבקש לך גדלות אל תבקש כי הנני מביא רעה על כל בשר נאם יהוה ונתתי לך את נפשך לשלל על כל המקמות אשר תלך שם׃ ");
INSERT INTO heb_vpl VALUES ("JR46_1","025_46_1","JER","46","1","1","אשר היה דבר יהוה אל ירמיהו הנביא על הגוים׃ ");
INSERT INTO heb_vpl VALUES ("JR46_2","025_46_2","JER","46","2","2","למצרים על חיל פרעה נכו מלך מצרים אשר היה על נהר פרת בכרכמש אשר הכה נבוכדראצר מלך בבל בשנת הרביעית ליהויקים בן יאשיהו מלך יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JR46_3","025_46_3","JER","46","3","3","ערכו מגן וצנה וגשו למלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JR46_4","025_46_4","JER","46","4","4","אסרו הסוסים ועלו הפרשים והתיצבו בכובעים מרקו הרמחים לבשו הסרינת׃ ");
INSERT INTO heb_vpl VALUES ("JR46_5","025_46_5","JER","46","5","5","מדוע ראיתי המה חתים נסגים אחור וגבוריהם יכתו ומנוס נסו ולא הפנו מגור מסביב נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR46_6","025_46_6","JER","46","6","6","אל ינוס הקל ואל ימלט הגבור צפונה על יד נהר פרת כשלו ונפלו׃ ");
INSERT INTO heb_vpl VALUES ("JR46_7","025_46_7","JER","46","7","7","מי זה כיאר יעלה כנהרות יתגעשו מימיו׃ ");
INSERT INTO heb_vpl VALUES ("JR46_8","025_46_8","JER","46","8","8","מצרים כיאר יעלה וכנהרות יתגעשו מים ויאמר אעלה אכסה ארץ אבידה עיר וישבי בה׃ ");
INSERT INTO heb_vpl VALUES ("JR46_9","025_46_9","JER","46","9","9","עלו הסוסים והתהללו הרכב ויצאו הגבורים כוש ופוט תפשי מגן ולודים תפשי דרכי קשת׃ ");
INSERT INTO heb_vpl VALUES ("JR46_10","025_46_10","JER","46","10","10","והיום ההוא לאדני יהוה צבאות יום נקמה להנקם מצריו ואכלה חרב ושבעה ורותה מדמם כי זבח לאדני יהוה צבאות בארץ צפון אל נהר פרת׃ ");
INSERT INTO heb_vpl VALUES ("JR46_11","025_46_11","JER","46","11","11","עלי גלעד וקחי צרי בתולת בת מצרים לשוא הרביתי רפאות תעלה אין לך׃ ");
INSERT INTO heb_vpl VALUES ("JR46_12","025_46_12","JER","46","12","12","שמעו גוים קלונך וצוחתך מלאה הארץ כי גבור בגבור כשלו יחדיו נפלו שניהם׃ ");
INSERT INTO heb_vpl VALUES ("JR46_13","025_46_13","JER","46","13","13","הדבר אשר דבר יהוה אל ירמיהו הנביא לבוא נבוכדראצר מלך בבל להכות את ארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("JR46_14","025_46_14","JER","46","14","14","הגידו במצרים והשמיעו במגדול והשמיעו בנף ובתחפנחס אמרו התיצב והכן לך כי אכלה חרב סביביך׃ ");
INSERT INTO heb_vpl VALUES ("JR46_15","025_46_15","JER","46","15","15","מדוע נסחף אביריך לא עמד כי יהוה הדפו׃ ");
INSERT INTO heb_vpl VALUES ("JR46_16","025_46_16","JER","46","16","16","הרבה כושל גם נפל איש אל רעהו ויאמרו קומה ונשבה אל עמנו ואל ארץ מולדתנו מפני חרב היונה׃ ");
INSERT INTO heb_vpl VALUES ("JR46_17","025_46_17","JER","46","17","17","קראו שם פרעה מלך מצרים שאון העביר המועד׃ ");
INSERT INTO heb_vpl VALUES ("JR46_18","025_46_18","JER","46","18","18","חי אני נאם המלך יהוה צבאות שמו כי כתבור בהרים וככרמל בים יבוא׃ ");
INSERT INTO heb_vpl VALUES ("JR46_19","025_46_19","JER","46","19","19","כלי גולה עשי לך יושבת בת מצרים כי נף לשמה תהיה ונצתה מאין יושב׃ ");
INSERT INTO heb_vpl VALUES ("JR46_20","025_46_20","JER","46","20","20","עגלה יפה פיה מצרים קרץ מצפון בא בא׃ ");
INSERT INTO heb_vpl VALUES ("JR46_21","025_46_21","JER","46","21","21","גם שכריה בקרבה כעגלי מרבק כי גם המה הפנו נסו יחדיו לא עמדו כי יום אידם בא עליהם עת פקדתם׃ ");
INSERT INTO heb_vpl VALUES ("JR46_22","025_46_22","JER","46","22","22","קולה כנחש ילך כי בחיל ילכו ובקרדמות באו לה כחטבי עצים׃ ");
INSERT INTO heb_vpl VALUES ("JR46_23","025_46_23","JER","46","23","23","כרתו יערה נאם יהוה כי לא יחקר כי רבו מארבה ואין להם מספר׃ ");
INSERT INTO heb_vpl VALUES ("JR46_24","025_46_24","JER","46","24","24","הבישה בת מצרים נתנה ביד עם צפון׃ ");
INSERT INTO heb_vpl VALUES ("JR46_25","025_46_25","JER","46","25","25","אמר יהוה צבאות אלהי ישראל הנני פוקד אל אמון מנא ועל פרעה ועל מצרים ועל אלהיה ועל מלכיה ועל פרעה ועל הבטחים בו׃ ");
INSERT INTO heb_vpl VALUES ("JR46_26","025_46_26","JER","46","26","26","ונתתים ביד מבקשי נפשם וביד נבוכדראצר מלך בבל וביד עבדיו ואחרי כן תשכן כימי קדם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR46_27","025_46_27","JER","46","27","27","ואתה אל תירא עבדי יעקב ואל תחת ישראל כי הנני מושעך מרחוק ואת זרעך מארץ שבים ושב יעקוב ושקט ושאנן ואין מחריד׃ ");
INSERT INTO heb_vpl VALUES ("JR46_28","025_46_28","JER","46","28","28","אתה אל תירא עבדי יעקב נאם יהוה כי אתך אני כי אעשה כלה בכל הגוים אשר הדחתיך שמה ואתך לא אעשה כלה ויסרתיך למשפט ונקה לא אנקך׃ ");
INSERT INTO heb_vpl VALUES ("JR47_1","025_47_1","JER","47","1","1","אשר היה דבר יהוה אל ירמיהו הנביא אל פלשתים בטרם יכה פרעה את עזה׃ ");
INSERT INTO heb_vpl VALUES ("JR47_2","025_47_2","JER","47","2","2","כה אמר יהוה הנה מים עלים מצפון והיו לנחל שוטף וישטפו ארץ ומלואה עיר וישבי בה וזעקו האדם והילל כל יושב הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR47_3","025_47_3","JER","47","3","3","מקול שעטת פרסות אביריו מרעש לרכבו המון גלגליו לא הפנו אבות אל בנים מרפיון ידים׃ ");
INSERT INTO heb_vpl VALUES ("JR47_4","025_47_4","JER","47","4","4","על היום הבא לשדוד את כל פלשתים להכרית לצר ולצידון כל שריד עזר כי שדד יהוה את פלשתים שארית אי כפתור׃ ");
INSERT INTO heb_vpl VALUES ("JR47_5","025_47_5","JER","47","5","5","באה קרחה אל עזה נדמתה אשקלון שארית עמקם עד מתי תתגודדי׃ ");
INSERT INTO heb_vpl VALUES ("JR47_6","025_47_6","JER","47","6","6","הוי חרב ליהוה עד אנה לא תשקטי האספי אל תערך הרגעי ודמי׃ ");
INSERT INTO heb_vpl VALUES ("JR47_7","025_47_7","JER","47","7","7","איך תשקטי ויהוה צוה לה אל אשקלון ואל חוף הים שם יעדה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_1","025_48_1","JER","48","1","1","למואב כה אמר יהוה צבאות אלהי ישראל הוי אל נבו כי שדדה הבישה נלכדה קריתים הבישה המשגב וחתה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_2","025_48_2","JER","48","2","2","אין עוד תהלת מואב בחשבון חשבו עליה רעה לכו ונכריתנה מגוי גם מדמן תדמי אחריך תלך חרב׃ ");
INSERT INTO heb_vpl VALUES ("JR48_3","025_48_3","JER","48","3","3","קול צעקה מחרונים שד ושבר גדול׃ ");
INSERT INTO heb_vpl VALUES ("JR48_4","025_48_4","JER","48","4","4","נשברה מואב השמיעו זעקה צעוריה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_5","025_48_5","JER","48","5","5","כי מעלה הלחות בבכי יעלה בכי כי במורד חורנים צרי צעקת שבר שמעו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_6","025_48_6","JER","48","6","6","נסו מלטו נפשכם ותהיינה כערוער במדבר׃ ");
INSERT INTO heb_vpl VALUES ("JR48_7","025_48_7","JER","48","7","7","כי יען בטחך במעשיך ובאוצרותיך גם את תלכדי ויצא כמיש בגולה כהניו ושריו יחד׃ ");
INSERT INTO heb_vpl VALUES ("JR48_8","025_48_8","JER","48","8","8","ויבא שדד אל כל עיר ועיר לא תמלט ואבד העמק ונשמד המישר אשר אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_9","025_48_9","JER","48","9","9","תנו ציץ למואב כי נצא תצא ועריה לשמה תהיינה מאין יושב בהן׃ ");
INSERT INTO heb_vpl VALUES ("JR48_10","025_48_10","JER","48","10","10","ארור עשה מלאכת יהוה רמיה וארור מנע חרבו מדם׃ ");
INSERT INTO heb_vpl VALUES ("JR48_11","025_48_11","JER","48","11","11","שאנן מואב מנעוריו ושקט הוא אל שמריו ולא הורק מכלי אל כלי ובגולה לא הלך על כן עמד טעמו בו וריחו לא נמר׃ ");
INSERT INTO heb_vpl VALUES ("JR48_12","025_48_12","JER","48","12","12","לכן הנה ימים באים נאם יהוה ושלחתי לו צעים וצעהו וכליו יריקו ונבליהם ינפצו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_13","025_48_13","JER","48","13","13","ובש מואב מכמוש כאשר בשו בית ישראל מבית אל מבטחם׃ ");
INSERT INTO heb_vpl VALUES ("JR48_14","025_48_14","JER","48","14","14","איך תאמרו גבורים אנחנו ואנשי חיל למלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_15","025_48_15","JER","48","15","15","שדד מואב ועריה עלה ומבחר בחוריו ירדו לטבח נאם המלך יהוה צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_16","025_48_16","JER","48","16","16","קרוב איד מואב לבוא ורעתו מהרה מאד׃ ");
INSERT INTO heb_vpl VALUES ("JR48_17","025_48_17","JER","48","17","17","נדו לו כל סביביו וכל ידעי שמו אמרו איכה נשבר מטה עז מקל תפארה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_18","025_48_18","JER","48","18","18","רדי מכבוד ישבי בצמא ישבת בת דיבון כי שדד מואב עלה בך שחת מבצריך׃ ");
INSERT INTO heb_vpl VALUES ("JR48_19","025_48_19","JER","48","19","19","אל דרך עמדי וצפי יושבת ערוער שאלי נס ונמלטה אמרי מה נהיתה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_20","025_48_20","JER","48","20","20","הביש מואב כי חתה הילילי וזעקי הגידו בארנון כי שדד מואב׃ ");
INSERT INTO heb_vpl VALUES ("JR48_21","025_48_21","JER","48","21","21","ומשפט בא אל ארץ המישר אל חלון ואל יהצה ועל מופעת׃ ");
INSERT INTO heb_vpl VALUES ("JR48_22","025_48_22","JER","48","22","22","ועל דיבון ועל נבו ועל בית דבלתים׃ ");
INSERT INTO heb_vpl VALUES ("JR48_23","025_48_23","JER","48","23","23","ועל קריתים ועל בית גמול ועל בית מעון׃ ");
INSERT INTO heb_vpl VALUES ("JR48_24","025_48_24","JER","48","24","24","ועל קריות ועל בצרה ועל כל ערי ארץ מואב הרחקות והקרבות׃ ");
INSERT INTO heb_vpl VALUES ("JR48_25","025_48_25","JER","48","25","25","נגדעה קרן מואב וזרעו נשברה נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_26","025_48_26","JER","48","26","26","השכירהו כי על יהוה הגדיל וספק מואב בקיאו והיה לשחק גם הוא׃ ");
INSERT INTO heb_vpl VALUES ("JR48_27","025_48_27","JER","48","27","27","ואם לוא השחק היה לך ישראל אם בגנבים נמצאה כי מדי דבריך בו תתנודד׃ ");
INSERT INTO heb_vpl VALUES ("JR48_28","025_48_28","JER","48","28","28","עזבו ערים ושכנו בסלע ישבי מואב והיו כיונה תקנן בעברי פי פחת׃ ");
INSERT INTO heb_vpl VALUES ("JR48_29","025_48_29","JER","48","29","29","שמענו גאון מואב גאה מאד גבהו וגאונו וגאותו ורם לבו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_30","025_48_30","JER","48","30","30","אני ידעתי נאם יהוה עברתו ולא כן בדיו לא כן עשו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_31","025_48_31","JER","48","31","31","על כן על מואב איליל ולמואב כלה אזעק אל אנשי קיר חרש יהגה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_32","025_48_32","JER","48","32","32","מבכי יעזר אבכה לך הגפן שבמה נטישתיך עברו ים עד ים יעזר נגעו על קיצך ועל בצירך שדד נפל׃ ");
INSERT INTO heb_vpl VALUES ("JR48_33","025_48_33","JER","48","33","33","ונאספה שמחה וגיל מכרמל ומארץ מואב ויין מיקבים השבתי לא ידרך הידד הידד לא הידד׃ ");
INSERT INTO heb_vpl VALUES ("JR48_34","025_48_34","JER","48","34","34","מזעקת חשבון עד אלעלה עד יהץ נתנו קולם מצער עד חרנים עגלת שלשיה כי גם מי נמרים למשמות יהיו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_35","025_48_35","JER","48","35","35","והשבתי למואב נאם יהוה מעלה במה ומקטיר לאלהיו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_36","025_48_36","JER","48","36","36","על כן לבי למואב כחללים יהמה ולבי אל אנשי קיר חרש כחלילים יהמה על כן יתרת עשה אבדו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_37","025_48_37","JER","48","37","37","כי כל ראש קרחה וכל זקן גרעה על כל ידים גדדת ועל מתנים שק׃ ");
INSERT INTO heb_vpl VALUES ("JR48_38","025_48_38","JER","48","38","38","על כל גגות מואב וברחבתיה כלה מספד כי שברתי את מואב ככלי אין חפץ בו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_39","025_48_39","JER","48","39","39","איך חתה הילילו איך הפנה ערף מואב בוש והיה מואב לשחק ולמחתה לכל סביביו׃ ");
INSERT INTO heb_vpl VALUES ("JR48_40","025_48_40","JER","48","40","40","כי כה אמר יהוה הנה כנשר ידאה ופרש כנפיו אל מואב׃ ");
INSERT INTO heb_vpl VALUES ("JR48_41","025_48_41","JER","48","41","41","נלכדה הקריות והמצדות נתפשה והיה לב גבורי מואב ביום ההוא כלב אשה מצרה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_42","025_48_42","JER","48","42","42","ונשמד מואב מעם כי על יהוה הגדיל׃ ");
INSERT INTO heb_vpl VALUES ("JR48_43","025_48_43","JER","48","43","43","פחד ופחת ופח עליך יושב מואב נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_44","025_48_44","JER","48","44","44","הניס מפני הפחד יפל אל הפחת והעלה מן הפחת ילכד בפח כי אביא אליה אל מואב שנת פקדתם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_45","025_48_45","JER","48","45","45","בצל חשבון עמדו מכח נסים כי אש יצא מחשבון ולהבה מבין סיחון ותאכל פאת מואב וקדקד בני שאון׃ ");
INSERT INTO heb_vpl VALUES ("JR48_46","025_48_46","JER","48","46","46","אוי לך מואב אבד עם כמוש כי לקחו בניך בשבי ובנתיך בשביה׃ ");
INSERT INTO heb_vpl VALUES ("JR48_47","025_48_47","JER","48","47","47","ושבתי שבות מואב באחרית הימים נאם יהוה עד הנה משפט מואב׃ ");
INSERT INTO heb_vpl VALUES ("JR49_1","025_49_1","JER","49","1","1","לבני עמון כה אמר יהוה הבנים אין לישראל אם יורש אין לו מדוע ירש מלכם את גד ועמו בעריו ישב׃ ");
INSERT INTO heb_vpl VALUES ("JR49_2","025_49_2","JER","49","2","2","לכן הנה ימים באים נאם יהוה והשמעתי אל רבת בני עמון תרועת מלחמה והיתה לתל שממה ובנתיה באש תצתנה וירש ישראל את ירשיו אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_3","025_49_3","JER","49","3","3","הילילי חשבון כי שדדה עי צעקנה בנות רבה חגרנה שקים ספדנה והתשוטטנה בגדרות כי מלכם בגולה ילך כהניו ושריו יחדיו׃ ");
INSERT INTO heb_vpl VALUES ("JR49_4","025_49_4","JER","49","4","4","מה תתהללי בעמקים זב עמקך הבת השובבה הבטחה באצרתיה מי יבוא אלי׃ ");
INSERT INTO heb_vpl VALUES ("JR49_5","025_49_5","JER","49","5","5","הנני מביא עליך פחד נאם אדני יהוה צבאות מכל סביביך ונדחתם איש לפניו ואין מקבץ לנדד׃ ");
INSERT INTO heb_vpl VALUES ("JR49_6","025_49_6","JER","49","6","6","ואחרי כן אשיב את שבות בני עמון נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_7","025_49_7","JER","49","7","7","לאדום כה אמר יהוה צבאות האין עוד חכמה בתימן אבדה עצה מבנים נסרחה חכמתם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_8","025_49_8","JER","49","8","8","נסו הפנו העמיקו לשבת ישבי דדן כי איד עשו הבאתי עליו עת פקדתיו׃ ");
INSERT INTO heb_vpl VALUES ("JR49_9","025_49_9","JER","49","9","9","אם בצרים באו לך לא ישארו עוללות אם גנבים בלילה השחיתו דים׃ ");
INSERT INTO heb_vpl VALUES ("JR49_10","025_49_10","JER","49","10","10","כי אני חשפתי את עשו גליתי את מסתריו ונחבה לא יוכל שדד זרעו ואחיו ושכניו ואיננו׃ ");
INSERT INTO heb_vpl VALUES ("JR49_11","025_49_11","JER","49","11","11","עזבה יתמיך אני אחיה ואלמנתיך עלי תבטחו׃ ");
INSERT INTO heb_vpl VALUES ("JR49_12","025_49_12","JER","49","12","12","כי כה אמר יהוה הנה אשר אין משפטם לשתות הכוס שתו ישתו ואתה הוא נקה תנקה לא תנקה כי שתה תשתה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_13","025_49_13","JER","49","13","13","כי בי נשבעתי נאם יהוה כי לשמה לחרפה לחרב ולקללה תהיה בצרה וכל עריה תהיינה לחרבות עולם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_14","025_49_14","JER","49","14","14","שמועה שמעתי מאת יהוה וציר בגוים שלוח התקבצו ובאו עליה וקומו למלחמה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_15","025_49_15","JER","49","15","15","כי הנה קטן נתתיך בגוים בזוי באדם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_16","025_49_16","JER","49","16","16","תפלצתך השיא אתך זדון לבך שכני בחגוי הסלע תפשי מרום גבעה כי תגביה כנשר קנך משם אורידך נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_17","025_49_17","JER","49","17","17","והיתה אדום לשמה כל עבר עליה ישם וישרק על כל מכותה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_18","025_49_18","JER","49","18","18","כמהפכת סדם ועמרה ושכניה אמר יהוה לא ישב שם איש ולא יגור בה בן אדם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_19","025_49_19","JER","49","19","19","הנה כאריה יעלה מגאון הירדן אל נוה איתן כי ארגיעה אריצנו מעליה ומי בחור אליה אפקד כי מי כמוני ומי יעידני ומי זה רעה אשר יעמד לפני׃ ");
INSERT INTO heb_vpl VALUES ("JR49_20","025_49_20","JER","49","20","20","לכן שמעו עצת יהוה אשר יעץ אל אדום ומחשבותיו אשר חשב אל ישבי תימן אם לא יסחבום צעירי הצאן אם לא ישים עליהם נוהם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_21","025_49_21","JER","49","21","21","מקול נפלם רעשה הארץ צעקה בים סוף נשמע קולה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_22","025_49_22","JER","49","22","22","הנה כנשר יעלה וידאה ויפרש כנפיו על בצרה והיה לב גבורי אדום ביום ההוא כלב אשה מצרה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_23","025_49_23","JER","49","23","23","לדמשק בושה חמת וארפד כי שמעה רעה שמעו נמגו בים דאגה השקט לא יוכל׃ ");
INSERT INTO heb_vpl VALUES ("JR49_24","025_49_24","JER","49","24","24","רפתה דמשק הפנתה לנוס ורטט החזיקה צרה וחבלים אחזתה כיולדה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_25","025_49_25","JER","49","25","25","איך לא עזבה עיר תהלה קרית משושי׃ ");
INSERT INTO heb_vpl VALUES ("JR49_26","025_49_26","JER","49","26","26","לכן יפלו בחוריה ברחבתיה וכל אנשי המלחמה ידמו ביום ההוא נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("JR49_27","025_49_27","JER","49","27","27","והצתי אש בחומת דמשק ואכלה ארמנות בן הדד׃ ");
INSERT INTO heb_vpl VALUES ("JR49_28","025_49_28","JER","49","28","28","לקדר ולממלכות חצור אשר הכה נבוכדראצור מלך בבל כה אמר יהוה קומו עלו אל קדר ושדדו את בני קדם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_29","025_49_29","JER","49","29","29","אהליהם וצאנם יקחו יריעותיהם וכל כליהם וגמליהם ישאו להם וקראו עליהם מגור מסביב׃ ");
INSERT INTO heb_vpl VALUES ("JR49_30","025_49_30","JER","49","30","30","נסו נדו מאד העמיקו לשבת ישבי חצור נאם יהוה כי יעץ עליכם נבוכדראצר מלך בבל עצה וחשב עליהם מחשבה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_31","025_49_31","JER","49","31","31","קומו עלו אל גוי שליו יושב לבטח נאם יהוה לא דלתים ולא בריח לו בדד ישכנו׃ ");
INSERT INTO heb_vpl VALUES ("JR49_32","025_49_32","JER","49","32","32","והיו גמליהם לבז והמון מקניהם לשלל וזרתים לכל רוח קצוצי פאה ומכל עבריו אביא את אידם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_33","025_49_33","JER","49","33","33","והיתה חצור למעון תנים שממה עד עולם לא ישב שם איש ולא יגור בה בן אדם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_34","025_49_34","JER","49","34","34","אשר היה דבר יהוה אל ירמיהו הנביא אל עילם בראשית מלכות צדקיה מלך יהודה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JR49_35","025_49_35","JER","49","35","35","כה אמר יהוה צבאות הנני שבר את קשת עילם ראשית גבורתם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_36","025_49_36","JER","49","36","36","והבאתי אל עילם ארבע רוחות מארבע קצות השמים וזרתים לכל הרחות האלה ולא יהיה הגוי אשר לא יבוא שם נדחי עולם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_37","025_49_37","JER","49","37","37","והחתתי את עילם לפני איביהם ולפני מבקשי נפשם והבאתי עליהם רעה את חרון אפי נאם יהוה ושלחתי אחריהם את החרב עד כלותי אותם׃ ");
INSERT INTO heb_vpl VALUES ("JR49_38","025_49_38","JER","49","38","38","ושמתי כסאי בעילם והאבדתי משם מלך ושרים נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR49_39","025_49_39","JER","49","39","39","והיה באחרית הימים אשוב את שבית עילם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_1","025_50_1","JER","50","1","1","הדבר אשר דבר יהוה אל בבל אל ארץ כשדים ביד ירמיהו הנביא׃ ");
INSERT INTO heb_vpl VALUES ("JR50_2","025_50_2","JER","50","2","2","הגידו בגוים והשמיעו ושאו נס השמיעו אל תכחדו אמרו נלכדה בבל הביש בל חת מרדך הבישו עצביה חתו גלוליה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_3","025_50_3","JER","50","3","3","כי עלה עליה גוי מצפון הוא ישית את ארצה לשמה ולא יהיה יושב בה מאדם ועד בהמה נדו הלכו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_4","025_50_4","JER","50","4","4","בימים ההמה ובעת ההיא נאם יהוה יבאו בני ישראל המה ובני יהודה יחדו הלוך ובכו ילכו ואת יהוה אלהיהם יבקשו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_5","025_50_5","JER","50","5","5","ציון ישאלו דרך הנה פניהם באו ונלוו אל יהוה ברית עולם לא תשכח׃ ");
INSERT INTO heb_vpl VALUES ("JR50_6","025_50_6","JER","50","6","6","צאן אבדות היה עמי רעיהם התעום הרים שובבים מהר אל גבעה הלכו שכחו רבצם׃ ");
INSERT INTO heb_vpl VALUES ("JR50_7","025_50_7","JER","50","7","7","כל מוצאיהם אכלום וצריהם אמרו לא נאשם תחת אשר חטאו ליהוה נוה צדק ומקוה אבותיהם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_8","025_50_8","JER","50","8","8","נדו מתוך בבל ומארץ כשדים יצאו והיו כעתודים לפני צאן׃ ");
INSERT INTO heb_vpl VALUES ("JR50_9","025_50_9","JER","50","9","9","כי הנה אנכי מעיר ומעלה על בבל קהל גוים גדלים מארץ צפון וערכו לה משם תלכד חציו כגבור משכיל לא ישוב ריקם׃ ");
INSERT INTO heb_vpl VALUES ("JR50_10","025_50_10","JER","50","10","10","והיתה כשדים לשלל כל שלליה ישבעו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_11","025_50_11","JER","50","11","11","כי תשמחי כי תעלזי שסי נחלתי כי תפושי כעגלה דשה ותצהלי כאברים׃ ");
INSERT INTO heb_vpl VALUES ("JR50_12","025_50_12","JER","50","12","12","בושה אמכם מאד חפרה יולדתכם הנה אחרית גוים מדבר ציה וערבה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_13","025_50_13","JER","50","13","13","מקצף יהוה לא תשב והיתה שממה כלה כל עבר על בבל ישם וישרק על כל מכותיה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_14","025_50_14","JER","50","14","14","ערכו על בבל סביב כל דרכי קשת ידו אליה אל תחמלו אל חץ כי ליהוה חטאה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_15","025_50_15","JER","50","15","15","הריעו עליה סביב נתנה ידה נפלו אשויתיה נהרסו חומותיה כי נקמת יהוה היא הנקמו בה כאשר עשתה עשו לה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_16","025_50_16","JER","50","16","16","כרתו זורע מבבל ותפש מגל בעת קציר מפני חרב היונה איש אל עמו יפנו ואיש לארצו ינסו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_17","025_50_17","JER","50","17","17","שה פזורה ישראל אריות הדיחו הראשון אכלו מלך אשור וזה האחרון עצמו נבוכדראצר מלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR50_18","025_50_18","JER","50","18","18","לכן כה אמר יהוה צבאות אלהי ישראל הנני פקד אל מלך בבל ואל ארצו כאשר פקדתי אל מלך אשור׃ ");
INSERT INTO heb_vpl VALUES ("JR50_19","025_50_19","JER","50","19","19","ושבבתי את ישראל אל נוהו ורעה הכרמל והבשן ובהר אפרים והגלעד תשבע נפשו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_20","025_50_20","JER","50","20","20","בימים ההם ובעת ההיא נאם יהוה יבקש את עון ישראל ואיננו ואת חטאת יהודה ולא תמצאינה כי אסלח לאשר אשאיר׃ ");
INSERT INTO heb_vpl VALUES ("JR50_21","025_50_21","JER","50","21","21","על הארץ מרתים עלה עליה ואל יושבי פקוד חרב והחרם אחריהם נאם יהוה ועשה ככל אשר צויתיך׃ ");
INSERT INTO heb_vpl VALUES ("JR50_22","025_50_22","JER","50","22","22","קול מלחמה בארץ ושבר גדול׃ ");
INSERT INTO heb_vpl VALUES ("JR50_23","025_50_23","JER","50","23","23","איך נגדע וישבר פטיש כל הארץ איך היתה לשמה בבל בגוים׃ ");
INSERT INTO heb_vpl VALUES ("JR50_24","025_50_24","JER","50","24","24","יקשתי לך וגם נלכדת בבל ואת לא ידעת נמצאת וגם נתפשת כי ביהוה התגרית׃ ");
INSERT INTO heb_vpl VALUES ("JR50_25","025_50_25","JER","50","25","25","פתח יהוה את אוצרו ויוצא את כלי זעמו כי מלאכה היא לאדני יהוה צבאות בארץ כשדים׃ ");
INSERT INTO heb_vpl VALUES ("JR50_26","025_50_26","JER","50","26","26","באו לה מקץ פתחו מאבסיה סלוה כמו ערמים והחרימוה אל תהי לה שארית׃ ");
INSERT INTO heb_vpl VALUES ("JR50_27","025_50_27","JER","50","27","27","חרבו כל פריה ירדו לטבח הוי עליהם כי בא יומם עת פקדתם׃ ");
INSERT INTO heb_vpl VALUES ("JR50_28","025_50_28","JER","50","28","28","קול נסים ופלטים מארץ בבל להגיד בציון את נקמת יהוה אלהינו נקמת היכלו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_29","025_50_29","JER","50","29","29","השמיעו אל בבל רבים כל דרכי קשת חנו עליה סביב אל יהי פליטה שלמו לה כפעלה ככל אשר עשתה עשו לה כי אל יהוה זדה אל קדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR50_30","025_50_30","JER","50","30","30","לכן יפלו בחוריה ברחבתיה וכל אנשי מלחמתה ידמו ביום ההוא נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_31","025_50_31","JER","50","31","31","הנני אליך זדון נאם אדני יהוה צבאות כי בא יומך עת פקדתיך׃ ");
INSERT INTO heb_vpl VALUES ("JR50_32","025_50_32","JER","50","32","32","וכשל זדון ונפל ואין לו מקים והצתי אש בעריו ואכלה כל סביבתיו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_33","025_50_33","JER","50","33","33","כה אמר יהוה צבאות עשוקים בני ישראל ובני יהודה יחדו וכל שביהם החזיקו בם מאנו שלחם׃ ");
INSERT INTO heb_vpl VALUES ("JR50_34","025_50_34","JER","50","34","34","גאלם חזק יהוה צבאות שמו ריב יריב את ריבם למען הרגיע את הארץ והרגיז לישבי בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR50_35","025_50_35","JER","50","35","35","חרב על כשדים נאם יהוה ואל ישבי בבל ואל שריה ואל חכמיה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_36","025_50_36","JER","50","36","36","חרב אל הבדים ונאלו חרב אל גבוריה וחתו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_37","025_50_37","JER","50","37","37","חרב אל סוסיו ואל רכבו ואל כל הערב אשר בתוכה והיו לנשים חרב אל אוצרתיה ובזזו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_38","025_50_38","JER","50","38","38","חרב אל מימיה ויבשו כי ארץ פסלים היא ובאימים יתהללו׃ ");
INSERT INTO heb_vpl VALUES ("JR50_39","025_50_39","JER","50","39","39","לכן ישבו ציים את איים וישבו בה בנות יענה ולא תשב עוד לנצח ולא תשכון עד דור ודור׃ ");
INSERT INTO heb_vpl VALUES ("JR50_40","025_50_40","JER","50","40","40","כמהפכת אלהים את סדם ואת עמרה ואת שכניה נאם יהוה לא ישב שם איש ולא יגור בה בן אדם׃ ");
INSERT INTO heb_vpl VALUES ("JR50_41","025_50_41","JER","50","41","41","הנה עם בא מצפון וגוי גדול ומלכים רבים יערו מירכתי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR50_42","025_50_42","JER","50","42","42","קשת וכידן יחזיקו אכזרי המה ולא ירחמו קולם כים יהמה ועל סוסים ירכבו ערוך כאיש למלחמה עליך בת בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR50_43","025_50_43","JER","50","43","43","שמע מלך בבל את שמעם ורפו ידיו צרה החזיקתהו חיל כיולדה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_44","025_50_44","JER","50","44","44","הנה כאריה יעלה מגאון הירדן אל נוה איתן כי ארגעה ארוצם מעליה ומי בחור אליה אפקד כי מי כמוני ומי יועדני ומי זה רעה אשר יעמד לפני׃ ");
INSERT INTO heb_vpl VALUES ("JR50_45","025_50_45","JER","50","45","45","לכן שמעו עצת יהוה אשר יעץ אל בבל ומחשבותיו אשר חשב אל ארץ כשדים אם לא יסחבום צעירי הצאן אם לא ישים עליהם נוה׃ ");
INSERT INTO heb_vpl VALUES ("JR50_46","025_50_46","JER","50","46","46","מקול נתפשה בבל נרעשה הארץ וזעקה בגוים נשמע׃ ");
INSERT INTO heb_vpl VALUES ("JR51_1","025_51_1","JER","51","1","1","כה אמר יהוה הנני מעיר על בבל ואל ישבי לב קמי רוח משחית׃ ");
INSERT INTO heb_vpl VALUES ("JR51_2","025_51_2","JER","51","2","2","ושלחתי לבבל זרים וזרוה ויבקקו את ארצה כי היו עליה מסביב ביום רעה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_3","025_51_3","JER","51","3","3","אל ידרך ידרך הדרך קשתו ואל יתעל בסרינו ואל תחמלו אל בחריה החרימו כל צבאה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_4","025_51_4","JER","51","4","4","ונפלו חללים בארץ כשדים ומדקרים בחוצותיה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_5","025_51_5","JER","51","5","5","כי לא אלמן ישראל ויהודה מאלהיו מיהוה צבאות כי ארצם מלאה אשם מקדוש ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JR51_6","025_51_6","JER","51","6","6","נסו מתוך בבל ומלטו איש נפשו אל תדמו בעונה כי עת נקמה היא ליהוה גמול הוא משלם לה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_7","025_51_7","JER","51","7","7","כוס זהב בבל ביד יהוה משכרת כל הארץ מיינה שתו גוים על כן יתהללו גוים׃ ");
INSERT INTO heb_vpl VALUES ("JR51_8","025_51_8","JER","51","8","8","פתאם נפלה בבל ותשבר הילילו עליה קחו צרי למכאובה אולי תרפא׃ ");
INSERT INTO heb_vpl VALUES ("JR51_9","025_51_9","JER","51","9","9","רפאנו את בבל ולא נרפתה עזבוה ונלך איש לארצו כי נגע אל השמים משפטה ונשא עד שחקים׃ ");
INSERT INTO heb_vpl VALUES ("JR51_10","025_51_10","JER","51","10","10","הוציא יהוה את צדקתינו באו ונספרה בציון את מעשה יהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_11","025_51_11","JER","51","11","11","הברו החצים מלאו השלטים העיר יהוה את רוח מלכי מדי כי על בבל מזמתו להשחיתה כי נקמת יהוה היא נקמת היכלו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_12","025_51_12","JER","51","12","12","אל חומת בבל שאו נס החזיקו המשמר הקימו שמרים הכינו הארבים כי גם זמם יהוה גם עשה את אשר דבר אל ישבי בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR51_13","025_51_13","JER","51","13","13","שכנתי על מים רבים רבת אוצרת בא קצך אמת בצעך׃ ");
INSERT INTO heb_vpl VALUES ("JR51_14","025_51_14","JER","51","14","14","נשבע יהוה צבאות בנפשו כי אם מלאתיך אדם כילק וענו עליך הידד׃ ");
INSERT INTO heb_vpl VALUES ("JR51_15","025_51_15","JER","51","15","15","עשה ארץ בכחו מכין תבל בחכמתו ובתבונתו נטה שמים׃ ");
INSERT INTO heb_vpl VALUES ("JR51_16","025_51_16","JER","51","16","16","לקול תתו המון מים בשמים ויעל נשאים מקצה ארץ ברקים למטר עשה ויוצא רוח מאצרתיו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_17","025_51_17","JER","51","17","17","נבער כל אדם מדעת הביש כל צרף מפסל כי שקר נסכו ולא רוח בם׃ ");
INSERT INTO heb_vpl VALUES ("JR51_18","025_51_18","JER","51","18","18","הבל המה מעשה תעתעים בעת פקדתם יאבדו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_19","025_51_19","JER","51","19","19","לא כאלה חלק יעקוב כי יוצר הכל הוא ושבט נחלתו יהוה צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_20","025_51_20","JER","51","20","20","מפץ אתה לי כלי מלחמה ונפצתי בך גוים והשחתי בך ממלכות׃ ");
INSERT INTO heb_vpl VALUES ("JR51_21","025_51_21","JER","51","21","21","ונפצתי בך סוס ורכבו ונפצתי בך רכב ורכבו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_22","025_51_22","JER","51","22","22","ונפצתי בך איש ואשה ונפצתי בך זקן ונער ונפצתי בך בחור ובתולה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_23","025_51_23","JER","51","23","23","ונפצתי בך רעה ועדרו ונפצתי בך אכר וצמדו ונפצתי בך פחות וסגנים׃ ");
INSERT INTO heb_vpl VALUES ("JR51_24","025_51_24","JER","51","24","24","ושלמתי לבבל ולכל יושבי כשדים את כל רעתם אשר עשו בציון לעיניכם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_25","025_51_25","JER","51","25","25","הנני אליך הר המשחית נאם יהוה המשחית את כל הארץ ונטיתי את ידי עליך וגלגלתיך מן הסלעים ונתתיך להר שרפה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_26","025_51_26","JER","51","26","26","ולא יקחו ממך אבן לפנה ואבן למוסדות כי שממות עולם תהיה נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_27","025_51_27","JER","51","27","27","שאו נס בארץ תקעו שופר בגוים קדשו עליה גוים השמיעו עליה ממלכות אררט מני ואשכנז פקדו עליה טפסר העלו סוס כילק סמר׃ ");
INSERT INTO heb_vpl VALUES ("JR51_28","025_51_28","JER","51","28","28","קדשו עליה גוים את מלכי מדי את פחותיה ואת כל סגניה ואת כל ארץ ממשלתו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_29","025_51_29","JER","51","29","29","ותרעש הארץ ותחל כי קמה על בבל מחשבות יהוה לשום את ארץ בבל לשמה מאין יושב׃ ");
INSERT INTO heb_vpl VALUES ("JR51_30","025_51_30","JER","51","30","30","חדלו גבורי בבל להלחם ישבו במצדות נשתה גבורתם היו לנשים הציתו משכנתיה נשברו בריחיה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_31","025_51_31","JER","51","31","31","רץ לקראת רץ ירוץ ומגיד לקראת מגיד להגיד למלך בבל כי נלכדה עירו מקצה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_32","025_51_32","JER","51","32","32","והמעברות נתפשו ואת האגמים שרפו באש ואנשי המלחמה נבהלו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_33","025_51_33","JER","51","33","33","כי כה אמר יהוה צבאות אלהי ישראל בת בבל כגרן עת הדריכה עוד מעט ובאה עת הקציר לה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_34","025_51_34","JER","51","34","34","אכלנו הממנו נבוכדראצר מלך בבל הציגנו כלי ריק בלענו כתנין מלא כרשו מעדני הדיחנו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_35","025_51_35","JER","51","35","35","חמסי ושארי על בבל תאמר ישבת ציון ודמי אל ישבי כשדים תאמר ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR51_36","025_51_36","JER","51","36","36","לכן כה אמר יהוה הנני רב את ריבך ונקמתי את נקמתך והחרבתי את ימה והבשתי את מקורה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_37","025_51_37","JER","51","37","37","והיתה בבל לגלים מעון תנים שמה ושרקה מאין יושב׃ ");
INSERT INTO heb_vpl VALUES ("JR51_38","025_51_38","JER","51","38","38","יחדו ככפרים ישאגו נערו כגורי אריות׃ ");
INSERT INTO heb_vpl VALUES ("JR51_39","025_51_39","JER","51","39","39","בחמם אשית את משתיהם והשכרתים למען יעלזו וישנו שנת עולם ולא יקיצו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_40","025_51_40","JER","51","40","40","אורידם ככרים לטבוח כאילים עם עתודים׃ ");
INSERT INTO heb_vpl VALUES ("JR51_41","025_51_41","JER","51","41","41","איך נלכדה ששך ותתפש תהלת כל הארץ איך היתה לשמה בבל בגוים׃ ");
INSERT INTO heb_vpl VALUES ("JR51_42","025_51_42","JER","51","42","42","עלה על בבל הים בהמון גליו נכסתה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_43","025_51_43","JER","51","43","43","היו עריה לשמה ארץ ציה וערבה ארץ לא ישב בהן כל איש ולא יעבר בהן בן אדם׃ ");
INSERT INTO heb_vpl VALUES ("JR51_44","025_51_44","JER","51","44","44","ופקדתי על בל בבבל והצאתי את בלעו מפיו ולא ינהרו אליו עוד גוים גם חומת בבל נפלה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_45","025_51_45","JER","51","45","45","צאו מתוכה עמי ומלטו איש את נפשו מחרון אף יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_46","025_51_46","JER","51","46","46","ופן ירך לבבכם ותיראו בשמועה הנשמעת בארץ ובא בשנה השמועה ואחריו בשנה השמועה וחמס בארץ ומשל על משל׃ ");
INSERT INTO heb_vpl VALUES ("JR51_47","025_51_47","JER","51","47","47","לכן הנה ימים באים ופקדתי על פסילי בבל וכל ארצה תבוש וכל חלליה יפלו בתוכה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_48","025_51_48","JER","51","48","48","ורננו על בבל שמים וארץ וכל אשר בהם כי מצפון יבוא לה השודדים נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_49","025_51_49","JER","51","49","49","גם בבל לנפל חללי ישראל גם לבבל נפלו חללי כל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR51_50","025_51_50","JER","51","50","50","פלטים מחרב הלכו אל תעמדו זכרו מרחוק את יהוה וירושלם תעלה על לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("JR51_51","025_51_51","JER","51","51","51","בשנו כי שמענו חרפה כסתה כלמה פנינו כי באו זרים על מקדשי בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_52","025_51_52","JER","51","52","52","לכן הנה ימים באים נאם יהוה ופקדתי על פסיליה ובכל ארצה יאנק חלל׃ ");
INSERT INTO heb_vpl VALUES ("JR51_53","025_51_53","JER","51","53","53","כי תעלה בבל השמים וכי תבצר מרום עזה מאתי יבאו שדדים לה נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_54","025_51_54","JER","51","54","54","קול זעקה מבבל ושבר גדול מארץ כשדים׃ ");
INSERT INTO heb_vpl VALUES ("JR51_55","025_51_55","JER","51","55","55","כי שדד יהוה את בבל ואבד ממנה קול גדול והמו גליהם כמים רבים נתן שאון קולם׃ ");
INSERT INTO heb_vpl VALUES ("JR51_56","025_51_56","JER","51","56","56","כי בא עליה על בבל שודד ונלכדו גבוריה חתתה קשתותם כי אל גמלות יהוה שלם ישלם׃ ");
INSERT INTO heb_vpl VALUES ("JR51_57","025_51_57","JER","51","57","57","והשכרתי שריה וחכמיה פחותיה וסגניה וגבוריה וישנו שנת עולם ולא יקיצו נאם המלך יהוה צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_58","025_51_58","JER","51","58","58","כה אמר יהוה צבאות חמות בבל הרחבה ערער תתערער ושעריה הגבהים באש יצתו ויגעו עמים בדי ריק ולאמים בדי אש ויעפו׃ ");
INSERT INTO heb_vpl VALUES ("JR51_59","025_51_59","JER","51","59","59","הדבר אשר צוה ירמיהו הנביא את שריה בן נריה בן מחסיה בלכתו את צדקיהו מלך יהודה בבל בשנת הרבעית למלכו ושריה שר מנוחה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_60","025_51_60","JER","51","60","60","ויכתב ירמיהו את כל הרעה אשר תבוא אל בבל אל ספר אחד את כל הדברים האלה הכתבים אל בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR51_61","025_51_61","JER","51","61","61","ויאמר ירמיהו אל שריה כבאך בבל וראית וקראת את כל הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_62","025_51_62","JER","51","62","62","ואמרת יהוה אתה דברת אל המקום הזה להכריתו לבלתי היות בו יושב למאדם ועד בהמה כי שממות עולם תהיה׃ ");
INSERT INTO heb_vpl VALUES ("JR51_63","025_51_63","JER","51","63","63","והיה ככלתך לקרא את הספר הזה תקשר עליו אבן והשלכתו אל תוך פרת׃ ");
INSERT INTO heb_vpl VALUES ("JR51_64","025_51_64","JER","51","64","64","ואמרת ככה תשקע בבל ולא תקום מפני הרעה אשר אנכי מביא עליה ויעפו עד הנה דברי ירמיהו׃ ");
INSERT INTO heb_vpl VALUES ("JR52_1","025_52_1","JER","52","1","1","בן עשרים ואחת שנה צדקיהו במלכו ואחת עשרה שנה מלך בירושלם ושם אמו חמיטל בת ירמיהו מלבנה׃ ");
INSERT INTO heb_vpl VALUES ("JR52_2","025_52_2","JER","52","2","2","ויעש הרע בעיני יהוה ככל אשר עשה יהויקים׃ ");
INSERT INTO heb_vpl VALUES ("JR52_3","025_52_3","JER","52","3","3","כי על אף יהוה היתה בירושלם ויהודה עד השליכו אותם מעל פניו וימרד צדקיהו במלך בבל׃ ");
INSERT INTO heb_vpl VALUES ("JR52_4","025_52_4","JER","52","4","4","ויהי בשנה התשעית למלכו בחדש העשירי בעשור לחדש בא נבוכדראצר מלך בבל הוא וכל חילו על ירושלם ויחנו עליה ויבנו עליה דיק סביב׃ ");
INSERT INTO heb_vpl VALUES ("JR52_5","025_52_5","JER","52","5","5","ותבא העיר במצור עד עשתי עשרה שנה למלך צדקיהו׃ ");
INSERT INTO heb_vpl VALUES ("JR52_6","025_52_6","JER","52","6","6","בחדש הרביעי בתשעה לחדש ויחזק הרעב בעיר ולא היה לחם לעם הארץ׃ ");
INSERT INTO heb_vpl VALUES ("JR52_7","025_52_7","JER","52","7","7","ותבקע העיר וכל אנשי המלחמה יברחו ויצאו מהעיר לילה דרך שער בין החמתים אשר על גן המלך וכשדים על העיר סביב וילכו דרך הערבה׃ ");
INSERT INTO heb_vpl VALUES ("JR52_8","025_52_8","JER","52","8","8","וירדפו חיל כשדים אחרי המלך וישיגו את צדקיהו בערבת ירחו וכל חילו נפצו מעליו׃ ");
INSERT INTO heb_vpl VALUES ("JR52_9","025_52_9","JER","52","9","9","ויתפשו את המלך ויעלו אתו אל מלך בבל רבלתה בארץ חמת וידבר אתו משפטים׃ ");
INSERT INTO heb_vpl VALUES ("JR52_10","025_52_10","JER","52","10","10","וישחט מלך בבל את בני צדקיהו לעיניו וגם את כל שרי יהודה שחט ברבלתה׃ ");
INSERT INTO heb_vpl VALUES ("JR52_11","025_52_11","JER","52","11","11","ואת עיני צדקיהו עור ויאסרהו בנחשתים ויבאהו מלך בבל בבלה ויתנהו בבית הפקדת עד יום מותו׃ ");
INSERT INTO heb_vpl VALUES ("JR52_12","025_52_12","JER","52","12","12","ובחדש החמישי בעשור לחדש היא שנת תשע עשרה שנה למלך נבוכדראצר מלך בבל בא נבוזראדן רב טבחים עמד לפני מלך בבל בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("JR52_13","025_52_13","JER","52","13","13","וישרף את בית יהוה ואת בית המלך ואת כל בתי ירושלם ואת כל בית הגדול שרף באש׃ ");
INSERT INTO heb_vpl VALUES ("JR52_14","025_52_14","JER","52","14","14","ואת כל חמות ירושלם סביב נתצו כל חיל כשדים אשר את רב טבחים׃ ");
INSERT INTO heb_vpl VALUES ("JR52_15","025_52_15","JER","52","15","15","ומדלות העם ואת יתר העם הנשארים בעיר ואת הנפלים אשר נפלו אל מלך בבל ואת יתר האמון הגלה נבוזראדן רב טבחים׃ ");
INSERT INTO heb_vpl VALUES ("JR52_16","025_52_16","JER","52","16","16","ומדלות הארץ השאיר נבוזראדן רב טבחים לכרמים וליגבים׃ ");
INSERT INTO heb_vpl VALUES ("JR52_17","025_52_17","JER","52","17","17","ואת עמודי הנחשת אשר לבית יהוה ואת המכנות ואת ים הנחשת אשר בבית יהוה שברו כשדים וישאו את כל נחשתם בבלה׃ ");
INSERT INTO heb_vpl VALUES ("JR52_18","025_52_18","JER","52","18","18","ואת הסרות ואת היעים ואת המזמרות ואת המזרקת ואת הכפות ואת כל כלי הנחשת אשר ישרתו בהם לקחו׃ ");
INSERT INTO heb_vpl VALUES ("JR52_19","025_52_19","JER","52","19","19","ואת הספים ואת המחתות ואת המזרקות ואת הסירות ואת המנרות ואת הכפות ואת המנקיות אשר זהב זהב ואשר כסף כסף לקח רב טבחים׃ ");
INSERT INTO heb_vpl VALUES ("JR52_20","025_52_20","JER","52","20","20","העמודים שנים הים אחד והבקר שנים עשר נחשת אשר תחת המכנות אשר עשה המלך שלמה לבית יהוה לא היה משקל לנחשתם כל הכלים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JR52_21","025_52_21","JER","52","21","21","והעמודים שמנה עשרה אמה קומה העמד האחד וחוט שתים עשרה אמה יסבנו ועביו ארבע אצבעות נבוב׃ ");
INSERT INTO heb_vpl VALUES ("JR52_22","025_52_22","JER","52","22","22","וכתרת עליו נחשת וקומת הכתרת האחת חמש אמות ושבכה ורמונים על הכותרת סביב הכל נחשת וכאלה לעמוד השני ורמונים׃ ");
INSERT INTO heb_vpl VALUES ("JR52_23","025_52_23","JER","52","23","23","ויהיו הרמנים תשעים וששה רוחה כל הרמונים מאה על השבכה סביב׃ ");
INSERT INTO heb_vpl VALUES ("JR52_24","025_52_24","JER","52","24","24","ויקח רב טבחים את שריה כהן הראש ואת צפניה כהן המשנה ואת שלשת שמרי הסף׃ ");
INSERT INTO heb_vpl VALUES ("JR52_25","025_52_25","JER","52","25","25","ומן העיר לקח סריס אחד אשר היה פקיד על אנשי המלחמה ושבעה אנשים מראי פני המלך אשר נמצאו בעיר ואת ספר שר הצבא המצבא את עם הארץ וששים איש מעם הארץ הנמצאים בתוך העיר׃ ");
INSERT INTO heb_vpl VALUES ("JR52_26","025_52_26","JER","52","26","26","ויקח אותם נבוזראדן רב טבחים וילך אותם אל מלך בבל רבלתה׃ ");
INSERT INTO heb_vpl VALUES ("JR52_27","025_52_27","JER","52","27","27","ויכה אותם מלך בבל וימתם ברבלה בארץ חמת ויגל יהודה מעל אדמתו׃ ");
INSERT INTO heb_vpl VALUES ("JR52_28","025_52_28","JER","52","28","28","זה העם אשר הגלה נבוכדראצר בשנת שבע יהודים שלשת אלפים ועשרים ושלשה׃ ");
INSERT INTO heb_vpl VALUES ("JR52_29","025_52_29","JER","52","29","29","בשנת שמונה עשרה לנבוכדראצר מירושלם נפש שמנה מאות שלשים ושנים׃ ");
INSERT INTO heb_vpl VALUES ("JR52_30","025_52_30","JER","52","30","30","בשנת שלש ועשרים לנבוכדראצר הגלה נבוזראדן רב טבחים יהודים נפש שבע מאות ארבעים וחמשה כל נפש ארבעת אלפים ושש מאות׃ ");
INSERT INTO heb_vpl VALUES ("JR52_31","025_52_31","JER","52","31","31","ויהי בשלשים ושבע שנה לגלות יהויכן מלך יהודה בשנים עשר חדש בעשרים וחמשה לחדש נשא אויל מרדך מלך בבל בשנת מלכתו את ראש יהויכין מלך יהודה ויצא אותו מבית הכליא׃ ");
INSERT INTO heb_vpl VALUES ("JR52_32","025_52_32","JER","52","32","32","וידבר אתו טבות ויתן את כסאו ממעל לכסא מלכים אשר אתו בבבל׃ ");
INSERT INTO heb_vpl VALUES ("JR52_33","025_52_33","JER","52","33","33","ושנה את בגדי כלאו ואכל לחם לפניו תמיד כל ימי חיו׃ ");
INSERT INTO heb_vpl VALUES ("JR52_34","025_52_34","JER","52","34","34","וארחתו ארחת תמיד נתנה לו מאת מלך בבל דבר יום ביומו עד יום מותו כל ימי חייו׃ ");
INSERT INTO heb_vpl VALUES ("LM1_1","026_1_1","LAM","1","1","1","איכה ישבה בדד העיר רבתי עם היתה כאלמנה רבתי בגוים שרתי במדינות היתה למס׃ ");
INSERT INTO heb_vpl VALUES ("LM1_2","026_1_2","LAM","1","2","2","בכו תבכה בלילה ודמעתה על לחיה אין לה מנחם מכל אהביה כל רעיה בגדו בה היו לה לאיבים׃ ");
INSERT INTO heb_vpl VALUES ("LM1_3","026_1_3","LAM","1","3","3","גלתה יהודה מעני ומרב עבדה היא ישבה בגוים לא מצאה מנוח כל רדפיה השיגוה בין המצרים׃ ");
INSERT INTO heb_vpl VALUES ("LM1_4","026_1_4","LAM","1","4","4","דרכי ציון אבלות מבלי באי מועד כל שעריה שוממין כהניה נאנחים בתולתיה נוגות והיא מר לה׃ ");
INSERT INTO heb_vpl VALUES ("LM1_5","026_1_5","LAM","1","5","5","היו צריה לראש איביה שלו כי יהוה הוגה על רב פשעיה עולליה הלכו שבי לפני צר׃ ");
INSERT INTO heb_vpl VALUES ("LM1_6","026_1_6","LAM","1","6","6","ויצא מן בת ציון כל הדרה היו שריה כאילים לא מצאו מרעה וילכו בלא כח לפני רודף׃ ");
INSERT INTO heb_vpl VALUES ("LM1_7","026_1_7","LAM","1","7","7","זכרה ירושלם ימי עניה ומרודיה כל מחמדיה אשר היו מימי קדם בנפל עמה ביד צר ואין עוזר לה ראוה צרים שחקו על משבתה׃ ");
INSERT INTO heb_vpl VALUES ("LM1_8","026_1_8","LAM","1","8","8","חטא חטאה ירושלם על כן לנידה היתה כל מכבדיה הזילוה כי ראו ערותה גם היא נאנחה ותשב אחור׃ ");
INSERT INTO heb_vpl VALUES ("LM1_9","026_1_9","LAM","1","9","9","טמאתה בשוליה לא זכרה אחריתה ותרד פלאים אין מנחם לה ראה יהוה את עניי כי הגדיל אויב׃ ");
INSERT INTO heb_vpl VALUES ("LM1_10","026_1_10","LAM","1","10","10","ידו פרש צר על כל מחמדיה כי ראתה גוים באו מקדשה אשר צויתה לא יבאו בקהל לך׃ ");
INSERT INTO heb_vpl VALUES ("LM1_11","026_1_11","LAM","1","11","11","כל עמה נאנחים מבקשים לחם נתנו מחמודיהם באכל להשיב נפש ראה יהוה והביטה כי הייתי זוללה׃ ");
INSERT INTO heb_vpl VALUES ("LM1_12","026_1_12","LAM","1","12","12","לוא אליכם כל עברי דרך הביטו וראו אם יש מכאוב כמכאבי אשר עולל לי אשר הוגה יהוה ביום חרון אפו׃ ");
INSERT INTO heb_vpl VALUES ("LM1_13","026_1_13","LAM","1","13","13","ממרום שלח אש בעצמתי וירדנה פרש רשת לרגלי השיבני אחור נתנני שממה כל היום דוה׃ ");
INSERT INTO heb_vpl VALUES ("LM1_14","026_1_14","LAM","1","14","14","נשקד על פשעי בידו ישתרגו עלו על צוארי הכשיל כחי נתנני אדני בידי לא אוכל קום׃ ");
INSERT INTO heb_vpl VALUES ("LM1_15","026_1_15","LAM","1","15","15","סלה כל אבירי אדני בקרבי קרא עלי מועד לשבר בחורי גת דרך אדני לבתולת בת יהודה׃ ");
INSERT INTO heb_vpl VALUES ("LM1_16","026_1_16","LAM","1","16","16","על אלה אני בוכיה עיני עיני ירדה מים כי רחק ממני מנחם משיב נפשי היו בני שוממים כי גבר אויב׃ ");
INSERT INTO heb_vpl VALUES ("LM1_17","026_1_17","LAM","1","17","17","פרשה ציון בידיה אין מנחם לה צוה יהוה ליעקב סביביו צריו היתה ירושלם לנדה ביניהם׃ ");
INSERT INTO heb_vpl VALUES ("LM1_18","026_1_18","LAM","1","18","18","צדיק הוא יהוה כי פיהו מריתי שמעו נא כל עמים וראו מכאבי בתולתי ובחורי הלכו בשבי׃ ");
INSERT INTO heb_vpl VALUES ("LM1_19","026_1_19","LAM","1","19","19","קראתי למאהבי המה רמוני כהני וזקני בעיר גועו כי בקשו אכל למו וישיבו את נפשם׃ ");
INSERT INTO heb_vpl VALUES ("LM1_20","026_1_20","LAM","1","20","20","ראה יהוה כי צר לי מעי חמרמרו נהפך לבי בקרבי כי מרו מריתי מחוץ שכלה חרב בבית כמות׃ ");
INSERT INTO heb_vpl VALUES ("LM1_21","026_1_21","LAM","1","21","21","שמעו כי נאנחה אני אין מנחם לי כל איבי שמעו רעתי ששו כי אתה עשית הבאת יום קראת ויהיו כמוני׃ ");
INSERT INTO heb_vpl VALUES ("LM1_22","026_1_22","LAM","1","22","22","תבא כל רעתם לפניך ועולל למו כאשר עוללת לי על כל פשעי כי רבות אנחתי ולבי דוי׃ ");
INSERT INTO heb_vpl VALUES ("LM2_1","026_2_1","LAM","2","1","1","איכה יעיב באפו אדני את בת ציון השליך משמים ארץ תפארת ישראל ולא זכר הדם רגליו ביום אפו׃ ");
INSERT INTO heb_vpl VALUES ("LM2_2","026_2_2","LAM","2","2","2","בלע אדני לא חמל את כל נאות יעקב הרס בעברתו מבצרי בת יהודה הגיע לארץ חלל ממלכה ושריה׃ ");
INSERT INTO heb_vpl VALUES ("LM2_3","026_2_3","LAM","2","3","3","גדע בחרי אף כל קרן ישראל השיב אחור ימינו מפני אויב ויבער ביעקב כאש להבה אכלה סביב׃ ");
INSERT INTO heb_vpl VALUES ("LM2_4","026_2_4","LAM","2","4","4","דרך קשתו כאויב נצב ימינו כצר ויהרג כל מחמדי עין באהל בת ציון שפך כאש חמתו׃ ");
INSERT INTO heb_vpl VALUES ("LM2_5","026_2_5","LAM","2","5","5","היה אדני כאויב בלע ישראל בלע כל ארמנותיה שחת מבצריו וירב בבת יהודה תאניה ואניה׃ ");
INSERT INTO heb_vpl VALUES ("LM2_6","026_2_6","LAM","2","6","6","ויחמס כגן שכו שחת מועדו שכח יהוה בציון מועד ושבת וינאץ בזעם אפו מלך וכהן׃ ");
INSERT INTO heb_vpl VALUES ("LM2_7","026_2_7","LAM","2","7","7","זנח אדני מזבחו נאר מקדשו הסגיר ביד אויב חומת ארמנותיה קול נתנו בבית יהוה כיום מועד׃ ");
INSERT INTO heb_vpl VALUES ("LM2_8","026_2_8","LAM","2","8","8","חשב יהוה להשחית חומת בת ציון נטה קו לא השיב ידו מבלע ויאבל חל וחומה יחדו אמללו׃ ");
INSERT INTO heb_vpl VALUES ("LM2_9","026_2_9","LAM","2","9","9","טבעו בארץ שעריה אבד ושבר בריחיה מלכה ושריה בגוים אין תורה גם נביאיה לא מצאו חזון מיהוה׃ ");
INSERT INTO heb_vpl VALUES ("LM2_10","026_2_10","LAM","2","10","10","ישבו לארץ ידמו זקני בת ציון העלו עפר על ראשם חגרו שקים הורידו לארץ ראשן בתולת ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("LM2_11","026_2_11","LAM","2","11","11","כלו בדמעות עיני חמרמרו מעי נשפך לארץ כבדי על שבר בת עמי בעטף עולל ויונק ברחבות קריה׃ ");
INSERT INTO heb_vpl VALUES ("LM2_12","026_2_12","LAM","2","12","12","לאמתם יאמרו איה דגן ויין בהתעטפם כחלל ברחבות עיר בהשתפך נפשם אל חיק אמתם׃ ");
INSERT INTO heb_vpl VALUES ("LM2_13","026_2_13","LAM","2","13","13","מה אעודך מה אדמה לך הבת ירושלם מה אשוה לך ואנחמך בתולת בת ציון כי גדול כים שברך מי ירפא לך׃ ");
INSERT INTO heb_vpl VALUES ("LM2_14","026_2_14","LAM","2","14","14","נביאיך חזו לך שוא ותפל ולא גלו על עונך להשיב שביתך ויחזו לך משאות שוא ומדוחים׃ ");
INSERT INTO heb_vpl VALUES ("LM2_15","026_2_15","LAM","2","15","15","ספקו עליך כפים כל עברי דרך שרקו וינעו ראשם על בת ירושלם הזאת העיר שיאמרו כלילת יפי משוש לכל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("LM2_16","026_2_16","LAM","2","16","16","פצו עליך פיהם כל אויביך שרקו ויחרקו שן אמרו בלענו אך זה היום שקוינהו מצאנו ראינו׃ ");
INSERT INTO heb_vpl VALUES ("LM2_17","026_2_17","LAM","2","17","17","עשה יהוה אשר זמם בצע אמרתו אשר צוה מימי קדם הרס ולא חמל וישמח עליך אויב הרים קרן צריך׃ ");
INSERT INTO heb_vpl VALUES ("LM2_18","026_2_18","LAM","2","18","18","צעק לבם אל אדני חומת בת ציון הורידי כנחל דמעה יומם ולילה אל תתני פוגת לך אל תדם בת עינך׃ ");
INSERT INTO heb_vpl VALUES ("LM2_19","026_2_19","LAM","2","19","19","קומי רני בליל לראש אשמרות שפכי כמים לבך נכח פני אדני שאי אליו כפיך על נפש עולליך העטופים ברעב בראש כל חוצות׃ ");
INSERT INTO heb_vpl VALUES ("LM2_20","026_2_20","LAM","2","20","20","ראה יהוה והביטה למי עוללת כה אם תאכלנה נשים פרים עללי טפחים אם יהרג במקדש אדני כהן ונביא׃ ");
INSERT INTO heb_vpl VALUES ("LM2_21","026_2_21","LAM","2","21","21","שכבו לארץ חוצות נער וזקן בתולתי ובחורי נפלו בחרב הרגת ביום אפך טבחת לא חמלת׃ ");
INSERT INTO heb_vpl VALUES ("LM2_22","026_2_22","LAM","2","22","22","תקרא כיום מועד מגורי מסביב ולא היה ביום אף יהוה פליט ושריד אשר טפחתי ורביתי איבי כלם׃ ");
INSERT INTO heb_vpl VALUES ("LM3_1","026_3_1","LAM","3","1","1","אני הגבר ראה עני בשבט עברתו׃ ");
INSERT INTO heb_vpl VALUES ("LM3_2","026_3_2","LAM","3","2","2","אותי נהג וילך חשך ולא אור׃ ");
INSERT INTO heb_vpl VALUES ("LM3_3","026_3_3","LAM","3","3","3","אך בי ישב יהפך ידו כל היום׃ ");
INSERT INTO heb_vpl VALUES ("LM3_4","026_3_4","LAM","3","4","4","בלה בשרי ועורי שבר עצמותי׃ ");
INSERT INTO heb_vpl VALUES ("LM3_5","026_3_5","LAM","3","5","5","בנה עלי ויקף ראש ותלאה׃ ");
INSERT INTO heb_vpl VALUES ("LM3_6","026_3_6","LAM","3","6","6","במחשכים הושיבני כמתי עולם׃ ");
INSERT INTO heb_vpl VALUES ("LM3_7","026_3_7","LAM","3","7","7","גדר בעדי ולא אצא הכביד נחשתי׃ ");
INSERT INTO heb_vpl VALUES ("LM3_8","026_3_8","LAM","3","8","8","גם כי אזעק ואשוע שתם תפלתי׃ ");
INSERT INTO heb_vpl VALUES ("LM3_9","026_3_9","LAM","3","9","9","גדר דרכי בגזית נתיבתי עוה׃ ");
INSERT INTO heb_vpl VALUES ("LM3_10","026_3_10","LAM","3","10","10","דב ארב הוא לי אריה במסתרים׃ ");
INSERT INTO heb_vpl VALUES ("LM3_11","026_3_11","LAM","3","11","11","דרכי סורר ויפשחני שמני שמם׃ ");
INSERT INTO heb_vpl VALUES ("LM3_12","026_3_12","LAM","3","12","12","דרך קשתו ויציבני כמטרא לחץ׃ ");
INSERT INTO heb_vpl VALUES ("LM3_13","026_3_13","LAM","3","13","13","הביא בכליותי בני אשפתו׃ ");
INSERT INTO heb_vpl VALUES ("LM3_14","026_3_14","LAM","3","14","14","הייתי שחק לכל עמי נגינתם כל היום׃ ");
INSERT INTO heb_vpl VALUES ("LM3_15","026_3_15","LAM","3","15","15","השביעני במרורים הרוני לענה׃ ");
INSERT INTO heb_vpl VALUES ("LM3_16","026_3_16","LAM","3","16","16","ויגרס בחצץ שני הכפישני באפר׃ ");
INSERT INTO heb_vpl VALUES ("LM3_17","026_3_17","LAM","3","17","17","ותזנח משלום נפשי נשיתי טובה׃ ");
INSERT INTO heb_vpl VALUES ("LM3_18","026_3_18","LAM","3","18","18","ואמר אבד נצחי ותוחלתי מיהוה׃ ");
INSERT INTO heb_vpl VALUES ("LM3_19","026_3_19","LAM","3","19","19","זכר עניי ומרודי לענה וראש׃ ");
