INSERT INTO heb_vpl VALUES ("EK1_23","027_1_23","EZK","1","23","23","ותחת הרקיע כנפיהם ישרות אשה אל אחותה לאיש שתים מכסות להנה ולאיש שתים מכסות להנה את גויתיהם׃ ");
INSERT INTO heb_vpl VALUES ("EK1_24","027_1_24","EZK","1","24","24","ואשמע את קול כנפיהם כקול מים רבים כקול שדי בלכתם קול המלה כקול מחנה בעמדם תרפינה כנפיהן׃ ");
INSERT INTO heb_vpl VALUES ("EK1_25","027_1_25","EZK","1","25","25","ויהי קול מעל לרקיע אשר על ראשם בעמדם תרפינה כנפיהן׃ ");
INSERT INTO heb_vpl VALUES ("EK1_26","027_1_26","EZK","1","26","26","וממעל לרקיע אשר על ראשם כמראה אבן ספיר דמות כסא ועל דמות הכסא דמות כמראה אדם עליו מלמעלה׃ ");
INSERT INTO heb_vpl VALUES ("EK1_27","027_1_27","EZK","1","27","27","וארא כעין חשמל כמראה אש בית לה סביב ממראה מתניו ולמעלה וממראה מתניו ולמטה ראיתי כמראה אש ונגה לו סביב׃ ");
INSERT INTO heb_vpl VALUES ("EK1_28","027_1_28","EZK","1","28","28","כמראה הקשת אשר יהיה בענן ביום הגשם כן מראה הנגה סביב הוא מראה דמות כבוד יהוה ואראה ואפל על פני ואשמע קול מדבר׃ ");
INSERT INTO heb_vpl VALUES ("EK2_1","027_2_1","EZK","2","1","1","ויאמר אלי בן אדם עמד על רגליך ואדבר אתך׃ ");
INSERT INTO heb_vpl VALUES ("EK2_2","027_2_2","EZK","2","2","2","ותבא בי רוח כאשר דבר אלי ותעמדני על רגלי ואשמע את מדבר אלי׃ ");
INSERT INTO heb_vpl VALUES ("EK2_3","027_2_3","EZK","2","3","3","ויאמר אלי בן אדם שולח אני אותך אל בני ישראל אל גוים המורדים אשר מרדו בי המה ואבותם פשעו בי עד עצם היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("EK2_4","027_2_4","EZK","2","4","4","והבנים קשי פנים וחזקי לב אני שולח אותך אליהם ואמרת אליהם כה אמר אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK2_5","027_2_5","EZK","2","5","5","והמה אם ישמעו ואם יחדלו כי בית מרי המה וידעו כי נביא היה בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("EK2_6","027_2_6","EZK","2","6","6","ואתה בן אדם אל תירא מהם ומדבריהם אל תירא כי סרבים וסלונים אותך ואל עקרבים אתה יושב מדבריהם אל תירא ומפניהם אל תחת כי בית מרי המה׃ ");
INSERT INTO heb_vpl VALUES ("EK2_7","027_2_7","EZK","2","7","7","ודברת את דברי אליהם אם ישמעו ואם יחדלו כי מרי המה׃ ");
INSERT INTO heb_vpl VALUES ("EK2_8","027_2_8","EZK","2","8","8","ואתה בן אדם שמע את אשר אני מדבר אליך אל תהי מרי כבית המרי פצה פיך ואכל את אשר אני נתן אליך׃ ");
INSERT INTO heb_vpl VALUES ("EK2_9","027_2_9","EZK","2","9","9","ואראה והנה יד שלוחה אלי והנה בו מגלת ספר׃ ");
INSERT INTO heb_vpl VALUES ("EK2_10","027_2_10","EZK","2","10","10","ויפרש אותה לפני והיא כתובה פנים ואחור וכתוב אליה קנים והגה והי׃ ");
INSERT INTO heb_vpl VALUES ("EK3_1","027_3_1","EZK","3","1","1","ויאמר אלי בן אדם את אשר תמצא אכול אכול את המגלה הזאת ולך דבר אל בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK3_2","027_3_2","EZK","3","2","2","ואפתח את פי ויאכלני את המגלה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("EK3_3","027_3_3","EZK","3","3","3","ויאמר אלי בן אדם בטנך תאכל ומעיך תמלא את המגלה הזאת אשר אני נתן אליך ואכלה ותהי בפי כדבש למתוק׃ ");
INSERT INTO heb_vpl VALUES ("EK3_4","027_3_4","EZK","3","4","4","ויאמר אלי בן אדם לך בא אל בית ישראל ודברת בדברי אליהם׃ ");
INSERT INTO heb_vpl VALUES ("EK3_5","027_3_5","EZK","3","5","5","כי לא אל עם עמקי שפה וכבדי לשון אתה שלוח אל בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK3_6","027_3_6","EZK","3","6","6","לא אל עמים רבים עמקי שפה וכבדי לשון אשר לא תשמע דבריהם אם לא אליהם שלחתיך המה ישמעו אליך׃ ");
INSERT INTO heb_vpl VALUES ("EK3_7","027_3_7","EZK","3","7","7","ובית ישראל לא יאבו לשמע אליך כי אינם אבים לשמע אלי כי כל בית ישראל חזקי מצח וקשי לב המה׃ ");
INSERT INTO heb_vpl VALUES ("EK3_8","027_3_8","EZK","3","8","8","הנה נתתי את פניך חזקים לעמת פניהם ואת מצחך חזק לעמת מצחם׃ ");
INSERT INTO heb_vpl VALUES ("EK3_9","027_3_9","EZK","3","9","9","כשמיר חזק מצר נתתי מצחך לא תירא אותם ולא תחת מפניהם כי בית מרי המה׃ ");
INSERT INTO heb_vpl VALUES ("EK3_10","027_3_10","EZK","3","10","10","ויאמר אלי בן אדם את כל דברי אשר אדבר אליך קח בלבבך ובאזניך שמע׃ ");
INSERT INTO heb_vpl VALUES ("EK3_11","027_3_11","EZK","3","11","11","ולך בא אל הגולה אל בני עמך ודברת אליהם ואמרת אליהם כה אמר אדני יהוה אם ישמעו ואם יחדלו׃ ");
INSERT INTO heb_vpl VALUES ("EK3_12","027_3_12","EZK","3","12","12","ותשאני רוח ואשמע אחרי קול רעש גדול ברוך כבוד יהוה ממקומו׃ ");
INSERT INTO heb_vpl VALUES ("EK3_13","027_3_13","EZK","3","13","13","וקול כנפי החיות משיקות אשה אל אחותה וקול האופנים לעמתם וקול רעש גדול׃ ");
INSERT INTO heb_vpl VALUES ("EK3_14","027_3_14","EZK","3","14","14","ורוח נשאתני ותקחני ואלך מר בחמת רוחי ויד יהוה עלי חזקה׃ ");
INSERT INTO heb_vpl VALUES ("EK3_15","027_3_15","EZK","3","15","15","ואבוא אל הגולה תל אביב הישבים אל נהר כבר ואשר המה יושבים שם ואשב שם שבעת ימים משמים בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("EK3_16","027_3_16","EZK","3","16","16","ויהי מקצה שבעת ימים ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK3_17","027_3_17","EZK","3","17","17","בן אדם צפה נתתיך לבית ישראל ושמעת מפי דבר והזהרת אותם ממני׃ ");
INSERT INTO heb_vpl VALUES ("EK3_18","027_3_18","EZK","3","18","18","באמרי לרשע מות תמות ולא הזהרתו ולא דברת להזהיר רשע מדרכו הרשעה לחיתו הוא רשע בעונו ימות ודמו מידך אבקש׃ ");
INSERT INTO heb_vpl VALUES ("EK3_19","027_3_19","EZK","3","19","19","ואתה כי הזהרת רשע ולא שב מרשעו ומדרכו הרשעה הוא בעונו ימות ואתה את נפשך הצלת׃ ");
INSERT INTO heb_vpl VALUES ("EK3_20","027_3_20","EZK","3","20","20","ובשוב צדיק מצדקו ועשה עול ונתתי מכשול לפניו הוא ימות כי לא הזהרתו בחטאתו ימות ולא תזכרן צדקתו אשר עשה ודמו מידך אבקש׃ ");
INSERT INTO heb_vpl VALUES ("EK3_21","027_3_21","EZK","3","21","21","ואתה כי הזהרתו צדיק לבלתי חטא צדיק והוא לא חטא חיו יחיה כי נזהר ואתה את נפשך הצלת׃ ");
INSERT INTO heb_vpl VALUES ("EK3_22","027_3_22","EZK","3","22","22","ותהי עלי שם יד יהוה ויאמר אלי קום צא אל הבקעה ושם אדבר אותך׃ ");
INSERT INTO heb_vpl VALUES ("EK3_23","027_3_23","EZK","3","23","23","ואקום ואצא אל הבקעה והנה שם כבוד יהוה עמד ככבוד אשר ראיתי על נהר כבר ואפל על פני׃ ");
INSERT INTO heb_vpl VALUES ("EK3_24","027_3_24","EZK","3","24","24","ותבא בי רוח ותעמדני על רגלי וידבר אתי ויאמר אלי בא הסגר בתוך ביתך׃ ");
INSERT INTO heb_vpl VALUES ("EK3_25","027_3_25","EZK","3","25","25","ואתה בן אדם הנה נתנו עליך עבותים ואסרוך בהם ולא תצא בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("EK3_26","027_3_26","EZK","3","26","26","ולשונך אדביק אל חכך ונאלמת ולא תהיה להם לאיש מוכיח כי בית מרי המה׃ ");
INSERT INTO heb_vpl VALUES ("EK3_27","027_3_27","EZK","3","27","27","ובדברי אותך אפתח את פיך ואמרת אליהם כה אמר אדני יהוה השמע ישמע והחדל יחדל כי בית מרי המה׃ ");
INSERT INTO heb_vpl VALUES ("EK4_1","027_4_1","EZK","4","1","1","ואתה בן אדם קח לך לבנה ונתתה אותה לפניך וחקות עליה עיר את ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("EK4_2","027_4_2","EZK","4","2","2","ונתתה עליה מצור ובנית עליה דיק ושפכת עליה סללה ונתתה עליה מחנות ושים עליה כרים סביב׃ ");
INSERT INTO heb_vpl VALUES ("EK4_3","027_4_3","EZK","4","3","3","ואתה קח לך מחבת ברזל ונתתה אותה קיר ברזל בינך ובין העיר והכינתה את פניך אליה והיתה במצור וצרת עליה אות היא לבית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK4_4","027_4_4","EZK","4","4","4","ואתה שכב על צדך השמאלי ושמת את עון בית ישראל עליו מספר הימים אשר תשכב עליו תשא את עונם׃ ");
INSERT INTO heb_vpl VALUES ("EK4_5","027_4_5","EZK","4","5","5","ואני נתתי לך את שני עונם למספר ימים שלש מאות ותשעים יום ונשאת עון בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK4_6","027_4_6","EZK","4","6","6","וכלית את אלה ושכבת על צדך הימוני שנית ונשאת את עון בית יהודה ארבעים יום יום לשנה יום לשנה נתתיו לך׃ ");
INSERT INTO heb_vpl VALUES ("EK4_7","027_4_7","EZK","4","7","7","ואל מצור ירושלם תכין פניך וזרעך חשופה ונבאת עליה׃ ");
INSERT INTO heb_vpl VALUES ("EK4_8","027_4_8","EZK","4","8","8","והנה נתתי עליך עבותים ולא תהפך מצדך אל צדך עד כלותך ימי מצורך׃ ");
INSERT INTO heb_vpl VALUES ("EK4_9","027_4_9","EZK","4","9","9","ואתה קח לך חטין ושערים ופול ועדשים ודחן וכסמים ונתתה אותם בכלי אחד ועשית אותם לך ללחם מספר הימים אשר אתה שוכב על צדך שלש מאות ותשעים יום תאכלנו׃ ");
INSERT INTO heb_vpl VALUES ("EK4_10","027_4_10","EZK","4","10","10","ומאכלך אשר תאכלנו במשקול עשרים שקל ליום מעת עד עת תאכלנו׃ ");
INSERT INTO heb_vpl VALUES ("EK4_11","027_4_11","EZK","4","11","11","ומים במשורה תשתה ששית ההין מעת עד עת תשתה׃ ");
INSERT INTO heb_vpl VALUES ("EK4_12","027_4_12","EZK","4","12","12","ועגת שערים תאכלנה והיא בגללי צאת האדם תעגנה לעיניהם׃ ");
INSERT INTO heb_vpl VALUES ("EK4_13","027_4_13","EZK","4","13","13","ויאמר יהוה ככה יאכלו בני ישראל את לחמם טמא בגוים אשר אדיחם שם׃ ");
INSERT INTO heb_vpl VALUES ("EK4_14","027_4_14","EZK","4","14","14","ואמר אהה אדני יהוה הנה נפשי לא מטמאה ונבלה וטרפה לא אכלתי מנעורי ועד עתה ולא בא בפי בשר פגול׃ ");
INSERT INTO heb_vpl VALUES ("EK4_15","027_4_15","EZK","4","15","15","ויאמר אלי ראה נתתי לך את צפועי הבקר תחת גללי האדם ועשית את לחמך עליהם׃ ");
INSERT INTO heb_vpl VALUES ("EK4_16","027_4_16","EZK","4","16","16","ויאמר אלי בן אדם הנני שבר מטה לחם בירושלם ואכלו לחם במשקל ובדאגה ומים במשורה ובשממון ישתו׃ ");
INSERT INTO heb_vpl VALUES ("EK4_17","027_4_17","EZK","4","17","17","למען יחסרו לחם ומים ונשמו איש ואחיו ונמקו בעונם׃ ");
INSERT INTO heb_vpl VALUES ("EK5_1","027_5_1","EZK","5","1","1","ואתה בן אדם קח לך חרב חדה תער הגלבים תקחנה לך והעברת על ראשך ועל זקנך ולקחת לך מאזני משקל וחלקתם׃ ");
INSERT INTO heb_vpl VALUES ("EK5_2","027_5_2","EZK","5","2","2","שלשית באור תבעיר בתוך העיר כמלאת ימי המצור ולקחת את השלשית תכה בחרב סביבותיה והשלשית תזרה לרוח וחרב אריק אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("EK5_3","027_5_3","EZK","5","3","3","ולקחת משם מעט במספר וצרת אותם בכנפיך׃ ");
INSERT INTO heb_vpl VALUES ("EK5_4","027_5_4","EZK","5","4","4","ומהם עוד תקח והשלכת אותם אל תוך האש ושרפת אתם באש ממנו תצא אש אל כל בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK5_5","027_5_5","EZK","5","5","5","כה אמר אדני יהוה זאת ירושלם בתוך הגוים שמתיה וסביבותיה ארצות׃ ");
INSERT INTO heb_vpl VALUES ("EK5_6","027_5_6","EZK","5","6","6","ותמר את משפטי לרשעה מן הגוים ואת חקותי מן הארצות אשר סביבותיה כי במשפטי מאסו וחקותי לא הלכו בהם׃ ");
INSERT INTO heb_vpl VALUES ("EK5_7","027_5_7","EZK","5","7","7","לכן כה אמר אדני יהוה יען המנכם מן הגוים אשר סביבותיכם בחקותי לא הלכתם ואת משפטי לא עשיתם וכמשפטי הגוים אשר סביבותיכם לא עשיתם׃ ");
INSERT INTO heb_vpl VALUES ("EK5_8","027_5_8","EZK","5","8","8","לכן כה אמר אדני יהוה הנני עליך גם אני ועשיתי בתוכך משפטים לעיני הגוים׃ ");
INSERT INTO heb_vpl VALUES ("EK5_9","027_5_9","EZK","5","9","9","ועשיתי בך את אשר לא עשיתי ואת אשר לא אעשה כמהו עוד יען כל תועבתיך׃ ");
INSERT INTO heb_vpl VALUES ("EK5_10","027_5_10","EZK","5","10","10","לכן אבות יאכלו בנים בתוכך ובנים יאכלו אבותם ועשיתי בך שפטים וזריתי את כל שאריתך לכל רוח׃ ");
INSERT INTO heb_vpl VALUES ("EK5_11","027_5_11","EZK","5","11","11","לכן חי אני נאם אדני יהוה אם לא יען את מקדשי טמאת בכל שקוציך ובכל תועבתיך וגם אני אגרע ולא תחוס עיני וגם אני לא אחמול׃ ");
INSERT INTO heb_vpl VALUES ("EK5_12","027_5_12","EZK","5","12","12","שלשתיך בדבר ימותו וברעב יכלו בתוכך והשלשית בחרב יפלו סביבותיך והשלישית לכל רוח אזרה וחרב אריק אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("EK5_13","027_5_13","EZK","5","13","13","וכלה אפי והנחותי חמתי בם והנחמתי וידעו כי אני יהוה דברתי בקנאתי בכלותי חמתי בם׃ ");
INSERT INTO heb_vpl VALUES ("EK5_14","027_5_14","EZK","5","14","14","ואתנך לחרבה ולחרפה בגוים אשר סביבותיך לעיני כל עובר׃ ");
INSERT INTO heb_vpl VALUES ("EK5_15","027_5_15","EZK","5","15","15","והיתה חרפה וגדופה מוסר ומשמה לגוים אשר סביבותיך בעשותי בך שפטים באף ובחמה ובתכחות חמה אני יהוה דברתי׃ ");
INSERT INTO heb_vpl VALUES ("EK5_16","027_5_16","EZK","5","16","16","בשלחי את חצי הרעב הרעים בהם אשר היו למשחית אשר אשלח אותם לשחתכם ורעב אסף עליכם ושברתי לכם מטה לחם׃ ");
INSERT INTO heb_vpl VALUES ("EK5_17","027_5_17","EZK","5","17","17","ושלחתי עליכם רעב וחיה רעה ושכלך ודבר ודם יעבר בך וחרב אביא עליך אני יהוה דברתי׃ ");
INSERT INTO heb_vpl VALUES ("EK6_1","027_6_1","EZK","6","1","1","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK6_2","027_6_2","EZK","6","2","2","בן אדם שים פניך אל הרי ישראל והנבא אליהם׃ ");
INSERT INTO heb_vpl VALUES ("EK6_3","027_6_3","EZK","6","3","3","ואמרת הרי ישראל שמעו דבר אדני יהוה כה אמר אדני יהוה להרים ולגבעות לאפיקים ולגאית הנני אני מביא עליכם חרב ואבדתי במותיכם׃ ");
INSERT INTO heb_vpl VALUES ("EK6_4","027_6_4","EZK","6","4","4","ונשמו מזבחותיכם ונשברו חמניכם והפלתי חלליכם לפני גלוליכם׃ ");
INSERT INTO heb_vpl VALUES ("EK6_5","027_6_5","EZK","6","5","5","ונתתי את פגרי בני ישראל לפני גלוליהם וזריתי את עצמותיכם סביבות מזבחותיכם׃ ");
INSERT INTO heb_vpl VALUES ("EK6_6","027_6_6","EZK","6","6","6","בכל מושבותיכם הערים תחרבנה והבמות תישמנה למען יחרבו ויאשמו מזבחותיכם ונשברו ונשבתו גלוליכם ונגדעו חמניכם ונמחו מעשיכם׃ ");
INSERT INTO heb_vpl VALUES ("EK6_7","027_6_7","EZK","6","7","7","ונפל חלל בתוככם וידעתם כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK6_8","027_6_8","EZK","6","8","8","והותרתי בהיות לכם פליטי חרב בגוים בהזרותיכם בארצות׃ ");
INSERT INTO heb_vpl VALUES ("EK6_9","027_6_9","EZK","6","9","9","וזכרו פליטיכם אותי בגוים אשר נשבו שם אשר נשברתי את לבם הזונה אשר סר מעלי ואת עיניהם הזנות אחרי גלוליהם ונקטו בפניהם אל הרעות אשר עשו לכל תועבתיהם׃ ");
INSERT INTO heb_vpl VALUES ("EK6_10","027_6_10","EZK","6","10","10","וידעו כי אני יהוה לא אל חנם דברתי לעשות להם הרעה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("EK6_11","027_6_11","EZK","6","11","11","כה אמר אדני יהוה הכה בכפך ורקע ברגלך ואמר אח אל כל תועבות רעות בית ישראל אשר בחרב ברעב ובדבר יפלו׃ ");
INSERT INTO heb_vpl VALUES ("EK6_12","027_6_12","EZK","6","12","12","הרחוק בדבר ימות והקרוב בחרב יפול והנשאר והנצור ברעב ימות וכליתי חמתי בם׃ ");
INSERT INTO heb_vpl VALUES ("EK6_13","027_6_13","EZK","6","13","13","וידעתם כי אני יהוה בהיות חלליהם בתוך גלוליהם סביבות מזבחותיהם אל כל גבעה רמה בכל ראשי ההרים ותחת כל עץ רענן ותחת כל אלה עבתה מקום אשר נתנו שם ריח ניחח לכל גלוליהם׃ ");
INSERT INTO heb_vpl VALUES ("EK6_14","027_6_14","EZK","6","14","14","ונטיתי את ידי עליהם ונתתי את הארץ שממה ומשמה ממדבר דבלתה בכל מושבותיהם וידעו כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_1","027_7_1","EZK","7","1","1","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK7_2","027_7_2","EZK","7","2","2","ואתה בן אדם כה אמר אדני יהוה לאדמת ישראל קץ בא הקץ על ארבעת כנפות הארץ׃ ");
INSERT INTO heb_vpl VALUES ("EK7_3","027_7_3","EZK","7","3","3","עתה הקץ עליך ושלחתי אפי בך ושפטתיך כדרכיך ונתתי עליך את כל תועבתיך׃ ");
INSERT INTO heb_vpl VALUES ("EK7_4","027_7_4","EZK","7","4","4","ולא תחוס עיני עליך ולא אחמול כי דרכיך עליך אתן ותועבותיך בתוכך תהיין וידעתם כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_5","027_7_5","EZK","7","5","5","כה אמר אדני יהוה רעה אחת רעה הנה באה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_6","027_7_6","EZK","7","6","6","קץ בא בא הקץ הקיץ אליך הנה באה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_7","027_7_7","EZK","7","7","7","באה הצפירה אליך יושב הארץ בא העת קרוב היום מהומה ולא הד הרים׃ ");
INSERT INTO heb_vpl VALUES ("EK7_8","027_7_8","EZK","7","8","8","עתה מקרוב אשפוך חמתי עליך וכליתי אפי בך ושפטתיך כדרכיך ונתתי עליך את כל תועבותיך׃ ");
INSERT INTO heb_vpl VALUES ("EK7_9","027_7_9","EZK","7","9","9","ולא תחוס עיני ולא אחמול כדרכיך עליך אתן ותועבותיך בתוכך תהיין וידעתם כי אני יהוה מכה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_10","027_7_10","EZK","7","10","10","הנה היום הנה באה יצאה הצפרה צץ המטה פרח הזדון׃ ");
INSERT INTO heb_vpl VALUES ("EK7_11","027_7_11","EZK","7","11","11","החמס קם למטה רשע לא מהם ולא מהמונם ולא מהמהם ולא נה בהם׃ ");
INSERT INTO heb_vpl VALUES ("EK7_12","027_7_12","EZK","7","12","12","בא העת הגיע היום הקונה אל ישמח והמוכר אל יתאבל כי חרון אל כל המונה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_13","027_7_13","EZK","7","13","13","כי המוכר אל הממכר לא ישוב ועוד בחיים חיתם כי חזון אל כל המונה לא ישוב ואיש בעונו חיתו לא יתחזקו׃ ");
INSERT INTO heb_vpl VALUES ("EK7_14","027_7_14","EZK","7","14","14","תקעו בתקוע והכין הכל ואין הלך למלחמה כי חרוני אל כל המונה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_15","027_7_15","EZK","7","15","15","החרב בחוץ והדבר והרעב מבית אשר בשדה בחרב ימות ואשר בעיר רעב ודבר יאכלנו׃ ");
INSERT INTO heb_vpl VALUES ("EK7_16","027_7_16","EZK","7","16","16","ופלטו פליטיהם והיו אל ההרים כיוני הגאיות כלם המות איש בעונו׃ ");
INSERT INTO heb_vpl VALUES ("EK7_17","027_7_17","EZK","7","17","17","כל הידים תרפינה וכל ברכים תלכנה מים׃ ");
INSERT INTO heb_vpl VALUES ("EK7_18","027_7_18","EZK","7","18","18","וחגרו שקים וכסתה אותם פלצות ואל כל פנים בושה ובכל ראשיהם קרחה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_19","027_7_19","EZK","7","19","19","כספם בחוצות ישליכו וזהבם לנדה יהיה כספם וזהבם לא יוכל להצילם ביום עברת יהוה נפשם לא ישבעו ומעיהם לא ימלאו כי מכשול עונם היה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_20","027_7_20","EZK","7","20","20","וצבי עדיו לגאון שמהו וצלמי תועבתם שקוציהם עשו בו על כן נתתיו להם לנדה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_21","027_7_21","EZK","7","21","21","ונתתיו ביד הזרים לבז ולרשעי הארץ לשלל וחללה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_22","027_7_22","EZK","7","22","22","והסבותי פני מהם וחללו את צפוני ובאו בה פריצים וחללוה׃ ");
INSERT INTO heb_vpl VALUES ("EK7_23","027_7_23","EZK","7","23","23","עשה הרתוק כי הארץ מלאה משפט דמים והעיר מלאה חמס׃ ");
INSERT INTO heb_vpl VALUES ("EK7_24","027_7_24","EZK","7","24","24","והבאתי רעי גוים וירשו את בתיהם והשבתי גאון עזים ונחלו מקדשיהם׃ ");
INSERT INTO heb_vpl VALUES ("EK7_25","027_7_25","EZK","7","25","25","קפדה בא ובקשו שלום ואין׃ ");
INSERT INTO heb_vpl VALUES ("EK7_26","027_7_26","EZK","7","26","26","הוה על הוה תבוא ושמעה אל שמועה תהיה ובקשו חזון מנביא ותורה תאבד מכהן ועצה מזקנים׃ ");
INSERT INTO heb_vpl VALUES ("EK7_27","027_7_27","EZK","7","27","27","המלך יתאבל ונשיא ילבש שממה וידי עם הארץ תבהלנה מדרכם אעשה אותם ובמשפטיהם אשפטם וידעו כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_1","027_8_1","EZK","8","1","1","ויהי בשנה הששית בששי בחמשה לחדש אני יושב בביתי וזקני יהודה יושבים לפני ותפל עלי שם יד אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_2","027_8_2","EZK","8","2","2","ואראה והנה דמות כמראה אש ממראה מתניו ולמטה אש וממתניו ולמעלה כמראה זהר כעין החשמלה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_3","027_8_3","EZK","8","3","3","וישלח תבנית יד ויקחני בציצת ראשי ותשא אתי רוח בין הארץ ובין השמים ותבא אתי ירושלמה במראות אלהים אל פתח שער הפנימית הפונה צפונה אשר שם מושב סמל הקנאה המקנה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_4","027_8_4","EZK","8","4","4","והנה שם כבוד אלהי ישראל כמראה אשר ראיתי בבקעה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_5","027_8_5","EZK","8","5","5","ויאמר אלי בן אדם שא נא עיניך דרך צפונה ואשא עיני דרך צפונה והנה מצפון לשער המזבח סמל הקנאה הזה בבאה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_6","027_8_6","EZK","8","6","6","ויאמר אלי בן אדם הראה אתה מהם עשים תועבות גדלות אשר בית ישראל עשים פה לרחקה מעל מקדשי ועוד תשוב תראה תועבות גדלות׃ ");
INSERT INTO heb_vpl VALUES ("EK8_7","027_8_7","EZK","8","7","7","ויבא אתי אל פתח החצר ואראה והנה חר אחד בקיר׃ ");
INSERT INTO heb_vpl VALUES ("EK8_8","027_8_8","EZK","8","8","8","ויאמר אלי בן אדם חתר נא בקיר ואחתר בקיר והנה פתח אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK8_9","027_8_9","EZK","8","9","9","ויאמר אלי בא וראה את התועבות הרעות אשר הם עשים פה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_10","027_8_10","EZK","8","10","10","ואבוא ואראה והנה כל תבנית רמש ובהמה שקץ וכל גלולי בית ישראל מחקה על הקיר סביב סביב׃ ");
INSERT INTO heb_vpl VALUES ("EK8_11","027_8_11","EZK","8","11","11","ושבעים איש מזקני בית ישראל ויאזניהו בן שפן עמד בתוכם עמדים לפניהם ואיש מקטרתו בידו ועתר ענן הקטרת עלה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_12","027_8_12","EZK","8","12","12","ויאמר אלי הראית בן אדם אשר זקני בית ישראל עשים בחשך איש בחדרי משכיתו כי אמרים אין יהוה ראה אתנו עזב יהוה את הארץ׃ ");
INSERT INTO heb_vpl VALUES ("EK8_13","027_8_13","EZK","8","13","13","ויאמר אלי עוד תשוב תראה תועבות גדלות אשר המה עשים׃ ");
INSERT INTO heb_vpl VALUES ("EK8_14","027_8_14","EZK","8","14","14","ויבא אתי אל פתח שער בית יהוה אשר אל הצפונה והנה שם הנשים ישבות מבכות את התמוז׃ ");
INSERT INTO heb_vpl VALUES ("EK8_15","027_8_15","EZK","8","15","15","ויאמר אלי הראית בן אדם עוד תשוב תראה תועבות גדלות מאלה׃ ");
INSERT INTO heb_vpl VALUES ("EK8_16","027_8_16","EZK","8","16","16","ויבא אתי אל חצר בית יהוה הפנימית והנה פתח היכל יהוה בין האולם ובין המזבח כעשרים וחמשה איש אחריהם אל היכל יהוה ופניהם קדמה והמה משתחויתם קדמה לשמש׃ ");
INSERT INTO heb_vpl VALUES ("EK8_17","027_8_17","EZK","8","17","17","ויאמר אלי הראית בן אדם הנקל לבית יהודה מעשות את התועבות אשר עשו פה כי מלאו את הארץ חמס וישבו להכעיסני והנם שלחים את הזמורה אל אפם׃ ");
INSERT INTO heb_vpl VALUES ("EK8_18","027_8_18","EZK","8","18","18","וגם אני אעשה בחמה לא תחוס עיני ולא אחמל וקראו באזני קול גדול ולא אשמע אותם׃ ");
INSERT INTO heb_vpl VALUES ("EK9_1","027_9_1","EZK","9","1","1","ויקרא באזני קול גדול לאמר קרבו פקדות העיר ואיש כלי משחתו בידו׃ ");
INSERT INTO heb_vpl VALUES ("EK9_2","027_9_2","EZK","9","2","2","והנה ששה אנשים באים מדרך שער העליון אשר מפנה צפונה ואיש כלי מפצו בידו ואיש אחד בתוכם לבש בדים וקסת הספר במתניו ויבאו ויעמדו אצל מזבח הנחשת׃ ");
INSERT INTO heb_vpl VALUES ("EK9_3","027_9_3","EZK","9","3","3","וכבוד אלהי ישראל נעלה מעל הכרוב אשר היה עליו אל מפתן הבית ויקרא אל האיש הלבש הבדים אשר קסת הספר במתניו׃ ");
INSERT INTO heb_vpl VALUES ("EK9_4","027_9_4","EZK","9","4","4","ויאמר יהוה אלו עבר בתוך העיר בתוך ירושלם והתוית תו על מצחות האנשים הנאנחים והנאנקים על כל התועבות הנעשות בתוכה׃ ");
INSERT INTO heb_vpl VALUES ("EK9_5","027_9_5","EZK","9","5","5","ולאלה אמר באזני עברו בעיר אחריו והכו על תחס עיניכם ואל תחמלו׃ ");
INSERT INTO heb_vpl VALUES ("EK9_6","027_9_6","EZK","9","6","6","זקן בחור ובתולה וטף ונשים תהרגו למשחית ועל כל איש אשר עליו התו אל תגשו וממקדשי תחלו ויחלו באנשים הזקנים אשר לפני הבית׃ ");
INSERT INTO heb_vpl VALUES ("EK9_7","027_9_7","EZK","9","7","7","ויאמר אליהם טמאו את הבית ומלאו את החצרות חללים צאו ויצאו והכו בעיר׃ ");
INSERT INTO heb_vpl VALUES ("EK9_8","027_9_8","EZK","9","8","8","ויהי כהכותם ונאשאר אני ואפלה על פני ואזעק ואמר אהה אדני יהוה המשחית אתה את כל שארית ישראל בשפכך את חמתך על ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("EK9_9","027_9_9","EZK","9","9","9","ויאמר אלי עון בית ישראל ויהודה גדול במאד מאד ותמלא הארץ דמים והעיר מלאה מטה כי אמרו עזב יהוה את הארץ ואין יהוה ראה׃ ");
INSERT INTO heb_vpl VALUES ("EK9_10","027_9_10","EZK","9","10","10","וגם אני לא תחוס עיני ולא אחמל דרכם בראשם נתתי׃ ");
INSERT INTO heb_vpl VALUES ("EK9_11","027_9_11","EZK","9","11","11","והנה האיש לבש הבדים אשר הקסת במתניו משיב דבר לאמר עשיתי כאשר צויתני׃ ");
INSERT INTO heb_vpl VALUES ("EK10_1","027_10_1","EZK","10","1","1","ואראה והנה אל הרקיע אשר על ראש הכרבים כאבן ספיר כמראה דמות כסא נראה עליהם׃ ");
INSERT INTO heb_vpl VALUES ("EK10_2","027_10_2","EZK","10","2","2","ויאמר אל האיש לבש הבדים ויאמר בא אל בינות לגלגל אל תחת לכרוב ומלא חפניך גחלי אש מבינות לכרבים וזרק על העיר ויבא לעיני׃ ");
INSERT INTO heb_vpl VALUES ("EK10_3","027_10_3","EZK","10","3","3","והכרבים עמדים מימין לבית בבאו האיש והענן מלא את החצר הפנימית׃ ");
INSERT INTO heb_vpl VALUES ("EK10_4","027_10_4","EZK","10","4","4","וירם כבוד יהוה מעל הכרוב על מפתן הבית וימלא הבית את הענן והחצר מלאה את נגה כבוד יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK10_5","027_10_5","EZK","10","5","5","וקול כנפי הכרובים נשמע עד החצר החיצנה כקול אל שדי בדברו׃ ");
INSERT INTO heb_vpl VALUES ("EK10_6","027_10_6","EZK","10","6","6","ויהי בצותו את האיש לבש הבדים לאמר קח אש מבינות לגלגל מבינות לכרובים ויבא ויעמד אצל האופן׃ ");
