INSERT INTO heb_vpl VALUES ("EK13_14","027_13_14","EZK","13","14","14","והרסתי את הקיר אשר טחתם תפל והגעתיהו אל הארץ ונגלה יסדו ונפלה וכליתם בתוכה וידעתם כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK13_15","027_13_15","EZK","13","15","15","וכליתי את חמתי בקיר ובטחים אתו תפל ואמר לכם אין הקיר ואין הטחים אתו׃ ");
INSERT INTO heb_vpl VALUES ("EK13_16","027_13_16","EZK","13","16","16","נביאי ישראל הנבאים אל ירושלם והחזים לה חזון שלם ואין שלם נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK13_17","027_13_17","EZK","13","17","17","ואתה בן אדם שים פניך אל בנות עמך המתנבאות מלבהן והנבא עליהן׃ ");
INSERT INTO heb_vpl VALUES ("EK13_18","027_13_18","EZK","13","18","18","ואמרת כה אמר אדני יהוה הוי למתפרות כסתות על כל אצילי ידי ועשות המספחות על ראש כל קומה לצודד נפשות הנפשות תצודדנה לעמי ונפשות לכנה תחיינה׃ ");
INSERT INTO heb_vpl VALUES ("EK13_19","027_13_19","EZK","13","19","19","ותחללנה אתי אל עמי בשעלי שערים ובפתותי לחם להמית נפשות אשר לא תמותנה ולחיות נפשות אשר לא תחיינה בכזבכם לעמי שמעי כזב׃ ");
INSERT INTO heb_vpl VALUES ("EK13_20","027_13_20","EZK","13","20","20","לכן כה אמר אדני יהוה הנני אל כסתותיכנה אשר אתנה מצדדות שם את הנפשות לפרחות וקרעתי אתם מעל זרועתיכם ושלחתי את הנפשות אשר אתם מצדדות את נפשים לפרחת׃ ");
INSERT INTO heb_vpl VALUES ("EK13_21","027_13_21","EZK","13","21","21","וקרעתי את מספחתיכם והצלתי את עמי מידכן ולא יהיו עוד בידכן למצודה וידעתן כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK13_22","027_13_22","EZK","13","22","22","יען הכאות לב צדיק שקר ואני לא הכאבתיו ולחזק ידי רשע לבלתי שוב מדרכו הרע להחיתו׃ ");
INSERT INTO heb_vpl VALUES ("EK13_23","027_13_23","EZK","13","23","23","לכן שוא לא תחזינה וקסם לא תקסמנה עוד והצלתי את עמי מידכן וידעתן כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_1","027_14_1","EZK","14","1","1","ויבוא אלי אנשים מזקני ישראל וישבו לפני׃ ");
INSERT INTO heb_vpl VALUES ("EK14_2","027_14_2","EZK","14","2","2","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK14_3","027_14_3","EZK","14","3","3","בן אדם האנשים האלה העלו גלוליהם על לבם ומכשול עונם נתנו נכח פניהם האדרש אדרש להם׃ ");
INSERT INTO heb_vpl VALUES ("EK14_4","027_14_4","EZK","14","4","4","לכן דבר אותם ואמרת אליהם כה אמר אדני יהוה איש איש מבית ישראל אשר יעלה את גלוליו אל לבו ומכשול עונו ישים נכח פניו ובא אל הנביא אני יהוה נעניתי לו בה ברב גלוליו׃ ");
INSERT INTO heb_vpl VALUES ("EK14_5","027_14_5","EZK","14","5","5","למען תפש את בית ישראל בלבם אשר נזרו מעלי בגלוליהם כלם׃ ");
INSERT INTO heb_vpl VALUES ("EK14_6","027_14_6","EZK","14","6","6","לכן אמר אל בית ישראל כה אמר אדני יהוה שובו והשיבו מעל גלוליכם ומעל כל תועבתיכם השיבו פניכם׃ ");
INSERT INTO heb_vpl VALUES ("EK14_7","027_14_7","EZK","14","7","7","כי איש איש מבית ישראל ומהגר אשר יגור בישראל וינזר מאחרי ויעל גלוליו אל לבו ומכשול עונו ישים נכח פניו ובא אל הנביא לדרש לו בי אני יהוה נענה לו בי׃ ");
INSERT INTO heb_vpl VALUES ("EK14_8","027_14_8","EZK","14","8","8","ונתתי פני באיש ההוא והשמתיהו לאות ולמשלים והכרתיו מתוך עמי וידעתם כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_9","027_14_9","EZK","14","9","9","והנביא כי יפתה ודבר דבר אני יהוה פתיתי את הנביא ההוא ונטיתי את ידי עליו והשמדתיו מתוך עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK14_10","027_14_10","EZK","14","10","10","ונשאו עונם כעון הדרש כעון הנביא יהיה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_11","027_14_11","EZK","14","11","11","למען לא יתעו עוד בית ישראל מאחרי ולא יטמאו עוד בכל פשעיהם והיו לי לעם ואני אהיה להם לאלהים נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_12","027_14_12","EZK","14","12","12","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK14_13","027_14_13","EZK","14","13","13","בן אדם ארץ כי תחטא לי למעל מעל ונטיתי ידי עליה ושברתי לה מטה לחם והשלחתי בה רעב והכרתי ממנה אדם ובהמה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_14","027_14_14","EZK","14","14","14","והיו שלשת האנשים האלה בתוכה נח דנאל ואיוב המה בצדקתם ינצלו נפשם נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_15","027_14_15","EZK","14","15","15","לו חיה רעה אעביר בארץ ושכלתה והיתה שממה מבלי עובר מפני החיה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_16","027_14_16","EZK","14","16","16","שלשת האנשים האלה בתוכה חי אני נאם אדני יהוה אם בנים ואם בנות יצילו המה לבדם ינצלו והארץ תהיה שממה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_17","027_14_17","EZK","14","17","17","או חרב אביא על הארץ ההיא ואמרתי חרב תעבר בארץ והכרתי ממנה אדם ובהמה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_18","027_14_18","EZK","14","18","18","ושלשת האנשים האלה בתוכה חי אני נאם אדני יהוה לא יצילו בנים ובנות כי הם לבדם ינצלו׃ ");
INSERT INTO heb_vpl VALUES ("EK14_19","027_14_19","EZK","14","19","19","או דבר אשלח אל הארץ ההיא ושפכתי חמתי עליה בדם להכרית ממנה אדם ובהמה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_20","027_14_20","EZK","14","20","20","ונח דנאל ואיוב בתוכה חי אני נאם אדני יהוה אם בן אם בת יצילו המה בצדקתם יצילו נפשם׃ ");
INSERT INTO heb_vpl VALUES ("EK14_21","027_14_21","EZK","14","21","21","כי כה אמר אדני יהוה אף כי ארבעת שפטי הרעים חרב ורעב וחיה רעה ודבר שלחתי אל ירושלם להכרית ממנה אדם ובהמה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_22","027_14_22","EZK","14","22","22","והנה נותרה בה פלטה המוצאים בנים ובנות הנם יוצאים אליכם וראיתם את דרכם ואת עלילותם ונחמתם על הרעה אשר הבאתי על ירושלם את כל אשר הבאתי עליה׃ ");
INSERT INTO heb_vpl VALUES ("EK14_23","027_14_23","EZK","14","23","23","ונחמו אתכם כי תראו את דרכם ואת עלילותם וידעתם כי לא חנם עשיתי את כל אשר עשיתי בה נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK15_1","027_15_1","EZK","15","1","1","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK15_2","027_15_2","EZK","15","2","2","בן אדם מה יהיה עץ הגפן מכל עץ הזמורה אשר היה בעצי היער׃ ");
INSERT INTO heb_vpl VALUES ("EK15_3","027_15_3","EZK","15","3","3","היקח ממנו עץ לעשות למלאכה אם יקחו ממנו יתד לתלות עליו כל כלי׃ ");
