INSERT INTO heb_vpl VALUES ("EK15_5","027_15_5","EZK","15","5","5","הנה בהיותו תמים לא יעשה למלאכה אף כי אש אכלתהו ויחר ונעשה עוד למלאכה׃ ");
INSERT INTO heb_vpl VALUES ("EK15_6","027_15_6","EZK","15","6","6","לכן כה אמר אדני יהוה כאשר עץ הגפן בעץ היער אשר נתתיו לאש לאכלה כן נתתי את ישבי ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("EK15_7","027_15_7","EZK","15","7","7","ונתתי את פני בהם מהאש יצאו והאש תאכלם וידעתם כי אני יהוה בשומי את פני בהם׃ ");
INSERT INTO heb_vpl VALUES ("EK15_8","027_15_8","EZK","15","8","8","ונתתי את הארץ שממה יען מעלו מעל נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK16_1","027_16_1","EZK","16","1","1","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK16_2","027_16_2","EZK","16","2","2","בן אדם הודע את ירושלם את תועבתיה׃ ");
INSERT INTO heb_vpl VALUES ("EK16_3","027_16_3","EZK","16","3","3","ואמרת כה אמר אדני יהוה לירושלם מכרתיך ומלדתיך מארץ הכנעני אביך האמרי ואמך חתית׃ ");
INSERT INTO heb_vpl VALUES ("EK16_4","027_16_4","EZK","16","4","4","ומולדותיך ביום הולדת אתך לא כרת שרך ובמים לא רחצת למשעי והמלח לא המלחת והחתל לא חתלת׃ ");
INSERT INTO heb_vpl VALUES ("EK16_5","027_16_5","EZK","16","5","5","לא חסה עליך עין לעשות לך אחת מאלה לחמלה עליך ותשלכי אל פני השדה בגעל נפשך ביום הלדת אתך׃ ");
INSERT INTO heb_vpl VALUES ("EK16_6","027_16_6","EZK","16","6","6","ואעבר עליך ואראך מתבוססת בדמיך ואמר לך בדמיך חיי ואמר לך בדמיך חיי׃ ");
INSERT INTO heb_vpl VALUES ("EK16_7","027_16_7","EZK","16","7","7","רבבה כצמח השדה נתתיך ותרבי ותגדלי ותבאי בעדי עדיים שדים נכנו ושערך צמח ואת ערם ועריה׃ ");
INSERT INTO heb_vpl VALUES ("EK16_8","027_16_8","EZK","16","8","8","ואעבר עליך ואראך והנה עתך עת דדים ואפרש כנפי עליך ואכסה ערותך ואשבע לך ואבוא בברית אתך נאם אדני יהוה ותהיי לי׃ ");
INSERT INTO heb_vpl VALUES ("EK16_9","027_16_9","EZK","16","9","9","וארחצך במים ואשטף דמיך מעליך ואסכך בשמן׃ ");
