INSERT INTO heb_vpl VALUES ("EK16_13","027_16_13","EZK","16","13","13","ותעדי זהב וכסף ומלבושך ששי ומשי ורקמה סלת ודבש ושמן אכלתי ותיפי במאד מאד ותצלחי למלוכה׃ ");
INSERT INTO heb_vpl VALUES ("EK16_14","027_16_14","EZK","16","14","14","ויצא לך שם בגוים ביפיך כי כליל הוא בהדרי אשר שמתי עליך נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK16_15","027_16_15","EZK","16","15","15","ותבטחי ביפיך ותזני על שמך ותשפכי את תזנותיך על כל עובר לו יהי׃ ");
