INSERT INTO heb_vpl VALUES ("EK16_17","027_16_17","EZK","16","17","17","ותקחי כלי תפארתך מזהבי ומכספי אשר נתתי לך ותעשי לך צלמי זכר ותזני בם׃ ");
INSERT INTO heb_vpl VALUES ("EK16_18","027_16_18","EZK","16","18","18","ותקחי את בגדי רקמתך ותכסים ושמני וקטרתי נתתי לפניהם׃ ");
