INSERT INTO heb_vpl VALUES ("EK16_22","027_16_22","EZK","16","22","22","ואת כל תועבתיך ותזנתיך לא זכרתי את ימי נעוריך בהיותך ערם ועריה מתבוססת בדמך היית׃ ");
INSERT INTO heb_vpl VALUES ("EK16_23","027_16_23","EZK","16","23","23","ויהי אחרי כל רעתך אוי אוי לך נאם אדני יהוה׃ ");
