INSERT INTO heb_vpl VALUES ("EK16_28","027_16_28","EZK","16","28","28","ותזני אל בני אשור מבלתי שבעתך ותזנים וגם לא שבעת׃ ");
INSERT INTO heb_vpl VALUES ("EK16_29","027_16_29","EZK","16","29","29","ותרבי את תזנותך אל ארץ כנען כשדימה וגם בזאת לא שבעת׃ ");
