INSERT INTO heb_vpl VALUES ("EK16_33","027_16_33","EZK","16","33","33","לכל זנות יתנו נדה ואת נתת את נדניך לכל מאהביך ותשחדי אותם לבוא אליך מסביב בתזנותיך׃ ");
INSERT INTO heb_vpl VALUES ("EK16_34","027_16_34","EZK","16","34","34","ויהי בך הפך מן הנשים בתזנותיך ואחריך לא זונה ובתתך אתנן ואתנן לא נתן לך ותהי להפך׃ ");
