INSERT INTO heb_vpl VALUES ("EK16_36","027_16_36","EZK","16","36","36","כה אמר אדני יהוה יען השפך נחשתך ותגלה ערותך בתזנותיך על מאהביך ועל כל גלולי תועבותיך וכדמי בניך אשר נתת להם׃ ");
INSERT INTO heb_vpl VALUES ("EK16_37","027_16_37","EZK","16","37","37","לכן הנני מקבץ את כל מאהביך אשר ערבת עליהם ואת כל אשר אהבת על כל אשר שנאת וקבצתי אתם עליך מסביב וגליתי ערותך אלהם וראו את כל ערותך׃ ");
INSERT INTO heb_vpl VALUES ("EK16_38","027_16_38","EZK","16","38","38","ושפטתיך משפטי נאפות ושפכת דם ונתתיך דם חמה וקנאה׃ ");
INSERT INTO heb_vpl VALUES ("EK16_39","027_16_39","EZK","16","39","39","ונתתי אותך בידם והרסו גבך ונתצו רמתיך והפשיטו אותך בגדיך ולקחו כלי תפארתך והניחוך עירם ועריה׃ ");
INSERT INTO heb_vpl VALUES ("EK16_40","027_16_40","EZK","16","40","40","והעלו עליך קהל ורגמו אותך באבן ובתקוך בחרבותם׃ ");
