INSERT INTO heb_vpl VALUES ("EK16_48","027_16_48","EZK","16","48","48","חי אני נאם אדני יהוה אם עשתה סדם אחותך היא ובנותיה כאשר עשית את ובנותיך׃ ");
INSERT INTO heb_vpl VALUES ("EK16_49","027_16_49","EZK","16","49","49","הנה זה היה עון סדם אחותך גאון שבעת לחם ושלות השקט היה לה ולבנותיה ויד עני ואביון לא החזיקה׃ ");
INSERT INTO heb_vpl VALUES ("EK16_50","027_16_50","EZK","16","50","50","ותגבהינה ותעשינה תועבה לפני ואסיר אתהן כאשר ראיתי׃ ");
