INSERT INTO heb_vpl VALUES ("EK17_7","027_17_7","EZK","17","7","7","ויהי נשר אחד גדול גדול כנפים ורב נוצה והנה הגפן הזאת כפנה שרשיה עליו ודליותיו שלחה לו להשקות אותה מערגות מטעה׃ ");
