INSERT INTO heb_vpl VALUES ("EK17_9","027_17_9","EZK","17","9","9","אמר כה אמר אדני יהוה תצלח הלוא את שרשיה ינתק ואת פריה יקוסס ויבש כל טרפי צמחה תיבש ולא בזרע גדולה ובעם רב למשאות אותה משרשיה׃ ");
INSERT INTO heb_vpl VALUES ("EK17_10","027_17_10","EZK","17","10","10","והנה שתולה התצלח הלוא כגעת בה רוח הקדים תיבש יבש על ערגת צמחה תיבש׃ ");
INSERT INTO heb_vpl VALUES ("EK17_11","027_17_11","EZK","17","11","11","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK17_12","027_17_12","EZK","17","12","12","אמר נא לבית המרי הלא ידעתם מה אלה אמר הנה בא מלך בבל ירושלם ויקח את מלכה ואת שריה ויבא אותם אליו בבלה׃ ");
