INSERT INTO heb_vpl VALUES ("EK17_16","027_17_16","EZK","17","16","16","חי אני נאם אדני יהוה אם לא במקום המלך הממליך אתו אשר בזה את אלתו ואשר הפר את בריתו אתו בתוך בבל ימות׃ ");
INSERT INTO heb_vpl VALUES ("EK17_17","027_17_17","EZK","17","17","17","ולא בחיל גדול ובקהל רב יעשה אותו פרעה במלחמה בשפך סללה ובבנות דיק להכרית נפשות רבות׃ ");
INSERT INTO heb_vpl VALUES ("EK17_18","027_17_18","EZK","17","18","18","ובזה אלה להפר ברית והנה נתן ידו וכל אלה עשה לא ימלט׃ ");
INSERT INTO heb_vpl VALUES ("EK17_19","027_17_19","EZK","17","19","19","לכן כה אמר אדני יהוה חי אני אם לא אלתי אשר בזה ובריתי אשר הפיר ונתתיו בראשו׃ ");
INSERT INTO heb_vpl VALUES ("EK17_20","027_17_20","EZK","17","20","20","ופרשתי עליו רשתי ונתפש במצודתי והביאותיהו בבלה ונשפטתי אתו שם מעלו אשר מעל בי׃ ");
