INSERT INTO heb_vpl VALUES ("EK17_23","027_17_23","EZK","17","23","23","בהר מרום ישראל אשתלנו ונשא ענף ועשה פרי והיה לארז אדיר ושכנו תחתיו כל צפור כל כנף בצל דליותיו תשכנה׃ ");
