INSERT INTO heb_vpl VALUES ("EK18_21","027_18_21","EZK","18","21","21","והרשע כי ישוב מכל חטאתו אשר עשה ושמר את כל חקותי ועשה משפט וצדקה חיה יחיה לא ימות׃ ");
