INSERT INTO heb_vpl VALUES ("EK33_5","027_33_5","EZK","33","5","5","את קול השופר שמע ולא נזהר דמו בו יהיה והוא נזהר נפשו מלט׃ ");
INSERT INTO heb_vpl VALUES ("EK33_6","027_33_6","EZK","33","6","6","והצפה כי יראה את החרב באה ולא תקע בשופר והעם לא נזהר ותבוא חרב ותקח מהם נפש הוא בעונו נלקח ודמו מיד הצפה אדרש׃ ");
INSERT INTO heb_vpl VALUES ("EK33_7","027_33_7","EZK","33","7","7","ואתה בן אדם צפה נתתיך לבית ישראל ושמעת מפי דבר והזהרת אתם ממני׃ ");
INSERT INTO heb_vpl VALUES ("EK33_8","027_33_8","EZK","33","8","8","באמרי לרשע רשע מות תמות ולא דברת להזהיר רשע מדרכו הוא רשע בעונו ימות ודמו מידך אבקש׃ ");
INSERT INTO heb_vpl VALUES ("EK33_9","027_33_9","EZK","33","9","9","ואתה כי הזהרת רשע מדרכו לשוב ממנה ולא שב מדרכו הוא בעונו ימות ואתה נפשך הצלת׃ ");
INSERT INTO heb_vpl VALUES ("EK33_10","027_33_10","EZK","33","10","10","ואתה בן אדם אמר אל בית ישראל כן אמרתם לאמר כי פשעינו וחטאתינו עלינו ובם אנחנו נמקים ואיך נחיה׃ ");
INSERT INTO heb_vpl VALUES ("EK33_11","027_33_11","EZK","33","11","11","אמר אליהם חי אני נאם אדני יהוה אם אחפץ במות הרשע כי אם בשוב רשע מדרכו וחיה שובו שובו מדרכיכם הרעים ולמה תמותו בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK33_12","027_33_12","EZK","33","12","12","ואתה בן אדם אמר אל בני עמך צדקת הצדיק לא תצילנו ביום פשעו ורשעת הרשע לא יכשל בה ביום שובו מרשעו וצדיק לא יוכל לחיות בה ביום חטאתו׃ ");
INSERT INTO heb_vpl VALUES ("EK33_13","027_33_13","EZK","33","13","13","באמרי לצדיק חיה יחיה והוא בטה על צדקתו ועשה עול כל צדקתו לא תזכרנה ובעולו אשר עשה בו ימות׃ ");
INSERT INTO heb_vpl VALUES ("EK33_14","027_33_14","EZK","33","14","14","ובאמרי לרשע מות תמות ושב מחטאתו ועשה משפט וצדקה׃ ");
INSERT INTO heb_vpl VALUES ("EK33_15","027_33_15","EZK","33","15","15","חבל ישיב רשע גזלה ישלם בחקות החיים הלך לבלתי עשות עול חיו יחיה לא ימות׃ ");
INSERT INTO heb_vpl VALUES ("EK33_16","027_33_16","EZK","33","16","16","כל חטאתו אשר חטא לא תזכרנה לו משפט וצדקה עשה חיו יחיה׃ ");
INSERT INTO heb_vpl VALUES ("EK33_17","027_33_17","EZK","33","17","17","ואמרו בני עמך לא יתכן דרך אדני והמה דרכם לא יתכן׃ ");
INSERT INTO heb_vpl VALUES ("EK33_18","027_33_18","EZK","33","18","18","בשוב צדיק מצדקתו ועשה עול ומת בהם׃ ");
INSERT INTO heb_vpl VALUES ("EK33_19","027_33_19","EZK","33","19","19","ובשוב רשע מרשעתו ועשה משפט וצדקה עליהם הוא יחיה׃ ");
INSERT INTO heb_vpl VALUES ("EK33_20","027_33_20","EZK","33","20","20","ואמרתם לא יתכן דרך אדני איש כדרכיו אשפוט אתכם בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK33_21","027_33_21","EZK","33","21","21","ויהי בשתי עשרה שנה בעשרי בחמשה לחדש לגלותנו בא אלי הפליט מירושלם לאמר הכתה העיר׃ ");
INSERT INTO heb_vpl VALUES ("EK33_22","027_33_22","EZK","33","22","22","ויד יהוה היתה אלי בערב לפני בוא הפליט ויפתח את פי עד בוא אלי בבקר ויפתח פי ולא נאלמתי עוד׃ ");
INSERT INTO heb_vpl VALUES ("EK33_23","027_33_23","EZK","33","23","23","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK33_24","027_33_24","EZK","33","24","24","בן אדם ישבי החרבות האלה על אדמת ישראל אמרים לאמר אחד היה אברהם ויירש את הארץ ואנחנו רבים לנו נתנה הארץ למורשה׃ ");
INSERT INTO heb_vpl VALUES ("EK33_25","027_33_25","EZK","33","25","25","לכן אמר אלהם כה אמר אדני יהוה על הדם תאכלו ועינכם תשאו אל גלוליכם ודם תשפכו והארץ תירשו׃ ");
