INSERT INTO heb_vpl VALUES ("EK33_27","027_33_27","EZK","33","27","27","כה תאמר אלהם כה אמר אדני יהוה חי אני אם לא אשר בחרבות בחרב יפלו ואשר על פני השדה לחיה נתתיו לאכלו ואשר במצדות ובמערות בדבר ימותו׃ ");
INSERT INTO heb_vpl VALUES ("EK33_28","027_33_28","EZK","33","28","28","ונתתי את הארץ שממה ומשמה ונשבת גאון עזה ושממו הרי ישראל מאין עובר׃ ");
