INSERT INTO heb_vpl VALUES ("EK33_30","027_33_30","EZK","33","30","30","ואתה בן אדם בני עמך הנדברים בך אצל הקירות ובפתחי הבתים ודבר חד את אחד איש את אחיו לאמר באו נא ושמעו מה הדבר היוצא מאת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK33_31","027_33_31","EZK","33","31","31","ויבואו אליך כמבוא עם וישבו לפניך עמי ושמעו את דבריך ואותם לא יעשו כי עגבים בפיהם המה עשים אחרי בצעם לבם הלך׃ ");
INSERT INTO heb_vpl VALUES ("EK33_32","027_33_32","EZK","33","32","32","והנך להם כשיר עגבים יפה קול ומטב נגן ושמעו את דבריך ועשים אינם אותם׃ ");
INSERT INTO heb_vpl VALUES ("EK33_33","027_33_33","EZK","33","33","33","ובבאה הנה באה וידעו כי נביא היה בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("EK34_1","027_34_1","EZK","34","1","1","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK34_2","027_34_2","EZK","34","2","2","בן אדם הנבא על רועי ישראל הנבא ואמרת אליהם לרעים כה אמר אדני יהוה הוי רעי ישראל אשר היו רעים אותם הלוא הצאן ירעו הרעים׃ ");
INSERT INTO heb_vpl VALUES ("EK34_3","027_34_3","EZK","34","3","3","את החלב תאכלו ואת הצמר תלבשו הבריאה תזבחו הצאן לא תרעו׃ ");
INSERT INTO heb_vpl VALUES ("EK34_4","027_34_4","EZK","34","4","4","את הנחלות לא חזקתם ואת החולה לא רפאתם ולנשברת לא חבשתם ואת הנדחת לא השבתם ואת האבדת לא בקשתם ובחזקה רדיתם אתם ובפרך׃ ");
INSERT INTO heb_vpl VALUES ("EK34_5","027_34_5","EZK","34","5","5","ותפוצינה מבלי רעה ותהיינה לאכלה לכל חית השדה ותפוצינה׃ ");
INSERT INTO heb_vpl VALUES ("EK34_6","027_34_6","EZK","34","6","6","ישגו צאני בכל ההרים ועל כל גבעה רמה ועל כל פני הארץ נפצו צאני ואין דורש ואין מבקש׃ ");
INSERT INTO heb_vpl VALUES ("EK34_7","027_34_7","EZK","34","7","7","לכן רעים שמעו את דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK34_8","027_34_8","EZK","34","8","8","חי אני נאם אדני יהוה אם לא יען היות צאני לבז ותהיינה צאני לאכלה לכל חית השדה מאין רעה ולא דרשו רעי את צאני וירעו הרעים אותם ואת צאני לא רעו׃ ");
