INSERT INTO heb_vpl VALUES ("EK36_3","027_36_3","EZK","36","3","3","לכן הנבא ואמרת כה אמר אדני יהוה יען ביען שמות ושאף אתכם מסביב להיותכם מורשה לשארית הגוים ותעלו על שפת לשון ודבת עם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_4","027_36_4","EZK","36","4","4","לכן הרי ישראל שמעו דבר אדני יהוה כה אמר אדני יהוה להרים ולגבעות לאפיקים ולגאיות ולחרבות השממות ולערים הנעזבות אשר היו לבז וללעג לשארית הגוים אשר מסביב׃ ");
INSERT INTO heb_vpl VALUES ("EK36_5","027_36_5","EZK","36","5","5","לכן כה אמר אדני יהוה אם לא באש קנאתי דברתי על שארית הגוים ועל אדום כלא אשר נתנו את ארצי להם למורשה בשמחת כל לבב בשאט נפש למען מגרשה לבז׃ ");
INSERT INTO heb_vpl VALUES ("EK36_6","027_36_6","EZK","36","6","6","לכן הנבא על אדמת ישראל ואמרת להרים ולגבעות לאפיקים ולגאיות כה אמר אדני יהוה הנני בקנאתי ובחמתי דברתי יען כלמת גוים נשאתם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_7","027_36_7","EZK","36","7","7","לכן כה אמר אדני יהוה אני נשאתי את ידי אם לא הגוים אשר לכם מסביב המה כלמתם ישאו׃ ");
INSERT INTO heb_vpl VALUES ("EK36_8","027_36_8","EZK","36","8","8","ואתם הרי ישראל ענפכם תתנו ופריכם תשאו לעמי ישראל כי קרבו לבוא׃ ");
INSERT INTO heb_vpl VALUES ("EK36_9","027_36_9","EZK","36","9","9","כי הנני אליכם ופניתי אליכם ונעבדתם ונזרעתם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_10","027_36_10","EZK","36","10","10","והרביתי עליכם אדם כל בית ישראל כלה ונשבו הערים והחרבות תבנינה׃ ");
INSERT INTO heb_vpl VALUES ("EK36_11","027_36_11","EZK","36","11","11","והרביתי עליכם אדם ובהמה ורבו ופרו והושבתי אתכם כקדמותיכם והיטבתי מראשתיכם וידעתם כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK36_12","027_36_12","EZK","36","12","12","והולכתי עליכם אדם את עמי ישראל וירשוך והיית להם לנחלה ולא תוסף עוד לשכלם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_13","027_36_13","EZK","36","13","13","כה אמר אדני יהוה יען אמרים לכם אכלת אדם אתי ומשכלת גויך היית׃ ");
INSERT INTO heb_vpl VALUES ("EK36_14","027_36_14","EZK","36","14","14","לכן אדם לא תאכלי עוד וגויך לא תכשלי עוד נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK36_15","027_36_15","EZK","36","15","15","ולא אשמיע אליך עוד כלמת הגוים וחרפת עמים לא תשאי עוד וגויך לא תכשלי עוד נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK36_16","027_36_16","EZK","36","16","16","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK36_17","027_36_17","EZK","36","17","17","בן אדם בית ישראל ישבים על אדמתם ויטמאו אותה בדרכם ובעלילותם כטמאת הנדה היתה דרכם לפני׃ ");
INSERT INTO heb_vpl VALUES ("EK36_18","027_36_18","EZK","36","18","18","ואשפך חמתי עליהם על הדם אשר שפכו על הארץ ובגלוליהם טמאוה׃ ");
INSERT INTO heb_vpl VALUES ("EK36_19","027_36_19","EZK","36","19","19","ואפיץ אתם בגוים ויזרו בארצות כדרכם וכעלילותם שפטתים׃ ");
INSERT INTO heb_vpl VALUES ("EK36_20","027_36_20","EZK","36","20","20","ויבוא אל הגוים אשר באו שם ויחללו את שם קדשי באמר להם עם יהוה אלה ומארצו יצאו׃ ");
INSERT INTO heb_vpl VALUES ("EK36_21","027_36_21","EZK","36","21","21","ואחמל על שם קדשי אשר חללוהו בית ישראל בגוים אשר באו שמה׃ ");
INSERT INTO heb_vpl VALUES ("EK36_22","027_36_22","EZK","36","22","22","לכן אמר לבית ישראל כה אמר אדני יהוה לא למענכם אני עשה בית ישראל כי אם לשם קדשי אשר חללתם בגוים אשר באתם שם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_23","027_36_23","EZK","36","23","23","וקדשתי את שמי הגדול המחלל בגוים אשר חללתם בתוכם וידעו הגוים כי אני יהוה נאם אדני יהוה בהקדשי בכם לעיניהם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_24","027_36_24","EZK","36","24","24","ולקחתי אתכם מן הגוים וקבצתי אתכם מכל הארצות והבאתי אתכם אל אדמתכם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_25","027_36_25","EZK","36","25","25","וזרקתי עליכם מים טהורים וטהרתם מכל טמאותיכם ומכל גלוליכם אטהר אתכם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_26","027_36_26","EZK","36","26","26","ונתתי לכם לב חדש ורוח חדשה אתן בקרבכם והסרתי את לב האבן מבשרכם ונתתי לכם לב בשר׃ ");
INSERT INTO heb_vpl VALUES ("EK36_27","027_36_27","EZK","36","27","27","ואת רוחי אתן בקרבכם ועשיתי את אשר בחקי תלכו ומשפטי תשמרו ועשיתם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_28","027_36_28","EZK","36","28","28","וישבתם בארץ אשר נתתי לאבתיכם והייתם לי לעם ואנכי אהיה לכם לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("EK36_29","027_36_29","EZK","36","29","29","והושעתי אתכם מכל טמאותיכם וקראתי אל הדגן והרביתי אתו ולא אתן עליכם רעב׃ ");
INSERT INTO heb_vpl VALUES ("EK36_30","027_36_30","EZK","36","30","30","והרביתי את פרי העץ ותנובת השדה למען אשר לא תקחו עוד חרפת רעב בגוים׃ ");
INSERT INTO heb_vpl VALUES ("EK36_31","027_36_31","EZK","36","31","31","וזכרתם את דרכיכם הרעים ומעלליכם אשר לא טובים ונקטתם בפניכם על עונתיכם ועל תועבתיכם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_32","027_36_32","EZK","36","32","32","לא למענכם אני עשה נאם אדני יהוה יודע לכם בושו והכלמו מדרכיכם בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK36_33","027_36_33","EZK","36","33","33","כה אמר אדני יהוה ביום טהרי אתכם מכל עונותיכם והושבתי את הערים ונבנו החרבות׃ ");
INSERT INTO heb_vpl VALUES ("EK36_34","027_36_34","EZK","36","34","34","והארץ הנשמה תעבד תחת אשר היתה שממה לעיני כל עובר׃ ");
INSERT INTO heb_vpl VALUES ("EK36_35","027_36_35","EZK","36","35","35","ואמרו הארץ הלזו הנשמה היתה כגן עדן והערים החרבות והנשמות והנהרסות בצורות ישבו׃ ");
INSERT INTO heb_vpl VALUES ("EK36_36","027_36_36","EZK","36","36","36","וידעו הגוים אשר ישארו סביבותיכם כי אני יהוה בניתי הנהרסות נטעתי הנשמה אני יהוה דברתי ועשיתי׃ ");
INSERT INTO heb_vpl VALUES ("EK36_37","027_36_37","EZK","36","37","37","כה אמר אדני יהוה עוד זאת אדרש לבית ישראל לעשות להם ארבה אתם כצאן אדם׃ ");
INSERT INTO heb_vpl VALUES ("EK36_38","027_36_38","EZK","36","38","38","כצאן קדשים כצאן ירושלם במועדיה כן תהיינה הערים החרבות מלאות צאן אדם וידעו כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK37_1","027_37_1","EZK","37","1","1","היתה עלי יד יהוה ויוצאני ברוח יהוה ויניחני בתוך הבקעה והיא מלאה עצמות׃ ");
INSERT INTO heb_vpl VALUES ("EK37_2","027_37_2","EZK","37","2","2","והעבירני עליהם סביב סביב והנה רבות מאד על פני הבקעה והנה יבשות מאד׃ ");
INSERT INTO heb_vpl VALUES ("EK37_3","027_37_3","EZK","37","3","3","ויאמר אלי בן אדם התחיינה העצמות האלה ואמר אדני יהוה אתה ידעת׃ ");
INSERT INTO heb_vpl VALUES ("EK37_4","027_37_4","EZK","37","4","4","ויאמר אלי הנבא על העצמות האלה ואמרת אליהם העצמות היבשות שמעו דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK37_5","027_37_5","EZK","37","5","5","כה אמר אדני יהוה לעצמות האלה הנה אני מביא בכם רוח וחייתם׃ ");
INSERT INTO heb_vpl VALUES ("EK37_6","027_37_6","EZK","37","6","6","ונתתי עליכם גדים והעלתי עליכם בשר וקרמתי עליכם עור ונתתי בכם רוח וחייתם וידעתם כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK37_7","027_37_7","EZK","37","7","7","ונבאתי כאשר צויתי ויהי קול כהנבאי והנה רעש ותקרבו עצמות עצם אל עצמו׃ ");
INSERT INTO heb_vpl VALUES ("EK37_8","027_37_8","EZK","37","8","8","וראיתי והנה עליהם גדים ובשר עלה ויקרם עליהם עור מלמעלה ורוח אין בהם׃ ");
INSERT INTO heb_vpl VALUES ("EK37_9","027_37_9","EZK","37","9","9","ויאמר אלי הנבא אל הרוח הנבא בן אדם ואמרת אל הרוח כה אמר אדני יהוה מארבע רוחות באי הרוח ופחי בהרוגים האלה ויחיו׃ ");
INSERT INTO heb_vpl VALUES ("EK37_10","027_37_10","EZK","37","10","10","והנבאתי כאשר צוני ותבוא בהם הרוח ויחיו ויעמדו על רגליהם חיל גדול מאד מאד׃ ");
INSERT INTO heb_vpl VALUES ("EK37_11","027_37_11","EZK","37","11","11","ויאמר אלי בן אדם העצמות האלה כל בית ישראל המה הנה אמרים יבשו עצמותינו ואבדה תקותנו נגזרנו לנו׃ ");
INSERT INTO heb_vpl VALUES ("EK37_12","027_37_12","EZK","37","12","12","לכן הנבא ואמרת אליהם כה אמר אדני יהוה הנה אני פתח את קברותיכם והעליתי אתכם מקברותיכם עמי והבאתי אתכם אל אדמת ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK37_13","027_37_13","EZK","37","13","13","וידעתם כי אני יהוה בפתחי את קברותיכם ובהעלותי אתכם מקברותיכם עמי׃ ");
INSERT INTO heb_vpl VALUES ("EK37_14","027_37_14","EZK","37","14","14","ונתתי רוחי בכם וחייתם והנחתי אתכם על אדמתכם וידעתם כי אני יהוה דברתי ועשיתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK37_15","027_37_15","EZK","37","15","15","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK37_16","027_37_16","EZK","37","16","16","ואתה בן אדם קח לך עץ אחד וכתב עליו ליהודה ולבני ישראל חברו ולקח עץ אחד וכתוב עליו ליוסף עץ אפרים וכל בית ישראל חברו׃ ");
INSERT INTO heb_vpl VALUES ("EK37_17","027_37_17","EZK","37","17","17","וקרב אתם אחד אל אחד לך לעץ אחד והיו לאחדים בידך׃ ");
INSERT INTO heb_vpl VALUES ("EK37_18","027_37_18","EZK","37","18","18","וכאשר יאמרו אליך בני עמך לאמר הלוא תגיד לנו מה אלה לך׃ ");
INSERT INTO heb_vpl VALUES ("EK37_19","027_37_19","EZK","37","19","19","דבר אלהם כה אמר אדני יהוה הנה אני לקח את עץ יוסף אשר ביד אפרים ושבטי ישראל חברו ונתתי אותם עליו את עץ יהודה ועשיתם לעץ אחד והיו אחד בידי׃ ");
INSERT INTO heb_vpl VALUES ("EK37_20","027_37_20","EZK","37","20","20","והיו העצים אשר תכתב עליהם בידך לעיניהם׃ ");
INSERT INTO heb_vpl VALUES ("EK37_21","027_37_21","EZK","37","21","21","ודבר אליהם כה אמר אדני יהוה הנה אני לקח את בני ישראל מבין הגוים אשר הלכו שם וקבצתי אתם מסביב והבאתי אותם אל אדמתם׃ ");
INSERT INTO heb_vpl VALUES ("EK37_22","027_37_22","EZK","37","22","22","ועשיתי אתם לגוי אחד בארץ בהרי ישראל ומלך אחד יהיה לכלם למלך ולא יהיה עוד לשני גוים ולא יחצו עוד לשתי ממלכות עוד׃ ");
INSERT INTO heb_vpl VALUES ("EK37_23","027_37_23","EZK","37","23","23","ולא יטמאו עוד בגלוליהם ובשקוציהם ובכל פשעיהם והושעתי אתם מכל מושבתיהם אשר חטאו בהם וטהרתי אותם והיו לי לעם ואני אהיה להם לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("EK37_24","027_37_24","EZK","37","24","24","ועבדי דוד מלך עליהם ורועה אחד יהיה לכלם ובמשפטי ילכו וחקתי ישמרו ועשו אותם׃ ");
INSERT INTO heb_vpl VALUES ("EK37_25","027_37_25","EZK","37","25","25","וישבו על הארץ אשר נתתי לעבדי ליעקב אשר ישבו בה אבותיכם וישבו עליה המה ובניהם ובני בניהם עד עולם ודוד עבדי נשיא להם לעולם׃ ");
INSERT INTO heb_vpl VALUES ("EK37_26","027_37_26","EZK","37","26","26","וכרתי להם ברית שלום ברית עולם יהיה אותם ונתתים והרביתי אותם ונתתי את מקדשי בתוכם לעולם׃ ");
INSERT INTO heb_vpl VALUES ("EK37_27","027_37_27","EZK","37","27","27","והיה משכני עליהם והייתי להם לאלהים והמה יהיו לי לעם׃ ");
INSERT INTO heb_vpl VALUES ("EK37_28","027_37_28","EZK","37","28","28","וידעו הגוים כי אני יהוה מקדש את ישראל בהיות מקדשי בתוכם לעולם׃ ");
INSERT INTO heb_vpl VALUES ("EK38_1","027_38_1","EZK","38","1","1","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("EK38_2","027_38_2","EZK","38","2","2","בן אדם שים פניך אל גוג ארץ המגוג נשיא ראש משך ותבל והנבא עליו׃ ");
INSERT INTO heb_vpl VALUES ("EK38_3","027_38_3","EZK","38","3","3","ואמרת כה אמר אדני יהוה הנני אליך גוג נשיא ראש משך ותבל׃ ");
INSERT INTO heb_vpl VALUES ("EK38_4","027_38_4","EZK","38","4","4","ושובבתיך ונתתי חחים בלחייך והוצאתי אותך ואת כל חילך סוסים ופרשים לבשי מכלול כלם קהל רב צנה ומגן תפשי חרבות כלם׃ ");
INSERT INTO heb_vpl VALUES ("EK38_5","027_38_5","EZK","38","5","5","פרס כוש ופוט אתם כלם מגן וכובע׃ ");
INSERT INTO heb_vpl VALUES ("EK38_6","027_38_6","EZK","38","6","6","גמר וכל אגפיה בית תוגרמה ירכתי צפון ואת כל אגפיו עמים רבים אתך׃ ");
INSERT INTO heb_vpl VALUES ("EK38_7","027_38_7","EZK","38","7","7","הכן והכן לך אתה וכל קהלך הנקהלים עליך והיית להם למשמר׃ ");
INSERT INTO heb_vpl VALUES ("EK38_8","027_38_8","EZK","38","8","8","מימים רבים תפקד באחרית השנים תבוא אל ארץ משובבת מחרב מקבצת מעמים רבים על הרי ישראל אשר היו לחרבה תמיד והיא מעמים הוצאה וישבו לבטח כלם׃ ");
INSERT INTO heb_vpl VALUES ("EK38_9","027_38_9","EZK","38","9","9","ועלית כשאה תבוא כענן לכסות הארץ תהיה אתה וכל אגפיך ועמים רבים אותך׃ ");
INSERT INTO heb_vpl VALUES ("EK38_10","027_38_10","EZK","38","10","10","כה אמר אדני יהוה והיה ביום ההוא יעלו דברים על לבבך וחשבת מחשבת רעה׃ ");
INSERT INTO heb_vpl VALUES ("EK38_11","027_38_11","EZK","38","11","11","ואמרת אעלה על ארץ פרזות אבוא השקטים ישבי לבטח כלם ישבים באין חומה ובריח ודלתים אין להם׃ ");
INSERT INTO heb_vpl VALUES ("EK38_12","027_38_12","EZK","38","12","12","לשלל שלל ולבז בז להשיב ידך על חרבות נושבת ואל עם מאסף מגוים עשה מקנה וקנין ישבי על טבור הארץ׃ ");
INSERT INTO heb_vpl VALUES ("EK38_13","027_38_13","EZK","38","13","13","שבא ודדן וסחרי תרשיש וכל כפריה יאמרו לך הלשלל שלל אתה בא הלבז בז הקהלת קהלך לשאת כסף וזהב לקחת מקנה וקנין לשלל שלל גדול׃ ");
INSERT INTO heb_vpl VALUES ("EK38_14","027_38_14","EZK","38","14","14","לכן הנבא בן אדם ואמרת לגוג כה אמר אדני יהוה הלוא ביום ההוא בשבת עמי ישראל לבטח תדע׃ ");
INSERT INTO heb_vpl VALUES ("EK38_15","027_38_15","EZK","38","15","15","ובאת ממקומך מירכתי צפון אתה ועמים רבים אתך רכבי סוסים כלם קהל גדול וחיל רב׃ ");
INSERT INTO heb_vpl VALUES ("EK38_16","027_38_16","EZK","38","16","16","ועלית על עמי ישראל כענן לכסות הארץ באחרית הימים תהיה והבאותיך על ארצי למען דעת הגוים אתי בהקדשי בך לעיניהם גוג׃ ");
INSERT INTO heb_vpl VALUES ("EK38_17","027_38_17","EZK","38","17","17","כה אמר אדני יהוה האתה הוא אשר דברתי בימים קדמונים ביד עבדי נביאי ישראל הנבאים בימים ההם שנים להביא אתך עליהם׃ ");
INSERT INTO heb_vpl VALUES ("EK38_18","027_38_18","EZK","38","18","18","והיה ביום ההוא ביום בוא גוג על אדמת ישראל נאם אדני יהוה תעלה חמתי באפי׃ ");
INSERT INTO heb_vpl VALUES ("EK38_19","027_38_19","EZK","38","19","19","ובקנאתי באש עברתי דברתי אם לא ביום ההוא יהיה רעש גדול על אדמת ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK38_20","027_38_20","EZK","38","20","20","ורעשו מפני דגי הים ועוף השמים וחית השדה וכל הרמש הרמש על האדמה וכל האדם אשר על פני האדמה ונהרסו ההרים ונפלו המדרגות וכל חומה לארץ תפול׃ ");
INSERT INTO heb_vpl VALUES ("EK38_21","027_38_21","EZK","38","21","21","וקראתי עליו לכל הרי חרב נאם אדני יהוה חרב איש באחיו תהיה׃ ");
INSERT INTO heb_vpl VALUES ("EK38_22","027_38_22","EZK","38","22","22","ונשפטתי אתו בדבר ובדם וגשם שוטף ואבני אלגביש אש וגפרית אמטיר עליו ועל אגפיו ועל עמים רבים אשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("EK38_23","027_38_23","EZK","38","23","23","והתגדלתי והתקדשתי ונודעתי לעיני גוים רבים וידעו כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK39_1","027_39_1","EZK","39","1","1","ואתה בן אדם הנבא על גוג ואמרת כה אמר אדני יהוה הנני אליך גוג נשיא ראש משך ותבל׃ ");
INSERT INTO heb_vpl VALUES ("EK39_2","027_39_2","EZK","39","2","2","ושבבתיך וששאתיך והעליתיך מירכתי צפון והבאותך על הרי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK39_3","027_39_3","EZK","39","3","3","והכיתי קשתך מיד שמאולך וחציך מיד ימינך אפיל׃ ");
INSERT INTO heb_vpl VALUES ("EK39_4","027_39_4","EZK","39","4","4","על הרי ישראל תפול אתה וכל אגפיך ועמים אשר אתך לעיט צפור כל כנף וחית השדה נתתיך לאכלה׃ ");
INSERT INTO heb_vpl VALUES ("EK39_5","027_39_5","EZK","39","5","5","על פני השדה תפול כי אני דברתי נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK39_6","027_39_6","EZK","39","6","6","ושלחתי אש במגוג ובישבי האיים לבטח וידעו כי אני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK39_7","027_39_7","EZK","39","7","7","ואת שם קדשי אודיע בתוך עמי ישראל ולא אחל את שם קדשי עוד וידעו הגוים כי אני יהוה קדוש בישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK39_8","027_39_8","EZK","39","8","8","הנה באה ונהיתה נאם אדני יהוה הוא היום אשר דברתי׃ ");
INSERT INTO heb_vpl VALUES ("EK39_9","027_39_9","EZK","39","9","9","ויצאו ישבי ערי ישראל ובערו והשיקו בנשק ומגן וצנה בקשת ובחצים ובמקל יד וברמח ובערו בהם אש שבע שנים׃ ");
INSERT INTO heb_vpl VALUES ("EK39_10","027_39_10","EZK","39","10","10","ולא ישאו עצים מן השדה ולא יחטבו מן היערים כי בנשק יבערו אש ושללו את שלליהם ובזזו את בזזיהם נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK39_11","027_39_11","EZK","39","11","11","והיה ביום ההוא אתן לגוג מקום שם קבר בישראל גי העברים קדמת הים וחסמת היא את העברים וקברו שם את גוג ואת כל המונה וקראו גיא המון גוג׃ ");
INSERT INTO heb_vpl VALUES ("EK39_12","027_39_12","EZK","39","12","12","וקברום בית ישראל למען טהר את הארץ שבעה חדשים׃ ");
INSERT INTO heb_vpl VALUES ("EK39_13","027_39_13","EZK","39","13","13","וקברו כל עם הארץ והיה להם לשם יום הכבדי נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK39_14","027_39_14","EZK","39","14","14","ואנשי תמיד יבדילו עברים בארץ מקברים את העברים את הנותרים על פני הארץ לטהרה מקצה שבעה חדשים יחקרו׃ ");
INSERT INTO heb_vpl VALUES ("EK39_15","027_39_15","EZK","39","15","15","ועברו העברים בארץ וראה עצם אדם ובנה אצלו ציון עד קברו אתו המקברים אל גיא המון גוג׃ ");
INSERT INTO heb_vpl VALUES ("EK39_16","027_39_16","EZK","39","16","16","וגם שם עיר המונה וטהרו הארץ׃ ");
INSERT INTO heb_vpl VALUES ("EK39_17","027_39_17","EZK","39","17","17","ואתה בן אדם כה אמר אדני יהוה אמר לצפור כל כנף ולכל חית השדה הקבצו ובאו האספו מסביב על זבחי אשר אני זבח לכם זבח גדול על הרי ישראל ואכלתם בשר ושתיתם דם׃ ");
INSERT INTO heb_vpl VALUES ("EK39_18","027_39_18","EZK","39","18","18","בשר גבורים תאכלו ודם נשיאי הארץ תשתו אילים כרים ועתודים פרים מריאי בשן כלם׃ ");
