INSERT INTO heb_vpl VALUES ("EK39_21","027_39_21","EZK","39","21","21","ונתתי את כבודי בגוים וראו כל הגוים את משפטי אשר עשיתי ואת ידי אשר שמתי בהם׃ ");
INSERT INTO heb_vpl VALUES ("EK39_22","027_39_22","EZK","39","22","22","וידעו בית ישראל כי אני יהוה אלהיהם מן היום ההוא והלאה׃ ");
