INSERT INTO heb_vpl VALUES ("EK39_24","027_39_24","EZK","39","24","24","כטמאתם וכפשעיהם עשיתי אתם ואסתר פני מהם׃ ");
INSERT INTO heb_vpl VALUES ("EK39_25","027_39_25","EZK","39","25","25","לכן כה אמר אדני יהוה עתה אשיב את שבית יעקב ורחמתי כל בית ישראל וקנאתי לשם קדשי׃ ");
