INSERT INTO heb_vpl VALUES ("EK40_3","027_40_3","EZK","40","3","3","ויביא אותי שמה והנה איש מראהו כמראה נחשת ופתיל פשתים בידו וקנה המדה והוא עמד בשער׃ ");
