INSERT INTO heb_vpl VALUES ("EK43_26","027_43_26","EZK","43","26","26","שבעת ימים יכפרו את המזבח וטהרו אתו ומלאו ידו׃ ");
INSERT INTO heb_vpl VALUES ("EK43_27","027_43_27","EZK","43","27","27","ויכלו את הימים והיה ביום השמיני והלאה יעשו הכהנים על המזבח את עולותיכם ואת שלמיכם ורצאתי אתכם נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK44_1","027_44_1","EZK","44","1","1","וישב אתי דרך שער המקדש החיצון הפנה קדים והוא סגור׃ ");
INSERT INTO heb_vpl VALUES ("EK44_2","027_44_2","EZK","44","2","2","ויאמר אלי יהוה השער הזה סגור יהיה לא יפתח ואיש לא יבא בו כי יהוה אלהי ישראל בא בו והיה סגור׃ ");
INSERT INTO heb_vpl VALUES ("EK44_3","027_44_3","EZK","44","3","3","את הנשיא נשיא הוא ישב בו לאכול לחם לפני יהוה מדרך אלם השער יבוא ומדרכו יצא׃ ");
INSERT INTO heb_vpl VALUES ("EK44_4","027_44_4","EZK","44","4","4","ויביאני דרך שער הצפון אל פני הבית וארא והנה מלא כבוד יהוה את בית יהוה ואפל אל פני׃ ");
INSERT INTO heb_vpl VALUES ("EK44_5","027_44_5","EZK","44","5","5","ויאמר אלי יהוה בן אדם שים לבך וראה בעיניך ובאזניך שמע את כל אשר אני מדבר אתך לכל חקות בית יהוה ולכל תורתו ושמת לבך למבוא הבית בכל מוצאי המקדש׃ ");
INSERT INTO heb_vpl VALUES ("EK44_6","027_44_6","EZK","44","6","6","ואמרת אל מרי אל בית ישראל כה אמר אדני יהוה רב לכם מכל תועבותיכם בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK44_7","027_44_7","EZK","44","7","7","בהביאכם בני נכר ערלי לב וערלי בשר להיות במקדשי לחללו את ביתי בהקריבכם את לחמי חלב ודם ויפרו את בריתי אל כל תועבותיכם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_8","027_44_8","EZK","44","8","8","ולא שמרתם משמרת קדשי ותשימון לשמרי משמרתי במקדשי לכם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_9","027_44_9","EZK","44","9","9","כה אמר אדני יהוה כל בן נכר ערל לב וערל בשר לא יבוא אל מקדשי לכל בן נכר אשר בתוך בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK44_10","027_44_10","EZK","44","10","10","כי אם הלוים אשר רחקו מעלי בתעות ישראל אשר תעו מעלי אחרי גלוליהם ונשאו עונם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_11","027_44_11","EZK","44","11","11","והיו במקדשי משרתים פקדות אל שערי הבית ומשרתים את הבית המה ישחטו את העלה ואת הזבח לעם והמה יעמדו לפניהם לשרתם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_12","027_44_12","EZK","44","12","12","יען אשר ישרתו אותם לפני גלוליהם והיו לבית ישראל למכשול עון על כן נשאתי ידי עליהם נאם אדני יהוה ונשאו עונם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_13","027_44_13","EZK","44","13","13","ולא יגשו אלי לכהן לי ולגשת על כל קדשי אל קדשי הקדשים ונשאו כלמתם ותועבותם אשר עשו׃ ");
INSERT INTO heb_vpl VALUES ("EK44_14","027_44_14","EZK","44","14","14","ונתתי אותם שמרי משמרת הבית לכל עבדתו ולכל אשר יעשה בו׃ ");
INSERT INTO heb_vpl VALUES ("EK44_15","027_44_15","EZK","44","15","15","והכהנים הלוים בני צדוק אשר שמרו את משמרת מקדשי בתעות בני ישראל מעלי המה יקרבו אלי לשרתני ועמדו לפני להקריב לי חלב ודם נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK44_16","027_44_16","EZK","44","16","16","המה יבאו אל מקדשי והמה יקרבו אל שלחני לשרתני ושמרו את משמרתי׃ ");
INSERT INTO heb_vpl VALUES ("EK44_17","027_44_17","EZK","44","17","17","והיה בבואם אל שערי החצר הפנימית בגדי פשתים ילבשו ולא יעלה עליהם צמר בשרתם בשערי החצר הפנימית וביתה׃ ");
INSERT INTO heb_vpl VALUES ("EK44_18","027_44_18","EZK","44","18","18","פארי פשתים יהיו על ראשם ומכנסי פשתים יהיו על מתניהם לא יחגרו ביזע׃ ");
INSERT INTO heb_vpl VALUES ("EK44_19","027_44_19","EZK","44","19","19","ובצאתם אל החצר החיצונה אל החצר החיצונה אל העם יפשטו את בגדיהם אשר המה משרתם בם והניחו אותם בלשכת הקדש ולבשו בגדים אחרים ולא יקדשו את העם בבגדיהם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_20","027_44_20","EZK","44","20","20","וראשם לא יגלחו ופרע לא ישלחו כסום יכסמו את ראשיהם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_21","027_44_21","EZK","44","21","21","ויין לא ישתו כל כהן בבואם אל החצר הפנימית׃ ");
INSERT INTO heb_vpl VALUES ("EK44_22","027_44_22","EZK","44","22","22","ואלמנה וגרושה לא יקחו להם לנשים כי אם בתולת מזרע בית ישראל והאלמנה אשר תהיה אלמנה מכהן יקחו׃ ");
INSERT INTO heb_vpl VALUES ("EK44_23","027_44_23","EZK","44","23","23","ואת עמי יורו בין קדש לחל ובין טמא לטהור יודעם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_24","027_44_24","EZK","44","24","24","ועל ריב המה יעמדו לשפט במשפטי ושפטהו ואת תורתי ואת חקתי בכל מועדי ישמרו ואת שבתותי יקדשו׃ ");
INSERT INTO heb_vpl VALUES ("EK44_25","027_44_25","EZK","44","25","25","ואל מת אדם לא יבוא לטמאה כי אם לאב ולאם ולבן ולבת לאח ולאחות אשר לא היתה לאיש יטמאו׃ ");
INSERT INTO heb_vpl VALUES ("EK44_26","027_44_26","EZK","44","26","26","ואחרי טהרתו שבעת ימים יספרו לו׃ ");
INSERT INTO heb_vpl VALUES ("EK44_27","027_44_27","EZK","44","27","27","וביום באו אל הקדש אל החצר הפנימית לשרת בקדש יקריב חטאתו נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK44_28","027_44_28","EZK","44","28","28","והיתה להם לנחלה אני נחלתם ואחזה לא תתנו להם בישראל אני אחזתם׃ ");
INSERT INTO heb_vpl VALUES ("EK44_29","027_44_29","EZK","44","29","29","המנחה והחטאת והאשם המה יאכלום וכל חרם בישראל להם יהיה׃ ");
INSERT INTO heb_vpl VALUES ("EK44_30","027_44_30","EZK","44","30","30","וראשית כל בכורי כל וכל תרומת כל מכל תרומותיכם לכהנים יהיה וראשית ערסותיכם תתנו לכהן להניח ברכה אל ביתך׃ ");
INSERT INTO heb_vpl VALUES ("EK44_31","027_44_31","EZK","44","31","31","כל נבלה וטרפה מן העוף ומן הבהמה לא יאכלו הכהנים׃ ");
INSERT INTO heb_vpl VALUES ("EK45_1","027_45_1","EZK","45","1","1","ובהפילכם את הארץ בנחלה תרימו תרומה ליהוה קדש מן הארץ ארך חמשה ועשרים אלף ארך ורחב עשרה אלף קדש הוא בכל גבולה סביב׃ ");
INSERT INTO heb_vpl VALUES ("EK45_2","027_45_2","EZK","45","2","2","יהיה מזה אל הקדש חמש מאות בחמש מאות מרבע סביב וחמשים אמה מגרש לו סביב׃ ");
INSERT INTO heb_vpl VALUES ("EK45_3","027_45_3","EZK","45","3","3","ומן המדה הזאת תמוד ארך חמש ועשרים אלף ורחב עשרת אלפים ובו יהיה המקדש קדש קדשים׃ ");
INSERT INTO heb_vpl VALUES ("EK45_4","027_45_4","EZK","45","4","4","קדש מן הארץ הוא לכהנים משרתי המקדש יהיה הקרבים לשרת את יהוה והיה להם מקום לבתים ומקדש למקדש׃ ");
INSERT INTO heb_vpl VALUES ("EK45_5","027_45_5","EZK","45","5","5","וחמשה ועשרים אלף ארך ועשרת אלפים רחב יהיה ללוים משרתי הבית להם לאחזה עשרים לשכת׃ ");
INSERT INTO heb_vpl VALUES ("EK45_6","027_45_6","EZK","45","6","6","ואחזת העיר תתנו חמשת אלפים רחב וארך חמשה ועשרים אלף לעמת תרומת הקדש לכל בית ישראל יהיה׃ ");
INSERT INTO heb_vpl VALUES ("EK45_7","027_45_7","EZK","45","7","7","ולנשיא מזה ומזה לתרומת הקדש ולאחזת העיר אל פני תרומת הקדש ואל פני אחזת העיר מפאת ים ימה ומפאת קדמה קדימה וארך לעמות אחד החלקים מגבול ים אל גבול קדימה׃ ");
INSERT INTO heb_vpl VALUES ("EK45_8","027_45_8","EZK","45","8","8","לארץ יהיה לו לאחזה בישראל ולא יונו עוד נשיאי את עמי והארץ יתנו לבית ישראל לשבטיהם׃ ");
INSERT INTO heb_vpl VALUES ("EK45_9","027_45_9","EZK","45","9","9","כה אמר אדני יהוה רב לכם נשיאי ישראל חמס ושד הסירו ומשפט וצדקה עשו הרימו גרשתיכם מעל עמי נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK45_10","027_45_10","EZK","45","10","10","מאזני צדק ואיפת צדק ובת צדק יהי לכם׃ ");
INSERT INTO heb_vpl VALUES ("EK45_11","027_45_11","EZK","45","11","11","האיפה והבת תכן אחד יהיה לשאת מעשר החמר הבת ועשירת החמר האיפה אל החמר יהיה מתכנתו׃ ");
INSERT INTO heb_vpl VALUES ("EK45_12","027_45_12","EZK","45","12","12","והשקל עשרים גרה עשרים שקלים חמשה ועשרים שקלים עשרה וחמשה שקל המנה יהיה לכם׃ ");
INSERT INTO heb_vpl VALUES ("EK45_13","027_45_13","EZK","45","13","13","זאת התרומה אשר תרימו ששית האיפה מחמר החטים וששיתם האיפה מחמר השערים׃ ");
INSERT INTO heb_vpl VALUES ("EK45_14","027_45_14","EZK","45","14","14","וחק השמן הבת השמן מעשר הבת מן הכר עשרת הבתים חמר כי עשרת הבתים חמר׃ ");
INSERT INTO heb_vpl VALUES ("EK45_15","027_45_15","EZK","45","15","15","ושה אחת מן הצאן מן המאתים ממשקה ישראל למנחה ולעולה ולשלמים לכפר עליהם נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK45_16","027_45_16","EZK","45","16","16","כל העם הארץ יהיו אל התרומה הזאת לנשיא בישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK45_17","027_45_17","EZK","45","17","17","ועל הנשיא יהיה העולות והמנחה והנסך בחגים ובחדשים ובשבתות בכל מועדי בית ישראל הוא יעשה את החטאת ואת המנחה ואת העולה ואת השלמים לכפר בעד בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK45_18","027_45_18","EZK","45","18","18","כה אמר אדני יהוה בראשון באחד לחדש תקח פר בן בקר תמים וחטאת את המקדש׃ ");
INSERT INTO heb_vpl VALUES ("EK45_19","027_45_19","EZK","45","19","19","ולקח הכהן מדם החטאת ונתן אל מזוזת הבית ואל ארבע פנות העזרה למזבח ועל מזוזת שער החצר הפנימית׃ ");
INSERT INTO heb_vpl VALUES ("EK45_20","027_45_20","EZK","45","20","20","וכן תעשה בשבעה בחדש מאיש שגה ומפתי וכפרתם את הבית׃ ");
INSERT INTO heb_vpl VALUES ("EK45_21","027_45_21","EZK","45","21","21","בראשון בארבעה עשר יום לחדש יהיה לכם הפסח חג שבעות ימים מצות יאכל׃ ");
INSERT INTO heb_vpl VALUES ("EK45_22","027_45_22","EZK","45","22","22","ועשה הנשיא ביום ההוא בעדו ובעד כל עם הארץ פר חטאת׃ ");
INSERT INTO heb_vpl VALUES ("EK45_23","027_45_23","EZK","45","23","23","ושבעת ימי החג יעשה עולה ליהוה שבעת פרים ושבעת אילים תמימם ליום שבעת הימים וחטאת שעיר עזים ליום׃ ");
INSERT INTO heb_vpl VALUES ("EK45_24","027_45_24","EZK","45","24","24","ומנחה איפה לפר ואיפה לאיל יעשה ושמן הין לאיפה׃ ");
INSERT INTO heb_vpl VALUES ("EK45_25","027_45_25","EZK","45","25","25","בשביעי בחמשה עשר יום לחדש בחג יעשה כאלה שבעת הימים כחטאת כעלה וכמנחה וכשמן׃ ");
INSERT INTO heb_vpl VALUES ("EK46_1","027_46_1","EZK","46","1","1","כה אמר אדני יהוה שער החצר הפנימית הפנה קדים יהיה סגור ששת ימי המעשה וביום השבת יפתח וביום החדש יפתח׃ ");
INSERT INTO heb_vpl VALUES ("EK46_2","027_46_2","EZK","46","2","2","ובא הנשיא דרך אולם השער מחוץ ועמד על מזוזת השער ועשו הכהנים את עולתו ואת שלמיו והשתחוה על מפתן השער ויצא והשער לא יסגר עד הערב׃ ");
INSERT INTO heb_vpl VALUES ("EK46_3","027_46_3","EZK","46","3","3","והשתחוו עם הארץ פתח השער ההוא בשבתות ובחדשים לפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK46_4","027_46_4","EZK","46","4","4","והעלה אשר יקרב הנשיא ליהוה ביום השבת ששה כבשים תמימם ואיל תמים׃ ");
INSERT INTO heb_vpl VALUES ("EK46_5","027_46_5","EZK","46","5","5","ומנחה איפה לאיל ולכבשים מנחה מתת ידו ושמן הין לאיפה׃ ");
INSERT INTO heb_vpl VALUES ("EK46_6","027_46_6","EZK","46","6","6","וביום החדש פר בן בקר תמימם וששת כבשם ואיל תמימם יהיו׃ ");
INSERT INTO heb_vpl VALUES ("EK46_7","027_46_7","EZK","46","7","7","ואיפה לפר ואיפה לאיל יעשה מנחה ולכבשים כאשר תשיג ידו ושמן הין לאיפה׃ ");
INSERT INTO heb_vpl VALUES ("EK46_8","027_46_8","EZK","46","8","8","ובבוא הנשיא דרך אולם השער יבוא ובדרכו יצא׃ ");
INSERT INTO heb_vpl VALUES ("EK46_9","027_46_9","EZK","46","9","9","ובבוא עם הארץ לפני יהוה במועדים הבא דרך שער צפון להשתחות יצא דרך שער נגב והבא דרך שער נגב יצא דרך שער צפונה לא ישוב דרך השער אשר בא בו כי נכחו יצאו׃ ");
INSERT INTO heb_vpl VALUES ("EK46_10","027_46_10","EZK","46","10","10","והנשיא בתוכם בבואם יבוא ובצאתם יצאו׃ ");
INSERT INTO heb_vpl VALUES ("EK46_11","027_46_11","EZK","46","11","11","ובחגים ובמועדים תהיה המנחה איפה לפר ואיפה לאיל ולכבשים מתת ידו ושמן הין לאיפה׃ ");
INSERT INTO heb_vpl VALUES ("EK46_12","027_46_12","EZK","46","12","12","וכי יעשה הנשיא נדבה עולה או שלמים נדבה ליהוה ופתח לו את השער הפנה קדים ועשה את עלתו ואת שלמיו כאשר יעשה ביום השבת ויצא וסגר את השער אחרי צאתו׃ ");
INSERT INTO heb_vpl VALUES ("EK46_13","027_46_13","EZK","46","13","13","וכבש בן שנתו תמים תעשה עולה ליום ליהוה בבקר בבקר תעשה אתו׃ ");
INSERT INTO heb_vpl VALUES ("EK46_14","027_46_14","EZK","46","14","14","ומנחה תעשה עליו בבקר בבקר ששית האיפה ושמן שלישית ההין לרס את הסלת מנחה ליהוה חקות עולם תמיד׃ ");
INSERT INTO heb_vpl VALUES ("EK46_15","027_46_15","EZK","46","15","15","ועשו את הכבש ואת המנחה ואת השמן בבקר בבקר עולת תמיד׃ ");
INSERT INTO heb_vpl VALUES ("EK46_16","027_46_16","EZK","46","16","16","כה אמר אדני יהוה כי יתן הנשיא מתנה לאיש מבניו נחלתו היא לבניו תהיה אחזתם היא בנחלה׃ ");
INSERT INTO heb_vpl VALUES ("EK46_17","027_46_17","EZK","46","17","17","וכי יתן מתנה מנחלתו לאחד מעבדיו והיתה לו עד שנת הדרור ושבת לנשיא אך נחלתו בניו להם תהיה׃ ");
INSERT INTO heb_vpl VALUES ("EK46_18","027_46_18","EZK","46","18","18","ולא יקח הנשיא מנחלת העם להונתם מאחזתם מאחזתו ינחל את בניו למען אשר לא יפצו עמי איש מאחזתו׃ ");
INSERT INTO heb_vpl VALUES ("EK46_19","027_46_19","EZK","46","19","19","ויביאני במבוא אשר על כתף השער אל הלשכות הקדש אל הכהנים הפנות צפונה והנה שם מקום בירכתם ימה׃ ");
INSERT INTO heb_vpl VALUES ("EK46_20","027_46_20","EZK","46","20","20","ויאמר אלי זה המקום אשר יבשלו שם הכהנים את האשם ואת החטאת אשר יאפו את המנחה לבלתי הוציא אל החצר החיצונה לקדש את העם׃ ");
INSERT INTO heb_vpl VALUES ("EK46_21","027_46_21","EZK","46","21","21","ויוציאני אל החצר החיצנה ויעבירני אל ארבעת מקצועי החצר והנה חצר במקצע החצר חצר במקצע החצר׃ ");
INSERT INTO heb_vpl VALUES ("EK46_22","027_46_22","EZK","46","22","22","בארבעת מקצעות החצר חצרות קטרות ארבעים ארך ושלשים רחב מדה אחת לארבעתם מהקצעות׃ ");
INSERT INTO heb_vpl VALUES ("EK46_23","027_46_23","EZK","46","23","23","וטור סביב בהם סביב לארבעתם ומבשלות עשוי מתחת הטירות סביב׃ ");
INSERT INTO heb_vpl VALUES ("EK46_24","027_46_24","EZK","46","24","24","ויאמר אלי אלה בית המבשלים אשר יבשלו שם משרתי הבית את זבח העם׃ ");
INSERT INTO heb_vpl VALUES ("EK47_1","027_47_1","EZK","47","1","1","וישבני אל פתח הבית והנה מים יצאים מתחת מפתן הבית קדימה כי פני הבית קדים והמים ירדים מתחת מכתף הבית הימנית מנגב למזבח׃ ");
INSERT INTO heb_vpl VALUES ("EK47_2","027_47_2","EZK","47","2","2","ויוצאני דרך שער צפונה ויסבני דרך חוץ אל שער החוץ דרך הפונה קדים והנה מים מפכים מן הכתף הימנית׃ ");
INSERT INTO heb_vpl VALUES ("EK47_3","027_47_3","EZK","47","3","3","בצאת האיש קדים וקו בידו וימד אלף באמה ויעברני במים מי אפסים׃ ");
INSERT INTO heb_vpl VALUES ("EK47_4","027_47_4","EZK","47","4","4","וימד אלף ויעברני במים מים ברכים וימד אלף ויעברני מי מתנים׃ ");
INSERT INTO heb_vpl VALUES ("EK47_5","027_47_5","EZK","47","5","5","וימד אלף נחל אשר לא אוכל לעבר כי גאו המים מי שחו נחל אשר לא יעבר׃ ");
INSERT INTO heb_vpl VALUES ("EK47_6","027_47_6","EZK","47","6","6","ויאמר אלי הראית בן אדם ויולכני וישבני שפת הנחל׃ ");
INSERT INTO heb_vpl VALUES ("EK47_7","027_47_7","EZK","47","7","7","בשובני והנה אל שפת הנחל עץ רב מאד מזה ומזה׃ ");
INSERT INTO heb_vpl VALUES ("EK47_8","027_47_8","EZK","47","8","8","ויאמר אלי המים האלה יוצאים אל הגלילה הקדמונה וירדו על הערבה ובאו הימה אל הימה המוצאים ונרפאו המים׃ ");
INSERT INTO heb_vpl VALUES ("EK47_9","027_47_9","EZK","47","9","9","והיה כל נפש חיה אשר ישרץ אל כל אשר יבוא שם נחלים יחיה והיה הדגה רבה מאד כי באו שמה המים האלה וירפאו וחי כל אשר יבוא שמה הנחל׃ ");
INSERT INTO heb_vpl VALUES ("EK47_10","027_47_10","EZK","47","10","10","והיה יעמדו עליו דוגים מעין גדי ועד עין עגלים משטוח לחרמים יהיו למינה תהיה דגתם כדגת הים הגדול רבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("EK47_11","027_47_11","EZK","47","11","11","בצאתו וגבאיו ולא ירפאו למלח נתנו׃ ");
INSERT INTO heb_vpl VALUES ("EK47_12","027_47_12","EZK","47","12","12","ועל הנחל יעלה על שפתו מזה ומזה כל עץ מאכל לא יבול עלהו ולא יתם פריו לחדשיו יבכר כי מימיו מן המקדש המה יוצאים והיו פריו למאכל ועלהו לתרופה׃ ");
INSERT INTO heb_vpl VALUES ("EK47_13","027_47_13","EZK","47","13","13","כה אמר אדני יהוה גה גבול אשר תתנחלו את הארץ לשני עשר שבטי ישראל יוסף חבלים׃ ");
INSERT INTO heb_vpl VALUES ("EK47_14","027_47_14","EZK","47","14","14","ונחלתם אותה איש כאחיו אשר נשאתי את ידי לתתה לאבתיכם ונפלה הארץ הזאת לכם בנחלה׃ ");
INSERT INTO heb_vpl VALUES ("EK47_15","027_47_15","EZK","47","15","15","וזה גבול הארץ לפאת צפונה מן הים הגדול הדרך חתלן לבוא צדדה׃ ");
INSERT INTO heb_vpl VALUES ("EK47_16","027_47_16","EZK","47","16","16","חמת ברותה סברים אשר בין גבול דמשק ובין גבול חמת חצר התיכון אשר אל גבול חורן׃ ");
INSERT INTO heb_vpl VALUES ("EK47_17","027_47_17","EZK","47","17","17","והיה גבול מן הים חצר עינון גבול דמשק וצפון צפונה וגבול חמת ואת פאת צפון׃ ");
INSERT INTO heb_vpl VALUES ("EK47_18","027_47_18","EZK","47","18","18","ופאת קדים מבין חורן ומבין דמשק ומבין הגלעד ומבין ארץ ישראל הירדן מגבול על הים הקדמוני תמדו ואת פאת קדימה׃ ");
INSERT INTO heb_vpl VALUES ("EK47_19","027_47_19","EZK","47","19","19","ופאת נגב תימנה מתמר עד מי מריבות קדש נחלה אל הים הגדול ואת פאת תימנה נגבה׃ ");
INSERT INTO heb_vpl VALUES ("EK47_20","027_47_20","EZK","47","20","20","ופאת ים הים הגדול מגבול עד נכח לבוא חמת זאת פאת ים׃ ");
INSERT INTO heb_vpl VALUES ("EK47_21","027_47_21","EZK","47","21","21","וחלקתם את הארץ הזאת לכם לשבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK47_22","027_47_22","EZK","47","22","22","והיה תפלו אותה בנחלה לכם ולהגרים הגרים בתוככם אשר הולדו בנים בתוככם והיו לכם כאזרח בבני ישראל אתכם יפלו בנחלה בתוך שבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK47_23","027_47_23","EZK","47","23","23","והיה בשבט אשר גר הגר אתו שם תתנו נחלתו נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK48_1","027_48_1","EZK","48","1","1","ואלה שמות השבטים מקצה צפונה אל יד דרך חתלן לבוא חמת חצר עינן גבול דמשק צפונה אל יד חמת והיו לו פאת קדים הים דן אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK48_2","027_48_2","EZK","48","2","2","ועל גבול דן מפאת קדים עד פאת ימה אשר אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK48_3","027_48_3","EZK","48","3","3","ועל גבול אשר מפאת קדימה ועד פאת ימה נפתלי אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK48_4","027_48_4","EZK","48","4","4","ועל גבול נפתלי מפאת קדמה עד פאת ימה מנשה אחד׃ ");
