INSERT INTO heb_vpl VALUES ("EK48_8","027_48_8","EZK","48","8","8","ועל גבול יהודה מפאת קדים עד פאת ימה תהיה התרומה אשר תרימו חמשה ועשרים אלף רחב וארך כאחד החלקים מפאת קדימה עד פאת ימה והיה המקדש בתוכו׃ ");
INSERT INTO heb_vpl VALUES ("EK48_9","027_48_9","EZK","48","9","9","התרומה אשר תרימו ליהוה ארך חמשה ועשרים אלף ורחב עשרת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("EK48_10","027_48_10","EZK","48","10","10","ולאלה תהיה תרומת הקדש לכהנים צפונה חמשה ועשרים אלף וימה רחב עשרת אלפים וקדימה רחב עשרת אלפים ונגבה ארך חמשה ועשרים אלף והיה מקדש יהוה בתוכו׃ ");
INSERT INTO heb_vpl VALUES ("EK48_11","027_48_11","EZK","48","11","11","לכהנים המקדש מבני צדוק אשר שמרו משמרתי אשר לא תעו בתעות בני ישראל כאשר תעו הלוים׃ ");
INSERT INTO heb_vpl VALUES ("EK48_12","027_48_12","EZK","48","12","12","והיתה להם תרומיה מתרומת הארץ קדש קדשים אל גבול הלוים׃ ");
INSERT INTO heb_vpl VALUES ("EK48_13","027_48_13","EZK","48","13","13","והלוים לעמת גבול הכהנים חמשה ועשרים אלף ארך ורחב עשרת אלפים כל ארך חמשה ועשרים אלף ורחב עשרת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("EK48_14","027_48_14","EZK","48","14","14","ולא ימכרו ממנו ולא ימר ולא יעבור ראשית הארץ כי קדש ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK48_15","027_48_15","EZK","48","15","15","וחמשת אלפים הנותר ברחב על פני חמשה ועשרים אלף חל הוא לעיר למושב ולמגרש והיתה העיר בתוכה׃ ");
INSERT INTO heb_vpl VALUES ("EK48_16","027_48_16","EZK","48","16","16","ואלה מדותיה פאת צפון חמש מאות וארבעת אלפים ופאת נגב חמש חמש מאות וארבעת אלפים ומפאת קדים חמש מאות וארבעת אלפים ופאת ימה חמש מאות וארבעת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("EK48_17","027_48_17","EZK","48","17","17","והיה מגרש לעיר צפונה חמשים ומאתים ונגבה חמשים ומאתים וקדימה חמשים ומאתים וימה חמשים ומאתים׃ ");
INSERT INTO heb_vpl VALUES ("EK48_18","027_48_18","EZK","48","18","18","והנותר בארך לעמת תרומת הקדש עשרת אלפים קדימה ועשרת אלפים ימה והיה לעמת תרומת הקדש והיתה תבואתה ללחם לעבדי העיר׃ ");
INSERT INTO heb_vpl VALUES ("EK48_19","027_48_19","EZK","48","19","19","והעבד העיר יעבדוהו מכל שבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("EK48_20","027_48_20","EZK","48","20","20","כל התרומה חמשה ועשרים אלף בחמשה ועשרים אלף רביעית תרימו את תרומת הקדש אל אחזת העיר׃ ");
INSERT INTO heb_vpl VALUES ("EK48_21","027_48_21","EZK","48","21","21","והנותר לנשיא מזה ומזה לתרומת הקדש ולאחזת העיר אל פני חמשה ועשרים אלף תרומה עד גבול קדימה וימה על פני חמשה ועשרים אלף על גבול ימה לעמת חלקים לנשיא והיתה תרומת הקדש ומקדש הבית בתוכה׃ ");
INSERT INTO heb_vpl VALUES ("EK48_22","027_48_22","EZK","48","22","22","ומאחזת הלוים ומאחזת העיר בתוך אשר לנשיא יהיה בין גבול יהודה ובין גבול בנימן לנשיא יהיה׃ ");
INSERT INTO heb_vpl VALUES ("EK48_23","027_48_23","EZK","48","23","23","ויתר השבטים מפאת קדמה עד פאת ימה בנימן אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK48_24","027_48_24","EZK","48","24","24","ועל גבול בנימן מפאת קדימה עד פאת ימה שמעון אחד׃ ");
