INSERT INTO heb_vpl VALUES ("EK48_26","027_48_26","EZK","48","26","26","ועל גבול יששכר מפאת קדימה עד פאת ימה זבולן אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK48_27","027_48_27","EZK","48","27","27","ועל גבול זבולן מפאת קדמה עד פאת ימה גד אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK48_28","027_48_28","EZK","48","28","28","ועל גבול גד אל פאת נגב תימנה והיה גבול מתמר מי מריבת קדש נחלה על הים הגדול׃ ");
INSERT INTO heb_vpl VALUES ("EK48_29","027_48_29","EZK","48","29","29","זאת הארץ אשר תפילו מנחלה לשבטי ישראל ואלה מחלקתם נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("EK48_30","027_48_30","EZK","48","30","30","ואלה תוצאת העיר מפאת צפון חמש מאות וארבעת אלפים מדה׃ ");
INSERT INTO heb_vpl VALUES ("EK48_31","027_48_31","EZK","48","31","31","ושערי העיר על שמות שבטי ישראל שערים שלושה צפונה שער ראובן אחד שער יהודה אחד שער לוי אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK48_32","027_48_32","EZK","48","32","32","ואל פאת קדימה חמש מאות וארבעת אלפים ושערים שלשה ושער יוסף אחד שער בנימן אחד שער דן אחד׃ ");
INSERT INTO heb_vpl VALUES ("EK48_33","027_48_33","EZK","48","33","33","ופאת נגבה חמש מאות וארבעת אלפים מדה ושערים שלשה שער שמעון אחד שער יששכר אחד שער זבולן אחד׃ ");
