INSERT INTO heb_vpl VALUES ("EK48_35","027_48_35","EZK","48","35","35","סביב שמנה עשר אלף ושם העיר מיום יהוה שמה׃ ");
INSERT INTO heb_vpl VALUES ("DN1_1","028_1_1","DAN","1","1","1","בשנת שלוש למלכות יהויקים מלך יהודה בא נבוכדנאצר מלך בבל ירושלם ויצר עליה׃ ");
INSERT INTO heb_vpl VALUES ("DN1_2","028_1_2","DAN","1","2","2","ויתן אדני בידו את יהויקים מלך יהודה ומקצת כלי בית האלהים ויביאם ארץ שנער בית אלהיו ואת הכלים הביא בית אוצר אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("DN1_3","028_1_3","DAN","1","3","3","ויאמר המלך לאשפנז רב סריסיו להביא מבני ישראל ומזרע המלוכה ומן הפרתמים׃ ");
INSERT INTO heb_vpl VALUES ("DN1_4","028_1_4","DAN","1","4","4","ילדים אשר אין בהם כל מאום וטובי מראה ומשכילים בכל חכמה וידעי דעת ומביני מדע ואשר כח בהם לעמד בהיכל המלך וללמדם ספר ולשון כשדים׃ ");
INSERT INTO heb_vpl VALUES ("DN1_5","028_1_5","DAN","1","5","5","וימן להם המלך דבר יום ביומו מפת בג המלך ומיין משתיו ולגדלם שנים שלוש ומקצתם יעמדו לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("DN1_6","028_1_6","DAN","1","6","6","ויהי בהם מבני יהודה דניאל חנניה מישאל ועזריה׃ ");
INSERT INTO heb_vpl VALUES ("DN1_7","028_1_7","DAN","1","7","7","וישם להם שר הסריסים שמות וישם לדניאל בלטשאצר ולחנניה שדרך ולמישאל מישך ולעזריה עבד נגו׃ ");
INSERT INTO heb_vpl VALUES ("DN1_8","028_1_8","DAN","1","8","8","וישם דניאל על לבו אשר לא יתגאל בפתבג המלך וביין משתיו ויבקש משר הסריסים אשר לא יתגאל׃ ");
INSERT INTO heb_vpl VALUES ("DN1_9","028_1_9","DAN","1","9","9","ויתן האלהים את דניאל לחסד ולרחמים לפני שר הסריסים׃ ");
INSERT INTO heb_vpl VALUES ("DN1_10","028_1_10","DAN","1","10","10","ויאמר שר הסריסים לדניאל ירא אני את אדני המלך אשר מנה את מאכלכם ואת משתיכם אשר למה יראה את פניכם זעפים מן הילדים אשר כגילכם וחיבתם את ראשי למלך׃ ");
INSERT INTO heb_vpl VALUES ("DN1_11","028_1_11","DAN","1","11","11","ויאמר דניאל אל המלצר אשר מנה שר הסריסים על דניאל חנניה מישאל ועזריה׃ ");
INSERT INTO heb_vpl VALUES ("DN1_12","028_1_12","DAN","1","12","12","נס נא את עבדיך ימים עשרה ויתנו לנו מן הזרעים ונאכלה ומים ונשתה׃ ");
INSERT INTO heb_vpl VALUES ("DN1_13","028_1_13","DAN","1","13","13","ויראו לפניך מראינו ומראה הילדים האכלים את פתבג המלך וכאשר תראה עשה עם עבדיך׃ ");
INSERT INTO heb_vpl VALUES ("DN1_14","028_1_14","DAN","1","14","14","וישמע להם לדבר הזה וינסם ימים עשרה׃ ");
INSERT INTO heb_vpl VALUES ("DN1_15","028_1_15","DAN","1","15","15","ומקצת ימים עשרה נראה מראיהם טוב ובריאי בשר מן כל הילדים האכלים את פתבג המלך׃ ");
INSERT INTO heb_vpl VALUES ("DN1_16","028_1_16","DAN","1","16","16","ויהי המלצר נשא את פתבגם ויין משתיהם ונתן להם זרענים׃ ");
INSERT INTO heb_vpl VALUES ("DN1_17","028_1_17","DAN","1","17","17","והילדים האלה ארבעתם נתן להם האלהים מדע והשכל בכל ספר וחכמה ודניאל הבין בכל חזון וחלמות׃ ");
INSERT INTO heb_vpl VALUES ("DN1_18","028_1_18","DAN","1","18","18","ולמקצת הימים אשר אמר המלך להביאם ויביאם שר הסריסים לפני נבכדנצר׃ ");
INSERT INTO heb_vpl VALUES ("DN1_19","028_1_19","DAN","1","19","19","וידבר אתם המלך ולא נמצא מכלם כדניאל חנניה מישאל ועזריה ויעמדו לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("DN1_20","028_1_20","DAN","1","20","20","וכל דבר חכמת בינה אשר בקש מהם המלך וימצאם עשר ידות על כל החרטמים האשפים אשר בכל מלכותו׃ ");
INSERT INTO heb_vpl VALUES ("DN1_21","028_1_21","DAN","1","21","21","ויהי דניאל עד שנת אחת לכורש המלך׃ ");
INSERT INTO heb_vpl VALUES ("DN2_1","028_2_1","DAN","2","1","1","ובשנת שתים למלכות נבכדנצר חלם נבכדנצר חלמות ותתפעם רוחו ושנתו נהיתה עליו׃ ");
INSERT INTO heb_vpl VALUES ("DN2_2","028_2_2","DAN","2","2","2","ויאמר המלך לקרא לחרטמים ולאשפים ולמכשפים ולכשדים להגיד למלך חלמתיו ויבאו ויעמדו לפני המלך׃ ");
INSERT INTO heb_vpl VALUES ("DN2_3","028_2_3","DAN","2","3","3","ויאמר להם המלך חלום חלמתי ותפעם רוחי לדעת את החלום׃ ");
INSERT INTO heb_vpl VALUES ("DN2_4","028_2_4","DAN","2","4","4","וידברו הכשדים למלך ארמית מלכא לעלמין חיי אמר חלמא לעבדיך ופשרא נחוא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_5","028_2_5","DAN","2","5","5","ענה מלכא ואמר לכשדיא מלתא מני אזדא הן לא תהודעונני חלמא ופשרה הדמין תתעבדון ובתיכון נולי יתשמון׃ ");
INSERT INTO heb_vpl VALUES ("DN2_6","028_2_6","DAN","2","6","6","והן חלמא ופשרה תהחון מתנן ונבזבה ויקר שגיא תקבלון מן קדמי להן חלמא ופשרה החוני׃ ");
INSERT INTO heb_vpl VALUES ("DN2_7","028_2_7","DAN","2","7","7","ענו תנינות ואמרין מלכא חלמא יאמר לעבדוהי ופשרה נהחוה׃ ");
INSERT INTO heb_vpl VALUES ("DN2_8","028_2_8","DAN","2","8","8","ענה מלכא ואמר מן יציב ידע אנה די עדנא אנתון זבנין כל קבל די חזיתון די אזדא מני מלתא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_9","028_2_9","DAN","2","9","9","די הן חלמא לא תהודענני חדה היא דתכון ומלה כדבה ושחיתה הזמנתון למאמר קדמי עד די עדנא ישתנא להן חלמא אמרו לי ואנדע די פשרה תהחונני׃ ");
INSERT INTO heb_vpl VALUES ("DN2_10","028_2_10","DAN","2","10","10","ענו כשדיא קדם מלכא ואמרין לא איתי אנש על יבשתא די מלת מלכא יוכל להחויה כל קבל די כל מלך רב ושליט מלה כדנה לא שאל לכל חרטם ואשף וכשדי׃ ");
INSERT INTO heb_vpl VALUES ("DN2_11","028_2_11","DAN","2","11","11","ומלתא די מלכה שאל יקירה ואחרן לא איתי די יחונה קדם מלכא להן אלהין די מדרהון עם בשרא לא איתוהי׃ ");
INSERT INTO heb_vpl VALUES ("DN2_12","028_2_12","DAN","2","12","12","כל קבל דנה מלכא בנס וקצף שגיא ואמר להובדה לכל חכימי בבל׃ ");
INSERT INTO heb_vpl VALUES ("DN2_13","028_2_13","DAN","2","13","13","ודתא נפקת וחכימיא מתקטלין ובעו דניאל וחברוהי להתקטלה׃ ");
INSERT INTO heb_vpl VALUES ("DN2_14","028_2_14","DAN","2","14","14","באדין דניאל התיב עטא וטעם לאריוך רב טבחיא די מלכא די נפק לקטלה לחכימי בבל׃ ");
INSERT INTO heb_vpl VALUES ("DN2_15","028_2_15","DAN","2","15","15","ענה ואמר לאריוך שליטא די מלכא על מה דתא מהחצפה מן קדם מלכא אדין מלתא הודע אריוך לדניאל׃ ");
INSERT INTO heb_vpl VALUES ("DN2_16","028_2_16","DAN","2","16","16","ודניאל על ובעה מן מלכא די זמן ינתן לה ופשרא להחויה למלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_17","028_2_17","DAN","2","17","17","אדין דניאל לביתה אזל ולחנניה מישאל ועזריה חברוהי מלתא הודע׃ ");
INSERT INTO heb_vpl VALUES ("DN2_18","028_2_18","DAN","2","18","18","ורחמין למבעא מן קדם אלה שמיא על רזה דנה די לא יהבדון דניאל וחברוהי עם שאר חכימי בבל׃ ");
INSERT INTO heb_vpl VALUES ("DN2_19","028_2_19","DAN","2","19","19","אדין לדניאל בחזוא די ליליא רזה גלי אדין דניאל ברך לאלה שמיא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_20","028_2_20","DAN","2","20","20","ענה דניאל ואמר להוא שמה די אלהא מברך מן עלמא ועד עלמא די חכמתא וגבורתא די לה היא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_21","028_2_21","DAN","2","21","21","והוא מהשנא עדניא וזמניא מהעדה מלכין ומהקים מלכין יהב חכמתא לחכימין ומנדעא לידעי בינה׃ ");
INSERT INTO heb_vpl VALUES ("DN2_22","028_2_22","DAN","2","22","22","הוא גלא עמיקתא ומסתרתא ידע מה בחשוכא ונהירא עמה שרא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_23","028_2_23","DAN","2","23","23","לך אלה אבהתי מהודא ומשבח אנה די חכמתא וגבורתא יהבת לי וכען הודעתני די בעינא מנך די מלת מלכא הודעתנא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_24","028_2_24","DAN","2","24","24","כל קבל דנה דניאל על על אריוך די מני מלכא להובדה לחכימי בבל אזל וכן אמר לה לחכימי בבל אל תהובד העלני קדם מלכא ופשרא למלכא אחוא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_25","028_2_25","DAN","2","25","25","אדין אריוך בהתבהלה הנעל לדניאל קדם מלכא וכן אמר לה די השכחת גבר מן בני גלותא די יהוד די פשרא למלכא יהודע׃ ");
INSERT INTO heb_vpl VALUES ("DN2_26","028_2_26","DAN","2","26","26","ענה מלכא ואמר לדניאל די שמה בלטשאצר האיתיך כהל להודעתני חלמא די חזית ופשרה׃ ");
INSERT INTO heb_vpl VALUES ("DN2_27","028_2_27","DAN","2","27","27","ענה דניאל קדם מלכא ואמר רזה די מלכא שאל לא חכימין אשפין חרטמין גזרין יכלין להחויה למלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_28","028_2_28","DAN","2","28","28","ברם איתי אלה בשמיא גלא רזין והודע למלכא נבוכדנצר מה די להוא באחרית יומיא חלמך וחזוי ראשך על משכבך דנה הוא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_29","028_2_29","DAN","2","29","29","אנתה מלכא רעיונך על משכבך סלקו מה די להוא אחרי דנה וגלא רזיא הודעך מה די להוא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_30","028_2_30","DAN","2","30","30","ואנה לא בחכמה די איתי בי מן כל חייא רזא דנה גלי לי להן על דברת די פשרא למלכא יהודעון ורעיוני לבבך תנדע׃ ");
INSERT INTO heb_vpl VALUES ("DN2_31","028_2_31","DAN","2","31","31","אנתה מלכא חזה הוית ואלו צלם חד שגיא צלמא דכן רב וזיוה יתיר קאם לקבלך ורוה דחיל׃ ");
INSERT INTO heb_vpl VALUES ("DN2_32","028_2_32","DAN","2","32","32","הוא צלמא ראשה די דהב טב חדוהי ודרעוהי די כסף מעוהי וירכתה די נחש׃ ");
INSERT INTO heb_vpl VALUES ("DN2_33","028_2_33","DAN","2","33","33","שקוהי די פרזל רגלוהי מנהון די פרזל ומנהון די חסף׃ ");
INSERT INTO heb_vpl VALUES ("DN2_34","028_2_34","DAN","2","34","34","חזה הוית עד די התגזרת אבן די לא בידין ומחת לצלמא על רגלוהי די פרזלא וחספא והדקת המון׃ ");
INSERT INTO heb_vpl VALUES ("DN2_35","028_2_35","DAN","2","35","35","באדין דקו כחדה פרזלא חספא נחשא כספא ודהבא והוו כעור מן אדרי קיט ונשא המון רוחא וכל אתר לא השתכח להון ואבנא די מחת לצלמא הות לטור רב ומלת כל ארעא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_36","028_2_36","DAN","2","36","36","דנה חלמא ופשרה נאמר קדם מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_37","028_2_37","DAN","2","37","37","אנתה מלכא מלך מלכיא די אלה שמיא מלכותא חסנא ותקפא ויקרא יהב לך׃ ");
INSERT INTO heb_vpl VALUES ("DN2_38","028_2_38","DAN","2","38","38","ובכל די דארין בני אנשא חיות ברא ועוף שמיא יהב בידך והשלטך בכלהון אנתה הוא ראשה די דהבא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_39","028_2_39","DAN","2","39","39","ובתרך תקום מלכו אחרי ארעא מנך ומלכו תליתיא אחרי די נחשא די תשלט בכל ארעא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_40","028_2_40","DAN","2","40","40","ומלכו רביעיה תהוא תקיפה כפרזלא כל קבל די פרזלא מהדק וחשל כלא וכפרזלא די מרעע כל אלין תדק ותרע׃ ");
INSERT INTO heb_vpl VALUES ("DN2_41","028_2_41","DAN","2","41","41","ודי חזיתה רגליא ואצבעתא מנהון חסף די פחר ומנהון פרזל מלכו פליגה תהוה ומן נצבתא די פרזלא להוא בה כל קבל די חזיתה פרזלא מערב בחסף טינא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_42","028_2_42","DAN","2","42","42","ואצבעת רגליא מנהון פרזל ומנהון חסף מן קצת מלכותא תהוה תקיפה ומנה תהוה תבירה׃ ");
INSERT INTO heb_vpl VALUES ("DN2_43","028_2_43","DAN","2","43","43","די חזית פרזלא מערב בחסף טינא מתערבין להון בזרע אנשא ולא להון דבקין דנה עם דנה הא כדי פרזלא לא מתערב עם חספא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_44","028_2_44","DAN","2","44","44","וביומיהון די מלכיא אנון יקים אלה שמיא מלכו די לעלמין לא תתחבל ומלכותה לעם אחרן לא תשתבק תדק ותסיף כל אלין מלכותא והיא תקום לעלמיא׃ ");
INSERT INTO heb_vpl VALUES ("DN2_45","028_2_45","DAN","2","45","45","כל קבל די חזית די מטורא אתגזרת אבן די לא בידין והדקת פרזלא נחשא חספא כספא ודהבא אלה רב הודע למלכא מה די להוא אחרי דנה ויציב חלמא ומהימן פשרה׃ ");
INSERT INTO heb_vpl VALUES ("DN2_46","028_2_46","DAN","2","46","46","באדין מלכא נבוכדנצר נפל על אנפוהי ולדניאל סגד ומנחה וניחחין אמר לנסכה לה׃ ");
INSERT INTO heb_vpl VALUES ("DN2_47","028_2_47","DAN","2","47","47","ענה מלכא לדניאל ואמר מן קשט די אלהכון הוא אלה אלהין ומרא מלכין וגלה רזין די יכלת למגלא רזה דנה׃ ");
INSERT INTO heb_vpl VALUES ("DN2_48","028_2_48","DAN","2","48","48","אדין מלכא לדניאל רבי ומתנן רברבן שגיאן יהב לה והשלטה על כל מדינת בבל ורב סגנין על כל חכימי בבל׃ ");
INSERT INTO heb_vpl VALUES ("DN2_49","028_2_49","DAN","2","49","49","ודניאל בעא מן מלכא ומני על עבידתא די מדינת בבל לשדרך מישך ועבד נגו ודניאל בתרע מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_1","028_3_1","DAN","3","1","1","נבוכדנצר מלכא עבד צלם די דהב רומה אמין שתין פתיה אמין שת אקימה בבקעת דורא במדינת בבל׃ ");
INSERT INTO heb_vpl VALUES ("DN3_2","028_3_2","DAN","3","2","2","ונבוכדנצר מלכא שלח למכנש לאחשדרפניא סגניא ופחותא אדרגזריא גדבריא דתבריא תפתיא וכל שלטני מדינתא למתא לחנכת צלמא די הקים נבוכדנצר מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_3","028_3_3","DAN","3","3","3","באדין מתכנשין אחשדרפניא סגניא ופחותא אדרגזריא גדבריא דתבריא תפתיא וכל שלטני מדינתא לחנכת צלמא די הקים נבוכדנצר מלכא וקאמין לקבל צלמא די הקים נבוכדנצר׃ ");
INSERT INTO heb_vpl VALUES ("DN3_4","028_3_4","DAN","3","4","4","וכרוזא קרא בחיל לכון אמרין עממיא אמיא ולשניא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_5","028_3_5","DAN","3","5","5","בעדנא די תשמעון קל קרנא משרוקיתא קיתרס סבכא פסנתרין סומפניה וכל זני זמרא תפלון ותסגדון לצלם דהבא די הקים נבוכדנצר מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_6","028_3_6","DAN","3","6","6","ומן די לא יפל ויסגד בה שעתא יתרמא לגוא אתון נורא יקדתא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_7","028_3_7","DAN","3","7","7","כל קבל דנה בה זמנא כדי שמעין כל עממיא קל קרנא משרוקיתא קיתרס שבכא פסנטרין וכל זני זמרא נפלין כל עממיא אמיא ולשניא סגדין לצלם דהבא די הקים נבוכדנצר מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_8","028_3_8","DAN","3","8","8","כל קבל דנה בה זמנא קרבו גברין כשדאין ואכלו קרציהון די יהודיא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_9","028_3_9","DAN","3","9","9","ענו ואמרין לנבוכדנצר מלכא מלכא לעלמין חיי׃ ");
INSERT INTO heb_vpl VALUES ("DN3_10","028_3_10","DAN","3","10","10","אנתה מלכא שמת טעם די כל אנש די ישמע קל קרנא משרקיתא קיתרס שבכא פסנתרין וסיפניה וכל זני זמרא יפל ויסגד לצלם דהבא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_11","028_3_11","DAN","3","11","11","ומן די לא יפל ויסגד יתרמא לגוא אתון נורא יקדתא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_12","028_3_12","DAN","3","12","12","איתי גברין יהודאין די מנית יתהון על עבידת מדינת בבל שדרך מישך ועבד נגו גבריא אלך לא שמו עליך מלכא טעם לאלהיך לא פלחין ולצלם דהבא די הקימת לא סגדין׃ ");
INSERT INTO heb_vpl VALUES ("DN3_13","028_3_13","DAN","3","13","13","באדין נבוכדנצר ברגז וחמה אמר להיתיה לשדרך מישך ועבד נגו באדין גבריא אלך היתיו קדם מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_14","028_3_14","DAN","3","14","14","ענה נבכדנצר ואמר להון הצדא שדרך מישך ועבד נגו לאלהי לא איתיכון פלחין ולצלם דהבא די הקימת לא סגדין׃ ");
INSERT INTO heb_vpl VALUES ("DN3_15","028_3_15","DAN","3","15","15","כען הן איתיכון עתידין די בעדנא די תשמעון קל קרנא משרוקיתא קיתרס שבכא פסנתרין וסומפניה וכל זני זמרא תפלון ותסגדון לצלמא די עבדת והן לא תסגדון בה שעתה תתרמון לגוא אתון נורא יקדתא ומן הוא אלה די ישיזבנכון מן ידי׃ ");
INSERT INTO heb_vpl VALUES ("DN3_16","028_3_16","DAN","3","16","16","ענו שדרך מישך ועבד נגו ואמרין למלכא נבוכדנצר לא חשחין אנחנה על דנה פתגם להתבותך׃ ");
INSERT INTO heb_vpl VALUES ("DN3_17","028_3_17","DAN","3","17","17","הן איתי אלהנא די אנחנא פלחין יכל לשיזבותנא מן אתון נורא יקדתא ומן ידך מלכא ישיזב׃ ");
INSERT INTO heb_vpl VALUES ("DN3_18","028_3_18","DAN","3","18","18","והן לא ידיע להוא לך מלכא די לאלהיך לא איתנא פלחין ולצלם דהבא די הקימת לא נסגד׃ ");
INSERT INTO heb_vpl VALUES ("DN3_19","028_3_19","DAN","3","19","19","באדין נבוכדנצר התמלי חמא וצלם אנפוהי אשתנו על שדרך מישך ועבד נגו ענה ואמר למזא לאתונא חד שבעה על די חזה למזיה׃ ");
INSERT INTO heb_vpl VALUES ("DN3_20","028_3_20","DAN","3","20","20","ולגברין גברי חיל די בחילה אמר לכפתה לשדרך מישך ועבד נגו למרמא לאתון נורא יקדתא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_21","028_3_21","DAN","3","21","21","באדין גבריא אלך כפתו בסרבליהון פטישיהון וכרבלתהון ולבשיהון ורמיו לגוא אתון נורא יקדתא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_22","028_3_22","DAN","3","22","22","כל קבל דנה מן די מלת מלכא מחצפה ואתונא אזה יתירא גבריא אלך די הסקו לשדרך מישך ועבד נגו קטל המון שביבא די נורא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_23","028_3_23","DAN","3","23","23","וגבריא אלך תלתהון שדרך מישך ועבד נגו נפלו לגוא אתון נורא יקדתא מכפתין׃ ");
INSERT INTO heb_vpl VALUES ("DN3_24","028_3_24","DAN","3","24","24","אדין נבוכדנצר מלכא תוה וקם בהתבהלה ענה ואמר להדברוהי הלא גברין תלתא רמינא לגוא נורא מכפתין ענין ואמרין למלכא יציבא מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_25","028_3_25","DAN","3","25","25","ענה ואמר הא אנה חזה גברין ארבעה שרין מהלכין בגוא נורא וחבל לא איתי בהון ורוה די רביעיא דמה לבר אלהין׃ ");
INSERT INTO heb_vpl VALUES ("DN3_26","028_3_26","DAN","3","26","26","באדין קרב נבוכדנצר לתרע אתון נורא יקדתא ענה ואמר שדרך מישך ועבד נגו עבדוהי די אלהא עליא פקו ואתו באדין נפקין שדרך מישך ועבד נגו מן גוא נורא׃ ");
INSERT INTO heb_vpl VALUES ("DN3_27","028_3_27","DAN","3","27","27","ומתכנשין אחשדרפניא סגניא ופחותא והדברי מלכא חזין לגבריא אלך די לא שלט נורא בגשמהון ושער ראשהון לא התחרך וסרבליהון לא שנו וריח נור לא עדת בהון׃ ");
INSERT INTO heb_vpl VALUES ("DN3_28","028_3_28","DAN","3","28","28","ענה נבוכדנצר ואמר בריך אלההון די שדרך מישך ועבד נגו די שלח מלאכה ושיזב לעבדוהי די התרחצו עלוהי ומלת מלכא שניו ויהבו גשמיהון די לא יפלחון ולא יסגדון לכל אלה להן לאלההון׃ ");
INSERT INTO heb_vpl VALUES ("DN3_29","028_3_29","DAN","3","29","29","ומני שים טעם די כל עם אמה ולשן די יאמר שלה על אלההון די שדרך מישך ועבד נגוא הדמין יתעבד וביתה נולי ישתוה כל קבל די לא איתי אלה אחרן די יכל להצלה כדנה׃ ");
INSERT INTO heb_vpl VALUES ("DN3_30","028_3_30","DAN","3","30","30","באדין מלכא הצלח לשדרך מישך ועבד נגו במדינת בבל׃ ");
INSERT INTO heb_vpl VALUES ("DN4_1","028_4_1","DAN","4","1","1","נבוכדנצר מלכא לכל עממיא אמיא ולשניא די דארין בכל ארעא שלמכון ישגא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_2","028_4_2","DAN","4","2","2","אתיא ותמהיא די עבד עמי אלהא עליא שפר קדמי להחויה׃ ");
INSERT INTO heb_vpl VALUES ("DN4_3","028_4_3","DAN","4","3","3","אתוהי כמה רברבין ותמהוהי כמה תקיפין מלכותה מלכות עלם ושלטנה עם דר ודר׃ ");
INSERT INTO heb_vpl VALUES ("DN4_4","028_4_4","DAN","4","4","4","אנה נבוכדנצר שלה הוית בביתי ורענן בהיכלי׃ ");
INSERT INTO heb_vpl VALUES ("DN4_5","028_4_5","DAN","4","5","5","חלם חזית וידחלנני והרהרין על משכבי וחזוי ראשי יבהלנני׃ ");
INSERT INTO heb_vpl VALUES ("DN4_6","028_4_6","DAN","4","6","6","ומני שים טעם להנעלה קדמי לכל חכימי בבל די פשר חלמא יהודענני׃ ");
INSERT INTO heb_vpl VALUES ("DN4_7","028_4_7","DAN","4","7","7","באדין עללין חרטמיא אשפיא כשדיא וגזריא וחלמא אמר אנה קדמיהון ופשרה לא מהודעין לי׃ ");
INSERT INTO heb_vpl VALUES ("DN4_8","028_4_8","DAN","4","8","8","ועד אחרין על קדמי דניאל די שמה בלטשאצר כשם אלהי ודי רוח אלהין קדישין בה וחלמא קדמוהי אמרת׃ ");
INSERT INTO heb_vpl VALUES ("DN4_9","028_4_9","DAN","4","9","9","בלטשאצר רב חרטמיא די אנה ידעת די רוח אלהין קדישין בך וכל רז לא אנס לך חזוי חלמי די חזית ופשרה אמר׃ ");
INSERT INTO heb_vpl VALUES ("DN4_10","028_4_10","DAN","4","10","10","וחזוי ראשי על משכבי חזה הוית ואלו אילן בגוא ארעא ורומה שגיא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_11","028_4_11","DAN","4","11","11","רבה אילנא ותקף ורומה ימטא לשמיא וחזותה לסוף כל ארעא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_12","028_4_12","DAN","4","12","12","עפיה שפיר ואנבה שגיא ומזון לכלא בה תחתוהי תטלל חיות ברא ובענפוהי ידרון צפרי שמיא ומנה יתזין כל בשרא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_13","028_4_13","DAN","4","13","13","חזה הוית בחזוי ראשי על משכבי ואלו עיר וקדיש מן שמיא נחת׃ ");
INSERT INTO heb_vpl VALUES ("DN4_14","028_4_14","DAN","4","14","14","קרא בחיל וכן אמר גדו אילנא וקצצו ענפוהי אתרו עפיה ובדרו אנבה תנד חיותא מן תחתוהי וצפריא מן ענפוהי׃ ");
INSERT INTO heb_vpl VALUES ("DN4_15","028_4_15","DAN","4","15","15","ברם עקר שרשוהי בארעא שבקו ובאסור די פרזל ונחש בדתאא די ברא ובטל שמיא יצטבע ועם חיותא חלקה בעשב ארעא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_16","028_4_16","DAN","4","16","16","לבבה מן אנושא ישנון ולבב חיוה יתיהב לה ושבעה עדנין יחלפון עלוהי׃ ");
INSERT INTO heb_vpl VALUES ("DN4_17","028_4_17","DAN","4","17","17","בגזרת עירין פתגמא ומאמר קדישין שאלתא עד דברת די ינדעון חייא די שליט עליא במלכות אנושא ולמן די יצבא יתננה ושפל אנשים יקים עליה׃ ");
INSERT INTO heb_vpl VALUES ("DN4_18","028_4_18","DAN","4","18","18","דנה חלמא חזית אנה מלכא נבוכדנצר ואנתה בלטשאצר פשרא אמר כל קבל די כל חכימי מלכותי לא יכלין פשרא להודעתני ואנתה כהל די רוח אלהין קדישין בך׃ ");
INSERT INTO heb_vpl VALUES ("DN4_19","028_4_19","DAN","4","19","19","אדין דניאל די שמה בלטשאצר אשתומם כשעה חדה ורעינהי יבהלנה ענה מלכא ואמר בלטשאצר חלמא ופשרא אל יבהלך ענה בלטשאצר ואמר מראי חלמא לשנאיך ופשרה לעריך׃ ");
INSERT INTO heb_vpl VALUES ("DN4_20","028_4_20","DAN","4","20","20","אילנא די חזית די רבה ותקף ורומה ימטא לשמיא וחזותה לכל ארעא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_21","028_4_21","DAN","4","21","21","ועפיה שפיר ואנבה שגיא ומזון לכלא בה תחתוהי תדור חיות ברא ובענפוהי ישכנן צפרי שמיא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_22","028_4_22","DAN","4","22","22","אנתה הוא מלכא די רבית ותקפת ורבותך רבת ומטת לשמיא ושלטנך לסוף ארעא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_23","028_4_23","DAN","4","23","23","ודי חזה מלכא עיר וקדיש נחת מן שמיא ואמר גדו אילנא וחבלוהי ברם עקר שרשוהי בארעא שבקו ובאסור די פרזל ונחש בדתאא די ברא ובטל שמיא יצטבע ועם חיות ברא חלקה עד די שבעה עדנין יחלפון עלוהי׃ ");
INSERT INTO heb_vpl VALUES ("DN4_24","028_4_24","DAN","4","24","24","דנה פשרא מלכא וגזרת עליא היא די מטת על מראי מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_25","028_4_25","DAN","4","25","25","ולך טרדין מן אנשא ועם חיות ברא להוה מדרך ועשבא כתורין לך יטעמון ומטל שמיא לך מצבעין ושבעה עדנין יחלפון עליך עד די תנדע די שליט עליא במלכות אנשא ולמן די יצבא יתננה׃ ");
INSERT INTO heb_vpl VALUES ("DN4_26","028_4_26","DAN","4","26","26","ודי אמרו למשבק עקר שרשוהי די אילנא מלכותך לך קימה מן די תנדע די שלטן שמיא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_27","028_4_27","DAN","4","27","27","להן מלכא מלכי ישפר עליך וחטיך בצדקה פרק ועויתך במחן ענין הן תהוא ארכה לשלותך׃ ");
INSERT INTO heb_vpl VALUES ("DN4_28","028_4_28","DAN","4","28","28","כלא מטא על נבוכדנצר מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN4_29","028_4_29","DAN","4","29","29","לקצת ירחין תרי עשר על היכל מלכותא די בבל מהלך הוה׃ ");
INSERT INTO heb_vpl VALUES ("DN4_30","028_4_30","DAN","4","30","30","ענה מלכא ואמר הלא דא היא בבל רבתא די אנה בניתה לבית מלכו בתקף חסני וליקר הדרי׃ ");
INSERT INTO heb_vpl VALUES ("DN4_31","028_4_31","DAN","4","31","31","עוד מלתא בפם מלכא קל מן שמיא נפל לך אמרין נבוכדנצר מלכא מלכותה עדת מנך׃ ");
INSERT INTO heb_vpl VALUES ("DN4_32","028_4_32","DAN","4","32","32","ומן אנשא לך טרדין ועם חיות ברא מדרך עשבא כתורין לך יטעמון ושבעה עדנין יחלפון עליך עד די תנדע די שליט עליא במלכות אנשא ולמן די יצבא יתננה׃ ");
INSERT INTO heb_vpl VALUES ("DN4_33","028_4_33","DAN","4","33","33","בה שעתא מלתא ספת על נבוכדנצר ומן אנשא טריד ועשבא כתורין יאכל ומטל שמיא גשמה יצטבע עד די שערה כנשרין רבה וטפרוהי כצפרין׃ ");
INSERT INTO heb_vpl VALUES ("DN4_34","028_4_34","DAN","4","34","34","ולקצת יומיה אנה נבוכדנצר עיני לשמיא נטלת ומנדעי עלי יתוב ולעליא ברכת ולחי עלמא שבחת והדרת די שלטנה שלטן עלם ומלכותה עם דר ודר׃ ");
INSERT INTO heb_vpl VALUES ("DN4_35","028_4_35","DAN","4","35","35","וכל דארי ארעא כלה חשיבין וכמצביה עבד בחיל שמיא ודארי ארעא ולא איתי די ימחא בידה ויאמר לה מה עבדת׃ ");
INSERT INTO heb_vpl VALUES ("DN4_36","028_4_36","DAN","4","36","36","בה זמנא מנדעי יתוב עלי וליקר מלכותי הדרי וזוי יתוב עלי ולי הדברי ורברבני יבעון ועל מלכותי התקנת ורבו יתירה הוספת לי׃ ");
INSERT INTO heb_vpl VALUES ("DN4_37","028_4_37","DAN","4","37","37","כען אנה נבוכדנצר משבח ומרומם ומהדר למלך שמיא די כל מעבדוהי קשט וארחתה דין ודי מהלכין בגוה יכל להשפלה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_1","028_5_1","DAN","5","1","1","בלשאצר מלכא עבד לחם רב לרברבנוהי אלף ולקבל אלפא חמרא שתה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_2","028_5_2","DAN","5","2","2","בלשאצר אמר בטעם חמרא להיתיה למאני דהבא וכספא די הנפק נבוכדנצר אבוהי מן היכלא די בירושלם וישתון בהון מלכא ורברבנוהי שגלתה ולחנתה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_3","028_5_3","DAN","5","3","3","באדין היתיו מאני דהבא די הנפקו מן היכלא די בית אלהא די בירושלם ואשתיו בהון מלכא ורברבנוהי שגלתה ולחנתה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_4","028_5_4","DAN","5","4","4","אשתיו חמרא ושבחו לאלהי דהבא וכספא נחשא פרזלא אעא ואבנא׃ ");
INSERT INTO heb_vpl VALUES ("DN5_5","028_5_5","DAN","5","5","5","בה שעתה נפקו אצבען די יד אנש וכתבן לקבל נברשתא על גירא די כתל היכלא די מלכא ומלכא חזה פס ידה די כתבה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_6","028_5_6","DAN","5","6","6","אדין מלכא זיוהי שנוהי ורעינהי יבהלונה וקטרי חרצה משתרין וארכבתה דא לדא נקשן׃ ");
INSERT INTO heb_vpl VALUES ("DN5_7","028_5_7","DAN","5","7","7","קרא מלכא בחיל להעלה לאשפיא כשדיא וגזריא ענה מלכא ואמר לחכימי בבל די כל אנש די יקרה כתבה דנה ופשרה יחונני ארגונא ילבש והמונכא די דהבא על צוארה ותלתי במלכותא ישלט׃ ");
INSERT INTO heb_vpl VALUES ("DN5_8","028_5_8","DAN","5","8","8","אדין עללין כל חכימי מלכא ולא כהלין כתבא למקרא ופשרא להודעה למלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN5_9","028_5_9","DAN","5","9","9","אדין מלכא בלשאצר שגיא מתבהל וזיוהי שנין עלוהי ורברבנוהי משתבשין׃ ");
INSERT INTO heb_vpl VALUES ("DN5_10","028_5_10","DAN","5","10","10","מלכתא לקבל מלי מלכא ורברבנוהי לבית משתיא עללת ענת מלכתא ואמרת מלכא לעלמין חיי אל יבהלוך רעיונך וזיויך אל ישתנו׃ ");
INSERT INTO heb_vpl VALUES ("DN5_11","028_5_11","DAN","5","11","11","איתי גבר במלכותך די רוח אלהין קדישין בה וביומי אבוך נהירו ושכלתנו וחכמה כחכמת אלהין השתכחת בה ומלכא נבכדנצר אבוך רב חרטמין אשפין כשדאין גזרין הקימה אבוך מלכא׃ ");
INSERT INTO heb_vpl VALUES ("DN5_12","028_5_12","DAN","5","12","12","כל קבל די רוח יתירה ומנדע ושכלתנו מפשר חלמין ואחוית אחידן ומשרא קטרין השתכחת בה בדניאל די מלכא שם שמה בלטשאצר כען דניאל יתקרי ופשרה יהחוה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_13","028_5_13","DAN","5","13","13","באדין דניאל העל קדם מלכא ענה מלכא ואמר לדניאל אנתה הוא דניאל די מן בני גלותא די יהוד די היתי מלכא אבי מן יהוד׃ ");
INSERT INTO heb_vpl VALUES ("DN5_14","028_5_14","DAN","5","14","14","ושמעת עליך די רוח אלהין בך ונהירו ושכלתנו וחכמה יתירה השתכחת בך׃ ");
INSERT INTO heb_vpl VALUES ("DN5_15","028_5_15","DAN","5","15","15","וכען העלו קדמי חכימיא אשפיא די כתבה דנה יקרון ופשרה להודעתני ולא כהלין פשר מלתא להחויה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_16","028_5_16","DAN","5","16","16","ואנה שמעת עליך די תוכל פשרין למפשר וקטרין למשרא כען הן תוכל כתבא למקרא ופשרה להודעתני ארגונא תלבש והמונכא די דהבא על צוארך ותלתא במלכותא תשלט׃ ");
INSERT INTO heb_vpl VALUES ("DN5_17","028_5_17","DAN","5","17","17","באדין ענה דניאל ואמר קדם מלכא מתנתך לך להוין ונבזביתך לאחרן הב ברם כתבא אקרא למלכא ופשרא אהודענה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_18","028_5_18","DAN","5","18","18","אנתה מלכא אלהא עליא מלכותא ורבותא ויקרא והדרה יהב לנבכדנצר אבוך׃ ");
INSERT INTO heb_vpl VALUES ("DN5_19","028_5_19","DAN","5","19","19","ומן רבותא די יהב לה כל עממיא אמיא ולשניא הוו זאעין ודחלין מן קדמוהי די הוה צבא הוא קטל ודי הוה צבא הוה מחא ודי הוה צבא הוה מרים ודי הוה צבא הוה משפיל׃ ");
INSERT INTO heb_vpl VALUES ("DN5_20","028_5_20","DAN","5","20","20","וכדי רם לבבה ורוחה תקפת להזדה הנחת מן כרסא מלכותה ויקרה העדיו מנה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_21","028_5_21","DAN","5","21","21","ומן בני אנשא טריד ולבבה עם חיותא שוי ועם ערדיא מדורה עשבא כתורין יטעמונה ומטל שמיא גשמה יצטבע עד די ידע די שליט אלהא עליא במלכות אנשא ולמן די יצבה יהקים עליה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_22","028_5_22","DAN","5","22","22","ואנתה ברה בלשאצר לא השפלת לבבך כל קבל די כל דנה ידעת׃ ");
INSERT INTO heb_vpl VALUES ("DN5_23","028_5_23","DAN","5","23","23","ועל מרא שמיא התרוממת ולמאניא די ביתה היתיו קדמיך ואנתה ורברבניך שגלתך ולחנתך חמרא שתין בהון ולאלהי כספא ודהבא נחשא פרזלא אעא ואבנא די לא חזין ולא שמעין ולא ידעין שבחת ולאלהא די נשמתך בידה וכל ארחתך לה לא הדרת׃ ");
INSERT INTO heb_vpl VALUES ("DN5_24","028_5_24","DAN","5","24","24","באדין מן קדמוהי שליח פסא די ידא וכתבא דנה רשים׃ ");
INSERT INTO heb_vpl VALUES ("DN5_25","028_5_25","DAN","5","25","25","ודנה כתבא די רשים מנא מנא תקל ופרסין׃ ");
INSERT INTO heb_vpl VALUES ("DN5_26","028_5_26","DAN","5","26","26","דנה פשר מלתא מנא מנה אלהא מלכותך והשלמה׃ ");
INSERT INTO heb_vpl VALUES ("DN5_27","028_5_27","DAN","5","27","27","תקל תקילתה במאזניא והשתכחת חסיר׃ ");
INSERT INTO heb_vpl VALUES ("DN5_28","028_5_28","DAN","5","28","28","פרס פריסת מלכותך ויהיבת למדי ופרס׃ ");
INSERT INTO heb_vpl VALUES ("DN5_29","028_5_29","DAN","5","29","29","באדין אמר בלשאצר והלבישו לדניאל ארגונא והמונכא די דהבא על צוארה והכרזו עלוהי די להוא שליט תלתא במלכותא׃ ");
INSERT INTO heb_vpl VALUES ("DN5_30","028_5_30","DAN","5","30","30","בה בליליא קטיל בלאשצר מלכא כשדיא׃ ");
INSERT INTO heb_vpl VALUES ("DN5_31","028_5_31","DAN","5","31","31","ודריוש מדיא קבל מלכותא כבר שנין שתין ותרתין׃ ");
INSERT INTO heb_vpl VALUES ("DN6_1","028_6_1","DAN","6","1","1","שפר קדם דריוש והקים על מלכותא לאחשדרפניא מאה ועשרין די להון בכל מלכותא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_2","028_6_2","DAN","6","2","2","ועלא מנהון סרכין תלתא די דניאל חד מנהון די להון אחשדרפניא אלין יהבין להון טעמא ומלכא לא להוא נזק׃ ");
INSERT INTO heb_vpl VALUES ("DN6_3","028_6_3","DAN","6","3","3","אדין דניאל דנה הוא מתנצח על סרכיא ואחשדרפניא כל קבל די רוח יתירא בה ומלכא עשית להקמותה על כל מלכותא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_4","028_6_4","DAN","6","4","4","אדין סרכיא ואחשדרפניא הוו בעין עלה להשכחה לדניאל מצד מלכותא וכל עלה ושחיתה לא יכלין להשכחה כל קבל די מהימן הוא וכל שלו ושחיתה לא השתכחת עלוהי׃ ");
INSERT INTO heb_vpl VALUES ("DN6_5","028_6_5","DAN","6","5","5","אדין גבריא אלך אמרין די לא נהשכח לדניאל דנה כל עלא להן השכחנה עלוהי בדת אלהה׃ ");
INSERT INTO heb_vpl VALUES ("DN6_6","028_6_6","DAN","6","6","6","אדין סרכיא ואחשדרפניא אלן הרגשו על מלכא וכן אמרין לה דריוש מלכא לעלמין חיי׃ ");
INSERT INTO heb_vpl VALUES ("DN6_7","028_6_7","DAN","6","7","7","אתיעטו כל סרכי מלכותא סגניא ואחשדרפניא הדבריא ופחותא לקימה קים מלכא ולתקפה אסר די כל די יבעה בעו מן כל אלה ואנש עד יומין תלתין להן מנך מלכא יתרמא לגב אריותא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_8","028_6_8","DAN","6","8","8","כען מלכא תקים אסרא ותרשם כתבא די לא להשניה כדת מדי ופרס די לא תעדא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_9","028_6_9","DAN","6","9","9","כל קבל דנה מלכא דריוש רשם כתבא ואסרא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_10","028_6_10","DAN","6","10","10","ודניאל כדי ידע די רשים כתבא על לביתה וכוין פתיחן לה בעליתה נגד ירושלם וזמנין תלתה ביומא הוא ברך על ברכוהי ומצלא ומודא קדם אלהה כל קבל די הוא עבד מן קדמת דנה׃ ");
INSERT INTO heb_vpl VALUES ("DN6_11","028_6_11","DAN","6","11","11","אדין גבריא אלך הרגשו והשכחו לדניאל בעא ומתחנן קדם אלהה׃ ");
INSERT INTO heb_vpl VALUES ("DN6_12","028_6_12","DAN","6","12","12","באדין קריבו ואמרין קדם מלכא על אסר מלכא הלא אסר רשמת די כל אנש די יבעה מן כל אלה ואנש עד יומין תלתין להן מנך מלכא יתרמא לגוב אריותא ענה מלכא ואמר יציבא מלתא כדת מדי ופרס די לא תעדא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_13","028_6_13","DAN","6","13","13","באדין ענו ואמרין קדם מלכא די דניאל די מן בני גלותא די יהוד לא שם עליך מלכא טעם ועל אסרא די רשמת וזמנין תלתה ביומא בעא בעותה׃ ");
INSERT INTO heb_vpl VALUES ("DN6_14","028_6_14","DAN","6","14","14","אדין מלכא כדי מלתא שמע שגיא באש עלוהי ועל דניאל שם בל לשיזבותה ועד מעלי שמשא הוא משתדר להצלותה׃ ");
INSERT INTO heb_vpl VALUES ("DN6_15","028_6_15","DAN","6","15","15","באדין גבריא אלך הרגשו על מלכא ואמרין למלכא דע מלכא די דת למדי ופרס די כל אסר וקים די מלכא יהקים לא להשניה׃ ");
INSERT INTO heb_vpl VALUES ("DN6_16","028_6_16","DAN","6","16","16","באדין מלכא אמר והיתיו לדניאל ורמו לגבא די אריותא ענה מלכא ואמר לדניאל אלהך די אנתה פלח לה בתדירא הוא ישיזבנך׃ ");
INSERT INTO heb_vpl VALUES ("DN6_17","028_6_17","DAN","6","17","17","והיתית אבן חדה ושמת על פם גבא וחתמה מלכא בעזקתה ובעזקת רברבנוהי די לא תשנא צבו בדניאל׃ ");
INSERT INTO heb_vpl VALUES ("DN6_18","028_6_18","DAN","6","18","18","אדין אזל מלכא להיכלה ובת טות ודחון לא הנעל קדמוהי ושנתה נדת עלוהי׃ ");
INSERT INTO heb_vpl VALUES ("DN6_19","028_6_19","DAN","6","19","19","באדין מלכא בשפרפרא יקום בנגהא ובהתבהלה לגבא די אריותא אזל׃ ");
INSERT INTO heb_vpl VALUES ("DN6_20","028_6_20","DAN","6","20","20","וכמקרבה לגבא לדניאל בקל עציב זעק ענה מלכא ואמר לדניאל דניאל עבד אלהא חיא אלהך די אנתה פלח לה בתדירא היכל לשיזבותך מן אריותא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_21","028_6_21","DAN","6","21","21","אדין דניאל עם מלכא מלל מלכא לעלמין חיי׃ ");
INSERT INTO heb_vpl VALUES ("DN6_22","028_6_22","DAN","6","22","22","אלהי שלח מלאכה וסגר פם אריותא ולא חבלוני כל קבל די קדמוהי זכו השתכחת לי ואף קדמיך מלכא חבולה לא עבדת׃ ");
INSERT INTO heb_vpl VALUES ("DN6_23","028_6_23","DAN","6","23","23","באדין מלכא שגיא טאב עלוהי ולדניאל אמר להנסקה מן גבא והסק דניאל מן גבא וכל חבל לא השתכח בה די הימן באלהה׃ ");
INSERT INTO heb_vpl VALUES ("DN6_24","028_6_24","DAN","6","24","24","ואמר מלכא והיתיו גבריא אלך די אכלו קרצוהי די דניאל ולגב אריותא רמו אנון בניהון ונשיהון ולא מטו לארעית גבא עד די שלטו בהון אריותא וכל גרמיהון הדקו׃ ");
INSERT INTO heb_vpl VALUES ("DN6_25","028_6_25","DAN","6","25","25","באדין דריוש מלכא כתב לכל עממיא אמיא ולשניא די דארין בכל ארעא שלמכון ישגא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_26","028_6_26","DAN","6","26","26","מן קדמי שים טעם די בכל שלטן מלכותי להון זאעין ודחלין מן קדם אלהה די דניאל די הוא אלהא חיא וקים לעלמין ומלכותה די לא תתחבל ושלטנה עד סופא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_27","028_6_27","DAN","6","27","27","משיזב ומצל ועבד אתין ותמהין בשמיא ובארעא די שיזיב לדניאל מן יד אריותא׃ ");
INSERT INTO heb_vpl VALUES ("DN6_28","028_6_28","DAN","6","28","28","ודניאל דנה הצלח במלכות דריוש ובמלכות כורש פרסיא׃ ");
INSERT INTO heb_vpl VALUES ("DN7_1","028_7_1","DAN","7","1","1","בשנת חדה לבלאשצר מלך בבל דניאל חלם חזה וחזוי ראשה על משכבה באדין חלמא כתב ראש מלין אמר׃ ");
INSERT INTO heb_vpl VALUES ("DN7_2","028_7_2","DAN","7","2","2","ענה דניאל ואמר חזה הוית בחזוי עם ליליא וארו ארבע רוחי שמיא מגיחן לימא רבא׃ ");
INSERT INTO heb_vpl VALUES ("DN7_3","028_7_3","DAN","7","3","3","וארבע חיון רברבן סלקן מן ימא שנין דא מן דא׃ ");
INSERT INTO heb_vpl VALUES ("DN7_4","028_7_4","DAN","7","4","4","קדמיתא כאריה וגפין די נשר לה חזה הוית עד די מריטו גפיה ונטילת מן ארעא ועל רגלין כאנש הקימת ולבב אנש יהיב לה׃ ");
INSERT INTO heb_vpl VALUES ("DN7_5","028_7_5","DAN","7","5","5","וארו חיוה אחרי תנינה דמיה לדב ולשטר חד הקמת ותלת עלעין בפמה בין שניה וכן אמרין לה קומי אכלי בשר שגיא׃ ");
INSERT INTO heb_vpl VALUES ("DN7_6","028_7_6","DAN","7","6","6","באתר דנה חזה הוית וארו אחרי כנמר ולה גפין ארבע די עוף על גביה וארבעה ראשין לחיותא ושלטן יהיב לה׃ ");
INSERT INTO heb_vpl VALUES ("DN7_7","028_7_7","DAN","7","7","7","באתר דנה חזה הוית בחזוי ליליא וארו חיוה רביעיה דחילה ואימתני ותקיפא יתירא ושנין די פרזל לה רברבן אכלה ומדקה ושארא ברגליה רפסה והיא משניה מן כל חיותא די קדמיה וקרנין עשר לה׃ ");
INSERT INTO heb_vpl VALUES ("DN7_8","028_7_8","DAN","7","8","8","משתכל הוית בקרניא ואלו קרן אחרי זעירה סלקת ביניהון ותלת מן קרניא קדמיתא אתעקרו מן קדמיה ואלו עינין כעיני אנשא בקרנא דא ופם ממלל רברבן׃ ");
INSERT INTO heb_vpl VALUES ("DN7_9","028_7_9","DAN","7","9","9","חזה הוית עד די כרסון רמיו ועתיק יומין יתב לבושה כתלג חור ושער ראשה כעמר נקא כרסיה שביבין די נור גלגלוהי נור דלק׃ ");
INSERT INTO heb_vpl VALUES ("DN7_10","028_7_10","DAN","7","10","10","נהר די נור נגד ונפק מן קדמוהי אלף אלפים ישמשונה ורבו רבון קדמוהי יקומון דינא יתב וספרין פתיחו׃ ");
INSERT INTO heb_vpl VALUES ("DN7_11","028_7_11","DAN","7","11","11","חזה הוית באדין מן קל מליא רברבתא די קרנא ממללה חזה הוית עד די קטילת חיותא והובד גשמה ויהיבת ליקדת אשא׃ ");
INSERT INTO heb_vpl VALUES ("DN7_12","028_7_12","DAN","7","12","12","ושאר חיותא העדיו שלטנהון וארכה בחיין יהיבת להון עד זמן ועדן׃ ");
INSERT INTO heb_vpl VALUES ("DN7_13","028_7_13","DAN","7","13","13","חזה הוית בחזוי ליליא וארו עם ענני שמיא כבר אנש אתה הוה ועד עתיק יומיא מטה וקדמוהי הקרבוהי׃ ");
INSERT INTO heb_vpl VALUES ("DN7_14","028_7_14","DAN","7","14","14","ולה יהיב שלטן ויקר ומלכו וכל עממיא אמיא ולשניא לה יפלחון שלטנה שלטן עלם די לא יעדה ומלכותה די לא תתחבל׃ ");
INSERT INTO heb_vpl VALUES ("DN7_15","028_7_15","DAN","7","15","15","אתכרית רוחי אנה דניאל בגוא נדנה וחזוי ראשי יבהלנני׃ ");
INSERT INTO heb_vpl VALUES ("DN7_16","028_7_16","DAN","7","16","16","קרבת על חד מן קאמיא ויציבא אבעא מנה על כל דנה ואמר לי ופשר מליא יהודענני׃ ");
INSERT INTO heb_vpl VALUES ("DN7_17","028_7_17","DAN","7","17","17","אלין חיותא רברבתא די אנין ארבע ארבעה מלכין יקומון מן ארעא׃ ");
INSERT INTO heb_vpl VALUES ("DN7_18","028_7_18","DAN","7","18","18","ויקבלון מלכותא קדישי עליונין ויחסנון מלכותא עד עלמא ועד עלם עלמיא׃ ");
INSERT INTO heb_vpl VALUES ("DN7_19","028_7_19","DAN","7","19","19","אדין צבית ליצבא על חיותא רביעיתא די הות שניה מן כלהון דחילה יתירה שניה די פרזל וטפריה די נחש אכלה מדקה ושארא ברגליה רפסה׃ ");
INSERT INTO heb_vpl VALUES ("DN7_20","028_7_20","DAN","7","20","20","ועל קרניא עשר די בראשה ואחרי די סלקת ונפלו מן קדמיה תלת וקרנא דכן ועינין לה ופם ממלל רברבן וחזוה רב מן חברתה׃ ");
INSERT INTO heb_vpl VALUES ("DN7_21","028_7_21","DAN","7","21","21","חזה הוית וקרנא דכן עבדה קרב עם קדישין ויכלה להון׃ ");
INSERT INTO heb_vpl VALUES ("DN7_22","028_7_22","DAN","7","22","22","עד די אתה עתיק יומיא ודינא יהב לקדישי עליונין וזמנא מטה ומלכותא החסנו קדישין׃ ");
INSERT INTO heb_vpl VALUES ("DN7_23","028_7_23","DAN","7","23","23","כן אמר חיותא רביעיתא מלכו רביעיא תהוא בארעא די תשנא מן כל מלכותא ותאכל כל ארעא ותדושנה ותדקנה׃ ");
INSERT INTO heb_vpl VALUES ("DN7_24","028_7_24","DAN","7","24","24","וקרניא עשר מנה מלכותה עשרה מלכין יקמון ואחרן יקום אחריהון והוא ישנא מן קדמיא ותלתה מלכין יהשפל׃ ");
INSERT INTO heb_vpl VALUES ("DN7_25","028_7_25","DAN","7","25","25","ומלין לצד עליא ימלל ולקדישי עליונין יבלא ויסבר להשניה זמנין ודת ויתיהבון בידה עד עדן ועדנין ופלג עדן׃ ");
INSERT INTO heb_vpl VALUES ("DN7_26","028_7_26","DAN","7","26","26","ודינא יתב ושלטנה יהעדון להשמדה ולהובדה עד סופא׃ ");
INSERT INTO heb_vpl VALUES ("DN7_27","028_7_27","DAN","7","27","27","ומלכותה ושלטנא ורבותא די מלכות תחות כל שמיא יהיבת לעם קדישי עליונין מלכותה מלכות עלם וכל שלטניא לה יפלחון וישתמעון׃ ");
INSERT INTO heb_vpl VALUES ("DN7_28","028_7_28","DAN","7","28","28","עד כה סופא די מלתא אנה דניאל שגיא רעיוני יבהלנני וזיוי ישתנון עלי ומלתא בלבי נטרת׃ ");
INSERT INTO heb_vpl VALUES ("DN8_1","028_8_1","DAN","8","1","1","בשנת שלוש למלכות בלאשצר המלך חזון נראה אלי אני דניאל אחרי הנראה אלי בתחלה׃ ");
INSERT INTO heb_vpl VALUES ("DN8_2","028_8_2","DAN","8","2","2","ואראה בחזון ויהי בראתי ואני בשושן הבירה אשר בעילם המדינה ואראה בחזון ואני הייתי על אובל אולי׃ ");
INSERT INTO heb_vpl VALUES ("DN8_3","028_8_3","DAN","8","3","3","ואשא עיני ואראה והנה איל אחד עמד לפני האבל ולו קרנים והקרנים גבהות והאחת גבהה מן השנית והגבהה עלה באחרנה׃ ");
INSERT INTO heb_vpl VALUES ("DN8_4","028_8_4","DAN","8","4","4","ראיתי את האיל מנגח ימה וצפונה ונגבה וכל חיות לא יעמדו לפניו ואין מציל מידו ועשה כרצנו והגדיל׃ ");
INSERT INTO heb_vpl VALUES ("DN8_5","028_8_5","DAN","8","5","5","ואני הייתי מבין והנה צפיר העזים בא מן המערב על פני כל הארץ ואין נוגע בארץ והצפיר קרן חזות בין עיניו׃ ");
INSERT INTO heb_vpl VALUES ("DN8_6","028_8_6","DAN","8","6","6","ויבא עד האיל בעל הקרנים אשר ראיתי עמד לפני האבל וירץ אליו בחמת כחו׃ ");
INSERT INTO heb_vpl VALUES ("DN8_7","028_8_7","DAN","8","7","7","וראיתיו מגיע אצל האיל ויתמרמר אליו ויך את האיל וישבר את שתי קרניו ולא היה כח באיל לעמד לפניו וישליכהו ארצה וירמסהו ולא היה מציל לאיל מידו׃ ");
INSERT INTO heb_vpl VALUES ("DN8_8","028_8_8","DAN","8","8","8","וצפיר העזים הגדיל עד מאד וכעצמו נשברה הקרן הגדולה ותעלנה חזות ארבע תחתיה לארבע רוחות השמים׃ ");
INSERT INTO heb_vpl VALUES ("DN8_9","028_8_9","DAN","8","9","9","ומן האחת מהם יצא קרן אחת מצעירה ותגדל יתר אל הנגב ואל המזרח ואל הצבי׃ ");
INSERT INTO heb_vpl VALUES ("DN8_10","028_8_10","DAN","8","10","10","ותגדל עד צבא השמים ותפל ארצה מן הצבא ומן הכוכבים ותרמסם׃ ");
INSERT INTO heb_vpl VALUES ("DN8_11","028_8_11","DAN","8","11","11","ועד שר הצבא הגדיל וממנו הרים התמיד והשלך מכון מקדשו׃ ");
INSERT INTO heb_vpl VALUES ("DN8_12","028_8_12","DAN","8","12","12","וצבא תנתן על התמיד בפשע ותשלך אמת ארצה ועשתה והצליחה׃ ");
INSERT INTO heb_vpl VALUES ("DN8_13","028_8_13","DAN","8","13","13","ואשמעה אחד קדוש מדבר ויאמר אחד קדוש לפלמוני המדבר עד מתי החזון התמיד והפשע שמם תת וקדש וצבא מרמס׃ ");
INSERT INTO heb_vpl VALUES ("DN8_14","028_8_14","DAN","8","14","14","ויאמר אלי עד ערב בקר אלפים ושלש מאות ונצדק קדש׃ ");
INSERT INTO heb_vpl VALUES ("DN8_15","028_8_15","DAN","8","15","15","ויהי בראתי אני דניאל את החזון ואבקשה בינה והנה עמד לנגדי כמראה גבר׃ ");
INSERT INTO heb_vpl VALUES ("DN8_16","028_8_16","DAN","8","16","16","ואשמע קול אדם בין אולי ויקרא ויאמר גבריאל הבן להלז את המראה׃ ");
INSERT INTO heb_vpl VALUES ("DN8_17","028_8_17","DAN","8","17","17","ויבא אצל עמדי ובבאו נבעתי ואפלה על פני ויאמר אלי הבן בן אדם כי לעת קץ החזון׃ ");
INSERT INTO heb_vpl VALUES ("DN8_18","028_8_18","DAN","8","18","18","ובדברו עמי נרדמתי על פני ארצה ויגע בי ויעמידני על עמדי׃ ");
INSERT INTO heb_vpl VALUES ("DN8_19","028_8_19","DAN","8","19","19","ויאמר הנני מודיעך את אשר יהיה באחרית הזעם כי למועד קץ׃ ");
INSERT INTO heb_vpl VALUES ("DN8_20","028_8_20","DAN","8","20","20","האיל אשר ראית בעל הקרנים מלכי מדי ופרס׃ ");
INSERT INTO heb_vpl VALUES ("DN8_21","028_8_21","DAN","8","21","21","והצפיר השעיר מלך יון והקרן הגדולה אשר בין עיניו הוא המלך הראשון׃ ");
INSERT INTO heb_vpl VALUES ("DN8_22","028_8_22","DAN","8","22","22","והנשברת ותעמדנה ארבע תחתיה ארבע מלכיות מגוי יעמדנה ולא בכחו׃ ");
INSERT INTO heb_vpl VALUES ("DN8_23","028_8_23","DAN","8","23","23","ובאחרית מלכותם כהתם הפשעים יעמד מלך עז פנים ומבין חידות׃ ");
INSERT INTO heb_vpl VALUES ("DN8_24","028_8_24","DAN","8","24","24","ועצם כחו ולא בכחו ונפלאות ישחית והצליח ועשה והשחית עצומים ועם קדשים׃ ");
INSERT INTO heb_vpl VALUES ("DN8_25","028_8_25","DAN","8","25","25","ועל שכלו והצליח מרמה בידו ובלבבו יגדיל ובשלוה ישחית רבים ועל שר שרים יעמד ובאפס יד ישבר׃ ");
INSERT INTO heb_vpl VALUES ("DN8_26","028_8_26","DAN","8","26","26","ומראה הערב והבקר אשר נאמר אמת הוא ואתה סתם החזון כי לימים רבים׃ ");
INSERT INTO heb_vpl VALUES ("DN8_27","028_8_27","DAN","8","27","27","ואני דניאל נהייתי ונחליתי ימים ואקום ואעשה את מלאכת המלך ואשתומם על המראה ואין מבין׃ ");
INSERT INTO heb_vpl VALUES ("DN9_1","028_9_1","DAN","9","1","1","בשנת אחת לדריוש בן אחשורוש מזרע מדי אשר המלך על מלכות כשדים׃ ");
INSERT INTO heb_vpl VALUES ("DN9_2","028_9_2","DAN","9","2","2","בשנת אחת למלכו אני דניאל בינתי בספרים מספר השנים אשר היה דבר יהוה אל ירמיה הנביא למלאות לחרבות ירושלם שבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("DN9_3","028_9_3","DAN","9","3","3","ואתנה את פני אל אדני האלהים לבקש תפלה ותחנונים בצום ושק ואפר׃ ");
INSERT INTO heb_vpl VALUES ("DN9_4","028_9_4","DAN","9","4","4","ואתפללה ליהוה אלהי ואתודה ואמרה אנא אדני האל הגדול והנורא שמר הברית והחסד לאהביו ולשמרי מצותיו׃ ");
INSERT INTO heb_vpl VALUES ("DN9_5","028_9_5","DAN","9","5","5","חטאנו ועוינו והרשענו ומרדנו וסור ממצותך וממשפטיך׃ ");
INSERT INTO heb_vpl VALUES ("DN9_6","028_9_6","DAN","9","6","6","ולא שמענו אל עבדיך הנביאים אשר דברו בשמך אל מלכינו שרינו ואבתינו ואל כל עם הארץ׃ ");
INSERT INTO heb_vpl VALUES ("DN9_7","028_9_7","DAN","9","7","7","לך אדני הצדקה ולנו בשת הפנים כיום הזה לאיש יהודה וליושבי ירושלם ולכל ישראל הקרבים והרחקים בכל הארצות אשר הדחתם שם במעלם אשר מעלו בך׃ ");
INSERT INTO heb_vpl VALUES ("DN9_8","028_9_8","DAN","9","8","8","יהוה לנו בשת הפנים למלכינו לשרינו ולאבתינו אשר חטאנו לך׃ ");
INSERT INTO heb_vpl VALUES ("DN9_9","028_9_9","DAN","9","9","9","לאדני אלהינו הרחמים והסלחות כי מרדנו בו׃ ");
INSERT INTO heb_vpl VALUES ("DN9_10","028_9_10","DAN","9","10","10","ולא שמענו בקול יהוה אלהינו ללכת בתורתיו אשר נתן לפנינו ביד עבדיו הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("DN9_11","028_9_11","DAN","9","11","11","וכל ישראל עברו את תורתך וסור לבלתי שמוע בקלך ותתך עלינו האלה והשבעה אשר כתובה בתורת משה עבד האלהים כי חטאנו לו׃ ");
INSERT INTO heb_vpl VALUES ("DN9_12","028_9_12","DAN","9","12","12","ויקם את דבריו אשר דבר עלינו ועל שפטינו אשר שפטונו להביא עלינו רעה גדלה אשר לא נעשתה תחת כל השמים כאשר נעשתה בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("DN9_13","028_9_13","DAN","9","13","13","כאשר כתוב בתורת משה את כל הרעה הזאת באה עלינו ולא חלינו את פני יהוה אלהינו לשוב מעוננו ולהשכיל באמתך׃ ");
INSERT INTO heb_vpl VALUES ("DN9_14","028_9_14","DAN","9","14","14","וישקד יהוה על הרעה ויביאה עלינו כי צדיק יהוה אלהינו על כל מעשיו אשר עשה ולא שמענו בקלו׃ ");
INSERT INTO heb_vpl VALUES ("DN9_15","028_9_15","DAN","9","15","15","ועתה אדני אלהינו אשר הוצאת את עמך מארץ מצרים ביד חזקה ותעש לך שם כיום הזה חטאנו רשענו׃ ");
INSERT INTO heb_vpl VALUES ("DN9_16","028_9_16","DAN","9","16","16","אדני ככל צדקתך ישב נא אפך וחמתך מעירך ירושלם הר קדשך כי בחטאינו ובעונות אבתינו ירושלם ועמך לחרפה לכל סביבתינו׃ ");
INSERT INTO heb_vpl VALUES ("DN9_17","028_9_17","DAN","9","17","17","ועתה שמע אלהינו אל תפלת עבדך ואל תחנוניו והאר פניך על מקדשך השמם למען אדני׃ ");
INSERT INTO heb_vpl VALUES ("DN9_18","028_9_18","DAN","9","18","18","הטה אלהי אזנך ושמע פקחה עיניך וראה שממתינו והעיר אשר נקרא שמך עליה כי לא על צדקתינו אנחנו מפילים תחנונינו לפניך כי על רחמיך הרבים׃ ");
INSERT INTO heb_vpl VALUES ("DN9_19","028_9_19","DAN","9","19","19","אדני שמעה אדני סלחה אדני הקשיבה ועשה אל תאחר למענך אלהי כי שמך נקרא על עירך ועל עמך׃ ");
INSERT INTO heb_vpl VALUES ("DN9_20","028_9_20","DAN","9","20","20","ועוד אני מדבר ומתפלל ומתודה חטאתי וחטאת עמי ישראל ומפיל תחנתי לפני יהוה אלהי על הר קדש אלהי׃ ");
INSERT INTO heb_vpl VALUES ("DN9_21","028_9_21","DAN","9","21","21","ועוד אני מדבר בתפלה והאיש גבריאל אשר ראיתי בחזון בתחלה מעף ביעף נגע אלי כעת מנחת ערב׃ ");
INSERT INTO heb_vpl VALUES ("DN9_22","028_9_22","DAN","9","22","22","ויבן וידבר עמי ויאמר דניאל עתה יצאתי להשכילך בינה׃ ");
INSERT INTO heb_vpl VALUES ("DN9_23","028_9_23","DAN","9","23","23","בתחלת תחנוניך יצא דבר ואני באתי להגיד כי חמודות אתה ובין בדבר והבן במראה׃ ");
INSERT INTO heb_vpl VALUES ("DN9_24","028_9_24","DAN","9","24","24","שבעים שבעים נחתך על עמך ועל עיר קדשך לכלא הפשע ולחתם חטאות ולכפר עון ולהביא צדק עלמים ולחתם חזון ונביא ולמשח קדש קדשים׃ ");
INSERT INTO heb_vpl VALUES ("DN9_25","028_9_25","DAN","9","25","25","ותדע ותשכל מן מצא דבר להשיב ולבנות ירושלם עד משיח נגיד שבעים שבעה ושבעים ששים ושנים תשוב ונבנתה רחוב וחרוץ ובצוק העתים׃ ");
INSERT INTO heb_vpl VALUES ("DN9_26","028_9_26","DAN","9","26","26","ואחרי השבעים ששים ושנים יכרת משיח ואין לו והעיר והקדש ישחית עם נגיד הבא וקצו בשטף ועד קץ מלחמה נחרצת שממות׃ ");
INSERT INTO heb_vpl VALUES ("DN9_27","028_9_27","DAN","9","27","27","והגביר ברית לרבים שבוע אחד וחצי השבוע ישבית זבח ומנחה ועל כנף שקוצים משמם ועד כלה ונחרצה תתך על שמם׃ ");
INSERT INTO heb_vpl VALUES ("DN10_1","028_10_1","DAN","10","1","1","בשנת שלוש לכורש מלך פרס דבר נגלה לדניאל אשר נקרא שמו בלטשאצר ואמת הדבר וצבא גדול ובין את הדבר ובינה לו במראה׃ ");
INSERT INTO heb_vpl VALUES ("DN10_2","028_10_2","DAN","10","2","2","בימים ההם אני דניאל הייתי מתאבל שלשה שבעים ימים׃ ");
INSERT INTO heb_vpl VALUES ("DN10_3","028_10_3","DAN","10","3","3","לחם חמדות לא אכלתי ובשר ויין לא בא אל פי וסוך לא סכתי עד מלאת שלשת שבעים ימים׃ ");
INSERT INTO heb_vpl VALUES ("DN10_4","028_10_4","DAN","10","4","4","וביום עשרים וארבעה לחדש הראשון ואני הייתי על יד הנהר הגדול הוא חדקל׃ ");
INSERT INTO heb_vpl VALUES ("DN10_5","028_10_5","DAN","10","5","5","ואשא את עיני וארא והנה איש אחד לבוש בדים ומתניו חגרים בכתם אופז׃ ");
INSERT INTO heb_vpl VALUES ("DN10_6","028_10_6","DAN","10","6","6","וגויתו כתרשיש ופניו כמראה ברק ועיניו כלפידי אש וזרעתיו ומרגלתיו כעין נחשת קלל וקול דבריו כקול המון׃ ");
INSERT INTO heb_vpl VALUES ("DN10_7","028_10_7","DAN","10","7","7","וראיתי אני דניאל לבדי את המראה והאנשים אשר היו עמי לא ראו את המראה אבל חרדה גדלה נפלה עליהם ויברחו בהחבא׃ ");
INSERT INTO heb_vpl VALUES ("DN10_8","028_10_8","DAN","10","8","8","ואני נשארתי לבדי ואראה את המראה הגדלה הזאת ולא נשאר בי כח והודי נהפך עלי למשחית ולא עצרתי כח׃ ");
INSERT INTO heb_vpl VALUES ("DN10_9","028_10_9","DAN","10","9","9","ואשמע את קול דבריו וכשמעי את קול דבריו ואני הייתי נרדם על פני ופני ארצה׃ ");
INSERT INTO heb_vpl VALUES ("DN10_10","028_10_10","DAN","10","10","10","והנה יד נגעה בי ותניעני על ברכי וכפות ידי׃ ");
INSERT INTO heb_vpl VALUES ("DN10_11","028_10_11","DAN","10","11","11","ויאמר אלי דניאל איש חמדות הבן בדברים אשר אנכי דבר אליך ועמד על עמדך כי עתה שלחתי אליך ובדברו עמי את הדבר הזה עמדתי מרעיד׃ ");
INSERT INTO heb_vpl VALUES ("DN10_12","028_10_12","DAN","10","12","12","ויאמר אלי אל תירא דניאל כי מן היום הראשון אשר נתת את לבך להבין ולהתענות לפני אלהיך נשמעו דבריך ואני באתי בדבריך׃ ");
INSERT INTO heb_vpl VALUES ("DN10_13","028_10_13","DAN","10","13","13","ושר מלכות פרס עמד לנגדי עשרים ואחד יום והנה מיכאל אחד השרים הראשנים בא לעזרני ואני נותרתי שם אצל מלכי פרס׃ ");
INSERT INTO heb_vpl VALUES ("DN10_14","028_10_14","DAN","10","14","14","ובאתי להבינך את אשר יקרה לעמך באחרית הימים כי עוד חזון לימים׃ ");
INSERT INTO heb_vpl VALUES ("DN10_15","028_10_15","DAN","10","15","15","ובדברו עמי כדברים האלה נתתי פני ארצה ונאלמתי׃ ");
INSERT INTO heb_vpl VALUES ("DN10_16","028_10_16","DAN","10","16","16","והנה כדמות בני אדם נגע על שפתי ואפתח פי ואדברה ואמרה אל העמד לנגדי אדני במראה נהפכו צירי עלי ולא עצרתי כח׃ ");
INSERT INTO heb_vpl VALUES ("DN10_17","028_10_17","DAN","10","17","17","והיך יוכל עבד אדני זה לדבר עם אדני זה ואני מעתה לא יעמד בי כח ונשמה לא נשארה בי׃ ");
INSERT INTO heb_vpl VALUES ("DN10_18","028_10_18","DAN","10","18","18","ויסף ויגע בי כמראה אדם ויחזקני׃ ");
INSERT INTO heb_vpl VALUES ("DN10_19","028_10_19","DAN","10","19","19","ויאמר אל תירא איש חמדות שלום לך חזק וחזק וכדברו עמי התחזקתי ואמרה ידבר אדני כי חזקתני׃ ");
INSERT INTO heb_vpl VALUES ("DN10_20","028_10_20","DAN","10","20","20","ויאמר הידעת למה באתי אליך ועתה אשוב להלחם עם שר פרס ואני יוצא והנה שר יון בא׃ ");
INSERT INTO heb_vpl VALUES ("DN10_21","028_10_21","DAN","10","21","21","אבל אגיד לך את הרשום בכתב אמת ואין אחד מתחזק עמי על אלה כי אם מיכאל שרכם׃ ");
INSERT INTO heb_vpl VALUES ("DN11_1","028_11_1","DAN","11","1","1","ואני בשנת אחת לדריוש המדי עמדי למחזיק ולמעוז לו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_2","028_11_2","DAN","11","2","2","ועתה אמת אגיד לך הנה עוד שלשה מלכים עמדים לפרס והרביעי יעשיר עשר גדול מכל וכחזקתו בעשרו יעיר הכל את מלכות יון׃ ");
INSERT INTO heb_vpl VALUES ("DN11_3","028_11_3","DAN","11","3","3","ועמד מלך גבור ומשל ממשל רב ועשה כרצונו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_4","028_11_4","DAN","11","4","4","וכעמדו תשבר מלכותו ותחץ לארבע רוחות השמים ולא לאחריתו ולא כמשלו אשר משל כי תנתש מלכותו ולאחרים מלבד אלה׃ ");
INSERT INTO heb_vpl VALUES ("DN11_5","028_11_5","DAN","11","5","5","ויחזק מלך הנגב ומן שריו ויחזק עליו ומשל ממשל רב ממשלתו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_6","028_11_6","DAN","11","6","6","ולקץ שנים יתחברו ובת מלך הנגב תבוא אל מלך הצפון לעשות מישרים ולא תעצר כוח הזרוע ולא יעמד וזרעו ותנתן היא ומביאיה והילדה ומחזקה בעתים׃ ");
INSERT INTO heb_vpl VALUES ("DN11_7","028_11_7","DAN","11","7","7","ועמד מנצר שרשיה כנו ויבא אל החיל ויבא במעוז מלך הצפון ועשה בהם והחזיק׃ ");
INSERT INTO heb_vpl VALUES ("DN11_8","028_11_8","DAN","11","8","8","וגם אלהיהם עם נסכיהם עם כלי חמדתם כסף וזהב בשבי יבא מצרים והוא שנים יעמד ממלך הצפון׃ ");
INSERT INTO heb_vpl VALUES ("DN11_9","028_11_9","DAN","11","9","9","ובא במלכות מלך הנגב ושב אל אדמתו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_10","028_11_10","DAN","11","10","10","ובנו יתגרו ואספו המון חילים רבים ובא בוא ושטף ועבר וישב ויתגרו עד מעזה׃ ");
INSERT INTO heb_vpl VALUES ("DN11_11","028_11_11","DAN","11","11","11","ויתמרמר מלך הנגב ויצא ונלחם עמו עם מלך הצפון והעמיד המון רב ונתן ההמון בידו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_12","028_11_12","DAN","11","12","12","ונשא ההמון ירום לבבו והפיל רבאות ולא יעוז׃ ");
INSERT INTO heb_vpl VALUES ("DN11_13","028_11_13","DAN","11","13","13","ושב מלך הצפון והעמיד המון רב מן הראשון ולקץ העתים שנים יבוא בוא בחיל גדול וברכוש רב׃ ");
INSERT INTO heb_vpl VALUES ("DN11_14","028_11_14","DAN","11","14","14","ובעתים ההם רבים יעמדו על מלך הנגב ובני פריצי עמך ינשאו להעמיד חזון ונכשלו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_15","028_11_15","DAN","11","15","15","ויבא מלך הצפון וישפך סוללה ולכד עיר מבצרות וזרעות הנגב לא יעמדו ועם מבחריו ואין כח לעמד׃ ");
INSERT INTO heb_vpl VALUES ("DN11_16","028_11_16","DAN","11","16","16","ויעש הבא אליו כרצונו ואין עומד לפניו ויעמד בארץ הצבי וכלה בידו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_17","028_11_17","DAN","11","17","17","וישם פניו לבוא בתקף כל מלכותו וישרים עמו ועשה ובת הנשים יתן לו להשחיתה ולא תעמד ולא לו תהיה׃ ");
INSERT INTO heb_vpl VALUES ("DN11_18","028_11_18","DAN","11","18","18","וישב פניו לאיים ולכד רבים והשבית קצין חרפתו לו בלתי חרפתו ישיב לו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_19","028_11_19","DAN","11","19","19","וישב פניו למעוזי ארצו ונכשל ונפל ולא ימצא׃ ");
INSERT INTO heb_vpl VALUES ("DN11_20","028_11_20","DAN","11","20","20","ועמד על כנו מעביר נוגש הדר מלכות ובימים אחדים ישבר ולא באפים ולא במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("DN11_21","028_11_21","DAN","11","21","21","ועמד על כנו נבזה ולא נתנו עליו הוד מלכות ובא בשלוה והחזיק מלכות בחלקלקות׃ ");
INSERT INTO heb_vpl VALUES ("DN11_22","028_11_22","DAN","11","22","22","וזרעות השטף ישטפו מלפניו וישברו וגם נגיד ברית׃ ");
INSERT INTO heb_vpl VALUES ("DN11_23","028_11_23","DAN","11","23","23","ומן התחברות אליו יעשה מרמה ועלה ועצם במעט גוי׃ ");
INSERT INTO heb_vpl VALUES ("DN11_24","028_11_24","DAN","11","24","24","בשלוה ובמשמני מדינה יבוא ועשה אשר לא עשו אבתיו ואבות אבתיו בזה ושלל ורכוש להם יבזור ועל מבצרים יחשב מחשבתיו ועד עת׃ ");
INSERT INTO heb_vpl VALUES ("DN11_25","028_11_25","DAN","11","25","25","ויער כחו ולבבו על מלך הנגב בחיל גדול ומלך הנגב יתגרה למלחמה בחיל גדול ועצום עד מאד ולא יעמד כי יחשבו עליו מחשבות׃ ");
INSERT INTO heb_vpl VALUES ("DN11_26","028_11_26","DAN","11","26","26","ואכלי פת בגו ישברוהו וחילו ישטוף ונפלו חללים רבים׃ ");
INSERT INTO heb_vpl VALUES ("DN11_27","028_11_27","DAN","11","27","27","ושניהם המלכים לבבם למרע ועל שלחן אחד כזב ידברו ולא תצלח כי עוד קץ למועד׃ ");
INSERT INTO heb_vpl VALUES ("DN11_28","028_11_28","DAN","11","28","28","וישב ארצו ברכוש גדול ולבבו על ברית קדש ועשה ושב לארצו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_29","028_11_29","DAN","11","29","29","למועד ישוב ובא בנגב ולא תהיה כראשנה וכאחרנה׃ ");
INSERT INTO heb_vpl VALUES ("DN11_30","028_11_30","DAN","11","30","30","ובאו בו ציים כתים ונכאה ושב וזעם על ברית קודש ועשה ושב ויבן על עזבי ברית קדש׃ ");
INSERT INTO heb_vpl VALUES ("DN11_31","028_11_31","DAN","11","31","31","וזרעים ממנו יעמדו וחללו המקדש המעוז והסירו התמיד ונתנו השקוץ משומם׃ ");
INSERT INTO heb_vpl VALUES ("DN11_32","028_11_32","DAN","11","32","32","ומרשיעי ברית יחניף בחלקות ועם ידעי אלהיו יחזקו ועשו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_33","028_11_33","DAN","11","33","33","ומשכילי עם יבינו לרבים ונכשלו בחרב ובלהבה בשבי ובבזה ימים׃ ");
INSERT INTO heb_vpl VALUES ("DN11_34","028_11_34","DAN","11","34","34","ובהכשלם יעזרו עזר מעט ונלוו עליהם רבים בחלקלקות׃ ");
INSERT INTO heb_vpl VALUES ("DN11_35","028_11_35","DAN","11","35","35","ומן המשכילים יכשלו לצרוף בהם ולברר וללבן עד עת קץ כי עוד למועד׃ ");
INSERT INTO heb_vpl VALUES ("DN11_36","028_11_36","DAN","11","36","36","ועשה כרצונו המלך ויתרומם ויתגדל על כל אל ועל אל אלים ידבר נפלאות והצליח עד כלה זעם כי נחרצה נעשתה׃ ");
INSERT INTO heb_vpl VALUES ("DN11_37","028_11_37","DAN","11","37","37","ועל אלהי אבתיו לא יבין ועל חמדת נשים ועל כל אלוה לא יבין כי על כל יתגדל׃ ");
INSERT INTO heb_vpl VALUES ("DN11_38","028_11_38","DAN","11","38","38","ולאלה מעזים על כנו יכבד ולאלוה אשר לא ידעהו אבתיו יכבד בזהב ובכסף ובאבן יקרה ובחמדות׃ ");
INSERT INTO heb_vpl VALUES ("DN11_39","028_11_39","DAN","11","39","39","ועשה למבצרי מעזים עם אלוה נכר אשר הכיר ירבה כבוד והמשילם ברבים ואדמה יחלק במחיר׃ ");
INSERT INTO heb_vpl VALUES ("DN11_40","028_11_40","DAN","11","40","40","ובעת קץ יתנגח עמו מלך הנגב וישתער עליו מלך הצפון ברכב ובפרשים ובאניות רבות ובא בארצות ושטף ועבר׃ ");
INSERT INTO heb_vpl VALUES ("DN11_41","028_11_41","DAN","11","41","41","ובא בארץ הצבי ורבות יכשלו ואלה ימלטו מידו אדום ומואב וראשית בני עמון׃ ");
INSERT INTO heb_vpl VALUES ("DN11_42","028_11_42","DAN","11","42","42","וישלח ידו בארצות וארץ מצרים לא תהיה לפליטה׃ ");
INSERT INTO heb_vpl VALUES ("DN11_43","028_11_43","DAN","11","43","43","ומשל במכמני הזהב והכסף ובכל חמדות מצרים ולבים וכשים במצעדיו׃ ");
INSERT INTO heb_vpl VALUES ("DN11_44","028_11_44","DAN","11","44","44","ושמעות יבהלהו ממזרח ומצפון ויצא בחמא גדלה להשמיד ולהחרים רבים׃ ");
INSERT INTO heb_vpl VALUES ("DN11_45","028_11_45","DAN","11","45","45","ויטע אהלי אפדנו בין ימים להר צבי קדש ובא עד קצו ואין עוזר לו׃ ");
INSERT INTO heb_vpl VALUES ("DN12_1","028_12_1","DAN","12","1","1","ובעת ההיא יעמד מיכאל השר הגדול העמד על בני עמך והיתה עת צרה אשר לא נהיתה מהיות גוי עד העת ההיא ובעת ההיא ימלט עמך כל הנמצא כתוב בספר׃ ");
INSERT INTO heb_vpl VALUES ("DN12_2","028_12_2","DAN","12","2","2","ורבים מישני אדמת עפר יקיצו אלה לחיי עולם ואלה לחרפות לדראון עולם׃ ");
INSERT INTO heb_vpl VALUES ("DN12_3","028_12_3","DAN","12","3","3","והמשכלים יזהרו כזהר הרקיע ומצדיקי הרבים ככוכבים לעולם ועד׃ ");
INSERT INTO heb_vpl VALUES ("DN12_4","028_12_4","DAN","12","4","4","ואתה דניאל סתם הדברים וחתם הספר עד עת קץ ישטטו רבים ותרבה הדעת׃ ");
INSERT INTO heb_vpl VALUES ("DN12_5","028_12_5","DAN","12","5","5","וראיתי אני דניאל והנה שנים אחרים עמדים אחד הנה לשפת היאר ואחד הנה לשפת היאר׃ ");
INSERT INTO heb_vpl VALUES ("DN12_6","028_12_6","DAN","12","6","6","ויאמר לאיש לבוש הבדים אשר ממעל למימי היאר עד מתי קץ הפלאות׃ ");
INSERT INTO heb_vpl VALUES ("DN12_7","028_12_7","DAN","12","7","7","ואשמע את האיש לבוש הבדים אשר ממעל למימי היאר וירם ימינו ושמאלו אל השמים וישבע בחי העולם כי למועד מועדים וחצי וככלות נפץ יד עם קדש תכלינה כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("DN12_8","028_12_8","DAN","12","8","8","ואני שמעתי ולא אבין ואמרה אדני מה אחרית אלה׃ ");
INSERT INTO heb_vpl VALUES ("DN12_9","028_12_9","DAN","12","9","9","ויאמר לך דניאל כי סתמים וחתמים הדברים עד עת קץ׃ ");
INSERT INTO heb_vpl VALUES ("DN12_10","028_12_10","DAN","12","10","10","יתבררו ויתלבנו ויצרפו רבים והרשיעו רשעים ולא יבינו כל רשעים והמשכלים יבינו׃ ");
INSERT INTO heb_vpl VALUES ("DN12_11","028_12_11","DAN","12","11","11","ומעת הוסר התמיד ולתת שקוץ שמם ימים אלף מאתים ותשעים׃ ");
INSERT INTO heb_vpl VALUES ("DN12_12","028_12_12","DAN","12","12","12","אשרי המחכה ויגיע לימים אלף שלש מאות שלשים וחמשה׃ ");
INSERT INTO heb_vpl VALUES ("DN12_13","028_12_13","DAN","12","13","13","ואתה לך לקץ ותנוח ותעמד לגרלך לקץ הימין׃ ");
INSERT INTO heb_vpl VALUES ("HS1_1","029_1_1","HOS","1","1","1","דבר יהוה אשר היה אל הושע בן בארי בימי עזיה יותם אחז יחזקיה מלכי יהודה ובימי ירבעם בן יואש מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("HS1_2","029_1_2","HOS","1","2","2","תחלת דבר יהוה בהושע ויאמר יהוה אל הושע לך קח לך אשת זנונים וילדי זנונים כי זנה תזנה הארץ מאחרי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HS1_3","029_1_3","HOS","1","3","3","וילך ויקח את גמר בת דבלים ותהר ותלד לו בן׃ ");
INSERT INTO heb_vpl VALUES ("HS1_4","029_1_4","HOS","1","4","4","ויאמר יהוה אליו קרא שמו יזרעאל כי עוד מעט ופקדתי את דמי יזרעאל על בית יהוא והשבתי ממלכות בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("HS1_5","029_1_5","HOS","1","5","5","והיה ביום ההוא ושברתי את קשת ישראל בעמק יזרעאל׃ ");
INSERT INTO heb_vpl VALUES ("HS1_6","029_1_6","HOS","1","6","6","ותהר עוד ותלד בת ויאמר לו קרא שמה לא רחמה כי לא אוסיף עוד ארחם את בית ישראל כי נשא אשא להם׃ ");
INSERT INTO heb_vpl VALUES ("HS1_7","029_1_7","HOS","1","7","7","ואת בית יהודה ארחם והושעתים ביהוה אלהיהם ולא אושיעם בקשת ובחרב ובמלחמה בסוסים ובפרשים׃ ");
INSERT INTO heb_vpl VALUES ("HS1_8","029_1_8","HOS","1","8","8","ותגמל את לא רחמה ותהר ותלד בן׃ ");
INSERT INTO heb_vpl VALUES ("HS1_9","029_1_9","HOS","1","9","9","ויאמר קרא שמו לא עמי כי אתם לא עמי ואנכי לא אהיה לכם׃ ");
INSERT INTO heb_vpl VALUES ("HS1_10","029_1_10","HOS","1","10","10","והיה מספר בני ישראל כחול הים אשר לא ימד ולא יספר והיה במקום אשר יאמר להם לא עמי אתם יאמר להם בני אל חי׃ ");
INSERT INTO heb_vpl VALUES ("HS1_11","029_1_11","HOS","1","11","11","ונקבצו בני יהודה ובני ישראל יחדו ושמו להם ראש אחד ועלו מן הארץ כי גדול יום יזרעאל׃ ");
INSERT INTO heb_vpl VALUES ("HS2_1","029_2_1","HOS","2","1","1","אמרו לאחיכם עמי ולאחותיכם רחמה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_2","029_2_2","HOS","2","2","2","ריבו באמכם ריבו כי היא לא אשתי ואנכי לא אישה ותסר זנוניה מפניה ונאפופיה מבין שדיה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_3","029_2_3","HOS","2","3","3","פן אפשיטנה ערמה והצגתיה כיום הולדה ושמתיה כמדבר ושתה כארץ ציה והמתיה בצמא׃ ");
INSERT INTO heb_vpl VALUES ("HS2_4","029_2_4","HOS","2","4","4","ואת בניה לא ארחם כי בני זנונים המה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_5","029_2_5","HOS","2","5","5","כי זנתה אמם הבישה הורתם כי אמרה אלכה אחרי מאהבי נתני לחמי ומימי צמרי ופשתי שמני ושקויי׃ ");
INSERT INTO heb_vpl VALUES ("HS2_6","029_2_6","HOS","2","6","6","לכן הנני שך את דרכך בסירים וגדרתי את גדרה ונתיבותיה לא תמצא׃ ");
INSERT INTO heb_vpl VALUES ("HS2_7","029_2_7","HOS","2","7","7","ורדפה את מאהביה ולא תשיג אתם ובקשתם ולא תמצא ואמרה אלכה ואשובה אל אישי הראשון כי טוב לי אז מעתה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_8","029_2_8","HOS","2","8","8","והיא לא ידעה כי אנכי נתתי לה הדגן והתירוש והיצהר וכסף הרביתי לה וזהב עשו לבעל׃ ");
INSERT INTO heb_vpl VALUES ("HS2_9","029_2_9","HOS","2","9","9","לכן אשוב ולקחתי דגני בעתו ותירושי במועדו והצלתי צמרי ופשתי לכסות את ערותה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_10","029_2_10","HOS","2","10","10","ועתה אגלה את נבלתה לעיני מאהביה ואיש לא יצילנה מידי׃ ");
INSERT INTO heb_vpl VALUES ("HS2_11","029_2_11","HOS","2","11","11","והשבתי כל משושה חגה חדשה ושבתה וכל מועדה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_12","029_2_12","HOS","2","12","12","והשמתי גפנה ותאנתה אשר אמרה אתנה המה לי אשר נתנו לי מאהבי ושמתים ליער ואכלתם חית השדה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_13","029_2_13","HOS","2","13","13","ופקדתי עליה את ימי הבעלים אשר תקטיר להם ותעד נזמה וחליתה ותלך אחרי מאהביה ואתי שכחה נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_14","029_2_14","HOS","2","14","14","לכן הנה אנכי מפתיה והלכתיה המדבר ודברתי על לבה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_15","029_2_15","HOS","2","15","15","ונתתי לה את כרמיה משם ואת עמק עכור לפתח תקוה וענתה שמה כימי נעוריה וכיום עלתה מארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("HS2_16","029_2_16","HOS","2","16","16","והיה ביום ההוא נאם יהוה תקראי אישי ולא תקראי לי עוד בעלי׃ ");
INSERT INTO heb_vpl VALUES ("HS2_17","029_2_17","HOS","2","17","17","והסרתי את שמות הבעלים מפיה ולא יזכרו עוד בשמם׃ ");
INSERT INTO heb_vpl VALUES ("HS2_18","029_2_18","HOS","2","18","18","וכרתי להם ברית ביום ההוא עם חית השדה ועם עוף השמים ורמש האדמה וקשת וחרב ומלחמה אשבור מן הארץ והשכבתים לבטח׃ ");
INSERT INTO heb_vpl VALUES ("HS2_19","029_2_19","HOS","2","19","19","וארשתיך לי לעולם וארשתיך לי בצדק ובמשפט ובחסד וברחמים׃ ");
INSERT INTO heb_vpl VALUES ("HS2_20","029_2_20","HOS","2","20","20","וארשתיך לי באמונה וידעת את יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HS2_21","029_2_21","HOS","2","21","21","והיה ביום ההוא אענה נאם יהוה אענה את השמים והם יענו את הארץ׃ ");
INSERT INTO heb_vpl VALUES ("HS2_22","029_2_22","HOS","2","22","22","והארץ תענה את הדגן ואת התירוש ואת היצהר והם יענו את יזרעאל׃ ");
INSERT INTO heb_vpl VALUES ("HS2_23","029_2_23","HOS","2","23","23","וזרעתיה לי בארץ ורחמתי את לא רחמה ואמרתי ללא עמי עמי אתה והוא יאמר אלהי׃ ");
INSERT INTO heb_vpl VALUES ("HS3_1","029_3_1","HOS","3","1","1","ויאמר יהוה אלי עוד לך אהב אשה אהבת רע ומנאפת כאהבת יהוה את בני ישראל והם פנים אל אלהים אחרים ואהבי אשישי ענבים׃ ");
INSERT INTO heb_vpl VALUES ("HS3_2","029_3_2","HOS","3","2","2","ואכרה לי בחמשה עשר כסף וחמר שערים ולתך שערים׃ ");
INSERT INTO heb_vpl VALUES ("HS3_3","029_3_3","HOS","3","3","3","ואמר אליה ימים רבים תשבי לי לא תזני ולא תהיי לאיש וגם אני אליך׃ ");
INSERT INTO heb_vpl VALUES ("HS3_4","029_3_4","HOS","3","4","4","כי ימים רבים ישבו בני ישראל אין מלך ואין שר ואין זבח ואין מצבה ואין אפוד ותרפים׃ ");
INSERT INTO heb_vpl VALUES ("HS3_5","029_3_5","HOS","3","5","5","אחר ישבו בני ישראל ובקשו את יהוה אלהיהם ואת דויד מלכם ופחדו אל יהוה ואל טובו באחרית הימים׃ ");
INSERT INTO heb_vpl VALUES ("HS4_1","029_4_1","HOS","4","1","1","שמעו דבר יהוה בני ישראל כי ריב ליהוה עם יושבי הארץ כי אין אמת ואין חסד ואין דעת אלהים בארץ׃ ");
INSERT INTO heb_vpl VALUES ("HS4_2","029_4_2","HOS","4","2","2","אלה וכחש ורצח וגנב ונאף פרצו ודמים בדמים נגעו׃ ");
INSERT INTO heb_vpl VALUES ("HS4_3","029_4_3","HOS","4","3","3","על כן תאבל הארץ ואמלל כל יושב בה בחית השדה ובעוף השמים וגם דגי הים יאספו׃ ");
INSERT INTO heb_vpl VALUES ("HS4_4","029_4_4","HOS","4","4","4","אך איש אל ירב ואל יוכח איש ועמך כמריבי כהן׃ ");
INSERT INTO heb_vpl VALUES ("HS4_5","029_4_5","HOS","4","5","5","וכשלת היום וכשל גם נביא עמך לילה ודמיתי אמך׃ ");
INSERT INTO heb_vpl VALUES ("HS4_6","029_4_6","HOS","4","6","6","נדמו עמי מבלי הדעת כי אתה הדעת מאסת ואמאסאך מכהן לי ותשכח תורת אלהיך אשכח בניך גם אני׃ ");
INSERT INTO heb_vpl VALUES ("HS4_7","029_4_7","HOS","4","7","7","כרבם כן חטאו לי כבודם בקלון אמיר׃ ");
INSERT INTO heb_vpl VALUES ("HS4_8","029_4_8","HOS","4","8","8","חטאת עמי יאכלו ואל עונם ישאו נפשו׃ ");
INSERT INTO heb_vpl VALUES ("HS4_9","029_4_9","HOS","4","9","9","והיה כעם ככהן ופקדתי עליו דרכיו ומעלליו אשיב לו׃ ");
INSERT INTO heb_vpl VALUES ("HS4_10","029_4_10","HOS","4","10","10","ואכלו ולא ישבעו הזנו ולא יפרצו כי את יהוה עזבו לשמר׃ ");
INSERT INTO heb_vpl VALUES ("HS4_11","029_4_11","HOS","4","11","11","זנות ויין ותירוש יקח לב׃ ");
INSERT INTO heb_vpl VALUES ("HS4_12","029_4_12","HOS","4","12","12","עמי בעצו ישאל ומקלו יגיד לו כי רוח זנונים התעה ויזנו מתחת אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("HS4_13","029_4_13","HOS","4","13","13","על ראשי ההרים יזבחו ועל הגבעות יקטרו תחת אלון ולבנה ואלה כי טוב צלה על כן תזנינה בנותיכם וכלותיכם תנאפנה׃ ");
INSERT INTO heb_vpl VALUES ("HS4_14","029_4_14","HOS","4","14","14","לא אפקוד על בנותיכם כי תזנינה ועל כלותיכם כי תנאפנה כי הם עם הזנות יפרדו ועם הקדשות יזבחו ועם לא יבין ילבט׃ ");
INSERT INTO heb_vpl VALUES ("HS4_15","029_4_15","HOS","4","15","15","אם זנה אתה ישראל אל יאשם יהודה ואל תבאו הגלגל ואל תעלו בית און ואל תשבעו חי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HS4_16","029_4_16","HOS","4","16","16","כי כפרה סררה סרר ישראל עתה ירעם יהוה ככבש במרחב׃ ");
INSERT INTO heb_vpl VALUES ("HS4_17","029_4_17","HOS","4","17","17","חבור עצבים אפרים הנח לו׃ ");
INSERT INTO heb_vpl VALUES ("HS4_18","029_4_18","HOS","4","18","18","סר סבאם הזנה הזנו אהבו הבו קלון מגניה׃ ");
INSERT INTO heb_vpl VALUES ("HS4_19","029_4_19","HOS","4","19","19","צרר רוח אותה בכנפיה ויבשו מזבחותם׃ ");
INSERT INTO heb_vpl VALUES ("HS5_1","029_5_1","HOS","5","1","1","שמעו זאת הכהנים והקשיבו בית ישראל ובית המלך האזינו כי לכם המשפט כי פח הייתם למצפה ורשת פרושה על תבור׃ ");
INSERT INTO heb_vpl VALUES ("HS5_2","029_5_2","HOS","5","2","2","ושחטה שטים העמיקו ואני מוסר לכלם׃ ");
INSERT INTO heb_vpl VALUES ("HS5_3","029_5_3","HOS","5","3","3","אני ידעתי אפרים וישראל לא נכחד ממני כי עתה הזנית אפרים נטמא ישראל׃ ");
INSERT INTO heb_vpl VALUES ("HS5_4","029_5_4","HOS","5","4","4","לא יתנו מעלליהם לשוב אל אלהיהם כי רוח זנונים בקרבם ואת יהוה לא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("HS5_5","029_5_5","HOS","5","5","5","וענה גאון ישראל בפניו וישראל ואפרים יכשלו בעונם כשל גם יהודה עמם׃ ");
INSERT INTO heb_vpl VALUES ("HS5_6","029_5_6","HOS","5","6","6","בצאנם ובבקרם ילכו לבקש את יהוה ולא ימצאו חלץ מהם׃ ");
INSERT INTO heb_vpl VALUES ("HS5_7","029_5_7","HOS","5","7","7","ביהוה בגדו כי בנים זרים ילדו עתה יאכלם חדש את חלקיהם׃ ");
INSERT INTO heb_vpl VALUES ("HS5_8","029_5_8","HOS","5","8","8","תקעו שופר בגבעה חצצרה ברמה הריעו בית און אחריך בנימין׃ ");
INSERT INTO heb_vpl VALUES ("HS5_9","029_5_9","HOS","5","9","9","אפרים לשמה תהיה ביום תוכחה בשבטי ישראל הודעתי נאמנה׃ ");
INSERT INTO heb_vpl VALUES ("HS5_10","029_5_10","HOS","5","10","10","היו שרי יהודה כמסיגי גבול עליהם אשפוך כמים עברתי׃ ");
INSERT INTO heb_vpl VALUES ("HS5_11","029_5_11","HOS","5","11","11","עשוק אפרים רצוץ משפט כי הואיל הלך אחרי צו׃ ");
INSERT INTO heb_vpl VALUES ("HS5_12","029_5_12","HOS","5","12","12","ואני כעש לאפרים וכרקב לבית יהודה׃ ");
INSERT INTO heb_vpl VALUES ("HS5_13","029_5_13","HOS","5","13","13","וירא אפרים את חליו ויהודה את מזרו וילך אפרים אל אשור וישלח אל מלך ירב והוא לא יוכל לרפא לכם ולא יגהה מכם מזור׃ ");
INSERT INTO heb_vpl VALUES ("HS5_14","029_5_14","HOS","5","14","14","כי אנכי כשחל לאפרים וככפיר לבית יהודה אני אני אטרף ואלך אשא ואין מציל׃ ");
INSERT INTO heb_vpl VALUES ("HS5_15","029_5_15","HOS","5","15","15","אלך אשובה אל מקומי עד אשר יאשמו ובקשו פני בצר להם ישחרנני׃ ");
INSERT INTO heb_vpl VALUES ("HS6_1","029_6_1","HOS","6","1","1","לכו ונשובה אל יהוה כי הוא טרף וירפאנו יך ויחבשנו׃ ");
INSERT INTO heb_vpl VALUES ("HS6_2","029_6_2","HOS","6","2","2","יחינו מימים ביום השלישי יקמנו ונחיה לפניו׃ ");
INSERT INTO heb_vpl VALUES ("HS6_3","029_6_3","HOS","6","3","3","ונדעה נרדפה לדעת את יהוה כשחר נכון מצאו ויבוא כגשם לנו כמלקוש יורה ארץ׃ ");
INSERT INTO heb_vpl VALUES ("HS6_4","029_6_4","HOS","6","4","4","מה אעשה לך אפרים מה אעשה לך יהודה וחסדכם כענן בקר וכטל משכים הלך׃ ");
INSERT INTO heb_vpl VALUES ("HS6_5","029_6_5","HOS","6","5","5","על כן חצבתי בנביאים הרגתים באמרי פי ומשפטיך אור יצא׃ ");
INSERT INTO heb_vpl VALUES ("HS6_6","029_6_6","HOS","6","6","6","כי חסד חפצתי ולא זבח ודעת אלהים מעלות׃ ");
INSERT INTO heb_vpl VALUES ("HS6_7","029_6_7","HOS","6","7","7","והמה כאדם עברו ברית שם בגדו בי׃ ");
INSERT INTO heb_vpl VALUES ("HS6_8","029_6_8","HOS","6","8","8","גלעד קרית פעלי און עקבה מדם׃ ");
INSERT INTO heb_vpl VALUES ("HS6_9","029_6_9","HOS","6","9","9","וכחכי איש גדודים חבר כהנים דרך ירצחו שכמה כי זמה עשו׃ ");
INSERT INTO heb_vpl VALUES ("HS6_10","029_6_10","HOS","6","10","10","בבית ישראל ראיתי שעריריה שם זנות לאפרים נטמא ישראל׃ ");
INSERT INTO heb_vpl VALUES ("HS6_11","029_6_11","HOS","6","11","11","גם יהודה שת קציר לך בשובי שבות עמי׃ ");
INSERT INTO heb_vpl VALUES ("HS7_1","029_7_1","HOS","7","1","1","כרפאי לישראל ונגלה עון אפרים ורעות שמרון כי פעלו שקר וגנב יבוא פשט גדוד בחוץ׃ ");
INSERT INTO heb_vpl VALUES ("HS7_2","029_7_2","HOS","7","2","2","ובל יאמרו ללבבם כל רעתם זכרתי עתה סבבום מעלליהם נגד פני היו׃ ");
INSERT INTO heb_vpl VALUES ("HS7_3","029_7_3","HOS","7","3","3","ברעתם ישמחו מלך ובכחשיהם שרים׃ ");
INSERT INTO heb_vpl VALUES ("HS7_4","029_7_4","HOS","7","4","4","כלם מנאפים כמו תנור בערה מאפה ישבות מעיר מלוש בצק עד חמצתו׃ ");
INSERT INTO heb_vpl VALUES ("HS7_5","029_7_5","HOS","7","5","5","יום מלכנו החלו שרים חמת מיין משך ידו את לצצים׃ ");
INSERT INTO heb_vpl VALUES ("HS7_6","029_7_6","HOS","7","6","6","כי קרבו כתנור לבם בארבם כל הלילה ישן אפהם בקר הוא בער כאש להבה׃ ");
INSERT INTO heb_vpl VALUES ("HS7_7","029_7_7","HOS","7","7","7","כלם יחמו כתנור ואכלו את שפטיהם כל מלכיהם נפלו אין קרא בהם אלי׃ ");
INSERT INTO heb_vpl VALUES ("HS7_8","029_7_8","HOS","7","8","8","אפרים בעמים הוא יתבולל אפרים היה עגה בלי הפוכה׃ ");
INSERT INTO heb_vpl VALUES ("HS7_9","029_7_9","HOS","7","9","9","אכלו זרים כחו והוא לא ידע גם שיבה זרקה בו והוא לא ידע׃ ");
INSERT INTO heb_vpl VALUES ("HS7_10","029_7_10","HOS","7","10","10","וענה גאון ישראל בפניו ולא שבו אל יהוה אלהיהם ולא בקשהו בכל זאת׃ ");
INSERT INTO heb_vpl VALUES ("HS7_11","029_7_11","HOS","7","11","11","ויהי אפרים כיונה פותה אין לב מצרים קראו אשור הלכו׃ ");
INSERT INTO heb_vpl VALUES ("HS7_12","029_7_12","HOS","7","12","12","כאשר ילכו אפרוש עליהם רשתי כעוף השמים אורידם איסרם כשמע לעדתם׃ ");
INSERT INTO heb_vpl VALUES ("HS7_13","029_7_13","HOS","7","13","13","אוי להם כי נדדו ממני שד להם כי פשעו בי ואנכי אפדם והמה דברו עלי כזבים׃ ");
INSERT INTO heb_vpl VALUES ("HS7_14","029_7_14","HOS","7","14","14","ולא זעקו אלי בלבם כי יילילו על משכבותם על דגן ותירוש יתגוררו יסורו בי׃ ");
INSERT INTO heb_vpl VALUES ("HS7_15","029_7_15","HOS","7","15","15","ואני יסרתי חזקתי זרועתם ואלי יחשבו רע׃ ");
INSERT INTO heb_vpl VALUES ("HS7_16","029_7_16","HOS","7","16","16","ישובו לא על היו כקשת רמיה יפלו בחרב שריהם מזעם לשונם זו לעגם בארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("HS8_1","029_8_1","HOS","8","1","1","אל חכך שפר כנשר על בית יהוה יען עברו בריתי ועל תורתי פשעו׃ ");
INSERT INTO heb_vpl VALUES ("HS8_2","029_8_2","HOS","8","2","2","לי יזעקו אלהי ידענוך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("HS8_3","029_8_3","HOS","8","3","3","זנח ישראל טוב אויב ירדפו׃ ");
INSERT INTO heb_vpl VALUES ("HS8_4","029_8_4","HOS","8","4","4","הם המליכו ולא ממני השירו ולא ידעתי כספם וזהבם עשו להם עצבים למען יכרת׃ ");
INSERT INTO heb_vpl VALUES ("HS8_5","029_8_5","HOS","8","5","5","זנח עגלך שמרון חרה אפי בם עד מתי לא יוכלו נקין׃ ");
INSERT INTO heb_vpl VALUES ("HS8_6","029_8_6","HOS","8","6","6","כי מישראל והוא חרש עשהו ולא אלהים הוא כי שבבים יהיה עגל שמרון׃ ");
INSERT INTO heb_vpl VALUES ("HS8_7","029_8_7","HOS","8","7","7","כי רוח יזרעו וסופתה יקצרו קמה אין לו צמח בלי יעשה קמח אולי יעשה זרים יבלעהו׃ ");
INSERT INTO heb_vpl VALUES ("HS8_8","029_8_8","HOS","8","8","8","נבלע ישראל עתה היו בגוים ככלי אין חפץ בו׃ ");
INSERT INTO heb_vpl VALUES ("HS8_9","029_8_9","HOS","8","9","9","כי המה עלו אשור פרא בודד לו אפרים התנו אהבים׃ ");
INSERT INTO heb_vpl VALUES ("HS8_10","029_8_10","HOS","8","10","10","גם כי יתנו בגוים עתה אקבצם ויחלו מעט ממשא מלך שרים׃ ");
INSERT INTO heb_vpl VALUES ("HS8_11","029_8_11","HOS","8","11","11","כי הרבה אפרים מזבחת לחטא היו לו מזבחות לחטא׃ ");
INSERT INTO heb_vpl VALUES ("HS8_12","029_8_12","HOS","8","12","12","אכתוב לו רבו תורתי כמו זר נחשבו׃ ");
INSERT INTO heb_vpl VALUES ("HS8_13","029_8_13","HOS","8","13","13","זבחי הבהבי יזבחו בשר ויאכלו יהוה לא רצם עתה יזכר עונם ויפקד חטאותם המה מצרים ישובו׃ ");
INSERT INTO heb_vpl VALUES ("HS8_14","029_8_14","HOS","8","14","14","וישכח ישראל את עשהו ויבן היכלות ויהודה הרבה ערים בצרות ושלחתי אש בעריו ואכלה ארמנתיה׃ ");
INSERT INTO heb_vpl VALUES ("HS9_1","029_9_1","HOS","9","1","1","אל תשמח ישראל אל גיל כעמים כי זנית מעל אלהיך אהבת אתנן על כל גרנות דגן׃ ");
INSERT INTO heb_vpl VALUES ("HS9_2","029_9_2","HOS","9","2","2","גרן ויקב לא ירעם ותירוש יכחש בה׃ ");
INSERT INTO heb_vpl VALUES ("HS9_3","029_9_3","HOS","9","3","3","לא ישבו בארץ יהוה ושב אפרים מצרים ובאשור טמא יאכלו׃ ");
INSERT INTO heb_vpl VALUES ("HS9_4","029_9_4","HOS","9","4","4","לא יסכו ליהוה יין ולא יערבו לו זבחיהם כלחם אונים להם כל אכליו יטמאו כי לחמם לנפשם לא יבוא בית יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HS9_5","029_9_5","HOS","9","5","5","מה תעשו ליום מועד וליום חג יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HS9_6","029_9_6","HOS","9","6","6","כי הנה הלכו משד מצרים תקבצם מף תקברם מחמד לכספם קמוש יירשם חוח באהליהם׃ ");
INSERT INTO heb_vpl VALUES ("HS9_7","029_9_7","HOS","9","7","7","באו ימי הפקדה באו ימי השלם ידעו ישראל אויל הנביא משגע איש הרוח על רב עונך ורבה משטמה׃ ");
INSERT INTO heb_vpl VALUES ("HS9_8","029_9_8","HOS","9","8","8","צפה אפרים עם אלהי נביא פח יקוש על כל דרכיו משטמה בבית אלהיו׃ ");
INSERT INTO heb_vpl VALUES ("HS9_9","029_9_9","HOS","9","9","9","העמיקו שחתו כימי הגבעה יזכור עונם יפקוד חטאתם׃ ");
INSERT INTO heb_vpl VALUES ("HS9_10","029_9_10","HOS","9","10","10","כענבים במדבר מצאתי ישראל כבכורה בתאנה בראשיתה ראיתי אבותיכם המה באו בעל פעור וינזרו לבשת ויהיו שקוצים כאהבם׃ ");
INSERT INTO heb_vpl VALUES ("HS9_11","029_9_11","HOS","9","11","11","אפרים כעוף יתעופף כבודם מלדה ומבטן ומהריון׃ ");
INSERT INTO heb_vpl VALUES ("HS9_12","029_9_12","HOS","9","12","12","כי אם יגדלו את בניהם ושכלתים מאדם כי גם אוי להם בשורי מהם׃ ");
INSERT INTO heb_vpl VALUES ("HS9_13","029_9_13","HOS","9","13","13","אפרים כאשר ראיתי לצור שתולה בנוה ואפרים להוציא אל הורג בניו׃ ");
INSERT INTO heb_vpl VALUES ("HS9_14","029_9_14","HOS","9","14","14","תן להם יהוה מה תתן תן להם רחם משכיל ושדים צמקים׃ ");
INSERT INTO heb_vpl VALUES ("HS9_15","029_9_15","HOS","9","15","15","כל רעתם בגלגל כי שם שנאתים על רע מעלליהם מביתי אגרשם לא אוסף אהבתם כל שריהם סררים׃ ");
INSERT INTO heb_vpl VALUES ("HS9_16","029_9_16","HOS","9","16","16","הכה אפרים שרשם יבש פרי בלי יעשון גם כי ילדון והמתי מחמדי בטנם׃ ");
INSERT INTO heb_vpl VALUES ("HS9_17","029_9_17","HOS","9","17","17","ימאסם אלהי כי לא שמעו לו ויהיו נדדים בגוים׃ ");
INSERT INTO heb_vpl VALUES ("HS10_1","029_10_1","HOS","10","1","1","גפן בוקק ישראל פרי ישוה לו כרב לפריו הרבה למזבחות כטוב לארצו היטיבו מצבות׃ ");
INSERT INTO heb_vpl VALUES ("HS10_2","029_10_2","HOS","10","2","2","חלק לבם עתה יאשמו הוא יערף מזבחותם ישדד מצבותם׃ ");
INSERT INTO heb_vpl VALUES ("HS10_3","029_10_3","HOS","10","3","3","כי עתה יאמרו אין מלך לנו כי לא יראנו את יהוה והמלך מה יעשה לנו׃ ");
INSERT INTO heb_vpl VALUES ("HS10_4","029_10_4","HOS","10","4","4","דברו דברים אלות שוא כרת ברית ופרח כראש משפט על תלמי שדי׃ ");
INSERT INTO heb_vpl VALUES ("HS10_5","029_10_5","HOS","10","5","5","לעגלות בית און יגורו שכן שמרון כי אבל עליו עמו וכמריו עליו יגילו על כבודו כי גלה ממנו׃ ");
INSERT INTO heb_vpl VALUES ("HS10_6","029_10_6","HOS","10","6","6","גם אותו לאשור יובל מנחה למלך ירב בשנה אפרים יקח ויבוש ישראל מעצתו׃ ");
INSERT INTO heb_vpl VALUES ("HS10_7","029_10_7","HOS","10","7","7","נדמה שמרון מלכה כקצף על פני מים׃ ");
INSERT INTO heb_vpl VALUES ("HS10_8","029_10_8","HOS","10","8","8","ונשמדו במות און חטאת ישראל קוץ ודרדר יעלה על מזבחותם ואמרו להרים כסונו ולגבעות נפלו עלינו׃ ");
INSERT INTO heb_vpl VALUES ("HS10_9","029_10_9","HOS","10","9","9","מימי הגבעה חטאת ישראל שם עמדו לא תשיגם בגבעה מלחמה על בני עלוה׃ ");
INSERT INTO heb_vpl VALUES ("HS10_10","029_10_10","HOS","10","10","10","באותי ואסרם ואספו עליהם עמים באסרם לשתי עינתם׃ ");
INSERT INTO heb_vpl VALUES ("HS10_11","029_10_11","HOS","10","11","11","ואפרים עגלה מלמדה אהבתי לדוש ואני עברתי על טוב צוארה ארכיב אפרים יחרוש יהודה ישדד לו יעקב׃ ");
INSERT INTO heb_vpl VALUES ("HS10_12","029_10_12","HOS","10","12","12","זרעו לכם לצדקה קצרו לפי חסד נירו לכם ניר ועת לדרוש את יהוה עד יבוא וירה צדק לכם׃ ");
INSERT INTO heb_vpl VALUES ("HS10_13","029_10_13","HOS","10","13","13","חרשתם רשע עולתה קצרתם אכלתם פרי כחש כי בטחת בדרכך ברב גבוריך׃ ");
INSERT INTO heb_vpl VALUES ("HS10_14","029_10_14","HOS","10","14","14","וקאם שאון בעמך וכל מבצריך יושד כשד שלמן בית ארבאל ביום מלחמה אם על בנים רטשה׃ ");
INSERT INTO heb_vpl VALUES ("HS10_15","029_10_15","HOS","10","15","15","ככה עשה לכם בית אל מפני רעת רעתכם בשחר נדמה נדמה מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("HS11_1","029_11_1","HOS","11","1","1","כי נער ישראל ואהבהו וממצרים קראתי לבני׃ ");
INSERT INTO heb_vpl VALUES ("HS11_2","029_11_2","HOS","11","2","2","קראו להם כן הלכו מפניהם לבעלים יזבחו ולפסלים יקטרון׃ ");
INSERT INTO heb_vpl VALUES ("HS11_3","029_11_3","HOS","11","3","3","ואנכי תרגלתי לאפרים קחם על זרועתיו ולא ידעו כי רפאתים׃ ");
INSERT INTO heb_vpl VALUES ("HS11_4","029_11_4","HOS","11","4","4","בחבלי אדם אמשכם בעבתות אהבה ואהיה להם כמרימי על על לחיהם ואט אליו אוכיל׃ ");
INSERT INTO heb_vpl VALUES ("HS11_5","029_11_5","HOS","11","5","5","לא ישוב אל ארץ מצרים ואשור הוא מלכו כי מאנו לשוב׃ ");
INSERT INTO heb_vpl VALUES ("HS11_6","029_11_6","HOS","11","6","6","וחלה חרב בעריו וכלתה בדיו ואכלה ממעצותיהם׃ ");
INSERT INTO heb_vpl VALUES ("HS11_7","029_11_7","HOS","11","7","7","ועמי תלואים למשובתי ואל על יקראהו יחד לא ירומם׃ ");
INSERT INTO heb_vpl VALUES ("HS11_8","029_11_8","HOS","11","8","8","איך אתנך אפרים אמגנך ישראל איך אתנך כאדמה אשימך כצבאים נהפך עלי לבי יחד נכמרו נחומי׃ ");
INSERT INTO heb_vpl VALUES ("HS11_9","029_11_9","HOS","11","9","9","לא אעשה חרון אפי לא אשוב לשחת אפרים כי אל אנכי ולא איש בקרבך קדוש ולא אבוא בעיר׃ ");
INSERT INTO heb_vpl VALUES ("HS11_10","029_11_10","HOS","11","10","10","אחרי יהוה ילכו כאריה ישאג כי הוא ישאג ויחרדו בנים מים׃ ");
INSERT INTO heb_vpl VALUES ("HS11_11","029_11_11","HOS","11","11","11","יחרדו כצפור ממצרים וכיונה מארץ אשור והושבתים על בתיהם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HS11_12","029_11_12","HOS","11","12","12","סבבני בכחש אפרים ובמרמה בית ישראל ויהודה עד רד עם אל ועם קדושים נאמן׃ ");
INSERT INTO heb_vpl VALUES ("HS12_1","029_12_1","HOS","12","1","1","אפרים רעה רוח ורדף קדים כל היום כזב ושד ירבה וברית עם אשור יכרתו ושמן למצרים יובל׃ ");
INSERT INTO heb_vpl VALUES ("HS12_2","029_12_2","HOS","12","2","2","וריב ליהוה עם יהודה ולפקד על יעקב כדרכיו כמעלליו ישיב לו׃ ");
INSERT INTO heb_vpl VALUES ("HS12_3","029_12_3","HOS","12","3","3","בבטן עקב את אחיו ובאונו שרה את אלהים׃ ");
INSERT INTO heb_vpl VALUES ("HS12_4","029_12_4","HOS","12","4","4","וישר אל מלאך ויכל בכה ויתחנן לו בית אל ימצאנו ושם ידבר עמנו׃ ");
INSERT INTO heb_vpl VALUES ("HS12_5","029_12_5","HOS","12","5","5","ויהוה אלהי הצבאות יהוה זכרו׃ ");
INSERT INTO heb_vpl VALUES ("HS12_6","029_12_6","HOS","12","6","6","ואתה באלהיך תשוב חסד ומשפט שמר וקוה אל אלהיך תמיד׃ ");
INSERT INTO heb_vpl VALUES ("HS12_7","029_12_7","HOS","12","7","7","כנען בידו מאזני מרמה לעשק אהב׃ ");
INSERT INTO heb_vpl VALUES ("HS12_8","029_12_8","HOS","12","8","8","ויאמר אפרים אך עשרתי מצאתי און לי כל יגיעי לא ימצאו לי עון אשר חטא׃ ");
INSERT INTO heb_vpl VALUES ("HS12_9","029_12_9","HOS","12","9","9","ואנכי יהוה אלהיך מארץ מצרים עד אושיבך באהלים כימי מועד׃ ");
INSERT INTO heb_vpl VALUES ("HS12_10","029_12_10","HOS","12","10","10","ודברתי על הנביאים ואנכי חזון הרביתי וביד הנביאים אדמה׃ ");
INSERT INTO heb_vpl VALUES ("HS12_11","029_12_11","HOS","12","11","11","אם גלעד און אך שוא היו בגלגל שורים זבחו גם מזבחותם כגלים על תלמי שדי׃ ");
INSERT INTO heb_vpl VALUES ("HS12_12","029_12_12","HOS","12","12","12","ויברח יעקב שדה ארם ויעבד ישראל באשה ובאשה שמר׃ ");
INSERT INTO heb_vpl VALUES ("HS12_13","029_12_13","HOS","12","13","13","ובנביא העלה יהוה את ישראל ממצרים ובנביא נשמר׃ ");
INSERT INTO heb_vpl VALUES ("HS12_14","029_12_14","HOS","12","14","14","הכעיס אפרים תמרורים ודמיו עליו יטוש וחרפתו ישיב לו אדניו׃ ");
INSERT INTO heb_vpl VALUES ("HS13_1","029_13_1","HOS","13","1","1","כדבר אפרים רתת נשא הוא בישראל ויאשם בבעל וימת׃ ");
INSERT INTO heb_vpl VALUES ("HS13_2","029_13_2","HOS","13","2","2","ועתה יוספו לחטא ויעשו להם מסכה מכספם כתבונם עצבים מעשה חרשים כלה להם הם אמרים זבחי אדם עגלים ישקון׃ ");
INSERT INTO heb_vpl VALUES ("HS13_3","029_13_3","HOS","13","3","3","לכן יהיו כענן בקר וכטל משכים הלך כמץ יסער מגרן וכעשן מארבה׃ ");
INSERT INTO heb_vpl VALUES ("HS13_4","029_13_4","HOS","13","4","4","ואנכי יהוה אלהיך מארץ מצרים ואלהים זולתי לא תדע ומושיע אין בלתי׃ ");
INSERT INTO heb_vpl VALUES ("HS13_5","029_13_5","HOS","13","5","5","אני ידעתיך במדבר בארץ תלאבות׃ ");
INSERT INTO heb_vpl VALUES ("HS13_6","029_13_6","HOS","13","6","6","כמרעיתם וישבעו שבעו וירם לבם על כן שכחוני׃ ");
INSERT INTO heb_vpl VALUES ("HS13_7","029_13_7","HOS","13","7","7","ואהי להם כמו שחל כנמר על דרך אשור׃ ");
INSERT INTO heb_vpl VALUES ("HS13_8","029_13_8","HOS","13","8","8","אפגשם כדב שכול ואקרע סגור לבם ואכלם שם כלביא חית השדה תבקעם׃ ");
INSERT INTO heb_vpl VALUES ("HS13_9","029_13_9","HOS","13","9","9","שחתך ישראל כי בי בעזרך׃ ");
INSERT INTO heb_vpl VALUES ("HS13_10","029_13_10","HOS","13","10","10","אהי מלכך אפוא ויושיעך בכל עריך ושפטיך אשר אמרת תנה לי מלך ושרים׃ ");
INSERT INTO heb_vpl VALUES ("HS13_11","029_13_11","HOS","13","11","11","אתן לך מלך באפי ואקח בעברתי׃ ");
INSERT INTO heb_vpl VALUES ("HS13_12","029_13_12","HOS","13","12","12","צרור עון אפרים צפונה חטאתו׃ ");
INSERT INTO heb_vpl VALUES ("HS13_13","029_13_13","HOS","13","13","13","חבלי יולדה יבאו לו הוא בן לא חכם כי עת לא יעמד במשבר בנים׃ ");
INSERT INTO heb_vpl VALUES ("HS13_14","029_13_14","HOS","13","14","14","מיד שאול אפדם ממות אגאלם אהי דבריך מות אהי קטבך שאול נחם יסתר מעיני׃ ");
INSERT INTO heb_vpl VALUES ("HS13_15","029_13_15","HOS","13","15","15","כי הוא בין אחים יפריא יבוא קדים רוח יהוה ממדבר עלה ויבוש מקורו ויחרב מעינו הוא ישסה אוצר כל כלי חמדה׃ ");
INSERT INTO heb_vpl VALUES ("HS13_16","029_13_16","HOS","13","16","16","תאשם שמרון כי מרתה באלהיה בחרב יפלו עלליהם ירטשו והריותיו יבקעו׃ ");
INSERT INTO heb_vpl VALUES ("HS14_1","029_14_1","HOS","14","1","1","שובה ישראל עד יהוה אלהיך כי כשלת בעונך׃ ");
INSERT INTO heb_vpl VALUES ("HS14_2","029_14_2","HOS","14","2","2","קחו עמכם דברים ושובו אל יהוה אמרו אליו כל תשא עון וקח טוב ונשלמה פרים שפתינו׃ ");
INSERT INTO heb_vpl VALUES ("HS14_3","029_14_3","HOS","14","3","3","אשור לא יושיענו על סוס לא נרכב ולא נאמר עוד אלהינו למעשה ידינו אשר בך ירחם יתום׃ ");
INSERT INTO heb_vpl VALUES ("HS14_4","029_14_4","HOS","14","4","4","ארפא משובתם אהבם נדבה כי שב אפי ממנו׃ ");
INSERT INTO heb_vpl VALUES ("HS14_5","029_14_5","HOS","14","5","5","אהיה כטל לישראל יפרח כשושנה ויך שרשיו כלבנון׃ ");
INSERT INTO heb_vpl VALUES ("HS14_6","029_14_6","HOS","14","6","6","ילכו ינקותיו ויהי כזית הודו וריח לו כלבנון׃ ");
INSERT INTO heb_vpl VALUES ("HS14_7","029_14_7","HOS","14","7","7","ישבו ישבי בצלו יחיו דגן ויפרחו כגפן זכרו כיין לבנון׃ ");
INSERT INTO heb_vpl VALUES ("HS14_8","029_14_8","HOS","14","8","8","אפרים מה לי עוד לעצבים אני עניתי ואשורנו אני כברוש רענן ממני פריך נמצא׃ ");
INSERT INTO heb_vpl VALUES ("HS14_9","029_14_9","HOS","14","9","9","מי חכם ויבן אלה נבון וידעם כי ישרים דרכי יהוה וצדקים ילכו בם ופשעים יכשלו בם׃ ");
INSERT INTO heb_vpl VALUES ("JL1_1","030_1_1","JOL","1","1","1","דבר יהוה אשר היה אל יואל בן פתואל׃ ");
INSERT INTO heb_vpl VALUES ("JL1_2","030_1_2","JOL","1","2","2","שמעו זאת הזקנים והאזינו כל יושבי הארץ ההיתה זאת בימיכם ואם בימי אבתיכם׃ ");
INSERT INTO heb_vpl VALUES ("JL1_3","030_1_3","JOL","1","3","3","עליה לבניכם ספרו ובניכם לבניהם ובניהם לדור אחר׃ ");
