INSERT INTO heb_vpl VALUES ("AM1_13","031_1_13","AMO","1","13","13","כה אמר יהוה על שלשה פשעי בני עמון ועל ארבעה לא אשיבנו על בקעם הרות הגלעד למען הרחיב את גבולם׃ ");
INSERT INTO heb_vpl VALUES ("AM1_14","031_1_14","AMO","1","14","14","והצתי אש בחומת רבה ואכלה ארמנותיה בתרועה ביום מלחמה בסער ביום סופה׃ ");
INSERT INTO heb_vpl VALUES ("AM1_15","031_1_15","AMO","1","15","15","והלך מלכם בגולה הוא ושריו יחדו אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM2_1","031_2_1","AMO","2","1","1","כה אמר יהוה על שלשה פשעי מואב ועל ארבעה לא אשיבנו על שרפו עצמות מלך אדום לשיד׃ ");
INSERT INTO heb_vpl VALUES ("AM2_2","031_2_2","AMO","2","2","2","ושלחתי אש במואב ואכלה ארמנות הקריות ומת בשאון מואב בתרועה בקול שופר׃ ");
INSERT INTO heb_vpl VALUES ("AM2_3","031_2_3","AMO","2","3","3","והכרתי שופט מקרבה וכל שריה אהרוג עמו אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM2_4","031_2_4","AMO","2","4","4","כה אמר יהוה על שלשה פשעי יהודה ועל ארבעה לא אשיבנו על מאסם את תורת יהוה וחקיו לא שמרו ויתעום כזביהם אשר הלכו אבותם אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("AM2_5","031_2_5","AMO","2","5","5","ושלחתי אש ביהודה ואכלה ארמנות ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("AM2_6","031_2_6","AMO","2","6","6","כה אמר יהוה על שלשה פשעי ישראל ועל ארבעה לא אשיבנו על מכרם בכסף צדיק ואביון בעבור נעלים׃ ");
INSERT INTO heb_vpl VALUES ("AM2_7","031_2_7","AMO","2","7","7","השאפים על עפר ארץ בראש דלים ודרך ענוים יטו ואיש ואביו ילכו אל הנערה למען חלל את שם קדשי׃ ");
INSERT INTO heb_vpl VALUES ("AM2_8","031_2_8","AMO","2","8","8","ועל בגדים חבלים יטו אצל כל מזבח ויין ענושים ישתו בית אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("AM2_9","031_2_9","AMO","2","9","9","ואנכי השמדתי את האמרי מפניהם אשר כגבה ארזים גבהו וחסן הוא כאלונים ואשמיד פריו ממעל ושרשיו מתחת׃ ");
INSERT INTO heb_vpl VALUES ("AM2_10","031_2_10","AMO","2","10","10","ואנכי העליתי אתכם מארץ מצרים ואולך אתכם במדבר ארבעים שנה לרשת את ארץ האמרי׃ ");
INSERT INTO heb_vpl VALUES ("AM2_11","031_2_11","AMO","2","11","11","ואקים מבניכם לנביאים ומבחוריכם לנזרים האף אין זאת בני ישראל נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM2_12","031_2_12","AMO","2","12","12","ותשקו את הנזרים יין ועל הנביאים צויתם לאמר לא תנבאו׃ ");
INSERT INTO heb_vpl VALUES ("AM2_13","031_2_13","AMO","2","13","13","הנה אנכי מעיק תחתיכם כאשר תעיק העגלה המלאה לה עמיר׃ ");
INSERT INTO heb_vpl VALUES ("AM2_14","031_2_14","AMO","2","14","14","ואבד מנוס מקל וחזק לא יאמץ כחו וגבור לא ימלט נפשו׃ ");
INSERT INTO heb_vpl VALUES ("AM2_15","031_2_15","AMO","2","15","15","ותפש הקשת לא יעמד וקל ברגליו לא ימלט ורכב הסוס לא ימלט נפשו׃ ");
INSERT INTO heb_vpl VALUES ("AM2_16","031_2_16","AMO","2","16","16","ואמיץ לבו בגבורים ערום ינוס ביום ההוא נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM3_1","031_3_1","AMO","3","1","1","שמעו את הדבר הזה אשר דבר יהוה עליכם בני ישראל על כל המשפחה אשר העליתי מארץ מצרים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("AM3_2","031_3_2","AMO","3","2","2","רק אתכם ידעתי מכל משפחות האדמה על כן אפקד עליכם את כל עונתיכם׃ ");
INSERT INTO heb_vpl VALUES ("AM3_3","031_3_3","AMO","3","3","3","הילכו שנים יחדו בלתי אם נועדו׃ ");
INSERT INTO heb_vpl VALUES ("AM3_4","031_3_4","AMO","3","4","4","הישאג אריה ביער וטרף אין לו היתן כפיר קולו ממענתו בלתי אם לכד׃ ");
INSERT INTO heb_vpl VALUES ("AM3_5","031_3_5","AMO","3","5","5","התפל צפור על פח הארץ ומוקש אין לה היעלה פח מן האדמה ולכוד לא ילכוד׃ ");
INSERT INTO heb_vpl VALUES ("AM3_6","031_3_6","AMO","3","6","6","אם יתקע שופר בעיר ועם לא יחרדו אם תהיה רעה בעיר ויהוה לא עשה׃ ");
INSERT INTO heb_vpl VALUES ("AM3_7","031_3_7","AMO","3","7","7","כי לא יעשה אדני יהוה דבר כי אם גלה סודו אל עבדיו הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("AM3_8","031_3_8","AMO","3","8","8","אריה שאג מי לא יירא אדני יהוה דבר מי לא ינבא׃ ");
INSERT INTO heb_vpl VALUES ("AM3_9","031_3_9","AMO","3","9","9","השמיעו על ארמנות באשדוד ועל ארמנות בארץ מצרים ואמרו האספו על הרי שמרון וראו מהומת רבות בתוכה ועשוקים בקרבה׃ ");
INSERT INTO heb_vpl VALUES ("AM3_10","031_3_10","AMO","3","10","10","ולא ידעו עשות נכחה נאם יהוה האוצרים חמס ושד בארמנותיהם׃ ");
INSERT INTO heb_vpl VALUES ("AM3_11","031_3_11","AMO","3","11","11","לכן כה אמר אדני יהוה צר וסביב הארץ והורד ממך עזך ונבזו ארמנותיך׃ ");
INSERT INTO heb_vpl VALUES ("AM3_12","031_3_12","AMO","3","12","12","כה אמר יהוה כאשר יציל הרעה מפי הארי שתי כרעים או בדל אזן כן ינצלו בני ישראל הישבים בשמרון בפאת מטה ובדמשק ערש׃ ");
INSERT INTO heb_vpl VALUES ("AM3_13","031_3_13","AMO","3","13","13","שמעו והעידו בבית יעקב נאם אדני יהוה אלהי הצבאות׃ ");
INSERT INTO heb_vpl VALUES ("AM3_14","031_3_14","AMO","3","14","14","כי ביום פקדי פשעי ישראל עליו ופקדתי על מזבחות בית אל ונגדעו קרנות המזבח ונפלו לארץ׃ ");
INSERT INTO heb_vpl VALUES ("AM3_15","031_3_15","AMO","3","15","15","והכיתי בית החרף על בית הקיץ ואבדו בתי השן וספו בתים רבים נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_1","031_4_1","AMO","4","1","1","שמעו הדבר הזה פרות הבשן אשר בהר שמרון העשקות דלים הרצצות אביונים האמרת לאדניהם הביאה ונשתה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_2","031_4_2","AMO","4","2","2","נשבע אדני יהוה בקדשו כי הנה ימים באים עליכם ונשא אתכם בצנות ואחריתכן בסירות דוגה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_3","031_4_3","AMO","4","3","3","ופרצים תצאנה אשה נגדה והשלכתנה ההרמונה נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_4","031_4_4","AMO","4","4","4","באו בית אל ופשעו הגלגל הרבו לפשע והביאו לבקר זבחיכם לשלשת ימים מעשרתיכם׃ ");
INSERT INTO heb_vpl VALUES ("AM4_5","031_4_5","AMO","4","5","5","וקטר מחמץ תודה וקראו נדבות השמיעו כי כן אהבתם בני ישראל נאם אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_6","031_4_6","AMO","4","6","6","וגם אני נתתי לכם נקיון שנים בכל עריכם וחסר לחם בכל מקומתיכם ולא שבתם עדי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_7","031_4_7","AMO","4","7","7","וגם אנכי מנעתי מכם את הגשם בעוד שלשה חדשים לקציר והמטרתי על עיר אחת ועל עיר אחת לא אמטיר חלקה אחת תמטר וחלקה אשר לא תמטיר עליה תיבש׃ ");
INSERT INTO heb_vpl VALUES ("AM4_8","031_4_8","AMO","4","8","8","ונעו שתים שלש ערים אל עיר אחת לשתות מים ולא ישבעו ולא שבתם עדי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_9","031_4_9","AMO","4","9","9","הכיתי אתכם בשדפון ובירקון הרבות גנותיכם וכרמיכם ותאניכם וזיתיכם יאכל הגזם ולא שבתם עדי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_10","031_4_10","AMO","4","10","10","שלחתי בכם דבר בדרך מצרים הרגתי בחרב בחוריכם עם שבי סוסיכם ואעלה באש מחניכם ובאפכם ולא שבתם עדי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_11","031_4_11","AMO","4","11","11","הפכתי בכם כמהפכת אלהים את סדם ואת עמרה ותהיו כאוד מצל משרפה ולא שבתם עדי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM4_12","031_4_12","AMO","4","12","12","לכן כה אעשה לך ישראל עקב כי זאת אעשה לך הכון לקראת אלהיך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AM4_13","031_4_13","AMO","4","13","13","כי הנה יוצר הרים וברא רוח ומגיד לאדם מה שחו עשה שחר עיפה ודרך על במתי ארץ יהוה אלהי צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("AM5_1","031_5_1","AMO","5","1","1","שמעו את הדבר הזה אשר אנכי נשא עליכם קינה בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AM5_2","031_5_2","AMO","5","2","2","נפלה לא תוסיף קום בתולת ישראל נטשה על אדמתה אין מקימה׃ ");
INSERT INTO heb_vpl VALUES ("AM5_3","031_5_3","AMO","5","3","3","כי כה אמר אדני יהוה העיר היצאת אלף תשאיר מאה והיוצאת מאה תשאיר עשרה לבית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AM5_4","031_5_4","AMO","5","4","4","כי כה אמר יהוה לבית ישראל דרשוני וחיו׃ ");
INSERT INTO heb_vpl VALUES ("AM5_5","031_5_5","AMO","5","5","5","ואל תדרשו בית אל והגלגל לא תבאו ובאר שבע לא תעברו כי הגלגל גלה יגלה ובית אל יהיה לאון׃ ");
INSERT INTO heb_vpl VALUES ("AM5_6","031_5_6","AMO","5","6","6","דרשו את יהוה וחיו פן יצלח כאש בית יוסף ואכלה ואין מכבה לבית אל׃ ");
INSERT INTO heb_vpl VALUES ("AM5_7","031_5_7","AMO","5","7","7","ההפכים ללענה משפט וצדקה לארץ הניחו׃ ");
INSERT INTO heb_vpl VALUES ("AM5_8","031_5_8","AMO","5","8","8","עשה כימה וכסיל והפך לבקר צלמות ויום לילה החשיך הקורא למי הים וישפכם על פני הארץ יהוה שמו׃ ");
INSERT INTO heb_vpl VALUES ("AM5_9","031_5_9","AMO","5","9","9","המבליג שד על עז ושד על מבצר יבוא׃ ");
INSERT INTO heb_vpl VALUES ("AM5_10","031_5_10","AMO","5","10","10","שנאו בשער מוכיח ודבר תמים יתעבו׃ ");
INSERT INTO heb_vpl VALUES ("AM5_11","031_5_11","AMO","5","11","11","לכן יען בושסכם על דל ומשאת בר תקחו ממנו בתי גזית בניתם ולא תשבו בם כרמי חמד נטעתם ולא תשתו את יינם׃ ");
INSERT INTO heb_vpl VALUES ("AM5_12","031_5_12","AMO","5","12","12","כי ידעתי רבים פשעיכם ועצמים חטאתיכם צררי צדיק לקחי כפר ואביונים בשער הטו׃ ");
INSERT INTO heb_vpl VALUES ("AM5_13","031_5_13","AMO","5","13","13","לכן המשכיל בעת ההיא ידם כי עת רעה היא׃ ");
INSERT INTO heb_vpl VALUES ("AM5_14","031_5_14","AMO","5","14","14","דרשו טוב ואל רע למען תחיו ויהי כן יהוה אלהי צבאות אתכם כאשר אמרתם׃ ");
INSERT INTO heb_vpl VALUES ("AM5_15","031_5_15","AMO","5","15","15","שנאו רע ואהבו טוב והציגו בשער משפט אולי יחנן יהוה אלהי צבאות שארית יוסף׃ ");
INSERT INTO heb_vpl VALUES ("AM5_16","031_5_16","AMO","5","16","16","לכן כה אמר יהוה אלהי צבאות אדני בכל רחבות מספד ובכל חוצות יאמרו הו הו וקראו אכר אל אבל ומספד אל יודעי נהי׃ ");
INSERT INTO heb_vpl VALUES ("AM5_17","031_5_17","AMO","5","17","17","ובכל כרמים מספד כי אעבר בקרבך אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM5_18","031_5_18","AMO","5","18","18","הוי המתאוים את יום יהוה למה זה לכם יום יהוה הוא חשך ולא אור׃ ");
INSERT INTO heb_vpl VALUES ("AM5_19","031_5_19","AMO","5","19","19","כאשר ינוס איש מפני הארי ופגעו הדב ובא הבית וסמך ידו על הקיר ונשכו הנחש׃ ");
INSERT INTO heb_vpl VALUES ("AM5_20","031_5_20","AMO","5","20","20","הלא חשך יום יהוה ולא אור ואפל ולא נגה לו׃ ");
INSERT INTO heb_vpl VALUES ("AM5_21","031_5_21","AMO","5","21","21","שנאתי מאסתי חגיכם ולא אריח בעצרתיכם׃ ");
INSERT INTO heb_vpl VALUES ("AM5_22","031_5_22","AMO","5","22","22","כי אם תעלו לי עלות ומנחתיכם לא ארצה ושלם מריאיכם לא אביט׃ ");
INSERT INTO heb_vpl VALUES ("AM5_23","031_5_23","AMO","5","23","23","הסר מעלי המון שריך וזמרת נבליך לא אשמע׃ ");
INSERT INTO heb_vpl VALUES ("AM5_24","031_5_24","AMO","5","24","24","ויגל כמים משפט וצדקה כנחל איתן׃ ");
INSERT INTO heb_vpl VALUES ("AM5_25","031_5_25","AMO","5","25","25","הזבחים ומנחה הגשתם לי במדבר ארבעים שנה בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AM5_26","031_5_26","AMO","5","26","26","ונשאתם את סכות מלככם ואת כיון צלמיכם כוכב אלהיכם אשר עשיתם לכם׃ ");
INSERT INTO heb_vpl VALUES ("AM5_27","031_5_27","AMO","5","27","27","והגליתי אתכם מהלאה לדמשק אמר יהוה אלהי צבאות שמו׃ ");
INSERT INTO heb_vpl VALUES ("AM6_1","031_6_1","AMO","6","1","1","הוי השאננים בציון והבטחים בהר שמרון נקבי ראשית הגוים ובאו להם בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AM6_2","031_6_2","AMO","6","2","2","עברו כלנה וראו ולכו משם חמת רבה ורדו גת פלשתים הטובים מן הממלכות האלה אם רב גבולם מגבלכם׃ ");
INSERT INTO heb_vpl VALUES ("AM6_3","031_6_3","AMO","6","3","3","המנדים ליום רע ותגישון שבת חמס׃ ");
INSERT INTO heb_vpl VALUES ("AM6_4","031_6_4","AMO","6","4","4","השכבים על מטות שן וסרחים על ערשותם ואכלים כרים מצאן ועגלים מתוך מרבק׃ ");
INSERT INTO heb_vpl VALUES ("AM6_5","031_6_5","AMO","6","5","5","הפרטים על פי הנבל כדויד חשבו להם כלי שיר׃ ");
INSERT INTO heb_vpl VALUES ("AM6_6","031_6_6","AMO","6","6","6","השתים במזרקי יין וראשית שמנים ימשחו ולא נחלו על שבר יוסף׃ ");
INSERT INTO heb_vpl VALUES ("AM6_7","031_6_7","AMO","6","7","7","לכן עתה יגלו בראש גלים וסר מרזח סרוחים׃ ");
INSERT INTO heb_vpl VALUES ("AM6_8","031_6_8","AMO","6","8","8","נשבע אדני יהוה בנפשו נאם יהוה אלהי צבאות מתאב אנכי את גאון יעקב וארמנתיו שנאתי והסגרתי עיר ומלאה׃ ");
INSERT INTO heb_vpl VALUES ("AM6_9","031_6_9","AMO","6","9","9","והיה אם יותרו עשרה אנשים בבית אחד ומתו׃ ");
INSERT INTO heb_vpl VALUES ("AM6_10","031_6_10","AMO","6","10","10","ונשאו דודו ומסרפו להוציא עצמים מן הבית ואמר לאשר בירכתי הבית העוד עמך ואמר אפס ואמר הס כי לא להזכיר בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM6_11","031_6_11","AMO","6","11","11","כי הנה יהוה מצוה והכה הבית הגדול רסיסים והבית הקטן בקעים׃ ");
INSERT INTO heb_vpl VALUES ("AM6_12","031_6_12","AMO","6","12","12","הירצון בסלע סוסים אם יחרוש בבקרים כי הפכתם לראש משפט ופרי צדקה ללענה׃ ");
INSERT INTO heb_vpl VALUES ("AM6_13","031_6_13","AMO","6","13","13","השמחים ללא דבר האמרים הלוא בחזקנו לקחנו לנו קרנים׃ ");
INSERT INTO heb_vpl VALUES ("AM6_14","031_6_14","AMO","6","14","14","כי הנני מקים עליכם בית ישראל נאם יהוה אלהי הצבאות גוי ולחצו אתכם מלבוא חמת עד נחל הערבה׃ ");
INSERT INTO heb_vpl VALUES ("AM7_1","031_7_1","AMO","7","1","1","כה הראני אדני יהוה והנה יוצר גבי בתחלת עלות הלקש והנה לקש אחר גזי המלך׃ ");
INSERT INTO heb_vpl VALUES ("AM7_2","031_7_2","AMO","7","2","2","והיה אם כלה לאכול את עשב הארץ ואמר אדני יהוה סלח נא מי יקום יעקב כי קטן הוא׃ ");
INSERT INTO heb_vpl VALUES ("AM7_3","031_7_3","AMO","7","3","3","נחם יהוה על זאת לא תהיה אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM7_4","031_7_4","AMO","7","4","4","כה הראני אדני יהוה והנה קרא לרב באש אדני יהוה ותאכל את תהום רבה ואכלה את החלק׃ ");
INSERT INTO heb_vpl VALUES ("AM7_5","031_7_5","AMO","7","5","5","ואמר אדני יהוה חדל נא מי יקום יעקב כי קטן הוא׃ ");
INSERT INTO heb_vpl VALUES ("AM7_6","031_7_6","AMO","7","6","6","נחם יהוה על זאת גם היא לא תהיה אמר אדני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM7_7","031_7_7","AMO","7","7","7","כה הראני והנה אדני נצב על חומת אנך ובידו אנך׃ ");
INSERT INTO heb_vpl VALUES ("AM7_8","031_7_8","AMO","7","8","8","ויאמר יהוה אלי מה אתה ראה עמוס ואמר אנך ויאמר אדני הנני שם אנך בקרב עמי ישראל לא אוסיף עוד עבור לו׃ ");
INSERT INTO heb_vpl VALUES ("AM7_9","031_7_9","AMO","7","9","9","ונשמו במות ישחק ומקדשי ישראל יחרבו וקמתי על בית ירבעם בחרב׃ ");
INSERT INTO heb_vpl VALUES ("AM7_10","031_7_10","AMO","7","10","10","וישלח אמציה כהן בית אל אל ירבעם מלך ישראל לאמר קשר עליך עמוס בקרב בית ישראל לא תוכל הארץ להכיל את כל דבריו׃ ");
INSERT INTO heb_vpl VALUES ("AM7_11","031_7_11","AMO","7","11","11","כי כה אמר עמוס בחרב ימות ירבעם וישראל גלה יגלה מעל אדמתו׃ ");
INSERT INTO heb_vpl VALUES ("AM7_12","031_7_12","AMO","7","12","12","ויאמר אמציה אל עמוס חזה לך ברח לך אל ארץ יהודה ואכל שם לחם ושם תנבא׃ ");
INSERT INTO heb_vpl VALUES ("AM7_13","031_7_13","AMO","7","13","13","ובית אל לא תוסיף עוד להנבא כי מקדש מלך הוא ובית ממלכה הוא׃ ");
INSERT INTO heb_vpl VALUES ("AM7_14","031_7_14","AMO","7","14","14","ויען עמוס ויאמר אל אמציה לא נביא אנכי ולא בן נביא אנכי כי בוקר אנכי ובולס שקמים׃ ");
INSERT INTO heb_vpl VALUES ("AM7_15","031_7_15","AMO","7","15","15","ויקחני יהוה מאחרי הצאן ויאמר אלי יהוה לך הנבא אל עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AM7_16","031_7_16","AMO","7","16","16","ועתה שמע דבר יהוה אתה אמר לא תנבא על ישראל ולא תטיף על בית ישחק׃ ");
INSERT INTO heb_vpl VALUES ("AM7_17","031_7_17","AMO","7","17","17","לכן כה אמר יהוה אשתך בעיר תזנה ובניך ובנתיך בחרב יפלו ואדמתך בחבל תחלק ואתה על אדמה טמאה תמות וישראל גלה יגלה מעל אדמתו׃ ");
INSERT INTO heb_vpl VALUES ("AM8_1","031_8_1","AMO","8","1","1","כה הראני אדני יהוה והנה כלוב קיץ׃ ");
INSERT INTO heb_vpl VALUES ("AM8_2","031_8_2","AMO","8","2","2","ויאמר מה אתה ראה עמוס ואמר כלוב קיץ ויאמר יהוה אלי בא הקץ אל עמי ישראל לא אוסיף עוד עבור לו׃ ");
INSERT INTO heb_vpl VALUES ("AM8_3","031_8_3","AMO","8","3","3","והילילו שירות היכל ביום ההוא נאם אדני יהוה רב הפגר בכל מקום השליך הס׃ ");
INSERT INTO heb_vpl VALUES ("AM8_4","031_8_4","AMO","8","4","4","שמעו זאת השאפים אביון ולשבית ענוי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("AM8_5","031_8_5","AMO","8","5","5","לאמר מתי יעבר החדש ונשבירה שבר והשבת ונפתחה בר להקטין איפה ולהגדיל שקל ולעות מאזני מרמה׃ ");
INSERT INTO heb_vpl VALUES ("AM8_6","031_8_6","AMO","8","6","6","לקנות בכסף דלים ואביון בעבור נעלים ומפל בר נשביר׃ ");
INSERT INTO heb_vpl VALUES ("AM8_7","031_8_7","AMO","8","7","7","נשבע יהוה בגאון יעקב אם אשכח לנצח כל מעשיהם׃ ");
INSERT INTO heb_vpl VALUES ("AM8_8","031_8_8","AMO","8","8","8","העל זאת לא תרגז הארץ ואבל כל יושב בה ועלתה כאר כלה ונגרשה ונשקה כיאור מצרים׃ ");
INSERT INTO heb_vpl VALUES ("AM8_9","031_8_9","AMO","8","9","9","והיה ביום ההוא נאם אדני יהוה והבאתי השמש בצהרים והחשכתי לארץ ביום אור׃ ");
INSERT INTO heb_vpl VALUES ("AM8_10","031_8_10","AMO","8","10","10","והפכתי חגיכם לאבל וכל שיריכם לקינה והעליתי על כל מתנים שק ועל כל ראש קרחה ושמתיה כאבל יחיד ואחריתה כיום מר׃ ");
INSERT INTO heb_vpl VALUES ("AM8_11","031_8_11","AMO","8","11","11","הנה ימים באים נאם אדני יהוה והשלחתי רעב בארץ לא רעב ללחם ולא צמא למים כי אם לשמע את דברי יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM8_12","031_8_12","AMO","8","12","12","ונעו מים עד ים ומצפון ועד מזרח ישוטטו לבקש את דבר יהוה ולא ימצאו׃ ");
INSERT INTO heb_vpl VALUES ("AM8_13","031_8_13","AMO","8","13","13","ביום ההוא תתעלפנה הבתולת היפות והבחורים בצמא׃ ");
INSERT INTO heb_vpl VALUES ("AM8_14","031_8_14","AMO","8","14","14","הנשבעים באשמת שמרון ואמרו חי אלהיך דן וחי דרך באר שבע ונפלו ולא יקומו עוד׃ ");
INSERT INTO heb_vpl VALUES ("AM9_1","031_9_1","AMO","9","1","1","ראיתי את אדני נצב על המזבח ויאמר הך הכפתור וירעשו הספים ובצעם בראש כלם ואחריתם בחרב אהרג לא ינוס להם נס ולא ימלט להם פליט׃ ");
INSERT INTO heb_vpl VALUES ("AM9_2","031_9_2","AMO","9","2","2","אם יחתרו בשאול משם ידי תקחם ואם יעלו השמים משם אורידם׃ ");
INSERT INTO heb_vpl VALUES ("AM9_3","031_9_3","AMO","9","3","3","ואם יחבאו בראש הכרמל משם אחפש ולקחתים ואם יסתרו מנגד עיני בקרקע הים משם אצוה את הנחש ונשכם׃ ");
INSERT INTO heb_vpl VALUES ("AM9_4","031_9_4","AMO","9","4","4","ואם ילכו בשבי לפני איביהם משם אצוה את החרב והרגתם ושמתי עיני עליהם לרעה ולא לטובה׃ ");
INSERT INTO heb_vpl VALUES ("AM9_5","031_9_5","AMO","9","5","5","ואדני יהוה הצבאות הנוגע בארץ ותמוג ואבלו כל יושבי בה ועלתה כיאר כלה ושקעה כיאר מצרים׃ ");
INSERT INTO heb_vpl VALUES ("AM9_6","031_9_6","AMO","9","6","6","הבונה בשמים מעלותו ואגדתו על ארץ יסדה הקרא למי הים וישפכם על פני הארץ יהוה שמו׃ ");
INSERT INTO heb_vpl VALUES ("AM9_7","031_9_7","AMO","9","7","7","הלוא כבני כשיים אתם לי בני ישראל נאם יהוה הלוא את ישראל העליתי מארץ מצרים ופלשתיים מכפתור וארם מקיר׃ ");
INSERT INTO heb_vpl VALUES ("AM9_8","031_9_8","AMO","9","8","8","הנה עיני אדני יהוה בממלכה החטאה והשמדתי אתה מעל פני האדמה אפס כי לא השמיד אשמיד את בית יעקב נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AM9_9","031_9_9","AMO","9","9","9","כי הנה אנכי מצוה והנעותי בכל הגוים את בית ישראל כאשר ינוע בכברה ולא יפול צרור ארץ׃ ");
INSERT INTO heb_vpl VALUES ("AM9_10","031_9_10","AMO","9","10","10","בחרב ימותו כל חטאי עמי האמרים לא תגיש ותקדים בעדינו הרעה׃ ");
INSERT INTO heb_vpl VALUES ("AM9_11","031_9_11","AMO","9","11","11","ביום ההוא אקים את סכת דויד הנפלת וגדרתי את פרציהן והרסתיו אקים ובניתיה כימי עולם׃ ");
INSERT INTO heb_vpl VALUES ("AM9_12","031_9_12","AMO","9","12","12","למען יירשו את שארית אדום וכל הגוים אשר נקרא שמי עליהם נאם יהוה עשה זאת׃ ");
INSERT INTO heb_vpl VALUES ("AM9_13","031_9_13","AMO","9","13","13","הנה ימים באים נאם יהוה ונגש חורש בקצר ודרך ענבים במשך הזרע והטיפו ההרים עסיס וכל הגבעות תתמוגגנה׃ ");
INSERT INTO heb_vpl VALUES ("AM9_14","031_9_14","AMO","9","14","14","ושבתי את שבות עמי ישראל ובנו ערים נשמות וישבו ונטעו כרמים ושתו את יינם ועשו גנות ואכלו את פריהם׃ ");
INSERT INTO heb_vpl VALUES ("AM9_15","031_9_15","AMO","9","15","15","ונטעתים על אדמתם ולא ינתשו עוד מעל אדמתם אשר נתתי להם אמר יהוה אלהיך׃ ");
INSERT INTO heb_vpl VALUES ("OB1_1","032_1_1","OBA","1","1","1","חזון עבדיה כה אמר אדני יהוה לאדום שמועה שמענו מאת יהוה וציר בגוים שלח קומו ונקומה עליה למלחמה׃ ");
INSERT INTO heb_vpl VALUES ("OB1_2","032_1_2","OBA","1","2","2","הנה קטן נתתיך בגוים בזוי אתה מאד׃ ");
INSERT INTO heb_vpl VALUES ("OB1_3","032_1_3","OBA","1","3","3","זדון לבך השיאך שכני בחגוי סלע מרום שבתו אמר בלבו מי יורדני ארץ׃ ");
INSERT INTO heb_vpl VALUES ("OB1_4","032_1_4","OBA","1","4","4","אם תגביה כנשר ואם בין כוכבים שים קנך משם אורידך נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("OB1_5","032_1_5","OBA","1","5","5","אם גנבים באו לך אם שודדי לילה איך נדמיתה הלוא יגנבו דים אם בצרים באו לך הלוא ישאירו עללות׃ ");
INSERT INTO heb_vpl VALUES ("OB1_6","032_1_6","OBA","1","6","6","איך נחפשו עשו נבעו מצפניו׃ ");
INSERT INTO heb_vpl VALUES ("OB1_7","032_1_7","OBA","1","7","7","עד הגבול שלחוך כל אנשי בריתך השיאוך יכלו לך אנשי שלמך לחמך ישימו מזור תחתיך אין תבונה בו׃ ");
INSERT INTO heb_vpl VALUES ("OB1_8","032_1_8","OBA","1","8","8","הלוא ביום ההוא נאם יהוה והאבדתי חכמים מאדום ותבונה מהר עשו׃ ");
INSERT INTO heb_vpl VALUES ("OB1_9","032_1_9","OBA","1","9","9","וחתו גבוריך תימן למען יכרת איש מהר עשו מקטל׃ ");
INSERT INTO heb_vpl VALUES ("OB1_10","032_1_10","OBA","1","10","10","מחמס אחיך יעקב תכסך בושה ונכרת לעולם׃ ");
INSERT INTO heb_vpl VALUES ("OB1_11","032_1_11","OBA","1","11","11","ביום עמדך מנגד ביום שבות זרים חילו ונכרים באו שערו ועל ירושלם ידו גורל גם אתה כאחד מהם׃ ");
INSERT INTO heb_vpl VALUES ("OB1_12","032_1_12","OBA","1","12","12","ואל תרא ביום אחיך ביום נכרו ואל תשמח לבני יהודה ביום אבדם ואל תגדל פיך ביום צרה׃ ");
INSERT INTO heb_vpl VALUES ("OB1_13","032_1_13","OBA","1","13","13","אל תבוא בשער עמי ביום אידם אל תרא גם אתה ברעתו ביום אידו ואל תשלחנה בחילו ביום אידו׃ ");
INSERT INTO heb_vpl VALUES ("OB1_14","032_1_14","OBA","1","14","14","ואל תעמד על הפרק להכרית את פליטיו ואל תסגר שרידיו ביום צרה׃ ");
INSERT INTO heb_vpl VALUES ("OB1_15","032_1_15","OBA","1","15","15","כי קרוב יום יהוה על כל הגוים כאשר עשית יעשה לך גמלך ישוב בראשך׃ ");
INSERT INTO heb_vpl VALUES ("OB1_16","032_1_16","OBA","1","16","16","כי כאשר שתיתם על הר קדשי ישתו כל הגוים תמיד ושתו ולעו והיו כלוא היו׃ ");
INSERT INTO heb_vpl VALUES ("OB1_17","032_1_17","OBA","1","17","17","ובהר ציון תהיה פליטה והיה קדש וירשו בית יעקב את מורשיהם׃ ");
INSERT INTO heb_vpl VALUES ("OB1_18","032_1_18","OBA","1","18","18","והיה בית יעקב אש ובית יוסף להבה ובית עשו לקש ודלקו בהם ואכלום ולא יהיה שריד לבית עשו כי יהוה דבר׃ ");
INSERT INTO heb_vpl VALUES ("OB1_19","032_1_19","OBA","1","19","19","וירשו הנגב את הר עשו והשפלה את פלשתים וירשו את שדה אפרים ואת שדה שמרון ובנימן את הגלעד׃ ");
INSERT INTO heb_vpl VALUES ("OB1_20","032_1_20","OBA","1","20","20","וגלת החל הזה לבני ישראל אשר כנענים עד צרפת וגלת ירושלם אשר בספרד ירשו את ערי הנגב׃ ");
INSERT INTO heb_vpl VALUES ("OB1_21","032_1_21","OBA","1","21","21","ועלו מושעים בהר ציון לשפט את הר עשו והיתה ליהוה המלוכה׃ ");
INSERT INTO heb_vpl VALUES ("JH1_1","033_1_1","JON","1","1","1","ויהי דבר יהוה אל יונה בן אמתי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JH1_2","033_1_2","JON","1","2","2","קום לך אל נינוה העיר הגדולה וקרא עליה כי עלתה רעתם לפני׃ ");
INSERT INTO heb_vpl VALUES ("JH1_3","033_1_3","JON","1","3","3","ויקם יונה לברח תרשישה מלפני יהוה וירד יפו וימצא אניה באה תרשיש ויתן שכרה וירד בה לבוא עמהם תרשישה מלפני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JH1_4","033_1_4","JON","1","4","4","ויהוה הטיל רוח גדולה אל הים ויהי סער גדול בים והאניה חשבה להשבר׃ ");
INSERT INTO heb_vpl VALUES ("JH1_5","033_1_5","JON","1","5","5","וייראו המלחים ויזעקו איש אל אלהיו ויטלו את הכלים אשר באניה אל הים להקל מעליהם ויונה ירד אל ירכתי הספינה וישכב וירדם׃ ");
INSERT INTO heb_vpl VALUES ("JH1_6","033_1_6","JON","1","6","6","ויקרב אליו רב החבל ויאמר לו מה לך נרדם קום קרא אל אלהיך אולי יתעשת האלהים לנו ולא נאבד׃ ");
INSERT INTO heb_vpl VALUES ("JH1_7","033_1_7","JON","1","7","7","ויאמרו איש אל רעהו לכו ונפילה גורלות ונדעה בשלמי הרעה הזאת לנו ויפלו גורלות ויפל הגורל על יונה׃ ");
INSERT INTO heb_vpl VALUES ("JH1_8","033_1_8","JON","1","8","8","ויאמרו אליו הגידה נא לנו באשר למי הרעה הזאת לנו מה מלאכתך ומאין תבוא מה ארצך ואי מזה עם אתה׃ ");
INSERT INTO heb_vpl VALUES ("JH1_9","033_1_9","JON","1","9","9","ויאמר אליהם עברי אנכי ואת יהוה אלהי השמים אני ירא אשר עשה את הים ואת היבשה׃ ");
INSERT INTO heb_vpl VALUES ("JH1_10","033_1_10","JON","1","10","10","וייראו האנשים יראה גדולה ויאמרו אליו מה זאת עשית כי ידעו האנשים כי מלפני יהוה הוא ברח כי הגיד להם׃ ");
INSERT INTO heb_vpl VALUES ("JH1_11","033_1_11","JON","1","11","11","ויאמרו אליו מה נעשה לך וישתק הים מעלינו כי הים הולך וסער׃ ");
INSERT INTO heb_vpl VALUES ("JH1_12","033_1_12","JON","1","12","12","ויאמר אליהם שאוני והטילני אל הים וישתק הים מעליכם כי יודע אני כי בשלי הסער הגדול הזה עליכם׃ ");
INSERT INTO heb_vpl VALUES ("JH1_13","033_1_13","JON","1","13","13","ויחתרו האנשים להשיב אל היבשה ולא יכלו כי הים הולך וסער עליהם׃ ");
INSERT INTO heb_vpl VALUES ("JH1_14","033_1_14","JON","1","14","14","ויקראו אל יהוה ויאמרו אנה יהוה אל נא נאבדה בנפש האיש הזה ואל תתן עלינו דם נקיא כי אתה יהוה כאשר חפצת עשית׃ ");
INSERT INTO heb_vpl VALUES ("JH1_15","033_1_15","JON","1","15","15","וישאו את יונה ויטלהו אל הים ויעמד הים מזעפו׃ ");
INSERT INTO heb_vpl VALUES ("JH1_16","033_1_16","JON","1","16","16","וייראו האנשים יראה גדולה את יהוה ויזבחו זבח ליהוה וידרו נדרים׃ ");
INSERT INTO heb_vpl VALUES ("JH1_17","033_1_17","JON","1","17","17","וימן יהוה דג גדול לבלע את יונה ויהי יונה במעי הדג שלשה ימים ושלשה לילות׃ ");
INSERT INTO heb_vpl VALUES ("JH2_1","033_2_1","JON","2","1","1","ויתפלל יונה אל יהוה אלהיו ממעי הדגה׃ ");
INSERT INTO heb_vpl VALUES ("JH2_2","033_2_2","JON","2","2","2","ויאמר קראתי מצרה לי אל יהוה ויענני מבטן שאול שועתי שמעת קולי׃ ");
INSERT INTO heb_vpl VALUES ("JH2_3","033_2_3","JON","2","3","3","ותשליכני מצולה בלבב ימים ונהר יסבבני כל משבריך וגליך עלי עברו׃ ");
INSERT INTO heb_vpl VALUES ("JH2_4","033_2_4","JON","2","4","4","ואני אמרתי נגרשתי מנגד עיניך אך אוסיף להביט אל היכל קדשך׃ ");
INSERT INTO heb_vpl VALUES ("JH2_5","033_2_5","JON","2","5","5","אפפוני מים עד נפש תהום יסבבני סוף חבוש לראשי׃ ");
INSERT INTO heb_vpl VALUES ("JH2_6","033_2_6","JON","2","6","6","לקצבי הרים ירדתי הארץ ברחיה בעדי לעולם ותעל משחת חיי יהוה אלהי׃ ");
INSERT INTO heb_vpl VALUES ("JH2_7","033_2_7","JON","2","7","7","בהתעטף עלי נפשי את יהוה זכרתי ותבוא אליך תפלתי אל היכל קדשך׃ ");
INSERT INTO heb_vpl VALUES ("JH2_8","033_2_8","JON","2","8","8","משמרים הבלי שוא חסדם יעזבו׃ ");
INSERT INTO heb_vpl VALUES ("JH2_9","033_2_9","JON","2","9","9","ואני בקול תודה אזבחה לך אשר נדרתי אשלמה ישועתה ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("JH2_10","033_2_10","JON","2","10","10","ויאמר יהוה לדג ויקא את יונה אל היבשה׃ ");
INSERT INTO heb_vpl VALUES ("JH3_1","033_3_1","JON","3","1","1","ויהי דבר יהוה אל יונה שנית לאמר׃ ");
INSERT INTO heb_vpl VALUES ("JH3_2","033_3_2","JON","3","2","2","קום לך אל נינוה העיר הגדולה וקרא אליה את הקריאה אשר אנכי דבר אליך׃ ");
INSERT INTO heb_vpl VALUES ("JH3_3","033_3_3","JON","3","3","3","ויקם יונה וילך אל נינוה כדבר יהוה ונינוה היתה עיר גדולה לאלהים מהלך שלשת ימים׃ ");
INSERT INTO heb_vpl VALUES ("JH3_4","033_3_4","JON","3","4","4","ויחל יונה לבוא בעיר מהלך יום אחד ויקרא ויאמר עוד ארבעים יום ונינוה נהפכת׃ ");
INSERT INTO heb_vpl VALUES ("JH3_5","033_3_5","JON","3","5","5","ויאמינו אנשי נינוה באלהים ויקראו צום וילבשו שקים מגדולם ועד קטנם׃ ");
INSERT INTO heb_vpl VALUES ("JH3_6","033_3_6","JON","3","6","6","ויגע הדבר אל מלך נינוה ויקם מכסאו ויעבר אדרתו מעליו ויכס שק וישב על האפר׃ ");
INSERT INTO heb_vpl VALUES ("JH3_7","033_3_7","JON","3","7","7","ויזעק ויאמר בנינוה מטעם המלך וגדליו לאמר האדם והבהמה הבקר והצאן אל יטעמו מאומה אל ירעו ומים אל ישתו׃ ");
INSERT INTO heb_vpl VALUES ("JH3_8","033_3_8","JON","3","8","8","ויתכסו שקים האדם והבהמה ויקראו אל אלהים בחזקה וישבו איש מדרכו הרעה ומן החמס אשר בכפיהם׃ ");
INSERT INTO heb_vpl VALUES ("JH3_9","033_3_9","JON","3","9","9","מי יודע ישוב ונחם האלהים ושב מחרון אפו ולא נאבד׃ ");
INSERT INTO heb_vpl VALUES ("JH3_10","033_3_10","JON","3","10","10","וירא האלהים את מעשיהם כי שבו מדרכם הרעה וינחם האלהים על הרעה אשר דבר לעשות להם ולא עשה׃ ");
INSERT INTO heb_vpl VALUES ("JH4_1","033_4_1","JON","4","1","1","וירע אל יונה רעה גדולה ויחר לו׃ ");
INSERT INTO heb_vpl VALUES ("JH4_2","033_4_2","JON","4","2","2","ויתפלל אל יהוה ויאמר אנה יהוה הלוא זה דברי עד היותי על אדמתי על כן קדמתי לברח תרשישה כי ידעתי כי אתה אל חנון ורחום ארך אפים ורב חסד ונחם על הרעה׃ ");
INSERT INTO heb_vpl VALUES ("JH4_3","033_4_3","JON","4","3","3","ועתה יהוה קח נא את נפשי ממני כי טוב מותי מחיי׃ ");
INSERT INTO heb_vpl VALUES ("JH4_4","033_4_4","JON","4","4","4","ויאמר יהוה ההיטב חרה לך׃ ");
INSERT INTO heb_vpl VALUES ("JH4_5","033_4_5","JON","4","5","5","ויצא יונה מן העיר וישב מקדם לעיר ויעש לו שם סכה וישב תחתיה בצל עד אשר יראה מה יהיה בעיר׃ ");
INSERT INTO heb_vpl VALUES ("JH4_6","033_4_6","JON","4","6","6","וימן יהוה אלהים קיקיון ויעל מעל ליונה להיות צל על ראשו להציל לו מרעתו וישמח יונה על הקיקיון שמחה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("JH4_7","033_4_7","JON","4","7","7","וימן האלהים תולעת בעלות השחר למחרת ותך את הקיקיון וייבש׃ ");
INSERT INTO heb_vpl VALUES ("JH4_8","033_4_8","JON","4","8","8","ויהי כזרח השמש וימן אלהים רוח קדים חרישית ותך השמש על ראש יונה ויתעלף וישאל את נפשו למות ויאמר טוב מותי מחיי׃ ");
INSERT INTO heb_vpl VALUES ("JH4_9","033_4_9","JON","4","9","9","ויאמר אלהים אל יונה ההיטב חרה לך על הקיקיון ויאמר היטב חרה לי עד מות׃ ");
INSERT INTO heb_vpl VALUES ("JH4_10","033_4_10","JON","4","10","10","ויאמר יהוה אתה חסת על הקיקיון אשר לא עמלת בו ולא גדלתו שבן לילה היה ובן לילה אבד׃ ");
INSERT INTO heb_vpl VALUES ("JH4_11","033_4_11","JON","4","11","11","ואני לא אחוס על נינוה העיר הגדולה אשר יש בה הרבה משתים עשרה רבו אדם אשר לא ידע בין ימינו לשמאלו ובהמה רבה׃ ");
INSERT INTO heb_vpl VALUES ("MC1_1","034_1_1","MIC","1","1","1","דבר יהוה אשר היה אל מיכה המרשתי בימי יותם אחז יחזקיה מלכי יהודה אשר חזה על שמרון וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("MC1_2","034_1_2","MIC","1","2","2","שמעו עמים כלם הקשיבי ארץ ומלאה ויהי אדני יהוה בכם לעד אדני מהיכל קדשו׃ ");
INSERT INTO heb_vpl VALUES ("MC1_3","034_1_3","MIC","1","3","3","כי הנה יהוה יצא ממקומו וירד ודרך על במותי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("MC1_4","034_1_4","MIC","1","4","4","ונמסו ההרים תחתיו והעמקים יתבקעו כדונג מפני האש כמים מגרים במורד׃ ");
INSERT INTO heb_vpl VALUES ("MC1_5","034_1_5","MIC","1","5","5","בפשע יעקב כל זאת ובחטאות בית ישראל מי פשע יעקב הלוא שמרון ומי במות יהודה הלוא ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("MC1_6","034_1_6","MIC","1","6","6","ושמתי שמרון לעי השדה למטעי כרם והגרתי לגי אבניה ויסדיה אגלה׃ ");
INSERT INTO heb_vpl VALUES ("MC1_7","034_1_7","MIC","1","7","7","וכל פסיליה יכתו וכל אתנניה ישרפו באש וכל עצביה אשים שממה כי מאתנן זונה קבצה ועד אתנן זונה ישובו׃ ");
INSERT INTO heb_vpl VALUES ("MC1_8","034_1_8","MIC","1","8","8","על זאת אספדה ואילילה אילכה שילל וערום אעשה מספד כתנים ואבל כבנות יענה׃ ");
INSERT INTO heb_vpl VALUES ("MC1_9","034_1_9","MIC","1","9","9","כי אנושה מכותיה כי באה עד יהודה נגע עד שער עמי עד ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("MC1_10","034_1_10","MIC","1","10","10","בגת אל תגידו בכו אל תבכו בבית לעפרה עפר התפלשתי׃ ");
INSERT INTO heb_vpl VALUES ("MC1_11","034_1_11","MIC","1","11","11","עברי לכם יושבת שפיר עריה בשת לא יצאה יושבת צאנן מספד בית האצל יקח מכם עמדתו׃ ");
INSERT INTO heb_vpl VALUES ("MC1_12","034_1_12","MIC","1","12","12","כי חלה לטוב יושבת מרות כי ירד רע מאת יהוה לשער ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("MC1_13","034_1_13","MIC","1","13","13","רתם המרכבה לרכש יושבת לכיש ראשית חטאת היא לבת ציון כי בך נמצאו פשעי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MC1_14","034_1_14","MIC","1","14","14","לכן תתני שלוחים על מורשת גת בתי אכזיב לאכזב למלכי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MC1_15","034_1_15","MIC","1","15","15","עד הירש אבי לך יושבת מרשה עד עדלם יבוא כבוד ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MC1_16","034_1_16","MIC","1","16","16","קרחי וגזי על בני תענוגיך הרחבי קרחתך כנשר כי גלו ממך׃ ");
INSERT INTO heb_vpl VALUES ("MC2_1","034_2_1","MIC","2","1","1","הוי חשבי און ופעלי רע על משכבותם באור הבקר יעשוה כי יש לאל ידם׃ ");
INSERT INTO heb_vpl VALUES ("MC2_2","034_2_2","MIC","2","2","2","וחמדו שדות וגזלו ובתים ונשאו ועשקו גבר וביתו ואיש ונחלתו׃ ");
INSERT INTO heb_vpl VALUES ("MC2_3","034_2_3","MIC","2","3","3","לכן כה אמר יהוה הנני חשב על המשפחה הזאת רעה אשר לא תמישו משם צוארתיכם ולא תלכו רומה כי עת רעה היא׃ ");
INSERT INTO heb_vpl VALUES ("MC2_4","034_2_4","MIC","2","4","4","ביום ההוא ישא עליכם משל ונהה נהי נהיה אמר שדוד נשדנו חלק עמי ימיר איך ימיש לי לשובב שדינו יחלק׃ ");
INSERT INTO heb_vpl VALUES ("MC2_5","034_2_5","MIC","2","5","5","לכן לא יהיה לך משליך חבל בגורל בקהל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("MC2_6","034_2_6","MIC","2","6","6","אל תטפו יטיפון לא יטפו לאלה לא יסג כלמות׃ ");
INSERT INTO heb_vpl VALUES ("MC2_7","034_2_7","MIC","2","7","7","האמור בית יעקב הקצר רוח יהוה אם אלה מעלליו הלוא דברי ייטיבו עם הישר הולך׃ ");
INSERT INTO heb_vpl VALUES ("MC2_8","034_2_8","MIC","2","8","8","ואתמול עמי לאויב יקומם ממול שלמה אדר תפשטון מעברים בטח שובי מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("MC2_9","034_2_9","MIC","2","9","9","נשי עמי תגרשון מבית תענגיה מעל עלליה תקחו הדרי לעולם׃ ");
INSERT INTO heb_vpl VALUES ("MC2_10","034_2_10","MIC","2","10","10","קומו ולכו כי לא זאת המנוחה בעבור טמאה תחבל וחבל נמרץ׃ ");
INSERT INTO heb_vpl VALUES ("MC2_11","034_2_11","MIC","2","11","11","לו איש הלך רוח ושקר כזב אטף לך ליין ולשכר והיה מטיף העם הזה׃ ");
INSERT INTO heb_vpl VALUES ("MC2_12","034_2_12","MIC","2","12","12","אסף אאסף יעקב כלך קבץ אקבץ שארית ישראל יחד אשימנו כצאן בצרה כעדר בתוך הדברו תהימנה מאדם׃ ");
INSERT INTO heb_vpl VALUES ("MC2_13","034_2_13","MIC","2","13","13","עלה הפרץ לפניהם פרצו ויעברו שער ויצאו בו ויעבר מלכם לפניהם ויהוה בראשם׃ ");
INSERT INTO heb_vpl VALUES ("MC3_1","034_3_1","MIC","3","1","1","ואמר שמעו נא ראשי יעקב וקציני בית ישראל הלוא לכם לדעת את המשפט׃ ");
INSERT INTO heb_vpl VALUES ("MC3_2","034_3_2","MIC","3","2","2","שנאי טוב ואהבי רעה גזלי עורם מעליהם ושארם מעל עצמותם׃ ");
INSERT INTO heb_vpl VALUES ("MC3_3","034_3_3","MIC","3","3","3","ואשר אכלו שאר עמי ועורם מעליהם הפשיטו ואת עצמתיהם פצחו ופרשו כאשר בסיר וכבשר בתוך קלחת׃ ");
INSERT INTO heb_vpl VALUES ("MC3_4","034_3_4","MIC","3","4","4","אז יזעקו אל יהוה ולא יענה אותם ויסתר פניו מהם בעת ההיא כאשר הרעו מעלליהם׃ ");
INSERT INTO heb_vpl VALUES ("MC3_5","034_3_5","MIC","3","5","5","כה אמר יהוה על הנביאים המתעים את עמי הנשכים בשניהם וקראו שלום ואשר לא יתן על פיהם וקדשו עליו מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("MC3_6","034_3_6","MIC","3","6","6","לכן לילה לכם מחזון וחשכה לכם מקסם ובאה השמש על הנביאים וקדר עליהם היום׃ ");
INSERT INTO heb_vpl VALUES ("MC3_7","034_3_7","MIC","3","7","7","ובשו החזים וחפרו הקסמים ועטו על שפם כלם כי אין מענה אלהים׃ ");
INSERT INTO heb_vpl VALUES ("MC3_8","034_3_8","MIC","3","8","8","ואולם אנכי מלאתי כח את רוח יהוה ומשפט וגבורה להגיד ליעקב פשעו ולישראל חטאתו׃ ");
INSERT INTO heb_vpl VALUES ("MC3_9","034_3_9","MIC","3","9","9","שמעו נא זאת ראשי בית יעקב וקציני בית ישראל המתעבים משפט ואת כל הישרה יעקשו׃ ");
INSERT INTO heb_vpl VALUES ("MC3_10","034_3_10","MIC","3","10","10","בנה ציון בדמים וירושלם בעולה׃ ");
INSERT INTO heb_vpl VALUES ("MC3_11","034_3_11","MIC","3","11","11","ראשיה בשחד ישפטו וכהניה במחיר יורו ונביאיה בכסף יקסמו ועל יהוה ישענו לאמר הלוא יהוה בקרבנו לא תבוא עלינו רעה׃ ");
INSERT INTO heb_vpl VALUES ("MC3_12","034_3_12","MIC","3","12","12","לכן בגללכם ציון שדה תחרש וירושלם עיין תהיה והר הבית לבמות יער׃ ");
INSERT INTO heb_vpl VALUES ("MC4_1","034_4_1","MIC","4","1","1","והיה באחרית הימים יהיה הר בית יהוה נכון בראש ההרים ונשא הוא מגבעות ונהרו עליו עמים׃ ");
INSERT INTO heb_vpl VALUES ("MC4_2","034_4_2","MIC","4","2","2","והלכו גוים רבים ואמרו לכו ונעלה אל הר יהוה ואל בית אלהי יעקב ויורנו מדרכיו ונלכה בארחתיו כי מציון תצא תורה ודבר יהוה מירושלם׃ ");
INSERT INTO heb_vpl VALUES ("MC4_3","034_4_3","MIC","4","3","3","ושפט בין עמים רבים והוכיח לגוים עצמים עד רחוק וכתתו חרבתיהם לאתים וחניתתיהם למזמרות לא ישאו גוי אל גוי חרב ולא ילמדון עוד מלחמה׃ ");
INSERT INTO heb_vpl VALUES ("MC4_4","034_4_4","MIC","4","4","4","וישבו איש תחת גפנו ותחת תאנתו ואין מחריד כי פי יהוה צבאות דבר׃ ");
INSERT INTO heb_vpl VALUES ("MC4_5","034_4_5","MIC","4","5","5","כי כל העמים ילכו איש בשם אלהיו ואנחנו נלך בשם יהוה אלהינו לעולם ועד׃ ");
INSERT INTO heb_vpl VALUES ("MC4_6","034_4_6","MIC","4","6","6","ביום ההוא נאם יהוה אספה הצלעה והנדחה אקבצה ואשר הרעתי׃ ");
INSERT INTO heb_vpl VALUES ("MC4_7","034_4_7","MIC","4","7","7","ושמתי את הצלעה לשארית והנהלאה לגוי עצום ומלך יהוה עליהם בהר ציון מעתה ועד עולם׃ ");
INSERT INTO heb_vpl VALUES ("MC4_8","034_4_8","MIC","4","8","8","ואתה מגדל עדר עפל בת ציון עדיך תאתה ובאה הממשלה הראשנה ממלכת לבת ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("MC4_9","034_4_9","MIC","4","9","9","עתה למה תריעי רע המלך אין בך אם יועצך אבד כי החזיקך חיל כיולדה׃ ");
INSERT INTO heb_vpl VALUES ("MC4_10","034_4_10","MIC","4","10","10","חולי וגחי בת ציון כיולדה כי עתה תצאי מקריה ושכנת בשדה ובאת עד בבל שם תנצלי שם יגאלך יהוה מכף איביך׃ ");
