INSERT INTO heb_vpl VALUES ("MC5_5","034_5_5","MIC","5","5","5","והיה זה שלום אשור כי יבוא בארצנו וכי ידרך בארמנתינו והקמנו עליו שבעה רעים ושמנה נסיכי אדם׃ ");
