INSERT INTO heb_vpl VALUES ("ZP1_13","037_1_13","ZEP","1","13","13","והיה חילם למשסה ובתיהם לשממה ובנו בתים ולא ישבו ונטעו כרמים ולא ישתו את יינם׃ ");
