INSERT INTO heb_vpl VALUES ("ZP1_18","037_1_18","ZEP","1","18","18","גם כספם גם זהבם לא יוכל להצילם ביום עברת יהוה ובאש קנאתו תאכל כל הארץ כי כלה אך נבהלה יעשה את כל ישבי הארץ׃ ");
