INSERT INTO heb_vpl VALUES ("ZP3_20","037_3_20","ZEP","3","20","20","בעת ההיא אביא אתכם ובעת קבצי אתכם כי אתן אתכם לשם ולתהלה בכל עמי הארץ בשובי את שבותיכם לעיניכם אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HG1_1","038_1_1","HAG","1","1","1","בשנת שתים לדריוש המלך בחדש הששי ביום אחד לחדש היה דבר יהוה ביד חגי הנביא אל זרבבל בן שאלתיאל פחת יהודה ואל יהושע בן יהוצדק הכהן הגדול לאמר׃ ");
INSERT INTO heb_vpl VALUES ("HG1_2","038_1_2","HAG","1","2","2","כה אמר יהוה צבאות לאמר העם הזה אמרו לא עת בא עת בית יהוה להבנות׃ ");
