INSERT INTO heb_vpl VALUES ("HG2_23","038_2_23","HAG","2","23","23","ביום ההוא נאם יהוה צבאות אקחך זרבבל בן שאלתיאל עבדי נאם יהוה ושמתיך כחותם כי בך בחרתי נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_1","039_1_1","ZEC","1","1","1","בחדש השמיני בשנת שתים לדריוש היה דבר יהוה אל זכריה בן ברכיה בן עדו הנביא לאמר׃ ");
