INSERT INTO heb_vpl VALUES ("ZC1_6","039_1_6","ZEC","1","6","6","אך דברי וחקי אשר צויתי את עבדי הנביאים הלוא השיגו אבתיכם וישובו ויאמרו כאשר זמם יהוה צבאות לעשות לנו כדרכינו וכמעללינו כן עשה אתנו׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_7","039_1_7","ZEC","1","7","7","ביום עשרים וארבעה לעשתי עשר חדש הוא חדש שבט בשנת שתים לדריוש היה דבר יהוה אל זכריה בן ברכיהו בן עדוא הנביא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_8","039_1_8","ZEC","1","8","8","ראיתי הלילה והנה איש רכב על סוס אדם והוא עמד בין ההדסים אשר במצלה ואחריו סוסים אדמים שרקים ולבנים׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_9","039_1_9","ZEC","1","9","9","ואמר מה אלה אדני ויאמר אלי המלאך הדבר בי אני אראך מה המה אלה׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_10","039_1_10","ZEC","1","10","10","ויען האיש העמד בין ההדסים ויאמר אלה אשר שלח יהוה להתהלך בארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_11","039_1_11","ZEC","1","11","11","ויענו את מלאך יהוה העמד בין ההדסים ויאמרו התהלכנו בארץ והנה כל הארץ ישבת ושקטת׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_12","039_1_12","ZEC","1","12","12","ויען מלאך יהוה ויאמר יהוה צבאות עד מתי אתה לא תרחם את ירושלם ואת ערי יהודה אשר זעמתה זה שבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_13","039_1_13","ZEC","1","13","13","ויען יהוה את המלאך הדבר בי דברים טובים דברים נחמים׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_14","039_1_14","ZEC","1","14","14","ויאמר אלי המלאך הדבר בי קרא לאמר כה אמר יהוה צבאות קנאתי לירושלם ולציון קנאה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_15","039_1_15","ZEC","1","15","15","וקצף גדול אני קצף על הגוים השאננים אשר אני קצפתי מעט והמה עזרו לרעה׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_16","039_1_16","ZEC","1","16","16","לכן כה אמר יהוה שבתי לירושלם ברחמים ביתי יבנה בה נאם יהוה צבאות וקוה ינטה על ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_17","039_1_17","ZEC","1","17","17","עוד קרא לאמר כה אמר יהוה צבאות עוד תפוצינה ערי מטוב ונחם יהוה עוד את ציון ובחר עוד בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_18","039_1_18","ZEC","1","18","18","ואשא את עיני וארא והנה ארבע קרנות׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_19","039_1_19","ZEC","1","19","19","ואמר אל המלאך הדבר בי מה אלה ויאמר אלי אלה הקרנות אשר זרו את יהודה את ישראל וירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_20","039_1_20","ZEC","1","20","20","ויראני יהוה ארבעה חרשים׃ ");
INSERT INTO heb_vpl VALUES ("ZC1_21","039_1_21","ZEC","1","21","21","ואמר מה אלה באים לעשות ויאמר לאמר אלה הקרנות אשר זרו את יהודה כפי איש לא נשא ראשו ויבאו אלה להחריד אתם לידות את קרנות הגוים הנשאים קרן אל ארץ יהודה לזרותה׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_1","039_2_1","ZEC","2","1","1","ואשא עיני וארא והנה איש ובידו חבל מדה׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_2","039_2_2","ZEC","2","2","2","ואמר אנה אתה הלך ויאמר אלי למד את ירושלם לראות כמה רחבה וכמה ארכה׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_3","039_2_3","ZEC","2","3","3","והנה המלאך הדבר בי יצא ומלאך אחר יצא לקראתו׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_4","039_2_4","ZEC","2","4","4","ויאמר אלו רץ דבר אל הנער הלז לאמר פרזות תשב ירושלם מרב אדם ובהמה בתוכה׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_5","039_2_5","ZEC","2","5","5","ואני אהיה לה נאם יהוה חומת אש סביב ולכבוד אהיה בתוכה׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_6","039_2_6","ZEC","2","6","6","הוי הוי ונסו מארץ צפון נאם יהוה כי כארבע רוחות השמים פרשתי אתכם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_7","039_2_7","ZEC","2","7","7","הוי ציון המלטי יושבת בת בבל׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_8","039_2_8","ZEC","2","8","8","כי כה אמר יהוה צבאות אחר כבוד שלחני אל הגוים השללים אתכם כי הנגע בכם נגע בבבת עינו׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_9","039_2_9","ZEC","2","9","9","כי הנני מניף את ידי עליהם והיו שלל לעבדיהם וידעתם כי יהוה צבאות שלחני׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_10","039_2_10","ZEC","2","10","10","רני ושמחי בת ציון כי הנני בא ושכנתי בתוכך נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_11","039_2_11","ZEC","2","11","11","ונלוו גוים רבים אל יהוה ביום ההוא והיו לי לעם ושכנתי בתוכך וידעת כי יהוה צבאות שלחני אליך׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_12","039_2_12","ZEC","2","12","12","ונחל יהוה את יהודה חלקו על אדמת הקדש ובחר עוד בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ZC2_13","039_2_13","ZEC","2","13","13","הס כל בשר מפני יהוה כי נעור ממעון קדשו׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_1","039_3_1","ZEC","3","1","1","ויראני את יהושע הכהן הגדול עמד לפני מלאך יהוה והשטן עמד על ימינו לשטנו׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_2","039_3_2","ZEC","3","2","2","ויאמר יהוה אל השטן יגער יהוה בך השטן ויגער יהוה בך הבחר בירושלם הלוא זה אוד מצל מאש׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_3","039_3_3","ZEC","3","3","3","ויהושע היה לבש בגדים צואים ועמד לפני המלאך׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_4","039_3_4","ZEC","3","4","4","ויען ויאמר אל העמדים לפניו לאמר הסירו הבגדים הצאים מעליו ויאמר אליו ראה העברתי מעליך עונך והלבש אתך מחלצות׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_5","039_3_5","ZEC","3","5","5","ואמר ישימו צניף טהור על ראשו וישימו הצניף הטהור על ראשו וילבשהו בגדים ומלאך יהוה עמד׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_6","039_3_6","ZEC","3","6","6","ויעד מלאך יהוה ביהושע לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_7","039_3_7","ZEC","3","7","7","כה אמר יהוה צבאות אם בדרכי תלך ואם את משמרתי תשמר וגם אתה תדין את ביתי וגם תשמר את חצרי ונתתי לך מהלכים בין העמדים האלה׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_8","039_3_8","ZEC","3","8","8","שמע נא יהושע הכהן הגדול אתה ורעיך הישבים לפניך כי אנשי מופת המה כי הנני מביא את עבדי צמח׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_9","039_3_9","ZEC","3","9","9","כי הנה האבן אשר נתתי לפני יהושע על אבן אחת שבעה עינים הנני מפתח פתחה נאם יהוה צבאות ומשתי את עון הארץ ההיא ביום אחד׃ ");
INSERT INTO heb_vpl VALUES ("ZC3_10","039_3_10","ZEC","3","10","10","ביום ההוא נאם יהוה צבאות תקראו איש לרעהו אל תחת גפן ואל תחת תאנה׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_1","039_4_1","ZEC","4","1","1","וישב המלאך הדבר בי ויעירני כאיש אשר יעור משנתו׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_2","039_4_2","ZEC","4","2","2","ויאמר אלי מה אתה ראה ויאמר ראיתי והנה מנורת זהב כלה וגלה על ראשה ושבעה נרתיה עליה שבעה ושבעה מוצקות לנרות אשר על ראשה׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_3","039_4_3","ZEC","4","3","3","ושנים זיתים עליה אחד מימין הגלה ואחד על שמאלה׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_4","039_4_4","ZEC","4","4","4","ואען ואמר אל המלאך הדבר בי לאמר מה אלה אדני׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_5","039_4_5","ZEC","4","5","5","ויען המלאך הדבר בי ויאמר אלי הלוא ידעת מה המה אלה ואמר לא אדני׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_6","039_4_6","ZEC","4","6","6","ויען ויאמר אלי לאמר זה דבר יהוה אל זרבבל לאמר לא בחיל ולא בכח כי אם ברוחי אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_7","039_4_7","ZEC","4","7","7","מי אתה הר הגדול לפני זרבבל למישר והוציא את האבן הראשה תשאות חן חן לה׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_8","039_4_8","ZEC","4","8","8","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_9","039_4_9","ZEC","4","9","9","ידי זרבבל יסדו הבית הזה וידיו תבצענה וידעת כי יהוה צבאות שלחני אלכם׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_10","039_4_10","ZEC","4","10","10","כי מי בז ליום קטנות ושמחו וראו את האבן הבדיל ביד זרבבל שבעה אלה עיני יהוה המה משוטטים בכל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_11","039_4_11","ZEC","4","11","11","ואען ואמר אליו מה שני הזיתים האלה על ימין המנורה ועל שמאולה׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_12","039_4_12","ZEC","4","12","12","ואען שנית ואמר אליו מה שתי שבלי הזיתים אשר ביד שני צנתרות הזהב המריקים מעליהם הזהב׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_13","039_4_13","ZEC","4","13","13","ויאמר אלי לאמר הלוא ידעת מה אלה ואמר לא אדני׃ ");
INSERT INTO heb_vpl VALUES ("ZC4_14","039_4_14","ZEC","4","14","14","ויאמר אלה שני בני היצהר העמדים על אדון כל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_1","039_5_1","ZEC","5","1","1","ואשוב ואשא עיני ואראה והנה מגלה עפה׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_2","039_5_2","ZEC","5","2","2","ויאמר אלי מה אתה ראה ואמר אני ראה מגלה עפה ארכה עשרים באמה ורחבה עשר באמה׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_3","039_5_3","ZEC","5","3","3","ויאמר אלי זאת האלה היוצאת על פני כל הארץ כי כל הגנב מזה כמוה נקה וכל הנשבע מזה כמוה נקה׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_4","039_5_4","ZEC","5","4","4","הוצאתיה נאם יהוה צבאות ובאה אל בית הגנב ואל בית הנשבע בשמי לשקר ולנה בתוך ביתו וכלתו ואת עציו ואת אבניו׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_5","039_5_5","ZEC","5","5","5","ויצא המלאך הדבר בי ויאמר אלי שא נא עיניך וראה מה היוצאת הזאת׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_6","039_5_6","ZEC","5","6","6","ואמר מה היא ויאמר זאת האיפה היוצאת ויאמר זאת עינם בכל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_7","039_5_7","ZEC","5","7","7","והנה ככר עפרת נשאת וזאת אשה אחת יושבת בתוך האיפה׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_8","039_5_8","ZEC","5","8","8","ויאמר זאת הרשעה וישלך אתה אל תוך האיפה וישלך את אבן העפרת אל פיה׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_9","039_5_9","ZEC","5","9","9","ואשא עיני וארא והנה שתים נשים יוצאות ורוח בכנפיהם ולהנה כנפים ככנפי החסידה ותשאנה את האיפה בין הארץ ובין השמים׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_10","039_5_10","ZEC","5","10","10","ואמר אל המלאך הדבר בי אנה המה מולכות את האיפה׃ ");
INSERT INTO heb_vpl VALUES ("ZC5_11","039_5_11","ZEC","5","11","11","ויאמר אלי לבנות לה בית בארץ שנער והוכן והניחה שם על מכנתה׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_1","039_6_1","ZEC","6","1","1","ואשב ואשא עיני ואראה והנה ארבע מרכבות יצאות מבין שני ההרים וההרים הרי נחשת׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_2","039_6_2","ZEC","6","2","2","במרכבה הראשנה סוסים אדמים ובמרכבה השנית סוסים שחרים׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_3","039_6_3","ZEC","6","3","3","ובמרכבה השלשית סוסים לבנים ובמרכבה הרבעית סוסים ברדים אמצים׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_4","039_6_4","ZEC","6","4","4","ואען ואמר אל המלאך הדבר בי מה אלה אדני׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_5","039_6_5","ZEC","6","5","5","ויען המלאך ויאמר אלי אלה ארבע רחות השמים יוצאות מהתיצב על אדון כל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_6","039_6_6","ZEC","6","6","6","אשר בה הסוסים השחרים יצאים אל ארץ צפון והלבנים יצאו אל אחריהם והברדים יצאו אל ארץ התימן׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_7","039_6_7","ZEC","6","7","7","והאמצים יצאו ויבקשו ללכת להתהלך בארץ ויאמר לכו התהלכו בארץ ותתהלכנה בארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_8","039_6_8","ZEC","6","8","8","ויזעק אתי וידבר אלי לאמר ראה היוצאים אל ארץ צפון הניחו את רוחי בארץ צפון׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_9","039_6_9","ZEC","6","9","9","ויהי דבר יהוה אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_10","039_6_10","ZEC","6","10","10","לקוח מאת הגולה מחלדי ומאת טוביה ומאת ידעיה ובאת אתה ביום ההוא ובאת בית יאשיה בן צפניה אשר באו מבבל׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_11","039_6_11","ZEC","6","11","11","ולקחת כסף וזהב ועשית עטרות ושמת בראש יהושע בן יהוצדק הכהן הגדול׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_12","039_6_12","ZEC","6","12","12","ואמרת אליו לאמר כה אמר יהוה צבאות לאמר הנה איש צמח שמו ומתחתיו יצמח ובנה את היכל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_13","039_6_13","ZEC","6","13","13","והוא יבנה את היכל יהוה והוא ישא הוד וישב ומשל על כסאו והיה כהן על כסאו ועצת שלום תהיה בין שניהם׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_14","039_6_14","ZEC","6","14","14","והעטרת תהיה לחלם ולטוביה ולידעיה ולחן בן צפניה לזכרון בהיכל יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC6_15","039_6_15","ZEC","6","15","15","ורחוקים יבאו ובנו בהיכל יהוה וידעתם כי יהוה צבאות שלחני אליכם והיה אם שמוע תשמעון בקול יהוה אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_1","039_7_1","ZEC","7","1","1","ויהי בשנת ארבע לדריוש המלך היה דבר יהוה אל זכריה בארבעה לחדש התשעי בכסלו׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_2","039_7_2","ZEC","7","2","2","וישלח בית אל שר אצר ורגם מלך ואנשיו לחלות את פני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_3","039_7_3","ZEC","7","3","3","לאמר אל הכהנים אשר לבית יהוה צבאות ואל הנביאים לאמר האבכה בחדש החמשי הנזר כאשר עשיתי זה כמה שנים׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_4","039_7_4","ZEC","7","4","4","ויהי דבר יהוה צבאות אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_5","039_7_5","ZEC","7","5","5","אמר אל כל עם הארץ ואל הכהנים לאמר כי צמתם וספוד בחמישי ובשביעי וזה שבעים שנה הצום צמתני אני׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_6","039_7_6","ZEC","7","6","6","וכי תאכלו וכי תשתו הלוא אתם האכלים ואתם השתים׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_7","039_7_7","ZEC","7","7","7","הלוא את הדברים אשר קרא יהוה ביד הנביאים הראשנים בהיות ירושלם ישבת ושלוה ועריה סביבתיה והנגב והשפלה ישב׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_8","039_7_8","ZEC","7","8","8","ויהי דבר יהוה אל זכריה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_9","039_7_9","ZEC","7","9","9","כה אמר יהוה צבאות לאמר משפט אמת שפטו וחסד ורחמים עשו איש את אחיו׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_10","039_7_10","ZEC","7","10","10","ואלמנה ויתום גר ועני אל תעשקו ורעת איש אחיו אל תחשבו בלבבכם׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_11","039_7_11","ZEC","7","11","11","וימאנו להקשיב ויתנו כתף סררת ואזניהם הכבידו משמוע׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_12","039_7_12","ZEC","7","12","12","ולבם שמו שמיר משמוע את התורה ואת הדברים אשר שלח יהוה צבאות ברוחו ביד הנביאים הראשנים ויהי קצף גדול מאת יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_13","039_7_13","ZEC","7","13","13","ויהי כאשר קרא ולא שמעו כן יקראו ולא אשמע אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ZC7_14","039_7_14","ZEC","7","14","14","ואסערם על כל הגוים אשר לא ידעום והארץ נשמה אחריהם מעבר ומשב וישימו ארץ חמדה לשמה׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_1","039_8_1","ZEC","8","1","1","ויהי דבר יהוה צבאות לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_2","039_8_2","ZEC","8","2","2","כה אמר יהוה צבאות קנאתי לציון קנאה גדולה וחמה גדולה קנאתי לה׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_3","039_8_3","ZEC","8","3","3","כה אמר יהוה שבתי אל ציון ושכנתי בתוך ירושלם ונקראה ירושלם עיר האמת והר יהוה צבאות הר הקדש׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_4","039_8_4","ZEC","8","4","4","כה אמר יהוה צבאות עד ישבו זקנים וזקנות ברחבות ירושלם ואיש משענתו בידו מרב ימים׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_5","039_8_5","ZEC","8","5","5","ורחבות העיר ימלאו ילדים וילדות משחקים ברחבתיה׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_6","039_8_6","ZEC","8","6","6","כה אמר יהוה צבאות כי יפלא בעיני שארית העם הזה בימים ההם גם בעיני יפלא נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_7","039_8_7","ZEC","8","7","7","כה אמר יהוה צבאות הנני מושיע את עמי מארץ מזרח ומארץ מבוא השמש׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_8","039_8_8","ZEC","8","8","8","והבאתי אתם ושכנו בתוך ירושלם והיו לי לעם ואני אהיה להם לאלהים באמת ובצדקה׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_9","039_8_9","ZEC","8","9","9","כה אמר יהוה צבאות תחזקנה ידיכם השמעים בימים האלה את הדברים האלה מפי הנביאים אשר ביום יסד בית יהוה צבאות ההיכל להבנות׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_10","039_8_10","ZEC","8","10","10","כי לפני הימים ההם שכר האדם לא נהיה ושכר הבהמה איננה וליוצא ולבא אין שלום מן הצר ואשלח את כל האדם איש ברעהו׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_11","039_8_11","ZEC","8","11","11","ועתה לא כימים הראשנים אני לשארית העם הזה נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_12","039_8_12","ZEC","8","12","12","כי זרע השלום הגפן תתן פריה והארץ תתן את יבולה והשמים יתנו טלם והנחלתי את שארית העם הזה את כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_13","039_8_13","ZEC","8","13","13","והיה כאשר הייתם קללה בגוים בית יהודה ובית ישראל כן אושיע אתכם והייתם ברכה אל תיראו תחזקנה ידיכם׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_14","039_8_14","ZEC","8","14","14","כי כה אמר יהוה צבאות כאשר זממתי להרע לכם בהקציף אבתיכם אתי אמר יהוה צבאות ולא נחמתי׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_15","039_8_15","ZEC","8","15","15","כן שבתי זממתי בימים האלה להיטיב את ירושלם ואת בית יהודה אל תיראו׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_16","039_8_16","ZEC","8","16","16","אלה הדברים אשר תעשו דברו אמת איש את רעהו אמת ומשפט שלום שפטו בשעריכם׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_17","039_8_17","ZEC","8","17","17","ואיש את רעת רעהו אל תחשבו בלבבכם ושבעת שקר אל תאהבו כי את כל אלה אשר שנאתי נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_18","039_8_18","ZEC","8","18","18","ויהי דבר יהוה צבאות אלי לאמר׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_19","039_8_19","ZEC","8","19","19","כה אמר יהוה צבאות צום הרביעי וצום החמישי וצום השביעי וצום העשירי יהיה לבית יהודה לששון ולשמחה ולמעדים טובים והאמת והשלום אהבו׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_20","039_8_20","ZEC","8","20","20","כה אמר יהוה צבאות עד אשר יבאו עמים וישבי ערים רבות׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_21","039_8_21","ZEC","8","21","21","והלכו ישבי אחת אל אחת לאמר נלכה הלוך לחלות את פני יהוה ולבקש את יהוה צבאות אלכה גם אני׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_22","039_8_22","ZEC","8","22","22","ובאו עמים רבים וגוים עצומים לבקש את יהוה צבאות בירושלם ולחלות את פני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC8_23","039_8_23","ZEC","8","23","23","כה אמר יהוה צבאות בימים ההמה אשר יחזיקו עשרה אנשים מכל לשנות הגוים והחזיקו בכנף איש יהודי לאמר נלכה עמכם כי שמענו אלהים עמכם׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_1","039_9_1","ZEC","9","1","1","משא דבר יהוה בארץ חדרך ודמשק מנחתו כי ליהוה עין אדם וכל שבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_2","039_9_2","ZEC","9","2","2","וגם חמת תגבל בה צר וצידון כי חכמה מאד׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_3","039_9_3","ZEC","9","3","3","ותבן צר מצור לה ותצבר כסף כעפר וחרוץ כטיט חוצות׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_4","039_9_4","ZEC","9","4","4","הנה אדני יורשנה והכה בים חילה והיא באש תאכל׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_5","039_9_5","ZEC","9","5","5","תרא אשקלון ותירא ועזה ותחיל מאד ועקרון כי הביש מבטה ואבד מלך מעזה ואשקלון לא תשב׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_6","039_9_6","ZEC","9","6","6","וישב ממזר באשדוד והכרתי גאון פלשתים׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_7","039_9_7","ZEC","9","7","7","והסרתי דמיו מפיו ושקציו מבין שניו ונשאר גם הוא לאלהינו והיה כאלף ביהודה ועקרון כיבוסי׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_8","039_9_8","ZEC","9","8","8","וחניתי לביתי מצבה מעבר ומשב ולא יעבר עליהם עוד נגש כי עתה ראיתי בעיני׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_9","039_9_9","ZEC","9","9","9","גילי מאד בת ציון הריעי בת ירושלם הנה מלכך יבוא לך צדיק ונושע הוא עני ורכב על חמור ועל עיר בן אתנות׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_10","039_9_10","ZEC","9","10","10","והכרתי רכב מאפרים וסוס מירושלם ונכרתה קשת מלחמה ודבר שלום לגוים ומשלו מים עד ים ומנהר עד אפסי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_11","039_9_11","ZEC","9","11","11","גם את בדם בריתך שלחתי אסיריך מבור אין מים בו׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_12","039_9_12","ZEC","9","12","12","שובו לבצרון אסירי התקוה גם היום מגיד משנה אשיב לך׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_13","039_9_13","ZEC","9","13","13","כי דרכתי לי יהודה קשת מלאתי אפרים ועוררתי בניך ציון על בניך יון ושמתיך כחרב גבור׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_14","039_9_14","ZEC","9","14","14","ויהוה עליהם יראה ויצא כברק חצו ואדני יהוה בשופר יתקע והלך בסערות תימן׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_15","039_9_15","ZEC","9","15","15","יהוה צבאות יגן עליהם ואכלו וכבשו אבני קלע ושתו המו כמו יין ומלאו כמזרק כזויות מזבח׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_16","039_9_16","ZEC","9","16","16","והושיעם יהוה אלהיהם ביום ההוא כצאן עמו כי אבני נזר מתנוססות על אדמתו׃ ");
INSERT INTO heb_vpl VALUES ("ZC9_17","039_9_17","ZEC","9","17","17","כי מה טובו ומה יפיו דגן בחורים ותירוש ינובב בתלות׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_1","039_10_1","ZEC","10","1","1","שאלו מיהוה מטר בעת מלקוש יהוה עשה חזיזים ומטר גשם יתן להם לאיש עשב בשדה׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_2","039_10_2","ZEC","10","2","2","כי התרפים דברו און והקוסמים חזו שקר וחלמות השוא ידברו הבל ינחמון על כן נסעו כמו צאן יענו כי אין רעה׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_3","039_10_3","ZEC","10","3","3","על הרעים חרה אפי ועל העתודים אפקוד כי פקד יהוה צבאות את עדרו את בית יהודה ושם אותם כסוס הודו במלחמה׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_4","039_10_4","ZEC","10","4","4","ממנו פנה ממנו יתד ממנו קשת מלחמה ממנו יצא כל נוגש יחדו׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_5","039_10_5","ZEC","10","5","5","והיו כגברים בוסים בטיט חוצות במלחמה ונלחמו כי יהוה עמם והבישו רכבי סוסים׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_6","039_10_6","ZEC","10","6","6","וגברתי את בית יהודה ואת בית יוסף אושיע והושבותים כי רחמתים והיו כאשר לא זנחתים כי אני יהוה אלהיהם ואענם׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_7","039_10_7","ZEC","10","7","7","והיו כגבור אפרים ושמח לבם כמו יין ובניהם יראו ושמחו יגל לבם ביהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_8","039_10_8","ZEC","10","8","8","אשרקה להם ואקבצם כי פדיתים ורבו כמו רבו׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_9","039_10_9","ZEC","10","9","9","ואזרעם בעמים ובמרחקים יזכרוני וחיו את בניהם ושבו׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_10","039_10_10","ZEC","10","10","10","והשיבותים מארץ מצרים ומאשור אקבצם ואל ארץ גלעד ולבנון אביאם ולא ימצא להם׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_11","039_10_11","ZEC","10","11","11","ועבר בים צרה והכה בים גלים והבישו כל מצולות יאר והורד גאון אשור ושבט מצרים יסור׃ ");
INSERT INTO heb_vpl VALUES ("ZC10_12","039_10_12","ZEC","10","12","12","וגברתים ביהוה ובשמו יתהלכו נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_1","039_11_1","ZEC","11","1","1","פתח לבנון דלתיך ותאכל אש בארזיך׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_2","039_11_2","ZEC","11","2","2","הילל ברוש כי נפל ארז אשר אדרים שדדו הילילו אלוני בשן כי ירד יער הבצור׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_3","039_11_3","ZEC","11","3","3","קול יללת הרעים כי שדדה אדרתם קול שאגת כפירים כי שדד גאון הירדן׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_4","039_11_4","ZEC","11","4","4","כה אמר יהוה אלהי רעה את צאן ההרגה׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_5","039_11_5","ZEC","11","5","5","אשר קניהן יהרגן ולא יאשמו ומכריהן יאמר ברוך יהוה ואעשר ורעיהם לא יחמול עליהן׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_6","039_11_6","ZEC","11","6","6","כי לא אחמול עוד על ישבי הארץ נאם יהוה והנה אנכי ממציא את האדם איש ביד רעהו וביד מלכו וכתתו את הארץ ולא אציל מידם׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_7","039_11_7","ZEC","11","7","7","וארעה את צאן ההרגה לכן עניי הצאן ואקח לי שני מקלות לאחד קראתי נעם ולאחד קראתי חבלים וארעה את הצאן׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_8","039_11_8","ZEC","11","8","8","ואכחד את שלשת הרעים בירח אחד ותקצר נפשי בהם וגם נפשם בחלה בי׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_9","039_11_9","ZEC","11","9","9","ואמר לא ארעה אתכם המתה תמות והנכחדת תכחד והנשארות תאכלנה אשה את בשר רעותה׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_10","039_11_10","ZEC","11","10","10","ואקח את מקלי את נעם ואגדע אתו להפיר את בריתי אשר כרתי את כל העמים׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_11","039_11_11","ZEC","11","11","11","ותפר ביום ההוא וידעו כן עניי הצאן השמרים אתי כי דבר יהוה הוא׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_12","039_11_12","ZEC","11","12","12","ואמר אליהם אם טוב בעיניכם הבו שכרי ואם לא חדלו וישקלו את שכרי שלשים כסף׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_13","039_11_13","ZEC","11","13","13","ויאמר יהוה אלי השליכהו אל היוצר אדר היקר אשר יקרתי מעליהם ואקחה שלשים הכסף ואשליך אתו בית יהוה אל היוצר׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_14","039_11_14","ZEC","11","14","14","ואגדע את מקלי השני את החבלים להפר את האחוה בין יהודה ובין ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_15","039_11_15","ZEC","11","15","15","ויאמר יהוה אלי עוד קח לך כלי רעה אולי׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_16","039_11_16","ZEC","11","16","16","כי הנה אנכי מקים רעה בארץ הנכחדות לא יפקד הנער לא יבקש והנשברת לא ירפא הנצבה לא יכלכל ובשר הבריאה יאכל ופרסיהן יפרק׃ ");
INSERT INTO heb_vpl VALUES ("ZC11_17","039_11_17","ZEC","11","17","17","הוי רעי האליל עזבי הצאן חרב על זרועו ועל עין ימינו זרעו יבוש תיבש ועין ימינו כהה תכהה׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_1","039_12_1","ZEC","12","1","1","משא דבר יהוה על ישראל נאם יהוה נטה שמים ויסד ארץ ויצר רוח אדם בקרבו׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_2","039_12_2","ZEC","12","2","2","הנה אנכי שם את ירושלם סף רעל לכל העמים סביב וגם על יהודה יהיה במצור על ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_3","039_12_3","ZEC","12","3","3","והיה ביום ההוא אשים את ירושלם אבן מעמסה לכל העמים כל עמסיה שרוט ישרטו ונאספו עליה כל גויי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_4","039_12_4","ZEC","12","4","4","ביום ההוא נאם יהוה אכה כל סוס בתמהון ורכבו בשגעון ועל בית יהודה אפקח את עיני וכל סוס העמים אכה בעורון׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_5","039_12_5","ZEC","12","5","5","ואמרו אלפי יהודה בלבם אמצה לי ישבי ירושלם ביהוה צבאות אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_6","039_12_6","ZEC","12","6","6","ביום ההוא אשים את אלפי יהודה ככיור אש בעצים וכלפיד אש בעמיר ואכלו על ימין ועל שמאול את כל העמים סביב וישבה ירושלם עוד תחתיה בירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_7","039_12_7","ZEC","12","7","7","והושיע יהוה את אהלי יהודה בראשנה למען לא תגדל תפארת בית דויד ותפארת ישב ירושלם על יהודה׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_8","039_12_8","ZEC","12","8","8","ביום ההוא יגן יהוה בעד יושב ירושלם והיה הנכשל בהם ביום ההוא כדויד ובית דויד כאלהים כמלאך יהוה לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_9","039_12_9","ZEC","12","9","9","והיה ביום ההוא אבקש להשמיד את כל הגוים הבאים על ירושלם׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_10","039_12_10","ZEC","12","10","10","ושפכתי על בית דויד ועל יושב ירושלם רוח חן ותחנונים והביטו אלי את אשר דקרו וספדו עליו כמספד על היחיד והמר עליו כהמר על הבכור׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_11","039_12_11","ZEC","12","11","11","ביום ההוא יגדל המספד בירושלם כמספד הדד רמון בבקעת מגדון׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_12","039_12_12","ZEC","12","12","12","וספדה הארץ משפחות משפחות לבד משפחת בית דויד לבד ונשיהם לבד משפחת בית נתן לבד ונשיהם לבד׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_13","039_12_13","ZEC","12","13","13","משפחת בית לוי לבד ונשיהם לבד משפחת השמעי לבד ונשיהם לבד׃ ");
INSERT INTO heb_vpl VALUES ("ZC12_14","039_12_14","ZEC","12","14","14","כל המשפחות הנשארות משפחת משפחת לבד ונשיהם לבד׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_1","039_13_1","ZEC","13","1","1","ביום ההוא יהיה מקור נפתח לבית דויד ולישבי ירושלם לחטאת ולנדה׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_2","039_13_2","ZEC","13","2","2","והיה ביום ההוא נאם יהוה צבאות אכרית את שמות העצבים מן הארץ ולא יזכרו עוד וגם את הנביאים ואת רוח הטמאה אעביר מן הארץ׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_3","039_13_3","ZEC","13","3","3","והיה כי ינבא איש עוד ואמרו אליו אביו ואמו ילדיו לא תחיה כי שקר דברת בשם יהוה ודקרהו אביהו ואמו ילדיו בהנבאו׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_4","039_13_4","ZEC","13","4","4","והיה ביום ההוא יבשו הנביאים איש מחזינו בהנבאתו ולא ילבשו אדרת שער למען כחש׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_5","039_13_5","ZEC","13","5","5","ואמר לא נביא אנכי איש עבד אדמה אנכי כי אדם הקנני מנעורי׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_6","039_13_6","ZEC","13","6","6","ואמר אליו מה המכות האלה בין ידיך ואמר אשר הכיתי בית מאהבי׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_7","039_13_7","ZEC","13","7","7","חרב עורי על רעי ועל גבר עמיתי נאם יהוה צבאות הך את הרעה ותפוצין הצאן והשבתי ידי על הצערים׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_8","039_13_8","ZEC","13","8","8","והיה בכל הארץ נאם יהוה פי שנים בה יכרתו יגועו והשלשית יותר בה׃ ");
INSERT INTO heb_vpl VALUES ("ZC13_9","039_13_9","ZEC","13","9","9","והבאתי את השלשית באש וצרפתים כצרף את הכסף ובחנתים כבחן את הזהב הוא יקרא בשמי ואני אענה אתו אמרתי עמי הוא והוא יאמר יהוה אלהי׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_1","039_14_1","ZEC","14","1","1","הנה יום בא ליהוה וחלק שללך בקרבך׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_2","039_14_2","ZEC","14","2","2","ואספתי את כל הגוים אל ירושלם למלחמה ונלכדה העיר ונשסו הבתים והנשים תשגלנה ויצא חצי העיר בגולה ויתר העם לא יכרת מן העיר׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_3","039_14_3","ZEC","14","3","3","ויצא יהוה ונלחם בגוים ההם כיום הלחמו ביום קרב׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_4","039_14_4","ZEC","14","4","4","ועמדו רגליו ביום ההוא על הר הזתים אשר על פני ירושלם מקדם ונבקע הר הזיתים מחציו מזרחה וימה גיא גדולה מאד ומש חצי ההר צפונה וחציו נגבה׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_5","039_14_5","ZEC","14","5","5","ונסתם גיא הרי כי יגיע גי הרים אל אצל ונסתם כאשר נסתם מפני הרעש בימי עזיה מלך יהודה ובא יהוה אלהי כל קדשים עמך׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_6","039_14_6","ZEC","14","6","6","והיה ביום ההוא לא יהיה אור יקרות יקפאון׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_7","039_14_7","ZEC","14","7","7","והיה יום אחד הוא יודע ליהוה לא יום ולא לילה והיה לעת ערב יהיה אור׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_8","039_14_8","ZEC","14","8","8","והיה ביום ההוא יצאו מים חיים מירושלם חצים אל הים הקדמוני וחצים אל הים האחרון בקיץ ובחרף יהיה׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_9","039_14_9","ZEC","14","9","9","והיה יהוה למלך על כל הארץ ביום ההוא יהיה יהוה אחד ושמו אחד׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_10","039_14_10","ZEC","14","10","10","יסוב כל הארץ כערבה מגבע לרמון נגב ירושלם וראמה וישבה תחתיה למשער בנימן עד מקום שער הראשון עד שער הפנים ומגדל חננאל עד יקבי המלך׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_11","039_14_11","ZEC","14","11","11","וישבו בה וחרם לא יהיה עוד וישבה ירושלם לבטח׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_12","039_14_12","ZEC","14","12","12","וזאת תהיה המגפה אשר יגף יהוה את כל העמים אשר צבאו על ירושלם המק בשרו והוא עמד על רגליו ועיניו תמקנה בחריהן ולשונו תמק בפיהם׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_13","039_14_13","ZEC","14","13","13","והיה ביום ההוא תהיה מהומת יהוה רבה בהם והחזיקו איש יד רעהו ועלתה ידו על יד רעהו׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_14","039_14_14","ZEC","14","14","14","וגם יהודה תלחם בירושלם ואסף חיל כל הגוים סביב זהב וכסף ובגדים לרב מאד׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_15","039_14_15","ZEC","14","15","15","וכן תהיה מגפת הסוס הפרד הגמל והחמור וכל הבהמה אשר יהיה במחנות ההמה כמגפה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_16","039_14_16","ZEC","14","16","16","והיה כל הנותר מכל הגוים הבאים על ירושלם ועלו מדי שנה בשנה להשתחות למלך יהוה צבאות ולחג את חג הסכות׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_17","039_14_17","ZEC","14","17","17","והיה אשר לא יעלה מאת משפחות הארץ אל ירושלם להשתחות למלך יהוה צבאות ולא עליהם יהיה הגשם׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_18","039_14_18","ZEC","14","18","18","ואם משפחת מצרים לא תעלה ולא באה ולא עליהם תהיה המגפה אשר יגף יהוה את הגוים אשר לא יעלו לחג את חג הסכות׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_19","039_14_19","ZEC","14","19","19","זאת תהיה חטאת מצרים וחטאת כל הגוים אשר לא יעלו לחג את חג הסכות׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_20","039_14_20","ZEC","14","20","20","ביום ההוא יהיה על מצלות הסוס קדש ליהוה והיה הסירות בבית יהוה כמזרקים לפני המזבח׃ ");
INSERT INTO heb_vpl VALUES ("ZC14_21","039_14_21","ZEC","14","21","21","והיה כל סיר בירושלם וביהודה קדש ליהוה צבאות ובאו כל הזבחים ולקחו מהם ובשלו בהם ולא יהיה כנעני עוד בבית יהוה צבאות ביום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("ML1_1","040_1_1","MAL","1","1","1","משא דבר יהוה אל ישראל ביד מלאכי׃ ");
INSERT INTO heb_vpl VALUES ("ML1_2","040_1_2","MAL","1","2","2","אהבתי אתכם אמר יהוה ואמרתם במה אהבתנו הלוא אח עשו ליעקב נאם יהוה ואהב את יעקב׃ ");
INSERT INTO heb_vpl VALUES ("ML1_3","040_1_3","MAL","1","3","3","ואת עשו שנאתי ואשים את הריו שממה ואת נחלתו לתנות מדבר׃ ");
INSERT INTO heb_vpl VALUES ("ML1_4","040_1_4","MAL","1","4","4","כי תאמר אדום רששנו ונשוב ונבנה חרבות כה אמר יהוה צבאות המה יבנו ואני אהרוס וקראו להם גבול רשעה והעם אשר זעם יהוה עד עולם׃ ");
INSERT INTO heb_vpl VALUES ("ML1_5","040_1_5","MAL","1","5","5","ועיניכם תראינה ואתם תאמרו יגדל יהוה מעל לגבול ישראל׃ ");
INSERT INTO heb_vpl VALUES ("ML1_6","040_1_6","MAL","1","6","6","בן יכבד אב ועבד אדניו ואם אב אני איה כבודי ואם אדונים אני איה מוראי אמר יהוה צבאות לכם הכהנים בוזי שמי ואמרתם במה בזינו את שמך׃ ");
INSERT INTO heb_vpl VALUES ("ML1_7","040_1_7","MAL","1","7","7","מגישים על מזבחי לחם מגאל ואמרתם במה גאלנוך באמרכם שלחן יהוה נבזה הוא׃ ");
INSERT INTO heb_vpl VALUES ("ML1_8","040_1_8","MAL","1","8","8","וכי תגשון עור לזבח אין רע וכי תגישו פסח וחלה אין רע הקריבהו נא לפחתך הירצך או הישא פניך אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML1_9","040_1_9","MAL","1","9","9","ועתה חלו נא פני אל ויחננו מידכם היתה זאת הישא מכם פנים אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML1_10","040_1_10","MAL","1","10","10","מי גם בכם ויסגר דלתים ולא תאירו מזבחי חנם אין לי חפץ בכם אמר יהוה צבאות ומנחה לא ארצה מידכם׃ ");
INSERT INTO heb_vpl VALUES ("ML1_11","040_1_11","MAL","1","11","11","כי ממזרח שמש ועד מבואו גדול שמי בגוים ובכל מקום מקטר מגש לשמי ומנחה טהורה כי גדול שמי בגוים אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML1_12","040_1_12","MAL","1","12","12","ואתם מחללים אותו באמרכם שלחן אדני מגאל הוא וניבו נבזה אכלו׃ ");
INSERT INTO heb_vpl VALUES ("ML1_13","040_1_13","MAL","1","13","13","ואמרתם הנה מתלאה והפחתם אותו אמר יהוה צבאות והבאתם גזול ואת הפסח ואת החולה והבאתם את המנחה הארצה אותה מידכם אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("ML1_14","040_1_14","MAL","1","14","14","וארור נוכל ויש בעדרו זכר ונדר וזבח משחת לאדני כי מלך גדול אני אמר יהוה צבאות ושמי נורא בגוים׃ ");
INSERT INTO heb_vpl VALUES ("ML2_1","040_2_1","MAL","2","1","1","ועתה אליכם המצוה הזאת הכהנים׃ ");
INSERT INTO heb_vpl VALUES ("ML2_2","040_2_2","MAL","2","2","2","אם לא תשמעו ואם לא תשימו על לב לתת כבוד לשמי אמר יהוה צבאות ושלחתי בכם את המארה וארותי את ברכותיכם וגם ארותיה כי אינכם שמים על לב׃ ");
INSERT INTO heb_vpl VALUES ("ML2_3","040_2_3","MAL","2","3","3","הנני גער לכם את הזרע וזריתי פרש על פניכם פרש חגיכם ונשא אתכם אליו׃ ");
INSERT INTO heb_vpl VALUES ("ML2_4","040_2_4","MAL","2","4","4","וידעתם כי שלחתי אליכם את המצוה הזאת להיות בריתי את לוי אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML2_5","040_2_5","MAL","2","5","5","בריתי היתה אתו החיים והשלום ואתנם לו מורא וייראני ומפני שמי נחת הוא׃ ");
INSERT INTO heb_vpl VALUES ("ML2_6","040_2_6","MAL","2","6","6","תורת אמת היתה בפיהו ועולה לא נמצא בשפתיו בשלום ובמישור הלך אתי ורבים השיב מעון׃ ");
INSERT INTO heb_vpl VALUES ("ML2_7","040_2_7","MAL","2","7","7","כי שפתי כהן ישמרו דעת ותורה יבקשו מפיהו כי מלאך יהוה צבאות הוא׃ ");
INSERT INTO heb_vpl VALUES ("ML2_8","040_2_8","MAL","2","8","8","ואתם סרתם מן הדרך הכשלתם רבים בתורה שחתם ברית הלוי אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML2_9","040_2_9","MAL","2","9","9","וגם אני נתתי אתכם נבזים ושפלים לכל העם כפי אשר אינכם שמרים את דרכי ונשאים פנים בתורה׃ ");
INSERT INTO heb_vpl VALUES ("ML2_10","040_2_10","MAL","2","10","10","הלוא אב אחד לכלנו הלוא אל אחד בראנו מדוע נבגד איש באחיו לחלל ברית אבתינו׃ ");
INSERT INTO heb_vpl VALUES ("ML2_11","040_2_11","MAL","2","11","11","בגדה יהודה ותועבה נעשתה בישראל ובירושלם כי חלל יהודה קדש יהוה אשר אהב ובעל בת אל נכר׃ ");
INSERT INTO heb_vpl VALUES ("ML2_12","040_2_12","MAL","2","12","12","יכרת יהוה לאיש אשר יעשנה ער וענה מאהלי יעקב ומגיש מנחה ליהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML2_13","040_2_13","MAL","2","13","13","וזאת שנית תעשו כסות דמעה את מזבח יהוה בכי ואנקה מאין עוד פנות אל המנחה ולקחת רצון מידכם׃ ");
INSERT INTO heb_vpl VALUES ("ML2_14","040_2_14","MAL","2","14","14","ואמרתם על מה על כי יהוה העיד בינך ובין אשת נעוריך אשר אתה בגדתה בה והיא חברתך ואשת בריתך׃ ");
INSERT INTO heb_vpl VALUES ("ML2_15","040_2_15","MAL","2","15","15","ולא אחד עשה ושאר רוח לו ומה האחד מבקש זרע אלהים ונשמרתם ברוחכם ובאשת נעוריך אל יבגד׃ ");
INSERT INTO heb_vpl VALUES ("ML2_16","040_2_16","MAL","2","16","16","כי שנא שלח אמר יהוה אלהי ישראל וכסה חמס על לבושו אמר יהוה צבאות ונשמרתם ברוחכם ולא תבגדו׃ ");
INSERT INTO heb_vpl VALUES ("ML2_17","040_2_17","MAL","2","17","17","הוגעתם יהוה בדבריכם ואמרתם במה הוגענו באמרכם כל עשה רע טוב בעיני יהוה ובהם הוא חפץ או איה אלהי המשפט׃ ");
INSERT INTO heb_vpl VALUES ("ML3_1","040_3_1","MAL","3","1","1","הנני שלח מלאכי ופנה דרך לפני ופתאם יבוא אל היכלו האדון אשר אתם מבקשים ומלאך הברית אשר אתם חפצים הנה בא אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML3_2","040_3_2","MAL","3","2","2","ומי מכלכל את יום בואו ומי העמד בהראותו כי הוא כאש מצרף וכברית מכבסים׃ ");
INSERT INTO heb_vpl VALUES ("ML3_3","040_3_3","MAL","3","3","3","וישב מצרף ומטהר כסף וטהר את בני לוי וזקק אתם כזהב וככסף והיו ליהוה מגישי מנחה בצדקה׃ ");
INSERT INTO heb_vpl VALUES ("ML3_4","040_3_4","MAL","3","4","4","וערבה ליהוה מנחת יהודה וירושלם כימי עולם וכשנים קדמניות׃ ");
INSERT INTO heb_vpl VALUES ("ML3_5","040_3_5","MAL","3","5","5","וקרבתי אליכם למשפט והייתי עד ממהר במכשפים ובמנאפים ובנשבעים לשקר ובעשקי שכר שכיר אלמנה ויתום ומטי גר ולא יראוני אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML3_6","040_3_6","MAL","3","6","6","כי אני יהוה לא שניתי ואתם בני יעקב לא כליתם׃ ");
INSERT INTO heb_vpl VALUES ("ML3_7","040_3_7","MAL","3","7","7","למימי אבתיכם סרתם מחקי ולא שמרתם שובו אלי ואשובה אליכם אמר יהוה צבאות ואמרתם במה נשוב׃ ");
INSERT INTO heb_vpl VALUES ("ML3_8","040_3_8","MAL","3","8","8","היקבע אדם אלהים כי אתם קבעים אתי ואמרתם במה קבענוך המעשר והתרומה׃ ");
INSERT INTO heb_vpl VALUES ("ML3_9","040_3_9","MAL","3","9","9","במארה אתם נארים ואתי אתם קבעים הגוי כלו׃ ");
INSERT INTO heb_vpl VALUES ("ML3_10","040_3_10","MAL","3","10","10","הביאו את כל המעשר אל בית האוצר ויהי טרף בביתי ובחנוני נא בזאת אמר יהוה צבאות אם לא אפתח לכם את ארבות השמים והריקתי לכם ברכה עד בלי די׃ ");
INSERT INTO heb_vpl VALUES ("ML3_11","040_3_11","MAL","3","11","11","וגערתי לכם באכל ולא ישחת לכם את פרי האדמה ולא תשכל לכם הגפן בשדה אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML3_12","040_3_12","MAL","3","12","12","ואשרו אתכם כל הגוים כי תהיו אתם ארץ חפץ אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML3_13","040_3_13","MAL","3","13","13","חזקו עלי דבריכם אמר יהוה ואמרתם מה נדברנו עליך׃ ");
INSERT INTO heb_vpl VALUES ("ML3_14","040_3_14","MAL","3","14","14","אמרתם שוא עבד אלהים ומה בצע כי שמרנו משמרתו וכי הלכנו קדרנית מפני יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML3_15","040_3_15","MAL","3","15","15","ועתה אנחנו מאשרים זדים גם נבנו עשי רשעה גם בחנו אלהים וימלטו׃ ");
INSERT INTO heb_vpl VALUES ("ML3_16","040_3_16","MAL","3","16","16","אז נדברו יראי יהוה איש את רעהו ויקשב יהוה וישמע ויכתב ספר זכרון לפניו ליראי יהוה ולחשבי שמו׃ ");
INSERT INTO heb_vpl VALUES ("ML3_17","040_3_17","MAL","3","17","17","והיו לי אמר יהוה צבאות ליום אשר אני עשה סגלה וחמלתי עליהם כאשר יחמל איש על בנו העבד אתו׃ ");
INSERT INTO heb_vpl VALUES ("ML3_18","040_3_18","MAL","3","18","18","ושבתם וראיתם בין צדיק לרשע בין עבד אלהים לאשר לא עבדו׃ ");
INSERT INTO heb_vpl VALUES ("ML4_1","040_4_1","MAL","4","1","1","כי הנה היום בא בער כתנור והיו כל זדים וכל עשה רשעה קש ולהט אתם היום הבא אמר יהוה צבאות אשר לא יעזב להם שרש וענף׃ ");
INSERT INTO heb_vpl VALUES ("ML4_2","040_4_2","MAL","4","2","2","וזרחה לכם יראי שמי שמש צדקה ומרפא בכנפיה ויצאתם ופשתם כעגלי מרבק׃ ");
INSERT INTO heb_vpl VALUES ("ML4_3","040_4_3","MAL","4","3","3","ועסותם רשעים כי יהיו אפר תחת כפות רגליכם ביום אשר אני עשה אמר יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("ML4_4","040_4_4","MAL","4","4","4","זכרו תורת משה עבדי אשר צויתי אותו בחרב על כל ישראל חקים ומשפטים׃ ");
INSERT INTO heb_vpl VALUES ("ML4_5","040_4_5","MAL","4","5","5","הנה אנכי שלח לכם את אליה הנביא לפני בוא יום יהוה הגדול והנורא׃ ");
INSERT INTO heb_vpl VALUES ("ML4_6","040_4_6","MAL","4","6","6","והשיב לב אבות על בנים ולב בנים על אבותם פן אבוא והכיתי את הארץ חרם׃ ");
INSERT INTO heb_vpl VALUES ("MT1_1","070_1_1","MAT","1","1","1","ספר תולדת ישוע המשיח בן דוד בן אברהם׃ ");
INSERT INTO heb_vpl VALUES ("MT1_2","070_1_2","MAT","1","2","2","אברהם הוליד את יצחק ויצחק הוליד את יעקב ויעקב הוליד את יהודה ואת אחיו׃ ");
INSERT INTO heb_vpl VALUES ("MT1_3","070_1_3","MAT","1","3","3","ויהודה הוליד את פרץ ואת זרח מתמר ופרץ הוליד את חצרון וחצרון הוליד את רם׃ ");
INSERT INTO heb_vpl VALUES ("MT1_4","070_1_4","MAT","1","4","4","ורם הוליד את עמינדב ועמינדב הוליד את נחשון ונחשון הוליד את שלמון׃ ");
INSERT INTO heb_vpl VALUES ("MT1_5","070_1_5","MAT","1","5","5","ושלמון הוליד את בעז מרחב ובעז הוליד את עובד מרות ועובד הוליד את ישי׃ ");
INSERT INTO heb_vpl VALUES ("MT1_6","070_1_6","MAT","1","6","6","וישי הוליד את דוד המלך ודוד המלך הוליד את שלמה מאשת אוריה׃ ");
INSERT INTO heb_vpl VALUES ("MT1_7","070_1_7","MAT","1","7","7","ושלמה הוליד את רחבעם ורחבעם הוליד את אביה ואביה הוליד את אסא׃ ");
INSERT INTO heb_vpl VALUES ("MT1_8","070_1_8","MAT","1","8","8","ואסא הוליד את יהושפט ויהושפט הוליד את יורם ויורם הוליד את עזיהו׃ ");
INSERT INTO heb_vpl VALUES ("MT1_9","070_1_9","MAT","1","9","9","ועזיהו הוליד את יותם ויותם הוליד את אחז ואחז הוליד את יחזקיהו׃ ");
INSERT INTO heb_vpl VALUES ("MT1_10","070_1_10","MAT","1","10","10","ויחזקיהו הוליד את מנשה ומנשה הוליד את אמון ואמון הוליד את יאשיהו׃ ");
INSERT INTO heb_vpl VALUES ("MT1_11","070_1_11","MAT","1","11","11","ויאשיהו הוליד את יכניהו ואת אחיו לעת גלות בבל׃ ");
INSERT INTO heb_vpl VALUES ("MT1_12","070_1_12","MAT","1","12","12","ואחרי גלותם בבלה הוליד יכניה את שאלתיאל ושאלתיאל הוליד את זרבבל׃ ");
INSERT INTO heb_vpl VALUES ("MT1_13","070_1_13","MAT","1","13","13","וזרבבל הוליד את אביהוד ואביהוד הוליד את אליקים ואליקים הוליד את עזור׃ ");
INSERT INTO heb_vpl VALUES ("MT1_14","070_1_14","MAT","1","14","14","ועזור הוליד את צדוק וצדוק הוליד את יכין ויכין הוליד את אליהוד׃ ");
INSERT INTO heb_vpl VALUES ("MT1_15","070_1_15","MAT","1","15","15","ואליהוד הוליד את אלעזר ואלעזר הוליד את מתן ומתן הוליד את יעקב׃ ");
INSERT INTO heb_vpl VALUES ("MT1_16","070_1_16","MAT","1","16","16","ויעקב הוליד את יוסף בעל מרים אשר ממנה נולד ישוע הנקרא משיח׃ ");
INSERT INTO heb_vpl VALUES ("MT1_17","070_1_17","MAT","1","17","17","והנה כל הדרות מן אברהם עד דוד ארבעה עשר דרות ומן דוד עד גלות בבל ארבעה עשר דרות ומעת גלות בבל עד המשיח ארבעה עשר דרות׃ ");
INSERT INTO heb_vpl VALUES ("MT1_18","070_1_18","MAT","1","18","18","והלדת ישוע המשיח כה היתה מרים אמו ארשה ליוסף ובטרם יבא אליה נמצאת הרה לרוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("MT1_19","070_1_19","MAT","1","19","19","ויוסף בעלה היה איש צדיק ולא אבה לתתה לבוז ויאמר בלבו לשלחה בסתר׃ ");
INSERT INTO heb_vpl VALUES ("MT1_20","070_1_20","MAT","1","20","20","הוא חשב כזאת והנה מלאך יהוה נראה אליו בחלום ויאמר יוסף בן דוד אל תירא מכנוס אליך את מרים אשתך כי אשר הרה בה מרוח הקדש הוא׃ ");
INSERT INTO heb_vpl VALUES ("MT1_21","070_1_21","MAT","1","21","21","והיא ילדת בן וקראת את שמו ישוע כי הוא יושיע את עמו מעונותיהם׃ ");
INSERT INTO heb_vpl VALUES ("MT1_22","070_1_22","MAT","1","22","22","ותהי כל זאת למלאת את אשר דבר יהוה ביד הנביא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT1_23","070_1_23","MAT","1","23","23","הנה העלמה הרה וילדת בן וקראו שמו עמנואל אשר פרושו האל עמנו׃ ");
INSERT INTO heb_vpl VALUES ("MT1_24","070_1_24","MAT","1","24","24","וייקץ יוסף משנתו ויעש כאשר צוהו מלאך יהוה ויקח אליו את אשתו׃ ");
INSERT INTO heb_vpl VALUES ("MT1_25","070_1_25","MAT","1","25","25","ולא ידעה עד כי ילדה בן את בכורה ויקרא את שמו ישוע׃ ");
INSERT INTO heb_vpl VALUES ("MT2_1","070_2_1","MAT","2","1","1","ויהי כאשר נולד ישוע בבית לחם יהודה בימי הורדוס המלך ויבאו מגושים מארץ מזרח ירושלימה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT2_2","070_2_2","MAT","2","2","2","איה מלך היהודים הנולד כי ראינו את כוכבו במזרח ונבא להשתחות לו׃ ");
INSERT INTO heb_vpl VALUES ("MT2_3","070_2_3","MAT","2","3","3","ויהי כשמע הורדוס המלך את דבריהם ויבהל הוא וכל ירושלים עמו׃ ");
INSERT INTO heb_vpl VALUES ("MT2_4","070_2_4","MAT","2","4","4","ויקהל את כל ראשי הכהנים וסופרי העם וידרש מאתם לאמר איפה יולד המשיח׃ ");
INSERT INTO heb_vpl VALUES ("MT2_5","070_2_5","MAT","2","5","5","ויאמרו לו בבית לחם יהודה כי כן כתוב ביד הנביא׃ ");
INSERT INTO heb_vpl VALUES ("MT2_6","070_2_6","MAT","2","6","6","ואתה בית לחם ארץ יהודה אינך צעיר באלפי יהודה כי ממך יצא מושל אשר ירעה את עמי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MT2_7","070_2_7","MAT","2","7","7","אז קרא הורדוס למגושים בסתר ויחקר אתם לדעת עת הראות הכוכב׃ ");
INSERT INTO heb_vpl VALUES ("MT2_8","070_2_8","MAT","2","8","8","וישלחם בית לחם ויאמר לכו חקרו היטב על דבר הילד והיה כי תמצאון אתו והגדתם לי ואבאה להשתחות לו גם אני׃ ");
INSERT INTO heb_vpl VALUES ("MT2_9","070_2_9","MAT","2","9","9","ויהי כשמעם את דברי המלך וילכו והנה הכוכב אשר ראו במזרח דרך לפניהם עד באו אל מקום אשר שם הילד ויעמד ממעל לו׃ ");
INSERT INTO heb_vpl VALUES ("MT2_10","070_2_10","MAT","2","10","10","ויראו את הכוכב וישמחו שמחה גדולה עד מאד׃ ");
INSERT INTO heb_vpl VALUES ("MT2_11","070_2_11","MAT","2","11","11","ויבאו הביתה וימצאו את הילד עם מרים אמו ויפל על פניהם וישתחוו לו ויפתחו את אוצרותם ויקריבו לו מנחה זהב ולבונה ומר׃ ");
INSERT INTO heb_vpl VALUES ("MT2_12","070_2_12","MAT","2","12","12","ויצוו בחלום לבלתי שוב אל הורדוס וילכו בדרך אחר אל ארצם׃ ");
INSERT INTO heb_vpl VALUES ("MT2_13","070_2_13","MAT","2","13","13","הם הלכו משם והנה מלאך יהוה נראה אל יוסף בחלום לאמר קום קח את הילד ואת אמו וברח לך מצרימה והיה שם עד אשר אמר אליך כי הורדוס צדה את הילד לאבדו׃ ");
INSERT INTO heb_vpl VALUES ("MT2_14","070_2_14","MAT","2","14","14","ויקם ויקח את הילד ואת אמו בלילה ויברח מצרימה׃ ");
INSERT INTO heb_vpl VALUES ("MT2_15","070_2_15","MAT","2","15","15","ויהי שם עד מות הורדוס למלאת את אשר דבר יהוה ביד הנביא לאמר ממצרים קראתי לבני׃ ");
INSERT INTO heb_vpl VALUES ("MT2_16","070_2_16","MAT","2","16","16","וירא הורדוס כי התלו בו המגושים ויקצף מאד וישלח וימת את כל הילדים אשר בבית לחם ובכל גבוליה מבן שנתים ולמטה כפי העת אשר חקרה מפי המגושים׃ ");
INSERT INTO heb_vpl VALUES ("MT2_17","070_2_17","MAT","2","17","17","וימלא הדבר הנאמר בפי ירמיה הנביא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT2_18","070_2_18","MAT","2","18","18","קול ברמה נשמע נהי ובכי תמרורים רחל מבכה על בניה מאנה להנחם כי אינם׃ ");
INSERT INTO heb_vpl VALUES ("MT2_19","070_2_19","MAT","2","19","19","ויהי אחרי מות הורדוס והנה מלאך יהוה נראה בחלום אל יוסף בארץ מצרים׃ ");
INSERT INTO heb_vpl VALUES ("MT2_20","070_2_20","MAT","2","20","20","ויאמר אליו קום קח את הילד ואת אמו ולך שוב אל ארץ ישראל כי מתו המבקשים את נפש הילד׃ ");
INSERT INTO heb_vpl VALUES ("MT2_21","070_2_21","MAT","2","21","21","ויקם ויקח את הילד ואת אמו ויבא ארצה ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MT2_22","070_2_22","MAT","2","22","22","וכשמעו כי ארקלוס מלך ביהודה תחת הורדוס אביו ירא ללכת שמה ויצוה בחלום וילך לו אל ארצות הגליל׃ ");
INSERT INTO heb_vpl VALUES ("MT2_23","070_2_23","MAT","2","23","23","ויבא וישב בעיר אשר שמה נצרת למלאת הדבר הנאמר על פי הנביאים כי נצרי יקרא לו׃ ");
INSERT INTO heb_vpl VALUES ("MT3_1","070_3_1","MAT","3","1","1","בימים ההם בא יוחנן המטביל ויהי קרא במדבר יהודה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT3_2","070_3_2","MAT","3","2","2","שובו כי מלכות השמים הגיעה׃ ");
INSERT INTO heb_vpl VALUES ("MT3_3","070_3_3","MAT","3","3","3","הלא זה הוא אשר נבא עליו ישעיהו הנביא לאמר קול קורא במדבר פנו דרך יהוה ישרו מסלותיו׃ ");
INSERT INTO heb_vpl VALUES ("MT3_4","070_3_4","MAT","3","4","4","והוא יוחנן לבושו שער גמלים ואזור עור במתניו ומאכלו חגבים ודבש היער׃ ");
INSERT INTO heb_vpl VALUES ("MT3_5","070_3_5","MAT","3","5","5","ויצאו אליו ישבי ירושלים וכל יהודה וכל ככר הירדן׃ ");
INSERT INTO heb_vpl VALUES ("MT3_6","070_3_6","MAT","3","6","6","ויטבלו על ידו בירדן מתודים את חטאתם׃ ");
INSERT INTO heb_vpl VALUES ("MT3_7","070_3_7","MAT","3","7","7","ויהי כראותו רבים מן הפרושים והצדוקים נגשים לטבילתו ויאמר להם ילדי הצפעונים מי השכיל אתכם להמלט מן הקצף הבא׃ ");
INSERT INTO heb_vpl VALUES ("MT3_8","070_3_8","MAT","3","8","8","לכן עשו פרי הראוי לתשובה׃ ");
INSERT INTO heb_vpl VALUES ("MT3_9","070_3_9","MAT","3","9","9","ואל תחשבו בלבבכם לאמר אברהם הוא אבינו כי אני אמר לכם כי מן האבנים האלה יכול האלהים להקים בנים לאברהם׃ ");
INSERT INTO heb_vpl VALUES ("MT3_10","070_3_10","MAT","3","10","10","וכבר הושם הגרזן על שרש העצים והנה כל עץ אשר איננו עשה פרי טוב יגדע וישלך באש׃ ");
INSERT INTO heb_vpl VALUES ("MT3_11","070_3_11","MAT","3","11","11","הן אנכי טובל אתכם במים לתשובה והבא אחרי חזק הוא ממני אשר אינני כדי לשאת נעליו והוא יטבל אתכם ברוח הקדש ובאש׃ ");
INSERT INTO heb_vpl VALUES ("MT3_12","070_3_12","MAT","3","12","12","אשר בידו המזרה וזרה את גרנו ואסף את דגנו אל אוצרו ואת המץ ישרפנו באש אשר לא תכבה׃ ");
INSERT INTO heb_vpl VALUES ("MT3_13","070_3_13","MAT","3","13","13","ויבא ישוע מן הגליל הירדנה אל יוחנן להטבל על ידו׃ ");
INSERT INTO heb_vpl VALUES ("MT3_14","070_3_14","MAT","3","14","14","ויוחנן חשך אותו לאמר אני צריך להטבל על ידך ואתה בא אלי׃ ");
INSERT INTO heb_vpl VALUES ("MT3_15","070_3_15","MAT","3","15","15","ויען ישוע ויאמר אליו הניחה לי כי כן נאוה לנו למלא כל הצדקה וינח לו׃ ");
INSERT INTO heb_vpl VALUES ("MT3_16","070_3_16","MAT","3","16","16","ויהי כאשר נטבל ישוע וימהר לעלות מן המים והנה נפתחו לו השמים וירא את רוח אלהים יורדת כיונה ונחה עליו׃ ");
