INSERT INTO heb_vpl VALUES ("MT4_10","070_4_10","MAT","4","10","10","ויאמר אליו ישוע סור ממני השטן כי כתוב ליהוה אלהיך תשתחוה ואותו לבדו תעבד׃ ");
INSERT INTO heb_vpl VALUES ("MT4_11","070_4_11","MAT","4","11","11","וירף ממנו השטן והנה נגשו אליו מלאכים וישרתוהו׃ ");
INSERT INTO heb_vpl VALUES ("MT4_12","070_4_12","MAT","4","12","12","ויהי כשמעו כי הסגירו את יוחנן וילך לו ארץ הגליל׃ ");
INSERT INTO heb_vpl VALUES ("MT4_13","070_4_13","MAT","4","13","13","ויעזב את נצרת ויבא וישב בכפר נחום אשר על שפת הים בגבול זבלון ונפתלי׃ ");
