INSERT INTO heb_vpl VALUES ("MT4_18","070_4_18","MAT","4","18","18","ויהי בהתהלכו על יד ים הגליל וירא שני אנשים אחים את שמעון הנקרא פטרוס ואת אנדרי אחיו והמה משליכים מצודה בים כי דיגים היו׃ ");
INSERT INTO heb_vpl VALUES ("MT4_19","070_4_19","MAT","4","19","19","ויאמר אליהם לכו אחרי ואשימכם לדיגי אנשים׃ ");
