INSERT INTO heb_vpl VALUES ("MT4_22","070_4_22","MAT","4","22","22","ויעזבו מיד את האניה ואת אביהם וילכו אחריו׃ ");
INSERT INTO heb_vpl VALUES ("MT4_23","070_4_23","MAT","4","23","23","ויסב ישוע בכל הגליל וילמד בבתי כנסיותיהם ויבשר בשורת המלכות וירפא כל מחלה וכל מדוה בעם׃ ");
INSERT INTO heb_vpl VALUES ("MT4_24","070_4_24","MAT","4","24","24","ויצא שמעו בכל ארץ סוריא ויביאו אליו את כל החולים המענים בכל חלים ומכאובים ואחוזי שדים ומכי ירח ונכי אברים וירפאם׃ ");
INSERT INTO heb_vpl VALUES ("MT4_25","070_4_25","MAT","4","25","25","וילכו אחריו המנים המנים מן הגליל ומן עשר הערים ומירושלים ויהודה ומעבר לירדן׃ ");
INSERT INTO heb_vpl VALUES ("MT5_1","070_5_1","MAT","5","1","1","ויהי כראותו את המון העם ויעל ההרה וישב שם ויגשו אליו תלמידיו׃ ");
