INSERT INTO heb_vpl VALUES ("MT5_13","070_5_13","MAT","5","13","13","אתם מלח הארץ ואם המלח היה תפל במה ימלח הן לא יצלח עוד לכל כי אם להשליך חוצה והיה מרמס לבני אדם׃ ");
INSERT INTO heb_vpl VALUES ("MT5_14","070_5_14","MAT","5","14","14","אתם אור העולם עיר ישבת על ההר לא תוכל להסתר׃ ");
INSERT INTO heb_vpl VALUES ("MT5_15","070_5_15","MAT","5","15","15","גם אין מדליקים נר ושמים אותו תחת האיפה כי אם על המנורה ויאר לכל אנשי הבית׃ ");
INSERT INTO heb_vpl VALUES ("MT5_16","070_5_16","MAT","5","16","16","כן יאר אורכם לפני בני האדם למען יראו מעשיכם הטובים ושבחו את אביכים שבשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT5_17","070_5_17","MAT","5","17","17","אל תחשבו כי באתי להפר את התורה או את דברי הנביאים לא באתי להפר כי אם למלאת׃ ");
INSERT INTO heb_vpl VALUES ("MT5_18","070_5_18","MAT","5","18","18","כי אמן אמר אני לכם עד כי יעברו השמים והארץ לא תעבר יוד אחת או קוץ אחד מן התורה עד אשר יעשה הכל׃ ");
