INSERT INTO heb_vpl VALUES ("MT5_20","070_5_20","MAT","5","20","20","כי אני אמר לכם אם לא תרבה צדקתכם מצדקת הסופרים והפרושים לא תבאו אל מלכות השמים׃ ");
