INSERT INTO heb_vpl VALUES ("MT5_25","070_5_25","MAT","5","25","25","מהר התרצה לאיש ריבך בעודך בדרך אתו פן יסגיר אתך איש ריבך אל השפט והשפט יסגירך לשוטר והשלכת את בית הכלא׃ ");
INSERT INTO heb_vpl VALUES ("MT5_26","070_5_26","MAT","5","26","26","אמן אמר אני לך לא תצא משם עד אשר שלמת את הפרוטה האחרונה׃ ");
