INSERT INTO heb_vpl VALUES ("MT5_29","070_5_29","MAT","5","29","29","ואם תכשילך עין ימינך נקר אותה והשלך ממך כי טוב לך אשר יאבד אחד מאבריך מרדת כל גופך אל גיהנם׃ ");
INSERT INTO heb_vpl VALUES ("MT5_30","070_5_30","MAT","5","30","30","ואם ידך הימנית תכשילך קצץ אותה והשלך ממך כי טוב לך אשר יאבד אחד מאבריך מרדת כל גופך אל גיהנם׃ ");
INSERT INTO heb_vpl VALUES ("MT5_31","070_5_31","MAT","5","31","31","ונאמר איש אשר ישלח את אשתו ונתן לה ספר כריתות׃ ");
