INSERT INTO heb_vpl VALUES ("MT6_1","070_6_1","MAT","6","1","1","השמרו לכם מעשות צדקתכם לפני בני אדם למען יראו אתכם ואם לא אין לכם שכר מאת אביכם שבשמים׃ ");
