INSERT INTO heb_vpl VALUES ("MT6_12","070_6_12","MAT","6","12","12","וסלח לנו את חבותינו כאשר סלחנו גם אנחנו לחיבינו׃ ");
INSERT INTO heb_vpl VALUES ("MT6_13","070_6_13","MAT","6","13","13","ואל תביאנו לידי נסיון כי אם חלצנו מן הרע כי לך הממלכה והגבורה והתפארת לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("MT6_14","070_6_14","MAT","6","14","14","כי אם תסלחו לבני אדם את חטאתם אביכם שבשמים יסלח גם לכם׃ ");
INSERT INTO heb_vpl VALUES ("MT6_15","070_6_15","MAT","6","15","15","ואם לא תסלחו לבני אדם גם אביכם לא יסלח לכם את חטאתיכם׃ ");
INSERT INTO heb_vpl VALUES ("MT6_16","070_6_16","MAT","6","16","16","וכי תצומו אל תהיו זעפים כחנפים המשנים את פניהם להראות צמים לבני אדם אמן אמר אני לכם כי לקחו את שכרם׃ ");
INSERT INTO heb_vpl VALUES ("MT6_17","070_6_17","MAT","6","17","17","ואתה כי תצום סוך את ראשך ורחץ את פניך׃ ");
INSERT INTO heb_vpl VALUES ("MT6_18","070_6_18","MAT","6","18","18","למען לא תראה בצומך לבני אדם כי אם לאביך אשר בסתר ואביך הראה במסתרים הוא בגלוי יגמלך׃ ");
INSERT INTO heb_vpl VALUES ("MT6_19","070_6_19","MAT","6","19","19","אל תאצרו לכם אוצרות בארץ אשר יאכלום שם סס ורקב וגנבים יחתרו שם וגנבו׃ ");
INSERT INTO heb_vpl VALUES ("MT6_20","070_6_20","MAT","6","20","20","אבל תאצרו לכם אוצרות בשמים אשר סס ורקב לא יאכלום שם וגנבים לא יחתרו שם ולא יגנבו׃ ");
INSERT INTO heb_vpl VALUES ("MT6_21","070_6_21","MAT","6","21","21","כי במקום אשר אוצרכם בו שם יהיה גם לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("MT6_22","070_6_22","MAT","6","22","22","נר הגוף הוא העין ואם עינך היא תמימה כל גופך יאור׃ ");
INSERT INTO heb_vpl VALUES ("MT6_23","070_6_23","MAT","6","23","23","ואם עינך רעה כל גופך יחשך והנה אם יחשך האור אשר בקרבך מה רב החשך׃ ");
INSERT INTO heb_vpl VALUES ("MT6_24","070_6_24","MAT","6","24","24","לא יוכל איש לעבד שני אדנים כי אם ישנא את האחד ויאהב את האחר או ידבק באחד ויבזה את האחר לא תוכלו עבוד את האלהים ואת הממון׃ ");
INSERT INTO heb_vpl VALUES ("MT6_25","070_6_25","MAT","6","25","25","על כן אמר אני לכם אל תדאגו לנפשכם מה תאכלו ומה תשתו ולגופכם מה תלבשו הלא הנפש היא יקרה מן המזון והגוף יקר מן המלבוש׃ ");
INSERT INTO heb_vpl VALUES ("MT6_26","070_6_26","MAT","6","26","26","הביטו וראו את עוף השמים אשר אינם זרעים ואינם קצרים ואינם אספים לאסמים ואביכם שבשמים מכלכל אתם הלא אתם נעליתם עליהם מאד׃ ");
INSERT INTO heb_vpl VALUES ("MT6_27","070_6_27","MAT","6","27","27","ומי זה מכם אשר בדאגתו יוכל להוסיף על קומתו אמה אחת׃ ");
INSERT INTO heb_vpl VALUES ("MT6_28","070_6_28","MAT","6","28","28","וללבוש למה תדאגו התבוננו נא אל שושני השדה הצמחות אינן עמלות ואינן טות׃ ");
INSERT INTO heb_vpl VALUES ("MT6_29","070_6_29","MAT","6","29","29","ואני אמר לכם כי גם שלמה בכל הדרו לא היה לבוש כאחת מהנה׃ ");
INSERT INTO heb_vpl VALUES ("MT6_30","070_6_30","MAT","6","30","30","ואם ככה מלביש האלהים את חציר השדה אשר היום צמח ומחר ישלך לתוך התנור אף כי אתכם קטני האמונה׃ ");
INSERT INTO heb_vpl VALUES ("MT6_31","070_6_31","MAT","6","31","31","לכן אל תדאגו לאמר מה נאכל ומה נשתה ומה נלבש׃ ");
INSERT INTO heb_vpl VALUES ("MT6_32","070_6_32","MAT","6","32","32","כי את כל אלה מבקשים הגוים הלא ידע אביכם אשר בשמים כי אתם צריכים לכל אלה׃ ");
INSERT INTO heb_vpl VALUES ("MT6_33","070_6_33","MAT","6","33","33","אך בקשו בראשונה את מלכות אלהים ואת צדקתו ונוסף לכם כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("MT6_34","070_6_34","MAT","6","34","34","לכן אל תדאגו ליום מחר כי יום מחר הוא ידאג לעצמו ודיו ליום צרתו׃ ");
INSERT INTO heb_vpl VALUES ("MT7_1","070_7_1","MAT","7","1","1","אל תשפטו למען לא תשפטו׃ ");
INSERT INTO heb_vpl VALUES ("MT7_2","070_7_2","MAT","7","2","2","כי במשפט אשר אתם שפטים בו תשפטו ובמדה אשר אתם מדדים בה ימד לכם׃ ");
INSERT INTO heb_vpl VALUES ("MT7_3","070_7_3","MAT","7","3","3","ולמה זה אתה ראה את הקסם בעין אחיך ואת הקורה אשר בעינך לא תביט׃ ");
INSERT INTO heb_vpl VALUES ("MT7_4","070_7_4","MAT","7","4","4","ואיך תאמר אל אחיך הניחה לי ואסירה את הקסם מעינך והנה הקורה בעינך׃ ");
INSERT INTO heb_vpl VALUES ("MT7_5","070_7_5","MAT","7","5","5","החנף הסר בראשונה את הקורה מעינך ואחרי כן ראה תראה להסיר את הקסם מעין אחיך׃ ");
INSERT INTO heb_vpl VALUES ("MT7_6","070_7_6","MAT","7","6","6","אל תתנו את הקדש לכלבים ואל תשליכו פניניכם לפני החזירים פן ירמסום ברגליהם ופנו וטרפו אתכם׃ ");
INSERT INTO heb_vpl VALUES ("MT7_7","070_7_7","MAT","7","7","7","שאלו וינתן לכם דרשו ותמצאו דפקו ויפתח לכם׃ ");
INSERT INTO heb_vpl VALUES ("MT7_8","070_7_8","MAT","7","8","8","כי כל השאל יקבל והדרש ימצא והדפק יפתח לו׃ ");
INSERT INTO heb_vpl VALUES ("MT7_9","070_7_9","MAT","7","9","9","ומי זה איש מכם אשר ישאל ממנו בנו לחם ונתן לו אבן׃ ");
INSERT INTO heb_vpl VALUES ("MT7_10","070_7_10","MAT","7","10","10","וכי ישאל ממנו דג היתן לו נחש׃ ");
INSERT INTO heb_vpl VALUES ("MT7_11","070_7_11","MAT","7","11","11","הן אתם הרעים ידעים לתת מתנות טבות לבניכם אף כי אביכם שבשמים יתן אך טוב לשאלים מאתו׃ ");
INSERT INTO heb_vpl VALUES ("MT7_12","070_7_12","MAT","7","12","12","לכן כל אשר תחפצו כי יעשו לכם בני האדם עשו להם גם אתם כי זאת היא התורה והנביאים׃ ");
INSERT INTO heb_vpl VALUES ("MT7_13","070_7_13","MAT","7","13","13","באו בפתח הצר כי רחב הפתח ומרוח הדרך המביא לאבדון ורבים אשר יבאו בו׃ ");
INSERT INTO heb_vpl VALUES ("MT7_14","070_7_14","MAT","7","14","14","ומה צר הפתח ומוצק הדרך המביא לחיים ומעטים הם אשר ימצאוהו׃ ");
INSERT INTO heb_vpl VALUES ("MT7_15","070_7_15","MAT","7","15","15","השמרו לכם מנביאי השקר הבאים אליכם בלבוש כבשים ובקרבם זאבים טרפים המה׃ ");
INSERT INTO heb_vpl VALUES ("MT7_16","070_7_16","MAT","7","16","16","הכר תכירו אותם בפריהם היאספו ענבים מן הקצים או תאנים מן הברקנים׃ ");
INSERT INTO heb_vpl VALUES ("MT7_17","070_7_17","MAT","7","17","17","כן כל עץ טוב עשה פרי טוב והמשחת עשה פרי רע׃ ");
INSERT INTO heb_vpl VALUES ("MT7_18","070_7_18","MAT","7","18","18","עץ טוב לא יוכל עשות פרי רע ועץ משחת לא יעשה פרי טוב׃ ");
INSERT INTO heb_vpl VALUES ("MT7_19","070_7_19","MAT","7","19","19","וכל עץ אשר לא יעשה פרי טוב יגדע וישלך באש׃ ");
INSERT INTO heb_vpl VALUES ("MT7_20","070_7_20","MAT","7","20","20","לכן בפרים תכירו אותם׃ ");
INSERT INTO heb_vpl VALUES ("MT7_21","070_7_21","MAT","7","21","21","לא כל האמר לי אדני אדני יבוא אל מלכות השמים כי אם העשה רצון אבי שבשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT7_22","070_7_22","MAT","7","22","22","והיה ביום ההוא יאמרו רבים אלי אדנינו אדנינו הלא בשמך נבאנו ובשמך גרשנו שדים ובשמך עשינו גבורות רבות׃ ");
INSERT INTO heb_vpl VALUES ("MT7_23","070_7_23","MAT","7","23","23","אז אענה בם לאמר מעולם לא ידעתי אתכם סורו ממני פעלי האון׃ ");
INSERT INTO heb_vpl VALUES ("MT7_24","070_7_24","MAT","7","24","24","לכן כל השמע את דברי אלה ועשה אתם אדמהו לאיש חכם אשר בנה את ביתו על הסלע׃ ");
INSERT INTO heb_vpl VALUES ("MT7_25","070_7_25","MAT","7","25","25","וירד הגשם וישטפו הנהרות וישבו הרוחות ויגעו בבית ההוא ולא נפל כי יסד על הסלע׃ ");
INSERT INTO heb_vpl VALUES ("MT7_26","070_7_26","MAT","7","26","26","וכל השמע את דברי אלה ולא יעשה אתם ידמה לאיש בער אשר בנה את ביתו על החול׃ ");
INSERT INTO heb_vpl VALUES ("MT7_27","070_7_27","MAT","7","27","27","וירד הגשם וישטפו הנהרות וישבו הרוחות ויפגעו בבית ההוא ויפל ותהי מפלתו גדולה׃ ");
INSERT INTO heb_vpl VALUES ("MT7_28","070_7_28","MAT","7","28","28","ויהי ככלות ישוע לדבר את הדברים האלה וישתומם המון העם על תורתו׃ ");
INSERT INTO heb_vpl VALUES ("MT7_29","070_7_29","MAT","7","29","29","כי היה מלמד אותם כבעל גבורה ולא כסופרים׃ ");
INSERT INTO heb_vpl VALUES ("MT8_1","070_8_1","MAT","8","1","1","וירד מן ההר וילך אחריו המון עם רב׃ ");
INSERT INTO heb_vpl VALUES ("MT8_2","070_8_2","MAT","8","2","2","והנה איש מצרע בא וישתחו לו ויאמר אדני אם תרצה תוכל לטהרני׃ ");
INSERT INTO heb_vpl VALUES ("MT8_3","070_8_3","MAT","8","3","3","וישלח ישוע את ידו ויגע בו ויאמר חפץ אנכי טהר ומיד נרפאה צרעתו׃ ");
INSERT INTO heb_vpl VALUES ("MT8_4","070_8_4","MAT","8","4","4","ויאמר אליו ישוע ראה פן תספר לאיש כי אם לך לך והראה אל הכהן והקרב את הקרבן אשר צוה משה לעדות להם׃ ");
INSERT INTO heb_vpl VALUES ("MT8_5","070_8_5","MAT","8","5","5","ויהי כבאו אל כפר נחום ויגש אליו שר מאה אחד ויתחנן לו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT8_6","070_8_6","MAT","8","6","6","אדני הנה נערי נפל למשכב בביתי והוא נכה אברים ומענה עד מאד׃ ");
INSERT INTO heb_vpl VALUES ("MT8_7","070_8_7","MAT","8","7","7","ויאמר ישוע אליו אבא וארפאהו׃ ");
INSERT INTO heb_vpl VALUES ("MT8_8","070_8_8","MAT","8","8","8","ויען שר המאה ויאמר אדני נקלתי מבאך בצל קורתי אך דבר נא רק דבר ונרפא נערי׃ ");
INSERT INTO heb_vpl VALUES ("MT8_9","070_8_9","MAT","8","9","9","כי אנכי איש נתון תחת השלטון וגם יש תחת ידי אנשי צבא ואמרתי לזה לך והלך ולזה בוא ובא ולעבדי עשה זאת ועשה׃ ");
INSERT INTO heb_vpl VALUES ("MT8_10","070_8_10","MAT","8","10","10","וישמע ישוע ויתמה ויאמר אל ההלכים אחריו אמן אמר אני לכם גם בישראל לא מצאתי אמונה גדולה כזאת׃ ");
INSERT INTO heb_vpl VALUES ("MT8_11","070_8_11","MAT","8","11","11","ואני אמר לכם רבים יבאו ממזרח וממערב ויסבו עם אברהם ויצחק ויעקב במלכות השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT8_12","070_8_12","MAT","8","12","12","אבל בני המלכות המה יגרשו אל החשך החיצון שם תהיה היללה וחרוק השנים׃ ");
INSERT INTO heb_vpl VALUES ("MT8_13","070_8_13","MAT","8","13","13","ויאמר ישוע אל שר המאה לך וכאמונתך כן יהיה לך וירפא נערו בשעה ההיא׃ ");
INSERT INTO heb_vpl VALUES ("MT8_14","070_8_14","MAT","8","14","14","ויבא ישוע ביתה פטרוס וירא את חמותו נפלת למשכב כי אחזתה הקדחת׃ ");
INSERT INTO heb_vpl VALUES ("MT8_15","070_8_15","MAT","8","15","15","ויגע בידה ותרף ממנה הקדחת ותקם ותשרתם׃ ");
INSERT INTO heb_vpl VALUES ("MT8_16","070_8_16","MAT","8","16","16","ויהי לעת ערב ויביאו אליו רבים אחוזי שדים ויגרש את הרוחות בדבר וירפא את כל החולים׃ ");
INSERT INTO heb_vpl VALUES ("MT8_17","070_8_17","MAT","8","17","17","למלאת את אשר דבר ישעיהו הנביא לאמר חלינו הוא נשא ומכאבינו סבלם׃ ");
INSERT INTO heb_vpl VALUES ("MT8_18","070_8_18","MAT","8","18","18","ויהי כראות ישוע המון עם רב סביבתיו ויצו לעבר משם אל עבר הים׃ ");
INSERT INTO heb_vpl VALUES ("MT8_19","070_8_19","MAT","8","19","19","ויגש אליו אחד הסופרים ויאמר אליו רבי אלכה אחריך אל כל אשר תלך׃ ");
INSERT INTO heb_vpl VALUES ("MT8_20","070_8_20","MAT","8","20","20","ויאמר אליו ישוע לשועלים יש חורי עפר ולעוף השמים קנים ובן האדם אין לו מקום להניח שם את ראשו׃ ");
INSERT INTO heb_vpl VALUES ("MT8_21","070_8_21","MAT","8","21","21","ואחר מן התלמידים אמר אליו אדני הניחה לי בראשונה ללכת ולקבר את אבי׃ ");
INSERT INTO heb_vpl VALUES ("MT8_22","070_8_22","MAT","8","22","22","ויאמר אליו ישוע לך אחרי והנח למתים לקבר את מתיהם׃ ");
INSERT INTO heb_vpl VALUES ("MT8_23","070_8_23","MAT","8","23","23","וירד אל האניה וירדו אתו תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("MT8_24","070_8_24","MAT","8","24","24","והנה סער גדול היה בים ותכסה האניה בגלים והוא ישן׃ ");
INSERT INTO heb_vpl VALUES ("MT8_25","070_8_25","MAT","8","25","25","ויגשו אליו תלמידיו ויעירו אותו לאמר הושיענו אדנינו אבדנו׃ ");
INSERT INTO heb_vpl VALUES ("MT8_26","070_8_26","MAT","8","26","26","ויאמר אליהם קטני האמונה למה זה יראתם ויקם ויגער ברוחות ובים ותהי דממה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("MT8_27","070_8_27","MAT","8","27","27","ויתמהו האנשים ויאמרו מי אפוא הוא אמר גם הרוחות והים לו ישמעון׃ ");
INSERT INTO heb_vpl VALUES ("MT8_28","070_8_28","MAT","8","28","28","ויהי כבאו אל עבר הים אל ארץ הגרגשים ויפגשוהו שני אנשים אחוזי שדים יצאים מבתי הקברות והמה רגונים מאד עד אשר לא יכל איש לעבר בדרך ההוא׃ ");
INSERT INTO heb_vpl VALUES ("MT8_29","070_8_29","MAT","8","29","29","והנה הם צעקים לאמר מה לנו ולך ישוע בן האלהים הבאת הלם לענותנו בלא עתנו׃ ");
INSERT INTO heb_vpl VALUES ("MT8_30","070_8_30","MAT","8","30","30","ועדר חזירים רבים היה שם במרעה הרחק מהם׃ ");
INSERT INTO heb_vpl VALUES ("MT8_31","070_8_31","MAT","8","31","31","ויתחננו אליו השדים לאמר אם תגרשנו שלחנו בעדר החזירים׃ ");
INSERT INTO heb_vpl VALUES ("MT8_32","070_8_32","MAT","8","32","32","ויאמר אליהם לכו לכם ויצאו ויבאו בעדר החזירים והנה השתער כל עדר החזירים מן המורד על הים וימותו במים׃ ");
INSERT INTO heb_vpl VALUES ("MT8_33","070_8_33","MAT","8","33","33","וינוסו הרעים ויבאו העירה ויגידו את הכל ואת אשר נעשה לאחוזי השדים׃ ");
INSERT INTO heb_vpl VALUES ("MT8_34","070_8_34","MAT","8","34","34","והנה כל העיר יצאה לקראת ישוע וכראותם אתו ויבקשו ממנו לעבר מגבולם׃ ");
INSERT INTO heb_vpl VALUES ("MT9_1","070_9_1","MAT","9","1","1","וירד באניה ויעבר ויבא אל עירו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_2","070_9_2","MAT","9","2","2","והנה הם מביאים אליו איש נכה אברים והוא משכב על המטה ויהי כראות ישוע את אמונתם ויאמר אל נכה האברים חזק בני נסלחו לך חטאתיך׃ ");
INSERT INTO heb_vpl VALUES ("MT9_3","070_9_3","MAT","9","3","3","והנה אנשים מן הסופרים אמרו בלבבם מגדף הוא׃ ");
INSERT INTO heb_vpl VALUES ("MT9_4","070_9_4","MAT","9","4","4","וירא ישוע את מחשבתם ויאמר למה תחשבו רעה בלבבכם׃ ");
INSERT INTO heb_vpl VALUES ("MT9_5","070_9_5","MAT","9","5","5","כי מה הנקל האמר נסלחו לך חטאתיך אם אמר קום התהלך׃ ");
INSERT INTO heb_vpl VALUES ("MT9_6","070_9_6","MAT","9","6","6","אך למען תדעון כי בן האדם יש לו השלטן בארץ לסלח חטאים ויאמר אל נכה האברים קום שא את מטתך ולך לך אל ביתך׃ ");
INSERT INTO heb_vpl VALUES ("MT9_7","070_9_7","MAT","9","7","7","ויקם וילך לביתו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_8","070_9_8","MAT","9","8","8","והמון העם כראותם זאת השתוממו וישבחו את האלהים אשר נתן שלטן כזה לבני אדם׃ ");
INSERT INTO heb_vpl VALUES ("MT9_9","070_9_9","MAT","9","9","9","ויהי בעבר ישוע משם וירא איש ישב בבית המכס ושמו מתי ויאמר אליו לכה אחרי ויקם וילך אחריך׃ ");
INSERT INTO heb_vpl VALUES ("MT9_10","070_9_10","MAT","9","10","10","ויהי בהסבו בביתו והנה מוכסים וחטאים רבים באו ויסבו עם ישוע ותלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_11","070_9_11","MAT","9","11","11","ויראו הפרושים ויאמרו אל תלמידיו מדוע עם המוכסים והחטאים אכל רבכם׃ ");
INSERT INTO heb_vpl VALUES ("MT9_12","070_9_12","MAT","9","12","12","וישמע זאת ישוע ויאמר אליהם החזקים אינם צריכים לרפא כי אם החולים׃ ");
INSERT INTO heb_vpl VALUES ("MT9_13","070_9_13","MAT","9","13","13","ואתם צאו ולמדו מה הוא חסד חפצתי ולא זבח כי לא באתי לקרא את הצדיקים כי אם את החטאים לתשובה׃ ");
INSERT INTO heb_vpl VALUES ("MT9_14","070_9_14","MAT","9","14","14","ויגשו אליו תלמידי יוחנן ויאמרו מדוע אנחנו והפרושים צמים הרבה ותלמידיך אינם צמים׃ ");
INSERT INTO heb_vpl VALUES ("MT9_15","070_9_15","MAT","9","15","15","ויאמר אליהם ישוע איך יוכלו בני החפה להתאבל בעוד החתן עמהם הנה ימים באים ולקח מאתם החתן ואז יצומו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_16","070_9_16","MAT","9","16","16","אין משים מטלית חדשה על שמלה בלה כי תנתק מלאתו מן השמלה ותרע הקריעה׃ ");
INSERT INTO heb_vpl VALUES ("MT9_17","070_9_17","MAT","9","17","17","ואין נותנים יין חדש בנאדות בלים פן יבקעו הנאדות והיין ישפך והנאדות יאבדו אבל נותנים את היין החדש בנאדות חדשים ושניהם יחדו ישמרו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_18","070_9_18","MAT","9","18","18","ויהי הוא מדבר אליהם את אלה והנה אחד השרים בא וישתחו לו ויאמר עתה זה מתה בתי בא נא ושים את ידך עליה ותחיה׃ ");
INSERT INTO heb_vpl VALUES ("MT9_19","070_9_19","MAT","9","19","19","ויקם ישוע וילך אחריו הוא ותלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_20","070_9_20","MAT","9","20","20","והנה אשה זבת דם שתים עשרה שנה נגשה מאחריו ותגע בציצת בגדו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_21","070_9_21","MAT","9","21","21","כי אמרה בלבה אך אם אגע בבגדו אושע׃ ");
INSERT INTO heb_vpl VALUES ("MT9_22","070_9_22","MAT","9","22","22","ויפן ישוע וירא אותה ויאמר חזקי בתי אמונתך הושיעה לך ותושע האשה מן השעה ההיא׃ ");
INSERT INTO heb_vpl VALUES ("MT9_23","070_9_23","MAT","9","23","23","ויבא ישוע אל בית השר וירא את המחללים בחלילים ואת העם ההומה ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT9_24","070_9_24","MAT","9","24","24","סורו מפה כי לא מתה הילדה אך ישנה היא וישחקו לו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_25","070_9_25","MAT","9","25","25","ויהי אחרי גרש העם ויבא הביתה ויאחז בידה ותקם הנערה׃ ");
INSERT INTO heb_vpl VALUES ("MT9_26","070_9_26","MAT","9","26","26","ותצא השמועה הזאת בכל הארץ ההיא׃ ");
INSERT INTO heb_vpl VALUES ("MT9_27","070_9_27","MAT","9","27","27","ויעבר ישוע משם וילכו אחריו שני אנשים עורים והמה צעקעם ואמרים חננו בן דוד׃ ");
INSERT INTO heb_vpl VALUES ("MT9_28","070_9_28","MAT","9","28","28","וכבואו הביתה נגשו אליו העורים ויאמר אליהם ישוע המאמינים אתם כי יש לאל ידי לעשות זאת ויאמרו אליו כן אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("MT9_29","070_9_29","MAT","9","29","29","ויגע בעיניהם ויאמר יעשה לכם כאמונתכם׃ ");
INSERT INTO heb_vpl VALUES ("MT9_30","070_9_30","MAT","9","30","30","ותפקחנה עיניהם ויגער בם ישוע ויאמר ראו פן יודע לאיש׃ ");
INSERT INTO heb_vpl VALUES ("MT9_31","070_9_31","MAT","9","31","31","והמה בצאתם השמיעו את שמעו בכל הארץ ההיא׃ ");
INSERT INTO heb_vpl VALUES ("MT9_32","070_9_32","MAT","9","32","32","המה יצאו והנה הביאו אליו איש אלם אחוז שד׃ ");
INSERT INTO heb_vpl VALUES ("MT9_33","070_9_33","MAT","9","33","33","וכאשר גרש השד וידבר האלם ויתמה המון האנשים ויאמרו מעולם לא נראתה כזאת בישראל׃ ");
INSERT INTO heb_vpl VALUES ("MT9_34","070_9_34","MAT","9","34","34","והפרושים אמרו על ידי שר השדים מגרש הוא את השדים׃ ");
INSERT INTO heb_vpl VALUES ("MT9_35","070_9_35","MAT","9","35","35","ויסב ישוע בכל הערים והכפרים וילמד בבתי כנסיותיהם ויבשר בשורת המלכות וירפא כל מחלה וכל מדוה בעם׃ ");
INSERT INTO heb_vpl VALUES ("MT9_36","070_9_36","MAT","9","36","36","ובראותו את ההמנים נכמרו רחמיו עליהם כי הם מתעלפים ונדחים כצאן אשר אין להם רעה׃ ");
INSERT INTO heb_vpl VALUES ("MT9_37","070_9_37","MAT","9","37","37","אז ידבר לתלמדידיו ויאמר רב הקציר והפעלים מעטים׃ ");
INSERT INTO heb_vpl VALUES ("MT9_38","070_9_38","MAT","9","38","38","לכן התחננו אל בעל הקציר לשלח פעלים לקצירו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_1","070_10_1","MAT","10","1","1","ויקרא אליו את שנים עשר תלמידיו ויתן להם שלטן על רוחות הטמאה לגרשם ולרפוא כל חלי וכל מדוה׃ ");
INSERT INTO heb_vpl VALUES ("MT10_2","070_10_2","MAT","10","2","2","ואלה שמות שנים עשר השליחים הראשון שמעון הנקרא פטרוס ואנדרי אחיו יעקב בן זבדי ויוחנן אחיו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_3","070_10_3","MAT","10","3","3","פילפוס ובר תלמי תומא ומתי המוכס יעקב בן חלפי ולבי המכנה תדי׃ ");
INSERT INTO heb_vpl VALUES ("MT10_4","070_10_4","MAT","10","4","4","שמעון הקני ויהודה איש קריות אשר גם מסר אתו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_5","070_10_5","MAT","10","5","5","את שנים העשר האלה שלח ישוע ויצו אתם לאמר אל דרך הגוים אל תלכו ואל עיר השמרונים אל תבאו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_6","070_10_6","MAT","10","6","6","כי אם לכו אל הצאן האבדות לבית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MT10_7","070_10_7","MAT","10","7","7","ובלכתכם קראו לאמר למכות השמים קרבה לבוא׃ ");
INSERT INTO heb_vpl VALUES ("MT10_8","070_10_8","MAT","10","8","8","רפאו את החולים טהרו את המצרעים הקימו את המתים ואת השדים גרשו חנם לקחתם חנם תתנו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_9","070_10_9","MAT","10","9","9","לא תקחו זהב ולא כסף ולא נחשת בחגוריכם׃ ");
INSERT INTO heb_vpl VALUES ("MT10_10","070_10_10","MAT","10","10","10","ולא תרמיל לדרך ולא שתי כתנות ולא נעלים ולא מטה כי שוה הפעל די מחיתו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_11","070_10_11","MAT","10","11","11","וכל עיר וכפר אשר תבאו שמה דרשו מי הוא הראוי לזה בתוכה ושם שבו עד כי תצאו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_12","070_10_12","MAT","10","12","12","ובבואכם אל הבית שאלו לו לשלום׃ ");
INSERT INTO heb_vpl VALUES ("MT10_13","070_10_13","MAT","10","13","13","והיה אם ראוי הבית יבוא עליו שלומכם ואם איננו ראוי שלומכם אליכם ישוב׃ ");
INSERT INTO heb_vpl VALUES ("MT10_14","070_10_14","MAT","10","14","14","וכל אשר לא יקבל אתכם ולא ישמע לדבריכם צאו לכם מן הבית ההוא ומן העיר ההיא ונערו את עפר רגליכם׃ ");
INSERT INTO heb_vpl VALUES ("MT10_15","070_10_15","MAT","10","15","15","אמן אמר אני לכם כי יקל לארץ סדום ועמרה ביום הדין מן העיר ההיא׃ ");
INSERT INTO heb_vpl VALUES ("MT10_16","070_10_16","MAT","10","16","16","הנני שלח אתכם ככבשים בין הזאבים לכן היו ערומים כנחשים ותמימים כיונים׃ ");
INSERT INTO heb_vpl VALUES ("MT10_17","070_10_17","MAT","10","17","17","והשמרו לכם מבני האדם כי ימסרו אתכם לסנהדריות ויכו אתכם בשוטים בבתי כנסיותיהם׃ ");
INSERT INTO heb_vpl VALUES ("MT10_18","070_10_18","MAT","10","18","18","ולפני משלים ומלכים תובאו למעני לעדות להם ולגוים׃ ");
INSERT INTO heb_vpl VALUES ("MT10_19","070_10_19","MAT","10","19","19","וכי ימסרו אתכם אל תדאגו איך ומה תדברו כי ינתן לכם בשעה ההיא את אשר תדברו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_20","070_10_20","MAT","10","20","20","כי לא אתם הם המדברים כי רוח אביכם הוא המדבר בפיכם׃ ");
INSERT INTO heb_vpl VALUES ("MT10_21","070_10_21","MAT","10","21","21","והיה אח ימסר את אחיו למות ואב ימסר את בנו וקמו בנים באבותם וימיתו אותם׃ ");
INSERT INTO heb_vpl VALUES ("MT10_22","070_10_22","MAT","10","22","22","והייתם שנואים לכל אדם למען שמי והמחכה עד עת קץ הוא יושע׃ ");
INSERT INTO heb_vpl VALUES ("MT10_23","070_10_23","MAT","10","23","23","ואם ירדפו אתכם בעיר אחת נוסו לעיר אחרת כי אמן אמר אני לכם לא תכלו לעבר ערי ישראל עד כי יבוא בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT10_24","070_10_24","MAT","10","24","24","אין תלמיד עלה על רבו ועבד על אדניו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_25","070_10_25","MAT","10","25","25","דיו לתלמיד להיות כרבו ולעבד להיות כאדניו אם לבעל הבית קראו בעל זבוב אף לאנשי ביתו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_26","070_10_26","MAT","10","26","26","על כן לא תיראום כי אין דבר מכסה אשר לא יגלה ואין נעלם אשר לא יודע׃ ");
INSERT INTO heb_vpl VALUES ("MT10_27","070_10_27","MAT","10","27","27","את אשר אני אמר לכם בחשך דברו באור ואשר ילחש לאזניכם השמיעו על הגגות׃ ");
INSERT INTO heb_vpl VALUES ("MT10_28","070_10_28","MAT","10","28","28","ואל תיראי מן ההרגים את הגוף ואת הנפש לא יוכלו להרג אך תיראו את אשר יוכל לאבד גם את הנפש גם את הגוף בגיהנם׃ ");
INSERT INTO heb_vpl VALUES ("MT10_29","070_10_29","MAT","10","29","29","הלא תמכרנה שתי צפרים באסר ואחת מהנה לא תפול ארצה מבלעדי אביכם׃ ");
INSERT INTO heb_vpl VALUES ("MT10_30","070_10_30","MAT","10","30","30","ואתם גם שערות ראשכם נמנות כלן׃ ");
INSERT INTO heb_vpl VALUES ("MT10_31","070_10_31","MAT","10","31","31","לכן אל תיראו הנכם יקרים מצפרים רבות׃ ");
INSERT INTO heb_vpl VALUES ("MT10_32","070_10_32","MAT","10","32","32","הן כל אשר יודה בי לפני האדם אודה בו גם אני לפני אבי שבשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT10_33","070_10_33","MAT","10","33","33","ואשר יכחש בי לפני האדם אכחש בו גם אני לפני אבי שבשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT10_34","070_10_34","MAT","10","34","34","אל תחשבו כי באתי להטיל שלום בארץ לא באתי להטיל שלום כי אם חרב׃ ");
INSERT INTO heb_vpl VALUES ("MT10_35","070_10_35","MAT","10","35","35","כי באתי להפריד איש מאביו ובת מאמה וכלה מחמותה׃ ");
INSERT INTO heb_vpl VALUES ("MT10_36","070_10_36","MAT","10","36","36","ואיבי איש אנשי ביתו׃ ");
INSERT INTO heb_vpl VALUES ("MT10_37","070_10_37","MAT","10","37","37","האהב את אביו ואת אמו יותר ממני איננו כדי לי והאהב את בנו ובתו יותר ממני איננו כדי לי׃ ");
INSERT INTO heb_vpl VALUES ("MT10_38","070_10_38","MAT","10","38","38","ואשר לא יקח את צלבו והלך אחרי איננו כדי לי׃ ");
INSERT INTO heb_vpl VALUES ("MT10_39","070_10_39","MAT","10","39","39","המצא את נפשו יאבדנה והמאבד את נפשו למעני הוא ימצאנה׃ ");
INSERT INTO heb_vpl VALUES ("MT10_40","070_10_40","MAT","10","40","40","המקבל אתכם אותי הוא מקבל והמקבל אותי הוא מקבל את אשר שלחני׃ ");
INSERT INTO heb_vpl VALUES ("MT10_41","070_10_41","MAT","10","41","41","המקבל נביא לשם נביא שכר נביא יקח והמקבל צדיק לשם צדיק שכר צדיק יקח׃ ");
INSERT INTO heb_vpl VALUES ("MT10_42","070_10_42","MAT","10","42","42","והמשקה את אחד הקטנים האלה רק כוס מים קרים לשם תלמיד אמן אמר אני לכם כי לא יאבד שכרו׃ ");
INSERT INTO heb_vpl VALUES ("MT11_1","070_11_1","MAT","11","1","1","ויהי ככלות ישוע לצות את שנים עשר תלמידיו וילך משם ללמד ולקרא בעריהם׃ ");
INSERT INTO heb_vpl VALUES ("MT11_2","070_11_2","MAT","11","2","2","ויוחנן שמע בבית הסהר את מעשי המשיח וישלח שנים מתלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("MT11_3","070_11_3","MAT","11","3","3","ויאמר אליו האתה הוא הבא אם נחכה לאחר׃ ");
INSERT INTO heb_vpl VALUES ("MT11_4","070_11_4","MAT","11","4","4","ויען ישוע ויאמר להם לכו הגידו ליוחנן את אשר שמעתם וראיתם׃ ");
INSERT INTO heb_vpl VALUES ("MT11_5","070_11_5","MAT","11","5","5","עורים ראים ופסחים מתהלכים מצרעים מטהרים וחרשים שומעין ומתים קמים ועניים מתבשרי ישועה הם׃ ");
INSERT INTO heb_vpl VALUES ("MT11_6","070_11_6","MAT","11","6","6","ואשרי אשר לא יכשל בי׃ ");
INSERT INTO heb_vpl VALUES ("MT11_7","070_11_7","MAT","11","7","7","המה הלכו להם וישוע החל לדבר אל המון העם על אדות יוחנן ויאמר מה זה יצאתם המדברה לראות הקנה אשר ינוע ברוח׃ ");
INSERT INTO heb_vpl VALUES ("MT11_8","070_11_8","MAT","11","8","8","ואם לא מה זה יצאתם לראות האיש לבוש בגדי עדנים הנה הלבשים עדנים בבתי המלכים המה׃ ");
INSERT INTO heb_vpl VALUES ("MT11_9","070_11_9","MAT","11","9","9","ואם לא מה זה יצאתם לראות אם איש נביא הן אני אמר לכם כי גם גדול הוא מנביא׃ ");
INSERT INTO heb_vpl VALUES ("MT11_10","070_11_10","MAT","11","10","10","כי זה הוא אשר כתוב עליו הנני שלח מלאכי לפניך ופנה רדכך לפניך׃ ");
INSERT INTO heb_vpl VALUES ("MT11_11","070_11_11","MAT","11","11","11","אמן אמר אני לכם לא קם בילודי אשה איש גדול מיוחנן המטביל אך הקטן במלכות השמים גדול הוא ממנו׃ ");
INSERT INTO heb_vpl VALUES ("MT11_12","070_11_12","MAT","11","12","12","ומימי יוחנן המטביל עד הנה מלכות השמים נתפשה בחזקה והמתחזקים יחטפוה׃ ");
INSERT INTO heb_vpl VALUES ("MT11_13","070_11_13","MAT","11","13","13","כי כל הנביאים והתורה עדי יוחנן נבאו׃ ");
INSERT INTO heb_vpl VALUES ("MT11_14","070_11_14","MAT","11","14","14","ואם תרצו לקבל הנה הוא אליה העתיד לבוא׃ ");
INSERT INTO heb_vpl VALUES ("MT11_15","070_11_15","MAT","11","15","15","מי אשר אזנים לו לשמע ישמע׃ ");
INSERT INTO heb_vpl VALUES ("MT11_16","070_11_16","MAT","11","16","16","ואל מי אדמה את הדור הזה דומה הוא לילדים הישבים בשוקים וקראים לחבריהם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT11_17","070_11_17","MAT","11","17","17","חללנו לכם בחלילים ולא רקדתם קוננו לכם קינה ולא ספדתם׃ ");
INSERT INTO heb_vpl VALUES ("MT11_18","070_11_18","MAT","11","18","18","כי בא יוחנן לא אכל ולא שתה ויאמרו שד בו׃ ");
INSERT INTO heb_vpl VALUES ("MT11_19","070_11_19","MAT","11","19","19","ויבא בן האדם והוא אכל ושתה ויאמרו הנה איש זולל וסבא ואהב מוכסים וחטאים ונצדקה החכמה מאת בניה׃ ");
INSERT INTO heb_vpl VALUES ("MT11_20","070_11_20","MAT","11","20","20","אז החל לגער בערים אשר רב גבורותיו נעשו בתוכן ולא שבו׃ ");
INSERT INTO heb_vpl VALUES ("MT11_21","070_11_21","MAT","11","21","21","אוי לך כורזין אוי לך בית צידה כי הגבורות אשר נעשו בקרבכן לו בצור ובצידון נעשו הלא כבר שבו בשק ואפר׃ ");
INSERT INTO heb_vpl VALUES ("MT11_22","070_11_22","MAT","11","22","22","אבל אני אמר לכם כי ביום הדין יקל לצור וצידון יותר מכם׃ ");
INSERT INTO heb_vpl VALUES ("MT11_23","070_11_23","MAT","11","23","23","ואת כפר נחום המרוממה עד השמים עד שאול תורדי כי הגבורות אשר נעשו בתוכך לו בסדום נעשו כי עתה עמדה על תלה עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("MT11_24","070_11_24","MAT","11","24","24","אבל אני אמר לכם כי ביום הדין יקל לאדמת סדום ממך׃ ");
INSERT INTO heb_vpl VALUES ("MT11_25","070_11_25","MAT","11","25","25","בעת ההיא ענה ישוע ואמר אודך אבי אדון השמים והארץ כי הסתרת את אלה מן החכמים והנבונים וגליתם לעוללים׃ ");
INSERT INTO heb_vpl VALUES ("MT11_26","070_11_26","MAT","11","26","26","הן אבי כי כן היה רצון לפניך׃ ");
INSERT INTO heb_vpl VALUES ("MT11_27","070_11_27","MAT","11","27","27","הכל נמסר לי מאת אבי ואין מכיר את הבן בלתי האב ואין מכיר את האב בלתי הבן ואשר יחפץ הבן לגלותו לו׃ ");
INSERT INTO heb_vpl VALUES ("MT11_28","070_11_28","MAT","11","28","28","לכו אלי כל העמלים והטעונים ואני אניח לכם׃ ");
INSERT INTO heb_vpl VALUES ("MT11_29","070_11_29","MAT","11","29","29","קבלו עליכם את עלי ולמדו ממני כי ענו ושפל רוח אנכי ותמצאו מרגוע לנפשתיכם׃ ");
INSERT INTO heb_vpl VALUES ("MT11_30","070_11_30","MAT","11","30","30","כי עלי נעים הוא וקל משאי׃ ");
INSERT INTO heb_vpl VALUES ("MT12_1","070_12_1","MAT","12","1","1","בעת ההיא עבר ישוע בין הקמה ביום השבת ותלמידיו רעבו ויחלו לקטף מלילת ויאכלו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_2","070_12_2","MAT","12","2","2","ויראו הפרושים ויאמרו לו הנה תלמידיך עשים את אשר אסור לעשות בשבת׃ ");
INSERT INTO heb_vpl VALUES ("MT12_3","070_12_3","MAT","12","3","3","ויאמר אליהם הלא קראתם את אשר עשה דוד בהיתו רעב הוא והאנשים אשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_4","070_12_4","MAT","12","4","4","כי בא אל בית האלהים ויאכל את לחם הפנים אשר איננו מתר לו ולאנשיו לאכלה רק לכהנים לבדם׃ ");
INSERT INTO heb_vpl VALUES ("MT12_5","070_12_5","MAT","12","5","5","או הלא קראתם בתורה כי בשבתות יחללו הכהנים את השבת במקדש ואין להם עון׃ ");
INSERT INTO heb_vpl VALUES ("MT12_6","070_12_6","MAT","12","6","6","אבל אני אמר לכם כי יש פה גדול מן המקדש׃ ");
INSERT INTO heb_vpl VALUES ("MT12_7","070_12_7","MAT","12","7","7","ולו ידעתם מה הוא חסד חפצתי ולא זבח לא הרשעתם את הנקים׃ ");
INSERT INTO heb_vpl VALUES ("MT12_8","070_12_8","MAT","12","8","8","כי בן האדם הוא גם אדון השבת׃ ");
INSERT INTO heb_vpl VALUES ("MT12_9","070_12_9","MAT","12","9","9","ויעבר משם אל בית כנסתם׃ ");
INSERT INTO heb_vpl VALUES ("MT12_10","070_12_10","MAT","12","10","10","והנה שם איש אשר ידו יבשה וישאלוהו לאמר המתר לרפא בשבת למען ימצאו עליו שטנה׃ ");
INSERT INTO heb_vpl VALUES ("MT12_11","070_12_11","MAT","12","11","11","ויאמר אליהם מי האיש בכם אשר לו כבש אחד ונפל בבור בשבת ולא יחזיק בו ויעלנו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_12","070_12_12","MAT","12","12","12","ומה יקר אדם מן הכבש לכן מתר להיטיב בשבת׃ ");
INSERT INTO heb_vpl VALUES ("MT12_13","070_12_13","MAT","12","13","13","ויאמר אל האיש פשט את ידך ויפשט אתה ותרפא ותשב כידו האחרת׃ ");
INSERT INTO heb_vpl VALUES ("MT12_14","070_12_14","MAT","12","14","14","ויצא הפרושים ויתיעצו עליו לאבדו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_15","070_12_15","MAT","12","15","15","וידע ישוע ויסר משם וילך אחריו המון עם רב וירפאם כלם׃ ");
INSERT INTO heb_vpl VALUES ("MT12_16","070_12_16","MAT","12","16","16","ויצו אתם בגערה שלא יגלהו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_17","070_12_17","MAT","12","17","17","למלאת את אשר דבר ישעיהו הנביא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT12_18","070_12_18","MAT","12","18","18","הן עבדי בחרתי בו ידידי רצתה נפשי נתתי רוחי עליו ומשפט לגוים יוציא׃ ");
INSERT INTO heb_vpl VALUES ("MT12_19","070_12_19","MAT","12","19","19","לא יצעק ולא ישא ולא ישמע בחוץ קולו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_20","070_12_20","MAT","12","20","20","קנה רצוץ לא ישבור ופשתה כהה לא יכבנה עד יוציא לנצח משפט׃ ");
INSERT INTO heb_vpl VALUES ("MT12_21","070_12_21","MAT","12","21","21","ולשמו גוים ייחלו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_22","070_12_22","MAT","12","22","22","אז הובא אליו איש עור ואלם אשר אחזו שד וירפאהו וידבר האלם וגם ראה׃ ");
INSERT INTO heb_vpl VALUES ("MT12_23","070_12_23","MAT","12","23","23","וישתוממו כל המון העם ויאמרו הכי זה הוא בן דוד׃ ");
INSERT INTO heb_vpl VALUES ("MT12_24","070_12_24","MAT","12","24","24","והפרושים כשמעם זאת אמרו זה איננו מגרש את השדים כי אם על ידי בעל זבוב שר השדים׃ ");
INSERT INTO heb_vpl VALUES ("MT12_25","070_12_25","MAT","12","25","25","וישוע ידע את מחשבותם ויאמר אליהם כל ממלכה הנחלקה על עצמה תחרב וכל עיר ובית הנחלקים על עצמם לא יכונו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_26","070_12_26","MAT","12","26","26","והשטן אם יגרש את השטן נחלק על עצמו ואיככה תכון ממלכתו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_27","070_12_27","MAT","12","27","27","ואם אני מגרש את השדים בבעל זבוב בניכם במי הם מגרשים אתם על כן המה יהיו שפטיכם׃ ");
INSERT INTO heb_vpl VALUES ("MT12_28","070_12_28","MAT","12","28","28","אך אם ברוח אלהים אני מגרש את השדים הנה הגיעה אליכם מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("MT12_29","070_12_29","MAT","12","29","29","או איך יוכל איש לבוא לבית הגבור ולגזל את כליו אם לא יאסר בראשונה את הגבור ואחר ישסה את ביתו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_30","070_12_30","MAT","12","30","30","כל אשר איננו אתי הוא לנגדי ואשר איננו מכנס אתי הוא מפזר׃ ");
INSERT INTO heb_vpl VALUES ("MT12_31","070_12_31","MAT","12","31","31","על כן אני אמר לכם כל חטא וגדוף יסלח לאדם אך גדוף הרוח לא יסלח לאדם׃ ");
INSERT INTO heb_vpl VALUES ("MT12_32","070_12_32","MAT","12","32","32","וכל אשר ידבר דבר חרפה על בן האדם יסלח לו והמחרף את רוח הקדש לא יסלח לו לא בעולם הזה ולא בעולם הבא׃ ");
INSERT INTO heb_vpl VALUES ("MT12_33","070_12_33","MAT","12","33","33","או עשו את העץ טוב ופריו טוב או עשו את העץ משחת ופריו משחת כי בפריו נכר העץ׃ ");
INSERT INTO heb_vpl VALUES ("MT12_34","070_12_34","MAT","12","34","34","ילדי הצפעונים איכה תוכלו למלל טוב ואתם רעים כי משפעת הלב ימלל הפה׃ ");
INSERT INTO heb_vpl VALUES ("MT12_35","070_12_35","MAT","12","35","35","האיש הטוב מאוצר לבו הטוב מוציא את הטוב והאיש הרע מאוצר הרע מוציא רע׃ ");
INSERT INTO heb_vpl VALUES ("MT12_36","070_12_36","MAT","12","36","36","ואני אמר לכם כל מלה בטלה אשר ידברו בני האדם יתנו עליה חשבון ביום הדין׃ ");
INSERT INTO heb_vpl VALUES ("MT12_37","070_12_37","MAT","12","37","37","כי מדבריך תצדק ומדבריך תחיב׃ ");
INSERT INTO heb_vpl VALUES ("MT12_38","070_12_38","MAT","12","38","38","ויענו מן הסופרים והפרושים ויאמרו רבי חפצנו לראות אות מידך׃ ");
INSERT INTO heb_vpl VALUES ("MT12_39","070_12_39","MAT","12","39","39","ויען ויאמר אליהם דור רע ומנאף מבקש לו אות ואות לא ינתן לו בלתי אם אות יונה הנביא׃ ");
INSERT INTO heb_vpl VALUES ("MT12_40","070_12_40","MAT","12","40","40","כי כאשר היה יונה במעי הדג שלשה ימים ושלשה לילות כן יהיה בן האדם בלב האדמה שלשה ימים ושלשה לילות׃ ");
INSERT INTO heb_vpl VALUES ("MT12_41","070_12_41","MAT","12","41","41","אנשי נינוה יקומו במשפט עם הדור הזה וירשיעוהו כי הם שבו בקריאת יונה והנה פה גדול מיונה׃ ");
INSERT INTO heb_vpl VALUES ("MT12_42","070_12_42","MAT","12","42","42","מלכת תימן תקום במשפט עם הדור הזה ותרשיענו כי באה מקצות הארץ לשמע את חכמה שלמה והנה פה גדול משלמה׃ ");
INSERT INTO heb_vpl VALUES ("MT12_43","070_12_43","MAT","12","43","43","והרוח הטמאה אחרי צאתה מן האדם תשטט במקמות ציה לבקש לה מנוחה ולא תמצאנה׃ ");
INSERT INTO heb_vpl VALUES ("MT12_44","070_12_44","MAT","12","44","44","אז תאמר אשובה אל ביתי אשר יצאתי משם ובאה ומצאה אתו מפנה ומטאטא ומהדר׃ ");
INSERT INTO heb_vpl VALUES ("MT12_45","070_12_45","MAT","12","45","45","ואחר תלך ולקחה אליה שבע רוחות אחרות רעות ממנה ובאו ושכנו שם והיתה אחרית האדם ההוא רעה מראשיתו כן יהיה גם לדור הרע הזה׃ ");
INSERT INTO heb_vpl VALUES ("MT12_46","070_12_46","MAT","12","46","46","עודנו מדבר אל המון העם והנה אמו ואחיו עמדו בחוץ מבקשים לדבר אתו׃ ");
INSERT INTO heb_vpl VALUES ("MT12_47","070_12_47","MAT","12","47","47","ויגד אליו הנה אמך ואחיך עמדים בחוץ ומבקשים לדבר אתך׃ ");
INSERT INTO heb_vpl VALUES ("MT12_48","070_12_48","MAT","12","48","48","ויען ויאמר אל האיש המגיד לו מי היא אמי ומי הם אחי׃ ");
INSERT INTO heb_vpl VALUES ("MT12_49","070_12_49","MAT","12","49","49","ויט ידו על תלמידיו ויאמר הנה אמי ואחי׃ ");
INSERT INTO heb_vpl VALUES ("MT12_50","070_12_50","MAT","12","50","50","כי כל אשר יעשה רצון אבי שבשמים הוא אחי ואחותי ואמי׃ ");
INSERT INTO heb_vpl VALUES ("MT13_1","070_13_1","MAT","13","1","1","ויהי ביום ההוא ויצא ישוע מן הבית וישב על הים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_2","070_13_2","MAT","13","2","2","ויקהלו אליו המון עם רב וירד אל האניה וישב בה וכל העם עמדים על שפת הים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_3","070_13_3","MAT","13","3","3","וירב לדבר אליהם במשלים לאמר הנה הזורע יצא לזרע׃ ");
INSERT INTO heb_vpl VALUES ("MT13_4","070_13_4","MAT","13","4","4","ובזרעו נפל מן הזרע על יד הדרך ויבא העוף ויאכלהו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_5","070_13_5","MAT","13","5","5","ויש אשר נפל על מקמות סלע אשר אין לו שם אדמה הרבה וימהר לצמח כי לא היה לו עמק אדמה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_6","070_13_6","MAT","13","6","6","ויהי כזרח השמש ויצרב וייבש כי לא היה לו שרש׃ ");
INSERT INTO heb_vpl VALUES ("MT13_7","070_13_7","MAT","13","7","7","ויש אשר נפל בין הקצים ויעלו הקצים וימעכהו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_8","070_13_8","MAT","13","8","8","ויש אשר נפל על האדמה הטובה ויתן פרי זה מאה שערים וזה ששים וזה שלשים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_9","070_13_9","MAT","13","9","9","מי אשר אזנים לו לשמע ישמע׃ ");
INSERT INTO heb_vpl VALUES ("MT13_10","070_13_10","MAT","13","10","10","ויגשו אליו התלמידים ויאמרו למה זה במשלים תדבר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("MT13_11","070_13_11","MAT","13","11","11","ויען ויאמר כי לכם נתן לדעת את סודות מלכות השמים ולהם לא נתן׃ ");
INSERT INTO heb_vpl VALUES ("MT13_12","070_13_12","MAT","13","12","12","כי מי שיש לו נתן ינתן לו ויעדיף ומי שאין לו גם את אשר יש לו יקח ממנו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_13","070_13_13","MAT","13","13","13","על כן במשלים אדבר אליהם כי בראתם לא יראו ובשמעם לא ישמעו אף לא יבינו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_14","070_13_14","MAT","13","14","14","ותקים בהם נבואת ישעיהו האמרת שמעו שמוע ואל תבינו וראו ראו ואל תדעו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_15","070_13_15","MAT","13","15","15","כי השמן לב העם הזה ואזניו הכבד ועיניו השע פן יראה בעיניו ובאזניו ישמע ולבבו יבין ושב ורפא לו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_16","070_13_16","MAT","13","16","16","ואתם אשרי עיניכם כי תראינה ואזניכם כי תשמענה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_17","070_13_17","MAT","13","17","17","כי אמן אמר אני לכם נביאים וצדיקים רבים נכספו לראת את אשר אתם ראים ולא ראוהו ולשמע את אשר אתם שמעים ולא שמעוהו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_18","070_13_18","MAT","13","18","18","לכן אתם שמעו נא את משל הזורע׃ ");
INSERT INTO heb_vpl VALUES ("MT13_19","070_13_19","MAT","13","19","19","כל איש שמע את דבר המלכות ולא יבינהו ובא הרע וחטף את הזרוע בלבבו הוא הנזרע על יד הדרך׃ ");
INSERT INTO heb_vpl VALUES ("MT13_20","070_13_20","MAT","13","20","20","והנזרע על הסלע הוא השמע את הדבר וימהר ויקחנו בשמחה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_21","070_13_21","MAT","13","21","21","אך אין לו שרש תחתיו ורק לשעה יעמד ובהיות צרה ורדיפה על אדות הדבר מיד נכשל׃ ");
INSERT INTO heb_vpl VALUES ("MT13_22","070_13_22","MAT","13","22","22","והנזרע בין הקצים הוא השמע את הדבר ודאגת העולם הזה ומרמת העשר ימעכו את הדבר ופרי לא יהיה לו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_23","070_13_23","MAT","13","23","23","והנזרע על האדמה הטובה הוא השמע את הדבר ומבין אתו אף יעשה פרי ונתן זה מאה שערים וזה ששים וזה שלשים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_24","070_13_24","MAT","13","24","24","וישם לפניהם משל אחר לאמר מלכות השמים דומה לאיש אשר זרע זרע טוב בשדהו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_25","070_13_25","MAT","13","25","25","ויהי בנפל תרדמה על האנשים ויבא איבו ויזרע זונין בתוך החטים וילך לו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_26","070_13_26","MAT","13","26","26","וכאשר פרח הדשא ויעש פרי ויראו גם הזונין׃ ");
INSERT INTO heb_vpl VALUES ("MT13_27","070_13_27","MAT","13","27","27","ויגשו עבדי בעל הבית ויאמרו אליו אדנינו הלא זרע טוב זרעת בשדך ומאין לו הזונין׃ ");
INSERT INTO heb_vpl VALUES ("MT13_28","070_13_28","MAT","13","28","28","ויאמר להם איש איב עשה זאת ויאמרו אליו העבדים היש את נפשך כי נלך ונלקט אתם׃ ");
INSERT INTO heb_vpl VALUES ("MT13_29","070_13_29","MAT","13","29","29","ויאמר לא פן בלקטכם את הזונין תשרשו גם את החטים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_30","070_13_30","MAT","13","30","30","הניחו אתם ויגדלו שניהם יחד עד הקציר והיה בעת הקציר אמר לקוצרים לקטו בראשונה את הזונין ואגדו אתם אגדות לשרפם ואת החטים אספו לאוצרי׃ ");
INSERT INTO heb_vpl VALUES ("MT13_31","070_13_31","MAT","13","31","31","וישם לפניהם משל אחר לאמר מלכות השמים דומה לגרגר של חרדל אשר לקחו איש ויזרעהו בשדהו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_32","070_13_32","MAT","13","32","32","והוא קטן מכל הזרועים וכאשר צמח גדול הוא מן הירקות והיה לעץ עד אשר יבאו עוף השמים וקננו בענפיו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_33","070_13_33","MAT","13","33","33","וישא עוד משלו ויאמר מלכות השמים דומה לשאר אשר לקחתו אשה ותטמנהו בשלש סאים קמח עד כי יחמץ כלו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_34","070_13_34","MAT","13","34","34","כל זאת דבר ישוע במשלים אל המון העם ובבלי משל לא דבר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("MT13_35","070_13_35","MAT","13","35","35","למלאת את אשר דבר הנביא לאמר אפתחה במשל פי אביעה חידות מני קדם׃ ");
INSERT INTO heb_vpl VALUES ("MT13_36","070_13_36","MAT","13","36","36","אז שלח ישוע את המון העם ויבא הביתה ויגשו אליו תלמידיו ויאמרו באר נא לנו את משל זוני השדה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_37","070_13_37","MAT","13","37","37","ויען ויאמר אליהם הזורע את הזרע הטוב הוא בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT13_38","070_13_38","MAT","13","38","38","והשדה הוא העולם והזרע הטוב בני המלכות הם והזונין בני הרע המה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_39","070_13_39","MAT","13","39","39","והאיב אשר זרעם הוא השטן והקציר הוא קץ העולם והקצרים הם המלאכים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_40","070_13_40","MAT","13","40","40","והנה כאשר ילקטו הזונין ונשרפו באש כן יהיה בקץ העולם הזה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_41","070_13_41","MAT","13","41","41","בן האדם ישלח את מלאכיו ולקטו ממלכותו את כל המכשלות ואת כל פעלי האון׃ ");
INSERT INTO heb_vpl VALUES ("MT13_42","070_13_42","MAT","13","42","42","והשליכו אתם אל תנור האש שם תהיה היללה וחרק השנים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_43","070_13_43","MAT","13","43","43","אז יזהירו הצדיקים כשמש במלכות אביהם מי אשר אזנים לו לשמע ישמע׃ ");
INSERT INTO heb_vpl VALUES ("MT13_44","070_13_44","MAT","13","44","44","עוד דומה מלכות השמים לאוצר טמון בשדה אשר מצאו איש ויטמנהו ובשמחתו ילך ומכר את כל אשר לו וקנה את השדה ההוא׃ ");
INSERT INTO heb_vpl VALUES ("MT13_45","070_13_45","MAT","13","45","45","עוד דומה מלכות השמים לסחר המבקש מרגליות טבות׃ ");
INSERT INTO heb_vpl VALUES ("MT13_46","070_13_46","MAT","13","46","46","וכאשר מצא מרגלית אחת יקרה מאד הלך לו וימכר את כל אשר לו ויקן אתה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_47","070_13_47","MAT","13","47","47","עוד דומה מלכות השמים למכמרת אשר הורדה לים ומינים שונים יאספו לתוכה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_48","070_13_48","MAT","13","48","48","וכאשר נמלאה העלו אתה אל שפת הים וישבו וילקטו את המינים הטובים לתוך הכלים ואת המשחתים השליכו חוצה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_49","070_13_49","MAT","13","49","49","כן יהיה בקץ העולם יצאו המלאכים והבדילו את הרשעים מתוך הצדיקים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_50","070_13_50","MAT","13","50","50","והשליכום אל תנור האש שם תהיה היללה וחרק השנים׃ ");
INSERT INTO heb_vpl VALUES ("MT13_51","070_13_51","MAT","13","51","51","ויאמר אליהם ישוע האתם הבינותם את כל זאת ויאמרו אליו כן אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_52","070_13_52","MAT","13","52","52","ויאמר אליהם על כן כל סופר המלמד למלכות השמים דומה לאיש בעל הבית המוציא מאוצרו חדשות וישנות׃ ");
INSERT INTO heb_vpl VALUES ("MT13_53","070_13_53","MAT","13","53","53","ויהי ככלות ישוע את המשלים האלה ויעבר משם׃ ");
INSERT INTO heb_vpl VALUES ("MT13_54","070_13_54","MAT","13","54","54","ויבא לארצו וילמד אתם בבית כנסתם עד כי השתוממו ויאמרו מאין לזה החכמה הזאת והגבורות׃ ");
INSERT INTO heb_vpl VALUES ("MT13_55","070_13_55","MAT","13","55","55","הלא זה הוא בן החרש הלא אמו שמה מרים ואחיו יעקב ויוסי ושמעון ויהודה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_56","070_13_56","MAT","13","56","56","ואחיותיו הלא כלן אתנו הן ומאין איפוא לו כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("MT13_57","070_13_57","MAT","13","57","57","ויהי להם למכשול ויאמר ישוע אליהם אין הנביא נקלה כי אם בארצו ובביתו׃ ");
INSERT INTO heb_vpl VALUES ("MT13_58","070_13_58","MAT","13","58","58","ולא עשה שם גבורות רבות מפני חסר אמונתם׃ ");
INSERT INTO heb_vpl VALUES ("MT14_1","070_14_1","MAT","14","1","1","בעת ההיא שמע הורדוס שר רבע המדינה את שמע ישוע׃ ");
INSERT INTO heb_vpl VALUES ("MT14_2","070_14_2","MAT","14","2","2","ויאמר אל נעריו זה הוא יוחנן המטביל והוא קם מן המתים על כן הגבורות פעלות בו׃ ");
INSERT INTO heb_vpl VALUES ("MT14_3","070_14_3","MAT","14","3","3","כי הורדוס תפש את יוחנן ויאסרהו וישימהו בבית הסהר בגלל הורודיה אשת פילפוס אחיו׃ ");
INSERT INTO heb_vpl VALUES ("MT14_4","070_14_4","MAT","14","4","4","כי יוחנן אמר אליו לא נכון היתה לך לאשה׃ ");
INSERT INTO heb_vpl VALUES ("MT14_5","070_14_5","MAT","14","5","5","ויבקש המיתו אך ירא את ההמון כי לנביא חשבו אתו׃ ");
INSERT INTO heb_vpl VALUES ("MT14_6","070_14_6","MAT","14","6","6","ויהי ביום הלדת הורדוס ותרקד בת הורודיה בתוכם ותיטב בעיני הורדוס׃ ");
INSERT INTO heb_vpl VALUES ("MT14_7","070_14_7","MAT","14","7","7","וישבע לה ויאמר מה תשאל נפשך ואתן לך׃ ");
INSERT INTO heb_vpl VALUES ("MT14_8","070_14_8","MAT","14","8","8","ואמה שמה את הדברים בפיה ותשאל לאמר תנה לי פה בקערה את ראש יוחנן המטביל׃ ");
INSERT INTO heb_vpl VALUES ("MT14_9","070_14_9","MAT","14","9","9","ויעצב המלך אך בעבור השבועה והמסבים עמו צוה לתת לה׃ ");
INSERT INTO heb_vpl VALUES ("MT14_10","070_14_10","MAT","14","10","10","וישלח וישא את ראש יוחנן מעליו בבית הסהר׃ ");
INSERT INTO heb_vpl VALUES ("MT14_11","070_14_11","MAT","14","11","11","ויביאו את ראשו בקערה ויתנו לנערה ותביאהו אל אמה׃ ");
INSERT INTO heb_vpl VALUES ("MT14_12","070_14_12","MAT","14","12","12","ויגשו תלמידיו וישאו את גויתו ויקברוה וילכו ויגידו לישוע׃ ");
INSERT INTO heb_vpl VALUES ("MT14_13","070_14_13","MAT","14","13","13","ויהי כשמעו את זאת ויסר משם באניה אל מקום חרבה לבדד וישמעו המון העם וילכו אחריו ברגליהם מן הערים׃ ");
INSERT INTO heb_vpl VALUES ("MT14_14","070_14_14","MAT","14","14","14","ויצא ישוע וירא המון עם רב ויהמו מעיו עליהם וירפא את החלשים אשר בהם׃ ");
INSERT INTO heb_vpl VALUES ("MT14_15","070_14_15","MAT","14","15","15","ויהי לפנות ערב ויגשו אליו תלמידיו ויאמרו המקום חרב וגם נטה היום שלחה את המון העם וילכו אל הכפרים לקנות להם אכל׃ ");
INSERT INTO heb_vpl VALUES ("MT14_16","070_14_16","MAT","14","16","16","ויאמר אליהם אינם צריכים ללכת תנו אתם להם לאכל׃ ");
INSERT INTO heb_vpl VALUES ("MT14_17","070_14_17","MAT","14","17","17","ויאמרו אליו אין לנו פה כי אם חמשת ככרות לחם ושני דגים׃ ");
