INSERT INTO heb_vpl VALUES ("MT14_20","070_14_20","MAT","14","20","20","ויאכלו כלם וישבעו וישאו מן הפתותים הנותרים שנים עשר סלים מלאים׃ ");
INSERT INTO heb_vpl VALUES ("MT14_21","070_14_21","MAT","14","21","21","והאכלים היו כחמשת אלפי איש מלבד הנשים והטף׃ ");
INSERT INTO heb_vpl VALUES ("MT14_22","070_14_22","MAT","14","22","22","ויאץ ישוע בתלמידיו לרדת באניה לעבר לפניה אל עבר הים עד אשר ישלח את העם׃ ");
INSERT INTO heb_vpl VALUES ("MT14_23","070_14_23","MAT","14","23","23","ואחרי שלחו את העם עלה ההרה בדד להתפלל ויהי ערב והוא לבדו שמה׃ ");
INSERT INTO heb_vpl VALUES ("MT14_24","070_14_24","MAT","14","24","24","והאניה הלכה בתוך הים ותטרף מן הגלים כי הרוח לנגדה׃ ");
INSERT INTO heb_vpl VALUES ("MT14_25","070_14_25","MAT","14","25","25","ויהי באשמרת הרביעית ויבא אליהם ישוע מתהלך על פני הים׃ ");
INSERT INTO heb_vpl VALUES ("MT14_26","070_14_26","MAT","14","26","26","והתלמידים בראתם אותו מתהלך על פני הים נבהלו לאמר מראה רוח הוא ויצעקו מפחד׃ ");
INSERT INTO heb_vpl VALUES ("MT14_27","070_14_27","MAT","14","27","27","וידבר ישוע פתאם אליהם חזקו כי אני הוא אל תיראו׃ ");
INSERT INTO heb_vpl VALUES ("MT14_28","070_14_28","MAT","14","28","28","ויען פטרוס ויאמר אליו אם אתה הוא אדני צוה נא כי אבא אליך על המים׃ ");
INSERT INTO heb_vpl VALUES ("MT14_29","070_14_29","MAT","14","29","29","ויאמר בוא וירד פטרוס מן האניה ויתהלך על המים לבוא אל ישוע׃ ");
INSERT INTO heb_vpl VALUES ("MT14_30","070_14_30","MAT","14","30","30","ויהי כראתו את הרוח כי חזקה היא ויירא ויחל לטבע ויצעק לאמר אדני הושיעני׃ ");
INSERT INTO heb_vpl VALUES ("MT14_31","070_14_31","MAT","14","31","31","וימהר ישוע לשלח את ידו ויחזק בו ויאמר אליו קטן האמונה למה לחק לבך׃ ");
INSERT INTO heb_vpl VALUES ("MT14_32","070_14_32","MAT","14","32","32","הם עלו אל האניה והרוח שככה׃ ");
