INSERT INTO heb_vpl VALUES ("MT14_34","070_14_34","MAT","14","34","34","ויעברו את הים ויבאו ארצה גניסר׃ ");
INSERT INTO heb_vpl VALUES ("MT14_35","070_14_35","MAT","14","35","35","ויכירו אתו אנשי המקום ההוא וישלחו אל כל סביבותיהם ויביאו אליו את כל החולים׃ ");
INSERT INTO heb_vpl VALUES ("MT14_36","070_14_36","MAT","14","36","36","ויבקשו ממנו כי יגעו רק בציצת בגדו וכל הנגעים נושעו׃ ");
INSERT INTO heb_vpl VALUES ("MT15_1","070_15_1","MAT","15","1","1","אז באו אל ישוע הסופרים והפרושים אשר מירושלים׃ ");
INSERT INTO heb_vpl VALUES ("MT15_2","070_15_2","MAT","15","2","2","ויאמרו מדוע תלמידיך עברים את קבלת הזקנים כי אינם רחצים את ידיהם באכלם לחם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_3","070_15_3","MAT","15","3","3","ויען ויאמר אליהם מדוע גם אתם עברים את מצות אלהים בעבור קבלתכם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_4","070_15_4","MAT","15","4","4","כי אלהים צוה לאמר כבד את אביך ואת אמך ומקלל אביו ואמו מות יומת׃ ");
INSERT INTO heb_vpl VALUES ("MT15_5","070_15_5","MAT","15","5","5","ואתם אמרים האמר לאביו ולאמו קרבן כל מה שאתה נהנה לי אין עליו לכבד את אביו ואת אמו׃ ");
INSERT INTO heb_vpl VALUES ("MT15_6","070_15_6","MAT","15","6","6","ותפרו את דבר האלהים בעבור קבלתכם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_7","070_15_7","MAT","15","7","7","חנפים היטב נבא עליכם ישעיהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT15_8","070_15_8","MAT","15","8","8","העם הזה נגש בפיו ובשפתיו כבדוני ולבו רחק ממני׃ ");
INSERT INTO heb_vpl VALUES ("MT15_9","070_15_9","MAT","15","9","9","ותהו יראתם אתי מצות אנשים מלמדים׃ ");
INSERT INTO heb_vpl VALUES ("MT15_10","070_15_10","MAT","15","10","10","ויקרא אל העם ויאמר להם שמעו והבינו׃ ");
INSERT INTO heb_vpl VALUES ("MT15_11","070_15_11","MAT","15","11","11","לא הבא אל הפה יטמא את האדם כי אם היוצא מן הפה הוא מטמא את האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_12","070_15_12","MAT","15","12","12","ויגשו אליו תלמידיו ויאמרו הידעת כי הפרושים בשמעם את הדבר הזה נכשלו בו׃ ");
INSERT INTO heb_vpl VALUES ("MT15_13","070_15_13","MAT","15","13","13","ויען ויאמר כל מטע אשר לא נטע אבי שבשמים עקור יעקר׃ ");
INSERT INTO heb_vpl VALUES ("MT15_14","070_15_14","MAT","15","14","14","הניחו אותם מנהלים עורים המה לעורים וכי יוליך עור את העור ונפלו שניהם בתוך הבור׃ ");
INSERT INTO heb_vpl VALUES ("MT15_15","070_15_15","MAT","15","15","15","ויען פטרוס ויאמר אליו באר לנו את המשל הזה׃ ");
INSERT INTO heb_vpl VALUES ("MT15_16","070_15_16","MAT","15","16","16","ויאמר ישוע עדנה גם אתם באין בינה׃ ");
INSERT INTO heb_vpl VALUES ("MT15_17","070_15_17","MAT","15","17","17","העוד לא תשכילו כי כל הבא אל הפה יורד אל הכרש וישפך משם למוצאות׃ ");
INSERT INTO heb_vpl VALUES ("MT15_18","070_15_18","MAT","15","18","18","אבל היוצא מן הפה יוצא מן הלב והוא מטמא את האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_19","070_15_19","MAT","15","19","19","כי מן הלב יוצאות מחשבות רע רציחות נאופים זנונים גנבות עדיות שקר וגדופים׃ ");
INSERT INTO heb_vpl VALUES ("MT15_20","070_15_20","MAT","15","20","20","אלה הם המטמאים את האדם אבל אכול בלי נטילת ידים לא יטמא את האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_21","070_15_21","MAT","15","21","21","ויצא ישוע משם ויסר אל גלילות צור וצידון׃ ");
INSERT INTO heb_vpl VALUES ("MT15_22","070_15_22","MAT","15","22","22","והנה אשה כנענית יצאה מן הגבולות ההם ותצעק אליו לאמר חנני אדני בן דוד כי בתי מענה מאד על ידי שד׃ ");
INSERT INTO heb_vpl VALUES ("MT15_23","070_15_23","MAT","15","23","23","והוא לא ענה אתה דבר ויגשו תלמידיו ויבקשו ממנו לאמר שלחה כי צעקת היא אחרינו׃ ");
INSERT INTO heb_vpl VALUES ("MT15_24","070_15_24","MAT","15","24","24","ויען ויאמר לא שלחתי כי אם אל הצאן האבדות לבית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MT15_25","070_15_25","MAT","15","25","25","והיא באה ותשתחו לו לאמר אדני עזרני׃ ");
INSERT INTO heb_vpl VALUES ("MT15_26","070_15_26","MAT","15","26","26","ויען ויאמר לא טוב לקחת את לחם הבנים ולהשליכו לצעירי הכלבים׃ ");
INSERT INTO heb_vpl VALUES ("MT15_27","070_15_27","MAT","15","27","27","ותאמר כן אדני אפס כי גם צעירי הכלבים יאכלו מפרורים הנפלים מעל שלחן אדניהם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_28","070_15_28","MAT","15","28","28","ויען ישוע ויאמר אליה אשה גדלה אמונתך יהי לך כרצונך ותרפא בתה מן השעה ההיא׃ ");
INSERT INTO heb_vpl VALUES ("MT15_29","070_15_29","MAT","15","29","29","ויעבר ישוע משם ויבא אל ים הגליל ויעל ההרה וישב שם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_30","070_15_30","MAT","15","30","30","ויבאו אליו המון עם רב ועמהם פסחים עורים חרשים קטעים ורבים כהמה ויפילום לרגלי ישוע וירפאם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_31","070_15_31","MAT","15","31","31","ויתמהו העם בראותם את האלמים מדברים והקטעים בריאים והפסחים מתהלכים והעורים ראים וישבחו את אלהי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MT15_32","070_15_32","MAT","15","32","32","ויקרא ישוע אל תלמידיו ויאמר נכמרו רחמי על העם כי זה שלשת ימים עמדו עמדי ואין להם מה לאכל ואינני אבה לשלחם רעבים פן יתעלפו בדרך׃ ");
INSERT INTO heb_vpl VALUES ("MT15_33","070_15_33","MAT","15","33","33","ויאמרו אליו התלמידים מאין לנו די לחם במדבר להשביע את ההמון הגדול הזה׃ ");
INSERT INTO heb_vpl VALUES ("MT15_34","070_15_34","MAT","15","34","34","ויאמר ישוע אליהם כמה ככרות לחם לכם ויאמרו שבע ומעט דגים קטנים׃ ");
INSERT INTO heb_vpl VALUES ("MT15_35","070_15_35","MAT","15","35","35","ויצו את המון העם לשבת לארץ׃ ");
INSERT INTO heb_vpl VALUES ("MT15_36","070_15_36","MAT","15","36","36","ויקח את שבע ככרות הלחם ואת הדגים ויברך ויפרס ויתן אל התלמידים והתלמידים נתנו לעם׃ ");
INSERT INTO heb_vpl VALUES ("MT15_37","070_15_37","MAT","15","37","37","ויאכלו כלם וישבעו וישאו מן הפתותים הנותרים שבעה דודים מלאים׃ ");
INSERT INTO heb_vpl VALUES ("MT15_38","070_15_38","MAT","15","38","38","והאכלים היו ארבעת אלפי איש מלבד הנשים והטף׃ ");
INSERT INTO heb_vpl VALUES ("MT15_39","070_15_39","MAT","15","39","39","וישלח את העם וירד באניה ויבא אל גבול מגדלא׃ ");
INSERT INTO heb_vpl VALUES ("MT16_1","070_16_1","MAT","16","1","1","ויגשו הפרושים והצדוקים לנסותו וישאלו מאתו להראותם אות מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_2","070_16_2","MAT","16","2","2","ויען ויאמר להם בערב תאמרו יום צח יהיה כי אדמו השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_3","070_16_3","MAT","16","3","3","ובבקר תאמרו היום סער כי אדמו והתקדרו השמים חנפים אתם את פני השמים ידעתם לבחן ואתות העתים לא תוכלו׃ ");
INSERT INTO heb_vpl VALUES ("MT16_4","070_16_4","MAT","16","4","4","דור רע ומנאף בקש לו אות ואות לא ינתן לו בלתי אם אות יונה הנביא ויעזבם וילך לו׃ ");
INSERT INTO heb_vpl VALUES ("MT16_5","070_16_5","MAT","16","5","5","וכבוא התלמידים אל עבר הים שכחו לקחת אתם לחם׃ ");
INSERT INTO heb_vpl VALUES ("MT16_6","070_16_6","MAT","16","6","6","ויאמר ישוע אליהם ראו והשמרו לכם משאר הפרושים והצדוקים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_7","070_16_7","MAT","16","7","7","ויחשבו בלבבם לאמר כי לא לקחנו אתנו לחם׃ ");
INSERT INTO heb_vpl VALUES ("MT16_8","070_16_8","MAT","16","8","8","וידע ישוע ויאמר אליהם קטני האמונה מה תחשבו בלבבכם כי לא לקחתם אתכם לחם׃ ");
INSERT INTO heb_vpl VALUES ("MT16_9","070_16_9","MAT","16","9","9","העוד לא תשכילו ולא תזכרו את חמשת ככרות הלחם לחמשת אלפי איש וכמה סלים נשאתם׃ ");
INSERT INTO heb_vpl VALUES ("MT16_10","070_16_10","MAT","16","10","10","ואת שבע ככרות לחם לארבעת אלפי איש וכמה דודים נשאתם׃ ");
INSERT INTO heb_vpl VALUES ("MT16_11","070_16_11","MAT","16","11","11","איך לא תבינו כי לא על הלחם אמרתי אליכם השמרו לכם משאר הפרושים והצדוקים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_12","070_16_12","MAT","16","12","12","אז הבינו כי לא אמר להשמר משאר הלחם כי אם מלמוד הפרושים והצדוקים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_13","070_16_13","MAT","16","13","13","ויהי כבוא ישוע אל גלילות קיסרין של פילפוס וישאל את תלמידיו לאמר מה אמרים האנשים עלי מי הוא בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT16_14","070_16_14","MAT","16","14","14","ויאמרו יש אמרים יוחנן המטביל הוא ואחרים אמרים אליהו ויש אמרים ירמיהו או אחד מן הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_15","070_16_15","MAT","16","15","15","ויאמר אליהם ואתם מה תאמרו מי אני׃ ");
INSERT INTO heb_vpl VALUES ("MT16_16","070_16_16","MAT","16","16","16","ויען שמעון פטרוס ויאמר אתה הוא המשיח בן אלהים חיים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_17","070_16_17","MAT","16","17","17","ויען ויאמר אליו אשריך שמעון בר יונה כי בשר ודם לא גלה לך את זאת כי אם אבי שבשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_18","070_16_18","MAT","16","18","18","ואף אני אמר אליך כי אתה פטרוס ועל הסלע הזה אבנה את קהלתי ושערי שאול לא יגברו עליה׃ ");
INSERT INTO heb_vpl VALUES ("MT16_19","070_16_19","MAT","16","19","19","ואתן לך את מפתחות מלכות השמים וכל אשר תאסר על הארץ אסור יהיה בשמים וכל אשר תתיר על הארץ מתר יהיה בשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT16_20","070_16_20","MAT","16","20","20","אז צוה את התלמידים בגערה לבלתי הגיד לאיש כי הוא ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("MT16_21","070_16_21","MAT","16","21","21","מן העת ההיא החל ישוע להורות את תלמידיו שהוא צריך ללכת ירושלים ויענה הרבה בידי הזקנים והכהנים הגדולים והסופרים ויהרג וביום השלישי קום יקום׃ ");
INSERT INTO heb_vpl VALUES ("MT16_22","070_16_22","MAT","16","22","22","ויקחהו פטרוס ויחל לגער בו לאמר חס לך אדני אל יהי לך כזאת׃ ");
INSERT INTO heb_vpl VALUES ("MT16_23","070_16_23","MAT","16","23","23","ויפן ויאמר לפטרוס סור מעלי השטן למכשול אתה לי כי אין לבך לדברי אלהים כי אם לדברי בני אדם׃ ");
INSERT INTO heb_vpl VALUES ("MT16_24","070_16_24","MAT","16","24","24","ויאמר ישוע אל תלמידיו איש כי יחפץ ללכת אחרי יכחש בנפשו ונשא את צלבו והלך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("MT16_25","070_16_25","MAT","16","25","25","כי כל אשר יחפץ להושיע את נפשו תאבד נפשו ממנו וכל אשר תאבד לו נפשו למעני הוא ימצאנה׃ ");
INSERT INTO heb_vpl VALUES ("MT16_26","070_16_26","MAT","16","26","26","כי מה יועיל האדם כי יקנה את כל העולם ונפשו תשחת או מה יתן האדם פדיון נפשו׃ ");
INSERT INTO heb_vpl VALUES ("MT16_27","070_16_27","MAT","16","27","27","כי עתיד בן האדם לבוא בכבוד אביו עם מלאכיו ואז ישלם לכל איש כמעשהו׃ ");
INSERT INTO heb_vpl VALUES ("MT16_28","070_16_28","MAT","16","28","28","אמן אמר אני לכם כי יש מן העמדים פה אשר לא יטעמו מות עד כי יראו את בן האדם בא במלכותו׃ ");
INSERT INTO heb_vpl VALUES ("MT17_1","070_17_1","MAT","17","1","1","ומקץ ששת ימים לקח לו ישוע את פטרוס ואת יעקב ואת יוחנן אחיו ויעלם בדד על הר גבוה׃ ");
INSERT INTO heb_vpl VALUES ("MT17_2","070_17_2","MAT","17","2","2","וישתנה לעיניהם ויזהירו פניו כשמש ובגדיו כאור הלבינו׃ ");
INSERT INTO heb_vpl VALUES ("MT17_3","070_17_3","MAT","17","3","3","והנה נראו אליהם משה ואליהו מדברים אתו׃ ");
INSERT INTO heb_vpl VALUES ("MT17_4","070_17_4","MAT","17","4","4","ויען פטרוס ויאמר אל ישוע אדני טוב היותנו פה אם תחפץ נעשה נא פה שלש סכות לך אחת ולמשה אחת ולאליהו אחת׃ ");
INSERT INTO heb_vpl VALUES ("MT17_5","070_17_5","MAT","17","5","5","עודנו מדבר והנה ענן אור הצל עליהם והנה קול מתוך הענן אמר זה בני ידידי אשר רציתי בו אליו תשמעון׃ ");
INSERT INTO heb_vpl VALUES ("MT17_6","070_17_6","MAT","17","6","6","ויהי כשמע התלמידים ויפלו על פניהם וייראו מאד׃ ");
INSERT INTO heb_vpl VALUES ("MT17_7","070_17_7","MAT","17","7","7","ויגש ישוע ויגע בם ויאמר קומו ואל תיראו׃ ");
INSERT INTO heb_vpl VALUES ("MT17_8","070_17_8","MAT","17","8","8","וישאו עיניהם ולא ראו איש בלתי את ישוע לבדו׃ ");
INSERT INTO heb_vpl VALUES ("MT17_9","070_17_9","MAT","17","9","9","וברדתם מן ההר צוה ישוע אתם לאמר לא תגידו לאיש את דבר המראה עד אם קם בן האדם מעם המתים׃ ");
INSERT INTO heb_vpl VALUES ("MT17_10","070_17_10","MAT","17","10","10","וישאלהו תלמידיו לאמר למה זה אמרים הסופרים כי אליהו בוא יבוא בראשונה׃ ");
INSERT INTO heb_vpl VALUES ("MT17_11","070_17_11","MAT","17","11","11","ויען ישוע ויאמר אליהם הנה אליהו בא בראשונה והשיב את הכל׃ ");
INSERT INTO heb_vpl VALUES ("MT17_12","070_17_12","MAT","17","12","12","אבל אמר אני לכם כי אליהו כבר בא ולא הכירהו ויעשו בו כרצונם וכן גם בן האדם יענה על ידם׃ ");
INSERT INTO heb_vpl VALUES ("MT17_13","070_17_13","MAT","17","13","13","אז הבינו התלמידים כי על יוחנן המטביל דבר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("MT17_14","070_17_14","MAT","17","14","14","ויהי כבואם אל המון העם ויגש אליו איש ויכרע על ברכיו לנגדו׃ ");
INSERT INTO heb_vpl VALUES ("MT17_15","070_17_15","MAT","17","15","15","ויאמר אדני רחם נא על בני כי מכה ירח הוא וחליו רע כי פעמים רבות הוא נפל באש ופעמים רבות אל תוך המים׃ ");
INSERT INTO heb_vpl VALUES ("MT17_16","070_17_16","MAT","17","16","16","ואביא אתו אל תלמידיך ולא יכלו לרפא לו׃ ");
INSERT INTO heb_vpl VALUES ("MT17_17","070_17_17","MAT","17","17","17","ויען ישוע ויאמר הוי דור בלתי מאמין ופתלתל עד מתי אהיה עמכם עד מתי אסבל אתכם הביאו אותו אלי הנה׃ ");
INSERT INTO heb_vpl VALUES ("MT17_18","070_17_18","MAT","17","18","18","ויגער בו ישוע ויצא השד ממנו וירפא הנער מן השעה ההיא׃ ");
INSERT INTO heb_vpl VALUES ("MT17_19","070_17_19","MAT","17","19","19","ויגשו התלמידים אל ישוע והוא לבדו ויאמרו מדוע אנחנו לא יכלנו לגרשו׃ ");
INSERT INTO heb_vpl VALUES ("MT17_20","070_17_20","MAT","17","20","20","ויאמר ישוע אליהם מפני אשר אינכם מאמינים כי אמן אמר אני לכם אם יש לכם אמונה כגרגר החרדל ואמרתם אל ההר הזה העתק מזה שמה ונעתק ממקומו ואין דבר אשר יבצר מכם׃ ");
INSERT INTO heb_vpl VALUES ("MT17_21","070_17_21","MAT","17","21","21","אבל המין הזה לא יצא כי אם בתפלה ובצום׃ ");
INSERT INTO heb_vpl VALUES ("MT17_22","070_17_22","MAT","17","22","22","ויהי בהתהלכם בארץ הגליל ויאמר אליהם ישוע עתיד בן האדם להמסר בידי אנשים׃ ");
INSERT INTO heb_vpl VALUES ("MT17_23","070_17_23","MAT","17","23","23","ויהרגהו וביום השלישי קום יקום ויתעצבו מאד׃ ");
INSERT INTO heb_vpl VALUES ("MT17_24","070_17_24","MAT","17","24","24","ויהי כבואם אל כפר נחום ויגשו אל פטרוס גבי מחצית השקל ויאמרו הלא יתן רבכם את מחצית השקל׃ ");
INSERT INTO heb_vpl VALUES ("MT17_25","070_17_25","MAT","17","25","25","ויאמר הן ובבואו הביתה קדם אתו ישוע לשאל מה דעתך שמעון מלכי הארץ ממי יקחו מכס ומס מאת בניהם או מאת הזרים׃ ");
INSERT INTO heb_vpl VALUES ("MT17_26","070_17_26","MAT","17","26","26","ויאמר פטרוס אליו מאת הזרים ויאמר לו ישוע אם כן אפוא הבנים חפשים המה׃ ");
INSERT INTO heb_vpl VALUES ("MT17_27","070_17_27","MAT","17","27","27","אך למען לא נהיה להם למכשול לך אל הים והשלכת אל תוכו חכה ואת הדג הראשון אשר יעלה שאהו וכאשר תפתח את פיו תמצא בו אסתירא אותו קח לך ונתת להם בעדי ובעדך׃ ");
INSERT INTO heb_vpl VALUES ("MT18_1","070_18_1","MAT","18","1","1","בשעה ההיא נגשו התלמידים אל ישוע ויאמרו מי אפוא גדול מחבריו במלכות השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT18_2","070_18_2","MAT","18","2","2","ויקרא ישוע אליו ילד קטן ויעמידהו בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("MT18_3","070_18_3","MAT","18","3","3","ויאמר אמן אמר אני לכם אם לא תשובו להיות כילדים לא תבוא אל מלכות השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT18_4","070_18_4","MAT","18","4","4","לכן כל המשפיל את עצמו כילד הזה הוא הגדול במלכות השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT18_5","070_18_5","MAT","18","5","5","וכל אשר יקבל ילד אחד כזה בשמי אותי הוא מקבל׃ ");
INSERT INTO heb_vpl VALUES ("MT18_6","070_18_6","MAT","18","6","6","וכל המכשיל את אחד מן הקטנים האלה המאמינים בי נוח לו שיתלה פלח רכב על צוארו וטבע במצולות ים׃ ");
INSERT INTO heb_vpl VALUES ("MT18_7","070_18_7","MAT","18","7","7","אוי לעולם מפני המכשלים כי המכשלים צריכים לבוא אבל אוי לאיש ההוא אשר על ידו יבוא המכשול׃ ");
INSERT INTO heb_vpl VALUES ("MT18_8","070_18_8","MAT","18","8","8","ואם תכשילך ידך או רגלך קצץ אותה והשלך ממך טוב לך לבוא לחיים פסח או קטע מהיות לך שתי ידים או שתי רגלים ותשלך אל אש עולם׃ ");
INSERT INTO heb_vpl VALUES ("MT18_9","070_18_9","MAT","18","9","9","ואם עינך תכשליך נקר אותה והשלך ממך טוב לך לבוא לחיים בעין אחת מהיות לך שתי עינים ותשלך אל אש גיהנם׃ ");
INSERT INTO heb_vpl VALUES ("MT18_10","070_18_10","MAT","18","10","10","ראו פן תבזו אחד wקטנים האלה כי אמר אני לכם כי מלאכיהם ראים תמיד את פני אבי שבשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT18_11","070_18_11","MAT","18","11","11","כי בא בן האדם להושיע את האבד׃ ");
INSERT INTO heb_vpl VALUES ("MT18_12","070_18_12","MAT","18","12","12","מה דעתכם כי יהיו לאיש מאה כבשים ותעה אחד מהם הלא יעזב את התשעים ותשעה על ההרים והלך לבקש את התעה׃ ");
INSERT INTO heb_vpl VALUES ("MT18_13","070_18_13","MAT","18","13","13","והיה כאשר ימצאהו אמן אמר אני לכם כי ישמח עליו יותר מעל התשעים ותשעה אשר לא תעו׃ ");
INSERT INTO heb_vpl VALUES ("MT18_14","070_18_14","MAT","18","14","14","כן איננו רצון מלפני אביכם שבשמים כי יאבד אחד מן הקטנים האלה׃ ");
INSERT INTO heb_vpl VALUES ("MT18_15","070_18_15","MAT","18","15","15","וכי יחטא לך אחיך לך והוכחת אותו בינך ובינו לבדו ואם ישמע אליך קנית לך אחיך׃ ");
INSERT INTO heb_vpl VALUES ("MT18_16","070_18_16","MAT","18","16","16","ואם לא ישמע קח עמך עוד אחד או שנים למען על פי שנים או שלשה עדים יקום כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("MT18_17","070_18_17","MAT","18","17","17","ואם לא ישמע אליהם הגד אל הקהל ואם לא ישמע גם אל הקהל והיה לך כגוי וכמוכס׃ ");
INSERT INTO heb_vpl VALUES ("MT18_18","070_18_18","MAT","18","18","18","אמן אמר אני לכם כל אשר תאסרו על הארץ אסור יהיה בשמים וכל אשר תתירו על הארץ מתר יהיה בשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT18_19","070_18_19","MAT","18","19","19","ועוד אמר אני לכם שנים מכם כי יועצו יחדו בארץ על כל דבר אשר ישאלו היה יהיה להם מאת אבי שבשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT18_20","070_18_20","MAT","18","20","20","כי בכל מקום אשר שנים או שלשה נאספו בשמי שם אני בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("MT18_21","070_18_21","MAT","18","21","21","ויגש אליו פטרוס ויאמר לו אדני כמה פעמים יחטא לי אחי וסלחתי לו העד שבע פעמים׃ ");
INSERT INTO heb_vpl VALUES ("MT18_22","070_18_22","MAT","18","22","22","ויאמר אליו ישוע לא אמר לך עד שבע פעמים כי אם עד שבעים ושבע׃ ");
INSERT INTO heb_vpl VALUES ("MT18_23","070_18_23","MAT","18","23","23","על כן דומה מלכות השמים למלך בשר ודם אשר חפץ לעשות חשבון עם עבדיו׃ ");
INSERT INTO heb_vpl VALUES ("MT18_24","070_18_24","MAT","18","24","24","וכאשר החל לחשב הובא לפניו איש אשר חיב לו עשרת אלפים ככרי כסף׃ ");
INSERT INTO heb_vpl VALUES ("MT18_25","070_18_25","MAT","18","25","25","ולא היה לו לשלם ויצו אדניו למכר אותו ואת אשתו ואת בניו ואת כל אשר לו וכן ישלם׃ ");
INSERT INTO heb_vpl VALUES ("MT18_26","070_18_26","MAT","18","26","26","ויפל העבד וישתחו לו לאמר אדני הארך לי אפך ואת כל אשלמה לך׃ ");
INSERT INTO heb_vpl VALUES ("MT18_27","070_18_27","MAT","18","27","27","ויהמו רחמי אדוני העבד ההוא ויפטרהו וישמט לו את החוב׃ ");
INSERT INTO heb_vpl VALUES ("MT18_28","070_18_28","MAT","18","28","28","ויצא העבד ההוא מלפניו וימצא אחד מחבריו העבדים והוא חיב לו מאה דינרים ויחזק בו ויחנקהו לאמר שלם את אשר אתה חיב לי׃ ");
INSERT INTO heb_vpl VALUES ("MT18_29","070_18_29","MAT","18","29","29","ויפל חברו לפני רגליו ויבקש ממנו לאמר הארך לי אפך ואשלמה לך הכל׃ ");
INSERT INTO heb_vpl VALUES ("MT18_30","070_18_30","MAT","18","30","30","והוא מאן וילך וישליכהו במשמר עד כי ישלם לו את חובו׃ ");
INSERT INTO heb_vpl VALUES ("MT18_31","070_18_31","MAT","18","31","31","וחבריו העבדים ראו את הנעשה ויעצבו מאד ויבאו ויגידו לאדניהם את כל אשר נעשה׃ ");
INSERT INTO heb_vpl VALUES ("MT18_32","070_18_32","MAT","18","32","32","ויקרא אליו אדניו ויאמר לו אתה העבד הרע את כל החוב ההוא השמטתי לך יען אשר בקשת ממני׃ ");
INSERT INTO heb_vpl VALUES ("MT18_33","070_18_33","MAT","18","33","33","הלא היה לך גם אתה לרחם על העבד חברך כאשר רחמתי אני עליך׃ ");
INSERT INTO heb_vpl VALUES ("MT18_34","070_18_34","MAT","18","34","34","ויקצף אדניו ויסגר אותו למיסרים עד כי ישלם את כל חובו׃ ");
INSERT INTO heb_vpl VALUES ("MT18_35","070_18_35","MAT","18","35","35","ככה יעשה לכם גם אבי שבשמים אם לא תסלחו איש איש לאחיו בכל לבבכם את חטאתם׃ ");
INSERT INTO heb_vpl VALUES ("MT19_1","070_19_1","MAT","19","1","1","ויהי ככלות ישוע לדבר את הדברים האלה ויסע מן הגליל ויבא אל גבול יהודה בעבר הירדן׃ ");
INSERT INTO heb_vpl VALUES ("MT19_2","070_19_2","MAT","19","2","2","וילכו אחריו המון עם רב וירפאם שם׃ ");
INSERT INTO heb_vpl VALUES ("MT19_3","070_19_3","MAT","19","3","3","ויגשו אליו הפרושים לנסותו לאמר היוכל איש לשלח את אשתו על כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("MT19_4","070_19_4","MAT","19","4","4","ויען ויאמר אליהם הלא קראתם כי עשה בראשית זכר ונקבה עשה אתם׃ ");
INSERT INTO heb_vpl VALUES ("MT19_5","070_19_5","MAT","19","5","5","ואמר על כן יעזב איש את אביו ואת אמו ודבק באשתו והיו שניהם לבשר אחד׃ ");
INSERT INTO heb_vpl VALUES ("MT19_6","070_19_6","MAT","19","6","6","אם כן אינם עוד שנים כי אם בשר אחד לכן את אשר חבר האלהים אל יפרידנו האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT19_7","070_19_7","MAT","19","7","7","ויאמרו אליו ולמה זה צוה משה לתת לה ספר כריתת ולשלחה׃ ");
INSERT INTO heb_vpl VALUES ("MT19_8","070_19_8","MAT","19","8","8","ויאמר אליהם בעבור קשי לבבכם הניח לכם משה לשלח את נשיכם אך מראש לא היתה ככה׃ ");
INSERT INTO heb_vpl VALUES ("MT19_9","070_19_9","MAT","19","9","9","ואני אמר לכם המשלח את אשתו בלתי על דבר זנות ולקח לו אחרת נאף הוא והלקח את הגרושה נאף הוא׃ ");
INSERT INTO heb_vpl VALUES ("MT19_10","070_19_10","MAT","19","10","10","ויאמרו אליו התלמידים אם ככה הוא ענין איש ואשתו לא טוב לקחת אשה׃ ");
INSERT INTO heb_vpl VALUES ("MT19_11","070_19_11","MAT","19","11","11","ויאמר אליהם לא יוכל כל אדם קבל את הדבר הזה כי אם אלה אשר נתן להם להבין׃ ");
INSERT INTO heb_vpl VALUES ("MT19_12","070_19_12","MAT","19","12","12","יש סריסים אשר נולדו כן מבטן אמם ויש סריסים המסרסים על ידי אדם ויש סריסים אשר סרסו את עצמם למען מלכות השמים מי שיוכל לקבל יקבל׃ ");
INSERT INTO heb_vpl VALUES ("MT19_13","070_19_13","MAT","19","13","13","אז יביאו אליו ילדים למען ישים עליהם את ידיו ויתפלל עליהם ויגערו בם התלמידים׃ ");
INSERT INTO heb_vpl VALUES ("MT19_14","070_19_14","MAT","19","14","14","והוא ישוע אמר הניחו לילדים ואל תמנעום מבוא אלי כי לאלה מלכות השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT19_15","070_19_15","MAT","19","15","15","וישם את ידיו עליהם ויעבר משם׃ ");
INSERT INTO heb_vpl VALUES ("MT19_16","070_19_16","MAT","19","16","16","והנה איש נגש אליו ויאמר רבי הטוב אי זה הטוב אשר אעשנו לקנות חיי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("MT19_17","070_19_17","MAT","19","17","17","ויאמר אליו מה תקראני טוב אין טוב כי אם אחד האלהים ואם חפצך לבוא אל החיים שמר את המצות׃ ");
INSERT INTO heb_vpl VALUES ("MT19_18","070_19_18","MAT","19","18","18","ויאמר אליו מה הנה ויאמר ישוע אלה הן לא תרצח לא תנאף לא תגנב לא תענה עד שקר׃ ");
INSERT INTO heb_vpl VALUES ("MT19_19","070_19_19","MAT","19","19","19","כבד את אביך ואת אמך ואהבת לרעך כמוך׃ ");
INSERT INTO heb_vpl VALUES ("MT19_20","070_19_20","MAT","19","20","20","ויאמר אליו הבחור את כל אלה שמרתי מנעורי ומה חסרתי עוד׃ ");
INSERT INTO heb_vpl VALUES ("MT19_21","070_19_21","MAT","19","21","21","ויאמר ישוע אליו אם חפצך להיות שלם לך מכר את רכשך ותן לעניים והיה לך אוצר בשמים ושוב הלם ולך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("MT19_22","070_19_22","MAT","19","22","22","ויהי כשמע הבחור את הדבר הזה וילך משם נעצב כי היו לו נכסים רבים׃ ");
INSERT INTO heb_vpl VALUES ("MT19_23","070_19_23","MAT","19","23","23","ויאמר ישוע אל תלמידיו אמן אמר אני לכם קשה לעשיר לבוא אל מלכות השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT19_24","070_19_24","MAT","19","24","24","ועוד אני אמר לכם כי נקל לגמל לעבר דרך נקב המחט מבא עשיר אל מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("MT19_25","070_19_25","MAT","19","25","25","והתלמידים כשמעם זאת השתוממו מאד ויאמרו מי אפוא יוכל להושע׃ ");
INSERT INTO heb_vpl VALUES ("MT19_26","070_19_26","MAT","19","26","26","ויבט בן ישוע ויאמר להם מבני אדם יפלא הדבר אבל מהאלהים לא יפלא כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("MT19_27","070_19_27","MAT","19","27","27","ויען פטרוס ויאמר אליו הן אנחנו עזבנו את הכל ונלך אחריך מה יהיה לנו׃ ");
INSERT INTO heb_vpl VALUES ("MT19_28","070_19_28","MAT","19","28","28","ויאמר ישוע אליהם אמן אמר אני לכם אתם ההלכים אחרי בהתחדש הבריאה כאשר ישב בן האדם על כסא כבודו תשבו גם אתם על שנים עשר כסאות לשפט את שנים עשר שבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("MT19_29","070_19_29","MAT","19","29","29","וכל איש אשר עזב את בתיו ואת אחיו ואת אחיותיו ואת אביו ואת אמו ואת אשתו ואת בניו ואת שדותיו למען שמי הוא יקח מאה שערים וחיי עולמים יירש׃ ");
INSERT INTO heb_vpl VALUES ("MT19_30","070_19_30","MAT","19","30","30","ואולם רבים מן הראשונים אשר יהיו אחרונים ומן האחרונים יהיו ראשונים׃ ");
INSERT INTO heb_vpl VALUES ("MT20_1","070_20_1","MAT","20","1","1","כי דומה מלכות השמים לאדם בעל בית אשר השכים לצאת בבקר לשכר פעלים לכרמו׃ ");
INSERT INTO heb_vpl VALUES ("MT20_2","070_20_2","MAT","20","2","2","והתנה עם הפעלים שכר דינר ליום וישלחם אל כרמו׃ ");
INSERT INTO heb_vpl VALUES ("MT20_3","070_20_3","MAT","20","3","3","ויצא בשעה השלישית וירא אחרים עמדים בטלים בשוק׃ ");
INSERT INTO heb_vpl VALUES ("MT20_4","070_20_4","MAT","20","4","4","ויאמר להם לכו גם אתם אל כרמי וכישר אתן לכם וילכו׃ ");
INSERT INTO heb_vpl VALUES ("MT20_5","070_20_5","MAT","20","5","5","ויצא גם בשעה הששית גם בתשיעית ויעש כדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("MT20_6","070_20_6","MAT","20","6","6","ויצא בשעת עשתי עשרה וימצא אחרים עמדים ויאמר אליהם למה אתם עמדים פה בטלים כל היום׃ ");
INSERT INTO heb_vpl VALUES ("MT20_7","070_20_7","MAT","20","7","7","ויאמרו לו כי לא שכר אותנו איש ויאמר אליהם לכו גם אתם אל הכרם וכישר יתן לכם׃ ");
INSERT INTO heb_vpl VALUES ("MT20_8","070_20_8","MAT","20","8","8","ויהי בערב ויאמר בעל הכרם אל פקידו קרא את הפעלים ושלם להם את שכרם החל באחרונים וכלה בראשונים׃ ");
INSERT INTO heb_vpl VALUES ("MT20_9","070_20_9","MAT","20","9","9","ויבאו הנשכרים בשעת אחת עשרה ויקחו איש איש דינר אחד׃ ");
INSERT INTO heb_vpl VALUES ("MT20_10","070_20_10","MAT","20","10","10","ובבא הראשונים דמו בנפשם כי יקחו יותר ויקחו גם הם איש איש דינר אחד׃ ");
INSERT INTO heb_vpl VALUES ("MT20_11","070_20_11","MAT","20","11","11","ויהי בקחתם וילונו על בעל הבית לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT20_12","070_20_12","MAT","20","12","12","אלה האחרונים לא עשו כי אם שעה אחת ואתה השויתם אלינו אשר סבלנו את כבד היום ואת חמו׃ ");
INSERT INTO heb_vpl VALUES ("MT20_13","070_20_13","MAT","20","13","13","ויען ויאמר אל אחד מהם רעי לא עשקתיך הלא שכר דינר התנית עמי׃ ");
INSERT INTO heb_vpl VALUES ("MT20_14","070_20_14","MAT","20","14","14","קח את שלך ולך ואני רצוני לתת גם לזה האחרון כמו לך׃ ");
INSERT INTO heb_vpl VALUES ("MT20_15","070_20_15","MAT","20","15","15","הלא אוכל לעשות בשלי כרצוני האם תרע עינך על אשר טוב אנכי׃ ");
INSERT INTO heb_vpl VALUES ("MT20_16","070_20_16","MAT","20","16","16","ככה יהיו האחרונים ראשונים והראשונים יהיו אחרונים כי רבים הם הקרואים ומעטים הנבחרים׃ ");
INSERT INTO heb_vpl VALUES ("MT20_17","070_20_17","MAT","20","17","17","ויהי כעלות ישוע ירושלים ויקח אליו את שנים העשר לבדם ויאמר להם בדרך׃ ");
INSERT INTO heb_vpl VALUES ("MT20_18","070_20_18","MAT","20","18","18","הננו עלים ירושלימה ובן האדם ימסר לראשי הכהנים ולסופרים והרשיעהו למות׃ ");
INSERT INTO heb_vpl VALUES ("MT20_19","070_20_19","MAT","20","19","19","ומסרו אותו לגוים להתל בו ולהכות אותו בשוטים ולצלב אותו וביום השלישי קום יקום׃ ");
INSERT INTO heb_vpl VALUES ("MT20_20","070_20_20","MAT","20","20","20","אז נגשה אליו אם בני זבדי עם בניה ותשתחו לו לבקש ממנו דבר׃ ");
INSERT INTO heb_vpl VALUES ("MT20_21","070_20_21","MAT","20","21","21","ויאמר אליה מה בקשתך ותאמר אליו אמר נא כי ישבו שני בני אלה אחד לימינך ואחד לשמאלך במלכותך׃ ");
INSERT INTO heb_vpl VALUES ("MT20_22","070_20_22","MAT","20","22","22","ויען ישוע ויאמר לא ידעתם את אשר שאלתם היכל תוכלו שתות את הכוס אשר אני עתיד לשתותו והטבל בטבילה אשר אני נבטל בה ויאמרו אליו נוכל׃ ");
INSERT INTO heb_vpl VALUES ("MT20_23","070_20_23","MAT","20","23","23","ויאמר אליהם הן את כוסי תשתו ובטבילה אשר אני נטבל בה תטבלו אך שבת לימימי ולשמאלי אין בידי לתתה בלתי לאשר הוכן להם מאת אבי׃ ");
INSERT INTO heb_vpl VALUES ("MT20_24","070_20_24","MAT","20","24","24","ויהי כאשר שמעו זאת העשרה ויכעסו אל שני האחים׃ ");
INSERT INTO heb_vpl VALUES ("MT20_25","070_20_25","MAT","20","25","25","וישוע קרא להם ויאמר אתם ידעתם כי שרי הגוים רדים בהם והגדולים שלטים עליהם׃ ");
INSERT INTO heb_vpl VALUES ("MT20_26","070_20_26","MAT","20","26","26","ואתם אל יהי כן ביניכם כי אם החפז להיות גדול בכם יהי לכם למשרת׃ ");
INSERT INTO heb_vpl VALUES ("MT20_27","070_20_27","MAT","20","27","27","והחפץ להיות בכם לראש יהי לכם עבד׃ ");
INSERT INTO heb_vpl VALUES ("MT20_28","070_20_28","MAT","20","28","28","כאשר בן האדם לא בא למען ישרתוהו כי אם לשרת ולתת את נפשו כפר תחת רבים׃ ");
INSERT INTO heb_vpl VALUES ("MT20_29","070_20_29","MAT","20","29","29","ויהי כצאתם מיריחו וילך אחריו המון עם רב׃ ");
INSERT INTO heb_vpl VALUES ("MT20_30","070_20_30","MAT","20","30","30","והנה שני עורים ישבים על יד הדרך וישמעו כי ישוע עבר ויצעקו לאמר חננו נא אדנינו בן דוד׃ ");
INSERT INTO heb_vpl VALUES ("MT20_31","070_20_31","MAT","20","31","31","ויגער בם העם להשתיקם והם הרבו לצעק ויאמרו אדנינו חננו נא בן דוד׃ ");
INSERT INTO heb_vpl VALUES ("MT20_32","070_20_32","MAT","20","32","32","ויעמד ישוע ויקרא להם ויאמר מה תחפצו ואעשה לכם׃ ");
INSERT INTO heb_vpl VALUES ("MT20_33","070_20_33","MAT","20","33","33","ויאמרו אליו אדנינו עשה שתפקחנה עינינו׃ ");
INSERT INTO heb_vpl VALUES ("MT20_34","070_20_34","MAT","20","34","34","ורחמי ישוע נכמרו ויגע בעיניהם ופתאם החלו עיניהם לראות וילכו אחריו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_1","070_21_1","MAT","21","1","1","ויהי כאשר קרבו לירושלים ובאו אל בית פגי בהר הזיתים וישלח ישוע שנים מן התלמידים׃ ");
INSERT INTO heb_vpl VALUES ("MT21_2","070_21_2","MAT","21","2","2","ויאמר אליהם לכו אל הכפר אשר ממולכם שם תמצאו אתון אסורה ועיר עמה התירו אתם והביאו אלי׃ ");
INSERT INTO heb_vpl VALUES ("MT21_3","070_21_3","MAT","21","3","3","וכי יאמר איש אליכם דבר ואמרתם האדון צריך להם וברגע ישלחם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_4","070_21_4","MAT","21","4","4","וכל זאת היתה למלאת הנאמר ביד הנביא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT21_5","070_21_5","MAT","21","5","5","אמרו לבת ציון הנה מלכך יבוא לך עני ורכב על חמור ועל עיר בן אתנות׃ ");
INSERT INTO heb_vpl VALUES ("MT21_6","070_21_6","MAT","21","6","6","וילכו התלמידים ויעשו כאשר צוה אתם ישוע׃ ");
INSERT INTO heb_vpl VALUES ("MT21_7","070_21_7","MAT","21","7","7","ויביאו את האתון ואת העיר וישימו עליהם את בגדיהם וירכיבהו עליהם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_8","070_21_8","MAT","21","8","8","ורב ההמון פרשו את בגדיהם על הדרך ואחרים כרתו ענפי עצים וישטחום על הדרך׃ ");
INSERT INTO heb_vpl VALUES ("MT21_9","070_21_9","MAT","21","9","9","והמון העם ההלכים לפניו ואחריו קראו לאמר הושע נא לבן דוד ברוך הבא בשם יהוה הושע נא במרומים׃ ");
INSERT INTO heb_vpl VALUES ("MT21_10","070_21_10","MAT","21","10","10","ויהי בבאו ירושלים ותהם כל העיר לאמר מי הוא זה׃ ");
INSERT INTO heb_vpl VALUES ("MT21_11","070_21_11","MAT","21","11","11","ויאמרו המני העם זה הוא הנביא ישוע מנצרת אשר בגליל׃ ");
INSERT INTO heb_vpl VALUES ("MT21_12","070_21_12","MAT","21","12","12","ויבא ישוע אל מקדש האלהים ויגרש משם את כל המוכרים והקונים במקדש ויהפך את שלחנות השלחנים ואת מושבות מכרי היונים׃ ");
INSERT INTO heb_vpl VALUES ("MT21_13","070_21_13","MAT","21","13","13","ויאמר אליהם הן כתוב כי ביתי בית תפלה יקרא ואתם שמתם אתו למערת פריצים׃ ");
INSERT INTO heb_vpl VALUES ("MT21_14","070_21_14","MAT","21","14","14","ויגשו אליו עורים ופסחים במקדש וירפאם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_15","070_21_15","MAT","21","15","15","ויהי כראות הכהנים הגדולים והסופרים את הנפלאות אשר עשה ואת הילדים הצעקים במקדש ואמרים הושע נא לבן דוד ויחר להם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_16","070_21_16","MAT","21","16","16","ויאמרו אליו השמע אתה את אשר אלה אמרים ויאמר ישוע אליהם כן הכי קרא לא קראתם מפי עוללים ויונקים יסדת עז׃ ");
INSERT INTO heb_vpl VALUES ("MT21_17","070_21_17","MAT","21","17","17","ויעזבם ויצא מחוץ לעיר אל בית היני וילן שם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_18","070_21_18","MAT","21","18","18","ובבקר שב אל העיר והוא רעב׃ ");
INSERT INTO heb_vpl VALUES ("MT21_19","070_21_19","MAT","21","19","19","וירא תאנה אחת על הדרך ויקרב אליה ולא מצא בה מאומה מלבד העלים ויאמר אליה מעתה לא יהיה ממך פרי עד עולם ותיבש התאנה פתאם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_20","070_21_20","MAT","21","20","20","ויראו התלמידים ויתמהו לאמר איך יבשה התאנה פתאם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_21","070_21_21","MAT","21","21","21","ויען ישוע ויאמר אליהם אמן אמר אני לכם אם תהיה לכם אמונה ואינכם מסתפקים לא לבד כמעשה התאנה הזאת תעשו כי גם באמרכם אל ההר הזה הנשא והעתק אל תוך הים היו תהיה׃ ");
INSERT INTO heb_vpl VALUES ("MT21_22","070_21_22","MAT","21","22","22","וכל אשר תשאלו בתפלה ואתם מאמינים תקחהו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_23","070_21_23","MAT","21","23","23","ויבא אל המקדש ויהי בלמדו שם ויגשו אליו ראשי הכהנים וזקני העם ויאמרו באי זו רשות אתה עשה אלה ומי נתן לך הרשות הזאת׃ ");
INSERT INTO heb_vpl VALUES ("MT21_24","070_21_24","MAT","21","24","24","ויען יושע ויאמר אליהם גם אני אשאלה אתכם דבר אחד אשר אם תגידו אתו לי גם אני אגיד לכם באי זו רשות אני עשה אלה׃ ");
INSERT INTO heb_vpl VALUES ("MT21_25","070_21_25","MAT","21","25","25","טבילת יוחנן מאין היתה המן השמים אם מבני אדם ויחשבו בלבבם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT21_26","070_21_26","MAT","21","26","26","אם נאמר מן השמים יאמר אלינו מדוע אפוא לא האמונתם לו ואם נאמר מבני אדם יראים אנחנו את המון העם כי כלם חשבים את יוחנן לנביא׃ ");
INSERT INTO heb_vpl VALUES ("MT21_27","070_21_27","MAT","21","27","27","ויענו את ישוע ויאמרו לא ידענו ויאמר אליהם גם אני לא אמר לכם באי זו רשות אני עשה אלה׃ ");
INSERT INTO heb_vpl VALUES ("MT21_28","070_21_28","MAT","21","28","28","אבל מה דעתכם איש היה ולו שני בנים ויגש אל הראשון ויאמר בני לך היום ועבד בכרמי׃ ");
INSERT INTO heb_vpl VALUES ("MT21_29","070_21_29","MAT","21","29","29","ויען ויאמר אינני אבא ואחרי כן נחם וילך׃ ");
INSERT INTO heb_vpl VALUES ("MT21_30","070_21_30","MAT","21","30","30","ויגש אל השני וידבר כזאת גם אליו ויען ויאמר הנני אדני ולא הלך׃ ");
INSERT INTO heb_vpl VALUES ("MT21_31","070_21_31","MAT","21","31","31","מי משניהם עשה את רצון האב ויאמרו אליו הראשון ויאמר להם ישוע אמן אמר אני לכם המוכסים והזונות יקדמו אתכם לבוא אל מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("MT21_32","070_21_32","MAT","21","32","32","כי יוחנן בא אליכם בדרך צדקה ולא האמנתם לו אבל המוכסים והזונות הם האמינו לו ואתם ראיתם ולא שבתם אחרי כן להאמין לו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_33","070_21_33","MAT","21","33","33","משל אחר שמעו איש בעל בית היה ויטע האיש כרם ויעש גדר סביב לו ויחצב יקב ויבן מגדל בתוכו ויתנהו אל כרמים וילך בדרך מרחוק׃ ");
INSERT INTO heb_vpl VALUES ("MT21_34","070_21_34","MAT","21","34","34","ויהי בהגיע עת האסיף וישלח עבדיו אל הכרמים לקחת את פריו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_35","070_21_35","MAT","21","35","35","ויחזיקו הכרמים בעבדיו את זה הכו ואת זה הרגו ואת זה סקלו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_36","070_21_36","MAT","21","36","36","ויוסף שלח עבדים אחרים רבים מן הראשונים ויעשו ככה גם להם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_37","070_21_37","MAT","21","37","37","ובאחרונה שלח אליהם את בנו באמרו מפני בני יגורו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_38","070_21_38","MAT","21","38","38","ויהי כראות הכרמים את הבן ויאמרו איש אל אחיו זה הוא היורש לכו ונהרגהו ונאחזה בנחלתו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_39","070_21_39","MAT","21","39","39","ויחזיקו בו וידחפוהו אל מחוץ לכרם ויהרגו אתו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_40","070_21_40","MAT","21","40","40","והנה כבוא בעל הכרם מה יעשה לכרמים ההם׃ ");
INSERT INTO heb_vpl VALUES ("MT21_41","070_21_41","MAT","21","41","41","ויאמרו אליו ירע לרעים ויאבדם ואת הכרם יתן לכרמים אחרים אשר ישיבו לו את הפרי בעתו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_42","070_21_42","MAT","21","42","42","ויאמר ישוע אליהם הכי קרא לא קראתם בכתובים אבן מאסו הבונים היתה לראש פנה מאת יהוה היתה זאת היא נפלאת בעינינו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_43","070_21_43","MAT","21","43","43","על כן אני אמר לכם כי תקח מכם מלכות האלהים ותנתן לגוי אשר יעשה את פריה׃ ");
INSERT INTO heb_vpl VALUES ("MT21_44","070_21_44","MAT","21","44","44","והנפל על האבן ההיא ישבר ואשר תפל עליו תשחקהו׃ ");
INSERT INTO heb_vpl VALUES ("MT21_45","070_21_45","MAT","21","45","45","ויהי כשמע הכהנים הגדולים והפרושים את משליו ויבינו כי עליהם דבר׃ ");
INSERT INTO heb_vpl VALUES ("MT21_46","070_21_46","MAT","21","46","46","ויבקשו לתפשו אך יראו מפני המון העם כי לנביא חשבהו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_1","070_22_1","MAT","22","1","1","ויען ישוע ויסף דבר במשלים אליהם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT22_2","070_22_2","MAT","22","2","2","דומה מלכות השמים למלך בשר ודם אשר עשה חתנה לבנו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_3","070_22_3","MAT","22","3","3","וישלח את עבדיו לקרא הקרואים אל החתנה ולא אבו לבוא׃ ");
INSERT INTO heb_vpl VALUES ("MT22_4","070_22_4","MAT","22","4","4","ויסף שלח עבדים אחרים לאמר אמרו אל הקרואים הנה ערכתי את סעודתי שורי ומריאי טבוחים והכל מוכן באו אל החתנה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_5","070_22_5","MAT","22","5","5","והם לא שתו לבם לזאת וילכו להם זה אל שדהו וזה אל מסחרו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_6","070_22_6","MAT","22","6","6","והנשארים תפשו את עבדיו ויתעללו בם ויהרגום׃ ");
INSERT INTO heb_vpl VALUES ("MT22_7","070_22_7","MAT","22","7","7","ויקצף המלך וישלח צבאותיו ויאבד את המרצחים ההם ואת עירם שרף באש׃ ");
INSERT INTO heb_vpl VALUES ("MT22_8","070_22_8","MAT","22","8","8","אז אמר אל עבדיו הן החתנה מוכנה והקרואים לא היו ראוים לה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_9","070_22_9","MAT","22","9","9","לכן לכו נא אל ראשי הדרכים וכל איש אשר תמצאו קראו אתו אל החתנה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_10","070_22_10","MAT","22","10","10","ויצאו העבדים ההם אל הדרכים ויאספו את כל אשר מצאו גם רעים גם טובים וימלא בית החתנה מסבים׃ ");
INSERT INTO heb_vpl VALUES ("MT22_11","070_22_11","MAT","22","11","11","ויהי כבוא המלך לראות את המסבים וירא בהם איש ולא היה לבוש בגדי חתנה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_12","070_22_12","MAT","22","12","12","ויאמר אליו רעי איכה באת הנה ואין לך בגדי חתנה ויאלם׃ ");
INSERT INTO heb_vpl VALUES ("MT22_13","070_22_13","MAT","22","13","13","ויאמר המלך למשרתים אסרו ידיו ורגליו ונשאתם והשלכתם אותו אל החשך החיצון שם תהיה היללה וחרק השנים׃ ");
INSERT INTO heb_vpl VALUES ("MT22_14","070_22_14","MAT","22","14","14","כי רבים הם הקרואים ומעטים הנבחרים׃ ");
INSERT INTO heb_vpl VALUES ("MT22_15","070_22_15","MAT","22","15","15","וילכו הפרושים ויתיעצו איך יכשילהו בדבר׃ ");
INSERT INTO heb_vpl VALUES ("MT22_16","070_22_16","MAT","22","16","16","וישלחו אליו את תלמידיהם עם ההורדוסיים לאמר רבי ידענו כי איש אמת אתה ותורה באמת את דרך אלהים ולא תגור מפני איש כי אינך מכיר פני אדם׃ ");
INSERT INTO heb_vpl VALUES ("MT22_17","070_22_17","MAT","22","17","17","לכן הגידה נא לנו את דעתך הנכון לנו לתת מס אל הקיסר אם לא׃ ");
INSERT INTO heb_vpl VALUES ("MT22_18","070_22_18","MAT","22","18","18","וישוע ידע את רשעתם ויאמר החנפים מה תנסוני׃ ");
INSERT INTO heb_vpl VALUES ("MT22_19","070_22_19","MAT","22","19","19","הראוני את מטבע המס ויביאו לו דינר׃ ");
INSERT INTO heb_vpl VALUES ("MT22_20","070_22_20","MAT","22","20","20","ויאמר אליהם של מי הצורה הזאת והמכתב אשר עליו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_21","070_22_21","MAT","22","21","21","ויאמרו אליו של הקיסר ויאמר אליהם לכן תנו לקיסר את אשר לקיסר ולאלהים את אשר לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("MT22_22","070_22_22","MAT","22","22","22","וכשמעם את זאת תמהו ויעזבהו וילכו להם׃ ");
INSERT INTO heb_vpl VALUES ("MT22_23","070_22_23","MAT","22","23","23","ביום ההוא נגשו אליו צדוקים האמרים כי אין תחית המתים וישאלו אתו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT22_24","070_22_24","MAT","22","24","24","רבי הן משה אמר איש כי ימות ובנים אין לו אחיו ייבם את אשתו והקים זרע לאחיו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_25","070_22_25","MAT","22","25","25","ואתנו היו שבעה אחים והראשון נשא אשה וימת וזרע אין לו ויעזב את אשתו לאחיו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_26","070_22_26","MAT","22","26","26","וכמו כן גם השני וכן גם השלישי עד השבעה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_27","070_22_27","MAT","22","27","27","ואחרי כלם מתה גם האשה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_28","070_22_28","MAT","22","28","28","ועתה בתחית המתים למי מן השבעה תהיה לאשה כי לכלם היתה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_29","070_22_29","MAT","22","29","29","ויען ישוע ויאמר להם טעים אתם באשר אינכם יודעים את הכתובים וגם את גבורת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("MT22_30","070_22_30","MAT","22","30","30","כי בתחית המתים לא ישאו נשים ולא תנשאנה כי אם כמלאכי אלהים בשמים יהיו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_31","070_22_31","MAT","22","31","31","ועל דבר תחית המתים הלא קראתם את הנאמר לכם מפי האלהים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT22_32","070_22_32","MAT","22","32","32","אנכי אלהי אברהם ואלהי יצחק ואלהי יעקב והוא איננו אלהי המתים כי אם אלהי החיים׃ ");
INSERT INTO heb_vpl VALUES ("MT22_33","070_22_33","MAT","22","33","33","וישמע המון העם וישתומממו על תורתו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_34","070_22_34","MAT","22","34","34","והפרושים כשמעם כי סכר פי הצדוקים ויועדו יחדו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_35","070_22_35","MAT","22","35","35","ואחד מהם מבין בתורה שאל אתו לנסותו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT22_36","070_22_36","MAT","22","36","36","רבי אי זו מצוה גדולה היא בתורה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_37","070_22_37","MAT","22","37","37","ויאמר ישוע אליו ואהבת את יהוה אלהיך בכל לבבך ובכל נפשך ובכל מדעך׃ ");
INSERT INTO heb_vpl VALUES ("MT22_38","070_22_38","MAT","22","38","38","זאת היא המצוה הגדולה והראשונה׃ ");
INSERT INTO heb_vpl VALUES ("MT22_39","070_22_39","MAT","22","39","39","והשנית דומה לה ואהבת לרעך כמוך׃ ");
INSERT INTO heb_vpl VALUES ("MT22_40","070_22_40","MAT","22","40","40","בשתי המצות האלה כל התורה תלויה וגם הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("MT22_41","070_22_41","MAT","22","41","41","ויהי בהקהל הפרושים וישאלם ישוע לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT22_42","070_22_42","MAT","22","42","42","מה דעתכם על המשיח בן מי הוא ויאמרו אליו בן דוד׃ ");
INSERT INTO heb_vpl VALUES ("MT22_43","070_22_43","MAT","22","43","43","ויאמר אליהם ואיך קרא לו דוד ברוח אדון באמרו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_44","070_22_44","MAT","22","44","44","נאם יהוה לאדני שב לימיני עד אשית איביך הדם לרגליך׃ ");
INSERT INTO heb_vpl VALUES ("MT22_45","070_22_45","MAT","22","45","45","ועתה אם דוד קרא לו אדון איך הוא בנו׃ ");
INSERT INTO heb_vpl VALUES ("MT22_46","070_22_46","MAT","22","46","46","ולא יכל איש לענות אתו דבר ולא ערב עוד איש את לבו מן היום ההוא לשאל אותו׃ ");
INSERT INTO heb_vpl VALUES ("MT23_1","070_23_1","MAT","23","1","1","אז ידבר ישוע אל המון העם ואל תלמידיו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT23_2","070_23_2","MAT","23","2","2","על כסא משה ישבו הסופרים והפרושים׃ ");
INSERT INTO heb_vpl VALUES ("MT23_3","070_23_3","MAT","23","3","3","לכן כל אשר יאמרו לכם תשמרו לעשות אך כמעשיהם לא תעשו כי אמרים הם ואינם עשים׃ ");
INSERT INTO heb_vpl VALUES ("MT23_4","070_23_4","MAT","23","4","4","כי אסרים משאת כבדים ועמסים על שכם האנשים ולא יאבו להניעם אף באצבעם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_5","070_23_5","MAT","23","5","5","ועשים את כל מעשיהם להראות בהם לבני אדם כי מרחיבים את תפליהם ומגדילים את ציציותיהם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_6","070_23_6","MAT","23","6","6","ואהבים את הסבת הראש בסעודות ואת מושבי הראש בבתי הכנסיות׃ ");
INSERT INTO heb_vpl VALUES ("MT23_7","070_23_7","MAT","23","7","7","ואת שאלות שלומם בשוקים ואת אשר יקראו להם בני האדם רבי רבי׃ ");
INSERT INTO heb_vpl VALUES ("MT23_8","070_23_8","MAT","23","8","8","אולם אתם אל תקראו רבי כי אחד הוא רבכם המשיח ואתם אחים כלכם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_9","070_23_9","MAT","23","9","9","ואל תקראו אב לאיש מכם על האדמה כי אחד הוא אביכם אשר בשמים׃ ");
INSERT INTO heb_vpl VALUES ("MT23_10","070_23_10","MAT","23","10","10","גם אל תקראו מנהיגים כי אחד הוא מנהיגכם המשיח׃ ");
INSERT INTO heb_vpl VALUES ("MT23_11","070_23_11","MAT","23","11","11","והגדול בכם יהי לכם למשרת׃ ");
INSERT INTO heb_vpl VALUES ("MT23_12","070_23_12","MAT","23","12","12","כל המרומם את עצמו ישפל והמשפיל את עצמו ירומם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_13","070_23_13","MAT","23","13","13","אך אוי לכם הסופרים והפרושים החנפים כי סגרים אתם לפני האדם את מלכות השמים הן אתם לא תבאו בה ואת הבאים לא תניחו לבוא׃ ");
INSERT INTO heb_vpl VALUES ("MT23_14","070_23_14","MAT","23","14","14","אוי לכם הסופרים והפרושים החנפים כי בלעים אתם את בתי האלמנות ומאריכים בתפלה למראה עין תחת זאת משפט על יתר תקחו׃ ");
INSERT INTO heb_vpl VALUES ("MT23_15","070_23_15","MAT","23","15","15","אוי לכם הסופרים והפרושים החנפים כי סובבים אתם בים וביבשה למען גיר גר אחד וכי יתגיר תעשו אותו לבן גיהנם כפלים יותר מכם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_16","070_23_16","MAT","23","16","16","אוי לכם מנהלים עורים האמרים הנשבע בהיכל אין זאת מאומה והנשבע בזהב ההיכל יאשם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_17","070_23_17","MAT","23","17","17","אתם הכסילים והעורים כי מה הוא הגדול אם הזהב או ההיכל המקדש את הזהב׃ ");
INSERT INTO heb_vpl VALUES ("MT23_18","070_23_18","MAT","23","18","18","ואמרתם הנשבע במזבח אין מאומה והנשבע בקרבן אשר עליו יאשם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_19","070_23_19","MAT","23","19","19","אתם הכסילים והעורים כי מה הוא הגדול אם הקרבן או המזבח המקדש את הקרבן׃ ");
INSERT INTO heb_vpl VALUES ("MT23_20","070_23_20","MAT","23","20","20","לכן הנשבע במזבח נשבע בו ובכל אשר עליו׃ ");
INSERT INTO heb_vpl VALUES ("MT23_21","070_23_21","MAT","23","21","21","והנשבע בהיכל נשבע בו ובשוכן בתוכו׃ ");
INSERT INTO heb_vpl VALUES ("MT23_22","070_23_22","MAT","23","22","22","והנשבע בשמים נשבע בכסא אלהים ובישב עליו׃ ");
INSERT INTO heb_vpl VALUES ("MT23_23","070_23_23","MAT","23","23","23","אוי לכם הסופרים והפרושים החנפים כי מעשרים אתם את המנתא ואת השבת ואת הכמן ותניחו את החמורות בתורה את המשפט ואת החסד ואת האמונה והיה לכם לעשות את אלה ולא להניח גם את אלה׃ ");
INSERT INTO heb_vpl VALUES ("MT23_24","070_23_24","MAT","23","24","24","מנהלים עורים המסננים את היתוש ובלעים את הגמל׃ ");
INSERT INTO heb_vpl VALUES ("MT23_25","070_23_25","MAT","23","25","25","אוי לכם הסופרים והפרושים החנפים כי מטהרים אתם פני הכוס והקערה מחוץ ותוכן מלא גזל ופריצות׃ ");
INSERT INTO heb_vpl VALUES ("MT23_26","070_23_26","MAT","23","26","26","פרוש עור טהר בראשונה את תוך הכוס למען תטהר גם מחוץ׃ ");
INSERT INTO heb_vpl VALUES ("MT23_27","070_23_27","MAT","23","27","27","אוי לכם הסופרים והפרושים החנפים כי דמים אתם לקברים המסידים הנראים נאים מחוץ ותוכם מלא עצמות מתים וכל טמאה׃ ");
INSERT INTO heb_vpl VALUES ("MT23_28","070_23_28","MAT","23","28","28","ככה גם אתם מחוץ נראים כצדיקים אל בני אדם ותוככם מלא חנפה ואון׃ ");
INSERT INTO heb_vpl VALUES ("MT23_29","070_23_29","MAT","23","29","29","אוי לכם הסופרים והפרושים החנפים כי בונים אתם את קברי הנביאים ותיפו את מצבות קברות הצדיקים׃ ");
INSERT INTO heb_vpl VALUES ("MT23_30","070_23_30","MAT","23","30","30","ואמרתם אם היינו בימי אבותינו לא היתה ידנו עמהם לשפך דם הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("MT23_31","070_23_31","MAT","23","31","31","ובכן תעידו על נפשכם כי בנים אתם לרוצחי הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("MT23_32","070_23_32","MAT","23","32","32","אף אתם מלאו סאת אבותיכם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_33","070_23_33","MAT","23","33","33","נחשים אתם ילדי הצפעונים איכה תמלטו מדין גיהנם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_34","070_23_34","MAT","23","34","34","לכן הנני שלח לכם נביאים וחכמים וסופרים ומהם תהרגו ותצלבו ומהם תכו בשוטים בבתי כנסיותיכם ותרדפום מעיר לעיר׃ ");
INSERT INTO heb_vpl VALUES ("MT23_35","070_23_35","MAT","23","35","35","למען יבא עליכם כל דם נקי הנשפך בארץ מדם הבל הצדיק עד דם זכריה בן ברכיה אשר רצחתם אותו בין ההיכל ולמזבח׃ ");
INSERT INTO heb_vpl VALUES ("MT23_36","070_23_36","MAT","23","36","36","אמן אמר אני לכם בא יבא כל אלה על הדור הזה׃ ");
