INSERT INTO heb_vpl VALUES ("MT23_38","070_23_38","MAT","23","38","38","הנה ביתכם יעזב לכם שמם׃ ");
INSERT INTO heb_vpl VALUES ("MT23_39","070_23_39","MAT","23","39","39","כי אני אמר לכם ראה לא תראוני מעתה עד אשר תאמרו ברוך הבא בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("MT24_1","070_24_1","MAT","24","1","1","ויצא ישוע מן המקדש ללכת לדרכו ויגשו תלמידיו להראותו את בניני המקדש׃ ");
INSERT INTO heb_vpl VALUES ("MT24_2","070_24_2","MAT","24","2","2","ויען ישוע ויאמר אליהם הראיתם את כל אלה אמן אמר אני לכם לא תשאר פה אבן על אבן אשר לא תתפרק׃ ");
INSERT INTO heb_vpl VALUES ("MT24_3","070_24_3","MAT","24","3","3","וישב על הר הזיתים ויגשו אליו התלמידים לבדם ויאמרו אמר נא לנו מתי תהיה זאת ומה הוא אות בואך ואות קץ העולם׃ ");
INSERT INTO heb_vpl VALUES ("MT24_4","070_24_4","MAT","24","4","4","ויען ישוע ויאמר להם ראו פן יתעה אתכם איש׃ ");
INSERT INTO heb_vpl VALUES ("MT24_5","070_24_5","MAT","24","5","5","כי רבים יבאו בשמי לאמר אני הוא המשיח והתעו רבים׃ ");
INSERT INTO heb_vpl VALUES ("MT24_6","070_24_6","MAT","24","6","6","ואתם עתידים לשמע מלחמות ושמעות מלחמה ראו פן תבהלו כי היו תהיה כל זאת אך עדן אין הקץ׃ ");
INSERT INTO heb_vpl VALUES ("MT24_7","070_24_7","MAT","24","7","7","כי יקום גוי על גוי וממלכה על ממלכה והיה רעב ודבר ורעש הנה והנה׃ ");
INSERT INTO heb_vpl VALUES ("MT24_8","070_24_8","MAT","24","8","8","וכל אלה רק ראשית החבלים׃ ");
INSERT INTO heb_vpl VALUES ("MT24_9","070_24_9","MAT","24","9","9","אז ימסרו אתכם לעני והמיתו אתכם והייתם שנואים לכל הגוים למען שמי׃ ");
