INSERT INTO heb_vpl VALUES ("MT24_11","070_24_11","MAT","24","11","11","ונביאי שקר רבים יקומו והתעו רבים׃ ");
INSERT INTO heb_vpl VALUES ("MT24_12","070_24_12","MAT","24","12","12","ומפני אשר ירבה הרשע תפוג אהבת רבים׃ ");
INSERT INTO heb_vpl VALUES ("MT24_13","070_24_13","MAT","24","13","13","והמחכה עד עת קץ הוא יושע׃ ");
INSERT INTO heb_vpl VALUES ("MT24_14","070_24_14","MAT","24","14","14","ותקרא בשורת המלכות הזאת בתבל כלה לעדות לכל הגוים ואחר יבוא הקץ׃ ");
