INSERT INTO heb_vpl VALUES ("MT24_16","070_24_16","MAT","24","16","16","אז נוס ינוסו אנשי יהודה אל ההרים׃ ");
INSERT INTO heb_vpl VALUES ("MT24_17","070_24_17","MAT","24","17","17","ואשר על הגג אל ירד לשאת דבר מביתו׃ ");
INSERT INTO heb_vpl VALUES ("MT24_18","070_24_18","MAT","24","18","18","ואשר בשדה אל ישב הביתה לשאת את מלבושו׃ ");
INSERT INTO heb_vpl VALUES ("MT24_19","070_24_19","MAT","24","19","19","ואוי להרות ולמיניקות בימים ההם׃ ");
INSERT INTO heb_vpl VALUES ("MT24_20","070_24_20","MAT","24","20","20","אך התפללו אשר מנוסתכם לא תהיה בחרף ולא בשבת׃ ");
INSERT INTO heb_vpl VALUES ("MT24_21","070_24_21","MAT","24","21","21","כי אז תהיה צרה גדולה אשר כמוה לא נהיתה מראשית העולם עד עתה וכמוה לא תהיה עוד׃ ");
INSERT INTO heb_vpl VALUES ("MT24_22","070_24_22","MAT","24","22","22","ולולא נקצרו הימים ההם לא יושע כל בשר אך למען הבחירים יקצרו הימים ההם׃ ");
INSERT INTO heb_vpl VALUES ("MT24_23","070_24_23","MAT","24","23","23","וכי יאמר אליכם איש בעת ההיא הנה פה המשיח או הנו שם אל תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("MT24_24","070_24_24","MAT","24","24","24","כי יקומו משיחי שקר ונביאי שקר ויתנו אתות גדלות ומופתים למען התעות אף את הבחירים אם יוכלו׃ ");
INSERT INTO heb_vpl VALUES ("MT24_25","070_24_25","MAT","24","25","25","הנה מראש הגדתי לכם׃ ");
INSERT INTO heb_vpl VALUES ("MT24_26","070_24_26","MAT","24","26","26","לכן כי יאמרו אליכם הנו במדבר אל תצאו הנו בחדרים אל תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("MT24_27","070_24_27","MAT","24","27","27","כי כברק היוצא ממזרח ומאיר עד מערב כן יהיה גם בואו של בן האדם׃ ");
