INSERT INTO heb_vpl VALUES ("MT24_31","070_24_31","MAT","24","31","31","וישלח את מלאכיו בקול שופר גדול ויקבצו את בחיריו מארבע הרוחות למקצה השמים ועד קצה השמים׃ ");
INSERT INTO heb_vpl VALUES ("MT24_32","070_24_32","MAT","24","32","32","למדו נא את משל התאנה כאשר ירטב ענפה ופרחו עליה ידעתם כי קרוב הקיץ׃ ");
INSERT INTO heb_vpl VALUES ("MT24_33","070_24_33","MAT","24","33","33","כן גם אתם בראותכם את כל אלה דעו כי קרוב הוא לפתח׃ ");
INSERT INTO heb_vpl VALUES ("MT24_34","070_24_34","MAT","24","34","34","אמן אמר אני לכם כי לא יעבר הדור הזה עד אשר יהיו כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("MT24_35","070_24_35","MAT","24","35","35","השמים והארץ יעברו ודברי לא יעברון׃ ");
