INSERT INTO heb_vpl VALUES ("MT24_37","070_24_37","MAT","24","37","37","וכימי נח כן יהיה גם בואו של בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT24_38","070_24_38","MAT","24","38","38","כי כאשר בימי המבול היו אכלים ושתים נשאים נשים ונתנים אתן לאנשים עד היום אשר בא נח אל התבה׃ ");
INSERT INTO heb_vpl VALUES ("MT24_39","070_24_39","MAT","24","39","39","ולא ידעו עד בוא המבול וישחת את כלם כן יהיה גם בואו של בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT24_40","070_24_40","MAT","24","40","40","אז יהיו שנים בשדה אחד יאסף ואחד יעזב׃ ");
INSERT INTO heb_vpl VALUES ("MT24_41","070_24_41","MAT","24","41","41","שתים טוחנות ברחים אחת תאסף ואחת תעזב׃ ");
