INSERT INTO heb_vpl VALUES ("MT24_44","070_24_44","MAT","24","44","44","לכן היו נכונים גם אתם כי בשעה אשר לא תדמו יבוא בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT24_45","070_24_45","MAT","24","45","45","מי הוא אפוא העבד הנאמן והנבון אשר הפקידו אדניו על בני ביתו לתת להם את אכלם בעתו׃ ");
INSERT INTO heb_vpl VALUES ("MT24_46","070_24_46","MAT","24","46","46","אשרי העבד אשר אדניו בבואו ימצאהו עשה כן׃ ");
INSERT INTO heb_vpl VALUES ("MT24_47","070_24_47","MAT","24","47","47","אמן אמר אני לכם כי יפקידהו על כל אשר לו׃ ");
INSERT INTO heb_vpl VALUES ("MT24_48","070_24_48","MAT","24","48","48","ואם העבד הרע יאמר בלבו בשש אדני לבוא׃ ");
INSERT INTO heb_vpl VALUES ("MT24_49","070_24_49","MAT","24","49","49","ויחל להכות את חבריו ואכל ושתה עם הסובאים׃ ");
INSERT INTO heb_vpl VALUES ("MT24_50","070_24_50","MAT","24","50","50","בוא יבוא אדני העבד ההוא ביום לא יצפה ובשעה לא ידע׃ ");
INSERT INTO heb_vpl VALUES ("MT24_51","070_24_51","MAT","24","51","51","וישסף אתו וישים את חלקו עם החנפים שם תהיה היללה וחרק השנים׃ ");
INSERT INTO heb_vpl VALUES ("MT25_1","070_25_1","MAT","25","1","1","אז תדמה מלכות השמים לעשר עלמות אשר לקחו את נרותיהן ותצאנה לקראת החתן׃ ");
INSERT INTO heb_vpl VALUES ("MT25_2","070_25_2","MAT","25","2","2","חמש מהן היו חכמות וחמש כסילות׃ ");
INSERT INTO heb_vpl VALUES ("MT25_3","070_25_3","MAT","25","3","3","הכסילות לקחו את הנרות ולא לקחו עמהן שמן׃ ");
INSERT INTO heb_vpl VALUES ("MT25_4","070_25_4","MAT","25","4","4","והחכמות לקחו שמן בכליהן ואת נרותיהן׃ ");
INSERT INTO heb_vpl VALUES ("MT25_5","070_25_5","MAT","25","5","5","וכאשר בשש החתן לבוא ותנמנה כלן ותרדמנה׃ ");
INSERT INTO heb_vpl VALUES ("MT25_6","070_25_6","MAT","25","6","6","ויהי בחצות הלילה ותהי צוחה הנה החתן צאינה לקראתו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_7","070_25_7","MAT","25","7","7","אז התעוררו כל העלמות ההן ותיטבנה את נרותיהן׃ ");
INSERT INTO heb_vpl VALUES ("MT25_8","070_25_8","MAT","25","8","8","ותאמרנה הכסילות אל החכמות תנה לנו משמנכן כי יכבו נרותינו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_9","070_25_9","MAT","25","9","9","ותענינה החכמות לאמר לא כן פן יחסר לנו ולכן כי אם לכנה אל המוכרים וקנינה לכן׃ ");
INSERT INTO heb_vpl VALUES ("MT25_10","070_25_10","MAT","25","10","10","ויהי בעת לכתן לקנות ויבוא החתן והנכנות ללכת באו אתו אל החתנה ותסגר הדלת׃ ");
INSERT INTO heb_vpl VALUES ("MT25_11","070_25_11","MAT","25","11","11","ואחרי כן באו גם שאר העלמות ותאמרנה אדנינו אדנינו פתח לנו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_12","070_25_12","MAT","25","12","12","ויען ויאמר אמן אמר אני לכן לא ידעתי אתכן׃ ");
INSERT INTO heb_vpl VALUES ("MT25_13","070_25_13","MAT","25","13","13","לכן שקדו כי אינכם יודעים את היום ואת השעה אשר יבא בה בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("MT25_14","070_25_14","MAT","25","14","14","כי כמו איש נסע למרחוק אשר קרא אל עבדיו וימסר להם את רכושו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_15","070_25_15","MAT","25","15","15","ויתן לזה חמש ככרים ולזה שתים ולזה אחת לכל איש ואיש כפי ערכו וימהר ויסע משם׃ ");
INSERT INTO heb_vpl VALUES ("MT25_16","070_25_16","MAT","25","16","16","וילך האיש הלקח חמש ככרים ויסחר בהן ויעש לו חמש ככרים אחרות׃ ");
INSERT INTO heb_vpl VALUES ("MT25_17","070_25_17","MAT","25","17","17","וכן הלקח שתים גם הוא הרויח שתים אחרות׃ ");
INSERT INTO heb_vpl VALUES ("MT25_18","070_25_18","MAT","25","18","18","אך לקח האחת הלך ויחפר באדמה ויטמן את כסף אדניו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_19","070_25_19","MAT","25","19","19","ואחרי ימים רבים בא אדוני העבדים ההם ויעש חשבון עמהם׃ ");
INSERT INTO heb_vpl VALUES ("MT25_20","070_25_20","MAT","25","20","20","ויגש הלקח חמש הככרים ויבא חמש ככרים אחרות לאמר אדני חמש ככרים מסרת לי הנה חמש ככרים אחרות הרוחתי בהן׃ ");
INSERT INTO heb_vpl VALUES ("MT25_21","070_25_21","MAT","25","21","21","ויאמר אליו אדניו כן העבד הטוב והנאמן כי במעט נאמן היית ועל הרבה אפקידך בוא אל שמחת אדניך׃ ");
INSERT INTO heb_vpl VALUES ("MT25_22","070_25_22","MAT","25","22","22","ויגש גם לקח הככרים ויאמר אדני ככרים מסרת לי הנה ככרים הרוחתי בהן׃ ");
INSERT INTO heb_vpl VALUES ("MT25_23","070_25_23","MAT","25","23","23","ויאמר אליו אדניו היטבת העבד הטוב והנאמן במזער נאמן היית ועל הרבה אפקידך בוא אל שמחת אדניך׃ ");
INSERT INTO heb_vpl VALUES ("MT25_24","070_25_24","MAT","25","24","24","ויגש גם הלקח את הככר האחת ויאמר אדני ידעתיך כי איש קשה אתה קצר באשר לא זרעת וכנס מאשר לא פזרת׃ ");
INSERT INTO heb_vpl VALUES ("MT25_25","070_25_25","MAT","25","25","25","ואירא ואלך ואטמן את ככרך באדמה ועתה הא לך את אשר לך׃ ");
INSERT INTO heb_vpl VALUES ("MT25_26","070_25_26","MAT","25","26","26","ויען אדניו ויאמר אליו העבד הרע והעצל אתה ידעת כי קצר אנכי באשר לא זרעתי וכנס מאשר לא פזרתי׃ ");
INSERT INTO heb_vpl VALUES ("MT25_27","070_25_27","MAT","25","27","27","לכן היה עליך לתת את כספי לשלחנים ואני בבואי הייתי לקח את אשר לי בתרבית׃ ");
INSERT INTO heb_vpl VALUES ("MT25_28","070_25_28","MAT","25","28","28","על כן שאו ממנו את הככר ותנו אל האיש אשר לו עשר הככרים׃ ");
INSERT INTO heb_vpl VALUES ("MT25_29","070_25_29","MAT","25","29","29","כי כל איש אשר יש לו ינתן לו ויעדיף והאיש אשר אין לו גם את אשר לו יקח ממנו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_30","070_25_30","MAT","25","30","30","ואת עבד הבליעל השליכו אל החשך החיצון שם תהיה היללה וחרק השנים׃ ");
INSERT INTO heb_vpl VALUES ("MT25_31","070_25_31","MAT","25","31","31","והיה כי יבוא בן האדם בכבודו וכל המלאכים הקדשים עמו וישב על כסא כבודו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_32","070_25_32","MAT","25","32","32","ונאספו לפניו כל הגוים והפריד בינותם כאשר יפריד הרעה את הכבשים מן העתודים׃ ");
INSERT INTO heb_vpl VALUES ("MT25_33","070_25_33","MAT","25","33","33","והציב את הכבשים לימינו ואת העתודים לשמאלו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_34","070_25_34","MAT","25","34","34","אז יאמר המלך אל הנצבים לימינו באו ברוכי אבי ורשו את המלכות המוכנה לכם למן הוסד העולם׃ ");
INSERT INTO heb_vpl VALUES ("MT25_35","070_25_35","MAT","25","35","35","כי רעב הייתי ותאכילני צמא הייתי ותשקוני גר הייתי ותאספוני׃ ");
INSERT INTO heb_vpl VALUES ("MT25_36","070_25_36","MAT","25","36","36","ערום ותכסוני חולה ותבקרוני במשמר הייתי ותבאו אלי׃ ");
INSERT INTO heb_vpl VALUES ("MT25_37","070_25_37","MAT","25","37","37","וענו הצדיקים ואמרו אדנינו מתי ראינוך רעב ונכלכלך או צמא ונשקה אותך׃ ");
INSERT INTO heb_vpl VALUES ("MT25_38","070_25_38","MAT","25","38","38","ומתי ראינוך גר ונאספך או ערם ונכסך׃ ");
INSERT INTO heb_vpl VALUES ("MT25_39","070_25_39","MAT","25","39","39","ומתי ראינוך חולה או במשמר ונבא אליך׃ ");
INSERT INTO heb_vpl VALUES ("MT25_40","070_25_40","MAT","25","40","40","והמלך יענה ויאמר אליהם אמן אמר אני לכם מה שעשיתם לאחד מאחי הצעירים האלה לי עשיתם׃ ");
INSERT INTO heb_vpl VALUES ("MT25_41","070_25_41","MAT","25","41","41","ואז יאמר גם אל הנצבים לשמאלו לכו מעלי אתם הארורים אל אש עולם המוכנה לשטן ולמלאכיו׃ ");
INSERT INTO heb_vpl VALUES ("MT25_42","070_25_42","MAT","25","42","42","כי רעב הייתי ולא האכלתם אותי צמא הייתי ולא השקיתם אותי׃ ");
INSERT INTO heb_vpl VALUES ("MT25_43","070_25_43","MAT","25","43","43","גר הייתי ולא אספתם אותי ערום ולא כסיתם אותי חולה ובמשמר ולא בקרתם אותי׃ ");
INSERT INTO heb_vpl VALUES ("MT25_44","070_25_44","MAT","25","44","44","וענו גם הם ואמרו אדנינו מתי ראינוך רעב או צמא או גר או ערום או חולה או במשמר ולא שרתנוך׃ ");
INSERT INTO heb_vpl VALUES ("MT25_45","070_25_45","MAT","25","45","45","אז יענה אתם לאמר אמן אמר אני לכם מה שלא עשיתם לאחד מן הצעירים האלה גם לי לא עשיתם׃ ");
INSERT INTO heb_vpl VALUES ("MT25_46","070_25_46","MAT","25","46","46","וילכו אלה למעצבת עולם והצדיקים לחיי עולם׃ ");
INSERT INTO heb_vpl VALUES ("MT26_1","070_26_1","MAT","26","1","1","ויהי ככלות ישוע לדבר את כל הדברים האלה ויאמר אל תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_2","070_26_2","MAT","26","2","2","אתם ידעתם כי אחרי יומים יהיה הפסח ובן האדם ימסר להצלב׃ ");
INSERT INTO heb_vpl VALUES ("MT26_3","070_26_3","MAT","26","3","3","ויקהלו הכהנים הגדולים והסופרים וזקני העם אל חצר הכהן הגדול הנקרא קיפא׃ ");
INSERT INTO heb_vpl VALUES ("MT26_4","070_26_4","MAT","26","4","4","ויועצו יחדו לתפש את ישוע בערמה ולהמיתו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_5","070_26_5","MAT","26","5","5","ויאמרו אך לא בחג פן תהיה מהומה בעם׃ ");
INSERT INTO heb_vpl VALUES ("MT26_6","070_26_6","MAT","26","6","6","ויהי בהיות ישוע בית היני בבית שמעון המצרע׃ ");
INSERT INTO heb_vpl VALUES ("MT26_7","070_26_7","MAT","26","7","7","ותקרב אליו אשה ובידה פך שמן יקר מאד ותצק על ראשו בהסבו על השלחן׃ ");
INSERT INTO heb_vpl VALUES ("MT26_8","070_26_8","MAT","26","8","8","ויראו התלמידים ויתרעמו לאמר על מה האבוד הזה׃ ");
INSERT INTO heb_vpl VALUES ("MT26_9","070_26_9","MAT","26","9","9","כי השמן הזה היה ראוי להמכר במחיר רב ולתתו לעניים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_10","070_26_10","MAT","26","10","10","וידע ישוע ויאמר אליהם למה תוגו את האשה הלא מעשה טוב עשתה עמדי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_11","070_26_11","MAT","26","11","11","כי עניים תמיד עמכם ואנכי אינני אתכם תמיד׃ ");
INSERT INTO heb_vpl VALUES ("MT26_12","070_26_12","MAT","26","12","12","כי אשר שפכה את השמן הזה על גופי לחנט אותי עשתה זאת׃ ");
INSERT INTO heb_vpl VALUES ("MT26_13","070_26_13","MAT","26","13","13","אמן אמר אני לכם באשר תקרא הבשורה הזאת בכל העולם גם את אשר היא עשתה יספר לזכרון לה׃ ");
INSERT INTO heb_vpl VALUES ("MT26_14","070_26_14","MAT","26","14","14","וילך אחד משנים העשר הנקרא יהודה איש קריות אל ראשי הכהנים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_15","070_26_15","MAT","26","15","15","ויאמר מה תתנו לי ואמסרנו בידכם וישקלו לו שלשים כסף׃ ");
INSERT INTO heb_vpl VALUES ("MT26_16","070_26_16","MAT","26","16","16","ומן העת ההיא בקש תאנה למסר אותו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_17","070_26_17","MAT","26","17","17","ויהי בראשון לחג המצות ויגשו התלמידים אל ישוע לאמר באי זה מקום תחפץ כי נכין לך לאכל את הפסח׃ ");
INSERT INTO heb_vpl VALUES ("MT26_18","070_26_18","MAT","26","18","18","ויאמר לכו העירה אל פלני אלמני ואמרתם אליו כה אמר הרב עתי קרובה היא ובביתך אעשה את הפסח עם תלמידי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_19","070_26_19","MAT","26","19","19","ויעשו התלמידים כאשר צום ישוע ויכינו את הפסח׃ ");
INSERT INTO heb_vpl VALUES ("MT26_20","070_26_20","MAT","26","20","20","ויהי בערב ויסב עם שנים העשר׃ ");
INSERT INTO heb_vpl VALUES ("MT26_21","070_26_21","MAT","26","21","21","ובאכלם ויאמר אמן אמר אני לכם כי אחד מכם ימסרני׃ ");
INSERT INTO heb_vpl VALUES ("MT26_22","070_26_22","MAT","26","22","22","ויתעצבו מאד ויחלו איש ואיש לאמר לו האנכי הוא אדני׃ ");
INSERT INTO heb_vpl VALUES ("MT26_23","070_26_23","MAT","26","23","23","ויען ויאמר האיש אשר טבל עמי את ידו בקערה הוא ימסרני׃ ");
INSERT INTO heb_vpl VALUES ("MT26_24","070_26_24","MAT","26","24","24","הן בן האדם הלוך ילך לו ככתוב עליו אבל אוי לאיש ההוא אשר על ידו ימסר בן האדם טוב לאיש ההוא אם לא נולד׃ ");
INSERT INTO heb_vpl VALUES ("MT26_25","070_26_25","MAT","26","25","25","ויען יהודה המסר אותו ויאמר רבי האני הוא ויאמר אליו אתה אמרת׃ ");
INSERT INTO heb_vpl VALUES ("MT26_26","070_26_26","MAT","26","26","26","ובאכלם ויקח ישוע את הלחם ויברך ויבצע ויתן לתלמידים ויאמר קחו ואכלו זה הוא גופי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_27","070_26_27","MAT","26","27","27","ויקח את הכוס ויברך ויתן להם לאמר שתו ממנה כלכם׃ ");
INSERT INTO heb_vpl VALUES ("MT26_28","070_26_28","MAT","26","28","28","כי זה הוא דמי דם הברית החדשה הנשפך בעד רבים לסליחת חטאים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_29","070_26_29","MAT","26","29","29","ואני אמר לכם כי מעתה שתה לא אשתה מתנובת הגפן הזאת עד היום ההוא אשר אשתה אתה עמכם חדשה במלכות אבי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_30","070_26_30","MAT","26","30","30","ויהי אחרי גמרם את ההלל ויצאו אל הר הזיתים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_31","070_26_31","MAT","26","31","31","אז אמר אליהם ישוע אתם כלכם תכשלו בי בלילה הזה כי כתוב אכה את הרעה ותפוצין הצאן׃ ");
INSERT INTO heb_vpl VALUES ("MT26_32","070_26_32","MAT","26","32","32","ואחרי קומי אלך לפניכם הגלילה׃ ");
INSERT INTO heb_vpl VALUES ("MT26_33","070_26_33","MAT","26","33","33","ויען פטרוס ויאמר לו גם כי יכשלו בך כלם אני לעולם לא אכשל׃ ");
INSERT INTO heb_vpl VALUES ("MT26_34","070_26_34","MAT","26","34","34","ויאמר אליו ישוע אמן אמר אני לך כי בלילה הזה בטרם יקרא התרנגול תכחש בי שלש פעמים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_35","070_26_35","MAT","26","35","35","ויאמר אליו פטרוס גם כי יהיה עלי למות אתך כחש לא אכחש בך וכן אמרו גם כל התלמידים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_36","070_26_36","MAT","26","36","36","אחרי כן בא אתם ישוע אל חצר הנקרא גת שמני ויאמר אל התלמידים שבו לכם פה עד אשר אלך שמה והתפללתי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_37","070_26_37","MAT","26","37","37","ויקח אתו את פטרוס ואת שני בני זבדי ויחל להעצב ולמוג׃ ");
INSERT INTO heb_vpl VALUES ("MT26_38","070_26_38","MAT","26","38","38","ויאמר להם נפשי מרה לי עד מות עמדו פה ושקדו עמי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_39","070_26_39","MAT","26","39","39","וילך מעט האלה ויפל על פניו ויתפלל לאמר אבי אם יוכל להיות תעבר נא מעלי הכוס הזאת אך לא כרצוני כי אם כרצונך׃ ");
INSERT INTO heb_vpl VALUES ("MT26_40","070_26_40","MAT","26","40","40","ויבא אל התלמידים וימצאם ישנים ויאמר אל פטרוס הנה לא היה ביכלתכם לשקד עמי שעה אחת׃ ");
INSERT INTO heb_vpl VALUES ("MT26_41","070_26_41","MAT","26","41","41","שקדו והתפללו פן תבאו לידי נסיון הן הרוח היא חפצה והבשר הוא רפה׃ ");
INSERT INTO heb_vpl VALUES ("MT26_42","070_26_42","MAT","26","42","42","ויוסף ללכת לו שנית ויתפלל לאמר אבי אם לא תוכל הכוס הזאת לעבר ממני מבלי שתותי אתה יהי כרצונך׃ ");
INSERT INTO heb_vpl VALUES ("MT26_43","070_26_43","MAT","26","43","43","ויבא וימצאם גם בפעם הזאת ישנים כי עיניהם היו כבדות׃ ");
INSERT INTO heb_vpl VALUES ("MT26_44","070_26_44","MAT","26","44","44","ויניחם ויוסף ללכת ויתפלל שלישית באמרו עוד הפעם כדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("MT26_45","070_26_45","MAT","26","45","45","ויבא אל התלמידים ויאמר אליהם נומו מעתה ונוחו הנה השעה קרובה ובן האדם נמסר לידי חטאים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_46","070_26_46","MAT","26","46","46","קומו ונלכה הנה הלך וקרב המסר אותי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_47","070_26_47","MAT","26","47","47","עודנו מדבר והנה בא יהודה אחד משנים העשר ועמו המון רב ברחבות ובמקלות מאת ראשי הכהנים וזקני העם׃ ");
INSERT INTO heb_vpl VALUES ("MT26_48","070_26_48","MAT","26","48","48","והמסר אתו נתן להם אות לאמר האיש אשר אשקהו זה הוא תפשוהו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_49","070_26_49","MAT","26","49","49","ומיד נגש אל ישוע ויאמר שלום לך רבי וינשק לו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_50","070_26_50","MAT","26","50","50","ויאמר אליו ישוע רעי על מה באת ויגשו וישלחו את ידיהם בישוע ויתפשו אתו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_51","070_26_51","MAT","26","51","51","והנה אחד מן האנשים אשר עם ישוע שלח ידו וישלף חרבו ויך את עבד הכהן הגדול ויקצץ את אזנו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_52","070_26_52","MAT","26","52","52","ויאמר אליו ישוע השב את חרבך אל תערה כי כל אחזי חרב בחרב יאבדו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_53","070_26_53","MAT","26","53","53","או היחשב לבך כי לא יכלתי לשאל עתה מאת אבי והוא יצוה לי יותר משנים עשר לגיונות של מלאכים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_54","070_26_54","MAT","26","54","54","ואיככה אפוא ימלאו הכתובים כי כן היה תהיה׃ ");
INSERT INTO heb_vpl VALUES ("MT26_55","070_26_55","MAT","26","55","55","בשעה ההיא אמר ישוע אל המון העם כעל פריץ יצאתם בחרבות ובמקלות לתפשני ויום יום הייתי ישב ומלמד אצלכם במקדש ולא החזקתם בי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_56","070_26_56","MAT","26","56","56","וכל זאת היתה למלאת כתבי הנביאים אז עזבוהו התלמידים כלם וינוסו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_57","070_26_57","MAT","26","57","57","והאנשים אשר תפשו את ישוע הוליכהו אל קיפא הכהן הגדול אשר נקהלו שם הסופרים והזקנים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_58","070_26_58","MAT","26","58","58","ופטרוס הלך אחריו מרחוק עד לחצר הכהן הגדול ויבא פנימה וישב לו אצל המשרתים לראות את אחרית הדבר׃ ");
INSERT INTO heb_vpl VALUES ("MT26_59","070_26_59","MAT","26","59","59","והכהנים הגדולים והסופרים וכל הסנהדרין בקשו עדות שקר בישוע להמיתו ולא מצאו׃ ");
INSERT INTO heb_vpl VALUES ("MT26_60","070_26_60","MAT","26","60","60","ואף בעמד שם עדי שקר רבים לא מצאו ובאחרונה נגשו שני עדי שקר׃ ");
INSERT INTO heb_vpl VALUES ("MT26_61","070_26_61","MAT","26","61","61","ויאמרו זה אמר יש ביכלתי להרס את היכל האלהים ולשוב לבנותו בשלשת ימים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_62","070_26_62","MAT","26","62","62","ויקם הכהן הגדול ויאמר אליו האינך משיב דבר על אשר ענו בך אלה׃ ");
INSERT INTO heb_vpl VALUES ("MT26_63","070_26_63","MAT","26","63","63","וישוע החריש ויען הכהן הגדול ויאמר לו משביעך אני באלהים חיים שתאמר לנו אם אתה הוא המשיח בן האלהים׃ ");
INSERT INTO heb_vpl VALUES ("MT26_64","070_26_64","MAT","26","64","64","ויאמר אליו ישוע אתה אמרת אבל אני אמר לכם כי מעתה תראו את בן האדם ישב לימין הגבורה ובא עם ענני השמים׃ ");
