INSERT INTO heb_vpl VALUES ("MT26_66","070_26_66","MAT","26","66","66","מה דעתכם ויענו ויאמרו איש מות הוא׃ ");
INSERT INTO heb_vpl VALUES ("MT26_67","070_26_67","MAT","26","67","67","וירקו בפניו ויכהו באגרוף ואחרים הכהו על הלחי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_68","070_26_68","MAT","26","68","68","ויאמרו הנבא לנו המשיח מי הוא המכה אותך׃ ");
INSERT INTO heb_vpl VALUES ("MT26_69","070_26_69","MAT","26","69","69","ופטרוס ישב מחוץ לבית בחצר ותגש אליו שפחה לאמר גם אתה היית עם ישוע הגלילי׃ ");
INSERT INTO heb_vpl VALUES ("MT26_70","070_26_70","MAT","26","70","70","ויכחש בפני כלם לאמר לא ידעתי מה את אמרת׃ ");
