INSERT INTO heb_vpl VALUES ("MT27_1","070_27_1","MAT","27","1","1","ויהי לפנות הבקר ויתיעצו כל ראשי הכהנים וזקני העם על ישוע להמיתו׃ ");
INSERT INTO heb_vpl VALUES ("MT27_2","070_27_2","MAT","27","2","2","ויאסרו אתו ויוליכהו משם וימסרהו אל פונטיוס פילטוס ההגמון׃ ");
INSERT INTO heb_vpl VALUES ("MT27_3","070_27_3","MAT","27","3","3","וירא יהודה המסר אותו כי הרשיעהו וינחם וישב את שלשים הכסף אל הכהנים הגדולים והזקנים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MT27_4","070_27_4","MAT","27","4","4","חטאתי כי דם נקי הסגרתי והם אמרו מה לנו ולזאת אתה תראה׃ ");
INSERT INTO heb_vpl VALUES ("MT27_5","070_27_5","MAT","27","5","5","וישלך את הכסף אל ההיכל ויפן וילך ויחנק׃ ");
INSERT INTO heb_vpl VALUES ("MT27_6","070_27_6","MAT","27","6","6","ויקחו ראשי הכהנים את הכסף ויאמרו לא נכון לנו לתתו אל ארון הקרבן כי מחיר דמים הוא׃ ");
INSERT INTO heb_vpl VALUES ("MT27_7","070_27_7","MAT","27","7","7","ויתיעצו ויקנו בו את שדה היוצר לקבורת הגרים׃ ");
