INSERT INTO heb_vpl VALUES ("MT27_10","070_27_10","MAT","27","10","10","ויתנו אתם אל שדה היוצר כאשר צוני יהוה׃ ");
INSERT INTO heb_vpl VALUES ("MT27_11","070_27_11","MAT","27","11","11","וישוע העמד לפני ההגמון וישאלהו ההגמון לאמר האתה הוא מלך היהודים ויאמר ישוע אתה אמרת׃ ");
INSERT INTO heb_vpl VALUES ("MT27_12","070_27_12","MAT","27","12","12","וידברו עליו שטנה הכהנים הגדולים והזקנים והוא לא ענה דבר׃ ");
