INSERT INTO heb_vpl VALUES ("MT27_20","070_27_20","MAT","27","20","20","והכהנים הגדולים והזקנים פתו את המון העם לשאל להם את בר אבא ולאבד את ישוע׃ ");
INSERT INTO heb_vpl VALUES ("MT27_21","070_27_21","MAT","27","21","21","ויען ההגמון ויאמר אליהם את מי משניהם תחפצו כי אפטר לכם ויאמרו את בר אבא׃ ");
