INSERT INTO heb_vpl VALUES ("MT27_56","070_27_56","MAT","27","56","56","ובתוכן מרים המגדלית ומרים אם יעקב ויוסי ואם בני זבדי׃ ");
INSERT INTO heb_vpl VALUES ("MT27_57","070_27_57","MAT","27","57","57","ויהי בערב ויבא איש עשיר מן הרמתים ושמו יוסף וגם הוא היה מתלמידי ישוע׃ ");
