INSERT INTO heb_vpl VALUES ("MT27_65","070_27_65","MAT","27","65","65","ויאמר אליהם פילטוס הנה לכם אנשי משמר לכו סכרוהו כדעתכם׃ ");
INSERT INTO heb_vpl VALUES ("MT27_66","070_27_66","MAT","27","66","66","וילכו ויסכרו את מבוא הקבר ויחתמו את האבן ויעמידו עליו את המשמר׃ ");
