INSERT INTO heb_vpl VALUES ("MT28_2","070_28_2","MAT","28","2","2","והנה רעש גדול היה כי מלאך יהוה ירד מן השמים ויגש ויגל את האבן מן הפתח וישב עליה׃ ");
