INSERT INTO heb_vpl VALUES ("MK2_22","071_2_22","MRK","2","22","22","ואין נתן יין חדש בנאדות בלים כי אז יבקע היין את הנאדות והיין ישפך והנאדות יאבדו אבל בנאדות חדשים ינתן היין החדש׃ ");
INSERT INTO heb_vpl VALUES ("MK2_23","071_2_23","MRK","2","23","23","ויהי כעברו בשבת בין הקמה ויחלו תלמידיו לקטף מלילת בלכתם׃ ");
