INSERT INTO heb_vpl VALUES ("MK5_18","071_5_18","MRK","5","18","18","ויהי ברדתו אל האניה התחנן אליו האיש אשר היה אחוז שדים לתתו לשבת עמו׃ ");
INSERT INTO heb_vpl VALUES ("MK5_19","071_5_19","MRK","5","19","19","ולא הניח לו כי אם אמר אליו שוב לביתך אל בני משפחתך והגד להם את הגדלות אשר עשה לך יהוה ויחנך׃ ");
INSERT INTO heb_vpl VALUES ("MK5_20","071_5_20","MRK","5","20","20","וילך לו ויחל לקרא בעשר הערים את הגדלות אשר עשה לו ישוע ויתמהו כלם׃ ");
INSERT INTO heb_vpl VALUES ("MK5_21","071_5_21","MRK","5","21","21","וישב ישוע לעבר באניה אל עבר הים ויקהל אליו המון רב והוא על שפת הים׃ ");
INSERT INTO heb_vpl VALUES ("MK5_22","071_5_22","MRK","5","22","22","והנה בא אחד מראשי הכנסת ושמו יאיר וירא אתו ויפל לרגליו׃ ");
INSERT INTO heb_vpl VALUES ("MK5_23","071_5_23","MRK","5","23","23","ויתחנן אליו מאד לאמר בתי הקטנה חלתה עד למות אנא בוא נא ושים ידיך עליה למען תרפא ותחיה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_24","071_5_24","MRK","5","24","24","וילך אתו וילכו אחריו המון רב וידחקהו׃ ");
INSERT INTO heb_vpl VALUES ("MK5_25","071_5_25","MRK","5","25","25","ואשה היתה זבת דם שתים עשרה שנה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_26","071_5_26","MRK","5","26","26","והיא סבלה הרבה תחת ידי רפאים רבים והוציאה את כל אשר לה ולא להועיל ויהי חליה חזק מאד׃ ");
INSERT INTO heb_vpl VALUES ("MK5_27","071_5_27","MRK","5","27","27","ויהי כשמעה את שמע ישוע ותבוא בהמון העם מאחריו ותגע בבגדו׃ ");
INSERT INTO heb_vpl VALUES ("MK5_28","071_5_28","MRK","5","28","28","כי אמרה רק אם אגע בבגדיו אושע׃ ");
INSERT INTO heb_vpl VALUES ("MK5_29","071_5_29","MRK","5","29","29","וייבש מקור דמיה פתאם ותבן בבשרה כי נרפא נגעה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_30","071_5_30","MRK","5","30","30","וברגע ידע ישוע בנפשו כי גבורה יצאה ממנו ויפן בתוך העם ויאמר מי נגע בבגדי׃ ");
INSERT INTO heb_vpl VALUES ("MK5_31","071_5_31","MRK","5","31","31","ויאמר אליו תלמידיו אתה ראה את ההמון דוחק אתך ואמרת מי נגע בי׃ ");
INSERT INTO heb_vpl VALUES ("MK5_32","071_5_32","MRK","5","32","32","ויבט סביב לראות את אשר עשתה זאת׃ ");
INSERT INTO heb_vpl VALUES ("MK5_33","071_5_33","MRK","5","33","33","ותירא האשה ותחרד כי ידעה את אשר נעשה לה ותבא ותפל לפניו ותגד לו את האמת כלה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_34","071_5_34","MRK","5","34","34","ויאמר אליה בתי אמונתך הושיעה לך לכי לשלום וחיית מנגעך׃ ");
INSERT INTO heb_vpl VALUES ("MK5_35","071_5_35","MRK","5","35","35","עודנו מדבר והנה באים מבית ראש הכנסת לאמר בתך מתה למה תטריח עוד את המורה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_36","071_5_36","MRK","5","36","36","וכשמע ישוע את הדבר אשר דברו ויאמר אל ראש הכנסת אל תירא רק האמינה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_37","071_5_37","MRK","5","37","37","ולא הניח לאיש ללכת אתו בלתי אם לפטרוס וליעקב וליוחנן אחי יעקב׃ ");
INSERT INTO heb_vpl VALUES ("MK5_38","071_5_38","MRK","5","38","38","ויבא בית ראש הכנסת וירא המון הבכים והמיללים הרבה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_39","071_5_39","MRK","5","39","39","ובבאו אמר אליהם מה תהמו ותבכו הנערה לא מתה אך ישנה היא׃ ");
INSERT INTO heb_vpl VALUES ("MK5_40","071_5_40","MRK","5","40","40","וישחקו לו והוא גרש את כלם ויקח את אבי הנערה ואת אמה ואת אשר אתו ויבא החדרה אשר שם שכבת הנערה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_41","071_5_41","MRK","5","41","41","ויאחז ביד הנערה ויאמר אליה טליתא קומי אשר פרושו הילדה אני אמר לך קומי נא׃ ");
INSERT INTO heb_vpl VALUES ("MK5_42","071_5_42","MRK","5","42","42","ומיד קמה הילדה ותתהלך והיא בת שתים עשרה שנה וישמו שמה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("MK5_43","071_5_43","MRK","5","43","43","ויזהר אותם מאד שלא יודע הדבר לאיש ויאמר לתת לה לאכול׃ ");
INSERT INTO heb_vpl VALUES ("MK6_1","071_6_1","MRK","6","1","1","ויצא משם ויבא אל ארצו וילכו אחריו תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_2","071_6_2","MRK","6","2","2","וביום השבת החל ללמד בבית הכנסת וישמעו רבים וישתוממו לאמר מאין לזה כאלה ומה היא החכמה הנתונה לו עד אשר נעשו גבורות כאלה על ידיו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_3","071_6_3","MRK","6","3","3","הלא זה הוא החרש בן מרים ואחי יעקב ויוסי ויהודה ושמעון והלא אחיותיו אתנו פה ויהי להם למכשול׃ ");
INSERT INTO heb_vpl VALUES ("MK6_4","071_6_4","MRK","6","4","4","ויאמר אליהם ישוע אין הנביא נקלה כי אם בארצו ובין קרוביו ובביתו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_5","071_6_5","MRK","6","5","5","ולא יכל לעשות שם פלא רק על חלשים מעטים שם את ידיו וירפאם׃ ");
INSERT INTO heb_vpl VALUES ("MK6_6","071_6_6","MRK","6","6","6","ויתמה על חסרון אמונתם ויסב בכפרים סבוב ולמד׃ ");
INSERT INTO heb_vpl VALUES ("MK6_7","071_6_7","MRK","6","7","7","ויקרא אל שנים העשר ויחל לשלח אותם שנים שנים ויתן להם שלטן על רוחות הטמאה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_8","071_6_8","MRK","6","8","8","ויצו אותם אשר לא ישאו מאומה לדרך זולתי מקל לבדו לא תרמיל ולא לחם ולא נחשת בחגורה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_9","071_6_9","MRK","6","9","9","רק להיות נעולי סנדל ושתי כתנות לא ילבשו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_10","071_6_10","MRK","6","10","10","ויאמר אליהם במקום אשר תבאו בית איש שבו בו עד כי תצאו משם׃ ");
INSERT INTO heb_vpl VALUES ("MK6_11","071_6_11","MRK","6","11","11","וכל אשר לא יקבלו אתכם ולא ישמעו אליכם צאו משם ונערו את עפר כפות רגליכם לעדות להם אמן אני אמר לכם לסדם ולעמרה יקל ביום הדין מן העיר ההיא׃ ");
INSERT INTO heb_vpl VALUES ("MK6_12","071_6_12","MRK","6","12","12","ויצאו ויקראו לשוב בתשובה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_13","071_6_13","MRK","6","13","13","ויגרשו שדים רבים ויסוכו בשמן חלשים רבים וירפאום׃ ");
INSERT INTO heb_vpl VALUES ("MK6_14","071_6_14","MRK","6","14","14","וישמע עליו המלך הורדוס כי נודע שמו ויאמר יוחנן הטובל קם מן המתים ועל כן פעלות בו הגבורות׃ ");
INSERT INTO heb_vpl VALUES ("MK6_15","071_6_15","MRK","6","15","15","ואחרים אמרו כי הוא אליהו ואחרים אמרו כי נביא הוא או כאחד הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("MK6_16","071_6_16","MRK","6","16","16","וישמע הורדוס ויאמר יוחנן אשר אנכי נשאתי את ראשו מעליו הוא קם מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("MK6_17","071_6_17","MRK","6","17","17","כי הוא הורודס שלח לתפש את יוחנן ויאסרהו בבית הסהר בגלל הורודיה אשת פילפוס אחיו כי אתה לקח לו לאשה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_18","071_6_18","MRK","6","18","18","יען אשר אמר יוחנן אל הורדוס אשת אחיך איננה מתרת לך׃ ");
INSERT INTO heb_vpl VALUES ("MK6_19","071_6_19","MRK","6","19","19","ותשטם אותו הורודיה ותבקש המיתו ולא יכלה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_20","071_6_20","MRK","6","20","20","כי הורדוס ירא את יוחנן בדעתו כי הוא איש צדיק וקדוש ויגן בעדו והרבה עשה בשמעו אליו ויאהב לשמע אתו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_21","071_6_21","MRK","6","21","21","ויבא היום המכשר כי הורדוס ביום הלדת אתו עשה משתה לגדוליו ולשרי האלפים ולראשי הגליל׃ ");
INSERT INTO heb_vpl VALUES ("MK6_22","071_6_22","MRK","6","22","22","ותבא בת הורודיה ותרקד ותיטב בעיני הורדוס ובעיני המסבים עמו ויאמר המלך אל הנערה שאלי ממני את אשר תחפצי ואתן לך׃ ");
INSERT INTO heb_vpl VALUES ("MK6_23","071_6_23","MRK","6","23","23","וישבע לה לאמר כל אשר תשאלי ממני אתן לך עד חצי מלכותי׃ ");
INSERT INTO heb_vpl VALUES ("MK6_24","071_6_24","MRK","6","24","24","ותצא ותאמר לאמה מה אשאל ותאמר את ראש יוחנן המטביל׃ ");
INSERT INTO heb_vpl VALUES ("MK6_25","071_6_25","MRK","6","25","25","ותמהר מאד לבוא אל המלך ותשאל לאמר רצוני אשר תתן לי עתה בקערה את ראש יוחנן המטביל׃ ");
INSERT INTO heb_vpl VALUES ("MK6_26","071_6_26","MRK","6","26","26","ויתעצב המלך מאד אך בעבור השבועה והמסבים עמו לא רצה להשיב פניה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_27","071_6_27","MRK","6","27","27","ומיד שלח המלך אחד הטבחים ויצוהו להביא את ראשו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_28","071_6_28","MRK","6","28","28","וילך ויכרת את ראשו בבית הסהר ויביאהו בקערה ויתנהו לנערה והנערה נתנה אתו אל אמה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_29","071_6_29","MRK","6","29","29","וישמעו תלמידיו ויבאו וישאו את גויתו וישימוה בקבר׃ ");
INSERT INTO heb_vpl VALUES ("MK6_30","071_6_30","MRK","6","30","30","ויקהלו השליחים אל ישוע ויגידו לו את כל אשר עשו ואת אשר למדו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_31","071_6_31","MRK","6","31","31","ויאמר אליהם באו אתם לבדד אל מקום חרבה ונוחו מעט כי רבים היו הבאים והיצאים עד לאין עת להם לאכול׃ ");
INSERT INTO heb_vpl VALUES ("MK6_32","071_6_32","MRK","6","32","32","וילכו משם באניה אל מקום חרבה לבדד׃ ");
INSERT INTO heb_vpl VALUES ("MK6_33","071_6_33","MRK","6","33","33","וההמון ראה אותם יצאים ויכירהו רבים וירוצו שמה ברגליהם מכל הערים ויעברו אותם ויאספו אליו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_34","071_6_34","MRK","6","34","34","ויצא וירא המון עם רב ויהמו מעיו עליהם כי היו כצאן אשר אין להם רעה ויחל ללמד אותם דברים הרבה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_35","071_6_35","MRK","6","35","35","ויהי כאשר רפה היום לערוב ויגשו אליו תלמידיו לאמר הנה המקום חרב והיום רד מאד׃ ");
INSERT INTO heb_vpl VALUES ("MK6_36","071_6_36","MRK","6","36","36","שלח אותם וילכו אל החצרים והכפרים מסביב לקנות להם לחם כי אין להם מה לאכל׃ ");
INSERT INTO heb_vpl VALUES ("MK6_37","071_6_37","MRK","6","37","37","ויען ויאמר אליהם תנו אתם להם לאכלה ויאמרו אליו הנלך לקנות לחם במאתים דינר ונתן להם לאכלה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_38","071_6_38","MRK","6","38","38","ויאמר אליהם כמה ככרות לחם יש לכם לכו וראו וידעו ויאמרו חמש ושני דגים׃ ");
INSERT INTO heb_vpl VALUES ("MK6_39","071_6_39","MRK","6","39","39","ויצו אותם לשבת כלם חברה חברה לבדה על ירק הדשא׃ ");
INSERT INTO heb_vpl VALUES ("MK6_40","071_6_40","MRK","6","40","40","וישבו להם שורות שורות למאות ולחמשים׃ ");
INSERT INTO heb_vpl VALUES ("MK6_41","071_6_41","MRK","6","41","41","ויקח את חמשת ככרות הלחם ואת שני הדגים וישא עיניו השמימה ויברך ויפרס את הלחם ויתן לתלמידיו לשום לפניהם ואת שני הדגים חלק לכלם׃ ");
INSERT INTO heb_vpl VALUES ("MK6_42","071_6_42","MRK","6","42","42","ויאכלו כלם וישבעו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_43","071_6_43","MRK","6","43","43","וישאו מן הפתותים מלוא סלים שנים עשר וגם מן הדגים׃ ");
INSERT INTO heb_vpl VALUES ("MK6_44","071_6_44","MRK","6","44","44","והאכלים מן הלחם היו כחמשת אלפי איש׃ ");
INSERT INTO heb_vpl VALUES ("MK6_45","071_6_45","MRK","6","45","45","ואחרי כן האיץ בתלמידיו לרדת באניה ולעבור לפניו אל עבר הים אל בית צידה עד שלחו את העם׃ ");
INSERT INTO heb_vpl VALUES ("MK6_46","071_6_46","MRK","6","46","46","ויהי אחר שלחו אתם ויעל ההרה להתפלל׃ ");
INSERT INTO heb_vpl VALUES ("MK6_47","071_6_47","MRK","6","47","47","ויהי ערב והאניה באה בתוך הים והוא לבדו ביבשה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_48","071_6_48","MRK","6","48","48","וירא אותם מתעמלים בשוטם כי הרוח לנגדם ויהי כעת האשמרת הרביעית ויבא אליהם מתהלך על פני הים ויואל לעבור לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("MK6_49","071_6_49","MRK","6","49","49","והם בראתם אתו מתהלך על פני הים חשבו כי מראה רוח הוא ויצעקו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_50","071_6_50","MRK","6","50","50","כי כלם ראוהו ויבהלו אז דבר אתם ויאמר אליהם חזקו כי אני הוא אל תיראו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_51","071_6_51","MRK","6","51","51","וירד אליהם אל האניה והרוח שככה וישתוממו עוד יותר בלבבם ויתמהו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_52","071_6_52","MRK","6","52","52","כי לא השכילו בדבר ככרות הלחם מפני טמטום לבבם׃ ");
INSERT INTO heb_vpl VALUES ("MK6_53","071_6_53","MRK","6","53","53","ויעברו את הים ויבאו ארצה גניסר ויקרבו אל היבשה׃ ");
INSERT INTO heb_vpl VALUES ("MK6_54","071_6_54","MRK","6","54","54","ויהי כצאתם מן האניה אז הכירהו׃ ");
INSERT INTO heb_vpl VALUES ("MK6_55","071_6_55","MRK","6","55","55","וירוצו בכל סביבותיהם ויחלו לשאת את החולים במשכבות אל כל מקום אשר שמעו כי שם הוא׃ ");
INSERT INTO heb_vpl VALUES ("MK6_56","071_6_56","MRK","6","56","56","ובכל מקום אשר יבא אל הכפרים או הערים ואל השדות שם שמו את החולים בחוצות ויתחננו לו כי יגעו רק בציצת בגדו והיה כל אשר נגעו ונושעו׃ ");
INSERT INTO heb_vpl VALUES ("MK7_1","071_7_1","MRK","7","1","1","ויקהלו אליו הפרושים ומן הסופרים אשר באו מירושלים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_2","071_7_2","MRK","7","2","2","ויהי כראותם מתלמידיו אכלים לחם בטמאת ידיהם בלא נטילה ויוכיחו אתם׃ ");
INSERT INTO heb_vpl VALUES ("MK7_3","071_7_3","MRK","7","3","3","כי הפרושים וכל היהודים לא יאכלו בלתי את רחצו את ידיהם עד הפרק באחזם בקבלת הזקנים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_4","071_7_4","MRK","7","4","4","ואת אשר מן השוק אינם אכלים בלא טבילה ועוד דברים אחרים רבים אשר קבלו לשמר כמו טבילת כסות וכדים ויורות ומטות׃ ");
INSERT INTO heb_vpl VALUES ("MK7_5","071_7_5","MRK","7","5","5","וישאלו אותו הפרושים והסופרים מדוע תלמידיך אינם נהגים על פי קבלת הזקנים כי אכלים לחם בלא נטבילת ידים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_6","071_7_6","MRK","7","6","6","ויען ויאמר אליהם היטב נבא ישעיהו עליכם החנפים ככתוב העם הזה בשפתיו כבדוני ולבו רחק ממני׃ ");
INSERT INTO heb_vpl VALUES ("MK7_7","071_7_7","MRK","7","7","7","ותהו יראתם אתי מצות אנשים מלמדים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_8","071_7_8","MRK","7","8","8","כי עזבתם את מצות אלהים לאחז בקבלת בני אדם טבילות כדים וכסות וכאלה רבות אתם עשים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_9","071_7_9","MRK","7","9","9","ויאמר אליהם מה יפה עשיתם אשר בטלתם את מצות האלהים כדי שתשמרו את קבלתכם׃ ");
INSERT INTO heb_vpl VALUES ("MK7_10","071_7_10","MRK","7","10","10","כי משה אמר כבד את אביך ואת אמך ומקלל אביו ואמו מות יומת׃ ");
INSERT INTO heb_vpl VALUES ("MK7_11","071_7_11","MRK","7","11","11","ואתם אמרים איש כי יאמר לאביו ולאמו קרבן פרושו מתנה לאלהים כל מה שאתה נהנה לי׃ ");
INSERT INTO heb_vpl VALUES ("MK7_12","071_7_12","MRK","7","12","12","ולא תניחו לו לעשות עוד מאומה לאביו ולאמו׃ ");
INSERT INTO heb_vpl VALUES ("MK7_13","071_7_13","MRK","7","13","13","ותפרו את דבר האלהים על ידי קבלתכם אשר קבלתם והרבה כאלה אתם עשים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_14","071_7_14","MRK","7","14","14","ויקרא אל כל העם ויאמר אליהם שמעו אלי כלכם והבינו׃ ");
INSERT INTO heb_vpl VALUES ("MK7_15","071_7_15","MRK","7","15","15","אין דבר מחוץ לאדם אשר יוכל לטמא אותו בבאו אל קרבו כי אם הדברים היוצאים ממנו המה יטמאו את האדם׃ ");
INSERT INTO heb_vpl VALUES ("MK7_16","071_7_16","MRK","7","16","16","כל אשר אזנים לו לשמע ישמע׃ ");
INSERT INTO heb_vpl VALUES ("MK7_17","071_7_17","MRK","7","17","17","ויהי כאשר שב הביתה מן ההמון וישאלהו תלמידיו על דבר המשל׃ ");
INSERT INTO heb_vpl VALUES ("MK7_18","071_7_18","MRK","7","18","18","ויאמר אליהם האף אתם חסרי בינה הלא תשכילו כי כל הבא את תוך האדם מחוצה לו לא יטמאנו׃ ");
INSERT INTO heb_vpl VALUES ("MK7_19","071_7_19","MRK","7","19","19","כי לא יבוא אל לבו כי אם אל כרשו ויצא למוצאות להבר כל אכל׃ ");
INSERT INTO heb_vpl VALUES ("MK7_20","071_7_20","MRK","7","20","20","ויאמר היצא מן האדם הוא מטמא את האדם׃ ");
INSERT INTO heb_vpl VALUES ("MK7_21","071_7_21","MRK","7","21","21","22-12 כי מתוך לב האדם יצאות המחשבות הרעות נאף וזנה ורצוח וגנוב ואהבת בצע ורשעה ורמיה וזוללות וצרות עין וגדוף וזדון וסכלות׃ ");
INSERT INTO heb_vpl VALUES ("MK7_22","071_7_22","MRK","7","22","22","22-12׃ ");
INSERT INTO heb_vpl VALUES ("MK7_23","071_7_23","MRK","7","23","23","כל הרעות האלה מקרב האדם הן יוצאות ומטמאות אתו׃ ");
INSERT INTO heb_vpl VALUES ("MK7_24","071_7_24","MRK","7","24","24","ויקם משם וילך לו אל גבולות צור וצידון ובבואו הביתה לא אבה כי יודע לאיש ולא יכל להסתר׃ ");
INSERT INTO heb_vpl VALUES ("MK7_25","071_7_25","MRK","7","25","25","כי אשה אשר רוח טמאה נכנסה בבתה הקטנה שמעה את שמעו ותבא ותפל לרגליו׃ ");
INSERT INTO heb_vpl VALUES ("MK7_26","071_7_26","MRK","7","26","26","והאשה יונית וארץ מולדתה כנען אשר לסוריא ותבקש ממנו לגרש אר השד מבתה׃ ");
INSERT INTO heb_vpl VALUES ("MK7_27","071_7_27","MRK","7","27","27","ויאמר אליה ישוע הניחו לשבע בראשונה הבנים כי לא טוב לקחת לחם הבנים ולהשליכו לצעירי הכלבים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_28","071_7_28","MRK","7","28","28","ותען ותאמר אליו כן אדני אבל גם צעירי הכלבים יאכלו תחת השלחן מפרורי לחם הבנים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_29","071_7_29","MRK","7","29","29","ויאמר אליה בגלל דברך זה לכי לך יצא השד מבתך׃ ");
INSERT INTO heb_vpl VALUES ("MK7_30","071_7_30","MRK","7","30","30","ותבא אל ביתה ותמצא את הילדה משכבת על חמטה והשד יצא ממנה׃ ");
INSERT INTO heb_vpl VALUES ("MK7_31","071_7_31","MRK","7","31","31","וישב ויצא מגבול צור וצידון ויבא אל ים הגליל בתוך גבול עשר הערים׃ ");
INSERT INTO heb_vpl VALUES ("MK7_32","071_7_32","MRK","7","32","32","ויביאו אליו איש אשר היה חרש ואלם ויתחננו לו לשום עליו את ידו׃ ");
INSERT INTO heb_vpl VALUES ("MK7_33","071_7_33","MRK","7","33","33","ויקח אתו לבדו מקרב ההמון וישם את אצבעותיו באזניו וירק ויגע על לשנו׃ ");
INSERT INTO heb_vpl VALUES ("MK7_34","071_7_34","MRK","7","34","34","ויבט השמימה ויאנח ויאמר אליו אפתח ופרושו הפתח׃ ");
INSERT INTO heb_vpl VALUES ("MK7_35","071_7_35","MRK","7","35","35","וברגע נפתחו אזניו ויתר קשר לשונו וידבר בשפה ברורה׃ ");
INSERT INTO heb_vpl VALUES ("MK7_36","071_7_36","MRK","7","36","36","ויזהר אותם כי לא יספרו לאיש וכאשר יזהירם כן ירבו להכריז׃ ");
INSERT INTO heb_vpl VALUES ("MK7_37","071_7_37","MRK","7","37","37","וישתוממו עד מאד ויאמרו את הכל עשה יפה גם החרשים הוא עשה לשמעים גם האלמים למדברים׃ ");
INSERT INTO heb_vpl VALUES ("MK8_1","071_8_1","MRK","8","1","1","ויהי בימים ההם בהקבץ עם רב ואין להם מה יאכלו ויקרא אל תלמידיו ויאמר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("MK8_2","071_8_2","MRK","8","2","2","נכמרו רחמי על העם כי זה שלשת ימים עמדו עמדי ואין להם לחם לאכל׃ ");
INSERT INTO heb_vpl VALUES ("MK8_3","071_8_3","MRK","8","3","3","והיה בשלחי אותם רעבים לבתיהם יתעלפו בדרך כי יש מהם אשר באו ממרחק׃ ");
INSERT INTO heb_vpl VALUES ("MK8_4","071_8_4","MRK","8","4","4","ויענו אתו תלמידיו מאין יוכל איש להשביע את אלה פה במדבר לחם׃ ");
INSERT INTO heb_vpl VALUES ("MK8_5","071_8_5","MRK","8","5","5","וישאל אותם כמה ככרות לחם יש לכם ויאמרו שבע׃ ");
INSERT INTO heb_vpl VALUES ("MK8_6","071_8_6","MRK","8","6","6","ויצו את העם לשבת לארץ ויקח את שבע ככרות הלחם ויברך ויפרס ויתן אותם לתלמידיו לשום לפניהם וישימו לפני העם׃ ");
INSERT INTO heb_vpl VALUES ("MK8_7","071_8_7","MRK","8","7","7","ויהי להם מעט דגים קטנים ויברך ויאמר לשום לפניהם גם את אלה׃ ");
INSERT INTO heb_vpl VALUES ("MK8_8","071_8_8","MRK","8","8","8","ויאכלו וישבעו וישאו מן הפתותים הנותרים שבעת דודים׃ ");
INSERT INTO heb_vpl VALUES ("MK8_9","071_8_9","MRK","8","9","9","והאכלים היו כארבעת אלפי איש וישלחם׃ ");
INSERT INTO heb_vpl VALUES ("MK8_10","071_8_10","MRK","8","10","10","אז ירד באניה עם תלמידיו ויבא אל גלילות דלמונתא׃ ");
INSERT INTO heb_vpl VALUES ("MK8_11","071_8_11","MRK","8","11","11","ויצאו הפרושים ויחלו להתוכח אתו וישאלו מעמו אות מן השמים והם מנסים אתו׃ ");
INSERT INTO heb_vpl VALUES ("MK8_12","071_8_12","MRK","8","12","12","ויאנח ברוחו ויאמר מה הדור הזה מבקש לו אות אמן אמר אני לכם אם ינתן אות לדור הזה׃ ");
INSERT INTO heb_vpl VALUES ("MK8_13","071_8_13","MRK","8","13","13","ויעזב אותם וירד באניה וישב ויעבר אל עבר הים׃ ");
INSERT INTO heb_vpl VALUES ("MK8_14","071_8_14","MRK","8","14","14","וישכחו לקחת אתם לחם ולא היה להם באניה בלתי אם ככר לחם אחת׃ ");
INSERT INTO heb_vpl VALUES ("MK8_15","071_8_15","MRK","8","15","15","ויזהר אותם לאמר ראו השמרו לכם משאר הפרושים ומשאר הורדוס׃ ");
INSERT INTO heb_vpl VALUES ("MK8_16","071_8_16","MRK","8","16","16","ויחשבו ויאמרו איש אל רעהו על כי לחם אין אתנו׃ ");
INSERT INTO heb_vpl VALUES ("MK8_17","071_8_17","MRK","8","17","17","וידע ישוע ויאמר להם מה תחשבו על כי לחם אין לכם העוד לא תשכילו ולא תבינו ולבכם עודנו מטמטם׃ ");
INSERT INTO heb_vpl VALUES ("MK8_18","071_8_18","MRK","8","18","18","עינים לכם ולא תראו ואזנים לכם ולא תשמעו ולא תזכרו׃ ");
INSERT INTO heb_vpl VALUES ("MK8_19","071_8_19","MRK","8","19","19","כאשר פרסתי את חמשת ככרות הלחם לחמשת אלפי איש כמה סלים מלאי פתותים נשאתם ויאמרו אליו שנים עשר׃ ");
INSERT INTO heb_vpl VALUES ("MK8_20","071_8_20","MRK","8","20","20","ובשבע לארבעת אלפי איש כמה דודים מלאי פתותים נשאתם ויאמרו אליו שבעה׃ ");
INSERT INTO heb_vpl VALUES ("MK8_21","071_8_21","MRK","8","21","21","ויאמר אליהם איך לא תבינו׃ ");
INSERT INTO heb_vpl VALUES ("MK8_22","071_8_22","MRK","8","22","22","ויבא אל בית צידה ויביאו אליו איש עור ויתחננו לו לגעת בו׃ ");
INSERT INTO heb_vpl VALUES ("MK8_23","071_8_23","MRK","8","23","23","ויאחז ביד העור ויוליכהו אל מחוץ לכפר וירק בעיניו וישם את ידיו עליו וישאלהו לאמר הראה אתה דבר׃ ");
INSERT INTO heb_vpl VALUES ("MK8_24","071_8_24","MRK","8","24","24","ויבט ויאמר אראה את בני האדם כי מתהלכים כאילנות אני ראה׃ ");
INSERT INTO heb_vpl VALUES ("MK8_25","071_8_25","MRK","8","25","25","ויוסף לשום את ידיו על עיניו ותפקחנה עיניו וירפא וירא הכל היטב עד למרחוק׃ ");
INSERT INTO heb_vpl VALUES ("MK8_26","071_8_26","MRK","8","26","26","וישלחהו אל ביתו לאמר אל תבא בתוך הכפר ואל תדבר לאיש בכפר׃ ");
INSERT INTO heb_vpl VALUES ("MK8_27","071_8_27","MRK","8","27","27","ויצא ישוע ותלמידיו ללכת אל כפרי קיסרין של פילפוס ויהי בדרך וישאל את תלמידיו ויאמר אליהם מה אמרים עלי האנשים מי אני׃ ");
INSERT INTO heb_vpl VALUES ("MK8_28","071_8_28","MRK","8","28","28","ויענו ויאמרו יוחנן המטביל ויש אמרים אליהו ואחרים אמרים אחד מן הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("MK8_29","071_8_29","MRK","8","29","29","וישאל אתם לאמר ואתם מה תאמרו עלי מי אני ויען פטרוס ויאמר אליו אתה הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("MK8_30","071_8_30","MRK","8","30","30","ויצו אתם בגערה לבלתי דבר עליו לאיש׃ ");
INSERT INTO heb_vpl VALUES ("MK8_31","071_8_31","MRK","8","31","31","ויחל ללמדם כי צריך בן האדם לענות הרבה וימאס על ידי הזקנים והכהנים הגדולים והסופרים ויומת ומקצה שלשת ימים קום יקום׃ ");
INSERT INTO heb_vpl VALUES ("MK8_32","071_8_32","MRK","8","32","32","והוא בגלוי דבר את הדבר הזה ויקחהו פטרוס ויחל לגער בו׃ ");
INSERT INTO heb_vpl VALUES ("MK8_33","071_8_33","MRK","8","33","33","ויפן אחריו ויבט את תלמידיו ויגער בפטרוס לאמר סור מעל פני השטן כי אין לבך לדברי האלהים כי אם לדברי האדם׃ ");
INSERT INTO heb_vpl VALUES ("MK8_34","071_8_34","MRK","8","34","34","ויקרא אל העם ואל תלמידיו ויאמר אליהם החפץ ללכת אחרי יכחש בנפשו וישא את צלבו וילך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("MK8_35","071_8_35","MRK","8","35","35","כי כל אשר יחפץ להושיע את נפשו תאבד נפשו ממנו וכל אשר תאבד לו נפשו למעני ולמען הבשורה הוא יושיענה׃ ");
INSERT INTO heb_vpl VALUES ("MK8_36","071_8_36","MRK","8","36","36","כי מה יסכן לאדם כי יקנה את כל העולם ונשחתה נפשו׃ ");
INSERT INTO heb_vpl VALUES ("MK8_37","071_8_37","MRK","8","37","37","או מה יתן איש פדיון נפשו׃ ");
INSERT INTO heb_vpl VALUES ("MK8_38","071_8_38","MRK","8","38","38","כי כל איש אשר הייתי אני ודברי לו לחרפה בדור הנאף והחוטא הזה אף הוא יהיה לחרפה לבן האדם בבואו בכבוד אביו עם המלאכים הקדושים׃ ");
INSERT INTO heb_vpl VALUES ("MK9_1","071_9_1","MRK","9","1","1","ויאמר אליהם אמן אמר אני לכם כי יש מן העמדים פה אשר לא יטעמו מות עד כי יראו מלכות האלהים באה בגבורה׃ ");
INSERT INTO heb_vpl VALUES ("MK9_2","071_9_2","MRK","9","2","2","ואחרי ששת ימים לקח ישוע את פטרוס ואת יעקב ואת יוחנן ויעלם על הר גבה אתו לבדם וישתנה לעיניהם׃ ");
INSERT INTO heb_vpl VALUES ("MK9_3","071_9_3","MRK","9","3","3","ובגדיו נהיו מזהירים לבנים מאד כשלג אשר לא יוכל כובס בארץ להלבין כמוהם׃ ");
INSERT INTO heb_vpl VALUES ("MK9_4","071_9_4","MRK","9","4","4","וירא אליהם אליהו ומשה מדברים עם ישוע׃ ");
INSERT INTO heb_vpl VALUES ("MK9_5","071_9_5","MRK","9","5","5","ויען פטרוס ויאמר אל ישוע רבי טוב היותנו פה נעשה נא שלש סכות לך אחת ולמשה אחת ולאליהו אחת׃ ");
INSERT INTO heb_vpl VALUES ("MK9_6","071_9_6","MRK","9","6","6","כי לא ידע מה ידבר כי היו נבהלים׃ ");
INSERT INTO heb_vpl VALUES ("MK9_7","071_9_7","MRK","9","7","7","ויהי ענן סוכך עליהם ויצא מן הענן קול אמר זה בני ידידי אליו שמעו׃ ");
INSERT INTO heb_vpl VALUES ("MK9_8","071_9_8","MRK","9","8","8","והמה הביטו כה וכה פתאם ולא ראו עוד איש בלתי את ישוע לבדו אתם׃ ");
INSERT INTO heb_vpl VALUES ("MK9_9","071_9_9","MRK","9","9","9","וירדו מן ההר ויזהירם לבלתי הגיד לאיש את אשר ראו עד כי יקום בן האדם מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("MK9_10","071_9_10","MRK","9","10","10","וישמרו את הדבר בלבבם וידרשו לדעת מה היא התקומה מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("MK9_11","071_9_11","MRK","9","11","11","וישאלהו לאמר מה זה אמרים הסופרים כי אליהו בוא יבוא בראשונה׃ ");
INSERT INTO heb_vpl VALUES ("MK9_12","071_9_12","MRK","9","12","12","ויען ויאמר להם הנה אליהו בא בראשונה וישיב את הכל ומה כתוב על בן האדם הלא כי יענה הרבה וימאס׃ ");
INSERT INTO heb_vpl VALUES ("MK9_13","071_9_13","MRK","9","13","13","אבל אמר אני לכם גם בא אליהו וגם עשו לו כרצונם כאשר כתוב עליו׃ ");
INSERT INTO heb_vpl VALUES ("MK9_14","071_9_14","MRK","9","14","14","ויהי כבואו אל התלמידים וירא עם רב סביבותם וסופרים מתוכחים אתם׃ ");
INSERT INTO heb_vpl VALUES ("MK9_15","071_9_15","MRK","9","15","15","וכל העם כראותם אתו כן תמהו וירוצי אליו וישאלו לו לשלום׃ ");
INSERT INTO heb_vpl VALUES ("MK9_16","071_9_16","MRK","9","16","16","וישאל את הסופרים מה אתם מתוכחים עמהם׃ ");
INSERT INTO heb_vpl VALUES ("MK9_17","071_9_17","MRK","9","17","17","ויען אחד מן העם ויאמר רבי הבאתי אליך את בני אשר רוח אלם בקרבו׃ ");
INSERT INTO heb_vpl VALUES ("MK9_18","071_9_18","MRK","9","18","18","והיה בכל מקום אשר יאחזהו הוא מרצץ אתו וירד רירו וחרק את שניו ויבש גופו ואמר אל תלמידיך לגרשו ולא יכלו׃ ");
INSERT INTO heb_vpl VALUES ("MK9_19","071_9_19","MRK","9","19","19","ויען ויאמר להם הוי דור בלתי מאמין עד מתי אהיה עמכם עד מתי אסבל אתכם הביאו אתו לפני׃ ");
INSERT INTO heb_vpl VALUES ("MK9_20","071_9_20","MRK","9","20","20","ויביאהו לפניו ויהי כאשר ראהו הרוח וירוצצנו פתאם ויפל ארצה ויתגולל ויורד רירו׃ ");
INSERT INTO heb_vpl VALUES ("MK9_21","071_9_21","MRK","9","21","21","וישאל את אביו כמה ימים היתה לו זאת ויאמר מימי נעוריו׃ ");
INSERT INTO heb_vpl VALUES ("MK9_22","071_9_22","MRK","9","22","22","ופעמים רבות הפיל אתו גם באש גם במים להאבידו אך אם יכל תוכל רחם עלינו ועזרנו׃ ");
