INSERT INTO heb_vpl VALUES ("MK11_7","071_11_7","MRK","11","7","7","ויביאו את העיר אל ישוע וישליכו עליו את בגדיהם וישב עליו׃ ");
INSERT INTO heb_vpl VALUES ("MK11_8","071_11_8","MRK","11","8","8","ורבים פרשו את בגדיהם על הדרך ואחרים כרתו ענפים מן העצים וישטחו על הדרך׃ ");
INSERT INTO heb_vpl VALUES ("MK11_9","071_11_9","MRK","11","9","9","וההלכים לפניו ואחריו צעקים לאמר הושע נא ברוך הבא בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("MK11_10","071_11_10","MRK","11","10","10","ברוכה מלכות דוד אבינו הבאה בשם יהוה הושע נא במרומים׃ ");
INSERT INTO heb_vpl VALUES ("MK11_11","071_11_11","MRK","11","11","11","ויבא ישוע ירושלים ואל בית המקדש וירא ויתבונן על הכל והיום רפה לערוב ויצא אל בית היני עם שנים העשר׃ ");
INSERT INTO heb_vpl VALUES ("MK11_12","071_11_12","MRK","11","12","12","ויהי ממחרת בצאתם מבית היני וירעב׃ ");
INSERT INTO heb_vpl VALUES ("MK11_13","071_11_13","MRK","11","13","13","וירא תאנה מרחוק ולא עלים ויבא לראות הימצא בה פרי ויקרב אליה ולא מצא בה כי אם עלים לבד כי לא היתה עת תאנים׃ ");
INSERT INTO heb_vpl VALUES ("MK11_14","071_11_14","MRK","11","14","14","ויען ויאמר אליה מעתה איש אל יאכל פרי ממך עד עולם וישמעו תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("MK11_15","071_11_15","MRK","11","15","15","ויבאו ירושלים ויבא ישוע אל המקדש ויחל לגרש משם את המוכרים ואת הקונים ויהפך את שלחנות השלחנים ואת מושבות מכרי היונים׃ ");
INSERT INTO heb_vpl VALUES ("MK11_16","071_11_16","MRK","11","16","16","ולא הניח לאיש לשאת כלי דרך המקדש׃ ");
INSERT INTO heb_vpl VALUES ("MK11_17","071_11_17","MRK","11","17","17","וילמד ויאמר להם הלא כתוב כי ביתי בית תפלה יקרא לכל העמים ואתם עשיתם אתו מערת פריאים׃ ");
INSERT INTO heb_vpl VALUES ("MK11_18","071_11_18","MRK","11","18","18","וישמעו הסופרים וראשי הכהנים ויתנכלו אתו להשמידו כי יראו מפניו יען אשר כל העם משתוממים על תורתו׃ ");
INSERT INTO heb_vpl VALUES ("MK11_19","071_11_19","MRK","11","19","19","ויהי בערב ויצא אל מחוץ לעיר׃ ");
INSERT INTO heb_vpl VALUES ("MK11_20","071_11_20","MRK","11","20","20","ויהי הם עברים בבקר ויראו את התאנה כי יבשה עם שרשיה׃ ");
INSERT INTO heb_vpl VALUES ("MK11_21","071_11_21","MRK","11","21","21","ויזכר פטרוס ויאמר אליו רבי הנה התאנה אשר אררתה יבשה׃ ");
INSERT INTO heb_vpl VALUES ("MK11_22","071_11_22","MRK","11","22","22","ויען ישוע ויאמר אליהם תהי נא בכם אמונת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("MK11_23","071_11_23","MRK","11","23","23","כי אמן אמר אני לכם כל אשר יאמר אל ההר הזה הנשא והעתק אל תוך הים ואין ספק בלבבו כי אם יאמין כי יהיה כאשר אמר כן גם יהיה לו׃ ");
INSERT INTO heb_vpl VALUES ("MK11_24","071_11_24","MRK","11","24","24","על כן אני אמר לכם כל אשר תשאלו בהתפללכם האמינו כי תקחו ויהי לכם׃ ");
INSERT INTO heb_vpl VALUES ("MK11_25","071_11_25","MRK","11","25","25","וכי תעמדו להתפלל תסלחו לכל איש את אשר בלבבכם עליו למען יסלח לכם אביכם שבשמים אף הוא את פשעיכם׃ ");
INSERT INTO heb_vpl VALUES ("MK11_26","071_11_26","MRK","11","26","26","ואתם אם לא תסלחו אף אביכם שבשמים לא יסלח לכם את פשעיכם׃ ");
INSERT INTO heb_vpl VALUES ("MK11_27","071_11_27","MRK","11","27","27","וישובו ויבאו ירושלים ויהי הוא מתהלך במקדש ויבאו אליו הכהנים הגדולים והסופרים והזקנים׃ ");
INSERT INTO heb_vpl VALUES ("MK11_28","071_11_28","MRK","11","28","28","ויאמרו אליו באי זו רשות אתה עשה אלה ומי נתן לך את הרשות הזאת לעשות את אלה׃ ");
INSERT INTO heb_vpl VALUES ("MK11_29","071_11_29","MRK","11","29","29","ויאמר ישוע אליהם גם אני אשאלה אתכם דבר אחד ואתם השיבוני ואמר לכם באי זו רשות אני עשה אלה׃ ");
INSERT INTO heb_vpl VALUES ("MK11_30","071_11_30","MRK","11","30","30","טבילת יוחנן המן השמים היתה אם מבני אדם השיבוני׃ ");
INSERT INTO heb_vpl VALUES ("MK11_31","071_11_31","MRK","11","31","31","ויחשבו כה וכה בקרבם לאמר אם נאמר מן השמים יאמר מדוע אפוא לא האמנתם לו׃ ");
INSERT INTO heb_vpl VALUES ("MK11_32","071_11_32","MRK","11","32","32","או הנאמר מבני אדם וייראו את העם כי כלם חשבו את יוחנן לנביא באמת׃ ");
INSERT INTO heb_vpl VALUES ("MK11_33","071_11_33","MRK","11","33","33","ויענו ויאמרו אל ישוע לא ידענו ויען ישוע ויאמר אליהם אם כן גם אני לא אמר לכם באי זו רשות אני עשה אלה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_1","071_12_1","MRK","12","1","1","ויחל לדבר אליהם במשלים לאמר איש נטע כרם ויעש גדר סביבותיו ויחצב יקב ויבן מגדל ויתנהו אל כרמים וילך למרחקים׃ ");
INSERT INTO heb_vpl VALUES ("MK12_2","071_12_2","MRK","12","2","2","ולמועד שלח אל הכרמים עבד לקחת מאת הכרמים מפרי הכרם׃ ");
INSERT INTO heb_vpl VALUES ("MK12_3","071_12_3","MRK","12","3","3","ויחזיקו בו ויכהו וישלחהו ריקם׃ ");
INSERT INTO heb_vpl VALUES ("MK12_4","071_12_4","MRK","12","4","4","ויסף לשלח אליהם עבד אחר ואתו סקלו באבנים ומחקו ראשו וישלחהו נכלם׃ ");
INSERT INTO heb_vpl VALUES ("MK12_5","071_12_5","MRK","12","5","5","ויסף וישלח אחר וגם אתו הרגו וכן עשו ברבים אחרים מהם הכו ומהם הרגו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_6","071_12_6","MRK","12","6","6","ויהי לו עוד בן יחיד אשר אהבו וישלח גם אתו אליהם באחרנה לאמר מפני בני יגורו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_7","071_12_7","MRK","12","7","7","והכרמים ההם אמרו איש אל רעהו הנה זה הוא היורש לכו ונהרגהו ולנו תהיה הירשה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_8","071_12_8","MRK","12","8","8","ויחזיקו בו ויהרגו אותו וישליכהו אל מחוץ לכרם׃ ");
INSERT INTO heb_vpl VALUES ("MK12_9","071_12_9","MRK","12","9","9","ועתה מה יעשה בעל הכרם יבוא ויאבד את הכרמים ההם ויתן את הכרם לאחרים׃ ");
INSERT INTO heb_vpl VALUES ("MK12_10","071_12_10","MRK","12","10","10","הלא קראתם את הכתוב הזה אבן מאסו הבונים היתה לראש פנה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_11","071_12_11","MRK","12","11","11","מאת יהוה היתה זאת היא נפלאת בעינינו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_12","071_12_12","MRK","12","12","12","ויבקשו לתפשו וייראו מפני העם יען אשר הבינו כי עליהם דבר את המשל הזה ויעזבהו וילכו להם׃ ");
INSERT INTO heb_vpl VALUES ("MK12_13","071_12_13","MRK","12","13","13","וישלחו אליו אנשים מן הפרושים ומן ההורדוסים ללכד אתו בדברו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_14","071_12_14","MRK","12","14","14","ויבאו ויאמרו אליו רבי ידענו כי איש אמת אתה ולא תגור מפני איש כי לא תכיר פנים כי אם באמת מורה אתה את דרך האלהים הנכון לתת מס אל הקיסר אם לא נתן׃ ");
INSERT INTO heb_vpl VALUES ("MK12_15","071_12_15","MRK","12","15","15","והוא ידע את חנפתם ויאמר אליהם מה תנסוני הביאו אלי דינר ואראה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_16","071_12_16","MRK","12","16","16","ויביאו ויאמר אליהם של מי הצורה הזאת והמכתב אשר עליו ויאמרו אליו של הקיסר׃ ");
INSERT INTO heb_vpl VALUES ("MK12_17","071_12_17","MRK","12","17","17","ויאמר ישוע אליהם את אשר לקיסר תנו לקיסר ואת אשר לאלהים תנו לאלהים ויתמהו עליו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_18","071_12_18","MRK","12","18","18","ויבאו אליו מן הצדוקים האמרים כי אין תחיה למתים וישאלהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("MK12_19","071_12_19","MRK","12","19","19","רבי כתב לנו משה כי ימות אחי איש ועזב אשה ובנים אין לו ייבם אחיו את אשתו ויקם זרע לאחיו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_20","071_12_20","MRK","12","20","20","והנה שבעה אחים והראשון לקח אשה ובמותו לא השאיר אחריו זרע׃ ");
INSERT INTO heb_vpl VALUES ("MK12_21","071_12_21","MRK","12","21","21","ויקח אתה השני וימת ולא הניח זרע וכן גם השלישי׃ ");
INSERT INTO heb_vpl VALUES ("MK12_22","071_12_22","MRK","12","22","22","ויקחוה כל השבעה ולא השאירו אחריהם זרע ואחרי מות כלם מתה גם האשה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_23","071_12_23","MRK","12","23","23","ועתה בתחית המתים כשיקומו למי מהם תהיה לאשה כי לשבעה היתה לאשה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_24","071_12_24","MRK","12","24","24","ויאמר ישוע אליהם הלא בזאת אתם תעים באשר אינכם יודעים גם את הכתובים גם את גבורת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("MK12_25","071_12_25","MRK","12","25","25","כי בעת קומם מן המתים האנשים לא ישאו נשים ולא תנשאנה אך יהיו כמלאכי השמים׃ ");
INSERT INTO heb_vpl VALUES ("MK12_26","071_12_26","MRK","12","26","26","ועל דבר המתים כי קום יקומו הלא קראתם בספר משה בסנה את אשר דבר אליו האלהים לאמר אנכי אלהי אברהם ואלהי יצחק ואלהי יעקב׃ ");
INSERT INTO heb_vpl VALUES ("MK12_27","071_12_27","MRK","12","27","27","האלהים איננו אלהי המתים כי אם אלהי החיים לכן הרביתם לתעות׃ ");
INSERT INTO heb_vpl VALUES ("MK12_28","071_12_28","MRK","12","28","28","ואחד מן הסופרים שמע אתם מתוכחים ויקרב אליהם וירא כי היטב השיבם וישאלהו מה היא הראשנה לכל המצות׃ ");
INSERT INTO heb_vpl VALUES ("MK12_29","071_12_29","MRK","12","29","29","ויען ישוע וידבר אליו הראשנה לכל המצות היא שמע ישראל יהוה אלהינו יהוה אחד׃ ");
INSERT INTO heb_vpl VALUES ("MK12_30","071_12_30","MRK","12","30","30","ואהבת את יהוה אלהיך בכל לבבך ובכל נפשך ובכל מדעך ובכל מאדך זאת היא המצוה הראשנה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_31","071_12_31","MRK","12","31","31","והשנית הדמה לה היא ואהבת לרעך כמוך ואין מצוה גדולה מאלה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_32","071_12_32","MRK","12","32","32","ויאמר אליו הסופר אמנם רבי יפה דברת כי אלהים אחד הוא ואין עוד מלבדו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_33","071_12_33","MRK","12","33","33","ולאהבה אתו בכל לבב ובכל מדע ובכל נפש ובכל מאד ולאהבה את הרע כנפשו גדולה היא מכל עלות וזבחים׃ ");
INSERT INTO heb_vpl VALUES ("MK12_34","071_12_34","MRK","12","34","34","וירא ישוע כי ענה בדעת ויאמר אליו לא רחוק אתה ממלכות האלהים ואיש לא ערב עוד את לבו לשאל אותו שאלה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_35","071_12_35","MRK","12","35","35","ויען ישוע בלמדו במקדש ויאמר איך יאמרו הסופרים כי המשיח הוא בן דוד׃ ");
INSERT INTO heb_vpl VALUES ("MK12_36","071_12_36","MRK","12","36","36","והוא דוד אמר ברוח הקדש נאם יהוה לאדני שב לימיני עד אשית איביך הדם לרגליך׃ ");
INSERT INTO heb_vpl VALUES ("MK12_37","071_12_37","MRK","12","37","37","הנה דוד בעצמו קרא לו אדון ואיך הוא בנו ויאהב רב העם לשמע אתו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_38","071_12_38","MRK","12","38","38","ויאמר אליהם בלמד אתם השמרו מן הסופרים האהבים להתהלך עטופי טלית ואת שאלות שלומם בשוקים׃ ");
INSERT INTO heb_vpl VALUES ("MK12_39","071_12_39","MRK","12","39","39","ואת מושבי הראש בבתי כנסיות ואת מסבות הראש בסעודות׃ ");
INSERT INTO heb_vpl VALUES ("MK12_40","071_12_40","MRK","12","40","40","הבלעים את בתי האלמנות ומאריכים בתפלה למראה עינים המה משפט על יתר יקחו׃ ");
INSERT INTO heb_vpl VALUES ("MK12_41","071_12_41","MRK","12","41","41","וישוע ישב ממול ארון האוצר והוא ראה את העם משליכים מעות לארון האוצר ועשירים רבים נתנו הרבה׃ ");
INSERT INTO heb_vpl VALUES ("MK12_42","071_12_42","MRK","12","42","42","ותבא אלמנה עניה ותשלך שתי פרוטות אשר הן רבע אסר׃ ");
INSERT INTO heb_vpl VALUES ("MK12_43","071_12_43","MRK","12","43","43","ויקרא אל תלמידיו ויאמר אליהם אמן אמר אני לכם כי האלמנה העניה הזאת נתנה יותר מכל הנתנים אל ארון האוצר׃ ");
INSERT INTO heb_vpl VALUES ("MK12_44","071_12_44","MRK","12","44","44","כי כלם נתנו מן העדף שלהם והיא ממחסרה נתנה כל אשר לה את כל רכושה׃ ");
INSERT INTO heb_vpl VALUES ("MK13_1","071_13_1","MRK","13","1","1","ויהי בצאתו מן המקדש ויאמר אליו אחד מתלמידיו רבי ראה מה יפו האבנים והבנינים האלה׃ ");
INSERT INTO heb_vpl VALUES ("MK13_2","071_13_2","MRK","13","2","2","ויען ישוע אתו ויאמר הראית את כל הבנינים הגדולים האלה לא תשאר אבן על אבן אשר לא תתפרק׃ ");
INSERT INTO heb_vpl VALUES ("MK13_3","071_13_3","MRK","13","3","3","וישב על הר הזיתים ממול המקדש וישאלהו פטרוס ויעקב ויוחנן ואנדרי והם אתו לבדם׃ ");
INSERT INTO heb_vpl VALUES ("MK13_4","071_13_4","MRK","13","4","4","אמר נא לנו מתי תהיה זאת ומה הוא האות בבא העת אשר תעשה בה כל זאת׃ ");
INSERT INTO heb_vpl VALUES ("MK13_5","071_13_5","MRK","13","5","5","ויען אתם ישוע ויחל לדבר ראו פן יתעה אתכם איש׃ ");
INSERT INTO heb_vpl VALUES ("MK13_6","071_13_6","MRK","13","6","6","כי רבים יבאו בשמי לאמר אני הוא ויתעו רבים׃ ");
INSERT INTO heb_vpl VALUES ("MK13_7","071_13_7","MRK","13","7","7","ובשמעכם מלחמות ושמעות מלחמה אל תבהלו כי היו תהיה זאת אך לא זאת היא הקץ׃ ");
INSERT INTO heb_vpl VALUES ("MK13_8","071_13_8","MRK","13","8","8","כי יקום גוי על גוי וממלכה על ממלכה והיה רעש כה וכה והיה רעב ומהומה׃ ");
INSERT INTO heb_vpl VALUES ("MK13_9","071_13_9","MRK","13","9","9","אלה ראשית החבלים ואתם השמרו בנפשתיכם כי ימסרו אתכם לסנהדריות והכיתם בבתי כנסיות ולפני משלים ומלכים תובאו למעני לעדות להם׃ ");
INSERT INTO heb_vpl VALUES ("MK13_10","071_13_10","MRK","13","10","10","והבשורה צריכה להקרא בראשנה לכל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("MK13_11","071_13_11","MRK","13","11","11","וכאשר יוליכו ומסרו אתכם אל תדאגו ואל תחשבו מה תדברו כי הדבר אשר ינתן לכם בשעה ההיא אותו דברו יען לא אתם הם המדברים כי אם רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("MK13_12","071_13_12","MRK","13","12","12","ואח ימסר את אחיו למות ואב את בנו וקמו בנים באבותם והמיתו אותם׃ ");
INSERT INTO heb_vpl VALUES ("MK13_13","071_13_13","MRK","13","13","13","והייתם שנואים לכל אדם למען שמי והמחכה עד עת קץ הוא יושע׃ ");
INSERT INTO heb_vpl VALUES ("MK13_14","071_13_14","MRK","13","14","14","וכי תראו את שקוץ משמם הנאמר ביד דניאל הנביא עמד במקום אשר לא לו הקורא יבין אז נוס ינוסו אנשי יהודה אל ההרים׃ ");
INSERT INTO heb_vpl VALUES ("MK13_15","071_13_15","MRK","13","15","15","ואשר על הגג אל ירד הביתה ואל יבא פנימה לשאת דבר מביתו׃ ");
INSERT INTO heb_vpl VALUES ("MK13_16","071_13_16","MRK","13","16","16","ואשר בשדה אל ישב הביתה לשאת מלבושו׃ ");
INSERT INTO heb_vpl VALUES ("MK13_17","071_13_17","MRK","13","17","17","ואוי להרות ולמיניקות בימים ההמה׃ ");
INSERT INTO heb_vpl VALUES ("MK13_18","071_13_18","MRK","13","18","18","אך התפללו אשר לא תהיה מנוסתכם בחרף׃ ");
INSERT INTO heb_vpl VALUES ("MK13_19","071_13_19","MRK","13","19","19","כי הימים ההם יהיו עת צרה אשר לא נהיתה כמוה מראשית הבריאה אשר ברא אלהים עד עתה וכמוה לא תהיה עוד׃ ");
INSERT INTO heb_vpl VALUES ("MK13_20","071_13_20","MRK","13","20","20","ולולי קצר יהוה את הימים ההם לא יושע כל בשר אך למען הבחירים אשר בחר בם קצר את הימים׃ ");
INSERT INTO heb_vpl VALUES ("MK13_21","071_13_21","MRK","13","21","21","ואז אם יאמר איש אליכם הנה פה המשיח או הנהו שם אל תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("MK13_22","071_13_22","MRK","13","22","22","כי יקומו משיחי שקר ונביאי שקר ונתנו אתות ומופתים להתעות אף את הבחירים אם יוכלו׃ ");
INSERT INTO heb_vpl VALUES ("MK13_23","071_13_23","MRK","13","23","23","ואתם ראו הנה מראש הגדתי לכם את כל׃ ");
INSERT INTO heb_vpl VALUES ("MK13_24","071_13_24","MRK","13","24","24","והיה בימים ההם אחרי הצרה ההיא תחשך השמש והירח לא יגיה אורו׃ ");
INSERT INTO heb_vpl VALUES ("MK13_25","071_13_25","MRK","13","25","25","והכוכבים יפלו מן השמים וכחות השמים יתמוטטו׃ ");
INSERT INTO heb_vpl VALUES ("MK13_26","071_13_26","MRK","13","26","26","ואז יראו את בן האדם בא בעננים בגבורה רבה ובכבוד׃ ");
INSERT INTO heb_vpl VALUES ("MK13_27","071_13_27","MRK","13","27","27","ואז ישלח את מלאכיו ויקבץ את בחיריו מארבע הרוחות מקצה הארץ עד קצה השמים׃ ");
INSERT INTO heb_vpl VALUES ("MK13_28","071_13_28","MRK","13","28","28","למדו נא את משל התאנה כשירטב ענפה ופרח עלה ידעתם כי קרוב הקיץ׃ ");
INSERT INTO heb_vpl VALUES ("MK13_29","071_13_29","MRK","13","29","29","כן אף אתם בראתכם כי היו כל אלה דעו כי קרוב הוא לפתח׃ ");
INSERT INTO heb_vpl VALUES ("MK13_30","071_13_30","MRK","13","30","30","אמן אמר אני לכם לא יעבר הדור הזה עד אשר יהיו כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("MK13_31","071_13_31","MRK","13","31","31","השמים והארץ יעברו ודברי לא יעברון׃ ");
INSERT INTO heb_vpl VALUES ("MK13_32","071_13_32","MRK","13","32","32","אך עת בוא היום ההוא והשעה ההיא אין איש יודע אותה גם לא מלאכי השמים גם לא הבן מבלעדי האב׃ ");
INSERT INTO heb_vpl VALUES ("MK13_33","071_13_33","MRK","13","33","33","ראו שקדו והתפללו כי לא ידעתם מתי תהיה העת׃ ");
INSERT INTO heb_vpl VALUES ("MK13_34","071_13_34","MRK","13","34","34","והיה כאיש הולך למרחק אשר עזב את ביתו ויתן שלטן לעבדיו ולאיש איש את מלאכתו וגם את השוער צוה לשקד׃ ");
INSERT INTO heb_vpl VALUES ("MK13_35","071_13_35","MRK","13","35","35","לכן שקדו כי לא ידעתם מתי יבוא בעל הבית אם לעת ערב או בחצות הלילה אם בעת קריאת הגבר או בבקר׃ ");
INSERT INTO heb_vpl VALUES ("MK13_36","071_13_36","MRK","13","36","36","פן יבוא פתאם ומצא אתכם ישנים׃ ");
INSERT INTO heb_vpl VALUES ("MK13_37","071_13_37","MRK","13","37","37","ואת אשר אמרתי לכם אמר אני לכל שקדו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_1","071_14_1","MRK","14","1","1","ויהי יומים לפני חג הפסח והמצות ויבקשו הכהנים הגדולים והסופרים איך יתפשהו בערמה להמיתו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_2","071_14_2","MRK","14","2","2","ויאמרו אך לא בחג פן תהיה מהומה בעם׃ ");
INSERT INTO heb_vpl VALUES ("MK14_3","071_14_3","MRK","14","3","3","ויהי בהיותו בבית היני בית שמעון המצרע ויסב אל השלחן ותבא אשה ובידה פך שמן נרד זך ויקר מאד ותשבר את הפך ותצק על ראשו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_4","071_14_4","MRK","14","4","4","ויש אשר מתרעמים איש אל רעהו לאמר על מה היה אבוד השמן הזה׃ ");
INSERT INTO heb_vpl VALUES ("MK14_5","071_14_5","MRK","14","5","5","כי ראוי היה זה להמכר ביותר משלש מאות דינר ולתתו לעניים ויגערו בה׃ ");
