INSERT INTO heb_vpl VALUES ("MK14_7","071_14_7","MRK","14","7","7","כי העניים תמיד עמכם וכשתרצו תוכלו להיטיב להם ואנכי לא אהיה אתכם תמיד׃ ");
INSERT INTO heb_vpl VALUES ("MK14_8","071_14_8","MRK","14","8","8","את אשר היה לאל ידה עשתה קדמה למשוח את גופי לחנטו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_9","071_14_9","MRK","14","9","9","אמן אמר אני לכם כי באשר תקרא הבשורה הזאת אל כל העולם גם את אשר עשתה היא יספר לזכרון לה׃ ");
INSERT INTO heb_vpl VALUES ("MK14_10","071_14_10","MRK","14","10","10","ויהודה איש קריות אחד משנים העשר הלך אל ראשי הכהנים למסר אותו אליהם׃ ");
INSERT INTO heb_vpl VALUES ("MK14_11","071_14_11","MRK","14","11","11","והם כשמעם שמחו ויאמרו לתת לו כסף ויבקש תאנה למסרו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_12","071_14_12","MRK","14","12","12","ויהי בראשון לחג המצות עת זבח הפסח ויאמרו אליו תלמידיו איפה תחפץ לאכל את הפסח ונלכה ונכין׃ ");
INSERT INTO heb_vpl VALUES ("MK14_13","071_14_13","MRK","14","13","13","וישלח שנים מתלמידיו ויאמר אליהם לכו העירה ויפגע אתכם איש נשא צפחת המים לכו אחריו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_14","071_14_14","MRK","14","14","14","ובאשר יבוא שמה אמרו לבעל הבית כה אמר הרב איה המלון אשת אכלה שם את הפסח עם תלמידי׃ ");
INSERT INTO heb_vpl VALUES ("MK14_15","071_14_15","MRK","14","15","15","והוא יראה אתכם עליה גדולה מצעה ומוכנה ושם הכינו לנו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_16","071_14_16","MRK","14","16","16","ויצאו תלמידיו ויבאו העירה וימצאו כאשר דבר להם ויכינו את הפסח׃ ");
INSERT INTO heb_vpl VALUES ("MK14_17","071_14_17","MRK","14","17","17","ויהי בערב ויבא עם שנים העשר׃ ");
INSERT INTO heb_vpl VALUES ("MK14_18","071_14_18","MRK","14","18","18","ויסבו ויאכלו ויאמר ישוע אמן אמר אני לכם אחד מכם האכל אתי ימסרני׃ ");
INSERT INTO heb_vpl VALUES ("MK14_19","071_14_19","MRK","14","19","19","ויחלו להתעצב ויאמרו אליו זה אחר זה הכי אני הוא׃ ");
INSERT INTO heb_vpl VALUES ("MK14_20","071_14_20","MRK","14","20","20","ויען ויאמר אליהם אחד משנים העשר הוא הטבל עמי בקערה׃ ");
