INSERT INTO heb_vpl VALUES ("MK14_22","071_14_22","MRK","14","22","22","ויהי באכלם ויקח ישוע לחם ויברך ויבצע ויתן להם ויאמר קחו אכלו זה הוא גופי׃ ");
INSERT INTO heb_vpl VALUES ("MK14_23","071_14_23","MRK","14","23","23","ויקח את הכוס ויברך ויתן להם וישתו ממנה כלם׃ ");
INSERT INTO heb_vpl VALUES ("MK14_24","071_14_24","MRK","14","24","24","ויאמר להם זה הוא דמי דם הברית החדשה הנשפך בעד רבים׃ ");
INSERT INTO heb_vpl VALUES ("MK14_25","071_14_25","MRK","14","25","25","אמן אמר אני לכם שתה לא אשתה עוד מתנובת הגפן עד היום ההוא אשר אשתה אותה חדשה במלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("MK14_26","071_14_26","MRK","14","26","26","ואחרי גמרם את ההלל ויצאו אל הר הזיתים׃ ");
