INSERT INTO heb_vpl VALUES ("MK14_30","071_14_30","MRK","14","30","30","ויאמר אליו ישוע אמן אמר אני לך כי היום בלילה הזה בטרם יקרא התרנגול פעמים אתה תכחש בי שלש פעמים׃ ");
