INSERT INTO heb_vpl VALUES ("MK14_37","071_14_37","MRK","14","37","37","ויבא וימצאם ישנים ויאמר אל פטרוס שמעון התישן הכי לא יכלת לשקד שעה אחת׃ ");
INSERT INTO heb_vpl VALUES ("MK14_38","071_14_38","MRK","14","38","38","שקדו והתפללו פן תבאו לידי נסיון הן הרוח היא חפצה והבשר רפה׃ ");
