INSERT INTO heb_vpl VALUES ("MK14_45","071_14_45","MRK","14","45","45","הוא בא והוא נגש אליו ויאמר רבי רבי וינשק לו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_46","071_14_46","MRK","14","46","46","וישלחו בו את ידיהם ויתפשהו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_47","071_14_47","MRK","14","47","47","ואחד מן העמדים אצלו שלף את חרבו ויך את עבד הכהן הגדול ויקצץ את אזנו׃ ");
INSERT INTO heb_vpl VALUES ("MK14_48","071_14_48","MRK","14","48","48","ויען ישוע ויאמר אליהם כמו על פריץ יצאתם עלי בחרבות ובמקלות לתפשני׃ ");
