INSERT INTO heb_vpl VALUES ("MK14_58","071_14_58","MRK","14","58","58","שמענו אתו אמר אני אהרס את ההיכל הזה מעשה ידי אדם ולשלשת ימים אבנה היכל אחר אשר איננו מעשה ידי אדם׃ ");
INSERT INTO heb_vpl VALUES ("MK14_59","071_14_59","MRK","14","59","59","וגם בזאת עדותם לא שותה׃ ");
INSERT INTO heb_vpl VALUES ("MK14_60","071_14_60","MRK","14","60","60","ויקם הכהן הגדול ויעמד בתוך וישאל את ישוע לאמר האינך משיב דבר מה זה אלה ענים בך׃ ");
INSERT INTO heb_vpl VALUES ("MK14_61","071_14_61","MRK","14","61","61","והוא החריש ולא השיב דבר ויוסף עוד הכהן הגדול לשאל אתו ויאמר אליו האתה הוא המשיח בן המברך׃ ");
INSERT INTO heb_vpl VALUES ("MK14_62","071_14_62","MRK","14","62","62","ויאמר ישוע אני הוא ואתם תראו את בן האדם יושב לימין הגבורה ובא עם ענני השמים׃ ");
INSERT INTO heb_vpl VALUES ("MK14_63","071_14_63","MRK","14","63","63","ויקרע הכהן הגדול את בגדיו ויאמר מה לנו עוד לבקש עדים׃ ");
INSERT INTO heb_vpl VALUES ("MK14_64","071_14_64","MRK","14","64","64","שמעתם את הגדוף מה דעתכם וירשיעהו כלם כי חיב מיתה הוא׃ ");
INSERT INTO heb_vpl VALUES ("MK14_65","071_14_65","MRK","14","65","65","ויחלו מהם לרק בו ויחפו את פניו ויכהו באגרף ויאמרו אליו הנבא והמשרתים הכאיבהו בהכותם אותו על הלחי׃ ");
INSERT INTO heb_vpl VALUES ("MK14_66","071_14_66","MRK","14","66","66","ויהי בהיות פטרוס בתחתית החצר ותבא אחת משפחות הכהן הגדול׃ ");
