INSERT INTO heb_vpl VALUES ("MK15_1","071_15_1","MRK","15","1","1","וישכימו ראשי הכהנים עם הזקנים והסופרים וכל הסנהדרין בבקר ויתיעצו ויאסרו את ישוע ויוליכהו משם וימסרהו אל פילטוס׃ ");
