INSERT INTO heb_vpl VALUES ("MK15_21","071_15_21","MRK","15","21","21","ויאנסו איש עבר אחד הבא מן השדה ושמו שמעון הקוריני אבי אלכסנדרוס ורופוס לשאת את צלבו׃ ");
