INSERT INTO heb_vpl VALUES ("MK15_30","071_15_30","MRK","15","30","30","הושע את עצמך ורדה מן הצלב׃ ");
INSERT INTO heb_vpl VALUES ("MK15_31","071_15_31","MRK","15","31","31","וכן לעגו לו גם ראשי הכהנים עם הסופרים באמרם איש אל רעהו את אחרים הושיע ואת עצמו לא יוכל להושיע׃ ");
INSERT INTO heb_vpl VALUES ("MK15_32","071_15_32","MRK","15","32","32","המשיח מלך ישראל ירד נא מן הצלב למען נראה ונאמין וגם הנצלבים אתו חרפוהו׃ ");
