INSERT INTO heb_vpl VALUES ("MK15_40","071_15_40","MRK","15","40","40","וגם נשים היו שם ראות מרחוק ובתוכן גם מרים המגדלית ומרים אמו של יעקב הצעיר ושל יוסי ושלמית׃ ");
