INSERT INTO heb_vpl VALUES ("LK1_18","072_1_18","LUK","1","18","18","ויאמר זכריה אל המלאך במה אדע זאת כי אני זקנתי ואשתי באה בימים׃ ");
INSERT INTO heb_vpl VALUES ("LK1_19","072_1_19","LUK","1","19","19","ויען המלאך ויאמר אליו אני גבריאל העומד לפני האלהים ושלוח אנכי לדבר אליך ולבשרך את זאת׃ ");
