INSERT INTO heb_vpl VALUES ("LK2_52","072_2_52","LUK","2","52","52","וישוע הלך וגדל בחכמה ומקומה ובחן עם אלהים ועם אנשים׃ ");
INSERT INTO heb_vpl VALUES ("LK3_1","072_3_1","LUK","3","1","1","בשנת חמש עשרה למלכות הקיסר טיבריוס בהיות פונטיוס פילטוס הגמון ביהודה והורדוס שר רבע על הגליל ואחיו פילפוס שר רבע על מדינות יטור וטרכונה ולוסניס שר רבע על אבילין׃ ");
INSERT INTO heb_vpl VALUES ("LK3_2","072_3_2","LUK","3","2","2","בימי הכהנים הגדולים חנן וקיפא היה דבר אלהים אל יוחנן בן זכריה במדבר׃ ");
