INSERT INTO heb_vpl VALUES ("LK4_19","072_4_19","LUK","4","19","19","שלחני לחבש לנשברי לב לקרא לשבוים דרור ולעורים פקח קוח לשלח רצוצים חפשים לקרא שנת רצון ליהוה׃ ");
INSERT INTO heb_vpl VALUES ("LK4_20","072_4_20","LUK","4","20","20","ויהי כאשר גלל את הספר וישיבהו אל החזן וישב ועיני כל אשר בבית הכנסת נשאות אליו׃ ");
INSERT INTO heb_vpl VALUES ("LK4_21","072_4_21","LUK","4","21","21","ויחל ויאמר אליהם היום נתמלא הכתוב הזה באזניכם׃ ");
