INSERT INTO heb_vpl VALUES ("LK4_23","072_4_23","LUK","4","23","23","ויאמר אליהם הן תאמרו לי את המשל הזה רפא רפא את עצמך וככל אשר שמענו שנעשה בכפר נחום עשה כן גם פה בעיר מולדתך׃ ");
INSERT INTO heb_vpl VALUES ("LK4_24","072_4_24","LUK","4","24","24","ויאמר אמן אמר אני לכם כי אין נביא רצוי בארץ מולדתו׃ ");
INSERT INTO heb_vpl VALUES ("LK4_25","072_4_25","LUK","4","25","25","ואמת אני אמר לכם אלמנות רבות היו בישראל בימי אליהו בהעצר השמים שלש שנים וששה חדשים ורעב גדול היה בכל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("LK4_26","072_4_26","LUK","4","26","26","ולא נשלח אליהו אל אחת מהנה זולתי צרפתה אשר לצידון אל אשה אלמנה׃ ");
INSERT INTO heb_vpl VALUES ("LK4_27","072_4_27","LUK","4","27","27","ומצרעים רבים היו בישראל בימי אלישע הנביא ולא טהר אחד מהם זולתי נעמן הארמי׃ ");
INSERT INTO heb_vpl VALUES ("LK4_28","072_4_28","LUK","4","28","28","וימלאו כל אשר בבית הכנסת חמה בשמעם את אלה׃ ");
INSERT INTO heb_vpl VALUES ("LK4_29","072_4_29","LUK","4","29","29","ויקומו וידיחו אותו אל מחוץ לעיר ויביאהו עד גב ההר אשר נבנתה עירם עליו למען השליכו מטה׃ ");
INSERT INTO heb_vpl VALUES ("LK4_30","072_4_30","LUK","4","30","30","אך הוא עבר בתוכם וילך לדרכו׃ ");
