INSERT INTO heb_vpl VALUES ("LK4_33","072_4_33","LUK","4","33","33","ואיש היה בבית הכנסת ובו רוח שד טמא ויצעק בקול גדול לאמר׃ ");
INSERT INTO heb_vpl VALUES ("LK4_34","072_4_34","LUK","4","34","34","אתה מה לנו ולך ישוע הנצרי באת להאבידנו ידעתיך מי אתה קדוש האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK4_35","072_4_35","LUK","4","35","35","ויגער בו ישוע לאמר האלם וצא ממנו ויפילהו השד בתוכם ויצא ממנו לא הרע לו׃ ");
INSERT INTO heb_vpl VALUES ("LK4_36","072_4_36","LUK","4","36","36","ותפל אימה על כלם וידברו איש אל רעהו לאמר מה הדבר הזה כי בשלטן ובגבורה מצוה לרוחות הטמאה והמה יצאים׃ ");
INSERT INTO heb_vpl VALUES ("LK4_37","072_4_37","LUK","4","37","37","ושמעו הולך בכל מקמות הככר׃ ");
INSERT INTO heb_vpl VALUES ("LK4_38","072_4_38","LUK","4","38","38","ויקם מבית הכנסת ויבא ביתה שמעון וחמות שמעון אחזתה קדחת חזקה וישאלהו בעדה׃ ");
INSERT INTO heb_vpl VALUES ("LK4_39","072_4_39","LUK","4","39","39","ויתיצב עליה ויגער בקדחת ותרף ממנה ותקם מהרה ותשרת אתם׃ ");
INSERT INTO heb_vpl VALUES ("LK4_40","072_4_40","LUK","4","40","40","וכבוא השמש הביאו אליו כל אשר להם חלים חליים שונים וירפא אותם בשומו את ידיו על כל אחד מהם׃ ");
INSERT INTO heb_vpl VALUES ("LK4_41","072_4_41","LUK","4","41","41","וגם שדים יצאו מרבים צעקים ואמרים אתה הוא המשיח בן האלהים ויגער בם ולא נתנם לדבר כי ידעו אשר הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("LK4_42","072_4_42","LUK","4","42","42","ויצא וילך לו כאור הבקר אל מקום חרבה והמון העם בקשהו ויבאו עדיו ויפצרו בו לבלתי סור מהם׃ ");
INSERT INTO heb_vpl VALUES ("LK4_43","072_4_43","LUK","4","43","43","ויאמר להם הן עלי לבשר גם לערים האחרות את בשורת מלכות האלהים כי לזאת שלחתי׃ ");
INSERT INTO heb_vpl VALUES ("LK4_44","072_4_44","LUK","4","44","44","ויהי קורא בבתי הכנסיות אשר בגליל׃ ");
INSERT INTO heb_vpl VALUES ("LK5_1","072_5_1","LUK","5","1","1","ויהי כאשר נדחק המון העם לשמע את דבר האלהים והוא עמד על יד ים גניסר׃ ");
INSERT INTO heb_vpl VALUES ("LK5_2","072_5_2","LUK","5","2","2","וירא שתי אניות עמדות על יד הים והדיגים יצאו מהן וידיחו את המכמרות׃ ");
INSERT INTO heb_vpl VALUES ("LK5_3","072_5_3","LUK","5","3","3","וירד אל אחת מן האניות אשר היא לשמעון ויבקש ממנו להוליכו מעט מן היבשה אל הים וישב וילמד את העם מתוך האניה׃ ");
INSERT INTO heb_vpl VALUES ("LK5_4","072_5_4","LUK","5","4","4","ויכל לדבר ויאמר אל שמעון הוליכה אל עמק הים והורידו את מכמרותיכם לצוד׃ ");
INSERT INTO heb_vpl VALUES ("LK5_5","072_5_5","LUK","5","5","5","ויען שמעון ויאמר אליו מורה כל הלילה יגענו ולא לכדנו מאומה אך על פי דברך אוריד את המכמרת׃ ");
INSERT INTO heb_vpl VALUES ("LK5_6","072_5_6","LUK","5","6","6","ויעשו כן וילכדו דגים הרבה מאד ותקרע מכמרתם׃ ");
INSERT INTO heb_vpl VALUES ("LK5_7","072_5_7","LUK","5","7","7","ויניפו יד אל חבריהם אשר באמיה השנית לבוא אליהם ולעזרם ויבאו וימלאו את שתי האניות עד כי שקעו׃ ");
INSERT INTO heb_vpl VALUES ("LK5_8","072_5_8","LUK","5","8","8","ויהי כראות שמעון פטרוס את זאת ויפל לברכי ישוע ויאמר אדני צא נא מעמי כי איש חוטא אנכי׃ ");
INSERT INTO heb_vpl VALUES ("LK5_9","072_5_9","LUK","5","9","9","כי שמה החזיקה אותו ואת כל אשר אתו על ציד הדגים אשר צדו׃ ");
INSERT INTO heb_vpl VALUES ("LK5_10","072_5_10","LUK","5","10","10","וכן גם את יעקב ואת יוחנן בני זבדי אשר התחברו עם שמעון ויאמר ישוע אל שמעון אל תירא מעתה צוד תצוד אנשים׃ ");
INSERT INTO heb_vpl VALUES ("LK5_11","072_5_11","LUK","5","11","11","ויוליכו את האניות אל היבשה ויעזבו את הכל וילכו אחריו׃ ");
INSERT INTO heb_vpl VALUES ("LK5_12","072_5_12","LUK","5","12","12","ויהי בהיותו באחת הערים והנה איש מלא צרעת וירא את ישוע ויפל על פניו ויתחנן אליו לאמר אדני אם תחפץ תוכל לטהרני׃ ");
INSERT INTO heb_vpl VALUES ("LK5_13","072_5_13","LUK","5","13","13","וישלח את ידו ויגע בו ויאמר חפץ אנכי טהר ופתאם סרה ממנו הצרעת׃ ");
INSERT INTO heb_vpl VALUES ("LK5_14","072_5_14","LUK","5","14","14","ויעד בו לבלתי ספר לאיש כי אם לך והראה אל הכהן והקרב קרבן על טהרתך כאשר צוה משה לעדות להם׃ ");
INSERT INTO heb_vpl VALUES ("LK5_15","072_5_15","LUK","5","15","15","ושמעו הולך הלוך וגדל ויקבצו עם רב לשמוע ולהרפא בידו מתחלואיהם׃ ");
INSERT INTO heb_vpl VALUES ("LK5_16","072_5_16","LUK","5","16","16","והוא סר אל המדברות ויתפלל׃ ");
INSERT INTO heb_vpl VALUES ("LK5_17","072_5_17","LUK","5","17","17","ויהי באחד הימים והוא מלמד וישבו שם פרושים ומורי התורה אשר באו מכל כפרי הגליל ומיהודה וירושלים וגבורת יהוה היתה בו לרפוא׃ ");
INSERT INTO heb_vpl VALUES ("LK5_18","072_5_18","LUK","5","18","18","והנה אנשים נושאים איש במטה והוא נכה אברים ויבקשו להביאו הביתה ולשום לפניו׃ ");
INSERT INTO heb_vpl VALUES ("LK5_19","072_5_19","LUK","5","19","19","ולא מצאו דרך להכניסו מרב העם ויעלו הגגה ויורידהו ואת ערשו בין הרעפים לתוך הבית לפני ישוע׃ ");
INSERT INTO heb_vpl VALUES ("LK5_20","072_5_20","LUK","5","20","20","וירא את אמונתם ויאמר אליו בן אדם נסלחו לך חטאתיך׃ ");
INSERT INTO heb_vpl VALUES ("LK5_21","072_5_21","LUK","5","21","21","ויחלו הסופרים והפרושים לחשב מחשבות לאמר מי הוא זה המדבר גדופים מי יוכל לסלח חטאים מבלעדי האלהים לבדו׃ ");
INSERT INTO heb_vpl VALUES ("LK5_22","072_5_22","LUK","5","22","22","וידע ישוע את מחשבותם ויען ויאמר אליהם מה אתם חשבים בלבבכם׃ ");
INSERT INTO heb_vpl VALUES ("LK5_23","072_5_23","LUK","5","23","23","מה הוא הנקל האמר נסלחו לך חטאתיך אם אמר קום והתהלך׃ ");
INSERT INTO heb_vpl VALUES ("LK5_24","072_5_24","LUK","5","24","24","אך למען תדעון כי בן האדם יש לו השלטן בארץ לסלח חטאים ויאמר אל נכה האברים אמר אני אליך קום ושא את ערשך ולך לך אל ביתך׃ ");
INSERT INTO heb_vpl VALUES ("LK5_25","072_5_25","LUK","5","25","25","וימהר ויקם לעיניהם וישא את משכבו וילך לו אל ביתו מהלל את האלהים וישא את משכבו וילך לו אל ביתו מהלל את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK5_26","072_5_26","LUK","5","26","26","ושמה החזיקה את כלם ויברכו את האלהים וימלאו יראה ויאמרו כי נפלאות ראינו היום׃ ");
INSERT INTO heb_vpl VALUES ("LK5_27","072_5_27","LUK","5","27","27","ויהי אחרי כן ויצא וירא מוכס ושמו לוי יושב בבית המכס ויאמר אליו לכה אחרי׃ ");
INSERT INTO heb_vpl VALUES ("LK5_28","072_5_28","LUK","5","28","28","ויעזב את הכל ויקם וילך אחריו׃ ");
INSERT INTO heb_vpl VALUES ("LK5_29","072_5_29","LUK","5","29","29","ויעש לו לוי משתה גדול בביתו ועם רב של מוכסים ואנשים אחרים היו מסבים עמהם׃ ");
INSERT INTO heb_vpl VALUES ("LK5_30","072_5_30","LUK","5","30","30","13-03 וילונו הסופרים אשר בהם והפרושים על תלמידיו ויאמרו למה אתם אכלים אליהם הבריאים אינם צריכים לרפא כי אם החלים׃ ");
INSERT INTO heb_vpl VALUES ("LK5_31","072_5_31","LUK","5","31","31","13-03׃ ");
INSERT INTO heb_vpl VALUES ("LK5_32","072_5_32","LUK","5","32","32","לא באתי לקרוא הצדיקים כי אם החטאים לתשובה׃ ");
INSERT INTO heb_vpl VALUES ("LK5_33","072_5_33","LUK","5","33","33","ויאמרו אליו הן תלמידי יוחנן צמים הרבה ואמרים תחנות וגם תלמידי הפרושים עשים כן ותלמידיך אכלים ושתים׃ ");
INSERT INTO heb_vpl VALUES ("LK5_34","072_5_34","LUK","5","34","34","ויאמר אליהם התוכלו אנס בני החפה לצום והחתן עוד עמהם׃ ");
INSERT INTO heb_vpl VALUES ("LK5_35","072_5_35","LUK","5","35","35","ואולם ימים באים ולקח מאתם החתן אז יצומו בימים ההמה׃ ");
INSERT INTO heb_vpl VALUES ("LK5_36","072_5_36","LUK","5","36","36","וידבר אליהם גם אם המשל הזה אין איש מעלה מטלית של בגד חדש על בגד בלוי כי אז גם החדש יקרע וגם לא תשוה מטלית החדש לבלוי׃ ");
INSERT INTO heb_vpl VALUES ("LK5_37","072_5_37","LUK","5","37","37","ואין איש נתן יין חדש בנאדות בלים כי אז היין החדש יבקע את הנאדות והוא ישפך והנאדות יאבדו׃ ");
INSERT INTO heb_vpl VALUES ("LK5_38","072_5_38","LUK","5","38","38","אך יתן היין החדש בנאדות חדשים ושניהם יחדו ישמרו׃ ");
INSERT INTO heb_vpl VALUES ("LK5_39","072_5_39","LUK","5","39","39","ואשר שתה יין ישן איננו חפץ עוד ביין חדש כי יאמר הישן הוא נעים ממנו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_1","072_6_1","LUK","6","1","1","ויהי בשבת השנית לספירת העמר עבר בין הקמה ויקטפו תלמידיו מלילת ויפרכו אתן בידיהם ויאכלו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_2","072_6_2","LUK","6","2","2","ויש מן הפרושים אשר אמרו אליהם למה אתם עשים את אשר איננו מתר לעשות בשבת׃ ");
INSERT INTO heb_vpl VALUES ("LK6_3","072_6_3","LUK","6","3","3","ויען ישוע ויאמר אליהם הלא קראתם את אשר עשה דוד בהיותו רעב הוא ואשר היו אתו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_4","072_6_4","LUK","6","4","4","כאשר בא אל בית האלהים ויקח את לחם הפנים ויאכל וגם נתן לאשר אתו את אשר לא נכון לאכלו כי אם לכהנים לבדם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_5","072_6_5","LUK","6","5","5","ויאמר אליהם בן האדם גם אדון השבת הוא׃ ");
INSERT INTO heb_vpl VALUES ("LK6_6","072_6_6","LUK","6","6","6","ויהי בשבת אחרת בא אל בית הכנסת וילמד ושם איש אשר יבשה ידו הימנית׃ ");
INSERT INTO heb_vpl VALUES ("LK6_7","072_6_7","LUK","6","7","7","ויארבו לו הסופרים והפרושים לראות אם ירפא בשבת למען ימצאו עליו שטנה׃ ");
INSERT INTO heb_vpl VALUES ("LK6_8","072_6_8","LUK","6","8","8","והוא ידע את מחשבותם ויאמר אל האיש אשר ידו יבשה קום ועמוד בתוך ויקם ויעמד׃ ");
INSERT INTO heb_vpl VALUES ("LK6_9","072_6_9","LUK","6","9","9","ויאמר אליהם ישוע אשאלה אתכם דבר הנכון בשבת להיטיב אם להרע להציל נפש אם לאבד׃ ");
INSERT INTO heb_vpl VALUES ("LK6_10","072_6_10","LUK","6","10","10","ויבט סביב אל כלם ויאמר לאיש פשט את ידך ויעש כן ותרפא ידו ותשב כאחרת׃ ");
INSERT INTO heb_vpl VALUES ("LK6_11","072_6_11","LUK","6","11","11","והמה נמלאו חמה ויוסדו יחד מה לעשות לישוע׃ ");
INSERT INTO heb_vpl VALUES ("LK6_12","072_6_12","LUK","6","12","12","ויהי בימים ההם ויצא ההרה להתפלל ויעמד כל הלילה בתפלה לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK6_13","072_6_13","LUK","6","13","13","ובהית הבקר אסף אליו את תלמידיו ויבחר מהם שנים עשר אשר גם קרא להם שליחים׃ ");
INSERT INTO heb_vpl VALUES ("LK6_14","072_6_14","LUK","6","14","14","את שמעון אשר גם קראו פטרוס ואת אנדרי אחיו את יעקב ואת יוחנן את פילפוס ואת בר תלמי׃ ");
INSERT INTO heb_vpl VALUES ("LK6_15","072_6_15","LUK","6","15","15","את מתי ואת תומא ואת יעקב בן חלפי ואת שמעון המכנה הקנא׃ ");
INSERT INTO heb_vpl VALUES ("LK6_16","072_6_16","LUK","6","16","16","את יהודה בן יעקב ואת יהודה איש קריות אשר גם היה למוסר׃ ");
INSERT INTO heb_vpl VALUES ("LK6_17","072_6_17","LUK","6","17","17","וירד אתם ויעמד במקום מישור והמון תלמידיו וקהל עם רב מכל יהודה וירושלים ומחוף ים צר וצידון אשר באו לשמע אתו ולהרפא מחלייהם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_18","072_6_18","LUK","6","18","18","וגם הנלחצים ברוחות טמאות וירפאו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_19","072_6_19","LUK","6","19","19","וכל ההמון מבקשים לגעת בו כי גבורה יצאה מאתו ורפאה את כלם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_20","072_6_20","LUK","6","20","20","והוא נשא את עיניו אל תלמידיו ויאמר אשריכם העניים כי לכם מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK6_21","072_6_21","LUK","6","21","21","אשריכם הרעבים כעת כי תשבעו אשריכם הבכים כעת כי תשחקו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_22","072_6_22","LUK","6","22","22","אשריכם אם ישנאו אתכם האנשים ואם ינדו אתכם וחרפו והדיחו את שמכם כשם רע בעבור בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_23","072_6_23","LUK","6","23","23","שמחו ביום ההוא ורקדו כי הנה שכרכם רב בשמים כי כזאת עשו אבתיהם לנביאים׃ ");
INSERT INTO heb_vpl VALUES ("LK6_24","072_6_24","LUK","6","24","24","אך אוי לכם העשירים כי כבר לקחתם את נחמתכם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_25","072_6_25","LUK","6","25","25","אוי לכם השבעים כי תרעבו אוי לכם השחקים כעת כי תתאבלו ותבכו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_26","072_6_26","LUK","6","26","26","אוי לכם אם כל האנשים משבחים אתכם כי כזאת עשו אבותיהם לנביאי השקר׃ ");
INSERT INTO heb_vpl VALUES ("LK6_27","072_6_27","LUK","6","27","27","אבל אליכם השמעים אני אמר אהבו את איביכם היטיבו לשנאיכם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_28","072_6_28","LUK","6","28","28","ברכו את מקלליכם והתפללו בעד מכלימיכם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_29","072_6_29","LUK","6","29","29","המכה אתך על הלחי הטה לו גם את האחרת והלקח את מעילך אל תמנע ממנו גם את כתנתך׃ ");
INSERT INTO heb_vpl VALUES ("LK6_30","072_6_30","LUK","6","30","30","וכל השאל ממך תן לו והלקח את אשר לך אל תשאל מאתו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_31","072_6_31","LUK","6","31","31","וכאשר תחפצו כי יעשו לכם בני האדם כן תעשו להם גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_32","072_6_32","LUK","6","32","32","ואם תאהבו את אהביכם מה הוא חסדכם כי גם החטאים אהבים את אהביהם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_33","072_6_33","LUK","6","33","33","ואם תיטיבו למטיביכם מה הוא חסדכם גם החטאים יעשו כן׃ ");
INSERT INTO heb_vpl VALUES ("LK6_34","072_6_34","LUK","6","34","34","ואם תלוו את האנשים אשר תקוו לקבל מהם מה הוא חסדכם גם החטאים מלוים את החטאים למען יושב להם בשוה׃ ");
INSERT INTO heb_vpl VALUES ("LK6_35","072_6_35","LUK","6","35","35","אבל אהבו את איביכם והיטיבו והלוו מבלי תוחלת ויהי שכרכם רב והייתם בני עליון כי טוב הוא גם לשכחי טובה ולרעים׃ ");
INSERT INTO heb_vpl VALUES ("LK6_36","072_6_36","LUK","6","36","36","לכן היו רחמנים כאשר גם אביכם רחום הוא׃ ");
INSERT INTO heb_vpl VALUES ("LK6_37","072_6_37","LUK","6","37","37","ואל תשפטו ולא תשפטו אל תחיבו ולא תחיבו נקו ותנקו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_38","072_6_38","LUK","6","38","38","תנו ותנתן לכם מדה טובה דחוקה וגדושה ומשפעה יתנו אל חיקכם כי במדה אשר אתם מודדים בה ימד לכם׃ ");
INSERT INTO heb_vpl VALUES ("LK6_39","072_6_39","LUK","6","39","39","וישא משלו ויאמר אליהם היוכל עור לנהל את העור הלא יפלו שניהם אל הפחת׃ ");
INSERT INTO heb_vpl VALUES ("LK6_40","072_6_40","LUK","6","40","40","אין תלמיד נעלה על רבו ודי לכל תלמיד שלם להיות כרבו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_41","072_6_41","LUK","6","41","41","ולמה זה אתה ראה את הקסם אשר בעין אחיך ואת הקורה בעינך לא תביט׃ ");
INSERT INTO heb_vpl VALUES ("LK6_42","072_6_42","LUK","6","42","42","ואיך תאמר אל אחיך אחי הניחה לי ואסירה את הקסם אשר בעינך ואינך ראה את הקורה אשר בעינך החנף הסר בראשונה את הקורה מעינך ואחר ראה תראה להסיר את הקסם אשר בעין אחיך׃ ");
INSERT INTO heb_vpl VALUES ("LK6_43","072_6_43","LUK","6","43","43","כי עץ טוב איננו עשה פרי משחת וגם עץ משחת איננו עשה פרי טוב׃ ");
INSERT INTO heb_vpl VALUES ("LK6_44","072_6_44","LUK","6","44","44","כי כל עץ נכר בפריו כי אין אספים תאנים מן הקצים אף אין בצרים ענב מן הסנה׃ ");
INSERT INTO heb_vpl VALUES ("LK6_45","072_6_45","LUK","6","45","45","האיש הטוב מאוצר לבבו הטוב מפיק את הטוב והאיש הרע מאוצר לבבו הרע מפיק את הרע כי משפעת הלב ימלל פיהו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_46","072_6_46","LUK","6","46","46","ולמה זה אתם קראים לי אדני אדני ואינכם עשים את אשר אני אמר׃ ");
INSERT INTO heb_vpl VALUES ("LK6_47","072_6_47","LUK","6","47","47","כל הבא אלי ושומע את דברי ועשה אתם אורה אתכם למי הוא דומה׃ ");
INSERT INTO heb_vpl VALUES ("LK6_48","072_6_48","LUK","6","48","48","דומה הוא לאיש בנה בית אשר העמיק לחפר וייסדו על הסלע וכבוא השטף פרץ הנהר בבית ההוא ולא יכל להניעו כי על הסלע יסודו׃ ");
INSERT INTO heb_vpl VALUES ("LK6_49","072_6_49","LUK","6","49","49","ואשר שמע ולא עשה דומה לאיש אשר בנה בית על הקרקע בלי יסוד ויפרץ בו הנהר ויפל פתאם ויגדל שבר הבית ההוא׃ ");
INSERT INTO heb_vpl VALUES ("LK7_1","072_7_1","LUK","7","1","1","ויהי אחרי כלותו לדבר את כל דבריו באזני העם ויבא אל כפר נחום׃ ");
INSERT INTO heb_vpl VALUES ("LK7_2","072_7_2","LUK","7","2","2","ועבד לאחד משרי המאות חלה למות והוא יקר לו מאד׃ ");
INSERT INTO heb_vpl VALUES ("LK7_3","072_7_3","LUK","7","3","3","וישמע את שמע ישוע וישלח אליו מזקני היהודים וישאל מאתו לבוא ולהושיע את עבדו׃ ");
INSERT INTO heb_vpl VALUES ("LK7_4","072_7_4","LUK","7","4","4","ויבאו אל ישוע ויתחננו לו מאד ויאמרו ראוי הוא אשר תעשה בקשתו׃ ");
INSERT INTO heb_vpl VALUES ("LK7_5","072_7_5","LUK","7","5","5","כי אהב עמנו הוא והוא בנה לנו את בית הכנסת׃ ");
INSERT INTO heb_vpl VALUES ("LK7_6","072_7_6","LUK","7","6","6","וילך אתם ישוע ויהי כאשר קרב אל הבית וישלח אליו שר המאה על ידי רעיו לאמר לו בי אדני אל נא תטריח את עצמך כי אינני כדי שתבוא בצל קורתי׃ ");
INSERT INTO heb_vpl VALUES ("LK7_7","072_7_7","LUK","7","7","7","ובעבור זאת גם את עצמי לא חשבתי ראוי לבוא אליך אך דבר נא דבר וירפא נערי׃ ");
INSERT INTO heb_vpl VALUES ("LK7_8","072_7_8","LUK","7","8","8","כי גם אנכי איש נתון תחת השלטון יש תחת ידי אנשי צבא ואמרתי לזה לך והלך ולזה בוא ובא ולעבדי עשה זאת ועשה׃ ");
INSERT INTO heb_vpl VALUES ("LK7_9","072_7_9","LUK","7","9","9","וישמע ישוע את דבריו ויתמה עליו ויפן ויאמר אל ההמון ההלך אחריו אמר אני לכם גם בישראל לא מצאתי אמונה גדולה כזאת׃ ");
INSERT INTO heb_vpl VALUES ("LK7_10","072_7_10","LUK","7","10","10","וישובו השלוחים אל הבית וימצאו את העבד החלה והוא נרפא׃ ");
INSERT INTO heb_vpl VALUES ("LK7_11","072_7_11","LUK","7","11","11","ויהי ממחרת וילך אל עיר ושמה נעים ורבים מתלמידיו הלכים אתו והמון עם רב׃ ");
INSERT INTO heb_vpl VALUES ("LK7_12","072_7_12","LUK","7","12","12","הוא קרב אל שער העיר והנה מוציאים מת בן יחיד לאמו והיא אלמנה ועמה רבים מעם העיר׃ ");
INSERT INTO heb_vpl VALUES ("LK7_13","072_7_13","LUK","7","13","13","וכראות אתה האדון נכמרו רחמיו עליה ויאמר לה אל תבכי׃ ");
INSERT INTO heb_vpl VALUES ("LK7_14","072_7_14","LUK","7","14","14","ויגש ויגע בארון והנשאים עמדו ויאמר עלם אמר אני אליך קומה׃ ");
INSERT INTO heb_vpl VALUES ("LK7_15","072_7_15","LUK","7","15","15","ויתעודד המת ויחל לדבר ויתנהו לאמו׃ ");
INSERT INTO heb_vpl VALUES ("LK7_16","072_7_16","LUK","7","16","16","ותאחז כלם רעדה וישבחו את האלהים ויאמרו כי נביא גדול קם בקרבנו וכי פקד האלהים את עמו׃ ");
INSERT INTO heb_vpl VALUES ("LK7_17","072_7_17","LUK","7","17","17","ויצא הדבר הזה בכל יהודה ובכל הככר׃ ");
INSERT INTO heb_vpl VALUES ("LK7_18","072_7_18","LUK","7","18","18","ותלמידי יוחנן הגידו לו את כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("LK7_19","072_7_19","LUK","7","19","19","ויקרא אליו יוחנן שנים מתלמידיו וישלחם אל ישוע לאמר לו האתה הוא הבא אם נחכה לאחר׃ ");
INSERT INTO heb_vpl VALUES ("LK7_20","072_7_20","LUK","7","20","20","ויבאו אליו האנשים ויאמרו יוחנן המטביל שלחנו אליך לאמר האתה הוא הבא אם נחכה לאחר׃ ");
INSERT INTO heb_vpl VALUES ("LK7_21","072_7_21","LUK","7","21","21","בעת ההיא רפא רבים מחליים ומנגעים ומרוחות רעות ולעורים רבים נתן ראות עינים׃ ");
INSERT INTO heb_vpl VALUES ("LK7_22","072_7_22","LUK","7","22","22","ויען ישוע ויאמר להם לכו והגידו ליוחנן את אשר ראיתם ואשר שמעתם כי עורים ראים ופסחים מתהלכים ומצרעים מטהרים וחרשים שומעים ומתים קמים ועניים מתבשרים׃ ");
INSERT INTO heb_vpl VALUES ("LK7_23","072_7_23","LUK","7","23","23","ואשרי אשר לא יכשל בי׃ ");
INSERT INTO heb_vpl VALUES ("LK7_24","072_7_24","LUK","7","24","24","ויהי כאשר הלכו להם שלוחי יוחנן ויחל לדבר אל המון העם על אדות יוחנן ויאמר מה זה יצאתם המדברה לראות הקנה אשר ינוע ברוח׃ ");
INSERT INTO heb_vpl VALUES ("LK7_25","072_7_25","LUK","7","25","25","ואם לא מה זה יצאתם לראות האיש לבוש בגדי עדנים הנה המלבשים בגדי תפארת והמענגים בחצרות המלכים המה׃ ");
INSERT INTO heb_vpl VALUES ("LK7_26","072_7_26","LUK","7","26","26","ועתה מה זה יצאתם לראות אם לראות איש נביא הן אני אמר לכם כי אף גדול הוא מנביא׃ ");
INSERT INTO heb_vpl VALUES ("LK7_27","072_7_27","LUK","7","27","27","זה הוא אשר כתוב עליו הנני שלח מלאכי לפניך ופנה דרכך לפניך׃ ");
INSERT INTO heb_vpl VALUES ("LK7_28","072_7_28","LUK","7","28","28","כי אמר אני לכם אין איש בילודי אשה גדול מיוחנן המטביל אך הקטן במלכות האלהים גדול הוא ממנו׃ ");
INSERT INTO heb_vpl VALUES ("LK7_29","072_7_29","LUK","7","29","29","וכל העם והמכסים כשמעם הצדיקו את האלהים ויטבלו בטבילת יוחנן׃ ");
INSERT INTO heb_vpl VALUES ("LK7_30","072_7_30","LUK","7","30","30","אך הפרושים ובעלי התורה נאצו את עצת האלהים על נפשם ולא נטבלו על ידו׃ ");
INSERT INTO heb_vpl VALUES ("LK7_31","072_7_31","LUK","7","31","31","ויאמר האדון עתה אל מי אדמה את אנשי הדור הזה ואל מי הם דמים׃ ");
INSERT INTO heb_vpl VALUES ("LK7_32","072_7_32","LUK","7","32","32","דמים הם לילדים הישבים בשוק וקראים זה אל זה ואמרים חללנו לכם בחלילים ולא רקדתם קוננו לכם קינה ולא בכיתם׃ ");
INSERT INTO heb_vpl VALUES ("LK7_33","072_7_33","LUK","7","33","33","כי בא יוחנן המטביל לחם לא אכל ויין לא שתה ואמרתם שד בו׃ ");
INSERT INTO heb_vpl VALUES ("LK7_34","072_7_34","LUK","7","34","34","ובא בן האדם והוא אכל ושתה ואמרתם הנה זולל וסבא ורע למוכסים ולחטאים׃ ");
INSERT INTO heb_vpl VALUES ("LK7_35","072_7_35","LUK","7","35","35","ותצדק החכמה על ידי כל בניה׃ ");
INSERT INTO heb_vpl VALUES ("LK7_36","072_7_36","LUK","7","36","36","ויבקש ממנו אחד מן הפרושים לאכל אתו לחם ויבא אל בית הפרוש ויסב׃ ");
INSERT INTO heb_vpl VALUES ("LK7_37","072_7_37","LUK","7","37","37","והנה אשה אחת בעיר והיא חטאת שמעה כי הוא מסב בית הפרוש ותבא פך שמן המור׃ ");
INSERT INTO heb_vpl VALUES ("LK7_38","072_7_38","LUK","7","38","38","ותעמד לרגליו מאחריו ותבך ותחל להרטיב את רגליו בדמעות ותנגב אתן בשערות ראשה ותשק את רגליו ותמשח אתן בשמן׃ ");
INSERT INTO heb_vpl VALUES ("LK7_39","072_7_39","LUK","7","39","39","וירא הפרוש הקרא אתו ויאמר בלבו אלו היה זה נביא כי עתה ידע ידע מי היא זאת ואי זו היא הנגעת בו כי אשה חטאת היא׃ ");
INSERT INTO heb_vpl VALUES ("LK7_40","072_7_40","LUK","7","40","40","ויען ישוע ויאמר אליו שמעון דבר לי אליך ויאמר רבי דבר׃ ");
INSERT INTO heb_vpl VALUES ("LK7_41","072_7_41","LUK","7","41","41","שני חיבים היו לנשה אחד האחד חיב לו דינרים חמש מאות והשני דינרים חמשים׃ ");
INSERT INTO heb_vpl VALUES ("LK7_42","072_7_42","LUK","7","42","42","ויהי באשר לא השיגה ידם לשלם וישמט את שניהם ועתה אמר נא מי משניהם ירבה לאהבה אתו׃ ");
INSERT INTO heb_vpl VALUES ("LK7_43","072_7_43","LUK","7","43","43","ויען שמעון ויאמר אחשב כי האיש ההוא אשר הרבה להשמיט לו ויאמר אליו כן שפטת׃ ");
INSERT INTO heb_vpl VALUES ("LK7_44","072_7_44","LUK","7","44","44","ויפן אל האשה ויאמר אל שמעון הראית את האשה הזאת הנה באתי אל ביתך ומים על רגלי לא נתת והיא הרטיבה את רגלי בדמעות ותנגב בשערותיה׃ ");
INSERT INTO heb_vpl VALUES ("LK7_45","072_7_45","LUK","7","45","45","נשיקה לא נשקתני והיא מאז באתי לא חדלה מנשק את רגלי׃ ");
INSERT INTO heb_vpl VALUES ("LK7_46","072_7_46","LUK","7","46","46","בשמן לא משחת את ראשי והיא בשמן המור משחה את רגלי׃ ");
INSERT INTO heb_vpl VALUES ("LK7_47","072_7_47","LUK","7","47","47","לכן אני אמר אליך נסלחו לה חטאתיה הרבות כי הרבה אהבה ואשר נסלח לו מעט הוא אהב מעט׃ ");
INSERT INTO heb_vpl VALUES ("LK7_48","072_7_48","LUK","7","48","48","ויאמר אליה נסלחו לך חטאתיך׃ ");
INSERT INTO heb_vpl VALUES ("LK7_49","072_7_49","LUK","7","49","49","ויחלו המסבים עמו לאמר בלבם מי הוא זה אשר גם יסלח חטאים׃ ");
INSERT INTO heb_vpl VALUES ("LK7_50","072_7_50","LUK","7","50","50","ויאמר אל האשה אמונתך הושיעה לך לכי לשלום׃ ");
INSERT INTO heb_vpl VALUES ("LK8_1","072_8_1","LUK","8","1","1","ויהי אחרי כן ויעבר מעיר אל עיר ומכפר אל כפר קורא ומבשר את מלכות האלהים ושנים העשר אתו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_2","072_8_2","LUK","8","2","2","ונשים אשר נרפאו מרוחות רעות ומחליים מרים הנקראה מגדלית אשר גרשו ממנה שבעה שדים׃ ");
INSERT INTO heb_vpl VALUES ("LK8_3","072_8_3","LUK","8","3","3","ויוחנה אשת כוזא סוכן הורדוס ושושנה ואחרות רבות אשר שרתהו מנכסיהן׃ ");
INSERT INTO heb_vpl VALUES ("LK8_4","072_8_4","LUK","8","4","4","ויהי בהתאסף המון עם רב אשר יצאו אליו מעיר ועיר וידבר במשל׃ ");
INSERT INTO heb_vpl VALUES ("LK8_5","072_8_5","LUK","8","5","5","הזורע יצא לזרע את זרעו ובזרעו נפל מן הזרע על יד הדרך וירמס ועוף השמים אכלו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_6","072_8_6","LUK","8","6","6","ויש אשר נפל על הסלע ויצמח וייבש כי לא היתה לו לחה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_7","072_8_7","LUK","8","7","7","ויש אשר נפל בתוך הקצים ויצמחו הקצים עמו וימעכהו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_8","072_8_8","LUK","8","8","8","ויש אשר נפל על האדמה הטובה ויצמח ויעש פרי מאה שערים כזאת דבר ויזעק מי אשר אזנים לו לשמע ישמע׃ ");
INSERT INTO heb_vpl VALUES ("LK8_9","072_8_9","LUK","8","9","9","וישאלהו תלמידיו לאמר מה המשל הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_10","072_8_10","LUK","8","10","10","ויאמר לכם נתן לדעת את סודות מלכות האלהים ולאחרים במשלים למען בראתם לא יראו ובשמעם לא יבינו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_11","072_8_11","LUK","8","11","11","וזה הוא המשל הזרע דבר אלהים הוא׃ ");
INSERT INTO heb_vpl VALUES ("LK8_12","072_8_12","LUK","8","12","12","ואשר על יד הדרך הם השמעים ואחר כן בא השטן ונשא את הדבר מלבם פן יאמינו ונושעו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_13","072_8_13","LUK","8","13","13","ואשר על הסלע הם המקבלים בשמחה את הדבר בשמעם ושרש אין להם רק לשעה מאמינים ובעת הנסיון יסגו אחור׃ ");
INSERT INTO heb_vpl VALUES ("LK8_14","072_8_14","LUK","8","14","14","ואשר נפל בין הקצים הם השמעים והוליכם להם וימכו בדאגות ובעשר ובתאות החיים ופרי לא ישוו למו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_15","072_8_15","LUK","8","15","15","ואשר באדמה הטובה הם השמרים בלב טוב וטהור את הדבר אשר שמעו ועשים פרי בתוחלת׃ ");
INSERT INTO heb_vpl VALUES ("LK8_16","072_8_16","LUK","8","16","16","ואין איש מדליק נר אשר יכסה אותו בכלי או ישימהו תחת המטה כי אם על המנורה יעלהו למען יראו כל באי הבית את האור׃ ");
INSERT INTO heb_vpl VALUES ("LK8_17","072_8_17","LUK","8","17","17","כי אין דבר נעלם אשר לא יגלה ואין גנוז אשר לא יודע ובא לאור׃ ");
INSERT INTO heb_vpl VALUES ("LK8_18","072_8_18","LUK","8","18","18","לכן ראו איך תשמעון כי כל אשר יש לו נתון ינתן לו וכל אשר אין לו גם את אשר הוא חשב להיות לו יקח ממנו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_19","072_8_19","LUK","8","19","19","ויבאו אליו אמו ואחיו ולא יכלו לגשת אליו מפני העם׃ ");
INSERT INTO heb_vpl VALUES ("LK8_20","072_8_20","LUK","8","20","20","ויגד לו לאמר אמך ואחיך עמדים בחוץ והם חפצים לראותך׃ ");
INSERT INTO heb_vpl VALUES ("LK8_21","072_8_21","LUK","8","21","21","ויען ויאמר אליהם אמי ואחי הם השמעים ועשים את דבר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK8_22","072_8_22","LUK","8","22","22","ויהי היום וירד אל אניה הוא ותלמידיו ויאמר אליהם נעברה אל עבר הים וישוטו הימה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_23","072_8_23","LUK","8","23","23","ויהי בלכתם באניה וישכב ויישן ורוח סערה ירדה על הים וישטפו עליהם המים ויהיו בסכנה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_24","072_8_24","LUK","8","24","24","ויגשו ויעירו אותו לאמר מורה מורה אבדנו ויעור ויגער ברוח ובמשברי ים וישתקו ותהי דממה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_25","072_8_25","LUK","8","25","25","ויאמר אליהם איה אמונתכם וייראו ויתמהו ויאמרו איש אל רעהו מי אפוא הוא המצוה גם את הרוחות ואת המים וישמעו לו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_26","072_8_26","LUK","8","26","26","ויעברו ויבאו אל ארץ הגדריים אשר ממול הגליל׃ ");
INSERT INTO heb_vpl VALUES ("LK8_27","072_8_27","LUK","8","27","27","ויצא אל היבשה ויפגשהו איש מן העיר אשר שדים בו מימים רבים ובגד לא לבש ובבית לא ישב כי אם בקברים׃ ");
INSERT INTO heb_vpl VALUES ("LK8_28","072_8_28","LUK","8","28","28","וירא את ישוע ויפל לפניו ויקרא בקול גדול מה לי ולך ישוע בן אל עליון מבקש אני ממך אשר לא תענני׃ ");
INSERT INTO heb_vpl VALUES ("LK8_29","072_8_29","LUK","8","29","29","כי צוה את הרוח הטמא לצאת מן האיש כי ימים רבים חטף אתו ונאסר בזיקים ונשמר בכבלים והיה בנתקו את המוסרות ונדחף ביד השד אל המדברות׃ ");
INSERT INTO heb_vpl VALUES ("LK8_30","072_8_30","LUK","8","30","30","וישאל אתו ישוע לאמר מה שמך ויאמר לגיון שמי כי שדים רבים נכנסו בו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_31","072_8_31","LUK","8","31","31","ויתחנן לו לבלתי צות אתם לרדת אל התהום׃ ");
INSERT INTO heb_vpl VALUES ("LK8_32","072_8_32","LUK","8","32","32","ויהי שם עדר חזירים רבים על המרעה בהר ויתחננו לו כי יניח להם לבוא אל תוכם וינח להם׃ ");
INSERT INTO heb_vpl VALUES ("LK8_33","072_8_33","LUK","8","33","33","ויצאו השדים מן האדם ההוא ויבאו בחזירים וישתער העדר מן המורד אל הים ויטבע׃ ");
INSERT INTO heb_vpl VALUES ("LK8_34","072_8_34","LUK","8","34","34","וינוסו הרעים כראותם את אשר נעשה ויגידו הדבר בעיר ובכפרים׃ ");
INSERT INTO heb_vpl VALUES ("LK8_35","072_8_35","LUK","8","35","35","ויצאו לראת את אשר נעשה ויבאו אל ישוע וימצאו שם את האדם אשר יצאו ממנו השדים ישב לרגלי ישוע מלבש וטוב שכל וייראו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_36","072_8_36","LUK","8","36","36","ויספרו להם הראים איך נרפא אחוז השדים׃ ");
INSERT INTO heb_vpl VALUES ("LK8_37","072_8_37","LUK","8","37","37","ויבקשו ממנו כל המון חבל הגדריים ללכת מאתם כי אימה גדולה נפלה עליהם וירד אל האניה וישב׃ ");
INSERT INTO heb_vpl VALUES ("LK8_38","072_8_38","LUK","8","38","38","ויבקש ממנו האיש אשר יצאו ממנו השדים לשבת אתו וישלח אתו ישוע באמרו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_39","072_8_39","LUK","8","39","39","שוב לביתך וספר הגדלות אשר עשה לך האלהים וילך לו וישמע בכל העיר את הגדלות אשר עשה לו ישוע׃ ");
INSERT INTO heb_vpl VALUES ("LK8_40","072_8_40","LUK","8","40","40","ויהי בשוב ישוע ויקבל אתו העם כי כלם היו מחכים לו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_41","072_8_41","LUK","8","41","41","והנה בא איש ושמו יאיר והוא ראש בית הכנסת ויפל לרגלי ישוע ויתחנן לו לבוא אתו אל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("LK8_42","072_8_42","LUK","8","42","42","כי בת יחידה כשתים עשרה שנה היתה לו והיא נוטה למות ויהי בלכתו שמה וידחקהו המון העם׃ ");
INSERT INTO heb_vpl VALUES ("LK8_43","072_8_43","LUK","8","43","43","ואשה זבת דם שתים עשרה שנה אשר הוציאה כל קנינה לרפאים ואין איש יכל לרפאתה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_44","072_8_44","LUK","8","44","44","היא קרבה מאחריו ותגע בציצת בגדו וזוב דמה עמד פתאם׃ ");
INSERT INTO heb_vpl VALUES ("LK8_45","072_8_45","LUK","8","45","45","ויאמר ישוע מי זה נגע בי וכלם כחשו ויאמר פטרוס והעמדים אצלו מורה המון העם דחקים ולחצים אתך ואתה תאמר מי נגע בי׃ ");
INSERT INTO heb_vpl VALUES ("LK8_46","072_8_46","LUK","8","46","46","ויאמר ישוע נגע בי אדם כי ידעתי אשר יצאה ממני גבורה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_47","072_8_47","LUK","8","47","47","ותרא האשה כי לא נסתרה ממנו ותחרד לקראתו ותפל לפניו ותגד באזני כל העם על מה נגעה בו ואיך נרפאה פתאם׃ ");
INSERT INTO heb_vpl VALUES ("LK8_48","072_8_48","LUK","8","48","48","ויאמר אליה חזקי בתי אמונתך הושיעה לך לכי לשלום׃ ");
INSERT INTO heb_vpl VALUES ("LK8_49","072_8_49","LUK","8","49","49","עודנו מדבר ואיש בא מבית ראש הכנסת ויאמר מתה בתך אל תטריח את המורה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_50","072_8_50","LUK","8","50","50","וישמע ישוע ויען ויאמר לו אל תירא אך האמן והיא תושע׃ ");
INSERT INTO heb_vpl VALUES ("LK8_51","072_8_51","LUK","8","51","51","ויבא הביתה ולא הניח לאיש לבוא אתו בלתי אם לפטרוס וליעקב וליוחנן ולאבי הילדה ולאמה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_52","072_8_52","LUK","8","52","52","וכלם בכים וספדים לה ויאמר אל תבכו כי לא מתה אך ישנה היא׃ ");
INSERT INTO heb_vpl VALUES ("LK8_53","072_8_53","LUK","8","53","53","וישחקו עליו באשר ידעו כי מתה׃ ");
INSERT INTO heb_vpl VALUES ("LK8_54","072_8_54","LUK","8","54","54","והוא אחז בידה ויקרא לאמר הילדה קומי׃ ");
INSERT INTO heb_vpl VALUES ("LK8_55","072_8_55","LUK","8","55","55","ותשב רוחה ותקם פתאם ויצו לתת לה לאכול׃ ");
INSERT INTO heb_vpl VALUES ("LK8_56","072_8_56","LUK","8","56","56","וישתוממו אביה ואמה והוא צוה אתם לבלתי הגיד לאיש את אשר נעשה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_1","072_9_1","LUK","9","1","1","ויקרא אל שנים העשר ויתן להם גבורה ושלטן על כל השדים ולרפא חליים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_2","072_9_2","LUK","9","2","2","וישלחם לקרא את מלכות האלהים ולרפא את החלים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_3","072_9_3","LUK","9","3","3","ויאמר להם אל תקחו מאומה לדרך לא מטות ולא תרמיל ולא לחם ולא כסף ואל יהיה לאיש מכם שתי כתנות׃ ");
INSERT INTO heb_vpl VALUES ("LK9_4","072_9_4","LUK","9","4","4","והבית אשר תבאו בו שם שבו לכם ומשם צאו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_5","072_9_5","LUK","9","5","5","וכל אשר לא יקבלו אתכם צאו מן העיר ההיא ונערו את העפר מעל רגליכם לעדות בהם׃ ");
INSERT INTO heb_vpl VALUES ("LK9_6","072_9_6","LUK","9","6","6","ויצאו ויעברו בכפרים מבשרים את הבשורה ומרפאים בכל מקום׃ ");
INSERT INTO heb_vpl VALUES ("LK9_7","072_9_7","LUK","9","7","7","וישמע הורדוס שר הרבע את כל אשר נעשה על ידו ותפעם רוחו כי יש אשר אמרו יוחנן קם מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_8","072_9_8","LUK","9","8","8","ויש שאמרו אליהו נראה ואחרים אמרו נביא קם מן הקדמונים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_9","072_9_9","LUK","9","9","9","ויאמר הורדוס הן אנכי נשאתי את ראש יוחנן מעליו ומי אפוא הוא אשר אני שמע עליו כזאת ויבקש לראותו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_10","072_9_10","LUK","9","10","10","וישובו השליחים ויספרו לו את כל אשר עשו ויקחם אליו ויסר לבדד אל מקום חרב אשר לעיר הנקראה בית צידה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_11","072_9_11","LUK","9","11","11","והמון העם כאשר ידעו את זאת הלכו אחריו ויקבלם וידבר אליהם על מלכות האלהים וירפא את הצריכים לרפואה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_12","072_9_12","LUK","9","12","12","והיום רפה לערב ושנים העשר קרבו ויאמרו אליו שלח נא את העם וילכו אל הכפרים והחצרים אשר סביבותינו ללון שם ולמצא מזון כי פה אנחנו במקום חרבה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_13","072_9_13","LUK","9","13","13","ויאמר אליהם תנו אתם להם לאכל ויאמרו אין לנו כי אם חמשת ככרות לחם ודגים שנים בלתי אם נלך ונקנה אכל לכל העם הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_14","072_9_14","LUK","9","14","14","כי היו כחמשת אלפי איש ויאמר אל תלמידיו הושיבו אתם שורות שורות חמשים בשורה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_15","072_9_15","LUK","9","15","15","ויעשו כן ויושיבו את כלם׃ ");
INSERT INTO heb_vpl VALUES ("LK9_16","072_9_16","LUK","9","16","16","ויקח את חמשת ככרות הלחם ואת שני הדגים וישא עיניו השמימה ויברך עליהם ויפרס ויתן לתלמידיו לשום לפני העם׃ ");
INSERT INTO heb_vpl VALUES ("LK9_17","072_9_17","LUK","9","17","17","ויאכלו כלם וישבעו וישאו מן הפתותים הנותרים להם שנים עשר סלים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_18","072_9_18","LUK","9","18","18","ויהי הוא מתפלל לבדד ויאספו אליו תלמידיו וישאל אתם לאמר מה אמרים עלי המון העם מי אני׃ ");
INSERT INTO heb_vpl VALUES ("LK9_19","072_9_19","LUK","9","19","19","ויענו ויאמרו יוחנן המטביל ואחרים אמרים אליהו ואחרים אמרים נביא קם מן הקדמונים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_20","072_9_20","LUK","9","20","20","ויאמר אליהם ואתם מה אתם אמרים מי אני ויען פטרוס ויאמר משיח האלהים אתה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_21","072_9_21","LUK","9","21","21","ויצו אתם בגערה לבלתי הגיד לאיש את הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_22","072_9_22","LUK","9","22","22","ויאמר מן הצרך הוא אשר בן האדם יענה הרבה וימאס מן הזקנים והכהנים הגדולים והסופרים ויהרג וביום השלישי קום יקום׃ ");
INSERT INTO heb_vpl VALUES ("LK9_23","072_9_23","LUK","9","23","23","ואל כלם אמר איש כי יחפץ ללכת אחרי יכחש בנפשו ויום יום ישא את צלבו והלך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("LK9_24","072_9_24","LUK","9","24","24","כי כל אשר יחפץ להושיע את נפשו תאבד נפשו ממנו וכל אשר יאבד את נפשו למעני הוא יושיענה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_25","072_9_25","LUK","9","25","25","כי מה יועיל האדם כי יקנה את כל העולם ואבד והשחית את נפשו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_26","072_9_26","LUK","9","26","26","כי כל אשר הייתי אני ודברי לו לחרפה הוא יהיה לחרפה לבן האדם כאשר יבא בכבודו ובכבוד האב והמלאכים הקדושים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_27","072_9_27","LUK","9","27","27","ובאמת אני אמר לכם יש מן העמדים פה אשר לא יטעמו מות עד כי יראו את מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_28","072_9_28","LUK","9","28","28","ויהי כשמנה ימים אחרי הדברים האלה ויקח אליו את פטרוס ואת יוחנן ואת יעקב ויעל אל ההר להתפלל שם׃ ");
INSERT INTO heb_vpl VALUES ("LK9_29","072_9_29","LUK","9","29","29","ויהי בהתפללו נשתנה מראה פניו ולבושו הלבין והבריק׃ ");
INSERT INTO heb_vpl VALUES ("LK9_30","072_9_30","LUK","9","30","30","והנה שני אנשים מדברים אתו והמה משה ואליהו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_31","072_9_31","LUK","9","31","31","אשר נראו בכבוד והגידו את אחריתו אשר ימלאנה בירושלים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_32","072_9_32","LUK","9","32","32","ויהיו פטרוס ואשר אתו נרדמים ובהקיצם ראו את כבודו ואת שני האנשים העמדים עליו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_33","072_9_33","LUK","9","33","33","ויהי בהפרדם ממנו ויאמר פטרוס אל ישוע מורה טוב היותנו פה נעשה נא שלש סכות לך אחת ולמשה אחת ולאליהו אחת ולא ידע מה דבר׃ ");
INSERT INTO heb_vpl VALUES ("LK9_34","072_9_34","LUK","9","34","34","הוא מדבר כזאת והנה ענן סכך עליהם וכבואם בענן נבעתו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_35","072_9_35","LUK","9","35","35","ויצא קול מן הענן אמר זה בני ידידי אליו תשמעון׃ ");
INSERT INTO heb_vpl VALUES ("LK9_36","072_9_36","LUK","9","36","36","ובהיות הקול נשאר ישוע לבדו והמה החשו ולא הגידו דבר לאיש בימים ההם מכל אשר ראו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_37","072_9_37","LUK","9","37","37","ויהי ממחרת ברדתם מן ההר ויצא עם רב לקראתו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_38","072_9_38","LUK","9","38","38","והנה איש אחד מן העם צעק לאמר אנא רבי פנה נא אל בני כי יחיד הוא לי׃ ");
INSERT INTO heb_vpl VALUES ("LK9_39","072_9_39","LUK","9","39","39","והנה רוח אחז בו ופתאם הוא מצעק והרוח מרוצץ אתו בהוריד רירו ומקשה לסור ממנו ובסורו ידכא אתו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_40","072_9_40","LUK","9","40","40","ואבקש מתלמידיך לגרשו ולא יכלו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_41","072_9_41","LUK","9","41","41","ויען ישוע ויאמר הוי דור חסר אמונה ופתלתל עד מתי אהיה עמכם ואסבל אתכם הבא הנה את בנך׃ ");
INSERT INTO heb_vpl VALUES ("LK9_42","072_9_42","LUK","9","42","42","ויהי אך הקריב לבוא וירעצהו השד וירוצצהו וישוע גער ברוח הטמא וירפא את הנער וישיבהו לאביו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_43","072_9_43","LUK","9","43","43","וישתוממו כלם על גדלת האלהים ויהי בתמהם כלם על כל אשר עשה ויאמר ישוע אל תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_44","072_9_44","LUK","9","44","44","שימו אתם באזניכם את הדברים האלה כי עתיד בן האדם להמסר בידי בני האדם׃ ");
INSERT INTO heb_vpl VALUES ("LK9_45","072_9_45","LUK","9","45","45","והמה לא הבינו את המאמר הזה ונעלם הוא מדעתם וייראו לשאל אתו על המאמר הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK9_46","072_9_46","LUK","9","46","46","ויעל על לבבם לחשוב מי הוא הגדול בהם׃ ");
INSERT INTO heb_vpl VALUES ("LK9_47","072_9_47","LUK","9","47","47","וירא ישוע את מחשבת לבם ויקח ילד ויעמידהו אצלו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_48","072_9_48","LUK","9","48","48","ויאמר אליהם כל אשר יקבל את הילד הזה לשמי אותי הוא מקבל וכל אשר יקבל אותי הוא מקבל את אשר שלחני כי הקטן בכלכם הוא יהיה הגדול׃ ");
INSERT INTO heb_vpl VALUES ("LK9_49","072_9_49","LUK","9","49","49","ויען יוחנן ויאמר מורה ראינו איש מגרש שדים בשמך ונכלא אותו יען איננו הולך עמנו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_50","072_9_50","LUK","9","50","50","ויאמר ישוע אליו אל תכלאו כי כל אשר איננו נגדנו בעדנו הוא׃ ");
INSERT INTO heb_vpl VALUES ("LK9_51","072_9_51","LUK","9","51","51","ויהי כמלאת ימי העלותו והוא שם את פניו ללכת ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_52","072_9_52","LUK","9","52","52","וישלח מלאכים לפניו וילכו ויבאו אל אחד מכפרי השמרונים להכין לו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_53","072_9_53","LUK","9","53","53","ולא קבלהו על אשר היו פניו הלכים ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_54","072_9_54","LUK","9","54","54","ויאמרו יעקב ויוחנן תלמידיו כראותם זאת לאמר אדנינו התרצה ונאמר כי תרד אש מן השמים ותאכלם כאשר עשה גם אליהו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_55","072_9_55","LUK","9","55","55","ויפן ויגער בם ויאמר הלא ידעתם בני רוח מי אתם׃ ");
INSERT INTO heb_vpl VALUES ("LK9_56","072_9_56","LUK","9","56","56","כי בן האדם לא בא לאבד נפשות אדם כי אם להושיעם וילכו להם אל כפר אחר׃ ");
INSERT INTO heb_vpl VALUES ("LK9_57","072_9_57","LUK","9","57","57","ויהי בלכתם בדרך ויאמר אליו איש אדני אלכה אחריך אל כל אשר תלך׃ ");
INSERT INTO heb_vpl VALUES ("LK9_58","072_9_58","LUK","9","58","58","ויאמר אליו ישוע לשועלים יש חורי עפר ולעוף השמים קנים ובן האדם אין לו מקום להניח שם את ראשו׃ ");
INSERT INTO heb_vpl VALUES ("LK9_59","072_9_59","LUK","9","59","59","ואל איש אחר אמר לך אחרי והוא אמר אדני תן לי ואלכה בראשונה לקבר את אבי׃ ");
INSERT INTO heb_vpl VALUES ("LK9_60","072_9_60","LUK","9","60","60","ויאמר אליו ישוע הנח למתים לקבר את מתיהם ואתה לך הודע את מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK9_61","072_9_61","LUK","9","61","61","ויאמר עוד איש אחר אלכה אחריך אדני אך הניחה לי בראשונה להפטר מבני ביתי׃ ");
INSERT INTO heb_vpl VALUES ("LK9_62","072_9_62","LUK","9","62","62","ויאמר ישוע כל השם את ידו על המחרשה ומביט אחריו לא יכשר למלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK10_1","072_10_1","LUK","10","1","1","ואחרי כן הבדיל האדון עוד שבעים אחרים וישלחם לפניו שנים שנים אל כל עיר ומקום אשר בקש לבוא שמה׃ ");
INSERT INTO heb_vpl VALUES ("LK10_2","072_10_2","LUK","10","2","2","ויאמר להם הן הקציר רב והפעלים מעטים לכן התחננו אל אדון הקציר וישלח פעלים לקצירו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_3","072_10_3","LUK","10","3","3","לכו נא הנני שלח אתכם ככבשים בין הזאבים׃ ");
INSERT INTO heb_vpl VALUES ("LK10_4","072_10_4","LUK","10","4","4","אל תשאו כיס ולא תרמיל ולא נעלים ואל תשאלו לשלום איש בדרך׃ ");
INSERT INTO heb_vpl VALUES ("LK10_5","072_10_5","LUK","10","5","5","ולכל בית אשר תבאו שם אמרו בראשונה שלום לבית הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK10_6","072_10_6","LUK","10","6","6","והיה כי יהיה שם בן שלום ונח עליו שלומכם ואם לא אליכם ישוב׃ ");
INSERT INTO heb_vpl VALUES ("LK10_7","072_10_7","LUK","10","7","7","ובבית ההוא תשבו ותאכלו ותשתו משלהם כי שוה הפועל בשכרו אל תסעו מבית לבית׃ ");
INSERT INTO heb_vpl VALUES ("LK10_8","072_10_8","LUK","10","8","8","וכל עיר אשר תבאו בה וקבלו אתכם אכלו שם את אשר ישימו לפניכם׃ ");
INSERT INTO heb_vpl VALUES ("LK10_9","072_10_9","LUK","10","9","9","ורפאו את החולים אשר בקרבה ואמרו להם קרבה אליכם מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK10_10","072_10_10","LUK","10","10","10","וכל עיר אשר תבאו בה ולא יקבלו אתכם צאו לכם אל רחובותיה ואמרו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_11","072_10_11","LUK","10","11","11","אף את עפר עירכם הנדבק ברגלינו ננערהו לכם אך ידע תדעו כי קרבה אליכם מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK10_12","072_10_12","LUK","10","12","12","אני אמר אלכים כי לסדום יקל ביום ההוא מן העיר ההיא׃ ");
INSERT INTO heb_vpl VALUES ("LK10_13","072_10_13","LUK","10","13","13","אוי לך כורזין אוי לך בית צידה כי הגבורות אשר נעשו בקרבכן אלו נעשו בצור ובצידון הלא כבר ישבו בשק ואפר ושבו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_14","072_10_14","LUK","10","14","14","אכן לצור וצידון יקל בדין מכם׃ ");
INSERT INTO heb_vpl VALUES ("LK10_15","072_10_15","LUK","10","15","15","ואת כפר נחום אשר עד השמים התרוממת אל שאול תורדי׃ ");
INSERT INTO heb_vpl VALUES ("LK10_16","072_10_16","LUK","10","16","16","השומע אליכם אלי הוא שומע והבוזה אתכם אותי הוא בוזה והבוזה אותי הוא בוזה את אשר שלחני׃ ");
INSERT INTO heb_vpl VALUES ("LK10_17","072_10_17","LUK","10","17","17","וישובו השבעים בשמחה ויאמרו אדנינו גם השדים נכנעים לנו בשמך׃ ");
INSERT INTO heb_vpl VALUES ("LK10_18","072_10_18","LUK","10","18","18","ויאמר אליהם ראיתי את השטן נפל כברק מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("LK10_19","072_10_19","LUK","10","19","19","הנה השלטתי אתכם לדרך על נחשים ועקרבים ועל כל גבורת האיב וכל דבר לא יזיק לכם׃ ");
INSERT INTO heb_vpl VALUES ("LK10_20","072_10_20","LUK","10","20","20","אך בזאת אל תשמחו כי נכנעים לכם הרוחות כי אם שמחו על אשר נכתבו שמותיכם בשמים׃ ");
INSERT INTO heb_vpl VALUES ("LK10_21","072_10_21","LUK","10","21","21","בשעה ההיא עלץ ישוע ברוח ויאמר אודך האב אדון השמים והארץ כי הסתרת את אלה מן החכמים והנבונים וגליתם לעללים הן אבי כי כן היה רצון מלפניך׃ ");
INSERT INTO heb_vpl VALUES ("LK10_22","072_10_22","LUK","10","22","22","הכל נמסר לי מאת אבי ואין יודע מי הוא הבן בלתי האב ומי הוא האב בלתי הבן ואשר יחפץ הבן לגלותו לו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_23","072_10_23","LUK","10","23","23","ויפן אל תלמידיו לבדם ויאמר אשרי העינים הראות את אשר אתם ראים׃ ");
INSERT INTO heb_vpl VALUES ("LK10_24","072_10_24","LUK","10","24","24","כי אני אמר לכם נביאים ומלכים רבים חפצו לראות את אשר אתם ראים ולא ראו ולשמע את אשר אתם שמעים ולא שמעו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_25","072_10_25","LUK","10","25","25","והנה אחד מבעלי התורה קם לנסותו ויאמר מורה מה אעשה ואירש חיי עולם׃ ");
INSERT INTO heb_vpl VALUES ("LK10_26","072_10_26","LUK","10","26","26","ויאמר אליו מה כתוב בתורה ואיך אתה קורא׃ ");
INSERT INTO heb_vpl VALUES ("LK10_27","072_10_27","LUK","10","27","27","ויען ויאמר ואהבת את יהוה אלהיך בכל לבבך ובכל נפשך ובכל מאדך ובכל מדעך ואת רעך כמוך׃ ");
INSERT INTO heb_vpl VALUES ("LK10_28","072_10_28","LUK","10","28","28","ויאמר אליו כן השיבות עשה זאת וחיה׃ ");
INSERT INTO heb_vpl VALUES ("LK10_29","072_10_29","LUK","10","29","29","והוא חפץ להצטדק ויאמר אל ישוע ומי הוא רעי׃ ");
INSERT INTO heb_vpl VALUES ("LK10_30","072_10_30","LUK","10","30","30","ויען ישוע ויאמר איש אחד ירד מירושלים ליריחו ונפל בידי שדדים והם הפשיטהו וגם פצעהו ויעזבו אותו בין חיים למות וילכו להם׃ ");
INSERT INTO heb_vpl VALUES ("LK10_31","072_10_31","LUK","10","31","31","ויקר המקרה כי ירד כהן אחד בדרך ההוא וירא אתו ויעבר מעליו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_32","072_10_32","LUK","10","32","32","וכן גם איש לוי פגע במקום ויגש וירא אתו ויעבר מעליו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_33","072_10_33","LUK","10","33","33","ואיש שמרוני הלך בדרך ויבא עליו וירא אתו ויהמו רחמיו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_34","072_10_34","LUK","10","34","34","ויגש אליו ויחבש את פצעיו ויסוכם בשמן ויין ויעלהו על בהמתו ויוליכהו אל המלון ויכלכלהו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_35","072_10_35","LUK","10","35","35","ולמחרת בנסעו הוציא שני דינרים ויתנם לבעל המלון ויאמר כלכל אותו ואת אשר תוסיף עוד להוציא עליו אני בשובי אשלמנו לך׃ ");
INSERT INTO heb_vpl VALUES ("LK10_36","072_10_36","LUK","10","36","36","ועתה מי מאלה השלשה היה בעיניך הרע לנפל בידי השדדים׃ ");
INSERT INTO heb_vpl VALUES ("LK10_37","072_10_37","LUK","10","37","37","ויאמר העשה עמו את החסד ויאמר אליו ישוע לך ועשה כן גם אתה׃ ");
INSERT INTO heb_vpl VALUES ("LK10_38","072_10_38","LUK","10","38","38","ויהי בנסעם ויבא אל כפר אחד ואשה אחת ושמה מרתא אספה אותו אל ביתה׃ ");
INSERT INTO heb_vpl VALUES ("LK10_39","072_10_39","LUK","10","39","39","ולה היתה אחות ושמה מרים אשר ישבה לרגלי ישוע לשמע אל דברו׃ ");
INSERT INTO heb_vpl VALUES ("LK10_40","072_10_40","LUK","10","40","40","ומרתא יגעה ברב שרותה ותגש ותאמר הלא תשים על לבך אדני אשר אחותי עזבתני לשרת לבדי אמר נא אליה ותעזר לי׃ ");
INSERT INTO heb_vpl VALUES ("LK10_41","072_10_41","LUK","10","41","41","ויען ישוע ויאמר לה מרתא מרתא את דאגת ומבהלת על הרבה׃ ");
INSERT INTO heb_vpl VALUES ("LK10_42","072_10_42","LUK","10","42","42","אבל אחת היא מן הצרך ומרים בחרה לה החלק הטוב אשר לא יקח ממנה׃ ");
INSERT INTO heb_vpl VALUES ("LK11_1","072_11_1","LUK","11","1","1","ויהי הוא מתפלל במקום אחד ויאמר אליו אחד מתלמידיו אחרי כלותו אדני למדנו להתפלל כאשר למד גם יוחנן את תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_2","072_11_2","LUK","11","2","2","ויאמר אליהם כי תתפללו אמרו אבינו שבשמים יתקדש שמך תבוא מלכותך יעשה רצונך כמו בשמים כן בארץ׃ ");
INSERT INTO heb_vpl VALUES ("LK11_3","072_11_3","LUK","11","3","3","את לחם חקנו תן לנו יום יום׃ ");
INSERT INTO heb_vpl VALUES ("LK11_4","072_11_4","LUK","11","4","4","וסלח לנו את חובתנו כי סלחים גם אנחנו לכל החיב לנו ואל תביאנו לידי נסיון כי אם הצילנו מן הרע׃ ");
INSERT INTO heb_vpl VALUES ("LK11_5","072_11_5","LUK","11","5","5","ויאמר אליהם מי בכם אשר יהיה לו אהב והלך ובא אליו בחצות הלילה ואמר אליו ידידי הלוני שלשת ככרות לחם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_6","072_11_6","LUK","11","6","6","כי אהבי בא אלי מן הדרך ואין לי דבר לשום לפניו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_7","072_11_7","LUK","11","7","7","והוא מלפנים יענה ויאמר אל תוגיעני כי כבר נסגרה הדלת וילדי שוכבים עמדי במטה לא אוכל לקום ולתת לך׃ ");
INSERT INTO heb_vpl VALUES ("LK11_8","072_11_8","LUK","11","8","8","אני אמר לכם גם כי לא יקום לתת לו על היותו אהבו יקום בעבור עזות פניו ויתן לו ככל צרכו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_9","072_11_9","LUK","11","9","9","וגם אני אמר לכם שאלו וינתן לכם דרשו ותמצאו דפקו ויפתח לכם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_10","072_11_10","LUK","11","10","10","כי כל השאל יקבל והדרש ימצא ולדפק יפתח׃ ");
INSERT INTO heb_vpl VALUES ("LK11_11","072_11_11","LUK","11","11","11","ומי בכם האב אשר ישאל ממנו בנו לחם ונתן לו אבן ואם דג היתן לו נחש תחת הדג׃ ");
INSERT INTO heb_vpl VALUES ("LK11_12","072_11_12","LUK","11","12","12","או כי ישאלנו ביצה היתן לו עקרב׃ ");
INSERT INTO heb_vpl VALUES ("LK11_13","072_11_13","LUK","11","13","13","הן אתם הרעים ידעים לתת מתנות טבות לבניכם אף כי האב מן השמים יתן את רוח הקדש לשאלים מאתו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_14","072_11_14","LUK","11","14","14","ויהי היום ויגרש שד והוא אלם ויהי אחרי צאת השד וידבר האלם ויתמהו העם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_15","072_11_15","LUK","11","15","15","ויש אשר אמרו בבעל זבוב שר השדים הוא מגרש את השדים׃ ");
INSERT INTO heb_vpl VALUES ("LK11_16","072_11_16","LUK","11","16","16","ויש אשר נסוהו וישאלו ממנו אות מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("LK11_17","072_11_17","LUK","11","17","17","והוא ידע את מחשבותם ויאמר אליהם כל ממלכה הנחלקה על עצמה תחרב ובית יפל על בית׃ ");
INSERT INTO heb_vpl VALUES ("LK11_18","072_11_18","LUK","11","18","18","וגם השטן אם נחלק על עצמו איככה תכון ממלכתו כי אמרתם שבבעל זבוב מגרש אני את השדים׃ ");
INSERT INTO heb_vpl VALUES ("LK11_19","072_11_19","LUK","11","19","19","ואם אני מגרש את השדים בבעל זבוב בניכם במי הם מגרשים אתם על כן המה יהיו שפטיכם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_20","072_11_20","LUK","11","20","20","ואם באצבע אלהים מגרש אני את השדים הנה הגיעה אליכם מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK11_21","072_11_21","LUK","11","21","21","בהיות הגבור שמר את חצרו והוא מזין והיה רכושו שלום׃ ");
INSERT INTO heb_vpl VALUES ("LK11_22","072_11_22","LUK","11","22","22","ואם יבוא עליו חזק ממנו ותקפו ישא ממנו את נשקו אשר בטח בו ואת מלקחו יחלק׃ ");
INSERT INTO heb_vpl VALUES ("LK11_23","072_11_23","LUK","11","23","23","כל אשר איננו אתי הוא לנגדי ואשר איננו מאסף אתי הוא מפזר׃ ");
INSERT INTO heb_vpl VALUES ("LK11_24","072_11_24","LUK","11","24","24","הרוח הטמאה אחרי צאתה מן האדם תשוטט במקמות ציה לבקש לה מנוחה ולא תמצא אז תאמר אשובה נא אל ביתי אשר יצאתי משם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_25","072_11_25","LUK","11","25","25","ובבואה תמצא אתו מטאטא ומהדר׃ ");
INSERT INTO heb_vpl VALUES ("LK11_26","072_11_26","LUK","11","26","26","ואחר תלך ולקחה שבע רוחות אחרות רעות ממנה ובאו ושכנו שם והיתה אחרית האדם ההוא רעה מראשיתו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_27","072_11_27","LUK","11","27","27","ויהי כדברו את הדברים האלה ואשה אחת מן העם נשאה את קולה ותאמר אליו אשרי הבטן אשר נשאתך והשדים אשר ינקת׃ ");
INSERT INTO heb_vpl VALUES ("LK11_28","072_11_28","LUK","11","28","28","והוא אמר ואף כי אשרי השמעים והשמרים את דבר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK11_29","072_11_29","LUK","11","29","29","ויקבצו עם רב ויחל לדבר הדור הזה דור רע הוא אות הוא מבקש ואות לא ינתן לו בלתי אם אות יונה הנביא׃ ");
INSERT INTO heb_vpl VALUES ("LK11_30","072_11_30","LUK","11","30","30","כי כאשר היה יונה לאנשי נינוה לאות כן יהיה גם בן האדם לדור הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK11_31","072_11_31","LUK","11","31","31","מלכת תימן תקום במשפט עם אנשי הדור הזה והרשיעה אותם כי באה מקצות הארץ לשמע את חכמת שלמה והנה יש פה גדול משלמה׃ ");
INSERT INTO heb_vpl VALUES ("LK11_32","072_11_32","LUK","11","32","32","אנשי נינוה יקומו במשפט עם הדור הזה והרשיעהו כי הם שבו בקריאת יונה והנה יש פה גדול מיונה׃ ");
INSERT INTO heb_vpl VALUES ("LK11_33","072_11_33","LUK","11","33","33","אין מדליק נר אשר ישימהו בסתר או תחת האיפה כי אם על המנורה למען יראו באי הבית את אורו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_34","072_11_34","LUK","11","34","34","נר הגוף הוא העין לכן בהיות עינך תמימה גם כל גופך יאור ובהיותה רעה וחשך גם גופך׃ ");
INSERT INTO heb_vpl VALUES ("LK11_35","072_11_35","LUK","11","35","35","על כן השמר לך פן יחשך האור אשר בקרבך׃ ");
INSERT INTO heb_vpl VALUES ("LK11_36","072_11_36","LUK","11","36","36","והנה אם גופך כלו אור ואין בו כל דבר חשך אז יאור כלו והיה כהאיר לך הנר בברק נגהו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_37","072_11_37","LUK","11","37","37","ויהי בדברו ויבקש ממנו פרוש אחד לאכל אתו לחם ויבא הביתה ויסב׃ ");
INSERT INTO heb_vpl VALUES ("LK11_38","072_11_38","LUK","11","38","38","ויתמה הפרוש בראתו אשר לא נטל ידיו בראשונה לפני הסעודה׃ ");
INSERT INTO heb_vpl VALUES ("LK11_39","072_11_39","LUK","11","39","39","ויאמר אליו האדון כעת אתם הפרושים מטהרים את הכום והקערה מחוץ והפנימי אשר בכם הוא מלא גזל ורשע׃ ");
INSERT INTO heb_vpl VALUES ("LK11_40","072_11_40","LUK","11","40","40","הכסילים הלא עשה החיצון גם עשה את הפנימי׃ ");
INSERT INTO heb_vpl VALUES ("LK11_41","072_11_41","LUK","11","41","41","אבל תנו לצדקה את אשר בם והנה הכל טהור לכם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_42","072_11_42","LUK","11","42","42","אך אוי לכם הפרושים כי תעשרו את המנתא ואת הפיגם ואת כל הירק ותעברו את המשפט ואת אהבת אלהים והיה לכם לעשות את אלה ולא להניח גם את אלה׃ ");
INSERT INTO heb_vpl VALUES ("LK11_43","072_11_43","LUK","11","43","43","אוי לכם הפרושים כי תאהבו את מושב הראש בבתי הכנסיות ואת שאלות שלומכם בשוקים׃ ");
INSERT INTO heb_vpl VALUES ("LK11_44","072_11_44","LUK","11","44","44","אוי לכם הסופרים והפרושים החנפים כי אתם כקברים הנסתרים ובני האדם מתהלכים עליהם ולא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_45","072_11_45","LUK","11","45","45","ויען אחד מבעלי התורה ויאמר אליו רבי בדבריך אלה תחרף גם אתנו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_46","072_11_46","LUK","11","46","46","ויאמר אוי גם לכם בעלי התורה כי עמסים אתם על בני האדם משאות כבדים מסבל ואתם בעצמכם אינכם נגעים במשאות גם באחת מאצבעותיכם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_47","072_11_47","LUK","11","47","47","אוי לכם כי בונים אתם את קברות הנביאים ואבותיכם הרגו אותם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_48","072_11_48","LUK","11","48","48","וכן אתם מעידים ורוצים במעשי אבותיכם כי המה הרגו אותם ואתם בונים את קבריהם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_49","072_11_49","LUK","11","49","49","בעבור זאת גם אמרה חכמת האלהים אשלח אליהם נביאים ושליחים ומהם יהרגו וירדפו׃ ");
INSERT INTO heb_vpl VALUES ("LK11_50","072_11_50","LUK","11","50","50","למען ידרש מן הדור הזה דם כל הנביאים אשר נשפך למן הוסד הארץ׃ ");
INSERT INTO heb_vpl VALUES ("LK11_51","072_11_51","LUK","11","51","51","מדם הבל עד דם זכריהו אשר נהרג בין המזבח ולבית הן אמר אני לכם דרוש ידרש מן הדור הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK11_52","072_11_52","LUK","11","52","52","אוי לכם בעלי התורה כי הסירתם את מפתח הדעת אתם לא באתם ואת הבאים מנעתם׃ ");
INSERT INTO heb_vpl VALUES ("LK11_53","072_11_53","LUK","11","53","53","ויהי כדברו להם את אלה ויחלו הסופרים והפרושים לשטם אותו מאד ולהקשות לו בדברים רבים׃ ");
INSERT INTO heb_vpl VALUES ("LK11_54","072_11_54","LUK","11","54","54","ויארבו לו ויבקשו לצודד דבר מפיהו למען ימצאו עליו שטנה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_1","072_12_1","LUK","12","1","1","ויהי עד כה ועד כה בהתאסף רבבות עם עד כי לחצו איש את רעהו ויחל לדבר אל תלמידיו בראשונה השמרו לנפשתיכם משאור הפרושים שהוא החנפה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_2","072_12_2","LUK","12","2","2","ואין דבר מכסה אשר לא יגלה ואין נעלם אשר לא יודע׃ ");
INSERT INTO heb_vpl VALUES ("LK12_3","072_12_3","LUK","12","3","3","לכן כל אשר דברתם בחשך באור ישמע ואת אשר לחשתם לאזן בחדרים קרא יקרא על הגגות׃ ");
INSERT INTO heb_vpl VALUES ("LK12_4","072_12_4","LUK","12","4","4","ואני אמר לכם ידידי אל תיראו מן הממיתים את הגוף ואחרי זאת אין לאל ידם לעשות עוד דבר׃ ");
INSERT INTO heb_vpl VALUES ("LK12_5","072_12_5","LUK","12","5","5","אבל אורה אתכם את אשר תיראו יראו את אשר יש לו שלטן אחרי המיתו להשליך אל גיהנם הן אני אמר לכם אותו תיראון׃ ");
INSERT INTO heb_vpl VALUES ("LK12_6","072_12_6","LUK","12","6","6","הלא חמש צפרים תמכרנה בשני אסרים ואין אחת מהן נשכחת לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK12_7","072_12_7","LUK","12","7","7","ואתם גם שערות ראשכם נמנות כלן לכן אל תיראו יקרתם מצפרים רבות׃ ");
INSERT INTO heb_vpl VALUES ("LK12_8","072_12_8","LUK","12","8","8","ואני אמר לכם כל אשר יודה בי לפני האדם גם בן האדם יודה בו לפני מלאכי אלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK12_9","072_12_9","LUK","12","9","9","ואשר יכחש בי לפני האדם הוא יכחש לפני מלאכי אלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK12_10","072_12_10","LUK","12","10","10","וכל אשר ידבר דבר חרפה על בן האדם יסלח לו והמגדף את רוח הקדש לא יסלח לו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_11","072_12_11","LUK","12","11","11","וכאשר יביאו אתכם אל בתי הכנסיות ולפני הרשיות והשלטונים אל תדאגו איך או במה תצטדקו ומה תדברו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_12","072_12_12","LUK","12","12","12","כי רוח הקדש הוא יורה אתכם בשעה ההיא את הנכון לדבר׃ ");
INSERT INTO heb_vpl VALUES ("LK12_13","072_12_13","LUK","12","13","13","ויאמר אליו אחד מן העם רבי אמר נא אל אחי ויחלק אתי את הירשה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_14","072_12_14","LUK","12","14","14","ויאמר אליו בן אדם מי שמני עליכם לשפט ולמחלק׃ ");
INSERT INTO heb_vpl VALUES ("LK12_15","072_12_15","LUK","12","15","15","ויאמר אליהם ראו והשמרו לכם מבצע בצע כי חיי האדם אינם תלוים בהרבות נכסיו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_16","072_12_16","LUK","12","16","16","וישא משלו ויאמר אליהם לאמר שדה איש עשיר אחד עשה תבואה הרבה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_17","072_12_17","LUK","12","17","17","ויחשב בלבו לאמר מה אעשה כי אין לי מקום לכנוס בו את תבואתי׃ ");
INSERT INTO heb_vpl VALUES ("LK12_18","072_12_18","LUK","12","18","18","ויאמר את זאת אעשה הרס את אסמי ובנה גדולים מהם ואכנסה שמה את כל יבולי וטובי׃ ");
INSERT INTO heb_vpl VALUES ("LK12_19","072_12_19","LUK","12","19","19","ואמר לנפשי נפשי יש לך עתודות הרבה לשנים רבות הנפשי אכלי שתי ושישי׃ ");
INSERT INTO heb_vpl VALUES ("LK12_20","072_12_20","LUK","12","20","20","והאלהים אמר לו אתה הכסיל בעצם הלילה הזה ידרשו ממך את נפשך ואשר הכינות לך למי יהיה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_21","072_12_21","LUK","12","21","21","זה חלק האצר לו אצרות ולא יעשיר באלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK12_22","072_12_22","LUK","12","22","22","ויאמר אל תלמידיו לכן אני אמר לכם אל תדאגו לנפשכם מה תאכלו ולגופכם מה תלבשו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_23","072_12_23","LUK","12","23","23","הנפש יקרה היא מן המזון והגוף יקר מן המלבוש׃ ");
INSERT INTO heb_vpl VALUES ("LK12_24","072_12_24","LUK","12","24","24","התבוננו אל הערבים אשר אינם זרעים ואינם קצרים וגם אין להם מגורה ואוצר והאלהים מכלכל אותם ומה מעלים אתם מן העוף׃ ");
INSERT INTO heb_vpl VALUES ("LK12_25","072_12_25","LUK","12","25","25","ומי זה מכם אשר בדאגתו יוכל להוסיף אמה אחת על קומתו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_26","072_12_26","LUK","12","26","26","ועתה הן מעט מזער אין ביכלתכם וליותר מה תדאגו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_27","072_12_27","LUK","12","27","27","התבוננו אל השושנים הצמחות ואינן טות ואינן ארגות ואני אמר לכם כי גם שלמה בכל הדרו לא היה לבוש כאחת מהנה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_28","072_12_28","LUK","12","28","28","ואם ככה ילביש אלהים את חציר השדה אשר היום ישנו ומחר ישלך לתוך התנור אף כי אתכם קטני האמונה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_29","072_12_29","LUK","12","29","29","גם אתם אל תדרשו מה תאכלו ומה תשתו ואל תהלכו בגדלות׃ ");
INSERT INTO heb_vpl VALUES ("LK12_30","072_12_30","LUK","12","30","30","כי את כל אלה מבקשים גויי הארץ ואביכם הוא יודע כי צריכים אתם לאלה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_31","072_12_31","LUK","12","31","31","אך בקשו את מלכות האלהים ונוסף לכם כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_32","072_12_32","LUK","12","32","32","אל תירא העדר הקטן כי רצה אביכם לתת לכם את המלכות׃ ");
INSERT INTO heb_vpl VALUES ("LK12_33","072_12_33","LUK","12","33","33","מכרו את רכושכם ותנו צדקה עשו לכם כיסים אשר לא יבלו ואוצר בשמים אשר לא יגרע לעולם אשר גנב לא יקרב אליו וסס לא יאכלהו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_34","072_12_34","LUK","12","34","34","כי במקום אשר אוצרכם בו שם יהיה גם לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("LK12_35","072_12_35","LUK","12","35","35","מתניכם יהיו חגורים והנרות דלקים׃ ");
INSERT INTO heb_vpl VALUES ("LK12_36","072_12_36","LUK","12","36","36","ואתם היו דמים לאנשים המחכים לאדניהם מתי ישוב מן החתנה וכאשר יבוא ודפק יפתחו לו כרגע׃ ");
INSERT INTO heb_vpl VALUES ("LK12_37","072_12_37","LUK","12","37","37","אשרי העבדים ההם אשר בבוא האדון ימצאם שקדים אמן אמר אני לכם כי יתאזר ויושיבם וילך לשרת אותם׃ ");
INSERT INTO heb_vpl VALUES ("LK12_38","072_12_38","LUK","12","38","38","ואם יבוא באשמרה השנית או באשמרה השלישית וכן ימצא אשרי העבדים ההם׃ ");
INSERT INTO heb_vpl VALUES ("LK12_39","072_12_39","LUK","12","39","39","וזאת דעו אשר אם ידע ידע בעל הבית באי זו שעה יבוא הגנב כי עתה שקד שקוד ולא יתן לחתר את ביתו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_40","072_12_40","LUK","12","40","40","לכן גם אתם היו נכונים כי בשעה אשר לא פללתם יבוא בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("LK12_41","072_12_41","LUK","12","41","41","ויאמר פטרוס אדנינו הלנו אתה אמר את המשל הזה אם גם לכל אדם׃ ");
INSERT INTO heb_vpl VALUES ("LK12_42","072_12_42","LUK","12","42","42","ויאמר האדון מי הוא אפוא הסכן הנאמן והנבון אשר יפקידהו האדון על עבדתו לתת את ארחתם בעתו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_43","072_12_43","LUK","12","43","43","אשרי העבד ההוא אשר בבא אדניו ימצאהו עשה כן׃ ");
INSERT INTO heb_vpl VALUES ("LK12_44","072_12_44","LUK","12","44","44","אמת אמר אני לכם כי על כל אשר יש לו יפקידהו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_45","072_12_45","LUK","12","45","45","והעבד ההוא אם יאמר בלבו בשש אדני לבוא והחל להכות את העבדים ואת השפחות ולאכל ולשתות ולשכר׃ ");
INSERT INTO heb_vpl VALUES ("LK12_46","072_12_46","LUK","12","46","46","בוא יבוא אדני העבד ההוא ביום לא יצפה ובשעה לא ידע וישסף אותו וישים את חלקו עם הסוררים׃ ");
INSERT INTO heb_vpl VALUES ("LK12_47","072_12_47","LUK","12","47","47","84-74 והעבד ההוא אשר ידע את רצון אדניו ולא הכין ולא עשה כרצונו יכה מכות רבות, ואשר לא ידע ועשה דברים אשר עליהם בן הכות הוא לא יכה כי אם מעט כי כל איש אשר נתן לו הרבה דרוש ידרש ממנו הרבה ואשר הפקידו בידו הרבה ישאלו מאתו יותר׃ ");
INSERT INTO heb_vpl VALUES ("LK12_48","072_12_48","LUK","12","48","48","84-74׃ ");
INSERT INTO heb_vpl VALUES ("LK12_49","072_12_49","LUK","12","49","49","להפיל אש על הארץ באתי ומה חפץ אני כי כבר בערה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_50","072_12_50","LUK","12","50","50","ועלי טבילה להטבל ומה יצר לי עד כי תשלם׃ ");
INSERT INTO heb_vpl VALUES ("LK12_51","072_12_51","LUK","12","51","51","החשבים אתם כי באתי לתת שלום בארץ אני אמר לכם לא כי אם מחלקת׃ ");
INSERT INTO heb_vpl VALUES ("LK12_52","072_12_52","LUK","12","52","52","כי מעתה חמשה בבית אחד יחלקו שלשה על שנים ושנים על שלשה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_53","072_12_53","LUK","12","53","53","האב יחלק על הבן והבן על האב האם על הבת והבת על האם החמות על הכלה והכלה על החמות׃ ");
INSERT INTO heb_vpl VALUES ("LK12_54","072_12_54","LUK","12","54","54","ויאמר גם אל המון העם כראתכם את הענן עלה במערב ואמרתם גשם בא וכן יהיה׃ ");
INSERT INTO heb_vpl VALUES ("LK12_55","072_12_55","LUK","12","55","55","ואם נשבה רוח הנגב תאמרו הנה חם בא וגם יבוא׃ ");
INSERT INTO heb_vpl VALUES ("LK12_56","072_12_56","LUK","12","56","56","החנפים את פני הארץ והשמים ידעתם לבחן ואת העת הזאת איך לא תבחנו׃ ");
INSERT INTO heb_vpl VALUES ("LK12_57","072_12_57","LUK","12","57","57","למה אף מנפשכם לא תשפטו את הישר׃ ");
INSERT INTO heb_vpl VALUES ("LK12_58","072_12_58","LUK","12","58","58","כי כאשר תלך אל השר עם איש ריבך בעודך בדרך השתדל להנצל ממנו פן יסחב אותך אל השפט והשפט ימסרך אל השוטר והשוטר ישליכך אל בית הכלא׃ ");
INSERT INTO heb_vpl VALUES ("LK12_59","072_12_59","LUK","12","59","59","ואני אמר לך לא תצא משם עד אם שלמת גם את הפרוטה האחרונה׃ ");
INSERT INTO heb_vpl VALUES ("LK13_1","072_13_1","LUK","13","1","1","ויבאו אנשים בעת ההיא ויגידו לו על דבר הגלילים אשר פילטוס ערב דמם עם זבחיהם׃ ");
INSERT INTO heb_vpl VALUES ("LK13_2","072_13_2","LUK","13","2","2","ויען ישוע ויאמר אליהם החשבים אתם כי הגלילים האלה היו חטאים מכל אנשי הגליל על אשר באה כזאת עליהם׃ ");
INSERT INTO heb_vpl VALUES ("LK13_3","072_13_3","LUK","13","3","3","לא כי אמר אני לכם אם לא תשובו תאבדו כלכם גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("LK13_4","072_13_4","LUK","13","4","4","או שמנה העשר ההם אשר נפל עליהם המגדל בשלח וימיתם החשבים אתם כי היו אשמים מכל האנשים הישבים בירושלים׃ ");
INSERT INTO heb_vpl VALUES ("LK13_5","072_13_5","LUK","13","5","5","לא כי אמר אני לכם אם לא תשובו תאבדו כלכם גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("LK13_6","072_13_6","LUK","13","6","6","וישא משלו ויאמר איש אחד היתה לו תאנה נטועה בכרמו ויבא לבקש בה פרי ולא מצא׃ ");
INSERT INTO heb_vpl VALUES ("LK13_7","072_13_7","LUK","13","7","7","ויאמר אל הכרם הנה זה שלש שנים אנכי בא לבקש פרי בתאנה הזאת ואינני מוצא גדע אותה למה זה תשחית את האדמה׃ ");
INSERT INTO heb_vpl VALUES ("LK13_8","072_13_8","LUK","13","8","8","ויען ויאמר אליו אדני הניחה אתה עוד השנה הזאת עד כי אעדר ושמתי דמן סביבותיה׃ ");
INSERT INTO heb_vpl VALUES ("LK13_9","072_13_9","LUK","13","9","9","אולי תעשה פרי ואם לא בשנה הבאה תגדענה׃ ");
INSERT INTO heb_vpl VALUES ("LK13_10","072_13_10","LUK","13","10","10","ויהי הוא מלמד בשבת באחד מבתי הכנסיות׃ ");
INSERT INTO heb_vpl VALUES ("LK13_11","072_13_11","LUK","13","11","11","והנה אשה טעונת רוח חלי כשמנה עשרה שנה ותהי כפופה ולא יכלה לקום קומה זקופה׃ ");
INSERT INTO heb_vpl VALUES ("LK13_12","072_13_12","LUK","13","12","12","ויהי בראות אתה ישוע ויקרא אליה ויאמר לה אשה החלצי מחליך׃ ");
INSERT INTO heb_vpl VALUES ("LK13_13","072_13_13","LUK","13","13","13","וישם את ידיו עליה וכרגע קמה ותתעודד ותשבח את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK13_14","072_13_14","LUK","13","14","14","ויכעס ראש הכנסת על אשר רפא ישוע בשבת ויען ויאמר אל העם ששת ימים הם אשר תעשה בהם מלאכה לכן באלה באו והרפאו ולא ביום השבת׃ ");
INSERT INTO heb_vpl VALUES ("LK13_15","072_13_15","LUK","13","15","15","ויען האדון ויאמר אליו החנף איש איש מכם הלא יתיר בשבת את שורו או את חמרו מן האבוס ויוליכהו להשקתו׃ ");
INSERT INTO heb_vpl VALUES ("LK13_16","072_13_16","LUK","13","16","16","וזאת אשר היא בת אברהם ואשר השטן אסרה זה שמנה עשרה שנה הלא תתר ממוסרותיה ביום השבת׃ ");
INSERT INTO heb_vpl VALUES ("LK13_17","072_13_17","LUK","13","17","17","ויהי כאמרו את הדברים האלה נכלמו כל מתקוממיו וישמח כל העם על כל הנפלאות הנעשות על ידו׃ ");
INSERT INTO heb_vpl VALUES ("LK13_18","072_13_18","LUK","13","18","18","ויאמר למה דומה מלכות האלהים ואל מה אמשילנה׃ ");
INSERT INTO heb_vpl VALUES ("LK13_19","072_13_19","LUK","13","19","19","דומה היא לגרגר של חרדל אשר לקחו איש וישימהו בגנו ויצמח ויהי לעץ גדול ועוף השמים יקנן בענפיו׃ ");
INSERT INTO heb_vpl VALUES ("LK13_20","072_13_20","LUK","13","20","20","ויאמר עוד אל מה אדמה את מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK13_21","072_13_21","LUK","13","21","21","דומה היא לשאר אשר לקחתו אשה ותטמנהו בשלש סאים קמח עד כי יחמץ כלו׃ ");
INSERT INTO heb_vpl VALUES ("LK13_22","072_13_22","LUK","13","22","22","ויעבר בערים ובכפרים עבור ולמד וישם את דרכו לבוא ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("LK13_23","072_13_23","LUK","13","23","23","וישאלהו איש לאמר אדנינו המעט הם הנושעים׃ ");
INSERT INTO heb_vpl VALUES ("LK13_24","072_13_24","LUK","13","24","24","ויאמר אליהם התאמצו לבוא בפתח הצר כי אמר אני לכם רבים יבקשו לבוא ולא יוכלו׃ ");
INSERT INTO heb_vpl VALUES ("LK13_25","072_13_25","LUK","13","25","25","והיה מיום אשר יקום בעל הבית וסגר את הדלת ותחלו לעמד בחוץ ולדפק על הדלת לאמר אדנינו אדנינו פתח לנו וענה ואמר אליכם אינני יודע אתכם מאין אתם׃ ");
INSERT INTO heb_vpl VALUES ("LK13_26","072_13_26","LUK","13","26","26","אז תחלו לאמר אכלנו ושתינו לפניך וברחבותינו למדת׃ ");
INSERT INTO heb_vpl VALUES ("LK13_27","072_13_27","LUK","13","27","27","ויאמר אני אמר לכם אינני יודע אתכם מאין אתם סורו ממני כל פעלי האון׃ ");
INSERT INTO heb_vpl VALUES ("LK13_28","072_13_28","LUK","13","28","28","ושם תהיה היללה וחרק השנים כאשר תראו את אברהם ויצחק ויעקב ואת כל הנביאים במלכות האלהים ואתם מגרשים החוצה׃ ");
INSERT INTO heb_vpl VALUES ("LK13_29","072_13_29","LUK","13","29","29","ויבאו ממזרח וממערב ומצפון ומדרום ויסבו במלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK13_30","072_13_30","LUK","13","30","30","והנה יש אחרונים אשר יהיו ראשונים וראשונים אשר יהיו אחרונים׃ ");
INSERT INTO heb_vpl VALUES ("LK13_31","072_13_31","LUK","13","31","31","ביום ההוא נגשו מן הפרושים ויאמרו אליו צא ולך מזה כי הורדוס מבקש להרגך׃ ");
INSERT INTO heb_vpl VALUES ("LK13_32","072_13_32","LUK","13","32","32","ויאמר אליהם לכו ואמרו אל השועל הזה הנני מגרש שדים ופעל רפואות היום ומחר ובשלישי אבא עד קצי׃ ");
INSERT INTO heb_vpl VALUES ("LK13_33","072_13_33","LUK","13","33","33","אבל הלוך אלך היום ומחר וממחרתו כי לא יתכן אשר יאבד נביא מחוץ לירושלים׃ ");
INSERT INTO heb_vpl VALUES ("LK13_34","072_13_34","LUK","13","34","34","ירושלים ירושלים ההרגת את הנביאים והסקלת את הנשלחים אליה כמה פעמים חפצתי לקבץ את בניך כאשר תקבץ התרנגלת את אפרוחיה תחת כנפיה ואתם לא אביתם׃ ");
INSERT INTO heb_vpl VALUES ("LK13_35","072_13_35","LUK","13","35","35","הנה ביתכם יעזב לכם שמם ואני אמר לכם כי ראה לא תראוני עד בוא העת אשר תאמרו ברוך הבא בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("LK14_1","072_14_1","LUK","14","1","1","ויהי בבאו בשבת אל בית אחד מראשי הפרושים לאכל לחם והמה ארבים לו׃ ");
INSERT INTO heb_vpl VALUES ("LK14_2","072_14_2","LUK","14","2","2","והנה איש אחד לפניו אשר גופו צבה ממים׃ ");
INSERT INTO heb_vpl VALUES ("LK14_3","072_14_3","LUK","14","3","3","ויען ישוע ויאמר אל בעלי התורה ואל הפרושים לאמר המתר לרפא בשבת אם לא ויחרישו׃ ");
INSERT INTO heb_vpl VALUES ("LK14_4","072_14_4","LUK","14","4","4","ויאחז בו וירפאהו וישלחהו׃ ");
INSERT INTO heb_vpl VALUES ("LK14_5","072_14_5","LUK","14","5","5","ויען ויאמר אליהם מי מכם אשר חמרו או שורו יפול אל הבאר ולא ימהר להעלותו ביום השבת׃ ");
INSERT INTO heb_vpl VALUES ("LK14_6","072_14_6","LUK","14","6","6","ולא יכלו להשיב על זאת דבר׃ ");
INSERT INTO heb_vpl VALUES ("LK14_7","072_14_7","LUK","14","7","7","וישא משלו אל הקרואים בראותו איך בחרו להם להסב בראש ויאמר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("LK14_8","072_14_8","LUK","14","8","8","כי יקרא אתך איש אל החתנה אל תסב בראש פן יקרא שמה איש נכבד ממך׃ ");
INSERT INTO heb_vpl VALUES ("LK14_9","072_14_9","LUK","14","9","9","ובא הקרא אותך ואותו ואמר אליך פנה מקום לזה ואז תקום בכלמה לקחת את המקום האחרון׃ ");
INSERT INTO heb_vpl VALUES ("LK14_10","072_14_10","LUK","14","10","10","אבל כי תקרא לך והסב במקום האחרון למען יבא הקרא אתך ואמר אליך אהובי עלה למעלה מזה והיה לך כבוד לפני המסבים עמך׃ ");
INSERT INTO heb_vpl VALUES ("LK14_11","072_14_11","LUK","14","11","11","כי כל המרומם את עצמו ישפל והמשפיל את עצמו ירומם׃ ");
INSERT INTO heb_vpl VALUES ("LK14_12","072_14_12","LUK","14","12","12","וגם אל האיש אשר קרא אותו אמר כי תעשה סעודת צהרים או סעודת ערב אל תקרא לאהביך ולאחיך ולקרוביך ולשכניך העשירים פן יקראו לך גם המה והיה לך לשלום׃ ");
INSERT INTO heb_vpl VALUES ("LK14_13","072_14_13","LUK","14","13","13","אבל כי תעשה משתה קרא לעניים ולנשברים ולפסחים ולעורים׃ ");
INSERT INTO heb_vpl VALUES ("LK14_14","072_14_14","LUK","14","14","14","ואשריך באשר אין להם לשלם לך כי ישלם לך בתחית הצדיקים׃ ");
INSERT INTO heb_vpl VALUES ("LK14_15","072_14_15","LUK","14","15","15","וישמע זאת אחד מן המסבים ויאמר אליו אשרי האכל לחם במלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK14_16","072_14_16","LUK","14","16","16","והוא אמר אליו איש אחד עשה סעודה גדולה ויקרא לרבים׃ ");
INSERT INTO heb_vpl VALUES ("LK14_17","072_14_17","LUK","14","17","17","וישלח את עבדו לעת הסעודה לאמר אל הקרואים באו כי כבר מוכן הכל׃ ");
INSERT INTO heb_vpl VALUES ("LK14_18","072_14_18","LUK","14","18","18","ויחלו כלם פה אחד להתנצל ויאמר אליו הראשון שדה קניתי ועלי לצאת לראתו אבקש ממך נקני׃ ");
INSERT INTO heb_vpl VALUES ("LK14_19","072_14_19","LUK","14","19","19","ואחר אמר חמשת צמדי בקר קניתי ואני הלך לבחן אותם אבקש ממך נקני׃ ");
INSERT INTO heb_vpl VALUES ("LK14_20","072_14_20","LUK","14","20","20","ואחר אמר אשה לקחתי ובעבור זאת לא אוכל לבוא׃ ");
INSERT INTO heb_vpl VALUES ("LK14_21","072_14_21","LUK","14","21","21","ויבא העבד ויגד את הדברים האלה לאדניו ויקצף בעל הבית ויאמר לעבדו מהר צא אל רחבות העיר ואל הוצותיה והבא הנה את העניים ואת הנשברים ואת העורים ואת הפסחים׃ ");
INSERT INTO heb_vpl VALUES ("LK14_22","072_14_22","LUK","14","22","22","ויאמר העבד אדני כאשר צוית כן נעשה ויש עוד מקום׃ ");
INSERT INTO heb_vpl VALUES ("LK14_23","072_14_23","LUK","14","23","23","ויאמר האדון אל העבד צא אל הדרכים ואל הגדרות ופצר בהם לבוא למען ימלא ביתי׃ ");
INSERT INTO heb_vpl VALUES ("LK14_24","072_14_24","LUK","14","24","24","כי אני אמר לכם אין אחד מן האנשים הקרואים ההם אשר יטעם סעודתי׃ ");
INSERT INTO heb_vpl VALUES ("LK14_25","072_14_25","LUK","14","25","25","והמון עם רב הלכים אתו ויפן ויאמר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("LK14_26","072_14_26","LUK","14","26","26","איש כי יבוא אלי ולא ישנא את אביו ואת אמו ואת אשתו ואת בניו ואת אחיו ואת אחיתיו ואף גם את נפשו לא יוכל להיות תלמידי׃ ");
INSERT INTO heb_vpl VALUES ("LK14_27","072_14_27","LUK","14","27","27","ואשר לא ישא את צלבו ובא אחרי לא יוכל להיות תלמידי׃ ");
INSERT INTO heb_vpl VALUES ("LK14_28","072_14_28","LUK","14","28","28","כי מי מכם החפץ לבנות מגדל הלא ישב בראשונה ויחשב את ההוצאות אם השג תשיג ידו להשלימו׃ ");
INSERT INTO heb_vpl VALUES ("LK14_29","072_14_29","LUK","14","29","29","פן ישים את היסוד ולא יוכל לכלותו והיה כל הראים יקומו להלעיג לו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("LK14_30","072_14_30","LUK","14","30","30","כי זה האיש החל לבנות ולא יכל לכלות׃ ");
INSERT INTO heb_vpl VALUES ("LK14_31","072_14_31","LUK","14","31","31","אז מי הוא המלך הקם להתגרות מלחמה במלך אחר ולא ישב בראשונה ויתיעץ אם יוכל בעשרת אלפים לערך לקראת הבא עליו בעשרים אלף׃ ");
INSERT INTO heb_vpl VALUES ("LK14_32","072_14_32","LUK","14","32","32","ואם לא ושלח אליו מלאכים בעודנו רחוק לבקש שלום׃ ");
INSERT INTO heb_vpl VALUES ("LK14_33","072_14_33","LUK","14","33","33","ככה כל איש מכם אשר לא נפטר מכל רכושו לא יוכל להיות תלמידי׃ ");
INSERT INTO heb_vpl VALUES ("LK14_34","072_14_34","LUK","14","34","34","טוב המלח ואם המלח היה תפל במה יתקן׃ ");
INSERT INTO heb_vpl VALUES ("LK14_35","072_14_35","LUK","14","35","35","לא יצלח גם לאדמה גם לדמן החוצה ישליכהו מי אשר אזנים לו לשמע ישמע׃ ");
INSERT INTO heb_vpl VALUES ("LK15_1","072_15_1","LUK","15","1","1","ויהי בקרב אליו כל המוכסים והחטאים לשמע אותו׃ ");
INSERT INTO heb_vpl VALUES ("LK15_2","072_15_2","LUK","15","2","2","וילונו הפרושים והסופרים לאמר הנה זה מקבל את החטאים ואכל אתם׃ ");
INSERT INTO heb_vpl VALUES ("LK15_3","072_15_3","LUK","15","3","3","וידבר אליהם את המשל הזה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("LK15_4","072_15_4","LUK","15","4","4","מי זה האיש מכם אשר לו מאה כבשים ואבד לו אחד מהם ולא יטוש את התשעים ותשעה במדבר והלך אחרי האבד עד כי ימצאהו׃ ");
INSERT INTO heb_vpl VALUES ("LK15_5","072_15_5","LUK","15","5","5","והיה כמצאו אתו ישימנו על כתפיו בשמחה׃ ");
INSERT INTO heb_vpl VALUES ("LK15_6","072_15_6","LUK","15","6","6","ובא אל ביתו וקרא לאהביו ולשכניו יחד לאמר שמחו אתי כי מצאתי את שיי האבד׃ ");
INSERT INTO heb_vpl VALUES ("LK15_7","072_15_7","LUK","15","7","7","אני אמר לכם כי כן תהיה שמחה בשמים על חוטא אחד השב יותר מעל תשעים ותשעה צדיקים אשר לא יצטרכו לתשובה׃ ");
INSERT INTO heb_vpl VALUES ("LK15_8","072_15_8","LUK","15","8","8","או מי האשה אשר לה עשרה דרכמונים ואבד לה דרכמון אחד ולא תדליק נר ותטאטא את הבית ותחפש היטב עד כי תמצאהו׃ ");
INSERT INTO heb_vpl VALUES ("LK15_9","072_15_9","LUK","15","9","9","והיה כמצאה אותו תקרא לרעותיה ולשכנותיה לאמר שמחנה אתי כי מצאתי את הדרכמון אשר אבד לי׃ ");
INSERT INTO heb_vpl VALUES ("LK15_10","072_15_10","LUK","15","10","10","כן אני אמר לכם תהיה שמחה לנפי מלאכי אלהים על חוטא אחד אשר שב מחטאו׃ ");
INSERT INTO heb_vpl VALUES ("LK15_11","072_15_11","LUK","15","11","11","ויאמר איש אחד היו לו שני בנים׃ ");
INSERT INTO heb_vpl VALUES ("LK15_12","072_15_12","LUK","15","12","12","ויאמר הצעיר אל אביו אבי תנה לי את חלק הרכוש אשר יפל לי ויחלק להם את הנחלה׃ ");
INSERT INTO heb_vpl VALUES ("LK15_13","072_15_13","LUK","15","13","13","ויהי מקץ ימים ויאסף הבן הצעיר את הכל וילך אל ארץ רחוקה ושם פזר את רכשו וילך בדרך סובאים וזוללים׃ ");
INSERT INTO heb_vpl VALUES ("LK15_14","072_15_14","LUK","15","14","14","ואחרי כלותו את הכל היה רעב חזק בארץ ההיא ויחל להיות חסר לחם׃ ");
INSERT INTO heb_vpl VALUES ("LK15_15","072_15_15","LUK","15","15","15","וילך וידבק באחד מבני המדינה בארץ ההיא וישלח אותו אל שדותיו לרעות חזירים׃ ");
INSERT INTO heb_vpl VALUES ("LK15_16","072_15_16","LUK","15","16","16","ויתאו למלא את בטנו בחרובים אשר יאכלו החזירים ואין נתן לו׃ ");
INSERT INTO heb_vpl VALUES ("LK15_17","072_15_17","LUK","15","17","17","וישב אל לבו ויאמר מה רבו שכירי אבי ויש להם לחם לשבע ואני אבד ברעב׃ ");
INSERT INTO heb_vpl VALUES ("LK15_18","072_15_18","LUK","15","18","18","אקומה נא ואלכה אל אבי ואמר אליו אבי חטאתי לשמים ולפניך׃ ");
INSERT INTO heb_vpl VALUES ("LK15_19","072_15_19","LUK","15","19","19","ונקלתי מהקרא עוד בנך שימני כאשר שכיריך׃ ");
INSERT INTO heb_vpl VALUES ("LK15_20","072_15_20","LUK","15","20","20","ויקם ויבא אל אביו עודנו מרחוק ואביו ראהו ויהמו מעיו וירץ ויפל על צואריו וישקהו׃ ");
INSERT INTO heb_vpl VALUES ("LK15_21","072_15_21","LUK","15","21","21","ויאמר אליו הבן אבי חטאתי לשמים ולפניך ואני נקלתי מהקרא עוד בנך׃ ");
INSERT INTO heb_vpl VALUES ("LK15_22","072_15_22","LUK","15","22","22","ויאמר האב אל עבדיו הוציאו את השמלה הטובה מכלן והלבישהו ותנו טבעת על ידו ונעלים ברגליו׃ ");
INSERT INTO heb_vpl VALUES ("LK15_23","072_15_23","LUK","15","23","23","והביאו את עגל המרבק וטבחו אתו ונאכלה ונשמח׃ ");
INSERT INTO heb_vpl VALUES ("LK15_24","072_15_24","LUK","15","24","24","כי זה בני היה מת ויחי ואובד היה וימצא ויחלו לשמח׃ ");
INSERT INTO heb_vpl VALUES ("LK15_25","072_15_25","LUK","15","25","25","ובנו הגדול היה בשדה ויהי כאשר בא ויקרב אל הבית וישמע קול זמרה ומחלות׃ ");
INSERT INTO heb_vpl VALUES ("LK15_26","072_15_26","LUK","15","26","26","ויקרא אל אחד הנערים וישאל מה זאת׃ ");
INSERT INTO heb_vpl VALUES ("LK15_27","072_15_27","LUK","15","27","27","ויאמר אליו כי בא אחיך ויטבח אביך את עגל המרבק על אשר הושב לו שלם׃ ");
INSERT INTO heb_vpl VALUES ("LK15_28","072_15_28","LUK","15","28","28","ויחר לו ולא אבה לבוא הביתה ויצא אביו וידבר על לבו׃ ");
INSERT INTO heb_vpl VALUES ("LK15_29","072_15_29","LUK","15","29","29","ויען ויאמר אל אביו הנה זה שנים רבות אני עבד אתך ומימי לא עברתי את מצותך ומימי לא נתת לי גדי למען אשיש עם רעי׃ ");
INSERT INTO heb_vpl VALUES ("LK15_30","072_15_30","LUK","15","30","30","ויבא בנך זה אשר בלע את נחלתך עם הזנות ותזבח לו את עגל המרבק׃ ");
INSERT INTO heb_vpl VALUES ("LK15_31","072_15_31","LUK","15","31","31","ויאמר אליו בני אתה תמיד עמדי וכל אשר לי לך הוא׃ ");
INSERT INTO heb_vpl VALUES ("LK15_32","072_15_32","LUK","15","32","32","אבל נכון לשוש ולשמח כי אחיך זה היה מת ויחי ואבד היה וימצא׃ ");
INSERT INTO heb_vpl VALUES ("LK16_1","072_16_1","LUK","16","1","1","ויאמר גם אל תלמידיו איש עשיר היה ולו פקיד על ביתו וילשינהו אליו באמרם כי מפזר הוא את קניניך׃ ");
INSERT INTO heb_vpl VALUES ("LK16_2","072_16_2","LUK","16","2","2","ויקרא אתו ויאמר אליו מה זאת שמעתי עליך תן חשבון פקדתך כי לא תוכל להיות עוד פקיד׃ ");
INSERT INTO heb_vpl VALUES ("LK16_3","072_16_3","LUK","16","3","3","ויאמר הפקיד בלבו מה אעשה כי יקח אדני ממני את הפקדה לעדר לא אוכל ולשאל על הפתחים אני בוש׃ ");
INSERT INTO heb_vpl VALUES ("LK16_4","072_16_4","LUK","16","4","4","ידעתי מה אעשה למען יאספוני אל בתיהם בעת אוסר מפקדתי׃ ");
INSERT INTO heb_vpl VALUES ("LK16_5","072_16_5","LUK","16","5","5","ויקרא אל כל איש אשר נשה בהם אדניו וישאל את הראשון כמה אתה חיב לאדני׃ ");
INSERT INTO heb_vpl VALUES ("LK16_6","072_16_6","LUK","16","6","6","ויאמר מאת בתי שמן ויאמר אליו קח את שטרך ומהר שב וכתבת חמשים׃ ");
INSERT INTO heb_vpl VALUES ("LK16_7","072_16_7","LUK","16","7","7","ואל אחר אמר כמה אתה חיב ויאמר מאת כר חטים ויאמר קח את שטרך וכתב שמנים׃ ");
INSERT INTO heb_vpl VALUES ("LK16_8","072_16_8","LUK","16","8","8","וישבח האדון את פקיד העולה על אשר הערים לעשות כי בני העולם הזה ערומים הם בדורם מבני האור׃ ");
INSERT INTO heb_vpl VALUES ("LK16_9","072_16_9","LUK","16","9","9","וגם אני אמר לכם עשו לכם אהבים בממון העולה למען בעת כלתו יאספו אתכם אל משכנות עולם׃ ");
INSERT INTO heb_vpl VALUES ("LK16_10","072_16_10","LUK","16","10","10","הנאמן במעט מזער נאמן גם בהרבה והמעול במעט מזער מעול גם בהרבה׃ ");
INSERT INTO heb_vpl VALUES ("LK16_11","072_16_11","LUK","16","11","11","לכן אם בממון העולה לא הייתם נאמנים את האמתי מי יפקיד בידכם׃ ");
INSERT INTO heb_vpl VALUES ("LK16_12","072_16_12","LUK","16","12","12","ואם בדבר אשר לאחרים לא הייתם נאמנים את אשר לכם מי יתן לכם׃ ");
INSERT INTO heb_vpl VALUES ("LK16_13","072_16_13","LUK","16","13","13","אין עבד אשר יוכל לעבד שני אדנים כי ישנא את האחד ויאהב את האחר או ידבק באחד ואת האחר יבזה לא תוכלו עבד את האלהים ואת הממון׃ ");
INSERT INTO heb_vpl VALUES ("LK16_14","072_16_14","LUK","16","14","14","וישמעו כל זאת גם הפרושים אשר הם אהבי כסף וילעגו לו׃ ");
INSERT INTO heb_vpl VALUES ("LK16_15","072_16_15","LUK","16","15","15","ויאמר אליהם אתם הם המצטדקים לפני האדם ואלהים יודע את לבבכם כי הגבה באדם תועבה הוא לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK16_16","072_16_16","LUK","16","16","16","התורה והנביאים עד יוחנן ומן אז והלאה בשורת מלכות האלהים וכל איש בחזקה יבוא בה׃ ");
INSERT INTO heb_vpl VALUES ("LK16_17","072_16_17","LUK","16","17","17","אבל נקל כי יעברו השמים והארץ מאשר יפל קוץ אחד מן התורה׃ ");
INSERT INTO heb_vpl VALUES ("LK16_18","072_16_18","LUK","16","18","18","כל איש המשלח את אשתו ולקח אחרת נאף הוא וכל הלקח את הגרושה מאישה נאף הוא׃ ");
INSERT INTO heb_vpl VALUES ("LK16_19","072_16_19","LUK","16","19","19","איש עשיר היה והוא לבוש ארגמן ושש ויתעגג וישמח יום יום׃ ");
INSERT INTO heb_vpl VALUES ("LK16_20","072_16_20","LUK","16","20","20","ואיש אביון ושמו לעזר משכב פתח שער ביתו והוא מלא אבעבעות׃ ");
INSERT INTO heb_vpl VALUES ("LK16_21","072_16_21","LUK","16","21","21","ויתאו לשבע מן הפרורים הנפלים מעל שלחן העשיר וגם הכלבים באו וילקו אבעבעותיו׃ ");
INSERT INTO heb_vpl VALUES ("LK16_22","072_16_22","LUK","16","22","22","ויהי כאשר מת האביון ויובל על ידי המלאכים אל חיק אברהם וימת גם העשיר ויקבר׃ ");
INSERT INTO heb_vpl VALUES ("LK16_23","072_16_23","LUK","16","23","23","ובהיותו במכאבות בשאול וישא את עיניו וירא את אברהם מרחוק ואת לעזר בחיקו׃ ");
INSERT INTO heb_vpl VALUES ("LK16_24","072_16_24","LUK","16","24","24","ויצעק ויאמר אבי אברהם חנני ושלח נא את לעזר ויטבל את קצה אצבעו במים למען קרר את לשוני כי עניתי במוקד הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK16_25","072_16_25","LUK","16","25","25","ויאמר אברהם בני זכר כי לקחת טובך בחייך וגם לעזר לקח את הרעות ועתה הוא ינחם ואתה תצטער׃ ");
INSERT INTO heb_vpl VALUES ("LK16_26","072_16_26","LUK","16","26","26","ומלבד כל זאת שוחה גדולה מפסקת בינינו וביניכם לבלתי יוכלו עבור החפצים ללכת מפה אליכם ולבלתי יעברו משם אלינו׃ ");
INSERT INTO heb_vpl VALUES ("LK16_27","072_16_27","LUK","16","27","27","ויאמר אם כן אבי שאל אני מאתך כי תשלח אתו אל בית אבי׃ ");
INSERT INTO heb_vpl VALUES ("LK16_28","072_16_28","LUK","16","28","28","כי יש לי חמשה אחים למען יעיד בהם פן יבאו גם הם אל מקום המעצבה הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK16_29","072_16_29","LUK","16","29","29","ויאמר אברהם יש להם משה והנביאים אליהם ישמעון׃ ");
INSERT INTO heb_vpl VALUES ("LK16_30","072_16_30","LUK","16","30","30","ויאמר לא כן אבי אברהם אך אם ילך אליהם אחד מן המתים אז ישובו׃ ");
INSERT INTO heb_vpl VALUES ("LK16_31","072_16_31","LUK","16","31","31","ויאמר אליו אם לא ישמעו אל משה ואל הנביאים גם כי יקום אחד מן המתים לא יאמינו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_1","072_17_1","LUK","17","1","1","ויאמר אל תלמידיו אי אפשר שלא יבאו המכשלים אבל אוי לאיש אשר על ידו יבאו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_2","072_17_2","LUK","17","2","2","נוח לו שיתלה פלח רכב על צוארו וישלך אל הים מאשר יכשיל את אחד מהקטנים wאלה׃ ");
INSERT INTO heb_vpl VALUES ("LK17_3","072_17_3","LUK","17","3","3","השמרו לנפשותיכם אם יחטא לך אחיך הוכח לו ואם ינחם סלח לו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_4","072_17_4","LUK","17","4","4","ואם יחטא לך שבע פעמים ביום ושב אליך שבע פעמים ביום ואמר נחמתי וסלחת לו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_5","072_17_5","LUK","17","5","5","ויאמרו השליחים אל האדון הוסף לנו אמונה׃ ");
INSERT INTO heb_vpl VALUES ("LK17_6","072_17_6","LUK","17","6","6","ויאמר האדון לו היתה לכם אמונה כגרגר החרדל אז תאמרו אל התות הזה העקר והנטע בתוך הים וישמע לכם׃ ");
INSERT INTO heb_vpl VALUES ("LK17_7","072_17_7","LUK","17","7","7","מי הוא זה מכם ולו עבד חרש או רעה אשר בבאו מן השדה יאמר אליו מהר גשה הנה והסב׃ ");
INSERT INTO heb_vpl VALUES ("LK17_8","072_17_8","LUK","17","8","8","הלא יאמר אליו הכן לי ארוחת הערב וחגר מתניך ושרתני עד אם כליתי לאכל ולשתות ואחר תאכל ותשתה גם אתה׃ ");
INSERT INTO heb_vpl VALUES ("LK17_9","072_17_9","LUK","17","9","9","הגם יתן תודה לעבד על עשתו את אשר צוהו אמרתי לא יתן׃ ");
INSERT INTO heb_vpl VALUES ("LK17_10","072_17_10","LUK","17","10","10","ככה גם אתם אחרי עשותכם את כל אשר צויתם אמרו עבדים אין מועיל בם אנחנו כי רק את המטל עלינו לעשות עשינו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_11","072_17_11","LUK","17","11","11","ויהי בנסעו ירושלים והוא עבר בתוך שמרון והגליל׃ ");
INSERT INTO heb_vpl VALUES ("LK17_12","072_17_12","LUK","17","12","12","ויבא אל כפר אחד ויפגעהו עשרה אנשים מצרעים והם עמדים מרחוק׃ ");
INSERT INTO heb_vpl VALUES ("LK17_13","072_17_13","LUK","17","13","13","וישאו את קולם לאמר ישוע מורה חננו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_14","072_17_14","LUK","17","14","14","וירא אותם ויאמר אליהם לכו והראו אל הכהנים ויהי בלכתם ויטהרו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_15","072_17_15","LUK","17","15","15","ואחד מהם בראתו כי נרפא וישב וישבח את האלהים בקול גדול׃ ");
INSERT INTO heb_vpl VALUES ("LK17_16","072_17_16","LUK","17","16","16","ויפל על פניו לרגליו ויודה לו והוא היה שמרוני׃ ");
INSERT INTO heb_vpl VALUES ("LK17_17","072_17_17","LUK","17","17","17","ויען ישוע ויאמר הלא העשרה טהרו והתשעה איה הם׃ ");
INSERT INTO heb_vpl VALUES ("LK17_18","072_17_18","LUK","17","18","18","האם לא נמצא אשר שב לתת כבוד לאלהים זולתי הנכרי הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK17_19","072_17_19","LUK","17","19","19","ויאמר אליו קום ולך אמונתך הושיעה לך׃ ");
INSERT INTO heb_vpl VALUES ("LK17_20","072_17_20","LUK","17","20","20","וישאלהו הפרושים מתי תבוא מלכות האלהים ויען אתם לאמר מלכות האלהים לא תבוא במראה עינים׃ ");
INSERT INTO heb_vpl VALUES ("LK17_21","072_17_21","LUK","17","21","21","ולא יאמרו הנה פה או הנה שם כי מלכות האלהים הנה בקרבכם היא׃ ");
INSERT INTO heb_vpl VALUES ("LK17_22","072_17_22","LUK","17","22","22","ויאמר אל התלמידים ימים באים והתאויתם לראות יום אחד מימי בן האדם ולא תראו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_23","072_17_23","LUK","17","23","23","ואם יאמרו אליכם הנה שם הנה פה אל תלכו ואל תרוצו אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("LK17_24","072_17_24","LUK","17","24","24","כי כברק אשר יברק מקצה השמים ויאיר עד קצה השמים כן יהיה בן האדם ביומו׃ ");
INSERT INTO heb_vpl VALUES ("LK17_25","072_17_25","LUK","17","25","25","אך בראשונה צריך הוא לסבל הרבה ולהמאס מן הדור הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK17_26","072_17_26","LUK","17","26","26","וכאשר היה נח כן יהיה בימי בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("LK17_27","072_17_27","LUK","17","27","27","אכלו ושתו נשאו נשים והשיאו נשים לאנשים עד היום אשר בא נח אל התבה ויבא המבול וישחת את כלם׃ ");
INSERT INTO heb_vpl VALUES ("LK17_28","072_17_28","LUK","17","28","28","וכאשר היה בימי לוט אכל ושתה קנה ומכר נטע ובנה׃ ");
INSERT INTO heb_vpl VALUES ("LK17_29","072_17_29","LUK","17","29","29","ויהי ביום אשר יצא לוט מסדום וימטר אש וגפרית מן השמים וישחת את כלם׃ ");
INSERT INTO heb_vpl VALUES ("LK17_30","072_17_30","LUK","17","30","30","ככה יהיה ביום אשר יגלה בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("LK17_31","072_17_31","LUK","17","31","31","ביום ההוא איש אשר יהיה על הגג וכליו בבית אל ירד לשאת אתם ואיש אשר בשדה אל ישב הביתה׃ ");
INSERT INTO heb_vpl VALUES ("LK17_32","072_17_32","LUK","17","32","32","זכרו את אשת לוט׃ ");
INSERT INTO heb_vpl VALUES ("LK17_33","072_17_33","LUK","17","33","33","המבקש למלט את נפשו יאבדנה ואשר יאבד אתה יהיה׃ ");
INSERT INTO heb_vpl VALUES ("LK17_34","072_17_34","LUK","17","34","34","אני אמר לכם בלילה ההוא שנים יהיו במטה אחת האחד יאסף והאחר יעזב׃ ");
INSERT INTO heb_vpl VALUES ("LK17_35","072_17_35","LUK","17","35","35","שתים תהיינה טחנות יחד האחת תאסף והאחרת תעזב׃ ");
INSERT INTO heb_vpl VALUES ("LK17_36","072_17_36","LUK","17","36","36","שנים יהיו בשדה ונאסף האחד והאחר יעזב׃ ");
INSERT INTO heb_vpl VALUES ("LK17_37","072_17_37","LUK","17","37","37","ויענו ויאמרו אליו איה זאת אדנינו ויאמר אליהם באשר הפגר שם יקבצו הנשרים׃ ");
INSERT INTO heb_vpl VALUES ("LK18_1","072_18_1","LUK","18","1","1","וגם משל דבר אליהם להתפלל תמיד ולא להתרפות׃ ");
INSERT INTO heb_vpl VALUES ("LK18_2","072_18_2","LUK","18","2","2","ויאמר שופט היה בעיר אחת אשר לא ירא את האלהים ולא נשא פנים לאדם׃ ");
INSERT INTO heb_vpl VALUES ("LK18_3","072_18_3","LUK","18","3","3","ואלמנה היתה בעיר ההיא ותבא אליו לאמר דינה את דיני ממריבי׃ ");
INSERT INTO heb_vpl VALUES ("LK18_4","072_18_4","LUK","18","4","4","וימאן מיום אל יום ואחרי כן אמר בנפשו גם כי את האלהים אינני ירא ולאדם לא אשא פנים׃ ");
INSERT INTO heb_vpl VALUES ("LK18_5","072_18_5","LUK","18","5","5","אעשה את דין האלמנה הזאת על הוגיעה אתי פן תבוא תמיד ותדכאני במלים׃ ");
INSERT INTO heb_vpl VALUES ("LK18_6","072_18_6","LUK","18","6","6","ויאמר האדון שמעו את אשר אמר דין העולה׃ ");
INSERT INTO heb_vpl VALUES ("LK18_7","072_18_7","LUK","18","7","7","והאלהים הלא הוא יעשה דין בחיריו הקראים אליו יומם ולילה גם כי יתמהמה להושיעם׃ ");
