INSERT INTO heb_vpl VALUES ("LK20_10","072_20_10","LUK","20","10","10","ולמועד שלח עבד אל הכרמים לתת לו מפרי הכרם והכרמים הכהו וישלחהו ריקם׃ ");
INSERT INTO heb_vpl VALUES ("LK20_11","072_20_11","LUK","20","11","11","ויסף שלח עבד אחר ויכו גם אתו ויחרפהו וישלחהו ריקם׃ ");
INSERT INTO heb_vpl VALUES ("LK20_12","072_20_12","LUK","20","12","12","ויסף לשלח שלישי וגם אתו פצעו ויגרשהו וידחפהו חוצה׃ ");
INSERT INTO heb_vpl VALUES ("LK20_13","072_20_13","LUK","20","13","13","ויאמר בעל הכרם מה אעשה אשלחה את בני את ידידי כראותם אותו אולי יגורו מפניו׃ ");
INSERT INTO heb_vpl VALUES ("LK20_14","072_20_14","LUK","20","14","14","וכראות אתו הכרמים נועצו יחדו לאמר זה הוא היורש לכו ונהרגהו ותהי לנו הירשה׃ ");
INSERT INTO heb_vpl VALUES ("LK20_15","072_20_15","LUK","20","15","15","ויגרשו אותו אל מחוץ לכרם ויהרגהו ועתה מה יעשה להם בעל הכרם׃ ");
INSERT INTO heb_vpl VALUES ("LK20_16","072_20_16","LUK","20","16","16","יבוא ויאבד את הכרמים האלה ויתן את הכרם לאחרים ויהי כשמעם ויאמרו חלילה מהיות כזאת׃ ");
INSERT INTO heb_vpl VALUES ("LK20_17","072_20_17","LUK","20","17","17","ויבט בם ויאמר ומה הוא זה הכתוב אבן מאסו הבונים היתה לראש פנה׃ ");
INSERT INTO heb_vpl VALUES ("LK20_18","072_20_18","LUK","20","18","18","כל הנפל על האבן ההיא ישבר ואת אשר תפל עליו תשחקהו׃ ");
