INSERT INTO heb_vpl VALUES ("LK20_20","072_20_20","LUK","20","20","20","ויארבו לו וישלחו מארבים והם נדמו כצדיקים למען ילכדו אותו בדבר להסגירו אל השררה ואל יד ההגמון׃ ");
INSERT INTO heb_vpl VALUES ("LK20_21","072_20_21","LUK","20","21","21","וישאלהו לאמר רבי ידענו כי נכונה תדבר ותלמד ולא תשא פנים כי באמת מורה אתה את דרך אלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK20_22","072_20_22","LUK","20","22","22","המתר לנו לתת מס אל הקיסר אם לא׃ ");
INSERT INTO heb_vpl VALUES ("LK20_23","072_20_23","LUK","20","23","23","ויכר את נכליהם ויאמר להם׃ ");
INSERT INTO heb_vpl VALUES ("LK20_24","072_20_24","LUK","20","24","24","מה תנסוני הראוני דינר של מי הצורה והמכתב אשר עליו ויענו ויאמרו של הקיסר׃ ");
INSERT INTO heb_vpl VALUES ("LK20_25","072_20_25","LUK","20","25","25","ויאמר אליהם לכן תנו לקיסר את אשר לקיסר ולאלהים את אשר לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK20_26","072_20_26","LUK","20","26","26","ולא יכלו ללכדו בדבר לפני העם ויתמהו על מענהו ויחרישו׃ ");
INSERT INTO heb_vpl VALUES ("LK20_27","072_20_27","LUK","20","27","27","ויקרבו אנשים מן הצדוקים הכפרים בתחית המתים וישאלהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("LK20_28","072_20_28","LUK","20","28","28","מורה משה כתב לנו כי ימות אח בעל אשה ובנים אין לו ולקח אחיו את אשתו והקים זרע לאחיו׃ ");
INSERT INTO heb_vpl VALUES ("LK20_29","072_20_29","LUK","20","29","29","והנה היו שבעה אחים והראשון לקח אשה וימת לא בנים׃ ");
INSERT INTO heb_vpl VALUES ("LK20_30","072_20_30","LUK","20","30","30","ויקח אתה השני וימת גם הוא לא בנים׃ ");
INSERT INTO heb_vpl VALUES ("LK20_31","072_20_31","LUK","20","31","31","ויקח אתה השלישי וככה עשו אף השבעה ולא הניחו בנים וימותו׃ ");
INSERT INTO heb_vpl VALUES ("LK20_32","072_20_32","LUK","20","32","32","ובאחרונה מתה גם האשה׃ ");
INSERT INTO heb_vpl VALUES ("LK20_33","072_20_33","LUK","20","33","33","והנה בתחית המתים למי מהם תהיה לאשה כי היתה אשה לשבעה׃ ");
INSERT INTO heb_vpl VALUES ("LK20_34","072_20_34","LUK","20","34","34","ויען ישוע ויאמר אליהם בני העולם הזה ישאו נשים ותנשאנה׃ ");
INSERT INTO heb_vpl VALUES ("LK20_35","072_20_35","LUK","20","35","35","והזכים לנחל את העולם הבא ואת תחית המתים לא ישאו נשים ולא תנשאנה׃ ");
