INSERT INTO heb_vpl VALUES ("LK20_44","072_20_44","LUK","20","44","44","הנה דוד קרא לו אדון ואיך הוא בנו׃ ");
INSERT INTO heb_vpl VALUES ("LK20_45","072_20_45","LUK","20","45","45","ויאמר אל תלמידיו באזני כל העם׃ ");
INSERT INTO heb_vpl VALUES ("LK20_46","072_20_46","LUK","20","46","46","הזהרו מן הסופרים החפצים להתהלך עטופי טלית ואהבים את שאלות שלומם בשוקים ואת מושבי הראש בבתי הכנסיות ואת מסבות הראש בסעודות׃ ");
INSERT INTO heb_vpl VALUES ("LK20_47","072_20_47","LUK","20","47","47","הבלעים את בתי האלמנות ומאריכים תפלתם למראה עינים המה משפט על יתר יקחו׃ ");
