INSERT INTO heb_vpl VALUES ("LK21_3","072_21_3","LUK","21","3","3","ויאמר אמת אמר אני לכם כי האלמנה העניה הזאת נתנה יותר מכלם׃ ");
INSERT INTO heb_vpl VALUES ("LK21_4","072_21_4","LUK","21","4","4","כי כל אלה התנדבו לאלהים מהעדף שלהם והיא מחסרונה את כל רכושה נתנה׃ ");
INSERT INTO heb_vpl VALUES ("LK21_5","072_21_5","LUK","21","5","5","ויהי באמרם על המקדש כי מהדר הוא באבנים יפות ובמתנות ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("LK21_6","072_21_6","LUK","21","6","6","את אשר אתם ראים הנה ימים באים ולא תשאר אבן על אבן אשר לא תתפרק׃ ");
INSERT INTO heb_vpl VALUES ("LK21_7","072_21_7","LUK","21","7","7","וישאלהו לאמר רבי מתי אפוא תהיה זאת ומה הוא האות לעת היותה׃ ");
INSERT INTO heb_vpl VALUES ("LK21_8","072_21_8","LUK","21","8","8","ויאמר ראו פן תתעו כי רבים יבאו בשמי לאמר אני הוא והעת קרובה ואתם אל תלכו אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("LK21_9","072_21_9","LUK","21","9","9","ובשמעכם מלחמות ומהומות אל תחתו כי היו תהיה זאת לראשונה אך עוד קץ למועד׃ ");
INSERT INTO heb_vpl VALUES ("LK21_10","072_21_10","LUK","21","10","10","ויסף דבר אליהם לאמר יקום גוי על גוי וממלכה על ממלכה׃ ");
