INSERT INTO heb_vpl VALUES ("LK21_21","072_21_21","LUK","21","21","21","אז ינוסו אנשי יהודה אל ההרים ואשר הם בתוכה יצאו ואשר הם בפרזות אל יבואו בה׃ ");
INSERT INTO heb_vpl VALUES ("LK21_22","072_21_22","LUK","21","22","22","כי ימי נקם המה למלאת כל הכתוב׃ ");
