INSERT INTO heb_vpl VALUES ("LK21_25","072_21_25","LUK","21","25","25","והיו אתות בשמש ובירח ובכוכבים ועל הארץ מצוקה לגוים ומבוכה מהמית הים ודכיו׃ ");
