INSERT INTO heb_vpl VALUES ("LK21_37","072_21_37","LUK","21","37","37","ויהי מלמד יומם במקדש ובלילה יצא בהר הנקרא הר הזיתים ללון׃ ");
INSERT INTO heb_vpl VALUES ("LK21_38","072_21_38","LUK","21","38","38","וכל העם השכימו לבוא אליו במקדש לשמע אותו׃ ");
