INSERT INTO heb_vpl VALUES ("LK22_2","072_22_2","LUK","22","2","2","והכהנים הגדולים והסופרים מבקשים איך יהרגהו כי יראו מפני העם׃ ");
INSERT INTO heb_vpl VALUES ("LK22_3","072_22_3","LUK","22","3","3","והשטן נכנס ביהודה המכנה איש קריות והוא במספר שנים העשר׃ ");
