INSERT INTO heb_vpl VALUES ("LK22_11","072_22_11","LUK","22","11","11","ואמרתם אל בעל הבית כה אמר לך הרב איה המלון אשר אכלה שם את הפסח עם תלמידי׃ ");
INSERT INTO heb_vpl VALUES ("LK22_12","072_22_12","LUK","22","12","12","והוא יראה אתכם עליה גדולה מצעה שם תכינו׃ ");
