INSERT INTO heb_vpl VALUES ("LK22_14","072_22_14","LUK","22","14","14","ויהי כאשר הגיעה השעה ויסב הוא ושנים עשר השליחים אתו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_15","072_22_15","LUK","22","15","15","ויאמר אליהם נכסף נכספתי לאכל אתכם את הפסח הזה לפני ענותי׃ ");
INSERT INTO heb_vpl VALUES ("LK22_16","072_22_16","LUK","22","16","16","כי אמר אני לכם אינני אכל אותו עוד עד כי ימלא במלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK22_17","072_22_17","LUK","22","17","17","ויקח את הכוס ויברך ויאמר קחו אתה וחלקו ביניכם׃ ");
