INSERT INTO heb_vpl VALUES ("LK22_19","072_22_19","LUK","22","19","19","ויקח את הלחם ויברך ויבצע ויתן להם לאמר זה גופי הנתן בעדכם זאת עשו לזכרוני׃ ");
INSERT INTO heb_vpl VALUES ("LK22_20","072_22_20","LUK","22","20","20","וכן גם את הכוס אחר הסעודה לאמר זו הכוס היא הברית החדשה בדמי הנשפך בעדכם׃ ");
INSERT INTO heb_vpl VALUES ("LK22_21","072_22_21","LUK","22","21","21","אך הנה יד המסר אותי אתי על השלחן׃ ");
INSERT INTO heb_vpl VALUES ("LK22_22","072_22_22","LUK","22","22","22","כי הן בן האדם הלך לו כפי אשר נחרץ עליו אבל אוי לאיש ההוא אשר על ידו ימסר׃ ");
INSERT INTO heb_vpl VALUES ("LK22_23","072_22_23","LUK","22","23","23","והם החלו לחקר איש את רעהו מי הוא זה מהם אשר יעשה זאת׃ ");
INSERT INTO heb_vpl VALUES ("LK22_24","072_22_24","LUK","22","24","24","וגם מריבה היתה ביניהם מי יחשב להיות הגדול בהם׃ ");
INSERT INTO heb_vpl VALUES ("LK22_25","072_22_25","LUK","22","25","25","ויאמר אליהם מלכי הגוים רדים בהם ושליטיהם יקראו עשי חסד׃ ");
INSERT INTO heb_vpl VALUES ("LK22_26","072_22_26","LUK","22","26","26","ואתם לא כן כי הגדול בכם יהיה כצעיר והמשל יהיה כמשרת׃ ");
INSERT INTO heb_vpl VALUES ("LK22_27","072_22_27","LUK","22","27","27","כי מי הוא הגדול אם המסב או המשרת הלא המסב ואני הנני בתוככם כמו המשרת׃ ");
INSERT INTO heb_vpl VALUES ("LK22_28","072_22_28","LUK","22","28","28","ואתם הם העמדים עמדי עד עתה בנסיונתי׃ ");
INSERT INTO heb_vpl VALUES ("LK22_29","072_22_29","LUK","22","29","29","לכן אני מנחיל אתכם כאשר הנחילני אבי את המלכות׃ ");
INSERT INTO heb_vpl VALUES ("LK22_30","072_22_30","LUK","22","30","30","למען תאכלו ותשתו על שלחני במלכותי וישבתם על כסאות לשפט את שנים עשר שבטי ישראל׃ ");
INSERT INTO heb_vpl VALUES ("LK22_31","072_22_31","LUK","22","31","31","ויאמר האדון שמעון שמעון הנה תבע אתכם השטן לזרותכם כחטים׃ ");
INSERT INTO heb_vpl VALUES ("LK22_32","072_22_32","LUK","22","32","32","ואני התפללתי בעדך אשר לא תכלה אמונתך ואתה כאשר תשוב חזק את אחיך׃ ");
INSERT INTO heb_vpl VALUES ("LK22_33","072_22_33","LUK","22","33","33","והוא אמר אליו אדני הנני נכון ללכת אתך גם לבית האסורים גם למות׃ ");
INSERT INTO heb_vpl VALUES ("LK22_34","072_22_34","LUK","22","34","34","ויאמר אני אמר לך פטרוס לא יקרא תרנגל היום עד כי שלש פעמים כחשת בי לאמר לא ידעתיו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_35","072_22_35","LUK","22","35","35","ויאמר אליהם כאשר שלחתי אתכם בלי כיס ותרמיל ונעלים החסרתם דבר ויאמרו לא חסרנו כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("LK22_36","072_22_36","LUK","22","36","36","ויאמר אליהם אכן עתה אשר לו כיס ישאהו וכן גם את התרמיל ואשר אין לו הוא ימכר את בגדו ויקנה חרב׃ ");
INSERT INTO heb_vpl VALUES ("LK22_37","072_22_37","LUK","22","37","37","כי אמר אני לכם אשר צריך עוד להתמלא בי הכתוב הזה ואת פשעים נמנה כי כל הכתוב עלי בא עד קצו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_38","072_22_38","LUK","22","38","38","ויאמרו אדנינו הנה פה שתי חרבות ויאמר אליהם די׃ ");
INSERT INTO heb_vpl VALUES ("LK22_39","072_22_39","LUK","22","39","39","ויצא וילך כיום ביום על הר הזיתים וילכו אחריו גם תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_40","072_22_40","LUK","22","40","40","ויבא אל המקום ויאמר אליהם התפללו לבלתי בוא לידי נסיון׃ ");
INSERT INTO heb_vpl VALUES ("LK22_41","072_22_41","LUK","22","41","41","והוא נפרד מהם הרחק כקלע אבן ויכרע על ברכיו ויתפלל לאמר׃ ");
