INSERT INTO heb_vpl VALUES ("LK22_43","072_22_43","LUK","22","43","43","וירא אליו מלאך מן השמים ויחזקהו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_44","072_22_44","LUK","22","44","44","ויבאו עליו חבלי מות ויוסף להתפלל בחזקה ותהי זעתו כנטפי דם ירדים לארץ׃ ");
INSERT INTO heb_vpl VALUES ("LK22_45","072_22_45","LUK","22","45","45","ויקם מהתפלל ויבא אל התלמידים וימצאם ישנים מיגון׃ ");
INSERT INTO heb_vpl VALUES ("LK22_46","072_22_46","LUK","22","46","46","74-64 ויאמר אליהם למה תישנו קומו והתפללו אשר לא תבאו לידי נסיונ, עודנו מדבר והנה המון ואחד משנים העשר הנקרא יהודה הלך לפניהם ויקרב אל ישוע לנשק לו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_47","072_22_47","LUK","22","47","47","74-64׃ ");
INSERT INTO heb_vpl VALUES ("LK22_48","072_22_48","LUK","22","48","48","ויאמר ישוע אליו יהודה הבנשיקה אתה מוסר את בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("LK22_49","072_22_49","LUK","22","49","49","והאנשים אשר אתו ראים את אשר יהיה ויאמרו אליו אדנינו הנכה בחרב׃ ");
INSERT INTO heb_vpl VALUES ("LK22_50","072_22_50","LUK","22","50","50","ויך אחד מהם את עבד הכהן הגדול ויקצץ את אזנו הימנית׃ ");
INSERT INTO heb_vpl VALUES ("LK22_51","072_22_51","LUK","22","51","51","ויען ישוע ויאמר רב עתה הרפו ויגע באזנו וירפאהו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_52","072_22_52","LUK","22","52","52","ויאמר ישוע אל ראשי הכהנים ושרי המקדש והזקנים אשר באו עליו לאמר כמו על פריץ יצאתם עלי בחרבות ובמקלות׃ ");
INSERT INTO heb_vpl VALUES ("LK22_53","072_22_53","LUK","22","53","53","ואהי אצלכם יום יום בהיכל ולא שלחתם בי יד ואולם זאת היא שעתכם ושלטן החשך׃ ");
INSERT INTO heb_vpl VALUES ("LK22_54","072_22_54","LUK","22","54","54","ויתפשו אותו ויוליכהו ויביאהו בית הכהן הגדול ופטרוס הלך אחריו מרחוק׃ ");
INSERT INTO heb_vpl VALUES ("LK22_55","072_22_55","LUK","22","55","55","ויהי כי בערו אש בתוך החצר וישבו יחדו וישב גם פטרוס בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("LK22_56","072_22_56","LUK","22","56","56","ותראהו השפחה יושב נגד האור ותבט בו ותאמר גם זה היה עמו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_57","072_22_57","LUK","22","57","57","ויכחש בו ויאמר אשה לא ידעתיו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_58","072_22_58","LUK","22","58","58","ואחרי מעט ראהו אדם אחר ויאמר גם אתה מהם ויאמר פטרוס לא אדם כי אינני׃ ");
INSERT INTO heb_vpl VALUES ("LK22_59","072_22_59","LUK","22","59","59","ואחרי עבר כשעה אחת קים איש אחר לאמר אמנם גם זה היה עמו כי אף הוא גלילי׃ ");
INSERT INTO heb_vpl VALUES ("LK22_60","072_22_60","LUK","22","60","60","ויאמר פטרוס בן אדם לא ידעתי מה אתה אמר והוא עודנו מדבר והתרנגול קרא׃ ");
INSERT INTO heb_vpl VALUES ("LK22_61","072_22_61","LUK","22","61","61","ויפן האדון ויבט אל פטרוס ויזכר פטרוס את דבר האדון אשר דבר אליו כי בטרם יקרא התרנגל תכחש בי שלש פעמים׃ ");
INSERT INTO heb_vpl VALUES ("LK22_62","072_22_62","LUK","22","62","62","ויצא פטרוס החוצה וימרר בבכי׃ ");
INSERT INTO heb_vpl VALUES ("LK22_63","072_22_63","LUK","22","63","63","והאנשים אשר אחזו את ישוע התעללו בו ויכהו׃ ");
