INSERT INTO heb_vpl VALUES ("LK22_67","072_22_67","LUK","22","67","67","ויאמר אליהם כי אגיד לכם לא תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("LK22_68","072_22_68","LUK","22","68","68","וגם אם אשאל לא תשיבו דבר ולא תשלחוני׃ ");
INSERT INTO heb_vpl VALUES ("LK22_69","072_22_69","LUK","22","69","69","אבל מעתה יהיה בן האדם ישב לימין גבורת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK22_70","072_22_70","LUK","22","70","70","ויאמרו כלם הכי אתה הוא בן האלהים ויאמר אליהם אתם אמרתם כי אני הוא׃ ");
INSERT INTO heb_vpl VALUES ("LK22_71","072_22_71","LUK","22","71","71","ויאמרו מה לנו עוד לבקש עדות הלא באזנינו שמענוה מפיו׃ ");
INSERT INTO heb_vpl VALUES ("LK23_1","072_23_1","LUK","23","1","1","ויקם כל קהלם ויוליכהו אל פילטוס׃ ");
INSERT INTO heb_vpl VALUES ("LK23_2","072_23_2","LUK","23","2","2","ויחלו לדבר עליו שטנה לאמר את זה מצאנו מסית את העם ומנע אתו מתת מס אל הקיסר באמרו כי הוא מלך המשיח׃ ");
INSERT INTO heb_vpl VALUES ("LK23_3","072_23_3","LUK","23","3","3","וישאלהו פילטוס לאמר האתה הוא מלך היהודים ויען אתו ויאמר אתה אמרת׃ ");
INSERT INTO heb_vpl VALUES ("LK23_4","072_23_4","LUK","23","4","4","ויאמר פילטוס אל ראשי הכהנים ואל המון העם לא מצאתי דבר אשם באיש הזה׃ ");
INSERT INTO heb_vpl VALUES ("LK23_5","072_23_5","LUK","23","5","5","והם התאמצו לדבר מדיח הוא את העם בלמדו בכל יהודה החל מן הגליל ועד הנה׃ ");
INSERT INTO heb_vpl VALUES ("LK23_6","072_23_6","LUK","23","6","6","ויהי כשמע פילטוס את שם הגליל וישאל אם הוא איש גלילי׃ ");
INSERT INTO heb_vpl VALUES ("LK23_7","072_23_7","LUK","23","7","7","וכאשר ידע כי מממשלת הורדוס הוא שלחו אל הורדוס אשר היה גם הוא בירושלים בימים האלה׃ ");
INSERT INTO heb_vpl VALUES ("LK23_8","072_23_8","LUK","23","8","8","וישמח הורדוס עד מאד כראותו את ישוע כי מימים רבים אוה לראת אתו על כי שמע את שמעו ויקו לראת אות אשר יעשה׃ ");
INSERT INTO heb_vpl VALUES ("LK23_9","072_23_9","LUK","23","9","9","וירב לשאל אותו והוא לא השיב אתו דבר׃ ");
INSERT INTO heb_vpl VALUES ("LK23_10","072_23_10","LUK","23","10","10","ויעמדו הכהנים הגדולים והסופרים ויתחזקו לדבר עליו שטנה׃ ");
INSERT INTO heb_vpl VALUES ("LK23_11","072_23_11","LUK","23","11","11","ויבז אתו הורדוס עם צבאותיו ויהתל בו וילבש אותו בגד זהורית וישלחהו אל פילטוס׃ ");
INSERT INTO heb_vpl VALUES ("LK23_12","072_23_12","LUK","23","12","12","ביום ההוא נהיו פילטוס והורדוס לאהבים יחדו כי מלפנים איבה היתה בינתם׃ ");
