INSERT INTO heb_vpl VALUES ("LK23_15","072_23_15","LUK","23","15","15","וגם הורדוס לא מצא כי שלחתי אתכם אליו והנה אין בו חטא משפט מות׃ ");
INSERT INTO heb_vpl VALUES ("LK23_16","072_23_16","LUK","23","16","16","על כן איסרנו ואפטרנו׃ ");
INSERT INTO heb_vpl VALUES ("LK23_17","072_23_17","LUK","23","17","17","ועליו היה לפטר להם איש אחד בימי החג׃ ");
INSERT INTO heb_vpl VALUES ("LK23_18","072_23_18","LUK","23","18","18","ויצעקו כל המונם ויאמרו הסר את זה ופטר לנו את בר אבא׃ ");
INSERT INTO heb_vpl VALUES ("LK23_19","072_23_19","LUK","23","19","19","והוא היה משלך בית האסורים על דבר מרד אשר נהיה בעיר ועל דבר רצח׃ ");
INSERT INTO heb_vpl VALUES ("LK23_20","072_23_20","LUK","23","20","20","ויסף פילטוס לשאת קולו כי חפץ לפטר את ישוע׃ ");
INSERT INTO heb_vpl VALUES ("LK23_21","072_23_21","LUK","23","21","21","והמה צעקו אליו לאמר הצלב אותו הצלב׃ ");
INSERT INTO heb_vpl VALUES ("LK23_22","072_23_22","LUK","23","22","22","ויאמר אליהם פעם שלישית מה אפוא עשה זה רעה כל אשמת מות לא מצאתי בו על כן איסרנו ואפטרנו׃ ");
INSERT INTO heb_vpl VALUES ("LK23_23","072_23_23","LUK","23","23","23","ויפצרו בו בקול גדול ויבקשו כי יצלב ויחזק קולם וקול הכהנים הגדולים׃ ");
INSERT INTO heb_vpl VALUES ("LK23_24","072_23_24","LUK","23","24","24","ויגזר פילטוס כי תעשה בקשתם׃ ");
INSERT INTO heb_vpl VALUES ("LK23_25","072_23_25","LUK","23","25","25","ויפטר להם את המשלך בית האסורים על דבר מרד ורצח את אשר שאלו ואת ישוע מסר לרצונם׃ ");
INSERT INTO heb_vpl VALUES ("LK23_26","072_23_26","LUK","23","26","26","וכאשר הוליכהו משם ויחזיקו באיש אחד הבא מן השדה ושמו שמעון איש קוריני וישימו עליו את הצלב לשאת אחרי ישוע׃ ");
INSERT INTO heb_vpl VALUES ("LK23_27","072_23_27","LUK","23","27","27","וילכו אחריו המון עם רב והמון נשים והנה ספדות ומקוננות עליו׃ ");
INSERT INTO heb_vpl VALUES ("LK23_28","072_23_28","LUK","23","28","28","ויפן ישוע ויאמר אליהן בנות ירושלים אל תבכינה עלי כי אם על נפשכן בכינה ועל בניכן׃ ");
INSERT INTO heb_vpl VALUES ("LK23_29","072_23_29","LUK","23","29","29","כי הנה ימים באים ואמרו אשרי העקרות ואשרי המעים אשר לא ילדו והשדים אשר לא היניקו׃ ");
INSERT INTO heb_vpl VALUES ("LK23_30","072_23_30","LUK","23","30","30","אז יחלו לאמר אל ההרים נפלו עלינו ואל הגבעות כסונו׃ ");
INSERT INTO heb_vpl VALUES ("LK23_31","072_23_31","LUK","23","31","31","כי אם יעשו כזאת בעץ הלח מה יעשה ביבש׃ ");
INSERT INTO heb_vpl VALUES ("LK23_32","072_23_32","LUK","23","32","32","וגם שנים אחרים אנשי בליעל מוצאים אתו למות׃ ");
