INSERT INTO heb_vpl VALUES ("LK23_34","072_23_34","LUK","23","34","34","ויאמר ישוע אבי סלח להם כי לא ידעו מה הם עשים ויחלקו בגדיו להם ויפילו גורל׃ ");
INSERT INTO heb_vpl VALUES ("LK23_35","072_23_35","LUK","23","35","35","והעם עמד שם וראה וילעגו לו השרים לאמר את אחרים הושיע יושע נא את נפשו אם הוא המשיח בחיר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("LK23_36","072_23_36","LUK","23","36","36","ויהתלו בו אנשי הצבא ויגשו ויביאו לו חמץ׃ ");
INSERT INTO heb_vpl VALUES ("LK23_37","072_23_37","LUK","23","37","37","ויאמרו אם אתה הוא מלך היהודים הושע את נפשך׃ ");
