INSERT INTO heb_vpl VALUES ("JN1_27","073_1_27","JHN","1","27","27","הוא הבא אחרי אשר היה לפני ואני נקלתי מהתיר שרוך נעליו׃ ");
INSERT INTO heb_vpl VALUES ("JN1_28","073_1_28","JHN","1","28","28","זאת היתה בבית עברה מעבר לירדן מקום אשר יוחנן מטביל שם׃ ");
INSERT INTO heb_vpl VALUES ("JN1_29","073_1_29","JHN","1","29","29","ויהי ממחרת וירא יוחנן את ישוע בא אליו ויאמר הנה שה האלהים הנשא חטאת העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN1_30","073_1_30","JHN","1","30","30","זה הוא אשר אמרתי עליו אחרי יבא איש אשר היה לפני כי קדם לי היה׃ ");
INSERT INTO heb_vpl VALUES ("JN1_31","073_1_31","JHN","1","31","31","ואני לא ידעתיו כי אם בעבור יגלה בישראל באתי אני לטבל במים׃ ");
INSERT INTO heb_vpl VALUES ("JN1_32","073_1_32","JHN","1","32","32","ויעד יוחנן ויאמר חזיתי הרוח כדמות יונה ירדת משמים ותנח עליו׃ ");
INSERT INTO heb_vpl VALUES ("JN1_33","073_1_33","JHN","1","33","33","ואני לא ידעתיו אולם השלח אתי לטבל במים הוא אמר אלי את אשר תראה הרוח ירדת ונחה עליו הנה זה הוא אשר יטבל ברוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("JN1_34","073_1_34","JHN","1","34","34","ואני ראיתי ואעידה כי זה הוא בן האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN1_35","073_1_35","JHN","1","35","35","ויהי ממחרת ויסף יוחנן ויעמד ושנים מתלמידיו עמו׃ ");
INSERT INTO heb_vpl VALUES ("JN1_36","073_1_36","JHN","1","36","36","ויבט אל ישוע והוא מתהלך ויאמר הנה שה האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN1_37","073_1_37","JHN","1","37","37","ושני תלמידיו שמעו את דברו וילכו אחרי ישוע׃ ");
INSERT INTO heb_vpl VALUES ("JN1_38","073_1_38","JHN","1","38","38","ויפן ישוע אחריו וירא אתם הלכים אחריו ויאמר אליהם מה תבקשו ויאמרו אליו רבי פרושו מורי איפה תלין׃ ");
INSERT INTO heb_vpl VALUES ("JN1_39","073_1_39","JHN","1","39","39","ויאמר אליהם באו וראו ויבאו ויראו את מקום מלונו וישבו עמו ביום ההוא והעת כשעה העשירית׃ ");
INSERT INTO heb_vpl VALUES ("JN1_40","073_1_40","JHN","1","40","40","ואחד מן השנים אשר שמעו מאת יוחנן והלכו אחריו הוא אנדרי אחי שמעון פטרוס׃ ");
INSERT INTO heb_vpl VALUES ("JN1_41","073_1_41","JHN","1","41","41","הוא פגש בראשונה את שמעון אחיו ויאמר אליו את המשיח מצאנו אשר תרגומו כריסטוס׃ ");
INSERT INTO heb_vpl VALUES ("JN1_42","073_1_42","JHN","1","42","42","ויוליכהו אל ישוע ויהי כהביט אליו ישוע ויאמר שמעון בן יונה לך יקרא כיפא אשר תרגומו פטרוס׃ ");
INSERT INTO heb_vpl VALUES ("JN1_43","073_1_43","JHN","1","43","43","ויהי ממחרת ויואל ישוע לצאת הגלילה וימצא את פילפוס ויאמר אליו לך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("JN1_44","073_1_44","JHN","1","44","44","ופילפוס היה מבית צידה עיר אנדרי ופטרוס׃ ");
INSERT INTO heb_vpl VALUES ("JN1_45","073_1_45","JHN","1","45","45","ויפגע פילפוס את נתנאל ויאמר אליו מצאנו אתו אשר כתב משה בספר התורה והנביאים את ישוע בן יוסף מנצרת׃ ");
INSERT INTO heb_vpl VALUES ("JN1_46","073_1_46","JHN","1","46","46","ויאמר אליו נתנאל המנצרת תצא לנו טובה ויאמר אליו בא וראה׃ ");
INSERT INTO heb_vpl VALUES ("JN1_47","073_1_47","JHN","1","47","47","וירא ישוע את נתנאל בא לקראתו ויאמר עליו הנה באמת בן ישראל אשר אין בו רמיה׃ ");
INSERT INTO heb_vpl VALUES ("JN1_48","073_1_48","JHN","1","48","48","ויאמר אליו נתנאל מאין ידעתני ויען ישוע ויאמר לו בטרם קרא לך פילפוס בהיותך תחת התאנה אנכי ראיתיך׃ ");
INSERT INTO heb_vpl VALUES ("JN1_49","073_1_49","JHN","1","49","49","ויען נתנאל ויאמר אליו רבי אתה בן אלהים אתה הוא מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JN1_50","073_1_50","JHN","1","50","50","ויען ישוע ויאמר אליו על אמרי לך כי תחת התאנה ראיתיך האמנת הנה גדלות מאלה תראה׃ ");
INSERT INTO heb_vpl VALUES ("JN1_51","073_1_51","JHN","1","51","51","ויאמר אליו אמן אמן אני אמר לכם מעתה תראו השמים נפתחים ומלאכי אלהים עלים וירדים על בן אלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN2_1","073_2_1","JHN","2","1","1","וביום השלישי היתה חתנה בקנה אשר בגליל ואם ישוע היתה שם׃ ");
INSERT INTO heb_vpl VALUES ("JN2_2","073_2_2","JHN","2","2","2","וישוע ותלמידיו היו גם הם קרואים אל החתנה׃ ");
INSERT INTO heb_vpl VALUES ("JN2_3","073_2_3","JHN","2","3","3","ויחסר היין ותאמר אם ישוע אליו יין אין להם׃ ");
INSERT INTO heb_vpl VALUES ("JN2_4","073_2_4","JHN","2","4","4","ויאמר אליה ישוע מה לי ולך אשה עתי עדין לא באה׃ ");
INSERT INTO heb_vpl VALUES ("JN2_5","073_2_5","JHN","2","5","5","ותאמר אמו אל המשרתים ככל אשר יאמר לכם תעשו׃ ");
INSERT INTO heb_vpl VALUES ("JN2_6","073_2_6","JHN","2","6","6","והנה ששה כדי אבן ערוכים שם כמשפט היהודים לטהרתם שתים או שלש בתים יכיל כל אחד׃ ");
INSERT INTO heb_vpl VALUES ("JN2_7","073_2_7","JHN","2","7","7","ויאמר אליהם ישוע מלאו לכם הכדים מים וימלאום עד למעלה׃ ");
INSERT INTO heb_vpl VALUES ("JN2_8","073_2_8","JHN","2","8","8","ויאמר שאבו נא והביאו אל רב המסבה ויביאו׃ ");
INSERT INTO heb_vpl VALUES ("JN2_9","073_2_9","JHN","2","9","9","ויטעם רב המסבה את המים אשר נהפכו ליין ולא ידע מאין הוא ואולם המשרתים אשר שאבו את המים ידעו ויקרא רב המסבה אל החתן׃ ");
INSERT INTO heb_vpl VALUES ("JN2_10","073_2_10","JHN","2","10","10","ויאמר אליו כל איש יתן בראשונה את היין הטוב וכאשר ישכרו יתן להם את הגרוע ואתה צפנת היין הטוב עד עתה׃ ");
INSERT INTO heb_vpl VALUES ("JN2_11","073_2_11","JHN","2","11","11","זאת תחלת האתות אשר עשה ישוע בקנה אשר בארץ הגליל וגלה את כבודו ויאמינו בו תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("JN2_12","073_2_12","JHN","2","12","12","ויהי אחרי כן וירד אל כפר נחום הוא ואמו ואחיו ותלמידיו ולא ארכו ימי שבתם שם׃ ");
INSERT INTO heb_vpl VALUES ("JN2_13","073_2_13","JHN","2","13","13","ויקרבו ימי חג הפסח אשר ליהודים ויעל ישוע ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("JN2_14","073_2_14","JHN","2","14","14","וימצא במקדש מכרי בקר וצאן ובני יונה ואת מחליפי כסף ישבים שם׃ ");
INSERT INTO heb_vpl VALUES ("JN2_15","073_2_15","JHN","2","15","15","ויקח חבלים ויעבתם לשוט ויגרש כלם מן המקדש ואת הצאן ואת הבקר ויפזר את מעות השלחנים ויהפך שלחנתיהם׃ ");
INSERT INTO heb_vpl VALUES ("JN2_16","073_2_16","JHN","2","16","16","ואל מכרי היונים אמר הוציאו אלה מזה ואל תעשו את בית אבי לבית מסחר׃ ");
INSERT INTO heb_vpl VALUES ("JN2_17","073_2_17","JHN","2","17","17","ויזכרו תלמידיו את הכתוב כי קנאת ביתך אכלתני׃ ");
INSERT INTO heb_vpl VALUES ("JN2_18","073_2_18","JHN","2","18","18","ויענו היהודים ויאמרו אליו אי זו אות תראנו כי כזאת אתה עשה׃ ");
INSERT INTO heb_vpl VALUES ("JN2_19","073_2_19","JHN","2","19","19","ויען ישוע ויאמר אליהם הרסו את ההיכל הזה ובשלשה ימים אקימנו׃ ");
INSERT INTO heb_vpl VALUES ("JN2_20","073_2_20","JHN","2","20","20","ויאמרו היהודים הנה זה ארבעים ושש שנה נבנה ההיכל הזה ואתה בשלשה ימים תקימנו׃ ");
INSERT INTO heb_vpl VALUES ("JN2_21","073_2_21","JHN","2","21","21","והוא דבר על היכל גויתו׃ ");
INSERT INTO heb_vpl VALUES ("JN2_22","073_2_22","JHN","2","22","22","ואחרי קומו מן המתים זכרו תלמידיו כי זאת אמר להם ויאמינו בכתוב ובדבר אשר דבר ישוע׃ ");
INSERT INTO heb_vpl VALUES ("JN2_23","073_2_23","JHN","2","23","23","ויהי בהיתו בירושלים בחג הפסח האמינו רבים בשמו כי ראו האתות אשר עשה׃ ");
INSERT INTO heb_vpl VALUES ("JN2_24","073_2_24","JHN","2","24","24","והוא ישוע לא הפקיד את עצמו בידם על אשר ידע את כלם׃ ");
INSERT INTO heb_vpl VALUES ("JN2_25","073_2_25","JHN","2","25","25","ולא הצטרך לעדות איש על האדם כי הוא ידע מה בקרב האדם׃ ");
INSERT INTO heb_vpl VALUES ("JN3_1","073_3_1","JHN","3","1","1","ויהי איש אחד בתוך הפרושים ושמו נקדימון שר ליהודים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_2","073_3_2","JHN","3","2","2","ויבא אל ישוע לילה ויאמר אליו רבי ידענו כי אתה מורה מאת אלהים באת כי לא יוכל איש לעשות האתות אשר אתה עשה בלתי אם האלהים עמו׃ ");
INSERT INTO heb_vpl VALUES ("JN3_3","073_3_3","JHN","3","3","3","ויען ישוע ויאמר אליו אמן אמן אני אמר לך אם לא יולד איש מלמעלה לא יוכל לראות מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_4","073_3_4","JHN","3","4","4","ויאמר אליו נקדימון איך יולד אדם והוא זקן הכי שוב ישוב אל בטן אמו ויולד׃ ");
INSERT INTO heb_vpl VALUES ("JN3_5","073_3_5","JHN","3","5","5","ויען ישוע אמן אמן אני אמר לך אם לא יולד איש מן המים והרוח לא יוכל לבוא אל מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_6","073_3_6","JHN","3","6","6","הנולד מן הבשר בשר הוא והנולד מן הרוח רוח הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN3_7","073_3_7","JHN","3","7","7","אל תתמה על אמרי לך כי עליכם להולד מלמעלה׃ ");
INSERT INTO heb_vpl VALUES ("JN3_8","073_3_8","JHN","3","8","8","הרוח באשר יחפץ שם הוא נשב ואתה תשמע את קולו אך לא תדע מאין בא ואנה הוא הולך כן כל הנולד מן הרוח׃ ");
INSERT INTO heb_vpl VALUES ("JN3_9","073_3_9","JHN","3","9","9","ויען נקדימון ויאמר אליו איכה תהיה כזאת׃ ");
INSERT INTO heb_vpl VALUES ("JN3_10","073_3_10","JHN","3","10","10","ויען ישוע ויאמר אליו רבן של ישראל אתה וזאת לא ידעת׃ ");
INSERT INTO heb_vpl VALUES ("JN3_11","073_3_11","JHN","3","11","11","אמן אמן אני אמר לך כי את אשר ידענו נדבר ואת אשר ראינו נעיד ואתם לא תקבלו עדותנו׃ ");
INSERT INTO heb_vpl VALUES ("JN3_12","073_3_12","JHN","3","12","12","אם אמרתי אליכם דברי הארץ ואינכם מאמינים איך תאמינו באמרי אליכם דברי השמים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_13","073_3_13","JHN","3","13","13","ואיש לא עלה השמימה בלתי אם אשר ירד מן השמים בן האדם אשר הוא בשמים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_14","073_3_14","JHN","3","14","14","וכאשר הגביה משה את הנחש במדבר כן צריך בן האדם להנשא׃ ");
INSERT INTO heb_vpl VALUES ("JN3_15","073_3_15","JHN","3","15","15","למען לא יאבד כל המאמין בו כי אם יחיה חיי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_16","073_3_16","JHN","3","16","16","כי ככה אהב האלהים את העולם עד אשר נתן את בנו את יחידו למען לא יאבד כל המאמין בו כי אם יחיה חיי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_17","073_3_17","JHN","3","17","17","כי האלהים לא שלח את בנו אל העולם לדין את העולם כי אם למען יושע בו העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN3_18","073_3_18","JHN","3","18","18","המאמין בו לא ידון ואשר לא יאמין בו כבר נדון כי לא האמין בשם בן האלהים היחיד׃ ");
INSERT INTO heb_vpl VALUES ("JN3_19","073_3_19","JHN","3","19","19","וזה הוא הדין כי האור בא אל העולם ובני האדם אהבו החשך מן האור כי רעים מעשיהם׃ ");
INSERT INTO heb_vpl VALUES ("JN3_20","073_3_20","JHN","3","20","20","כי כל פעל עולה ישנא את האור ולא יבא לאור פן יוכחו מעשיו׃ ");
INSERT INTO heb_vpl VALUES ("JN3_21","073_3_21","JHN","3","21","21","אבל עשה האמת יבא לאור למען יגלו מעשיו כי נעשו באלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_22","073_3_22","JHN","3","22","22","ויהי אחרי הדברים האלה ויבא ישוע ותלמידיו אל ארץ יהודה ויגר שם עמהם ויטבל׃ ");
INSERT INTO heb_vpl VALUES ("JN3_23","073_3_23","JHN","3","23","23","וגם יוחנן היה טבל בעינון קרוב לשלם כי שמה מים לרב ויבאו ויטבלו׃ ");
INSERT INTO heb_vpl VALUES ("JN3_24","073_3_24","JHN","3","24","24","כי עוד לא נתן יוחנן אל בית הסהר׃ ");
INSERT INTO heb_vpl VALUES ("JN3_25","073_3_25","JHN","3","25","25","ויהי ריב בין תלמידי יוחנן ובין היהודים על דבר הטהרה׃ ");
INSERT INTO heb_vpl VALUES ("JN3_26","073_3_26","JHN","3","26","26","ויבאו אל יוחנן ויאמרו אליו רבי האיש אשר היה עמך בעבר הירדן ואשר העידת לו הנו טבל וכלם באים אליו׃ ");
INSERT INTO heb_vpl VALUES ("JN3_27","073_3_27","JHN","3","27","27","ויען יוחנן לא יוכל איש לקחת דבר בלתי אם נתן לו מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("JN3_28","073_3_28","JHN","3","28","28","ואתם עדי כי אמרתי אנכי אינני המשיח רק שלוח אני לפניו׃ ");
INSERT INTO heb_vpl VALUES ("JN3_29","073_3_29","JHN","3","29","29","אשר לו הכלה הוא החתן ורע החתן העמד ושמע אתו שמוח ישמח לקול החתן הנה שמחתי זאת עתה שלמה׃ ");
INSERT INTO heb_vpl VALUES ("JN3_30","073_3_30","JHN","3","30","30","הוא יגדל הלוך וגדל ואני אחסר הלוך וחסור׃ ");
INSERT INTO heb_vpl VALUES ("JN3_31","073_3_31","JHN","3","31","31","הבא ממעל נעלה על כל ואשר מארץ מארץ הוא ומארץ ידבר הבא משמים נעלה על כל׃ ");
INSERT INTO heb_vpl VALUES ("JN3_32","073_3_32","JHN","3","32","32","ואת אשר ראה ושמע את זאת יעיד ואין מקבל עדותו׃ ");
INSERT INTO heb_vpl VALUES ("JN3_33","073_3_33","JHN","3","33","33","ואשר קבל עדותו חתום חתם כי האלהים אמת׃ ");
INSERT INTO heb_vpl VALUES ("JN3_34","073_3_34","JHN","3","34","34","כי את אשר שלחו אלהים דברי אלהים ידבר כי לא במדה נתן אלהים את הרוח׃ ");
INSERT INTO heb_vpl VALUES ("JN3_35","073_3_35","JHN","3","35","35","האב אהב את בנו ואת כל נתן בידו׃ ");
INSERT INTO heb_vpl VALUES ("JN3_36","073_3_36","JHN","3","36","36","כל המאמין בבן יש לו חיי עולמים ואשר לא יאמין בבן לא יראה חיים כי אם חרון אלהים ישכן עליו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_1","073_4_1","JHN","4","1","1","ויהי כאשר נודע לאדון כי שמעו הפרושים אשר ישוע העמיד והטביל תלמידים הרבה מיוחנן׃ ");
INSERT INTO heb_vpl VALUES ("JN4_2","073_4_2","JHN","4","2","2","ואולם ישוע הוא לא הטביל כי אם תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_3","073_4_3","JHN","4","3","3","ויעזב את ארץ יהודה וילך שנית הגלילה׃ ");
INSERT INTO heb_vpl VALUES ("JN4_4","073_4_4","JHN","4","4","4","ויהי לו לעבר בארץ שמרון׃ ");
INSERT INTO heb_vpl VALUES ("JN4_5","073_4_5","JHN","4","5","5","ויבא לעיר מערי שמרון ושמה סוכר היא ממול חלקת השדה אשר נתנה יעקב לבנו ליוסף׃ ");
INSERT INTO heb_vpl VALUES ("JN4_6","073_4_6","JHN","4","6","6","ושם באר יעקב וישוע היה עיף מן הדרך וישב לו על הבאר והעת כשעה הששית׃ ");
INSERT INTO heb_vpl VALUES ("JN4_7","073_4_7","JHN","4","7","7","ותבא אשה משמרון לשאב מים ויאמר אליה ישוע תני נא לי לשתות׃ ");
INSERT INTO heb_vpl VALUES ("JN4_8","073_4_8","JHN","4","8","8","כי תלמידיו הלכו העירה לקנות אכל׃ ");
INSERT INTO heb_vpl VALUES ("JN4_9","073_4_9","JHN","4","9","9","ותאמר אליו האשה השמרונית הן יהודי אתה ואיככה תשאל ממני לשתות ואנכי אשה שמרונית כי לא יתערבו היהודים עם השמרונים׃ ");
INSERT INTO heb_vpl VALUES ("JN4_10","073_4_10","JHN","4","10","10","ויען ישוע ויאמר אליה לו ידעת את מתת אלהים ומי הוא האמר אליך תני נא לי לשתות כי עתה שאלת ממנו ונתן לך מים חיים׃ ");
INSERT INTO heb_vpl VALUES ("JN4_11","073_4_11","JHN","4","11","11","ותאמר אליו האשה אדני הן אין לך כלי לשאב בו והבאר עמקה ומאין לך אפוא מים חיים׃ ");
INSERT INTO heb_vpl VALUES ("JN4_12","073_4_12","JHN","4","12","12","האתה גדול מיעקב אבינו אשר נתן לנו את הבאר הזאת וישת ממנה הוא ובניו ובעירו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_13","073_4_13","JHN","4","13","13","ויען ישוע ויאמר אליה כל השתה מן המים האלה ישוב ויצמא׃ ");
INSERT INTO heb_vpl VALUES ("JN4_14","073_4_14","JHN","4","14","14","ואשר ישתה מן המים אשר אנכי נתן לו לא יצמא לעולם כי המים אשר אתן לו יהיו בקרבו למקור מים נבעים לחיי העולמים׃ ");
INSERT INTO heb_vpl VALUES ("JN4_15","073_4_15","JHN","4","15","15","ותאמר אליו האשה אדני תנה לי המים ההם למען לא אצמא עוד ולא אוסיף לבוא הנה לשאב׃ ");
INSERT INTO heb_vpl VALUES ("JN4_16","073_4_16","JHN","4","16","16","ויאמר אליה ישוע לכי וקראי לאישך ושובי הלום׃ ");
INSERT INTO heb_vpl VALUES ("JN4_17","073_4_17","JHN","4","17","17","ותען האשה ותאמר אין לי איש ויאמר אליה ישוע כן דברת אין לי איש׃ ");
INSERT INTO heb_vpl VALUES ("JN4_18","073_4_18","JHN","4","18","18","כי בעלים חמשה היו לך ואשר לך עתה איננו בעלך לכן אמת הדבר אשר דברת׃ ");
INSERT INTO heb_vpl VALUES ("JN4_19","073_4_19","JHN","4","19","19","ותאמר אליו האשה אדני ראה אנכי כי נביא אתה׃ ");
INSERT INTO heb_vpl VALUES ("JN4_20","073_4_20","JHN","4","20","20","אבותינו השתחוו בהר הזה ואתם אמרים כי ירושלים היא המקום הנבחר להשתחות שמה׃ ");
INSERT INTO heb_vpl VALUES ("JN4_21","073_4_21","JHN","4","21","21","ויאמר אליה ישוע אשה האמיני לי כי תבוא שעה אשר לא בהר הזה אף לא בירושלים תשתחוו לאב׃ ");
INSERT INTO heb_vpl VALUES ("JN4_22","073_4_22","JHN","4","22","22","אתם משתחוים אל אשר לא ידעתם ואנחנו משתחוים אל אשר ידענו כי הישועה מן היהודים היא׃ ");
INSERT INTO heb_vpl VALUES ("JN4_23","073_4_23","JHN","4","23","23","אולם תבוא שעה ועתה היא אשר עבדי אל האמתים ישתחוו לאב ברוח ובאמת כי במשתחוים כאלה חפץ האב׃ ");
INSERT INTO heb_vpl VALUES ("JN4_24","073_4_24","JHN","4","24","24","האלהים רוח הוא והמשתחוים לו צריכים להשתחות ברוח ובאמת׃ ");
INSERT INTO heb_vpl VALUES ("JN4_25","073_4_25","JHN","4","25","25","ותאמר אליו האשה ידעתי כי יבא המשיח הנקרא כריסטוס הוא בבאו יגיד לנו את כל׃ ");
INSERT INTO heb_vpl VALUES ("JN4_26","073_4_26","JHN","4","26","26","ויאמר אליה ישוע אני הוא המדבר אליך׃ ");
INSERT INTO heb_vpl VALUES ("JN4_27","073_4_27","JHN","4","27","27","ויהי הוא מדבר ככה ותלמידיו באו ויתמהו על דברו עם אשה אך לא אמר לו איש מה זה תשאל או מה תדבר עמה׃ ");
INSERT INTO heb_vpl VALUES ("JN4_28","073_4_28","JHN","4","28","28","ותעזב האשה את כדה ותלך העירה ותאמר אל האנשים׃ ");
INSERT INTO heb_vpl VALUES ("JN4_29","073_4_29","JHN","4","29","29","באו וראו איש אשר הגיד לי כל אשר עשיתי הכי זה הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("JN4_30","073_4_30","JHN","4","30","30","ויצאו מן העיר ויבאו אליו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_31","073_4_31","JHN","4","31","31","טרם יבאו ותלמידיו בקשו ממנו לאמר אכל נא אדני׃ ");
INSERT INTO heb_vpl VALUES ("JN4_32","073_4_32","JHN","4","32","32","ויאמר אליהם יש לי אכל לאכל אשר אתם לא ידעתם׃ ");
INSERT INTO heb_vpl VALUES ("JN4_33","073_4_33","JHN","4","33","33","ויאמרו התלמידים איש אל רעהו הכי הביא לו איש לאכל׃ ");
INSERT INTO heb_vpl VALUES ("JN4_34","073_4_34","JHN","4","34","34","ויאמר אליהם ישוע מאכלי הוא לעשות רצון שלחי ולהשלים מעשהו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_35","073_4_35","JHN","4","35","35","הלא אתם תאמרו כי עוד ארבעה חדשים והקציר בא הנה אני אמר לכם שאו עיניכם וראו בשדות כי כבר הלבינו לקציר׃ ");
INSERT INTO heb_vpl VALUES ("JN4_36","073_4_36","JHN","4","36","36","והקוצר יקח שכרו ויאסף תבואה לחיי עולמים למען ישמחו יחדו גם הזרע גם הקוצר׃ ");
INSERT INTO heb_vpl VALUES ("JN4_37","073_4_37","JHN","4","37","37","כי בזאת אמת המשל כי זה זרע ואחר יקצר׃ ");
INSERT INTO heb_vpl VALUES ("JN4_38","073_4_38","JHN","4","38","38","אנכי שלחתי אתכם לקצר את אשר לא עמלתם בו ואחרים עמלו ואתם נכנסתם בעמלם׃ ");
INSERT INTO heb_vpl VALUES ("JN4_39","073_4_39","JHN","4","39","39","ויאמינו בו שמרנים רבים מן העיר ההיא על דבר האשה אשר העידה לאמר הוא הגיד לי את כל אשר עשיתי׃ ");
INSERT INTO heb_vpl VALUES ("JN4_40","073_4_40","JHN","4","40","40","ויהי כאשר באו אליו השמרנים וישאלו ממנו לשבת אתם וישב שם יומים׃ ");
INSERT INTO heb_vpl VALUES ("JN4_41","073_4_41","JHN","4","41","41","ועוד רבים מהמה האמינו בו בעבור דברו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_42","073_4_42","JHN","4","42","42","ויאמרו אל האשה מעתה לא בעבור מאמרך נאמין כי באזנינו שמענו ונדע כי אמנם זה הוא המשיח מושיע העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN4_43","073_4_43","JHN","4","43","43","ויהי מקץ שני הימים ויצא משם ללכת הגלילה׃ ");
INSERT INTO heb_vpl VALUES ("JN4_44","073_4_44","JHN","4","44","44","כי הוא ישוע העיד כי נביא בארץ מולדתו איננו נכבד׃ ");
INSERT INTO heb_vpl VALUES ("JN4_45","073_4_45","JHN","4","45","45","ויהי הוא בא ארץ הגליל ויאספהו אנשי הגליל כי ראו את כל אשר עשה בירושלים בימי החג כי גם הם עלו לחג את החג׃ ");
INSERT INTO heb_vpl VALUES ("JN4_46","073_4_46","JHN","4","46","46","ויבא ישוע עוד הפעם אל קנה אשר בגליל מקום שומו המים ליין ואיש היה מעבדי המלך ובנו חלה בכפר נחום׃ ");
INSERT INTO heb_vpl VALUES ("JN4_47","073_4_47","JHN","4","47","47","ויהי כשמעו כי בא ישוע מיהודה לארץ הגליל וילך אליו וישאל מאתו לרדת ולרפא את בנו כי קרב למות׃ ");
INSERT INTO heb_vpl VALUES ("JN4_48","073_4_48","JHN","4","48","48","ויאמר אליו ישוע אם לא תראו אתות ומופתים לא תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_49","073_4_49","JHN","4","49","49","ויאמר אליו האיש אשר מעבדי המלך אדני רדה נא בטרם ימות בני׃ ");
INSERT INTO heb_vpl VALUES ("JN4_50","073_4_50","JHN","4","50","50","ויאמר אליו ישוע לך לך בנך חי והאיש האמין לדבר אשר דבר אליו ישוע וילך׃ ");
INSERT INTO heb_vpl VALUES ("JN4_51","073_4_51","JHN","4","51","51","ויהי ברדתו ויפגעו בו עבדיו ויבשרו אתו כי חי בנו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_52","073_4_52","JHN","4","52","52","וידרש מאתם את השעה אשר בה רוח לו ויאמרו אליו תמול בשעה השביעית עזבתו הקדחת׃ ");
INSERT INTO heb_vpl VALUES ("JN4_53","073_4_53","JHN","4","53","53","וידע אביהו כי היתה השעה אשר דבר לו ישוע בנך חי ויאמן הוא וכל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("JN4_54","073_4_54","JHN","4","54","54","זה הוא האות השני אשר עשה ישוע בבאו מיהודה לארץ הגליל׃ ");
INSERT INTO heb_vpl VALUES ("JN5_1","073_5_1","JHN","5","1","1","אחר הדברים האלה היה חג ליהודים ויעל ישוע ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("JN5_2","073_5_2","JHN","5","2","2","ובירושלים ברכה קרובה לשער הצאן ושמה בלשון עברית בית חסדא ולה חמשה אלמים׃ ");
INSERT INTO heb_vpl VALUES ("JN5_3","073_5_3","JHN","5","3","3","שמה שכבו חולים ועורים ופסחים ויבשי כח לרב והמה מיחלים לתנועת המים׃ ");
INSERT INTO heb_vpl VALUES ("JN5_4","073_5_4","JHN","5","4","4","כי מלאך ירד במועדו אל הברכה וירעש את מימיה והיה הירד ראשון אל תוכה אחרי התגעשו המים הוא נרפא מכל מחלה אשר דבקה בו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_5","073_5_5","JHN","5","5","5","ואיש היה שם אשר חלה חליו זה שלשים ושמנה שנה׃ ");
INSERT INTO heb_vpl VALUES ("JN5_6","073_5_6","JHN","5","6","6","וירא אתו ישוע שכב וידע כי ארכו לו ימי חליו ויאמר אליו התחפץ להרפא׃ ");
INSERT INTO heb_vpl VALUES ("JN5_7","073_5_7","JHN","5","7","7","ויען החולה אדני אין איש אתי אשר ישליכני בהרעש המים אל הברכה ובטרם אבא וירד אחר לפני׃ ");
INSERT INTO heb_vpl VALUES ("JN5_8","073_5_8","JHN","5","8","8","ויאמר אליו ישוע קום שא את משכבך והתהלך׃ ");
INSERT INTO heb_vpl VALUES ("JN5_9","073_5_9","JHN","5","9","9","וכרגע שב האיש לאיתנו וישא את משכבו ויתהלך והיום ההוא יום שבת היה׃ ");
INSERT INTO heb_vpl VALUES ("JN5_10","073_5_10","JHN","5","10","10","ויאמרו היהודים אל האיש הנרפא שבת היום אסור לך לשאת את משכבך׃ ");
INSERT INTO heb_vpl VALUES ("JN5_11","073_5_11","JHN","5","11","11","ויען אתם לאמר האיש אשר החלימני הוא אמר אלי שא את משכבך והתהלך׃ ");
INSERT INTO heb_vpl VALUES ("JN5_12","073_5_12","JHN","5","12","12","וישאלהו מי זה האיש אשר אמר לך שא את משכבך והתהלך׃ ");
INSERT INTO heb_vpl VALUES ("JN5_13","073_5_13","JHN","5","13","13","והנרפא לא ידע מי הוא כי סר ישוע וילך בהיות המון רב במקום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("JN5_14","073_5_14","JHN","5","14","14","ויהי אחרי כן וימצאהו ישוע בבית המקדש ויאמר אליו הנה נרפא לך אל תוסיף לחטא פן תאנה אליך רעה גדולה מזאת׃ ");
INSERT INTO heb_vpl VALUES ("JN5_15","073_5_15","JHN","5","15","15","וילך האיש ויגד ליהודים כי ישוע הוא אשר רפאו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_16","073_5_16","JHN","5","16","16","ועל כן רדפו היהודים את ישוע ויבקשו המיתו על כי עשה כזאת בשבת׃ ");
INSERT INTO heb_vpl VALUES ("JN5_17","073_5_17","JHN","5","17","17","ויען אתם ישוע אבי פעל עד עתה וגם אנכי פעל׃ ");
INSERT INTO heb_vpl VALUES ("JN5_18","073_5_18","JHN","5","18","18","אז יוסיפו היהודים לבקש את נפשו כי מלבד אשר חלל את השבת עוד אמר כי האלהים הוא אביו וידמה לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN5_19","073_5_19","JHN","5","19","19","ויען ישוע ויאמר אליהם אמן אמן אני אמר לכם לא יוכל הבן לעשות דבר מנפשו בלתי את אשר יראה את אביו עשה כי את אשר עשה הוא גם הבן יעשה כמהו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_20","073_5_20","JHN","5","20","20","כי האב אהב את הבן ומראה אתו כל אשר יעשה ועוד מעשים גדולים מאלה יראהו למען תתמהו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_21","073_5_21","JHN","5","21","21","כי כאשר האב יעיר ויחיה את המתים כן גם הבן יחיה את אשר יחפץ׃ ");
INSERT INTO heb_vpl VALUES ("JN5_22","073_5_22","JHN","5","22","22","כי האב לא ידין איש כי אם כל המשפט נתן לבן למען יכבדו כלם את הבן כאשר יכבדו את האב׃ ");
INSERT INTO heb_vpl VALUES ("JN5_23","073_5_23","JHN","5","23","23","מי אשר לא יכבד את הבן גם את האב אשר שלחו איננו מכבד׃ ");
INSERT INTO heb_vpl VALUES ("JN5_24","073_5_24","JHN","5","24","24","אמן אמן אני אמר לכם השמע דברי ומאמין לשלחי יש לו חיי עולמים ולא יבא במשפט כי עבר ממות לחיים׃ ");
INSERT INTO heb_vpl VALUES ("JN5_25","073_5_25","JHN","5","25","25","אמן אמן אני אמר לכם כי תבוא שעה ועתה היא אשר ישמעו המתים את קול בן האלהים והשמעים חיה יחיו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_26","073_5_26","JHN","5","26","26","כי כאשר לאב יש חיים בעצמו כן נתן גם לבן להיות לו חיים בעצמו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_27","073_5_27","JHN","5","27","27","ואף שלטן נתן לו לעשות משפט כי בן אדם הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN5_28","073_5_28","JHN","5","28","28","אל תתמהו על זאת כי הנה שעה באה אשר כל שכני קבר את קולו ישמעון׃ ");
INSERT INTO heb_vpl VALUES ("JN5_29","073_5_29","JHN","5","29","29","ויצאו עשי הטוב לתקומת החיים ועשי הרע לתקומת המשפט׃ ");
INSERT INTO heb_vpl VALUES ("JN5_30","073_5_30","JHN","5","30","30","לא אוכל לעשות דבר מנפשי כאשר אשמע כן אשפט ומשפטי משפט צדק כי לא אבקש רצוני כי אם רצון האב אשר שלחני׃ ");
INSERT INTO heb_vpl VALUES ("JN5_31","073_5_31","JHN","5","31","31","אם אנכי מעיד עלי עדותי איננה נאמנה׃ ");
INSERT INTO heb_vpl VALUES ("JN5_32","073_5_32","JHN","5","32","32","יש אחר המעיד עלי וידעתי כי עדותו אשר הוא מעיד עלי נאמנה היא׃ ");
INSERT INTO heb_vpl VALUES ("JN5_33","073_5_33","JHN","5","33","33","אתם שלחתם אל יוחנן והוא העיד על האמת׃ ");
INSERT INTO heb_vpl VALUES ("JN5_34","073_5_34","JHN","5","34","34","ואני אינני לקח עדות מאדם אך אמרתי זאת למען תושעון׃ ");
INSERT INTO heb_vpl VALUES ("JN5_35","073_5_35","JHN","5","35","35","הוא היה הנר הדלק והמאיר ואתם רציתם לשוש כשעה לאורו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_36","073_5_36","JHN","5","36","36","ואני יש לי עדות גדולה מעדות יוחנן כי המעשים אשר נתן לי אבי להשלימם המעשים האלה אשר אני עשה מעידים עלי כי האב שלחני׃ ");
INSERT INTO heb_vpl VALUES ("JN5_37","073_5_37","JHN","5","37","37","והאב אשר שלחני הוא מעיד עלי ואתם את קולו לא שמעתם מעולם ותמונתו לא ראיתם׃ ");
INSERT INTO heb_vpl VALUES ("JN5_38","073_5_38","JHN","5","38","38","ודברו איננו שכן בקרבכם כי אינכם מאמינים לשלוחו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_39","073_5_39","JHN","5","39","39","דרשו בכתובים אשר תחשבו שיש לכם חיי עולמים בהם והמה המעידים עלי׃ ");
INSERT INTO heb_vpl VALUES ("JN5_40","073_5_40","JHN","5","40","40","ואתם אינכם אבים לבוא אלי להיות לכם חיים׃ ");
INSERT INTO heb_vpl VALUES ("JN5_41","073_5_41","JHN","5","41","41","לא אקח כבוד מבני אדם׃ ");
INSERT INTO heb_vpl VALUES ("JN5_42","073_5_42","JHN","5","42","42","אכן ידעתי אתכם כי אין אהבת אלהים בקרבכם׃ ");
INSERT INTO heb_vpl VALUES ("JN5_43","073_5_43","JHN","5","43","43","אני הנה באתי בשם אבי ולא קבלתם אתו ואם יבא אחר בשם עצמו אתו תקבלו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_44","073_5_44","JHN","5","44","44","איך תוכלו להאמין אתם הלקחים כבוד איש מרעהו ואת הכבוד אשר מאת האלהים היחיד לא תבקשו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_45","073_5_45","JHN","5","45","45","אל תחשבו כי אנכי אטען עליכם לפני אבי משה הוא הטען עליכם אשר לו תיחלו׃ ");
INSERT INTO heb_vpl VALUES ("JN5_46","073_5_46","JHN","5","46","46","כי לו האמנתם למשה גם לי תאמינו כי הוא כתב עלי׃ ");
INSERT INTO heb_vpl VALUES ("JN5_47","073_5_47","JHN","5","47","47","ואם לכתביו אינכם מאמינים איכה לדברי תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_1","073_6_1","JHN","6","1","1","ויהי אחרי כן ויצא ישוע אל עבר ים הגליל אשר לטיבריה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_2","073_6_2","JHN","6","2","2","וילכו אחריו המון עם רב כי ראו אותתיו אשר עשה עם החולים׃ ");
INSERT INTO heb_vpl VALUES ("JN6_3","073_6_3","JHN","6","3","3","ויעל ישוע על ההר וישב שם הוא ותלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_4","073_6_4","JHN","6","4","4","וימי הפסח חג היהודים קרבו לבוא׃ ");
INSERT INTO heb_vpl VALUES ("JN6_5","073_6_5","JHN","6","5","5","וישא ישוע את עיניו וירא עם רב בא אליו ויאמר אל פילפוס מאין נקנה להם לחם לאכל׃ ");
INSERT INTO heb_vpl VALUES ("JN6_6","073_6_6","JHN","6","6","6","ואך למען נסות אתו דבר זאת כי הוא ידע את אשר יעשה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_7","073_6_7","JHN","6","7","7","ויען אתו פילפוס לחם מאתים דינר לא ימצא להם לקחת לו איש איש מעט׃ ");
INSERT INTO heb_vpl VALUES ("JN6_8","073_6_8","JHN","6","8","8","ויאמר אליו אחד מתלמידיו אנדרי אחי שמעון פטרוס׃ ");
INSERT INTO heb_vpl VALUES ("JN6_9","073_6_9","JHN","6","9","9","יש פה נער אשר לו חמש ככרות לחם שערים ושני דגים אך אלה מה המה לעם רב כזה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_10","073_6_10","JHN","6","10","10","ויאמר ישוע צוו את העם לשבת ארצה וירק דשא לרב היה במקום ההוא וישבו לארץ כחמשת אלפי איש במספר׃ ");
INSERT INTO heb_vpl VALUES ("JN6_11","073_6_11","JHN","6","11","11","ויקח ישוע את ככרות הלחם ויברך ויתן לתלמידיו והתלמידים אל המסבים וככה גם מן הדגים כאות נפשם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_12","073_6_12","JHN","6","12","12","ויהי כאשר שבעו ויאמר אל תלמידיו אספו את פתותי לחם הנותרים למען לא יאבד מאומה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_13","073_6_13","JHN","6","13","13","ויאספו וימלאו שנים עשר סלים בפתותי חמש ככרות לחם השערים הנותרים לאכליהם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_14","073_6_14","JHN","6","14","14","ויהי כראות האנשים את האות הזה אשר עשה ישוע ויאמרו הנה זה הוא באמת הנביא הבא לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_15","073_6_15","JHN","6","15","15","וידע ישוע כי יבאו ויתפשהו להמליך אותו וימלט עוד הפעם אל ההר הוא לבדו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_16","073_6_16","JHN","6","16","16","ויהי בערב וירדו תלמידיו אל הים ויבאו באניה ויעברו אל עבר הים אל כפר נחום׃ ");
INSERT INTO heb_vpl VALUES ("JN6_17","073_6_17","JHN","6","17","17","ויכס אתם החשך וישוע לא בא אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_18","073_6_18","JHN","6","18","18","ויסער הים כי רוח גדולה נושבת׃ ");
INSERT INTO heb_vpl VALUES ("JN6_19","073_6_19","JHN","6","19","19","והם חתרו במשוטיהם כדרך עשרים וחמש או שלשים ריס ויראו את ישוע מתהלך על הים הלוך וקרב אל האניה וייראו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_20","073_6_20","JHN","6","20","20","ויאמר אליהם אני הוא אל תיראו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_21","073_6_21","JHN","6","21","21","ויואילו לקחת אתו אל האניה ורגע הגיעה האניה לארץ אשר הם הלכים שמה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_22","073_6_22","JHN","6","22","22","ויהי ממחרת וירא המון העם העמד מעבר לים כי לא היתה אניה בזה בלתי אחת אשר ירדו בה תלמידיו וכי ישוע לא בא עם תלמידיו אל האניה אך תלמידיו לבדם נסעו מזה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_23","073_6_23","JHN","6","23","23","ואניות אחרות באו מטיברים קרוב למקום אשר אכלו שם את הלחם בברכת האדון׃ ");
INSERT INTO heb_vpl VALUES ("JN6_24","073_6_24","JHN","6","24","24","ויהי כראות המון העם כי ישוע איננו שם אף לא תלמידיו וירדו גם הם באניות ויבאו אל כפר נחום לבקש את ישוע׃ ");
INSERT INTO heb_vpl VALUES ("JN6_25","073_6_25","JHN","6","25","25","וכאשר מצאו אתו מעבר הים ויאמרו אליו רבי מתי באת הלם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_26","073_6_26","JHN","6","26","26","ויען אתם ישוע ויאמר אמן אמן אני אמר לכם לא על ראותכם את האתות תבקשוני כי אם על אשר אכלתם מן הלחם ותשבעו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_27","073_6_27","JHN","6","27","27","אל תעמלו במאכל אשר יאבד כי אם במאכל הקים לחיי עולמים אשר בן האדם יתננו לכם כי בו חתם חותמו אביו האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN6_28","073_6_28","JHN","6","28","28","ויאמרו אליו מה נעשה לפעל פעלות אלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN6_29","073_6_29","JHN","6","29","29","ויען ישוע ויאמר אליהם זאת פעלת אלהים כי תאמינו בזה אשר הוא שלחו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_30","073_6_30","JHN","6","30","30","ויאמרו אליו מה אפוא האות אשר תעשה למעננראה ונאמין בך מה תפעל׃ ");
INSERT INTO heb_vpl VALUES ("JN6_31","073_6_31","JHN","6","31","31","אבותינו אכלו את המן במדבר כאשר כתוב לחם מן השמים נתן למו לאכל׃ ");
