INSERT INTO heb_vpl VALUES ("JN6_33","073_6_33","JHN","6","33","33","כי לחם אלהים הוא היורד מן השמים ונתן חיים לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_34","073_6_34","JHN","6","34","34","ויאמרו אליו אדני תנה לנו תמיד את הלחם הזה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_35","073_6_35","JHN","6","35","35","ויאמר להם ישוע אנכי הוא לחם החיים כל הבא אלי לא ירעב ואשר יאמין בי לא יצמא עוד׃ ");
INSERT INTO heb_vpl VALUES ("JN6_36","073_6_36","JHN","6","36","36","ואני הנה אמרתי לכם כי גם חזיתם אתי ולא תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_37","073_6_37","JHN","6","37","37","כל אשר יתננו לי אבי יבוא אלי והבא אלי לא אהדפנו החוצה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_38","073_6_38","JHN","6","38","38","כי ירדתי מן השמים לא לעשות רצוני כי אם רצון שלחי׃ ");
INSERT INTO heb_vpl VALUES ("JN6_39","073_6_39","JHN","6","39","39","וזה רצון האב אשר שלחני כי כל אשר נתן לי לא יאבד לי כי אם אקימנו ביום האחרון׃ ");
INSERT INTO heb_vpl VALUES ("JN6_40","073_6_40","JHN","6","40","40","וזה רצון שלחי אשר כל הראה את הבן ומאמין בו יהיו לו חיי עולמים ואני אקימנו ביום האחרון׃ ");
INSERT INTO heb_vpl VALUES ("JN6_41","073_6_41","JHN","6","41","41","וילנו עליו היהודים על אמרו אנכי הוא הלחם הירד מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("JN6_42","073_6_42","JHN","6","42","42","ויאמרו הלא זה הוא ישוע בן יוסף אשר אנחנו ידעים את אביו ואת אמו ואיך יאמר מן השמים באתי׃ ");
INSERT INTO heb_vpl VALUES ("JN6_43","073_6_43","JHN","6","43","43","ויען ישוע ויאמר אליהם אל תלינו איש אל רעהו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_44","073_6_44","JHN","6","44","44","לא יוכל איש לבוא אלי בלתי אם ימשכהו אבי אשר שלחני ואני אקימנו ביום האחרון׃ ");
INSERT INTO heb_vpl VALUES ("JN6_45","073_6_45","JHN","6","45","45","הלא כתוב בנביאים וכל בניך למודי יהוה לכן כל אשר שמע מן האב ולמד יבא אלי׃ ");
