INSERT INTO heb_vpl VALUES ("JN6_47","073_6_47","JHN","6","47","47","אמן אמן אני אמר לכם המאמין בי לו חיי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("JN6_48","073_6_48","JHN","6","48","48","אנכי הוא לחם החיים׃ ");
INSERT INTO heb_vpl VALUES ("JN6_49","073_6_49","JHN","6","49","49","אבותיכם אכלו את המן במדבר וימתו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_50","073_6_50","JHN","6","50","50","זה הוא הלחם הירד מן השמים למען יאכל איש ממנו ולא ימות׃ ");
INSERT INTO heb_vpl VALUES ("JN6_51","073_6_51","JHN","6","51","51","אנכי הלחם החי הירד מן השמים איש כי יאכל מן הלחם הזה יחיה לעולם והלחם אשר אתננו הוא בשרי אשר אני נתן בעד חיי העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_52","073_6_52","JHN","6","52","52","ויתוכחו היהודים איש עם רעהו לאמר איכה יוכל זה לתת לנו את בשרו לאכל׃ ");
INSERT INTO heb_vpl VALUES ("JN6_53","073_6_53","JHN","6","53","53","ויאמר אליהם ישוע אמן אמן אני אמר לכם אם לא תאכלו את בשר בן האדם ושתיתם את דמו אין לכם חיים בקרבכם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_54","073_6_54","JHN","6","54","54","האכל את בשרי והשתה את דמי יש לו חיי עולמים ואני אקימנו ביום האחרון׃ ");
INSERT INTO heb_vpl VALUES ("JN6_55","073_6_55","JHN","6","55","55","כי בשרי באמת הוא מאכל ודמי באמת הוא משקה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_56","073_6_56","JHN","6","56","56","האכל את בשרי ושתה את דמי הוא ילין בי ואני בו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_57","073_6_57","JHN","6","57","57","כאשר שלחני האב החי ואנכי חי בגלל אבי כן האכל אתי גם הוא יחיה בגללי׃ ");
INSERT INTO heb_vpl VALUES ("JN6_58","073_6_58","JHN","6","58","58","זה הוא הלחם הירד מן השמים לא כאשר אכלו אבותיכם את המן וימתו האכל את הלחם הזה יחיה לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JN6_59","073_6_59","JHN","6","59","59","כזאת דבר בבית הכנסת בלמדו בכפר נחום׃ ");
INSERT INTO heb_vpl VALUES ("JN6_60","073_6_60","JHN","6","60","60","ורבים מתלמידיו כשמעם אמרו קשה הדבר הזה מי יוכל לשמע אתו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_61","073_6_61","JHN","6","61","61","ויבן ישוע בלבו כי תלמידיו מלינים על זאת ויאמר אליהם הזאת לכם למכשול׃ ");
INSERT INTO heb_vpl VALUES ("JN6_62","073_6_62","JHN","6","62","62","מה אפוא אם תראו את בן האדם עלה אל אשר היה שם לפנים׃ ");
INSERT INTO heb_vpl VALUES ("JN6_63","073_6_63","JHN","6","63","63","הרוח הוא הנתן חיים והבשר אין בו מועיל הדברים אשר אני דברתי אליכם רוח המה וחיים המה׃ ");
INSERT INTO heb_vpl VALUES ("JN6_64","073_6_64","JHN","6","64","64","אך יש מכם אשר לא יאמינו כי ישוע ידע מראש מי הם אשר אינם מאמינים ומי המוסר אתו׃ ");
