INSERT INTO heb_vpl VALUES ("JN6_66","073_6_66","JHN","6","66","66","מן העת הזאת רבים מתלמידיו נסגו אחור ולא יספו להתהלך אתו׃ ");
INSERT INTO heb_vpl VALUES ("JN6_67","073_6_67","JHN","6","67","67","ויאמר ישוע אל שנים העשר היש את נפשכם גם אתם לסור ממני׃ ");
INSERT INTO heb_vpl VALUES ("JN6_68","073_6_68","JHN","6","68","68","ויען אתו שמעון פטרוס אדני אל מי נלך דברי חיי עולמים עמך׃ ");
INSERT INTO heb_vpl VALUES ("JN6_69","073_6_69","JHN","6","69","69","ואנחנו האמנו ונדע כי אתה המשיח בן אל חי׃ ");
INSERT INTO heb_vpl VALUES ("JN6_70","073_6_70","JHN","6","70","70","ויען אתם ישוע הלא בחרתי אני בכם שנים העשר ואחד מכם שטן הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN6_71","073_6_71","JHN","6","71","71","זאת אמר על יהודה בן שמעון איש קריות כי עתיד היה למסרו והוא אחד משנים העשר׃ ");
INSERT INTO heb_vpl VALUES ("JN7_1","073_7_1","JHN","7","1","1","אחרי הדברים האלה הלך ישוע בארץ הגליל הלוך ועבור כי לא אבה להתהלך ביהודה על אשר בקשו היהודים להרגו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_2","073_7_2","JHN","7","2","2","ויקרב חג היהודים הוא חג הסכות׃ ");
INSERT INTO heb_vpl VALUES ("JN7_3","073_7_3","JHN","7","3","3","ויאמרו אליו אחיו קום ולך מזה ארצה יהודה למען יראו גם תלמידיך את המעשים אשר אתה עשה׃ ");
INSERT INTO heb_vpl VALUES ("JN7_4","073_7_4","JHN","7","4","4","כי לא יעשה איש דבר בסתר והוא חפץ להתפרסם לכן אם אתה עשה כאלה הגלה אל העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN7_5","073_7_5","JHN","7","5","5","כי אחיו גם הם לא האמינו בו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_6","073_7_6","JHN","7","6","6","ויאמר אליהם ישוע עתי לא באה עד עתה ועתכם תמיד נכונה׃ ");
INSERT INTO heb_vpl VALUES ("JN7_7","073_7_7","JHN","7","7","7","לא יוכל העולם לשנוא אתכם ואתי ישנא באשר אני מעיד עליו כי רעים מעלליו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_8","073_7_8","JHN","7","8","8","עלו אתם לחג את החג אני לא אעלה אל החג הזה כי עתי לא מלאה עד עתה׃ ");
INSERT INTO heb_vpl VALUES ("JN7_9","073_7_9","JHN","7","9","9","כזאת דבר וישב בגליל׃ ");
INSERT INTO heb_vpl VALUES ("JN7_10","073_7_10","JHN","7","10","10","ויהי כאשר עלו אחיו לרגל ויעל גם הוא לא בגלוי כי אם כמסתתר׃ ");
INSERT INTO heb_vpl VALUES ("JN7_11","073_7_11","JHN","7","11","11","והיהודים בקשהו בחג ויאמרו איה הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN7_12","073_7_12","JHN","7","12","12","ותהי תלונה רבה על אדותיו בתוך העם אלה אמרו טוב הוא ואלה אמרו לא כי מתעה הוא את העם׃ ");
INSERT INTO heb_vpl VALUES ("JN7_13","073_7_13","JHN","7","13","13","אך אין איש מדבר עליו בגלוי מפני יראת היהודים׃ ");
INSERT INTO heb_vpl VALUES ("JN7_14","073_7_14","JHN","7","14","14","ויהי בחצי ימי החג עלה ישוע אל המקדש וילמד׃ ");
INSERT INTO heb_vpl VALUES ("JN7_15","073_7_15","JHN","7","15","15","ויתמהו היהודים ויאמרו איך ידע זה ספר והוא לא למד׃ ");
INSERT INTO heb_vpl VALUES ("JN7_16","073_7_16","JHN","7","16","16","ויען אתם ישוע ויאמר לקחי לא שלי הוא כי אם לאשר שלחני׃ ");
INSERT INTO heb_vpl VALUES ("JN7_17","073_7_17","JHN","7","17","17","האיש החפץ לעשות רצונו ידע לקחי אם מאת אלהים הוא ואם מנפשי אדבר׃ ");
INSERT INTO heb_vpl VALUES ("JN7_18","073_7_18","JHN","7","18","18","המדבר מנפשי כבוד עצמו יבקש אבל המבקש כבוד שלחו נאמן הוא ואין עולתה בו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_19","073_7_19","JHN","7","19","19","הלא משה נתן לכם את התורה ואין איש מכם עשה התורה מדוע תבקשו להרגני׃ ");
INSERT INTO heb_vpl VALUES ("JN7_20","073_7_20","JHN","7","20","20","ויען העם ויאמר שד בקרבך מי מבקש להרגך׃ ");
INSERT INTO heb_vpl VALUES ("JN7_21","073_7_21","JHN","7","21","21","ויען ישוע ויאמר להם פעלה אחת פעלתי וכלכם עליה תתמהו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_22","073_7_22","JHN","7","22","22","משה נתן לכם המילה אך לא ממשה היא כי אם מן האבות וביום השבת תמולו כל זכר׃ ");
INSERT INTO heb_vpl VALUES ("JN7_23","073_7_23","JHN","7","23","23","ועתה אם ימול זכר בשבת למען אשר לא תופר תורת משה מה תקצפו עלי כי רפאתי איש כלו בשבת׃ ");
INSERT INTO heb_vpl VALUES ("JN7_24","073_7_24","JHN","7","24","24","אל תשפטו למראה עין כי אם משפט צדק שפטו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_25","073_7_25","JHN","7","25","25","ויאמרו אנשים מישבי ירושלים הלא זה הוא אשר בקשו להמיתו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_26","073_7_26","JHN","7","26","26","והנה הוא דבר בגלוי ולא יגערו בו האף אמנם ידעו ראשינו כי באמת זה הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("JN7_27","073_7_27","JHN","7","27","27","אך את זה ידענו מאין הוא וכאשר יבוא המשיח לא ידע איש אי מזה הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN7_28","073_7_28","JHN","7","28","28","אז קרא ישוע במקדש וילמד לאמר הן ידעתם אתי אף ידעתם מאין אני ומנפשי לא באתי אכן יש אמתי אשר שלחני ואתו לא ידעתם׃ ");
INSERT INTO heb_vpl VALUES ("JN7_29","073_7_29","JHN","7","29","29","ואני ידעתיו כי מאתו אני והוא שלחני׃ ");
INSERT INTO heb_vpl VALUES ("JN7_30","073_7_30","JHN","7","30","30","ויבקשו לתפשו ואיש לא שלח בו יד כי לא בא עתו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_31","073_7_31","JHN","7","31","31","ורבים מן העם האמינו בו ויאמרו אם יבא המשיח הגם יעשה אתות רבות מאשר עשה זה׃ ");
INSERT INTO heb_vpl VALUES ("JN7_32","073_7_32","JHN","7","32","32","והפרושים שמעו את העם מתלחשים עליו כזאת וישלחו הפרושים וראשי הכהנים משרתים לתפשו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_33","073_7_33","JHN","7","33","33","ויאמר אליהם ישוע אך למצער עודני עמכם והלכתי אל אשר שלחני׃ ");
INSERT INTO heb_vpl VALUES ("JN7_34","073_7_34","JHN","7","34","34","תשחרנני ולא תמצאנני ובאשר אני שם אתם לא תוכלו לבוא׃ ");
INSERT INTO heb_vpl VALUES ("JN7_35","073_7_35","JHN","7","35","35","ויאמרו היהודים איש רעהו אנה ילך זה ואנחנו לא נמצאהו הכי ילך אל הנפוצים בין היונים וילמד אנשי יון׃ ");
INSERT INTO heb_vpl VALUES ("JN7_36","073_7_36","JHN","7","36","36","מה זה הדבר אשר אמר תשחרנני ולא תמצאנני ובאשר אני שם אתם לא תוכלו לבוא׃ ");
INSERT INTO heb_vpl VALUES ("JN7_37","073_7_37","JHN","7","37","37","ויהי ביום החג האחרון הגדול עמד ישוע ויקרא לאמר איש כי יצמא יבא נא אלי וישתה׃ ");
INSERT INTO heb_vpl VALUES ("JN7_38","073_7_38","JHN","7","38","38","המאמין בי כדבר הכתוב מבטנו ינהרו נהרי מים חיים׃ ");
INSERT INTO heb_vpl VALUES ("JN7_39","073_7_39","JHN","7","39","39","וזאת אמר על הרוח אשר יקחהו המאמינים בו כי לא נתן רוח הקדש עדנה יען אשר ישוע עוד לא נתפאר׃ ");
INSERT INTO heb_vpl VALUES ("JN7_40","073_7_40","JHN","7","40","40","ורבים מהמון העם כשמעם את הדבר הזה אמרו אכן זה הוא הנביא׃ ");
INSERT INTO heb_vpl VALUES ("JN7_41","073_7_41","JHN","7","41","41","ויש אשר אמרו זה הוא המשיח ואחרים אמרו המן הגליל יבא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("JN7_42","073_7_42","JHN","7","42","42","הלא הכתוב אמר כי מזרע דוד ומכפר בית לחם מקום דוד יצא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("JN7_43","073_7_43","JHN","7","43","43","ותהי מחלקת בתוך העם על אדותיו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_44","073_7_44","JHN","7","44","44","ומקצתם רצו לתפשו ואיש לא שלח בו יד׃ ");
INSERT INTO heb_vpl VALUES ("JN7_45","073_7_45","JHN","7","45","45","וישובו המשרתים אל הכהנים הגדולים והפרושים והמה אמרו אליהם מדוע לא הבאתם אתו׃ ");
INSERT INTO heb_vpl VALUES ("JN7_46","073_7_46","JHN","7","46","46","ויענו העבדים מעולם לא דבר איש כאיש הזה׃ ");
INSERT INTO heb_vpl VALUES ("JN7_47","073_7_47","JHN","7","47","47","ויאמרו אליהם הפרושים הכי נדהתם גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("JN7_48","073_7_48","JHN","7","48","48","הגם האמין בו איש מן השרים או מן הפרושים׃ ");
INSERT INTO heb_vpl VALUES ("JN7_49","073_7_49","JHN","7","49","49","רק ההמון הזה אשר אינם ידעים את התורה ארורים המה׃ ");
INSERT INTO heb_vpl VALUES ("JN7_50","073_7_50","JHN","7","50","50","ויאמר אליהם נקדימון אשר בא אליו בלילה והוא היה אחד מהם׃ ");
INSERT INTO heb_vpl VALUES ("JN7_51","073_7_51","JHN","7","51","51","התשפט תורתנו איש בטרם תחקרהו לדעת את אשר עשה׃ ");
INSERT INTO heb_vpl VALUES ("JN7_52","073_7_52","JHN","7","52","52","ויענו ויאמרו אליו הגם אתה מן הגליל דרש נא וראה כי לא קם נביא מן הגליל׃ ");
INSERT INTO heb_vpl VALUES ("JN7_53","073_7_53","JHN","7","53","53","וילכו איש איש לביתו׃ ");
INSERT INTO heb_vpl VALUES ("JN8_1","073_8_1","JHN","8","1","1","וישוע הלך אל הר הזיתים׃ ");
INSERT INTO heb_vpl VALUES ("JN8_2","073_8_2","JHN","8","2","2","ויהי בבקר ויבא עוד אל המקדש וכל העם באו אליו וישב וילמדם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_3","073_8_3","JHN","8","3","3","ויביאו הסופרים והפרושים אשה לפניו אשר נתפשה בשטותה ויעמידוה בתוך׃ ");
INSERT INTO heb_vpl VALUES ("JN8_4","073_8_4","JHN","8","4","4","ויאמרו אליו רבי האשה הזאת נתפשה כשנטמאת בנאופיה׃ ");
INSERT INTO heb_vpl VALUES ("JN8_5","073_8_5","JHN","8","5","5","ומשה צונו בתורה לסקל נשים כאלה ואתה מה תאמר׃ ");
INSERT INTO heb_vpl VALUES ("JN8_6","073_8_6","JHN","8","6","6","ואך לנסות אתו דברו זאת למצא עליו שטנה ויכף ישוע למטה ויתו באצבעו על הקרקע׃ ");
INSERT INTO heb_vpl VALUES ("JN8_7","073_8_7","JHN","8","7","7","ויהי כאשר הוסיפו לשאל אתו וישא את עיניו ויאמר אליהם מי בכם זך בלי פשע הוא ראשונה ידה בה אבן׃ ");
INSERT INTO heb_vpl VALUES ("JN8_8","073_8_8","JHN","8","8","8","ויכף שנית למטה ויתו על הקרקע׃ ");
INSERT INTO heb_vpl VALUES ("JN8_9","073_8_9","JHN","8","9","9","ויהי כשמעם ויך לבם אתם ויצאו אחד אחד החוצה החל מן הזקנים ועד האחרונים ויותר ישוע לבדו והאשה נצבת בתוך׃ ");
INSERT INTO heb_vpl VALUES ("JN8_10","073_8_10","JHN","8","10","10","וישא ישוע את עיניו וירא כי אין איש בלתי האשה לבדה ויאמר אליה אשה איפה שטניך הכי הרשיעך איש׃ ");
INSERT INTO heb_vpl VALUES ("JN8_11","073_8_11","JHN","8","11","11","ותאמר לא אדני ויאמר לכן גם אני לא ארשיעך לכי לדרכך ואל תחטאי עוד׃ ");
INSERT INTO heb_vpl VALUES ("JN8_12","073_8_12","JHN","8","12","12","ויסף ישוע וידבר אליהם לאמר אני אור העולם כל ההלך אחרי לא יתהלך בחשכה כי אור החיים יהיה לו׃ ");
INSERT INTO heb_vpl VALUES ("JN8_13","073_8_13","JHN","8","13","13","ויאמרו הפרושים על נשפך מעיד אתה עדותך איננה נאמנה׃ ");
INSERT INTO heb_vpl VALUES ("JN8_14","073_8_14","JHN","8","14","14","ויען ישוע ויאמר אליהם אף אם אעיד על נפשי עדותי נאמנה יען כי ידעתי מאין באתי ואנה אני הלך ואתם לא ידעתם מאין באתי ואנה אלך׃ ");
INSERT INTO heb_vpl VALUES ("JN8_15","073_8_15","JHN","8","15","15","אתם לפי הבשר תשפטו ואני לא אשפט איש׃ ");
INSERT INTO heb_vpl VALUES ("JN8_16","073_8_16","JHN","8","16","16","ואם אנכי אשפט משפטי אמת כי לא לבדי הנני כי אם אני והאב אשר שלחני׃ ");
INSERT INTO heb_vpl VALUES ("JN8_17","073_8_17","JHN","8","17","17","וגם בתורתכם כתוב כי עדות שני אנשים נאמנה היא׃ ");
INSERT INTO heb_vpl VALUES ("JN8_18","073_8_18","JHN","8","18","18","אני הוא המעיד עלי וגם האב אשר שלחני יעידני׃ ");
INSERT INTO heb_vpl VALUES ("JN8_19","073_8_19","JHN","8","19","19","ויאמרו אליו איו אביך ויען ישוע גם אתי גם את אבי לא ידעתם אלו אתי ידעתם כי עתה גם את אבי ידעתם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_20","073_8_20","JHN","8","20","20","כדברים האלה דבר בבית האוצר בלמדו במקדש ולא תפשו איש כי לא בא עתו׃ ");
INSERT INTO heb_vpl VALUES ("JN8_21","073_8_21","JHN","8","21","21","ויוסף ישוע ויאמר אליהם אני הלך מזה ותבקשוני ובחטאתכם תמותו אל אשר אני הלך שמה אתם לא תוכלו לבוא׃ ");
INSERT INTO heb_vpl VALUES ("JN8_22","073_8_22","JHN","8","22","22","ויאמרו היהודים ההמת ימית את נפשו כי אמר אל אשר אני הולך שמה אתם לא תוכלו לבוא׃ ");
INSERT INTO heb_vpl VALUES ("JN8_23","073_8_23","JHN","8","23","23","ויאמר אליהם אתם הנכם מן התחתונים ואני מן העליונים אתם מן העולם הזה ואני אינני מן העולם הזה׃ ");
INSERT INTO heb_vpl VALUES ("JN8_24","073_8_24","JHN","8","24","24","לכן אמרתי אליכם כי תמותו בחטאיכם כי אם לא תאמינו כי אני הוא בחטאיכם תמותו׃ ");
INSERT INTO heb_vpl VALUES ("JN8_25","073_8_25","JHN","8","25","25","ויאמרו אליו מי זה אתה ויאמר אליהם ישוע מה שגם מראש דברתי אליכם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_26","073_8_26","JHN","8","26","26","רבות עמי לדבר ולשפט עליכם אכן שלחי נאמן הוא ואשר שמעתי ממנו אתו אני מדבר אל העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_27","073_8_27","JHN","8","27","27","והם לא התבוננו כי על האב אמר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_28","073_8_28","JHN","8","28","28","אז אמר להם ישוע בעת תנשאו את בן האדם וידעתם כי אני הוא וכי אינני עשה דבר מנפשי כי אם כאשר למדני אבי אלה אדבר׃ ");
INSERT INTO heb_vpl VALUES ("JN8_29","073_8_29","JHN","8","29","29","ואשר שלח אתי הוא עמדי האב לא עזבני לבדד כי את הטוב בעיניו אני עשה תמיד׃ ");
INSERT INTO heb_vpl VALUES ("JN8_30","073_8_30","JHN","8","30","30","ויהי בדברו זאת ויאמינו בו רבים׃ ");
INSERT INTO heb_vpl VALUES ("JN8_31","073_8_31","JHN","8","31","31","ויאמר ישוע אל היהודים המאמינים בו אם תעמדו בדברי באמת תלמידי אתם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_32","073_8_32","JHN","8","32","32","וידעתם את האמת והאמת תשימכם לבני חורין׃ ");
INSERT INTO heb_vpl VALUES ("JN8_33","073_8_33","JHN","8","33","33","ויענו אתו זרע אברהם נחנו ומעולם לא היינו לאיש לעבדים איכה תאמר בני חורין תהיו׃ ");
INSERT INTO heb_vpl VALUES ("JN8_34","073_8_34","JHN","8","34","34","ויען אתם ישוע אמן אמן אני אמר לכם כל עשה חטא עבד החטא הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN8_35","073_8_35","JHN","8","35","35","והעבד לא ישכן בבית לעולם הבן ישכן לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_36","073_8_36","JHN","8","36","36","לכן אם הבן יעשה אתכם בני חורין חפשים באמת תהיו׃ ");
INSERT INTO heb_vpl VALUES ("JN8_37","073_8_37","JHN","8","37","37","ידעתי כי זרע אברהם אתם אבל אתם מבקשים להמיתני כי דברי לא יכן בתוככם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_38","073_8_38","JHN","8","38","38","אני מדבר את אשר ראיתי אצל אבי ואתם עשים את אשר ראיתם אצל אביכם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_39","073_8_39","JHN","8","39","39","ויענו ויאמרו אליו אבינו הוא אברהם ויאמר אליהם ישוע אלו הייתם בני אברהם כמעשי אברהם עשיתם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_40","073_8_40","JHN","8","40","40","ועתה אתם מבקשים להמיתני איש דבר אליכם האמת אשר שמעתי מעם האלהים אברהם לא עשה כזאת׃ ");
INSERT INTO heb_vpl VALUES ("JN8_41","073_8_41","JHN","8","41","41","את מעשי אביכם אתם עשים ויאמרו אליו לא ילדי זנונים אנחנו יש לנו אב אחד הוא האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN8_42","073_8_42","JHN","8","42","42","ויאמר אליהם ישוע אלו אלהים הוא אביכם כי עתה אהבתם אתי כי אנכי יצאתי ובאתי מאת האלהים הן לא ממני באתי אך הוא שלחני׃ ");
INSERT INTO heb_vpl VALUES ("JN8_43","073_8_43","JHN","8","43","43","מדוע לא תבינו לשוני יען לא תוכלון לשמע את דברי׃ ");
INSERT INTO heb_vpl VALUES ("JN8_44","073_8_44","JHN","8","44","44","אתם מן אביכם השטן ולעשות את תאות אביכם חפצתם הוא רוצח נפש היה מראש ובאמת לא עמד כי אמת אין בו מדי דברי כזב משלו ידבר כי כזב הוא ואבי הכזב׃ ");
INSERT INTO heb_vpl VALUES ("JN8_45","073_8_45","JHN","8","45","45","ואני יען דברי האמת לא תאמינו לי׃ ");
INSERT INTO heb_vpl VALUES ("JN8_46","073_8_46","JHN","8","46","46","מי בכם על עון יוכיחני ואם אמת דברתי מדוע לא תאמינו לי׃ ");
INSERT INTO heb_vpl VALUES ("JN8_47","073_8_47","JHN","8","47","47","אשר מאת האלהים הוא ישמע את דברי האלהים על כן אתם לא שמעתם כי אינכם מאת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN8_48","073_8_48","JHN","8","48","48","אז יענו היהודים ויאמרו אליו הלא הטבנו אשר דברנו כי שמרוני אתה ושד בך׃ ");
INSERT INTO heb_vpl VALUES ("JN8_49","073_8_49","JHN","8","49","49","ויען ישוע שד אין בי רק את אבי אני מכבד ואתם תבזוני׃ ");
INSERT INTO heb_vpl VALUES ("JN8_50","073_8_50","JHN","8","50","50","אכן לא אבקש את כבודי יש אחד אשר יבקש וישפט׃ ");
INSERT INTO heb_vpl VALUES ("JN8_51","073_8_51","JHN","8","51","51","אמן אמן אני אמר לכם אם ישמר איש את דברי לא יראה מות לנצח׃ ");
INSERT INTO heb_vpl VALUES ("JN8_52","073_8_52","JHN","8","52","52","ויאמרו אליו היהודים עתה ידענו כי שד בך הן אברהם והנביאים מתו ואתה אמרת אם ישמר איש את דברי לא יטעם מות לנצח׃ ");
INSERT INTO heb_vpl VALUES ("JN8_53","073_8_53","JHN","8","53","53","האתה גדול מאברהם אבינו אשר מת גם הנביאים מתו מה תעשה את עצמך׃ ");
INSERT INTO heb_vpl VALUES ("JN8_54","073_8_54","JHN","8","54","54","ויען ישוע אם אני מכבד את נפשי כבודי מאין אבי הוא המכבד אתי אשר תאמרו עליו כי הוא אלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("JN8_55","073_8_55","JHN","8","55","55","ולא ידעתם אתו ואני ידעתיו ואם אמר לא ידעתי אתו אהיה כזב כמוכם אבל ידעתיו ואת דברו שמרתי׃ ");
INSERT INTO heb_vpl VALUES ("JN8_56","073_8_56","JHN","8","56","56","אברהם אביכם שש לראות את יומי וירא וישמח׃ ");
INSERT INTO heb_vpl VALUES ("JN8_57","073_8_57","JHN","8","57","57","ויאמרו אליו היהודים הנה אינך בן חמשים שנה ואת אברהם ראית׃ ");
INSERT INTO heb_vpl VALUES ("JN8_58","073_8_58","JHN","8","58","58","ויאמר אליהם ישוע אמן אמן אני אמר לכם בטרם היות אברהם אני הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN8_59","073_8_59","JHN","8","59","59","אז ירימו אבנים לרגם אתו וישוע התעלם ויצא מן המקדש ויעבר בתוכם עבור וחלוף׃ ");
INSERT INTO heb_vpl VALUES ("JN9_1","073_9_1","JHN","9","1","1","ויהי בעברו וירא איש והוא עור מיום הולדו׃ ");
INSERT INTO heb_vpl VALUES ("JN9_2","073_9_2","JHN","9","2","2","וישאלו אתו תלמידיו לאמר רבי מי הוא אשר חטא הזה אם ילדיו כי נולד עור׃ ");
INSERT INTO heb_vpl VALUES ("JN9_3","073_9_3","JHN","9","3","3","ויען ישוע לא זה חטא ולא יולדיו אך למען יגלו בו מעללי אל׃ ");
INSERT INTO heb_vpl VALUES ("JN9_4","073_9_4","JHN","9","4","4","עלי לעשות מעשי שלחי בעוד יום יבוא הלילה אשר בו לא יוכל איש לפעל׃ ");
INSERT INTO heb_vpl VALUES ("JN9_5","073_9_5","JHN","9","5","5","בהיותי בעולם אור העולם אני׃ ");
INSERT INTO heb_vpl VALUES ("JN9_6","073_9_6","JHN","9","6","6","ויהי כדברו זאת וירק על הארץ ויעש טיט מן הרוק וימרח את הטיט על עיני העור׃ ");
INSERT INTO heb_vpl VALUES ("JN9_7","073_9_7","JHN","9","7","7","ויאמר אליו לך ורחץ בברכת השלח פרושו שלוח וילך וירחץ ויבא ועיניו ראות׃ ");
INSERT INTO heb_vpl VALUES ("JN9_8","073_9_8","JHN","9","8","8","ויאמרו שכניו ואשר ראו אתו לפנים כי עור הוא הלא זה הוא הישב ומשאל׃ ");
INSERT INTO heb_vpl VALUES ("JN9_9","073_9_9","JHN","9","9","9","אלה אמרו כי הוא זה ואלה אמרו אך דומה לו והוא אמר אני הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN9_10","073_9_10","JHN","9","10","10","ויאמרו אליו במה אפו נפקחו עיניך׃ ");
INSERT INTO heb_vpl VALUES ("JN9_11","073_9_11","JHN","9","11","11","ויען ויאמר איש אשר נקרא שמו ישוע עשה טיט וימרח על עיני ויאמר אלי לך ורחץ בברכת השלח ואלך וארחץ ותארנה עיני׃ ");
INSERT INTO heb_vpl VALUES ("JN9_12","073_9_12","JHN","9","12","12","ויאמרו אליו איו ויאמר לא ידעתי׃ ");
INSERT INTO heb_vpl VALUES ("JN9_13","073_9_13","JHN","9","13","13","ויביאו את האיש אשר היה עור לפנים אל הפרושים׃ ");
INSERT INTO heb_vpl VALUES ("JN9_14","073_9_14","JHN","9","14","14","והיום אשר עשה בו ישוע את הטיט ויפקח את עיניו שבת היה׃ ");
INSERT INTO heb_vpl VALUES ("JN9_15","073_9_15","JHN","9","15","15","ויוסיפו לשאל אתו גם הפרושים איך נפקחו עיניו ויאמר אליהם טיט שם על עיני וארחץ והנני ראה׃ ");
INSERT INTO heb_vpl VALUES ("JN9_16","073_9_16","JHN","9","16","16","ויאמרו מקצת הפרושים זה האיש לא מאלהים הוא כי לא ישמר את השבת ואחרים אמרו איכה יוכל איש חטא לעשות אתות כאלה ויהי ריב ביניהם׃ ");
INSERT INTO heb_vpl VALUES ("JN9_17","073_9_17","JHN","9","17","17","ויוסיפו ויאמרו אל העור מה תאמר אתה עליו אשר פקח עיניך ויאמר נביא הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN9_18","073_9_18","JHN","9","18","18","ולא האמינו היהודים עליו כי עור היה וארו עיניו עד אשר קראו אל יולדי הנרפא׃ ");
INSERT INTO heb_vpl VALUES ("JN9_19","073_9_19","JHN","9","19","19","וישאלו אתם לאמר הזה הוא בנכם אשר אמרתם כי נולד עור ואיכה הוא ראה עתה׃ ");
INSERT INTO heb_vpl VALUES ("JN9_20","073_9_20","JHN","9","20","20","ויענו אתם יולדיו ויאמרו ידענו כי זה הוא בננו וכי נולד עור׃ ");
INSERT INTO heb_vpl VALUES ("JN9_21","073_9_21","JHN","9","21","21","אבל איך הוא ראה עתה או מי פקח את עיניו אנחנו לא ידענו הלא בן דעת הוא שאלו את פיהו והוא יגיד מה היה לו׃ ");
INSERT INTO heb_vpl VALUES ("JN9_22","073_9_22","JHN","9","22","22","כזאת דברו יולדיו מיראתם את היהודים כי היהודים כבר נועצו לנדות את כל אשר יודה כי הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("JN9_23","073_9_23","JHN","9","23","23","על כן אמרו יולדיו בן דעת הוא שאלו את פיהו׃ ");
INSERT INTO heb_vpl VALUES ("JN9_24","073_9_24","JHN","9","24","24","ויקראו שנית לאיש אשר היה עור ויאמרו אליו תן כבוד לאלהים אנחנו ידענו כי האיש הזה חטא הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN9_25","073_9_25","JHN","9","25","25","ויען ויאמר אם האיש חטא הוא אינני ידע אחת ידעתי כי עור הייתי ועתה הנני ראה׃ ");
INSERT INTO heb_vpl VALUES ("JN9_26","073_9_26","JHN","9","26","26","ויאמרו אליו עוד מה עשה לך איכה פקח עיניך׃ ");
INSERT INTO heb_vpl VALUES ("JN9_27","073_9_27","JHN","9","27","27","ויען אתם כבר אמרתי לכם הלא שמעתם ומה לכם לשמע שנית התאבו גם אתם להיות תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("JN9_28","073_9_28","JHN","9","28","28","ויחרפו אתו ויאמרו אתה תלמידו ואנחנו תלמידיו של משה׃ ");
INSERT INTO heb_vpl VALUES ("JN9_29","073_9_29","JHN","9","29","29","אנחנו יודעים כי אל משה דבר האלהים ואת זה לא ידענו מאין הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN9_30","073_9_30","JHN","9","30","30","ויען האיש ויאמר אליהם זאת היא הפלא ופלא כי לא ידעתם מאין הוא והוא פקח את עיני׃ ");
INSERT INTO heb_vpl VALUES ("JN9_31","073_9_31","JHN","9","31","31","והנה ידענו כי את החטאים לא ישמע אל כי אם את ירא האלהים ועשה רצונו אתו ישמע׃ ");
INSERT INTO heb_vpl VALUES ("JN9_32","073_9_32","JHN","9","32","32","מעולם לא נשמע כי פקח איש עיני עור מרחם׃ ");
INSERT INTO heb_vpl VALUES ("JN9_33","073_9_33","JHN","9","33","33","לולא היה זה מאת אלהים לא היה יכל לעשות מאומה׃ ");
INSERT INTO heb_vpl VALUES ("JN9_34","073_9_34","JHN","9","34","34","ויענו ויאמרו אליו הן בחטאים נולדת כלך ואתה תלמדנו ויהדפהו החוצה׃ ");
INSERT INTO heb_vpl VALUES ("JN9_35","073_9_35","JHN","9","35","35","וישמע ישוע כי הדפהו החוצה ויפגשהו ויאמר אליו התאמין בבן האדם׃ ");
INSERT INTO heb_vpl VALUES ("JN9_36","073_9_36","JHN","9","36","36","ויען ויאמר מי הוא זה אדני למען אאמין בו׃ ");
INSERT INTO heb_vpl VALUES ("JN9_37","073_9_37","JHN","9","37","37","ויאמר אליו ישוע הן ראית אתו והמדבר אליך הנה זה הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN9_38","073_9_38","JHN","9","38","38","ויאמר אני מאמין אדני וישתחו לו׃ ");
INSERT INTO heb_vpl VALUES ("JN9_39","073_9_39","JHN","9","39","39","ויאמר ישוע אני לדין באתי לעולם הזה למען יראו העורים והראים יכו בעורון׃ ");
INSERT INTO heb_vpl VALUES ("JN9_40","073_9_40","JHN","9","40","40","ואשר היו עמו מן הפרושים שמעו דבריו ויאמרו אליו הגם אנחנו עורים׃ ");
INSERT INTO heb_vpl VALUES ("JN9_41","073_9_41","JHN","9","41","41","ויאמר אליהם אם עורים הייתם לא היה בכם חטא ועתה כי אמרתם פקחים אנחנו חטאתכם תעמד׃ ");
INSERT INTO heb_vpl VALUES ("JN10_1","073_10_1","JHN","10","1","1","אמן אמן אני אמר לכם איש אשר לא יבוא דרך השער אל מכלא הצאן כי אם יעלה בדרך אחר גנב ופריץ הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN10_2","073_10_2","JHN","10","2","2","ואשר יבוא דרך השער הוא רעה הצאן׃ ");
INSERT INTO heb_vpl VALUES ("JN10_3","073_10_3","JHN","10","3","3","לו יפתח שמר הסף והצאן את קלו תשמענה והוא לצאנו בשם יקרא ויוציאם׃ ");
INSERT INTO heb_vpl VALUES ("JN10_4","073_10_4","JHN","10","4","4","ואחרי הוציאו את צאנו הוא יעבר לפניהן והצאן הלכות אחריו כי ידעו את קולו׃ ");
INSERT INTO heb_vpl VALUES ("JN10_5","073_10_5","JHN","10","5","5","ואחרי זר לא תלכנה כי אם ינוסו מפניו כי את קול הזרים לא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("JN10_6","073_10_6","JHN","10","6","6","המשל הזה דבר ישוע באזניהם והמה לא ידעו מה זאת אשר אמר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JN10_7","073_10_7","JHN","10","7","7","ויוסף ישוע וידבר אליהם אמן אמן אני אמר לכם אני הוא דלת הצאן׃ ");
INSERT INTO heb_vpl VALUES ("JN10_8","073_10_8","JHN","10","8","8","כל אשר באו לפני גנבים המה ופריצים והצאן לא שמעו לקולם׃ ");
INSERT INTO heb_vpl VALUES ("JN10_9","073_10_9","JHN","10","9","9","אנכי הדלת איש כי יבוא בי יושע ובצאתו ובבואו ימצא מרעה׃ ");
INSERT INTO heb_vpl VALUES ("JN10_10","073_10_10","JHN","10","10","10","הגנב לא יבוא כי אם לגנוב ולהרוג ולאבד ואני באתי לבעבור הביא להם חיים ומלא ספקם׃ ");
INSERT INTO heb_vpl VALUES ("JN10_11","073_10_11","JHN","10","11","11","אנכי הוא הרעה הטוב הרעה הטוב יתן את נפשו בעד צאנו׃ ");
INSERT INTO heb_vpl VALUES ("JN10_12","073_10_12","JHN","10","12","12","והשכיר אשר לא רעה הוא והצאן לא לו הנה בראותו כי בא הזאב יעזב את הצאן ונס והזאב יחטף ויפיץ את הצאן׃ ");
INSERT INTO heb_vpl VALUES ("JN10_13","073_10_13","JHN","10","13","13","השכיר ינוס כי שכיר הוא ולא ידאג לצאן׃ ");
INSERT INTO heb_vpl VALUES ("JN10_14","073_10_14","JHN","10","14","14","אני הרעה הטוב וידעתי את אשר לי ונודעתי לאשר לי׃ ");
INSERT INTO heb_vpl VALUES ("JN10_15","073_10_15","JHN","10","15","15","כאשר האב ידעני ואני ידעתי את האב ואת נפשי אתן בעד הצאן׃ ");
INSERT INTO heb_vpl VALUES ("JN10_16","073_10_16","JHN","10","16","16","וצאן אחרות יש לי אשר אינן מן המכלה הזאת ועלי לנהל גם אתן ותשמענה קולי והיה עדר אחד ורעה אחד׃ ");
INSERT INTO heb_vpl VALUES ("JN10_17","073_10_17","JHN","10","17","17","על כן אהב אתי אבי כי את נפשי אתן למען אשוב ואקחה׃ ");
INSERT INTO heb_vpl VALUES ("JN10_18","073_10_18","JHN","10","18","18","ואיש לא יקחנה מאתי כי אם אני מעצמי אתננה יש בידי לתת אתה ובידי לשוב לקחתה את המצוה הזאת לקחתי מעם אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN10_19","073_10_19","JHN","10","19","19","ותהי מחלקת גם בפעם הזאת בין היהודים על הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("JN10_20","073_10_20","JHN","10","20","20","ויאמרו רבים מהם שד בו ומשגע הוא למה תשמעו אליו׃ ");
INSERT INTO heb_vpl VALUES ("JN10_21","073_10_21","JHN","10","21","21","ואחרים אמרו לא כאלה ידבר איש אחוז שד היוכל שד לפקח עיני עורים׃ ");
INSERT INTO heb_vpl VALUES ("JN10_22","073_10_22","JHN","10","22","22","ויהי חג חנכת הבית בירושלים וסתיו היה׃ ");
INSERT INTO heb_vpl VALUES ("JN10_23","073_10_23","JHN","10","23","23","ויתהלך ישוע במקדש באולם של שלמה׃ ");
INSERT INTO heb_vpl VALUES ("JN10_24","073_10_24","JHN","10","24","24","ויסבו אתו היהודים ויאמרו אליו עד אנה תתלה את נפשנו את המשיח אתה הגידה לנו ברור׃ ");
INSERT INTO heb_vpl VALUES ("JN10_25","073_10_25","JHN","10","25","25","ויען אתם ישוע הן אמרתי אליכם ולא האמנתם בי המעשים אשר אני עשה בשם אבי הם יעידו עלי׃ ");
INSERT INTO heb_vpl VALUES ("JN10_26","073_10_26","JHN","10","26","26","אבל אתם לא תאמינו יען לא מצאני אתם כאשר אמרתי לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN10_27","073_10_27","JHN","10","27","27","צאני תשמענה את קולי ואני ידעתין ואחרי תלכנה׃ ");
INSERT INTO heb_vpl VALUES ("JN10_28","073_10_28","JHN","10","28","28","ואני אתן להן חיי עולמים ולא תאבדנה לנצח ואיש לא יחטף אתהן מידי׃ ");
INSERT INTO heb_vpl VALUES ("JN10_29","073_10_29","JHN","10","29","29","האב אשר נתנן לי גדול הוא על כל ואיש לא יחטף אתהן מיד האב׃ ");
INSERT INTO heb_vpl VALUES ("JN10_30","073_10_30","JHN","10","30","30","אני ואבי אחד אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("JN10_31","073_10_31","JHN","10","31","31","אז ירימו היהודים כפעם בפעם אבנים לסקלו׃ ");
INSERT INTO heb_vpl VALUES ("JN10_32","073_10_32","JHN","10","32","32","ויען אתם ישוע מעשים טובים רבים הראיתי אתכם מאת אבי על אי זה מן המעשים ההם תסקלני׃ ");
INSERT INTO heb_vpl VALUES ("JN10_33","073_10_33","JHN","10","33","33","ויענו היהודים אתו לאמר על מעשה טוב לא נסקל אתך כי אם על גדפך את אלהים ועל כי אדם אתה ותעש את עצמך לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN10_34","073_10_34","JHN","10","34","34","ויען אתם ישוע הלא כתוב בתורתכם אני אמרתי אלהים אתם׃ ");
INSERT INTO heb_vpl VALUES ("JN10_35","073_10_35","JHN","10","35","35","הן קרא שם אלהים לאלה אשר היה דבר האלהים אליהם והכתוב לא יופר׃ ");
INSERT INTO heb_vpl VALUES ("JN10_36","073_10_36","JHN","10","36","36","ואיך תאמרו על אשר קדשו האב ושלחו לעולם מגדף אתה יען אמרתי בן אלהים אני׃ ");
INSERT INTO heb_vpl VALUES ("JN10_37","073_10_37","JHN","10","37","37","אם לא אעשה את מעשי אבי אל תאמינו לי׃ ");
INSERT INTO heb_vpl VALUES ("JN10_38","073_10_38","JHN","10","38","38","ואם עשיתי ולא תאמינו לי האמינו נא למעשי למען תדעו ותאמינו כי בי האב ואני בו׃ ");
INSERT INTO heb_vpl VALUES ("JN10_39","073_10_39","JHN","10","39","39","אז ישובו ויבקשו לתפשו וימלט מידם׃ ");
INSERT INTO heb_vpl VALUES ("JN10_40","073_10_40","JHN","10","40","40","וילך וישב אל עבר הירדן אל המקום אשר הטביל שם יוחנן בתחלה וישב שם׃ ");
INSERT INTO heb_vpl VALUES ("JN10_41","073_10_41","JHN","10","41","41","ויבאו אליו רבים ויאמרו הנה יוחנן לא עשה אות אבל כל אשר דבר יוחנן על האיש הזה אמת היה׃ ");
INSERT INTO heb_vpl VALUES ("JN10_42","073_10_42","JHN","10","42","42","ויאמינו בו רבים במקום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("JN11_1","073_11_1","JHN","11","1","1","ויהי איש חולה לעזר שמו מבית היני כפר מרים ומרתא אחותה׃ ");
INSERT INTO heb_vpl VALUES ("JN11_2","073_11_2","JHN","11","2","2","היא מרים אשר משחה את האדון בשמן המר ותנגב את רגליו בשערותיה ועתה לעזר אחיה חלה׃ ");
INSERT INTO heb_vpl VALUES ("JN11_3","073_11_3","JHN","11","3","3","ותשלחנה אחיותיו אליו לאמר אדני הנה זה אשר אהבת חלה הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN11_4","073_11_4","JHN","11","4","4","וישמע ישוע ויאמר זאת המחלה איננה למות כי אם לכבוד האלהים למען יכבד בה בן האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN11_5","073_11_5","JHN","11","5","5","וישוע אהב את מרתא ואת אחותה ואת לעזר׃ ");
