INSERT INTO heb_vpl VALUES ("JN11_10","073_11_10","JHN","11","10","10","אבל ההלך בלילה יכשל כי האור אין בו׃ ");
INSERT INTO heb_vpl VALUES ("JN11_11","073_11_11","JHN","11","11","11","כזאת דבר ואחרי כן אמר אליהם לעזר ידידנו ישן הוא ואנכי הלך למען אעירנו׃ ");
