INSERT INTO heb_vpl VALUES ("JN11_33","073_11_33","JHN","11","33","33","ויהי כראות ישוע אתה בכיה וגם היהודים אשר באו אתה בכים ותזעם רוחו ויהי מרעיד׃ ");
