INSERT INTO heb_vpl VALUES ("JN11_35","073_11_35","JHN","11","35","35","ויבך ישוע׃ ");
INSERT INTO heb_vpl VALUES ("JN11_36","073_11_36","JHN","11","36","36","ויאמרו היהודים הנה מה גדלה אהבתו אתו׃ ");
