INSERT INTO heb_vpl VALUES ("JN12_7","073_12_7","JHN","12","7","7","ויאמר ישוע הניחה לה ליום קבורתי צפנה זאת׃ ");
INSERT INTO heb_vpl VALUES ("JN12_8","073_12_8","JHN","12","8","8","כי העניים תמיד המה עמכם ואני אינני תמיד עמכם׃ ");
