INSERT INTO heb_vpl VALUES ("JN12_13","073_12_13","JHN","12","13","13","ויקחו בידם כפות תמרים ויצאו לקראתו ויריעו לאמר הושע נא ברוך הבא בשם יהוה מלך ישראל׃ ");
INSERT INTO heb_vpl VALUES ("JN12_14","073_12_14","JHN","12","14","14","וימצא ישוע עיר אחד וירכב עליו כאשר כתוב׃ ");
INSERT INTO heb_vpl VALUES ("JN12_15","073_12_15","JHN","12","15","15","אל תיראי בת ציון הנה מלכך יבוא לך רכב על עיר בן אתנות׃ ");
INSERT INTO heb_vpl VALUES ("JN12_16","073_12_16","JHN","12","16","16","וכל זאת לא הבינו תלמידיו בראשונה אך אחרי אשר נתפאר ישוע זכרו כי כן כתוב עליו וכי זאת עשו לו׃ ");
INSERT INTO heb_vpl VALUES ("JN12_17","073_12_17","JHN","12","17","17","ויעידו העם אשר היו אצלו בקראו אל לעזר לצאת מן הקבר ויער אתו מעם המתים׃ ");
