INSERT INTO heb_vpl VALUES ("JN12_19","073_12_19","JHN","12","19","19","והפרושים דברו איש את אחיו לאמר הראיתם כי הועיל לא תועילו מאומה הנה כל העולם נמשך אחריו׃ ");
INSERT INTO heb_vpl VALUES ("JN12_20","073_12_20","JHN","12","20","20","ובתוך העלים להשתחות בחג היו אנשים יונים׃ ");
INSERT INTO heb_vpl VALUES ("JN12_21","073_12_21","JHN","12","21","21","ויקרבו אל פילפוס איש בית צידה אשר בארץ הגליל וישאלו ממנו לאמר אדני לראות את ישוע חפצנו׃ ");
INSERT INTO heb_vpl VALUES ("JN12_22","073_12_22","JHN","12","22","22","ויבא פילפוס ויגד זאת אל אנדרי ואנדרי ופילפוס הגידו אל ישוע׃ ");
INSERT INTO heb_vpl VALUES ("JN12_23","073_12_23","JHN","12","23","23","ויען אותם ישוע ויאמר באה השעה שיפאר בן האדם׃ ");
INSERT INTO heb_vpl VALUES ("JN12_24","073_12_24","JHN","12","24","24","אמן אמן אני אמר לכם אם לא יפל גרגר החטא אל תוך האדמה ומת ישאר לבדו וכאשר מת יעשה פרי הרבה׃ ");
INSERT INTO heb_vpl VALUES ("JN12_25","073_12_25","JHN","12","25","25","האהב את נפשו יאבדנה והשנא את נפשו בעולם הזה ינצרה לחיי נצח׃ ");
INSERT INTO heb_vpl VALUES ("JN12_26","073_12_26","JHN","12","26","26","החפץ לשרתני ילך אחרי ובאשר אהיה שם יהיה גם משרתי ואיש אשר ישרתני אתו יכבד אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN12_27","073_12_27","JHN","12","27","27","עתה נבהלה נפשי ומה אמר הושיעני אבי מן השעה הזאת אך על כן באתי אל השעה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("JN12_28","073_12_28","JHN","12","28","28","אבי פאר את שמך ותצא בת קול מן השמים גם פארתי וגם אוסיף לפאר׃ ");
INSERT INTO heb_vpl VALUES ("JN12_29","073_12_29","JHN","12","29","29","והעם העמדים שמה כשמעם אמרו רעם נשמע ואחרים אמרו מלאך דבר אתו׃ ");
INSERT INTO heb_vpl VALUES ("JN12_30","073_12_30","JHN","12","30","30","ויען ישוע ויאמר לא למעני היה הקול הזה כי אם למענכם׃ ");
INSERT INTO heb_vpl VALUES ("JN12_31","073_12_31","JHN","12","31","31","עתה משפט בא על העולם הזה עתה ישלך שר העולם הזה חוצה׃ ");
INSERT INTO heb_vpl VALUES ("JN12_32","073_12_32","JHN","12","32","32","ואני בהנשאי מעל הארץ אמשך כלם אלי׃ ");
INSERT INTO heb_vpl VALUES ("JN12_33","073_12_33","JHN","12","33","33","וזאת דבר לרמוז אי זה מות הוא עתיד למות׃ ");
INSERT INTO heb_vpl VALUES ("JN12_34","073_12_34","JHN","12","34","34","ויענו אתו העם ויאמרו הנה שמענו בתורה כי המשיח יכון לעולם ואיך אמרת כי בן האדם צריך להנשא ומי בן האדם הלזה׃ ");
INSERT INTO heb_vpl VALUES ("JN12_35","073_12_35","JHN","12","35","35","ויאמר אליהם ישוע אך למצער יהיה האור עמכם התהלכו בעוד לכם האור פן ישופכם חשך וההלך בחשך לא ידע אנה הוא הלך׃ ");
INSERT INTO heb_vpl VALUES ("JN12_36","073_12_36","JHN","12","36","36","בעוד לכם האור האמינו באור למען תהיו בני האור את הדברים האלה דבר ישוע וילך לו ויסתר מפניהם׃ ");
INSERT INTO heb_vpl VALUES ("JN12_37","073_12_37","JHN","12","37","37","רבים האתות אשר עשה לעיניהם ובכל זאת לא האמינו בו׃ ");
INSERT INTO heb_vpl VALUES ("JN12_38","073_12_38","JHN","12","38","38","למלאת דבר ישעיהו הנביא אשר אמר יהוה מי האמין לשמעתנו וזרוע יהוה על מי נגלתה׃ ");
INSERT INTO heb_vpl VALUES ("JN12_39","073_12_39","JHN","12","39","39","על כן לא יכלו להאמין כי עוד אמר ישעיהו׃ ");
INSERT INTO heb_vpl VALUES ("JN12_40","073_12_40","JHN","12","40","40","השע עיניהם והשמין לבבם פן יראו בעיניהם ולבבם יבין ושבו ורפאתי להם׃ ");
INSERT INTO heb_vpl VALUES ("JN12_41","073_12_41","JHN","12","41","41","כזאת דבר ישעיהו בראותו את תפארתו וינבא עליו׃ ");
INSERT INTO heb_vpl VALUES ("JN12_42","073_12_42","JHN","12","42","42","אולם רבים אף מן השרים האמינו בו אך בגלל הפרושים לא הודו למען אשר לא ינדו׃ ");
INSERT INTO heb_vpl VALUES ("JN12_43","073_12_43","JHN","12","43","43","כי אהבו כבוד אנשים יותר מכבוד האלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN12_44","073_12_44","JHN","12","44","44","ויקרא ישוע ויאמר המאמין בי לא בי הוא מאמין כי אם בשלח אתי׃ ");
INSERT INTO heb_vpl VALUES ("JN12_45","073_12_45","JHN","12","45","45","והראה אתי את אשר שלחני הוא ראה׃ ");
INSERT INTO heb_vpl VALUES ("JN12_46","073_12_46","JHN","12","46","46","אני באתי לאור אל העולם למען כל אשר יאמין בי לא ישב בחשך׃ ");
INSERT INTO heb_vpl VALUES ("JN12_47","073_12_47","JHN","12","47","47","והשמע את דברי ולא ישמרם אני לא אשפט אתו כי לא באתי לשפט את העולם כי אם להושיע את העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN12_48","073_12_48","JHN","12","48","48","ואיש אשר יבזני ולא יקח אמרי יש אחד אשר ידין אתו הדבר אשר דברתי הוא ידין אתו ביום האחרון׃ ");
INSERT INTO heb_vpl VALUES ("JN12_49","073_12_49","JHN","12","49","49","כי אני לא מלבי דברתי כי אם אבי השלח אתי הוא צוני את אשר אמר ואת אשר אדבר׃ ");
INSERT INTO heb_vpl VALUES ("JN12_50","073_12_50","JHN","12","50","50","ואני ידעתי כי מצותו חיי עולם לכן כל אשר אדבר כאשר אמר אלי אבי כן אני מדבר׃ ");
INSERT INTO heb_vpl VALUES ("JN13_1","073_13_1","JHN","13","1","1","ולפני חג הפסח כשידע ישוע כי באה שעתו לעבר מן העולם הזה אל אביו כאשר אהב את בחיריו אשר בעולם כן אהבם עד הקץ׃ ");
INSERT INTO heb_vpl VALUES ("JN13_2","073_13_2","JHN","13","2","2","ויהי אחרי החל הסעודה והשטן נתן בלב יהודה בן שמעון איש קריות למסרו׃ ");
INSERT INTO heb_vpl VALUES ("JN13_3","073_13_3","JHN","13","3","3","וידע ישוע כי נתן אביו את הכל בידו וכי מאלהים בא ואל אלהים ישוב׃ ");
INSERT INTO heb_vpl VALUES ("JN13_4","073_13_4","JHN","13","4","4","ויקם מעל השלחן ויפשט את בגדיו ויקח מטפחת ויחגרה׃ ");
INSERT INTO heb_vpl VALUES ("JN13_5","073_13_5","JHN","13","5","5","ואחר יצק מים בכיור ויחל לרחץ את רגלי תלמידיו ולנגב במטפחת אשר הוא חגור בה׃ ");
INSERT INTO heb_vpl VALUES ("JN13_6","073_13_6","JHN","13","6","6","ויקרב אל שמעון פטרוס והוא אמר אליו אדני האתה תרחץ את רגלי׃ ");
INSERT INTO heb_vpl VALUES ("JN13_7","073_13_7","JHN","13","7","7","ויען ישוע ויאמר אליו את אשר אני עשה אינך ידע כעת ואחרי כן תדע׃ ");
INSERT INTO heb_vpl VALUES ("JN13_8","073_13_8","JHN","13","8","8","ויאמר אליו פטרוס לעולם לא תרחץ את רגלי ויען ישוע אם לא ארחץ אתך אין לך חלק עמי׃ ");
INSERT INTO heb_vpl VALUES ("JN13_9","073_13_9","JHN","13","9","9","ויאמר אליו שמעון פטרוס אדני לא לבד את רגלי כי אם גם את ידי ואת ראשי׃ ");
INSERT INTO heb_vpl VALUES ("JN13_10","073_13_10","JHN","13","10","10","ויאמר אליו ישוע המרחץ אין לו לרחץ עוד כי אם את הרגלים כי כלו טהור הוא ואתם טהורים אך לא כלכם׃ ");
INSERT INTO heb_vpl VALUES ("JN13_11","073_13_11","JHN","13","11","11","כי ידע מי ימסרהו על כן אמר לא כלכם טהורים׃ ");
INSERT INTO heb_vpl VALUES ("JN13_12","073_13_12","JHN","13","12","12","ויהי אחרי אשר רחץ את רגלים וילבש את בגדיו וישב להסב ויאמר אליהם הידעתם מה הדבר אשר עשיתי לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN13_13","073_13_13","JHN","13","13","13","אתם קראים לי רב ואדון והיטבתם אשר דברתם כי אני הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN13_14","073_13_14","JHN","13","14","14","לכן אם אני המורה והאדון רחצתי את רגליכם גם אתם חיבים לרחץ איש את רגלי אחיו׃ ");
INSERT INTO heb_vpl VALUES ("JN13_15","073_13_15","JHN","13","15","15","כי מופת נתתי לכם למען תעשו גם אתם כאשר עשיתי לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN13_16","073_13_16","JHN","13","16","16","אמן אמן אני אמר לכם כי העבד איננו גדול מאדניו והשלוח איננו גדול משלחו׃ ");
INSERT INTO heb_vpl VALUES ("JN13_17","073_13_17","JHN","13","17","17","אם ידעתם זאת אשריכם אם כן תעשו׃ ");
INSERT INTO heb_vpl VALUES ("JN13_18","073_13_18","JHN","13","18","18","לא על כלכם דברתי יודע אני את אשר בחרתי בהם אך למען ימלא הכתוב אוכל לחמי הגדיל עלי עקב׃ ");
INSERT INTO heb_vpl VALUES ("JN13_19","073_13_19","JHN","13","19","19","מעתה אני אמר לכם בטרם היותה למען בבואה תאמינו כי אני הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN13_20","073_13_20","JHN","13","20","20","אמן אמן אני אמר לכם כי כל המקבל את אשר אשלחהו אתי הוא מקבל והמקבל אתי הוא מקבל את שלחי׃ ");
INSERT INTO heb_vpl VALUES ("JN13_21","073_13_21","JHN","13","21","21","ויהי ככלות ישוע לדבר הדברים האלה ויבהל ברוחו ויעד ויאמר אמן אמן אני אמר לכם כי אחד מכם ימסרני׃ ");
INSERT INTO heb_vpl VALUES ("JN13_22","073_13_22","JHN","13","22","22","ויתראו תלמידיו ויתמהו איש אל רעהו לדעת על מי דבר׃ ");
INSERT INTO heb_vpl VALUES ("JN13_23","073_13_23","JHN","13","23","23","ואחד מתלמידיו מסב על חיק ישוע אשר ישוע אהבו׃ ");
INSERT INTO heb_vpl VALUES ("JN13_24","073_13_24","JHN","13","24","24","וירמז לו שמעון פטרוס לדרש מי הוא זה אשר דבר עליו׃ ");
INSERT INTO heb_vpl VALUES ("JN13_25","073_13_25","JHN","13","25","25","ויפל על לב ישוע ויאמר אליו אדני מי הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN13_26","073_13_26","JHN","13","26","26","ויען ישוע הנה זה הוא אשר אטבל פתי לתתו לו ויטבל את פתו ויתן אל יהודה בן שמעון איש קריות׃ ");
INSERT INTO heb_vpl VALUES ("JN13_27","073_13_27","JHN","13","27","27","ואחרי בלעו בא השטן אל קרבו ויאמר אליו ישוע את אשר תעשה עשה מהרה׃ ");
INSERT INTO heb_vpl VALUES ("JN13_28","073_13_28","JHN","13","28","28","ומן המסבים לא ידע איש על מה דבר אליו כזאת׃ ");
INSERT INTO heb_vpl VALUES ("JN13_29","073_13_29","JHN","13","29","29","כי יש אשר חשבו כי אמר אליו ישוע קנה לנו צרכי החג או לתת לאביונים יען אשר כיס הכסף תחת יד יהודה׃ ");
INSERT INTO heb_vpl VALUES ("JN13_30","073_13_30","JHN","13","30","30","והוא בקחתו את פת הלחם מהר לצאת החוצה ויהי לילה׃ ");
INSERT INTO heb_vpl VALUES ("JN13_31","073_13_31","JHN","13","31","31","הוא יצא וישוע אמר עתה נתפאר בן האדם והאלהים נתפאר בו׃ ");
INSERT INTO heb_vpl VALUES ("JN13_32","073_13_32","JHN","13","32","32","אם האלהים נתפאר בו גם האלהים הוא יפארהו בעצמו ובמהרה יפארהו׃ ");
INSERT INTO heb_vpl VALUES ("JN13_33","073_13_33","JHN","13","33","33","בני עוד מעט מזער אהיה עמכם אתם תבקשוני וכאשר אמרתי אל היהודים כי אל אשר אני הולך לא תוכלו לבוא שמה כן אליכם אמר אני עתה׃ ");
INSERT INTO heb_vpl VALUES ("JN13_34","073_13_34","JHN","13","34","34","מצוה חדשה אני נתן לכם כי תאהבו איש את אחיו כאשר אהבתי אתכם כן גם אתם איש את אחיו תאהבון׃ ");
INSERT INTO heb_vpl VALUES ("JN13_35","073_13_35","JHN","13","35","35","בזאת ידעו כלם כי תלמידי אתם בהיות אהבה ביניכם׃ ");
INSERT INTO heb_vpl VALUES ("JN13_36","073_13_36","JHN","13","36","36","ויאמר אליו פטרוס אדני אנה תלך ויען אתו ישוע אל אשר אני הולך שמה לא תוכל עתה ללכת אחרי אך אחרי כן תלך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("JN13_37","073_13_37","JHN","13","37","37","ויאמר אליו פטרוס מדוע לא אוכל עתה ללכת אחריך הן נפשי בעד נפשך אתן׃ ");
INSERT INTO heb_vpl VALUES ("JN13_38","073_13_38","JHN","13","38","38","ויען אתו ישוע הכי תתן נפשך בעד נפשי אמן אמן אני אמר לך בטרם יקרא התרנגל תכחש בי שלש פעמים׃ ");
INSERT INTO heb_vpl VALUES ("JN14_1","073_14_1","JHN","14","1","1","אל יבהל לבבכם האמינו באלהים ובי האמינו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_2","073_14_2","JHN","14","2","2","בבית אבי מעונות רבות ואם לא כן הוא כי עתה הגדתי לכם הנני הלך להכין מקום לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_3","073_14_3","JHN","14","3","3","והיה כי הלכתי והכינותי לכם מקום שוב אשוב ולקחתי אתכם אלי למען באשר אהיה שם תהיו גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_4","073_14_4","JHN","14","4","4","ואל אשר אני הולך שמה ידעתם ואת הדרך ידעתם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_5","073_14_5","JHN","14","5","5","ויאמר אליו תומא אדני לא ידענו אנה אתה הלך ואיככה נדע את הדרך׃ ");
INSERT INTO heb_vpl VALUES ("JN14_6","073_14_6","JHN","14","6","6","ויאמר אליו ישוע אנכי הנני הדרך והאמת והחיים לא יבא איש אל האב כי אם על ידי׃ ");
INSERT INTO heb_vpl VALUES ("JN14_7","073_14_7","JHN","14","7","7","לו ידעתם אתי גם את אבי ידעתם ומעתה ידעתם אתו וראיתם אתו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_8","073_14_8","JHN","14","8","8","ויאמר אליו פילפוס אדני הראנו נא את האב ודי לנו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_9","073_14_9","JHN","14","9","9","ויאמר אליו ישוע זה כמה ימים אנכי אתכם ואתה פילפוס הטרם תדעני הראה אתי ראה את האב ולמה זה תאמר הראנו את האב׃ ");
INSERT INTO heb_vpl VALUES ("JN14_10","073_14_10","JHN","14","10","10","האינך מאמין כי אנכי באבי ואבי בי הוא הדברים אשר אדבר אליכם לא מנפשי אנכי דבר כי אבי השכן בקרבי הוא עשה את המעשים׃ ");
INSERT INTO heb_vpl VALUES ("JN14_11","073_14_11","JHN","14","11","11","האמינו לי כי אנכי באבי ואבי בי הוא ואם לא אך בגלל המעשים האמינו לי׃ ");
INSERT INTO heb_vpl VALUES ("JN14_12","073_14_12","JHN","14","12","12","אמן אמן אני אמר לכם המאמין בי יעשה גם הוא את המעשים אשר אנכי עשה וגדלות מאלה יעשה כי אני הולך אל אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN14_13","073_14_13","JHN","14","13","13","וכל אשר תשאלו בשמי אעשנו למען יכבד האב בבנו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_14","073_14_14","JHN","14","14","14","כי תשאלו דבר בשמי אני אעשנו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_15","073_14_15","JHN","14","15","15","אם אהבתם אתי את מצותי תשמרו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_16","073_14_16","JHN","14","16","16","ואני אשאלה מאבי והוא יתן לכם פרקליט אחר אשר ישכן אתכם לנצח׃ ");
INSERT INTO heb_vpl VALUES ("JN14_17","073_14_17","JHN","14","17","17","את רוח האמת אשר לא יכל העולם להשיגו באשר לא יראהו ולא ידעהו ואתם ידעתם אתו כי אתכם שכן הוא אף יהיה בתוככם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_18","073_14_18","JHN","14","18","18","לא אעזבכם יתומים אבואה אליכם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_19","073_14_19","JHN","14","19","19","עוד מעט והעולם לא יוסיף לראות אתי ואתם תראוני כי חי אני וגם אתם חיה תחיו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_20","073_14_20","JHN","14","20","20","והיה ביום ההוא ידוע תדעו כי אני באבי ואתם בי ואני בכם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_21","073_14_21","JHN","14","21","21","מי אשר מצותי אתו וינצרן זה הוא אשר יאהבני ואהבי אהוב הוא לאבי ואני אהבהו ואליו אתודע׃ ");
INSERT INTO heb_vpl VALUES ("JN14_22","073_14_22","JHN","14","22","22","ויאמר אליו יהודה לא יהודה איש קריות אדני מה הוא זה כי תחפץ להתודע אלינו ולא לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_23","073_14_23","JHN","14","23","23","ויען ישוע ויאמר אליו איש כי יאהבני ישמר את דברי ואבי יאהב אתו ונבואה אליו ונשים אצלו מעונתנו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_24","073_14_24","JHN","14","24","24","ואשר לא יאהבני הוא לא ישמר את דברי והדבר אשר שמעתם לא שלי הוא כי אם של אבי אשר שלחני׃ ");
INSERT INTO heb_vpl VALUES ("JN14_25","073_14_25","JHN","14","25","25","את אלה דברתי אליכם בעוד היותי עמכם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_26","073_14_26","JHN","14","26","26","והפרקליט תוח הקדש אשר ישלחנו אבי בשמי הוא ילמדכם את כל ויזכירכם את כל אשר הגדתי לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN14_27","073_14_27","JHN","14","27","27","שלום אניח לכם את שלומי אתן לכם לא כאשר יתן העולם אנכי נתן לכם אל יבהל לבבכם ואל יחת׃ ");
INSERT INTO heb_vpl VALUES ("JN14_28","073_14_28","JHN","14","28","28","הלא שמעתם כי אמרתי אליכם אלך לי ואשובה אליכם אם אהב תאהבוני כי עתה תשמחו באמרי לכם כי הלך אני אל האב כי אבי גדול ממני׃ ");
INSERT INTO heb_vpl VALUES ("JN14_29","073_14_29","JHN","14","29","29","ועתה הנה הגדתי זאת לכם בטרם היותה למען בבואה תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("JN14_30","073_14_30","JHN","14","30","30","לא ארבה עוד אמרים עמכם כי יבוא שר העולם הזה ובי אין לו מאומה׃ ");
INSERT INTO heb_vpl VALUES ("JN14_31","073_14_31","JHN","14","31","31","אך למען ידע העולם כי את אבי אני אהב וכאשר צוני אבי כן אני עשה קומו ונלכה מזה׃ ");
INSERT INTO heb_vpl VALUES ("JN15_1","073_15_1","JHN","15","1","1","אנכי הגפן האמתית ואבי הוא הכרם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_2","073_15_2","JHN","15","2","2","כל שריג בי אשר איננו עשה פרי יסירנו ואשר יעשה פרי יטהרנו להרבות את פריו׃ ");
INSERT INTO heb_vpl VALUES ("JN15_3","073_15_3","JHN","15","3","3","אתם כעת מטהרים בעבור דברי אשר דברתי אליכם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_4","073_15_4","JHN","15","4","4","עמדו בי ואני בכם כאשר השריג בל יעשה פרי מאליו אם לא יעמד בגפן כן גם אתם אם לא תעמדו בי׃ ");
INSERT INTO heb_vpl VALUES ("JN15_5","073_15_5","JHN","15","5","5","אנכי הוא הגפן ואתם השריגים העמד בי ואני בו הוא יעשה פרי לרב כי בלעדי לא תוכלון עשות מאומה׃ ");
INSERT INTO heb_vpl VALUES ("JN15_6","073_15_6","JHN","15","6","6","איש אשר לא יעמד בי השלך כשריג החוצה וייבש וילקטום וישליכום אל תוך האש והיה לבער׃ ");
INSERT INTO heb_vpl VALUES ("JN15_7","073_15_7","JHN","15","7","7","והיה אם תעמדו בי ודברי יהיו בכם ככל חפצכם תשאלו ויעשה לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_8","073_15_8","JHN","15","8","8","בזאת נכבד אבי בעשותכם פרי לרב והייתם לי לתלמידים׃ ");
INSERT INTO heb_vpl VALUES ("JN15_9","073_15_9","JHN","15","9","9","כאשר אהבני אבי אהבתי אתכם גם אני ואתם עמדו באהבתי׃ ");
INSERT INTO heb_vpl VALUES ("JN15_10","073_15_10","JHN","15","10","10","אם תשמרו את מצותי תעמדו באהבתי כאשר שמרתי גם אני את מצות אבי ועמדתי באהבתו׃ ");
INSERT INTO heb_vpl VALUES ("JN15_11","073_15_11","JHN","15","11","11","את אלה דברתי אליכם בעבור תהיה שמחתי בכם ותמלא שמחתכם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_12","073_15_12","JHN","15","12","12","הנה זאת מצותי כי תאהבון איש את אחיו כאשר אהבתיכם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_13","073_15_13","JHN","15","13","13","אין לאיש אהבה יתרה מתתו את נפשו בעד ידידיו׃ ");
INSERT INTO heb_vpl VALUES ("JN15_14","073_15_14","JHN","15","14","14","ואתם ידידי אתם אם תעשו את אשר אני מצוה אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_15","073_15_15","JHN","15","15","15","לא אקרא לכם עוד עבדים כי העבד איננו ידע את אשר יעשה אדניו כי אם אמרתי ידידי אתם כי כל אשר שמעתי מאת אבי הודעתי אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_16","073_15_16","JHN","15","16","16","לא אתם בחרתם בי כי אם אנכי בחרתי בכם והפקדתי אתכם ללכת ולעשות פרי ופריכם יקום והיה כל אשר תשאלו מאבי בשמי יתן לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_17","073_15_17","JHN","15","17","17","את אלה אני מצוה אתכם למען תאהבון איש את אחיו׃ ");
INSERT INTO heb_vpl VALUES ("JN15_18","073_15_18","JHN","15","18","18","אם העולם שנא אתכם דעו כי אתי שנא ראשונה׃ ");
INSERT INTO heb_vpl VALUES ("JN15_19","073_15_19","JHN","15","19","19","אלו מן העולם הייתם כי אז אהב העולם את אשר לו ויען כי אינכם מן העולם כי אם בחרתי אתכם מתוך העולם לכן העולם ישנא אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_20","073_15_20","JHN","15","20","20","זכרו את דברי אשר דברתי אליכם העבד איננו גדול מאדניו אם רדפו אתי גם אתכם ירדפו אם שמרו את דברי גם את דברכם ישמרו׃ ");
INSERT INTO heb_vpl VALUES ("JN15_21","073_15_21","JHN","15","21","21","אבל כל זאת יעשו לכם בעבור שמי כי לא ידעו את שלחי׃ ");
INSERT INTO heb_vpl VALUES ("JN15_22","073_15_22","JHN","15","22","22","לולא באתי ודברתי אליהם לא היה בהם חטא ועתה לא יוכלון להתנצל על חטאתם׃ ");
INSERT INTO heb_vpl VALUES ("JN15_23","073_15_23","JHN","15","23","23","השנא אתי ישנא גם את אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN15_24","073_15_24","JHN","15","24","24","לולא עשיתי בתוכם את המעשים אשר איש זולתי לא עשה לא היה בהם חטא ועתה ראו וישנאו גם אתי גם את אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN15_25","073_15_25","JHN","15","25","25","אך למלאת דבר הכתוב בתורתם שנאת חנם שנאוני׃ ");
INSERT INTO heb_vpl VALUES ("JN15_26","073_15_26","JHN","15","26","26","ובבוא הפרקליט אשר אשלחנו לכם מאת אבי רוח האמת היוצא מאת אבי הוא יעיד עלי׃ ");
INSERT INTO heb_vpl VALUES ("JN15_27","073_15_27","JHN","15","27","27","וגם אתם תעידו כי מראש הייתם עמדי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_1","073_16_1","JHN","16","1","1","את אלה דברתי אליכם למען לא תכשלו׃ ");
INSERT INTO heb_vpl VALUES ("JN16_2","073_16_2","JHN","16","2","2","הנה ינדו אתכם ואף באה השעה אשר כל הרג אתכם ידמה להקריב עבודה לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN16_3","073_16_3","JHN","16","3","3","וכזאת יעשו לכם יען גם את אבי וגם אתי לא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("JN16_4","073_16_4","JHN","16","4","4","אבל הגדתי לכם את אלה למען אשר בבא השעה תזכרום כי אנכי אמרתי אליכם וכאלה לא אמרתי אליכם מראש כי הייתי עמכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_5","073_16_5","JHN","16","5","5","ועתה הלך אנכי אל שלחי ולא ישאלני איש מכם אנה תלך׃ ");
INSERT INTO heb_vpl VALUES ("JN16_6","073_16_6","JHN","16","6","6","אך על דברי את אלה אליכם מלא לבבכם עצבת׃ ");
INSERT INTO heb_vpl VALUES ("JN16_7","073_16_7","JHN","16","7","7","אולם האמת אגיד לכם כי לכתי אך טוב לכם כי אם לא אלך לא יבא אליכם הפרקליט ואם אלך אשלחהו אליכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_8","073_16_8","JHN","16","8","8","והיה בבאו יוכיח את העולם על דבר החטא והצדק והמשפט׃ ");
INSERT INTO heb_vpl VALUES ("JN16_9","073_16_9","JHN","16","9","9","על החטא כי לא האמינו בי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_10","073_16_10","JHN","16","10","10","ועל הצדק כי אלך אל אבי ולא תוסיפו לראות אתי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_11","073_16_11","JHN","16","11","11","ועל המשפט כי נדון שר העולם הזה׃ ");
INSERT INTO heb_vpl VALUES ("JN16_12","073_16_12","JHN","16","12","12","עוד רבות לי להגיד לכם אך לא תוכלון שאת עתה׃ ");
INSERT INTO heb_vpl VALUES ("JN16_13","073_16_13","JHN","16","13","13","ורוח האמת בבאו הוא ידריך אתכם אל כל האמת כי לא ידבר מעצמו כי אם אשר ישמע ידבר והאתיות יגיד לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_14","073_16_14","JHN","16","14","14","הוא יפארני כי משלי יקח ויגיד לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_15","073_16_15","JHN","16","15","15","כל אשר לאבי לי הוא על כן אמרתי כי משלי יקח ויגיד לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_16","073_16_16","JHN","16","16","16","הן מעט ולא תראוני ועוד מעט ותחזוני כי אני הלך אל אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_17","073_16_17","JHN","16","17","17","ומקצת תלמידיו נדברו איש אל אחיו לאמר מה זה אמר אלינו הן מעט ולא תראוני ועוד מעט ותחזוני ואמרו אני הלך אל אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_18","073_16_18","JHN","16","18","18","ויאמרו מה זה אשר אמר מעט לא ידענו מה דבר׃ ");
INSERT INTO heb_vpl VALUES ("JN16_19","073_16_19","JHN","16","19","19","וידע ישוע כי עם לבבם לשאל אתו ויאמר אליהם העל זאת אתם דרשים ביניכם כי אמרתי הן מעט ולא תראוני ועוד מעט ותחזוני׃ ");
INSERT INTO heb_vpl VALUES ("JN16_20","073_16_20","JHN","16","20","20","אמן אמן אני אמר לכם כי אתם תבכו ותילילו והעולם ישמח הן אתם תעצבו אכן עצבכם יהפך לששון׃ ");
INSERT INTO heb_vpl VALUES ("JN16_21","073_16_21","JHN","16","21","21","האשה בלדתה עצב לה כי באה עתה ואחרי ילדה את הילד לא תזכר עוד את עצבונה משמחתה כי אדם נולד לעולם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_22","073_16_22","JHN","16","22","22","וגם אתם כעת תתעצבו אך אשוב אראה אתכם ושש לבכם ואין לקח שמחתכם מכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_23","073_16_23","JHN","16","23","23","וביום ההוא לא תשאלוני דבר אמן אמן אני אמר לכם כי כל אשר תשאלו מאת אבי בשמי יתננו לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_24","073_16_24","JHN","16","24","24","עד עתה לא שאלתם דבר בשמי שאלו ותקחו למען תמלא שמחתכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_25","073_16_25","JHN","16","25","25","את אלה דברתי אליכם במשלים אכן שעה באה ולא אדבר עוד אליכם במשלים כי אם ברור אמלל לכם על אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_26","073_16_26","JHN","16","26","26","ביום ההוא תשאלו בשמי ואינני אמר לכם כי אני אעתיר לאבי בעדכם׃ ");
INSERT INTO heb_vpl VALUES ("JN16_27","073_16_27","JHN","16","27","27","כי אבי גם הוא אהב אתכם עקב אשר אהבתוני והאמנתם כי מאת אלהים יצאתי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_28","073_16_28","JHN","16","28","28","מאת האב יצאתי ואבא לעולם אשובה אעזב את העולם ואלך אל אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_29","073_16_29","JHN","16","29","29","ויאמרו אליו תלמידיו הנה כעת ברור תמלל ולא תמשל משל׃ ");
INSERT INTO heb_vpl VALUES ("JN16_30","073_16_30","JHN","16","30","30","עתה ידענו כי כל ידעת ולא תצטרך כי ישאלך איש בזאת נאמין כי מאת אלהים יצאת׃ ");
INSERT INTO heb_vpl VALUES ("JN16_31","073_16_31","JHN","16","31","31","ויען אתם ישוע עתה תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("JN16_32","073_16_32","JHN","16","32","32","הנה שעה באה ועתה זה הגיעה ונפצותם איש איש לביתו ואתי תעזבו לבדי ואינני לבדי כי אבי עמדי׃ ");
INSERT INTO heb_vpl VALUES ("JN16_33","073_16_33","JHN","16","33","33","את אלה דברתי אליכם למען בי יהיה לכם שלום בעולם יהיה לכם עני אך יאמץ לבבכם אני נצחתי את העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN17_1","073_17_1","JHN","17","1","1","את אלה דבר ישוע וישא עיניו השמימה ויאמר אבי הנה באה השעה פאר את בנך למען גם בנך יפארך׃ ");
INSERT INTO heb_vpl VALUES ("JN17_2","073_17_2","JHN","17","2","2","כאשר נתת לו השלטן על כל בשר למען יתן חיי עולמים לכל אשר נתת לו׃ ");
INSERT INTO heb_vpl VALUES ("JN17_3","073_17_3","JHN","17","3","3","ואלה הם חיי העולמים לדעת אתך אשר אתה לבדך אל אמת ואת ישוע המשיח אשר שלחת׃ ");
INSERT INTO heb_vpl VALUES ("JN17_4","073_17_4","JHN","17","4","4","אני פארתיך בארץ כליתי פעלך אשר צויתני לעשות׃ ");
INSERT INTO heb_vpl VALUES ("JN17_5","073_17_5","JHN","17","5","5","ועתה פארני אתה אבי עמך בכבוד אשר היה לי עמך טרם היות העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN17_6","073_17_6","JHN","17","6","6","את שמך הודעתי לבני האדם אשר נתתם לי מתוך העולם לך היו ולי נתת אתם ואת דברך נצרו׃ ");
INSERT INTO heb_vpl VALUES ("JN17_7","073_17_7","JHN","17","7","7","ועתה ידעו כי כל אשר נתת לי מעמך הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN17_8","073_17_8","JHN","17","8","8","כי הדברים אשר נתת לי נתתי להם והם קבלום ויכירו באמת כי מעמך יצאתי ויאמינו כי אתה שלחתני׃ ");
INSERT INTO heb_vpl VALUES ("JN17_9","073_17_9","JHN","17","9","9","אני בעדם אעתיר לך לא בעד העולם אעתיר כי אם בעד אלה אשר נתת לי כי לך המה׃ ");
INSERT INTO heb_vpl VALUES ("JN17_10","073_17_10","JHN","17","10","10","וכל אשר לי לך הוא ושלך שלי ונתפארתי בהם׃ ");
INSERT INTO heb_vpl VALUES ("JN17_11","073_17_11","JHN","17","11","11","ואני אינני עוד בעולם והם בעולם המה ואני בא אליך אבי הקדוש נצר בשמך את אשר נתתם לי למען יהיו אחד כמנו׃ ");
INSERT INTO heb_vpl VALUES ("JN17_12","073_17_12","JHN","17","12","12","בהיותי עמהם בעולם אני נצרתי אתם בשמך את אשר נתתם לי שמרתי ולא אבד מהם איש זולתי בן האבדון למלאת דבר הכתוב׃ ");
INSERT INTO heb_vpl VALUES ("JN17_13","073_17_13","JHN","17","13","13","ועתה הנני בא אליך ואלה אני מדבר בעולם למען תמלא להם שמחתי בקרבם׃ ");
INSERT INTO heb_vpl VALUES ("JN17_14","073_17_14","JHN","17","14","14","אני נתתי להם את דברך והעולם שנא אתם יען כי לא מן העולם המה כאשר גם אנכי לא מן העולם אני׃ ");
INSERT INTO heb_vpl VALUES ("JN17_15","073_17_15","JHN","17","15","15","ולא אעתיר לך אשר תקחם מן העולם רק שתצרם מן הרע׃ ");
INSERT INTO heb_vpl VALUES ("JN17_16","073_17_16","JHN","17","16","16","מן העולם אינמו כאשר גם אנכי אינני מן העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN17_17","073_17_17","JHN","17","17","17","קדש אתם באמתך דברך אמת הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN17_18","073_17_18","JHN","17","18","18","כאשר אתה שלחת אתי אל העולם כן גם אני שלחתי אתם אל העולם׃ ");
INSERT INTO heb_vpl VALUES ("JN17_19","073_17_19","JHN","17","19","19","והתקדשתי בעדם למען יהיו גם הם מקדשים באמת׃ ");
INSERT INTO heb_vpl VALUES ("JN17_20","073_17_20","JHN","17","20","20","אולם לא לבד בעד אלה אנכי מעתיר לך כי אם גם בעד המאמינים בי על פי דברם׃ ");
INSERT INTO heb_vpl VALUES ("JN17_21","073_17_21","JHN","17","21","21","למען יהיו כלם אחד כאשר אתה אבי בי אתה ואני בך והיו גם המה בנו כאשר למען יאמין העולם כי אתה שלחתני׃ ");
INSERT INTO heb_vpl VALUES ("JN17_22","073_17_22","JHN","17","22","22","ואני נתתי להם את הכבוד אשר נתת לי למען יהיו אחד כאשר אנחנו אחד נחנו׃ ");
INSERT INTO heb_vpl VALUES ("JN17_23","073_17_23","JHN","17","23","23","אני בהם ואתה בי למען יהיו משלמים לאחד ולמען ידע העולם כי אתה שלחתני ואהבת אתם כאשר אהבתני׃ ");
INSERT INTO heb_vpl VALUES ("JN17_24","073_17_24","JHN","17","24","24","אבי חפצתי כי גם הם אשר נתתם לי יהיו עמי באשר אהיה אני למען יחזו את כבודי אשר נתת לי כי אהבתני לפני מוסדות עולם׃ ");
INSERT INTO heb_vpl VALUES ("JN17_25","073_17_25","JHN","17","25","25","אבי הצדיק הן העולם לא ידעך ואני ידעתיך ואלה הכירו כי אתה שלחתני׃ ");
INSERT INTO heb_vpl VALUES ("JN17_26","073_17_26","JHN","17","26","26","ואני הודעתים את שמך ואוסיף להודיעם למען תהיה בם האהבה אשר אהבתני ואני אהיה בהם׃ ");
INSERT INTO heb_vpl VALUES ("JN18_1","073_18_1","JHN","18","1","1","ויהי ככלות ישוע לדבר את הדברים האלה ויצא החוצה עם תלמידיו מעבר לנחל קדרון ושם גן ויבא בו הוא ותלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("JN18_2","073_18_2","JHN","18","2","2","וגם יהודה מוסרו ידע את המקום כי פעמים רבות נועד שמה ישוע עם תלמידיו׃ ");
INSERT INTO heb_vpl VALUES ("JN18_3","073_18_3","JHN","18","3","3","ויקח יהודה את הגדוד ומשרתים מאת הכהנים הגדולים והפרושים ויבא שמה בנרות ובלפידים ובכלי נשק׃ ");
INSERT INTO heb_vpl VALUES ("JN18_4","073_18_4","JHN","18","4","4","וישוע ידע את כל אשר יבא עליו ויצא ויאמר אליהם את מי תבקשו׃ ");
INSERT INTO heb_vpl VALUES ("JN18_5","073_18_5","JHN","18","5","5","ויענו ויאמרו את ישוע הנצרי ויאמר אליהם ישוע אני הוא וגם יהודה מוסרו עמד אצלם׃ ");
INSERT INTO heb_vpl VALUES ("JN18_6","073_18_6","JHN","18","6","6","ויהי בדבר ישוע אליהם אני הוא ויסגו אחור ויפלו ארצה׃ ");
INSERT INTO heb_vpl VALUES ("JN18_7","073_18_7","JHN","18","7","7","ויסף וישאל אתם את מי תבקשו ויאמרו את ישוע הנצרי׃ ");
INSERT INTO heb_vpl VALUES ("JN18_8","073_18_8","JHN","18","8","8","ויען ישוע הלא אמרתי לכם אני הוא לכן אם אתי תבקשו הניחו לאלה וילכו׃ ");
INSERT INTO heb_vpl VALUES ("JN18_9","073_18_9","JHN","18","9","9","למלאת הדבר אשר אמר מאלה אשר נתת לי לא אבד לי אף אחד׃ ");
INSERT INTO heb_vpl VALUES ("JN18_10","073_18_10","JHN","18","10","10","ולשמעון פטרוס חרב וישלפה ויך את עבד הכהן הגדול ויקצץ את אזנו הימנית ושם העבד מלכוס׃ ");
INSERT INTO heb_vpl VALUES ("JN18_11","073_18_11","JHN","18","11","11","ויאמר ישוע אל פטרוס השב חרבך אל נדנה הכי לא אשתה את הכוס אשר נתן לי אבי׃ ");
INSERT INTO heb_vpl VALUES ("JN18_12","073_18_12","JHN","18","12","12","אז תפשו הגדוד ושר האלף ומשרתי היהודים את ישוע ויאסרהו׃ ");
INSERT INTO heb_vpl VALUES ("JN18_13","073_18_13","JHN","18","13","13","ויוליכהו בראשונה אל חנן והוא חתן קיפא אשר שמש בכהנה גדולה בשנה ההיא׃ ");
INSERT INTO heb_vpl VALUES ("JN18_14","073_18_14","JHN","18","14","14","הוא קיפא אשר יעץ את היהודים כי טוב אשר איש אחד יאבד בעד כל העם׃ ");
INSERT INTO heb_vpl VALUES ("JN18_15","073_18_15","JHN","18","15","15","ושמעון פטרוס ותלמיד אחר הלכו אחרי ישוע והתלמיד ההוא היה נודע לכהן הגדול ויבא עם ישוע לחצר הכהן הגדול׃ ");
INSERT INTO heb_vpl VALUES ("JN18_16","073_18_16","JHN","18","16","16","ופטרוס עמד מחוץ לפתח ויצא התלמיד האחר המידע לכהן הגדול וידבר אל השערת ויבא את פטרוס פנימה׃ ");
INSERT INTO heb_vpl VALUES ("JN18_17","073_18_17","JHN","18","17","17","ותאמר האמה השערת אל פטרוס הלא גם אתה מתלמידי האיש הזה ויאמר אינני׃ ");
INSERT INTO heb_vpl VALUES ("JN18_18","073_18_18","JHN","18","18","18","והעבדים והמשרתים בערו אש גחלים כי עת קר היתה ויעמדו שם ויתחממו וגם פטרוס עמד עמם ומתחמם׃ ");
INSERT INTO heb_vpl VALUES ("JN18_19","073_18_19","JHN","18","19","19","וישאל הכהן הגדול את ישוע על תלמידיו ועל לקחו׃ ");
INSERT INTO heb_vpl VALUES ("JN18_20","073_18_20","JHN","18","20","20","ויען אתו ישוע אנכי בגלוי דברתי אל העולם ותמיד למדתי בבית הכנסת ובבית המקדש אשר כל היהודים נקהלים שמה ולא דברתי דבר בסתר׃ ");
INSERT INTO heb_vpl VALUES ("JN18_21","073_18_21","JHN","18","21","21","ומה תשאל אתי שאל נא את השמעים מה שדברתי אליהם הנם יודעים את אשר אמרתי׃ ");
INSERT INTO heb_vpl VALUES ("JN18_22","073_18_22","JHN","18","22","22","ויהי כדברו הדברים האלה ויך אחד המשרתים העמד שמה את ישוע על הלחי ויאמר הכזאת תענה את הכהן הגדול׃ ");
INSERT INTO heb_vpl VALUES ("JN18_23","073_18_23","JHN","18","23","23","ויען אותו ישוע אם רעה דברתי תנה עד כי רעה היא ואם טוב מדוע תסטרני׃ ");
INSERT INTO heb_vpl VALUES ("JN18_24","073_18_24","JHN","18","24","24","וישלחהו חנן אסור בזקים אל קיפא הכהן הגדול׃ ");
INSERT INTO heb_vpl VALUES ("JN18_25","073_18_25","JHN","18","25","25","ושמעון פטרוס עמד ומתחמם ויאמרו אליו הלא גם אתה מתלמידיו ויכחש ויאמר אינני׃ ");
INSERT INTO heb_vpl VALUES ("JN18_26","073_18_26","JHN","18","26","26","ויאמר איש מעבדי הכהן הגדול והוא מודע לאשר קצץ פטרוס את אזנו הלא ראיתיך עמו בתוך הגן׃ ");
INSERT INTO heb_vpl VALUES ("JN18_27","073_18_27","JHN","18","27","27","ויסף פטרוס לכחש ופתאם קרא התרנגול׃ ");
INSERT INTO heb_vpl VALUES ("JN18_28","073_18_28","JHN","18","28","28","ויוליכו את ישוע מבית קיפא אל בית המשפט ויהי בבקר השכם והמה לא נכנסו אל בית המשפט למען אשר לא יטמאו כי אם יאכלו את הפסח׃ ");
INSERT INTO heb_vpl VALUES ("JN18_29","073_18_29","JHN","18","29","29","ויצא פילטוס אליהם ויאמר על מה תאשימו את האיש הזה׃ ");
INSERT INTO heb_vpl VALUES ("JN18_30","073_18_30","JHN","18","30","30","ויענו ויאמרו אליו לולא היה זה עשה רע כי עתה לא הסגרנהו אליך׃ ");
INSERT INTO heb_vpl VALUES ("JN18_31","073_18_31","JHN","18","31","31","ויאמר אליהם פילטוס קחהו אתם עמכם ועשו משפטו כתורתכם ויאמרו אליו היהודים אין לנו רשיון להמית איש׃ ");
INSERT INTO heb_vpl VALUES ("JN18_32","073_18_32","JHN","18","32","32","למלאת דבר ישוע אשר דבר לרמז אי זה מות עתיד הוא למות׃ ");
INSERT INTO heb_vpl VALUES ("JN18_33","073_18_33","JHN","18","33","33","וישב פילטוס אל בית המשפט ויקרא אל ישוע ויאמר אליו האתה הוא מלך היהודים׃ ");
INSERT INTO heb_vpl VALUES ("JN18_34","073_18_34","JHN","18","34","34","ויען אתו ישוע המלבך תדבר זאת או אחרים הגידו לך עלי׃ ");
INSERT INTO heb_vpl VALUES ("JN18_35","073_18_35","JHN","18","35","35","ויען פילטוס האף אנכי יהודי הלא עמך וראשי הכהנים הסגירוך אלי מה עשית׃ ");
INSERT INTO heb_vpl VALUES ("JN18_36","073_18_36","JHN","18","36","36","ויען ישוע מלכותי איננה מן העולם הזה אם היתה מלכותי מן העולם הזה כי אז נלחמו לי משרתי לבלתי המסר ביד היהודים ועתה מלכותי איננה מפה׃ ");
INSERT INTO heb_vpl VALUES ("JN18_37","073_18_37","JHN","18","37","37","ויאמר אליו פילטוס אם כן אפוא מלך אתה ויען ישוע אתה אמרת כי מלך אנכי לזה נולדתי ולזה באתי בעולם להעיד לאמת כל אשר הוא מן האמת ישמע בקולי׃ ");
INSERT INTO heb_vpl VALUES ("JN18_38","073_18_38","JHN","18","38","38","ויאמר אליו פילטוס מה היא האמת ואחרי דברו זאת יצא שנית אל היהודים ויאמר אליהם אני לא מצאתי בו כל עון׃ ");
INSERT INTO heb_vpl VALUES ("JN18_39","073_18_39","JHN","18","39","39","הן מנהג הוא בכם כי אשלח לכם איש אחד חפשי בפסח היש את נפשכם כי אשלח לכם את מלך היהודים׃ ");
INSERT INTO heb_vpl VALUES ("JN18_40","073_18_40","JHN","18","40","40","ויוסיפו ויצעקו לאמר לא את האיש הזה אלא את בר אבא ובר אבא היה מרצח׃ ");
INSERT INTO heb_vpl VALUES ("JN19_1","073_19_1","JHN","19","1","1","אז לקח פילטוס את ישוע וייסרהו בשוטים׃ ");
INSERT INTO heb_vpl VALUES ("JN19_2","073_19_2","JHN","19","2","2","וישרגו אנשי הצבא עטרת קצים וישימו אתו על ראשו ויעטהו לבוש ארגמן׃ ");
INSERT INTO heb_vpl VALUES ("JN19_3","073_19_3","JHN","19","3","3","ויאמרו שלום לך מלך היהודים ויכהו על הלחי׃ ");
INSERT INTO heb_vpl VALUES ("JN19_4","073_19_4","JHN","19","4","4","ויצא פילטוס עוד החוצה ויאמר אליהם הנני מוציא אתו אליכם למען תדעו כי לא מצאתי בו כל עון׃ ");
INSERT INTO heb_vpl VALUES ("JN19_5","073_19_5","JHN","19","5","5","וישוע יצא החוץ ועליו עטרת הקצים ולבוש הארגמן ויאמר אליהם פילטוס הנה האדם׃ ");
INSERT INTO heb_vpl VALUES ("JN19_6","073_19_6","JHN","19","6","6","ויהי כאשר ראהו הכהנים הגדולים והמשרתים ויצעקו לאמר הצלב הצלב ויאמר אליהם פילטוס קחהו אתם והצליבהו כי אנכי לא מצאתי בו אשמה׃ ");
INSERT INTO heb_vpl VALUES ("JN19_7","073_19_7","JHN","19","7","7","ויענו היהודים תורה יש לנו ועל פי תורתנו חיב מות הוא כי עשה עצמו לבן אלהים׃ ");
INSERT INTO heb_vpl VALUES ("JN19_8","073_19_8","JHN","19","8","8","ויהי כשמע פילטוס את הדבר הזה ויאסף לרא עוד׃ ");
INSERT INTO heb_vpl VALUES ("JN19_9","073_19_9","JHN","19","9","9","וישב ויבא אל בית המשפט ויאמר אל ישוע מאין אתה ולא השיבו ישוע דבר׃ ");
INSERT INTO heb_vpl VALUES ("JN19_10","073_19_10","JHN","19","10","10","ויאמר אליו פילטוס אלי לא תדבר הלא ידעת כי יש לאל ידי לצלבך ויש לאל ידי לשלחך׃ ");
INSERT INTO heb_vpl VALUES ("JN19_11","073_19_11","JHN","19","11","11","ויען ישוע לא היתה לך רשות עלי לולא נתן לך מלמעלה לכן עון המסגיר אתי אליך גדול מעונך׃ ");
INSERT INTO heb_vpl VALUES ("JN19_12","073_19_12","JHN","19","12","12","אז יבקש פילטוס לשלחו והיהודים צעקו ויאמרו אם תשלח את זה אינך אהב לקיסר כי כל המתנשא להיות מלך מרד הוא בקיסר׃ ");
INSERT INTO heb_vpl VALUES ("JN19_13","073_19_13","JHN","19","13","13","ויהי כשמע פילטוס את הדבר הזה הוציא את ישוע החוצה וישב על כסא המשפט במקום הנקרא בשם רצפה ובלשונם גבתא׃ ");
INSERT INTO heb_vpl VALUES ("JN19_14","073_19_14","JHN","19","14","14","ואז היתה הכנת הפסח והשעה כשעה הששית ויאמר אל היהודים הנה מלככם והם צעקו טול טול צלב אתו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_15","073_19_15","JHN","19","15","15","ויאמר אליהם פילטוס הצלב אצלב את מלככם ויענו ראשי הכהנים אין לנו מלך כי אם הקיסר׃ ");
INSERT INTO heb_vpl VALUES ("JN19_16","073_19_16","JHN","19","16","16","אז מסרו אליהם להצליבו ויקחו את ישוע ויוליכהו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_17","073_19_17","JHN","19","17","17","וישא את צלבו ויצא אל המקום הנקרא מקום הגלגלת ובלשונם גלגלתא׃ ");
INSERT INTO heb_vpl VALUES ("JN19_18","073_19_18","JHN","19","18","18","ויצלבו אתו שמה ושני אנשים אחרים עמו מזה אחד ומזה אחד וישוע בתוך׃ ");
INSERT INTO heb_vpl VALUES ("JN19_19","073_19_19","JHN","19","19","19","ופילטוס כתב על לוח וישם על הצלב וזה מכתבו ישוע הנצרי מלך היהודים׃ ");
INSERT INTO heb_vpl VALUES ("JN19_20","073_19_20","JHN","19","20","20","ויהודים רבים קראו את המכתב הזה כי המקום אשר נצלב שם ישוע היה קרוב אל העיר והמכתב היה בלשון עבר יון ורומי׃ ");
INSERT INTO heb_vpl VALUES ("JN19_21","073_19_21","JHN","19","21","21","ויאמרו ראשי כהני היהודים אל פילטוס אל נא תכתב מלך היהודים כי אם אשר אמר אני מלך היהודים׃ ");
INSERT INTO heb_vpl VALUES ("JN19_22","073_19_22","JHN","19","22","22","ויען פילטוס ויאמר את אשר כתבתי כתבתי׃ ");
INSERT INTO heb_vpl VALUES ("JN19_23","073_19_23","JHN","19","23","23","ויהי כאשר צלבו אנשי הצבא את ישוע ויקחו את בגדיו ויחלקום לארבעה חלקים לאיש איש חלק אחד וגם את כתנתו והכתנת לא היתה תפורה כי אם מעשה ארג מלמעלה ועד קצה׃ ");
INSERT INTO heb_vpl VALUES ("JN19_24","073_19_24","JHN","19","24","24","ויאמרו איש אל אחיו אל נא נקרעה לקרעים אך נפיל עליה גורל למי תהיה למלאת דבר הכתוב יחלקו בגדי להם ועל לבושי יפילו גורל ויעשו כן אנשי הצבא׃ ");
INSERT INTO heb_vpl VALUES ("JN19_25","073_19_25","JHN","19","25","25","ועל יד צלב ישוע עמדו אמו ואחות אמו מרים אשת קלופס ומרים המגדלית׃ ");
INSERT INTO heb_vpl VALUES ("JN19_26","073_19_26","JHN","19","26","26","וירא ישוע את אמו ואת תלמידו אשר אהב עמדים אצלו ויאמר אל אמו אשה הנה זה בנך׃ ");
INSERT INTO heb_vpl VALUES ("JN19_27","073_19_27","JHN","19","27","27","ואחר אמר אל תלמידו הנה זאת אמך ומן השעה ההיא אסף אתה התלמיד אל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_28","073_19_28","JHN","19","28","28","ויהי מאחרי כן כאשר ידע ישוע כי עתה זה כלה הכל למען ימלא הכתוב כלו אמר צמאתי׃ ");
INSERT INTO heb_vpl VALUES ("JN19_29","073_19_29","JHN","19","29","29","ושם כלי מלא חמץ ויטבלו ספוג בחמץ וישימהו על אזוב ויקריבהו אל פיו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_30","073_19_30","JHN","19","30","30","ויקח ישוע את החמץ ויאמר כלה ויט את ראשו ויפקד את רוחו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_31","073_19_31","JHN","19","31","31","ולמען לא תשארנה הגויות על הצלב ביום השבת כי ערב שבת היה וגדול יום השבת ההוא שאלו היהודים מן פילטוס לשבר את שוקיהם ולהוריד אתם׃ ");
INSERT INTO heb_vpl VALUES ("JN19_32","073_19_32","JHN","19","32","32","ויבאו אנשי הצבא וישברו את שוקי הראשון והשני הנצלבים עמו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_33","073_19_33","JHN","19","33","33","ויבאו אל ישוע ובראתם כי כבר מת לא שברו את שוקיו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_34","073_19_34","JHN","19","34","34","אך אחד מאנשי הצבא דקר בחנית את צדו וכרגע יצא דם ומים׃ ");
INSERT INTO heb_vpl VALUES ("JN19_35","073_19_35","JHN","19","35","35","והראה זאת העיד ועדותו נאמנה והוא יודע כי האמת יגיד למען גם אתם תאמינו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_36","073_19_36","JHN","19","36","36","כי כל זאת היתה למלאת הכתוב ועצם לא תשברו בו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_37","073_19_37","JHN","19","37","37","ועוד כתוב אחר אמר והביט אליו את אשר דקרו׃ ");
INSERT INTO heb_vpl VALUES ("JN19_38","073_19_38","JHN","19","38","38","ויהי אחרי כן בא יוסף הרמתי והוא תלמיד ישוע אך בסתר מפני היהודים וישאל מאת פילטוס אשר יתנהו לשאת את גופת ישוע וינח לו פילטוס ויבא וישא את גופת ישוע׃ ");
INSERT INTO heb_vpl VALUES ("JN19_39","073_19_39","JHN","19","39","39","ויבא גם נקדימון אשר בא לפנים בלילה אל ישוע ויבא ערוב מר ואהלות כמאה ליטרין׃ ");
INSERT INTO heb_vpl VALUES ("JN19_40","073_19_40","JHN","19","40","40","ויקחו את גופת ישוע ויחתלוה בתכריכין עם הבשמים כאשר נהגים היהודים לקבר את מתיהם׃ ");
INSERT INTO heb_vpl VALUES ("JN19_41","073_19_41","JHN","19","41","41","ובמקום אשר נצלב שם היה גן ובגן קבר חדש אשר לא הושם בו איש עד עתה׃ ");
INSERT INTO heb_vpl VALUES ("JN19_42","073_19_42","JHN","19","42","42","שם שמו את ישוע כי ערב שבת היה ליהודים והקבר קרוב׃ ");
INSERT INTO heb_vpl VALUES ("JN20_1","073_20_1","JHN","20","1","1","ויהי באחד בשבת לפנות הבקר בעוד חשך ותבא מרים המגדלית אל הקבר ותרא את האבן מוסרה מעל הקבר׃ ");
INSERT INTO heb_vpl VALUES ("JN20_2","073_20_2","JHN","20","2","2","ותרץ ותבא אל שמעון פטרוס ואל התלמיד האחר אשר חשק בו ישוע ותאמר אליהם הנה נשאו את האדון מקברו ולא ידענו איפה הניחהו׃ ");
INSERT INTO heb_vpl VALUES ("JN20_3","073_20_3","JHN","20","3","3","ויצא פטרוס והתלמיד האחר וילכו אל הקבר׃ ");
INSERT INTO heb_vpl VALUES ("JN20_4","073_20_4","JHN","20","4","4","וירוצו שניהם יחדו וימהר התלמיד האחר לרוץ ויעבר את פטרוס ויבא ראשונה אל הקבר׃ ");
INSERT INTO heb_vpl VALUES ("JN20_5","073_20_5","JHN","20","5","5","וישקף אל תוכו וירא את התכריכין מנחים אך לא בא פנימה׃ ");
INSERT INTO heb_vpl VALUES ("JN20_6","073_20_6","JHN","20","6","6","ויבא שמעון פטרוס אחריו והוא נכנס אל הקבר וירא את התכריכין מנחים׃ ");
INSERT INTO heb_vpl VALUES ("JN20_7","073_20_7","JHN","20","7","7","והסודר אשר היתה על ראשו איננה מנחת אצל התכריכין כי אם מקפלת לבדה במקומה׃ ");
INSERT INTO heb_vpl VALUES ("JN20_8","073_20_8","JHN","20","8","8","ויבא שמה גם התלמיד האחר אשר בא ראשונה אל הקבר וירא ויאמן׃ ");
INSERT INTO heb_vpl VALUES ("JN20_9","073_20_9","JHN","20","9","9","כי לא הבינו עד עתה את הכתוב אשר קום יקום מעם המתים׃ ");
INSERT INTO heb_vpl VALUES ("JN20_10","073_20_10","JHN","20","10","10","וישובו התלמידים וילכו אל ביתם׃ ");
INSERT INTO heb_vpl VALUES ("JN20_11","073_20_11","JHN","20","11","11","ומרים עמדה בוכיה מחוץ לקבר ויהי בבכותה ותשקף אל תוך הקבר׃ ");
INSERT INTO heb_vpl VALUES ("JN20_12","073_20_12","JHN","20","12","12","ותרא שני מלאכים לבושי לבנים ישבים במקום אשר שמו שם את גופת ישוע אחד מראשותיו ואחד מרגלותיו׃ ");
INSERT INTO heb_vpl VALUES ("JN20_13","073_20_13","JHN","20","13","13","ויאמרו אליה אשה למה תבכי ותאמר אליהם כי נשאו מזה את אדני ולא ידעתי איפה הניחהו׃ ");
INSERT INTO heb_vpl VALUES ("JN20_14","073_20_14","JHN","20","14","14","ויהי בדברה זאת ותפן אחריה ותרא את ישוע עמד ולא ידעה כי הוא ישוע׃ ");
INSERT INTO heb_vpl VALUES ("JN20_15","073_20_15","JHN","20","15","15","ויאמר אליה ישוע אשה למה תבכי את מי תבקשי והיא חשבה כי הוא שמר הגן ותאמר אליו אדני אם אתה נשאת אתו מזה הגידה נא לי איפה הנחתו ולקחתיו משם׃ ");
INSERT INTO heb_vpl VALUES ("JN20_16","073_20_16","JHN","20","16","16","ויאמר אליה ישוע מרים ותפן ותאמר אליו רבוני הוא מורה׃ ");
INSERT INTO heb_vpl VALUES ("JN20_17","073_20_17","JHN","20","17","17","ויאמר אליה ישוע אל תגעי בי כי עוד לא עליתי אל אבי אך לכי נא אל אחי ואמרי אליהם אני עלה אל אבי ואביכם ואל אלהי ואלהיכם׃ ");
INSERT INTO heb_vpl VALUES ("JN20_18","073_20_18","JHN","20","18","18","ותבא מרים המגדלית ותספר אל התלמידים כי ראתה את האדון וכזאת דבר אליה׃ ");
INSERT INTO heb_vpl VALUES ("JN20_19","073_20_19","JHN","20","19","19","ויהי לעת ערב ביום ההוא והוא אחד בשבת כאשר נסגרו דלתות הבית אשר נקבצו שם התלמידים מיראת היהודים ויבא ישוע ויעמד ביניהם ויאמר אליהם שלום לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN20_20","073_20_20","JHN","20","20","20","ובדברו זאת הראה אתם את ידיו ואת צדו וישמחו התלמידים בראותם את האדון׃ ");
INSERT INTO heb_vpl VALUES ("JN20_21","073_20_21","JHN","20","21","21","ויסף ישוע לדבר אליהם שלום לכם כאשר שלח אתי האב כן אנכי שלח אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JN20_22","073_20_22","JHN","20","22","22","ויהי בדברו זאת ויפח בהם ויאמר אליהם קחו לכם את רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("JN20_23","073_20_23","JHN","20","23","23","והיה כל אשר תסלחו את חטאתם ונסלח להם ואשר תאשימו יאשמו׃ ");
INSERT INTO heb_vpl VALUES ("JN20_24","073_20_24","JHN","20","24","24","ותומא אחד משנים העשר הנקרא דידומוס לא היה בתוכם כבוא ישוע׃ ");
INSERT INTO heb_vpl VALUES ("JN20_25","073_20_25","JHN","20","25","25","ויגידו לו התלמידים הנשארים ראה ראינו את האדון ויאמר אליהם אם לא אראה בידיו את רשם המסמרות ואשים את אצבעתי במקום המסמרות ואשים את ידי בצדו לא אאמין׃ ");
INSERT INTO heb_vpl VALUES ("JN20_26","073_20_26","JHN","20","26","26","ויהי מקצה שמונת ימים ותלמידיו שנית פנימה ותומא עמהם ויבא ישוע והדלתות מסגרות ויעמד ביניהם ויאמר שלום לכם׃ ");
INSERT INTO heb_vpl VALUES ("JN20_27","073_20_27","JHN","20","27","27","ואחר אמר אל תומא שלח אצבעך הנה וראה את ידי ושלח את ידך הנה ושים בצדי ואל תהי חסר אמונה כי אם מאמין׃ ");
INSERT INTO heb_vpl VALUES ("JN20_28","073_20_28","JHN","20","28","28","ויען תומא ויאמר אליו אדני ואלהי׃ ");
INSERT INTO heb_vpl VALUES ("JN20_29","073_20_29","JHN","20","29","29","ויאמר אליו ישוע יען ראית אתי האמנת אשרי המאמינים ואינם ראים׃ ");
INSERT INTO heb_vpl VALUES ("JN20_30","073_20_30","JHN","20","30","30","והנה גם אתות אחרים רבים עשה ישוע לעיני תלמידיו אשר לא נכתבו בספר הזה׃ ");
INSERT INTO heb_vpl VALUES ("JN20_31","073_20_31","JHN","20","31","31","אך אלה נכתבו למען תאמינו כי ישוע הוא המשיח בן אלהים ולמען יהיו לכם המאמינים חיי עולם בשמו׃ ");
INSERT INTO heb_vpl VALUES ("JN21_1","073_21_1","JHN","21","1","1","ויהי אחרי כן ויסף ישוע הגלות אל תלמידיו על ים טיבריה וכה נגלה אליהם׃ ");
INSERT INTO heb_vpl VALUES ("JN21_2","073_21_2","JHN","21","2","2","שמעון פטרוס ותומא הנקרא דידומוס ונתנאל מקנה אשר בארץ הגליל ובני זבדי ועוד שנים אחרים מתלמידיו ישבו יחדו׃ ");
INSERT INTO heb_vpl VALUES ("JN21_3","073_21_3","JHN","21","3","3","ויאמר אליהם שמעון פטרוס הנני הלך לדיג ויאמרו אליו גם אנחנו נלך עמך ויצאו וימהרו לרדת אל האניה ובלילה ההוא לא אחזו מאומה׃ ");
INSERT INTO heb_vpl VALUES ("JN21_4","073_21_4","JHN","21","4","4","הבקר אור וישוע עמד על שפת הים ולא ידעו התלמידים כי ישוע הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN21_5","073_21_5","JHN","21","5","5","ויאמר אליהם ישוע בני היש לכם אכל מאומה ויענו אתו אין׃ ");
INSERT INTO heb_vpl VALUES ("JN21_6","073_21_6","JHN","21","6","6","ויאמר להם השליכו המכמרת מימין לאניה ותמצאו וישליכו ולא יכלו עוד למשך אתה מרב הדגים׃ ");
INSERT INTO heb_vpl VALUES ("JN21_7","073_21_7","JHN","21","7","7","ויאמר התלמיד ההוא אשר ישוע אהבו אל פטרוס זה הוא האדון ויהי כשמע שמעון פטרוס כי הוא האדון ויחגר את מעילו כי עירום היה ויתנפל אל הים׃ ");
INSERT INTO heb_vpl VALUES ("JN21_8","073_21_8","JHN","21","8","8","והתלמידים הנשארים באו בספינה כי לא הרחיקו מן היבשה כי אם כמאתים אמה וימשכו את המכמרת עם הדגים׃ ");
INSERT INTO heb_vpl VALUES ("JN21_9","073_21_9","JHN","21","9","9","ויהי כצאתם אל היבשה ויראו שם גחלי אש ערוכים ודגים עליהם ולחם לאכל׃ ");
INSERT INTO heb_vpl VALUES ("JN21_10","073_21_10","JHN","21","10","10","ויאמר אליהם ישוע הביאו הלם מן הדגים אשר אחזתם עתה׃ ");
INSERT INTO heb_vpl VALUES ("JN21_11","073_21_11","JHN","21","11","11","ויעל שמעון פטרוס וימשך את המכמרת אל היבשה והיא מלאה דגים גדולים מאה וחמשים ושלשה ולא נקרעה המכמרת אף כי רבים היו׃ ");
INSERT INTO heb_vpl VALUES ("JN21_12","073_21_12","JHN","21","12","12","ויאמר אליהם ישוע באו ברו לחם ואין גם אחד בתלמידים אשר מלאו לבו לשאל אתו מי אתה כי ידעו אשר הוא האדון׃ ");
INSERT INTO heb_vpl VALUES ("JN21_13","073_21_13","JHN","21","13","13","ויבא ישוע ויקח את הלחם ויתן להם וגם את הדגים׃ ");
INSERT INTO heb_vpl VALUES ("JN21_14","073_21_14","JHN","21","14","14","וזאת היא הפעם השלישית אשר נגלה ישוע אל תלמידיו אחרי קומו מעם המתים׃ ");
INSERT INTO heb_vpl VALUES ("JN21_15","073_21_15","JHN","21","15","15","ויהי אחרי אכלם אמר ישוע אל שמעון פטרוס שמעון בן יונה התאהב אתי יותר מאלה ויאמר אליו כן אדני אתה ידעת כי אהבתיך ויאמר אליו רעה את טלאי׃ ");
INSERT INTO heb_vpl VALUES ("JN21_16","073_21_16","JHN","21","16","16","ויאמר אליו עוד הפעם שמעון בן יונה התאהב אתי ויאמר אליו כן אדני אתה ידעת כי אהבתיך ויאמר אליו נהג את צאני׃ ");
INSERT INTO heb_vpl VALUES ("JN21_17","073_21_17","JHN","21","17","17","ויאמר אליו פעם שלישית שמעון בן יונה התאהב אתי ויתעצב פטרוס על כי אמר אליו בשלישית התאהב אתי ויאמר אליו אדני את כל אתה יודע וידעת כי אהבתיך ויאמר אליו ישוע רעה את צאני׃ ");
INSERT INTO heb_vpl VALUES ("JN21_18","073_21_18","JHN","21","18","18","אמן אמן אני אמר לך בהיותך צעיר לימים אתה חגרת את עצמך ותלך אל אשר חפצת והיה כאשר תזקן ופרשת כפיך ואחר יחגרך ונשאך אל אשר לא תחפץ׃ ");
INSERT INTO heb_vpl VALUES ("JN21_19","073_21_19","JHN","21","19","19","וכל זאת דבר לרמז על המיתה אשר יכבד בה את האלהים ויהי ככלותו לדבר ויאמר אליו לך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("JN21_20","073_21_20","JHN","21","20","20","ויפן פטרוס וירא את התלמיד אשר ישוע אהבו הלך אחריהם הוא הנפל על לבו בעת הסעודה וגם שאל אדני מי הוא זה אשר ימסרך׃ ");
INSERT INTO heb_vpl VALUES ("JN21_21","073_21_21","JHN","21","21","21","ויהי בראות אתו פטרוס ויאמר אל ישוע אדני וזה מה הוא׃ ");
INSERT INTO heb_vpl VALUES ("JN21_22","073_21_22","JHN","21","22","22","ויאמר אליו ישוע אם חפצי כי ישאר עד באי מה לך ולזאת אתה לך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("JN21_23","073_21_23","JHN","21","23","23","על כן יצא הדבר הזה בין האחים כי התלמיד ההוא לא ימות וישוע לא אמר לו כי לא ימות אך אמר אם חפצי כי ישאר עד באי מה זה לך׃ ");
INSERT INTO heb_vpl VALUES ("JN21_24","073_21_24","JHN","21","24","24","זה הוא התלמיד המעיד על אלה ואשר כתב כל זאת וידענו כי עדותו נאמנה׃ ");
INSERT INTO heb_vpl VALUES ("JN21_25","073_21_25","JHN","21","25","25","ויש עוד מעשים רבים אחרים אשר עשה ישוע ואם יכתבו כלם לאחד אחד אחשבה כי גם העולם כלו לא יכיל את הספרים אשר יכתבו אמן׃ ");
INSERT INTO heb_vpl VALUES ("AC1_1","074_1_1","ACT","1","1","1","הן המאמר הראשון תאופילוס עשיתיהו על כל אשר החל ישוע לעשות וללמד׃ ");
INSERT INTO heb_vpl VALUES ("AC1_2","074_1_2","ACT","1","2","2","עד היום אשר לקח למרום אחרי צותו ברוח הקדש את השליחים אשר בחר בהם׃ ");
INSERT INTO heb_vpl VALUES ("AC1_3","074_1_3","ACT","1","3","3","ואשר גם התיצב להם חי אחרי ענותו באתות רבות בהראותו אליהם ארבעים יום וידבר על מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC1_4","074_1_4","ACT","1","4","4","ובאכלו לחם עמהם צוה אתם לבלתי סור מירושלים כי אם להוחיל להבטחת האב אשר שמעתם ממני׃ ");
INSERT INTO heb_vpl VALUES ("AC1_5","074_1_5","ACT","1","5","5","כי יוחנן הטביל במים ואתם תטבלו ברוח הקדש בקרוב אחרי הימים האלה׃ ");
INSERT INTO heb_vpl VALUES ("AC1_6","074_1_6","ACT","1","6","6","ויהי כאשר נאספו יחדו וישאלהו לאמר אדנינו המשיב אתה בעת הזאת את המלוכה לישראל׃ ");
INSERT INTO heb_vpl VALUES ("AC1_7","074_1_7","ACT","1","7","7","ויאמר אליהם לא לכם לדעת העתים והזמנים אשר יעד האב בשלטנו׃ ");
INSERT INTO heb_vpl VALUES ("AC1_8","074_1_8","ACT","1","8","8","אבל תקבלו גבורה בבוא עליכם רוח הקדש והייתם עדי בירושלים ובכל יהודה ובשמרון ועד קצה הארץ׃ ");
INSERT INTO heb_vpl VALUES ("AC1_9","074_1_9","ACT","1","9","9","ויהי כדברו זאת העלה והם ראים וישאהו ענן מנגד עיניהם׃ ");
INSERT INTO heb_vpl VALUES ("AC1_10","074_1_10","ACT","1","10","10","ויביטו אחריו השמימה בעברו והנה שני אנשים לבושי בדים נצבים עליהם׃ ");
INSERT INTO heb_vpl VALUES ("AC1_11","074_1_11","ACT","1","11","11","ויאמרו אתם אנשי הגליל מה תעמדו פה ועיניכם השמימה ישוע זה אשר לקח מאתכם השמימה כן בוא יבוא כאשר ראיתם אתו עלה השמימה׃ ");
INSERT INTO heb_vpl VALUES ("AC1_12","074_1_12","ACT","1","12","12","ויפנו וילכו ירושלימה מן ההר הנקרא הר הזיתים והוא קרוב לירושלים דרך תחום שבת׃ ");
INSERT INTO heb_vpl VALUES ("AC1_13","074_1_13","ACT","1","13","13","ויבאו העירה ויעלו אל העליה אשר היו ישבים בה פטרוס ויעקב ויוחנן ואנדרי פילפוס ותומא בר תלמי ומתי יעקב בן חלפי ושמעון הקנא ויהודה בן יעקב׃ ");
INSERT INTO heb_vpl VALUES ("AC1_14","074_1_14","ACT","1","14","14","כל אלה היו שקדים יחדו בלב אחד להתפלל ולהתחנן ועמהם הנשים ומרים אם ישוע וגם אחיו׃ ");
INSERT INTO heb_vpl VALUES ("AC1_15","074_1_15","ACT","1","15","15","ובימים האלה קם פטרוס בתוך התלמידים ומספר שמות הנקהלים יחד כמאה ועשרים ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC1_16","074_1_16","ACT","1","16","16","אנשים אחים מן הצרך היה כי ימלא הכתוב ההוא אשר דבר מקדם רוח הקדש בפי דוד על יהודה אשר היה מוליך את תפשי ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC1_17","074_1_17","ACT","1","17","17","כי היה נמנה אתנו וזכה בגורל השרות הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC1_18","074_1_18","ACT","1","18","18","והנה הוא קנה לו שדה במחיר הרשעה ויפל על פניו ארצה ויבקע בתוך וישפכו כל מעיו׃ ");
INSERT INTO heb_vpl VALUES ("AC1_19","074_1_19","ACT","1","19","19","וגם נודעה זאת לכל ישבי ירושלים ויקרא בשפתם לשדה ההוא חקל דמא הוא שדה הדם׃ ");
INSERT INTO heb_vpl VALUES ("AC1_20","074_1_20","ACT","1","20","20","כי כתוב בספר תהלים תהי טירתו נשמה ואל יהי בה ישב ופקדתו יקח אחר׃ ");
INSERT INTO heb_vpl VALUES ("AC1_21","074_1_21","ACT","1","21","21","ועל כן מן הצרך כי מן האנשים האלה אשר התהלכו אתנו כל ימי היות אדנינו ישוע יוצא ובא לפנינו׃ ");
INSERT INTO heb_vpl VALUES ("AC1_22","074_1_22","ACT","1","22","22","החל מטבילת יוחנן עד יום הלקחו מאתנו כי אחד מהם יהיה לעד עמנו על קומו מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("AC1_23","074_1_23","ACT","1","23","23","ויעמידו שנים את יוסף הנקרא בר שבא והוא מכנה יוסטוס ואת מתיה׃ ");
INSERT INTO heb_vpl VALUES ("AC1_24","074_1_24","ACT","1","24","24","ויתפללו ויאמרו אתה אדני היודע כל הלבבות הראה נא מן השנים האלה את האחד אשר בחרת בו׃ ");
INSERT INTO heb_vpl VALUES ("AC1_25","074_1_25","ACT","1","25","25","לקחת את גורל השרות הזה והשליחות אשר סר ממנה יהודה להלך אל מקומו׃ ");
INSERT INTO heb_vpl VALUES ("AC1_26","074_1_26","ACT","1","26","26","ויפילו גורלות ויפל הגורל על מתיה ויספח אל עשתי עשר השליחים׃ ");
INSERT INTO heb_vpl VALUES ("AC2_1","074_2_1","ACT","2","1","1","וביום מלאת שבעת השבעות ויתאספו כלם לב אחד׃ ");
INSERT INTO heb_vpl VALUES ("AC2_2","074_2_2","ACT","2","2","2","ויהי פתאם קול רעש מן השמים כקול רוח סערה וימלא את כל הבית אשר ישבו בו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_3","074_2_3","ACT","2","3","3","ותראינה אליהם לשנות נחלקות ומראיהן כאש ותנוחינה אחת אחת על כל אחד מהם׃ ");
INSERT INTO heb_vpl VALUES ("AC2_4","074_2_4","ACT","2","4","4","וימלאו כלם רוח הקדש ויחלו לדבר בלשנות אחרות כאשר נתנם הרוח להטיף׃ ");
INSERT INTO heb_vpl VALUES ("AC2_5","074_2_5","ACT","2","5","5","ובירושלים שכנו יהודים אנשי חסד מכל גוי וגוי אשר תחת השמים׃ ");
INSERT INTO heb_vpl VALUES ("AC2_6","074_2_6","ACT","2","6","6","ויהי בהיות קול הרעש ההוא ויקבצו עם רב ויהיו נבכים כי איש איש שמע אתם מדברים בשפת עמו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_7","074_2_7","ACT","2","7","7","וישתוממו ויתמהו ויאמרו איש אל רעהו הנה כל אלה המדברים הלא גלילים המה׃ ");
INSERT INTO heb_vpl VALUES ("AC2_8","074_2_8","ACT","2","8","8","ואיך אנחנו שמעים אתם איש כשפת ארץ מולדתנו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_9","074_2_9","ACT","2","9","9","פרתיים ומדים ועילמים וישבי ארם נהרים יהודה וקפודקיה פנטוס ואסיא׃ ");
INSERT INTO heb_vpl VALUES ("AC2_10","074_2_10","ACT","2","10","10","פרוגיא ופמפוליא מצרים וחבל לוב אשר על יד קוריני והבאים מרומי גם יהודים גם גרים׃ ");
INSERT INTO heb_vpl VALUES ("AC2_11","074_2_11","ACT","2","11","11","כרתים וערבים הנה אנחנו שמעים אתם מספרים בלשנותינו גדלות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC2_12","074_2_12","ACT","2","12","12","וישתוממו כלם ויבהלו ויאמרו איש אל אחיו מה תהיה זאת׃ ");
INSERT INTO heb_vpl VALUES ("AC2_13","074_2_13","ACT","2","13","13","ואחרים לעגו ויאמרו כי מלאי עסיס המה׃ ");
INSERT INTO heb_vpl VALUES ("AC2_14","074_2_14","ACT","2","14","14","אז יעמד פטרוס ועשתי העשר עמו וישא את קולו וידבר אליהם אנשי יהודה וישבי ירושלים כלכם זאת תודע לכם והאזינו אל דברי׃ ");
INSERT INTO heb_vpl VALUES ("AC2_15","074_2_15","ACT","2","15","15","כי אלה לא שכורים המה כאשר חשבתם כי שעה שלישית ביום עתה׃ ");
INSERT INTO heb_vpl VALUES ("AC2_16","074_2_16","ACT","2","16","16","אבל זה הוא האמור על ידי יואל הנביא׃ ");
INSERT INTO heb_vpl VALUES ("AC2_17","074_2_17","ACT","2","17","17","והיה באחרית הימים נאם אלהים אשפך את רוחי על כל בשר ונבאו בניכם ובנתיכם ובחוריכם חזינות יראו וזקניכם חלמות יחלמון׃ ");
INSERT INTO heb_vpl VALUES ("AC2_18","074_2_18","ACT","2","18","18","וגם על עבדי ועל שפחותי בימים ההמה אשפך את רוחי ונבאו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_19","074_2_19","ACT","2","19","19","ונתתי מופתים בשמים ממעל ואתות בארץ מתחת דם ואש ותימרות עשן׃ ");
INSERT INTO heb_vpl VALUES ("AC2_20","074_2_20","ACT","2","20","20","השמש יהפך לחשך והירח לדם לפני בוא יום יהוה הגדול והנורא׃ ");
INSERT INTO heb_vpl VALUES ("AC2_21","074_2_21","ACT","2","21","21","והיה כל אשר יקרא בשם יהוה ימלט׃ ");
INSERT INTO heb_vpl VALUES ("AC2_22","074_2_22","ACT","2","22","22","אנשי ישראל שמעו הדברים האלה ישוע הנצרי האיש אשר נאמן לכם מאת האלהים בגבורות ובמופתים ובאתות אשר האלהים עשה על ידו בתוככם כאשר ידעתם גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("AC2_23","074_2_23","ACT","2","23","23","אתו הנמסר על פי עצת האלהים הנחרצה וידיעתו מקום לקחתם ובידי רשעים הוקעתם והרגתם אתו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_24","074_2_24","ACT","2","24","24","והאלהים הקימו מן המתים בהתיר את חבלי המות באשר נמנע מן המות לעצר אתו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_25","074_2_25","ACT","2","25","25","כי דוד אמר עליו שויתי יהוה לנגדי תמיד כי מימיני בל אמוט׃ ");
INSERT INTO heb_vpl VALUES ("AC2_26","074_2_26","ACT","2","26","26","לכן שמח לבי ויגל כבודי אף בשרי ישכן לבטח׃ ");
INSERT INTO heb_vpl VALUES ("AC2_27","074_2_27","ACT","2","27","27","כי לא תעזב נפשי לשאול לא תתן חסידך לראות שחת׃ ");
INSERT INTO heb_vpl VALUES ("AC2_28","074_2_28","ACT","2","28","28","תודיעני ארחות חיים שבע שמחות את פניך׃ ");
INSERT INTO heb_vpl VALUES ("AC2_29","074_2_29","ACT","2","29","29","אנשים אחים הניחו לי ואדברה באזני כלכם על דוד אבינו אשר גם מת גם נקבר וקבורתו אתנו היא עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC2_30","074_2_30","ACT","2","30","30","והוא בהיותו נביא ומדעתו את השבועה אשר נשבע לו האלהים להקים את המשיח כפי הבשר מפרי חלציו להושיבו על כסאו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_31","074_2_31","ACT","2","31","31","לכן בחזותו מראש דבר על תקומת המשיח כי לא נעזבה נפשו לשאול וגם בשרו לא ראה שחת׃ ");
INSERT INTO heb_vpl VALUES ("AC2_32","074_2_32","ACT","2","32","32","את ישוע זה הקים אלהים מן המתים ואנחנו כלנו עדיו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_33","074_2_33","ACT","2","33","33","ועתה אחרי הנשאו בימין האלהים לקח מאת האב את הבטחת רוח הקדש וישפך את אשר אתם ראים ושמעים׃ ");
INSERT INTO heb_vpl VALUES ("AC2_34","074_2_34","ACT","2","34","34","כי דוד לא עלה השמימה והנה הוא אמר נאם יהוה לאדני שב לימיני׃ ");
INSERT INTO heb_vpl VALUES ("AC2_35","074_2_35","ACT","2","35","35","עד אשית איביך הדם לרגליך׃ ");
INSERT INTO heb_vpl VALUES ("AC2_36","074_2_36","ACT","2","36","36","לכן ידע נא בית ישראל כלו כי לאדון ולמשיח שמו האלהים את ישוע זה אשר צלבתם׃ ");
INSERT INTO heb_vpl VALUES ("AC2_37","074_2_37","ACT","2","37","37","ויהי כשמעם התעצבו אל לבם ויאמרו אל פטרוס ואל שאר השליחים אנשים אחים מה עלינו לעשות׃ ");
INSERT INTO heb_vpl VALUES ("AC2_38","074_2_38","ACT","2","38","38","ויאמר פטרוס אליהם שובו מדרכיכם והטבלו כל איש מכם על שם ישוע המשיח לסליחת חטאיכם וקבלתם את מתנת רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC2_39","074_2_39","ACT","2","39","39","כי לכם ההבטחה ולבניכם ולכל הרחוקים לכל אשר קרא יהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_40","074_2_40","ACT","2","40","40","ויעד עוד בהם באמרים אחרים הרבה ויזהר אתם לאמר המלטו נא מדור תהפכות הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC2_41","074_2_41","ACT","2","41","41","ויקבלו את דברו בשמחה ויטבלו וביום ההוא נוספו כשלשת אלפי נפש׃ ");
INSERT INTO heb_vpl VALUES ("AC2_42","074_2_42","ACT","2","42","42","ויהיו שקדים על תורת השליחים ועל ההתחברות ועל בציעת הלחם ועל התפלה׃ ");
INSERT INTO heb_vpl VALUES ("AC2_43","074_2_43","ACT","2","43","43","ותפל אימה על כל נפש ומופתים רבים ואתות נעשו על ידי השליחים בירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC2_44","074_2_44","ACT","2","44","44","וכל המאמינים התאחדו יחד ויהי להם הכל בשתפות׃ ");
INSERT INTO heb_vpl VALUES ("AC2_45","074_2_45","ACT","2","45","45","ואת אחזתם ואת רכושם מכרו ויחלקו אתם לכלם לאיש איש די מחסורו׃ ");
INSERT INTO heb_vpl VALUES ("AC2_46","074_2_46","ACT","2","46","46","ויום יום היו שקדים במקדש לב אחד ויבצעו את הלחם בבית בבית׃ ");
INSERT INTO heb_vpl VALUES ("AC2_47","074_2_47","ACT","2","47","47","ויאכלו מזונם בגילה ובתם לבב וישבחו את האלהים וימצאו חן בעיני כל העם והאדון הוסיף יום יום על העדה את הנושעים׃ ");
INSERT INTO heb_vpl VALUES ("AC3_1","074_3_1","ACT","3","1","1","ופטרוס ויוחנן עלים יחדו אל המקדש לעת התפלה בשעה התשיעית׃ ");
INSERT INTO heb_vpl VALUES ("AC3_2","074_3_2","ACT","3","2","2","ואיש אחד פסח מבטן אמו מובא שמה אשר יושיבהו יום יום שער המקדש הנקרא שער המהדר לשאל מתנות מאת באי המקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC3_3","074_3_3","ACT","3","3","3","ויהי כראותו את פטרוס ואת יוחנן באים אל המקדש ויבקש לקחת מאתם צדקה׃ ");
INSERT INTO heb_vpl VALUES ("AC3_4","074_3_4","ACT","3","4","4","ויסתכל בו פטרוס וגם יוחנן ויאמר אליו הביטה אלינו׃ ");
INSERT INTO heb_vpl VALUES ("AC3_5","074_3_5","ACT","3","5","5","וישם פניו אליהם בקותו לקחת מאתם דבר׃ ");
INSERT INTO heb_vpl VALUES ("AC3_6","074_3_6","ACT","3","6","6","ויאמר פטרוס כסף וזהב אין לי אבל את אשר בידי אתננו לך בשם ישוע המשיח הנצרי קום התהלך׃ ");
INSERT INTO heb_vpl VALUES ("AC3_7","074_3_7","ACT","3","7","7","ויאחז ביד ימינו ויקם אותו ויתחזקו פתאם רגליו וקרסליו׃ ");
INSERT INTO heb_vpl VALUES ("AC3_8","074_3_8","ACT","3","8","8","ויקפץ ויתהלך ויבא אתם אל המקדש מתהלך ומרקד ומשבח את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC3_9","074_3_9","ACT","3","9","9","ויראהו כל העם מתהלך ומשבח את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC3_10","074_3_10","ACT","3","10","10","ויכירו אותו כי הוא אשר היה ישב לשאל צדקה בשער המקדש המהדר וימלאו שמה ושממון על הנעשה לו׃ ");
INSERT INTO heb_vpl VALUES ("AC3_11","074_3_11","ACT","3","11","11","ויהי הוא מחזיק בפטרוס וביוחנן וירץ אליהם כל העם אל האולם הנקרא אולם של שלמה וישתוממו׃ ");
INSERT INTO heb_vpl VALUES ("AC3_12","074_3_12","ACT","3","12","12","וירא פטרוס ויען ויאמר אל העם אנשי ישראל מה אתם תמהים על זאת ומה תסתכלו בנו כאלו אנחנו בכחנו ובחסידותנו שמנו את זה מתהלך׃ ");
INSERT INTO heb_vpl VALUES ("AC3_13","074_3_13","ACT","3","13","13","אלהי אברהם אלהי יצחק ואלהי יעקב אלהי אבותינו הוא פאר את עבדו ישוע אשר אתם מסרתם אותו וכחשתם בו בפני פילטוס כשהיה דן לפטרו׃ ");
INSERT INTO heb_vpl VALUES ("AC3_14","074_3_14","ACT","3","14","14","אבל אתם כחשתם בקדוש ובצדיק ובקשתם כי יחן לכם איש רצח׃ ");
INSERT INTO heb_vpl VALUES ("AC3_15","074_3_15","ACT","3","15","15","ואת שר החיים הרגתם אשר האלהים הקימו מן המתים ואנחנו עדיו׃ ");
INSERT INTO heb_vpl VALUES ("AC3_16","074_3_16","ACT","3","16","16","ולמען אמונת שמו חזק שמו את האיש הזה אשר אתם ראים ומכירים אתו והאמונה אשר לנו על ידו היא העלתה לו את הארכה הזאת לעיני כלכם׃ ");
INSERT INTO heb_vpl VALUES ("AC3_17","074_3_17","ACT","3","17","17","ועתה אחי ידע אני כי בבלי דעת עשיתם גם אתם גם ראשיכם׃ ");
INSERT INTO heb_vpl VALUES ("AC3_18","074_3_18","ACT","3","18","18","והאלהים ככה מלא את אשר הגיד מקדם בפי כל נביאיו כי יענה המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC3_19","074_3_19","ACT","3","19","19","לכן הנחמו ושובו וימחו חטאיכם׃ ");
INSERT INTO heb_vpl VALUES ("AC3_20","074_3_20","ACT","3","20","20","למען אשר יבאו ימי רוחה מלפני יהוה וישלח את אשר בשרו לכם מקדם את ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC3_21","074_3_21","ACT","3","21","21","אשר צריך כי יקבלהו השמים עד ימי שוב כל הדברים לתקונם אשר דבר עליהם האלהים בפי נביאיו הקדושים מימי עולם׃ ");
INSERT INTO heb_vpl VALUES ("AC3_22","074_3_22","ACT","3","22","22","הן משה אמר אל אבותינו נביא יקים לכם יהוה אלהיכם מקרב אחיכם כמני אליו תשמעון ככל אשר ידבר אליכם׃ ");
INSERT INTO heb_vpl VALUES ("AC3_23","074_3_23","ACT","3","23","23","והיה כל הנפש אשר לא תשמע אל הנביא ההוא ונכרתה מעמיה׃ ");
INSERT INTO heb_vpl VALUES ("AC3_24","074_3_24","ACT","3","24","24","וגם כל הנביאים משמואל ואשר נבאו אחריו כלם הגידו מראש את הימים האלה׃ ");
INSERT INTO heb_vpl VALUES ("AC3_25","074_3_25","ACT","3","25","25","אתם בני הנביאים ובני הברית אשר כרת האלהים עם אבותינו באמרו אל אברהם ונברכו בזרעך כל משפחות האדמה׃ ");
INSERT INTO heb_vpl VALUES ("AC3_26","074_3_26","ACT","3","26","26","לכם בראשונה העמיד האלהים את עבדו ישוע וישלחהו לברך אתכם בשובכם כל איש מרע מעלליכם׃ ");
INSERT INTO heb_vpl VALUES ("AC4_1","074_4_1","ACT","4","1","1","ויהי בדברם אל העם ויקומו עליהם הכהנים ונגיד בית המקדש והצדוקים׃ ");
INSERT INTO heb_vpl VALUES ("AC4_2","074_4_2","ACT","4","2","2","כי חרה להם על אשר למדו את העם והגידו בישוע את תחית המתים׃ ");
INSERT INTO heb_vpl VALUES ("AC4_3","074_4_3","ACT","4","3","3","וישלחו בהם את ידיהם וישימום במשמר עד למחר כי כבר בא הערב׃ ");
INSERT INTO heb_vpl VALUES ("AC4_4","074_4_4","ACT","4","4","4","ורבים מהשמעים את הדבר האמינו ויהי מספר האנשים כחמשת אלפים׃ ");
INSERT INTO heb_vpl VALUES ("AC4_5","074_4_5","ACT","4","5","5","ויהי ממחרת ויקהלו שריהם ראשיהם וזקניהם וסופריהם ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC4_6","074_4_6","ACT","4","6","6","וחנן הכהן הגדול וקיפא ויוחנן ואלכסנדרוס וכל אשר ממשפחת הכהן הגדול׃ ");
INSERT INTO heb_vpl VALUES ("AC4_7","074_4_7","ACT","4","7","7","ויעמידו אתם בתוך וישאלום באי זה כח ובאי זה שם עשיתם זאת׃ ");
INSERT INTO heb_vpl VALUES ("AC4_8","074_4_8","ACT","4","8","8","וימלא פטרוס רוח הקדש ויאמר אליהם אתם ראשי העם וזקני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AC4_9","074_4_9","ACT","4","9","9","אם אנחנו נחקרים היום על הטובה אשר עשינו לאיש חולה ושאלתם במה זה נושע׃ ");
INSERT INTO heb_vpl VALUES ("AC4_10","074_4_10","ACT","4","10","10","יודע לכלכם ולכל עם ישראל כי בשם ישוע המשיח הנצרי אשר צלבתם אותו ואשר האלהים הקימו מן המתים כי בשמו עמד זה לפניכם בריא׃ ");
INSERT INTO heb_vpl VALUES ("AC4_11","074_4_11","ACT","4","11","11","והוא האבן אשר מאסתם אתם הבונים ותהי לראש פנה׃ ");
INSERT INTO heb_vpl VALUES ("AC4_12","074_4_12","ACT","4","12","12","ואין הישועה באחר ואין תחת השמים שם אחר הנתן לבני אדם אשר בו נושע׃ ");
INSERT INTO heb_vpl VALUES ("AC4_13","074_4_13","ACT","4","13","13","ויהי כאשר ראו את בטחון לב של פטרוס ויוחנן והבינו כי הדיוטים ולא בעלי חכמה המה ויתמהו עליהם ויכירום כי התהלכו עם ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC4_14","074_4_14","ACT","4","14","14","ובראותם את האיש הנרפא עמד אצלם לא מצאו לדבר נגדם דבר׃ ");
INSERT INTO heb_vpl VALUES ("AC4_15","074_4_15","ACT","4","15","15","ויצוו אתם לצאת חוצה מן הסנהדרין ויתיעצו יחדו׃ ");
INSERT INTO heb_vpl VALUES ("AC4_16","074_4_16","ACT","4","16","16","ויאמרו מה נעשה לאנשים האלה הנה אות גלוי נעשה על ידיהם וגם מפרסם לכל ישבי ירושלים ולא נוכל לכחש בו׃ ");
INSERT INTO heb_vpl VALUES ("AC4_17","074_4_17","ACT","4","17","17","אך למען לא ירבה הדבר בעם ויפרץ נזהירה אתם בגערה לבלתי דבר עוד לכל אדם בשם הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC4_18","074_4_18","ACT","4","18","18","ויקראו אתם ויצוום אשר לא ידברו דבר ולא ילמדו בשם ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC4_19","074_4_19","ACT","4","19","19","ויענו פטרוס ויוחנן ויאמרו אליהם הנכון הוא לפני האלהים שמע לכם יתר משמע לאלהים שפטו אתם׃ ");
INSERT INTO heb_vpl VALUES ("AC4_20","074_4_20","ACT","4","20","20","כי לא נוכל אנחנו לחדל מדבר את אשר ראינו ושמענו׃ ");
INSERT INTO heb_vpl VALUES ("AC4_21","074_4_21","ACT","4","21","21","ויוסיפו לגער בם ויפטרו אתם באשר לא מצאו דבר לענוש אתם מפני העם כי כלם מהללים את האלהים על הנעשה׃ ");
INSERT INTO heb_vpl VALUES ("AC4_22","074_4_22","ACT","4","22","22","כי בן ארבעים שנה ומעלה היה האיש ההוא אשר נעשה עמו אות הרפואה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("AC4_23","074_4_23","ACT","4","23","23","ואחרי הפטרם באו אל אחיהם ויספרו להם את אשר אמרו אליהם הכהנים הגדולים והזקנים׃ ");
INSERT INTO heb_vpl VALUES ("AC4_24","074_4_24","ACT","4","24","24","ויהי כאשר שמעו את זאת וישאו את קולם בלב אחד לאלהים ויאמרו אדני אתה האל העשה את השמים ואת הארץ ואת הים ואת כל אשר בם׃ ");
INSERT INTO heb_vpl VALUES ("AC4_25","074_4_25","ACT","4","25","25","אשר אמרת בפי עבדך דוד למה רגשו גוים ולאמים יהגו ריק׃ ");
INSERT INTO heb_vpl VALUES ("AC4_26","074_4_26","ACT","4","26","26","יתיצבו מלכי ארץ ורוזנים נוסדו יחד על יהוה ועל משיחו׃ ");
INSERT INTO heb_vpl VALUES ("AC4_27","074_4_27","ACT","4","27","27","כי אמנם נוסדו הורדוס ופנטיוס פילטוס עם הגוים ולאמי ישראל על ישוע עבדך הקדוש אשר משחת׃ ");
INSERT INTO heb_vpl VALUES ("AC4_28","074_4_28","ACT","4","28","28","לעשות את אשר ידך ועצתך מקדם גזרה להיות׃ ");
INSERT INTO heb_vpl VALUES ("AC4_29","074_4_29","ACT","4","29","29","ועתה אדני ראה את גערתם ותן לעבדיך לדבר את דברך בכל בטחון לבם׃ ");
INSERT INTO heb_vpl VALUES ("AC4_30","074_4_30","ACT","4","30","30","בנטתך את ידך למרפא ולתת אתות ומופתים בשם ישוע עבדך הקדוש׃ ");
INSERT INTO heb_vpl VALUES ("AC4_31","074_4_31","ACT","4","31","31","ויהי כאשר התפללו וינע המקום אשר היו נקהלים שם וימלאו כלם רוח הקדש וידברו את דבר האלהים בבטחון לבב׃ ");
INSERT INTO heb_vpl VALUES ("AC4_32","074_4_32","ACT","4","32","32","וקהל המאמינים היה להם לב אחד ונפש אחת ואין איש מהם אומר על אשר בידו לי הוא כי הכל היה להם בשתפות׃ ");
INSERT INTO heb_vpl VALUES ("AC4_33","074_4_33","ACT","4","33","33","ובגבורה גדולה יעידו השליחים על תקומת האדון ישוע וחסד גדול נמשך לכלם׃ ");
INSERT INTO heb_vpl VALUES ("AC4_34","074_4_34","ACT","4","34","34","כי לא היה בהם חסר דבר כי כל בעלי שדות ובתים מכרו אתם ויביאו את כסף מחירם׃ ");
INSERT INTO heb_vpl VALUES ("AC4_35","074_4_35","ACT","4","35","35","וישימהו לרגלי השליחים ויתן לכל איש ואיש די מחסרו׃ ");
INSERT INTO heb_vpl VALUES ("AC4_36","074_4_36","ACT","4","36","36","ויוסף אשר כנוהו השליחים בשם בר נבא פרושו בן הנחמה איש לוי אשר נולד בארץ כתים׃ ");
INSERT INTO heb_vpl VALUES ("AC4_37","074_4_37","ACT","4","37","37","גם לו היה שדה וימכרהו ויבא את הכסף וישימהו לרגלי השליחים׃ ");
INSERT INTO heb_vpl VALUES ("AC5_1","074_5_1","ACT","5","1","1","ואיש אחד ושמו חנניה עם אשתו שפירה מכר את אחזתו׃ ");
INSERT INTO heb_vpl VALUES ("AC5_2","074_5_2","ACT","5","2","2","ויקח מן המחיר ויסתירהו ואשתו ידעת גם היא וחלק אחד הביא וישם לרגלי השליחים׃ ");
INSERT INTO heb_vpl VALUES ("AC5_3","074_5_3","ACT","5","3","3","ויאמר פטרוס חנניה למה זה מלא השטן את לבבך לשקר ברוח הקדש ולהסתיר ממחיר השדה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_4","074_5_4","ACT","5","4","4","הלא שלך היה טרם המכרו וגם אחרי נמכר היה בידך ולמה שמת על לבבך הדבר הזה לא שקרת בבני אדם כי אם באלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC5_5","074_5_5","ACT","5","5","5","וכשמע חנניה את הדברים האלה נפל ארצה ויגוע ותהי יראה גדולה על כל השמעים׃ ");
INSERT INTO heb_vpl VALUES ("AC5_6","074_5_6","ACT","5","6","6","ויקומו הצעירים ויאספו אתו וישאהו החוצה ויקברהו׃ ");
INSERT INTO heb_vpl VALUES ("AC5_7","074_5_7","ACT","5","7","7","ויהי כמשלש שעות ותבא אשתו והיא לא ידעה את הנעשה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_8","074_5_8","ACT","5","8","8","ויען פטרוס ויאמר אליה אמרי לי הבמחיר הזה מכרתם את השדה ותאמר כן במחיר הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_9","074_5_9","ACT","5","9","9","ויאמר פטרוס אליה למה זה נועדתם לנסות את רוח יהוה הנה בפתח רגלי המקברים את אישך ונשאו אתך החוצה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_10","074_5_10","ACT","5","10","10","ותפל פתאם לרגליו ותגוע והבחורים באו והנה מתה וישאוה החוצה ויקברוה אצל אישה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_11","074_5_11","ACT","5","11","11","ותהי יראה גדולה על כל הקהל ועל כל השמעים את אלה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_12","074_5_12","ACT","5","12","12","ויעשו אתות ומופתים רבים בקרב העם על ידי השליחים וכלם נאספו לב אחד באולם של שלמה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_13","074_5_13","ACT","5","13","13","ומן האחרים אין איש אשר מלאו לבו לחלות עליהם אך הוקיר אתם העם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_14","074_5_14","ACT","5","14","14","אבל נספחו עוד יתר מאמינים אל האדון אנשים ונשים הרבה מאד׃ ");
INSERT INTO heb_vpl VALUES ("AC5_15","074_5_15","ACT","5","15","15","עד כי נשאו את החולים אל הרחבות וישימום על מטות ומשכבות למען אשר ילך פטרוס ונפל אך צלו על אחד מהם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_16","074_5_16","ACT","5","16","16","וגם המון עם הערים אשר מסביב נקבצו ירושלים מביאים את החולים ואת הנלחצים מרוחות טמאות וירפאו כלם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_17","074_5_17","ACT","5","17","17","ויקם הכהן הגדול וכל אשר אתו והם אנשי כת הצדוקים וימלאו קנאה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_18","074_5_18","ACT","5","18","18","וישלחו יד בשליחים ויתנום במשמר העיר׃ ");
INSERT INTO heb_vpl VALUES ("AC5_19","074_5_19","ACT","5","19","19","ויהי בלילה ויפתח מלאך יהוה את דלתי בית הכלא ויוציאם לאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC5_20","074_5_20","ACT","5","20","20","לכו והתיצבו במקדש ודברו אל העם את כל דברי החיים האלה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_21","074_5_21","ACT","5","21","21","והם כשמעם את זאת באו אל המקדש בהית הבקר וילמדו שם ויבא הכהן הגדול ואשר אתו ויקראו אל הסנהדרין ואל כל זקני בני ישראל וישלחו אל בית האסורים להביא אתם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_22","074_5_22","ACT","5","22","22","וילכו המשרתים ולא מצאום בבית הכלא וישובו ויגידו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC5_23","074_5_23","ACT","5","23","23","את בית האסורים מצאנו סגור ומסגר והשמרים עמדים על הדלתות וכאשר פתחנו לא נמצא בו אדם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_24","074_5_24","ACT","5","24","24","ויהי כשמע הכהן ונגיד המקדש וראשי הכהנים את הדברים האלה ויבהלו עליהם ויאמרו איך יפל הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_25","074_5_25","ACT","5","25","25","ואיש אחד בא ויגד להם לאמר הנה האנשים אשר שמתם במשמר עמדים הם במקדש ומלמדים את העם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_26","074_5_26","ACT","5","26","26","וילך שמה הנגיד עם משרתיו ויקחם אך לא בחזקה כי יראו מפני העם פן יסקלו׃ ");
INSERT INTO heb_vpl VALUES ("AC5_27","074_5_27","ACT","5","27","27","ויביאו אתם ויעמידום לפני הסנהדרין וישאלם הכהן הגדול לאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC5_28","074_5_28","ACT","5","28","28","הלא צוה צוינו עליכם לבלתי למד בשם הזה והנה מלאתם את ירושלים תורתכם ותחפצו להביא עלינו את דמי האיש הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_29","074_5_29","ACT","5","29","29","ויען פטרוס והשליחים ויאמרו הלא עלינו להקשיב בקול אלהים מהקשיב בקול בני אדם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_30","074_5_30","ACT","5","30","30","אלהי אבותינו הקים את ישוע אשר שלחתם ידכם בו ותתלו אותו על העץ׃ ");
INSERT INTO heb_vpl VALUES ("AC5_31","074_5_31","ACT","5","31","31","את זה נשא האלהים בימינו לשר ולמושיע לתת תשובה לישראל וסליחת החטאים׃ ");
INSERT INTO heb_vpl VALUES ("AC5_32","074_5_32","ACT","5","32","32","ואנחנו עדיו על אלה וגם רוח הקדש אשר נתן אותו האלהים לשמעים בקולו׃ ");
INSERT INTO heb_vpl VALUES ("AC5_33","074_5_33","ACT","5","33","33","ויהי כשמעם ויתרגזו ויתיעצו להרוג אתם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_34","074_5_34","ACT","5","34","34","ויקם בתוך הסנהדרין אחד מן הפרושים גמליאל שמו והוא מורה התורה מכבד בעיני כל העם ויצו להוציא את השליחים החוצה לזמן מעט׃ ");
INSERT INTO heb_vpl VALUES ("AC5_35","074_5_35","ACT","5","35","35","ויאמר אליהם אנשי ישראל השמרו לכם מפני האנשים האלה במה שאתם עשים להם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_36","074_5_36","ACT","5","36","36","כי לפני הימים האלה קם תודס ויתן את נפשו כאחד הגדולים וידבקו בו כארבע מאות איש ויהרג וכל אשר שמעו אליו התפרדו ויהיו לאין׃ ");
INSERT INTO heb_vpl VALUES ("AC5_37","074_5_37","ACT","5","37","37","ואחר כן קם יהודה הגלילי בימי הספר ויסת אחריו עם רב וגם הוא נהרג וכל אשר שמעו אליו נפצו׃ ");
INSERT INTO heb_vpl VALUES ("AC5_38","074_5_38","ACT","5","38","38","ועתה אני אמר אליכם חדלו לכם מן האנשים האלה והניחו להם כי העצה והפעלה הזאת אם מאת אדם היא תפר׃ ");
INSERT INTO heb_vpl VALUES ("AC5_39","074_5_39","ACT","5","39","39","ואם מאת האלהים היא לא תוכלו להפר אתה פן תמצאו נלחמים את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC5_40","074_5_40","ACT","5","40","40","וישמעו אליו ויקראו את השליחים וילקו אתם ויצוו אשר לא ידברו בשם ישוע ויפטרו אותם׃ ");
INSERT INTO heb_vpl VALUES ("AC5_41","074_5_41","ACT","5","41","41","ויצאו שמחים מלפני הסנהדרין על כי זכו לשאת על שמו כלמה׃ ");
INSERT INTO heb_vpl VALUES ("AC5_42","074_5_42","ACT","5","42","42","וכל היום לא חדלו ללמד במקדש ובבתים ולבשר את בשורת ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC6_1","074_6_1","ACT","6","1","1","בימים ההם כאשר רבו התלמידים היתה תלונת היונים על העבריים על אשר העלימו עיניהם מאלמנותיהם לבלתי תת להן יום יום את ארוחתן׃ ");
INSERT INTO heb_vpl VALUES ("AC6_2","074_6_2","ACT","6","2","2","ויקראו שנים העשר את המון התלמידים ויאמרו לא נאוה לנו כי נעזב את דבר האלהים ונשמש את השלחנות׃ ");
INSERT INTO heb_vpl VALUES ("AC6_3","074_6_3","ACT","6","3","3","לכן אחי ברו לכם שבעה אנשים מקרבכם אשר שם טוב להם ומלאים רוח הקדש וחכמה ונפקידם על הענין הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC6_4","074_6_4","ACT","6","4","4","ואנחנו נשקד על התפלה ועל שמוש הדבר׃ ");
INSERT INTO heb_vpl VALUES ("AC6_5","074_6_5","ACT","6","5","5","וייטב הדבר לפני כל ההמון ויבחרו את אסטפנוס איש מלא אמונה ורוח הקדש ואת פילפוס ואת פרוכורוס ואת ניקנור ואת טימון ואת פרמנס ואת ניקלס גר אנטיוכיא׃ ");
INSERT INTO heb_vpl VALUES ("AC6_6","074_6_6","ACT","6","6","6","את אלה העמידו לפני השליחים ויתפללו ויסמכו את ידיהם עליהם׃ ");
INSERT INTO heb_vpl VALUES ("AC6_7","074_6_7","ACT","6","7","7","ויהי דבר האלהים הולך וגדל וירב מספר התלמידים בירושלים עד מאד וגם המון רב מן הכהנים נכנעו אל האמונה׃ ");
INSERT INTO heb_vpl VALUES ("AC6_8","074_6_8","ACT","6","8","8","ואסטפנוס מלא אמונה וגבורה ויעש אתות ומופתים גדולים בקרב העם׃ ");
INSERT INTO heb_vpl VALUES ("AC6_9","074_6_9","ACT","6","9","9","ויקומו אנשים מבית הכנסת הנקרא על שם הליברטינים ושל קורינים ואלכסנדריים ומן בני קיליקיא ואסיא ויתוכחו עם אסטפנוס׃ ");
INSERT INTO heb_vpl VALUES ("AC6_10","074_6_10","ACT","6","10","10","ולא יכלו עמד לנגד החכמה והרוח אשר דבר בו׃ ");
INSERT INTO heb_vpl VALUES ("AC6_11","074_6_11","ACT","6","11","11","ויסיתו בו אנשים אמרים שמענו אתו מדבר גדופים במשה ובאלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC6_12","074_6_12","ACT","6","12","12","ויעוררו את העם ואת הזקנים והסופרים ויקומו עליו ויחטפהו ויביאהו לפני הסנהדרין׃ ");
INSERT INTO heb_vpl VALUES ("AC6_13","074_6_13","ACT","6","13","13","ויעמידו עדי שקר אשר אמרו האיש הזה איננו חדל מהטיח דברים נגד מקום הקדש הזה ונגד התורה׃ ");
INSERT INTO heb_vpl VALUES ("AC6_14","074_6_14","ACT","6","14","14","כי שמענהו אמר זה ישוע הנצרי יתץ את המקום הזה וישנה את החקים אשר מסר לנו משה׃ ");
INSERT INTO heb_vpl VALUES ("AC6_15","074_6_15","ACT","6","15","15","ויסתכלו בו כל הישבים בסנהדרין ויראו את פניו כפני מלאך אלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC7_1","074_7_1","ACT","7","1","1","ויאמר הכהן הגדול האמת הוא אשר דברו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_2","074_7_2","ACT","7","2","2","ויען ויאמר אנשים אחים ואבות שמעו אלהי הכבוד נראה אל אברהם אבינו בהיותו בארם נהרים לפני שבתו בחרן׃ ");
INSERT INTO heb_vpl VALUES ("AC7_3","074_7_3","ACT","7","3","3","ויאמר אליו לך לך מארצך וממולדתך ובא אל הארץ אשר אראך׃ ");
INSERT INTO heb_vpl VALUES ("AC7_4","074_7_4","ACT","7","4","4","ויצא מארץ כשדים וישב בחרן ואחרי מות אביו העביר אתו משם אל הארץ הזאת אשר אתם ישבים בה עתה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_5","074_7_5","ACT","7","5","5","ולא נתן לו נחלה בה אף לא מדרך כף רגל ויבטח לתתה לאחזה לו ולזרעו אחריו ועוד לא היה לו בן׃ ");
INSERT INTO heb_vpl VALUES ("AC7_6","074_7_6","ACT","7","6","6","ויאמר לו אלהים כי גר יהיה זרעו בארץ לא להם ועבדום וענו אתם ארבע מאות שנה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_7","074_7_7","ACT","7","7","7","וגם את הגוי אשר יעבדו דן אנכי אמר אלהים ואחרי כן יצאו ויעבדוני במקום הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_8","074_7_8","ACT","7","8","8","ויתן לו את ברית המילה ובכן הוליד את יצחק וימל אתו ביום השמיני ויצחק הוליד את יעקב ויעקב הוליד את שנים עשר האבות׃ ");
INSERT INTO heb_vpl VALUES ("AC7_9","074_7_9","ACT","7","9","9","ויקנאו האבות ביוסף וימכרו אותו מצרימה ואלהים היה עמו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_10","074_7_10","ACT","7","10","10","ויצילהו מכל צרותיו ויתן לו חן וחכמה לפני פרעה מלך מצרים וישימהו שליט על מצרים ועל כל ביתו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_11","074_7_11","ACT","7","11","11","ויהי רעב על כל ארץ מצרים וכנען וצרה גדולה ואבותינו לא מצאו אכל׃ ");
INSERT INTO heb_vpl VALUES ("AC7_12","074_7_12","ACT","7","12","12","וישמע יעקב כי יש שבר במצרים וישלח שמה את אבותינו בפעם הראשונה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_13","074_7_13","ACT","7","13","13","ובפעם השנית התודע יוסף אל אחיו ומולדת יוסף נגלתה לפרעה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_14","074_7_14","ACT","7","14","14","וישלח יוסף ויקרא ליעקב אביו ולכל משפחתו בשבעים וחמש נפש׃ ");
INSERT INTO heb_vpl VALUES ("AC7_15","074_7_15","ACT","7","15","15","וירד יעקב מצרימה וימת הוא ואבותינו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_16","074_7_16","ACT","7","16","16","ויובאו שכמה ויושמו בקבר אשר קנה אברהם בכספו מיד בני חמור אבי שכם׃ ");
INSERT INTO heb_vpl VALUES ("AC7_17","074_7_17","ACT","7","17","17","ויהי כאשר קרבה עת ההבטחה אשר נשבע אלהים לאברהם ויגדל העם וירב במצרים׃ ");
INSERT INTO heb_vpl VALUES ("AC7_18","074_7_18","ACT","7","18","18","עד כי קם מלך אחר אשר לא ידע את יוסף׃ ");
INSERT INTO heb_vpl VALUES ("AC7_19","074_7_19","ACT","7","19","19","וזה התחכם למשפחתנו וירע לאבותינו ויצו אתם להשליך את עלליהם אל פני השדה לבלתי החיותם׃ ");
INSERT INTO heb_vpl VALUES ("AC7_20","074_7_20","ACT","7","20","20","בעת ההיא נולד משה ויהי טוב לאלהים ויהי אמון בבית אביו שלשה ירחים׃ ");
INSERT INTO heb_vpl VALUES ("AC7_21","074_7_21","ACT","7","21","21","וכאשר השלך אספה אתו בת פרעה ותגדלהו לה לבן׃ ");
INSERT INTO heb_vpl VALUES ("AC7_22","074_7_22","ACT","7","22","22","וילמד משה בכל חכמת מצרים ויהי גבור בדברים ובמעשים׃ ");
INSERT INTO heb_vpl VALUES ("AC7_23","074_7_23","ACT","7","23","23","ובמלאת לו ארבעים שנה עלה על לבו לפקד את אחיו בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AC7_24","074_7_24","ACT","7","24","24","וירא איש אחד מעשק חנם ויושע לו ויקם נקמת המכה בהכותו את המצרי׃ ");
INSERT INTO heb_vpl VALUES ("AC7_25","074_7_25","ACT","7","25","25","ויחשב בלבבו כי יבינו אחיו אשר על ידו יתן האלהים להם תשועה והם לא הבינו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_26","074_7_26","ACT","7","26","26","ויהי ביום השני ויבא בתוכם והם נצים ויבקש לעשות שלום ביניהם לאמר אנשים אחים אתם ולמה תעשקו איש את אחיו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_27","074_7_27","ACT","7","27","27","והעשק את רעהו הדפו לאמר מי שמך לאיש שר ושפט עלינו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_28","074_7_28","ACT","7","28","28","הלהרגני אתה אמר כאשר הרגת אתמל את המצרי׃ ");
INSERT INTO heb_vpl VALUES ("AC7_29","074_7_29","ACT","7","29","29","ויברח משה על הדבר הזה ויהי גר בארץ מדין ויולד שם שני בנים׃ ");
INSERT INTO heb_vpl VALUES ("AC7_30","074_7_30","ACT","7","30","30","ובמלאת ארבעים שנה נראה אליו מלאך יהוה במדבר הר סיני בלבת אש מתוך הסנה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_31","074_7_31","ACT","7","31","31","וירא משה ויתמה על המראה ובסורו לראות ויהי קול יהוה אליו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_32","074_7_32","ACT","7","32","32","אנכי אלהי אבותיך אלהי אברהם אלהי יצחק ואלהי יעקב ויחרד משה ויירא מהביט׃ ");
INSERT INTO heb_vpl VALUES ("AC7_33","074_7_33","ACT","7","33","33","ויאמר אליו יהוה של נעליך מעל רגליך כי המקום אשר אתה עומד עליו אדמת קדש הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC7_34","074_7_34","ACT","7","34","34","ראה ראיתי את עני עמי אשר במצרים ואת נאקתם שמעתי וארד להצילם ועתה לכה ואשלחך מצרימה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_35","074_7_35","ACT","7","35","35","הוא משה אשר כחשו בו לאמר מי שמך לשר ושפט אתו שלח האלהים לשר וגאל ביד המלאך הנראה אליו בסנה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_36","074_7_36","ACT","7","36","36","והוא הוציאם ויעש אתות ומפתים בארץ מצרים ובים סוף ובמדבר ארבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_37","074_7_37","ACT","7","37","37","הוא משה אשר אמר אל בני ישראל נביא מקרב אחיכם כמני יקים לכם יהוה אלהיכם אליו תשמעון׃ ");
INSERT INTO heb_vpl VALUES ("AC7_38","074_7_38","ACT","7","38","38","הוא אשר היה בקהל במדבר עם המלאך הדבר אליו בהר סיני ועם אבותינו ואשר קבל דברים חיים לתת לנו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_39","074_7_39","ACT","7","39","39","הוא אשר אבותינו לא אבו לשמע לו כי אם מאסו אתו ולבבם פנה מצרימה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_40","074_7_40","ACT","7","40","40","ויאמרו אל אהרן עשה לנו אלהים אשר ילכו לפנינו כי זה משה אשר העלנו מארץ מצרים לא ידענו מה היה לו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_41","074_7_41","ACT","7","41","41","ויעשו עגל בימים ההם ויזבחו זבחים לאליל וישמחו במעשה ידיהם׃ ");
INSERT INTO heb_vpl VALUES ("AC7_42","074_7_42","ACT","7","42","42","ויפן מהם האלהים ויתנם לעבד את צבא השמים כאשר כתוב בספר הנביאים הזבחים ומנחה הגשתם לי במדבר ארבעים שנה בית ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AC7_43","074_7_43","ACT","7","43","43","ונשאתם את סכת מלכם ואת כוכב אלהיכם רמפן הצלמים אשר עשיתם להשתחות להם והגליתי אתכם מהלאה לבבל׃ ");
INSERT INTO heb_vpl VALUES ("AC7_44","074_7_44","ACT","7","44","44","משכן העדות היה לאבותינו במדבר כאשר צוה המדבר אל משה לעשות אתו כתבנית אשר ראה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_45","074_7_45","ACT","7","45","45","ואבותינו לקחהו וגם הביאהו אתם הם ויהושע ברשתם את ארצות הגוים אשר גרש אתם אלהים מפני אבותינו עד ימי דוד׃ ");
INSERT INTO heb_vpl VALUES ("AC7_46","074_7_46","ACT","7","46","46","והוא מצא חן בעיני אלהים וישאל למצא משכנות לאלהי יעקב׃ ");
INSERT INTO heb_vpl VALUES ("AC7_47","074_7_47","ACT","7","47","47","ושלמה בנה לו בית׃ ");
INSERT INTO heb_vpl VALUES ("AC7_48","074_7_48","ACT","7","48","48","אבל העליון לא ישכן בהיכלות מעשי ידים כאשר אמר הנביא׃ ");
INSERT INTO heb_vpl VALUES ("AC7_49","074_7_49","ACT","7","49","49","השמים כסאי והארץ הדם רגלי אי זה בית אשר תבנו לי אמר יהוה ואי זה מקום מנוחתי׃ ");
INSERT INTO heb_vpl VALUES ("AC7_50","074_7_50","ACT","7","50","50","הלא את כל אלה ידי עשתה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_51","074_7_51","ACT","7","51","51","קשי ערף וערלי לב ואזנים ממרים הייתם תמיד ברוח הקדש כאבותיכם גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("AC7_52","074_7_52","ACT","7","52","52","מי מהנביאים אשר לא רדפוהו אבותיכם אף המיתו את המבשרים מקדם ביאת הצדיק אשר עתה הייתם אתם מוסריו ומרצחיו׃ ");
INSERT INTO heb_vpl VALUES ("AC7_53","074_7_53","ACT","7","53","53","אתם אשר קבלתם את התורה על ידי מלאכות המלאכים ולא שמרתם אותה׃ ");
INSERT INTO heb_vpl VALUES ("AC7_54","074_7_54","ACT","7","54","54","ויהי כשמעם את אלה התרגזו בלבבם ויחרקו עליו שניהם׃ ");
INSERT INTO heb_vpl VALUES ("AC7_55","074_7_55","ACT","7","55","55","והוא מלא רוח הקדש ויבט השמימה וירא את כבוד אלהים ואת ישוע נצב לימין האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC7_56","074_7_56","ACT","7","56","56","ויאמר הנני ראה את השמים נפתחים ואת בן האדם נצב לימין האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC7_57","074_7_57","ACT","7","57","57","ויצעקו בקול גדול ויאטמו את אזניהם ויתנפלו עליו כלם יחד׃ ");
INSERT INTO heb_vpl VALUES ("AC7_58","074_7_58","ACT","7","58","58","וידחפהו חוצה לעיר ויסקלו אתו באבנים והעדים פשטו את בגדיהם לרגלי בחור אחד ושמו שאול׃ ");
INSERT INTO heb_vpl VALUES ("AC7_59","074_7_59","ACT","7","59","59","ויסקלו את אסטפנוס והוא משוע ואמר אדני ישוע קבל את רוחי׃ ");
INSERT INTO heb_vpl VALUES ("AC7_60","074_7_60","ACT","7","60","60","ויכרע על ברכיו ויצעק בקול גדול יהוה אל תשמר להם את החטא הזה ויהי אחרי דברו כדבר הזה ויישן׃ ");
INSERT INTO heb_vpl VALUES ("AC8_1","074_8_1","ACT","8","1","1","ושאול גם הוא היה רצה בהרגתו ותהי ביום ההוא רדיפה גדולה על הקהלה אשר בירושלים ויפצו כלם בערי יהודה ושמרון לבד מן השליחים׃ ");
INSERT INTO heb_vpl VALUES ("AC8_2","074_8_2","ACT","8","2","2","וישאו אנשים חסידים את אסטפנוס ויקברהו ויספדו עליו מספד גדול׃ ");
INSERT INTO heb_vpl VALUES ("AC8_3","074_8_3","ACT","8","3","3","ושאול החריב את הקהלה וישוטט בבתים ויסחב משם אנשים ונשים ויסגירם לכלא׃ ");
INSERT INTO heb_vpl VALUES ("AC8_4","074_8_4","ACT","8","4","4","והנפוצים עברו בארץ ויבשרו את הדבר׃ ");
INSERT INTO heb_vpl VALUES ("AC8_5","074_8_5","ACT","8","5","5","ופילפוס ירד אל עיר שמרון ויכרז להם את המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC8_6","074_8_6","ACT","8","6","6","ויקשב המון העם בלב אחד אל אמרי פילפוס בשמעם ובראותם את האתות אשר עשה׃ ");
INSERT INTO heb_vpl VALUES ("AC8_7","074_8_7","ACT","8","7","7","כי רבים היו אחוזי רוחות הטמאה והרוחות יצאו מהם צעקות בקול גדול ורבים נכי אברים ופסחים וירפאו׃ ");
INSERT INTO heb_vpl VALUES ("AC8_8","074_8_8","ACT","8","8","8","ותהי שמחה גדולה בעיר ההיא׃ ");
INSERT INTO heb_vpl VALUES ("AC8_9","074_8_9","ACT","8","9","9","ואיש אחד ושמו שמעון היה מלפנים בעיר מכשף ומשמים את עם שמרון באמרו על נפשו כי גדול הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC8_10","074_8_10","ACT","8","10","10","ויקשיבו אליו מקטנם ועד גדולם לאמר זה הוא גבורת האלהים הגדולה׃ ");
INSERT INTO heb_vpl VALUES ("AC8_11","074_8_11","ACT","8","11","11","ויקשיבו אליו על היותו משמים אותם בכשפיו ימים רבים׃ ");
INSERT INTO heb_vpl VALUES ("AC8_12","074_8_12","ACT","8","12","12","ויהי כאשר האמינו לפילפוס בבשרו את מלכות האלהים ואת שם ישוע המשיח ויטבלו אנשים ונשים׃ ");
INSERT INTO heb_vpl VALUES ("AC8_13","074_8_13","ACT","8","13","13","ויאמן שמעון גם הוא ויטבל וידבק בפילפוס וירא את האתות והמפתים הגדלים אשר נעשו וישתומם׃ ");
INSERT INTO heb_vpl VALUES ("AC8_14","074_8_14","ACT","8","14","14","וישמעו השליחים אשר בירושלים כי קבלה שמרון את דבר האלהים וישלחו אליהם את פטרוס ואת יוחנן׃ ");
INSERT INTO heb_vpl VALUES ("AC8_15","074_8_15","ACT","8","15","15","וירדו שמה ויתפללו בעדם אשר יקבלו את רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC8_16","074_8_16","ACT","8","16","16","כי הרוח לא צלחה עד עתה על אחד מהם והם רק נטבלים בשם האדון ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC8_17","074_8_17","ACT","8","17","17","ויסמכו את ידיהם עליהם ויקבלו את רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC8_18","074_8_18","ACT","8","18","18","ויהי בראות שמעון כי בסמיכות ידי השליחים נתן רוח הקדש ויבא לפניהם כסף׃ ");
INSERT INTO heb_vpl VALUES ("AC8_19","074_8_19","ACT","8","19","19","ויאמר תנו נא גם לי את היכלת הזאת אשר יקבל את רוח הקדש כל אשר אשים עליו את ידי׃ ");
INSERT INTO heb_vpl VALUES ("AC8_20","074_8_20","ACT","8","20","20","ויאמר אליו פטרוס כספך יהי אתך לאבדון יען חשבת לקנות במחיר את מתת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC8_21","074_8_21","ACT","8","21","21","אין לך חלק וגורל בדבר הזה כי לבבך איננו ישר לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC8_22","074_8_22","ACT","8","22","22","ועתה שוב מרעתך זאת והתחנן אל האלהים אולי תסלח לך מזמת לבבך׃ ");
INSERT INTO heb_vpl VALUES ("AC8_23","074_8_23","ACT","8","23","23","כי ראה אנכי כי באת לידי מרורת רוש וחרצבות רשע׃ ");
INSERT INTO heb_vpl VALUES ("AC8_24","074_8_24","ACT","8","24","24","ויען שמעון ויאמר העתירו אתם בעדי אל יהוה לבלתי בוא עלי דבר מכל אשר אמריתם׃ ");
INSERT INTO heb_vpl VALUES ("AC8_25","074_8_25","ACT","8","25","25","והמה אחרי אשר העידה ודברו את דבר יהוה שבו ירושלים ויבשרו את הבשורה בכפרים רבים אשר לשמרונים׃ ");
INSERT INTO heb_vpl VALUES ("AC8_26","074_8_26","ACT","8","26","26","וידבר מלאך יהוה אל פילפוס לאמר קום לך הנגבה על הדרך הירדת מירושלים עזתה והיא חרבה׃ ");
INSERT INTO heb_vpl VALUES ("AC8_27","074_8_27","ACT","8","27","27","ויקם וילך והנה איש כושי והוא סריס ושליט לקנדק מלכת כוש וממנה על כל גנזיה אשר עלה אל ירושלים להשתחות׃ ");
INSERT INTO heb_vpl VALUES ("AC8_28","074_8_28","ACT","8","28","28","ויהי בשובו והוא ישב על מרכבתו וקרא בספר ישעיה הנביא׃ ");
INSERT INTO heb_vpl VALUES ("AC8_29","074_8_29","ACT","8","29","29","ויאמר הרוח אל פילפוס גשה והלוה על המרכבה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("AC8_30","074_8_30","ACT","8","30","30","וירץ פילפוס אליה וישמע אתו קרא בספר ישעיה הנביא ויאמר הגם תבין את אשר אתה קורא׃ ");
INSERT INTO heb_vpl VALUES ("AC8_31","074_8_31","ACT","8","31","31","ויאמר ואיככה אוכל אם אין איש אשר יורני ויבקש מאת פילפוס לעלות ולשבת אצלו׃ ");
INSERT INTO heb_vpl VALUES ("AC8_32","074_8_32","ACT","8","32","32","וענין הכתוב אשר קרא זה הוא כשה לטבח יובל וכרחל לפני גוזזיה נאלמה ולא יפתח פיו׃ ");
INSERT INTO heb_vpl VALUES ("AC8_33","074_8_33","ACT","8","33","33","בעצר משפטו לקח ואת דורו מי ישוחח כי נגזרו מארץ חייו׃ ");
INSERT INTO heb_vpl VALUES ("AC8_34","074_8_34","ACT","8","34","34","ויען הסריס ויאמר אל פילפוס אשאלה ממך על מי הנביא מדבר את זאת על נפשו או על איש אחר׃ ");
INSERT INTO heb_vpl VALUES ("AC8_35","074_8_35","ACT","8","35","35","ויפתח פילפוס את פיו ויחל מן הכתוב הזה ויבשר אותו את ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC8_36","074_8_36","ACT","8","36","36","ויהי בעברם בדרך ויבאו אל מקום מים ויאמר הסריס הנה מים מה ימנעני מהטבל׃ ");
INSERT INTO heb_vpl VALUES ("AC8_37","074_8_37","ACT","8","37","37","ויאמר פילפוס אם מאמין אתה בכל לבבך מתר לך ויען ויאמר אני מאמין כי ישוע המשיח בן האלהים הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC8_38","074_8_38","ACT","8","38","38","ויצו להעמיד את המרכבה וירדו שניהם אל תוך המים פילפוס והסריס ויטבל אותו׃ ");
INSERT INTO heb_vpl VALUES ("AC8_39","074_8_39","ACT","8","39","39","ויהי כי עלו מן המים וישא רוח יהוה את פילפוס ולא יסף הסריס לראותו כי הלך לדרכו שמח׃ ");
INSERT INTO heb_vpl VALUES ("AC8_40","074_8_40","ACT","8","40","40","ופילפוס נמצא באשדוד ויעבר ויבשר בכל הערים עד באו לקסרין׃ ");
INSERT INTO heb_vpl VALUES ("AC9_1","074_9_1","ACT","9","1","1","ושאול עודנו יפח זעם ורצח על תלמידי האדון ויבא אל הכהן הגדול׃ ");
INSERT INTO heb_vpl VALUES ("AC9_2","074_9_2","ACT","9","2","2","וישאל מאתו מכתבים לדמשק אל בתי הכנסיות למען אשר יאסר את אשר ימצא בדרך ההיא אנשים או נשים ויביאם ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC9_3","074_9_3","ACT","9","3","3","ויהי הוא הלך וקרב לדמשק והנה פתאם נגה עליו מסביב אור מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("AC9_4","074_9_4","ACT","9","4","4","ויפל ארצה וישמע קול מדבר אליו שאול שאול למה תרדפני׃ ");
INSERT INTO heb_vpl VALUES ("AC9_5","074_9_5","ACT","9","5","5","ויאמר מי אתה אדני ויאמר האדון אנכי ישוע אשר אתה רודף קשה לך לבעט בדרבנות׃ ");
INSERT INTO heb_vpl VALUES ("AC9_6","074_9_6","ACT","9","6","6","והוא חרד ונבעת ויאמר אדני מה תחפץ ואעשה ויען האדון קום לך העירה ויאמר לך את אשר עליך לעשות׃ ");
INSERT INTO heb_vpl VALUES ("AC9_7","074_9_7","ACT","9","7","7","והאנשים אשר הלכו אתו עמדו נאלמים כי שמעו את הקול ואיש לא הביטו׃ ");
INSERT INTO heb_vpl VALUES ("AC9_8","074_9_8","ACT","9","8","8","ויקם שאול מן הארץ ובפתחו את עיניו לא ראה איש ויחזיקו בידו ויוליכהו לדמשק׃ ");
INSERT INTO heb_vpl VALUES ("AC9_9","074_9_9","ACT","9","9","9","ויחשכו עיניו מראות שלשת ימים ולא אכל ולא שתה׃ ");
INSERT INTO heb_vpl VALUES ("AC9_10","074_9_10","ACT","9","10","10","ותלמיד אחד היה בדמשק חנניה שמו ויאמר אליו האדון במחזה חנניה ויאמר הנני אדני׃ ");
INSERT INTO heb_vpl VALUES ("AC9_11","074_9_11","ACT","9","11","11","ויאמר אליו האדון קום לך אל הרחוב הנקרא הישר ושאל בבית יהודה לאיש טרסי ושמו שאול כי הנה הוא מתפלל׃ ");
INSERT INTO heb_vpl VALUES ("AC9_12","074_9_12","ACT","9","12","12","וירא במחזה והנה איש ושמו חנניה בא החדרה ושם עליו את ידו למען ישוב ויראה׃ ");
INSERT INTO heb_vpl VALUES ("AC9_13","074_9_13","ACT","9","13","13","ויען חנניה ויאמר אדני שמעתי רבים מספרים על האיש הזה כמה רעות עשה לקדושיך בירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC9_14","074_9_14","ACT","9","14","14","וגם פה רשיון יש לו מאת ראשי הכהנים לאסר את כל הקראים בשמך׃ ");
INSERT INTO heb_vpl VALUES ("AC9_15","074_9_15","ACT","9","15","15","ויאמר אליו האדון לך כי כלי חפץ הוא לי לשאת את שמי לפני גוים ומלכים ולפני בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AC9_16","074_9_16","ACT","9","16","16","כי אני אראהו כמה יש לו לסבל למען שמי׃ ");
INSERT INTO heb_vpl VALUES ("AC9_17","074_9_17","ACT","9","17","17","וילך חנניה ויבא הביתה וישם את ידיו עליו ויאמר שאול אחי האדון ישוע הנראה אליך בדרך אשר באת בה שלחני למען תשוב ותראה ותמלא רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC9_18","074_9_18","ACT","9","18","18","וכרגע נפלו מעל עיניו כמו קשקשים וישב פתאם לראות ויקם ויטבל׃ ");
INSERT INTO heb_vpl VALUES ("AC9_19","074_9_19","ACT","9","19","19","ויאכל לחם ויחזק וישב שאול ימים אחדים עם התלמידים אשר בדמשק׃ ");
INSERT INTO heb_vpl VALUES ("AC9_20","074_9_20","ACT","9","20","20","וימהר ויקרא בבתי הכנסיות את המשיח לאמר כי הוא הוא בן האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC9_21","074_9_21","ACT","9","21","21","וישתוממו כל השמעים ויאמרו הלא זה הוא אשר האביד בירושלים את קראי השם הזה ולמען זאת בא הנה להביאם אסורים לפני ראשי הכהנים׃ ");
INSERT INTO heb_vpl VALUES ("AC9_22","074_9_22","ACT","9","22","22","ושאול היה הולך וחזק ויהם את היהודים ישבי דמשק בהוכיחו כי זה הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC9_23","074_9_23","ACT","9","23","23","ויהי כי ארכו לו שם הימים ויועצו היהודים יחדו להמיתו׃ ");
INSERT INTO heb_vpl VALUES ("AC9_24","074_9_24","ACT","9","24","24","ויודע לשאול ארבם והמה שמרו את השערים יומם ולילה למען ימיתהו׃ ");
INSERT INTO heb_vpl VALUES ("AC9_25","074_9_25","ACT","9","25","25","ויקחו אתו התלמידים לילה ויורידהו בסל בעד החומה׃ ");
INSERT INTO heb_vpl VALUES ("AC9_26","074_9_26","ACT","9","26","26","ויהי כבוא שאול ירושלימה ויבקש להלות אל התלמידים וייראו כלם מפניו ולא האמינו כי תלמיד הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC9_27","074_9_27","ACT","9","27","27","ויקח אתו בר נבא ויביאהו אל השליחים ויספר להם את אשר ראה בדרך את האדון וכי הוא דבר אליו ואיך בדמשק השמיע בבטחון את שם ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC9_28","074_9_28","ACT","9","28","28","ויהי אתם יוצא ובא בירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC9_29","074_9_29","ACT","9","29","29","ויקרא בבטחון בשם האדון ישוע וידבר ויתוכח גם עם היהודים היונים והם זממו להמיתו׃ ");
INSERT INTO heb_vpl VALUES ("AC9_30","074_9_30","ACT","9","30","30","וישמעו האחים ויורידו אתו לקסרין וישלחהו אל טרסוס׃ ");
INSERT INTO heb_vpl VALUES ("AC9_31","074_9_31","ACT","9","31","31","ויהי שלום לקהלות בכל מקמות יהודה והגליל ושמרון ותבנינה ותתהלכנה ביראת האדון ותרבינה בנחמת רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC9_32","074_9_32","ACT","9","32","32","ויהי בסבב פטרוס בכל המקמות וירד גם אל הקדושים אשר ישבו בלד׃ ");
INSERT INTO heb_vpl VALUES ("AC9_33","074_9_33","ACT","9","33","33","וימצא שם איש שמו אניס והוא שכב על משכבו זה שמנה שנים והוא נכה אברים׃ ");
INSERT INTO heb_vpl VALUES ("AC9_34","074_9_34","ACT","9","34","34","ויאמר אליו פטרוס אניס רפאך ישוע המשיח קום הצע לך אתה ויקם פתאם׃ ");
INSERT INTO heb_vpl VALUES ("AC9_35","074_9_35","ACT","9","35","35","ויראו אותו כל ישבי לד והשרון ויפנו אל האדון׃ ");
INSERT INTO heb_vpl VALUES ("AC9_36","074_9_36","ACT","9","36","36","ותלמידה ביפו ושמה טביתא תרגומו צביה והיא מלאה מעשים טובים וצדקות אשר עשתה׃ ");
INSERT INTO heb_vpl VALUES ("AC9_37","074_9_37","ACT","9","37","37","ויהי בימים ההם ותחלה ותמת וירחצו אתה וישימוה בעליה׃ ");
INSERT INTO heb_vpl VALUES ("AC9_38","074_9_38","ACT","9","38","38","ולד קרובה היא ליפו וישמעו התלמידים כי פטרוס שם וישלחו אליו שני אנשים ויפצרו בו לבלתי העצל לעבר אליהם׃ ");
INSERT INTO heb_vpl VALUES ("AC9_39","074_9_39","ACT","9","39","39","ויקם פטרוס וילך אתם ובבאו העלהו אל העליה ותנשנה אליו כל האלמנות בוכיות ומראות לו את הכתנת ואת הבגדים אשר עשתה צביה בעודה עמהן׃ ");
INSERT INTO heb_vpl VALUES ("AC9_40","074_9_40","ACT","9","40","40","ויוצא פטרוס את כלם החוצה ויכרע על ברכיו ויתפלל ויפן אל גויתה ויאמר טביתא קומי ותפתח את עיניה ותרא את פטרוס ותתעודד׃ ");
INSERT INTO heb_vpl VALUES ("AC9_41","074_9_41","ACT","9","41","41","וישלח ידו ויקם אתה ויקרא את הקדושים ואת האלמנות ויעמד אתה חיה לפניהם׃ ");
INSERT INTO heb_vpl VALUES ("AC9_42","074_9_42","ACT","9","42","42","ויודע הדבר בכל יפו ויאמינו רבים באדון׃ ");
INSERT INTO heb_vpl VALUES ("AC9_43","074_9_43","ACT","9","43","43","ויואל לשבת ביפו ימים רבים עם בורסי אחד ושמו שמעון׃ ");
INSERT INTO heb_vpl VALUES ("AC10_1","074_10_1","ACT","10","1","1","ואיש היה בקסרין ושמו קרניליוס שר מאה מן הגדוד הנקרא האיטלקי׃ ");
INSERT INTO heb_vpl VALUES ("AC10_2","074_10_2","ACT","10","2","2","והוא חסיד וירא אלהים עם כל בני ביתו ועשה צדקות הרבה לעם ומתפלל תמיד לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_3","074_10_3","ACT","10","3","3","ומחזה נראה אליו כשעה התשיעית ליום וירא מלאך אלהים בא אליו פנימה ואמר קרניליוס׃ ");
INSERT INTO heb_vpl VALUES ("AC10_4","074_10_4","ACT","10","4","4","ויבט אליו ויירא ויאמר מה זה אדני ויאמר אליו תפלותיך וצדקותיך עלו לזכרון לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_5","074_10_5","ACT","10","5","5","ועתה שלח לך אנשים אל יפו והבא אליך את שמעון המכנה פטרוס׃ ");
INSERT INTO heb_vpl VALUES ("AC10_6","074_10_6","ACT","10","6","6","הוא מתגורר עם בורסי אחד שמעון שמו אשר ביתו על יד הים הוא יאמר לך את אשר עליך לעשות׃ ");
INSERT INTO heb_vpl VALUES ("AC10_7","074_10_7","ACT","10","7","7","וילך לו המלאך הדבר אל קרניליוס ויקרא אל שנים מעבדי ביתו ואל איש מלחמה אחד ירא אלהים מן העמדים תמיד לפניו לשרתו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_8","074_10_8","ACT","10","8","8","ויספר להם את כל הדברים וישלחם אל יפו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_9","074_10_9","ACT","10","9","9","ויהי ממחרת והמה הלכים בדרך וקרבים לעיר ויעל פטרוס על הגג להתפלל כשעה הששית׃ ");
INSERT INTO heb_vpl VALUES ("AC10_10","074_10_10","ACT","10","10","10","והוא רעב ויתאו לטעם לחם ובהכינם לו נפלה תרדמה עליו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_11","074_10_11","ACT","10","11","11","וירא את השמים נפתחים והנה כלי ירד אליו כדמות מטפחת בד גדולה ויורד בארבע כנפותיו על הארץ׃ ");
INSERT INTO heb_vpl VALUES ("AC10_12","074_10_12","ACT","10","12","12","ובתוכו מכל בהמת הארץ וחיה ורמש ועוף השמים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_13","074_10_13","ACT","10","13","13","ויהי קול אליו לאמר קום פטרוס זבח ואכל׃ ");
INSERT INTO heb_vpl VALUES ("AC10_14","074_10_14","ACT","10","14","14","ויאמר פטרוס חלילה לי אדני כי מעולם לא אכלתי כל פגול וטמא׃ ");
INSERT INTO heb_vpl VALUES ("AC10_15","074_10_15","ACT","10","15","15","ויהי עוד קול אליו פעם שנית לאמר את אשר טהר האלהים אתה אל תטמאנו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_16","074_10_16","ACT","10","16","16","וכן היה שלש פעמים והכלי שב והעלה השמימה׃ ");
INSERT INTO heb_vpl VALUES ("AC10_17","074_10_17","ACT","10","17","17","ויהי בהתפעם רוח פטרוס על המראה אשר ראה והנה האנשים השלוחים מאת קרניליוס שאלו לבית שמעון ויעמדו על הפתח׃ ");
INSERT INTO heb_vpl VALUES ("AC10_18","074_10_18","ACT","10","18","18","ויקראו וידרשו היש מתגורר שם שמעון המכנה פטרוס׃ ");
INSERT INTO heb_vpl VALUES ("AC10_19","074_10_19","ACT","10","19","19","ופטרוס עודנו חשב עם לבבו על המראה והרוח אמר אליו הנה שלשה אנשים מבקשים אותך׃ ");
INSERT INTO heb_vpl VALUES ("AC10_20","074_10_20","ACT","10","20","20","לכן קום רד ולכה נא אתם ואל תתמהמה כי אנכי שלחתים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_21","074_10_21","ACT","10","21","21","וירד פטרוס אל האנשים הנשלחים אליו מאת קרניליוס ויאמר אנכי האיש אשר אתם מבקשים למה זה באתם הנה׃ ");
INSERT INTO heb_vpl VALUES ("AC10_22","074_10_22","ACT","10","22","22","ויאמרו קרניליוס שר מאה איש צדיק וירא אלהים ולו שם טוב בכל עם היהודים צוה על פי מלאך קדוש לקרא לך אל ביתו ולשמע דברים מפיך׃ ");
INSERT INTO heb_vpl VALUES ("AC10_23","074_10_23","ACT","10","23","23","ויקרא אתם אליו ויאספם הביתה ויהי ממחרת ויצא פטרוס אתם ומקצת האחים אשר ביפו הלכו עמו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_24","074_10_24","ACT","10","24","24","ולמחרתו באו אל קסרין וקרניליוס מחכה להם ועמו בני משפחתו וקרוביו ומידעיו הנקהלים אליו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_25","074_10_25","ACT","10","25","25","ויהי כבוא פטרוס ויצא קרניליוס לקראתו ויפל לרגליו וישתחו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_26","074_10_26","ACT","10","26","26","ויקם אותו פטרוס ויאמר קום כי גם אני אנוש אנכי׃ ");
INSERT INTO heb_vpl VALUES ("AC10_27","074_10_27","ACT","10","27","27","וידבר אתו ויבא הביתה וימצא רבים נאספים שמה׃ ");
INSERT INTO heb_vpl VALUES ("AC10_28","074_10_28","ACT","10","28","28","ויאמר אליהם אתם ידעתם כי אסור הוא לאיש יהודי להלות ולקרב אל נכרי ואתי הורה אלהים לבלתי אמר חל או טמא על כל אדם׃ ");
INSERT INTO heb_vpl VALUES ("AC10_29","074_10_29","ACT","10","29","29","ובעבור זאת כאשר נקראתי לא נמנעתי מהלך ועתה אשאלכם מדוע קראתם לי׃ ");
INSERT INTO heb_vpl VALUES ("AC10_30","074_10_30","ACT","10","30","30","ויאמר קרניליוס זה ארבעה ימים הייתי צם עד השעה הזאת ובשעה התשיעית התפללתי בתוך ביתי והנה איש נצב לפני בלבוש זהר׃ ");
INSERT INTO heb_vpl VALUES ("AC10_31","074_10_31","ACT","10","31","31","ויאמר קרניליוס נשמעה תפלתך וצדקותיך היו לזכרון לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_32","074_10_32","ACT","10","32","32","ועתה שלח אל יפו וקרא אליך את שמעון המכנה פטרוס מתגורר הוא בבית שמעון הבורסי על הים אשר בבואו ידבר לך׃ ");
INSERT INTO heb_vpl VALUES ("AC10_33","074_10_33","ACT","10","33","33","ואמהר ואשלח אליך ואתה היטבת לעשות אשר באת אלי והננו כלנו פה לפני האלהים לשמע את כל אשר צוית מאת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AC10_34","074_10_34","ACT","10","34","34","ויפתח פטרוס את פיו ויאמר עתה ידעתי באמת כי האלהים איננו נשא פנים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_35","074_10_35","ACT","10","35","35","כי אם בכל עם ועם הירא אותו ועשה צדק רצוי הוא לפניו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_36","074_10_36","ACT","10","36","36","וישלח את דברו לבני ישראל ויבשר את השלום על ידי ישוע המשיח והוא אדון הכל׃ ");
INSERT INTO heb_vpl VALUES ("AC10_37","074_10_37","ACT","10","37","37","אתם ידעתם את הדבר הנעשה בכל יהודה החל מן הגליל אחרי הטבילה אשר קרא אותה יוחנן׃ ");
INSERT INTO heb_vpl VALUES ("AC10_38","074_10_38","ACT","10","38","38","את אשר משח האלהים את ישוע הנצרי ברוח הקדש ובגבורה ויעבר בארץ עשה חסד ורפא את כל הנכבשים תחת יד השטן כי האלהים היה עמו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_39","074_10_39","ACT","10","39","39","ואנחנו עדים על כל אשר עשה בארץ היהודים ובירושלים ואשר הרגהו בהוקיעם אתו על העץ׃ ");
INSERT INTO heb_vpl VALUES ("AC10_40","074_10_40","ACT","10","40","40","אותו הקים האלהים ביום השלישי ויתנהו להראות בגלוי׃ ");
INSERT INTO heb_vpl VALUES ("AC10_41","074_10_41","ACT","10","41","41","לא לכל העם כי אם לנו העדים אשר האלהים בחר בהם מראש אשר אכלנו ושתינו אתו אחרי קומו מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_42","074_10_42","ACT","10","42","42","ויצו אתנו להשמיע לעם ולהעיד כי אתו שם האלהים לשופט החיים והמתים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_43","074_10_43","ACT","10","43","43","ועליו כל הנביאים מעידים כי יקבלו סליחת החטאים בשמו כל המאמינים בו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_44","074_10_44","ACT","10","44","44","עוד פטרוס מדבר הדברים האלה ורוח הקדש צלחה על כל השמעים את הדבר׃ ");
INSERT INTO heb_vpl VALUES ("AC10_45","074_10_45","ACT","10","45","45","והמאמינים בני המילה אשר באו את פטרוס השתוממו כי מתנת רוח הקדש נשפכה גם על הגוים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_46","074_10_46","ACT","10","46","46","כי שמעו אתם ממללים בלשנות ומגדלים את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC10_47","074_10_47","ACT","10","47","47","ויען פטרוס ויאמר היוכל איש למנע את המים מטבל את אלה אשר קבלו את רוח הקדש גם הם כמנו׃ ");
INSERT INTO heb_vpl VALUES ("AC10_48","074_10_48","ACT","10","48","48","ויצו לטבל אתם בשם האדון ויבקשו ממנו לשבת אתם ימים אחדים׃ ");
INSERT INTO heb_vpl VALUES ("AC11_1","074_11_1","ACT","11","1","1","וישמעו השליחים והאחים אשר ביהודה כי קבלו גם הגוים את דבר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC11_2","074_11_2","ACT","11","2","2","ויהי כאשר עלה פטרוס ירושלים ויריבו עמו בני המילה לאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC11_3","074_11_3","ACT","11","3","3","אל אנשים אשר להם ערלה באת ותאכל אתם לחם׃ ");
INSERT INTO heb_vpl VALUES ("AC11_4","074_11_4","ACT","11","4","4","ויחל פטרוס ויספר להם את כל אשר קרהו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC11_5","074_11_5","ACT","11","5","5","מתפלל הייתי בעיר יפו וארדם וארא מראה והנה כלי כדמות מטפחת בד גדולה יורד מן השמים ותורד בארבע כנפותיה ותבא עדי׃ ");
INSERT INTO heb_vpl VALUES ("AC11_6","074_11_6","ACT","11","6","6","והסתכלתי בה ואבין וארא את בהמת הארץ ואת החיה ורמש האדמה ועוף השמים׃ ");
INSERT INTO heb_vpl VALUES ("AC11_7","074_11_7","ACT","11","7","7","ואשמע גם קול האמר אלי קום פטרוס זבח ואכל׃ ");
INSERT INTO heb_vpl VALUES ("AC11_8","074_11_8","ACT","11","8","8","ואמר חלילה לי אדני כי כל פגול וטמא לא בא בפי מעולם׃ ");
INSERT INTO heb_vpl VALUES ("AC11_9","074_11_9","ACT","11","9","9","ויענני הקול שנית מן השמים ויאמר את אשר טהר האלהים אתה אל תטמאנו׃ ");
INSERT INTO heb_vpl VALUES ("AC11_10","074_11_10","ACT","11","10","10","וכן היה שלש פעמים והכל שב והעלה השמימה׃ ");
INSERT INTO heb_vpl VALUES ("AC11_11","074_11_11","ACT","11","11","11","והנה כרגע שלשה אנשים עמדים על פתח הבית אשר אנכי שם והמה שלוחים אלי מקסרין׃ ");
INSERT INTO heb_vpl VALUES ("AC11_12","074_11_12","ACT","11","12","12","ויאמר אלי הרוח ללכת אתם ולבלתי התמהמה וילכו אתי גם ששת האחים האלה ונבוא אל בית האיש׃ ");
INSERT INTO heb_vpl VALUES ("AC11_13","074_11_13","ACT","11","13","13","ויגד לנו את אשר ראה המלאך נצב בביתו ואמר אליו שלח אל יפו אנשים וקרא אליך את שמעון המכנה פטרוס׃ ");
INSERT INTO heb_vpl VALUES ("AC11_14","074_11_14","ACT","11","14","14","והוא ידבר אליך דברים אשר תושע בהם אתה וכל ביתך׃ ");
INSERT INTO heb_vpl VALUES ("AC11_15","074_11_15","ACT","11","15","15","וכאשר החלותי לדבר צלחה עליהם רוח הקדש כאשר צלחה עלינו בתחלה׃ ");
INSERT INTO heb_vpl VALUES ("AC11_16","074_11_16","ACT","11","16","16","ואזכר את דבר האדון אשר אמר יוחנן הטביל במים ואתם תטבלו ברוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC11_17","074_11_17","ACT","11","17","17","ועתה אם מתנה אחת נתן האלהים להם ולנו המאמינים באדון ישוע המשיח מי אנכי כי אעצר לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC11_18","074_11_18","ACT","11","18","18","ויהי כשמעם זאת ויחרישו ויהללו את האלהים ויאמרו אכן גם לגוים נתן האלהים התשובה לחיים׃ ");
INSERT INTO heb_vpl VALUES ("AC11_19","074_11_19","ACT","11","19","19","והנפוצים מפני הצרה אשר היתה על אודת אסטפנוס הלכו ובאו עד פינוקיא וקפרוס ואנטיוכיא ולא דברו את הדבר כי אם אל היהודים לבדם׃ ");
INSERT INTO heb_vpl VALUES ("AC11_20","074_11_20","ACT","11","20","20","ויהי בתוכם אנשי קפרוס וקוריני אשר באו אל אנטיוכיא וידברו גם אל היונים ויבשרו אתם את האדון ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC11_21","074_11_21","ACT","11","21","21","ותהי עמהם יד יהוה ומספר רב האמינו וישובו אל האדון׃ ");
INSERT INTO heb_vpl VALUES ("AC11_22","074_11_22","ACT","11","22","22","וישמע הדבר באזני הקהלה אשר בירושלים וישלחו את בר נבא אל אנטיוכיא׃ ");
INSERT INTO heb_vpl VALUES ("AC11_23","074_11_23","ACT","11","23","23","ויבא שמה וישמח כראתו את חסד האלהים ויזהר את כלם לדבקה באדון בלב נכון׃ ");
INSERT INTO heb_vpl VALUES ("AC11_24","074_11_24","ACT","11","24","24","כי איש טוב היה ומלא רוח הקדש ואמונה ויאספו לאדון עם רב׃ ");
INSERT INTO heb_vpl VALUES ("AC11_25","074_11_25","ACT","11","25","25","וילך בר נבא משם אל טרסוס לבקש את שאול וימצא אתו ויביאהו אל אנטיוכיא׃ ");
INSERT INTO heb_vpl VALUES ("AC11_26","074_11_26","ACT","11","26","26","ויהיו ישבים יחד בקהלה שנה תמימה ומלמדים עם רב אז הוחל באנטיוכיא לקרא את התלמידים בשם משיחיים׃ ");
INSERT INTO heb_vpl VALUES ("AC11_27","074_11_27","ACT","11","27","27","ויהי בימים ההם ויבאו נביאים מירושלים אל אנטיוכיא׃ ");
INSERT INTO heb_vpl VALUES ("AC11_28","074_11_28","ACT","11","28","28","ויקם אחד מהם ושמו אגבוס ויגד על פי הרוח כי רעב גדול יבוא על כל ישבי תבל ויהי כן בימי קלודיוס׃ ");
INSERT INTO heb_vpl VALUES ("AC11_29","074_11_29","ACT","11","29","29","ויועצו התלמידים לשלח איש איש מאשר תשיג ידו לעזרת האחים הישבים ביהודה׃ ");
INSERT INTO heb_vpl VALUES ("AC11_30","074_11_30","ACT","11","30","30","וכן גם עשו וישלחו אל הזקנים על ידי בר נבא ושאול׃ ");
INSERT INTO heb_vpl VALUES ("AC12_1","074_12_1","ACT","12","1","1","בעת ההיא שלח המלך הורדוס את ידו להרע לאנשים מן הקהל׃ ");
INSERT INTO heb_vpl VALUES ("AC12_2","074_12_2","ACT","12","2","2","וימת את יעקב אחי יוחנן בחרב׃ ");
INSERT INTO heb_vpl VALUES ("AC12_3","074_12_3","ACT","12","3","3","וירא כי טוב הדבר בעיני היהודים ויוסף לתפש גם את פטרוס והימים ימי חג המצות׃ ");
INSERT INTO heb_vpl VALUES ("AC12_4","074_12_4","ACT","12","4","4","ויאחז אתו ויתנהו במשמר וימסרהו לארבע מחלקות של ארבעה אנשי צבא לשמרו כי אמר להעלותו אחרי הפסח לפני העם׃ ");
INSERT INTO heb_vpl VALUES ("AC12_5","074_12_5","ACT","12","5","5","פטרוס היה עצור במשמר והקהלה העתירה בעדו בחזקה אל האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC12_6","074_12_6","ACT","12","6","6","ויהי בלילה ההוא אשר אמר הורדוס להביאו מחר לדין ויישן פטרוס בין שני אנשי צבא והוא אסור בשנים זקים ושמרי הפתח שמרים את המשמר׃ ");
INSERT INTO heb_vpl VALUES ("AC12_7","074_12_7","ACT","12","7","7","והנה מלאך יהוה נצב עליו ואור נגה בחדר ויספק על ירך פטרוס ויעירהו לאמר קום מהרה ויפלו מוסרותיו מעל ידיו׃ ");
INSERT INTO heb_vpl VALUES ("AC12_8","074_12_8","ACT","12","8","8","ויאמר אליו המלאך חגר מתניך והנעל את רגליך ויעש כן ויאמר אליו עטה מעילך ולך אחרי׃ ");
INSERT INTO heb_vpl VALUES ("AC12_9","074_12_9","ACT","12","9","9","ויצא וילך אחריו ולא ידע אם אמת הוא הנעשה לו על ידי המלאך כי כמראה היה בעיניו׃ ");
INSERT INTO heb_vpl VALUES ("AC12_10","074_12_10","ACT","12","10","10","ויעברו דרך המשמרת הראשונה והשניה ויבאו עד שער הברזל אשר יצאו בו העירה ויפתח השער לפניהם מאליו ויצאו החוצה וילכו מהלך רחוב אחד והמלאך סר מעליו פתאם׃ ");
INSERT INTO heb_vpl VALUES ("AC12_11","074_12_11","ACT","12","11","11","ויהי בשובו אל דעתו ויאמר פטרוס עתה זה ידעתי באמת כי האלהים שלח את מלאכו ויפלטני מיד הורדוס ומכל מזמת עם היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC12_12","074_12_12","ACT","12","12","12","הוא חשב כזאת והוא בא עד בית מרים אם יוחנן המכנה מרקוס אשר נקהלו שם רבים והם מתפללים יחד׃ ");
INSERT INTO heb_vpl VALUES ("AC12_13","074_12_13","ACT","12","13","13","וידפק על דלת השער ותגש נערה להקשיב ושמה רודי׃ ");
INSERT INTO heb_vpl VALUES ("AC12_14","074_12_14","ACT","12","14","14","ותכר את קול פטרוס ומשמחתה לא פתחה לו אם דלת השער ותרץ הביתה ותגד להם כי פטרוס עמד על השער׃ ");
INSERT INTO heb_vpl VALUES ("AC12_15","074_12_15","ACT","12","15","15","ויאמרו אליה משגעת את והיא מתאמצת כי כן הוא ויאמרו מלאכו הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC12_16","074_12_16","ACT","12","16","16","ופטרוס הרבה לדפק ויפתחו ויראהו וישתוממו׃ ");
INSERT INTO heb_vpl VALUES ("AC12_17","074_12_17","ACT","12","17","17","והוא רמז להם בידו לחשות ויספר להם את אשר הוציאו האדון מן המשמר ויאמר הגידו את זאת ליעקב ולאחים ויצא וילך לו למקום אחר׃ ");
INSERT INTO heb_vpl VALUES ("AC12_18","074_12_18","ACT","12","18","18","הבקר אור ומבוכה לא קטנה היתה בין אנשי הצבא על פטרוס מה היה לו׃ ");
INSERT INTO heb_vpl VALUES ("AC12_19","074_12_19","ACT","12","19","19","ויהי כאשר בקש אותו הורדוס ולא מצאו חקר את השמרים ויצו להוציאם למות וירד מיהודה אל קסרין וישב שם׃ ");
INSERT INTO heb_vpl VALUES ("AC12_20","074_12_20","ACT","12","20","20","ואיבה היתה בין הורדוס ובין בני צור וצידון ויבאו אליו בלב אחד ויפתו את בלסטוס אשר על חדר המלך ויבקשו שלום יען לקחו מחית ארצותם מארץ המלך׃ ");
INSERT INTO heb_vpl VALUES ("AC12_21","074_12_21","ACT","12","21","21","ויהי ביום המועד וילבש הורדוס לבוש מלכות וישב על כסא המשפט ויטף אליהם אמרתו׃ ");
INSERT INTO heb_vpl VALUES ("AC12_22","074_12_22","ACT","12","22","22","ויריעו לו העם לאמר קול אלהים הוא ולא קול אדם׃ ");
INSERT INTO heb_vpl VALUES ("AC12_23","074_12_23","ACT","12","23","23","ויכהו מלאך יהוה פתאם עקב אשר לא נתן הכבוד לאלהים ויאכלהו תולעים ויגוע׃ ");
INSERT INTO heb_vpl VALUES ("AC12_24","074_12_24","ACT","12","24","24","ודבר אלהים הולך ורב׃ ");
INSERT INTO heb_vpl VALUES ("AC12_25","074_12_25","ACT","12","25","25","וישובו בר נבא ושאול מירושלים אחרי כלותם את השמוש ויקחו אתם את יוחנן המכנה מרקוס׃ ");
INSERT INTO heb_vpl VALUES ("AC13_1","074_13_1","ACT","13","1","1","ואנשים נביאים ומלמדים היו באנטיוכיא בקהלה אשר בה בר נבא ושמעון הנקרא ניגר ולוקיוס הקוריני ומנחם אשר גדל עם הורדוס שר הרבע ושאול׃ ");
INSERT INTO heb_vpl VALUES ("AC13_2","074_13_2","ACT","13","2","2","ויהי בשרתם את יהוה ובצומם ויאמר רוח הקדש הבדילו לי את בר נבא ואת שאול למלאכה אשר קראתים לה׃ ");
INSERT INTO heb_vpl VALUES ("AC13_3","074_13_3","ACT","13","3","3","ויצומו ויתפללו ויסמכו את ידיהם עליהם וישלחום׃ ");
INSERT INTO heb_vpl VALUES ("AC13_4","074_13_4","ACT","13","4","4","והמה המשלחים על ידי רוח הקדש ירדו אל סלוקיא ומשם באו באניה אל קפרוס׃ ");
INSERT INTO heb_vpl VALUES ("AC13_5","074_13_5","ACT","13","5","5","ויבאו אל עיר סלמיס ויגידו את דבר האלהים בבתי הכנסיות אשר ליהודים ויהי להם גם יוחנן למשרת׃ ");
INSERT INTO heb_vpl VALUES ("AC13_6","074_13_6","ACT","13","6","6","ויעברו בכל האי עד פפוס וימצאו איש מגוש אחד נביא שקר איש יהודי ושמו בר ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC13_7","074_13_7","ACT","13","7","7","אשר היה עם סרגיוס פולוס שר המדינה איש נבון והוא קרא אליו את בר נבא ואת שאול ויתאו לשמע את דבר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_8","074_13_8","ACT","13","8","8","ויעמד לנגדם אלימא המגוש כי זה תרגום שמו ויבקש להטות את השר מן האמונה׃ ");
INSERT INTO heb_vpl VALUES ("AC13_9","074_13_9","ACT","13","9","9","ושאול הנקרא גם פולוס מלא רוח הקדש ויסתכל בו׃ ");
INSERT INTO heb_vpl VALUES ("AC13_10","074_13_10","ACT","13","10","10","ויאמר אתה המלא כל מרמה וכל עולה בן בליעל ושונא כל צדק הלא תחדל לסלף את דרכי יהוה הישרים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_11","074_13_11","ACT","13","11","11","ועתה הנה יד יהוה בך והיית עור ולא תראה את השמש עד עת מועד ותפל עליו פתאם אפלה וחשכה ויפן הנה והנה ויבקש איש להוליכו בידו׃ ");
INSERT INTO heb_vpl VALUES ("AC13_12","074_13_12","ACT","13","12","12","והשר כאשר ראה את המעשה האמין וישתומם על תורת האדון׃ ");
INSERT INTO heb_vpl VALUES ("AC13_13","074_13_13","ACT","13","13","13","ויצאו פולוס והאנשים אשר אתו מפפוס וירדו באניה ויבאו אל פרגי אשר בפמפוליא ויעזב אתם יוחנן וישב ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_14","074_13_14","ACT","13","14","14","והמה נסעו מפרגי ויבאו אל אנטיוכיא אשר בפיסדיא ויבאו אל בית הכנסת ביום השבת וישבו׃ ");
INSERT INTO heb_vpl VALUES ("AC13_15","074_13_15","ACT","13","15","15","ויהי אחר קריאת התורה והנביאים וישלחו אליהם ראשי הכנסת לאמר אנשים אחים אם יש לכם דבר מוסר לעם דברו׃ ");
INSERT INTO heb_vpl VALUES ("AC13_16","074_13_16","ACT","13","16","16","ויקם פולוס וינף ידו ויאמר אנשי ישראל ויראי אלהים שמעו׃ ");
INSERT INTO heb_vpl VALUES ("AC13_17","074_13_17","ACT","13","17","17","אלהי העם הזה אלהי ישראל בחר באבותינו וירומם את העם בהיותם גרים בארץ מצרים ובזרוע רמה הוציאם משם׃ ");
INSERT INTO heb_vpl VALUES ("AC13_18","074_13_18","ACT","13","18","18","וישא אתם ויכלכלם במדבר כארבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("AC13_19","074_13_19","ACT","13","19","19","וישמד שבעה גוים בארץ כנען ויחלק את ארצם להם לנחלה׃ ");
INSERT INTO heb_vpl VALUES ("AC13_20","074_13_20","ACT","13","20","20","ואחרי כן נתן להם שפטים כארבע מאות וחמשים שנה עד ימי שמואל הנביא׃ ");
INSERT INTO heb_vpl VALUES ("AC13_21","074_13_21","ACT","13","21","21","וישאלו מלך ויתן להם אלהים את שאול בן קיש איש משבט בנימן ארבעים שנה׃ ");
INSERT INTO heb_vpl VALUES ("AC13_22","074_13_22","ACT","13","22","22","וכהסירו אותו ויקם את דוד למלך עליהם אשר גם העיד עליו לאמר מצאתי דוד את בן ישי איש כלבבי והוא יעשה את כל חפצי׃ ");
INSERT INTO heb_vpl VALUES ("AC13_23","074_13_23","ACT","13","23","23","וזה הוא אשר מזרעו הקים האלהים כפי ההבטחה גואל לישראל את ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC13_24","074_13_24","ACT","13","24","24","אשר לפני בואו קדם יוחנן לקרא את טבילת התשובה אל כל עם ישראל׃ ");
INSERT INTO heb_vpl VALUES ("AC13_25","074_13_25","ACT","13","25","25","ויהי ככלות יוחנן את מרוצתו ויאמר למי תחשבוני לא אני הוא כי הנה הוא בא אחרי ואני נקלתי מהתיר את נעלי רגליו׃ ");
INSERT INTO heb_vpl VALUES ("AC13_26","074_13_26","ACT","13","26","26","אנשים אחים בני משפחת אברהם ויראי אלהים אשר בקרבכם לכם שלוח דבר הישועה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("AC13_27","074_13_27","ACT","13","27","27","כי ישבי ירושלים וראשיהם יען אשר לא הכירהו מלאו במשפטם אשר שפטהו את דברי הנביאים הנקראים בכל שבת׃ ");
INSERT INTO heb_vpl VALUES ("AC13_28","074_13_28","ACT","13","28","28","ואף כי לא מצאו בו משפט מות שאלו מאת פילטוס להמיתו׃ ");
INSERT INTO heb_vpl VALUES ("AC13_29","074_13_29","ACT","13","29","29","וכאשר השלימו את כל הדברים הכתובים עליו הורידו אותו מן העץ ויניחהו בקבר׃ ");
INSERT INTO heb_vpl VALUES ("AC13_30","074_13_30","ACT","13","30","30","אבל האלהים הקימו מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_31","074_13_31","ACT","13","31","31","וירא ימים רבים אל העלים אתו מן הגליל ירושלימה והמה עתה עדיו אל העם׃ ");
INSERT INTO heb_vpl VALUES ("AC13_32","074_13_32","ACT","13","32","32","ואנחנו מבשרים אתכם את בשורת ההבטחה אשר היתה לאבותינו כי אתה מלא האלהים לבנינו בהקימו את ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC13_33","074_13_33","ACT","13","33","33","ככתוב במזמור השני בני אתה היום ילדתיך׃ ");
INSERT INTO heb_vpl VALUES ("AC13_34","074_13_34","ACT","13","34","34","ועל אשר הקים אתו מן המתים לבלתי שוב עוד לשחת כה אמר אתן לכם חסדי דוד הנאמנים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_35","074_13_35","ACT","13","35","35","על כן הוא אמר גם במקום אחר לא תתן חסידך לראות שחת׃ ");
INSERT INTO heb_vpl VALUES ("AC13_36","074_13_36","ACT","13","36","36","כי דוד גוע אחרי שרתו בדורו לעצת האלהים ויאסף אל אבותיו וירא את השחת׃ ");
INSERT INTO heb_vpl VALUES ("AC13_37","074_13_37","ACT","13","37","37","ואשר האלהים הקים אותו הוא לא ראה השחת׃ ");
INSERT INTO heb_vpl VALUES ("AC13_38","074_13_38","ACT","13","38","38","לכן אנשים אחים יודע לכם כי על ידי זה הגד לכם סליחת החטאים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_39","074_13_39","ACT","13","39","39","ובכל אשר לא יכלתם להצטדק בתורת משה כל המאמין יצדק על ידו׃ ");
INSERT INTO heb_vpl VALUES ("AC13_40","074_13_40","ACT","13","40","40","לכן השמרו לכם פן יבוא עליכם הנאמר בנביאים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_41","074_13_41","ACT","13","41","41","ראו בגדים והתמהו ושמו כי פעל פעל אני בימיכם פעל אשר לא תאמינו כי יספר לכם׃ ");
INSERT INTO heb_vpl VALUES ("AC13_42","074_13_42","ACT","13","42","42","ובצאת היהודים מבית הכנסת בקשו מהם הגוים לדבר אליהם את הדברים האלה בשבת הבאה׃ ");
INSERT INTO heb_vpl VALUES ("AC13_43","074_13_43","ACT","13","43","43","ורבים מן היהודים ומגרי הצדק הלכו אחרי פולוס ובר נבא בהפרד הקהל והמה דברו על לבם ויזהירום לעמד בחסד האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_44","074_13_44","ACT","13","44","44","ובשבת השנית נקהלה כמעט כל העיר לשמע את דבר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AC13_45","074_13_45","ACT","13","45","45","ויהי כראות היהודים את המון העם וימלאו קנאה ויכחישו את דברי פולוס הכחש וגדף׃ ");
INSERT INTO heb_vpl VALUES ("AC13_46","074_13_46","ACT","13","46","46","אז הגידו פולוס ובר נבא על פניהם לאמר בדין היה להשמיע אתכם בראשונה את דבר האלהים ועתה אחרי אשר מאסתם אותו ואינכם זכים בעיניכם לחיי העולם לכן הננו פנים אל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("AC13_47","074_13_47","ACT","13","47","47","כי כן צוה עלינו האדון נתתיך לאור גוים להיות ישועתי עד קצה הארץ׃ ");
INSERT INTO heb_vpl VALUES ("AC13_48","074_13_48","ACT","13","48","48","וישמחו הגוים כשמעם ויהללו את דבר יהוה ויאמינו כל אשר היו מוכנים לחיי עולם׃ ");
INSERT INTO heb_vpl VALUES ("AC13_49","074_13_49","ACT","13","49","49","ויפרץ דבר יהוה בכל המקום׃ ");
INSERT INTO heb_vpl VALUES ("AC13_50","074_13_50","ACT","13","50","50","אך היהודים הסיתו את הנשים החסידות והחשובות ואת אצילי העיר ויעוררו רדיפה על פולוס ובר נבא ויגרשום מגבולם׃ ");
INSERT INTO heb_vpl VALUES ("AC13_51","074_13_51","ACT","13","51","51","והמה נערו עליהם את העפר מעל רגליהם וילכו לאיקניון׃ ");
INSERT INTO heb_vpl VALUES ("AC13_52","074_13_52","ACT","13","52","52","והתלמידים מלאו שמחה ורוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC14_1","074_14_1","ACT","14","1","1","ויהי באיקניון ויבאו יחדו אל בית כנסת היהודים וידברו שם עד כי האמין המון רב מן היהודים ומן היונים׃ ");
INSERT INTO heb_vpl VALUES ("AC14_2","074_14_2","ACT","14","2","2","אך היהודים אשר לא האמינו עוררו והכעיסו את נפשות הגוים על האחים׃ ");
INSERT INTO heb_vpl VALUES ("AC14_3","074_14_3","ACT","14","3","3","וישבו שם ימים רבים וילמדו בבטחונם ביהוה העמיד על דבר חסדו בעשותו על ידם אתות ומופתים׃ ");
INSERT INTO heb_vpl VALUES ("AC14_4","074_14_4","ACT","14","4","4","ויחלק המון העיר לחצי אלה נטו אחרי היהודים ואלה אחרי השליחים׃ ");
INSERT INTO heb_vpl VALUES ("AC14_5","074_14_5","ACT","14","5","5","ויהי רגשת הגוים והיהודים עם ראשיהם להתעלל בהם ולסקלם׃ ");
INSERT INTO heb_vpl VALUES ("AC14_6","074_14_6","ACT","14","6","6","ויודע להם ויברחו לערי לוקוניא אל לוסטרא ודרבי וסביבותן׃ ");
INSERT INTO heb_vpl VALUES ("AC14_7","074_14_7","ACT","14","7","7","ויבשרו שם הבשורה׃ ");
INSERT INTO heb_vpl VALUES ("AC14_8","074_14_8","ACT","14","8","8","ואיש נכה רגלים היה בלוסטרא והוא ישב פסח מבטן אמו ולא הלך מימיו׃ ");
INSERT INTO heb_vpl VALUES ("AC14_9","074_14_9","ACT","14","9","9","וישמע את פולוס מדבר והוא הסתכל בו וירא כי אמונה בו להושע׃ ");
INSERT INTO heb_vpl VALUES ("AC14_10","074_14_10","ACT","14","10","10","ויאמר בקול גדול עמד הכן על רגליך וידלג ויתהלך׃ ");
INSERT INTO heb_vpl VALUES ("AC14_11","074_14_11","ACT","14","11","11","והמון העם כראותם את אשר עשה פולוס נשאו את קולם ויאמרו בלשון לוקונית ירדו אלינו האלהים בדמות אנשים׃ ");
INSERT INTO heb_vpl VALUES ("AC14_12","074_14_12","ACT","14","12","12","ויקראו לבר נבא בל ולפולוס קראו הרמיס באשר הוא ראש המדברים׃ ");
INSERT INTO heb_vpl VALUES ("AC14_13","074_14_13","ACT","14","13","13","וכהן בית בל אשר מחוץ לעירם הביא השערה שורים ועטרות ויחפץ לזבח הוא והמון העם׃ ");
INSERT INTO heb_vpl VALUES ("AC14_14","074_14_14","ACT","14","14","14","ויהי כשמע זאת השליחים פולוס ובר נבא ויקרעו את בגדיהם וירוצו אל תוך העם׃ ");
INSERT INTO heb_vpl VALUES ("AC14_15","074_14_15","ACT","14","15","15","ויצעקו לאמר אנשים למה תעשו כזאת גם אנחנו בני אדם חלשים כמוכם ונבשרה אתכם למען שוב תשובו מן הבליכם אלה אל אלהים חיים אשר עשה את השמים ואת הארץ ואת הים ואת כל אשר בם׃ ");
INSERT INTO heb_vpl VALUES ("AC14_16","074_14_16","ACT","14","16","16","ואשר בדרות קדם הניח לכל הגוים ללכת בדרכיהם׃ ");
INSERT INTO heb_vpl VALUES ("AC14_17","074_14_17","ACT","14","17","17","וגם לא חדל להעיד על עצמו וייטב לנו בתתו מטר מן השמים ועתות שבע וימלא לבותינו מזון וששון׃ ");
INSERT INTO heb_vpl VALUES ("AC14_18","074_14_18","ACT","14","18","18","ואף בדברים האלה כמעט לא עצרו כח לכלוא את העם מזבח להם׃ ");
INSERT INTO heb_vpl VALUES ("AC14_19","074_14_19","ACT","14","19","19","ויבאו שמה יהודים מן אנטיוכיא ומן איקניון ויסיתו את העם וירגמו את פולוס באבנים ויסחבהו חוצה לעיר בחשבם כי מת׃ ");
INSERT INTO heb_vpl VALUES ("AC14_20","074_14_20","ACT","14","20","20","ויסבו אתו התלמידים ויקם ויבא העירה וממחרת יצא אל דרבי הוא ובר נבא׃ ");
INSERT INTO heb_vpl VALUES ("AC14_21","074_14_21","ACT","14","21","21","ויבשרו את הבשורה בעיר ההיא ואחרי העמידם תלמידים הרבה שבו אל לוסטרא ואיקניון ואנטיוכיא׃ ");
INSERT INTO heb_vpl VALUES ("AC14_22","074_14_22","ACT","14","22","22","ויחזקו את נפשות התלמידים ויזהירו אתם לעמד באמונה וכי רק בצרות רבות בוא נבוא אל מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC14_23","074_14_23","ACT","14","23","23","ויבחרו להם זקנים בכל קהלה וקהלה ויתפללו ויצומו ויפקידום ביד האדון אשר האמינו בו׃ ");
INSERT INTO heb_vpl VALUES ("AC14_24","074_14_24","ACT","14","24","24","ויעברו בפיסדיא ויבאו אל פמפוליא׃ ");
INSERT INTO heb_vpl VALUES ("AC14_25","074_14_25","ACT","14","25","25","וישמיעו את דבר יהוה בפרגי וירדו אל אטליא׃ ");
INSERT INTO heb_vpl VALUES ("AC14_26","074_14_26","ACT","14","26","26","ומשם באו באניה אל אנטיוכיא אשר נמסרו שם לחסד אלהים על המלאכה אשר מלאו אתה׃ ");
INSERT INTO heb_vpl VALUES ("AC14_27","074_14_27","ACT","14","27","27","ובבאם שמה הקהילו את העדה ויגידו את כל אשר עשה אתם האלהים ואת אשר פתח לגוים פתח האמונה׃ ");
INSERT INTO heb_vpl VALUES ("AC14_28","074_14_28","ACT","14","28","28","וישבו שם עם התלמידים ימים לא מעטים׃ ");
INSERT INTO heb_vpl VALUES ("AC15_1","074_15_1","ACT","15","1","1","ואנשים ירדו מיהודה וילמדו את האחים לאמר אם לא תמולו כדת משה לא תושעון׃ ");
INSERT INTO heb_vpl VALUES ("AC15_2","074_15_2","ACT","15","2","2","ויהי על זאת ריב ומחלקת לא קלה לפולוס ולבר נבא עמהם ויגזרו כי פולוס ובר נבא ואחרים מהם יעלו ירושלים אל השליחים והזקנים על אדות השאלה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("AC15_3","074_15_3","ACT","15","3","3","ותלוה אתם הקהלה ויעברו את פינוקיא ואת שמרון מספרים את תשובת הגוים וישמחו את כל האחים שמחה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("AC15_4","074_15_4","ACT","15","4","4","ויהי כבאם ירושלים ויקבלו אתם הקהלה והשליחים והזקנים ויגידו להם את אשר הגדיל האלהים לעשות עמהם׃ ");
INSERT INTO heb_vpl VALUES ("AC15_5","074_15_5","ACT","15","5","5","ויקומו אנשים מאמינים מכת הפרושים ויאמרו כי חובה היא למול אתם ולצותם לשמר את תורת משה׃ ");
INSERT INTO heb_vpl VALUES ("AC15_6","074_15_6","ACT","15","6","6","ויקהלו השליחים והזקנים לעין בדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC15_7","074_15_7","ACT","15","7","7","ויהי ברבות המחלקת קם פטרוס ויאמר אליהם אנשים אחים אתם ידעתם כי מימים ראשים בי בחר האלהים מכלנו אשר ישמעו הגוים מפי את דבר הבשורה ויאמינו׃ ");
INSERT INTO heb_vpl VALUES ("AC15_8","074_15_8","ACT","15","8","8","והאלהים ידע הלבבות העיד עליהם בתתו גם להם את רוח הקדש כאשר נתן לנו׃ ");
INSERT INTO heb_vpl VALUES ("AC15_9","074_15_9","ACT","15","9","9","ולא הבדיל בינינו וביניהם כי טהר את לבבם על ידי האמונה׃ ");
INSERT INTO heb_vpl VALUES ("AC15_10","074_15_10","ACT","15","10","10","ועתה מה תנסו את האלהים לשום על על צוארי התלמידים אשר גם אבותינו גם אנחנו לא יכלנו לשאת׃ ");
INSERT INTO heb_vpl VALUES ("AC15_11","074_15_11","ACT","15","11","11","אבל בחסד ישוע המשיח אדנינו נאמין להושע כמוהם כמונו׃ ");
INSERT INTO heb_vpl VALUES ("AC15_12","074_15_12","ACT","15","12","12","ויחרישו כל הקהל וישמעו אל בר נבא ואל פולוס מספרים את האתות והמופתים אשר הרבה האלהים לעשות על ידיהם בקרב הגוים׃ ");
INSERT INTO heb_vpl VALUES ("AC15_13","074_15_13","ACT","15","13","13","ויכלו לדבר ויען יעקב ויאמר אנשים אחים שמעו אלי׃ ");
INSERT INTO heb_vpl VALUES ("AC15_14","074_15_14","ACT","15","14","14","שמעון ספר איך האלהים ראה לו בראשונה לקחת מבין הגוים עם לשמו׃ ");
INSERT INTO heb_vpl VALUES ("AC15_15","074_15_15","ACT","15","15","15","ולזאת מסכימים דברי הנביאים ככתוב׃ ");
INSERT INTO heb_vpl VALUES ("AC15_16","074_15_16","ACT","15","16","16","אחרי זאת אשוב ואקים את סכת דויד הנפלת והרסותיה אקים ובניתיה׃ ");
INSERT INTO heb_vpl VALUES ("AC15_17","074_15_17","ACT","15","17","17","למען ידרשו שארית אדם את יהוה וכל הגוים אשר נקרא שמי עליהם נאם יהוה עשה כל אלה׃ ");
INSERT INTO heb_vpl VALUES ("AC15_18","074_15_18","ACT","15","18","18","נודעים לאלהים מעולם כל מעשיו׃ ");
INSERT INTO heb_vpl VALUES ("AC15_19","074_15_19","ACT","15","19","19","ועל כן אני דן שלא להחמיר על השבים מן הגוים לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC15_20","074_15_20","ACT","15","20","20","רק לכתב אליהם אשר ירחקו מטמאת האלילים ומן הזנות ומבשר הנחנק ומן הדם׃ ");
INSERT INTO heb_vpl VALUES ("AC15_21","074_15_21","ACT","15","21","21","כי משה מדרת עולם יש לו מגידיו בכל עיר ועיר ויקרא בבתי הכנסיות מדי שבת בשבתו׃ ");
INSERT INTO heb_vpl VALUES ("AC15_22","074_15_22","ACT","15","22","22","וייטב בעיני השליחים והזקנים עם כל הקהל לבחר מהם אנשים ולשלח אתם אל אנטיוכיא עם פולוס ובר נבא את יהודה המכנה בר שבא ואת סילא אנשי שם בין האחים׃ ");
INSERT INTO heb_vpl VALUES ("AC15_23","074_15_23","ACT","15","23","23","ויכתבו וישלחו על ידם לאמר אנחנו השליחים והזקנים והאחים שאלים לשלום האחים אשר מן הגוים באנטיוכיא ובסוריא ובקיליקיא׃ ");
INSERT INTO heb_vpl VALUES ("AC15_24","074_15_24","ACT","15","24","24","יען וביען שמענו כי יצאו מאתנו מבלבלים אתכם ומקלקלים נפשתיכם בדברים באמרם לכם להמול ולשמר את התורה אשר לא צוינו אותם׃ ");
INSERT INTO heb_vpl VALUES ("AC15_25","074_15_25","ACT","15","25","25","לכן טוב בעיני כלנו יחדו לבחר אנשים לשלחם אליכם עם חביבינו בר נבא ופולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC15_26","074_15_26","ACT","15","26","26","אנשים אשר מסרו נפשם על שם אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC15_27","074_15_27","ACT","15","27","27","על כן שלחנו את יהודה ואת סילא אשר גם המה יגידו זאת בפיהם׃ ");
INSERT INTO heb_vpl VALUES ("AC15_28","074_15_28","ACT","15","28","28","כי טוב לפני רוח הקדש ולפנינו לבלתי שום עליכם משא אחר לבד מאלה הדברים הצריכים׃ ");
INSERT INTO heb_vpl VALUES ("AC15_29","074_15_29","ACT","15","29","29","אשר תרחקו מזבחי אלילים ומן הדם ומבשר הנחנק ומן הזנות אם מאלה תשמרו את נפשתיכם תיטיבו לעשות ושלום לכם׃ ");
INSERT INTO heb_vpl VALUES ("AC15_30","074_15_30","ACT","15","30","30","וישלחו האנשים ויבאו אל אנטיוכיא ויקהילו את העם ויתנו להם את האגרת׃ ");
INSERT INTO heb_vpl VALUES ("AC15_31","074_15_31","ACT","15","31","31","ויקראו אתה וישמחו על הנחמה׃ ");
INSERT INTO heb_vpl VALUES ("AC15_32","074_15_32","ACT","15","32","32","ויהודה וסילא אשר גם הם נביאים נחמו האחים בדברים רבים ויחזקום׃ ");
INSERT INTO heb_vpl VALUES ("AC15_33","074_15_33","ACT","15","33","33","ויהיו שם ימים אחדים וישלחום האחים בשלום אל השליחים׃ ");
INSERT INTO heb_vpl VALUES ("AC15_34","074_15_34","ACT","15","34","34","וייטב בעיני סילא לשבת שם׃ ");
INSERT INTO heb_vpl VALUES ("AC15_35","074_15_35","ACT","15","35","35","ופולוס ובר נבא ישבו באנטיוכיא וילמדו ויבשרו את דבר יהוה המה וגם רבים אחרים עמם׃ ");
INSERT INTO heb_vpl VALUES ("AC15_36","074_15_36","ACT","15","36","36","ויהי מקץ ימים ויאמר פולוס אל בר נבא לכה ונשובה ונפקדה את אחינו בכל עיר ועיר אשר קראנו שם את דבר יהוה ונראה מה המה׃ ");
INSERT INTO heb_vpl VALUES ("AC15_37","074_15_37","ACT","15","37","37","ובר נבא יעץ לקחת אתם את יוחנן המכנה מרקוס׃ ");
INSERT INTO heb_vpl VALUES ("AC15_38","074_15_38","ACT","15","38","38","אך פולוס לא אבה לקחת אתם את האיש אשר סר מעליהם בפמפוליא ולא הלך אתם במלאכתם׃ ");
INSERT INTO heb_vpl VALUES ("AC15_39","074_15_39","ACT","15","39","39","ויהי רגז עד אשר נפרדו איש מאחיו ויקח בר נבא את מרקוס ויסע באניה אל קפרוס׃ ");
INSERT INTO heb_vpl VALUES ("AC15_40","074_15_40","ACT","15","40","40","ופולוס בחר לו את סילא וימסרהו האחים אל חסד יהוה ויצא׃ ");
INSERT INTO heb_vpl VALUES ("AC15_41","074_15_41","ACT","15","41","41","ויעבר בסוריא ובקיליקיא ויחזק את הקהלות׃ ");
INSERT INTO heb_vpl VALUES ("AC16_1","074_16_1","ACT","16","1","1","ויבא אל דרבי ואל לוסטרא והנה שם תלמיד אחד ושמו טימותיוס והוא בן אשה יהודית מאמנת ואביו יוני׃ ");
INSERT INTO heb_vpl VALUES ("AC16_2","074_16_2","ACT","16","2","2","ויהי לו שם טוב בין האחים אשר בלוסטרא ובאיקניון׃ ");
INSERT INTO heb_vpl VALUES ("AC16_3","074_16_3","ACT","16","3","3","בו בחר פולוס אשר יצא אתו ויקח וימל אתו בעבור היהודים אשר במקמות ההם כי כלם ידעו את אביו כי יוני הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC16_4","074_16_4","ACT","16","4","4","ויהי בעברם בערים וימסרו להם לשמר את הפקודים אשר גזרו השליחים והזקנים אשר בירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC16_5","074_16_5","ACT","16","5","5","ותתחזקנה הקהלות באמונה וירב מספרן יום יום׃ ");
INSERT INTO heb_vpl VALUES ("AC16_6","074_16_6","ACT","16","6","6","ויעברו בפרוגיא ובארץ גלטיא כי מנעם רוח הקדש מהשמיע את הדבר באסיא׃ ");
INSERT INTO heb_vpl VALUES ("AC16_7","074_16_7","ACT","16","7","7","וכבאם אל מוסיא הואילו ללכת אל ביתוניא ולא הניח להם הרוח׃ ");
INSERT INTO heb_vpl VALUES ("AC16_8","074_16_8","ACT","16","8","8","ויחלפו ממוסיא וירדו אל טרואס׃ ");
INSERT INTO heb_vpl VALUES ("AC16_9","074_16_9","ACT","16","9","9","וחזון נראה אל פולוס בלילה והנה איש מוקדון נצב והוא מבקש ממנו לאמר עבר אל מקדוניא ועזרנו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_10","074_16_10","ACT","16","10","10","וכראתו את המחזה מיד בקשנו ללכת אל מקדוניא בהביננו כי האלהים קראנו שמה לבשר אתם הבשורה׃ ");
INSERT INTO heb_vpl VALUES ("AC16_11","074_16_11","ACT","16","11","11","ונצא מן טרואס ונרד באניה ונבא דרך ישרה אל סמותרקיא וממחרת אל נפוליס׃ ");
INSERT INTO heb_vpl VALUES ("AC16_12","074_16_12","ACT","16","12","12","ומשם אל פילפי ראשית ערי הפלך של מקדוניא והיא בת חורין ונשב בעיר הזאת ימים אחדים׃ ");
INSERT INTO heb_vpl VALUES ("AC16_13","074_16_13","ACT","16","13","13","וביום השבת יצאנו אל מחוץ לעיר אל יד הנהר אשר שם מקום תפלה כמנהגם ונשב ונדבר אל הנשים הנקהלות שמה׃ ");
INSERT INTO heb_vpl VALUES ("AC16_14","074_16_14","ACT","16","14","14","ואשה יראת אליהם ושמה לודיא מכרת ארגמן מעיר תיאטירא שמעה ויפתח יהוה את לבה להקשיב אל דברי פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC16_15","074_16_15","ACT","16","15","15","ותטבל היא ובני ביתה ותבקש ממנו לאמר אם חשבתם אתי נאמנה לאדון באו נא אל ביתי ושבו בו ותפצר בנו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_16","074_16_16","ACT","16","16","16","ויהי בלכתנו למקום התפלה ותפגע בנו שפחה בעלת אוב אשר עשתה הון רב לאדניה בקסמיה׃ ");
INSERT INTO heb_vpl VALUES ("AC16_17","074_16_17","ACT","16","17","17","ותלך אחרי פולוס ואחרינו הלוך וקרוא לאמר האנשים האלה עבדי אל עליון המה המודיעים אתנו ארח הישועה׃ ");
INSERT INTO heb_vpl VALUES ("AC16_18","074_16_18","ACT","16","18","18","וכן עשתה ימים רבים וירע בעיני פולוס הדבר הזה ויפן ויאמר אל הרוח אנכי מצוך בשם ישוע המשיח לצאת ממנה ויצא בשעה ההיא׃ ");
INSERT INTO heb_vpl VALUES ("AC16_19","074_16_19","ACT","16","19","19","ויראו אדניה כי אזלה תוחלת בצעם ויתפשו את פולוס ואת סילא ויסחבום אל הרחוב לפני זקני העיר׃ ");
INSERT INTO heb_vpl VALUES ("AC16_20","074_16_20","ACT","16","20","20","ויביאום אל השרים ויאמרו האנשים האלה עכרים את עירנו והם יהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC16_21","074_16_21","ACT","16","21","21","ומודיעים חקות אשר לא נכון לנו לקבלם ולעשתם כי רומיים אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_22","074_16_22","ACT","16","22","22","ויקם גם העם עליהם והשרים קרעו את בגדיהם מעליהם ויצוו להכותם בשוטים׃ ");
INSERT INTO heb_vpl VALUES ("AC16_23","074_16_23","ACT","16","23","23","ויהי אחרי הכות אתם מכה רבה וישליכום במשמר ויצוו את שומר האסורים לשמרם היטב׃ ");
INSERT INTO heb_vpl VALUES ("AC16_24","074_16_24","ACT","16","24","24","והוא כאשר צוה כן השליכם בחדר המשמר הפנימי וישם את רגליהם בסד׃ ");
INSERT INTO heb_vpl VALUES ("AC16_25","074_16_25","ACT","16","25","25","ויהי כחצות הלילה ויתפללו פולוס וסילא ויזמרו לאלהים והאסורים מקשיבים אליהם׃ ");
INSERT INTO heb_vpl VALUES ("AC16_26","074_16_26","ACT","16","26","26","ופתאם היה רעש גדול עד אשר זעו מוסדות בית הכלא וכרגע נפתחו כל הדלתות ומוסרות כלם נתקו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_27","074_16_27","ACT","16","27","27","ושומר האסורים נעור משנתו ויהי כראתו את דלתות המשמר נפתחות וישלף חרבו ויבקש לאבד את עצמו בחשבו כי ברחו האסורים׃ ");
INSERT INTO heb_vpl VALUES ("AC16_28","074_16_28","ACT","16","28","28","ויקרא פולוס בקול גדול לאמר אל תעש לך מאומה רע כי פה אנחנו כלנו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_29","074_16_29","ACT","16","29","29","וישאל נרות וידלג פנימה והוא מרעיד ויפל לרגלי פולוס וסילא׃ ");
INSERT INTO heb_vpl VALUES ("AC16_30","074_16_30","ACT","16","30","30","ויוציאם החוצה ויאמר אדני מה עלי לעשות למען אושע׃ ");
INSERT INTO heb_vpl VALUES ("AC16_31","074_16_31","ACT","16","31","31","ויאמרו האמן באדון ישוע המשיח ותושע אתה וביתך׃ ");
INSERT INTO heb_vpl VALUES ("AC16_32","074_16_32","ACT","16","32","32","ויגידו לו את דבר יהוה ולכל אשר בביתו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_33","074_16_33","ACT","16","33","33","ויקחם בלילה בשעה ההיא וירחץ את חבורתיהם וימהר להטבל הוא וכל אשר לו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_34","074_16_34","ACT","16","34","34","ויעלם אל ביתו וישם שלחן לפניהם ויגל עם כל ביתו על היותו מאמין באלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC16_35","074_16_35","ACT","16","35","35","ובחית הבקר שלחו השרים את השוטרים לאמר שלח את האנשים ההם׃ ");
INSERT INTO heb_vpl VALUES ("AC16_36","074_16_36","ACT","16","36","36","ויגד שמר האסורים לפולוס את הדברים האלה לאמר שלחו השרים לפטר אתכם ועתה צאו ולכו בשלום׃ ");
INSERT INTO heb_vpl VALUES ("AC16_37","074_16_37","ACT","16","37","37","ויאמר פולוס אליהם הכה הכונו נגד כל העם בלא דין ומשפט ואנחנו אנשים רומיים וישליכו אתנו במשמר ועתה נסתר יגרשונו אל נא כי אם יבאו המה ויוציאונו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_38","074_16_38","ACT","16","38","38","ויגידו השטרים לשרים את הדברים האלה ויהי כשמעם כי רומיים הם וייראו׃ ");
INSERT INTO heb_vpl VALUES ("AC16_39","074_16_39","ACT","16","39","39","ויבאו ויחלו פניהם ויוציאום וישאלו מהם לצאת מן העיר׃ ");
INSERT INTO heb_vpl VALUES ("AC16_40","074_16_40","ACT","16","40","40","ויצאו מן המשמר ויבאו אל בית לודיא ויראו את האחים ויזהירום וילכו לדרכם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_1","074_17_1","ACT","17","1","1","ויהי אחרי עברם באמפפוליס ובאפלוינא ויבאו אל תסלוניקי אשר שם בית כנסת היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC17_2","074_17_2","ACT","17","2","2","ופולוס נכנס אליהם כמשפטו ושלש שבתות דבר עמהם בדברי הכתובים׃ ");
INSERT INTO heb_vpl VALUES ("AC17_3","074_17_3","ACT","17","3","3","פתוח והוכח להם כי צריך היה אשר יענה המשיח ויקום מן המתים וכי זה הוא המשיח ישוע אשר אני מגיד לכם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_4","074_17_4","ACT","17","4","4","ויאמינו מקצתם ויספחו על פולוס וסילא וגם יראי אלהים מן היונים לרב וגם נשים חשובות מספר לא מעט׃ ");
INSERT INTO heb_vpl VALUES ("AC17_5","074_17_5","ACT","17","5","5","ויקנאו הסוררים שביהודים ויקחו להם אנשי בליעל מבטלני השוק ויקבצו המון ויהמו את העיר ויסבו על בית יסון ויבקשו להביאם חוצה אל העם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_6","074_17_6","ACT","17","6","6","וכאשר לא מצאו אותם סחבו את יסון ואנשים מן האחים לפני ראשי העיר ויצעקו לאמר הנה המדיחים את כל ישבי תבל באו גם הלום׃ ");
INSERT INTO heb_vpl VALUES ("AC17_7","074_17_7","ACT","17","7","7","ויסון אסף אתם אל ביתו והם כלם עשים נגד דתי הקיסר באמרם כי יש מלך אחר והוא ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC17_8","074_17_8","ACT","17","8","8","ויחרידו את העם ואת ראשי העיר אשר שמעו את זאת׃ ");
INSERT INTO heb_vpl VALUES ("AC17_9","074_17_9","ACT","17","9","9","ויקחו ערבון מידי יסון ומידי האחרים ואחרי כן פטרום׃ ");
INSERT INTO heb_vpl VALUES ("AC17_10","074_17_10","ACT","17","10","10","והאחים מהרו לשלח את פולוס ואת סילא לילה לברואה והם בבאם שמה הלכו לבית כנסת היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC17_11","074_17_11","ACT","17","11","11","ואלה היו נדיבים מאנשי תסלוניקי ויקבלו את הדבר בכל לב וידרשו בכתובים יום יום לדעת אם כן הוא הדבר׃ ");
INSERT INTO heb_vpl VALUES ("AC17_12","074_17_12","ACT","17","12","12","ויאמינו הרבה מהם וגם מן הנשים החשובות היוניות ומן האנשים לא מעט׃ ");
INSERT INTO heb_vpl VALUES ("AC17_13","074_17_13","ACT","17","13","13","ויהי כאשר שמעו היהודים אשר מתסלוניקי כי מגיד פולוס את דבר אלהים גם בברואה ויבאו ויעררו את העם גם שמה׃ ");
INSERT INTO heb_vpl VALUES ("AC17_14","074_17_14","ACT","17","14","14","וימהרו האחים וישלחו את פולוס ללכת עד הים וסילא וטימותיוס נשארו שם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_15","074_17_15","ACT","17","15","15","והמלוים את פולוס הוליכהו עד אתינס ויקבלו מצותו אל סילא וטימותיוס כי בוא יבאו אליו במהרה וילכו׃ ");
INSERT INTO heb_vpl VALUES ("AC17_16","074_17_16","ACT","17","16","16","ויהי באתינס ופולוס מהכה להם ותתחמץ רוחו בקרבו בראתו את העיר מלאה אלילים׃ ");
INSERT INTO heb_vpl VALUES ("AC17_17","074_17_17","ACT","17","17","17","על כן בבית הכנסת דבר עם היהודים ועם יראי אלהים ובשוק יום יום עם הנקרים אליו׃ ");
INSERT INTO heb_vpl VALUES ("AC17_18","074_17_18","ACT","17","18","18","וגם מקצת הפילוסופים מתלמידי אפיקורוס ומחברת האסטוא התגרו בו ויש אשר אמרו מה יאמר המפטפט הלז ואחרים אמרים כפי הנראה הוא מגיד אלהי נכר יען כי בשר אתם את ישוע ואת התחיה׃ ");
INSERT INTO heb_vpl VALUES ("AC17_19","074_17_19","ACT","17","19","19","ויאחזוהו ויביאהו אל גבעת המשפט הנקראה בשם אריופגוס ויאמרו הנוכל לדעת מה היא זו התורה החדשה אשר אתה משמיע׃ ");
INSERT INTO heb_vpl VALUES ("AC17_20","074_17_20","ACT","17","20","20","כי דברים זרים אתה מביא באזנינו והננו חפצים לדעת מה ענינם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_21","074_17_21","ACT","17","21","21","כי האתיניים כלם וגם הנכרים הגרים שם לא חשו לדבר אחר כי אם לספר או לשמע חדשות׃ ");
INSERT INTO heb_vpl VALUES ("AC17_22","074_17_22","ACT","17","22","22","ויעמד פולוס בתוך ועד השפטים ויאמר אנשי אתינס הנני ראה בכל כי יראי אלים אתם מאד׃ ");
INSERT INTO heb_vpl VALUES ("AC17_23","074_17_23","ACT","17","23","23","כי אני עבר ומתבונן אל עבדות אלהיכם ואמצא מזבח אחד כתוב עליו לאל הנעלם ועתה את אשר עבדתם ואינכם ידעים אתו אני מגיד לכם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_24","074_17_24","ACT","17","24","24","האל אשר עשה את העולם וכל אשר בו לא ישכן בהיכלות מעשה ידים כי הוא אדון השמים והארץ׃ ");
INSERT INTO heb_vpl VALUES ("AC17_25","074_17_25","ACT","17","25","25","גם לא ישרתוהו ידי בני אדם כאלו יצטרך לדבר כי הוא הנתן לכל חיים ונשמה וכל דבר׃ ");
INSERT INTO heb_vpl VALUES ("AC17_26","074_17_26","ACT","17","26","26","ויושב כל עממי בני אדם על כל פני האדמה מדם אחד ויצב מועדים קבועים וגבולת מושבם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_27","074_17_27","ACT","17","27","27","למען יבקשו את האלהים אולי ימששהו וימצאהו אף כי איננו רחוק מכל אחד ממנו׃ ");
INSERT INTO heb_vpl VALUES ("AC17_28","074_17_28","ACT","17","28","28","כי בו אנחנו חיים ומתנועעים וקימים כאשר גם מקצת משורריכם אמרו אף ילידיו אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("AC17_29","074_17_29","ACT","17","29","29","והנה בהיותנו ילידי האלהים לא נכון לנו לחשב כי האלהות תדמה לזהב או לכסף או לאבן מעשה חרש ומחשבת בני אדם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_30","074_17_30","ACT","17","30","30","לכן עתה אחרי עבר אלהים על ימות הסכלות מצוה הוא את כל בני האדם בכל אפסי ארץ כי שוב ישובו׃ ");
INSERT INTO heb_vpl VALUES ("AC17_31","074_17_31","ACT","17","31","31","יען אשר שת יום לשפט תבל בצדק על ידי איש אשר הפקידו ויתן עדות נאמנה לכלם בהקימו אתו מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("AC17_32","074_17_32","ACT","17","32","32","וכאשר שמעו תחית מתים אלה הלעיגו לו ואלה אמרו על זאת נשמעך בעת אחרת׃ ");
INSERT INTO heb_vpl VALUES ("AC17_33","074_17_33","ACT","17","33","33","ובכן יצא פולוס מתוכם׃ ");
INSERT INTO heb_vpl VALUES ("AC17_34","074_17_34","ACT","17","34","34","ומקצתם דבקו בו ויאמינו ובהם דיונוסיוס מן השפטים של אריופגוס ואשה אחת שמה דמריס ועוד אחרים עמהם׃ ");
INSERT INTO heb_vpl VALUES ("AC18_1","074_18_1","ACT","18","1","1","אחר כן סר פולוס מאתינס ויבא אל קורנתוס׃ ");
INSERT INTO heb_vpl VALUES ("AC18_2","074_18_2","ACT","18","2","2","וימצא יהודי נולד בפונטוס ומשו עקילס אשר בא מקרוב מן איטליא הוא ואשתו פריסקלה מפני אשר צוה קלודיוס את כל היהודים לסור מעיר רומי׃ ");
INSERT INTO heb_vpl VALUES ("AC18_3","074_18_3","ACT","18","3","3","ויבא אליהם ויהי בהיתם בני אמנות אחת וישב אתם ויעש מלאכתו ואמנותם עשות יריעות אהלים׃ ");
INSERT INTO heb_vpl VALUES ("AC18_4","074_18_4","ACT","18","4","4","וידבר בבית הכנסת בכל שבת ושבת ויוכח את היהודים ואת היונים׃ ");
INSERT INTO heb_vpl VALUES ("AC18_5","074_18_5","ACT","18","5","5","וכבוא סילא וטימותיוס ממקדוניא היה פולוס נגש ברוח להעיד אל היהודים כי ישוע הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC18_6","074_18_6","ACT","18","6","6","ויהי כהמרותם וכגדפם וינער את בגדיו ויאמר אליהם דמכם בראשיכם ואנכי נקי מעתה אלכה לי אל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("AC18_7","074_18_7","ACT","18","7","7","וילך משם ויבא אל בית איש ושמו יוסטוס איש ירא אלהים וביתו סמוך לבית הכנסת׃ ");
INSERT INTO heb_vpl VALUES ("AC18_8","074_18_8","ACT","18","8","8","וקריספוס ראש הכנסת האמין באדון הוא וכל ביתו וגם קורנתים רבים בשמעם האמינו ויטבלו׃ ");
INSERT INTO heb_vpl VALUES ("AC18_9","074_18_9","ACT","18","9","9","ודבר האדון היה אל פולוס במחזה בלילה לאמר אל תירא כי אם דבר ואל תחשה׃ ");
INSERT INTO heb_vpl VALUES ("AC18_10","074_18_10","ACT","18","10","10","כי עמך אנכי ואיש אל יגע בך להרע לך כי גוי גדול לי בעיר הזאת׃ ");
INSERT INTO heb_vpl VALUES ("AC18_11","074_18_11","ACT","18","11","11","וישב שם שנה וששה חדשים וילמד בהם את דבר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC18_12","074_18_12","ACT","18","12","12","ויהי בהיות גליון שר מדינת אכיא ויקומו היהודים כלם וחדו על פולוס ויביאהו אל כסא המשפט׃ ");
INSERT INTO heb_vpl VALUES ("AC18_13","074_18_13","ACT","18","13","13","ויאמרו האיש הזה מפתה את בני האדם לעבד את אלהים בלא כתורה׃ ");
INSERT INTO heb_vpl VALUES ("AC18_14","074_18_14","ACT","18","14","14","ויהי אך בקש פולוס לפתח את פיו וגליון אמר אל היהודים לאמר אם היה דבר פשע או מעשה נבלה כי עתה נשאתי ושמעתי אתכם היהודים כמשפט׃ ");
INSERT INTO heb_vpl VALUES ("AC18_15","074_18_15","ACT","18","15","15","אבל אם היא שאלה על מלין ושמות והדת שלכם ראו אתם ואני אין רצוני להיות שפט על דברים כאלה׃ ");
INSERT INTO heb_vpl VALUES ("AC18_16","074_18_16","ACT","18","16","16","ויגרש אתם מלפני כסא המשפט׃ ");
INSERT INTO heb_vpl VALUES ("AC18_17","074_18_17","ACT","18","17","17","ויאחזו כל היונים את סוסתנים ראש הכנסת ויכוהו לפני כסא המשפט וגליון לא שת לבו גם לזאת׃ ");
INSERT INTO heb_vpl VALUES ("AC18_18","074_18_18","ACT","18","18","18","ופולוס ישב שם עוד ימים רבים ויפטר מן האחים וירד באניה ללכת אל סוריא ואתו פריסקלה ועקילס ויגלח את ראשו בקנכרי כי נדר עליו׃ ");
INSERT INTO heb_vpl VALUES ("AC18_19","074_18_19","ACT","18","19","19","ויבאו אל אפסוס ויעזב אתם שם והוא הלך לבית הכנסת וידבר עם היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC18_20","074_18_20","ACT","18","20","20","ויבקשו ממנו להאריך ימי שבתו אתם ולא אבה׃ ");
INSERT INTO heb_vpl VALUES ("AC18_21","074_18_21","ACT","18","21","21","כי אם נפטר מהם באמרו מחיב אני לחג את החג הבא בירושלים ואחרי כן אשובה אליכם אם ירצה יהוה וילך לו באניה מן אפסוס׃ ");
INSERT INTO heb_vpl VALUES ("AC18_22","074_18_22","ACT","18","22","22","ויבא אל קסרין ויעל וישאל לשלום הקהלה וירד אל אנטיוכיא׃ ");
INSERT INTO heb_vpl VALUES ("AC18_23","074_18_23","ACT","18","23","23","וישב שם ימים אחדים וילך למסעיו ויעבר בארץ גלטיא ופרוגיא ויחזק את כל התלמידים׃ ");
INSERT INTO heb_vpl VALUES ("AC18_24","074_18_24","ACT","18","24","24","ואיש יהודי בא אל אפסוס ועיר מולדתו אלכסנדריא ושמו אפולוס איש דברים ותקיף בכתובים׃ ");
INSERT INTO heb_vpl VALUES ("AC18_25","074_18_25","ACT","18","25","25","הוא היה מלמד דרך האדון והוא מדבר כחם רוחו ומלמד היטב על אדות ישוע ולא ידע כי אם טבילת יוחנן לבדה׃ ");
INSERT INTO heb_vpl VALUES ("AC18_26","074_18_26","ACT","18","26","26","והוא החל לקרא בבית הכנסת בבטחון לבב וישמעו אתו עקילס ופריסקלה ויקחהו אליהם ויוסיפו להגיד לו את דרך האלהים באר היטב׃ ");
INSERT INTO heb_vpl VALUES ("AC18_27","074_18_27","ACT","18","27","27","ויחפץ ללכת לאכיא ויכתבו האחים אל התלמידים ויעררו אתם לקבלו ויבא שמה ויעזר הרבה את המאמינים על ידי החסד׃ ");
INSERT INTO heb_vpl VALUES ("AC18_28","074_18_28","ACT","18","28","28","כי בחזקה התוכח עם היהודים לפני כל העם ויראם מן המקראות כי ישוע הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC19_1","074_19_1","ACT","19","1","1","ויהי בהיות אפולוס בקורנתוס ויעבר פולוס במדינות העליונת וירד אל אפסוס וימצא שם תלמידים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_2","074_19_2","ACT","19","2","2","ויאמר אליהם הקבלתם את רוח הקדש אחרי אשר האמנתם ויאמרו אליו אף לא שמענו כי ישנו רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC19_3","074_19_3","ACT","19","3","3","ויאמר אליהם על מה אפוא הטבלתם ויאמרו על טבילת יוחנן׃ ");
INSERT INTO heb_vpl VALUES ("AC19_4","074_19_4","ACT","19","4","4","ויאמר פולוס יוחנן הטביל בטבילת התשובה ואמר אל העם כי האמן יאמינו באשר יבוא אחריו והוא המשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC19_5","074_19_5","ACT","19","5","5","ויהי כשמעם זאת ויבאו להטבל בשם ישוע האדון׃ ");
INSERT INTO heb_vpl VALUES ("AC19_6","074_19_6","ACT","19","6","6","ויסמך פולוס את ידיו עליהם ויבא עליהם רוח הקדש וימללו בלשנות ויתנבאו׃ ");
INSERT INTO heb_vpl VALUES ("AC19_7","074_19_7","ACT","19","7","7","ויהיו כלם כשנים עשר איש׃ ");
INSERT INTO heb_vpl VALUES ("AC19_8","074_19_8","ACT","19","8","8","ויבא אל בית הכנסת ויקרא שם בבטחון לבב וידבר עמם כשלשה חדשים ויט את לבם אל דברי מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_9","074_19_9","ACT","19","9","9","אך מקצתם הקשו את לבבם ולא האמינו וידברו סרה על הדרך הזה לפני הקהל ויסר מהם ויבדל מתוכם את התלמידים וידבר אתם יום יום בבית המדרש של טורנוס׃ ");
INSERT INTO heb_vpl VALUES ("AC19_10","074_19_10","ACT","19","10","10","וכן היתה כשנתים ימים עד כי שמעו כל ישבי אסיא גם יהודים גם יונים את דבר ישוע האדון׃ ");
INSERT INTO heb_vpl VALUES ("AC19_11","074_19_11","ACT","19","11","11","וגבורות גדלות עשה האלהים על ידי פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC19_12","074_19_12","ACT","19","12","12","עד כי גם הניחו סודרים וחגרת מעל עור בשרו על החולים ויסורו מהם תחלאיהם וגם הרוחות הרעות יצאו׃ ");
INSERT INTO heb_vpl VALUES ("AC19_13","074_19_13","ACT","19","13","13","ואנשים מן היהודים הסבבים ומלחשים הואילו להזכיר את שם ישוע האדון על אחוזי הרוחות הרעות לאמר משביע אני אתכם בישוע אשר פולוס קרא אותו׃ ");
INSERT INTO heb_vpl VALUES ("AC19_14","074_19_14","ACT","19","14","14","והעשים ככה היו שבעת בני סקוה אחד מגדולי כהני היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_15","074_19_15","ACT","19","15","15","ויען הרוח ויאמר את ישוע אני מכיר ואת פולוס אני ידע ומי אתם׃ ");
INSERT INTO heb_vpl VALUES ("AC19_16","074_19_16","ACT","19","16","16","ויקפץ עליהם בעל הרוח הרעה ויגבר עליהם ויכבשם עד כי נסו מן הבית ההוא עירמים ופצועים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_17","074_19_17","ACT","19","17","17","ויודע הדבר לכל היהודים והיונים ישבי אפסוס ויפל פחד על כלם ויגדל שם האדון ישוע׃ ");
INSERT INTO heb_vpl VALUES ("AC19_18","074_19_18","ACT","19","18","18","ורבים מן המאמינים באו ויתודו ויודיעו את אשר עשו׃ ");
INSERT INTO heb_vpl VALUES ("AC19_19","074_19_19","ACT","19","19","19","ורבים אשר עשקו במעשי כשפים הביאו את ספריהם וישרפום לעיני כל ויחשבו את ערכם וימצאהו חמשת רבבות דינרים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_20","074_19_20","ACT","19","20","20","ודבר יהוה גבר מאד וילך הלך וחזק׃ ");
INSERT INTO heb_vpl VALUES ("AC19_21","074_19_21","ACT","19","21","21","ויהי ככלות הדברים האלה יעץ פולוס ברוחו לעבר בתוך מקדוניא ואכיא וללכת ירושלים ויאמר אחרי היותי שמה ראה אראה גם את רומי׃ ");
INSERT INTO heb_vpl VALUES ("AC19_22","074_19_22","ACT","19","22","22","וישלח שנים מן המשרתים אתו את טימותיוס ואת ארסטוס אל מקדוניא והוא התמהמה עוד ימים באסיא׃ ");
INSERT INTO heb_vpl VALUES ("AC19_23","074_19_23","ACT","19","23","23","ותהי בעת ההיא מהומה לא קטנה על אדות דרך יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AC19_24","074_19_24","ACT","19","24","24","כי צורף כסף אחד דמטריוס שמו עשה היכלות כסף של ארטמיס המציא לחרשים משכרת לא מעט׃ ");
INSERT INTO heb_vpl VALUES ("AC19_25","074_19_25","ACT","19","25","25","ויקהל אתם ואת שאר העסקים במלאכה ההיא ויאמר אנשים אתם ידעים כי מן המלאכה הזאת עשינו כבוד׃ ");
INSERT INTO heb_vpl VALUES ("AC19_26","074_19_26","ACT","19","26","26","ואתם ראים ושמעים אשר לא באפסוס לבדה כי גם כמעט באסיא כלה זה פולוס פתה והדיח המון עם רב לאמר לא אלהים אלה הנעשים בידים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_27","074_19_27","ACT","19","27","27","ועתה עוד מעט ולא לבד חלקנו זה יהיה לבוז כי אם גם היכל ארטמיס המלכת הגדולה יחשב לאין ותכלה תפארתה אשר כל אסיא וכל ישבי תבל מכבדים אותה׃ ");
INSERT INTO heb_vpl VALUES ("AC19_28","074_19_28","ACT","19","28","28","ויהי כשמעם את דבריו וימלאו חמה ויצעקו לאמר גדולה ארטמיס של האפסיים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_29","074_19_29","ACT","19","29","29","ותמלא כל העיר מבוכה ויסערו כלם יחדו אל התאטרון ויחטפו אתם את גיוס ואת ארסטרכוס אנשים מקדונים וחברי פולוס במסעיו׃ ");
INSERT INTO heb_vpl VALUES ("AC19_30","074_19_30","ACT","19","30","30","ויאל פולוס לבוא אל תוך העם ולא הניחו לו התלמידים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_31","074_19_31","ACT","19","31","31","וגם מקצת ראשי אסיא אשר היו אהביו שלחו אליו ויזהירו אתו אשר לא ימלאהו לבו לבוא אל התאטרון׃ ");
INSERT INTO heb_vpl VALUES ("AC19_32","074_19_32","ACT","19","32","32","ויצעקו שם אלה בכה ואלה בכה כי מבוכה גדולה היתה בקהל ורבם לא ידעו על מה זה נאספו׃ ");
INSERT INTO heb_vpl VALUES ("AC19_33","074_19_33","ACT","19","33","33","וימשכו מתוך ההמון את אלכסנדר והיהודים דחו אתו עד צאתו וינף אלכסנדר את ידו ויבקש להצטדק לפני העם׃ ");
INSERT INTO heb_vpl VALUES ("AC19_34","074_19_34","ACT","19","34","34","והמה כהכירם כי הוא יהודי נשאו כלם קול ויצעקו כשתי שעות לאמר גדולה ארטמיס של האפסיים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_35","074_19_35","ACT","19","35","35","ויהס סופר העיר את העם ויאמר אנשי אפסוס מי הוא האיש אשר לא ידע כי העיר אפסוס סכנת היא להיכל של ארטמיס המלכת הגדולה ולצלמה היורד מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("AC19_36","074_19_36","ACT","19","36","36","ויען אשר אין לכחש בדברים האלה ראוי לכם להיות שקטים ולא לעשות דבר נמהר׃ ");
INSERT INTO heb_vpl VALUES ("AC19_37","074_19_37","ACT","19","37","37","כי הבאתם את האנשים האלה אשר אינם גזלי מקדש גם אינם מגדפי מלכתכם׃ ");
INSERT INTO heb_vpl VALUES ("AC19_38","074_19_38","ACT","19","38","38","לכן אם לדמטריוס ולחרשים אשר אתו דבר ריב עם איש הנה לנו ימי בית דין ושרי המדינה ויביאו אליהם את ריבם׃ ");
INSERT INTO heb_vpl VALUES ("AC19_39","074_19_39","ACT","19","39","39","ואם תבקשו דבר אחר שפוט ישפט בקהל כפי החק׃ ");
INSERT INTO heb_vpl VALUES ("AC19_40","074_19_40","ACT","19","40","40","כי הלא בסכנה אנחנו להתחיב במרד בעבור היום הזה ודבר אין לנו לתת דין וחשבון על הרגשה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("AC19_41","074_19_41","ACT","19","41","41","ויהי כאשר כלה לדבר כדברים האלה וישלח את הקהל׃ ");
INSERT INTO heb_vpl VALUES ("AC20_1","074_20_1","ACT","20","1","1","ואחרי אשר שקטה המהומה קרא פולוס לתלמידים ויברכם ויצא ללכת אל מקדוניא׃ ");
INSERT INTO heb_vpl VALUES ("AC20_2","074_20_2","ACT","20","2","2","ויעבר במדינות ההן ויזהר אתם בדברים רבים ויבא אל ארץ יון׃ ");
INSERT INTO heb_vpl VALUES ("AC20_3","074_20_3","ACT","20","3","3","וישב שם שלשה חדשים ויהי באמרו ללכת אל סוריא ויארבו לו היהודים ויגמר בלבו לשוב דרך מקדוניא׃ ");
INSERT INTO heb_vpl VALUES ("AC20_4","074_20_4","ACT","20","4","4","וילכו אתו עד לאסיא סופטרוס הברואי ומן התסלוניקים ארסטרכוס וסקונדוס וגיוס הדרבי וטימותיוס ומן אסיא טוכיקוס וטרופימוס׃ ");
INSERT INTO heb_vpl VALUES ("AC20_5","074_20_5","ACT","20","5","5","ואלה הלכו לפנינו ויוחילו לנו בטרואס׃ ");
INSERT INTO heb_vpl VALUES ("AC20_6","074_20_6","ACT","20","6","6","ואנחנו יצאנו מן פילפי אחרי ימי חג המצות ומקץ חמשה ימים באנו באניה אליהם אל טרואס ונשב שם שבעת ימים׃ ");
INSERT INTO heb_vpl VALUES ("AC20_7","074_20_7","ACT","20","7","7","ויהי באחד בשבת כאשר נאספו התלמידים לבצע הלחם וידבר אתם פולוס כי אמר ללכת משם למחרת היום ויארך הדבר עד חצות הלילה׃ ");
INSERT INTO heb_vpl VALUES ("AC20_8","074_20_8","ACT","20","8","8","ונרות רבים היו בעליה אשר נאספנו שם׃ ");
INSERT INTO heb_vpl VALUES ("AC20_9","074_20_9","ACT","20","9","9","ובחור אחד שמו אבטוכוס ישב בחלון וירדם בהאריך פולוס את אמרתו ותגבר עליו שנתו ויפל מהמדור השלישי למטה וישאהו מת׃ ");
INSERT INTO heb_vpl VALUES ("AC20_10","074_20_10","ACT","20","10","10","וירד פולוס ויגהר עליו ויחבקהו ויאמר אל תבהלו כי נשמתו בו׃ ");
INSERT INTO heb_vpl VALUES ("AC20_11","074_20_11","ACT","20","11","11","ואחר עלה ויבצע הלחם ויטעם וירב לשיח אתם עד אור הבקר ויצא ללכת לדרכו׃ ");
INSERT INTO heb_vpl VALUES ("AC20_12","074_20_12","ACT","20","12","12","והם הביאו את הנער חי וינחמו עד מאד׃ ");
INSERT INTO heb_vpl VALUES ("AC20_13","074_20_13","ACT","20","13","13","ואנחנו קדמנו לרדת באניה ונעבר אסוסה למען נקח שם אתנו את פולוס כי כן צוה והוא חשב בלבו ללכת שמה ברגליו׃ ");
INSERT INTO heb_vpl VALUES ("AC20_14","074_20_14","ACT","20","14","14","ויפגש אתנו באסוס ונקח אתו ונבא אל מיטוליני׃ ");
INSERT INTO heb_vpl VALUES ("AC20_15","074_20_15","ACT","20","15","15","ומשם יצאנו באניה ונפגע ממחרת אל מול כיוס וביום השלישי עברנו אל סמוס ונלן בטרוגוליון ולמחרתו באנו אל מיליטוס׃ ");
INSERT INTO heb_vpl VALUES ("AC20_16","074_20_16","ACT","20","16","16","כי פולוס אמר לעבר מעל פני אפסוס פן יצטרך להתמהמה באסיא כי אץ לבוא אם יוכל עד חג השבועות ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC20_17","074_20_17","ACT","20","17","17","וממיליטוס שלח אל אפסוס ויקרא את זקני הקהלה׃ ");
INSERT INTO heb_vpl VALUES ("AC20_18","074_20_18","ACT","20","18","18","ויבאו אליו ויאמר להם אתם ידעתם איך הייתי עמכם בכל עת מן היום הראשון אשר דרכה רגלי באסיא׃ ");
INSERT INTO heb_vpl VALUES ("AC20_19","074_20_19","ACT","20","19","19","אשר עבדתי את האדון בכל ענוה ובדמעות הרבה ובמסות המצאות אתי בנכלי היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC20_20","074_20_20","ACT","20","20","20","איך לא כחדתי מכם כל דבר תועלת והגדתיו לכם ולמדתי אתכם ברבים ובכל בית ובית׃ ");
INSERT INTO heb_vpl VALUES ("AC20_21","074_20_21","ACT","20","21","21","ואעיד ליהודים וליונים את התשובה לאלהים ואת האמונה באדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC20_22","074_20_22","ACT","20","22","22","ועתה הנני אסיר הרוח ללכת ירושלים ואינני יודע מה יקרני שם׃ ");
INSERT INTO heb_vpl VALUES ("AC20_23","074_20_23","ACT","20","23","23","אפס כי רוח הקדש מעיד בכל עיר ועיר לאמר כי מוסרות וצרות נכונו לי׃ ");
INSERT INTO heb_vpl VALUES ("AC20_24","074_20_24","ACT","20","24","24","אבל לא אחוש לאחת מהנה וגם נפשי לא יקרה בעיני למען אשלים בשמחה את מרוצתי ואת השרות אשר קבלתי מאת האדון ישוע להעיד על בשורת חסד אליהם׃ ");
INSERT INTO heb_vpl VALUES ("AC20_25","074_20_25","ACT","20","25","25","ועתה הנה ידע אנכי כי אתם כלכם אשר התהלכתי בקרבכם הלוך והשמע את מלכות יהוה כי לא תוסיפו עוד ראות פני׃ ");
INSERT INTO heb_vpl VALUES ("AC20_26","074_20_26","ACT","20","26","26","על כן מעיד אני בכם היום הזה כי נקי אנכי מדמי כלכם׃ ");
INSERT INTO heb_vpl VALUES ("AC20_27","074_20_27","ACT","20","27","27","כי לא כחדתי מהגיד לכם את עצת האלהים כלה׃ ");
INSERT INTO heb_vpl VALUES ("AC20_28","074_20_28","ACT","20","28","28","לכן שמרו את נפשותיכם ואת כל העדר אשר הקים אתכם רוח הקדש לפקידים בו לרעות את עדת האלהים אשר קנה לו בדם נפשו׃ ");
INSERT INTO heb_vpl VALUES ("AC20_29","074_20_29","ACT","20","29","29","כי ידע אני אשר אחרי צאתי יבואו בתוככם זאבים עזים אשר לא יחוסו על העדר׃ ");
INSERT INTO heb_vpl VALUES ("AC20_30","074_20_30","ACT","20","30","30","וגם מקרבכם יקומו אנשים דברי תהפכות להטות אחריהם את התלמידים׃ ");
INSERT INTO heb_vpl VALUES ("AC20_31","074_20_31","ACT","20","31","31","על כן שקדו וזכרו כי שלש שנים יומם ולילה לא חדלתי לדבר על לב כל אחד מכם בדמעות׃ ");
INSERT INTO heb_vpl VALUES ("AC20_32","074_20_32","ACT","20","32","32","ועתה אחי אני מסר אתכם לאלהים ולדבר חסדו אשר לו היכלת לבנות אתכם ולתת לכם נחלה בקרב כל המקדשים׃ ");
INSERT INTO heb_vpl VALUES ("AC20_33","074_20_33","ACT","20","33","33","לא חמדתי כסף איש או זהבו או לבושו׃ ");
INSERT INTO heb_vpl VALUES ("AC20_34","074_20_34","ACT","20","34","34","ואתם ידעתם כי ידי אלה עבדו בעד צרכי ובעד צרכי ההלכים אתי׃ ");
INSERT INTO heb_vpl VALUES ("AC20_35","074_20_35","ACT","20","35","35","ובכל הראיתי אתכם כי כן עלינו לעמל ולתמך את החלשים ולזכר את דברי האדון ישוע כי הוא אמר טוב אשר תתן משתקח׃ ");
INSERT INTO heb_vpl VALUES ("AC20_36","074_20_36","ACT","20","36","36","ואחרי דברו את הדברים האלה כרע על ברכיו ויתפלל עם כלם׃ ");
INSERT INTO heb_vpl VALUES ("AC20_37","074_20_37","ACT","20","37","37","ויבכו כלם בכי גדול ויפלו על צוארי פולוס וינשקו לו׃ ");
INSERT INTO heb_vpl VALUES ("AC20_38","074_20_38","ACT","20","38","38","וביותר התעצבו על הדבר אשר דבר כי לא יוסיפו עוד לראות פניו וילוהו אל האניה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_1","074_21_1","ACT","21","1","1","ויהי כאשר נפרדנו מהם ונרד באניה ונבוא דרך ישרה אל קוס וממחרת אל רודוס ומשם אל פטרה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_2","074_21_2","ACT","21","2","2","שם מצאנו אניה עברת אל פינוקיא ונרד בה ונעבר׃ ");
INSERT INTO heb_vpl VALUES ("AC21_3","074_21_3","ACT","21","3","3","ונרא את פני קפרוס ונעזבנה לשמאל ונעבר אל סוריא ונגיע אל צור כי שמה יוציאו את מעמסת האניה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_4","074_21_4","ACT","21","4","4","ונמצא את התלמידים ונשב שם שבעת ימים והם אמרו אל פולוס על פי הרוח לבלתי עלות ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC21_5","074_21_5","ACT","21","5","5","ויהי אחרי מלאת לנו הימים האלה ונצא ללכת לדרכנו וילוו אתנו כלם עם נשיהם ועם טפם עד מחוץ לעיר ונכרע על ברכינו על חוף הים ונתפלל׃ ");
INSERT INTO heb_vpl VALUES ("AC21_6","074_21_6","ACT","21","6","6","ונברך איש את רעהו ונעל אל האניה והמה שבו איש לביתו׃ ");
INSERT INTO heb_vpl VALUES ("AC21_7","074_21_7","ACT","21","7","7","ואנחנו כלינו את דרך הים ונרד מצור אל עכו ונשאל לשלום האחים ונשב אתם יום אחד׃ ");
INSERT INTO heb_vpl VALUES ("AC21_8","074_21_8","ACT","21","8","8","וממחרת נסענו פולוס ואשר אתו ונבא אל קסרין ונלך אל בית פילפוס המבשר אשר הוא אחד מן השבעה ונשב עמו׃ ");
INSERT INTO heb_vpl VALUES ("AC21_9","074_21_9","ACT","21","9","9","ולו היו ארבע בנות בתולות מתנבאות׃ ");
INSERT INTO heb_vpl VALUES ("AC21_10","074_21_10","ACT","21","10","10","ויהי בהיותנו שם ימים רבים וירד נביא אחד מיהודה ושמו אגבוס׃ ");
INSERT INTO heb_vpl VALUES ("AC21_11","074_21_11","ACT","21","11","11","ויבא אצלנו ויקח את אזור פולוס ויאסר בו את ידיו ואת רגליו ויאמר כה אמר רוח הקדש ככה יאסרו היהודים בירושלים את האיש אשר לו האזור הזה ויסגירהו בידי הגוים׃ ");
INSERT INTO heb_vpl VALUES ("AC21_12","074_21_12","ACT","21","12","12","ויהי כאשר שמענו את זאת ונבקש ממנו אנחנו ואנשי המקום אשר לא יעלה ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC21_13","074_21_13","ACT","21","13","13","ויען פולוס ויאמר מה לכם אשר תבכו ותשברו לבבי כי נכון אנכי לא לבד להאסר כי גם למות בירושלים על שם ישוע האדון׃ ");
INSERT INTO heb_vpl VALUES ("AC21_14","074_21_14","ACT","21","14","14","ולא אבה שמע ונרף ממנו לאמר רצון יהוה יעשה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_15","074_21_15","ACT","21","15","15","ואחרי הימים האלה נשאנו את כלינו ונעל ירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC21_16","074_21_16","ACT","21","16","16","וילכו אתנו גם תלמידים מקסרין ויביאו אתנו ללון בבית איש כתי ושמו מנסון והוא תלמיד ישן׃ ");
INSERT INTO heb_vpl VALUES ("AC21_17","074_21_17","ACT","21","17","17","ויהי כבאנו ירושלים ויקבלו אתנו האחים בשמחה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_18","074_21_18","ACT","21","18","18","וממחרת היום נכנס פולוס עמנו אל יעקב ויבאו שמה כל הזקנים׃ ");
INSERT INTO heb_vpl VALUES ("AC21_19","074_21_19","ACT","21","19","19","וישאלם לשלום ויספר אחת לאחת את אשר עשה האלהים לגוים בשרותו׃ ");
INSERT INTO heb_vpl VALUES ("AC21_20","074_21_20","ACT","21","20","20","וישמעו ויהללו את האלהים ויאמרו אליו הנך ראה אחינו כמה רבבות יהודים באו להאמין וכלם מקנאים לתורה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_21","074_21_21","ACT","21","21","21","והם שמעו עליך שמועה כי תלמד את כל היהודים אשר בקרב הגוים לסור ממשה באמרך כי אין עליהם למול את בניהם וללכת בחקות התורה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_22","074_21_22","ACT","21","22","22","ועתה מה לעשות הנה האסף יאסף המון העם כי ישמעו כי באת׃ ");
INSERT INTO heb_vpl VALUES ("AC21_23","074_21_23","ACT","21","23","23","לכן עשה זאת אפוא אשר נאמר אליך׃ ");
INSERT INTO heb_vpl VALUES ("AC21_24","074_21_24","ACT","21","24","24","הנה יש אתנו ארבעה אנשים אשר נדר עליהם אתם קח לך והטהר אתם ושלם ההוצאות בעדם למען אשר יגלחו את ראשם וידעו כלם כי שמועת שוא שמעו עליך וכי אתה בעצמך מתהלך בחקות התורה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_25","074_21_25","ACT","21","25","25","ועל דבר המאמינים בגוים כתבנו וגזרנו אשר לא ישמרו דבר מאלה רק להשמר מזבחי אלילים ומן הדם ומבשר הנחנק ומן הזנות׃ ");
INSERT INTO heb_vpl VALUES ("AC21_26","074_21_26","ACT","21","26","26","ויקח פולוס את האנשים ויטהר אתם וממחרת בא אל המקדש ויגד כי מלאו ימי טהרתם עד כי הקרב קרבן כל אחד מהם׃ ");
INSERT INTO heb_vpl VALUES ("AC21_27","074_21_27","ACT","21","27","27","ויהי כאשר קרבו שבעת הימים לכלות והיהודים אשר מאסיא ראו אתו במקדש ויעוררו את כל ההמון וישלחו בו את ידיהם׃ ");
INSERT INTO heb_vpl VALUES ("AC21_28","074_21_28","ACT","21","28","28","ויצעקו לאמר אנשי ישראל עזרו זה הוא האיש המלמד את כל אדם אשר בכל הארץ סרה על העם הזה ועל התורה ועל המקום הזה וגם הביא אל המקדש אנשים יונים ויחלל את המקום הקדוש הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_29","074_21_29","ACT","21","29","29","כי היו ראים את טרופימוס האפסי בעיר אתו ויחשבו כי פולוס הביא אתו אל המקדש׃ ");
INSERT INTO heb_vpl VALUES ("AC21_30","074_21_30","ACT","21","30","30","ותהם כל העיר וירץ העם ויקבץ ויאחזו את פולוס וימשכהו אל מחוץ למקדש ופתאם סגרו הדלתות׃ ");
INSERT INTO heb_vpl VALUES ("AC21_31","074_21_31","ACT","21","31","31","והמה מבקשים להמיתו והשמועה באה אל שר האלף של הגדוד כי כל ירושלים נבוכה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_32","074_21_32","ACT","21","32","32","וימהר ויקח אתו אנשי צבא ושרי מאות וירץ אליהם ויהי כראותם את שר האלף ואת אנשי הצבא ויחדלו מהכות את פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC21_33","074_21_33","ACT","21","33","33","ויגש שר האלף ויחזק בו ויצו לאסרו בנחשתים וישאל מי הוא זה ומה עשה׃ ");
INSERT INTO heb_vpl VALUES ("AC21_34","074_21_34","ACT","21","34","34","ויענו מן העם אלה בכה ואלה בכה ולא יכל לדעת מאומה אל נכון מרב השאון ויצו להוליכו אל המצד׃ ");
INSERT INTO heb_vpl VALUES ("AC21_35","074_21_35","ACT","21","35","35","ויהי כבואו עד המעלות וישאהו אנשי הצבא מפני חמת העם׃ ");
INSERT INTO heb_vpl VALUES ("AC21_36","074_21_36","ACT","21","36","36","כי עם רב הלך אחריו והם צעקים ואמרים הסר אתו׃ ");
INSERT INTO heb_vpl VALUES ("AC21_37","074_21_37","ACT","21","37","37","וכאשר הקריב פולוס להאסף אל המצד אמר אל שר האלף התניח לי לדבר אליך דבר ויאמר הידעת יונית׃ ");
INSERT INTO heb_vpl VALUES ("AC21_38","074_21_38","ACT","21","38","38","האם אינך המצרי אשר לפני הימים האלה העיר מרד והוציא המדברה ארבעת אלפים אנשי דמים׃ ");
INSERT INTO heb_vpl VALUES ("AC21_39","074_21_39","ACT","21","39","39","ויאמר פולוס איש יהודי אנכי מטרסוס בן עיר קיליקיא אשר איננה בלי שם ועתה אשאלה מאתך הניחה לי לדבר אל העם׃ ");
INSERT INTO heb_vpl VALUES ("AC21_40","074_21_40","ACT","21","40","40","וינח לו ויעמד פולוס על המעלות הניף ידו אל העם ותהי דממה רבה וידבר בלשון עברית ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC22_1","074_22_1","ACT","22","1","1","אנשים אחים ואבות שמעו נא את דברי התנצלותי אליכם׃ ");
INSERT INTO heb_vpl VALUES ("AC22_2","074_22_2","ACT","22","2","2","ויהי כשמעם כי הוא מדבר אליהם בלשון עברית ויחשו עוד יותר׃ ");
INSERT INTO heb_vpl VALUES ("AC22_3","074_22_3","ACT","22","3","3","ויאמר איש יהודי אנכי נולד בטרסוס אשר בקיליקיא ומגדל בעיר הזאת לרגלי גמליאל ומלמד לפי דקדוקי תורת אבותינו ואהי מקנא לאלהים כמוכם כלכם היום׃ ");
INSERT INTO heb_vpl VALUES ("AC22_4","074_22_4","ACT","22","4","4","וארדף את הדרך הזאת עד מות ואהי אסר ומסגיר לכלא אנשים ונשים׃ ");
INSERT INTO heb_vpl VALUES ("AC22_5","074_22_5","ACT","22","5","5","כאשר גם יעיד עלי הכהן הגדול וכל בית הזקנים אשר מהם לקחתי מכתבים ואלך אל האחים לדמשק לאסר אף את הנמצאים שמה להביאם ירושלים למען יוסרו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_6","074_22_6","ACT","22","6","6","ויהי אנכי הלך וקרב לדמשק כעת צהרים ופתאם נגה עלי מסביב אור גדול מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("AC22_7","074_22_7","ACT","22","7","7","ואפל ארצה ואשמע קול מדבר אלי שאול שאול למה תרדפני׃ ");
INSERT INTO heb_vpl VALUES ("AC22_8","074_22_8","ACT","22","8","8","ואען ואמר מי אתה אדני ויאמר אלי אני ישוע הנצרי אשר אתה רדפו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_9","074_22_9","ACT","22","9","9","והאנשים אשר אתי ראו את האור וייראו ואת קול המדבר אלי לא שמעו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_10","074_22_10","ACT","22","10","10","ואמר מה אעשה אדני ויאמר אלי האדון קום לך אל דמשק ושם יאמר לך את כל אשר צוית לעשות׃ ");
INSERT INTO heb_vpl VALUES ("AC22_11","074_22_11","ACT","22","11","11","ואני לא יכלתי לראות מפני זהר האור ההוא והאנשים אשר אתי הוליכוני ביד ואבא לדמשק׃ ");
INSERT INTO heb_vpl VALUES ("AC22_12","074_22_12","ACT","22","12","12","ואיש חסיד כפי התורה ושמו חנניה אשר קנה לו שם טוב בקרב כל היהודים הישבים שם׃ ");
INSERT INTO heb_vpl VALUES ("AC22_13","074_22_13","ACT","22","13","13","ויבא אלי ויעמד ויאמר אלי שאול אחי שוב ראה ובשעה ההיא נפקחו עיני וראיתיהו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_14","074_22_14","ACT","22","14","14","ויאמר אלהי אבותינו בחר בך לדעת את רצונו ולראות את הצדיק ולשמע קול מפיהו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_15","074_22_15","ACT","22","15","15","כי היו תהיה לו לעד אל כל בני האדם על כל אשר ראית ושמעת׃ ");
INSERT INTO heb_vpl VALUES ("AC22_16","074_22_16","ACT","22","16","16","ועתה למה תתמהמה קום והטבל והתרחץ מחטאתיך בקראך בשמו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_17","074_22_17","ACT","22","17","17","ויהי בשובי אל ירושלים ואתפלל במקדש ותהי עלי יד יהוה׃ ");
INSERT INTO heb_vpl VALUES ("AC22_18","074_22_18","ACT","22","18","18","וארא אותו מדבר אלי חושה צא במהרה מירושלים כי לא יקבלו את עדותך עלי׃ ");
INSERT INTO heb_vpl VALUES ("AC22_19","074_22_19","ACT","22","19","19","ואמר הלא הם יודעים את אשר השלכתי אל הכלא והלקיתי בבתי הכנסיות את המאמינים בך׃ ");
INSERT INTO heb_vpl VALUES ("AC22_20","074_22_20","ACT","22","20","20","ובהשפך דם אסטפנוס עדך אף אני עמדתי שם חפץ בהרגתו ושומר את בגדי הרגיו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_21","074_22_21","ACT","22","21","21","ויאמר אלי לך כי אני אל הגיום עד למרחוק אשלחך׃ ");
INSERT INTO heb_vpl VALUES ("AC22_22","074_22_22","ACT","22","22","22","וישמעו אליו עד הדבר הזה וישאו את קולם ויאמרו הסירו איש כזה מעל האדמה כי איננו ראוי כי יחיה׃ ");
INSERT INTO heb_vpl VALUES ("AC22_23","074_22_23","ACT","22","23","23","ויהי בהיותם צעקים ומשליכים את בגדיהם מעליהם וזרקים עפר השמימה׃ ");
INSERT INTO heb_vpl VALUES ("AC22_24","074_22_24","ACT","22","24","24","ויצו שר האלף להוליכו אל המצד ויאמר לבדקו במלקות למען ידע מדוע המה ככה צעקים עליו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_25","074_22_25","ACT","22","25","25","ויהי כאשר אסר להכותו ברצועות ויאמר אל שר המאה העמד עליו האף רשיון לכם להכות איש רומי בלא דין ומשפט׃ ");
INSERT INTO heb_vpl VALUES ("AC22_26","074_22_26","ACT","22","26","26","וילך שר המאה כשמעו את הדבר הזה ויגד לשר האלף לאמר ראה מה תעשה כי האיש הזה רומי הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC22_27","074_22_27","ACT","22","27","27","ויבא שר האלף ויאמר אמר לי הרומי אתה ויאמר הן׃ ");
INSERT INTO heb_vpl VALUES ("AC22_28","074_22_28","ACT","22","28","28","ויען שר האלף אני בכסף רב קניתי לי משפט האזרחות הזאת ויאמר פולוס ואני אף נולדתי בה׃ ");
INSERT INTO heb_vpl VALUES ("AC22_29","074_22_29","ACT","22","29","29","אז הרפו ממנו האנשים אשר באו לבדקו וגם שר האלף ירא בדעתו כי רומי הוא והוא אסר אותו׃ ");
INSERT INTO heb_vpl VALUES ("AC22_30","074_22_30","ACT","22","30","30","וממחרת בקש לדעת אל נכון על מה שטנים אותו היהודים ויתר מוסרותיו ויצו להביא את ראשי הכהנים ואת כל הסנהדרין ויורד את פולוס ויעמידהו בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("AC23_1","074_23_1","ACT","23","1","1","ויבט פולוס אל הסנהדרין ויאמר אנשים אחים בכל תמת לבבי התהלכתי לפני אלהים עד היום הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC23_2","074_23_2","ACT","23","2","2","ויצו חנניה הכהן הגדול את העמדים עליו להכותו על פיו׃ ");
INSERT INTO heb_vpl VALUES ("AC23_3","074_23_3","ACT","23","3","3","ויאמר אליו פולוס יככה אלהים הקיר המסיד האמנם ישב אתה לדין אתי כתורה ואתה מצוה להכותי שלא כתורה׃ ");
INSERT INTO heb_vpl VALUES ("AC23_4","074_23_4","ACT","23","4","4","ויאמרו העמדים שם את הכהן הגדול לאלהים תחרף׃ ");
INSERT INTO heb_vpl VALUES ("AC23_5","074_23_5","ACT","23","5","5","ויאמר פולוס אחי לא ידעתי אשר הוא הכהן הגדול כי כתוב נשיא בעמך לא תאר׃ ");
INSERT INTO heb_vpl VALUES ("AC23_6","074_23_6","ACT","23","6","6","ופולוס ידע כי מקצתם צדוקים ומקצתם פרושים ויצעק בתוך הסנהדרין אנשים אחים פרוש בן פרוש אנכי ועל תקות המתים ותחיתם אני נדין׃ ");
INSERT INTO heb_vpl VALUES ("AC23_7","074_23_7","ACT","23","7","7","ובדברו הדבר הזה היה ריב בין הצדוקים ובין הפרושים ויחלק ההמון׃ ");
INSERT INTO heb_vpl VALUES ("AC23_8","074_23_8","ACT","23","8","8","כי הצדוקים אמרים אין תחיה ואין מלאך ורוח והפרושים מודים בשניהם׃ ");
INSERT INTO heb_vpl VALUES ("AC23_9","074_23_9","ACT","23","9","9","ותהי המלה גדולה ויקומו הסופרים אשר מכת הפרושים ויתוכחו לאמר לא מצאנו דבר רע באיש הזה ואם רוח דבר אליו או מלאך אל נלחמה באלהים׃ ");
INSERT INTO heb_vpl VALUES ("AC23_10","074_23_10","ACT","23","10","10","והריב הולך וחזק ושר האלף דאג פן ישסעו את פולוס ויצו את אנשי הצבא לרדת ולחטף אתו מתוכם ולהכיאו אל המצד׃ ");
INSERT INTO heb_vpl VALUES ("AC23_11","074_23_11","ACT","23","11","11","ובלילה ההוא נצב עליו האדון ויאמר חזק פולוס כי כאשר העידות לי בירושלים כן העד תעיד ברומי׃ ");
INSERT INTO heb_vpl VALUES ("AC23_12","074_23_12","ACT","23","12","12","ויהי לפנות הבקר ויתחברו היהודים ויאסרו אסר על נפשם לאמר כי לא יאכלו ולא ישתו עד אם יהרגו את פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC23_13","074_23_13","ACT","23","13","13","ומספר הבאים באלה הזאת היה יותר מארבעים׃ ");
INSERT INTO heb_vpl VALUES ("AC23_14","074_23_14","ACT","23","14","14","ויגשו לא ראשי הכהנים ואל הזקנים לאמר אסר אסרנו על נפשנו לבלתי טעם מאומה עד אם הרגנו את פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC23_15","074_23_15","ACT","23","15","15","ועתה הודיעו אתם והסנהדרין את שר האלף ויורידהו מחר אליכם כאלו תחפצו לדרש היטב את ענינו ואנחנו נכונים להמיתו בטרם יקרב אליכם׃ ");
INSERT INTO heb_vpl VALUES ("AC23_16","074_23_16","ACT","23","16","16","וישמע בן אחות פולוס את ארבם וילך ויבא אל המצד ויגד לפולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC23_17","074_23_17","ACT","23","17","17","ויקרא פולוס לאחד משרי המאות ויאמר אליו הולך את הבחור הזה אל שר האלף כי דבר לו להודיעו׃ ");
INSERT INTO heb_vpl VALUES ("AC23_18","074_23_18","ACT","23","18","18","ויקחהו ויוליכהו אל שר האלף ויאמר פולוס האסיר קראני אליו ויבקש ממני להוליך אליך את הבחור הזה כי דבר לו להגיד לך׃ ");
INSERT INTO heb_vpl VALUES ("AC23_19","074_23_19","ACT","23","19","19","ויאחז שר האלף בידו ויסר עמו לבדו וישאלהו מה הוא זה אשר לך להודיעני׃ ");
INSERT INTO heb_vpl VALUES ("AC23_20","074_23_20","ACT","23","20","20","ויאמר כי נועצו היהודים יחדו לבקש ממך כי מחר תוריד את פולוס לפני הסנהדרין והמה כאלו חפצים לדעת היטב את ענינו׃ ");
INSERT INTO heb_vpl VALUES ("AC23_21","074_23_21","ACT","23","21","21","ואתה אל תשמע להם כי ארבים לו מהם יותר מארבעים איש אשר אסרו אסר על נפשם לבלתי אכל ושתות בטרם יהרגוהו והמה עתה עמדים ומחכים להבטחתך׃ ");
INSERT INTO heb_vpl VALUES ("AC23_22","074_23_22","ACT","23","22","22","וישלח שר האלף את הבחור ויצוהו לבלתי אמר לאיש כי גלה לו את הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("AC23_23","074_23_23","ACT","23","23","23","ויקרא לשני שרי מאות ויאמר החלצו מאתכם אנשי צבא מאתים ללכת לקסרין ופרשים שבעים ומשכי קשת מאתים מן השעה השלישית בלילה׃ ");
INSERT INTO heb_vpl VALUES ("AC23_24","074_23_24","ACT","23","24","24","ובהמות יכינו להרכיב את פולוס למען הביאו שלם אל פיליכס ההגמון׃ ");
INSERT INTO heb_vpl VALUES ("AC23_25","074_23_25","ACT","23","25","25","ויכתב אגרת וזה תכן דבריה׃ ");
INSERT INTO heb_vpl VALUES ("AC23_26","074_23_26","ACT","23","26","26","קלודיוס לוסיאס אל פיליכס ההגמון האדיר שלום׃ ");
INSERT INTO heb_vpl VALUES ("AC23_27","074_23_27","ACT","23","27","27","את האיש הזה תפשו היהודים ויבקשו המיתו ואבא עם אנשי הצבא ואפלטהו מתוכם בשמעי כי רומי הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC23_28","074_23_28","ACT","23","28","28","ובאשר חפצתי לדעת על מה שמנו אתו הורדתיו אל הסנהדרין שלהם׃ ");
INSERT INTO heb_vpl VALUES ("AC23_29","074_23_29","ACT","23","29","29","ואמצא כי שטנו אתו על דברי שאלות דתם ולא על דבר אשר יהיה עליו חיב מיתה או מוסרות׃ ");
INSERT INTO heb_vpl VALUES ("AC23_30","074_23_30","ACT","23","30","30","ועתה הנה הגד לי שהיהודים מתנכלים באיש הזה ואשלחהו אליך מיד וגם את שטניו צויתי לבוא ולהגיש שטנתם לפניך ואתה שלום׃ ");
INSERT INTO heb_vpl VALUES ("AC23_31","074_23_31","ACT","23","31","31","ויקחו אנשי הצבא את פולוס כאשר צוו ויביאהו לילה אל אנטפטריס׃ ");
INSERT INTO heb_vpl VALUES ("AC23_32","074_23_32","ACT","23","32","32","וממחרת הניחו את הפרשים ללכת אתו וישובו למצד׃ ");
INSERT INTO heb_vpl VALUES ("AC23_33","074_23_33","ACT","23","33","33","והמה באו אל קסרין ויתנו את האגרת בידי ההגמון ויעמידו לפניו גם את פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC23_34","074_23_34","ACT","23","34","34","ויהי כקרא ההגמון את האגרת וישאל מאי זה מדינה הוא ויהי כשמעו כי הוא מקיליקיא ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC23_35","074_23_35","ACT","23","35","35","אשמע את דבריך בבוא גם שטניך הנה ויצו לשמרו בבית המשפט אשר להורדוס׃ ");
INSERT INTO heb_vpl VALUES ("AC24_1","074_24_1","ACT","24","1","1","וירד חנניה הכהן הגדול אחרי חמשת ימים ואתו הזקנים וטרטלוס איש דברים ויודיעו את ההגמון את דבר ריבם עם פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC24_2","074_24_2","ACT","24","2","2","ויהי כאשר קראו לו ויחל טרטלוס לשטנו ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC24_3","074_24_3","ACT","24","3","3","את אשר ישבנו על ידך בשלום רב ואשר נעשו תקנות רבות לעם הזה בהשגחתך נקבל על כל פנים ובכל מקום בכל תודה פיליכס האדיר׃ ");
INSERT INTO heb_vpl VALUES ("AC24_4","074_24_4","ACT","24","4","4","אך לבלתי הלאותך הרבה אתחנן אליך אשר תשמענו בקצר דברינו כחמלתך׃ ");
INSERT INTO heb_vpl VALUES ("AC24_5","074_24_5","ACT","24","5","5","כי מצאנו את האיש הזה כקטב ומגרה מדינים בין כל היהודים על פני תבל והוא ראש כת הנצרים׃ ");
INSERT INTO heb_vpl VALUES ("AC24_6","074_24_6","ACT","24","6","6","והוא גם נסה לחלל את המקדש ונתפש אותו ונחפץ לשפטו על פי תורתנו׃ ");
INSERT INTO heb_vpl VALUES ("AC24_7","074_24_7","ACT","24","7","7","ויבא עלינו לוסיאס שר האלף ברב כח ויחטפהו מידינו׃ ");
INSERT INTO heb_vpl VALUES ("AC24_8","074_24_8","ACT","24","8","8","ויצו את שטניו כי בוא יבאו לפניך ואתה כי תחקר אתו תוכל לדעת מפיהו את כל הדברים האלה אשר אנחנו טענים עליו׃ ");
INSERT INTO heb_vpl VALUES ("AC24_9","074_24_9","ACT","24","9","9","וימלאו היהודים את דבריו לאמר כי כן הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC24_10","074_24_10","ACT","24","10","10","וירמז ההגמון אל פולוס לדבר ויען ויאמר יען אשר ידעתי כי זה כמה שנים שופט אתה לעם הזה הנני מצטדק בלב בטוח על עניני׃ ");
INSERT INTO heb_vpl VALUES ("AC24_11","074_24_11","ACT","24","11","11","אתה תוכל לדעת אשר לא עברו יותר משנים עשר יום מעת עלותי ירושלים להשתחות׃ ");
INSERT INTO heb_vpl VALUES ("AC24_12","074_24_12","ACT","24","12","12","ולא במקדש מצאוני מתוכח עם איש או מעורר מהומה בעם ולא בבתי הכנסיות ולא בעיר׃ ");
INSERT INTO heb_vpl VALUES ("AC24_13","074_24_13","ACT","24","13","13","גם אין ביכלתם להוכיח עלי את אשר עתה הם שטנים אותי׃ ");
INSERT INTO heb_vpl VALUES ("AC24_14","074_24_14","ACT","24","14","14","אבל את זאת מודה אני לפניך כי בדרך ההיא אשר יקראוה בשם כת בה אני עבד את אלהי אבותינו בהאמיני בכל הכתוב בתורה ובנביאים׃ ");
INSERT INTO heb_vpl VALUES ("AC24_15","074_24_15","ACT","24","15","15","ותקותי לאלהים אשר גם הם יחכו לה זאת היא כי עתידה להיות תחית המתים לצדיקים ולרשעים׃ ");
INSERT INTO heb_vpl VALUES ("AC24_16","074_24_16","ACT","24","16","16","ובזאת גם עמלתי להיות תמים לב לאלהים ולאדם תמיד׃ ");
INSERT INTO heb_vpl VALUES ("AC24_17","074_24_17","ACT","24","17","17","ומקץ שנים רבות באתי להביא נדבות לעמי ולהקריב קרבן׃ ");
INSERT INTO heb_vpl VALUES ("AC24_18","074_24_18","ACT","24","18","18","ואהי מטהר במקדש לא בהמון עם ולא במהומה וכן מצאוני אנשים יהודים מאסיא׃ ");
INSERT INTO heb_vpl VALUES ("AC24_19","074_24_19","ACT","24","19","19","אשר עליהם היה לעמד הנה לפניך ולענות בי אם היה להם דבר נגדי׃ ");
INSERT INTO heb_vpl VALUES ("AC24_20","074_24_20","ACT","24","20","20","או אלה ידברו נא המה מה מצאו בי עול בעמדי לפני הסנהדרין׃ ");
INSERT INTO heb_vpl VALUES ("AC24_21","074_24_21","ACT","24","21","21","בלתי אם הדבר האחד ההוא אשר קראתי בעמדי בתוכם כי על תחית המתים אני נדון היום לפניכם׃ ");
INSERT INTO heb_vpl VALUES ("AC24_22","074_24_22","ACT","24","22","22","ויהי כשמע פיליכס את הדרים האלה ויאחר את דינם לעת אחרת כי עניני הדרך הזאת נודעו לו היטב ויאמר ברדת אלי לוסיאס שר האלף אשפט על דברכם׃ ");
INSERT INTO heb_vpl VALUES ("AC24_23","074_24_23","ACT","24","23","23","ויצו את שר המאה לשום אתו במשמר ולתת לו רוחה ולבלתי מנע איש ממידעיו משרת אתו ומבוא אליו׃ ");
INSERT INTO heb_vpl VALUES ("AC24_24","074_24_24","ACT","24","24","24","ואחרי ימים אחדים בא פיליכס עם אשתו דרוסלה והיא יהודית וישלח לקרא לפולוס וישמע אתו על דבר האמונה במשיח׃ ");
INSERT INTO heb_vpl VALUES ("AC24_25","074_24_25","ACT","24","25","25","ויהי כדברו על הצדק והפרישות ועל הדין העתיד לבוא ויחרד פיליכס ויען עתה זה לך ולכשאפנה אשוב לקרא לך׃ ");
INSERT INTO heb_vpl VALUES ("AC24_26","074_24_26","ACT","24","26","26","והוא מקוה כי פולוס יתן לו שחד למען יתירהו ובעבור זה קרא לו פעמים הרבה וידבר עמו׃ ");
INSERT INTO heb_vpl VALUES ("AC24_27","074_24_27","ACT","24","27","27","ויהי מקץ שנתים ימים ויקם פרקיוס פסטוס תחת פיליכס ופיליכס חפץ להתרצות אל היהודים ויעזב את פולוס חבוש בבית האסורים׃ ");
INSERT INTO heb_vpl VALUES ("AC25_1","074_25_1","ACT","25","1","1","ויבא פסטוס אל המדינה ויעל אחרי שלשת ימים מקסרין לירושלים׃ ");
INSERT INTO heb_vpl VALUES ("AC25_2","074_25_2","ACT","25","2","2","והכהן הגדול וראשי היהודים הודיעהו את ריבם עם פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC25_3","074_25_3","ACT","25","3","3","ויפצרו בו וישאלו ממנו לעשות חסד עמהם להביאו ירושלים והמה מתנכלים אתו להמיתו בדרך׃ ");
INSERT INTO heb_vpl VALUES ("AC25_4","074_25_4","ACT","25","4","4","ויען אותם פסטוס כי עצור פולוס בקסרין וכי גם הוא ישוב שמה בקרוב׃ ");
INSERT INTO heb_vpl VALUES ("AC25_5","074_25_5","ACT","25","5","5","ויאמר לכן ירדו אתי העצומים שבכם ואם יש מאום באיש הזה יענו בו׃ ");
INSERT INTO heb_vpl VALUES ("AC25_6","074_25_6","ACT","25","6","6","וישב בתוכם יותר מימים עשרה וירד אל קסרין וממחרת ישב על כסא המשפט ויצו להביא את פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC25_7","074_25_7","ACT","25","7","7","הוא בא והיהודים אשר ירדו מירושלים סבבהו ויאשימו את פולוס באשמות רבות וקשות אשר לא יכלו להוכיח׃ ");
INSERT INTO heb_vpl VALUES ("AC25_8","074_25_8","ACT","25","8","8","והוא הצטדק לאמר לא חטאתי במאומה לא לדת היהודים ולא למקדש ולא לקיסר׃ ");
INSERT INTO heb_vpl VALUES ("AC25_9","074_25_9","ACT","25","9","9","ופסטוס חפץ להתרצות אל היהודים ויען את פולוס ויאמר התחפץ לעלות ירושלים להשפט על אלה לפני שמה׃ ");
INSERT INTO heb_vpl VALUES ("AC25_10","074_25_10","ACT","25","10","10","ויאמר פולוס לפני כסא משפט הקיסר אני עמד ושם נכון לי להשפט לא הרעתי ליהודים כאשר ידעת היטב גם אתה׃ ");
INSERT INTO heb_vpl VALUES ("AC25_11","074_25_11","ACT","25","11","11","אם הרעתי ויש בי דבר משפט מות בל אחשך נפשי ממות ואם אין בי מאומה מכל אשר הם ענים בי איש לא יוכל להסגירני אל ידם את הקיסר אני קורא לדיני׃ ");
INSERT INTO heb_vpl VALUES ("AC25_12","074_25_12","ACT","25","12","12","ויועץ פסטוס עם יועציו ויען אתו לאמר את הקיסר קראת אל הקיסר תלך׃ ");
INSERT INTO heb_vpl VALUES ("AC25_13","074_25_13","ACT","25","13","13","ויהי אחרי ימים וירדו המלך אגרפס וברניקה אל קסרין לשאל לשלום פסטוס׃ ");
INSERT INTO heb_vpl VALUES ("AC25_14","074_25_14","ACT","25","14","14","ויהי כי ארכו להם הימים שם ויספר פסטוס למלך את ריב פולוס לאמר יש פה איש אשר פיליכס הניחו אסור׃ ");
INSERT INTO heb_vpl VALUES ("AC25_15","074_25_15","ACT","25","15","15","ובהיותי בירושלים דברו אלי ראשי הכהנים וזקני היהודים על אדותיו ויבקשו ממני לחרץ משפטו׃ ");
INSERT INTO heb_vpl VALUES ("AC25_16","074_25_16","ACT","25","16","16","ואען אותם כי אין מנהג הרומיים למגן איש לאבד בטרם יעמד הנשטן לנכח שטניו ונתן לו מקום להצטדק מן השטנה׃ ");
INSERT INTO heb_vpl VALUES ("AC25_17","074_25_17","ACT","25","17","17","ולכן כאשר באו הנה יחד חשתי ולא התמהמהתי כי ממחרת היום ישבתי על כסא המשפט ואצוה להביא את האיש׃ ");
INSERT INTO heb_vpl VALUES ("AC25_18","074_25_18","ACT","25","18","18","ויעמדו עליו שטניו ולא הביאו עליו דבר רע מאשר הייתי חשד אתו׃ ");
INSERT INTO heb_vpl VALUES ("AC25_19","074_25_19","ACT","25","19","19","רק היו להם דברי ריבת לנגדו על עבודת אלהיהם ועל מת אחד ישוע שמו אשר אמר עליו פולוס כי הוא חי׃ ");
INSERT INTO heb_vpl VALUES ("AC25_20","074_25_20","ACT","25","20","20","ותכבד בעיני השאלה הזאת ואמר החפץ אתה ללכת ירושלים ולהשפט שם על אלה׃ ");
INSERT INTO heb_vpl VALUES ("AC25_21","074_25_21","ACT","25","21","21","אבל פולוס שאל להניחו במשמר עד צאת משפטו מלפני אגוסטוס ואצוה לשמרו עד אשר אשלח אתו אל הקיסר׃ ");
INSERT INTO heb_vpl VALUES ("AC25_22","074_25_22","ACT","25","22","22","ויאמר אגרפס אל פסטוס גם אני חפץ לשמע את האיש ויאמר מחר תשמענו׃ ");
INSERT INTO heb_vpl VALUES ("AC25_23","074_25_23","ACT","25","23","23","ויהי ממחרת כבוא אגרפס וברניקה בהוד גדול ויבאו אל אלם המשמעת המה ושרי האלף ונגידי העיר ויצו פסטוס ויביאו את פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC25_24","074_25_24","ACT","25","24","24","ויאמר פסטוס אגרפס המלך וכל האישים אשר אתם פה אתנו הנכם ראים את האיש אשר בעבורו פגעו בי כל המון היהודים גם בירושלים וגם פה ויצעקו כי אינו בדין שיחיה עוד׃ ");
INSERT INTO heb_vpl VALUES ("AC25_25","074_25_25","ACT","25","25","25","ואני כאשר הכרתי כי לא עשה דבר לחיבו מיתה והוא גם הוא קרא את אגוסטוס לדינו יעצתי לשלח אתו שמה׃ ");
INSERT INTO heb_vpl VALUES ("AC25_26","074_25_26","ACT","25","26","26","אך אין לי לכתב עליו דבר נכון לאדנינו ובעבור זאת הביאתיו לפניכם וביותר לפניך המלך אגרפס למען יחקר וידעתי מה אכתב׃ ");
INSERT INTO heb_vpl VALUES ("AC25_27","074_25_27","ACT","25","27","27","כי לא יתכן בעיני לשלוח אסיר מבלי הודיע גם את עלילת הדברים אשר שמו לו׃ ");
INSERT INTO heb_vpl VALUES ("AC26_1","074_26_1","ACT","26","1","1","ויאמר אגרפס אל פולוס נתן לך לדבר בעד נפשך אז יצטדק פולוס ויושט את ידו ויאמר׃ ");
INSERT INTO heb_vpl VALUES ("AC26_2","074_26_2","ACT","26","2","2","מאשר אני את נפשי המלך אגרפס כי לפניך אצטדק היום על כל אשר שטנים אתי היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC26_3","074_26_3","ACT","26","3","3","כי אתה ידע היטב כל המנהגים והשאלות אשר בין היהודים ועל כן אשאלה מאתך לשמע אתי כארך רוחך׃ ");
INSERT INTO heb_vpl VALUES ("AC26_4","074_26_4","ACT","26","4","4","הנה את דרכי מנעורי אשר התהלכתי בה מאז בתוך עמי ובירושלים ידעים אותה כל היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC26_5","074_26_5","ACT","26","5","5","כי מימים ראשונים ידעוני אם ירצו להעיד כי כפרוש התנהגתי על פי הכת המקפדת ביותר בעבודתנו׃ ");
INSERT INTO heb_vpl VALUES ("AC26_6","074_26_6","ACT","26","6","6","ועתה אני עמד להשפט על תקות ההבטחה אשר הבטיחה האלהים את אבותינו׃ ");
INSERT INTO heb_vpl VALUES ("AC26_7","074_26_7","ACT","26","7","7","ואשר שנים עשר שבטינו מיחלים להגיע לה בעבדם את יהוה תמיד יומם ולילה על דבר התקוה הזאת אגרפס המלך שטנים אותי היהודים׃ ");
INSERT INTO heb_vpl VALUES ("AC26_8","074_26_8","ACT","26","8","8","מדוע יפלא בעיניכם כי האלהים יחיה מתים׃ ");
INSERT INTO heb_vpl VALUES ("AC26_9","074_26_9","ACT","26","9","9","הן לפנים אני חשבתי צדקה לצרר את שם ישוע הנצרי עד מאד׃ ");
INSERT INTO heb_vpl VALUES ("AC26_10","074_26_10","ACT","26","10","10","כאשר עשיתי בירושלים וגם קדושים רבים אני הסגרתי לבתי כלאים ברשיון אשר קבלתי מאת הכהנים הגדולים וכשנהרגו הסכמתי׃ ");
INSERT INTO heb_vpl VALUES ("AC26_11","074_26_11","ACT","26","11","11","ובכל בתי הכנסיות יסרתי אתם פעמים רבות ואנסתים לגדף ואתהוללה בם עד מאד וארדפם עד לערים אשר חוצה לארץ׃ ");
INSERT INTO heb_vpl VALUES ("AC26_12","074_26_12","ACT","26","12","12","ויהי בלכתי על זאת לדמשק ברשיון הכהנים הגדולים ובמצותם׃ ");
INSERT INTO heb_vpl VALUES ("AC26_13","074_26_13","ACT","26","13","13","והנה אדני המלך בצהרים בדרך ראיתי אור צח מזהר השמש אשר משמים נגה עלי מסביב ועל ההלכים אתי׃ ");
INSERT INTO heb_vpl VALUES ("AC26_14","074_26_14","ACT","26","14","14","ונפל כלנו ארצה ואשמע קול מדבר אלי בלשון עברית לאמר שאול שאול למה תרדפני קשה לך לבעט בדרבנות׃ ");
INSERT INTO heb_vpl VALUES ("AC26_15","074_26_15","ACT","26","15","15","ואמר מי אתה אדני ויאמר אנכי ישוע אשר אתה רדף׃ ");
INSERT INTO heb_vpl VALUES ("AC26_16","074_26_16","ACT","26","16","16","אבל קום ועמד על רגליך כי לבעבור זאת נראיתי אליך לבחר בך למשרת ולעד על אשר ראית ועל אשר אראך׃ ");
INSERT INTO heb_vpl VALUES ("AC26_17","074_26_17","ACT","26","17","17","בהצילי אותך מן העם ומן הגוים אשר אשלחך עתה אליהם׃ ");
INSERT INTO heb_vpl VALUES ("AC26_18","074_26_18","ACT","26","18","18","לפקח את עיניהם למען ישובו מחשך לאור ומיד השטן אל האלהים וימצאו באמונתם בי את סליחת החטאים ואת הנחלה בתוך המקדשים׃ ");
INSERT INTO heb_vpl VALUES ("AC26_19","074_26_19","ACT","26","19","19","על כן המלך אגרפס לא המריתי את המראה אשר ראיתי מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("AC26_20","074_26_20","ACT","26","20","20","כי אם קראתי ראשונה לישבי דמשק וירושלים ובכל ארץ יהודה וגם לגוים כי ינחמו וישובו אל האלהים ויעשו מעשים ראוים לתשובה׃ ");
INSERT INTO heb_vpl VALUES ("AC26_21","074_26_21","ACT","26","21","21","ובגלל הדבר הזה תפשו אתי היהודים במקדש ויבקשו להמיתני׃ ");
INSERT INTO heb_vpl VALUES ("AC26_22","074_26_22","ACT","26","22","22","והאלהים היה בעזרי ועד היום הזה עמד אני ומעיד לפני קטן וגדול ואינני מדבר דבר זולתי אשר דברו הנביאים ומשה כי עתידות הנה להיות׃ ");
INSERT INTO heb_vpl VALUES ("AC26_23","074_26_23","ACT","26","23","23","כי המשיח מענה הוא וכי ראשון הוא לקמים מן המתים להפיץ אור בעם ובגוים׃ ");
INSERT INTO heb_vpl VALUES ("AC26_24","074_26_24","ACT","26","24","24","ויהי הוא מצטדק כזאת ויען פסטוס בקול גדול לאמר הנך משתגע פולוס רב הלמוד הביאך לידי שגעון׃ ");
INSERT INTO heb_vpl VALUES ("AC26_25","074_26_25","ACT","26","25","25","ויאמר פולוס אינני משגע פסטוס האדיר כי אם דברי אמת וטעם אביע׃ ");
INSERT INTO heb_vpl VALUES ("AC26_26","074_26_26","ACT","26","26","26","כי המלך יודע את אלה ועל זאת גם בבטחון אני מדבר אליו יען אשר לא אאמין כי נעלם ממנו דבר מן הדברים האלה כי לא בקרן זוית נעשתה זאת׃ ");
INSERT INTO heb_vpl VALUES ("AC26_27","074_26_27","ACT","26","27","27","המלך אגרפס המאמין אתה בנביאים ידעתי כי מאמין אתה׃ ");
INSERT INTO heb_vpl VALUES ("AC26_28","074_26_28","ACT","26","28","28","ויאמר אגרפס אל פולוס עוד מעט ופתיתני להיות נצרי׃ ");
INSERT INTO heb_vpl VALUES ("AC26_29","074_26_29","ACT","26","29","29","ויאמר פולוס אבקשה מאלהים אשר אם במעט ואם בהרבה לא אתה לבדך כי גם כל השמעים אותי יהיו כמוני זולתי המוסרות האלה׃ ");
INSERT INTO heb_vpl VALUES ("AC26_30","074_26_30","ACT","26","30","30","ויהי בדברו הדבר הזה ויקם המלך וההגמון וברניקה והישבים אתם׃ ");
INSERT INTO heb_vpl VALUES ("AC26_31","074_26_31","ACT","26","31","31","ויסורו החדרה וידברו איש אל רעהו לאמר האיש הזה לא עשה דבר אשר יהיה עליו חיב מיתה או מוסרות׃ ");
INSERT INTO heb_vpl VALUES ("AC26_32","074_26_32","ACT","26","32","32","ויאמר אגרפס אל פסטוס האיש הזה יוכל להפטר לולא קרא את הקיסר לדינו׃ ");
INSERT INTO heb_vpl VALUES ("AC27_1","074_27_1","ACT","27","1","1","וכאשר נגמר הדין כי נעבר באניה אל איטליא מסרו את פולוס ומקצת אסירים אחרים אל שר המאה לגדוד אגוסטוס ושמו יוליוס׃ ");
INSERT INTO heb_vpl VALUES ("AC27_2","074_27_2","ACT","27","2","2","ונרד אל אניה אדרמטית נכנים לבוא על פני חוף אסיא ונעבר הימה ויהי אתנו ארסטרכוס מוקדון מן תסלוניקי׃ ");
INSERT INTO heb_vpl VALUES ("AC27_3","074_27_3","ACT","27","3","3","וממחרת הגענו אל צידון ויוליוס עשה עם פולוס חסד וינח לו ללכת אל מידעיו להעזר בידם׃ ");
INSERT INTO heb_vpl VALUES ("AC27_4","074_27_4","ACT","27","4","4","ונלך משם ונעבר בסביבות קפרוס כי הרוחות היו לנגדנו׃ ");
INSERT INTO heb_vpl VALUES ("AC27_5","074_27_5","ACT","27","5","5","ונעבר את הים אשר לפני קיליקיא ופמפוליא ונבא אל מורא אשר בלוקיא׃ ");
INSERT INTO heb_vpl VALUES ("AC27_6","074_27_6","ACT","27","6","6","וימצא שם שר המאה אניה אלכסנדרית באה לאיטליא ויעבירנו לתוכה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_7","074_27_7","ACT","27","7","7","והאניה הלכה בכבדות ימים רבים ואחרי אשר יגענו ובאנו אל מול קנידוס לא הניחנו הרוח לחתר אל היבשה ונעבר מצד לקריטי על פני הר סלמוני׃ ");
INSERT INTO heb_vpl VALUES ("AC27_8","074_27_8","ACT","27","8","8","ואחרי אשר עברנו בתלאות באנו למקום אחד נקרא קלילמני אשר קרובה לו עיר ושמה לסיא׃ ");
INSERT INTO heb_vpl VALUES ("AC27_9","074_27_9","ACT","27","9","9","ויהי מקץ ימים רבים כאשר באה עת הסכנה לירדי הים כי גם הצום כבר עבר ויזהר אתם פולוס׃ ");
INSERT INTO heb_vpl VALUES ("AC27_10","074_27_10","ACT","27","10","10","ויאמר אליהם אנשים ראה אני כי הליכתנו תהיה אך מרי ונזק גדול לא לבד למעמסה ולאניה כי אם גם לנפשותינו׃ ");
INSERT INTO heb_vpl VALUES ("AC27_11","074_27_11","ACT","27","11","11","ושר המאה לא שמע אל דברי פולוס כי אם אל רב החבל ואל בעל האניה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_12","074_27_12","ACT","27","12","12","ובאשר החוף איננו טוב לעמד בו בימי הסתיו יעצו הרבים לעבר משם לאמר אולי נוכל הגיע לפיניכס וישבנו שם בימי הסתו והוא חוף בקריטי פונה דרך הדרום מערבה ודרך הצפון מערבה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_13","074_27_13","ACT","27","13","13","ורוח נשבת לאט מדרום ויחשבו כי תצלח עצתם בידם ויעלו העוגין ויעברו לעמת שפת קריטי׃ ");
INSERT INTO heb_vpl VALUES ("AC27_14","074_27_14","ACT","27","14","14","ויהי כמעט אחרי כן ותפגע בה רוח נחשל הנקראה אוריקלידון׃ ");
INSERT INTO heb_vpl VALUES ("AC27_15","074_27_15","ACT","27","15","15","ותטרף האניה ולא יכלה לעמד נגד הרוח ונרף ידינו ממנה וננדף׃ ");
INSERT INTO heb_vpl VALUES ("AC27_16","074_27_16","ACT","27","16","16","ותרץ האניה אל עבר אי קטן הנקרא קלודה וכמעט לא יכלנו לאחז העברה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_17","074_27_17","ACT","27","17","17","ואחרי משכם אותה אליהם ויקחו לעזר את כל אשר השיגה ידם ויחשבו את דפני האניה ומיראתם פן יפלו אל בין רכסי החול הורידו את כלי המפרש וכה נדפו׃ ");
INSERT INTO heb_vpl VALUES ("AC27_18","074_27_18","ACT","27","18","18","ויהי הסער הולך וסער עלינו וממחרת הטילו את המעמסה אל הים׃ ");
INSERT INTO heb_vpl VALUES ("AC27_19","074_27_19","ACT","27","19","19","וביום השלישי הטלנו בידינו את כלי האניה אל הים׃ ");
INSERT INTO heb_vpl VALUES ("AC27_20","074_27_20","ACT","27","20","20","ויהי ימים רבים גם השמש גם הכוכבים לא נראו והסערה חזקה עלינו עד מאד ותכרת ממנו כל תקות ישועה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_21","074_27_21","ACT","27","21","21","ופולוס עמד בתוכם אחרי האריכם בצום ויאמר אנשים לו שמעתם אלי ולא יצאתם מקריטי כי אז לא קרנו הנזק הזה במריכם׃ ");
INSERT INTO heb_vpl VALUES ("AC27_22","074_27_22","ACT","27","22","22","ועתה אני אמר אליכם חזקו ואמצו כי לא תאבד נפש מכם בלתי הספינה לבדה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_23","074_27_23","ACT","27","23","23","כי בלילה הזה נצב עלי מלאך האלהים אשר לו אנכי ואשר אני עבד אתו׃ ");
INSERT INTO heb_vpl VALUES ("AC27_24","074_27_24","ACT","27","24","24","ויאמר אל תירא פולוס עליך עוד לעמד לפני הקיסר ועתה הנה נתן לך האלהים את כל ההלכים אתך באניה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_25","074_27_25","ACT","27","25","25","על כן אנשים חזקו ואמצו כי מאמין אני לאלהים כי כן יהיה כאשר נאמר אלי׃ ");
INSERT INTO heb_vpl VALUES ("AC27_26","074_27_26","ACT","27","26","26","אך השלך נשלך אל אחד האיים׃ ");
INSERT INTO heb_vpl VALUES ("AC27_27","074_27_27","ACT","27","27","27","ויהי כבוא ליל ארבעה עשר לטלטולנו בים אדריה כחצות הלילה ויחשבו המלחים כי קרבה להם יבשת׃ ");
INSERT INTO heb_vpl VALUES ("AC27_28","074_27_28","ACT","27","28","28","ויורידו את האנך וימצאו עמק הים עשרים קומה ויעברו מעט ויוסיפו להוריד את האנך וימצאו קומות חמש עשרה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_29","074_27_29","ACT","27","29","29","וייראו פן יפגעו בשני הסלעים וישליכו מעל אחורי האניה ארבעה עוגינים אל הים ויכספו לאור היום׃ ");
INSERT INTO heb_vpl VALUES ("AC27_30","074_27_30","ACT","27","30","30","והמלחים בקשו לברח מן האניה ויורידו את העברה אל הים באמרם כי יש את נפשם לשלח עוגינים גם מראש האניה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_31","074_27_31","ACT","27","31","31","ויאמר פולוס אל שר המאה ואל אנשי הצבא לאמר אם אלה לא ישבו אתנו באניה לא תוכלו אתם להושע׃ ");
INSERT INTO heb_vpl VALUES ("AC27_32","074_27_32","ACT","27","32","32","ויקצצו אנשי הצבא את חבלי העברה ויתנוה לנפול׃ ");
INSERT INTO heb_vpl VALUES ("AC27_33","074_27_33","ACT","27","33","33","והבקר טרם יאור ופולוס מבקש מכלם לטעם לחם לאמר היום יום ארבעה עשר אשר חכיתם צמים ולא טעמתם מאומה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_34","074_27_34","ACT","27","34","34","על כן קרא אני אתכם לטעם לחם כי הוא למחיתכם כי איש איש מכם לא יפל משערת ראשו ארצה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_35","074_27_35","ACT","27","35","35","הוא דבר את הדברים האלה והוא לקח את הלחס ויודה לאלהים לפני כלם ויבצע ויחל לאכל׃ ");
INSERT INTO heb_vpl VALUES ("AC27_36","074_27_36","ACT","27","36","36","ויאמץ לב כלם ויטעמו אכל גם המה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_37","074_27_37","ACT","27","37","37","ואנחנו כל נפש אשר באניה מאתים ושבעים ושש׃ ");
INSERT INTO heb_vpl VALUES ("AC27_38","074_27_38","ACT","27","38","38","ויאכלו לשבעה ויקלו מעל האניה ויטילו את הצדה אל הים׃ ");
INSERT INTO heb_vpl VALUES ("AC27_39","074_27_39","ACT","27","39","39","הבקר אור ולא הכירו את הארץ אבל ראו כמפרץ וחוף לו ויועצו לנהג אליו את האניה אם יוכלו׃ ");
INSERT INTO heb_vpl VALUES ("AC27_40","074_27_40","ACT","27","40","40","ויגדעו את העוגינים ויעזבום לים ויתירו גם את מיתרי המנהיג ויפרשו מפרש התרן אל פני הרוח ויבקשו לבא אל החוף׃ ");
INSERT INTO heb_vpl VALUES ("AC27_41","074_27_41","ACT","27","41","41","ויפגעו במקום אשר הים משני עבריו ותדבק בו האניה ותעמד ראשה לא ינוע ואחוריה נשברו משאון הגלים׃ ");
INSERT INTO heb_vpl VALUES ("AC27_42","074_27_42","ACT","27","42","42","ותהי עצת אנשי הצבא להמית את האסירים פן ישחה איש מהם וימלט׃ ");
INSERT INTO heb_vpl VALUES ("AC27_43","074_27_43","ACT","27","43","43","ושר המאה חפץ להציל את פולוס וינא את עצתם ויאמר מי ידע לשחות ירד ויעבר ליבשה בראשנה והנשארים אלה על קרשים ואלה על שברי האניה׃ ");
INSERT INTO heb_vpl VALUES ("AC27_44","074_27_44","ACT","27","44","44","ויהי כן וימלטו כלם אל היבשה׃ ");
INSERT INTO heb_vpl VALUES ("AC28_1","074_28_1","ACT","28","1","1","וכאשר נמלטנו נודע לנו כי שם האי מליטי׃ ");
INSERT INTO heb_vpl VALUES ("AC28_2","074_28_2","ACT","28","2","2","והנכרים לא המעיטו חסדם עמנו כי בערו אש ויאספו את כלנו אליהם מפני הגשם היורד ומפני הקר׃ ");
INSERT INTO heb_vpl VALUES ("AC28_3","074_28_3","ACT","28","3","3","ופולוס אסף לו ערמת קצים וישם על המוקד ומן החם יצא אפעה ויאחז בידו׃ ");
INSERT INTO heb_vpl VALUES ("AC28_4","074_28_4","ACT","28","4","4","ויראו הנכרים את החיה תלויה על ידו ויאמרו איש אל רעהו אכן רצח האיש הזה אשר הנקמה לא הניחה לו לחיות אף כי נמלט מן הים׃ ");
INSERT INTO heb_vpl VALUES ("AC28_5","074_28_5","ACT","28","5","5","והוא נער את החיה מעל ידו אל תוך האש ולא הרעה לו מאומה׃ ");
INSERT INTO heb_vpl VALUES ("AC28_6","074_28_6","ACT","28","6","6","והם הוחילו אשר יצבה גופו או אשר יפל מת פתאם ויחילו עד בוש והנה לא קרהו כל אסון ויהפך לבם ויאמרו כי אלהים הוא׃ ");
INSERT INTO heb_vpl VALUES ("AC28_7","074_28_7","ACT","28","7","7","ובסביבו המקום ההוא היו שדות אשר לראש אנשי האי ושמו פובליוס הוא הביא אתנו לביתו ויכלכל אתנו בטובו שלשת ימים׃ ");
INSERT INTO heb_vpl VALUES ("AC28_8","074_28_8","ACT","28","8","8","ואבי פובליוס מוטל למשכב בקדחת ובמחלה המעים ויבא אליו פולוס ויתפלל וישם עליו את ידיו וירפאהו׃ ");
INSERT INTO heb_vpl VALUES ("AC28_9","074_28_9","ACT","28","9","9","ואחרי המעשה הזה באו גם החלים האחרים אשר באי וירפאו׃ ");
INSERT INTO heb_vpl VALUES ("AC28_10","074_28_10","ACT","28","10","10","ויכבדנו כבוד גדול ובלכתנו משם ספקו לנו די צרכנו׃ ");
INSERT INTO heb_vpl VALUES ("AC28_11","074_28_11","ACT","28","11","11","ואחרי שלשת חדשים עברנו משם באניה אלכסנדרית אשר ישבה באי בימי הסתו ואות דגלה התאומים׃ ");
INSERT INTO heb_vpl VALUES ("AC28_12","074_28_12","ACT","28","12","12","ונבא אל סרקוסא ונשב שם שלשת ימים׃ ");
INSERT INTO heb_vpl VALUES ("AC28_13","074_28_13","ACT","28","13","13","משם סבנו ונבא אל רגיון ובנשב רוח דרומית ביום המחרת באנו ביום השני אל פוטיולי׃ ");
INSERT INTO heb_vpl VALUES ("AC28_14","074_28_14","ACT","28","14","14","ושם מצאנו אחים ויבקשו ממנו לשבת אתם שבעת ימים ובכן הלכנו אל רומי׃ ");
INSERT INTO heb_vpl VALUES ("AC28_15","074_28_15","ACT","28","15","15","וישמעו האחים את בואנו ויצאו משם לקראתנו עד לשוק אפיוס ועד לשלשת החניות וירא אתם פולוס ויודה לאלהים ויתחזק׃ ");
INSERT INTO heb_vpl VALUES ("AC28_16","074_28_16","ACT","28","16","16","ואחר באנו אל רומי העביר שר המאה את האסירים אל שר הצבא ולפולוס הניחו לשבת לבדו עם איש הצבא השמר אותו׃ ");
INSERT INTO heb_vpl VALUES ("AC28_17","074_28_17","ACT","28","17","17","ויהי אחרי שלשת ימים ויקרא פולוס אליו את ראשי היהודים ויקהלו אליו ויאמר אליהם אנשים אחים אף כי לא מעלתי מעל בעמנו ובחקות אבותינו אסרוני בירושלים וימסרוני לידי הרומיים׃ ");
INSERT INTO heb_vpl VALUES ("AC28_18","074_28_18","ACT","28","18","18","והם אחרי חקרם אתי אמרו לפטרני כי לא נמצא בי משפט מות׃ ");
INSERT INTO heb_vpl VALUES ("AC28_19","074_28_19","ACT","28","19","19","והיהודים קמו בי ואאנס לקרא את הקיסר לדיני אך אין נפשי לשטון את עמי בדבר׃ ");
