INSERT INTO heb_vpl VALUES ("AC28_21","074_28_21","ACT","28","21","21","ויאמרו אליו לא קבלנו על אדותיך אגרות מארץ יהודה ולא בא הנה אחד מן האחים אשר הגיד או דבר עליך דבר רע׃ ");
