INSERT INTO heb_vpl VALUES ("AC28_23","074_28_23","ACT","28","23","23","וישימו לו יום מועד ויבאו אליו רבים אל מלונו ויעד בהם ויבאר את מלכות אלהים ויוכח להם עניני ישוע מתורת משה ומן הנביאים מבקר עד ערב׃ ");
