INSERT INTO heb_vpl VALUES ("RM7_1","075_7_1","ROM","7","1","1","או הלא ידעתם אחי ולידעי התורה אנכי מדבר כי התורה תשלט על האדם כל ימי חייו׃ ");
INSERT INTO heb_vpl VALUES ("RM7_2","075_7_2","ROM","7","2","2","כי אשה בעלת בעל קשורה היא באישה כפי התורה בחייו ובמות הבעל פטורה היא מתורת בעלה׃ ");
