INSERT INTO heb_vpl VALUES ("RM7_5","075_7_5","ROM","7","5","5","כי בעת היותנו בבשר תשוקות החטא אשר התעוררו על ידי התורה היו פעלות באברינו לעשות פרי למות׃ ");
INSERT INTO heb_vpl VALUES ("RM7_6","075_7_6","ROM","7","6","6","אבל עתה נפטרנו מן התורה כי מתנו לאשר היינו אסורים בו למען נעבד מעתה לפי התחדשות הרוח ולא לפי ישן הכתב׃ ");
