INSERT INTO heb_vpl VALUES ("RM13_3","075_13_3","ROM","13","3","3","כי השליטים אינם לפחד למעשים הטובים כי אם להרעים ועל כן אם רצונך שלא תירא מן הרשות עשה הטוב והיה לך שבח ממנה׃ ");
INSERT INTO heb_vpl VALUES ("RM13_4","075_13_4","ROM","13","4","4","כי משמשת אלהים היא לטוב לך אך אם הרע תעשה ירא כי לא לחנם חגרת חרב היא כי משמשת אלהים היא נקמת בקצף מכל עשה הרע׃ ");
INSERT INTO heb_vpl VALUES ("RM13_5","075_13_5","ROM","13","5","5","על כן עלינו להכנע לא לבד בעבור הקצף כי גם בעבור דעת חובתנו׃ ");
INSERT INTO heb_vpl VALUES ("RM13_6","075_13_6","ROM","13","6","6","כי לזאת אף משלמים אתם את המס כי משרתי אלהים המה השקדים על זאת׃ ");
INSERT INTO heb_vpl VALUES ("RM13_7","075_13_7","ROM","13","7","7","לכן תנו לכל איש כחובתכם המס לאשר לו המס המכס לאשר לו המכס והמורא לאשר לו המורא והכבוד לאשר לו הכבוד׃ ");
INSERT INTO heb_vpl VALUES ("RM13_8","075_13_8","ROM","13","8","8","ואל תהיו חיבים לאיש דבר זולתי אהבת איש את רעהו כי האהב את חברו קים את התורה׃ ");
INSERT INTO heb_vpl VALUES ("RM13_9","075_13_9","ROM","13","9","9","כי מצות לא תנאף לא תרצח לא תגנב לא תענה עד שקר לא תחמד ועוד כאלה כלולות הנה במאמר הזה ואהבת לרעך כמוך׃ ");
INSERT INTO heb_vpl VALUES ("RM13_10","075_13_10","ROM","13","10","10","האהבה לא תרע לרע על כן האהבה קיום התורה כלה׃ ");
INSERT INTO heb_vpl VALUES ("RM13_11","075_13_11","ROM","13","11","11","וכזאת עשו מדעתכם את הזמן כי כבר הגיעה השעה להקיץ מן השנה כי ישועתנו קרובה עתה מהיום אשר באנו להאמין׃ ");
INSERT INTO heb_vpl VALUES ("RM13_12","075_13_12","ROM","13","12","12","הלילה חלף והיום קרב לכן נסירה נא את מעשי החשך ונלבשה את כלי נשק האור׃ ");
INSERT INTO heb_vpl VALUES ("RM13_13","075_13_13","ROM","13","13","13","וכמו ביום נתהלכה בצניעות לא בזוללות ובשכרון ולא בבעילות ועשות זמה ולא במריבה וקנאה׃ ");
INSERT INTO heb_vpl VALUES ("RM13_14","075_13_14","ROM","13","14","14","כי אם לבשו את האדון ישוע המשיח ודאגו לבשרכם אך לא להגביר התאות׃ ");
INSERT INTO heb_vpl VALUES ("RM14_1","075_14_1","ROM","14","1","1","ואת החלוש באמונה אותו קבלו ולא לדין את המחשבות׃ ");
INSERT INTO heb_vpl VALUES ("RM14_2","075_14_2","ROM","14","2","2","יש מאמין כי נכון לאכל כל דבר והחלוש יאכל רק את הירק׃ ");
INSERT INTO heb_vpl VALUES ("RM14_3","075_14_3","ROM","14","3","3","האכל אל יבז את אשר לא יאכל ואשר לא יאכל אל ידין את האכל כי קבל אתו האלהים׃ ");
INSERT INTO heb_vpl VALUES ("RM14_4","075_14_4","ROM","14","4","4","מי אתה כי תדין את עבד האחר הן לאדניו הוא יקום או יפל אבל יוקם כי יכל האלהים להקימו׃ ");
INSERT INTO heb_vpl VALUES ("RM14_5","075_14_5","ROM","14","5","5","יש מבדיל בין יום ליום ויש אשר כל הימים שוים בעיניו ויהי כל איש נכון בדעתו׃ ");
INSERT INTO heb_vpl VALUES ("RM14_6","075_14_6","ROM","14","6","6","השמר את היום לאדון שמר אתו ואשר איננו שמר את היום לאדון איננו שמר האכל לאדון הוא אכל כי מודה הוא לאלהים ואשר איננו אכל לאדון איננו אכל ומודה הוא לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("RM14_7","075_14_7","ROM","14","7","7","כי אין איש מאתנו אשר יחיה לנפשו ואין איש אשר ימות לנפשו׃ ");
INSERT INTO heb_vpl VALUES ("RM14_8","075_14_8","ROM","14","8","8","כי כאשר נחיה נחיה לאדון וכאשר נמות נמות לאדון לכן אם נחיה ואם נמות לאדון הננו׃ ");
INSERT INTO heb_vpl VALUES ("RM14_9","075_14_9","ROM","14","9","9","כי לזאת מת המשיח ויקם ויחי למען יהיה אדון גם על המתים גם על החיים׃ ");
INSERT INTO heb_vpl VALUES ("RM14_10","075_14_10","ROM","14","10","10","ואתה למה זה תדין את אחיך או אתה למה תבוז לאחיך הלא כלנו עתידים לעמד לפני כסא דין אלהים׃ ");
INSERT INTO heb_vpl VALUES ("RM14_11","075_14_11","ROM","14","11","11","כי כתוב חי אני נאם יהוה כי לי תכרע כל ברך וכל לשון תודה לאלהים׃ ");
