INSERT INTO heb_vpl VALUES ("RM14_13","075_14_13","ROM","14","13","13","לכן אל נדין עוד איש את רעהו כי אם זה יהי דינכם שלא יתן איש לפני אחיו מכשול או מוקש׃ ");
INSERT INTO heb_vpl VALUES ("RM14_14","075_14_14","ROM","14","14","14","ידעתי ומבטח אני באדון ישוע כי אין דבר טמא בפני עצמו ורק טמא הוא למי שיחשבנו לו לטמא׃ ");
