INSERT INTO heb_vpl VALUES ("RM14_19","075_14_19","ROM","14","19","19","ועתה נרדפה דרך השלום ודרך הבנות יחד איש מרעהו׃ ");
INSERT INTO heb_vpl VALUES ("RM14_20","075_14_20","ROM","14","20","20","אל תהרוס את מעשה אלהים על דבר מאכל הן הכל טהור הוא אבל רע לאדם אשר יאכלנו במכשל לבו׃ ");
INSERT INTO heb_vpl VALUES ("RM14_21","075_14_21","ROM","14","21","21","טוב שלא תאכל בשר ולא תשתה יין ולא תעשה דבר אשר יתנגף בו אחיך או יכשל או יחלש׃ ");
