INSERT INTO heb_vpl VALUES ("RM15_15","075_15_15","ROM","15","15","15","אך העזתי מעט בכתבי אליכם הנה והנה כמזכיר אתכם על פי החסד הנתון לי מאת האלהים׃ ");
