INSERT INTO heb_vpl VALUES ("RM16_18","075_16_18","ROM","16","18","18","כי אנשים אשר כאלה אינם עבדים את אדנינו ישוע המשיח כי אם את כרשם ובאמרי נעם ושפת חלקות יתעו את לב הפתאים׃ ");
INSERT INTO heb_vpl VALUES ("RM16_19","075_16_19","ROM","16","19","19","כי משמעתכם נודעת לכל לכן אני שמח עליכם אך חפצתי היתכם חכמים להטיב ותמימים לבלתי הרע׃ ");
INSERT INTO heb_vpl VALUES ("RM16_20","075_16_20","ROM","16","20","20","ואלהי השלום הוא ידכא את השטן במהרה תחת רגליכם חסד אדנינו ישוע המשיח עמכם׃ ");
INSERT INTO heb_vpl VALUES ("RM16_21","075_16_21","ROM","16","21","21","טימותיוס חברי ולוקיוס ויסון וסוספטרוס קרובי שאלים לשלומכם׃ ");
INSERT INTO heb_vpl VALUES ("RM16_22","075_16_22","ROM","16","22","22","אני טרטיוס כותב האגרת הזאת שאל לשלומכם באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("RM16_23","075_16_23","ROM","16","23","23","גיוס המארח אותי ואת כל הקהלה שאל לשלומכם ארסטוס סכן העיר וקורטוס אחינו שאלים לשלומכם׃ ");
INSERT INTO heb_vpl VALUES ("RM16_24","075_16_24","ROM","16","24","24","חסד אדנינו ישוע המשיח עם כלכם אמן׃ ");
INSERT INTO heb_vpl VALUES ("RM16_25","075_16_25","ROM","16","25","25","ולאשר יכל לחזק אתכם כבשורתי וכקריאת ישוע המשיח כפי גלוי הסוד אשר היה מכסה מימות עולם׃ ");
INSERT INTO heb_vpl VALUES ("RM16_26","075_16_26","ROM","16","26","26","ועתה נתפרסם ונודע על ידי כתבי הנביאים כמצות אלהי עולם לכל הגוים להביאם למשמעת האמונה׃ ");
INSERT INTO heb_vpl VALUES ("RM16_27","075_16_27","ROM","16","27","27","לאלהים החכם לבדו לו הכבוד בישוע המשיח לעולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("C11_1","076_1_1","1CO","1","1","1","פולוס המקרא להיות שליח ישוע המשיח ברצון אלהים וסוסתניס אחינו׃ ");
INSERT INTO heb_vpl VALUES ("C11_2","076_1_2","1CO","1","2","2","אל קהלת אלהים אשר בקורנתוס אל המקדשים במשיח ישוע הקרואים להיות קדשים עם כל הקראים בשם אדנינו ישוע המשיח בכל מקום שלהם ושלנו׃ ");
INSERT INTO heb_vpl VALUES ("C11_3","076_1_3","1CO","1","3","3","חסד לכם ושלום מאת האלהים אבינו ואדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C11_4","076_1_4","1CO","1","4","4","אודה לאלהי בעבורכם בכל עת על חסד האלהים הנתן לכם במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("C11_5","076_1_5","1CO","1","5","5","אשר עשרתם בו בכל בכל דבור ובכל דעת׃ ");
INSERT INTO heb_vpl VALUES ("C11_6","076_1_6","1CO","1","6","6","באשר עדות המשיח התקימה בכם׃ ");
INSERT INTO heb_vpl VALUES ("C11_7","076_1_7","1CO","1","7","7","עד כי לא חסרתם כל מתן החסד והנכם מחכים להתגלות אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C11_8","076_1_8","1CO","1","8","8","אשר גם יקים אתכם ער עת קץ להיות נקיים ביום אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C11_9","076_1_9","1CO","1","9","9","נאמן הוא האלהים אשר על פיו נקראתם לחברת בנו ישוע המשיח אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("C11_10","076_1_10","1CO","1","10","10","והנני מזהיר אתכם אחי בשם אדנינו ישוע המשיח להיות כלכם פה אחד ולא תהיין מחלקות בקרבכם כי אם תכוננו יחד בלב אחד ובעצה אחת׃ ");
INSERT INTO heb_vpl VALUES ("C11_11","076_1_11","1CO","1","11","11","כי הגד לי עליכם ביד בני בית כלואה כי יש מריבות ביניכם׃ ");
INSERT INTO heb_vpl VALUES ("C11_12","076_1_12","1CO","1","12","12","וזאת אני אמר כי איש איש מכם זה אמר לפולוס וזה לאפולוס וזה לכיפא וזה למשיח הנני׃ ");
INSERT INTO heb_vpl VALUES ("C11_13","076_1_13","1CO","1","13","13","הכי חלק המשיח הכי פולוס נצלב בעדכם או לשם פולוס נטבלתם׃ ");
INSERT INTO heb_vpl VALUES ("C11_14","076_1_14","1CO","1","14","14","אודה לאלהים שלא טבלתי איש מכם כי אם את קרספוס ואת גיוס׃ ");
INSERT INTO heb_vpl VALUES ("C11_15","076_1_15","1CO","1","15","15","פן יאמרו כי לשמי טבלתי׃ ");
INSERT INTO heb_vpl VALUES ("C11_16","076_1_16","1CO","1","16","16","אך טבלתי גם את בני בית אסטפנוס ומלבד אלה אינני ידע אם טבלתי עוד איש אחר׃ ");
INSERT INTO heb_vpl VALUES ("C11_17","076_1_17","1CO","1","17","17","כי לא שלחני המשיח לטבול כי אם לבשר לא בחכמת דברים למען אשר לא יהיה לריק צלב המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C11_18","076_1_18","1CO","1","18","18","כי דבר הצלב סכלות הוא לאבדים אבל לנו הנושעים גבורת אלהים הוא׃ ");
INSERT INTO heb_vpl VALUES ("C11_19","076_1_19","1CO","1","19","19","כי כן כתוב אאבד חכמת חכמים ובינת נבונים אסתיר׃ ");
INSERT INTO heb_vpl VALUES ("C11_20","076_1_20","1CO","1","20","20","איה חכם איה ספר איה דרש העולם הזה הלא סכל האלהים את חכמת העולם הזה׃ ");
INSERT INTO heb_vpl VALUES ("C11_21","076_1_21","1CO","1","21","21","כי אחרי אשר בחכמת האלהים לא ידע העולם את האלהים בחכמה היה רצון לפניו להושיע בסכלות הקריאה את המאמינים׃ ");
INSERT INTO heb_vpl VALUES ("C11_22","076_1_22","1CO","1","22","22","כי היהודים שאלים להם אות והיונים מבקשים חכמה׃ ");
INSERT INTO heb_vpl VALUES ("C11_23","076_1_23","1CO","1","23","23","ואנחנו משמיעים את המשיח הצלוב מכשול ליהודים וסכלות ליונים׃ ");
INSERT INTO heb_vpl VALUES ("C11_24","076_1_24","1CO","1","24","24","אבל למקראים הן מיהודים הן מיונים את המשיח אשר הוא גבורת אלהים וחכמת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C11_25","076_1_25","1CO","1","25","25","יען כי סכלות האל חכמה היא מאדם וחלשת האל חזקה היא מאדם׃ ");
INSERT INTO heb_vpl VALUES ("C11_26","076_1_26","1CO","1","26","26","כי ראו נא אחי את קריאתכם שלא רבים המה החכמים לפי הבשר לא רבים השליטים ולא רבים החרים׃ ");
INSERT INTO heb_vpl VALUES ("C11_27","076_1_27","1CO","1","27","27","כי אם בסכל שבעולם בחר האל למען ביש את החכמים ובחלוש שבעולם בחר האל למען ביש את החזק׃ ");
INSERT INTO heb_vpl VALUES ("C11_28","076_1_28","1CO","1","28","28","ובדלת העולם בחר האל ובנמאס ובאשר כאין למען בטל את אשר ישנו׃ ");
INSERT INTO heb_vpl VALUES ("C11_29","076_1_29","1CO","1","29","29","כדי שלא יתהלל לפניו כל בשר׃ ");
INSERT INTO heb_vpl VALUES ("C11_30","076_1_30","1CO","1","30","30","וממנו אתם במשיח ישוע אשר היה לנו לחכמה מאת האלהים ולצדקה ולקדוש ולפדיון׃ ");
INSERT INTO heb_vpl VALUES ("C11_31","076_1_31","1CO","1","31","31","ויהי ככתוב המתהלל יתהלל ביהוה׃ ");
INSERT INTO heb_vpl VALUES ("C12_1","076_2_1","1CO","2","1","1","וגם אנכי בבאי אליכם אחי לא באתי בגאות הדבור והחכמה בהגידי לכם את עדות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C12_2","076_2_2","1CO","2","2","2","כי לא חשבתי לדעת בתוככם דבר בלתי אם ישוע המשיח והוא הנצלב׃ ");
INSERT INTO heb_vpl VALUES ("C12_3","076_2_3","1CO","2","3","3","ואהי אצלכם בחלשה וביראה ובחלחלה רבה׃ ");
INSERT INTO heb_vpl VALUES ("C12_4","076_2_4","1CO","2","4","4","ודברי וקריאתי לא לפתות באמרי חכמת בני אדם כי אם בתוכחת הרוח והגבורה׃ ");
INSERT INTO heb_vpl VALUES ("C12_5","076_2_5","1CO","2","5","5","למען אשר לא תהיה אמונתכם בחכמת בני אדם כי אם בגבורת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C12_6","076_2_6","1CO","2","6","6","אכן חכמה נדבר בין השלמים לא חכמת העולם הזה גם לא של שרי העולם הזה אשר יאבדו׃ ");
INSERT INTO heb_vpl VALUES ("C12_7","076_2_7","1CO","2","7","7","כי אם בסוד נדבר חכמת האלהים הנסתרה אשר האלהים יעדה לכבודנו לפני ימי העולם׃ ");
INSERT INTO heb_vpl VALUES ("C12_8","076_2_8","1CO","2","8","8","אשר לא ידעה איש משרי העולם הזה כי לו ידעוה לא צלבו את אדון הכבוד׃ ");
INSERT INTO heb_vpl VALUES ("C12_9","076_2_9","1CO","2","9","9","אלא ככתוב אשר עין לא ראתה ואזן לא שמעה ולא עלה על לב אנוש את אשר הכין האלהים לאהביו׃ ");
INSERT INTO heb_vpl VALUES ("C12_10","076_2_10","1CO","2","10","10","ולנו גלה האלהים ברוחו כי הרוח חוקר את הכל גם את מעמקי האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C12_11","076_2_11","1CO","2","11","11","כי מי הוא בבני אדם הידע את אשר באדם בלתי אם רוח האדם אשר בקרבו כן גם לא ידע איש את אשר באלהים בלתי אם רוח האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C12_12","076_2_12","1CO","2","12","12","ואנחנו לא קבלנו את רוח העולם כי אם הרוח מאת האלהים למען נדע את אשר נתן לנו מאת האלהים בחסדו׃ ");
INSERT INTO heb_vpl VALUES ("C12_13","076_2_13","1CO","2","13","13","ואת זאת נדבר לא בדברים אשר תלמדם חכמת בני אדם כי אם בדברים אשר רוח הקדש תלמדם ונבאר דברים רוחניים על פי הרוח׃ ");
INSERT INTO heb_vpl VALUES ("C12_14","076_2_14","1CO","2","14","14","הן האדם הנפשי איננו מקבל את דברי רוח אלהים כי המה סכלות לו ולא יוכל להבינם באשר המה נדונים בדרך הרוח׃ ");
INSERT INTO heb_vpl VALUES ("C12_15","076_2_15","1CO","2","15","15","אבל האדם הרוחני ידין את הכל ואותו לא ידין איש׃ ");
INSERT INTO heb_vpl VALUES ("C12_16","076_2_16","1CO","2","16","16","כי מי תכן את רוח יהוה ומי יודיענו ואנחנו הנה יש לנו רוח המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C13_1","076_3_1","1CO","3","1","1","ואני לא יכלתי לדבר עמכם אחי כעם רוחניים כי עודכם של הבשר וכמו עוללים במשיח׃ ");
INSERT INTO heb_vpl VALUES ("C13_2","076_3_2","1CO","3","2","2","חלב השקיתי אתכם ולא מאכל כי אז לא יכלתם וגם עתה לא תוכלו יען היתכם עוד של הבשר׃ ");
INSERT INTO heb_vpl VALUES ("C13_3","076_3_3","1CO","3","3","3","כי באשר קנאה ומריבה ומחלקים ביניכם הלא של הבשר אתם ומתהלכים לפי דרך בני אדם׃ ");
INSERT INTO heb_vpl VALUES ("C13_4","076_3_4","1CO","3","4","4","הן באמר האחד אני לפולוס והשני אני לאפולוס הלא של הבשר אתם׃ ");
INSERT INTO heb_vpl VALUES ("C13_5","076_3_5","1CO","3","5","5","מי אפוא פולוס ומי הוא אפולוס אך משרתים הם אשר על ידם באתם להאמין איש איש כמתנת האדון אשר נתן לו׃ ");
INSERT INTO heb_vpl VALUES ("C13_6","076_3_6","1CO","3","6","6","אני נטעתי ואפולוס השקה אבל האלהים הוא הצמיח׃ ");
INSERT INTO heb_vpl VALUES ("C13_7","076_3_7","1CO","3","7","7","על כן הנטע איננו מאומה והמשקה איננו מאומה כי אם האלהים המצמיח׃ ");
INSERT INTO heb_vpl VALUES ("C13_8","076_3_8","1CO","3","8","8","והנטע והמשקה כאחד המה ואיש איש יקבל את שכרו כפי עמלו׃ ");
INSERT INTO heb_vpl VALUES ("C13_9","076_3_9","1CO","3","9","9","כי עזרי אל אנחנו ואתם שדה אלהים ובנין אלהים אתם׃ ");
INSERT INTO heb_vpl VALUES ("C13_10","076_3_10","1CO","3","10","10","11-01 ואני כפי חסד אלהים הנתן לי כבני חכם שתי יסוד ואחר בונה עליו אך ירא כל איש לשית יסוד אחר חוץ מן המוסד שהוא ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C13_11","076_3_11","1CO","3","11","11","11-01׃ ");
INSERT INTO heb_vpl VALUES ("C13_12","076_3_12","1CO","3","12","12","ואם יבנה הבונה על היסוד הזה זהב או כסף או אבנים יקרות או עץ או חציר או קש׃ ");
INSERT INTO heb_vpl VALUES ("C13_13","076_3_13","1CO","3","13","13","מעשה כל איש יגלה כי היום הוא יבררהו כי באש יראה ואת מה מעשה כל איש ואיש האש תבחננו׃ ");
INSERT INTO heb_vpl VALUES ("C13_14","076_3_14","1CO","3","14","14","אם יעמד מעשה איש אשר בנה עליו יקבל שכרו׃ ");
INSERT INTO heb_vpl VALUES ("C13_15","076_3_15","1CO","3","15","15","ואם ישרף מעשהו יפסידנו והוא יושע אך כמו מצל מאש׃ ");
INSERT INTO heb_vpl VALUES ("C13_16","076_3_16","1CO","3","16","16","הלא ידעתם כי היכל אלהים אתם ורוח אלהים שכן בקרבכם׃ ");
INSERT INTO heb_vpl VALUES ("C13_17","076_3_17","1CO","3","17","17","ואיש אשר ישחית את היכל אלהים האלהים ישחית אתו כי היכל אלהים קדוש ואתם הנכם קדושים׃ ");
INSERT INTO heb_vpl VALUES ("C13_18","076_3_18","1CO","3","18","18","אל ירמה איש את עצמו והחשב את עצמו חכם בעולם הזה יהי לסכל למען יחכם׃ ");
INSERT INTO heb_vpl VALUES ("C13_19","076_3_19","1CO","3","19","19","כי חכמת העולם הזה סכלות היא לפני האלהים ככתוב לכד חכמים בערמם׃ ");
INSERT INTO heb_vpl VALUES ("C13_20","076_3_20","1CO","3","20","20","ועוד כתוב יהוה ידע מחשבות חכמים כי המה הבל׃ ");
INSERT INTO heb_vpl VALUES ("C13_21","076_3_21","1CO","3","21","21","על כן אל יתהלל איש באדם כי הכל הוא שלכם׃ ");
INSERT INTO heb_vpl VALUES ("C13_22","076_3_22","1CO","3","22","22","אם פולוס אם אפולוס ואם כיפא אם העולם אם החיים ואם המות אם ההוה ואם העתיד הכל הוא שלכם׃ ");
INSERT INTO heb_vpl VALUES ("C13_23","076_3_23","1CO","3","23","23","ואתם הנכם של המשיח והמשיח הוא של אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C14_1","076_4_1","1CO","4","1","1","כן יחשב איש אתנו כמשרתי המשיח וסכני רזי אל׃ ");
INSERT INTO heb_vpl VALUES ("C14_2","076_4_2","1CO","4","2","2","הנה סוף דבר שלא יבקש מן הסכנים כי אם להמצא נאמן׃ ");
INSERT INTO heb_vpl VALUES ("C14_3","076_4_3","1CO","4","3","3","ואני נקלה היא בעיני כי אתם דנים אתי או יום דין של בני אדם גם אני את נפשי לא אדין׃ ");
INSERT INTO heb_vpl VALUES ("C14_4","076_4_4","1CO","4","4","4","כי אינני יודע בנפשי רע ובכל זאת לא אצדק כי הדן אתי הוא יהוה׃ ");
INSERT INTO heb_vpl VALUES ("C14_5","076_4_5","1CO","4","5","5","על כן אל תשפטו שפוט לפני העת עד כי יבוא האדון אשר גם יוציא לאור את תעלמות החשך ויגלה את עצת הלבבות ואז תהיה תהלה לכל איש מאת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C14_6","076_4_6","1CO","4","6","6","ואת זאת אחי הסבתי על עצמי ועל אפולוס בעבורכם למען תלמדו בנו שלא יתחכם איש יותר ממה שכתוב פן תתגאו איש בשם איש לנגד רעהו׃ ");
INSERT INTO heb_vpl VALUES ("C14_7","076_4_7","1CO","4","7","7","כי מי הפליא אותך ומה בידך אשר לא קבלתו ואם קבלתו למה תתהלל כאיש אשר לא קבל׃ ");
INSERT INTO heb_vpl VALUES ("C14_8","076_4_8","1CO","4","8","8","הן כבר שבעתם כבר עשרתם ובלעדינו מלכתם ולו מלכתם למען נמלך אתכם גם אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("C14_9","076_4_9","1CO","4","9","9","כי אחשב שהאלהים הציג אתנו השליחים שפלי השפלים כבני תמותה כי היינו לראוה לעולם גם למלאכים גם לבני אדם׃ ");
INSERT INTO heb_vpl VALUES ("C14_10","076_4_10","1CO","4","10","10","אנחנו סכלים למען המשיח ואתם חכמים במשיח אנחנו חלשים ואתם גבורים אתם נכבדים ואנחנו נקלים׃ ");
INSERT INTO heb_vpl VALUES ("C14_11","076_4_11","1CO","4","11","11","ועד השעה הזאת הננו רעבים גם צמאים וערמים ומכים באגרף ואין מנוח לנו׃ ");
INSERT INTO heb_vpl VALUES ("C14_12","076_4_12","1CO","4","12","12","ויגעים אנחנו בעמל ידינו קללונו ונברך חרפונו ונסבל׃ ");
INSERT INTO heb_vpl VALUES ("C14_13","076_4_13","1CO","4","13","13","גדפו אתנו ותנחנן ונהי כגללי העולם ולסחי לכלם עד עתה׃ ");
INSERT INTO heb_vpl VALUES ("C14_14","076_4_14","1CO","4","14","14","ולא לביש אתכם אני כתב הדברים האלה כי אם מזהיר אתכם כבני האהובים׃ ");
INSERT INTO heb_vpl VALUES ("C14_15","076_4_15","1CO","4","15","15","כי גם אם היו לכם רבבות אמנים במשיח אין לכם אבות רבים כי אנכי הולדתי אתכם בישוע המשיח על ידי הבשורה׃ ");
INSERT INTO heb_vpl VALUES ("C14_16","076_4_16","1CO","4","16","16","על כן אני מבקש מכם ללכת בעקבותי׃ ");
INSERT INTO heb_vpl VALUES ("C14_17","076_4_17","1CO","4","17","17","ובעבור זאת שלחתי אליכם את טימותיוס בני האהוב והנאמן באדון והוא יזכיר לכם את דרכי במשיח כאשר מלמד אנכי בכל מקום בכל קהלה וקהלה׃ ");
INSERT INTO heb_vpl VALUES ("C14_18","076_4_18","1CO","4","18","18","הן יש מתנשאים כאלו לא אבוא אליכם׃ ");
INSERT INTO heb_vpl VALUES ("C14_19","076_4_19","1CO","4","19","19","אבל בוא אבוא אליכם בזמן קרוב אם ירצה האדון ואדעה לא את דברי המתרוממים כי אם את גבורתם׃ ");
INSERT INTO heb_vpl VALUES ("C14_20","076_4_20","1CO","4","20","20","כי מלכות האלהים איננה בדבר שפתים כי אם בגבורה׃ ");
INSERT INTO heb_vpl VALUES ("C14_21","076_4_21","1CO","4","21","21","ומה תחפצו הבוא אבוא אליכם בשבט או באהבה וברוח ענוה׃ ");
INSERT INTO heb_vpl VALUES ("C15_1","076_5_1","1CO","5","1","1","שמועה נשמעת בארץ כי נמצאה זנות ביניכם ואף זנות אשר בגוים לא ספר כמוה כי יקח איש את אשת אביו׃ ");
INSERT INTO heb_vpl VALUES ("C15_2","076_5_2","1CO","5","2","2","ואתם עוד גבהי רוח תחת אשר היה לכם להתאבל למען יוסר מקרבכם עשה המעשה הזה׃ ");
INSERT INTO heb_vpl VALUES ("C15_3","076_5_3","1CO","5","3","3","הן אנכי הרחוק מכם בגופי וקרוב ברוחי כבר דנתי כאלו הייתי אצלכם על האיש אשר עשה כדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("C15_4","076_5_4","1CO","5","4","4","בשם אדנינו ישוע המשיח בהקהלתכם יחד ורוחי אתכם עם גבורת אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C15_5","076_5_5","1CO","5","5","5","למסר את האיש ההוא לשטן לאבדן הבשר למען יושע הרוח ביום האדון ישוע׃ ");
INSERT INTO heb_vpl VALUES ("C15_6","076_5_6","1CO","5","6","6","לא טוב התהללכם הלא ידעתם כי מעט שאר מחמץ את כל העסה׃ ");
INSERT INTO heb_vpl VALUES ("C15_7","076_5_7","1CO","5","7","7","בערו את השאור הישן למען תהיו עסה חדשה הלא לחם מצות אתם כי גם לנו פסחנו הנזבח בעדנו הוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C15_8","076_5_8","1CO","5","8","8","על כן נחגה נא החג לא בשאר ישן ולא בשאר הרע והרשע כי אם במצות הישר והאמת׃ ");
INSERT INTO heb_vpl VALUES ("C15_9","076_5_9","1CO","5","9","9","כתבתי לכם באגרת שלא תתערבו עם הזנים׃ ");
INSERT INTO heb_vpl VALUES ("C15_10","076_5_10","1CO","5","10","10","ואין דעתי בזאת על הזנים שבעולם הזה או על בצעי בצע וגזלנים ועבדי אלילים כי אז יהיה לכם לצאת מן העולם׃ ");
INSERT INTO heb_vpl VALUES ("C15_11","076_5_11","1CO","5","11","11","אך זאת כתבתי לכם לבלתי התערב עם איש אשר אח יקרא והוא זנה או בצע בצע או עבד אלילים או מגדף או סבא או גזלן עם האיש אשר כזה גם לא תאכלו׃ ");
INSERT INTO heb_vpl VALUES ("C15_12","076_5_12","1CO","5","12","12","כי מה לי לשפט את אשר בחוץ הלא תשפטו את אשר בבית׃ ");
INSERT INTO heb_vpl VALUES ("C15_13","076_5_13","1CO","5","13","13","ואשר בחוץ האלהים ישפטם ואתם תבערו את הרע מקרבכם׃ ");
INSERT INTO heb_vpl VALUES ("C16_1","076_6_1","1CO","6","1","1","היש בכם איש אשר בריבו עם רעהו יזיד להביא דבר דינו לפני הרשעים ולא לפני הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("C16_2","076_6_2","1CO","6","2","2","הלא ידעתם כי הקדשים ידינו את העולם ואם העולם ידון על ידכם האינכם ראוים לדין דינים קטנים׃ ");
INSERT INTO heb_vpl VALUES ("C16_3","076_6_3","1CO","6","3","3","הלא ידעתם כי נדין את המלאכים אף כי דברי ממונות׃ ");
INSERT INTO heb_vpl VALUES ("C16_4","076_6_4","1CO","6","4","4","ואתם כאשר יש לכם דיני ממונות מושיבים אתם את הנחשבים לאין בקהל לשפטיכם׃ ");
INSERT INTO heb_vpl VALUES ("C16_5","076_6_5","1CO","6","5","5","לבשתכם אמר אני את זאת הכי אין בכם חכם אחד שיוכל להוכיח בין איש לאחיו׃ ");
INSERT INTO heb_vpl VALUES ("C16_6","076_6_6","1CO","6","6","6","כי אח רב עם אחיו וזאת לפני לא מאמינים׃ ");
INSERT INTO heb_vpl VALUES ("C16_7","076_6_7","1CO","6","7","7","הן בכל ירידה היא לכם שתריבו זה עם זה למה לא תבחרו לסבל הונאה ולמה לא תבחרו להיות עשוקים׃ ");
INSERT INTO heb_vpl VALUES ("C16_8","076_6_8","1CO","6","8","8","אבל מונים אתם ועשקים אף את אחיכם׃ ");
INSERT INTO heb_vpl VALUES ("C16_9","076_6_9","1CO","6","9","9","הלא ידעתם כי הרשעים לא יירשו את מלכות האלהים אל תתעו את נפשותיכם לא הזנים לא עבדי אלילים לא המנאפים ולא הקדשים ולא השכבים את זכר׃ ");
INSERT INTO heb_vpl VALUES ("C16_10","076_6_10","1CO","6","10","10","לא הגנבים ולא בצעי בצע לא הסבאים ולא המגדפים ולא הגזלנים כל אלה לא יירשו את מלכות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C16_11","076_6_11","1CO","6","11","11","וכאלה לפנים היו מקצתכם אבל רחצתם אבל קדשתם אבל הצדקתם בשם האדון ישוע וברוח אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("C16_12","076_6_12","1CO","6","12","12","הכל הוא ברשותי אך לא כל דבר יועיל הכל הוא ברשותי אך לא ישעבדני דבר׃ ");
INSERT INTO heb_vpl VALUES ("C16_13","076_6_13","1CO","6","13","13","המאכל לכרש והכרש למאכל והאלהים את זה ואת זה ילכה והגוף אל יהי לזנות כי אם לאדון והאדון לגוף׃ ");
INSERT INTO heb_vpl VALUES ("C16_14","076_6_14","1CO","6","14","14","והאלהים העיר גם את אדנינו ויעיר גם אתכם בגבורתו׃ ");
INSERT INTO heb_vpl VALUES ("C16_15","076_6_15","1CO","6","15","15","הלא ידעתם כי גופתיכם אברי המשיח הנה הכי אקח את אברי המשיח ואעשה אתם לאברי זונה חלילה׃ ");
INSERT INTO heb_vpl VALUES ("C16_16","076_6_16","1CO","6","16","16","או הלא ידעתם כי הדבק בזונה גוף אחד הוא עמה כי הכתוב אמר והיו שניהם לבשר אחד׃ ");
INSERT INTO heb_vpl VALUES ("C16_17","076_6_17","1CO","6","17","17","אבל הדבק באדון רוח אחד הוא עמו׃ ");
INSERT INTO heb_vpl VALUES ("C16_18","076_6_18","1CO","6","18","18","נוסו מן הזנות כל חטא אשר יעשה אותו האדם מחוץ לגופו הוא והזונה חטא בעצם גופו׃ ");
INSERT INTO heb_vpl VALUES ("C16_19","076_6_19","1CO","6","19","19","או הלא ידעתם כי גופכם הוא היכל רוח הקדש השכן בקרבכם אשר קבלתם מאת האלהים וכי לא לעצמכם אתם׃ ");
INSERT INTO heb_vpl VALUES ("C16_20","076_6_20","1CO","6","20","20","כי במחיר נקניתם על כן כבדו את האלהים בגופכם וברוחכם אשר לאלהים המה׃ ");
INSERT INTO heb_vpl VALUES ("C17_1","076_7_1","1CO","7","1","1","ולענים מה שכתבתם אלי הנה טוב לאדם שלא יגע באשה׃ ");
INSERT INTO heb_vpl VALUES ("C17_2","076_7_2","1CO","7","2","2","אך מפני הזנות תהי לכל איש אשתו ויהי לכל אשה בעלה׃ ");
INSERT INTO heb_vpl VALUES ("C17_3","076_7_3","1CO","7","3","3","האיש יקים חובת העונה לאשתו וכמו כן האשה לבעלה׃ ");
INSERT INTO heb_vpl VALUES ("C17_4","076_7_4","1CO","7","4","4","האשה איננה שלטת על גופה כי אם בעלה וכמו כן גם האיש איננו שלט על גופו כי אם אשתו׃ ");
INSERT INTO heb_vpl VALUES ("C17_5","076_7_5","1CO","7","5","5","אל תמנעו את עצמכם זה מזה זולתי בהסכמת שניכם על זמן קבוע להיות פנוים לתענית ולתפלה ותשובו ותתאחדו פן ינסה אתכם השטן בעבור פריצות יצרכם׃ ");
INSERT INTO heb_vpl VALUES ("C17_6","076_7_6","1CO","7","6","6","ואני אמר זאת בדרך עצה ולא בדרך מצוה׃ ");
INSERT INTO heb_vpl VALUES ("C17_7","076_7_7","1CO","7","7","7","כי מי יתן והיה כל אדם כמני אך יש לכל איש מתנתו מאת האלהים זה בכה וזה בכה׃ ");
INSERT INTO heb_vpl VALUES ("C17_8","076_7_8","1CO","7","8","8","ואל הפנוים ואל האלמנות אמר אני כי טוב להם אם ישבו ככה כמו גם אני׃ ");
INSERT INTO heb_vpl VALUES ("C17_9","076_7_9","1CO","7","9","9","אך אם לא יוכלו להנזר יתחברו בנשואין כי טוב להתחבר בנשואין מהיות בער בתאוה׃ ");
INSERT INTO heb_vpl VALUES ("C17_10","076_7_10","1CO","7","10","10","והנה את הנשואים אנכי מצוה ולא אנכי כי אם האדון אשר לא תפרש אשה מבעלה׃ ");
INSERT INTO heb_vpl VALUES ("C17_11","076_7_11","1CO","7","11","11","ואם פרש תפרש ממנו תשב בלא איש או תתרצה לבעלה ואיש אל ישלח את אשתו׃ ");
INSERT INTO heb_vpl VALUES ("C17_12","076_7_12","1CO","7","12","12","והנה אל האחרים אמר אנכי ולא האדון כי תהיה לאח אשה אשר איננה מאמנת ורצונה לשבת עמו לא יעזבנה׃ ");
INSERT INTO heb_vpl VALUES ("C17_13","076_7_13","1CO","7","13","13","ואשה כי יהיה לה בעל אשר איננו מאמין ורצונו לשבת עמה לא תעזבנו׃ ");
INSERT INTO heb_vpl VALUES ("C17_14","076_7_14","1CO","7","14","14","כי האיש אשר איננו מאמין מקדש הוא באשה והאשה אשר איננה מאמנת מקדשת היא באיש שאם לא כן יהיו בניכם טמאים אמנם עתה קדושים המה׃ ");
INSERT INTO heb_vpl VALUES ("C17_15","076_7_15","1CO","7","15","15","אבל אם יפרש מי שאיננו מאמין יפרש והאח או האחות אינם משעבדים באלה כי לשלום קראנו האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C17_16","076_7_16","1CO","7","16","16","כי מה תדעי את האשה אם תושיעי את האיש ומה תדע אתה האיש אם תושיע את האשה׃ ");
INSERT INTO heb_vpl VALUES ("C17_17","076_7_17","1CO","7","17","17","רק יתהלך איש איש כפי מה שחלק לו האלהים וכפי מה שקרא אתו האדון וכן מתקן אנכי בכל הקהלות׃ ");
INSERT INTO heb_vpl VALUES ("C17_18","076_7_18","1CO","7","18","18","אם נמול האיש המקרא אל ימשך את ערלתו ואם ערל הוא אל ימול׃ ");
INSERT INTO heb_vpl VALUES ("C17_19","076_7_19","1CO","7","19","19","אין המילה נחשבה ואין הערלה נחשבה כי אם שמירת מצות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C17_20","076_7_20","1CO","7","20","20","איש איש במשמרתו אשר נקרא בה שם יעמד׃ ");
INSERT INTO heb_vpl VALUES ("C17_21","076_7_21","1CO","7","21","21","אם נקראת בהיותך עבד אל ירע בעיניך אלא אם תשיג ידך לצאת לחפשי בחר בזה׃ ");
INSERT INTO heb_vpl VALUES ("C17_22","076_7_22","1CO","7","22","22","כי הקרוא באדון בהיותו עבד משחרר הוא לאדון וככה גם הקרוא בהיותו חפשי עבד הוא למשיח׃ ");
INSERT INTO heb_vpl VALUES ("C17_23","076_7_23","1CO","7","23","23","במחיר נקניתם אל תהיו עבדי בני אדם׃ ");
INSERT INTO heb_vpl VALUES ("C17_24","076_7_24","1CO","7","24","24","איש איש במשמרת אשר נקרא בה אחי בזאת יעמד לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C17_25","076_7_25","1CO","7","25","25","ועל דבר הבתולות אין לי מצוה מאת האדון רק אודיע את עצתי אחרי אשר חנני האדון להיות נאמן׃ ");
INSERT INTO heb_vpl VALUES ("C17_26","076_7_26","1CO","7","26","26","הנני חשב כי טוב לאדם מפני הצרה הקרובה כי טוב לו להיות כמו שהוא׃ ");
INSERT INTO heb_vpl VALUES ("C17_27","076_7_27","1CO","7","27","27","אם נקשרת באשה אל תבקש להפטר ואם נפטרת אל תבקש אשה׃ ");
INSERT INTO heb_vpl VALUES ("C17_28","076_7_28","1CO","7","28","28","וגם כי תקח אשה אינך חטא והבתולה כי תהיה לאיש איננה חטאת אך יבאום צרות בבשרם והנני חס עליכם׃ ");
INSERT INTO heb_vpl VALUES ("C17_29","076_7_29","1CO","7","29","29","וזאת אני אמר אחי כי השעה דחוקה למען מעתה יהיו הנשואים כאלו אין להם נשים׃ ");
INSERT INTO heb_vpl VALUES ("C17_30","076_7_30","1CO","7","30","30","והבכים כאינם בכים והשמחים כאינם שמחים והקונים כאלו אין קנין בידם׃ ");
INSERT INTO heb_vpl VALUES ("C17_31","076_7_31","1CO","7","31","31","והנהנים מן העולם הזה כאלו אין להם הנאה ממנו כי עבור יעבר תאר העולם הזה׃ ");
INSERT INTO heb_vpl VALUES ("C17_32","076_7_32","1CO","7","32","32","ואני חפצתי שתהיו בלי דאגה מי שאין לו אשה דאג לאשר לאדון איך ייטב בעיני האדון׃ ");
INSERT INTO heb_vpl VALUES ("C17_33","076_7_33","1CO","7","33","33","ומי שיש לו אשה דאג הוא לעניני העולם איך ייטב בעיני האשה׃ ");
INSERT INTO heb_vpl VALUES ("C17_34","076_7_34","1CO","7","34","34","יש הבדל בין אשת איש לבתולה כי האשה אשר לא היתה לאיש דאגת לאשר לאדון ולהיות קדושה גם בגופה גם ברוחה ובעולת בעל דאגת היא לעניני העולם איך תיטב בעיני בעלה׃ ");
INSERT INTO heb_vpl VALUES ("C17_35","076_7_35","1CO","7","35","35","וזאת אני אמר לתועלתכם ולא להשליך עליכם פח כי אם להנהגה טובה ולהיותכם נכונים תמיד לפני האדון באין מנע׃ ");
INSERT INTO heb_vpl VALUES ("C17_36","076_7_36","1CO","7","36","36","וכי יחשב איש למעשה שלא כהגן לבתולתו אם תעבר פרקה ודבר חובה הוא אז יעשה כאשר עם לבבו איננו חוטא ישיאנה׃ ");
INSERT INTO heb_vpl VALUES ("C17_37","076_7_37","1CO","7","37","37","ומי שהוא נכון בלבו ואיננו מכרח ויוכל לעשות כרצונו ויגמר זאת בלבו לשמר את בתולתו טוב עשה׃ ");
INSERT INTO heb_vpl VALUES ("C17_38","076_7_38","1CO","7","38","38","לכן המשיא אתה טוב הוא עשה ואשר איננו משיא עשה טוב ממנו׃ ");
INSERT INTO heb_vpl VALUES ("C17_39","076_7_39","1CO","7","39","39","האשה קשורה לבעלה על פי התורה כל עת שהוא חי וכי מת בעלה אזי מתרת היא להנשא למי שתרצה ובלבד שתהיה באדון׃ ");
INSERT INTO heb_vpl VALUES ("C17_40","076_7_40","1CO","7","40","40","אבל אשריה יותר אם תעמד פנויה זאת דעתי ואחשב גם אני כי רוח אלהים בי׃ ");
INSERT INTO heb_vpl VALUES ("C18_1","076_8_1","1CO","8","1","1","ועל דבר זבחי האלילים ידענו שיש דעה לכלנו הדעת תגביה לב והאהבה היא הבונה׃ ");
INSERT INTO heb_vpl VALUES ("C18_2","076_8_2","1CO","8","2","2","החשב כי הוא ידע דבר מה עוד לא ידע מאומה כאשר עליו לדעת אתו׃ ");
INSERT INTO heb_vpl VALUES ("C18_3","076_8_3","1CO","8","3","3","אבל אם יאהב איש את האלהים האלהים ידעו׃ ");
INSERT INTO heb_vpl VALUES ("C18_4","076_8_4","1CO","8","4","4","ועל דבר אכילת זבחי האלילים הנה ידענו כי האליל אין בעולם ואין אלהים בלתי אחד׃ ");
INSERT INTO heb_vpl VALUES ("C18_5","076_8_5","1CO","8","5","5","ואף כי יש הנקראים אלהים אם בשמים אם בארץ באשר יש אלהים רבים ואדנים רבים׃ ");
INSERT INTO heb_vpl VALUES ("C18_6","076_8_6","1CO","8","6","6","אמנם לנו אך לא אחד האב אשר הכל ממנו ואנחנו אליו ואדון אחד ישוע המשיח אשר הכל על ידו ונחנו על ידו׃ ");
INSERT INTO heb_vpl VALUES ("C18_7","076_8_7","1CO","8","7","7","אך לא בכלם הדעת כי יש אשר בזכרם עוד את האליל אכלים כזבח האליל ובכן לבם החלוש יתגאל׃ ");
INSERT INTO heb_vpl VALUES ("C18_8","076_8_8","1CO","8","8","8","המאכל לא יקרב אתכם לאלהים כי אם נאכל אין לנו יתרון ואם לא נאכל לא נגרע׃ ");
INSERT INTO heb_vpl VALUES ("C18_9","076_8_9","1CO","8","9","9","אבל הזהרו פן יהיה אתו הרשיון שלכם למכשל החלשים׃ ");
INSERT INTO heb_vpl VALUES ("C18_10","076_8_10","1CO","8","10","10","כי האיש הראה אתך אשר לך הדעת מסב בבית אלילים הלא יעז ברוחו החלוש לאכל מזבחי אלילים׃ ");
INSERT INTO heb_vpl VALUES ("C18_11","076_8_11","1CO","8","11","11","ויאבד על ידי דעתך אחיך החלש אשר למענו מת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C18_12","076_8_12","1CO","8","12","12","ואם ככה תחטאו לאחיכם ותכאיבו את רוחם החלוש למשיח אתם חטאים׃ ");
INSERT INTO heb_vpl VALUES ("C18_13","076_8_13","1CO","8","13","13","על כן אם מאכלי מכשיל את אחי לא אכל בשר לעולם למען לא אכשיל את אחי׃ ");
INSERT INTO heb_vpl VALUES ("C19_1","076_9_1","1CO","9","1","1","הלא שליח אנכי הלא חפשי אנכי הלא ראיתי את ישוע המשיח אדנינו הלא אתם פעלי באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("C19_2","076_9_2","1CO","9","2","2","ואם אינני שליח לאחרים אך לכם הנני שליח כי חותם שליחותי אתם באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("C19_3","076_9_3","1CO","9","3","3","וזאת התנצלותי כנגד הדנים אותי׃ ");
INSERT INTO heb_vpl VALUES ("C19_4","076_9_4","1CO","9","4","4","האין רשות בידנו לאכל ולשתות׃ ");
INSERT INTO heb_vpl VALUES ("C19_5","076_9_5","1CO","9","5","5","האין רשות בידנו להוליך עמנו אחות לאשה כמו גם השליחים האחרים וכמו אחי האדון וכמו כיפא׃ ");
INSERT INTO heb_vpl VALUES ("C19_6","076_9_6","1CO","9","6","6","אם לי לבדי ולבר נבא לא נתנה רשות להבטל ממלאכה׃ ");
INSERT INTO heb_vpl VALUES ("C19_7","076_9_7","1CO","9","7","7","מי הלך לצבא במשכרת של עצמו מי נטע כרם ולא יאכל את פריו מי רעה עדר ומחלב העדר לא יאכל׃ ");
INSERT INTO heb_vpl VALUES ("C19_8","076_9_8","1CO","9","8","8","הכי לפי דרכו של אדם אני מדבר כזאת הלא גם התורה אמרת כן׃ ");
INSERT INTO heb_vpl VALUES ("C19_9","076_9_9","1CO","9","9","9","כי כתוב בתורת משה לא תחסם שור בדישו הלשורים הושש האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C19_10","076_9_10","1CO","9","10","10","או אך למעננו מדבר אכן למעננו נכתב כי החרש יחרש אלי תקוה והדש ידוש אלי תקוה לקחת חלקו בתקוה׃ ");
INSERT INTO heb_vpl VALUES ("C19_11","076_9_11","1CO","9","11","11","אם זרענו בכם עניני הרוח הכי דבר גדול הוא אם נקצר מכם עניני הבשר׃ ");
INSERT INTO heb_vpl VALUES ("C19_12","076_9_12","1CO","9","12","12","ואם לאחרים יש רשות עליכם הלא ביותר לנו אבל לא השתמשנו ברשות הזאת כי אם סבלנו את הכל לבלתי שום מעצור לבשורת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C19_13","076_9_13","1CO","9","13","13","הלא ידעתם כי עבדי עבדת הקדש אכלים מן הקדשים ומשרתי המזבח לקחים חלקם במזבח׃ ");
INSERT INTO heb_vpl VALUES ("C19_14","076_9_14","1CO","9","14","14","כן תקן אדנינו גם הוא אשר יחיו המבשרים על הבשורה׃ ");
INSERT INTO heb_vpl VALUES ("C19_15","076_9_15","1CO","9","15","15","ואנכי לא השתמשתי באחת מאלה וגם לא כתבתי זאת למען יעשה לי כזאת כי טוב לי המות מאשר ישים איש את תהלתי לריק׃ ");
INSERT INTO heb_vpl VALUES ("C19_16","076_9_16","1CO","9","16","16","אם אבשר את הבשורה אין לי תהלה כי החובה מטלת עלי ואוי לי אם לא אבשר׃ ");
INSERT INTO heb_vpl VALUES ("C19_17","076_9_17","1CO","9","17","17","כי אם ברצוני אעשה כן יהיה לי שכר ואם בעל כרחי פקדת משמרתי היא׃ ");
INSERT INTO heb_vpl VALUES ("C19_18","076_9_18","1CO","9","18","18","ועתה מה הוא שכרי הלא זה שאבשר בשורת המשיח בלא מחיר לבלתי השתמש להנאת עצמי ברשיון הנתן לי בבשורה׃ ");
INSERT INTO heb_vpl VALUES ("C19_19","076_9_19","1CO","9","19","19","כי בהיותי חפשי מכל עשיתי עצמי עבד לכל אדם למען אקנא את הרבים׃ ");
INSERT INTO heb_vpl VALUES ("C19_20","076_9_20","1CO","9","20","20","ואהי ליהודים כיהודי לקנות היהודים ואשר הם תחת התורה הייתי להם כמו תחת התורה למען קנות אותם אשר תחת התורה׃ ");
INSERT INTO heb_vpl VALUES ("C19_21","076_9_21","1CO","9","21","21","לאלה אשר בלי תורה הייתי כבלי תורה אף כי אינני בלי תורת האלהים כי אם תחת תורת המשיח אנכי למען קנות אותם אשר בלי תורה׃ ");
INSERT INTO heb_vpl VALUES ("C19_22","076_9_22","1CO","9","22","22","ולחלשים הייתי כחלש לקנות את החלשים הכל לכלם נהייתי למען בכל דרך אושיע אחדים׃ ");
INSERT INTO heb_vpl VALUES ("C19_23","076_9_23","1CO","9","23","23","ואת זאת אני עשה בעבור הבשורה למען אקח חלקי בה גם אנכי׃ ");
INSERT INTO heb_vpl VALUES ("C19_24","076_9_24","1CO","9","24","24","הלא ידעתם כי רצי המרוצה באסטדין רצים כלם ורק אחד מהם ישיג את שכר הנצוח ככה רוצו למען תשיגהו׃ ");
INSERT INTO heb_vpl VALUES ("C19_25","076_9_25","1CO","9","25","25","וכל העמד להאבק ינזר מכל דבר המה לקחת כתר נפסד ואנחנו לקחת כתר אשר איננו נפסד׃ ");
INSERT INTO heb_vpl VALUES ("C19_26","076_9_26","1CO","9","26","26","לכן הנני רץ לא כמו בחשכה הנני נלחם לא כהולם רוח׃ ");
INSERT INTO heb_vpl VALUES ("C19_27","076_9_27","1CO","9","27","27","כי אם אדכא את גופי ואשעבדנו פן אהיה אני הקורא לאחרים נאלח בעצמי׃ ");
INSERT INTO heb_vpl VALUES ("C110_1","076_10_1","1CO","10","1","1","ולא אכחד מכם אחי אשר אבותינו היו כלם תחת הענן וכלם עברו בתוך הים׃ ");
INSERT INTO heb_vpl VALUES ("C110_2","076_10_2","1CO","10","2","2","וכלם נטבלו למשה בענן ובים׃ ");
INSERT INTO heb_vpl VALUES ("C110_3","076_10_3","1CO","10","3","3","וכלם אכלם מאכל אחד רוחני׃ ");
INSERT INTO heb_vpl VALUES ("C110_4","076_10_4","1CO","10","4","4","וכלם שתו משקה אחד רוחני כי שתו מן הצור הרוחני ההלך עמהם והצור ההוא היה המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C110_5","076_10_5","1CO","10","5","5","אבל ברבם לא רצה האלהים ופגריהם נפלו במדבר׃ ");
INSERT INTO heb_vpl VALUES ("C110_6","076_10_6","1CO","10","6","6","וכל זאת היתה לנו למופת לבלתי התאות לרעה כאשר התאוו גם המה׃ ");
INSERT INTO heb_vpl VALUES ("C110_7","076_10_7","1CO","10","7","7","ולא תהיו עבדי אלילים כאשר היו מקצתם כמו שכתוב וישב העם לאכל ושתו ויקמו לצחק׃ ");
INSERT INTO heb_vpl VALUES ("C110_8","076_10_8","1CO","10","8","8","ולא נהיה זנים כאשר זנו מקצתם ויפלו ביום אחד שלשה ועשרים אלף איש׃ ");
INSERT INTO heb_vpl VALUES ("C110_9","076_10_9","1CO","10","9","9","ולא ננסה את המשיח כאשר נסוהו מקצתם ויאבדום הנחשים׃ ");
INSERT INTO heb_vpl VALUES ("C110_10","076_10_10","1CO","10","10","10","גם לא תלינו כאשר הלינו מקצתם וימותו ביד המשחית׃ ");
INSERT INTO heb_vpl VALUES ("C110_11","076_10_11","1CO","10","11","11","כל זאת מצאתם להיות למופת ותכתב למוסר לנו אשר הגיעו אלינו קצי העולמים׃ ");
INSERT INTO heb_vpl VALUES ("C110_12","076_10_12","1CO","10","12","12","לכן החשב שהוא נצב ירא פן יפול׃ ");
INSERT INTO heb_vpl VALUES ("C110_13","076_10_13","1CO","10","13","13","עדין לא בא עליכם נסיון אחר בלתי אם נסיון בני אדם כי נאמן הוא האלהים אשר לא יניח לנסות אתכם למעלה מיכלתכם כי אם יתן עם הנסיון גם תוצאתיו כדי שתוכלו שאת׃ ");
INSERT INTO heb_vpl VALUES ("C110_14","076_10_14","1CO","10","14","14","על כן חביבי נוסו מעבודת אלילים׃ ");
INSERT INTO heb_vpl VALUES ("C110_15","076_10_15","1CO","10","15","15","כמו אל נבונים מדבר אנכי ושפטו אתם את אשר אמר׃ ");
INSERT INTO heb_vpl VALUES ("C110_16","076_10_16","1CO","10","16","16","כוס הברכה אשר אנחנו מברכים הלא היא התחברות דם המשיח והלחם אשר אנחנו בצעים הלא הוא התחברות גוף המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C110_17","076_10_17","1CO","10","17","17","כי לחם אחד הוא לכן גם נוף אחד אנחנו הרבים באשר לכלנו חלק בלחם האחד׃ ");
INSERT INTO heb_vpl VALUES ("C110_18","076_10_18","1CO","10","18","18","ראו את ישראל לפי הבשר הלא אכלי הזבחים חברי המזבח המה׃ ");
INSERT INTO heb_vpl VALUES ("C110_19","076_10_19","1CO","10","19","19","ועתה מה אמר היש ממש באליל אם יש ממש בזבחי אלילים׃ ");
INSERT INTO heb_vpl VALUES ("C110_20","076_10_20","1CO","10","20","20","אלא את אשר יזבחו הגוים לשדים הם זבחים ולא לאלהים ואני לא אחפץ היתכם חברים לשדים׃ ");
INSERT INTO heb_vpl VALUES ("C110_21","076_10_21","1CO","10","21","21","לא תוכלו לשתות יחד כוס אדנינו וגם כוס השדים ולא תוכלו להתחבר אל שלחן אדנינו וגם אל שלחן השדים׃ ");
INSERT INTO heb_vpl VALUES ("C110_22","076_10_22","1CO","10","22","22","הנעז להקניא את אדנינו הכי חזקים אנחנו ממנו׃ ");
INSERT INTO heb_vpl VALUES ("C110_23","076_10_23","1CO","10","23","23","הכל ברשותי אבל אין הכל מועיל הכל ברשותי אבל אין הכל בנה׃ ");
INSERT INTO heb_vpl VALUES ("C110_24","076_10_24","1CO","10","24","24","איש איש אל יבקש את תועלת עצמו כי אם את תועלת רעהו׃ ");
INSERT INTO heb_vpl VALUES ("C110_25","076_10_25","1CO","10","25","25","כל הנמכר במקולין אתו תאכלו ואל תחקרו מפני מכשל הלב׃ ");
INSERT INTO heb_vpl VALUES ("C110_26","076_10_26","1CO","10","26","26","כי ליהוה הארץ ומלואה׃ ");
INSERT INTO heb_vpl VALUES ("C110_27","076_10_27","1CO","10","27","27","ואם יקרא אתכם איש מאשר אינם מאמינים ותרצו ללכת אליו אכול תאכלו מכל אשר ישימו לפניכם ואל תחקרו מפני מכשול הלב׃ ");
INSERT INTO heb_vpl VALUES ("C110_28","076_10_28","1CO","10","28","28","ואיש כי יאמר אליכם זה הוא זבח אלילים אל תאכלו בעבור המודיע ומפני מכשול הלב כי ליהוה הארץ ולמואה׃ ");
INSERT INTO heb_vpl VALUES ("C110_29","076_10_29","1CO","10","29","29","והלב אשר אני אמר לא לבך כי אם לב רעך כי למה זה תשפט חרותי על ידי לב האחר׃ ");
INSERT INTO heb_vpl VALUES ("C110_30","076_10_30","1CO","10","30","30","ואם אכל אני בתודה למה אהיה מגדף על הדבר אשר אני מודה עליו׃ ");
INSERT INTO heb_vpl VALUES ("C110_31","076_10_31","1CO","10","31","31","לכן אם תאכלו או אם תשתו או כל אשר תעשו את הכל עשו לכבוד אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C110_32","076_10_32","1CO","10","32","32","ואל תתנו מכשול לא ליהודים ולא ליונים ולא לקהלת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C110_33","076_10_33","1CO","10","33","33","כאשר גם אנכי מבקש להיות רצוי לכל בכל ולא אבקש תועלת עצמי כי אם של הרבים למען יושעו׃ ");
INSERT INTO heb_vpl VALUES ("C111_1","076_11_1","1CO","11","1","1","לכו בעקבותי כאשר גם אני הלך בעקבות המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C111_2","076_11_2","1CO","11","2","2","ועל זאת אני משבח אתכם אחי כי זכרתם אתי בכל לשמר את הקבלות כאשר מסרתי לכם׃ ");
INSERT INTO heb_vpl VALUES ("C111_3","076_11_3","1CO","11","3","3","אך חפץ אנכי שתדעו כי ראש כל איש המשיח וראש האשה האיש וראש המשיח הוא האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C111_4","076_11_4","1CO","11","4","4","כל איש אשר יתפלל או יתנבא וראשו מכסה מבזה הוא את ראשו׃ ");
INSERT INTO heb_vpl VALUES ("C111_5","076_11_5","1CO","11","5","5","וכל אשה אשר תתפלל או תתנבא וראשה פרוע מבזה היא את ראשה יען בזה היא כמו מגלחה׃ ");
INSERT INTO heb_vpl VALUES ("C111_6","076_11_6","1CO","11","6","6","כי האשה אם לא תתכסה גם תתגלח ואם בזיון הוא לאשה להכסם או להתגלח תתכסה׃ ");
INSERT INTO heb_vpl VALUES ("C111_7","076_11_7","1CO","11","7","7","והאיש איננו חיב לכסות את ראשו כי הוא צלם אלהים וכבודו אבל האשה היא כבוד האיש׃ ");
INSERT INTO heb_vpl VALUES ("C111_8","076_11_8","1CO","11","8","8","כי אין האיש מן האשה כי אם האשה מן האיש׃ ");
INSERT INTO heb_vpl VALUES ("C111_9","076_11_9","1CO","11","9","9","גם לא נברא האיש בעבור האשה כי אם האשה בעבור האיש׃ ");
INSERT INTO heb_vpl VALUES ("C111_10","076_11_10","1CO","11","10","10","על כן האשה חיבת להיות לה כפה על ראשה בעבור המלאכים׃ ");
INSERT INTO heb_vpl VALUES ("C111_11","076_11_11","1CO","11","11","11","אבל אין האיש בלא אשה ואין האשה בלא איש באדון׃ ");
INSERT INTO heb_vpl VALUES ("C111_12","076_11_12","1CO","11","12","12","כי כאשר האשה מן האיש כן גם האיש על ידי האשה וכל זאת מאלהים׃ ");
INSERT INTO heb_vpl VALUES ("C111_13","076_11_13","1CO","11","13","13","שפטו נא בנפשכם הנאוה לאשה להתפלל אל האלהים בגלוי ראש׃ ");
INSERT INTO heb_vpl VALUES ("C111_14","076_11_14","1CO","11","14","14","או הלא גם הטבע בעצמו ילמד אתכם כי איש אשר יגדל פרע שער ראשו חרפה היא לו׃ ");
INSERT INTO heb_vpl VALUES ("C111_15","076_11_15","1CO","11","15","15","אבל האשה כי תגדל שערה פאר הוא לה כי נתן לה השער לצניף׃ ");
INSERT INTO heb_vpl VALUES ("C111_16","076_11_16","1CO","11","16","16","ואם יחשב איש לערער עלינו אין לנו מנהג כזה ולא לקהלות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C111_17","076_11_17","1CO","11","17","17","והנה בצותי את זאת לא אוכל לשבח אתכם על אשר תקהלו יחד לא להועיל כי אם לרעה׃ ");
INSERT INTO heb_vpl VALUES ("C111_18","076_11_18","1CO","11","18","18","כי בראשונה שמעתי שיש מחלקות ביניכם כאשר תועדו בקהל ומקצתו אני מאמין׃ ");
INSERT INTO heb_vpl VALUES ("C111_19","076_11_19","1CO","11","19","19","כי אף צריכות כתות להיות ביניכם למען יודעו הנאמנים בכם׃ ");
INSERT INTO heb_vpl VALUES ("C111_20","076_11_20","1CO","11","20","20","ועתה כאשר תקהלו יחד אין זה לאכל סעודת האדון׃ ");
INSERT INTO heb_vpl VALUES ("C111_21","076_11_21","1CO","11","21","21","כי כל אחד מקדים לקחת סעודתו בעת האכילה וזה ירעב וזה ישתכר׃ ");
INSERT INTO heb_vpl VALUES ("C111_22","076_11_22","1CO","11","22","22","האין לכם בתים לאכל ולשתות בהם או התבוזו את קהל אלהים ותכלימו את אשר אין בידם מאומה מה אמר לכם העל זאת אשבח אתכם אינני משבח׃ ");
INSERT INTO heb_vpl VALUES ("C111_23","076_11_23","1CO","11","23","23","כי כה קבלתי אנכי מן האדון את אשר גם מסרתי לכם כי האדון ישוע בלילה ההוא אשר נמסר בו לקח את הלחם׃ ");
INSERT INTO heb_vpl VALUES ("C111_24","076_11_24","1CO","11","24","24","ויברך ויבצע ויאמר קחו אכלו זה גופי הנבצע בעדכם עשו זאת לזכרוני׃ ");
INSERT INTO heb_vpl VALUES ("C111_25","076_11_25","1CO","11","25","25","וכן גם את הכוס אחר הסעודה ויאמר הכוס הזאת היא הברית החדשה בדמי עשו זאת לזכרוני בכל עת שתשתו׃ ");
INSERT INTO heb_vpl VALUES ("C111_26","076_11_26","1CO","11","26","26","כי בכל עת שתאכלו את הלחם הזה ותשתו את הכוס הזאת הזכר תזכירו את מות אדנינו עד כי יבוא׃ ");
INSERT INTO heb_vpl VALUES ("C111_27","076_11_27","1CO","11","27","27","לכן מי שיאכל מן הלחם הזה או ישתה מכוס האדון שלא כראוי יאשם לגוף אדנינו ולדמו׃ ");
INSERT INTO heb_vpl VALUES ("C111_28","076_11_28","1CO","11","28","28","יבחן האיש את נפשו ואז יאכל מן הלחם וישתה מן הכוס׃ ");
INSERT INTO heb_vpl VALUES ("C111_29","076_11_29","1CO","11","29","29","כי האכל והשתה שלא כראוי אכל ושתה דין לנפשו יען אשר לא הפלה את גוף האדון׃ ");
INSERT INTO heb_vpl VALUES ("C111_30","076_11_30","1CO","11","30","30","בעבור זאת יש בכם חולים וחלשים רבים והרבה ישנו המות׃ ");
INSERT INTO heb_vpl VALUES ("C111_31","076_11_31","1CO","11","31","31","כי אם נבחן את נפשנו לא נהיה נדונים׃ ");
INSERT INTO heb_vpl VALUES ("C111_32","076_11_32","1CO","11","32","32","וכאשר נדון נוסר על יד האדון למען לא נחיב עם העולם׃ ");
INSERT INTO heb_vpl VALUES ("C111_33","076_11_33","1CO","11","33","33","על כן אחי בהקהלכם יחד לאכל תחכו איש אל רעהו׃ ");
INSERT INTO heb_vpl VALUES ("C111_34","076_11_34","1CO","11","34","34","וכי ירעב איש יאכל בביתו פן תקהלו לאשמה ויתר הדברים אתקן בבאי׃ ");
INSERT INTO heb_vpl VALUES ("C112_1","076_12_1","1CO","12","1","1","ובענין הרוחניות אחי לא אכחד מכם דבר׃ ");
INSERT INTO heb_vpl VALUES ("C112_2","076_12_2","1CO","12","2","2","הלא ידעתם כי בהיתכם גוים אחרי אלילים אלמים הובלתם כאשר נמשכתם׃ ");
INSERT INTO heb_vpl VALUES ("C112_3","076_12_3","1CO","12","3","3","לכן אודיע אתכם כי אין איש דבר ברוח אלהים אשר יאמר ישוע חרם הוא ולא יוכל איש לקרא לישוע אדון בלתי אם ברוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("C112_4","076_12_4","1CO","12","4","4","ושנות הנה המתנות אבל הרוח אחד הוא׃ ");
INSERT INTO heb_vpl VALUES ("C112_5","076_12_5","1CO","12","5","5","ושנים המה השמושים והאדון אחד הוא׃ ");
INSERT INTO heb_vpl VALUES ("C112_6","076_12_6","1CO","12","6","6","ושנות הנה הפעלות והאלהים הוא אחד הפעל את הכל בכל׃ ");
INSERT INTO heb_vpl VALUES ("C112_7","076_12_7","1CO","12","7","7","ולכל איש ואיש נתנה לו התגלות הרוח להועיל׃ ");
INSERT INTO heb_vpl VALUES ("C112_8","076_12_8","1CO","12","8","8","כי האחד נתן לו על ידי הרוח דבור החכמה ולאחד דבור הדעת כפי הרוח ההוא׃ ");
INSERT INTO heb_vpl VALUES ("C112_9","076_12_9","1CO","12","9","9","לאחר האמונה ברוח ההוא ולאחר מתנות הרפאות ברוח ההוא׃ ");
INSERT INTO heb_vpl VALUES ("C112_10","076_12_10","1CO","12","10","10","ולאחר לפעל גבורות ולאחר נבואה ולאחר להבחין בין הרוחות ולאחר מיני לשנות ולאחר באור לשנות׃ ");
INSERT INTO heb_vpl VALUES ("C112_11","076_12_11","1CO","12","11","11","וכל אלה פעל הרוח האחד ההוא המחלק לאיש איש כרצונו׃ ");
INSERT INTO heb_vpl VALUES ("C112_12","076_12_12","1CO","12","12","12","כי כאשר הגוף הוא אחד ויש בו אברים הרבה וכל אברי הגוף ההוא אף כי רבים הם כלם גוף אחד כן גם המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C112_13","076_12_13","1CO","12","13","13","כי ברוח אחד נטבלנו כלנו לגוף אחד אם יהודים אם יונים אם עבדים אם בני חורין וכלנו לרוח אחד השקינו׃ ");
INSERT INTO heb_vpl VALUES ("C112_14","076_12_14","1CO","12","14","14","כי גם הגוף לא אבר אחד הוא כי אם רבים׃ ");
INSERT INTO heb_vpl VALUES ("C112_15","076_12_15","1CO","12","15","15","אם תאמר הרגל אינני יד על כן אינני מן הגוף הבעבור זאת איננה מן הגוף׃ ");
INSERT INTO heb_vpl VALUES ("C112_16","076_12_16","1CO","12","16","16","ואם תאמרו האזן אינני עין על כן אינני מן הגוף הבעבור זאת איננה מן הגוף׃ ");
INSERT INTO heb_vpl VALUES ("C112_17","076_12_17","1CO","12","17","17","אם הגוף כלו יהיה עין איה השמע ואם כלו יהיה שמע איה הריח׃ ");
INSERT INTO heb_vpl VALUES ("C112_18","076_12_18","1CO","12","18","18","ועתה האלהים שת את האברים כל אחד ואחד מהם בגוף כמי רצונו׃ ");
INSERT INTO heb_vpl VALUES ("C112_19","076_12_19","1CO","12","19","19","ואלו היו כלם אבר אחד איה הגוף׃ ");
INSERT INTO heb_vpl VALUES ("C112_20","076_12_20","1CO","12","20","20","הנה רבים הם האברים והגוף אחד׃ ");
INSERT INTO heb_vpl VALUES ("C112_21","076_12_21","1CO","12","21","21","העין לא תוכל דבר אל היד לאמר לא אצטרך לך וגם הראש לא יוכל דבר אל הרגלים לאמר לא אצטרך לכן׃ ");
INSERT INTO heb_vpl VALUES ("C112_22","076_12_22","1CO","12","22","22","כי להפך אברי הגוף הנראים רפים הם לנו לצרך ביותר׃ ");
INSERT INTO heb_vpl VALUES ("C112_23","076_12_23","1CO","12","23","23","והנראים לנו נקלים בגוף אתם נלביש ביתר כבוד ואשר לבשת לנו המה כאלו ההגונים מכלם׃ ");
INSERT INTO heb_vpl VALUES ("C112_24","076_12_24","1CO","12","24","24","כי ההגונים לנו אינם צריכים לזאת אבל האלהים מזג ככה את הגוף שנתן כבוד יותר לגרוע׃ ");
INSERT INTO heb_vpl VALUES ("C112_25","076_12_25","1CO","12","25","25","למען לא תהיה מחלקת בגוף כי אם ידאגו כל האברים יחד זה לזה׃ ");
INSERT INTO heb_vpl VALUES ("C112_26","076_12_26","1CO","12","26","26","ואם יכאב אבר אחד יכאבו אתו כל האברים ואם יכבד אבד אחד ישמחו אתו כל האברים׃ ");
INSERT INTO heb_vpl VALUES ("C112_27","076_12_27","1CO","12","27","27","אכן גוף המשיח אתם ואבריו כל אחד לפי חלקו׃ ");
INSERT INTO heb_vpl VALUES ("C112_28","076_12_28","1CO","12","28","28","ומהם שם האלהים בקהל ראשונה לשליחים ושנית לנביאים ושלישית למלמדים ויתן גבורות אף מתנות הרפאות ועזרים ומנהיגים ומיני לשנות׃ ");
INSERT INTO heb_vpl VALUES ("C112_29","076_12_29","1CO","12","29","29","הכלם שליחים אם כלם נביאים או כלם מלמדים הכלם עשי גבורות׃ ");
INSERT INTO heb_vpl VALUES ("C112_30","076_12_30","1CO","12","30","30","הלכלם מתנות רפאות הכלם מדברים בלשנות הכלם מפרשי לשנות׃ ");
INSERT INTO heb_vpl VALUES ("C112_31","076_12_31","1CO","12","31","31","ואתם התאוו המתנות המועילות ביותר ובכל זאת אראה אתכם דרך נעלה על כלנה׃ ");
INSERT INTO heb_vpl VALUES ("C113_1","076_13_1","1CO","13","1","1","אם בלשנות אנשים ומלאכים אדבר ואין בי האהבה הייתי כנחשת המה או כצלצל תרועה׃ ");
INSERT INTO heb_vpl VALUES ("C113_2","076_13_2","1CO","13","2","2","וכי תהיה לי נבואה ואדע כל הסודות וכל הדעת וכי תהיה לי כל האמונה עד כי אעתיק הרים ואין בי האהבה הייתי כאין׃ ");
INSERT INTO heb_vpl VALUES ("C113_3","076_13_3","1CO","13","3","3","ואם אחלק את כל הוני ואם אתן את גופי לשרפה ואין בי האהבה כל זאת לא תועילני׃ ");
INSERT INTO heb_vpl VALUES ("C113_4","076_13_4","1CO","13","4","4","האהבה מארכת אף ועשה חסד האהבה לא תקנא האהבה לא תתפאר ולא תתרומם׃ ");
INSERT INTO heb_vpl VALUES ("C113_5","076_13_5","1CO","13","5","5","לא תעשה דבר תפלה ולא תבקש את אשר לה ולא תתמרמר ולא תחשב הרעה׃ ");
INSERT INTO heb_vpl VALUES ("C113_6","076_13_6","1CO","13","6","6","לא תשמח בעולה כי שמחתה עם האמת׃ ");
INSERT INTO heb_vpl VALUES ("C113_7","076_13_7","1CO","13","7","7","את כל תשא את כל תאמין את כל תקוה ואת כל תסבל׃ ");
INSERT INTO heb_vpl VALUES ("C113_8","076_13_8","1CO","13","8","8","האהבה לא תבל לעולם אך הנבואות הנה תבטלנה והלשנות תכלינה והדעת תבטל׃ ");
INSERT INTO heb_vpl VALUES ("C113_9","076_13_9","1CO","13","9","9","כי קצת הוא שידענו וקצת הוא שנבאנו׃ ");
INSERT INTO heb_vpl VALUES ("C113_10","076_13_10","1CO","13","10","10","וכבוא התמים אז עבור תעבר הקצת׃ ");
INSERT INTO heb_vpl VALUES ("C113_11","076_13_11","1CO","13","11","11","כאשר הייתי עולל כעולל דברתי כעולל הגיתי כעולל חשבתי וכאשר הייתי לאיש הסירתי דברי העולל׃ ");
INSERT INTO heb_vpl VALUES ("C113_12","076_13_12","1CO","13","12","12","כי כעת מביטים אנחנו במראה ובחידות ואז פנים אל פנים כעת יודע אני קצתו ואז כאשר נודעתי אדע אף אני׃ ");
INSERT INTO heb_vpl VALUES ("C113_13","076_13_13","1CO","13","13","13","ועתה שלש אלה תעמדנה האמונה והתקוה והאהבה והגדולה בהן היא האהבה׃ ");
INSERT INTO heb_vpl VALUES ("C114_1","076_14_1","1CO","14","1","1","רדפו אחרי האהבה והתאוו מתנות הרוח וביותר אשר תתנבאו׃ ");
INSERT INTO heb_vpl VALUES ("C114_2","076_14_2","1CO","14","2","2","כי המדבר בלשון איננו מדבר לאדם כי אם לאלהים כי אין איש אשר ישמעהו רק ברוח הוא מדבר סודות׃ ");
INSERT INTO heb_vpl VALUES ("C114_3","076_14_3","1CO","14","3","3","והמתנבא הוא מדבר לבני אדם לבנותם וליסרם ולנחמם׃ ");
INSERT INTO heb_vpl VALUES ("C114_4","076_14_4","1CO","14","4","4","המדבר בלשון בונה את נפשו והמתנבא בונה את העדה׃ ");
INSERT INTO heb_vpl VALUES ("C114_5","076_14_5","1CO","14","5","5","וחפצתי כי תדברו כלכם בלשנות וביותר כי תתנבאו כי גדול המתנבא מן המדבר בלשנות בלתי אם יפרש למען תבנה העדה׃ ");
INSERT INTO heb_vpl VALUES ("C114_6","076_14_6","1CO","14","6","6","ועתה אחי כי אבוא אליכם ואדבר בלשנות מה אועיל לכם אם לא אדבר אליכם בחזון או בדעת או בנבואה או בהוראה׃ ");
INSERT INTO heb_vpl VALUES ("C114_7","076_14_7","1CO","14","7","7","הלא גם הכלים הדוממים הנתנים קול הן חליל הן כנור אם לא ישמיעו קלות אשר תוכל האזן להבחין איכה יודע מה יזמר ומה ינגן׃ ");
INSERT INTO heb_vpl VALUES ("C114_8","076_14_8","1CO","14","8","8","גם השופר אם יתן את קולו בלתי ברור מי יחלץ למלחמה׃ ");
INSERT INTO heb_vpl VALUES ("C114_9","076_14_9","1CO","14","9","9","כן גם אתם אם לא תוציאו בלשונכם דבור מפרש איכה יודע האמור הלא תהיו כמדברים לרוח׃ ");
INSERT INTO heb_vpl VALUES ("C114_10","076_14_10","1CO","14","10","10","הן כמה מיני לשנות יש בעולם ואין אחת מהן בלי קול׃ ");
INSERT INTO heb_vpl VALUES ("C114_11","076_14_11","1CO","14","11","11","לכן אם אינני ידע פשר הקול אהיה נכרי בעיני המדבר והמדבר יהיה נכרי בעיני׃ ");
INSERT INTO heb_vpl VALUES ("C114_12","076_14_12","1CO","14","12","12","כן גם אתם בהיותכם מתאוים לכחות רוחניות בקשו להעדיף במה שיבנה את העדה׃ ");
INSERT INTO heb_vpl VALUES ("C114_13","076_14_13","1CO","14","13","13","על כן יתפלל המדבר בלשון וגם יפרשנה׃ ");
INSERT INTO heb_vpl VALUES ("C114_14","076_14_14","1CO","14","14","14","כי אם אתפלל בלשון רוחי מתפלל ושכלי איננו עשה פרי׃ ");
INSERT INTO heb_vpl VALUES ("C114_15","076_14_15","1CO","14","15","15","ועתה מה לעשות אתפללה ברוחי ואתפללה גם בשכלי אזמרה ברוחי ואזמרה גם בשכלי׃ ");
INSERT INTO heb_vpl VALUES ("C114_16","076_14_16","1CO","14","16","16","כי אם תברך ברוח איך יענה העמד נמצב ההדיוט אמן על הודיתך באשר לא ידע מה אתה אמר׃ ");
INSERT INTO heb_vpl VALUES ("C114_17","076_14_17","1CO","14","17","17","הן אתה תיטיב להודות אבל רעך לא יבנה׃ ");
INSERT INTO heb_vpl VALUES ("C114_18","076_14_18","1CO","14","18","18","אודה לאלהי כי יותר מכלכם אני מדבר בלשנות׃ ");
INSERT INTO heb_vpl VALUES ("C114_19","076_14_19","1CO","14","19","19","אכן בקהל אבחר לדבר חמש מלין בשכלי למען הורת גם את האחרים מלדבר רבבות מלין בלשון׃ ");
INSERT INTO heb_vpl VALUES ("C114_20","076_14_20","1CO","14","20","20","אחי אל תהיו ילדים בבינה רק לרע היו עללים ובבינה היו שלמים׃ ");
INSERT INTO heb_vpl VALUES ("C114_21","076_14_21","1CO","14","21","21","הן כתוב בתורה כי בלעגי שפה ובלשון אחרת אדבר אל העם הזה וגם בזאת לא אבו שמע לי אמר יהוה׃ ");
INSERT INTO heb_vpl VALUES ("C114_22","076_14_22","1CO","14","22","22","לכן הלשנות לא למאמינים הנה לאות כי אם לאשר אינם מאמינים אבל הנבואה איננה לאשר אינם מאמינים כי אם למאמינים׃ ");
INSERT INTO heb_vpl VALUES ("C114_23","076_14_23","1CO","14","23","23","והנה אם תקהל כל העדה יחד וכלם ידברו בלשנות ויבואו הדיוטים או אשר אינם מאמינים הלא יאמרו כי משגעים אתם׃ ");
INSERT INTO heb_vpl VALUES ("C114_24","076_14_24","1CO","14","24","24","אבל אם יתנבאו כלם ובא איש לא מאמין או הדיוט אז יוכח על ידי כלם וידון על ידי כלם׃ ");
INSERT INTO heb_vpl VALUES ("C114_25","076_14_25","1CO","14","25","25","ובכן יגלו תעלמות לבבו ויפל על פניו וישתחוה לאלהים ויודה בקול כי באמת האלהים בקרבכם׃ ");
INSERT INTO heb_vpl VALUES ("C114_26","076_14_26","1CO","14","26","26","ועתה מה לעשות אחי בהקהלכם יחד כל אחד ואחד מכם יש לו מזמור יש לו הוראה יש לו לשון יש לו חזון יש לו באור אך יעשה הכל להבנות׃ ");
INSERT INTO heb_vpl VALUES ("C114_27","076_14_27","1CO","14","27","27","כי ידבר איש בלשון ידברו נא שנים שנים או על היותר שלשה וזה אחר זה ואחד יפרש׃ ");
INSERT INTO heb_vpl VALUES ("C114_28","076_14_28","1CO","14","28","28","ואם אין מפרש אז ידם בקהל וידבר לנפשו ולאלהים׃ ");
INSERT INTO heb_vpl VALUES ("C114_29","076_14_29","1CO","14","29","29","והנביאים הם ידברו שנים או שלשה והאחרים יבחנו׃ ");
INSERT INTO heb_vpl VALUES ("C114_30","076_14_30","1CO","14","30","30","וכי נגלה חזון לאחר הישב שם אז ידם הראשון׃ ");
INSERT INTO heb_vpl VALUES ("C114_31","076_14_31","1CO","14","31","31","כי תוכלו להתנבא כלכם זה אחר זה למען ילמדו כלם וכלם יזהרו׃ ");
INSERT INTO heb_vpl VALUES ("C114_32","076_14_32","1CO","14","32","32","ורוחות הנביאים תחת ידי הנביאים המה׃ ");
INSERT INTO heb_vpl VALUES ("C114_33","076_14_33","1CO","14","33","33","כי לא אלהי מבוכה האלהים כי אם אלהי השלום כאשר בכל קהלות הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("C114_34","076_14_34","1CO","14","34","34","נשיכם בכנסיות תשתקנה כי לא נתנה להן רשות לדבר כי אם להכנע כאשר גם אמרה התורה׃ ");
INSERT INTO heb_vpl VALUES ("C114_35","076_14_35","1CO","14","35","35","ואם חפצן ללמד דבר תשאלנה את בעליהן בבית כי חרפה היא לנשים לדבר בקהל׃ ");
INSERT INTO heb_vpl VALUES ("C114_36","076_14_36","1CO","14","36","36","או המכם יצא דבר אלהים אם אליכם לבדכם הגיע׃ ");
INSERT INTO heb_vpl VALUES ("C114_37","076_14_37","1CO","14","37","37","כי יתברך איש בלבבו להיות נביא או איש הרוח בין יבין את אשר אני כתב לכם כי מצות האדון הנה׃ ");
INSERT INTO heb_vpl VALUES ("C114_38","076_14_38","1CO","14","38","38","ומי אשר לא ידע אל ידע׃ ");
INSERT INTO heb_vpl VALUES ("C114_39","076_14_39","1CO","14","39","39","לכן אחי השתדלו להתנבא ואל תכלאו מלדבר בלשנות׃ ");
INSERT INTO heb_vpl VALUES ("C114_40","076_14_40","1CO","14","40","40","הכל יעשה כהגן וכשורה׃ ");
INSERT INTO heb_vpl VALUES ("C115_1","076_15_1","1CO","15","1","1","ואני אחי אודיעכם את הבשורה אשר בשרתי אתכם אשר גם קבלתם אתה וגם עמדתם בה׃ ");
INSERT INTO heb_vpl VALUES ("C115_2","076_15_2","1CO","15","2","2","אשר גם תושעו בה אם תחזיקו בדבר אשר בשרתי אתכם אך אם לא לשוא האמנתם׃ ");
INSERT INTO heb_vpl VALUES ("C115_3","076_15_3","1CO","15","3","3","כי מסרתי לכם בראשונה את אשר גם קבלתי כי המשיח מת בעד חטאתינו כפי הכתובים׃ ");
INSERT INTO heb_vpl VALUES ("C115_4","076_15_4","1CO","15","4","4","וכי נקבר וכי הוקם ביום השלישי כפי הכתובים׃ ");
INSERT INTO heb_vpl VALUES ("C115_5","076_15_5","1CO","15","5","5","וכי נראה אל כיפא ואחריו אל שנים העשר׃ ");
INSERT INTO heb_vpl VALUES ("C115_6","076_15_6","1CO","15","6","6","ואחרי כן נראה ליותר מחמש מאות אחים כאחד אשר רבם עודם בחיים ומקצתם ישנו׃ ");
INSERT INTO heb_vpl VALUES ("C115_7","076_15_7","1CO","15","7","7","ואחרי כן נראה אל יעקב ואחריו אל כל השליחים׃ ");
INSERT INTO heb_vpl VALUES ("C115_8","076_15_8","1CO","15","8","8","ואחרי כלם נראה גם אלי כמו אל הנפל׃ ");
INSERT INTO heb_vpl VALUES ("C115_9","076_15_9","1CO","15","9","9","כי אני הצעיר בשליחים ואינני כדי להקרא שליח באשר רדפתי את קהל האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C115_10","076_15_10","1CO","15","10","10","אבל בחסד אלהים הייתי מה שהייתי וחסדו עלי לא היה לריק כי יותר מכלם עבדתי ולא אני כי אם חסד אלהים אשר עמדי׃ ");
INSERT INTO heb_vpl VALUES ("C115_11","076_15_11","1CO","15","11","11","והנה גם אני גם המה ככה משמיעים וככה האמנתם׃ ");
INSERT INTO heb_vpl VALUES ("C115_12","076_15_12","1CO","15","12","12","ואם הגד הגד כי הוקם המשיח מן המתים איך יאמרו אנשים מכם כי אין תחיה למתים׃ ");
INSERT INTO heb_vpl VALUES ("C115_13","076_15_13","1CO","15","13","13","אם אין תחיה למתים גם המשיח לא הוקם׃ ");
INSERT INTO heb_vpl VALUES ("C115_14","076_15_14","1CO","15","14","14","ואם המשיח לא הוקם כי עתה ריק שמועתנו וגם ריק אמונתכם׃ ");
INSERT INTO heb_vpl VALUES ("C115_15","076_15_15","1CO","15","15","15","וגם נמצא עדי שקר לאלהים יען אשר העידנו את האלהים כי הקים את המשיח אשר לא הקימו אם אמת הוא שהמתים לא יקומו׃ ");
INSERT INTO heb_vpl VALUES ("C115_16","076_15_16","1CO","15","16","16","כי אם המתים לא יקומו גם המשיח לא קם׃ ");
INSERT INTO heb_vpl VALUES ("C115_17","076_15_17","1CO","15","17","17","ואם המשיח לא קם הבל אמונתכם ועודכם בחטאתיכם׃ ");
INSERT INTO heb_vpl VALUES ("C115_18","076_15_18","1CO","15","18","18","אזי גם אשר ישנו במשיח אבד אבדו׃ ");
INSERT INTO heb_vpl VALUES ("C115_19","076_15_19","1CO","15","19","19","ואם בחיים האלה לבד בטחים אנחנו במשיח אמללים אנחנו מכל אדם׃ ");
INSERT INTO heb_vpl VALUES ("C115_20","076_15_20","1CO","15","20","20","ועתה המשיח הוקם מן המתים ויהי לראשית הישנים׃ ");
INSERT INTO heb_vpl VALUES ("C115_21","076_15_21","1CO","15","21","21","כי אחרי אשר בא המות על ידי אדם אחד גם תחית המתים באה על ידי אדם אחד׃ ");
INSERT INTO heb_vpl VALUES ("C115_22","076_15_22","1CO","15","22","22","כי כאשר באדם מתים כלם כן גם יחיו כלם במשיח׃ ");
INSERT INTO heb_vpl VALUES ("C115_23","076_15_23","1CO","15","23","23","וכל אחד ואחד בסדרו ראשית כלם המשיח ואחרי כן אשר הם למשיח בבואו׃ ");
INSERT INTO heb_vpl VALUES ("C115_24","076_15_24","1CO","15","24","24","ואחרי כן הקץ כשימסר את המלכות אל האלהים האב אחרי בטלו כל משרה וכל שלטן וגבורה׃ ");
INSERT INTO heb_vpl VALUES ("C115_25","076_15_25","1CO","15","25","25","כי הוא מלך ימלך עד כי ישית את כל איביו תחת רגליו׃ ");
INSERT INTO heb_vpl VALUES ("C115_26","076_15_26","1CO","15","26","26","ואחרון האיבים אשר יבטל הוא המות׃ ");
INSERT INTO heb_vpl VALUES ("C115_27","076_15_27","1CO","15","27","27","כי כל שת תחת רגליו ובאמרו כל הושת תחתיו ברור הוא שהשת כל תחתיו איננו בכלל׃ ");
INSERT INTO heb_vpl VALUES ("C115_28","076_15_28","1CO","15","28","28","וכאשר יושת הכל תחתיו אז הבן גם הוא יושת תחת השת כל תחתיו למען יהיה האלהים הכל בכל׃ ");
INSERT INTO heb_vpl VALUES ("C115_29","076_15_29","1CO","15","29","29","כי מה יעשו הנטבלים בעד המתים אם אמת הוא שהמתים קום לא יקומו למה זה יטבלו בעד המתים׃ ");
INSERT INTO heb_vpl VALUES ("C115_30","076_15_30","1CO","15","30","30","ולמה זה אנחנו בסכנה בכל שעה׃ ");
INSERT INTO heb_vpl VALUES ("C115_31","076_15_31","1CO","15","31","31","בתהלתנו אשר יש לי במשיח ישוע אדנינו מעיד אני עלי כי מת אנכי בכל יום ויום׃ ");
INSERT INTO heb_vpl VALUES ("C115_32","076_15_32","1CO","15","32","32","אם לפי ררכו של אדם נלחמתי עם החיות הרעות באפסוס מה תועלת יש לי אם המתים לא יקומו נאכלה ונשתה כי מחר נמות׃ ");
INSERT INTO heb_vpl VALUES ("C115_33","076_15_33","1CO","15","33","33","אל נא תתעו חברת אנשים רעים משחתת מדות טבות׃ ");
INSERT INTO heb_vpl VALUES ("C115_34","076_15_34","1CO","15","34","34","הקיצו במישרים משכרון ואל תחטאו כי יש אנשים אשר אין בהם דעת אלהים לבשתכם אני אמר זאת׃ ");
INSERT INTO heb_vpl VALUES ("C115_35","076_15_35","1CO","15","35","35","ואם יאמר איש איך יקומו המתים ובאי זה גוף יבואו׃ ");
INSERT INTO heb_vpl VALUES ("C115_36","076_15_36","1CO","15","36","36","אתה הסכל הן מה שתזרע לא יחיה בלתי אם ימות׃ ");
INSERT INTO heb_vpl VALUES ("C115_37","076_15_37","1CO","15","37","37","ומה שתזרע אינך זרע את הגוף אשר יהיה כי אם כגרגר ערם של חטה או של אחד הזרעים׃ ");
INSERT INTO heb_vpl VALUES ("C115_38","076_15_38","1CO","15","38","38","והאלהים יתן לו גוף כפי רצונו ולכל זרע וזרע את גופו למינהו׃ ");
INSERT INTO heb_vpl VALUES ("C115_39","076_15_39","1CO","15","39","39","לא כל הבשר באשר אחד הוא כי מין אחר הוא בשר האדם ומין אחר בשר הבהמה ומין אחר בשר הדגה ומין אחר בשר העוף׃ ");
INSERT INTO heb_vpl VALUES ("C115_40","076_15_40","1CO","15","40","40","ויש גופות שבשמים וגופות שבארץ אבל אחר הוא כבוד הגופות שבשמים וגופות שבארץ אבל אחר הוא כבוד הגופות שבשמים ואחר הוא כבוד הגופות שבארץ׃ ");
INSERT INTO heb_vpl VALUES ("C115_41","076_15_41","1CO","15","41","41","אחר הוא כבוד השמש ואחר הוא כבוד הירח ואחר הוא כבוד הכוכבים כי כוכב מכוכב נבדל בכבודו׃ ");
INSERT INTO heb_vpl VALUES ("C115_42","076_15_42","1CO","15","42","42","וכן גם בתחיה המתים הן יזרע בכליון ויקום בלא כליון׃ ");
INSERT INTO heb_vpl VALUES ("C115_43","076_15_43","1CO","15","43","43","יזרע בבזיון ויקום בכבוד יזרע בחלשה ויקום בגבורה׃ ");
INSERT INTO heb_vpl VALUES ("C115_44","076_15_44","1CO","15","44","44","יזרע גוף נפשי ויקום גוף רוחני יש גוף נפשי ויש גוף רוחני׃ ");
INSERT INTO heb_vpl VALUES ("C115_45","076_15_45","1CO","15","45","45","כן גם כתוב ויהי האדם הוא אדם הראשון לנפש חיה אדם האחרון לרוח מחיה׃ ");
INSERT INTO heb_vpl VALUES ("C115_46","076_15_46","1CO","15","46","46","אבל לא של הרוח היא הראשונה אלא של הנפש ואחרי כן של הרוח׃ ");
INSERT INTO heb_vpl VALUES ("C115_47","076_15_47","1CO","15","47","47","האדם הראשון מן האדמה הוא של עפר והאדם השני הוא האדון מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("C115_48","076_15_48","1CO","15","48","48","וכמו אשר הוא מעפר ככה גם אשר הם מעפר וכמו אשר הוא מן השמים ככה גם אשר הם מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("C115_49","076_15_49","1CO","15","49","49","וכאשר לבשנו דמות האדם אשר מעפר כן נלבש גם דמות האדם אשר מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("C115_50","076_15_50","1CO","15","50","50","וזאת אני אמר אחי כי בשר ודם לא יוכל לרשת את מלכות האלהים ואשר יכלה לא יירש את אשר לא יכלה׃ ");
INSERT INTO heb_vpl VALUES ("C115_51","076_15_51","1CO","15","51","51","הנה סוד אגידה לכם הן לא כלנו נישן המות אבל כלנו נתחלף׃ ");
INSERT INTO heb_vpl VALUES ("C115_52","076_15_52","1CO","15","52","52","ברגע אחד כהרף עין כתקע השופר האחרון כי יתקע בשופר והמתים יחיו בלי כליון ואנחנו נתחלף׃ ");
INSERT INTO heb_vpl VALUES ("C115_53","076_15_53","1CO","15","53","53","כי מה שעתה לכליון לבוש ילבש אל כליון ואמר ימות יבוש ילבש אל מות׃ ");
INSERT INTO heb_vpl VALUES ("C115_54","076_15_54","1CO","15","54","54","וכשילבש מה שעתה לכליון אל כליון ומה שעתה למות ילבש אל מות אז יהיה דבר הכתוב בלע המות לנצח׃ ");
INSERT INTO heb_vpl VALUES ("C115_55","076_15_55","1CO","15","55","55","איה עקצף המות איה שאול בצחונך׃ ");
INSERT INTO heb_vpl VALUES ("C115_56","076_15_56","1CO","15","56","56","עקץ המות הוא החטא וכח החטא היא התורה׃ ");
INSERT INTO heb_vpl VALUES ("C115_57","076_15_57","1CO","15","57","57","אבל תודות לאלהים אשר נתן לנו הנצחון על ידי אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C115_58","076_15_58","1CO","15","58","58","על כן אחי חביבי התכוננו בל תמוטו והעדיפו בכל עת במעשה אדנינו מדעתכם כי לא לריק עמלכם באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("C116_1","076_16_1","1CO","16","1","1","ועל דבר קבוץ התרומות לעזרת הקדושים כאשר תקנתי לקהלות אשר בגלטיא כן תעשו גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("C116_2","076_16_2","1CO","16","2","2","בכל אחד בשבת יניח אצלו איש איש מכם ויאצר את אשר עלה בידו למען אשר בבאי לא יקבץ עוד׃ ");
INSERT INTO heb_vpl VALUES ("C116_3","076_16_3","1CO","16","3","3","ואני בבאי את אשר תמצאו נאמנים עם אגרות אשלח אתם להביא את נדבתכם לירושלים׃ ");
INSERT INTO heb_vpl VALUES ("C116_4","076_16_4","1CO","16","4","4","ואם שוה הטרח שגם אנכי אלך שמה אתי ילכו׃ ");
INSERT INTO heb_vpl VALUES ("C116_5","076_16_5","1CO","16","5","5","ואני אבא אליכם אחרי עברי את מקדוניא כי את מקדוניא אעברה׃ ");
INSERT INTO heb_vpl VALUES ("C116_6","076_16_6","1CO","16","6","6","ואולי אשב עמכם ימים אחדים או כל ימי הסתו למען תלוני אל אשר אלך שמה׃ ");
INSERT INTO heb_vpl VALUES ("C116_7","076_16_7","1CO","16","7","7","כי כעת אין רצוני לראתכם אך בעברי כי אקוה לשבת אצלכם זמן מה אם ירצה יהוה׃ ");
INSERT INTO heb_vpl VALUES ("C116_8","076_16_8","1CO","16","8","8","אבל אשב באפסוס עד חג השבועות׃ ");
INSERT INTO heb_vpl VALUES ("C116_9","076_16_9","1CO","16","9","9","כי נפתח לי פתח גדול ורב פעלים ורבים המתקוממים׃ ");
INSERT INTO heb_vpl VALUES ("C116_10","076_16_10","1CO","16","10","10","וכי יבוא אליכם טימותיוס ראו נא שיהיה עמכם בלי פחד כי מלאכת יהוה הוא עשה כמו גם אני׃ ");
INSERT INTO heb_vpl VALUES ("C116_11","076_16_11","1CO","16","11","11","על כן איש אל יבז אתו אך שלחהו בשלום למען יבא אלי כי אחכה לו עם האחים׃ ");
INSERT INTO heb_vpl VALUES ("C116_12","076_16_12","1CO","16","12","12","ואפולוס האח הנה פצרתי בו לבוא אליכם עם האחים אך לא היה ברצונו לבוא עתה אמנם בוא יבוא במצאו עת נכונה׃ ");
INSERT INTO heb_vpl VALUES ("C116_13","076_16_13","1CO","16","13","13","שקדו ועמדו באמונה התאששו והתחזקו׃ ");
INSERT INTO heb_vpl VALUES ("C116_14","076_16_14","1CO","16","14","14","וכל דבריכם יעשו באהבה׃ ");
INSERT INTO heb_vpl VALUES ("C116_15","076_16_15","1CO","16","15","15","ואבקשה מכם אחי הלא ידעתם את בית אסטפנוס שהוא ראשית אכיא ויתנו את נפשם לשרות הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("C116_16","076_16_16","1CO","16","16","16","לכן הכנעו גם אתם מפני אנשים כאלה ומפני כל אשר יעבד עמהם ויעמלו׃ ");
INSERT INTO heb_vpl VALUES ("C116_17","076_16_17","1CO","16","17","17","והנני שמח בביאת אסטפנוס ופרטונטוס ואכיקוס כי המה מלאו את אשר חסרתי אתכם׃ ");
INSERT INTO heb_vpl VALUES ("C116_18","076_16_18","1CO","16","18","18","ויניחו את רוחי ואת רוחכם על כן הכירו אנשים כאלה׃ ");
INSERT INTO heb_vpl VALUES ("C116_19","076_16_19","1CO","16","19","19","הקהלות אשר באסיא שאלות לשלומכם עקילס ופריסקלא וגם הקהלה אשר בביתם מרבים לשאל לשלומכם באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("C116_20","076_16_20","1CO","16","20","20","האחים כלם שאלים לשלומכם שאלו לשלום איש את רעהו בנשקה הקדושה׃ ");
INSERT INTO heb_vpl VALUES ("C116_21","076_16_21","1CO","16","21","21","שאלת שלומכם בידי אני פולוס׃ ");
INSERT INTO heb_vpl VALUES ("C116_22","076_16_22","1CO","16","22","22","מי שלא יאהב את האדון ישוע המשיח יחרם מרן אתא׃ ");
INSERT INTO heb_vpl VALUES ("C116_23","076_16_23","1CO","16","23","23","חסד ישוע המשיח אדנינו יהי עמכם׃ ");
INSERT INTO heb_vpl VALUES ("C116_24","076_16_24","1CO","16","24","24","ואהבתי את כלכם במשיח ישוע אמן׃ ");
INSERT INTO heb_vpl VALUES ("C21_1","077_1_1","2CO","1","1","1","פולוס שליח ישוע המשיח ברצון אלהים וטימותיוס אחינו אל קהלת אלהים אשר בקורנתוס עם כל הקדשים אשר באכיא׃ ");
INSERT INTO heb_vpl VALUES ("C21_2","077_1_2","2CO","1","2","2","חסד לכם ושלום מאת האלהים אבינו ואדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C21_3","077_1_3","2CO","1","3","3","ברוך האלהים ואבי אדנינו ישוע המשיח אב הרחמים ואלהי כל הנחמה׃ ");
INSERT INTO heb_vpl VALUES ("C21_4","077_1_4","2CO","1","4","4","המנחם אתנו בכל לחצנו עד שנוכל לנחם הנלחצים בכל לחץ בנחמה אשר אנחנו מנחמים בה מאת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C21_5","077_1_5","2CO","1","5","5","כי כרב ענויי המשיח בנו כן תרבה נחמתנו על ידי המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C21_6","077_1_6","2CO","1","6","6","והנה אם נלחץ הוא לנחמתכם ולישועתכם אשר יראה כחה בסבלכם הענוים אשר נסבל אתן גם אנחנו ואם ננחם גם הוא לנחמתכם ולישועתכם׃ ");
INSERT INTO heb_vpl VALUES ("C21_7","077_1_7","2CO","1","7","7","ותקותנו בעדכם נכונה היא באשר ידענו כי כאשר חלק לכם בענוים כן גם חלק לכם בנחמה׃ ");
INSERT INTO heb_vpl VALUES ("C21_8","077_1_8","2CO","1","8","8","כי לא נכחד מכם אחי את צרתנו אשר מצאתנו באסיא אשר כבדה עלינו עד למאד ויותר מכחנו עד כי נואשנו מן החיים׃ ");
INSERT INTO heb_vpl VALUES ("C21_9","077_1_9","2CO","1","9","9","ואנחנו בלבבנו חרצנו לנו את המות למען לא נהיה בטחים בנפשנו כי אם באלהים המחיה את המתים׃ ");
INSERT INTO heb_vpl VALUES ("C21_10","077_1_10","2CO","1","10","10","אשר הצילנו ממות כזה ועודנו מציל ולו אנחנו מקוים כי יוסיף להצילנו׃ ");
INSERT INTO heb_vpl VALUES ("C21_11","077_1_11","2CO","1","11","11","בעזרכם אתנו בתפלתכם למען יודו רבים בעדנו על מתנת החסד שהיתה לנו על ידי רבים׃ ");
INSERT INTO heb_vpl VALUES ("C21_12","077_1_12","2CO","1","12","12","כי זאת היא תהלתנו עדות לבבנו אשר בתם וישר אלהים התהלכנו בעולם וביותר אתכם ולא בחכמת הבשר כי אם בחסד אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C21_13","077_1_13","2CO","1","13","13","כי לא נכתב לכם כי אם מה שאתם קראים או גם ידעים׃ ");
INSERT INTO heb_vpl VALUES ("C21_14","077_1_14","2CO","1","14","14","ואקוה כי כאשר ידעתם אתנו למקצת אף תדעו עד תכלית כי אנחנו תהלתכם כאשר גם אתם תהלתנו ביום אדנינו ישוע׃ ");
INSERT INTO heb_vpl VALUES ("C21_15","077_1_15","2CO","1","15","15","ובבטחון הזה חפצתי לבוא אליכם מראש למען תקבלו טובה פעמים׃ ");
INSERT INTO heb_vpl VALUES ("C21_16","077_1_16","2CO","1","16","16","ולעבר בתוככם אל מקדוניא ולשוב ממקדוניא אליכם ואתם תשלחוני אל ארץ יהודה׃ ");
INSERT INTO heb_vpl VALUES ("C21_17","077_1_17","2CO","1","17","17","ועתה הכי נמהר הייתי בעצתי אם אשר יעצתי לפי הבשר יעצתי והיה אצלי פעם הן הן ופעם לא לא׃ ");
INSERT INTO heb_vpl VALUES ("C21_18","077_1_18","2CO","1","18","18","אכן נאמן האלהים כי דברנו אליכם לא היה הן ולא׃ ");
INSERT INTO heb_vpl VALUES ("C21_19","077_1_19","2CO","1","19","19","כי בן האלהים ישוע המשיח הנקרא בתוככם על ידינו על ידי ועל ידי סלונוס וטימותיוס הוא לא היה הן ולא כי היו היה בו רק הן׃ ");
INSERT INTO heb_vpl VALUES ("C21_20","077_1_20","2CO","1","20","20","כי כל הבטחות האלהים כלן בו היו הן ובו היו אמן לכבוד האלהים על ידינו׃ ");
INSERT INTO heb_vpl VALUES ("C21_21","077_1_21","2CO","1","21","21","והמכונן אותנו אתכם במשיח ואשר משחנו הוא האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C21_22","077_1_22","2CO","1","22","22","אשר גם חתמנו ואשר נתן בלבנו את ערבון הרוח׃ ");
INSERT INTO heb_vpl VALUES ("C21_23","077_1_23","2CO","1","23","23","ואני את אלהים אקרא להיות עד לנפשי כי בעבור היותי חס עליכם לא באתי עוד לקורנתוס׃ ");
INSERT INTO heb_vpl VALUES ("C21_24","077_1_24","2CO","1","24","24","לא שנמשל באמונתכם כי אם עזרים אנחנו לשמחתכם כי באמונה עמדתם׃ ");
INSERT INTO heb_vpl VALUES ("C22_1","077_2_1","2CO","2","1","1","ואני גמרתי בלבי לבלתי שוב עוד אליכם בעצבת׃ ");
INSERT INTO heb_vpl VALUES ("C22_2","077_2_2","2CO","2","2","2","כי אם אני אעציבכם מי אפוא ישמחני בלתי אם הנעצב על ידי׃ ");
INSERT INTO heb_vpl VALUES ("C22_3","077_2_3","2CO","2","3","3","וזאת כתבתי לכם פן יהיה לי בבואי עצב מאלה אשר היה לי לשמח עליהם ובטח אני בכלכם כי שמחתי היא שמחת כלכם׃ ");
INSERT INTO heb_vpl VALUES ("C22_4","077_2_4","2CO","2","4","4","כי מרב צרת לבי ומצוקה כתבתי לכם ובדמעות הרבה ולא להעציבכם רק למען תדעו האהבה היתרה אשר אהבתי אתכם׃ ");
INSERT INTO heb_vpl VALUES ("C22_5","077_2_5","2CO","2","5","5","ואם יש איש אשר העציב לא אתי העציב אלא כלכם פן אפריז על המדה העציב למקצת׃ ");
INSERT INTO heb_vpl VALUES ("C22_6","077_2_6","2CO","2","6","6","ודי לאיש כמהו התוכחה ההיא אמת הרבים׃ ");
INSERT INTO heb_vpl VALUES ("C22_7","077_2_7","2CO","2","7","7","ועתה להפך תסלחו ותנחמו כדי שלא יתבלע האיש בגדל העצבון׃ ");
INSERT INTO heb_vpl VALUES ("C22_8","077_2_8","2CO","2","8","8","על כן אבקשה מכם לגמל עליו גמולת אהבה׃ ");
INSERT INTO heb_vpl VALUES ("C22_9","077_2_9","2CO","2","9","9","כי לבעבור זאת גם כתבתי למען אדע את תמתכם אם בכל תשמעון׃ ");
INSERT INTO heb_vpl VALUES ("C22_10","077_2_10","2CO","2","10","10","ואיש אשר תסלחו לו אסלח לו גם אני כי גם אנכי אם סלחתי דבר סלחתי לו למענכם בפני המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C22_11","077_2_11","2CO","2","11","11","פן יונה אתנו השטן כי לא נעלמו מאתנו מזמותיו׃ ");
INSERT INTO heb_vpl VALUES ("C22_12","077_2_12","2CO","2","12","12","ואני בבאי לטרואס על דבר בשורת המשיח אף כי נפתח לי פתח באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("C22_13","077_2_13","2CO","2","13","13","לא היתה רוחה לרוחי על אשר לא מצאתי שם את טיטוס אחי ואני נפטרתי מהם ויצאתי ללכת אל מקדוניא׃ ");
INSERT INTO heb_vpl VALUES ("C22_14","077_2_14","2CO","2","14","14","אבל תודות לאלהים הנתן לנו בכל עת נצחון במשיח ומפיץ על ידינו את ריח דעתו בכל מקום׃ ");
INSERT INTO heb_vpl VALUES ("C22_15","077_2_15","2CO","2","15","15","כי ריח ניחח המשיח אנחנו לאלהים גם בתוך הנושעים וגם בתוך האבדים׃ ");
INSERT INTO heb_vpl VALUES ("C22_16","077_2_16","2CO","2","16","16","לאלה ריח מות למות ולאלה ריח חיים לחיים ומי זה ראוי לכך׃ ");
INSERT INTO heb_vpl VALUES ("C22_17","077_2_17","2CO","2","17","17","כי אנחנו איננו כמו הרבים העשים סחורה בדבר האלהים כי אם מתוך ישר לבב ומאלהים לפני אלהים נדבר במשיח׃ ");
INSERT INTO heb_vpl VALUES ("C23_1","077_3_1","2CO","3","1","1","הנחל עוד לשבח עצמנו האם נצטרך כמקצת אנשים לאגרות אליכם או מכם המזכירות אתנו לשבח׃ ");
INSERT INTO heb_vpl VALUES ("C23_2","077_3_2","2CO","3","2","2","אתם אגרתנו הכתובה בלבבנו ונודעה ונקראה לכל אדם׃ ");
INSERT INTO heb_vpl VALUES ("C23_3","077_3_3","2CO","3","3","3","כי בידוע שאתם אגרת המשיח ערוכה על ידי שרותנו כתובה לא בדיו כי אם ברוח אלהים חיים ולא על לוחות אבן כי אם על לוחות בשר הלב׃ ");
INSERT INTO heb_vpl VALUES ("C23_4","077_3_4","2CO","3","4","4","וכזה בטחוננו באלהים על ידי המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C23_5","077_3_5","2CO","3","5","5","יען אשר לא נוכל אנחנו לדין דין מעצמנו כי יכלתנו מאת האלהים היא׃ ");
INSERT INTO heb_vpl VALUES ("C23_6","077_3_6","2CO","3","6","6","אשר הכשיר אתנו למשרתי ברית חדשה לא של האותיות אלא של הרוח כי האות ימית והרוח יחיה׃ ");
INSERT INTO heb_vpl VALUES ("C23_7","077_3_7","2CO","3","7","7","ואם שרות המות החרות באותיות על האבן נראה בכבוד עד שלא יכלו בני ישראל להביט אל פני משה מפני כבוד פניו העמד להבטל׃ ");
INSERT INTO heb_vpl VALUES ("C23_8","077_3_8","2CO","3","8","8","כמה יגדל כבוד שרות הרוח׃ ");
INSERT INTO heb_vpl VALUES ("C23_9","077_3_9","2CO","3","9","9","כי אם השרות אשר לחיב כבוד הוא כמה יעדף בכבוד השרות אשר לזכות׃ ");
INSERT INTO heb_vpl VALUES ("C23_10","077_3_10","2CO","3","10","10","כי אף הנכבד איננו נחשב לכבוד לעמת הכבוד הנעלה הזה׃ ");
INSERT INTO heb_vpl VALUES ("C23_11","077_3_11","2CO","3","11","11","כי אם הדבר העמד להבטל יש לו כבוד הדבר הקים על אחת כמה וכמה׃ ");
INSERT INTO heb_vpl VALUES ("C23_12","077_3_12","2CO","3","12","12","על כן בהיות לנו תקוה כזאת פתחון פינו רב הוא׃ ");
INSERT INTO heb_vpl VALUES ("C23_13","077_3_13","2CO","3","13","13","ולא כמשה אשר נתן מסוה על פניו פן יביטו בני ישראל אל סוף העמד להבטל׃ ");
INSERT INTO heb_vpl VALUES ("C23_14","077_3_14","2CO","3","14","14","אבל נטמטמו דעותיהם כי עד היום הזה בקראם הברית הישנה נשאר ולא גלה המסוה ההוא אשר לא יוסר כי אם במשיח׃ ");
INSERT INTO heb_vpl VALUES ("C23_15","077_3_15","2CO","3","15","15","אבל עד היום הזה בקראם את משה מונח מסוה על לבם׃ ");
INSERT INTO heb_vpl VALUES ("C23_16","077_3_16","2CO","3","16","16","וכשיפנו אל האדון יוסר המסוה׃ ");
INSERT INTO heb_vpl VALUES ("C23_17","077_3_17","2CO","3","17","17","והאדון הוא הרוח ובאשר רוח האדון שם החרות׃ ");
INSERT INTO heb_vpl VALUES ("C23_18","077_3_18","2CO","3","18","18","ואנחנו כלנו בפנים מגלים ראים את כבוד האדון במראה ונחלף אל עצם דמות ההיא מכבוד אל כבוד כהחלף מאת אדון הרוח׃ ");
INSERT INTO heb_vpl VALUES ("C24_1","077_4_1","2CO","4","1","1","על כן בהיות לנו השרות הזה כאשר חננו לא נחת׃ ");
INSERT INTO heb_vpl VALUES ("C24_2","077_4_2","2CO","4","2","2","כי אם מאסנו בסתרי הבשת שלא להתהלך בערמה ולא לזיף את דבר האלהים אלא בהראות האמת נזכיר אתנו לטוב נגד דעת כל בני אדם לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C24_3","077_4_3","2CO","4","3","3","וגם כי נעלמה בשורתנו נעלמה היא מן האבדים׃ ");
INSERT INTO heb_vpl VALUES ("C24_4","077_4_4","2CO","4","4","4","אשר אלהי העולם הזה עור בהם את דעות הסוררים לבלתי זרח להם נגה בשורת כבוד המשיח אשר הוא צלם האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C24_5","077_4_5","2CO","4","5","5","כי לא אתנו מכריזים אנחנו כי אם את המשיח ישוע לאמר הוא האדון ואנחנו עבדיכם למען ישוע׃ ");
INSERT INTO heb_vpl VALUES ("C24_6","077_4_6","2CO","4","6","6","כי האלהים אשר אמר ויפע אור מחשך הוא הופיע בלבנו להפיץ אור דעת כבוד האלהים אשר בפני המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C24_7","077_4_7","2CO","4","7","7","אבל יש לנו האוצר הזה בכלי חרש למען אשר תהיה הגבורה היתרה לאלהים ולא מאתנו׃ ");
INSERT INTO heb_vpl VALUES ("C24_8","077_4_8","2CO","4","8","8","נחלצים אנחנו בכל ולא נדכאים דאגים ולא נואשים׃ ");
INSERT INTO heb_vpl VALUES ("C24_9","077_4_9","2CO","4","9","9","נרדפים ולא נטושים משלכים ולא אבדים׃ ");
INSERT INTO heb_vpl VALUES ("C24_10","077_4_10","2CO","4","10","10","ונשאים בכל עת מיתת האדון ישוע בגויתנו למען יגלו גם חיי ישוע בגויתנו׃ ");
INSERT INTO heb_vpl VALUES ("C24_11","077_4_11","2CO","4","11","11","כי אנחנו החיים נמסרים תמיד למות בעבור ישוע למען יגלו גם חיי ישוע בבשרנו בשר התמותה׃ ");
INSERT INTO heb_vpl VALUES ("C24_12","077_4_12","2CO","4","12","12","לכן בנו יאמץ המות ובכם החיים׃ ");
INSERT INTO heb_vpl VALUES ("C24_13","077_4_13","2CO","4","13","13","ובהיות לנו הרוח ההוא של האמונה כדבר הכתוב האמנתי כי אדבר גם אנחנו נאמין ועל כן נדבר׃ ");
INSERT INTO heb_vpl VALUES ("C24_14","077_4_14","2CO","4","14","14","באשר ידענו כי המעיר את האדון ישוע יעיר גם אתנו על יד ישוע ויעמידנו עמכם׃ ");
INSERT INTO heb_vpl VALUES ("C24_15","077_4_15","2CO","4","15","15","כי כל זאת למענכם למען אשר ירבה החסד על ידי רבים ותפרץ התודה לכבוד האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C24_16","077_4_16","2CO","4","16","16","ובעבור זאת לא נחת ואף אם יכלה בנו האדם החיצון הנה האדם הפנימי יתחדש יום יום׃ ");
INSERT INTO heb_vpl VALUES ("C24_17","077_4_17","2CO","4","17","17","כי לחצנו אשר הוא קל ואך לרגע יביא לנו כבוד עולמים גדול ורב עד למאד׃ ");
INSERT INTO heb_vpl VALUES ("C24_18","077_4_18","2CO","4","18","18","אשר לא נביט אל הדברים הנראים כי אם אל אשר אינם נראים כי הנראים לשעה המה ואשר אינם נראים הם לעולם׃ ");
INSERT INTO heb_vpl VALUES ("C25_1","077_5_1","2CO","5","1","1","הן ידענו כי בהרס בית אהלנו אשר בארץ יש לנו בנין מאת האלהים בית אשר איננו מעשה ידים והוא לעולם בשמים׃ ");
INSERT INTO heb_vpl VALUES ("C25_2","077_5_2","2CO","5","2","2","כי גם עתה נאנחים ונכספים אנחנו להתעטף בביתנו אשר מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("C25_3","077_5_3","2CO","5","3","3","באשר אחרי לבשנהו לא נמצא ערמים׃ ");
INSERT INTO heb_vpl VALUES ("C25_4","077_5_4","2CO","5","4","4","כי גם עתה באהלנו זה נאנח מפני הכבד ולא חפצנו להתפשט כי אם להתעטף למען יבלע המות על ידי החיים׃ ");
INSERT INTO heb_vpl VALUES ("C25_5","077_5_5","2CO","5","5","5","והמכין אתנו לזאת הוא האלהים אשר אף נתן לנו את ערבון הרוח׃ ");
INSERT INTO heb_vpl VALUES ("C25_6","077_5_6","2CO","5","6","6","לכן בטוחים אנחנו בכל עת וידעים כי כל עוד שמושבנו בגוף רחוקים אנחנו מן האדון׃ ");
INSERT INTO heb_vpl VALUES ("C25_7","077_5_7","2CO","5","7","7","כי באמונה נתהלך ולא בראות עינים׃ ");
INSERT INTO heb_vpl VALUES ("C25_8","077_5_8","2CO","5","8","8","אמנם בטוחים אנחנו ונבחרה לנו להתרחק מן הגוף ולהיות קרובים אל האדון׃ ");
INSERT INTO heb_vpl VALUES ("C25_9","077_5_9","2CO","5","9","9","על כן גם נשתדל אם קרובים אם רחוקים להיות לו לרצון׃ ");
INSERT INTO heb_vpl VALUES ("C25_10","077_5_10","2CO","5","10","10","כי כלנו עתידים להראות לפני כסא דין המשיח למען יקבל איש ואיש כפי פעלו בחיי גופו אם טוב ואם רע׃ ");
INSERT INTO heb_vpl VALUES ("C25_11","077_5_11","2CO","5","11","11","ועתה יען אשר ידענו יראת האדון נדבר על לב בני אדם ולאלהים אנחנו גלוים ואקוה כי גלוים אנחנו גם במדעכם׃ ");
INSERT INTO heb_vpl VALUES ("C25_12","077_5_12","2CO","5","12","12","כי אין אנחנו משתבחין שנית אליכם אך נתנים לכם סבה להתפאר בנו לנגד המתפארים בפנים ולא בלב׃ ");
INSERT INTO heb_vpl VALUES ("C25_13","077_5_13","2CO","5","13","13","כי אם השתגענו לאלהים היתה זאת ואם השכלנו לכם היתה׃ ");
INSERT INTO heb_vpl VALUES ("C25_14","077_5_14","2CO","5","14","14","כי אהבת המשיח דחקת אתנו בהיותנו דנים אשר אם מת אחד בעד כלם כלם מתו׃ ");
INSERT INTO heb_vpl VALUES ("C25_15","077_5_15","2CO","5","15","15","ובעד כלם מת למען לא יחיו החיים עוד לנפשם כי אם לאשר מת ויקם בעדם׃ ");
INSERT INTO heb_vpl VALUES ("C25_16","077_5_16","2CO","5","16","16","לכן מעתה אנחנו לא נדע איש לפי הבשר וגם אם ידענו את המשיח לפי הבשר מעתה לא נדעהו עוד׃ ");
INSERT INTO heb_vpl VALUES ("C25_17","077_5_17","2CO","5","17","17","ובכן מי שהוא במשיח בריאה חדשה הוא הישנות עברו והנה הכל נהיה לחדש׃ ");
INSERT INTO heb_vpl VALUES ("C25_18","077_5_18","2CO","5","18","18","והכל מאת האלהים המרצה אתנו לעצמו על ידי ישוע המשיח ויתן לנו שרות הרצוי׃ ");
INSERT INTO heb_vpl VALUES ("C25_19","077_5_19","2CO","5","19","19","יען אשר אלהים היה במשיח מרצה את העולם לעצמו ולא חשב להם את פשעיהם וישם בנו את דבר הרצוי׃ ");
INSERT INTO heb_vpl VALUES ("C25_20","077_5_20","2CO","5","20","20","לכן מליצי המשיח אנחנו וכאלו האלהים מזהיר אתכם על ידנו נבקש מכם בעד המשיח התרצו נא אל האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C25_21","077_5_21","2CO","5","21","21","כי את אשר לא ידע חטאת אתו עשה לחטאת בעדנו למען נהיה בו אנחנו לצדקת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C26_1","077_6_1","2CO","6","1","1","ואנחנו כעזרים נזהירה אתכם שלא תקבלו לריק את חסד אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C26_2","077_6_2","2CO","6","2","2","כי הוא אומר בעת רצון עניתיך וביום ישועה עזרתיך הנה עתה עת רצון הנה עתה יום ישועה׃ ");
INSERT INTO heb_vpl VALUES ("C26_3","077_6_3","2CO","6","3","3","ואין אנחנו נתנים מכשול במאומה פן יהיה שרותנו לנאצה׃ ");
INSERT INTO heb_vpl VALUES ("C26_4","077_6_4","2CO","6","4","4","כי אם נראה בכל דבר כמשרתי אלהים בסבלנות רבה בלחץ ובצרות ובמצוקות׃ ");
INSERT INTO heb_vpl VALUES ("C26_5","077_6_5","2CO","6","5","5","במכות ובמוסרות ובמהומות בתלאות בשקידות ובצומות׃ ");
INSERT INTO heb_vpl VALUES ("C26_6","077_6_6","2CO","6","6","6","בטהרה ובדעת ובארך רוח ובחסד וברוח הקדש ובאהבה לא צבועה׃ ");
INSERT INTO heb_vpl VALUES ("C26_7","077_6_7","2CO","6","7","7","בדבר האמת ובגבורת אלהים בכלי נשק הצדקה מימין ומשמאל׃ ");
INSERT INTO heb_vpl VALUES ("C26_8","077_6_8","2CO","6","8","8","בכבוד ובקלון בשם רע ובשם טוב כמתעים ובכל זאת נאמנים׃ ");
INSERT INTO heb_vpl VALUES ("C26_9","077_6_9","2CO","6","9","9","כאינם ידועים וגם ידועים כמתים והננו חיים כמיסרים ולא מומתים׃ ");
INSERT INTO heb_vpl VALUES ("C26_10","077_6_10","2CO","6","10","10","כנעצבים ובכל עת שמחים כרשים ומעשירי רבים כאשר אין להם מאומה ויש להם כל׃ ");
INSERT INTO heb_vpl VALUES ("C26_11","077_6_11","2CO","6","11","11","פינו פתוח לכם אנשי קורנתוס ורחב לבנו׃ ");
INSERT INTO heb_vpl VALUES ("C26_12","077_6_12","2CO","6","12","12","לא צר מקומכם בנו אך צר המקום במעיכם׃ ");
INSERT INTO heb_vpl VALUES ("C26_13","077_6_13","2CO","6","13","13","והיה זה גמולי כמו אל בנים אנכי מדבר אם תרחיבו לבבכם גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("C26_14","077_6_14","2CO","6","14","14","אל תהיו משכי על זר עם חסרי אמונה כי אי זה שתפות יש לצדקה עם העול ואי זה התחברות לאור עם החשך׃ ");
INSERT INTO heb_vpl VALUES ("C26_15","077_6_15","2CO","6","15","15","ואי זה הסכמה למשיח עם בליאל או מה חלק המאמין עם שאיננו מאמין׃ ");
INSERT INTO heb_vpl VALUES ("C26_16","077_6_16","2CO","6","16","16","ואי זה דבק יש להיכל אלהים עם האלילים כי אתם היכל אלהים חיים כמו שאמר האלהים ושכנתי והתהלכתי בתוכם והייתי להם לאלהים והם יהיו לי לעם׃ ");
INSERT INTO heb_vpl VALUES ("C26_17","077_6_17","2CO","6","17","17","על כן צאו מתוכם והברו נאם יהוה וטמא אל תגעו ואני אקבץ אתכם׃ ");
INSERT INTO heb_vpl VALUES ("C26_18","077_6_18","2CO","6","18","18","והייתי לכם לאב ואתם תהיו לי לבנים ולבנות נאם יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("C27_1","077_7_1","2CO","7","1","1","לכן חביבי בהיות לנו ההבטחות האלה נטהרה את עצמנו מכל טמאת בשר ורוח להשלים קדשתנו ביראת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C27_2","077_7_2","2CO","7","2","2","תנו לנו מקום בלבבכם לא חמסנו איש לא חבלנו איש לא עשקנו איש׃ ");
INSERT INTO heb_vpl VALUES ("C27_3","077_7_3","2CO","7","3","3","לא לחיב אתכם אני מדבר הלא הקדמתי לאמר כי אתם בלבנו יחד למות ויחד לחיות׃ ");
INSERT INTO heb_vpl VALUES ("C27_4","077_7_4","2CO","7","4","4","רב בטחוני עליכם רבה תהלתי בכם מלאתי נחמה שבעתי שמחות בכל לחצנו׃ ");
INSERT INTO heb_vpl VALUES ("C27_5","077_7_5","2CO","7","5","5","כי גם בבאנו אל מקדוניא לא היתה מרגעה לבשרנו רק נלחצנו בכל מחוץ מלחמות ומחדרים אימה׃ ");
INSERT INTO heb_vpl VALUES ("C27_6","077_7_6","2CO","7","6","6","אבל האלהים המנחם את השפלים נחם אתנו בבוא טיטוס׃ ");
INSERT INTO heb_vpl VALUES ("C27_7","077_7_7","2CO","7","7","7","ולא בבאו לבד כי אם גם בנחמה אשר נחם בכם בהגידו לנו את תשוקתכם ואת אבלכם ואת קנאתכם לי ובכן הוספתי לשמוח׃ ");
INSERT INTO heb_vpl VALUES ("C27_8","077_7_8","2CO","7","8","8","כי גם אם העצבתי אתכם באגרת אינני מתחרט גם כי התחרטתי לפני מזה בראותי כי האגרת ההיא העציבה אתכם ואף אם לשעה׃ ");
INSERT INTO heb_vpl VALUES ("C27_9","077_7_9","2CO","7","9","9","עתה אני שמח לא על אשר נעצבתם כי אם על אשר נעצבתם לתשובה כי נעצבתם כרצון אלהים למען לא תשאו נזק במאומה על ידנו׃ ");
INSERT INTO heb_vpl VALUES ("C27_10","077_7_10","2CO","7","10","10","כי העצבת שהיא כרצון אלהים תפעל תשובה לישועה אשר איש לא יתחרט עליה אבל עצבת העולם פעלת את המות׃ ");
INSERT INTO heb_vpl VALUES ("C27_11","077_7_11","2CO","7","11","11","כי ראו נא את אשר נעצבתם כרצון אלהים כמה הביא אתכם זה לידי זריזות גם להתנצלות גם לרגז גם ליראה גם לתשוקה גם לקנאה גם לנקמה ובכל הוכחתם כי נקיים אתם בדבר ההוא׃ ");
INSERT INTO heb_vpl VALUES ("C27_12","077_7_12","2CO","7","12","12","לכן גם אם כתבתי לכם לא כתבתי בעבור העלב ולא בעבור הנעלב רק למען תגלה בכם זריזותנו בעדכם לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C27_13","077_7_13","2CO","7","13","13","ובעבור זאת נחמנו בנחמתכם ועוד שמחה יתרה היתה לנו בשמחת טיטוס כי הונח רוחו על ידי כלכם׃ ");
INSERT INTO heb_vpl VALUES ("C27_14","077_7_14","2CO","7","14","14","כי במה שהתהללתי לפניו בכם לא נכלמתי כי כמו שדברנו הכל אליכם באמת כן גם תהלתנו אל טיטוס היתה אמת׃ ");
INSERT INTO heb_vpl VALUES ("C27_15","077_7_15","2CO","7","15","15","וביותר מעיו המו לכם בזכרו את משמעת כלכם ואת אשר קבלתם אתו ביראה ובחרדה׃ ");
INSERT INTO heb_vpl VALUES ("C27_16","077_7_16","2CO","7","16","16","לכן אני שמח כי בכל דבר יאמץ לבי בכם׃ ");
INSERT INTO heb_vpl VALUES ("C28_1","077_8_1","2CO","8","1","1","והננו מודיעים אתכם אחי את חסד אלהים הנתן בקהלות מקדוניא׃ ");
INSERT INTO heb_vpl VALUES ("C28_2","077_8_2","2CO","8","2","2","כי ברב נסיון הלחץ רבתה שמחתם ושפלות רישם העדיפה להראות עשר תמתם׃ ");
INSERT INTO heb_vpl VALUES ("C28_3","077_8_3","2CO","8","3","3","כי מעיד אנכי אשר לפי כחם ויותר מכחם התנדבו׃ ");
INSERT INTO heb_vpl VALUES ("C28_4","077_8_4","2CO","8","4","4","ויבקשו ממנו ברב תחנונים להיות חברינו בגמילות חסדם לעזרת הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("C28_5","077_8_5","2CO","8","5","5","ולא כאשר הוחלנו כי אם את עצמם נתנו בראשונה לאדון וגם לנו ברצון האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C28_6","077_8_6","2CO","8","6","6","עד כי בקשנו מן טיטוס כאשר החל כן גם לגמור בכם את גמילות החסד הזאת׃ ");
INSERT INTO heb_vpl VALUES ("C28_7","077_8_7","2CO","8","7","7","אבל כאשר הותרתם בכל באמונה ובדבור ובדעת ובכל זריזות ובאהבתכם אתנו כן גם תותירו בחסד הזה׃ ");
INSERT INTO heb_vpl VALUES ("C28_8","077_8_8","2CO","8","8","8","ואינני אמר זאת בדרך צווי כי אם לבחן על ידי זריזות אחרים גם את אמתת אהבתכם׃ ");
INSERT INTO heb_vpl VALUES ("C28_9","077_8_9","2CO","8","9","9","כי ידעים אתם את חסד אדנינו ישוע המשיח כי בהיותו עשיר נעשה רש בעבורכם למען תעשירו על ידי רישו׃ ");
INSERT INTO heb_vpl VALUES ("C28_10","077_8_10","2CO","8","10","10","ואחוה את דעתי בדבר הזה כי זאת להועיל לכם אשר הקדמתם כבר בשנה שעברה לא לעשות בלבד כי גם לחפץ׃ ");
INSERT INTO heb_vpl VALUES ("C28_11","077_8_11","2CO","8","11","11","ועתה גם השלימו את המעשה למען כאשר התנדבתם לעשות כן גם תגמרו כפי יכלתכם׃ ");
INSERT INTO heb_vpl VALUES ("C28_12","077_8_12","2CO","8","12","12","כי בהמצא לאיש רוח נדיבה רצויה היא לפי מה שיש לו ולא לפי מה שאין לו׃ ");
INSERT INTO heb_vpl VALUES ("C28_13","077_8_13","2CO","8","13","13","כי לא למען תהיה רוחה לאחרים ולכם צוקה כי אם בשווי ימלא יתרכם בעת הזאת את מחסורם׃ ");
INSERT INTO heb_vpl VALUES ("C28_14","077_8_14","2CO","8","14","14","למען גם יתרם יהיה למלא מחסרכם כדי להשות׃ ");
INSERT INTO heb_vpl VALUES ("C28_15","077_8_15","2CO","8","15","15","ככתוב לא העדיף המרבה והממעיט לא החסיר׃ ");
INSERT INTO heb_vpl VALUES ("C28_16","077_8_16","2CO","8","16","16","ותודות לאלהים הנותן גם בלב טיטוס לשקד עליכם בשקידה כזאת׃ ");
INSERT INTO heb_vpl VALUES ("C28_17","077_8_17","2CO","8","17","17","כי שמע לבקשתנו ובשקידתו היתרה הלך אליכם מרצון נפשו׃ ");
INSERT INTO heb_vpl VALUES ("C28_18","077_8_18","2CO","8","18","18","ועמו יחדו שלחנו האח אשר יצא שבחו בבשורה בכל הקהלות׃ ");
INSERT INTO heb_vpl VALUES ("C28_19","077_8_19","2CO","8","19","19","ומלבד זאת גם נבחר הוא מאת הקהלות ללכת אתנו להביא החסד הזה הגבוי על ידינו לכבוד האדון ולאמץ לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("C28_20","077_8_20","2CO","8","20","20","ונשמר בזאת שלא יוציא איש עלינו דבה רעה בשפעת המתנה הזאת הגבויה על ידינו׃ ");
INSERT INTO heb_vpl VALUES ("C28_21","077_8_21","2CO","8","21","21","כי משגיחים אנחנו על הטוב לא לפני האדון לבד כי גם לפני האדם׃ ");
INSERT INTO heb_vpl VALUES ("C28_22","077_8_22","2CO","8","22","22","ונשלח עמהם את אחינו אשר בחנו את שקידתו פעמים רבות בדברים הרבה ועתה הוא שקוד עוד יותר בגדל בטחונו עליכם׃ ");
INSERT INTO heb_vpl VALUES ("C28_23","077_8_23","2CO","8","23","23","אם לטיטוס הנה חברי הוא ועזרי בכם ואם לאחינו הנה שלוחי הקהלות הם ותפארת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C28_24","077_8_24","2CO","8","24","24","על כן הראו והוכיחו להם לפני הקהלות את אהבתכם ואת תהלתנו עליכם׃ ");
INSERT INTO heb_vpl VALUES ("C29_1","077_9_1","2CO","9","1","1","אמנם אין צרך לכתב אליכם על דבר השרות אשר לעזרת הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("C29_2","077_9_2","2CO","9","2","2","כי ידעתי את נדיבתכם אשר עליה אני מתהלל בכם לפני אנשי מקדוניא לאמר אכיא מזמנת היא משנה שעברה ותער הקנאה היוצאת מכם את רוח רבם׃ ");
INSERT INTO heb_vpl VALUES ("C29_3","077_9_3","2CO","9","3","3","אבל שלחתי את האחים פן תהיה לריק תהלתנו עליכם בדבר הזה ולמען תהיו מזמנים כאשר אמרתי׃ ");
INSERT INTO heb_vpl VALUES ("C29_4","077_9_4","2CO","9","4","4","פן בבוא אתי אנשים ממקדוניא ימצאו אתכם לא מזמנים ונבוש אנחנו ואינני אמר אתם בבטחון הזה אשר התהללנו בו׃ ");
INSERT INTO heb_vpl VALUES ("C29_5","077_9_5","2CO","9","5","5","על כן היה נכון בעיני לבקש מן האחים כי יקדמו ללכת אליכם ויכינו את ברכתכם המיועדה מלפנים למען תהיה מוכנת כעין ברכה ולא כעין כילות׃ ");
INSERT INTO heb_vpl VALUES ("C29_6","077_9_6","2CO","9","6","6","כי הנה הזרע בצמצום גם יקצר בצמצום והזרע בברכות גם יקצר בברכות׃ ");
INSERT INTO heb_vpl VALUES ("C29_7","077_9_7","2CO","9","7","7","וכל איש כאשר ידבנו לבו לא מצער ולא מאנס כי הנתן בלב שמח יאהבנו אלהים׃ ");
INSERT INTO heb_vpl VALUES ("C29_8","077_9_8","2CO","9","8","8","ואלהים יכל להשפיע עליכם כל חסד עד כי יהיה לכם בכל עת די ספוקכם בכל ותותירו בכל מעשה טוב׃ ");
INSERT INTO heb_vpl VALUES ("C29_9","077_9_9","2CO","9","9","9","ככתוב פזר נתן לאביונים צדקתו עמדת לעד׃ ");
INSERT INTO heb_vpl VALUES ("C29_10","077_9_10","2CO","9","10","10","והנתן זרע לזרע ולחם לאכל יתן וירבה את זרעכם ויפריא תנובות צדקתכם׃ ");
INSERT INTO heb_vpl VALUES ("C29_11","077_9_11","2CO","9","11","11","למען תעשירו בכל לכל התמימות הפעלת תודה לאלהים על ידינו׃ ");
INSERT INTO heb_vpl VALUES ("C29_12","077_9_12","2CO","9","12","12","כי שרות העבודה הזאת לא לבד ימלא את מחסרי הקדושים כי גם יודו רבים לאלהים בשרותכם הנאמן הזה׃ ");
INSERT INTO heb_vpl VALUES ("C29_13","077_9_13","2CO","9","13","13","ויכבדו את האלהים על משמעת הודאתכם לבשורת המשיח ועל תמת התחברותכם אליהם ואל כלם׃ ");
INSERT INTO heb_vpl VALUES ("C29_14","077_9_14","2CO","9","14","14","והם בהתחננם בעדכם נכספים לכם בעבור חסד האלהים אשר גבר עליכם׃ ");
INSERT INTO heb_vpl VALUES ("C29_15","077_9_15","2CO","9","15","15","ותודה לאלהים על מתנתו העצומה מספר׃ ");
INSERT INTO heb_vpl VALUES ("C210_1","077_10_1","2CO","10","1","1","ואני פולוס הנני מזהיר אתכם בענות המשיח וחמלתו אשר פנים בפנים שפל אני בתוככם וברחקי מתאמץ עליכון׃ ");
INSERT INTO heb_vpl VALUES ("C210_2","077_10_2","2CO","10","2","2","ואתחננה שלא אצטרך בבאי להתאמץ בבטחון ההוא אשר אחשב להתגבר בו נגד האנשים החשבים אתנו כמתהלכים לפי הבשר׃ ");
INSERT INTO heb_vpl VALUES ("C210_3","077_10_3","2CO","10","3","3","כי בלכתנו בבשר לא נלחם לפי הבשר׃ ");
INSERT INTO heb_vpl VALUES ("C210_4","077_10_4","2CO","10","4","4","כי כלי מלחמתנו אינם של הבשר כי אם חזקים הם לאלהים להרס מבצרים׃ ");
INSERT INTO heb_vpl VALUES ("C210_5","077_10_5","2CO","10","5","5","באשר הרסים אנחנו תחבלות וכל מרום המתנשא נגד דעת האלהים ושובים כל מזמה למשמעת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C210_6","077_10_6","2CO","10","6","6","ונכונים לנקם נקמה מאת כל מרי אם תשלם משמעתכם׃ ");
INSERT INTO heb_vpl VALUES ("C210_7","077_10_7","2CO","10","7","7","התשפטו למראה פנים איש כי יבטח להיות למשיח ישוב וידין בלבו כי כאשר הוא למשיח כן למשיח גם אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("C210_8","077_10_8","2CO","10","8","8","וגם כי אתהלל יותר מעט על דבר הרשות אשר נתן לנו האדון לבנותכם ולא לשחתכם לא אבוש׃ ");
INSERT INTO heb_vpl VALUES ("C210_9","077_10_9","2CO","10","9","9","למען לא אראה כמאים אתכם על ידי האגרות׃ ");
INSERT INTO heb_vpl VALUES ("C210_10","077_10_10","2CO","10","10","10","כאמרם הן האגרות קשות הנה וחזקות אבל הגוף בהיותו לנגדנו חלוש הוא וניבו נבזה׃ ");
INSERT INTO heb_vpl VALUES ("C210_11","077_10_11","2CO","10","11","11","ידע נא האמר כזאת כי כמו שאנחנו בדבור על ידי אגרות בהיותנו רחוקים כן גם בפעל אנחנו בהיותנו קרובים׃ ");
INSERT INTO heb_vpl VALUES ("C210_12","077_10_12","2CO","10","12","12","כי אל נעז פנינו לכלל אתנו עם האנשים המשבחים נפשם או לערך אתנו לאלה אכן נבערו מדעת המדדים את נפשם בנפשם וערכים את נפשם לנפשם׃ ");
INSERT INTO heb_vpl VALUES ("C210_13","077_10_13","2CO","10","13","13","ואנחנו לא נתגדל לבלי מדה כי אם כפי מדת הגבול אשר חלק לנו האלהים לחק להגיע גם עדיכם׃ ");
INSERT INTO heb_vpl VALUES ("C210_14","077_10_14","2CO","10","14","14","כי לולא הגענו עדיכם לא נשתרע למעלה מערכנו הלא כבר קדמנו גם אתכם בבשורת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C210_15","077_10_15","2CO","10","15","15","לא נתגדל לבלי מדה ביגיעת אחרים אבליש לנו התקוה כי ברבות אמונתכם נכבד בכם כפי גבולנו עד למעלה׃ ");
INSERT INTO heb_vpl VALUES ("C210_16","077_10_16","2CO","10","16","16","כדי לבשר הבשורה גם להלאה מכם ולא להתהלל במה שמוכן כבר בגבול אחרים׃ ");
INSERT INTO heb_vpl VALUES ("C210_17","077_10_17","2CO","10","17","17","והמתהלל יתהלל ביהוה׃ ");
INSERT INTO heb_vpl VALUES ("C210_18","077_10_18","2CO","10","18","18","כי לא המשבח נפשו משבח הוא כי אם אשר ישבחנו יהוה׃ ");
INSERT INTO heb_vpl VALUES ("C211_1","077_11_1","2CO","11","1","1","אחלי תשאו מעט אולתי ואף אמנם תשאוני׃ ");
INSERT INTO heb_vpl VALUES ("C211_2","077_11_2","2CO","11","2","2","כי מקנא אני לכם קנאת אלהים כי ארשתי אתכם לאיש אחד להעמיד אתכם בתולה טהורה לפני המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C211_3","077_11_3","2CO","11","3","3","אך ירא אנכי פן כאשר השיא הנחש בערמתו את חוה כן תשטינה גם מחשבותיכם מן התמימות אשר עם המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C211_4","077_11_4","2CO","11","4","4","כי אם יבא הבא והגיד לכם ישוע אחר אשר לא הגדנהו או אם תקחו רוח אחר אשר לא לקחתם אתו או בשורה אחרת אשר לא קבלתם אתה כי עתה היטב תשאהו׃ ");
INSERT INTO heb_vpl VALUES ("C211_5","077_11_5","2CO","11","5","5","אולם אחשב אשר אינני נפל במאומה מהשליחים הגדולים כל כך׃ ");
INSERT INTO heb_vpl VALUES ("C211_6","077_11_6","2CO","11","6","6","ואף אם בער אנכי בדבור אינני בער בדעת כי אם בכל נגלינו אליכם בפני כל אדם׃ ");
INSERT INTO heb_vpl VALUES ("C211_7","077_11_7","2CO","11","7","7","או החטא חטאתי בהשפילי את עצמי למען הגביהכם כי בשרתי אתכם בלא מחיר את בשורת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("C211_8","077_11_8","2CO","11","8","8","קהלות אחרות שלותי בקחתי מהן שכר למען אשרתכם ובהיותי עמכם ואחסר לא הלאיתי אדם׃ ");
INSERT INTO heb_vpl VALUES ("C211_9","077_11_9","2CO","11","9","9","כי את מחסורי מלאו האחים בבאם ממקדוניא ובכל דבר נשמרתי מהיות לכם למשא וגם אשמר׃ ");
INSERT INTO heb_vpl VALUES ("C211_10","077_11_10","2CO","11","10","10","באמתו של המשיח אשר בי מעיד אני בכם כי תהלתי זאת לא תכלא ממני בגלילות אכיא׃ ");
INSERT INTO heb_vpl VALUES ("C211_11","077_11_11","2CO","11","11","11","על מה זה העל אשר אינני אהב אתכם האלהים יודע׃ ");
INSERT INTO heb_vpl VALUES ("C211_12","077_11_12","2CO","11","12","12","אבל את אשר אני עשה אוסיף לעשות לבלתי תת מקום למבקשים עלילה למען במה שיתהללו בו ימצאו דומים לנו׃ ");
INSERT INTO heb_vpl VALUES ("C211_13","077_11_13","2CO","11","13","13","כי אנשים כאלה שליחי שקר הם פעלי רמיה מתחפשים לשליחי המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C211_14","077_11_14","2CO","11","14","14","ואיננו פלא הלא השטן גם הוא מתחפש למלאך האור׃ ");
INSERT INTO heb_vpl VALUES ("C211_15","077_11_15","2CO","11","15","15","לכן אין זה דבר גדול אם גם משרתיו יתחפשו למשרתי הצדק אשר אחריתם תהיה לפי מעלליהם׃ ");
INSERT INTO heb_vpl VALUES ("C211_16","077_11_16","2CO","11","16","16","ואשוב ואמר אל נא יחשבני איש לסכל ואם אין אף כסכל קבלוני למען אתהלל מעט גם אני׃ ");
INSERT INTO heb_vpl VALUES ("C211_17","077_11_17","2CO","11","17","17","את אשר אדבר לא לפי דרך האדון אנכי מדבר כי אם כמו בסכלות אעז ואתהלל׃ ");
INSERT INTO heb_vpl VALUES ("C211_18","077_11_18","2CO","11","18","18","רבים מתהללים לפי הבשר לכן אתהלל אף אני׃ ");
INSERT INTO heb_vpl VALUES ("C211_19","077_11_19","2CO","11","19","19","כי נשאים אתם ברצון את הסכלים בהיותכם חכמים׃ ");
INSERT INTO heb_vpl VALUES ("C211_20","077_11_20","2CO","11","20","20","הלא תשאו אם יעביד אתכם איש אם יבלע אם ילכד אתכם אם יתנשא אם יכה אתכם על פניכם׃ ");
INSERT INTO heb_vpl VALUES ("C211_21","077_11_21","2CO","11","21","21","לחרפתנו אנכי אמר זאת כאלו היינו רפים אבל בכל אשר ירהב איש להתהלל בסכלות אמר זאת ארהב גם אנכי׃ ");
INSERT INTO heb_vpl VALUES ("C211_22","077_11_22","2CO","11","22","22","עברים הם כן גם אנכי ישראלים הם כן גם אנכי זרע אברהם הם כן גם אנכי׃ ");
INSERT INTO heb_vpl VALUES ("C211_23","077_11_23","2CO","11","23","23","משרתי המשיח הם כמתהולל אמר אנכי יותר מהם יותר ביגיעות יותר למאד במכות יותר במוסרות ורב פעמים במצוקות מות׃ ");
INSERT INTO heb_vpl VALUES ("C211_24","077_11_24","2CO","11","24","24","חמש פעמים ספגתי בידי היהודים ארבעים חסר אחת׃ ");
INSERT INTO heb_vpl VALUES ("C211_25","077_11_25","2CO","11","25","25","שלש פעמים יסרתי בשוטים פעם אחת סקלתי ושלש פעמים נשברה לי הספינה ואהי במצולות ים לילה ויום׃ ");
INSERT INTO heb_vpl VALUES ("C211_26","077_11_26","2CO","11","26","26","במסעות רבות בסכנות נהרות בסכנות שדדים בסכנות מצד בני עמי בסכנות מצד הגוים סכנות בעיר סכנות במדבר סכנות בים סכנות בתוך אחי שקר׃ ");
INSERT INTO heb_vpl VALUES ("C211_27","077_11_27","2CO","11","27","27","בעמל ובתלאה בשקידות הרבה ברעב ובצמא בצומות הרבה בקר ובעירום׃ ");
INSERT INTO heb_vpl VALUES ("C211_28","077_11_28","2CO","11","28","28","מלבד שאר הדברים הבאים עלי יום יום והדאגה לכל הקהלות׃ ");
INSERT INTO heb_vpl VALUES ("C211_29","077_11_29","2CO","11","29","29","מי יחלש ואני לא אחלש מי יכשל ולא יבער לבי׃ ");
INSERT INTO heb_vpl VALUES ("C211_30","077_11_30","2CO","11","30","30","אם יש להתהלל אתהלל בחלשתי׃ ");
INSERT INTO heb_vpl VALUES ("C211_31","077_11_31","2CO","11","31","31","האלהים אבי ישוע המשיח אדנינו המברך לעולמי עולמים הוא ידע כי לא אשקר׃ ");
INSERT INTO heb_vpl VALUES ("C211_32","077_11_32","2CO","11","32","32","בדמשק שמר הנצב של המלך ארטס את עיר הדמשקיין ויבקש לתפשני׃ ");
INSERT INTO heb_vpl VALUES ("C211_33","077_11_33","2CO","11","33","33","ובעד החלון הורידו אתי בסל מעל החומה ואמלט מידיו׃ ");
INSERT INTO heb_vpl VALUES ("C212_1","077_12_1","2CO","12","1","1","אמנם להתהלל לא יועיל לי כי אבוא למראות האדון וחזינותיו׃ ");
INSERT INTO heb_vpl VALUES ("C212_2","077_12_2","2CO","12","2","2","ידעתי איש במשיח זה ארבע עשרה שנה אם היה בגוף לא ידעתי או מחוץ לגוף לא ידעתי האלהים יודע והאיש ההוא לקח עד לרקיע השלישי׃ ");
INSERT INTO heb_vpl VALUES ("C212_3","077_12_3","2CO","12","3","3","וידעתי את האיש ההוא אם בגוף או מחוץ לגוף לא ידעתי האלהים יודע׃ ");
INSERT INTO heb_vpl VALUES ("C212_4","077_12_4","2CO","12","4","4","אשר העלה אל הפרדס וישמע דברים נסתרים אשר נמנע מאיש למללם׃ ");
INSERT INTO heb_vpl VALUES ("C212_5","077_12_5","2CO","12","5","5","על איש כמוהו אתהלל אך על עצמי לא אתהלל זולתי בחלשותי׃ ");
INSERT INTO heb_vpl VALUES ("C212_6","077_12_6","2CO","12","6","6","כי לו חפצתי להתהלל לא אהיה סכל כי אמת אדבר אבל אתאפק פן יחשבני איש יותר ממה שיראה בי או שישמע ממני׃ ");
INSERT INTO heb_vpl VALUES ("C212_7","077_12_7","2CO","12","7","7","ולמען אשר לא אתרומם ברב גדל החזינות נתן לי סלון בבשרי מלאך השטן להכתני באגרוף למען לא אתרומם׃ ");
INSERT INTO heb_vpl VALUES ("C212_8","077_12_8","2CO","12","8","8","על זאת התחננתי שלש פעמים אל האדון להסירו ממני׃ ");
INSERT INTO heb_vpl VALUES ("C212_9","077_12_9","2CO","12","9","9","ויאמר אלי די לך חסדי כי בחלשה תשלם גבורתי על כן שמח לבי להתהלל בחלשותי למען תשרה עלי גבורת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("C212_10","077_12_10","2CO","12","10","10","לכן רצתה נפשי בחלשות ובחרפות ובצרות וברדיפות ובמצוקות בעד המשיח כי כאשר חלשתי אז גבור אני׃ ");
INSERT INTO heb_vpl VALUES ("C212_11","077_12_11","2CO","12","11","11","סכל הייתי בהתהללי אתם הכרחתם אתי תחת אשר היה עליכם להזכירני לשבח כי לא נפל אנכי במאומה מן השליחים הגדולים כל כך אף כי כאין אנכי׃ ");
INSERT INTO heb_vpl VALUES ("C212_12","077_12_12","2CO","12","12","12","הן אתות השליח נעשו בקרבכם בכל סבלנות באתות ובמופתים ובגבורות׃ ");
INSERT INTO heb_vpl VALUES ("C212_13","077_12_13","2CO","12","13","13","כי במה נגרעתם מן הקהלות האחרות אם לא הלאיתי אתכם סלחו נא לי את העולה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("C212_14","077_12_14","2CO","12","14","14","הנני מוכן לבוא אליכם פעם שלישית ולא אלאה אתכם כי לא אבקש את אשר לכם כי אם אתכם כי הבנים אינם חיבים לאצר אוצרות לאבות כי אם האבות לבנים׃ ");
INSERT INTO heb_vpl VALUES ("C212_15","077_12_15","2CO","12","15","15","אבל אני בכל חפץ לבבי אפזר וגם אפזר בעד נפשותיכם אף אם תחת אהבתי לכם היתרה אתם תמעיטו את אהבתכם אלי׃ ");
INSERT INTO heb_vpl VALUES ("C212_16","077_12_16","2CO","12","16","16","אך אם כן הוא ואני לא הכבדתי עליכם אולי כאיש ערום במרמה לכדתי אתכם׃ ");
INSERT INTO heb_vpl VALUES ("C212_17","077_12_17","2CO","12","17","17","האף הוניתי אתכם ביד אחד מאלה אשר שלחתי אליכם׃ ");
INSERT INTO heb_vpl VALUES ("C212_18","077_12_18","2CO","12","18","18","בקשתי מן טיטוס ושלחתי אתו את האח הכי הונה אתכם טיטוס הלא ברוח אחד התהלכנו הלא במעגל אחד׃ ");
INSERT INTO heb_vpl VALUES ("C212_19","077_12_19","2CO","12","19","19","התחשבו עוד כי מתנצלים אנחנו אליכם לא כי לפני האלהים נדבר במשיח וכל זאת חביבי למען תבנו׃ ");
INSERT INTO heb_vpl VALUES ("C212_20","077_12_20","2CO","12","20","20","כי ירא אנכי פן בבאי לא אמצא אתכם כאשר חפצתי ואתם גם אתם לא תמצאו אתי כאשר חפצתם פן יהיה בכם מצה וקנאה ורגז ומריבות ודבה רעה ורכילות וגאות ומבוכה׃ ");
INSERT INTO heb_vpl VALUES ("C212_21","077_12_21","2CO","12","21","21","פן אשוב לבוא וישפילני אלהי אצלכם ואתאבל על רבים אשר חטאו כבר ולא שבו מן הטמאה ומן הזנות ומן הזמה אשר עשו׃ ");
INSERT INTO heb_vpl VALUES ("C213_1","077_13_1","2CO","13","1","1","זאת הפעם השלישית אשר אבוא אליכם על פי שנים עדים או שלשה עדים יקום כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("C213_2","077_13_2","2CO","13","2","2","מקדם אמרתי בהיותי אצלכם בפעם השנית ומקדם אני אמר וכתב עתה ברחקי מכם לאשר חטאו לפני מזה ולכל הנשארים כי בשובי לבוא לא אחוס׃ ");
INSERT INTO heb_vpl VALUES ("C213_3","077_13_3","2CO","13","3","3","יען בקשכם לבחן את המשיח המדבר בי אשר איננו חלש לכם כי אם גבור הוא בתוככם׃ ");
INSERT INTO heb_vpl VALUES ("C213_4","077_13_4","2CO","13","4","4","כי אם גם נצלב בחלשה אכן חי הוא בגבורת אלהים ואם גם חלשים בו אנחנו אכן נחיה עמו בגבורת אלהים לנגדכם׃ ");
INSERT INTO heb_vpl VALUES ("C213_5","077_13_5","2CO","13","5","5","נסו נא אתכם אם באמונה אתם בחנו אתכם או האינכם ידעים את נפשכם כי ישוע המשיח בכם אם לא כי נמאסים אתם׃ ");
INSERT INTO heb_vpl VALUES ("C213_6","077_13_6","2CO","13","6","6","אבל אקוה כי תדעו אשר אנחנו איננו נמאסים׃ ");
INSERT INTO heb_vpl VALUES ("C213_7","077_13_7","2CO","13","7","7","ואני מתחנן אל האלהים אשר לא תעשו כל רע לא למען נראה אנחנו נאמנים כי אם למען תעשו אתם את הטוב ואנחנו נהיה כנמאסים׃ ");
INSERT INTO heb_vpl VALUES ("C213_8","077_13_8","2CO","13","8","8","כי אין אנחנו יכולים לעשות מאומה לנגד האמת כי אם בעד האמת׃ ");
INSERT INTO heb_vpl VALUES ("C213_9","077_13_9","2CO","13","9","9","כי נשמח אם חלשים אנחנו ואתם גבורים ועל זאת גם נתפלל על אשר תכוננו׃ ");
INSERT INTO heb_vpl VALUES ("C213_10","077_13_10","2CO","13","10","10","ובעבור זאת כתבתי את אלה בהיותי ברחוק למען אשר לא אצטרך בקרבי אליכם לדבר אתכם משפטים לפי הרשות אשר נתנה לי האדון לבנות ולא להרוס׃ ");
INSERT INTO heb_vpl VALUES ("C213_11","077_13_11","2CO","13","11","11","ובכן אחי שמחו והתכוננו התנחמו ויהי לכם לב אחד אהבו השלום ואלהי האהבה והשלום יהי עמכם׃ ");
INSERT INTO heb_vpl VALUES ("C213_12","077_13_12","2CO","13","12","12","31-21 שאלו לשלום איש את רעהו בנשיקה הקדושה הקדושים כלם שאלים לשלומכם׃ ");
INSERT INTO heb_vpl VALUES ("C213_13","077_13_13","2CO","13","13","13","31-21׃ ");
INSERT INTO heb_vpl VALUES ("C213_14","077_13_14","2CO","13","14","14","חסד האדון ישוע המשיח ואהבת האלהים והתחברות רוח הקדש עם כלכם אמן׃ ");
INSERT INTO heb_vpl VALUES ("GL1_1","078_1_1","GAL","1","1","1","פולוס השליח לא מבני אדם ולא על ידי בן אדם כי אם על ידי ישוע המשיח ואלהים האב אשר העירו מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("GL1_2","078_1_2","GAL","1","2","2","וכל האחים אשר עמדי אל הקהלות אשר בגלטיא׃ ");
INSERT INTO heb_vpl VALUES ("GL1_3","078_1_3","GAL","1","3","3","חסד לכם ושלום מאת האלהים אבינו ומאת אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("GL1_4","078_1_4","GAL","1","4","4","אשר נתן את נפשו בעד חטאתינו לחלצנו מן העולם הרע הזה כרצון אלהינו אבינו׃ ");
INSERT INTO heb_vpl VALUES ("GL1_5","078_1_5","GAL","1","5","5","אשר לו הכבוד לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("GL1_6","078_1_6","GAL","1","6","6","תמה אני כי סרתם מהר מאחרי הקרא אתכם בחסד המשיח אל בשורה זרה׃ ");
INSERT INTO heb_vpl VALUES ("GL1_7","078_1_7","GAL","1","7","7","והיא איננה אחרת רק שיש אנשים העכרים אתכם וחפצים להפך את בשורת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("GL1_8","078_1_8","GAL","1","8","8","אבל גם אנחנו או מלאך מן השמים אם יבוא לבשר אתכם בשורה מבלעדי זאת אשר בשרנו אתכם חרם יהיה׃ ");
INSERT INTO heb_vpl VALUES ("GL1_9","078_1_9","GAL","1","9","9","כמו שאמרנו כבר כן אמר עתה עוד הפעם איש כי יבשר אתכם בשורה מבלעדי אשר קבלתם חרם יהיה׃ ");
INSERT INTO heb_vpl VALUES ("GL1_10","078_1_10","GAL","1","10","10","ועתה המתרצה אנכי אל בני אדם אם אל האלהים או המבקש אנכי למצא חן בעיני בני אדם כי במצאי חן בעיני בני אדם לא אהיה עוד עבד המשיח׃ ");
INSERT INTO heb_vpl VALUES ("GL1_11","078_1_11","GAL","1","11","11","אבל מודיע אני אתכם אחי כי הבשורה אשר בשרתי לא לפי דרך אדם היא׃ ");
INSERT INTO heb_vpl VALUES ("GL1_12","078_1_12","GAL","1","12","12","כי גם אנכי לא קבלתיה מאדם ולא למדוני אתה כי אם בחזיון ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("GL1_13","078_1_13","GAL","1","13","13","כי הלא שמעתם את דרכי אשר התהלכתי מלפנים בין היהודים ואת אשר רדפתי על יתר את עדת אלהים ואבדתיה׃ ");
INSERT INTO heb_vpl VALUES ("GL1_14","078_1_14","GAL","1","14","14","ואהי הולך וחזק בדת היהודית על רבים מבני גילי בעמי בקנאתי הגדולה לקבלות אבותי׃ ");
INSERT INTO heb_vpl VALUES ("GL1_15","078_1_15","GAL","1","15","15","אך כאשר היה רצון האלהים אשר הבדיל אתי מרחם אמי ויקראני בחסדו׃ ");
INSERT INTO heb_vpl VALUES ("GL1_16","078_1_16","GAL","1","16","16","לגלות בי את בנו שאבשרנו בגוים מיד לא נועצתי עם בשר ודם׃ ");
INSERT INTO heb_vpl VALUES ("GL1_17","078_1_17","GAL","1","17","17","גם לא עליתי ירושלים אל אשר היו שליחים לפני כי אם הלכתי לערב ומשם שבתי אל דמשק׃ ");
INSERT INTO heb_vpl VALUES ("GL1_18","078_1_18","GAL","1","18","18","אחרי כן מקץ שלש שנים עליתי ירושלים לראות את כיפא ואשב עמו חמשה עשר יום׃ ");
INSERT INTO heb_vpl VALUES ("GL1_19","078_1_19","GAL","1","19","19","ואחר מן השליחים לא ראיתי זולתי את יעקב אחי אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("GL1_20","078_1_20","GAL","1","20","20","ואשר אני כתב אליכם הנה נגד האלהים כי לא אכזב׃ ");
INSERT INTO heb_vpl VALUES ("GL1_21","078_1_21","GAL","1","21","21","אחרי כן באתי אל גלילות סוריא וקיליקיא׃ ");
INSERT INTO heb_vpl VALUES ("GL1_22","078_1_22","GAL","1","22","22","אבל קהלות יהודה אשר במשיח הנה לא ידעו את פני׃ ");
INSERT INTO heb_vpl VALUES ("GL1_23","078_1_23","GAL","1","23","23","רק זאת בלבד שמעו כי האיש ההוא אשר היה רדף אתנו מאז עתה הוא מבשר את האמונה אשר האבידה מלפנים׃ ");
INSERT INTO heb_vpl VALUES ("GL1_24","078_1_24","GAL","1","24","24","ויהללו בי את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("GL2_1","078_2_1","GAL","2","1","1","אחרי כן מקץ ארבע עשרה שנה שבתי ועליתי לירושלים עם בר נבא ואקח אתי גם את טיטוס׃ ");
INSERT INTO heb_vpl VALUES ("GL2_2","078_2_2","GAL","2","2","2","ואעל שמה על פי מחזה ואשים לפניהם את הבשורה אשר קראתי בגוים וביחוד שמתיה לפני החשובים שבהם פן תהיה לריק מרוצתי אשר ארוץ או רצתי׃ ");
INSERT INTO heb_vpl VALUES ("GL2_3","078_2_3","GAL","2","3","3","אבל גם טיטוס אשר אתי אף כי יוני הוא לא הכרח להמול׃ ");
INSERT INTO heb_vpl VALUES ("GL2_4","078_2_4","GAL","2","4","4","מפני אחי השקר הנכנסים בסתר בתוכנו אשר באו לרגל את חרותנו אשר לנו בישוע המשיח למען העבידנו׃ ");
INSERT INTO heb_vpl VALUES ("GL2_5","078_2_5","GAL","2","5","5","אשר לא סרנו למשמעתם אף לא שעה אחת למען אשר תעמד בקרבכם אמתה של הבשורה׃ ");
INSERT INTO heb_vpl VALUES ("GL2_6","078_2_6","GAL","2","6","6","ומאת הנחשבים להיות מה יהיו מי שיהיו אינני חושש לזה כי האלהים לא ישא פני איש לי לא הוסיפו החשובים מאומה׃ ");
INSERT INTO heb_vpl VALUES ("GL2_7","078_2_7","GAL","2","7","7","ותהי להפך בראותם כי הפקדה לי הבשורה אל הערלים כמו שהפקד כיפא אל המולים׃ ");
INSERT INTO heb_vpl VALUES ("GL2_8","078_2_8","GAL","2","8","8","כי הפעל בכיפא לשלחו אל המולים הוא פעל גם בי לשלחני אל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("GL2_9","078_2_9","GAL","2","9","9","וכאשר ידעו יעקב וכיפא ויוחנן הנחשבים לעמודים את החסד הנתן לי נתנו לי ולבר נבא את יד ימינם ונאות כי נלך אנחנו לגוים והמה למולים׃ ");
INSERT INTO heb_vpl VALUES ("GL2_10","078_2_10","GAL","2","10","10","רק שנזכר את האביונים אשר גם שקדתי לעשותה׃ ");
INSERT INTO heb_vpl VALUES ("GL2_11","078_2_11","GAL","2","11","11","וכאשר בא כיפא לאנטיוכיא הוכחתי אל פניו דרכו מפני שהיה בו אשם׃ ");
INSERT INTO heb_vpl VALUES ("GL2_12","078_2_12","GAL","2","12","12","כי לפני בא אנשים מאת יעקב היה אכל עם הגוים יחדו וכבאם היה מתרחק ופורש מהם מיראתו את בני המילה׃ ");
INSERT INTO heb_vpl VALUES ("GL2_13","078_2_13","GAL","2","13","13","ויכחשו עמו גם שאר היהודים עד כי בר נבא גם הוא נדח אחרי כחשם׃ ");
INSERT INTO heb_vpl VALUES ("GL2_14","078_2_14","GAL","2","14","14","אכן בראותו את אשר לא ישרו לכת כאמתה של הבשורה אמרתי אל כיפא בפני כל אם אתה היהודי תתנהג כנכרי ולא כיהודי למה תכריח את הגוים להתנהג כיהודים׃ ");
INSERT INTO heb_vpl VALUES ("GL2_15","078_2_15","GAL","2","15","15","הן מזרע היהודים אנחנו ולא חטאים מן הגוים׃ ");
INSERT INTO heb_vpl VALUES ("GL2_16","078_2_16","GAL","2","16","16","ומדעתנו כי לא יצדק אדם מתוך מעשי התורה כי אם באמונת ישוע המשיח גם אנחנו האמנו במשיח ישוע למען נצדק מאמונת המשיח ולא ממעשי התורה כי ממעשי התורה לא יצדק כל בשר׃ ");
INSERT INTO heb_vpl VALUES ("GL2_17","078_2_17","GAL","2","17","17","ואם בבקשנו להצדק במשיח נמצא גם אנחנו חטאים הנה המשיח משרת החטא חלילה׃ ");
INSERT INTO heb_vpl VALUES ("GL2_18","078_2_18","GAL","2","18","18","כי אם אשוב ואבנה את מה שסתרתי אני עשה את עצמי פשע׃ ");
INSERT INTO heb_vpl VALUES ("GL2_19","078_2_19","GAL","2","19","19","כי מתי אני לתורה על ידי התורה למען אחיה לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("GL2_20","078_2_20","GAL","2","20","20","עם המשיח נצלבתי ואין עוד אנכי החי כי אם המשיח הוא חי בקרבי ואשר אני חי עתה בבשר אחיה באמונת בן אלהים אשר אהבני ויתן את נפשו בעדי׃ ");
INSERT INTO heb_vpl VALUES ("GL2_21","078_2_21","GAL","2","21","21","לא אמאס את חסד האלהים כי אלו תהיה על ידי התורה צדקה הנה חנם מת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("GL3_1","078_3_1","GAL","3","1","1","אהה גלטים חסרי דעת מי התעה אתכם בכשפיו משמע את האמת אחרי אשר ציר בתוככם ישוע המשיח הצלוב לנגד עיניכם׃ ");
INSERT INTO heb_vpl VALUES ("GL3_2","078_3_2","GAL","3","2","2","זאת לבד חפצתי ללמד מכם האם ממעשי התורה קבלתם את הרוח או משמועת האמונה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_3","078_3_3","GAL","3","3","3","האתם סכלים כל כך אשר החלותם ברוח ועתה תכלו בבשר׃ ");
INSERT INTO heb_vpl VALUES ("GL3_4","078_3_4","GAL","3","4","4","הכזאת סבלתם לריק אם אמנם אך לריק׃ ");
INSERT INTO heb_vpl VALUES ("GL3_5","078_3_5","GAL","3","5","5","הנה המפיק לכם את הרוח ופעל בכם גבורות הכי ממעשי התורה הוא עשה אלה או משמועת האמונה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_6","078_3_6","GAL","3","6","6","כאשר האמין אברהם באלהים ותחשב לו לצדקה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_7","078_3_7","GAL","3","7","7","דעו אפוא כי בני האמונה בני אברהם המה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_8","078_3_8","GAL","3","8","8","והמקרא בראתו מראש כי האלהים יצדיק את הגוים מתוך האמונה קדם לבשר את אברהם לאמר ונברכו בך כל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("GL3_9","078_3_9","GAL","3","9","9","על כן בני האמונה יתברכו עם אברהם המאמין׃ ");
INSERT INTO heb_vpl VALUES ("GL3_10","078_3_10","GAL","3","10","10","כי בני מעשי התורה תחת הקללה המה שנאמר ארור אשר לא יקים את כל הדברים הכתובים בספר התורה לעשות אותם׃ ");
INSERT INTO heb_vpl VALUES ("GL3_11","078_3_11","GAL","3","11","11","וגלוי הוא כי על ידי התורה לא יצדק האדם לפני האלהים כי צדיק באמונתו יחיה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_12","078_3_12","GAL","3","12","12","והתורה איננה מן האמונה כי אם אשר יעשה אתם האדם וחי בהם׃ ");
INSERT INTO heb_vpl VALUES ("GL3_13","078_3_13","GAL","3","13","13","המשיח פדנו מקללת התורה בהיותו לקללה בעדנו שנאמר קללת אלהים תלוי׃ ");
INSERT INTO heb_vpl VALUES ("GL3_14","078_3_14","GAL","3","14","14","למען אשר תבא ברכת אברהם במשיח ישוע על הגוים למען אשר נשא את הבטחת הרוח על ידי האמונה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_15","078_3_15","GAL","3","15","15","אחי לפי דרך אדם אדבר אפלו דיתיקי של בן אדם אם מקימת היא לא יפרנה איש גם לא יוסיף עליה דבר׃ ");
INSERT INTO heb_vpl VALUES ("GL3_16","078_3_16","GAL","3","16","16","והנה לאברהם נאמרו ההבטחות ולזרעו ולא אמר ולזרעיך כאלו לרבים אלא כאלו ליחיד ולזרעך והוא המשיח׃ ");
INSERT INTO heb_vpl VALUES ("GL3_17","078_3_17","GAL","3","17","17","וזאת אני אמר כי דיתיקי אשר קימה האלהים מאז לימות המשיח לא תוכל התורה אשר באה אחרי ארבע מאות ושלשים שנה להפר אותה ולבטל את ההבטחה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_18","078_3_18","GAL","3","18","18","כי אם תבוא הנחלה מתוך התורה לא תבוא עוד מתוך ההבטחה אבל את אברהם חנן האלהים על ידי הבטחה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_19","078_3_19","GAL","3","19","19","אם כן התורה מה היא מפני הפשעים נוספה עד כי יבוא הזרע אשר לו ההבטחה ותושם התורה על ידי המלאכים וביד סרסר׃ ");
INSERT INTO heb_vpl VALUES ("GL3_20","078_3_20","GAL","3","20","20","והסרסר לא של אחד הוא אך האלהים הוא אחד׃ ");
INSERT INTO heb_vpl VALUES ("GL3_21","078_3_21","GAL","3","21","21","ועתה הכי התורה סתרת את הבטחות האלהים חלילה כי אלו נתנה תורה אשר בכחה להחיות אז באמת היתה הצדקה על ידי התורה׃ ");
