INSERT INTO heb_vpl VALUES ("GL3_23","078_3_23","GAL","3","23","23","לפני בוא האמונה היינו סגורים ונשמרים תחת התורה אלי האמונה העתידה להגלות׃ ");
INSERT INTO heb_vpl VALUES ("GL3_24","078_3_24","GAL","3","24","24","ובכן התורה היתה אמנת אותנו אל המשיח למען נצדק על ידי האמונה׃ ");
INSERT INTO heb_vpl VALUES ("GL3_25","078_3_25","GAL","3","25","25","אבל עתה אחרי אשר באה האמונה אין אנחנו עוד תחת יד האמן׃ ");
