INSERT INTO heb_vpl VALUES ("PP2_30","080_2_30","PHP","2","30","30","כי בעבור מעשה המשיח הגיע עד מות ותקל נפשו בעיניו למען ימלא את אשר חסרתם בשרתכם אותי׃ ");
