INSERT INTO heb_vpl VALUES ("PP3_2","080_3_2","PHP","3","2","2","הזהרו מן הכלבים הזהרו מן הפעלים הרעים הזהרו מן החתוך׃ ");
INSERT INTO heb_vpl VALUES ("PP3_3","080_3_3","PHP","3","3","3","כי אנחנו בני המילה העבדים את האלהים ברוח ומתפארים במשיח ישוע ואיננו בטחים בבשר׃ ");
INSERT INTO heb_vpl VALUES ("PP3_4","080_3_4","PHP","3","4","4","אף כי גם לי יש לבטח בבשר ואם יחשב איש שיוכל לבטח בבשר הנה אני יותר ממנו׃ ");
INSERT INTO heb_vpl VALUES ("PP3_5","080_3_5","PHP","3","5","5","אשר אני נמול בן שמונת ימים מבני ישראל משבט בנימין עברי מן העברים׃ ");
INSERT INTO heb_vpl VALUES ("PP3_6","080_3_6","PHP","3","6","6","לפי התורה פרוש בקנאתי רדף את העדה ולפי צדקת התורה בלי שמץ׃ ");
INSERT INTO heb_vpl VALUES ("PP3_7","080_3_7","PHP","3","7","7","אך היתרנות האלה כלן חשבתי לי לחסרנות למען המשיח׃ ");
