INSERT INTO heb_vpl VALUES ("PP3_9","080_3_9","PHP","3","9","9","ולא תהיה לי צדקתי מתוך התורה כי אם באמונת המשיח הצדקה הבאה מאת האלהים באמונה׃ ");
INSERT INTO heb_vpl VALUES ("PP3_10","080_3_10","PHP","3","10","10","לדעת אתו ואת גבורת תחיתו והתחברות ענוייו ולהדמות למותו׃ ");
