INSERT INTO heb_vpl VALUES ("PP3_12","080_3_12","PHP","3","12","12","לא כאלו השגתי כבר או כאלו השלמתי אבל ארדף אולי אשיג כאשר גם השיגני המשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("PP3_13","080_3_13","PHP","3","13","13","אחי אינני חשב כי כבר השגתי אך אחת דברתי כי שכח אני את אשר מאחרי ואשתטח אל אשר לפני׃ ");
