INSERT INTO heb_vpl VALUES ("PP3_18","080_3_18","PHP","3","18","18","כי רבים המתהלכים כן כאשר אנחנו מופת לכם׃ ");
INSERT INTO heb_vpl VALUES ("PP3_19","080_3_19","PHP","3","19","19","כי רבים המתהלכים אשר עליהם אמרתי לכם פעמים הרבה ועתה גם בבכי אני אמר כי הם איבי צלב המשיח׃ ");
INSERT INTO heb_vpl VALUES ("PP3_20","080_3_20","PHP","3","20","20","אשר אחריתם האבדון אשר כרסם אלהיהם וכבודם בבשתם וקרבם הבלי חלד׃ ");
INSERT INTO heb_vpl VALUES ("PP3_21","080_3_21","PHP","3","21","21","כי אזרחותנו בשמים היא ומשם מחכים אנחנו למושיענו אדנינו ישוע המשיח׃  (Philippians 3:22) אשר יחליף את גוף שפלותנו להיותו דומה לגוף כבודו כפי כח יכלתו לכבש הכל תחתיו׃  ");
INSERT INTO heb_vpl VALUES ("PP4_1","080_4_1","PHP","4","1","1","ועתה אחי החביבים והחמודים שמחתי ועטרת ראשי עמדו נא כן באדנינו חביבי׃ ");
INSERT INTO heb_vpl VALUES ("PP4_2","080_4_2","PHP","4","2","2","את אבהודיה אני מזהיר ואת סונטיכי אני מזהיר להיות לב אחד באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("PP4_3","080_4_3","PHP","4","3","3","ואתה חברי הנצמד לי באמת אף ממך אני מבקש להיות להן לעזר אשר יגעו עמדי על הבשורה עם קלימיס ועם שאר תמכי אשר שמותם יחד בספר החיים׃ ");
INSERT INTO heb_vpl VALUES ("PP4_4","080_4_4","PHP","4","4","4","שמחו באדנינו בכל עת ועוד הפעם אמר אני שמחו׃ ");
