INSERT INTO heb_vpl VALUES ("PP4_6","080_4_6","PHP","4","6","6","אל תדאגו כי אם בתפלה ובתחנונים עם תודה תודיעו בכל דבר את משאלותיכם לאלהינו׃ ");
INSERT INTO heb_vpl VALUES ("PP4_7","080_4_7","PHP","4","7","7","ושלום אלהים הנשגב מכל שכל ינצר את לבבכם ואת מחשבותיכם במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("PP4_8","080_4_8","PHP","4","8","8","ובכן אחי כל אשר הוא אמת ונכבד וישר וטהור ונעים ואשר שמעו טוב כל מעשה צדק כל מעשה שבח על אלה תשימו לבבכם׃ ");
