INSERT INTO heb_vpl VALUES ("PP4_17","080_4_17","PHP","4","17","17","לא שאבקש את המתן אך אבקש הפרי אשר ירבה בחשבנכם׃ ");
INSERT INTO heb_vpl VALUES ("PP4_18","080_4_18","PHP","4","18","18","ואני קבלתי את הכל ויש לי די והותר ואני נמלאתי ריח ניחח בקבלי מידי אפפרודיטוס את כל אשר שלחתם זבח ערב ורצוי לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("PP4_19","080_4_19","PHP","4","19","19","ואלהי הוא ימלא את כל צרככם כעשר כבודו במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("PP4_20","080_4_20","PHP","4","20","20","ולאלהים אבינו הכבוד לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("PP4_21","080_4_21","PHP","4","21","21","שאלו לשלום כל קדוש במשיח ישוע האחים אשר עמדי שאלים לשלומכם׃ ");
INSERT INTO heb_vpl VALUES ("PP4_22","080_4_22","PHP","4","22","22","כל הקדשים שאלים לשלומכם וביותר אלה אשר מבית הקיסר׃ ");
INSERT INTO heb_vpl VALUES ("PP4_23","080_4_23","PHP","4","23","23","חסד ישוע המשיח אדנינו עם כלכם אמן׃ ");
INSERT INTO heb_vpl VALUES ("CL1_1","081_1_1","COL","1","1","1","פולוס שליח ישוע המשיח ברצון אלהים וטימותיוס אחינו׃ ");
INSERT INTO heb_vpl VALUES ("CL1_2","081_1_2","COL","1","2","2","אל הקדשים והאחים הנאמנים במשיח אשר הם בקולשא חסד לכם ושלום מאת האלהים אבינו ואדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("CL1_3","081_1_3","COL","1","3","3","נודה לאלהים אבי אדנינו ישוע המשיח בכל עת אשר אנחנו מתפללים בעדכם׃ ");
INSERT INTO heb_vpl VALUES ("CL1_4","081_1_4","COL","1","4","4","אחרי אשר שמענו אמונתכם במשיח ישוע ואהבתכם אל כל הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("CL1_5","081_1_5","COL","1","5","5","בעבור התקוה הצפונה לכם בשמים ונודעתם לכם מקדם בדבר אמת הבשורה׃ ");
INSERT INTO heb_vpl VALUES ("CL1_6","081_1_6","COL","1","6","6","אשר באה אליכם וגם לכל העולם ותפרה ותרבה כמו גם בתוככם למן היום אשר שמעתם והכרתם באמת את חסד אלהים׃ ");
INSERT INTO heb_vpl VALUES ("CL1_7","081_1_7","COL","1","7","7","כאשר למדתם מן אפפרס חברנו החביב אשר הוא משרת נאמן בעדכם למשיח׃ ");
INSERT INTO heb_vpl VALUES ("CL1_8","081_1_8","COL","1","8","8","והוא גם הודיע אתנו את האבתכם ברוח׃ ");
INSERT INTO heb_vpl VALUES ("CL1_9","081_1_9","COL","1","9","9","בעבור זאת גם אנחנו למן היום אשר שמענוה לא חדלנו להתפלל בעדכם ולבקש שתמלאו דעת רצון האלהים בכל חכמה ותבונה רוחנית׃ ");
INSERT INTO heb_vpl VALUES ("CL1_10","081_1_10","COL","1","10","10","להתהלך כטוב בעיני האדון וככל רצונו ולעשות פרי בכל מעשה טוב ולרבות בדעת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("CL1_11","081_1_11","COL","1","11","11","להתחזק בכל כח כגבורת כבודו לכל סבלנות וארך רוח עם שמחה׃ ");
INSERT INTO heb_vpl VALUES ("CL1_12","081_1_12","COL","1","12","12","ולתת תודה לאבינו העשה אתנו ראוים לחלק נחלת הקדשים באור׃ ");
INSERT INTO heb_vpl VALUES ("CL1_13","081_1_13","COL","1","13","13","אשר הוא חלצנו מממשלת החשך והעבירנו למלכות בן אהבתו׃ ");
INSERT INTO heb_vpl VALUES ("CL1_14","081_1_14","COL","1","14","14","אשר יש לנו בו הפדיון בדמו סליחת החטאים׃ ");
INSERT INTO heb_vpl VALUES ("CL1_15","081_1_15","COL","1","15","15","והוא צלם האלהים הנעלם ובכור כל נברא׃ ");
INSERT INTO heb_vpl VALUES ("CL1_16","081_1_16","COL","1","16","16","כי בו נברא כל אשר בשמים ואשר בארץ כל הנראה וכל אשר איננו נראה הן כסאות וממשלות הן שררות ורשיות הכל נברא על ידי ולמענהו׃ ");
INSERT INTO heb_vpl VALUES ("CL1_17","081_1_17","COL","1","17","17","והוא לפני הכל והכל קים בו׃ ");
INSERT INTO heb_vpl VALUES ("CL1_18","081_1_18","COL","1","18","18","והוא ראש גוף העדה אשר הוא ראשית ובכור מעם המתים למען יהיה הראשון בכל׃ ");
INSERT INTO heb_vpl VALUES ("CL1_19","081_1_19","COL","1","19","19","כי כן היה הרצון לשכן בו את כל המלוא׃ ");
INSERT INTO heb_vpl VALUES ("CL1_20","081_1_20","COL","1","20","20","ולרצות אל עצמו את הכל על ידו בעשותו שלום בדם צלבו על ידו הן אשר בארץ הן אשר בשמים׃ ");
INSERT INTO heb_vpl VALUES ("CL1_21","081_1_21","COL","1","21","21","וגם אתם אשר הייתם מלפנים מוזרים ואיבים בנטות לבבכם אחרי המעשים הרעים׃ ");
INSERT INTO heb_vpl VALUES ("CL1_22","081_1_22","COL","1","22","22","עתה רצה אתכם בגוף בשרו על ידי מותו להעמידכם לפניו קדשים ובלי מום ודפי׃ ");
INSERT INTO heb_vpl VALUES ("CL1_23","081_1_23","COL","1","23","23","אם תעמדו מיסדים ונכונים באמונה ולא תזועו מתוחלת הבשורה אשר שמעתם ואשר נשמעה לכל הנברא תחת השמים ואני פולוס הייתי לה למשרת׃ ");
INSERT INTO heb_vpl VALUES ("CL1_24","081_1_24","COL","1","24","24","עתה הנני שמח בענויי אשר אני סבל למענכם ואמלא את החסר ביסורי המשיח בבשרי בעד גופו היא העדה׃ ");
INSERT INTO heb_vpl VALUES ("CL1_25","081_1_25","COL","1","25","25","אשר הייתי לה למשרת כפי פקדת אלהים אשר נתנה לי עליכם למלאת את דבר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("CL1_26","081_1_26","COL","1","26","26","את הסוד אשר היה נסתר מעולמים ומדור ודור ועתה נגלה לקדושיו׃ ");
INSERT INTO heb_vpl VALUES ("CL1_27","081_1_27","COL","1","27","27","אשר רצה האלהים להודיעם אי זה הוא עשר כבוד הסוד ההוא בגוים והוא המשיח אשר בכם אשר הוא תקות הכבוד׃ ");
INSERT INTO heb_vpl VALUES ("CL1_28","081_1_28","COL","1","28","28","ואותו משמיעים אנחנו בהוכיחנו כל איש ובלמדנו כל איש בכל חכמה למען העמיד כל איש שלם במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("CL1_29","081_1_29","COL","1","29","29","ובזאת אף אני עמל ונלחם כפי פעלת כחו הפעל בי בגבורה׃ ");
INSERT INTO heb_vpl VALUES ("CL2_1","081_2_1","COL","2","1","1","הנני מודיע אתכם גדל הקרב אשר בקרבי על אדותיכם ועל אדות אנשי לודקיא ועל כל אשר לא ראו את פני בבשר׃ ");
INSERT INTO heb_vpl VALUES ("CL2_2","081_2_2","COL","2","2","2","למען ינחמו לבותם ונקשרו יחד באהבה ולכל עשר דעת נכונה להשכיל סוד האלהים אבינו וסוד המשיח׃ ");
INSERT INTO heb_vpl VALUES ("CL2_3","081_2_3","COL","2","3","3","אשר צפונים בו כל אצרות החכמה והדעת׃ ");
INSERT INTO heb_vpl VALUES ("CL2_4","081_2_4","COL","2","4","4","וזאת אמר אני לכם למען אשר לא יטעה אתכם איש בשפתי חלקות׃ ");
INSERT INTO heb_vpl VALUES ("CL2_5","081_2_5","COL","2","5","5","כי גם אם בבשרי אני רחוק מכם הנה ברוחי אני אצלכם ואשמח בראתי את תכונתכם ואמץ אמונתכם במשיח׃ ");
INSERT INTO heb_vpl VALUES ("CL2_6","081_2_6","COL","2","6","6","לכן כאשר קבלתם את המשיח את ישוע אדנינו כן גם התהלכו בו׃ ");
INSERT INTO heb_vpl VALUES ("CL2_7","081_2_7","COL","2","7","7","משרשים ונבנים בו וקימים באמונה כאשר למדתם ומרבים בתודה בה׃ ");
INSERT INTO heb_vpl VALUES ("CL2_8","081_2_8","COL","2","8","8","הזהרו פן יוליך איש אתכם שולל בפילסופיה ובמדוחי שוא לפי קבלת בני האדם ויסדות העולם ולא על פי המשיח׃ ");
INSERT INTO heb_vpl VALUES ("CL2_9","081_2_9","COL","2","9","9","כי בו בגופו שכן כל מלא האלהות ובו אתם נמלאים׃ ");
INSERT INTO heb_vpl VALUES ("CL2_10","081_2_10","COL","2","10","10","אשר הוא ראש כל שררה ושלטן׃ ");
INSERT INTO heb_vpl VALUES ("CL2_11","081_2_11","COL","2","11","11","ובו אתם גם נמולים מילה שלא בידים בהפשטת גוף הבשר החוטא היא מילת המשיח׃ ");
INSERT INTO heb_vpl VALUES ("CL2_12","081_2_12","COL","2","12","12","כי נקברתם אתו בטבילה אף קמתם אתו בתחיה על ידי האמונה בגבורת אלהים אשר העירו מן המתים׃ ");
INSERT INTO heb_vpl VALUES ("CL2_13","081_2_13","COL","2","13","13","גם אתכם המתים בפשעים ובערלת בשרכם החיה אתו בסלח לכם את כל פשעיכם׃ ");
INSERT INTO heb_vpl VALUES ("CL2_14","081_2_14","COL","2","14","14","וימחק את השטר המעיד בנו בחקתיו אשר היה לנגדנו וישאהו מתוכנו ויתקעהו בצלב׃ ");
INSERT INTO heb_vpl VALUES ("CL2_15","081_2_15","COL","2","15","15","ויפשט את השרים והשליטים ויתנם ביד רמה לראוה בם ויוליכם שולל בנפשו׃ ");
INSERT INTO heb_vpl VALUES ("CL2_16","081_2_16","COL","2","16","16","על כן לא ידין איש אתכם על דבר מאכל ומשקה או בענין המועדים וראשי חדשים ושבתות׃ ");
INSERT INTO heb_vpl VALUES ("CL2_17","081_2_17","COL","2","17","17","אשר הם צל הדברים העתידים לבא וגופם הוא במשיח׃ ");
INSERT INTO heb_vpl VALUES ("CL2_18","081_2_18","COL","2","18","18","אל תתנו לאיש לעקב אתכם על ידי שפלות רוח ועבודה מלאכים המהלך בדברים אשר לא ראו עיניו ומלא רוח גאוה על לא דבר משכל בשרו׃ ");
INSERT INTO heb_vpl VALUES ("CL2_19","081_2_19","COL","2","19","19","ואיננו אחז בראש אשר מחבר ממנו כל הגוף ומאחז בציריו ודבקיו יגדל גדול אלהים׃ ");
INSERT INTO heb_vpl VALUES ("CL2_20","081_2_20","COL","2","20","20","לכן אם מתם עם המשיח ליסודת העולם למה תשתעבדו לחקים כאלו עדכם חיים בעולם׃ ");
INSERT INTO heb_vpl VALUES ("CL2_21","081_2_21","COL","2","21","21","אל תאחז אל תטעם אל תגע׃ ");
INSERT INTO heb_vpl VALUES ("CL2_22","081_2_22","COL","2","22","22","והם כלם לכליון בתשמישם לפי מצות אנשים ולמודיהם׃ ");
INSERT INTO heb_vpl VALUES ("CL2_23","081_2_23","COL","2","23","23","הנראים כעין חכמה בעבודה בדויה מלב ובשפלות רוח ובענוי הגוף שלא כהגן רק להשביע הבשר׃ ");
INSERT INTO heb_vpl VALUES ("CL3_1","081_3_1","COL","3","1","1","לכן אם קמתם עם המשיח בקשו את אשר למעלה אשר המשיח ישב שם לימין האלהים׃ ");
INSERT INTO heb_vpl VALUES ("CL3_2","081_3_2","COL","3","2","2","את אשר למעלה יהגה לבבכם לא את אשר בארץ׃ ");
INSERT INTO heb_vpl VALUES ("CL3_3","081_3_3","COL","3","3","3","כי מתם וחייכם צפונים עם המשיח באלהים׃ ");
INSERT INTO heb_vpl VALUES ("CL3_4","081_3_4","COL","3","4","4","בעת הגלות המשיח אשר הוא חייכם גם אתם תגלו עמו בכבוד׃ ");
INSERT INTO heb_vpl VALUES ("CL3_5","081_3_5","COL","3","5","5","על כן תמותתו את אבריכם בארץ את הזנות והטמאה והזמה והתאות הרעות ונטות אחרי הבצע אשר היא עבודת אלילים׃ ");
INSERT INTO heb_vpl VALUES ("CL3_6","081_3_6","COL","3","6","6","כי בגלל אלה בא חרון אלהים על בני חמרי׃ ");
INSERT INTO heb_vpl VALUES ("CL3_7","081_3_7","COL","3","7","7","אשר גם אתם הלכתם בהם מלפנים בחיותכם בתוכם׃ ");
INSERT INTO heb_vpl VALUES ("CL3_8","081_3_8","COL","3","8","8","אך עתה הסירו מכם כל אלה את הרגז את הכעס את הרשע את הגדוף ואת דברי נבלה מפיכם׃ ");
INSERT INTO heb_vpl VALUES ("CL3_9","081_3_9","COL","3","9","9","ואל תשקרו איש בעמיתו כי פשטתם את האדם הישן עם פעלותיו׃ ");
INSERT INTO heb_vpl VALUES ("CL3_10","081_3_10","COL","3","10","10","ולבשתם את האדם החדש המתחדש בדעת כצלם בראו׃ ");
INSERT INTO heb_vpl VALUES ("CL3_11","081_3_11","COL","3","11","11","אשר אין שם יוני ויהודי אין מילה וערלה אין לעז וסקותי אין עבד ובן חורין כי המשיח הוא הכל ובכל׃ ");
INSERT INTO heb_vpl VALUES ("CL3_12","081_3_12","COL","3","12","12","לכן אתם כבחירי האלהים הקדשים והחביבים לבשו המון רחמים ונדיבות ונמיכות רוח וענוה וארך אפים׃ ");
INSERT INTO heb_vpl VALUES ("CL3_13","081_3_13","COL","3","13","13","ותשאו איש את רעהו ותסלחו בהיות לכם ריב איש עם אחיו כאשר המשיח סלח לכם כן תסלחו גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("CL3_14","081_3_14","COL","3","14","14","ועל כל אלה לבשו האהבה היא אגדת השלמות׃ ");
INSERT INTO heb_vpl VALUES ("CL3_15","081_3_15","COL","3","15","15","וישלט בלבבכם שלום האלהים אשר נקראתם לו בגוף אחד וזבחו תודה׃ ");
INSERT INTO heb_vpl VALUES ("CL3_16","081_3_16","COL","3","16","16","דבר האדון ישכן בקרבכם בשפע רב בכל חכמה ותלמדו ותעוררו את נפשכם בתהלות ותשבחות ושירות רוחניות ושירו ליהוה בנעימה בלבבכם׃ ");
INSERT INTO heb_vpl VALUES ("CL3_17","081_3_17","COL","3","17","17","וכל אשר תעשו הן במלין הן בפעל עשו בשם האדון ישוע והודו לאלהים אבינו על ידי׃ ");
INSERT INTO heb_vpl VALUES ("CL3_18","081_3_18","COL","3","18","18","אתן הנשים הכנענה לבעליכן כראוי באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("CL3_19","081_3_19","COL","3","19","19","אתם האנשים אהבו את נשיכם ואל תתמרמרו אליהן׃ ");
INSERT INTO heb_vpl VALUES ("CL3_20","081_3_20","COL","3","20","20","הבנים שמעו אל ילדיכם בכל דבר כי הוא לרצון לאדנינו׃ ");
INSERT INTO heb_vpl VALUES ("CL3_21","081_3_21","COL","3","21","21","האבות אל תרגיזו את בניכם פן יחתו׃ ");
INSERT INTO heb_vpl VALUES ("CL3_22","081_3_22","COL","3","22","22","העבדים שמעו בכל דבר אל אדניכם לפי הבשר לא בעבודה למראה העין כמבקשי חן בני אדם כי אם בתם לבב כיראי האלהים׃ ");
INSERT INTO heb_vpl VALUES ("CL3_23","081_3_23","COL","3","23","23","כל אשר תעשו עשו בכל נפשכם כמו ליהוה ולא לבני אדם׃ ");
INSERT INTO heb_vpl VALUES ("CL3_24","081_3_24","COL","3","24","24","וידעתם כי תקבלו מאת יהוה גמול הירשה כי את אדנינו המשיח עבדים אתם׃ ");
INSERT INTO heb_vpl VALUES ("CL3_25","081_3_25","COL","3","25","25","וכל עשה עול הוא ישא העול אשר עשה ואין שם משא פנים׃ ");
INSERT INTO heb_vpl VALUES ("CL4_1","081_4_1","COL","4","1","1","אתם האדנים תנו לעבדיכם הישר והשוה ודעו כי גם אתם יש לכם אדון בשמים׃ ");
INSERT INTO heb_vpl VALUES ("CL4_2","081_4_2","COL","4","2","2","התמידו בתפלה ושקדו בה בתודה׃ ");
INSERT INTO heb_vpl VALUES ("CL4_3","081_4_3","COL","4","3","3","והתפללו גם בעדנו למען יפתח לנו האלהים את שער הדבור לחות את סוד המשיח אשר בעבורו אסור אנכי׃ ");
INSERT INTO heb_vpl VALUES ("CL4_4","081_4_4","COL","4","4","4","למען אשר אגלה אתו כמשפט עלי לחות׃ ");
INSERT INTO heb_vpl VALUES ("CL4_5","081_4_5","COL","4","5","5","התהלכו בחכמה עם אשר בחוץ והוקירו את העת׃ ");
INSERT INTO heb_vpl VALUES ("CL4_6","081_4_6","COL","4","6","6","דבריכם יהיו נעימים בכל עת וממלחים במלח למען תדעו להשיב דבר לכל אדם׃ ");
INSERT INTO heb_vpl VALUES ("CL4_7","081_4_7","COL","4","7","7","את כל הקרת אותי וידיעכם טוכיקוס האח החביב והמשרת הנאמן ועבד עמיתי באדון׃ ");
INSERT INTO heb_vpl VALUES ("CL4_8","081_4_8","COL","4","8","8","אשר לזאת שלחתיהו אליכם למען ידע את דבריכם וינחם את לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("CL4_9","081_4_9","COL","4","9","9","עם אוניסימוס האח הנאמן והחביב אשר הוא מכם המה יודיעו אתכם את כל דברינו פה׃ ");
INSERT INTO heb_vpl VALUES ("CL4_10","081_4_10","COL","4","10","10","ארסטרכוס השבוי עמי יחד שאל לשלומכם ומרקוס בן אחות בר נבא אשר צויתם עליו אם יבוא אליכם תקבלהו׃ ");
INSERT INTO heb_vpl VALUES ("CL4_11","081_4_11","COL","4","11","11","וישוע הנקרא יוסטוס אשר הם מן המולים אלה לבדם מן העזרים למלכות האלהים היו לי לנחמה׃ ");
INSERT INTO heb_vpl VALUES ("CL4_12","081_4_12","COL","4","12","12","אפפרס אשר הוא מכם שאל לשלומכם משרת המשיח הנאבק בעדכם בתפלתיו בכל עת למען תעמדו שלמים ומלאים דעת בכל רצון אלהים׃ ");
INSERT INTO heb_vpl VALUES ("CL4_13","081_4_13","COL","4","13","13","כי מעיד אני עליו כי קנאה גדולה הוא מקנא לכם ולאנשי לודקיא ולאנשי הירפוליס׃ ");
INSERT INTO heb_vpl VALUES ("CL4_14","081_4_14","COL","4","14","14","לוקס הרופא החביב ודימס שאלים לשלומכם׃ ");
INSERT INTO heb_vpl VALUES ("CL4_15","081_4_15","COL","4","15","15","שאלו לשלום האחים אשר בלודקיא ולשלום נומפס והקהלה אשר בביתו׃ ");
INSERT INTO heb_vpl VALUES ("CL4_16","081_4_16","COL","4","16","16","ואחרי קראם את האגרת הזאת לפניכם עשו שתקרא גם בקהל לודקיים ואת אשר ללודקיא תקראוה גם אתם׃ ");
INSERT INTO heb_vpl VALUES ("CL4_17","081_4_17","COL","4","17","17","ואמרו אל ארכפוס שית לבך לעבודה אשר קבלתה באדון למען תמלאנה׃ ");
INSERT INTO heb_vpl VALUES ("CL4_18","081_4_18","COL","4","18","18","שאלת השלום מידי אני פולוס זכרו את מוסרי החסד עמכם אמן׃ ");
INSERT INTO heb_vpl VALUES ("H11_1","082_1_1","1TH","1","1","1","פולוס וסלונוס וטימותיוס אל קהלת התסלוניקים באלהים האב ובאדון ישוע המשיח חסד לכם ושלום מאת אלהים אבינו ואדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H11_2","082_1_2","1TH","1","2","2","נודה לאלהים על כלכם בכל עת בהזכיר אתכם בתפלותינו׃ ");
INSERT INTO heb_vpl VALUES ("H11_3","082_1_3","1TH","1","3","3","בזכרנו תמיד לפני האלהים אבינו את פעל אמונתכם ויגיעת אהבתכם וסבלנות תקותכם לאדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H11_4","082_1_4","1TH","1","4","4","כי ידענו אחי חביבי האלהים את אשר נבחרתם׃ ");
INSERT INTO heb_vpl VALUES ("H11_5","082_1_5","1TH","1","5","5","באשר בשורתנו לא היתה לכם בדבור לבד כי גם בגבורה וברוח הקדש ובדעת נאמנה מאד כאשר ידעתם גם אתם את אשר היינו בתוככם למענכם׃ ");
INSERT INTO heb_vpl VALUES ("H11_6","082_1_6","1TH","1","6","6","ואתם הייתם הלכים בעקבותינו ובעקבות אדנינו בקבלכם את הדבר בתוך עני רב עם חדות רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("H11_7","082_1_7","1TH","1","7","7","עד היותכם מופת לכל המאמינים אשר במקדוניא ובאכיא׃ ");
INSERT INTO heb_vpl VALUES ("H11_8","082_1_8","1TH","1","8","8","כי מאתכם נשמע קול דבר יהוה לא לבד במקדוניא ואכיא כי אם בכל מקום יצאה אמונתכם באלהים עד שאין לנו צרך לדבר דבר׃ ");
INSERT INTO heb_vpl VALUES ("H11_9","082_1_9","1TH","1","9","9","כי פיהם המספר מה היה מבואנו אליכם ואיך פניתם מעבודת אלילים ושבתם לאלהים לעבד את אל חי ואמתי׃ ");
INSERT INTO heb_vpl VALUES ("H11_10","082_1_10","1TH","1","10","10","ולחכות לבנו מן השמים אשר העירו מן המתים לישוע מצילנו מן החרון הבא׃ ");
INSERT INTO heb_vpl VALUES ("H12_1","082_2_1","1TH","2","1","1","כי אתם אחי הנכם ידעים את מבואנו אליכם כי לא היה לריק׃ ");
INSERT INTO heb_vpl VALUES ("H12_2","082_2_2","1TH","2","2","2","אך אחרי אשר ענינו ולחרפות היינו בפילפי כאשר ידעתם התחזקנו באלהינו להגיד גם לכם את הבשורה בנפתולים רבים׃ ");
INSERT INTO heb_vpl VALUES ("H12_3","082_2_3","1TH","2","3","3","כי תוכחתנו איננה מתוך טעות וגם לא מתוך טמאה ולא ברמיה׃ ");
INSERT INTO heb_vpl VALUES ("H12_4","082_2_4","1TH","2","4","4","כי אם כאשר נחשבנו נאמנים לאלהים להפקיד בידנו את הבשורה כן נדבר ולא כחפצים להיות רצוים לבני אדם כי אם לאלהים הבחן לבותנו׃ ");
INSERT INTO heb_vpl VALUES ("H12_5","082_2_5","1TH","2","5","5","כי מעולם לא דברנו בשפת חלקות כאשר ידעתם וגם לא למען בצע בצע האלהים עד׃ ");
INSERT INTO heb_vpl VALUES ("H12_6","082_2_6","1TH","2","6","6","גם לא בקשנו מן האדם כבוד לא מכם ולא מאחרים אף כי היה לנו מקום להתכבד כשליחי המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H12_7","082_2_7","1TH","2","7","7","אבל הלכנו לאט בתוככם כאמנת מפנקת את בניה׃ ");
INSERT INTO heb_vpl VALUES ("H12_8","082_2_8","1TH","2","8","8","ובחבבנו ככה אתכם חפצנו לתת לכם לא לבד את בשורת האלהים כי גם את נפשתינו יען כי הייתם חביבים עלינו׃ ");
INSERT INTO heb_vpl VALUES ("H12_9","082_2_9","1TH","2","9","9","הלא תזכרו אחי את יגיעתנו ואת תלאתנו אשר היינו עמלים לילה ויומם לבלתי היות למשא לאיש בבשרנו בקרבכם את בשורת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("H12_10","082_2_10","1TH","2","10","10","עדים אתם ועד האלהים כי בקדש ובצדק ובתמים היינו עמכם המאמינים׃ ");
INSERT INTO heb_vpl VALUES ("H12_11","082_2_11","1TH","2","11","11","ואתם ידעתם כי כאב את בניו הזהרנו את כל אחד מכם ודברנו על לבו׃ ");
INSERT INTO heb_vpl VALUES ("H12_12","082_2_12","1TH","2","12","12","ונעד בכם ללכת כראוי לפני האלהים הקורא אתכם למלכותו ולכבודו׃ ");
INSERT INTO heb_vpl VALUES ("H12_13","082_2_13","1TH","2","13","13","בעבור זאת גם נודה תמיד לאלהים כי אתם בקבלכם מאתנו דבר שמועת האלהים לא קבלתם אותו כדבר בני אדם כי אם כמו שהוא באמת כדבר האלהים אשר הוא גם פעל בכם המאמינים׃ ");
INSERT INTO heb_vpl VALUES ("H12_14","082_2_14","1TH","2","14","14","כי אתם אחי הלכתם בעקבי קהלות האלהים אשר בארץ יהודה במשיח ישוע כי סבלתם גם אתם כאלה על ידי בני שבטכם כאשר סבלו גם המה על ידי היהודים׃ ");
INSERT INTO heb_vpl VALUES ("H12_15","082_2_15","1TH","2","15","15","אשר אף המיתו את האדון ישוע ואת נביאיהם ואותנו רדפו ואינם טובים בעיני אלהים ואיבים לכל אדם׃ ");
INSERT INTO heb_vpl VALUES ("H12_16","082_2_16","1TH","2","16","16","המנעים אתנו מדבר אל הגוים כי יושעו למען אשר ימלאו את חטאתיהם בכל עת וישיגם החרון עד לכלה׃ ");
INSERT INTO heb_vpl VALUES ("H12_17","082_2_17","1TH","2","17","17","ואנחנו אחי אחרי אשר שכלנו אתכם לזמן מעט בפנים ולא בלב השתדלנו ביותר לראות פניכם בתשוקה רבה׃ ");
INSERT INTO heb_vpl VALUES ("H12_18","082_2_18","1TH","2","18","18","ועל כן חפצנו לבוא אליכם אני פולוס פעם ושתים והשטן עצרנו׃ ");
INSERT INTO heb_vpl VALUES ("H12_19","082_2_19","1TH","2","19","19","כי מי תקותנו ומי שמחתנו ועטרת תפארתנו הלא גם אתם לפני אדנינו ישוע המשיח בבואו׃ ");
INSERT INTO heb_vpl VALUES ("H12_20","082_2_20","1TH","2","20","20","אמנם אתם כבודנו ושמחתנו׃ ");
INSERT INTO heb_vpl VALUES ("H13_1","082_3_1","1TH","3","1","1","ועל כן לא יכלנו עוד להתאפק ונועץ להותר לבדנו באתינס׃ ");
INSERT INTO heb_vpl VALUES ("H13_2","082_3_2","1TH","3","2","2","ונשלח את טימותיוס אחינו ומשרת האלהים ועזרנו בבשורת המשיח לחזק ולהזהיר אתכם על דבר אמונתכם׃ ");
INSERT INTO heb_vpl VALUES ("H13_3","082_3_3","1TH","3","3","3","שלא ימוט איש במצוקות האלה כי ידעתם אף אתם כי לזאת יעדנו׃ ");
INSERT INTO heb_vpl VALUES ("H13_4","082_3_4","1TH","3","4","4","הלא כבד אמרנו אליכם בהיותנו אצלכם כי עתידים אנחנו להלחץ כאשר גם היה ואתם ידעתם׃ ");
INSERT INTO heb_vpl VALUES ("H13_5","082_3_5","1TH","3","5","5","ובעבור כן לא יכלתי עוד להתאפק ואשלח לדעת אמונתכם כי אמרתי פן נסה אתכם המנסה והיתה לריק יגיעתנו׃ ");
INSERT INTO heb_vpl VALUES ("H13_6","082_3_6","1TH","3","6","6","ועתה כשוב אלינו טימותיוס מאתכם ויבשר אתנו את בשורת אמונתכם ואהבתכם ואת אשר אתם זכרים אתנו לטובה בכל עת ונכספים לראות אתנו כאשר גם אנחנו נכספים לכם׃ ");
INSERT INTO heb_vpl VALUES ("H13_7","082_3_7","1TH","3","7","7","אז נחמנו עליכם אחי בכל צרתנו ולחצנו על ידי אמונתכם׃ ");
INSERT INTO heb_vpl VALUES ("H13_8","082_3_8","1TH","3","8","8","כי עתה נחיה אם תעמדו אתם באדנינו׃ ");
INSERT INTO heb_vpl VALUES ("H13_9","082_3_9","1TH","3","9","9","כי מה נשיב לאלהים להודות לו בעבורכם על כל השמחה אשר שמחנו עליכם לפני אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("H13_10","082_3_10","1TH","3","10","10","לילה ויומם מפילים אנחנו תחנתנו לראות את פניכם ולהשלים את מחסרי אמונתכם׃ ");
INSERT INTO heb_vpl VALUES ("H13_11","082_3_11","1TH","3","11","11","והוא האלהים אבינו ואדנינו ישוע המשיח יישר את דרכנו אליכם׃ ");
INSERT INTO heb_vpl VALUES ("H13_12","082_3_12","1TH","3","12","12","ואתכם ירבה ויותיר האדון לאהבה איש את רעהו ולאהבה כל אדם כאשר גם אנחנו אהבים אתכם׃ ");
INSERT INTO heb_vpl VALUES ("H13_13","082_3_13","1TH","3","13","13","ויכונן את לבבכם להיות תמים בקדשה לפני אלהינו אבינו בבוא ישוע המשיח אדנינו עם כל קדשיו׃ ");
INSERT INTO heb_vpl VALUES ("H14_1","082_4_1","1TH","4","1","1","ועוד נבקשה מכם אחי ונזהיר אתכם באדנינו ישוע כי כאשר קבלתם מאתנו איך לכם להתהלך ולמצא חן בעיני האלהים כן תוסיפו וכן תרבו עוד׃ ");
INSERT INTO heb_vpl VALUES ("H14_2","082_4_2","1TH","4","2","2","כי ידעתם את המצות אשר נתנו לכם בשם האדון ישוע׃ ");
INSERT INTO heb_vpl VALUES ("H14_3","082_4_3","1TH","4","3","3","כי רצון האלהים היא קדשתכם אשר תתרחקו מן הזנות׃ ");
INSERT INTO heb_vpl VALUES ("H14_4","082_4_4","1TH","4","4","4","וידע כל איש מכם לשמר את כליו בקדשה ויקר׃ ");
INSERT INTO heb_vpl VALUES ("H14_5","082_4_5","1TH","4","5","5","ולא בתאות זמה כדרך הגוים אשר אינם ידעים האלהים׃ ");
INSERT INTO heb_vpl VALUES ("H14_6","082_4_6","1TH","4","6","6","ולא יפרץ איש ויונה את אחיו בעשק כי נוקם יהוה על כל זאת כאשר כבר אמרנו והעידנו לכם׃ ");
INSERT INTO heb_vpl VALUES ("H14_7","082_4_7","1TH","4","7","7","כי לא קרא אותנו האלהים לטמאה כי אם לקדשה׃ ");
INSERT INTO heb_vpl VALUES ("H14_8","082_4_8","1TH","4","8","8","על כן הבוזה זאת לא אנשים הוא בוזה כי אם את האלהים אשר גם שם בקרבנו את רוח קדשו׃ ");
INSERT INTO heb_vpl VALUES ("H14_9","082_4_9","1TH","4","9","9","ועל אהבת האחים אין צרך לכתב אליכם הלא אף אתם למודי יהוה לאהבה איש את רעהו׃ ");
INSERT INTO heb_vpl VALUES ("H14_10","082_4_10","1TH","4","10","10","וגם עשים אתם כן לכל אחיכם אשר בכל מקדוניא אך נבקשה מכם אחי אשר תוסיפו ותרבו עוד׃ ");
INSERT INTO heb_vpl VALUES ("H14_11","082_4_11","1TH","4","11","11","ותשתדלו לשבת בנחת ותעשו איש מלאכתו בעמל ידיכם כאשר צוינו אתכם׃ ");
INSERT INTO heb_vpl VALUES ("H14_12","082_4_12","1TH","4","12","12","למען תתנהגו כהגן עם אשר בחוץ ולא תצטרכו לאדם׃ ");
INSERT INTO heb_vpl VALUES ("H14_13","082_4_13","1TH","4","13","13","ועל דבר הישנים אחי לא נכחד מכם דבר למען לא תעצבו כאחרים אשר אין להם תקוה׃ ");
INSERT INTO heb_vpl VALUES ("H14_14","082_4_14","1TH","4","14","14","כי אם נאמין אשר מת ישוע ויחי כן יביא האלהים על ידי ישוע גם את הישנים אתו׃ ");
INSERT INTO heb_vpl VALUES ("H14_15","082_4_15","1TH","4","15","15","כי את זאת נאמר לכם בדבר יהוה כי אנחנו החיים הנותרים עד בא האדון לא נקדם את הישנים׃ ");
INSERT INTO heb_vpl VALUES ("H14_16","082_4_16","1TH","4","16","16","כי הוא האדון ירד מן השמים בתרועה בקול שר המלאכים ובשופר אלהים ואז יקומו ראשונה המתים במשיח׃ ");
INSERT INTO heb_vpl VALUES ("H14_17","082_4_17","1TH","4","17","17","אחרי כן אנחנו החיים הנשארים נלקח אתם יחדו בעננים לקראת האדון לרקיע ובכן נהיה תמיד עם האדון׃ ");
INSERT INTO heb_vpl VALUES ("H14_18","082_4_18","1TH","4","18","18","לכן נחמו זה את זה בדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("H15_1","082_5_1","1TH","5","1","1","ועל דבר העתים והזמנים אין צרך לכתב אליכם אחי׃ ");
INSERT INTO heb_vpl VALUES ("H15_2","082_5_2","1TH","5","2","2","הלא אף אתם ידעתם היטב כי יום יהוה כגנב בלילה כן בוא יבוא׃ ");
INSERT INTO heb_vpl VALUES ("H15_3","082_5_3","1TH","5","3","3","כי בעת אמרם שלום ושלוה יבא עליהם השבר פתאם כחבלים על ההרה ולא יוכלו להמלט׃ ");
INSERT INTO heb_vpl VALUES ("H15_4","082_5_4","1TH","5","4","4","אבל אתם אחי אינכם בחשך שישיג אתכם היום כגנב׃ ");
INSERT INTO heb_vpl VALUES ("H15_5","082_5_5","1TH","5","5","5","אתם כלכם בני האור ובני היום לא בני הלילה אנחנו ולא בני החשך׃ ");
INSERT INTO heb_vpl VALUES ("H15_6","082_5_6","1TH","5","6","6","לכן אל נא נרדם כמו האחרים כי אם נשקד וננזר׃ ");
INSERT INTO heb_vpl VALUES ("H15_7","082_5_7","1TH","5","7","7","כי הנרדמים הם בלילה נרדמים והמשתכרים משתכרים בלילה׃ ");
INSERT INTO heb_vpl VALUES ("H15_8","082_5_8","1TH","5","8","8","ואנחנו בני היום ננזרה נא ונלבש את שריון האמונה והאהבה וככובע את תקות הישועה׃ ");
INSERT INTO heb_vpl VALUES ("H15_9","082_5_9","1TH","5","9","9","יען אשר לא יעדנו האלהים לחרון כי אם לנחל את הישועה על ידי אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H15_10","082_5_10","1TH","5","10","10","אשר מת בעדנו למען אם נשקד ואם נישן חיה נחיה עמו יחד׃ ");
INSERT INTO heb_vpl VALUES ("H15_11","082_5_11","1TH","5","11","11","על כן נחמו זה את זה ובנו איש את אחיו כאשר גם עשיתם׃ ");
INSERT INTO heb_vpl VALUES ("H15_12","082_5_12","1TH","5","12","12","והננו מבקשים מכם אחי להכיר את העמלים בכם ואשר הם נצבים עליכם באדון ומוכיחים אתכם׃ ");
INSERT INTO heb_vpl VALUES ("H15_13","082_5_13","1TH","5","13","13","אשר תנהגו בם כבוד עד למעלה באהבה למען פעלתם ויהי שלום ביניכם׃ ");
INSERT INTO heb_vpl VALUES ("H15_14","082_5_14","1TH","5","14","14","והננו מזהירים אתכם אחי הוכיחו את הסוררים אמצו את רכי הלבב תמכו את החלשים והאריכו רוח אל כל אדם׃ ");
INSERT INTO heb_vpl VALUES ("H15_15","082_5_15","1TH","5","15","15","וראו פן ישלם איש לאיש רעה תחת רעה כי אם רדפו בכל עת את הטוב הן לאיש איש מכם הן לכל אדם׃ ");
INSERT INTO heb_vpl VALUES ("H15_16","082_5_16","1TH","5","16","16","היו שמחים בכל עת׃ ");
INSERT INTO heb_vpl VALUES ("H15_17","082_5_17","1TH","5","17","17","התמידו בתפלה׃ ");
INSERT INTO heb_vpl VALUES ("H15_18","082_5_18","1TH","5","18","18","הודו על הכל כי זה רצון האלהים אליכם במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("H15_19","082_5_19","1TH","5","19","19","את הרוח לא תכבו׃ ");
INSERT INTO heb_vpl VALUES ("H15_20","082_5_20","1TH","5","20","20","את הנבואות לא תמאסו׃ ");
INSERT INTO heb_vpl VALUES ("H15_21","082_5_21","1TH","5","21","21","בחנו כל דבר ובטוב אחזו׃ ");
INSERT INTO heb_vpl VALUES ("H15_22","082_5_22","1TH","5","22","22","התרחקו מכל הדומה לרע׃ ");
INSERT INTO heb_vpl VALUES ("H15_23","082_5_23","1TH","5","23","23","והוא אלהי השלום יקדש אתכם קדשה שלמה וכל רוחכם ונפשכם וגופכם ישמר תמים בבוא אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H15_24","082_5_24","1TH","5","24","24","נאמן הקורא אתכם אשר גם יעשה׃ ");
INSERT INTO heb_vpl VALUES ("H15_25","082_5_25","1TH","5","25","25","אחי התפללו בעדנו׃ ");
INSERT INTO heb_vpl VALUES ("H15_26","082_5_26","1TH","5","26","26","שאלו לשלום כל האחים בנשיקה הקדשה׃ ");
INSERT INTO heb_vpl VALUES ("H15_27","082_5_27","1TH","5","27","27","הנני משביעכם באדון שתקרא האגרת הזאת באזני כל האחים הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("H15_28","082_5_28","1TH","5","28","28","חסד ישוע המשיח אדנינו עמכם אמן׃ ");
INSERT INTO heb_vpl VALUES ("H21_1","083_1_1","2TH","1","1","1","פולוס וסלונוס וטימותיוס אל קהלת התסלוניקים באלהים אבינו ובאדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H21_2","083_1_2","2TH","1","2","2","חסד לכם ושלום מאת אלהים אבינו ואדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H21_3","083_1_3","2TH","1","3","3","חיבים אנחנו להודות בכל עת לאלהים עליכם אחי כראוי כי אמונתכם גדלה מאד ורבה אהבת כלכם איש לרעהו׃ ");
INSERT INTO heb_vpl VALUES ("H21_4","083_1_4","2TH","1","4","4","עד כי נתהלל בכם אף אנחנו בקהלות אלהים על סבלנותכם ועל אמונתכם בכל הרדיפות ובכל הלחץ אשר סבלתם׃ ");
INSERT INTO heb_vpl VALUES ("H21_5","083_1_5","2TH","1","5","5","לאות צדקת משפט אלהים למען תמצאו ראוים למלכות האלהים אשר בעבורה גם תענו׃ ");
INSERT INTO heb_vpl VALUES ("H21_6","083_1_6","2TH","1","6","6","באשר צדיק האלהים לגמל לחץ ללחציכם׃ ");
INSERT INTO heb_vpl VALUES ("H21_7","083_1_7","2TH","1","7","7","ולכם הנלחצים רוחה אתנו יחד בהגלות האדון ישוע מן השמים עם מלאכי עזו׃ ");
INSERT INTO heb_vpl VALUES ("H21_8","083_1_8","2TH","1","8","8","באש להבה להשיב נקם לאשר לא ידעו את האלהים ולא שמעו לבשורת אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H21_9","083_1_9","2TH","1","9","9","אשר ישאו משפט אבדן עולם מאת פני האדון ומהדר גאונו׃ ");
INSERT INTO heb_vpl VALUES ("H21_10","083_1_10","2TH","1","10","10","בבאו ביום ההוא להכבד בקדשיו ולהתפלא בכל המאמינים כי האמנתם לעדותנו אליכם׃ ");
INSERT INTO heb_vpl VALUES ("H21_11","083_1_11","2TH","1","11","11","לכן גם נתפלל בעדכם בכל עת אשר יתן אתכם אלהינו ראוים אל אשר אתם מקראים וימלא בעז כל חפצכם בטוב וכל מעשה אמונתכם׃ ");
INSERT INTO heb_vpl VALUES ("H21_12","083_1_12","2TH","1","12","12","למען יכבד בכם שם ישוע אדנינו ואתם תכבדו בו על פי חסד אלהינו ואדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H22_1","083_2_1","2TH","2","1","1","והננו מבקשים מכם אחי על אדות ביאת אדנינו ישוע המשיח ואסיפתנו אליו׃ ");
INSERT INTO heb_vpl VALUES ("H22_2","083_2_2","2TH","2","2","2","אשר לא תטרף דעתכם פתאם ואשר לא תבהלו לא ברוח ולא בדבור ולא באגרת כמו שלוחה מאתנו כאלו הגיע יום המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H22_3","083_2_3","2TH","2","3","3","אל יתעה אתכם איש בשום אופן כי לא יבא בטרם יהיה בראשונה המרד ונגלה איש החטאה בן האבדון׃ ");
INSERT INTO heb_vpl VALUES ("H22_4","083_2_4","2TH","2","4","4","המתקומם והמתרומם על כל הנקרא אל או עבודה עד כי גם ישב בהיכל האלהים כאלהים ומראה את עצמו כי אלהים הוא׃ ");
INSERT INTO heb_vpl VALUES ("H22_5","083_2_5","2TH","2","5","5","הלא תזכרו כי בעוד היותי אתכם דברתי אלה אליכם׃ ");
INSERT INTO heb_vpl VALUES ("H22_6","083_2_6","2TH","2","6","6","ועתה ידעתם מה שימנעהו מלהגלות בעתו׃ ");
INSERT INTO heb_vpl VALUES ("H22_7","083_2_7","2TH","2","7","7","כי סוד הרשע כבר החל לפעל רק שיוסר מתוך המנע עד כה׃ ");
INSERT INTO heb_vpl VALUES ("H22_8","083_2_8","2TH","2","8","8","ואז יגלה הרשע אשר ימיתנו האדון ברוח שפתיו וישביתנו בהופעת ביאתו׃ ");
INSERT INTO heb_vpl VALUES ("H22_9","083_2_9","2TH","2","9","9","את אשר יבוא כחזקת השטן ברב כח ובאתות ובמופתי שקר׃ ");
INSERT INTO heb_vpl VALUES ("H22_10","083_2_10","2TH","2","10","10","ובכל מרמת און באבדים תחת אשר לא קבלו את אהבת האמת להושע׃ ");
INSERT INTO heb_vpl VALUES ("H22_11","083_2_11","2TH","2","11","11","ובעבור זאת ישלח להם האלהים מדוחי שוא להאמין בשקר׃ ");
INSERT INTO heb_vpl VALUES ("H22_12","083_2_12","2TH","2","12","12","למען ידונו בל אשר לא האמינו באמת כי אם רצו בעולה׃ ");
INSERT INTO heb_vpl VALUES ("H22_13","083_2_13","2TH","2","13","13","אבל אנחנו חיבים להודות לאלהים בכל עת בעבורכם אחי חביבי האדון אשר האלהים בחר בכם מראשית לישועה בקדוש הרוח ובאמונת האמת׃ ");
INSERT INTO heb_vpl VALUES ("H22_14","083_2_14","2TH","2","14","14","לזאת קרא אתכם בבשורתנו לנחלת כבוד אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H22_15","083_2_15","2TH","2","15","15","לכן אחי עמדו והחזיקו בקבלות אשר למדתם אם בדברנו אם באגרתנו׃ ");
INSERT INTO heb_vpl VALUES ("H22_16","083_2_16","2TH","2","16","16","והוא אדנינו ישוע המשיח ואלהינו אבינו אשר אהב אתנו ויתן לנו בחסדו נחמת עולם ותקוה טובה׃ ");
INSERT INTO heb_vpl VALUES ("H22_17","083_2_17","2TH","2","17","17","הוא ינחם את לבבכם ויכונן אתכם בכל דבר ומעשה טוב׃ ");
INSERT INTO heb_vpl VALUES ("H23_1","083_3_1","2TH","3","1","1","ועוד אחי התפללו בעדנו אשר ירוץ דבר יהוה ויכבד כמו גם בקרבכם׃ ");
INSERT INTO heb_vpl VALUES ("H23_2","083_3_2","2TH","3","2","2","ואשר ננצל מן האנשים התעים והרעים כי לא לכל אדם האמונה׃ ");
INSERT INTO heb_vpl VALUES ("H23_3","083_3_3","2TH","3","3","3","אבל נאמן הוא האדון אשר יחזק אתכם וישמרכם מן הרע׃ ");
INSERT INTO heb_vpl VALUES ("H23_4","083_3_4","2TH","3","4","4","ואנחנו בטוחים עליכם באדנינו כי תעשו וגם תוסיפו לעשות את אשר נצוה׃ ");
INSERT INTO heb_vpl VALUES ("H23_5","083_3_5","2TH","3","5","5","והאדון הוא יישר את לבבכם לאהבת האלהים ולסבלנות המשיח׃ ");
INSERT INTO heb_vpl VALUES ("H23_6","083_3_6","2TH","3","6","6","והננו מצוים אתכם אחים בשם אדנינו ישוע המשיח אשר תבדלו מכל אח מעקש דרכיו ואיננו מתהלך על פי הקבלה אשר קבל מאתנו׃ ");
INSERT INTO heb_vpl VALUES ("H23_7","083_3_7","2TH","3","7","7","הלא ידעתם אף אתם איך עליכם להתהלך כמנו כי לא נהגנו דרך מעות בתוככם׃ ");
INSERT INTO heb_vpl VALUES ("H23_8","083_3_8","2TH","3","8","8","גם לא אכלנו לחם איש חנם כי ביגיעה ותלאה לילה ויומם היינו עמלים לבלתי היות לאיש מכם למשא׃ ");
INSERT INTO heb_vpl VALUES ("H23_9","083_3_9","2TH","3","9","9","לא בעבור שאין לנו הרשות לזאת כי אם לתת אתנו לכם למופת ללכת בעקבותינו׃ ");
INSERT INTO heb_vpl VALUES ("H23_10","083_3_10","2TH","3","10","10","כי גם בהיותנו אצלכם צוינו אתכם לאמר מי שלא ירצה לעבד גם אכול לא יאכל׃ ");
INSERT INTO heb_vpl VALUES ("H23_11","083_3_11","2TH","3","11","11","כי שמענו שיש בכם אנשים המעקשים את דרכיהם ואינם עבדים מאומה ומבלים ימיהם בהבלים׃ ");
INSERT INTO heb_vpl VALUES ("H23_12","083_3_12","2TH","3","12","12","ואנשים כאלה נצוה אותם ונבקש מהם באדנינו ישוע המשיח לעבד בנחת למען יאכלו את לחמם׃ ");
INSERT INTO heb_vpl VALUES ("H23_13","083_3_13","2TH","3","13","13","ואתם אחי אל תלאו בעשות הטוב׃ ");
INSERT INTO heb_vpl VALUES ("H23_14","083_3_14","2TH","3","14","14","ואם לא ישמע איש אל דברנו באגרת הזאת אתו תרשמו לכם ואל תתערבו עמו למען יבוש׃ ");
INSERT INTO heb_vpl VALUES ("H23_15","083_3_15","2TH","3","15","15","אך לא כאיב תחשבהו כי אם תוכיחהו כאח׃ ");
INSERT INTO heb_vpl VALUES ("H23_16","083_3_16","2TH","3","16","16","והוא אדון השלום הוא יתן לכם את השלום תמיד ובכל פנים׃ ");
INSERT INTO heb_vpl VALUES ("H23_17","083_3_17","2TH","3","17","17","יהי האדון עם כלכם׃ ");
INSERT INTO heb_vpl VALUES ("H23_18","083_3_18","2TH","3","18","18","שאלת השלום מידי אני פולוס והיא האות בכל האגרות כן אנכי כתב׃  (II Thessalonians 3:19) חסד ישוע המשיח אדנינו עם כלכם אמן׃  ");
INSERT INTO heb_vpl VALUES ("T11_1","084_1_1","1TI","1","1","1","פולוס שליח ישוע המשיח כמצות האלהים מושיענו והאדון ישוע המשיח תקותנו׃ ");
INSERT INTO heb_vpl VALUES ("T11_2","084_1_2","1TI","1","2","2","אל טימותיוס בנו האמתי באמונה חסד ורחמים ושלום מאת אלהים אבינו והמשיח ישוע אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("T11_3","084_1_3","1TI","1","3","3","הנה בלכתי למקדוניא בקשתי ממך לשבת באפסוס למען תזהיר מקצת אנשים שלא יורו תורה זרה׃ ");
INSERT INTO heb_vpl VALUES ("T11_4","084_1_4","1TI","1","4","4","ולא ישימו לבם להגדות וללמודי תולדות אין קץ המביאים יותר לשאלות מלבנות בית אלהים באמונה׃ ");
INSERT INTO heb_vpl VALUES ("T11_5","084_1_5","1TI","1","5","5","כי תכלית המצוה היא האהבה בלב טהור וברוח טובה ובאמונה לא צבועה׃ ");
INSERT INTO heb_vpl VALUES ("T11_6","084_1_6","1TI","1","6","6","יש אשר תעו ממנה ויפנו אחרי למודי תהו׃ ");
INSERT INTO heb_vpl VALUES ("T11_7","084_1_7","1TI","1","7","7","בחשבם להיות מורי תורה ואינם מבינים מה הם אמרים ומה הם מחליטים׃ ");
INSERT INTO heb_vpl VALUES ("T11_8","084_1_8","1TI","1","8","8","אבל ידענו כי התורה טובה היא אם יתנהג בה האדם כתורה׃ ");
INSERT INTO heb_vpl VALUES ("T11_9","084_1_9","1TI","1","9","9","בדעתו זאת כי חק לא הושם בעבור הצדיק אלא בעבור הסוררים והמרדים הרשעים והחטאים עשי זמה ונבלה מכי אב ומכי אם ומרצחים׃ ");
INSERT INTO heb_vpl VALUES ("T11_10","084_1_10","1TI","1","10","10","וזנים ושכבים את זכר וגנבי נפש וכזבים ונשבעים לשקר וכל מעשה הפך מן הלקח הבריא׃ ");
INSERT INTO heb_vpl VALUES ("T11_11","084_1_11","1TI","1","11","11","כפי בשורת כבוד האל המברך אשר פקדה עלי׃ ");
INSERT INTO heb_vpl VALUES ("T11_12","084_1_12","1TI","1","12","12","והנני מודה לישוע המשיח אדנינו המאזרני חיל כי חשבני נאמן וישימני למשרת לו׃ ");
INSERT INTO heb_vpl VALUES ("T11_13","084_1_13","1TI","1","13","13","אתי אשר מלפנים הייתי מגדף ומרדף ומחרף אבל רחמתי כי עשיתי מבלי דעת באין אמונה׃ ");
INSERT INTO heb_vpl VALUES ("T11_14","084_1_14","1TI","1","14","14","ויגדל עלי במאד מאד חסד אדנינו עם האמונה והאהבה במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("T11_15","084_1_15","1TI","1","15","15","נאמן הדבר וראוי להתקבל על כל כי המשיח ישוע בא לעולם להושיע את החטאים אשר אנכי הגדול בהם׃ ");
INSERT INTO heb_vpl VALUES ("T11_16","084_1_16","1TI","1","16","16","ובעבור זאת רחמתי למען אשר יראה ישוע המשיח בי בראשונה את כל ארך רוחו להיותי למופת לכל אשר יבאו להאמין בו לחיי עולם׃ ");
INSERT INTO heb_vpl VALUES ("T11_17","084_1_17","1TI","1","17","17","ולמלך עולמים לאלהים הקים לעד והנעלם מעין והחכם לבדו לו הכבוד וההדר לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("T11_18","084_1_18","1TI","1","18","18","את המצוה הזאת אני מצוך בני טימותיוס כפי הנבואות הקדמות עליך שתלחם לפיהן המלחמה הטובה׃ ");
INSERT INTO heb_vpl VALUES ("T11_19","084_1_19","1TI","1","19","19","לאחז באמונה וברוח הטובה אשר יש מאסים בה ותשבר אנית אמונתם׃ ");
INSERT INTO heb_vpl VALUES ("T11_20","084_1_20","1TI","1","20","20","ומהם הומניוס ואלכסנדר אשר מסרתים לשטן למען יוסרו לבלתי גדף עוד׃ ");
INSERT INTO heb_vpl VALUES ("T12_1","084_2_1","1TI","2","1","1","ועתה קדם כל דבר אבקשה מכם לשאת תפלות ותחנונים ובקשות ותודות בעד כל בני אדם׃ ");
INSERT INTO heb_vpl VALUES ("T12_2","084_2_2","1TI","2","2","2","בעד המלכים וכל השליטים למען נחיה חיי השקט ובטח בכל חסידות וישר׃ ");
INSERT INTO heb_vpl VALUES ("T12_3","084_2_3","1TI","2","3","3","כי כן טוב ורצוי בעיני אלהים מושיענו׃ ");
INSERT INTO heb_vpl VALUES ("T12_4","084_2_4","1TI","2","4","4","אשר חפצו שיושעו כל בני האדם ויגיעו להכרת האמת׃ ");
INSERT INTO heb_vpl VALUES ("T12_5","084_2_5","1TI","2","5","5","כי אחד הוא האלהים ואחד הוא העמד בין אלהים ובין בני אדם הוא בן אדם המשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("T12_6","084_2_6","1TI","2","6","6","אשר נתן את נפשו כפר בעד כל וזאת העדות הבאה בעתה׃ ");
INSERT INTO heb_vpl VALUES ("T12_7","084_2_7","1TI","2","7","7","אשר אני הפקדתי לה לכרוז ולשליח אמת אני אמר במשיח ולא אשקר מורה הגוים באמונה ובאמת׃ ");
INSERT INTO heb_vpl VALUES ("T12_8","084_2_8","1TI","2","8","8","לכן רצוני שיתפללו האנשים בכל מקום וישאו ידיהם קדש בלי כעס ומדון׃ ");
INSERT INTO heb_vpl VALUES ("T12_9","084_2_9","1TI","2","9","9","וכן גם הנשים תתיפינה בתלבשת נאה עם בשת פנים וצניעות לא במחלפות הראש לא בזהב לא בפנינים ולא במלבושים יקרים׃ ");
INSERT INTO heb_vpl VALUES ("T12_10","084_2_10","1TI","2","10","10","אלא כמו שהוא הגון לנשים אשר בחרו להן יראת אלהים במעשים טובים׃ ");
INSERT INTO heb_vpl VALUES ("T12_11","084_2_11","1TI","2","11","11","האשה תלמד דומם בכל הכנעה׃ ");
INSERT INTO heb_vpl VALUES ("T12_12","084_2_12","1TI","2","12","12","ואינני נתן רשות לאשה ללמד אף לא להתנשא על האיש אלא תדום׃ ");
INSERT INTO heb_vpl VALUES ("T12_13","084_2_13","1TI","2","13","13","כי אדם נוצר בראשונה ואחריו חוה׃ ");
INSERT INTO heb_vpl VALUES ("T12_14","084_2_14","1TI","2","14","14","ואדם לא נפתה כי האשה שמעה לקול המשיא ותבא לידי עברה׃ ");
INSERT INTO heb_vpl VALUES ("T12_15","084_2_15","1TI","2","15","15","אבל תושע בלדתה בנים אם תעמדנה באמונה ובאהבה ובקדשה עם הצניעות׃ ");
INSERT INTO heb_vpl VALUES ("T13_1","084_3_1","1TI","3","1","1","אמת הדבר איש כי יבקש לו פקידות הוא מתאוה מעשה טוב׃ ");
INSERT INTO heb_vpl VALUES ("T13_2","084_3_2","1TI","3","2","2","ופקיד העדה צריך להיות איש אשר אין בו דפי בעל אשה אחת משל ברוחו צנוע ונחמד לבריות מכניס ארחים ומבין ללמד ולא אהב יין ולא נוח להכות ולא בצע בצע רע׃ ");
INSERT INTO heb_vpl VALUES ("T13_3","084_3_3","1TI","3","3","3","כי אם דן לכף זכות ולא בעל קטטה ולא אהב כסף׃ ");
INSERT INTO heb_vpl VALUES ("T13_4","084_3_4","1TI","3","4","4","ויהי מנהיג את ביתו בטוב ומדריך את בניו למשמעתו בכל הישר׃ ");
INSERT INTO heb_vpl VALUES ("T13_5","084_3_5","1TI","3","5","5","כי אם לא ידע איש להנהיג את ביתו איככה יוכל לדאג לעדת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("T13_6","084_3_6","1TI","3","6","6","ואל יהי תלמיד הדש למען לא ירהב לבו ויפל בדין המשטין׃ ");
INSERT INTO heb_vpl VALUES ("T13_7","084_3_7","1TI","3","7","7","והוא גם צריך לשם טוב בפי אלה אשר בחוץ פן יפל בחרפה ובמוקש המשטין׃ ");
INSERT INTO heb_vpl VALUES ("T13_8","084_3_8","1TI","3","8","8","וכן גם השמשים יהיו ישרים ולא מחליקי לשון ולא אהבים סבא יין ולא נטים אחרי בצע רע׃ ");
INSERT INTO heb_vpl VALUES ("T13_9","084_3_9","1TI","3","9","9","כי אם ישמרו את סוד האמונה ברוח טהורה׃ ");
INSERT INTO heb_vpl VALUES ("T13_10","084_3_10","1TI","3","10","10","וגם אלה יבחנו בראשונה ואחר כן ישמשו אם אין בהם דפי׃ ");
INSERT INTO heb_vpl VALUES ("T13_11","084_3_11","1TI","3","11","11","וככה הנשים תהיינה ישרות ולא מלשינות משלות ברוחן ונאמנות בכל׃ ");
INSERT INTO heb_vpl VALUES ("T13_12","084_3_12","1TI","3","12","12","השמשים יהיו כל אחד בעל אשה אחת ומנהלים בטוב את בניהם ואת בתיהם׃ ");
INSERT INTO heb_vpl VALUES ("T13_13","084_3_13","1TI","3","13","13","כי המשמשים היטב יקנו לעצמם מעלה טובה ובטחון רב באמונת המשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("T13_14","084_3_14","1TI","3","14","14","זאת אני כתב אליך ואקוה לבא אליך במהרה׃ ");
INSERT INTO heb_vpl VALUES ("T13_15","084_3_15","1TI","3","15","15","ואם אחר הנה תדע איך להתנהג בבית האלהים שהיא עדת אלהים חיים עמוד האמת ומכונה׃ ");
INSERT INTO heb_vpl VALUES ("T13_16","084_3_16","1TI","3","16","16","ובודי גדול סוד החסידות אלהים נגלה בבשר נצדק ברוח נראה למלאכים הגד בגוים נתקבל באמונה בעולם נעלה בכבוד׃ ");
INSERT INTO heb_vpl VALUES ("T14_1","084_4_1","1TI","4","1","1","אבל הרוח אמר בפרוש כי באחרית הימים יהיו אנשים אשר יסורו מן האמונה בפנותם אל הרוחות המטעות ואל תורת השדים׃ ");
INSERT INTO heb_vpl VALUES ("T14_2","084_4_2","1TI","4","2","2","דברי שקרים בחנפה ונכוים הם במדעת׃ ");
INSERT INTO heb_vpl VALUES ("T14_3","084_4_3","1TI","4","3","3","אסרים לקחת אשה ומנעים ממיני מאכל אשר בראם האלהים שיאכלות בתודה המאמינים וידעי האמת׃ ");
INSERT INTO heb_vpl VALUES ("T14_4","084_4_4","1TI","4","4","4","כי כל בריאת אלהים טובה היא ואין דבר משקץ אם יאכל בתודה׃ ");
INSERT INTO heb_vpl VALUES ("T14_5","084_4_5","1TI","4","5","5","כי יקדש בדבר אלהים ובתפלה׃ ");
INSERT INTO heb_vpl VALUES ("T14_6","084_4_6","1TI","4","6","6","אם תשים כזאת לפני אחיך משרת טוב תהיה לישוע המשיח מגדל בדברי האמונה ובלקח הטוב אשר דבקת אחריו׃ ");
INSERT INTO heb_vpl VALUES ("T14_7","084_4_7","1TI","4","7","7","אך התרחק מהגדות פסולות ובלות והרגל עצמך בחסידות׃ ");
INSERT INTO heb_vpl VALUES ("T14_8","084_4_8","1TI","4","8","8","כי הרגל הגוף יועיל מעט אבל החסידות תועיל לכל דבר ויש לה הבטחת חיי העולם הזה והעולם הבא׃ ");
INSERT INTO heb_vpl VALUES ("T14_9","084_4_9","1TI","4","9","9","נאמן הדבר הזה וראוי על כל להתקבל׃ ");
INSERT INTO heb_vpl VALUES ("T14_10","084_4_10","1TI","4","10","10","כי לזאת אנחנו גם יגעים גם נעלבים על אשר הוחלנו לאלהים חיים שהוא המושיע לכל האדם וביותר למאמינים׃ ");
INSERT INTO heb_vpl VALUES ("T14_11","084_4_11","1TI","4","11","11","את זאת תצוה ותלמד׃ ");
INSERT INTO heb_vpl VALUES ("T14_12","084_4_12","1TI","4","12","12","אל יבוז איש את בחורותיך אך היה מופת למאמינים בדבור במעשה באהבה ברוח באמונה ובטהרה׃ ");
INSERT INTO heb_vpl VALUES ("T14_13","084_4_13","1TI","4","13","13","והיה שקוד לקרות ולהוכיח ולהורת עד כי אבוא׃ ");
INSERT INTO heb_vpl VALUES ("T14_14","084_4_14","1TI","4","14","14","ואל תקל בעיניך מתנת החסד אשר בך הנתונה לך בנבואה עם סמיכת ידי הזקנים׃ ");
INSERT INTO heb_vpl VALUES ("T14_15","084_4_15","1TI","4","15","15","לאלה תשית לבך ובהם היה למען תראה הצלחתך לכל׃ ");
INSERT INTO heb_vpl VALUES ("T14_16","084_4_16","1TI","4","16","16","שית לבך לנפשך ולהוראה והחזק בזה כי בעשותך כן תושיע את נפשך ואת נפש השמעים אליך׃ ");
INSERT INTO heb_vpl VALUES ("T15_1","084_5_1","1TI","5","1","1","אל תגער בזקן כי אם תזהירנו כאב לך ואת הצעירים כאחים׃ ");
INSERT INTO heb_vpl VALUES ("T15_2","084_5_2","1TI","5","2","2","את הזקנות כאמות ואת הצעירות כאחיות ובכל טהרה׃ ");
INSERT INTO heb_vpl VALUES ("T15_3","084_5_3","1TI","5","3","3","כבד את האלמנות אשר באמת אלמנות הנה׃ ");
INSERT INTO heb_vpl VALUES ("T15_4","084_5_4","1TI","5","4","4","וכי יהיו לאלמנה בנים או בני בנים הם ילמדו לראשונה לעשות חסד עם ביתם ולשלם גמול לאבותם כי זה הוא טוב ורצוי לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("T15_5","084_5_5","1TI","5","5","5","אבל האלמנה באמת אשר נשארה יחידה שמה אלהים מבטחה ומתמדת בתפלות ובתחנות לילה ויומם׃ ");
INSERT INTO heb_vpl VALUES ("T15_6","084_5_6","1TI","5","6","6","אך המענגה מתה היא בחייה׃ ");
INSERT INTO heb_vpl VALUES ("T15_7","084_5_7","1TI","5","7","7","וזאת תצוה למען תהיינה בלא דפי׃ ");
INSERT INTO heb_vpl VALUES ("T15_8","084_5_8","1TI","5","8","8","אבל מי שלא יפרנס את קרוביו וביותר את בני ביתו כפר באמונה והוא גרוע מאשר איננו מאמין׃ ");
INSERT INTO heb_vpl VALUES ("T15_9","084_5_9","1TI","5","9","9","אלמנה אל תבחר זולתי בת ששים שנה ואשר היתה אשת איש אחד׃ ");
INSERT INTO heb_vpl VALUES ("T15_10","084_5_10","1TI","5","10","10","ויש לה עדות על מעשיה הטובים שגדלה בנים והכניסה ארחים ירחצה את רגלי הקדשים ותמכה את העשוקים ורדפה כל מעשה טוב׃ ");
INSERT INTO heb_vpl VALUES ("T15_11","084_5_11","1TI","5","11","11","אבל האלמנות הצעירות אל תקבל כי בהטות יצרן את לבן מן המשיח חשקות הן להיות לאיש׃ ");
INSERT INTO heb_vpl VALUES ("T15_12","084_5_12","1TI","5","12","12","ודינן עליהן כי בגדו באמונתן הראשונה׃ ");
INSERT INTO heb_vpl VALUES ("T15_13","084_5_13","1TI","5","13","13","ועוד בהיותן עצלות למדו לשוטט מבית לבית ולא לבד עצלות כי אף מפטפטות ורדפות אחר חדשות ומדברות את אשר לא יתכן׃ ");
INSERT INTO heb_vpl VALUES ("T15_14","084_5_14","1TI","5","14","14","על כן רצוני כי הצעירות תהיינה לאיש ללדת בנים ולהנהיג את בתיהן ולא לתת לאיב תאנה לחרף׃ ");
INSERT INTO heb_vpl VALUES ("T15_15","084_5_15","1TI","5","15","15","כי יש מהן אשר כבר סרו אחרי השטן׃ ");
INSERT INTO heb_vpl VALUES ("T15_16","084_5_16","1TI","5","16","16","בן אמונה או בת אמונה שיש להם אלמנות יעזרו אתן ולא תהיינה למשא על הקהל כדי שיוכל להספיק לאלה אשר הנה אלמנות באמת׃ ");
INSERT INTO heb_vpl VALUES ("T15_17","084_5_17","1TI","5","17","17","הזקנים המיטיבים לנהל ראוים הם למשנה כבוד וביותר העמלים בדבר ובהוראה׃ ");
INSERT INTO heb_vpl VALUES ("T15_18","084_5_18","1TI","5","18","18","כי הכתוב אמר לא תחסם שור בדישו ועוד נאמר הפעל שוה בשכרו׃ ");
INSERT INTO heb_vpl VALUES ("T15_19","084_5_19","1TI","5","19","19","אל תקבל שטנה על הזקן בלתי אם על פי שנים או שלשה עדים׃ ");
INSERT INTO heb_vpl VALUES ("T15_20","084_5_20","1TI","5","20","20","את החטאים תוכיח בפני כל למען ייראו גם האחרים׃ ");
INSERT INTO heb_vpl VALUES ("T15_21","084_5_21","1TI","5","21","21","הנני מעיד בך נגד האלהים ואדנינו ישוע המשיח ונגד בחירי המלאכים אשר שמור תשמר את זאת בלי משפט נמהר ולא תעשה דבר במשא פנים׃ ");
INSERT INTO heb_vpl VALUES ("T15_22","084_5_22","1TI","5","22","22","אל תהי נמהר בסמיכת ידיך על אדם ולא תשתתף לחטאת אחרים שמר את נפשך בטהרה׃ ");
INSERT INTO heb_vpl VALUES ("T15_23","084_5_23","1TI","5","23","23","אל תרבה לשתות עוד מים כי אם קח מעט יין בעבור בטנך ואשר פעמים רבות חלה אתה׃ ");
INSERT INTO heb_vpl VALUES ("T15_24","084_5_24","1TI","5","24","24","יש בני אדם אשר חטאתיהם גלויות ומקדימות לדין ויש מהם אשר הנה הלכות אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("T15_25","084_5_25","1TI","5","25","25","וככה גם המעשים הטובים גלוים המה ואשר אינם כן לא יוכלו להסתר׃ ");
INSERT INTO heb_vpl VALUES ("T16_1","084_6_1","1TI","6","1","1","כל אשר הם תחת על העבדות יחשבו את אדניהם ראוים לכל כבוד למען לא יחלל שם האלהים והלקח׃ ");
INSERT INTO heb_vpl VALUES ("T16_2","084_6_2","1TI","6","2","2","ואלה אשר אדניהם בני אמונה אל יקלו אתם על היותם אחים כי אם יעבדום ביותר בעבור כי מאמינים ואהובים הם המשתדלים לגמל חסד את זאת תלמד ותצוה׃ ");
INSERT INTO heb_vpl VALUES ("T16_3","084_6_3","1TI","6","3","3","האיש אשר יורה תורה אחרת ולא יעמד בדברים הבריאים של אדנינו ישוע המשיח ובלקח החסידות׃ ");
INSERT INTO heb_vpl VALUES ("T16_4","084_6_4","1TI","6","4","4","נפשו עפלה ולא ידע מאומה כי אם חלה הוא בשאלות ומחלקות מלים המביאים לידי קנאה ומריבה וגדופים וחשד רע׃ ");
INSERT INTO heb_vpl VALUES ("T16_5","084_6_5","1TI","6","5","5","וכוחי הבל של אנשים נשחתי דעת ומחסרי אמת השמים את החסידות לדבר בצע סור מאנשים כאלה׃ ");
INSERT INTO heb_vpl VALUES ("T16_6","084_6_6","1TI","6","6","6","ואף אמנם יתרון גדול היא החסידות עם לב שמח בגורלו׃ ");
INSERT INTO heb_vpl VALUES ("T16_7","084_6_7","1TI","6","7","7","כי לא הבאנו מאומה לעולם בידוע שגם לא נוכל להוציא ממנו מאומה׃ ");
INSERT INTO heb_vpl VALUES ("T16_8","084_6_8","1TI","6","8","8","ועל כן אם יש לנו מזון וכסות נסתפקה בהם׃ ");
INSERT INTO heb_vpl VALUES ("T16_9","084_6_9","1TI","6","9","9","אבל המבקשים להעשיר יפלו בנסיון ובמוקשים וברב תאות סבלות ומשחיתות המשקיעות את האדם בשחת ובאבדון׃ ");
INSERT INTO heb_vpl VALUES ("T16_10","084_6_10","1TI","6","10","10","כי שרש כל הרעות אהבת הכסף ויש אשר ערגו לו ויסורו מן האמונה ויעציבו את נפשם במכאבים רבים׃ ");
INSERT INTO heb_vpl VALUES ("T16_11","084_6_11","1TI","6","11","11","ואתה איש האלהים ברח לך מאלה ורדף צדקה וחסידות ואמונה ואהבה וסבלנות וענוה׃ ");
INSERT INTO heb_vpl VALUES ("T16_12","084_6_12","1TI","6","12","12","הלחם המלחמה הטובה של האמונה ואחז חיי עולמים אשר נקראת להם והודית הודאה יפה בפני עדים רבים׃ ");
INSERT INTO heb_vpl VALUES ("T16_13","084_6_13","1TI","6","13","13","הנני מצוך נגד האלהים המחיה את כל ונגד המשיח ישוע אשר העיד ההודאה היפה לפני פנטיוס פילטוס׃ ");
INSERT INTO heb_vpl VALUES ("T16_14","084_6_14","1TI","6","14","14","כי שמור תשמר את המצוה באין שמץ ודפי עד הופעת המשיח ישוע אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("T16_15","084_6_15","1TI","6","15","15","אשר יראנה בעתה המברך והשליט לבדו מלך המלכים ואדני האדנים׃ ");
INSERT INTO heb_vpl VALUES ("T16_16","084_6_16","1TI","6","16","16","אשר הוא לבדו חי וקים והוא הדר באור נשגב ואיש לא ראהו ולא יוכל לראונו ולו הכבוד וגבורת עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("T16_17","084_6_17","1TI","6","17","17","את עשירי העולם הזה תצוה שלא ירום לבבם גם לא יבטחו בעשר הבוגד כי אם באלהים חיים המספיק לנו די והותר לשבע׃ ");
INSERT INTO heb_vpl VALUES ("T16_18","084_6_18","1TI","6","18","18","ויגמלו טוב ויעשירו במעשים טובים לתת מהונם ולעזר לזולתם׃ ");
INSERT INTO heb_vpl VALUES ("T16_19","084_6_19","1TI","6","19","19","ויאצרו להם אוצר ליסוד טוב לעתיד שישיגו את חיי העולם׃ ");
INSERT INTO heb_vpl VALUES ("T16_20","084_6_20","1TI","6","20","20","אתה טימותיוס שמר את הפקדון והתרחק מדברי הבל הפסולים ומן וכוחי המדע הנקרא כן בשקר׃ ");
INSERT INTO heb_vpl VALUES ("T16_21","084_6_21","1TI","6","21","21","אשר יש מתפארים בו ויתעו מן האמונה׃  (I Timothy 6:22) החסד עמך אמן׃  ");
INSERT INTO heb_vpl VALUES ("T21_1","085_1_1","2TI","1","1","1","פולוס שליח ישוע המשיח ברצון האלהים לפי הבטחת החיים אשר בישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("T21_2","085_1_2","2TI","1","2","2","אל טימותיוס בנו החביב חסד ורחמים ושלום מאת אלהים אבינו ומאת המשיח ישוע אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("T21_3","085_1_3","2TI","1","3","3","מודה אני לאלהים אשר אני עבד אותו מימי אבותי ברוח טהורה כי תמיד אזכרך בתפלותי לילה ויומם׃ ");
INSERT INTO heb_vpl VALUES ("T21_4","085_1_4","2TI","1","4","4","ונכספתי לראותך בזכרי את דמעותיך למען אמלא שמחה׃ ");
INSERT INTO heb_vpl VALUES ("T21_5","085_1_5","2TI","1","5","5","כי באתי לזכר את אמונתך בלתי צבועה ששכנה כבר בלואיס זקנתך ובאבניקה אמך ומבטח אני כי תשכן גם בך׃ ");
INSERT INTO heb_vpl VALUES ("T21_6","085_1_6","2TI","1","6","6","על כן אזכירך שתעורר את מתנת האלהים הנתונה לך בסמיכת ידי׃ ");
INSERT INTO heb_vpl VALUES ("T21_7","085_1_7","2TI","1","7","7","כי האלהים לא נתן לנו רוח אימה כי אם רוח גבורה ואהבה ומוסר׃ ");
INSERT INTO heb_vpl VALUES ("T21_8","085_1_8","2TI","1","8","8","לכן אל תבוש לא מעדות אדנינו ולא ממני אסירו כי אם תסבל הרעות גם אתה כמוני על הבשורה כפי כח האלהים׃ ");
INSERT INTO heb_vpl VALUES ("T21_9","085_1_9","2TI","1","9","9","אשר הוא הושיענו וקראנו בקריאה קדושה לא לפי מעשינו כי אם לפי עצתו וחסדו הנתן לנו במשיח ישוע לפני ימות עולם׃ ");
INSERT INTO heb_vpl VALUES ("T21_10","085_1_10","2TI","1","10","10","ועתה נגלה בהראות מושיענו ישוע המשיח אשר בטל את המות ויוצא לאור על ידי הבשורה את החיים ואת אשר איננו עובר׃ ");
INSERT INTO heb_vpl VALUES ("T21_11","085_1_11","2TI","1","11","11","אשר הפקדתי להיות לה כרוז ושליח ומורה הגוים׃ ");
INSERT INTO heb_vpl VALUES ("T21_12","085_1_12","2TI","1","12","12","ובעבור זאת אסבל כאלה ולא אבוש כי יודע אנכי במי האמנתי ומבטח אנכי כי היכלת לו לשמר את פקדוני עד היום ההוא׃ ");
INSERT INTO heb_vpl VALUES ("T21_13","085_1_13","2TI","1","13","13","החזק בתכונת הדברים הבריאים אשר שמעת ממני באמונה ובאהבה אשר במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("T21_14","085_1_14","2TI","1","14","14","שמר את הפקדון הטוב בעזרת רוח הקדש השכן בנו׃ ");
INSERT INTO heb_vpl VALUES ("T21_15","085_1_15","2TI","1","15","15","זאת אתה יודע כי פנו ממני כל אשר באסיא ובתוכם פוגלוס והרמוגניס׃ ");
INSERT INTO heb_vpl VALUES ("T21_16","085_1_16","2TI","1","16","16","יתן האדון רחמים לבית אניסיפורוס כי פעמים רבות השיב את נפשי ולא בוש ממוסרי׃ ");
INSERT INTO heb_vpl VALUES ("T21_17","085_1_17","2TI","1","17","17","כי אם בהיותו ברומי יגע לבקשני עד כי מצאני׃ ");
INSERT INTO heb_vpl VALUES ("T21_18","085_1_18","2TI","1","18","18","יתן לו האדון למצא רחמים מלפני יהוה ביום ההוא ורב שרותו אשר שרת באפסוס אתה ידעת היטב׃ ");
INSERT INTO heb_vpl VALUES ("T22_1","085_2_1","2TI","2","1","1","לכן בני התחזק בחסד אשר במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("T22_2","085_2_2","2TI","2","2","2","ואת אשר שמעת ממני בפני עדים רבים תפקידנו בידי אנשים נאמנים אשר הם כשרים ללמד גם את האחרים׃ ");
INSERT INTO heb_vpl VALUES ("T22_3","085_2_3","2TI","2","3","3","וסבל הרעות כאיש חיל בצבא מלחמת ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("T22_4","085_2_4","2TI","2","4","4","איש יצא לצבא לא יתערב בעשקי החיים למען יהיה רצוי לשר הצבא׃ ");
INSERT INTO heb_vpl VALUES ("T22_5","085_2_5","2TI","2","5","5","וגם אם נאבק איש לא יכתר אם לא יאבק כמשפט׃ ");
INSERT INTO heb_vpl VALUES ("T22_6","085_2_6","2TI","2","6","6","האכר העבד הוא יאכל ראשונה מפרי האדמה׃ ");
INSERT INTO heb_vpl VALUES ("T22_7","085_2_7","2TI","2","7","7","בין באשר אני אמר כי האדון יתן לך חכמה בכל דבר׃ ");
INSERT INTO heb_vpl VALUES ("T22_8","085_2_8","2TI","2","8","8","זכור תזכר את ישוע המשיח הנעור מן המתים אשר הוא מזרע דוד כפי בשורתי׃ ");
INSERT INTO heb_vpl VALUES ("T22_9","085_2_9","2TI","2","9","9","אשר בעבורה אני נשא רעות עד למוסרות כעשה עול אבל דבר האלהים איננו נאסר׃ ");
INSERT INTO heb_vpl VALUES ("T22_10","085_2_10","2TI","2","10","10","ועל כן אסבל את כל למען הבחירים למען ישיגו גם המה את התשועה במשיח ישוע עם כבוד עולמים׃ ");
INSERT INTO heb_vpl VALUES ("T22_11","085_2_11","2TI","2","11","11","נאמן הדבר הזה כי אם מתנו אתו גם אתו נחיה׃ ");
INSERT INTO heb_vpl VALUES ("T22_12","085_2_12","2TI","2","12","12","אם נסבל גם נמלך אתו ואם ננכר גם הוא ינכר אתנו׃ ");
INSERT INTO heb_vpl VALUES ("T22_13","085_2_13","2TI","2","13","13","אם לא נאמין הנה הוא קים באמונתו כי לכחש בעצמו לא יוכל׃ ");
INSERT INTO heb_vpl VALUES ("T22_14","085_2_14","2TI","2","14","14","זאת הזכר להם והעד לפני האדון שלא לעשק במחלקת מלים אשר לא להועיל רק לעות דעת השמעים׃ ");
INSERT INTO heb_vpl VALUES ("T22_15","085_2_15","2TI","2","15","15","היה שקוד להתיצב נאמן לפני אלהים וכפעל אשר לא יבוש המחלק על נכון דבר האמת׃ ");
INSERT INTO heb_vpl VALUES ("T22_16","085_2_16","2TI","2","16","16","אבל תרחק מדברי הבל הפסולים כי יוסיפו הרבות רשע׃ ");
INSERT INTO heb_vpl VALUES ("T22_17","085_2_17","2TI","2","17","17","ושיחתם כרקב תאכל סביב אשר מהם הומניוס ופיליטוס׃ ");
INSERT INTO heb_vpl VALUES ("T22_18","085_2_18","2TI","2","18","18","אשר תעו מן האמת באמרם כי תחית המתים כבר היתה ויבלבלו אמונת קצת אנשים׃ ");
INSERT INTO heb_vpl VALUES ("T22_19","085_2_19","2TI","2","19","19","אך איתן הוא יסוד האלהים וזה חותמו ידע יהוה את אשר לו ועוד יסור מעול כל הקורא את שם המשיח׃ ");
INSERT INTO heb_vpl VALUES ("T22_20","085_2_20","2TI","2","20","20","כי בבית גדול לא כלי זהב וכסף בלבד אלא גם של עץ ושל חרש ומהם לכבוד ומהם לבזיון׃ ");
INSERT INTO heb_vpl VALUES ("T22_21","085_2_21","2TI","2","21","21","והנה אם טהר איש את נפשו מאלה יהיה כלי לכבוד מקדש ומועיל לבעל הבית מוכן לכל מעשה טוב׃ ");
INSERT INTO heb_vpl VALUES ("T22_22","085_2_22","2TI","2","22","22","ברח לך מתאות הנעורים ורדף צדק ואמונה ואהבה ושלום עם כל הקראים אל יהוה בלב טהור׃ ");
INSERT INTO heb_vpl VALUES ("T22_23","085_2_23","2TI","2","23","23","ותרחק מן השאלות התפלות באין מוסר באשר תדע כי אך קטטה מולידות הנה׃ ");
INSERT INTO heb_vpl VALUES ("T22_24","085_2_24","2TI","2","24","24","ועבד האדון לא יתקוטט אלא יהי נוח לכל ומבין ללמד וסבלן׃ ");
INSERT INTO heb_vpl VALUES ("T22_25","085_2_25","2TI","2","25","25","ומיסר בנמיכות רוח את המתנגדים אולי יתן האלהים בלבבם לשוב להכרת האמת׃ ");
INSERT INTO heb_vpl VALUES ("T22_26","085_2_26","2TI","2","26","26","ויעירו ממוקשי השטן אשר צדם בהם לרצונו׃ ");
INSERT INTO heb_vpl VALUES ("T23_1","085_3_1","2TI","3","1","1","וזאת תדע כי באחרית הימים יבאו עתים קשות׃ ");
INSERT INTO heb_vpl VALUES ("T23_2","085_3_2","2TI","3","2","2","כי יהיו האנשים אהבי עצמם ואהבי בצע והוללים וגאים ומגדפים וממרים באבותם וכפויי טובה ולא חסידים׃ ");
INSERT INTO heb_vpl VALUES ("T23_3","085_3_3","2TI","3","3","3","חסרי אהבה ובוגדים ומלשינים וזוללים ואכרזים ושנאי טוב׃ ");
INSERT INTO heb_vpl VALUES ("T23_4","085_3_4","2TI","3","4","4","ומסרים ופחזים וגבהי רוח והלכים אחרי תענוגים יותר מאחרי האלהים׃ ");
INSERT INTO heb_vpl VALUES ("T23_5","085_3_5","2TI","3","5","5","ואשר דמיון חסידות להם ומכחשים בכחה ואתה סור מאלה׃ ");
INSERT INTO heb_vpl VALUES ("T23_6","085_3_6","2TI","3","6","6","כי יש בהם הבאים בלאט אל הבתים ושבים נשים טעונות חטאים ונתעות בתאות שנות׃ ");
INSERT INTO heb_vpl VALUES ("T23_7","085_3_7","2TI","3","7","7","הלמדות תמיד ולעולם אינן יכלות לבוא לידיעת האמת׃ ");
INSERT INTO heb_vpl VALUES ("T23_8","085_3_8","2TI","3","8","8","כי כמו יניס וימבריס אשר קמו על משה כן גם אלה מתקוממים אל האמת אנשים אשר נשחתה דעתם ונמאסים בדבר האמונה׃ ");
INSERT INTO heb_vpl VALUES ("T23_9","085_3_9","2TI","3","9","9","אכן לא יוסיפו להצליח כי שגעונם יגלה לכל כאשר קרה גם את האנשים ההם׃ ");
INSERT INTO heb_vpl VALUES ("T23_10","085_3_10","2TI","3","10","10","אבל אתה הלכת אחרי בהוראה ובהנהגה וברצון ובאמונה ובארך הרוח ובאהבה ובסבלנות׃ ");
INSERT INTO heb_vpl VALUES ("T23_11","085_3_11","2TI","3","11","11","וברדיפות ובענוים אשר מצאוני באנטיוכיא ובאקוניא ובלוסטרא ואלה הרדיפות סבלתי ומכלן הצילני האדון׃ ");
INSERT INTO heb_vpl VALUES ("T23_12","085_3_12","2TI","3","12","12","וגם כל החפצים לחיות חיי חסידות במשיח ישוע המה ירדפו׃ ");
INSERT INTO heb_vpl VALUES ("T23_13","085_3_13","2TI","3","13","13","ואנשים רעים וקסמים יוסיפו סרה מתעים ונתעים׃ ");
INSERT INTO heb_vpl VALUES ("T23_14","085_3_14","2TI","3","14","14","אבל אתה עמד במה שלמדת והבטחת כי יודע אתה מי הוא אשר למדת ממנו׃ ");
INSERT INTO heb_vpl VALUES ("T23_15","085_3_15","2TI","3","15","15","ומנעוריך ידעת את כתבי הקדש היכלים להחכימך אל הישועה על ידי האמונה במשיח ישוע׃ ");
INSERT INTO heb_vpl VALUES ("T23_16","085_3_16","2TI","3","16","16","כי כל הכתוב נכתב ברוח אלהים גם מועיל להורת ולהוכיח ולישר וליסר בצדק׃ ");
INSERT INTO heb_vpl VALUES ("T23_17","085_3_17","2TI","3","17","17","למען אשר יהיה איש האלהים תמים ומהיר לכל מעשה טוב׃ ");
INSERT INTO heb_vpl VALUES ("T24_1","085_4_1","2TI","4","1","1","לכן אני מעיד בך נגד האלהים ונגד אדנינו ישוע המשיח הבא לשפט את החיים ואת המתים בהופעתו ובמלכותו׃ ");
INSERT INTO heb_vpl VALUES ("T24_2","085_4_2","2TI","4","2","2","הכרז את הדבר והתמד בין בעתו בין שלא בעתו הוכח וגער והזהר בכל ארך רוח והוראה׃ ");
INSERT INTO heb_vpl VALUES ("T24_3","085_4_3","2TI","4","3","3","כי בוא תבא העת אשר לא יכילו את הלקח הבריא כי אם כאות נפשם יקבצו להם מורים לשעשעי אזנים׃ ");
INSERT INTO heb_vpl VALUES ("T24_4","085_4_4","2TI","4","4","4","ויטו אזניהם מן האמת ויפנו אל ההגדות׃ ");
INSERT INTO heb_vpl VALUES ("T24_5","085_4_5","2TI","4","5","5","אבל אתה היה ער בכל סבל הרעות ועשה מלאכת המבשר ומלא את שרותך׃ ");
INSERT INTO heb_vpl VALUES ("T24_6","085_4_6","2TI","4","6","6","כי עתה זה אסך נסך ועת פטירתי הגיעה׃ ");
INSERT INTO heb_vpl VALUES ("T24_7","085_4_7","2TI","4","7","7","המלחמה הטובה נלחמתי את המרוצה השלמתי את האמונה שמרתי׃ ");
INSERT INTO heb_vpl VALUES ("T24_8","085_4_8","2TI","4","8","8","ומעתה שמור לי כתר הצדקה אשר ביום ההוא יתננו לי האדון השפט הצדיק ולא לי לבדי כי גם לכל אהבי הופעתו׃ ");
INSERT INTO heb_vpl VALUES ("T24_9","085_4_9","2TI","4","9","9","חושה לבוא אלי במהרה׃ ");
INSERT INTO heb_vpl VALUES ("T24_10","085_4_10","2TI","4","10","10","כי דימס עזבני באהבתו את העולם הזה וילך לו לתסלוניקי וקריסקיס הלך לגלטיא וטיטוס לדלמטיא׃ ");
INSERT INTO heb_vpl VALUES ("T24_11","085_4_11","2TI","4","11","11","ולוקס הוא לבדו עמדי קח את מרקוס והביאהו אתך כי יועיל לי למאד לעבודה׃ ");
INSERT INTO heb_vpl VALUES ("T24_12","085_4_12","2TI","4","12","12","את טוכיקוס שלחתי לאפסוס׃ ");
INSERT INTO heb_vpl VALUES ("T24_13","085_4_13","2TI","4","13","13","את המטפחת שהנחתי בטרואס אצל קרפוס הביאהו אתך בבואך ואף את הספרים ובפרט את המגלות של קלף׃ ");
INSERT INTO heb_vpl VALUES ("T24_14","085_4_14","2TI","4","14","14","אלכסנדר חרש הנחשת עשה לי רעות רבות ישלם לו יהוה כמעשיו׃ ");
INSERT INTO heb_vpl VALUES ("T24_15","085_4_15","2TI","4","15","15","וגם אתה השמר לך ממנו כי מרו מרה את דברינו׃ ");
INSERT INTO heb_vpl VALUES ("T24_16","085_4_16","2TI","4","16","16","בהתנצלותי הראשונה לא היה איש לעזרני כי כלם עזבוני אל יחשב להם עון׃ ");
INSERT INTO heb_vpl VALUES ("T24_17","085_4_17","2TI","4","17","17","אבל האדון הוא עזרני וחזקני למען תשלם על ידי הבשורה וישמעוה כל הגוים ואנצל מפי אריה׃ ");
INSERT INTO heb_vpl VALUES ("T24_18","085_4_18","2TI","4","18","18","ויצילני האדון מכל מעשה רע ויושיעני אל מלכותו שבשמים לו הכבוד לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("T24_19","085_4_19","2TI","4","19","19","שאל לשלום פריסקה ועקילס ובית אניסיפורוס׃ ");
INSERT INTO heb_vpl VALUES ("T24_20","085_4_20","2TI","4","20","20","ארסטוס נשאר בקורנתוס ואת טרופימוס הנחתי חולה במילטוס׃ ");
INSERT INTO heb_vpl VALUES ("T24_21","085_4_21","2TI","4","21","21","חושה לבוא לפני הסתיו אובולוס ופודיס ולינוס וקלודיה והאחים כלם שאלים לשלומך׃ ");
INSERT INTO heb_vpl VALUES ("T24_22","085_4_22","2TI","4","22","22","אדנינו ישוע המשיח יהי עם רוחך החסד עמכם אמן׃ ");
INSERT INTO heb_vpl VALUES ("TT1_1","086_1_1","TIT","1","1","1","פולוס עבד אלהים ושליח ישוע המשיח לפי אמונת בחירי אלהים ודעת האמת אשר לחסידות׃ ");
INSERT INTO heb_vpl VALUES ("TT1_2","086_1_2","TIT","1","2","2","עלי תקות חיי העולם אשר הבטיח לפני ימות עולם האל אשר לא ישקר׃ ");
INSERT INTO heb_vpl VALUES ("TT1_3","086_1_3","TIT","1","3","3","וגלה במועדו את דברו על ידי הקריאה המפקדה בידי על פי מצות האלהים מושיענו׃ ");
INSERT INTO heb_vpl VALUES ("TT1_4","086_1_4","TIT","1","4","4","אל טיטוס בנו האמתי לפי אמונה אחת חסד ורחמים ושלום מאת האלהים אבינו ואדנינו ישוע המשיח מושיענו׃ ");
INSERT INTO heb_vpl VALUES ("TT1_5","086_1_5","TIT","1","5","5","לזאת עזבתיך בקריטי למען תשלים את החסד ותשים זקנים בכל עיר ועיר כאשר צויתיך׃ ");
INSERT INTO heb_vpl VALUES ("TT1_6","086_1_6","TIT","1","6","6","אם ימצא איש תם ובעל אשה אחת ויש לו בנים מאמינים ואין עליהם טענת פריצות ואינם סוררים׃ ");
INSERT INTO heb_vpl VALUES ("TT1_7","086_1_7","TIT","1","7","7","כי פקיד העדה צריך להיות איש תם כסכן לאלהים לא עמד על דעתו ולא רגזן ולא אהב יין ולא בעל אגרף ולא נטה אחרי הבצע׃ ");
INSERT INTO heb_vpl VALUES ("TT1_8","086_1_8","TIT","1","8","8","כי אם יהי מכניס ארחים ואהב טוב וצנוע וצדיק וקדוש וכבש את יצרו׃ ");
INSERT INTO heb_vpl VALUES ("TT1_9","086_1_9","TIT","1","9","9","ומחזיק בדבר הנאמן כפי ההוראה למען יהיה בכחו להזהיר בלקח הבריא ולהוכיח את המריבים׃ ");
INSERT INTO heb_vpl VALUES ("TT1_10","086_1_10","TIT","1","10","10","כי יש הרבה מרדים מדברי הבל ומתעי נפש ובפרט מן המולים׃ ");
INSERT INTO heb_vpl VALUES ("TT1_11","086_1_11","TIT","1","11","11","אשר סכור יסכר פיהם ההפכים בתים כלם בהורותם דברים לא כנים עקב בצע׃ ");
INSERT INTO heb_vpl VALUES ("TT1_12","086_1_12","TIT","1","12","12","וכבר אמר אחד מהם נביאם אשר בתוכם בני קריטי כזבים הם מעולם וחיות רעות וכרשים עצלים׃ ");
INSERT INTO heb_vpl VALUES ("TT1_13","086_1_13","TIT","1","13","13","והעדות הזאת אמת היא ובעבור כן תוכיחם תוכחה קשה למען יהיו בריאים באמונה׃ ");
INSERT INTO heb_vpl VALUES ("TT1_14","086_1_14","TIT","1","14","14","ולא ישימו לב אל הגדות היהודים ואל מצות האנשים הסרים מן האמת׃ ");
INSERT INTO heb_vpl VALUES ("TT1_15","086_1_15","TIT","1","15","15","הן הכל טהור לטהורים אבל לנטמאים ולאינם מאמינים אין דבר טהור כי נטמאה גם דעתם גם רוחם׃ ");
INSERT INTO heb_vpl VALUES ("TT1_16","086_1_16","TIT","1","16","16","אמרים המה כי ידעו את האלהים ובמעשיהם כופרים בו כי מתעבים וממרים הם ולא יצלחו לכל מעשה טוב׃ ");
INSERT INTO heb_vpl VALUES ("TT2_1","086_2_1","TIT","2","1","1","ואתה דבר את הנאה ללקח הבריא׃ ");
INSERT INTO heb_vpl VALUES ("TT2_2","086_2_2","TIT","2","2","2","שיהיו הזקנים משלים ברוחם ומכבדים וצנועים ובריאים באמונה ובאהבה ובסבלנות׃ ");
INSERT INTO heb_vpl VALUES ("TT2_3","086_2_3","TIT","2","3","3","וכן הזקנות תהי הנהגתן כאשר נאוה לקדש לא תהיינה מלשינות ולא נכבשות לסבוא יין כי אם מלמדות טוב׃ ");
INSERT INTO heb_vpl VALUES ("TT2_4","086_2_4","TIT","2","4","4","ומישרות את הצעירות לאהב את בעליהן ולאהב את בניהן׃ ");
INSERT INTO heb_vpl VALUES ("TT2_5","086_2_5","TIT","2","5","5","ולהיות צנועות וטהרות צופיות הליכות ביתן וטבות ונכנעות לבעליהן למען לא יחלל דבר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("TT2_6","086_2_6","TIT","2","6","6","ככה תזהיר גם את הבחורים שיהיו צנועים׃ ");
INSERT INTO heb_vpl VALUES ("TT2_7","086_2_7","TIT","2","7","7","ובכל דבר היה אתה למופת במעשים טובים בהוראה צרופה ונהדרה׃ ");
INSERT INTO heb_vpl VALUES ("TT2_8","086_2_8","TIT","2","8","8","ובדבר בריא ומום אין בו למען יבוש המתקומם ולא ימצא לדבר עליכם רע׃ ");
INSERT INTO heb_vpl VALUES ("TT2_9","086_2_9","TIT","2","9","9","העבדים יכנעו לאדניהם ויתרצו להם בכל דבר ולא ימרו את דבריהם׃ ");
INSERT INTO heb_vpl VALUES ("TT2_10","086_2_10","TIT","2","10","10","ולא ימעלו מעל כי אם יראו כל אמונה טובה למען יפארו בכל את לקח אלהינו מושיענו׃ ");
INSERT INTO heb_vpl VALUES ("TT2_11","086_2_11","TIT","2","11","11","כי הופיע חסד אלהים להושיע את כל בני האדם׃ ");
INSERT INTO heb_vpl VALUES ("TT2_12","086_2_12","TIT","2","12","12","וליסר אתנו אשר נתעב הרשע ותאות העולם ונחיה בעולם הזה בצניעות ובצדק ובחסידות׃ ");
INSERT INTO heb_vpl VALUES ("TT2_13","086_2_13","TIT","2","13","13","ונחכה לתקוה המאשרת ולהופעת כבוד אלהינו הגדול ומושיענו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("TT2_14","086_2_14","TIT","2","14","14","אשר נתן את נפשו בעדנו לגאלנו מכל עול ולטהר לו עם סגלה הזריז במעשים טובים׃ ");
INSERT INTO heb_vpl VALUES ("TT2_15","086_2_15","TIT","2","15","15","את אלה תדבר ותזהיר ותוכיח בכל חזקה ואיש אל יבוז לך׃ ");
INSERT INTO heb_vpl VALUES ("TT3_1","086_3_1","TIT","3","1","1","הזכר אתם להכנע ולשמע לשרים ולשלטונים ולהיות נכונים לכל מעשה טוב׃ ");
INSERT INTO heb_vpl VALUES ("TT3_2","086_3_2","TIT","3","2","2","ולבלתי גדף אדם ולחדל מריב ולהכריע לכף זכות ולהתנהג בכל ענוה לפני כל אדם׃ ");
INSERT INTO heb_vpl VALUES ("TT3_3","086_3_3","TIT","3","3","3","כי גם אנחנו היינו מלפנים חסרי דעת וסוררים ותועים ועבדים לתאות ולתשוקות שנות ומתהלכים ברשעה וקנאה ושנואים ושנאים איש את אחיו׃ ");
INSERT INTO heb_vpl VALUES ("TT3_4","086_3_4","TIT","3","4","4","אמנם כאשר נגלה נעם אלהים מושיענו ורחמנותו אל האדם׃ ");
INSERT INTO heb_vpl VALUES ("TT3_5","086_3_5","TIT","3","5","5","אז לא בגלל מעשי הצדקה אשר עשינו הושיע אתנו כי אם מתוך חסדו על ידי טבילת התולדה השניה וחדוש רוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("TT3_6","086_3_6","TIT","3","6","6","אשר שפך עלינו למכביר על ידי ישוע המשיח מושיענו׃ ");
INSERT INTO heb_vpl VALUES ("TT3_7","086_3_7","TIT","3","7","7","למען נצדק בחסדו ונירש לפי התקוה את חיי העולמים׃ ");
INSERT INTO heb_vpl VALUES ("TT3_8","086_3_8","TIT","3","8","8","נאמן הוא הדבר ורצה אני כי תקים את אלה למען אשר ישתדלו המאמינים לאלהים לעשק במעשים טובים עשות כאלה טוב הוא ומועיל לאדם׃ ");
