INSERT INTO heb_vpl VALUES ("TT3_12","086_3_12","TIT","3","12","12","כאשר אשלח אליך את ארטמס או את טוכיקוס תמהר לבוא אלי לניקפליס כי גמרתי בלבי לשבת שם בימי הסתיו׃ ");
