INSERT INTO heb_vpl VALUES ("TT3_15","086_3_15","TIT","3","15","15","כל אשר עמדי שאלים לשלומך שאל לשלום האהבים אתנו באמונה החסד עם כלכם אמן׃ ");
INSERT INTO heb_vpl VALUES ("PM1_1","087_1_1","PHM","1","1","1","פולוס אסיר המשיח ישוע וטימותיוס האח אל פילימון החביב והעזר אתנו׃ ");
INSERT INTO heb_vpl VALUES ("PM1_2","087_1_2","PHM","1","2","2","ואל אפיה האהובה ואל ארכפוס חבר מלחמתינו ואל הקהלה אשר בביתך׃ ");
