INSERT INTO heb_vpl VALUES ("HB4_2","088_4_2","HEB","4","2","2","כי גם אלינו באה הבשורה כמו אליהם אך לא הועיל להם דבר השמועה מפני אשר לא התערב באמונה לשמעים׃ ");
INSERT INTO heb_vpl VALUES ("HB4_3","088_4_3","HEB","4","3","3","כי באי המונה אנחנו המאמינים כמו שאמר אשר נשבעתי באפי אם יבאון אל מנוחתי אף כי נגמרו מעשי יהוה מעת הוסד העולם׃ ");
INSERT INTO heb_vpl VALUES ("HB4_4","088_4_4","HEB","4","4","4","כי על היום השביעי אמר במקום אחד וישבת ביום השביעי מכל מלאכתו׃ ");
INSERT INTO heb_vpl VALUES ("HB4_5","088_4_5","HEB","4","5","5","ובמקום הזה אמר עוד אם יבאון אל מנוחתי׃ ");
