INSERT INTO heb_vpl VALUES ("HB4_7","088_4_7","HEB","4","7","7","לכן הוסיף לקבוע יום באמרו היום על ידי דוד מקץ ימים רבים כמו שנאמר היום אם בקלו תשמעו אל תקשו לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("HB4_8","088_4_8","HEB","4","8","8","כי אלו יהושע הניח להם לא היה מדבר אחרי זאת על יום אחר׃ ");
INSERT INTO heb_vpl VALUES ("HB4_9","088_4_9","HEB","4","9","9","על כן נשארה עוד מנוחת שבת לעם אלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB4_10","088_4_10","HEB","4","10","10","כי הבא אל מנוחתו גם הוא שבת ממלאכתו כמו האלהים משלו׃ ");
INSERT INTO heb_vpl VALUES ("HB4_11","088_4_11","HEB","4","11","11","לכן נשקדה נא לבוא אל המנוחה ההיא למען אשר לא יכשל איש והיה ממרה כמוהם׃ ");
INSERT INTO heb_vpl VALUES ("HB4_12","088_4_12","HEB","4","12","12","כי דבר האלהים חי הוא ופעל גבורות וחד מחרב פיפיות ונכנס עד להבדיל בין נפש לרוח ובין הדבקים למוח ובחן מחשבות לבב ומזמותיו׃ ");
INSERT INTO heb_vpl VALUES ("HB4_13","088_4_13","HEB","4","13","13","ואין כל נברא נסתר מנגדו כי הכל חשוף וגלוי לעיני בעל דברים שלנו׃ ");
INSERT INTO heb_vpl VALUES ("HB4_14","088_4_14","HEB","4","14","14","ועתה בהיות לנו כהן ראש גדול אשר עבר בשמים הוא ישוע בן האלהים נחזיקה בהודאתנו׃ ");
INSERT INTO heb_vpl VALUES ("HB4_15","088_4_15","HEB","4","15","15","כי אין לנו כהן גדול אשר לא יוכל להצטער על חליינו כי אם המנסה בכל כמונו אך בלי חטא׃ ");
INSERT INTO heb_vpl VALUES ("HB4_16","088_4_16","HEB","4","16","16","על כן נקרבה בבטחון אל כסא החסד לשאת רחמים ולמצא חסד לעזרה בעתה׃ ");
INSERT INTO heb_vpl VALUES ("HB5_1","088_5_1","HEB","5","1","1","כי כל כהן גדול הלקוח מתוך בני אדם מפקד הוא בעבור בני אדם בעניני אלהים להקריב מנחה וזבח על החטאים׃ ");
INSERT INTO heb_vpl VALUES ("HB5_2","088_5_2","HEB","5","2","2","והוא יכול לחמל על השגגים והתעים בהיותו גם הוא ידוע חלי׃ ");
INSERT INTO heb_vpl VALUES ("HB5_3","088_5_3","HEB","5","3","3","אשר על כן חיב להקריב על החטאים גם בעד העם גם בעד נפשו׃ ");
INSERT INTO heb_vpl VALUES ("HB5_4","088_5_4","HEB","5","4","4","ואת הגדלה הזאת לא יקח איש לעצמו רק הקרוא לה מאת האלהים כמו אהרן׃ ");
INSERT INTO heb_vpl VALUES ("HB5_5","088_5_5","HEB","5","5","5","כן גם המשיח לא כבד את עצמו להיות כהן גדול כי אם האמר אליו בני אתה אני היום ילדתיך׃ ");
INSERT INTO heb_vpl VALUES ("HB5_6","088_5_6","HEB","5","6","6","כמו שאמר גם במקום אחר אתה כהן לעולם על דברתי מלכי צדק׃ ");
INSERT INTO heb_vpl VALUES ("HB5_7","088_5_7","HEB","5","7","7","אשר בימי היותו בבשר הקריב תפלות ותחנונים בצעקה גדולה ובדעות לפני מי שיכול להושיעו ממות ויעתר לו מפני יראתו׃ ");
INSERT INTO heb_vpl VALUES ("HB5_8","088_5_8","HEB","5","8","8","ואף כי היה הבן למד מענותו לשמוע׃ ");
INSERT INTO heb_vpl VALUES ("HB5_9","088_5_9","HEB","5","9","9","ואחרי אשר השלם היה ממציא תשועת עולמים לכל שמעיו׃ ");
INSERT INTO heb_vpl VALUES ("HB5_10","088_5_10","HEB","5","10","10","והאלהים קרא לו כהן גדול על דברתי מלכי צדק׃ ");
INSERT INTO heb_vpl VALUES ("HB5_11","088_5_11","HEB","5","11","11","על זאת יש לנו לדבר הרבה וקשות לבאר לכם במלין יען כי כבדו אזניכם׃ ");
INSERT INTO heb_vpl VALUES ("HB5_12","088_5_12","HEB","5","12","12","כי תחת אשר היה ראוי לכם לפי ארך הזמן להיות מלמדים עתה מן הצרך לשוב וללמד אתכם עקרי ראשית דברי אלהים ונצרכתם לחלב ולא למאכל בריא׃ ");
INSERT INTO heb_vpl VALUES ("HB5_13","088_5_13","HEB","5","13","13","כי כל אשר מאכלו חלב איננו מבין בדבר צדק כי עודנו עולל׃ ");
INSERT INTO heb_vpl VALUES ("HB5_14","088_5_14","HEB","5","14","14","אך לשלמים המאכל הבריא אשר על פי ההרגל יש להם חושים מנסים להבדיל בין טוב לרע׃ ");
INSERT INTO heb_vpl VALUES ("HB6_1","088_6_1","HEB","6","1","1","על כן בעזב כעת ראשית דבר המשיח נעבר אל השלמות ולא נשוב לשית יסודי התשובה ממעשי מות והאמונה באלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB6_2","088_6_2","HEB","6","2","2","ותורת הטבילות וסמיכת ידים ותחית המתים והדין הנצחי׃ ");
INSERT INTO heb_vpl VALUES ("HB6_3","088_6_3","HEB","6","3","3","ואת זאת נעשה אם יתן האל׃ ");
INSERT INTO heb_vpl VALUES ("HB6_4","088_6_4","HEB","6","4","4","כי אלה אשר נגה עליהם האור וטעמו ממתנת השמים ונתן להם חלקם ברוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("HB6_5","088_6_5","HEB","6","5","5","וטעמו את דבר אלהים הטוב וכחות העולם הבא וימעלו מעל׃ ");
INSERT INTO heb_vpl VALUES ("HB6_6","088_6_6","HEB","6","6","6","נמנעו מהתחדש עוד לתשובה כי צלבו להם מחדש את בן האלהים ויתנוהו למשל׃ ");
INSERT INTO heb_vpl VALUES ("HB6_7","088_6_7","HEB","6","7","7","כי האדמה השותה את הגשם הירד עליה למכביר ומוציאה עשב טוב לעבדיה תשא ברכה מאת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB6_8","088_6_8","HEB","6","8","8","ואשר תוציא קוץ ודרדר נמאסה היא וקרובה למארה וסופה להשרף׃ ");
INSERT INTO heb_vpl VALUES ("HB6_9","088_6_9","HEB","6","9","9","אמנם ידידי מבטחים אנחנו בכם טבות מאלה וקרבות לישועה אף כי דברנו כזאת׃ ");
INSERT INTO heb_vpl VALUES ("HB6_10","088_6_10","HEB","6","10","10","כי האלהים לא יעות צדק לשכח את מעשיכם ואת עמל אהבתכם אשר הראיתם לשמו ששרתם ועודכם משרתים את הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("HB6_11","088_6_11","HEB","6","11","11","אבל חפצנו שכל אחד מכם גם ישקד שקוד להחזיק בשלמות התקוה עד הקץ׃ ");
INSERT INTO heb_vpl VALUES ("HB6_12","088_6_12","HEB","6","12","12","שלא תעצלו כי אם תלכו בעקבות היורשים באמונה וארך רוח את ההבטחות׃ ");
INSERT INTO heb_vpl VALUES ("HB6_13","088_6_13","HEB","6","13","13","כי בהבטיח אלהים את אברהם נשבע בנפשו יען אשר אין גדול ממנו להשבע בו׃ ");
INSERT INTO heb_vpl VALUES ("HB6_14","088_6_14","HEB","6","14","14","ויאמר כי ברך אברכך והרבה ארבה אותך׃ ");
INSERT INTO heb_vpl VALUES ("HB6_15","088_6_15","HEB","6","15","15","ויהי בהאריך נפשו השיג את ההבטחה׃ ");
INSERT INTO heb_vpl VALUES ("HB6_16","088_6_16","HEB","6","16","16","בני האדם ישבעו בגדול מהם והשבועה להם קץ כל ערעור לקיום הדבר׃ ");
INSERT INTO heb_vpl VALUES ("HB6_17","088_6_17","HEB","6","17","17","על כן כאשר רצה האלהים להראות ביותר את ירשי ההבטחה כי לא תשתנה עצתו ערב אתה בשבועה׃ ");
INSERT INTO heb_vpl VALUES ("HB6_18","088_6_18","HEB","6","18","18","למען על פי שני דברים בלתי משתנים אשר חלילה לאלהים לשקר בם יהיה לנו אשר נסנו עליו זרוז גדול לאחז בתקוה הנתונה לפנינו׃ ");
INSERT INTO heb_vpl VALUES ("HB6_19","088_6_19","HEB","6","19","19","אשר היא לנפשנו לעוגין נכון וחזק ומגיע אל מבית לפרכת׃ ");
INSERT INTO heb_vpl VALUES ("HB6_20","088_6_20","HEB","6","20","20","אשר בא שמה ישוע העבר לפנינו ויהי כהן גדול לעולם על דברתי מלכי צדק׃ ");
INSERT INTO heb_vpl VALUES ("HB7_1","088_7_1","HEB","7","1","1","כי זה מלכי צדק מלך שלם כהן לאל עליון אשר יצא לקראת אברהם בשובו מהכות את המלכים ויברכהו׃ ");
INSERT INTO heb_vpl VALUES ("HB7_2","088_7_2","HEB","7","2","2","ואשר חלק לו אברהם מעשר מכל שמו יפרש מלך הצדק ועוד מלך שלם הוא מלך השלום׃ ");
INSERT INTO heb_vpl VALUES ("HB7_3","088_7_3","HEB","7","3","3","באין אב באין אם באין יחש ולימיו אין תחלה ולחייו אין סוף כי אם נדמה לבן האלהים הוא עומד בכהנתו לנצח׃ ");
INSERT INTO heb_vpl VALUES ("HB7_4","088_7_4","HEB","7","4","4","ראו עתה מה גדול הוא אשר גם אברהם אבינו נתן לו מעשר מראשית השלל׃ ");
INSERT INTO heb_vpl VALUES ("HB7_5","088_7_5","HEB","7","5","5","הן אלה מבני לוי אשר נחלי את הכהנה יש להם חק על פי התורה לקחת את המעשרות מן העם מן אחיהם אשר אף הם יצאי ירך אברהם׃ ");
INSERT INTO heb_vpl VALUES ("HB7_6","088_7_6","HEB","7","6","6","ואשר איננו מתיחש למשפחתם הוא לקח את המעשר מן אברהם ויברך את אשר היתה לו ההבטחה׃ ");
INSERT INTO heb_vpl VALUES ("HB7_7","088_7_7","HEB","7","7","7","והנה נכון הדבר כי הקטן יברך על ידי הגדול ממנו׃ ");
INSERT INTO heb_vpl VALUES ("HB7_8","088_7_8","HEB","7","8","8","ופה בני אדם שימותו לקחים את המעשר אבל שם לקחו מי שהועד עליו כי הוא חי׃ ");
INSERT INTO heb_vpl VALUES ("HB7_9","088_7_9","HEB","7","9","9","ויתכן לומר כי גם לוי הלקח את המעשרות היה מעשר בעשר אברהם׃ ");
INSERT INTO heb_vpl VALUES ("HB7_10","088_7_10","HEB","7","10","10","כי עוד בירך האב היה בצאת מלכי צדק לקראתו׃ ");
INSERT INTO heb_vpl VALUES ("HB7_11","088_7_11","HEB","7","11","11","על כן אלו היתה שלמות על ידי כהנת בני לוי אשר בה נתנה התורה לעם למה זה צריך לקום עוד כהן אחר על דברתי מלכי צדק ולא יאמר על דברתי אהרן׃ ");
INSERT INTO heb_vpl VALUES ("HB7_12","088_7_12","HEB","7","12","12","כי בהשתנות הכהנה מן הצרך שתשתנה גם התורה׃ ");
INSERT INTO heb_vpl VALUES ("HB7_13","088_7_13","HEB","7","13","13","כי אשר מדבר בו כזאת הוא משבט אחר אשר מעולם לא שרת איש ממנו את המזבח׃ ");
INSERT INTO heb_vpl VALUES ("HB7_14","088_7_14","HEB","7","14","14","כי גלוי לכל אשר אדנינו זרח מיהודה מן השבט אשר משה לא דבר אליו דבר על הכהנה׃ ");
INSERT INTO heb_vpl VALUES ("HB7_15","088_7_15","HEB","7","15","15","ועוד יותר ברור הוא אם יוקם על דמיון מלכי צדק כהן אחר׃ ");
INSERT INTO heb_vpl VALUES ("HB7_16","088_7_16","HEB","7","16","16","אשר איננו על פי חקת בשר ודם אלא על פי כח חיים בלתי נפסקים׃ ");
INSERT INTO heb_vpl VALUES ("HB7_17","088_7_17","HEB","7","17","17","כי העיד עליו אתה כהן לעולם על דברתי מלכי צדק׃ ");
INSERT INTO heb_vpl VALUES ("HB7_18","088_7_18","HEB","7","18","18","בעבור כי המצוה הקדמת הוסרה בהיותה חלושה וקצרת יד מהועיל׃ ");
INSERT INTO heb_vpl VALUES ("HB7_19","088_7_19","HEB","7","19","19","כי התורה לא השלימה דבר והנה נכנסה במקומה תקוה טובה ממנה אשר נקרב על ידה לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB7_20","088_7_20","HEB","7","20","20","וכפי אשר לא היתה זאת בלי שבועה׃ ");
INSERT INTO heb_vpl VALUES ("HB7_21","088_7_21","HEB","7","21","21","כי המה נתכהנו בלי שבועה וזה בשבועה על ידי האמר לו נשבע יהוה ולא ינחם אתה כהן לעולם על דברתי מלכי צדק׃ ");
INSERT INTO heb_vpl VALUES ("HB7_22","088_7_22","HEB","7","22","22","גם הברית טובה ויתרה היא אשר ישוע ערב אותה׃ ");
INSERT INTO heb_vpl VALUES ("HB7_23","088_7_23","HEB","7","23","23","ושם נתכהנו רבים מפני אשר המות לא הניחם להותר בארץ׃ ");
INSERT INTO heb_vpl VALUES ("HB7_24","088_7_24","HEB","7","24","24","אבל זה בעמדו לעולם יש לו כהנה אשר לא תעבר ממנו׃ ");
INSERT INTO heb_vpl VALUES ("HB7_25","088_7_25","HEB","7","25","25","אשר על כן יוכל גם להושיע בכל וכל את הנגשים על ידו לאלהים כי חי הוא תמיד להפגיע בעדם׃ ");
INSERT INTO heb_vpl VALUES ("HB7_26","088_7_26","HEB","7","26","26","כי נאוה לנו כהן כזה שהוא חסיד ותמים וטהור ונבדל מן החטאים ונשא מהשמים׃ ");
INSERT INTO heb_vpl VALUES ("HB7_27","088_7_27","HEB","7","27","27","אשר איננו צריך יום יום ככהנים הגדולים ההם להקריב בראשונה על חטאתיו ואחרי כן על חטאת העם כי זאת עשה בפעם אחת בהקריבו את נפשו׃ ");
INSERT INTO heb_vpl VALUES ("HB7_28","088_7_28","HEB","7","28","28","כי התורה העמידה לכהנים גדולים בני אדם חלשים אבל דבר השבועה הבאה אחרי התורה העמיד את הבן המשלם לעולם׃ ");
INSERT INTO heb_vpl VALUES ("HB8_1","088_8_1","HEB","8","1","1","וזה ראש הנאמרים כי יש לנו כהן גדול היושב לימין כסא הגבורה בשמים׃ ");
INSERT INTO heb_vpl VALUES ("HB8_2","088_8_2","HEB","8","2","2","והוא משרת הקדש והמשכן האמתי אשר כוננו אדני ולא אדם׃ ");
INSERT INTO heb_vpl VALUES ("HB8_3","088_8_3","HEB","8","3","3","כי כל כהן גדול הוא מפקד להקריב מנחות וזבחים ועל כן צריך שיהיה גם לזה דבר להקריב׃ ");
INSERT INTO heb_vpl VALUES ("HB8_4","088_8_4","HEB","8","4","4","והנה אלו היה בארץ לא היה כהן כי יש פה הכהנים המקריבים הקרבנות לפי התורה׃ ");
INSERT INTO heb_vpl VALUES ("HB8_5","088_8_5","HEB","8","5","5","ומכהנים לדמות וצל הדברים שבשמים כדבר יהוה אל משה בבאו לכלות את המשכן כי אמר אליו ראה ועשה הכל בתבניתו אשר אתה מראה בהר׃ ");
INSERT INTO heb_vpl VALUES ("HB8_6","088_8_6","HEB","8","6","6","ועתה הוא קבל שרות מעלה כפי מעלת הברית הנעשה על ידו אשר הוקמה על הבטחות טבות ויתרות׃ ");
INSERT INTO heb_vpl VALUES ("HB8_7","088_8_7","HEB","8","7","7","כי אלו היתה הראשונה ההיא תמימה לא יבקש מקום לשניה׃ ");
INSERT INTO heb_vpl VALUES ("HB8_8","088_8_8","HEB","8","8","8","כי כה אמר בהוכיח אתם הנה ימים באים נאם יהוה וכרתי את בית ישראל ואת בית יהודה ברית חדשה׃ ");
INSERT INTO heb_vpl VALUES ("HB8_9","088_8_9","HEB","8","9","9","לא כברית אשר כרתי את אבותם ביום החזיקי בידם להוציאם מארץ מצרים אשר המה הפרו את בריתי ואנכי בחלתי בם נאם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("HB8_10","088_8_10","HEB","8","10","10","כי זאת הברית אשר אכרת את בית ישראל אחרי הימים ההם נאם יהוה נתתי את תורתי בקרבם ועל לבם אכתבנה והייתי להם לאלהים והמה יהיו לי לעם׃ ");
INSERT INTO heb_vpl VALUES ("HB8_11","088_8_11","HEB","8","11","11","ולא ילמדו עוד איש את רעהו ואיש את אחיו לאמר דעו את יהוה כי כולם ידעו אותי למקטנם ועד גדולם׃ ");
INSERT INTO heb_vpl VALUES ("HB8_12","088_8_12","HEB","8","12","12","כי אסלח לעונם ולחטאתם ולפשעיהם לא אזכר עוד׃ ");
INSERT INTO heb_vpl VALUES ("HB8_13","088_8_13","HEB","8","13","13","הנה באמרו ברית חדשה ישן את הראשונה ומה שהוא נושן ומזקין קרוב הוא אל קצו׃ ");
INSERT INTO heb_vpl VALUES ("HB9_1","088_9_1","HEB","9","1","1","הן היה גם לברית הראשונה משפטי העבודה ומקדש ארצי׃ ");
INSERT INTO heb_vpl VALUES ("HB9_2","088_9_2","HEB","9","2","2","כי הוקם המשכן החיצון אשר בו המנורה והשלחן ומערכת הלחם והוא נקרא קדש׃ ");
INSERT INTO heb_vpl VALUES ("HB9_3","088_9_3","HEB","9","3","3","ומבית לפרכת השנית משכן הנקרא קדש הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("HB9_4","088_9_4","HEB","9","4","4","אשר לו מזבח הזהב לקטרת וארון הברית מצפה זהב כלו ובו צנצנת זהב אשר המן בתוכו ומטה אהרן אשר פרח ולוחות הברית׃ ");
INSERT INTO heb_vpl VALUES ("HB9_5","088_9_5","HEB","9","5","5","וממעל לו כרובי הכבוד הסככים על הכפרת לא נדבר כעת על כל אחד מהם בפרט׃ ");
INSERT INTO heb_vpl VALUES ("HB9_6","088_9_6","HEB","9","6","6","ואחרי שהוכנו אלה ככה באו הכהנים תמיד אל המשכן החיצון לעבד שם את עבודתם׃ ");
INSERT INTO heb_vpl VALUES ("HB9_7","088_9_7","HEB","9","7","7","ואל המשכן אשר לפנים ממנו בא שמה הכהן הגדול לבדו פעם אחת בשנה לא בבלי דם אשר יקריב בעד נפשו ובעד שגגות העם׃ ");
INSERT INTO heb_vpl VALUES ("HB9_8","088_9_8","HEB","9","8","8","ורוח הקדש מודיע בזאת כי לא נגלה הדרך אל הקדש כל הימים אשר המשכן החיצון יש לו לעמד׃ ");
INSERT INTO heb_vpl VALUES ("HB9_9","088_9_9","HEB","9","9","9","והוא משל על העת ההוה אשר בה מקריבים מנחות וזבחים אשר לא יוכלו להשלים את לבב העבד׃ ");
INSERT INTO heb_vpl VALUES ("HB9_10","088_9_10","HEB","9","10","10","אך משפטי הגוף המה עם המאכלות והמשקים והטבילות השנות אשר הושמו עד עת התקון׃ ");
INSERT INTO heb_vpl VALUES ("HB9_11","088_9_11","HEB","9","11","11","אבל המשיח בבאו להיות כהן גדול לטבות העתידות עבר בתוך המשכן המעלה בגדלה ושלמות אשר לא נעשה בידים כלומר אשר איננו בכלל הבריאה הזאת׃ ");
INSERT INTO heb_vpl VALUES ("HB9_12","088_9_12","HEB","9","12","12","גם לא בא בדם שעירים ועגלים אלא בדם נפשו בא בפעם אחת אל הקדש פנימה וימצא גאלת עולם׃ ");
INSERT INTO heb_vpl VALUES ("HB9_13","088_9_13","HEB","9","13","13","כי אם דם הפרים והשעירים ואפר הפרה אשר יזה על הטמאים יקדשם לטהרת גופם׃ ");
INSERT INTO heb_vpl VALUES ("HB9_14","088_9_14","HEB","9","14","14","אף כי דם המשיח אשר הקריב את עצמו לאלהים ברוח נצחי ובלי מום יטהר לבבכם ממעשי מות לעבד את אלהים חיים׃ ");
INSERT INTO heb_vpl VALUES ("HB9_15","088_9_15","HEB","9","15","15","ובעבור זאת הוא גם סרסר לברית חדשה למען אשר יירשו המקראים את הבטחת נחלת עולם אחרי אשר מת לפדות מן הפשעים אשר נעשו תחת הברית הראשונה׃ ");
INSERT INTO heb_vpl VALUES ("HB9_16","088_9_16","HEB","9","16","16","כי במקום שיש דיתיקי צריך לדעת מות מקימה׃ ");
INSERT INTO heb_vpl VALUES ("HB9_17","088_9_17","HEB","9","17","17","כי רק במות המת תכון דיתיקי ואיננה בתקפה בעוד מקימה בחיים׃ ");
INSERT INTO heb_vpl VALUES ("HB9_18","088_9_18","HEB","9","18","18","לכן גם הראשונה לא חנכה בלא דם׃ ");
INSERT INTO heb_vpl VALUES ("HB9_19","088_9_19","HEB","9","19","19","כי ככלות משה להגיד לכל העם את כל המצות כתורה לקח דם העגלים והשעירים עם מים ותולעת שני ואזוב ויזרק על הספר ועל כל העם׃ ");
INSERT INTO heb_vpl VALUES ("HB9_20","088_9_20","HEB","9","20","20","ויאמר הנה דם הברית אשר צוה אלהים אליכם׃ ");
INSERT INTO heb_vpl VALUES ("HB9_21","088_9_21","HEB","9","21","21","וכן הזה מן הדם על המשכן ועל כל כלי השרת׃ ");
INSERT INTO heb_vpl VALUES ("HB9_22","088_9_22","HEB","9","22","22","וכמעט הכל יטהר בדם על פי התורה ואין כפרה בלי שפיכת דם׃ ");
INSERT INTO heb_vpl VALUES ("HB9_23","088_9_23","HEB","9","23","23","לכן דמיוני הדברים שבשמים צריכים להטהר באלה והדברים שבשמים בעצמם צריכים להטהר בזבחים טובים מאלה׃ ");
INSERT INTO heb_vpl VALUES ("HB9_24","088_9_24","HEB","9","24","24","כי המשיח לא בא אל הקדש הנעשה בידים שהוא רק דמות האמתי כי אם בא אל עצם השמים לראות עתה בעדנו את פני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB9_25","088_9_25","HEB","9","25","25","אף לא להקריב את נפשו פעמים רבות ככהן הגדול אשר בא שנה בשנה אל הקדש בדם אחרים׃ ");
INSERT INTO heb_vpl VALUES ("HB9_26","088_9_26","HEB","9","26","26","כי אם כן הוא הלא היה לו לענות פעמים רבות מראשית העולם ועתה בקץ העתים נגלה בפעם אחת כדי לבטל את החטא בזבח נפשו׃ ");
INSERT INTO heb_vpl VALUES ("HB9_27","088_9_27","HEB","9","27","27","וכאשר נגזר על בני אדם פעם אחת המות ואחריו הדין׃ ");
INSERT INTO heb_vpl VALUES ("HB9_28","088_9_28","HEB","9","28","28","כן הקרב המשיח פעם אחת למען שאת חטאי רבים ופעם שנית יראה בלי חטא לישועה למחכים לו׃ ");
INSERT INTO heb_vpl VALUES ("HB10_1","088_10_1","HEB","10","1","1","כי התורה בהיות בה צל הטבות העתידות ולא מראה עצם הדברים אין ביכלתה להשלים את הקרבים בקרבנות ההם אשר יקריבו תמיד מדי שנה בשנה׃ ");
INSERT INTO heb_vpl VALUES ("HB10_2","088_10_2","HEB","10","2","2","כי לולא זאת חדלו מהביאם באשר המקריבים בהטהרם פעם אחת לא היתה בהם עוד רגשת חטאים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_3","088_10_3","HEB","10","3","3","אבל יש שם הזכרת החטאים שנה בשנה׃ ");
INSERT INTO heb_vpl VALUES ("HB10_4","088_10_4","HEB","10","4","4","כי דם הפרים והשעירים לא יוכל להסיר חטאים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_5","088_10_5","HEB","10","5","5","ובעבור זאת אמר בבואו לעולם זבח ומנחה לא חפצת גוף כוננת לי׃ ");
INSERT INTO heb_vpl VALUES ("HB10_6","088_10_6","HEB","10","6","6","עולה וחטאה לא שאלת׃ ");
INSERT INTO heb_vpl VALUES ("HB10_7","088_10_7","HEB","10","7","7","אז אמרתי הנה באתי במגלת ספר כתוב עלי לעשות רצונך אלהי׃ ");
INSERT INTO heb_vpl VALUES ("HB10_8","088_10_8","HEB","10","8","8","אחרי אמרו למעלה זבח ומנחה עולה וחטאה לא חפצת ולא שאלת אשר יקריבו אתם על פי התורה׃ ");
INSERT INTO heb_vpl VALUES ("HB10_9","088_10_9","HEB","10","9","9","אז אמר הנה באתי לעשות רצונך אלהי מעביר בזה את הראשונה למען הקים את השניה׃ ");
INSERT INTO heb_vpl VALUES ("HB10_10","088_10_10","HEB","10","10","10","וברצון הזה מקדשים אנחנו על ידי הקרבת קרבן גוף ישוע המשיח בפעם אחת׃ ");
INSERT INTO heb_vpl VALUES ("HB10_11","088_10_11","HEB","10","11","11","וכל כהן עמד יום יום לשרת ומוסיף פעמים רבות להקריב אתן הקרבנות אשר לא יוכלו לעולם להעביר חטאים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_12","088_10_12","HEB","10","12","12","אולם זה אחרי הקריבו זבח אחד על החטאים ישב עד עולם לימין האלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_13","088_10_13","HEB","10","13","13","וחכה יחכה עד כי יושתו איביו הדם לרגליו׃ ");
INSERT INTO heb_vpl VALUES ("HB10_14","088_10_14","HEB","10","14","14","כי הוא בקרבן אחת השלים לנצח את המקדשים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_15","088_10_15","HEB","10","15","15","ואף רוח הקדש מעיד לנו על זאת כי אחרי אמרו׃ ");
INSERT INTO heb_vpl VALUES ("HB10_16","088_10_16","HEB","10","16","16","זאת הברית אשר אכרת אתם אחרי הימים ההם אמר יהוה נתתי את תורתי בקרבם ועל לבם אכתבנה׃ ");
INSERT INTO heb_vpl VALUES ("HB10_17","088_10_17","HEB","10","17","17","ולעונם ולחטאתם לא אזכר עוד׃ ");
INSERT INTO heb_vpl VALUES ("HB10_18","088_10_18","HEB","10","18","18","והנה באשר נסלחו החטאים אין עוד קרבן עליהם׃ ");
INSERT INTO heb_vpl VALUES ("HB10_19","088_10_19","HEB","10","19","19","ועתה אחי בהיות לנו בטחון דרך הקדש בדם ישוע׃ ");
INSERT INTO heb_vpl VALUES ("HB10_20","088_10_20","HEB","10","20","20","דרך חדש וחי אשר חדש לנו בפרכת היא בשרו׃ ");
INSERT INTO heb_vpl VALUES ("HB10_21","088_10_21","HEB","10","21","21","ובהיות לנו כהן גדול על בית אלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_22","088_10_22","HEB","10","22","22","נקרבה נא בלבב שלם ובאמונה תמימה מטהרים בהזית לבבנו מרוח רעה ורחוצי בשר במים טהורים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_23","088_10_23","HEB","10","23","23","נחזיקה בהודית התקוה בל נמוט כי נאמן המבטיח׃ ");
INSERT INTO heb_vpl VALUES ("HB10_24","088_10_24","HEB","10","24","24","ונתבוננה זה על זה לעורר אתנו לאהבה ולמעשים טובים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_25","088_10_25","HEB","10","25","25","ואל נעזב את כנאיתנו כמנהג קצת אנשים כי אם נוכיח איש את אחיו וביותר בראתכם כי קרוב היום׃ ");
INSERT INTO heb_vpl VALUES ("HB10_26","088_10_26","HEB","10","26","26","כי אם נחטא בזדון אחרי אשר קבלנו דעת האמת לא ישאר עוד זבח קרבן לכפר על החטא׃ ");
INSERT INTO heb_vpl VALUES ("HB10_27","088_10_27","HEB","10","27","27","כי אם בעותי הדין העתיד ואש קנאה אשר תאכל את הצררים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_28","088_10_28","HEB","10","28","28","הן איש כי יפר תורת משה מות ימות בלי חמלה על פי שנים עדים או שלשה׃ ");
INSERT INTO heb_vpl VALUES ("HB10_29","088_10_29","HEB","10","29","29","מה תחשבו כמה יגדל הענש הראוי לרמס ברגלו את בן האלהים וחשב לחל את דם הברית אשר הוא מקדש בו ומחרף את רוח החסד׃ ");
INSERT INTO heb_vpl VALUES ("HB10_30","088_10_30","HEB","10","30","30","כי ידענו את האמר לי נקם ושלם ועוד כי ידין יהוה עמו׃ ");
INSERT INTO heb_vpl VALUES ("HB10_31","088_10_31","HEB","10","31","31","מה נורא לנפל ביד אלהים חיים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_32","088_10_32","HEB","10","32","32","אבל זכרו נא את הימים הראשונים כי אז אחרי ארו עיניכם נשאתם כבד ענוים רבים׃ ");
INSERT INTO heb_vpl VALUES ("HB10_33","088_10_33","HEB","10","33","33","פעם בהיותכם לראי בחרפה ותוגה פעם בהשתתף לאשר הגיע אליהם כזאת׃ ");
INSERT INTO heb_vpl VALUES ("HB10_34","088_10_34","HEB","10","34","34","כי הצטערתם על מוסרי וגזלת רכושכם סבלתם בשמחה מדעתכם בנפשכם שיש לכם בשמים קנין טוב ממנו וקים לעד׃ ");
INSERT INTO heb_vpl VALUES ("HB10_35","088_10_35","HEB","10","35","35","לכן אל תשליכו את בטחונכם כי יש לו שכר רב׃ ");
INSERT INTO heb_vpl VALUES ("HB10_36","088_10_36","HEB","10","36","36","כי צריכים אתם לסבלנות למען תעשו רצון אלהים ונשאתם את ההבטחה׃ ");
INSERT INTO heb_vpl VALUES ("HB10_37","088_10_37","HEB","10","37","37","כי עוד מעט רגע והבא יבא לא יאחר׃ ");
INSERT INTO heb_vpl VALUES ("HB10_38","088_10_38","HEB","10","38","38","הצדיק באמונתו יחיה ואם יסג אחור לא רצתה נפשי בו׃ ");
INSERT INTO heb_vpl VALUES ("HB10_39","088_10_39","HEB","10","39","39","אמנם אנחנו איננו מן הנסוגים אחור לאבדם כי אם מן המאמינים להצלת הנפש׃ ");
INSERT INTO heb_vpl VALUES ("HB11_1","088_11_1","HEB","11","1","1","כי האמונה היא חסן הבטחון במקוה והוכחת דברים לא נראים׃ ");
INSERT INTO heb_vpl VALUES ("HB11_2","088_11_2","HEB","11","2","2","ובה נחלו האבות עדות׃ ");
INSERT INTO heb_vpl VALUES ("HB11_3","088_11_3","HEB","11","3","3","באמונה נבין כי העולמות נעשו בדבר האלהים למען אשר יצא הנראה מן הנעלם׃ ");
INSERT INTO heb_vpl VALUES ("HB11_4","088_11_4","HEB","11","4","4","באמונה הקריב הבל לאלהים זבח טוב מקין אשר היה לו לעדות כי צדיק הוא בהעיד אלהים על מנחתיו ובה עודנו מדבר אחרי מותו׃ ");
INSERT INTO heb_vpl VALUES ("HB11_5","088_11_5","HEB","11","5","5","באמונה לקח חנוך לבלתי ראותו המות ואיננו כי לקח אתו אלהים והועד עליו לפני הלקחו כי את האלהים התהלך׃ ");
INSERT INTO heb_vpl VALUES ("HB11_6","088_11_6","HEB","11","6","6","ובלי אמונה לא יוכל איש להיות רצוי אל האלהים כי כל הקרב אליו צריך להאמין כי יש אלהים וגמול הוא משיב לדרשיו׃ ");
INSERT INTO heb_vpl VALUES ("HB11_7","088_11_7","HEB","11","7","7","באמונה בנה נח ביראת יהוה את התבה להצלת ביתו אתרי אשר צוה על דברים לא נראים עדין וירשע בה את העולם ויהי לירש הצדקה עקב האמונה׃ ");
INSERT INTO heb_vpl VALUES ("HB11_8","088_11_8","HEB","11","8","8","באמונה שמע אברהם כאשר נקרא ללכת אל הארץ אשר יירשנה ויצא ולא ידע אנה יבוא׃ ");
INSERT INTO heb_vpl VALUES ("HB11_9","088_11_9","HEB","11","9","9","באמונה היה גר בארץ ההבטחה כמו בנכריה וישב באהלים הוא ויצחק ויעקב אשר ירשו עמו ההבטחה ההיא׃ ");
INSERT INTO heb_vpl VALUES ("HB11_10","088_11_10","HEB","11","10","10","כי חכה לעיר אשר יסודתה נאמנה ובונה ומכוננה האלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB11_11","088_11_11","HEB","11","11","11","באמונה שרה גם היא קבלה הכח להזריע ותלד אחרי בלתה כי חשבה לנאמן את המבטיח׃ ");
INSERT INTO heb_vpl VALUES ("HB11_12","088_11_12","HEB","11","12","12","על כן מאחד אשר כמעט מת גופו יצאו ככוכבי השמים לרב וכחול על שפת הים אשר לא יספר׃ ");
INSERT INTO heb_vpl VALUES ("HB11_13","088_11_13","HEB","11","13","13","כפי אמונה מתו כל אלה ולא השיגו את ההבטחות רק מרחוק ראו אותן ויבטחו וישמחו לקראתן ויודו כי גרים הם ותושבים בארץ׃ ");
INSERT INTO heb_vpl VALUES ("HB11_14","088_11_14","HEB","11","14","14","הלא המדברים כזאת יודיעו כי הם מבקשי ארץ מושב׃ ");
INSERT INTO heb_vpl VALUES ("HB11_15","088_11_15","HEB","11","15","15","ואם היתה דעתם על הארץ ההיא אשר יצאו ממנה הלא היה בידם לשוב אליה׃ ");
INSERT INTO heb_vpl VALUES ("HB11_16","088_11_16","HEB","11","16","16","אכן נכספו למושב טוב ממנו והוא בשמים ועל כן לא בוש האלהים להקרא אלהיהם כי הכין להם עיר׃ ");
INSERT INTO heb_vpl VALUES ("HB11_17","088_11_17","HEB","11","17","17","באמונה העלה אברהם את יצחק כאשר נסה ואת יחידו הקריב המקבל את ההבטחות׃ ");
INSERT INTO heb_vpl VALUES ("HB11_18","088_11_18","HEB","11","18","18","אשר נאמר לו כי ביצחק יקרא לך זרע׃ ");
INSERT INTO heb_vpl VALUES ("HB11_19","088_11_19","HEB","11","19","19","ויחשב בלבו כי יכול יוכל אלהים להחיות גם את המתים על כן גם הושב אליו להיות למשל׃ ");
INSERT INTO heb_vpl VALUES ("HB11_20","088_11_20","HEB","11","20","20","באמונה ברך יצחק את יעקב ואת עשו וידבר על העתידות׃ ");
INSERT INTO heb_vpl VALUES ("HB11_21","088_11_21","HEB","11","21","21","באמונה ברך יעקב את שני בני יוסף לפני מותו וישתחו על ראש המטה׃ ");
INSERT INTO heb_vpl VALUES ("HB11_22","088_11_22","HEB","11","22","22","באמונה הזכיר יוסף בקרב קצו את יציאת בני ישראל ויצו על אדות עצמותיו׃ ");
INSERT INTO heb_vpl VALUES ("HB11_23","088_11_23","HEB","11","23","23","באמונה הצפינו את משה אבותיו שלשה ירחים אהרי הולדו כראתם את הילד כי טוב הוא ולא יראו את מצות המלך׃ ");
INSERT INTO heb_vpl VALUES ("HB11_24","088_11_24","HEB","11","24","24","באמונה מאן משה כאשר גדל להקרא בן לבת פרעה׃ ");
INSERT INTO heb_vpl VALUES ("HB11_25","088_11_25","HEB","11","25","25","ויבחר לסבל את עני עם אלהים מלהתענג לשעה בתענוגי החטא׃ ");
INSERT INTO heb_vpl VALUES ("HB11_26","088_11_26","HEB","11","26","26","בחשבו את חרפת המשיח לעשר גדול מאצרות מצרים כי הביט אל הגמול׃ ");
INSERT INTO heb_vpl VALUES ("HB11_27","088_11_27","HEB","11","27","27","באמונה עזב את ארץ מצרים ולא ירא מחמת המלך כי היה כראה אשר איננו נראה ויתחזק׃ ");
INSERT INTO heb_vpl VALUES ("HB11_28","088_11_28","HEB","11","28","28","באמונה עשה את הפסח ונתינת הדם למען אשר לא יגע המשחית בבכוריהם׃ ");
INSERT INTO heb_vpl VALUES ("HB11_29","088_11_29","HEB","11","29","29","באמונה עברו את ים סוף ביבשה אשר נסו מצרים גם המה לעבר בו ויטבעו׃ ");
INSERT INTO heb_vpl VALUES ("HB11_30","088_11_30","HEB","11","30","30","באמונה נפלו חומות יריחו אחרי הקיפו אותן שבעת ימים׃ ");
INSERT INTO heb_vpl VALUES ("HB11_31","088_11_31","HEB","11","31","31","באמונה לא אבדה רחב הזונה עם הסוררים כי אספה את המרגלים אל ביתה בשלום׃ ");
INSERT INTO heb_vpl VALUES ("HB11_32","088_11_32","HEB","11","32","32","ומה אמר עוד הן תקצר לי העת אם אספר מעשי גדעון וברק ושמשון ויפתח ודוד ושמואל והנביאים׃ ");
INSERT INTO heb_vpl VALUES ("HB11_33","088_11_33","HEB","11","33","33","אשר באמונה כבשו ממלכות ופעלו צדק והשגו הבטחות וסכרו פי אריות׃ ");
INSERT INTO heb_vpl VALUES ("HB11_34","088_11_34","HEB","11","34","34","וכבו גבורת האש ונמלטו מפי החרב והתחזקו מחלים ועשו חיל במלחמה והפילו מחנות זרים׃ ");
INSERT INTO heb_vpl VALUES ("HB11_35","088_11_35","HEB","11","35","35","נשים לקחו מתחיה את מתיהן ואחרים רטשו בענוים ולא אבו להנצל למען יזכו לתחיה טובה ממנה׃ ");
INSERT INTO heb_vpl VALUES ("HB11_36","088_11_36","HEB","11","36","36","מהם נסו בתעלולים ובמכות וגם נמסרו לכבל ומסגר׃ ");
INSERT INTO heb_vpl VALUES ("HB11_37","088_11_37","HEB","11","37","37","נסקלו באבנים נסרו במגרה נבחנו ביסורים מתו לפי חרב וינעו עטופי עורת כבשים ועזים בחסר ובעצר רעה ויגון׃ ");
INSERT INTO heb_vpl VALUES ("HB11_38","088_11_38","HEB","11","38","38","אשר העולם לא היה כדי להם הם תעו במדבר ובהרים ובמערות ובנקיקי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("HB11_39","088_11_39","HEB","11","39","39","וכל אלה אף היתה להם העדות בגלל אמונתם לא קבלו את ההבטחה׃ ");
INSERT INTO heb_vpl VALUES ("HB11_40","088_11_40","HEB","11","40","40","למען אשר לא ישלמו בלעדינו כי צפה לנו אלהים מקדם טובה יתרה׃ ");
INSERT INTO heb_vpl VALUES ("HB12_1","088_12_1","HEB","12","1","1","לכן גם אנחנו אשר ענן עדים רב כזה סבב אתנו נשליכה ממנו כל טרח והחטא המקיף עלינו ונרוצה בתוחלת את המרוצה הערוכה לפנינו׃ ");
INSERT INTO heb_vpl VALUES ("HB12_2","088_12_2","HEB","12","2","2","ונביטה אל ישוע ראש האמונה ומשלימה אשר בעד השמחה השמורה לו סבל את הצלב ויבז החרפה וישב לימין כסא האלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB12_3","088_12_3","HEB","12","3","3","התבוננו אליו אשר נשא כלמת חטאים גדולה כזאת למען לא תיעפו ולא תיגעו בנפשותיכם׃ ");
INSERT INTO heb_vpl VALUES ("HB12_4","088_12_4","HEB","12","4","4","עדין לא עמדתם עד לדם במלחמתכם עם החטא׃ ");
INSERT INTO heb_vpl VALUES ("HB12_5","088_12_5","HEB","12","5","5","ותשכחו דבר הנחומים המדבר אליכם כמו אל בנים לאמר מוסר יהוה בני אל תמאס ואל תקץ בתוכחתו׃ ");
INSERT INTO heb_vpl VALUES ("HB12_6","088_12_6","HEB","12","6","6","כי את אשר יאהב יהוה יוכיח יכאב את בן ירצה׃ ");
INSERT INTO heb_vpl VALUES ("HB12_7","088_12_7","HEB","12","7","7","אם סבלים אתם מוסר דעו כי כאב עם בניו כן מתנהג אלהים עמכם כי איה הבן אשר אביו לא ייסרנו׃ ");
INSERT INTO heb_vpl VALUES ("HB12_8","088_12_8","HEB","12","8","8","אך אם תהיו באין מוסר אשר היה מנת כלם אז ממזרים אתם ולא בנים׃ ");
INSERT INTO heb_vpl VALUES ("HB12_9","088_12_9","HEB","12","9","9","ועוד אם אבות בשרנו היו מיסרים אתנו ונירא מהם אף כי נכנע לפני אבי הרוחות ונחיה׃ ");
INSERT INTO heb_vpl VALUES ("HB12_10","088_12_10","HEB","12","10","10","כי המה יסרונו כטוב בעיניהם לימים מעטים אבל זה להועיל למען יהיה לנו חלק בקדשתו׃ ");
INSERT INTO heb_vpl VALUES ("HB12_11","088_12_11","HEB","12","11","11","וכל מוסר בעת עברו עלינו איננו שמחה בעינינו כי אם יגון אולם באחריתו יתן פרי שלום לצדקה למלמדים בו׃ ");
INSERT INTO heb_vpl VALUES ("HB12_12","088_12_12","HEB","12","12","12","על כן חזקו ידים רפות וברכים כשלות׃ ");
INSERT INTO heb_vpl VALUES ("HB12_13","088_12_13","HEB","12","13","13","ומעגל רגליכם פלסו למען לא תטה הצלעה מן הדרך כי אם תרפא׃ ");
INSERT INTO heb_vpl VALUES ("HB12_14","088_12_14","HEB","12","14","14","רדפו את השלום עם כל אדם ואת הקדשה אשר בלעדיה לא יראה איש את האדון׃ ");
INSERT INTO heb_vpl VALUES ("HB12_15","088_12_15","HEB","12","15","15","והזהרו פן יש בכם איש מתאחר מחסד אלהים פן יוגיעכם שרש פרה לענה ויטמאו בו רבים׃ ");
INSERT INTO heb_vpl VALUES ("HB12_16","088_12_16","HEB","12","16","16","פן ימצא בכם זנה או חלל כעשו אשר בנזיד אחד מכר את בכורתו׃ ");
INSERT INTO heb_vpl VALUES ("HB12_17","088_12_17","HEB","12","17","17","הלא ידעתם כי גם נמאס אחרי כן כאשר רצה לרשת את הברכה כי לא מצא מקום לתשובה אף בקש אותה בדמעות׃ ");
INSERT INTO heb_vpl VALUES ("HB12_18","088_12_18","HEB","12","18","18","כי לא באתם אל הר נמשש ובער באש ולא אל ענן וערפל וסערה׃ ");
INSERT INTO heb_vpl VALUES ("HB12_19","088_12_19","HEB","12","19","19","ולא לקול שופר ולקול הדברים אשר שמעיו בקשו שלא יוסיף לדבר עמהם עוד׃ ");
INSERT INTO heb_vpl VALUES ("HB12_20","088_12_20","HEB","12","20","20","כי לא יכלו לשאת את אשר צוו ואם בהמה תגע בהר סקל תקסל או ירה תירה בחצים׃ ");
INSERT INTO heb_vpl VALUES ("HB12_21","088_12_21","HEB","12","21","21","והמראה היה נורא עד מאד ויאמר משה יגרתי וחרדתי׃ ");
INSERT INTO heb_vpl VALUES ("HB12_22","088_12_22","HEB","12","22","22","כי אם באתם אל הר ציון ואל עיר אלהים חיים אל ירושלים שבשמים׃ ");
INSERT INTO heb_vpl VALUES ("HB12_23","088_12_23","HEB","12","23","23","ואל עצרת רבבות המלאכים ועדת הבכורים הכתובים בשמים ואל אלהים שפט הכל ואל רוחות הצדיקים הנשלמים׃ ");
INSERT INTO heb_vpl VALUES ("HB12_24","088_12_24","HEB","12","24","24","ואל ישוע סרסר הברית החדשה ואל דם ההזאה המיטיב דבר מדם הבל׃ ");
INSERT INTO heb_vpl VALUES ("HB12_25","088_12_25","HEB","12","25","25","לכן ראו פן תמאנו לשמע אל המדבר כי הן לא נמלטו המאנים לשמע אל המדבר עמהם בארץ אף אנחנו אם נמאן לשמע בקול המדבר מן השמים׃ ");
INSERT INTO heb_vpl VALUES ("HB12_26","088_12_26","HEB","12","26","26","אשר קולו הרעיש אז את הארץ ועתה זה הבטיח לאמר עוד אחת ואני מרעיש לא לבד את הארץ כי גם את השמים׃ ");
INSERT INTO heb_vpl VALUES ("HB12_27","088_12_27","HEB","12","27","27","וזו עוד אחת שאמר משמיע חליפת הנרעשים אשר הם עשוים למען יעמד אשר איננו נרעש׃ ");
INSERT INTO heb_vpl VALUES ("HB12_28","088_12_28","HEB","12","28","28","לכן אנחנו המקבלים מלכות אשר לא תמוט נבאה נא בתודה ונעבד בה את האלהים לרצון לו בצניעות וביראה׃ ");
INSERT INTO heb_vpl VALUES ("HB12_29","088_12_29","HEB","12","29","29","כי אלהינו אש אכלה הוא׃ ");
INSERT INTO heb_vpl VALUES ("HB13_1","088_13_1","HEB","13","1","1","אהבת האחים תעמד׃ ");
INSERT INTO heb_vpl VALUES ("HB13_2","088_13_2","HEB","13","2","2","הכנסת ארחים אל תשכחו כי יש אשר הכניסו בה מלאכים ולא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("HB13_3","088_13_3","HEB","13","3","3","זכרו את האסורים כאלו אתם אסורים עמהם ואת הנלחצים באשר גם אתם בבשר׃ ");
INSERT INTO heb_vpl VALUES ("HB13_4","088_13_4","HEB","13","4","4","האישות תיקר בכל וערש יצועכם אל יחלל את הזנים ואת המנאפים ידין אלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB13_5","088_13_5","HEB","13","5","5","רחקו מאהבת כסף ושמחו בחלקכם כי הוא אמר לא ארפך ולא אעזבך׃ ");
INSERT INTO heb_vpl VALUES ("HB13_6","088_13_6","HEB","13","6","6","על כן נבטח ונאמר יהוה לי בעזרי לא אירא מה יעשה לי אדם׃ ");
INSERT INTO heb_vpl VALUES ("HB13_7","088_13_7","HEB","13","7","7","זכרו את מנהיגיכם אשר הגידו לכם את דבר האלהים בינו לאחרית דרכם ולכו באמונתם׃ ");
INSERT INTO heb_vpl VALUES ("HB13_8","088_13_8","HEB","13","8","8","ישוע המשיח גם תמול גם היום הוא הוא וגם לעולמים׃ ");
INSERT INTO heb_vpl VALUES ("HB13_9","088_13_9","HEB","13","9","9","אל תנועו בתורות שנות וזרות כי טוב לכונן לבנו בחסד ולא בעניני מאכל אשר לא הועילו למתהלכים בהם׃ ");
INSERT INTO heb_vpl VALUES ("HB13_10","088_13_10","HEB","13","10","10","יש לנו מזבח אשר אינם רשאים לאכל מעליו משרתי המשכן׃ ");
INSERT INTO heb_vpl VALUES ("HB13_11","088_13_11","HEB","13","11","11","כי הבהמות אשר הובא דמן בקדש לכפרת החטא על ידי הכהן הגדול גויתיהן נשרפו מחוץ למחנה׃ ");
INSERT INTO heb_vpl VALUES ("HB13_12","088_13_12","HEB","13","12","12","בעבור זאת גם ישוע למען קדש בדמו את העם ענה מחוץ לשער׃ ");
INSERT INTO heb_vpl VALUES ("HB13_13","088_13_13","HEB","13","13","13","לכן נצאה נא אליו אל מחוץ למחנה ונשא את חרפתו׃ ");
INSERT INTO heb_vpl VALUES ("HB13_14","088_13_14","HEB","13","14","14","כי פה אין לנו עיר עמדת כי את העתידה אנחנו מבקשים׃ ");
INSERT INTO heb_vpl VALUES ("HB13_15","088_13_15","HEB","13","15","15","לכן נקריב על ידו בכל עת זבח תודה לאלהים היא פרי שפתים המודות לשמו׃ ");
INSERT INTO heb_vpl VALUES ("HB13_16","088_13_16","HEB","13","16","16","ואל תשכחו לגמל חסד ולתת לאביונים כי זבחים כאלה יערבו לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("HB13_17","088_13_17","HEB","13","17","17","שמעו אל מנהיגיכם והכנעו מפניהם כי שקדים הם על נפשתיכם כעתידים לתת חשבון למען יעשו זאת בשמחה ולא באנחה כי זאת לא להועיל לכם׃ ");
INSERT INTO heb_vpl VALUES ("HB13_18","088_13_18","HEB","13","18","18","התפללו בעדנו כי ידענו אשר שלמה מחשבתנו ונחפץ ללכת דרך ישרה בכל׃ ");
INSERT INTO heb_vpl VALUES ("HB13_19","088_13_19","HEB","13","19","19","ובחזקה אבקש מכם לעשות זאת למען אושב אליכם במהרה׃ ");
INSERT INTO heb_vpl VALUES ("HB13_20","088_13_20","HEB","13","20","20","ואלהי השלום אשר בדם ברית עולם העלה מן המתים את רעה הצאן הגדול את ישוע אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("HB13_21","088_13_21","HEB","13","21","21","הוא ישלימכם בכל מעשה טוב לעשות רצונו בפעלו בכם את הרצוי לפניו ביד ישוע המשיח אשר לו הכבוד לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("HB13_22","088_13_22","HEB","13","22","22","ואבקש מכם אחי שאו נא דבר התוכחה כי כתבתי אליכם בקצרה׃ ");
INSERT INTO heb_vpl VALUES ("HB13_23","088_13_23","HEB","13","23","23","ודעו כי טימותיוס אחינו יצא מבית האסורים והיה אם יבא במהרה אראה אתו את פניכם׃ ");
INSERT INTO heb_vpl VALUES ("HB13_24","088_13_24","HEB","13","24","24","שאלו לשלום כל מנהיגיכם ולשלום כל הקדשים בני ארץ איטליא שאלים לשלומכם׃ ");
INSERT INTO heb_vpl VALUES ("HB13_25","088_13_25","HEB","13","25","25","החסד עם כלכם אמן׃ ");
INSERT INTO heb_vpl VALUES ("JM1_1","089_1_1","JAS","1","1","1","יעקב עבד אלהים ואדנינו ישוע המשיח שאל לשלום שנים עשר השבטים הנפוצים׃ ");
INSERT INTO heb_vpl VALUES ("JM1_2","089_1_2","JAS","1","2","2","אך לשמחה חשבו לכם אחי כאשר תבאו בנסינות שונים׃ ");
INSERT INTO heb_vpl VALUES ("JM1_3","089_1_3","JAS","1","3","3","בדעתכם כי בחן אמונתכם מביא לידי סבלנות׃ ");
INSERT INTO heb_vpl VALUES ("JM1_4","089_1_4","JAS","1","4","4","והסבלנות שלמה תהיה בפעלה להיותכם שלמים ותמימים ולא תחסרו כל דבר׃ ");
INSERT INTO heb_vpl VALUES ("JM1_5","089_1_5","JAS","1","5","5","ואיש מכם כי יחסר חכמה יבקשנה מאלהים הנותן לכל בנדיבה ובאין גערה ותנתן לו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_6","089_1_6","JAS","1","6","6","רק יבקש באמונה ובבלי ספק כי בעל ספק דומה לגלי הים הסער והנגרש׃ ");
INSERT INTO heb_vpl VALUES ("JM1_7","089_1_7","JAS","1","7","7","והאיש ההוא אל ידמה בנפשו כי ישא דבר מאת יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JM1_8","089_1_8","JAS","1","8","8","איש אשר חלק לבו הפכפך הוא בכל דרכיו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_9","089_1_9","JAS","1","9","9","אבל האח השפל יתהלל ברוממתו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_10","089_1_10","JAS","1","10","10","והעשיר יתהלל בשפלותו כי יעבר כציץ החציר׃ ");
INSERT INTO heb_vpl VALUES ("JM1_11","089_1_11","JAS","1","11","11","כי זרח השמש בחמתו וייבש את החציר ויבל ציצו וחסד מראהו אבד כן יבול העשיר בהליכותיו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_12","089_1_12","JAS","1","12","12","אשרי האיש העמד בנסיונו כי כאשר נבחן ישא עטרת החיים אשר הבטיח יהוה לאהביו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_13","089_1_13","JAS","1","13","13","אל יאמר המנסה האלהים נסני כי האלהים איננו מנסה ברע והוא לא ינסה איש׃ ");
INSERT INTO heb_vpl VALUES ("JM1_14","089_1_14","JAS","1","14","14","כי אם ינסה כל איש בתאות נפשו אשר תסיתהו ותפתהו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_15","089_1_15","JAS","1","15","15","ואחרי כן הרתה התאות ותלד חטא והחטא כי נשלם יוליד את המות׃ ");
INSERT INTO heb_vpl VALUES ("JM1_16","089_1_16","JAS","1","16","16","אל תתעו אחי אהובי׃ ");
INSERT INTO heb_vpl VALUES ("JM1_17","089_1_17","JAS","1","17","17","כל מתנה טובה וכל מנחה שלמה תרד ממעל מאת אבי האורות אשר חלוף וכל צל שנוי אין עמו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_18","089_1_18","JAS","1","18","18","הוא בחפצו ילד אותנו בדבר האמת להיותנו כמו ראשית בכורי יצוריו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_19","089_1_19","JAS","1","19","19","על זאת אחי אהובי יהי כל איש מהיר לשמע קשה לדבר וקשה לכעוס׃ ");
INSERT INTO heb_vpl VALUES ("JM1_20","089_1_20","JAS","1","20","20","כי כעס אדם לא יפעל צדקת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("JM1_21","089_1_21","JAS","1","21","21","לכן הסירו מעליכם כל טנוף ותרבות רעה וקבלו בענוה את הדבר הנטוע בכם אשר יכל להושיע את נפשתיכם׃ ");
INSERT INTO heb_vpl VALUES ("JM1_22","089_1_22","JAS","1","22","22","והיו עשי הדבר ולא שמעיו לבד לרמות את נפשכם׃ ");
INSERT INTO heb_vpl VALUES ("JM1_23","089_1_23","JAS","1","23","23","כי האיש אשר רק שמע את הדבר ולא עשהו נמשל לאיש מביט את תאר הויתו במראה׃ ");
INSERT INTO heb_vpl VALUES ("JM1_24","089_1_24","JAS","1","24","24","כי הביט אל מראהו וילך לו וברגע שכח מה תארו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_25","089_1_25","JAS","1","25","25","אבל המשקיף בתורה השלמה תורת החרות ומחזיק בה אשר איננו שמע ושכח כי אם עשה בפעל אשרי האיש ההוא במעשהו׃ ");
INSERT INTO heb_vpl VALUES ("JM1_26","089_1_26","JAS","1","26","26","איש מכם אם ידמה להיות עבד אלהים ואיננו שם רסן ללשנו כי אם מתעה הוא את לבבו עבדתו אך לריק תהיה׃ ");
INSERT INTO heb_vpl VALUES ("JM1_27","089_1_27","JAS","1","27","27","זאת העבודה הטהורה והברה לפני האלהים אבינו לבקר את היתומים והאלמנות בלחצם ולשמר את עצמו נקי מחלאת העולם׃ ");
INSERT INTO heb_vpl VALUES ("JM2_1","089_2_1","JAS","2","1","1","אחי אל יהי משא פנים באמונתכם בישוע המשיח אדנינו אדון הכבוד׃ ");
INSERT INTO heb_vpl VALUES ("JM2_2","089_2_2","JAS","2","2","2","כי אם יבוא איש לבית כנסתכם וטבעת זהב על ידיו והוא לבוש לבשי מכלול וגם איש עני יבא שמה ובגדו מטנף׃ ");
INSERT INTO heb_vpl VALUES ("JM2_3","089_2_3","JAS","2","3","3","ופניתם אל הלבוש לבשי מכלול ואמרתם לו שב לך הנה בטוב ולעני תאמרו עמד שם או שב פה מתחת להדם רגלי׃ ");
INSERT INTO heb_vpl VALUES ("JM2_4","089_2_4","JAS","2","4","4","הלא בזאת נחלק לבכם והנכם שפטים בעלי מחשבות רעות׃ ");
INSERT INTO heb_vpl VALUES ("JM2_5","089_2_5","JAS","2","5","5","שמעו אחי אהובי הלא בעניי העולם הזה בחר האלהים להיות עשירים באמונה וירשי המלכות אשר הבטיח לאהביו׃ ");
INSERT INTO heb_vpl VALUES ("JM2_6","089_2_6","JAS","2","6","6","ואתם הכלמתם את העני הלא העשירים הם העשקים אתכם והם הסחבים אתכם אל בתי דין׃ ");
INSERT INTO heb_vpl VALUES ("JM2_7","089_2_7","JAS","2","7","7","הלא הם המגדפים את השם הטוב הנקרא עליכם׃ ");
INSERT INTO heb_vpl VALUES ("JM2_8","089_2_8","JAS","2","8","8","הן בקימכם את המצוה המלכת על כלן כפי הכתוב ואהבת לרעך כמוך תיטיבו לעשות׃ ");
INSERT INTO heb_vpl VALUES ("JM2_9","089_2_9","JAS","2","9","9","אולם אם תשאו פנים תחטאו במעשיכם והתורה תוכיחכם כעברים אותה׃ ");
INSERT INTO heb_vpl VALUES ("JM2_10","089_2_10","JAS","2","10","10","כי איש אשר יקים את כל התורה ונכשל בדבר אחד הוא אשם אשם בכלם׃ ");
INSERT INTO heb_vpl VALUES ("JM2_11","089_2_11","JAS","2","11","11","כי האמר לא תנאף גם הוא אמר לא תרצח ואם אינך נאף ואתה רוצח היה נהיית לעבר התורה׃ ");
INSERT INTO heb_vpl VALUES ("JM2_12","089_2_12","JAS","2","12","12","כן דברו וכן עשו כאנשים העתידים להשפט על פי תורת החרות׃ ");
INSERT INTO heb_vpl VALUES ("JM2_13","089_2_13","JAS","2","13","13","כי אין חסד בדין לאשר לא עשה חסד והחסד יתגאה על הדין׃ ");
INSERT INTO heb_vpl VALUES ("JM2_14","089_2_14","JAS","2","14","14","אחי מה יועיל לאיש אם יאמר כי יש לו אמונה ומעשים אין בו התוכל האמונה להושיעו׃ ");
INSERT INTO heb_vpl VALUES ("JM2_15","089_2_15","JAS","2","15","15","אח או אחות אם יהיו בעירם ובחסר לחם יומם׃ ");
INSERT INTO heb_vpl VALUES ("JM2_16","089_2_16","JAS","2","16","16","ואיש מכם יאמר אליהם לכו לשלום והתחממו ושבעו ולא תתנו להם די מחסור גופם מה תועיל זאת׃ ");
INSERT INTO heb_vpl VALUES ("JM2_17","089_2_17","JAS","2","17","17","ככה גם האמונה אם אין בה מעשים מתה היא בעצמה׃ ");
INSERT INTO heb_vpl VALUES ("JM2_18","089_2_18","JAS","2","18","18","אך יאמר איש אתה יש לך אמונה ואני יש לי מעשים הראני נא את אמונתך מתוך מעשיך ואני אראך מתוך מעשי את אמוני׃ ");
INSERT INTO heb_vpl VALUES ("JM2_19","089_2_19","JAS","2","19","19","אתה מאמין כי האלהים אחד הוא הטיבות גם השדים מאמינים בו ורעדים׃ ");
INSERT INTO heb_vpl VALUES ("JM2_20","089_2_20","JAS","2","20","20","ואתה איש בער התחפץ לדעת כי האמונה בבלי מעשים מתה היא׃ ");
INSERT INTO heb_vpl VALUES ("JM2_21","089_2_21","JAS","2","21","21","אברהם אבינו הלא במעשיו נצדק בהעלתו את יצחק בנו על המזבח׃ ");
INSERT INTO heb_vpl VALUES ("JM2_22","089_2_22","JAS","2","22","22","הנך ראה כי היתה האמונה עזרת למעשיו ומתוך המעשים השלמה האמונה׃ ");
INSERT INTO heb_vpl VALUES ("JM2_23","089_2_23","JAS","2","23","23","וימלא הכתוב האמר והאמן אברהם ביהוה ותחשב לו לצדקה ויקרא אהב יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JM2_24","089_2_24","JAS","2","24","24","הנכם ראים כי במעשים יצדק האיש ולא באמונה לבדה׃ ");
INSERT INTO heb_vpl VALUES ("JM2_25","089_2_25","JAS","2","25","25","וכן גם רחב הזונה הלא נצדקה במעשים באספה את המלאכים אל ביתה ותשלחם בדרך אחר׃ ");
INSERT INTO heb_vpl VALUES ("JM2_26","089_2_26","JAS","2","26","26","כי כאשר הגוף בלי נשמה מת הוא כן גם האמונה בלי מעשים מתה היא׃ ");
INSERT INTO heb_vpl VALUES ("JM3_1","089_3_1","JAS","3","1","1","אחי אל יהיו רבים מכם למורים באשר ידעתם כי בזאת נכביד עלינו את הדין׃ ");
INSERT INTO heb_vpl VALUES ("JM3_2","089_3_2","JAS","3","2","2","כי כלנו מרבים להכשל ואשר לא יכשל בדבור הוא איש תמים וביכלתו לשום רסן גם לכל גופו׃ ");
INSERT INTO heb_vpl VALUES ("JM3_3","089_3_3","JAS","3","3","3","הנה בפי הסוסים נשים את הרסן למען אשר ישמעו לנו ונהגנו בו את כל גויתם׃ ");
INSERT INTO heb_vpl VALUES ("JM3_4","089_3_4","JAS","3","4","4","והנה האניות אף כי גדלות הנה ורוחות קשות יהדפום ינהג אתן משוט קטן אל כל אשר יחפץ החבל כן גם הלשון אבר קטן היא וגדלות תדבר׃ ");
INSERT INTO heb_vpl VALUES ("JM3_5","089_3_5","JAS","3","5","5","ראה מה גדול היער ואש קטנה תבעירנו גם הלשון אש היא עולם מלא עולה׃ ");
INSERT INTO heb_vpl VALUES ("JM3_6","089_3_6","JAS","3","6","6","כן הלשון נצבת בין אברינו המגאלת את כל הגוף ומלהטת את גלגל הויתנו והיא להוטה באש גיהנם׃ ");
INSERT INTO heb_vpl VALUES ("JM3_7","089_3_7","JAS","3","7","7","כי מין כל בהמה ועוף ורמש וחיות הים יכבש ונכבשים הם על ידי מין האדם׃ ");
INSERT INTO heb_vpl VALUES ("JM3_8","089_3_8","JAS","3","8","8","אבל הלשון אין אדם יכל לכבשה אין מעצור לרעה הזאת וסם המות מלאה׃ ");
INSERT INTO heb_vpl VALUES ("JM3_9","089_3_9","JAS","3","9","9","בה נברך את האלהים אבינו ובה נקלל את האנשים העשוים בצלם אלהים׃ ");
INSERT INTO heb_vpl VALUES ("JM3_10","089_3_10","JAS","3","10","10","מפה אחד יצאת ברכה וקללה וכן לא יעשה אחי׃ ");
INSERT INTO heb_vpl VALUES ("JM3_11","089_3_11","JAS","3","11","11","היביע המעין מתוקים ומרים ממוצא אחד׃ ");
INSERT INTO heb_vpl VALUES ("JM3_12","089_3_12","JAS","3","12","12","אחי היוכל עץ התאנה להוציא זיתים או התוכל הגפן להוציא תאנים כן גם מעין אחד לא יוכל נבע מים מלוחים ומתוקים׃ ");
INSERT INTO heb_vpl VALUES ("JM3_13","089_3_13","JAS","3","13","13","מי בכם חכם ונבון יראה בדרכו הטובה את מעשיו בענות החכמה׃ ");
INSERT INTO heb_vpl VALUES ("JM3_14","089_3_14","JAS","3","14","14","ואם קנאה מרה ומריבה בלבבכם אל תתהללו ואל תשקרו באמת׃ ");
INSERT INTO heb_vpl VALUES ("JM3_15","089_3_15","JAS","3","15","15","אין זאת החכמה הירדת ממעל כי אם חכמת אדמה היא וחכמת היצר והשדים׃ ");
INSERT INTO heb_vpl VALUES ("JM3_16","089_3_16","JAS","3","16","16","כי במקום קנאה ומריבה שם מהומה וכל מעשה רע׃ ");
INSERT INTO heb_vpl VALUES ("JM3_17","089_3_17","JAS","3","17","17","אבל החכמה אשר ממעל בראשונה צנועה היא אף אהבת שלום ומכרעת לכף זכות ואיננה עמדת על דעתה ומלאה רחמים ופרי טוב בלא לב ולב ובלי חנפה׃ ");
INSERT INTO heb_vpl VALUES ("JM3_18","089_3_18","JAS","3","18","18","ופרי הצדקה בשלום יזרע לעשי השלום׃ ");
INSERT INTO heb_vpl VALUES ("JM4_1","089_4_1","JAS","4","1","1","מאין המלחמות והמדנים אשר ביניכם הלא מתוך התאות המתגרות באבריכם׃ ");
INSERT INTO heb_vpl VALUES ("JM4_2","089_4_2","JAS","4","2","2","אתם מתאוים ואין לכם תרצחו ותקנאו והשג לא תשיגו תריבו ותלחמו ואין לכם יען אשר לא התפללתם׃ ");
INSERT INTO heb_vpl VALUES ("JM4_3","089_4_3","JAS","4","3","3","הן אתם מבקשים ואינכם מקבלים על אשר תתפללו ברעה למען תבלו בתאותיכם׃ ");
INSERT INTO heb_vpl VALUES ("JM4_4","089_4_4","JAS","4","4","4","הנאפים והמנאפות הלא ידעתם כי אהבת העולם איבת אלהים היא ועתה החפץ להיות אהב העולם יהיה איב לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("JM4_5","089_4_5","JAS","4","5","5","או התדמו בנפשכם כי לריק אמר הכתוב בקנאה יתאוה לרוח השכן בקרבנו׃ ");
INSERT INTO heb_vpl VALUES ("JM4_6","089_4_6","JAS","4","6","6","וגם יגדיל לתת חן על כן אומר אלהים ללצים יליץ ולענוים יתן חן׃ ");
INSERT INTO heb_vpl VALUES ("JM4_7","089_4_7","JAS","4","7","7","לכן הכנעו לאלהים התיצבו נגד השטן ויברח מפניכם׃ ");
INSERT INTO heb_vpl VALUES ("JM4_8","089_4_8","JAS","4","8","8","קרבו לאלהים ויקרב אליכם רחצו ידיכם החטאים טהרו לבבכם חלוקי הלבב׃ ");
INSERT INTO heb_vpl VALUES ("JM4_9","089_4_9","JAS","4","9","9","התענו והתאבלו ובכו שחקכם יהפך לאבל ושמחתכם ליגון׃ ");
INSERT INTO heb_vpl VALUES ("JM4_10","089_4_10","JAS","4","10","10","הכנעו לפני יהוה והוא ירים אתכם׃ ");
INSERT INTO heb_vpl VALUES ("JM4_11","089_4_11","JAS","4","11","11","אחי אל תחרפו איש את רעהו המחרף את רעהו ודן את אחיו הוא מחרף את התורה ודן את התורה ואם תדין את התורה אינך עשה התורה כי אם שפטה׃ ");
INSERT INTO heb_vpl VALUES ("JM4_12","089_4_12","JAS","4","12","12","אחד הוא המחקק אשר יכול להושיע ולאבד ומי אתה כי תדין את עמיתך׃ ");
INSERT INTO heb_vpl VALUES ("JM4_13","089_4_13","JAS","4","13","13","הוי האמרים נלכה היום ומחר לעיר פלונית אלמונית ונעשה שם שנה אחת לסחר בה ולהרבות רוח׃ ");
INSERT INTO heb_vpl VALUES ("JM4_14","089_4_14","JAS","4","14","14","ולא תדעו מה ילד יום מחר כי מה חייכם עשן הם אשר נראה כמעט רגע ואחר כלה וילך׃ ");
INSERT INTO heb_vpl VALUES ("JM4_15","089_4_15","JAS","4","15","15","תחת אשר תאמרו אם ירצה יהוה ונחיה נעשה כזה וכזה׃ ");
INSERT INTO heb_vpl VALUES ("JM4_16","089_4_16","JAS","4","16","16","עתה תתגאו בפחזותכם וכל גאוה אשר כזאת רעה היא׃ ");
INSERT INTO heb_vpl VALUES ("JM4_17","089_4_17","JAS","4","17","17","לכן היודע לעשות הטוב ולא יעשנו והיה בו חטא׃ ");
INSERT INTO heb_vpl VALUES ("JM5_1","089_5_1","JAS","5","1","1","הוי העשירים בכו והילילו על הצרות אשר תבאנה עליכם׃ ");
INSERT INTO heb_vpl VALUES ("JM5_2","089_5_2","JAS","5","2","2","עשרכם בלה ובגדיכם אכלם עש׃ ");
INSERT INTO heb_vpl VALUES ("JM5_3","089_5_3","JAS","5","3","3","זהבכם וכספכם כסתם חלאה והיתה חלאתם בכם לעדות ואכלה כמו אש את בשרכם אצרתם לכם אוצרות בקץ הימים׃ ");
INSERT INTO heb_vpl VALUES ("JM5_4","089_5_4","JAS","5","4","4","הנה שכר הפעלים אספי קציר שדתיכם אשר עשקתם צעק עליכם וצעקת הקוצרים באה באזני יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("JM5_5","089_5_5","JAS","5","5","5","התעדנתם בארץ והתענגתם והשמנתם את לבכם כמו ליום טבחה׃ ");
INSERT INTO heb_vpl VALUES ("JM5_6","089_5_6","JAS","5","6","6","הרשעתם והמתם את הצדיק והוא נענה לא יפתח פיו׃ ");
INSERT INTO heb_vpl VALUES ("JM5_7","089_5_7","JAS","5","7","7","לכן אחי דמו והוחילו עד בוא האדון הנה האכר מחכה לטוב תבואת האדמה בהוחילו כי ירד עליה גשם יורה ומלקוש׃ ");
INSERT INTO heb_vpl VALUES ("JM5_8","089_5_8","JAS","5","8","8","כן הוחילו גם אתם ואמצו לבבכם כי קרוב האדון לבא׃ ");
INSERT INTO heb_vpl VALUES ("JM5_9","089_5_9","JAS","5","9","9","אחי אל תתאוננו איש על רעהו פן תשפטו הנה השופט עמד לפתח׃ ");
INSERT INTO heb_vpl VALUES ("JM5_10","089_5_10","JAS","5","10","10","אחי הנביאים אשר דברו בשם יהוה הם יהיו לכם למופת העני והתוחלת׃ ");
INSERT INTO heb_vpl VALUES ("JM5_11","089_5_11","JAS","5","11","11","הנה מאשרים אנחנו את הסבלים את סבלנות איוב שמעתכם ואת אחרית האדון ראיתם כי רחום וחנון יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JM5_12","089_5_12","JAS","5","12","12","וראש דבר אחי לא תשבעו לא בשמים ולא בארץ ולא בכל שבועה אחרת ויהי הן שלכם הן ולא שלכם לא פן תפלו בידי הדין׃ ");
INSERT INTO heb_vpl VALUES ("JM5_13","089_5_13","JAS","5","13","13","כי יצר לאיש בכם הוא יתפלל ואשר ייטב לבו הוא יזמר׃ ");
INSERT INTO heb_vpl VALUES ("JM5_14","089_5_14","JAS","5","14","14","איש כי יחלה בכם יקרא את זקני הקהלה ויתפללו בעדו ויסוכהו שמן בשם יהוה׃ ");
INSERT INTO heb_vpl VALUES ("JM5_15","089_5_15","JAS","5","15","15","ותפלת האמונה תושיע את החולה ויהוה יקימנו ואשר חטא יסלח לו׃ ");
INSERT INTO heb_vpl VALUES ("JM5_16","089_5_16","JAS","5","16","16","התודו עונותיכם איש לפני רעהו והתפללו איש בעד רעהו למען תרפאו כי גדול כח תפלת הצדיק הקרא אל אלהים בחזקה׃ ");
INSERT INTO heb_vpl VALUES ("JM5_17","089_5_17","JAS","5","17","17","אליהו אנוש אנוש היה כמנו והתפלל תפלה שלא יהיה מטר ולא היה מטר בארץ שלש שנים וששה חדשים׃ ");
INSERT INTO heb_vpl VALUES ("JM5_18","089_5_18","JAS","5","18","18","וישב ויתפלל והשמים נתנו מטר והארץ הצמיחה את פריה׃ ");
INSERT INTO heb_vpl VALUES ("JM5_19","089_5_19","JAS","5","19","19","אחי כי יתעה איש בכם מן האמת ואיש אחר ישיבנו׃ ");
INSERT INTO heb_vpl VALUES ("JM5_20","089_5_20","JAS","5","20","20","ידוע ידע כי המשיב את החוטא מעקשות דרכו הוא יושיע את נפשו ממות ויכסה על המון פשעים׃ ");
INSERT INTO heb_vpl VALUES ("P11_1","090_1_1","1PE","1","1","1","פטרוס שליח ישוע המשיח אל תושבי תפוצות פנטוס גלטיא קפודקיא אסיא וביתוניא׃ ");
INSERT INTO heb_vpl VALUES ("P11_2","090_1_2","1PE","1","2","2","הנבחרים מקדם כפי דעת אלהים האב בקדוש הרוח אל משמעת ישוע המשיח ואל הזית דמו חסד ושלום למכביר יהיו לכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_3","090_1_3","1PE","1","3","3","ברוך האלהים אבי אדנינו ישוע המשיח אשר כרב רחמיו שב והוליד אתנו לתקוה חיה בהקמת ישוע המשיח מעם המתים׃ ");
INSERT INTO heb_vpl VALUES ("P11_4","090_1_4","1PE","1","4","4","לנחלה אשר לא תשחת ולא תגאל ולא תבל הצפונה בשמים לכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_5","090_1_5","1PE","1","5","5","הנשמרים בעז אלהים על יד האמונה לתשועה העתידה להגלות בעת קץ׃ ");
INSERT INTO heb_vpl VALUES ("P11_6","090_1_6","1PE","1","6","6","אשר בה תגילו אתם המתעצבים עתה מעט לפי הצרך במסת שנות׃ ");
INSERT INTO heb_vpl VALUES ("P11_7","090_1_7","1PE","1","7","7","למען תמצא אמונתכם המזקקה יקרה הרבה מן הזהב האבד הצרוף באש לתהלה ולכבוד ולתפארת בהתגלות ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P11_8","090_1_8","1PE","1","8","8","אשר אהבתם ולא ראיתם ואשר עתה תאמינו בו בלא ראות אתו ובכן תגילו בשמחה מפארה עצמה מספר׃ ");
INSERT INTO heb_vpl VALUES ("P11_9","090_1_9","1PE","1","9","9","בקחתכם עקב אמונתכם תשועה לנפשתיכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_10","090_1_10","1PE","1","10","10","את התשועה אשר עליה חקרו ודרשו הנביאים הנבאים על החסד השמור לכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_11","090_1_11","1PE","1","11","11","בחקרם לדעת מתי ואיך תהיה העת אשר הודיעה רוח המשיח אשר בקרבם בהגידו מראש את ענויי המשיח ואת הגדלות אשר אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("P11_12","090_1_12","1PE","1","12","12","ונגלה להם כי לא לפנשם כי אם לנו שרתו בדברים ההם אשר הגד לכם עתה על פי המבשרים אתכם ברוח הקדש השלוח משמים דברים אשר מלאכי אלהים חמדו להשקיף אל תוכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_13","090_1_13","1PE","1","13","13","לכן חגרו מתני שכלכם התעוררו וקוו קוה לחסד אשר יבואכם בהתגלות ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P11_14","090_1_14","1PE","1","14","14","כבני משמעת אל תתנהגו בתאות אשר התאויתם בעוד היותכם בבלי דעת׃ ");
INSERT INTO heb_vpl VALUES ("P11_15","090_1_15","1PE","1","15","15","כי אם היו קדשים בכל דרכיכם כאשר קדוש הוא אשר קרא אתכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_16","090_1_16","1PE","1","16","16","כי על כן כתוב והייתם קדשים כי קדוש אני׃ ");
INSERT INTO heb_vpl VALUES ("P11_17","090_1_17","1PE","1","17","17","ואם אב תקראו לאלהים השפט בבלי משא פנים כפי מעללי איש ואיש התהלכו נא ביראה בימי מגוריכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_18","090_1_18","1PE","1","18","18","מדעתכם כי לא בדבר נפסד בכסף או בזהב נפדיתם מדרך הבלכם אשר הנחלתם מאת אבותיכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_19","090_1_19","1PE","1","19","19","כי אם בדם יקר של שה תמים ומום אין בו בדם המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P11_20","090_1_20","1PE","1","20","20","הנודע מראש לפני מוסדות תבל ונגלה באחרית הימים למענכם׃ ");
INSERT INTO heb_vpl VALUES ("P11_21","090_1_21","1PE","1","21","21","המאמינים על פיו באלהים אשר הקים אתו מעם המתים ויתן לו כבוד למען היות אמונתכם גם תקוה לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("P11_22","090_1_22","1PE","1","22","22","זכו את נפשתיכם על ידי הרוח בשמעכם בקול האמת לאהבת אחים בלא חנפה ואהבתם איש את רעהו אהבה חזקה בלב טהור׃ ");
INSERT INTO heb_vpl VALUES ("P11_23","090_1_23","1PE","1","23","23","כנולדים מחדש לא מזרע נשחת כי אם מזרע לא ישחת במאמר אלהים החי והקים לעולם׃ ");
INSERT INTO heb_vpl VALUES ("P11_24","090_1_24","1PE","1","24","24","כי כל בשר חציר וכל כבוד איש כציץ השדה יבש חציר נבל ציץ׃ ");
INSERT INTO heb_vpl VALUES ("P11_25","090_1_25","1PE","1","25","25","ודבר יהוה יקום לעולם וזה הוא הדבר אשר בשר לכם׃ ");
INSERT INTO heb_vpl VALUES ("P12_1","090_2_1","1PE","2","1","1","ועתה הסירו מכם כל רשע וכל מרמה וחנפה וקנאה וכל לשון רע׃ ");
INSERT INTO heb_vpl VALUES ("P12_2","090_2_2","1PE","2","2","2","וכעללים אשר מקרוב נולדו התאוו לחלב השכלי והזך למען תגדלו בו׃ ");
INSERT INTO heb_vpl VALUES ("P12_3","090_2_3","1PE","2","3","3","אם אמנם טעמתם כי טוב האדון׃ ");
INSERT INTO heb_vpl VALUES ("P12_4","090_2_4","1PE","2","4","4","אשר נגשתם אליו אל אבן חיה אשר מאסו בה בני האדם והיא נבחרה ויקרה לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("P12_5","090_2_5","1PE","2","5","5","ונבניתם גם אתם כאבנים חיות לבית רוחני לכהנת קדש להעלות זבחי רוח לרצון לאלהים בישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P12_6","090_2_6","1PE","2","6","6","וזה הוא שאמר הכתוב הנני יסד בציון אבן פנה אבן בחן ויקרה והמאמין בה לא יבוש׃ ");
INSERT INTO heb_vpl VALUES ("P12_7","090_2_7","1PE","2","7","7","לכן לכם המאמינים היקר אבל לסוררים האבן אשר מאסו הבונים היתה לראש פנה ולאבן נגף ולצור מכשל׃ ");
INSERT INTO heb_vpl VALUES ("P12_8","090_2_8","1PE","2","8","8","והם נכשלו יען לא שמעו לדבר ולזאת גם נועדו׃ ");
INSERT INTO heb_vpl VALUES ("P12_9","090_2_9","1PE","2","9","9","ואתם הנכם זרע נבחר ממלכת כהנים וגוי קדוש ועם סגלה למען תספרו תהלות הקורא אתכם מחשך אל אורו הנפלא׃ ");
INSERT INTO heb_vpl VALUES ("P12_10","090_2_10","1PE","2","10","10","אשר לפנים לא עם הייתם ועתה עם אלהים ואשר לפנים לא רחמו ועתה מרחמים׃ ");
INSERT INTO heb_vpl VALUES ("P12_11","090_2_11","1PE","2","11","11","אהובים אזהירכם כגרים ותושבים הנזרו מתאות הבשר המתגרות בנפש׃ ");
INSERT INTO heb_vpl VALUES ("P12_12","090_2_12","1PE","2","12","12","והיטיבו דרככם בגוים למען יביטו אל מעשיכם הטובים והיה תחת אשר חרפו אתכם כפעלי און יכבדו את האלהים ביום הפקדה׃ ");
INSERT INTO heb_vpl VALUES ("P12_13","090_2_13","1PE","2","13","13","והכנעו לכל פקדת אדם בגלל האדון אם למלך כראוי לראש׃ ");
INSERT INTO heb_vpl VALUES ("P12_14","090_2_14","1PE","2","14","14","אם למשלים כראוי לשלוחים מאתו לנקמת פעלי און ולתהלת עשי טוב׃ ");
INSERT INTO heb_vpl VALUES ("P12_15","090_2_15","1PE","2","15","15","כי כן הוא חפץ אלהים אשר בעשותכם הטוב תסכרו את פי אולת האנשים אשר אין בם דעת׃ ");
INSERT INTO heb_vpl VALUES ("P12_16","090_2_16","1PE","2","16","16","כחפשים ולא כאלו היתה לכם החפשה למכסה הרעה כי אם כעבדי אלהים׃ ");
INSERT INTO heb_vpl VALUES ("P12_17","090_2_17","1PE","2","17","17","נהגו כבוד בכל איש אהבו את האחים יראו את אלהים כבדו את המלך׃ ");
INSERT INTO heb_vpl VALUES ("P12_18","090_2_18","1PE","2","18","18","העבדים הכנעו לפני אדניכם בכל יראה לא לפני הטובים והענוים לבד כי אם גם לפני העקשים׃ ");
INSERT INTO heb_vpl VALUES ("P12_19","090_2_19","1PE","2","19","19","כי חסד הוא לאיש אם ישבע ממררים ויענה חנם למען דעת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("P12_20","090_2_20","1PE","2","20","20","כי אם חטא תחטאו וסבלתם מכות אגרוף מה תתהללו אך אם תענו וסבלתם בעשותכם הטוב חסד הוא מלפני אלהים׃ ");
INSERT INTO heb_vpl VALUES ("P12_21","090_2_21","1PE","2","21","21","כי לזאת נקראתם כי גם המשיח ענה בעבורכם והשאיר לכם מופת ללכת בעקבותיו׃ ");
INSERT INTO heb_vpl VALUES ("P12_22","090_2_22","1PE","2","22","22","אשר חטא לא עשה ולא מרמה בפיו׃ ");
INSERT INTO heb_vpl VALUES ("P12_23","090_2_23","1PE","2","23","23","אשר שמע חרפתו ולא השיב נענה ולא גער כי אם מסר דינו לשפט צדק ואת חטאתנו הוא נשא בגויתו על העץ׃ ");
INSERT INTO heb_vpl VALUES ("P12_24","090_2_24","1PE","2","24","24","למען נחיה לצדקה מאחר שנפטרנו מן החטאים׃ ");
INSERT INTO heb_vpl VALUES ("P12_25","090_2_25","1PE","2","25","25","אשר בחברתו נרפא לכם כי הייתם כצאן אבדות ועתה שבתם אל הרעה פקיד נפשתיכם׃ ");
INSERT INTO heb_vpl VALUES ("P13_1","090_3_1","1PE","3","1","1","וכן אתן הנשים הכנענה לפני בעליכן למען גם אם יש אשר אינם שמעים לדבר יקנו באין אמר ודברים על ידי מעשי הנשים׃ ");
INSERT INTO heb_vpl VALUES ("P13_2","090_3_2","1PE","3","2","2","בראותם כי תצנענה לכת ביראה׃ ");
INSERT INTO heb_vpl VALUES ("P13_3","090_3_3","1PE","3","3","3","ופארכן אל יהי מבחוץ במחלפות שער ועדי זהב ולבישת מחלצים׃ ");
INSERT INTO heb_vpl VALUES ("P13_4","090_3_4","1PE","3","4","4","כי אם האדם הצפון פנימה ברוח ענוה והשקט אשר לא יכלה ויקר הוא בעיני אלהים׃ ");
INSERT INTO heb_vpl VALUES ("P13_5","090_3_5","1PE","3","5","5","כי כן התקשטו לפנים גם הנשים הקדשות המיחלות לאלהים בהכנען לפני בעליהן׃ ");
INSERT INTO heb_vpl VALUES ("P13_6","090_3_6","1PE","3","6","6","כשרה אשר שמעה בקול אברהם ותקרא לו אדון אשר אתן הייתן לה לבנות בעשותכן הטוב ולא תיראנה מפחד׃ ");
INSERT INTO heb_vpl VALUES ("P13_7","090_3_7","1PE","3","7","7","וכן אתם האנשים שבו עמהן בתבונה כי כלי רפה האשה ותנו לה כבוד כי גם להן יש חלק בנחלת מתנת החיים פן תכלאו מתפלותיכם׃ ");
INSERT INTO heb_vpl VALUES ("P13_8","090_3_8","1PE","3","8","8","וסוף דבר היו כלכם לב אחד בעלי חמלה אהבי האחים רחמנים ומתקבלים על הבריות׃ ");
INSERT INTO heb_vpl VALUES ("P13_9","090_3_9","1PE","3","9","9","אל תשלמו רעה תחת רעה או חרפה תחת חרפה כי אם תברכו מדעתכם כי לזאת נקראתם למען תירשו את הברכה׃ ");
INSERT INTO heb_vpl VALUES ("P13_10","090_3_10","1PE","3","10","10","כי האיש החפץ חיים אהב ימים לראות טוב יצר לשונו מרע ושפתיו מדבר מרמה׃ ");
INSERT INTO heb_vpl VALUES ("P13_11","090_3_11","1PE","3","11","11","יסור מרע ויעשה טוב יבשק שלום וירדפהו׃ ");
INSERT INTO heb_vpl VALUES ("P13_12","090_3_12","1PE","3","12","12","כי עיני יהוה אל צדיקים ואזניו אל שועתם ופני יהוה בעשי רע׃ ");
INSERT INTO heb_vpl VALUES ("P13_13","090_3_13","1PE","3","13","13","ומי ירע לכם אם תקנאו לעשות הטוב׃ ");
INSERT INTO heb_vpl VALUES ("P13_14","090_3_14","1PE","3","14","14","אבל אשריכם גם אם תענו למען הצדקה אך מוראם לא תיראו ולא תעריצו׃ ");
INSERT INTO heb_vpl VALUES ("P13_15","090_3_15","1PE","3","15","15","את יהוה אלהים אתו תקדישו בלבבכם והיו נכנים תמיד להשיב דבר בענוה וביראה לכל שאל אתכם חשבון התוחלת אשר בקרבכם׃ ");
INSERT INTO heb_vpl VALUES ("P13_16","090_3_16","1PE","3","16","16","רוח שלמה תהי לכם למען יבשו המנאצים דרככם הטובה במשיח בהלשינם אתכם כפעלי און׃ ");
INSERT INTO heb_vpl VALUES ("P13_17","090_3_17","1PE","3","17","17","כי טוב לכם אם חפץ אלהים הוא אשר תענו בעשותכם הטוב משתענו בעשותכם רע׃ ");
INSERT INTO heb_vpl VALUES ("P13_18","090_3_18","1PE","3","18","18","כי גם המשיח ענה פעם אחת על חטאתינו הצדיק בעד הרשעים לקרב אתנו אל האלהים הומת לפי הבשר ויחי ברוח׃ ");
INSERT INTO heb_vpl VALUES ("P13_19","090_3_19","1PE","3","19","19","אשר בו הלך ויקרא גם לרוחות אשר במשמר׃ ");
INSERT INTO heb_vpl VALUES ("P13_20","090_3_20","1PE","3","20","20","אשר לפנים לא האמינו כאשר חכה אלהים בארך אפו בימי נח בהעשות התבה אשר נמלטו אליה מעטים והם שמנה נפשות במים׃ ");
INSERT INTO heb_vpl VALUES ("P13_21","090_3_21","1PE","3","21","21","וזה הוא אות הטבילה אשר כעת תושיע גם אתנו לא בהסיר טנוף הבשר כי אם בשאל לנו מאת אלהים רוח שלמה על ידי הקמת ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P13_22","090_3_22","1PE","3","22","22","אשר הוא לימין אלהים אחרי אשר עבר השמימה ויכנעו לפניו המלאכים והרשיות והגבורות׃ ");
INSERT INTO heb_vpl VALUES ("P14_1","090_4_1","1PE","4","1","1","ועתה כאשר ענה המשיח בעדנו בבשר כן היו גם אתם מזינים במחשבה ההיא כי המענה בבשר חדל מחטוא׃ ");
INSERT INTO heb_vpl VALUES ("P14_2","090_4_2","1PE","4","2","2","למען אשר לא תחיו עוד לתאות בני אדם כי אם לרצון אלהים כל ימי היתכם עוד בבשר׃ ");
INSERT INTO heb_vpl VALUES ("P14_3","090_4_3","1PE","4","3","3","כי דינו עת החיים אשר עברה לעשות כחפץ הגוים בלכתנו בדרכי זמה ובתאות כסבאי יין וזללי בשר ורדפי שכר ותועבות עבדת האלילים׃ ");
INSERT INTO heb_vpl VALUES ("P14_4","090_4_4","1PE","4","4","4","ועל זאת תמהים המה ומגדפים כי לא תרוצו עמהם לשטף בזמה כמוהם׃ ");
INSERT INTO heb_vpl VALUES ("P14_5","090_4_5","1PE","4","5","5","אשר יתנו חשבון לפני העתיד לשפט החיים והמתים׃ ");
INSERT INTO heb_vpl VALUES ("P14_6","090_4_6","1PE","4","6","6","כי על כן התבשרו גם המתים למען ישפטו בבשר לפי דרך בני אדם ויחיו ברוח לפי דרך אלהים׃ ");
INSERT INTO heb_vpl VALUES ("P14_7","090_4_7","1PE","4","7","7","הן קץ הכל קרב לכן היו צנועים וערים להתפלל׃ ");
INSERT INTO heb_vpl VALUES ("P14_8","090_4_8","1PE","4","8","8","ולפני כל דבר אהבו איש את אחיו אהבה חזקה כי על רב פשעים תכסה האהבה׃ ");
INSERT INTO heb_vpl VALUES ("P14_9","090_4_9","1PE","4","9","9","היו מארחים איש את רעהו בבלי תלנות׃ ");
INSERT INTO heb_vpl VALUES ("P14_10","090_4_10","1PE","4","10","10","איש איש כמתן החסד אשר קבל תעזרו איש לרעהו כגזברים ממנים על חסדי אלהים הרבים׃ ");
INSERT INTO heb_vpl VALUES ("P14_11","090_4_11","1PE","4","11","11","איש כי ידבר יהי כאמרי אל ואיש כי יעזר תהי עזרתו מתוך החיל אשר חננו אלהים למען יכבד אלהים בכל על ידי ישוע המשיח אשר לו הכבוד והעז לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("P14_12","090_4_12","1PE","4","12","12","אהובים בבאכם בתוך כור עני למען נסתכם אל נא תתמהו כאלו קרה לכם דבר זר׃ ");
INSERT INTO heb_vpl VALUES ("P14_13","090_4_13","1PE","4","13","13","כי אם שמחו על אשר חלק לכם בענויי המשיח למען גם תשמחו ותעלצו בהגלות כבודו׃ ");
INSERT INTO heb_vpl VALUES ("P14_14","090_4_14","1PE","4","14","14","אם יחרפו אתכם למען שם המשיח אשריכם כי נחה עליכם רוח הכבוד רוח אלהים אצלם מנאץ הוא ואצלכם נכבד׃ ");
INSERT INTO heb_vpl VALUES ("P14_15","090_4_15","1PE","4","15","15","רק אל יענה איש מכם כרצח או כגנב או כפעל און או כנכנס בפקדת אחרים׃ ");
INSERT INTO heb_vpl VALUES ("P14_16","090_4_16","1PE","4","16","16","ואם יענה כאחד המשיחיים אל יבוש כי אם יודה לאלהים על הדבר הזה׃ ");
INSERT INTO heb_vpl VALUES ("P14_17","090_4_17","1PE","4","17","17","כי עת החל המשפט מבית אלהים ואם ממנו ראשנה מה אפוא תהיה אחרית הממרים את בשורת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("P14_18","090_4_18","1PE","4","18","18","הן צדיק כמעט יושע אף כי רשע וחוטא׃ ");
INSERT INTO heb_vpl VALUES ("P14_19","090_4_19","1PE","4","19","19","לכן גם המענים כרצון אלהים יפקידו את נפשותם ביד אלהים הברא הנאמן ויוסיפו לעשות הטוב׃ ");
INSERT INTO heb_vpl VALUES ("P15_1","090_5_1","1PE","5","1","1","את הזקנים אשר בקרבכם אזהיר אנכי עמיתם הזקן ועד ענויי המשיח וגם חבר לכבוד העתיד להגלות׃ ");
INSERT INTO heb_vpl VALUES ("P15_2","090_5_2","1PE","5","2","2","רעו את עדר האלהים אשר בידכם והשגיחו עליהם לא באנס כי אם בנדבה אף לא עקב בצע כי אם בנפש חפצה׃ ");
INSERT INTO heb_vpl VALUES ("P15_3","090_5_3","1PE","5","3","3","גם לא כמתעמרים בנחלת יהוה כי אם בהיותכם מופת לצאן׃ ");
INSERT INTO heb_vpl VALUES ("P15_4","090_5_4","1PE","5","4","4","והיה בהגלות שר הרעים תשאו עטרת הכבוד אשר לא תבל׃ ");
INSERT INTO heb_vpl VALUES ("P15_5","090_5_5","1PE","5","5","5","וכן גם אתם הנערים הכנעו לפני הזקנים וחגרו כלכם שפלות רוח בהכנע איש לרעהו כי אלהים ללצים יליץ ולענוים יתן חן׃ ");
INSERT INTO heb_vpl VALUES ("P15_6","090_5_6","1PE","5","6","6","השפילו נפשכם תחת יד אלהים החזקה למען ירומם אתכם בעתו׃ ");
INSERT INTO heb_vpl VALUES ("P15_7","090_5_7","1PE","5","7","7","השליכו עליו כל יהבכם כי הוא ידאג לכם׃ ");
INSERT INTO heb_vpl VALUES ("P15_8","090_5_8","1PE","5","8","8","התעוררו שקדו כי מריבכם השטן משוטט כאריה שאג ומבקש את אשר יבלע׃ ");
INSERT INTO heb_vpl VALUES ("P15_9","090_5_9","1PE","5","9","9","ועמדתם נגדו חזקים באמונה ודעו כי ענוים כאלה באו גם על אחיכם אשר בעולם׃ ");
INSERT INTO heb_vpl VALUES ("P15_10","090_5_10","1PE","5","10","10","ואלהי כל החסד אשר קראנו לכבודו הנצחי במשיח ישוע אחרי ענותכם מעט הוא ישלים ויחזק ויגבר וייסד אתכם׃ ");
INSERT INTO heb_vpl VALUES ("P15_11","090_5_11","1PE","5","11","11","לו הכבוד והעז לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("P15_12","090_5_12","1PE","5","12","12","ביד סלונוס האח הנאמן לכם כאשר אחשב כתבתי אליכם בדברים מעטים להזהיר אתכם ולהעיד כי חסד האלהים הזה אשר עמדתם בו אמת הוא׃ ");
INSERT INTO heb_vpl VALUES ("P15_13","090_5_13","1PE","5","13","13","חברתכם אשר בבבל הנבחרה אתכם ומרקוס בני שאלים לשלומכם׃ ");
INSERT INTO heb_vpl VALUES ("P15_14","090_5_14","1PE","5","14","14","שאלו לשלום איש את רעהו בנשיקת אהבה שלום לכלכם אשר במשיח ישוע אמן׃ ");
INSERT INTO heb_vpl VALUES ("P21_1","091_1_1","2PE","1","1","1","שמעון פטרוס עבד ישוע המשיח ושליחו אל אשר קבלו אמונה יקרה כשלנו בצדקת אלהינו ומושיענו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P21_2","091_1_2","2PE","1","2","2","חסד ושלום יהיו לכם למכביר בדעת האלהים וישוע אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("P21_3","091_1_3","2PE","1","3","3","באשר גבורתו האלהית נתנה לנו את כל אשר לחיים ולחסידות על ידי דעת הקורא אתנו בכבודו וחילו׃ ");
INSERT INTO heb_vpl VALUES ("P21_4","091_1_4","2PE","1","4","4","אשר בהם נתן לנו הבטחות גדלות מאד ויקרות למען תקחו על ידן חלק בטבע אלהים בהמלטכם מכליון התאוה אשר בעולם׃ ");
INSERT INTO heb_vpl VALUES ("P21_5","091_1_5","2PE","1","5","5","בעבור זאת השתדלו להעמיד באמונתכם את הצדקה ובצדקה את הדעת׃ ");
INSERT INTO heb_vpl VALUES ("P21_6","091_1_6","2PE","1","6","6","ובדעת את הפרישות ובפרישות את הסבלנות ובסבלנות את החסידות׃ ");
INSERT INTO heb_vpl VALUES ("P21_7","091_1_7","2PE","1","7","7","ובחסידות את האחוה ובאחוה את האהבה׃ ");
INSERT INTO heb_vpl VALUES ("P21_8","091_1_8","2PE","1","8","8","כי אם אלה תמצאנה ותרבינה בכם לא תתנה אתכם להיות בטלים ובלא עשות פרי לדעת אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P21_9","091_1_9","2PE","1","9","9","כי האיש אשר אין אלה לו עור הוא קצר הראות ושכח את טהרתו מחטאתיו הראשנות׃ ");
INSERT INTO heb_vpl VALUES ("P21_10","091_1_10","2PE","1","10","10","לכן אחי הוסיפו והשתדלו לחזק את קריאתכם ובחירתכם כי בעשותכם זאת כשול לא תכשלו׃ ");
INSERT INTO heb_vpl VALUES ("P21_11","091_1_11","2PE","1","11","11","כי כן יפתח לפניכם לרוחה המבוא אל מלכות עולם אשר לאדנינו ומושיענו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P21_12","091_1_12","2PE","1","12","12","על כן לא אחדל להזכירכם על אלה בכל עת גם כי ידעתם והתכוננתם באמת אשר היא לפנינו׃ ");
INSERT INTO heb_vpl VALUES ("P21_13","091_1_13","2PE","1","13","13","ואחשב כי נכון להזכיר ולהעיר אתכם כל ימי היותי במשכן הזה׃ ");
INSERT INTO heb_vpl VALUES ("P21_14","091_1_14","2PE","1","14","14","באשר ידעתי כי מהר יעתק משכני כאשר גם גלה לי אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("P21_15","091_1_15","2PE","1","15","15","ואשתדל שיהיה לכם תמיד גם אחרי פטירתי זכרון הדברים האלה׃ ");
INSERT INTO heb_vpl VALUES ("P21_16","091_1_16","2PE","1","16","16","כי הודענו אתכם גבורת אדנינו ישוע המשיח ובאו לא בלכתנו אחרי הגדות מחכמות כי אם ראות היו עינינו את גדלתו׃ ");
INSERT INTO heb_vpl VALUES ("P21_17","091_1_17","2PE","1","17","17","כי לקח מאת אלהים האב יקר וכבוד בבא אליו קול מתוך הדרת כבודו לאמר זה בני ידידי רצתה נפשי בו׃ ");
INSERT INTO heb_vpl VALUES ("P21_18","091_1_18","2PE","1","18","18","ואת הקול הזה שמענו באזנינו יצא משמים בהיותנו עמו בהר הקדש׃ ");
INSERT INTO heb_vpl VALUES ("P21_19","091_1_19","2PE","1","19","19","ועתה דבר הנבואה יותר קים אתנו והטיבתם עשות אשר שתם לבכם אליו כמו אל נר מאיר במקום אפל עד כי יבקע אור היום וזרח כוכב הנגה בלבבכם׃ ");
INSERT INTO heb_vpl VALUES ("P21_20","091_1_20","2PE","1","20","20","וזאת תדעו ראשונה אשר כל נבואת המקרא איננה תלה בפתרון אדם מלבו׃ ");
INSERT INTO heb_vpl VALUES ("P21_21","091_1_21","2PE","1","21","21","כי מעולם לא יצאה נבואה ברצון האדם כי אם ברוח הקדש אשר נשאם דברו אנשי אלהים הקדושים׃ ");
INSERT INTO heb_vpl VALUES ("P22_1","091_2_1","2PE","2","1","1","וגם נביאי שקר היו בעם כאשר יהיו גם בכם מורי שקר אשר יכניסו כתות משחיתות ובכחשם במשל אשר קנם יביאו על נפשם כליון פתאם׃ ");
INSERT INTO heb_vpl VALUES ("P22_2","091_2_2","2PE","2","2","2","ורבים ילכו אחרי תועבותם ובעבורם יתן דרך האמת לגדופים׃ ");
INSERT INTO heb_vpl VALUES ("P22_3","091_2_3","2PE","2","3","3","ובדברי בדוי יעשו אתכם למחסר להם למען בצע בצע אשר משפטם מעולם לא יתמהמה ושברם לא ינום׃ ");
INSERT INTO heb_vpl VALUES ("P22_4","091_2_4","2PE","2","4","4","כי לא חס אלהים על המלאכים אשר חטאו כי אם הורידם לקצבי הרים ויסגירם בכבלי אפל לשמרם למשפט׃ ");
INSERT INTO heb_vpl VALUES ("P22_5","091_2_5","2PE","2","5","5","וגם על דורות קדם לא חס וישמר רק את נח השמיני קרא הצדק בהביאו את המבול על דור הרשעים׃ ");
INSERT INTO heb_vpl VALUES ("P22_6","091_2_6","2PE","2","6","6","ואת ערי סדום ועמרה הפך לאפר והאשימם במהפכה וישימם למשל לאשר עתידים לעשות זמה׃ ");
INSERT INTO heb_vpl VALUES ("P22_7","091_2_7","2PE","2","7","7","ויצל את לוט הצדיק אשר הלאוהו אנשי בליעל ההם בדרך זמתם׃ ");
INSERT INTO heb_vpl VALUES ("P22_8","091_2_8","2PE","2","8","8","כי הצדיק הזה בשבתו בתוכם האדיב את נפשו הישרה יום יום בראותו ובשמעו מעשי רשעם׃ ");
INSERT INTO heb_vpl VALUES ("P22_9","091_2_9","2PE","2","9","9","כי יודע יהוה להציל את חסידיו מנסיון ולחשך את הרשעים ליום המשפט להשיב גמולם להם׃ ");
INSERT INTO heb_vpl VALUES ("P22_10","091_2_10","2PE","2","10","10","וביותר את ההלכים אחרי הבשר בתאות תבל ובזים את הממשלה עזי פנים הלכים בשרירות לבם ולא יחרדו מחרף את השררות׃ ");
INSERT INTO heb_vpl VALUES ("P22_11","091_2_11","2PE","2","11","11","אשר אף המלאכים הגדולים מהם בעז וכח לא יגדפום לפני יהוה במשפטם׃ ");
INSERT INTO heb_vpl VALUES ("P22_12","091_2_12","2PE","2","12","12","והמה כבהמות הסכלות הנולדות כחק טבעם ללכד ולשחת יאבדו באבוד נפשם יען חרפו את אשר לא הבינו וישאו גמול עולתם׃ ");
INSERT INTO heb_vpl VALUES ("P22_13","091_2_13","2PE","2","13","13","אשר עדנת יומם לענג יחשבו מטנפים ומום בם המתפנקים במדוחי נפשם ואכלים ושתים עמכם׃ ");
INSERT INTO heb_vpl VALUES ("P22_14","091_2_14","2PE","2","14","14","עינים להם מלאות נאפים אשר לא תחדלות מחטוא ואת נפשות הפתאים יצודדו ולב מלמד בצע להם בני המארה׃ ");
INSERT INTO heb_vpl VALUES ("P22_15","091_2_15","2PE","2","15","15","את הדרך הישר עזבו ויתעו וילכו בדרך בלעם בן בעור אשר אהב שכר העולה׃ ");
INSERT INTO heb_vpl VALUES ("P22_16","091_2_16","2PE","2","16","16","ותהי לו תוכחת על חטאתו כי הבהמה האלמת דברה בקול אדם ותעצר באולת הקסם׃ ");
INSERT INTO heb_vpl VALUES ("P22_17","091_2_17","2PE","2","17","17","בארות בלי מים המה עבים נדפים בסערה אשר שמור להם חשך אפלה לעולם׃ ");
INSERT INTO heb_vpl VALUES ("P22_18","091_2_18","2PE","2","18","18","כי בדברם בגאות דברי שוא יצודו בתאות הבשר על ידי זמתם את אשר אך נמלטו מידי ההלכים בדרך תועה׃ ");
INSERT INTO heb_vpl VALUES ("P22_19","091_2_19","2PE","2","19","19","חפשה יבטיחו להם והם בעצמם עבדים לשחת כי האיש עבד לאשר נכבש ממנו׃ ");
INSERT INTO heb_vpl VALUES ("P22_20","091_2_20","2PE","2","20","20","כי אחרי המלטם מטמאת העולם בדעת אדנינו ומושיענו ישוע המשיח אם שבו והטבעו בתוכן ונכבשו אחריתם תהיה רעה מראשיתם׃ ");
INSERT INTO heb_vpl VALUES ("P22_21","091_2_21","2PE","2","21","21","טוב היה להם לא לדעת את דרך הצדקה מאשר ידעהו ונסגו אחור מן המצוה הקדושה המסורה להם׃ ");
INSERT INTO heb_vpl VALUES ("P22_22","091_2_22","2PE","2","22","22","ויקר להם כאשר יאמר משל האמת הכלב שב על קאו והחזיר עלה מן הרחצה להתגלל ברפש׃ ");
INSERT INTO heb_vpl VALUES ("P23_1","091_3_1","2PE","3","1","1","זאת היא האגרת השנית אשר אני כתב אליכם אהובים ובשתיהן אעיר בדרך הזכרה את תמת לבבכם׃ ");
INSERT INTO heb_vpl VALUES ("P23_2","091_3_2","2PE","3","2","2","לזכר את הדברים הנאמרים מקדם בידי הנביאים הקדשים ואת מצות אדנינו ומושיענו אשר נתנה בידנו השליחים׃ ");
INSERT INTO heb_vpl VALUES ("P23_3","091_3_3","2PE","3","3","3","ודעו זאת לכם ראשנה כי באחרית הימים יבאו לצים ההלכים אחרי תאות נפשם ויתלוצצו לאמר׃ ");
INSERT INTO heb_vpl VALUES ("P23_4","091_3_4","2PE","3","4","4","איה הבטחת באו כי מאז שכבו האבות הכל עמד כמו מראשית הבריאה׃ ");
INSERT INTO heb_vpl VALUES ("P23_5","091_3_5","2PE","3","5","5","ונסתר מהם באשר לא יאבו לדעת כי מקדם קמו השמים והארץ בדבר אלהים מן המים ועל ידי המים׃ ");
INSERT INTO heb_vpl VALUES ("P23_6","091_3_6","2PE","3","6","6","ובמים אבדה תבל מאז כי נשטפה במי המבול׃ ");
INSERT INTO heb_vpl VALUES ("P23_7","091_3_7","2PE","3","7","7","גם השמים והארץ אשר לפנינו נצפנו בדברו והם שמורים לאש ליום הדין ואבד אנשי הרשע׃ ");
INSERT INTO heb_vpl VALUES ("P23_8","091_3_8","2PE","3","8","8","וזאת האחת אל תעלם מכם אהובים כי יום אחד כאלף שנים בעיני יהוה ואלף שנים כיום אחד׃ ");
INSERT INTO heb_vpl VALUES ("P23_9","091_3_9","2PE","3","9","9","ולא יאחר יהוה את אשר הבטיח כאשר יש חשבים אתה לאחור כי אך האריך אפו בעבורנו ולא יחפץ באבד איש כי אם בפנות כלם לתשובה׃ ");
INSERT INTO heb_vpl VALUES ("P23_10","091_3_10","2PE","3","10","10","בא יבא יום יהוה כגנב בלילה אז השמים בשאון יחלפו והיסדות יבערו והתמגגו והארץ והמעשים אשר עליה ישרפו׃ ");
INSERT INTO heb_vpl VALUES ("P23_11","091_3_11","2PE","3","11","11","ועתה אם כל אלה ימוגו מה מאד חיבים אתם להתהלך בקדשה ובחסידות׃ ");
INSERT INTO heb_vpl VALUES ("P23_12","091_3_12","2PE","3","12","12","ולחכות לבא יום יהוה ולהחיש אתו אשר בגללו השמים ימוגו באש והיסדות יבערו ונמסו׃ ");
INSERT INTO heb_vpl VALUES ("P23_13","091_3_13","2PE","3","13","13","ואנחנו כפי הבטחתו מחכים לשמים חדשים ולארץ חדשה אשר צדק ילין בם׃ ");
INSERT INTO heb_vpl VALUES ("P23_14","091_3_14","2PE","3","14","14","על כן אהובים אשר לאלה חכיתם שקדו להמצא לפניו בשלום נקים וזכים מפשע׃ ");
INSERT INTO heb_vpl VALUES ("P23_15","091_3_15","2PE","3","15","15","ואת ארך רוח אדנינו תחשבו לתשועה כאשר גם אחינו האהוב פולוס כתב אליכם כפי החכמה הנתונה לו׃ ");
INSERT INTO heb_vpl VALUES ("P23_16","091_3_16","2PE","3","16","16","וכן בכל אגרותיו בדברו שם על אלה ובהם יש דברים קשי ההבנה והבערים והפתאים יהפכו אתם כאשר גם יעשו לכתבים האחרים לאבדן נפשם׃ ");
INSERT INTO heb_vpl VALUES ("P23_17","091_3_17","2PE","3","17","17","ואתם אהובים אשר ידעתם זאת השמרו לנפשתיכם פן תמשכו אחרי טעות אנשי בליעל ונפלתם ממעזכם׃ ");
INSERT INTO heb_vpl VALUES ("P23_18","091_3_18","2PE","3","18","18","ורבו בחסד ובדעת אדנינו ומושיענו ישוע המשיח אשר לו הכבוד גם היום וגם ליום העולם אמן׃ ");
INSERT INTO heb_vpl VALUES ("J11_1","092_1_1","1JN","1","1","1","את אשר היה מראש אשר שמענו ובעינינו ראינו אשר הבטנו ואשר מששו ידינו על דבר החיים׃ ");
INSERT INTO heb_vpl VALUES ("J11_2","092_1_2","1JN","1","2","2","והחיים נגלו ונרא ומעידים אנחנו ומודיעים לכם את חיי העולם אשר היו עם האב ונגלו לנו׃ ");
INSERT INTO heb_vpl VALUES ("J11_3","092_1_3","1JN","1","3","3","את אשר ראינו ושמענו נודיעה לכם למען תתחברו לנו גם אתם והתחברותנו היא עם האב ועם בנו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("J11_4","092_1_4","1JN","1","4","4","ואת זאת כתבים אנחנו לכם למען תהיה שמחתכם שלמה׃ ");
INSERT INTO heb_vpl VALUES ("J11_5","092_1_5","1JN","1","5","5","וזאת היא השמועה אשר שמענו ממנו ונגד לכם כי האלהים אור הוא וכל חשך אין בו׃ ");
INSERT INTO heb_vpl VALUES ("J11_6","092_1_6","1JN","1","6","6","אם נאמר כי יש לנו התחברות עמו ונתהלך בחשך הננו כזבים ופעלתנו איננה אמת׃ ");
INSERT INTO heb_vpl VALUES ("J11_7","092_1_7","1JN","1","7","7","אך אם באור נלך כאשר הוא באור הנה נתחברנו יחד ודם ישוע המשיח בנו יטהרנו מכל חטא׃ ");
INSERT INTO heb_vpl VALUES ("J11_8","092_1_8","1JN","1","8","8","אם נאמר כי אין בנו חטא הננו מתעים את נפשתינו והאמת אין בנו׃ ");
INSERT INTO heb_vpl VALUES ("J11_9","092_1_9","1JN","1","9","9","ואם נתודה את חטאתינו נאמן הוא וצדיק לסלח לנו את חטאתינו ולטהרנו מכל עון׃ ");
INSERT INTO heb_vpl VALUES ("J11_10","092_1_10","1JN","1","10","10","ואם נאמר כי לא חטאנו לכזב נשימנו ודברו אין בנו׃ ");
INSERT INTO heb_vpl VALUES ("J12_1","092_2_1","1JN","2","1","1","בני הנני כתב אליכם את זאת לבלתי תחטאו ואם יחטא איש יש לנו מליץ לפני אבינו ישוע המשיח הצדיק׃ ");
INSERT INTO heb_vpl VALUES ("J12_2","092_2_2","1JN","2","2","2","והוא כפרה על חטאתינו ולא על חטאתינו לבד כי גם על חטאת כל העולם׃ ");
INSERT INTO heb_vpl VALUES ("J12_3","092_2_3","1JN","2","3","3","ובזאת נדע כי הכרנו אותו אם נשמר את מצותיו׃ ");
INSERT INTO heb_vpl VALUES ("J12_4","092_2_4","1JN","2","4","4","האמר הכרתיו ואת מצותיו לא ישמר כזב הוא והאמת אין בו׃ ");
INSERT INTO heb_vpl VALUES ("J12_5","092_2_5","1JN","2","5","5","אבל השמר את דברו בו נשלמה באמת אהבת אלהים ובזאת נדע כי בו אנחנו׃ ");
INSERT INTO heb_vpl VALUES ("J12_6","092_2_6","1JN","2","6","6","האמר כי בו יעמד עליו להתהלך בדרך אשר גם הוא הלך׃ ");
INSERT INTO heb_vpl VALUES ("J12_7","092_2_7","1JN","2","7","7","אחי אינני כתב לכם מצוה חדשה כי אם מצוה ישנה אשר היתה לכם מראש והמצוה הישנה היא הדבר אשר שמעתם מראש׃ ");
INSERT INTO heb_vpl VALUES ("J12_8","092_2_8","1JN","2","8","8","ועוד מצוה חדשה אני כתב לכם אשר היא אמת גם בו גם בכם כי החשך עבר והאור האמתי כבר זורח׃ ");
INSERT INTO heb_vpl VALUES ("J12_9","092_2_9","1JN","2","9","9","האומר כי ישנו באור והוא שנא את אחיו עודנו בחשך׃ ");
INSERT INTO heb_vpl VALUES ("J12_10","092_2_10","1JN","2","10","10","האהב את אחיו יעמד באור ומכשול אין בו׃ ");
INSERT INTO heb_vpl VALUES ("J12_11","092_2_11","1JN","2","11","11","והשנא את אחיו בחשך הוא ובחשך יתהלך ולא ידע אנה הוא הלך כי החשך עור את עיניו׃ ");
INSERT INTO heb_vpl VALUES ("J12_12","092_2_12","1JN","2","12","12","הנני כתב אליכם הבנים יען כי נסלחו לכם חטאתיכם למען שמו׃ ");
INSERT INTO heb_vpl VALUES ("J12_13","092_2_13","1JN","2","13","13","כתב אני אליכם האבות יען כי הכרתם אתו אשר הוא מראש כתב אני אליכם הבחורים יען כי התגברתם על הרע כתב אני אליכם הילדים יען כי הכרתם את האב׃ ");
INSERT INTO heb_vpl VALUES ("J12_14","092_2_14","1JN","2","14","14","כתבתי אליכם האבות יען כי הכרתם אתו אשר הוא מראש כתבתי אליכם הבחורים יען כי חזקתם ודבר האלהים שכן בקרבכם והתגברתם על הרע׃ ");
INSERT INTO heb_vpl VALUES ("J12_15","092_2_15","1JN","2","15","15","אל תאהבו את החלד ואת דברי החלד אם יאהב איש את החלד אין בו אהבת האב׃ ");
INSERT INTO heb_vpl VALUES ("J12_16","092_2_16","1JN","2","16","16","כי כל אשר בחלד תאות הבשר ותאות העינים וגאות ההון איננו מן אבינו כי אם מן החלד׃ ");
INSERT INTO heb_vpl VALUES ("J12_17","092_2_17","1JN","2","17","17","והחלד עבור יעבר עם תאותיו והעשה רצון אלהים יעמד לעד׃ ");
INSERT INTO heb_vpl VALUES ("J12_18","092_2_18","1JN","2","18","18","ילדי הנה השעה האחרונה באה וכאשר שמעתם כי יבא צר המשיח כן עתה רבו צרי המשיח ובזאת נדע כי היא השעה האחרונה׃ ");
INSERT INTO heb_vpl VALUES ("J12_19","092_2_19","1JN","2","19","19","מאתנו יצאו אך לא משלנו היו כי אלו היו משלנו כי אז היו עמדים עמנו אבל למען יגלו כי לא כלם משלנו המה׃ ");
INSERT INTO heb_vpl VALUES ("J12_20","092_2_20","1JN","2","20","20","ואתם המשחה לכם מאת הקדוש וידעתם הכל׃ ");
INSERT INTO heb_vpl VALUES ("J12_21","092_2_21","1JN","2","21","21","לא כתבתי אליכם יען כי לא ידעתם את האמת אך יען כי ידעתם אתה ואשר כל כזב איננו מן האמת׃ ");
INSERT INTO heb_vpl VALUES ("J12_22","092_2_22","1JN","2","22","22","מי הוא הכזב אם לא המכחש בישוע לאמר כי איננו המשיח זה הוא צר המשיח המכחש באב ובבן׃ ");
INSERT INTO heb_vpl VALUES ("J12_23","092_2_23","1JN","2","23","23","כל המכחש בבן גם האב אין לו׃ ");
INSERT INTO heb_vpl VALUES ("J12_24","092_2_24","1JN","2","24","24","ואתם יקם נא בכם הדבר אשר שמעתם מראש ואם יקום בכם אשר שמעתם מראש אז גם אתם תקומו בבן ובאב׃ ");
INSERT INTO heb_vpl VALUES ("J12_25","092_2_25","1JN","2","25","25","וההבטחה אשר הבטיחנו היא חיי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("J12_26","092_2_26","1JN","2","26","26","זאת כתבתי אליכם מפני המתעים אתכם׃ ");
INSERT INTO heb_vpl VALUES ("J12_27","092_2_27","1JN","2","27","27","ואתם המשחה אשר קבלתם מאתו עמדת בכם ולא תצטרכו לאיש אשר ילמדכם כי אם כאשר תלמד אתכם המשחה בכל דבר היא האמת ואיננה כזב וכאשר למדה אתכם כן תעמדו בו׃ ");
INSERT INTO heb_vpl VALUES ("J12_28","092_2_28","1JN","2","28","28","ועתה בנים עמדו בו למען יאמץ לבנו בהראותו ולא נבוש מפניו בבואו׃ ");
INSERT INTO heb_vpl VALUES ("J12_29","092_2_29","1JN","2","29","29","אם ידעתם כי צדיק הוא דעו כי כל עשה צדקה נולד ממנו׃ ");
INSERT INTO heb_vpl VALUES ("J13_1","092_3_1","1JN","3","1","1","ראו מה גדלה אהבת האב הנתונה לנו אשר נקרא בני האלהים על כן העולם איננו ידע אתנו יען כי אותו לא ידע׃ ");
INSERT INTO heb_vpl VALUES ("J13_2","092_3_2","1JN","3","2","2","אהובי עתה בנים לאלהים אנחנו ועוד לא נגלה מה נהיה אך ידענו כי בהגלותו נדמה לו כי נראהו כאשר הוא׃ ");
INSERT INTO heb_vpl VALUES ("J13_3","092_3_3","1JN","3","3","3","וכל אשר לו תקוה כזאת יטהר את עצמו כאשר טהור גם הוא׃ ");
INSERT INTO heb_vpl VALUES ("J13_4","092_3_4","1JN","3","4","4","כל העשה חטא גם פשע בתורה הוא והחטא הוא פשע בתורה׃ ");
INSERT INTO heb_vpl VALUES ("J13_5","092_3_5","1JN","3","5","5","וידעתם כי הוא נגלה לשאת את חטאינו ובו אין חטא׃ ");
INSERT INTO heb_vpl VALUES ("J13_6","092_3_6","1JN","3","6","6","כל העמד בו לא יחטא כל החוטא לא ראהו גם לא ידעו׃ ");
INSERT INTO heb_vpl VALUES ("J13_7","092_3_7","1JN","3","7","7","בני אל יתעה אתכם איש העשה צדקה צדיק הוא כאשר הוא צדיק׃ ");
INSERT INTO heb_vpl VALUES ("J13_8","092_3_8","1JN","3","8","8","והעשה חטא מן השטן הוא כי השטן חטא מראש לזאת נגלה בן האלהים להפר את פעלות השטן׃ ");
INSERT INTO heb_vpl VALUES ("J13_9","092_3_9","1JN","3","9","9","כל הנולד מאלהים לא יחטא כי זרעו בו יקום ולא יוכל לחטא כי מאלהים נולד׃ ");
INSERT INTO heb_vpl VALUES ("J13_10","092_3_10","1JN","3","10","10","ונודעו בזאת בני האלהים ובני השטן כל איש אשר לא יעשה צדקה איננו מאלהים וכן כל אשר לא יאהב את אחיו׃ ");
INSERT INTO heb_vpl VALUES ("J13_11","092_3_11","1JN","3","11","11","כי זאת היא השמועה אשר שמעתם מראש לאהבה איש את רעהו׃ ");
INSERT INTO heb_vpl VALUES ("J13_12","092_3_12","1JN","3","12","12","לא כקין אשר היה מן הרע והרג את אחיו ומדוע הרגו יען כי מעשיו היו רעים ומעשי אחיו מעשי צדק׃ ");
INSERT INTO heb_vpl VALUES ("J13_13","092_3_13","1JN","3","13","13","אל תתמהו אחי אם ישנא אתכם העולם׃ ");
INSERT INTO heb_vpl VALUES ("J13_14","092_3_14","1JN","3","14","14","אנחנו ידענו כי עברנו מן המות אל החיים על כי נאהב את אחינו איש אשר לא יאהב את אחיו ישאר במות׃ ");
INSERT INTO heb_vpl VALUES ("J13_15","092_3_15","1JN","3","15","15","כל השנא את אחיו רצח נפש הוא וידעתם כי כל רצח נפש לא יתקימו בו חיי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("J13_16","092_3_16","1JN","3","16","16","בזאת הכרנו את האהבה כי הוא נתן את נפשו בעדנו גם אנחנו חיבים לתת את נפשתינו בעד אחינו׃ ");
INSERT INTO heb_vpl VALUES ("J13_17","092_3_17","1JN","3","17","17","ואיש אשר לו נכסי העולם והוא ראה את אחיו חסר לחם וקפץ את רחמיו ממנו איך תעמד בו אהבת אלהים׃ ");
INSERT INTO heb_vpl VALUES ("J13_18","092_3_18","1JN","3","18","18","בני אל נא נאהב במלין ובלשון כי אם בפעל ובאמת׃ ");
INSERT INTO heb_vpl VALUES ("J13_19","092_3_19","1JN","3","19","19","ובזאת נדעה כי מן האמת אנחנו ולפניו נשקיט את לבותינו׃ ");
INSERT INTO heb_vpl VALUES ("J13_20","092_3_20","1JN","3","20","20","כי אם לבבנו ירשיע אתנו האלהים נשגב הוא מלבבנו וידע את כל׃ ");
INSERT INTO heb_vpl VALUES ("J13_21","092_3_21","1JN","3","21","21","אהובי אם לבבנו לא ירשיענו בטחון לנו באלהים׃ ");
INSERT INTO heb_vpl VALUES ("J13_22","092_3_22","1JN","3","22","22","וכל אשר נשאל מאתו נקבל כי נשמר את מצותיו ונעשה את הרצוי לפניו׃ ");
INSERT INTO heb_vpl VALUES ("J13_23","092_3_23","1JN","3","23","23","וזאת היא מצותו להאמין בשם בנו ישוע המשיח ולאהבה איש את רעהו כאשר צונו׃ ");
INSERT INTO heb_vpl VALUES ("J13_24","092_3_24","1JN","3","24","24","והשמר את מצותיו יקום בו והוא בו ובזאת נדע כי הוא שכן בנו ברוח אשר נתן לנו׃ ");
INSERT INTO heb_vpl VALUES ("J14_1","092_4_1","1JN","4","1","1","אהובי אל תאמינו לכל רוח כי אם בחנו הרוחות אם מאלהים המה כי נביאי שקר רבים יצאו לעולם׃ ");
INSERT INTO heb_vpl VALUES ("J14_2","092_4_2","1JN","4","2","2","בזאת תכירו את רוח אלהים כל רוח המודה בישוע המשיח כי בא בבשר מאלהים הוא׃ ");
INSERT INTO heb_vpl VALUES ("J14_3","092_4_3","1JN","4","3","3","וכל רוח אשר איננו מודה בישוע האדון כי בא בבשר לא מאלהים הוא וזה הוא רוח צר המשיח אשר שמעתם עליו כי בוא יבא ועתה הנה הוא בעולם׃ ");
INSERT INTO heb_vpl VALUES ("J14_4","092_4_4","1JN","4","4","4","אתם הבנים הנכם מאלהים ונצחתם אתם כי אשר בכם גדול הוא מאשר בעולם׃ ");
INSERT INTO heb_vpl VALUES ("J14_5","092_4_5","1JN","4","5","5","המה מן העולם על כן מהעולם ידברו והעולם ישמע אליהם׃ ");
INSERT INTO heb_vpl VALUES ("J14_6","092_4_6","1JN","4","6","6","ואנחנו מאלהים הננו היודע את האלהים ישמע אלינו ואשר איננו מאלהים לא ישמע אלינו בזאת נכיר את רוח האמת ואת רוח התועה׃ ");
INSERT INTO heb_vpl VALUES ("J14_7","092_4_7","1JN","4","7","7","אהובי נאהב נא איש את רעהו כי האהבה מאלהים היא וכל אשר יאהב נולד מאלהים וידע את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("J14_8","092_4_8","1JN","4","8","8","ואשר איננו אהב לא ידע את האלהים כי האלהים הוא אהבה׃ ");
INSERT INTO heb_vpl VALUES ("J14_9","092_4_9","1JN","4","9","9","בזאת נראתה אהבת האלהים לנו כי שלח האלהים את בנו את יחידו לעולם למען נחיה על ידו׃ ");
INSERT INTO heb_vpl VALUES ("J14_10","092_4_10","1JN","4","10","10","בזאת היא האהבה לא שאנחנו אהבנו את האלהים כי אם הוא אהב אותנו וישלח את בנו לכפרה על חטאתינו׃ ");
INSERT INTO heb_vpl VALUES ("J14_11","092_4_11","1JN","4","11","11","אהובי אם ככה אהב אתנו האלהים גם אנחנו חיבים לאהבה איש את רעהו׃ ");
INSERT INTO heb_vpl VALUES ("J14_12","092_4_12","1JN","4","12","12","את האלהים לא ראה איש מעולם ואם נאהב איש את רעהו האלהים יעמד בקרבנו ואהבתו נשלמה בנו׃ ");
INSERT INTO heb_vpl VALUES ("J14_13","092_4_13","1JN","4","13","13","בזאת נדע אשר בו נקום והוא בנו כי נתן לנו מרוחו׃ ");
INSERT INTO heb_vpl VALUES ("J14_14","092_4_14","1JN","4","14","14","ואנחנו חזינו ונעידה כי האב שלח את הבן מושיע העולם׃ ");
INSERT INTO heb_vpl VALUES ("J14_15","092_4_15","1JN","4","15","15","כל המודה כי ישוע הוא בן האלהים האלהים שכן בו והוא באלהים׃ ");
INSERT INTO heb_vpl VALUES ("J14_16","092_4_16","1JN","4","16","16","ואנחנו ידענו ונאמן באהבה אשר אלהים אהב אתנו האלהים הוא אהבה והעמד באהבה עמד באלהים והאלהים עמד בו׃ ");
INSERT INTO heb_vpl VALUES ("J14_17","092_4_17","1JN","4","17","17","ובזאת נשלמה בנו האהבה בהיות לנו בטחון ביום הדין כי כמהו כן גם אנחנו בעולם הזה׃ ");
INSERT INTO heb_vpl VALUES ("J14_18","092_4_18","1JN","4","18","18","אין אימה באהבה כי אם האהבה השלמה תגרש את האימה כי באימה מעצבה ואשר באימה איננו שלם באהבה׃ ");
INSERT INTO heb_vpl VALUES ("J14_19","092_4_19","1JN","4","19","19","אנחנו אהבים אתו כי הוא קדם לאהבה אתנו׃ ");
INSERT INTO heb_vpl VALUES ("J14_20","092_4_20","1JN","4","20","20","כי יאמר איש אהב אני את האלהים והוא שנא את אחיו כזב הוא כי אשר לא יאהב את אחיו אשר הוא ראה איככה יוכל לאהב את האלהים אשר איננו ראה אתו׃ ");
INSERT INTO heb_vpl VALUES ("J14_21","092_4_21","1JN","4","21","21","וזאת המצוה יש לנו מאתו כי האהב את האלהים יאהב גם את אחיו׃ ");
INSERT INTO heb_vpl VALUES ("J15_1","092_5_1","1JN","5","1","1","כל המאמין כי ישוע הוא המשיח הנה זה ילד מאלהים וכל האהב את מולידו יאהב גם את הנולד מאתו׃ ");
INSERT INTO heb_vpl VALUES ("J15_2","092_5_2","1JN","5","2","2","בזאת נדע כי נאהב את בני האלהים באהבתנו את האלהים ובשמרנו את מצותיו׃ ");
INSERT INTO heb_vpl VALUES ("J15_3","092_5_3","1JN","5","3","3","כי זאת אהבת אלהים היא אשר נשמר את מצותיו ומצותיו אינן כבדות׃ ");
INSERT INTO heb_vpl VALUES ("J15_4","092_5_4","1JN","5","4","4","כי כל הנולד מאת האלהים מנצח את העולם ואמונתנו הנצחון המנצח את העולם׃ ");
INSERT INTO heb_vpl VALUES ("J15_5","092_5_5","1JN","5","5","5","מי הוא זה המנצח את העולם אם לא המאמין בישוע שהוא בן האלהים׃ ");
INSERT INTO heb_vpl VALUES ("J15_6","092_5_6","1JN","5","6","6","זה הוא אשר בא במים ובדם ישוע המשיח לא במים לבד כי אם במים ובדם והרוח הוא המעיד כי הרוח הוא האמת׃ ");
INSERT INTO heb_vpl VALUES ("J15_7","092_5_7","1JN","5","7","7","כי שלשה המה המעידים בשמים האב הדבר ורוח הקדש ושלשתם אחד המה׃ ");
INSERT INTO heb_vpl VALUES ("J15_8","092_5_8","1JN","5","8","8","ושלשה המה המעידים בארץ הרוח המים והדם ושלשתם לאחת המה׃ ");
INSERT INTO heb_vpl VALUES ("J15_9","092_5_9","1JN","5","9","9","אם נקבל עדות בני אדם הנה עדות האלהים גדולה ממנה כי זאת היא עדות האלהים אשר העיד על בנו׃ ");
INSERT INTO heb_vpl VALUES ("J15_10","092_5_10","1JN","5","10","10","המאמין בבן האלהים יש לו העדות בנפשו ואשר לא יאמין לאלהים לכזב שמהו יען לא האמין בעדות אשר העיד האלהים על בנו׃ ");
INSERT INTO heb_vpl VALUES ("J15_11","092_5_11","1JN","5","11","11","וזאת היא העדות כי חיי עולמים נתן לנו האלהים והחיים האלה בבנו המה׃ ");
INSERT INTO heb_vpl VALUES ("J15_12","092_5_12","1JN","5","12","12","אשר יש לו הבן יש לו החיים ואשר אין לו בן האלהים אין לו החיים׃ ");
INSERT INTO heb_vpl VALUES ("J15_13","092_5_13","1JN","5","13","13","זאת כתבתי אליכם המאמינים בשם בן האלהים למען תדעון שיש לכם חיי עולם ולמען תאמינו בשם בן האלהים׃ ");
INSERT INTO heb_vpl VALUES ("J15_14","092_5_14","1JN","5","14","14","וזה הוא בטחוננו אליו אשר אם נשאל דבר כפי רצונו ישמענו׃ ");
INSERT INTO heb_vpl VALUES ("J15_15","092_5_15","1JN","5","15","15","ומדעתנו כי ישמענו לכל אשר נשאל נדע גם זאת כי נשיג את המשאלות אשר שאלנו ממנו׃ ");
INSERT INTO heb_vpl VALUES ("J15_16","092_5_16","1JN","5","16","16","איש כי יראה את אחיו חוטא חטאת אשר לא למות שאל ישאל בעדו ויתן לו חיים לכל אשר חטאו לא למות הן יש חטא למות על זה לא אמר לשאל בעדו׃ ");
INSERT INTO heb_vpl VALUES ("J15_17","092_5_17","1JN","5","17","17","כל מעשה שלא כמשפט חטא היא ויש חטא שלא למות׃ ");
INSERT INTO heb_vpl VALUES ("J15_18","092_5_18","1JN","5","18","18","ידענו כי כל הנולד מאת האלהים לא יחטא כי אשר ילד מאת האלהים ישמר את נפשו והרע לא יגע בו׃ ");
INSERT INTO heb_vpl VALUES ("J15_19","092_5_19","1JN","5","19","19","ידענו כי מאלהים אנחנו וכל העולם ברע הוא׃ ");
INSERT INTO heb_vpl VALUES ("J15_20","092_5_20","1JN","5","20","20","וידענו כי בא בן אלהים ויתן לנו בינה לדעת את האמתי ובאמתי אנחנו בבנו ישוע המשיח זה הוא האל האמתי וחיי העולם׃ ");
INSERT INTO heb_vpl VALUES ("J15_21","092_5_21","1JN","5","21","21","בני השמרו לכם מן האלילים אמן׃ ");
INSERT INTO heb_vpl VALUES ("J21_1","093_1_1","2JN","1","1","1","הזקן אל הגבירה הבחירה ואל בניה אשר אני אהב אתם באמת ולא אני לבדי כי אם גם כל ידעי האמת׃ ");
INSERT INTO heb_vpl VALUES ("J21_2","093_1_2","2JN","1","2","2","למען האמת העמדת בקרבנו וגם תהיה עמנו לעולם׃ ");
INSERT INTO heb_vpl VALUES ("J21_3","093_1_3","2JN","1","3","3","יהי עמכם חסד ורחמים ושלום מאת האלהים אבינו ומאת אדנינו ישוע המשיח בן האב באמת ובאהבה׃ ");
INSERT INTO heb_vpl VALUES ("J21_4","093_1_4","2JN","1","4","4","שמחתי למאד כי מצאתי מבניך מתהלכים באמת כמצוה אשר קבלנו מאת האב׃ ");
INSERT INTO heb_vpl VALUES ("J21_5","093_1_5","2JN","1","5","5","ועתה מבקש אני ממך הגבירה ולא ככתב אליך מצוה חדשה כי אם את אשר היתה לנו מראש לאהבה איש את רעהו׃ ");
INSERT INTO heb_vpl VALUES ("J21_6","093_1_6","2JN","1","6","6","וזאת היא האהבה אשר נתהלך במצותיו זאת היא המצוה אשר שמעתם מראש להתהלך בה׃ ");
INSERT INTO heb_vpl VALUES ("J21_7","093_1_7","2JN","1","7","7","כי מתעים רבים באו לעולם אשר אינם מודים בישוע המשיח כי בא בבשר זה הוא המתעה וצר המשיח׃ ");
INSERT INTO heb_vpl VALUES ("J21_8","093_1_8","2JN","1","8","8","השמרו לכם פן תאבד ממנו פעלתנו כי אם נקח משכרתנו שלמה׃ ");
INSERT INTO heb_vpl VALUES ("J21_9","093_1_9","2JN","1","9","9","כל העבר על תורת המשיח ואיננו עמד בה אין לו אלהים והעמד בתורת המשיח יש לו גם האב גם הבן׃ ");
INSERT INTO heb_vpl VALUES ("J21_10","093_1_10","2JN","1","10","10","כל הבא אליכם ולא יביא את התורה הזאת לא תאספו אתו הביתה ולא תשאלו לו לשלום׃ ");
INSERT INTO heb_vpl VALUES ("J21_11","093_1_11","2JN","1","11","11","כי השאל בשלומו הוא משתתף במעשיו הרעים׃ ");
INSERT INTO heb_vpl VALUES ("J21_12","093_1_12","2JN","1","12","12","הרבה לי לכתב אליכם ולא חפצתי בניר ובדיו כי אקוה לבוא אליכם ולדבר פה אל פה למען תהיה שמחתנו שלמה׃ ");
INSERT INTO heb_vpl VALUES ("J21_13","093_1_13","2JN","1","13","13","בני אחותך הבחירה שאלים לשלומך אמן׃ ");
INSERT INTO heb_vpl VALUES ("J31_1","094_1_1","3JN","1","1","1","הזקן אל גיוס החביב אשר אני אהב אתו באמת׃ ");
INSERT INTO heb_vpl VALUES ("J31_2","094_1_2","3JN","1","2","2","חביבי חפצי הוא כי ייטב לך בכל דבר ותחזק כאשר טוב לך בנפשך׃ ");
INSERT INTO heb_vpl VALUES ("J31_3","094_1_3","3JN","1","3","3","כי שמחתי למאד כאשר באו אחים ויעידו על אמתך אשר מתהלך באמת אתה׃ ");
INSERT INTO heb_vpl VALUES ("J31_4","094_1_4","3JN","1","4","4","אין לי שמחה גדולה מלשמע את אשר בני יתהלכו באמת׃ ");
INSERT INTO heb_vpl VALUES ("J31_5","094_1_5","3JN","1","5","5","חביבי באמונה כל מעשיך עם האחים ועם הארחים׃ ");
INSERT INTO heb_vpl VALUES ("J31_6","094_1_6","3JN","1","6","6","אשר העידו על אהבתך בפני הקהל ואף תיטיב לעשות בלותך אתם כאשר יאתה לפני אלהים׃ ");
INSERT INTO heb_vpl VALUES ("J31_7","094_1_7","3JN","1","7","7","כי בעבור שמו יצאו ולא לקחו מאומה מן הגוים׃ ");
INSERT INTO heb_vpl VALUES ("J31_8","094_1_8","3JN","1","8","8","על כן חיבים אנחנו לקבל אתם למען נהיה עזרים לאמת׃ ");
INSERT INTO heb_vpl VALUES ("J31_9","094_1_9","3JN","1","9","9","אני כתבתי אל הקהלה אך דיוטריפס המתאוה להיות עליהם לראש איננו מקבל אתנו׃ ");
INSERT INTO heb_vpl VALUES ("J31_10","094_1_10","3JN","1","10","10","על כן בבאי אזכיר את מעשיו אשר הוא עשה בספרו עלינו דברים רעים ולא דיו שלא יקבל את האחים כי גם ימנע את החפצים לקבל ויגרשם מתוך הקהלה׃ ");
INSERT INTO heb_vpl VALUES ("J31_11","094_1_11","3JN","1","11","11","חביבי אל תרדף הרעה כי אם הטוב העשה טוב הוא מאלהים והעשה רע לא ראה את האלהים׃ ");
INSERT INTO heb_vpl VALUES ("J31_12","094_1_12","3JN","1","12","12","על דימטריוס העידו הכל וגם האמת עצמה וגם אנחנו מעידים עליו וידעתם כי עדותנו היא נאמנה׃ ");
INSERT INTO heb_vpl VALUES ("J31_13","094_1_13","3JN","1","13","13","הרבה לי לכתב ולא חפצתי לכתב אליך בדיו ובקנה׃ ");
INSERT INTO heb_vpl VALUES ("J31_14","094_1_14","3JN","1","14","14","אבל אקוה לראותך במהרה ופה אל פה נדבר׃  (III John 1:15) שלום לך הרעים שאלים לשלומך שאל לשלום הרעים לאיש איש בשמו׃  ");
INSERT INTO heb_vpl VALUES ("JD1_1","095_1_1","JUD","1","1","1","יהודה עבד ישוע המשיח ואחי יעקב אל המקראים אשר הם מקדשים באלהים האב ושמורים לישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("JD1_2","095_1_2","JUD","1","2","2","רחמים ושלום ואהבה יהיו לכם למכביר׃ ");
INSERT INTO heb_vpl VALUES ("JD1_3","095_1_3","JUD","1","3","3","אהובי בהשתדלי לכתב אליכם על דבר התשועה האחת לכלנו חובה היא בעיני לזרזכם במכתב אשר תלחמו לאמונה המסורה פעם אחת לקדושים׃ ");
INSERT INTO heb_vpl VALUES ("JD1_4","095_1_4","JUD","1","4","4","כי התגנבו לבוא מקצת אנשים הכתובים מאז למשפט הזה אנשי רשע ההפכים את חסד אלהינו לזמה וכפרים באלהים המשל היחיד ובאדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("JD1_5","095_1_5","JUD","1","5","5","ויש את נפשי להזכיר אתכם את אשר כבר ידעתם כי הושיע יהוה את העם ממצרים וישמד אחרי כן את אשר לא האמינו׃ ");
INSERT INTO heb_vpl VALUES ("JD1_6","095_1_6","JUD","1","6","6","והמלאכים אשר לא שמרו את משרתם כי אם עזבו את זבלם שמרם במוסרות עולם ובאפלה למשפט היום הגדול׃ ");
INSERT INTO heb_vpl VALUES ("JD1_7","095_1_7","JUD","1","7","7","כאשר סדום ועמרה והערים סביבותיהן אשר הזנו כמוהם וילכו אחרי בשר זר נהיו כראי כי נמסרו למוסר אש עולם׃ ");
INSERT INTO heb_vpl VALUES ("JD1_8","095_1_8","JUD","1","8","8","וכן גם בעלי החלמות האלה מטמאים את הבשר ואת הממשלה ינאצו ואת השררות יחרפו׃ ");
INSERT INTO heb_vpl VALUES ("JD1_9","095_1_9","JUD","1","9","9","ומיכאל שר המלאכים בהתוכחו עם השטן וירב אתו על אדות גוית משה לא מלאו לבו לחרץ משפט גדופים כי אם אמר יגער יהוה בך׃ ");
INSERT INTO heb_vpl VALUES ("JD1_10","095_1_10","JUD","1","10","10","ואלה מגדפים את אשר לא ידעו ובדברים אשר יבינו מחק טבעים כבהמות הסכלות בהמה ישחיתו את נפשם׃ ");
INSERT INTO heb_vpl VALUES ("JD1_11","095_1_11","JUD","1","11","11","אוי להם כי ברדך קין הלכו וישתקעו בתועת בלעם לקבל שכר ובמרי קרח אבדו׃ ");
INSERT INTO heb_vpl VALUES ("JD1_12","095_1_12","JUD","1","12","12","הלא צורי מכשול המה בסעודתיכם של אהבה ובקלות ראש יאכלו וישתו עמכם ורעים את נפשם עננים הם בבלי מים הנדפים מפני רוח עצי חרף באין פרי אשר מתו פעמים ונעקרו׃ ");
INSERT INTO heb_vpl VALUES ("JD1_13","095_1_13","JUD","1","13","13","משברי ים עזים אשר יגרשו בשתם ככבים תעים אשר חשך אפלה צפון להם עדי עד׃ ");
INSERT INTO heb_vpl VALUES ("JD1_14","095_1_14","JUD","1","14","14","וגם חנוך השביעי לאדם נבא לאלה לאמר הנה יהוה בא ברבבת קדשיו׃ ");
INSERT INTO heb_vpl VALUES ("JD1_15","095_1_15","JUD","1","15","15","לעשות משפט בכלם ולהוכיח כל רשעי ארץ על כל מעשי רשעתם ועל כל הקשות אשר דברו עליו חטאים אנשי רשע׃ ");
INSERT INTO heb_vpl VALUES ("JD1_16","095_1_16","JUD","1","16","16","אלה הם הרגנים והמתאוננים ההלכים אחרי תאותיהם אשר פיהם ידבר עתק הדרי פנים עקב שחד׃ ");
INSERT INTO heb_vpl VALUES ("JD1_17","095_1_17","JUD","1","17","17","ואתם האהובים זכרו את הדברים הנאמרים מקדם ביד שליחי אדנינו ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("JD1_18","095_1_18","JUD","1","18","18","בדברם אליכם לאמר הנה באחרית הימים יבאו לצים ההלכים אחרי תאות רשעם׃ ");
INSERT INTO heb_vpl VALUES ("JD1_19","095_1_19","JUD","1","19","19","אלה הם הפרשים מן הצבור אנשים נפשיים ורוח אין בהם׃ ");
INSERT INTO heb_vpl VALUES ("JD1_20","095_1_20","JUD","1","20","20","ואתם האהובים הבנו באמונתכם הנעלה על כל בקדשתה והתפללו ברוח הקדש׃ ");
INSERT INTO heb_vpl VALUES ("JD1_21","095_1_21","JUD","1","21","21","ושמרתם את נפשתיכם באהבת אלהים וחכיתם לרחמי אדנינו ישוע המשיח לחיי העולם׃ ");
INSERT INTO heb_vpl VALUES ("JD1_22","095_1_22","JUD","1","22","22","הבדילו את אלה והתנהגו עמהם ברחמים׃ ");
INSERT INTO heb_vpl VALUES ("JD1_23","095_1_23","JUD","1","23","23","ואת אלה תושיעו באימה וחלצתם אתם מתוך האש וגעלתם גם את הלבוש המגאל בחלאת הבשר׃ ");
INSERT INTO heb_vpl VALUES ("JD1_24","095_1_24","JUD","1","24","24","ולאשר יכול לשמרכם בבלי מכשול ולהעמיד אתכם בששון תמימים לפני כבודו׃ ");
INSERT INTO heb_vpl VALUES ("JD1_25","095_1_25","JUD","1","25","25","לאלהים אשר לו לבדו החכמה המושיע אתנו לו הכבוד והגדלה והעז והממשלה מעתה ולעולמי עד אמן׃ ");
INSERT INTO heb_vpl VALUES ("RV1_1","096_1_1","REV","1","1","1","חזון ישוע המשיח אשר נתן לו האלהים להראות את עבדיו את אשר היה יהיה במהרה והוא הודיע בשלחו ביד מלאכו לעבדו יוחנן׃ ");
INSERT INTO heb_vpl VALUES ("RV1_2","096_1_2","REV","1","2","2","אשר העיד דבר האלהים ועדות ישוע המשיח ואת כל אשר ראה׃ ");
INSERT INTO heb_vpl VALUES ("RV1_3","096_1_3","REV","1","3","3","אשרי הקורא ואשרי השמעים את דברי הנבואה ושמרים את אשר כתוב בה כי קרובה העת׃ ");
INSERT INTO heb_vpl VALUES ("RV1_4","096_1_4","REV","1","4","4","יוחנן אל שבע הקהלות אשר באסיא חסד לכם ושלום מאת ההוה והיה ויבוא ומן שבעת הרוחות אשר לפני כסאו׃ ");
INSERT INTO heb_vpl VALUES ("RV1_5","096_1_5","REV","1","5","5","ומאת ישוע המשיח העד הנאמן ובכור מן המתים ועליון למלכי ארץ לו אשר אהב אתנו ובדמו גאלנו מחטאתינו׃ ");
INSERT INTO heb_vpl VALUES ("RV1_6","096_1_6","REV","1","6","6","ויעש אתנו למלכים וכהנים לאלהים אביו הכבוד והעז לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("RV1_7","096_1_7","REV","1","7","7","הנה הוא בא עם העננים וראתה אתו כל עין גם אלה אשר דקרהו וספדו עליו כל משפחות הארץ כן יהיה אמן׃ ");
INSERT INTO heb_vpl VALUES ("RV1_8","096_1_8","REV","1","8","8","אני האלף ואני התו ראש וסוף נאם יהוה אלהים ההוה והיה ויבוא אלהי צבאות׃ ");
INSERT INTO heb_vpl VALUES ("RV1_9","096_1_9","REV","1","9","9","אני יוחנן אחיכם וגם חבר לכם בלחץ ובמלכות ובסבלנות למען ישוע המשיח הייתי באי אשר שמו פטמוס בעבור דבר האלהים ובעבור עדות ישוע המשיח׃ ");
INSERT INTO heb_vpl VALUES ("RV1_10","096_1_10","REV","1","10","10","ואהי ברוח ביום האדון ואשמע אחרי קול גדול כקול שופר׃ ");
INSERT INTO heb_vpl VALUES ("RV1_11","096_1_11","REV","1","11","11","ויאמר אני האלף ואני התו הראשון והאחרון ואת אשר אתה ראה כתב אל ספר ושלחהו אל הקהלות אשר באסיא לאפסוס ולזמירנא ולפרגמוס ולתיאטירא ולסרדיס ולפילדפיא וללודקיא׃ ");
INSERT INTO heb_vpl VALUES ("RV1_12","096_1_12","REV","1","12","12","ואפן לראות את הקול המדבר אלי ויהי בפנותי וארא שבע מנרות זהב׃ ");
INSERT INTO heb_vpl VALUES ("RV1_13","096_1_13","REV","1","13","13","ובתוך שבע המנרות דמות בן אדם לבוש מעיל וחגור אזור זהב על לבו׃ ");
INSERT INTO heb_vpl VALUES ("RV1_14","096_1_14","REV","1","14","14","וראשו ושערו לבנים כצמר צחר כשלג ועיניו כלבת אש׃ ");
INSERT INTO heb_vpl VALUES ("RV1_15","096_1_15","REV","1","15","15","ומרגלתיו כעין נחשת קלל כצרופות בכור וקולו כקול מים רבים׃ ");
INSERT INTO heb_vpl VALUES ("RV1_16","096_1_16","REV","1","16","16","ויהי לו ביד ימינו שבעה כוכבים ומפיו יוצאת חרב פיפיות חדה ופניו כשמש המאיר בגבורתו׃ ");
INSERT INTO heb_vpl VALUES ("RV1_17","096_1_17","REV","1","17","17","וכראתי אותו ואפל לרגליו כמת וישת עלי יד ימינו ויאמר אל תירא אני הראשון והאחרון והחי׃ ");
INSERT INTO heb_vpl VALUES ("RV1_18","096_1_18","REV","1","18","18","ואהי מת והנני חי לעולמי עולמים אמן ובידי מפתחות שאול ומות׃ ");
INSERT INTO heb_vpl VALUES ("RV1_19","096_1_19","REV","1","19","19","ועתה כתב את אשר ראית ואשר נעשה עתה ואשר עתיד להיות אחרי כן׃ ");
INSERT INTO heb_vpl VALUES ("RV1_20","096_1_20","REV","1","20","20","את סוד שבעת הכוכבים אשר ראית בימיני ואת שבע מנרות הזהב שבעת הכוכבים הם מלאכי שבע הקהלות ושבע המנרות אשר ראית שבע קהלות הנה׃ ");
INSERT INTO heb_vpl VALUES ("RV2_1","096_2_1","REV","2","1","1","אל מלאך קהל אפסוס כתב כה אמר האחז בימינו שבעת הכוכבים המתהלך בתוך שבע מנרות הזהב׃ ");
INSERT INTO heb_vpl VALUES ("RV2_2","096_2_2","REV","2","2","2","ידעתי את מעשיך ואת עמלך ואת סבלך וכי לא תוכל שאת את הרשעים ותנסה את האמרים שליחים אנחנו ואינם ותמצאם כזבים׃ ");
INSERT INTO heb_vpl VALUES ("RV2_3","096_2_3","REV","2","3","3","ואתה נשאת הרבה ויש לך סבלנות ולמען שמי לא יעפת׃ ");
INSERT INTO heb_vpl VALUES ("RV2_4","096_2_4","REV","2","4","4","אך יש לי עליך כי עזבת את אהבתך הראשונה׃ ");
INSERT INTO heb_vpl VALUES ("RV2_5","096_2_5","REV","2","5","5","זכר אפוא אי מזה נפלת ושובה ועשה מעשיך הראשנים ואם לא הנני בא עליך מהר ונסחתי מנורתך ממקומה אם לא תשוב׃ ");
INSERT INTO heb_vpl VALUES ("RV2_6","096_2_6","REV","2","6","6","אבל זאת היא לך כי תשנא את מעשי הניקלסיים אשר שנאתים גם אני׃ ");
INSERT INTO heb_vpl VALUES ("RV2_7","096_2_7","REV","2","7","7","מי אשר אזן לו ישמע את אשר הרוח אמר לקהלות המנצח אתן לו לאכל מעץ החיים אשר בתוך גן עדן לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV2_8","096_2_8","REV","2","8","8","ואל מלאך קהל זמירנא כתב כה אמר הראשון והאחרון אשר מת ויחי׃ ");
INSERT INTO heb_vpl VALUES ("RV2_9","096_2_9","REV","2","9","9","ידעתי את מעשיך ואת צרתך ואת רישך ואולם עשיר אתה ואת גדוף האמרים יהודים אנחנו ואינם כי אם כנסית השטן׃ ");
INSERT INTO heb_vpl VALUES ("RV2_10","096_2_10","REV","2","10","10","אל תירא את אשר עליך לסבל הנה עתיד המלשין להשליך מכם לבית המשמר למען תנסו והייתם בצרה עשרת ימים היה נאמן עד מות ואתנה לך עטרת החיים׃ ");
INSERT INTO heb_vpl VALUES ("RV2_11","096_2_11","REV","2","11","11","מי אשר אזן לו ישמע את אשר הרוח אמר לקהלות המנצח לא ינזק במות השני׃ ");
INSERT INTO heb_vpl VALUES ("RV2_12","096_2_12","REV","2","12","12","ואל מלאך קהל פרגמוס כתב כה אמר אשר לו חרב פיפיות החדה׃ ");
INSERT INTO heb_vpl VALUES ("RV2_13","096_2_13","REV","2","13","13","ידעתי את מעשיך ואת מקום שבתך אשר שם כסא השטן ותדבק בשמי ולא שקרת באמונתי גם בימי אנטיפס עדי הנאמן אשר נהרג אצלכם מקום מושב השטן׃ ");
INSERT INTO heb_vpl VALUES ("RV2_14","096_2_14","REV","2","14","14","אך מעט יש לי עליך כי שם עמך אנשים דבקים בתורת בלעם אשר הורה את בלק לתת מכשול לפני בני ישראל לאכל מזבחי אלילים ולזנות׃ ");
INSERT INTO heb_vpl VALUES ("RV2_15","096_2_15","REV","2","15","15","כן נמצאו גם בך אנשים דבקים בתורת הניקלסיים אשר שנאתי׃ ");
INSERT INTO heb_vpl VALUES ("RV2_16","096_2_16","REV","2","16","16","שובה ואם לא כי עתה אבוא עליך מהרה ונלחמתי בם בחרב פי׃ ");
INSERT INTO heb_vpl VALUES ("RV2_17","096_2_17","REV","2","17","17","מי אשר אזן לו ישמע את אשר הרוח אמר לקהלות המנצח אאכילנו מן המן הגנוז ונתתי לו אבן לבנה ועל האבן מפתח שם חדש אשר לא ידענו איש זולתי המקבל׃ ");
INSERT INTO heb_vpl VALUES ("RV2_18","096_2_18","REV","2","18","18","ואל מלאך קהל תיאטירא כתב כה אמר בן האלהים אשר עיניו כלבת אש ומרגלתיו כעין נחשת קלל׃ ");
INSERT INTO heb_vpl VALUES ("RV2_19","096_2_19","REV","2","19","19","ידעתי את מעשיך ואהבתך ואמונתך ועבורתך וסבלך וכי מעשיך האחרונים רבים הם מן הראשנים׃ ");
INSERT INTO heb_vpl VALUES ("RV2_20","096_2_20","REV","2","20","20","אך מעט יש לי עליך כי תניח את האשה איזבל האמרת כי היא נביאה ללמד ולהתעות את עבדי לזנות ולאכל זבחי אלילים׃ ");
INSERT INTO heb_vpl VALUES ("RV2_21","096_2_21","REV","2","21","21","ואתן לה זמן לשוב והיא מאנה לשוב מתזנותיה׃ ");
INSERT INTO heb_vpl VALUES ("RV2_22","096_2_22","REV","2","22","22","הנני מפיל אתה על מטה ואת המנאפים אתה בצרה גדולה אם לא ישובו ממעשיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV2_23","096_2_23","REV","2","23","23","והרגתי במות את בניה וידעו כל הקהלות כי אני חקר כליות ולב ונתתי לכם לכל איש כפרי מעלליו׃ ");
INSERT INTO heb_vpl VALUES ("RV2_24","096_2_24","REV","2","24","24","אבל אמר אני לכם ולשאר הנמצאים בתיאטירא כל אשר אין להם הלקח ההוא ולא ידעו את עמקות השטן כאשר הם מתהללים לא אשים עליכם משא אחר׃ ");
INSERT INTO heb_vpl VALUES ("RV2_25","096_2_25","REV","2","25","25","אפס מה שיש לכם החזיקו בו עד כי אבוא׃ ");
INSERT INTO heb_vpl VALUES ("RV2_26","096_2_26","REV","2","26","26","והמנצח ושמר את מעשי עד עת קץ אתן לו שלטן על הגוים׃ ");
INSERT INTO heb_vpl VALUES ("RV2_27","096_2_27","REV","2","27","27","ורעם בשבט ברזל ככלי יוצר ינפצו כאשר קבלתי גם אנכי מאת אבי׃ ");
INSERT INTO heb_vpl VALUES ("RV2_28","096_2_28","REV","2","28","28","ונתתי לו כוכב השחר׃ ");
INSERT INTO heb_vpl VALUES ("RV2_29","096_2_29","REV","2","29","29","מי אשר אזן לו ישמע את אשר הרוח אמר לקהלות׃ ");
INSERT INTO heb_vpl VALUES ("RV3_1","096_3_1","REV","3","1","1","ואל מלאך קהל סרדיס כתב כה אמר אשר לו שבע רוחות האלהים ושבעת הכוכבים ידעתי את מעשיך כי לך שם כאלו אתה חי והנך מת׃ ");
INSERT INTO heb_vpl VALUES ("RV3_2","096_3_2","REV","3","2","2","שקד וחזק את השארית הקרובה למות כי לא מצאתי מעשיך שלמים לפני האלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV3_3","096_3_3","REV","3","3","3","זכור את אשר קבלת ושמעת ושמרה זאת ושובה ואם לא תשקד הנני בא עליך כגנב ולא תדע באי זו שעה אבא עליך׃ ");
INSERT INTO heb_vpl VALUES ("RV3_4","096_3_4","REV","3","4","4","יש לך גם בסרדיס שמות מעטים אשר לא גאלו את מלבושיהם ויתהלכו אתי לבשי לבנים כי ראוים הם לזאת׃ ");
INSERT INTO heb_vpl VALUES ("RV3_5","096_3_5","REV","3","5","5","המנצח ילבש בגדים לבנים ולא אמחה את שמו מספר החיים ואודה שמו לפני אבי ולפני מלאכיו׃ ");
INSERT INTO heb_vpl VALUES ("RV3_6","096_3_6","REV","3","6","6","מי אשר אזן לו ישמע את אשר הרוח אמר לקהלות׃ ");
INSERT INTO heb_vpl VALUES ("RV3_7","096_3_7","REV","3","7","7","ואל מלאך קהל פילדלפיא כתב כה אמר הקדוש האמתי אשר בידו מפתח דוד הפתח ואין סגר והסגר ואין פתח׃ ");
INSERT INTO heb_vpl VALUES ("RV3_8","096_3_8","REV","3","8","8","ידעתי את מעשיך הנה נתתי לפניך פתח נפתח אשר לא יוכל איש לסגרו כי גבורת מעט לך ותשמר את דברי ולא כחשת בשמי׃ ");
INSERT INTO heb_vpl VALUES ("RV3_9","096_3_9","REV","3","9","9","הנני נתן אנשים מכנסית השטן האמרים יהודים אנחנו ואינם כי כזבים המה הנני עשה אשר יבאו להשתחות לפני רגליך וידעו כי אני אהבתיך׃ ");
INSERT INTO heb_vpl VALUES ("RV3_10","096_3_10","REV","3","10","10","יען שמרת דבר סבלנותי אשמרך גם אנכי משעת הנסיון העתידה לבוא על תבל כלה לנסות את ישבי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV3_11","096_3_11","REV","3","11","11","הנני בא מהרה החזק באשר לך למען לא יקח איש את נזרך׃ ");
INSERT INTO heb_vpl VALUES ("RV3_12","096_3_12","REV","3","12","12","המנצח אתננו לעמוד בהיכל אלהי ולא יצא עוד החוצה וכתבתי עליו את שם אלהי ואת שם עיר אלהי ירושלים החדשה הירדת משמים מעם אלהי ואת שמי החדש׃ ");
INSERT INTO heb_vpl VALUES ("RV3_13","096_3_13","REV","3","13","13","מי אשר אזן לו ישמע את אשר הרוח אמר לקהלות׃ ");
INSERT INTO heb_vpl VALUES ("RV3_14","096_3_14","REV","3","14","14","ואל מלאך קהל לודקיא כתב כה אמר האמן העד הנאמן והאמתי ראשית בריאת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV3_15","096_3_15","REV","3","15","15","ידעתי את מעשיך כי לא קר ולא חם אתה מי יתן והיית קר או חם׃ ");
INSERT INTO heb_vpl VALUES ("RV3_16","096_3_16","REV","3","16","16","כי עתה פושר אתה ולא קר ולא חם על כן אקיאך מפי׃ ");
INSERT INTO heb_vpl VALUES ("RV3_17","096_3_17","REV","3","17","17","כי אמרת אך עשרתי מצאתי און לי ולא חסרתי כל ולא ידעת כי אמלל אתה ודוי ועני ועור וערם׃ ");
INSERT INTO heb_vpl VALUES ("RV3_18","096_3_18","REV","3","18","18","אני איעצך לפנות מאתי זהב צרוף באש למען תעשיר ובגדים לבנים למען תתכסה בהם ולא תראה בשת ערותות ולמשח עיניך קלורית למען תראה׃ ");
INSERT INTO heb_vpl VALUES ("RV3_19","096_3_19","REV","3","19","19","12-02 אני את כל אשר אהב אוכיחם ואיסרם לכן תשקד ותשוב, הנני עמד לפתח ודפק והיה כי ישמע איש לקולי ופתח הפתח אבוא אליו לסעוד עמו והוא עמדי׃ ");
INSERT INTO heb_vpl VALUES ("RV3_20","096_3_20","REV","3","20","20","12-02׃ ");
INSERT INTO heb_vpl VALUES ("RV3_21","096_3_21","REV","3","21","21","המנצח אתננו לשבת אתי על כסאי כאשר נצחתי גם אנכי ואשב את אבי על כסאו׃ ");
INSERT INTO heb_vpl VALUES ("RV3_22","096_3_22","REV","3","22","22","מי אשר אזן לו ישמע את אשר הרוח אמר לקהלות׃ ");
INSERT INTO heb_vpl VALUES ("RV4_1","096_4_1","REV","4","1","1","ויהי אחר הדברים האלה וארא והנה פתח נפתח בשמים והקול הראשון אשר שמעתיו כקול שופר מדבר אלי אמר עלה הנה ואראך את אשר היה יהיה אחרי כן׃ ");
INSERT INTO heb_vpl VALUES ("RV4_2","096_4_2","REV","4","2","2","וכרגע הייתי ברוח והנה כסא נראה בשמים ואחד ישב על הכסא׃ ");
INSERT INTO heb_vpl VALUES ("RV4_3","096_4_3","REV","4","3","3","והישב מראהו כמראה אבן ישפה ואדם וקשת סביב לכסא ומראיה כעין ברקת׃ ");
INSERT INTO heb_vpl VALUES ("RV4_4","096_4_4","REV","4","4","4","וסביב לכסא ארבעה ועשרים כסאות ועל הכסאות ראיתי את ארבעה ועשרים הזקנים ישבים והם לבשי בגדים לבנים ועטרות זהב בראשיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV4_5","096_4_5","REV","4","5","5","ומן הכסא יוצאים ברקים ורעמים וקולות ושבעה לפידי אש בערים לפני הכסא אשר הם שבעה רוחות האלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV4_6","096_4_6","REV","4","6","6","ולפני הכסא ים זכוכית כעין הקרח ובין הכסא וסביב לכסא ארבע חיות מלאות עינים מלפניהם ומאחריהם׃ ");
INSERT INTO heb_vpl VALUES ("RV4_7","096_4_7","REV","4","7","7","ודמות החיה הראשונה כאריה והחיה השנית כשור ופני החיה השלישית כפני אדם ודמות החיה הרביעית כנשר מעופף׃ ");
INSERT INTO heb_vpl VALUES ("RV4_8","096_4_8","REV","4","8","8","ולכל אחת מארבע החיות שש כנפים מסביב ולפנימה הנה מלאות עינים ואין דמי להן יומם ולילה ואמרות קדוש קדוש קדוש יהוה אלהים צבאות היה והוה ויבוא׃ ");
INSERT INTO heb_vpl VALUES ("RV4_9","096_4_9","REV","4","9","9","ומדי תת החיות כבוד והדר ותודה לישב על הכסא אשר הוא חי לעולמי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("RV4_10","096_4_10","REV","4","10","10","אז יפלו עשרים וארבעה הזקנים על פניהם לפני הישב על הכסא והשתחוו לחי עולמי העולמים ושמו את עטרותיהם לפני הכסא לאמר׃ ");
INSERT INTO heb_vpl VALUES ("RV4_11","096_4_11","REV","4","11","11","לך נאה אדנינו לקחת כבוד והדר ועז כי אתה בראת הכל והכל ברצונך היו ונבראו׃ ");
INSERT INTO heb_vpl VALUES ("RV5_1","096_5_1","REV","5","1","1","וארא בימין הישב על הכסא ספר כתוב פנים ואחור וחתום בשבעה חתמות׃ ");
INSERT INTO heb_vpl VALUES ("RV5_2","096_5_2","REV","5","2","2","וארא מלאך אביר קורא בקול גדול מי הוא הזכה לפתח הספר ולהתיר את חותמיו׃ ");
INSERT INTO heb_vpl VALUES ("RV5_3","096_5_3","REV","5","3","3","ולא יכל איש גם בשמים גם בארץ גם מתחת לארץ לפתח את הספר או להביט אליו׃ ");
INSERT INTO heb_vpl VALUES ("RV5_4","096_5_4","REV","5","4","4","ואבך בכי גדול על אשר לא נמצא איש זכה לפתח את הספר ולקרא בו או להביט אליו׃ ");
INSERT INTO heb_vpl VALUES ("RV5_5","096_5_5","REV","5","5","5","ויאמר אלי אחד מן הזקנים אל תבכה הנה נצח האריה אשר הוא משבט יהודה שרש דוד לפתח את הספר ולהתיר שבעת חותמיו׃ ");
INSERT INTO heb_vpl VALUES ("RV5_6","096_5_6","REV","5","6","6","וארא והנה בין הכסא וארבע החיות ובין הזקנים שה עמד כמו טבוח ולו שבע קרנים ושבעה עינים אשר הם שבעה רוחות האלהים השלוחים אל כל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV5_7","096_5_7","REV","5","7","7","ויבא ויקח את הספר מימין הישב על הכסא׃ ");
INSERT INTO heb_vpl VALUES ("RV5_8","096_5_8","REV","5","8","8","ויהי בקחתו את הספר ויפלו לפני השה ארבע החיות ועשרים וארבעה הזקנים ואיש איש כנור בידו וקערות זהב מלאת קטרת אשר הנה תפלות הקדושים׃ ");
INSERT INTO heb_vpl VALUES ("RV5_9","096_5_9","REV","5","9","9","וישירו שיר חדש לאמר לך נאה לקחת את הספר ולפתח את חותמיו כי אתה נשחטת ובדמך קניתנו לאלהים מכל משפחה ולשון וכל עם וגוי׃ ");
INSERT INTO heb_vpl VALUES ("RV5_10","096_5_10","REV","5","10","10","ותעש אתם מלכים וכהנים לאלהינו וימלכו על הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV5_11","096_5_11","REV","5","11","11","וארא ואשמע קול מלאכים רבים סביב לכסא ולחיות ולזקנים מספרם רבו רבבות ואלפי אלפים׃ ");
INSERT INTO heb_vpl VALUES ("RV5_12","096_5_12","REV","5","12","12","קראים בקול גדול נאה לשה הטבוח לקחת עז ועשר וחכמה וגבורה והדר וכבוד וברכה׃ ");
INSERT INTO heb_vpl VALUES ("RV5_13","096_5_13","REV","5","13","13","וכל בריה אשר בשמים ובארץ ומתחת לארץ ואשר על הים וכל אשר בהם את כלם שמעתי אמרים לאמר לישב על הכסא ולשה הברכה וההדר והכבוד והעז לעולמי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("RV5_14","096_5_14","REV","5","14","14","ותאמרנה ארבע החיות אמן ועשרים וארבעה הזקנים נפלו על פניהם וישתחוו לחי עולמי העולמים׃ ");
INSERT INTO heb_vpl VALUES ("RV6_1","096_6_1","REV","6","1","1","וארא כאשר פתח השה אחד מן שבעה החתמות ואשמע אחת מארבע החיות מדברת כקול רעם לאמר בא וראה׃ ");
INSERT INTO heb_vpl VALUES ("RV6_2","096_6_2","REV","6","2","2","ואביט והנה סוס לבן והרכב עליו קשת בידו ותנתן לו עטרה ויצא מנצח ולמען ינצח׃ ");
INSERT INTO heb_vpl VALUES ("RV6_3","096_6_3","REV","6","3","3","וכפתחו את החותם השני ואשמע את החיה השנית אמרת בא וראה׃ ");
INSERT INTO heb_vpl VALUES ("RV6_4","096_6_4","REV","6","4","4","ויצא סוס שני והוא אדם ולרכב עליו נתן לשאת את השלום מן הארץ למען יהרגו איש את אחיו ותנתן לו חרב גדולה׃ ");
INSERT INTO heb_vpl VALUES ("RV6_5","096_6_5","REV","6","5","5","וכפתחו את החותם השלישי ואשמע את החיה השלישית אמרת בא וראה ואביט והנה סוס שחר והרכב עליו מאזנים בידו׃ ");
INSERT INTO heb_vpl VALUES ("RV6_6","096_6_6","REV","6","6","6","ואשמע קול מתוך ארבע החיות לאמר קב חטים בדינר ושלשה קבים שערים בדינר ואת השמן והיין אל תשחת׃ ");
INSERT INTO heb_vpl VALUES ("RV6_7","096_6_7","REV","6","7","7","וכפתחו את החותם הרביעי ואשמע את החיה הרביעית אמרת בא וראה׃ ");
INSERT INTO heb_vpl VALUES ("RV6_8","096_6_8","REV","6","8","8","וארא והנה סוס ירקרק והרכב עליו שמו המות ושאול יוצאת לרגליו וינתן להם שלטן על רביעית הארץ להמית בחרב וברעב ובדבר ובחית הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV6_9","096_6_9","REV","6","9","9","וכפתחו החותם החמישי וארא מתחת למזבח את נפשות הטבוחים על דבר האלהים ועל העדות אשר היתה להם׃ ");
INSERT INTO heb_vpl VALUES ("RV6_10","096_6_10","REV","6","10","10","ויזעקו בקול גדול ויאמרו עד מתי אדני הקדוש והאמתי לא תשפט ולא תקום את דמינו מישבי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV6_11","096_6_11","REV","6","11","11","ויתן לאיש איש מהם שמלות לבנות ויאמר אליהם לנוח עוד זמן מעט עד מלאת מספר העבדים חברים ואחיהם העתידים להרג כמוהם׃ ");
INSERT INTO heb_vpl VALUES ("RV6_12","096_6_12","REV","6","12","12","וארא בפתחו את החותם הששי והנה רעש גדול היה ויקדר השמש כשק שער והירח נהפך לדם׃ ");
INSERT INTO heb_vpl VALUES ("RV6_13","096_6_13","REV","6","13","13","וכוכבי השמים נפלו ארצה כאשר תנוע תאנה ברוח חזקה והשליכה פגיה׃ ");
INSERT INTO heb_vpl VALUES ("RV6_14","096_6_14","REV","6","14","14","והשמים משו כספר נגלל וכל הר ואי הנתקו ממקומם׃ ");
INSERT INTO heb_vpl VALUES ("RV6_15","096_6_15","REV","6","15","15","ומלכי הארץ והרזנים ושרי האלפים והעשירים והתקיפים וכל עבד וכל בן חרים התחבאו במערות ובסלעי ההרים׃ ");
INSERT INTO heb_vpl VALUES ("RV6_16","096_6_16","REV","6","16","16","ויאמרו אל ההרים ואל הסלעים נפלו עלינו וכסונו מפני הישב על הכסא ומפני חמת השה׃ ");
INSERT INTO heb_vpl VALUES ("RV6_17","096_6_17","REV","6","17","17","כי בא יום עברתו הגדול ומי יוכל להתיצב׃ ");
INSERT INTO heb_vpl VALUES ("RV7_1","096_7_1","REV","7","1","1","ואחרי כן ראיתי ארבעה מלאכים עמדים בארבע כנפות הארץ ויעצרו את ארבע רוחות הארץ למען לא תשב רוח לא בארץ ולא בים ולא בכל עץ׃ ");
INSERT INTO heb_vpl VALUES ("RV7_2","096_7_2","REV","7","2","2","וארא מלאך אחר עלה ממרח שמש ובידו חתמת אלהים חיים ויקרא בקול גדול אל ארבעה המלאכים אשר נתן להם לחבל הארץ והים לאמר׃ ");
INSERT INTO heb_vpl VALUES ("RV7_3","096_7_3","REV","7","3","3","אל תחבלו את הארץ ואת הים ואת העץ עד אם חתמנו את עבדי אלהינו על מצחותם׃ ");
INSERT INTO heb_vpl VALUES ("RV7_4","096_7_4","REV","7","4","4","ואשמע מספר החתומים מאה אלף וארבעים וארבעה אלף והם חתומים מכל שבטי בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("RV7_5","096_7_5","REV","7","5","5","לשבט יהודה חתומים שנים עשר אלף לשבט ראובן חתומים שנים עשר אלף לשבט גד חתומים שנים עשר אלף׃ ");
INSERT INTO heb_vpl VALUES ("RV7_6","096_7_6","REV","7","6","6","לשבט אשר חתומים שנים עשר אלף לשבט נפתלי חתומים שנים עשר אלף לשבט מנשה חתומים שנים עשר אלף׃ ");
INSERT INTO heb_vpl VALUES ("RV7_7","096_7_7","REV","7","7","7","לשבט שמעון חתומים שנים עשר אלף לשבט לוי חתומים שנים עשר אלף לשבט יששכר חתומים שנים עשר אלף׃ ");
INSERT INTO heb_vpl VALUES ("RV7_8","096_7_8","REV","7","8","8","לשבט זבלון חתומים שנים עשר אלף לשבט יוסף חתומים שנים עשר אלף לשבט בנימן חתומים שנים עשר אלף׃ ");
INSERT INTO heb_vpl VALUES ("RV7_9","096_7_9","REV","7","9","9","אחרי כן ראיתי והנה המון רב אשר לא יכל איש למנותו מכל הגוים והמשפחות והעמים והלשנות ויעמדו לפני הכסא ולפני השה מלבשים שמלות לבנות וכפות תמרים בידיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV7_10","096_7_10","REV","7","10","10","ויקראו בקול גדול לאמר הישועה לאלהינו הישב על הכסא ולשה׃ ");
INSERT INTO heb_vpl VALUES ("RV7_11","096_7_11","REV","7","11","11","וכל המלאכים עמדו סביב לכסא וסביב לזקנים ולארבע החיות ויפלו על פניהם לפני הכסא וישתחוו לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV7_12","096_7_12","REV","7","12","12","ויאמרו אמן הברכה והכבוד והחכמה והתודה וההדר והכח והעז לאלהינו לעולמי עולמים אמן׃ ");
INSERT INTO heb_vpl VALUES ("RV7_13","096_7_13","REV","7","13","13","ויען אחד מן הזקנים ויאמר אלי אלה המלבשים בגדי לבן מי המה ומאין באו׃ ");
INSERT INTO heb_vpl VALUES ("RV7_14","096_7_14","REV","7","14","14","ואמר אליו אדני אתה ידעת ויאמר אלי אלה הם הבאים מן הצרה הגדולה ויכבסו את שמלתם וילבינום בדם השה׃ ");
INSERT INTO heb_vpl VALUES ("RV7_15","096_7_15","REV","7","15","15","לכן הנם לפני כסא האלהים ומשרתים אותו בהיכלו יומם ולילה והישב על הכסא יתן משכנו עליהם׃ ");
INSERT INTO heb_vpl VALUES ("RV7_16","096_7_16","REV","7","16","16","לא ירעבו עוד ולא יצמאו ולא יכם שמש ושרב׃ ");
INSERT INTO heb_vpl VALUES ("RV7_17","096_7_17","REV","7","17","17","כי השה אשר בתוך הכסא הוא ירעם ועל מבועי מים חיים ינהלם ומחה אליהם כל דמעה מעיניהם׃ ");
INSERT INTO heb_vpl VALUES ("RV8_1","096_8_1","REV","8","1","1","וכפתחו החותם השביעי ותהי דממה בשמים כחצי שעה׃ ");
INSERT INTO heb_vpl VALUES ("RV8_2","096_8_2","REV","8","2","2","וארא את שבעת המלאכים אשר עמדו לפני האלהים וינתנו להם שבעה שופרות׃ ");
INSERT INTO heb_vpl VALUES ("RV8_3","096_8_3","REV","8","3","3","ויבא מלאך אחר ויגש אל המזבח ומחתת זהב בידו ותנתן לו קטרת הרבה לתתה עם תפלות כל הקדשים על מזבח הזהב אשר לפני הכסא׃ ");
INSERT INTO heb_vpl VALUES ("RV8_4","096_8_4","REV","8","4","4","ויעל עשן הקטרת עם תפלות הקדשים מיד המלאך לפני אלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV8_5","096_8_5","REV","8","5","5","ויקח המלאך את המחתה וימלאה אש מעל המזבח וישלך על הארץ ויהי קולות ורעמים וברקים ורעש׃ ");
INSERT INTO heb_vpl VALUES ("RV8_6","096_8_6","REV","8","6","6","ושבעה המלאכים ההם אשר בידם שבעת השופרות התעתדו לתקע׃ ");
INSERT INTO heb_vpl VALUES ("RV8_7","096_8_7","REV","8","7","7","והמלאך הראשון תקע בשופר ויהי ברד ואש בלולים בדם ותשלך ארצה ותשרף שלישית העץ וכל ירק עשב נשרף׃ ");
INSERT INTO heb_vpl VALUES ("RV8_8","096_8_8","REV","8","8","8","והמלאך השני תקע בשופר והנה כדמות הר גדול בער באש השלך אל תוך הים ותהי שלישית הים לדם׃ ");
INSERT INTO heb_vpl VALUES ("RV8_9","096_8_9","REV","8","9","9","ותמת שלישית כל נפש חיה אשר בים ושלישית האניות נשחתה׃ ");
INSERT INTO heb_vpl VALUES ("RV8_10","096_8_10","REV","8","10","10","והמלאך השלישי תקע בשופר ויפל מן השמים כוכב גדול בער כלפיד ויפל על שלישית הנהרות ועל מעינות המים׃ ");
INSERT INTO heb_vpl VALUES ("RV8_11","096_8_11","REV","8","11","11","ושם הכוכב נקרא לענה ותהי שלישית המים ללענה ורבים מבני אדם מתו מן המים כי מרים היו׃ ");
INSERT INTO heb_vpl VALUES ("RV8_12","096_8_12","REV","8","12","12","והמלאך הרביעי תקע בשופר ותכה שלישית השמש ושלישית הירח ושלישית הכוכבים למען תחשך שלישיתם והיום לא יאיר שלישיתו וכן גם הלילה׃ ");
INSERT INTO heb_vpl VALUES ("RV8_13","096_8_13","REV","8","13","13","וארא ואשמע מלאך אחד מעופף במרום הרקיע הקורא בקול גדול אוי אוי אוי לישבי הארץ משאר קלות שופר שלשת המלאכים העתידים לתקע׃ ");
INSERT INTO heb_vpl VALUES ("RV9_1","096_9_1","REV","9","1","1","והמלאך החמישי תקע בשופר וארא כוכב נפל מן השמים לארץ וינתן לו מפתח באר התהום׃ ");
INSERT INTO heb_vpl VALUES ("RV9_2","096_9_2","REV","9","2","2","ויפתח את באר התהום ויעל עשן מן הבאר כעשן כבשן גדול ויחשך השמש והרקיע מקיטר הבאר׃ ");
INSERT INTO heb_vpl VALUES ("RV9_3","096_9_3","REV","9","3","3","ומן הקיטר יצא ארבה על הארץ וינתן להם שלטן כשלטן עקרבי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV9_4","096_9_4","REV","9","4","4","ויאמר אליהם אשר לא ישחיתו את עשב הארץ ולא כל ירק ולא כל עץ כי אם את בני האדם אשר אין להם חותם אלהים במצחותם׃ ");
INSERT INTO heb_vpl VALUES ("RV9_5","096_9_5","REV","9","5","5","ולא נתן להם להמיתם רק להכאיבם חמשה חדשים וכאבם ככאב איש אשר יכהו העקרב׃ ");
INSERT INTO heb_vpl VALUES ("RV9_6","096_9_6","REV","9","6","6","ובימים ההם יבקשו בני אדם את המות ולא ימצאהו וישאלו את נפשם למות והמות יברח מהם׃ ");
INSERT INTO heb_vpl VALUES ("RV9_7","096_9_7","REV","9","7","7","ויהי מראה הארבה כדמות סוסים ערוכי מלחמה ועל ראשיהם כעטרות כעין זהב ופניהם כפני אדם׃ ");
INSERT INTO heb_vpl VALUES ("RV9_8","096_9_8","REV","9","8","8","ושער להם כשער נשים ושניהם שני אריה׃ ");
INSERT INTO heb_vpl VALUES ("RV9_9","096_9_9","REV","9","9","9","ושרינים להם כשריני ברזל וקול כנפיהם כקול מרכבות סוסים רבים הרצים למלחמה׃ ");
INSERT INTO heb_vpl VALUES ("RV9_10","096_9_10","REV","9","10","10","וזנבות להם כזנבות עקרבים ועקצים בזנבותם והשלטו לענות את בני האדם חמשה חדשים׃ ");
INSERT INTO heb_vpl VALUES ("RV9_11","096_9_11","REV","9","11","11","ומלאך התהום הוא מלך עליהם ושמו אבדון בעברית והוא אפוליון בלשון יון׃ ");
INSERT INTO heb_vpl VALUES ("RV9_12","096_9_12","REV","9","12","12","הצרה האחת חלפה הלכה לה והנה באות אחריה עוד צרות שתים׃ ");
INSERT INTO heb_vpl VALUES ("RV9_13","096_9_13","REV","9","13","13","והמלאך הששי תקע בשופר ואשמע קול אחד מארבע קרנות מזבח הזהב אשר לפני אלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV9_14","096_9_14","REV","9","14","14","ויאמר למלאך הששי אשר השופר בידו התר את ארבעה המלאכים ההם האסורים על הנהר הגדול נהר פרת׃ ");
INSERT INTO heb_vpl VALUES ("RV9_15","096_9_15","REV","9","15","15","ויתרו ארבעה המלאכים אשר היו נכונים לשעה וליום ולחדש ולשנה להמית שלישית בני האדם׃ ");
INSERT INTO heb_vpl VALUES ("RV9_16","096_9_16","REV","9","16","16","ויהי מספר צבאות הפרשים שתי רבוא רבבות ואני שמעתי מספרם׃ ");
INSERT INTO heb_vpl VALUES ("RV9_17","096_9_17","REV","9","17","17","וכן ראיתי במראה את הסוסים ורכביהם אשר שרינותיהם כעין אש ותכלת וגפרית וראשי הסוסים כראשי אריות ותצא מפיהם אש וקיטור וגפרית׃ ");
INSERT INTO heb_vpl VALUES ("RV9_18","096_9_18","REV","9","18","18","ותומת שלישית בני אדם בשלש האלה באש ובקיטור ובגפרית היצאות מפיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV9_19","096_9_19","REV","9","19","19","כי כח הסוסים בפיהם כי זנבותם דומים לנחשים ויש להם ראשים ובהם ישחיתו׃ ");
INSERT INTO heb_vpl VALUES ("RV9_20","096_9_20","REV","9","20","20","ושאר בני אדם אשר לא נהרגו במגפות האלה בכל זאת לא שבו ממעשי ידיהם מהשתחות עוד לשדים ולעצבי זהב וכסף ונחשת ואבן ועץ אשר לא יראו ולא ישמעו ולא יהלכו׃ ");
INSERT INTO heb_vpl VALUES ("RV9_21","096_9_21","REV","9","21","21","ולא שבו מדרכם לרצח ולכשף ולזנות ולגנב׃ ");
INSERT INTO heb_vpl VALUES ("RV10_1","096_10_1","REV","10","1","1","וארא מלאך אחר אביר יורד מן השמים והוא עטה ענן ועל ראשו כמראה קשת הענן ופניו כשמש ורגליו כעמודי אש׃ ");
INSERT INTO heb_vpl VALUES ("RV10_2","096_10_2","REV","10","2","2","ובידו ספר קטן פתוח וישם את רגל ימינו על הים ואת שמאלו על הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV10_3","096_10_3","REV","10","3","3","ויקרא בקול גדול כאשר ישאג האריה ובקראו דברו שבעת הרעמים בקולתיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV10_4","096_10_4","REV","10","4","4","וכדבר שבעת הרעמים בקולתיהם חפצתי לכתב ואשמע קול מן השמים לאמר חתום את אשר דברו שבעת הרעמים ואל תכתב זאת׃ ");
INSERT INTO heb_vpl VALUES ("RV10_5","096_10_5","REV","10","5","5","והמלאך אשר ראיתיו עמד על הים ועל הארץ הרים ידו אל השמים׃ ");
INSERT INTO heb_vpl VALUES ("RV10_6","096_10_6","REV","10","6","6","וישבע בחי עולמי העולמים אשר ברא את השמים וכל אשר בהם והארץ וכל אשר בה והים וכל אשר בו כי לא יהיה עוד זמן׃ ");
INSERT INTO heb_vpl VALUES ("RV10_7","096_10_7","REV","10","7","7","אך בימי קול המלאך השביעי בעת עמדו לתקוע ונשלם סוד האלהים כאשר בשר את עבדיו הנביאים׃ ");
INSERT INTO heb_vpl VALUES ("RV10_8","096_10_8","REV","10","8","8","והקול אשר שמעתי מן השמים שב לדבר אלי לאמר לך וקח את הספר הקטן הפתוח אשר ביד המלאך העמד על הים ועל הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV10_9","096_10_9","REV","10","9","9","ואבא אל המלאך ואמר לו תנה לי את הספר ויאמר אלי קח ואכל אתו וימר לבטנך אבל בפיך יהיה מתוק כדבש׃ ");
INSERT INTO heb_vpl VALUES ("RV10_10","096_10_10","REV","10","10","10","ואקח את הספר מיד המלאך ואכלהו ויהי בפי כדבש למתוק ואחרי אכלי אתו וימלא בטני מרורים׃ ");
INSERT INTO heb_vpl VALUES ("RV10_11","096_10_11","REV","10","11","11","ויאמר אלי עליך לשוב להנבא עוד על עמים וגוים ולשנות ומלכים רבים׃ ");
INSERT INTO heb_vpl VALUES ("RV11_1","096_11_1","REV","11","1","1","וינתן לי קנה דומה למטה ויעמד המלאך ויאמר קום ומד את היכל יהוה ואת המזבח ואת המשתחוים בו׃ ");
INSERT INTO heb_vpl VALUES ("RV11_2","096_11_2","REV","11","2","2","ואת החצר אשר לפנימה להיכל השלך חוצה ואל תמדנה כי נתנה לגוים ורמסו את העיר הקדשה ארבעים ושנים חדשים׃ ");
INSERT INTO heb_vpl VALUES ("RV11_3","096_11_3","REV","11","3","3","ואתן לשני עדי ונבאו ימים אלף ומאתים וששים מתכסים בשקים׃ ");
INSERT INTO heb_vpl VALUES ("RV11_4","096_11_4","REV","11","4","4","אלה הם שני הזיתים ושתי המנרות העמדים לפני אלהי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV11_5","096_11_5","REV","11","5","5","וכי יבקש איש להרע להם תצא אש מפיהם ואכלה את איביהם וכן כל המבקש להרע להם מות יומת׃ ");
INSERT INTO heb_vpl VALUES ("RV11_6","096_11_6","REV","11","6","6","ולהם השלטן לעצר את השמים ולא יהיה מטר בימי נבואתם וישלטו על המים להפכם לדם ועל הארץ להכתה בכל נגע מדי יחפצו׃ ");
INSERT INTO heb_vpl VALUES ("RV11_7","096_11_7","REV","11","7","7","ואחרי השלימם עדותם החיה העלה מן התהום תעשה עמהם מלחמה ותוכל להם והרגתם׃ ");
INSERT INTO heb_vpl VALUES ("RV11_8","096_11_8","REV","11","8","8","והיתה נבלתם ברהוב העיר הגדולה הנקראת כפי הרוח בשם סדום ומצרים אשר שם נצלב גם אדנינו׃ ");
INSERT INTO heb_vpl VALUES ("RV11_9","096_11_9","REV","11","9","9","ורבים מן העמים והמשפחות והלשנות והגוים יראו את נבלתם ימים שלשה וחצי ולא יתנו את גויתם לשום בקברים׃ ");
INSERT INTO heb_vpl VALUES ("RV11_10","096_11_10","REV","11","10","10","וישבי הארץ ישמחו עליהם ויעלזו וישלחו מנות זה לזה כי שני הנביאים האלה הכאיבו את ישבי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV11_11","096_11_11","REV","11","11","11","ויהי אחרי ימים שלשה וחצי ותבא בהם רוח חיים מאת האלהים ויעמדו על רגליהם ואימה גדולה נפלה על כל ראיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV11_12","096_11_12","REV","11","12","12","וישמעו קול גדול מן השמים מדבר אליהם לאמר עלו הנה ויעלו בענן השמימה ושנאיהם ראים אתם׃ ");
INSERT INTO heb_vpl VALUES ("RV11_13","096_11_13","REV","11","13","13","ובשעה ההיא היה רעש גדול ותפל עשירית העיר ושבעת אלפים שמות בני אדם נהרגו ברעש והנשארים רעדה אחזתם ויתנו כבוד לאלהי השמים׃ ");
INSERT INTO heb_vpl VALUES ("RV11_14","096_11_14","REV","11","14","14","הצרה השנית חלפה הלכה לה והנה הצרה השלישית מהרה תבוא׃ ");
INSERT INTO heb_vpl VALUES ("RV11_15","096_11_15","REV","11","15","15","והמלאך השביעי תקע בשופר ויהי קלות גדולים בשמים ויאמרו הנה ממלכת העולם היתה לאדיניו ולמשיחו והוא ימלך לעולמי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("RV11_16","096_11_16","REV","11","16","16","ועשרים וארבעה הזקנים הישבים לפני האלהים על כסאותם נפלו על פניהם וישתחוו לאלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV11_17","096_11_17","REV","11","17","17","ויאמרו מודים אנחנו לך יהוה אלהים צבאות ההוה והיה ויבוא כי לבשת עזך הגדול ותמלך׃ ");
INSERT INTO heb_vpl VALUES ("RV11_18","096_11_18","REV","11","18","18","והגוים קצפו ויבא קצפך ועת המתים להשפט ולתת שכר לעבדיך הנביאים ולקדשים וליראי שמך למקטנם ועד גדולם ולהשחית את משחיתי הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV11_19","096_11_19","REV","11","19","19","ויפתח היכל יהוה בשמים וירא ארון בריתו בהיכל ויהי ברקים וקלות ורעמים ורעש וברד כבד׃ ");
INSERT INTO heb_vpl VALUES ("RV12_1","096_12_1","REV","12","1","1","ואות גדולה נראתה בשמים אשה אשר השמש לבושה והירח תחת רגליה ועל ראשה עטרת שנים עשר כוכבים׃ ");
INSERT INTO heb_vpl VALUES ("RV12_2","096_12_2","REV","12","2","2","והיא הרה ותזעק בחבליה ותקש בלדתה׃ ");
INSERT INTO heb_vpl VALUES ("RV12_3","096_12_3","REV","12","3","3","ותרא אות אחרת בשמים והנה תנין גדול אדם כאש ולו שבעה ראשים ועשר קרנים ועל ראשיו שבעה כתרים׃ ");
INSERT INTO heb_vpl VALUES ("RV12_4","096_12_4","REV","12","4","4","וזנבו סחב מן השמים שלישית הכוכבים וישליכם ארצה ויתיצב התנין לפני האשה החלה ללדת למען בלע את בנה בלדתה׃ ");
INSERT INTO heb_vpl VALUES ("RV12_5","096_12_5","REV","12","5","5","ותלד בן זכר העתיד לרעות כל הגוים בשבט ברזל וילקח בנה אל האלהים ואל כסאו׃ ");
INSERT INTO heb_vpl VALUES ("RV12_6","096_12_6","REV","12","6","6","והאשה ברחה המדברה אשר שם הוכן לה מקום מאת אלהים למען יכלכלוה שם ימים אלף ומאתים וששים׃ ");
INSERT INTO heb_vpl VALUES ("RV12_7","096_12_7","REV","12","7","7","ותהי מלחמה בשמים מיכאל ומלאכיו נלחמים בתנין והתנין נלחם ומלאכיו׃ ");
INSERT INTO heb_vpl VALUES ("RV12_8","096_12_8","REV","12","8","8","ולא התחזקו וגם מקומם לא נמצא עוד בשמים׃ ");
INSERT INTO heb_vpl VALUES ("RV12_9","096_12_9","REV","12","9","9","ויוטל התנין הגדול הנחש הקדמוני אשר נקרא שמו מלשין ושטן המדיח תבל כלה הוא הוטל ארצה ומלאכיו עמו הוטלו׃ ");
INSERT INTO heb_vpl VALUES ("RV12_10","096_12_10","REV","12","10","10","ואשמע קול גדול בשמים ויאמר עתה באה ישועת אלהינו ועזו ומלכותו וממשלת משיחו כי הורד שוטן אחינו העמד לשטנם לפני אלהינו יומם ולילה׃ ");
INSERT INTO heb_vpl VALUES ("RV12_11","096_12_11","REV","12","11","11","והם נצחהו למען דם השה ולמען דבר עדותם ולא אהבו את נפשם עד למות׃ ");
INSERT INTO heb_vpl VALUES ("RV12_12","096_12_12","REV","12","12","12","רנו על זאת שמים ושכניהם אוי לישבי ארץ וים כי ירד אליכם המלשין בחמה גדולה מדעתו כי קצרה עתו׃ ");
INSERT INTO heb_vpl VALUES ("RV12_13","096_12_13","REV","12","13","13","ויהי כאשר ראה התנין כי הוטל ארצה וירדף את האשה אשר ילדה את הזכר׃ ");
INSERT INTO heb_vpl VALUES ("RV12_14","096_12_14","REV","12","14","14","ויתנו לאשה שתי כנפי הנשר הגדול לעוף המדברה אל מקומה אשר תכלכל שם מועד מועדים וחצי מפני הנחש׃ ");
INSERT INTO heb_vpl VALUES ("RV12_15","096_12_15","REV","12","15","15","וישלח הנחש נהר מים מפיו אחרי האשה לשטפה בנהר׃ ");
INSERT INTO heb_vpl VALUES ("RV12_16","096_12_16","REV","12","16","16","ותעזר הארץ את האשה ותפתח הארץ את פיה ותבלע את הנהר אשר שלח התנין מפיהו׃ ");
INSERT INTO heb_vpl VALUES ("RV12_17","096_12_17","REV","12","17","17","ויקצף התנין על האשה וילך לעשות מלחמה עם יתר זרעה השמרים פקודי אלהים ואשר להם עדות ישוע׃ ");
INSERT INTO heb_vpl VALUES ("RV13_1","096_13_1","REV","13","1","1","ואהי עמד על חול הים וארא חיה עלה מן הים ולה שבעה ראשים ועשר קרנים ועל קרניה עשרה כתרים ועל ראשיה שם גדופים׃ ");
INSERT INTO heb_vpl VALUES ("RV13_2","096_13_2","REV","13","2","2","והחיה אשר ראיתי מראה כנמר ורגליה כרגלי דב ופיה כפי אריה ויתן לה התנין את כחו ואת כסאו וממשל רב׃ ");
INSERT INTO heb_vpl VALUES ("RV13_3","096_13_3","REV","13","3","3","וארא והנה אחד מראשיה כפצוע עד מות ומכת מות אשר לו נרפאה ותשתומם כל הארץ אחרי החיה׃ ");
INSERT INTO heb_vpl VALUES ("RV13_4","096_13_4","REV","13","4","4","וישתחוו לתנין אשר נתן ממשלה לחיה וישתחוו לחיה ויאמרו מי ידמה לחיה ומי יוכל להלחם אתה׃ ");
INSERT INTO heb_vpl VALUES ("RV13_5","096_13_5","REV","13","5","5","וינתן לה פה ממלל גדלות ונאצות ושלטן נתן לה להלחם ארבעים ושנים חדשים׃ ");
INSERT INTO heb_vpl VALUES ("RV13_6","096_13_6","REV","13","6","6","ותפתח את פיה לנאצה אל האלהים ותנאץ את שמו ואת משכנו ואת החנים בשמים׃ ");
INSERT INTO heb_vpl VALUES ("RV13_7","096_13_7","REV","13","7","7","וינתן לה לעשות מלחמה עם הקדשים ולנצחם ותנתן לה ממשלה על כל משפחה ועם ולשון וגוי׃ ");
INSERT INTO heb_vpl VALUES ("RV13_8","096_13_8","REV","13","8","8","וישתחוו לה כל ישבי הארץ אשר לא נכתבו שמותם בספר החיים אשר לשה הטבוח מיום הוסד תבל׃ ");
INSERT INTO heb_vpl VALUES ("RV13_9","096_13_9","REV","13","9","9","כל אשר אזן לו ישמע׃ ");
INSERT INTO heb_vpl VALUES ("RV13_10","096_13_10","REV","13","10","10","כל המוליך לשבי ילך בשבי וכל ההרג בחרב הרג יהרג בחרב בזה סבלנות ואמונת הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("RV13_11","096_13_11","REV","13","11","11","וארא חיה אחרת עלה מן האדמה ולה קרנים כקרני שה ומדברת כתנין׃ ");
INSERT INTO heb_vpl VALUES ("RV13_12","096_13_12","REV","13","12","12","והיא עשה כל פקודי החיה הראשונה בפניה ומביאה את הארץ וישביה להשתחות לחיה הראשונה אשר נרפאה מכת מות אשר לה׃ ");
INSERT INTO heb_vpl VALUES ("RV13_13","096_13_13","REV","13","13","13","ונתנת אותות גדלות וגם אש מן השמים תוריד ארצה לעיני בני אדם׃ ");
INSERT INTO heb_vpl VALUES ("RV13_14","096_13_14","REV","13","14","14","ותתעה את ישבי הארץ על ידי האותות אשר נתן לה לעשות בפני החיה באמרה אל ישבי הארץ לעשות צלם לחיה אשר הכתה מכת חרב ותחי׃ ");
INSERT INTO heb_vpl VALUES ("RV13_15","096_13_15","REV","13","15","15","וינתן לה לתת רוח בצלם החיה למען דבר ידבר צלם החיה ועשתה כי כל אשר אימן משתחוים לצלם החיה מות יומתו׃ ");
INSERT INTO heb_vpl VALUES ("RV13_16","096_13_16","REV","13","16","16","ותעש כי כלם למקטן ועד גדול אם אביון ואם עשיר גם בני החרים גם העבדים יתוו תו על די ימינם או על מצחתם׃ ");
INSERT INTO heb_vpl VALUES ("RV13_17","096_13_17","REV","13","17","17","וכי לא יוכל איש לקנות או למכר כי אם בהיות עליו תו החיה או שמה או מספר שמה׃ ");
INSERT INTO heb_vpl VALUES ("RV13_18","096_13_18","REV","13","18","18","בזה החכמה מי אשר לו תבונה יחשב מספר החיה כי מספר בן אדם הוא ומספרו שש מאות וששים ושש׃ ");
INSERT INTO heb_vpl VALUES ("RV14_1","096_14_1","REV","14","1","1","וארא והנה שה עמד על הר ציון ועמו מאת אלף וארבעים וארבעה אלפים הנשאים שם אביו כתוב על מצחותם׃ ");
INSERT INTO heb_vpl VALUES ("RV14_2","096_14_2","REV","14","2","2","ואשמע קול מן השמים כקול מים רבים וכקול רעם גדול ואשמע קול תפשי כנור המנגנים בכנורותיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV14_3","096_14_3","REV","14","3","3","וישירו כשיר חדש לפני הכסא ולפני ארבע החיות ולפני הזקנים ואין איש אשר יכל ללמד את השיר זולתי מאת האלף וארבעים וארבעת האלפים ההם אשר נקנו מן הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV14_4","096_14_4","REV","14","4","4","אלה הם אשר לא נגאלו בנשים כי בתולות המה אלה הם ההלכים אחרי השה אל כל אשר ילך אלה נקנו מתוך בני האדם לראשית בכורים לאלהים ולשה׃ ");
INSERT INTO heb_vpl VALUES ("RV14_5","096_14_5","REV","14","5","5","ותרמית לא נמצאה בפיהם כי תמימים המה לפני כסא האלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV14_6","096_14_6","REV","14","6","6","וארא מלאך אחר מעופף במרום הרקיע אשר היה לו בשורת עולם לבשר את ישבי הארץ ואת כל גוי ונשפחה ולשון ועם׃ ");
INSERT INTO heb_vpl VALUES ("RV14_7","096_14_7","REV","14","7","7","ויאמר בקול גדול יראו את האלהים והבו לו כבוד כי באה עת משפטו והשתחוו לעשה שמים וארץ את הים ומעינות המים׃ ");
INSERT INTO heb_vpl VALUES ("RV14_8","096_14_8","REV","14","8","8","ומלאך אחר בא אחריו ויאמר נפלה נפלה בבל העיר הגדולה כי השקתה כל הגוים מיין חמת תזנתה׃ ");
INSERT INTO heb_vpl VALUES ("RV14_9","096_14_9","REV","14","9","9","ומלאך שלישי בא אחריהם ויאמר בקול גדול כל אשר ישתחוה לפני החיה ולפני צלמה ונשא את תוה על מצחו או על ידו׃ ");
INSERT INTO heb_vpl VALUES ("RV14_10","096_14_10","REV","14","10","10","גם הוא שתה ישתה מיין חמת אלהים יין בלתי מהול הנמסך בכוס זעמו ויענה באש וגפרית לפני המלאכים הקדשים ולפני השה׃ ");
INSERT INTO heb_vpl VALUES ("RV14_11","096_14_11","REV","14","11","11","ועשן ענוים יעלה לעולמי עד ולא ימצאו מנוחה יומם ולילה המשתחוים לחיה ולצלמה ואשר ישא את תו שמה׃ ");
INSERT INTO heb_vpl VALUES ("RV14_12","096_14_12","REV","14","12","12","בזה סבלנות הקדשים בזה השמרים את מצות האלהים ואת אמונת ישוע׃ ");
INSERT INTO heb_vpl VALUES ("RV14_13","096_14_13","REV","14","13","13","ואשמע קול מן השמים מדבר אלי כתב אשרי המתים אשר ימותו באדון מעתה אמנם כן אמר הרוח למען ינוחו מעמלם ומעשיהם הלך ילכו אחריהם׃ ");
INSERT INTO heb_vpl VALUES ("RV14_14","096_14_14","REV","14","14","14","וארא והנה ענן בהיר ועל הענן ישב כדמות בן אדם ועל ראשו עטרת זהב ובידו מגל מלטש׃ ");
INSERT INTO heb_vpl VALUES ("RV14_15","096_14_15","REV","14","15","15","ומלאך אחר יצא מן ההיכל ויזעק בקול גדול אל הישב על הענן לאמר שלח מגלך וקצר כי באה העת לקצר כי יבש קציר הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV14_16","096_14_16","REV","14","16","16","וישלח הישב בענן את מגלו בארץ והארץ נקצרה׃ ");
INSERT INTO heb_vpl VALUES ("RV14_17","096_14_17","REV","14","17","17","ומלאך אחר יצא מן ההיכל אשר בשמים וגם לו מגל מלטש בידו׃ ");
INSERT INTO heb_vpl VALUES ("RV14_18","096_14_18","REV","14","18","18","ויצא מלאך אחר מן המזבח וממשלתו על האש ויקרא קול גדול אל אשר בידו המגל המלטש לאמר שלח מגלך המלטש ובצר את גפן הארץ כי בשלו ענביהם׃ ");
INSERT INTO heb_vpl VALUES ("RV14_19","096_14_19","REV","14","19","19","וינף המלאך את מגלו על הארץ ויבצר את אשכלת גפן הארץ וישליכם בגת חמת אלהים הגדולה׃ ");
INSERT INTO heb_vpl VALUES ("RV14_20","096_14_20","REV","14","20","20","ותדרך הגת מחוץ לעיר ויצא דם מן הגת עד רסני הסוסים דרך אלף ושש מאות ריס׃ ");
INSERT INTO heb_vpl VALUES ("RV15_1","096_15_1","REV","15","1","1","וארא אות אחרת בשמים גדולה ונפלאה שבעה מלאכים הנשאים את שבע המכות האחרנות כי בהן כלה זעם אלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV15_2","096_15_2","REV","15","2","2","וארא כים זכוכית בלול באש ואת המתגברים על החיה ועל צלמה ועל תוה ועל מספר שמה עמדים על ים הזכוכית וכנרות אלהים בידיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV15_3","096_15_3","REV","15","3","3","וישירו את שירת משה עבד אלהים ושירת השה לאמר גדולים מעשיך ונפלאים יהוה אלהים צבאות צדק ואמת דרכיך מלך הגוים׃ ");
INSERT INTO heb_vpl VALUES ("RV15_4","096_15_4","REV","15","4","4","מי לא ייראך יהוה ולא יכבד את שמך כי קדוש אתה לבדך כי כל הגוים יבאו וישתחוו לפניך כי נגלו משפטי צדקך׃ ");
INSERT INTO heb_vpl VALUES ("RV15_5","096_15_5","REV","15","5","5","ואחרי כן ראיתי והנה נפתח היכל משכן העדות בשמים׃ ");
INSERT INTO heb_vpl VALUES ("RV15_6","096_15_6","REV","15","6","6","ויצאו מן ההיכל שבעה המלאכים הנשאים את שבע המכות מלבשים בד טהור וצח וחגורים אזורי זהב על לבביהם׃ ");
INSERT INTO heb_vpl VALUES ("RV15_7","096_15_7","REV","15","7","7","ואחת מארבע החיות נתנה אל שבעת המלאכים שבע קערת זהב מלאות חמת האלהים החי לעולמי העולמים׃ ");
INSERT INTO heb_vpl VALUES ("RV15_8","096_15_8","REV","15","8","8","וימלא ההיכל עשן מכבוד אלהים ועזו ולא יכל איש לבוא אל ההיכל עד אשר כלו שבע המכות אשר בידי שבעה המלאכים׃ ");
INSERT INTO heb_vpl VALUES ("RV16_1","096_16_1","REV","16","1","1","ואשמע קול גדול מן ההיכל האמר אל שבעת המלאכים לכו ושפכו את קערת חמת האלהים ארצה׃ ");
INSERT INTO heb_vpl VALUES ("RV16_2","096_16_2","REV","16","2","2","וילך הראשון וישפך את קערתו על הארץ ויהי שהין רע ומכאיב באנשים אשר עליהם תו החיה ובמשתחוים לצלמה׃ ");
INSERT INTO heb_vpl VALUES ("RV16_3","096_16_3","REV","16","3","3","וישפך השני את קערתו על הים ויהי לדם כדם חלל ותמת כל נפש חיה אשר בים׃ ");
INSERT INTO heb_vpl VALUES ("RV16_4","096_16_4","REV","16","4","4","וישפך השלישי את קערתו בנהרות ובמעינות המים ויהיו לדם׃ ");
INSERT INTO heb_vpl VALUES ("RV16_5","096_16_5","REV","16","5","5","ואשמע את מלאך המים אמר צדיק אתה ההוה והיה והקדוש כי כן שפטת׃ ");
INSERT INTO heb_vpl VALUES ("RV16_6","096_16_6","REV","16","6","6","כי דם קדשים ונביאים שפכו ודם השקיתם כי גמול ידם הוא׃ ");
INSERT INTO heb_vpl VALUES ("RV16_7","096_16_7","REV","16","7","7","ואשמע את המזבח אמר אמנם כן יהוה אלהים צבאות אמת וצדק משפטיך׃ ");
INSERT INTO heb_vpl VALUES ("RV16_8","096_16_8","REV","16","8","8","וישפך המלאך הרביעי את קערתו על השמש וינתן לו לצרב את בני אדם באש׃ ");
INSERT INTO heb_vpl VALUES ("RV16_9","096_16_9","REV","16","9","9","ויצרבו בני אדם בחם גדול ויגדפו את שם אלהים אשר לו הממשלה על המכות האלה ולא שבו לתת לו הכבוד׃ ");
INSERT INTO heb_vpl VALUES ("RV16_10","096_16_10","REV","16","10","10","וישפך החמישי את קערתו על כסא החיה ותחשך מלכותה וינשכו מכאב לב את לשונם׃ ");
INSERT INTO heb_vpl VALUES ("RV16_11","096_16_11","REV","16","11","11","ויגדפו את אלהי השמים ממכאבם ושחינם ולא שבו ממעשיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV16_12","096_16_12","REV","16","12","12","וישפך הששי את קערתו על הנהר הגדול נהר פרת ויחרבו מימיו למען תישר מסלה למלכים אשר ממזרח שמש׃ ");
INSERT INTO heb_vpl VALUES ("RV16_13","096_16_13","REV","16","13","13","וארא והנה מפי התנין ומפי החיה ומפי נביא השקר יצאות שלש רוחות טמאות דומת לצפרדעים׃ ");
INSERT INTO heb_vpl VALUES ("RV16_14","096_16_14","REV","16","14","14","כי רוחות השדים הנה עשות אותות ויצאות אל מלכי ארץ ותבל כלה לאספם למלחמה היום ההוא הגדול יום אלהי הצבאות׃ ");
INSERT INTO heb_vpl VALUES ("RV16_15","096_16_15","REV","16","15","15","הנני בא כגנב אשרי השקד ושמר את בגדיו למען לא ילך ערם וראו את ערותו׃ ");
INSERT INTO heb_vpl VALUES ("RV16_16","096_16_16","REV","16","16","16","ויאסף אתם אל המקום הנקרא בעברית הר מגדון׃ ");
INSERT INTO heb_vpl VALUES ("RV16_17","096_16_17","REV","16","17","17","וישפך המלאך השביעי את קערתו על האור ויצא קול גדול מהיכל השמים מן הכסא ויאמר היה נהיתה׃ ");
INSERT INTO heb_vpl VALUES ("RV16_18","096_16_18","REV","16","18","18","ויהיו קלות ורעמים וברקים ויהי רעש גדול אשר לא היה כמהו למן היות אדם על הארץ רעש כזה גדול עד מאד׃ ");
INSERT INTO heb_vpl VALUES ("RV16_19","096_16_19","REV","16","19","19","והעיר הגדולה נחלקה לשלשה חלקים ותפלנה ערי הגוים ותזכר בבל הגדולה לפני אלהים לתת לה כוס יין חמת אפו׃ ");
INSERT INTO heb_vpl VALUES ("RV16_20","096_16_20","REV","16","20","20","וינס כל אי וההרים לא נמצאו׃ ");
INSERT INTO heb_vpl VALUES ("RV16_21","096_16_21","REV","16","21","21","וברד כבד כככר ירד מן השמים על בני האדם ויגדפו בני האדם את האלהים על אדות מכת הברד כי כבדה מכתו מאד׃ ");
INSERT INTO heb_vpl VALUES ("RV17_1","096_17_1","REV","17","1","1","ויבא אחד מן שבעה המלאכים הנשאים שבע הקערות וידבר אלי לאמר בא ואראך את משפט הזונה הגדולה הישבת על מים רבים׃ ");
INSERT INTO heb_vpl VALUES ("RV17_2","096_17_2","REV","17","2","2","אשר זנו אתה מלכי האדמה וישכרו שכני תבל מיין תזנותה׃ ");
INSERT INTO heb_vpl VALUES ("RV17_3","096_17_3","REV","17","3","3","ויוליכני ברוח המדברה וארא והנה אשה ישבת על חיה אדמה כתולע מלאת שמות גדופים ולה שבעה ראשים ועשר קרנים׃ ");
INSERT INTO heb_vpl VALUES ("RV17_4","096_17_4","REV","17","4","4","והאשה לבושה ארגמן ושני והיא מכללה בזהב ואבן יקרה ופנינים ובידה כוס זהב מלאה תועבות וטמאת תזנותה׃ ");
INSERT INTO heb_vpl VALUES ("RV17_5","096_17_5","REV","17","5","5","ועל מצחה כתוב שם סוד בבל הגדולה אם הזנות ותועבות האדמה׃ ");
INSERT INTO heb_vpl VALUES ("RV17_6","096_17_6","REV","17","6","6","וארא את האשה שכורה מדם הקדשים ומדם עדי ישוע ואשתומם על המראה שמה גדולה׃ ");
INSERT INTO heb_vpl VALUES ("RV17_7","096_17_7","REV","17","7","7","ויאמר אלי המלאך למה זה השתוממת אני אמר לך את סוד האשה והחיה הנשאת אתה בעלת שבעת הראשים ועשרת הקרנים׃ ");
INSERT INTO heb_vpl VALUES ("RV17_8","096_17_8","REV","17","8","8","החיה אשר ראיתה היתה ואיננה ועתידה לעלות מן התהום וללכת לאבדון וישבי הארץ אשר שמם איננו נכתב בספר החיים מיום הוסד תבל ישתוממו בראתם את החיה אשר היתה ואיננה ותבוא׃ ");
INSERT INTO heb_vpl VALUES ("RV17_9","096_17_9","REV","17","9","9","בזה להבין לאשר לו חכמה שבעת הראשים שבעת הרים המה אשר האשה ישבת עליהם׃ ");
INSERT INTO heb_vpl VALUES ("RV17_10","096_17_10","REV","17","10","10","ושבעה מלכים המה חמשה מהם נפלו והאחד ישנו והאחר עוד לא בא והיה כי יבוא עמד יעמד לעת מעט׃ ");
INSERT INTO heb_vpl VALUES ("RV17_11","096_17_11","REV","17","11","11","והחיה אשר היתה ואיננה הוא השמיני והוא מן השבעה וילך לאבדון׃ ");
INSERT INTO heb_vpl VALUES ("RV17_12","096_17_12","REV","17","12","12","ועשר הקרנים אשר ראית עשרה מלכים הם אשר לא קבלו מלכות עד הנה רק לשעה אחת ממשלה כמלכים יקבלו עם החיה׃ ");
INSERT INTO heb_vpl VALUES ("RV17_13","096_17_13","REV","17","13","13","ולאלה עצה אחת ואת כחם ואת ממשלתם יתנו לחיה׃ ");
INSERT INTO heb_vpl VALUES ("RV17_14","096_17_14","REV","17","14","14","המה ילחמו בשה והשה יכול יוכל להם כי הוא אדני האדנים ומלך המלכים ועמו הקרואים והבחירים והנאמנים׃ ");
INSERT INTO heb_vpl VALUES ("RV17_15","096_17_15","REV","17","15","15","ויאמר אלי המים ההם אשר ראית אשר הזונה ישבת עליהם עמים והמנים המה וגוים ולשנות׃ ");
INSERT INTO heb_vpl VALUES ("RV17_16","096_17_16","REV","17","16","16","ועשר הקרנים אשר ראית והחיה המה ישנאו את הזונה ועשוה גלמודה וערמה ואכלו את בשרה ואתה ישרפו באש׃ ");
INSERT INTO heb_vpl VALUES ("RV17_17","096_17_17","REV","17","17","17","כי האלהים נתן בלבם לעשות את עצתו ולעשות עצה אחת ולתת את ממשלתם לחיה עד כי ישלמו דברי האלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV17_18","096_17_18","REV","17","18","18","והאשה אשר ראית היא העיר הגדולה אשר היא נברת ממלכות הארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV18_1","096_18_1","REV","18","1","1","אחרי כן ראיתי מלאך אחר יורד מן השמים אשר לו שלטן גדול והארץ האירה מכבדו׃ ");
INSERT INTO heb_vpl VALUES ("RV18_2","096_18_2","REV","18","2","2","ויקרא בקול עז לאמר נפלה נפלה בבל הגדולה ותהי נוה שערים ומשמר לכל רוח טמא ומשמר לכל עוף טמא ונמאס׃ ");
INSERT INTO heb_vpl VALUES ("RV18_3","096_18_3","REV","18","3","3","כי מיין חמת זנותה שתו כל הגוים ומלכי ארץ זנו עמה וסחרי ארץ משפעת תענגיה העשירו׃ ");
INSERT INTO heb_vpl VALUES ("RV18_4","096_18_4","REV","18","4","4","ואשמע קול אחר מן השמים האמר צאו ממנה עמי פן תתחברו אל חטאתיה ופן תקחו ממכותיה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_5","096_18_5","REV","18","5","5","כי חטאתיה הגיעו עד לשמים ויזכר אלהים את עונותיה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_6","096_18_6","REV","18","6","6","שלמו לה גמולה שגמלה לכם ועשו לה כפלים כפעלה בכוס אשר מסכה מסכו לה כפלים׃ ");
INSERT INTO heb_vpl VALUES ("RV18_7","096_18_7","REV","18","7","7","כאשר התרוממה והתענגה כן תנו לה חבל ואבל כי אמרה התרוממה והתענגה כן תנו לה חבל ואבל כי אמרה בלבבה אני ישבתי מלכה ולא אהיה אלמנה ואבל לא אראה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_8","096_18_8","REV","18","8","8","על כן רגע ביום אחד תבאנה מכותיה מות ואבל ורעב ותשרף במו אש כי חזק יהוה אלהים השפט אתה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_9","096_18_9","REV","18","9","9","ויבכו ויספדו עליה מלכי ארץ אשר זנו והתענגו עמה בראתם את עשן שרפתה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_10","096_18_10","REV","18","10","10","ומרחוק יעמדו מפני אימת ענויה ואמרו אוי אוי לך בבל העיר הגדולה העיר החזקה כי בשעה אחת בא משפטך׃ ");
INSERT INTO heb_vpl VALUES ("RV18_11","096_18_11","REV","18","11","11","וסחרי הארץ בכים ומתאבלים עליה כי עתה לא יקנה עוד איש את משא אניותם׃ ");
INSERT INTO heb_vpl VALUES ("RV18_12","096_18_12","REV","18","12","12","את משא זהב וכסף ואבן יקרה ופנינים ובוץ וארגמן ומשי ושני וכל עצי בשם וכל כלי שנהבים וכל כלי עץ יקר וכלי נחשת וברזל ושיש׃ ");
INSERT INTO heb_vpl VALUES ("RV18_13","096_18_13","REV","18","13","13","וקנמון וקטרת סמים ומר ולבונה ויין ושמן וסלת וחטים ומקנה וצאן וסוסים ומרכבות וגויות ונפש אדם׃ ");
INSERT INTO heb_vpl VALUES ("RV18_14","096_18_14","REV","18","14","14","והמגדים מחמד נפשך אזלו ממך וכל שמן ומצהיר אבד ממך ולא תמצאם עוד׃ ");
INSERT INTO heb_vpl VALUES ("RV18_15","096_18_15","REV","18","15","15","ורכליהם אשר העשירו ממנה יעמדו מרחוק מפני אימת ענויה ובכו והתאבלו׃ ");
INSERT INTO heb_vpl VALUES ("RV18_16","096_18_16","REV","18","16","16","ואמרו אוי אוי העיר הגדולה המכסה בשש וארגמן ושני ומכללה בזהב ואבן יקרה ופנינים כי בשעה אחת החרב עשר גדול כזה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_17","096_18_17","REV","18","17","17","וכל חבל וכל בעל מעברת והמלחים וכל עשי מלאכה בים עמדו מרחוק׃ ");
INSERT INTO heb_vpl VALUES ("RV18_18","096_18_18","REV","18","18","18","ויצעקו בראתם עשן שרפתה לאמר מי בערים כעיר הגדולה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_19","096_18_19","REV","18","19","19","ויזרקו עפר על ראשיהם ויצעקו בכה וספוד לאמר אוי אוי העיר הגדולה אשר בה העשירו מהונה כל אשר להם אניות בים כי בשעה אחת החרבה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_20","096_18_20","REV","18","20","20","רנו עליה השמים והשליחים הקדשים והנביאים כי שפט אלהים את משפטכם ממנה׃ ");
INSERT INTO heb_vpl VALUES ("RV18_21","096_18_21","REV","18","21","21","וישא מלאך נורא אבן גדולה כפלח רכב וישליכה אל תוך הים לאמר ככה תשלך במערצה בבל העיר הגדולה ולא תמצא עוד׃ ");
INSERT INTO heb_vpl VALUES ("RV18_22","096_18_22","REV","18","22","22","וקול המנגנים בכנור והמזמרים ומחללים בחלילים ומחצרים בחצצרות בל ישמע עוד בתוכך וכל חרש וחשב בל ימצא בך עוד וקול רחים בל ישמע עוד בקרבך׃ ");
INSERT INTO heb_vpl VALUES ("RV18_23","096_18_23","REV","18","23","23","ואור נר לא יאיר לך עוד וקול חתן וקול כלה לא ישמע בך עוד כי כנעניך היו נכבדי ארץ ובכשפיך תעו כל הגוים׃ ");
INSERT INTO heb_vpl VALUES ("RV18_24","096_18_24","REV","18","24","24","ובה נמצא דם הנביאים והקדשים וכל הרוגי ארץ׃ ");
INSERT INTO heb_vpl VALUES ("RV19_1","096_19_1","REV","19","1","1","אחרי כן שמעתי קול גדול כקול המון רב בשמים האמרים הללויה הישועה והכבוד והעז ליהוה אלהינו׃ ");
INSERT INTO heb_vpl VALUES ("RV19_2","096_19_2","REV","19","2","2","כי אמת וישר משפטיו כי שפט את הזונה הגדולה אשר השחיתה את הארץ בתזנתה וידרש מידה טאת דם עבדיו׃ ");
INSERT INTO heb_vpl VALUES ("RV19_3","096_19_3","REV","19","3","3","וישנו ויאמרו הללויה ועשנה יעלה לעולמי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("RV19_4","096_19_4","REV","19","4","4","ועשרים וארבעה הזקנים וארבע החיות נפלו על פניהם וישתחוו לאלהים הישב על הכסא ויאמרו אמן הללויה׃ ");
INSERT INTO heb_vpl VALUES ("RV19_5","096_19_5","REV","19","5","5","וקול יוצא מן הכסא ויאמר הללו את אלהינו כל עבדיו ויראיו הקטנים עם הגדולים׃ ");
INSERT INTO heb_vpl VALUES ("RV19_6","096_19_6","REV","19","6","6","ואשמע כקול המון רב וכקול מים רבים וכקול רעמים חזקים ויאמרו הללויה כי מלך אלהינו יהוה צבאות׃ ");
INSERT INTO heb_vpl VALUES ("RV19_7","096_19_7","REV","19","7","7","נשמחה ונגילה ונתנה לו הכבוד כי באה חתנת השה ואשתו התקדשה׃ ");
INSERT INTO heb_vpl VALUES ("RV19_8","096_19_8","REV","19","8","8","וינתן לה ללבש בוץ טהור וצח כי הבוץ הוא צדקות הקדשים׃ ");
INSERT INTO heb_vpl VALUES ("RV19_9","096_19_9","REV","19","9","9","ויאמר אלי כתב אשרי הקרואים אל משתה חתנת השה ויאמר אלי אלה הדברים אמת הם דברי אלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV19_10","096_19_10","REV","19","10","10","ואפל לפני רגליו להשתחות לו ויאמר אלי ראה אל תעשה זאת עבד כמוך אנכי וחבר לך ולאחיך אשר להם עדות ישוע השתחוה לאלהים כי עדות ישוע היא רוח הנבואה׃ ");
INSERT INTO heb_vpl VALUES ("RV19_11","096_19_11","REV","19","11","11","וארא את השמים נפתחים והנה סוס לבן והרכב עליו נקרא נאמן ואמתי ובצדק הוא שפט ולחם׃ ");
INSERT INTO heb_vpl VALUES ("RV19_12","096_19_12","REV","19","12","12","ועיניו כלבת אש ועטרות הרבה על ראשו ויש לו שם כתוב אשר לא ידע איש כי אם הוא לבדו׃ ");
INSERT INTO heb_vpl VALUES ("RV19_13","096_19_13","REV","19","13","13","והוא לבוש בלבוש מאדם בדם ושמו נקרא דבר האלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV19_14","096_19_14","REV","19","14","14","וצבאות השמים יצאים אחריו על סוסים לבנים מלבשים בגדי בוץ לבן וטהור׃ ");
INSERT INTO heb_vpl VALUES ("RV19_15","096_19_15","REV","19","15","15","ומפיו יצאת חרב חדה להכות בה את הגוים והוא ירעם בשבט ברזל והוא דרך פורת יין חמת אף אלהי הצבאות׃ ");
INSERT INTO heb_vpl VALUES ("RV19_16","096_19_16","REV","19","16","16","ועל בגדו ועל ירכו כתוב שם מלך המלכים ואדני האדנים׃ ");
INSERT INTO heb_vpl VALUES ("RV19_17","096_19_17","REV","19","17","17","וארא מלאך אחד עמד בשמש ויצעק בקול גדול ויאמר אל צפור כל כנף אשר תעוף במרום הרקיע באו והאספו על זבח האלהים הגדול׃ ");
INSERT INTO heb_vpl VALUES ("RV19_18","096_19_18","REV","19","18","18","ואכלתם בשר מלכים ובשר שרי אלפים ובשר גבורים ובשר סוסים ורכביהם ובשר כל בני חורים ועבדים הקטנים עם הגדולים׃ ");
INSERT INTO heb_vpl VALUES ("RV19_19","096_19_19","REV","19","19","19","וארא את החיה ומלכי הארץ ואגפיהם נקהלים לעשות מלחמה עם הרכב על הסוס ובצבאו׃ ");
INSERT INTO heb_vpl VALUES ("RV19_20","096_19_20","REV","19","20","20","ותתפש החיה ונביא השקר אתה אשר עשה האותות לפניה אשר הדיח בהן את נשאי תו החיה והמשתחוים לצלמה וחיים השלכו שניהם באגם האש הבער בגפרית׃ ");
INSERT INTO heb_vpl VALUES ("RV19_21","096_19_21","REV","19","21","21","והנשארית נהרגו בחרב היוצאת מפי הרכב על הסוס וכל העוף שבעו מבשרם׃ ");
INSERT INTO heb_vpl VALUES ("RV20_1","096_20_1","REV","20","1","1","וארא מלאך יורד מן השמים ובידו מפתח התהום וכבל גדול׃ ");
INSERT INTO heb_vpl VALUES ("RV20_2","096_20_2","REV","20","2","2","ויתפש את התנין את הנחש הקדמוני הוא המלשין והוא השטן ויאסרהו לאלף שנים׃ ");
INSERT INTO heb_vpl VALUES ("RV20_3","096_20_3","REV","20","3","3","וישליכהו בתהום ויסגר בעדו ויחתם עליו למען לא ידיח עוד את הגוים עד כלות אלף השנים ואחרי כן יתר לזמן מצער׃ ");
INSERT INTO heb_vpl VALUES ("RV20_4","096_20_4","REV","20","4","4","וארא כסאות וישבו עליהם והמשפט נתן בידם ונפשות ההרוגים על עדות ישוע ועל דבר האלהים ואשר לא השתחוו לחיה ולצלמה ולא קבלו את תוה על מצחותם ועל ידם ויקומו ויחיו וימלכו עם המשיח אלף שנים׃ ");
INSERT INTO heb_vpl VALUES ("RV20_5","096_20_5","REV","20","5","5","ושאר המתים לא קמו לחיים עד כלות אלף השנים זאת היא התחיה הראשונה׃ ");
INSERT INTO heb_vpl VALUES ("RV20_6","096_20_6","REV","20","6","6","אשרי האיש וקדוש הוא אשר חלקו לקום בתחיה הראשונה באלה לא ישלט המות השני כי אם יהיו כהנים לאלהים ולמשיחו וימלכו אתו אלף שנים׃ ");
INSERT INTO heb_vpl VALUES ("RV20_7","096_20_7","REV","20","7","7","ואחרי כלות אלף השנים יתר השטן מבית משמרו׃ ");
INSERT INTO heb_vpl VALUES ("RV20_8","096_20_8","REV","20","8","8","ויצא להדיח את הגוים בארבע כנפות הארץ את גוג ומגוג ולקבצם למלחמה אשר מספרם כחול הים׃ ");
INSERT INTO heb_vpl VALUES ("RV20_9","096_20_9","REV","20","9","9","ויעלו על מרחבי ארץ ויסבו את מחנה הקדשים ואת העיר החביבה ותרד אש מאת האלהים מן השמים ותאכל אתם׃ ");
INSERT INTO heb_vpl VALUES ("RV20_10","096_20_10","REV","20","10","10","והשטן אשר הדיחם השלך באגם אש וגפרית אשר שם גם החיה ונביא השקר ויסרו יומם ולילה לעולמי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("RV20_11","096_20_11","REV","20","11","11","וארא כסא לבן וגדול ואת הישב עליו אשר מפניו נסו ארץ ושמים ולא נמצא להם מקום׃ ");
INSERT INTO heb_vpl VALUES ("RV20_12","096_20_12","REV","20","12","12","וארא את המתים הקטנים עם הגדלים עמדים לפני הכסא וספרים נפתחים ויפתח ספר אחר אשר הוא ספר החיים וישפטו המתים על פי הכתוב בספרים כמעשיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV20_13","096_20_13","REV","20","13","13","ויתן הים את מתיו והמות והשאול נתנו את מתיהם וישפטו איש איש כמעשיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV20_14","096_20_14","REV","20","14","14","והמות והשאול השלכו באגם האש והוא המות השני׃ ");
INSERT INTO heb_vpl VALUES ("RV20_15","096_20_15","REV","20","15","15","וכל איש אשר לא נמצא כתוב בספר החיים השלך באגם האש׃ ");
INSERT INTO heb_vpl VALUES ("RV21_1","096_21_1","REV","21","1","1","וארא שמים חדשים וארץ חדשה כי השמים הראשנים והארץ הראשונה עברו והים איננו עוד׃ ");
INSERT INTO heb_vpl VALUES ("RV21_2","096_21_2","REV","21","2","2","וארא את העיר הקדושה ירושלים החדשה ירדת מאת האלהים מן השמים נכונה ככלה המקשטת לבעלה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_3","096_21_3","REV","21","3","3","ואשמע קול גדול מן השמים לאמר הנה משכן אלהים עם בני האדם ושכן בתוכם והמה יהיו לו לעם והוא האלהים יהיה אתם אלהיהם׃ ");
INSERT INTO heb_vpl VALUES ("RV21_4","096_21_4","REV","21","4","4","ומחה אלהים כל דמעה מעיניהם והמות לא יהיה עוד וגם אבל וזעקה וכאב לא יהיה עוד כי הראשנות עברו׃ ");
INSERT INTO heb_vpl VALUES ("RV21_5","096_21_5","REV","21","5","5","ויאמר הישב על הכסא הנני עשה הכל חדש ויאמר אלי כתב כי הדברים האלה אמתים ונאמנים הם׃ ");
INSERT INTO heb_vpl VALUES ("RV21_6","096_21_6","REV","21","6","6","ויאמר אלי היה נהיתה אני האלף והתו הראש והסוף אני אתן לצמא ממעין מים חיים חנם׃ ");
INSERT INTO heb_vpl VALUES ("RV21_7","096_21_7","REV","21","7","7","המנצח יירש הכל ואני אהיה לו לאלהים והוא יהיה לי לבן׃ ");
INSERT INTO heb_vpl VALUES ("RV21_8","096_21_8","REV","21","8","8","אבל רכי הלב ואשר אינם מאמינים והמגאלים והמרצחים והזנים והמכשפים ועבדי האלילים וכל המכזבים חלקם יהיה באגם הבער באש וגפרית אשר הוא המות השני׃ ");
INSERT INTO heb_vpl VALUES ("RV21_9","096_21_9","REV","21","9","9","ויבא אלי אחד משבעת המלאכים הנשאים שבע הקערות המלאות שבע המכות האחרנות וידבר אלי לאמר בא ואראך את הכלה אשת השה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_10","096_21_10","REV","21","10","10","ויוליכני ברוח על הר גדול וגבה ויראני העיר הגדולה ירושלים הקדושה ירדת מן השמים מאת האלהים׃ ");
INSERT INTO heb_vpl VALUES ("RV21_11","096_21_11","REV","21","11","11","ויש לה כבוד אלהים ואור נגהה כאבן יקרה מאד כאבן ישפה המבהקת כעין הקרח׃ ");
INSERT INTO heb_vpl VALUES ("RV21_12","096_21_12","REV","21","12","12","ויש לה חומה גדולה וגבהה ושנים עשר שערים לה ועל השערים שנים עשר מלאכים ושמות כתובים עליהם אשר הם שמות שנים עשר שבטי בני ישראל׃ ");
INSERT INTO heb_vpl VALUES ("RV21_13","096_21_13","REV","21","13","13","שערים שלשה ממזרח שערים שלשה מצפון שערים שלשה מנגב ושערים שלשה ממערב׃ ");
INSERT INTO heb_vpl VALUES ("RV21_14","096_21_14","REV","21","14","14","ולחומת העיר שנים עשר מוסדות ועליהם שנים עשר שמות לשנים עשר שליחי השה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_15","096_21_15","REV","21","15","15","וביד המדבר אלי היה קנה זהב למד בו את העיר ואת שעריה ואת חומתה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_16","096_21_16","REV","21","16","16","ומושב העיר מרבע וארכה כרחבה וימד את העיר בקנה המדה שנים עשר אלף ריס ארכה ורחבה וקומתה שוים המה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_17","096_21_17","REV","21","17","17","וימד את חומתה על מאה וארבעים וארבע אמות במדת איש אשר היא מדת המלאך׃ ");
INSERT INTO heb_vpl VALUES ("RV21_18","096_21_18","REV","21","18","18","ובנין חומתה אבן ישפה והעיר זהב מופז דומה לזכוכית זכה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_19","096_21_19","REV","21","19","19","ומוסדות חומת העיר מרבצות בכל אבני חפץ המוסד הראשון ישפה השני ספיר השלישי שבו הרביעי ברקת׃ ");
INSERT INTO heb_vpl VALUES ("RV21_20","096_21_20","REV","21","20","20","החמישי יהלם הששי אדם השביעי תרשיש השמיני שהם התשיעי פטדה העשירי נפך אחד העשר לשם שנים העשר אחלמה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_21","096_21_21","REV","21","21","21","ושנים עשר השערים הם שתים עשרה מרגליות כל שער ושער מרגלית אחת ורחוב העיר זהב מופז כזכוכית בהירה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_22","096_21_22","REV","21","22","22","והיכל לא ראיתי בה כי יהוה אלהים צבאות היכלה הוא והשה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_23","096_21_23","REV","21","23","23","והעיר איננה צריכה לאור השמש ולנגה הירח כי כבוד אלהים האיר לה ונרה הוא השה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_24","096_21_24","REV","21","24","24","והגוים ילכו לאורה ומלכי ארץ מביאים כבודם ותפארתם אליה׃ ");
INSERT INTO heb_vpl VALUES ("RV21_25","096_21_25","REV","21","25","25","ושעריה יומם לא יסגרו כי לילה לא יהיה שם׃ ");
INSERT INTO heb_vpl VALUES ("RV21_26","096_21_26","REV","21","26","26","והביאו בה כבוד הגוים ותפארתם׃ ");
INSERT INTO heb_vpl VALUES ("RV21_27","096_21_27","REV","21","27","27","ולא יבוא בה כל טמא ועשה תועבה ושקר כי אם הכתובים בספר החיים של השה׃ ");
INSERT INTO heb_vpl VALUES ("RV22_1","096_22_1","REV","22","1","1","ויראני נחל של מים חיים זך מבהיק כעין הקרח יצא מכסא האלהים והשה׃ ");
INSERT INTO heb_vpl VALUES ("RV22_2","096_22_2","REV","22","2","2","ובתוך רחוב העיר ואל שפת הנחל מזה ומזה עץ חיים עשה פרי שנים עשר כי מדי חדש בחדשו יתן את פריו ועלה העץ לתרופת הגוים׃ ");
INSERT INTO heb_vpl VALUES ("RV22_3","096_22_3","REV","22","3","3","וכל חרם לא יהיה עוד וכסא האלהים והשה יהיה בה ועבדיו ישרתהו׃ ");
INSERT INTO heb_vpl VALUES ("RV22_4","096_22_4","REV","22","4","4","והמה יראו את פניו ושמו על מצחותם׃ ");
INSERT INTO heb_vpl VALUES ("RV22_5","096_22_5","REV","22","5","5","ולילה לא יהיה עוד ולא יצטרכו עוד לאור נר ולאור שמש כי יהוה אלהים הוא יאיר להם וימלכו עד עולמי עולמים׃ ");
INSERT INTO heb_vpl VALUES ("RV22_6","096_22_6","REV","22","6","6","ויאמר אלי הדברים האלה אמתים ונאמנים הם ויהוה אלהי הנביאים הקדשים שלח את מלאכו להראות את עבדיו את אשר היה יהיה במהרה׃ ");
INSERT INTO heb_vpl VALUES ("RV22_7","096_22_7","REV","22","7","7","הנני בא מהר אשרי השמר את דברי נבואת הספר הזה׃ ");
INSERT INTO heb_vpl VALUES ("RV22_8","096_22_8","REV","22","8","8","ואני יוחנן הוא הראה אלה ושמעם ויהי כשמעי וכראותי ואפל לפני רגלי המלאך אשר הראני את אלה להשתחות לו׃ ");
INSERT INTO heb_vpl VALUES ("RV22_9","096_22_9","REV","22","9","9","ויאמר אלי ראה אל תעשה זאת כי עבד כמוך אנכי וחבר לך ולאחיך הנביאים ולשמרים את דברי הספר הזה לאלהים השתחוה׃ ");
INSERT INTO heb_vpl VALUES ("RV22_10","096_22_10","REV","22","10","10","ויאמר אלי אל תחתם את דברי נבואת הספר הזה כי קרוב המועד׃ ");
INSERT INTO heb_vpl VALUES ("RV22_11","096_22_11","REV","22","11","11","החומס יוסיף לחמס והטמא יוסיף להטמא והצדיק יוסיף להצדק והקדוש יוסיף להתקדש׃ ");
INSERT INTO heb_vpl VALUES ("RV22_12","096_22_12","REV","22","12","12","והנני בא מהר ושכרי אתי לשלם לכל איש כמעשהו׃ ");
INSERT INTO heb_vpl VALUES ("RV22_13","096_22_13","REV","22","13","13","אני האלף והתו הראש והסוף הראשון והאחרון׃ ");
INSERT INTO heb_vpl VALUES ("RV22_14","096_22_14","REV","22","14","14","אשרי העשים את מצותיו למען תהיה ממשלתם בעץ החיים ובאו העירה דרך השערים׃ ");
INSERT INTO heb_vpl VALUES ("RV22_15","096_22_15","REV","22","15","15","ומחוץ לה הכלבים והמכשפים והזנים והמרצחים ועבדי האלילים וכל אהב שקר ועשהו׃ ");
INSERT INTO heb_vpl VALUES ("RV22_16","096_22_16","REV","22","16","16","אני ישוע שלחתי את מלאכי להעיד לכם את אלה בפני הקהלות אנכי שרש דוד ותולדתו כוכב נגה השחר׃ ");
INSERT INTO heb_vpl VALUES ("RV22_17","096_22_17","REV","22","17","17","והרוח והכלה אמרים בא והשמע יאמר בא והצמא יבוא והחפץ יקח מים חיים חנם׃ ");
INSERT INTO heb_vpl VALUES ("RV22_18","096_22_18","REV","22","18","18","מעיד אני בכל השמע דברי נבואת הספר הזה אם יוסיף איש עליהם יוסיף עליו האלהים את המכות הכתובות בספר הזה׃ ");
INSERT INTO heb_vpl VALUES ("RV22_19","096_22_19","REV","22","19","19","ואם יגרע איש מדברי ספר הנבואה הזאת יגרע האלהים את לחקו מעץ החיים ומעיר הקדש הכתובים בספר הזה׃ ");
INSERT INTO heb_vpl VALUES ("RV22_20","096_22_20","REV","22","20","20","המעיד את אלה אמר אמנם כן אני בא מהר אמן באה נא האדון ישוע׃ ");
INSERT INTO heb_vpl VALUES ("RV22_21","096_22_21","REV","22","21","21","חסד אדנינו ישוע המשיח עם כלכם כל הקדושים אמן׃ ");
